INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'I begynnelsen skapade Gud Himmel och Jord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Och jorden var öde och tom, och mörker var på djupet, och Guds Ande sväfde öfver vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Och Gud sade: Varde Ljus, och det vardt Ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Och Gud såg ljuset, att det var godt. Då skilde Gud ljuset ifrå mörkret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Och kallade ljuset Dag, och mörkret Natt. Och vardt af afton och morgon den första dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Och Gud sade: Varde ett Fäste emellan vattnen, och åtskilje vatten ifrå vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Och Gud gjorde fästet, och åtskilde det vattnet, som var under fästet, ifrå det vatten, som var ofvan fästet. Och det skedde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Och Gud kallade fästet Himmel. Och vardt af afton och morgon den andra dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Och Gud sade: Församle sig vattnet, som är under himmelen, uti besynnerligit rum, att det torra må synas. Och det skedde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Och Gud kallade det torra Jord, och vattnens församlingar kallade han Haf. Och Gud såg, att det var godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Och Gud sade: Bäre jorden gräs och örter, som frö hafva, och fruktsam trä, att hvart och ett bär frukt efter sin art, och hafver sitt eget frö i sig sjelfvo på jordene. Och det skedde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Och jorden bar gräs och örter, som frö hade, hvart efter sin art, och trä, som frukt båro, och hade sitt eget frö i sig sjelfvo, hvart efter sin art. Och Gud såg, att det var godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Och vardt af afton och morgon den tredje dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Och Gud sade: Varde Ljus uti himmelens fäste, och åtskilje dag och natt, och gifve tecken, månader, dagar och år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Och vare för ljus uti himmelens fäste, och lyse på jordene. Och det skedde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Och Gud gjorde tu stor ljus; ett stort ljus, som regerade dagen, och ett litet ljus, som regerade nattena; och stjernor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Och Gud satte dem uti himmelens fäste, att de skina skulle på jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Och regera dagen och nattena, och åtskilja ljuset och mörkret. Och Gud såg, att det var godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Och vardt af afton och morgon den fjerde dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Och Gud sade: Göre vattnet af sig kräkande och lefvande djur, och foglar, som på jordene flyga under himmelens fäste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Och Gud skapade stora hvalar, och allahanda lefvande och kräkande djur, som vattnet af sig gör, hvart efter sin art, och allahanda fjäderfoglar, hvart efter sin art. Och Gud såg, att det var godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Och välsignade dem, och sade: Varer fruktsamme, och förökens, och uppfyller hafsens vatten, och foglarna föröke sig på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Och vardt af afton och morgon den femte dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Och Gud sade: Göre jorden af sig lefvande djur, hvart efter sin art, fänad, kräkande djur, och vilddjur på jordene, hvart efter sin art. Och det skedde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Och Gud gjorde vilddjur på jordene, hvart efter sin art, fänad efter sin art, allahanda kräkande djur på jordene efter sin art. Och Gud såg, att det var godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Och Gud sade: Låt oss göra Menniskona till ett beläte, det oss likt är, den råda skall öfver fiskarna i hafvet, och öfver foglarna under himmelen, och öfver fänaden, och öfver hela jordena, och öfver allt det som kräker på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Och Gud skapade menniskona sig till ett beläte, till Guds beläte skapade han honom, Man och Qvinno skapade han dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Och Gud välsignade dem, och sade till dem: Varer fruktsamme, och föröker eder, och uppfyller jordena, och hafver henne under eder, och råder öfver fiskarna i hafvet, och öfver foglarna under himmelen, och öfver all djur, som kräla på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Och Gud sade: Si, jag hafver gifvit eder allahanda örter, som frö hafva på hela jordene, och allahanda fruktsam trä, och trä, som frö hafva i sig sjelfvo, eder till mat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Och allom djurom på jordene, och allom foglom under himmelen, och allo thy, som kräker på jordene, och lif hafver, att de skola hafva allahanda gröna örter till att äta. Och det skedde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Och Gud såg på allt det han gjort hade, och si, det var allt ganska godt. Och vardt af afton och morgon den sjette dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Så vardt nu himmel och jord fullkomnad med all sin här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Och Gud fullkomnade på sjunde dagenom sin verk, som han gjort hade, och hvilade på sjunde dagenom af all sin verk, som han gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Och välsignade sjunde dagen, och helgade honom, derföre att han på honom hvilade af all sin verk, som Gud skapade och gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Alltså är himmel och jord tillkommen, då de skapade vordo på den tid, då Herren Gud gjorde himmel och jord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Förra än någor stjelk var på markene, och förra än någor ört växte på jordene; förty Herren Gud hade än då intet låtit regna på jordene, och ingen menniska var, som brukade jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Men en dimba gick upp af jordene, och vattnade alla markena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Och Herren Gud gjorde menniskona af jordenes stoft, och inblåste uti hans näso en lefvande anda, och så vardt menniskan en lefvande själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Och Herren Gud planterade en lustgård uti Eden öster ut, och satte der in menniskona, som han gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Och Herren Gud lät uppväxa af jordene allahanda trä, lustig till att se och god till att äta; och lifsens trä midt i lustgårdenom, och kunskapsens trä på godt och ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Och utaf Eden gick en ström till att vattna lustgården, och han delade sig i fyra hufvudfloder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Den förste kallas Pison, den löper om hela Havila land, och der finnes guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Och dess landes guld är kosteligit, och der finnes Bedellion, och den ädle stenen Onix.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Den andre floden heter Gihon, den löper kring om hela Ethiopien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Den tredje floden kallas Hiddekel, den löper fram för Assyrien. Den fjerde floden är Phrath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Och Herren Gud tog menniskona, och satte honom in uti lustgården Eden, att han honom bruka och bevara skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Och Herren Gud böd menniskona, och sade: Du skall äta af allahanda trä i lustgårdenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Men af kunskapsens trä på godt och ondt skall du icke äta; förty, på hvad dag du deraf äter, skall du döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Och Herren Gud sade: Det är icke godt, att menniskan är allena; jag vill göra honom ena hjelp, den sig till honom hålla må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Som nu Herren Gud gjort hade af jordene allahanda djur på markene, och allahanda foglar under himmelen, hade han dem fram för menniskona, att han skulle se, huru han skulle nämna dem; ty, såsom menniskan allahanda lefvande djur nämnde, så skulle de heta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Och menniskan gaf hvart och ett fänad, och foglomen under himmelen, och djuren på markene, sina namn. Men till menniskone vardt icke funnen någon hjelp, den sig till honom hålla måtte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Då lät Herren Gud falla en tung sömn på menniskona, och vid han sof, tog han ett af hans sidoref, och uppfyllde kött i samma staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Och Herren Gud byggde ena Qvinno utaf refvet, som han uttagit hade af menniskone, och hade henne fram för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Då sade menniskan: Detta är dock ben af minom benom, och kött af mino kötte, hon skall heta Manna, derföre att hon är tagen utaf mannenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Fördenskull skall en man öfvergifva fader och moder, och blifva vid sina hustru, och skola varda till ett kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Och de voro både nakne, menniskan och hans hustru, och de blygdes intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Och ormen var listigare än all djur på jordene, som Herren Gud gjort hade, och sade till qvinnona: Ja, skulle Gud hafva sagt, I skolen icke äta af allahanda trä i lustgårdenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Då sade qvinnan till ormen: Vi äte af de träs frukt, som är i lustgårdenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Men af frukten af det trät, som är midt i lustgårdenom, hafver Gud sagt: Äter icke deraf, och kommer icke heller dervid, att I icke dön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Då sade ormen till qvinnona: Ingalunda skolen I döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Förty Gud vet, att på hvad dag I äten deraf, skola edor ögon öppnas, och I varden såsom Gud, vetandes hvad godt och ondt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Och qvinnan såg till, att trät var godt att äta af, och ljufligit uppå se, och att det ett lustigt trä var, efter det gaf förstånd; och tog utaf fruktene, och åt, och gaf desslikes sinom man deraf, och han åt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Då öppnades bägges deras ögon, och de vordo varse, att de voro nakne; och de bundo tillhopa fikonalöf, och gjorde sig skörte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Och de hörde Herrans Guds röst gångandes i lustgårdenom, då dagen svalkades; och Adam undstack sig, med sine hustru, för Herrans Guds ansigte, ibland trän i lustgårdenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Och Herren Gud kallade Adam, och sade till honom: Hvar äst du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Och han sade: Jag hörde dina röst i lustgårdenom, och fruktade mig, ty jag är naken, derföre undstack jag mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Han sade: Ho hafver låtit dig förstå, att du äst naken? Hafver du icke ätit af det trä, om hvilket jag dig budit hafver, att du deraf icke äta skulle?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Då sade Adam: Qvinnan, som du till mig gifvit hafver, gaf mig af trät, så att jag åt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Då sade Herren Gud till qvinnona: Hvi hafver du det gjort? Qvinnan sade: Ormen besvek mig, så att jag åt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Och Herren Gud sade till ormen: Efter du detta gjort hafver, förbannad vare du öfver allt det som lif hafver, och öfver all djur på markene; du skall gå på din buk, och äta jord i alla dina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Och jag skall sätta fiendskap emellan dig och qvinnona, och emellan dina säd och hennes säd. Den samme skall söndertrampa ditt hufvud, och du skall stinga honom i hans häl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Och till qvinnona sade han: Jag skall få dig mycken vedermödo, då du aflat hafver. Du skall föda din barn med sveda, och din vilje skall dinom manne undergifven vara, och han skall vara din herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Och till Adam sade han: Efter du lydde dine hustrus röst, och åt af trät, om hvilket jag dig böd och sade: Du skall icke äta deraf; förbannad vare marken för dina skull, med bekymmer skall du nära dig på henne i alla dina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Törne och tistlar skall hon bära dig, och du skall äta örter på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Du skall äta ditt bröd i dins anletes svett, till dess du varder åter till jord igen, der du af tagen äst; ty du äst jord, och till jord skall du varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Och Adam kallade sine hustrus namn Heva, derföre att hon en moder är åt allom lefvandom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Och Herren Gud gjorde Adam och hans hustru kjortlar af skinn, och klädde uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Och Herren Gud sade: Si, Adam är vorden såsom en af oss, och vet hvad godt och ondt är. Men nu, på det han icke uträcka skall sina hand, och taga desslikes af lifsens trä, och äta, och lefva evinnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Då lät Herren Gud honom utu lustgårdenom Eden, på det han skulle bruka jordena, der han af tagen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Och dref Adam ut; och satte för lustgården Eden Cherubim, med ett bart huggande svärd, till att förvara vägen till lifsens trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Och Adam kände sina hustru Heva, och hon aflade och födde Cain, och sade: Jag hafver fått Herrans man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Och hon födde framdeles Habel hans broder. Och vardt Habel en fåraherde, men Cain vardt en åkerman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Och det begaf sig efter några dagar, att Cain offrade Herranom gåfvor af jordenes frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Och Habel offrade desslikes af förstlingene af sin får, och af deras talg: Och Herren såg täckeliga till Habel och hans offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Men till Cain och hans offer såg han icke täckeliga. Då vardt Cain svårliga vred, och hans hy förvandlades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Sade Herren till Cain: Hvi äst du vred? Eller hvi förvandlas din hy?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Är det icke så? Om du äst from, så äst du tacknämlig; men äst du icke from, så blifver icke synden säker eller fördold; men städ henne icke hennes vilja, utan råd öfver henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Då talade Cain med sin broder Habel. Och det begaf sig, då de voro på markene, gaf Cain sig upp emot sin broder Habel, och slog honom ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Då sade Herren till Cain: Hvar är din broder Habel? Han svarade: Jag vet det icke; skall jag taga vara på min broder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Och han sade till honom: Hvad hafver du gjort? Dins broders blods röst ropar till mig utaf jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Och nu, förbannad vare du på jordene, som sin mun öppnat hafver, och tagit dins broders blod utu dina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Då du brukar jordena, skall hon icke straxt gifva dig efter sin förmågo; ostadig och flyktig skall du blifva på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Och Cain sade till Herran: Min missgerning är större, än att hon må mig förlåten varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Si, du drifver mig i dag utaf landet, och jag måste gömma mig undan ditt ansigte, och måste ostadig och flyktig blifva på jordene. Så varder mig gående, att hvilken som helst mig finner, han slår mig ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Men Herren sade till honom: Nej, utan den som slår Cain ihjäl, det skall sjufalt hämnadt varda. Och Herren satte ett tecken på Cain, att hvilken som helst honom funne, skulle icke slå honom ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Och så gick Cain ifrå Herrans ansigte, och bodde i det landet Nod öster ut, på hinsidan Eden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Och Cain kände sina hustru, och hon aflade och födde Hanoch, och han byggde en stad, hvilken han nämnde efter sin sons namn Hanoch.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Men Hanoch födde Yrad: Yrad födde Mahujael: Mahujael födde Methusael: Methusael födde Lamech.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Men Lamech tog sig två hustrur: Den ena het Ada, den andra Zilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Och Ada födde Jabal; af honom kommo de som bodde under tjäll, och hade boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Och hans broder het Jubal, af honom kommo de, som brukade harpor och pipor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Födde ock desslikes Zilla, nemliga Tubalkain, som var en mästare i allahanda koppars och jerns verk; och Tubalkains syster var Naema.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Och Lamech sade till sina hustrur Ada och Zilla: I Lamechs hustrur, hörer mina röst, och märker hvad jag säger: Jag hafver dräpit en man mig till sår, och en yngling mig till blånad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Cain skall varda hämnad sjufalt, men Lamech sju och sjutiofalt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Adam kände åter sina hustru, och hon födde en son, och kallade honom Seth, sägandes: Gud hafver satt mig en annor säd för Habel, som Cain ihjäl slog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Vardt också Seth född en son, den han kallade Enos. Och på den samma tiden begynte man predika om Herrans namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Detta är boken af menniskones slägt, på den tiden, då Gud skapte menniskona, och gjorde henne efter Guds liknelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Till man och qvinno skapade han dem, och välsignade dem, och kallade deras namn menniska, på den tiden de vordo skapade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Och Adam var hundrade och tretio år gammal, och han födde en son, som hans beläte lik var, och kallade honom Seth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Och vordo hans dagar, sedan han hade födt Seth, åttahundrade år, och han födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Och vardt tiden på allan hans ålder niohundrade och tretio år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Seth var hundrade och fem år gammal, och födde Enos;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Och lefde derefter åttahundrade och sju år, och födde söner och döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Och vardt tiden på allan hans ålder niohundrade och tolf år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enos var niotio år gammal, och födde Kenan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Och lefde derefter åttahundrade och femton år, och födde söner och döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Så att hans hela ålder vardt niohundrade och fem år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kenan var sjutio år gammal, och födde Mahalaleel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Och lefde derefter åttahundrade och fyratio år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Så att hans hela ålder vardt niohundrade och tio år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalaleel var sextio och fem år gammal, och födde Jared.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Och lefde sedan åttahundrade och tretio år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Så att hans hela ålder vardt åttahundrade fem och niotio år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jared var hundrade tu och sextio år gammal, och födde Henoch;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Och lefde derefter åttahundrade år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Så att hans hela ålder vardt niohundrade sextio och tu år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Henoch var sextio fem år gammal, och födde Methusalah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Och förde ett gudeligit lefverne i trehundrade år derefter, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Så att hans hela ålder vardt trehundrade sextio och fem år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Och efter han förde ett gudeligit lefverne, tog Gud honom bort, och han vardt sedan intet sedder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Methusalah var hundrade åttatio och sju år gammal, och födde Lamech;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Och lefde derefter i sjuhundrade åttatio och tu år, och födde söner och döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Så att hans hela ålder vardt niohundrade sextio och nio år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lamech var hundrade åttatio och tu år gammal, och födde en son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Och kallade honom Noah, och sade: Denne här varder oss tröstandes i våra mödo och arbete på jordene, den Herren förbannat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Derefter lefde han femhundrade niotio och fem år, och födde söner och döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Så att hans hela ålder vardt sjuhundrade sjutio och sju år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Noah var femhundrade år gammal, och födde Sem, Ham och Japhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Då menniskorna begynte förökas på jordene, och födde sig döttrar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Då sågo Guds söner menniskornas döttrar, att de voro dägeliga, och togo till hustrur hvilka de helst ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Då sade Herren: Menniskorna vilja icke mer låta min Anda straffa sig, ty de äro kött. Jag vill ännu gifva dem hundrade och tjugu års dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'På den tiden voro ock tyranner på jordene, förty, sedan Guds söner ingingo till menniskors döttrar, och de födde barn, vordo deraf väldige och fast beryktade män i verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Men då Herren såg, att menniskones ondska var stor på jordene, och all hennes hjertas uppsåt och tanke var alltid benägen till det ondt var:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Då ångrade Herranom, att han hade gjort menniskona på jordene, och det bekymrade honom i hans hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Och Herren sade: Menniskona, som jag skapade, skall jag förgöra utaf jordene, ifrå mennisko allt intill fänaden, och intill matkar, och intill foglarna under himmelen; förty det ångrar mig, att jag dem gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Men Noah fann nåde för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Detta är Noahs slägt: Noah var en from man och fullkomlig, och förde ett gudeligit lefverne i sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Och födde tre söner, Sem, Ham, Japhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Men jorden var förderfvad för Guds åsyn, och full med orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Då såg Gud på jordena, och si, hon var förderfvad, ty allt kött hade förderfvat sin väg på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Då sade Gud till Noah: Allt kötts ändalykt är kommen för mig, ty jorden är full med orätt af dem, och si, jag vill förderfva dem med jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Gör dig en ark utaf furuträ, och gör kamrar derinne, och becka honom utan och innan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Och gör honom alltså: Trehundrade alnar skall vara längden, femtio alnar bredden, och tretio alnar höjden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Ett fenster skall du göra der ofvan uppå, en aln stort. Dörrena skall du sätta midt på sidone; och skall han hafva tre bottnar, en nederst, den andra midt uti, den tredje öfverst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Ty si, jag skall låta komma en vattuflod öfver jordena, till att förderfva allt kött, der en lefvande ande uti är, under himmelen, och allt det på jordene är skall förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Men med dig vill jag göra ett förbund, och du skall gå in i arken med dina söner, med dine hustru, och med dina söners hustrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Och du skall låta komma in i arken allahanda djur af allt kött, ju ett par, mankön och qvinkön, att de måga blifva lefvande när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Af foglarna efter deras slag, af fänadenom efter sitt slag, och af allahanda kräkande djur på jordene efter deras slag. Af allo desso skall ju ett par ingå till dig, på det att de skola blifva lefvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Och du skall till dig taga allahanda mat, som man tärer, och skall samka honom till dig, att han varder dig och dem till födo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Och Noah gjorde allt det Gud böd honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Och Herren sade till Noah: Gack in uti arken, du och ditt hela hus, ty dig hafver jag sett rättfärdigan för mig i denna tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Af allahanda ren fänad tag till dig, ju sju och sju, mankön och qvinkön; men af orenom fänad, ju ett par, mankön och qvinkön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Sammalunda af foglarna under himmelen, ju sju och sju, mankön och qvinkön, på det att säd må blifva lefvandes på hela jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Ty ännu efter sju dagar skall jag låta regna på jordene fyratio dagar och fyratio nätter, och förgöra utaf jordene allt det som varelse hafver, det jag gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Och Noah gjorde allt det Herren böd honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Och han var sexhundrade år gammal, då flodenes vatten flödade på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Och han gick in i arken med sina söner, sine hustru, och sina söners hustrur, för flodenes vattens skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Af den rena fänaden, och af den orena, af foglar, och af allt det som kräker på jordene,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Gingo till honom in i arken, parom, ju mankön och qvinkön, såsom Gud honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Och då de sju dagar framlidne voro, kom flodsens vatten uppå jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Uti de sjettehundrade årena i Noahs ålder, på sjuttonde dagenom, i den andra månadenom, det är den dagen, då uppbrusto alla stora djupsens källor, och himmelens fenster öppnade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Och ett regn kom på jordene i fyratio dagar och fyratio nätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Rätt på samma dagen gick Noah in i arken, med Sem, Ham och Japhet, sina söner, och med sine hustru, och med tre sina söners hustrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Dertill allahanda djur efter sitt slag, allahanda fänad efter sitt slag, och allt det på jordene kräker efter sitt slag, och allahanda foglar efter sitt slag, allt det flyga kunde, och allt det vingar hade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Det gick allt till Noah in uti arken, parom af allt kött, der en lefvande ande uti var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Och det var mankön och qvinkön, utaf allahanda kött, och gingo derin, såsom Gud honom budit hade, och Herren lät igen efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Då kom floden fyratio dagar på jordene, och vattnet växte, och lyfte arken upp, och förde honom högt upp öfver jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Så fick då vattnet öfvermagt, och växte svårliga på jordene, så att arken dref på vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Och vattnet fick öfverhand, och växte så svåra på jordene, att all hög berg under hela himmelen vordo öfvertäckte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Femton alnar högt gick vattnet öfver bergen, som öfvertäckte vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Då förgicks allt kött, som på jordene kräker, foglar, fänad, vilddjur, och allt det som sig rörer på jordene, och alla menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Allt det som en lefvande anda hade på thy torra, det blef dödt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Så vardt då förgjordt allt det på jordene var, ifrå menniskone allt intill fänaden, intill kräkande djur, och intill foglarna under himmelen, allt vardt förgjordt utaf jordene. Allena Noah blef behållen, och hvad med honom var i arkenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Och vattnet stod på jordene hundrade och femtio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Då tänkte Gud på Noah, och på all djur, och på all fänad, som med honom i arkenom var, och lät komma väder på jordene, och vattnet minskades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Och djupsens källor förstoppades, så ock himmelens fenster, och regnet af himmelen vardt stilladt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Och vattnet förlopp utaf jordene mer och mer, och vardt mindre, efter hundrade och femtio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'På sjuttonde dagenom i den sjunde månadenom blef arken ståndandes på de berg Ararat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Men vattnet förlopp framgent af, och vardt ju mindre, allt intill tionde månaden. På första dagenom i tionde månadenom syntes det öfversta på bergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Efter fyratio dagar lät Noah fenstret upp på arkenom, som han gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Och lät flyga en korp ut, och han flög bort åter och fram, till dess att vattnet aftorkades af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Sedan lät han ena dufvo utflyga ifrå sig, på det han skulle försöka, om vattnet på jordene var förfallet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Då dufvan fann icke hvar hon kunde hvila sin fot uppå, kom hon igen till honom i arken, ty vattnet var ännu på hela jordene. Så räckte han handena ut, och tog henne till sig in i arken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Och bidde ännu andra sju dagar, och lät än en tid flyga ut dufvona af arkenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Hon kom till honom emot aftonen, och si, hon förde i sin mun ett afbrutet olivelöf. Så förnam Noah, att vattnet var förfallet på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Men han töfvade ännu andra sju dagar, och lät så ena dufvo flyga ut, hvilken intet igen kom till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'På första och sjettehundrade årena af Noahs ålder, på första dagenom i första månadenom, förtorkades vattnet på jordene. Då lät Noah taket upp på arkenom, och såg, att jorden var torr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Så vardt då jorden allstinges torr på sjunde och tjugonde dagenom i den andra månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Då talade Gud till Noah och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Gack utur arkenom, du och din hustru, dine söner och dina söners hustrur med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Allahanda djur, som när dig äro, utaf hvarjo och eno kötte, både i foglar och fänad, och det som på jordene kräker, det gånge ut med dig. Och förkofrer eder uppå jordene, och varer fruktsamme, och föröker eder på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Så gick Noah ut med sina söner, och med sine hustru, och sina söners hustrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Dertill allahanda djur, allahanda krypande, allahanda foglar, och allt det som på jordene kräker, det gick utur arkenom, och hvart och ett till sitt slag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Och Noah byggde Herranom ett altare, och tog utaf allahanda ren fänad, och utaf allahanda rena foglar, och offrade brännoffer på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Och Herren luktade en söt lukt, och sade i sitt hjerta: Ingalunda skall jag mer härefter förbanna jordena för menniskones skull, förty menniskones hjertas uppsåt är ondt allt ifrå ungdomen. Och skall jag nu icke mer härefter slå allt det som lefvandes är, såsom jag gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Så länge jorden står, skall icke återvända sående och uppskärande, köld och hette, sommar och vinter, dag och natt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Och Gud välsignade Noah och hans söner, och sade: Varer fruktsamme, och förökens, och uppfyller jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Edor fruktan och rädsla vare öfver all djur på jordene, öfver alla foglar under himmelen, och öfver allt det som kräker på jordene, och alle fiskar i hafvet vare gifne i edra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Allt det som röres och lefver, det vare eder till mat; såsom gröna örter hafver jag allt det gifvit eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Allena äter icke kött, det ännu lefver i sinom blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Förty, jag vill ock hämnas öfver edar kropps blod, och vill hämnat uppå all djur, och vill hämnas menniskones lif på hvarjo och ena mennisko, eho hon är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Den som utgjuter menniskoblod, hans blod skall ock af menniskom utgjutit varda. Förty Gud hafver gjort menniskona efter sitt beläte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Varer fruktsamme, och förökens, och förkofrer eder på jordene, att I uppfyllen henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Yttermera sade Gud till Noah, och hans söner med honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Si, jag gör med eder ett förbund, och med edra säd efter eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Och med allom lefvandom djurom som med eder äro, i foglar, i fänad, och i allom djurom, som på jordene när eder äro; af allt det som utur arkenom gånget är, ehvad djur det är på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Och vill göra mitt förbund med eder i så måtto, att härefter skall nu icke mer allt kött förderfvadt varda med flodsens vatten, och skall härefter ingen mer flod komma, den jordena förderfva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Och Gud sade: Detta är tecknet till mitt förbund, som jag gjort hafver emellan mig och eder, och all lefvande djur med eder härefter till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Min båga hafver jag satt i skynom, den skall vara tecknet till mitt förbund emellan mig och jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Och när så sker, att jag förer skyn öfver jordena, så skall man se min båga i skynom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Och så skall jag tänka på mitt förbund emellan mig och eder, och all lefvande djur i hvart och ett kött, att icke mer skall komma flod härefter, den allt kött förderfva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Derföre skall min båge vara i skynom, att jag skall se uppå honom, och tänka uppå det eviga förbund emellan Gud och all lefvande djur i hvarjo och eno kötte, som på jordene är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Det samma sade ock Gud till Noah: Detta skall vara tecknet till det förbund, som jag gjort hafver emellan mig och allt kött på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Noahs söner, som utur arkenom gingo, äro desse: Sem, Ham, Japhet. Men Ham är fadren till Canaan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Dessa tre äro Noahs söner, af hvilkom all land besatt vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Och Noah begynte till och vardt en åkerman, och plantade vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Och då han drack af vinet, vardt han drucken, och låg oskyld uti sine hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Då nu Ham, Canaans fader, såg sins faders blygd, sade han det bådom sinom brödrom, som ute voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Då togo Sem och Japhet ett kläde, och lade på bägges deras skuldror, och gingo baklänges till, och öfvertäckte deras faders blygd, och deras ansigte var ifrå vändt, så att de deras faders blygd icke sågo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Som nu Noah uppvaknade af sino vine, och fick veta hvad hans yngste son honom gjort hade, sade han:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Förbannad vare Canaan, och vare en träl under alla trälar ibland hans bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Och sade yttermera: Lofvad vare Herren Sems Gud, och Canaan vare hans träl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Gud förvidge Japhet, och låte honom bo i Sems hyddor, och Canaan vare hans träl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Och Noah lefde efter flodena trehundrade och femtio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Så att hans hela ålder vardt niohundrade och femtio år, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Detta är Noahs söners slägt: Sem, Ham, Japhet, och de födde barn efter flodena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Japhets barn äro desse: Gomer, Magog, Madaj, Javan, Thubal, Mesech och Thiras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Men Gomers barn äro desse: Ascenas, Riphath och Thogarma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Javans barn äro desse: Elisa, Tharsis, Chitthim och Dodanim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Utaf dessom äro utspridde Hedningarnas öar i deras landom, hvar efter sitt mål, slägte och folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Hams barn äro desse: Chus, Mizraim, Phut och Canaan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Chus barn äro desse: Seba, Hawila, Sabtha, Raema och Sabthecha. Raemas barn äro desse: Scheba och Dedan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Men Chus födde Nimrod; han begynte en väldig herre vara på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Och var en väldig jägare för Herranom. Deraf är det ordspråket: Det är en väldig jägare för Herranom, såsom Nimrod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Och hans rikes begynnelse var Babel, Erech, Acad och Calne uti Sinear land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Utaf det landet är sedan kommen Assur; och han byggde Nineve och Rehoboth, och Calah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Och dertill Resen emellan Nineve och Calah: Detta är en stor stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mizraim födde Ludim, Anamim, Lehabim, Naphtuhim,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Patrusim och Casluhim. Af hvilkom utkomne äro de Philistim och Caphthorim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Men Canaan födde Zidon sin första son, och Heth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Jebusi, Emori, Girgasi,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hivi, Archi, Sini,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arvadi, Semari och Hamathi. Af dem äro utspridde de Cananeers slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Och deras gränsor voro ifrå Zidon genom Gerar, allt intill Gaza, till dess man kommer intill Sodoma, Gomorra, Adama, Zeboim, och intill Lasa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Desse äro nu Hams barn i deras slägter, tungomålom, landom och folkom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Men Sem, Japhets broder, den äldste, födde ock barn, hvilken en fader är till all Ebers barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Och desse äro hans barn: Elam, Assur, Arphachsad, Lud och Aram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Arams barn äro desse: Uz, Hul, Gether och Mas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arphachsad födde Salah, Salah födde Eber.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Eber födde två söner, en het Peleg, derföre att i hans tid vardt verlden delad; hans broder het Jaketan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Och Jaketan födde Almodad, Saleph, Hazarmaveth, Jarah,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Usal, Dikela,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Seba,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Hawila och Jobab. Alle desse äro Jaketans söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Och deras boning var ifrå Mesa, intill man kommer till Sephar på berget öster ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Dessa äro Sems barn, uti deras slägter, tungomålom, landom och folkom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Detta är nu Noahs barns afföda, uti deras slägter och folkom. Af hvilkom utspridt är folket på jordene efter floden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Och all verlden hade enahanda tungo och mål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Då de nu drogo öster ut, funno de en plan uti Sinear land, och bodde der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Och sade till hvarannan: Kommer, låter oss slå tegel och bränna. Och togo tegel för sten, och ler för kalk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Och sade: Kommer, låter oss bygga en stad och ett torn, hvilkets höjd skall räcka upp i himmelen, att vi måge göra oss ett namn, förty vi varde tilläfventyrs spridde ut i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Då steg Herren neder, att han skulle se staden och tornet, som menniskones barn byggde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Och Herren sade: Si, det är enahanda folk, och enahanda mål ibland dem alla, och hafva detta begynt att göra, de varda icke aflåtande af allt det de hafva sig företagit att göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Kommer, låter oss stiga neder och förbistra der deras tungomål, så att ingen skall förstå den andras mål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Och så skingrade Herren dem dädan i all land, så att de återvände bygga staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Derföre kallades hans namn Babel, ty att Herren der förbistrade all lands tungomål, och Herren spridde dem dädan ut i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Detta är Sems slägt: Sem var hundrade år gammal, och födde Arphachsad, tu år efter floden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Och lefde derefter i femhundrade år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arphachsad var fem och tretio år gammal, och födde Salah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Och lefde derefter fyrahundrade och tre år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Salah var tretio år gammal, och födde Eber.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Och lefde derefter fyrahundrade och tre år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Eber var tretio och fyra år gammal, och födde Peleg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Och lefde derefter fyrahundrade och tretio år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg var tretio år gammal, och födde Regu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Och lefde derefter i tuhundrade och nio år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Regu var tu och tretio år gammal, och födde Serug.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Och lefde derefter tuhundrade och sju år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serug var tretio år gammal, och födde Nahor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Och lefde derefter tuhundrade år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nahor var nio och tjugu år gammal, och födde Tharah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Och lefde derefter hundrade och nitton år, och födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Tharah var sjutio år gammal, och födde Abram, Nahor och Haran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Desse äro Tharahs slägter: Tharah födde Abram, Nahor och Haran. Haran födde Lot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Och dödde Haran när sinom fader Tharah, uti hans faders land i Ur i Chaldeen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Då togo Abram och Nahor sig hustrur: Abrams hustru het Sarai, och Nahors hustru Milca Harans dotter, den fader var åt Milca och åt Jisca.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Men Sarai var ofruktsam, och hade inga barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Så tog Tharah sin son Abram, och Lot sins sons Harans son, och sina sonahustru Sarai, sins sons Abrams hustru, och förde dem ifrån Ur utu Chaldeen, på det de skulle fara i Canaans land; och de kommo till Haran, och bodde der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Och Tharah vardt tuhundrade och fem år gammal, och blef död i Haran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Och Herren talade till Abram: Gack utu ditt fädernesland, och ifrå dine slägt, och ifrå dins faders huse, uti ett land, som jag dig visa vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Och jag skall göra dig till ett stort folk, jag skall välsigna dig, och göra dig ett stort namn, och du skall vara en välsignelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Jag skall välsigna dem som dig välsigna, och förbanna dem som dig förbanna; och i dig skola välsignade varda alla slägter på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Då for Abram ut, såsom Herren honom sagt hade, och Lot for med honom. Men Abram var sjutio och fem år gammal, då han for utaf Haran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Så tog Abram sina hustru Sarai, och Lot sin broderson, med alla deras håfvor, som de förvärfvat hade, och de själar, som de födt hade i Haran, och foro ut till att resa in i Canaans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Och som de komne voro in i landet, drog han derigenom allt intill det rummet Sichem, och intill den lunden More. På den tiden bodde de Cananeer der i landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Då syntes Herren Abram och sade: Dine säd skall jag gifva detta land. Och han byggde dersammastädes ett altare Herranom, som honom synts hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Sedan drog han bätter fram dädan till ett berg, som låg öster ut ifrå BethEl, och slog der sitt tjäll upp, så att han hade BethEl vester ut, och Ay öster ut, och byggde der Herranom ett altare, och predikade om Herrans namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Och for Abram dädan fram bätter, och drog söder ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Då vardt en hård tid der i landet; derföre drog Abram neder uti Egypten, att han der en främling blifva måtte, förty tiden var ganska hård i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Och då han kom hardt in emot Egypten, talade han till sina hustru Sarai: Si, jag vet, att du äst en dägelig qvinna under ansigtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Då nu de Egyptier få se dig, skola de säga: Det är hans hustru, och slå mig ihjäl, och behålla dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Kära, säg fördenskull, att du äst min syster, att mig måtte ske godt för dina skull, och att min själ må lefva för dina skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Som han nu kom uti Egypten, sågo de Egyptier qvinnona, att hon var ganska dägelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Och Pharaos öfverstar sågo henne, och prisade henne för honom. Då vardt hon tagen in uti Pharaos hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Och Abram vederfors godt för hennes skull. Och han hade får, fä, åsnar, tjenare och tjenarinnor, åsninnor och camelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Men Herren plågade Pharao med stora plågor, och hans hus, för Sarai Abrams hustrus skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Då kallade Pharao Abram till sig, och sade till honom: Hvi hafver du sådant gjort mig? Hvi sade du mig icke, att hon var din hustru?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Hvi sade du, att det var din syster? Fördenskull ville jag taga mig henne till hustru. Och si, nu hafver du här dina hustru, tag henne och gack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Och han befallte sina män om honom, att de skulle fordra honom och hans hustru, och allt det han hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Så for då Abram upp utur Egypten med sine hustru, och med allt det han hade, och Lot ock med honom, söder ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Och Abram var ganska rik på boskap, silfver och guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Och han for bätter fram ifrå sunnan allt intill BethEl, till det rummet, der han sitt tjäll tillförene haft hade, emellan BethEl och Ay.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Rätt på samma rum, der han tillförene hade byggt altaret. Och der predikade han Herrans namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Men Lot, som med Abram for, hade också får, och fä, och tjäll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Och landet kunde icke fördragat, att de bodde tillhopa, förty deras håfvor voro stora, och kunde icke bo med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Och var ju alltid träta emellan herdarna öfver Abrams boskap och herdarna öfver Lots boskap. Och bodde desslikes i den tiden de Cananeer och Phereseer der i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Då sade Abram till Lot: Käre, låtom icke vara träta emellan mig och dig, och emellan mina och dina herdar; ty vi äre bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Står icke allt landet dig öppet? Käre, skilj dig ifrå mig. Vill du till venstra handena, så vill jag till den högra; eller vill du till den högra, så vill jag till den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Då hof Lot sin ögon upp, och besåg den hela ängden vid Jordan. Förty, förra än Herren förderfvade Sodom och Gomorra, var hon vatturik, allt intill man kommer till Zoar, såsom en Herrans lustgård, lika som Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Så utvalde sig Lot den hela ängden vid Jordan, och drog öster ut. Och så skildes den ene brodren ifrå den andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Att Abram bodde i Canaans land, och Lot i samma ängdens städer, och slog sitt tjäll upp in mot Sodom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Men det folk i Sodom var ondt, och syndade svårliga emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Då nu Lot hade skilt sig ifrån Abram, sade Herren (till Abram): Häf upp din ögon, och se ifrå det rummet, der du nu bor, norr ut, söder ut, öster ut och vester ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Förty allt detta landet, som du ser, vill jag gifva dig och dine säd till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Och vill göra dina säd såsom stoftet på jordene. Kan en menniska räkna stoftet på jordene, så må hon ock räkna dina säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Derföre upp, och drag genom landet, tvärs och ändalångs; förty dig vill jag gifva det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Så tog Abram sitt tjäll upp, och kom och bodde vid den lunden Mamre, hvilken i Hebron är, och byggde dersammastädes Herranom ett altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Och det begaf sig i Amraphels tid Konungens i Sinear, Ariochs, Konungens i Ellasar, Kedor Laomers, Konungens i Elam, och Thideals Hedningarnas Konungs,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Att de örligade med Bera, Konungenom i Sodom, och med Birsa, Konungenom i Gomorra, och med Sineab, Konungenom i Adama, och med Semeber, Konungenom i Zeboim, och med Konungenom i Bela, det är Zoar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Desse kommo alle tillsammans i den dalenom Siddim, der nu är salthafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Förty de hade varit i tolf år under Konung Kedor Laomer, och uti de trettonde årena voro de honom affallne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Derföre kom Kedor Laomer och de Konungar, som med honom voro, uti de fjortonde årena, och slogo de Resar i Astaroth Karnaim, och de Susim i Ham, och de Emim på den planenom Kiriathaim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Och de Horeer på deras berg Seir, intill den planen Pharan, som skjuter in på öknena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Sedan vände de om, och kommo till den brunnen Mispat, det är Kades, och slogo hela de Amalekiters land, dertill de Amoreers, som i Hazezon Thamar bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Så drogo ut Konungen i Sodom, Konungen i Gomorra, Konungen i Adama, Konungen i Zeboim, och Konungen af Bela, det Zoar heter, och rustade sig till att strida i den dalenom Siddim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Med Kedor Laomer, Konungen i Elam, och med Thideal, Hedningarnas Konung, och med Amraphel, Konungenom i Sinear, och med Arioch Konungenom i Ellasar: Fyra Konungar emot fem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Och den dalen Siddim hade många lergropar. Men Konungen i Sodom och Gomorra vordo der slagne på flyktena och nederlagde, och de som öfverblefvo flydde upp på berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Så togo de alla ägodelar i Sodom och Gomorra, och alla fetalia, och drogo sina färde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Och togo desslikes med sig Lot, Abrams broders son, och hans ägodelar, ty han bodde i Sodom, och drogo sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Då kom en, som undsluppen var, och sade det för Abram, den en utländning var, och bodde i den lundenom Mamre, dens Amoreens, hvilken Escols och Aners broder var; desse voro i förbund med Abram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Som nu Abram hörde, att hans broder var fången, väpnade han sina egna hemfödda tjenare, trehundrade och aderton, och drog efter dem allt intill Dan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Delade sig, och föll till dem med sina tjenare om nattena, och slog dem, och fullföljde dem allt intill Hoba, som ligger på venstra handen vid den staden Damasco,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Och tog alla ägodelar igen, och dertill Lot sin broder, och hans ägodelar, och qvinnorna, och folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Då han nu igen kom, och hade afslagit Kedor Laomer och de Konungar med honom, gick Konungen i Sodom emot honom på den planenom, som het Konungsdalen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Men Melchisedech, Konung i Salem, bar fram bröd och vin. Och han var den högstes Guds Prester;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Och välsignade honom, och sade: Välsignad vare du Abram dem högsta Gudi, den himmel och jord tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Och lofvad vare Gud den högste, som dina fiender beslutit hafver i dina hand. Och honom gaf Abram tionde af allo byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Då sade Konungen af Sodom till Abram: Gif mig folket, och ägodelarne behåll för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Men Abram sade till Konungen af Sodom: Jag upphäfver mina händer till Herran den högsta Gud, som himmel och jord tillhörer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Att jag af allo det ditt är icke en tråd eller en skorem taga vill, att du icke skall säga: Jag hafver riktat Abram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Undantagno det de unge karlar förtärt hafva, och de män, som med mig drogo, Aner, Escol och Mamre, dem låt taga deras del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Sedan detta så skedt var, begaf sig, att Herrans ord i en syn kom till Abram, sägandes: Frukta dig intet, Abram, jag är ditt beskärm och din ganska stora lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Men Abram sade: Herre, Herre, hvad vill du mig gifva? Jag går barnlös, och min redesven, denne Eleasar af Damasco, hafver en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Och Abram sade ytterligare: Men mig hafver du ingen säd gifvit. Och si, mins tjenares son skall vara min arfvinge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Och si, Herrans ord kom till honom, sägandes: Han skall icke vara din arfvinge, utan den, som utaf ditt lif komma skall, han skall vara din arfvinge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Och han hade honom ut, och sade: Se upp till himmelen, och räkna stjernorna, om du kan räkna dem. Och sade till honom: Så skall din säd vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Abram trodde Herranom, och han räknade honom det till rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Och han sade till honom: Jag är Herren, som dig utfört hafver ifrån Ur utu Chaldeen, att jag dig detta land gifva skall till besittning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Abram sade: Herre, Herre, hvaruppå skall jag märka, att jag skall besitta det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Och han sade till honom: Tag mig ena treåra ko, och ena treåra get, och en treåra vädur, och ena turturdufvo, och ena unga dufvo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Och han tog allt detta, och delade det midt i tu ifrå hvart annat, och lade hvar delen tvärt emot den andra; men foglarne delade han intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Och foglarne kommo neder på kropparna, och Abram dref bort dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Då solen nedergången var, föll en svår sömn på Abram, och si, en förskräckelse och ett stort mörker kom öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Då sade han till Abram: Detta skall du veta, att din säd skall varda främmande uti ett land, det dem icke tillhörer, och man skall der göra dem till trälar och fara illa med dem i fyrahundrade år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Men öfver det folk, som de tjenande varda, skall jag domare vara; sedan skola de draga ut med stora håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Och du skall fara till dina fäder med frid, och i en god ålder begrafven varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Men de skola i fjerde mans ålder komma hit igen; förty de Amoreers ondska är icke ännu all fullkomnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Då nu solen var nedergången, och mörker vordet, si, då rök en ugn, och en eld for emellan stycken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'På den dagen gjorde Herren ett förbund med Abram, och sade: Dine säd skall jag gifva detta landet, ifrå den älfvene i Egypten, allt intill den stora älfven Phrath:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'De Keneer, de Keniseer, de Kadmoneer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'De Hetheer, de Phereseer, de Reser,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'De Amoreer, de Cananeer, de Girgaseer, de Jebuseer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai Abrams hustru födde honom intet; men hon hade ena Egyptiska tjensteqvinno, som het Hagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Och sade till Abram: Si, Herren hafver igenlyckt mig, att jag icke kan få barn: Käre, lägg dig när mina tjensteqvinno, att jag dock tilläfventyrs måtte uppbyggd varda af henne. Abram hörde Sarai röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Och Sarai, Abrams hustru, tog sina Egyptiska tjensteqvinno Hagar, och gaf henne Abram sinom man till hustru, sedan de hade bott i tio år i Canaans lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Och han lade sig när Hagar, och hon vardt hafvande. Då hon nu såg, att hon vardt hafvande, föraktade hon sina fru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Då sade Sarai till Abram: Du gör orätt emot mig; jag hafver laggt mina tjensteqvinno när dig; nu, efter hon ser att hon är hafvande vorden, måste jag ringa aktad varda för henne: Herren dömme emellan mig och dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Men Abram sade till Sarai: Si, din tjensteqvinna är under ditt våld, gör med henne, som dig täckes. Då nu Sarai ville späka henne, flydde hon ifrå henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Men Herrans Ängel fann henne vid en vattubrunn i öknene, nemliga vid den brunnen, som är på den vägen till Sur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Och sade till henne: Hagar, Sarai tjensteqvinna, hvadan kommer du? Eller hvart vill du? Hon sade: Jag hafver flytt ifrå mine fru Sarai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Och Herrans Ängel sade till henne: Vänd om till dina fru igen, och ödmjuka dig under hennes hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Och Herrans Ängel sade till henne: Jag skall så föröka dina säd, att för stor myckenhet skall hon icke kunna räknas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Yttermera sade Herrans Ängel till henne: Si, du äst hafvande vorden, och skall föda en son; hans namn skall du kalla Ismael, derföre att Herren hafver sett dina vedermödo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Han skall vara en grym man; hans hand emot hvar man, och hvars mans hand emot honom; och han skall bo emot alla sina bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Och hon kallade Herrans namn, som talade med henne: Du Gud ser mig; ty hon sade: Visserliga hafver jag här sett ryggen på honom, som mig ser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Derföre kallade hon brunnen en brunn dens lefvandes, som mig ser, hvilken är emellan Kades och Bared.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Och Hagar födde Abram en son, och Abram kallade den sonen, som Hagar födde honom, Ismael.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Och Abram var sex och åttatio år gammal, då Hagar födde honom Ismael.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Då nu Abram nio och niotio år gammal var, syntes honom Herren, och sade till honom: Jag är Gud allsmäktig; vandra för mig och var fullkomlig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Och jag skall göra mitt förbund emellan mig och dig, och jag skall föröka dig svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Och Abram föll på sitt ansigte. Och Gud talade yttermera med honom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Si, jag äret, och hafver mitt förbund med dig, och du skall varda en fader för mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Derföre skall du icke mer heta Abram, utan Abraham skall vara ditt namn; ty jag hafver gjort dig till en fader för mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Och skall göra dig ganska mycket fruktsamman, och skall göra folk af dig; skola ock Konungar komma af dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Och jag vill göra mitt förbund emellan mig och dig, och dina säd efter dig, i deras afkommandom, att det skall vara ett evigt förbund, så att jag skall vara din Gud, och dine säds efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Och skall gifva dig, och dine säd efter dig, det land, der du en främling uti äst, nemliga, det hela landet Canaan, till evig besittning; och skall vara deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Och Gud sade yttermera till Abraham: Så håll nu mitt förbund, du, och din säd efter dig, i deras afkommandom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Och detta är förbundet, som I hålla skolen, emellan mig och dig, och dina säd efter dig: Allt det mankön ibland eder är skall omskäras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Men I skolen omskära edars kötts förhud. Det samma skall vara ett tecken till förbundet emellan mig och eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Hvart och ett piltebarn, då det är åtta dagar gammalt, skolen I omskära i edra afkommander. Sammalunda hvar och en tjenare, hemma födder eller köpter, eller eljest främmande, och icke af edro säd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Och så skall mitt förbund vara på edro kötte, till ett evigt förbund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Och hvar något piltebarn icke varder omskoret i hans kötts förhud, hans själ skall utrotas utu hans folk, derföre att han mitt förbund icke hållit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Och Gud sade åter till Abraham: Dina hustru Sarai skall du icke mer kalla Sarai, utan Sara skall vara hennes namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Ty jag skall välsigna henne, och af henne skall jag gifva dig en son, hvilken jag skall välsigna, och folk skola varda af honom, och Konungar öfver mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Då föll Abraham på sitt ansigte, och log, och sade i sitt hjerta: Skulle mig, som hundrade år gammal är, födas en son? Och Sara, som niotio år gammal är, skulle föda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Och Abraham sade till Gud: Ack, att dock Ismael måtte få lefva för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Då sade Gud: Ja, Sara din hustru skall föda dig en son, hvilken du skall kalla Isaac; ty med honom skall jag upprätta mitt eviga förbund, och med hans säd efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Dertill hafver jag ock bönhört dig om Ismael: Si, jag hafver välsignat honom, och skall göra honom fruktsamman, och föröka honom ganska svårliga; tolf Förstar skall han föda, och jag skall göra honom till mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Men mitt förbund skall jag upprätta med Isaac, den Sara dig föda skall, på denna tidenom åt året.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Och som talet vardt ändadt, for Gud upp ifrån Abraham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Och Abraham tog sin son Ismael och alla tjenare, hemma födda och köpta, och allt det mankön var i hans huse, och omskar förhudena på deras kött, straxt på samma dagenom, som Gud honom sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Och Abraham var nio och niotio år gammal, då han omskar förhudena på sitt kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Men Ismael hans son var tretton år gammal, då hans kötts förhud omskoren vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Allt på enom dag vordo de alle omskorne, Abraham och hans son Ismael;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Och allt det mankön var i hans huse, både hemfödde tjenare och köpte, och eljest främmande; alle vordo de omskorne med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Och Herren syntes honom i dem lundenom Mamre, der han satt vid sins tjälls dörr, då hetast var på dagenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Och som han upplyfte sin ögon och såg, då stodo tre män för honom. Och då han såg dem, lopp han emot dem ifrå sins tjälls dörr, och bugade sig ned på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Och sade: Herre, hafver jag funnit nåd för din ögon, så gack icke fram om din tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Man vill hemta eder litet af vatten och två edra fötter, och hviler eder under trät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Och jag vill lägga för eder ett stycke bröd, att I vederqvecken edor hjerta; sedan gån I då fram bätter, förty derföre ären I komne till edar tjenare. De sade: Gör som du hafver sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham skyndade sig in i tjället till Sara, och sade henne: Skynda dig, och blanda tre mått semlomjöl, och baka kakor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Men han lopp bort till boskapen, och tog en god späd kalf, och fick drängenom; han skyndade sig, och tillredde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Och han tog fram smör och mjölk, och af kalfvenom, som han tillredt hade, och satte för dem; och gick fram för dem under trät, och de åto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Då sade de till honom: Hvar är din hustru Sara? Han svarade: Derinne i tjället.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Han sade: När jag igenkommer till dig, om man lefver, si, så skall Sara din hustru hafva en son. Detta hörde Sara, der hon stod bak tjälldörrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Och de voro, både Abraham och Sara, gamle och väl till ålders komne, så att Sara nu icke mer hade som qvinnor pläga hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Derföre log hon vid sig sjelf, och sade: Nu jag gammal är, och min herre desslikes ålderstigen, skall jag ännu gifva mig till lusta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Då sade Herren till Abraham: Hvi log Sara, sägandes: Menar du, att det kan vara, att jag ännu föda skall, så gammal som jag är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Mån Herranom något vara omöjeligit? I sinom tid vill jag komma till dig igen, om man lefver, och då skall Sara hafva en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Då nekade Sara, och sade: Jag log intet, och vardt förfärad. Men han sade: Det är icke så, du logst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Då stodo männerne upp dädan, och vände sig åt Sodom, och Abraham följde dem och ledsagade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Och Herren sade: Huru kan jag dölja för Abraham det jag gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Efter han skall varda till ett stort och mägtigt folk, och all folk på jordene skola varda välsignade i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Ty jag vet, att han befaller sinom barnom, och sino huse efter sig, att de skola hålla Herrans vägar, och göra hvad rätt och godt är, på det att Herren skall låta komma öfver Abraham allt det han honom lofvat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Och Herren sade: I Sodom och Gomorra är ett rop, det är stort, och deras synder äro ganska svåra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Derföre skall jag fara ned och se till, om de allt gjort hafva efter ropet, som för mig kommet är; eller om det icke så är, att jag må vetat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Och männerne vände sitt ansigte, och gingo åt Sodom. Men Abraham vardt ståndandes för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Och trädde fram till honom, och sade: Vill du då förgöra den rättfärdiga med den ogudaktiga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Kunde hända, att i stadenom voro femtio rättfärdige, ville du dem förgöra, och icke skona de rummena för femtio rättfärdigas skull, som derinne voro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Bort det ifrå dig, att du det göra skulle, och döda den rättfärdiga med den ogudaktiga, och att dem rättfärdiga skulle gå lika som de ogudaktiga; bort det ifrå dig, som alla verldenes domare äst, sådana straff låter du icke gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Herren sade: Finner jag femtio rättfärdiga i Sodoms stad, så vill jag skona allestäds i all rum för deras skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Abraham svarade och sade: Ack si, jag hafver tagit mig före att tala med Herranom, ändock jag är stoft och aska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Om der voro fem mindre än femtio rättfärdige inne, ville du då förgöra hela staden för de fems skull? Han sade: Finner jag derinne fem och fyratio, så vill jag icke förgöra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Och han talade ändå ytterligare till honom, och sade: Måtte hända, att man finner der fyratio inne. Och han sade: Jag vill intet göra dem för de fyratio skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Och Abraham sade: Herre, tag icke till misstycke, om jag ännu talar något: Måtte hända, att man finner der tretio inne. Han svarade: Finner jag der tretio inne, så vill jag intet göra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Och han sade: Ack si, jag hafver tagit mig före att tala med min Herra: Måtte hända, att man finner tjugu derinne. Han svarade: Jag vill icke förgöra dem för de tjugu skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Och han sade: Tag icke till misstycke, Herre, om jag talar än en tid: Måtte hända, att man finner tio derinne. Han sade: Jag vill icke förgöra dem för de tio skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Och Herren gick bort, sedan han hade uttalat med Abraham; och Abraham vände om och gick hem till sitt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Och de två Änglarne kommo om aftonen till Sodom; och Lot satt i Sodom i portenom. Och då han såg dem, stod han upp emot dem, och bugade sig med sitt ansigte neder på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Och sade: Si Herre, kommer uti edar tjenares hus, och blifver der öfver nattena; låter två edra fötter, och i morgon stån I bittida upp, och faren edar väg. De sade: Nej, men vi vilje blifva öfver nattena på gatone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Då nödgade han dem fast, och de gingo in med honom, och de kommo uti hans hus: Och han gjorde dem en måltid, och bakade dem osyradt bröd, och de åto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Men förra än de lade sig, kommo de män af stadenom Sodom, och omhvärfde huset, unge och gamle, och allt folket tillhopa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Och kallade Lot ut, och sade till honom: Hvar äro männerne, som till dig ingångne äro i denna nattene? Låt dem gå här ut till oss, att vi måge känna dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot gick ut till dem för dörrene, och smällde dörrena igen efter sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Och sade: Ack käre bröder, görer icke så illa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Si, jag hafver två döttrar, de hafva ännu ingen man känt, dem vill jag få ut till eder, och farer med dem som eder täckes; att I ju intet ondt gören dessa männerna; ty derföre äro de ingångne under mitt taks skugga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Men de sade: Kom hit. Då sade de: Äst du icke allena en främling härinne, och vill nu regera? Nu väl, vi vilje göra dig mera ondt än dem. Och de trängde sig hårdeliga med våld in på mannen Lot, och de lupo till, och ville slå upp dörrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Men männerne räckte handen ut, och togo Lot in till sig i huset, och smällde dörrena till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Och männerna, som för dörrene voro af huset, slogo de med blindhet, både små och stora, så att de icke kunde finna dörrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Och männerne sade till Lot: Hafver du ock härinne några mågar, eller söner, eller döttrar? Alla de, som dig tillhöra i stadenom, dem haf här utu detta rummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Ty vi skole förgöra detta rummet, derföre, att deras rop är stort för Herranom, och Herren hafver utsändt oss till att förgöra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Då gick Lot ut, och talade med sina mågar, som skulle hafva hans döttrar, och sade: Görer redo, och går utu detta rum: förty Herren skall förgöra denna stad. Men dem syntes det vara gabberi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'När nu morgonrodnen uppgick, skyndade Änglarne på Lot, att han skulle låta sig lida, och sade: Gör redo, tag dina hustru, och dina två döttrar, som du hafver, att du ock icke förgås uti denna stadsens missgerningom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Som han ännu fördröjde, togo männerne honom vid handena, och hans hustru, och hans två döttrar, efter Herren ville skona dem, och ledde honom ut, och läto honom ut för staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Och som de hade haft honom ut, sade de: Förvara dina själ, och se icke tillbaka, och statt icke i alla denna ängd; men på berget undsätt dig, att du icke förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Då sade Lot till dem: Ack nej, min Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Si, efter din tjenare hafver funnit nåd för din ögon, så gör dock dina barmhertighet stora, som du på mig bevist hafver, att du skulle behålla mina själ vid lif: Jag kan icke förvara mig på bergena, mig måtte något ondt vederkomma, att jag blefve död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Si, der är en stad icke långt hädan, der jag in fly må, och han är liten, der vill jag förvara mig; är han dock liten, att min själ må der blifva vid lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Då sade han till honom: Si, i desse stycke hafver jag ock sett till dig, att jag icke vill omstörta den staden, der du om talade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Låt lida dig, och förvara dig der; ty jag kan intet göra, till dess du kommer der in. Deraf är den staden nämnd Zoar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Och solen var uppgången på jordene, då Lot kom in uti Zoar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Då lät Herren regna svafvel och eld ifrå Herranom af himmelen, öfver Sodom och Gomorra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Och omstörte de städer i alla den ängden, och alla de, som i städerna bodde, och allt det på landena växt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Och hans hustru såg tillbaka, och vardt en saltstod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Men Abraham stod upp om morgonen bittida, på det rummet, der han förr hade ståndet för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Och såg ut emot Sodom och Gomorra, och allt landet i den ängden, och fick se, att der uppgick ett damb af landena, lika som en rök af en ugn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Ty då Gud omstörte de städer i den ängdene, tänkte han på Abraham, och frälste Lot utu de städer, som han omstörte, der Lot uti bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Och Lot for utu Zoar, och blef på bergena med båda sina döttrar; ty han fruktade att blifva i Zoar: Och låg uti ene bergskrefvo, han och båda hans döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Då sade den äldsta till den yngsta: Vår fader är gammal, och ingen man är mer på jordene, som till oss ingå kan, efter alla verldenes sedvänjo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Kom, låt oss gifva vår fader dricka vin, och läggom oss när honom, att vi mågom behålla säd af vår fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Och så gåfvo de deras fader dricka vin i den nattene. Och den äldsta gick in, och lade sig när sinom fader; och han vardt intet varse, när hon lade sig, ej heller när hon stod upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Om morgonen sade den äldsta till den yngsta: Si, jag låg i går när min fader, låt oss ock i denna nattene gifva honom dricka vin, att du ock må gå in till honom, och lägga dig när honom, att vi behålle säd af vår fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Och så gåfvo de desslikes i den nattene sin fader dricka vin: Och den yngsta gick ock in, och lade sig när honom; och han vardt det intet varse, när hon lade sig ned, ej heller när hon stod upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Och så vordo de båda Lots döttrar hafvande af sin fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Och den äldsta födde en son, den hon kallade Moab; af honom kommo de Moabiter, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Och den yngsta födde ock en son, och hon kallade hans namn Ammi barn; af honom kommo Ammons barn, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Så for Abraham dädan in i landet söder ut, och bodde emellan Kades och Zur, och vardt en främling i Gerar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Och sade om sine hustru Sara: Det är min syster. Då sände Abimelech, Konungen i Gerar, efter henne, och lät hemta henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Men Gud kom till Abimelech om nattena i dröm, och sade till honom: Si, du måste dö för den qvinnones skull, som du tagit hafver; ty hon är ens mans ägta hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Men Abimelech hade ännu intet kommit vid henne. Och han sade: Herre, vill du ock dräpa ett rättfärdigt folk?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Sade han icke till mig: Hon är min syster? Och hon sade desslikes: han är min broder. Hafver jag dock detta gjort med enfaldigt hjerta och oskyldiga händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Och Gud sade till honom i drömmen: Jag vet ock, att du det med enfaldigo hjerta gjort hafver: Derföre hafver jag ock bevarat dig, att du icke skulle synda emot mig, och hafver icke tillstadt, att du skulle komma vid henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Så få nu mannenom sina hustru igen; ty han är en Prophet, och låt honom bedja för dig, så behåller du lifvet: Hvar du icke öfvergifver henne, så vet, att du måste döden dö, och allt det dig tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Då stod Abimelech bittida upp om morgonen, och kallade alla sina tjenare, och sade allt detta i deras åhöro. Och de män alle fruktade sig svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Och Abimelech kallade också Abraham, och sade till honom: Hvi hafver du oss detta gjort? Och hvad hafver jag brutit dig emot, att du ville komma så stor synd uppå mig och mitt rike? Du hafver icke så gjort emot oss, som man göra skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Och Abimelech sade ytterligare till Abraham: Hvad hafver du ansett, att du så gjorde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham sade: Jag tänkte tilläfventyrs i desso rumme är ingen Gudsfruktan, och de slå mig ihjäl för mine hustrus skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Och är hon sannerliga min syster; ty hon är min faders dotter, men icke mine moders dotter: Och jag tog mig henne till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Och då Gud böd mig, att jag skulle vandra utu mins faders huse, sade jag till henne: Gör denna barmhertighet med mig, hvart vi kommom, att du säger, att jag är din broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Då tog Abimelech får och fä, tjenare och tjenarinnor, och gaf Abraham, och fick honom igen hans hustru Sara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Och sade: Si, mitt land står dig öppet, bo var dig täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Och sade till Sara: Si, jag hafver gifvit dinom broder tusende silfverpenningar: Si, han skall vara dig till en ögnatäckelse för alla de, som när dig äro, ehvart du far, och en försvarare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Och Abraham bad till Gud, och Gud botade Abimelech, och hans hustru, och hans tjensteqvinnor, att de födde barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Ty Herren hade tillförene hårdeliga tillyckt alla qveder i Abimelechs huse, för Sara Abrahams hustrus skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Och Herren sökte Sara, såsom han sagt hade, och Herren gjorde med henne såsom han talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Och Sara vardt hafvande, och födde Abraham en son i sinom ålderdom, vid den tiden, som Gud honom föresagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Och Abraham nämnde sin son, som honom född var, Isaac, den honom Sara födt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Och omskar honom på åttonde dagen, som Gud honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Hundrade år gammal var Abraham, då honom hans son Isaac födder var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Och Sara sade: Gud hafver gjort mig ett löje; ty hvilken det får höra, han får le åt mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Och sade ytterligare: Ho torde ock säga Abraham sjelfvom, att Sara däggde barn, och hade födt honom en son i sinom ålderdom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Och barnet växte, och vardt afvandt. Och Abraham gjorde ett stort gästabud den dagen, då Isaac afvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Och Sara fick se den Egyptiska qvinnones Hagars son, den hon Abraham födt hade, att han var en bespottare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Och sade till Abraham: Drif denna tjensteqvinnona ut med hennes son; ty denne tjensteqvinnones son skall icke ärfva med min son Isaac.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Detta ordet behagade Abraham ganska illa för sin sons skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Men Gud sade till honom: Låt dig icke tycka hårdt vara om pilten och tjensteqvinnone; allt det Sara dig sagt hafver, så lyd henne; förty i Isaac skall säden dig nämnd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Jag skall ock göra tjensteqvinnones son till folk, derföre att han din säd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Då stod Abraham bittida upp om morgonen, och tog bröd och en flaska med vatten, och lade på Hagars rygg, och pilten med, och lät gå henne. Hon gick sin väg, och for vill i öknene, vid BerSaba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Då nu vattnet i flaskone var förtärdt, kastade hon pilten under en buska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Och gick bort och satte sig tvärs öfver långt ifrå, vid ett armborst skott; ty hon sade: Jag gitter icke se uppå att pilten dör. Och vid hon satt tvärs öfver, hof hon upp sina röst, och gret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Då hörde Gud piltens röst, och Guds Ängel kallade Hagar af himmelen, sägandes: Hvad skadar dig, Hagar? Frukta dig intet; förty Gud hafver hört piltens röst, der han ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Statt upp, tag pilten, och håll honom med dina händer; ty jag skall göra honom till stort folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Och Gud öppnade hennes ögon, att hon fick se en vattubrunn. Då gick hon till och fyllde sina flasko med vatten, och gaf piltenom dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Och Gud var med piltenom; han växte, och bodde i öknene, och vardt en god skytte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Och bodde i den öknene Pharan: Och hans moder tog honom hustru utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'På samma tiden talade Abimelech och Phicol, hans härhöfvitsman, med Abraham, och sade: Gud är med dig uti allt det du gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Så svär mig nu vid Gud, att du är mig icke arg, eller minom barnom, eller minom barnabarnom: Utan den barmhertighet, som jag hafver gjort med dig, den gör ock med mig, och landena, der du en främling uti äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Då sade Abraham: Jag vill svärja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Och Abraham straffade Abimelech för den vattubrunnens skull, som Abimelechs tjenare hade tagit med våld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Då svarade Abimelech: Jag hafver icke vist, ho det gjorde; ej heller sade du mig det; dertill hafver jag icke hört det förra än i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Då tog Abraham får och fä, och gaf Abimelech: Och gjorde båda ett förbund med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Och Abraham ställde sju lamb afsides.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Sade Abimelech till Abraham: Hvad skola de sju lamb, som du hafver ställt der afsides?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Han svarade: Sju lamb skall du taga af mine hand, att de skola vara mig till ett vittnesbörd, att jag denna brunn grafvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Deraf heter det rummet BerSaba, att de båda med hvarannan der så svoro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Och alltså gjorde de det förbund i BerSaba. Då stodo Abimelech och hans härhöfvitsman Phicol upp, och drogo in i de Philisteers land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Och Abraham plantade trä i BerSaba; och predikade der om Herrans eviga Guds namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Och var en främling uti de Philisteers land i långan tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Sedan det skedt var, försökte Gud Abraham, och sade till honom: Abraham. Och han svarade: Här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Och han sade: Tag Isaac din enda son, den du kär hafver, och gack bort uti Moria land, och offra honom der till ett bränneoffer på ett berg, det jag dig sägandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Då stod Abraham bittida upp om morgonen, och sadlade sin åsna, och tog med sig två drängar, och sin son Isaac, och högg sönder ved till bränneoffer, stod upp och gick bort till det rum, som Gud honom sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'På tredje dagen hof Abraham sin ögon upp, och såg rummet långt ifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Och sade till sina drängar: Blifver I här med åsnanom, jag och pilten viljom gå dit bort, och när vi tillbedit hafvom, vilje vi komma igen till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Och Abraham tog veden till bränneoffret, och lade den på sin son Isaac: Men han tog elden och knifven i sina hand, och gingo så både tillsamman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Då sade Isaac till sin fader Abraham: Min fader. Abraham svarade: Här är jag, min son. Och han sade: Si, här är elden och veden, hvar är nu fåret till bränneoffret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham svarade: Gud förser väl fåret, min son, till bränneoffret: Och de gingo både tillsamman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Och som de kommo till rummet, der Gud honom af sagt hade, byggde Abraham der ett altare, och lade veden deruppå; bandt sin son Isaac, och lade honom på altaret, ofvan på veden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Och uträckte sina hand, och tog till knifven, att han skulle slagta sin son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Då ropade honom Herrans Ängel af himmelen och sade: Abraham, Abraham. Han svarade: Här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Han sade: Kom intet dina hand vid pilten, och gör honom intet; ty nu vet jag att du fruktar Gud, och hafver icke skonat din enda son för mina skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Då hof Abraham sin ögon upp, och såg en vädur bak sig, bekajad med hornen uti en törnebuska: Och gick dit, och tog den väduren, och offrade honom till ett bränneoffer i sins sons stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Och Abraham kallade det rummet, Herren ser; af hvilko man ännu i dag säger: På berget, der Herren sedd varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Och Herrans Ängel ropade åter till Abraham af himmelen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Och sade: Jag hafver svorit vid mig sjelf, säger Herren, efter du detta gjorde, och icke skonade din enda son,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Att jag skall välsigna, och föröka dina säd såsom stjernorna på himmelen, och såsom sanden på hafsens strand: Och dina säd skall besitta sina fiendars portar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Och i dine säd skall allt folk på jordene välsignadt varda; derföre, att du mine röst lydt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Sedan gick Abraham till drängarna igen, och gjorde sig redo, och drogo tillsammans till BerSaba, och bodde der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Då detta så skedt var, begaf sig, att Abraham vardt sagdt: Si, Milca hafver ock födt barn dinom broder Nahor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Nemliga Uz den förstfödda, och Bus hans broder, och Kemuel, af hvilkom de Syrier komne äro:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Och Kesed, och Haso, och Pildas, och Jidlaph, och Bethuel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Men Bethuel födde Rebecka. Dessa åtta födde Milca Nahor, Abrahams broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Och hans frilla benämnd Rehuma födde ock, nemliga Tebah, Gaham, Thahas och Maacha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Sara lefde i hundrade sju och tjugu år:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Och blef död i den hufvudstaden, som kallas Hebron i Canaans lande. Då kom Abraham till att sörja och begråta henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Sedan stod han upp ifrå hennes lik, och talade till Hets barn, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Jag är en främling och en gäst när eder, gifver mig en arfrätt till begrafning när eder, att jag må begrafva min döda, som för mig ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Då svarade Hets barn Abraham, och sade till honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Hör oss, käre herre, du äst en Guds förste när oss; begraf din döda uti våra bästa grifter; ingen menniska af oss skall förvägra dig, att du begrafver din döda i hans graf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Då stod Abraham upp, och bugade sig för landsens folke, nemliga för Hets barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Och han talade med dem, och sade: Är det eder i sinnet, att jag begrafver min döda, som för mig ligger, så hörer mig, och beder för mig inför Ephron Zoars son,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Att han gifver mig sina dubbelkulo, den han hafver i andanom på sinom åker, för reda penningar; låter mig henne få när eder till en arfgrift.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Ty Ephron bodde ibland Hets barn. Då svarade Ephron, den Hetheen, Abraham i Hets barns åhöro, för allom dem, som ut och in gingo genom hans stadsport, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nej, min herre, utan hör till hvad jag säga vill: Jag gifver dig åkren, och den kulon med, som der inne är, och gifver dig honom för mitt folks barns åsyn, till att begrafva din döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Då bugade sig Abraham för landsens folke,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Och talade till Ephron i landsens folks åhöro, och sade: Vill du höra mig, så tag penningar af mig för åkren, de jag dig gifva vill; och så vill jag der begrafva min döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ephron svarade Abraham, och talade till honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Min herre, hör dock mig: Marken är värd fyrahundrade siklar silfver; men hvad kan det draga emellan mig och dig? Begraf man din döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraham hörde Ephron, och vog honom penningarna till, som han nämnt hade, hvilket Hets barn åhörde, nemliga fyrahundrade siklar silfver, som då gåfve och gängse voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Och så vardt Ephrons åker, der den dubbelkulan inne var, tvärs öfver Mamre, tillegnad Abraham till evärdeliga ägo, med kulone derinne, och med all trä omkring åkren,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'I Hets barns och allas deras åsyn, som genom hans stadsport ut och in gingo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Sedan begrof då Abraham Sara sina hustru uti kulone i åkrenom, den dubbel var, tvärs öfver ifrå Mamre, det är Hebron i Canaans lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Och alltså vardt Abraham stadfäst den åkren, och kulan, till begrafnings egendom af Hets barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Och Abraham var gammal och väl ålderstigen: Och Herren hade välsignat honom i all stycke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Då sade han till sin äldsta hustjenare, den all hans tingest förestod: Lägg dina hand under mina länd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Och svär mig vid Herran, himmelens och jordenes Gud, att du icke tager minom sone hustru af Canaans döttrar, ibland hvilka jag bor:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Utan far in uti mitt fädernesland, och till mina slägt, och tag minom sone Isaac hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Tjenaren sade: Om så hände, att qvinnan icke ville komma med mig in i detta land, skall jag då låta din son komma dit i landet igen, dädan du kommen äst?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham sade till honom: Vakta dig derföre, att du icke förer min son dit igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Herren himmelens Gud, som mig tog utu mins faders huse, och utu mitt födsloland, den med mig talat, och desslikes svurit och sagt hafver: Detta landet vill jag gifva dine säd; han skall sända sin Ängel framför dig, att du skall taga minom sone der hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Hvar nu qvinnan dig icke följa vill; så äst du qvitt denna ed: Allenast låt icke min son komma dit igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Då lade tjenaren sina hand under Abrahams sins herras länd, och svor honom här uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Så tog tjenaren tio camelar, af sins herras camelar, och drog åstad, och hade med sig af allahanda sins herras håfvor, och var uppe, och for till Mesopotamien till Nahors stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Der lät han camelarna blifva utanför stadenom, vid en vattubrunn, om aftonen då qvinfolken plägade der komma och taga vatten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Och sade: Herre, mins herras Abrahams Gud, kom i dag emot mig, och gör barmhertighet med minom herra Abraham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Si, jag står här när vattubrunnenom, och deras döttrar, som bo i denna stad, varda här utkommande till att taga vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Hvar nu någon piga kommer, och jag säger till henne: Håll hit dina kruko, och låt mig dricka, och hon säger: Drick, jag vill ock gifva dina camelar dricka, att hon är den samma, som du hafver beskärt dinom tjenare Isaac, och att jag derpå må förstå, att du hafver gjort barmhertighet med minom herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Och förra än han uttalat hade, si, Rebecka Bethuels dotter kom ut, hvilken är Milcas son, den Nahors Abrahams broders hustru var; hon bar ena kruko på axlarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Och hon var en ganska dägelig piga under ansigtet, och var ännu jungfru, och ingen man hade känt henne: Hon kom ned till brunnen, och fyllde krukona, och ville gå hem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Då lopp tjenaren emot henne, och sade: Låt mig dricka något litet vatten af dine kruko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Och hon sade: Drick, min herre; och strax tog hon krukona ned på sina hand, och gaf honom dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Och då hon hade gifvit honom dricka, sade hon: Jag vill ock ösa vatten åt dina camelar, till dess att de få alle dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Och hon slog straxt vattnet utu krukone i hoen, och lopp åter till brunnen till att ösa, och vattnade alla hans camelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Men mannen undrade på henne, och var stilla, till dess han kunde få veta, om Herren hade gjort hans resa lyckosam, eller ej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Då nu alle camelarne hade druckit, tog han fram ett gyldene ännespann, vägandes en half sikel, och två armringar till hennes händer, vägande tio siklar guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Och sade: Min dotter, hvem hörer du till? Säg mig dock det. Hafve vi ock rum till att få herberge i dins faders huse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Hon sade till honom: Jag är Bethuels dotter, Milcas sons, som hon hafver födt Nahor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Och hon sade ytterligare till honom: Är ock så mycket halm och foder när oss, och rum nog till herberge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Då böjde mannen sig ned, och bad till Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Och sade: Lofvad vare Herren, mins herras Abrahams Gud, som icke hafver tagit sina barmhertighet och sina sanning ifrå minom herra; förty Herren hafver fört mig den rätta vägen till mins herras broders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Och pigan lopp, och sade allt detta i sins moders huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Och Rebecka hade en broder, som het Laban: Och Laban lopp ut till mannen vid brunnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Och när han såg ännespannet och armringarna i sine systers händer, och hörde Rebeckas sine systers ord, att hon sade: Så hafver mannen sagt mig; kom han till mannen: Och si, han stod när camelarna vid brunnen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Och sade: Kom här in, du Herrans välsignade, hvi står du här ute? Jag hafver rymt huset, och gjort rum för camelarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Så hade han mannen in i huset, och lade af camelarna, och gaf dem halm och foder, och vatten till att två hans fötter, och männernas, som med honom voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Och satte mat för honom. Då sade han: Jag vill icke äta, förra än jag hafver värfvat mitt ärende. De svarade: Säg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Han sade: Jag är Abrahams tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Och Herren hafver rikeliga välsignat min herra, och han är stor vorden, och han hafver gifvit honom får och fä, silfver och guld, tjenare och tjenarinnor, camelar och åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Dertill hafver Sara, mins herras hustru, födt minom herra en son i sinom ålderdom, honom hafver han gifvit allt det han hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Och min herre hafver tagit en ed af mig, och sagt: Du skall icke taga minom sone någon hustru af de Cananeers döttrar, i hvilkas land jag bor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Utan far bort till mins faders hus, och till mina slägt, tag der minom sone hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Men jag sade till min herra: Huru? Om qvinnan icke vill följa mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Då sade han till mig: Herren, för hvilkom jag vandrar, varder sändandes sin Ängel med dig, och skall göra din väg lyckosam, så att du skall taga minom sone hustru af mine slägt och mins faders huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Då skall du vara min ed qvitt, när du kommer till mina slägt; gifva de dig icke, så äst du min ed qvitt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Så kom jag i dag till brunnen, och sade: Herre, mins herras Abrahams Gud, hafver du gjort min väg lyckosam, den jag nu reser:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Si, så står jag här vid vattubrunnen. När nu en jungfru kommer här ut till att taga vatten, och jag säger till henne: Gif mig litet vatten att dricka af dine kruko;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Och hon varder sägandes: Drick du; jag vill ock vattna dina camelar: det är den qvinna, som Herren hafver beskärt mins herras sone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Förra än jag nu sådan ord utsagt hade i mino hjerta, si, då kom Rebecka ut med ene kruko på sine axel, och gick ned åt brunnen till att taga vatten. Då sade jag till henne: Gif mig dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Och hon tog snarliga krukona af sin axel, och sade: Drick; dina camelar vill jag ock vattna. Så drack jag, och hon vattnade också camelarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Och jag frågade henne, och sade: Hvars dotter äst du? Hon svarade: Jag är Bethuels dotter, Nahors sons, som Milca honom födt hafver. Då hängde jag ett ännespann på hennes anlete, och armringar öfver hennes händer:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Och böjde mig neder, och bad till Herran, och lofvade Herran, mins herras Abrahams Gud, som mig hade fört rätta vägen, att jag skulle taga till hans son mins herras broders dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Om I nu ären de, som bevisen minom herra barmhertighet och sanning, så säger mig det; hvar ock icke, så säger mig ock det; att jag vänder mig antingen till den högra sidona, eller till den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Då svarade Laban och Bethuel, och sade: Det är utgånget af Herranom, derföre kunne vi intet säga dig emot, hvarken ondt eller godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Der är Rebecka för dig, tag henne, och far din väg, att hon blifver dins herras sons hustru, som Herren sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Då Abrahams tjenare hörde dessa ord, bugade han sig till jordena för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Och tog fram silfver och gyldene klenodier och kläder, och gaf dem Rebecka; men hennes broder och moder gaf han örter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Då åt han och drack samt med männerne, som med honom voro, och blefvo der öfver nattena. Om morgonen stod han upp, och sade: Låter mig fara till min herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Men hennes broder och moder sade: Låt dock blifva pigona vid tio dagar när oss; sedan skall du fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Då sade han till dem: Förhåller mig icke, förty Herren hafver gjort min väg lyckosam; släpper mig, att jag far till min herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Då sade de: Låter oss kalla pigona, och fråga hvad hon säger dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Och de kallade Rebecka, och sade till henne: Vill du fara med denne mannenom? Hon svarade: Ja, jag vill med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Så läto de Rebecka sina syster fara med hennes ammo, och Abrahams tjenare, och hans följare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Och de välsignade Rebecka, och sade till henne: Du äst vår syster, förkofra dig till tusende tusend, och din säd besitte sina fienders portar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Så redde Rebecka sig till med sina pigor, och satte sig på camelarna, och följde mannen efter. Och tjenaren tog Rebecka till sig, och for sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Men Isaac kom ifrå den brunnen, som kallades dens lefvandes och seendes; ty han bodde i det landet söder ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Och var utgången till att bedja i markene om aftonen; och hof upp sin ögon, och såg att camelarne kommo der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Och Rebecka hof upp sin ögon, och såg Isaac; då steg hon af camelen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Och sade till tjenaren: Hvad man är det, som kommer emot oss på markene? Tjenaren sade: Det är min herre. Då tog hon mantelen och höljde sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Och tjenaren förtäljde Isaac allt, huru han sakena uträttat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Då förde Isaac henne in i sins moders Saras hyddo, och tog Rebecka, och hon vardt hans hustru, och han vardt kär åt henne: Och så vardt Isaac hugsvalad öfver sina moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham tog åter ena hustru, hon het Ketura.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Hon födde honom Simran och Jacksan, Medan och Midian, Jisbak och Suah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Men Jacksan födde Seba och Dedan. Dedans barn voro Assurim, Letusim och Leummim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Midians barn voro Epha, Epher, Hanoch, Abida och Eldaa; desse äro alle Ketura barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Men Abraham gaf allt sitt gods Isaac.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Men de barnen, som han hade af frillorna, gaf han skänker, och lät dem fara ifrå sin son Isaac, medan han än lefde, öster ut i österlanden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Men Abrahams ålder, som han lefde, var hundrade fem och sjutio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Och blef sjuk, och dödde i en rolig ålder, då han af ålder och lefvande mätter var; och vardt samlad till sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Och honom begrofvo hans söner, Isaac och Ismael, i den dubbelkulone, på Ephrons åker, Zoars Hetheens sons, som ligger emot Mamre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'I den markene, som Abraham köpt hade af Hets barnom: Der är Abraham begrafven med Sara sine hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Och efter Abrahams död välsignade Gud hans son Isaac; och han bodde vid den brunnen, som kallades dens lefvandes och seendes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Detta är Ismaels Abrahams sons slägt, som Hagar, Saras tjensteqvinna af Egypten, födde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Och detta är Ismaels barns namn, der deras slägte hafva namn af: Ismaels förste son Nebajoth, Kedar, Adbeel, Mibsam,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma, Massa,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, Thema, Jethur, Naphis och Kedma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Desse äro Ismaels barn med deras namn, i deras byar och städer, tolf förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Och detta är Ismaels ålder, hundrade och sju och tretio år; och han vardt sjuk och dödde, och vardt samkad intill sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Men han bodde ifrå Hevila in till Zur emot Egypten, när man går till Assyrien; och satte sig emot alla sina bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Detta är Isaacs Abrahams sons slägte: Abraham födde Isaac.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Men Isaac var fyratio år gammal, då han tog Rebecka till hustru, Bethuels Syrens af Mesopotamien dotter, Labans Syrens syster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Men Isaac bad Herran för sine hustru, ty hon var ofruktsam; och Herren hörde honom, och Rebecka hans hustru vardt hafvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Och barnen stötte sig med hvarannan i hennes lif. Då sade hon: Efter mig skulle så gå, hvi är jag då vorden hafvandes? Och gick bort till att fråga Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Och Herran sade till henne: Tu folk äro i dino lifve, och tveggehanda folk skola skiljas utaf dino lifve: Och det ena folket skall öfvervinna det andra, och den större skall tjena den mindre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Då nu tiden kom att hon föda skulle, si, då voro tvillingar i hennes lifve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Den förste, som utkom, var röd och luden som ett skin: Och de kallade honom Esau.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Straxt derefter kom hans broder ut, han höll med sine hand i Esau fotablad, och de kallade honom Jacob: Sextio år gammal var Isaac, då de vordo födde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Och då drängarne vordo store, vardt Esau en jägare och en åkerman; men Jacob en from man, och bodde i tjäll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Och Isaac hade Esau kär, ty han plägade äta af hans vede; men Rebecka hade Jacob kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Och Jacob kokade en rätt; då kom Esau af markene, och var trötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Och sade till Jacob: Gif mig äta af denna röda rättenom, ty jag är trötter: Deraf heter han Edom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Men Jacob sade: Sälj mig i dag din förstfödslorätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Esau svarade: Si, jag måste dock dö: Hvad varder mig den förstfödslorätten nyttig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jacob sade: Så svär mig i dag. Och han svor honom: Och sålde så Jacob sin förstfödslorätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Då gaf Jacob honom bröd och den grynvällingen, och han åt och drack, och stod upp, och gick dädan. Och så föraktade Esau sin förstfödslorätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Så kom en dyr tid i landet, efter den förra, som var i Abrahams tid: Och Isaac for till Abimelech, de Philisteers Konung, till Gerar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Då uppenbarade sig honom Herren, och sade: Far icke ned i Egypten; utan blif i det land, som jag säger dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Blif en främling i desso landena, och jag skall vara med dig, och välsigna dig; förty dig dine säd skall jag gifva all denna landen, och skall stadfästa min ed, som jag dinom fader Abraham svurit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Och skall föröka dina säd såsom stjernorna på himmelen, och skall gifva dine säd all denna landen; och igenom dina säd skola all folk på jordene välsignade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Derföre, att Abraham hafver varit mina röst hörig, och hafver hållit mina seder, min bud, mina stadgar och min lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Så bodde Isaac i Gerar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Och när folket i den landsändanom frågade honom om hans hustru, sade han: Hon är min syster; ty han fruktade att säga: Hon är min hustru; att de tilläfventyrs icke måtte slagit honom ihjäl för Rebeckas skull; ty hon var dägelig under ansigtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Då han nu hade varit der en tid lång, såg Abimelech de Philisteers Konung ut genom fenstret, och vardt varse att Isaac skämtade med sine hustru Rebecka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Då kallade Abimelech Isaac, och sade: Si, det är din hustru; hvi hafver du sagt: Hon är min syster? Isaac svarade honom: Jag tänkte, att jag måtte tilläfventyrs varda slagen ihjäl för hennes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelech sade: Hvi hafver du då gjort oss det? Måtte sakta hafva skett, att någon af folket hade lägrat sig med dine hustru, och så hade du kommit skuld uppå oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Då böd Abimelech allo folkena, och sade: Hvilken som kommer vid denna mannen, eller hans hustru, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Och Isaac sådde der i landet, och fick det året hundradefaldt; ty Herren välsignade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Och han vardt en mägtig man, gick och växte till, till dess han vardt ganska stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Och hade mycket gods i får och fä, och mycket tjenstefolk; derföre afundades de Philisteer vid honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Och kastade igen alla de brunnar, som hans faders tjenare grafvit hade i hans faders Abrahams tid, och fyllde dem upp med jord:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Så att ock Abimelech sade till honom: Far ifrån oss; ty du äst vorden oss för mägtig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Då for Isaac dädan, och slog upp sin tjäll i Gerars dal, och bodde der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Och lät uppgrafva igen de vattubrunnar, som de i hans faders Abrahams tid grafvit hade, hvilka de Philisteer efter Abrahams död igenfyllt hade: Och kallade dem vid samma namnet, som hans fader dem kallat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Grofvo ock Isaacs tjenare i dalenom, och funno der en brunn med lefvandes vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Men herdarne af Gerar trätte med Isaacs herdar, och sade: Detta vattnet är vårt. Då kallade han den brunnen Esek, derföre att de hade der gjort honom högmod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Då grofvo de en annan brunn, der trätte de ock öfver; derföre kallade han honom Sitna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Då skyndade han sig dädan, och grof en annan brunn; der trätte de intet om; derföre kallade han honom Rehoboth, och sade: Nu hafver Herren gifvit oss rum, och låtit oss växa till i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Derefter for han dädan till BerSaba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Och Herren syntes honom i den nattene, och sade: Jag är dins faders Abrahams Gud: Frukta dig intet, ty jag är med dig, och skall välsigna dig, och föröka dina säd, för mins tjenares Abrahams skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Då byggde han dersammastädes ett altare, och predikade om Herrans namn, och uppslog der sitt tjäll: Och hans tjenare grofvo der en brunn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Och Abimelech gick till honom af Gerar, och Ahusath hans vän, och Phicol hans härhöfvitsman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Men Isaac sade till dem: Hvi kommen I till mig? Haten I mig dock, och hafven drifvit mig ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'De sade: Vi se med seende ögon, att Herren är med dig, derföre sade vi: Det skall vara en ed emellan oss och dig, och viljom göra ett förbund med dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Att du icke gör oss någon skada, lika som vi icke heller hafve något afhändt dig, och såsom vi ej heller hafve gjort dig annat än godt, och låtit dig fara med frid; men nu äst du den som Herren välsignat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Då gjorde han dem en måltid, och de åto och drucko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Och om morgonen bittida stodo de upp, och svoro den ene dem andra: Och Isaac lät dem gå. Och de foro ifrå honom med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Samma dagen kommo Isaacs tjenare, och sade honom om brunnen, som de grafvit hade, och sade till honom: Vi hafvom funnit vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Och han kallade honom Saba: Deraf heter den staden BerSaba än i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Då Esau var fyratio år gammal, tog han hustrur, Judith, Beeri dens Hetheens dotter, och Basmath, Elons dens Hetheens dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'De voro båda emot Isaac och Rebecka ganska bittra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Och det begaf sig, då Isaac var vorden gammal, att hans ögon vordo mörk till syn, kallade han Esau, sin större son, och sade till honom: Min son. Han svarade honom: Här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Och han sade: Si, jag är vorden gammal, och vet ej när jag skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Så tag nu din tyg, koger och båga, och gack ut i markena, och hemta mig villebråd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Och gör mig en mat, så som jag gerna vill hafvat, och bär mig honom här in, att jag må äta; på det min själ må välsigna dig, förra än jag dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Men Rebecka hörde sådana ord, som Isaac sade till sin son Esau. Och Esau gick ut i markena, att han skulle taga villebråd, och hafva henne hem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Då sade Rebecka till sin son Jacob: Si, jag hafver hört din fader tala med dinom broder Esau, och säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Hemta mig en villebråd, och gör mig mat, att jag må äta, och välsigna dig för Herranom, förra än jag dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Så hör nu min son mina röst, hvad jag dig säger:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gack bort till hjorden, och hemta mig två goda kidlingar, att jag gör dinom fader deraf mat, såsom han gerna vill hafvat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Det skall du bära dinom fader in, att han äter; på det han må välsigna dig, förra än han dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jacob sade till sina moder Rebecka: Si, min broder Esau är luden, och jag släter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Så kan tilläfventyrs min fader taga uppå mig, och måtte tänka, att jag vill bedraga honom: Och låter så öfver mig gå en förbannelse, och icke en välsignelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Då sade hans moder till honom: Den förbannelsen vare öfver mig, min son; hör man du mina röst, gack och tag mig det hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Då gick han bort och tog, och bar till sina moder; då gjorde hans moder en mat, såsom hans fader gerna hadet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Och tog Esau, hennes större sons, kosteliga kläder, som hon när sig i huset hade, och klädde dem på Jacob sin mindre son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Men skinnen af kidlingarna svepte hon om hans händer, och der han var släter på halsenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Och fick så maten, med bröd, såsom hon redt hade, uti Jacobs sins sons hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Och han bar det in till sin fader, och sade: Min fader. Han svarade: Här är jag; ho äst du, min son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jacob sade: Jag är Esau, din förstfödde son; jag hafver gjort som du hafver sagt mig: statt upp, sätt dig, och ät af mine villebråd, på det din själ må välsigna mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Men Isaac sade till sin son: Min son, huru hafver du så snart funnit? Han svarade: Herren din Gud hafver mig det bestyrt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Då sade Isaac till Jacob: Gack hit, min son, att jag tager uppå dig, om du äst min son Esau, eller ej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Så gick Jacob till sin fader Isaac, och då han hade tagit uppå honom, sade han: Rösten är Jacobs röst, men händerna äro Esaus händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Och kände honom intet, ty hans händer voro ludna, såsom Esaus hans broders händer; och så välsignade han honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Och sade till honom: Äst du min son Esau? Han svarade: Ja, jag äret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Då sade han: Så tag mig hit, min son, till att äta af dine villebråd, att min själ må välsigna dig. Då bar han det till honom, och han åt; och bar honom desslikes vin in, och han drack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Och Isaac hans fader sade till honom: Kom hit, och kyss mig, min son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Han gick till, och kysste honom. Då kände han lukten af hans kläder, och välsignade honom och sade: Si, mins sons lukt är såsom ens åkers lukt, den Herren välsignat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Gud gifve dig af himmelens dagg, och af jordenes fetma, och rikeliga korn och vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Folk tjene dig, och slägter falle dig till fota: Var en herre öfver dina bröder, och dins moders barn falle dig till fota: Förbannad vare den dig förbannar; välsignad vare den dig välsignar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'När nu Isaac lyktat hade välsignelsen öfver Jacob, och Jacob som nogast utgången var ifrå sinom fader Isaac, då kom Esau hans broder utaf sine jagt,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Och gjorde också en mat, och bar in till sin fader, och sade till honom: statt upp, min fader, och ät af dins sons vildebråd, att din själ må välsigna mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Då svarade honom Isaac hans fader: Ho äst du? Han sade: Jag är Esau din förstfödde son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Då vardt Isaac öfvermåttan häpen, och sade: Ho? Och hvar är då den jägaren, som mig det burit hafver, och jag åt utaf allo, förra än du kom, och välsignade honom? Han skall ock välsignad blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'När Esau detta sins faders tal hörde, ropade han högt, och vardt öfvermåttan förbittrad, och sade till sin fader: Välsigna ock mig, min fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Men han sade: Din broder är kommen med list, och hafver din välsignelse borta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Då sade han: Rätteliga heter han Jacob, ty han hafver nu två resor undertrampat mig: Min förstfödslorätt hafver han borta; och si, nu tager han ock min välsignelse bort. Och sade: Hafver du ingen välsignelse behållit för mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaac svarade, och sade till honom: Jag hafver satt honom till en herre öfver dig, och alla hans bröder hafver jag gjort honom till tjenare; med korn och vin hafver jag försett honom: Hvad skall jag dock nu göra dig, min son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Esau sade till sin fader: Hafver du då icke utan en välsignelse, min fader? Välsigna mig ock, min fader; och hof upp sina röst och gret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Då svarade Isaac hans fader och sade till honom: Si, en fet boning skall du hafva på jordene, och af himmelens dagg ofvan efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Med ditt svärd skall du nära dig, och skall tjena dinom broder: Och det skall ske, att du skall ock varda en herre, och rifva hans ok af dinom halse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Och Esau vardt vred uppå Jacob, för välsignelsens skull, der hans fader honom med välsignat hade, och sade i sitt hjerta: Den tiden varder snart kommandes, att min fader måste få sorg, ty jag vill dräpa min broder Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Då vardt Rebecka sagdt om dessa hennes större sons Esaus ord: Och sände bort, och lät kalla sin mindre son Jacob, och sade till honom: Si, din broder Esau hotar dig, att han vill dräpa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Och hör nu mina röst, min son, gör dig redo, och fly till min broder Laban i Haran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Och blif en tid lång när honom, till dess dins broders grymhet återvänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Och tilldess hans vrede vändes ifrå dig, och förgäter det du honom gjort hafver; så vill jag sedan sända, och låta hemta dig dädan: Hvi skulle jag mista eder båda på en dag?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Och Rebecka sade till Isaac: Mig ledes vid att lefva, för Hets döttrars skull: Om Jacob tager hustru af Hets döttrar, hvilka äro såsom dessa landsens döttrar, efter hvad skall jag lefva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Då kallade Isaac sin son Jacob, och välsignade honom, och böd honom, och sade till honom: Tag icke hustru af Canaans döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Utan gör dig redo, och far in i Mesopotamien till Bethuel, dins moderfaders hus, och tag dig der hustru af Labans dins moderbroders döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Men allsmägtig Gud välsigne dig, och göre dig fruktsam, och föröke dig, så att du varder en skare med folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Och gifve dig Abrahams välsignelse, dig och dine säd med dig; att du må besitta det land, der du en främling uti äst, det Gud Abraham gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Så skilde Isaac Jacob ifrå sig, att han for in i Mesopotamien till Laban Bethuels son af Syrien, Rebeckas broder, som hans och Esaus moder var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'När nu Esau såg, att Isaac hade välsignat Jacob, och sändt honom in i Mesopotamien, att han skulle der taga sig hustru; och att sedan han honom välsignat hade, böd han honom, och sade: Du skall ingen hustru taga af Canaans döttrar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Och att Jacob var sinom fader och moder lydig, och for in i Mesopotamien:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Såg ock, att Isaac hans fader såg icke gerna Canaans döttrar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Gick han bort till Ismael, och tog, utöfver de hustrur han tillförene hade, Mahalath, Ismaels Abrahams sons dotter, Nebajoths syster, till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Men Jacob for ut ifrå BerSaba, och reste till Haran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Och kom på ett rum, der blef han öfver nattena, förty solen var bärgad; och han tog en sten der på rummena, och lade honom under sitt hufvud, och lade sig i samma rum till att sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Och honom drömde, och si, en stege stod på jordene, och änden på honom tog upp i himmelen: Och si, Guds Änglar stego derpå upp och neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Och Herren stod der öfverst uppå, och sade: Jag är Herren, Abrahams och dins faders Gud, och Isaacs Gud: Det landet, som du ligger uppå, skall jag gifva dig och dine säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Och din säd skall varda såsom stoftet på jordene; och du skall varda utspridder vester ut, öster ut, norr ut, och söder ut, och genom dig och dina säd skola alla slägter på jordene varda välsignade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Och si, jag är med dig, och skall förvara dig ehvart du far, och skall föra dig åter i detta landet igen. Och skall icke öfvergifva dig, till des jag gör allt det jag dig sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Då nu Jacob vaknade upp af sin sömn, sade han: Visserliga är Herren i detta rum, och jag vistet icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Och fruktade han sig, och sade: Detta måste vara ett heligt rum; ty här bor visserliga Gud, och här är himmelens port.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Och Jacob stod upp om morgonen bittida, och tog stenen, som han hade lagt under sitt hufvud, och reste honom upp till en vård, och gjöt oljo der ofvan på.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Och kallade det rummet BethEl; men tillförene hette den staden Lus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Och Jacob gjorde ett löfte, och sade: Om så är, att Gud blifver med mig, och förvarar mig på denna vägen, som jag reser, och gifver mig bröd till att äta, och kläder till att klädas med;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'Och förer mig med strid åter hem igen till min fader; så skall Herren vara min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Och denne stenen, som jag upprest hafver till en vård, skall varda ett Guds hus: Och allt det du mig gifver, der vill jag gifva dig tionde af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Då hof Jacob sin fot upp, och gick in i det land, som öster ut ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Och såg sig om, och si, der var en brunn på markene; och si, tre hjordar med får der när; förty hjordarne måste dricka af brunnenom; och låg en stor sten för hålet på brunnenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Och de plägade der församla alla hjordarna, och vältra stenen ifrå brunnshålet, och vattna fåren, och lade så åter stenen för hålet i sitt rum igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Och Jacob sade till dem: Mine bröder, hvadan ären I? De svarade: Vi äre af Haran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Han sade till dem: Kännen I ock Laban Nahors son? De svarade: Vi känne honom väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Han sade: Går honom ock väl i hand? De svarade: Honom går väl i hand: Och si, der kommer hans dotter Rachel med fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Han sade: Det är ännu bittida dags, och är icke ännu tid drifva boskapen hem; vattner fåren, och går bort med dem i bet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'De svarade: Vi kunne icke, förra än du alle hjordarne komma tillsamman, och vi vältre stenen ifrå brunnshålet, och vattne så fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Medan han ännu talade med dem, kom Rachel med sins faders får; förty hon vaktade fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Då Jacob såg Rachel, Labans sins moderbroders dotter, och Labans sins moderbroders får, gick han till, och vältrade stenen ifrå hålet på brunnenom, och vattnade Labans sins moderbroders får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Och kysste Rachel; hof upp sina röst, och gret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Och kungjorde henne, att han var hennes faderbroders och Rebeckas son. Då lopp hon, och kungjorde det sinom fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Då nu Laban hörde om Jacob sin systerson, lopp han emot honom, och tog honom i famn, och kyssten, och hade honom in i sitt hus. Då förtäljde han honom allt, huru tillgått var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Då sade Laban till honom: Nu väl, du äst mitt ben och mitt kött: Och när han nu en månad långt hade varit när honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Sade Laban till Jacob: Ändock du äst min broder, skulle du fördenskull tjena mig för intet? Säg, hvad skall vara din lön?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Och Laban hade två döttrar; den äldsta het Lea, och den yngsta het Rachel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Men Lea var klenögd; Rachel var väl skapad, och hade ett dägeligit ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Till henne fick Jacob kärlek, och sade: Jag vill tjena dig i sju år för Rachel dina yngsta dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban svarade: Det är bättre jag gifver dig henne, än enom androm; blif när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Så tjente Jacob i sju år för Rachel; och tyckte honom det vara få dagar, så kär hade han henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Och Jacob sade till Laban: Få mig mina hustru; ty nu är tid, att jag kommer i säng med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Då böd Laban allt folket der omkring, och gjorde bröllop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Men om aftonen tog han Lea sina dotter, och hade henne in till honom: Och han låg när henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Och Laban fick sine dotter Lea Silpa till ena tjenstepigo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Om morgonen, si, då var det Lea: Och han sade till Laban: Hvi hafver du det gjort mig? Hafver jag icke tjent dig för Rachel? Hvi hafver du bedragit mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban svarade: Man gör icke så i våro lande, att man gifver ut den yngsta förr än den äldsta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Håll dessa veckona ut, så vill jag ock gifva dig denna med, för den tjenst, som du ännu skall tjena mig i androm sju år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jacob gjorde så, och höll de veckona ut; då gaf han honom Rachel sina dotter till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Och Laban gaf Rachel sine dotter Bilha till ena tjenstepigo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Så låg han ock när Rachel, och hade Rachel kärare än Lea; och tjente honom framdeles i de andra sju åren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Men då Herren såg, att Lea vardt vanvörd, gjorde han henne fruktsamma, och Rachel ofruktsamma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Och Lea vardt hafvande, och födde en son, den kallade hon Ruben, och sade: Herren hafver sett till min förtryckelse; nu varder min man hafvandes mig kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Och vardt åter hafvande, och födde en son, och sade: Herren hafver hört, att jag är vanvörd, och hafver desslikes denna gifvit mig; och kallade honom Simeon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Åter vardt hon hafvande, och födde en son, och sade: Nu varder min man åter hållandes sig till mig, ty jag hafver födt honom tre söner; derföre kallade hon honom Levi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Fjerde reso vardt hon hafvande, och födde en son, och sade: Nu vill jag tacka Herranom; derföre kallade hon honom Juda, och vände så igen att föda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Då Rachel såg, att hon födde Jacob intet, afundades hon vid sina syster, och sade till Jacob: Skaffa mig ock barn, eljest dör jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jacob vardt ganska vred på Rachel, och sade: Icke är jag Gud, som dig förmenar dins lifs frukt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Men hon sade: Si, der är min tjenstepiga Bilha: lägg dig när henne, att hon må föda i mitt sköt, och jag varder dock uppbyggd genom henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Och gaf honom så Bilha, sina tjenstepigo, till hustru, och Jacob lade sig när henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Och så vardt Bilha hafvande, och födde Jacob en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Då sade Rachel: Gud hafver dömt mina sak, och hört mina röst, och gifvit mig en son: Derföre kallade hon honom Dan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Åter vardt Bilha, Rachels tjensteqvinna, hafvande, och födde Jacob den andra sonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Då sade Rachel: Gud hafver omvändt det med mig och mine syster, och jag får öfverhandena: Och hon kallade honom Naphthali.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Då nu Lea såg, att hon hade vändt igen att föda, tog hon sina tjenstepigo Silpa, och gaf henne Jacob till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Så födde Silpa, Leas tjensteqvinna, Jacob en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Då sade Lea: Rustig; och kallade honom Gad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Derefter födde Silpa, Leas tjensteqvinna, Jacob den andra sonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Då sade Lea: Väl mig; förty döttrarna skola säga mig saliga: Och hon kallade honom Asser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben gick ut om hveteandena, och fann liljor på markene, och hade dem hem till sina moder Lea. Då sade Rachel till Lea: Gif mig en del af din sons liljor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Hon svarade: Hafver du icke nog, att du hafver tagit min man bort, och vill desslikes taga min sons liljor? Rachel sade: Nu väl, låt honom denna nattena sofva när dig, för dins sons liljor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Då nu Jacob kom om aftonen af markene, gick Lea ut emot honom, och sade: När mig skall du ligga; förty jag hafver köpt dig för mins sons liljor: Och han låg när henne de nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Och Gud hörde Lea, och hon vardt hafvande, och födde Jacob den femte sonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Och sade: Gud hafver lönt mig, för det jag gaf minom manne mina tjenstepigo; och hon kallade honom Isaschar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Åter vardt Lea hafvande, och födde Jacob den sjette sonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Och sade: Gud hafver väl försett mig: Nu varder åter min man boendes när mig, ty jag hafver födt honom sex söner: Och kallade honom Sebulon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Derefter födde hon ena dotter, och kallade henne Dina.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Men Gud tänkte på Rachel, och hörde henne, och gjorde henne fruktsamma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Då vardt hon hafvande, och födde en son, och sade: Gud hafver min smälek ifrå mig tagit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Och kallade honom Joseph, och sade: Herren gifve mig ännu en son härtill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Då nu Rachel hade födt Joseph, sade Jacob till Laban: Låt mig färdas, och resa hem till mitt, och i mitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gif mig mina hustrur och min barn, som jag hafver tjent dig före, att jag må färdas; förty du vetst, hvad jag hafver gjort dig för en tjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laban sade till honom: Kan jag icke finna nåd för din ögon? Jag förnimmer, att Herren hafver välsignat mig för dina skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Säg, hvad lön jag skall gifva dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Men han sade till honom: Du vetst, huru jag hafver tjent dig, och hvad boskap du hafver under mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Du hade litet, förra än jag kom, men nu äst du riker vorden; och Herren hafver välsignat dig för mina skull: Och nu, när skall jag ock något bestyra till mitt hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Laban sade: Hvad skall jag då gifva dig? Jacob sade: Du skall allsintet gifva mig; utan om du vill göra mig det jag säger, så skall jag ännu beta och vakta din får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Jag vill i dag gå igenom alla dina hjordar, och skilj du derifrån all fläckot och brokot får, och all svart får ibland lamben och kiden: Hvad nu sedan brokot och fläckot blifver, det skall vara min lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Så varder mig min rättfärdighet betygandes i dag eller morgon, när dertill kommer, att jag skall taga min lön af dig, alltså, att hvad som icke fläckot eller brokot, eller ock hvad svart är ibland lamben och kiden, det vare en tjufnad med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Då sade Laban: Jag är till frids, blifve som sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Och han skilde i den dagen ut spräcklota och brokota bockar, och all fläckot och brokot kid, der som ju något hvitt var uppå, och allt det svart var ibland lamben; och fick det sin barn i händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Och lät blifva tre dagsleder långe emellan sig och Jacob. Så bette Jacob det öfver var af Labans hjord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Men Jacob tog gröna aspekäppar, hassel och castaneen, och barkade hvita ränder deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Och lade käpparna, som han barkat hade, i dryckehoar för hjordarna, som der komma måste och vattnas, att de skulle hafvande varda, när de kommo till att dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Alltså vordo hjordarne hafvande öfver käpparna, och födde fläckot, spräcklot och brokot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Då afskiljde Jacob lamben, det icke brokot, och allt det svart var, och lät dem in till Labans hjord, och gjorde sig en egen hjord, den lät han icke till Labans hjord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Men när den tidfödde hjorden lopp, lade han käpparna i hoar för hjordens ögon, så att de vordo hafvande öfver käpparna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Men när de senfödda lupo, lade han dem intet deruti. Så vordo då de senfödlingar Labans och de tidfödlingar Jacobs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Deraf vardt mannen öfvermåttan riker, så att han hade mycken får, tjenarinnor och tjenare, camelar och åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Och kom för honom Labans barns tal, att de sade: Jacob hafver kommit allt vår faders gods till sig; och af vår faders gods hafver han sådana rikedomar samkat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Och Jacob såg på Labans ansigte, och si, det var icke sådana emot honom, som i går och förrgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Och Herren sade till honom: Far åter in i dina fäders land, och till dina fränder: Jag vill vara med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Då sände Jacob, och lät kalla Rachel och Lea ut på markena till sin hjord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Och sade till dem: Jag ser edars faders ansigte, att det är icke sådana emot mig, såsom i går och i förrgår: Men mins faders Gud hafver varit med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Och I veten, att jag hafver tjent edar fader af alla mina krafter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Och han hafver besvikit mig, och nu tio resor förvandlat min lön; men Gud hafver honom det icke tillstadt, att han skulle göra mig skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'När han sade: De brokota skola vara din lön, så bar hela hjorden brokot; men när han sade: De spräcklota skola vara din lön, så bar hela hjorden spräcklot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Så hafver Gud vändt edars faders gods ifrå honom, och gifvit det mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Ty när aflotiden kom, hof jag upp min ögon, och såg i dröm, och si, gumrarne sprungo på de spräcklota, fläckota och brokota hjordarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Och Guds Ängel sade till mig i drömmenom: Jacob; och jag svarade: Här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Men han sade: Häf upp din ögon, och si, gumrarne springa på de spräcklota, fläckota och brokota fåren; förty jag hafver allt sett, hvad Laban gör dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Jag är Gud i BethEl, der du hafver smort stenen, och gjort mig der ett löfte: Nu gör dig redo, och far utaf detta landet, och far in i ditt födsloland igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Då svarade Rachel och Lea, och sade till honom: Vi hafve hvarken del eller arf i vårs faders huse mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Hafver han dock hållit oss lika som främmande; förty han hafver sålt oss, och förtärt vårt värd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Derföre hafver Gud frånvändt vårom fader hans rikedomar till oss och vår barn. Allt det Gud dig nu sagt hafver, det gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Så gjorde Jacob sig redo, och satte sin barn och hustrur på camelar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Och förde bort all sin boskap, och alla sina håfvor, som han hade förvärfvat i Mesopotamien; på det han skulle komma till sin fader Isaac i Canaans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Men Laban var gången bort till att klippa sin hjord. Och Rachel stal sins faders beläter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Alltså stal Jacob Laban af Syrien hjertat, att han honom icke tillsade, då han flydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Så flydde han, och allt det hans var gjorde sig redo, och for öfver älfvena, och stämde åt Gileads berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'På tredje dagen vardt det Laban sagdt, att Jacob flydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Och han tog till sig sina bröder, och jagade efter honom sju dagsleder; och hinde honom på det berget Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Men Gud kom till Laban af Syrien i dröm om nattena, och sade till honom: Förvara dig, att du intet talar till Jacob annat än godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Och Laban nalkades intill Jacob. Men Jacob hade uppslagit sin tjäll på bergena: Och Laban med sina bröder slog desslikes sin tjäll upp på bergena Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Då sade Laban till Jacob: Hvad hafver du gjort, att du hafver stulit mitt hjerta, och bortfört mina döttrar, lika som de der med svärd gripna vore?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Hvarföre hafver du det fördolt, att du skulle fly, och hafver stulit dig ifrå mig, och hafver icke tillsagt, att jag måtte hafva ledsagat dig med fröjd, med sjungande, med bungande och harpande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Och hafver icke låtit mig kyssa min barn och döttrar? Du hafver dårliga gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Och jag hade väl så mycken magt, att jag kunde göra eder ondt; men edars faders Gud sade till mig i går: Förvara dig, att du intet talar till Jacob, utan godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Och medan du ju ville fara, och åstundade så mycket efter dins faders hus, hvarföre hafver du då stulit mig mina gudar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jacob svarade, och sade till Laban: Jag fruktade, att du skulle hafva tagit dina döttrar ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Men när hvilkom du finner dina gudar, han må dö här för våra bröder. Gör efter ditt när mig, och tag det. Men han visste icke, att Rachel hade stulit dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Då gick Laban in i Jacobs tjäll och Leas, och båda tjensteqvinnornas, och fann intet; och gick ut af Leas tjäll i Rachels tjäll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Då tog Rachel beläten, och lade dem under camelahalmen, och satte sig derpå. Men Laban ransakade öfver hela tjället, och fann intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Då sade hon till sin fader: Min herre, var icke vred; förty jag kan icke stå upp emot dig; förty det går med mig efter qvinno sätt. Så sökte han, och fann intet beläten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Och Jacob vardt vred, och kifvade med Laban, och sade till honom: Hvad hafver jag misshandlat eller syndat, att du äst så heter på mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Du hafver ransakat all min boting, hvad hafver du funnit af din boting? Lägg det der för mina och dina bröder, att de döma emellan oss båda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Tjugu år hafver jag varit när dig; din får och getter hafva icke varit ofruktsamma, vädrarna af din hjord hafver jag icke ätit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Det af djuren rifvit var, hade jag icke till dig, jag måste det betala: Du äskade det af mine hand, ehvad det var dag eller natt mig ifrå stulit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Om dagen var jag vanmägtig för hetas skull, om nattena för köld; och min sömn vek ifrå min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Så hafver jag i tjugu år tjent i ditt hus; fjorton för dina döttrar, och sex för din hjord: Och du hafver tio resor förvandlat min lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Hvar mins faders Abrahams Gud och Isaacs fruktan icke hade varit på mina sido, du hade låtit mig gå blottan ifrå dig. Men Gud hafver ansett min förtryckelse och arbete, och straffade dig i går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Laban svarade, och sade till Jacob: Döttrarna äro mina döttrar, och barnen äro mina barn, och hjordarna äro mine hjordar, och allt det du ser är mitt: Hvad kan jag i dag göra minom döttrom, eller deras barnom, som de födt hafva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Så kom nu och låt oss göra ett förbund, jag och du; som skall vara ett vittnesbörd emellan mig och dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Då tog Jacob en sten, och reste honom upp till en vård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Och sade till sina bröder: Hemter upp stenar; och de togo stenar, och gjorde ena rösjo, och åto uppå samma rösjo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Och Laban kallade henne Jegar Sahaduta; men Jacob kallade henne Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Då sade Laban: Denna stenrösjan vare i dag vittnesbörd emellan mig och dig; deraf kallar man henne Gilead:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Och vare en vård; ty han sade: Herren se härtill emellan mig och dig, då vi komme ifrå hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Hvar du besvärar mina döttrar, eller tager andra hustrur deröfver: Här är ingen menniska med oss; men si, Gud är vittne emellan mig och dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Och Laban sade ytterligare till Jacob: Si, detta är stenrösjan, och detta är vården, som jag upprest hafver emellan mig och dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Samma rösjan vare vittne, och vården vare desslikes vittne, om jag far här öfver till dig, eller du far öfver denna rösjan och vården till mig, till att göra skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Abrahams Gud och Nahors Gud, och deras fäders Gud, vare domare emellan oss. Och Jacob svor honom, vid Isaacs sins faders fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Och Jacob offrade offer på bergena, och böd sina bröder att de skulle äta bröd. Och då de hade ätit, blefvo de på bergena öfver nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Men om morgonen stod Laban bittida upp, kysste sin barn och döttrar; välsignade dem, och for sina färde, och kom hem till sitt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Men Jacob for sin väg, och Guds Änglar mötte honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Och då han såg dem, sade han: Detta äro Guds härar; och kallade det rummet Mahanaim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Men Jacob sände båd fram för sig till sin broder Esau in uti Seirs land, i Edoms ängd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Och befallte dem, och sade: Så säger minom herra Esau: Din tjenare Jacob låter säga dig, jag hafver varit ute när Laban, och hafver allt härtill varit ibland främmande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Och hafver fä och åsnor, får, tjenare och tjenarinnor; och hafver utsändt, och låtit dig minom herra det bebåda, på det jag måtte finna nåd för din ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Boden kommo igen till Jacob, och sade: Vi kommom till din broder Esau, och han reser emot dig med fyrahundrade män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Då fruktade Jacob storliga, och var förfärad: Och skifte folket, som var när honom, och får, och fä, och camelar, i två skarar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Och sade: Om Esau kommer på den ena skaran, och står honom, så må den andre undkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Ytterligare sade Jacob: Gud, mins faders Abrahams Gud, mins faders Isaacs, Herre, du som till mig sagt hafver: Far åter in i ditt land till dina fränder, jag vill göra dig godt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Jag är för ringa till all den barmhertighet och all den trohet, som du med dinom tjenare gjort hafver; förty jag hade icke mer än denna stafven, då jag gick öfver denna Jordanen, och nu är jag till två skarar vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Hjelp mig utu mins broders hand, utu Esaus hand; ty jag fruktar för honom; att han icke kommer, och står mig både mödrar och barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Du hafver sagt: Jag vill göra dig godt, och göra din säd som sanden i hafvet, den så mycken är, att han ej kan räknas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Och han blef der den nattena, och tog af thy han för handena hade, skänker till sin broder Esau.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Tuhundrade getter, tjugu bockar, tuhundrade får, tjugu vädrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Och tretio däggande camelar med deras föl, fyratio kor, och tio oxar; tjugu åsninnor, med tio föl;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Och fick dem under sina tjenares händer, ju hvar hjorden för sig, och sade till dem: Går fram för mig, och låter vara rum emellan den ena hjorden efter den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Och böd den första, och sade: När min broder Esau möter dig, och frågar dig: Hvem hörer du till, och hvart vill du, och hvem hörer det till, som du drifver för dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Skall du säga: Det hörer dinom tjenare Jacob till; han sände sinom herra Esau skänker, och kommer härefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Så böd han ock den andra, och den tredje, och allom dem som gingo efter hjorden, och sade: Som jag hafver sagt eder, så säger till Esau, när I finnen honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Och säger ju det med: Si, Jacob din tjenare är efter oss. Förty han tänkte, jag vill blidka honom med den skänken, som går för mig; sedan vill jag se honom; kan hända att han undfår mig väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Så gingo skänkningarna fram före honom; men han blef den nattena i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Och stod upp om nattena, och tog sina två hustrur, och de två tjensteqvinnorna, och sin ellofva barn, och for till vadet Jabbok:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Tog dem och förde dem öfver älfvena, så att det han hade, kom öfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Och han blef på den sidone allena. Då brottades en man med honom till dess morgonrodnen uppgick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Och då han såg, att han icke kunde öfvervinna honom, rörde han hans höftes sena, och straxt förtvinade hans höftes sena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Och han sade: Låt mig gå, ty morgonrodnen går upp; men han svarade: Jag släpper dig icke, med mindre du välsignar mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Han sade: Huru heter du? Han svarade: Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Han sade: Du skall icke mer heta Jacob, utan Israel. Förty du hafver med Gud och menniskor kämpat, och hafver fått öfverhandena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Och Jacob frågade honom, och sade: Huru heter du? Men han sade: Hvi frågar du, huru jag heter? Och han välsignade honom der sammastädes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Och Jacob kallade det rummet Pnuel; ty jag hafver sett Gud under ansigtet, och min själ är frälst vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Och som han kom fram om Pnuel, gick honom solen upp, och han haltade i sine höft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Fördenskull äta Israels barn inga höftsene ännu i dag, derföre, att Jacobs höftsena rörd vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jacob hof upp sin ögon, och såg sin broder Esau komma med fyrahundrade män. Och skifte sin barn till Lea, och till Rachel, och till båda tjensteqvinnorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Och skickade tjensteqvinnorna med deras barn främst; och Lea med hennes barn dernäst; och Rachel med Joseph efterst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Och han gick fram för dem, och bugade sig sju resor ned på jordena, till dess han kom fram till sin broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Men Esau lopp emot honom, och tog honom i famn, och fick honom om halsen, och kysste honom; och de greto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Och hof upp sin ögon, och såg qvinnorna med barnen, och sade: Ho äro desse med dig? Han svarade: Det äro barnen, som Gud dinom tjenare beskärt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Och tjensteqvinnorna gingo fram med deras barn, och bugade sig för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Lea gick ock fram med sin barn, och bugade sig för honom. Sedan gick Joseph och Rachel fram, och bugade sig ock för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Och han sade: Hvad vill du med allan den skaran, som jag hafver mött? Han svarade: Att jag måtte finna nåd för minom herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Esau sade: Jag hafver nog, min broder; behåll det du hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jacob svarade: Ack nej! hafver jag funnit nåd för dig, så tag min skänk af mine hand; förty jag såg ditt ansigte, lika som jag hade sett Guds ansigte; och tag det täckeliga af mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Tag den välsignelsen, som jag hafver fört till dig; ty Gud hafver mig det beskärt, och jag hafver all ting nog. Så nödgade han honom, till dess han anammade det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Och han sade: Låt oss fara framåt, och resa, jag vill fara med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Men han sade till honom: Min herre, du vetst att jag hafver späd barn när mig, dertill får och fä, som än äro unge; när de en dag för hastigt drifne vordo, dödde mig hela hjorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Min herre fare fram före åt för sin tjenare: Jag vill sakta följa, efter som boskapen och barnen gå kunna, till dess jag kommer till min herra i Seir.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Esau sade: Så vill jag dock låta blifva när dig något af folket, som med mig är. Han svarade: Hvad görs det behof? Låt mig man finna nåd för minom herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Så for Esau den dagen tillbaka sin väg åt Seir.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Och Jacob for till Succoth, och byggde sig ett hus, och gjorde hyddor till sin boskap. Deraf heter det rummet Succoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Derefter kom Jacob till Salem, till den staden Sichem, som ligger i Canaans lande, sedan han var kommen utaf Mesopotamien, och gjorde sitt lägre för stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Och köpte ett stycke åker af Hemors Sichems faders barnom, för hundrade penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Der slog han upp sin tjäll, och uppreste der ett altare, och åkallade dens starka Israels Guds namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Men Dina Leas dotter, den hon Jacob födt hade, gick ut till att bese dess landsens döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Då Sichem, Hemors Heveens son, som var dess landsens herre, såg henne, tog han henne, och belägrade henne, och förkränkte henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Och hon låg honom hårdt på hjertat, och han hade pigona kära, och talade ljufliga med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Och Sichem sade till sin fader Hemor: Tag mig den pigona till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Och Jacob förnam, att hans dotter Dina var skämd, och hans söner voro med boskapenom ute på markene: Och Jacob tigde till dess de kommo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Då gick Hemor Sichems fader ut till Jacob, till att tala med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'I det kommo Jacobs söner af markene; och då de det hörde, förtröt det männerna, och vordo ganska vrede, att han hade gjort en dårskap i Israel, och belägrat Jacobs dotter; ty det var icke rätt gjordt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Då talade Hemor med dem, och sade: Mins sons Sichems hjerta trängtar efter edra dotter; käre, gifver honom henne till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Befrynder eder med oss; gifver oss edra döttrar, och tager I våra döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Och bor när oss: Landet skall stå eder öppet; bygger och bruker, och bor derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Och Sichem sade till hennes fader och bröder: Låter mig finna nåd när eder, hvad I mig sägen, det vill jag gifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Begärer man troliga af mig morgongåfvor och skänker, jag vill gifva, som I begären; gifver mig allenast pigona till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Då svarade Jacobs söner Sichem, och hans fader Hemor, och talade bedrägeliga, derföre, att deras syster Dina var skämd:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Och sade till dem: Vi kunne det icke göra, att vi skole gifva våra syster enom oomskornom manne; ty det vore oss en skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Dock likväl vilje vi vara eder till viljes, om I varden oss like, och allt mankön ibland eder varder omskoret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Då vilje vi gifva eder våra döttrar, och taga oss edra döttrar, och bo när eder, och vara ett folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Men hvar I icke viljen lyda oss, och omskära eder, så vilje vi taga våra dotter, och fara vår väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Det talet behagade Hemer och hans son väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Och den unge mannen fördröjde intet att göra så; förty han hade lust till Jacobs dotter, och han var härlig hållen öfver alla i hans faders huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Så gingo Hemor och hans son Sichem i stadsporten, och talade med borgarena i stadenom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Desse män äro fridsamme när oss, och vilja bygga och bo i landena. Så är nu landet vidt begripet; vi vilje taga oss deras döttrar, och gifva dem våra döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Men då vilja de vara oss till viljes, så att de bo när oss, och varda ett folk med oss, om vi omskäre allt det som mankön är ibland oss, såsom de omskorne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Deras boskap och ägodelar, och allt det de hafva, blifver vårt, om vi eljest blifvom dem till viljes, så att de bo när oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Och de lydde Hemor och Sichem hans sone, alle de som genom hans stadsport ut och in gingo, och omskoro allt det som mankön var, det som i deras stad ut och in gick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Och på tredje dagenom, då det värkte dem, togo de två Jacobs söner, Simeon och Levi, Dinas bröder, hvardera sitt svärd, och gingo dristeliga in i staden, och slogo ihjäl allt det som var mankön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Och slogo också ihjäl Hemor och hans son Sichem med svärds ägg, och togo sina syster Dina utaf Sichems huse, och gingo sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Då kommo Jacobs söner öfver de slagna, och skinnade staden, derföre, att de skämt hade deras syster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Och togo deras får, fä, åsnar, och hvad i stadenom och på markene var:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Och alla deras håfvor; all barn och qvinnor togo de till fångar, och skinnade allt det i husen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Och Jacob sade till Simeon och Levi: I hafven åstadkommit, att jag blifver illa känder för alla dessa lands inbyggare, de Cananeer och Phereseer: Och jag är en ringa hop; när de nu församla sig öfver mig, så slå de mig ihjäl, så varder jag om intet gjord med mino huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Men de svarade: Skulle de då handla med våra syster, såsom med ene sköko?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Och Gud sade till Jacob: Gör dig redo, och far till BethEl, och bo der, och bygg der ett altare Gudi som dig syntes, då du flydde för dinom broder Esau.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Då sade Jacob till sitt hus, och till alla de som med honom voro: Lägger ifrån eder de främmande gudar, som äro ibland eder, och renser eder, och förvandler edor kläder:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Och görom oss redo att fara till BethEl, att jag må göra der ett altare Gudi, den mig hört hafver i min bedröfvelses tid, och hafver varit med mig på vägenom, som jag rest hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Då fingo de honom alla de främmande gudar, som voro under deras händer, och deras örnaringar; och han grof dem under ena ek, som stod vid Sichem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Och for ut: Och en Gudsfruktan kom öfver de städer, som lågo der omkring, att de icke foro efter Jacobs söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Så kom Jacob till Lus i Canaans land, som kallas BethEl, med allt det folk, som med honom var:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Och byggde der ett altare, och kallade det rummet ElBethEl, efter det Gud vardt honom der uppenbarad, då han flydde för sinom broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Då dödde Debora Rebeckas amma, och vardt begrafven nedanför BethEl, under ena ek, hvilken vardt kallad gråtoek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Och Gud syntes åter Jacob, sedan han var kommen utaf Mesopotamien, och välsignade honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Och sade till honom: Du heter Jacob; men du skall icke mer heta Jacob, utan Israel skall du heta: Och så kallade man honom Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Och Gud sade till honom: Jag är den allsmägtige Gud; var fruktsam, och föröka dig: Folk och folks skarar skola komma utaf dig, och Konungar skola komma utaf dina länder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Och det landet, som jag Abraham och Isaac gifvit hafver, skall jag gifva dig, och skall det gifva dine säd efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Och så for Gud upp ifrå honom, ifrå det rummet, der han med honom talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Men Jacob reste upp en stenvård på det rummet, der han med honom talat hade: Och gjöt drickoffer deruppå, och begjöt honom med oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Och Jacob kallade det rummet, der Gud hade talat med honom, BethEl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Och han for ifrå BethEl: Och som ännu ett litet stycke vägs var till Ephrath, då födde Rachel, och födslan var henne svår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Men då det vardt henne så svårt i födslone, sade Jordgumman till henne: Frukta dig icke; förty denna sonen skall du ock hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Men då själen utgick, att hon dö måste, kallade hon honom BenOni; men hans fader kallade honom BenJamin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Så dödde Rachel, och vardt begrafven vid vägen till Ephrath, som nu heter BethLehem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Och Jacob reste upp en vård öfver hennes graf: Der sammastädes är Rachels grafvård än i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Och Israel for ut, och slog upp ett tjäll på hinsidon vid det tornet Eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Och det begaf sig, då Israel bodde der i landet, gick Ruben bort och lade sig när Bilha, sins faders frillo: Och det kom för Israel. Men Jacob hade tolf söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Leas söner voro desse: Ruben, Jacobs förstfödde son, Simeon, Levi, Juda, Isaschar och Sebulon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Rachels söner voro: Joseph och BenJamin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Bilhas Rachels tjensteqvinnos söner: Dan och Naphthali.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Silpas Leas tjensteqvinnos söner: Gad och Asser. Desse äro Jacobs söner, som honom födde voro i Mesopotamien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Och Jacob kom till sin fader Isaac till Mamre i hufvudstaden, som heter Hebron, der Abraham och Isaac hade varit främlingar uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Och Isaac vardt hundrade och åttatio år gammal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Och vardt sjuk, och dödde, och vardt samlad till sitt folk, gammal och mätt af lefvande: Och hans söner Esau och Jacob begrofvo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Detta är Esaus slägte, som kallas Edom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau tog hustrur af Canaans döttrar: Ada Elons Hetheens dotter, och Aholibama Anas dotter, Zibeons Heveens dotters.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Och Basmath Ismaels dotter, Nebajoths syster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Och Ada födde Esau Eliphas. Men Basmath födde Reguel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Aholibama födde Jeus, Jaelam och Korah. Desse äro Esaus barn, som honom födde voro i Canaans lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Och Esau tog sina hustrur, söner och döttrar, och alla sins huses själar; sina håfvor, och allan boskapen med alla ägodelar, som han förvärfvat hade i Canaans lande: Och for uti ett land, ifrå sin broder Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Förty deras ägodelar voro så stora, att de kunde icke bo med hvarannan: Och landet, der de uti främlingar voro, kunde icke fördraga dem, för deras stora ägodelars skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Så bodde då Esau på Seirs berg: Och denne Esau är Edom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Detta är Esaus slägte, af hvilkom de Edomeer komne äro på Seirs berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Och så heta Esaus barn: Eliphas Ada son, Esaus hustrus; Reguel Basmaths son, Esaus hustrus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Men Eliphas söner voro desse: Theman, Omar, Zepho, Gatham och Kenas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Och Thimna var Eliphas Esau sons frilla; hon födde Amalek. Desse äro de barn af Ada, Esaus hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Men Reguels barn äro desse: Nahath, Serah, Samma, Missa. Desse äro de barn af Basmath, Esaus hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Men de barn af Aholibama, Esaus hustru, Anas dotter, Zibeons dotters, äro desse, dem hon födde Esau: Jeus, Jaelam och Korah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Desse äro de Förstar ibland Esaus barn: Eliphas barn, den första Esaus sons, voro desse: den Försten Theman, den Försten Omar, den Försten Zepho, den Försten Kenas,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Den Försten Korah, den Försten Gatham, den Försten Amalek. Desse äro de Förstar af Eliphas i Edoms lande; och äro barn af Ada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Och desse äro Reguels barn, Esau sons: Den Försten Nahath, den Försten Serah, den Försten Samma, den Försten Missa. Desse äro de Förstar af Reguel uti de Edomeers lande; och äro barn af Basmath, Esaus hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Desse äro barn af Aholibama, Esaus hustru: Den Försten Jeus, den Försten Jaelam, den Försten Korah. Desse äro de Förstar af Aholibama Anas dotter, Esaus hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Desse äro Esaus barn, och deras Förstar; han är Edom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Men de barn af Seir den Horeen, som i landena bodde, äro desse: Lotan, Sobal, Zibeon, Ana,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Ezer och Disan. Desse äro de Förstar ibland de Horeer, alle Seirs barn i Edoms lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Men Lotans barn voro desse: Hori och Hemam; och Lotans syster het Thimna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Sobals barn voro desse: Alvan, Manahat, Ebal, Sepho och Onam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Zibeons barn voro: Aja och Ana: Denne är den Ana, som i öknene påfann mular, då han vaktade sins faders Zibeons åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Men Anas barn voro: Dison och Aholibama, det är Anas dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Disons barn voro: Hemdan, Esban, Jithran och Cheran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Ezers barn voro: Bilhan, Saavan och Akan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Disans barn voro: Uz och Aran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Desse äro de Förstar ibland de Horeer: Den Försten Lotan, den Försten Sobal, den Försten Zibeon, den Försten Ana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Den Försten Dison, den Försten Ezer, den Försten Disan. Desse äro de Förstar ibland de Horeer, de som regerade i Seirs lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Men de Konungar, som i Edoms lande regerade, förra än Israels barn Konungar hade, äro desse:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela var Konung i Edom, Beors son; och hans stad het Dinhaba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Och då Bela blef död, vardt Jobab Konung i hans stad, Seras son af Bozra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Då Jobab blef död, vardt Husam utaf de Themaneers lande Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Då Husam blef död, vardt Konung i hans stad Hadad Bedads son, den som slog de Midianiter på de Moabiters mark; och hans stad het Avith.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Då Hadad blef död, vardt Samla af Masreka Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Då Samla blef död, vardt Konung i hans stad Saul af Rehoboth vid älfvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Då Saul blef död, vardt Baalhanan Achbors son Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Då Baalhanan Achbors son blef död, vardt Hadar Konung i hans stad: Och hans stad het Pagu; och hans hustru het Mehetabeel, Matreds dotter, och Mesahabs dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Alltså heta de Förstar af Esau i deras slägter, rummom och namnom: Den Försten Thimna, den Försten Alva, den Försten Jetheth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Den Försten Aholibama, den Försten Ela, den Försten Pinon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Den Försten Kenas, den Försten Theman, den Försten Mibzar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Den Försten Magdiel, den Försten Iram. Desse äro de Förstar i Edom, såsom de bott hafva uti deras arfvelande. Och Esau är fadren till de Edomeer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Men Jacob bodde i de landena, der hans fader var en främling uti, nemliga i Canaans lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Och detta är Jacobs slägt: Joseph var sjutton år gammal, då han vardt en herde öfver hjorden med sina bröder; och pilten var när Bilhas och Silpas sins faders hustrurs barnom; och han sade för deras fader, hvilket ondt rykte öfver dem var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Men Israel hade Joseph kärare än alla de andra sin barn, efter han hade födt honom i ålderdomen: Och gjorde honom en brokot kjortel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Då nu hans bröder sågo, att deras fader hade honom kärare än alla hans bröder, vordo de honom hätske, och kunde icke tala honom ett vänligit ord till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Derutöfver hade Joseph ena reso en dröm, och sade sina bröder deraf. Då blefvo de honom ännu hätskare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Ty han sade till dem: Käre, hörer hvad mig hafver drömt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Mig tyckte vi bundom kärfvar på markene, och min kärfve reste sig upp och stod; och edre kärfvar der omkring bugade sig för min kärfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Då sade hans bröder till honom: Skulle du varda vår Konung, och råda öfver oss? Och vordo honom ändå hätskare för hans dröm och hans tals skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Och han hade ännu en annan dröm, den förtäljde han sina bröder, och sade: Si, jag hafver ännu haft en dröm: Mig tyckte, att solen och månen och ellofva stjernor bugade sig för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Och då det hans fader och hans bröder sagdt vardt, straffade honom hans fader, och sade till honom: Hvad är det för en dröm, som dig hafver drömt? Skall jag och din moder och dine bröder komma, och falla ned på jordena för dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Och hans bröder afundades vid honom. Men hans fader behöll dessa ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Då nu hans bröder gingo bort till att beta deras faders boskap i Sichem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Sade Israel till Joseph: Vakta icke dine bröder boskapen i Sichem? Kom, jag vill sända dig till dem. Han sade: Här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Och han sade: Gack bort och se till, om det står väl till med dina bröder och boskapenom; och säg mig igen, huru det hafver sig. Och han sände honom utaf den dalenom Hebron, att han skulle gå till Sichem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Då fann honom en man, der han for vill på markene. Han frågade honom, och sade: Hvem söker du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Han svarade: Jag söker mina bröder: Käre, säg mig, hvarest de vakta hjorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Mannen sade: De äro hädan farne; ty jag hörde, att de sade: Låt oss gå till Dothan. Då drog Joseph efter sina bröder, och fann dem i Dothan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Som de nu långt ifrå fingo se honom, förra än han kom när intill dem, rådslogo de till att döda honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Och sade inbördes: Si, drömmaren kommer här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Så kommer nu, och låter oss slå honom ihjäl och kasta honom i ena grop; och säga, att ett ondt djur hafver ätit upp honom: Så får man se, hvad hans drömmar äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'När Ruben hörde det, ville han frälsa honom af deras händer, och sade: Låter oss icke slå ena själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Och ytterligare sade Ruben till dem: Låter oss icke utgjuta blod: Utan låt oss kasta honom i den gropena, som är i öknene, och icke komma händer vid honom. Men han ville hafva frälst honom utu deras hand, att han måtte hafva haft honom till sin fader igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Då nu Joseph kom till sina bröder, afklädde de honom hans kjortel, med den brokota kjortelen, som han hade uppå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Och togo honom, och kastaden i ena grop; men gropen var tom, och intet vatten deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Och de satte sig ned till att äta. I det hofvo de sin ögon upp, och sågo en hop Ismaeliter komma ifrå Gilead med deras camelar; de förde kryddor, balsam och mirrham, och foro ned uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Då sade Juda till sina bröder: Hvad hjelper det oss, att vi dräpe vår broder, och fördölje hans blod?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommer, och låter oss sälja honom de Ismaeliter, att våra händer icke förtaga sig på honom; ty han är vår broder, vårt kött och blod. Och de lydde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Och då de Midianitiske köpmännerne foro der fram, drogo de honom upp af gropene, och sålde honom de Ismaeliter för tjugu silfverpenningar: De förde honom in i Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Då nu Ruben kom åter till gropena, och fann icke Joseph derinne, ref han sin kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Och kom åter till sina bröder, och sade: Pilten är icke der; hvart skall jag?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Då togo de Josephs kjortel, och slagtade en bock, och indoppade kjortelen i blodet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Och sände den brokota kjortelen bort, och läto bära honom till deras fader, och sade: Denna hafvom vi funnit: Se, om det är dins sons kjortel eller ej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Men han kände honom, och sade: Det är mins sons kjortel. Ett ondt djur hafver ätit upp honom; ett vilddjur hafver rifvit Joseph.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Och Jacob ref sin kläder, och svepte en säck om sina länder, och sörjde sin son långan tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Och alle hans söner och döttrar gingo till, att de skulle hugsvala honom; men han ville icke låta hugsvala sig, och sade: Jag varder med sorg nederfarande i grafvena till min son. Och hans fader gret honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Men de Midianiter sålde honom in i Egypten Potiphar, Pharaos hofmästare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Det begaf sig på samma tiden, att Juda for neder ifrå sina bröder, och gaf sig till en man i Adullam, som het Hira.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Och Juda såg der en Cananeisk mans dotter, han het Sua; och tog henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Och då han belåg henne, vardt hon hafvande, och födde en son, den kallade hon Er.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Och hon vardt åter hafvande, och födde en son, den kallade hon Onan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Åter födde hon en son, honom kallade hon Sela. Och han var i Chesib, när hon den födde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Och Juda gaf sinom första sone Er ena hustru, som het Thamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Men Er Juda förstfödde son var arg för Herranom; derföre dödade Herren honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Då sade Juda till sin son Onan: Lägg dig när dins broders hustru, och tag henne till ägta, att du uppväcker dinom broder säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Men då Onan visste, att säden icke skulle vara hans egen, då han låg när sins broders hustru, lät han det falla uppå jordena, och förderfvade det, att han icke skulle gifva sinom broder säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Då misshagade Herranom det onda han gjorde, och dödade honom och.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Då sade Juda till sina sonahustru Thamar: Blif en enka i dins faders huse, så länge Sela min son varder stor; förty han tänkte, att han tilläfventyrs måtte ock så dö såsom hans broder. Så gick Thamar bort, och blef i sins faders huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Då nu månge dagar förledne voro, dödde Sua dotter, Judas hustru. Och sedan Juda utsörjt hade, gick han upp till att klippa sin får i Thimnath, med sin herda Hira af Adullam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Då vardt Thamar sagdt: Si, din svär går upp till Thimnath till att klippa sin får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Då lade hon af sin enkokläder, som hon drog, dokade sig, och förhöljde sig, och satte sig ut för porten på vägen emot Thimnath; förty hon såg, att Sela var stor vorden, och hon var icke gifven honom till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Då nu Juda såg henne, mente han det hade varit en sköka; förty hon hade förhöljt sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Och han vek af vägenom till henne, och sade: Käre, låt mig ligga när dig; ty han visste icke, att det var hans sonahustru. Hon svarade: Hvad vill du gifva mig, att du ligger när mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Han sade: Jag vill sända dig en bock ifrå hjordenom. Hon svarade: Gif mig en pant, så länge du sänder mig honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Han sade: Hvad vill du jag skall gifva dig för en pant? Hon svarade: Din ring, och din hufvudbonad, och din staf, som du hafver i händerna. Det gaf han henne, och låg när henne, och hon vardt hafvande af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Och hon stod upp, och gick dädan, och lade doken af, och tog sin enkokläder uppå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Men Juda sände bocken med sin herde af Adullam, att han skulle taga igen panten ifrå qvinnone; och han fann henne intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Då frågade han folket, som bodde vid det rummet, och sade: Hvarest är den skökan, som satt ute på vägenom? De svarade: Ingen sköka hafver der varit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Och då han kom åter till Juda, och sade: Jag hafver intet funnit henne; dertill säger folket, som der bor, att der hafver ingen sköka varit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juda sade: Hafve sig det, att vi icke tilläfventyrs skulle komma på skam; ty jag hafver sändt bocken, men du hafver icke funnit henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Tre månader derefter vardt det Juda sagdt: Din sonahustru Thamar hafver bolat; och si, i boleri är hon vorden hafvande: Juda sade: Hafver henne här fram, att hon skall brännas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Och då hon hades fram, sände hon till sin svär och sade: Af denna mannen är jag hafvande, som detta tillhörer. Och sade: Känner du ock, hvem denne ringen och hufvudbonaden och stafven tillhörer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Juda kände det, och sade: Hon är rättfärdigare än jag; ty jag hafver icke gifvit henne min son Sela. Dock belåg han henne intet mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Och då hon skulle föda, funnos tvillingar i hennes lifve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Och som hon nu födde, gaf sig en hand ut; då tog Jordgumman och band der en rödan tråd om, och sade: Denne skall först utkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Men då han drog sina hand åter in, kom hans broder ut, och hon sade: Hvi är hinnan för dina skull sönderremnad? Och man kallade honom Perez.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Derefter kom hans broder ut, som hade den röda tråden om sina hand; och man kallade honom Serah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Joseph vardt förd neder i Egypten: Och Potiphar, en Egyptisk man, Pharaos hofmästare, köpte honom af de Ismaeliter, som honom hade fört der ned.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Och Herren var med Joseph, så att han vardt en lyckosam man: Och var i sins herras dens Egyptiens huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Och hans herre såg, att Herren var med honom; ty allt det han gjorde, lät Herren gå lyckosamlig till med honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Så att han fann nåd för sinom herra, och vardt hans tjenare: Han satte honom öfver sitt hus, och allt det han hade lät han under hans händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Och ifrå den tiden, då han hade satt honom öfver sitt hus och alla sina ägodelar, välsignade Herren den Egyptiens hus för Josephs skull: Och var alltsammans Herrans välsignelse i allo de han hade, hemma och på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Derföre lät han det allt under Josephs händer, hvad han hade; och hade intet deraf, utan allena brödet, som han åt. Och Joseph var dägelig och fager under ansigtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Och det begaf sig, då detta var skedt, att hans herras hustru kastade sin ögon på Joseph, och sade: Ligg när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Men han vägrade det henne, och sade till henne: Si, min herre vet icke hvad i hans huse är, och allt det han hafver, hafver han gifvit under mina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Och hafver intet så godt i sino huse, det han i mitt våld icke gifvit hafver, utan dig, ty du äst hans hustru. Hvi skulle jag nu så mycket ondt göra, och synda emot Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Men hon hade dageliga sådana ord till Joseph; men han lydde henne intet, att han skulle ligga när henne, eller vara något om henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Det begaf sig en dag, att Joseph gick in i huset till att göra sina sysslo; och ingen af husfolket var der när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Och hon fick honom i hans mantel, och sade: Ligg när mig. Men han lät blifva mantelen i hennes hand, och rymde ut af huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Då hon nu såg, att han lät blifva mantelen i hennes hand, och rymde ut,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Kallade hon husfolket, och sade till dem: Si, han hafver fört oss här in en Ebreisk man, att han skulle komma oss på skam. Han kom här in till mig, på det han skulle ligga när mig; men jag ropade med höga röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Och då han hörde, att jag skriade och ropade, då lefde han sin mantel när mig, och flydde, och lopp ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Och hon lade hans mantel när sig, så länge hennes herre kom hem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Och talade till honom samma orden, och sade: Den Ebreiske tjenaren, som du hafver haft här in, kom här in till mig, att han skulle komma mig på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Men då jag skriade och ropade, lefde han sin mantel när mig, och flydde ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Då hans herre hörde sådana sine hustrus ord, som hon till honom talade, och sade: Så hafver mig din Ebreiske tjenare gjort; vardt han ganska vred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Då tog hans herre honom, och lade honom i fängelse, der Konungens fångar inne lågo: Och der låg han då i fängelset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Men Herren var med honom, och var honom gunstig, och lät honom finna nåd för befallningsmannen öfver fångahuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Så att han befallte alla fångarna i fängelsena under hans hand, att allt det der skedde, måste ske genom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Förty befallningsmannen öfver fängelset såg, att Herren var med honom i allt det som under hans händer var, och att Herren lät, det han gjorde, lyckosammeliga tillgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Och det begaf sig derefter, att Konungens i Egypten höfvitsman öfver skänkerna, och höfvitsmannen öfver bakarena, bröto deras herra Konungenom i Egypten emot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Och Pharao vardt vred uppå dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Och lät sätta dem i hofmästarens hus i fängelse, der Joseph låg fången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Och hofmästaren satte Joseph öfver dem, att han skulle tjena dem; och de såto några dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Och både skänken och bakaren drömde om ena natt hvar sin dröm, och hvars deras dröm hade sin uttydelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Då nu Joseph kom om morgonen in till dem, och såg dem ångse,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Frågade han dem, och sade: Hvi ären I så ångse i dag?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'De svarade: Oss hafver drömt, och vi hafvom ingen, som oss det utlägger. Joseph sade: Utläggningen hörer Gudi till; dock förtäljer mig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Då förtäljde skänken sin dröm för Joseph, och sade till honom: Mig drömde, att ett vinträ var för mig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Det hade tre grenar; det grönskades, växte och blomstrades, och dess drufvor vordo mogna:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Och jag hade Pharaos skänkekar i mine hand, och tog och kryste dem i skänkekaret, och fick Pharao skänkekaret i handena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Joseph sade: Detta är uttydningen: Tre grenar äro tre dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Efter tre dagar skall Pharao upphäfva ditt hufvud, och sätta dig åter till dit ämbete, att du får honom skänkekaret i hans hand, såsom tillförene, då du var hans skänk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Men tänk uppå mig, då dig går väl, och gör barmhertighet med mig, att du Pharao ingifver, att han tager mig utaf detta huset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Ty jag är hemliga bortstulen utaf de Ebreers lande: Så hafver jag ock här intet gjort, att de mig insatt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Då bakaren såg, att uttydningen var god, sade han till Joseph: Mig hafver ock drömt, att jag bar tre flätade korgar på mitt hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Och i öfversta korgenom allahanda bakad mat till Pharaos behof; och foglarne åto af korgenom på mitt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Joseph svarade, och sade: Detta är uttydningen: Tre korgar äro tre dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Och efter tre dagar skall Pharao upphäfva ditt hufvud, och hänga dig i en galga; och foglarne skola äta ditt kött på dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Och det hände tredje dagen, då begick Pharao sin årsdag, och han gjorde alla sina tjenare ena måltid: Och upphof den öfversta skänkens hufvud, och den öfversta bakarens, ibland sina tjenare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Och satte den öfversta skänken åter till sitt skänkeämbete, att han skulle få Pharao skänkekaret i handena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Men den öfversta bakaren lät han hänga; som Joseph hade uttydt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Men den öfverste skänken tänkte intet på Joseph, utan förgat honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Och tu år derefter hade Pharao en dröm, såsom han hade ståndit vid älfvena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Och sett af älfvene uppstiga sju nöt skön och fet; och de gingo i goda bet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Sedan såg han annor sju nöt uppstiga af älfvene, vanskapeliga och magra; och gingo jemte de andra på strandene vid älfvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Och de sju vanskapeliga och magra nöten åto upp de sju sköna och feta nöten. Då vaknade Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Och han somnade åter, och åter drömde honom, och såg, att sju ax full och tjock växte på enom stjelk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Derefter såg han sju tunn förvissen ax uppgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Och de sju magra axen uppslukte de sju stora och fulla axen. Då vaknade Pharao, och såg, att det var en dröm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Och då det vardt morgon, var hans ande bedröfvad; och skickade ut, och lät kalla alla spåmän i Egypten, och alla visa, och förtäljde dem sin dröm: Men der var ingen, som honom kunde uttyda för Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Då talade den öfverste skänken med Pharao, och sade: Jag kommer ihåg i dag mina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Då Pharao var förtörnad på sina tjenare, och lade mig med den öfversta bakaren i fängelse, i hofmästarens hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Då drömde oss bådom i ene natt, hvar sin dröm, hvars uttydning hvarjom för sig pågalt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Då var när oss en Ebreisk ung man, hofmästarens tjenare; honom förtäljde vi det, och han uttydde oss våra drömmar, hvarjom efter sinom dröm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Och som han oss uttydde, så är det gånget; ty jag är åter satt till mitt ämbete, och han är hängder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Då sände Pharao bort, och lät kalla Joseph, och de hade honom utu fängslet. Och han lät raka sig, och förvandla sin kläder, och kom in till Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Då sade Pharao till honom: Mig hafver drömt en dröm, och ingen är, som honom uttyder: Men jag hafver hört af dig sägas, att när du hörer en dröm, då uttyder du honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joseph svarade Pharao, och sade: Det står icke mig till; men Gud skall dock förkunna Pharao det godt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Pharao sade till Joseph: Mig drömde, jag stod på strandene vid älfvena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Och såg uppstiga af älfvene sju nöt, fet och skön, och de gingo i goda bet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Och efter dem såg jag sju annor nöt uppstiga, tunn och fast vanskapeliga och magra; jag hafver icke i hela Egypten sett så vanskapeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Och de sju vanskapeliga och magra nöten åto upp de sju första feta nöten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Och då de hade ätit dem upp, syntes intet på dem, att de hade ätit dem, och voro vanskapeliga såsom tillförene. Då vaknade jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Och såg åter i minom dröm sju ax vuxen på enom stjelk full och tjock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Derefter gingo upp sju torr ax tunn och förvissen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Och de sju tunna axen uppslöko de sju torra axen. Och jag hafver sagt det mina spåmän; men de kunna icke tyda mig det ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Joseph svarade Pharao: Båda drömmarne, Pharao, äro ens. Gud förkunnar Pharao, hvad han göra vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'De sju sköna nöten äro sju år, och de sju fulla axen äro ock de sju åren: Det är allt enahanda dröm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'De sju magra nöten och vanskapeliga, som efter de andra uppstigna äro, äro sju år; och de sju magra och förvissnade axen skola vara sju hård år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Det är nu det jag sagt hafver till Pharao, att Gud undervisar Pharao, hvad han göra vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Si, sju år varda kommande med stor ymnoghet i hela Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Och efter dem varda sju hård år kommande, att man varder förgätandes all sådana ymnoghet i Egypti lande: Och den dyre tiden varder förtärandes landet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Att man intet skall veta af den ymnoghetene i landena, för den dyra tidens skull, som efter kommer; förty han skall varda ganska svår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Men det Pharao hafver andra resona drömt betyder, att Gud skall sådant visserliga och snarliga göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nu må Pharao se efter en förståndig och vis man, den han sätta må öfver Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Och skaffa, att han förskickar ämbetsmän i landena, och taga den femte delen i Egypti lande i de sju rika åren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Och församle alla spisning af de goda åren, som komma skola, att de låta inkomma säd uti Pharaos kornhus till förråd i städerna, och förvara det:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'På det man finner landena spisning i de sju hårda åren, som komma skola öfver Egypti land; att landet icke förderfvas af hunger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Det talet behagade Pharao och alla hans tjenare väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Och Pharao sade till sina tjenare: Huru kunne vi finna en sådana man, som Guds Ande är uti?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Och sade till Joseph: Efter Gud hafver allt sådant kundgjort dig, är ingen så klok och förståndig, som du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du skall vara öfver mitt hus, och efter dino orde skall allt mitt folk lydigt vara: Allena i mitt Konungsliga säte vill jag vara mer än du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Och sade: Si, jag hafver satt dig öfver hela Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Och tog sin ring af sine hand, och gaf honom Joseph på sina hand, och klädde honom Joseph i hvitt silke, och hängde en guldkedjo på hans hals;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Och lät honom sitta på den andra vagnen, och lät utropa honom: Denne är landsens fader: Och satte honom öfver hela Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Och Pharao sade till Joseph: Jag är Pharao; utan din vilja skall ingen, i hela Egypti lande, röra sin hand eller fot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Och kallade honom det hemligaste rådet; och gaf honom till hustru Asnath Potiphera dotter Prestens i On. Så for Joseph ut till att bese Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Och han var tretio år gammal, då han stod för Pharao. Och for ut ifrå Pharao, och for omkring hela Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Och landet gjorde allt så i de sju rika åren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Och församlade i de sju åren alla spisning i Egypti land, och läto det i städerna: Ehvad spisning som växte på markene vid hvar och en stad allt omkring, det läto de komma der in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Så lade Joseph tillhopa sädena öfver måtto mycket, som sandkornen i hafvet, så att han vände igen att räkna; ty man kunde det icke räkna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Och Joseph vordo födde två söner, förra än den dyre tiden kom, hvilka honom födde Asnath Potiphera dotter Prestens i On.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Och kallade den första Manasse; förty, sade han, Gud hafver låtit mig förgäta alla mina olycko, och mins faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Den andra kallade han Ephraim; förty, sade han, Gud hafver låtit mig växa till i mins eländes lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Då nu de sju rika åren voro framliden i Egypten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Så begynte de sju hårda åren gå uppå, som Joseph hade omtalat. Och vardt en dyr tid i all land; men i hela Egypti lande var bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Då nu Egypti land ock led hunger, ropade folket till Pharao om bröd. Men Pharao sade till alla Egyptier: Går bort till Joseph, hvad han säger eder, det görer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'När nu dyr tid var öfver allt landet, slog Joseph kornhusen upp allestäds, och sålde de Egyptier; förty som dyre tiden vardt ju längre ju större i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Och all land kommo till Egypten, till att köpa när Joseph; förty den dyre tiden fick öfverhandena i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Men då Jacob såg, att säd var fal i Egypten, sade han till sina söner: Hvi sen I icke till?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Si, jag hörer, att uti Egypten är säd nog, farer der ned, och köper oss säd, att vi må lefva och icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Så foro då tio Josephs bröder ned, att de skulle köpa säd i Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Ty BenJamin Josephs broder lät Jacob icke fara med sina bröder, ty han sade: Honom måtte något ondt vederkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Så foro Israels barn åstad till att köpa säd med androm, som kommo med dem; ty det var ock dyr tid i Canaans lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Men Joseph var rådandes i landena, och sålde säd allo folkena i landena. Då nu hans bröder kommo till honom, föllo de ned på jordene för honom på sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Och han såg uppå dem, och kände dem, och låts vara främmande emot dem, och talade skarpt med dem, och sade till dem: Hvadan kommen I? De sade: Utaf Canaans land till att köpa spisning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Och ändå han kände dem, så kände de dock intet honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Och Joseph tänkte på drömmen, som honom hade drömt om dem, och sade till dem: I ären spejare, och ären komne till att bese, hvarest landet är öppet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'De svarade honom: Nej, min herre, dine tjenare äro komne till att köpa spisning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Vi äre alle ens mans söner; vi äre redelige, och dine tjenare hafva aldrig varit spejare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Han sade till dem: Nej, utan I ären komne till att bese, hvarest landet är öppet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'De svarade honom: Vi dine tjenare äre tolf bröder, ens mans söner i Canaans land; och den yngste är när vår fader, men den ene är icke mer till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Joseph sade till dem: Detta är det jag hafver sagt eder, spejare ären I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'De uppå vill jag pröfva eder: Vid Pharaos lif, I skolen icke komma hädan, med mindre edar yngste broder kommer hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Sänder en af eder bort, som hemtar hit edar broder: Men I skolen vara fångne. Så vill jag pröfva edart tal, om I faren med sanningene eller icke. Ty hvar så icke, så ären I, vid Pharaos lif, spejare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Och han lät dem allesamman i förvaring i tre dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Om tredje dagen sade han till dem: Viljen I lefva, så görer alltså; ty jag fruktar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Ären I redelige, så låter en edar broder ligga bunden i edart fängelse; men I farer bort, och förer hem hvad som I köpt hafven emot hungeren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Och förer edar yngsta broder hit till mig, så vill jag tro edor ord, på det I icke skolen dö. Och de gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Men de talade inbördes: Detta hafve vi förskyllat på vår broder, att vi såge hans själs ångest, då han bad oss, och vi ville intet höra honom; derföre kommer nu denna bedröfvelsen öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben svarade dem, och sade: Sade jag icke eder, då jag talade: Synder icke på pilten; och I villen icke hörat? Nu varder hans blod utkrafd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Men de visste icke, att Joseph förstod det; ty han talade med dem med en tolk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Och han vände sig ifrå dem, och gret. Då han nu vände sig åter till dem, och talade med dem, tog han Simeon utaf dem, och bandt honom för deras ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Och gaf befallningen, att deras säckar skulle fyllas med mälning, och gifvas deras penningar igen, hvars i hans säck; dertill ock hvarjom sina täring på resone. Och man gjorde dem så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Och de lade sina varor på sina åsnar, och foro dädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Men då endera lät upp sin säck, att han skulle fodra sin åsna i herberget, vardt han varse sina penningar, som lågo ofvan i säckenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Och sade till sina bröder: Jag hafver fått mina penningar igen; si, de äro i minom säck. Då förföll dem deras hjerta och förskräcktes inbördes, och sade: Hvi hafver Gud gjort oss så?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Då de nu kommo hem till deras fader Jacob i Canaans lande, sade de honom allt det dem vederfaret var, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Den mannen, som är herre i landet, talade skarpt till oss, och höll oss för landsens spejare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Och då vi svarade: Vi äre redelige, och hafve aldrig varit spejare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Utan ärom tolf bröder, vårs faders söner; en är icke mer till, och den yngste är ännu i denna dag när vår fader i Canaans lande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Sade han till oss: Deruppå vill jag märkat, att I ären redelige: En edar broder låter när mig qvar, och tager nödtorft till edor hus, och farer bort:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Och hemter edar yngsta broder hit till mig, så kan jag märka, att I icke ären spejare, utan redelige män; så vill jag ock gifva eder edar broder igen, och så må I bruka edart bästa i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Och då de slogo ut af säckarna, fann hvar och en sitt penningaknyte i sinom säck: Och då de sågo, att det var deras penningaknyte, vordo de, med deras fader, förskräckte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Då sade Jacob deras fader: I hafven gjort mig barnlös; Joseph är icke mera till, Simeon är ock icke mera till, BenJamin viljen I taga ifrå mig: Det går allt öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruben svarade sinom fader, och sade: Om jag icke förer dig honom hem igen, så dräp båda mina söner: Allenast gif honom i mina hand, jag vill föra dig honom hem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Han sade: Min son skall icke fara ned med eder; ty hans broder är död, och han är allena igenblifven: Om honom vederfores något ondt i vägen, der I resten, vorden I drifvandes min grå hår med sorg neder i grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Men den dyre tiden tvingade landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Och det vardt allt, som de hade fört utaf Egypten, sade deras fader Jacob till dem: Farer åter dit, och köper oss någon spisning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Då svarade honom Juda, och sade: Den mannen vederlade oss det högeliga, och sade: I skolen icke komma för min ögon, med mindre edar broder är med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Är det nu så, att du sänder vår broder med oss, så vilje vi fara ned, och köpa dig spisning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Men är det så, att du icke sänder honom, så fare vi icke neder; ty mannen hafver sagt oss: I skolen icke komma för min ögon, utan edar broder är med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel sade: Hvi hafven I så illa gjort emot mig, att I hafven det sagt mannenom, att I haden än en broder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'De svarade: Den mannen frågade så grant om oss och våra slägt, och sade: Lefver edar fader än? Hafven I ännu en broder? Då sade vi honom, som han frågade: Huru kunde vi veta, att han skulle säga: Hafver edar broder hit ned med eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Då sade Juda till Israel sin fader: Låt pilten fara med mig, att vi må göra oss redo och färdas, och mågom lefva, och icke dö, både vi och du, och vår barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Jag vill vara god för honom; utaf mina händer skall du äska honom: Förer jag dig icke honom igen, och sätter honom fram för din ögon, så vill jag hafva skuld så länge jag lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Ty hvar vi icke hade fördröjt, hade vi väl allaredo två resor varit igenkomne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Då sade Israel deras fader till dem: Måste det ju så vara, så görer det, och tager af landsens bästa frukt i edra säckar, och förer mannenom skänker dit neder, något balsam och hannog, och örter, och myrrham, och dadel och mandel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Tager ock andra penningar med eder, och de penningar, som I hafven fått igen ofvan i edra säckar, förer också med eder; tilläfventyrs der är någon villa ibland kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Dertill tager edar broder; görer eder redo, och farer till mannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Men allsmägtig Gud gifve eder barmhertighet för den mannenom, att han måtte eder fri låta den andra broderen och BenJamin. Men jag måste vara, som den der sin barn slätt mist hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Då togo de dessa skänker, och penningar dubbelt med sig, och BenJamin; gjorde sig redo, och foro in i Egypten, och gingo in för Joseph.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Då såg Joseph dem med BenJamin, och sade till honom, som var öfver hans hus: Haf dessa männerna in i huset, och slagta, och red till; förty de skola äta med mig i middag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Och mannen gjorde såsom Joseph honom sagt hade, och hade männerna in i Josephs hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Men de fruktade sig, att de vordo hafde i Josephs hus, och sade: Vi äre här införde för penningarnas skull, som vi tillförene funnom i våra säckar, att han vill komma oss det uppå, och låta en dom gå öfver oss, der han oss med tager till sina trälar, med våra åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Derföre gingo de till mannen, som var öfver Josephs hus, och talade med honom utanför dörrena af husena:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Och sade: Min herre, vi vorom tillförene här nedre till att köpa spisning:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Och då vi kommo i herberget, och löste upp våra säckar, si, då voro hvars och ens penningar ofvan i hans säck, med fulla vigt; derföre hafve vi åter fört dem med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Hafvom också fört andra penningar med oss, till att köpa spisning med. Men vi vete icke, ho som hafver stungit oss våra penningar i våra säckar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Men han sade: Varer till frids, frukter eder icke, edar Gud, och edar faders Gud, hafver gifvit eder en skatt i edra säckar; edra penningar hafver jag fått. Och han hade Simeon ut till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Och hade dem i Josephs hus: Gaf dem vatten, att de skulle två sina fötter, och gaf deras åsnar foder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Men de redde till skänkerna, tilldess Joseph kom till middagen; ty de hade hört, att de skulle der äta bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Då nu Joseph gick in i huset, båro de honom skänkerna i huset på sina händer, och föllo för honom neder på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Men han tackade dem kärliga, och sade: Går det väl med edrom fader den gamla, der I mig af saden? Lefver han ännu?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'De svarade: Vårom fader dinom tjenare går väl, och han lefver ännu: Och bugade sig, och föllo ned för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Och han lyfte upp sin ögon, och såg sin broder BenJamin, sine moders son, och sade: Är det edar yngste broder, som I saden mig af? Och sade ytterligare: Gud vare dig nådelig, min son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Och Joseph hastade, ty hans hjerta var brinnande öfver sin broder, och sökte rum till att gråta; och gick i sin kammar, och gret der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Och då han hade tvagit sitt ansigte, gick han ut, och höll sig fast, och sade: Lägger bröd fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Och der bars fram, besynnerliga för honom, och besynnerliga för dem, och för de Egyptier, som med honom åto, ock besynnerliga; förty de Egyptier töras icke äta bröd med de Ebreer, det är en vederstyggelse för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Och de sattes för honom, den förstfödde efter sina förstfödslo, och den yngste efter sin ungdom. Der förundrade de sig uppå inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Och man bar dem besynnerliga rätter af hans bord: Men BenJamin fem sinom mer än de andra; och de drucko, och vordo druckne med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Och Joseph befallde honom, som var öfver hans hus, och sade: Fyll dessa männernas säckar med spisning, så mycket de kunna föra, och lägg hvarjom sina penningar ofvan i hans säck:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Och mina silfskål ofvan i dens yngstas säck med penningarna för sädena. Han gjorde, som Joseph honom sade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Om morgonen, då ljust vardt, läto de männerna fara med sina åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Då de nu voro ut af stadenom, och icke långt komne, sade Joseph till honom, som var öfver hans hus: Up och far efter männerna, och när du får dem, så säg till dem: Hvi hafven I lönt godt med ondo?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Är icke det der min herre dricker utaf, och der han spår med? I hafven illa gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Och som han beslog dem, sade han sådan ord till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'De svarade honom: Hvi talar min herre sådana ord? Bort det, att dine tjenare skulle så göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Si, penningarna, som vi funnom ofvan uti våra säckar, hafvom vi fört till dig igen af Canaans lande: Och hvi skulle vi då hafva stulit silfver eller guld af dins herras huse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'När hvilken det varder funnit ibland dina tjenare, han må dö: Dertill vilje vi ock vara mins herras trälar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Han sade: Ja, vare som I hafven sagt: När hvilkom det finnes, han vare min träl: men I skolen vara löse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Och då de hastade sig, och lade hvar sin säck af ned på jordena, och hvar lät upp sin säck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Och han sökte, och begynte på den första, in till den yngsta; då fans skålen i BenJamins säck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Då refvo de sin kläder, och ladde hvar uppå sin åsna, och foro åter in i staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Och Juda gick med sina bröder in i Josephs hus; ty han var ändå der, och de föllo ned på jordena för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joseph sade till dem: Hvi torden I det göra? Veten I icke, att en sådana man, som jag är, kunde spå till?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juda sade: Hvad skole vi säga minom herra, eller huru skole vi bära före? Gud hafver funnit dina tjenares missgerningar: Si, vi och den, som skålen är funnen när, äre min herras trälar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Men han sade: Bort det, att jag skulle så göra. Den mannen, som skålen är funnen när, han skall vara min träl: Men I farer med frid upp till edar fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Då gick Juda till honom, och sade: Min herre, låt din tjenare tala ett ord i dina öron, min herre, och din vrede harmes icke öfver din tjenare; ty du äst såsom Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Min herre frågade sina tjenare, och sade: Hafven I ock någon fader, eller broder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Då svarade vi: Vi hafve en fader, och han är gammal, och en ung dräng föddan i hans ålderdom, och hans broder är död, och han är allena blifven igen af sine moder, och hans fader hafver honom kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Då sade du till dina tjenare: Hafver honom hit ned till mig, och jag vill göra honom godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Men vi svarade minom herra: Pilten kan icke komma ifrå sinom fader; hvar han komme honom ifrå, dödde han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Då sade du till dina tjenare: Hvar edar yngste broder icke kommer här med eder, skolen I icke mera komma för min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Då forom vi upp till din tjenare, min fader, och sadom honom mins herras tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Då sade vår fader: Farer åter bort, och köper oss någon spisning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Men vi sade: Vi kunne icke fara der ned, med mindre vår yngste broder är med oss, så vilje vi fara derned; ty vi kunne icke komma för dens mansens ögon, hvar vår yngste broder icke är med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Då sade din tjenare, min fader, till oss: I veten, att min hustru hafver födt mig två:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Den ene gick bort ifrån mig, och det sades, att han skulle vara ihjälrifven; och jag hafver ej sett honom allt härtill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Skolen I ock taga denna ifrå mig, och honom vederfars något ondt, så varden I drifvande min grå hår med sorg ned i grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Om jag nu komme hem till din tjenare, min fader, och pilten vore icke med oss, efter hans själ hänger intill desses själ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Så sker det, då han ser, att pilten icke är tillstädes, att han dör: Så vorde vi dine tjenare, dins tjenares, vårs faders grå hår förande med jämmer ned i grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Ty jag, din tjenare, hafver varit minom fader god för pilten, och sagt: Hafver jag icke honom till dig igen, så vill jag hafva skuld i alla mina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Derföre, låt din tjenare blifva här qvar minom herra för en träl i piltens stad; och låt pilten fara upp med sina bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Förty, huru skulle jag fara upp till min fader, när pilten är icke med mig? Jag finge se den jämmer, som min fader uppå komme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Då kunde icke Joseph hålla sig för allom dem, som omkring stodo, och han ropade: Går alle ut ifrå mig. Och stod ingen när honom, då Joseph bekände sig för sina bröder:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Och han gret öfverljudt, så att de Egyptier och Pharaos tjenare det hörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Och han sade sina bröder: Jag är Joseph; lefver min fader ännu? Och hans bröder kunde intet svara honom; så förskräckte voro de för hans ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Men han sade: Går dock hit till mig. Och de gingo till honom, och han sade: Jag är Joseph edar broder, den I hafven sålt in uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Och nu låter det icke bekymra eder, och tänker icke att jag derföre är vred, att I hafven sålt mig hit; ty för edra välfärds skull hafver Gud sändt mig hit för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Ty det är nu tu år, att dyr tid hafver varit i landena; och äro ännu fem år, att ingen plöjning eller uppskörd skall varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Men Gud hafver sändt mig hit för eder, att han vill låta eder blifva qvara på jordene, och hålla eder vid lif genom stor under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Så hafven icke nu I sändt mig hit, utan Gud: Han hafver gjort mig såsom en fader till Pharao, och till en herra öfver allt hans hus, och till en Första i hela Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Skynder eder nu, och farer upp till min fader, och säger honom: Det låter din son Joseph säga dig: Gud hafver satt mig till en herra i hela Egypti land; kom ned till mig, försumma dig icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Du skall bo i det landet Gosen, och vara hardt när mig, du och din barn, och din barnabarn, din får och fä, och allt det ditt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Jag vill der försörja dig; ty det är ännu fem åra dyr tid att du icke varder förderfvad med ditt hus, och allt det ditt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Si, edor ögon se, och mins broders BenJamins ögon, att jag talar munteliga med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Förkunner minom fader alla mina härligheter i Egypten, och allt det I sett hafven. Skynder eder, och kommer hit ned med minom fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Och han fick sin broder BenJamin om halsen, och gret; och BenJamin gret ock vid hans hals.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Och han kysste alla sina bröder, och gret öfver dem. Sedan talade hans bröder med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Och när det ryktet kom i Pharaos hus, att Josephs bröder voro komne, behagade det Pharao väl, och alla hans tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Och Pharao sade till Joseph: Säg dina bröder: Detta görer; ladder edor djur; farer bort, och när I kommen i Canaans land,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Så tager edar fader och edart folk, och kommer till mig, jag vill gifva eder af allt det goda, som i Egypti land är, att I skolen äta märgen i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Och bjud dem: Görer alltså: Tager edor utaf Egypti lande vagnar till edor barn och hustrur, och förer edar fader, och kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Och skoner icke edor bohags ting; förty allt det goda i hela Egypten skall höra eder till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Israels barn gjorde så, och Joseph fick dem vagnar, efter Pharaos befallning, och förtäring på vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Och gaf dem allom, hvarjom för sig, högtidskläder; men BenJamin och han trehundrad silfverpenningar, gaf fem högtidsklädningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Men fadrenom sände han tio åsnar, ladda med gods utaf Egypten, och tio åsninnor med mälning och bröd och spisning, sinom fader på vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Och så lät han sina bröder fara, och sade till dem: Kifver icke på vägenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Så foro de utaf Egypten, och kommo uti Canaans land till sin fader Jacob;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Och förkunnade honom det, och sade: Din son Joseph lefver ännu, och är en herre i hela Egypti lande. Men honom föll det icke i sinnet, ty han trodde dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Då sade de honom all Josephs ord, som han till dem sagt hade. Och då han såg vagnarna, som Joseph utsändt hade till att föra honom med, vardt hans ande lefvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Och sade: Jag hafver nog, att min son Joseph lefver ännu. Jag vill fara bort och se honom, förra än jag dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Israel for dit med allt det honom tillhörde. Och då han kom till BerSaba, offrade han ett offer sins faders Isaacs Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Och Gud sade till honom om nattena i ene syn: Jacob, Jacob. Han sade: Här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Och han sade: Jag är Gud, dins faders Gud, frukta dig icke att fara in i Egypten; förty, der vill jag göra dig till ett mägtigt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Jag vill fara dit med dig, och vill åter föra dig derut. Och Joseph skall lägga sina hand uppå din ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Då for Jacob ifrå BerSaba. Och Israels barn förde Jacob sin fader, med sin barn och hustrur, på vagnomen, som Pharao hade sändt till att föra dem med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Och togo sin boskap och håfvor, som de förvärfvat hade i Canaans lande, och kommo så in uti Egypten, Jacob och all hans säd med honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Hans barn och hans barnabarn med honom, hans döttrar, och hans barns döttrar, och all hans säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Desse äro Israels barns namn, de som kommo i Egypten: Jacob och hans söner. Jacobs förstfödde son Ruben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Rubens barn: Hanoch, Pallu, Hezron och Charmi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Simeons barn: Jemuel, Jamin, Ohad, Jachin, Zohar, och Saul den Cananeiske qvinnones son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Levi barn: Gerson, Kehat och Merari.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Juda barn: Er, Onan, Sela, Perez och Serah. Men Er och Onan dödde i Canaans lande. Men Perez barn: Hezron och Hamul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Isaschars barn: Thola, Phuva, Job och Simron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Sebulons barn: Sered, Elon och Jahleel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Desse äro barnen af Lea, som hon födde Jacob i Mesopotamien, med sine dotter Dina: De göra tillhopa alle, med söner och döttrar, tre och tretio själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gads barn: Ziphion, Haggi, Suni, Ezbon, Eri, Arodi och Areli.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Assers barn: Jimna, Jisua, Jisui, Brya; och Serah, deras syster. Men Bryas barn: Heber och Malchiel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Desse äro Silpas barn, som Laban gaf Lea sine dotter, och födde Jacob dessa sexton själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Rachels Jacobs hustrus barn: Joseph och BenJamin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Och Joseph vordo födde i Egypten, Manasse och Ephraim, som honom födde Asnath Potiphera dotter Prestens i On.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'BenJamins barn: Bela, Becher, Asbel, Gera, Naaman, Ehi, Ros, Muppim, Huppim och Ard.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Desse äro barnen af Rachel, som Jacob födde äro; alle tillhopa fjorton själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Dans barn: Husim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Naphthali barn: Jahzeel, Guni, Jezer och Sillem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Desse äro Bilhas barn, som Laban hade gifvit sine dotter Rachel, och födde Jacob dessa sju själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Alla själar som kommo med Jacob in i Egypten, som utgångne voro af hans länd, undantagande hans barnahustrur, äro alle tillsamman sex och sextio själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Och Josephs barn, som honom vordo födde i Egypten, voro två själar: Så att alla Jacobs hus själar, som kommo in i Egypten, voro sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Och han sände Juda för sig till Joseph, att han skulle visa honom vägen till Gosen; och de kommo in i landet Gosen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Då spände Joseph före sin vagn, och for ut emot Israel sin fader till Gosen. Och då han fick se honom, föll han om hans hals, och gret svårliga på hans hals.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Då sade Israel till Joseph: Nu vill jag gerna dö, efter det jag hafver sett ditt ansigte, att du ännu lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Joseph sade till sina bröder och sin faders hus: Jag vill fara upp, och undervisa der Pharao, och säga till honom: Mine broder och mins faders hus är kommit till mig utaf Canaans land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Och äro herdar, ty det är sådana folk, som med boskap umgå plägar; deras får och fä, och allt det de hafva, hafva de fört med sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Då nu Pharao varder eder kallandes, och säger: Hvad är edar handel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Så skolen I säga: Dine tjenare äro folk, som med boskap umgå ifrå vår barndom allt härtill, både vi och våre fäder, på det I må få bo i det landet Gosen; förty alle herdar äro såsom en styggelse för de Egyptier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Då kom Joseph och förkunnade det Pharao, och sade: Min fader och mine bröder, deras får och fä, och hvad de hafva, är kommet utu Canaans lande; och si, de äro i det landet Gosen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Och han tog fem fina bröder och ställde dem för Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Då sade Pharao till hans bröder: Hvad är edar handel? De svarade: Dine tjenare äro herdar, vi och våre fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Och sade ytterligare till Pharao: Vi äre komne till att bor med eder i landena; ty dine tjenare hafva ingen bet till deras boskap, så hårdt tvingar den hårde tiden Canaans land: Så gör väl, och låt dina tjenare bo i det landet Gosen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Pharao sade till Joseph: Det är din fader, och det äro dine bröder, de äro komne till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Egypti land står dig öppet; låt dem bo på bästa platsen i landena, att de må bo i det landet Gosen. Och om du vetst några män ibland dem, som dogse äro, så sätt dem öfver min boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Joseph hade ock sin fader Jacob in, och ställde honom för Pharao: Och Jacob välsignade Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Men Pharao frågade Jacob: Huru gammal äst du:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jacob sade: Mins eländes tid är hundrade och tretio år; liten och onder är min eländes tid, och räcker intet till mina fäders eländes tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Och Jacob välsignade Pharao, och gick ut ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Men Joseph skaffade sinom fader och sina bröder boning, och gaf dem en besittning i Egypti lande, på bästa platsen i landena, nemliga i det landet Rameses, såsom Pharao budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Och han försörjde sin fader och sina bröder, och hela sins faders hus, hvarjom och enom sin del bröd, allt ifrå de gamla intill de unga barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Men i all land var intet bröd; ty att den dyre tiden var ganska svår, så att Egypten och Canaans land svolte för den dyra tidens skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Och Joseph samkade alla de penningar tillhopa, som funnos i Egypten och Canaan, för mälning, som de köpte; och han lät alla penningarna komma i Pharaos hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Då nu penningarne fattades i Egypti land och Canaan, kommo alle Egyptier till Joseph, och sade: Skaffa oss bröd; hvi låter du oss dö för dig, derföre att vi hafve inga penningar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph sade: Skaffer hit edar boskap, så vill jag gifva eder för boskapen, medan I ären utan penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Då hade de deras boskap till Joseph, och han gaf dem bröd för deras hästar, får, fä och åsnar: Så födde han dem det året med bröd för all deras boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Då året var omlidet, kommo de till honom på andra året, och sade till honom: Vi vilje icke döljat för vår herra, att icke allena penningarne, utan ock all vår boskap är borto när vår herra, och är intet mer qvart för vår herra, utan allena vår kropp och åker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Hvi låter du både oss och vår åker dö? Tag oss till dig, och vårt land, för bröd, att vi och vårt land måge vara Pharaos egne; gif oss säd, att vi må lefva och icke åkren icke förlägges.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Så tog Joseph hela Egypti land in till Pharao; ty de Egyptier sålde hvar sin åker; ty den hårde tiden var allt för stark öfver dem. Och vardt så landet Pharaos eget,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Med folket, som i hans städer ut och ingick, ifrå den ena ändan i Egypten intill den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Undantagen Presternas åker, den tog han icke in; ty det var förskickadt af Pharao till Presterna, att de äta skulle det dem benämndt var, det han dem gaf; derföre behöfde de icke sälja sina åkrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Då sade Joseph till folket: Si, jag hafver i dag intagit eder och edar åker till Pharao: Si, der hafven I säd, och sår åkren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Och af växtenom skolen I gifva Pharao den femte delen; fyra delar skola vara edre till att så åkren med till edor spisning, och till edor hus och barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'De sade: Allenast låt oss lefva, och finna nåd för dig vårom herra, vi vilje gerna vara Pharaos egne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Så gjorde Joseph dem en lag allt intill denna dag, öfver de Egyptiers åker, till att gifva Pharao den femte delen, undantagnom Prestaåkrenom, den vardt icke Pharaos egen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Så bodde Israel i Egypten, i det landet Gosen, och hadet inne, och växte till, och förökades svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Och Jacob lefde sjutton år i Egypti land, så att hans hela ålder vardt hundrade och sju och fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Då nu tiden kom, att Israel dö skulle, kallade han sin son Joseph, och sade till honom: Hafver jag funnit nåd för dig, så lägg dina hand under mina länd, att du gör barmhertighet och trohet med mig, och begrafver mig icke uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Utan jag vill ligga när mina fäder, och du skall föra mig ut af Egypten, och begraf mig i deras grifter. Han sade: Jag vill göra som du hafver sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Och han sade: Så svär mig. Och han svor honom. Då böjde Israel sig intill sängenes hufvudgärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Derefter vardt Joseph sagdt: Si, din fader är sjuk. Och han tog båda sina söner med sig, Manasse och Ephraim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Då vardt Jacob sagdt: Si, din son Joseph kommer till dig. Och Israel tog styrko till sig, och satte sig upp i sängene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Och sade till Joseph: Den allsmägtige Gud syntes mig i Lus i Canaans land, och välsignade mig,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Och sade till mig: Si, jag skall låta dig växa och förökas, och göra dig till mycket folk, och skall gifva dine säd efter dig detta landet till egendom evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Så skola nu dine två söner, Ephraim och Manasse, som dig i Egypten födde äro, förra än jag kom hit in till dig, vara mine, lika som Ruben och Simeon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Men de, som du föder efter dem, skola vara dine: men desse skola vara nämnde med deras bröders namn i deras arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Och då jag kom utaf Mesopotamien, dödde mig Rachel i Canaans lande på vägenom, då ännu ett litet stycke vägs var till Ephrath; Och jag begrof henne på vägenom till Ephrath, det nu heter BethLehem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Och Israel såg Josephs söner, och sade: Ho äro desse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joseph svarade sinom fader: Det äro mine söner, som Gud hafver mig här gifvit. Han sade: Haf dem hit till mig, att jag välsignar dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Ty Israels ögon voro mörk vorden för ålders skull, och kunde icke väl se. Och han hade dem till honom: Och han kysste dem, och tog dem i famn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Och sade till Joseph: Si, jag hafver sett ditt ansigte, det jag icke förmodat hade: Och si, Gud hafver ock låtit mig se dina säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Och Joseph tog dem utaf hans sköte, och han böjde sig ned på jordena för hans ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Då tog Joseph dem båda, Ephraim i sin högra hand, emot Israels venstra hand, och Manasse i sina venstra hand, emot Israels högra hand, och dem till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Men Israel räckte ut sina högra hand, och lade henne på Ephraims dens yngstes hufvud, och sina venstra hand på Manasse hufvud, och omskifte händerna med vilja; ty Manasse var den förstfödde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Och han välsignade Joseph, och sade: Gud, för hvilkom mine fäder Abraham och Isaac vandrat hafva; Gud, som mig födt hafver utaf min ungdom allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Ängelen, som mig frälst hafver af allo ondo, han välsigne dessa piltarna, att de må efter mitt, och mina fäders, Abrahams och Isaacs, namn nämnde varda, så att de må växa och förökas på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Men då Joseph såg, att hans fader lade sina högra hand på Ephraims hufvud, behagade det honom illa, och fattade uti sins faders hand, att han skulle vända sina hand af Ephraims hufvud in på Manasse hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Och sade till honom: Icke så, min fader; denne är den förstfödde, lägg dina högra hand på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Men hans fader nekade det, och sade: Jag vet väl, min son, jag vet det väl; denne skall ock varda till folk, och skall varda stor, men hans yngre broder skall varda större än han, och hans säd skall varda till ett stort folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Så välsignade han dem i den dagen och sade: Varde Israel välsignad efter ditt sätt, så att man må säga: Gud sätte dig såsom Ephraim och Manasse: Och så satte han Ephraim för Manasse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Och Israel sade till Joseph: Si, jag dör, och Gud skall vara med eder, och skall föra eder åter i edra fäders land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Jag hafver gifvit dig ett stycke land utan dina bröder, som jag med mitt svärd och båga utaf de Amoreers hand tagit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Och Jacob kallade sina söner, och sade: Församler eder, att jag må förkunna eder, hvad eder skall hända i den yttersta tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kommer tillhopa, och hörer till, I Jacobs barn; hörer edar fader Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben min förste son, du äst min kraft, och min första magt, den öfverste i offret, och den öfverste i riket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Han utlöper med hast som vatten: Du skall icke vara den öfverste; ty du hafver uppstigit i dins faders lägre, och der hafver du med det uppstigandet besmittat mina säng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'De bröder Simeon och Levi, de hafva handlat orättfärdiga med deras mordvapen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Min själ komme icke i deras råd, och min härlighet vare icke i deras förbund; förty uti deras vrede hafva de dödat mannen, och uti deras öfverdådighet hafva de förderfvat oxan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Förbannad vare deras vrede, att hon så styf är, och deras grymhet, att hon så hård är: Jag skall skingra dem i Jacob, och förströ dem i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, du äret, dig skola dine bröder lofva, din hand skall vara dina fiender på halsen; för dig skola dins faders barn buga sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda är ett ungt lejon, du äst högt kommen, min son, genom stor seger: Han hafver nederböjt sig, och lägrat sig som ett lejon, och som en lejinna. Ho törs sätta sig upp emot honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Spiran skall icke varda tagen ifrån Juda, ej heller en mästare ifrå hans fötter, tilldess Hjelten kommer; och honom skola folken tillfalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Han varder bindandes sin fåla vid vinträt, och sine åsninnos son vid den ädla vinqvisten. Han skall två sin kläder i vin, och sin mantel i vinbärs blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Hans ögon äro rödaktigare än vin, och hans tänder äro hvitare än mjölk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon skall bo vid hafshamnena, och vid skepphamnena, och sträcka sig intill Sidon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isaschar skall vara en benåsne, och lägra sig emellan gränsorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Och han såg rolighetena, att hon är god, och landet, att det är lustigt, och böjde sina härdar till att bära, och är vorden en skattskyldig tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan skall varda en domare ibland sitt folk, såsom ett annat slägte i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan skall varda en orm på vägenom, och en huggorm på stigenom, och bita hästen i foten, att den derpå rider, skall till rygga falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Herre, jag väntar efter dina helso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gud, väpnad, skall föra hären, och åter igen föran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Af Asser kommer hans feta bröd, och han skall gifva Konungenom kräselig mat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphthali är en snar hjort, och gifver kosteligit tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph skall tillväxa; han skall tillväxa likavisst som vid en källo: Döttrarna träda fram uti regementet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Och ändock skyttarne voro honom förbittrade, trätte med honom, och hatade honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Så är dock hans båge blifven fast, och hans händers armar äro förmannade, genom dess mägtiges händer i Jacob: Af honom äro komne herdar, stenar i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Ifrå dins faders Gud är dig kommen hjelp, och af den Allsmägtiga äst du välsignad med välsignelse ofvan efter af himlenom; med välsignelse af djupet, som under ligger; med välsignelse på bröst och qved.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Den välsignelse, som dinom fader och minom föräldrom lofvad är, går mägteliga efter deras önskan, som höge äro i verldene. Utaf Joseph skola hufvuden varda, och de öfverste Nazareer ibland sina bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'BenJamin är en glupande ulf. Om morgonen skall han äta rof, men om aftonen skall han utskifta rofvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Desse alle äro de tolf Israels slägter, och det är det, som deras fader hafver talat med dem, då han välsignade dem, hvar med sin besynnerliga välsignelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Och han böd dem, och sade till dem: Jag skall samkas till mitt folk; begrafver mig när mina fäder, i den kulone på Ephrons Hetheens åker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'I den dubbelkulone, som ligger emot Mamre i Canaans lande, hvilka Abraham köpte till en arfgrift med åkrenom af Ephron den Hetheen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Der hafva de begrafvit Abraham och Sara hans hustru: Der hafva de ock begrafvit Isaac och Rebecka hans hustru: Der hafver jag ock begrafvit Lea;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'I den åkrenom och de kulone, som af Heths barnom köpt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Och när Jacob hade lyktat buden till sin barn, lade han sina fötter samman på sängene, led af, och vardt samkad till sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Då föll Joseph in på sins faders ansigte, och gret, och kysste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Och Joseph befallte sina tjenare läkarena, att de skulle smörja hans fader: Och läkarena smorde Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Tilldess fyratio dagar voro förgångne; ty så länge varade smörjedagarna. Och de Egyptier begreto honom i sjutio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Då nu sörjedagarne ute voro, talade Joseph med Pharaos gårdsfolk, och sade: Hafver jag funnit nåd för eder, så taler med Pharao, och säger:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Min fader hafver tagit en ed af mig, och sagt: Si, jag dör; begraf mig i mine graf, som jag hafver grafvit mig i Canaans lande. Så vill jag nu fara upp och begrafva min fader, och komma igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Pharao sade: Far dit upp, och begraf din fader, som du honom svorit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Så for Joseph upp till att begrafva sin fader: Oh med honom foro alle Pharaos tjenare, de äldste af hans folk, och alle de äldste i Egypti lande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Dertill allt Josephs folk, och hans bröder, och hans faders folk; allena deras barn, får och fä lefde de i det landet Gosen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Och foro desslikes upp med honom vagnar och resenärer, och var en ganska stor skare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Då de nu kommo in på den planen Atad, som ligger in emot Jordan, då höllo de en ganska stor och bitter dödklagan; och han sörjde öfver sin fader i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Och då folket i landet, de Cananeer, sågo det sörjandet på den planen Atad, sade de: De Egyptier sörja der fast. Deraf kallar man det rummet de Egyptiers sorg; hvilket ligger in emot Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Och hans barn gjorde som han dem befallt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Och förde honom i Canaans land, och begrofvo honom i den dubbelkulone af åkren, som Abraham med åkrenom köpt hade till arfgrift af Ephron Hetheen, tvärt emot Mamre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Så for Joseph åter in i Egypten med sina bröder, och med allom dem, som voro farne upp med honom till att begrafva hans fader; när de hade begrafvit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Men Josephs bröder fruktade sig, då deras fader var död, och sade: Kanske, att Joseph är oss gramse, och måtte vedergälla oss det onda vi honom gjort hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Derföre läto de säga honom: Din fader gaf befallning för sin död, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Så skolen I säga till Joseph: Käre, förlåt dina bröder deras missgerning och synd, att de så illa hafva gjort emot dig. Käre, förlåt oss nu, som ärom dins faders Guds tjenare, denna missgerning. Men Joseph gret, då de sådant talade med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Och hans bröder gingo till, och föllo ned för honom, och sade: Si, vi äre dine tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Joseph sade till dem: Frukter eder icke, ty jag är under Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'I tänkten ondt öfver mig, men Gud hafver vändt det till godo, att han gjorde som för ögon är, till att frälsa mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Så frukter eder nu intet, jag vill försörja eder och edro barn. Och han stärkte dem, och talade vänliga med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Så bodde Joseph i Egypten med sins faders huse, och lefde hundrade och tio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Och såg Ephraims barn till tredje led: Föddes också barn på Josephs sköte, utaf Machirs barnom, hvilken Manasse son var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Och Joseph sade till sina bröder: Jag dör, och Gud varder eder sökandes, och förandes utaf detta landet, in uti det landet, som han hafver svorit Abraham, Isaac och Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Derföre tog han en ed af Israels barnom, och sade: När Gud varder eder sökandes, så förer min ben hädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Så dödde Joseph, då han var hundrade och tio år gammal. Och de smorde honom, och lade honom uti ena kisto i Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Desse äro namnen af Israels barn, som kommo in uti Egypten med Jacob; hvar och en kom der in med sitt hus:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi, Juda,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaschar, Zebulon, BenJamin,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, Naphthali, Gad, Asser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Och alla de själar, som utaf Jacobs länd utgångne voro, voro sjutio. Men Joseph var tillförene uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Då nu Joseph död var, och alle hans bröder, och alle de som på den tiden lefvat hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Växte Israels barn, och födde barn, och förökades, och vordo ganska månge, så att de uppfyllde landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Då vardt en ny Konung öfver Egypten, hvilken intet visste af Joseph.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Han sade till sitt folk: Si, Israels barns folk är mycket, och mera än vi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Nu väl, vi vilje listeliga förlägga dem, att de icke varda så månge. Ty om något örlig påkomme mot oss, måtte de ock gifva sig till våra fiender, och strida emot oss, och draga utu landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Och han satte öfver dem arbetsfogdar, som dem betvinga skulle med träldom; ty man byggde Pharao de städer Pithom och Raamses till skatthus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Men ju mer de betungade folket, ju mer de förökades och förvidgade sig; derföre voro de Israels barnom hätske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Och de Egyptier tvingade Israels barn med obarmhertighet till att träla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Och gjorde deras lefverne bittert, med svårt arbete på ler och tegel, och med allahanda släpande på markene, och med allahanda arbete, som de kunde dem pålägga med obarmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Och Konungen i Egypten sade till jordgummorna för de Ebreiska qvinnor; den ena het Siphra, och den andra Pua:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'När I hjelpen de Ebreiska qvinnor, och de skola föda; är det mankön, så dräper det; är det qvinnkön, så låter det lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Men jordgummorna fruktade Gud, och gjorde ej som Konungen i Egypten sade dem; utan läto barnen lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Då kallade Konungen i Egypten jordgummorna, och sade till dem: Hvarföre gören I det, att I låten lefva barnen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Jordgummorna svarade Pharao: De Ebreiska qvinnor äro ej som de Egyptiska; förty de äro hårda qvinnor; förr än jordgumman kommer till dem, hafva de födt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Derföre gjorde Gud väl emot jordgummorna; och folket förökades, och vardt ganska mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Och efter jordgummorna fruktade Gud, byggde han dem hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Då böd Pharao allo sino folke, och sade: Allt det mankön, som födt varder, kaster i älfvena, och allt qvinnkön låter lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Och en man gick bort af Levi hus, och tog ena Levi dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Och qvinnan aflade, och födde en son. Och då hon såg att det var ett dägeligt barn, fördolde hon det i tre månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Och då hon icke längre kunde fördölja det, tog hon ena kisto af rör, och beströk henne med ler och beck, och lade barnet deruti, och hof henne ut i vassen vid strandena af älfvene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Och hans syster stod långt ifrå, på det hon skulle se huru honom skulle varda gångandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Och Pharaos dotter kom ned, och skulle två sig i älfvene, och hennes jungfrur gingo utmed bräddene af älfvene; och då hon fick se kistona i vassenom, sände hon sina pigo dit, och lät hemta henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Och då hon upplyckte henne, fick hon se barnet, och si, barnet gret. Då ömkade hon sig deröfver, och sade: Detta är ett af de Ebreiska barnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Då sade hans syster till Pharaos dotter: Vill du, att jag går och kallar till dig ena Ebreiska qvinno, som dia gifver, att hon ammar dig barnet upp?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Pharaos dotter sade till henne: Gack. Pigan gick, och kallade barnsens moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Då sade Pharaos dotter till henne: Tag detta barnet, och amma mig det upp, jag vill löna dig. Qvinnan tog barnet, och ammade det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Och då barnet var stort vordet, antvardade hon det Pharaos dotter, och hon anammade honom för sin son, och kallade honom Mose, ty hon sade: Utu vattnet hafver jag tagit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'På den tiden, när Mose var stor vorden, gick han ut till sina bröder, och såg deras tunga; och vardt varse, att en Egyptisk man slog hans broder, en af de Ebreiska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Och han vände sig hit och dit, och då han såg, att der ingen menniska var, slog han den Egyptiska, och begrof honom uti sandenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'I den andra dagen gick han ock ut, och såg två Ebreiska män träta sinsemellan, och sade till den som orätt gjorde: Hvi slår du din nästa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Han svarade: Ho hafver gjort dig till höfvitsman eller domare öfver oss? Vill du ock slå mig ihjäl, såsom du hafver slagit den Egyptiska mannen? Då fruktade Mose, och sade: Huru är detta uppkommet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Och det kom för Pharao, och han sökte efter att dräpa Mose. Men Mose flydde för Pharao, och blef i Midians lande, och bodde vid en brunn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Men Presten i Midian hade sju döttrar; de kommo till att vinda vatten, och de uppfyllde hoar till att vattna sins faders får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Då kommo någre herdar, och drefvo dem ifrå; men Mose gaf sig upp, och halp dem, och vattnade deras får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Och då de kommo till sin fader Reguel, sade han: Hvi kommen I i dag snarare än I plägen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'De sade: En Egyptisk man halp oss för herdarna, och vand med oss vatten, och vattnade fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Han sade till sina döttrar: Hvar är han? Hvi läten I så blifva mannen, och icke båden honom komma och äta med oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Och Mose belefvade att blifva när den mannenom; och han gaf Mose sina dotter Zipora.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Hon födde honom en son, och han kallade honom Gerson; ty han sade: Jag är en utländning vorden i främmande lande. Och hon födde ännu en son, den kallade han Elieser, och sade: Mins faders Gud är min hjelpare, och hafver frälst mig utu Pharaos händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Någon tid derefter blef Konungen i Egypten död. Och Israels barn suckade öfver deras arbete, och ropade, och deras rop kom till Gud öfver deras släpan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Och Gud hörde deras klagan, och tänkte på sitt förbund med Abraham, Isaac och Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Och han såg dertill, och lät sig vårda om dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Men Mose vaktade sins svärs Jethro får, Prestens i Midian; och han dref fåren bak in i öknena, och kom till Guds berg Horeb.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Och Herrans Ängel syntes honom uti en brinnande låga utu buskanom. Och han såg, att busken brann af elden, och vardt dock icke förtärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Och sade: Jag vill gå dit, och bese denna stora synena, hvi busken icke uppbrinner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Då Herren såg, att han gick åstad till att se, kallade Gud honom utu buskanom, och sade: Mose, Mose. Han svarade: Här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Han sade: Träd icke hit, drag dina skor af dina fötter; ty rummet, der du står uppå, är ett heligt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Och han sade ytterligare: Jag är dins faders Gud, Abrahams Gud, Isaacs Gud och Jacobs Gud. Och Mose skylde sitt ansigte; ty han fruktade se uppå Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Och Herren sade: Jag hafver sett mins folks jämmer uti Egypten, och jag hafver hört deras rop öfver dem, som drifva dem; jag hafver förnummit deras vedermödo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Och är nederstigen till att frälsa dem utu de Egyptiers våld; och föra dem utu det landet, in uti ett godt och vidt land, som flytandes är med mjölk och hannog, såsom är på den platsen, som de Cananeer, Hetheer, Amoreer, Phereseer, Heveer och Jebuseer bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Så efter nu Israels barnas rop är kommet före mig, och jag dertill hafver skådat deras tvång, der de Egyptier dem med betvinga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Så gack nu, jag vill sända dig till Pharao, att du skall föra mitt folk Israels barn utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mose sade till Gud: Ho är jag, att jag gå skulle till Pharao, och föra Israels barn utur Egypten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Han sade: Jag vill vara med dig, och detta skall vara dig för ett tecken, att jag hafver sändt dig; då du hafver fört mitt folk utur Egypten, skolen I offra Gudi på desso bergena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mose sade till Gud: Si, när jag kommer till Israels barn, och säger till dem: Edra fäders Gud hafver sändt mig till eder; och de säga till mig: Hvad är hans namn? hvad skall jag säga dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Sade Gud till Mose: Jag skall vara den jag vara skall; och sade: Så skall du säga till Israels barn: Jag skall varat, han hafver sändt mig till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Och Gud sade ytterligare till Mose: Så skall du säga till Israels barn: Herren, edra fäders Gud, Abrahams Gud, Isaacs Gud och Jacobs Gud, hafver sändt mig till eder: Detta Namnet är mig evinnerliga; det skall vara min åminnelse ifrå barn och till barnabarn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Derföre gack åstad, och församla de äldsta af Israel, och säg till dem: Herren, edra fäders Gud, hafver synts mig, Abrahams Gud, Isaacs Gud och Jacobs Gud, och sagt: Jag hafver sökt eder, och sett hvad eder vederfaret är uti Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Och hafver sagt: Jag skall föra eder utu den Egyptiska jämmeren in uti de Cananeers, Hetheers, Amoreers, Phereseers, Heveers och Jebuseers land, uti det land, der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Och då de höra dina röst, skall du och de äldste af Israel gå in till Konungen i Egypten, och säga till honom: Herren, de Ebreers Gud, hafver kallat oss. Så låt oss nu gå tre dagsresor in uti öknena, till att offra Herranom vårom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Men jag vet, att Konungen i Egypten icke skall låta eder fara, utan genom stark under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Ty jag skall uträcka mina hand, och slå Egypten med allahanda under, som jag derinne göra skall; sedan skall han låta fara eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Och jag vill gifva desso folkena nåde för de Egyptier, att när I utfaren, skolen I icke utgå med tomma händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Utan hvar och en qvinna skall bedas af hennes grannqvinno och värdinno silfver och gyldene tyg, och kläder; dem skolen I lägga på edra söner och döttrar, och blotta de Egyptier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mose svarade, och sade: Si, de tro mig intet, ej heller höra mina röst, utan skola säga: Herren hafver intet synts dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Herren sade till honom: Hvad är det som du hafver i dine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Han sade: En staf. Han sade: Kasta honom ifrå dig på markena. Och han kastade honom ifrå sig, och han vardt vänd uti en orm; och Mose flydde för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Men Herren sade till honom: Räck dina hand ut, och tag honom om stjerten. Då räckte han sina hand ut, och höll honom; och han vändes uti en staf i hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Derföre skola de tro, att Herren hafver synts dig, deras fäders Gud, Abrahams Gud, Isaacs Gud och Jacobs Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Och Herren sade ytterligare till honom: Stick dina hand in i din barm. Och han stack henne i sin barm, och då han drog henne ut, si, då var hon spitelsk som en snö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Och han sade: Stick henne åter in i din barm. Och han stack henne åter in i barmen, och drog henne ut igen, si, så vardt hon åter som det andra hans kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Om de icke vilja tro dig, eller lyda hvad du säger af det ena tecknet, så varda de dock troende, när du säger dem af det andra tecknet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Om de icke tro dessa tu tecknen, icke heller höra dina röst, så tag vattnet utur älfvene, och gjut det ut på torra landet, så skall det samma vattnet, som du utur älfvene tagit hafver, varda blod på torra landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Då sade Mose till Herran: Ack Herre! Jag är en sådan man som icke talande är, allt från i går och förrgår, och ifrå den tid du med din tjenare talat hafver; ty jag hafver ett tungt mål och ena svåra tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Herren sade till honom: Ho hafver skapat menniskone munnen? Eller ho hafver gjort dumban, eller den döfva, eller den seende, eller den blinda? Hafver icke jag Herren gjort dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Så gack nu åstad, jag vill vara i dinom mun, och lära dig, hvad du säga skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Mose sade: Min Herre, sänd hvem du sända vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Då vardt Herren mycket vred öfver Mose, och sade: Vet jag icke, att din broder Aaron af Levi slägte är talande? Och si, han skall utgå emot dig, och då han får se dig, skall han glädja sig af hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Du skall tala till honom, och sätta orden i munnen på honom; och jag skall vara i dinom, och i hans munne, och lära eder, hvad I göra skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Och han skall tala för dig till folket; han skall vara din mun, och du skall vara hans gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Och denna staf tag i dina hand, dermed du tecken göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Så gick då Mose dädan, och kom igen till sin svär Jethro, och sade till honom: Käre, låt mig gå, att jag åter må komma till mina bröder, som äro uti Egypten, och se, om de ännu lefva. Jethro sade till honom: Gack i frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Och sade Herren till honom i Midian: Gack, och far åter in uti Egypten; förty de äro alle döde, som gingo efter ditt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Och så tog Mose sina hustru, och sina söner, och satte dem på en åsna, och for åter in uti Egypti land; och tog Guds staf i sina hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Och Herren sade till Mose: Se till, när du åter kommer in uti Egypten, att du gör all de under för Pharao, som jag under dina hand gifvit hafver. Men jag skall förstocka hans hjerta, att han icke skall släppa folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Och du skall säga till honom: Så säger Herren: Israel är min förstfödde son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Jag bjuder dig, att du låter min son fara, att han må tjena mig: Förvägrar du mig det, så skall jag dräpa din förstfödda son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Och vid han var på resone uti ett herberge, mötte honom Herren, och ville dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Då tog Zipora en sten, och skar sinom son förhudena af, och tog på hans fötter, och sade: Du äst mig en blodbrudgumme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Och så vände han igen af honom. Men hon sade blodbrudgumme, för omskärelsens skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Och Herren sade till Aaron: Gack ut emot Mose i öknena. Och han gick åstad, och mötte honom på Guds berge, och kysste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Och Mose sade Aaron all Herrans ord, den honom sändt hade, och alla de tecken, som han honom befallt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Och de gingo åstad, och församlade alla de äldsta af Israels barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Och Aaron talade all de ord, som Herren med Mose talat hade, och gjorde tecknen för folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Och folket trodde. Och då de hörde, att Herren hade sökt Israels barn, och sett uppå deras jämmer, föllo de neder, och tillbådo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Derefter gingo Mose och Aaron in, och sade till Pharao: Så säger Herren, Israels Gud: Släpp mitt folk, att de må hålla mig högtid uti öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Pharao svarade: Ho är Herren, hvilkens röst jag höra skall, och släppa Israel? Jag vet intet af Herranom, och vill ej heller släppa Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'De sade: De Ebreers Gud hafver kallat oss; så låt nu gå oss tre dagsresor in uti öknena, och offra Herranom vårom Gud, att oss icke öfvergå skall pestilentie eller svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Då sade Konungen i Egypten till dem: Hvi gören I så, du Mose och Aaron, att detta folket öfvergifver sitt arbete? Går bort till edart arbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Ytterligare sade Pharao: Si, folket är allaredo för mycket i landena; och I viljen ännu låta dem hålla upp af arbetena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Derefter böd Pharao på samma dag fogdomen öfver folket, och deras ämbetsmän, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'I skolen icke härefter hemta strå tillhopa, och få folkena till att bränna teglet, såsom tillförene; låter dem sjelfva gå bort och hemta sig strå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Och samma talet på teglet skolen I likväl lägga dem uppå, såsom tillförene, och intet mindre; förty de gå fåfänge. Derföre ropa de, och säga: Vi vilje gå och offra vårom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Man må väl förtunga dem med arbete, att de något hafva till skaffa, och icke akta lögnaktigt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Då gingo fogdarne öfver folket och deras ämbetsmän ut, och sade till folket: Så säger Pharao: Man skall intet strå få eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Går sjelfve bort och hemter eder strå, hvar I det finna kunnen; men af edart arbete skall intet afslås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Då förströdde sig folket kringom hela Egypti land, till att hemta sig stybbe, att de ju strå hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Och fogdarne drefvo dem, och sade: Fyller upp edart dagsarbete, lika såsom I haden strå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Och de ämbetsmän af Israels barn, hvilka Pharaos fogdar öfver dem satt hade, vordo slagne, och vardt sagdt till dem: Hvi hafven I icke hvarken i dag eller i går fullkomnat edart förelagda dagsarbete, såsom tillförene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Då gingo de ämbetsmän af Israels barn in, och ropade till Pharao: Hvi far du så med dina tjenare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Dinom tjenarom gifves intet strå, och skola dock göra det tegel, som oss förelagdt är; och si, dine tjenare varda slagne, och syndas uppå ditt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Pharao sade: I ären fåfänge, fåfänge ären I; derföre sägen I: Vi viljom gå och offra Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Så går nu bort, och görer edor dagsarbete. Strå skall eder intet gifvas; men talet på teglet måsten I leverera ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Då sågo ämbetsmännerne af Israels barn, att det vardt intet bättre, efter sagdt vardt: I skolen intet förminska af dagsarbetena på teglet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Och då Mose och Aaron gingo ifrå Pharao, stodo de i vägenom före dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Och sade till dem: Herren se uppå eder, och döme det, att I hafven gjort vår lukt illa luktandes för Pharao och hans tjenarom, och fått dem svärdet i händerna till att dräpa oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Mose kom igen till Herran, och sade: Herre, hvi gör du så illa emot detta folket? Hvi hafver du sändt mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Ty ifrå den tiden jag ingick till att tala med Pharao i ditt Namn, hafver han ännu hårdare plågat folket; och du hafver icke frälst ditt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Herren sade till Mose: Nu skall du se hvad jag skall göra med Pharao; ty genom en väldig hand måste han släppa dem; han måste ännu genom en starka hand drifva dem ifrå sig utu sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Och Gud talade till Mose, och sade till honom: Jag är Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Och hafver synts Abraham, Isaac och Jacob, att jag vill vara deras allsmägtige Gud; men mitt Namn Herre gjorde jag dem icke kunnigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Och gjorde jag mitt förbund med dem, att jag skulle gifva dem Canaans land; det land, der de uti vandrat hafva, der de främmande uti varit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Och hafver jag hört Israels barns suckan, hvilka de Egyptier med arbete förtunga; och hafver ihågkommit mitt förbund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Derföre säg Israels barnom: Jag är Herren, och vill taga eder utur edar tunga i Egypten, och förlossa eder ifrån edar träldom; och vill frälsa eder med uträcktom arme och storom dom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Och vill anamma eder för mitt folk, och vill vara edar Gud; att I förnimma skolen, att jag är Herren edar Gud, den eder utfört hafver utu de Egyptiers tunga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Och fört eder in uti det land, öfver hvilket jag hafver upphäfvit mina hand, att jag skulle det gifva Abraham, Isaac och Jacob; det vill jag gifva eder till eget, Jag Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Sådant allt sade Mose Israels barnom; men de hörde honom intet, för andans ångests skull, och för hårdt arbetes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Då talade Herren med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Gack in, och tala med Pharao, Konungenom i Egypten, att han släpper Israels barn ut af sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Men Mose talade för Herranom och sade: Si, Israels barn höra mig intet, huru skall då Pharao höra mig? Dertill hafver jag oomskorna läppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Och så talade då Herren till Mose och Aaron, och gaf dem befallning till Israels barn, och till Pharao, Konungen i Egypten, att de skulle utföra Israels barn utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Desse äro hufvuden till deras fäders hus. Rubens, dens första Israels sons, barn äro desse: Hanoch, Pallu, Hezron, Charmi; det är Rubens slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Simeons barn äro desse: Jemuel, Jamin, Ohad, Jachin, Zoar och Saul, den Cananeiska qvinnones son; det är Simeons slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Desse äro Levi barnas namn i deras slägter: Gerson, Kehat, Merari. Men Levi vardt hundrade tretio och sju år gammal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Gersons barn äro desse: Libni och Simei, i deras slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kehats barn äro desse: Amram, Jizear, Hebron, Usiel. Men Kehat vardt hundrade tretio och tre år gammal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Merari barn äro desse: Maheli och Musi. Det är nu Levi slägte i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Och Amram tog sina faders syster Jochebed till hustru; den födde honom Aaron och Mose. Och vardt Amram hundrade tretio och sju år gammal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Jizears barn äro desse: Korah, Nepheg, Sichri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Usiels barn äro desse: Misael, Elzaphan, Sithri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron tog sig hustru, Elizeba, Amminadabs dotter, Nahessons syster; den födde honom Nadab, Abihu, Eleazar, Ithamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Korahs barn äro desse: Assir, Elkana, Abiassaph. Det äro nu de Korhiters slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Men Eleazar, Aarons son, tog sig hustru af Putiels döttrar; den födde honom Pinehas. Desse äro nu hufvuden ibland fäderna till de Levitiska slägterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Desse äro Aaron och Mose, till hvilka Herren sade: Förer Israels barn utur Egypti land med deras härar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'De samme äro de, som talade med Pharao, Konungenom i Egypten, att de måtte utföra Israels barn utur Egypten, nämliga Mose och Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Och på den dagen talade Herren med Mose uti Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Och Herren sade: Jag är Herren; tala till Pharao, Konungen i Egypten, allt det jag talar med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Och han svarade för Herranom: Si, jag hafver oomskorna läppar, huru skall Pharao höra mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Herren sade till Mose: Si, jag hafver satt dig till en gud öfver Pharao; och Aaron din broder skall vara din Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du skall tala allt det jag bjuder dig; men Aaron din broder skall tala det för Pharao, att han släpper Israels barn utu sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Men jag vill förhärda Pharaos hjerta, på det jag skall göra min tecken och under mång uti Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Och Pharao skall intet höra eder, på det jag skall bevisa mina hand uti Egypten; och föra min här, mitt folk Israels barn utur Egypti land genom stora domar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Och de Egyptier skola förnimma att jag är Herren, när jag nu uträcker mina hand öfver Egypten, och utförer Israels barn ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mose och Aaron gjorde såsom Herren hade budit dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Och Mose var åttatio år gammal, och Aaron tre och åttatio år gammal, då de talade med Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Och Herren talade till Mose, och Aaron:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'När Pharao säger till eder: Beviser edor under; så skall du säga till Aaron: Tag din staf och kasta honom för Pharao, att han varder en orm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Då gingo Mose och Aaron in till Pharao, och gjorde såsom Herren hade budit dem. Och Aaron kastade sin staf för Pharao, och för hans tjenare; och han vardt en orm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Då lät Pharao kalla visa och svartkonstiga; och de Egyptiske trollkarlar gjorde ock sammalunda med deras besvärjningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Och hvardera kastade sin staf ifrå sig, och vordo ormar deraf; men Aarons staf uppslukte deras stafrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Så vardt Pharaos hjerta förstockadt, och hörde dem intet, såsom Herren sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Och Herren sade till Mose: Pharaos hjerta är hårdt, och vill icke släppa folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Gack till Pharao bittida om morgonen, si, han varder utgångandes till älfvena; så gack emot honom på strandena af älfvene, och tag stafven i dina hand, den som en orm vardt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Och säg till honom: Herren, de Ebreers Gud, hafver sändt mig till dig, och låter säga dig: Släpp mitt folk, att de må tjena mig uti öknene; men du hafver härtilldags intet velat höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Derföre säger Herren alltså: Deruppå skall du förnimma, att jag är Herren; si, jag vill med den stafven, som jag hafver i mine hand, slå vattnet, som i älfvene är, och det skall vändas i blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Så att fiskarne i älfvene skola dö, och älfven lukta; och de Egyptier skola vämja, när de dricka af vattnet i älfvene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Och Herren sade till Mose: Säg till Aaron: Tag din staf, och räck ut dina hand öfver vattnen i Egypten, öfver deras älfver, och strömmar, och sjöar, och öfver all vattukärr, att de varda blod; och vare blod i hela Egypti land, både i träkar och i stenkar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mose och Aaron gjorde, såsom Herren dem budit hade, och hof upp stafven, och slog i vattnet, som i älfvene var, för Pharao och hans tjenare; och allt vattnet i älfvene vardt vändt i blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Och fiskarne i flodene dogo, och älfven vardt luktandes, så att de Egyptier icke kunde dricka vattnet utur älfvene; och vardt blod i hela Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Och de Egyptiske trollkarlar gjorde ock sammalunda med deras besvärjningar; men Pharaos hjerta vardt förstockadt, och han hörde dem intet, såsom Herren sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Och Pharao vände om, och gick hem, och lade det ännu intet på hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Men alle Egyptier grofvo efter vatten utmed älfvene till att dricka; ty vattnet af älfvene kunde de icke dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Och det varade i sju dagar långt, sedan Herren slog älfvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Herren sade till Mose: Gack in till Pharao, och säg till honom: Detta säger Herren: Släpp mitt folk, att de måga tjena mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Hvar du icke vill, si, så vill jag plåga alla dina landsändar med paddor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Så att älfven skall uppvälla paddor; de skola uppstiga, och komma in i din hus, in i din kammar, in i ditt lägre, in i din säng, och in i dina tjenares hus, ibland ditt folk, in uti dina bakugnar, och uti din deg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Och paddor skola stiga uppå dig, och uppå ditt folk, och uppå alla dina tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Och Herren sade till Mose: Säg till Aaron: Räck ut dina hand med din staf öfver älfver, och strömmar, och sjöar, och låt paddor komma öfver Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Och Aaron räckte sina hand öfver vattnen i Egypten; och paddor kommo derut, så att Egypti land vardt öfvertäckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Då gjorde ock trollkarlarne sammalunda med deras besvärjningar; och läto komma paddor öfver Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Då kallade Pharao Mose och Aaron, och sade: Beder Herren för mig, att han tager paddorna ifrå mig, och ifrå mitt folk; så vill jag släppa folket, att de måga offra Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Mose sade: Haf du den ärona, och lägg mig före, när jag skall bedja för dig, för dina tjenare, och för ditt folk; att paddorna skola fördrefna varda ifrå dig, och ifrå ditt hus, och allenast blifva i älfvene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Han sade: I morgon. Han sade: Såsom du sagt hafver, på det du skall förnimma, att ingen är såsom Herren vår Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Så skola paddorna varda tagna ifrå dig, ifrå ditt hus, ifrå dina tjenare, ifrå ditt folk, och allena blifva i älfvene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Så gingo Mose och Aaron ifrå Pharao. Och Mose ropade till Herran för paddornas skull, såsom han Pharao tillsagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Och Herren gjorde, som Mose sagt hade. Och paddorna blefvo döda i husen, i gårdarna, och på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Och de kastade dem tillsamman, här en hop, och der en hop, och marken luktade derutaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Då Pharao såg, att han hade fått rolighet, vardt hans hjerta förhärdadt, och hörde dem intet, såsom Herren sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Och Herren sade till Mose: Säg till Aaron: Räck ut din staf, och slå i stoftet på jordene, att löss varda i hela Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'De gjorde ock så. Och Aaron räckte ut sina hand med sin staf, och slog i stoftet uppå jordene, och der vordo löss på menniskom, och på boskapen. Allt stoft på markene vardt löss i hela Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Trollkarlarne gjorde ock sammalunda med deras besvärjningar, att de skulle göra löss, men de kunde icke. Och lössen voro på menniskom, och på boskapen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Då sade trollkarlarne till Pharao: Detta är Guds finger. Men Pharaos hjerta vardt förstockadt, och han hörde dem intet, såsom Herren sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Och Herren sade till Mose: Statt upp bittida om morgonen, och gack för Pharao. Si, han varder utgångandes till vattnet, och säg till honom: Detta säger Herren: Släpp mitt folk, att de måga tjena mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Hvar icke, si, så vill jag låta komma allehanda ohyra öfver dig, dina tjenare, ditt folk, och ditt hus, så att all de Egyptiers hus, och marken, och hvad deruppå är, skola varda full af ohyro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Och vill jag på den dagen göra ett besynnerligit med den landsändan Gosen, der mitt folk uti är, att der skall ingen ohyra komma, på det du skall förnimma, att jag är Herren öfver hela jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Och vill en förlösning sätta emellan mitt folk och ditt. I morgon skall det tecknet ske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Och Herren gjorde så. Och der kom mycken ohyra uti Pharaos hus, i hans tjenares hus, och öfver hela Egypti land, och landet vardt förderfvadt af den ohyrone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Då kallade Pharao Mose och Aaron, och sade: Går åstad, och offrer edrom Gud här i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mose sade: Det betämmer sig icke, att vi så göre; förty vi offre Herranom vårom Gud de Egyptiers styggelse. Si, när vi nu de Egyptiers styggelse offrade för deras ögon, månde de icke skola stena oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Tre dagsresor vilje vi gå in uti öknena, och offra Herranom vårom Gud, såsom han oss sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Pharao sade: Jag vill släppa eder, att I må offra Herranom edrom Gud i öknene, allenast att I icke fjerran faren; och bedjen för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Mose sade: Si, när jag härut ifrå dig kommer, så vill jag bedja Herran, att denna ohyran må blifva borttagen ifrå Pharao, och hans tjenare, och hans folke, i morgon; allenast förhala mig icke länger, att du icke släpper folket till att offra Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Och Mose gick ut ifrå Pharao, och bad Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Och Herren gjorde, såsom Mose sagt hade, och tog de ohyrona bort ifrå Pharao, ifrå hans tjenare, och ifrå hans folke, så att icke en blef qvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Men Pharao förhärdade sitt hjerta ännu i denna resone, och ville icke släppa folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Herren sade till Mose: Gack in till Pharao, och säg till honom: Detta säger Herren de Ebreers Gud: Släpp mitt folk, att de måga tjena mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Hvar du icke vill, utan förhåller dem länger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Si, så skall Herrans hand varda utöfver din boskap på markene; öfver hästar, öfver åsnar, öfver camelar, öfver oxar, öfver får, med en ganska stor pestilentie.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Och Herren skall göra ett besynnerligit emellan de Israeliters boskap, och de Egyptiers; så att intet skall dö utaf allt det som Israels barn hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Och Herren lade en tid före, och sade: I morgon skall Herren göra detta på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Och Herren gjorde så om morgonen, och allahanda boskap blef död för de Egyptier; men af Israels barns boskap blef icke ett dödt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Och Pharao sände derefter, och si, der var icke ett blifvet dödt utaf Israels boskap. Men Pharaos hjerta vardt förstockadt, och släppte icke folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Då sade Herren till Mose och Aaron: Tager edra händer fulla med sot utaf skorstenen, och Mose stänke det upp åt himmelen för Pharao;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Att stoft skall komma öfver hela Egypti land, och bölder och ond sår varda på menniskor, och på boskap i hela Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Och de togo sotet utaf skorstenen, och stodo för Pharao, och Mose stänktet upp åt himmelen. Då vordo bölder och ond sår på menniskom, och på boskapen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Så att trollkarlarne icke kunde stå för Mose, för de bölders skull; ty på trollkarlarne voro ock så väl bölder, som på alla Egyptier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Men Herren förstockade Pharaos hjerta, så att han intet hörde dem, såsom Herren Mose sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Då sade Herren till Mose: Statt bittida upp om morgonen, och gack fram för Pharao, och säg till honom: Detta säger Herren de Ebreers Gud: Släpp mitt folk, att de måga tjena mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Annars vill jag i denna resone sända alla mina plågor öfver dig, öfver dina tjenare, och öfver ditt folk; att du skall förnimma, att i all land är ingen min like.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Förty nu vill jag uträcka mina hand, och slå dig och ditt folk med pestilentie, att du skall förgås af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Dock fördenskull hafver jag uppväckt dig, att min kraft skall synas på dig, och mitt Namn kunnigt varda i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Du förhåller ännu mitt folk, och vill icke släppat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Si, jag vill i morgon på denna tiden låta komma ett mägtigt stort hagel, hvilkets like icke varit hafver i Egypten, ifrå den tid det funderadt vardt, intill nu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Så sänd nu bort, och förvara din boskap, och allt det du på markene hafver; ty alla menniskor och boskap, som på markene funnen varder, och icke inhemtad är i husen, och haglet faller på dem, de blifva döde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Den som nu ibland Pharaos tjenare fruktade Herrans ord, han lät sina tjenare och boskap fly in i husen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Men hvilkas hjerta intet aktade Herrans ord, de läto deras tjenare och boskap blifva på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Då sade Herren till Mose: Räck dina hand upp åt himmelen, att det haglar öfver hela Egypti land; öfver menniskor, öfver boskap, och öfver all gröda på markene i Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Så räckte Mose sin staf upp emot himmelen, och Herren lät dundra och hagla, så att elden flög på jordene. Alltså lät Herren komma hagel öfver Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Att hagel och eld foro ibland hvartannat så grufveliga, att dess like icke varit hade i hela Egypti lande, ifrå den tid att det med folk besatt vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Och haglet slog i hela Egypti lande allt det på markene var, både menniskor och boskap, och slog allan grödan på markene, och sönderslog all trä på markene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Utan allena i det landet Gosen, der Israels barn voro, der haglade intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Då sände Pharao bort, och lät kalla Mose och Aaron, och sade till dem: Jag hafver i denna resone syndat; Herren är rättfärdig, men jag och mitt folk äre ogudaktige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Derföre beder Herran, att Guds dunder och hagel återvänder, så vill jag släppa eder, och icke länger förhålla eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mose sade till honom: När jag kommer utu stadenom, vill jag uträcka mina händer till Herran, så skall dundret återvända, och intet hagel mera vara; på det du skall förnimma, att jorden är Herrans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Dock vet jag väl, att du och dine tjenare icke ännu frukten för Herran Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Så vardt då slaget linet och bjugget; ty bjugget var i ax gånget, och linet hade knoppat sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Men hvetet och rågen vardt icke slaget; förty det var sensäd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Så gick då Mose ifrå Pharao ut af stadenom, och räckte sina händer ut till Herran; och dundret och haglet vände igen, och regnet dröp intet mer på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Då nu Pharao såg, att regnet, och dundret, och haglet vände igen, syndade han ändå ytterligare, och förhärdade sitt hjerta, han och hans tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Alltså vardt Pharaos hjerta förstockadt, att han icke släppte Israels barn, såsom Herren sagt hade genom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Och Herren sade till Mose: Gack in till Pharao; ty jag hafver förhärdat hans och hans tjenares hjerta, på det jag skall göra dessa min tecken ibland dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Och att du skall förkunna i din barnas öron, och din barnabarnas, hvad jag bedrifvit hafver i Egypten; och huru jag hafver bevisat min tecken ibland dem, att I skolen veta, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Så gingo Mose och Aaron in till Pharao, och sade till honom: Detta säger Herren de Ebreers Gud: Huru länge vill du icke ödmjuka dig för mig, att du släpper mitt folk till att tjena mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Vill du icke släppa mitt folk, si, så vill jag i morgon låta komma gräshoppor i alla dina landsändar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Så att de skola öfvertäcka landet, så att man icke skall se landet, och de skola uppäta hvad eder qvart blifvet och undsatt är för haglena, och skola uppäta all edor grödande trä på markene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Och skola uppfylla all din hus, och alla dina tjenares hus, och alla Egyptiers hus, hvilkas like dine fäder, och dina fäders fäder icke sett hafva, ifrå den tid de på jordena kommo, intill denna dag. Och han vände sig, och gick ut ifrå Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Då sade Pharaos tjenare till honom: Huru länge skole vi lida dessa plågor? Låt folket gå, att de måga tjena Herranom sinom Gud; vetst du icke ännu, att Egypten är förderfvad?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Så vordo Mose och Aaron igen kallade till Pharao, och han sade till dem: Går åstad, och tjener Herranom edrom Gud. Hvilke äro nu de som gå skola?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mose sade: Vi vilje gå med unga och gamla, med söner och döttrar, med får och fä; ty vi hafve en Herrans högtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Han sade till dem: Rätt så, Herren vare med eder. Skulle jag släppa eder och edor barn dertill? Ser der, om I icke hafven något ondt för händer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Icke så, utan I män går åstad, och tjener Herranom; ty det samma hafven I ock begärat. Och de drefvo dem ut ifrå Pharao.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Då sade Herren till Mose: Räck ut dina hand öfver Egypti land om de gräshoppor, att de komma öfver Egypti land, och äta allan grödan upp i landena, med allt det som qvart blifvet är efter haglet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Mose räckte sin staf öfver Egypti land, och Herren dref ett östanväder i landet i den hela dagenom, och i den hela nattene. Och om morgonen förde det östanvädret gräshopporna fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Och de kommo öfver hela Egypti land, och gåfvo sig ned allestäds i Egypten, så ganska många, att tillförene deras like intet varit hade ej heller härefter varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Förty de öfvertäckte landet, och gjorde det svart. Och de åto upp allan grödan i landena, och all frukt på trän, som qvar var blifven efter haglet, och läto intet grönt blifva qvart på trän, och uppå grödan på markene i hela Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Då kallade Pharao hasteliga Mose och Aaron, och sade: Jag hafver syndat emot Herran edar Gud, och emot eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Förlåter mig mina synder ännu i denna resone, och beder Herran edar Gud, att han dock borttager denna döden ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Och han gick ut ifrå Pharao, och bad Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Då vände Herren ett ganska starkt vestanväder, och upptog gräshopporna, och förde dem i röda hafvet; så att der icke blef en qvar någorstäds i hela Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Men Herren förstockade Pharaos hjerta, att han icke släppte Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Herren sade till Mose: Räck dina hand upp åt himmelen, att det varder så mörkt i Egypti land, att man må taga uppå det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Och Mose räckte sina hand upp åt himmelen; då vardt ett tjockt mörker i hela Egypti lande i tre dagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Så att ingen såg den andra, ej heller uppstod af det rummet, der han var, i de tre dagar. Men när alla Israels barn var ljust, der de bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Då kallade Pharao Mose, och sade: Går åstad, och tjener Herranom, allenast låter edor får och fä blifva här; låter ock edor barn gå med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mose sade: Du måste ock låta oss hafva offer och bränneoffer, det vi Herranom vårom Gud göra skolom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Vår boskap skall gå med oss, och icke en klöf tillbakablifva; förty af våro skole vi taga Herranom vårom Gudi till tjenst; ty vi vete icke, hvarmed vi skole tjena Herranom, tilldess vi komme dit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Men Herren förstockade Pharaos hjerta, att han icke ville släppa dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Och Pharao sade till honom: Gack ifrå mig, och tag dig vara, att du icke mer kommer för min ögon; ty hvilken dag du för mina ögon kommer, skall du dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mose svarade: Såsom du sagt hafver; jag vill ej mer komma för din ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Och Herren sade till Mose: Jag vill ännu låta komma ena plågo öfver Pharao och Egypten, sedan skall han släppa eder hädan; och skall ej allenast släppa eder, utan ock drifva eder hädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Så säg nu till folket, att hvar och en man bedes af sin nästa, och hvar och en qvinna af sine nästo, silfver och gyldene tyg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Ty Herren varder gifvandes folkena nåd för de Egyptier. Och Mose var en ganska myndig man i Egypti land, för Pharaos tjenare, och för folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Och Mose sade: Detta säger Herren: Jag vill på midnattstid utgå i Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Och allt det förstfödt är i Egypti land skall blifva dödt, ifrå Pharaos förstfödda son, den på hans stol sitter, allt intill tjensteqvinnones förstfödda son, som är vid qvarnena; och allt det förstfödt är ibland boskapen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Och ett stort rop skall vara i hela Egypti lande, hvilkets like icke varit hafver, ej heller varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Men när Israels barnom skall icke en hund krätta med sine tungo, ifrå menniskom, allt intill boskapen; på det I skolen förnimma, huru Herren åtskiljer Egypten och Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Då skola alle desse dine tjenare gå ned till mig, och falla mig till fota, och säga: Far ut, du och allt folket, som under dig är. Sedan vill jag fara ut. Och han gick ifrå Pharao ganska vreder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Men Herren sade till Mose: Pharao hörer eder intet, på det mycken under skola ske i Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Och Mose och Aaron gjorde all dessa under inför Pharao; men Herren förstockade honom hans hjerta, att han icke ville släppa Israels barn utu sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Herren sade till Mose och Aaron i Egypti lande:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Denne månaden skall vara när eder den förste månaden; och af honom skolen I begynna månaderna om året.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Taler till hela Israels menighet, och säger: På tionde dagen i denna månadenom tage hvar och en ett får, den en husfader är, ju ett får till huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Men der ett hus är för klent till ett får, så tage sin nästa granna vid sitt hus efter själarnas tal, som nog kunde vara till att förtära fåret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Och det skall vara ett får, som ingen vank hafver, en gummar och årsgammal. Af lambom eller kidom skolen I tagat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Och I skolen behållat intill fjortonde dagen i denna månadenom. Och hvar hopen i hela Israel skall slagtat till aftonen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Och skolen taga af dess blod och stryka på båda sidoträn åt dörrene, och öfra dörrträt i husen, der de äta det uti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Och skolen så äta köttet i den samma nattene, stekt vid eld, och osyradt bröd, och skolen ätat med bitter salso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'I skolen icke ätat rått, eller med vattne sudet; utan allena stekt vid eld, dess hufvud med dess fötter och inelfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Och I skolen intet låta qvart blifva till morgonen; om något blifver qvart till morgonen, skolen I det uppbränna med elde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Men så skolen I ätat: I skolen vara gjordade kringom edra länder, och hafva edra skor på edra fötter, och stafrar i edra händer; och I skolen ätat såsom de der hasta till vägs; ty det är Herrans Passah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Förty jag vill i den samma nattene gå genom Egypti land, och slå allt det förstfödt är i Egypti lande, både af menniskor och boskap, och bevisa mitt straff på alla de Egyptiers gudar, Jag Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Och blodet skall vara eder ett tecken på husen, der I uti ären, att, när jag ser blodet, skall jag gå framom eder; och eder icke vederfaras skall den plåga, som eder förderfva må, när jag slår Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Och I skolen hafva denna dagen till åminnelse; och I skolen hålla honom högtideligan Herranom till en fest; I och alle edra efterkommande i en evig brukning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'I sju dagar skolen I äta osyradt bröd, nämliga, på första dagenom skolen I upphålla med syradt bröd uti edor hus. Den som syradt bröd äter, ifrå första dagen, allt intill den sjunde, hans själ skall förgöras af Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Den förste dagen skall vara helig, att I sammankommen, och den sjunde skall ock vara helig, att I sammankommen; intet arbete skolen I göra på dem, utan det som till maten hörer för allahanda själar, det allena mågen I göra för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Och håller eder vid osyradt bröd; förty på den samma dagen hafver jag utfört edra härar utur Egypti land; derföre skolen I, och alle edre efterkommande, hålla denna dagen i en evig brukning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'På fjortonde dagen i första månadenom, om aftonen, skolen I äta osyradt bröd, intill en och tjugonde dagen i samma månadenom om aftonen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Så att man i sju dagar intet syradt bröd finner i edor hus; ty den som syradt bröd äter, hans själ skall förgöras utur Israels menighet, ehvad han är utländsk eller inländsk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Derföre äter intet syradt bröd, utan allenast osyradt bröd uti alla edra boningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Och Mose kallade alla de äldsta i Israel, och sade till dem: Leter ut och tager får, hvar och en för sitt husfolk, och slagter Passah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Och tager ett knippe isop, och dopper i blodet i bäckenet, och stryker dermed på öfra dörrträt, och båda sidoträn; och ingen menniska gånge ut genom sins hus dörr intill morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Förty Herren varder gångandes der framom, och skall plåga de Egyptier. Och när han får se blodet på öfra dörrträt och på de tu sidoträn, går Herren framom dörrena, och icke låter förderfvaren komma uti edor hus till att plåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Derföre håll denna seden för dig och din barn till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Och när I kommen in uti landet, det Herren eder gifvandes varder, såsom han sagt hafver, så håller denna tjenstena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Och när edor barn säga till eder: Hvad hafven I der för en tjenst?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Skolen I säga: Det är Herrans Passahoffer, den der gick framom Israels barn i Egypten, då han plågade de Egyptier, och frälste vår hus. Då bugade sig folket, och tillbad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Och Israels barn gingo bort, och gjorde såsom Herren Mose och Aaron budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Och om midnattstid slog Herren allt det förstfödt var i Egypti lande, ifrå Pharaos förstfödda son, den på hans stol satt, allt intill dens förstfödda son, som fången satt i fängelset, och allt förstfödt af boskapenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Då stod Pharao upp, och alle hans tjenare på den nattene, och alle Egyptier, och ett stort rop vardt uti Egypten; ty der var intet hus, der icke en döder inne låg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Och han kallade Mose och Aaron om nattene, och sade: Görer eder redo, och farer ut ifrå mitt folk, I och Israels barn; går åstad, och tjener Herranom, såsom I sagt hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Tager ock med eder edor får och fä, såsom I sagt hafven; går åstad, och välsigner mig med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Och de Egyptier trängde fast uppå folket, att de måste med hast drifva dem ut af landet; ty de sade: Vi dö hvar och en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Och folket bar råan deg, förra än han försyrad vardt, till deras mat, bundnan i deras kläder, på deras axlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Och Israels barn hade gjort såsom Mose sagt hade; och hade bedts af de Egyptier silfver, och gyldene tyg, och kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Och Herren hade gifvit folkena nåd för de Egyptier, så att de lånte dem; och de blottade de Egyptier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Så drogo Israels barn ut ifrå Rameses till Succoth, sexhundradetusend män till fot, förutan barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Och mycket gement folk drog också med dem; och får och fä, och ganska mycken boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Och de bakade af den råa degen, som de utur Egypten förde, osyrade kakor; ty han var icke syrad, efter de vordo utdrefne utur Egypten, och kunde icke förtöfva, och hade eljest ingen kost beredt sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Tiden, i hvilkom Israels barn bodde i Egypten, är fyrahundrade och tretio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Då de förlidne voro, gick hela Herrans här på en dag utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Derföre varder denna natten hållen Herranom, att han hafver fört dem utur Egypti land. Och Israels barn skola hålla henne Herranom, de och deras efterkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Och Herren sade till Mose och Aaron: Detta är sättet till att hålla Passah; ingen främling skall äta deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Den som en köpter träl är, den skall man omskära, och sedan äte han deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'En husman, och en dagakarl, skola intet äta deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Uti eno huse skall man ätat. I skolen intet af dess kött bära ut för huset, och I skolen intet ben sönderslå af thy.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Hela menigheten i Israel skall så göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Om någon främling bor när dig, och vill hålla Herranom Passah, han omskäre allt det mankön är, sedan gånge härtill, att han detta gör, och vare såsom en inländsker; ty ingen oomskoren skall äta deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Samma lagen vare dem inländska, och utländska, som bor ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Och all Israels barn gjorde såsom Herren hade budit Mose och Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Och så förde Herren på en dag Israels barn utur Egypti land, med deras härar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Helga mig allt förstfödt; det som allehanda moderlif öppnar när Israels barnom, både ibland menniskor och boskap; ty de äro min.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Då sade Mose till folket: Tänker uppå denna dagen, på hvilken I utgångne ären af Egypten, utu träldomsens huse; att Herren hafver eder hädan utfört med väldiga hand; derföre skall du icke äta surdeg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'I dag ären I utgångne i den månadenom Abib.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'När nu Herren låter komma dig in uti de Cananeers, Hetheers, Amoreers, Heveers och Jebuseers land, hvilket han dina fäder svorit hafver, att han ville gifva dig ett land, der mjölk och hannog uti flyter; så skall du denna tjenstena hålla i denna månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'I sju dagar skall du äta osyradt bröd, och på sjunde dagenom är Herrans högtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Derföre skall du i sju dagar äta osyradt bröd; så att när dig ingen surdeg, ej heller syradt bröd skall finnas i alla dina landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Och du skall säga dinom son på den tiden: Sådant hålle vi fördenskull, att Herren så hafver gjort med oss, då vi drogom utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Derföre skall dig vara ett tecken i dine hand, och en åminnelse för din ögon; på det att Herrans lag skall vara i dinom mun, att Herren hafver utfört dig af Egypten med väldiga hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Derföre håll denna seden i sinom tid årliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'När nu Herren hafver låtit dig komma in uti de Cananeers land, såsom han dig och dina fäder svorit hafver, och hafver dig det gifvit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Så skall du afskilja Herranom allt det som öppnar moderlifvet, och förstfödt är ibland boskapen; det som mankön är, skall höra Herranom till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Det förstfödda af åsnanom skall du lösa med ett får; om du icke löser det, så bryt halsen sönder på thy; men allt förstfödt af mennisko ibland din barn skall du lösa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Och när ditt barn frågar dig i dag eller i morgon: Hvad är detta? skall du säga thy: Herren hafver fört oss med väldiga hand utur Egypten, ifrå träldomsens huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Ty då Pharao var trög till att släppa oss, slog Herren allt det förstfödt var i Egypti lande, ifrå menniskones förstfödda, intill boskapens förstfödda; derföre offrar jag Herranom allt det som moderlifvet öppnar, det mankön är; och det, som förstfödt är af min barn, löser jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Och det skall vara dig för ett tecken i dine hand, och en åminnelse för din ögon, att Herren hafver fört oss med väldiga hand utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Då nu Pharao hade släppt folket, förde icke Gud dem på den vägen genom de Philisteers land, den genast var; ty han tänkte att folket måtte ångra sig, när de sågo örlig emot sig, och så omvända igen till Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Derföre förde han folket omkring på den vägen genom öknena åt röda hafvet; och Israels barn foro väpnade utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Och Mose tog med sig Josephs ben; ty han hade tagit en ed af Israels barnom, och sagt: Gud varder eder sökandes, så förer min ben hädan med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Så drogo de ut ifrå Succoth, och slogo deras lägre i Etam, närmast vid öknena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Och Herren gick före dem om dagen uti en molnstod, på det han skulle föra dem den rätta vägen; och om nattene uti en eldstod, på det han skulle lysa dem; till att vandra både dag och natt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Den molnstoden och eldstoden skiljdes intet ifrå folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Tala med Israels barn, och säg att de vända om, och slå deras lägre tvärtemot den dalen Hyroth, emellan Migdol och hafvet, emot BaalZephon, och der tvärt öfver slå lägret vid hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Förty Pharao varder sägandes om Israels barn: De fara ville i landena; öknen hafver beslutit dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Och jag vill förstocka hans hjerta, att han skall jaga efter dem, och vill vinna pris på Pharao och alla hans magt; och de Egyptier skola förnimma, att jag är Herren. Och de gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Och då det vardt sagdt för Konungenom i Egypten, att folket flydde, vardt hans och hans tjenares hjerta förvandladt emot folket, och sade: Hvi hafvom vi så gjort, att vi hafvom släppt Israel, att de icke skola tjena oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Och han gjorde redo sin vagn, och tog sitt folk med sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Och tog sexhundrade utvalda vagnar, och hvad der eljest var för vagnar i Egypten, och höfvitsmän öfver allan sin här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Ty Herren förstockade Pharaos hjerta, Konungens i Egypten, att han jagade efter Israels barn, hvilke dock voro genom höga hand utgångne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Och de Egyptier jagade efter dem, och hinde dem der de sig lägrat hade vid hafvet, med hästar och vagnar och resenärer, och med all Pharaos här, uti den dalenom Hyroth, tvärt emot BaalZephon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Och då Pharao nalkades dem, hofvo Israels barn sin ögon upp, och si, de Egyptier kommo efter dem; och de fruktade sig storliga, och ropade till Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Och sade till Mose: Voro icke grafvar i Egypten, att du måste bortföra oss, att vi skulle dö i öknene? Hvi hafver du så gjort oss, att du hafver fört oss utur Egypten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Är icke nu detta det, som vi sade dig i Egypten: Låt blifva oss, att vi må tjena de Egyptier? Ty det vore oss ju bättre tjena de Egyptier, än dö i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mose sade till folket: Frukter eder intet, står och ser till, hvilken en salighet Herren varder görandes i dag med eder; ty dessa Egyptier, som I sen i dag, dem skolen I aldrig mera se i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Herren varder stridandes för eder, och I skolen stå stilla dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Herren sade till Mose: Hvad ropar du till mig? Säg Israels barnom, att de draga fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Men du häf din staf upp, och räck dina hand öfver hafvet, och skilj det åt, att Israels barn måga gå der midt igenom på det torra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Si, jag vill förstocka de Egyptiers hjerta, att de skola följa efter eder; så vill jag vinna pris på Pharao, och alla hans magt, uppå hans vagnar och resenärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Och de Egyptier skola förnimma, att jag är Herren; när jag hafver pris vunnit på Pharao, och hans vagnar och resenärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Då upphof sig Guds Ängel, den som för Israels lägre gick, och gaf sig bakom dem; och molnstoden gaf sig ock utu deras ansigte, och gick bakom dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Och kom emellan de Egyptiers och Israels lägre; och det var ett mörkt moln, och upplyste nattena, så att desse och hine i den hela nattene icke kunde komma tillsamman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Då nu Mose räckte sin hand öfver hafvet, lät Herren drifva det bort genom ett starkt östanväder i den hela nattene, och gjorde hafvet torrt; och vattnet skiljdes åt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Och Israels barn gingo derin, midt i hafvet på det torra; och vattnet var dem för en mur på den högra sidone, och den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Och de Egyptier följde, och gingo in efter dem, alle Pharaos hästar och vagnar och resenärer, midt in i hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Som nu morgonväkten kom, såg Herren uppå de Egyptiers lägre utur eldstodene och molnena; och gjorde en förskräckelse i deras lägre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Och stötte hjulen ifrå deras vagnar, och störte dem väldeliga omkull. Då sade de Egyptier: Låt oss fly ifrån Israel; Herren strider för dem emot de Egyptier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Men Herren sade till Mose: Räck ut dina hand öfver hafvet, att vattnet igenfaller öfver de Egyptier; öfver deras vagnar och resenärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Då räckte Mose sina hand ut öfver hafvet, och hafvet kom åter för morgonen i sin ström igen; och då de Egyptier flydde, mötte dem vattnet; och Herren inhvärfde dem midt i hafvena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Så att vattnet kom igen, och gick utöfver vagnar och resenärer, och alla Pharaos magt, som dem efterföljt hade in i hafvet; så att icke en af dem blef igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Men Israels barn gingo torre midt igenom hafvet; och vattnet var dem för en mur på högra sidone, och den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Och så halp Herren Israel på den dagenom ifrå de Egyptiers hand; och de sågo de Egyptier döda på hafsstrandene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Och den stora hand, som Herren hade bevisat på de Egyptier. Och folket fruktade Herran, och trodde Herranom, och hans tjenare Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Då söng Mose och Israels barn Herranom denna visona, och sade: Jag vill sjunga Herranom; ty han hafver ena härliga gerning gjort; häst och man hafver han stört i hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Herren är min starkhet och lofsång, och är min salighet; han är min Gud, jag vill ära honom; han är mins faders Gud, och jag vill upphöja honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Herren är den rätte krigsmannen; Herre är hans namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Pharaos vagnar och hans magt kastade han i hafvet; hans utkorade höfvitsmän äro fördränkte i röda hafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Djupet hafver öfvertäckt dem; och de föllo åt bottnen såsom stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Herre, din högra hand gör stor under; Herre, din högra hand hafver slagit fiendan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Och med dine stora härlighet hafver du förstört dina motståndare; ty när du lät utgå dina grymhet, förtärde hon dem såsom strå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Genom ditt blåsande gåfvo sig vattnen upp, flytande vattnet stod ihop; djupen svallade ifrå hvartannat midt i hafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Fienden sade: Jag vill jaga efter dem, och gripa dem, och byta rof, och släcka mitt mod på dem; jag vill draga ut mitt svärd, och min hand skall förgöra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Då blåste ditt väder, och hafvet öfvertäckte dem; och de sönko ned såsom bly uti mägtig vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Herre, ho är din like ibland gudarna? Ho är dig lik, som är så härlig och helig, förfärlig, prislig och under görandes?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Då du uträckte dina hand, uppsvalg dem jorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du hafver i barmhertighet varit ledsagare åt dino folke, det du förlossat hafver; och hafver fört dem uti dine starkhet till dina helga boning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Då folken det hörde, bäfvade de; på de Philisteer kom ångest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Då förfärades de Förstar i Edom, bäfvan kom öfver de mägtiga i Moab; alle Canaans inbyggare gåfvo sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Låt kalla förskräckelse öfver dem, och fruktan, genom din stora arm, att de blifva orörlige såsom stenar; tilldess, Herre, ditt folk kommer igenom; tilldess ditt folk igenomkommer, det du förvärfvat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Led dem in, och plantera dem på dins arfvedels berge, hvilket du, Herre, till dina boning gjort hafver; till din helgedom, Herre, det din hand beredt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Herren varder rådandes i evighet och utan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Ty Pharao for in i hafvet med hästar och vagnar och resenärer, och Herren lät hafvet igenfalla öfver dem; men Israels barn gingo torre midt igenom hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Och MirJam den Prophetissan, Aarons syster, tog ena trummo uti sina hand; och alla qvinnor följde henne efter i dans med trummor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Och MirJam söng före dem: Låt oss sjunga Herranom, han hafver gjort ena härliga gerning; man och häst hafver han stört i hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Så lät Mose Israels barn draga ifrå röda hafvet, ut åt den öknen Sur; och de vandrade tre dagar i öknene, och funno intet vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Då kommo de till Mara; men de kunde icke dricka det vattnet i Mara; ty det var mycket bittert; af hvilko det rummet heter Mara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Der knorrade folket emot Mose, och sade: Hvad skole vi dricka?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Han ropade till Herran; och Herren viste honom ett trä, det satte han i vattnet, och så vardt det sött. Der satte han dem före lag och rätt, och försökte dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Och han sade: Vill du höra Herrans dins Guds röst, och göra hvad som rätt är för honom, och fatta hans bud i din öron, och hålla alla hans lag; så skall jag ingen den krankhet lägga uppå dig, som jag på de Egyptier lagt hafver; ty jag är Herren din läkare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Och de kommo till Elim, der voro tolf vattubrunnar, och sjutio palmträ; der lägrade de sig vid vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Ifrån Elim drogo de, och kom hele hopen Israels barn uti den öknena Sin, hvilken ligger emellan Elim och Sinai, på femtonde dagen i den andra månadenom, sedan de utur Egypti land gångne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Och hela menigheten af Israels barn knorrade emot Mose och Aaron uti öknene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Och sade till dem: Gud gifve, att vi hade dött uti Egypti lande genom Herrans hand, der vi såto vid köttgrytorna, och hade bröd nog till att äta; ty I hafven fördenskull fört oss i denna öknena, att I skolen låta denna hela hopen dö af hunger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Då sade Herren till Mose: Si, jag vill låta regna eder bröd neder af himmelen; och folket skall gå ut och församla hvar dag så mycket som behöfves, på det att jag må försöka, om de vilja vandra uti min lag eller ej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'På sjette dagenom skola de bereda sig till att församla dubbelt, öfver det de dageliga pläga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Mose och Aaron sade till Israels barn: Om aftonen skolen I förnimma, att Herren hafver fört eder utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Och om morgonen skolen I få se Herrans härlighet; ty han hafver hört edor knorran emot Herran. Hvad äre vi, att I knorren emot oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Ytterligare sade Mose: Herren varder eder gifvandes om aftonen kött till att äta, och om morgonen bröd tillfyllest; derföre att Herren hafver hört edor knorran, der I emot honom knorrat hafven. Ty hvad äre vi? Edart knorrande är icke emot oss, utan emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Och Mose sade till Aaron: Säg till hela menighetena af Israels barn: Går hit fram till Herran; ty han hafver hört edar knorran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Och då Aaron så sagt hade till hela menighetena af Israels barn, vände de sig emot öknena; och si, Herrans härlighet syntes uti en sky.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Och Herren sade till Mose:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Jag hafver hört Israels barns knorran; säg dem: Om aftonen skolen I hafva kött till att äta, och om morgonen varda mättade af bröd; och skolen förnimma, att jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Och om aftonen kommo åkerhöns upp, och öfvertäckte lägret; och om morgonen låg dagg omkring lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Och som daggen fallen var, si, då låg der något i öknene rundt och smått, såsom rimfrost på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Och då Israels barn sågo det, sade de till hvarannan: Detta är Man; ty de visste icke hvad det var. Men Mose sade till dem: Det är det brödet, som Herren eder gifvit hafver till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Det är det samma, om hvilket Herren budit hafver: Hvar och en församle deraf så mycket han äter för sig; och tage ett gomer till hvart och ett hufvud, efter själarnas tal i deras tjäll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Och Israels barn gjorde så, och församlade, den ene mycket, den andre litet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Men då man mätte det ut med gomer, vardt dem, som mycket hade, intet öfverlöpse, och dem som litet hade, fattades intet; utan hvar och en hade församlat så mycket, som han åt för sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Och Mose sade till dem: Ingen låte något qvart blifva deraf till morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Men de hörde Mosen intet, utan somlige läto något qvart blifva deraf intill morgonen; då växte der matkar uti, och vardt luktande; och Mose blef vred uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Så församlade de deraf hvar morgon så mycket, som hvar och en förmådde äta för sig; men när solen vardt het, så försmälte det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Och på sjette dagenom församlade de dubbelt af det brödet, ju tu gomer för en. Och alle de öfverste för menighetene kommo in, och förkunnade det Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Och han sade till dem: Detta är det som Herren sagt hafver: I morgon är Sabbath, den helga hvilan Herranom. Hvad I baka viljen, det baker, och hvad I koka viljen, det koker; men hvad öfver är, det låter blifva, att det varder förvaradt intill morgons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Och de läto blifvat till morgonen, såsom Mose budit hade; då vardt det intet luktande, och ingen matk vardt derutinnan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Då sade Mose: Äter det i dag; ty i dag är Herrans Sabbath; I varden i dag intet finnande på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'I sex dagar skolen I församlat; men sjunde dagen är Sabbath, på honom varder det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Men på sjunde dagenom gingo somlige ut af folket till att församla, och funno intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Då sade Herren till Mose: Huru länge viljen I icke hålla min bud och lag?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Si, Herren hafver gifvit eder Sabbath, och derföre hafver han gifvit eder på sjette dagenom tveggedaga bröd; så blifve nu hvar och en hemma, och ingen gånge ut ifrå sitt rum på sjunde dagenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Så skonade då folket den sjunde dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Och Israels hus kallade det Man; och det var såsom corianderfrö, och hvitt, och hade en smak såsom semla med hannog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Och Mose sade: Detta är det som Herren budit hafver; uppfyll ett gomer deraf, till att förvara för edra efterkommande; på det man må se det bröd, der jag eder med spisat hafver i öknene, då jag förde eder utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Och Mose sade till Aaron: Tag ett käril och låt der in ett gomer fullt med Man; och förvara det inför Herranom till edra efterkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Såsom Herren hade budit Mose, så lät Aaron förvara det der inför vittnesbördet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Och Israels barn åto Man i fyratio år, intilldess de kommo till det land, der de bo skulle; allt intill gränsona på Canaans land åto de Man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Och är gomer tionde parten af ett epha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Och hela menigheten af Israels barn drog ut af den öknene Sin deras dagsresor, såsom Herren befallde dem; och lägrade sig i Rephidim; der hade folket intet vatten till att dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Och de kifvade med Mose, och sade: Gifver oss vatten, att vi må dricka. Mose sade till dem: Hvi kifven I med mig? Hvi försöken I Herran?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Då nu folket dersammastäds törste efter vatten, knorrade de emot Mose, och sade: Hvi hafver du låtit oss fara utur Egypten, på det att du oss, vår barn och boskap, skulle låta dö i törst?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Mose ropade till Herran, och sade: Huru skall jag göra med detta folket? Det fattas icke mycket, att de varda mig ännu stenande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Herren sade till honom: Gack för folket, och tag några de äldsta af Israel med dig; och tag din staf i dina hand, med hvilkom du slog vattnet, och gack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Si, jag vill stå der före dig på ett hälleberg i Horeb; der skall du slå hälleberget, och der skall utlöpa vatten, så att folket får dricka. Mose gjorde ock så för de äldsta af Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Derföre kallar man det rummet Massa och Meriba; för det Israels barnas kifs skull, och för det, att de försökte Herran, och sade: Är Herren med oss, eller ej?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Då kom Amalek, och stridde emot Israel i Rephidim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Och Mose sade till Josua: Utvälj oss män; far ut, och strid emot Amalek; i morgon vill jag stå öfverst på högenom, och hafva Guds staf i mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Och Josua gjorde såsom Mose honom sade, att han stridde emot Amalek. Men Mose, och Aaron, och Hur stego upp öfverst på högen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Och så länge Mose upphöll sina händer, hade Israel öfverhandena; men när han lät händerna ned, hade Amalek öfverhandena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Men Mose händer voro tunga, derföre togo de en sten, och lade under honom, att han satte sig deruppå. Aaron och Hur höllo under hans händer, hvar på sine sido; så vordo hans händer stadiga, intilldess solen gick neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Och Josua nederlade Amalek, och hans folk, genom svärdsegg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Och Herren sade till Mose: Skrif detta till en åminnelse uti en bok, och befall det i Josua öron; ty jag skall förgöra Amalek undan himmelen, att man icke mer skall tänka uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Och Mose byggde ett altare, och kallade det Herren Nissi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Ty han sade: Herrans strid skall vara emot Amalek genom ena hand, under Guds beskärm ifrå barn intill barnabarn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Och då Jethro, Presten i Midian, Mose svär, hörde allt det Gud gjort hade med Mose och hans folk Israel, att Herren hade fört Israel utur Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Tog han Zipora, Mose hustru, den han hade tillbakasändt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Samt med hennes två söner; af hvilkom en het Gersom, ty han sade: Jag är vorden en utländning i främmande lande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Och den andre Elieser, ty han sade: Mins faders Gud hafver varit min hjelp, och hafver frälst mig ifrå Pharaos svärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Då nu Jethro, Mose svär, och hans söner, och hans hustru kommo till honom i öknene in på Guds berg, der han lägret uppslagit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Lät han säga Mose: Jag Jethro, din svär, är kommen till dig; och din hustru, och både hennes söner med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Då gick Mose ut emot honom, och böjde sig för honom, och kysste honom. Och då de hade helsat hvarannan, gingo de in i tjället.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Då förtäljde Mose sinom svär allt det Herren hade gjort Pharao och de Egyptier, för Israels skull; och all den mödo, som de på vägenom haft hade, och att Herren hade hulpit dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Och Jethro fröjdade sig öfver allt det goda, som Herren hade gjort Israel; att han hade frälst dem ifrå de Egyptiers hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Och Jethro sade: Lofvad vare Herren, den eder frälst hafver ifrå de Egyptiers och Pharaos hand; den der kan frälsa sitt folk ifrå Egypti hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nu vet jag, att Herren är större än alle gudar; derföre att de högmodeliga emot dem handlat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Och Jethro, Mose svär, tog bränneoffer, och offrade det Gudi. Då kom Aaron, och alle de äldste i Israel, till att äta bröd för Gudi med Mose svär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Den andra morgonen satte sig Mose till att döma folket; och folket stod omkring Mose ifrå morgonen intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Då hans svär såg allt det han gjorde med folkena, sade han: Hvad är det du gör med folkena? Hvi sitter du allena, och allt folket står omkring dig ifrå morgonen allt intill aftonen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mose svarade honom: Folket kommer till mig, och frågar Gud om råd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Ty då de hafva något att skaffa, komma de till mig, att jag skall döma emellan hvar och en och hans nästa; och visa dem Guds rätt, och hans lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Hans svär sade till honom: Det är icke godt som du gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du gör ovisliga; så ock folket, som med dig är. Detta ärendet är dig för svårt, du kan icke uträtta det allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Men hör mina röst; jag vill gifva dig råd, och Gud skall vara med dig. Sköt du folket inför Gud, och framsätt ärenden för Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Och förse dem med rätt och lag, att du visar dem den väg, der de uti vandra skola, och de gerningar, som de göra skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Men sök dig upp ibland allt folket redeliga män, de som frukta Gud, sannfärdiga, och de som hata girighetena; dem sätt öfver dem, somliga öfver tusende, öfver hundrade, öfver femtio, och öfver tio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'De som alltid måga döma folket; men när någon svår sak är, att de må hafva henne inför dig, och de åtskilja alla de ringa saker; så varder det dig lättare, och de dragat med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Om du det gör, kan du bestå hvad Gud dig bjuder; och allt detta folket kan gå hem till sitt igen med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mose hörde sins svärs röst, och gjorde allt, såsom han sade honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Och utvalde redeliga män utaf hela Israel, och gjorde dem till höfdingar öfver folket; somliga öfver tusende, öfver hundrade, öfver femtio, och öfver tio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Att de alltid skulle döma folket; men hvad svåra saker voro, dem sköto de till Mose; och de ringa saker dömde de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Och så lät Mose sin svär fara hem i sitt land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Uti tredje månadenom, sedan Israels barn utgångne voro utur Egypti land, kommo de på denna dagen in uti den öknen Sinai;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Förty de voro utdragne ifrå Rephidim, och ville in uti den öknen Sinai, och lägrade sig der i öknene, tvärtemot berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Och Mose steg upp till Gud. Och Herren ropade till honom af bergena, och sade: Detta skall du säga till Jacobs hus, och förkunna Israels barnom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'I hafven sett hvad jag hafver gjort de Egyptier; och huru jag hafver burit eder på örnavingar, och tagit eder till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Om I nu hören mina röst, och hållen mitt förbund, så skolen I vara min egendom för allt folk; ty hela jorden är min.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Och I skolen vara mig ett Presterligit Konungsrike, och ett heligt folk. Desse äro de ord, som du skall säga Israels barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Mose kom, och sammankallade de äldsta i folket, och framsatte all dessa orden för dem, såsom Herren budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Och allt folket svarade tillsammans, och sade: Allt det Herren sagt hafver, vilje vi göra. Och Mose sade folksens ord Herranom igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Och Herren sade till Mose: Si, jag vill komma till dig uti en tjock molnsky, att folket skall höra min ord, som jag talar med dig, och tro dig evärdeliga. Och Mose förkunnade Herranom folksens ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Herren sade till Mose: Gack bort till folket, och helga dem i dag och i morgon, att de två sin kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Och äro redo på tredje dagen; ty på tredje dagen varder Herren nederstigandes uppå Sinai berg för allo folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Och uppsätt tecken omkring folket, och säg till dem: Vakter eder, att I icke gån upp på berget, eller kommen vid ändan på thy; ty den som kommer vid berget, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Ingen hand skall komma vid honom, utan han skall varda stenad, eller med skott genomskjuten; ehvad det är djur eller menniska, skall det icke lefva. När man hörer ett långsamt ljud, skola de gå intill berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mose steg ned af berget till folket, och helgade dem, och de tvådde sin kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Och han sade till dem: Varer redo på tredje dagen; och ingen komme vid sina hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Som nu den tredje dagen kom, och morgonen vardt, då hof sig upp ett dunder och ljungeld, och en tjock molnsky på bergena, och ett ljud af en ganska skarp basun; och folket, som i lägret var, vardt förfäradt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Och Mose förde folket utu lägret emot Gud; och de gingo in under berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Och hela Sinai berg dambade deraf, att Herren steg neder uppå det i eld; och dess rök gick upp såsom röken af en ugn, så att hela berget bäfvade svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Och basunens ljud gick, och vardt ju starkare. Mose talade, och Gud svarade honom öfverljudt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Då nu Herren nederkommen var uppå Sinai berg ofvan uppå kullen, kallade Herren Mose upp på bergskullen; och Mose steg ditupp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Då sade Herren till honom: Gack neder, och betyga folkena, att de icke träda fram till Herran, att de skola se honom, och månge falla af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Desslikes Presterna, som nalkas Herranom, de skola ock helga sig, att Herren icke förgör dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mose sade till Herran: Folket kan icke stiga upp på berget Sinai; ty du hafver betygat oss, och sagt: Sätt tecken upp omkring berget, och helga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Herren sade till honom: Gack, stig ned; du och Aaron med dig skolen uppstiga. Men Presterna, och folket, skola icke träda intill, så att de uppstiga till Herran; på det han icke skall förgöra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Och Mose steg neder till folket, och sade dem detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Och Gud talade all dessa orden:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Jag är Herren din Gud, den dig utfört hafver af Egypti lande, utu träldomsens huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du skall inga andra gudar hafva jemte mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du skall icke göra dig något beläte; ej heller eljest någon liknelse, antingen efter det ofvantill är i himlenom, eller efter det nedre är på jordene; ej heller efter det, som i vattnena är under jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Bed icke till dem, och tjena dem icke; ty jag, Herren din Gud, är en stark hämnare, den som söker fädernas missgerning, inpå barnen, allt intill tredje och fjerde led, de som mig hata;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Och gör barmhertighet uppå mång tusende, som mig hafva kär, och hålla min bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du skall icke missbruka Herrans dins Guds Namn; ty Herren skall icke låta honom blifva ostraffad, som hans namn missbrukar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Tänk uppå Sabbathsdagen, att du helgar honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sex dagar skall du arbeta, och göra alla dina gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Men på sjunde dagenom är Herrans dins Guds Sabbath; då skall du intet arbete göra, ej heller din son, ej heller din dotter, ej heller din tjenare, ej heller din tjenarinna, ej heller din ök, ej heller din främling, som innan din stadsport är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Ty uti sex dagar hafver Herren gjort himmel och jord, och hafvet, och hvad derinne är, och hvilade på sjunde dagenom. Derföre välsignade Herren Sabbathsdagen, och helgade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Du skall ära din fader och dina moder; på det du skall länge lefva i landena, som Herren din Gud dig gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du skall icke dräpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du skall icke göra hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du skall icke stjäla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du skall icke bära falskt vittnesbörd emot din nästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du skall icke hafva lust till dins nästas hus. Du skall icke begära dins nästas hustru, ej heller hans tjenare, eller hans tjenarinno, ej heller hans oxa, ej heller hans åsna, ej heller något, det din näste hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Och allt folket såg dundret och ljungelden, och basunens ljud, och berget rykandes; och fruktade sig, och flydde, trädandes fjerran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Och sade till Mose: Tala du med oss, vi vilje höra dertill; och låt icke Gud tala med oss, att vi icke skole dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mose talade till folket: Frukter eder intet; ty Gud är kommen till att försöka eder; och att hans fruktan skall vara för edor ögon, att I icke synden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Och folket trädde långt ifrå; men Mose gick in till mörkret, der Gud uti var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Och Herren sade till honom: Så skall du säga Israels barnom: I hafven sett, att jag af himmelen hafver talat med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Derföre skolen I ingen ting hålla lika vid mig; silfvergudar och gyldene gudar skolen I icke göra eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Ett altare af jord gör mig, der du uppå ditt bränneoffer, och tackoffer, din får och fä offra skall; ty på hvad rum jag stiftar mins Namns åminnelse, der vill jag komma till dig, och välsigna dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Och om du vill göra mig ett stenaltare, skall du icke göra det af huggen sten; förty om du far deråt med din knif, så gör du det oskärdt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Du skall ock icke uppstiga på trappor till mitt altare, att din skam icke skall der blifva upptäckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Dessa äro de rätter, som du skall ditt folk föregifva:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Om du köper en Ebreisk träl, han skall tjena när dig i sex år; på sjunde årena skall han utgå fri och ledig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Är han allena kommen, så skall han ock allena utgå; är han kommen gifter, så skall hans hustru utgå med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Hafver hans herre gifvit honom hustru, och hon hafver födt söner eller döttrar, så skall hustrun och barnen höra herranom till, och han skall gå allena ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Om trälen säger: Jag hafver min herra, och min hustru, och min barn kär; jag vill icke varda fri;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Så hafve hans herra honom bort för gudarna, och hålle honom intill dörrena eller dörraträn; och borre honom igenom örat med en syl; och han vare hans träl evärdeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Om någor säljer sina dotter till en trälinno, så skall hon icke utgå såsom trälar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Behagar hon icke sinom herra, och han hafver ingom förlofvat henne, han skall låta henne fri; men till främmande folk hafver han ingen magt att sälja henne, efter han hafver försmått henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Gifver han henne sinom son, då skall han låta henne njuta dotters rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Gifver han honom ena andra, så skall han icke förvägra desso hennes kost, kläder och äktenskapsplikt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Gör han icke denna tre stycken, så skall hon fri utgå, och intet betala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Den som slår ena mennisko, så att hon dör, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Hafver han det icke gjort med vilja, utan Gud hafver låtit henne oförvarandes falla honom i händer, så skall jag sätta dig ett rum före, dit han fly skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Om någor går sin nästa efter med arghet, och dräper honom med försåt; den skall du taga ifrå mitt altare, så att man skall dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Den som sin fader eller moder slår, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Den som stjäl ena mennisko, och säljer henne, så att man finner honom dermed, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Den som bannar fader eller moder, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Der som någre män kifva tillhopa, och den ene slår den andra med en sten, eller med näfvan, så att han icke dör, utan ligger på sängene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Fås han vid, så att han utgår vid sin staf, så skall han, som slog honom, vara ursaker; undantagno, att han skall betala honom hvad han försummat hafver, och gifva honom hans läkarelön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Den sin träl eller trälinno slår med en staf, så att han dör under hans händer, han skall lida der straff före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Lefver han öfver en eller två dagar, så skall han icke lida der straff före; ty det är hans penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Om män kifva tillhopa, och någondera stöter någon qvinno, som hafvandes är, så att henne förgås barn, och henne dock eljest intet skadar; så skall man näpsa honom till penningar, så mycket som qvinnones man honom pålägger; och skall det utgifva efter mäklares känning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Skader henne något, då skall han gifva själ för själ,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Öga för öga, tand för tand, hand för hand, fot för fot,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brännande för brännande, sår för sår, blånad för blånad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Den som slår sin träl eller trälinno i ögat, och förderfvar det, han skall låta dem fri lös för ögat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Sammalunda, om han slår sin träl eller trälinno en tand ut, skall han dem fri lös låta för tandena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Om en oxe stångar en man eller qvinna, så att han dör, så skall man den oxan stena, och icke äta hans kött; och så är oxans herre ursaker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Var oxen tillförene van att stångas, och hans herre är derom tillsagd, och han icke bevarade honom, och deröfver dräper en man eller qvinno; så skall man stena den oxan, och hans herre skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Varda honom penningar pålagde, så skall han gifva till att lösa sitt lif så mycket, som honom pålagdt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Sammalunda skall man ock med honom handla, om han en son eller dotter stångar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Stångar han en träl eller trälinno, så skall han gifva deras herra tretio silfversiklar, och oxan skall man stena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Om någor öppnar ena grop, eller gräfver ena grop, och täcker henne icke till, och en oxe eller åsne faller så deruti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Då skall gropenes herre lösa det med penningar, och gifva dem dess herra igen; men kroppen skall vara hans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Om någors mans oxe stångar ens annars oxa, så att han dör; då skola de sälja den lefvande oxan, och byta penningarna, och desslikes byta kroppen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Var det vetterligit, att oxen var tillförene van att stångas, och hans herre icke bevarade honom; då skall han gifva en oxa för den andra, och behålla kroppen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Om någor stjäl en oxa eller ett får, och slagtar det, eller säljer, han skall igengifva fem oxar för en oxa, och fyra får för ett får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Om en tjuf beslagen varder, att han bryter sig in, och får hugg till döds; så skall ingen blodsrätt gå öfver dråparen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Men är solen öfver honom uppgången, då skall man blodsrätten gå låta. En tjuf skall igen betala. Hafver han intet, så skall man sälja honom för hans tjufnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Finner man tjufnaden när honom lefvande, det vare sig oxe, åsne eller får, så skall han gifva dubbelt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Om någor gör skada på åker eller vingård, så att han låter sin boskap skada göra uti ens annars åker; han skall af det bästa i sin åker och vingård igen betala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Om en eld uppkommer, och fånger i törne, så att skylarne eller säden, som ännu står, eller åkren uppbränd varder; det skall han betala igen, som elden släppt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Om någor får sinom nästa penningar, eller tyg till att gömma, och dem samma varder det stulet utu huset; finner man tjufven, då skall han gifva det tvefaldt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Finner man icke tjufven, så skall man hafva husvärden fram för gudarna; om han icke hafver kommit sina hand vid sins nästas ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Och om en den andra skyller för någon orätt, vare sig om oxa, eller åsna, eller får, eller kläder, eller hvad som helst bortkommet är, då skall begges deras sak komma inför gudarna; hvilken gudarne fördöma, han skall betala sinom nästa dubbelt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Om någor sätter neder när sin nästa, åsna, eller oxa, eller får, eller hvad boskap det kan vara, och det dör, eller eljest får skada, eller varder honom bortdrifvet, så att ingen ser det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Så skall det komma till en ed dem emellan vid Herran, att han icke hafver låtit komma sina hand vid hans nästas ting. Och äganden skall den anamma, att hin icke skall gifvat igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Om en tjuf stjäl honom det ifrå, skall han då betala det ägandenom igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Varder det rifvet, skall han hafva fram vittne deruppå, och så intet igengifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Om någor lånar af sin nästa, och det varder förderfvadt, eller dör, så att dess herre der icke när är, då skall han gifva det igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Är dess herre der när, då skall han icke gifva det igen; medan han det för sina penningar lejt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Om någor lockar ena jungfru, den ännu icke förlofvad är, och lägrar henne; han skall gifva henne hennes morgongåfvor, och hafva henne till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Om hennes fader försön honom henne, skall han då utgifva penningar, så mycket som jungfruers morgongåfvor tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'En trollkona skall du icke låta lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Den som hafver värdskap med någon boskap, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Den som offrar gudom, utan Herranom allena, han vare förbannad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Främlingar skall du icke beröfva eller undertrycka; förty I hafven ock varit främlingar i Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'I skolen ingen enko och faderlös barn bedröfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Bedröfvar du dem, så varda de ropande till mig, och jag skall höra deras rop;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Och min vrede skall förgrymma sig, så att jag dräper eder med svärd, och edra hustrur skola varda enkor, och edor barn faderlös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'När du lånar mino folke penningar, det fattigt är när dig, skall du icke hafva dig så med honom som en ockrare, och intet ocker på honom bedrifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'När du tager en klädnad till pant af din nästa, skall du få honom det igen, förra än solen går ned.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Förty hans klädnad är hans huds endesta öfvertäckelse, der han uti sofver. Ropar han till mig, så vill jag höra honom; ty jag är barmhertig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Gudarna skall du icke banna, och den öfversta i ditt folk skall du icke lasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Din fyllelse och tårar skall du icke fördröja. Din första son skall du gifva mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Så skall du ock göra med dinom oxa och får; i sju dagar låt det blifva när sine moder; på åttonde dagenom skall du gifva mig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'I skolen vara ett heligt folk för mig; derföre skolen I intet kött äta, det som på markene af djurom rifvet är, utan kasta det för hundarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du skall icke tro lögnaktigt tal, så att du gör enom ogudaktigom bistånd, och varder ett vrångt vittne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du skall icke följa hopen efter till det ondt är; och icke svara för rätten, så att du efter hopen viker ifrå det rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Du skall icke bepryda den fattiga i hans sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'När du finner dins oväns oxa eller åsna, att han far vill, så skall du ledan hem till honom igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'När du finner hans åsna, som dig hatar, ligga under bördone, skall du icke låta honom ligga, utan hjelpa honom upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du skall icke böja dins fattigas rätt i hans sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Var fjerran ifrå falska saker. Den oskyldiga och rättfärdiga skall du icke dräpa; ty jag gifver ingom ogudaktigom rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Du skall icke taga mutor; förty mutor förblinda de seende, och förvända de rättfärdigas saker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Du skall icke undertrycka främlingar; ty I veten huru de främlingar i hjertat likar, efter I hafven ock främlingar varit i Egypti lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'I sex år skall du så ditt land, och insamla dess frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'På sjunde årena skall du låta det hvilas och ligga, att de fattige af ditt folk måga äta deraf; och hvad öfver blifver, låt vilddjuren på markene äta det. Så skall du ock göra med dinom vingård och oljoberge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'I sex dagar skall du göra ditt arbete, men den sjunde dagen skall du skona; på det din oxe och åsne måga hvila sig, och dine tjenarinnos son, och främlingen vederqvicka sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Allt det jag eder sagt hafver, det håller. Och andra gudars namn skolen I icke ihågkomma; och af edar mun skola de icke hörde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'I tre resor om året skolen I hålla mig högtid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Nämliga de osyrade bröds högtid skall du hålla, att du i sju dagar osyradt bröd äter, såsom jag dig budit hafver, i den tiden i Abibs månad; förty uti honom äst du utfaren utur Egypten; men kom icke med tomma händer fram för mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Och den högtiden, när du först begynner berga det du på markene sått hafver; och insamlingens högtid i årsens utgång, när du ditt arbete utaf markene insamlat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Tre resor om året skall allt det mankön är komma fram för Herran Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du skall icke offra mitt offers blod med surdeg; och mins högtides feta skall icke blifva qvart intill morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Förstlingen af första frukten på dine mark skall du föra in uti Herrans dins Guds hus; och skall icke koka kidet, så länge det på sine moders mjölk är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Si, jag sänder en Ängel framföre dig, den dig skall bevara på vägen, och föra dig till det rum, som jag beredt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Derföre tag dig vara för hans ansigte, och hör hans röst, och förbittra honom icke; ty han skall icke skona eder, när I brottslige ären; och mitt Namn är i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Hörer du hans röst, och gör allt det jag säger dig, så skall jag vara dina fiendars fiende, och dina motståndares motståndare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'När nu min Ängel går framföre dig, och förer dig till de Amoreer, Hetheer, Phereseer, Cananeer, Heveer, och Jebuseer, och jag förgör dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Då skall du icke tillbedja deras gudar, ej heller tjena dem, och icke göra såsom de göra; utan skall deras afgudar bortkasta, och sönderslå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Men Herranom edrom Gud skolen I tjena, så skall han välsigna ditt bröd och ditt vatten; och skall alla krankhet taga dig ifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Ingen ensam eller ofruktsam skall vara i dino lande; och jag skall låta dig blifva gamlan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Jag skall sända min förskräckelse framföre dig, och göra allt folk förtvifladt, dit du kommer; och skall låta alla dina fiendar komma på flyktena för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Jag skall sända getingar framföre dig, som skola för dig utjaga de Heveer, Cananeer och Hetheer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Jag skall icke utdrifva dem på ett år för dig, att landet icke skall öde varda, och vilddjur föröka sig emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Tågliga skall jag drifva dem ut för dig, intilldess du må växa till, och besitta landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Och skall jag sätta ditt landamäre, det röda hafvet, till de Philisteers haf, och ifrån öknene allt intill älfvena; ty jag skall gifva landsens inbyggare i dina hand, att du skall utdrifva dem före dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du skall intet förbund göra med dem; eller med deras gudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Utan låt icke bo dem i dino lande, att de icke komma dig till att synda emot mig; förty, om du tjenar deras gudar, kommer det dig till förargelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Och till Mose sade han: Stig upp till Herran, du och Aaron, Nadab och Abihu, och de sjutio äldste i Israel, och tillbeder fjerran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Och Mose nalke sig allena intill Herran, och låt de andra intet nalkas; och folket komme ej heller med honom upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Mose kom, och förtäljde folkena all Herrans ord, och alla rätter. Då svarade allt folket med ena röst, och sade: All de ord, som Herren sagt hafver, vilje vi göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Då skref Mose all Herrans ord, och stod om morgonen bittida upp, och byggde ett altare nedan vid berget, med tolf stodar, efter de tolf Israels slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Och sände dit unga män af Israels barnom, att de skulle offra deruppå bränneoffer och tackoffer Herranom af stutar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Och Mose tog hälftena af blodet, och lät det uti ett bäcken; den andra hälftena stänkte han uppå altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Och tog förbundsens bok, och las henne för folksens öron. Och då de sade: Allt det Herren sagt hafver, vilje vi göra och efterlyda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Då tog Mose blodet, och stänkte folket dermed, och sade: Si, detta är förbundsens blod, hvilket Herren med eder gör öfver all dessa orden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Då stego Mose, Aaron, Nadab och Abihu, och de sjutio äldste af Israel upp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Och sågo Israels Gud. Under hans fötter var såsom en skön saphir, och såsom en himmel, då han klar är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Och han lät icke sina hand komma öfver de yppersta af Israel. Och då de hade skådat Gud, åto de och drucko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Och Herren sade till Mose: Kom upp till mig på berget, och blif der, att jag gifver dig stentaflor, och lag, och budord, de jag skrifvit hafver, hvilka du dem lära skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Då stod Mose upp och hans tjenare Josua, och steg upp på Guds berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Och sade till de äldsta: Blifver här, tilldess vi komme igen till eder; si, Aaron och Hur äro när eder; kommer någon sak på färde, den må I hafva inför dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Då nu Mose kom på berget, öfvertäckte en molnsky berget;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Och Herrans härlighet bodde uppå bergena Sinai, och öfvertäckte det med molnskyn i sex dagar. Och han kallade Mose på sjunde dagenom utu skynom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Och Herrans härlighets anseende var såsom en förtärande eld öfverst på bergena, för Israels barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Och Mose gick midt in i skyn, och steg på berget; och blef uppå bergena i fyratio dagar, och fyratio nätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Säg Israels barnom, att de gifva mig ett häfoffer; och tager det af hvar man, den som dertill ett frivilligt hjerta hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Och detta är häfoffret, som I skolen taga af dem: Guld, silfver, koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Gult silke, skarlakan, rosenrödt, hvitt tvinnadt silke, getahår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Rödlett vädurskinn, tackskinn, furoträ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Oljo till lampor, speceri till smörjelse, och godt rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Onichsten, och infattade stenar till lifkjortelen, och till skölden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Och de skola göra mig en helgedom, att jag må bo ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Efter som jag vill visa dig en eftersyn till tabernaklet, och till allt det som dertill hörer, så skolen I göra det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Görer en ark af furoträ; halftredje aln skall vara längden, halfannor aln bredden, och halfannor aln höjden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Och du skall bedraga honom med godt guld, innan och utan; och gör en gyldene krans ofvan omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Och gjut fyra ringar af guld; dem skall du sätta i alla fyra hörnen, så att två ringar äro på den ena sidone, och två på den andra sidone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Och gör stänger af furoträ, och bedrag dem med guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Och stick dem in i ringarna på sidone af arken, att man må bära honom dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Och skola de blifva i ringomen, och icke varda utdragna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Och du skall lägga uti arken det vittnesbörd, som jag skall få dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Du skall ock göra en nådastol af klart guld; halftredje aln skall vara längden på honom, och halfannor aln bredden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Och du skall göra två Cherubim af tätt guld, på båda ändarna af nådastolenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Så att en Cherub är på denna ändanom, den andra på den andra ändanom; och alltså äro två Cherubim på nådastolens ändom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Och de Cherubim skola uträcka sina vingar ofvan öfver, så att de öfvertäcka nådastolen med sina vingar, och hvarsannars anlete stå emot hvartannat; och deras anlete skola se uppå nådastolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Och du skall sätta nådastolen ofvanuppå arken; och lägga i arken det vittnesbörd, som jag skall få dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Och dädan vill jag betyga dig, och tala med dig, nämliga utaf nådastolenom, emellan de två Cherubim, som äro uppå vittnesbördsens ark, allt det som jag vill befalla dig till Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Du skall ock göra ett bord af furoträ; två alnar skall dess längd vara, och en aln bredden, och halfannor aln höjden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Och du skall bedraga det med klart guld, och göra en gyldene krans omkring det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Och ena listo omkring, en hand bredt hög, och en gyldene krans omkring listona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Och du skall göra der fyra gyldene ringar till, uppå de fyra hörnen på dess fyra fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Hardt under listone skola ringarna vara, att man må stinga stänger derin, och bära bordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Och du skall göra stängerna af furoträ, och bedraga dem med guld, att bordet må dermed varda buret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Du skall ock göra dess fat, skedar, kannor, skålar, af klart guld, att man dermed ut och in skänker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Och skall du alltid lägga skådobröd fram för mig på bordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Du skall ock göra en ljusastaka af klart tätt guld; läggen deruppå skall vara med rör, skålar, knöpar och blommor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Sex rör skola utgå på sidorna af ljusastakan, af hvarjo tre rör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Hvar och en rör skall hafva tre skålar, såsom mandelnötter, knöpar och blommor. Detta skola vara de sex rör, som utgå af ljusastakanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Men läggen af ljusastakanom skall hafva fyra skålar, och dertill knöpar och blommor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Och ju en knöp under två rör af de sex, som gå utaf ljusastakanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Ty både knöpar och rör skola gå derutaf; och alltsamman klart tätt guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Och du skall göra sju lampor ofvanuppå, så att de lysa emot hvarandra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Och ljusanäpor, och släcketyg, allt af klart guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Utaf en centener klart guld skall du göra honom, med all desse tyg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Och se till, att du allt gör efter den eftersyn, som du på bergena sett hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Tabernaklet skall du göra af tio tapeter, af hvitt tvinnadt silke, af gult silke, af skarlakan och rosenrödt; Cherubim skall du göra deruppå konsteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Längden på hvart tapetet skall vara åtta och tjugu alnar, bredden fyra alnar; och skola alla tio vara ens;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Och skola ju vara fem tillhopafogd, det ena vid det andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Och du skall göra lyckor af gult silke, allestädes på stadet på tapeten, att de måga tillhopafogas, att ju tu och tu på sitt stad kunna tillsammanfästas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Femtio lyckor på hvart tapetet, att det ena må fästas vid det andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Och du skall göra femtio gyldene häkte, der man de tapeter med tillsammanknäpper, det ena vid det andra, tilldess det blifver ett tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Du skall ock göra ellofva tapeter af getahår, till öfvertäckelse öfver tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Längden af hvart tapetet skall vara tretio alnar, bredden fyra alnar; och skola alla ellofva vara lika stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Fem skall du med hvartannat tillhopafoga, och sedan sex tillhopa med hvartannat, så att du gör det sjette tapetet dubbelt frammanför tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Och du skall göra femtio lyckor på stadet, af hvart tapetet, att de måga tillhopaknäppas med hvartannat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Och skall du göra femtio kopparhäkte, och knäppa häkten in uti lyckorna, att tapeten tillsammanfogas, och varda en täckelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Men det öfver är, i längdene af tapeten på tabernaklet, skall du hälftena låta hänga utöfver tabernaklet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'På båda sidor en aln långt; så att det öfver är, blifver på sidomen af tabernaklet, och betäcker det på båda sidor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Utöfver denna täckelse skall du göra en annor öfvertäckelse af rödlett vädurskinn; och dertill en öfvertäckelse af tackskinn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Du skall ock göra bräder till tabernaklet, af furoträ, hvilka stå skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Tio alnar långt skall hvart brädet vara, och halfannor aln bredt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Två nåckor skall hvart brädet hafva, så att det ena må sättas vid det andra; alltså skall du göra all bräden till tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Tjugu af dem skola stå söder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'De skola hafva fyratio silfverfötter nedan under, ju två fötter under hvart brädet på sina två nåckor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Sammalunda på den andra sidone, norrut, skola ock stå tjugu bräder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Och fyratio silfverfötter, ju två fötter under hvart brädet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Men bak i tabernaklet, vesterut, skall du göra sex bräder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Dertill tu bräder bak i de tu hörnen af tabernaklet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Så att hvartdera af de tu bräden lagar sig med sitt hörnebräde ifrå nedan allt uppåt, och komma ofvan tillika tillhopa med en krampo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Så att det äro åtta bräder med deras silfverfötter, hvilke skola vara sexton; ju två under ett bräde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Och du skall göra skottstänger af furoträ, fem till de bräden, som äro på den ena sidone i tabernaklet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Och fem till de bräden, som äro på den andra sidone i tabernaklet; och fem till de bräden bak i tabernaklet, vesterut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Och du skall skjuta medelstången midt öfver bräden utåt, och fatta dem alla tillhopa ifrå den ena ändan till den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Och skall du bedraga bräden med guld, och ringarna på dem göra af guld, att man skjuter stängerna derin; och stängerna skall du bedraga med guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Och så skall du nu göra tabernaklet, efter det sättet, som du sett hafver på bergena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Och du skall göra en förlåt af gult silke, skarlakan, och rosenrödt, och tvinnadt hvitt silke; och du skall göra Cherubim deruppå konsteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Och du skall hänga det på fyra stolpar af furoträ, de som bedragne äro med guld, och hafva gyldene knappar, och fyra silfverfötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Och skall du knäppa förlåten derintill med häkter, och sätta vittnesbördsens ark innanför förlåten, att han är eder en åtskilnad emellan det helga och det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Och du skall sätta nådastolen på vittnesbördsens ark, uti det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Men bordet sätt utanför förlåten, och ljusastakan tvärtöfver emot bordet, söderut i tabernaklet, så att bordet står norrut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Och skall du göra ett kläde i tabernaklets dörr, virkadt med gult silke, rosenrödt, skarlakan, och hvitt tvinnadt silke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Och skall du göra fem stolpar till det samma klädet af furoträ, öfverdragna med guld, med gyldene knappar; och du skall gjuta dem fem kopparfötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Och du skall göra ett altare af furoträ, fem alnar långt och bredt, så att det varder rätt fyrakant, och tre alnar högt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Horn skall du göra på alla fyra hörnen, och du skall öfverdraga det med koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Gör ock askokäril, skoflar, bäcken, gafflar, kolpannor; allt det dertill hörer, skall du göra af koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Du skall ock göra ett galler, såsom ett nät, af koppar, och fyra kopparringar på dess fyra hörn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Du skall ock görat ifrå nedan uppåt kringom altaret, så att gallret räcker midt uppå altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Och skall du göra stänger till altaret af furoträ, öfverdragna med koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Och skall du stinga stängerna in i ringarna, så att stängerna äro på båda sidor af altaret, der man må bära det med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Och skall du så görat af bräder, att det blifver ihålt, såsom dig på berget vist är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Du skall ock göra en gård till tabernaklet; en bonad af hvitt tvinnadt silke, på den ena sidon, hundrade alnar lång söderut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Och tjugu stolpar på tjugu kopparfötter; och deras knappar med deras gjordar af silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Sammalunda ock norruppå en bonad, hundrade alnar lång; tjugu stolpar på tjugu kopparfötter, och deras knappar med deras gjordar af silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Men vesterut öfver gårdsens bredd skall vara en bonad, femtio alnar lång; tio stolpar på tio fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Österut öfver gårdsens bredd skall vara femtio alnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Så att bonaden hafver på ene sidone femton alnar; dertill tre stolpar på tre fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Och femton alnar på den andra sidone; dertill tre stolpar på tre fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Men i gårdsens ingång skall vara ett kläde, tjugu alnar bredt, stickadt med gult silke, skarlakan, rosenrödt och hvitt tvinnadt silke; dertill fyra stolpar på deras fyra fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle stolparna kringom gården skola hafva silfvergjordar, och silfverknappar, och kopparfötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Och längden på gården skall vara hundrade alnar, bredden femtio, höjden fem alnar, af hvitt tvinnadt silke, och deras fötter skola vara af koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Och allt det som tabernaklet tillhörer till allahanda ämbete, och alle dess pålar, och alle gårdsens pålar, skola vara af koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Bjud Israels barnom, att de bära till dig den aldraklaresta oljo, stött af oljoträ, till lysning; att man alltid deraf låter i lamporna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Uti vittnesbördsens tabernakel utanför förlåten, som hänger för vittnesbördet. Och Aaron med hans söner skola detta sköta, ifrå morgonen allt intill aftonen för Herranom. Det skall vara eder en evig sed intill edra efterkommande, ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Och du skall taga till dig din broder Aaron, och hans söner utaf Israels barnom, att han skall vara min Prest, nämliga Aaron och hans söner, Nadab, Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Och du skall göra dinom broder Aaron helig kläder, som äro härlig och skön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Och du skall tala med allom dem, som ett vist hjerta hafva, de jag med vishetens anda uppfyllt hafver, att de göra kläder åt Aaron till hans vigelse, att han blifver min Prest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Och desse äro kläden, som de göra skola: Sköld, lifkjortel, silkeskjortel, trång kjortel, hatt och bälte; alltså skola de göra dinom broder Aaron, och hans söner, helig kläder, att han skall vara min Prest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Dertill skola de taga guld, gult silke, skarlakan, rosenrödt och hvitt silke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Lifkjortelen skola de göra af guld, gult silke, skarlakan, rosenrödt och tvinnadt hvitt silke, konsteliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Att han varder sammanfogd på båda axlar, och tillhopabunden på båda sidor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Och hans bälte deröfver skall vara af samma konst och verk; af guld, gult silke, skarlakan, rosenrödt, och tvinnadt hvitt silke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Och du skall taga två onichinerstenar, och grafva deruppå Israels söners namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'På hvardera sex namn, efter som de äro gamle till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Det skall du beställa med de stensnidare, som grafva insegler, så att de varda infattade i guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Och du skall fästa dem uppå axlarna på lifkjortelen, att de äro åminnelsestenar för Israels barn, att Aaron drager deras namn på båda sina axlar, till åminnelse för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Och du skall göra gyldene spänne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Och två kedjor af klart guld, som uppåt gå skola, dem skall du fästa uti spännen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Ämbetsskölden skall du göra efter konst, såsom lifkjortelen, af guld, gult silke, skarlakan, rosenrödt, och tvinnadt hvitt silke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Fyrahörnad skall han vara, och tvefald; en hand bredt skall vara hans längd, och en hand bredt hans bredd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Och du skall uppfyllat med fyra rader af stenar. Den första raden skall vara en sardius, topaz, smaragd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'Den andra en rubin, saphir, diamant;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Den tredje en lyncurer, achat, amethist;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Den fjerde en turkos, onich, jaspis. Uti guld skola de satte varda på alla rader;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Och skola stå efter de tolf Israels söners namn, utgrafne af stensnidare, hvardera med sitt namn, efter de tolf slägten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Och du skall göra kedjor till skölden, som nederåt gå, af klart guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Och två gyldene ringar, så att du fäster de två ringar vid de tu hörnen af skölden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Och låt komma de två gyldene kedjorna in uti de två ringarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Men de två ändarna af de två kedjor skall du låta komma in uti de tu spännen, och fästa dem på axlarna af lifkjortelen emot hvarannat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Och du skall göra två andra gyldene ringar, och fästa dem vid de andra tu hörnen af skölden, nämliga till sina brädd, der de utanpå lifkjortelen med hänga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Och skall åter göra två gyldene ringar, och fästa dem emot hvarannan utantill, nedre på de tu hörnen af lifkjortelen, der som lifkjortelen kommer tillhopa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Och man skall tillhopaknäppa skölden med sina ringar med ett gult snöre intill lifkjortelens ringar, så att han ligger hardt inpå lifkjortelen, och skölden icke lossnar ifrå lifkjortelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Så skall Aaron bära Israels barnas namn uti ämbetssköldenom på sitt hjerta, när han går in uti det helga; till en åminnelse för Herranom alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Och du skall låta Ljus och Fullkomlighet i ämbetsskölden, att de blifva på Aarons hjerta, när han ingår för Herranom; och bär Israels barnas ämbete på sino hjerta för Herranom alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Du skall ock göra under lifkjortelen en silkeskjortel, allsamman af gult silke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Och öfverst midt på honom skall vara ett halssmog; och en borda omkring halssmoget tillhopafållad, att det icke söndergår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Och nedanpå hans fåll skall du göra såsom granataäple af gult silke, skarlakan, rosenrödt, allt omkring, och emellan dem gyldene bjellror, ock allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Så att der är en gyldene bjellra, och dernäst ett granataäple, och åter en gyldene bjellra med ett granataäple, allt omkring på fållen af samma silkeskjortel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Och Aaron skall hafva honom uppå, när han tjenar, så att man hörer klanget af honom, när han ut och in går uti det helga för Herranom, på det att han icke skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Du skall ock göra ett ännespann af klart guld, och grafva deruti, efter stensnidarekonst: Herrans HELIGHET.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Och du skall fästa det på hatten, framman i ännet på Aaron, med ett gult snöre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Och det skall vara i Aarons änne, så att Aaron bär dess helgas brist, som Israels barn helga i allom sinom gåfvom och helgedom. Och det skall alltid vara på hans änne, att han skall försona dem Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Du skall ock göra en trång kjortel af hvitt silke, och en hatt af hvitt silke, och ett stickadt bälte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Och till Aarons söner skall du göra kjortlar, bälte och hufvor, som äro härlig och skön; och skall kläda dem uppå din broder Aaron med hans söner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Och skall smörja dem, och fylla deras händer, och viga dem, att de blifva mine Prester;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Och skall göra dem linnen nederkläder, till att skyla blygdenes kött, ifrå ländene allt ned på låren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Och Aaron med hans söner skola hafva dem uppå, när de gå in uti vittnesbördsens tabernakel, eller fram till altaret, till att tjena uti thy helga, på det att de icke umgälla deras missgerning, och måste dö. Det skall vara honom, och hans säd efter honom, ett evigt sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Detta måste du ock göra dem, att de skola varda mig vigde till Prester. Tag en ungan stut, och två vädrar utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Osyradt bröd och osyrade kakor, blandade med oljo, och osyrade tunnkakor, smorda med oljo; af hvetemjöl skall du allt görat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Och skall läggat uti en korg, och uti korgenom bära det fram, samt med stutenom, och de två vädrarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Och du skall hafva Aaron och hans söner fram för dörrena af vittnesbördsens tabernakel, och två dem med vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Och taga kläden, och kläda uppå Aaron den trånga kjortelen, och den silkeskjortelen, och lifkjortelen, och skölden till lifkjortelen, och skall begjorda honom utanuppå lifkjortelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Och sätta hatten uppå hans hufvud, och den helga kronona uppå hatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Och skall taga smörjoolja, och gjuta uppå hans hufvud, och smörja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Och hans söner skall du ock hafva fram, och kläda uppå dem den trånga kjortelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Och begjorda både Aaron och dem med bälter, och binda hufvorna på dem, att de skola hafva Presterskapet till ett evigt sätt. Och du skall fylla händerna uppå Aaron och hans söner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Och skall hafva stuten fram för dörrena af vittnesbördsens tabernakel. Och Aaron med hans söner skola lägga sina händer på hufvudet af stutenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Och du skall slagta stuten för Herranom, inför dörrena af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Och skall taga af hans blod, och stryka uppå altarens horn med ditt finger, och allt det andra blodet kasta neder på bottnen till altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Och skall taga allt det feta, som är på tarmarna, och det nätet öfver lefrena, och båda njurarna, med det feta som deruppå är, och skall bränna det upp på altarena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Men stutens kött, hudena och gåret, skall du uppbränna med eld utanför lägret; ty det är ett syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Men den ena väduren skall du taga; och Aaron med hans söner skola lägga deras händer på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Sedan skall du slagta honom, och taga hans blod, och stänka uppå altaret allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Men väduren skall du hugga i stycker, och två hans inelfver och fötter, och skall lägga det på hans stycker och hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Och bränna upp allan väduren på altaret; ty det är ett bränneoffer Herranom, en söt lukt Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Den andra väduren skall du taga; och Aaron med hans söner skola lägga sina händer på hans hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Och skall slagtan, och taga af hans blod, och stryka på högra örnatimpen af Aaron och hans söner, och uppå tumman af deras högra hand, och på största tån af deras högra fot, och skall stänka blodet på altaret allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Och skall taga blodet på altarena, och smörjooljo, och stänka på Aaron och hans kläder, hans söner och deras kläder; så varder han och hans kläder, hans söner och deras kläder vigd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Sedan skall du taga det feta af väduren, stjerten, och det feta som är på inelfven, nätet som är öfver lefrena, och båda njurarna med det feta, som deröfver är, och den högra bogen; ty det är fyllelsens vädur;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Och ett bröd, och en oljokako, och en tunnkako, utu korgenom, der det osyrade brödet i är, den för Herranom står.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Och lägg allt detta på Aarons och hans söners händer; och vefta det Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Och så skall du taga det utaf deras händer, och bränn det upp på altarena för ett bränneoffer, till en söt lukt för Herranom; ty det är Herrans offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Och du skall taga bröstet af fyllelsens vädur Aarons, och skall vefta det för Herranom; det skall vara din del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Och skall alltså helga veftebröstet och häfvobogarna, som veftade och häfne äro af fyllelsens vädur, Aarons och hans söners.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Och det skall vara Aarons och hans söners, till ett evigt sätt af Israels barnom; ty det är ett häfoffer; och häfoffren skola höra Herranom till af Israels barnom i deras tackoffer och häfoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Men Aarons helga kläder skola hans söner hafva efter honom, att de derutinnan skola varda smorde, och deras händer fyllda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Hvilken af hans söner varder Prest i hans stad, han skall kläda dem uppå i sju dagar, att han skall gå in uti vittnesbördsens tabernakel, till att tjena uti de helga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Du skall ock taga fyllelsens vädur, och koka hans kött på heligt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Och Aaron med hans söner skola äta af samma vädurs kötte, med brödet, som i korgenom är, inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Ty en försoning är dermed skedd, till att fylla deras händer, att de skola vigde varda. Ingen annar skall ätat; ty det är heligt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Om något öfverblifver af fyllelsens kötte, och af brödena intill morgonen, det skall du uppbränna på elde, och icke låta ätat; ty det är heligt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Och alltså skall du göra med Aaron och hans söner, såsom jag hafver budit dig. I sju dagar skall du fylla deras händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Och hvar dag slagta en stut, till ett syndoffer till försoning; och skall skära altaren, när du försonar det, och skall smörja det, att det skall blifva vigdt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'I sju dagar skall du försona och viga altaret, att det skall vara dess aldrahelgestas altare. Ho som vill komma vid altaret, han skall vara vigd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Och detta skall du göra med altaret; tu lamb årsgammal skall du hvar dag offra deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Ett lamb om morgonen, det andra om aftonen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Och till ett lamb en tiung semlomjöl, blandadt med en fjerding af ett hin stött oljo; och en fjerding af ett hin vin till drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Med det andra lambet om aftonen skall du göra såsom med morgonens spisoffer och drickoffer, till en söt lukt Herranom af offrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Detta är det dageliga bränneoffret intill edra efterkommande, för dörrene af vittnesbördsens tabernakel för Herranom, der jag eder betyga, och med dig tala vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Der vill jag Israels barnom betygad och helgad varda i mine härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Och vill helga vittnesbördsens tabernakel med altarena, och viga Aaron med hans söner mig till Prester;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Och vill bo ibland Israels barn, och vara deras Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Att de veta skola, att jag är Herren deras Gud, som dem förde utur Egypti land, att jag skulle bo ibland dem: Jag Herren deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Du skall ock göra ett rökaltare till rökning, af furoträ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'En aln långt och bredt, rätt fyrakant, och två alnar högt, med sin horn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Och skall öfverdraga det med klart guld, dess tak, och dess väggar allt omkring, och dess horn; och skall göra en krans af guld deromkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Och två gyldene ringar under kransen på båda sidor, att man må sätta der stänger uti, och bärat dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Stängerna skall du ock göra af furoträ, och med guld öfverdraga dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Och skall sätta det inför förlåten, som hänger för vittnesbördsens ark, och för nådastolen, som är på vittnesbördet; dädan vill jag betyga dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Och Aaron skall derpå röka godt rökverk hvar morgon, när han reder lamporna till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Sammalunda när han upptänder lamporna om aftonen, skall han ock röka sådana rök. Det skall vara den dageliga röken för Herranom när edra efterkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'I skolen ingen främmande rök göra deruppå, och intet bränneoffer, ej heller spisoffer, och intet drickoffer offra deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Och Aaron skall på dess horn försona en tid om året, med syndoffrens blod till försoning. Sådana försoning skall ske en gång årliga när edra efterkommande; ty det är Herranom det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'När du räknar hufvuden af Israels barn, då skall hvar och en gifva Herranom försoning för sina själ, på det dem icke skall vederfaras en plåga, när de räknade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Och skall hvar och en, som med är i talet, gifva en half sikel, efter helgedomsens sikel. En sikel gäller tjugu gera. Sådana half sikel skall vara Herrans häfoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Den som i talet är ifrå tjugu år och derutöfver, han skall gifva Herranom häfoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Den rike skall icke mer gifva, och den fattige icke mindre i dem halfva siklenom, som man gifver Herranom till ett häfoffer, för deras själars försoning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Och du skall sådana försonings penningar taga af Israels barnom, och lägga dem till Guds tjenste i vittnesbördsens tabernakel, så att det är Israels barnom en åminnelse för Herranom, att han låter försona sig öfver deras själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Du skall ock göra ett tvättekar af koppar med en kopparfot, till att två utaf; och skall sätta det emellan vittnesbördsens tabernakel och altaret, och låta der vatten uti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Att Aaron och hans söner två deras händer och fötter derutur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'När de gå in uti vittnesbördsens tabernakel, skola de tvätta sig med vatten, att de icke måga dö; eller då de nalkas till altaret, till att tjena Herranom med rökoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'De skola tvätta sina händer och fötter, på det att de icke skola dö. Det skall dem ett evigt sätt vara, honom och hans säd i deras efterkommandom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Tag dig aldrabästa speceri, aldraädlesta myrrham, femhundrade siklar, och canel halft så mycket, femtio och tuhundrad, och calamus desslikes femtio och tuhundrad,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Och casia femhundrad, efter helgedomsens sikel; och oljo af oljoträ ett hin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Och gör en helig smörjooljo efter apothekarekonst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Och du skall dermed smörja vittnesbördsens tabernakel; vittnesbördsens ark;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Bordet med all sin tyg; ljusastakan med sin tyg; rökaltaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Bränneoffersaltaret med all sin tyg; och tvättekaret med sin fot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Och skall alltså viga dem, att de blifva det aldrahelgasta; ty den som vill komma dervid, han måste vara vigd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Aaron och hans söner skall du ock smörja, och viga dem mig till Prester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Och du skall tala med Israels barn, och säga: Denna oljan skall vara mig en helig smörjelse när edra efterkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'På menniskokropp skall hon icke gjuten varda, och skall ej heller någon sådana göras; ty hon är helig, derföre skall hon vara eder helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Den som gör en sådana eller gifver enom androm deraf, han skall utrotad varda utu sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Och Herren sade till Mose: Tag dig speceri, balsam, stacten, galban, och rent rökelse, så mycket af det ena som af det andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Och gör der rökverk af efter apothekarekonst bemängdt, så att det är klart till helighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Och stöt det till pulfver, och du skall lägga det inför vittnesbördet, in uti vittnesbördsens tabernakel; dädan jag dig betyga skall. Det skall vara eder det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Och ett sådant rökverk skolen I icke göra eder; utan det skall vara dig heligt Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Den som ett sådant gör, till att röka dermed, den skall utrotad varda utu sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Si, jag hafver vid namn kallat Bezaleel, Uri son, Hurs sons, af Juda slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Och hafver fyllt honom med Guds Anda; med vishet och förstånd, och konst, och med allahanda verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Konsteliga till att arbeta på guld, silfver, koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Konsteliga utskära och insätta stenar, och konsteliga timbra på trä; till att göra allahanda verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Och si, jag hafver fått honom till hjelp Aholiab, Ahisamachs son, af Dans slägte; och hafver hvarjom och enom visom gifvit visdom i hjertat, att de göra skola allt det jag dig budit hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Vittnesbördsens tabernakel, vittnesbördsens ark, nådastolen deruppå, och all tabernaklens tyg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Bordet och dess tyg; den sköna ljusastakan och all hans tyg; rökaltaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Bränneoffersaltaret med all sin tyg; tvättekaret med sinom fot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Ämbetskläden, och de helga kläden Prestens Aarons, och hans söners kläder, till att tjena i Presterskapena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Smörjooljona och rökverk af speceri till helgedomen. Allt det jag hafver budit dig, skola de göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Tala till Israels barn, och säg: Håller min Sabbath; ty han är ett tecken emellan mig och eder, intill edra efterkommande, att I skolen veta, att jag är Herren, den eder helgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Derföre håller min Sabbath; ty han skall vara eder helig. Den som ohelgar honom, han skall döden dö; den som gör något arbete på honom, hans själ skall utrotad varda utu hans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sex dagar skall man arbeta; men på sjunde dagen är Sabbath, Herrans helga hvila. Den som något arbete gör på Sabbathsdagen, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Derföre skola Israels barn hålla Sabbath, att de med deras efterkommande hålla honom till ett evigt förbund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Han är ett evigt tecken emellan mig och Israels barn. Ty i sex dagar gjorde Herren himmel och jord, men på sjunde dagen höll han upp, och hvilte sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Och då han hade uttalat med Mose på Sinai berg, gaf han honom två vittnesbördsens taflor; de voro af sten, och skrifna med Guds finger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Då folket såg, att Mose fördröjde komma neder af bergena, församlade de sig emot Aaron, och sade till honom: Upp, och gör oss gudar, de som gå före oss; ty vi vete icke hvad dessom manne Mose vederfaret är, den oss fört hafver utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Aaron sade till dem: Rifver de gyldene örnaringar utur edra hustrurs öron, edra söners och edra döttrars, och bärer dem till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Då ref allt folket deras gyldene örnaringar utu deras öron, och båro dem till Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Och han tog dem af deras händer, och utkastade det med en grafstickel, och gjorde en gjuten kalf. Och de sade: Desse äro dine gudar, Israel, som dig utur Egypti land fört hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Då Aaron såg det, byggde han ett altare för honom, och lät utropa, och säga: I morgon är Herrans högtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Och de stodo om morgonen bittida upp, och offrade bränneoffer, och båro fram tackoffer. Sedan satte sig folket till att äta och dricka, och stodo upp till att leka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Då sade Herren till Mose: Gack, stig ned; ty ditt folk, som du utur Egypti land fört hafver, hafver förderfvat det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'De äro snarliga trädde ifrå de vägar, som jag dem budit hafver. De hafva gjort sig en gjuten kalf; och hafva tillbedit honom, och offrat honom och sagt: Desse äro dina gudar, Israel, som dig hafva fört utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Och Herren sade till Mose: Jag ser, att det är ett hårdnackadt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Och nu låt mig, att min vrede förgrymmar sig öfver dem, och uppfräter dem, så vill jag göra dig till ett stort folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Men Mose bad allvarliga inför Herran sin Gud, och sade: Ack! Herre, hvi vill din vrede förgrymma sig öfver ditt folk, det du med stora magt och väldiga hand utur Egypti land fört hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Hvi skulle de Egyptier tala, och säga: Han hafver fört dem ut till deras ofärd, på det han skulle dräpa dem i bergomen, och utskrapa dem af jordene? Vänd dig ifrå dine vredes grymhet, och var nådelig öfver dins folks ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Tänk uppå dina tjenare Abraham, Isaac och Israel, hvilkom du vid dig sjelf svorit hafver, och sagt dem: Jag skall föröka edra säd, såsom stjernorna i himlenom; och allt det landet, der jag om talat hafver, vill jag gifva edro säd, och de skola besitta det evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Så ångrade då Herren det onda, som han hotade att göra sino folke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mose vände sig, och steg ned af bergena, och hade två vittnesbördsens taflor i sine hand; de voro skrifna på båda sidor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Och Gud hade sjelf gjort dem, och sjelf skrifvit skriftena deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Då nu Josua hörde folkens skri, att de jubilerade, sade han till Mose: Ett krigsskriande är i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Svarade han: Det är icke ett skriande såsom af dem der vinna eller tappa; utan jag hörer ett skriande af qvädedansar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Som han nu kom intill lägret, och fick se kalfven, och dansen, förgrymmade han sig i vrede, och kastade taflorna utu sine hand, och slog dem sönder nedanför bergena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Och tog kalfven, som de gjort hade, och brände honom upp i eld, och gjorde honom till pulfver, och strödde det i vatten, och gaf det Israels barnom till att dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Och sade till Aaron: Hvad hafver folket gjort dig, att du hafver kommit dem en så stor synd uppå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron sade: Min herre låte sina vrede icke förgrymma sig; du vetst att detta folket är ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'De sade till mig: Gör oss gudar, som oss föregå; ty vi vete icke huru denna mannenom Mose går, den oss fört hafver utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Jag sade till dem: Den som guld hafver, han rifve det af, och få mig; och jag kastade det i eld, deraf är denne kalfven vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Då nu Mose såg, att folket var fritt (ty Aaron hade gjort dem fri, och dermed han dem förhöja ville, kom han dem på skam),');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Trädde han in i porten åt lägrena, och sade: Kommer hit till mig hvar och en, som Herranom tillhörer. Då församlade sig till honom alle Levi barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Och han sade till dem: Detta säger Herren Israels Gud: Binde hvar och en sitt svärd på sina länder; och går igenom lägret fram och åter, ifrå den ena porten till den andra, och dräpe hvar och en sin broder, frända och nästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Levi barn gjorde såsom Mose dem sade. Och föll i den dagen af folkena vid tretusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Då sade Mose: Fyller i dag edra händer Herranom, hvar och en på sin son och broder, att i dag må öfver eder välsignelse gifven varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Om morgonen derefter sade Mose till folket: I hafven gjort en stor synd. Nu, jag vill uppstiga till Herran, om jag tilläfventyrs kan försona edra synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Som nu Mose åter kom till Herran, sade han: Ack! detta folket hafver gjort en stor synd, och hafva gjort sig gyldene gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Nu förlåt dem deras synd; hvar icke, så skrapa mig ock utu dine bok, som du skrifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Herren sade till Mose: Huru? Den vill jag utskrapa utu mine bok, som syndar emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Så gack nu, och för folket dit, som jag hafver sagt dig; si, min Ängel skall gå före dig. Men på min sökningsdag skall jag söka deras synder öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Alltså plågade Herren folket, derföre att de hade gjort kalfven, hvilken Aaron gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Herren sade till Mose: Gack, drag hädan, du, och folket, som du utur Egypti land fört hafver, in uti det landet, som jag Abraham, Isaac och Jacob svorit hafver, och sagt: Dine säd vill jag gifva det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Och vill sända min Ängel före dig, och utdrifva de Cananeer, Amoreer, Hetheer, Phereseer, Heveer, och Jebuseer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'In uti det land, der mjölk och hannog uti flyter; ty jag vill icke draga upp med dig, förty du äst ett hårdnackadt folk; jag måtte tilläfventyrs i vägenom uppfräta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Då folket detta onda talet hörde, vordo de ångse; och ingen drog sin prydning på sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Och Herren sade till Mose: Säg till Israels barn: I ären ett hårdnackadt folk; jag varder en gång kommandes med hast öfver dig, och förgör dig. Och nu lägg dina prydning af dig, att jag må veta hvad jag skall göra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Så lade Israels barn deras prydning af sig, inför Horebs berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Så tog Mose tabernaklet, och slog det upp ute, långt ifrå lägret, och kallade det vittnesbördsens tabernakel. Och hvilken der något ville fråga Herran, han måste gå till vittnesbördsens tabernakel ut för lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Och när Mose gick ut till tabernaklet, så stod allt folket upp, och hvar och en trädde i sins tjälls dörr, och sågo efter honom, tilldess han kom in uti tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Och när Mose kom in uti tabernaklet, så kom molnstoden neder, och stod i tabernaklens dörr, och talade med Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Och allt folket såg molnstodena stå uti tabernaklens dörr; och stodo upp, och bugade sig hvar och en i sins tjälls dörr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Och Herren talade med Mose, ansigte mot ansigte, såsom en man talar med sin vän. Och när han vände om igen till lägret, gick icke hans tjenare, den unge mannen Josua, Nuns son, utu tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Och Mose sade till Herran: Si, du säger till mig: För mig detta folket upp; och du låter mig icke veta, hvem du vill sända med mig, och besynnerliga efter du sagt hafver: Jag känner dig vid namn, och du hafver funnit nåde för min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Hafver jag då funnit nåde för din ögon, så låt mig veta din väg, der jag af förnimma må, att jag finner nåde för din ögon; och se dock dertill, att detta folket är ditt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Han sade: Mitt ansigte varder gåendes, dermed vill jag leda dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Han sade till honom: Om ditt ansigte icke går, så låt oss intet komma hädan af detta rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Ty hvarpå skall det dock förnummet varda, att jag och ditt folk hafva funnit nåde för din ögon, utan då du går med oss; på det att jag och ditt folk måga varda något besynnerligit för allt folk, som på jordene är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Herren sade till Mose: Såsom du nu sade, så vill jag ock göra; ty du hafver funnit nåde för min ögon, och jag känner dig vid namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Men han sade: Låt mig då se dina härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Och han sade: Jag vill låta allt mitt goda gå framföre ditt ansigte, och vill låta predika Herrans Namn för dig. Men hvem jag är gunstig, honom är jag gunstig, och öfver hvem jag mig förbarmar, den förbarmar jag mig öfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Och sade ytterligare: Du kan icke se mitt ansigte; förty ingen menniska, som mig ser, kan lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Och Herren sade ytterligare: Si, här är ett rum när mig; der skall du stiga upp på klippona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'När då min härlighet går framom, vill jag sätta dig in i stenklyftona; och min hand skall hålla öfver dig, tilldess jag kommer framom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Och när jag tager mina hand af dig, skall du få se mig på baken; men mitt ansigte kan man icke se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Och Herren sade till Mose: Uthugg dig två stentaflor, sådana som de första voro, att jag skrifver de ord deruti, som i första taflomen voro, som du sönderslog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Och var redo i morgon, att du bittida stiger upp på Sinai berg, och träder der upp till mig öfverst på berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Och låt ingen stiga ditupp, med dig, att ingen varder sedder kringom hela berget; och låt ingen får eller fä beta in mot detta berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Och Mose uthögg sig två stentaflor, sådana som de första voro, och stod bittida upp om morgonen, och steg upp på Sinai berg, såsom Herren honom budit hade, och tog de två stentaflor i sina hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Då kom Herren neder uti ett moln. Och han trädde ditfram till honom, och åkallade Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Och då Herren gick framom för hans ansigte, ropade han: Herre, Herre Gud, barmhertig och nådelig, och långmodig, och af stor nåde, och trofast.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Du som bevarar nåde till tusende leder, och förlåter missgerningar, öfverträdelser och synder; och för hvilkom ingen är oskyldig, du som söker fädernas missgerningar på barn och barnabarn, allt intill tredje och fjerde led.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Och Mose böjde sig hasteliga neder på jordena, och bad till honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Och sade: Hafver jag, Herre, funnit nåd för din ögon, så gånge Herren med oss, förty det är ett hårdnackadt folk; att du varder vårom missgerningom och syndom nådelig, och låter oss vara ditt arfgods.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Och han sade: Si, jag vill göra ett förbund för allo dino folke, och vill göra undertecken, hvilkas like icke skapade äro i all land, och ibland all folk. Och allt folk, der du ibland äst, skall se Herrans verk; ty förskräckeligit skall det vara, som jag göra skall med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Håll det som jag bjuder dig i dag; si, jag vill utdrifva för dig de Amoreer, Cananeer, Hetheer, Phereseer, Heveer och Jebuseer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Tag dig vara, att du icke gör något förbund med landsens inbyggare, der du inkommer; att de icke varda dig till förargelse ibland dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Utan deras altare skall du omstörta, och slå sönder deras beläter, och deras lundar hugga ned;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Ty du skall icke tillbedja en annan gud; ty Herren heter en nitälskare, derföre att han är en nitälskande Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'På det att, om du gör något förbund med landsens inbyggare, och när de i horeri löpa efter sina gudar, och offra sina gudar, att de icke bjuda dig, och du äter af deras offer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Och tager dinom sönom deras döttrar till hustrur, hvilka i horeri löpa efter deras gudar, och komma dina söner ock till att löpa i horeri efter sina gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Du skall inga gjutna gudar göra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Osyradt bröds högtid skall du hålla; i sju dagar skall du äta osyradt bröd, såsom jag dig budit hafver, i Abibs månads tid; ty uti Abibs månad äst du utdragen utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Allt det som först öppnar moderlifvet, är mitt; det mankön är, i dinom boskap, det sitt moderlif öppnar, vare sig oxe eller får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Men åsnans förstföding skall du lösa med ett får; om du icke löser det, så bryt thy halsen sönder. Allt förstfödt af din barn skall du lösa; och att ingen kommer fram för mig med tomma händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sex dagar skall du arbeta; på sjunde dagen skall du hålla upp, både med plöjande och skärande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Veckohögtid skall du hålla med förstlingen af hveteskördene; och insamlingshögtid, när året ute är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tre resor om året skall allt ditt mankön komma fram för den allsmägtiga Herran och Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'När jag utdrifver Hedningarna för dig, och förvidgar dina landsändar, skall ingen åstunda efter ditt land, den stund du uppgår, tre resor om året, till att hafva dig fram för Herran din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du skall icke offra bloden af mitt offer på syradt bröd; och Påskahögtidenes offer skall icke blifva öfver nattena intill morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Förstlingen af den första frukten af dinom åker skall du föra in uti Herrans dins Guds hus. Du skall icke koka kidet, den stund det ännu på sins moders mjölk är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Och Herren sade till Mose: Skrif dessa orden; ty efter dessa orden hafver jag gjort ett förbund med dig, och med Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Och han var der när Herranom fyratio dagar och fyratio nätter, och åt intet bröd, och drack intet vatten; och han skref på taflorna detta förbund, de tio ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Då nu Mose gick ned af berget Sinai, hade han de två vittnesbördsens taflor i sine hand, och visste icke, att huden af hans ansigte sken, deraf att han hade talat med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Och då Aaron och all Israels barn sågo, att hans ansigtes hud sken, fruktade de nalkas honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Då kallade Mose dem; och till honom vände sig både Aaron, och alle de öfverste för menighetene. Och han talade med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Sedan nalkades all Israels barn intill honom; och han böd dem allt det Herren hade talat med honom på Sinai berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Och då han talade med dem, lade han ett täckelse på sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Och när han ingick för Herran till att tala med honom, lade han täckelset af, tilldess han gick åter ut igen; och när han kom ut, och talade med Israels barn det honom budet var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Så sågo de Israels barn på hans ansigte, huru hans ansigtes hud sken; så drog han åter täckelset öfver ansigtet, tilldess han gick åter in igen till att tala med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Och Mose församlade hela menighetena af Israels barn, och sade till dem: Detta är det som Herren budit hafver, att I göra skolen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'I sex dagar skolen I arbeta; men den sjunde dagen skolen I hålla heligan, Herrans hvilos Sabbath. Den som något arbete gör på honom, han skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'I skolen ingen eld upptända på Sabbathsdagenom i alla edra boningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Och Mose sade till alla menighetena af Israels barn: Detta är det Herren budit hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Gifver ibland eder häfoffer Herranom, alltså att hvar och en frambär häfoffer Herranom af ett fritt hjerta, guld, silfver, koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Gult silke, skarlakan, rosenrödt, hvitt silke, och getahår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Rödlett vädurskinn och tackskinn, furoträ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Oljo till lamporna, och speceri till smörjoolja, och till godt rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Onich och infattade stenar till lifkjortelen, och till skölden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Och den ibland eder förståndig är, han komme och göre hvad Herren budit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Nämliga tabernaklet med dess täckelse och öfvertäckelse; ringar, bräder, skottstänger, stolpar och fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'Arken med hans stänger; nådastolen och förlåten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Bordet med sina stänger, och all dess tyg och förlåten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'Ljusastakan till att lysa, och hans redskap, och hans lampor, och oljo till lysning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Rökaltaret med sina stänger, smörjooljan, och speceri till rökverk; klädet för tabernaklets dörr;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Bränneoffersaltaret med dess koppargallrar, stänger och all sin redskap; tvättekaret med sin fot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Bonaden till gården, med sina stolpar och fötter; och klädet till dörrena åt gårdenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Pålarna till tabernaklet och till gården, med deras tåg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Ämbetskläden till tjensten i det helga; de helga kläder till Presten Aaron, med hans söners kläder till Presterskapet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Då gick hela menigheten af Israels barn ut ifrå Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Och alle de som gerna och välviljeliga gåfvo, kommo och båro det fram till ett häfoffer Herranom, till vittnesbördsens tabernakels verk, och till all dess tjenste, och till de helga kläden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Både man och qvinna båro fram, hvilken som helst dertill hade vilja, spänner, örnaringar, ringar och spann, och allahanda gyldene redskap; bar ock hvar man fram guld, till veftoffer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Och den som när sig fann gult silke, skarlakan, rosenrödt, hvitt silke, getahår, rödlett vädurskinn och tackskinn, han bar det fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Och den som silfver eller koppar hof, han bar det fram Herranom till häfoffer. Och den som fann furoträ när sig, han bar det fram till allahanda Gudstjenstens verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Och de der förståndiga qvinnor voro, de virkade med sina händer, och båro sitt verk fram af gult silke, skarlakan, rosenrödt, och hvitt silke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Och de qvinnor, som skickeliga voro, de virkade getahår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Men förstarna båro fram onich, och infattade stenar till lifkjortelen och till skölden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Och speceri och oljo till lysning, och till smörjo, och till godt rökverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Alltså båro Israels barn fram Herranom friviljoge, både män och qvinnor, till allahanda verk, som Herren budit hade genom Mose, att göras skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Och Mose sade till Israels barn: Ser, Herren hafver kallat Bezaleel vid namn, Uri son, Hurs sons, af Juda slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Och hafver uppfyllt honom med Guds Anda, att han är vis, förståndig, och skickelig till allahanda verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Till att konsteliga arbeta på guld, silfver och koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Snida, och insätta ädla stenar; till att timbra af trä; till att göra allt konsteligit arbete;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Och hafver gifvit honom undervisning i hans hjerta; samt med Aholiab, Ahisamachs son, af Dans slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Han hafver uppfyllt deras hjerta med vishet, till att göra allahanda verk, till att snida, virka och sticka, med gult silke, skarlakan, rosenrödt, och hvitt silke, och med väfvande, så att de göra allahanda verk, och konsteligit arbete påfinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Då arbetade Bezaleel och Aholiab, och alle vise män, de som Herren hade gifvit vishet och förstånd till att veta, huru de allahanda verk göra skulle, till den tjenst, som helgedomen tillhörde, efter allt det som Herren budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Och Mose kallade Bezaleel och Aholiab, och alla visa män, dem Herren hade gifvit vishet i deras hjerta; nämliga alla de som välviljeliga tillbödo sig, och gingo dertill, till att arbeta på verket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Och de togo till sig af Mose alla häfningar, som Israels barn frambåro, till den tjenst, som helgedomen tillkrafde, att det skulle blifva gjordt; ty de båro hvar morgon deras viljoga hjelp till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Då kommo alle de vise, som arbetade på helgedomens verk, hvar och en af sitt verk, som de gjorde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Och sade till Mose: Folket bär allt för mycket till, mer än till denna tjenstenes verk behöfves, som Herren budit hafver att göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Då böd Mose, att utropas skulle i lägren: Ingen gifve mer till helgedomens häfning. Så vände folket igen att frambära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Ty der var allaredo nog till allahanda verk, som görandes var, och ändå utöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Och så gjorde alle vise män ibland arbetarena på verket, tabernaklet, tio tapeter, af hvitt tvinnadt silke, gult silke, skarlakan, rosenrödt, Cherubim konsteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Längden af hvart tapetet var åtta och tjugu alnar, och bredden fyra alnar, och de voro all vid ena måtto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Och han häktade tillhopa ju fem tapeter, det ena vid det andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Och gjorde gula lyckor på hvart tapetens stad, der de vordo tillhopafogde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Ju femtio lyckor på hvart tapetet, der det ena det andra med fattade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Och gjorde femtio gyldene häkte, och tillhopafogade det ena tapetet med det andra med häkten; så att det vardt ett tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Och han gjorde ellofva tapeter af getahår till öfvertäckelse öfver tabernaklet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Tretio alnar lång, och fyra alnar bred; all vid ena måtto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Och fogde fem af dem tillhopa på en del;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Och sex tillhopa på den andra delen; och gjorde ju femtio lyckor på hvart tapetet vid stadet, dermed de vordo tillsammanknäppte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Och gjorde ju femtio kopparhäkte, der samma tapeter med tillhopafogdes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Och gjorde ett täckelse öfver detta täckelset af rödlett vädurskinn; och öfver det ännu ett täckelse af tackskinn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Och gjorde bräder till tabernaklet af furoträ, som stå skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Hvartdera tio alnar långt, och halfannor aln bredt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Och uppå hvartdera två nåckor, der de med vordo tillhopasatte; så gjorde han all bräden till tabernaklet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Att tjugu af dem stodo på södra sidone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Och gjorde fyratio silfverfötter derunder; under hvart brädet två fötter, till två sina nåckor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'På den andra sidone af tabernaklet, som var nordantill, gjorde han ock tjugu bräder,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Med fyratio silfverfötter; under hvart brädet två fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Men bak i tabernaklet på vestra sidone gjorde han sex bräder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Och tu annor på de tu hörnen af tabernaklet baktill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Så att hvartdera af de båda parade sig med sitt hörnebräde ifrå nedan uppåt, och kommo tillhopa ofvantill med en krampo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Så att bräden vordo åtta, och silfverfötterna sexton; under hvart två fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Och gjorde han skottstänger af furoträ; fem till bräden på den ena sidone af tabernaklet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Och fem på den andra sidone; och fem bak vestantill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Och gjorde skottstångena, så att hon öfver bräden allt bortåt skjuten vardt, ifrå den ena ändan till den andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Och öfverdrog bräden med guld. Men deras ringar gjorde han af guld till skottstängerna, och öfverdrog stängerna med guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Och gjorde Cherubim på förlåten konsteliga af gult silke, skarlakan, rosenrödt, och hvitt tvinnadt silke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Och gjorde till den samma fyra stolpar af furoträ, och öfverdrog dem med guld, och deras knappar af guld, och göt dertill fyra silfverfötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Och gjorde ett kläde uti tabernaklets dörr, stickadt af gult silke, skarlakan, rosenrödt, och hvitt tvinnadt silke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Och fem stolpar dertill med deras knappar, och öfverdrog deras knappar och gjordar med guld; och fem kopparfötter dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Och Bezaleel gjorde arken af furoträ, halftredje aln lång, halfannor aln bred och hög;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Och öfverdrog honom med klart guld innan och utan; och gjorde honom en gyldene krans omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Och göt fyra gyldene ringar till hans fyra hörner; på hvarje sidone två;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Och gjorde stänger af furoträ, och öfverdrog dem med guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Och satte dem uti ringarna på sidone af arken, så att man kunde bära honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Och han gjorde nådastolen af klart guld, halftredje aln lång, och halfannor aln bred;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Och gjorde två Cherubim af tätt guld, på båda ändarna af nådastolenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'En Cherub på denna ändan; en annan på den andra ändan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Och de Cherubim uträckte sina vingar ofvan öfver, och öfverskylde dermed nådastolen, och deras anlete stodo tvärtemot hvarsannars; och sågo på nådastolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Och han gjorde bordet af furoträ, två alnar långt, en aln bredt, och halfannor aln högt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Och öfverdrog det med klart guld, och gjorde der en gyldene krans omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Och gjorde der ena listo omkring; ena hand bredt hög, och gjorde en gyldene krans omkring listona;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Och göt dertill fyra gyldene ringar; och satte dem på de fyra hörnen uppå dess fyra fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Hardt under listone, så att stängerna voro deruti, der man bordet med bar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Och gjorde stängerna af furoträ, och öfverdrog dem med guld, att man skulle bära bordet dermed;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Och gjorde desslikes, af klart guld, redskapen på bordet, fat, skedar, kannor och skålar, der man med ut och in skänkte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Och gjorde ljusastakan af klart tätt guld; derpå voro läggen, rör, skålar, knöpar och blommor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Sex rör gingo ut af sidorna, på hvarjo sidone tre rör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Tre skålar, såsom mandelnötter, voro på hvar rör, med knöpar och blommor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Men på ljusastakanom voro fyra skålar med knöpar och blommor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Inunder två rör en knöp, så att sex rör gingo ut af honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Och hans knöpar och rör deruppå; och var allt klart tätt guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Och gjorde de sju lampor, med deras ljusanäpor och släcketyg, af klart guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Af en centner guld gjorde han honom, och all hans tyg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Han gjorde ock rökaltaret af furoträ, en aln långt och bredt, rätt fyrakant, och två alnar högt med sin horn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Och öfverdrog det med klart guld, dess tak och väggar allt omkring, och dess horn, och gjorde der en krans omkring af klart guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Och två gyldene ringar under kransen på båda sidor, så att man satte stängerna deruti, och bar det dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Men stängerna gjorde han af furoträ, och öfverdrog dem med guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Och gjorde den helga smörjooljan, och rökverk af rent speceri, efter apothekarekonst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Och han gjorde bränneoffersaltaret af furoträ, fem alnar långt och bredt, rätt fyrakant, och tre alnar högt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Och gjorde fyra horn, som utgingo af fyra hörnen, och öfverdrog dem med koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Och gjorde allahanda redskap till altaret, tråg, skoflar, bäcken, eldgafflar, kolpannor; allt af koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Och gjorde på altaret ett galler, såsom ett nät omkring, af koppar, ifrå nedan uppåt, intill halfväges på altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Och göt fyra ringar på de fyra hörnen af koppargallret till stängerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Dem gjorde han af furoträ, och öfverdrog dem med koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Och satte dem in uti ringarna på sidone af altaret, att man bar det dermed; och gjorde det ihålt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Och gjorde tvättekaret af koppar, och dess fot ock af koppar, tvärtemot härarna, som för dörrene af vittnesbördsens tabernakel lågo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Och gjorde han en gård, på södra sidone en bonad, hundrade alnar lång, af tvinnadt hvitt silke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Med hans tjugu stolpar och tjugu fötter af koppar; men deras knappar och gjordar af silfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Sammalunda ock på norra sidone hundrade alnar, med tjugu stolpar och tjugu fötter af koppar; men deras knappar och gjordar af silfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'På vestra sidone femtio alnar, med tio stolpar och tio fötter; men deras knappar och gjordar af silfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'På östra sidone femtio alnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Femton alnar på hvarjo sidone vid porten af gårdenom; ju med tre stolpar, och tre fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Så att aller bonaden till gården var af tvinnadt hvitt silke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Och fötterna till stolparna af koppar, och deras knappar och gjordar af silfver; så att deras knappar voro öfverdragne med silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Men deras gjordar voro af silfver på alla stolparna i gården.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Och klädet till ingången på gårdenom gjorde han stickadt af gult silke, skarlakan, rosenrödt, och tvinnadt hvitt silke; tjugu alnar långt, och fem alnar högt, efter det mått, som bonaden var till gården;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Dertill fyra stolpar och fyra fötter af koppar; och deras knappar af silfver, och deras knöpar öfverdragne; och deras gjordar af silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Och alla pålarna till tabernaklet, och till gården allt omkring, voro af koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Detta är nu summan af det, som vittnesbördsens tabernakel tillhörde, det förtäljdt är, såsom Mose sagt hade, till Leviternas Gudstjenst under Ithamars hand, som var Prestens Aarons son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Hvilket Bezaleel, Uri son, Hurs sons, af Juda slägte, gjorde, allt såsom Herren hade budit Mose;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Och med honom Aholiab, Ahisamachs son, af Dans slägte, en mästare till snida, till virka och till sticka med gult silke, skarlakan, rosenrödt, och hvitt silke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Allt det guld, som förarbetadt vardt i detta hela helgedomens verk, det till veftoffer gifvet vardt, var nio och tjugu centener, sjuhundrade och tretio siklar, efter helgedomens sikel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Men silfret, som kom ifrå menighetene, var hundrade centener; tusende, sjuhundrade fem och sjutio siklar, efter helgedomens sikel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Så mång hufvud, så många halfva siklar, efter helgedomens sikel, af alla dem som räknade vordo, ifrå tjugu år och deröfver, sexhundradetusend, tretusend, femhundrade och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Utaf de hundrade centener silfver göt man fötterna till helgedomen, och fötterna till förlåten; hundrade fötter utaf hundrade centener, ju en centener till foten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Men utaf de tusend, sjuhundrade och fem och sjutio siklar, vordo gjorde knapparna till stolparna; och deras knöpar öfverdragne, och deras gjordar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Veftoffret af koppar var sjutio centener; tutusend och fyrahundrade siklar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Deraf vordo gjorde fötterna uti dörrene till vittnesbördsens tabernakel, och kopparaltaret, och koppargallret dertill; och all redskapen till altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'Dertill fötterna till gården allt omkring, och fötterna i ingången på gårdenom; alle pålarna till tabernaklet, och alle pålarna till gården allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Men af det gula silket, skarlakanet och rosenrödt, gjorde de Aaron ämbetskläder, till att tjena i helgedomenom; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Och han gjorde lifkjortelen af guld, gult silke, skarlakan, rosenrödt, och tvinnadt hvitt silke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Och utslog guldet, och skar det i trådar, så att man kunde konsteliga virka det in med det gula silket, skarlakan, rosenrödt, och hvita silket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Och gjorde så, att man sammanfogade honom på båda axlar, och band honom tillhopa på båda sidor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Och bältet var af samma konst och verk, af guld, gult silke, skarlakan, rosenrödt, och tvinnadt hvitt silke; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Och de tillredde två onichinerstenar, omfattade i guld; utgrafna af stensnidare med Israels barnas namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Och fäste dem på axlarna af lifkjortelen, att de skulle vara åminnelsestenar till Israels barn; såsom Herren Mose budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Och de gjorde skölden efter den konst och verk, som lifkjortelen var, af guld, gult silke, skarlakan, rosenrödt, och tvinnadt hvitt silke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Så att han var fyrakant och tvefald, en hand lång och bred;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Och fyllde honom med fyra radar stenar. Den första raden var en sarder, topaz och smaragd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Den andra, en rubin, saphir och diamant;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Den tredje, en lyncurer, achat och amethist;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Den fjerde, en turkos, onicher och jaspis; omfattade i guld i alla radarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Och stenarna stodo grafne af stensnidarena, efter de tolf Israels barnas namn; hvardera af sitt namn, efter de tolf slägten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Och de gjorde till skölden kedjor uppåt af klart guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Och tu gyldene spänner, och två gyldene ringar; och fäste de två ringar vid tu hörnen af skölden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Och de två gyldene kedjorna satte de uti de två ringar på hörnen af skölden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Men de två ändar af de gyldene kedjor läto de komma intill de tu spännen; och hakade dem intill hörnen af lifkjortelen tvärtemot hvartannat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Och gjorde två andra gyldene ringar, och knäppte dem vid de andra tu hörnen af skölden nedantill, så att han låg hardt inpå lifkjortelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Och gjorde två andra gyldene ringar; dem gjorde de på tu hörnen nedantill på lifkjortelen, tvärtemot hvarannan, der lifkjortelen nedantill sammangår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Och vardt skölden med sina ringar knäppt intill lifkjortelens ringar med ett gult snöre, så att det låg hardt intill lifkjortelen, och icke for löst ifrå lifkjortelen; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Och han gjorde silkeskjortelen under lifkjortelen, den all virkad var med gult silke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Och hans hufvudsmog midt ofvanuppå, och en borda omkring hufvudsmoget fållad, att det icke skulle gå sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Och de gjorde på hans fåll granatäple af gult silke, skarlakan, rosenrödt, och tvinnadt hvitt silke:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Och gjorde bjellror af klart guld; dem satte de emellan de granatäplen allt omkring på fållen af den silkeskjortelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Ju ett granatäple, och en bjellra allt omkring, till att tjena deruti; såsom Herren hade budit Mose;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Och gjorde desslikes den trånga kjortelen, virkad af hvitt silke, till Aaron och hans söner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Och hatten af hvitt silke, och sköna hufvor af hvitt silke, och nederklädet af tvinnadt hvitt linne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Och det stickade bältet af tvinnadt hvitt silke, gult silke, skarlakan, rosenrödt; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'De gjorde ock ännespannet på den helga kronona af klart guld, och grofvo skrift deruppå: Herrans HELIGHET;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Och bundo ett gult snöre dervid, att det måtte knäppas ofvanpå hatten; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Alltså vardt fullbordadt hela verket till vittnesbördsens tabernakels boning. Och Israels barn gjorde allt det Herren hade budit Mose;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Och hade boningen till Mose, tabernaklet och all dess redskap, spänner, bräder, skottstänger, stolpar, fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Täckelset af rödlett vädurskinn; täckelset af tackskinn, och förlåten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'Vittnesbördsens ark med sina stänger; nådastolen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Bordet med all dess redskap, och skådobröden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Den sköna ljusastakan, tillreddan med lamporna, och all sin redskap, och oljo till lysning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Gyldene altaret och smörjelsen, och godt rökverk; klädet i tabernaklets dörr;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Kopparaltaret och dess koppargallrar, med sina stänger, och all sin redskap; tvättekaret med sin fot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Bonaden till gården med sina stolpar och fötter, klädet till ingången åt gårdenom med sin tåg och pålar, och all redskap som behöfdes till boningenes tjenst, vittnesbördsens tabernakels;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Aarons Prestens ämbetskläder till att tjena i helgedomenom; och hans söners kläder, till att de skulle göra Prestaämbetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'All ting, såsom Herren hade budit Mose, gjorde Israels barn till alla denna tjenstena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Och Mose såg på allt detta verket, att de gjorde såsom Herren budit hade, och välsignade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'På första dagen i den första månaden skall du uppsätta vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Och skall deruti sätta vittnesbördsens ark, och hänga förlåten för arken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Och skall bära bordet dit, och reda det till, och ställa der ljusastakan, och lamporna sätta deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Och skall sätta det gyldene rökaltaret för vittnesbördsens ark, och upphänga klädet i dörrene af tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Och bränneoffersaltaret skall du sätta inför dörrene af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Och tvättekaret emellan vittnesbördsens tabernakel och altaret, och låta der vatten in;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Och göra gården omkring, och upphänga klädet i ingången på gårdenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Och skall taga smörjooljo, och smörja tabernaklet, och allt det derinne är; och skall viga det med all dess redskap, att det skall vara heligt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Och skall smörja bränneoffersaltaret med all sin redskap, och vigat, att det skall vara aldrahelgast.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Skall du också smörja och viga tvättekaret med dess fot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Och du skall hafva Aaron och hans söner fram för dörrena af vittnesbördsens tabernakel, och två dem med vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Och kläda på Aaron de helga kläden, och smörja och viga honom, att han skall vara min Prest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Och hafva desslikes hans söner fram, och kläda uppå dem de trånga kjortlarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Och smörja dem, såsom du hafver smort deras fader, att de skola vara mine Prester. Och denna smörjelsen skola de hafva till ett evigt Presterskap när deras efterkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Och Mose gjorde allt det Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Så vardt tabernaklet uppsatt i de andra årena på första dagenom i den första månaden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Och då Mose uppsatte det, satte han fötterna och bräden, och skottstängerna, och reste upp stolparna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Och sträckte ut öfvertäckelset till ett tabernakel, och lade dess täckelse ofvanuppå, såsom Herren honom budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Och tog vittnesbördet, och lade det in i arken, och satte stängerna på arken, och satte nådastolen ofvanpå arken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Och bar arken in i tabernaklet, och hängde förlåten för vittnesbördsens ark, såsom Herren honom budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Och satte bordet in uti vittnesbördsens tabernakel, på den sidon i tabernaklet norrut, utanför förlåten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Och gjorde bröd redo deruppå för Herranom, såsom Herren honom budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Och satte desslikes ljusastakan derin tvärtöfver ifrå bordet, på den sidon i tabernaklet söderut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Och lät komma lamporna deruppå för Herranom, såsom Herren honom budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Och satte gyldene altaret derin för förlåten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Och rökte deruppå med godt rökverk, såsom Herren honom budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Och hängde klädet in i dörrena af tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Men bränneoffersaltaret satte han för dörrena af vittnesbördsens tabernakel, och offrade deruppå bränneoffer och spisoffer, såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Och tvättekaret satte han emellan vittnesbördsens tabernakel och altaret, och lät vatten derin, till att två sig med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Och Mose, Aaron och hans söner tvådde deras händer och fötter derutur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Förty de måste två sig, när de gingo in uti vittnesbördsens tabernakel, eller framträdde till altaret, såsom Herren dem budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Och gjorde han gården redo, kringom tabernaklet, och omkring altaret, och hängde klädet i ingången på gårdenom. Och alltså fullkomnade Mose det hela verket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Och så öfvertäckte en molnsky vittnesbördsens tabernakel; och Herrans härlighet uppfyllde tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Och Mose kunde icke gå in uti vittnesbördsens tabernakel, så länge som molnskyn blef deröfver, och Herrans härlighet uppfyllde tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Och när molnskyn gaf sig upp ifrå tabernaklet, så foro Israels barn, så ofta som de reste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'När molnskyn icke gaf sig upp, då foro de intet, allt intill den dagen han sig uppgaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Förty Herrans molnsky var om dagen öfver tabernaklet, och om natten var eld derinne, för hela Israels hus ögon, så länge de reste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Och Herren kallade Mose, och talade med honom utu vittnesbördsens tabernakel, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Tala med Israels barn, och säg till dem: Hvilken ibland eder vill göra Herranom ett offer, han göre det af boskape; af fä och af får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Vill han göra ett bränneoffer af oxar, så offre en stutkalf, den ingen brist hafver, inför dörrene af vittnesbördsens tabernakel, att det skall varda Herranom tacknämligit af honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Och lägge sina hand på bränneoffrets hufvud, så varder det tacknämligit, och försonar honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Och skall slagta den stuten för Herranom. Och Presterna, Aarons söner, skola bära blodet fram och stänka allt omkring på altaret, som är för dörrene af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Och huden skall bränneoffrena aftagas, och det skall huggas i stycker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Och Prestens Aarons söner skola göra en eld på altaret, och lägga der ved uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Och skola lägga stycken, nämliga hufvudet och kroppen uppå veden, som ligger på eldenom på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Men inelfverna och fötterna skall man två med vatten, och Presten skall allt detta uppbränna på altaret till ett bränneoffer. Detta är ett offer, som väl luktar för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Vill han göra bränneoffer af får eller getter, så offre det mankön är, det ingen brist hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Och skall slagta det utmed sidone af altaret, som norrut är för Herranom. Och Presterna, Aarons söner, skola stänka dess blod på altaret allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Och man skall hugga det i stycke. Och Presten skall lägga hufvudet och kroppen på veden och elden, som på altaret är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Men inelfverna och fötterna skall man två med vatten. Och Presten skall allt det offra och uppbränna på altaret till bränneoffer. Detta är ett offer, som väl luktar för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Vill han ock göra Herranom ett bränneoffer af foglar, så göre det af turturdufvor, eller af unga dufvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Och Presten skall hafvat fram till altaret, och först vrida thy halsen af, att det må uppbrännas på altaret, och låta utblöda blodet på altarens vägg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Och dess kräfvo med fjädrarna skall man kasta vid altaret österut på askohopen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Och skall bryta dess vingar sönder, men icke rifva dem ifrå. Och alltså skall Presten uppbränna det på altaret, på vedenom och eldenom, till ett bränneoffer. Detta är ett offer, som väl luktar Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Vill en själ göra Herranom ett spisoffer, så skall det vara af semlomjöl; och skall gjuta der oljo uppå, och lägga rökelse deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Och bära det så till Presterna, Aarons söner. Då skall Presten taga sina hand fulla af det samma semlomjölet och oljone, samt med allt rökelset, och bränna det upp på altaret till en åminnelse. Detta är ett offer, som väl luktar för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Det öfver är af spisoffret, skall höra Aaron och hans söner till. Det skall vara det aldrahelgasta af Herrans offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Men vill han göra ett spisoffer af det i ugn bakas, så tage kakor af semlomjöl, osyrade, beblandade med oljo, och osyrade tunnkakor, smorda med oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Men är ditt spisoffer af något det som bakadt är i panno, så skall det vara af osyradt semlomjöl, beblandadt med oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Och du skall delat i stycker, och gjuta der oljo uppå; så är det ett spisoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Är ock ditt spisoffer något det på halster bakadt är, så skall du göra det af semlomjöl med oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Och det spisoffer, som du af sådana vill göra Herranom, det skall du bära till Presten; han skall hafva det fram till altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Och häfoffra det samma spisoffret till en åminnelse, och bränna det upp på altaret. Det är ett offer, som väl luktar för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Det öfver är, skall höra Aaron och hans söner till. Det skall vara det aldrahelgasta af Herrans offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Allt spisoffer, som I viljen offra Herranom, skolen I göra utan surdeg; ty ingen surdeg eller hannog skall deribland uppbränd varda Herranom för offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Men till en förstling skolen I offra dem Herranom; men på intet altare skola de komma till en söt lukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Allt ditt spisoffer skall du salta. Och ditt spisoffer skall aldrig vara utan dins Guds förbunds salt; ty uti allt ditt offer skall du offra salt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Vill du göra ett spisoffer Herranom af första frukterna, skall du torka de gröna axen vid eld, och stöta dem små, och så offra spisoffer af dina första frukter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Och skall låta der oljo uppå, och lägga rökelse deruppå; så är det ett spisoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Och Presten skall taga af det stötta, och af oljone med allt rökelset, och uppbränna det till en åminnelse. Det är Herranom ett offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Om hans offer är ett tackoffer, af fä, antingen oxe eller ko, skall han offra för Herranom det utan vank är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Och skall lägga sina hand på dess hufvud, och slagta det för dörrene af vittnesbördsens tabernakel; och Presterna, Aarons söner, skola stänka blodet på altaret allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Och skall offra af det tackoffret Herranom, nämliga allt det feta på inelfverna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Och båda njurarna med det feta, som derpå är vid länderna, och det nätet öfver lefrena med njurarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Och Aarons söner skola det uppbränna på altaret för ett bränneoffer på vedenom, som ligger på eldenom. Det är ett offer, som väl luktar för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Men vill han göra Herranom ett tackoffer af små boskap, antingen gummar eller gymmer, så skall det vara utan all vank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Är det ett lamb, så skall han hafva det fram för Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Och skall lägga sina hand på dess hufvud, och slagta det inför vittnesbördsens tabernakel; och Aarons söner skola stänka dess blod på altaret allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Och alltså offra Herranom af tackoffrena, nämliga dess feta; hela stjerten med ryggenom, det feta som är öfver inelfven, samt med allt det feta som invärtes är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Och båda njurarna med allt det feta, som derpå är vid länderna, och det nätet om lefrena och njurarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Och Presten skall uppbränna det på altaret, till offrens spis Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Är hans offer en get, och bär henne fram för Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Skall han lägga sina hand på hennes hufvud, och slagta henne för vittnesbördsens tabernakel; och Aarons söner skola stänka hennes blod på altaret allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Och skall deraf offra ett offer Herranom, nämliga det feta som är omkring inelfverna, och allt det feta som invärtes är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Båda njurarna med det feta, som derpå är vid länderna, och nätet öfver lefrena med njurarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Och Presten skall uppbrännat på altaret till offrens spis, till en söt lukt. Allt det feta hörer Herranom till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Det vare en evig sed med edra efterkommande uti alla edra boningar, att I intet fett eller blod äten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Tala med Israels barn, och säg: Om en själ syndar af ovetenhet emot något Herrans bud, som hon icke göra skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Nämliga, om en Prest, som smord är, syndar, så att han förargar folket, han skall för sina synd, som han gjort hafver, bära fram en ung stut, den utan vank är, Herranom till ett syndoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Och skall hafva stuten fram för Herran inför dörrena af vittnesbördsens tabernakel, och lägga sina hand på hans hufvud, och slagta honom för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Och Presten, som smord är, skall taga af hans blod, och bära in uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Och skall doppa sitt finger uti blodet, och stänka dermed sju resor för Herranom inför förlåten i det helga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Och skall af samma blod stryka på hornen af rökaltaret, som står för Herranom inuti vittnesbördsens tabernakel, och gjuta allt blodet på bottnen af bränneoffrens altare, som står för dörrene till vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Och allt det feta af syndoffret skall han häfoffra, nämliga det feta, som är öfver inelfverna, och allt det feta, som invärtes är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Båda njurarna med det feta, som derpå är vid länderna, och det nätet öfver lefrena med njurarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Såsom man häfoffrar i tackoffret af oxanom; och skall uppbrännat på bränneoffrens altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Men hudena af stuten med allt köttet, samt med hufvudet, och fötterna, och inelfverna, och gåret,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Det skall han allt utföra utu lägret, på ett rent rum, dit man slår askona, och skall uppbrännat på ved i elde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Om en hel menighet i Israel försåge sig, och gerningen vore fördold för deras ögon, så att de gjort hade emot något Herrans bud, det de icke göra skulle, och vorde så brottslige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Och förnumme så sedan sina synd, som de gjort hade; så skola de hafva en ung stut fram till syndoffer, och ställa honom för dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Och de äldste af menighetene skola lägga deras händer på hans hufvud för Herranom, och slagta den stuten för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Och Presten, som smord är, skall bära bloden af stuten in uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Och doppa derin med sitt finger, och sju resor stänka för Herranom inför förlåten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Och skall stryka af blodet på hornen af altaret, som står för Herranom uti vittnesbördsens tabernakel, och allt det andra blodet gjuta på bottnen af bränneoffersaltaret, som står för dörrene af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Allt hans feta skall han häfoffra, och uppbränna på altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Och skall göra med denna stuten, såsom han gjorde med syndoffersstutenom. Och alltså skall Presten försona dem, och det varder dem förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Och skall han föra stuten utu lägret och bränna honom upp, såsom han uppbrände den förra stuten. Det skall vara syndoffret för menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Om en Förste syndar, och något gör emot Herrans sins Guds bud, det han icke göra skulle, och varder brottslig ovetandes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Och förnimmer sina synd, som han gjort hafver; han skall frambära till offers en getabock utan all vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Och lägga sina hand på bocksens hufvud, och slagta honom på det rum, der man slagtar bränneoffer för Herranom; det vare hans syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Sedan skall då Presten taga af syndoffrens blod med sitt finger, och stryka det på hornen af bränneoffersaltaret, och det andra blodet gjuta på hornen af bränneoffrens altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Men allt hans feta skall han uppbränna på altaret, lika såsom det feta af tackoffrena; och alltså skall Presten försona hans synd, och det varder honom förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Om en själ af meniga folket syndar ovetandes, så att hon ovetandes gör emot något Herrans bud, det hon icke göra skulle, och blifver så brottslig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Eller förnimmer sina synd, som hon gjort hafver; hon skall bära fram för ett offer ena get utan vank, för syndena, som hon gjort hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Och skall lägga sina hand på syndoffrens hufvud, och slagta det på bränneoffrens rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Och Presten skall taga af blodet med sitt finger, och stryka på hornen af bränneoffrens altare, och allt blodet gjuta på bottnen af altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Allt hennes feta skall han aftaga, såsom han aftager det feta af tackoffrena, och skall uppbränna på altaret till en söt lukt Herranom. Och alltså skall Presten försona henne, och det varder henne förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Men bär han fram ett får till syndoffer, så bäre en gymmer utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Och lägge sina hand på syndoffrens hufvud, och slagte det till ett syndoffer, på det rummet, der man slagtar bränneoffret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Och Presten skall taga af blodet med sitt finger, och stryka på hornen af bränneoffrets altare, och gjuta allt blodet på bottnen af altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Men allt dess feta skall man aftaga, såsom han aftager det feta af tackoffrets fåre, och skall det uppbränna på altaret till ett Herrans offer. Och alltså skall Presten försona hans synd, den han gjort hafver, och honom varder det förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Om en själ syndar, så att hon hörer några bannor, och hon är dess vittne, eller det sett eller förfarit hafver, och icke hafver tillsagt, hon är brottslig till en missgerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Eller om en själ kommer vid något orent, antingen ett as af ett orent djur, eller af boskap, eller af matkar, och visste det icke, hon är oren, och är brottslig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Eller om hon kommer vid ena orena mennisko, i hvad som helst orenhet der menniskan kan med oren varda, och visste det icke, och förnimmer det sedan, den är brottslig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Eller om en själ svär, så att henne går af munnen att göra illa eller väl, såsom ene mennisko väl händer att svärja, och visste det icke, och förnimmer det sedan, den varder brottslig på ett af detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'När nu händer, att hon brottslig är på ettdera, och bekänner att hon derpå syndat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Så skall hon för detta hennes synds brott, som hon gjort hafver, bära fram Herranom af hjordenom ett får eller ena get, som foster haft hafver, till syndoffer; så skall Presten försona henne hennes synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Förmår hon icke ett får, så bäre Herranom för sitt brott, som hon brutit hafver, två turturdufvor, eller två unga dufvor; ena till syndoffer, den andra till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Och bäre dem till Presten, han skall den första göra till syndoffer, och vrida halsen sönder af henne, och dock icke rifva hufvudet ifrå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Och stänka med syndoffrets blod på altarens vägg, och låta det blodet, som öfver är, utblöda på altarens botten; det är syndoffret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Den andra skall han göra till bränneoffer efter dess rätt; och alltså skall Presten försona henne hennes synd, som hon gjort hafver, och det varder henne förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Förmår hon icke två turturdufvor, eller två unga dufvor, så bäre fram sitt offer för sina synd, en tiondedel af ett epha semlomjöl till syndoffer; men ingen oljo skall han låta deruppå, eller rökelse låta komma deruppå; ty det är ett syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Och han skall bärat fram till Presten, och Presten skall taga deraf en hand full till åminnelse, och bränna det upp på altaret Herranom till ett offer; detta är ett syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Och Presten skall så försona honom hans synd, som han gjort hafver, och det varder honom förlåtet. Och det skall höra Prestenom till, såsom ett spisoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Och Herren talade med Mose och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Om en själ förtager sig, så att hon med ovetenhet syndar på något, som Herranom vigdt är; skall hon bära Herranom skuldoffer, en vädur af hjordenom utan vank, den två siklar silfver är värd, efter helgedomens sikel, till skuldoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Dertill, hvad han syndat hafver på det vigda, skall han det igengifva, och ändå gifva femtedelen derutöfver, och skall gifvat Prestenom; han skall försona honom med skuldoffrets vädur, så varder det honom förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Om en själ syndar, och gör emot något Herrans bud, det hon icke göra skulle, och visste det icke, hon är brottslig, och är skyldig åt den missgerningene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Och skall bära en vädur af hjordenom utan vank, den ett skuldoffer värd är, till Presten. Han skall försona honom hans ovetenhet, den han gjort hafver, och visste det icke, så varder det honom förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Det är skuldoffret, till hvilket han Herranom brottslig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Om en själ syndar, och förtager sig för Herranom, så att han nekar sinom nästa det han honom befallt hafver, eller det han honom i godo tro handfått hafver, eller det han med våld tagit eller med orätt under sig slagit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Eller det tappadt var funnit hafver, och säger der nej till med en falsk ed, och hvad det helst kan vara, det en menniska emot sin nästa bryter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'När nu sker, att han så syndar, och sig förbryter, så skall han igengifva, hvad han så med våld tagit hafver, eller med orätt under sig slagit, eller det honom befaldt var, eller det han funnit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Eller der han den falska eden öfver gjort hafver; det skall han alltsammans igengifva, och ändå gifva femtedelen deröfver, honom som det tillhörde, på den dagen han sitt skuldoffer gifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Men för sina skuld skall han bära Herranom till Presten en vädur af hjorden utan vank, den ett skuldoffer värd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Så skall Presten försona honom för Herranom; så varder honom förlåtet allt det han gjorde, der han sig med förbröt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Bjud Aaron och hans söner, och säg: Detta är bränneoffrets lag. Bränneoffret skall brinna på altarens eldstad, och alla nattena intill morgonen; och allena altarens eld skall derpå brinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Och Presten skall kläda på sig sin linna kjortel, och det linna nederklädet på sin kropp; och skall upptaga askona, som af bränneoffrets eld kommer uppå altaret, och lägga den jemte vid altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Och skall kläda sig af, och kläda sig i annor kläde, och bära askona utom lägret på ett rent rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Elden på altaret skall brinna, och aldrig utsläckas. Presten skall hvar morgon upptända veden deruppå, och ställa bränneoffret deruppå, och bränna deruppå det feta af tackoffret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Alltid skall elden brinna på altaret, och aldrig utsläckas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Och detta är spisoffrens lag, det Aarons söner offra skola för Herranom på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Man skall häfoffra sin hand full af semlomjöl, af spisoffret och dess oljo, och allt rökelset, som ligger på spisoffret, och skall upptändat på altarena till en söt lukt, Herranom till åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Det öfver är, skall Aaron och hans söner förtära, och skola ätat osyradt på heligt rum, i gårdenom till vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'De skola intet baka med surdeg; ty det är deras del, den jag dem af mitt offer gifvit hafver; det skall vara dem det aldrahelgasta, lika såsom syndoffret och skuldoffret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Det mankön är ibland Aarons barn, skola det äta. Det vare edrom efterkommandom en evig rätt om Herrans offer. Ingen skall komma dervid, utan han är vigd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Detta skall vara Aarons och hans söners offer, som de skola offra Herranom på deras vigelsedag: Tiondedelen af ett epha semlomjöl till evigt spisoffer, hälftena om morgonen, och hälftena om aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Uti panno skall du göra det med oljo, och bära det bakadt fram, och i stycker skall du det offra Herranom till en söt lukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Och Presten, som af hans söner i hans stad smord varder, han skall göra det. Detta är en evig rätt Herranom. Det skall allt uppbrändt varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Ty allt spisoffer, som för en Prest sker, skall förtäras af eld, och icke ätas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Tala till Aaron och hans söner, och säg: Detta är syndoffrens lag: På den staden, der du slagtar bränneoffret, der skall du ock slagta syndoffret för Herranom; det är det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Presten, som syndoffret offrar, skall det äta på heligt rum, uti gårdenom till vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Ingen skall komma vid dess kött, utan han är vigd. Och den som en klädnad stänker af dess blod, han skall två sig på heligt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Och krukan, der det uti kokadt är, skall sönderslås. Är det en koppargryta, så skall man skura henne, och skölja med vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Det mankön är ibland Presterna, de skola äta deraf; ty det är det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Men allt det syndoffer, hvars blod buret varder in uti vittnesbördsens tabernakel till försoning i thy helga, det skall man icke äta, utan uppbränna det med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Och detta är skuldoffrens lag, och det är det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'På det rummet, der man slagtar bränneoffret, skall man ock slagta skuldoffret, och stänka dess blod på altaret allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Och allt dess feta skall man offra, stjerten och det feta, som är på inelfverna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Båda njurarna med det feta, som derpå är vid länderna, och nätet öfver lefrena med njurarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Och Presten skall uppbränna det på altaret Herranom till ett offer; det är ett skuldoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Det mankön är ibland Presterna, skola det äta på heligt rum; ty det är det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Såsom syndoffret, så skall ock skuldoffret vara; begges deras skall en lag vara; och skall höra Prestenom till, som derigenom försonar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Den Prest något bränneoffer offrar, honom skall tillhöra huden af bränneoffret, som han offrat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Och allt spisoffer, som i ugn, eller på halster, eller uti panno bakadt varder, skall höra Prestenom till, som det offrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Och allt spisoffer, som med oljo blandadt eller torrt är, det skall allom Aarons barnom tillhöra, så thy eno som thy andro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Och detta är tackoffers lag, det man Herranom offrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Vilja de göra ett lofoffer, så skola de offra osyrade kakor, blandade med oljo, och osyrade tunnkakor, bestrukna med oljo, och i panno bakade semlokakor, blandade med oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Och sådana offer skola de göra på en kako af syradt bröd till sitt tackoffers lofoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Och ett af thy allo skall offras Herranom till häfoffer, och skall höra Prestenom till, som stänker tackoffrens blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Och lofoffrens kött, i sitt tackoffer, skall ätas på samma dagen, som det offradt varder, och intet låtas qvart intill morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Och ehvad det är ett löfte eller friviljogt offer, så skall det på samma dagen ätet varda, som det offradt är; om något qvart blifver till den andra dagen, skall man ändå ätat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Men hvad qvart blifver af offradt kött intill tredje dagen, det skall uppbrännas i elde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Och om någor äter på tredje dagen af det offrade köttet af hans tackoffer, så blifver han icke tacknämlig, som det offrat hafver, det skall icke heller varda honom tillräknadt, utan det blifver en styggelse. Och hvad själ som deraf äter, hon är brottslig till en missgerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Och det kött, som kommer vid något orent, det skall icke varda ätet, utan uppbrändt i elde. Den der ren är till lekamen, han skall äta det köttet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Och den själ, som äter af tackoffrens kött, det Herranom tillhörer, hennes orenhet vare öfver henne, och hon skall varda utrotad utu sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Och om en själ kommer vid något det orent är, vare sig oren menniska, boskap, eller hvad eljest styggeligit är, eller ock äter af tackoffrens kött, det Herranom tillhörer, den skall utrotad varda utu sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Tala med Israels barn, och säg: I skolen intet fett äta af fä, lambom och getom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Men det feta af ett as, och hvad af vilddjur rifvet är, bruker eder till allahanda nytto; men icke skolen I ätat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Ty den som äter det feta af den boskap, som Herranom till offer gifven är, den samma själen skall utrotad varda utu sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'I skolen ock intet blod äta, antingen af boskap, eller af foglar, der I bon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Hvilken själ, som äter något blod, hon skall utrotad varda utu sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Tala med Israels barn, och säg: Den som Herranom sitt tackoffer göra vill, han skall ock bära med hvad som Herranom till ett tackoffer tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Han skall med sine hand bärat fram till Herrans offer, nämliga det feta på bröstena skall han frambära, samt med bröstet, att de skola varda ett veftoffer för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Och Presten skall uppbränna det feta på altaret. Och bröstet skall höra Aaron till, och hans söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Och den högra bogen skola de gifva Prestenom till häfoffer af deras tackoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Och hvilken ibland Aarons söner offrar blodet af tackoffret, och det feta, han skall ock hafva den högra bogen på sin del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Ty veftebröstet och häfvebogen hafver jag tagit af Israels barn, af deras tackoffer, och hafver gifvit det Prestenom Aaron och hans söner, till en evig rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Detta är Aarons och hans söners vigelse af Herrans offer, på den dagen då de öfverantvardade vordo till att vara Herranom Prester;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Då Herren böd, på den dagen, då han dem vigde, hvad dem af Israels barnom gifvas skulle, till en evig rätt, allom deras efterkommandom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Och detta är bränneoffrens lag, spisoffrens, syndoffrens, skuldoffrens, fyllooffrens och tackoffrens;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Det Herren på Sinai berg Mose böd, den dagen då han böd honom till Israels barn, att de skulle offra deras offer Herranom uti den öknene Sinai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Tag Aaron och hans söner med honom, samt med deras kläder, och smörjooljon, och en stut till syndoffer; två vädrar, och en korg med osyradt bröd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Och församla alla menighetena inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mose gjorde såsom Herren honom böd, och församlade menighetena inför dörrena af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Och sade till dem: Detta är det som Herren budit hafver att göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Och tog Aaron och hans söner, och tvådde dem med vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Och drog honom den linna kjortelen uppå, och band bältet omkring honom, och klädde på honom den gula silkeskjortelen, och fick honom lifkjortelen uppå, och gjordade honom öfver lifkjortelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Och satte på honom skölden, och i skölden Ljus och Fullkomlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Och satte honom hatten på hans hufvud, och satte på hatten ofvanför hans änne, ett gyldene spann på den helga kronona; såsom Herren Mose budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Och Mose tog smörjooljon, och smorde tabernaklet med allt det deruti var, och vigde det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Och stänkte dermed sju resor på altaret, och smorde altaret med all sin redskap, tvättekaret med sinom fot, att det skulle varda vigdt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Och göt af smörjooljone på Aarons hufvud, och smorde honom, att han skulle varda vigd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Och hade Aarons söner fram, och drog dem linna kjortlar uppå, och gjordade dem med bälter, och band dem hufvor uppå; såsom Herren honom budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Och lät hafva fram till sig en stut till syndoffer. Och Aaron och hans söner lade sina händer på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Sedan slagtades han. Och Mose tog af blodet, och strök med fingret på hornen af altaret allt omkring, och skärde altaret, och göt blodet på altarens botten, och vigde det, att han skulle försonat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Och tog allt det feta af inelfverna; nätet öfver lefrena, och båda njurarna dem det feta derpå är, och uppbrände det på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Men stuten med hans hud, kött och träck, brände han upp i elde utanför lägret; såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Och hade en vädur fram till bränneoffer; och Aaron med hans söner lade sina händer på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Sedan slagtades han. Och Mose stänkte af blodet på altaret allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Högg väduren i stycker, och brände upp hufvudet och stycken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Och tvådde inelfverna och fötterna med vatten, och brände så hela väduren upp på altarena. Det var ett bränneoffer till en söt lukt, ett offer Herranom; såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Han hade ock fram den andra väduren, som är fyllooffrens. Och Aaron med hans söner lade sina händer på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Sedan slagtades han. Och Mose tog af hans blod, och strök på högra örnatimpen af Aaron, och uppå tumman af högra handene, och på den största tåna af hans högra fot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Och hade fram Aarons söner, och strök af blodet på deras högra örnatimp, och på tumman af deras högra hand, och på största tåna af deras högra fot; och stänkte blodet på altaret rundt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Och tog det feta och stjerten, och allt det feta på inelfverna, och nätet på lefrena, båda njurarna med det feta deruppå är, och den högra bogen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Dertill tog han utaf korgenom, der det osyrade brödet uti var för Herranom, ena osyrada kako, och ena kako af det oljade brödet, och ena tunnkako, och lade det på det feta, och på högra bogen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Och fick allt detta Aaron och hans söner på händerna, och veftade det för ett veftoffer för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Och tog det allt igen af deras händer, och brände det upp på altaret ofvanuppå bränneoffret; ty det är fyllooffer till en söt lukt, ett offer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Och Mose tog bröstet, och veftade det till ett veftoffer för Herranom af fyllooffrens vädur, den kom Mose på hans del; såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Och Mose tog af smörjooljone, och af blodet på altaret, och stänkte på Aaron och hans kläder, på hans söner och deras kläder, och vigde så Aaron och hans kläder, hans söner och deras kläder med honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Och sade till Aaron och hans söner: Koker köttet för dörrene af vittnesbördsens tabernakel; och äter det der, dertill med brödet i fyllooffrens korg, såsom mig budet är och sagdt, att Aaron och hans söner skulle ätat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Hvad öfver blifver af köttet och brödet, det skolen I uppbränna på elde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Och I skolen icke utgå i sju dagar ifrå dörrene af vittnesbördsens tabernakel, allt intill den dagen, då edra fyllooffers dagar äro ute; ty i sju dagar äro edra händer fyllda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Såsom det på denna dag skedt är: Herren hafver så budit att göra, på det I skolen vara försonade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Och I skolen blifva för dörrene af vittnesbördsens tabernakel dag och natt i sju dagar långt; och skolen taga vara på Herrans vakt, att I icke dön; ty så är mig budet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Och Aaron med hans söner gjorde allt det Herren genom Mose budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Och på åttonde dagen kallade Mose Aaron och hans söner, och de äldsta i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Och sade till Aaron: Tag till dig en ung kalf till syndoffer, och en vädur till bränneoffer, båda utan vank, och haf dem fram för Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Och tala med Israels barn, och säg: Tager en getabock till syndoffer, och en kalf, och ett får, båda årsgamla, och utan vank, till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Och en oxa och en vädur till tackoffer, att vi offre för Herranom; och ett spisoffer blandadt med oljo; förty i dag skall Herren låta eder se sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Och de togo det Mose budit hade inför dörrena af vittnesbördsens tabernakel; och hela menigheten gick fram och stod för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Då sade Mose: Detta är det Herren budit hafver, att I göra skolen; så varder Herrans härlighet sig se låtandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Och Mose sade till Aaron: Gack fram till altaret, och gör ditt syndoffer, och ditt bränneoffer, och försona dig och folket. Derefter gör folkens offer, och försona desslikes dem; såsom Herren budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Och Aaron gick fram till altaret, och slagtade kalfven till sitt syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Och hans söner båro blodet till honom, och han doppade med sitt finger i blodet, och strök på hornen af altaret, och göt blodet på bottnen af altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Men det feta, och njurarna, och det nätet på lefrene af syndoffrena brände han upp på altaret; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Och köttet och skinnet brände han upp på elde utanför lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Sedan slagtade han bränneoffret, och Aarons söner båro blodet till honom, och han stänkte det på altaret allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Och de båro bränneoffret till honom styckadt, och hufvudet; och han brände det upp på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Och han tvådde inelfverna och fötterna, och brände det upp ofvanpå bränneoffret på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Derefter bar han fram folkens offer, och tog bocken, folkens syndoffer, och slagtade honom, och gjorde ett syndoffer deraf, såsom det förra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Och bar bränneoffret fram, och gjorde såsom det sig borde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Och bar fram spisoffret dertill, och tog sina hand full, och brände det upp på altaret, förutan morgonens bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Sedan slagtade han oxan och väduren till folkens tackoffer; och hans söner båro honom blodet, det stänkte han på altaret allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Men det feta af oxanom och vädrenom, stjerten, och det feta som var öfver inelfverna, och njurarna, och nätet öfver lefrena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Allt detta feta lade de på bröstet, och brände det feta upp på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Men bröstet och den högra bogen veftade Aaron till ett veftoffer för Herranom; såsom Mose budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Och Aaron hof sina hand upp till folket, och välsignade dem; och gick neder, sedan han syndoffret, bränneoffret och tackoffret gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Och Mose och Aaron gingo in uti vittnesbördsens tabernakel. Och då de gingo åter ut igen, välsignade de folket. Då lät Herrans härlighet se sig allo folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Ty eld kom ut ifrå Herranom, och förtärde bränneoffret, och det feta på altaret. Då allt folket såg detta, fröjdade de sig, och föllo på deras anlete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Och Aarons söner, Nadab och Abihu, togo hvar sitt rökelsekar, och lade eld deruti, och lade rökverk deruppå, och båro främmande eld fram för Herran, det han dem icke budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Då kom en eld ut ifrå Herranom, och förtärde dem, så att de blefvo döde för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Då sade Mose till Aaron: Detta är det Herren sagt hafver: Jag skall varda helgader på dem som nalkas mig, och för allo folke skall jag härlig hållen varda. Och Aaron tigde stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Men Mose kallade till sig Misael och Elzaphan, Usiels söner, Aarons faderbroders, och sade till dem: Går fram, och bärer edra bröder härut af helgedomenom, ut för lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Och de gingo fram, och båro dem med deras linnekjortlar ut för lägret; såsom Mose sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Då sade Mose till Aaron och hans söner, Eleazar och Ithamar: I skolen icke blotta edor hufvud, icke eller rifva edor kläder, att I icke dön, och vrede kommer öfver hela menighetena; låter edra bröder af hela Israels hus gråta öfver denna branden, som Herren gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Men I skolen intet gå ut igenom dörrena af vittnesbördsens tabernakel; annars kunden I dö; ty Herrans smörjoolja är på eder. Och de gjorde såsom Mose sade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Men Herren talade med Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Du och dine söner med dig skolen icke dricka vin eller starka drycker, när I gån in uti vittnesbördsens tabernakel, att I icke skolen dö. Det vare en evig rätt allom edrom efterkommandom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Att I mågen åtskilja hvad heligt och oheligt, hvad rent och orent är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Och att I mågen lära Israels barn alla rätter, som Herren till eder genom Mose sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Och Mose talade med Aaron, och med hans återlefda söner, Eleazar och Ithamar: Tager det öfverblifvet är af spisoffret och af Herrans offer, och äter det osyradt vid altaret; ty det är det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Och I skolen ätat på ett heligt rum, ty det är din rätt, och dina söners rätt af Herrans offer; ty så är mig budet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Veftebröstet och häfvebogen skall du och dine söner, och dina döttrar med dig, äta på rent rum; ty denne rätten är dig och dina söner gifven till Israels barnas tackoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Ty häfvebogen och veftebröstet, med dess fetas offer, skola inbäras, att de skola varda veftad till veftoffer för Herranom. Derföre är det ditt och dina barnas till en evig rätt; såsom Herren budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Och Mose sökte efter syndoffrens bock; och fann honom vara uppbrändan. Och han vardt vred öfver Eleazar och Ithamar, Aarons söner, de ännu igenlefde voro; och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Hvi hafven I icke ätit syndoffret på heligt rum, efter det är det aldrahelgasta, och han hafver gifvit eder det, på det I skolen bära menighetenes missgerningar, och försona dem för Herranom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Si, hans blod är icke kommen in uti det helga; I skullen hafva ätit det in i det helga, såsom mig budet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Men Aaron sade till Mose: Si, i dag hafva de offrat deras syndoffer, och deras bränneoffer för Herranom, och mig är så gånget som du ser. Skulle jag i dag äta af syndoffer, och vara vid godt mod för Herranom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Då Mose det hörde, var han tillfrids.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Och Herren talade med Mose och Aaron, och sade till dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Taler med Israels barn, och säger: Dessa äro de djur, som I äta skolen, ibland all djur på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Allt det som ibland djuren tveklöfvadt är, och idislar, det skolen I äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Men det som idislar, och är klöfvadt, dock icke tveklöfvadt, såsom camelen, det är eder orent, och I skolen icke ätat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Cuniler idisla väl, men de äro icke tveklöfvade; derföre äro de orene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Haren idislar ock, men han är icke tveklöfvad; derföre är han eder oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Och svinet är väl klöfvadt, men det idislar icke; derföre är det eder orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Af desses kött skolen I icke äta, och icke komma vid deras as; ty de äro eder oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Detta skolen I äta ibland det som i vattnena är: allt det som spol och fjäll hafver i floder, i hafvena, och i bäckom, det skolen I äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Men allt det som icke hafver spol och fjäll i hafvena och i bäckom, ibland allt det som röres i vattnen, och allt det som lefver i vattne, det skall vara eder en vederstyggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Att I icke äten af dess kött, och skyr vid deras as;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Ty allt det som icke hafver spol och fjäll i vattnena, der skolen I sky veder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Och detta skolen I sky veder ibland foglarna, att I icke äten dem: örnen, höken, falken,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Gamen, gladona, och det af deras art är,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Och alle korpar med deras art,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Strutsfoglen, ugglona, göken, sparfhöken med sine art,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Stenugglona, svanen, ufven,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Flädermusena, rördrommen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Storken, hägren, skrikona med sine art, vidhöfden och svalona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Och allt det sig rörer ibland foglarna, och går på fyra fötter, det skall vara eder en vederstyggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Dock detta skolen I äta af foglom, det sig rörer och går på fyra fötter, hvilkas knä stå tillbaka, der det med hoppar på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Deraf mån I äta, såsom är Arbe med sin art, och Saleam med sin art, och Hargol med sin art, och Hagab med sin art.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Allt det eljest hafver fyra fötter ibland foglarna, det skall vara eder en vederstyggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Och I skolen räkna dem oren. Den som kommer vid deras as, han skall vara oren allt intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Och den som någorsderas as bär, han skall två sin kläder, och skall blifva oren allt intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Derföre, allt det djur, som klöfvadt är, och icke tveklöfvadt, och idislar icke, det skall vara eder orent; den som kommer dervid, han blifver oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Och allt det som går på händer ibland djuren, som gå på fyra fötter, det skall vara eder orent; den som kommer vid deras as, han skall vara oren allt intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Och den som deras as bär, han skall två sin kläder, och vara oren allt intill aftonen; ty allt sådant är eder orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Desse skola ock vara eder oren ibland de djur, som krypa på jordene: lekatten, musen, paddan, hvart efter sitt slag,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Igelkotten, molken, ödlan, stellion, mullvaden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'De äro eder oren ibland allt det som kryper; den som kommer vid deras as, han skall vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Och allt det som ett sådant dödt as på faller, det varder orent; vare sig allahanda träkäril, eller kläder, eller skinn, eller säck, och all sådana redskap, der man något med gör, skall man låta i vatten, och det blifver orent intill aftonen; så varder det rent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Allahanda lerkäril, om ett sådant as deruti faller, varder allt orent, som deruti är, och skall sönderslås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'All mat, som man äter, om det vattnet kommer deruti, den är oren; och all dryck, som man dricker af allahanda sådana kärile, är oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Och allt det som ett sådant as på faller, det blifver orent, vare sig ugn eller kettlar, det skall man slå sönder; ty det är orent, och skall vara eder orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Dock brunnar, källor och dammar äro rene; den som kommer vid deras as, han är oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Och om ett sådant as fölle på säd, som man sått hafver, så är hon dock ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Men gjuter man vatten på sädena, och sedan fölle sådant as deruppå, så vorde hon eder oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Om ett djur dör, det I äta mågen, den som kommer vid det aset, den är oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Den som äter af sådant as, han skall två sin kläder och skall blifva oren intill aftonen; så ock den som bär ett sådant as, han skall två sin kläder, och blifva oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Det som kräker på jordene, skall vara eder en vederstyggelse, och man skall icke ätat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Och allt det som går på bukenom, och allt det som går på fyra eller flere fötter, af allo thy som kräker på jordene, det skolen I icke äta; ty det skall vara eder en vederstyggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Görer edra själar icke till styggelse, och besmitter eder icke deruppå, så att I blifven orene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Ty jag är Herren edar Gud; derföre skolen I helga eder, att I blifven helige, ty jag är helig; och I skolen icke orena edra själar på något kräkande djur, som på jordene kräker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Ty jag är Herren, som hafver fört eder utur Egypti land, att jag skall vara edar Gud; derföre skolen I vara helige, ty jag är helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Detta är lagen öfver djur, och foglar, och allahanda kräkande djur i vattnena, och allahanda djur, som kräka på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Att I skolen veta åtskilnad på hvad orent och rent är, och hvad djur man äta, och hvad man icke äta skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Tala med Israels barn, och säg: När en qvinna undfår säd, och föder piltabarn, då skall hon vara oren i sju dagar, så länge hon lider sina krankhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Och på åttonde dagen skall man omskära hans förhuds kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Och hon skall hemma blifva tre och trettio dagar uti hennes renselseblod. Intet heligt skall hon komma vid, och till helgedomen skall hon icke komma, till dess hennes renselsedagar äro ute.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Föder hon pigobarn, så skall hon vara oren i två veckor, så länge hon lider sina krankhet, och skall sex och sextio dagar hemma blifva i hennes renselseblod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Och när hennes renselsedagar äro ute, efter son eller dotter, skall hon bära fram ett årsgammalt lamb till bränneoffer, och en ung dufvo, eller turturdufvo, till syndoffer Prestenom, för dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Der skall han offrat för Herranom, och försona henne, så varder hon ren af sinom blodgång. Detta är lagen för den som föder piltabarn eller pigobarn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Om hennes hand icke förmå ett får, så tage två turturdufvor, eller två unga dufvor, den ena till bränneoffer, den andra till syndoffer; så skall Presten försona henne, att hon skall varda ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Om ene mennisko något kommer på hennes kötts hud, eller varder skabbot, eller etterhvit, såsom der ville spitelska komma på hans kötts hud, skall man hafva honom till Presten Aaron, eller till en af hans söner ibland Presterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Och när Presten ser sårnaden på köttsens hud, att håren äro förvandlade till hvitnad, och rummet är så påseende som det djupare är än den andra huden af hans kött, så är det förvisso spitelska; ty skall Presten bese honom, och döma honom oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Om något etterhvitt är på hans kötts hud, och är dock icke rummet så påseendes, att det djupare är än den andra huden på köttet, och håren äro icke förvandlade till hvitnad, så skall Presten lycka honom inne i sju dagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Och på sjunde dagen bese honom, om sårnaden synes för hans ögon såsom tillförene, och hafver intet vidare ätit sig ut på hudene, så skall Presten åter sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Och när han beser honom annan gången, på sjunde dagen, och finner då, att sårnaden är försvunnen, och hafver intet vidare ätit sig på hudene, så skall han döma honom renan; ty det är en skabb. Och han skall två sin kläder, och så är han ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Om nu skabben vidare äter sig på hudene, sedan han af Prestenom besedd och ren sagd vardt, och varder nu annan tid besedd af Prestenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Ser då Presten, att skabben hafver vidare ätit sig i hudena, skall han döma honom oren; ty det är visserliga spitelska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Om någon spitelskosårnad varder på ene mennisko, den skall man hafva till Presten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'När han ser och finner, att en hvitnad är kommen på hudena, och håren äro hvit vordne, och rått kött är i sårena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Så är det visserliga en gammal spitelska på hans kötts hud; derföre skall Presten döma honom oren, och icke sluta honom inne; ty han är allaredo oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Om spitelskan förvidgas på hudene, och går utöfver hela hudena, ifrå hufvudet ned till fötterna, allt det Prestenom för ögonen vara kan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'När nu Presten beser det, och finner att spitelskan är gången öfver hela köttet, så skall han döma honom ren, efter det allt på honom förvandladt är till hvitnad; ty han är ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Men är det rått kött den dagen då han besedd varder, så är han oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Och när Presten ser det rå köttet, skall han döma honom oren; ty han är oren, och är visserliga spitelsk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Om det rå köttet förvänder sig igen, och förvandlas till hvitnad, så skall han komma till Presten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Och när Presten ser och finner, att den sårnaden är förvandlad till hvitnad, skall han döma honom renan; ty han är ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Om någrom kommer på hans kötts hud en böld, och läkes åter igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Och derefter på samma rummet uppkommer något hvitt, eller rödligit etterhvitt varder, skall han varda besedd af Prestenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'När Presten ser, att det rummet är lägre än den andra huden, och håret är förvandladt till hvitnad, så skall han döma honom oren; ty det är visserliga vordet en spitelskosårnad af den böldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Men ser Presten och finner, att håren icke äro hvit, och är icke lägre än den andra huden, och är försvunnet, så skall han sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Äter det sig vidare i hudena, så skall han döma honom oren; ty det är visserliga en spitelskosårnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Men blifver den etterhvitnaden så ståndandes, och äter sig icke vidare, så är det ärret efter böldene; och Presten skall döma honom ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Om någors mans kött varder sårt på hudene af eldbränning, och brännesårnaden är rödlig eller hvit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Och Presten beser honom, och finner håret förvandladt till hvitnad, der bränningen var, och är lägre till anseende än den andra huden; så är visserliga spitelska vorden af den bränningene; derföre skall Presten döma honom oren; ty det är en spitelskosårnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Men ser Presten och finner, att håret på bränningene icke är förvandladt till hvitnad, och icke lägre än den andra huden, och är dertill försvunnet; skall han sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Och på sjunde dagen skall han bese honom. Hafver det vidare ätit sig ut på hudene, så skall han döma honom oren; ty det är spitelska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Men är det blifvet ståndande på bränningene, och icke hafver vidare ätit sig ut på hudene, och är dertill försvunnet, så är det ett sår efter bränningene, och Presten skall döma honom ren; ty det är ett ärr efter bränningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Om en man eller qvinna varder skabbot på hufvudet eller på skägget;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Och Presten beser sårnaden, och finner att det är lägre till anseende än den andra huden, och håret dersammastäds varder gulaktigt och tunnt, så skall han döma honom oren; ty det är en spitelskoskabb på hufvudet eller skäggena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Men ser Presten, att skabben icke är lägre till anseende än den andra huden, och håret icke är blackt; skall han sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Och när han på sjunde dagen ser och finner, att skabben icke hafver ätit sig vidare, och intet gult hår på färde är, och skabben är icke lägre till anseende än den andra huden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Skall han raka sig, dock att han icke rakar skabben; och Presten skall åter sluta honom inne i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Och när han på sjunde dagen beser honom, och finner att skabben hafver icke vidare ätit sig i hudene, och är icke lägre till anseende än den andra huden, så skall Presten säga honom ren, och han skall två sin kläder; ty han är ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Om skabben äter sig vidare i hudena, sedan han ren sagd var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Och Presten ser och finner, att skabben hafver ätit sig vidare på hudene, så skall han icke mer fråga efter, om håren äro gulaktig; ty han är oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Är det ock för ögonen, att skabben hafver ståndit stilla, och der äro black hår uppgångne, så är skabben läkt, och han är ren; ty skall Presten säga honom renan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Om enom manne eller qvinno något etterhvitt kommer på hans kötts hud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Och Presten ser, att det etterhvita något försvinner, så är det en hvit skabb, uppkommen på hudena; och han är ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Om enom manne hufvudhåret affaller, så att han varder skallot, han är ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Faller det honom framman af hufvudet, så är det en framskallot; och han är ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Men varder der någor hvit eller rödlig sårnad uppå det skallota eller framskallota, så är det spitelska uppgången på samma skallota eller framskallota.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Derföre skall Presten bese honom, och när han finner den hvita eller rödliga sårnaden upplupen på hans skallota eller framskallota, att det synes såsom eljest spitelska på hudene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Så är han spitelsk och oren; och Presten skall säga honom oren för sådana sårnads skull på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Den som spitelsk är, hans kläder skola vara rifven, och hufvudet blott, munnen skylder; och skall allstinges oren kallas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Och så länge den sårnaden på honom är, skall han vara oren, bo allena, och hans boning skall vara utan lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Om på ett kläde kommer en spitelskosårnad, vare sig ullet eller linnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'På varp eller väft, ehvad det är, linnet eller ullet, eller på ett skinn, eller på allt det af skinn gjordt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Och när den sårnaden varder blek eller rödlig, på kläde eller på skinne, eller på varpe eller väfte, eller på något ting som af skinn gjordt är, det är visst en spitelskosårnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Derföre skall Presten bese det, och när han ser sårnaden, skall han sluta det inne i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Och om han på sjunde dagen ser, att sårnaden hafver vidare ätit sig på klädet, på varpenom eller väftena, på skinne, eller hvad af skinne gjordt är; så är det en inbiten spitelskosårnad, och det är orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Och klädet skall brännas upp, eller varpen, eller väftet, ehvad det är ullet eller linnet, eller allahanda skinnverk, der sådana sårnad uppå är; ty det är en spitelskosårnad, och skall brännas upp på elde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Om Presten ser att sårnaden icke hafver vidare ätit sig på klädet eller på varpenom, eller väftena, eller allahanda skinnverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Så skall han bjuda, att man tvår der sårnaden är, och skall sluta det inne i andra sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Och när Presten ser, sedan sårnaden tvagen är, att sårnaden intet förvandlad är för hans ögon, och ej heller hafver vidare ätit sig, så är det orent, och skall uppbrännas på elde; ty det är djupt inätet, och hafver befrätit det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Om Presten ser, att sårnaden något försvunnen är, sedan han vardt tvagen; så skall han rifva det af klädena, af skinnena, af varpenom eller väftena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Synes det ändå sedan på klädena, på varpenom, på väftena, eller allahanda skinnverk; så är det en fläck, och skall det uppbrännas med elde, der den sårnaden uti är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Men klädet eller varpen, eller väftet, eller allahanda skinnverk, som tvaget är, och sårnaden afgången är, skall man på nytt två, och så är det rent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Detta är lagen om spitelskosårnad på kläder, ehvad de äro ullen eller linnen; på varp eller väft, och allahanda skinnverk, till att säga dem ren eller oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Detta är lagen om den spitelska, när han skall rensad varda: Han skall komma till Presten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Och Presten skall gå utu lägret, och bese huru spitelskosårnaden är på dem spitelsko hel vorden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Och skall bjuda honom, som rensas skall, att han tager två lefvande foglar, de som rene äro, och cederträ, och rosenfärgoull, och isop;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Och skall bjuda att slagta den ena foglen uti ett lerkärile vid rinnande vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Och skall taga den lefvande foglen med cederträt, rosenfärgoullen, och isopen, och doppa uti den slagtade foglens blod vid rinnande vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Och stänka på honom, som af spitelskone rensas skall, sju resor; och rensa honom alltså, och låta den lefvande foglen flyga i fria markena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Men den rensade skall två sin kläder, och raka allt sitt hår af, och bada sig i vattne, och så är han ren; sedan gånge han in i lägret, dock skall han blifva utan sitt tjäll i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Och på sjunde dagen skall han raka allt sitt hår af hufvudet, skägget och ögonbrynen, så att allt hår blifver afrakadt; och skall två sin kläder, och bada sitt kött i vattne, och så är han ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Och på åttonde dagen skall han taga tu lamb, de utan vank äro, och ett årsgammalt får utan vank, och tre tiungar semlomjöl till spisoffer, blandadt med oljo, och en log oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Då skall Presten ställa den rensada och dessa ting fram för Herran, för dörrena af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Och skall taga det ena lambet, och offra det till ett skuldoffer med den log oljo, och skall sådant veftoffra för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Och sedan slagta lambet, der man slagtar syndoffret och bränneoffret, som är på heligt rum; ty såsom syndoffret, så hörer ock skuldoffret Prestenom till; ty det är det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Och Presten skall taga af skuldoffrens blod, och stryka på högra örnatimpen af den rensada, och på tumman af hans högra hand, och på största tåna af hans högra fot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Sedan skall han taga af oljone utu logen, och gjuta den i sin venstra hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Och doppa med sitt högra finger i oljona, den i hans venstra hand är, och stänka oljona med sitt finger sju resor för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Men det öfver blifver af oljone i hans hand, skall han gjuta på den högra örnatimpen af honom, som rensad är, och på den högra tumman, och på den stora tåna af hans högra fot, ofvanuppå skuldoffrens blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Det qvart är af oljone i hans hand, skall han slå på hans hufvud, som rensader är, och försona honom för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Och skall göra syndoffer, och försona den rensada för hans orenlighets skull; och skall sedan slagta bränneoffret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Och skall offra det på altaret samt med spisoffret, och försona honom, så är han ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Är han fattig, och icke så mycket förvärfvar med sine hand, så tage ett lamb för sitt skuldoffer, till att veftoffra, till att försona honom, och en tiung af semlomjöl, blandad med oljo till spisoffer, och en log oljo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Och två turturdufvor, eller två unga dufvor, de han med sine hand förvärfva kan; den ena vare till ett syndoffer, den andra till ett bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Och bäre dem till Presten, på åttonde dagen efter hans renselse, inför dörrena af vittnesbördsens tabernakel för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Då skall Presten taga skuldoffrens lamb, och den log oljo, och skall det allt veftoffra för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Och slagta skuldoffrens lamb, och taga af samma skuldoffers blod, och stryka den rensada på hans högra örnatimp, och på tumman af hans högra hand, och på den stora tåna af hans högra fot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Och gjuta oljona i sina venstra hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Och stänka med sitt högra finger oljona, som i hans venstra hand är, sju resor för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Det qvart blifver i hans hand, skall han låta på högra örnatimpen af den rensada, och på tumman af hans högra hand, och på stora tåna af hans högra fot, ofvanuppå skuldoffrens blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Det qvart är i hans hand af oljone, skall han låta på hufvudet af den rensada, till att försona honom för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Och sedan göra ett syndoffer utaf den ena turturdufvone, eller unga dufvone, såsom hans hand hafver kunnat förvärfva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Utaf den andra ett bränneoffer, samt med spisoffret. Och alltså skall Presten försona den rensada för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Detta vare lagen för den spitelska, som icke kan med sine hand förvärfva det till hans renselse hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'När I kommen in uti Canaans land, det jag eder till besittning gifva skall, och jag der i någro edor besittninges huse en spitelskosårnad gifver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Så skall han, som huset tillhörer, komma, undervisa det Prestenom, och säga: Det synes såsom en spitelskosårnad är i mino huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Då skall Presten säga dem, att de skola rymma utu huset förra än Presten går derin, till att bese sårnaden; på det att allt, det i huset är, icke skall varda orent. Sedan skall Presten gå in till att bese huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'När han nu ser sårnaden, och finner att på husens väggar gula eller rödletta gropar äro, och deras anseende djupare in är än väggen eljest är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Så skall han gå utu huset genom dörrena, och igenlycka huset i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Och när han på sjunde dagen igenkommer, och ser att sårnaden hafver ätit sig vidare på väggene af huset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Så skall han bjuda dem utbryta stenarna, der den sårnaden uti är, och kasta det ut för staden på ett orent rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Och huset skall man skrapa innantill allt omkring, och kasta det afskrapade stoftet ut för staden på ett orent rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Och taga andra stenar, och sätta dem i samma staden; och taga annan kalk, och bestryka huset med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Om då sårnaden igenkommer, och brister ut på huset, sedan man hafver uttagit stenarna, skrapat huset, och bestrukit det på nytt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Så skall Presten gå derin. Och när han ser att sårnaden hafver vidare ätit sig på husena, så är det visserliga en frätande spitelska på huset; och är orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Derföre skall man bryta huset ned, både sten och trä, och allt stoftet af husena föra ut för staden på ett orent rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Och den som går in i huset, så länge det tillslutet är, han är oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Och den derinne ligger, eller äter derinne, han skall två sin kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Hvar nu Presten ser, då han går derin, att sårnaden icke vidare hafver ätit sig på huset, sedan huset bestruket är; så skall han säga det rent; ty sårnaden är hel vorden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Och skall taga till syndoffer för huset, två foglar, cedreträ, och rosenfärgad ull, och isop;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Och slagta den ena foglen uti ett lerkäril vid rinnande vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Och skall taga det cederträt, rosenfärgada ullen, isopen och den lefvande foglen, och doppa honom uti den slagtada foglens blod vid rinnande vatten, och stänka huset sju resor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Och skall alltså skära huset med foglens blod, och med det rinnande vattnet, med den lefvande foglen, med cedreträt, med isopen, och med rosenfärgada ullen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Och skall låta den lefvande foglen flyga ut för staden i fria markena, och försona huset; så är det rent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Detta är lagen om all spitelskos och skabbs sårnad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Om kläders spitelsko, och huses;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Om blemmor, skabb och etterhvitt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'På det man skall veta, när något orent eller rent är. Detta är lagen om spitelsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Taler med Israels barn, och säger till dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Om enom manne flyter hans kötts flöd, han är oren. Och då är han oren af denna flödene, när hans kött förrötes, eller bortfrätes af det flytandet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'All säng, der han på ligger, och allt det han sitter uppå, skall vara orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Och den som kommer vid hans säng, han skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Och den som sätter sig der han sutit hafver, han skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Den som kommer vid hans kött, han skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Om han spottar på den som ren är, skall han två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Och sadelen, der han rider uppå, skall vara oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Och den som kommer vid något, som under honom varit hafver, han skall vara oren intill aftonen. Och den sådant bär, han skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Och den som han vederkommer, och hafver tillförene icke tvagit sina händer, han skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Kommer han vid ett lerkäril, skall man det sönderslå; men träkäril skall man skölja med vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Och när han varder ren af hans flytande, skall han räkna sju dagar sedan han vardt ren, och två sin kläder, och bada sitt kött med rinnande vatten, så är han ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Och på åttonde dagen skall han taga två turturdufvor, eller två unga dufvor, och bära fram för Herran inför dörrena af vittnesbördsens tabernakel, och få Prestenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Och Presten skall göra af den ena ett syndoffer, och af den andra ett bränneoffer; och försona honom för Herranom, för hans flytandes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'När enom manne hans säd utgår i sömnen, han skall bada sitt hela kött med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Och allt kläde, och allt skinn, som med sådana säd befläckadt är, skall tvås med vatten, och vara orent intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'En qvinna, när hvilko en sådana ligger, hon skall bada sig i vattne, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'När en qvinna hafver sins kötts blodflöd, hon skall vara afsides i sju dagar. Och den som kommer vid henne, han skall vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Och allt det hon ligger uppå, så länge hon afsides är, skall vara orent; och det hon sitter uppå, skall vara orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Och den som kommer vid hennes säng, han skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Och den som kommer vid något, der hon hafver sutit uppå, den skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Hvad som kommer vid hennes säng, eller det hon sitter på, den det rörer, han skall vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Och om en man ligger när henne, den stund hon afsides satt är, han skall vara oren i sju dagar; och sängen, der han uppå legat hafver, skall vara oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Om en qvinna hafver sin blodflöd i långan tid, icke allenast i så lång tid som vant är, utan ock utöfver den tiden som vant är, skall hon vara oren så länge hon flyter; såsom hon är i hennes rätta flöds tid, så skall hon ock vara oren i denna tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'All den säng, der hon uppå ligger, så länge hon då flyter, skall vara såsom den säng i hennes rätta flöds tid. Och allt det hon sitter uppå skall vara orent, såsom i den orenheten i hennes rätta flöds tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Den som kommer vid något deraf, han skall vara oren, och skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Varder hon ren af hennes flöd, så skall hon räkna sju dagar, sedan skall hon vara ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Och på åttonde dagen skall hon taga två turturdufvor, eller två unga dufvor, och bära dem till Presten inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Och Presten skall göra ett syndoffer af den ena; af den andra ett bränneoffer, och försona henne för Herranom, öfver hennes orenlighets flöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Så skolen I förvara Israels barn för deras orenlighet, att de icke dö uti deras orenlighet, om de göra mitt tabernakel orent, det ibland eder är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Detta är lagen om den som hafver en flöd, och den som i sömnen hans säd flyter, så att han varder deraf oren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Och öfver henne som hafver sina blodsflöd, och den som en flöd hafver, ehvad det är man eller qvinna, och när en man ligger när ena oreno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Och Herren talade med Mose, sedan de två Aarons söner döde voro, då de offrade för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Och Herren sade: Säg dinom broder Aaron, att han icke i alla tider ingår uti den innersta helgedomen, inom förlåten inför nådastolen, som på arkenom är, att han icke dör; ty jag vill låta se mig uti ett moln på nådastolenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Utan härmed skall han gå in: Med en ung stut till syndoffer, och med en vädur till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Och skall kläda den helga linna kjortelen uppå, och hafva det linna nederklädet uppå sitt kött, och gjorda sig med ett linnet bälte, och hafva den linna hatten uppå; förty det äro de helga kläden; och skall bada sitt kött med vatten, och lägga dem uppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Och skall taga utaf menighetene af Israels barnom två getabockar till syndoffer, och en vädur till bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Och Aaron skall hafva fram stuten, sitt syndoffer, och försona sig och sitt hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Och sedan taga de två bockarna, och ställa dem fram för Herran, inför dörrena af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Och skall kasta lott öfver de två bockarna; den ena lotten Herranom, den andra fribockenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Och skall offra den bocken till ett syndoffer, på hvilken Herrans lott föll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Men den bocken, öfver hvilken dess frias lott föll, skall han ställa lefvande fram för Herran, att han skall försona honom, och släppa den fribocken i öknena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Och så skall han då hafva fram sins syndoffers stut, och försona sig och sitt hus, och skall slagta honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Och skall taga ena panno, full med glöd af altaret, som står för Herranom, och handena fulla med stött rökverk, och bära det inom förlåten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Och lägga rökverket på elden inför Herranom, så att dambet af rökverket skyler nådastolen, som är på vittnesbördet, att han icke dör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Och skall taga blodet af stutenom, och stänka med sitt finger upp åt nådastolen, frammantill. Sju resor skall han så stänka af blodet för nådastolenom med hans finger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Sedan skall han slagta bocken, folkens syndoffer, och bära af hans blod derinom förlåten, och skall göra med hans blod såsom han gjorde med stutens blod, och stänka desslikes dermed frammantill, upp åt nådastolen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Och skall alltså försona helgedomen af Israels barnas orenhet, och ifrå deras öfverträdelse i alla deras synder. Sammalunda skall han göra vittnesbördsens tabernakel; ty de äro orene, som omkring ligga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Ingen menniska skall vara inuti vittnesbördsens tabernakel, när han går derin till att försona i helgedomenom, tilldess han går ut igen; och skall alltså försona sig och sitt hus, och hela Israels menighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Och när han utgår till altaret, som står för Herranom, skall han försona det; och skall taga af stutens blod, och af bockens blod, och stryka på altarens horn allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Och skall stänka af blodet med sitt finger sju resor deruppå, och rensa, och helga det af Israels barnas orenhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Och när han fullkomnat hafver helgedomens och vittnesbördsens tabernakels och altarens försoning, skall han hafva fram den lefvande bocken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Och skall då Aaron lägga båda sina händer på hans hufvud, och bekänna öfver honom alla Israels barnas missgerningar, och all deras öfverträdelse i alla deras synder, och skall lägga dem på bockens hufvud, och låta honom löpa genom någon mans hjelp, som förhanden är, i öknena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Att bocken skall bortbära alla deras missgerningar på sig uti vildmarkena; och låta honom i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Och Aaron skall gå in uti vittnesbördsens tabernakel, och afkläda sig de linna kläden, som han på sig klädt hade, då han gick in uti helgedomen, och skall der låta blifva dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Och skall bada sitt kött med vatten på heligt rum, och kläda sin egen kläder uppå, och gå derut, och göra sitt bränneoffer och folkens bränneoffer, och försona både sig och folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Och bränna upp det feta af syndoffret på altarena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Men den, som förde fribocken ut, skall två sin kläder, och bada sitt kött med vatten, och sedan komma igen i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Syndoffrens stut och syndoffrens bock, hvilkas blod till försoning buret vardt in i helgedomen, skall man föra utom lägret, och uppbränna i elde, både deras hud, kött och träck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Och den som bränner det upp, han skall två sin kläder, och bada sitt kött med vatten, och sedan komma i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Och skall detta vara eder en evig rätt: På tionde dagenom i sjunde månadenom skolen I späka edra kroppar, och ingen gerning göra, vare sig inländsk eller utländsk ibland eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Förty på den dagen sker eder försoning, så att I varden rengjorde; ifrån alla edra synder varden I rengjorde för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Derföre skall det vara eder den störste Sabbath, och I skolen späka edra kroppar; en evig rätt vare det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Men den försoningen skall en Prest göra, den man vigt hafver, och hvilkens hand man fyllt hafver till en Prest i hans faders stad; och skall kläda på sig de linna kläder, som äro de helga kläden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Och skall alltså försona den helga helgedomen, och vittnesbördsens tabernakel, och altaret, och Presterna, och allt folket af menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Det skall vara eder en evig rätt, att I försonen Israels barn af alla deras synder, ena reso om året. Och Mose gjorde såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Tala med Aaron och hans söner, och all Israels barn, och säg till dem: Detta är det Herren budit hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Hvilken af Israels hus, som i lägret, eller utanför lägret, slagtar en oxa, eller lamb, eller get;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Och intet bär fram för dörrena af vittnesbördsens tabernakel det som Herranom för ett offer buret varder inför Herrans boning, han skall för blod brottslig vara, såsom den som blod utgjutit hafver; och sådana menniska skall utrotad varda utu sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Derföre skola Israels barn deras offer, som de på fria markene offra vilja, bära fram för Herran, inför dörrena af vittnesbördsens tabernakel till Presten, och der offra deras tackoffer Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Och Presten skall stänka blodet på Herrans altare inför dörrene af vittnesbördsens tabernakel, och bränna upp det feta, Herranom till en söt lukt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Och ingalunda mer offra djeflomen deras offer, med hvilkom de hor bedrifva. Det skall dem vara en evig rätt i deras efterkommandom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Derföre skall du säga dem: Hvilken menniska af Israels huse, eller ock en främling, den ibland eder är, som gör ett offer eller bränneoffer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Och bär det icke inför dörrena af vittnesbördsens tabernakel, att han gör det Herranom, den skall utrotad varda utu hans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Och hvilken menniska, vare sig af Israels huse, eller en främling ibland eder, äter något blod; emot honom skall jag sätta mitt anlete, och skall utrota honom midt utu hans folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Ty kroppsens lif är uti blodet, och jag hafver gifvit eder det till altaret, att edra själar skola dermed försonade varda; förty blodet är försoning för lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Derföre hafver jag sagt Israels barnom: Ingen själ ibland eder skall äta blod, och ingen främling, som ibland eder bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Och hvilken menniska, vare sig af Israels huse, eller en främling ibland eder, som tager ett djur eller fogel i jagt, det man äter, han skall utgjuta dess blod, och öfvertäcka honom med jord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Ty kroppsens lif är i sinom blod. Och jag hafver sagt Israels barnom: I skolen ingen kropps blod äta; ty kroppsens lif är i sinom blod. Den det äter, han skall utrotad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Och hvilken själ som äter ett as, eller det af vilddjur rifvet är, vare sig en inländsk eller utländsk, han skall två sin kläder, och bada sig med vatten, och vara oren intill aftonen, så varder han ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Om han icke tvår sin kläder, eller sig icke badar, skall han bära sina missgerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Tala med Israels barn, och säg till dem: Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'I skolen icke göra efter som görs i Egypti land, der I bott hafven; och icke efter som görs i Canaans land, der jag dig införa skall; I skolen icke heller hålla eder vid deras sätt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Utan efter mina rätter skolen I göra, och mina stadgar skolen I hålla, att I vandren derutinnan; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Derföre skolen I hålla mina stadgar, och mina rätter; ty hvilken menniska dem gör, han skall derigenom lefva; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Ingen skall gå in till sina nästa blodsfränko, till att blotta hennes blygd; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Du skall dins faders och dine moders blygd icke blotta; hon är din moder, derföre skall du icke blotta hennes blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Du skall icke blotta dins faders hustrus blygd; ty det är dins faders blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Du skall icke blotta dine systers blygd, den dins faders, eller dine moders dotter är, hemma eller ute född.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Du skall icke blotta dine sonadotters, eller dine dotterdotters blygd; ty det är din blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Du skall icke blotta dins faders hustrus dotters blygd, den dinom fader född är, och din syster är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Du skall icke blotta dins faders systers blygd; ty det är dins faders nästa blodsfränka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Du skall icke blotta dine moders systers blygd; ty hon är dine moders nästa blodsfränka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Du skall icke blotta dins faderbroders blygd, så att du tager hans hustru; ty hon är din svägerska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Du skall icke blotta dine sonahustrus blygd; ty hon är dins sons hustru, derföre skall du icke blotta hennes blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Du skall icke blotta dins broders hustrus blygd; ty hon är dins broders blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Du skall icke blotta dine hustrus, samt med hennes dotters blygd; ej heller taga hennes sons dotter, eller dotterdotter, till att blotta hennes blygd; ty hon är hennes nästa blodsfränka; och det är en last.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Du skall ock icke taga dine hustrus syster, till att blotta hennes blygd, henne emot, medan hon ännu lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Du skall icke gå in till qvinnona, så länge hon hafver sina sjuko i sine orenhet, till att blotta hennes blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Du skall ock icke ligga när dins nästas hustru, till att beblanda dig med henne, dermed du orenar dig på henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du skall ock icke gifva af dine säd, att det skall uppbrännas för Molech, att du icke ohelgar dins Guds Namn; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Du skall icke ligga när dränger, såsom när ena qvinno; ty det är en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Du skall ock icke ligga när något djur, att du dermed orenar dig; och ingen qvinna skall skaffa hafva med något djur; ty det är en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'I skolen uti intet af detta orena eder; förty uti allt detta hafva Hedningarna orenat sig, hvilka jag skall här utdrifva för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Och landet är derigenom orenadt; och jag skall söka deras missgerningar på dem, så att landet skall utspy sina inbyggare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Derföre håller mina stadgar och rätter, och görer intet af denna styggelsen, antingen inländske eller utländske ibland eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Ty all sådana styggelse hafva landsens folk gjort, som för eder voro, och hafva orenat landet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'På det att landet ock icke utspyr eder, då I det orenen, lika som det hafver utspytt Hedningarna, som för eder voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Förty de som göra denna styggelsen, deras själar skola utrotade varda utu deras folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Derföre håller mina stadgar, att I icke gören efter de styggeliga seder, som för eder voro, att I icke dermed orenade varden; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Tala med hela menighetene af Israels barn, och säg till dem: I skolen vara helige; ty jag är helig, Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Hvar och en frukte sina moder, och sin fader. Håller mina helgedagar; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'I skolen icke vända eder till afgudar, och skolen icke göra eder gjutna gudar; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Och när I viljen göra Herranom tackoffer, så skolen I offra det, att det må vara honom täckt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Och skolen det äta på samma dagen, då I offren det, och på den andra dagen. Hvad qvart blifver till tredje dagen, det skall man bränna upp i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Äter der någor af på tredje dagen, så är han en styggelse, och varder icke tacknämlig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Och den samme ätaren skall bära sin missgerning, att han Herrans helgedom hafver ohelgat; och den själen skall utrotad varda utu sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'När du uppskär af ditt land, skall du icke skära intill ändan allt omkring, och icke noga allt afhemta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Sammalunda skall du ej heller noga berga din vingård, eller upphemta de affallna bären; utan skall det blifva låta för de fattiga och främlingar: ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'I skolen icke stjäla eller ljuga, eller handla falskeliga den ene med den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'I skolen icke svärja falskt vid mitt Namn, och ohelga dins Guds Namn; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du skall icke göra dinom nästa orätt, eller röfva honom. Din dagakarls lön skall icke blifva när dig intill morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du skall icke banna dem döfva. Du skall icke sätta för den blinda något der han kan stöta sig uppå; utan du skall frukta din Gud; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'I skolen icke handla orätt i dome, och skall icke skona dem ringa, och icke ära den mägtiga; utan skall döma dinom nästa rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du skall icke vara en bakdantare ibland ditt folk. Du skall ock icke stå emot dins nästas blod; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du skall icke hata din broder i dino hjerta; utan du skall straffa din nästa, på det du icke skall lida skuld för hans skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du skall icke hämnas, och icke behålla någon ovilja emot dins folks barn. Du skall älska din nästa såsom dig sjelfvan; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Mina stadgar skolen I hålla, att du icke låter din boskap hafva beblandning med annor djur; och icke sår din åker med blandad säd; och att ingen klädnad kommer på dig, som af ull och lin tillhopa kommen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Om en man ligger när ena qvinno, och beblandar sig med henne, och hon är en trälinna, och är af enom androm kränkt, dock är icke löst, eller frihet fått hafver, det skall straffadt varda; men icke skola de dö; ty hon hafver icke varit fri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Men han skall frambära Herranom för sina skuld en vädur till skuldoffer, inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Och Presten skall försona honom med skuldoffret för Herranom, för den synd, som han gjort hafver; så varder honom Gud nådelig öfver hans synd, som han gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'När I kommen i landet, och planteren allahanda trä, der man af äter, skolen I afskära deras förhud med deras frukt; i tre år skolen I hålla dem för oomskorna, så att I icke äten dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Men i fjerde årena skall all deras frukt vara helgad och prisad Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'I femte årena skolen I äta fruktena, och samla henne in; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'I skolen intet äta med blod. I skolen icke akte på foglarop; eller välja några dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'I skolen icke skära någon plätt på edart hufvud, och icke allstinges raka edart skägg af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'I skolen icke skära något märke på edar kropp öfver en dödan; eller skrifva bokstäfver på eder; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du skall icke hålla dina dotter till boleri; på det att landet icke skall bedrifva boleri, och varda fullt med laster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Håller mina helgedagar, och frukter för min helgedom; ty Jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'I skolen icke vända eder till spåmän, och fråger intet af de tecknatydare, att I icke varden orenade på dem; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'För ett grått hufvud skall du uppstå, och ära de gamla; ty du skall frukta din Gud; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Om en främling varder boendes när eder i edro lande, den skolen I icke öfverfalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Han skall bo när eder såsom en inländsk ibland eder; och du skall älskan såsom dig sjelfvan; förty I voren ock främlingar i Egypti lande. Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'I skolen intet olika handla, i dom, med aln, med vigt, med mått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Rätt våg, rätt pund, rätt skäppa, rätt kanna skall vara när eder; ty jag är Herren edar Gud, som hafver fört eder utur Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Att I skolen hålla och göra alla mina stadgar, och alla mina rätter; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Säg Israels barnom: Hvilken af Israels barn, eller en främling, som bor i Israel, gifver af sine säd Molech, han skall döden dö; folket i landena skall stena honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Och jag skall sätta mitt anlete emot sådana mennisko, och skall utrota honom utu hans folk; derföre, att han af sine säd gifvit hafver Molech, och orenat min helgedom, och ohelgat mitt helga Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Och om folket i landet se genom finger med de menniskone, som af sine säd hafver gifvit Molech, så att de icke dräpa honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Så vill jag dock sätta mitt anlete emot den menniskon och emot hans slägt, och skall utrota honom, och alla de som efter honom med Molech hor bedrifvit hafva, utu deras folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Om en själ vänder sig till spåmän och tecknatydare, så att hon hor bedrifver efter dem; så vill jag sätta mitt anlete emot den samma själen, och vill utrota henne utu hennes folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Derföre helger eder, och varer helige; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Och håller mina stadgar, och görer dem; ty jag är Herren, den eder helgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Den som bannar sin fader eller sina moder, han skall döden dö; hans blod vare öfver honom, att han sin fader eller moder bannat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Den som hor bedrifver med någors mans hustru, den skall döden dö, både horkarlen och horkonan; derföre, att han med sins nästas hustru hor bedrifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Om någor ligger när sins faders hustru, så att han sins faders blygd blottat hafver, de skola både döden dö; deras blod vare öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Om någor ligger när sina sonahustru, så skola de både döden dö; förty de hafva gjort ena skam; deras blod vare öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Om någor ligger när en dräng, såsom när ena qvinno, de hafva gjort en stygghet, och skola både döden dö; deras blod vare öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Om någor tager en hustru, och hennes moder dertill, han hafver gjort en last; man skall bränna honom upp i elde, och de båda med, att ingen last blifver ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Om någor hafver skaffa med oskälig djur, han skall döden dö; och djuret skall man dräpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Om en qvinna låter sig in till något oskäligt djur, så att hon dermed hafver skaffa, den skall du dräpa, och djuret desslikes, Döden skola de dö; deras blod vare öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Om någor tager sina syster, sins faders dotter, eller sine moders dotter, och skådar hennes blygd, och hon åter hans blygd, det är en skam; de skola förgöras inför deras slägtes folk; ty han hafver blottat sine systers blygd. Han skall bära sina skuld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Om en man ligger när ena qvinno i hennes krankhets tid, och blottar hennes blygd, och upplåter hennes brunn, och hon blottar sins blods brunn; de skola både förgjorde varda utu deras folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Dine modersysters blygd, och dine fadersysters blygd skall du icke blotta; ty en sådana hafver sina nästa blodsfränko blottat; och de skola bära deras skuld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Om någor ligger när sins faderbroders hustru, den hafver sins faderbroders blygd blottat; de skola bära deras synd; utan barn skola de dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Om någor tager sins broders hustru, det är en skamlig gerning; de skola vara utan barn, derföre att han hafver sins broders blygd blottat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Så håller nu alla mina stadgar och mina rätter, och görer dem, på det landet icke utspyr eder, der jag eder införer, att I deruti bo skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Och vandrer icke uti Hedningarnas stadgar, hvilka jag skall utdrifva för eder; ty allt sådant hafva de gjort, och jag hafver haft en styggelse vid dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Men eder säger jag: I skolen besitta deras land; ty jag skall gifva eder ett land i arf, der mjölk och hannog uti flyter. Jag är Herren edar Gud, den eder afskiljt hafver ifrån annat folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Att I ock skilja skolen den rena boskapen ifrå den orena; och orena foglar ifrå de rena; och icke orena edra själar på boskap, och foglar, och på allt det på jordene kryper, det jag eder afskiljt hafver, att det skall vara orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Derföre skolen I vara mig helige; ty jag Herren är helig, den eder afskiljt hafver ifrån annat folk, att I skolen höra mig till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Om någor man eller qvinna varda en spåman, eller en tecknatydare, de skola döden dö. Man skall stena dem; deras blod vare öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Och Herren sade till Mose: Tala till Presterna, Aarons söner, och säg till dem: En Prest skall icke orena sig på någon dödan af sitt folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Utan på sin skyldman, den honom näst tillkommer, såsom på sin moder, på sin fader, på sin son, på sin dotter, på sin broder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Och på sin syster, den ännu en jungfru och ingens mans hustru varit hafver; den hans nästa skyldman är, på dem må han orena sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Eljest skall han icke orena sig på någon, som honom är vederkommande ibland hans folk, så att han sig ohelgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Han skall ock ingen plätt göra på sitt hufvud, eller afraka sitt skägg, och på hans kropp intet märke skära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'De skola sinom Gudi helige vara, och icke ohelga sins Guds Namn; förty de offra Herrans offer, deras Guds bröd; derföre skola de vara helige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Han skall icke taga någon sköko, eller ena förkränkta, eller den som af sin man bortdrifven är; ty han är helig sinom Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Derföre skall du räkna honom helig; ty han offrar dins Guds bröd. Han skall vara dig helig; ty jag är helig, Herren, som eder helgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Om ens Prests dotter begynner till att bola, den skall man uppbränna i elde; ty hon hafver skämt sin fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Hvilken öfverste Prest är ibland hans bröder, på hvilkens hufvud smörjooljan gjuten är, och hans hand fylld är, så att han med kläden iklädd varder, den skall icke blotta sitt hufvud, och icke skära sin kläder sönder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Och skall till ingen dödan komma, och skall icke orena sig, hvarken öfver fader eller moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Utu helgedomenom skall han icke gå, att han icke ohelgar sins Guds helgedom; ty vigelsen, hans Guds smörjoolja, är på honom. Jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Ena jungfru skall han taga sig till hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Men inga enko, eller bortdrefna, eller förkränkta, eller sköko; utan ena jungfru, af sitt folk, skall han taga till hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'På det han icke skall ohelga sina säd ibland sitt folk; ty jag är Herren, som honom helgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Tala med Aaron, och säg: Om någor vank är på någrom af dine säd uti edart slägte, den skall icke gå fram, att han offrar sins Guds bröd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Förty hvar och en, den någon vank hafver, skall icke gå fram, vare sig blind, halt, med ene stygga näso, med oskickeliga lemmar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Eller den som hafver en sönderbruten fot eller hand,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Eller kroppog är, eller hinno på ögonen hafver, eller vindögd, eller maslog, eller skabbog, eller förbråken är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Den som nu af Prestens Aarons säd hafver en vank uppå sig, han skall icke gå fram till att offra Herrans offer; ty han hafver en vank, derföre skall han intet nalkas intill sins Guds bröd, att han dem offrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Dock skall han äta af sins Guds bröde, både af de helgo, så ock af de aldrahelgasto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Men dock skall han icke komma in till förlåten, ej heller nalkas altarena, så länge sådana vank på honom är, att han icke ohelgar min helgedom; ty jag är Herren, som helgar dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Och Mose sade detta till Aaron, och till hans söner, och till all Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Säg Aaron och hans söner, att de hålla sig ifrån Israels barnas helgo, hvilket de mig helga, och icke ohelga mitt helga Namn; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Säg dem nu till, och deras efterkommandom: Hvilken af edor säd går till det helga, som Israels barn helga Herranom, och orenar sig så på det, hans själ skall utrotad varda för mitt anlete; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Hvilken af Aarons säd är spitelsk, eller hafver ena flöd, den skall icke äta af de helgo, tilldess han varder ren. Den som kommer vid någon oren kropp, eller den som hans säd afgår i sömnen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Eller den som kommer vid en matk, den honom oren är, eller en mennisko, som honom oren är, och allt det honom orenar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Hvilken själ kommer vid något deraf, den är oren intill aftonen, och skall icke äta af de helgo; utan skall först bada sin kropp med vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Och när solen är nedergången, och han ren vorden är, då må han äta deraf; ty det är hans spis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Ett as, och hvad af vilddjur rifvet är, skolen I icke äta, att I icke skolen varda orene deruppå; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Derföre skola de hålla mina stadgar, att de icke skola lägga synd uppå sig, och dö deröfver, när de ohelga sig; ty jag är Herren, som dem helgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Ingen annar skall äta af de helgo, ej heller Prestens husman, ej heller någon dagakarl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'När Presten köper ena själ för sina penningar, den må äta deraf. Och det i hans huse födt är, det må ock äta af hans bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Om Prestens dotter varder ens främmandes hustru, skall hon icke äta af dess helgas häfoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Varder hon en enka, eller utdrifven, och hafver ingen säd, och kommer igen till sins faders hus, så skall hon äta af sins faders bröd, såsom då hon ännu piga var; men ingen främmande skall äta deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Hvilken som eljest äter af de helgo ovetandes, han skall lägga femtedelen dertill, och gifva Prestenom med de helgo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'På det att de icke skola ohelga Israels barnas helga, som de häfoffra Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Att de icke skola lägga missgerning och skuld på sig, när de äta af deras helgo; ty jag är Herren, som dem helgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Säg Aaron och hans söner, och all Israels barn: Hvilken Israelit eller främling i Israel vill göra sitt offer, vare sig af löfte, eller af fri vilja, att de vilja göra Herranom ett bränneoffer, det honom skall vara tacknämligit af eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Det skall vara ett mankön, och utan vank, af fä, lambom eller getom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Allt det som något fel hafver, skolen I icke offra; förty det varder icke tacknämligit för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Och hvilken ett tackoffer Herranom göra vill, ett besynnerligit löfte, eller af fri vilja, af fä eller får, det skall vara utan vank, att det må varda tacknämligit. Det skall hafva ingen vank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Är det blindt, eller brutet, eller sargadt, eller förtvinadt, eller maslogt, eller skabbogt; så skola de icke sådant offra Herranom, och intet offer deraf gifva på Herrans altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'En oxe eller får, som oskickeliga eller lytta lemmar hafver, må du offra af en fri vilja; men icke varder det tacknämligit för ett löfte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Du skall ock icke offra Herranom något det förkramadt, eller förstött, eller förslitet, eller utskuret är; och skolen sådant icke göra i edro lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Du skall ock icke offra något sådant af ens främlings hand, med edars Guds bröd; ty det doger intet, och hafver en vank; derföre varder det icke tacknämligit för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'När en kalf, eller lamb, eller get födt är, så skall det vara när sine moder i sju dagar; på åttonde dagen och derefter må man offra det Herranom, så är det tacknämligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Vare sig nöt eller får, så skall man icke slagta det med sin unga på enom dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'När I viljen göra Herranom ett lofoffer, det för eder tacknämligit skall vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Så skolen I äta det på samma dagen, och skolen intet behålla qvart intill morgonen; ty jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Derföre håller min bud, och görer dem; ty jag är Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Att I icke ohelgen mitt helga Namn, och att jag må helgad varda ibland Israels barn; ty jag är Herren, den eder helgar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Den eder utur Egypti land fört hafver, att jag skulle vara edar Gud: Jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Tala till Israels barn, och säg till dem: Desse äro Herrans högtider, som I skolen kalla heliga och mina högtider, då I sammankommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sex dagar skall du göra ditt arbete; men den sjunde dagen är den store helge Sabbathen, då I tillhopakommen. Intet arbete skolen I göra på honom; förty det är Herrans Sabbath, ehvar I bon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Desse äro de Herrans högtider, dem I skolen kalla helga högtider, då I sammankommen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'På fjortonde dagen i första månadenom om aftonen är Herrans Passah;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Och på den femtonde i samma månadenom är Herrans osyrade bröds högtid; då skolen I äta osyradt bröd i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Den förste dagen skall kallas helig ibland eder, då I sammankommen; då skolen I intet tjenstearbete göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Och offra Herranom i sju dagar. Den sjunde dagen skall ock helig kallas, då I tillhopakommen; på honom skolen I ock intet tjenstearbete göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Tala till Israels barn, och säg till dem: När I kommen i landet, som jag eder gifva skall, och I skolen uppskära, så skolen I föra till Presten en kärfva, förstlingen af edro säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Då skall den kärfven varda veftad för Herranom, att det skall blifva tacknämligit af eder. Och detta skall Presten göra på den andra dagen näst efter Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Och I skolen på den dagen, då edar kärfve veftad varder, göra Herranom ett bränneoffer af ett lamb, det utan vank och årsgammalt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Samt med spisoffret, två tiungar semlomjöl, blandadt med oljo, till en söt lukts offer Herranom; dertill dryckoffer, en fjerding af ett hin vin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Och skolen intet äta af det nya, hvarken bröd, torkad ax eller korn, intill den dagen, då I bären edrom Gud offer. Det skall vara en evig rätt till edra efterkommande, ehvar I bon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Sedan skolen I räkna ifrå den andra Sabbathsdagen, då I båren veftekärfvan fram, sju hela Sabbather;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Intill den andra dagen efter den sjunde Sabbathen; det är, femtio dagar skolen I räkna och offra Herranom nytt spisoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Och skolen offra det af alla edra boningar, nämliga tu veftebröd af två tiungar semlomjöl, syradt och bakadt Herranom till en förstling;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Och skolen frambära med edor bröd sju årsgamla lamb utan vank, och en ung stut, och två vädrar. Det skall vara Herrans bränneoffer, spisoffer och dryckoffer; det är en söt lukts offer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Dertill skolen I göra en getabock till syndoffer, och tu årsgamla lamb till tackoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Och Presten skall vefta det med förstlingsbrödena för Herranom till de tu lamben; och skall vara Herranom heligt, och höra Presten till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Och I skolen utropa denna dagen; ty han skall kallas helig ibland eder, då I sammankommen; intet tjenstearbete skolen I göra. En evig rätt skall det vara, till edra efterkommande, ehvar I bon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'När I uppskären sädena i edro lande, skolen I icke allt uppskära på åkren, och icke alltför noga upphemta; utan skolen det låta dem fattigom, och främlingom. Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Tala med Israels barnom, och säg: På första dagen i sjunde månadenom skolen I hålla blåsandens helga Sabbath till åminnelse, då I sammankommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Då skolen I intet tjenstearbete göra; och skolen göra Herranom offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'På tionde dagen i denna sjunde månadenom är Försonedagen; den skall ibland eder kallas helig, att I tillhopakommen. Då skolen I späka edra kroppar, och offra Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Och skolen intet arbete göra på denna dagen; ty det är en försonedag, att I skolen försonade varda för Herranom edrom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Ty hvilken icke späker sin kropp på denna dagen, den skall utrotad varda utu hans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Och hvilken på denna dagen något arbete gör, den skall jag förgöra utu hans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Derföre skolen I intet arbete göra. Det skall vara en evig rätt till edra efterkommande, ehvar I bon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Det är edar store Sabbath, att I skolen späka edra kroppar. På nionde dagen i månadenom om aftonen skolen I hålla denna Sabbath, ifrån aftonen och åter intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Tala med Israels barn, och säg: På femtonde dagen i denna sjunde månadenom är löfhyddohögtid i sju dagar Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Den förste dagen skall kallas helig, att I sammankommen; intet tjenstearbete skolen I göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'I sju dagar skolen I offra Herranom. Den åttonde dagen skall ock kallas helig, att I sammankommen. Och I skolen göra edart offer Herranom; ty det är samlingesdag; intet tjenstearbete skolen I göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Desse äro Herrans helgedagar, de I skolen heliga hålla, att I sammankommen, och gören Herranom offer, bränneoffer, spisoffer, dryckoffer, och annor offer, hvart efter sin dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Förutan det Herrans Sabbath, och edra gåfvor och löfte, och friviljoga gåfvor äro, som I gifven Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Så skolen I nu på femtonde dagen i sjunde månadenom, när I hafven i hus samlat årsväxten af landena, hålla Herrans högtid i sju dagar. På första dagenom är Sabbath, och på åttonde dagenom är ock Sabbath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Och I skolen på första dagenom taga frukt af skön trä, palmtelningar, och qvistar af tjockqvistadt trä, och pilträ; och vara glade i sju dagar för Herranom edrom Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Och skolen alltså hålla Herranom den högtiden om året i sju dagar; det skall vara en evig rätt till edra efterkommande, att de så skola hålla helg uti den sjunde månaden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sju dagar skolen I bo i löfhyddor. Den en inländning är i Israel, han skall bo i löfhyddor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Att edra efterkommande skola veta, huru jag hafver låtit Israels barn bo i hyddor, då jag förde dem utur Egypti land. Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Och Mose sade Israels barnom om denna Herrans helg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Bjud Israels barnom, att de bära till dig klara stötta bomoljo till lysning, hvilken dagliga skall slås upp i lamporna,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Utanför vittnesbördsens förlåt i vittnesbördsens tabernakel. Och Aaron skall sköta det både afton och morgon för Herranom dagliga. Det skall vara en evig rätt med edra efterkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Och skall han pynta till lamporna på den sköna ljusastakanom för Herranom dagliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Och du skall taga semlomjöl, och baka deraf tolf kakor; en kaka skall hålla två tiungar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Och skall lägga dem, ju sex i hvar hop, på det sköna bordet för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Och skall lägga på dem rent rökelse, att det skall vara åminnelsebröd till ett offer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'På hvar Sabbathsdag skall han pynta dem till Herranom alltid, af Israels barn till ett evigt förbund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Och skola höra Aaron och hans söner till, de skola äta dem på heligt rum; ty det är hans aldrahelgasta af Herrans offer till en evig rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Och en man utgick, enes Israelitiska qvinnos son, den ens Egyptisk mans son var ibland Israels barn, och trätte med en Israelitisk man i lägret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Och nämnde Namnet, och bannades. Då hade de honom fram för Mose. Och hans moder het Selomith, Dibri dotter, af Dans slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Och de lade honom i fängelse, tilldess dem vorde viss svar gifven genom Herrans mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'För honom ut för lägret, som bannats hafver, och låt alla dem som det hörde, lägga sina händer på hans hufvud, och låt hela menigheten stena honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Och säg Israels barnom: Hvilken som bannar sin Gud, han skall bära sina synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Hvilken som Herrans Namn nämner, han skall döden dö; hela menigheten skall stena honom. Såsom utländningen, så skall ock inländningen vara; om han nämner det Namnet, så skall han dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Om någor slår ena mennisko, han skall döden dö;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Men den som slår någon boskap, han skall betalat kropp för kropp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Och den som gör sinom nästa skada, honom skall man göra såsom han gjorde:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Skada för skada, öga för öga, tand för tand; såsom han hafver gjort ene mennisko skada, så skall man göra honom igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Så att den som slår någon boskap, den skall betalat; men den som slår ena mennisko, han skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Samma rätten skall vara ibland eder, så för utländningen, som för inländningen; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Och Mose sade detta för Israels barnom, och förde honom, som bannats hade, ut för lägret, och stenade honom. Och alltså gjorde Israels barn, såsom Herren Mose budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Och Herren talade med Mose på Sinai berg, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Tala med Israels barn, och säg till dem: När I kommen in uti det land, som jag eder gifvandes varder, skolen I hålla landsens helg Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Så att du i sex år sår din åker, och i sex år skär din vingård, och samlar in fruktena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Men på sjunde årena skall landet hålla Herranom sina stora helg, i hvilko du icke skall så din åker, eller berga din vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Och hvad af sig sjelfvo växer, efter din afbergning, skall du icke berga; och de vindrufvor, som utan ditt arbete växte äro, skall du icke afhemta, efter det är landsens helgår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Utan landsens helgår skall du fördenskull hålla, att du skall äta deraf, din tjenare, din tjenarinna, din dagakarl, din husman, din främling när dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Din boskap, och djuren i ditt land, allt det der växer skall vara till mats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Och du skall räkna sju sådana helgår, så att sju år skola sju resor tald varda, och den sju helgårs tiden gör nio och fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Då skall du låta blåsa i basunen öfver allt edart land, på tionde dagen i sjunde månadenom, rätt på Försonedagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Och I skolen helga det femtionde året, och skolen kalla det ett friår i landena, allom dem som bo derinne; ty det är edart klangår. Så skall hvar och en när eder komma till sina ägor igen, och till sina slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ty det femtionde året är edart klangår. I skolen intet så, ej heller uppskära det af sig sjelfvo växt är, ej heller afhemta i vingårdenom det utan arbete växt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Förty klangåret skall vara heligt ibland eder. Men I skolen äta allt det som marken bär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Det är klangåret, i hvilko hvar man skall komma till sitt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Om du något säljer dinom nästa, eller något köper af honom, skall ingen besnika sin broder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Men efter klangårens tal skall du köpa det af honom, och hvad åren sedan draga kunna, derefter skall han sälja dig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Efter som åren äro mång till, så skall du låta risa köpet, och efter som de äro få till, skall du låta köpet falla; ty han skall sälja dig det efter som det draga kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Så besnike nu ingen sin nästa, utan frukta din Gud; ty Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Derföre görer efter mina stadgar, och håller mina rätter, att I dem gören, på det I mågen tryggeliga bo i landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Ty landet skall gifva eder sina frukt, att I skolen hafva nog till att äta, och bo tryggeliga derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Och om du vorde sägandes: Hvad skole vi äta på sjunde årena; ty vi så intet, och församle ingen årsväxten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Så vill jag bjuda min välsignelse i sjette årena öfver eder, så att det skall göra eder treåra växt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Det I sån på de åttonde årena, och af den gamla årsväxten, der äter af intill nionde året, så att I äten af det gamla, intilldess åter ny årsväxt kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Derföre skolen I icke sälja landet evinnerliga; ty landet är mitt, och I ären främmande och gäster före mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Och I skolen i allt edart land låta landet till lösen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Om din broder varder fattig, och säljer dig sina ägor, och hans näste skyldman kommer till honom, och vill lösat, så skall han lösa det hans broder sålt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Om någor vore, som ingen lösare hafver, och kan med sine hand så mycket åstadkomma, att han löser en del;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Då skall man räkna åratalet sedan han såldet, och hvad igenstår, gifve honom, som köpt hafver, att han må komma till sina ägor igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Om hans hand icke kan finna så mycket, att han kan få någon del igen, så skall det, som han sålt hafver, vara i köparens händer intill klangåret; då skall det vara ute, och han komme till sina ägor igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Ho som säljer bort ett boningahus innan stadsmuren, han hafver ett helt års frist till att lösa det igen; det skall vara tiden, innan hvilken han det lösa må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Om han icke löser det förra än hela året ute är, så skall köparen behålla det evinnerliga, och hans efterkommande; och skall icke löst utgå i klangårena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Men är det ett hus i sådana by, der ingen mur om är, det skall man räkna lika med markene i landena; och skall varda löst, och i klangårena fritt utgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'De Leviters städer, och husen i städerna, der deras ägor inne äro, måga alltid löste varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Den som något löser ifrå de Leviter, den skall gå derifrån i klangårena; vare sig hus eller stad, som han besutit hafver; förty husen uti de Leviters städer äro deras ägor ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Men markena för deras städer skall man icke sälja; förty det är deras egendom evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Om din broder varder fattig, och afsigkommer när dig, så skall du taga honom till dig, såsom en främling eller husman, att han må lefva när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Och du skall icke taga ocker af honom, eller vinning; utan skall frukta din Gud, att din broder må lefva bredevid dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Ty du skall icke få honom dina penningar på ocker, och icke utfå din spis på fördel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ty jag är Herren edar Gud, den eder utur Egypti land fört hafver, att jag skulle gifva eder det landet Canaan, och vara edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Om din broder varder fattig när dig, och säljer sig dig, så skall du icke låta honom göra trälars arbete;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Utan han skall vara när dig, såsom en dagakarl och en husman, och tjena dig intill klangåret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Då skall han gå lös ut ifrå dig, och hans barn med honom; och skall komma till sitt slägte igen, och till sina fäders ägor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Förty de äro mine tjenare, de jag utur Egypti land fört hafver; ty skall man icke sälja dem efter trälars sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Och skall du icke med stränghet råda öfver dem, utan frukta din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Men vill du hafva trälar och trälinnor, så skall du köpa dem af Hedningarna, som omkring eder äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Af husmän, som främlingar ibland eder äro, och af deras afkommandom, som de när eder uti edro lande föda, dem skolen I hafva till egna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Och skolen äga dem, och edor barn efter eder till en evig ägo; dem skolen I låta vara trälar. Men öfver edra bröder, Israels barn, skall ingen öfver den andra råda med stränghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Om en främling eller en husman växer till när dig, och din broder varder fattig när honom, och säljer sig enom främling, eller husmanne när dig, eller någrom af sine slägt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Så skall han rätt hafva, sedan han såld är, att varda löst igen; och någor af hans bröder må lösa honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Eller hans faderbroder, eller faderbroders son, eller eljest någor hans när skyldman i hans slägte; eller om hans egen hand kan så mycket åstadkomma, så skall han lösa sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Och skall räkna med sin köpare ifrå det året, då han sålde sig, intill klangåret. Och penningarna skola räknade varda efter åratalet, sedan han såldes; och skall hans lön med inräknas för hela tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Om ännu mång år äro intill klangåret, så skall han derefter desto mer gifva för lösnen, efter som han köpt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Äro få år qvar intill klangåret, så skall han ock derefter igengifva till sin lösning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Och skall räkna sin lön med honom år från år. Och du skall icke låta råda öfver honom med stränghet för din ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Om han icke löser sig i denna måtto, så skall han i klangåret lös utgå, och hans barn med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Förty Israels barn äro mine tjenare, de jag utur Egypti land fört hafver. Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'I skolen icke göra eder några afgudar, eller beläte, icke heller uppresa eder några stodar, icke heller någon vårdsten sätta uti edro lande, till att tillbedja derföre; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Håller mina Sabbather, och frukter eder för min helgedom. Jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Om I vandren i minom stadgom, och hållen min bud, och gören dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Så skall jag gifva eder regn i sinom tid; landet skall gifva sin växt, och trän på markene bära sina frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Och tröskotiden skall räcka intill vinandena, och vinanden skall räcka intill sädestiden. Och I skolen hafva bröd nog, och skolen tryggeliga bo i edro lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Jag skall gifva frid i edro lande, att I skolen sofva, och ingen förfära eder. Jag skall låta komma de onda djur utur edro lande, och intet svärd skall gå genom edart land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'I skolen jaga edra fiendar, och de skola falla för eder genom svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Fem af eder skola jaga hundrade, och hundrade af eder skola jaga tiotusende; ty edra fiender skola falla för eder genom svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Och jag skall vända mig till eder; jag skall föröka eder, och låta eder växa till, och jag skall göra mitt förbund fast med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Och I skolen äta af det gamla, så att I skolen låta det gamla fara för det nya.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Jag skall hafva min boning ibland eder, och min själ skall icke förkasta eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Och jag skall vandra ibland eder, och skall vara edar Gud, så skolen I vara mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ty jag är Herren edar Gud, den eder utur Egypti land fört hafver, att I icke skullen vara deras trälar; och hafver sönderbrutit edart ok, och hafver låtit eder gå rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Men om I icke hören mig, och icke gören dessa buden all;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Utan förakten mina stadgar, och edra själar förkasta mina rätter, så att I icke gören all min bud, och låten mitt förbund tillbaka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Så skall jag ock då göra eder detta: Jag skall hemsöka eder med förskräckelse, svullnad, och skälfvo, att edor ansigte förfalla, och edra kroppar försmäkta skola; I skolen fåfängt så edra säd, och edre fiender skola äta henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Och jag skall ställa mitt anlete emot eder, och I skolen varda slagne för edra fiendar. Och de som hata eder, skola råda öfver eder, och skolen fly, då ingen jagar eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Om I ändå icke hören mig, så skall jag ännu sju resor mer görat, till att näpsa eder för edra synder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Att jag edra högfärd och genstörtighet nederslå skall. Och jag skall göra edar himmel såsom jern, och edra jord såsom koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Och edor möda och arbete skall förtappadt vara, så att edart land icke skall gifva sin växt, och trän i landet icke bära sina frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Och om I vandren mig emot, och icke viljen höra mig, så skall jag ändå görat sju resor mer, till att slå eder för edra synders skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Och skall sända vilddjur ibland eder; de skola uppäta edor barn, och förderfva edar boskap, och förminska eder; och edra vägar skola varda öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Om I ändå icke dermed låten rätta eder, och vandren mig emot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Så skall jag ock vandra emot eder, och skall ännu slå eder sju resor mer för edra synders skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Och skall låta komma öfver eder ett hämndesvärd, det mitt förbund hämna skall. Och om I församlen eder uti edra städer, skall jag dock sända pestilentie ibland eder, och skall gifva eder uti edra fiendars händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Så skall jag ock förderfva edars bröds tillråd, så att tio qvinnor skola baka sitt bröd i enom ugn, och edart bröd skall man utväga med vigt; och när I äten, skolen I icke varda mätte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Om I dermed än icke hören mig, utan vandren mig emot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Så skall jag ock i grymhet vandra emot eder, och skall sjufaldt mer näpsa eder för edra synders skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Så att I skolen äta edra söners och döttrars kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Och jag skall borthäfva edra höjder, och edor beläte utrota, och skall kasta edra kroppar uppå edra afgudar, och min själ skall vämja vid eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Och skall göra edra städer öde, och edra kyrkor förlägga, och skall icke vilja lukta edra söta lukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Alltså skall jag göra landet öde, att edra fiender, som bo deruti, skola grufva sig derföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Men eder skall jag förskingra ibland Hedningarna, och draga ut svärdet efter eder, att edart land skall blifva öde, och edra städer omkullslagne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Så skall då landena behaga sin helg, så länge det öde ligger, och I ären i fiendalande. Ja, då skall landet hålla helg, och dess helg thy behaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Så länge det öde ligger, skall det hålla helg; derföre, att det icke kunde heligt hålla, då I skullen låtat heligt hålla, då I deruti bodden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Och de som återlefvas af eder, dem skall jag göra ett bäfvande hjerta uti deras fiendars lande, så att ett ruskande löf skall jaga dem; och skola fly derföre, lika som ett svärd jagade dem, och falla der som ingen jagar dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Och den ene skall falla på den andra, lika såsom för svärd, och dock ingen jagar dem. Och I skolen icke töra duka eder upp för edra fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Och I skolen förfaras ibland Hedningarna, och edra fiendars land skall fräta eder upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'De som återlefvas, skola försmäktas i deras missgerningar uti fiendalande; och uti deras fäders missgerningar skola de försmäktas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Så skola de då bekänna sina missgerning, och sina fäders missgerning, i hvilkom de sig förtagit, och emot mig vandrat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Derföre vill jag ock vandra emot dem, och skall drifva dem bort i deras fiendaland. Då varder ju deras oomskorna hjerta sig ödmjukandes. Och då skall dem behaga deras missgerningars straff.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Och jag skall ihågkomma mitt förbund med Jacob, och mitt förbund med Isaac, och mitt förbund med Abraham; och skall tänka uppå landet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Som af dem öfvergifvet är, och hafver haft ett behag till sina helg, medan det öde ligger ifrå dem, och dem behagar deras missgerningars straff; derföre, att de hafva föraktat mina rätter, och deras själ hafver haft en vämjelse till mina stadgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Och om de än i fiendaland äro, hafver jag likväl icke förkastat dem, och icke så vämjat vid dem, att det skulle vara ute med dem, och mitt förbund med dem skulle intet mer gälla; ty jag är Herren deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Och jag skall för dem ihågkomma mitt första förbund, då jag förde dem utur Egypti land för Hedningarnas ögon, att jag skulle vara deras Gud: Jag Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Dessa äro de stadgar, och rätter, och lag, som Herren emellan sig och Israels barn satt hafver, på Sinai berg, genom Mose hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Tala med Israels barn, och säg till dem: Om någor gör Herranom ett besynnerligit löfte, så att han skattar sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Så skall detta vara skattningen: en mansperson tjuguåra gammal, intill sextio år, skall du skatta på femtio silfversiklar, efter helgedomens sikel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'En qvinnosperson på tretio siklar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Men ifrå fem år in till tjugu år, om det är en mansperson, skall du skatta honom på tjugu siklar; en qvinnosperson på tio siklar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Är det en månad gammalt, intill fem år, om det är en mansperson, skall du skatta det på fem silfversiklar; en qvinno på tre silfversiklar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Men är det sextioåra gammalt, och derutöfver, och är en mansperson, skall du skatta honom på femton silfversiklar; en qvinno på tio siklar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Om han är för fattig till sådana skattning, så skall han gå för Presten, och Presten skall skatta honom; och han skall skatta honom efter som hans hand, som löftet gjort hafver, förvärfva kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Om det är af boskap, det man Herranom offra må, allt det man Herranom gifver, det är heligt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Man skall icke vexla det, eller förvandlat, ett godt för ett ondt, eller ett ondt för ett godt. Om någor vexlar det, ett djur för det andra, så skola de båda vara helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Är det djuret orent, det man icke bör offra Herranom, så skall man hafva det fram för Presten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Och Presten skall skatta det, om det är godt eller ondt. Och det skall blifva vid Prestens skattning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Vill någor lösa det, han skall gifva femtedelen utöfver skattningena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Om någor helgar sitt hus, så att det skall vara Herranom heligt, så skall Presten skatta det, om det är godt eller ondt. Och efter som Presten skattar det, så skall det blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Men om han, som det helgat hafver, vill det lösa, skall han gifva den femte delen i silfver mer än som det skattadt är, och så skall det varda hans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Om någor helgar Herranom ett stycke åker af sitt arfvegods, så skall den skattad varda efter som han bär. Bär han en homer korn, så skall han gälla femtio silfversiklar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Men helgar han sin åker straxt ifrå klangåret, så skall han gälla efter hans värde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Hafver han helgat honom efter klangåret, så skall Presten räkna honom efter de åren, som tillbakastå intill klangåret, och derefter skatta honom desto ringare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Vill han, som honom helgat hafver, lösa åkren, så skall han gifva femtedelen i silfver, mer än han skattad är, och så skall han varda hans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Vill han icke lösan, utan säljer honom enom androm, så skall han icke mer lösa honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Utan den samme åkren, när han i klangåret lös utgår, skall vara helig Herranom, såsom en förspilld åker, och skall vara Prestens arfvegods.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Om någor helgar Herranom en åker, den han köpt hafver, och icke hans arfvegods är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Så skall Presten räkna honom hvad han gälla kan intill klangåret, och han skall på samma dagen gifva den skattningen ut, att hon skall vara Herranom helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Men på klangåret skall han komma till honom igen, som honom sålt hade, att han blifver hans arfvegods i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'All skattning skall ske efter helgedomens sikel; men en sikel gör tjugu gera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Det förstfödda ibland boskapen, det Herranom eljest tillhörer, skall ingen helga, vare sig oxe eller får; ty det är Herrans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Är något orent på boskapen, så skall man lösa det efter sitt värde, och derutöfver gifva den femte delen. Vill han icke lösa det, så må det säljas efter sitt värde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Man skall intet spillgifvet sälja eller lösa, det någor Herranom tillspillogifver, af allt det hans ägodelar är, vare sig menniska, boskap, eller arfåker; ty allt spillgifvet är det aldrahelgasta Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Man skall icke lösa någon spillgifven mennisko; utan hon skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'All tionde i landet, både af landsens säd, och af frukten af trän, höra Herranom till, och skola vara helig Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Vill någor lösa sin tiond, han skall gifva femtedelen utöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Och all tiond af fä och får, och allt det under ris går, det är en helig tiond Herranom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Man skall icke fråga, om det är godt eller ondt; man skall icke heller vexlat. Om någor vexlar det, så skall både vara heligt, och icke löst varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Desse äro de bud, som Herren böd Mose till Israels barn på Sinai berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Och Herren talade med Mose, i Sinai öken, uti vittnesbördsens tabernakel, på första dagen, i den andra månadenom, i de andra årena, sedan de voro gångne utur Egypti land, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Tager en summo af hela Israels barnas menighet, efter deras slägter, och deras fäders hus och namn, allt det som mankön är, ifrå hufvud till hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Ifrå tjugu år och derutöfver, allt det som doger till att draga i här i Israel. Och I skolen tälja dem efter deras härar, du och Aaron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Och skolen taga till eder af hvarjo slägtene en höfvitsman öfver hans faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Desse äro namnen af de höfvitsmän, som med eder stå skola. Af Ruben: Elizur, Sedeurs son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Af Simeon: Selumiel, ZuriSadai son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Af Juda: Nahesson, Amminadabs son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Af Isaschar: Nethaneel, Zuars son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Af Sebulon: Eliab, Helons son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Af Josephs barn: Af Ephraim, Elisama, Ammihuds son: Af Manasse, Gamliel, Pedahzurs son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Af BenJamin: Abidan, Gideoni son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Af Dan: Ahieser, Ammi Sadai son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Af Asser: Pagiel, Ochrans son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Af Gad: Eliasaph, Deguels son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Af Naphthali: Ahira, Enans son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Desse äro de namnkunnigaste i menighetene, höfvitsmän i deras fäders slägter, som voro hufvud och Förstar i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Och Mose och Aaron togo dem till sig, såsom de vid namn uppräknade voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Och församlade desslikes hela menighetena på första dagen i den andra månadenom, och räknade dem efter deras börd, efter deras slägter och fäders hus och namn, ifrå tjugu år och derutöfver, ifrå hufvud till hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Såsom Herren hade budit Mose; och talde dem uti Sinai öken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Rubens barn, som var den förste Israels son, efter deras börd, slägter, deras fäders hus och namn, ifrå hufvud till hufvud, allt det mankön var, ifrå tjugu år och derutöfver, och de som dogde till att draga i här,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'De vordo räknade intill Rubens slägte, sex och fyratio tusend, och femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Simeons barn, efter deras börd, slägter, deras fäders hus och namn, ifrå hufvud till hufvud, allt det som mankön var, ifrå tjugu år och derutöfver, och i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Vordo talde intill Simeons slägte, nio och femtio tusend, och trehundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Gads barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det som i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Vordo talde intill Gads slägte, fem och fyratio tusend, sexhundrad och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Juda barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Vordo talde intill Juda slägte, fyra och sjutio tusend, och sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Isaschars barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Vordo talde intill Isaschars slägte, fyra och femtio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Sebulons barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Vordo talde intill Sebulons slägte, sju och femtio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Josephs barn, af Ephraim, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Vordo talde intill Ephraims slägte, fyratiotusend, och femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Manasse barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Vordo talde intill Manasse slägte, tu och tretio tusend, och tuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'BenJamins barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Vordo talde intill BenJamins slägte, fem och tretio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Dans barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Vordo talde intill Dans slägte, tu och sextio tusend, och sjuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Assers barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Vordo talde intill Assers slägte, ett och fyratio tusend, och femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Naphthali barn, efter deras börd, slägter, deras fäders hus och namn, ifrå tjugu år och derutöfver, allt det i här draga dogde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Vordo talde intill Naphthali slägte, tre och femtio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Desse äro de som Mose och Aaron, samt med de tolf Israels Förstar, talde, af hvilkom ju en var öfver hvart af deras fäders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Och summan af Israels barn, efter deras fäders hus, ifrå tjugu år och derutöfver, det i här draga dogde i Israel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Var sex resor hundradetusend, och tretusen, femhundrade och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Men de Leviter, efter deras fäders slägter, vordo intet räknade ibland med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Levi slägt skall du intet räkna, eller taga någon summo af dem, ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Men du skall skicka dem till vittnesbördsens tabernakel, och till all dess tyg, och allt det dertill hörer; och de skola bära tabernaklet, och all dess tyg, och skola det sköta, och lägra sig omkring tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Och när man resa skall, då skola de Leviter taga tabernaklet neder; och när hären skall lägra sig, skola de slå tabernaklet upp. Om någor främmande nalkas dertill, han skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Israels barn skola lägra sig hvar i sitt lägre, och vid sins härs baner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Men Leviterna skola lägra sig omkring vittnesbördsens tabernakel, på det icke skall komma en vrede öfver menighetena af Israels barn. Derföre skola de Leviter vakt hålla vid vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Och Israels barn gjorde allt det Herren Mose budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Israels barn skola lägra sig allt omkring för vittnesbördsens tabernakel, hvar under sitt baner och tecken, efter deras fäders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Österut skall sig lägra Juda med sitt baner och här; deras höfvitsman Nahesson, Amminadabs son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Och hans här, de fyra och sjutio tusend, och sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Bredovid honom skall sig lägra Isaschars slägte; deras höfvitsman Nethaneel, Zuars son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Och hans här, de fyra och femtio tusend, och fyrahundrad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Dertill Sebulons slägte; deras höfvitsman Eliab, Helons son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Med sin här, de sju och femtio tusend, och fyrahundrad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Så att alle de, som höra till Juda lägre, skola vara i allo hundrade sex och åttatio tusend, och fyrahundrad, de som deras här tillhöra; och de skola draga främst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Söderut skall ligga Rubens lägre och baner med deras här; deras höfvitsman Elizur, Sedeurs son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Och hans här, de sex och fyratio tusend, femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Bredovid honom skall sig lägra Simeons slägte; deras höfvitsman Selumiel, ZuriSadai son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Och hans här, de nio och femtio tusend, trehundrad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Dertill Gads slägte; deras höfvitsman Eliasaph, Reguels son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Och hans här, de fem och fyratio tusend, sexhundrad och femtio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Så att alle de, som höra till Rubens lägre, skola vara i allo hundrade ett och femtio tusend, fyrahundrad och femtio, de som deras här tillhöra; och skola vara de andre i utdragningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Sedan skall vittnesbördsens tabernakel draga fram med Leviternas lägre midt ibland lägren; och såsom de lägra sig, så skola de ock draga, hvar vid sitt rum under sitt baner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Vesterut skall ligga Ephraims lägre och baner, med deras här; deras höfvitsman skall vara Elisama, Ammihuds son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Och hans här, de fyratiotusend och femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Bredovid honom skall sig lägra Manasse slägte; deras höfvitsman Gamliel, Pedahzurs son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Hans här, de tu och tretio tusend, och tuhundrad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Dertill BenJamins slägte; deras höfvitsman, Abidan, Gideoni son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Hans här de fem och tretio tusend, och fyrahundrad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Så att alle de som Ephraims lägre tillhöra, skola vara hundrade och åtta tusend, och etthundrad, de hans här tillhöra; och skola vara de tredje i utdragningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Norrut skall ligga Dans lägre och baner; deras höfvitsman Ahieser, AmmiSadai son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Hans här, de tu och sextio tusend, och sjuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Bredovid honom skall lägra sig Assers slägte; deras höfvitsman Pagiel, Ochrans son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Hans här, de ett och fyratio tusend, och femhundrad:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Dertill Naphthali slägte; deras höfvitsman Ahira, Enans son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Hans här, de tre och femtio tusend, och fyrahundrad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Så att alle de, som höra till Dans lägre, skola vara hundrade sju och femtio tusend, och sexhundrad; och skola vara de ytterste i utdragningene med deras baner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Detta är summan af Israels barn, efter deras fäders hus och lägre med deras härar: sexhundradtusend, och tretusend, femhundrad och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Men de Leviter vordo intet talde i summan med Israels barnom; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Och Israels barn gjorde allt det Herren hade budit Mose; och lägrade sig under deras baner, och drogo ut hvar i sine slägt efter deras fäders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Detta är Aarons och Mose slägt, i den tiden, då Herren talade med Mose på Sinai berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Och detta är Aarons söners namn: Den förstfödde Nadab, dernäst Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Det äro namn till Aarons söner, som till Prester smorde voro, och deras händer fyllde till Presterskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Men Nadab och Abihu blefvo döde för Herranom, då de offrade främmande eld för Herranom, uti Sinai öken, och hade inga söner. Men Eleazar och Ithamar skötte Prestaämbetet under deras fader Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Haf fram Levi slägte, och ställ dem inför Presten Aaron, att de skola tjena honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Och hålla hans och hela menighetenes vakt inför vittnesbördsens tabernakel, och tjena i tabernaklets tjenste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Och vakta all tyg, som vittnesbördsens tabernakel tillhörer, och Israels barnas vakt, till att tjena i tabernaklets tjenste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Och skall gifva Aaron och hans sönom Leviterna till gåfvo af Israels barnom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Men Aaron och hans söner skall du sätta, att de vakta på deras Presterskap. Om någor främmande bjuder sig dertill, han skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Si, jag hafver tagit de Leviter ibland Israels barn, för allt förstfödt, som moderlif öppnar ibland Israels barn, så att Leviterna skola vara mine.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Förty de förstfödingar äro mine, ifrå den tid jag slog all förstföding i Egypti land; då helgade jag mig all förstföding i Israel, ifrå mennisko allt intill boskapen, att de skola höra mig till: Jag Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Och Herren talade med Mose uti Sinai öken, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Räkna Levi söner efter deras fäders hus och slägter, allt det mankön är, månade gammalt, och derutöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Och så talde Mose dem efter Herrans ord, såsom han budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Och voro desse Levi barn vid namn: Gerson, Kehat, Merari.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Men Gersons barnas namn i deras slägter voro: Libni och Simei.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Kehats barn i deras slägter voro: Amram, Jizear, Hebron och Usiel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Merari barn i deras slägter voro: Maheli och Musi. Det äro Levi slägter, efter deras fäders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Desse äro Gersons slägter: De Libniter och Simeiter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Summan af talet vardt funnen sjutusend och femhundrad, allt det som mankön var, och månade gammalt, och derutöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Och de samma Gersoniters slägter skola lägra sig bakföre tabernaklet, vesterut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Deras öfverste skall vara Eliasaph, Laels son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Och de skola vakta på vittnesbördsens tabernakel, på boningena och täckelset, och dess öfvertäckelse, och på klädet i dörrene af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'På bonaden åt gårdenom, och på klädet i gårdsens ingång, hvilken går omkring boningena och altaret, och på dess tåg, och allt det som till dess tjenste hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Desse äro Kehats slägter: De Amramiter, de Jizeariter, de Hebroniter och Usieliter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Allt det som mankön var, och månade gammalt, och derutöfver, vid tal åttatusend och sexhundrad, de som akta skola på helgedomens vakt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Och skola lägra sig vid sidona af tabernaklet, söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Deras öfverste skall vara Elizaphan, Usiels son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Och de skola vakta arken, bordet, ljusastakan, altaren, och all helgedomens tyg, der de tjena med; och på förlåten, och hvad till dess tjenste tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Men den öfverste öfver alla Leviternas öfverstar skall vara Eleazar, Prestens Aarons son, öfver dem som skickade äro till att taga vara på helgedomens vakt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Desse äro Merari slägte: De Maheliter och Musiter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Hvilke till talet voro sextusend och tuhundrad, allt det mankön var, månade gammalt, och derutöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Deras öfverste skall vara Zuriel, Abihails son; och skola lägra sig vid sidona af tabernaklet, norrut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Och deras ämbete skall vara, att vakta uppå bräden, skottstängerna, och stolparna, och fötterna åt tabernaklet, och all tyg, som till den tjensten tillhöra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Så ock på stolparna kringom gården, med fötterna, och pålarna, och tågen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Men framför boningena och vittnesbördsens tabernakel österut skola sig lägra Mose och Aaron, och hans söner, att de skola vakta på helgedomen, och på Israels barn. Om någor främmande bjuder sig dertill, han skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Alle Leviterna uti en summo, som Mose och Aaron talde efter deras slägter, efter Herrans ord, alltsammans mankön, månade gammalt, och derutöfver, voro tu och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Och Herren talade till Mose: Räkna all förstföding, det mankön är ibland Israels barn, månade gammalt, och derutöfver och tag talet på deras namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Och skall uttaga Leviterna mig Herranom för all Israels barnas förstföding; och Leviternas boskap, för all förstföding af Israels barnas boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Och Mose talde, såsom Herren honom budit hade, all förstföding ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Och vardt funnet namnens tal, af all förstföding, det mankön var, månade gammalt, och derutöfver, i deras summo, tu och tjugu tusend, tuhundrad, och tre och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Tag de Leviter för all förstföding ibland Israels barn, och Leviternas boskap för deras boskap, att Leviterna skola vara mine, Herrans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Men de lösepenningar för de tuhundrade tre och sjutio, som öfverlöpa i Israels barnas förstföding, utöfver Leviternas tal,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Skall du taga ju fem siklar ifrå hufvud till hufvud, efter helgedomens sikel; tjugu gera gäller en sikel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Och skall de samma penningar, som öfverrisa utöfver deras tal, gifva Aaron och hans sönom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Då tog Mose de lösepenningarna, som öfverriste utöfver Leviternas tal,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Af Israels barnas förstfödingar, tusende trehundrad, och fem och sextio siklar, efter helgedomens sikel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Och fick dem Aaron och hans söner, efter Herrans ord, såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Tag summon af Kehats barn utaf Levi söner, efter deras slägter och fäders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Ifrå tretio år och derutöfver, allt intill femtionde året, alla de som doga till ämbetet, att de göra de verk i vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Och detta skall vara Kehats söners ämbete uti vittnesbördsens tabernakel, det aldrahelgast är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'När hären drager af stad, så skola Aaron och hans söner gå in, och taga ned förlåten, och svepa vittnesbördsens ark deruti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Och lägga täckelset deröfver af tackskinn, och breda deruppå ett kläde alltsammans gult, och lägga hans stänger dervid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Och breda desslikes öfver skådobordet ett gult kläde, och sätta deruppå fat, skedar, skålar och kannor, der man med ut och in skänker; och det dagliga brödet skall ligga der när;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Och skola breda deröfver ett rosenrödt kläde, och betäcka det med ett täckelse af tackskinn, och lägga dess stänger der när;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Och skola taga ett gult kläde, och svepa ljusens ljusastaka deruti, och hans lampor med hans ljusanäpor och släcketyg, och all oljokar, som ämbetet tillhöra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Och skola lägga om allt detta ett täckelse af tackskinn, och skola lägga dem på stänger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Sammalunda skola de ock breda öfver gyldene altaret ett gult kläde, och betäcka det med täckelset af tackskinn, och lägga dess stänger dervid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'All tyg, som de skola med tjena i helgedomen, skola de taga och lägga ett gult kläde deröfver, och täcka det med ett täckelse af tackskinn, och lägga uppå stänger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'De skola ock sopa askona utaf altaret, och breda ett skarlakanskläde deröfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Och all dess tyg lägga dertill, der de med skaffa hafva deruppå, kolpannor, gafflar, skoflar, bäcken med all redskap till altaret; och skola breda deröfver ett täckelse af tackskinn, och lägga dess stänger dervid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'När nu Aaron och hans söner sådant gjort hafva, och betäckt helgedomen, och all dess redskap, när hären drager af stad, då skola Kehats barn gå in till att bära det, och skola icke komma vid helgedomen, att de icke dö. Detta är Kehats barnas tunge vid vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Och Eleazar, Prestens Aarons son, skall hafva detta ämbetet, att han skickar oljona till lysning, och speceri till rökverk, och det dagliga spisoffret, och smörjooljan, så att han beskickar hela tabernaklet och allt det deruti är, uti helgedomenom, och hans redskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Och Herren talade med Mose och med Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'I skolen icke låta de Kehatiters slägtes ätt förderfva sig ibland de Leviter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Utan det skolen I göra med dem, att de måga lefva och icke dö, om de komma vid det aldrahelgasta: Aaron och hans söner skola gå in, och skicka hvar och en till sitt ämbete och tunga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Men icke skola de gå derin, och skåda helgedomen ohöljdan, att de icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Tag desslikes summon af Gersons barn, efter deras fäders hus och slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Ifrå tretio år och derutöfver, intill femtionde året, och skicka dem alla, som till ämbete dogse äro, att de skola hafva ämbete i vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Och detta skall vara de Gersoniters slägtes ämbete, det de skola sköta och bära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'De skola bära boningenes tapeter, och vittnesbördsens tabernakel, och dess täckelse, och det täckelset af tackskinn, som ofvan öfver är, och klädet i dörrene af vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Och den bonaden i gårdenom, och klädet i ingången åt gårdenom, som går omkring tabernaklet och altaret, och deras tåg, och all redskap till deras ämbete, och allt det som deras ämbete tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Efter Aarons och hans söners ord skall allt Gersons barnas ämbete gå, allt det de bära och sköta skola; och I skolen se till, att de taga vara på allan deras tunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Detta skall vara de Gersoniters barnas slägtes ämbete uti vittnesbördsens tabernakel. Och deras vakt skall vara under Ithamars, Prestens Aarons sons, hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Merari barn, efter deras slägte och fäders hus, skall du ock skicka,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Ifrå tretio år och derutöfver, intill det femtionde året, alla de som till ämbete doga, att de skola hafva ämbete uti vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'På denna tungan skola de vakta, efter allt deras ämbete uti vittnesbördsens tabernakel, att de bära bräden till tabernaklet, och skottstängerna, och stolparna, och fötterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Och dertillmed stolparna till gården allt omkring, och fötterna och pålarna, och tågen med all deras redskap, efter allt deras ämbete. Hvar och en skolen I tillskicka sin del af tunganom, till att taga vara på redskapen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Detta vare Merari barnas slägtes ämbete, af allt det de sköta skola uti vittnesbördsens tabernakel, under Ithamars, Prestens Aarons sons, hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Och Mose och Aaron, samt med höfvitsmännerna öfver menighetena, talde de Kehatiters barn, efter deras slägte och fäders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Ifrå tretio år och derutöfver, intill femtionde året, alla de som till ämbete dogde, till att hafva ämbete uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Och summan var tutusend, sjuhundrad och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Det är summan af de Kehatiters slägte, hvilka alle till skaffa hade uti vittnesbördsens tabernakel; de Mose och Aaron talde efter Herrans ord genom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Gersons barn vordo ock talde i deras slägter och fäders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Ifrå tretio år och derutöfver, allt intill det femtionde, alle de som till ämbete dogde, till att hafva ämbete uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Och summan var tutusend, sexhundrad och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Det är summan af Gersons barnas slägte, de der alle hade till skaffa uti vittnesbördsens tabernakel, hvilka Mose och Aaron talde efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Merari barn vordo ock talde, efter deras slägter och fäders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Ifrå tretio år och derutöfver, allt intill det femtionde, alle de som till ämbete dogde, till att hafva ämbete uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Och summan var tretusend och tuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Detta är summan af Merari barnas slägte, de Mose och Aaron talde efter Herrans ord genom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Summan af alla Leviterna, som Mose och Aaron, samt med Israels höfvitsmän, talde efter deras slägter och fäders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Ifrå tretio år och derutöfver, intill det femtionde, alle de som ingingo till att skaffa, hvar i sitt ämbete, till att draga tungan uti vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Var åttatusend, femhundrad och åttatio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'De der talde vordo efter Herrans ord genom Mose, hvar och en till sitt ämbete och tunga, såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Bjud Israels barnom, att de låta alla spitelska komma utu lägret, och alla de som etterflöd hafva, och de som på något dödt orene vordne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Både man och qvinno skola de drifva ut för lägret, att de icke skola göra deras lägre orent, der jag uti bor ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Och Israels barn gjorde så, och drefvo dem ut för lägret, såsom Herren hade sagt till Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Tala till Israels barn, och säg till dem: Om en man eller qvinna gör en synd på en mennisko, och förbryter sig dermed emot Herranom, så hafver den själen en skuld uppå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Och de skola bekänna deras synd, som de gjort hafva, och skola försona deras skuld med lika värd, och derutöfver lägga femtedelen till, och gifva honom, som de emot syndat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Om ingen är, hvilkom man betala skulle, så skall man gifvat Herranom inför Prestenom, undantagen försoningenes vädur, der han med försonad varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Desslikes skall allt häfoffer af allo thy, som Israels barn helga och offra Prestenom, vara hans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Och hvilken något helgar, det skall ock vara hans; och hvad någor gifver Prestenom, det skall ock vara hans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Tala till Israels barn, och säg till dem: Om en mans hustru förlöper honom, och förbryter sig emot honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Och någor köttsliga belägrar henne, och varder dock mannenom fördoldt för hans ögon, och varder förskyldt att hon oren vorden är, och han kan icke öfvertygat henne; ty hon är icke beslagen dermed;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Och misstankoanden upptänder honom, att han sina hustru misstänker, ehvad hon är oren, eller ej oren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Så skall han hafva henne fram för Presten, och bära fram ett offer öfver henne, tiondeparten af ett epha bjuggmjöl, och skall ingen oljo gjuta deruppå, ej heller lägga der rökelse på; ty det är ett misstankaoffer, och ett röjelseoffer, som missgerning röjer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Då skall Presten hafva henne fram, och ställa henne för Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Och taga af det helga vattnet uti ett lerkar, och lägga stoft af tabernaklets golf i vattnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Och skall ställa qvinnona inför Herran, och blotta hennes hufvud, och lägga röjelseoffret, det ett misstankaoffer är, på hennes hand; och Presten skall hafva i sine hand bittert förbannadt vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Han skall besvärja qvinnan, och säga till henne: Hafver ingen man belägrat dig, och du icke hafver förlupit din man, så att du hafver orenat dig, så skall detta bittra förbannade vattnet intet skada dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Men hafver du förlupit din man, så att du äst oren, och någor hafver belägrat dig förutan din man;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Så skall Presten besvärja qvinnona med sådana förbannelse, och skall säga till henne: Herren sätte dig i förbannelse och till en ed ibland ditt folk; så att Herren låter förfalla dina länder, och din buk svälla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Så gånge nu det förbannade vattnet i ditt lif, så att din buk sväller, och dina länder förfalla. Och qvinnan skall säga: Amen, amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Och så skall Presten skrifva denna förbannelsen på en sedel, och två det af med vattnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Och skall gifva qvinnone dricka af det bittra förbannade vattnet; och när det bittra förbannade vattnet är gånget uti henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Då skall Presten taga det misstankaoffret af hennes hand, och veftoffra det för Herranom till ett spisoffer, och offrat uppå altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Han skall taga en hand full af spisoffret till hennes åminnelse, och bränna det upp på altaret, och derefter gifva qvinnone dricka vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Och när hon hafver druckit vattnet, om hon är oren, och hafver sig emot sin man förbrutit; så skall det förbannade vattnet gå in i henne, och vara henne bittert, så att buken sväller på henne, och länderna förfalla; och den qvinna skall vara till en förbannelse ibland hennes folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Är samma qvinna intet orenad, utan är ren; så skall det intet skada henne, så att hon ju må varda hafvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Detta är misstankas lag, när en qvinna förlöper sin man och varder oren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Eller när en misstankoande upptänder en man, att han misstänker sina hustru, att han skall ställa henne inför Herran; och Presten göre med henne allt efter denna lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Och mannen skall vara utan skuld för den missgerning, men qvinnan skall bära sin skuld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Tala till Israels barn, och säg till dem: Om en man eller qvinna gör Herranom ett besynnerligt löfte till återhåll;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Han skall hålla sig ifrå vin och starka drycker; vinättiko och starka dryckers ättiko skall han ock icke dricka, ej heller det af vinbär gjordt varder; han skall hvarken färsk eller torr vinbär äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Så länge som hans löfte varar, skall han icke äta det af vinträ gjordt är, hvarken vinbärskärnarna eller skalena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Så länge hans löftes tid varar, skall icke rakoknif komma på hans hufvud, tilldess tiden är ute, den han Herranom lofvat hafver; ty han är helig, och skall låta fri växa håret på sitt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'I hela tidenom, den han Herranom lofvat hafver, skall han till ingen dödan gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Han skall ej heller orena sig på sins faders död, sine moders, sins broders, eller sine systers; förty hans Guds löfte är öfver hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Och i hela hans löftes tid skall han vara Herranom helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Och om någor oförvarandes bråddör när honom, då varder hans löftes hufvud orent. Derföre skall han raka sitt hufvud på hans renselsedag, det är, på sjunde dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Och på åttonde dagen skall han bära fram två turturdufvor, eller två unga dufvor, till Presten inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Och Presten skall göra den ena till ett syndoffer, den andra till ett bränneoffer, och försona honom, derföre att han syndade öfver en dödan; och alltså på samma dagenom helga hans hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Att han skall uthålla Herranom tiden till sitt löfte; och skall bära fram ett årsgammalt lamb till ett skuldoffer. Dock skola de förra dagarna vara förgäfves, derföre att hans löfte vardt orenadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Detta är hans lag, som sig förlofvat hafver: När hans löftes tid ute är, skall man hafva honom fram för dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Och han skall bära fram sitt offer Herranom, ett årsgammalt lamb utan vank till bränneoffer, och ett årsgammalt får utan vank till syndoffer; och en vädur utan vank till tackoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Och en korg med osyrade kakor af semlomjöl, blandadt med oljo, och osyrade tunnkakor, smorda med oljo, och deras spisoffer och drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Och Presten skall bära det in för Herran, och skall göra hans syndoffer, och hans bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Och väduren skall han göra till ett tackoffer Herranom till den osyrade brödkorgen; och skall desslikes göra hans spisoffer, och hans drickoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Och skall raka dens förlofvades löftes hufvud inför dörrene af vittnesbördsens tabernakel; och skall taga hans löftes hufvudhår, och kasta det på elden, som under tackoffrena är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Och skall taga bogen af väduren sudnan, och en osyrad kako utu korgenom, och en osyrad tunnkako; och skall läggat dem förlofvade på hans händer, sedan han hans löfte afrakat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Och skall veftoffra det för Herranom. Det är heligt Prestenom, samt med veftoffersbröstena, och häfoffersbogenom. Sedan må den förlofvade dricka vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Detta är dens förlofvades lag, som sitt offer lofvar Herranom för sitt löfte, förutan det han eljest förmår. Såsom han lofvat hafver, så skall han ock göra, efter hans löftes lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Tala till Aaron och hans söner, och säg: Så skolen I säga till Israels barn, när I välsignen dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Herren välsigne dig, och bevare dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Herren låte sitt ansigte lysa öfver dig, och vare dig nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Herren upplyfte sitt ansigte öfver dig, och gifve dig frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Ty I skolen sätta mitt Namn uppå Israels barn, att jag skall välsigna dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Och då Mose hade upprest tabernaklet, smort det, och helgat det med all dess tyg; dertill ock smort och helgat altaret med all dess tyg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Så offrade höfvitsmännerna i Israel, de som ypperst voro i deras fäders hus; förty de voro höfvitsmän i slägterna, och stodo öfverst ibland dem som talde voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Och de båro sitt offer fram för Herran, sex öfvertäckta vagnar, och tolf oxar, ju en vagn för två höfvitsmän, och en oxa för hvardera; och hade dem fram för tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Och Herren sade till Mose:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Tag det af dem, att det må tjena i vittnesbördsens tabernakels tjenste, och få det Leviterna, hvarjom efter sitt ämbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Då tog Mose vagnarna och oxarna, och fick dem Leviterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Två vagnar och fyra oxar fick han Gersons barnom, efter deras ämbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Och fyra vagnar och åtta oxar fick han Merari barnom, efter deras ämbete, under Ithamars, Prestens Aarons sons, hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Men Kehats barnom fick han intet; derföre att de ett heligt ämbete på sig hade och måste bära på sina axlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Och höfvitsmännerna offrade till altarets vigning, på den dagen, då det vigdt vardt, och offrade sina gåfvor inför altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Och Herren sade till Mose: Låt hvar höfvitsmannen bära sitt offer fram på sin dag till altarets vigning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'På första dagen offrade Nahesson sina gåfvo, Amminadabs son, af Juda slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Och hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Dertill en gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Och två oxar till tackoffer, fem vädrar, fem bockar, och fem årsgamla lamb. Detta är Nahessons, Amminadabs sons, gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'På den andra dagen offrade Nethaneel, Zuars son, höfvitsmannen för Isaschar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Dertill en gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Nethaneels, Zuars sons, gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'På tredje dagen, höfvitsmannen för Sebulons barn, Eliab, Helons son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
