INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Elizurs, Sedeurs sons, gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'På femte dagen, höfvitsmannen för Simeons barn, Selumiel, ZuriSadai son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
