INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'På sjette dagen, höfvitsmannen för Gads barn, Eliasaph, Deguels son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
