INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'På sjunde dagen, höfvitsmannen för Ephraims barn, Elisama, Ammihuds son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl blandadt med oljo till spisoffer;');
