INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'På nionde dagen, höfvitsmannen för BenJamins barn, Abidan, Gideoni son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Abidans, Gideoni sons, gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'På tionde dagen, höfvitsmannen för Dans barn, Ahieser, AmmiSadai son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Ahiesers, AmmiSadai sons, gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'På ellofte dagen, höfvitsmannen för Assers barn, Pagiel, Ochrans son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Pagiels, Ochrans sons, gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'På tolfte dagen, höfvitsmannen för Naphthali barn, Ahira, Enans son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Hans gåfva var: Ett silffat, hundrade och tretio siklar värdt; en silfskål, sjutio siklar värd, efter helgedomens sikel, både full med semlomjöl, blandadt med oljo till spisoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'En gyldene sked, tio siklar guld värd, full med rökverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'En stut af boskapen, en vädur, ett årsgammalt lamb till bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'En getabock till syndoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Och till tackoffer två oxar, fem vädrar, fem bockar och fem årsgamla lamb. Detta är Ahira, Enans sons, gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Detta är nu altarets vigning, på den tiden, då det vigdt vardt, till hvilket de Israels höfvitsmän offrade dessa tolf silffat, tolf silfskålar, tolf gyldene skedar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Så att ju ett fat höll hundrade och tretio siklar silfver, och ju en skål sjutio siklar; så att summan af allt silfret i faten riste till tutusendfyrahundrade siklar, efter helgedomens sikel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Och af de tolf gyldene skedar, fulla med rökverk, höll ju en tio siklar, efter helgedomens sikel; så att summan af guldet i skedarne riste till hundrade och tjugu siklar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Summan af boskapen till bränneoffret var tolf stutar, tolf vädrar, tolf årsgamla lamb, med deras spisoffer; och tolf getabockar till syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Och summan af boskapen till tackoffret var fyra och tjugu oxar, sextio vädrar, sextio bockar, sextio årsgamla lamb. Detta är nu altarets vigning, då det vigdt vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Och när Mose gick in uti vittnesbördsens tabernakel, att med honom skulle taladt varda, så hörde han röstena med sig tala af nådastolenom, som var på vittnesbördsens ark, emellan de två Cherubim; dädan vardt med honom taladt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Tala med Aaron, och säg till honom: När du uppsätter lamporna, skall du så sätta dem, att de alla sju lysa framföre ljusastakan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Och Aaron gjorde så, och satte lamporna upp till att lysa framföre ljusastakan; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Men ljusastaken var af tätt guld, både hans lägg och hans blommor; efter den eftersyn, som Herren hade vist Mose, så gjorde han ljusastakan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Tag Leviterna utur Israels barn, och rena dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Och alltså skall du göra med dem, att du dem renar: Du skall stänka skärvatten på dem, och allt slätt afraka allt deras hår, och två deras kläder, så äro de rene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Sedan skola de taga en ung stut, och hans spisoffer, semlomjöl, blandadt med oljo; och en annan ung stut skall du taga till syndoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Och skall hafva Leviterna in för dörrena af vittnesbördsens tabernakel, och församla hela menighetena af Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Och hafva Leviterna fram för Herran; och Israels barn skola lägga sina händer på Leviterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Och Aaron skall veftoffra Leviterna för Herranom utaf Israels barn, att de tjena skola i Herrans ämbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Och Leviterna skola lägga sina händer på stutarnas hufvud; och den ene skall Herranom till ett syndoffer, och den andre till ett bränneoffer gjord varda, till att försona Leviterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Och du skall ställa Leviterna inför Aaron och hans söner, och veftoffra dem Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Och skall således afskilja dem ifrån Israels barn, att de skola vara mine.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Sedan skola de ingå till att tjena ut i vittnesbördsens tabernakel. Alltså skall du rena och veftoffra dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Ty de äro min gåfva utaf Israels barn; och jag hafver tagit dem till mig för allt det som öppnar moderlif, nämliga för förstfödingen i all Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Förty all förstföding i Israels barn är min, både af menniskor och af fänad; den tid jag slog all förstföding i Egypti land, helgade jag dem mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Och tog Leviterna mig till för all förstföding ibland Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Och gaf dem Aaron och hans söner för en gåfvo utur Israels barn, att de tjena skola i Israels barnas ämbete uti vittnesbördsens tabernakel, till att försona Israels barn; på det att ibland Israels barn icke skall komma en plåga, om de ville nalkas helgedomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Och Mose, med Aaron och hela menigheten af Israels barn, gjorde med Leviterna allt såsom Herren Mose budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Och Leviterna renade sig, och tvådde sin kläder; och Aaron veftoffrade dem för Herranom, och försonade dem, att de vordo rene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Sedan gingo de in att göra sitt ämbete uti vittnesbördsens tabernakel, för Aaron och hans söner. Såsom Herren hade budit Mose om Leviterna, så gjorde de med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Detta är det Leviterna bör: Ifrå fem och tjugu år, och derutöfver, doga de till ämbete och tjenst i vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Men ifrå femtionde året skola de vara löse ifrå tjenstenes ämbete, och skola icke mera tjena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Utan taga vara på deras bröders tjenst uti vittnesbördsens tabernakel; men ämbetet skola de icke sköta. Alltså skall du göra med Leviterna, att hvar och en tager vara på sina vakt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Och Herren talade med Mose uti Sinai öken, i andra årena, sedan de voro dragne utur Egypti land, i första månadenom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Låt Israels barn hålla Passah i sinom tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'På fjortonde dagen i denna månadenom om aftonen, i sinom tid, skola de hållat, efter alla dess stadgar och rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Och Mose talade med Israels barn, att de skulle hålla Passah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Och de höllo Passah på fjortonde dagen i första månadenom om aftonen, uti Sinai öken. Allt såsom Herren hade budit Mose, så gjorde Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Då voro der någre män orene öfver ena döda mennisko, så att de icke kunde hålla Passah på den dagen; de gingo på samma dagen till Mose och Aaron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Och de sade till honom: Vi äre orene öfver ena döda mennisko; hvi skulle vi så föraktelige vara, att vi icke måge bära Herranom våra gåfvo i sin tid, ibland Israels barn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mose sade till dem: Bider, jag vill höra hvad Herren bjuder eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Tala till Israels barn, och säg: Om någor orenas på någon dödan, eller fjerran är ifrån eder på markene, eller ibland edra slägt, han skall ändå hålla Herranom Passah;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Dock uti den andra månaden, på fjortonde dagenom om aftonen; och de skola ätat med osyradt bröd och salso;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Och skola intet låta deraf blifva qvart till morgonen, och intet ben sönderbryta deraf; och skola hållat efter allt Passah sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Men den som ren är, och icke är på markene, och försummar hålla Passah, hans själ skall utrotad varda utu hans folk; derföre, att han icke hafver burit Herranom sina gåfvo i sinom tid; han skall bära sin synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Och om en främling bor när eder, han skall ock hålla Herranom Passah, och skall hållat efter de stadgar och sätt, som Passah kräfver. Detta sättet skall vara eder allom ens, så dem utländska, som dem inländska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Och på den dagen, då tabernaklet uppsatt vardt, öfvertäckte det en molnsky på vittnesbördsens tabernakel. Om aftonen, och sedan intill morgonen, var öfver tabernaklet såsom en eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Så skedde det allestädes, att molnskyn öfvertäckte det om dagen, och om nattena såsom en eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Och efter som molnskyn hof sig upp ifrå tabernaklet, så foro Israels barn; och uppå hvad rum molnskyn blef, der lägrade sig Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Efter Herrans ord foro Israels barn, och efter Herrans ord lägrade de sig. Så länge molnskyn blef öfver tabernaklet, så länge lågo de stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Och när molnskyn i flera dagar dvaldes öfver tabernaklet, så togo Israels barn vara uppå Herrans vakt, och foro ingen vägs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Och när så skedde, att molnskyn var på tabernaklet till några dagars tal, så lägrade de sig efter Herrans ord, och foro efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'När molnskyn der var ifrån aftonen allt intill morgonen, och så hof sig upp, så foro de; eller när han sig om dagen eller nattena upphof, så foro de ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Men när han två dagar, eller en månad, eller eljest länge blef öfver tabernaklet, så lågo Israels barn, och foro intet. Och när han då gaf sig upp, så foro de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Ty efter Herrans mun lågo de, och efter Herrans mun foro de; så att de togo vara på Herrans vakt, efter Herrans ord genom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Gör dig två trummeter af tätt silfver, att du brukar dem till att kalla tillhopa menighetena, och när hären af stad skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'När man blås slätt med dem båda, skall församla sig till dig hela menigheten inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'När man slätt blås med enom, så skola höfvitsmännerna församla sig till dig; de öfverste öfver tusende i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Men när I trummeten, så skola de lägren draga af stad, som ligga österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Och när I trummeten annan gång, då skola de lägren draga af stad, som ligga söderut; förty, när de resa skola, så skolen I trummeta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Men när menigheten skall församlas, skolen I slätt blåsa, och icke trummeta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Och det blåsandet med trummeterna skola Prestens Aarons söner göra. Och det skall vara eder ett evigt sätt till edra efterkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'När I dragen till någon strid uti edro lande emot edra fiendar, som strida på eder, så skolen I trummeta med trummeterna, att uppå eder skall tänkt varda för Herranom edrom Gud, och I mågen löste varda ifrån edra fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Sammalunda ock, när I ären glade, på edra högtider och edra nymånader, skolen I blåsa med trummeterna öfver edor bränneoffer och tackoffer; att det skall vara eder till åminnelse för edrom Gud. Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'På tjugonde dagen i dem andra månadenom, i de andra årena, gaf molnskyn sig upp af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Och Israels barn drogo i deras skarar utu Sinai öken; och molnskyn blef uti den öknene Paran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Och de förste drogo af stad, efter Herrans ord genom Mose;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Nämliga det baneret af Juda barnas lägre drog först åstad med deras här; och öfver deras här var Nahesson, Amminadabs son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Och öfver den hären af Isaschars barnas slägte var Nathaneel, Zuars son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Och öfver den hären af Sebulons barnas slägte var Eliab, Helons son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Då lade man tillsamman tabernaklet; och Gersons och Merari barn drogo åstad, och båro tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Dernäst följde det baneret af Rubens lägre med deras här; och öfver deras här var Elizur, Sedeurs son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Och öfver den hären af Simeons barnas slägte var Selumiel, ZuriSadai son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Och Eliasaph, Deguels son, öfver Gads barnas slägtes här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Så drogo ock de Kehatiter åstad, och båro helgedomen; och hine uppsatte tabernaklet tilldess denne kommo efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Dernäst drog det baneret åstad af Ephraims barnas lägre med deras här; och öfver dem var Elisama, Ammihuds son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Och Gamliel, Pedahzurs son, öfver den hären af Manasse barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Och Abidan, Gideoni son, öfver den hären af BenJamins barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Dernäst följde det baneret af Dans barnas lägre med deras här; och så voro all lägren uppe; och Ahieser, AmmiSadai son, var öfver deras här;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Och Pagiel, Ochrans son, öfver den hären af Assers barnas slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Och Ahira, Enans son, öfver den hären af Naphthali barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Så foro Israels barn med deras härar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Och Mose sade till sin svåger Hobab, Reguels son, af Midian: Vi drage till de rum, om hvilka Herren sagt hafver: Jag skall gifva eder dem; så kom nu med oss, vi vilje göra det bästa med dig; ty Herren hafver Israel godt tillsagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Han svarade: Jag vill icke med eder, utan fara i mitt land till mina slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Han sade: Käre, öfvergif oss icke; förty du vetst hvar vi skole lägra oss i öknene, och skall vara vårt öga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Och om du far med oss, det goda, som Herren gör med oss, det vilje vi göra med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Så drogo de ifrå Herrans berg tre dagsresor; och Herrans förbunds ark drog för dem tre dagsresor, till att visa dem hvar de hvila skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Och Herrans molnsky var öfver dem om dagen, när de drogo utu lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Och när arken for, så sade Mose: Herre, statt upp, att dine fiender måga förströs; och de som dig hata, måga flyktige varda för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Och när han sattes ned, sade han: Kom igen, Herre, till de många Israels tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Och som folket gjordes otåligt, misshagade det för Herrans öron. Och då Herren hörde det, förgrymmade sig hans vrede, och Herrans eld fängde ibland dem, hvilken förtärde de yttersta lägren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Då ropade folket till Mose. Och Mose bad Herran; så försvann elden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Och det rummet kallade man Thabeera; derföre, att Herrans eld hade sig upptändt ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Ty det meniga folk ibland dem hade fått lusta, och såto och greto samt med Israels barn, och sade: Ho kan fly oss kött till att äta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Vi komme ihåg den fisk, som vi åto till gäfves uti Egypten, och de cucumerer, meloner, purlök, rödlök och hvitlök;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Men nu är vår själ borttorkad; vår ögon se intet annat än Man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Och var Man såsom coriandersfrö, och så till seendes som bedellion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Och folket lopp hit och dit, och samkade tillhopa, molo det på qvarn, och stötte det sönder i mortare, och kokade det i grytor och gjorde sig der kakor af; och det hade en smak såsom en oljokaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Och när daggen föll om nattena öfver lägret, så föll ock Man dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Då nu Mose hörde folket gråta i deras slägter, hvar och en i sins tjälls dörr, då förgrymmade sig Herrans vrede svårliga. Och Mose vardt ock ångse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Och Mose sade till Herran: Hvi bekymrar du din tjenare; och hvi finner jag icke nåd för din ögon, att du så lägger på mig all folkens tunga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Hafver nu jag allt detta folket aflat eller födt, att du må säga till mig: Bär dem på dinom armom, såsom en amma bär ett barn, in uti det landet, som du deras fäder svorit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Hvar skulle jag nu taga kött, det jag allo desso folkena gifva skulle? De gråta för mig, och säga: Gif oss kött till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Jag förmår icke allt detta folket uppehålla allena; ty det är mig för svårt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Och vill du så göra emot mig, så slå mig heldre ihjäl, om jag eljest hafver funnit nåd för din ögon, att jag icke så skall se min jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Och Herren sade till Mose: Församla mig sjutio män utaf de äldsta i Israel, de som du vetst att de äro de äldste och förmän i folkena, och haf dem fram för vittnesbördsens tabernakel, och ställ dem der när dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Så vill jag komma neder, och der tala med dig, och taga af dinom Anda, som öfver dig är, och få dem, att de måga draga tungan öfver folket med dig, att du icke drager honom allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Och till folket skall du säga: Helger eder till morgons, att I mågen få äta kött; förty eder gråt är kommen inför Herrans öron; ty I sägen: Ho gifver oss kött till att äta; förty vi mådde väl uti Egypten? Derföre skall Herren gifva eder kött, att I äten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Icke i en dag, icke i två, icke i fem, icke i tio, icke i tjugu dagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Utan en månad långt, tilldess att det skall gå eder utaf näsorna, och varda eder en vämjelse; derföre, att I hafven bortkastat Herran, den ibland eder är, och gråtit för honom, och sagt: Hvi äre vi gångne utur Egypten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Och Mose sade: Sexhundradtusend män fotfolk är, der jag ibland är, och du säger: Jag vill gifva eder kött, att I äten en månad långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Skall man slagta får och fä, att man må mätta dem, eller alla fiskar i hafvet församla dertill, att de måga blifva mättade?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Men Herren sade till Mose: Är då Herrans hand förkortad? Men du skall nu se, om min ord dig något värd äro, eller ej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Och Mose gick ut, och sade till folket Herrans ord, och församlade de sjutio män af de äldsta i folket, och ställde dem omkring tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Då kom Herren neder i molnskyn, och talade med honom, och tog af Andanom, som öfver honom var, och gaf de sjutio äldsta männerna. Och när Anden hvilades utöfver dem, propheterade de, och vände sedan intet igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Och så hade ännu två män blifvit qvare i lägrena, den ene het Eldad, den andre Medad. Och Anden hvilades öfver dem; ty de voro ock uppskrefne, ändock de icke utgångne voro till tabernaklet; och de propheterade i lägrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Då lopp en dräng af stad, och bådade det Mose, och sade: Eldad och Medad prophetera i lägrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Då svarade Josua, Nuns son, Mose tjenare, den han utvalt hade, och sade: Min herre Mose, förbjud dem det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Men Mose sade till honom: Hvi äst du så nitisk för mig? Gåfve Gud, att allt Herrans folk propheterade, och Herren läte sin Anda komma öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Och så gingo Mose och de äldste af Israel i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Då kom ett väder ut ifrå Herranom, och lät komma åkerhöns ifrå hafvet, och förströdde dem öfver lägret, den ena dagen såsom den andra, i två dagar långt kringom lägret, två alnar högt uppifrå jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Då stod folket upp på den samma hela dagen och den hela natten, och på allan den dagen derefter, och samkade åkerhöns, och den som minst samkade, han samkade tio homer; och de torkade dem kringom lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Som ännu köttet var under deras tänder, och förr än det åtgånget var, förgrymmade sig Herrans vrede öfver folket, och Herren slog dem med en ganska stor plågo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Deraf heter det samma rummet Lustgrifter; derföre, att man der begrof det lustna folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Ifrå Lustgrifterna drog folket ut till Hazeroth; och blefvo i Hazeroth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Och MirJam och Aaron talade emot Mose för hans hustrus skull, den Ethiopissan, som han till hustru tagit hade; derföre att han en Ethiopisso hade till hustru tagit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Och sade: Talar nu Herren allena genom Mose? Talar han ock icke genom oss? Och Herren hörde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Men Mose var en ganska saktmodig man, öfver alla menniskor på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Och strax sade Herren till Mose, och till Aaron, och till MirJam: Går ut I tre intill vittnesbördsens tabernakel. Och de gingo alle tre ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Då kom Herren neder i molnstodene, och steg in i dörrena af tabernaklet, och kallade Aaron och MirJam; och de gingo både ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Och han sade: Hörer min ord; om någor är ibland eder en Herrans Prophet, honom vill jag uppenbara mig uti en syn; eller uti en dröm vill jag tala med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Men icke så min tjenare Mose, hvilken uti mitt hela hus trogen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Munteliga talar jag med honom, och han ser Herran såsom han är, icke genom mörk ord eller liknelse. Hvi hafven I då icke fruktat att tala emot min tjenare Mose?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Och Herrans vrede förgrymmade sig öfver dem, och han vände sig bort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Dertill gaf ock molnskyn sig ifrå tabernaklet. Och si, då var MirJam spitelsk såsom en snö; och Aaron vände sig till MirJam, och fick se att hon var spitelsk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Han sade till Mose: Ack min herre! lägg icke denna syndena på oss, i det vi hafve ovisliga gjort, och syndat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Att denna icke blifver såsom ett dödt ting, som kommer ut af moderlifvet; det hafver allaredo bortfrätit hälftena af hennes kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Då ropade Mose till Herran, och sade: Ack Gud! gör henne helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Herren sade: Om hennes fader hade spottat henne i ansigtet, skulle hon icke skämma sig i sju dagar? Låt innelycka henne i sju dagar utan lägret; sedan låt åter taga henne igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Så vardt då MirJam innelyckt i sju dagar utan lägret, och folket for ingen vägs fram bätter, intilldess MirJam vardt igen anammad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Sedan drog folket ifrå Hazeroth, och lägrade sig uti den öknene Paran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Sänd ut män, de som må bespeja landet Canaan, det jag Israels barn gifva vill; af hvarjo deras fäders slägt en myndig man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Mose sände dem ut af den öknene Paran, efter Herrans ord, de som alle voro myndige män ibland Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Och heto alltså: Sammua, Zaccurs son, af Rubens slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Saphat, Hori son, af Simeons slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Caleb, Jephunne son, af Juda slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Jigeal, Josephs son, af Isaschars slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Hosea, Nuns son, af Ephraims slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Palti, Raphu son, af BenJamins slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Gaddiel, Sodi son, af Sebulons slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Gaddi, Susi son, af Josephs slägte af Manasse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Ammiel, Gemalli son, af Dans slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Sethur, Michaels son, af Assers slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Nahebi, Vaphsi son, af Naphthali slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Geuel, Machi son, af Gads slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Desse äro namnen af männerna, som Mose utsände till att bespeja landet. Och Hosea, Nuns son, kallade Mose Josua.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Då nu Mose utsände dem till att bespeja landet Canaan, sade han till dem: Farer upp söderut, och går upp på bergen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Och beser landet, huru det är, och folket, som deruti bor, om det är starkt eller svagt, litet eller mycket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Och hurudana land det är, der de uti bo, om det är godt eller ondt; och hurudana städer äro, der de uti bo, om de äro förvarade med murar, eller ej;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Och hurudana landet är, fett eller magert, och om trä deruti äro, eller ej; varer vid en god tröst, och tager af landsens frukt. Och det var rätt på den tiden, då första vinbären voro mogne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'De gingo upp, och bespejade landet, ifrå den öknene Zin allt intill Rehob, der man går till Hamath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'De gingo också upp söderut, och kommo till Hebron; der var Ahiman, Sesai och Thalmai, Enaks barn. Och Hebron var uppbygdt i sju år förra än Zoan uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Och de kommo intill den bäcken Escol, och skoro der en vinqvist af med en vinklasa, och läto två bära den på en stång, och dertill granatäple och fikon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Det rummet kallas Escols bäck, för den vinklasans skull, som Israels barn der afskoro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Och de vände om, när de hade bespejat landet, efter fyratio dagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Gingo och kommo till Mose och Aaron till hela menigheten af Israels barn, uti den öknene Paran till Kades; och sade honom igen, och hela menighetene, huruledes det stod till, och läto dem se landsens frukt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Och förtäljde dem, och sade: Vi vore in uti det land, dit I oss sänden, der mjölk och hannog uti flyter; och detta är dess frukt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Förutan att der bor starkt folk uti, och der äro ganska faste och store städer; och vi såge der ock Enaks barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'De Amalekiter bo söderut i landena; de Hetheer, och Jebuseer, och Amoreer bo uppå bergen; de Cananeer bo vid hafvet och vid Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Men Caleb stillte folket för Mose, och sade till dem: Låt oss draga ditupp, och taga landet in; förty vi kunne väl vara dem öfvermägtige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Men de män, som hade varit med honom uppfarne, sade: Vi förmåge icke draga ditupp emot det folk; ty de äro oss för starke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Och de förtalade landet, som de skådat hade, för Israels barnom, och sade: Landet, som vi igenomgångit hafve till att bespeja det, uppfräter sina inbyggare; och allt det folk, som vi derinne sågo, är ganska långt folk. Vi såge der ock tyranner, Enaks barn af de tyranner; och vi vorom för vår ögon såsom gräshoppor, och så vorom vi ock för deras ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Då tog hela menigheten till att skria; och folket gret den nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Och all Israels barn knorrade emot Mose och Aaron, och hela menigheten sade till dem: Ack! att vi dock hade mått dött i Egypti land, eller ännu dö måtte i denna öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Hvi förer Herren oss i detta landet, att vi skole falla för svärd, och våra hustrur och barn varda till rofs? Är icke bättre, att vi drage in uti Egypten igen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Och den ene sade till den andra: Låt oss häfva oss upp en höfvitsman, och fara in uti Egypten igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Men Mose och Aaron föllo uppå sin ansigte för hela menighetenes församling af Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Och Josua, Nuns son, och Caleb, Jephunne son, de ock landet bespejat hade, refvo sin kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Och sade till alla menighetena af Israels barn: Landet, som vi igenomvandrat hafve till att bespeja det, är ganska godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Hafver Herren vilja till oss, så förer han oss väl uti det landet, och gifver oss det; hvilket ett land är, som mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Faller icke ifrå Herran, och frukter eder intet för detta landsens folk; ty vi vilje äta dem upp såsom bröd. Deras beskärm är gånget ifrå dem, och Herren är med oss; frukter eder intet för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Då sade hela folket, att man skulle stena dem. Så syntes Herrans härlighet på vittnesbördsens tabernakel för all Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Och Herren sade till Mose: Huru länge skall detta folket försmäda mig? Och huru länge vilja de icke tro på mig genom allahanda tecken, som jag ibland dem gjort hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Jag skall slå dem med pestilentie, och förgöra dem, och göra dig till ett större och mägtigare folk, än detta är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Men Mose sade till Herran: Så få de Egyptier det höra; ty du hafver fört detta folket med dine kraft midt ut ifrå dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Och man varder sägandes till detta lands inbyggare, som hört hafva, att du, Herre, äst ibland detta folket, att du ansigte mot ansigte sedd varder, och din molnsky står öfver dem, och du, Herre, går för dem i molnstodene om dagen, och i eldstodene om nattene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Och du dräpte detta folket, såsom en man; så skulle Hedningarna, som sådana rop på dig hörde, tala och säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Herren förmådde icke föra det folket in uti det land, som han dem svorit hade; derföre hafver han dräpit dem i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Så låt nu Herrans kraft stor varda, såsom du talat hafver och sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Herren är långmodig, och af stora barmhertighet, och förlåter missgerning och öfverträdelse, och låter ingen vara ostraffad, utan söker fädernas missgerningar öfver barnen, intill tredje och fjerde led.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Så var nu nådelig öfver detta folks missgerning, efter dina stora barmhertighet, såsom du ock desso folke förlåtit hafver, allt ifrån Egypten, och härtill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Och Herren sade: Jag hafver förlåtit dem det, såsom du sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Men så visst som jag lefver, så skall all verlden varda full af Herrans härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Ty alle de män, som hafva sett mina härlighet, och min tecken, som jag gjort hafver uti Egypten, och uti öknene, och nu tio resor försökt mig, och icke hafva lydt mine röst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Ingen af dem skall få se det landet, som jag deras fäder svorit hafver; och ingen skall se det, den mig försmädat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Men min tjenare Caleb, derföre, att en annar Anda med honom är, och hafver troliga följt mig efter, honom skall jag föra in i det landet, der han inkom; och hans säd skall intaga det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Dertill ock de Amalekiter och Cananeer, som i dalarna bo. I morgon vänder om, och drager in uti öknena, på den vägen åt röda hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Huru länge skall denna onda hopen knorra emot mig? Ty jag hafver hört Israels barnas knorran, som de emot mig knorrat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Derföre säg till dem: Så visst som jag lefver, säger Herren, skall jag göra eder såsom I för min öron sagt hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Edra kroppar skola falla i denna öknene; och alle I, som räknade ären ifrå tjugu år och derutöfver, I som emot mig knorrat hafven,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Skolen intet komma in uti det land, der jag mina hand på upphäfvit hafver, att jag skulle låta eder deruti bo, förutan Caleb, Jephunne son, och Josua, Nuns son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Men edor barn, der I om saden, att de skulle varda till ett rof, dem vill jag föra derin, att de skola få se det land, som I förkasten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Men I, med edra kroppar, skolen falla i denna öken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Och edor barn skola varda herdar i öknene, i fyratio år, och umgälla edart horeri, intilldess edra kroppar varda åtgångne i öknene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Efter talet af de fyratio dagarna, i hvilkom I landet bespejaden, ju ett år för hvar dagen, att de skola umgälla edor missgerning i fyratio år; på det I skolen förnimma, hvad det är, när jag tager mina hand ifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Jag Herren hafver det sagt, det vill jag ock så göra allom dessom onda hopenom, som sig emot mig upphäfvit hafver; uti denna öken skola de åtgå, och der dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Alltså dödde af Herrans plågo alle de män, som Mose sändt hade till att bespeja landet, och igenkomne voro, och hade kommit hela menighetena till att knorra deremot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Dermed att de gåfvo landena ett rykte, att det var ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Men Josua, Nuns son, och Caleb, Jephunne son, blefvo lefvande, af de män, som gångne voro till att bespeja landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Och Mose talade dessa orden till all Israels barn; då sörjde folket svårliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Och stodo om morgonen bittida upp, och drogo upp på bergshöjdena, och sade: Här äre vi, och vilje draga upp till de rum, der Herren oss af sagt hafver; ty vi hafve syndat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Men Mose sade: Hvi gån I så utöfver Herrans ord? Det skall icke väl bekomma eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Drager icke upp; förty Herren är icke med eder; att I icke blifven slagne för edra fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Ty de Amalekiter och Cananeer äro der för eder; och I varden fallande för svärd, derföre, att I hafven vändt eder ifrå Herranom; och Herren skall intet vara med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Men de voro förblindade till att draga upp på bergshöjdena; men Herrans förbunds ark och Mose kommo intet utu lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Så kommo de Amalekiter och Cananeer, som på bergen bodde, neder, och slogo dem, och förföljde dem allt intill Horma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Tala med Israels barn, och säg till dem: När I kommen in uti det land, der I uti bo skolen, det jag eder gifva skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'Och viljen göra Herranom offer, vare sig bränneoffer, eller ett offer af ett besynnerligit löfte, eller ett friviljeoffer, eller edor högtidsoffer; på det I skolen göra Herranom en söt lukt, af fä eller får;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Hvilken nu Herranom sina gåfvo offra vill, han skall göra till ett spisoffer en tiung semlomjöl, blandadt med oljo; en fjerding af ett hin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Och vin till drickoffer, sammalunda en fjerding af ett hin till bränneoffer eller eljest till ett offer, der ett lamb offradt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Men der en vädur varder offrad, skall du göra spisoffret två tiungar semlomjöl, blandadt med oljo, en tridiung af ett hin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Och vin till drickoffer, ock en tridiung af ett hin; det skall du offra Herranom till en söt lukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Men vill du göra en stut till bränneoffer, eller till ett besynnerligit löfteoffer, eller till tackoffer Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Så skall du till stuten göra ett spisoffer, tre tiungar semlomjöl, blandadt med oljo, ett halft hin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Och vin till drickoffer, sammalunda ett halft hin. Detta är ett offer Herranom till en söt lukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Alltså skall du göra med en stut, med enom vädur, med ett får, af lambom och getom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Derefter som talet är af dessa offren, derefter skall ock talet vara till spisoffret och drickoffret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Den som en inländsker är, han skall detta göra, på det han må göra Herranom ett offer till en söt lukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Och om en främling bor när eder, eller ibland eder när edra fränder är, och vill göra Herranom ett offer till en söt lukt; han skall göra såsom de göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Hela menighetene skall vara en stadge, både eder och främlingomen. En evig stadge skall det vara edrom efterkommandom, att för Herranom skall en främling vara såsom I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'En lag, en rätt skall vara eder och främlingenom, som bor när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Tala med Israels barn, och säg till dem: När I kommen in uti landet, dit jag eder införa skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Att I äten af landsens bröd, skolen I gifva Herranom ett häfoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Nämliga af edars degs förstling skolen I gifva ena kako till häfoffer, såsom I gifven häfoffer af ladone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Så skolen I ock gifva Herranom förstling af edar deg till häfoffer, med edra efterkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Och om I af ovetenhet försummen något af dessa bud, som Herren till Mose sagt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Och allt det Herren eder genom Mose budit hafver, ifrå den dagen Herren begynte bjuda, intill edra efterkommande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Om nu menigheten gör något ovetandes, så skall hela menigheten göra en ungan stut af boskapen till ett bränneoffer, Herranom till en söt lukt; samt med sitt spisoffer och drickoffer, såsom det sig bör; och en getabock till syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Och Presten skall alltså försona hela menighetena af Israels barn, så varder det dem förlåtet; ty det är en ovetenhet. Och de skola frambära sådana sina gåfvor Herranom till ett offer; och sitt syndoffer för Herranom öfver sina ovetenhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Så varder det förlåtet hela menighetene af Israels barn; dertill ock främlingomen, som bo ibland eder, efter hela folket är i sådana ovetenhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Men när en själ genom ovetenhet syndar, hon skall frambära en årsgammal get till syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Och Presten skall försona sådana ovetande själ med syndoffret för ovetenhetena för Herranom, så att han henne försonar; så varder det henne förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Och det skall vara allt en lag, som I för ovetenhet göra skolen, både dem som inländske äro ibland Israels barn, ock så främlingomen, som bo ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Men om en själ något gör af öfverdådighet, vare sig inländsk eller utländsk, den hafver Herran försmädat; den själen skall utrotad varda utu hennes folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Ty hon hafver föraktat Herrans ord, och gjort hans bud omintet; hon skall platt utrotad varda, och umgälla sin skuld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Som nu Israels barn voro i öknene, funno de en man hemtande ved om Sabbathsdagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Och de som hade funnit honom dermed, då han hemtade veden, hade honom fram för Mose och Aaron, och för hela menighetena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Och de satte honom i fängelse; ty det var icke klarliga uttryckt, hvad man skulle göra med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Men Herren sade till Mose: Den mannen skall döden dö; hela menigheten skall stena honom utanför lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Så förde hela menigheten honom ut för lägret, och stenade honom ihjäl, såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Och Herren sade till Mose:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Tala med Israels barn, och säg till dem, att de skola göra sig klutar på fållarna af deras kläder, i alla deras efterkommandom, och gul snöre i klutomen vid fållarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Och skola de klutar tjena eder dertill, att I skolen se på dem, och ihågkomma all Herrans bud, och göra dem, att I icke efterföljen edars hjertas tycko, eller hor drifven efter edor ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Derföre skolen I ihågkomma och göra all min bud, och helige vara edrom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Jag Herren edar Gud, den eder utur Egypti land fört hafver, att jag skulle vara edar Gud: Jag Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Och Korah, Jizears son, Kehats sons, Levi sons, tog till sig Dathan och Abiram, Eliabs söner, och On, Peleths son, af Rubens söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Och de hofvo sig upp emot Mose, med några män af Israels barn, tuhundrade och femtio myndige i menighetene, rådherrar och ärlige män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Och de församlade sig emot Mose och Aaron, och sade till dem: I gören allt för mycket; ty hela menigheten är helig, och Herren är ibland dem; hvi upphäfven I eder öfver Herrans menighet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Då Mose det hörde, föll han uppå sitt ansigte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Och sade till Korah, och hans hela parti: I morgon varder Herren kungörandes, hvilka honom tillhöra, hvilken helig är, och honom offra skall; den han utväljer, han skall offra honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Detta görer: Tager för eder rökopannor, Korah och hans hela parti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'Och lägger der eld in, och kaster rökverk deruppå för Herranom i morgon. Hvilken som Herren utväljer, han vare helig; I göret allt för mycket, I Levi barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Och Mose sade till Korah: Käre, hörer dock, I Levi barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Är det eder icke nog, att Israels Gud hafver afskiljt eder ifrå den meniga Israel, att I skolen offra honom, så att I skolen tjena honom i Herrans tabernakels ämbete, och träda fram för menighetena till att tjena henne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Han hafver tagit dig, och alla dina bröder, Levi barn, samt med dig till sig, och I faren nu ock efter Presterskapet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Du och ditt hela parti gören uppror emot Herran: Hvad är Aaron, att I knorren emot honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Och Mose sände bort och lät kalla Dathan och Abiram, Eliabs söner; men de sade: Vi komme intet ditupp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Är det icke nog, att du hafver fört oss utu landet, der mjölk och hannog uti flyter, att du skulle dräpa oss i öknene; skall du ännu dertill vara herre öfver oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Skönliga hafver du fört oss in uti det land, der mjölk och hannog uti flyter, och hafver gifvit oss åkrar och vingårdar till arfvedel; vill du ock stinga folke ögonen ut? Vi komme intet ditupp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Då förgrymmade sig Mose ganska svårliga, och sade till Herran: Vänd dig icke till deras spisoffer; jag hafver icke tagit dem en åsna ifrå, och ingen af dem något gjort emot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Och han sade till Korah: Du och ditt hela parti skolen i morgon vara för Herranom, du, de ock, och Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Och hvar tage sina rökopanno, och lägge rökverk deruppå, och går fram för Herran, hvar med sine panno, det äro tuhundrade och femtio pannor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Och hvardera tog sina panno, och lade der eld in, och kastade rökverk deruppå, och gingo in för dörrena af vittnesbördsens tabernakel; och Mose och Aaron desslikes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Och Korah församlade emot dem hela menighetena, inför dörrena af vittnesbördsens tabernakel. Och Herrans härlighet syntes för hela menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Skiljer eder ifrå denna menighetene, att jag med hast må förgöra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Men de föllo på sitt ansigte, och sade: Ack Gud, allt kötts andas Gud! Om en man syndat hafver, vill du då hämnas öfver hela menighetena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Tala till menighetena, och säg: Kommer upp ifrå Korahs, och Dathans, och Abirams tjäll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Och Mose stod upp, och gick till Dathan och Abiram; och de äldste af Israel följde honom efter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Och talade till menighetena, och sade: Går ifrå dessa ogudaktiga menniskors tjäll, och kommer intet vid något det dem tillhörer, att I icke tilläfventyrs förgås uti någon deras synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Och de gingo upp ifrå Korahs, Dathans och Abirams tjäll; men Dathan och Abiram gingo ut, och trädde i dörrena af deras tjäll med deras hustrur, söner och barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Och Mose sade: Deruppå skolen I märka, att Herren mig sändt hafver, att jag alla dessa gerningar göra skulle; och icke af mino hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Om de dö såsom alla menniskor, eller hemsökta varda, såsom alla menniskor hemsökta varda; så hafver Herren icke sändt mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Men om Herren gör här något nytt, så att jorden öppnar sin mun, och uppslukar dem, med allt det de hafva, att de lefvande fara neder i helvetet; så skolen I förstå, att desse männerna hafva försmädat Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Och som han all dessa orden uttalat hade, remnade jorden under dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'Och lät sin mun upp, och uppslukte dem med deras hus, med alla de menniskor, som när Korah voro, och med alla deras håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Och de foro lefvande neder i helvetet, med allt det de hade; och jorden öfvertäckte dem; och de förgingos utu menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Och hela Israel, som omkring dem var, flydde för deras skris skull; ty de sade: Att jorden icke ock uppslukar oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Dertill for en eld ut ifrå Herranom, och upptärde de tuhundrade och femtio män, som det rökverket offrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Säg Eleazar, Prestens Aarons son, att han upptager rökopannorna utu brandenom, och förströr elden hit och dit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Förty de syndares pannor äro helgade genom deras själar, att man må slå dem i skifvor, och hänga dem på altaret; ty de äro offrade för Herranom, och helgade, och skola vara Israels barnom ett tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Och Eleazar Presten tog de kopparpannorna, som de uppbrände män uti offrat hade, och slog dem i skifvor, till att hänga vid altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Israels barnom till en åminnelse, att ingen främmande skulle gå fram, som icke är af Aarons säd, till att offra rökverk för Herranom; på det honom icke skall gå såsom Korah och hans parti, såsom Herren honom sagt hade genom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Den andra morgonen knorrade hela menigheten af Israels barn emot Mose och Aaron, och sade: I hafven dräpit Herrans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Och då menigheten församlade sig emot Mose och Aaron, vände de sig till vittnesbördsens tabernakel; och si, molnskyn öfvertäckte det, och Herrans härlighet syntes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Och Mose och Aaron gingo in för vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Går ut ifrå denna menighetene; jag vill med hast förgöra dem. Och de föllo uppå sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Och Mose sade till Aaron: Tag rökopannona, och låt der eld in af altaret, och kasta rökverk deruppå, och gack snarliga till menighetena, och försona dem; förty vrede är utgången af Herranom, och plågan hafver begynt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Och Aaron tog, såsom Mose sade honom, och lopp midt igenom menighetena; och si, plågan var uppågången ibland folket och han rökte, och försonade folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Och stod emellan de döda och de lefvande; då vardt plågan förtagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Men de som af plågone döde voro, voro fjortontusend och sjuhundrad, undantagnom dem som förgingos uti Korahs uppror.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Och Aaron kom igen till Mose för dörrena af vittnesbördsens tabernakel; och plågan var förtagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Säg Israels barnom, och tag af dem tolf stafrar, af hvar och en sins faders hus Första en, och skrif hvarsderas namn på hans staf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Men Aarons namn skall du skrifva på Levi staf; ty ju för hvar sins faders hus höfvitsman skall vara en staf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Och lägg dem in i vittnesbördsens tabernakel, för vittnesbördet, der jag betygar eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Och den som jag utväljandes varder, hans staf skall grönskas; på det att jag må stilla det knorrandet, som Israels barn knorra emot eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Mose talade med Israels barn; och alle deras Förstar fingo honom tolf stafrar, hvar försten en staf efter deras fäders hus; och Aarons staf var desslikes ibland deras stafrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Och Mose lade stafrarne inför Herran uti vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Om morgonen, då Mose gick in uti vittnesbördsens tabernakel, fann han Aarons staf af Levi hus grönskas, och blomstren utgångna, och mandel bära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Och Mose bar ut alla strafrarna ifrå Herranom för all Israels barn, så att de sågo det, och hvar och en tog sin staf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Då sade Herren till Mose: Bär Aarons staf åter inför vittnesbördet, att han förvarad varder för ett tecken till de olydiga barnen; att deras knorrande uppå mig må återvända, att de icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Mose gjorde såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Och Israels barn sade till Mose: Si, vi förgås, och blifve borto; vi förminskas, och vardom alle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Ho som kommer intill Herrans tabernakel, han dör: skole vi då platt förödas?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Och Herren sade till Aaron: Du och dine söner, och dins faders hus med dig, skolen bära helgedomens missgerning; och du och dine söner med dig skolen bära edars Presterskaps missgerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Men dine bröder af Levi dins faders slägte skall du taga till dig, att de äro när dig, och tjena dig; men du och dine söner med dig skolen tjena inför vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Och de skola taga vara på din tjenst, och hela tabernaklets tjenst; dock skola de intet nalkas intill helgedomens tyg, och till altaret, att både de och I icke skolen dö;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Utan de skola vara när dig, att de taga vara uppå vittnesbördsens tabernakels tjenst, uti all tabernaklets ämbete; och ingen främmande skall nalkas eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Så akter nu uppå helgedomens tjenste, och uppå altarens tjenste, att icke mer en vrede kommer öfver Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Ty si, jag hafver tagit edra bröder Leviterna ut ifrån Israels barn, och gifvit eder Herranom till en skänk, att de skola taga vara på ämbetet vid vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Men du och dine söner med dig skolen akta på edart Presterskap, att I tjenen uti all altarens handel, och innanför förlåten; ty edart Presterskap gifver jag eder till ett ämbete för en gåfvo; om någor främmande går härtill, han skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Och Herren sade till Aaron: Si, jag hafver gifvit dig mitt häfoffer, af allt det som Israels barn helga, för ditt Prestaämbete, och dinom sönom till en evig rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Detta skall du hafva af det aldrahelgasta, som de offra: Alla deras gåfvor med allt deras spisoffer, och med allt deras syndoffer, och med allt deras skuldoffer, som de mig gifva, det skall vara dig och dinom sönom det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'På aldrahelgasta rum skall du äta det; hvad mankön är, skall deraf äta; ty det skall vara dig heligt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Jag hafver ock gifvit dig och dinom sönom, och dinom döttrom med dig, deras gåfvors häfoffer, i allo Israels barnas veftoffre till en evig rätt: Den som ren är i dino huse, han skall äta deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Alla bästa oljo, och all bästa vinmust, och deras förstlingskorn, det som de gifva Herranom, hafver jag gifvit dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Den första frukten af allt det i deras lande är, det som de bära Herranom, skall vara ditt; den som ren är i dino huse, han skall äta deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Allt det spillgifvet är i Israel, skall vara ditt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Allt det som moderlif öppnar ibland allt kött, det som de bära Herranom, vare sig menniska eller fänad, skall vara ditt; dock så, att du den första fruktena af mennisko låter lösa, och den första frukten af en oren fänad också lösa låter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Och skola de lösa det, när det är en månad gammalt; och skall gifvat till lösen för penningar, för fem siklar efter helgedomens sikel, hvilken tjugu gera gäller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Men den första frukten af fä eller får, eller get, skall du icke till lösen gifva; ty de äro helig. Deras blod skall du stänka på altaret, och deras feta skall du uppbränna till en söt lukts offer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Deras kött skall vara ditt, såsom ock veftebröstet, och högre bogen din är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Allt häfoffer, som Israels barn helga Herranom, hafver jag gifvit dig och dinom sönom, och dinom döttrom med dig till en evig rätt; det skall vara ett oförgängeligit och evigt förbund för Herranom, dig och dine säd med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Och Herren sade till Aaron: Du skall ingen besittning hafva i deras land, och ingen lott hafva med dem; ty jag är din lott, och ditt arfvegods ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Men Levi barn hafver jag gifvit all tionde i Israel till ett arfvegods, för deras ämbete, som de göra mig vid vittnesbördsens tabernakel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Så att härefter Israels barn intet skola nalkas intill vittnesbördsens tabernakel, till att komma sig i synd och dö;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Utan Leviterna skola akta på ämbetet vid vittnesbördsens tabernakel, och de skola bära deras synder till en evig rätt till edra efterkommande; och de skola intet arfvegods besitta ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Ty Israels barnas tiond, som de häfoffra Herranom, hafver jag gifvit Leviterna till arfvegods; derföre hafver jag sagt till dem, att de ibland Israels barn intet arfvegods besitta skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Tala till de Leviter, och säg till dem: När I tagen tionden af Israels barn, den jag eder af dem gifvit hafver till edart arfvegods, så skolen I göra Herranom deraf ett häfoffer, ju tiond af tiond;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Och skolen sådana edart häfoffer hålla såsom I gåfven korn af ladone, och fyllo af pressen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Alltså skolen I ock gifva Herranom häfoffer af allo edro tiond, som I tagen af Israels barnom; så att I sådant Herrans häfoffer gifven Prestenom Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Utaf allt, det eder gifvet varder, skolen I gifva Herranom allahanda häfoffer, af allt det bästa, som deraf helgadt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Och säg till dem: När I alltså det bästa deraf häfoffren, så skall det Levitomen räknadt varda, lika som det af ladone, och såsom det af pressen gåfves.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Och I mågen det äta allestäds, I och edor barn; ty det är edor lön för edart ämbete uti vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Så synden I icke deröfver, när I häfoffren det feta deraf, och icke ohelgen det Israels barn helgat hafva, att I icke dön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Och Herren talade med Mose och Aaron, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Detta sättet skall vara en lag, den Herren budit hafver, och sagt: Säg Israels barnom, att de hafva till dig en rödlett ko utan vank, der ingen brist på är, der intet ok ännu påkommet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Och få henne Prestenom Eleazar, han skall föra henne ut för lägret, och låta der slagta henne för sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Och Presten Eleazar skall taga af hennes blod med sitt finger, och stänka rätt emot vittnesbördsens tabernakel sju resor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Och låta uppbränna kona för sig, både hennes hud och hennes kött, dertill hennes blod, samt med gåret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Och Presten skall taga cedreträ och isop, och rosenröd ull, och kasta på den brinnande kona;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Och skall två sin kläder, och bada sin kropp med vatten, och sedan gå i lägret, och vara oren allt intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Och den som uppbrände henne, skall ock två sin kläder med vatten, och bada sin kropp i vatten, och vara oren allt intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Och en ren man skall upptaga askona af kone, och slå henne ut på ett rena rum utan lägret, att hon varder der förvarad åt menighetene af Israels barnom till stänkevatten; ty det är ett syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Och den som askona af kone upptog, skall två sin kläder, och vara oren allt intill aftonen. Detta skall vara en evig rätt Israels barnom, och främlingomen, som bo ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Den som kommer vid ena döda mennisko, han skall vara oren i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Så skall han härmed rena sig på tredje dagen, och på sjunde dagen, och så varder han ren. Och om han icke på tredje och sjunde dagen renar sig, så skall han icke ren varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Men om någor kommer vid ena döda mennisko, och icke vill rena sig, den orenar Herrans tabernakel, och sådana själ skall utrotad varda utur Israel; derföre, att stänkevattnet icke är stänkt öfver honom, så är han oren, så länge han sig icke rena låter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Detta är lagen, om en menniska dör i tjället: Den som går in i tjället, och allt det som i tjället är, skall vara orent i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Och hvart och ett botyg, som öppet är, det intet öfvertäckelse eller band hafver, det är orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Desslikes den som på markene kommer vid någon, som slagen är med svärd, eller eljest en dödan, eller ene menniskos ben, eller graf, den är oren i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Så skola de nu för den orena taga af desso uppbrända syndoffers asko, och låta deruppå rinnande vatten uti ett käril.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Och en ren man skall taga isop, och doppa i vattnet, och stänka tjället, och alla botyg, och alla de själar, som derinne äro; sammalunda ock den som hafver kommit vid ens döds ben, eller en slagnan, eller en dödan, eller någon graf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Och den rene skall stänka den orena på tredje dagen, och på sjunde dagen, och rena honom på sjunde dagen; och skall två sin kläder, och bada sig i vatten, så varder han ren om aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Men hvilken som varder oren, och icke vill rena sig, hans själ skall utrotad varda utu menighetene; förty han hafver orenat Herrans helgedom, och icke är med stänkevattne stänkt; derföre är han oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Och detta skall varda dem en evig rätt. Skall också den som med stänkevattnena stänkte, två sin kläder; och den som kommer vid stänkevattnet, han skall vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Och allt det han kommer vid, det skall vara orent. Och hvilken själ, som han vederkommer, hon skall vara oren intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Och Israels barn kommo med hela menighetene in uti den öknena Zin, i första månaden; och folket blef i Kades. Och MirJam blef der död, och vardt der begrafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Och menigheten hade intet vatten; och de församlade sig emot Mose och Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Och folket trätte med Mose, och sade: Ack! det vi hade förgångits, der våre bröder förgingos för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Hvi hafven I fört denna Herrans menighet uti denna öknena, att vi här dö skole med vårom boskap?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Och hvi hafven I fört oss utur Egypten intill denna onda platsen, der man intet så kan; der hvarken äro fikon eller vinträ, ej heller granatäple; och är dertillmed intet vatten till att dricka?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Då gingo Mose och Aaron ifrå menighetene intill dörrena af vittnesbördsens tabernakel, och föllo på sitt ansigte; och Herrans härlighet syntes dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Tag stafven, och församla menighetena, du och din broder Aaron, och taler till hälleberget för deras ögon; det skall gifva sitt vatten. Alltså skall du skaffa dem vatten utu hälleberget, och gifva menighetene dricka, och deras boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Då tog Mose stafven för Herranom, såsom han honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Och Mose och Aaron församlade menighetena inför hälleberget, och sade till dem: Hörer, I olydige; månne vi ock skole skaffa eder vatten utu detta hälleberget?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Och Mose hof upp sina hand, och slog på hälleberget med sin staf två gånger; då gick der ut mycket vatten, så att menigheten fick dricka, och deras boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Och Herren sade till Mose och Aaron: Derföre, att I icke trodden uppå mig, att I måtten helgat mig för Israels barnom, skolen I icke föra denna menighetena in i det land, som jag dem gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Detta är det trätovattnet, öfver hvilket Israels barn trätte med Herranom, och han vardt helgad i dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Och Mose sände bådskap ut ifrå Kades till de Edomeers Konung: Så låter din broder Israel säga dig: Du vetst all den mödo, som oss påkommen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Att våre fäder voro nederfarne in uti Egypten, och vi i långan tid bodde uti Egypten, och de Egyptier handlade illa med oss och våra fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Och vi ropade till Herran, och han hörde våra röst, och utsände en Ängel, och förde oss utur Egypten: och si, vi äre i Kades, i den staden, som vid dina gränsor är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Låt oss draga igenom ditt land; vi vilje icke fara öfver åker eller vingårdar, och icke dricka vattnet utu brunnarna; vi vilje draga rätta landsstråtena, hvarken vikande på den högra sidona eller på den venstra, tilldess vi komme igenom dina landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'De Edomeer sade till dem: Du skall icke draga härigenom, eller jag skall möta dig med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Israels barn sade till dem: Vi vilje draga den meniga stråtena; och om vi dricke af ditt vatten, vi och vår boskap, så vilje vi det betala; vi vilje icke utan allenast gå till fot derigenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Men han sade: Du skall icke draga härigenom. Och de Edomeer drogo ut emot dem med mägtigt folk, och starka hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Alltså förvägrade de Edomeer Israel draga igenom deras landsändar. Och Israel vek ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Och Israels barn drogo ifrå Kades, och kommo med hela menighetene intill det berget Hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Och Herren talade med Mose och Aaron på bergena Hor, vid gränsen åt de Edomeers land, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Låt Aaron samla sig till sitt folk; ty han skall icke komma i det landet, som jag Israels barnom gifvit hafver, derföre, att I voren minom mun ohörsamme vid trätovattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Så tag nu Aaron och hans son Eleazar, och haf dem upp på berget Hor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Och afkläd Aaron hans kläder, och kläd dem på hans son Eleazar; och Aaron skall der samlas, och dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Mose gjorde såsom Herren honom böd; och de stego upp på berget Hor, för hela menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Och Mose afklädde Aaron hans kläder, och klädde dem på hans son Eleazar. Och Aaron blef der död uppå berget; men Mose och Eleazar stego neder utaf bergena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Och då hela menigheten såg att Aaron var död, begreto de honom i tretio dagar, hela Israels hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Och då den Cananeen, Konungen i Arad, som söderut bor, hörde att Israel inkom genom spejares väg, stridde han emot Israel, och förde några af dem fångna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Då lofvade Israel Herranom ett löfte, och sade: Om du gifver detta folket under mina hand, så skall jag gifva deras städer tillspillo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Och Herren hörde Israels bön, och gaf dem de Cananeer, och de gjorde dem tillspillo med deras städer; och kallade det rummet Horma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Sedan drogo de ifrå berget Hor, på den vägen åt röda hafvet, att de skulle draga omkring de Edomeers land. Och folket vardt ledse på vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Och folket talade emot Gud, och emot Mose: Hvi hafver du fört oss utur Egypten, att vi skulle dö i öknene? Ty här är hvarken bröd eller vatten, och vår själ vämjar öfver denna lösa maten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Då sände Herren ibland folket brännande ormar; de beto folket, så att mycket folk i Israel blef dödt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Så kommo de till Mose, och sade: Vi hafve syndat, att vi emot Herran och emot dig talat hafve; bed Herran, att han tager dessa ormarna ifrån oss. Mose bad för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Då sade Herren till Mose: Gör dig en kopparorm, och res honom upp för ett tecken; hvilken som biten är, och ser uppå honom, han skall lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Så gjorde Mose en kopparorm, och reste honom upp för ett tecken, och om någor vardt biten af orme, så såg han på den kopparormen, och blef vid lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Och Israels barn drogo ut, och lägrade sig i Oboth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Och ifrån Oboth drogo de ut, och lägrade sig i Ijim vid berget Abarim, uti den öknene tvärtöfver Moab österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Dädan drogo de, och lägrade sig vid den bäcken Sared.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Dädan drogo de, och lägrade sig på denna sidone vid Arnon, hvilket i öknene är, och sträcker sig ut ifrå de Amoreers landsändar; ty Arnon är Moabs landamäre, emellan Moab och de Amoreer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Deraf säger man uti den bokene om Herrans strider: Den höga bergklippan allt intill skyn, och intill Arnons bäck;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Och intill bäcksens källo, hvilken räcker allt intill den staden Ar, och böjer sig, och är Moabs gränsa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Och dädan drogo de till brunnen; det är den brunnen, der Herren af sade till Mose: Församla folket, jag vill gifva dem vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Då söng Israel denna visona, och söngo emot hvarannan öfver brunnen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Denna är den brunnen, som de Förstar grafvit hafva; de ädle i folket hafva grafvit honom, genom läraren och deras stafrar. Ifrå denne öknene drogo de till Mattana;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Och ifrå Mattana till Nahaliel, och ifrå Nahaliel till Bamoth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'Och ifrå Bamoth till den dalen, som ligger i Moabs mark, vid det höga berget Pisga, som vet åt öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Och Israel sände båd till Sihon, de Amoreers Konung, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Låt mig draga igenom ditt land; vi vilje intet vika in på åkrar, eller in på vingårdar; vi vilje icke heller dricka brunnvattnet; landstråtena vilje vi fara, tilldess vi komme genom dina landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Men Sihon tillstadde icke Israels barn gå igenom sina landsändar; utan församlade allt sitt folk, och drog emot Israel i öknena. Och som han kom till Jahza, stridde han emot Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Men Israel slog honom med svärdsegg, och tog hans land in, ifrån Arnon allt intill Jabbok, och allt intill Ammons barn; förty Ammons landsändar voro faste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Alltså tog Israel alla dessa städerna, och bodde i alla de Amoreers städer, i Hesbon, och alla hans döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Ty staden Hesbon hörde Sihon Amoreers Konunge till, och han hade tillförene stridt med de Moabiters Konung, och vunnit honom af all hans land, allt intill Arnon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Deraf säger man i ordspråket: Kommer till Hesbon, att man bygger och upprättar den staden Sihon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Ty en eld är utgången af Hesbon, en låge af den staden Sihon; han hafver uppfrätit Ar de Moabiters; och de der bo i de höjder Arnon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Ve dig, Moab; du Chemos folk äst förgånget. Man hafver hans söner slagit på flyktena, och fört hans döttrar fångna till Sihon, de Amoreers Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Deras härlighet är vorden omintet, ifrå Hesbon intill Dibon; hon är förstörd allt intill Nopha, hvilken räcker allt intill Medeba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Så bodde Israel uti de Amoreers lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Och Mose sände ut spejare till Jaeser, och de vunno dess döttrar, och togo de Amoreer in, som deruti voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Och vände om, och drogo uppåt den vägen till Basan. Då drog Og, Konungen i Basan, ut emot dem med allt sitt folk, till att strida i Edrei.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Och Herren sade till Mose: Frukta dig intet för honom; ty jag hafver gifvit honom i dina hand med land och folk; och du skall göra med honom, såsom du med Sihon, de Amoreers Konung, gjort hafver, hvilken i Hesbon bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Och de slogo honom och hans söner, och allt hans folk, tilldess att ingen var igen; och togo det landet in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Sedan foro Israels barn ut, och lägrade sig i Moabs mark, vid Jordan, in mot Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Och då Balak, Zipors son, såg allt det Israel gjort hade de Amoreer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Och att de Moabiter mycket fruktade för det folket, som så mycket var; och att de Moabiter grufvade sig för Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Då sade de Moabiter till de äldsta af de Midianiter: Nu varder denne hopen uppgnagandes allt det omkring oss är, såsom en oxe uppfräter gräset på markene. Och var Balak, Zipors son, den tiden de Moabiters Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Och han sände ut båd till Bileam, Beors son, den en spåman var; han bodde vid älfvena i hans folks barnas lande; att de skulle kalla honom, och lät säga honom: Si, ett folk är draget utur Egypten, det öfvertäcker jordenes ansigte, och det ligger emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Så kom nu, och förbanna mig det folket; ty det är mig för mägtigt; om jag kunde slå dem, och fördrifva dem utu landet; förty jag vet, hvem du välsignar, han är välsignad, och den du förbannar, han är förbannad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Och de äldste af de Moabiter gingo bort med de äldsta af de Midianiter, och hade spådomslön i deras händer; och gingo in till Bileam, och sade honom Balaks ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Och han sade till dem: Blifver här öfver nattena, så vill jag säga eder igen, hvad Herren mig sägandes varder. Så blefvo de Moabiters Förstar när Bileam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Och Gud kom till Bileam, och sade: Ho äro de män, som när dig äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileam sade till Gud: Balak, Zipors son, de Moabiters Konung, hafver sändt till mig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Si, ett folk är utdraget utur Egypten, och öfvertäcker jordenes ansigte; så kom nu, och förbanna dem; om jag kunde strida med dem, och fördrifva dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Men Gud sade till Bileam: Gack intet med dem, förbanna icke heller folket; ty det är välsignadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Då stod Bileam bittida upp om morgonen, och sade till Balaks Förstar: Går i edart land; förty Herren vill icke tillstädja, att jag går med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Och de Moabiters Förstar stodo upp, kommo till Balak, och sade: Bileam nekar sig vilja komma med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Då sände Balak ännu yppare och härligare Förstar än hine voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Då de kommo till Bileam, sade de till honom: Så låter Balak, Zipors son, säga dig: Låt dig icke förtryta att komma till mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Ty jag vill högeliga ära dig, och hvad du säger mig, det vill jag göra: Käre, kom, och förbanna mig detta folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Bileam svarade, och sade till Balaks tjenare: Om Balak gåfve mig sitt hus fullt med silfver och guld, så kunde jag dock icke gå öfver Herrans mins Guds ord, litet eller mycket till att göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Så blifver ock ännu I här i denna natten, att jag må förfara hvad Herren ytterligare med mig talandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Då kom Gud om nattena till Bileam, och sade till honom: Äro desse männerne komne till att kalla dig, så statt upp, och far med dem; dock hvad jag säger dig, det skall du göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Då stod Bileam om morgonen upp, och sadlade sina åsninno, och följde de Moabiters Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Men Guds vrede förgrymmade sig, att han for dit. Och Herrans Ängel trädde fram i vägen, att han skulle stå honom emot. Men han red på sine åsninno, och två dränger voro med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Och åsninnan såg Herrans Ängel stå i vägenom, och ett draget svärd i hans hand. Och åsninnan vek af vägenom in på markena; men Bileam slog henne, att hon skulle gå på vägenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Då trädde Herrans Ängel uti ett trångt tä emellan vingårdar, der på båda sidor gårdar voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Och då åsninnan såg Herrans Ängel, trängde hon sig intill gården, och klämde foten af Bileam in mot gården; och han slog henne ännu mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Då gick Herrans Ängel ytterligare in på ett trångt rum, der ingen väg var till att afvika, antingen på högra eller venstra sidona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Och då åsninnan såg Herrans Ängel, föll hon på knä under Bileam. Då förgrymmade sig Bileams vrede, och han slog åsninnona med stafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Då öppnade Herren åsninnones mun, och hon sade till Bileam: Hvad hafver jag gjort dig, att du hafver slagit mig nu tre gånger?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileam sade till åsninnan: Förty du gjorde gäck af mig; ack! hade jag nu ett svärd i handene, jag skulle dräpa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Åsninnan sade till Bileam: Är jag icke din åsninna, der du på ridit hafver i dina dagar intill denna tid? Hafver jag någon tid så plägat göra med dig? Han sade: Nej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Då öppnade Herren Bileams ögon, att han såg Herrans Ängel stå i vägenom, och ett draget svärd uti hans hand, och han neg, och bugade sig med sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Och Herrans Ängel sade till honom: Hvi hafver du slagit dina åsninno nu tre gånger? Si, jag är utgången, att jag skall stå dig emot; ty denne vägen är mig emot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Och åsninnan såg mig, och vek undan för mig i tre gånger; eljest, hvar hon icke undanvikit hade, så hade jag nu slagit dig ihjäl, och åsninnan hade lefvande blifvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Då sade Bileam till Herrans Ängel: Jag hafver syndat; ty jag visste icke, att du stod emot mig i vägenom. Och nu, om det är icke din vilje, vill jag vända om igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Herrans Ängel sade till honom: Far med dessa männerna; men intet annat skall du tala, utan det jag säger dig. Så följde Bileam Balaks Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Då Balak hörde, att Bileam kom, for han ut emot honom uti de Moabiters stad, som ligger i gränsone vid Arnon, hvilken är vid den yttersta gränson;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Och sade till honom: Hafver jag icke sändt efter dig, och låtit kalla dig? Hvi äst du då icke kommen till mig? Menar du jag kunde icke ära dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Bileam svarade honom: Si, jag är kommen till dig; men huru kan jag något annat tala, utan det Gud gifver mig i munnen, det måste jag tala?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Så for Bileam med Balak, och kommo in i gatustaden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Och Balak offrade fä och får, och sände efter Bileam, och efter de Förstar som när honom voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Om morgonen tog Balak Bileam, och hade honom upp på Baals höjder, att han dädan af måtte se intill ändan af folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Och Bileam sade till Balak: Bygg mig här sju altare, och låt mig få hit sju stutar och sju vädrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balak gjorde som Bileam honom sade. Och både Balak och Bileam offrade, ju på hvart altare en stut och en vädur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Och Bileam sade till Balak: Gack till ditt bränneoffer; och jag vill gå bort; om tilläfventyrs Herren kan komma emot mig, och undervisa mig hvad jag skall säga dig. Och gick åstad hasteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Och Gud kom emot Bileam. Men han sade till honom: Sju altare hafver jag tillredt, och ju på hvart altaret en stut och en vädur offrat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Och Herren gaf Bileam ordet i munnen, och sade: Gack till Balak igen, och säg alltså.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Och då han kom igen till honom, si då stod han när sitt bränneoffer, med alla de Moabiters Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Då hof han sitt tal upp, och sade: Utaf Syrien hafver Balak, de Moabiters Konung, låtit hemta mig, ifrå bergen österut: Kom och förbanna mig Jacob; kom, tala ondt emot Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Huru skall jag förbanna den Gud icke förbannar? Huru skall jag tala ondt emot den Herren intet ondt emot talar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Ty af bergshöjden ser jag honom väl, och af högarna skådar jag honom. Si, det folket varder allena boendes, och icke skall räknadt varda ibland Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Ho kan räkna Jacobs stoft, och talet på fjerdedelen af Israel? Min själ dö med de rättfärdigas död, och min ände varde såsom dessas ände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Då sade Balak till Bileam: Hvad gör du mig? Jag hafver låtit hemta dig till att förbanna mina fiendar, och si, du välsignar dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Han svarade, och sade: Skulle jag icke det hålla och tala, som Herren gifver mig i munnen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Balak sade till honom: Kom då med mig på en annan plats, dädan du hans ända ser, och dock icke allansamman ser; och förbanna mig honom der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Och tog han honom på en fri plan, uppå kullen af berget Pisga, och byggde sju altare, och offrade ju på hvart altaret en stut och en vädur;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Och sade till Balak: Gack till ditt bränneoffer; jag vill vänta derborta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Och Herren kom emot Bileam, och gaf honom ordet i hans mun, och sade: Gack till Balak igen, och säg alltså.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Och då han kom igen till honom, si, då stod han när sitt bränneoffer, med de Moabiters Förstar. Och Balak sade till honom: Hvad hafver Herren sagt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Och han hof upp sitt tal, och sade: Statt upp, Balak, och hör; fatta i öronen hvad jag säger, du Zipors son:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Gud är icke en menniska, att han kan ljuga; eller menniskobarn, att honom något kan ångra. Skulle han säga något, och icke görat? Skulle han något tala, och icke hållat?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Si, till att välsigna är jag hit hafd; jag välsignar, och kan icke omvändat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Man ser ingen mödo i Jacob, och intet arbete i Israel; Herren hans Gud är när honom, och Konungens trummetning ibland honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Gud hafver fört honom utur Egypten; hans frimodighet är såsom ens enhörnings.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Ty ingen trollkarl är i Jacob, och ingen spåman i Israel. I sin tid varder man sägandes om Jacob och om Israel, hvilka under Gud gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Si, det folket varder uppståndandes såsom ett ungt lejon, och varder sig uppresandes såsom ett lejon; det skall icke lägga sig, tilldess det äter rof, och dricker deras blod, som slagne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Då sade Balak till Bileam: Du skall hvarken förbanna dem, eller välsigna dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bileam svarade, och sade till Balak: Hafver jag icke sagt dig, att allt det Herren talandes vorde, det måste jag göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Balak sade till honom: Kom, jag vill hafva dig på en annan plats; om tilläfventyrs Gudi må täckas, att du förbannar dem der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Och han tog honom upp på kullen af det berget Peor, hvilket vet åt öknena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Och Bileam sade till Balak: Bygg mig här sju altare, och låt mig få sju stutar och sju vädrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balak gjorde såsom Bileam sade, och offrade ju uppå hvart altaret en stut och en vädur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Då nu Bileam såg, att Herranom täcktes, att han skulle välsigna Israel, gick han intet, såsom tillförene, bort till att söka trolldom, utan vände sitt ansigte rätt emot öknena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Hof sin ögon upp, och såg Israel såsom de lågo efter deras slägter; och Guds Ande kom öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Och han hof upp sitt tal, och sade: Detta säger Bileam, Beors son: Detta säger den man, hvilkom ögonen öppnade äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Detta säger den som hörer Guds tal; den som dens Allsmägtigas uppenbarelse ser, hvilkom ögonen öppnade varda, när han på knä faller:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Huru skön äro din tjäll, Jacob, och din boning, Israel!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Såsom bäcker utvidga sig, såsom örtagårdar vid vatten, såsom tjäll de Herren uppsätter, såsom cedreträ vid vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Vatten skola flyta utu hans ämbar, och hans säd skall varda till ett stort vatten. Hans Konung skall varda högre än Agag, och hans rike skall upphäfva sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Gud hafver honom fört utur Egypten; hans frimodighet är såsom ens enhörnings; han skall uppfräta sina motståndare Hedningarna, och deras ben sönderkrossa, och med sina pilar sönderbråka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Han hafver sig nederlagt såsom ett lejon, och såsom ett ungt lejon. Ho vill sätta sig emot honom? Välsignad vare den som dig välsignar, och förbannad den dig förbannar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Då förgrymmade sig Balak i vrede emot Bileam, och slog händerna tillsamman, och sade till honom: Jag hafver kallat dig, att du skulle förbanna mina fiendar; och si, du hafver nu tre gånger välsignat dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Far nu hem till ditt. Jag tänkte, att jag skulle ärat dig; men Herren hafver den ärona förtagit dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Bileam svarade honom: Hafver jag ock icke talat med din sändningabåd, som du sände till mig, och sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Om Balak gåfve mig sitt hus fullt med silfver och guld, så kunde jag dock icke gå utöfver Herrans ord, antingen till att göra ondt eller godt efter mitt sinne; utan hvad som Herren sägandes vorde, det skulle jag ock säga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Och nu, si, när jag far till mitt folk, så kom, jag skall råda dig, hvad detta folk med dino folke göra skall, på yttersta tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Och han hof sitt tal upp, och sade: Detta säger Bileam, Beors son: Det säger den man, hvilkom ögonen öppnade äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Det säger den som hörer Guds tal, och den som dens Högstas kunskap hafver; den som ser dens Allsmägtigas uppenbarelse, hvilkom ögonen öppnade varda, när han på knä faller:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Jag skall få se honom, men icke nu; jag skall skåda honom, men icke när: En stjerna skall uppgå utaf Jacob, och en spira uppkomma af Israel, och skall sönderkrossa de Moabiters Förstar, och ödelägga all Seths barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Han skall intaga Edom, och Seir skall komma under sina fiendars våld, men Israel skall vinna seger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Utur Jacob varder kommandes den som råda skall, och omkullslå hvad igen är af städerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Och då han såg de Amalekiter, hof han upp sitt tal, och sade: Amalek de förste ibland Hedningarna; men på sistone blifver du platt borta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Och då han såg de Keniter, hof han upp sitt tal, och sade: Fast är din boning, och du hafver lagt ditt näste, i hällebergena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Men du, Kain, skall varda förbränd, när Assur dig fångnan bortförer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Och han hof åter upp sitt tal, och sade: Ack! ho må lefva, när Gud detta göra skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Och skepp utu Chittim skola förderfva Assur och Eber; men han skall ock förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Och Bileam stod upp, och drog sina färde, och kom igen till sitt rum; och Balak for sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Och Israel bodde i Sittim, och folket begynte bola med de Moabiters döttrar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Hvilka bödo folket till deras gudars offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Och folket åt, och tillbad deras gudar, och Israel höll sig intill BaalPeor; då förgrymmade sig Herrans vrede öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Och Herren sade till Mose: Tag alla öfverstarna för folket, och häng dem upp Herranom i solene, på det den grymme Herrans vrede måtte varda vänd ifrån Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Och Mose sade till de domare i Israel: Hvar och en dräpe sina män, som sig till BaalPeor hållit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Och si, en man utaf Israels barn kom, och hade in ibland sina bröder ena Midianitiska qvinno; och lät Mose se det, och hela menighetena af Israels barn, som greto inför dörrena af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Då Pinehas det såg, Eleazars son, Prestens Aarons sons, stod han upp utu menighetene, och tog en knif i sina hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Och gick efter den Israelitiska mannen in uti horohuset, och stack dem, både den Israelitiska mannen och qvinnona, igenom deras buk. Så vände plågan igen af Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Och i de plågone vordo dräpne fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinehas, Eleazars son, Prestens Aarons sons, hafver afvändt mina grymhet ifrån Israels barn, i det han nitisk var om mig, att jag i mitt nit icke skulle förgöra Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Derföre säger jag: Si, jag gifver honom mins frids förbund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Och han och hans säd efter honom skall hafva ett evigt Presterskaps förbund; derföre, att han för sin Gud hafver nitisk varit, och Israels barn försonat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Men den Israelitiska mannen, som slagen vardt med den Midianitiska qvinnone, het Simri, Salu son, en Förste öfver de Simeoniters fäders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Den Midianitiska qvinnan, som ock slagen vardt, het Cosbi, Zurs dotter, den en Förste var för en slägt ibland de Midianiter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Gör de Midianiter ondt, och slå dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Förty de hafva gjort eder ondt med deras list, den de eder beställt hafva med Peor, och med deras syster Cosbi, den Midianitiska Förstans dotter, hvilken slagen vardt, på plågones dag, för Peors skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Och skedde efter denna plågona, att Herren talade med Mose och Eleazar, Prestens Aarons son, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Tag summona af hela menighetene af Israels barn, ifrå tjugu år och derutöfver, efter deras fäders hus, alla de som förmå draga i här i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Och Mose, samt med Eleazar Prestenom, talade på de Moabiters mark, vid Jordan in mot Jericho,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Med dem, som tjugu åra gamle voro, och derutöfver, såsom Herren hade budit Mose och Israels barnom, som utur Egypti land dragne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, den förstfödde Israels son. Rubens barn voro: Hanoch, af hvilkom de Hanochiters slägt kommer: Pallu, af hvilkom de Palliters slägt kommer:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Hezron, af hvilkom de Hezroniters slägt kommer: Charmi, af hvilkom de Charmiters slägt kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Dessa äro Rubens slägter; och deras tal var tre och fyratio tusend, sjuhundrad och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Men Pallu barn voro: Eliab.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Och Eliabs barn voro: Remuel; och Dathan, och Abiram. Desse äro Dathan och Abiram, myndige män i den menighetene, som satte sig upp emot Mose och Aaron uti Korahs parti, då de satte sig upp emot Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Och jorden öppnade sin mun, och uppsvalg dem med Korah, då det partiet blefvo döde, och elden förtärde tuhundrad och femtio män; och voro till ett tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Men Korahs barn blefvo icke döde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Simeons barn uti deras slägter voro: Nemuel, af honom kommer de Nemueliters slägt: Jamin, af honom kommer de Jaminiters slägt: Jachin, af honom kommer de Jachiniters slägt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Serah, af honom kommer de Serahiters slägt: Saul, af honom kommer de Sauliters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Dessa äro Simeons slägter, tu och tjugu tusend, och tuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gads barn uti deras slägter voro: Zephon, af honom kommer de Zephoniters slägt: Haggi, af honom kommer de Haggiters slägt: Suni, af honom kommer de Suniters slägt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Osni, af honom kommer de Osniters slägt: Eri, af honom kommer de Eriters slägt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arod, af honom kommer de Aroditers slägt: Areli, af honom kommer de Areliters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Dessa äro Gads barnas slägter: deras tal fyratiotusend och femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Juda barn: Er och Onan, hvilke både blefvo döde i Canaans lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Och voro Juda barn i deras slägter: Sela, af honom kommer de Selaniters slägt: Perez, af honom kommer de Pereziters slägt: Serah, af honom kommer de Serahiters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Men Perez barn voro: Hezron, af honom kommer de Hezroniters slägt: Hamul, af honom kommer de Hamuliters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Dessa äro Juda slägter; deras tal sex och sjutio tusend, och femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Isaschars barn i deras slägter voro: Thola, af honom kommer de Tholaiters slägt: Phuva, af honom kommer de Phuvaiters slägt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jasub, af honom kommer de Jasubiters slägt: Simron, af honom kommer de Simroniters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Dessa äro Isaschars slägter; deras tal fyra och sextio tusend, trehundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Sebulons barn i deras slägter voro: Sered, af honom kommer de Sarditers slägt: Elon, af honom kommer de Eloniters slägt: Jahleel, af honom kommer de Jahleeliters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Dessa äro Sebulons slägter; deras tal sextiotusend, och femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Josephs barn i deras slägter voro: Manasse och Ephraim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manasse barn voro: Machir, af honom kommer de Machiriters slägt: Machir födde Gilead, af honom kommer de Gileaditers slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Gileads barn äro: Jeser, af honom kommer de Jeseriters slägt: Helek, af honom kommer de Helekiters slägt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asriel, af honom kommer de Asrieliters slägt: Sichem, af honom kommer de Sichemiters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Semida, af honom kommer de Semiditers slägt: Hepher, af honom kommer de Hepheriters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Men Zelaphehad var Hephers son, och hade inga söner, utan döttrar; de heto: Mahela, Noa, Hogla, Milca och Thirza.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Dessa äro Manasse slägter; deras tal tu och femtio tusend, och sjuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Ephraims barn i deras slägter voro: Suthelah, af honom kommer de Suthelahiters slägt: Becher, af honom kommer de Becheriters slägt: Thahan, af honom kommer de Thahaniters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Men Suthelahs barn voro: Eran, af honom kommer de Eraniters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Dessa äro Ephraims barnas slägter, deras tal tu och tretio tusend, och femhundrad. Dessa äro Josephs barn i deras slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'BenJamins barn i deras slägter voro: Bela, af honom kommer de Belaiters slägt: Asbel, af honom kommer de Asbeliters slägt: Ahiram, af honom kommer de Ahiramiters slägt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Supham, af honom kommer de Suphamiters slägt: Hupham, af honom kommer de Huphamiters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Men Bela barn voro: Ard och Naaman, af dem kommer de Arditers och Naamiters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Dessa äro BenJamins barn i deras slägter; deras tal fem och fyratio tusend, och sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Dans barn i deras slägter voro: Suham, af honom kommer de Suhamiters slägt. Dessa äro Dans slägter i deras slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Och alle de Suhamiters slägte i deras tal voro fyra och sextio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Assers barn i deras slägter voro: Jimna, af honom kommer de Jimniters slägt: Jisvi, af honom kommer de Jisviters slägt: Beria, af honom kommer de Beriiters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Men Beria barn voro: Heber, af honom kommer de Heberiters slägt: Malchiel, af honom kommer de Malchieliters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Och Assers dotter het Sarah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Dessa äro Assers barnas slägter; deras tal tre och femtio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Naphthali barn i deras slägter voro: Jahzeel, af honom kommer de Jahzeeliters slägt: Guni, af honom kommer de Guniters slägt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jezer, af honom kommer de Jezeriters slägt: Sillem, af honom kommer de Sillemiters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Dessa äro Naphthali slägter i deras slägter: deras tal fem och fyratio tusend, och fyrahundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Detta är summan af Israels barn, sex gånger hundradetusend, ett tusend, sjuhundrad och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Dessom skall du utskifta landet till arfs, efter namnens tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Mångom skall du gifva mycket till arfs, och fåm litet; hvarjom och enom skall man gifva efter deras tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Dock skall man skifta landet med lott; efter deras faders slägters namn skola de arf taga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Ty efter lotten skall du utskifta dem arfvet, emellan de många och de få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Och detta är summan af de Leviter uti deras slägter: Gerson, af hvilkom de Gersoniters slägt: Kehat, af hvilkom de Kehatiters slägt: Merari, af hvilkom de Merariters slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Dessa äro Levi slägter: De Libniters slägt, de Hebroniters slägt, de Maheliters slägt, de Musiters slägt, de Korahiters slägt; men Kehat födde Amram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Och Amrams hustru het Jochebed, Levi dotter, den honom född var uti Egypten; och hon födde Amram, Aaron och Mose, och deras syster MirJam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Men af Aaron vardt född Nadab, Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Men Nadab och Abihu blefvo döde, då de offrade främmande eld för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Och deras tal var tre och tjugu tusend, allt mankön ifrå en månad och derutöfver; ty de vordo icke räknade ibland Israels barn; förty man gaf dem icke arf ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Detta är summan af Israels barn, som Mose och Presten Eleazar talde på de Moabiters mark vid Jordan, in mot Jericho;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Ibland hvilka var ingen utaf den summo, då Mose och Presten Aaron talde Israels barn uti Sinai öken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Förty Herren hade sagt dem, att de skulle döden dö i öknene. Och ingen blef qvar, utan Caleb, Jephunne son, och Josua, Nuns son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Och Zelaphehads döttrar, Hephers sons, Gileads sons, Machirs sons, Manasse sons, utaf Manasse slägt, Josephs sons, benämnda Mahela, Noa, Hogla, Milca och Thirza, kommo fram;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Och de trädde för Mose, och för Presten Eleazar, och för Förstarna, och hela menighetena, inför dörrena af vittnesbördsens tabernakel, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Vår fader är döder i öknene, och han var icke med i den menighetene, som uppsatte sig emot Herran i Korahs upplopp; utan är i sine synd död blefven, och hade inga söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Hvi skall då vår faders namn borto blifva utu hans slägt, ändock att han ingen son hade? Gifver oss ock arfvegods ibland vår faders bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mose förde deras sak inför Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Och Herren sade till honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Zelaphehads döttrar hafva rätt sagt; du skall ock gifva dem arfvegods med deras faders bröder, och skall deras faders arf vända dem till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Och säg Israels barnom: Om någor dör och hafver inga söner, så skolen I hans arf gifva hans döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Hafver han inga döttrar, skolen I gifva det hans bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Hafver han inga bröder, så skolen I gifva det hans faderbroder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Hafver han icke faderbroder, skolen I gifva det hans nästa fränder, som honom skylde äro i hans slägt, att de taga det in. Det skall vara Israels barnom för en lag och rätt, såsom Herren budit hafver Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Och Herren sade till Mose: Stig upp på berget Abarim, och bese landet, som jag Israels barn gifva skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Och när du det sett hafver, skall du samka dig till ditt folk, såsom din broder Aaron samkad är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Efter det I min ord olydige voren uti den öknene Zin, öfver menighetenes träto, då I mig helga skullen genom vattnet för dem. Det är det trätovattnet i Kades uti den öknene Zin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Och Mose talade med Herranom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Herren Gud öfver allt lefvande kött sätte en man öfver menighetena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Som för dem ut och in går, och förer dem ut och in, att Herrans menighet icke skall vara såsom får utan herda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Och Herren sade till Mose: Tag Josua till dig, Nuns son, hvilken en man är, der Anden uti är, och lägg dina händer på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Och haf honom fram för Presten Eleazar, och för hela menighetena; och bjud honom för deras ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Och lägg dina härlighet uppå honom, att hela menigheten af Israels barn är honom lydig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Och han skall gå fram för Presten Eleazar; han skall rådfråga för honom genom Ljusens sätt inför Herranom. Efter hans mun skola ut och in gå, både han och all Israels barn med honom, och hela menigheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Mose gjorde såsom Herren honom böd; och tog Josua, och ställde honom fram för Presten Eleazar, och för hela menighetena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Och lade sina hand uppå honom, och böd honom, såsom Herren med Mose talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Bjud Israels barnom, och säg till dem: Mitt bröds offer, hvilket mitt offer är till en söt lukt, skolen I hålla i sinom tid, så att I mig det offren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Och säg till dem: Dessa äro de offer, som I offra skolen Herranom: årsgamla lamb, de som utan vank äro, dagliga tu till dagligit bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Ett lamb om morgonen, det andra om aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Dertill tiondeparten af ett epha semlomjöl till spisoffer, blandadt med oljo, den stött är, en fjerdepart af ett hin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Det är ett dagligit bränneoffer, det I uppå Sinai berg offraden, till en söt lukt af ett offer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Dertill dess drickoffer, ju till hvart lambet en fjerdedel af ett hin; och det skall offradt varda i helgedomenom, obemängdt Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Det andra lambet skall du göra om aftonen, såsom spisoffret om morgonen, och dess drickoffer till en söt lukts offer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Men om Sabbathsdagen tu årsgamla lamb utan vank, och två tiungar af semlomjöl till spisoffer, blandadt med oljo, och dess drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Det är hvars Sabbathens bränneoffer, utöfver det dagliga bränneoffret, med sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Men på första dagen i edra månader skolen I offra Herranom ett bränneoffer, två unga stutar, en vädur, sju årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Och ju tre tiungar semlomjöl till spisoffer, blandadt med oljo, till en stut, och två tiungar semlomjöl till spisoffer, blandadt med oljo, till en vädur;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Och ju en tiung semlomjöl till spisoffer, med oljo blandadt, till ett lamb; det är bränneoffret till en söt lukt, ett offer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Och deras drickoffer skall vara, ett halft hin vin till stuten, en tredjedel af ett hin till väduren, en fjerdedel af ett hin till lambet; det är bränneoffret till hvar månad om året.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Dertill skall man göra en getabock till ett syndoffer Herranom, öfver det dagliga bränneoffret, och dess drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Men på fjortonde dagenom i första månaden är Passah Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Och uppå femtonde dagenom i samma månaden är högtid; i sju dagar skall man äta osyradt bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Den förste dagen skall kallas helig, att I sammankommen; intet tjenstearbete skolen I göra deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Och skolen I göra Herranom bränneoffer, två unga stutar, en vädur, sju årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Med deras spisoffer, tre tiungar semlomjöl, blandadt med oljo, till hvar stuten, och två tiungar till väduren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Och ju en tiung till hvart af de sju lamben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Dertill en bock till syndoffer, på det I skolen försonade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Och det skolen I göra om morgonen, förutan det bränneoffret, som ett dagligit bränneoffer är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Efter detta sättet skolen I hvar dag i de sju dagar offra bröd till en söt lukts offer Herranom, till det dagliga bränneoffret, dertill dess drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Och den sjunde dagen skall kallas helig ibland eder, att I sammankommen; intet tjenstearbete skolen I göra deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Och förstlingens dag, då I offren det nya spisoffret Herranom, när edra veckor äro framledna, skall helig kallas, att I sammankommen; intet tjenstearbete skolen I göra deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Och skolen I göra Herranom bränneoffer till en söt lukt, två unga stutar, en vädur, sju årsgamla lamb;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Med deras spisoffer, tre tiungar semlomjöl, blandadt med oljo, till hvar stuten, två tiungar till väduren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Och ju en tiung till hvart och ett af de sju lamben;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Och en getabock till att försona eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Detta skolen I göra, förutan det dagliga bränneoffret med sitt spisoffer; utan vank skall det vara; dertill deras drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Och den förste dagen i sjunde månadenom skall ibland eder kallas helig, att I sammankommen; intet tjenstearbete skolen I göra deruppå; det är eder trummetandes dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Och I skolen göra bränneoffer till en söt lukt Herranom, en ungan stut, en vädur, sju årsgamla lamb utan vank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Dertill deras spisoffer, tre tiungar semlomjöl, blandadt med oljo, till stuten, två tiungar till väduren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'En tiung på hvart och ett af de sju lamben;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Och en getabock till syndoffer, till att försona eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Förutan månadens bränneoffer, och dess spisoffer, och förutan det dagliga bränneoffret med dess spisoffer, och med deras drickoffer, efter deras sätt, till en söt lukt; det är ett offer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Den tionde dagen i denna sjunde månadenom skall ock när eder kallas helig, att I sammankommen; och I skolen späka edra kroppar, och intet arbete deruppå göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Utan offra bränneoffer Herranom till en söt lukt, en ungan stut, en vädur, sju årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Med deras spisoffer, tre tiungar semlomjöl, blandade med oljo, till stuten, två tiungar till väduren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'Och en tiung på hvart och ett af de sju lamben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Dertill en getabock till syndoffer, förutan försoningens syndoffer, och det dagliga bränneoffret med sitt spisoffer, och med deras drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Den femtonde dagen i den sjunde månaden skall kallas helig när eder, att I sammankommen; intet tjenstearbete skolen I göra deruppå, och I skolen hålla Herranom helg i sju dagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Och skolen göra bränneoffer till en söt lukts offer Herranom, tretton unga stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Med deras spisoffer, tre tiungar semlomjöl, blandadt med oljo, till hvar och en af de tretton stutar, två tiungar uppå hvar väduren af de två;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'Och en tiung uppå hvart och ett af de fjorton lamben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret med sitt spisoffer och sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'På den andra dagen, tolf unga stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret med sitt spisoffer, och med deras drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'På tredje dagen, ellofva stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer och sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'På fjerde dagen, tio stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret med sitt spisoffer, och sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'På femte dagen, nio stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer, och sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'På sjette dagen, åtta stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer, och sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'På sjunde dagen sju stutar, två vädrar, fjorton årsgamla lamb utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Med deras spisoffer och drickoffer, till stutarna, till vädrarna, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Dertill en getabock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer, och sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'På den åttonde skall vara församlingenes dag; intet tjenstearbete skolen I göra deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Och skolen offra bränneoffer till en söt lukts offer Herranom; en stut, en vädur, sju årsgamla lamb, utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Med deras spisoffer och drickoffer, till stuten, till väduren, och till lamben, i deras tal efter sättet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Dertill en bock till syndoffer, förutan det dagliga bränneoffret, med sitt spisoffer och sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Detta skolen I göra Herranom i edra högtider, undantagno det I lofven och friviljoge gifven till bränneoffer, spisoffer, drickoffer och tackoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Och Mose sade Israels barnom allt det Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Och Mose talade med de Förstar i slägterna af Israels barn, och sade: Detta är det som Herren budit hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Om någor gör Herranom ett löfte, eller svär honom en ed, så att han förpligtar sina själ; han skall icke göra sin ord omyndig, utan göra allt det af hans mun utgånget är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Om en qvinna gör Herranom ett löfte, och förpligtar sig, medan hon är i sins faders huse och i sin pigodom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Och hennes löfte om förpligtelse, som hon gör öfver sina själ, kommer för hennes fader, och han tiger dertill; så gäller allt hennes löfte, och all hennes bepligtelse, som hon sig med öfver sina själ förpligtat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Men om hennes fader säger der nej till, på den dagen han det hörer; så gäller intet löfte eller bepligtelse, der hon sig med öfver sina själ förpligtat hafver; och Herren skall vara henne nådelig, efter fadren hafver det nekat henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Hafver hon man, och hafver ett löfte uppå sig, eller af hennes mun utgår en bepligtelse öfver hennes själ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Och mannen hörer det, och tiger den dagen stilla; så gäller hennes löfte och bepligtelse, med hvilko hon sig öfver sina själ förpligtat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Men om hennes man säger der nej till, på den dagen han det hörer; så är hennes löfte löst, som hon hafver på sig, och den bepligtelsen, som af hennes mun öfver hennes själ utgången är; och Herren skall vara henne nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Enes enkos löfte, och enes, som bortdrifven är, allt det hon förpligtar sig öfver sina själ, det gäller öfver henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Om någons mans tjenstehjon lofvar, eller sig med en ed förpligtar öfver sina själ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Och husbonden hörer det, och tiger dertill, och säger der intet nej till; så gäller allt det löftet, och allt det han sig förpligtat hafver öfver sina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Om husbonden gör det löst, den dagen, då han det hörer; så gäller det intet, hvad utaf hans mun gånget är, och han lofvat, eller sig förpligtat hafver öfver sina själ; förty husbonden hafver gjort det löst; och Herren skall vara honom nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Och allt löfte, och eder, som bepligta till att späka kroppen, må husbonden vidmagthålla, eller omintetgöra alltså.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Om han tiger dertill ifrå den ena dagen till den andra; så gifver han allo hans löfte och förpligtelse magt, som han hafver på sig; derföre, att han hafver tegat, på den dagen, då han hörde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Om han efteråt ryggar det, sedan han det hört hafver, så skall han bära missgerningena. Desse äro de stadgar, som Herren hafver budit Mose emellan man och hustru, emellan fader och dotter, medan hon en piga är i sins faders huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Hämna Israels barn öfver de Midianiter, att du sedan församkar dig till ditt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Så talade Mose med folket, och sade: Väpner män af eder till härs emot de Midianiter, att de hämnas Herran öfver de Midianiter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Utu hvart slägte ett tusend, så att I skicken i hären af alla Israels slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Och de togo af Israels tusender, ju tusende af hvart slägtet, tolftusende väpnade till härs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Och Mose skickade dem med Pinehas, Prestens Eleazars son, i här, och de helga tygen, och de klangtrummeter i hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Och de förde hären emot de Midianiter, såsom Herren hade budit Mose; och slogo ihjäl allt det som mankön var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Dertill slogo de de Midianiters Konungar, med deras slagna, nämliga Evi, Rekem, Zur, Hur och Reba, de fem Midianiters Konungar; Bileam, Beors son, slogo de ock med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Och Israels barn togo till fångar de Midianiters qvinnor med deras barn; all deras boskap, alla deras håfvor, och allt deras gods skinnade de;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Och uppbrände med eld alla deras städer, deras boningar och alla borger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Och togo allt rof, och allt det till tagandes var, både menniskor och boskap;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Och hade det till Mose, och till Presten Eleazar, och till menighetena af Israels barn, nämliga de fångar och den tagna boskapen, och det skinnade godset, uti lägret på de Moabiters mark, som ligger vid Jordan emot Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Och Mose och Eleazar Presten, och alle Förstarna för menighetene, gingo emot dem ut för lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Och Mose vardt vred på härens höfvitsmän, som höfvitsmän voro öfver tusende, och öfver hundrade, och kommo utu hären och stridene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Och sade till dem: Hafven I låtit alla qvinnor lefva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Si, hafva icke de förvändt Israels barn, genom Bileams råd, till att synda emot Herran på Peor; och en plåga öfvergick Herrans menighet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Så slår nu ihjäl allt det som mankön är ibland barnen, och alla de qvinnor, som man känt och när legat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Men all pigobarn, som icke ännu man känt, eller när legat hafva, dem låter för eder lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Och ligger utanför lägret i sju dagar, alle som någon slagit, eller den slagen var vederkommit hafven, på det I skolen rena eder på tredje och sjunde dagen; samt med dem som I till fångar gripit hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Och all kläder, och all tyg af skinn, och allt skinnverk, och all träkäril skolen I skär göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Och Presten Eleazar sade till krigsfolket, som i stridene varit hade: Detta är lagen, som Herren hafver budit Mose:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Guld, silfver, koppar, jern, tenn och bly;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Och allt det som eld lider, skolen I gå låta genom eld, och rena det, att det med stänkevattnena skärt varder; men allt det som icke lider eld, skolen I låta gå genom vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Och skolen två eder kläder på sjunde dagen, så varden I rene; sedan skolen I komma i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Tag summona af fångarnas rof, både af menniskor och af boskap, du och Eleazar Presten, och de öfverste fäderna i menighetene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Och gif dem hälftena, som utgingo i hären, och stridt hafva, och andra hälftena menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Och du skall häfoffra Herranom af stridsmännernas del, som i hären voro, ju af femhundrade ena själ, både i menniskor, fä, åsnar och får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Af deras hälfte skall du taga det, och få det Prestenom Eleazar, till att häfoffra det Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Men af den hälften, som Israels barn tillkommer, skall du ju af femtio taga ett stycke, både af menniskor, fä, åsnar och får, och af allom fänad, och skall gifva det Leviterna, som taga vara på Herrans tabernakels vakt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Och Mose, och Eleazar Presten, gjorde såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Och det öfriga bytet, som krigsfolket röfvat hade, var sexhundradetusend, fem och sjutio tusend får;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'Tu och sjutio tusend nöt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'Ett och sextio tusend åsnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Och qvinnfolk, som icke hade känt man eller när legat, tu och tretio tusend själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Och den hälften, som dem tillkom, som i stridene varit hade, var i talet trehundradetusend, sju och tretio tusend, och femhundrade får;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Deraf vordo Herranom sexhundrade fem och sjutio får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Item sex och tretio tusend nöt; deraf vordo Herranom tu och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Item tretiotusend och femhundrade åsnar; deraf vordo Herranom en och sextio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Item menniskors själar, sextontusend själar; deraf vordo Herranom två och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Och Mose fick det Herrans häfoffret Prestenom Eleazar, såsom Herren honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Men den andra hälften, som Mose Israels barnom tillbytt hade ifrå krigsmännerna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'Nämliga den hälften, som menighetene tillkom, var ock trehundradetusend, sju och tretio tusend, femhundrade får;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Sex och tretio tusend nöt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Tretiotusend och femhundrade åsnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'Och sextontusend menniskors själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Och Mose tog af denna hälftene, som Israels barnas var, ju ett stycke af femtio, både af fänaden och af menniskor, och fick det Leviterna, som togo vara på Herrans tabernakels vakt; såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Och de som höfvitsmännerna voro öfver de tusend i krigsfolket, nämliga öfver tusend, och öfver hundrade, gingo fram till Mose;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Och de sade till honom: Dine tjenare hafva tagit summona af krigsfolket, som under våra händer varit hafva, och der fattas icke en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Derföre bäre vi Herranom gåfvor, hvad som hvar och en funnit hafver af gyldene tyg, kedjor, armsmide, ringar, örnaringar och spann, att våra själar måga varda försonada för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Och Mose med Prestenom Eleazar tog af dem guldet i allahanda tyg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Och allt gulds häfoffer, som de Herranom häfoffrade, var sextontusend, sjuhundrade och femtio siklar, af höfvitsmännerna öfver tusend, och öfver hundrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Förty krigsfolket hade röfvat hvar och en för sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Och Mose med Prestenom Eleazar tog guldet af höfvitsmännerna öfver tusend, och öfver hundrade, och båro det in uti vittnesbördsens tabernakel, Israels barnom till en åminnelse för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Rubens barn och Gads barn hade ganska mycken boskap; och de sågo det landet Jaeser och Gilead, att det var beqvämt rum till att föda boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Så kommo de, och talade till Mose, och till Presten Eleazar, och till Förstarna i menighetene:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Det landet Ataroth, Dibon, Jaeser, Nimra, Hesbon, Eleale, Sebam, Nebo och Beon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Som Herren slagit hade för Israels menighet, är beqvämt till boskap, och vi dine tjenare hafve boskap;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Och sade ytterligare: Hafve vi funnit nåde för dig, så gif dinom tjenarom detta landet till eget; och så fare vi intet öfver Jordanen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mose sade till dem: Skulle edra bröder draga i strid, och I skullen blifva här?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Hvi omvänden I Israels barnas hjerta, att de icke skola draga utöfver, uti det land, som Herren dem gifva skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Alltså gjorde ock edra fäder, då jag sände dem ifrå KadesBarnea, till att skåda landet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Och då de voro komne ditupp, allt intill den bäcken Escol, och sågo landet, omvände de Israels barnas hjerta, så att de icke ville in uti landet, som Herren dem gifva ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Och Herrans vrede förgrymmade sig på den tiden, och han svor, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Detta folket, som utur Egypten draget är, ifrå tjugu år och deröfver, skola ju icke se det landet, som jag Abraham, Isaac och Jacob svorit hafver; derföre, att de mig icke troliga efterföljt hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Undantagnom Caleb, Jephunne son, den Kenisiten, och Josua, Nuns son; ty de hafva Herranom troliga efterföljt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Så förgrymmade sig Herrans vrede öfver Israel, och lät fara dem hit och dit i öknene i fyratio år, intilldess en ände vardt på allt det slägtet, som syndat hade emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Och si, I ären inträdde uti edra fäders stad, att syndarena skola vara desto flere, och att I också Herrans vrede och grymhet ännu föröka skullen emot Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Förty om I vänden eder ifrå honom, så varder han ock ännu länger låtandes eder blifva i öknene, och så förderfven I allt detta folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Då gingo de fram, och sade: Vi vilje allenast bygga här fägårdar för vår boskap, och städer för vår barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Men vi vilje väpna oss, och gå framför Israels barn, intilldess vi före dem till deras rum; vår barn skola blifva uti de fasta städer för landsens inbyggares skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Vi vilje icke vända hemåt, intilldess Israels barn intaga hvar sitt arf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Ty vi vilje intet ärfva med dem på hinsidan Jordan; utan vårt arfvegods må vara på denna sidone Jordan österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Mose sade till dem: När I det göra viljen, att I rusten eder till strid för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'Så drager öfver Jordan för Herranom, hvilken som helst ibland eder väpnader är, tilldess I utdrifven hans fiendar ifrå hans ansigte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'Och landet blifver undergifvet för Herranom; sedan skolen I vända om, och oskyldige vara för Herranom, och för Israel; och skolen så hafva detta landet till eget för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Men om I det icke göra viljen, si, så varden I syndande emot Herran, och varden edra synder förnimmande, då de begripa eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Så bygger nu städer för edor barn, och fägårdar för edor boskap; och görer som I sagt hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Gads barn och Rubens barn sade till Mose: Dine tjenare skola göra såsom min herre budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Vår barn, hustrur, håfvor, och all vår boskap skola blifva uti Gileads städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Men vi dine tjenare vilje alle väpnade draga i stridena för Herranom, såsom min herre sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Då böd Mose för deras skull Prestenom Eleazar, och Josua, Nuns son, och de öfversta fäderna i Israels barnas slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Och sade till dem: Om Gads barn och Rubens barn draga öfver Jordan med eder, alle väpnade till strid för Herranom, och landet blifver eder allt undergifvet; så gifver dem det landet Gilead till eget;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Men draga de icke med eder väpnade, så skola de ärfva med eder i Canaans lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Gads barn och Rubens barn svarade, och sade: Såsom Herren talat hafver till dina tjenare, så vilje vi göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Vi vilje draga väpnade för Herranom in uti Canaans land, och besitta vårt arfvegods på desso sidone Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Så gaf Mose Gads barnom, och Rubens barnom, och den halfva slägtene Manasse, Josephs sons, Sihons rike, de Amoreers Konungs, och Ogs rike, Konungens i Basan, landet och städerna i alla gränsor, deromkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Då byggde Gads barn Dibon, Ataroth, Aroer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atroth, Sophan, Jaeser, Jogbeha,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bethnimra och Betharan, bevarada städer och fägårdar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Rubens barn byggde Hesbon, Eleale, Kiriathaim,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo, BaalMeon; och förvände namnen; och Sibma; och gåfvo de städer namn, som de byggde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Och Machirs barn, Manasse sons, drogo till Gilead, och vunno den, och fördrefvo de Amoreer, som derinne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Då gaf Mose Machir, Manasse sone, Gilead; och han bodde deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Men Jair, Manasse son, drog bort, och vann deras byar, och kallade dem HavothJair.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nobah drog åstad, och vann Kenath med dess döttrar, och kallade dem Nobah efter sitt namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Detta är Israels barnas resande, hvilke utur Egypti land dragne voro i deras härar, genom Mose och Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Och Mose beskref deras utresande, såsom de drogo efter Herrans befallning; och äro desse de resande som de reste:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'De drogo ut ifrå Rameses på femtonde dagen i den första månadenom, på annandag Påska, genom höga hand, i alla de Egyptiers åsyn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Då de Egyptier begrofvo sina förstfödingar, som Herren ibland dem slagit hade; ty Herren hade ock gjort dom öfver deras gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'När de dragne voro ifrå Rameses, lägrade de sig i Succoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Och de drogo ut ifrå Succoth, och lägrade sig i Etham, hvilket ligger vid ändan på öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Ifrån Etham drogo de ut, och blefvo i den dalen Hyroth, hvilken ligger emot BaalZephon; och lägrade sig inför Migdol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Ifrå Hyroth drogo de ut, och gingo midt igenom hafvet in uti öknena, och reste tre dagsresor in uti Ethams öken, och lägrade sig i Marah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Ifrå Marah drogo de ut, och kommo till Elim; der voro tolf vattubrunnar och sjutio palmträd; och lägrade sig der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Ifrån Elim drogo de ut, och lägrade sig invid röda hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Ifrå röda hafvet drogo de ut, och lägrade sig i den öknene Sin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Ifrå den öknene Sin drogo de ut, och lägrade sig i Daphka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Ifrå Daphka drogo de ut, och lägrade sig i Alus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Ifrån Alus drogo de ut, och lägrade sig i Rephidim; der hade folket intet vatten att dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Ifrå Rephidim drogo de ut, och lägrade sig uti den öknene Sinai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Ifrå Sinai drogo de ut, och lägrade sig i de Lustgrifter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Ifrå de Lustgrifter drogo de ut, och lägrade sig i Hazeroth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Ifrå Hazeroth drogo de ut, och lägrade sig i Rithma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Ifrå Rithma drogo de ut, och lägrade sig i RimmonParez.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Ifrå RimmonParez drogo de ut, och lägrade sig i Libna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Ifrå Libna drogo de ut, och lägrade sig i Rissa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Ifrå Rissa drogo de ut, och lägrade sig i Kehelatha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Ifrå Kehelatha drogo de ut, och lägrade sig på berget Sapher.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Ifrå berget Sapher drogo de ut, och lägrade sig i Harada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Ifrå Harada drogo de ut, och lägrade sig i Makheloth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Ifrå Makheloth drogo de ut, och lägrade sig i Thahath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Ifrå Thahath drogo de ut, och lägrade sig i Tharah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Ifrå Tharah drogo de ut, och lägrade sig i Mitka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Ifrå Mitka drogo de ut, och lägrade sig i Hasmona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Ifrå Hasmona drogo de ut, och lägrade sig i Moseroth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Ifrå Moseroth drogo de ut, och lägrade sig i BeneJaakan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Ifrå BeneJaakan drogo de ut, och lägrade sig i HorGidgad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Ifrå HorGidgad drogo de ut, och lägrade sig i Jotbatha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Ifrå Jotbatha drogo de ut, och lägrade sig i Abrona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Ifrån Abrona drogo de ut, och lägrade sig i EzionGaber.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Ifrån EzionGaber drogo de ut, och lägrade sig i den öknene Zin, det är Kades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Ifrå Kades drogo de ut, och lägrade sig på det berget Hor, som är på gränsone vid Edoms land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Der gick Presten Aaron upp på berget Hor, efter Herrans befallning, och blef der död på fyrationde årena, sedan Israels barn voro utdragne utur Egypti land, på första dagen i femte månadenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Då han var hundrade tre och tjugu åra gammal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Och Arad, de Cananeers Konung, som bodde söderut i Canaans lande, hörde att Israels barn kommo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Ifrå berget Hor drogo de ut, och lägrade sig i Zalmona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Ifrå Zalmona drogo de ut, och lägrade sig i Punon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Ifrå Punon drogo de ut, och lägrade sig i Oboth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Ifrån Oboth drogo de ut, och lägrade sig i Ijim vid Abarim, i de Moabiters gränso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Ifrån Ijim drogo de ut, och lägrade sig i DibonGad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Ifrå DibonGad drogo de ut, och lägrade sig i AlmonDiblathaim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Ifrån AlmonDiblathaim drogo de ut, och lägrade sig på berget Abarim emot Nebo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Ifrå berget Abarim drogo de ut, och lägrade sig på de Moabiters mark, vid Jordan in mot Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Och de lägrade sig ifrå BethJesimoth allt intill den slättena Sittim, på de Moabiters mark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Och Herren talade med Mose på de Moabiters mark, vid Jordan, in mot Jericho, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Tala med Israels barn, och säg till dem: När I öfver Jordan komne ären, in uti Canaans land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Så skolen I fördrifva alla dess inbyggare för edart ansigte, och alla deras stodar, och alla deras gjutna beläten förgöra, och alla deras höjder förderfva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Så att I tagen landet in, och bon deruti; förty eder hafver jag gifvit landet, att I skolen det intaga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Och skolen utskifta landet genom lott ibland edra slägter; dem som månge äro, skolen I mer gifva, och dem som få äro, mindre; efter som lotten faller till hvar och en, så skall han hafva det, efter edra fäders slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Om I landsens inbyggare icke fördrifven för edart ansigte, så skola de, som återlefde äro, vara eder som törne i edor ögon, och såsom spjut i edra sidor; och skola tränga eder på landena, der I uti bon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Så skall då ske, att jag så varder görandes eder, som jag emot dem göra aktade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Bjud Israels barnom, och säg till dem: När I uti Canaans land kommen, så skall det landet, som eder till arfvedel faller i Canaans lande, hafva sin landamär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Den sidan söderut skall begynna af den öknene Zin vid Edom, så att edart landamäre söderut skall vara ifrån ändanom af salthafvet, det österut ligger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Och att det landamäret skall sträcka sig ifrå sunnan uppåt intill Akrabbim, och gå igenom Zinna; och dess ända ifrå sunnan intill KadesBarnea, och räcka intill den byn Addar, och gå igenom Azmon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Och skall sträcka sig ifrån Azmon allt intill Egypti bäck; och dess ände vare i hafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Men det landamäret vesterut skall vara detta, nämliga det stora hafvet; det skall vara edart landamäre vesterut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Det landamäret norrut skall vara detta: I skolen mäta ifrå stora hafvet allt intill berget Hor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Och ifrå berget Hor mäta intilldess man kommer till Hamath; så att dess utgång skall vara det landamäret Zedada;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Och samma landamärens ände inåt Ziphron, och dess ände vare vid den byn Enan; det skall vara edart landamäre norrut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Och skolen mäta eder landamäret österut, ifrå den byn Enan intill Sepham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Och det landamäret gånge nederåt ifrå Sepham intill Ribla, till Ain östanefter; sedan gånge nederåt, och drage sig uppmed sidone af hafvet Cinnereth österut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Och komme neder åt Jordan, så att dess ände blifver salthafvet; det skall vara edart land med sin landamäre allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Och Mose böd Israels barnom, och sade: Detta är landet, som I skolen skifta emellan eder med lott, hvilket Herren budit hafver att gifva de nio slägter, och den halfva slägtene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Ty Rubens barnas slägte efter deras fäders hus, och Gads barnas slägte efter deras fäders hus, och den halfva slägten Manasse, hafva allaredo tagit sin del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Så hafva de två slägterna, och den halfva slägten, sin arfvedel på desso sidone Jordan in mot Jericho österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Desse äro namnen af männerna, som landet skola skifta emellan eder: Presten Eleazar, och Josua, Nuns son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Dertill skolen I taga Förstan af hvarjo slägtene, till att utskifta landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Och desse äro männernas namn: Caleb, Jephunne son, af Juda slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Semuel, Ammihuds son, af Simeons slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Elidad, Chislons son, af BenJamins slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Bucki, Jogli son, Försten för Dans barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Hanniel, Ephods son, Försten för Manasse barnas slägte, af Josephs barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Kemuel, Siphtans son, Försten för Ephraims barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Elizaphan, Parnachs son, Försten för Sebulons barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Palthiel, Assans son, Försten för Isaschars barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Ahihud, Selomi son, Försten för Assers barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Pedahel, Ammihuds son, Försten för Naphthali barnas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Desse äro de som Herren budit hafver, att de skulle utskifta Israels barnom arfvet i Canaans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Och Herren talade med Mose på de Moabiters mark, vid Jordan, in mot Jericho, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Bjud Israels barnom, att de gifva Leviterna städer utaf sitt arfvegods, der de måga uti bo; dertill förstäder omkring städerna skolen I ock gifva Leviterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Att de skola bo i städerna, och hafva sin boskap, gods och allahanda djur i förstäderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Vidden till förstäderna, som de skola gifva Leviterna, skall vara tusende alnar utifrå stadsmuren allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Så skolen I då mäta utanför staden, på den sidone österut, tutusend alnar; och på den sidone söderut, tutusend alnar; och på den sidone vesterut, tutusend alnar; och på den sidone norrut, tutusend alnar; att staden skall vara midt uti. Det skall vara deras förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Och ibland de städer, som I gifven Leviterna, skolen I gifva sex fristäder, att den som någon ihjälslår må fly derin; derutöfver skolen I ännu gifva dem två och fyratio städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Så att alle städer, som I gifven Leviterna, blifva åtta och fyratio med deras förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Och skolen gifva dem mer af dem som mycket äga ibland Israels barn, och mindre af dem som mindre äga; hvar och en, efter hans arfvedel, den honom tillskift varder, skall gifva Leviterna städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Och Herren talade med Mose, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Tala med Israels barn, och säg till dem: När I kommen öfver Jordan in uti Canaans land,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Skolen I utvälja städer, som fristäder skola vara, deruti fly må den som någon med våda ihjälslår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Och skola sådane fristäder vara ibland eder, för blodhämnarens skull, att han icke skall dö, som dråpet gjorde, intilldess han hafver ståndit till rätta inför menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Och de städer, som I gifva skolen, skola vara sex fristäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Tre skolen I gifva på desso sidone Jordan; och tre i Canaans lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Det äro de sex fristäder, både för Israels barn, och främlingom, och husmän ibland eder; att dit må fly ho som helst ena själ slår med våda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Hvilken som slår en med något jern, så att han dör, han är en mandråpare; och skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Kastar han honom med en sten, der någor kan död af varda, så att han blifver död deraf, så är han en mandråpare; och skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Slår han honom med något trä, der någor kan med dödsslagen varda, så att han dör, så är han en mandråpare; och skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Blodhämnaren skall slå mandråparen ihjäl; såsom han slagit hafver, så skall man döda honom igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Stöter han honom af hat, eller kastar något på honom med försåt, så att han dör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Eller slår honom af ovänskap med sine hand, så att han dör, så skall han döden dö, som honom slog; ty han är en mandråpare; blodhämnaren skall dräpa honom, när han råkar honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Men stöter han honom oförvarandes utan ovänskap, eller kastar något på honom, icke med försåt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Eller kastar en sten på honom oförvarandes, der man af dö kan, så att han dör, och han är icke hans ovän, och ville honom heller intet ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Så skall menigheten döma, emellan honom som slog och blodhämnaren, i denna sakene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Och menigheten skall fria mandråparen ifrå blodhämnarens hand, och låta honom komma i fristaden igen, dit han flydder var; och der skall han blifva, tilldess öfverste Presten dör, den man med den helga oljone smort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Om mandråparen går utaf sin fristads råmärke, dit han flydd är,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'Och blodhämnaren finner honom utanför hans fristads råmärke, och slår honom ihjäl; han skall för det blod intet saker vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Ty han skulle blifva i sinom fristad intill den öfversta Prestens död; och efter öfversta Prestens död åter komma till sins arfvegods land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Detta skall vara eder en rätt med edra efterkommande, i alla edra boningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Mandråparen skall man dräpa efter tvegga vittnes mun; ett vittne skall icke svara öfver en själ till döds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Och I skolen ingen försoning taga för en mandråpares själ, ty han är saker till döden; utan han skall döden dö;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Och skolen ingen försoning taga öfver den, som till fristaden flydder var, så att han igenkommer till att bo i landena, intill att Presten dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Och skämmer icke landet, der I uti bon; ty den som blodssaker är, han skämmer landet; och landet kan icke försonadt varda för det blod, som der utgjutet varder, annars utan genom hans blod, som det utgjutit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Orener icke landet, som I bon uti, der jag ock uti bor; ty jag är Herren, som bor ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Och de öfverste fäderna till Gileads barnas slägte, Machirs sons, hvilken Manasse son var, af Josephs barnas slägte, gingo fram, och talade för Mose, och för Förstarna, öfversta fäderna till Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Och sade: Käre herre, Herren hafver budit, att man skall utskifta landet Israels barnom till arfvedel genom lott; och du, min herre, hafver budit genom Herran, att man vår broders Zelaphehads arfvedel hans döttrar gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Om någor af Israels slägte tager dem till hustru, så varder vår faders arfvedel mindre, och så mycket som de hafva, kommer den slägtenes arfvedel till, dit som de komma; och så varder vår arfvedels lott förminskad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'När nu Israels barnas klangår kommer, så kommer deras arfvedel till den slägtenes arfvedel, der de äro; så varder vår faders arfvedel förminskad, så mycket som de hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Så böd Mose Israels barnom, efter Herrans befallning, och sade: Josephs barnas slägt hafver talat rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Detta är det som Herren bjuder Zelaphehads döttrar, och säger: Gifte sig hvem de vilja; allenast att de gifta sig in i sina ätt och faders slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'På det att Israels barnas arfvedel icke skall falla ifrå den ena slägten till den andra; ty hvar och en ibland Israels barn skall hänga intill sitt fädernes slägtes arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Och alla döttrar, som äga arfvedel i Israels barnas slägter, skola gifta sig enom af sins faders slägts ätt; på det hvar och en ibland Israels barn må behålla sins faders arf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Och en arfvedel icke skall falla ifrå den ena slägtene till den andra; utan hvar och en hänge intill sitt arf ibland Israels barnas slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Såsom Herren böd Mose, så gjorde Zelaphehads döttrar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Mahela, Thirza, Hogla, Milca och Noa, och gifte sig vid deras faderbroders barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Af Manasse barnas slägte, Josephs sons; alltså blef deras arfvedel vid ättena och deras faders slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Desse äro de bud och rätter, som Herren genom Mose böd Israels barnom, på de Moabiters mark, vid Jordan, in mot Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Desse äro de ord, som Mose talade till hela Israel på hinsidon Jordan i öknene, på den markene emot röda hafvet, emellan Paran och Tophel, Laban, Hazeroth och Disahab;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Ellofva dagsresor ifrå Horeb, den vägen om Seirs berg intill KadesBarnea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Och det skedde i fyrationde årena, på första dagen i den ellofte månadenom; då talade Mose med Israels barn, allt det Herren honom till dem budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Sedan att han hade slagit Sihon, de Amoreers Konung, som i Hesbon bodde; dertill Og, Konungen i Basan, som i Astaroth och i Edrei bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'På hinsidon Jordan, i de Moabiters lande, begynte Mose utlägga denna lagen, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Herren vår Gud talade med oss på Horebs berg, och sade: I hafven länge nog varit vid detta berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Vänder eder, och drager åstad, att I mån komma till de Amoreers berg, och till alla deras grannar, till mark, på berg och i dalar, söderut, och emot hafsens hamn, i Canaans lande, och till berget Libanon, allt intill den stora älfvena Phrath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Si, jag hafver gifvit eder landet, som för eder ligger; går derin, och intager det, såsom Herren edra fäder, Abraham, Isaac och Jacob, svorit hafver, att han dem, och deras säd efter dem, det gifva ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Då sade jag till eder på samma tiden: Jag förmår icke allena utstå med eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Förty Herren edar Gud hafver förökat eder, så att I på denna dag ären såsom stjernornas tal på himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Herren edra fäders Gud göre eder ännu mång tusend mer, och välsigne eder, såsom han eder sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Huru kan jag allena sådana mödo, och tunga, och trätor, draga af eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Tager utaf eder visa och förståndiga män, de som ibland edra slägter bekände äro, dem vill jag uppsätta eder för höfvitsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Då svaraden I mig, och saden: Det är en god ting, der du om talar, att du göra vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Så tog jag de yppersta af edra slägter, visa och bekända män, och satte dem öfver eder till höfvitsmän, öfver tusende, öfver hundrade, öfver femtio, öfver tio, och ämbetsmän i edra slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Och böd edra domare på samma tid, och sade: Förhörer edra bröder, och dömer rätt emellan hvar man och hans broder, och främlingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'I skolen ingen person anse i domen; utan skolen höra den litsla såsom den stora, och icke hafva försyn för någons mans person; ty domsämbetet hörer Gudi till. Om någor sak varder eder för svår, den låter komma till mig, att jag må den höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Alltså böd jag eder på den tiden allt det I göra skullen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Så drogo vi ut ifrå Horeb, och vandrade genom den hela öknena, den stor och grufvelig är, såsom I sett hafven, uppå den vägen till de Amoreers berg, såsom Herren vår Gud oss budit hade; och kommo intill KadesBarnea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Då sade jag till eder: I ären komne intill de Amoreers berg, det Herren vår Gud oss gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Si, landet före dig, hvilket Herren din Gud dig gifvit hafver! Drag ditupp, och tag det in, såsom Herren dina fäders Gud dig sagt hafver; frukta dig intet, och grufva dig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Så kommen I till mig alle, och saden: Låt oss sända några män framför oss, som bespeja oss landet, och säga oss igen, hvilken vägen vi skole draga derin, och de städer, der vi inkomma skole.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Det nöjde mig väl; och tog utaf eder tolf män, utaf hvart slägtet en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Då de samme gingo åstad, och drogo upp på berget, och kommo till den bäcken Escol, så skådade de det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Och togo landsens frukt med sig, och båro neder till oss, och bådade oss igen, och sade: Landet är godt, som Herren vår Gud oss gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Men I villen icke draga ditupp, och blefven Herrans edor Guds orde ohörsamme;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Och knorraden i edor tjäll, och saden: Herren är oss hätsk, derföre hafver han fört oss utur Egypti land, på det han skall gifva oss i de Amoreers händer, till att förgöra oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Hvad skulle vi deruppe? Våra bröder hafva förfärat vårt hjerta, och sagt: Det folket är större och högre än vi; städerna äro store och bemurade upp till himmelen; dertill hafve vi sett der Enakims barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Och jag sade till eder: Grufver eder icke, och frukter eder intet för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Herren edar Gud drager för eder, och han skall strida för eder, såsom han hafver gjort med eder i Egypten för edor ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Och i öknene, der du sett hafver, huru Herren din Gud dig burit hafver, såsom en man bär sin son, i allom dem väg, der I vandrat hafven, intilldess I till detta rummet komne ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Men I skötten der intet om, att I måtten trott Herranom edrom Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Den för eder gick, till att visa eder de rum, der I eder lägra skullen, om nattena i eld, att han skulle visa eder vägen, den I gå skullen, och om dagen i molnskyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Då nu Herren hörde edart rop, vardt han vred, och svor, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Ingen af detta onda slägtet skall få se det goda landet, som jag svorit hafver att gifva deras fäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Förutan Caleb, Jephunne son, han skall se det; honom vill jag gifva det landet, der han på stigit hafver, och hans barnom; derföre att han hafver troliga efterföljt Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Och vardt Herren vred på mig för edra skull, och sade: Du skall icke heller komma derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Men Josua, Nuns son, som din tjenare är, han skall komma derin; styrk honom; ty han skall utskifta Israel arfvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Och edor barn, om hvilka I saden: De skola blifva till ett rof; och edra söner, som på denna dag hvarken veta godt eller ondt; de skola komma derin, dem skall jag gifva det, och de skola taga det in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Men vänder I om, och drager åt öknena, den vägen åt röda hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Då svaraden I, och saden till mig: Vi hafve syndat emot Herran; vi vilje ditupp och strida, såsom Herren vår Gud oss budit hafver. Som I nu redo voren, hvar i sitt harnesk, och skullen draga upp på berget,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Sade Herren till mig: Säg dem, att de icke draga ditupp, ej heller strida; ty jag är icke med eder; att I icke varden slagne för edra fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Då jag detta sade eder, lydden I intet, och vorden Herrans ord ohörsamme, och vorden öfverdådige, och drogen upp på berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Så drogo de Amoreer ut, som på berget bodde, emot eder, och jagade eder, såsom bin göra, och slogo eder i Seir allt intill Horma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Då I nu igenkommen, och greten för Herranom, ville Herren icke höra edra röst, och böjde sin öron intet till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Så blefven I uti Kades en långan tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Då vände vi om, och drogo ut i öknena, på den vägen till röda hafvet, såsom Herren sade till mig; och drogom omkring Seirs berg, en långan tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Och Herren sade till mig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'I hafven nu nog dragit kringom detta berget; vänder eder norrut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Och bjud folkena, och säg: I skolen draga genom edra bröders Esau barnas gränsor, som bo i Seir, och de skola frukta för eder; men förvarer eder granneliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Slår icke uppå dem; ty jag skall icke gifva eder en fot bredt uti deras land; förty Esau barn hafver jag gifvit Seirs berg till att besitta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Maten skolen I köpa af dem för edra penningar, den I äten; och vattnet skolen I köpa af dem för penningar, som I dricken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Ty Herren din Gud hafver välsignat dig i alla dina händers gerningar; han hafver lagt på hjertat ditt resande genom denna stora öknena; och Herren din Gud hafver i fyratio år varit när dig, så att dig intet hafver fattats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Då vi nu ifrå våra bröder Esau barn dragne voro, som på Seirs berg bodde, på den vägen den markenes ifrån Elath och EzionGaber, vände vi om, och gingom den vägen genom de Moabiters öken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Då sade Herren till mig: Du skall ingen skada göra de Moabiter, eller slå uppå dem; ty jag vill intet gifva dig af deras land till att besitta; förty Lots barn hafver jag gifvit Ar till att besitta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'De Emim hafva i förtiden bott deruti, hvilke voro ett stort, starkt och högt folk, såsom Enakim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Man höll dem ock för Resar, såsom Enakim; och de Moabiter kalla dem ock Emim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Bodde ock i förtiden de Horiter i Seir, och Esau barn fördrefvo och förlade dem för sig, och bodde i deras stad, såsom Israel sins besittninges lande gjorde, det Herren dem gaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Så varer nu redo, och drager öfver den bäcken Sared. Och vi droge deröfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Men tiden medan vi droge ifrå KadesBarnea, intilldess vi komme öfver den bäcken Sared, var åtta och tretio år, tilldess alle stridsmän döde voro i lägrena, såsom Herren dem svorit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Dertill var ock Herrans hand emot dem, att de förgingos utu lägret, tilldess de voro åtgångne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Då alle stridsmännerna åtgångne voro, att de döde voro ibland folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Talade Herren med mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'I dag skall du draga genom de Moabiters landsändar vid Ar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Och skall komma in mot Ammons barn, dem skall du ingen skada göra, eller slå på dem; ty jag vill icke gifva dig Ammons barnas land till att besitta; förty jag hafver gifvit det Lots barnom till att besitta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Det hafver ock räknadt varit för Resars land; och hafva desslikes i förtiden Resar bott derinne. Och de Ammoniter kalla dem Samsummim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'De voro ett stort, starkt och högt folk, såsom Enakim; och Herren förgjorde dem för dem, och lät dem besitta dem, så att de skulle bo i deras stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Såsom han gjort hade med Esau barn, som på Seirs berg bo, då han förgjorde för dem de Horiter, och lät dem besitta dem, så att de hafva bott i deras stad, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Och de Caphthorim drogo utu Caphthor, och förgjorde de Avim, som bodde i Hazerim, allt intill Gaza, och bodde i deras stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Varer redo, och drager ut, och går öfver den bäcken vid Arnon. Si, jag hafver gifvit i dina händer Sihon, de Amoreers Konung i Hesbon, med hans land; begynn att intaga det, och strid emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'I dag vill jag begynna, att all folk under himmelen skola frukta och förskräckas för dig, så att, när de höra om dig, skola de bäfva och sorg hafva för din tillkommelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Då sände jag båd utaf öknene östanefter, till Sihon, Konungen i Hesbon, med fridsam ord, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Jag vill draga genom ditt land, och såsom vägen löper, så vill jag draga; jag vill icke vika antingen på den högra eller den venstra sidona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Mat skall du sälja mig för penningar, att jag äter; och vatten skall du sälja mig för penningar, att jag dricker; jag vill allenast till fot gå derigenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Såsom Esau barn mig gjort hafva, som bo i Seir, och de Moabiter, som bo i Ar; tilldess jag må komma öfver Jordan, uti det landet, som Herren vår Gud oss gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Men Sihon, Konungen i Hesbon, ville icke att vi skulle draga derigenom; ty Herren din Gud förhärde hans sinne, och förstockade hans hjerta, på det han skulle gifva honom i dina händer, såsom du nu ser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Och Herren sade till mig: Si, jag hafver begynt att gifva för dig Sihon och hans land; begynn till att intaga och besitta hans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Och Sihon drog ut emot oss med allt sitt folk till strid, till Jahza.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Men Herren vår Gud gaf honom för oss, att vi slogo honom med hans barn, och allt hans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Så vunne vi på samma tiden alla hans städer, och tillspillogåfvom alla städer, både män, qvinnor och barn, och lätom ingen igenblifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Utan boskapen toge vi för oss, och det byte af städerna, som vi vunne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Ifrån Aroer, som ligger på strandene utmed den bäcken vid Arnon, och ifrå den staden i dalenom allt intill Gilead, ingen stad var, som sig kunde beskydda för oss; Herren vår Gud gaf alltsamman för oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Utan till Ammons barnas land kom du icke, eller till något det som var vid den bäcken Jabbok, eller till de städer på bergena, eller till något det Herren vår Gud oss förbudit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Och vi vände om, och drogo upp, den vägen till Basan. Och Og, Konungen i Basan, drog ut emot oss med allt sitt folk, till att strida vid Edrei.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Men Herren sade till mig: Frukta dig intet för honom; ty jag hafver gifvit honom i dina händer, och allt hans folk med hans land, och du skall göra med honom, såsom du gjorde med Sihon, de Amoreers Konung, den i Hesbon satt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Alltså gaf Herren vår Gud ock Konung Og i Basan i våra händer, med allt hans folk, så att vi sloge honom, tilldess honom intet igenblef.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'På samma tid vunne vi alla hans städer, och var ingen stad den vi honom icke aftogom; sextio städer, hela den ängden Argob i Ogs rike, som var i Basan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Alle desse städer voro faste med höga murar, portar och bommar, förutan andra ganska många små städer, som ingen mur hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Och gåfvom dem tillspillo, såsom vi, med Sihon, Konungenom i Hesbon, gjort hade; alla städer gåfve vi tillspillo, både med män, qvinnor och barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Men allan boskapen, och rofvet af städerna toge vi för oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Alltså toge vi i den tiden landet utu de två Amoreers Konungars händer på hinsidon Jordan, ifrå den bäcken vid Arnon, allt intill det berget Hermon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'Hvilket de Sidonier Sirion kalla; men de Amoreer kalla det Senir;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Alla de städer på slättene, och hela Gilead, och hela Basan, allt intill Salcha och Edrei, som äro städer i Ogs rike i Basan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Ty allena Konung Og i Basan var ännu igen utaf de Resar. Si, hans säng af jern är här i Rabbath, som hörer Ammons barnom till, nio alnar lång, och fyra alnar bred, efter ens mans armbåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Så toge vi då landet in på den tiden, ifrån Aroer, som ligger när bäcken vid Arnon; och halfva landet af Gileads berg, med dess städer, gaf jag de Rubeniter och Gaditer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Men det öfver var i Gilead, och hela Basan af Ogs rike, gaf jag den halfva slägtene Manasse; den hela ängden Argob med hela Basan, som kallas de Resars land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, Manasse son, fick den hela ängden Argob, allt intill Gessuri och Maachathi landsändar; och kallade Basan efter sitt namn, HavothJair, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Men Machir gaf jag Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Och de Rubeniter och Gaditer gaf jag en del af Gilead, allt intill bäcken vid Arnon, midt i bäcken, der landamäret är, och allt intill den bäcken Jabbok, der landamäret är för Ammons barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Dertill den slättmarkena, och Jordan, den landamäret är, ifrå Cinnereth intill hafvet vid slättmarkena; nämliga salthafvet nedan vid berget Pisga österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Och jag böd eder på samma tiden, och sade: Herren edar Gud hafver gifvit eder detta landet att intaga det; så drager nu väpnade för edra bröder Israels barn, alle I som stridsamme ären;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Förutan edra hustrur, barn och boskap; ty jag vet, att I hafven mycken boskap; låter dem blifva uti edra städer, som jag eder gifvit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Tilldess Herren låter ock edra bröder komma till rolighet såsom eder, att de ock intaga det land, som Herren deras Gud dem gifva skall på hinsidon Jordan; sedan skolen I omvända till edor besittning, den jag eder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Och jag böd Josua på samma tiden, och sade: Din ögon hafva sett allt det som Herren edar Gud dessa två Konungar gjort hafver; så varder Herren ock görandes all Konungarike, dit du drager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Frukter eder intet för dem; ty Herren edar Gud strider för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Och jag bad Herran på den tiden, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Herre, Herre, du hafver begynt visa dinom tjenare dina härlighet och dina starka hand; ty hvilken är den Gud i himmelen eller på jordene, som förmår efter din verk och din magt göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Låt mig gå och se det goda landet, på hinsidon Jordan; de goda berg, och Libanon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Men Herren vardt vred på mig för edra skull, och bönhörde mig intet; utan Herren sade till mig: Låt blifvat: tala intet mer derom för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Stig upp på höjden af berget Pisga, och häf din ögon upp vesterut, och norrut, och söderut, och österut, och se det med ögonen; ty du skall intet gå utöfver denna Jordan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Utan bjud Josua, att han är tröst och frimodig; förty han skall gå öfver Jordan för folket, och skall utskifta dem landet, som du seendes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Så blefvo vi då i den dalen in mot Peors hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Och nu hör, Israel, de bud och rätter, som jag eder lärer, att I dem göra skolen, på det I män lefva, och inkomma, och intaga landet, som Herren edra fäders Gud eder gifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'I skolen intet lägga dertill, som jag eder bjuder; och skolen ej heller taga der något ifrå; på det I mågen bevara Herrans edars Guds bud, som jag bjuder eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Edor ögon hafva sett hvad Herren gjort hafver med BaalPeor; ty alla de som efterföljde BaalPeor, dem hafver Herren din Gud förgjort ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Men I som höllen eder intill Herran edar Gud, I lefven alle på denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Si, jag hafver lärt eder bud och rätter, såsom Herren min Gud mig budit hafver, att I så göra skolen i landet, der I inkommande varden till att intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Så behåller det nu, och görer det; ty så varder edor vishet och förstånd berömd för all folk, när de hörande varda all denna bud, så att de skola säga: Si, hvilket vist och förståndigt folk detta är, och ett härligit folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Ty hvad folk är så härligit, hvilko gudarna så nalkas, såsom Herren vår Gud, så ofta som vi åkalle honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Och hvar är något så härligit folk, som så rättfärdiga seder och bud hafver, såsom all denna lagen, som jag eder på denna dagen föregifver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Så förvara dig nu och dina själ granneliga, att du icke förgäter hvad för din ögon skedt är, och att det icke gånger utu dino hjerta i alla dina lifsdagar; och skall förkunna dinom barnom, och dinom barnabarnom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Den dagen, då du stod för Herranom dinom Gud vid berget Horeb, och Herren till mig sade: Församla mig folket, att jag skall låta dem höra min ord, och lära frukta mig i alla deras lifsdagar på jordene, och lära sin barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Och I gingen fram, och stoden neder under berget, och berget brann halfväges upp till himmelen; och der var mörker, moln och töckna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Och Herren talade med eder midt utur elden; hans ords röst hörden I, men ingen liknelse sågen I, utan röstena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Och han förkunnade eder sitt förbund, det han eder böd att göra; nämliga de tio ord, och skref dem på två stentaflor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Och Herren böd mig på samma tiden, att jag skulle lära eder bud och rätter, att I derefter göra skullen uti de lande, der I indragen till att intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Så förvarer nu edra själar väl; ty I hafven ingen liknelse sett på den dagen, då Herren talade med eder utur elden på bergena Horeb;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'På det I icke skolen förderfva eder och göra eder något beläte, det en man likt är eller qvinno;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Eller djure på jordene, eller fogle under himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Eller matke, som kräker på jordene, eller fiske i vattnena under jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Och att du icke heller upphäfver din ögon till himmelen, och ser solen, och månan, och stjernorna, hela himmelens här, och faller af, och tillbeder dem, och tjenar dem, hvilka Herren din Gud förskickat hafver allom folkom under hela himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Men eder hafver Herren upptagit, och fört eder utu jernugnen, nämliga utur Egypten, att I skullen vara hans arffolk, som det ock är i denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Och Herren vardt vred på mig för edra gerningars skull, så att han svor, att jag icke skulle komma öfver Jordanen, eller i det goda landet, som Herren din Gud dig till arfvedel gifva skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Utan jag måste dö i detta land, och skall icke gå öfver Jordanen; men I skolen gå deröfver, och intaga det goda landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Så tager eder nu vara, att I Herrans edars Guds förbund icke förgäten, det han med eder gjort hafver; och icke görer beläte till någrahanda liknelse, såsom Herren din Gud dig budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Förty Herren din Gud är en frätande eld, och en nitälskande Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'När I nu föden barn, och barnabarn, och bon på landena, och förderfven eder, och gören eder beläte till någrahanda liknelse, så att I gören illa för Herranom edrom Gud, och förtörnen honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Så kallar jag i denna dag himmel och jord till vittne öfver eder, att I skolen snart förgås utaf landena, uti hvilket I ingån öfver Jordanen, till att intaga det. I skolen icke länge blifva deruti; utan skolen förgjorde varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Och Herren skall förströ eder ibland folk, och I varden ett fögo folk qvart blifvande ibland Hedningarna, dit Herren eder drifvandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Der skall du tjena afgudom, som menniskohandaverk äro, stock och sten, hvilke hvarken se eller höra, eller äta, eller lukta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Om du då der söker Herran din Gud, så skall du finna honom; om du söker honom af allo hjerta, och af allo själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'När du bedröfvad varder, och dig all denna tingen uppåkomma i de yttersta dagar, så skall du vända dig till Herran din Gud, och skall höra hans röst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Förty Herren din Gud är en barmhertig Gud; han varder dig icke öfvergifvandes, eller förderfvandes; och skall han icke förgäta det förbund med dina fäder, som han dem svorit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Befråga efter förtiden, som för dig varit hafver, ifrå den dagen då Gud skop menniskona på jordene, ifrå den ena himmelens ända till den andra, om någon tid en sådana stor ting skedd, eller dess like någon tid hörd är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Att något folk hade hört Guds röst talandes utur elden, såsom du hört hafver, och likväl lefver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Eller om Gud försökt hafver att ingå, och taga sig ett folk midt utur eno folke, genom frestelse, genom tecken, genom under, genom strid, och genom mägtiga hand, och genom uträcktan arm, och genom stora syner, såsom Herren edar Gud allt detta med eder gjort hafver, för din ögon uti Egypten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Du hafver sett det, på det du skall veta, att Herren är allena Gud, och ingen annan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Af himmelen hafver han låtit dig höra sina röst, att han skulle lära dig; och på jordene hafver han låtit dig se sin stora eld, och utur elden hafver du hört hans ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Derföre, att han dina fäder älskat, och deras säd efter dem utvalt hafver; och fört dig utur Egypten med sitt ansigte, genom sina stora magt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'På det han skulle för dig fördrifva stor folk, och starkare än du äst, och föra dig derin, och gifva dig deras land till arfvedel, såsom det tillstår i denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Så skall du nu veta i dag, och lägga det på hjertat, att Herren är en Gud, ofvan i himmelen, och nedre uppå jordene, och ingen annan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Att du håller hans rätter och bud, som jag i dag bjuder dig, så varder dig och dinom barnom efter dig väl gåendes, att ditt lif skall länge vara i landena, som Herren din Gud dig gifver evärdeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Då afskiljde Mose tre städer hinsidon Jordan, österut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Att dit fly skulle ho som sin nästa ihjälsloge med våda, och tillförene icke hade varit hans ovän; den skulle fly in uti en af de städer, på det han måtte blifva vid lif;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bezer i öknene på den slättmarkene ibland de Rubeniter, och Ramoth i Gilead ibland de Gaditer, och Golan i Basan ibland de Manassiter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Detta är den lag, som Mose Israels barnom föregaf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Och detta är vittnesbördet, och bud, och rätter, som Mose sade Israels barnom, då de utur Egypten dragne voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Hinsidon Jordan uti den dalenom in mot Peors hus, uti Sihons lande, de Amoreers Konungs, som i Hesbon bodde, hvilken Mose och Israels barn slogo, då de utur Egypten komne voro,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Och togo hans land in; dertill Ogs land, Konungens i Basan, de två Amoreers Konungars, som på hinsidon Jordan voro, österut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Ifrån Aroer, hvilken på den bäckens strand vid Arnon ligger, intill berget Sion, det är Hermon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'Och allt släta landet hinsidon Jordan, österut, allt intill hafvet, på slättene, nedanför berget Pisga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Och Mose kallade hela Israel, och sade till dem: Hör, Israel, de bud och rätter, som jag i dag talar för edor öron, och lärer dem, och behåller dem, att I gören derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Herren vår Gud hafver gjort ett förbund med oss i Horeb;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Och Herren hafver icke gjort detta förbundet med våra fäder, utan med oss, som nu här äre på denna dag, och alle lefve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Ansigte mot ansigte hafver Herren talat med oss utur eldenom på berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Jag stod på den tiden emellan Herran och eder, att jag skulle föra Herrans ord till eder; förty I fruktaden eder för eldenom, och gingen icke upp på berget; och han sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Jag är Herren din Gud, som dig utur Egypti land fört hafver, utu träldomens hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Du skall inga andra gudar hafva för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Du skall intet beläte göra dig, efter någrahanda liknelse, antingen det ofvan i himmelen är, eller nedre på jordene, eller i vattnena under jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Du skall icke tillbedja dem, eller tjena dem; ty jag är Herren din Gud, en nitälskande Gud, som hemsöker fädernas missgerningar öfver barnen, intill tredje och fjerde led, deras som mig hata;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'Och beviser barmhertighet på mång tusend, som mig älska och min bud hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Du skall icke missbruka Herrans dins Guds Namn; ty Herren skall icke låta blifva honom ostraffad, som hans Namn missbrukar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Sabbathsdagen skall du hålla, att du honom helgar; såsom Herren din Gud dig budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sex dagar skall du arbeta, och göra all din verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Men på sjunde dagen är Herrans dins Guds Sabbath; då skall du intet arbete göra, icke heller din son, eller din dotter, eller din tjenare, eller din tjenarinna, eller din oxe, eller din åsne, eller all din boskap, eller främlingen som innan dina portar är; på det att din tjenare och tjenarinna måga hafva ro så väl som du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Förty du skall ihågkomma, att du vast ock en träl uti Egypti land, och Herren din Gud förde dig derut med mägtiga hand och uträcktom arme; derföre hafver Herren din Gud budit dig, att du skall hålla Sabbathsdagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Du skall hedra din fader och dina moder, såsom Herren din Gud dig budit hafver; på det att du må länge lefva, och att dig må väl gå uti de lande, som Herren din Gud dig gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Du skall icke dräpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Du skall icke göra hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Du skall icke stjäla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Du skall icke bära falskt vittnesbörd emot din nästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Du skall icke hafva lust till dins nästas hustru; du skall icke begära dins nästas hus, åker, tjenare, tjenarinno, oxa, åsna, eller hvad som helst honom tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Desse äro de ord, som Herren talade till alla edra menighet uppå berget, utur eldenom, och molnena, och töcknene, med stora röst; och lade der intet till; och skref dem på två stentaflor, och fick mig dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'När I hörden röstena utu mörkret, och berget brinna i elde, gingen I fram till mig, alle öfverstar i edra slägter, och edre äldste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Och saden: Si, Herren vår Gud hafver låtit oss se sina härlighet, och sitt majestät, och vi hafve hört hans röst utur eldenom; i dag hafve vi sett, att Gud talade med menniskom, och de blefvo i lifve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Och nu, hvi skole vi dö, så att den store elden förtärer oss? Om vi oftare höre Herrans vår Guds röst, så måste vi dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Förty hvad är allt kött, att det höra må lefvandes Guds röst tala utur eldenom, såsom vi, och kan lefva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Gack du fram, och hör allt det Herren vår Gud säger; och säg oss det. Allt det Herren vår Gud med dig talar, det vilje vi höra och göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Då Herren hörde rösten af edor ord, som I taladen med mig, sade Herren till mig: Jag hafver hört detta folks ord, som de med dig talat hafva; det är allt godt, som de sagt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Ack! det de ett sådant hjerta hade till att frukta mig, och till att hålla all min bud i deras lifsdagar; på det att dem måtte gå väl, och deras barn evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Gack, och säg dem: Går hem i edor tjäll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Men du skall stå här för mig, att jag talar med dig all lag, och bud, och rätter, som du dem lära skall, att de göra derefter uti landena, som jag dem gifva skall till att intaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Så behåller det nu, att I mån göra såsom Herren edar Gud eder budit hafver; och viker icke hvarken på högra sidon eller venstra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Utan vandrer i alla de vägar, som Herren edar Gud eder budit hafver; på det I mågen lefva, och eder skall väl gå, och I länge lefven i landena, som I intaga skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Desse äro nu de lag, och bud, och rätter, som Herren edar Gud budit hafver, att I dem lära och göra skolen i landena, dit I indragen till att intaga det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Att du fruktar Herran din Gud, och håller alla hans rätter och bud, som jag bjuder dig; du och din barn, och din barnabarn, i alla edra lifsdagar, på det I skolen länge lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Israel, du skall höra, och behållat, så att du gör ock så, att dig väl går, och varder mycket förökad, såsom Herren dina fäders Gud dig tillsagt hafver ett land, der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Hör, Israel: Herren vår Gud är en enig Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Och du skall älska Herran din Gud af allo hjerta, af allo själ, af allo förmågo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Och dessa ord, som jag bjuder dig i dag, skall du lägga på hjertat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Och skall skärpa dem dinom barnom, och derom tala, när du sitter i ditt hus, eller går uppå vägen; när du nederlägger dig, eller uppstår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Och skall binda dem för ett tecken på dine hand, och skola vara dig till en åminnelse för din ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Och skall skrifva dem på dins hus dörrträ, och uppå dörrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'När nu Herren din Gud låter dig komma uti landet, som han dina fäder, Abraham, Isaac och Jacob, svorit hafver, dig att gifva stora och sköna städer, som du intet byggt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'Och hus full med allt godt, de du intet uppfyllt hafver; och uthuggna brunnar, som du intet uthuggit hafver; och vingårdar och oljoberg, som du intet planterat hafver, att du må äta och mätt varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Så tag dig vara, att du icke förgäter Herran, som dig utur Egypti land, utu träldomens hus, fört hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Utan skall frukta Herran din Gud, och tjena honom, och svärja vid hans Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Och skall icke följa andra gudar efter, dess folks, som omkring eder bo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Ty Herren din Gud är en nitälskande Gud ibland dig; att Herrans dins Guds vrede icke skall förgrymma sig öfver dig, och förgöra dig af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'I skolen icke försöka Herran edar Gud, såsom I försökten honom i Massa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Utan skolen hålla Herrans edars Guds bud, och hans vittnesbörder, och hans rätter, som han budit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Att du gör det rätt och godt är för Herrans ögon, på det dig må gå väl, och du inkommer, och intager det goda landet, som Herren svorit hafver dina fäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Att han skall fördrifva alla dina fiendar för dig, såsom Herren sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'När nu din son i dag eller i morgon frågar dig, och säger: Hvad är detta för vittnesbörder, bud och rätter, som Herren vår Gud eder budit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Så skall du säga dinom son: Vi vorom Pharaos trälar i Egypten; och Herren förde oss utur Egypten med mägtiga hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Och Herren gjorde stor och ond tecken och under öfver Egypten och Pharao, och allt hans hus, för vår ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Och förde oss dädan, på det han skulle införa oss, och gifva oss det land, som han våra fäder svorit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Och böd Herren oss att göra efter alla dessa rätter, att vi skole frukta Herran vår Gud, att oss väl går i alla våra lifsdagar, såsom det tillgår i denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Och det skall vara oss till rättfärdighet för Herranom vårom Gud, om vi hålle och göre all dessa buden, såsom han oss budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'När Herren din Gud förer dig in uti det land, der du inkomma skall, till att intaga det, och nederlägger mycket folk för dig; de Hetheer, Girgaseer, Amoreer, Cananeer, Pheriseer, Heveer och Jebuseer, sjuhanda folk, de som större äro och mägtigare än du;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'Och när Herren din Gud gifver dem för dig, att du slår dem, så skall du gifva dem tillspillo, och intet förbund med dem göra, eller någon gunst bevisa dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Och skall intet befrynda dig med dem; edra döttrar skall du icke gifva deras söner, och deras döttrar skolen I icke taga edrom sönom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Förty de varda dragande edra söner ifrå mig, så att de tjena andra gudar; så varder då Herrans vrede förgrymmandes sig öfver eder, och snarliga förgör eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Utan alltså skolen I göra med dem: Deras altare skolen I nederrifva, deras stodar nederbryta, deras lundar afhugga, och deras afgudar uppbränna med elde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Ty du äst ett heligt folk Herranom dinom Gud; dig hafver Herren din Gud utvalt till att du skall vara hans eget folk, utaf all de folk som på jordene äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Icke hafver Herren upptagit och utvalt eder derföre, att I större på talet ären än annat folk; ty du äst minst i all folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Utan derföre, att Herren älskade eder, och att han skulle hålla sin ed, som han edra fäder svorit hade, hafver Herren utfört eder med mägtiga hand; och hafver frälst dig utu träldomens hus, utu Pharaos hand, Konungens i Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Så skall du nu veta, att Herren din Gud är en Gud, en trofast Gud, hållandes förbund och barmhertighet dem som älska honom, och hålla hans bud, i tusende leder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Och vedergäller dem som hata honom, för sitt ansigte, så att han förgör dem; och skall icke fördröjat, att han dem vedergäller för sitt ansigte, som hata honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Så behåll nu de bud, och lag, och rätter, som jag dig bjuder i denna dag, att du gör derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Och när I dessa rätter hören, och hållen dem, och gören derefter, så varder Herren din Gud ock hållandes det förbund och barmhertighet, som han dina fäder svorit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Han skall älska dig, välsigna och föröka; och skall välsigna dins lifs frukt, och dins lands frukt, dina säd, vin och oljo, fruktena af dina kor, och fruktena af din får, på landet, som han dina fäder svorit hafver att gifva dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Välsignad varder du utöfver all folk; ingen ibland dig skall vara ofruktsam, ej heller ibland din boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Herren skall taga ifrå dig all krankhet, och skall icke kasta dig någon de Egyptiers onda sjukdom uppå, hvilka du förnummit hafver; men han skall kasta dem på alla dem som dig hata.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Du skall uppfräta allt det folk, som Herren din Gud dig gifvandes varder; du skall icke skona dem, och icke tjena deras gudar; ty det vorde dig till en snaro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Om du säger i ditt hjerta: Detta folk är mer än jag; huru kan jag fördrifva dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Så frukta dig intet för dem; tänk uppå hvad Herren din Gud gjorde Pharao, och alla Egyptier;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Med stor försökelse, som du med ögonen sett hafver, och med tecken och under, och genom mägtiga hand och uträcktom arm, med hvilko Herren din Gud dig utförde. Alltså skall Herren din Gud göra allom folkom, som du fruktar före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Dertill skall Herren din Gud sända ibland dem getingar, intilldess förgjordt varder hvad som qvart är, och sig för dig förgömmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Grufva dig intet för dem; ty Herren din Gud är ibland dig, den store och förfärlige Guden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Han, Herren din Gud, skall utrota dessa folken för dig, med tiden, det ena efter det andra; du kan icke hastigt förgöra dem, på det att djuren icke skola förökas emot dig på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Herren din Gud skall gifva dem för dig, och skall slå dem med stort slag, intilldess han förgör dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Och skall gifva deras Konungar i dina händer, och du skall förgöra deras namn under himmelen; ingen skall kunna dig emotstå, tilldess du förgör dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Deras afgudars beläte skall du bränna upp i elde; och skall intet begära utaf silfret eller guldet, som deruppå är, eller taga det till dig, på det att du icke skall förtaga dig derutinnan: ty sådant är Herranom dinom Gud en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Derföre skall du icke föra den styggelsen in uti ditt hus, att du icke varder tillspillogifven, såsom ock det är; utan du skall hafva en vämjelse och styggelse dervid; ty det är tillspillogifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'All de bud, som jag bjuder dig i dag, skolen I hålla, att I gören derefter; på det I mågen lefva och förökas, och komma in, och intaga det land, som Herren edra fäder svorit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Och skall tänka på allan den väg, genom hvilken Herren din Gud dig ledt hafver, i dessa fyratio åren i öknene; på det han skulle späka och försöka dig, att kunnigt skulle varda hvad i dino hjerta var; om du hölle hans bud eller ej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Han späkte dig och lät dig hungra, och spisade dig med Man, det du och dine fäder intet känt hade; på det han skulle låta dig veta, att menniskan lefver icke allenast af bröd, utan af allt det af Herrans mun går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Din kläder äro intet förslitne på dig, och dine fötter äro intet svullnade i dessa fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Så finner du ju i dino hjerta, att Herren din Gud dig lärt hafver, såsom en man lärer sin son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Så håll nu Herrans dins Guds bud, att du vandrar i hans vägar, och fruktar honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Ty Herren din Gud förer dig uti ett godt land; i ett land, der bäcker, och brunnar, och djup uti äro, hvilke utmed bergen och inpå slättena flyta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Ett land, der hvete, korn, vinträ, fikonträ och granatäple uti äro; ett land, der oljoträ och hannog uti växer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Ett land, der du skall hafva bröd nog till att äta, der ock intet fattas; ett land, hvilkets stenar äro jern; der du ock koppar utu bergen hugger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Och när du ätit hafver och äst mätt, att du då lofvar Herran din Gud, för det goda land, som han dig gifvit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Så tag dig nu vara, att du icke förgäter Herran din Gud, dermed, att du icke håller hans bud, och hans lag och rätter, som jag bjuder dig i dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Att när du ätit hafver, och äst mätt, och bygger skön hus, der du uti bor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'Och ditt fä och får, och silfver och guld, och allt det du hafver, förökas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Att ditt hjerta då icke upphäfves, och du förgäter Herran din Gud, som dig utur Egypti land fört hafver, utu träldomens hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Och hafver ledt dig igenom denna stora och förskräckeliga öknen, der brännande ormar, och scorpion, och torrhet, och platt intet vatten var, och lät dig utgå vatten ur hårda hälleberget;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Och spisade dig med Man i öknene, der dine fäder intet af vetat hade; på det han skulle späka och försöka dig, och framdeles göra väl emot dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Annars måtte du säga i dino hjerta: Min kraft och mina händers starkhet hafver mig denna förmågona gjort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Utan tänk på Herran din Gud; ty han är den som kraft gifver till att komma detta åstad; på det han skulle fullkomna sitt förbund, som han dina fäder svorit hade, såsom det tillgår i denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Men om du förgäter Herran din Gud, och följer andra gudar efter, och tjenar dem, och tillbeder dem; så betygar jag i dag öfver eder, att I skolen slätt förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Lika som Hedningarna, hvilka Herren förgör för edart ansigte, så skolen ock I förgås; derföre, att I icke ären Herrans edars Guds röst hörige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Hör, Israel: I dag skall du gå öfver Jordan, att du inkommer till att intaga de folk, som större och starkare äro än du; stora städer, murade upp till himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Ett stort högt folk, Enakims barn, som du känt hafver, af hvilkom du ock hört hafver: Ho kan stå emot Enaks barn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Så skall du veta i dag, att Herren din Gud går framför dig, en förtärande eld; han varder dem förgörandes och nederläggandes för dig, och skall fördrifva dem, och omintetgöra dem snarliga, såsom Herren dig sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Då nu Herren din Gud dem utdrifvit hafver för dig, så säg icke i dino hjerta: Herren hafver mig här infört, till att intaga detta landet för mina rättfärdighets skull; ändock Herren fördrifver Hedningarna för dig, för deras ogudaktighets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ty du kommer icke in i landet till att besitta det, för dina rättfärdighet, eller för dins hjertas fromhets skull; utan Herren din Gud fördrifver dessa Hedningarna för deras ogudaktighets skull, på det han skall fullkomna det ord, som Herren dina fäder, Abraham, Isaac och Jacob, svorit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Så vet nu, att Herren din Gud icke gifver dig detta goda landet till att intaga för dina rättfärdighets skull; efter du äst ett halsstyft folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Kom ihåg, och förgät icke, huru du Herran din Gud förtörnade i öknene; ifrå den dag att du drog utur Egypti land, tilldess I komne ären till detta rum, hafven I varit Herranom ohörsamme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Förty i Horeb förtörnaden I Herran, så att Herren för vredes skull ville förgöra eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Då jag gången var på berget, till att anamma de stentaflor, förbundsens taflor, som Herren gjorde med eder, och jag blef på bergena fyratio dagar, och fyratio nätter, och åt intet bröd och drack intet vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Och Herren fick mig de två stentaflorna, beskrefna med Guds finger, och derutinnan all ord, som Herren med eder utur elden på berget talat hade, på församlingenes dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Och efter de fyratio dagar och fyratio nätter fick mig Herren de två förbundsens stentaflor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Och Herren sade till mig: Statt upp, gack snart ned hädan; ty ditt folk, som du utfört hafver af Egypten, hafver förderfvat det; de äro snarliga trädde ifrå den vägen, som jag hafver budit dem; de hafva gjort sig ett gjutet beläte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Och Herren sade till mig: Jag ser, att detta folket är ett halsstyft folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Låt mig betämma, att jag förgör dem, och utskrapar deras namn under himmelen. Jag vill göra ett starkare och mägtigare folk af dig, än detta är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Och som jag omvände mig, och gick ned af berget, som brann i eld, och hade de två förbundsens taflor i båda mina händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Då såg jag, och si, då haden I syndat emot Herran edar Gud, så att I haden gjort en gjuten kalf, och voren snarliga trädde ifrå den vägen, den Herren eder budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Så tog jag båda taflorna, och kastade dem bort utu båda händerna, och slog dem sönder för edor ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Och föll ned för Herran, såsom tillförene, i fyratio dagar, och fyratio nätter; och åt intet bröd, och drack intet vatten, för alla edra synders skull, som I gjort haden; i det I sådant ondt gjorden för Herranom, till att förtörna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Ty jag fruktade för den vrede och grymhet, der Herren på eder med förtörnad var, så att han ville förgöra eder. Och Herren hörde mig än i den gången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Var ock Herren storliga vred på Aaron, så att han ville förgöra honom; men jag bad ock för Aaron på samma tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Men edor synd, kalfven som I gjort haden, tog jag och brände upp i elde, och slog sönder honom, och sönderstötte, tilldess han vardt stoft; och kastade stoftet i bäcken, som flyter utaf bergena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Sammalunda förtörnaden I ock Herran i Thabeera, och i Massa, och vid de Lustgrifter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Och då Herren sände eder ifrå KadesBarnea, och sade: Går ditupp, och tager landet in, som jag eder gifvit hafver; voren I Herrans edars Guds mun ohörsamme, och trodden icke på honom, och lydden icke hans röst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Ty I hafven varit Herranom ohörsamme, så länge som jag eder känt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Då föll jag neder för Herran fyratio dagar, och fyratio nätter, som jag der låg; ty Herren sade, att han ville förgöra eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Men jag bad Herran, och sade: Herre, Herre, förderfva icke ditt folk och din arfvedel, hvilket du genom dina stora magt förlossat, och med mägtiga hand utur Egypten fört hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Kom ihåg dina tjenare Abraham, Isaac och Jacob; se icke på detta folkets hårdhet, och detta folkets ogudaktighet och synd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Att det landet, der du oss utfört hafver, icke skall säga: Herren kunde icke föra dem uti det land, som han dem lofvat hade, och hafver fördenskull fört dem derut, att han var vred på dem, att han skulle dräpa dem i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Förty de äro ditt folk, och din arfvedel, som du med dine stora magt, och med din uträckta arm, utfört hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'På samma tiden sade Herren till mig: Uthugg dig två stentaflor såsom de första, och kom till mig på berget, och gör dig en ark af trä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Så vill jag skrifva på taflorna de ord, som på de första voro, hvilka du sönderslagit hafver; och du skall lägga dem i arken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Så gjorde jag då en ark af furoträ, och uthögg två stentaflor, sådana som de första voro, och gick upp på berget, och hade de två taflorna i mina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Då skref han på taflorna, såsom den första skriften var, de tio ord, som Herren talade till eder utur eldenom på berget, på församlingenes dag; och Herren fick mig dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Och jag vände om, och gick af berget, och lade taflorna i arken, som jag gjort hade, att de skulle der blifva, såsom Herren mig budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Och Israels barn drogo ut ifrå Beeroth BeneJaakan till Moserah; der blef Aaron död, och vardt der begrafven; och hans son Eleazar vardt Prester för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Dädan drogo de ut till Gudgoda; ifrå Gudgoda till Jothbath, ett land der bäcker äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'På den tiden afskiljde Herren Levi slägte, till att bära Herrans förbunds ark, och till att stå för Herranom, till att tjena honom, och lofva hans Namn, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Derföre skulle de Leviter ingen del eller arf hafva med sina bröder; ty Herren är deras arf, såsom Herren din Gud dem sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Och jag stod på bergena, såsom tillförene, fyratio dagar och fyratio nätter, och Herren bönhörde mig än i den gången, och Herren ville icke förgöra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Men Herren sade till mig: Statt upp, och gack åstad, att du går för folket, att de inkomma, och intaga landet, som jag deras fäder svorit hafver dem att gifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nu, Israel, hvad äskar Herren din Gud af dig, utan att du skall frukta Herran din Gud, att du vandrar i alla hans vägar, och älskar honom, och tjenar Herranom dinom Gud, af allo hjerta och af allo själ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Att du håller Herrans bud och hans rätter, de jag dig bjuder i denna dag, på det att dig må väl gå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Si, himmelen och alla himlars himlar, och jorden, och allt det deruti är, är Herrans dins Guds;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Dock likväl hafver Herren allena haft vilja till dina fäder, så att han älskade dem, och hafver utvalt deras säd efter dem, nämliga eder, utöfver allt folk, såsom det ock tillgår på denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Så omskärer nu edars hjertas förhud, och varer icke mer halsstyfve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Förty Herren edar Gud är en Gud öfver alla gudar, och en Herre öfver alla herrar, en stor Gud, mägtig och förfärlig, den ingen person aktar, och tager inga mutor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Och skaffar dem faderlösom och enkom rätt, och älskar de främmande, så att han gifver dem födo och kläde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Derföre skolen I ock älska de främmande; ty I hafven ock varit främmande uti Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Herran din Gud skall du frukta; honom skall du tjena; till honom skall du hålla dig, och svärja vid hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Han är ditt lof, och din Gud, den med dig så stor och förfärlig ting gjort hafver, såsom din ögon sett hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Dine fäder foro neder uti Egypten med sjutio själar; men nu hafver Herren din Gud förökat dig, såsom stjernorna på himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Så skall du nu älska Herran din Gud, och hålla hans lag, hans seder, hans rätter och hans bud, så länge du lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Och förnimmer i dag det edor barn icke veta, eller sett hafva; nämliga Herrans edars Guds tuktan, hans härlighet, och hans mägtiga hand, och uträckta arm;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Och hans tecken och verk, som han gjorde ibland de Egyptier, på Pharao, Konungen i Egypten, och på allt hans land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'Och hvad han gjorde på de Egyptiers magt; på deras hästar och vagnar, då han lät komma vattnet af det röda hafvet öfver dem, när de foro efter eder, och Herren förgjorde dem, allt intill denna dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Och hvad han eder gjorde i öknene, intilldess I nu till detta rummet komne ären;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'Hvad han gjorde Dathan och Abiram, Eliabs sönom, Rubens sons; huru jorden öppnade sin mun, och uppsvalg dem med deras folk och tjäll, och alla deras ägodelar, som under dem voro, midt i hela Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Ty edor ögon hafva sett de stora Herrans gerningar, som han gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Derföre skolen I hålla all de bud, som jag bjuder eder i dag, på det I skolen styrkte varda till att komma in, och intaga landet, dit I faren till att intaga det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'Och att du skall länge lefva i landena, som Herren edra fäder svorit hafver att gifva dem och deras säd, ett land der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Ty det landet, som du kommer till att intaga, är icke såsom Egypti land, der I utdragne ären, der man sår säd, och bär dit vatten till fots, såsom till en kålgård;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Utan det hafver berg, och slättmarker, hvilka regn af himmelen vattna måste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Om hvilket land Herren din Gud låter sig vårda, och Herrans dins Guds ögon se alltid deruppå, ifrå begynnelsen på året, intill ändan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Om I nu hören min bud, som jag bjuder eder i dag, att I älsken Herran edar Gud, och tjenen honom af allt hjerta, och af allo själ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Så skall jag gifva edro lande regn i sinom tid, arla och serla, att du skall inberga din säd, ditt vin, och dina oljo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Och skall gifva dinom boskap gräs på dine mark, att I mågen äta och varda mätte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Men tager eder vara, att edart hjerta icke låter draga sig dertill, att I afträden, och tjenen andra gudar, och tillbedjen dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Och Herrans vrede förgrymmar sig då öfver eder, och lycker himmelen till, att intet regn kommer, och jorden icke gifver sin växt, och I snarliga förgås utaf det goda landet, som Herren eder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Så fatter nu dessa orden i hjertat, och i edra själar, och binder dem för ett tecken på edra hand, att de äro till en åminnelse för edor ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Och lärer dem edor barn, så att du talar derom, när du sitter i dino huse, eller går på vägen; när du lägger dig neder, och när du uppstår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Och skrif dem på dörrträn i dino huse, och på dine dörr;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Att du och din barn mågen länge lefva i landena, som Herren dine fäder svorit hafver att gifva dem, så länge dagarna af himmelen på jordene vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Ty om I alla dessa buden hållen, som jag bjuder eder, och derefter gören, så att I älsken Herran edar Gud, och vandren i alla hans vägar, och håller eder intill honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Så skall Herren fördrifva allt detta folket för eder, så att I skolen intaga större och starkare folk än I ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'All rum, som edar fot på träder, skola vara edor; ifrån öknene och ifrå berget Libanon, och ifrån älfvene Phrath, allt intill det yttersta hafvet, skall edart landamäre vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Ingen skall kunna stå eder emot; edar räddhåga och förfärelse skall Herren låta komma öfver all de land, der I inresen, såsom han eder sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Si, jag lägger eder före i dag välsignelse och förbannelse:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Välsignelse, om I lyden Herrans edars Guds bud, som jag bjuder eder i dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'Förbannelse, om I icke lyden Herrans edars Guds bud, och afträden ifrå den vägen, som jag bjuder eder i dag, så att I vandren efter andra gudar, de I icke kännen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'När Herren din Gud förer dig in i det land, der du inkommer till att intagat, så skall du låta tala välsignelsen på det berget Grisim, och förbannelsen på det berget Ebal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Hvilke äro på hinsidon Jordan, på den vägen vesterut, i de Cananeers lande, som bo på den slättmarkene in emot Gilgal, vid den lunden More.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Ty du måste gå öfver Jordan, att du inkommer, och tager landet in, som Herren edar Gud eder gifvit hafver, att I det intaga och deruti bo skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Så ser nu till, att I gören efter all de bud och rätter, som jag eder i dag förelägger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Desse äro de bud och rätter, som I hålla skolen, så att I gören derefter uti landena, som Herren dina fäders Gud dig gifvit hafver till att intaga, så länge I på jordene lefven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Förgörer all de rum, der Hedningarna, som I intagen, sina gudar tjent hafva, vare sig på hög berg, på backar, eller under grön trä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Och bryter neder deras altare, och slår sönder deras stodar; och deras lundar uppbränner med eld, och deras afgudabeläte kaster bort, och tager bort deras namn utu det rummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'I skolen icke så göra Herranom edrom Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Utan på det rum, som Herren edar Gud utväljer af allom edrom slägtom, att han vill låta sitt Namn der bo, der skolen I fråga, och dit komma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Och göra edart bränneoffer, och edor annor offer, och edor tiond, och edra händers häfoffer, och edor löfte, och edor friviljoga offer, och förstfödningena af edart fä och får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Och der skolen I äta för Herranom edrom Gud, och vara glade öfver allt det I och edor hus förvärfven, der Herren din Gud dig uti välsignat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'I skolen intet göra af det vi i dag här görom, hvar och en som honom tycker rätt vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Ty I ären ännu härtilldags icke komne till ro, eller till arfvedelen, som Herren din Gud dig gifva skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Men I måsten gå öfver Jordan, och bo i de landena, som Herren edar Gud eder till arfs utskiftandes varder; och han skall låta eder få ro för alla edra fiendar omkring eder, och I skolen bo trygge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'När nu Herren din Gud utväljer ett rum, att hans Namn der bo skall, dit skolen I bära allt det jag bjuder eder: edart bränneoffer, edor annor offer, edor tiond, edra händers häfoffer, och all edor fri löfte, som I Herranom lofven;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Och skolen vara glade för Herranom edrom Gud, I och edre söner, och edra döttrar, och edre tjenare, och edra tjenarinnor, och Leviterna, som i edra portar äro; förty de hafva ingen lott eller arfvedel med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Tag dig vara, att du icke offrar ditt bränneoffer i all de rum som du ser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Utan i det rum, som Herren utväljer, uti någro af dina slägter, der skall du offra ditt bränneoffer, och göra allt det jag bjuder dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Dock må du slagta, och äta kött i alla dina portar, efter all dine själs begärelse, efter Herrans dins Guds välsignelse, som han dig gifvit hafver; både rene och orene måga det äta, såsom en rå eller en hjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Men blodet skall du icke äta; utan gjuta det på jordena såsom vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Men icke må du äta i dina portar utaf tionden af din säd, dino vine, dine oljo, ej heller af den förstfödning af dino fä, af din får, eller af något ditt löfte, som du lofvat hafver, eller af ditt friviljoge offer, eller af dine hands häfoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Utan för Herranom dinom Gud skall du sådant äta på de rumme, som Herren din Gud utväljer, du och dine söner, dina döttrar, dine tjenare, dina tjenarinnor, och Leviten, som i dina portar är; och skall vara glad för Herranom dinom Gud, öfver allt det du dig företager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Och tag dig vara, att du icke öfvergifver Leviten, så länge du lefver på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'När nu Herren din Gud varder förvidgandes dina landsändar, såsom han dig sagt hafver, och du säger: Jag vill äta kött; efter din själ lyster äta kött, så ät kött efter alla dine själs begärelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Är rummet långt ifrå dig, som Herren din Gud utvalt hafver, att han der vill låta bo sitt Namn, så slagta af ditt fä eller får, som Herren dig gifvit hafver, såsom jag dig budit hafver, och ät det i dinom portom, efter all dine själs begärelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Såsom man äter en rå eller en hjort, må du ätat; både rene och orene måga lika väl ätat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Allenast vakta, att du icke äter blodet; ty blodet är själen, derföre skall du icke äta själena med köttet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Utan skall gjuta det på jordena såsom vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Och skall fördenskull icke ätat, att dig må väl gå, och dinom barnom efter dig, deraf att du gjort hafver det som rätt är för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Men när du helgar något det ditt är, eller lofvar, så skall du tagat, och bära till det rum, som Herren utvalt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Och göra ditt bränneoffer, med kött och blod, på Herrans dins Guds altare; blodet af ditt offer skall du gjuta på Herrans dins Guds altare, och äta köttet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Se till, och hör alla dessa orden, som jag bjuder dig; på det dig må väl gå, och dinom barnom efter dig till evig tid, deraf att du gjort hafver det rätt är, och Herranom dinom Gud behageligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'När Herren din Gud utrotar Hedningarna för dig, der du inkommer till att intaga dem, och du dem intagit hafver, och bor i deras land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Så tag dig vara, att du icke faller i snarona efter dem, sedan de fördrefne äro för dig; och att du intet söker efter deras gudar, och säger: Såsom detta folk hafver tjent deras gudar, så vill jag ock göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Du skall icke således göra Herranom dinom Gud; förty de hafva gjort sinom gudom allt det Herranom stygges vid, och det han hatar; ty de hafva ock uppbränt i elde sina söner och döttrar till sina gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Allt det jag bjuder eder, det skolen I hålla, så att I gören derefter. I skolen intet lägga dertill, och intet taga derifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Om en Prophet eller drömmare uppkommer ibland eder, och han gifver dig ett tecken eller under;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Och det tecken eller under sker, der han dig af sade, och säger: Låt oss vandra efter andra gudar, de som I icke kännen, och tjenom dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Så skall du icke höra den Prophetens eller drömmarens ord; ty Herren din Gud försöker eder, att han må förfara, om I af allo hjerta, och af allo själ, älsken Herran edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Ty Herran edar Gud skolen I följa, och frukta honom, och hålla hans bud, och höra hans röst, och honom tjena, och hålla eder intill honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Men den Propheten eller drömmaren skall dö, derföre att han lärde afträdelse ifrå Herranom edrom Gud, som eder utur Egypti land fört, och dig utu träldomens hus förlossat hafver: på det han skulle komma dig utaf den vägen, som Herren din Gud budit hafver, till att vandra deruppå; på det att du skall skilja den onda ifrå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Om din broder, dins moders son, eller din son, eller din dotter, eller hustrun, som är i dinom famn, eller din vän, den dig är såsom ditt hjerta, råder dig hemliga, och säger: Låt oss gå, och tjena andra gudar, hvilka du intet känner, ej heller dine fäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'De gudar, som ibland folken allt omkring eder äro, ehvad de äro när eller fjerran, ifrå den ena jordenes ända intill den andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Så samtyck det icke, ej heller lyd honom; och skall ditt öga intet skona honom, och skall intet förbarma dig öfver honom, eller fördölja honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Utan skall dräpa honom; din hand skall vara den första öfver honom, att han dräpes; och dernäst hela folkens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Man skall stena honom ihjäl; ty han for efter att han skulle komma dig ifrå Herranom dinom Gud, den dig utur Egypti land, ifrå träldomens hus, fört hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'På det att hela Israel skall det höra, och befrukta sig, och icke mer taga sig sådana ondt före ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Om du får höra i någon stad, som Herren din Gud dig gifvit hafver till att bo uti, att man säger:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Någre Belials barn äro utgångne ibland dig, och hafva förfört deras stads inbyggare, och sagt: Låt oss gå, och tjena andra gudar, som I intet kännen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Så skall du granneliga söka, ransaka och befråga, om sanningen finnes, att så visst är, att denna styggelsen ibland eder skedd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Så skall du slå den stadsens inbyggare med svärdsegg, och dem tillspillogifva, med allt som derinne är, och deras boskap med svärdsegg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Och allt deras rof skall du tillhopabära midt uppå gatona, och bränna upp i elde, både staden och allt hans rof, det ena med det andra, Herranom dinom Gud; att han till en hög blifver i evig tid, och aldrig uppbyggd varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Och låt intet blifva i dine hand af det som tillspillogifvet är; på det att Herren skall vändas ifrå sine vredes grymhet, och gifva dig barmhertighet, och förbarma sig öfver dig, och föröka dig, såsom han dina fäder svorit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Derföre, att du Herrans dins Guds röst lydt hafver, till att hålla all hans bud, som jag dig bjuder på denna dag, att du skall göra det som rätt är för Herrans dins Guds ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'I ären Herrans edars Guds barn; skärer eder icke, och görer eder icke skallota öfver edart änne för någon dödan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Ty du äst ett heligt folk Herranom dinom Gud, och Herren hafver utvalt dig, att du skall vara hans eget, utaf all folk som på jordene äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Du skall ingen styggelse äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Men desse äro de djur, som I äta skolen: Fä, får, get, hjort,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Rå, buffel, stenbock, enhörning, urnöt, och elgen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Och all djur, som tveklöfvad äro, och idisla, skolen I äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Men det skolen I icke äta, som idislar, och icke tveklöfvadt är: camelen, haran, cunilen. De som idisla, och icke tveklöfvad äro, de skola vara eder oren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Svinet, ändock det tveklöfvadt är, så idislar det dock icke, det skall vara eder orent; af dess kött skolen I icke äta, och vid dess as skolen I icke komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Detta är det I äta skolen, utaf allt det i vattnet är: allt det som spol och fjäll hafver, det skolen I äta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Men det som intet spol eller fjäll hafver, det skolen I icke äta; ty det är eder orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Alla rena foglar äter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Desse af dem äro de som I icke äta skolen: örnen, höken, falken,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Fiskagjusen, gladan, gamen med sine art,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Och alla korpar med deras art,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Strutsfoglen, ugglan, göken, sparfhöken med sine art,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'Stenugglan, ufven, flädermusen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Rördrommen, storken, svanen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Hägren, skrikan med sine art, vidhöfden, och svalan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Och alle foglar, som krypa, skola vara eder orene, och I skolen icke äta dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'De rena foglar skolen I äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'I skolen intet as äta. Främlingenom, som i dinom porte är, må du gifva det, att han det äter, eller sälj det enom främmande; ty du äst ett heligt folk Herranom dinom Gud. Du skall icke koka kidet, medan det ännu dir sina moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Du skall all år afskilja tionden af allo dine säds frukt, som utaf dinom åker kommer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Och skall äta den för Herranom dinom Gud, på det rum som han utväljer, att hans Namn der bo skall; nämliga af tionden utaf din säd, dino vine, dine oljo, och förstfödningen af ditt fä och din får; på det du skall lära frukta Herran din Gud i alla dina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Om vägen är dig för lång, att du icke kan komma det dit, derföre att det rummet är dig för långt ifrå, som Herren din Gud utvalt hafver, att han vill låta sitt Namn bo der; ty Herren din Gud hafver välsignat dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Så sälj det allt för penningar, och tag penningarna i dina hand, och gack till det rum, som Herren din Gud utvalt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Och köp för penningarna allt det din själ lyster, vare sig fä, får, vin, stark dryck, eller allt det din själ begärar; och ät det der för Herranom dinom Gud, och var glad, du och ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Och Leviten, som i dina portar är, honom skall du icke förlåta; förty han hafver ingen lott eller arf med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Efter tre år skall du afsöndra all tiond af dine säd i det året, och skall lägga henne i dina portar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Så skall Leviten komma, som ingen lott eller arf hafver med dig; och främlingen, och den faderlöse, och enkan, som i dina portar äro, och äta, och mätta sig; på det Herren din Gud dig välsigna skall i alla dina händers gerningar, som du gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Efter sju år skall du hålla ett friår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Och så skall det tillgå med samma friår: Hvilken man något ifrå sine hand sinom nästa borgat hafver, han skall icke kräfva det in af sinom nästa, eller af sinom broder; förty det heter friår Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Utaf en främmande må du det inkräfva; men dinom broder skall du tillgifvat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Och skall allsingen fattig vara ibland eder; ty Herren varder dig välsignande uti landena, som Herren din Gud dig till arfs gifva skall, till att intaga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Allenast att du lyder Herrans dins Guds röst, och håller all dessa buden, som jag bjuder dig i denna dag, att du gör derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Ty Herren din Gud skall välsigna dig, såsom han dig sagt hafver: Så skall du låna myckno folke; men af ingom skall du till låns taga; du skall blifva rådandes öfver mycket folk; men öfver dig skall ingen rådandes blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Om din broder i någon stad är fattig i dino lande, som Herren din Gud dig gifvandes varder, så skall du icke förhärda ditt hjerta eller tillycka dina hand för dinom fattiga broder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Utan skall upplycka henne honom, och låna honom, efter som honom fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Vakta dig, att i ditt hjerta icke ligger ett Belials ord, så att du säger: Det kommer snart sjunde året, som är friåret, och ser så illa ut på din fattiga broder, och får honom intet; så varder han ropandes öfver dig till Herran, och det varder dig till synd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Utan du skall låtan fåt, och ditt hjerta skall icke förtrytat, att du får honom det; ty fördenskull skall Herren din Gud välsigna dig i alla dina gerningar, och i allt det du företager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Fattige skola väl alltid vara i landena; derföre bjuder jag dig, och säger, att du skall upplycka dina hand dinom broder, som trängder och fattiger är i dino lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Om din broder, en Ebreisk eller Ebreiska, säljer sig dig, så skall han tjena dig i sex år; i sjunde årena skall du gifva honom fri lös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Och när du gifver honom fri lös, skall du icke låta honom gå med tomma händer ifrå dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Utan du skall få honom med sig af din får, af dine lado, af dinom press, så att du gifver honom af det som Herren din Gud dig med välsignat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Och tänk uppå, att du ock vast en träl i Egypti land, och Herren din Gud förlossade dig; derföre bjuder jag dig detta i denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Säger han till dig: Jag vill icke fara ut ifrå dig; ty jag unner dig och dino huse godt, efter han mår väl när dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Så tag en syl, och borra honom genom hans öra, vid dins huses dörr, och låt honom blifva din träl i evig tid; med dine trälinno skall du ock så göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Och låt dig icke tycka tungt vara, att du gifver honom fri lös; förty han hafver tjent dig såsom en dubbel legodräng, i sex år; så skall Herren din Gud välsigna dig i allt det du gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Allt förstfödt, som ibland ditt fä och får födt varder, det mankön är, det skall du helga Herranom dinom Gud; du skall icke arbeta med förstfödningen af dino fä, och icke klippa förstfödningen af din får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'För Herranom dinom Gud skall du äta dem årliga, på det rum som Herren utvalt hafver, du och ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Om det hafver någon brist, så att det haltar, eller är blindt, eller eljest någon ond vank hafver, så skall du icke offra det Herranom dinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Utan i dinom port skall du ätat, ehvad du äst ren eller oren, såsom en rå eller hjort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Allenast att du icke äter af dess blod, utan gjuter det på jordena såsom vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Håll den månaden Abib, att du gör Herranom dinom Gud Passah; förty uti Abibs månad hafver Herren din Gud fört dig utur Egypten om natten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Och du skall slagta Herranom dinom Gud Passah, får och fä, på det rum, som Herren utväljandes varder, att hans Namn der bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Du skall intet syradt bröd äta i de högtidene. I sju dagar skall du äta osyradt bedröfvelsens bröd; förty med hast gick du utur Egypti land; på det att du skall ihågkomma den dagen, som du drog utur Egypti land, i alla dina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'I sju dagar skall intet syradt bröd sedt varda i alla dina landsändar; och skall intet af köttet, som på första dagen om aftonen slagtadt vardt, blifva qvart öfver nattena intill morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Du kan icke slagta Passah någorstädes i dinom portom, som Herren din Gud dig gifvit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Utan på det rum, som Herren din Gud utväljandes varder, att hans Namn der bo skall, der skall du slagta Passah, om aftonen när solen nedergången är, vid den tiden som du utur Egypten drogst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Och du skall kokat, och ätat på det rum, som Herren din Gud utväljandes varder; och sedan om morgonen vända dig, och gå hem i dina hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'I sex dagar skall du äta osyradt, och på sjunde dagen är Herrans dins Guds församling, då skall du intet arbete göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sju veckor skall du räkna dig, och begynna räkna ifrå den dagen, när man kastar lian i sädena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Och skall hålla veckohögtid Herranom dinom Gud, att du gifver dina hands friviljoga gåfvo, efter som Herren din Gud dig välsignat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Och du skall vara glad för Herranom dinom Gud, du och din son, din dotter, din tjenare, din tjenarinna, och Leviten som är i dina portar, främlingen, den faderlöse och enkan, som ibland dig äro, på det rum som Herren din Gud utväljandes varder, att hans Namn der bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Och tänk uppå, att du hafver varit en träl i Egypten, att du håller och gör efter dessa buden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Löfhyddohögtid skall du hålla i sju dagar, när du hafver insamlat af dinom loga, och af dinom press;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Och skall vara glad på dine högtid, du och din son, din dotter, din tjenare, din tjenarinna, Leviten, främlingen, den faderlöse och enkan, som i dina portar äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'I sju dagar skall du hålla den högtiden Herranom dinom Gud, på det rum som Herren din Gud dig utväljandes varder; ty Herren din Gud skall välsigna dig i allt det du inbergar, och i alla dina händers gerningar; derföre skall du vara glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Tre resor om året skall allt det mankön är ibland dig, komma fram för Herran din Gud, på det rum som han utväljandes varder, på osyrade bröds högtidene, på veckohögtidene, och på löfhyddohögtidene; icke skall han tomhändter komma fram för Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Hvar och en efter sine hands gåfvo, efter den välsignelse, som Herren din Gud dig gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Domare och ämbetsmän skall du sätta dig i allom dinom portom, som Herren din Gud dig gifvandes varder ibland dina slägter, att de måga döma folket med rättom dom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Du skall icke böja rätten, och skall ock ingen person anse, eller mutor taga; förty mutor förblinda de visa, och förvända de rättfärdigas saker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Du skall fara efter det rätt är; på det du må lefva, och besitta det land, som Herren din Gud dig gifvandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Du skall icke någon lund af någrahanda trä plantera vid Herrans dins Guds altare, som du dig gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Du skall ingen stod uppresa, hvilket Herren din Gud hatar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Du skall icke offra Herranom dinom Gud något nöt eller får, det någon brist eller något ondt på sig hafver; förty det är Herranom dinom Gud en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Om någor funnen varder i någon af dina portar, som Herren din Gud dig gifvandes varder, man eller qvinna, den som illa gör för Herrans dins Guds ögon, så att han öfverträder hans förbund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'Och går bort, och tjenar andra gudar, och tillbeder dem, vare sig sol eller måne, eller någor himmels här, det jag icke budit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'Och det varder dig sagdt, och du hörer det, så skall du granneligen fråga derefter; och när du finner, att det visserliga sant är, att sådana styggelse skedd är i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Så skall du utföra den samma mannen eller den samma qvinnona, som sådana ondt gjort hafva, till dina portar, och skall stena dem ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Efter tu eller tre vittnes mun skall den dö, som döden värd är; men efter ett vittnes mun skall han icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Vittnens hand skall den första vara till att dräpa honom, och sedan allt folksens hand; på det att du låter den onda ifrå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Om någor sak i rätta varder dig för svår, emellan blod och blod, emellan handel och handel, emellan skada och skada, och hvad tvedrägtiga saker äro i dinom portom, så skall du stå upp, och gå upp till det rum, som Herren din Gud utväljandes varder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Och till Presterna, Leviterna, och till domaren, som den tiden är, och fråga af dem; de skola säga dig domen af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Och du skall göra efter som de säga dig före i de rumme, som Herren utväljandes varder; och skall hålla det så, att du gör efter allt det som de dig lära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Efter lagen, som de lära dig, och efter rätten, som de säga dig före, skall du hålla dig, så att du icke viker derifrå, antingen på den högra sidon, eller på den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Och om någor vore öfverdådig, så att han icke ville lyda Prestenom, som der i Herrans dins Guds ämbete står, eller domarenom, han skall dö; och du skall borttaga den onda af Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Att allt folket skall höra det, och rädas och icke mer öfverdådige vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'När du kommer uti landet, som Herren din Gud dig gifva skall, och tager det in, och bor der, och varder sägandes: Jag vill sätta en Konung öfver mig, såsom all folk omkring mig hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Så skall du den sätta för Konung öfver dig, som Herren din Gud utväljer. Du skall en af dina bröder sätta öfver dig för Konung; du kan icke sätta en främmande öfver dig, den icke din broder är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Allenast att han icke håller många hästar, och förer folket åter in i Egypten, för de många hästars skull; efter Herren eder sagt hafver, att I icke mer genom denna vägen komma skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Han skall ock icke taga sig många hustrur, att hans hjerta varder icke afvändt; och skall ej heller mycket silfver eller guld församla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Och när han nu sittandes varder på sins rikes stol, skall han taga denna andra lagen af Prestomen Levitomen, och låta den skrifva uti en bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Hon skall vara när honom, och han skall deruti läsa i alla sina lifsdagar; på det att han skall lära frukta Herran sin Gud, att han håller all denna lagsens ord, och dessa rätter, att han gör derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Han skall icke förhäfva sitt hjerta utöfver sina bröder; och skall icke vika ifrå budet, hvarken på den högra sidona, eller på den venstra; på det han skall förlänga sina dagar i sitt regemente, han och hans barn i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Presterna Leviterna, och hela Levi slägt, skola ingen lott eller arf hafva med Israel; Herrans offer och hans arfvedel skola de äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Derföre skola de intet arf hafva ibland deras bröder; ty Herren är deras arf, såsom han dem sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Och detta skall vara Presternas rättighet af folkena, och af dem som offra, ehvad det är fä eller får, att man skall gifva Prestenom bogen, och båda kindbenen, och våmbena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Och förstlingen af ditt korn, och dinom must, och dine oljo; och förstlingen af din fårs klippning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Förty Herren din Gud hafver utvalt honom utur alla dina slägter, att han stå skall i tjenstene i Herrans Namn, och hans söner evärdeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Om en Levit kommer utaf någon dina städer, eller eljest af hela Israel, der han en gäst är, och kommer af allo hans själs begärelse, till det rum som Herren utvalt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Att han vill tjena i Herrans sins Guds Namn, såsom alle hans bröder Leviterna, som der stå för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'De skola få lika del till att äta, förutan det han hafver af sina fäders sålda godse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'När du kommer uti landet, som Herren din Gud dig gifvandes varder, så skall du icke lära göra dens folksens styggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Att ingen ibland dig varder funnen, som sin son eller dotter låter gå igenom eld, eller den som är en spåman, eller en dagväljare, eller den som på foglalåt aktar, eller trollkarl;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Eller besvärjare, eller en svartkonstig, eller en tecknatydare, eller den der någon dödan frågar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Ty den som sådant gör, han är Herranom en styggelse; och för sådana styggelses skull fördrifver dem Herren din Gud för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Var utan vank inför Herranom dinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Ty detta folket, som du intaga skall, lyda de dagväljare och spåmän; men du skall icke så göra Herranom dinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'En Prophet, såsom mig, skall Herren din Gud uppväcka dig, utaf dig, och utaf dina bröder; honom skolen I lyda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Såsom du beddes af Herranom dinom Gud i Horeb, på församlingenes dag, och sade: Jag vill icke mer höra Herrans mins Guds röst, och icke mer se den stora elden, att jag icke skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Och Herren sade till mig: De hafva väl sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Jag skall uppväcka dem en Prophet, såsom du äst, utaf deras bröder, och gifva min ord i hans mun; han skall tala till dem allt det jag honom bjuda vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Och den som min ord icke hörer, som han i mitt Namn talandes varder, af honom vill jag utkräfva det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Dock om någor Prophete djerfves tala i mitt Namn, det jag honom icke befallt hafver att tala, och den som talar i andra gudars namn, den Propheten skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Om du nu säga ville i ditt hjerta: Huru kan jag märka, hvilket ord Herren icke talat hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'När den Propheten talar i Herrans Namn, och der varder intet af, och sker intet, så är det det ord, som Herren icke talat hafver. Den Propheten hafver det talat af öfverdådighet: derföre skall du icke frukta dig för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'När Herren din Gud hafver utrotat folket, hvilkets land Herren din Gud dig gifva skall, att du dem intager, och bor i deras städer och husom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Så skall du afskilja dig tre städer i landena, som Herren din Gud dig gifva skall till att intaga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Och skall utvälja belägna rum, och skifta dins lands gränsor, som Herren din Gud dig utdelandes varder, i tre delar; att dit må fly den som ett mandråp gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Och det skall vara saken, att dit skall fly den som ett mandråp gjort hafver, att han må lefva. Om någor slår sina nästa icke med vilja, och hafver tillförene intet hat haft till honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Utan såsom någor ginge med sin nästa i skogen till att hugga ved, och hofve med handene yxena upp till att hugga veden och jernet fölle af skaftet, och råkade hans nästa, så att han blefve död; den skall uti en af dessa städerna fly, och få lefva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'På det blodhämnaren icke skall fara efter dråparen, medan hans hjerta förbittradt är, och få fatt på honom, om vägen är lång, och slå hans själ; ändock han till döds icke brutit hafver, efter han tillförene intet hat till honom haft hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Derföre bjuder jag dig, att du afskiljer tre städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Och om Herren din Gud dina landsändar utvidgandes varder, såsom han dina fäder svorit hafver, och gifver dig allt det landet, som han dina fäder lofvat hafver att gifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Om du annars håller all dessa buden, att du gör derefter, som jag dig bjuder i denna dag, att du älskar Herran din Gud, och vandrar i hans vägar i dina lifsdagar, så skall du ännu tre städer lägga till dessa tre städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'På det oskyldigt blod icke skall utgjutet varda i dino lande, som Herren din Gud dig till arfs gifva skall, och blodskulder komma öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Men om någor hafver hat emot sin nästa, och vaktar efter honom, och han går åstad, och slår honom hans själ ihjäl, och flyr uti en af dessa städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Så skola de äldste i hans stad sända dit, och låta hemta honom dädan, och få honom i blodhämnarens händer, att han skall dräpas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Din ögon skola intet skona honom, och skall borttaga oskyldigt blod af Israel, på det att dig må väl gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Du skall icke dins nästas råmärke flytta, hvilka förfäderna satt hafva i dinom arfvedel, den du ärfver i landena, som Herren din Gud dig gifvit hafver att intaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Intet vittne skall ensamt framträda emot någon om någor missgerning eller synd, ehvad missgerning det är som man göra kan; utan i tvegge eller tregge vittnes mun skola alla saker stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Om ett vrångt vittne går fram emot någon, till att vittna öfver honom någon öfverträdning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Så skola de både männerna, som saken på gäller, stå för Herranom framför Presterna och domarena, som på den tiden äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Och domarena skola väl ransakat. Och om det falska vittnet hafver burit falskt vittnesbörd emot sin broder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Så skolen I göra honom, såsom han hade aktat göra sinom broder; på det att du skall skilja den onda ifrå dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Och andre skola det höra och rädas, och icke mer taga sig före sådana ondt stycke göra ibland dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Ditt öga skall icke skona honom: själ för själ, öga för öga, tand för tand, hand för hand, fot för fot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'När du drager till örlig emot dina fiendar, och får se hästar och vagnar, dess folks som är större än du, så frukta dig intet för dem; ty Herren din Gud, som dig utur Egypti land fört hafver, han är med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'När I nu kommen till strids, så skall Presten träda fram, och tala med folkena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Och säga till dem: Israel, hör härtill; I gån i dag i stridena emot edra fiendar. Edart hjerta vare icke blödigt; frukter eder intet, bäfver intet, och grufver eder intet för dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Ty Herren edar Gud går med eder, att han skall strida för eder mot edra fiendar, och hjelpa eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Men ämbetsmännerna skola tala med folket, och säga: Hvilken som ett nytt hus byggt hafver, och hafver icke ännu vigt det, han gånge sina färde, och blifve hemma; på det han icke skall blifva död i stridene, och en annar viger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Hvilken som hafver plantat en vingård, och hafver icke ännu gjort honom menligan, han gånge sina färde, och blifve hemma; på det han icke blifver död i stridene, och en annan gör honom menligan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Hvilken sig en hustru trolofvat hafver, och hafver icke ännu hemtat henne hem, den gånge sina färde, och blifve hemma; att han icke dör i stridene, och en annar hemtar henne hem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Och ämbetsmännerna skola ytterligare tala med folket, och säga: Hvilken som rädder är, och förskräckt hjerta hafver, han gånge sina färde, och blifve hemma; på det han ock icke skall göra sina bröders hjerta förskräckt, såsom hans hjerta är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Och när ämbetsmännerna uttalat hafva med folkena, så skola de skicka höfvitsmännerna för folket främst i spetsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'När du drager för en stad, till att bestrida honom, så skall du först bjuda dem frid till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Svara de dig fridliga, och låta upp för dig, så skall allt det folk, som derinne är, vara dig skattskyldigt och underdånigt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Men vilja de icke fridliga handla med dig, och vilja örliga med dig, så belägg dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Och när Herren din Gud gifver dem dig i händer, så skall du slå allt mankön, som derinne är, med svärdsegg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Utan qvinnfolk, barn och boskap, och allt det i staden är, och allt rofvet skall du byta emellan dig, och skall äta af dina fiendars byte, som Herren din Gud dig gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Alltså skall du göra med alla städer, som fast långt ifrå dig ligga, och icke äro af desso folks städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Men i desso folks städer, som Herren din Gud dig till arf gifva skall, skall du intet låta lefva det som anda hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Utan skall gifva det tillspillo, nämliga de Hetheer, Amoreer, Cananeer, Phereseer, Heveer och Jebuseer, såsom Herren din Gud dig budit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'På det att de icke skola lära eder göra all den styggelse, som de göra deras gudar, och I synden emot Herran edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Om du måste länge ligga för en stad, emot hvilken du strider, till att intagan, så skall du icke förderfva trän, så att du låter yxena komma på dem; förty du kan äta deraf, derföre skall du icke afhugga dem. Är det dock ett trä på markene, och icke menniska, och kan icke komma i bålverk emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Men de trä, som du vetst att man icke äter deraf, dem skall du förderfva och afhugga, och gör bålverk emot staden som med dig örligar, tilldess du honom öfvermägtig varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Om någon dräpen man finnes i landena, som Herren din Gud dig gifva skall till att intaga, och ligger på markene, och man icke vet ho honom dräpit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Så skola dine äldste och domare gå der ut, och mäla ifrå den dräpna, intill de städer, som deromkring ligga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Hvilken staden, som der näst är, hans äldste skola taga af boskapenom ena unga ko, der man intet med arbetat hafver, och den intet ok hafver dragit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Och de skola leda henne in på en stenogan dal, den intet hafver brukad varit, ej heller besådd, och der i dalen hugga henne halsen af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Så skola Presterna gå fram, Levi söner, ty Herren din Gud hafver utvalt dem, att de skola tjena honom, och lofva Herrans Namn, och efter deras mun skola alla saker och all slags mål handlad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Och alle äldste af den staden skola gå fram till den dräpna, och två sina händer öfver den unga kon, som i dalenom halshuggen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Och skola svara och säga: Våra händer hafva detta blodet icke utgjutit; hafva ej heller vår ögon sett det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Var nådelig dino folke Israel, som du, Herre, förlossat hafver; lägg icke detta oskyldiga blodet på ditt folk Israel. Så skola de vara försonade för det blodet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Alltså skall du lägga ifrå dig oskyldigt blod, att du skall göra det rätt är för Herrans ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'När du drager i strid emot dina fiendar, och Herren din Gud gifver dem i dina händer, att du förer dem fångna bort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Och du ser ibland de fångar en dägelig qvinno, och dig faller lust till henne, att du måtte taga henne till hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Så för henne i ditt hus, och låt raka henne håret af, och omskära hennes naglar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Och lägga de kläder af, der hon uti fången var, och låt henne sitta i dino huse, och gråta i en månad sin fader och sina moder; sedan sof när henne, och tag henne till äkta, och låt henne vara din hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Om du sedan icke hafver lust till henne, så skall du låta henne fara hvart hon vill, och icke sälja henne för penningar, eller försätta henne; derföre, att du hafver förnedrat henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Om någor hafver två hustrur, ena som han kär hafver, och ena som han hatar, och de föda honom barn, både den kära och den okära, så att det förstfödda är de okäres;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Och tiden kommer, att han skall sinom barnom utskifta arfvet, så kan han icke göra dess käres son till förstfödda son, för den okäres förstfödda son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Utan han skall bekänna den okäres son för förstfödda sonen, så att han gifver honom dubbelt af allt det på färde är; förty den samme är hans första kraft, och honom hörer förstfödslorätten till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Om någor hafver en sjelfsvörding och ohörsamman son, som faders och moders röst icke lyder, och när de tukta honom, lyder han dem intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Så skola hans fader och moder taga honom fatt, och hafva honom fram för de äldsta i staden, och till porten åt samma rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Och säga till de äldsta i staden: Denne vår son är en sjelfsvörding och ohörsam, och lyder intet våra röst, och är en fråssare och drinkare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Så skall allt folket i staden stena honom ihjäl; och alltså skall du skilja den onda ifrå dig, att hela Israel skall det höra och rädas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'När någor hafver bedrifvit en synd, den döden värd är, och varder så dödad, att man hängre honom upp i trä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Så skall hans lekamen icke blifva på trät öfver nattena; utan I skolen begrafva honom på den samma dagen; ty förbannad är den för Gud, som hängder är; på det att du icke skall orena ditt land, som Herren din Gud gifver dig till arfs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'När du dins broders oxa eller får ser vilsefara, så skall du icke draga dig derifrån; utan skall drifva dem till din broder igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Om din broder icke bor när, och du känner honom icke, så skall du taga dem in uti ditt hus, att de blifva när dig, tilldess din broder söker efter dem, och då får du honom dem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Sammalunda skall du göra med hans åsna, med hans kläde, och med allt det som tappadt är, det din broder mist hafver, och du finner det; drag dig icke derifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Om du ser dins broders åsna eller oxa falla på vägenom, så skall du icke draga dig derifrån; utan skall hjelpa honom upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'En qvinna skall icke bära mans tyg, och en man skall icke draga qvinnokläder uppå; ty den som det gör, är Herranom dinom Gud en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Om du råkar på vägen ett foglabo, på eno trä eller på jordene, med ungar eller med ägg, och modren sitter på ungarna eller på äggen, så skall du icke taga modren med ungarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Utan skall låta modren flyga, och taga ungarna; att dig må gå väl, och du må länge lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'När du bygger ett nytt hus, så gör såsom en värn ofvanomkring på taket, att du icke indrager blod på ditt hus, om någon faller deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Du skall icke så din vingård med mångahanda, att du icke helgar till fyllelse sådana säd, som du sått hafver ibland vingårdsens frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Du skall icke plöja tillhopa med en oxa och med en åsna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Du skall icke utikläda dig en klädning, som af ull och lin tillsammans kommen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Du skall göra dig klutar i fyra hörnen på din mantel, som du hafver på dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Om någor tager ena hustru, och sedan han henne belägrat hafver, får ledo till henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'Och kastar henne något slemt före, och förer henne ett rykte uppå, och säger: Denna qvinnona hafver jag tagit, och när jag ingick till henne, fann jag att hon icke var jungfru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Så skola fader och moder åt qvinnone taga henne, och bära fram qvinnones jungfruskap inför de äldsta i stadenom, som i porten sitta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Och qvinnones fader skall säga till de äldsta: Jag hafver gifvit denna mannenom mina dotter till hustru; nu är han henne vorden hätsk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Och kastar henne skamlig ting före, och säger: Jag hafver icke funnit dina dotter jungfru; detta är mina dotters jungfruskap. Och de skola utbreda klädet för de äldsta i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Så skola de äldste i stadenom taga mannen och näpsa honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Och sakfälla honom till hundrade siklar silfver, och gifva dem qvinnones fader, derföre att han hafver beryktat ena jungfru i Israel; och han skall hafva henne till hustru, så att han icke skall öfvergifva henne i alla sina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Är det ock sant, att qvinnan icke är funnen jungfru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Så skall man föra henne ut för hennes faders husdörr, och folket i staden skola stena henne till döds, derföre att hon hafver bedrifvit en galenskap i Israel, och hafver bolat i hennes faders hus; och skall bortkasta det onda ifrå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Om någor varder befunnen, att han ligger när en hustru, som en äkta man hafver, så skola de både dräpas, mannen och qvinnan, som han när legat hafver; och skall taga bort det onda af Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Om en piga är enom manne trolofvad, och någor kommer i färd med henne i stadenom, och ligger när henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Så skall du föra dem båda ut till stadsporten, och skall stena dem båda till döds; pigona fördenskull, att hon icke ropade, efter hon var i stadenom; mannen fördenskull, att han sins nästas hustru skämt hafver; och skall kasta det onda bort ifrå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Om någor finner en förlofvad pigo på markene, och tager henne fatt, och ligger när henne; så skall mannen allena dräpas, som låg när henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Och pigone skall du intet göra; ty hon hafver ingen synd gjort, som döden värd är; utan lika som någor hofve sig upp emot sin nästa, och sloge hans själ ihjäl, så är detta ock;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Ty han fann henne på markene, och den förlofvade pigan ropade, och ingen var som henne halp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Om någor kommer till en jungfru som intet trolofvad är, och får henne fatt och ligger när henne, och det varder funnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Så skall han, som när henne låg, gifva hennes fader femtio siklar silfver, och skall hafva henne till hustru, derföre att han hafver förnedrat henne; han må icke öfvergifva henne i hans lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Ingen skall taga sins faders hustru, och icke upptäcka sins faders täckelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Ingen förbråken eller snöpt skall komma in i Herrans församling.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Skall ock ingen skökoson komma i Herrans församling, ja ock efter tionde led; utan skall platt intet komma i Herrans församling.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'De Ammoniter och Moabiter skola icke komma in i Herrans församling; ja ock efter tionde led; aldrig skola de komma in i Herrans församling;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Derföre, att de icke ville möta dig med bröd och vatten på vägen, då I drogen utur Egypten; och dertill lejde emot eder Bileam, Beors son, den spåmannen utaf Mesopotamien, att han skulle förbanna dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Men Herren din Gud ville icke höra Bileam; och Herren din Gud förvände dig den förbannelsen uti välsignelse; derföre, att Herren din Gud hade dig kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Du skall dem hvarken godt eller äro bevisa i alla dina lifsdagar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Edomeen skall du icke för styggelse hålla; ty han är din broder. Egyptien skall du ej heller hålla för styggelse; ty du hafver varit en främling i hans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'De barn, som af dem födde varda i tredje led, de måga komma in uti Herrans församling.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'När du utdrager utu lägret emot dina fiendar, så tag dig vara för allt ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Är någor ibland dig, som icke är ren, att honom om natten något vederfaret är, han skall gå ut för lägret, och icke igen inkomma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Förra än han mot aftonen tvår sig i vatten; och när solen nedergången är, skall han åter komma i lägret igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Utanför lägret skall du hafva en plats, der du ut uppå går till dina tarfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Och skall hafva en staka vid bältet, och när du dig derute sätta vill, skall du grafva dermed; och när du sutit hafver, skall du med mullene öfverskyla det af dig gånget är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Ty Herren din Gud vandrar i dino lägre, att han skall frälsa dig, och gifva dina fiendar för dig; derföre skall ditt lägre vara heligt, att ingen skam skall sedd vara ibland dig, och han vänder sig ifrå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Du skall icke igen antvarda husbondanom tjenaren, som ifrå honom flyr till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Han skall blifva när dig på det rum, som honom täckes i någon af dina portar, sig till godo, och skall icke bedröfva honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Ingen sköka skall vara ibland Israels döttrar, och ingen bolare ibland Israels söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Du skall icke bära skökolön eller hundapenningar uti Herrans dins Guds hus, af någrahanda löfte; ty både äro Herranom dinom Gud en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Du skall icke ockra på dinom broder, antingen med penningar eller fetalia, eller med någon ting, der man med ockra kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'På dem främmande må du ockra, men icke på dinom broder; på det Herren din Gud skall välsigna dig i allt det du företager i landena, dit du kommer till att intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'När du gör Herranom dinom Gud ett löfte, så skall du icke fördröja att hålla det; ty Herren din Gud varder det utkräfvandes af dig; och det blifver dig räknadt till synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Om du intet löfte lofvar, så är det dig ingen synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Hvad af dina läppar utgånget är, det skall du hålla, och göra derefter, såsom du Herranom dinom Gud med fri vilja lofvat hafver, det du med dinom mun talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'När du går i dins nästas vingård, så må du äta af vinbären så mycket dig täckes, tilldess du blifver mätt; men du skall intet taga med dig i dino kärile.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'När du går i dins nästas säd, så må du afplocka ax; men med lian skall du icke gå dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Om någor tager sig hustru, och äktar henne, och hon icke finner ynnest för hans ögon, för någon olusts skull, så skall han skrifva ett skiljobref, och få henne i handena, och låta henne utu sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'När hon utu hans hus gången är, och går till och blifver ens annars mans hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Och den samme andre mannen varder henne ock ogunstig, och skrifver ett skiljobref och får henne i handena, och låter henne utu sitt hus; eller om den samme andre mannen dör, som henne till hustru tog;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Så kan hennes förste man, som henne utdref, icke taga henne igen, att hon blifver hans hustru, efter det att hon är oren; ty det är en styggelse för Herranom; på det att du icke skall komma landet i synd, som Herren din Gud dig till arfs gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Om någor hafver nyliga tagit sig hustru, han skall icke draga ut i härfärd, och man skall intet lägga honom uppå; han skall vara fri i sino huse ett år igenom, att han må vara glad med sine hustru, som han tagit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Du skall intet till pant taga understenen och öfverstenen i qvarnene; ty han hafver satt dig själena till pant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Om någor varder funnen den som stjäl ena själ utaf sina bröder utaf Israels barnom, och försätter eller säljer henne, den tjufven skall dräpas; att du skiljer det onda ifrå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Tag dig vara för den plågon spitelskona, att du med flit håller och gör allt det som Presterna Leviterna lära dig, och jag dem budit hafver; det skolen I hålla, och göra derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Kom ihåg hvad Herren din Gud gjorde med MirJam på vägenom, då I drogen utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Om du något borgar dinom nästa, så skall du icke gå i hans hus, och taga honom en pant af;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Utan du skall stå utanföre, och den som du borgat hafver, skall bära sin pant ut till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Är han nödställd, så skall du icke gå och lägga dig sofva med hans pant;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Utan skall gifva honom hans pant igen, när solen nedergår, att han må sofva i sin kläder, och välsigna dig; det varder dig räknadt för Herranom dinom Gud till rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Du skall icke förhålla lönen för den som torftig och fattig är ibland dina bröder; eller för främlingenom, som i dino lande eller i dina portar är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Utan skall gifva honom samma dagen sin lön, att solen dermed icke nedergår, efter han nödställd är, och dermed uppehåller sina själ; på det han icke skall ropa till Herran öfver dig, och det varder dig till synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Fäderna skola icke dö för barnen, ej eller barnen för fäderna; utan hvar och en skall dö för sina synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Du skall icke böja främlingens, eller dens faderlösas rätt; och skall icke taga enkone hennes kläder af till pant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Ty du skall ihågkomma, att du hafver varit en träl i Egypten, och Herren din Gud hafver dig dädan löst; derföre bjuder jag dig, att du detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'När du hafver bergat af dinom åker, och du en kärfva förgätit hafver på åkrenom, så skall du icke omvända och taga honom; utan han skall höra främlingenom, dem faderlösa och enkone till; på det att Herren din Gud skall välsigna dig i all din händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'När du afrist hafver af ditt oljoträ, så skall du icke sedan på nytt afrista; det skall höra främlingenom, dem faderlösa och enkone till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'När du din vingård afbergat hafver, så skall du icke sedan på nytt hemta; det skall höra främlingenom, dem faderlösa och enkone till;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Och skall ihågkomma, att du hafver varit en träl i Egypti land; derföre bjuder jag dig, att du detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Om en träta är emellan män, så skall man hafva dem fram för rätten, och döma emellan dem, och gifva dem rättfärdiga rätt, och den ogudaktiga fördöma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Och om den ogudaktige hafver förtjent hugg, skall domaren bjuda honom falla neder, och de skola inför honom slå honom, efter det mått och tal, som missgerningen kräfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'När man honom fyratio slag gifvit hafver, skall man icke mer slå; på det, om man mer slår, han icke skall förmycket slagen varda, och din broder styggelig varder för din ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Du skall icke binda munnen till på oxanom, som tröskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'När bröder bo tillhopa, och en dör utan barn, så skall dens dödas hustru icke taga någon främmande man utantill; utan hennes svåger skall ingå till henne, och taga henne till hustru, och befrynda henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Och den förste sonen, som hon föder, skall nämnas efter hans döda broder; att hans namn icke nederlägges i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Om mannenom icke täckes, att han tager sina svägersko, så skall hans svägerska uppgå till porten för de äldsta, och säga: Min svåger nekar sig vilja uppväcka sinom broder namn i Israel, och vill icke hafva mig till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Så skola de äldste i stadenom låta kalla honom, och tala med honom. Om han då står, och säger: Mig faller icke i sinnet att taga henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Så skall hans svägerska träda till honom inför de äldsta, och draga honom en sko af hans fötter, och spotta uppå honom, och skall svara och säga: Så skall man göra hvarjom och enom, som sins broders hus icke uppbygga vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Och hans namn skall heta i Israel: Dens barföttes hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Om två män träta tillhopa, och ensderas hustru löper till, att hon vill undsätta sin man ifrå hans hand som honom slår, och räcker sina hand ut, och fatter honom om hans hemlig ting;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Så skall du hugga henne handena af, och ditt öga skall icke skona henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Du skall icke hafva tveggehanda vigt i dinom säck, större och mindre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Och i dino huse skall icke vara tveggehanda skäppa, större och mindre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Du skall hafva ena fulla och rätta vigt, och ena fulla och rätta skäppo; på det att du skall länge lefva på landena, som Herren din Gud dig gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Ty den som detta gör, han är Herranom dinom Gud en styggelse; såsom ock alle de som illa göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Kom ihåg hvad de Amalekiter gjorde dig uppå vägenom, då I drogen utur Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Huru de kommo emot dig på vägenom, och slogo dina eftersta, alla de svaga som efterst drogo, när du mödd och trött vast, och de fruktade icke Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'När nu Herren din Gud låter dig komma till ro ifrån alla dina fiendar omkring dig i landena, som Herren din Gud dig gifver till arfs till att intaga, så skall du utskrapa de Amalekiters åminnelse under himmelen; det förgät icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'När du kommer in i landet, som Herren din Gud dig till arfs gifva skall, och du tager det in, och bor der;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Så skall du taga allahanda landsens första frukter, som af jordene komma, som Herren din Gud dig gifver, och skall lägga dem uti en korg, och gå bort på det rum, som Herren din Gud utväljandes varder, att hans Namn der bo skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Och skall gå till Presten, som på den tiden är, och säga till honom: Jag förkunnar på denna dag Herranom dinom Gud, att jag är kommen in uti det land, som Herren vårom fädrom svorit hafver till att gifva oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Och Presten skall taga korgen utu dine hand, och sätta honom ned för Herrans dins Guds altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Då skall du svara, och säga för Herranom dinom Gud: De Syrer ville förgöra min fader, han drog neder i Egypten, och var der en främling med fögo folk; och vardt der ett stort, starkt och mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Men de Egyptier handlade illa med oss, och tvingade oss, och lade en hård träldom på oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Då ropade vi till Herran våra fäders Gud, och Herren hörde vårt rop, och såg vårt elände, ångest och nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Och Herren förde oss utur Egypten med väldiga hand och uträcktom arm, och med stor förfärelse genom tecken och under;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Och förde oss på detta rummet, och gaf oss detta landet, der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Och derföre bär jag nu här fram landsens första frukt, som du, Herre, mig gifvit hafver. Och så skall du låta det der för Herranom dinom Gud, och tillbedja för Herranom dinom Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Och vara glad öfver allt det goda, som Herren din Gud hafver gifvit dig, och dino huse, du och Leviten, och främlingen som när dig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'När du hafver tillhopasamlat allan tionden af din årsväxt i tredje årena, hvilket är ett tiondeår, så skall du gifva Levitenom, främlingenom, dem faderlösa och enkone, att de måga äta i dinom port, och varda mätte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Och skall säga för Herranom dinom Gud: Jag hafver här framburit det som helgadt är af mino huse, och hafver gifvit det Levitenom, främlingenom, dem faderlösa och enkone, efter allt ditt bud, som du mig budit hafver; jag hafver icke gått utöfver ditt bud, eller förgätit det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Jag hafver icke ätit deraf i mine sorg; jag hafver intet tagit deraf i orenlighet; jag hafver intet deraf gifvit till de döda; jag hafver varit Herrans mins Guds röst hörig, och hafver gjort allt det du mig budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Se här neder af dine helga boning af himmelen, och välsigna ditt folk Israel, och landet som du oss gifvit hafver, såsom du våra fäder svorit hafver, ett land der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'I dag hafver Herren din Gud budit dig, att du efter all dessa bud och rätter göra skall, så att du håller dem, och gör derefter af allo hjerta, och af allo själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Herranom hafver du det tillsagt i denna dag, att han skall vara din Gud, och du skall vandra i hans vägar, och hålla hans lag, bud och rätter, och lyda hans röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Herren hafver dig tillsagt i dag, att du skall vara hans eget folk, såsom han dig sagt hafver; att du skall hålla all hans bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Och han skall göra dig det högsta, och du varder prisad, lofvad och ärad, öfver allt folk som han gjort hafver; på det du skall vara Herranom dinom Gud ett heligt folk, såsom han sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Och Mose, samt med de äldsta i Israel, böd folkena, och sade: Behåller all de bud, som jag bjuder eder i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Och på den tiden, när I öfver Jordan dragen in i landet, som Herren din Gud dig gifvandes varder, skall du uppresa stora stenar, och plåstra dem med kalk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Och derpå skrifva all dessa lagsens ord, när du deröfver kommer; på det du skall komma i landet, som Herren din Gud dig gifva skall, ett land der mjölk och hannog uti flyter; såsom Herren dina fäders Gud dig sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'När I nu gån öfver Jordan, så skolen I sådana stenar uppresa, om hvilka jag eder i dag bjuder, på det berget Ebal, och plåstra dem med kalk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Och skall dersammastäds uppbygga Herranom dinom Gud ett altare af sten, der intet jern kommer vid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Af helom stenom skall du bygga det altaret Herranom dinom Gud, och offra deruppå bränneoffer Herranom dinom Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Och skall offra tackoffer, och dersammastäds äta, och vara glad för Herranom dinom Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Och skall skrifva på stenarna all dessa lagsens ord, klarliga och ljusliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Och Mose, samt med Presterna Leviterna, talade med hela Israel, och sade: Märk och hör till, Israel; på denna dagen äst du vorden Herrans dins Guds folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Att du skall lydig vara Herrans dins Guds röst, och göra efter hans bud och rätter, som jag bjuder dig i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Och Mose böd folkena på samma dagen, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Desse skola stå på det berget Grisim, till att välsigna folket, när I öfver Jordan gångne ären: Simeon, Levi, Juda, Isaschar, Joseph och BenJamin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Och desse skola stå på det berget Ebal, till att förbanna: Ruben, Gad, Asser, Sebulon, Dan och Naphthali.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Och Leviterna skola begynna, och säga till hvar man af Israel med klara röst:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Förbannad vare den som gör en afgud eller gjutet beläte, Herrans styggelse; ett verk, som konstnärers händer gjort hafva, och sätter det hemliga; och allt folket skall svara och säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Förbannad vare den som bannar sin fader eller moder; och allt folket skall svara och säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Förbannad vare den som flyttar sins nästas råmärke; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Förbannad vare den som låter en blindan fara vill på vägenom; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Förbannad vare den som böjer främlingens, dens faderlösas och enkones rätt; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Förbannad vare den som ligger när sins faders hustru, att han upptäcker sins faders täckelse; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Förbannad vare den som beligger någon fänad; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Förbannad vare den som ligger när sina syster, den hans faders eller moders dotter är; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Förbannad vare den som ligger när sina sväro; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Förbannad vare den som slår sin nästa hemliga; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Förbannad vare den som tager mutor, att han ens oskyldigs blods själ slå skall; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Förbannad vare den som icke fullkomnar all denna lagsens ord, så att han gör derefter; och allt folket skall säga: Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Och om du Herrans dins Guds röst lydig äst, att du behåller och gör all hans bud, som jag bjuder dig i dag; så skall Herren din Gud göra dig högst öfver allt folk på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Och all denna välsignelsen skola komma öfver dig, och drabba på dig, derföre att du hafver varit Herrans dins Guds röst hörig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Välsignad skall du vara uti stadenom, välsignad på åkrenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Välsignad skall vara dins lifs frukt, dins lands frukt, och frukten af dinom boskap, frukten af ditt fä, frukten af din får;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Välsignad varder din korg, och dina öfverlefvor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Välsignad skall du vara, när du ingår; välsignad, när du utgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Och Herren skall dina fiendar, som sig emot dig resa, låta falla för dig; på en väg skola de komma ut emot dig, och på sju vägar fly för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Herren skall bjuda välsignelsen, att hon är med dig i ditt visthus, och i allt det du företager; och skall välsigna dig i landena, som Herren din Gud dig gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Herren skall upprätta dig sig till ett heligt folk, såsom han dig svorit hafver; derföre, att du Herrans dins Guds bud håller, och vandrar i hans vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Att all folk på jordene skola se, att du nämnd är efter Herrans Namn; och skola frukta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Och Herren skall göra, att du skall öfverflöda i alla ägodelar; i dine lifs frukt, i dins boskaps frukt, i dins åkers frukt, på landena som Herren dina fäder svorit hafver dig till att gifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Och Herren skall öppna dig sina goda håfvor, himmelen, att han skall gifva dino lande regn i sinom tid, och att han skall välsigna all dina händers verk; och du skall låna mycket folk, och du skall taga till låns af ingom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Och Herren skall göra dig till hufvud, och icke till stjert, och skall alltid sväfva ofvanuppå, och icke underligga; derföre, att du äst lydig Herrans dins Guds bud, som jag dig bjuder i denna dag, till att hålla och göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Och hafver icke vikit ifrå något det ord, som jag bjuder dig i dag, hvarken på den högra sidon, eller på den venstra, så att du efterföljde andra gudar, till att tjena dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Om du ock icke lyder Herrans dins Guds röst, så att du håller och gör all hans bud och rätter, som jag bjuder dig i dag, så skola all denna förbannelsen komma öfver dig, och drabba på dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Förbannad skall du vara i stadenom; förbannad på åkrenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Förbannad skall vara din korg, och dina öfverlefvor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Förbannad skall vara dins lifs frukt, dins lands frukt, frukten af ditt fä, frukten af din får;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Förbannad skall du vara, när du ingår: förbannad, när du utgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Herren skall sända ibland dig armod, ofrid och oråd, öfver allt det du tager dig före att göra, tilldess han förgör dig, och förderfvar dig snarliga, för dina onda gerningars skull, att du mig öfvergifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Herren skall låta pestilentie låda vid dig, tilldess han gör ända med dig på landena, dit du kommer till att intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Herren skall slå dig med svullnad, skälfvo, hetta, bränno, torrhet och blekhet; och skall förfölja dig, tilldess han förgör dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Himmelen, som öfver ditt hufvud är, skall vara som koppar; och jorden under dig såsom jern.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Herren skall gifva dino lande stoft och asko för regn af himmelen öfver dig, tilldess han förgör dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Herren skall låta slå dig för dina fiendar; på en väg skall du draga ut till dem, och på sju vägar skall du fly ifrå dem; och skall varda förströdd kringom all rike på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Din lekamen skall till mat vara allom himmelens foglom, och allom vilddjurom på jordene, och ingen skall vara, som dem afdrifver,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Herren skall slå dig med Egyptes böld, med fikbölder, med skabb och klåda, så att du icke skall kunna varda hel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Herren skall slå dig med ursinnighet, blindhet, och hjertans rasande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Och du skall famla om middagen, såsom en blinder famlar i mörkret, och skall ingen lycko hafva på dina vägar; och skall lida våld och orätt så länge du lefver, och ingen skall hjelpa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Du skall trolofva dig hustru, men en annar skall sofva när henne; du skall bygga dig hus, men en annar skall bo deruti; du skall plantera vingård, men du skall icke bergan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Din oxe skall för din ögon slagtad varda, men du skall intet få äta af honom; din åsne skall för din ögon med våld tagen varda, och skall dig intet igengifven varda; din får skola varda gifne dinom fiendom, och ingen skall hjelpa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Dine söner och dina döttrar skola andro folke gifne varda, så att din ögon skola se deruppå, och uppgifvas öfver dem dagliga; och ingen starkhet skall vara i dina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Frukten af dino lande, och allt ditt arbete skall ett folk förtära, som du intet känner; och du skall orätt lida, och förtryckt varda i alla dina dagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Och skall ursinnig blifva för sådana syn, som din ögon se skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Herren skall slå dig med en ond böld på knän, och uppå benkalfvana, att du icke skall kunna helas ifrå fotbjellet intill hjessan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Herren skall drifva dig och din Konung, som du öfver dig satt hafver, till ett folk, som du intet känner eller dina fäder; och der skall du tjena andra gudar, stockar och stenar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Och skall varda till en grufvelse, och till ett ordspråk och gabberi ibland all folk, dit Herren dig drifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Du skall mycken säd föra ut på markena, och litet införa; ty gräshoppor skola det uppäta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Du skall plantera och bruka vingård, men intet vinet dricka eller hemta; ty matkar skola förtärat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Du skall hafva oljoträ i allom dinom landsändom, men du skall icke smörja dig med oljone; ty ditt oljoträ skall uppryckt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Söner och döttrar skall du föda, och dock intet hafva dem; ty de skola varda bortförde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'All din trä och dins lands frukt skall ohyra förtära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Främlingen, som när dig är, skall stiga öfver dig, och alltid blifva öfverst; men du skall stiga neder, och alltid ligga under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Han skall låna dig, men du skall intet låna honom: han skall vara hufvudet, och du skall vara stjerten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Och all denna förbannelsen skola komma öfver dig, och förfölja dig, och drabba uppå dig, tilldess du blifver omintet; derföre, att du Herrans dins Guds röst icke hört hafver, att du måtte hållit hans bud och rätter, som han dig budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Derföre skola tecken och under varda på dig och dine säd till evig tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Att du icke hafver tjent Herranom dinom Gud med gladt och lustigt hjerta, då du allahanda nog hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Och du skall tjena dinom fienda, som Herren dig tillskickandes varder, i hunger och törst, i nakenhet och allahanda nöd; och han skall lägga på din hals ett jernok, tilldess han förgör dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Herren skall låta folk komma på dig fjerranefter ifrå verldenes ända, såsom en örn flyger, hvilkets mål du icke förstå kan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Ett skamlöst folk, det icke skall hafva försyn för dens gamlas person, ej heller mildt är för den unga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Och skall förtära fruktena af din boskap, och fruktena af ditt land, tilldess han förgör dig; och skall intet låta dig qvart blifva, i korn, vin, oljo, i frukt af fä eller får, tilldess han gör dig omintet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Och skall tränga dig i alla dina portar, tilldess han nederlägger dina höga och fasta murar, der du på förlåter dig i allo dino lande; och du skall trängd varda i alla dina portar, i hela dino lande, som Herren din Gud dig gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Du skall äta fruktena af ditt eget lif; dins sons och dine dotters kött, som Herren din Gud dig gifvit hafver, i den ångest och nöd, som din fiende dig uti tvinga skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Så att en man, som tillförene kräseliga och i mycken vällust ibland eder lefvat hafver, skall missunna sinom broder, och hustrune som i hans famn är, och sonenom som ännu igenlefder är af hans söner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Att gifva någromdera af sins sons kött, der han af äter; efter han nu intet mer hafver af alla sina ägodelar, i den ångest och nöd, som din fiende dig med tvinga skall uti alla dina portar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'En qvinna ibland eder, som tillförene kräseliga och i vällust lefvat hafver, så att hon icke hafver försökt sätta sin fot på jordena för kräselighets och vällusts skull, hon skall icke unna mannenom som i hennes famn är, och sinom son, och sine dotter,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Efterbördena, som emellan hennes ben utgången är; ja, ock sina söner, som hon födt hafver; förty de skola äta dem hemliga, för allahanda brists skull, i den ångest och nöd, med hvilko din fiende dig tvinga skall i dina portar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Om du icke håller och gör all dessa lagsens ord, som i denna bokene skrifne äro, så att du fruktar detta härliga och förskräckeliga Namnet, Herran din Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Så skall Herren underliga hafva sig med dig, med plågo på dig och dina säd, med stora och långsamma plågor, med onda och långsamma krankheter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Och skall vända till dig alla de Egyptiska sjukdomar, der du rädes före; och de skola låda vid dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Dertill alla krankheter, och alla plågor, som icke skrifne äro i denna lagbok, skall Herren låta komma öfver dig, tilldess att han förgör dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Och fögo folk skall öfverblifva af eder, som tillförene voren såsom stjernorna på himmelen, för myckenhets skull; derföre, att du icke lydt hafver Herrans dins Guds röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Och såsom Herren tillförene fröjdade sig öfver eder, att han gjorde eder godt, och förökade eder; så skall Herren fröjda sig öfver eder, att han förderfvar eder, och omintetgör; och I varden förstörde ifrå landena, der du nu indrager till att intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Ty Herren skall förskingra eder ibland all folk, ifrå den ena verldenes ända till den andra; och der skall du tjena andra gudar, som du intet känner, eller dine fäder, stock och sten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Och ibland de folk skall du intet visst hemman hafva, och din fotbjelle skola ingen hvilo få; ty Herren skall gifva dig der ett bäfvande hjerta, och vanmägtig ögon, och en förvissnada själ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Så att ditt lif skall vara hängandes för dig; dag och natt skall du rädas, och skall icke vara viss på ditt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Om morgonen skall du säga: Ack! det jag måtte lefva till aftonen; och om aftonen skall du säga: Ack! det jag måtte lefva till morgonen, för dins hjertas stora räddhåga, som dig förskräcka skall, och för det som du med din ögon se skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Och Herren skall föra dig skeppom full åter in uti Egypten på den vägen, om hvilken jag sade: Du skall icke mer se honom; och skolen varda sålde edrom fiendom till trälar och trälinnor, och der skall ingen vara, som köpa vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Desse äro förbundsens ord, som Herren böd Mose att göra med Israels barnom, uti de Moabiters land, annan gång, sedan han det samma med dem gjort hade i Horeb.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Och Mose kallade hela Israel, och sade till dem: I hafven sett allt det Herren för edor ögon gjort hafver i Egypten, Pharao, med alla hans tjenare, och hela hans land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'De stora frestelser, som din ögon sett hafva; och det var stor tecken och under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Och Herren hafver ännu intill denna dag icke gifvit dig ett hjerta, som förståndigt vore; ögon, som se kunde, och öron, som höra kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Han hafver låtit eder vandra i öknene i fyratio år; edor kläder äro icke förslitne vordne på eder, och dina skor äro icke föråldrade på dina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'I åten intet bröd, och intet vin drucken, eller starka drycker, på det att du skulle veta, att jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Och då I kommen på detta rummet, drog ut Sihon, Konungen i Hesbon, och Og, Konungen i Basan, till att strida med oss, och vi sloge dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Och toge deras land in, och gåfvom det de Rubeniter och Gaditer, och den halfve slägtene af de Manassiter till arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Så håller nu detta förbunds ord, och görer derefter, på det I skolen visliga handla i allt det I gören.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'I stån alle i dag för Herranom edrom Gud; de öfverste i edra slägter, edre äldste, edre ämbetsmän, hvar och en i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Edra barn, edra qvinnor, främlingen som i ditt lägre är, både din vedahuggare, och din vattudragare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Att du skall ingå uti Herrans dins Guds förbund, och i den ed som Herren din Gud med dig gör i dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'På det han skall i denna dag upprätta dig sig till folk; och han skall vara din Gud, såsom han dig sagt hafver, och såsom han dina fäder, Abraham, Isaac och Jacob, svorit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Ty jag gör icke detta förbundet och denna eden med eder allena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Utan både med eder, som i dag här ären, och stån här med oss för Herranom vårom Gud, och med dem som i dag här icke med oss äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Förty I veten huru vi bodde i Egypti land, och droge midt igenom Hedningarna, genom hvilka I foren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Och sågen deras styggelse, och deras afgudar, stock och sten, silfver och guld, som när dem var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Att tilläfventyrs icke någor är ibland eder, man eller qvinna, eller en slägt, eller ätt, som sitt hjerta i dag vändt hafver ifrå Herranom vårom Gud, så att han vill bortgå, och tjena dessa folks gudar, och varder tilläfventyrs en rot ibland eder, som galla och malört bär;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Och ändock han än hörer denna förbannelsens ord, välsignar han sig likaväl i sino hjerta, och säger: Det varder icke än så ondt; jag vill vandra såsom mitt hjerta täckes; och varda alltså de druckne med de törstiga förtappade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Då skall Herren icke vara honom nådelig; utan då skall Herrans vrede och nit hämnas öfver den mannen, och på honom skola all denna förbannelsen lägga sig, som i denna bokene skrifne äro; och Herren skall utskrapa hans namn under himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Och Herren skall afskilja honom till det ondt är, utur all Israels slägter, efter all förbundsens förbannelse, som i desso lagbok skrifne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Och så skall då edor afföda säga edor barn, som efter eder uppkomma, och de främmande, som fjerran långvägs komma, när de se detta landsens plågo, och de krankheter, som Herren dem med besvärat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Att han allt deras land med svafvel och salt förbränt hafver, så att det icke kan sådt varda, ej heller växer, ej heller någon ört uppgår, lika som Sodom, Gomorra, Adama och Zeboim omstörte äro, hvilka Herren i sine vrede och grymhet omstörte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Så skola all folk säga: Hvi hafver Herren så gjort desso landena? Hvad är denna hans stora grymma vrede?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Då skall man säga: Derföre, att de hafva gått ifrå Herrans deras fäders Guds förbund, som han med dem gjort hade, då han förde dem utur Egypti land,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Och de äro bortgångne, och hafva tjent andra gudar, och tillbedit dem; sådana gudar, som de intet kände, och dem de intet tillhörde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Derföre hafver Herrans vrede förgrymmat sig öfver detta land, så att han hafver låtit komma öfver dem all de förbannelser, som i denna bok skrifne stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Och Herren hafver drifvit dem utu deras land med stora vrede, grymhet och ogunst, och kastat dem uti ett annat land, såsom det i denna dag befinnes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Herrans vår Guds hemlighet är uppenbarad oss och vårom barnom till evig tid, att vi all dessa lagsens ord göra skole.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'När nu allt detta kommer öfver dig, antingen välsignelsen eller förbannelsen, som jag dig föresatt hafver, och du begynner lägga på hjertat, huru du äst ibland Hedningar, dit Herren din Gud dig fördrifvit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'Och du omvänder dig till Herran din Gud, så att du lyder hans röst, du och din barn, af allo hjerta, och af allo själ, i allt det som jag bjuder dig i denna dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Så skall Herren din Gud vända ditt fängelse, och förbarma sig öfver dig, och skall åter församla dig utur all folk, dit Herren din Gud dig förskingrat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Om du vore bortdrifven allt intill himmelens ända, så skall dock Herren din Gud församla dig dädan, och hemta dig dädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Och Herren din Gud skall låta dig komma i det land, som dine fäder besutit hafva; och du skall det intaga, och han skall göra dig godt, och föröka dig öfver dina fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Och Herren din Gud skall omskära ditt hjerta, och dine säds hjerta, att du Herran din Gud älska skall af allo hjerta, och af allo själ; på det att du må lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Men denna förbannelsen skall Herren din Gud alla låta komma uppå dina fiendar, och uppå dem som dig hata och förfölja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Men du skall omvända dig, och lyda Herrans röst, att du gör all hans bud, som jag bjuder dig i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Och Herren din Gud skall gifva dig lycko i alla dina händers gerningar; i dins lifs frukt, i dins boskaps frukt, i dins lands frukt, att det kommer dig till godo; ty Herren skall vända sig, så att han skall fröjda sig öfver dig, dig till godo, såsom han sig öfver dina fäder fröjdat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Derföre, att du Herrans dins Guds röst lyder, till att hålla hans bud och rätter, som skrifne äro i desso lagbok; såframt du vänder dig till Herran din Gud af allo hjerta, och af allo själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Ty det budet, som jag bjuder dig i dag, är dig icke fördoldt, ej heller för fjerran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Ej heller i himmelen, så att du måtte säga: Ho vill fara oss upp i himmelen, och hemta oss det, att vi måge hörat och görat?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Det är icke heller på hinsidon hafvet, så att du måtte säga: Ho vill fara oss öfver hafvet, och hemta oss det, att vi måge hörat och görat?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Ty ordet är ganska hardt när dig, i dinom mun, och i dino hjerta, att du det göra må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Si, jag hafver i dag satt dig före lifvet, och det goda; döden, och det onda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Det jag bjuder dig i dag, att du skall älska Herran din Gud, och vandra i hans vägar, och hålla hans bud, lag och rätter, och få lefva, och varda förökad; och Herren din Gud skall välsigna dig i landena, der du indrager till att intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Men vänder du ditt hjerta, och lyder icke, utan låter förföra dig, så att du tillbeder andra gudar, och tjenar dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Så förkunnar jag eder i dag, att I skolen förgås, och icke länge blifva i landena, der du indrager öfver Jordan, det att intaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Jag tager i dag himmel och jord till vittne öfver eder, jag hafver satt eder före lifvet och döden, välsignelse och förbannelse, att du skall utvälja lifvet, och du och din säd mågen lefva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Att I skolen älska Herran edar Gud, och lyda hans röst, och hålla eder intill honom; ty det är ditt lif, och din långa ålder, att du må bo i landena, som Herren dina fäder, Abraham, Isaac och Jacob, svorit hafver dem att gifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Och Mose gick bort, och talade dessa orden med hela Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Och sade till dem: Jag är i dag hundrade och tjugu åra gammal; jag kan icke mer ut och in gå; dertill hafver Herren sagt till mig: Du skall icke gå öfver denna Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Herren din Gud skall sjelfver gå för dig; han skall sjelf förgöra dessa folk för dig, så att du skall taga dem in; Josua skall gå för dig deröfver, såsom Herren sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Och Herren skall göra dem, såsom han gjort hafver Sihon och Og, de Amoreers Konungar, och deras lande, hvilka han förgjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'När nu Herren gifver dem för eder, så skolen I göra dem efter all de bud, som jag eder budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Varer tröste, och vid godt mod; frukter eder intet, och grufver eder intet för dem; ty Herren din Gud skall sjelfver vandra med dig, och skall icke draga handena ifrå, ej heller förlåta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Och Mose kallade Josua, och sade till honom för hela Israels ögon: Var tröst, och vid godt mod; ty du skall föra detta folket i landet, som Herren deras fäder svorit hafver dem att gifva; och skall utskifta det emellan dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Men Herren, som sjelfver går för eder, han skall vara med dig, och icke draga handena ifrå, icke heller förlåta dig; frukta dig intet, och förskräck dig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Och Mose skref denna lagen, och fick Presterna, Levi söner, som båro Herrans förbunds ark, och allom Israels äldstom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Och böd dem, och sade: Ju efter sju år, då friåret är, på löfhyddohögtiden,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Då hela Israel kommer till att bete sig för Herranom dinom Gud, på det rum, som han utväljandes varder, skall du denna lagen låta utropa för hela Israel, för deras öron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Nämliga för folkens församling, både för män och qvinnor, barn, och dinom främling som i dina portar är; på det att de skola höra och lära, huru de skola frukta Herran sin Gud, och akta uppå, att de göra all denna lagsens ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Och att deras barn, som icke vetat, måga ock höra och lära, huru de skola frukta Herran edar Gud i alla edra lifsdagar, som I på landena lefven, dit I öfver Jordan ingån, till att intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Och Herren sade till Mose: Si, din dödstid är kommen; kalla Josua, och går in i vittnesbördsens tabernakel, att jag må gifva honom befallning. Mose gick åstad med Josua, och trädde in i vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Och Herren syntes i tabernaklet uti en molnstod, och samma molnstod stod i dörrene på tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Och Herren sade till Mose: Si, du skall afsomna med dina fäder, och detta folket skall uppkomma, och skall löpa i horeri efter landsens främmande gudar, der de inkomma, och skola öfvergifva mig, och omintetgöra det förbund, som jag med dem gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Så skall min vrede förgrymma sig öfver dem på samma tiden, och jag skall öfvergifva dem, och fördölja mitt ansigte för dem, att de skola upptärde varda. Och när dem då mycken olycka och ångest öfverkommer, skola de säga: Hafver icke allt detta onda råkat på mig, efter Gud icke är med mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Men jag skall på den tiden förskyla mitt ansigte, för allt det ondas skull, som de gjort hafva, att de hafva vändt sig till andra gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Så skrifver eder nu denna visona, och lärer henne Israels barn; och sätter henne i deras mun, att den visan blifver mig ett vittne ibland Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Ty jag vill föra dem i landet, som jag deras fäder svorit hafver, der mjölk och hannog uti flyter; och när de äta och varda mätte och fete, så varda de sig vändande till andra gudar, och tjena dem och förhäda mig, och låta mitt förbund fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Och när dem då mycken olycka och ångest påkommer, så skall denna visan vara dem för ett vittnesbörd, den de icke skola förgäta utu deras säds mun; ty jag vet deras tankar, som de nu allaredo med omgå, förra än jag förer dem i landet, som jag svorit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Så skref Mose denna visona på samma tiden, och lärde henne Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Och befallde Josua, Nuns sone, och sade: Var tröst och frimodig; förty du skall föra Israels barn i landet, som jag dem svorit hafver, och jag skall vara med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Då Mose hade all denna lagsens ord utskrifvit i en bok,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Böd han Leviterna, som Herrans vittnesbörds ark båro, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Tager denna lagsens bok, och lägger henne vid sidon på förbundsens ark, Herrans edars Guds; på det att han skall vara der till ett vittne emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Förty jag känner dina olydighet och halsstyfhet; si, medan jag ännu i dag lefver med eder, hafven I olydige varit emot Herranom; huru mycket mer efter min död?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Så låter nu tillhopakomma för mig alla de äldsta i edra slägter, och edra ämbetsmän, att jag må tala dessa orden för deras öron, och taga himmel och jord till vittne öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Ty jag vet, att I efter min död skolen förderfvat, och gå utaf vägenom, den jag eder budit hafver; så skall eder vederfaras olycka derefter, derföre, att I hafven illa gjort för Herrans ögon, och förtörnat honom genom edra händers gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Alltså talade Mose denna visones ord all ut, för hela Israels församlings öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Akter uppå, I himlar, jag vill tala; och jorden höre mins muns ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Min lära drype såsom regn, och mitt tal flyte såsom dagg; såsom regn uppå gräs, och såsom droppar uppå örter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Ty jag vill prisa Herrans Namn; gifvom vårom Gudi allena ärona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Han är en klippa; hans verk äro ostraffelig; ty allt det han gör, det är rätt. Trofast är Gud, och utan allt argt; rättvis och from är han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Den afvoga och onda slägten är honom ifråfallen; skamfläcker äro de, och icke hans barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Tackar du så Herranom dinom Gud, du galna och ovisa folk? Är han icke din Fader, och din Herre? Hafver han icke allena gjort och beredt dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Tänk uppå den förra tiden allt härtill, och betrakta hvad han gjort hafver med de gamla fäder; fråga din fader, han skall förkunnat dig; dina äldsta, och de skola sägat dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'När den Högste utskifte folken, och utströdde menniskors barn, då satte han landamäre till folken, efter Israels barnas tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Ty Herrans lott är hans folk; Jacob är snöret till hans arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Han fann honom i vildmarkene; uti torro öknene, der styggeligit är; han förde honom omkring, och gaf honom lag, och bevarade honom såsom sin ögnasten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Såsom en örn utförer sina ungar, och flyger öfver dem; så räckte han sina vingar ut, tog dem, och bar dem uppå sina vingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Herren allena ledde honom, och ingen främmande gud var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Han lät honom fara högt uppe på jordene, och födde honom med åkrens frukt; och lät honom suga hannog utu hälleberget, och oljo utu hårda stenen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Smör af korna, och mjölk af fåren, samt med det feta af lamben, och fetesta vädrar, och bockar med feta njurar, och hvete; och lät honom dricka goda vindrufvos blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Och då han vardt fet och mätt, vardt han kåter; han är fet, tjock och stark vorden; och hafver öfvergifvit Gud, den honom gjort hade; sine helsos klippo aktade han ringa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Och rette honom genom främmande gudar till nit; genom styggelse förtörnade han honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'De offrade djeflom, och icke sinom Gud; dem gudom, som de intet kände; dem nyom, som icke tillförene varit hade, hvilka deras fäder intet dyrkat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Dina klippo, den dig födt hafver, den öfvergaf du, och förgat den Gud, som dig skapat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Och då Herren det såg, vardt han vreder öfver sina söner och döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Och han sade: Jag skall förskyla mitt ansigte för dem, och vill se hvad dem på sistone vederfaras kan; ty det är ett afvogt slägte, och sådana barn, der ingen tro uti är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'De hafva rett mig på det som icke är Gud; med deras afguderi hafva de förtörnat mig; och jag skall reta dem igen, på det som icke är folk; med ett galet folk skall jag förtörna dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Elden är upptänd i mine vrede, och skall brinna intill det nedersta helvetet; och skall förtära landet med sin växt, och skall uppbränna bergsgrunden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Jag skall samka olycko öfver dem; jag skall förskjuta alla mina pilar på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'För hunger skola de försmäkta, och förtärde varda af skälfvo och ond sår; jag skall låta komma till dem vilddjurs tänder och grymma ormar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Utvärtes skall svärdet föröda dem, och invärtes förskräckelse; både dränger och pigor, den som dir med dem gråhårota.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Jag skall säga: Hvar äro de? Jag skall borttaga deras åminnelse ifrå menniskomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Om jag icke skydde för fiendernas vrede, att deras fiender icke skola varda stolte, och måtte säga: Vår höga hand hafver allt detta gjort, och icke Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Ty det är ett folk, der intet råd uti är, och intet förstånd är i dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'O! att de vise vore, och de måtte besinna, hvad dem framdeles öfvergå skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Huru kommer det till, att en skall jaga tusende af dem, och två skola komma tiotusend på flyktena? Månn icke deras klippa hafva sålt dem, och Herren hafver öfvergifvit dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Förty vår klippa är icke såsom deras klippa; våre fiender äro der sjelfve domare om.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Deras vinträ är Sodoms vinträ, och af Gomorres åker; deras drufvor äro galle, de hafva bitter bär;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Deras vin är drakaetter, och grymma huggormars galle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Är icke sådant fördoldt när mig, och försegladt i minom håfvom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Hämnden är min; jag skall vedergällat. På sin tid skall deras fot slinta; deras ofärds tid är när, och det dem tillstundar skyndar sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Ty Herren varder dömandes sitt folk, och öfver sina tjenare skall han förbarma sig; ty han varder anseendes, att de äro slätt förgångne, och hvarken de beslutne, eller någon man är öfverblifven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Och man varder sägandes: Hvar äro deras gudar; deras klippa, der de förtröste sig uppå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Af hvilkas offer de åto det feta, och drucko vin af deras drickoffer; lät dem uppstå och hjelpa eder, och beskärma eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Sen I nu, att jag allena äret, och ingen Gud är förutan mig; jag kan döda, och lefvande göra; jag kan slå, och kan hela, och ingen är, som utu mine hand kan fria.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Ty jag vill lyfta mina hand upp i himmelen, och vill säga: Jag lefver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'När jag mins svärds ljungande hvetter, och min hand tager till straffa; så skall jag hämnas igen på mina fiendar, och vedergälla dem som mig hata.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Jag skall göra mina pilar druckna af blod, och mitt svärd skall äta kött, öfver de slagnas blod, och öfver fängelset, och öfver fiendens blottade hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Fröjdens alle I som ären hans folk; ty han varder hämnandes sina tjenares blod; och varder hämnandes öfver sina fiendar; och skall nådelig vara sins folks lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Och Mose kom, och talade all denna visones ord för folkens öron, han och Josua, Nuns son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Då nu Mose allt detta uttalat hade till hela Israel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Sade han till dem: Lägger på hjertat all de ord, som jag betygar eder i dag, att I befallen edor barn, att de hålla och göra all dessa lagsens ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Förty det är intet fåfängt ord till eder, utan det är edart lif; och det ord skall förlänga edart lif på landena, dit I gån öfver Jordan till att intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Och Herren talade till Mose på samma dagen, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Gack upp på berget Abarim, uppå Nebo berg som ligger i de Moabiters land, tvärtöfver Jericho, och bese landet Canaan, som jag Israels barnom till eget gifva skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Och blif död på bergena, då du dit uppkommen äst, och församla dig till ditt folk; lika som din broder Aaron blef död på de bergena Hor, och församlade sig till sitt folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Derföre, att I hafven brutit emot mig ibland Israels barn, vid trätovattnet i Kades, i den öknene Zin, att I icke helgaden mig ibland Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Ty du skall få se landet tvärtifrå dig, det jag Israels barn gifver; men du skall icke komma derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Detta är välsignelsen, der Mose, Guds man, med välsignade Israels barn för hans död,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Och sade: Herren är kommen af Sinai, och är dem uppgången af Seir; han är framkommen ifrå det berget Paran, och är kommen med mång tusend heliga; på hans högra hand är en brinnande lag för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'O! huru kär hafver han folken; alle hans helige äro i dine hand, de skola sätta sig till dina fötter, och skola lära af dinom ordom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mose hafver budit oss lagen, Jacobs menighets arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Och han var i Konungavälde, och Förstarna för folket höll han tillhopa, samt med Israels slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ruben lefve, och dö icke, och hans folk vare fögo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Detta är Juda välsignelse; och han sade: Herre, hör Juda röst, och gör honom till en regent i sitt folk, och låt hans magt varda stora, och honom varde hulpet ifrå hans fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Och till Levi sade han: Din rätt och ditt ljus vare när dinom helga Man, den du försökte i Massa, der I trätten vid trätovattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Den som till sin fader, och till sina moder säger: Jag ser dem intet; och till sina bröder: Jag känner dem intet; och till sin son: Jag vet intet af honom; de samma hålla din ord, och bevara ditt förbund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'De skola lära Jacob dina rätter, och Israel din lag; de skola bära rökverk fram för dina näso, och heloffer på ditt altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Herre, välsigna hans förmågo, och låt hans händers gerningar behaga dig; slå deras rygg sönder, som sätta sig upp emot honom, och deras som hata honom, att de icke skola kunna rätta sig upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Och till BenJamin sade han: Herrans kärkomne skola bo säkert: alltid skall han akta uppå honom, och skall bo emellan hans axlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Och till Joseph sade han: Hans land ligger i Herrans välsignelse; der äro ädla frukter af himmelen, af daggene, och af djupet, som under ligger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Der äro ädla frukter af solene, och ädla mogna frukter af månanom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Och af de höga bergen af begynnelsen, och af högomen i evig tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Och ädla frukter af jordene, och hvad derpå är; hans nåd, som bodde i buskanom, komme öfver Josephs hufvud, och uppå Nazirs hjessa ibland hans bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Hans härlighet är såsom en förstfödd oxe, och hans horn äro såsom enhörningshorn; med dem skall han stånga folken ihop intill landsens ända. Detta är Ephraims tiotusende, och Manasses tusende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Och till Sebulon sade han: Sebulon, fröjda dig af din utgång. Men Isaschar, fröjda dig af dina hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'De skola kalla folk uppå berget, och offra der rättfärdighetenes offer; ty de skola suga hafsens ymnighet, och de fördolda håfvor i sandenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Och till Gad sade han: Välsignad vare den utrymmaren Gad; han bor som ett lejon, och röfvar arm och hjessa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Och han såg, att honom ett hufvud gifvet var; en lärare, som är fördold, och kom med folkens öfverstar, och skaffade Herrans rättviso, och hans rätter med Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Och till Dan sade han: Dan, ett ungt lejon; han skall flyta af Basan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Och till Naphthali sade han: Naphthali skall hafva nog, ehvad honom lyster, och skall vara full med Herrans välsignelse; vesterut, och söderut skall hans besittning vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Och till Asser sade han: Asser vare välsignad med söner; han vare sina bröder täck, och doppe sin fot i oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Jern och koppar vare på hans skor; din ålder vare såsom din ungdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Ingen Gud är såsom dens starkas Gud; den som sitter i himmelen, han vare din hjelp; hans härlighet är i skyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Det är Guds boning af begynnelsen, och hans armar äro härnedre evinnerlig; och han skall utdrifva din fienda för dig, och säga: Var förderfvad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Israel skall allena trygger bo; Jacobs brunn skall vara uppå det land, som korn och vin uti är, och dess himmel skall drypa dagg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Väl är dig, Israel; ho är din like? O du folk, som igenom Herran salig varder, hvilken dins hjelps sköld är, och dins segers svärd! Dine fiender skola fela, och du skall träda in på deras höjder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Och Mose gick utaf de Moabiters mark, upp på berget Nebo, uppå klinten af berget Pisga, tvärtemot Jericho; och Herren viste honom det hela landet Gilead, allt intill Dan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'Och hela Naphthali, och Ephraims land, och Manasse, och hela Juda land, allt intill det yttersta hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Och söderut, och den breda ängden vid Jericho Palma stadsens, allt intill Zoar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Och Herren sade till honom: Detta är det landet, som jag Abraham, Isaac och Jacob, svorit hafver, och sagt: Jag skall gifva det dine säd. Du hafver nu sett det med din ögon; men du skall icke komma ditöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Och så blef Mose Herrans tjenare der död i de Moabiters lande, efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Och han begrof honom uti dalenom uti de Moabiters lande, emot Peors hus; och ingen hafver fått veta hans graf allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Och Mose var hundrade och tjugu år gammal, då han blef död; hans ögon voro intet mörk vorden, och hans kinder voro intet förfallna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Och Israels barn begreto Mose på de Moabiters mark i tretio dagar; och de gråto- och klagodagar öfver Mose vordo fullkomnade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Men Josua, Nuns son, vardt uppfylld med vishetsanda; ty Mose hade lagt sina händer på honom; och Israels barn lydde honom, och gjorde såsom Herren budit hade Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Och sedan stod ingen Prophete upp i Israel, såsom Mose, den Herren kände ansigte mot ansigte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Till allahanda tecken och under, till hvilken Herren honom sände, att han dem göra skulle i Egypti land, på Pharao och alla hans tjenare, och på allt hans land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Och till all den mägtiga hand, och stora syner, som Mose gjorde för hela Israels ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Efter Mose, Herrans tjenares död, sade Herren till Josua, Nuns son, Mose tjenare:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Min tjenare Mose är död; så gör dig nu redo och drag öfver denna Jordan, du och allt detta folket, in uti det land, som jag dem, nämliga Israels barnom, gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Allt rum, der edart fotbjelle på trädandes varder, hafver jag gifvit eder, såsom jag Mose sagt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Ifrån öknene och denna Libanon, intill den stora älfvena Phrath, hela Hetheers land, intill det stora hafvet vesterut, skola edor landamäre vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Ingen skall stå emot dig i dina lifsdagar; såsom jag hafver varit med Mose, så skall jag ock vara med dig; jag skall icke öfvergifva eller förgäta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Var tröst och frimodig; ty du skall utskifta desso folkena landet, som jag deras fäder svorit hafver, att jag dem det gifva skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Var nu tröst och ganska frimodig, att du håller och gör all ting efter lagen, som Mose min tjenare dig budit hafver; vik icke derifrån, antingen på högra sidon eller den venstra, på det att du må handla visliga i allt det du göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Och låt denna lagbokena icke komma utu dinom mun; utan haf dina tankar deruti dag och natt, på det att du skall hålla och göra all ting derefter, som deruti skrifvet står; så skall dig lyckas i allt det du gör, och du skall kunna handla visliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Si, jag hafver budit dig, att du skall vara tröst, och vid godt mod; grufva dig för ingen ting, och frukta intet; ty Herren din Gud är med dig i allt det du företager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Då böd Josua höfvitsmännerna öfver folket, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Går igenom lägret, och bjuder folkena, och säger: Bereder eder spisning; ty efter tre dagar skolen I gå öfver denna Jordanen, att I mågen inkomma till att intaga landet, som Herren edar Gud eder gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Och sade Josua till de Rubeniter, Gaditer, och till de halfva slägtena Manasse:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Tänker uppå det ord, som Mose Herrans tjenare eder böd, och sade: Herren edar Gud hafver låtit eder komma till ro, och gifvit eder detta landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Edra hustrur, barn och boskap låter blifva i landena, som Mose eder gifvit hafver, på denna sidone Jordan; men I skolen gå för edra bröder väpnade, alle de som väraktige män äro, och hjelpa dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Intilldess Herren låter ock edra bröder komma till ro, så väl som eder, att de ock måga intaga det land, som Herren edar Gud dem gifva skall. Sedan skolen I vända om igen till edart land, att I det besitten, som Mose Herrans tjenare eder gifvit hafver, på denna sidone Jordan österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Och de svarade Josua, och sade: Allt det du oss budit hafver, det vilje vi göra, och hvart du sänder oss, dit vilje vi gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Såsom vi hafve varit Mose lydige, så vilje vi ock vara dig lydige; allenast vare Herren din Gud med dig, såsom han var med Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Hvilken som din mun emotstår, och icke lyder din ord i allt det du bjuder oss, han skall dö; allenast var du tröst, och vid godt mod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Josua, Nuns son, sände hemliga ut två spejare ifrå Sittim, och sade dem: Går och beser landet, och Jericho. De gingo åstad, och kommo in uti ene skökos hus, som het Rahab, och der lågo de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Då vardt Konungenom i Jericho sagdt: Si, i denna nattene äro någre män inkomne ifrån Israels barn, till att bespeja landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Då sände Konungen i Jericho till Rahab, och lät säga henne: Få oss ut de män, som till dig i ditt hus komne äro; ty de äro komne till att bespeja allt landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Men qvinnan fördolde de två männerna, och sade: Här äro väl två män inkomne till mig; men jag visste icke hvadan de voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Och då jag ville låta dörrena igen, då mörkt vardt, gingo de ut, så att jag icke vet hvart de gingo; söker med hast efter dem, I fån dem väl fatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Men hon lät dem stiga upp på taket, och öfvertäckte dem med linstjelkar, som hon der på taket utbredt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Men männerna sökte efter dem på den vägen till Jordan, allt intill färjostaden; och porten vardt tilläster straxt de utkomne voro, som efter dem jagade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Och förra än männerna lade sig till sofva, steg hon upp på taket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Och sade till dem: Jag vet, att Herren hafver gifvit eder detta landet; ty en förskräckelse för eder är fallen öfver oss, och alle landsens inbyggare äro bäfvande vordne för edor tillkommelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Ty vi hafve hört, huru Herren uttorkade vattnet i röda hafvet för eder, då I drogen utur Egypten; och hvad I gjort hafven de två Amoreers Konungar, Sihon och Og, på hinsidon Jordan, huru I gåfven dem tillspillo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Och sedan vi det hörde, vardt vårt hjerta förtvifladt, och intet mod är mer i någon man för edor tillkommelse; ty Herren edar Gud han är Gud, både uppe i himmelen, och nedre på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Så svärjer mig nu vid Herran, efter jag hafver gjort barmhertighet med eder, att I ock gören barmhertighet med mins faders hus, och gifver mig ett vårdtecken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Att I låten lefva min fader, mina moder, mina bröder, och mina systrar, och allt det de hafva; och frälser våra själar ifrå döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Männerna sade till henne: Om vi icke göre barmhertighet och trohet med dig, då Herren gifver oss landet, så skall vår själ vara döden skyldig för eder, såframt du icke förråder vårt ärende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Så släppte hon dem neder med ett tåg genom ett fenster; ty hennes hus var i stadsmurenom; och hon bodde desslikes på murenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Och hon sade till dem: Går uppåt berget, att de, som söka efter eder, icke möta eder, och gömmer eder der i tre dagar, så länge de komma igen, som efter eder fara; sedan går edar väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Männerna sade till henne: Vi vilje vara denna eden qvitte, som du af oss tagit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'När vi komme i landet, och du icke binder detta rosenröda tåget i fenstret, med hvilko du oss nedersläppt hafver: och hafver församlat till dig i huset din fader, dina moder, dina bröder, och hela dins faders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Och hvilken som går utom dörrena af ditt hus, hans blod vare öfver hans hufvud, och vi oskyldige; men alle de som i dino huse äro, om en hand kommer vid dem, så skall deras blod vara öfver vårt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Och om du något af denna vår ärende utröjer, så vilje vi vara den eden qvitte, som du af oss tagit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Hon sade: Vare som I sägen: och lät gå dem; och de gingo sin väg, och hon band det rosenröda tåget i fenstret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Och de gingo sin väg, och kommo upp på berget, och blefvo der i tre dagar, tilldess de kommo igen, som efter dem foro: ty de hade sökt dem på alla vägar, och dock intet funnit dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Så vände de två männerna tillbaka, gingo ned af berget, och foro utöfver, och kommo till Josua, Nuns son, och förtäljde honom allt, såsom de det funnit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Och sade till Josua: Herren hafver gifvit oss allt landet i våra händer, alle landsens inbyggare äro förskräckte för oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Och Josua stod bittida upp, och de drogo ut ifrå Sittim, och kommo till Jordan, han och all Israels barn, och blefvo der öfver nattena, förra än de drogo utöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Efter tre dagar gingo befallningsmännerna genom lägret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'Och bödo folkena, och sade: När I sen Herrans edars Guds förbunds ark, och Presterna Leviterna bära honom, så drager ut ifrån edor rum, och följer honom efter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Dock så, att emellan eder och honom är rum vid tutusende alnar långt. I skolen ock icke komma hardt intill honom, på det I mågen veta, på hvilken vägen I gå skolen; förty I hafven den vägen tillförene icke gångit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Och Josua sade till folket: Helger eder; ty i morgon varder Herren görandes ett underligit ting ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Och till Presterna sade han: Tager förbundsens ark, och går framför folket. Och de togo förbundsens ark, och gingo för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Och Herren sade till Josua: I dag skall jag begynna göra dig stor för hela Israel, att de skola veta att, såsom jag hafver varit med Mose, så är jag ock med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Och du bjud Presterna, som förbundsens ark bära, och säg: Som I kommen först i vattnet af Jordan, så står stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Och Josua sade till Israels barn: Går fram, och hörer Herrans edars Guds ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Och sade: Deruppå skolen I märka, att en lefvandes Gud är ibland eder, och han för eder utdrifva skall de Cananeer, Hetheer, Heveer, Phereseer, Girgaseer, Amoreer och Jebuseer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Si, hans förbunds ark, som en Herre är öfver alla verldena, skall gå för eder in uti Jordanen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Så tager nu tolf män utaf Israels slägter, utaf hvart slägte en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'När då Presternas fotbjelle, som bära Herrans ark, den en Herre är öfver alla verldena, komma in uti Jordans vatten, så skall vattnet, som ofvanefter flyter, i Jordan afskilja sig, så att det skall stå i enom hop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Då nu folket drog ut af sin tjäll, att de skulle gå utöfver Jordan, och Presterna båro förbundsens ark fram för folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Och kommo intill Jordanen, och deras fötter först trädde i vattnet, och Jordan var full till alla sina brädder af allahanda andenes vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Då stod det vattnet, som ofvanefter flöt, upprest i en hop, ganska långt ifrå dens stadsens folk, som ligger utmed Zarthan; men det vattnet, som nederlopp åt hafvet, som är salthafvet, det förminskades, och förlopp. Så gick då folket deröfver inåt Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Och Presterna, som båro Herrans förbunds ark, stodo stilla, torre midt i Jordan, och hela Israel gick torr igenom, tilldess allt folket kom öfver Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Och Herren sade till Josua:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Tager eder tolf män, utaf hvart slägtet en;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Och bjuder dem, och säger: Lyfter upp utur Jordan tolf stenar, af det rummet der Presternas fötter stilla stå, och hafver dem öfver med eder, att I lefven dem i lägrena, der I eder i denna nattene lägren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Då kallade Josua tolf män, som tillskickade voro af Israels barn, utaf hvart slägte en;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Och sade till dem: Går fram för Herrans edars Guds ark midt i Jordan, och hvar lyfte en sten på sina axlar, efter talet af Israels barnas slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Att de skola vara ett tecken ibland eder, när edor barn i framtiden fråga sina fäder, och säga: Hvad göra desse stenarna här?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Att I då mågen säga dem, huru Jordans vatten sig åtskiljde för Herrans förbunds ark, då han gick genom Jordan; så att desse stenarna skola vara Israels barnom till en evig åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Då gjorde Israels barn såsom Josua böd dem; och båro tolf stenar midt utur Jordan, såsom Herren hade sagt Josua, efter talet af Israels barnas slägte; och båro dem med sig till det rummet, der de lägrade sig, och der lade de dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Och Josua reste upp tolf stenar midt i Jordan, der Presternas fötter ståndit hade, som förbundsens ark båro, och de äro der ännu intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Ty Presterna, som arken båro, stodo midt i Jordan, tilldess allt bestäldt vardt, som Herren böd Josua säga folkena, och Mose Josua budit hade; och folket skyndade sig, och gick öfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Då nu folket allt öfvergånget var, så gick ock Herrans ark öfver, och Presterna för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Och de Rubeniter, och de Gaditer, och den halfva Manasse slägt, gingo väpnade för Israels barnom, såsom Mose dem sagt hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Vid fyratiotusend väpnade till härs gingo för Herranom till strids på Jericho mark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'På den dagen gjorde Herren Josua stor för hela Israel; och de fruktade honom, såsom de fruktade Mose, medan han lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Och Herren sade till Josua:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Bjud Presterna, som bära vittnesbördsens ark, att de träda upp utur Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Alltså böd Josua Prestomen, och sade: Stiger upp utur Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Och då Presterna, som Herrans förbunds ark båro, stego upp utur Jordan, och trädde med deras fotbjelle på torra landet, kom Jordans vatten återigen i sin stad, och flöt såsom tillförene till alla sina brädder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Och det var den tionde dagen i den första månadenom, då folket uppsteg utur Jordan, och lägrade sig i Gilgal, östan för Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Och de tolf stenar, som de utur Jordan tagit hade, reste Josua upp i Gilgal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Och sade till Israels barn: När nu i framtiden edor barn fråga sina fäder, och säga: Hvad skola desse stenarna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Så skolen I undervisa dem, och säga: Israel gick torr igenom Jordan,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Då Herren edar Gud förtorkade Jordans vatten för eder, så länge I gingen deröfver, lika som Herren edar Gud gjorde i röda hafvet, hvilket han torrt gjorde för oss, så att vi ginge derigenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'På det all folk på jordene skola känna Herrans hand, huru mägtig hon är; och att I skolen frukta Herran edar Gud alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Då nu alla de Amoreers Konungar, som på den sidan Jordan vesterut bodde, och alla de Cananeers Konungar vid hafvet, hörde huru Herren hade förtorkat Jordans vatten för Israels barn, så länge de gingo deröfver, vardt deras hjerta bäfvande, och intet mod var mer i dem, för Israels barns skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'På den tiden sade Herren till Josua: Gör dig stenknifvar, och omskär Israels barn annan gång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Då gjorde Josua sig stenknifvar, och omskar Israels barn på den högen Araloth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Och detta är saken, hvarföre Josua omskar allt folket, som utur Egypten draget var, mankön; ty allt krigsfolket var dödt blifvet i öknene på vägenom, då de drogo utur Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Ty allt det folk, som utdrog, var omskoret; men allt det folk, som i öknene föddes på vägenom, då de drogo utur Egypten, det var icke omskoret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Förty Israels barn vandrade i fyratio år i öknene, tilldess allt folket af krigsmännerna, som utur Egypten dragne voro, förgingos; derföre, att de icke lydde Herrans röst, såsom Herren dem svorit hade, att de icke skulle få se det landet, som Herren deras fäder svorit hade, att gifva oss ett land, der mjölk och hannog uti flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Deras barn, som i deras stad uppkomne voro, dem omskar Josua; förty de hade förhud, och voro intet omskorne på vägenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Och då hela folket omskoret var, blefvo de på sitt rum i lägrena, tilldess de voro läkte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Och Herren sade till Josua: I denna dag hafver jag vändt ifrån eder Egypti skam; och det rummet vardt kalladt Gilgal, intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Och som Israels barn så hade deras lägre i Gilgal, höllo de Passah, på fjortonde dagen i den månadenom, om aftonen, uppå Jericho mark;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Och åto af landsens säd på annan dagen i Passah, nämliga osyradt bröd, och torkad ax, rätt uppå samma dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Och Man vände åter på den andra dagen, sedan de hade ätit af landsens säd, så att Israels barn intet Man mera hade, utan åto af landsens Canaans säd, utaf det samma året.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Och det begaf sig, då Josua var vid Jericho, att han upplyfte sin ögon, och vardt varse att en man stod der för honom, och hade ett draget svärd i sine hand; och Josua gick till honom, och sade till honom: Hörer du oss, eller våra fiendar till?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Han sade: Nej; utan jag är Förste öfver Herrans här, och är rätt nu kommen. Då föll Josua neder på jordena på sitt ansigte, och tillbad, och sade till honom: Hvad säger min Herre till sin tjenare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Och Försten öfver Herrans här sade till Josua: Drag dina skor af dina fötter; ty rummet, som du står uppå, är heligt. Och Josua gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Och Jericho var tillstängdt och förvaradt för Israels barns skull, så att ingen kunde komma ut eller in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Men Herren sade till Josua: Si, jag hafver gifvit Jericho, med dess Konung och krigsfolk, i dina hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Låt alla krigsmännerna gå en gång kringom staden; och gör så i sex dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'På sjunde dagen låt Presterna taga sju klangårens basuner, och gå dermed för arken; och går på den samma sjunde dagenom sju resor kringom staden, och låt Presterna blåsa i basunerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Och då man blås i klangårshornet långsamt, så att I hören basunerna, då skall folket göra ett stort skri, och så skola stadsmurarna falla, och folket skall falla derin, hvar och en rätt framför sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Då kallade Josua, Nuns son, Presterna, och sade till dem: Bärer förbundsens ark, och låter sju Prester bära sju klangårens basuner för Herrans ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Men till folket sade han: Drager åstad, och går omkring staden, och hvilken som väpnader är, han gånge fram för Herrans ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Då Josua detta folkena sagt hade, togo de sju Prester sju klangårens basuner, och gingo för Herrans ark, och blåste i basunerna; och Herrans förbunds ark följde efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Och hvilken som väpnader var, han gick för Presterna, som i basunerna blåste, och hopen följde efter arken, och blåste i basuner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Men Josua böd folkena, och sade: I skolen intet härskri göra, eller låta höra edra röst, eller något ord låta gå utaf edar mun, intill den dagen jag säger till eder: Gifver upp ett härskri; då gifver ett härskri upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Så gick Herrans ark kringom staden en gång; och kommo i lägret, och blefvo der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Förty Josua plägade vara bittida uppe om morgonen; och Presterna båro Herrans ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Så båro de sju Presterna de sju klangårens basuner för Herrans ark, och gingo och blåste i basunerna; och hvilken som väpnad var, han gick för dem, och hopen följde Herrans ark, och blåste i basuner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'På den andra dagen gingo de ock en gång om staden, och kommo i lägret igen; så gjorde de i sex dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Men på sjunde dagen, då morgonrodnen uppgick, voro de bittida uppe, och gingo vid samma sättet sju resor kringom staden; så att de på den samma ena dagen kommo sju resor kringom staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Och på sjunde resone, då Presterna blåste i basunerna, sade Josua till folket: Gifver upp ett härskri; ty Herren hafver gifvit eder staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Men staden, och allt det deruti är, skall tillspillogifvas Herranom; allenast den skökan Rahab skall blifva lefvandes, och alla de som med henne äro i huse; ty hon fördolde de bådskap, som vi utsände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Allenast tager eder vara för det som tillspillogifvet är, att I icke gifven eder sjelf tillspillo, om I något tagen af det som tillspillogifvet är, och gören så Israels lägre tillspillo, och låten det komma i olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Men allt silfver och guld, och koppars och jerns tyg, skall vara helgadt Herranom, och bevaras till Herrans skatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Då gaf folket upp ett härskri, och blåste i basunerna; ty allt folket, som hörde basunernas ljud, gaf upp ett stort härskri, och murarna föllo omkull, och folket besteg staden, hvar och en rätt för sig. Så vunno de staden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Och tillspillogjorde allt det i stadenom var, med svärdsegg, både man och qvinno, ung och gammal, fä, får och åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Och Josua sade till de två män, som hade bespejat landet: Går uti den skökones hus, och hafver qvinnona dädan hitut, med allt det hon hafver, såsom I hafven svorit henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Då gingo de unge män spejarena ditin, och hade Rahab ut med hennes fader och moder, och bröder, och allt det hon hade, och alla hennes slägt, och läto dem blifva utanför Israels lägre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Men staden brände de upp med eld, och allt det deruti var; allenast silfver och guld, och koppars och jerns tyg, lade de för en skatt in uti Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Men den skökan Rahab, med hennes faders hus, och allo thy hon hade, lät Josua lefva; och hon bodde i Israel intill denna dag; derföre att hon hade fördolt de bådskap, som Josua till att bespeja utsändt hade till Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'På den tiden svor Josua, och sade: Förbannad vare den man för Herranom, som upprättar och bygger denna staden Jericho. När han lägger hans grund, det koste honom hans första son; och när han uppsätter hans port, det koste honom hans yngsta son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Och var Herren med Josua, så att han vardt namnkunnig i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Men Israels barn förtogo sig på det som tillspillogifvet var; ty Achan, Charmi son, Sabdi sons, Serahs sons, af Juda slägte, tog något af det som tillspillogifvet var; då förgrymmade sig Herrans vrede öfver Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Och Josua utsände af Jericho några män in mot Aj, som ligger vid BethAven österut ifrå BethEl, och sade till dem: Går upp, och bespejer landet. Och då de hade uppgångit, och bespejat Aj,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Kommo de igen till Josua, och sade till honom: Låt icke allt folket draga ditupp; utan vid tu eller tre tusend män, att de draga ditupp, och slå Aj, att icke allt folket gör sig der mödo om; förty de äro få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Så drogo ditupp af folkena vid tretusend män, och de flydde för de män af Aj.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Och de af Aj slogo af dem vid sex och tretio män, och jagade dem allt ifrå porten intill Sebarim, och slogo dem den vägen nederåt. Då vardt folkens hjerta förtvifladt, och vardt såsom vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Och Josua ref sina kläder sönder, och föll uppå sitt ansigte till jordena för Herrans ark, allt intill aftonen, samt med de äldsta af Israel, och de strödde stoft på sin hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Och Josua sade: Ack! Herre, Herre, hvi hafver du fört detta folket öfver Jordan, att du skulle gifva oss uti de Amoreers händer, till att förgöra oss? Ack! det vi dock hade blifvit på hinsidon Jordan, såsom vi begynt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Ack! min Herre, hvad skall jag säga, medan Israel vänder ryggen till sina fiendar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'När de Cananeer och alle landsens inbyggare det höra, så varda de oss omkringhvärfvande, och utrota vårt namn af jordene; hvad vill du då göra dino stora Namne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Då sade Herren till Josua: Statt upp, hvi ligger du så på ditt ansigte?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel hafver syndat, och de hafva gångit öfver mitt förbund, som jag dem budit hafver; och hafva tagit af det som tillspillogifvet var, och stulit, och ljugit, och lagt ibland sin tyg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Israels barn kunna icke blifva ståndande för sina fiendar; utan måste vända ryggen till sina fiendar; förty de äro tillspillo vordne. Jag skall icke vara mera med eder, om I icke låten komma den spillning ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Statt upp, och helga folket, och säg: Helger eder till morgons; ty så säger Herren Israels Gud: En spillning är ibland dig, Israel; derföre kan du icke blifva ståndandes för dina fiendar, tilldess I låten den spillningen komma ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Och I skolen bittida gå fram, den ena slägten efter den andra; och på hvilken slägten Herren drabbar, der skall gå fram den ena ätten efter den andra; och på hvilken ätten Herren drabbar, der skall gå fram det ena huset efter det andra; och på hvilket hus Herren drabbar, der skall gå fram den ene husbonden efter den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Och hvilken som befunnen varder med någon spillgifven ting, honom skall man uppbränna i eld, med allt det han hafver; derföre, att han hafver gångit emot Herrans förbund, och bedrifvit en galenskap i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Så stod Josua bittida upp om morgonen, och hade fram Israel, den ena slägten efter den andra; och det drabbade inpå Juda slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Och då han hade Juda slägte fram, drabbade det inpå de Serahiters ätt; och då han hade de Serahiters ätt fram, den ena husbonden efter den andra, drabbade det på Sabdi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Och då han hade hans hus fram, den ena husbonden efter den andra, drabbade det på Achan, Charmi son, Sabdi sons, Serahs sons, utaf Juda slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Och Josua sade till Achan: Min son, gif Herranom Israels Gudi ärona, och gif honom prisen; och säg mig hvad du gjort hafver, och ljug intet för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Då svarade Achan Josua, och sade: Sannerliga, jag hafver syndat emot Herran Israels Gud; så och så hafver jag gjort:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Jag såg ibland rofvet en kostelig Babylonisk mantel, och tuhundrade siklar silfver, och en gyldene tungo, femtio siklar värd till vigt; der fick jag lust till, och tog det; och si, det är nedergrafvet i jordene i mitt tjäll, och silfret derunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Då sände Josua dit båd; de lupo till tjället, och si, der var det nedergrafvet i hans tjäll, och silfret derunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Och de togo det utu tjället, och båro till Josua, och till all Israels barn, och kastade det der ned för Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Då tog Josua och hela Israel med honom Achan, Serahs son, med silfret, mantelen och gyldene tungone, hans söner och döttrar, hans oxar och åsnar, och får, hans tjäll, och allt det han hade; och förde ut i Achors dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Och Josua sade: Efter du hafver plågat oss, så plåge dig Herren på denna dag! Och hela Israel stenade dem, och brände dem upp i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Och då de hade stenat dem, gjorde de ena stora stenrösjo öfver dem, hvilken ännu varar allt intill denna dag. Så vände då Herren sig ifrå sine vredes grymhet; deraf heter det rummet Achors dal intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Och Herren sade till Josua: Frukta dig intet, och var intet förfärad. Tag med dig allt krigsfolket, och gör redo, och drag upp till Aj. Si, jag hafver gifvit Konungen i Aj, med hans folk, hans stad och land, i dina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Och du skall göra med Aj och dess Konung, såsom du med Jericho och dess Konung gjort hafver; undantagno, att dess rof och dess boskap skolen I byta eder emellan. Beställ ett bakhåll afsides vid staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Då gjorde Josua redo, och allt krigsfolket, till att draga upp till Aj; och Josua utvalde tretiotusend stridsmän, och sände ut om nattena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Och böd dem, och sade: Ser till, I skolen vara i bakhåll, afsides vid staden; och varer icke för långt ifrå staden, och varer alle redo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Men jag, och allt folket, som med mig är, viljom draga till staden; och när de draga ut emot oss, såsom tillförene, så vilje vi fly för dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Att de draga ut efter oss, så länge vi komme dem ut ifrå staden; ty de skola tänka, att vi fly för dem, såsom tillförene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Och medan vi fly för dem, skolen I redo vara i bakhållena, och taga staden in; förty Herren edar Gud skall gifva eder honom i händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'När I hafven intagit staden, så tänder elden på honom; efter Herrans ord görer: si, jag hafver det budit eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Så sände Josua dem åstad, och de gingo ditupp i bakhåll, och höllo emellan BethEl och Aj, vesterut ifrån Aj; men Josua blef i den nattene när folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Och om morgonen var han bittida uppe, och skickade folket, och drog upp med de äldsta af Israel för folkena till Aj.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Och allt krigsfolket, som när honom var, drogo upp, och trädde fram, och kommo in mot staden, och lägrade sig norrut ifrån Aj; så att en dal var emellan dem och Aj.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Men han hade tagit vid femtusend män, och ställt dem till bakhåll emellan BethEl och Aj, vesterut ifrå staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Och folket af hela lägret, som norrut ifrå stadenom var, ställdes så, att dess yttersta räckte vester om staden; så drog då Josua i den nattene midt in uppå dalen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Som nu Konungen i Aj såg det, skyndade de sig, och gjorde bittida redo; och männerna af stadenom drogo ut, till att möta Israel i strid med allt sitt folk, på ett förelagdt rum emot slättmarkene; ty han visste icke, att ett bakhåll var på honom bakom staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Men Josua och hela Israel ställde sig, såsom de hade varit slagne för dem, och flydde på den vägen åt öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Då skriade allt folket af stadenom, att man skulle förfölja dem; och de jagade desslikes efter Josua, och föllo utu stadenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Så att icke en man blef qvar i Aj och BethEl, den icke utdrog, och förföljde Israel; och läto staden stå öppen, på det de skulle jaga efter Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Då sade Herren till Josua: Räck ut spetsen, som du hafver i dine hand, emot Aj; ty jag vill gifva det i dina hand. Och Josua räckte ut spetsen, som i hans hand var, emot staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Då gaf sig bakhållet upp med hast utaf sitt rum, och lupo, sedan han räckte ut sina hand, och kommo i staden, och vunno honom, och hastade sig, och tände elden på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Och de män af Aj vände sig, och sågo tillbaka, och fingo se röken af staden gå upp i himmelen, och hade intet rum till att fly, hvarken hit eller dit: och det folket, som flydde åt öknena, vände sig om till att jaga efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Då nu Josua och hela Israel sågo, att bakhållet hade vunnit staden, efter röken gick upp af stadenom, vände de om, och slogo de män af Aj.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Och de i staden drogo också ut emot dem, så att de kommo midt ibland Israel på båda sidor; och de slogo dem, tilldess ingen af dem öfverblef lefvandes, eller undslapp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Och grepo Konungen af Aj lefvandes, och förde honom till Josua.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Och då Israel hade ihjälslagit alla Ajs inbyggare på markene, och i öknene, som hade jagat efter dem, och de föllo alle genom svärdsegg, tilldess de voro ändade; då vände sig hela Israel åt Aj, och slogo det med svärdsegg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Och alle de som föllo på den dagen, både män och qvinnor, de voro tolftusend, allt folk i Aj.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Och Josua drog icke handena igen, med hvilko han uträckte spetsen, tilldess han tillspillogjorde alla Ajs inbyggare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Utan boskapen, och rofvet af stadenom, utbytte Israel emellan sig, efter Herrans ord, såsom han Josua budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Och Josua brände upp Aj, och gjorde en hög deraf till evig tid, den ännu der är på denna dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Och lät upphänga Konungen af Aj i ett trä intill aftonen. Då solen var nedergången, befallde han, att man skulle taga hans kropp utu trät; och de kastaden i stadsporten, och hofvo en stor stenhop deruppå, hvilken ännu der är intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Då byggde Josua Herranom Israels Gud ett altare, på det berget Ebal,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Såsom Mose Herrans tjenare Israels barnom budit hade, såsom skrifvet står i Mose lagbok, ett altare af hela stenar, der intet jern på kommet var; och offrade deruppå Herranom bränneoffer och tackoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Och skref der på stenarna den andra lagen, som Mose Israels barnom föreskrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Och hela Israel med deras äldsta, och ämbetsmän och domare, stodo på båda sidor vid arken inför Presterna af Levi, som båro Herrans förbunds ark; de främlingar, så väl som de infödde; hälften af dem invid det berget Grisim, och den andra hälften invid det berget Ebal; såsom Mose Herrans tjenare tillförene budit hade till att välsigna Israels folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Sedan lät han utropa all lagsens ord, om välsignelsen och förbannelsen, som skrifne stå i lagbokene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Det var icke ett ord, som Mose budit hade, det Josua icke lät utropa för hela Israels menighet; för qvinnor och barn, och främlingom, som ibland dem voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Då nu detta hördes intill alla de Konungar, som voro på den sidon Jordan, på bergom och i dalom, och i alla stora hafsens hamner, och när dem som voro invid Libanons berg, nämliga de Hetheer, Amoreer, Cananeer, Phereseer, Heveer och Jebuseer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Samkade de sig tillhopa endrägteliga, att de skulle strida emot Josua, och emot Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Men Gibeons inbyggare, då de hörde hvad Josua gjort hade med Jericho och Aj,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Upptänkte de en list, gingo till och sände bådskap åstad, och togo gamla säcker på sina åsnar, och gamla slitna vinläglar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Och gamla lappade skor på sina fötter, och drogo gamla och rifna kläder uppå; och allt det bröd, som de togo med sig, var hårdt och mögladt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Och gingo till Josua i lägret vid Gilgal, och sade till honom, och till hela Israel: Vi äre komne fjerran af annor land; så görer nu ett förbund med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Då sade hela Israel till de Heveer: Kan hända, att du bor här ibland oss, huru kunne vi då göra förbund med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'De sade till Josua: Vi äre dine tjenare. Josua sade till dem: Ho ären I; eller hvadan kommen I?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'De sade: Dine tjenare äro ganska fjerran komne af annor land, för Herrans dins Guds Namns skull; ty vi hafve hört hans rykte, och allt det han i Egypten gjort hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'Och allt det han de två Amoreers Konungar på hinsidon Jordan gjort hafver, Sihon, Konungenom i Hesbon, och Og, Konungenom i Basan, som bodde i Astaroth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Derföre sade våre äldste; och alle vårt lands inbyggare: Tager spisning med eder på resona, och går åstad emot dem, och säger till dem: Vi äre edre tjenare; så görer nu ett förbund med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Detta vårt bröd, som vi togo med oss till spisning utu vår hus, var ännu färskt, då vi åstad forom till eder; men nu, si, det är hårdt och mögladt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Och dessa vinläglarna fyllde vi nya; och si, de äro slitne; och denna vår kläder och skor äro gamla vordna för denna ganska långa resonas skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Då togo höfvitsmännerna af deras spisning, och frågade intet Herrans mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Och Josua gjorde frid med dem, och ingick ett förbund med dem, att de skulle blifva lefvande; och de öfverste för menighetene svoro dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Men efter tre dagar, sedan de hade gjort förbundet med dem, kom för dem, att de voro hardt när dem, och skulle bo ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Ty då Israels barn drogo framåt, kommo de tredje dagen till deras städer, hvilke så voro nämnde: Gibeon, Cephira, Beeroth och KiriathJearim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Och de slogo dem intet, ty de öfverste för menighetene hade svorit vid Herran Israels Gud; och hela menigheten knorrade emot de öfversta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Då sade alle de öfverste för hela menighetene: Vi hafve svorit dem vid Herran Israels Gud; derföre kunne vi intet komma vid dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Men det vilje vi göra dem; låtom dem lefva, att en vrede icke kommer öfver oss för edens skull, den vi dem gjort hafvom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Och de öfverste sade till dem: Låtom dem lefva, att de måga vara vedahuggare och vattudragare för hela menighetene, såsom öfverstarna dem sagt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Då kallade dem Josua, och talade med dem, och sade: Hvi hafven I bedragit oss, och sagt: I ären ganska långt ifrån oss; ändock I bon ibland oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Derföre skolen I vara förbannade, så att af eder icke skall återvända trälar, som ved hugga, och vatten draga, till mins Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'De svarade Josua, och sade: Det hafver varit sagdt dina tjenare, att Herren din Gud hafver budit sinom tjenare Mose, att han skall gifva eder detta hela landet, och förgöra för eder alla landsens inbyggare; då fruktade vi om våra själar för eder storliga, och gjorde detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Men nu, si, vi äre i dina händer; hvad dig tycker godt och rätt vara att göra med oss, det gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Och han gjorde dem så, och friade dem ifrån Israels barnas hand, att de icke slogo dem ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Så gjorde Josua dem på samma dagen till vedahuggare och vattudragare för menighetene, och till Herrans altare, allt intill denna dag, på det rum som han utväljandes vorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Då nu AdoniZedech, Konungen i Jerusalem, hörde att Josua hade vunnit Aj, och gifvit det tillspillo, och hade gjort Aj och dess Konung lika såsom han hade gjort Jericho och dess Konung, och att de Gibeoniter hade gjort frid med Israel, och voro komne ibland dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Fruktade de svårliga; förty Gibeon var en stor stad, såsom en af Konungastäderna, och större än Aj, och alle hans borgare gode stridsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Och han sände till Hoham, Konungen i Hebron, och till Piram, Konungen i Jarmuth, och till Japhia, Konungen i Lachis, och till Debir, Konungen i Eglon, och lät säga dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Kommer hitupp till mig, och hjelper mig, att vi må slå Gibeon; förty de hafva gjort frid med Josua och Israels barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Då kommo tillhopa, och drogo uppåt, de fem Amoreers Konungar: Konungen i Jerusalem, Konungen i Hebron, Konungen i Jarmuth, Konungen i Lachis, Konungen i Eglon, med all deras härlägre, och belade Gibeon, och stridde deremot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Men de af Gibeon sände till Josua i lägret i Gilgal, och läto säga honom: Drag icke dina hand ifrå dina tjenare; kom hitupp till oss snarliga, undsätt och hjelp oss; ty alla de Amoreers Konungar, som bo uppå bergen, hafva samkat sig tillhopa emot oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Josua drog ditupp ifrå Gilgal, och allt krigsfolket med honom, och alle gode stridsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Och Herren sade till Josua: Frukta dig intet för dem; ty jag hafver gifvit dem i dina händer; ingen af dem skall kunna blifva ståndandes för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Alltså kom Josua hasteliga på dem; ty han drog i hela nattene upp ifrå Gilgal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Men Herren förskräckte dem för Israel, så att de slogo dem en stor slagtning af i Gibeon; och jagade efter dem på den vägen till BethHoron, och slogo dem intill Aseka och Makkeda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Och då de flydde för Israel den vägen nederåt till BethHoron, lät Herren falla af himmelen stora hagelstenar på dem intill Aseka, så att de blefvo döde; och mycket flere af dem blefvo döde af hagelstenarna, än Israels barn slogo med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Då talade Josua med Herranom, på den dagen, när Herren gaf de Amoreer för Israels barn, och sade i Israels närvaro: Sol, statt stilla i Gibeon, och måne, i Ajalons dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Då stod solen stilla, och månen desslikes, tilldess att folket hämnade sig på sina fiendar. Är icke detta skrifvet i dens frommas bok? Så stod solen midt på himmelen, och fördröjde gå neder, sånär en helan dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Och hafver ingen dag varit lik vid denna, hvarken förr eller sedan, då Herren lydde ens mans röst; ty Herren stridde för Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Och Josua drog åter i lägret igen till Gilgal; och hela Israel med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Men de fem Konungar voro flydde, och undstungo sig uti en kulo i Makkeda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Då vardt Josua sagdt: Vi hafve funnit de fem Konungar fördolda i ene kulo i Makkeda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Josua sade: Så välter stora stenar för gapet af kulone; och befaller några män, som taga der vara på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Men I står icke stilla, utan jager efter edra fiendar, och slår deras eftersta, och låter icke komma dem i deras städer; ty Herren edar Gud hafver gifvit dem i edra händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Och då Josua och Israels barn hade lyktat den mägtiga stora slagtningen på dem, och platt slagit dem, hvad sedan qvart blef af dem, det kom in i de fasta städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Så kom allt folket åter i lägret igen till Josua i Makkeda med frid; och ingen torde röra sina tungo för Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Men Josua sade: Låter upp gapet för kulone, och drager fram de fem Konungar till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'De gjorde ock så, och hade de fem Konungar till honom utu kulone: Konungen i Jerusalem, Konungen i Hebron, Konungen i Jarmuth, Konungen i Lachis, Konungen i Eglon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Då nu desse Konungar voro framledde till honom, kallade Josua hela Israel, och sade till de öfversta af krigsfolket, som med honom drogo: Kommer hit, och träder dessa Konungarna på halsen med fötterna; och de kommo fram, och trädde på deras halsar med fötterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Och Josua sade till dem: Frukter eder intet, och grufver eder intet; varer tröste och vid ett fritt mod; ty alltså skall Herren göra alla edra fiendar, som I emot striden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Och Josua slog dem sedan, och drap dem, och hängde dem i fem trä; och de hängde i trän allt intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Då solen var nedergången, böd han, att man skulle taga dem ned af trän, och kasta dem in i kulona, der de sig uti fördolt hade; och lade stora stenar för gapet af kulone, hvilke der ännu äro på denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'På den samma dagen vann ock Josua Makkeda, och slog det med svärdsegg, med dess Konung, och gaf det tillspillo, och alla de själar, som derinne voro, och lät ingen blifva igen; och gjorde dem Konungenom i Makkeda, såsom han hade gjort Konungenom i Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Så drog Josua, och hela Israel med honom, ifrå Makkeda till Libna, och stridde deremot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Och Herren gaf det också i Israels hand, med dess Konung; och han slog det med svärdsegg, och alla de själar, som derinne voro, och lät ingen blifva igen derinne; och gjorde dess Konung, såsom han hade gjort Konungenom i Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Sedan drog Josua, och hela Israel med honom, ifrå Libna till Lachis; belade och bestridde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Och Herren gaf desslikes Lachis i Israels händer, så att de vunno det på annan dagen, och slogo det med svärdsegg, och alla de själar som derinne voro, alldeles som han hade gjort i Libna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'På samma tiden drog Horam, Konungen i Geser, upp till att hjelpa Lachis; men Josua slog honom med allt hans folk, tilldess ingen igenblef.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Och Josua drog ifrå Lachis med hela Israel, intill Eglon, och belade och bestridde det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Och vann det på samma dag, och slog det med svärdsegg, och gaf tillspillo alla de själar, som derinne voro på samma dagen, alldeles såsom han hade gjort Lachis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Sedan drog Josua med hela Israel ifrån Eglon upp till Hebron, och bestridde det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Och vann det, och slog det med svärdsegg, och dess Konung med alla dess städer, och alla de själar, som derinne voro; och lät icke en igenblifva, alldeles såsom han hade gjort Eglon; och gaf det tillspillo, och alla de själar som derinne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Då vände Josua igen med hela Israel inåt Debir, och bestridde det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Och vann det med dess Konung, och alla dess städer, och slogo dem med svärdsegg, och gåfvo tillspillo alla de själar som derinne voro; och lät icke en igenblifva. Såsom han hade gjort Hebron, så gjorde han ock Debir och dess Konung, och såsom han hade gjort Libna och dess Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Alltså slog Josua allt landet på bergen, och söderut, och i dalarna, och vid bäckerna, med alla deras Konungar; och lät icke en igenblifva; och gaf tillspillo allt det som anda hade, såsom Herren Israels Gud budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Och slog dem allt ifrå KadesBarnea intill Gasa; och hela landet Gosen intill Gibeon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Och vann alla dessa Konungarna med deras land, allt med en ryck; ty Herren Israels Gud stridde för Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Och Josua drog åter i lägret till Gilgal med hela Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Då Jabin, Konungen i Hazor, detta hörde, sände han till Jobab, Konungen i Madon, och till Konungen i Achsaph,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'Och till de Konungar, som bodde norrut uppå bergen, och uppå slättmarkene, söderut Cinneroth; och i dalarna, och i NaphotDor, utmed hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Till de Cananeer österut och vesterut, till de Amoreer, Hetheer, Phereseer, och Jebuseer uppå bergen; så ock till de Heveer nedanför Hermons berg i Mizpa land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Desse drogo ut med alla deras härar, dråpeliga mycket folk, såsom sanden i hafsstrandene; och ganska många hästar och vagnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Alle desse Konungar församlade sig, och kommo, och lägrade sig ihop vid det vattnet Merom, till att strida med Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Och Herren sade till Josua: Frukta dig intet för dem; ty i morgon på denna tiden skall jag gifva dem alla slagna för Israels barn; deras hästar skall du hasa, och bränna deras vagnar i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Och Josua kom hasteliga på dem, och allt krigsfolket med honom, vid vattnet Merom, och öfverföll dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Och Herren gaf dem i Israels händer; och de slogo dem, och jagade dem allt intill det stora Zidon, och intill det varma vattnet; och intill slätten i Mizpe österut, och slogo dem tilldess icke en igenblef.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Då gjorde Josua dem såsom Herren honom budit hade, och hasade deras hästar, och brände upp deras vagnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Och vände om på samma tiden, och vann Hazor, och slog dess Konung med svärd; ty Hazor var tillförene hufvudstaden för alla dessa Konungariken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Och slog alla de själar, som derinne voro, med svärdsegg, och gaf dem tillspillo; och lät intet igenblifva, som anda hade; och brände upp Hazor med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Dertill alla dessa Konungarnas städer vann Josua, med deras Konungar; och slog dem med svärdsegg, och gaf dem tillspillo, såsom Mose Herrans tjenare budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Dock uppbrände Israels barn inga städer med eld, som högt uppe lågo, förutan Hazor allena; det uppbrände Josua.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Och allt rofvet af dessa städerna, och boskapen, bytte Israels barn emellan sig; men alla menniskor slogo de med svärdsegg, tilldess de förgjorde dem, och läto intet igenblifva, som anda hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Såsom Herren sinom tjenare Mose, och Mose Josua budit hade, så gjorde Josua, att intet blef tillbaka af allt det Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Alltså intog Josua all denna landen på bergen, och allt det söderut ligger, och allt landet Gosen, och dalarna, och slättmarkena, och Israels berg med dess dalar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Allt ifrå berget, som åtskiljer landet uppåt emot Seir intill BaalGad, på bergsens Libanons slätt nedan vid Hermons berg; alla deras Konungar vann han, och slog dem, och drap dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Men han förde örlig med dessa Konungarna i långan tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Och var ingen stad, som sig gaf med frid under Israels barn, undantagna de Heveer, som bodde i Gibeon; utan de vunno dem alla med strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Och det skedde så af Herranom, att deras hjerta vardt förstockadt, till att möta Israels barn med strid; på det de skulle tillspillo komma, och dem ingen nåd vederfaras, utan förgöras, såsom Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'På den tiden kom Josua, och utrotade de Enakim utaf bergen af Hebron, af Debir, af Anab, af all Juda berg, och af all Israels berg, och gaf dem tillspillo med deras städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Och lät ingen Enakim igenblifva i Israels barnas land, förutan i Gasa, i Gath, och i Asdod; der blefvo de igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Alltså tog Josua allt landet in, alldeles såsom Herren hade sagt till Mose; och gaf det Israels barnom till arfs, hvarjo slägtene sin del. Och landet vände åter att strida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Desse äro de Konungar i landena, som Israels barn slogo, och togo deras land in på hinsidon Jordan, österut: ifrån Arnons bäck intill Hermons berg, och hela marken österut:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, de Amoreers Konung, som bodde i Hesbon, och var rådandes ifrån Aroer, som på strandene ligger vid den bäcken vid Arnon, och midt i bäcken, och öfver halft Gilead, intill den bäcken Jabbok, der Ammons barnas landamäre är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Och öfver den slättmarkena allt intill hafvet Cinneroth österut, och intill hafvet i slättmarkene, som är salthafvet österut, den vägen åt BethJesimoth; och ifrå sunnan neder utmed bäcken vid berget Pisga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Dertill Ogs gränso, Konungens i Basan, den ännu af de Resar qvar blifven var, och bodde i Astaroth och Edrei,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Och var rådandes öfver berget Hermon, öfver Salcha, och öfver hela Basan, allt intill Gessuri och Maachathi gränsor, och i halfva Gilead, hvilket var Sihons gränsa, Konungens i Hesbon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mose Herrans tjenare, och Israels barn slogo dem; och Mose Herrans tjenare gaf dem de Rubeniter, Gaditer, och den halfva slägtene Manasse till att intaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Men desse äro de Konungar i landena, som Josua slog, och Israels barn, på denna sidone Jordan, vesterut, ifrå BaalGad på Libanons bergs slätt, intill det berget som åtskiljer landet uppåt emot Seir, och det Josua Israels slägter gaf till att intaga, hvarjom och enom sin del;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Det som uppå bergen, dalomen, slättmarkene, vid bäcker, i öknene, och söderut var, de Hetheer, Amoreer, Cananeer, Phereseer, Heveer och Jebuseer:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Konungen i Jericho, Konungen i Aj, som vid sidona ligger af BethEl;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Konungen i Jerusalem, Konungen i Hebron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Konungen i Jarmuth, Konungen i Lachis;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Konungen i Eglon, Konungen i Geser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Konungen i Debir, Konungen i Geder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Konungen i Horma, Konungen i Arad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Konungen i Libna, Konungen i Adullam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Konungen i Makkeda, Konungen i BethEl;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Konungen i Tappnah, Konungen i Hepher;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Konungen i Aphek, Konungen i Lasaron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Konungen i Madon, Konungen i Hazor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Konungen i SimronMeron, Konungen i Achsaph;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Konungen i Thaanach, Konungen i Megiddo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Konungen i Kedes, Konungen i Jokneam på Charmel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Konungen i DorNaphotDor, Konungen för de Hedningar i Gilgal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Konungen i Tirza. Det äro en och tretio Konungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Då nu Josua vardt gammal, och väl till ålders, sade Herren till honom: Du äst gammal vorden, och väl till ålders, och landet är ännu mycket qvart, som intagas skall:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Nämliga hela landet de Philisteers och hela Gessuri,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Ifrå Sichor, som löper framom Egypten, allt intill Ekrons landsändar norrut, hvilka de Cananeer tillräknas; fem de Philisteers herrar, nämliga de Gasiter, de Asdoditer, de Askaloniter, de Gittiter, de Ekroniter, och de Aviter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Men ifrå söder är hela de Cananeers land, och Mearah de Zidoniers, allt intill Aphek, och till de Amoreers landsändar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Dertill de Gibliters land, och hela Libanon österut, ifrå BaalGad nedanför berget Hermon, tilldess man kommer till Hamath;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Alle de som på bergen bo, ifrå Libanon intill det varma vattnet, och alle Zidonier; jag skall fördrifva dem för Israels barn; kasta lott derom, till att utskifta dem emellan Israel, såsom jag hafver budit dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Så skift nu denna landen emellan de nio slägter till arfs, och emellan den halfva slägten Manasse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Ty de Rubeniter och Gaditer hafva med den andra halfva Manasse undfått deras arfvedel, som Mose dem gaf på hinsidon Jordan österut, såsom Herrans tjenare Mose dem det gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Ifrån Aroer, som ligger på bäcksens strand vid Arnon, och ifrå den staden midt i bäcken, och all den ängden Medeba allt intill Dibon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'Och alla Sihons, de Amoreers Konungs, städer, som satt i Hesbon, allt intill Ammons barnas landsändar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Dertill Gilead, och de landsändar vid Gessuri och Maachati, och hela berget Hermon, och hela Basan, allt intill Salcha,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Hela Ogs rike i Basan, den i Astaroth och Edrei satt, hvilken ännu igen var af de Resar; men Mose slog dem, och fördref dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Men Israels barn fördrefvo icke dem i Gessur, och i Maachath; utan de bodde, både Gessur och Maachath, ibland Israels barn allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Men de Leviters slägte gaf han ingen arfvedel; ty Herrans Israels Guds offer är deras arfvedel, såsom han dem sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Så gaf Mose Rubens barnas slägte, efter deras ätter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Så att deras landsändar voro ifrån Aroer, som ligger på bäcksens strand vid Arnon, och den staden midt i bäcken, med alla slättmarkene intill Medeba;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon och alla dess städer, som ligga på slättmarkene, Dibon, BamothBaal, och BethBaalMeon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahza, Kedemoth, Mephaath,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kiriathaim, Sibma, SerethSahar uppå berget Emek,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'BethPeor, de bäcker vid Pisga, och BethJesimoth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Och alla de städer på slättmarkene; och hela Sihons, de Amoreers Konungs, rike, som satt i Hesbon, den Mose slog med de Förstar i Midian, Evi, Rekem, Zur, Hur och Reba, hvilke Konung Sihons höfvitsmän voro, som i landena bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Dertill Bileam, Beors son, den spåmannen, slogo Israels barn med svärd, samt med de andra dräpna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Och landamäret till Rubens barn var Jordan. Detta är nu Rubens barnas arfvedel i deras ätter, städer och byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Gads barnas slägte, efter deras ätter, gaf Mose,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Så att deras landsändar voro Jaeser, och alla de städer i Gilead, och halft Ammons barnas land, allt intill Aroer, som ligger för Rabbah;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'Och ifrå Hesbon intill RamathMizpe och Betonim; och ifrå Mahanaim allt intill Debirs landsändar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'Men i dalenom, BethHaram, BethNimra, Succoth och Zaphon, som qvart var af Sihons rike, Konungens i Hesbon, hvilkets gränsa var Jordan, allt intill ändan af hafvet Cinnereth, på denna sidone Jordan, österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Detta är nu Gads barnas arfvedel, i deras ätter, städer och byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Den halfva Manasse barnas slägt, efter deras ätter, gaf Mose,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Så att deras landsändar voro ifrå Mahanaim, hela Basan; hela Ogs rike, Konungens i Basan, och alla Jairs byar, som i Basan ligga, nämliga sextio städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Och halfva Gilead, Astaroth, Edrei, Ogs rikes städer i Basan, gaf han Machirs Manasse sons barnom, det är, hälftena af Machirs barnom, efter deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Detta är det som Mose utskifte uppå Moabs mark, hinsidon Jordan in mot Jericho, österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Men Levi slägte gaf Mose ingen arfvedel; ty Herren Israels Gud är deras arfvedel, såsom han dem sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Detta är nu det som Israels barn intogo i Canaans lande, hvilket dem emellan utskifte Presten Eleazar och Josua, Nuns son, och de öfverste fäder i Israels barnas slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Och de skifte det emellan sig med lott, såsom Herren budit hade genom Mose, att gifva de halftionde slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Ty de två slägterna, och den halfva, hade Mose gifvit arfvedel hinsidon Jordan; men Leviterna hade han ingen arfvedel gifvit ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Ty Josephs barn vordo två slägter, Manasse och Ephraim; derföre gåfvo de Leviterna ingen del i landena, utan städer, der de skulle bo uti, och förstäder för deras boskap, och håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Såsom Herren hade budit Mose, så gjorde Israels barn, och skifte landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Då gingo Juda barn fram till Josua i Gilgal; och Caleb, Jephunne son, den Kenisiten, sade till honom: Du vetst hvad Herren sade till den Guds mannen Mose, på mina och dina vägnar, i KadesBarnea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Jag var fyratio åra gammal, när Mose Herrans tjenare mig utsände ifrå KadesBarnea, till att bespeja landet; och jag sade honom igen efter mitt samvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Men mine bröder, som med mig uppgångne voro, gjorde folkena ett förskräckt hjerta; men jag följde Herran min Gud troliga efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Då svor Mose på den samma dagen, och sade: Det landet, som du på trädt hafver med din fot, skall vara din och dina barnas arfvedel till evig tid; derföre, att du Herran min Gud troliga efterföljt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Och nu, si, Herren hafver låtit mig lefva, såsom han sagt hade; det är nu fem och fyratio år, sedan Herren detta sade till Mose, då Israel vandrade i öknene; och si, jag är nu på denna dag fem och åttatio åra gammal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Och är ännu i dag så stark, som jag var på den dagen, då Mose sände mig ut; såsom min magt var på den tiden, så är hon ännu, till att strida och till att gå ut och in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Så gif mig nu detta berget, om hvilket Herren sade på den dagen; ty du hörde det på den tiden, att de Enakim bo deruppå, och äro store och faste städer, om Herren ville vara med mig, att jag kunde fördrifva dem, såsom Herren sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Då välsignade Josua honom, och gaf så Caleb, Jephunne son, Hebron till arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Deraf vardt Hebron Calebs, Jephunne sons, den Kenisitens arfvedel, allt intill denna dag; derföre, att han hade troliga efterföljt Herran Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Men Hebron kallades i förtiden KiriathArba, den en stor man var ibland de Enakim. Och landet hade återvändt örliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Juda barnas slägtes lott, efter deras ätter, var in emot Edoms landsändar, vid den öknen Zin, som söderut stöter inpå söderlanden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Så att deras södergränsor voro ifrån ändanom af salthafvet, det är, ifrå den tungone som drager söderåt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Och går dädan uppåt Akrabbim, och går igenom Zin, och går uppåt ifrå sunnan intill KadesBarnea; och går igenom Hezron, och går uppåt Adar, och böjer sig omkring Karkaa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Och går igenom Azmon, och kommer ut vid Egypti bäck, så att änden af den gränson varder hafvet. Detta äro nu edra gränsor söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Men östergränsen är salthafvet intill Jordans ända. Den norra gränsan är ifrå hafsens tungo, som är vid Jordan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Och går uppåt intill BethHogla, och drager sig ifrå nordan intill BethAraba, och går uppåt till Bohans sten, Rubens sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Och går uppåt till Debir ifrån Achors dal, och ifrå norra sidone, som vet åt Gilgal, det tvärtöfver ligger vid Adummim uppåt, hvilket sunnantill ligger vid bäcken; sedan går hon uppåt till det vattnet EnSemes, och går ut vid den brunnen Rogel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Sedan går hon uppåt till Hinnoms sons dal, vid den Jebuseens sido, som bor söderut, det är Jerusalem; och går uppåt öfver bergsklinten, som ligger för den dalen Hinnom vesterut, hvilken stöter inpå sidona af Rephaims dal norrut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Sedan går hon ifrå den samma bergsklinten, intill den vattubrunnen Nephtoah, och går ut till de städer vid Ephrons berg, och böjer sig åt Baala, det är KiriathJearim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Och går omkring ifrå Baala vesterut intill berget Seir, och går utmed sidone af det berget Jearim ifrå nordan, det är Chesalon, och kommer neder till BethSemes, och går igenom Thimna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Och kommer ut vid sidona af Ekron norrut, och drager sig inåt Sichron, och går öfver det berget Baala, och kommer ut vid Jabneel; så att hennes yttersta är hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Den gränsan vesterut är det stora hafvet. Detta är nu Juda barnas gränsor allt omkring i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Men Caleb, Jephunne son, vardt gifvet hans del ibland Juda barn, efter som Herren hade befallt Josua; nämliga KiriathArba, Enaks faders, det är Hebron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Och Caleb fördref dädan de tre Enaks söner, Sesai, Ahiman och Thalmai, Enaks afföda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Och drog dädan uppåt till Debirs inbyggare; och Debir het tillförene KiriathSepher.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Och Caleb sade: Den som slår KiriathSepher, och vinner det, honom vill jag gifva mina dotter Achsa till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Då vann det Athniel, Kenas son, Calebs broders; och han gaf honom sina dotter Achsa till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Och det begaf sig, då hon indrog, vardt henne rådet, att bedas en åker af sinom fader; och hon gaf sig ifrån åsnan. Då sade Caleb till henne: Hvad är dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Hon sade: Gif mig en välsignelse; ty du hafver gifvit mig ett söderland, gif mig ock vattukällor; så gaf han henne källor ofvan och nedan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Detta är nu Juda slägtes arfvedel i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Och Juda barnas slägtes städer ifrå den ena sidone till den andra, utmed de Edomeers gränsor söderut, voro desse: Kabzeel, Eder, Jagur,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, AdAda,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Hazor, Jithnan,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siph, Telem, Bealoth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'HazorHadatta, Kerioth, Hezron, det är Hazor,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Aman, Sema, Molada,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'HazarGadda, Hesmon, BethPalet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'HazarSual, BerSeba, Bisjothja,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Jjim, Azem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltholad, Chesil, Horma,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Ziklag, Madmanna, Sansanna,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaoth, Silhim, Ain, Rimmon. Det äro nio och tjugu städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Men i dalarna voro Esthaol, Zorga, Asna,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Sanoah, EnGannim, Tappuah, Enam,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth, Adullam, Socho, Aseka,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saaraim, Adithaim, Gedera, Gederothaim. Det äro fjorton städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenan, Hadasa, MigdalGad,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilean, Mizpe, Joktheel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachis, Bozkath, Eglon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Chabbon, Lahmas, Cithlis,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederoth, BethDagon, Naama, Makkeda. Det äro sexton städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Ether, Asan,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiphthah, Asna, Nesib,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegila, Achsib, Maresa. Det äro nio städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron med dess döttrar och byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Ifrån Ekron och intill hafvet, allt det som räcker intill Asdod, och dess byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod med dess döttrar och byar, Gaza med dess döttrar och byar intill Egypti bäck, och det stora hafvet är gränsan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Men uppå berget var Samir, Jathir, Socho,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, KiriathSanna, det är Debir,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Estemo, Anim,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Holon, Gilo. Det äro ellofva städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Esean,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, BethTappuah, Apheka,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, KiriathArba, det är Hebron, Zior. Det äro nio städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Carmel, Siph, Jutta,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jesreel, Jokedam, Sanoah,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gibea, Thimna. Det äro tio städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Bethzur, Gedor,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarath, BethAnoth, Elthekon. Det äro sex städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'KiriathBaal, det är KiriathJearim, Rabba; två städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Men i öknene voro, BethAraba, Middin, Sechacha,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan, och den saltstaden, och EnGedi. Det äro sex städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Men de Jebuseer bodde i Jerusalem, och Juda barn kunde icke fördrifva dem; alltså blefvo de Jebuseer med Juda barnom i Jerusalem allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Och Josephs barnom föll lotten till ifrå Jordan, in mot Jericho, allt intill vattnet vid Jericho ifrån östan, och öknen, som går uppifrå Jericho genom det berget BethEl;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Och går ut ifrå BethEl till Lus, och går igenom den gränson ArchiAtaroth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Och drager sig nederåt vesterut, till den gränson Japhleti, allt intill den nedra BethHorons gränso, och allt intill Gaser; och dess ände är vid hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Detta fingo nu Josephs barn till arfvedel, Manasse och Ephraim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Ephraims barnas gränsa i deras ätter till deras arfvedel ifrån östan var AtarothAddar, allt intill det öfra BethHoron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Och går ut vesteråt vid Michmethath, som norrut ligger, der böjer det sig omkring öster om den staden ThaanathSilo; och går ifrån östan inåt Janoha;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Och kommer neder ifrå Janoha till Ataroth, och Naaratha, och stöter inpå Jericho, och går ut vid Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Ifrå Tappuah går hon vesterut till NahalKana, och hennes utgång är i hafvet. Detta är nu Ephraims barnas slägtes arfvedel, till deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Och alle Ephraims barnas gränsostäder med deras byar, lågo förströdde ibland Manasse barnas arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Och de fördrefvo icke de Cananeer, som bodde i Gaser; så blefvo då de Cananeer ibland Ephraim allt intill denna dag, och vordo skattskyldige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Och lotten föll till Manasse slägte, den Josephs förste son var, och föll till Machir, Manasse första son, Gileads fader; ty han var en god stridsman, derföre fick han Gilead och Basan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Dem androm Manasse barnom uti deras ätter föll också till, nämliga: Abiesers barnom, Heleks barnom, Asriels barnom, Sechems barnom, Hephers barnom, och Semida barnom. Desse äro Manasse barn, Josephs sons, som mankön voro i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Men Zelaphehad, Hephers son, Gileads sons, Machirs sons, Manasse sons, hade inga söner, utan döttrar; och deras namn äro desse: Mahela, Noa, Hogla, Milca, Thirza.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Och de gingo fram för Presten Eleazar, och för Josua, Nuns son, och för de öfversta, och sade: Herren böd Mose, att han skulle gifva oss arfvedel ibland våra bröder; så gaf han dem ock arfvedel ibland deras faders bröder, efter Herrans befallning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Men Manasse föllo tio snöre till, förutan det landet Gilead och Basan, som på hinsidon Jordan ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Ty Manasse döttrar togo arfvedel med hans söner; och det landet Gilead kom de andra Manasse barn till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Och Manasse gränsa var ifrån Asser till Michmethath, som ligger för Sechem, och går ut på högra handena intill dem af EnTappuah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Ty det landet Tappuah kom Manasse till, och är Manasse gränsa invid Ephraims barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Sedan går hon neder till NahalKana söderut till bäckstäderna, hvilka Ephraim tillhöra ibland Manasse städer; men ifrå nordan är Manasse gränsa inpå bäcken, och går ut i hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Ephraims söderut, och Manasse norrut, och hafvet är hans landamäre, och stöter inpå Asser ifrå nordan, och inpå Isaschar ifrån östan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Så hade nu Manasse ibland Isaschar och Asser, BethSean och dess döttrar, Jibleam och dess döttrar, och dem i Dor och dess döttrar, och dem i Endor och dess döttrar, och dem i Thaanach och dess döttrar, och dem i Megiddo och dess döttrar, och tredje delen Naphet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Och Manasse barn kunde icke intaga de städer; utan de Cananeer begynte till att bo i dessa landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Men då Israels barn vordo mägtige, gjorde de de Cananeer skattskyldiga, och fördrefvo dem icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Då talade Josephs barn till Josua, och sade: Hvi hafver du icke gifvit mig mer än en lott, och ett snöre af arfvedelenom, och jag är dock ett mycket folk, såsom Herren hafver välsignat mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Då sade Josua till dem: Efter du äst ett mycket folk, så gack upp i skogen, och rödj dig der rum uti de Phereseers och Resars land, efter Ephraims berg är dig för trångt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Då sade Josephs barn: Berget kunne vi icke få; ty de Cananeer bruka alle jernvagnar, som i de landena Emek bo, när hvilko ligger BethSean och dess döttrar, och Jisreel i Emek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Josua sade till Josephs hus, Ephraim och Manasse: Du äst ett mycket folk; och efter du så mycket äst, måste du icke hafva en lott;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Utan berget skall höra dig till, der skogen är; der rödj om dig, så blifver det dins lotts ände, när du fördrifver de Cananeer, som jernvagnar hafva och mägtige äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Och hela menigheten af Israels barn församlade sig i Silo, och der uppsatte de vittnesbördsens tabernakel; och landet var dem undergifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Och voro ännu sju slägter af Israels barn, hvilkom deras del icke utskift var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Och Josua sade till Israels barn: Huru länge viljen I vara så late, att I icke gån åstad, och tagen landet in, som Herren edra fäders Gud eder gifvit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Tager eder af hvarjo slägtene tre män, att jag må sända dem, och de stå upp, och gå igenom landet, och beskrifva det efter deras arfvedelar, och komma till mig igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Skifter landet i sju delar: Juda skall blifva vid sina gränsor sunnanefter; och Josephs hus skall blifva vid sina gränsor nordanefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Men I, beskrifver de sju delars land, och bärer det hit till mig, så vill jag kasta eder lott för Herranom vårom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Ty Leviterna hafva ingen del ibland eder, utan Herrans Presterskap är deras arfvedel; men Gad och Ruben, och den halfva slägten Manasse, hafva tagit sin del på hinsidon Jordan österut, den Mose Herrans tjenare dem gaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Då stodo de män upp, och foro åstad; och Josua böd dem, då de gå ville till att beskrifva landet, och sade: Vandrer igenom landet, och beskrifver det, och kommer igen till mig, att jag må kasta eder lott för Herranom i Silo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Så gingo männerna åstad, och drogo landet igenom, och beskrefvo det på en skrift efter städerna i sju delar; och kommo till Josua i lägret igen i Silo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Då kastade Josua lotten öfver dem i Silo för Herranom, och skifte der landet ut ibland Israels barn, hvarjom och enom sin del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Och föll BenJamins barnas slägtes lott efter deras ätter, och vardt deras lotts gränsa emellan Juda barn och Josephs barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Och deras gränsa var på sidone norrut ifrå Jordan, och går uppåt utmed Jericho på norra sidone, och kommer upp på berget vesterut; och utgången är vid den öknen BethAven;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Och går dädan intill Lus, utmed sidone på Lus söderut, det är BethEl; och går nederåt intill AtharothAdar vid berget, som ligger sunnan vid det nedra BethHoron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Och går neder, och böjer sig omkring till vestra sidona söderut ifrå berget, som ligger för BethHoron söderut; och går ut vid KiriathBaal, det är KiriathJearim, Juda barnas stad. Detta är nu den sidan vesterut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Men den sidan söderut är ifrå KiriathJearim, och går ut emot vester, och kommer ut till vattubrunnen Nephtoah:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Och går neder vid ändan på berget, som ligger för Hinnoms sons dal, den der ligger i Naphaims dal norrut, och går neder genom Hinnoms dal på de Jebuseers sido, sunnantill, och kommer neder vid den brunnen Rogel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Och drager sig ifrå nordan, och kommer ut till EnSemes, och kommer ut till de högar, som ligga uppe emot Adummim, och kommer ned till Bohens sten, Rubens sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Och går utmed sidone vid slättmarkena, som ligger norrut, och kommer neder på slättmarkena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Och drager utmed den sidone vid BethHogla, som ligger norrut, och änden deraf vid salthafsens tungo norrut, inpå Jordans södra ända. Detta är nu den södra gränsan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Men till den östra sidan skall Jordan vara änden. Detta är nu BenJamins arfvedel i deras gränsor allt omkring, i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Men städerna BenJamins barnas slägters, ibland deras ätter, äro desse: Jericho, BethHogla, EmekKeziz,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'BethAraba, Zemaraim, BethEl,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avim, Para, Ophra,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'CepharAmmonai, Ophni, Gaba. Det äro tolf städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Rama, Beeroth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mizpe, Cephira, Moza,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeel, Thareala,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Zela, Eleph, och de Jebuseer, det är Jerusalem, Gibeath, Kiriath; fjorton städer, och deras byar. Detta är nu BenJamins barnas arfvedel i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Sedan föll den andre lotten Simeons barnas slägtes, efter deras ätter; och deras arfvedel var ibland Juda barnas arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Och kom på deras arfvedel BerSeba, Seba, Molada,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'HazarSual, Bala, Azem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Bethul, Horma,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Ziklag, BethMarkaboth, HazarSusa,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'BethLebaoth, Saruhen. Det äro tretton städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon, Ether, Asan. Det äro fyra städer och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Dertill alla byar, som ligga omkring dessa städerna, allt intill BaalathBer, Ramath söderut. Detta är Simeons barnas arfvedel i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Ty Simeons barnas arfvedel är ibland Juda barnas snöre; efter Juda barnom var deras arfvedel för stor; derföre fingo Simeons barn del ibland deras arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Tredje lotten föll på Sebulons barn efter deras ätter; och deras arfvedels gränsa var allt intill Sarid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Och går uppåt vesterut till Marala, och stöter inpå Dabbaseth, och stöter inpå bäcken, som löper framom Jokneam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Och vänder sig ifrå Sarid österut, allt intill den gränsan CislothThabor; och går ut till Dabberath, och räcker upp till Japhia;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Och löper dädan österåt igenom GittaHepher, IttaKazin, och kommer ut till Rimmon, Hammethoar, Hannea;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Och böjer sig omkring ifrå nordan inåt Nathon; och utgången är i den dalen JiphtaEl;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Kattath, Nahalal, Simron, Jideala och BethLehem. Det äro tolf städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Detta är nu Sebulons barnas arfvedel till deras ätter; och detta är deras städer och byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Fjerde lotten föll på Isaschars barn efter deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Och deras gränsa var Jisreel, Chesulloth, Sunem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hapharaim, Sion, Anaharath,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbith, Kisjon, Abez.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remeth, EnGannim, EnHadda, BethPazzez;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Och stöter inpå Thabor, Sahazima, BethSemes, och utgången deraf var inuppå Jordan; sexton städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Detta är nu Isaschars barnas slägters arfvedel till deras ätter, städer och byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Femte lotten föll på Assers barnas slägte i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Och deras gränsa var Helkath, Hali, BetenAchsaph,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alammelech, Amead, Miseal; och stöter inpå Carmel vid hafvet, och till SihorLibnath;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Och vänder sig österut till BethDagon, och stöter inpå Sebulon, och till den dalen JiphthahEl norrut, BethEmek, Negiel, och kommer ut vid Cabul på venstra sidone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ebron, Rehob, Hammon, Kana, allt intill det stora Zidon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Och vänder sig inåt Rama, allt intill den fasta staden Zor; och vänder sig åt Hosa, och går ut vid hafvet efter snöret åt Achsib;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Umma, Aphek, Rehob; två och tjugu städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Detta är nu Assers barnas slägters arfvedel till deras ätter, städer och byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Sjette lotten föll på Naphthali barn i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Och deras gränsa var ifrå Heleph, Allon, igenom Zaanannim, Adami, Nekeb, JabneEl, allt intill Lakum, och går ut inpå Jordan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Och vänder sig vesterut åt Asnoth Thabor; och kommer dädan ut och till Hukkob, och stöter inpå Sebulon söderut, och till Assur vesterut, och till Juda invid Jordan österut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Och hafver fasta städer, Ziddim, Zer, Hammath, Rakkath, Chinnareth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama, Hazor,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei, EnHazor,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jireon, MigdalEl, Horem, BethAnath, BethSames; nitton städer, och deras byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Detta är nu Naphthali barnas slägters arfvedel till deras ätter, städer och byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Sjunde lotten föll på Dans barnas slägte i deras ätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Och gränsan af deras arfvedel var: Zorga, Esthaol, IrSames,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabbin, Ajalon, Jithla,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Timnatha, Ekron,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Eltheke, Gibbethon, Baalath,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Benebarak, GathRimmon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'MeJarkon, Rakkon med den gränsona vid Japho:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Och der går Dans barnas gränsa ut. Och Dans barn drogo upp, och stridde emot Lesem och vunno det, och slogo det med svärdsegg; och togo det in, och bodde deruti, och kallade det Dan, efter deras faders namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Detta är nu Dans barnas slägtes arfvedel i deras ätter, städer och byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Och då de hade lyktat utskifta landet med dess gränsor, gåfvo Israels barn Josua, Nuns son, en arfvedel ibland sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Och gåfvo honom efter Herrans befallning den stad, som han begärade, som var ThimnathSerah uppå Ephraims berg; den staden byggde han, och bodde deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Desse äro nu de arfvedelar, som Eleazar Presten, och Josua, Nuns son, och de öfverste af fäderna ibland slägterna, genom lott utskifte Israels barnom i Silo för Herranom, inför dörrene af vittnesbördsens tabernakel; och lyktade så landsens utskiftning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Och Herren talade med Josua, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Säg Israels barnom: Skicker ibland eder några fristäder, om hvilka jag eder genom Mosen sagt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Att dit må fly en mandråpare, som slår en själ oförvarandes och ovetandes; att de må ibland eder fri vara för blodhämnaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Och den som flyr till någon af de städer, han skall stå utanför stadsporten, och för de äldsta i staden förtälja sin sak; så skola de taga honom in i staden till sig, och få honom rum, att han må bo när dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Och om blodhämnaren kommer efter honom, skola de icke öfverantvarda dråparen i hans händer, efter han oförvarandes slog sin nästa, och var icke tillförene hans ovän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Så skall han bo i stadenom, tilldess han står för menighetene till rätta, allt intilldess öfverste Presten dör, som på den tiden är; då skall dråparen komma till sin stad igen, och i sitt hus i stadenom, der han utflydder var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Då helgade de Kedes i Galilea på Naphthali berg, och Sechem på Ephraims berg, och KariathArba, det är Hebron, på Juda berg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Och på hinsidon Jordan vid Jericho österut skickade de Bezer i öknene på slättmarkene, af Rubens slägte; och Ramoth i Gilead, af Gads slägte, och Golan i Basan, af Manasse slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Det voro då de städer, som Israels barnom förelagde voro, och främlingomen som ibland dem bodde, att dit skulle fly den som en själ oförvarandes sloge; att han icke skulle ihjälslås af blodhämnaren, intilldess han hade ståndit för menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Då trädde de öfverste fäder ibland Leviterna fram för Presten Eleazar, och för Josua, Nuns son, och för de öfversta fäder ibland Israels barnas slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'Och talade med dem i Silo i Canaans land, och sade: Herren hafver budit genom Mose, att man skulle gifva oss städer till att bo uti, och deras förstäder till vår boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Så gåfvo då Israels barn Leviterna utaf deras arfvedelar, efter Herrans befallning, dessa städer och deras förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Och lotten föll uppå de Kehathiters ätt; och kommo Aarons barnom Prestens af Leviterna tretton städer till, igenom lotten; af Juda slägte, af Simeons slägte, och af BenJamins slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Men de andra Kehats barnom af samma ätt kommo tio städer till, igenom lotten; af Ephraims slägte, af Dans slägte, och af den halfva slägtene Manasse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Men Gersons barnom af samma ätt kommo tretton städer till, igenom lotten; af Isaschars slägte, af Assers slägte, och af Naphthali slägte, och af den halfva slägtene Manasse i Basan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merari barnom till deras ätter kommo tolf städer till; af Rubens slägte, af Gads slägte, och af Sebulons slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Alltså gåfvo Israels barn Leviterna igenom lotten dessa städer, och deras förstäder, såsom Herren genom Mose budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Af Juda barnas slägte, och af Simeons barnas slägte, gåfvo de dessa städerna, hvilka de nämnde efter deras namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Aarons barnom af de Kehathiters ätt, af Levi barnom; ty förste lotten var deras;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Så gåfvo de dem nu KiriathArba, den Enaks fader var, det är Hebron, på Juda berg, och dess förstäder allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Men stadsens åker, och hans byar, gåfvo de Caleb, Jephunne son, till hans arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Så gåfvo de Prestens Aarons barnom den mandråpares fristad Hebron, och hans förstäder; Libna, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jathir, och dess förstäder; Estemoa, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holon, och dess förstäder; Debir, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ain, och dess förstäder; Jutta, och dess förstäder; BethSemes, och dess förstäder; nio städer af dessa två slägterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Af BenJamins slägte gåfvo de fyra städer: Gibeon, och dess förstäder; Geba och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anathoth, och dess förstäder; Almon, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Så att alle Aarons Prestens barnas städer voro tretton, med deras förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Men de andra Kehats Levitens barnas ätter kommo fyra städer till, igenom deras lott, af Ephraims slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Och de gåfvo dem den mandråpares fristaden Sechem, och hans förstäder på Ephraims berg; Geser, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibzaim, och dess förstäder; BethHoron, och dess förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Af Dans slägte fyra städer: Eltheke, och dess förstäder; Gibbethon, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon, och dess förstäder; GathRimmon, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Af den halfva slägtene Manasse två städer: Thaenach, och dess förstäder; GathRimmon, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Så att alla de andra Kehats ätts barnas städer voro tio, med deras förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Men Gersons barnom af de Leviters ätter vordo gifne af den halfva slägtene Manasse, två städer, den mandråpares fristaden Golan i Basan, med dess förstäder; Beestera, och dess förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Af Isaschars slägte fyra städer: Kision, och dess förstäder; Dabrath, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmuth, och dess förstäder; EnGannim, och dess förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Af Assers slägte fyra städer: Miseal, och dess förstäder; Abdon, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkath, och dess förstäder; Rehob, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Af Naphthali slägte tre städer: den mandråpares fristaden Kedes i Galilea, och dess förstäder; HamothDor, och dess förstäder; Karthan, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Så att alle Gersoniters ätts städer voro tretton, med deras förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Men Merari barnom, de andra Leviterna vardt gifvet, af den slägten Sebulon, fyra städer: Jokneam, och dess förstäder; Kartha, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna, och dess förstäder; Nahalal, och dess förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Af Rubens slägte fyra städer: Bezer, och dess förstäder; Jahza, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemoth, och dess förstäder; Mephaath, och dess förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Af Gads slägte fyra städer: den mandråpares fristaden Ramoth i Gilead, och dess förstäder; Mahanaim, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbon, och dess förstäder; Jaeser, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Så att alle Merari barnas, de andra Leviternas städer, ibland deras ätter, efter deras lott, voro tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Alle Leviternas städer, ibland Israels barnas arf, voro åtta och fyratio, med deras förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Och hvar och en af dessa hade sin förstad om sig; den ene som den andre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Alltså gaf Herren Israels barnom allt landet, som han svorit hade deras fäder att gifva; och de togo det in, och bodde deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Och Herren lät dem hafva ro för allom omkring dem, såsom han deras fäder svorit hade. Och ingen af deras fiendar stod emot dem; utan alla deras fiendar gaf Herren i deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Och felade intet af det goda, som Herren Israels hus tillsagt hade; utan det skedde så allt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Då kallade Josua till sig de Rubeniter och Gaditer, och den halfva slägtena Manasse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Och sade till dem: I hafven hållit allt det Mose Herrans tjenare eder budit hafver, och lydt mine röst i allt det jag hafver budit eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'I hafven icke öfvergifvit edra bröder nu i en lång tid, allt intill denna dag; och hafven blifvit vid Herrans edars Guds bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Efter nu Herren edar Gud hafver låtit edra bröder komma till ro, såsom han dem sagt hade; så vänder nu om igen, och drager till edra hyddor i edars arfs land, som Mose Herrans tjenare eder gifvit hafver på hinsidon Jordan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Allenast tager der vara uppå granneliga, att I gören efter de bud och lag, som Mose Herrans tjenare eder budit hafver; att I älsken Herran edar Gud, och vandren uppå alla hans vägar, och hållen hans bud, och hållen eder intill honom, och tjenen honom af allo hjerta, och af allo själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Så välsignade Josua dem, och lät gå dem; och de gingo till deras hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Den halfva slägtene Manasse hade Mose gifvit i Basan; den andra hälftene gaf Josua ibland deras bröder på desso sidone Jordan, vestantill. Och då han lät dem gå till deras hyddor, och hade välsignat dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Sade han till dem: I kommen hem igen med stora ägodelar till edra hyddor, med ganska mycken boskap, silfver, guld, koppar, jern och kläder; så skifter nu edra fiendars rof med edra bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Och så vände de Rubeniter och Gaditer, och den halfva slägten Manasse, om igen, och gingo ifrån Israels barn af Silo, som i Canaans land ligger, att de skulle draga in i Gileads land till deras arfs land, det de till arfs fått hade af Herrans befallning genom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Och då de kommo till de högar vid Jordan, som i Canaans land ligga, byggde de samme Rubeniter, Gaditer, och halfva Manasse slägt, der vid Jordan ett stort skönt altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Då Israels barn hörde sägas: Si, Rubens barn, Gads barn, och den halfva slägten Manasse hafva byggt ett altare emot Canaans land, vid Jordans högar, på desso sidone vid Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Församlade de sig hela menigheten i Silo, att de skulle draga upp till dem, och strida med dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Och sände till dem in uti Gileads land, Pinehas, Eleazars Prestens son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'Och med honom tio öfversta Förstar ibland deras fäders hus, af hvarjo Israels slägt en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Och när de kommo till dem i landet Gilead, talade de med dem, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Så låter hela Herrans menighet säga eder: Hvi synden I så emot Israels Gud; och vänden eder i dag ifrå Herranom, dermed att I byggen eder ett altare, och fallen ifrå Herranom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Är oss icke nog med Peors missgerning, af hvilko vi ännu på denna dag icke renade äre; och en plåga kom i Herrans menighet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Och I vänden eder i dag bort ifrå Herranom, och ären i dag affällige vordne ifrå Herranom; på det han i dag eller morgon skall vredgas öfver hela Israels menighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Tycker eder, att edart arfs land är orent, så kommer hitöfver i det land, som Herren hafver, der Herrans tabernakel är, och tager arf ibland oss; och träder icke ifrå Herranom, och ifrån oss, att I byggen eder ett altare, förutan Herrans vårs Guds altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Förbröt icke Achan, Serahs son, sig på det spillgifna; och vreden kom öfver hela Israels menighet, och han umgalt icke sina synd allena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Då svarade Rubens barn, och Gads barn, och den halfva slägten Manasse, och sade till de höfvitsmän och Förstar af Israel:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Herren den starke Gud, Herren den starke Gud vet det, och Israel desslikes; är detta afträdning eller synd emot Herran, så hjelpe han oss intet i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Och om vi altaret fördenskull byggt hafve, att vi vilje vända oss ifrå Herranom, offra deruppå bränneoffer och spisoffer, eller göra der tackoffer uppå, så hämnes det Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Och om vi icke det mycket heldre för denna sakens skull gjorde, och sade: I dag eller morgon måtte edor barn säga till vår barn: Hvad hafven I göra med Herranom Israels Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Herren hafver satt Jordan till ett landamäre emellan oss och eder; I Rubens och Gads barn, I hafven ingen del med Herranom; och så måtte edor barn komma vår barn ifrå Herrans fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Derföre sade vi: Låt oss bygga ett altare, icke till något offer eller bränneoffer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Utan på det att det må vara ett vittnesbörd emellan oss och eder, och våra efterkommande, att vi måge tjena Herranom för honom med vårt bränneoffer, tackoffer och annor offer; och edor barn icke behöfva i dag eller morgon säga till vår barn: I hafven ingen del med Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'När de nu vordo sägande till oss, eller våra efterkommande i dag eller morgon, så kunna de säga: Ser liknelsen till Herrans altare, hvilket våre fäder gjort hafva; icke till offer eller bränneoffer, utan till ett vittnesbörd emellan oss och eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Bort det ifrån oss, att vi skulle träda ifrå Herranom, så att vi i dag skulle vända oss ifrå Herranom, och bygga ett altare till bränneoffer, och till spisoffer, och annor offer, förutan Herrans vårs Guds altare, som står för hans tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Då nu Pinehas Presten, och de öfverste för menighetene, Israels Förstar, som med honom voro, detta hörde, täcktes dem väl Rubens barnas, Gads, och den halfva Manasse slägts ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Och Pinehas, Prestens Eleazars son, sade till Rubens, Gads, och Manasse barn: I dag förstå vi, att Herren är med oss, att I icke hafven syndat emot Herran med denna gerning; nu hafven I frälst Israels barn utu Herrans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Så drog Pinehas, Prestens Eleazars son, och de öfverste, utu Gileads land, ifrå Rubens och Gads barn, åter in uti Canaans land, till Israels barn, och sade dem det igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Då behagade det Israels barnom väl, och lofvade Israels barnas Gud; och sade intet mer, att de ville draga upp emot dem till slags, till att förderfva landet, som Rubens och Gads barn uti bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Och Rubens och Gads barn kallade det altaret, att det skall vara ett vittne emellan oss, och att Herren är Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Efter lång tid, sedan Herren hade låtit Israel komma till ro för alla deras fiendar omkring sig; och Josua nu gammal och väl till ålders kommen var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Kallade han till sig hela Israel, och deras äldsta, höfvitsmän, domare och ämbetsmän, och sade till dem: Jag är gammal och väl till ålders;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Och I hafven sett allt det Herren edar Gud gjort hafver på all dessa folken här för eder; ty Herren edar Gud hafver sjelf stridt för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Ser, jag hafver utskift eder de folk, som ännu qvare äro, genom lott, hvarjo slägtene sin arfvedel, allt ifrå Jordan, och all de folk, som jag utrotat hafver; och ifrå stora hafvet vesterut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Och Herren edar Gud skall utdrifva dem för eder, och utrota dem ifrån eder, så att I skolen intaga deras land, såsom Herren edar Gud eder sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Så varer nu fast frimodige, att I hållen och gören allt det som skrifvet står i Mose lagbok; att I icke viken derifrå, antingen på den högra sidon eller på den venstra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Att I icke kommen ibland dessa återlefda folken, som med eder ännu äro; och I icke ihågkommen, eller svärjen vid deras gudars namn, eller tjenen dem, eller tillbedjen dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Utan håller eder intill Herran edar Gud, såsom I intill denna dag gjort hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Så skall Herren fördrifva för eder stor och mägtig folk; och ingen hafver kunnat stå eder emot allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'En af eder skall jaga tusende; ty Herren edar Gud strider för eder, såsom han eder sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Derföre bevarer edra själar granneliga, att I hafven Herran edar Gud kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Men om I vänden eder härifrå, och hållen eder intill dessa återlefda folken, och befrynden eder med dem i giftermål, så att I kommen ibland dem, och de ibland eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Så veter, att Herren edar Gud skall icke mer fördrifva all dessa folken för eder; utan de skola eder varda till snaro och nät, och till en staka i edra sido, och till en törnagadd i edor ögon, tilldess han förgör eder utu det goda landet, som Herren edar Gud eder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Si, jag går i dag alla verldenes väg, och I skolen veta af allt hjerta, och af allo själ, att icke ett ord felat hafver på allt det goda, som Herren edar Gud eder sagt hafver; allt är skedt, och intet tillbakablifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Lika som nu allt det goda kommet är, som Herren edar Gud eder sagt hafver, så skall ock Herren låta komma öfver eder allt ondt, tilldess han förgör eder utu detta goda landet, som Herren edar Gud eder gifvit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Om I Herrans edars Guds förbund öfverträden, som han eder budit hafver, och gången bort, och tjenen andra gudar, och tillbedjen dem; så att Herrans vrede förgrymmar sig öfver eder, och snarliga förgör eder utu det goda landet, som han eder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Och Josua församlade alla Israels slägter till Sichem, och kallade fram de äldsta i Israel, höfvitsmän, domare och ämbetsmän. Då de voro framträdde för Gud,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Sade han till hela folket: Så säger Herren, Israels Gud: Edra fäder bodde i förtiden på hinsidon älfven, Tharah, Abrahams och Nahors fader, och tjente andra gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Då tog jag edar fader Abraham på hinsidon älfven, och lät honom vandra i hela Canaans land, och förökade honom hans säd, och gaf honom Isaac.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Och Isaac gaf jag Jacob och Esau; och gaf Esau det berget Seir till besitta; men Jacob och hans barn drogo neder uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Då sände jag Mose och Aaron, och plågade Egypten, såsom jag ibland dem gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Sedan förde jag eder och edra fäder utur Egypten, och när I kommen till hafvet, och de Egyptier jagade efter edra fäder med vagnar och resenärar intill röda hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Så ropade de till Herran, och han satte ett mörker emellan eder och de Egyptier, och förde hafvet öfver dem, och öfvertäckte dem; och edor ögon sågo hvad jag i Egypten gjorde; och I bodden i öknene i en lång tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Och jag förde eder uti de Amoreers land, som bodde på hinsidon Jordan; och då de stridde emot eder, gaf jag dem i edra händer, så att I besågen deras land, och förgjorden dem för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Då reste sig upp Balak, Zipors son, de Moabiters Konung, och stridde emot Israel, och han sände bort, och lät kalla Bileam, Beors son, att han skulle förbanna eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Men jag ville intet höra honom, och han välsignade eder; och jag frälste eder utu hans händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Och då I gingen öfver Jordan, och kommen till Jericho, stridde Jericho inbyggare emot eder, de Amoreer, Phereseer, Cananeer, Hetheer, Girgaseer, Heveer och Jebuseer; men jag gaf dem i edra händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Och sände getingar framför eder, de drefvo dem ut för eder, de två Amoreers Konungar; icke genom ditt svärd eller genom din båga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Och gaf eder ett land, der I intet på arbetat haden, och städer, som I intet uppbyggt haden; att I skullen bo deruti, och skullen äta af vingårdar, och oljoberg, som I intet planterat haden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Så frukter nu Herran, och tjener honom troliga och rättsinneliga; och låter fara de gudar, som edra fäder tjent hafva på hinsidon älfven, och i Egypten; och tjener Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Tycker eder icke godt vara, att I tjenen Herranom, så utväljer eder i dag hvem I tjena viljen; antingen den Gud, som edre fäder tjent hafva på hinsidon älfvena, eller de Amoreers gudar, i hvilkas land I bon; men jag och mitt hus vilje tjena Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Då svarade folket, och sade: Bort det, att vi skulle öfvergifva Herran, och tjena andra gudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Ty Herren vår Gud hafver fört oss och våra fäder utur Egypti land, utu träldomens hus; och hafver för vår ögon gjort så stor tecken, och bevarat oss på hela vägenom, som vi dragit hafve; och ibland alla de folk, genom hvilka vi gångne äre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Och Herren hafver utdrifvit för oss all de Amoreers folk, som bodde i landena; derföre vilje vi ock tjena Herranom; ty han är vår Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Josua sade till folket: I kunnen icke tjena Herranom; ty han är en helig Gud, och en nitälskande Gud, den eder icke förlåter edor öfverträdelse och synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'När I nu öfvergifven Herran, och tjenen en främmande gud, så skall han vända sig, och göra eder ondt; och förgöra eder, sedan han eder godt gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Men folket sade till Josua: Icke så, utan vi vilje tjena Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Då sade Josua till folket: I ären vittne öfver eder, att I hafven eder utvalt Herran, att I skolen tjena honom. Och de sade: Ja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Så lägger nu ifrån eder de främmande gudar, som ibland eder äro, och böjer edor hjerta till Herran Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Och folket sade till Josua: Vi vilje tjena Herranom vårom Gud, och lyda hans röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Så gjorde Josua på den samma dagen ett förbund med folket, och satte dem lag och rätt före i Sichem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Och Josua skref allt detta i Guds lagbok, och tog en stor sten, och reste honom der upp under ena ek, som var vid Herrans helgedom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Och sade till allt folket: Si, denne stenen skall vara vittne emellan oss; ty han hafver hört allt Herrans tal, som han med oss talat hafver; och skall vara ett vittne öfver eder, att I edar Gud icke försaka skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Alltså lät Josua folket gå, hvar och en i sin arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Och det begaf sig, när detta skedt var, att Josua, Nuns son, Herrans tjenare, blef död, då han hundrade och tio år gammal var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Och de begrofvo honom i hans arfvedels gränso i ThimnathSerah, som ligger på Ephraims berg, på norra sidone vid det berget Gaas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Och Israel tjente Herranom så länge Josua lefde, och de äldste, hvilke i långan tid lefde efter Josua, och visste alla Herrans gerningar, som han med Israel gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Och Josephs ben, som Israels barn hade fört utur Egypten, begrofvo de i Sichem, i det åkrastycket, som Jacob köpte af Hemors barnom, Sichems faders, för hundrade penningar; och vardt Josephs barnas arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Blef ock Eleazar, Aarons son, död, och de begrofvo honom i Gibeath Pinehas hans sons, det honom på Ephraims berg gifvet var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Efter Josua död frågade Israels barn Herran, och sade: Ho skall ibland oss föra örliget emot de Cananeer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Herren sade: Juda skall föra det; si, jag hafver gifvit landet i hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Då sade Juda till sin broder Simeon: Drag med mig upp i min lott, och låt oss strida emot de Cananeer, så vill jag åter draga med dig i din lott. Så drog Simeon med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Då nu Juda drog ditupp, gaf Herren honom de Cananeer och Phereseer i deras händer; och de slogo i Besek tiotusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Och de funno AdoniBesek i Besek; och stridde emot honom, och slogo de Cananeer och Phereseer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Men AdoniBesek flydde, och de jagade efter honom, fingo honom, och höggo af honom tummarna, både af hans händer och fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Då sade AdoniBesek: Sjutio Konungar, med afhuggna tummar af deras händer och fötter, hemtade upp under mitt bord; såsom jag nu gjort hafver, så hafver Gud vedergullit mig. Och de förde honom till Jerusalem, der blef han död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Men Juda barn stridde emot Jerusalem, och vunno det, och slogo det med svärdsegg, och brände staden upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Sedan drogo Juda barn neder, till att strida emot de Cananeer, som bodde på bergen, och söderut, och i dalarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Och Juda drog emot de Cananeer, som bodde i Hebron; men Hebron het i förtiden KiriathArba; och slog Sesai, och Ahiman, och Thalmai;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Och drog dädan emot Debirs inbyggare; men Debir het i förtiden KiriathSepher.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Och Caleb sade: Den som KiriathSepher slår och vinner, honom vill jag gifva mina dotter Achsa till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Då vann det Athniel, Kenas son, Calebs yngsta broders; och han gaf honom sina dotter Achsa till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Och det begaf sig, då hon indrog, vardt henne rådet, att hon skulle bedas en åker af sin fader; och hon gaf sig ifrån åsnanom. Då sade Caleb till henne: Hvad är dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Hon sade: Gif mig en välsignelse; ty du hafver gifvit mig ett söderland; gif mig ock ett, som vatten hafver. Då gaf han henne ett, som vatten hade ofvan och nedan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Och de Keniters barn, Mose svågers, drogo upp utu Palma staden med Juda barn uti Juda öken, som ligger sunnan för den staden Arad; och gingo till, och bodde ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Och Juda drog åstad med hans broder Simeon, och slogo de Cananeer i Zephat, och gåfvo honom tillspillo, och kallade staden Horma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Dertill vann Juda Gaza med dess tillhöring, och Askelon med dess tillhöring, och Ekron med dess tillhöring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Och Herren var med Juda, så att han intog berget; förty han kunde icke intaga dem som i dalarna bodde, derföre, att de hade jernvagnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Och de gåfvo Caleb Hebron, såsom Mose sagt hade; och han fördref derut de tre Enaks söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Men BenJamins barn fördrefvo icke de Jebuseer, som bodde i Jerusalem; utan de Jebuseer bodde när BenJamins barn i Jerusalem, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Sammalunda drogo ock Josephs barn upp till BethEl; och Herren var med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Och Josephs hus bespejade BethEl, det tillförene het Lus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Och hållarena fingo se en man gå utu staden, och sade till honom: Visa oss huru vi skole komma in i staden, så vilje vi göra barmhertighet med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Och när han hade vist dem hvar de skulle komma in, slogo de staden med svärdsegg; men den mannen och all hans slägt läto de gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Då drog den samme mannen in uti de Hetheers land, och byggde en stad, och kallade honom Lus. Den heter ännu i dag så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Och Manasse fördref icke BethSean med dess döttrar; icke heller Thaanach med dess döttrar, och icke heller de inbyggare i Dor med dess döttrar, ej heller de inbyggare i Jibleam med dess döttrar, ej heller de inbyggare i Megiddo med dess döttrar; och de Cananeer begynte till att bo i de samma landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Men då Israel kom till magt, gjorde han de Cananeer skattpligtiga, och fördref dem icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Sammalunda fördref icke heller Ephraim de Cananeer, som bodde i Gaser; utan de Cananeer bodde ibland dem i Gaser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Sebulon fördref icke heller dem som bodde i Kitron och Nahalol; utan de Cananeer bodde ibland dem, och voro skattpligtige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser fördref icke dem som bodde i Acco; icke heller dem som bodde i Zidon, i Ahlab, i Achsib, i Helbah, i Aphik och i Rehob;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Utan de Asseriter bodde ibland de Cananeer, som i landena bodde; ty de fördrefvo dem icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Napthali fördref icke dem som bodde i BethSemes, ej heller i BethAnath; utan bodde ibland de Cananeer, som i landena bodde; men de i BethSemes och i BethAnath vordo skattpligtige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Men de Amoreer trängde Dans barn in på bergena, och stadde dem icke till, att de kommo neder i dalarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Och de Amoreer begynte bo på de bergena Heres i Ajalon och Saalbim; dock vardt Josephs hus hand dem för svår, så att de vordo skattpligtige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Och de Amoreers gränsa var der man uppgår till Akrabbim, och ifrå klippone, och ifrå höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Och kom en Herrans Ängel upp ifrå Gilgal till Bochim, och sade: Jag förde eder utur Egypten, och lät eder komma in uti det land, som jag edra fäder svorit hade, och sade: Jag skall icke göra mitt förbund med eder ogildt i evig tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Att I icke skullen göra något förbund med detta lands inbyggare, utan skullen bryta deras altare omkull; men I hafven intet lydt mine röst. Hvi hafven I det gjort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Sade jag ock med: Jag vill icke fördrifva dem för eder; att de skola vara eder till snaro, och deras gudar eder till nät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Och då Herrans Ängel dessa orden sagt hade till all Israels barn, hof folket sina röst upp, och gret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Och kallade det rummet Bochim, och offrade der Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Ty då Josua hade släppt folket ifrå sig, och Israel var dragen hvar till sin arfvedel, till att intaga landet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Tjente folket Herranom, så länge Josua lefde, och de äldste, som länge lefde efter Josua, och sett hade alla Herrans stora gerningar, som han Israel gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Men då Josua, Nuns son, Herrans tjenare, död var, hundrade och tio år gammal,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Begrofvo de honom i hans arfvedels gränso i ThimnathHeres, på Ephraims berg, på norra sidone vid Gaas berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Då ock alle de, som på den tiden lefde, voro samkade till sina fäder, kom ett annat slägte upp efter dem, som intet kände Herran, eller de gerningar, som han med Israel gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Så gjorde Israels barn det ondt var för Herranom, och tjente Baalim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Och öfvergåfvo Herran deras fäders Gud, som dem utur Egypti land fört hade, och följde andra gudar efter, och de folks gudar, som omkring dem bodde, och tillbådo dem, och förtörnade Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Ty de öfvergåfvo ju mer och mer Herran, och tjente Baal och Astaroth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Så förgrymmade då Herrans vrede sig öfver Israel, och gaf dem i deras hand, som dem röfvade, att de dem beröfva skulle, och sålde dem i deras fiendars händer allt omkring; och de kunde icke mer stå deras fiendar emot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Utan, ehvart de vände sig, var Herrans hand emot dem till deras ofärd, såsom Herren dem sagt, och Herren dem svorit hade; och de vordo hårdeliga plågade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'När nu Herren uppväckte domare, som dem hulpo utu röfvarenas hand,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Så lydde de icke heller domarena, utan bedrefvo hor med andra gudar, och tillbådo dem, och veko snarliga af den vägen, der deras fäder på gångit hade, till att lyda Herrans bud och gjorde intet såsom de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Då nu Herren uppväckte dem domare, så var Herren med domarenom, och halp dem utu deras fiendars hand, så länge domaren lefde; ty Herren förbarmade sig öfver deras suckan, öfver dem som dem tvingade, och trängde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Men när domaren blef död, så vände de sig, och förderfvade det mer än deras fäder, så att de följde andra gudar, till att tjena dem, och tillbedja dem, de gingo icke ifrå sina påfunder, eller ifrå sina halsstyfva väsende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Derföre förgrymmade sig så Herrans vrede öfver Israel, att han sade: Efter detta folket hafver gått ifrå mitt förbund, som jag deras fäder budit hafver, och icke velat höra min röst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Så skall jag nu härefter ingen fördrifva af de Hedningar, som Josua återlefde, då han blef död;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Att jag på dem må försöka Israel, om de vilja blifva på Herrans vägar, och vandra på dem, såsom deras fäder vandrat hafva, eller ej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Så lät då Herren blifva dessa Hedningar, att han icke med hast fördref dem, hvilka han i Josua hand icke gifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Desse äro de Hedningar, som Herren lät blifva, på det han skulle med dem försöka Israel, som intet visste utaf Canaans örlig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Och att Israels barnas afföda måtte veta och lära strida, de som tillförene intet visste deraf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Nämliga de fem Philisteers Förstar, och alla Cananeer och Zidonier, och de Heveer, som bodde på Libanons berg, allt ifrå det berget BaalHermon, tilldess man kommer till Hamath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'De samme blefvo till att försöka Israel med dem, att man måtte förfara, om de lydde Herrans bud, som han deras fäder budit hade genom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Då nu Israels barn bodde ibland de Cananeer, Hetheer, Amoreer, Phereseer, Heveer och Jebuseer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Togo de deras döttrar till hustrur, och gåfvo sina döttrar deras söner, och tjente deras gudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Och gjorde illa för Herranom, och förgåto Herran deras Gud, och tjente Baalim och lundom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Då förgrymmade sig Herrans vrede öfver Israel, och sålde dem i CusanRisathaims hand, Konungens i Mesopotamien; och så tjente Israels barn CusanRisathaim i åtta år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Då ropade Israels barn till Herran, och Herren uppväckte dem en frälsare, som dem frälste, Athniel, Kenas son, Calebs yngste broders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Och Herrans Ande var i honom, och han vardt domare i Israel, och drog ut till strid; och Herren gaf CusanRisathaim, Konungen i Syrien, i hans hand, så att hans hand vardt honom öfvermägtig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Så blef landet stilla i fyratio år; och Athniel, Kenas son, blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Men Israels barn gjorde ännu mer ondt för Herranom. Då stärkte Herren Eglon, de Moabiters Konung, emot Israel, derföre att de gjorde det ondt var för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Och församlade till sig Ammons barn och de Amalekiter; och han drog åstad, och slog Israel, och tog in Palma staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Och Israels barn tjente Eglon, de Moabiters Konung, i aderton år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Så ropade de till Herran, och Herren uppväckte dem en frälsare, Ehud, Gera son, Jemini sons; han var ofärdig i sin högra hand. Och Israels barn sände med honom skänker till Eglon, de Moabiters Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Och Ehud gjorde sig ett tveeggadt svärd, en aln långt, och band det under sin kläder på högra låret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Och bar fram skänken till Eglon, de Moabiters Konung; och Eglon var en ganska fet man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Och när han hade fått ifrå sig skänken, öfvergaf han folket, som hade burit skänken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Och vände tillbaka igen ifrå de afgudar i Gilgal; och lät båda: Jag hafver, o Konung, något hemligit tala vid dig. Han bad gifva ljud; och de gingo alle ut, som stodo omkring honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Och Ehud kom till honom in, och han satt uti en sommarsal allena; och Ehud sade: Jag hafver Guds ord till dig; då stod han upp af sinom stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Men Ehud räckte ut sina venstra hand, och tog svärdet af sitt högra lår, och stötte det in uti hans buk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Så att ock skaftet följde in med bladet, och fetman innelyckte skaftet; ty han drog intet svärdet ut af hans buk, och träcken gick af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Men Ehud gick ut genom bakdörrena, och lät igen dörrena efter sig, och slog henne i lås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Då han nu utkommen var, gingo hans tjenare in; och som de sågo, att dörren på sommarsalen igenlyckt var, sade de: Han är tilläfventyrs gången på stol i kammaren till sommarsalen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'När de nu så länge bidt hade, att de skämdes, ty ingen lät dem dörrena upp af salen, togo de nyckelen, och läste upp; si, då låg deras herre der död på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Och Ehud undflydde, medan de fördröjde, och gick fram om afgudarna, och undkom allt intill Seirath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Och då han kom derin, blåste han i basuner på Ephraims berg, och Israels barn drogo med honom af bergena, och han framför dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Och sade till dem: Följer mig efter, ty Herren hafver gifvit edra fiendar, de Moabiter, i edra händer; och de följde honom efter, och vunno Jordans färjostad, den som drager åt Moab, och läto ingen komma deröfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Och slogo de Moabiter af på den tiden vid tiotusend män, alltsammans ädla och stridsamma män, så att icke en undslapp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Alltså vordo de Moabiter på den tiden nederlagde, under Israels barnas hand; och landet var stilla i åttatio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Efter honom var Samgar, Anaths son; han slog sexhundrade Philisteer med en herdastaf, och frälste ock han Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Men Israels barn gjorde ytterligare illa för Herranom, då Ehud var död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Och Herren sålde dem uti Jabins, de Cananeers Konungs, händer, som satt i Hazor, och hans härhöfvitsman var Sisera, och han bodde i Haroseth Hedningarnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Och Israels barn ropade till Herran; ty han hade niohundrade jernvagnar, och tvingade Israels barn med våld i tjugu år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'På den samma tiden var domarinna i Israel, den Prophetissan Debora, Lappidoths hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Och hon bodde under Deboras palmträ, emellan Rama och BethEl, på Ephraims berg; och Israels barn kommo ditupp till henne för rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Hon sände åstad, och kallade Barak, AbiNoams son, af Kedes Naphthali, och lät säga honom: Hafver icke Herren Israels Gud budit dig: Gack åstad, och drag upp på berget Thabor, och tag tiotusend män med dig, utaf Naphthali och Sebulons barn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Ty jag vill föra till dig Sisera, Jabins härhöfvitsman, vid den bäcken Kison, med hans vagnar, och med all hans hop; och vill gifva honom i dina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Barak sade till henne: Om du far med mig, så drager jag åstad; men far du icke med, så drager icke heller jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Hon sade: Jag vill draga med dig; men segren blifver icke din i denna resone, som du gör; utan Herren skall gifva Sisera uti en qvinnos hand. Så gjorde Debora redo, och for med Barak till Kedes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Då kallade Balak Sebulon och Naphthali till Kedes, och drog till fot med tiotusend män; Debora följde ock med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Men Heber den Keniten var dragen ifrå de Keniter, ifrå Hobabs barn, Mose svågers, och hade uppslagit sin tjäll vid den eken Zaanaim invid Kedes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Då vardt Sisera bådadt, att Barak, AbiNoams son, var dragen upp på det berget Thabor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Så samkade han alla sina vagnar tillhopa, niohundrade jernvagnar; och allt det folk med honom var, ifrå Haroseth Hedningarnas, allt intill den bäcken Kison.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Men Debora sade till Barak: Upp, detta är den dagen, i hvilkom Herren hafver gifvit Sisera i dina hand; ty Herren skall draga ut för dig. Så drog Barak neder af berget Thabor, och de tiotusend män med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Och Herren förskräckte Sisera med alla hans vagnar, och all hans här, för Baraks svärdsegg, så att Sisera sprang ifrå sin vagn, och flydde till fot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Men Barak jagade efter vagnarna och hären, allt intill Haroseth Hedningarnas, och all Sisera här föll för svärdsegg, så att icke en blef öfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Men Sisera flydde till fot in uti Jaels tjäll, Hebers den Kenitens hustrus; förty Konung Jabin i Hazor, och Hebers den Kenitens hus stodo i frid med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Och Jael gick ut emot Sisera, och sade till honom: Kom, min herre, kom in till mig, och frukta dig intet; och han gaf sig in till henne uti hennes tjäll, och hon höljde öfver honom en mantel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Och han sade till henne: Kära, gif mig litet vatten till att dricka, ty mig törster. Då tog hon en bytto mjölk, och gaf honom dricka, och höljde på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Och han sade till henne: Gack fram i dörrena på tjället, och om någor kommer och frågar, om någor är här, så säg: Ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Så tog Jael, Hebers hustru, en nagla af tjället, och en hammar i sina hand, och gick sakta in till honom, och slog honom naglan genom tinningen, så att han sank neder till jordena; ty han var sömnig och vanmägtig, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Då Barak jagade efter Sisera, gick Jael ut emot honom, och sade till honom: Kom hit, jag vill visa dig den man, som du söker efter. Och då han kom in till henne, låg Sisera död, och naglen fast i hans tinning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Alltså nederlade Gud, på den tiden, Jabin, de Cananeers Konung för Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Och Israels barnas hand fullföljde, och vardt stark emot Jabin, de Cananeers Konung, tilldess de utrotade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Då söngo Deborah och Barak, AbiNoams son, på den samma tiden, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Lofver Herran, att Israel är åter fri vorden, och folket hafver varit der viljogt till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Hörer till, I Konungar, och akter uppå, I Förstar: jag vill, Herranom vill jag sjunga, Herranom Israels Gudi vill jag spela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Herre, då du utdrogst ifrå Seir, och gick fram ifrån Edoms mark, då skalf jorden, himmelen dröp, och skyarna dröpo vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Bergen smulto för Herranom, Sinai för Herranom Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'I Samgars, Anaths sons, tid, i Jaels tid, voro vägarna förgångne; och de som på stigarna gå skulle, de vandrade krokota vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Det fattades, bönder fattades i Israel, tilldess jag Debora uppkom, tilldess jag uppkom en moder i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Ett nytt hafver Gud utvalt, portarna hafver han bestridt; ingen sköld eller spets vardt sedd ibland fyratiotusend i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mitt hjerta faller till Israels regenter, hvilke friviljoge äro ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Lofver Herran, I som riden på sköna åsninnor, I som sitten för rätta; och sjunger, I som gån på vägomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Der skyttarna ropa ibland dem som vatten hemta, der säge man om Herrans rättfärdighet, om hans bönders rättfärdighet i Israel; då drog Herrans folk neder till portarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Upp, upp, Debora, upp, upp, och sjung ena viso; upp, Barak, och fånga dina fångare, du AbiNoams son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Då vordo de förlåtne rådande öfver de mägtiga; Herren vardt rådandes genom mig öfver de hjeltar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Utaf Ephraim var deras rot emot Amalek; och efter dig BenJamin i ditt folk. Af Machir äro komne regenter; och af Sebulon äro regerare vordne igenom skrifpennan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Isaschars Förstar voro med Debora, och Isaschar var såsom Barak i dalenom, utsänder med sitt fotfolk. Ruben höll mycket af sig, och skiljde sig ifrån oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Hvi blefst du i dinom fårahyddom, till att höra hjordarnas bräkande; och höll mycket af dig, och skiljde dig ifrån oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead blef hinsidon Jordan. Och hvi bor Dan ibland skeppen? Asser satt i hafsens hamn, och blef i sina förfallna byar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Men Sebulons folk vågade sina själ i döden; Naphthali desslikes på höjdene af markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Konungarna kommo och stridde. Då stridde de Cananeers Konungar i Thaanach, vid det vattnet Megiddo; men de hade ingen vinning deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Af himmelen var stridt emot dem; stjernorna i deras lopp stridde emot Sisera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Den bäcken Kison vältrade dem, den bäcken Kedumim, den bäcken Kison. Träd, min själ, på de starka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Då darrade hästarnas fötter, för deras starka åsittares förfärelses skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Förbanner den staden Meros, sade Herrans Ängel; förbanner hans borgare, att de icke kommo Herranom till hjelp; till hjelp Herranom, till de hjeltar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Välsignad vare ibland qvinnor Jael, Hebers den Kenitens hustru; välsignad vare hon i hyddomen ibland qvinnor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Mjölk gaf hon, då han vatten beddes, och bar smör in uti en härlig skål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Hon tog naglan med sin hand, och smedshammaren i sina högra hand, och slog Sisera genom hans hufvud; sönderkrossade, och genomstack hans tinningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Till hennes fötter krökte han sig, föll neder, och lade sig; han krökte sig, och föll neder till hennes fötter; såsom han krökte sig, så låg han förderfvad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Sisera moder såg genom fenstret ut, och gret igenom gallren: Hvi förtöfvar hans vagn så länge, att han icke kommer? Hvi fördröja hans vagns hjul?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'De visesta ibland hennes qvinnor svarade, då hon så jämmerliga qvidde:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Skulle de icke finna och byta rof, hvarjom manne en ung pigo eller två till byte; och Sisera brokot stickad kläder till byte, stickad brokot kläder om halsen till byte?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Alltså, Herre, förgånge alle dine fiender; men de som honom kär hafva, de vare såsom uppgångande solen i sine magt. Och landet hade frid i fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Och då Israels barn gjorde det ondt var för Herranom, gaf Herren dem under de Midianiters hand i sju år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Och då de Midianiters hand vardt för stark öfver Israel, gjorde Israels barn sig klyfter i bergen, och kulor, och fäste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Och när Israel något sådde, så kommo de Midianiter upp, och de Amalekiter, och de af österlanden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Och lägrade sig emot dem, och förderfvade växten på landet, allt intill Gasa, och läto ingen boskap blifva qvar i Israel, hvarken får, fä eller åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Förty de kommo ditupp med sinom boskap och tjäll, såsom ett stort tal gräshoppor, så att hvarken de eller deras cameler stodo till att räkna; och de föllo in i landet, på det de skulle förderfva det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Så vardt Israel mycket försvagad för de Midianiter. Då ropade Israels barn till Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Som de nu ropade till Herran, för de Midianiters skull,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Sände Herren till dem en Prophet; han sade till dem: Detta säger Herren Israels Gud: Jag hafver fört eder utur Egypten, och utu träldomens hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Och hafver frälst eder utu de Egyptiers hand, och utur alla deras hand, som eder tvingade, och hafver drifvit dem ut för eder, och gifvit eder deras land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Och sade till eder: Jag är Herren edar Gud; frukter intet de Amoreers gudar, i hvilkas land I bon. Och I lydden mine röst intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Och en Herrans Ängel kom, och satte sig under ena ek i Ophra, hvilken Joas tillhörde, de Esriters fader; och hans son Gideon tröskade hvete i pressen, på det han skulle fly för de Midianiter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Då syntes honom Herrans Ängel, och sade till honom: Herren vare med dig, du stridsamme hjelte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideon sade till honom: Min Herre, är Herren med oss, hvi vederfars oss då allt detta? Och hvar äro all hans under, som våre fäder hafva förtäljt oss, och sagt: Herren hafver fört oss utur Egypten? Herren hafver nu öfvergifvit oss, och gifvit oss i de Midianiters händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Då vände Herren sig till honom, och sade: Gack åstad i denna dine kraft; du skall fria Israel utu de Midianiters händer; si, jag hafver sändt dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Han sade till honom: Min Herre, hvarmed skall jag fria Israel? Si, min slägt är den minsta i Manasse, och jag är den svagaste i mins faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Herren sade till honom: Jag vill vara med dig, så att du skall slå de Midianiter, såsom en man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Men han sade till honom: Käre, hafver jag funnit nåd för dig, så gif mig ett tecken, att det är du, som talar med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Gack icke hädan, tilldess jag kommer till dig, och bär mitt spisoffer, och lägger det för dig. Han sade: Jag vill blifva, tilldess du kommer igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Och Gideon gick, och slagtade ett kid, och tog ett epha osyradt mjöl; och lade kött uti en korg, och lät sådet uti ena kruko, och bar ut till honom under ekena, och gick fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Men Guds Ängel sade till honom: Tag köttet, och det osyrada, och lägg det på hälleberget, som här är, och gjut sådet ut. Och han gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Då räckte Herrans Ängel käppen ut, som han hade i handene, och kom vid köttet och det osyrada mjölet med käppsändanom; och elden kom utu hällebergena, och förtärde köttet och det osyrada mjölet. Och Herrans Ängel försvann utu hans ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Då nu Gideon såg, att det var en Herrans Ängel, sade han: O! Herre, Herre, hafver jag nu sett en Herrans Ängel ansigte mot ansigte?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Men Herren sade till honom: Frid vare med dig; frukta dig intet, du skall icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Då byggde Gideon dersammastäds Herranom ett altare, och kallade det fridsens Herre. Det står der ännu på denna dag, i Ophra, de Esriters faders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Och i den samma nattene sade Herren till honom: Tag en stut ibland oxarna, som dinom fader tillhöra, och en annan stut som sju åra gammal är, och slå sönder Baals altare, som är dins faders, och hugg bort den lunden, som der när står.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Och bygg Herranom dinom Gud ett altare öfverst på desso hällebergena, och red det till; och tag den andra stuten, och offra ett bränneoffer, med veden af lundenom, som du borthuggit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Då tog Gideon tio män utaf sina tjenare, och gjorde såsom Herren honom sagt hade; men han fruktade sig göra det om dagen, för sins faders hus skull, och för folkens skull i stadenom; utan om nattena gjorde han det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Då nu folket i staden stodo upp bittida om morgonen, si, då var Baals altare sönderslaget, och lunden der när afhuggen; och den andre stuten för ett bränneoffer lagd på det altaret, som uppbygdt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Och den ene sade till den andra: Ho hafver detta gjort? Och då de sökte, och frågade derefter, vardt sagdt: Gideon, Joas son, hafver det gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Då talade folket i staden till Joas: Få oss hitut din son; han måste dö, derföre, att han hafver omkullslagit Baals altare, och afhuggit lunden der när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Men Joas sade till alla dem som när honom stodo: Viljen I lägga eder ut för Baal? Viljen I fria honom? Den som lägger sig ut för honom, han skall dö i denna morgon. Är han gud, så hämne sig sjelf, att hans altare omkullslaget är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Ifrå den dagen kallade man honom JerubBaal, och sade: Baal hämne sig sjelf, att hans altare omkullslaget är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Då församlade sig tillhopa de Midianiter och Amalekiter, och de österländningar, och drogo öfver, och lägrade sig i den dalen Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Så iklädde Herrans Ande Gideon, och han lät blåsa i basuner, och kallade AbiEser, att de skulle följa honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Och sände bådskap i hela Manasse, och kallade dem, att de skulle ock följa honom; han sände ock bådskap till Asser, och Sebulon, och Naphthali; de kommo upp emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Och Gideon sade till Gud: Vill du frälsa Israel igenom mina hand, såsom du sagt hafver,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Så vill jag lägga ett skinn med ullone ut på logan; om daggen lägger sig allenast på skinnet, och all marken är torr, så kan jag märka, att du vill frälsa Israel igenom mina hand, såsom du sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Och det skedde så. Och då han den andra morgonen bittida uppstod, tryckte han daggena utu skinnet, och uppfyllde ena skål med det vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Och Gideon sade till Gud: Din vrede förgrymme sig icke öfver mig, om jag än en tid talar; jag vill än en tid försökat med skinnet; vare nu allena torrt på skinnena, och daggen på allo markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Gud gjorde ock så i samma natt, att allena var torrt på skinnet, och dagg uppå allo markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Då stod JerubBaal, det är Gideon, bittida upp, och allt folket, som med honom var, och lägrade sig vid den brunnen Harod, så att han hade de Midianiters här norrut, bakföre det berget More i dalenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Och Herren sade till Gideon: Folket, som med dig är, är allt för mycket. Om jag gåfve Midian i deras händer, måtte Israels barn berömma sig emot mig, och säga: Min hand hafver frälst mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Så låt nu utropa för folkets öron, och säga: Den som rädder är och förfärad, han vände om, och skynde sig af berget Gilead. Då vände folket tillbaka, tu och tjugu tusend, så att icke utan tiotusend blefvo qvara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Och Herren sade till Gideon: Detta folket är ännu för mycket; haf dem neder till vattnet, der vill jag pröfva dig dem; och om hvilken jag säger dig, att han skall draga med dig, han skall draga med dig; och om hvilken jag säger, att han icke skall draga med dig, han skall icke draga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Och han hade folket neder till vattnet. Och Herren sade till Gideon: Hvilken som läppjar vattnet med sine tungo, såsom en hund läppjar, honom ställ afsides; desslikes dem som på sin knä nederfalla till att dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Då var deras tal, som med munnen läppjat hade utu handene, trehundrade män; allt det andra folket hade fallit på knä och druckit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Och Herren sade till Gideon: Med de trehundrade män, som läppjat hafva, vill jag frälsa eder, och gifva de Midianiter i dina händer; men det andra folket låt alltsammans gå hem till sitt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Och de togo spisning för folket med sig, och sina basuner; men de andra Israeliter lät han alla gå hvar och en i sina hyddo; men han stärkte sig med de trehundrade män; och de Midianiters här låg nedanför honom i dalenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Och Herren sade till honom i samma natt: Statt upp, och gack neder till lägret; ty jag hafver gifvit dem i dina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Om du fruktar dig att gå ditneder, så låt din dräng Pura gå ned med dig till lägret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Att du må få höra hvad de tala; sedan skall du med magt draga neder till lägret. Så gick Gideon med sin dräng Pura neder till det rummet på lägret, der vakten var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Men de Midianiter och de Amalekiter, och alle österländningarna, hade lägrat sig i dalenom, såsom en hop gräshoppor; och deras cameler stodo icke till att räkna, så månge voro de, såsom sanden på hafsens strand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Då nu Gideon kom, si, då förtäljde en för dem andra en dröm, och sade: Mig tyckte, att ett bjuggbröd, på glöd bakadt, välte sig intill de Midianiters lägre, och då det kom till tjället, slog det det, och kastade det neder, och vände upp ned uppå thy, så att tjället låg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Då svarade den andre: Det är icke annat än Gideons svärd, Joas sons, den Israelitens; Gud hafver gifvit de Midianiter i hans händer med hela hären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Då Gideon nu hörde förtäljas sådana dröm, och hans utläggning, tillbad han, och kom igen i Israels här, och sade: Upp, ty Herren hafver gifvit de Midianiters här uti edra händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Och han skifte de trehundrade män i tre delar, och fick hvarjom och enom en basun i sina hand, och tomma krukor, och lampor deruti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Och sade till dem: Ser på mig, och görer ock så; si, när jag kommer intill hären, såsom jag gör, så görer ock med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Såsom jag blås i basunen, och alle de som med mig äro, så skolen ock I blåsa i basunen omkring hela hären, och säga: Herren och Gideon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Så kom Gideon, och hundrade män med honom, till det yttersta på hären, till första väktarena, som der skickade voro och väckte dem upp, och blåste med basunerna, och slogo sönder krukorna i sina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Och så blåste då alle tre hoparna med basunerna, och slogo sönder krukorna; men lamporna höllo de i deras venstra hand, och basunen i deras högra hand, och blåste och ropade: Herrans och Gideons svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Och hvar och en stod på sitt rum, omkring hären. Då begynte hela hären att löpa, ropa och fly.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Och som de trehundrade män blåste i basunerna, gjorde Herren så, att hvars och ens svärd i hela härenom var emot den andra; och hären flydde allt intill BethSittaZereratha, allt intill gränsona åt den slättene Mehola vid Tabbath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Och de Israels män af Naphthali, af Asser, och af hela Manasse, skriade, och jagade efter de Midianiter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Och Gideon sände bådskap på hela berget Ephraim, och lät säga dem: Kommer neder emot de Midianiter, och kommer förr än de till vattnet, intill BethBara och Jordan. Så ropade alle de som af Ephraim voro, och kommo förr än de till vattnet, intill BethBara och Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Och de fingo fatt på två de Midianiters Förstar, Oreb och Seeb; och dråpo Oreb på det hälleberget Oreb, och Seeb i Seebs press; och jagade de Midianiter; och båro Orebs och Seebs hufvud till Gideon öfver Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Och de män af Ephraim sade till honom: Hvi gjorde du oss detta, att du icke kallade oss, då du drog till strids emot de Midianiter? Och kifvade svårliga på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Men han sade till dem: Hvad hafver jag nu gjort, det edro gerning liknas kan? Är icke en vinqvist Ephraims bättre, än hela AbiEsers vinbergning?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Gud hafver gifvit i edra händer de Midianiters Förstar Oreb och Seeb. Huru skulle jag kunnat det gjort, som I gjort hafven? Då han detta sade, stillades deras vrede emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Då nu Gideon kom till Jordan, gick han deröfver med trehundrade män, som med honom voro; och de voro trötte, och jagade efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Och han sade till det folket i Succoth: Käre, gif detta folket, som under mig är, något bröd, förty de äro trötte; att jag måtte jaga efter de Midianiters Konungar, Sebah och Zalmunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Men de öfverste i Succoth sade: Äro Sebahs och Zalmunna händer allaredo i dina händer, att vi ju skole gifva dinom här bröd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideon sade: Nu väl, när Herren gifver Sebah och Zalmunna i mina hand, skall jag söndertröska edart kött med törne utur öknene, och med tistlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Och han drog dädan upp till Pnuel, och talade sammalunda till dem. Och det folket i Pnuel svarade honom lika som de i Succoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Och han sade ock till det folket i Pnuel: Kommer jag igen i frid, så skall jag bryta detta tornet neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Men Sebah och Zalmunna voro i Karkor, och deras här när dem, vid femtontusend, hvilke alle voro undsluppne af hela de österländningars här; ty tjugu och hundrade tusend voro fallne, som svärd utdraga kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Och Gideon drog uppåt på den vägen, der man i tjäll bor, österut in mot Nobah och Jogbeha, och slog hären; ty hären var trygg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Och Sebah och Zalmunna flydde; men han jagade efter dem, och grep de två Midianiters Konungar, Sebah och Zalmunna, och förskräckte hela hären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Då nu Gideon, Joas son, kom igen af stridene, förr än solen uppgången var,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Fick han fatt på en dräng utaf det folket i Succoth, och frågade honom; han skref honom upp de öfversta i Succoth, och deras äldsta, sju och sjutio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Och han kom till det folket i Succoth, och sade: Si, här äro Sebah och Zalmunna, om hvilka I bespottaden mig, och saden: Är då allaredo Sebahs och Zalmunna hand uti dina händer, att vi ju skole gifva dino folke, som trött är, bröd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Och han tog de äldsta af staden, och törne utaf öknene och tistlar, och lät dermed sönderslita det folket i Succoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Och tornet i Pnuel bröt han neder, och slog ihjäl folket i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Och till Sebah och Zalmunna sade han: Hurudana voro de män, som I slogen ihjäl i Thabor? De sade: De voro sådana som du, och dägelige såsom ens Konungs barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Han sade: De voro mine bröder, mine moders söner; så sant som Herren lefver, om I haden låtit dem lefva, skulle jag icke aflifva eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Och sade till sin förstfödda son Jether: Statt upp, och dräp dem. Men drängen drog sitt svärd icke ut; ty han fruktade sig, efter han var ännu en ung dräng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Då sade Sebah och Zalmunna: Statt du upp, och slå oss; ty efter som mannen är, så är ock hans magt. Så stod Gideon upp, och slog ihjäl Sebah och Zalmunna, och tog de spänger, som voro på deras camelers halsar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Då sade till Gideon någre af Israel: Var herre öfver oss, du och din son, och dins sons son, efter du hafver frälst oss ifrå de Midianiters hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Men Gideon sade till dem: Jag vill ingen herre vara öfver eder, och min son skall icke heller vara herre öfver eder; utan Herren skall vara herre öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Och Gideon sade till dem: Ett begärar jag af eder, hvar och en gifve mig de örnaringar, som han röfvat hafver; förty, efter de voro Ismaeliter, hade de gyldene örnaringar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'De sade: Dem vilje vi gifva; och bredde ett kläde ut, och hvar och en kastade örnaringarna deruppå, som han röfvat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Och de gyldene örnaringarna, som han hade begärat, gjorde till vigt tusende sjuhundrade siklar guld; förutan de spänger, kedjor och skarlakanskläder, som de Midianiters Konungar plägade bära, och förutan deras camelers halsband.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Och Gideon gjorde der en lifkjortel af, och satte honom i sin stad Ophra; och hela Israel bedref der hor uppå; och det vardt Gideon och hans huse till förargelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Alltså vordo de Midianiter förnedrade för Israels barn, och hofvo sitt hufvud icke mer upp; och landet var stilla i fyratio år, så länge Gideon lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Och JerubBaal, Joas son, gick bort, och bodde i sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Och Gideon hade sjutio söner, som utaf hans länder komne voro; ty han hade många hustrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Och hans frilla, den han hade i Sichem, födde honom ock en son; hans namn kallade han AbiMelech.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Och Gideon, Joas son, blef död i godom ålder, och vardt begrafven i sins faders Joas graf, i Ophra, de Esriters faders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Då Gideon var död, vände Israels barn om, och bedrefvo hor efter Baalim, och gjorde BaalBerith sig till en gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Och Israels barn kommo intet Herran deras Gud ihåg, den dem frälsat hade ifrån allas deras fiendars hand allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Och de gjorde ingen barmhertighet med JerubBaals Gideons huse, efter allt det goda, som han emot Israel gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Men AbiMelech, JerubBaals son, gick bort till Sichem till sina moders bröder, och talade med dem, och med hela slägtene af hans moderfaders hus, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Käre, taler för alla mäns öron i Sichem: Hvilket är eder bättre, att sjutio män, alle JerubBaals barn, blifva herrar öfver eder, eller en man blifver herre öfver eder? Kommer ock dertillmed ihåg, att jag är edart ben och kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Då talade hans moders bröder all dessa orden om honom, för alla mäns öron i Sichem; och deras hjerta bevektes efter AbiMelech; ty de tänkte: Han är vår broder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Och gåfvo honom sjutio silfpenningar utur BaalBeriths huse; och AbiMelech lejde sig dermed lösaktiga och lättfärdiga män, som honom följde efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Och han kom i sins faders hus i Ophra, och slog sina bröder, JerubBaals söner, sjutio män, ihjäl på enom sten; men Jotham, den yngste sonen JerubBaals, blef igen; ty han vardt undstungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Och sig församlade alle män af Sichem, och hela Millo hus; och gingo till, och gjorde AbiMelech till Konung vid den höga ekena, som stod i Sichem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Då detta var sagdt Jotham, gick han bort, och stod öfverst på Grisims berg, och hof sin röst upp, ropade, och sade till dem: Hörer mig, I män af Sichem, att Gud ock hörer eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Trän gingo till och skulle smörja öfver sig en Konung, och sade till oljoträt: Var vår Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Men oljoträt svarade dem: Skulle jag öfvergifva min fetma, hvilken både Gud och menniskor prisa i mig, och gå bort, och uppsättas öfver trän?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Då sade trän till fikonträt: Kom du, och var Konung öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Men fikonträt sade till dem: Skulle jag öfvergifva min sötma och mina goda frukt, och gå bort, och uppsättas öfver trän?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Då sade trän till vinträt: Kom du, och var vår Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Men vinträt sade till dem: Skulle jag öfvergifva min must, den Gud och menniskor glada gör, och gå bort, och uppsättas öfver trän?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Då sade all trän till törnebuskan: Kom du, och var Konung öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Och törnebusken sade till trän: Är det sant, att I viljen smörja mig till Konung öfver eder, så kommer, och betror eder under min skugga; hvar I icke viljen, så gånge en eld utu törnebuskan, och förtäre cedreträn i Libanon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Hafven I nu gjort rätt och redeliga, att I hafven gjort AbiMelech till Konung; och hafven I gjort väl emot JerubBaal och hans hus; och hafven så gjort emot honom som han förtjent hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Att min fader för edra skull stridde, och vågade sin själ, derföre att han skulle frälsa eder ifrå de Midianiters hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Och hafven uppsatt eder i denna dag emot mins faders hus, och slagit hans söner ihjäl, sjutio män på en sten, och gjort eder till Konung AbiMelech, hans tjensteqvinnos son, öfver de män i Sichem, efter han edar broder är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Hafven I nu gjort rätt och redeliga emot JerubBaal och hans hus på denna dag, så varer glade öfver AbiMelech, och han vare glad öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Hvar ock icke, så gånge en eld utaf AbiMelech, och förtäre de män af Sichem, och af Millo hus; och gånge desslikes ut en eld af de män i Sichem, och af Millo hus, och förtäre AbiMelech.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Och Jotham flydde, och undvek, och gick till Ber, och bodde der, för hans broders AbiMelechs skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Då nu AbiMelech hade rådit öfver Israel i tre år,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Sände Gud en ondan vilja emellan AbiMelech och de män af Sichem; förty de män af Sichem förtalade AbiMelech,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Och kastade honom före den ogerning, som han bedref på de sjutio JerubBaals söner, och lade deras blod på AbiMelech deras broder, den dem ihjälslog; och på de män i Sichem, som honom hans hand dertill styrkt hade, att han sina bröder drap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Och de män i Sichem beställde ett bakhåll öfverst på bergen, och röfvade på vägenom alla de som foro der fram; och det vardt bådadt AbiMelech.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Så kom Gaal, Ebeds son, och hans bröder, och gingo in i Sichem; och de män i Sichem förläto sig uppå honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Och drogo ut på markena, och bergde sina vingårdar, och trampade der, och gjorde en dans, och gingo uti deras guds hus, och åto och drucko, och bannade AbiMelech.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Och Gaal, Ebeds son, sade: Hvad är AbiMelech? Och hvad är Sichem, att vi honom tjena skole? Är icke han JerubBaals son, och hafver satt sin tjenare Sebul hit öfver Hemors folk, Sichems faders? Hvi skulle vi tjena honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Gud gifve, att detta folket vore under mine hand, att jag måtte förjaga AbiMelech. Och det vardt sagdt AbiMelech: Föröka din här, och drag ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Förty Sebul, öfversten i stadenom, då han hörde Gaals, Ebeds sons ord, vardt han illa vred;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Och sände bådskap till AbiMelech hemliga, och lät säga honom: Si, Gaal, Ebeds son, och hans bröder, äro komne till Sichem, och göra dig staden genstörtigan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Så statt nu upp om natten, du och ditt folk, som när dig är, och var i bakhåll för dem i markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Och i morgonstundene, när solen uppgår, så var bittida uppe, och fall till staden; och när han och det folk, som med honom är, draga ut till dig, så gör med dem såsom din hand finna kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'AbiMelech stod upp om nattena, och allt folket, som med honom var, och satte bakhåll inför Sichem med fyra skarar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Och Gaal, Ebeds son, drog ut för stadsporten; men AbiMelech reste upp utaf bakhållet, med det folk som med honom var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Då nu Gaal såg folket, sade han till Sebul: Si, der kommer en hop folk neder af bergshöjdene. Sebul sade: Du ser skuggan af bergen, likasom det vore menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal talade än en tid, och sade: Si, der kommer en hop folk neder midt utaf landet; och en här kommer på den vägen till trollareekena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Då sade Sebul till honom: Hvar är nu din mun, som sade: Ho är AbiMelech, att vi honom tjena skole? Är icke nu detta det folk, som du föraktat hafver? Drag nu ut, och strid med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Gaal drog ut med Sichems folk, och stridde med AbiMelech.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Men AbiMelech jagade honom, så att han flydde för honom; och månge föllo slagne allt intill stadsporten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Och AbiMelech blef i Aruma; men Sebul dref Gaal och hans bröder ut, så att de icke måtte blifva i Sichem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Om morgonen gick folket ut på markena; och det vardt sagdt AbiMelech.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Och han tog folket, och skifte det i tre delar, och beställde håll på dem i markene. Som han nu såg, att folket gick utu stadenom, föll han till dem, och slog dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Men AbiMelech med den hopen, som med honom var, föllo till, och trädde intill stadsporten; de andre två hoparna föllo till alla dem som på markene voro, och slogo dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Då stridde AbiMelech emot staden den hela dagen, och vann honom; och drap det folk, som derinne var, och slog staden neder, och sådde salt deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'När de män, som i Sichems torn bodde, detta hörde, gingo de in uti ett fäste i den gudens Beriths hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Då AbiMelech det hörde, att alle de män af Sichems torn voro församlade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Gick han på det berget Zalmon med allt sitt folk, som med honom var; och tog ena yxa i sin hand, och högg en gren af ett trä, och lade på sin axel, och sade till allt folket, som med honom var: Hvad I sågen att jag gjorde, det görer ock I med hast såsom jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Då högg allt folket hvar i sin stad en gren af, och följde AbiMelech efter, och kastade dem intill fästet, och tände der eld uppå; så att alle de män af Sichems torn blefvo döde, vid tusend män och qvinnor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Och AbiMelech drog till Thebez, och belade det, och vann det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Men der var ett starkt torn midt i stadenom, på hvilket flydde alle, både män och qvinnor, och alle stadsens inbyggare, och läste igen efter sig, och stego upp på taket af tornet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Då kom AbiMelech intill tornet, och stridde deremot, och kom sig intill porten af tornet, på det han skulle tända der eld uppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Men en qvinna kastade ett stycke af en qvarnsten ned på AbiMelechs hufvud, och slog honom hufvudskålena sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Då kallade AbiMelech drängen, som hans värja drog, hasteliga, och sade till honom: Drag ut ditt svärd, och dräp mig, att man icke skall säga: En qvinna slog honom ihjäl. Så stack hans dräng honom igenom, och han blef död,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Då nu de Israeliter, som med honom voro, sågo att AbiMelech var död, gick hvar och en hem till sin ort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Alltså betalade Gud AbiMelech det onda, som han emot sin fader gjort hade, då han drap sina sjutio bröder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Desslikes allt det onda, som de män af Sichem gjorde, betalade dem Gud på deras hufvud; och öfver dem kom Jothams förbannelse, JerubBaals sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Efter AbiMelech kom upp en annan frälsare i Israel, Thola, en man af Isaschar, Puahs son, Dodo sons; och han bodde i Samir på Ephraims berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Och han dömde Israel i tre och tjugu år, och blef död, och vardt begrafven i Samir.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Efter honom kom upp Jair, en Gileadit, och han dömde Israel i tu och tjugu år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Och han hade tretio söner, ridande på tretio åsnafålar, och hade tretio städer, de kallades HavothJair allt intill denna dag, och ligga i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Och Jair blef död, och vardt begrafven i Kamon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Men Israels barn gjorde åter det ondt var för Herranom; och tjente Baalim och Astaroth, och de gudar i Syria, och de gudar i Zidon, och Moabs gudar, och Ammons barnas gudar, och de Philisteers gudar, och öfvergåfvo Herran, och tjente honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Då förgrymmade sig Herrans vrede öfver Israel, och sålde dem under de Philisteers och Ammons barnas hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Och de tvingade och förtryckte Israels barn, ifrå det året, i aderton år; alla Israels barn på hinsidon Jordan, uti de Amoreers lande, som i Gilead ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Dertill drogo Ammons barn öfver Jordan, och stridde emot Juda, BenJamin, och emot Ephraims hus, så att Israel vardt ganska svårliga förtryckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Då ropade Israels barn till Herran, och sade: Vi hafve syndat emot dig; ty vi hafve öfvergifvit vår Gud, och tjent Baalim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Men Herren sade till Israels barn: Betvingade ock icke eder de Egyptier, de Amoreer, Ammons barn, de Philisteer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'De Zidonier, de Amalekiter och Maoniter? Och jag halp eder utu deras händer, då I ropaden till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Så hafven I dock likaväl öfvergifvit mig, och tjent andra gudar; derföre vill jag intet mer hjelpa eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Går och åkaller de gudar, som I utvalt hafven; låter dem hjelpa eder uti edor bedröfvelses tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Men Israels barn sade till Herran: Vi hafve syndat; gör du med oss hvad dig täckes, allenast hjelp oss i denna tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Och de kastade ifrå sig de främmande gudar, och tjente Herranom; och honom ömkade deröfver, att Israel så tvingad vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Och Ammons barn slogo sig ihop, och lägrade sig i Gilead; men Israels barn församlade sig, och lägrade sig i Mizpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Och folket, de öfverste i Gilead, sade emellan sig: Hvilken som först begynner till att strida emot Ammons barn, han skall vara höfvitsman öfver alla de som bo i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jephthah, en Gileadit, var en stridsam hjelte, dock likväl enes skökos son; och Gilead hade födt Jephthah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Men då Gileads hustru födde honom barn, och de samma barn vordo stor, drefvo de Jephthah ut, och sade till honom: Du skall intet arf taga i vårs faders huse; ty du äst ens annors qvinnos son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Då flydde han för sina bröder, och bodde i det landet Tob; och till honom församlade sig lösaktige män, och drogo ut med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Och någon tid derefter stridde Ammons barn med Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Då nu Ammons barn så stridde med Israel, gingo de äldste af Gilead bort, till att hemta Jephthah utu Tobs lande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Och sade till honom: Kom, och var vår höfvitsman, att vi måge strida emot Ammons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Men Jephthah sade till de äldsta af Gilead: Ären icke I de som mig haten, och hafven drifvit mig utu mins faders hus, och nu kommen I till mig, medan I ären i bedröfvelse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'De äldste i Gilead sade till Jephthah: Derföre komme vi nu igen till dig, att du skall gå med oss, och hjelpa oss strida emot Ammons barn; och vara vår höfvitsman öfver alla de som bo i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jephthah sade till de äldsta i Gilead: Om I hemten mig igen till att strida emot Ammons barn, och Herren gifver dem för mig, skall jag då vara edar höfvitsman?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'De äldste af Gilead sade till Jephthah: Herren vare tillhörare emellan oss, om vi icke göre som du sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Alltså gick då Jephthah med de äldsta af Gilead, och folket satte honom för höfvitsman och öfversta öfver sig; och Jephthah talade allt detta inför Herranom i Mizpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Då sände Jephthah bådskap till Konungen öfver Ammons barn, och lät säga honom: Hvad hafver du med mig att skaffa, att du kommer emot mig, till att strida emot mitt land?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Konungen öfver Ammons barn svarade Jephthas bådskap: Derföre, att Israel hafver tagit bort mitt land, då de drogo utur Egypten, allt ifrån Arnon intill Jabbok, och allt intill Jordan; så få mig nu det igen med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jephthah sände åter bådskap till Ammons barnas Konung;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Och lät säga honom: Så säger Jephthah: Israel hafver intet land borttagit, antingen ifrå de Moabiter, eller ifrån Ammons barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Förty när de drogo utur Egypten, vandrade Israel genom öknena allt intill röda hafvet, och kom till Kades;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Och sände bådskap till de Edomeers Konung, och sade: Låt mig draga igenom ditt land; men de Edomeers Konung tillstadde dem intet. Och sände han båd till Konungen öfver de Moabiter; han ville icke heller tillstädjat. Så blef Israel i Kades;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Och vandrade i öknene, och drog omkring de Edomeers och Moabiters land, och kom östan på de Moabiters land, och lägrade sig på hinsidon Arnon; och kom intet in uti de Moabiters landsändar; ty Arnon är de Moabiters landamäre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Och Israel sände båd till Sihon, de Amoreers Konung, i Hesbon, och sade: Låt oss draga igenom ditt land in till mitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Men Sihon betrodde icke Israel, att han skulle draga igenom hans landsändar; utan församlade allt sitt folk, och lägrade sig i Jahza, och stridde med Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Men Herren Israels Gud gaf Sihon, med allt hans folk, i Israels händer, så att de slogo dem; alltså tog Israel in allt de Amoreers land, som då i samma land bodde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Och togo alla de Amoreers landsändar in, ifrån Arnon allt intill Jabbok, och ifrån öknene intill Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Så hafver nu Herren Israels Gud fördrifvit de Amoreer för sino folke Israel; och du vill nu taga dem in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Hafver din gud Chemos några fördrifvit, dem må du intaga, och låta oss intaga alla dem som Herren vår Gud för oss fördrifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Menar du, att du bättre rätt hafver, än Balak, Zipors son, de Moabiters Konung? Trätte icke han och stridde emot Israel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Så ändock Israel nu i trehundrad år bott hafver i Hesbon och dess döttrar, i Aroer och dess döttrar, och i alla städer, som ligga vid Arnon; hvi friaden I det icke på den tiden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Jag hafver intet brutit emot dig, och du gör så illa emot mig, att du strider emot mig. Herren döme i dag emellan Israel och Ammons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Men Ammons barnas Konung skötte intet efter de Jephthahs ord, som han böd honom till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Då kom Herrans Ande öfver Jephthah, och han drog igenom Gilead och Manasse, och igenom Mizpe, som i Gilead ligger, och ifrå Mizpe, som i Gilead ligger, inpå Ammons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Och Jephthah lofvade Herranom ett löfte, och sade: Gifver du Ammons barn i mina hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Hvad som helst utu mins hus dörr kommer emot mig, när jag med frid igenkommer ifrån Ammons barn, det skall höra Herranom till; och jag skall offra det till bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Så drog Jephthah in på Ammons barn till att strida på dem; och Herren gaf dem i hans händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Och han slog dem, allt ifrån Aroer intilldess man kommer till Minnith, tjugu städer, och intill vingårdaplatsen, en mägtig stor slagtning. Och vordo så Ammons barn nedtryckte för Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Då nu Jephthah kom till Mizpa till sitt hus, si, då gick hans dotter ut emot honom, med pipande och dansande, och hon var enda barn, och han hade eljest ingen son eller dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Och som han fick se henne, ref han sin kläder, och sade: Aj! min dotter, du gör mig en hjertans sorg, och bedröfvar mig; ty jag hafver öppnat min mun inför Herranom, och kan icke kalla det tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Men hon sade: Min fader, hafver du öppnat din mun inför Herranom, så gör med mig såsom utaf din mun gånget är, efter Herren hafver hämnats på dina fiendar. Ammons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Och hon sade till sin fader: Allenast beder jag dig om ett, att du unner mig två månader, att jag går neder på bergen, och begråter min jungfrudom med mina leksystrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Han sade: Gack; och lät henne gå i två månader. Så gick hon bort med sina leksystrar, och begret sin jungfrudom på bergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Och efter två månader kom hon igen till sin fader, och han gjorde henne såsom han lofvat hade; och hon hade intet skaffa haft med någrom man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Och en sedvänja kom upp i Israel, att Israels döttrar gingo årliga till, och begreto Jephthahs den Gileaditens dotter, fyra dagar om året.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Och de af Ephraim skriade, och gingo norrut, och sade till Jephthah: Hvi drogst du i strid emot Ammons barn, och kallade icke oss, att vi hade mått dragit med dig? Vi vilje uppbränna ditt hus med dig i elde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jephthah sade till dem: Jag och mitt folk hade en stor sak med Ammons barn; och jag kallade på eder, men I hulpen mig intet utu deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Då jag nu såg, att ingen frälsare på färde var, satte jag mina själ i mina hand, och drog åstad emot Ammons barn, och Herren gaf dem i mina hand. Hvi kommen I nu hitupp till mig, till att strida emot mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Och Jephthah församlade alla män i Gilead, och stridde emot Ephraim; och de män i Gilead slogo Ephraim, derföre, att de sade: Ären I dock, I Gileaditer, ibland Ephraim och Manasse, såsom de der af Ephraim beskyddas måste?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Och de Gileaditer togo in Jordans färjostad för Ephraim. När de nu sade: Vi äre ock de beskyddade af Ephraim, låt mig fara öfver; så sade de män af Gilead till honom: Äst du en Ephrait? När han nu svarade nej,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Så bådo de honom säga Schibboleth; så sade han Sibboleth, och kunde icke rätt säga det ut. Så togo de honom fatt, och dråpo honom vid färjostaden åt Jordan; så att på den tiden föllo af Ephraim tu och fyratio tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Och Jephthah dömde Israel i sex år. Och Jephthah den Gileaditen blef död, och vardt begrafven i de städer i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Efter dessom dömde Ibzan af BethLehem Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Han hade tretio söner, och tretio döttrar gifte han ut, och tretio döttrar tog han utanefter till sina söner; och dömde Israel i sju år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Och blef död, och blef begrafven i BethLehem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Efter dessom dömde Israel Elon, en Sebulonit, och dömde Israel i tio år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Och blef död, och vardt begrafven i Ajalon, uti Sebulons land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Efter dessom dömde Israel Abdon, Hillels son, en Pirgathonit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Han hade fyratio söner, och tretio sonasöner, som på sjutio åsnafålar redo. Han dömde Israel i åtta år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Och blef död, och vardt begrafven i Pirgathon uti Ephraims lande, på de Amalekiters berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Och Israels barn gjorde åter det ondt var för Herranom; och Herren gaf dem uti de Philisteers händer i fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Men en man var i Zorga utaf Dans slägte, benämnd Manoah, och hans hustru var ofruktsam, och födde intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Och Herrans Ängel syntes hustrune, och sade till henne: Si, du äst ofruktsam, och föder intet; men du skall varda hafvandes, och föda en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Så vakta dig nu, att du icke dricker vin, eller starka drycker, och att du intet orent äter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Ty du skall varda hafvandes, och föda en son, hvilkom ingen rakoknif skall komma på hufvudet; förty den pilten skall vara en Guds Nazir utaf moderlifvet; och han skall begynna till att frälsa Israel utu de Philisteers hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Då kom qvinnan, och talade med sin man och sade: En Guds man kom till mig, och han var till seendes såsom en Guds Ängel, ganska förskräcklig; så att jag intet frågade honom hvadan han var, eller hvart han ville; och han sade mig intet hur han het.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Men han sade till mig; Si, du skall varda hafvandes, och föda en son; så drick nu intet vin, eller starka drycker, och ät intet orent; förty pilten skall vara en Guds Nazir, ifrå moderlifvet allt intill hans död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Då bad Manoah Herran, och sade: Ack! Herre, låt den Guds mannen åter komma till oss, den du utsändt hafver, att han må lära oss, hvad vi skole göra med piltenom, som födas skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Och Gud hörde Manoahs röst; och Guds Ängel kom igen till qvinnona; och hon satt på markene, och hennes man Manoah var icke när henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Då lopp hon hasteliga, och underviste det sinom man, och sade till honom: Si, den mannen hafver synts mig, som i dag kom till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Manoah stod upp, och följde qvinnona efter, och kom till mannen, och sade till honom: Äst du den mannen, som talade med qvinnone? Han sade: Ja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Och Manoah sade: När nu sker såsom du sagt hafver, hurudana skola piltens seder och gerning vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Herrans Ängel sade till Manoah: Han skall vakta sig för allt det som jag qvinnone sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Han skall icke äta hvad utaf vinträ kommet är, och skall intet vin dricka, eller starka drycker, och äta intet orent; allt det jag henne budit hafver, skall han hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Manoah sade till Herrans Ängel: Käre, låt oss behålla dig här, vi vilje tillreda dig ett kid af getterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Men Herrans Ängel svarade Manoah: Om du än behåller mig, så äter jag dock intet utaf ditt bröd; men vill du göra Herranom ett bränneoffer, så må du det offra; ty Manoah visste icke, att det var en Herrans Ängel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Och Manoah sade till Herrans Ängel: Huru heter du, att vi dig prisa måge, när du kommer såsom du sagt hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Herrans Ängel sade till honom: Hvi frågar du efter mitt Namn, det dock underligit är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Då tog Manoah ett kid af getterna och spisoffer, och lade det på en sten Herranom; och han gjorde det underliga; och Manoah med hans hustru sågo deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Och då lågen uppgick af altaret åt himmelen, för Herrans Ängel ock upp i altarens låga. Då Manoah och hans hustru det sågo, föllo de neder till jordena på sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Och Herrans Ängel syntes intet mer Manoah och hans hustru. Så förnam Manoah, att det var en Herrans Ängel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Och sade till sina hustru: Vi måste döden dö, att vi hafve sett Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Men hans hustru svarade honom: Om Herren hade velat dräpa oss, så hade han icke anammat bränneoffret och spisoffret af våra händer, och hade icke tett oss allt detta, ej heller låtit oss detta höra, såsom nu skedt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Och qvinnan födde en son, och kallade honom Simson; och pilten växte, och Herren välsignade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Och Herrans Ande begynte till att vara med honom, uti Dans lägre, emellan Zorga och Esthaol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Simson gick ned till Thimnath, och såg ena qvinno i Thimnath, utaf de Philisteers döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Och då han uppkom, underviste han det sinom fader och sine moder, och sade: Jag hafver sett ena qvinno i Thimnath, utaf de Philisteers döttrar; käre, gifver mig henne till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Hans fader och moder sade till honom: Är nu ingen qvinna ibland dina bröders döttrar, och i allt mitt folk, att du går bort, och tager dig hustru när de Philisteer, som oomskorne äro? Simson sade till sin fader: Gif mig denna; ty hon behagar min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Men hans fader och moder visste icke, att det var af Herranom; ty han sökte tillfälle emot de Philisteer; och de Philisteer rådde på den tiden öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Så gick Simson neder med sinom fader och sine moder till Thimnath; och som de kommo till vingårdarna vid Thimnath, si, då kom ett ungt lejon rytandes emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Och Herrans Ande föll öfver honom, och han ref det sönder i stycker, såsom man hade sönderrifvit ett kid, och hade dock platt intet i handene; och sade icke sinom fader eller sine moder, hvad han gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Då han nu kom ditneder, talade han med qvinnone, och hon behagade Simson i hans ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Och några dagar derefter kom han igen till att taga henne, och gick af vägenom till att bese aset af lejonet; si, då var en bisvärm i aset af lejonet, och hannog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Och han tog det i sina hand, och åt deraf i vägenom, och gick till sin fader och till sina moder, och gaf dem, så att de ock åto; men han sade dem intet deraf, att han hade tagit hannogen utaf lejonets as.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Och då hans fader kom ditneder till qvinnona, gjorde Simson der bröllop, såsom unga män pläga göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Och då de sågo honom, fingo de honom tretio stallbröder, som skulle vara när honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Men Simson sade till dem: Jag vill sätta eder ena gåto före; om I det utgäten, och råken rätt i dessa sju bröllopsdagar, så vill jag gifva eder tretio skjortor, och tretio högtidskläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Men kunnen I icke utråda henne, så skolen I gifva mig tretio skjortor och tretio högtidskläder. Och de sade till honom: Sätt fram dina gåto, låt oss höra henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Han sade till dem: Af fråssarenom utgick mat, och sötme utaf dem starka. Och de kunde i tre dagar icke råka uppå gåtona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'På sjunde dagen talade de till Simsons hustru: Locka för dinom man, att han utsäger oss gåtona, eller vi skole bränna dig och dins faders hus upp i eld; hafven I budit oss hit, till att göra oss fattiga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Då gret Simsons hustru för honom, och sade: Du äst mig vred, och hafver mig icke kär; du hafver gifvit mins folks barnom ena gåto före, och hafver icke utsagt mig henne. Han sade till henne: Si, jag hafver icke utsagt henne minom fader, eller mine moder; skulle jag nu sägat för dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Och hon gret i de sju dagar för honom, medan bröllopet stod. På sjunde dagen sade han henne det, ty hon låg honom så hårdt uppå; och hon sade gåtona för sins folks barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Då sade de män af stadenom till honom på sjunde dagen, förra än solen gick neder: Hvad är sötare än hannogen; hvad är starkare än lejonet? Han sade till dem: Om I icke haden plöjt med minom kalf, I haden icke råkat på mina gåto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Och Herrans Ande föll på honom, och han gick neder till Askelon, och slog tretio män af dem, och tog deras kläder, och gaf högtidskläder dem som gåtona på råkat hade; och vardt ganska vred, och gick upp i sin faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Men Simsons hustru vardt gifven enom hans stallbroder, den honom tillydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Och det begaf sig efter några dagar, om hveteandene, att Simson sökte sina hustru med ett kid af getterna; och som han tänkte: Jag vill gå till mina hustru i kammaren, ville hennes fader icke låta honom in;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Och sade: Jag mente att du hade varit henne vred vorden, ty hafver jag gifvit henne dinom stallbroder; men hon hafver ena yngre syster, hon är dägeligare än hon, tag henne för desso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Då sade Simson till honom: Jag hafver en gång en rättfärdig sak emot de Philisteer; jag skall göra eder skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Och Simson gick bort, och fick trehundrade räfvar, och tog brandar, och vände ju en stjert emot den andra, och satte ju en brand emellan två stjertar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Och tände eld på dem, och släppte dem uti de Philisteers säd, och brände upp kärfvarna med den ståndande sädene, och vingårdarna, och oljoträn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Då sade de Philisteer: Ho hafver detta gjort? Då sades: Simson den Thimnitens måg, derföre att han hafver tagit honom hans hustru ifrå, och gifvit henne hans stallbroder. Då foro de Philisteer upp, och brände upp både henne och hennes fader i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Men Simson sade till dem: Jag låter eder det göra; jag vill ändå hämna mig på eder, och sedan vara tillfrids.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Och han slog dem hårdeliga, både på skuldror och på länder; och gick neder, och bodde uti en bergklyfto i Etham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Då drogo de Philisteer upp, och belade Juda; och gåfvo sig neder till Lehi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'De af Juda sade: Hvi hafven I dragit hitupp emot oss? De svarade: Vi äre komne hitupp till att binda Simson, att vi måge göra honom, såsom han oss gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Så drogo tretusend män af Juda neder i bergklyftena i Etham, och sade till Simson: Vetst du icke, att de Philisteer äro rådande öfver oss? Hvi hafver du så gjort emot oss? Han sade till dem: Såsom de hafva gjort emot mig, så hafver jag gjort emot dem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'De sade till honom: Vi äre komne hitneder till att binda dig, och få dig de Philisteer i händer. Simson sade till dem: Så svärjen, att I viljen intet hinder göra mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'De svarade honom: Vi vilje intet hinder göra dig; utan vi vilje allenast binda dig, och antvarda dig dem i händer, och vilje intet dräpa dig; och de bundo honom med tu ny tåg, och förde honom upp ifrå klippone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Och då han kom intill Lehi, skriade de Philisteer, och kommo emot honom; men Herrans Ande föll på honom, och tågen på hans armar vordo såsom blår, de af eld förbrände äro, så att banden på hans händer försmulto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Och han råkade en rutten åsnakindbåga; han räckte ut sina hand och tog honom, och slog dermed tusende män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Och Simson sade: Der ligga de ihop; med en åsnakindbåga hafver jag slagit tusende män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Och då han det utsagt hade, kastade han kindbågan utu sine hand, och kallade det rummet RamathLehi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Och som han begynte svårliga törsta, åkallade han Herran, och sade: Du hafver en så stor salighet gifvit igenom dins tjenares hand, och nu måste jag dö i törst, och falla uti de oomskornas händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Då öppnade Gud ena oxlatand i kindbåganom, och der gick ut vatten; och som han drack, kom hans ande igen, och vederqvicktes; derföre heter ock det rummet åkallarens kindbågabrunn, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Och han dömde Israel uti de Philisteers dagar i tjugu år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Och Simson gick till Gasa, och fick der se ena sköko, och lade sig när henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Då vardt sagdt de Gasiter: Simson är kommen härin; och de omhvärfde honom, och läto taga vara på honom i stadsportenom i hela nattene; och voro stilla i hela nattene, och sade: I morgon, då ljust varder, vilje vi slå honom ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Men Simson låg intill midnatt. Då stod han upp om midnatt, och fattade båda dörrarna i stadsporten med båda dörrträn, och skottbommen, och lade dem på sina axlar, och bar dem upp på bergshöjdena för Hebron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Derefter fick han kärlek till ena qvinno vid den bäcken Sorek, hvilken het Delila.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Upp till henne kommo de Philisteers Förstar, och sade till henne: Tala så vid honom, att du kan få se, hvarutinnan han sådana stor kraft hafver, och hvarmed vi kunne varda honom öfverhändige, så att vi finge bindan och tvingan; så vilje vi gifva dig hvar våra tusende och hundrade silfpenningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Och Delila sade till Simson: Käre, säg mig, hvaruti står din stora starkhet; och hvarmed man kunde binda dig, och tvinga dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Simson sade till henne: Om man bunde mig med sju ny tåg, som ännu intet förtorkad voro, så vorde jag svag, och såsom en annor menniska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Då förde de Philisteers Förstar upp till henne sju ny tåg, som ännu intet förtorkad voro, och hon band honom dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Och de hade håll på honom när henne i kammaren; och hon sade till honom: De Philisteer öfver dig, Simson! Och han slet sönder tågen, såsom ett vridet snöre söndergår, när det af eld förbrändt är; och vardt icke kunnigt, hvarutinnan hans starkhet var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Då sade Delila till Simson: Si, du hafver gäckat mig, och ljugit för mig; säg mig dock nu, hvarmed man dig binda kan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Han svarade: Om jag vorde bunden med ny tåg, der ännu intet arbete med gjordt är, så vorde jag svag, och såsom en annor menniska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Så tog Delila ny tåg, och band honom dermed, och sade: De Philisteer öfver dig, Simson! Och de hade håll på honom i kammaren; och han slet sönder dem utaf sina armar, såsom ett snöre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Delila sade till honom: Du hafver ännu gäckat mig, och ljugit för mig. Käre, säg mig dock, hvarmed man kan dig binda? Han svarade henne: Om du flätade sju lockar af mitt hufvud uti ett fläteband.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Och hon fäste dem in med en nagla, och sade till honom: De Philisteer öfver dig, Simson! Och han vaknade upp af sinom sömn, och drog de flätade lockar med nagla och fläteband ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Då sade hon till honom: Huru kan du säga, att du hafver mig kär, efter ditt hjerta är dock icke när mig? I tre gånger hafver du gäckat mig, och icke sagt mig, hvarutinnan din stora starkhet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Och som hon alla dagar låg honom uppå med sådana ordom, och lät honom ingen ro få, vardt hans själ uppgifven allt intill döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Och sade henne allt sitt hjerta, och sade till henne: På mitt hufvud hafver aldrig någon rakoknif kommit, ty jag är en Guds Nazir af moderlifvet; om man rakar håret af mig, så går min starkhet ifrå mig, så att jag varder svag, lika som andra menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Då nu Delila såg, att han hade uppenbarat henne allt sitt hjerta, sände hon bort, och lät kalla de Philisteers Förstar, och sade: Kommer än en gång hitupp; ty han hafver uppenbarat mig allt sitt hjerta. Då kommo de Philisteers Förstar upp till henne, och hade penningarna med sig i sine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Och hon lät honom sofva på sitt knä, och kallade en, som rakade honom bort de sju lockar af hans hufvud; och hon begynte till att tvinga honom, och hans magt var gången ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Och hon sade till honom: De Philisteer öfver dig, Simson! Som han nu vaknade af sinom sömn, tänkte han: Jag vill gå ut, såsom jag i flera resor gjort hafver, jag vill slita mig lös; och visste icke, att Herren var viken ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Men de Philisteer grepo honom, och stungo honom ögonen ut, och förde honom neder till Gasa, och bundo honom med två kopparfjettrar; och han måste mala i fängelset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Och hans hufvudhår begynte åter växa, der han rakad var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Då församlade sig de Philisteers Förstar, till att göra sinom gud Dagon ett stort offer, och göra sig glada, och sade: Vår gud hafver gifvit oss vår fienda Simson i våra händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Sammalunda när folket såg honom, prisade de deras gud: ty de sade: Vår gud hafver gifvit vår fienda i våra händer, den vårt land förderfvade, och slog många af oss ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Då nu deras hjerta väl gladt var, sade de: Låt hemta Simson, att han må spela för oss. Så hemtade de Simson utu fängelset, och han spelade för dem, och de ställde honom emellan två pelare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Men Simson sade till drängen, som ledde honom vid handena: Låt mig taga på pelarena, på hvilka huset hänger, att jag må stödja mig derintill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Och huset var fullt med män och qvinnor; och de Philisteers Förstar voro der ock alle, och på taket vid tretusend män och qvinnor, de som sågo till huru Simson spelade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Men Simson åkallade Herran, och sade: Herre, Herre, tänk uppå mig, och styrk mig, Gud! i denna gången, att jag för båda min ögon må ena reso hämnas på de Philisteer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Och han fattade de två medelpelare, på hvilka huset hängde, och stödde sig på dem, och tog den ena i den högra, och den andra i den venstra handena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Och sade: Min själ dö med de Philisteer! och han böjde dem krafteliga. Så föll huset uppå Förstarna, och uppå allt folket, som derinne var, så att de döde, som han drap i sin död, voro flere, än de som han drap medan han lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Då kommo hans bröder ditneder, och hela hans faders hus, och togo honom upp, och båro honom upp, och begrofvo honom i hans faders Manoahs graf, emellan Zorga och Esthaol. Men han dömde Israel i tjugu år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'En man var på Ephraims berg, benämnd Micha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Han sade till sina moder: De tusende och hundrade silfpenningar, som äro tagne ifrå dig, och som du svorit öfver, och sagt för min öron, si, de samma penningar äro när mig; jag hafver tagit dem till mig. Då sade hans moder: Välsignad vare min son Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Så fick han sine moder de tusende och hundrade silfpenningar igen; och hans moder sade: Jag hafver helgat de penningarna Herranom ifrå mine hand, för min son, till att man må göra ett gjutet beläte; derföre så får jag dig dem nu igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Men han fick sine moder penningarna igen. Då tog hans moder tuhundrade silfpenningar, och fick dem till guldsmeden; han gjorde henne ett gjutet beläte; det var sedan i Micha huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Och den mannen Micha hade så ett guds hus; och han gjorde en lifkjortel, och afgudar, och fyllde enom sinom son handena, att han vardt hans Prester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'På den tiden var ingen Konung i Israel, och hvar och en gjorde såsom honom tyckte godt vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Men en ung man var på den tiden af BethLehem Juda, ibland Juda slägte, och han var en Levit, och var dersammastäds främmande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Men han drog utu BethLehem, Juda stad, till att vandra hvart han kunde; och då han kom på Ephraims berg till Micha hus, på det han skulle hålla sin väg fram,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Frågade honom Micha: Hvadan kommer du? Han svarade honom: Jag är en Levit af BethLehem Juda, och vandrar hvart jag kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Micha sade till honom: Blif när mig, du skall vara min fader, och min Prest; jag vill gifva dig årliga tio silfpenningar, och någor förenämnd kläder, och din födo. Och Leviten gick med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Och Leviten tog till att blifva när mannenom; och han höll den unga mannen såsom en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Och Micha fyllde Levitenom handena, så att han vardt hans Prester, och blef så i Micha huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Och Micha sade: Nu vet jag, att Herren varder mig godt görandes, efter jag hafver en Levit till Prest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'På den tiden var ingen Konung i Israel; och Dans slägte sökte sig en arfvedel, der de måtte bo; ty intill den dagen var ännu ingen arflott fallen för dem ibland Israels slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Och Dans barn sände utaf sitt slägte och sina landsändar fem höfvitsmän, stridsamma män, ifrå Zorga och Esthaol, till att bespeja landet, och ransaka om det, och sade till dem: Går åstad, och bespejer landet; och de kommo uppå Ephraims berg till Micha hus, och blefvo der öfver nattene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Och som de nu voro med Micha husfolk, kände de röstena af dem unga mannenom Levitenom, och gingo bort till honom, och sade till honom: Ho hafver kommit dig hit? Hvad gör du här? Och hvad hafver du här?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Han svarade dem: Så och så hafver Micha gjort emot mig, och hafver lejt mig, att jag skall vara hans Prester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'De sade till honom: Käre, fråga Gud till, att vi måge få veta om vår väg, som vi vandrom, skall oss lyckosam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Presten svarade dem: Går åstad med frid; edar väg är rätt för Herranom, den I vandren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Så gingo de fem män åstad, och kommo till Lais, och sågo att det folk, som derinne var, bodde säkert, efter de Zidoniers sed, stilla och säkre; och ingen var, som dem något bekymmer gjorde i landena, eller hade det under sig; och voro långt ifrå de Zidonier, och hade intet beställa med något folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Och de kommo till sina bröder i Zorga och Esthaol; och deras bröder sade till dem: Huru går det till med eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'De sade: Upp, låt oss draga upp till dem; ty vi hafve besett landet, det är ganska godt; derföre skynder eder, och varer icke sene till att draga, att I mågen komma och taga landet in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'När I kommen, varden I finnande ett säkert folk, och landet är vidt och bredt; ty Gud hafver det gifvit i edra händer, en sådana plats, der intet fattas som på jordene är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Så drogo ut af Dans slägte, ifrå Zorga och Esthaol, sexhundrad män, väl väpnade till strids;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Och drogo ditupp, och lägrade sig i KiriathJearim i Juda; deraf kallas det rummet Dans lägre, allt intill denna dag; och det är bakför KiriathJearim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Och dädan gingo de upp på Ephraims berg, och kommo till Micha hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Då svarade de fem män, som hade varit utgångne till att bespeja Lais land, och sade till sina bröder: Veten I ock, att i dessom husom är en lifkjortel, afgudar och gjutet beläte? I mågen tillse, hvad eder till görandes är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'De drogo dit, och kommo i den unga mansens Levitens hus, uti Micha hus, och helsade honom vänliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Men de sexhundrad väpnade, med deras harnesk, som voro utaf Dans barnom, stodo för dörrene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Och de fem män, som hade utdragne varit till att bespeja landet, gingo upp, och kommo dit, och togo belätet, lifkjortelen, och de gjutna afgudarna; emedan stod Presten för portenom när de sexhundrad väpnade i deras harnesk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Som nu hine voro komne in uti Micha hus, och togo belätet, lifkjortelen, och de gjutna afgudarna, sade Presten till dem: Hvad gören I?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'De svarade honom: Tig, och håll munnen på dig, och kom med oss, att du må blifva vår fader och Prester. Är det dig bättre, att du äst Prester uti ens mans huse, än uti en hel slägt och ätt i Israel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Det behagade Prestenom väl; och tog både lifkjortelen, afgudarna, och belätet, och gaf sig midt ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Och då de vände om, och drogo sin väg, skickade de barnen, och boskapen, och allt det bästa som de hade, framför sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Som de nu voro fjerran komne ifrå Micha hus, ropade de män, som i husen voro vid Micha hus, och följde efter Dans barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Och ropade till Dans barn. Och de vände sitt ansigte om, och sade till Micha: Hvad skadar dig, att du så ropar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Han svarade: I hafven tagit bort mina gudar, som jag gjort hafver, och Presten, och dragen edra färde, och hvad hafver jag nu mer? Och I sägen ändå till mig: Hvad skadar dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Men Dans barn sade till honom: Låt dina röst intet höras när oss, att icke öfverfalla dig vrede män, och du låter dina själ till, och dins hus själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Så gingo Dans barn sin väg. Och Micha, då han såg att de voro honom för starke, vände om, och kom igen till sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Men de togo det Micha gjort hade, och den Presten, som han hade, och kommo till Lais, till ett stilla och säkert folk, och slogo dem med svärdsegg, och uppbrände staden med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Och ingen var, som dem undsatte, ty han låg långt ifrå Zidon, och hade med ingom beställa; och han låg i den dalen, som ligger vid BethRehob. Så byggde de staden, och bodde deruti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Och kallade honom Dan, efter sins faders Dans namn, hvilken af Israel född var; och staden het tillförene Lais.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Och Dans barn uppsatte sig belätet; och Jonathan, Gersons son, Manasse sons, och hans söner voro Prester uti de Daniters slägte, allt intill den tiden, som de vordo förde fångne utu landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Och satte alltså ibland sig det Micha beläte, som han gjort hade, så länge som Guds hus var i Silo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Uti den tiden var ingen Konung i Israel. Och en Levitisk man var en främling vid sidone af Ephraims berg, och hade tagit sig ena frillo till hustru uti BethLehem Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Och som hon bedref hor när honom, lopp hon ifrå honom till sins faders hus till BethLehem Juda, och blef der i fyra månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Och hennes man stod upp, och for efter henne, på det han skulle tala vänliga med henne, och hemta henne igen till sig. Och han hade en dräng och ett par åsnar med sig. Och hon hade honom in uti sins faders hus; och då qvinnones fader såg honom, vardt han glad, och undfick honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Och hans svär, qvinnones fader, höll honom uppe, så att han blef der i tre dagar när honom; åto och drucko, och blefvo der om nattene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'På fjerde dagen voro de bittida uppe, och han stod upp, och ville färdas; då sade qvinnones fader till sin måg: Styrk ditt hjerta med en beta bröd, sedan mån I fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Och de satte sig, och åto hvar med annan, och drucko. Så sade qvinnones fader till mannen: Käre, blif öfver nattena, och ditt hjerta vare lustigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Men mannen stod upp, och ville färdas, men hans svär nödgade honom, så att han blef den nattena der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Om morgonen på femte dagen var han uppe, och ville färdas; då sade qvinnones fader: Käre, vederqvick ditt hjerta, och låt oss töfva, så länge något lider uppå dagen; och de åto med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Och mannen stod upp och ville fara med sine frillo, och med sinom dräng; men hans svär, qvinnones fader, sade till honom: Si, dagen är framliden, och aftonen är för handene, blif qvar i natt; si, här är herberge ännu i denna dagen; blif här öfver natten, att ditt hjerta må vara lustigt; i morgon stån I bittida upp, och dragen edra färde till dina hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Men mannen ville icke blifva öfver nattena, utan stod upp, och for sin väg, och kom inför Jebus, det är Jerusalem, och hans par åsnar klefjade, och hans frilla med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Som de nu kommo intill Jebus, förled fast dagen, och drängen sade till sin herra: Käre, kom och låt oss draga in uti de Jebuseers stad, och blifva der öfver nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Men hans herre sade till honom: Vi vilje icke draga in uti de främmandes stad, som icke äro af Israels barn; utan vi vilje fram bätter till Gibea;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Och sade till sin dräng: Gack uppå, att vi måge komma någorstäds till nattena, antingen i Gibea eller i Ramah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Och de drogo framåt, och reste; och solen gick dem neder hardt invid Gibea, som ligger i BenJamin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Och der drogo de in, till att blifva der i Gibea öfver nattena. Då han kom derin, satte han sig på gatone i stadenom; ty der var ingen, som dem ville herberga i sino huse öfver nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Och si, der kom en gammal man utaf markene, ifrå sitt arbete om aftonen; och han var också utaf Ephraims berg, och en främling i Gibea; men folket i det rummet voro Jemini barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Och då han upplyfte sin ögon, såg han den främmande mannen på gatone, och sade till honom: Hvart vill du? Och hvadan kommer du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Han svarade honom: Vi äre komne ifrå BethLehem Juda, och farom intill sidona af Ephraims berg, dädan jag är; och var faren till BethLehem Juda, och nu far jag till Herrans hus, och ingen vill herberga mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Vi hafve halm och foder till våra åsnar, och bröd och vin för mig, och dine tjenarinno, och för drängen, som med dinom tjenare är; så att oss fattas intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Den gamle mannen sade: Var tillfrids; allt det dig fattas, finner du när mig; allenast blif icke öfver nattena på gatone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Och han hade honom i sitt hus, och gaf åsnomen foder; och de tvådde sina fötter, och åto och drucko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Och som deras hjerta begynte vara gladt, si, då kommo män af stadenom, Belials barn, och belade huset, och klappade på dörrena, och sade till den gamla mannen, värden i huset: Låt oss få den mannen hitut, som i ditt hus kommen är, att vi måge känna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Men mannen husvärden gick ut till dem, och sade till dem: Icke så, mine bröder, görer icke detta onda; efter denne mannen är kommen i mitt hus; görer icke en sådana galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Si, jag hafver ena dotter, den ännu en jungfru är, och denne hafver ena frillo, dem vill jag låta komma ut till eder, att I förnedren dem, och gören med dem hvad eder täckes; men på denna mannen görer icke en sådana galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Men männerna ville intet lyda honom. Så tog mannen sina frillo, och hade henne ut till dem; den kände de, och hade sig skändeliga med henne i den hela nattene allt intill morgonen; och som morgonrodnen uppgick, läto de gå henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Då kom qvinnan, litet för dagningen, inför dörrena af mansens hus, der hennes herre inne var, och föll der omkull, och låg der intill ljust var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Då nu hennes herre uppstod om morgonen, och lät upp dörrena af huset, och gick ut till att fara sin väg; si, då låg hans frilla för dörrene af huset, och hennes händer på tröskelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Och han sade till henne: Statt upp, låt oss gå; men hon svarade honom intet. Så tog han henne på sin åsna, redde sig till, och for hem till sitt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Som han hemkom, tog han en knif, och tog sina frillo, och styckade henne, med ben och med allo, i tolf stycker, och sände till alla Israels landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Alle de, som det sågo, sade: Sådant är aldrig skedt eller sedt, sedan Israels barn kommo utur Egypti land, intill denna dag: Nu, betänker eder häröfver, och rådens vid, och säger till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Så drogo Israels barn ut, och församlade sig ihop, såsom en man, ifrå Dan allt intill BerSeba, och ifrå Gileads land, intill Herran i Mizpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Och gingo tillhopa utaf alla vrår, all folk af all Israels slägte i Guds menighet, fyrahundradetusend män till fot, som svärd utdrogo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Men BenJamins barn fingo höra, att Israels barn voro dragne upp till Mizpa, och Israels barn sade: Säger, huru det onda tillgånget är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Då svarade Leviten, qvinnones man, som dräpen var, och sade: Jag kom till Gibea i BenJamin med mine frillo, till att blifva der öfver nattena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Då hofvo sig upp borgarena i Gibea emot mig, och belade mig i huset, om nattena, och ville slå mig ihjäl, och skämde min frillo, så att hon blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Så tog jag min frillo, och styckade henne, och sände det i alla Israels arfs mark; förty de hade gjort en slem ting, och galenskap i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Si, nu ären I här alle Israels barn, rådens vid, hvad I skolen göra dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Då reste sig allt folket upp, såsom en man, och sade: Ingen gånge hem i sina hyddo eller i sitt hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Utan det vilje vi nu göra emot Gibea; låt oss kasta lott;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Och taga tio män af hundrade, och hundrade af tusend, och tusend af tiotusend, af alla Israels slägter, att de besörja spisning för folket, att de måga komma, och göra med Gibea BenJamins, efter all deras galenskap, som de i Israel bedrifvit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Så församlade sig till staden alle Israels män, såsom en man, och förbundo sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Och Israels slägter sände några män till alla BenJamins slägt, och läto säga dem: Hvad är det för en ond ting, som när eder skedd är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Så får oss nu ut de män, Belials barn i Gibea, att vi måge dräpa dem, och låta det onda komma ifrån Israel. Men BenJamins barn ville icke lyda sina bröders Israels barnas röst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Utan församlade sig utu städerna intill Gibea, till att draga ut till strids emot Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Och vordo på den dagen talde BenJamins barn utu städerna, sex och tjugu tusend män, som svärd utdrogo; förutan de borgare i Gibea, de vordo talde sjuhundrade utvalde män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Och ibland allt detta folket voro sjuhundrade utvalde män, som vensterhändte voro, och kunde med slungor drabba på ett hår, så att de intet felade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Men de män af Israel, förutan de af BenJamin, vordo talde fyrahundradetusend män, som svärd förde, och stridsamme män voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Israels barn stodo upp, och drogo upp till Guds hus, och frågade Gud, och sade: Ho skall draga ditupp för oss till att begynna striden emot BenJamins barn? Herren sade: Juda skall begynna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Alltså stodo Israels barn om morgonen upp, och lägrade sig för Gibea;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Och hvar och en af Israel gick ut till att strida med BenJamin, och skickade sig till att strida emot Gibea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Då föllo BenJamins barn ut af Gibea, och slogo på den dagen af Israel tu och tjugu tusend män till markena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Men folket Israels män förmannade sig, och redde sig till att ytterligare strida på samma platsen, der de sig i den förra dagen redt hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Och Israels barn drogo upp, och greto för Herranom allt intill aftonen, och frågade Herran, och sade: Skole vi mer falla till och strida med BenJamins barn, våra bröder? Herren sade: Drager upp till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Och då Israels barn trädde den andra dagen till att strida emot BenJamins barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Föllo de BenJamiter utu Gibea emot dem på samma dagen, och slogo ännu till markena adertontusend män af Israels barn, som alle svärd förde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Då drogo all Israels barn upp, och allt folket, och kommo till Guds hus, och greto, och blefvo der för Herranom, och fastade den dagen intill aftonen, och offrade bränneoffer och tackoffer för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Och Israels barn frågade Herran, och dersammastäds var Guds förbunds ark på den tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Och Pinehas, Eleazars son, Aarons sons, stod för honom på den tiden, och sade: Skole vi mer draga ut till att strida emot BenJamins barn, våra bröder, eller skall jag vända igen? Herren sade: Drager ditupp; i morgon skall jag gifva dem i edra händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Och Israels barn beställde ett bakhåll omkring staden Gibea;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Och drogo så Israels barn upp på tredje dagen till BenJamins barn; och skickade sig emot Gibea, såsom i de två gånger tillförene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Då drogo BenJamins barn ut emot folket, och gåfvo sig ifrå staden, och begynte till att slå och sarga några af folket, såsom förr i de två gånger, i markene på två vägar, den ene går till BethEl, och den andre till Gibea, vid tretio män i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Då tänkte BenJamins barn: De äro slagne för oss såsom tillförene. Men Israels barn sade: Låt oss fly, att vi måge komma dem ifrå staden ut uppå vägarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Så reste upp alle män af Israel, hvar af sitt rum, och skickade sig i BaalThamar, och det bakhållet af Israel gaf sig upp utu sitt rum, ifrå Gaba kulo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Och kommo in mot Gibea tiotusend män, utvalde af hela Israel, så att striden vardt skarp; men de visste icke, att dem ondt tillstundade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Alltså slog Herren BenJamin för Israels barn, så att Israels barn på den dagen förderfvade fem och tjugu tusend och hundrade män i BenJamin, som alle svärd förde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Ty då BenJamins barn sågo, att de slagne voro, gåfvo Israels män dem rum; ty de förläto sig på bakhållet, som de hade beställt invid Gibea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Och bakhållet skyndade sig ock, och drogo fram till Gibea, och stormade till, och slogo den hela staden med svärdsegg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Och de hade en lösen sig emellan, de män af Israel och bakhållet, till att öfverfalla dem med svärd, när röken af stadenom uppslog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Då nu de män af Israel vände sig i stridene, och BenJamin begynte till att slå och försarga i Israel vid tretio män; och tänkte: De äro slagne för oss såsom i den förra stridene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Så begynte slå en rök af staden rättupp. Och BenJamin vände sig tillbaka; si, då gick röken af hela stadenom upp i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Och de män af Israel vände ock om; då förskräcktes de män af BenJamin; förty de sågo, att dem tillstundade ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Och de vände sig för de män af Israel på den vägen till öknena; men striden fullföljde dem; dertill de som af städerna inkomne voro, de förderfvade dem derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Och de kringhvärfde BenJamin, och fullföljde dem allt intill Menuah, och förtrampade dem inför Gibea österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Och föllo af BenJamin adertontusend män, som alle stridsamme män voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Då vände de sig, och flydde åt öknena till den bergklippon Rimmon; men på den samma vägen slogo de femtusend män, och följde dem efter allt intill Gideom, och slogo dem af tutusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Och så föllo på den dagen af BenJamin fem och tjugu tusend män, som svärd förde, och alle stridsamme män voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Allenast sexhundrad män vände sig, och flydde åt öknena till den bergklippon Rimmon; och blefvo i Rimmons bergklippo i fyra månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Och de män af Israel kommo igen till BenJamins barn, och slogo med svärdsegg dem i stadenom, både folk och fä, och allt det man fann; och alla de städer, som de funno, uppbrände de i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Och de män af Israel hade svorit i Mizpa, och sagt: Ingen af oss skall gifva sina dotter de BenJamiter till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Och folket kom till Guds hus, och blef der för Gudi allt intill aftonen; och de upphofvo sina röst, och greto svårliga,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Och sade: O Herre Israels Gud, hvi är detta skedt i Israel, att en slägt är i dag nederlagd i Israel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Och andra dagen var folket bittida uppe och byggde der ett altare, och offrade bränneoffer och tackoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Och Israels barn sade: Hvilken är den af Israels slägter, som icke hit uppkommen är med menighetene inför Herran? Ty en stor ed var gången, att den som icke uppkomme till Herran i Mizpa, han skulle döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Och Israel ångrade sig öfver sin broder BenJamin, och sade: I dag är en slägt i Israel nederlagd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Huru vilje vi göra, att de som qvare äro måga få hustrur? Ty vi hafve svorit vid Herran, att vi icke skole gifva dem hustrur utaf våra döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Och sade: Hvilken är af Israels slägter, som icke är kommen hitupp till Herran i Mizpa? Och si, der hade ingen varit i menighetenes lägre utaf Jabes i Gilead;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Ty de talde folket, och si, der var ingen borgare af Jabes i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Då sände menigheten tolftusend män af stridsamma män, och bödo dem, och sade; Går bort, och slår med svärdsegg de borgare i Jabes i Gilead, med hustrur och barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Dock skolen I så göra: allt det mankön är, och alla de qvinnor, som när manne legat hafva, skolen I tillspillogifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Och de funno när de borgare i Jabes i Gilead fyrahundrade pigor, som jungfrur voro, och när ingen man legat hade; dem förde de i lägret till Silo, som ligger i Canaans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Då sände hela menigheten bort, och lät tala med BenJamins barn, som lågo i bergklippone Rimmon, och kallade dem vänliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Alltså kommo BenJamins barn igen på den tiden; och de gåfvo dem till hustrur de som de vid lif behållit hade utaf Jabes qvinnfolk i Gilead; och funno så inga flera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Då ångrade sig folket öfver BenJamin, att Herren hade gjort ett splitter i Israels slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Och de äldste i menighetene sade: Hvad vilje vi göra, att de som öfver äro måga ock få hustrur? Ty de qvinnor i BenJamin äro förgjorda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Och sade: De måste ju behålla sitt arf, som igenblefne äro af BenJamin, att icke en slägt nederlägges i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Och vi kunne icke gifva dem våra döttrar till hustrur; ty Israels barn hafva svorit och sagt: Förbannad vare den, som de BenJamiter gifver hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Och de sade: Si, det är en årlig Herrans högtid i Silo, norrut ifrå Guds hus, österut på den vägen, som drager ifrå BethEl intill Sichem, och söder ifrå Lebona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Och de bödo BenJamins barnom, och sade: Går bort, och sitter i försåt i vingårdarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'När I då sen, att Silo döttrar gå ut i dans, så gifver eder hasteliga utu vingårdarna, och tager hvar och en sig en hustru af Silo döttrar, och går uti BenJamins land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'När nu deras fäder eller bröder komma till att beklaga sig för oss, vilje vi säga till dem: Varer dem barmhertige för våra skull; förty vi hafve icke tagit dem hustrur med strid, utan I villen icke gifva dem dem; det är nu edor skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'BenJamins barn gjorde ock så, och togo qvinnor efter sitt tal, hvilka de röfvade utaf dansen; och foro bort, och bodde i sin arfvedel, och byggde städer, och bodde deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Israels barn foro ock dädan på den tiden, hvar och en till sina slägt, och till sina ätt; och drogo ut dädan, hvar och en till sin arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'På den tiden var ingen Konung i Israel; utan hvar och en gjorde hvad honom tycktes rätt vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'På den tiden, då domare regerade, vardt en hård tid i landena; och en man af BethLehem Juda for bort, och var främmande uti de Moabiters land, med sine hustru och två söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Han het EliMelech, och hans hustru Naemi, och hans två söner Mahlon och Chilion, de voro Ephrateer af BethLehem Juda; och då de kommo in i de Moabiters land, blefvo de der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Och EliMelech, Naemis man, blef död; och hon blef qvar med sina två söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'De togo Moabitiska hustrur; den ena het Arpa, den andra Ruth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Och som de hade bott der i tio år, blefvo de både döde, Mahlon och Chilion, så att qvinnan var qvar efter båda sina söner och sin man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Så gjorde hon redo med sina två sonahustrur, och for ut igen af de Moabiters land; ty hon hade förnummit i de Moabiters land, att Herren hade sökt sitt folk, och gifvit dem bröd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Och gick ut ifrå det rum, der hon varit hade, och båda hennes sonahustrur med henne. Och då hon i vägen var hem åt Juda land igen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Sade hon till båda sina sonahustrur: Går edra färde, och vänder om igen, hvar edra till sins moders hus. Herren göre barmhertighet med eder, såsom I med de döda och med mig gjort hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Herren gifve eder, att I mågen finna ro, hvar i sins mans hus. Och hon kysste dem. Då hofvo de sina röst upp, och greto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Och sade till henne: Vi vilje gå med dig till ditt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Men Naemi sade: Vänder om, mina döttrar; hvi viljen I gå med mig? Huru kan jag nu härefter hafva barn i mitt lif, som edra män blifva måtte?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Vänder om, mina döttrar, och går edra färde: ty jag är nu för gammal, till att gifva mig manne i våld. Och om jag än sade: Det är förhoppandes, att jag i denna nattene må taga mig en man, och föda barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Så kunnen I dock icke bida, intilldess de varda store; ty I föråldradens, så att I kunden inga män hafva. Ingalunda, mina döttrar; ty det gör mig ångest för edra skull; ty Herrans hand är utgången öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Då hofvo de sina röst upp, och greto ännu mer; och Arpa kysste sina sväro; men Ruth blef när henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Men hon sade: Si, din svägerska hafver vändt tillbaka till sitt folk, och till sin gud. Vänd ock du om efter dina svägersko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ruth svarade: Tala mig icke i det sinnet, att jag skall öfvergifva dig, och vända tillbaka igen ifrå dig; dit du går, dit vill jag ock gå; der du blifver, der blifver jag ock. Ditt folk är mitt folk, och din Gud är min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Der du dör, der dör jag ock, der vill jag ock begrafven varda. Herren göre mig det och det, om döden icke skall skilja oss åt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Som hon nu såg, att hon stod fast i det sinnet, att hon ville följa henne, vände hon åter att tala mer derom med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Så gingo de båda med hvarandra, intilldess de kommo till BethLehem. Och då de kommo till BethLehem, rörde sig hela staden öfver dem, och sade: Är detta Naemi?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Men hon sade till dem: Kaller mig icke Naemi, utan Mara; ty den Allsmägtige hafver svårliga bedröfvat mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Full drog jag härut, och tomman hafver Herren låtit mig komma igen. Hvi kallen I mig då Naemi, efter Herren hafver så tryckt mig, och den Allsmägtige hafver bedröfvat mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Och det var på den tiden, då bjugganden var begynt, då Naemi och hennes sonahustru Ruth, den Moabitiskan, igenkommo af de Moabiters land till BethLehem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Och der var en man, Naemis mans frände af EliMelechs slägt, benämnd Boas; och var en ärlig man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Och Ruth, den Moabitiskan, sade till Naemi: Låt mig gå ut på åkren, och hemta ax efter den som jag nåde för finner. Hon sade till henne: Gack, min dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Hon gick åstad, kom och hemtade upp efter dem som skåro på åkrenom; och det hände, att den åkren var Boas arfvedel, som af EliMelechs slägt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Och si, Boas kom ifrå BethLehem och sade till skördemännerna: Herren vare med eder. De svarade: Herren välsigne dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Och Boas sade till sin tjenare, som satter var öfver skördemännerna: Hvem hörer den unga qvinnan till?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Drängen, som öfver skördemännerna satter var, svarade och sade: Det är den Moabitiska qvinnan, som med Naemi igenkommen är ifrå de Moabiters land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Ty hon sade: Käre, låt mig upphemta och församla emellan kärfvarna efter skördemännerna; och är så kommen, och hafver ståndit sedan i morgons intill nu, och hafver icke en tid gångit hem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Då sade Boas till Ruth: Hör, min dotter, du skall icke gå bort på någon annan åker till att hemta; och skall icke heller gå hädan, utan håll dig intill mina pigor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Och tag vara uppå, hvar de skära på åkren, och gack efter dem. Jag hafver sagt mina dränger, att ingen skall komma vid dig; och om dig törster, gack till karen, och drick der mina dränger hemta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Då föll hon på sitt ansigte, och tillbad ned på jordene, och sade till honom: Hvarmed hafver jag den nåden funnit för din ögon, att du känner mig, som dock främmande är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boas svarade och sade till henne: Mig är sagdt allt det du gjort hafver med dine sväro efter dins mans död, att du hafver öfvergifvit din fader och dina moder, och ditt fädernesland, och farit till det folk, som du tillförene intet kände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Herren vedergälle dig det du gjort hafver; och din lön vare fullkommen när Herranom Israels Gud, till hvilken du kommen äst, till att hafva tröst under hans vingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Hon sade: Låt mig finna nåd för din ögon, min Herre; ty du hafver hugsvalat mig, och talat dine tjenarinno vänliga till, ändock jag icke är såsom någon af dina pigor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Boas sade till henne: När måltid är, så kom hit till med, och ät bröd, och doppa din beta uti ättikona. Så satte hon sig när skördemännerna; och han lade henne torkad ax före, och hon åt, och vardt mätt, och lät blifva något qvart.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Och då hon stod upp till att hemta, böd Boas sina dränger, och sade: Låter henne ock hemta emellan kärfvarna, och snubber henne intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Och låter desslikes falla utaf händerna henne till, och låter liggat, att hon må upphemta det, och ingen tale derföre illa till henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Så hemtade hon på åkrenom allt intill aftonen; och det hon upphemtat hade, tröskade hon, och det var vid ett epha bjugg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Och lade på sig, och kom i staden, och viste sina sväro hvad hon hemtat hade; dertill bar hon fram, och gaf henne det henne qvart blifvit var, der hon af mättad vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Då sade hennes svära till henne: Hvar hafver du hemtat i dag, och hvar hafver du arbetat? Välsignad vare den som vid dig känts hafver. Och hon sade det sine sväro, när hvem hon arbetat hade, och sade: Den man, som jag i dag när arbetat hafver, heter Boas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Naemi sade till sina sonahustru: Välsignad vare han Herranom; ty han hafver icke tillbakalåtit sina barmhertighet, hvarken på de lefvande, eller på de döda. Och Naemi sade till henne: Den mannen är oss åkommen, och är vår arfvinge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Ruth, den Moabitiskan, sade: Han sade ock till mig: Håll dig intill mina dränger, tilldess de hafva allt inbergat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Naemi sade till Ruth sina sonahustru: Det är bättre, min dotter, att du går ut med hans pigor, att på en annan åker icke någor afvisar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Alltså höll hon sig intill Boas pigor, och hemtade der, så länge bjugganden och hveteanden öfverfaren var; och kom igen till sina sväro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Och Naemi hennes svära sade till henne: Min dotter, jag vill komma dig till ro, så att du skall må väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Den samme Boas, vår skyldman, när hvilkens pigor du varit hafver, kastar i denna nattene korn på sin loga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Så två dig, och smörj dig, och drag din kläder uppå, och gack neder till logan, så att ingen känner dig, tilldess han hafver ätit och druckit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'När han då lägger sig, så märk till, hvar han lägger sig, och kom och lyft upp kläden vid hans fötter, och lägg dig, så varder han dig väl sägandes, hvad du göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Hon sade till henne: Allt det du säger mig, vill jag göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Hon gick neder till logan, och gjorde allt såsom hennes svära henne budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Och då Boas hade ätit och druckit, vardt hans hjerta gladt, och kom och lade sig bakom en kornskyl; och hon kom sakta, och lyfte upp kläden vid hans fötter, och lade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Vid midnattstid vardt mannen förfärad, och tog om sig, och si, en qvinna låg vid hans fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Och han sade: Ho äst du? Hon svarade: Jag är Ruth din tjenarinna, sträck ut din vinga öfver dina tjenarinno; ty du äst arfvingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Han sade: Välsignad vare du Herranom, min dotter, du hafver sedermer gjort en bättre barmhertighet än tillförene, att du icke hafver gångit efter ynglingar, rika eller fattiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Nu, min dotter, frukta dig intet; allt det du säger, vill jag göra dig; förty hela staden af mitt folk vet, att du äst en dygdesam qvinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Det är sant, att jag är arfvingen, men en annar är närmer än jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Blif i natt; i morgon om han tager dig, är så godt; lyster honom ock icke taga dig, så vill jag taga dig, så visst som Herren lefver. Sof intill morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Och hon sof intill morgonen vid hans fötter; och hon stod upp, förra än någor den andra känna kunde och han sade: Låt icke uppenbart varda, att någon qvinna är kommen till logan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Och sade: Räck hit din mantel, som du hafver uppå, och håll honom fram; och hon höll honom fram, och han mälte sex mått korn, och lade på henne. Och han kom i staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Men hon kom till sina sväro; den sade: Huru går det med dig, min dotter? Och hon sade henne allt det mannen hade gjort henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Och sade: Dessa sex mått korn gaf han mig; ty han sade: Du skall icke komma med tomma händer till dina sväro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Hon sade: Låt oss bida, min dotter, tilldess du får se hvartut det vill; ty mannen vänder icke igen, med mindre han gör der i dag en ända med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boas gick upp i porten, och satte sig der. Och si, när arfvingen gick derfram, talade Boas till honom, och sade: Kom, och sätt dig här, ehuru ditt namn är. Och han kom, och satte sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Och han tog tio män af de äldsta i staden, och sade: Sätter eder här. Och de satte sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Då sade han till arfvingan: Naemi, som ifrå de Moabiters land igenkommen är, bjuder ett stycke åker fält, som hörde vår broder EliMelech till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Derföre tänkte jag, att jag skulle det kungöra dig, och säga: Vill du komma det i ditt arf, så köp det inför borgarena, och inför de äldsta af mitt folk. Vill du ock icke kommat i ditt arf, så säg mig det, att jag må veta det; ty här är ingen arfvinge till, annar än du, och jag näst dig. Han sade: Jag vill komman i mitt arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Boas sade: När du köper åkren af Naemis hand, så måste du ock taga Ruth, den Moabitiskon, dens dödas hustru, att du må uppväcka dem döda namn till hans arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Då sade han: Jag kan icke blifva vid arfvet, att jag tilläfventyrs icke förderfvar min arfvedel. Lös du hvad jag lösa skulle, ty jag kan icke lösan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Och det var en gammal sedvänja i Israel, när en någon ting icke ärfva eller köpa ville, till att all ting skulle fast blifva, så drog han sin sko utaf, ock fick dem andra; det var då till ett vittnesbörd i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Och arfvingen sade till Boas: Köp du det; och drog sin sko af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Och Boas sade till de äldsta, och till allt folket: I ären i denna dag vittne, att jag hafver köpt allt det EliMelech, och allt det Chilion och Mahlon tillhörde, utaf Naemis hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Dertill tager jag ock Ruth, den Moabitiskon, Mahlons hustru, mig till hustru, att jag må uppväcka dem döda namn i hans arfvedel, och hans namn icke skall utrotadt varda ibland hans bröder, och utu hans rums portar; dess ären I vittne i denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Och allt folket, som i portenom var, samt med de äldsta, sade: Vi äre vittne; Herren göre den qvinnona, som kommer i ditt hus, såsom Rachel och Lea, hvilka båda hafva uppbyggt Israels hus; och blif ärlig hållen i Ephrata, och var namnkunnig i BethLehem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Och ditt hus vare såsom Perez hus, hvilken Thamar födde Juda, utaf den säd, som Herren dig gifvandes varder af denna qvinnone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Så tog Boas Ruth, att hon vardt hans hustru; och när han låg när henne, gaf Herren henne, att hon vardt hafvandes, och födde en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Då sade qvinnorna till Naemi: Lofvad vare Herren, som hafver låtit dig icke fattas arfvinga i denna tiden, att hans namn må blifva i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Han varder dig kommandes till lif igen, och försörjandes dig i dinom ålder; ty din sonahustru, som dig älskat hafver, hafver födt den dig bättre är än sju söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Och Naemi tog barnet, och lade det i sitt sköt, och vardt dess amma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Och hennes grannhustrur gåfvo honom ett namn, och sade: Naemi är födt ett barn; och de kallade honom Obed; han är Isai fader, som är Davids fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Detta är Perez börd: Perez födde Hezron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hezron födde Ram; Ram födde Amminadab;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminadab födde Nahesson; Nahesson födde Salmon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmon födde Boas; Boas födde Obed;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed födde Isai; Isai födde David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Det var en man af Ramathaim Zophim, af Ephraims berg; han het ElKana, Jerohams son, Elihu sons, Thohu sons, Zuphs sons, hvilken en Ephrateer var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Och han hade två hustrur, den ena het Hanna, den andra Peninna; men Peninna hade barn, och Hanna hade inga barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Den samme mannen gick upp ifrå sin stad i sinom tid, att han skulle tillbedja och offra Herranom Zebaoth i Silo: och dersammastäds voro Herrans Prester Hophni och Pinehas, både Eli söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Då nu en dag kom, att ElKana offrade, gaf han sine hustru Peninna, och alla hennes söner och döttrar, stycker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Men Hanna gaf han ett stycke sörjandes; ty han hade Hanna kär; men Herren hade igenlyckt hennes lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Och hennes haterska gjorde henne harmt, och kastade henne före hennes ofruktsamhet, att Herren hade igenlyckt hennes lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Så gjorde hon hvart år, när de gingo upp till Herrans hus, och gjorde henne alltså harmt; men hon gret, och åt intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Och ElKana hennes man sade till henne: Hanna, hvi gråter du? Och hvi äter du icke? Och för hvad sak är ditt hjerta så illa tillfrids? Är jag dig icke bättre än tio söner?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Då stod Hanna upp, sedan hon ätit och druckit hade i Silo; och Presten Eli satt på en stol utanför dörrene af Herrans tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Och hon var full med hjertans bedröfvelse; och hon bad till Herran, och gret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Och lofvade ett löfte, och sade: Herre Zebaoth, om du ville se till dina tjenarinnos jämmer, och tänka på mig, och icke förgäta dina tjenarinno, utan gifva dina tjenarinno en son, så vill jag gifva honom Herranom, så länge han lefver, och ingen rakoknif skall komma på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Och som hon länge bad för Herranom, gaf Eli akt på hennes mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Ty Hanna talade i sitt hjerta, allenast hennes läppar rörde sig, men hennes röst hördes intet. Då mente Eli, att hon var drucken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Och sade till henne: Huru länge vill du vara drucken? Låt vinet gå af dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Men Hanna svarade och sade: Nej, min Herre, jag är en bedröfvad qvinna; vin och starka drycker hafver jag icke druckit, utan hafver utgjutit mitt hjerta för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Räkna dock icke dina tjenarinno såsom en Belials dotter; ty jag hafver utaf mitt svåra bekymmer och sorg talat allt härtill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Eli svarade, och sade: Gack i frid; Israels Gud gifve dig dina bön, den du af honom bedit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Hon sade: Låt dina tjenarinno finna nåd för din ögon. Så gick qvinnan sin väg och åt, och såg icke mer så sorgeliga ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Och om morgonen voro de bittida uppe; och då de tillbedit hade för Herranom, vände de om, och gingo hem igen till Ramath. Och ElKana kände sina hustru Hanna. Och Herren tänkte på henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Och då någre dagar voro framlidne, vardt hon hafvandes, och födde en son, och kallade honom Samuel, sägandes: Ty jag hafver bedit honom af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Och då mannen ElKana for upp med hela sitt hus, till att offra Herranom offer efter sedvänjon och sitt löfte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'For Hanna intet med upp; utan sade till sin man: Jag vill icke fara upp, tilldess barnet är afvanat; då vill jag hafva honom med, att han må hafvas fram för Herran, och blifva der sedan evigliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'ElKana hennes man sade till henne: Gör såsom dig täckes; blif, tilldess du hafver afvant honom; Herren stadfäste det han sagt hafver. Så blef då qvinnan, och däggde sin son, intilldess hon vande honom af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Och så hade hon honom upp, sedan hon honom afvant hade, med tre stutar, med ett epha mjöl, och med en flasko vin, och hade honom in i Herrans hus i Silo; och pilten var ännu ung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Och de slagtade stuten, och hade pilten fram för Eli.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Och hon sade: Ack! min Herre, så visst som din själ lefver, min Herre, jag är den qvinnan, som här när dig stod, och bad Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Då jag bad om denna pilten. Nu hafver Herren gifvit mig den bönena, som jag bad af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Derföre gifver jag honom Herranom igen evigliga, efter han af Herranom beden är. Och de tillbådo der Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Och Hanna bad, och sade: Mitt hjerta fröjdar sig i Herranom; mitt horn är upphöjdt i Herranom; min mun hafver vidt öppnat sig öfver mina fiendar; ty jag fröjdar mig af dine salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Ingen är helig såsom Herren. Utan dig är ingen; och ingen tröst är såsom vår Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Låter af att berömma eder och tala stor ord. Låter det gamla utur edar mun: ty Herren är en Gud, som vet det, och låter icke sådana anslag hafva framgång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'De starkas båge är sönderbruten, och de svage äro omgjordade med starkhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'De som mätte voro, de vordo sålde för bröd; och de som hunger ledo, hungra intet mer; tilldess den ofruktsamma födde sju, och den som mång barn hade, vardt försvagad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Herren dödar, och gifver lif; förer till helvete, och derut igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Herren gör fattigan; han gör ock rikan han förnedrar och upphöjer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Han uppreser den torftiga utu stoftet, och upphäfver den fattiga utu träcken, att han skall sätta honom ibland Förstar, och låtan ärfva ärones stol; ty verldenes ändar äro Herrans, och jordenes krets hafver han satt deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Han varder bevarandes sina heligas fötter; men de ogudaktige skola vara tyste i mörkrena; ty ingen förmår något af sin egen kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'För Herranom skola förskräckas hans fiender; öfver dem skall han dundra i himmelen. Herren skall döma verldenes ändar, och skall gifva sinom Konung magt, och upphöja sins Smordas horn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Och ElKana gick hem igen till Hamath uti sitt hus, och pilten var Herrans tjenare inför Presten Eli.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Men Eli söner voro Belials barn, och visste intet af Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Ej heller hvad deras Prestaämbete var till folket. Då någor ville något offra, så kom Prestens dräng, medan köttet kokades, och hade en treuddad gaffel i sine hand:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'Och stack i grytona eller kettilen, eller pannona, eller krukona, och hvad han drog ut med gaffelen, det tog Presten till sig. Så gjorde de allom Israel, som ditkommo till Silo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Sammalunda, förra än de uppbrände det feta, kom Prestens dräng, och sade till honom, som offret frambar: Få mig kött, att jag må steka det åt Prestenom; ty han vill icke taga kokadt kött af dig, utan rått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'När då någor sade till honom: Låt upptända det feta såsom det bör sig i dag, och tag sedan hvad ditt hjerta begärar, så sade han till honom: Du skall nu gifva mig det, eljest skall jag taga det med våld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Derföre var piltarnas synd ganska stor för Herranom; förty folket förhädde Herrans spisoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Men Samuel var en tjenare för Herranom, en dräng i en linnen lifkjortel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Dertill gjorde hans moder honom en liten kjortel, och förde den upp till honom i sinom tid, då hon uppgick med sin man, till att offra offer i sinom tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Och Eli välsignade ElKana och hans hustru, och sade: Herren gifve dig säd utaf denna qvinnone för den bön, som du hafver bedit af Herranom. Och de gingo hem till sitt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Och Herren sökte Hanna, att hon blef hafvandes, och födde tre söner och två döttrar; men pilten Samuel växte till för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Men Eli var ganska gammal, och han förnam hvad hans söner gjorde allom Israel; och att de sofvo när de qvinnor, som tjente inför dörrene af vittnesbördsens tabernakel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Och han sade till dem: Hvi gören I sådant? Ty jag hörer edart onda väsende af allt detta folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Icke så, mina barn, det är icke godt rykte, som jag hörer; I kommen Herrans folk till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Om någor syndar emot en mennisko, så kunna domarena förlika det; men om någor syndar emot Herran, ho kan förlikat? Och de hörde intet sins faders röst; ty Herren ville döda dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Men pilten Samuel växte till, och var både Herranom och menniskom täcker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Och en Guds man kom till Eli, och sade till honom: Så säger Herren: Jag hafver uppenbarat mig dins faders huse, då de ännu voro uti Egypten i Pharaos hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Och utvalde honom der mig, för all Israels slägter till Presterskap, att han skulle offra på mitt altare, och upptända rökverk, och bära lifkjortel för mig: och gaf dins faders huse all Israels barnas offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Hvi spjernar du då emot mitt offer och spisoffer, som jag budit hafver i tabernaklet, och du ärar dina söner mer än mig, så att I göden eder utaf allt mitt folks Israels spisoffers förstling?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Derföre säger Herren Israels Gud: Jag hafver sagt, att ditt hus och dins faders hus skulle vandra för mig evinnerliga. Men nu säger Herren: Det vare långt ifrå mig; utan den mig ärar, honom vill jag ock ära: men den mig föraktar, han skall komma på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Si, den tid skall komma, att jag skall bryta din arm sönder, och dins faders hus arm, så att ingen gammal skall vara i dino huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Och du skall se din motståndare uti tabernaklet i allo Israels godo; och ingen gammal skall vara i dins faders hus evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Dock vill jag icke utrota af dig allan man ifrå mitt altare, på det din ögon skola försmäkta, och din själ gräma sig; och hela hopen i dino huse skola dö, då de till manna komne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Och detta skall vara dig ett tecken, som båda dina söner Hophni och Pinehas öfvergå skall: På en dag skola de både dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Och jag skall uppväcka mig en trogen Prest, och han skall göra såsom det i mino hjerta och mine själ är; honom skall jag bygga ett säkert hus, så att han skall vandra inför minom Smorda i alla dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Och den qvar blifver af ditt hus, han skall komma och falla neder för honom, om en silfpenning och ett stycke bröd, och skall säga: Käre, låt mig komma till en Prestadel, att jag må äta en beta bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Och då pilten Samuel tjente Herranom under Eli, var Herrans ord sällsynt på den tiden, och var fögo Prophetia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Och det begaf sig på samma tid, att Eli låg i sino rumme, och hans ögon begynte mörkas, så att han icke se kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Och Samuel hade lagt sig uti Herrans tempel, der Guds ark var, förra än Guds lampa utsläcktes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Och Herren kallade Samuel. Han svarade: Si, här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Och han lopp till Eli, och sade: Si, här är jag, du kallade mig. Han sade: Jag hafver intet kallat dig; gack bort igen, och lägg dig sofva. Och han gick bort, och lade sig sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Och Herren kallade åter Samuel, och Samuel stod upp, och gick till Eli, och sade: Si, här är jag, du hafver kallat mig. Han sade: Jag hafver icke kallat dig, min son; gack bort igen, och lägg dig sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Men Samuel kände icke ännu Herran, och Herrans ord var honom icke ännu uppenbaradt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Och Herren kallade Samuel ännu tredje gången, och han stod upp, och gick till Eli, och sade: Si, här är jag, du hafver kallat mig. Så förmärkte Eli, att Herren kallade pilten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Och sade till honom: Gack bort igen, och lägg dig sofva; och om han mer kallar dig, så säg: Tala, Herre, ty din tjenare hörer till. Samuel gick bort och lade sig i sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Så kom Herren, och gick fram, och kallade såsom tillförene: Samuel, Samuel. Och Samuel sade: Tala, ty din tjenare hörer till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Och Herren sade till Samuel: Si, jag skall göra en ting i Israel, så att den det får höra, honom skall gälla i båda hans öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'På den dagen skall jag uppväcka öfver Eli allt det jag öfver hans hus sagt hafver; jag skall begynnat och fullkomnat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Ty jag hafver sagt honom till, att jag vill vara domare öfver hans hus till evig tid, för den missgernings skull, att han visste huru hans söner bedrefvo slem ting, och hafver icke en gång sett illa på dem derföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Fördenskull hafver jag svorit Eli huse, att denna Eli hus missgerning skall icke försonad varda antingen med offer eller spisoffer, till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Och Samuel låg intill morgonen, och lät upp dörrena af Herrans hus. Och Samuel torde icke säga Eli synena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Då kallade Eli honom, och sade: Samuel, min son. Han svarade: Si, här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Han sade: Hvad är det för ord, som dig sagdt är? Dölj det icke för mig; Gud göre dig det och det, om du något döljer för mig, af det som dig sagdt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Då sade Samuel honom alltsamman, och döljde intet för honom; men han sade: Han är Herren; han göre såsom honom godt tyckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Och Samuel växte till, och Herren var med honom, och intet af all hans ord föll på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Och hela Israel, allt ifrå Dan intill BerSaba, visste att Samuel var en trogen Herrans Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Och Herren syntes åter i Silo; ty Herren var Samuel uppenbarad vorden i Silo, genom Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Och Samuel begynte predika för hela Israel. Och Israel drog ut emot de Philisteer i strid, och lägrade sig vid Hjelpostenen; men de Philisteer hade lägrat sig i Aphek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Och de gjorde redo emot Israel; och hären vardt förskingrad, så att Israel vardt slagen förde Philisteer; och de slogo i spetsen på markene vid fyratusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Och då folket kom i lägret, sade de äldsta i Israel: Hvi hafver Herren låtit slå oss i dag för de Philisteer? Låt oss taga till oss Herrans förbunds ark ifrå Silo, och låt honom komma ibland oss, att han må frälsa oss ifrå våra fiendars hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Och folket sände till Silo, ock läto hemta dädan Herrans Zebaoths förbunds ark, hvilken der sitter på Cherubim. Och voro de två Eli söner med Guds förbunds ark, Hophni och Pinehas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Och då Herrans förbunds ark kom i lägret, skriade hela Israel med stort skriande, så att det skall i markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Då de Philisteer hörde det skriandet, sade de: Hvad är det för ett skri och glädje uti de Ebreers lägre? Och då de förnummo, att Herrans ark var kommen i lägret,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Fruktade de sig, och sade: Gud är kommen i lägret; och sade ytterligare: Ve oss, ty det hafver icke så varit tillförene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Ve oss, ho kan hjelpa oss ifrå dessa mägtiga Gudars hand? Det äro de Gudar, som slogo Egypten med allahanda plågo i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Så varer nu tröste, och varer män, I Philisteer, att I icke skolen tjena de Ebreer, såsom de hafva tjent eder; varer män och strider.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Då stridde de Philisteer, och Israel vardt slagen, och hvar och en flydde uti sina hyddo; och det var en ganska stor slagtning, så att utaf Israel föllo tretiotusend män fotfolk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Och Guds ark vardt tagen, och de två Eli söner Hophni och Pinehas blefvo döde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Då lopp en af BenJamin utaf hären, och kom den samma dagen till Silo; och hade rifvit sin kläder, och hade strött jord uppå hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Och som han kom derin, satt Eli på en stol, till att se ut på vägen; ty hans hjerta var bekymradt om Guds ark; och då mannen kom i staden, sade han det; och hela staden gret och ropade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Och som Eli fick höra det ropet, sade han: Hvad är detta för ett rop och buller? Så kom mannen hasteliga, och sade det Eli.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Och Eli var åtta och niotio år gammal; och hans ögon voro mörk, så att han icke kunde se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Och mannen sade till Eli: Jag är kommen, och är flydd i dag utu hären; men han sade: Huru går det, min son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Då svarade bådet, och sade: Israel är flydd för de Philisteer, och en stor slagtning är skedd på folket, och dine två söner, Hophni och Pinehas, äro döde; dertill är Guds ark borttagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Och som han rörde om arken, föll han tillrygga af stolenom vid dörrena, och slog sig halsen sönder, och blef död; ty han var gammal och en tung man; men han hade dömt Israel i fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Och hans sonahustru, Pinehas hustru, var hafvandes, och skulle snart läggas ned. Då hon hörde det ryktet, att Guds ark var tagen, och hennes svär och man voro döde, böjde hon sig, och födde; ty hennes nöd kom henne uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Och som hon nu dö skulle, sade qvinnorna, som när henne stodo: Var icke förfärad, du hafver födt en son; men hon svarade intet, och lade det heller intet på hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Och hon kallade det barnet Icabod, och sade: Israels härlighet är borto; efter Guds ark tagen var, och hennes svär, och hennes man;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Och sade åter: Israels härlighet är borto; ty Guds ark är tagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Och de Philisteer togo Guds ark, och förde honom ifrå Hjelpostenen intill Asdod,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Uti Dagons hus, och satte honom bredovid Dagon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Och som de af Asdod den andra morgonen bittida uppstodo, funno de Dagon liggandes framstupa, på jordene inför Herrans ark; men de togo Dagon, och satte honom upp igen i sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Då de den andra morgonen igen uppstodo, funno de Dagon åter liggandes framstupa på jordene inför Herrans ark, och hans hufvud och båda hans händer afhuggna vid tröskelen, så att stumpen låg allena för sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Derföre träda icke Dagons Prester, och alle de som i Dagons hus gå, på Dagons tröskel i Asdod, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Men Herrans hand vardt svår öfver dem i Asdod, och förderfvade dem; och slog Asdod och alla dess gränsor, i deras hemlig rum baktill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Då nu det folk i Asdod sågo, att så tillgick, sade de: Låt icke Israels Guds ark blifva när oss, förty hans hand är för svår öfver oss, och öfver vår gud Dagon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Och de sände bort, och församlade alla de Philisteers Förstar till sig, och sade: Hvad skole vi göra af Israels Guds ark? Då svarade de: Låter bära Israels Guds ark omkring till Gath. Och de båro Israels Guds ark omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Då de nu båro honom omkring, vardt ett stort buller i stadenom genom Herrans hand; och han slog folket i stadenom, både små och stora, och förderfvade dem i deras hemlig rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Så sände de Guds ark till Ekron. Då nu Guds ark kom till Ekron, ropade de af Ekron, och sade: De hafva omkringdragit Guds ark till mig, på det de skola dräpa mig och mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Då sände de bort, och församlade alla de Philisteers Förstar, och sade: Sänder Israels Guds ark åter till sitt rum igen, att han icke dräper mig och mitt folk; förty Guds hand gjorde ett ganska stort rumor med dräpande i hela stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Och det folk, som icke blefvo döde, de vordo slagne i deras hemlig rum, så att skriet af stadenom gick upp i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Så var Herrans ark i sju månader uti de Philisteers land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Och de Philisteer kallade sina Prester och spåmän, och sade: Hvad skole vi göra med Herrans ark? Säger oss före, hvarmed vi skole sända honom till sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'De sade: Viljen I sända Israels Guds ark, så sänder honom icke allstinges blottan, utan betaler honom ett skuldoffer; så varden I helbregda, och eder skall varda kunnigt, hvarföre hans hand icke återvänder af eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Men de sade: Hvilket är det skuldoffret, det vi honom gifva skole? De svarade: Fem gyldene ardsar, och fem gyldene möss, efter de fem Philisteers Förstars tal; förty det hafver varit allt enahanda plåga öfver eder alla, och öfver edra Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Så må I nu göra liknelse efter edra ardsar, och efter edra möss, som edart land förderfvat hafva, så att I hedren Israels Gud; tilläfventyrs hans hand varder lättare öfver eder, och öfver edar gud, och öfver edart land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Hvi förhärden I edor hjerta, såsom de Egyptier och Pharao förhärde sin hjerta? Skedde det icke så, att då han beviste sig på dem, läto de fara dem, att de gingo sin väg?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Så tager nu till, och görer en ny vagn; och tager två unga däggande kor, på hvilka intet ok kommet är, och spänner dem för vagnen, och låter deras kalfvar blifva qvara hemma efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Och tager Herrans ark, och sätter honom på vagnen; och de gyldene klenodier, som I honom till skuldoffer gifven, lägger i ett skrin utmed hans sido, och sänder honom åstad, och låter gån.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Och ser I till, går han upp den vägen åt sina gränsor emot BethSemes, så hafver han gjort oss allt detta stora onda; hvar ock icke, så måge vi veta, att hans hand icke hafver rört oss, utan det är oss eljest af en olycko påkommet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Folket gjorde ock så, och togo två unga däggande kor, och spände dem för en vagn, och behöllo deras kalfvar hemma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Och satte Herrans ark på vagnen, och det skrinet med de gyldene möss, och med deras ardsars liknelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Och korna gingo rättfram den vägen, som drog till BethSemes, på enom väg, och gingo och råmade, och veko hvarken på den högra sidona eller på den venstra; och de Philisteers Förstar gingo efter dem, allt intill BethSemes gränso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Men de BethSemiter gingo och skåro i hveteandene i dalenom, och de hofvo sin ögon upp, och fingo se arken, och vordo glade att de fingo se honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Men vagnen kom uppå Josua den BethSemitens åker, och stadnade der. Och der var en stor sten; och de höggo sönder trät af vagnenom, och offrade de kor Herranom till bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Och Leviterna lyfte Herrans ark neder, och det skrinet, som der bredovid låg, der de gyldene klenodier uti voro, och satte på den stora stenen. Och det folket i BethSemes offrade på den dagen Herranom bränneoffer och annor offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'När nu de fem Philisteers Förstar hade detta sett, foro de tillbaka igen på samma dagen till Ekron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Och detta äro de gyldene ardsar, som de Philisteer offrade Herranom till skuldoffer: Asdod en, Gasa en, Askelon en, Gath en, och Ekron en;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Och gyldene möss efter talet af alla de Philisteers städer, under de fem Förstar, både murade städer och byar; och intill det stora sorgerummet, der de läto Herrans ark uppå, intill denna dag, på Josua den BethSemitens åker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Och somlige af de BethSemiter vordo slagne, derföre att de hade sett Herrans ark; och han slog af folket femtiotusend och sjutio män. Då jämrade sig folket, att Herren hade med så stor plågo slagit folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Och det folket i BethSemes sade: Ho kan blifva ståndandes för Herranom, en sådana helig Gud? Och till hvem skall han fara ifrån oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Och de sände bådskap till de borgare af KiriathJearim, och läto säga dem: De Philisteer hafva fört igen Herrans ark; kommer hitneder, och hemter honom upp till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Så kommo det folket af KiriathJearim, och hemtade Herrans ark ditupp, och förde honom i AbiNadabs hus i Gibea; och hans son Eleazar vigde de, att han skulle taga vara på Herrans ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Och ifrå den dagen, då Herrans ark kom till KiriathJearim, fördröjde sig tiden, tilldess tjugu år voro förlupne; och allt Israels hus greto för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Men Samuel sade till hela Israels hus: Om I omvänden eder med allt hjerta till Herran, så låter ifrån eder de främmande gudar och Astaroth, och bereder edart hjerta till Herran, och tjener honom allena, så varder han eder frälsandes utu de Philisteers hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Så bortkastade Israels barn ifrå sig Baalim och Astaroth, och tjente Herranom allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Och Samuel sade: Församler hela Israel till Mizpa, att jag må der bedja Herran för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Och de kommo tillhopa i Mizpa, och öste vatten, och göto ut för Herranom, och fastade den dagen, och sade der: Vi hafve syndat för Herranom. Och så dömde Samuel Israels barn i Mizpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Då nu de Philisteer hörde, att Israels barn voro tillhopakomne i Mizpa, drogo de Philisteers Förstar upp emot Israel. När Israels barn det hörde, fruktade de sig för de Philisteer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Och sade till Samuel: Vänd icke igen att ropa för oss till Herran vår Gud, att han hjelper oss utu de Philisteers hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel tog ett fett lamb, och offrade Herranom ett helt bränneoffer, och ropade till Herran för Israel; och Herren bönhörde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Och som Samuel offrade bränneoffret, kommo de Philisteer fram till att strida emot Israel. Men Herren lät dundra en stor tordön öfver de Philisteer på den dagen; och förfärade dem, så att de vordo slagne för Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Så drogo Israels män ut ifrå Mizpa, och jagade de Philisteer, och slogo dem allt inunder BethCar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Då tog Samuel en sten, och satte honom emellan Mizpa och Sen, och kallade honom Hjelposten, och sade: Allt härintill hafver Herren hulpit oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Så vordo de Philisteer förtryckte, och kommo intet mer i Israels gränso. Och Herrans hand var emot de Philisteer, så länge Samuel lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Så vordo ock de städer Israel igengifne, som de Philisteer dem ifråtagit hade, ifrån Ekron intill Gath, med deras gränsor; dem friade Israel utu de Philisteers hand; ty Israel hade frid med de Amoreer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Och Samuel dömde Israel, så länge han lefde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Och for hvart år omkring till BethEl, och Gilgal, och Mizpa. Och när han hade på all denna rummen dömt Israel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Kom han igen till Ramath, ty der var hans hus; och dömde der Israel, och byggde der Herranom ett altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Då nu Samuel vardt gammal, satte han sina söner till domare öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Hans förstfödde son het Joel, och den andre Abia; och de voro domare i BerSaba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Men hans söner vandrade icke uti hans vägar; utan böjde sig efter girighet, och togo gåfvor, och förvände rätten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Så församlade sig alle äldste i Israel, och kommo till Ramath till Samuel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Och sade till honom: Si, du äst vorden gammal, och dine söner gå icke uti dina vägar: så sätt nu en Konung öfver oss, den oss döma må, såsom alle Hedningar hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Det behagade Samuel illa, när de sade: Få oss en Konung, den oss döma må. Och Samuel bad inför Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Och Herren sade till Samuel: Hör folkens röst i allt det de hafva talat dig till; förty de hafva icke förkastat dig, utan mig, att jag icke skall vara Konung öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'De göra dig såsom de alltid gjort hafva, ifrå den dag, då jag förde dem utur Egypten, allt intill denna dag; och hafva öfvergifvit mig, och tjent andra gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Så hör nu deras röst; dock betyga dem, och undervisa dem Konungens rätt, den öfver dem råda skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Och Samuel sade all Herrans ord folkena, som af honom Konung begärat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Detta skall vara Konungs rätt, den öfver eder råda skall; edra söner skall han taga till sin vagn, och resenärar som rida för hans vagn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Och till höfvitsmän öfver tusende, och öfver femtio, och till åkermän, som hans åker bruka skola, och till uppskärare i hans säd, och de som göra hans harnesk, och det hans vagnar tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Edra döttrar skall han taga sig till apothekerskor, kokerskor och bakerskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Edra bästa åkrar och vingårdar, och oljogårdar skall han taga och gifva sina tjenare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Dertill skall han taga af edra säd och vingårdar tiond, och gifva sina kamererare och tjenare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Och edra tjenare och tjenarinnor, och edra dägeligaste ynglingar, och edra åsnar, skall han taga, och uträtta sin ärende med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Af edra hjordar skall han taga tiond; och I måsten vara hans trälar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'När I då ropen på den tiden öfver edar Konung, som I eder utvalt hafven, så skall Herren på den tiden intet höra eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Men folket ville intet höra Samuels röst, och sade: Ingalunda, utan en Konung måste vara öfver oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Att vi ock äre såsom alle andre Hedningar; att vår Konung må döma oss, och draga ut för oss, när vi före vårt örlig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Så hörde Samuel allt detta, som folket sade: och sade det för Herrans öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Och Herren sade till Samuel: Hör deras röst, och gör dem en Konung. Och Samuel sade till Israels män: Går edra färde, hvar och en i sin stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Och en man af BenJamin benämnd Kis, Abiels son, Zerors sons, Bechoraths sons, Aphiahs sons, en mans Jemini sons, en ärlig man;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Han hade en son benämnd Saul, han var en dägelig ung man, så att ingen dägeligare var ibland Israels barn; hufvudet högre än allt folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Så hade Sauls fader Kis borttappat sina åsninnor; och han talade till sin son Saul: Tag en af drängerna med dig, och statt upp, gack bort, och sök upp åsninnorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Och han gick öfver Ephraims berg, och genom det landet Salisa, och de funno dem intet. De gingo igenom det landet Saalim, och der voro de intet. De gingo genom Jemini land, och funno dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'När de kommo uti det landet Zuph, sade Saul till drängen, som med honom var: Kom, låt oss gå hem igen; min fader måtte öfvergifva åsninnorna, och hafva sorg om oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Men han sade: Si, här är en märkelig Guds man i denna staden; allt det han säger, det sker; låt oss nu gå dit; tilläfventyrs säger han oss vår väg, den vi gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Saul sade till sin dräng: Om vi än gå dit, hvad bäre vi mannenom? Förty brödet är allaredo upptärdt utu vår matsäck; vi hafve ingen gåfvo, som vi kunne bära dem Guds mannenom: Hvad hafve vi?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Drängen svarade igen, och sade: Si, jag hafver fjerdedelen af en sikel silfver när mig; den vilje vi gifva dem Guds mannenom, att han må säga oss vår väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Fordomtid i Israel, när man gick bort till att fråga Gud, sade man: Kom, låt oss gå till Siaren; ty de som man nu kallar Propheter, dem kallade man i förtiden Siare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saul sade till sin dräng: Du hafver väl sagt; kom, låt oss gå. Och de gingo åstad till staden, der Guds mannen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Och när de komne voro upp till staden, funno de pigor, som utgångna voro till att hemta vatten; till dem sade de: Är Siaren här?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'De svarade dem, och sade: Ja, si, här är han; skynda dig, ty i dag är han kommen i staden; efter folket i dag offrar uppå höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'När I kommen i staden, så finnen I honom, förra än han uppgår på höjdena till att äta; förty folket äter icke, förra än han kommer, efter han skall välsigna offret; sedan äta de som budne äro. Derföre går ditupp, rätt nu finnen I honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Och då de kommo upp i staden, och voro midt i stadenom, si, då gick Samuel ut emot dem, och ville gå upp till höjdena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Men Herren hade uppenbarat för Samuels öron, en dag förra än Saul kom, och sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'I morgon på denna tiden skall jag sända till dig en man utu BenJamins land; den skall du smörja till en Första öfver mitt folk Israel, att han skall frälsa mitt folk ifrå de Philisteers hand; ty jag hafver sett till mitt folk, och deras rop är kommet till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Då nu Samuel fick se Saul, svarade Herren honom, och sade: Si, der är mannen, som jag dig af sagt hafver, att han skall råda öfver mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Då gick Saul fram till Samuel i porten, och sade: Säg mig, hvar är här Siarens hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel svarade Saul, och sade: Jag är Siaren, gack för mig upp på höjdena, ty I måsten i dag äta med mig; i morgon vill jag låta dig gå, och allt det i dino hjerta är, vill jag säga dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Och om åsninnorna, som du för tre dagar sedan borttappade, var nu intet bekymrad, ty de äro funna; och hvem hörer allt det goda till i Israel? Blifver det icke ditt, och hela dins faders hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul sade: Är jag icke en son af Jemini, och af det ringasta slägtet i Israel, och min ätt ringast ibland alla ätter i BenJamin? Hvi säger du då mig sådant?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Men Samuel tog Saul, och hans dräng, och hade dem upp i salen, och satte dem öfverst ibland dem som budne voro, hvilke voro vid tretio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Och Samuel sade till kocken: Få hit det stycket, som jag fick dig, och befallde att du skulle behålla det när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Då bar kocken en bog upp, och hvad dervid hängde. Och han satte den för Saul, och sade: Si, detta blef öfver, lägg för dig och ät; förty det är på denna tid till dig förvaradt, då jag böd folket. Så åt Saul med Samuel på den dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Och då de gingo neder af höjdene in i staden, talade han med Saul på taket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Och de stodo bittida upp; och som morgonrodnaden gick upp, kallade Samuel Saul uppå taket, och sade: Statt upp, att jag må låta dig gå. Och Saul stod upp, och de gingo både tillsammans ut, han och Samuel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Och då de kommo neder till ändan på staden, sade Samuel till Saul: Säg drängenom, att han går framför oss; och han gick framföre. Men du, statt nu här qvar, att jag må undervisa dig, hvad Gud hafver sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Då tog Samuel ett oljoglas, och göt uppå hans hufvud, och kysste honom, och sade: Ser du, att Herren hafver smort dig till en Första öfver hans arfvedel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'När du nu går ifrå mig, så finner du två män vid Rachels graf i BenJamins gränso i Zelzah; de skola säga till dig: Åsninnorna äro funna, der du efter gången äst, dem att söka; och si, din fader hafver öfvergifvit tänka på åsnarna, och sörjer om eder, och säger: Hvad skall jag göra om min son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Och när du går dädan fram bätter, så kommer du till den eken Thabor; der skola tre män råka dig, som gå upp till Gud i BethEl, den ene bär tre kid, den andre tre bröd, den tredje en flasko med vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Och de skola helsa dig vänliga, och gifva dig tu bröd, det skall du taga af deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Sedan kommer du på Guds hög, der de Philisteers lägre är; och när du kommer derin i staden, möta dig en hop med Propheter, som komne äro af höjdene, och för dem en psaltare, och trumma, och pipa, och harpa, och de prophetera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Och Herrans Ande skall komma öfver dig, att du propheterar med dem; och då skall du varda en annar man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'När nu dessa tecknen komma dig, så gör allt det dig för handen kommer; ty Gud är med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Men du skall gå neder för mig till Gilgal; si, der vill jag komma neder till dig, till att offra bränneoffer och tackoffer. I sju dagar skall du bida, tilldess jag kommer till dig, och undervisar dig hvad du göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Och som han vände ryggen åt Samuel, och gick ifrå honom, gaf honom Gud ett annat hjerta; och all dessa tecknen kommo på den dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Och då de kommo till högen, si, då mötte honom en hop Propheter; och Guds Ande kom öfver honom, så att han propheterade med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Då de nu alle sågo honom, som tillförene hade känt honom, att han propheterade med Propheterna, sade de till hvarannan: Hvad är Kis son tillkommet? Är ock Saul ibland Propheterna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Och en svarade der, och sade: Ho är deras fader? Dädan är det ordspråket kommet: Är ock Saul ibland Propheterna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Och då han utpropheterat hade, kom han upp till höjdena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Men Sauls faderbroder sade till honom, och till hans dräng: Hvart voren I gånge? De svarade: Till att uppsöka åsnar; och då vi såge att vi funne dem icke, komme vi till Samuel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Då sade Sauls faderbroder: Säg mig, hvad sade eder Samuel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul svarade sinom faderbroder: Han sade oss, att åsninnorna funna voro; men om Konungariket sade han honom intet, hvad Samuel sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Samuel kallade folket in till Herran i Mizpa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Och sade till Israels barn: Så säger Herren Israels Gud: Jag förde eder utur Egypten, och frälste eder utu de Egyptiers hand, och utur all Konungarikes hand som eder tvingade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Och I hafven i dag förkastat edar Gud, som eder utur all edor olycko och bedröfvelse hulpit hafver, och sägen till honom: Sätt en Konung öfver oss. Nu väl, så går nu fram för Herran efter edor slägter och hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Som nu Samuel framhade alla Israels slägter, vardt råkadt inpå BenJamins slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Och som han hade BenJamins slägt fram med hennes ätter, vardt råkadt inpå Matri ätt, och råkade inpå Saul, Kis son; och de sökte efter honom, men de funno honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Då frågade de åter Herran, om han ännu skulle ditkomma? Herren svarade: Si, han hafver undstungit sig under ett fat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Då lupo de dit, och hemtade honom. Och då han gick fram ibland folket, var han hufvudet högre än allt folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Och Samuel sade till allt folket: Här sen I, hvem Herren utvalt hafver; ty hans like är icke ibland allt folket. Då gladdes allt folket, och sade: Lycka ske Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Och Samuel sade folkena all riksens rätt, och skref det uti ena bok, och ladet inför Herran. Och Samuel lät allt folket gå, hvar och en i sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Och Saul gick ock hem till Gibea, och en del af hären gick med honom, hvilkes hjerta Gud rörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Men somlige Belials barn sade: Hvad skulle denne hjelpa oss? Och föraktade honom, och båro honom inga gåfvor; men han låts som han intet hörde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Så for Nahas, den Ammoniten, upp, och belade Jabes i Gilead. Och alle män i Jabes sade till Nahas: Gör ett förbund med oss, så vilje vi tjena dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Men Nahas, den Ammoniten, svarade dem: I så måtto vill jag göra ett förbund med eder, att jag stinger ut högra ögat på eder alla, och sätter eder till en försmädelse i hela Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Då sade till honom alle äldste i Jabes: Gif oss sju dagar, att vi måge sända bådskap i alla Israels gränsor; är då ingen hjelp, så vilje vi gå ut till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Så kommo bådskapen till Gibea Sauls, och sade detta för folkens öron. Då hof allt folket sina röst upp, och gret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Och si, då kom Saul utaf markene, gångandes bakefter sitt fä, och sade: Hvad skadar folkena, att det gråter? Då förtäljde de honom de mäns ord af Jabes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Då kom Guds Ande öfver honom, när han dessa orden hörde, och hans vrede förgrymmade sig svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Och han tog ett par oxar, och styckade dem, och sände i alla Israels gränsor med bådskap, och lät säga: Den som icke utdrager efter Saul och Samuel, hans oxar skall man så göra. Så föll Herrans fruktan öfver folket, att de utdrogo såsom en man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Och man räknade dem i Besek; och Israels barn voro tre resor hundradetusend män; och Juda barn tretiotusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Och de sade till bådskapen, som komne voro: Säger de män i Jabes i Gilead: I morgon skolen I få hjelp, när solen är som hetast. Då desse bådskapen kommo, och förkunnade det de män i Jabes, vordo de glade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Och de män i Jabes sade: I morgon vilje vi gå ut till eder, att I mågen göra oss allt det eder täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Den andra morgonen skickade Saul folket i tre hopar, och de kommo i lägret i morgonväktene, och slogo de Ammoniter allt intill dagen vardt som hetast. Och de som öfverblefvo, vordo så förskingrade, att icke två blefvo tillhopa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Då sade folket till Samuel: Hvar äro de, som sade: Skall Saul råda öfver oss? Låt de män komma här fram, att vi måge dräpa dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Saul sade: På denna dagen skall ingen dö; ty Herren hafver i dag gjort salighet i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Samuel sade till folket: Kommer, låter oss gå till Gilgal, och der förnya Konungariket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Så drog allt folket till Gilgal, och gjorde der Saul till Konung för Herranom i Gilgal, och offrade tackoffer inför Herranom. Och Saul med alla Israels män fröjdade sig der ganska storliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Då sade Samuel till hela Israel: Si, jag hafver hört edra röst uti allt det I mig sagt hafven, och hafver gjort en Konung öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Och si, der går nu edar Konung för eder; men jag är gammal och grå vorden, och mine söner äro när eder, och jag hafver gångit för eder, ifrå min ungdom allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Si, här är jag: Svarer mig inför Herranom och hans smorda, om jag någons mans oxa eller åsna tagit hafver? Om jag hafver någrom gjort öfvervåld och orätt? Om jag någon undertryckt hafver? Om jag af någons mans hand hafver tagit gåfvor, och hållit det hemliga? Så vill jag gifva eder det igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'De sade: Du hafver intet öfvervåld eller orätt gjort oss, ej heller någon undertryckt; ej heller af någons mans hand något tagit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Han sade till dem: Herren och hans smorde vare vittne emot eder i dag, att i intet hafven funnit i mine hand. De sade: Ja, vare vittne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Och Samuel sade till folket: Ja, Herren, som Mose och Aaron gjort hafver, och förde edra fäder utur Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Så går nu fram, att jag må döma eder för Herranom, öfver all Herrans rättfärdighet, som han med eder och edra fäder gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Då Jacob var kommen in uti Egypten, ropade edra fäder till Herran. Och Herren sände Mose och Aaron, att de skulle föra edra fäder utur Egypten, och lät bo dem på detta rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Men när de förgåto Herran sin Gud, sålde han dem under Sisera våld, höfvitsmansens i Hazor, och uti de Philisteers våld, och uti de Moabiters Konungs våld; de stridde emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Och de ropade till Herran, och sade: Vi hafve syndat, att vi hafve öfvergifvit Herran, och tjent Baalim och Astaroth; men frälsa oss nu ifrå våra fiendars hand, så vilje vi tjena dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Då sände Herren JerubBaal, Bedan, Jephthah och Samuel, och frälste eder utur edra fiendars händer, allt omkring, och lät eder bo tryggeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'När I då sågen att Nahas, Ammons barnas Konung, Kom emot eder, saden I till mig: Icke du, utan en Konung skall råda öfver oss; ändock Herren edar Gud var edar Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Nu, här hafven I edar Konung, den I utvalt och begärat hafven; ty, si, Herren hafver satt en Konung öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Om I nu frukten Herran, och tjenen honom, och hören hans röst, och icke ären Herrans mun ohörige, så skolen både I och edar Konung, som öfver eder råder, efterfölja Herran edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Om I icke hören Herrans röst, utan ären Herrans mun ohörige, så skall Herrans hand vara emot eder och edra fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Går också nu fram, och ser det stora ärende, som Herren göra skall för edor ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Är icke nu hveteanden? Dock vill jag åkalla Herran, att han skall låta dundra och regna, att I skolen förnimma och se det stora onda, som I för Herrans ögon gjort hafven, att I hafven bedts eder Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Och då Samuel åkallade Herran, lät Herren den samma dagen dundra och regna; då fruktade allt folket Herran och Samuel ganska storliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Och sade alle till Samuel: Bed för dina tjenare Herran din Gud, att vi icke dö; ty öfver alla våra synder hafve vi ock gjort detta onda, att vi beddes oss Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Och Samuel sade till folket: Frukter eder intet, I hafven sannerliga gjort allt det onda; dock träder icke af ifrå Herranom, utan tjener Herranom af allo hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Och viker icke efter fåfängelig ting; ty det gagnar eder intet, och kan intet hjelpa eder, efter det en fåfängelig ting är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Förty Herren öfvergifver icke sitt folk, för sitt stora Namns skull; ty Herren hafver begynt till att göra eder sig sjelfvom till ett folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Vare ock fjerran ifrå mig, att jag så skulle synda emot Herran, att jag skulle aflåta bedja för eder, och lära eder den goda och rätta vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Allenast frukter Herran, och tjener honom troliga af allo hjerta; förty I hafven sett huru stor ting han gör med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Men om I gören det ondt är, så skolen både I och edar Konung förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul hade varit Konung ett år; och som han tu år hade rådit öfver Israel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Utvalde han sig tretusend män utur Israel; tutusend voro med Saul i Michmas, och uppå berget BethEl, och ett tusend med Jonathan i Gibea BenJamins; men det andra folket lät han gå, hvar och en i sina hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Och Jonathan slog de Philisteer i deras lägre, som i Gibea var; det kom för de Philisteer. Och Saul lät blåsa i basunen öfver hela landet, och säga: I Ebreer, hörer till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Och hela Israel hörde sägas: Saul hafver slagit de Philisteers lägre; ty Israel luktade illa för de Philisteer, och allt folket ropades till Saul i Gilgal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Då församlade sig de Philisteer till att strida med Israel, tretiotusend vagnar, sextusend resenärer, och eljest folk så mycket som sanden i hafsstrandene; och de drogo upp, och lägrade sig i Michmas, östan för BethAven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Då de män af Israel sågo, att de i nöd voro, ty folket var förskräckt, krupo de uti kulor, och klyfter, och klippor, och i hål, och i gropar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Och de Ebreer drogo öfver Jordan in uti Gads land och Gileads; men Saul var ännu i Gilgal, och allt folket, som följde honom, vardt förtvifladt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Då förbidde han i sju dagar, den tiden som Samuel förelagt hade; och efter Samuel icke kom till Gilgal, skingrade sig folket ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Då sade Saul: Bärer mig hit bränneoffer och tackoffer; och han offrade bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Och som han hade fullkomnat bränneoffret, si, då kom Samuel; då gick Saul ut emot honom, till att helsa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Men Samuel sade: Hvad hafver du gjort? Saul svarade: Jag såg att folket förskingrade sig ifrå mig, och du kom icke i rättom tid, och de Philisteer voro församlade i Michmas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Då sade jag: Nu komma de Philisteer hitneder till mig i Gilgal, och jag hafver icke bedit Herrans ansigte; då vågade jag det, och offrade bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Men Samuel sade till Saul: Du hafver gjort dårliga, och icke hållit Herrans dins Guds bud, som han dig budit hafver; ty Herren hade stadfäst ditt rike öfver Israel till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Men nu skall ditt rike icke blifva ståndandes. Herren hafver sökt sig en man efter sitt hjerta, honom hafver Herren budit att vara en Förste öfver hans folk; ty du hafver icke hållit Herrans bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Och Samuel stod upp, och gick ifrå Gilgal upp till Gibea BenJamins. Men Saul talde det folk, som när honom var, vid sexhundrad män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Och Saul med hans son Jonathan, och det folk som när honom var, blefvo uppå BenJamins hög; men de Philisteer hade lägrat sig i Michmas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Och utu de Philisteers lägre drogo tre hopar till att förhärja landet. Den ene vände sig inpå den vägen till Ophra uti Sauls land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'Den andre vände sig inpå den vägen till BethHoron; den tredje vände sig på den vägen, som drager åt den dalen Zeboim vid öknena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Och ingen smed vardt funnen i hela Israels land; förty de Philisteer tänkte, de Ebreer måtte göra svärd och spjut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Ty måste hela Israel fara neder till de Philisteer, om någor ville låta hvässa sin plogbill, hacko, yxa eller lia;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Och när eggen på liarna, hackorna, gafflarna och yxarna, vardt slö, och uddarna vordo stubbote.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Då nu stridsdagen kom, vardt intet svärd eller spjut funnet i hela folkens hand, som var med Saul och Jonathan; utan Saul och hans son hade värjor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Och de Philisteers lägre drog fram vid Michmas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Det begaf sig i den tiden, att Jonathan, Sauls son, sade till sin dräng, som hans värjo bar: Kom, låt oss gå utöfver till de Philisteers lägre, som deruppe är; och han sade sinom fader intet till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Men Saul blef ytterst i Gibea under ett granatträ, som i förstadenom var; och det folk, som när honom var, var vid sexhundrad män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Och Ahia, Achitobs son, Icabods broders, Pinehas sons, Eli sons, var Herrans Prest i Silo, och drog lifkjortelen uppå; folket visste icke heller, att Jonathan var bortgången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Och i vägenom, der Jonathan sökte efter att gå öfver till de Philisteers lägre, voro två branta klippor, den ena på denna sidone, och den andra på hinsidone; den ena het Bozez, den andra Sene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Och den ena var norrut ifrå Michmas, och den andra var söderut ifrå Gaba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Och Jonathan sade till sin vapnedragare: Kom, låt oss gå utöfver till dessa oomskornas lägre; tilläfventyrs varder Herren något uträttandes genom oss; förty det är icke Herranom tungt hjelpa genom många, eller genom få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Då svarade honom hans vapnedragare: Gör allt det i dino hjerta är; gack åstad, si, jag är med dig såsom ditt hjerta vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonathan sade: Nu väl, när vi komme ditöfver till det folket, och de få se oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Om de då säga: Står qvare, tilldess vi komme till eder; så vilje vi blifva ståndande i vårt rum, och icke stiga upp till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Men om de säga: Kommer hitupp till oss; så vilje vi stiga upp till dem; så hafver Herren gifvit dem oss i våra händer; och det skall oss vara för ett tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Då nu de Philisteers lägre fingo se dem båda, sade de Philisteer: Si, de Ebreer äro utkrupne utu hålen, der de sig gömt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Och männerna i lägret svarade Jonathan och hans vapnedragare, och sade: Kommer hitupp till oss, vi vilje väl lära eder. Då sade Jonathan till sin vapnedragare: Träd efter mig, Herren hafver gifvit dem i Israels händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Och Jonathan klef med händer och fötter uppföre, och hans vapnedragare efter honom. Då föllo de neder för Jonathan, och hans vapnedragare slog allt ihjäl efter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Så att första slagtningen, som Jonathan och hans vapnedragare gjorde, var vid tjugu män, på en halfvan åker vid pass, som ett par oxars dagsplöjning är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Och en rädsel kom på markene i lägret, och på hela folket i lägrena; och de som utsände voro till att förhärja, dem kom ock rädsel uppå, och landet skalf dervid; ty det var en förskräckelse af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Och Sauls väktare i Gibea BenJamins fingo se, att hopen skingrades, och lupo hit och dit, och vordo slagne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Saul sade till folket, som när honom var: Räkner, och ser till, hvilken af oss är bortgången; och då de räknade, si, då var Jonathan och hans vapnedragare icke der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Då sade Saul till Ahia: Bär fram Guds ark; ty Guds ark var på den tiden när Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Och som Saul ännu talade med Prestenom, förökade sig sorlet och löpandet uti de Philisteers lägre. Och Saul sade till Presten: Tag dina hand af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Och Saul ropade, och allt folket, som med honom var, och kommo i stridena; och si, då gick hvars och ens svärd emot den andra, och var ett mägta sorl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Och de Ebreer, som tillförene hade varit när de Philisteer, och hade varit uppdragne med dem i lägret allt omkring, gåfvo sig intill Israel, som voro med Saul och Jonathan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Och alle män af Israel, som sig förgömt hade på Ephraims berg, då de hörde att de Philisteer flydde, följde de efter med de andra till stridena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Alltså halp då Herren Israel på den tiden, och slaget stod allt intill BethAven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Och då Israels män försmäktade på den dagen, besvor Saul folket, och sade: Förbannad vare hvar och en, som bröd äter intill aftonen, att jag må hämnas på mina fiendar. Så smakade ock allt folket intet bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Och hela landet kom i skogen, och der låg hannog på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Då folket kom in i skogen, si, då flöt der hannog; men ingen lät honom med handene komma till sin mun; ty folket fruktade sig för eden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Men Jonathan hade icke hört, att hans fader hade besvorit folket; och räckte sin staf ut, som han hade i sine hand, och doppade med ändanom i hannogskakona, och vände sina hand till sin mun; så vordo hans ögon frisk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Då svarade en af folkena, och sade: Din fader hafver besvorit folket, och sagt: Förbannad vare hvar och en, som något äter i dag. Och folket var förtröttadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Då sade Jonathan: Min fader hafver bedröfvat landet; ser, huru min ögon äro frisk vordne deraf, att jag af denna hannogen något litet smakat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Hade folket i dag ätit af sina fiendars rof, som de funnit hafva, så hade ock slagtningen vordit större emot de Philisteer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Och de slogo på den dagen de Philisteer, ifrå Michmas allt intill Ajalon; och folket vardt ganska trött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Och folket vände sig till bytet, och togo får, fä och kalfvar, och slagtade på jordene, och åto det med blodet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Så vardt Saul förkunnadt: Si, folket hafver syndat emot Herran, och ätit blod. Han sade: I hafven illa gjort; välter hit till mig en stor sten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Och Saul sade ytterligare: Går ut ibland folket, och säger dem, att hvar och en hafve sin oxa och sitt får till mig, och slagter det här, att I mågen äta, och icke synda emot Herranom med det blodätandet. Så drog allt folket fram, hvar och en sin oxa i sine hand, om nattena, och slagtade det der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Och Saul byggde Herranom ett altare; det är det första altare, som han byggde Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Och Saul sade: Låt oss draga ned efter de Philisteer i natt, och beröfva dem, tilldess i morgon ljust varder, att vi ingen af dem låte öfverblifva. De svarade: Gör allt det dig täckes. Men Presten sade: Låt oss gå hit till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Och Saul frågade Gud: Skall jag draga ned efter de Philisteer, och vill du gifva dem uti Israels händer? Men han svarade honom på den tiden intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Då sade Saul: Låt gå hitfram all hörn af folket; och förfarer, och tillser, när hvilkom denna synden är på denna tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Ty så visst som Herren Israels hjelpare lefver, om det än vore min son Jonathan, så skall han dö. Och ingen svarade honom utaf hela folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Och han sade till hela Israel: Varer I på den sidon; jag och min son Jonathan vilje vara på desso sidone. Folket sade till Saul: Gör hvad dig täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Och Saul sade till Herran Israels Gud: Gör det rätt är. Då råkade det på Jonathan och Saul; och folket gick qvitt ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Saul sade: Kaster öfver mig och min son Jonathan. Då råkade det på Jonathan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Och Saul sade till Jonathan: Säg mig, hvad hafver du gjort? Jonathan lät honom förståt, och sade: Jag smakade litet hannog med stafven, som jag i mine hand hade; och si, derföre måste jag dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Då sade Saul: Gud göre mig det och det; Jonathan, du måste döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Men folket sade till Saul: Skulle Jonathan dö, den en så stor salighet gjort hafver i Israel? Bort det! Så visst som Herren lefver, icke ett hår af hans hufvud skall falla på jordena; förty Gud hafver i dag gjort det igenom honom. Alltså friade folket Jonathan, att han icke dö måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Så drog Saul upp ifrå de Philisteer; och de Philisteer drogo till sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Men då Saul hade tagit riket in öfver Israel, stridde han emot alla sina fiendar allt omkring; emot de Moabiter, emot Ammons barn, emot de Edomeer, emot Zoba Konungar, emot de Philisteer; och hvart han vände sig, der straffade han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Och han församlade en här, och slog de Amalekiter; och friade Israel ifrån allas deras hand, som dem förtryckte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Och Saul hade söner, Jonathan, Isvi, MalchiSua. Och hans två döttrar heto alltså: den förstfödda Merob, och den yngsta Michal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Och Sauls hustru het Ahinoam, Ahimaaz dotter; och hans härhöfvitsman het Abner, Ners son, Sauls faderbroders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Men Kis var Sauls fader, och Ner, Abners fader, var Abiels son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Och ett mägtigt örlig var emot de Philisteer, så länge Saul lefde; och hvar Saul såg en doglig och stridsam man, den tog han till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Men Samuel sade till Saul: Herren sände mig, att jag skulle smörja dig till Konung öfver hans folk Israel; så hör nu röstena af Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Så säger Herren Zebaoth: Jag hafver tänkt uppå hvad Amalek gjorde Israel, och huru han låg i vägen för honom, då han drog utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Så drag nu åstad, och slå de Amalekiter, och gif dem tillspillo med allt det de hafva; skona dem intet, utan dräp både man och qvinno, barn, och dem som dia, fä och får, camel och åsna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul lät detta komma för folket, och talde dem i Telaim, tuhundradtusend fotfolk, och tiotusend män af Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Och då Saul kom till de Amalekiters stad, satte han ett bakhåll vid bäcken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Och lät säga de Keniter: Går edra färde, och gifver eder ifrå de Amalekiter, att jag icke utrotar eder med dem; förty I gjorden barmhertighet med all Israels barn, då de drogo utur Egypten. Alltså gåfvo de Keniter sig ifrå de Amalekiter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Då slog Saul de Amalekiter, allt ifrå Hevila intill Sur, som ligger för Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Och grep Agag, de Amalekiters Konung, lefvande; och allt folket gaf han tillspillo med svärdsegg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Men Saul och folket skonade Agag, och hvad god får och fä var, och väl fett, och lamb, och allt det godt var, och ville icke låtat tillspillo; men det som slemt var, och intet dogde, det läto de tillspillo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Då skedde Herrans ord till Samuel, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Mig ångrar, att jag hafver gjort Saul till Konung; ty han hafver vändt sig ifrå mig, och icke fullkomnat min ord. Dess vardt Samuel vred; och ropade till Herran den hela nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Och Samuel stod bittida upp, att han skulle om morgonen möta Saul; och honom vardt sagdt, att Saul var kommen till Carmel, och reste sig upp ett segertecken, och var omkringdragen, och kommen neder till Gilgal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Som nu Samuel kom till Saul, sade Saul till honom: Välsignad vare du Herranom! Jag hafver fullkomnat Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel svarade: Hvad är då det rop af får i min öron, och det rop af fä, som jag hörer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul sade: Utaf de Amalekiter hafva de tagit det; förty folket skonade det bästa får och fä, för Herrans dins Guds offers skull; det andra hafve vi låtit tillspillo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Men Samuel svarade Saul: Städ till, att jag säger dig, hvad Herren hafver talat med mig i denna natt. Han sade: Säg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel sade: Är det icke så, då du liten vast för din ögon, vardt du ett hufvud i Israels slägter, och Herren smorde dig till Konung öfver Israel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Och Herren sände dig på vägen, och sade: Far bort, och förgör de syndare, de Amalekiter, och strid emot dem, tilldess du gör en ända på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Hvi hafver du icke lydt Herrans röst; utan vändt dig till rof, och illa handlat inför Herrans ögon?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Då sade Saul till Samuel: Hafver jag dock lydt Herrans röst, och hafver dragit den vägen, som Herren mig sändt hafver; jag hafver fört hit Agag, de Amalekiters Konung, och förgjort de Amalekiter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Men folket hafver tagit af rofvet får och fä, det bästa af de spillgifno, till att offra det Herranom dinom Gud i Gilgal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Men Samuel sade: Menar du att Herren hafver lust till offer och bränneoffer, såsom dertill, att man lyder Herrans röst? Si, lydnad är bättre än offer, och höra till är bättre än det feta af vädrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Förty olydnad är en trolldomssynd, och gensträfvighet är ett afguderi och afgudadyrkan; så, efter du hafver förkastat Herrans ord, hafver han ock förkastat dig; att du icke skall vara Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Då sade Saul till Samuel: Jag hafver syndat, att jag hafver öfvergångit Herrans befallning och din ord; ty jag fruktade folket, och hörde deras röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Och nu förlåt mig den synden, och vänd tillbaka med mig, att jag må tillbedja Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel sade till Saul: Jag vänder intet om med dig; ty du hafver förkastat Herrans ord, och Herren hafver ock förkastat dig, att du icke skall vara Konung öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Och som Samuel vände sig om, till att gå sina färde, fattade han honom i hans kjortels flik, och hon refs sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Då sade Samuel till honom: Herren hafver i denna dag rifvit Israels Konungarike ifrå dig, och gifvit dinom nästa, den bättre är än du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Ljuger icke heller Hjelten i Israel, eller låter sig ångra; ty han är ingen menniska, att han sig något ångra låter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Men han sade: Jag hafver syndat; så gör mig dock du den ärona inför de äldsta af mitt folk, och för Israel, och vänd om med mig, att jag må tillbedja Herran din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Så vände då Samuel om, och följde Saul, så att Saul tillbad Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Och Samuel sade: Låt komma fram för mig Agag, de Amalekiters Konung; och Agag gick dristeliga fram till honom. Och Agag sade: Alltså måste man fördrifva dödsens bitterhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel sade: Såsom ditt svärd hafver gjort qvinnor barnlös, så skall ock din moder blifva barnlös ibland qvinnor. Så högg Samuel Agag i stycker inför Herranom i Gilgal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Och Samuel gick bort till Ramath; men Saul drog upp till sitt hus i Gibea Sauls.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Och Samuel såg Saul intet mer intilldess han blef död; dock likväl sörjde Samuel för Sauls skull, att Herren hade ångrat sig, att han hade gjort honom till Konung öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Och Herren sade till Samuel: Huru länge vill du sörja för Sauls skull, den jag förkastat hafver, så att han icke skall vara Konung öfver Israel? Uppfyll ditt horn med oljo, och gack åstad; jag vill sända dig till den BethLehemiten Isai; förty af hans söner hafver jag försett mig en Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel sade: Huru skulle jag gå dit? Saul får det veta, och slår mig ihjäl. Herren sade: Tag en kalf af fät till dig, och säg: Jag är kommen till att offra Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Och du skall kalla Isai till offret; då vill jag visa dig hvad du göra skall, att du der smörjer den jag dig säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel gjorde såsom Herren honom sagt hade, och kom till BethLehem; då förskräcktes de äldste i stadenom, och gingo emot honom, och sade: Är det frid, medan du kommer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Han sade: Ja, jag är kommen till att offra Herranom; helger eder, och kommer med mig till offret. Och han helgade Isai och hans söner, och böd dem till offret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Då de nu kommo in, såg han på Eliab, och tänkte: Visst är för Herranom här hans smorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Men Herren sade till Samuel: Se intet på hans skapnad, eller hans stora person; jag hafver förkastat honom, förty det går icke efter som en menniska ser. En menniska ser det för ögonen är, men Herren ser till hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Då kallade Isai AbiNadab, och lät honom gå fram för Samuel; och han sade: Denna hafver Herren ock intet utvalt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Då lät Isai gå fram Samma; men han sade: Denna hafver Herren ock intet utvalt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Då lät Isai gå sina sju söner fram för Samuel; men Samuel sade till Isai: Herren hafver ingen af dem utvalt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Och Samuel sade till Isai: Äro nu här piltarna? Han sade: Det är ännu en den minste igen, och si, han vaktar får. Då sade Samuel till Isai: Sänd bort, och låt hemta honom; ty vi skole icke sätta oss, förra än han kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Då sände han åstad, och lät hemta honom. Och han var brunaktig, med fager ögon och dägelig skapnad. Och Herren sade: Upp, och smörj honom; den är det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Då tog Samuel sitt oljohorn, och smorde honom midt ibland hans bröder. Och Herrans Ande kom öfver David, ifrå den dagen, och allt sedan; och Samuel stod upp, och gick till Ramath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Och Herrans Ande vek ifrå Saul, och en ond ande af Herranom qvalde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Då sade Sauls tjenare till honom: Si, en ond ande af Gudi qväl dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Vår herre säge sina tjenare som för honom stå, att de söka en man, som kan på harpo och strängaspel; på det att, när den onde Guds anden kommer öfver dig, må han spela med sine hand, att det må varda bättre med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Då sade Saul till sina tjenare: Ser efter en man, som är god på strängaspel, och hafver honom hit till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Då svarade en af tjenarena, och sade: Si, jag hafver sett en Isai son, den BethLehemitens; han kan på strängaspel, en dogelig man, och stridsam, och förståndig i saker, och dägelig, och Herren är med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Då sände Saul båd till Isai, och lät säga honom: Sänd din son David till mig, som är med fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Så tog Isai en åsna, med bröd, och en lägel vin, och ett kid af getterna, och sände till Saul med sinom son David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Så kom David till Saul, och gick fram för honom; och han vardt honom ganska kär, och blef hans vapnedragare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Och Saul sände till Isai, och lät säga honom: Låt David blifva inför mig; ty han hafver funnit ynnest för min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'När nu den Guds anden kom öfver Saul, så tog David harpona, och spelade med sine hand; så kom Saul till sig igen, och det vardt bättre med honom, och den onde anden vek ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'De Philisteer församlade sina härar till strid, och kommo tillhopa i Socho i Juda, och lägrade sig emellan Socho och Aseka, vid ändan af Dammin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Men Saul och Israels män komma tillhopa, och lägrade sig i ekdalenom, och skickade sig till strid emot de Philisteer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Och de Philisteer stodo på ett berg på hinsidon, och de Israeliter på ett berg på denna sidone, så att en del var emellan dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Då kom framträdandes utu de Philisteers lägre en man, en kämpe, benämnd Goliath af Gath, sex alnar och en tvärhand lång;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Och hade en kopparhjelm på sitt hufvud, och ett fjällpansar uppå; och vigten på pansaret var femtusend siklar koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Och hade kopparbenvapen uppå sin ben, och en kopparsköld på sina axlar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Och skaftet på hans spjut var såsom ett väfträ, och jernet på hans spjut höll sexhundrad siklar jern; och hans vapnedragare gick framför honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Och han stod och ropade till Israels slagorden, och sade till dem: Hvi ären I utdragne till att skicka eder till strid? Är icke jag en Philisteer, och I ären Sauls tjenare? Väljer en ut af eder, som går hitneder till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Kan han strida emot mig, och slår mig, så vilje vi vara edra tjenare; varder ock jag hans öfverman, och slår honom, så skolen I vara våra tjenare, och skolen tjena oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Och Philisteen sade: Jag hafver i denna dag gjort Israels här en skam; låter mig få en, och låter oss strida med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Då Saul och hela Israel hörde dessa Philisteens ord, förskräckte de sig, och fruktade sig storliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Men David var en Ephratisk mans son, af BethLehem Juda, som het Isai; han hade åtta söner, och var en gammal man i Sauls tid, och var ålderstigen ibland män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Och de tre äldste Isai söner voro dragne med Saul till stridena; och var detta deras namn: Eliab den förstfödde, AbiNadab den andre, och Samma den tredje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Men David var den yngste. Då nu de tre äldste voro utdragne med Saul till stridena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Gick David åter hem ifrå Saul, till att vakta sins faders får i BethLehem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Men den Philisteen trädde fram både morgon och afton, och stod der i fyratio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Och Isai sade till sin son David: Tag åt dina bröder detta epha af torkad ax, och dessa tio bröd, och löp bort i hären till dina bröder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Och dessa tio blöta ostar, och få höfvitsmannenom; och besök dina bröder, om dem väl går, och tag vara uppå hvad de säga dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Men Saul, och de, och alle Israels män voro i ekdalenom, och stridde emot de Philisteer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Då stod David bittida upp om morgonen, och befallde fåren herdanom; lade uppå sig, och gick åstad, såsom Isai honom budit hade, och kom till vagnborgena; och hären var utdragen, och hade skickat sig, och de skriade i stridene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Ty Israel hade skickat sig; så voro ock de Philisteer redo emot deras här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Då lät David det han bar i tygvaktarens händer, och lopp bort i spetsen, och gick bort och helsade sina bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Och vid han nu talade med dem, si, då trädde den kämpen fram, som het Goliath, den Philisteen af Gath, utu de Philisteers här, och talade såsom tillförene; och David hörde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Men hvar man i Israel, då han den mannen såg, flydde för honom, och fruktade sig storliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Och hvar man i Israel sade: Hafven I icke sett denna mannen, som uppgången är? Ty han är uppgången till att tala försmädelse emot Israel; och den honom slår, honom vill Konungen göra mycket rik, och gifva honom sina dotter; och vill göra hans faders hus fritt i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Då sade David till männerna, som när honom stodo: Hvad skall man gifva honom, som slår denna Philisteen, och vänder denna skammen ifrån Israel? Ty hvad är denna oomskorne Philisteen, som försmäder lefvandes Guds här?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Då sade folket honom såsom tillförene: Det skall man gifva honom, som honom slår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Och Eliab hans äldste broder hörde att han talade med männerna, och vardt vred på David, och sade: Hvi äst du hitneder kommen? Och hvi hafver du öfvergifvit de få fåren i öknene? Jag känner väl dina öfverdådighet, och dins hjertas ondsko; ty du äst hitned kommen till att se stridena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'David sade: Hvad hafver jag då nu gjort? Är det mig icke befaldt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Och vände sig om till en annan, och sade såsom han hade sagt tillförene; då svarade honom folket såsom tillförene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Och då de hörde de ord, som David sade, förkunnade de det Saul; och han lät hemta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Och David sade till Saul: Ingens mans hjerta gifve sig för den sakens skull; din tjenare skall gå bort, och strida med Philisteen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul sade till David: Du kan icke gå bort emot denna Philisteen, och strida med honom; ty du äst en yngling, och han är en stridsman ifrå hans ungdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Men David sade till Saul: Din tjenare vaktade sins faders får, och då der kom ett lejon och en björn, och tog bort ett får af hjorden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Då följde han efter, och slog honom, och tog det utu hans mun; och då han reste sig upp emot mig, tog jag honom i skägget, och slog honom, och drap honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Så hafver din tjenare slagit både lejon och björn. Så må nu denne oomskorne Philisteen vara såsom endera; ty han hafver försmädat lefvandes Guds här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Och David sade: Herren, som mig frälste ifrå lejonet, och ifrå björnen, han frälsar mig ock ifrå denna Philisteen. Och Saul sade till David: Gack åstad, Herren vare med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Och Saul drog sin kläder uppå David, och satte honom en kopparhjelm på hans hufvud, och lade ett pansar uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Och David band sitt svärd öfver sin kläder, och begynte till att gå; ty han hade icke försökt det. Då sade David till Saul: Jag kan icke så gå; ty jag är det icke van. Och han lade det ifrå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Och tog sin staf i sina hand, och utvalde fem släta stenar utu bäcken, och lade dem uti herdaskräppona, som han hade, och i säcken, och tog slungona i sina hand, och gick fram emot Philisteen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Och Philisteen gick ock framåt, och nalkades intill David, och hans vapnedragare för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Då nu Philisteen såg och skådade David, föraktade han honom; ty han var en yngling, brunaktig och dägelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Philisteen sade till David: Är jag då en hund, att du kommer emot mig med käppar? Och bannade David vid sina gudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Och sade till David: Kom hit till mig, jag skall gifva ditt kött foglom under himmelen och djurom på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'David sade till Philisteen: Du kommer till mig med svärd, spjut och sköld; men jag kommer till dig i Herrans Zebaoths Namn, Israels härs Guds, den du försmädat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Och Herren skall i denna dag gifva dig uti mina hand, att jag skall slå dig, och taga ditt hufvud af dig, och gifva de Philisteers härs kropp i denna dag foglom under himmelen, och djurom på markene, att all land skola förnimma, att Israel hafver en Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Och all denna menigheten skall förnimma, att Herren icke hjelper genom svärd eller spjut; ty striden är Herrans, och han skall gifva eder i våra händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Då nu Philisteen reste åstad, gick och nalkades in mot David, skyndade sig David, och lopp ifrå hären emot Philisteen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Och David tog sina hand i skräppona, och fattade derut en sten, och slungade, och råkade Philisteen i hans panno, så att stenen gick in i pannona; och han föll på jordena på sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Alltså öfvervann David Philisteen med slungone och stenenom, och slog honom, och drap honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Och efter David intet svärd hade i sine hand, lopp han fram till Philisteen, och tog hans svärd, och drog det utu skidone, och drap honom; och högg honom dermed hufvudet af. Då de Philisteer sågo, att deras starkaste var död, flydde de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Och Israels män och Juda reste upp, ropade och jagade efter de Philisteer, intilldess man kommer i dalen, och allt intill Ekrons portar; och de Philisteer föllo slagne på vägenom till portarna, allt intill Gath, och intill Ekron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Och Israels barn vände om af det jagandet efter de Philisteer, och skinnade deras lägre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Men David tog Philisteens hufvud, och förde det till Jerusalem; men hans vapen lade han i sina hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Men då Saul såg David utgå emot Philisteen, sade han till Abner sin härhöfvitsman: Hvars son är den ynglingen? Abner sade: Så visst som din själ lefver, Konung jag vet det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Konungen sade: Så fråga derefter, hvars son den ynglingen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Då nu David kom igen, sedan Philisteen slagen var, tog Abner honom, och hade honom in för Saul; och han hade den Philisteens hufvud i sine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Och Saul sade till honom: Hvars son äst du, yngling? David sade: Jag är dins tjenares Isai den BethLehemitens son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Då han hade uttalat med Saul, förband sig Jonathans hjerta med Davids hjerta; och Jonathan vardt kär åt honom, såsom sitt eget hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Och Saul tog honom i den dagen, och lät honom icke mer komma i sins faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Och Jonathan och David gjorde ett förbund tillhopa; ty han hade honom kär, såsom sitt eget hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Och Jonathan drog af sin kjortel, som han hade uppå, och gaf honom David; dertill sin mantel, sitt svärd, sin båga och sitt bälte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Och David gick ut, dit Saul sände honom, och skickade sig visliga; och Saul satte honom öfver krigsfolket, och han var allo folkena, och desslikes Sauls tjenarom, täcker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Men det begaf sig, då han igenkommen var, sedan han hade slagit Philisteen, att qvinnorna af alla Israels städer gingo emot Konung Saul med sång och harpor, med trummor, med glädje, och med gigor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Och qvinnorna söngo till hvarandra, och spelade, och sade: Saul hafver slagit tusende; men David tiotusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Då förgrymmade sig Saul storliga, och det talet behagade honom ganska illa, och sade: De hafva gifvit David tiotusend, och mig tusende; han varder väl ännu Konung?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Och Saul såg illa uppå David, ifrå den dagen, och allt sedan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'På den andra dagen föll den onde anden af Gudi öfver Saul, och han propheterade hemma i huset; men David spelade på strängerna med sine hand, såsom han dageliga plägade. Och Saul hade ett spjut i handene:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Och sköt det åstad, och tänkte: Jag vill skjuta David igenom i väggena; men David gaf sig undan för honom i två gånger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Och Saul fruktade för David; ty Herren var med honom, och var gången ifrå Saul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Så satte Saul honom ifrå sig, och gjorde honom till höfvitsman öfver tusende män; och han gick ut och in för folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Och David hade sig förnumsteliga i alla sina gerningar; och Herren var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Då nu Saul såg, att han var så ganska förnumstig, fruktade han för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Men hela Israel och Juda hade David kär; ty han gick ut och in för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Och Saul sade till David: Si, min äldsta dotter Merob vill jag gifva dig till hustru; var manlig, och för Herrans krig; ty Saul tänkte, min hand skall icke komma vid honom, utan de Philisteers hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Men David svarade Saul: Ho är jag? Eller hvad är mitt lefverne, och mins faders hus slägt i Israel, att jag skulle varda Konungens måg?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Då nu tiden kom, att Merob, Sauls dotter, skulle vordit gifven David, vardt hon gifven Adriel den Meholathiten till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Men Michal, Sauls dotter, hade David kär. Då det vardt sagdt Saul, sade han: Det är rätt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Jag vill gifva honom henne, att hon må komma honom på fall, och de Philisteers händer måga komma öfver honom. Och han sade till David: Du skall i dag varda min måg med den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Och Saul böd sina tjenare: Taler vid David hemliga, och säger: Si, Konungen hafver vilja till dig, och alla hans tjenare älska dig; så blif nu Konungens måg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Och Sauls tjenare talade dessa orden för Davids öron; men David sade: Tycker eder det vara en ringa ting, att vara Konungens måg? Och jag är en fattig och ringa man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Och Sauls tjenare gåfvo honom svar igen, och sade: Sådana ord hafver David sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Saul sade: Säger så till David: Konungen begärar ingen morgongåfvo, annan än hundrade förhudar af de Philisteer, att man må hämnas på Konungens fiendar; ty Saul for efter att fälla David genom de Philisteers hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Då sade hans tjenare David dessa orden. Och David tyckte så godt vara, att han måtte blifva Konungens måg. Och tiden var ännu icke ute.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Och David stod upp, och drog åstad med sina män, och slog af de Philisteer tuhundrad män; och David hade deras förhudar, och förnöjde Konungen med talet; på det han skulle varda Konungens måg. Då gaf Saul honom sina dotter Michal till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Och Saul såg och märkte, att Herren var med honom. Och Michal, Sauls dotter, hade honom kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Då fruktade Saul ännu mer för David, och vardt hans fiende i alla sina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Och då de Philisteers Förstar drogo ut, handlade David förnumsteligare än alle Sauls tjenare, när de utdrogo, så att hans namn vardt mycket aktadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Men Saul talade med sin son Jonathan, och med alla sina tjenare, att de skulle slå David ihjäl. Men Jonathan, Sauls son, hade stor vilja till David;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Och underviste honom det, och sade: Min fader Saul far efter, och vill dräpa dig; så förvara dig nu till morgons, och blif öfver en sido, och göm dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Men jag vill gå ut med min fader, och vill stå bredevid min fader på markene, der du äst, och tala om dig med min fader; och hvad jag ser, det vill jag kungöra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Och Jonathan talade det bästa om David med sinom fader Saul, och sade till honom: Konungen synde icke på sin tjenare David; ty han hafver intet brutit dig emot, och hans gerningar äro dig ganska nyttiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Och han hafver satt sitt lif i sina hand, och slog den Philisteen, och Herren gjorde en stor salighet helo Israel; det hafver du sett, och gladt dig deraf; hvi vill du då synda på ett oskyldigt blod, så att du dräper David utan sak?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Då lydde Saul Jonathans röst, och svor: Så visst som Herren lefver, skall han icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Då kallade Jonathan David, och sade honom alla dessa orden; och hade honom in för Saul, att han var för honom, såsom tillförene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Så kom åter ett örlig; och David drog ut, och stridde emot de Philisteer, och slog en stor slagtning; så att de flydde för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Men den onde Herrans ande kom öfver Saul, och han satt i sitt hus, och hade ett spjut i sine hand; så spelade David på strängerna med handene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Men Saul for efter att skjuta David igenom med spjutet i väggena; men han vek undan ifrå Saul, och spjutet for in i väggena; och David flydde, och undslapp i den nattene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Och Saul sände båd i Davids hus, att de skulle taga vara uppå honom, och om morgonen slå honom ihjäl; men Michal, Davids hustru, underviste det honom, och sade: Om du i natt icke undsätter dina själ, så måste du i morgon dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Så lät Michal honom neder genom ett fenster; och han gick sina färde, flydde, och undslapp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Och Michal tog ett beläte, och lade det i sängena; och lade ett getskinn om dess hufvud, och öfvertäckte det med kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Då sände Saul båd, att de skulle hemta David; men hon sade: Han är krank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Då sände Saul båd, till att bese David, och sade: Bärer honom hitupp till mig med sängene, att han må dräpas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Då nu båden kommo, si, då låg belätet i sängene, och getskinn om dess hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Då sade Saul till Michal: Hvi hafver du bedragit mig, och släppt min fienda, att han skulle undkomma? Michal sade till Saul: Han sade till mig: Låt mig gå, eller jag slår dig ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Och David flydde, och undkom, och kom till Samuel i Rama, och sade honom allt det Saul honom gjort hade; och han gick bort med Samuel, och blefvo i Najoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Och det vardt undervist Saul: Si, David är i Najoth i Rama.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Då sände Saul båd, att de skulle hemta David; och de sågo chorar med Propheter prophetera, och Samuel var deras tillsiare. Då kom Guds Ande uppå Sauls båd, så att de ock propheterade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Då det vardt Saul sagdt, sände han annor båd; de propheterade ock. Så sände han tredje båden; de propheterade ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Så gick han ock sjelf till Rama; och då han kom till den stora brunnen, som är i Sechu, frågade han, och sade: Hvar är Samuel och David? Då vardt honom sagdt: Si, i Najoth i Rama.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Och han gick dit till Najoth i Rama; och Guds Ande kom också öfver honom; och han gick och propheterade, tilldess han kom till Najoth i Rama.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Och han drog också sin kläder af, och propheterade också för Samuel, och föll naken neder den hela dagen, och den hela nattena. Deraf säger man: Är ock Saul ibland Propheter?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Och David flydde ifrå Najoth i Rama, och kom och talade för Jonathan: Hvad hafver jag gjort? Hvad hafver jag misshandlat? Hvad hafver jag syndat för dinom fader, att han står efter mitt lif?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Han sade till honom: Bort det! Du skall icke dö; si, min fader gör intet, hvarken stort eller litet, det han icke uppenbarar för min öron; hvi skulle då min fader dölja detta för mig? Det skall icke gå så till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Då svor David ytterligare, och sade: Din fader vet väl, att jag hafver funnit nåde för din ögon; derföre må han tänka, Jonathan skall intet veta häraf, på det han icke skall bedröfvas deraf; sannerliga, så visst som Herren lefver, och så visst som din själ lefver, det är icke mer än ett steg emellan mig och döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Jonathan sade till David: Jag vill göra dig allt det ditt hjerta begärar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'David sade till honom: Si, i morgon är nymånad, att jag skall sitta till bords med Konungen; så låt mig betämma, att jag gömmer mig på markene allt intill aftonen på tredje dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Om din fader frågar efter mig, så säg: David bad mig, att han måtte löpa till sin stad BethLehem; förty det är ett årligit offer allo slägtene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Är det så, att han säger: Det är godt; så står det väl med dinom tjenare; varder han ock vred, så varder du väl märkandes, att han hafver ondt i sinnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Så gör nu barmhertighet med dinom tjenare; ty du hafver med mig dinom tjenare gjort ett förbund i Herranom; är ock någor missgerning i mig, så dräp du mig, och låt mig icke komma inför din fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jonathan sade: Bort det ifrå dig, att jag skulle märka, att min fader hade i sinnet göra dig ondt, och jag icke skulle det säga dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'David sade: Ho skall säga mig det, om din fader svarar dig något hårdt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonathan sade till David: Kom, låt oss gå ut på markena; och de gingo både ut på markena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Och Jonathan sade till David: Herre Israels Gud, om jag utfrågar af minom fader i morgon och öfvermorgon, att det står väl till med David, och jag icke sänder till dig, och uppenbarar det för din öron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Så göre Herren det och det med Jonathan; men om minom fader täckes det ondt är emot dig, så vill jag ock uppenbara det för din öron, och släppa dig, att du går dina färde med frid; och Herren vare med dig, såsom han med minom fader vant hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Gör jag det icke, så gör du inga Herrans barmhertighet med mig, så länge jag lefver, ej heller när jag dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Och när Herren utrotar Davids fiendar, hvar och en utaf landet, så tag icke du dina barmhertighet bort ifrå mitt hus till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Alltså gjorde Jonathan ett förbund med Davids hus, och sade: Herren kräfve det utaf Davids fiendars händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Och Jonathan sade ytterligare, och svor David, så kär hade han honom; ty han hade honom så kär, som sina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Och Jonathan sade till honom: I morgon är nymånad, så varder väl frågadt efter dig; ty man varder dig saknandes, der du plägar sitta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'På tredje dagen kom med hast neder, och gack uti något rum, der du kan gömma dig på söknedagenom, och sätt dig vid den stenen Asel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Så vill jag skjuta tre pilar utmed honom, såsom jag sköte till ett mål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Och si, jag vill sända drängen: Gack och tag igen pilen; om jag säger till drängen: Si, pilarna ligga hitut bak dig, tag upp dem; så kom, ty det är frid, och är ingen fara, så visserliga som Herren lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Men om jag säger till drängen: Si, pilarna ligga bort bätter fram för dig; så gack dina färde, ty Herren hafver låtit dig gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Och hvad du och jag med hvarannan talat hafve, Herren vare emellan mig och dig i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Så gömde David sig i markene; och då nymånaden kom, satte Konungen sig till bords till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Då nu Konungen hade satt sig i sitt rum, såsom han tillförene var van, utmed väggene, stod Jonathan upp; och Abner satte sig vid Sauls sido; och man saknade David i hans rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Och Saul talade den dagen intet; ty han tänkte, honom är något vederkommet, att han icke är ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'På den andra nymånadsdagenom, då man saknade David i hans rum, sade Saul till sin son Jonathan: Hvi är icke Isai son kommen till bords, hvarken i går eller idag?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonathan svarade Saul: Han bad mig, att han skulle gå till BethLehem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Och sade: Låt mig gå, förty vår slägt skall offra i stadenom, och min broder hafver sjelf budit mig; hafver jag nu funnit nåd för din ögon, så vill jag dit, och se mina bröder; derföre är han icke kommen till Konungens bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Då vardt Saul vred på Jonathan, och sade: Du skalk och bofve, jag vet väl, att du hafver utvalt Isai son, dig och dine slemma moder till skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Ty så länge Isai son lefver på jordene, varder hvarken du eller ditt rike beståndandes. Så sänd nu, och låt hemta honom hit till mig; ty han måste dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonathan svarade sinom fader Saul, och sade till honom: Hvi skall han dö? Hvad hafver han gjort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Då sköt Saul spjutet efter honom, att han måtte skjutit honom igenom. Då märkte Jonathan, att alldeles var beslutet med hans fader, att han ville dräpa David;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Och stod upp ifrå bordet ganska vred, och åt på den samma andra nymånadsdagenom intet bröd; ty han vardt bedröfvad om David, efter hans fader hade så beskämt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Om morgonen gick Jonathan ut i markena, såsom han hade öfverens varit med David; och en liten dräng med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Och han sade till drängen: Löp och hemta mig pilarna upp igen, som jag skjuter; då drängen lopp, sköt han en pil öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Och då drängen kom på det rummet, dit Jonathan hade skjutit pilarna, ropade Jonathan efter honom, och sade: Pilen ligger bätter fram för dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Och ropade än en tid efter honom: Skynda dig full snart, statt icke stilla. Då hemtade drängen Jonathan pilarna upp, och bar dem till sin herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Och drängen visste intet hvad på färde var; allenast Jonathan och David visste det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Då fick Jonathan sinom dräng sin vapen, och sade till honom: Gack, och bär in i staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Då drängen var ingången, stod David upp af rummet på södra sidone, och föll på sitt ansigte till jordena, och tillbad tre resor; och de kysste hvarannan, och greto tillhopa, ju David aldramest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Och Jonathan sade till David: Gack med frid, hvad vi både svorit hafve i Herrans Namn och sagt: Herren vare emellan mig och dig, emellan min säd och din säd, till evig tid. Och han stod upp, och gick sin väg; men Jonathan gick i staden igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Och David kom till Nobe till Presten Ahimelech, och Ahimelech vardt häpen vid han gick emot David, och sade till honom: Hvi kommer du så allena, och ingen man med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David sade till Presten Ahimelech: Konungen hafver befallt mig ett ärende, och sade till mig: Låt ingen veta hvarefter jag hafver sändt dig, och hvad jag hafver befallt dig, så hafver jag sagt mina tjenare före der och der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Om du nu hafver något under dina händer, till en fem bröd, få mig det i mina hand; eller hvad du finner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Presten svarade David, och sade: dag hafver ingen menlig bröd under mine hand; utan helig bröd, om eljest tjenarena hafva hållit sig ifrå qvinnor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'David svarade Prestenom, och sade till honom: Qvinnorna hafva varit oss ifråstängda i tre dagar, då jag for åstad; och tjenarens tyg voro helig; men är denna vägen ohelig, så skall han i dag helgad varda genom tygen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Så gaf Presten honom af det helga, efter det var intet annat bröd, utan skådobröden, dem man upptog för Herranom, på det man skulle lägga fram annor färsk bröd, på den dagen då han dem borttog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Men der var den dagen en man inne besluten för Herranom, utaf Sauls tjenare, benämnd Doeg, en Edomeer, den mägtigaste ibland Sauls herdar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Och David sade till Ahimelech: Är icke här under dina hand ett spjut eller svärd? Jag hafver icke tagit mitt svärd eller vapen med mig; förty Konungens ärende var hastigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Presten sade: Den Philisteens svärd, Goliaths, den du slogst i ekdalen, det är här svept uti en mantel bak lifkjortelen; vill du det, så tag det; ty här är intet annat, än det. David sade: Dess like är icke, få mig det hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Och David stod upp, och flydde för Saul, och kom till Achis, Konungen i Gath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Men Achis tjenare sade till honom: Denne är David, landsens Konung, om hvilken de söngo i dansen, och sade: Saul slog tusende, men David tiotusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Och David lade dessa orden på hjertat, och fruktade sig storliga för Achis, Konungenom i Gath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Och han förvandlade sina åthäfvor för dem, och föll neder i deras händer, och stötte sig emot dörrene i portenom, och hans spott flöt honom ut på skägget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Då sade Achis till sina tjenare: Si, I sen, att mannen är ursinnig; hvi hafven I haft honom till mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Hafver jag icke nog ursinniga, att I skullen hafva denna in till mig, att han skulle rasa för mig? Skulle han komma i mitt hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'David gick dädan, och flydde bort uti den kulon Adullam. Då hans bröder det hörde, och hela hans faders hus, kommo de ditned till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Och till honom församlade sig allehanda män, som i nöd, i gäld och bedröfvadt hjerta voro, och han vardt deras höfvitsman, så att när honom voro vid fyrahundrade män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Och David gick dädan till Mizpa uti de Moabiters land, och sade till de Moabiters Konung: Låt min fader och min moder gå ut och in med eder, tilldess jag får se hvad Gud vill göra med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Och han lät dem in för de Moabiters Konung, att de voro när honom så länge som David var på borgene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Men den Propheten Gad sade till David: Blif icke på borgene, utan gack bort i Juda land. Så gick David åstad, och kom uti den skogen Hareth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Och det kom för Saul, att David och de män, som när honom voro, voro sedde. Som nu Saul bodde i Gibea i en lund i Rama, hade han sitt spjut i handene, och alla hans tjenare stodo bredevid honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Då sade Saul till sina tjenare, som stodo bredevid honom: Hörer, I Jemini barn, månn ock Isai son skola gifva eder allom åkrar och vingårdar, och göra eder alla till öfverstar öfver tusende, och öfver hundrade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Att I alle hafven förbundit eder emot mig, och ingen är, som det för min öron uppenbarar, efter min son hafver ock gjort ett förbund med Isai son? Är ingen ibland eder, hvilkom det gör ondt för mina skull, och uppenbarar det för min öron? Ty min son hafver uppväckt min tjenare emot mig; att han skall gå mig efter, såsom för ögon är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Så svarade Doeg den Edomeen, som stod ibland Sauls tjenare, och sade: Jag såg Isai son, att han kom till Nobe till Ahimelech, Ahitobs son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Han frågade om honom Herran, och gaf honom spisning och Goliaths den Philisteens svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Då sände Konungen åstad, och lät kalla Presten Ahimelech, Ahitobs son, och hela hans faders hus, Presterna som voro i Nobe; och de kommo alle till Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Och Saul sade: Hör du, Ahitobs son. Han sade: Här är jag, min herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Och Saul sade till honom: Hvi hafven I gjort ett förbund emot mig, du och Isai son, så att du hafver gifvit honom bröd och svärd, och frågat Gud för honom, på det du skulle uppväcka honom, till att han skulle gå mig efter, såsom för ögon är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelech svarade Konungenom, och sade: Och ho är ibland alla dina tjenare sådana som David, trogen och Konungens måg, och går i dine lydno, och är mycket afhållen i ditt hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Hafver jag nu först i dag begynt fråga Gud för honom? Det vare långt ifrå mig; Konungen lägge sin tjenare icke sådant till i allo mins faders huse; förty din tjenare hafver intet vetat af allt detta, hvarken litet eller stort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Men Konungen sade: Ahimelech, du måste döden dö, du och hela dins faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Och Konungen sade till sina drabanter, som när honom stodo: Vänder eder, och dräper Herrans Prester; förty deras hand är ock med David; och då de visste att han flydde, underviste de mig det icke. Men Konungens tjenare ville icke komma deras händer vid Herrans Prester, och slå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Då sade Konungen till Doeg: Vänd du dig, och slå Presterna. Doeg den Edomeen vände sig, och slog Presterna, så att den dagen blefvo döde fem och åttatio män, som drogo linnan lifkjortel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Och Presternas stad Nobe slog han med svärdsegg, både män och qvinnor, barn och dem som didde, fä och åsnar, och får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Men en Ahimelechs son, Ahitobs sons, benämnd AbJathar, slapp undan, och flydde bort till David;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Och sade honom, att Saul hade dräpit Herrans Prester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Men David sade till AbJathar: Jag visste väl den dagen, då den Edomeen Doeg der var, att han skulle säga det Saul. Jag är skyldig för alla dins faders hus själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Blif när mig, och frukta dig intet. Den som står efter mitt lif, han skall ock stå efter ditt lif, och du skall med mig blifva förvarad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Och David vardt bådadt: Si, de Philisteer strida emot Kegila, och röfva ladorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Då frågade David Herran, och sade: Skall jag gå bort och slå dessa Philisteer? Och Herren sade till David: Gack åstad, du skall slå de Philisteer, och undsätta Kegila.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Men de män när David sade till honom: Si, vi hafve fruktan här i Juda; och vilje ännu gå bort till Kegila, till de Philisteers här?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Då frågade åter David Herran. Och Herren svarade honom, och sade: Upp, drag ned till Kegila; ty jag vill gifva de Philisteer i dina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Så drog David med sina män till Kegila, och stridde emot de Philisteer, och dref dem deras boskap bort, och slog dem en stor slagtning af. Alltså undsatte David dem i Kegila;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Ty då AbJathar, Ahimelechs son, flydde till David till Kegila, bar han lifkjortelen ditned med sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Då vardt Saul sagdt, att David var kommen till Kegila; och han sade: Gud hafver gifvit honom i mina händer, så att han är innelyckt, och är kommen i en stad, som är förvarad med portar och bommar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Och Saul lät kalla allt folket till strid, ditneder till Kegila, och skulle belägga David och hans män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Då David förmärkte, att Saul hade ondt i sinnet om honom, sade han till Presten AbJathar: Tag hit lifkjortelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Och David sade: Herre Israels Gud, din tjenare hafver hört, att Saul hafver i sinnet, att han skall komma till Kegila, till att förderfva staden för mina skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Månn borgarena i Kegila öfverantvarda mig i hans händer? Och månn Saul komma hitneder, såsom din tjenare hört hafver? Det låt din tjenare få veta, Herre Israels Gud. Och Herren sade: Han kommer hitneder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'David sade: Månn borgarena i Kegila öfverantvarda mig och mina män i Sauls händer? Herren sade: Ja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Då stod David upp med sina män, som voro vid sexhundrad, och drogo ut af Kegila, och vandrade hvart de kunde. Då nu Saul vardt sagdt, att David var utflydder af Kegila, lät han sitt uttåg bestå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Och David blef i öknene på borgene, och blef på berget i den öknene Siph; men Saul sökte honom så länge han lefde; men Gud gaf honom icke i hans händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Och David såg, att Saul utdragen var att söka efter hans lif; men David blef uti den öknene Siph i hedene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Då stod Jonathan upp, Sauls son, och gick bort till David ut i hedena, och styrkte hans hand i Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Och sade till honom: Frukta dig intet; mins faders Sauls hand finner dig intet; och du varder Konung öfver Israel, så vill jag vara dig närmast; och detta vet min fader väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Och de gjorde både ett förbund tillhopa för Herranom. Och David blef i hedene; men Jonathan drog hem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Men de Siphiter foro upp till Saul i Gibea, och sade: Är icke David gömder när oss på borgene i hedene, på den högen Hachila, som ligger på högra handene vid öknen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Så kom nu neder, Konung, efter allt dins hjertans begär, så vilje vi öfverantvarda honom i Konungens händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Då sade Saul: Välsignade varen I Herranom, att I hafven förbarmat eder öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Så går nu bort, och varder dess ännu vissare, att I mågen få veta och se, på hvad rum hans fötter varit hafva, och tio honom der sett hafver; ty mig är sagdt, att han är listig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Beser och bespejer all rum der han gömmer sig; och kommer igen till mig, när ären visse vordne, så vill jag fara med eder. Är han i landena, så skall jag söka upp honom i all tusend i Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Då stodo de upp, och gingo till Siph fram för Saul; men David och hans män voro i den öknene Maon, på den slättmarkene, på högra sidone vid öknena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Då nu Saul drog dit med sina män till att söka, vardt David förvarad, och drog ned uti en bergklippo i öknene Maon. Då Saul det hörde, jagade han efter David i den öknene Maon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Och Saul med sina män gick på ena sidon om berget, och David med sina män på den andra sidon om berget. Då nu David skyndade sig att undkomma för Saul, då kringhvärfde Saul med sina män David och hans män, att de måtte få dem fatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Men ett bådskap kom till Saul, och sade: Skynda dig, och kom; förty de Philisteer äro infallne i landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Då vände Saul om af det sökandet efter David, och drog bort emot de Philisteer. Deraf kallar man det rummet SelaMahelkoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Och David drog med dädan, och blef på borgene i EnGedi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Då nu Saul igenkom ifrå de Philisteer, vardt honom sagdt: Si, David är i den öknene EnGedi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Och Saul tog tretusend unga män utu hela Israel, och drog åstad till att söka David med hans män, på de stengetters klippor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Och då han kom till de fårahyddor vid vägen, var der en kula; och Saul gick derin till att betäcka sina fötter; men David och hans män såto inne i kulone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Då sade Davids män till honom: Si, detta är den dagen, om hvilken Herren din Gud dig sagt hafver: Si, jag skall gifva din fienda i dina händer, att du gör med honom såsom dig täckes. Och David stod upp, och skar sakta bort ena flik af Sauls kjortel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Men sedan slog honom hans hjerta, att han hade skorit den Sauls flik bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Och sade till sina män: Det låte Herren vara långt ifrå mig, att jag det göra skulle, och komma mina hand vid min herra, Herrans smorda; ty han är Herrans smorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Och David stillte sina män med ordom, och lät dem icke öfverfalla Saul. Och Saul kom upp utu kulone, och gick ut på vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Stod ock David sedan upp, och gick utu kulone, och ropade efter Saul, och sade: Min herre Konung. Saul såg tillbaka efter sig; och David böjde sitt ansigte ned till jordena, och tillbad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Och sade till Saul: Hvi hörer du de menniskors ord, som säga: David söker efter ditt argesta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Si, i dag se din ögon, att Herren hafver i denna dag gifvit dig i mina hand i kulone; och det vardt sagdt, att jag skulle dräpit dig; men dig vardt skonadt; ty jag sade: Jag vill icke komma mina hand vid min herra; ty han är Herrans smorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Min fader, se dock fliken af din kjortel i mine hand, att jag icke ville dräpa dig då jag bortskar en flik af din kjortel; känn och se, att intet ondt är i mine hand, eller någor öfverträdelse. Jag hafver ock intet syndat emot dig, och du går efter mina själ, att du må taga henne bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Herren skall vara domare emellan mig och dig, och Herren skall hämna mig på dig; men min hand skall icke vara öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Såsom man säger af ett gammalt ordspråk: Af ogudaktigom kommer odygd; men min hand skall icke vara öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Hvem förföljer du, Israels Konung? Hvem jagar du efter? En dödan hund, ena loppo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Herren vare domare, och döme emellan mig och dig, och se dertill, och rätte min sak ut, och frie mig ifrå dine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Som nu David hade dessa orden uttalat, sade Saul: Är det icke din röst, min son David? Och Saul upphof sina röst och gret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Och sade till David: Du äst rättfärdigare än jag; du hafver bevist mig godt; men jag hafver bevist dig ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Och du hafver i denna dag gifvit mig tillkänna, huru du hafver gjort väl emot mig; att Herren hade beslutit mig i dina händer, och du hafver dock icke dräpit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Huru skulle någor finna sin fienda, och låta honom sedan gå en god väg? Herren vedergälle dig det goda, som du i denna dag med mig gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Nu si, jag vet, att du varder Konung, och Israels Konungsrike står i dine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Så svär mig nu vid Herran, att du icke utrotar min säd efter mig, och icke utskrapar mitt namn utu mins faders hus. Och David svor Saul; och så drog Saul hem; men David och hans män drogo upp på borgena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Och Samuel blef död; och hela Israel församlade sig, begreto honom, och begrofvo honom i hans hus i Rama. Men David stod upp, och drog ned i den öknena Paran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Och en man var i Maon, och hans väsende var i Carmel, och den mannen var ganska mägtig, och hade tretusende får och tusende getter. Och det begaf sig, att han klippte sin får i Carmel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Och han het Nabal; och hans hustru het Abigail, och var en förnuftig qvinna, och dägelig under ansigtet; men mannen var hård och arg i sina gerningar, och var en af Caleb.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Då nu David fick höra i öknene, att Nabal klippte sin får,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Sände han ut tio unga män, och sade till dem: Går upp till Carmel, och då I kommen till Nabal, så helser honom, på mina vägnar, vänliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Och önsker honom lycko, och säger: Frid vare med dig, och med ditt hus, och med allt det du hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Jag hafver hört, att du hafver fåraklippare; si, dina herdar, som du hafver, hafva varit när oss; vi hafve aldrig talat dem illa till; och dem hafver intet fattats på talet, så länge de hafva varit i Carmel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Fråga dina dränger derom, de skola säga dig det. Så låt nu dessa unga män finna nåd för din ögon; ty vi äre komne på en god dag. Gif dina tjenare, och dinom son David, hvad din hand finner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Då de Davids unga män kommo dit, och hade på Davids vägnar talat all dessa orden med Nabal, höllo de upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Men Nabal svarade Davids tjenare, och sade: Ho är den David? Och ho är den Isai son? Det äro nu månge de tjenare, som gifva sig ifrå sina herrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Skulle jag taga mitt bröd, vatten, och kött som jag för mina klippare slagtat hafver, och gifva de folke, som jag intet vet hvadan de äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Då vände de Davids unga män om igen på deras väg; och när de kommo till David, sade de honom allt detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Då sade David till sina män: Hvar och en binde sitt svärd vid sig. Och hvar och en af dem band sitt svärd vid sig; och David band ock desslikes sitt svärd vid sig; och drogo med honom ned vid fyrahundrad män; men tuhundrad blefvo qvar när deras tyg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Men en af drängerna gaf Abigail, Nabals hustru, tillkänna, och sade: Si David hafver sändt båd utur öknene, till att helsa vår herra; och han snubbade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Och de män hafva dock varit oss ganska nyttige, och intet talat oss illa till, och oss hafver intet fattats på talet, så länge vi hafve vistats när dem, medan vi i markene vorom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Utan de hafva varit våra murar dag och natt, så länge vi vaktade fåren när dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Så märk nu och se, hvad du göra vill; ty förvisso är ett ondt för handene öfver vår herra, och öfver hela hans hus; och han är en Belials man, hvilkom ingen något säga djerfves.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Då hastade sig Abigail, och tog tuhundrad bröd, och två läglar, vin, och fem kokad får, och fem skäppor mjöl, och hundrad stycke russin, och tuhundrad stycke fikon, och lade på åsnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Och sade till sina dränger: Går för mig, jag vill komma efter. Och hon sade sinom man Nabal här intet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Och som hon red på åsnanom, och kom neder i bergsskygdena, si, då kom David och hans män nederdragandes emot henne, så att hon mötte dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Och David hade sagt: Jag hafver förgäfves förvarat allt det denne hade i öknene, så att der hafver intet fattats af allt det han hade; och han betalar mig godt med ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Gud göre detta, och än mer, Davids fiendar, om jag låter honom blifva qvar, intill morgon ljust varder, en som på väggena pissar, utaf allt det han hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Då nu Abigail såg David, steg hon hastigt af åsnanom, och föll för David på sitt ansigte, och tillbad honom på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Och föll till hans fötter, och sade: Ack! min Herre, min vare denna missgerning, och låt dina tjenarinno tala för din ögon; och hör dina tjenarinnos ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Min herre sätte icke sitt hjerta emot denna Nabal, den Belials mannen; ty han är en galen man, såsom hans namn är, och galenskap är med honom; men jag din tjenarinna hafver icke sett mins herras unga män, som du utsände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Men nu, min Herre, så visst som Herren lefver, och så visst som din själ lefver, Herren hafver förtagit dig, att du icke kom i blod, och hafver friat dig dina hand; men nu vare dine fiender såsom Nabal, och de som vilja minom herra ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Här är välsignelsen, som din tjenarinna minom herra fört hafver; gif henne de unga män, som med min herra vandra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Förlåt dine tjenarinno den öfverträdelsen; ty Herren skall göra minom herra ett tryggt hus; ty du förer Herrans krig, och intet ondt skall när dig funnet varda i alla dina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Och om någor menniska hafver sig upp till att förfölja dig, och står efter dina själ, så skall mins herras själ vara inbunden uti de lefvandes knippe, när Herranom dinom Gud; men dina fiendars själ skall varda bortslungad med slungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'När nu Herren minom herra allt detta goda görandes varder, som han dig sagt hafver, och budit dig, att du skall vara en höfvitsman öfver Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Så varder detta icke görandes mins herras hjerta någon ångest eller nyck, att du hafver blod utgjutit utan orsak, och hämnat dig sjelfvan; så skall Herren göra minom herra godt, och du varder tänkandes på dina tjenarinno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Då sade David till Abigail: Lofvad vare Herren Israels Gud, som dig i dag hafver emot mig sändt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Och lofvade vare dina åthäfvor; och lofvad vare du, som i dag hafver förtagit mig, att jag icke är kommen i blod, och hämnat mig med egna hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Sannerliga, så visst som Herren Israels Gud lefver, den mig förtagit hafver, att jag icke gjorde dig ondt, hade du icke snarliga kommit emot mig, så hade Nabal, intill morgon ljust varder, icke qvar blifvit en, som på väggena pissar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Alltså tog då David af hennes hand det hon honom fört hade, och sade till henne: Far med frid upp till ditt hus; si, jag hafver hört dina röst, och täckeliga tagit din person.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Då Abigail kom till Nabal, si, då hade han tillredt ena måltid i sitt hus, såsom en Konungs måltid, och hans hjerta var gladt i honom; ty han var mycket drucken. Men hon sade honom intet, hvarken litet eller stort, intill morgonen ljust vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Då dager vardt, när vinet var gånget af Nabal, sade hans hustru honom detta. Då vardt hans hjerta dödt i honom, så att han vardt såsom en sten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Och efter tio dagar slog Herren honom, så att han blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Då David hörde att Nabal var död, sade han: Lofvad vare Herren, som hafver hämnat min försmädelse på Nabal, och hafver förvarat sin tjenare för det ondt var; och Herren hafver Nabals ondsko vedergullit in på hans hufvud. Och David sände bort, och lät tala med Abigail, att han måtte taga henne till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Och då Davids tjenare kommo till Abigail i Carmel, talade de till henne, och sade: David hafver sändt oss till dig, på det han må få dig till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Hon stod upp, och tillbad på sitt ansigte till jordena, och sade: Si, här är din tjenarinna, att hon må tjena mins herras tjenare, och två deras fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Och Abigail hastade sig, och gjorde redo, och red på en åsna, och fem tjenstepigor, som under henne voro; och följde Davids bådskap, och vardt hans hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Desslikes tog David Ahinoam af Jisreel; och voro båda hans hustrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Men Saul gaf sina dotter Michal, Davids hustru, Phalti, Lais sone, af Gallim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Och de af Siph kommo till Saul i Gibea, och sade: Är icke David fördold på berget Hachila, inför öknene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Då stod Saul upp, och drog ned till den öknen Siph; och med honom tretusend unge män af Israel; på det han skulle uppsöka David i öknene Siph.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Och lägrade sig på det berget Hachila, som ligger inför öknene vid vägen; men David blef i öknene. Och då han såg, att Saul kom efter honom i öknena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Sände han spejare ut, och förfor att Saul visserliga kommen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Och David stod upp, och kom till det rummet, der Saul höll sitt lägre; och han såg rummet, der Saul låg med sin härhöfvitsman, Abner, Ners son; ty Saul låg i vagnborgene, och härfolket omkring honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Då svarade David, och sade till Ahimelech den Hetheen, och till Abisai, ZeruJa son, Joabs broder: Ho vill med mig neder till Saul i lägret? Abisai sade: Jag vill ned med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Så kom David och Abisai till folket om nattena, och si, Saul låg och sof i vagnborgene, och hans spjut stött i jordena, vid hans hufvud; men Abner och folket låg omkring honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Då sade Abisai till David: Gud hafver i denna dag beslutit din fienda i dina hand; så vill jag nu en gång med spjutet stinga honom igenom i jordena, så att han skall icke mer behöfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Men David sade till Abisai: Förderfva honom intet; ty ho vill komma sina hand vid Herrans smorda, och blifva oskyldig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Ytterligare sade David: Så visst som Herren lefver, om Herren icke slår honom, eller hans tid kommer, att han dör, eller han drager i en strid, och så blifver borta,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Så låte Herren det vara långt ifrå mig, att jag skall komma mina hand vid Herrans smorda; så tag nu spjutet vid hans hufvud, och vattubägaren, och låt oss gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Så tog David spjutet och vattubägaren vid Sauls hufvud, och gingo sina färde; och ingen var, som det såg eller märkte, eller vaknade, utan de sofvo alle; ty en tung sömn var fallen på dem af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Då nu David var kommen öfver på hinsidon, gick han upp på bergskullan långt ifrå, så att der var stort rum emellan dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Och ropade till folket och till Abner, Ners son, och sade: Hörer du icke, Abner? Och Abner svarade, och sade: Ho äst du, att du så ropar Konungen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Och David sade till Abner: Äst du icke en man? Och ho är din like i Israel? Hvi hafver du då icke bevarat din herra Konungen? Ty en af folket är der ingången, till att slå din herra Konungen ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Det är icke redeligit, som du gjort hafver; så visst som Herren lefver, I ären dödsens barn, att I edar herra, Herrans smorda, icke bevarat hafven; nu se, här är Konungens spjut och vattubägaren, som stodo vid hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Då kände Saul Davids röst, och sade: Är det icke din röst, min son David? David sade: Det är min röst, min herre Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Och sade ytterligare: Hvi förföljer min herre så sin tjenare? Hvad hafver jag gjort? Och hvad ondt är i mine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Så höre dock nu min herre Konungen sin tjenares ord: Om Herren uppretar dig emot mig, så låte man ett spisoffer lukta; men om menniskors barn göra det, så vare de förbannade för Herranom, att de på denna dag hafva fördrifvit mig, att jag icke må blifva i Herrans arfvedel, och säga: Gack bort, och tjena andra gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Så förfalle nu icke mitt blod på jordena för Herrans ansigte; ty Israels Konung är utdragen till att söka ena loppo, såsom man jagar ett rapphöns på bergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Och Saul sade: Jag hafver syndat. Kom igen, min son David, jag vill intet ondt mer göra dig, derföre att min själ hafver i denna dag dyr varit för din ögon; si, jag hafver gjorts dårliga och ganska ovisliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'David svarade, och sade: Si, här är Konungens spjut; en af de unga män gånge hitupp, och tage det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Herren varder väl hvarjom och enom vedergällandes efter hans rättfärdighet och tro; ty Herren hade i dag gifvit dig i mina hand; men jag ville icke komma mina hand vid Herrans smorda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Och såsom din själ hafver i denna dagen för min ögon mycket aktad varit, så varde ock min själ mycket aktad för Herrans ögon, och hjelpe mig utur all bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Saul sade till David: Välsignad vare du, min son David; du skall görat, och gåt igenom. Så gick David sin väg; och Saul vände om hem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Så tänkte David i sitt hjerta: Jag faller dock en dag Saul i händer; det är mig bättre, att jag rymmer undan in uti de Philisteers land; på det Saul må vända igen att ytterligare söka efter mig i alla Israels gränsor; så må jag då komma ifrå hans händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Och stod upp, och gick åstad med de sexhundrad män, som med honom voro, till Achis, Maochs son, Konungen i Gath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Så blef David när Achis i Gath, med sina män, hvar med sitt hus; David desslikes med sina två hustrur, Ahinoam den Jisreelitiskon, och Abigail, Nabals hustru, den Carmelitiskon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Då Saul vardt sagdt, att David var flydd till Gath, sökte han intet mera efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Och David sade till Achis: Hafver jag funnit nåd för din ögon, så låt gifva mig ett rum uti en af städerna på landena, att jag må bo derinne; hvi skulle din tjenare bo uti Konungsstadenom när dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Då gaf honom Achis på den dagen Ziklag. Deraf är Ziklag Juda Konungars, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Tiden, som David bodde uti de Philisteers land, var ett år och fyra månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Och David med sina män drog upp, och föll in uti de Gessuriters och de Girsiters och de Amalekiters land; ty desse bodde i landena af ålder, der man kommer till Zur, allt intill Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Och då han slog landet, lät han hvarken man eller qvinno lefva, och tog får, fä, åsnar, camelar och kläder, och vände om, och kom till Achis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'När nu Achis sade: Hafven I ock i dag någorstäds infallit? Då sade David: Söderut i Juda, och söderut till de Jerahmeehter, och söderut till de Keniter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Men David lät hvarken man eller qvinno lefvande komma till Gath, och tänkte: De måga säga på oss, och sqvallra. Så gjorde David, och det var hans sedvänja, så länge han bodde uti de Philisteers land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Derföre trodde Achis David, och tänkte: Han hafver gjort sig illa luktandes för sitt folk Israel; ty blifver han väl min tjenare till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Och det begaf sig på den tiden, att de Philisteer församlade sin här, till att draga ut i strid emot Israel. Och Achis sade till David: Du skall veta, att du och dine män skolen draga ut med mig i hären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'David sade till Achis: Nu väl, du skall se hvad din tjenare göra skall. Achis sade till David: Derföre skall jag sätta dig till mins hufvuds väktare, i mina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Så var nu Samuel död, och hele Israel hade begråtit honom, och begrafvit honom i hans stad Rama. Så hade Saul bortdrifvit utu landet spåmän och tecknatydare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Som nu de Philisteer församlade sig, och kommo och lägrade sig i Sunem, församlade ock Saul hela Israel, och lagrade sig i Gilboa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Då Saul såg de Philisteers här, fruktade han sig, och hans hjerta var mycket försoffadt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Och han frågade Herran, och Herren svarade honom intet, hvarken i drömmar eller genom ljus, eller genom Propheter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Då sade Saul till sina tjenare: Söker mig ena qvinno, som en spådomsanda hafver, att jag må gå till henne, och fråga henne. Hans tjenare sade till honom: Si, i EnDor är en qvinna, som hafver en spådomsanda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Och Saul omskifte sin kläder, och tog annor uppå, och gick dit, och två män med honom, och kommo om nattena till qvinnona, och sade: Kära, spå mig genom spådomsanda, och res mig upp den jag säger dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Qvinnan sade till honom: Si, du vetst väl hvad Saul gjort hafver, huru han hafver förödt de spåmän och tecknatydare utu landet; hvi vill du då komma min själ i nätet, att jag skulle blifva dödad?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Då svor Saul henne vid Herran, och sade: Så visst som Herren lefver, skall detta icke varda dig räknadt till missgerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Då sade qvinnan: Hvem skall jag uppresa dig? Han sade: Res mig Samuel upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Då nu qvinnan såg Samuel, ropade hon högt, och sade till Saul: Hvi hafver du bedragit mig? Du äst Saul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Och Konungen sade till henne: Frukta dig intet; hvad ser du? Qvinnan sade till Saul: Jag ser gudar stiga upp af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Han sade: Huru är hans skapnad? Hon sade: En gammal man kommer upp, och är klädd i en silkeskjortel. Så förnam Saul, att det var Samuel, och böjde sitt ansigte ned på jordena, och tillbad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Och Samuel sade till Saul: Hvi hafver du gjort mig omak, att du hafver låtit mig uppresas? Saul sade: Jag är i stora nöd; de Philisteer strida emot mig, och Gud är viken ifrå mig, och svarar mig intet, hvarken genom Propheter, eller genom drömmar; derföre hafver jag låtit kalla dig, att du skall undervisa mig hvad jag göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel sade: Hvad vill du fråga mig, efter Herren är ifrå dig viken, och är din ovän vorden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Herren varder dig görandes, såsom han genom mig talat hafver; och Herren skall rifva riket utu dine hand, och gifva det David dinom nästa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Derföre, att du Herrans röst icke lydt hafver; icke heller fullföljt hans vredes grymhet emot Amalek; derföre hafver nu Herren detta gjort dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Dertill skall Herren ock gifva Israel med dig uti de Philisteers händer. I morgon skall du och dine söner vara när mig; och Herren skall gifva Israels här uti de Philisteers händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Då föll Saul hasteliga till jordena; ty han kunde icke stå, och vardt svårliga förfärad för Samuels ord, så att ingen magt var mer i honom; ty han hade intet bröd ätit i den hela dagen, och den hela nattene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Och qvinnan gick in till Saul, och såg att han var mycket förfärad, och sade till honom: Si, din tjenarinna hafver lydt dine röst: och jag hafver satt mina själ i mina hand, så att jag lydde din ord, som du talade till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Så hör ock nu du dina tjenarinnos röst: Jag vill sätta för dig en beta bröd, att du äter, och kommer till magt igen, och går dina färde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Han nekade, och sade: Jag vill intet äta. Då nödgade honom hans tjenare och qvinnan, så att han lydde deras röst. Och han stod upp af jordene, och satte sig på sängena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Och qvinnan hade en göddan kalf i huset; då hastade hon sig, och slagtade honom, och tog mjöl, och blandade, och bakade det osyradt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Och bar fram för Saul, och för hans tjenare; och då de hade ätit, stodo de upp, och gingo alla den nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Men de Philisteer samlade alla sina härar i Aphek, och Israel lägrade sig i Ajin i Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Och de Philisteers Förstar gingo med hundrad, och med tusend; men David gick efterst med sina män när Achis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Då sade de Philisteers Förstar: Hvad skola denne Ebreer? Achis sade till dem: Är icke det David, Sauls tjenare, Israels Konungs, den nu när mig varit hafver år och dag; och jag hafver intet funnit med honom, ifrå den tiden han föll intill mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Men de Philisteers Förstar vordo vrede på honom, och sade till honom: Låt den mannen vända om, och blifva i sitt rum, der du hafver satt honom, att han icke drager neder med oss i stridena, och varder vår fiende i stridene; ty i hvad kunde han bättre blidka sin herra, än med dessa männernas hufvud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Är icke han den David, om hvilken de söngo i dansen: Saul slog tusende, men David slog tiotusend?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Då kallade Achis David, och sade till honom: Så visst som Herren lefver, jag håller dig för en redelig man; och din utgång och ingång, med mig i härenom, behagar mig väl, och hafver intet argt sport af dig, ifrå den tiden, du kom till mig, intill nu; men du behagar icke Förstomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Så vänd nu om, och gack med frid, på det du icke skall förtörna de Philisteers Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David sade: Hvad hafver jag gjort? Och hvad hafver du sport af din tjenare, ifrå den tid jag hafver varit när dig, intill nu, att jag icke skall komma och strida emot mins herras Konungens fiendar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Achis svarade, och sade till David: Jag vet väl, att du äst täck för min ögon, såsom en Guds Ängel; men de Philisteers Förstar hafva sagt: Låt honom icke draga upp med oss i stridena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Så var nu i morgon bittida uppe, och dins herras tjenare, som med dig komne äro; och när I ären i morgon bittida uppståndne, och ljust är, så går edar väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Så var då David och hans män bittida uppe, att de skulle om morgonen färdas, och komma uti de Philisteers land igen; men de Philisteer drogo upp till Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Då nu David på tredje dagen kom till Ziklag med sina män, voro de Amalekiter der infallne söderut, och till Ziklag; och hade slagit Ziklag, och uppbränt med eld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Och hade bortfört qvinnorna dädan, både små och stora; men de hade ingen slagit ihjäl, utan drifvit dem bort och voro sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Då nu David med sina män kom till staden, och såg att han var uppbränd med eld, och deras hustrur, söner och döttrar fångne,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Hof David och folket, som med honom var, deras röst upp, och greto, tilldess de icke mer gråta kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Ty Davids två hustrur voro ock fångna, Ahinoam den Jisreelitiskan, och Abigail, Nabals hustru, den Carmelitens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Och David var storliga bedröfvad; ty folket ville stena honom; ty hela folkens själ var bedröfvad, hvar och en öfver sina söner och döttrar. Men David stärkte sig i Herranom sinom Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Och sade till Presten AbJathar, Ahimelechs son: Bär mig fram lifkjortelen. Och då AbJathar hade burit fram lifkjorteln,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Frågade David Herran, och sade: Skall jag jaga efter krigsfolket? och skall jag få dem fatt? Han sade: Jaga efter dem; du skall få dem fatt, och undsätta rofvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Så drog David åstad, och de sexhundrad män, som när honom voro. Och då de kommo till den bäcken Besor, blefvo någre ståndande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Men David och fyrahundrad män jagade efter; och de tuhundrade män, som ståndande blefvo, hade försummat sig fara öfver bäcken Besor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Och de funno en Egyptisk man på markene, den förde de till David, och gåfvo honom bröd, att han åt, och gåfvo honom vatten dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Och gåfvo honom ett stycke fikon, och tu stycke russin; och då han ätit hade, kom hans anda åter till honom; ty han hade i tre dagar och tre nätter intet bröd ätit, och intet vatten druckit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'David sade till honom: Hvem hörer du till? Och hvadan äst du? Han sade: Jag är en Egyptisk dräng, en Amalekiters tjenare, och min herre hafver öfvergifvit mig; ty jag vardt krank för tre dagar sedan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Vi vorom här infallne söder på Crethi, och uppå Juda, och söder på Caleb, och hafve bränt upp Ziklag med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David sade till honom: Vill du föra mig ned till det krigsfolket? Han sade: Svär mig vid Gud, att du icke slår mig ihjäl eller antvardar mig i mins herras hand, så vill jag föra dig ned till det krigsfolket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Och han förde dem ned; och si, de hade förstrött sig öfver hela jordena, åto och drucko, och fröjdade sig, för det stora bytets skull, som de tagit hade utu de Philisteers land, och utur Juda land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Och David slog dem, ifrå morgonen allt intill aftonen, emot den andra dagen, så att ingen af dem undslapp, förutan fyrahundrade ynglingar, de satte sig uppå cameler, och flydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Så undsatte då David allt det de Amalekiter tagit hade, och sina två hustrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Och fattades ingen, hvarken liten eller stor, hvarken söner eller döttrar, eller af rofvet, eller hvad som helst de tagit hade; David hemtade det allt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Och David tog får och fä, och dref boskapen för sig, och de sade: Detta är Davids rof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Och då David kom till de tuhundrade män, som sig försummat hade efterfölja David, och voro blefne vid bäcken Besor, gingo de ut emot David, och folket, som med honom var; och David gick till folket, och helsade dem vänliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Då svarade de som onde och Belials män voro, ibland dem som med David dragne voro, och sade: Efter de icke foro med oss, skall man intet gifva dem af rofvet, som vi undsatt hafve; utan hvar och en tage sina hustru och sin barn, och gånge sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Då sade David: I skolen icke så göra, mine bröder, med det som Herren oss gifvit hafver, och hafver förvarat oss, och gifvit det krigsfolket i våra händer, som emot oss komne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Ho skulle höra eder derutinnan? Sådana som deras del är, som voro neddragne i stridena, sådana skall ock deras del vara, som när tygen blifvit hafva, och skall lika bytt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Detta är också ifrå den tiden och allt sedan vordet för en sed och rätt i Israel, intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Och då David kom till Ziklag, sände han rofvet till de äldsta i Juda sina nästa, och sade: Si, der hafven I välsignelsen af Herrans fiendars rof;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Nämliga dem i BethEl, dem i Bamoth söderut, dem i Jathir,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Dem i Aroer, dem i Siphmoth, dem i Esthemoa,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Dem i Rachal, dem i de Jerahmeeliters städer, dem i de Keniters städer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'Dem i Horma, dem i ChorAsan, dem i Atach,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'Dem i Hebron, och allestäds der David vandrat hade med sina män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Så stridde nu de Philisteer emot Israel, och Israels män flydde för de Philisteer, och föllo slagne på det berget Gilboa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Och de Philisteer föllo hardt in på Saul och hans söner, och slogo Jonathan, och AbiNadab, och MalchiSua, Sauls söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Och striden vardt hård emot Saul, och skyttorna drabbade på honom med bågarna; och han vardt illa sår af skyttorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Då sade Saul till sin vapnedragare: Drag ditt svärd ut, och sting mig igenom dermed, att desse oomskorne icke komma, och stinga mig igenom, och drifva gabberi med mig. Men hans vapnedragare ville icke; ty han fruktade sig storliga. Så tog Saul svärdet, och föll deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Då nu hans vapnedragare såg, att Saul var död, föll han ock på sitt svärd, och blef död med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Så blef Saul död, och tre hans söner, och hans vapnedragare, och alle hans män tillhopa på den dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Då nu Israels män, som voro på hinsidon vid dalen, och på hinsidon Jordan, sågo, att Israels män voro flydde, och att Saul och hans söner voro döde, öfvergåfvo de städerna, och flydde sammaledes. Så kommo de Philisteer, och bodde deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Den andra dagen kommo de Philisteer till att afkläda de slagna; och funno Saul och hans tre söner liggande på berget Gilboa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Och höggo honom hans hufvud af, och drogo af honom hans vapen, och sände i de Philisteers land allt omkring, till att förkunna det i deras gudars husom, och ibland folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Och lade hans harnesk i Astaroths hus; men hans kropp hängde de upp på muren i Bethsan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Då de i Jabes och Gilead hörde, hvad de Philisteer hade gjort Saul,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Reste sig upp alle de som striddogse män voro, och gingo den hela nattena, och togo Sauls och hans söners kroppar ned af muren i Bethsan, och förde dem till Jabes, och brände dem der upp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Och togo deras ben, och begrofvo dem under ett trä i Jabes; och fastade i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Efter Sauls död, då David igenkommen var ifrå de Amalekiters slagtning, och hade blifvit två dagar i Ziklag,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Si, på tredje dagen kom en man ifrå Sauls här, med sönderrifven kläder, och jord på hans hufvud. Och som han kom till David, föll han ned på jordena, och tillbad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Men David sade till honom: Hvadan kommer du? Han sade till honom: Ifrån Israels här hafver jag flytt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'David sade till honom: Säg mig, huru tillgånget är. Han sade: Folket är flydt af stridene, och mycket folk är fallet; dertill är ock Saul död, och hans son Jonathan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'David sade till den ynglingen, som detta bådade: Hvaraf vetst du, att Saul och hans son Jonathan äro döde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Ynglingen, som detta bådade, sade: Jag kom oförvarandes upp på Gilboa berg; och si, Saul böjde sig neder på sitt spjut, och vagnar och resenärer jagade efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Och han vände sig om, och fick se mig, och kallade mig, och jag sade: Här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Och han talade till mig: Ho äst du? Jag sade till honom: Jag är en Amalekit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Och han sade till mig: Kom hit till mig, och dräp mig; ty ångest hafver begripit mig; ty mitt lif är ännu allt helt i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Så gick jag till honom, och drap honom; förty jag visste väl, att han icke skulle kunna lefva efter hans fall; och jag tog kronona af hans hufvud, och armsmidet af hans arm, och hafver burit det hit till dig, min herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Då fattade David sin kläder, och ref dem sönder, och alle de män, som när honom voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Och jämrade sig, och greto, och fastade allt intill aftonen öfver Saul och Jonathan hans son; och öfver Herrans folk, och öfver Israels hus, att de genom svärd fallne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Och David sade till ynglingen, som honom det bådat hade: Hvadan äst du? Han sade: Jag är en främling, en Amalekits son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'David sade till honom: Hvi hafver du icke fruktat dig komma dina hand vid Herrans smorda, till att dräpa honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Och David sade till en af sina unga män: Fram, och slå honom. Och han slog honom, att han blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Då sade David till honom: Ditt blod vare öfver ditt hufvud; ty din mun hafver talat emot dig sjelf, och sagt: Jag hafver dräpit Herrans smorda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Och David klagade denna klagan öfver Saul och Jonathan hans son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Och befallde, att man skulle lära Juda barn bågan: Si, det är skrifvet uti den redeligas bok:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'De ädlaste i Israel äro slagne på din berg; huru äro de hjeltar fallne!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Bebåder det icke i Gath, förkunner det icke på gatomen i Askelon; på det att de Philisteers döttrar sig icke fröjda skola, att de oomskornas döttrar icke glädjas skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'I Gilboa berg, komme på eder hvarken dagg eller regn, icke heller vare åkrar, der häfoffer af kommer; förty der är de hjeltars sköld afslagen, Sauls sköld, likasom han icke hade varit smord med oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Jonathans båge felade icke, och Sauls svärd kom aldrig fåfängt igen ifrå de slagnas blod, och ifrå de hjeltars fetma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul och Jonathan, ljuflige och täcke medan de lefde, äro också icke åtskiljde i döden; raskare än örnar, och starkare än lejon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'I Israels döttrar, gråter öfver Saul, den eder klädde med rosenfärgo i kräselighet, och prydde eder med gyldene klenodier på edor kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Huru äro de hjeltar så fallne i stridene; Jonathan är slagen på dina högar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Jag sörjer om dig, min broder Jonathan; du hafver varit mig mycket kär; din kärlek var mig närmare än qvinnokärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Huru äro de hjeltar fallne, och vapnen borto blefne!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Sedan detta skedt var, frågade David Herran, och sade: Skall jag draga upp uti någon af Juda städer? Och Herren sade till honom: Drag ditupp. David sade: Hvart? Han sade: Till Hebron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Så drog då David dit med sina två hustrur, Ahinoam den Jisreelitiskon, och Abigail, Nabals den Carmelitens hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Dertill hade han ock de män upp med sig, som när honom voro, hvar och en med sitt hus; och bodde i Hebrons städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Och de män af Juda kommo, och smorde der David till Konung öfver Juda hus. Och då David vardt bådadt, att de af Jabes i Gilead hade begrafvit Saul,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Sände han båd till dem, och lät säga dem: Välsignade varen I Herranom, att I denna barmhertighet hafven gjort på edar herra Saul, och begrafvit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Så göre nu Herren med eder barmhertighet och trohet; och jag skall ock desslikes göra eder godt, att I detta gjorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Så vare nu edra händer trösta, och står faste; efter edar herre Saul är död, så hafver nu Juda hus smort mig till Konung öfver sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Men Abner, Ners son, som Sauls höfvitsman var, tog Isboseth, Sauls son, och förde honom genom Mahanaim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Och gjorde honom till Konung öfver Gilead, Assuri, Jisreel, Ephraim, BenJamin, och öfver hela Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Och Isboseth, Sauls son, var fyratio år gammal, då han blef Konung öfver Israel, och regerade i tu år; men Juda hus höll med David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Och den tiden, som David var Konung i Hebron öfver Juda hus, var sju år och sex månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Och Abner, Ners son, drog ut med Isboseths, Sauls sons, tjenare, utu Mahanaim till Gibeon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Och Joab, ZeruJa son, drog ut med Davids tjenare, och mötte hvarannan vid dammen i Gibeon; och lade sig, desse på denna sidone vid dammen, och de andre på den andra sidone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Och Abner sade till Joab: Låt de unga män stå, upp och spela för oss. Joab sade: Det må väl vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Så stodo de upp, och gingo fram tolf i talet utaf BenJamin, på Isboseths, Sauls sons, sido, och tolf af Davids tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Och hvardera tog den andra vid halsen, och stötte honom svärdet i hans sido; och föllo den ene med den andra; deraf det rummet kallas HelkathHazurim, hvilket i Gibeon är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Och begyntes en ganska hård strid på den dagen; men Abner och de män af Israel vordo slagne för Davids tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Och tre ZeruJa söner voro der, Joab, Abisai och Asahel; men Asahel var snar till fötter, såsom en rå på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Han jagade efter Abner, och vek icke, hvarken på den högra sidon eller den venstra, ifrån Abner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Då vände Abner sig om, och sade: Äst du Asahel? Han sade: Ja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abner sade till honom: Gif dig ifrå mig, antingen på högra sidon eller den venstra, och tag dig före någon af de unga karlar, och tag honom harnesket af. Men Asahel ville icke vika ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Då sade Abner ytterligare till Asahel: Gif dig ifrå mig, hvi vill du att jag skall slå dig till markena? Och huru skulle jag töra häfva mitt ansigte upp för dinom broder Joab?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Men han ville ingalunda vika. Då stack Abner honom bakom sig med ett spjut i hans buk, så att spjutet gick bak ut, och han föll, och blef der död för honom; och hvilken som kom till det rummet, der Asahel låg död, han stod der stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Men Joab och Abisai jagade efter Abner, intill solen gick ned; och de kommo på det berget Amma, som ligger för Giah, på den vägen till Gibeons öken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Då församlade sig BenJamins barn bakför Abner, och vordo till en hop, och gingo öfverst på en hög.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Och Abner ropade till Joab, och sade: Skall då svärdet fräta utan ända? Vetst du icke, att det vill på sistone skarpt varda? Huru länge vill du icke säga folkena, att de låta af fördölja sina bröder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joab sade: Så sant som Gud lefver, hade du bittida i dag sagt detta till mig, folket hade väl aflåtit att förfölja hvar och en sin broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Och Joab blåste i basunen, och allt folket blef stilla ståndandes, och jagade intet mer efter Israel; och stridde ej heller mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Men Abner och hans män gingo den hela nattena öfver slättmarkena, och drogo öfver Jordan, och vandrade genom hela Bithron, och kommo till Mahanaim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Men Joab vände sig ifrån Abner, och församlade hela folket; och der saknades af Davids tjenare nitton män, och Asahel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Och Davids tjenare hade slagit af BenJamin och Abners män, så att trehundrad och sextio män voro döde blefne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Och de togo Asahel upp, och begrofvo honom i hans faders graf i BethLehem. Och Joab med sina män gingo den hela nattena, och kommo i morgonlysningene till Hebron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Och det var ett långt örlig emellan Sauls hus och Davids hus; men David gick och förkofrades, och Sauls hus gick tillbaka och förminskades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Och David vordo födde bara i Hebron: hans förstfödde son Ammon, utaf Ahinoam den Jisreelitiskon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Den andre Chileab, utaf Abigail, Nabals hustru den Carmelitens; den tredje Absalom, Maachas son, Thalmai dotters, Konungens i Gesur;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Den fjerde Adonia, Haggiths son; den femte SephatJa, Abitals son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Den sjette Jithream, utaf Egla, Davids hustru. Desse äro födde David i Hebron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Som nu örlig var emellan Sauls hus och Davids hus, förstärkte Abner Sauls hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Och Saul hade ena frillo benämnd Rizpa, Aja dotter; och Isboseth sade till Abner: Hvi sofver du när mins faders frillo?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Då vardt Abner ganska vred af denna Isboseths ord, och sade: Är jag då ett hundahufvud, jag som emot Juda gör barmhertighet på dins faders Sauls hus, och på hans bröder och vänner, och hafver icke gifvit dig i Davids händer; och du räknar mig i dag en ogerning till för en qvinnos skull?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Gud göre med Abner det och det, om jag icke gör, såsom Herren David svorit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Att riket skall tagas ifrån Sauls hus; och Davids stol skall uppsätter varda öfver Israel och Juda, ifrå Dan allt intill BerSaba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Och han kunde icke mer svara honom ett ord; ty han fruktade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Och Abner sände båd för sig till David, och lät säga honom: Hvem hörer landet till? Och sade: Gör ditt förbund med mig; si, min hand skall vara med dig, så att jag vill vända till dig hela Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Han sade: Ja väl, jag vill göra förbund med dig; men ett beder jag af dig, att du icke ser mitt ansigte, förra än du förer till mig Michal, Sauls dotter, när du kommer till att se mitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Sände ock David båd till Isboseth, Sauls son, och lät säga honom: Få mig mina hustru Michal, den jag mig fast hafver med hundrade Philisteers förhudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Isboseth sände åstad, och lät taga henne ifrå mannen Phaltiel, Lais son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Och hennes man gick med henne, och gret efter henne, allt intill Bahurim. Då sade Abner till honom: Vänd om, och gack dina färde. Och han vände om igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Och Abner hade ett tal med de äldsta i Israel, och sade: I hafven länge tillförene åstundat David, att han måtte vara Konung öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Så görer ock så nu; förty Herren hafver sagt om David: Jag skall frälsa mitt folk Israel, genom min tjenares Davids hand, utu de Philisteers hand, och utur alla deras fiendars hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Talade ock Abner för BenJamins öron; och gick desslikes bort till att tala för Davids öron i Hebron, allt det Israel och hela BenJamins hus täcktes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Då nu Abner kom till David i Hebron, och tjugu män med honom, gjorde David dem ett gästabåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Och Abner sade till David: Jag vill stå upp, och gå bort till att församla hela Israel till min herra Konungen, och att de skola göra ett förbund med dig; på det du må vara en Konung, såsom din själ det begärar. Så lät då David Abner gå ifrå sig med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Och si, Davids tjenare och Joab kommo ifrå krigsfolket, och hade ett stort rof med sig; men Abner var icke nu qvar när David i Hebron, utan han hade låtit honom ifrå sig, så att han med frid bortgången var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Då nu Joab, och hela hären med honom, var kommen, vardt honom sagdt, att Abner, Ners son, var kommen till Konungen, och han hade låtit honom ifrå sig, så att han var med frid bortgången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Så gick Joab in till Konungen, och sade: Hvad hafver du gjort? Si, Abner är kommen till dig: Hvi hafver du släppt honom ifrå dig, så att han är bortgången?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Känner du icke Abner, Ners son? Ty han är kommen till att bedraga dig, att han må bespeja din utgång och ingång, och få veta allt det du gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Och som Joab utgick ifrån David, sände han båd efter Abner, att de skulle hem ta honom igen ifrå BorHasira; och David visste der intet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Som nu Abner igenkom till Hebron, hade Joab honom midt uti porten, att han skulle tala med honom enskildt; och stack honom der i buken, så att han blef död, för hans broders Asahels blods skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'När nu David detta hörde, sade han: Jag är oskyldig, och mitt rike, för Herranom evinnerliga, för Abners, Ners sons, blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Men det komme öfver Joabs hufvud, och öfver hela hans faders hus; och vände icke åter i Joabs hus, den som en etterflöd och spitelsko hafver, och den som sländo håller, och den genom svärd faller och den som bröd fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Alltså dråpo Joab och hans broder Abisai Abner, derföre att han slog deras broder Asahel ihjäl, i stridene vid Gibeon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Men David sade till Joab, och allt folket som med honom var: Rifver edor kläder sönder, och drager säcker uppå eder, och jämrer eder för Abners skull. Och Konungen gick efter bårena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Och då de begrofvo Abner i Hebron, upphof Konungen sina röst, och gret vid Abners graf; gret ock desslikes allt folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Och Konungen beklagade sig öfver Abner, och sade: Abner är icke död såsom en dåre dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Dina händer voro intet bundna; dina fötter voro intet satte i fjettrar; du äst fallen, såsom man faller för arga skalkar. Då begret folket honom än mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Då nu allt folket kom in med David till att äta, och ännu bittida dags var, svor David, och sade: Gud göre mig det och det, om jag bröd eller något annat smakar, förrän solen nedergår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Och allt folket visste det, och det behagade dem väl allt det goda, som Konungen gjorde för hela folksens ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Och allt folket och hela Israel märkte på den dagen, att det var icke af Konungenom, att Abner, Ners son, vardt dräpen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Och Konungen sade till sina tjenare: Veten I icke, att på denna dag är en Förste och stor man fallen i Israel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Och jag är ännu späd, och en smord Konung; men de män ZeruJa söner äro mig allt för hårde; Herren vedergälle honom, som illa gör, efter hans ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Då nu Sauls son hörde, att Abner var död i Hebron, föll honom händer ned, och hela Israel vardt bedröfvad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Så voro två män höfvitsmän öfver krigsfolket under Sauls son; den ena het Baana, den andre Rechab, Rimmons den Beerothitens söner, utaf BenJamins barn; ty Beeroth vardt ock räknad under BenJamin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Och de Beerothiter voro flydde till Gitthaim, och der främlingar vordne, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Hade ock Jonathan, Sauls son, en son; han var ofärdig i fötterna, och var fem åra gammal, då tidenden kommo om Saul och Jonathan utaf Jisreel; och hans amma tog honom upp, och flydde; och i det hon hastade, och flydde, föll han, och vardt halt; och han het MephiBoseth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Så gingo nu Rimmons den Beerothitens söner, Bechab och Baana, bort, och kommo till Isboseths hus, då dagen var hetast; och han låg på sine säng om middagen, och sof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Och de kommo i huset till att hem ta hvete; och stungo honom i buken, och rymde sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Ty då de kommo i huset, låg han på sine säng i sin sängakammar, och de stungo honom ihjäl, och höggo honom hufvudet af; och togo hans hufvud, och gingo bort den vägen på slättmarkene, i den hela nattene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Och båro Isboseths hufvud till David i Hebron, och sade till Konungen: Si, der är Isboseths hufvud, Sauls sons, din fiendas, som stod efter dina själ; Herren hafver i dag hämnat min herra Konungen på Saul och hans säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Då svarade David, och sade till dem: Så visst som Herren lefver, som mina själ utur all bedröfvelse frälst hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Den som mig bådade, och sade: Saul är död, och mente att han var ett godt bådskap, den tog jag fatt, och drap honom i Ziklag, den jag skulle tidendeslön gifvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Och desse ogudaktige männerna hafva ihjälslagit en oskyldig man, uti hans hus, på hans säng? Ja, skulle jag icke utkräfva hans blod utur edra händer, och taga eder utaf jordene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Och David böd sina unga män, och de slogo dem ihjäl, och höggo dem händer och fötter af, och hängde dem vid dammen i Hebron; men Isboseths hufvud togo de, och begrofvo det i Abners graf, i Hebron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Och alla Israels slägter kommo till David i Hebron, och sade: Si, vi äre af ditt ben och ditt kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Dertill ock tillförene, när Saul var Konung öfver oss, förde du Israel ut och in; så hafver nu Herren sagt dig: Du skall vakta mitt folk Israel, och skall vara en höfvitsmän öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Och alle äldste i Israel kommo till Konungen i Hebron; och Konung David gjorde med dem ett förbund i Hebron för Herranom; och de smorde David till Konung öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Tretio åra gammal var David, då han Konung vardt, och regerade i fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'I Hebron regerade han i sju år och sex månader, öfver Juda; men i Jerusalem regerade han i tre och tretio år, öfver hela Israel och Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Och Konungen drog bort med sina män till Jerusalem, emot de Jebuseer, som bodde der i landena. Men de sade till David: Du skall icke komma härin, utan blinde och halte skola drifva dig af. Och deras mening var, att David skulle icke komma derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Men David vann borgena Zion; det är Davids stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Då sade David på den dagen: Den som slår de Jebuseer, och kommer upp till takrännorna; de halta och blinda, hvilka Davids själ hatar. Deraf säger man: Låt ingen blindan eller haltan komma i huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Så bodde då David på borgene, och kallade henne Davids stad; och David byggde omkring, ifrå Millo och innanföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Och David gick, och förkofrade sig; och Herren Gud Zebaoth var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Och Hiram, Konungen i Tyro, sände båd till David, och cederträ till väggar, och timbermän och stenhuggare, att de skulle bygga David ett hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Och David förmärkte, att Herren hade stadfäst honom för en Konung öfver Israel, och upphöjt hans rike för sitt folk Israels skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Och David tog ännu flera hustrur och frillor i Jerusalem, sedan han var kommen ifrå Hebron; och honom vordo ännu flere söner och döttrar födde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Och detta är deras namn, som honom födde voro i Jerusalem: Sammua, Sobab, Nathan, Salomo,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibehar, Elisua, Nepheg, Japhia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eljada, Eliphalet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Och då de Philisteer hörde, att man hade smort David till Konung öfver Israel, drogo de alle upp till att söka David. Då David det förnam, drog han neder till en borg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Men de Philisteer kommo, och lade sig neder i den dalenom Rephaim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Och David frågade Herran, och sade: Skall jag draga upp emot de Philisteer, och vill du gifva dem i mina hand? Herren sade till David: Drag ditupp; jag vill gifva de Philisteer i dina hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Och David kom till BaalPerazim, och slog dem der, och sade: Herren hafver förskingrat mina fiendar för mig ifrå, hvarannan, såsom vattnen förskingras. Deraf kallar man det samma rummet BaalPerazim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Och de läto der deras afgudar; men David och hans män togo dem bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Men de Philisteer drogo åter upp, och lade sig neder i Rephaims dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Och David frågade Herran. Han sade: Du skall icke draga ditupp; utan kom bakuppå dem, så att du kommer uppå dem in mot päronaträn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Och när du får höra, att det ruskar öfverst uppe i skatarna af päronaträn, så var vid ett friskt mod; ty Herren är då utgången för dig, till att slå de Philisteers här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David gjorde som Herren honom budit hade, och slog de Philisteer, ifrå Geba allt intilldess man kommer till Gaser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Och David samlade åter alla de unga män i Israel, tretiotusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Och stod upp, och gick bort med allt det folk, som när honom var af Juda män, att han skulle hemta dädan Guds ark, hvilkens namn heter: Herrans Zebaoths Namn bor deruppå öfver Cherubim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Och de satte Guds ark uppå en ny vagn, och hemtade honom utur AbiNadabs hus, som bodde i Gibea; men Ussa och Ahio, AbiNadabs söner, drefvo den nya vagnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Och de förde honom med Guds ark utur AbiNadabs hus, som i Gibea bodde; och Ahio gick framför arkenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Då spelade David och hela Israels hus för Herranom, med allahanda strängaspel af granträ, med harpor, och psaltare, och trummor, och bjellror, och cymbaler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Och då de kommo till Nachons lado, tog Ussa till, och höll Guds ark; ty oxarna gingo afsides utaf vägenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Då förgrymmade sig Herrans vrede öfver Ussa, och Gud slog honom der för hans öfverdådighets skull, så att han blef der död vid Guds ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Då var David bedröfvad, att Herren så sönderref Ussa. Och vardt det samma rummet kalladt Perez Ussa allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Och David fruktade sig för Herranom på den dagen, och sade: Huru skall Herrans ark komma till mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Och ville icke låta bära honom till sig in i Davids stad; utan lät bära honom uti ObedEdoms den Gitthitens hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Och då Herrans ark blef i tre månader uti ObedEdoms den Gitthitens hus, välsignade Herren honom, och allt hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Och det vardt sagdt Konung David, att Herren hade välsignat ObedEdoms hus, och allt det han hade, för Guds arks skull. Då gick han bort, och hemtade Guds ark utur ObedEdoms hus, upp uti Davids stad, med fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Och som de voro framgångne vid sex tren med Herrans ark, offrade man en oxa och ett fett får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Och David dansade med allo magt för Herranom, och hade klädt uppå sig en linnan lifkjortel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Och David samt hela Israel förde Herrans ark upp, med trummeter och basuner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Och då Herrans ark kom in uti Davids stad, såg Michal, Sauls dotter, ut genom fenstret, och såg Konung David springa och dansa för Herranom; och föraktade honom i sitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'När de nu båro Herrans ark in, satte de honom på sitt rum midt i tabernaklet, som David för honom uppslagit hade. Och David offrade bränneoffer och tackoffer för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Och då David hade utoffrat bränneoffer, och tackoffer, välsignade han folket i Herrans Zebaoths Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Och utskifte allo folkena och Israels menighet, både man och qvinno, hvarjom och enom ett bröd, och ett stycke kött, och ett mått vin; sedan gick allt folket sin väg, hvar och en i sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Men då David igenkom, till att välsigna sitt hus, gick Michal, Sauls dotter, ut emot honom, och sade: Huru härlig hafver Israels Konung varit i dag, som sig blottat hafver för sina tjenares tjensteqvinnor, såsom lösaktiga menniskor sig blotta!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Men David sade till Michal: Jag skall spela för Herranom, den mig utvalt hafver, heldre än din fader, och heldre än allt hans hus, så att han hafver mig befallt vara en Förste öfver Herrans folk öfver Israel; ja, för Herranom vill jag spela;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Och vill ännu ringare varda än så, och vill nedrig vara i min ögon, och med de tjensteqvinnor, som du af sagt hafver, till äro komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Och Michal, Sauls dotter, hade intet barn intill hennes dödsdag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Då nu Konungen satt i sitt hus, och Herren hade honom ro gifvit för alla hans fiendar allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Sade han till den Propheten Nathan: Si, jag bor uti cedrehus, och Guds ark bor under tapeter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Nathan sade till Konungen: Gack, allt det du hafver i ditt hjerta, det gör; ty Herren är med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Men om natten kom Herrans ord till Nathan, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Gack och säg till min tjenare David: Detta säger Herren: Skulle du bygga mig ett hus, att jag deruti bo skulle?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Hafver jag dock intet bott i något hus, ifrå den dag, jag förde Israels barn utur Egypten, allt intill denna dag; utan jag hafver vandrat i tabernakel och hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Ehvart jag med alla Israels barn vandrade, hafver jag ock någon tid talat med någro Israels slägt, den jag befallt hafver att föda mitt folk, och sagt: Hvi hafven I icke byggt mig ett cedrehus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Så skall du nu säga minom tjenare David: Detta säger Herren Zebaoth: Jag hafver tagit dig utaf markene, der du gick efter fåren, att du skulle vara en Förste öfver mitt folk Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Och hafver varit med dig, ehvart du gångit hafver; och hafver utrotat alla dina fiendar för dig, och hafver gjort dig ett stort namn, såsom de storas namn på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Och jag vill sätta mino folke Israel ett rum, och plantera det så, att det skall der blifva, och icke yttermera rördt varda; och orättfärdighetenes barn skola icke mera tränga det, såsom tillförene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Och ifrå den tid jag skickade domare öfver mitt folk Israel; och jag skall gifva dig ro för alla dina fiendar. Och Herren förkunnar dig, att Herren vill göra dig ett hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'När nu din tid förliden är, att du afsomnad äst med dina fäder, skall jag uppväcka dina säd efter dig, som af ditt lif komma skall; honom skall jag stadfästa hans rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Han skall bygga mino Namne ett hus; och jag skall stadfästa hans rikes stol till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Jag skall vara hans fader, och han skall vara min son; om han gör något illa, skall jag straffa honom med menniskoris, och med menniskors barnas hugg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Men min barmhertighet skall icke ifrå honom vänd vara, såsom jag vände henne ifrå Saul, den jag för dig borttagit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Men ditt hus och ditt rike skall blifva ståndandes för dig evinnerliga; och din stol skall stadig blifva till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Då nu Nathan hade sagt David all dessa orden, och alla denna synena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Kom Konung David, och satte sig för Herranom, och sade: Ho är jag, Herre, Herre? Och hvad är mitt hus, att du hafver låtit mig komma härtill?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Dertill hafver det icke tyckt dig vara nog, Herre, Herre; utan du hafver ock talat till dins tjenares hus om tillkommande ting i längdene. Är det menniskorätt, Herre, Herre?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Och hvad skulle David mer tala med dig? Du känner din tjenare, Herre, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'För ditt ords skull, och efter ditt hjerta hafver du all denna stora tingen gjort, att du det dinom tjenare förkunna ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Derföre äst du ock mycket aktad, Herre Gud; ty det är ingen såsom du, och är ingen Gud, utan du, efter allt det vi med vår öron hört hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Förty hvar är ett folk på jordene, såsom ditt folk Israel? För hvilkets skull Gud är gången till att förlossa sig ett folk, och göra sig ett Namn, och göra sådana stor och förskräckelig ting på ditt land för dino folke, som du dig förlossade utur Egypten, ifrå Hedningarna och deras gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Och du hafver tillredt dig ditt folk Israel, dig till folk i evig tid; och du, Herre, äst deras Gud vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Så stadfäst nu, Herre Gud, ordet i evighet, det du öfver din tjenare, och öfver hans hus sagt hafver, och gör såsom du sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Så blifver ditt Namn stort i evighet, så att man skall säga: Herren Zebaoth är Gud öfver Israel; och dins tjenares Davids hus varder fast för ditt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Ty du, Herre Zebaoth, du Israels Gud, hafver öppnat dins tjenares öra, och sagt: Jag skall bygga dig ett hus; derföre hafver din tjenare funnit sitt hjerta, att han denna bönena till dig bedja skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Nu, Herre, Herre, du äst Gud, och din ord skola vara sanning; du hafver detta goda talat öfver din tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Så tag nu till, och välsigna dins tjenares hus, att det blifver evigt för dig; ty du Herre, Herre, hafver det talat; och med din välsignelse skall dins tjenares hus välsignadt varda till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Och det begaf sig derefter, att David slog de Philisteer, och förnedrade dem, och tog träldomsbetslet utu de Philisteers hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Han slog ock de Moabiter så till jordena, att han två delar drap, och en del lät lefvandes blifva. Alltså vordo de Moabiter David underdånige, så att de förde skänker till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David slog ock HadadEser, Rehobs son, Konungen i Zoba, då han drog ut till att hemta sin magt igen, vid den älfven Phrath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Och David fångade af dem tusende och sjuhundrad resenärar, och tjugutusend fotfolk; och hasade alla vagnhästar, och behöll qvar hundrade vagnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Så kommo de Syrer af Damascon, till att hjelpa HadadEser, Konungen i Zoba; och David slog de Syrer, tu och tjugu tusend män;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Och lade folk till Damascon i Syria. Alltså vardt Syria David underdånig, så att de förde skänker till honom; ty Herren halp David, ehvart han drog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Och David tog de gyldene sköldar, som HadadEsers tjenare tillhört hade, och förde dem till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Men ifrå Bethah, och Berothai, HadadEsers städer, tog Konung David ganska mycken koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Då Thoi, Konungen i Hemath, hörde att David hade slagit alla HadadEsers magt,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Sände han Joram sin son till David, till att helsa honom vänliga, och välsigna honom, att han hade stridt med HadadEser, och slagit honom; ty Thoi hade örlig med HadadEser, och han hade med sig silfver, och gyldene, och koppartyg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Hvilka Konung David ock helgade Herranom, samt med det silfver och guld, som han helgade af allom Hedningom, dem han under sig tvingade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Af Syria, af Moab, af Ammons barn, af de Philisteer, af Amalek, af HadadEsers rof, Rehobs sons, Konungens i Zoba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Och gjorde David sig ett namn, då han igenkom och slog de Syrer i saltdalenom, adertontusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Och han lade folk i hela Edomea; och hela Edom var David undergifven; ty Herren halp David, ehvart han drog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Alltså vardt David Konung öfver hela Israel; och han skaffade rätt och rättviso allo folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab, ZeruJa son, var öfver hären; men Josaphat, Ahiluds son, var canceller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Zadok, Ahitobs son, och Ahimelech, AbJathars son, voro Prester; Seraja var skrifvare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, Jojada son, var öfver Crethi och Plethi; och Davids söner voro Prester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Och David sade: Månn ock någor vara qvar af Sauls hus, att jag måtte göra barmhertighet med honom, för Jonathans skull?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Så var en tjenare af Sauls hus, benämnd Ziba, den kallade de till David; och Konungen sade till honom: Äst du Ziba? Han sade: Ja, din tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Konungen sade: Är ännu någor till af Sauls hus, att jag måtte göra barmhertighet med honom? Ziba sade till Konungen: Det är ännu en till, Jonathans son, ofärdig i fötterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Konungen sade till honom: Hvar är han? Ziba sade till Konungen: Si, han är i Lodebar, i Machirs hus, Ammiels sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Då sände Konung David bort, och lät hemta honom ifrå Lodebar, utu Machirs hus, Ammiels sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Då nu MephiBoseth, Jonathans son, Sauls sons, kom till David, föll han på sitt ansigte, och tillbad. Och David sade: MephiBoseth. Han sade: Här är jag, din tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'David sade till honom: Frukta dig intet; ty jag vill göra barmhertighet på dig, för Jonathans dins faders skull, och vill gifva dig alla dins faders Sauls åkrar igen; men du skall dageliga äta bröd vid mitt bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Han tillbad, och sade: Ho är jag, din tjenare, att du vände dig till en död hund, såsom jag är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Då kallade Konungen Ziba, Sauls tjenare, och sade till honom: Allt det Saul hafver tillhört, och hans hela hus, hafver jag gifvit dins herras son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Så bruka nu honom hans åker, du och din barn, och tjenare, och låt det komma in, att det skall vara dins herras sons bröd, att han må föda dig; men MephiBoseth dins herras son skall dagliga äta bröd vid mitt bord. Och Ziba hade femton söner och tjugu tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Och Ziba sade till Konungen: Allt det min herre Konungen hafver budit sinom tjenare, det skall hans tjenare göra; och MephiBoseth äte vid mitt bord, såsom ett af Konungsbarnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Och MephiBoseth hade en liten son, som het Micha; men allt det i Ziba hus bodde, det tjente MephiBoseth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Och MephiBoseth bodde i Jerusalem; ty han åt dagliga vid Konungens bord; och haltade på båda sina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Och det begaf sig derefter, att Ammons barnas Konung blef död, och hans son Hanun vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Då sade David: Jag vill göra barmhertighet på Hanun, Nahas son, såsom hans fader hafver gjort barmhertighet med mig. Och sände bort och lät genom sina tjenare hugsvala honom öfver hans fader. Och Davids tjenare kommo i Ammons barnas land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Då sade de öfverste öfver Ammons barn till sin herra Hanun: Menar du, att David hedrar din fader för din ögon, att han hafver sändt hugsvalare till dig? Menar du icke, att han fördenskull hafver sändt sina tjenare till dig, att han skall utspana och bespeja staden, och förstöra honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Då tog Hanun Davids tjenare, och lät raka dem halft skägget af; och skar half kläden af på dem, allt intill bältet, och lät så gå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Då det vardt bådadt David, sände han emot dem; förty männerna voro ganska mycket skämde. Och Konungen lät säga dem: Blifver i Jericho tilldess edart skägg växer, och kommer så igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Då nu Ammons barn sågo, att de voro illa luktande vordne för David, sände de bort, och lejde sig de Syrer af Rehobs hus, och de Syrer i Zoba, tjugutusend män fotfolk, och af Konung Maacha tusend män, och af Istob tolftusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Då David det hörde, sände han Joab med hela hären af krigsfolket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Och Ammons barn drogo ut, och skickade sig till strid ut för stadsporten; men de Syrer af Zoba, af Rehob, af Istob, och af Maacha, voro allena i markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Då nu Joab såg, att striden var ställd på honom både bak och före, utvalde han utaf alla de unga män i Israel, och skickade sig emot de Syrer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Och det andra folket lät han under sins broders hand Abisai, och han skickade sig emot de Ammons barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Och sade: Om de Syrer varda mig för mägtige, så kom mig till hjelp; om Ammons barn varda dig öfvermägtige, så vill jag komma dig till hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Var vid god tröst, och låt oss stå fasta för vårt folk och för vår Guds städer; men Herren göre hvad honom täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Och Joab drog åstad med det folk, som när honom var, till att strida emot de Syrer; och de flydde för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Och då Ammons barn sågo, att de Syrer flydde, flydde de ock för Abisai, och drogo in i staden. Så vände Joab om ifrån Ammons barn, och kom till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Och då de Syrer sågo, att de voro slagne för Israel, församlade de sig tillhopa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Och HadarEser sände bort, och lät utkomma de Syrer på hinsidon älfven; och lät deras magt inkomma; och Sobach, HadarEsers härhöfvitsman, drog för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Då det vardt bådadt David, församlade han tillhopa hela Israel, och drog öfver Jordan, och kom till Helam; och de Syrer skickade sig emot David, till att strida med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Men de Syrer flydde för Israel, och David slog ihjäl de Syrer sjuhundrad vagnar, och fyratiotusend resenärar; dertill slog han Sobach härhöfvitsmannen, så att han blef der död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Då nu de Konungar, som voro under HadarEser, sågo att de slagne voro för Israel, gjorde de frid med Israel, och vordo dem underdånige; och de Syrer fruktade sig mer hjelpa Ammons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Och då året så led, att Konungar pläga utdraga, sände David Joab, och sina tjenare med honom, och hela Israel, att de skulle förderfva Ammons barn, och de belade Rabba; men David blef i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Och det begaf sig, att David om aftonstid stod upp af sine säng, och gick upp på taket af Konungshuset, och såg af taket ena qvinno två sig; och qvinnan var ganska dägelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Och David sände bort, och lät fråga efter qvinnona, och sade: Är icke detta BathSeba, Eliams dotter, Uria den Hetheens hustru?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Och David sände bort båd, och lät hemta henne; och då hon kom in till honom, sof han när henne; men hon renade sig ifrå sine orenlighet, och gick hem igen till sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Och qvinnan vardt hafvandes, och sände bort, och lät förkunna det David, och säga: Jag är hafvandes vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Så sände David till Joab, och sade: Sänd till mig Uria den Hetheen. Och Joab sände Uria till David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Och då Uria kom till honom, frågade David, om det stod väl till med Joab, och med folket, och med stridene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Och David sade till Uria: Gack af i ditt hus, och två dina fötter. Och då Uria gick utu Konungens hus, följde honom straxt efter Konungens gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Och Uria lade sig till att sofva för dörrene af Konungens hus, der alle hans herras tjenare lågo, och gick intet neder i sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Då nu David sagdt vardt: Uria är icke afgången i sitt hus, sade David till honom: Äst du icke kommen af markene? Hvi äst du icke afgången i ditt hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Men Uria sade till David: Arken, och Israel, och Juda blifva i tjäll, och Joab min Herre, och mins herras tjenare ligga i markene; och jag skulle gå i mitt hus, till att äta och; dricka, och ligga när mine hustru? Så sant som du lefver, och din själ lefver, jag gör det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'David sade till Uria: Så blif ännu i dag här; i morgon vill jag låta dig gå. Så blef Uria i Jerusalem i den dagen, och den andra dagen dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Och David böd honom, att han skulle med honom äta och dricka, och gjorde honom drucken; och om aftonen gick han ut, och lade sig till att sofva i sin säng, med sins herras tjenare, och gick icke af i sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Om morgonen skref David ett bref till Joab, och sände det med Uria.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Och i brefvet skref han alltså: Skicka Uria i stridene, der hon aldrahårdast är; och vänder eder tillbaka ifrå honom, att han måtte varda slagen, och blifva död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Som nu Joab låg för staden, skickade han Uria på det rum, der han visste att stridsamme män voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Och då männerna slogo utu stadenom, och stridde emot Joab, föllo somlige af folket, Davids tjenare; och Uria den Hetheen blef ock död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Så sände Joab bort, och lät säga David all stridsens handel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Och befallde bådet, och sade: När du hafver uttalat all stridsens handel med Konungenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Och du får se, att Konungen är vred, och säger till dig: Hvi hafven I så när trädt intill staden med stridene? Veten I icke huru man plägar skjuta af muren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Ho slog AbiMelech, JeruBeseths son? Kastade icke en qvinna ett stycke af en qvarnsten uppå honom af muren, så att han blef död i Thebez? Hvi hafven I trädt så när muren? Så skall du säga: Din tjenare Uria den Hetheen är ock död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Bådet gick åstad, och kom, och sade David allt detta, der Joab honom om sändt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Och bådet sade till David: De män fingo öfverhanden med oss, och föllo till oss ut på markena; men vi sloge dem tillbaka allt intill stadsporten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Och de skyttar sköto af muren på dina tjenare, och dråpo somliga af Konungens tjenare; dertill är ock din tjenare Uria den Hetheen död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'David sade till bådet: Så skall du säga till Joab: Låt detta icke bekymra dig; ty svärdet uppfräter nu den ena, nu den andra; håll uppå att strida emot staden, att du må nederslå honom, och var tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Och då Uria hustru hörde, att hennes man var död, jämrade hon sig för sin husbondas skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Då hon ut gråtit hade, sände David bort, och lät hemta henne i sitt hus; och hon vardt hans hustru, och födde honom en son; men Herranom misshagade detta ärendet, som David bedref.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Och Herren sände Nathan till David. När han kom till honom, sade han till honom: Det voro två män uti en stad; den ene rik, den andre fattig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Den rike hade ganska mycken får och fä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Men den fattige icke utan ett litet får, hans endesta, hvilket han köpt hade, och uppfödde det, att det uppväxte när honom, och bredovid hans barn. Det åt af hans beta, och drack af hans drickekar, och sof i hans famn, och han höll det såsom ena dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Men då till den rika mannen kom en gäst, nändes han icke taga af sin får och fä, till att tillreda något åt den gästen, som till honom kommen var; och tog den fattiga mannens får, och redde det till för den mannen, som till honom kommen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Då förgrymmade sig David med stora vrede emot den mannen, och sade till Nathan: Så sant som Herren lefver, den mannen är dödsens barn, som detta gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Dertill skall han betala fåret fyradubbelt igen, efter han sådant gjort hafver, och icke hade det fördrag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Då sade Nathan till David: Du äst den mannen. Så säger Herren Israels Gud: Jag hafver smort dig till en Konung öfver Israel, och hafver frälst dig utu Sauls hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Och hafver gifvit dig dins herras hus; dertill hans hustrur i din famn, och hafver gifvit dig Israels hus och Juda; och är det icke nog, vill jag ännu det och det göra dig dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Hvi hafver du då föraktat Herrans ord, att du sådant ondt för hans ögon göra skulle? Uria den Hetheen hafver du slagit med svärd; hans hustru hafver du tagit dig till hustru; men honom hafver du dräpit med Ammons barnas svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Nu, så skall icke svärd återvända af ditt hus till evig tid; efter du hafver föraktat mig, och Uria den Hetheens hustru tagit, att hon skall vara din hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Detta säger Herren: Si, jag skall uppväcka ondt öfver dig, utaf ditt eget hus, och skall taga dina hustrur för din ögon, och skall gifva dinom nästa, att han skall ligga när dina hustrur om ljusa dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Ty du hafver gjort det hemliga; men jag vill detta göra för hela Israel, på ljusa dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Då sade David till Nathan: Jag hafver syndat emot Herranom. Nathan sade till David: Så hafver ock Herren tagit din synd bort; du skall icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Men efter du hafver med detta ärendet kommit Herrans fiendar till att förhäda, skall den sonen, som dig födder är, döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Och Nathan gick hem i sitt hus. Men Herren slog barnet, som Uria hustru David födt hade, så att det vardt dödssjukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Och David bad Gud om barnet, och fastade, och gick in, och låg öfver natt ena på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Då stodo upp de äldste i hans hus, och ville rätta honom upp af jordene; men han ville icke, och åt icke heller med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'På sjunde dagenom blef barnet dödt; och Davids tjenare torde icke säga honom att barnet var dödt; ty de tänkte: Si, då barnet ännu var lefvandes, talade vi med honom, och han hörde vår röst intet; huru mycket mer skall det göra honom ondt, om vi säge: Barnet är dödt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Och David fick se att hans tjenare talade i mjugg, och förmärkte att barnet var dödt, och sade till sina tjenare: Är barnet dödt? De sade: Ja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Då stod David upp af jordene, och tvådde sig, och smorde sig, och lade annor kläder uppå, och gick in uti Herrans hus, och tillbad; och då han kom hem igen i sitt hus, lät han komma mat upp för sig, och åt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Då sade hans tjenare till honom: Hvad är det för ett ting, som du gör? Då barnet lefde, fastade du, och gret; men nu, sedan det dödt är, står du upp, och äter!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Han sade: För barnets skull fastade jag, och gret, då det lefde; ty jag tänkte: Ho vet, om Herren varder mig nådelig, så att barnet må blifva vid lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Men nu, sedan det dödt är, hvad skulle jag fasta? Kan jag ock hemta honom igen? Jag går väl till honom, men han kommer intet till mig igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Och då David hade hugsvalat sina hustru BathSeba, gick han in till henne, och sof när henne; och hon födde en son, den kallade han Salomo; och Herren älskade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Och han fick honom under Nathans hand, Prophetens; han kallade honom JedidJa, för Herrans skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Så stridde nu Joab emot Rabba Ammons barnas, och vann den Konungsliga staden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Och sände båd till David, och lät säga honom: Jag hafver stridt emot Rabba, och hafver ock vunnit vattustaden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Så tag nu tillhopa det folk, som qvart är, och belägg staden, och vinn honom; på det att jag icke vinner honom, och får der namnet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Alltså tog David allt folket tillhopa, och drog åstad, och stridde emot Rabba, och vann honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Och tog deras Konungs krono utaf hans hufvud, hvilken hade i vigt en centener guld, och ädla stenar; och den vardt satt David på hans hufvud; och förde ganska mycket rof utu staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Och folket derinne förde han ut, och lade dem under jernsågar och taggar, och jernkilar, och brände dem upp uti tegelugnar; så gjorde han alla Ammons barnas städer. Så vände då David och allt folket om igen till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Och det begaf sig derefter, att Absalom, Davids son, hade en dägelig syster, den het Thamar. Och Amnon, Davids son, fick henne kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Och Amnon ställde sig såsom han var sjuk för Thamars sin systers skull; ty hon var en jungfru; och Amnon syntes icke lätt vara att göra henne något.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Men Amnon hade en vän, han het Jonadab, Simea son, Davids broders; och den samme Jonadab var en ganska snäll man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Han sade till honom: Hvi varder du så mager, du Konungens son, dag frå dag? Må du icke säga mig det? Då sade Amnon till honom: Jag hafver Thamar, mins broders Absaloms syster, kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Jonadab sade till honom: Lägg dig på dina säng, och gör dig krank. När då din fader kommer till att besöka dig, så säg till honom: Käre, lät mina syster Thamar komma, att hon gifver mig äta, och reder mat för mig, så att jag ser det, och äter utu hennes hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Så lade Amnon sig, och gjorde sig krank. Då nu Konungen kom till att se honom, sade Amnon till Konungen: Käre, låt mina syster Thamar komma, att hon reder för mig ett mos eller tu, och jag må äta af hennes hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Då sände David efter Thamar i huset, och lät säga henne: Gack i dins broders Amnons hus, och red honom något mat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Thamar gick åstad till sins broders Amnons hus, och han låg på sängene; och hon tog en deg, och knådade, och söd det för hans ögon, och kokade honom ett mos;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Och hon tog den rätten, och gaf upp för honom; men han ville icke ätat. Och Amnon sade: Låt alla gå ut ifrå mig; och alle gingo ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Då sade Amnon till Thamar: Bär maten in i kammaren, att jag må äta af dine hand. Så tog Thamar moset, som hon gjort hade, och bar det till Amnon sin broder i kammaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Och som hon hade burit honom moset in, att han skulle äta, fick han henne fatt, och sade till henne: Hit, min syster, och ligg när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Men hon sade till honom: Icke så, min broder; förkränk mig icke; ty så plägar man icke göra i Israel. Gör icke en sådana galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Hvar skulle jag blifva för mina blygds skull? Och du vorde såsom en dåre i Israel. Tala heldre med Konungenom; han nekar mig dig icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Men han ville icke höra henne; utan vardt henne öfvermägtig, och förnedrade henne, och låg när henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Och han fick ett stort hat till henne, så att hatet vardt större än tillförene kärleken var. Och Amnon sade till henne: Statt upp, och gack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Men hon sade: Detta onda är större, än det andra, som du hafver gjort på mig, att du drifver mig ut. Men han hörde hennes röst intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Utan kallade sin dräng, som hans tjenare var, och sade: Drif denna ut ifrå mig, och stäng igen dörrena efter henne,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Och hon hade en brokot kjortel uppå; ty sådana kjortlar drogo Konungens döttrar, så länge de voro jungfrur. Och då hans tjenare hade drifvit henne ut, och stängt dörrena igen efter henne,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Kastade Thamar asko på sitt hufvud, och ref den brokota kjortelen sönder, som hon uppå hade, och lade sina hand på hufvudet, och gick, och ropade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Och hennes broder Absalom sade till henne: Hafver din broder Amnon varit när dig? Nu, min syster, tig stilla; det är din broder, och lägg det ärendet icke så på hjertat. Så blef Thamar ensam i Absaloms sins broders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Och då Konung David allt detta hörde, tog han det ganska illa vid sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Men Absalom talade intet vid Amnon, hvarken ondt eller godt; dock hatade Absalom Amnon, derföre att han hans syster Thamar förkränkt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Efter tu år lät Absalom klippa sin får i BaalHazor, som ligger under Ephraim; och Absalom böd all Konungens barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Och kom till Konungen, och sade: Si, din tjenare hafver fåraklippare. Jag beder att Konungen, samt med sina tjenare, ville gå med sinom tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Men Konungen sade till Absalom: Icke så, min son; låt oss icke alla gå, att vi icke göra dig tunga; och då han föll hårdt efter honom, ville han dock icke gå, utan välsignade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Absalom sade: Skall icke då min broder Amnon gå med oss? Konungen sade till honom: Hvi skulle han gå med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Då nödgade Absalom honom, så att han lät Amnon och all Konungens barn gå med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Och Absalom böd sina tjenare, och sade: Tager vara uppå, när Amnon varder glad af vinet, och jag säger till eder: Slår Amnon; och dräper honom, att I intet frukten eder, ty jag hafver det befallt eder; varer tröste och frimodige dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Alltså gjorde Absaloms tjenare Amnon, såsom Absalom dem budit hade. Då stodo all Konungens barn upp, och hvar och en satte sig på sin mula, och flydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Och medan de ännu voro på vägenom, kom rykte för David, att Absalom hade slagit all Konungens barn, så att icke en var öfverblifven af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Då stod Konungen upp, och ref sin kläder sönder, och lade sig neder på jordena; och alle hans tjenare, som stodo omkring honom, refvo sin kläder sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Då svarade Jonadab, Simea son, Davids broders, och sade: Min herre tänke icke att alle drängerne, Konungens barn, äro döde; utan Amnon är allena död; ty Absalom hafver detta haft inne med sig, ifrå den dagen han förkränkte hans syster Thamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Så tage icke nu min herre Konungen sådant till hjertat, att all Konungens barn äro döde; utan Amnon är allena död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Men Absalom flydde; och drängen på vaktene lyfte upp sin ögon, och såg ut; och si, en stor hop folk kom på vägenom, hvar efter den andra, utmed bergssidon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Då sade Jonadab till Konungen: Si, Konungens barn komma; såsom din tjenare sagt hafver, så är det tillgånget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Och då han uttalat hade, si, då kommo Konungens barn, och upphofvo sina röst, och greto. Konungen och alle hans tjenare greto ock ganska fast.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Men Absalom flydde, och drog till Thalmai, Ammihuds son, Konungen i Gesur. Men han jämrade sig öfver sin son alla dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Men då Absalom flydd var, och drog till Gesur, var han der i tre år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Och Konung David öfvergaf att draga ut emot Absalom; ty han var hugsvalad öfver Amnon, att han död var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Men Joab, ZeruJa son, förmärkte att Konungens hjerta var vändt till Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Och han sände bort till Thekoa, och lät hämta dädan ena kloka qvinno, och sade till henne: Jämra dig, och drag sorgkläder uppå, och smörj dig icke med oljo; utan ställ dig såsom en qvinna, den en lång tid hafver haft sorg öfver någon dödan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Och skall gå in till Konungen, och tala så och så med honom. Och Joab gaf henne in hvad hon säga skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Och då Qvinnan af Thekoa ville tala med Konungenom, föll hon på sitt anlete neder på jordena, och tillbad, och sade: Hjelp mig, Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Konungen sade till henne: Hvad är dig? Hon sade: Jag är en enka, en qvinna som sorg hafver, och min man är död;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Och din tjenarinna hade två söner; de kifvade tillhopa på markene; och efter der var ingen, som dem förtagat kunde, slog den ene den andra, och drap honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Och si, nu reser sig upp hela slägten emot dina tjenarinno, och säga: Få hit den som slog sin broder ihjäl, att vi måge dräpa honom för hans broders själ, den han dräpit hafver, och göra dig arfvingalösa; och de vilja utsläcka mina gnisto, som ännu qvar är, att minom man intet namn och ingen återlefva blifva skall på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Konungen sade till qvinnona: Gack hem, jag vill bjuda för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Och qvinnan af Thekoa sade till Konungen: Min herre Konung, missgerningen vare uppå mig, och uppå mins faders hus; men Konungen och hans stol vare oskyldig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Konungen sade: Den som emot dig talar, honom haf till mig, så skall han intet mer röra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Hon sade: Konungen tänke på Herran din Gud, att de blodhämnare icke varda för månge till att förderfva, och att min son icke förgörs. Han sade: Så sant som Herren lefver, skall icke ett hår falla på jordene af dinom son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Och qvinnan sade: Låt dina tjenarinno något säga minom herra Konungenom. Han sade: Säg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Qvinnan sade: Hvi hafver du ett sådant tänkt emot Guds folk, att Konungen detta sagt hafver, att han skall komma sig i skuld, och icke låta igentaga sin fördrefna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Ty vi dö döden, och förlöpe såsom vatten i jordena, det man icke uppehåller; och Gud vill icke taga lifvet bort, utan betänker sig, att det fördrefna icke också skall fördrifvet varda af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Så är jag nu kommen, till att tala med min herra Konungen dessa ord; ty folket hafver förskräckt mig; ty din tjenarinna tänkte: Jag skall tala med Konungenom; kanhända, att han gör det hans tjenarinna säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Ty han skall väl höra sina tjenarinno, att han hjelper mig ifrån allas deras hand, som mig, samt med minom son, ifrå Guds arf förgöra vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Och din tjenarinna tänkte: Mins herras Konungens ord skall vara mig en tröst; ty min herre Konungen är såsom en Guds Ängel, så att han kan höra godt och ondt; derföre varder ock Herren din Gud med dig blifvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Konungen svarade, och sade till qvinnona: Ljug icke för mig i det jag frågar dig. Qvinnan sade: Min herre Konungen tale.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Konungen sade: Är icke Joabs hand med dig i allo desso? Qvinnan svarade, och sade: Så sant som din själ lefver, min herre Konung, det är ingen annan, antingen på högra handen eller den venstra, utan såsom min herre Konungen sagt hafver; ty din tjenare Joab hafver detta så budit mig, och han hafver allt detta dine tjenarinno ingifvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Att jag skulle så vända denna sakena, det hafver din tjenare Joab gjort; men min herre är vis såsom en Guds Ängels vishet, så att han allt vet på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Då sade Konungen till Joab: Si, jag hafver detta gjort; så gack nu bort, och haf pilten Absalom hem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Då föll Joab på sitt ansigte till jordena, och tillbad, och tackade Konungenom, och sade: I dag förmärker din tjenare, att jag hafver funnit nåd för din ögon, min herre Konung, att Konungen gör hvad hans tjenare säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Så stod då Joab upp, och for till Gesur, och hade Absalom till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Men Konungen sade: Låt honom gå i sitt hus igen, och icke se mitt ansigte. Och så kom då Absalom igen i sitt hus, och såg intet Konungens ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Och i hela Israel var icke en man så dägelig och så prislig som Absalom; ifrå hans fotabjelle upp till hans hjessa var ingen brist på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Och när han skar sitt hår af; det skedde gemenliga hvart år, ty det var honom för tungt, så att man måste det afskära; så vog hans hufvudhår tuhundrade siklar, efter Konungsvigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Och Absalom vordo födde tre söner, och en dotter; hon het Thamar, och var en dägelig qvinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Alltså blef Absalom i tu år i Jerusalem, att han Konungens ansigte intet såg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Och Absalom sände efter Joab, att han skulle sända honom till Konungen; och han ville icke komma till honom. Han sände annan gången, likväl ville han icke komma,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Då sade han till sina tjenare: Ser det stycket af Joabs åker bredevid min, och han hafver der bjugg uppå; så går bort, och sticker eld deruppå. Så stucko Absaloms tjenare eld på det stycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Då stod Joab upp, och kom till Absalom i huset, och sade till honom: Hvi hafva dine tjenare stuckit eld på mitt stycke?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom sade till Joab: Si, jag sände efter dig, och lät säga dig: Kom till mig, att jag må sända dig till Konungen, och låta säga: Hvi kom jag ifrå Gesur? Det vore mig bättre, att jag ännu vore der. Så låt mig nu få se Konungens ansigte; är ock någon missgerning i mig, så dräp mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Och Joab gick in till Konungen, och sade det honom; och han kallade Absalom, att han kom in till Konungen; och han tillbad på sitt ansigte neder till jordena för Konungenom; och Konungen kysste Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Och det begaf sig derefter, att Absalom beställde sig vagnar och resenärar, och femtio män, som hans drabanter voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Och Absalom stod bittida upp om morgonen, och gick in på den vägen vid porten; och hvar någor hade ett ärende, så att han skulle komma till rätta för Konungen, den kallade Absalom till sig, och sade: Utaf hvad stad äst du? Då nu någor sade: Din tjenare är utaf ene af Israels slägter,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Så sade Absalom till honom: Si, din sak är god och rätt: men du hafver ingen, som dig förhörer af Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Och Absalom sade: Ack! ho sätter mig till domare i landena, att hvar man måtte komma till mig, den någon sak och klagan hafver, att jag måtte hjelpa honom till rätta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Och när någon gick fram till honom, till att tala med honom, så räckte han sina hand ut, och fick honom fatt, och kysste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Vid det sättet gjorde Absalom allom Israel, när de kommo med några saker till Konungen; och stal alltså bort männernas hjerta af Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Efter fyratio år sade Absalom till Konungen: Jag vill gå bort och fullkomna mitt löfte i Hebron, som jag Herranom lofvat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Förty din tjenare gjorde ett löfte, då jag bodde i Gesur i Syrien, och sade: När Herren låter mig återkomma till Jerusalem, så vill jag göra Herranom en Gudstjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Konungen sade till honom: Gack i frid. Och han stod upp, och gick till Hebron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Men Absalom hade utsändt spejare uti alla Israels slägter, och lät säga: När I fån höra ljudet af basunen, så säger: Absalom är Konung vorden i Hebron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Och med Absalom gingo tuhundrad män af Jerusalem kallade; men de gingo i enfaldighet, och visste intet af sakene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Sände ock desslikes Absalom efter Achitophel den Giloniten, Davids rådgifvare, utaf hans stad Gilo; och som han nu hade offrat, vardt förbundet starkt, och folket lopp till, och förökades med Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Så kom en och bidade David, och sade: Hvars mans hjerta i Israel följer Absalom efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Men David sade till alla sina tjenare, som när honom voro i Jerusalem: Upp, låt oss fly; ty här blifver ingen undflykt för Absalom; skynder eder, låt oss gå, att han icke är snarare än vi, och får oss fatt, och drifver inuppå oss det ondt är, och slår staden med svärdsegg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Då sade Konungens tjenare till honom: Hvad min herre Konungen täckes, si, här äro dine tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Och Konungen gick ut till fot, med allt sitt hus; men han lät blifva qvara tio frillor, till att bevara huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Och då Konungen och allt folket till fot utkommo, gingo de bortåt långt ifrå huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Och alle hans tjenare gingo när honom; dertill alle Crethi och Plethi, och alle de Gitthiter; sexhundrad män, som af Gath till fot komne voro, gingo framför Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Och Konungen sade till Itthai den Gitthiten: Hvi går du ock med oss? Vänd om, och blif när Konungenom; ty du äst främmande; far ock igen till ditt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'I går komst du, och i dag vågar du dig till att gå med oss? Jag går hvart jag gå kan, vänd om, och dina bröder med; dig vederfare barmhertighet och trohet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Itthai svarade, och sade: Så sant som Herren lefver, och så sant som min herre Konungen lefver, hvar som helst min herre Konungen blifver, antingen i lifvet eller i döden, der skall din tjenare ock blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'David sade till Itthai: Så kom, och gack med. Alltså gick Itthai den Gitthiten, och alle hans män, och hela barnahopen, som med honom var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Och hela landet greto med höga röst, och allt folket gick med; och Konungen gick öfver den bäcken Kidron, och allt folket gick före, på den vägen som löper åt öknena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Och si, Zadok var ock der, och alle Leviterna, som med honom voro, och båro Gudsförbunds ark, och der satte de honom; och AbJathar steg upp, tilldess allt folket kom utu stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Men Konungen sade till Zadok: Bär Guds ark åter in i staden; om jag finner nåd för Herranom, så låter han mig väl komma igen, och låter mig få se honom, och sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Men om han säger: Jag hafver intet behag till dig; si, här är jag; han göre med mig såsom honom täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Och Konungen sade till Presten Zadok: O Siare, vänd om igen i staden med frid; och med eder Ahimaaz din son, och Jonathan, AbJathars son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Si, jag vill draga fram på slättmarkena i öknene, tilldess bådskap kommer ifrån eder, och gifver mig all ting tillkänna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Så båro då Zadok och AbJathar Guds ark in i Jerusalem igen, och blefvo der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Men David gick uppfor oljoberget, och gret, och hans hufvud var skyldt, och han gick barfött; dertill allt folket, som med honom var, hade hvar och en förskylt sitt hufvud, och gingo uppåt gråtandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Och då David vardt sagdt, att Achitohel var i förbundet med Absalom, sade han: Herre, gör Achitophels rådslag till galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Och då David kom öfverst på berget, der man plägar tillbedja Gud; si, der mötte honom Husai, den Architen, med sönderrifven kjortel, och jord på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Och David sade till honom: Om du går med mig, äst du mig till tunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Men går du åter i staden, och säger till Absalom: Jag är din tjenare, jag vill höra Konungenom till; jag, som tillförene var dins faders tjenare, vill nu vara din tjenare; så kan du göra Achitophels rådslag om intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Och äro der Zadok och AbJathar Presterna med dig; allt det du hörer utu Konungens hus, må du undervisa Presterna Zadok och AbJathar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Och si, när dem äro två deras söner, Ahimaaz, Zadoks, och Jonathan, AbJathars son, genom dem kan du bjuda mig till hvad du förnimmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Så kom då Husai, Davids vän, i staden, och Absalom kom till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Och som David något litet var nedergången af berget, si, då mötte honom Ziba, MephiBoseths tjenare, med ett par sadlade åsnar; deruppå voro tuhundrad bröd, och hundrade stycke russin, och hundrade stycke fikon, och en lägel vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Då sade Konungen till Ziba: Hvad vill du göra härmed? Ziba sade: Åsnorna skola vara för Konungens husfolk, att de derpå rida; och bröden och fikonen för tjenarena, att de måga äta, och vinet till att dricka, när de varda trötte i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Konungen sade: Hvar är dins herras son? Ziba sade till Konungen: Si, han blef i Jerusalem; ty han sade: I dag varder Israels hus mig igengifvandes mins faders rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Konungen sade till Ziba: Si, allt det MephiBoseth hafver, skall vara ditt. Ziba sade med tillbedjande: Låt mig finna nåd för dig, min herre Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Då nu Konung David kom till Bahurim, si, då gick der en man utaf Sauls hus slägt, han het Simei, Gera son; han gick ut och bannades;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Och kastade stenar åt David, och åt alla Konung Davids tjenare; ty allt folk och alle de väldige voro vid hans högra, och vid hans venstra sido.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Och sade Simei, då han bannades: Härut, härut, du blodhund, du Belials man!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Herren hafver vedergullit dig allt Sauls hus blod, att du äst vorden Konung i hans stad; nu hafver Herren gifvit riket i din sons Absaloms hand; och si, nu tränger dig din olycka; ty du äst en blodhund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Men Abisai, ZeruJa son, sade till Konungen: Skall denne döde hunden banna min herra Konungen? Jag vill gå bort, och hugga hufvudet af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Konungen sade: I ZeruJa barn, hvad hafver jag skaffa med eder? Låt honom banna, ty Herren hafver budit honom banna David. Ho kan nu säga, hvi gör du så?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Och David sade till Abisai, och till alla sina tjenare: Si, min son, som af mitt lif kommen är, går mig efter mitt lif; hvi ock icke nu Jemini son? Låt honom betämma, att han bannar; ty Herren hafver så budit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Må hända, att Herren ser till mina bedröfvelse, och Herren löner mig med godo dessa bannor, som jag lider i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Alltså gick David med sitt folk framåt vägen; men Simei gick ut med bergssidone jemte vid honom, och bannades, och kastade stenar till honom, och hof jord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Och Konungen kom derin, och allt folket, som med honom var, trötte; och vederqvickte sig der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Men Absalom och allt folket, Israels män, kommo till Jerusalem, och Achitophel med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Då nu Husai den Architen, Davids vän, kom in till Absalom, sade han till Absalom: Till lycko, herre Konung, till lycko, herre Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom sade till Husai: Är detta din barmhertighet emot din vän? Hvi hafver du icke farit ut med dinom vän?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Husai sade till Absalom: Icke så, utan den som Herren utväljer, och detta folk, och hvar man i Israel, honom vill jag tillhöra, och när honom blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Och sedan, hvem skulle jag tjena? Skulle jag icke tjena hans son? Såsom jag hafver tjent dinom fader, så vill jag ock tjena dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Och Absalom sade till Achitophel: Gifver råd, hvad skole vi göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Achitophel sade till Absalom: Lägg dig när dins faders frillor, som han hafver låtit qvara blifva till att bevara huset, så får hele Israel höra, att du hafver gjort din fader illa luktande, och alles deras hand, som när dig äro, blifver styrkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Då gjorde de till Absalom ett tjäll uppå taket; och Absalom belåg sins faders frillor för all Israels ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'På den tiden, då Achitophel gaf ett råd, var det såsom man hade frågat Gud om någon ting; alltså var all Achitophels rådslag, både när David, och så när Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Och Achitophel sade till Absalom: Jag vill utvälja mig tolftusend män, och stå upp till att fara efter David i denna nattene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Och vill öfverfalla honom, medan han trött och mödd är. När jag nu förskräcker honom, så att allt folket, som när honom är, flyr, vill jag slå Konungen allena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Och draga allt folket till dig igen. När då hvar man till dig dragen är, såsom du begärar, så blifver allt folket i frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Detta tycktes Absalom vara godt, och allom äldstom i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Men Absalom sade: Käre, låt oss ock kalla Husai den Architen, och höra hvad han säger derom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Och då Husai kom in till Absalom, sade Absalom till honom: Sådant hafver Achitophel sagt; säg du, skole vi göra så, eller ej?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Då sade Husai till Absalom: Det är intet godt råd, som Achitophel i denna gången gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Och Husai sade ytterligare: Du känner väl din fader, och hans män, att de äro starke och illsinnade såsom en björn, hvilkom ungarna äro ifråtagne i markene. Dertill är din fader en stridsman, och varder sig intet försummandes med folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Si, han hafver tilläfventyrs nu förvarat sig någorstäds i en kulo, eller annorstäds. Om det nu skedde, att det ginge icke väl i första gången, och uppkomme ett rykte, och sades: Det är skedt en slagtning på det folk, som Absalom efterföljer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Så varder hvar och en förtviflad, den dock eljest dugelig är, och hafver ett hjerta såsom ett lejon; ty hela Israel vet, att din fader är stark, och dugelige män de som när honom äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Men det råder jag, att du församlar dig hela Israel, ifrå Dan intill BerSeba, många såsom sanden i hafvet; och din person drage ibland dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Så vilje vi öfverfalla honom på hvad rum vi finne honom, och vilje komma öfver honom, såsom daggen faller på jordena, att vi icke låte blifva en qvar, af honom och alla hans män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Om han församlar sig in uti någon stad, så skall hela Israel kasta linor kringom samma stad, och rycka honom i strömmen, att der skall icke finnas en sten igen af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Då sade Absalom, och hvar och en i Israel: Husai den Architens råd är bättre, än Achitophels råd. Men Herren skickade det så, att det goda Achitophels råd skulle varda förhindradt, på det att Herren skulle låta komma en olycko på Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Och Husai sade till Zadok och AbJathar Presterna: Så och så hafver Achitophel rådt Absalom och dem äldstom i Israel; men jag hafver så och så rådt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Så sänder nu med hast åstad, och båder David, och säger: Blif icke öfver nattena på slättmarkene i öknene; utan drag deröfver snarliga, att Konungen icke varder uppsluken, och allt folket, som med honom är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Men Jonathan och Ahimaaz stodo vid den brunnen Rogel; och en tjenstepiga gick bort, och sade dem det; och de gingo åstad, och sade det Konung David; förty de torde icke låta sig se, så att de kommo in i staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Men en dräng fick se dem, och sade det för Absalom. Då gingo de både med hast sin väg, och kommo uti ens mans hus i Bahurim; han hade en brunn i sinom gård, der stego de in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Och qvinnan tog och bredde ett öfvertäckelse öfver brunnshålet, och slog der gryn uppå, så att man kunde det intet märka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Då nu Absaloms tjenare kommo till qvinnona i huset, sade de: Hvar är Ahimaaz och Jonathan? Qvinnan sade till dem: De gingo öfver vattubäcken. Och då de sökte, och funno intet, gingo de tillbaka igen till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Och då de voro bortgångne, stego de upp utu brunnen, och gingo sina färde; och underviste det Konung David, och sade till David: Står upp, och går med hast öfver älfvena; ty så och så hafver Achitophel gifvit råd emot eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Då stod David upp, och allt folket, som när honom var, och gingo öfver Jordan, tilldess morgon ljust vardt; och icke en fattades, som icke var kommen öfver Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Då Achitophel såg, att hans råd icke hade framgång, sadlade han sin åsna, och stod upp, och for hem i sin stad, och skickade om sitt hus, och hängde sig, och blef död, och vardt begrafven i sins faders graf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Och David kom till Mahanaim; och Absalom drog öfver Jordan, och alle Israels män med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Och Absalom hade satt Amasa i Joabs stad öfver hären; och Amasa var ens mans son, som het Jithra, en Israelit, hvilken låg när Abigail, Nahas dotter, ZeruJa syster, Joabs moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Men Israel och Absalom lägrade sig i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Då David var kommen till Mahanaim, kommo der Sobi, Nahas son, af Rabba Ammons barnas, och Machir, Ammiels son af Lodebar, och Barsillai, en Gileadit af Rogelim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Och förde sängkläder, bäcken, lerkäril, hvete, bjugg, mjöl, torkad ax, bönor, linse, gryn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Hannog, smör, får, och nötaostar till David, och till folket, som med honom var, till spisning; ty de tänkte, folket varder hungrigt, trött och törstigt i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Och David skickade folket, som när honom var, och satte höfvitsmän öfver dem, öfver tusend, och öfver hundrad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Och sände ut folket, en tredjepart under Joab, och en tredjepart under Abisai, ZeruJa son, Joabs broder, och en tredjepart under Itthai den Gitthiten. Och Konungen sade till folket: Jag vill ock draga ut med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Men folket sade: Du skall icke draga ut; förty om vi än flydde, eller hälften af oss blefve döde, der skola de intet om sköta; men du äst så mycket som tiotusend af oss; så är det nu bättre, att du må vara oss till hjelp utu stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Konungen sade till dem: Såsom eder täckes, så vill jag göra. Och Konungen blef ståndandes i portenom, och allt folket drog ut, vid hundrad, och vid tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Och Konungen böd Joab och Abisai, och Itthai, och sade: Farer mig sakta med pilten Absalom. Och allt folket hörde, att Konungen böd alla höfvitsmännerna om Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Och då folket kom ut i markena emot Israel, vardt stridt i Ephraims skog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Och Israels folk vardt der slaget för Davids tjenare, så att i den dagen skedde en stor slagtning, till tjugutusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Och striden vardt der förströdd uppå allt landet; och skogen uppfrätte flera på den dagen än svärdet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Och Absalom mötte Davids tjenare, och red på en mula; och då mulen kom under en stor tjock ek, fastnade hans hufvud vid ekena, och han blef hängandes emellan himmel och jord; men mulen lopp sin väg undan honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Då en man fick det se, bådade han det Joab och sade: Si, jag såg Absalom hänga vid en ek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Och Joab sade till mannen, som det bådade: Si, sågst du det, hvi slog du honom icke der till jordena? Så ville jag gifvit dig på mina vägnar tio silfpenningar, och ett bälte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mannen sade till Joab: Om du hade vägit mig tusende silfpenningar i mina hand, så ville jag ändå icke låtit komma min hand på Konungens son; ty Konungen böd dig, och Abisai, och Itthai, i våro åhöro, och sade: Förvarer mig pilten Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Eller om jag än något ondt gjort hade på min själs fara, efter för Konungenom intet fördoldt varder, skulle du väl sjelfver fallit mig emot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Joab sade: Icke så; jag vill till honom för din ögon. Då tog Joab tre spetsar i sin hand, och stötte dem Absalom i hjertat, medan han ännu lefde i ekene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Och tio unge karlar, Joabs vapnedragare, gåfvo sig omkring honom, och slogo honom ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Då blåste Joab i basunen, och kallade folket igen, att de icke mer skulle jaga efter Israel; ty Joab ville skona folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Och de togo Absalom och kastade honom i skogen uti en stor grop, och lade en stor hop med stenar på honom; och hele Israel flydde, hvar och en i sina hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Men Absalom hade sig upprest en stod, medan han ännu lefde, den står i Konungsdalenom; ty han sade: Jag hafver ingen son; derföre skall detta vara mins namns åminnelse; och kallade den stodena efter sitt namn, och heter ännu på denna dag Absaloms rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahimaaz, Zadoks son, sade: Käre, låt mig löpa, och förkunna Konungenom, att Herren hafver skaffat honom rätt af hans fiendars händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Joab sade till honom: Du bär ingen god tidende i denna dagen; på en annan dag må du bära tidende, och icke i dag; ty Konungens son är död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Men till Cusi sade Joab: Gack åstad, och båda Konungen hvad du sett hafver. Och Cusi tillbad Joab, och lopp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Men Ahimaaz, Zadoks son, sade åter till Joab: Huru, om jag ock löper efter Cusi? Joab sade: Hvad vill du löpa, min son? Kom hit, du bär ingen god tidende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Han svarade: Huru, om jag lopp? Han sade till honom: Så löp. Så lopp då Ahimaaz på den genesta vägen, och kom förr än Cusi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Men David satt emellan två portar; och väktaren gick uppå taket åt porten om på muren, och lyfte sin ögon upp, och fick se en man löpandes allena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Och han ropade, och sade det Konungenom. Konungen sade: Är han allena, så är det god tidende i hans mun. Som han ännu lopp, och kom närmer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Fick väktaren se en annan man löpandes, och han ropade af murenom, och sade: Si, en man löper allena. Åter sade Konungen: Den är ock ett godt bådskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Väktaren sade: Mig synes den förstas löpande, såsom det vore Ahimaaz löpande, Zadoks sons. Och Konungen sade: Det är en god man, och han bär god tidende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahimaaz ropade, och sade till Konungen: Frid; och tillbad för Konungen på sitt anlete ned till jordena, och sade: Lofvad vare Herren din Gud, som de menniskor beslutit hafver, som upphofvo sina hand emot min herra Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Konungen sade: Mår ock pilten Absalom väl? Ahimaaz sade: Jag såg ett stort sorl, då Konungens tjenare Joab sände mig, din tjenare, och jag vet icke hvad det var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Konungen sade: Gack afsides, och statt der; och han gick afsides, och stod der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Si, då kom Cusi, och sade: Jag bär god tidende, min herre Konung: Herren hafver i dag skaffat dig rätt af allas deras hand, som sig hafva uppsatt emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Konungen sade till Cusi: Mår ock pilten Absalom väl? Cusi sade: Gånge så med alla mins herras Konungens fiendar såsom med piltenom går, och med alla dem som sätta sig upp emot dig, till att göra dig ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Då vardt Konungen sorgse, och gick upp i salen i portenom, och gret; och vid han gick, sade han: Min son Absalom, min son, min son Absalom! Gifve Gud, att jag måtte dö för dig. O Absalom! min son, min son!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Och det vardt bådadt Joab: Si, Konungen gråter, och beklagar sig om Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Och vardt i den dagen en sorg af segren i hela folkena; förty folket hade i den dagen hört, att Konungen var bedröfvad om sin son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Och folket drog sig bort i den dagen, så att det icke kom i staden, lika som ett folk drager sig bort, som till blygd kommet är, när det i strid flytt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Men Konungen förskylde sitt ansigte, och ropade högt: Ack! min son Absalom! Absalom, min son, min son!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Så gick Joab in uti huset till Konungen, och sade: Du hafver i dag till blygd gjort alla dina tjenare, som i dag undsatt hafva dina, dina söners, dina döttrars, dina hustrurs och dina frillors själar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Så att du hafver dem kär som dig hata, och hatar dem som dig kär hafva; ty du låter dig märka i dag, att dig ligger ingen magt uppå höfvitsmännerna och tjenarena; utan jag märker i dag väl, att om allenast Absalom lefde dig, och vi alle i dag döde vore, det skulle dig tycka så godt vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Så statt nu upp, och gack ut, och tala vänliga med dina tjenare; ty jag svär dig vid Herran: Om du icke går ut, blifver icke en man qvar när dig öfver denna nattena; det skall vara dig värre, än allt det onda som öfver dig kommet är, ifrå din ungdom allt intill nu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Då stod Konungen upp, och satte sig i porten, och allo folkena vardt sagdt: Si, Konungen sitter i portenom. Så kom allt folket för Konungen; men Israel var flydd, hvar och en i sin hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Och allt folket kifvade tillhopa i alla Israels slägter, och sade: Konungen hafver hulpit oss utu våra fiendars hand, och förlossat oss utu de Philisteers hand, och hafver måst fly utaf landena för Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Så är Absalom död blifven i stridene, den vi öfver oss smort hade; hvi ären I nu så stilla, att I icke hemten Konungen igen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Och Konungen sände till Zadok och AbJathar Presterna, och lät säga dem: Taler med de äldsta i Juda, och säger: Hvi viljen I vara de siste, till att hemta Konungen hem i sitt hus igen? Ty hela Israels tal var kommet för Konungen i hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'I ären mine bröder, mitt ben, och mitt kött; hvi viljen I då vara de siste, till att hemta Konungen igen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Och till Amasa säger: Äst du icke mitt ben, och mitt kött? Gud göre mig det och det, om du icke skall blifva härhöfvitsman för mig, så länge du lefver, i Joabs stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Och han bevekte alla Juda mäns hjerta, såsom ens mans; och de sände till Konungen: Kom igen, du och alle dine tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Så kom då Konungen igen. Och som han kom till Jordan, voro Juda män komne till Gilgal, till att draga neder emot Konungen, att de skulle föra Konungen öfver Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Och Simei, Gera son, Jemini sons, som i Bahurim bodde, hastade sig, och drog neder med Juda män emot Konung David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Och med honom voro tusende män af BenJamin; desslikes ock Ziba, den tjenaren af Sauls hus, med hans femton söner, och tjugu tjenare, och de skyndade sig öfver Jordan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Och beredde färjona för Konungenom, att de skulle föra Konungens tjenare öfver, och göra det honom till vilja var. Och Simei, Gera son, föll neder för Konungen, då han for öfver Jordan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Och sade till Konungen: Min Herre, tillräkna mig icke den missgerning, och kom icke ihåg, att din tjenare förtörnade dig den dagen, då min herre Konungen gick utu Jerusalem, och Konungen lägge ett icke på hjertat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Ty din tjenare känner, att jag syndat hafver. Och si, jag är i dag den förste kommen utaf Josephs hus, att jag skulle draga neder emot min herra Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Men Abisai, ZeruJa son, svarade, och sade: Och skulle icke Simei derföre dö, som bannade Herrans smorda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'David sade: Hvad hafver jag beställa med eder, I ZeruJa barn, att I viljen i dag varda mig till Satan? Skulle i dag någor dö i Israel? Menar du att jag icke vet, att jag i dag är vorden Konung öfver Israel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Och Konungen sade till Simei: Du skall icke dö; och Konungen svor honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Kom också MephiBoseth, Sauls son, neder emot Konungen, och hade intet ryktat sina fötter, eller sitt skägg, eller tvagit sin kläder, ifrå den dagen Konungen bortgången var, intill den dagen då han kom med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Då han nu till Jerusalem kom, till att möta Konungenom, sade Konungen till honom: Hvi for du icke med mig, MephiBoseth?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Och han sade: Min herre Konung, min tjenare gjorde orätt emot mig; ty din tjenare tänkte: Jag vill sadla en åsna, och stiga deruppå, och rida till min herra Konungen; förty din tjenare är ofärdig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Dertill hafver han ock beklagat din tjenare för min herra Konungenom; men min herre Konungen är såsom en Guds Ängel, och må göra hvad honom täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Ty allt mins faders hus hafver icke varit utan till döden skyldigt för minom herra Konungenom; så hafver du dock satt din tjenare ibland dem, som äta öfver ditt bord; hvad rätt hafver jag mer, eller hvad kan jag mer ropa till Konungen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Konungen sade till honom: Hvad talar du mer härom? Jag hafver sagt det, du och Ziba skifter åkren med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'MephiBoseth sade till Konungen: Han må tagan allsamman, efter min herre Konungen med frid hemkommen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Och Barsillai, den Gileaditen, kom neder ifrå Roglim, och for öfver Jordan för Konungen, på det han skulle ledsaga honom öfver Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Och Barsillai var fast gammal, väl åttatio år; han hade försörjt Konungen, medan han var i Mahanaim; ty han var en ganska väldig man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Och Konungen sade till Barsillai: Du skall draga fram med mig; jag vill försörja dig med mig i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Men Barsillai sade till Konungen: Hvad är det jag ännu hafver till att lefva, att jag ännu skulle draga upp med Konungenom till Jerusalem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Jag är i dag åttatio år gammal; huru skulle jag känna hvad godt eller ondt är? Eller smaka hvad jag äter eller dricker? Eller höra hvad de sångare eller sångerskor sjunga? Hvi skulle din tjenare ytterligare besvära min herra Konungen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Din tjenare skall något litet fara med Konungenom öfver Jordan; hvi skulle Konungen göra mig en sådana vedergällning?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Låt din tjenare vända om igen, att jag må dö i minom stad, och varda begrafven i mins faders och mine moders grift. Si, der är din tjenare Chimham, den låt draga öfver med min herra Konungen; och gör honom hvad dig täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Konungen sade: Chimham skall draga öfver med mig, och jag vill göra honom hvad dig är till vilja; och allt det du bedes af mig, det vill jag göra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Och då allt folket var kommet öfver Jordan, och Konungen desslikes, kysste Konungen Barsillai, och välsignade honom; och han vände om igen till sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Och Konungen drog öfver till Gilgal, och Chimham for med honom; och allt Juda folk hade fört Konungen öfver; men Israels folk var icke utan hälften der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Och si, då kommo alle Israels män till Konungen, och sade till honom: Hvi hafva våre bröder, Juda män, stulit dig, och hafva fört Konungen och hans hus öfver Jordan, och alla Davids män med honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Då svarade de af Juda dem af Israel: Konungen är oss när åkommen; hvi ären I der vrede före? Menen I, att vi af Konungenom kost och skänker fått hafve?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Så svarade då de af Israel dem af Juda, och sade: Vi hafve tio sinom mer, med Konungenom, med David också, än I; hvi hafver du då så ringa aktat mig, att vi icke måtte hafva varit de förste, till att hemta vår Konung? Men de af Juda talade hårdare, än de män af Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Och dit var kommen en Belials man, som het Seba, Bichri son, ens mans af Jemini, han blåste i basunen, och sade: Vi hafve ingen del i David, eller något arf i Isai son; hvar och en fare i sina hyddo, o Israel!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Då föll ifrå David hvar man i Israel, och följde Seba, Bichri son; men Juda män blefvo vid sin Konung, ifrå Jordan intill Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Då Konung David kom hem till Jerusalem, tog han de tio frillor, som han återleft hade till att bevara huset, och satte dem i förvaring, och försörjde dem; men han belåg dem intet mer; och de voro så innelyckta intill deras död, och lefde i enkodom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Och Konungen sade till Amasa: Kalla mig tillhopa alla Juda män, på tredje dagen; och du skall också vara vid handena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Och Amasa gick bort till att kalla tillhopa Juda; och han fördröjde öfver den tiden, som han honom förelagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Och David sade till Abisai: Nu varder oss Seba, Bichri son, mer vedermödo görandes än Absalom; tag du dins herras tjenare, och jaga efter honom, att han tilläfventyrs icke finner fasta städer för sig, och undslipper utu vår ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Då drogo ut med honom Joabs män, dertill Crethi och Plethi, och alle starke; men de drogo ut af Jerusalem, till att jaga efter Seba, Bichri son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Som de nu komne voro till den stora stenen i Gibeon, kom Amasa der emot dem; och Joab var begjordad öfver sin kläder, som han uppå hade, och hade bundit derutanöfver ett svärd, det hängde vid hans länd i skidone; och det gick väl ut och in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Och Joab sade till Amasa: Frid vare med dig, min broder; och Joab fattade Amasa i skägget med högra handene, såsom han ville kyssa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Och Amasa gaf icke akt på svärdet i Joabs hand. Och han stack honom dermed i buken, så att hans inelfver utgingo på jordena, och gaf honom intet styng mer; och han blef död. Men Joab och hans broder Abisai jagade efter Seba, Bichri son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Och en af Joabs tjenare blef ståndandes när honom, och sade: Hvilken dristar sig emot Joab, och hvilken går efter Joab när David?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Men Amasa låg sölad i blodet midt uppå vägenom. Då nu en såg, att allt folket blef der ståndandes, drog han Amasa af vägen bort på markena, och kastade kläder på honom; efter han såg att, hvilken till honom kom, han blef der ståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Då han nu var utaf vägenom tagen, följde hvar man efter Joab, till att jaga efter Seba, Bichri son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Och han drog genom alla Israels slägter, till Abel och BethMaacha, och hela Haberim; och de församlade sig, och följde honom efter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Och kommo, och belade honom i Abel och BethMaacha, och de gjorde en skam om staden, och trädde intill muren; och allt folket, som med Joab var, stormade och ville kasta muren omkull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Då ropade en vis qvinna utu stadenom: Hörer, hörer; säger till Joab, att han kommer hit, jag vill tala med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Och då han kom till henne, sade qvinnan: Äst du Joab? Han sade: Ja. Hon sade till honom: Hör dine tjenarinnos tal. Han sade: Jag hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Hon sade: I förtiden sade man: Den som fråga vill, han fråge i Abel; och så gick det väl till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Detta är den redelige och trogne staden i Israel, och du vill dräpa staden och modrena i Israel? Hvi vill du uppsluka Herrans arfvedel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joab svarade, och sade: Bort det, bort det ifrå mig, att jag uppsluka eller förderfva skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Det hafver sig icke så; utan en man af Ephraims berg, benämnd Seba, Bichri son, hafver upphäfvit sig emot Konung David: Får honom hitut allena, så vill jag draga af ifrå stadenom. Qvinnan sade till Joab: Si, hans hufvud skall varda kastadt ut till dig öfver muren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Och qvinnan kom in till allt folket med sine vishet; och de höggo Seba, Bichri son, hufvudet af, och kastade det ut till Joab. Då blåste han i basunen, och de åtskiljde sig ifrå stadenom, hvar och en uti sin hyddo; och Joab kom igen till Konungen i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Och Joab var öfver all Israels här; Benaja, Jojada son, var öfver Crethi och Plethi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram var räntomästare; Josaphat, Ahiluds son, var canceller;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja var skrifvare; Zadok och AbJathar voro Prester;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Dertill var Ira, den Jairiten, Davids Prest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Så vardt en hård tid i Davids dagar i tre år efter hvartannat; och David sökte Herrans ansigte; och Herren sade: För Sauls skull, och för det blodhus skull, derföre att han drap de Gibeoniter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Då lät Konungen kalla de Gibeoniter, och talade med dem; men de Gibeoniter voro icke utaf Israels barn, utan voro igenblefne utaf de Amoreer; men Israels barn hade svorit dem; och Saul sökte efter att slå dem i sitt nit för Israels barn och Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Så sade nu David till de Gibeoniter: Hvad skall jag göra eder? Och hvarmed skall jag försonat, att I mågen välsigna Herrans arfvedel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'De Gibeoniter svarade honom: Oss är intet om guld eller silfver af Saul eller hans hus; och är oss intet om, att någor skall dräpas af Israel. Han sade: Hvad sägen I då, det jag eder göra skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'De sade till Konungen: Den mannen, som oss förderfvat och tillintetgjort hafver, honom skole vi förderfva, så att intet blifver qvart af honom i alla Israels gränsor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Gif oss sju män utaf hans hus, att vi upphänge dem Herranom i Gibea Sauls, Herrans utvaldas. Konungen sade: Jag vill få eder dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Men Konungen skonade MephiBoseth, Jonathans son, Sauls sons, för Herrans eds skull, som emellan dem var, nämliga, emellan David och Jonathan, Sauls son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Men de två Rizpa söner, Aja dotters, hvilka hon Saul födt hade, Armoni och MephiBoseth; dertill de fem Michals söner Sauls dotters, hvilka hon Adriel, Barsillai den Meholathitens son, födt hade, tog Konungen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Och fick dem uti de Gibeoniters hand; dem upphängde de på bergena för Herranom. Och så föllo desse sju på eno reso; och blefvo döde i första andene, när bjugganden uppågick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Då tog Rizpa, Aja dotter, en säck och bredde honom på ena håll i andenes begynnelse, intilldess vattnet af himmelen dröp uppå dem; och lät i den dagen inga himmelens foglar sätta sig på dem; ej heller markenes djur om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Och det vardt sagdt David, hvad Rizpa, Aja dotter, Sauls frilla, gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Och David gick bort, och tog Sauls ben, och Jonathans hans sons ben ifrå de borgare i Jabes i Gilead, hvilken de utaf Bethsans gato stulit hade; der de Philisteer dem hängt hade, på den tiden då de Philisteer slogo Saul på Gilboa berg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Och förde dem dädan ditupp, och samkade dem tillhopa med de hängdas ben;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Och begrofvo Sauls och hans sons Jonathans ben i BenJamins land i Zela, i hans faders Kis graf; och gjorde allt såsom Konungen budit hade. Alltså vardt då Gud sedan landena försonad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Så hof sig åter ett örlig upp utaf de Philisteer emot Israel. Och David drog neder, och hans tjenare med honom, och stridde emot de Philisteer. Och David vardt trött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Och Jesbi af Nob, hvilken en af Rapha barn var, och hans glafvens vigt var trehundrad kopparsvigter, och han hade ett nytt harnesk uppå, han for efter att slå David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Men Abisai, ZeruJa son, halp honom, och slog den Philisteen ihjäl. Då svoro honom Davids män, och sade: Du skall icke mer draga ut med oss i strid, att icke utsläckes lyktan i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Sedan hof sig åter ett örlig upp i Gob med de Philisteer; då slog Sibbechai, den Husathiten, Saph, den ock en var utaf de Rapha barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Och sig hof ännu upp ett örlig i Gob med de Philisteer; då slog ElhananJaere, Orgims son, en BethLehemit, Goliath, den Gitthiten, hvilken hade en spets, hvilkens stång var såsom ett väfträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Och sig upphof ännu ett örlig i Gath. Der var en lång man, han hade sex finger på sina händer, och sex tår på sina fötter, så att de voro fyra och tjugu på talet; och han var också födder af Rapha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Och då han talade hädelse till Israel, slog honom Jonathan, Simea son, Davids broders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Desse fyra voro Rapha födde i Gath; och föllo igenom Davids och hans tjenares hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Och David talade för Herranom denna visones ord, den tid då Herren hade hulpit honom ifrån alla hans fiendars hand, och ifrå Sauls hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Och sade: Herren är min klippa, och min borg, och min Frälsare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Gud är min tröst, på honom vill jag trösta; min sköld och mine helsos horn; mitt beskärm, och min tillflykt, min Frälsare, du som mig hjelper ifrån orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Jag vill lofva och åkalla Herran, så blifver jag ifrå mina fiendar förlossad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Ty dödsens förderf hade omhvärft mig; och Belials bäcker hade förskräckt mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Helvetes band omhvärfde mig; och dödsens snaror öfverföllo mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'När jag bedröfvad är, vill jag åkalla Herran, och ropa till min Gud, så hörer han mina röst utaf sitt tempel; och mitt rop kommer för honom i hans öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Jorden bäfvade och skalf; himmelens grundvalar hafva sig rört, och gifvit sig, då han var vred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Rök gick upp utaf hans näso, och förtärande eld utaf hans mun; så att det ljungade deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Himmelen böjde han, och steg neder; och mörker var under hans fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Och han steg på Cherub, och flög, och syntes på vädrens vingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Hans tjäll kringom honom var mörker, och svart tjockt moln.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Af skenet för honom brann det med ljungande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Herren dundrade af himmelen; och den Högste lät utgå sitt dunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Han sköt sina pilar, och förströdde dem; han lät ljunga, och förskräckte dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Då såg man vattnet uppvälla; och jordenes grund vardt blottad genom Herrans straff, och genom hans näsos anda och blåst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Han sände utaf höjdene, och hemtade mig, och drog mig utu stor vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Han frälste mig ifrå mina starka fiendar; ifrå mina hatare, som mig för mägtige voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'De mig öfverföllo i mine olyckos tid; och Herren är min tröst vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Han hafver utfört mig på rymdena. Han tog mig ut; förty han hade lust till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Herren gör väl vid mig efter mina rättfärdighet; han betalar mig efter mina händers renhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Ty jag håller Herrans vägar, och är icke ogudaktig vorden emot min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Förty alla hans rätter hafver jag för ögon; och hans bud kastar jag icke ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Men jag är utan vank för honom, och bevarar mig för synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Derföre vedergäller mig Herren efter min rättfärdighet; efter min renhet för hans ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Med de heliga äst du helig; med de fromma äst du from.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Med de rena äst du ren; och vid de afvoga ställer du dig afvog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Ty du hjelper det elända folk; och med din ögon förnedrar du de höga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Ty du, Herre, äst min lykta; Herren upplyser mitt mörker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Förty med dig kan jag nederslå krigsfolk; och genom min Gud springa öfver muren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Guds vägar äro utan brist; Herrans tal är genomluttradt; han är en sköld allom dem som hoppas till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Ty hvilken är en Gud, utan Herren? Och hvilken är en tröst, utan vår Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Gud styrker mig med kraft, och visar mig en väg utan brist.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Han gör mina fötter lika som hjortars; och sätter mig uppå mina höjder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Han lärer mina händer strida, och drifver mina armars kopparbåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Och du gifver mig dine helsos sköld; och när du förnedrar mig, gör du mig storan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Du gör rum för mig till att gå, att mina fötter icke slinta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Jag vill jaga efter mina fiendar, och förgöra dem; och vill icke omvända, tilldess jag gör en ända med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Jag vill förgöra dem, och nederslå dem, och de skola icke stå mig emot; de måste falla under mina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Du kan omgjorda mig med kraft till strid; du kan kasta dem under mig, som sätta sig upp emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Du gifver mig mina fiendar på flyktena, att jag må förstöra dem som mig hata.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'De ropa, men der är ingen hjelpare; till Herran, men han svarar dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Jag skall sönderstöta dem såsom stoft på jordene; såsom träck uppå gatone skall jag göra dem till mull, och förströ dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Du hjelper mig ifrå det trätosamma folket; och bevarar mig till ett hufvud öfver Hedningarna. Det folk, som jag intet kände, skall tjena mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'De främmande barn försaka mig; men desse lyda mig med hörsam öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'De främmande barn äro försmäktade, och brytas i sina bojor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Herren lefver, och lofvad vare min tröst; och varde upphöjd Gud, mine helsos tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Gud, som gifver mig hämnden, och kastar folk under mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Han förer mig ut ifrå mina fiendar, och ifrå dem, som sätta sig emot mig, upphöjer du mig; och ifrå vrångvisa män frälsar du mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Derföre vill jag tacka dig, Herre, ibland Hedningarna, och dino Namne lofsjunga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Den der stor salighet bevisar sinom Konung; och gör väl med David sinom smorda, och med hans säd i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Dessa äro de sista Davids ord; David, Isai son, sade: Den mannen sadet, som för en Jacobs Guds smord uppsätter är, och en lustig Israels diktare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Herrans Ande hafver talat genom mig, och hans ord är skedt genom mina tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Israels Gud hafver talat till mig; Israels tröst hafver mig tillsagt, den der råder öfver menniskorna, den rättvise rådanden i Guds fruktan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Såsom ljuset är om morgonen, då solen uppgår bittida, utan moln; och af skenet efter regn växer gräs upp af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Ty ingen ting är för Gudi såsom mitt hus; ty han hafver gjort ett evigt förbund med mig, i alla måtto visst och fast; ty det är all min salighet, och all lust, att intet så växa skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Men den ogudaktige Belial skall varda alldeles utrotad såsom törne, så att man intet behåller deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Och om någor antastar dem, skola de med jern och spets platt förderfva dem; och man skall uppbränna dem med eld i deras rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Desse äro namnen af Davids hjeltar: Jasabeam, Hachmoni son, den ypperste ibland tre; hvilken upphof sin spets, och slog ihjäl åttahundrad i ena reso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Näst honom var Eleazar, Dodi son, Ahohi sons, ibland de tre hjeltar med David, då de förhädde de Philisteer, och voro der församlade till strid, och Israels män drogo upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Då stod han, och slog de Philisteer, tilldess hans hand dofnade, trött af svärdena. Och Herren gaf en stor salighet på den tiden, så att folket vände om igen efter honom till att röfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Efter honom var Samma, Age son, den Hararitens. Då de Philisteer församlade sig i en rota, och der var en åker full med linse, och folket flydde för de Philisteer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Då trädde han midt uppå den åkren, och undsatte honom, och slog de Philisteer; och Herren gaf en stor salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Och desse tre ypperste ibland tretio kommo neder i andene, till David uti kulona Adullam; och de Philisteers rote låg i Rephaims dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Men David var på den tiden på borgene; och de Philisteers folk låg i BethLehem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Och David vardt lysten och sade: Ho vill hemta mig dricka af det vatten i BethLehems brunn, under portenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Då föllo de tre hjeltar in uti de Philisteers lägre, och hemtade vatten utu brunnenom i BethLehem, under porten, och båro till David; men han ville intet dricka det, utan utgöt det Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Och sade: Det låte Herren vara långt ifrå mig, att jag detta göra skulle; är det icke de mäns blod, som sitt lif vågade, och gingo dit? Och han ville icke drickat. Det gjorde nu de tre hjeltar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai, Joabs broder, ZeruJa son, var ock en ypperst ibland tre. Han hof sin spets upp, och slog trehundrad, och var också prisad ibland tre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Och den härligaste ibland tre och var deras öfverste; men han kom icke intill de tre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Och Benaja, Jojada son, IsHails sons af storom gerningom, af Kabzeel, han slog tu de Moabiters lejon, och gick ned, och slog ett lejon i brunnenom i snötiden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Och slog desslikes en grufvelig Egyptisk man; den hade en spets i sine hand; men han gick neder till honom med en staf, och tog den Egyptien spetsen utu handene, och slog honom ihjäl med sin egen spets.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Detta gjorde Benaja, Jojada son, och var beprisad ibland de tre hjeltar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Och härligare än de tretio; men han kom icke till de tre. Och David gjorde honom till sitt hemliga Råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asahel, Joabs broder, är ibland de tretio; Elhanan, Dodo son, i BethLehem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma den Haroditen; Elika den Haroditen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Helez den Palthiten; Ira, Ikkes son, den Thekoitens;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abieser den Annethothiten; Mebunnai den Husathiten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Zalmon den Achothiten; Maharai den Netophathiten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb, Baena son, den Netophathiten; Itthai, Ribai son, af Gibea BenJamins barnas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja, den Pirgathoniten; Hiddai, af de bäcker Gaas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'AbiAlbon den Arbathiten; Asmaveth den Barhumiten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliaheba den Saalboniten, Jasens och Jonathans barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samma den Harariten; Ahiam, Sarars son, dens Araritens;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphelet, Ahasbai son, Maachathi sons; Eliam, Achitophels son, dens Gilonitens;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezrai den Carmeliten; Paarai den Arbiten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigeal, Nathans son, af Zoba; Bani den Gaditen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zelek den Ammoniten; Naharai den Beerothiten, Joabs vapnedragare, ZeruJa sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira den Jithriten; Gareb den Jithriten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Uria den Hetheen. De äro alle tillhopa sju och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Och Herrans vrede förgrymmade sig åter emot Israel, och gaf David ibland dem in, att han sade: Gack bort, räkna Israel och Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Och Konungen sade till Joab sin härhöfvitsman: Far omkring i alla Israels slägter, ifrå Dan intill BerSeba, och räkna folket, att jag må veta huru mycket det är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joab sade till Konungen: Herren din Gud föröke till detta folket, såsom det nu är, ännu hundrade resor så mycket, att min herre Konungen må se lust deruppå. Men hvad hafver min herre Konungen lust till detta ärendet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Men Konungens ord måste gå före, emot Joab och höfvitsmännerna öfver hären. Alltså drog Joab ut, och höfvitsmännerna öfver hären ifrå Konungenom, att de skulle tälja Israels folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Och foro öfver Jordan, och lägrade sig i Aroer, på högra sidone vid den staden, som ligger i Guds bäck, och i Jaeser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Och kommo till Gilead, och i nederlandet Hadsi; och kommo till DanJaan, och omkring Zidon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Och kommo till den fasta staden Tyrus, och till alla de Heveers och Cananeers städer; och kommo ut söder på Juda till BerSeba;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Och drogo kringom hela landet. Och efter nio månader och tjugu dagar kommo de till Jerusalem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Och Joab fick Konungenom summan af folket, som taldt var; och det var i Israel åttahundrade sinom tusende starke män, som svärd utdrogo; och i Juda femhundrade sinom tusende män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Och Davids hjerta slog honom, sedan folket taldt var. Och David sade till Herran: Jag hafver svårliga syndat, att jag detta gjort hafver; och nu, Herre, tag bort dins tjenares missgerning; ty jag hafver gjort mycket dårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Och då David stod upp om morgonen, kom Herrans ord till Propheten Gad, Davids Siare, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Gack bort och tala till David: Så säger Herren: Treggehanda ting sätter jag dig före; utvälj der ett af, det jag dig göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gad kom till David, och bådade honom, och sade till honom: Vill du, att hård tid kommer i sju år i ditt land? Eller att du i tre månader måste fly för dina fiendar, och de förfölja dig? Eller att pestilentie blifver i tre dagar i ditt land? Så märk nu, och se till hvad jag skall säga honom igen, som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'David sade till Gad: Mig är stor ångest; men låt mig falla i Herrans hand; ty hans barmhertighet är stor; jag vill icke falla i menniskohand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Alltså lät Herren komma pestilentie i Israel, ifrå morgonen intill bestämdan tid, så att folket blef dödt, ifrå Dan intill BerSeba, sjutiotusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Och då Ängelen utsträckte sina hand öfver Jerusalem, att han det förderfva skulle, ångrade Herranom det onda, och sade till Ängelen, som folket förderfvade: Det är nog; håll nu din hand tillbaka. Och Herrans Ängel var vid Arauna lado, den Jebuseens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Då David såg Ängelen, som folket slog, sade han till Herran: Si, jag hafver syndat; jag hafver gjort den missgerningena; hvad hafva desse fåren gjort? Låt dina hand vara emot mig och mins faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Och Gad kom till David i samma tiden, och sade till honom: Gack upp, och res upp Herranom ett altare uti Arauna lado, den Jebuseens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Alltså gick David upp, såsom Gad sagt och Herren budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Och då Arauna vände sig om, såg han Konungen med sina tjenare gå till sig; och tillbad på sitt ansigte ned till jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Och sade: Hvi kommer min herre Konungen till sin tjenare? David sade: Till att köpa ladona af dig, och bygga Herranom ett altare, att plågan må återvända i folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Arauna sade till David: Min herre Konungen tage och offre såsom honom täckes; si, der äro oxarna till bränneoffer, och slädar, och redskapen till oxarna till ved.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Allt gaf Arauna Konungenom; och Arauna sade till Konungen: Herren din Gud låte dig vara sig behagelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Men Konungen sade till Arauna: Icke så, utan jag vill köpa dig det af för penningar; ty jag vill icke göra Herranom minom Gud bränneoffer, det jag till gifvins hafver. Alltså köpte David ladona, och oxarna, för femtio siklar silfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Och byggde dersammastäds Herranom ett altare; och offrade bränneoffer, och tackoffer. Och Herren vardt landena försonad, och plågan vände åter på Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Och då Konung David var gammal, och väl till ålders kommen, kunde han icke varda varm, ändå man höljde honom med kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Då sade hans tjenare till honom: Låt dem söka minom herra Konungenom en pigo, en jungfru som står för Konungenom, och sköter honom, och sofver i hans famn, och värmer min herra Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Och de sökte upp en dägelig pigo i alla Israels gränsor, och funno Abisag af Sunem, och hade henne till Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Och hon var en ganska dägelig piga, och hon skötte Konungen, och tjente honom; men Konungen kände henne intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Men Adonia, Haggiths son, hof sig upp, och sade: Jag vill vara Konung; och gjorde sig vagnar och resenärar, och femtio män till drabanter för sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Och hans fader bekymrade honom intet i sinom tid, så att han sade: Hvi gör du så? Och han var ock en dägelig man; och han hade födt honom näst efter Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Och han hade sitt råd med Joab, ZeruJa son, och med AbJathar Presten; de hulpo Adonia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Men Presten Zadok, och Benaja, Jojada son, och Nathan Propheten, och Simei, och Rei, och de Davids hjeltar, voro icke med Adonia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Och då Adonia offrade får, och oxar, och gödd boskap, vid den stenen Soheleth, som låg vid den brunnen Rogel, böd han alla sina bröder Konungens söner, och alla Juda män Konungens tjenare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Men den Propheten Nathan, och Benaja, och de hjeltar, och Salomo, sin broder, böd han intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Då sade Nathan till BathSeba, Salomos moder: Hafver du icke hört, att Adonia, Haggiths son, är Konung vorden, och vår herre David vet intet deraf?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Så kom nu, jag vill gifva dig ett råd, att du må undsätta dina och dins sons Salomos själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Bort, och gack in till Konungen David, och säg till honom: Hafver du icke, min herre Konung, svorit, och sagt dina tjenarinno: Din son Salomo skall vara Konung efter mig, och han skall sitta på minom stol; hvi är då Adonia Konung vorden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Si, medan du ännu der är, och talar med Konungenom, vill jag komma in efter dig, och fullkomna ditt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Och BathSeba gick in till Konungen i kammaren; och Konungen var ganska gammal; och Abisag af Sunem tjente Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Och BathSeba böjde sig, och tillbad Konungen. Konungen sade: Hvad vill du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Hon sade till honom: Min Herre, du hafver svorit dine tjenarinno vid Herran din Gud: Din son Salomo skall vara Konung efter mig, och sitta på minom stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Men nu, si, Adonia är Konung vorden; och min herre Konungen vet intet deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Han hafver offrat oxar, och gödd boskap, och mång får, och hafver budit alla Konungens söner; dertill AbJathar Presten, och Joab härhöfvitsmannen; men din tjenare Salomo hafver han intet budit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Men du äst min herre Konung; hela Israels ögon se på dig, att du skall gifva dem före, ho som skall sitta på mins herras Konungens stol efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'När nu min herre Konungen med sina fader afsomnad är, så måste jag och min son Salomo syndare vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Medan hon ännu talade med Konungenom, kom Propheten Nathan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Och de sade Konungenom till: Si, Propheten Nathan är der. Och som han kom in för Konungen, tillbad han Konungen på sitt ansigte neder till jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Och sade: Min herre Konung, hafver du sagt: Adonia skall vara Konung efter mig, och sitta på minom stol?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Ty han är i dag nedergången, och hafver offrat oxar, och gödd boskap, och mång får, och hafver budit alla Konungens söner, och höfvitsmännerna, dertill Presten AbJathar; och si, de äta och dricka för honom, och säga: Lycka ske Konungenom Adonia!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Men mig din tjenare, och Zadok Presten, och Benaja, Jojada son, och din tjenare Salomo, hafver han intet budit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Är det så af minom herra Konungenom befaldt, och du hafver det din tjenare icke veta låtit, hvilken uppå mins herras Konungens stol efter honom sitta skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Konung David svarade, och sade: Kaller mig BathSeba. Och hon kom in för Konungen; och då hon stod för Konungenom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Svor Konungen, och sade: Så sant som Herren lefver, som min själ förlossat hafver utur alla nöd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Jag vill i dag göra, såsom jag dig vid Herran Israels Gud svorit hafver, och sagt: Salomo din son skall vara Konung efter mig, och han skall sitta på minom stol för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Då böjde sig BathSeba med sitt anlete neder till jordena, och tillbad Konungen, och sade: Lycka minom herra Konung David i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Och Konung David sade: Kaller mig Presten Zadok, och Propheten Nathan, och Benaja, Jojada son. Och då de kommo in för Konungen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Sade Konungen till dem: Tager med eder edars herras tjenare, och sätter min son Salomo uppå mina mulo, och förer honom ned till Gihon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Och Presten Zadok, samt med Propheten Nathan, smörje honom der till Konung öfver Israel; och blåser med basuner, och säger: Lycka ske Konung Salomo!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Och drager med honom upp, och kommer, så skall han sitta på minom stol, och vara Konung för mig; och jag vill bjuda honom, att han skall vara en Förste öfver Israel och Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Då svarade Benaja, Jojada son, Konungenom, och sade: Amen; det säge också Herren, mins herras Konungens Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Såsom Herren hafver varit med min herra Konungenom, så vare han ock med Salomo, att hans stol må större varda än mins herras Konung Davids stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Då gingo Presten Zadok och Propheten Nathan, och Benaja, Jojada son, och Crethi och Plethi, neder, och satte Salomo på Konung Davids mulo, och förde honom till Gihon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Och Presten Zadok tog oljohornet utu tabernaklet, och smorde Salomo; och de blåste med basuner, och allt folket sade: Lycka ske Konung Salomo!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Och allt folket drog upp efter honom, och folket pipade med pipor, och var ganska gladt, så att det skall i markene utaf deras skri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Och Adonia hörde det, och alle de budne som med honom voro, och de hade allaredo ätit; och då Joab hörde basunens ljud, sade han: Hvart vill det skriet och bullret i stadenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Som han ännu talade, si, då kom Jonathan, AbJathars Prestens son; och Adonia sade: Kom härin; ty du äst en dugelig man, och bär god tidende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Jonathan svarade, och sade till Adonia: Ja, vår herre Konung David hafver gjort Salomo till Konung;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Och hafver sändt med honom Presten Zadok, och Propheten Nathan, och Benaja, Jojada son, och Crethi och Plethi; och de hafva satt honom på Konungens mulo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Och Presten Zadok, med Propheten Nathan hafver smort honom till Konung i Gihon; och de äro uppdragne dädan med fröjd, så att staden sorlar; det är det skri, som I hört hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Dertill sitter Salomo på Konungastolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Och Konungens tjenare hafva ingångit till att välsigna vår herra Konung David, och hafva sagt: Din Gud göre Salomo ett bättre namn än ditt namn är, och göre hans stol större än din stol; och Konungen hafver tillbedit, der han låg på sängene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Och Konungen hafver så sagt: Lofvad vare Herren Israels Gud, som i dag hafver låtit en sitta på minom stol, så att min ögon det sett hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Då vordo förskräckte och stodo upp alle de som när Adonia budne vore, och gingo bort, hvar och en sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Men Adonia fruktade sig för Salomo, och stod upp, och gick bort, och fattade hornen af altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Och Salomo vardt sagdt: Si, Adonia fruktar för Konung Salomo; och si, han fattar altarets horn, och säger: Konung Salomo svärje mig i dag, att han icke dräper sin tjenare med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Salomo sade: Vill han vara redelig, så skall icke ett hår af honom falla på jordena; men varder något ondt befunnet med honom, så skall han dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Och Konung Salomo sände bort, och lät hemta honom neder ifrån altaret; och då han kom, tillbad han Konung Salomo; men Salomo sade till honom: Gack i ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Som nu tiden led, att David skulle dö, böd han sinom son Salomo, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Jag går alla verldenes väg; så var nu tröst, och var en man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Och akta på Herrans dins Guds vakt, så att du vandrar i hans vägar, och håller hans seder, bud, rätter, vittnesbörd, såsom skrifvet är i Mose lag; på det du skall vara klok i allt det du gör, och ehvart du dig vänder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'På det Herren skall uppväcka sitt ord, som han öfver mig talat hafver och sagt: Om din barn bevara sina vägar, så att de vandra troliga, och af allt hjerta och af allo själ, för mig, så skall aldrig fattas af dig en man på Israels stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Och vetst du väl hvad Joab, ZeruJa son, hafver gjort mig, hvad han gjorde de två härhöfvitsmän i Israel, Abner, Ners son, och Amasa, Jethers son, hvilka han drap, och utgöt krigsblod i fridenom, och lät komma krigsblod uppå sitt bälte, det omkring hans länder var, och uppå sina skor, som på hans fötter voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Gör efter dina vishet, så att du icke förer hans grå hår med frid ned till helvete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Och Barsillai barnom, den Gileaditens, skall du bevisa barmhertighet, så att de äta vid ditt bord; förty de gåfvo sig till mig, då jag flydde för dinom broder Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Och si, du hafver Simei när dig, Gora son, Jemini sons af Bahurim, den mig skamliga bannade, på den tid jag gick till Mahanaim; men han kom neder emot mig vid Jordan; då svor jag honom vid Herran, och sade: Jag vill icke dräpa dig med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Men låt icke du blifva honom oskyldig; ty du äst en vis man, och vetst väl hvad du honom göra skall, att du låter hans grå hår med blod komma neder till helvete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Så afsomnade då David med sina fäder, och vardt begrafven uti Davids stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Men tiden, som David hade varit Konung öfver Israel, var fyratio år. I sju år var han Konung i Hebron, och tre och tretio år i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Och Salomo satt på sins faders Davids stol, och hans rike vardt storliga befäst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Men Adonia, Haggiths son, kom in till BathSeba, Salomos moder; och hon sade: Kommer du ock med frid? Han sade: Ja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Och han sade: Jag hafver något tala med dig. Hon sade: Säg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Han sade: Du vetst, att riket var mitt; och hela Israel hade vändt sitt ansigte till mig, att jag skulle vordit Konung; men nu är riket förvändt, och vordet mins broders; af Herranom är det hans vordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nu beder jag en bön af dig låt icke mitt ansigte komma till blygd. Hon sade till honom: Säg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Han sade: Tala med Konungen Salomo, ty han låter icke ditt ansigte komma till blygd, att han gifver mig Abisag af Sunem till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'BathSeba sade: Väl; jag vill på dina vägnar tala till Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Och BathSeba kom in till Konung Salomo, till att tala med honom, på Adonia vägnar. Och Konungen stod upp, och gick emot henne, och tillbad henne, och satte sig på sin stol; och för Konungens moder vardt ock satt en stol, så att hon satte sig på hans högra sido.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Och hon sade: Jag beder en liten bön af dig; låt icke mitt ansigte komma till blygd. Konungen sade till henne: Bed, min moder; jag vill icke låta ditt ansigte komma till blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Hon sade: Låt gifva Abisag af Sunem dinom broder Adonia till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Då svarade Konung Salomo, och sade till sina moder: Hvi beder du om Abisag af Sunem till Adonia? Bed honom ock riket med; förty han är min äldste broder, och han hafver Presten AbJathar och Joab, ZeruJa son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Och Konung Salomo svor vid Herran och sade: Gud göre mig det och det, Adonia skall detta hafva talat emot sitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Och nu, så visst som Herren lefver, den mig stadfäst hafver, och låtit sitta på mins faders Davids stol och den mig ett hus gjort hafver, såsom han sagt hafver; i dag skall Adonia dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Och Konung Salomo sände bort Benaja, Jojada son; han slog honom, så att han blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Och till Presten AbJathar sade Konungen: Gack bort till Anathoth till din åker, ty du hörer döden till; men jag vill icke dräpa dig i dag; förty du hafver burit Herrans Herrans ark för minom fader David, och hafver med lidit, hvad som helst min fader lidit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Alltså fördref Salomo AbJathar, att han icke måtte blifva Herrans Prest; på det Herrans ord fullbordas skulle, som han öfver Eli hus talat hade i Silo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Och detta ryktet kom för Joab; ty Joab höll sig intill Adonia, ehuruväl han icke hade hållit sig till Absalom. Då flydde Joab in uti Herrans tabernakel, och fattade hornen af altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Och det vardt bådadt Konung Salomo, att Joab var flydd uti Herrans tabernakel, och si, han står vid altaret. Då sände Salomo Benaja, Jojada son, och sade: Gack, och slå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Och då Benaja kom till Herrans tabernakel, sade han till honom: Så säger Konungen: Gack härut. Han sade: Nej, här vill jag dö. Och Benaja sade detta Konungenom igen, och sade: Så hafver Joab sagt, och så hafver han svarat mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Konungen sade till honom: Gör såsom han sagt hafver, och slå honom, och begraf honom, att du ifrå mig och mins faders hus tager det blod, som Joab oförskyldt utgjutit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Och Herren betale honom hans blod uppå hans hufvud, att han hafver slagit två män, de der redeligare och bättre voro än han; och hafver dräpit dem med svärd, så att min fader David deraf intet visste, nämliga Abner, Ners son, den härhöfvitsmannen öfver Israel, och Amasa, Jethers son, härhöfvitsman öfver Juda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Så att deras blod må betaldt varda på Joabs hufvud, och hans säds, i evig tid. Men David och hans säd, hans hus och hans stol, hafve frid af Herranom i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Och Benaja, Jojada son, gick upp, och slog honom, och drap honom; och han vardt begrafven i sitt hus i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Och Konungen satte Benaja, Jojada son, i hans stad öfver hären; och Zadok Presten satte Konungen i AbJathars stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Och Konungen sände bort, och lät kalla Simei, och sade till honom: Bygg dig ett hus i Jerusalem, och bo der, och gack intet ut dädan, antingen hit eller dit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'På hvilken dag du der utgår, och går öfver den bäcken Kidron, så vet att du skall döden dö; ditt blod vare på ditt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Simei sade till Konungen: Det är en god mening; såsom min herre Konungen sagt hafver, så skall din tjenare göra. Så bodde Simei i Jerusalem i långan tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Men det begaf sig efter tre år, att två tjenare lupo ifrå Simei till Achis, Maacha son, Konungen i Gath. Och Simei vardt sagdt: Si, dine tjenare äro i Gath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Då stod Simei upp, och sadlade sin åsna, och drog åstad till Gath till Achis, att han skulle söka sina tjenare; och då han ditkom, förde han sina tjenare ifrå Gath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Och det vardt sagdt Salomo, att Simei var faren af Jerusalem till Gath, och igen kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Då sände Konungen bort, och lät kalla Simei, och sade till honom: Hafver jag icke svorit dig vid Herran, och betygat dig, och sagt: På hvilken dag du fore ut, antingen hit eller dit, att du då veta skulle att du skulle döden dö? Och du sade till mig: Jag: hafver hört en god mening.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Hvi hafver du då icke hållit dig efter Herrans ed, och det bud som jag dig budit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Och Konungen sade till Simei: Du vetst allt det onda, som ditt hjerta med sig vet, som du minom fader David gjort hafver; Herren hafver betalat dina ondsko på ditt hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Och Konung Salomo är välsignad, och Davids stol varder befäst för Herranom i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Och Konungen böd Benaja, Jojada son. Han gick ut, och slog honom, att han blef död. Och riket vardt befäst i Salomos hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Och Salomo befryndade sig med Pharao, Konungenom i Egypten, och tog Pharaos dotter, och förde henne uti Davids stad, tilldess han skulle fullbygga sitt hus, och Herrans hus, och muren omkring Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Men folket offrade ännu på höjdomen; ty det var ändå intet hus bygdt Herrans Namne, intill den tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Men Salomo hade Herran kär, och vandrade efter sins faders Davids seder; undantagno att han offrade, och rökte uppå höjdomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Och Konungen gick bort till Gibeon, till att offra der; ty der var en härlig höjd; och Salomo offrade tusende bränneoffer på det samma altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Och Herren syntes Salomo i Gibeon, uti en dröm om nattene. Och Gud sade: Bed hvad jag skall gifva dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomo sade: Du hafver gjort med min fader David din tjenare stora barmhertighet, såsom han vandrade för dig i sanning och rättfärdighet, och med ett rättsinnigt hjerta när dig; och du hafver hållit honom denna stora barmhertigheten, och gifvit honom en son, som på hans stol sitta skulle, såsom nu tillgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Nu, Herre min Gud, du hafver gjort din tjenare till Konung i mins faders Davids stad; så är jag en ung dräng, och vet icke min utgång eller ingång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Och din tjenare är ibland ditt folk, som du utvalt hafver, det så mycket är, att det ingen räkna eller beskrifva kan, för myckenhets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Så gif nu dinom tjenare ett lydaktigt hjerta, att han må döma ditt folk, och förstå hvad godt och ondt är; ty ho förmår döma detta ditt mägtiga folk?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Då täcktes det Herranom väl, att Salomo bad om sådant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Och Gud sade till honom: Efter du detta beddes, och bad icke om långt lif eller rikedomar, eller om dina fiendars själar, utan om förstånd till att döma,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Si, så hafver jag gjort efter din ord; si, jag hafver gifvit dig ett vist och förståndigt hjerta, så att din like hafver icke varit för dig, och icke heller efter dig uppkomma skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Dertill det du icke bedit hafver, det hafver jag också gifvit dig, nämliga rikedomar och härlighet; så att ingen skall vara din like ibland Konungarna i dina dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Och om du vandrar i mina vägar, så att du håller mina seder och bud, såsom din fader David vandrat hafver, så vill jag gifva dig långt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Och då Salomo vaknade, si, då var det en dröm; och han kom till Jerusalem, och gick fram för Herrans förbunds ark, och offrade bränneoffer och tackoffer; och gjorde ett stort gästabåd allom sinom tjenarom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'På den tiden kommo två skökor för Konungen, och gingo fram för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Och den ena qvinnan sade: Ack! min Herre, jag och denna qvinnan bodde uti ett hus, och jag födde när henne i huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Och efter tre dagar, sedan jag födt hade, födde hon och; och vi voro tillhopa, så att ingen främmande var med oss i huset, utan vi båda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Och denna qvinnones son blef död om nattena; ty hon förkramade honom i sömnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Och hon stod upp om nattena, och tog min son ifrå mine sido, vid din tjenarinna sof, och lade honom på sin arm; och sin döda son lade hon på min arm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Och då jag om morgonen uppstod, till att gifva min son dia, si, då var han död; men om morgonen såg jag granneliga på honom, och si, det var icke min son, den jag födt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Den andra qvinnan sade: Det är icke så; min son lefver, och din son är död. Men denna sade: Det är icke så; din son är död, och min son lefver; och talade alltså för Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Och Konungen sade: Denna säger: Min son lefver, och din son är död; den andra säger: Icke så; din son är död, och min son lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Och Konungen sade: Tager mig hit ett svärd. Och då svärdet var buret fram till Konungen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Sade Konungen: Hugger det lefvande barnet i tu stycker, och gifver desso hälftena; och den andro ock hälftena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Då sade qvinnan, hvilkens barn lefde, till Konungen (ty hennes moderliga hjerta gaf sig öfver sin son): Ack! min Herre, gifver henne barnet lefvandes, och dräper det icke. Men den andra sade: Det vare hvarken mitt eller ditt, låt skiftat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Då svarade Konungen, och sade: Gifver desso barnet lefvandes, och dräper det icke; hon är dess moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Och den domen, som Konungen afsagt hade, spordes för hela Israel, och de fruktade Konungen; förty de sågo, att Guds vishet var i honom till att döma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Alltså vardt Salomo Konung öfver hela Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Och desse voro hans Förstar: AsarJa, Zadoks son, Prestens,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoreph och AhiJa, Sisa söner, voro skrifvare; Josaphat, Ahiluds son, var canceller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaja, Jojada son, var härhöfvitsman; Zadok och AbJathar voro Prester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'AsarJa, Nathans son, var öfver ämbetsmännerna; Sabud, Nathans son, Prestens, var Konungens vän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahisar var hofmästare; Adoniram, Abda son, var räntomästare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Och Salomo hade tolf befallningsmän öfver hela Israel, som försörjde Konungen och hans hus; hvar hade en månad om året till att försörja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Och de heto alltså: Hurs son på Ephraims berg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Dekers son i Makaz, och i Saalbim, och i BethSemes, och i Elon BethHanan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Heseds son i Aruboth, och hade dertill Socho, och hela landet Hepher;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'AbiNadabs son hela landet Dor; och hade Taphath, Salomos dotter, till hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, Ahiluds son, i Taanach, och i Megiddo, och öfver hela BethSean, hvilket ligger vid Zarthana under Jisreel, ifrå BethSean intill den planen Mehola, intill hinsidon Jokmeam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Gibers son i Ramoth i Gilead; och hade de städer Jairs, Manasse sons, i Gilead; och hade den ängden Argob, som i Basan ligger, sextio stora städer murade, och med kopparbommar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab, Iddo son, i Mahanaim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaaz i Naphthali; och han tog också Basmath, Salomos dotter, till hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, Husai son, i Asser och i Aloth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jasaphat, Paruahs son, i Isaschar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei, Ela son, i BenJamin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, Uri son, i Gileads land, i Sihons, de Amoreers Konungs land; och Ogs, Konungens i Basan; en befallningsman var i de samma landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Men Juda och Israel voro månge, såsom sanden i hafvet, och de åto och drucko, och voro glade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Alltså var Salomo en herre öfver all rike, ifrån älfvene intill de Philisteers land, och allt intill de Egyptiers gränso; hvilke honom förde skänker, och tjente honom i hans lifstid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Och Salomo måste dagliga hafva till spisning tretio corer semlomjöl, sextio corer annat mjöl,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Tio gödda oxar, och tjugu oxar af betene, och hundrade får; förutan hjort och rå, stengetter, och hvad man på stall höll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Ty han var rådandes i hela landena, på denna sidon älfven, ifrå Tiphsah allt intill Gasa, öfver alla de Konungar på denna sidon älfven; och hade frid med alla sina grannar allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Så att Juda och Israel bodde trygge, hvar och en under sitt vinträ, och under sitt fikonaträ, ifrå Dan allt intill BerSeba, så länge Salomo lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Och Salomo hade fyratiotusend vagnhästar, och tolftusend resenärar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Och befallningsmännerna försörjde Konung Salomo, och allt det som till Konungens bord hörde, hvar och en i sin månad; och läto intet fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Sammalunda ock korn, och halm för hästar och mular, förde de dit som han var, hvar och en efter som honom befaldt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Och Gud gaf Salomo ganska stor visdom och förstånd, och ett fritt mod, såsom sanden som ligger på hafsens strand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Så att Salomos visdom var större, än alla österländningabarnas, och alla Egyptiers visdom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Och var visare än alla menniskor, och visare än Ethan den Esrahiten, Heman, Chalchol och Darda, Mahols söner; och var namnkunnig ibland alla Hedningar allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Och han talade tretusend ordspråk; och hans visor voro tusende och fem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Och han talade om trä, ifrå ceder, som är i Libanon, allt intill isop, som växer utu väggene; desslikes talade han om djur, om foglar, om matkar, om fiskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Och utaf all folk kommo till att höra Salomos visdom, ifrån alla Konungar på jordene, som af hans visdom hört hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Och Hiram, Konungen i Tyro, sände sina tjenare till Salomo; ty han hade hört, att de hade smort honom till Konung i hans faders stad; ty Hiram älskade David så länge han lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Och Salomo sände till Hiram, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Du vetst, att min fader David icke kunde bygga Herrans sins Guds Namne ett hus, för örligs skull, som allt omkring honom var, intilldess Herren gaf dem under hans fotbjelle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Men nu hafver Herren min Gud gifvit mig rolighet allt omkring, så att ingen motståndare, eller ondt hinder mer på färde är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Si, så hafver jag tänkt bygga ett hus, Herrans mins Guds Namne, såsom Herren talat hafver till min fader David, och sagt: Din son, som jag i din stad sätta skall på din stol, han skall bygga mino Namne hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Så befall nu, att man hugger mig ceder utu Libanon, och att dine tjenare äro med mina tjenare, och dina tjenares lön vill jag gifva dig, allt såsom du säger; ty du vetst, att när oss är ingen som kan hugga trä, såsom de Zidonier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Då Hiram hörde Salomos ord, fröjdade han sig storliga, och sade: Lofvad vare Herren i denna dag, som hafver gifvit David en visan son öfver detta myckna folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Och Hiram sände till Salomo, och lät säga honom: Jag hafver hört det du till mig sändt hafver; jag vill göra efter allt ditt begär med ceder och furoträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Mine tjenare skola föra dem neder af Libanon ut till hafvet; och jag vill låta lägga dem i flottor på hafvet, intill det rum som du mig föresägandes varder, och vill lossa dem der, och du skall låta hemta dem; men du skall ock göra mitt begär, och gifva mino folke kost.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Alltså gaf Hiram Salomo ceder och furoträ, efter allt hans begär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Och Salomo gaf Hiram tjugutusend corer hvete till kost för hans folk, och tjugu corer stött oljo; detta gaf Salomo Hiram årliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Och Herren gaf Salomo visdom, såsom han honom sagt hade; och var frid emellan Hiram och Salomo, och de gjorde både ett förbund med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Och Salomo böd uppå en utgärd öfver hela Israel; och i utgärdene voro tretiotusend män;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Och sände uppå Libanon, ju i hvarje månad tiotusend; så att de voro en månad på Libanon, och två månader hemma; och Adoniram var öfver den utgärden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Och Salomo hade sjutiotusend, de som båro bördor, och åttatiotusend, de som höggo på bergena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Förutan de öfversta Salomos befallningsmän, som öfver verket satte voro; nämliga tretusend och trehundrad, hvilke rådde öfver folket som arbetade på verket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Och Konungen; böd, att de skulle bryta ut stora och kosteliga stenar; nämliga huggna stenar, till husets grundval.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Och Salomos byggningsmän, och Hirams byggningsmän, och de som vid gränsona voro, höggo ut, och tillredde trä och stenar till husets byggning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Uti fjerde hundrade och åttationde årena, sedan Israels barn drogo utur Egypti land, i fjerde årena, sedan Salomo vardt rådandes öfver Israel, uti den månaden Sif, det är den andra månaden, vardt huset bygdt Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Och huset, som Konung Salomo byggde Herranom, var sextio alnar långt, tjugu alnar bredt, och tretio alnar högt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Och byggde ett förhus för templet, tjugu alnar långt, efter husets bredd, och tio alnar bredt, frammanför huset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Och gjorde fenster på huset, de man upp och åter låta kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Och han byggde en omgång på väggene af huset allt omkring, så att han gick både omkring templet och choren, och gjorde hans yttra vägg omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Den nederste gången var fem alnar bred, och den medlersta sex alnar bred, och den tredje sju alnar bred; ty han lade bjelkar utan omkring huset, så att de icke skulle gå in i väggena på huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Och då huset byggdes, vardt det bygdt af helom stenom, såsom de framförde voro; så att man intet hörde någon hammar, eller yxe, eller någon jernredskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Och en dörr var på högra sidone midt på husena, så att man uppgick genom en vindsten upp i den medelgången; och ifrå medelgången upp till den tredje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Alltså byggde han huset, och fullkomnade det, och bedrog huset med ceder, både ofvan och på väggarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Han byggde ock en gång ofvanpå hela huset omkring, fem alnar hög, och täckte huset med cedreträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Och Herrans ord kom till Salomo, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Det vare det hus, som du bygger; om du vandrar i min bud, och gör efter mina rätter, och håller all min bud, till att vandra deruti, så vill jag stadfästa min ord med dig, såsom jag dinom fader David sagt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Och vill bo ibland Israels barn, och skall icke öfvergifva mitt folk Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Alltså byggde Salomo huset, och fullkomnade det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Och byggde väggarna af huset innantill på sidomen af ceder, ifrå husets golf allt upp till taket; och bedrog med trä innantill, och telde golfvet på huset med furobräder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Och han byggde bak i husena en cedervägg, tjugu alnar lång, ifrå golfvet allt inunder taket, och byggde derinne choren och det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Men templets hus utanför chorenom var fyratio alnar långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Innantill var hela huset alltsamman af ceder, med svarfvade knappar och blomverk, så att man ingen sten såg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Men choren gjorde han innantill i husena, att man skulle derinne sätta Herrans förbunds ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Och för chorenom, den tjugu alnar lång, tjugu alnar bred, och tjugu alnar hög, och med klart guld bedragen var, bedrog han altaret med ceder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Och Salomo bedrog huset innantill med klart guld, och satte gyldene bommar för choren, som han med guld bedragit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Så att hela huset alltsammans med guld bedraget var. Dertill bedrog han ock hela altaret för choren allt öfver med guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'I Han gjorde ock i chorenom två Cherubim, tio alnar höga, utaf olivoträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Fem alnar höll hvar vingen af hvar Cherub, så att tio alnar voro ifrån andanom af den ena vingan, intill ändan på hans andra vinga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Alltså höll den andre Cherub ock tio alnar; och var lika mått och lika rum åt båda Cherubim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Så att hvar Cherub var tio alnar hög.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Och han satte de Cherubim innan i huset; och Cherubim räckte ut vingarna, så att ensderas vinge kom intill denna väggena; och dens andras Cherubs vinge kom intill den andra väggena; med midt i huset kom den enes vinge intill den andras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Och han bedrog de Cherubim med guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Och på alla husets väggar allt omkring lät han göra snidverk med utskorna Cherubim, palmar och blomverk, innan och utan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Och bedrog han golfvet af huset med gyldene skifvor, innan och utan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Och i chorens ingång gjorde han två dörrar af olivoträ, med femhörnad dörrträ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Och lät göra snidverk deruppå af Cherubim, palmar och blomverk, och öfverdrog dem med gyldene skifvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Alltså gjorde han ock i templets ingång fyrahörnad dörrträ af olivoträ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'Och två dörrar af furoträ, så att hvar dörren var i två delar, som tillhopahängde på deras hängsler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Och han gjorde deruppå snidverk af Cherubim, palmar och blomverk, och öfverdrog dem med guld, allt såsom det befaldt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Och han byggde desslikes en gård derinne af tre radar huggen sten, och af en rad höflad ceder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Uti fjerde årena i den månaden Sif vardt grundvalen lagd till Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Och i ellofte årena i den månaden Bul, det är den åttonde månaden, vardt huset redo, som det vara skulle, så att de byggde der i sju år uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Men uppå sitt hus byggde Salomo i tretton år, förr än det allt fullbygdt var, nämliga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Han byggde ett hus af Libanons skog, hundrade alnar långt, femtio alnar bredt, och tretio alnar högt. På det samma fyrhörnada lade han bottnen af cedrebräde, på cedrestodar å rad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Och der ofvanuppå en sal af ceder på samma stodar, hvilka voro fem och fyratio, ju femton i hvar rad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Och voro fenster efter de tre radarna, tvärtemot hvartannat, tre emot tre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Och voro i deras bågar fyrahörnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Han byggde ock ett förhus med stodar, femtio alnar långt, och tretio alnar bredt; och ändå ett förhus för desso, med stodar och tjocka, bjelkar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Och byggde desslikes ett förhus till domstolen, der man rättgång uti hålla skulle, och telde båda bottnarna med cedreträ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Dertill sitt hus, der han uti bodde, i bakgårdenom bak vid förhuset, gjordt såsom de andra. Och gjorde han också ett hus såsom förhuset till Pharaos dotter, den Salomo till hustru tagit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Allt detta voro kostelige stenar huggne efter mått, och med såg skorne på alla sidor, ifrå grundvalen allt upp till taket; dertill ock utantill den store gården.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Grundvalarne voro af kosteliga och stora stenar, tio och åtta alnar stora;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Och deruppå kostelige huggne stenar efter mått, och ceder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Men den store gården omkring hade tre radar huggen sten, och en rad af cedrebräde. Sammalunda ock gården till Herrans hus innantill, och förhuset till huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Och Konung Salomo sände bort, och lät hemta Hiram af Tyro,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Ene enkos son af Naphthali slägte, och hans fader hade varit en man af Tyro; han var en mästare på koppar, full med visdom, förstånd och konst, till att arbeta allahanda kopparverk. Då han kom till Konung Salomo, gjorde han allt hans verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Och gjorde två kopparstodar, hvardera aderton alnar hög; och en tråd, tolf alnar lång, var måttet omkring hvarjo stodena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Och gjorde två knappar, gjutna af koppar, till att sätta ofvanpå stoderna; och hvar knappen var fem alnar hög:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Och på hvar knappen ofvanpå stoderna sju flätade gjordar såsom kedjor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Och gjorde till hvar knappen två radar granatäple omkring, till ena gjord, der knappen med öfvertäckt vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Och knapparna voro såsom roser för förhusena, fyra alnar store.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Och de granatäplen i radarna omkring voro tuhundrad, ofvan och under på gjorden, som gick midt om knappen, om hvar knapp på båda stoderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Och han uppreste de stoderna inför förhusena af templet, och den som han satte på högra sidon, kallade han Jachin; och den som han satte på venstra sidon, kallade han Boas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Och det stod ofvanpå stoderna såsom roser. Alltså vardt fullkomnadt de stoders verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Och han gjorde ett haf gjutet, tio alnar bredt, ifrå den ena bräddene till den andra, rundt omkring; och fem alnar högt, och måttet rätt omkring var tretio alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Och om det samma hafvet, det tio alnar bredt var, gick en krusering utmed dess brädd, allt omkring hafvet; den kruseringen var gjuten i två radar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Och det stod på tolf oxar; tre af dem vände sig norrut, tre vesterut, tre söderut, och tre österut; och hafvet der ofvanuppå; så att all bakdelen af dem var inunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Tjockheten af thy var en tvärhand; och brädden deruppå var såsom brädden på en bägare, såsom en utsprungen ros; och tutusende bath gick deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Han gjorde ock tio kopparstolar; hvardera fyra alnar lång och bred, och tre alnar hög.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Och var stolen så gjord, att han hade sidor emellan listor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Och på sidomen emellan listorna voro lejon, oxar och Cherubim, och sidorna, der lejonen, oxarna och Cherubim voro uppå, hade listor ofvan och nedan, och fötter deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Och hvar stolen hade fyra kopparhjul med kopparaxlar. Och uppå fyra hörnen voro gjutna styltor, hvar emot den andra stödjandes under kettilen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Men halsen midt på stolen var en aln hög och trind; half annan aln bred, och på halsenom voro bulor i planarna, hvilke fyrkant voro, och icke runde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Men de fyra hjul stodo nedan under sidorna, och axlarna åt hjulen voro vid stolen; hvart hjulet var halfannor aln högt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Och voro hjul såsom vagnshjul; och deras axlar, naf, ekrar och löter, voro allt gjutne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Och de fyra styltor, på de fyra hörnen af hvar stolen, voro ock alla fasta vid stolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Och på halsenom, ofvanuppå stolen en half aln högt allt omkring, voro listor och sidor på stolenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Och han lät grafva på det slätt var, på samma sidor och listor, Cherubim, lejon och palmträ, det ena efter det andra allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Vid det sättet gjorde han de tio gjutna stolar; enahanda mått och rum var på dem allom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Och han gjorde tio kopparkettlar, så att fyratio bath gingo uti hvar kettilen; och den var fyra alnar stor, och på hvar stol var en kettil.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Och han satte fem stolar på högra sidone i huset, och de andre fem på venstra; men hafvet satte han rätt framföre på högra sidone, söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Och Hiram gjorde desslikes grytor, skoflar, bäcken; och fullkomnade så all verk, som Konung Salomo göra lät i Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Nämliga de två stoder, och de två runda knappar ofvanuppå de två stodar, och de två vridna gjordar, till att betäcka de två runda knappar på stoderna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Och de fyrahundrad granatäple på de två vridna gjordar, ju två rader granatäple på en gjord, till att betäcka de två runda knapparna på stoderna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Dertill de tio stolar, och de tio kettlar der ofvanuppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Och hafvet, och de tolf oxar under hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Och de grytor, skoflar och bäcken; och all denna kärilen, som Hiram gjorde åt Konung Salomo till Herrans hus, voro utaf klar koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'I den ängden vid Jordan lät Konungen gjuta dem, i den lermarkene emellan Succoth och Zarthan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Och Salomo lät all dessa kärilen ovägne blifva; derföre att kopparen var så mycken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Och gjorde Salomo all tyg, som Herrans hus tillhörde; nämliga ett gyldene altar, ett gyldene bord, der skådobröd på ligga skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'Fem ljusastakar på högra, och fem ljusastakar på den venstra sidone, framför choren, af klart guld, med gyldene blommor, lampor och ljusanäpor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Dertill skålar, fat, bäcken, skedar och pannor, af klart guld. Och voro dörrahängslorna på dörrarna åt innersta huset, som var det aldrahelgasta, och åt templets husdörr, af guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Alltså vardt fullkomnadt allt verk, som Konung Salomo gjorde till Herrans hus. Och Salomo bar ditin det som hans fader David helgat hade, af silfver och guld, och käril, och lade det in uti Herrans hus skatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Då församlade Konung Salomo till sig de äldsta af Israel, alla öfverstar i slägterna, och Förstar för fäderna ibland Israels barn, till Jerusalem, till att föra Herrans förbunds ark upp utu Davids stad, det är Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Och sig församlade till Konung Salomo alle män i Israel, uti den månaden Ethanim på högtidene, det är sjunde månaden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Och då alle äldste i Israel kommo, lyfte Presterna arken upp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Och båro Herrans ark ditupp; dertill vittnesbördsens tabernakel, och all helgedomens tyg, som i tabernaklet var; det gjorde Presterna och Leviterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Och Konung Salomo och hela Israels menighet, som sig till honom församlat hade, gingo med honom fram för arken, och offrade får, och fä, så mycket att man dem hvarken tälja eller räkna kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Alltså båro Presterna Herrans förbunds ark uti sitt rum i husets chor, i det aldrahelgasta, under Cherubims vingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Ty Cherubim räckte vingarna ut till det rum der arken stod, och öfverskylde arken och hans stänger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Och så långa voro stängerna, att deras ändar syntes i helgedomenom för choren; men utantill vordo de intet sedde; och de blefvo der intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Och i arkenom var intet, utan allenast de två Mose stentaflor, som han lät deruti i Horeb, då Herren gjorde ett förbund med Israels barnom, då de utur Egypti land dragne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Då nu Presterna gingo utu helgedomenom, uppfyllde en molnsky Herrans hus,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Så att Presterna icke kunde stå och sköta ämbetet för molnskyn; ty Herrans härlighet uppfyllde Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Då sade Salomo: Herren hafver sagt, att han ville bo i mörkrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Jag hafver byggt ett hus dig till boning; ett säte, att du skall bo der till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Och Konungen vände sitt ansigte, och välsignade hela menighetena Israel, och hela menigheten Israel stod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Och han sade: Lofvad vare Herren Israels Gud, som med sin mun med minom fader David talat, och med sine hand fullbordat hafver, och sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Ifrå den dag, då jag förde mitt folk Israel utur Egypten, hafver jag ingen stad utvalt i några af Israels slägter, att mig skulle varda ett hus bygdt, så att mitt Namn skulle vara der; men David hafver jag utvalt, att han skall vara öfver mitt folk Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Och min fader David hade väl i sinnet, att han skulle bygga Herrans Israels. Guds Namne ett hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Men Herren sade till min fader David: Att du hafver i sinnet bygga mino Namne ett hus, hafver du gjort väl, att du hade det i sinnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Dock skall icke du bygga det huset, utan din son, som utaf dina länder komma skall, han skall bygga mino Namne ett hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Och Herren hafver gjort sitt ord fast, som han talat hafver; ty jag är uppkommen i mins faders Davids stad, och sitter på Israels stol, såsom Herren sagt, och hafver byggt Herrans Israels Guds Namne ett hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Och hafver derutinnan tillpyntat ett rum till arken, som Herrans förbund uti är, det han gjort hafver med våra fäder, då han dem utur Egypti land förde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Och Salomo stod för Herrans altare emot hela Israels menighet, och räckte ut sina händer upp till himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Och sade: Herre Israels Gud, det är ingen Gud, antingen ofvantill i himmelen, eller nedre på jordene, din like; du som håller förbund och barmhertighet dinom tjenarom, som vandra för dig af allo hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Du som hafver hållit dinom tjenare David, minom fader, allt det du honom sagt hafver; med dinom mun hafver du talat det, och med dine hand hafver du fullkomnat det, såsom det nu i denna dag tillgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nu, Herre Israels Gud, håll dinom tjenare David, minom fader, det du med honom talat hafver, och sagt: Dig skall icke fattas en man för mig, som sitta skall på Israels stol; såframt din barn förvara sina vägar, att de vandra såsom du för mig vandrat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nu, Israels Gud, låt din ord blifva sann, som du till din tjenare David, min fader, talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Ty menar du ock, att Gud bor på jordene? Si, himmelen och alla himlars himlar kunna icke begripa dig; huru skulle då detta huset göra det, som jag nu byggt hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Så vänd dig till dins tjenares bon, och till hans begär, Herre min Gud, så att du hörer det lof, och den bön, som din tjenare gör för dig i dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Att din ögon måga stå öppne öfver detta hus, natt och dag; öfver det rum, der du om sagt hafver: Mitt Namn skall vara der; att du ville höra den bön, som din tjenare gör på detta rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Och ville höra dins tjenares, och dins folks Israels bön, den de här görande varda i detta rum; och höra det der du bor i himmelen; och när du det hörer, vara nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'När nu någor syndar emot sin nästa, och tager dess en ed uppå sig, der han sig med förpligtar, och eden kommer inför ditt altare i desso huse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Att du ville då höra i himmelen, och skaffa dina tjenare rätt, att du fördömer den ogudaktiga, och låter hans väg komma öfver hans hufvud; och rättfärdigar den rätta, att du honom gör efter hans rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Om ditt folk Israel vorde slaget för sina fiendar, efter de emot dig syndat hafva; och vända sig till dig, och bekänna ditt Namn, och bedja, och begära af dig i desso huse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Att du ville då hörat i himmelen, och dins folks Israels syndom nådelig vara; och föra dem åter i det land, som du deras fäder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Om himmelen igenlyckt varder, så att intet regnar, efter de emot dig syndat hafva; och varda bedjande på detta rum, och bekänna ditt Namn, och vända sig ifrå sina synder, efter du plågar dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Att du ville i himmelen höra dem, och vara dina tjenares, och dins folks Israels synder nådelig; att du visar dem den goda vägen, der de uti vandra skola, och låter regna på landet, som du dino folke till arfs gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Om en hård tid, eller pestilentie, eller torka, eller brand, eller gräshoppor, eller matkar på landet kommande varda; eller deras fiende belägger deras portar i landena, eller någor plåga eller krankhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Den då beder eller begärar, ehvad de äro andra menniskor, eller ditt folk Israel, som förnimma sina plågo, hvar och en i sitt hjerta, och räcka sina händer ut till detta huset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Att du ville då höra i himmelen, i det säte der du bor, och vara nådelig; och fly det så, att du gifver hvarjom och enom såsom han vandrat hafver, såsom du hans hjerta känner; ty du allena känner alla menniskors barnas hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'På det att de skola frukta dig alltid, så länge de lefva i landena, det du våra fäder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Om ock en främmande, som icke är af ditt folk Israel, kommer af fjerran land för ditt Namns skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'Ty de varda hörande om ditt stora Namn, och om dina mägtiga hand, och om din uträckta arm; och kommer till att bedja i desso huse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Att du då ville höra i himmelen, i det säte der du bor, och göra allt det den främmande dig om åkallar; på det all folk på jordene måga känna ditt Namn, att de ock frukta dig lika som ditt folk Israel, och förnimma, att detta huset efter ditt Namn nämndt är, det jag byggt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Om ditt folk utdrager i strid emot sina fiendar, den vägen som du dem sändandes varder, och de varda bedjande till Herran, emot vägen till den staden som du utvalt hafver, och emot huset som jag dino Namne byggt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Att du då ville höra deras bön och begär i himmelen, och skaffa dem rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Om de varda syndande emot dig; ty det är ingen menniska, som icke syndar; och du varder vred, och gifver dem för deras fiendar, så att de föra dem fångna i fiendaland, fjerran eller när;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Och de besinna sig i sitt hjerta, uti landena der de fångne äro, och omvända sig, och bedja dig uti deras fängelses land, och säga: Vi hafve syndat, och gjort illa, och varit ogudaktige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'Och vända sig så till dig af allt hjerta, af allo själ, uti deras fiendars land, som dem bortfört hafva, och bedja till dig emot vägen till deras land, som du deras fäder gifvit hafver, emot den staden som du utvalt hafver, och emot det huset som jag dino Namne byggt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Att du då ville höra deras bön och begär i himmelen, af det säte der du bor, och skaffa dem rätt,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Och vara dino folke nådelig, som emot dig syndat hafver, och all deras öfverträdelse, der de med hafva förbrutit sig emot dig; och gifva dem barmhertighet för dem som dem fångna hålla, att de förbarma sig öfver dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Förty de äro ditt folk, och ditt arf, som du utur Egypten, utu jernugnenom fört hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Att din ögon måga öppne vara till dins tjenares och dins folks Israels bön; att du ville höra dem i allt det, der de om åkalla dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Ty du hafver dem dig af skiljt till ett arf utur all folk på jordene, såsom du sagt hafver genom din tjenare Mose, då du våra fäder utur Egypten förde, Herre, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Och då Salomo hade all denna bön och begäran utbedit för Herranom, stod han upp ifrå Herrans altare, och höll upp att böja sin knä, och uträcka sina händer till himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Och stod, och välsignade alla menighetena Israel, med höga, röst, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Lofvad vare Herren, som sino folke Israel ro gifvit hafver, såsom han sagt hafver; icke ett är förfallet af hans goda ord, som han genom sin tjenare Mose talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Herren vår Gud vare med oss, såsom han varit hafver med våra fäder. Han öfvergifve oss icke, och tage icke handena bort ifrån oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Till att böja vårt hjerta till sig, att vi måge vandra i alla hans vägar, och hålla hans bud, seder och rätter, som han våra fäder budit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Och att desse orden, som jag för Herranom bedit hafver, måtte nalkas Herranom vårom Gud dag och natt, att han må skaffa sinom tjenare rätt, och sino folke Israel, hvarjom och enom i sinom tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'På det att all folk på jordene måga känna, att Herren är Gud, och ingen annar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Och edor hjerta vare rättsinnig med Herranom vårom Gud, till att vandra i hans seder, och till att hålla hans bud, såsom det tillgår i denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Och Konungen, samt med hela Israel, offrade offer för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Och Salomo offrade tackoffer, som han Herranom offrade, tu och tjugu tusend oxar, och hundradetusend och tjugutusend får. Alltså vigde de Herrans hus, Konungen och all Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'På samma dagen vigde Konungen medelgården, som var för Herrans hus, dermed att han der uträttade bränneoffer, spisoffer, och det feta af tackoffret; förty kopparaltaret, som för Herranom stod, var för litet till bränneoffer, spisoffer, och till det feta af tackoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Och Salomo gjorde på den tiden en högtid, och all Israel med honom en stor församling, ifrå den gränson Hamath, allt intill Egypti bäck, för Herranom vårom Gud i sju dagar, och åter i sju dagar; det voro fjorton dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Och på åttonde dagen lät han folket gå; och de välsignade Konungen, och gingo sina färde i sina hyddor, glädjandes och fröjdandes sig öfver allt det goda, som Herren med sinom tjenare David, och med sitt folk Israel, gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Och då Salomo hade fullbyggt Herrans hus, och Konungshuset, och allt det hans hjerta begärade, och lust hade till att göra,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Syntes honom Herren annan gång, såsom han honom synts hade i Gibeon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Och Herren sade till honom: Jag hafver hört dina bön och begär, som du för mig bedit hafver, och helgat detta huset, som du byggt hafver; så att jag skall sätta der mitt Namn till evig tid, och skola min ögon och mitt hjerta vara der alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Och du, om du vandrar för mig, såsom din fader David vandrat hafver, med rättsinnigt hjerta, och rättfärdighet, så att du gör allt det som jag dig budit hafver, och håller min bud och mina rätter,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Så vill jag befästa dins rikes stol öfver Israel i evig tid, såsom jag med din fader David talat hafver, och sagt: Dig skall icke fattas en man på Israels stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Hvar I ock vänden eder tillbaka ifrå mig, I och edor barn, och icke hållen min bud och rätter, som jag eder föresatt hafver; och gången bort och tjenen andra gudar, och tillbedjen dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Så skall jag utrota Israel ut af det land, som jag dem gifvit hafver; och det huset, som jag mino Namne helgat hafver, skall jag bortkasta ifrå mitt ansigte; och Israel skall vara till ett ordspråk och fabel ibland allt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Och detta huset skall förfalla, så att alle de som gå der framom skola förundra sig, och hvissla, och säga: Hvi hafver Herren desso lande och desso huse så gjort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Då skall blifva svaradt: Derföre, att de Herran sin Gud öfvergifvit hade, som deras fäder utur Egypti land förde, och tagit sig andra gudar, och tillbedit dem och tjent dem; derföre hafver Herren allt detta onda låtit komma öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Då nu de tjugu år framlidne voro, i hvilko Salomo de tu husen byggde, som var Herrans hus, och Konungshuset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Till hvilket Hiram, Konungen i Tyro, Salomo cedreträ, och furoträ, och guld, efter allt hans begär skickade; då gaf Konung Salomo Hiram tjugu städer i Galilea land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Och Hiram drog utaf Tyro, till att bese de städer, som Salomo honom gifvit hade; och de behagade honom intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Och sade: Hvad är detta för städer, min broder, som du mig gifvit hafver? Och han kallade dem Cabuls land allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Och Hiram hade sändt Konungenom hundrade och tjugu centener guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Och det är summan af skattenom, som Konung Salomo uppbar, till att bygga Herrans hus, och sitt hus, och Millo, och Jerusalems murar, och Hazor, och Megiddo, och Gaser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Ty Pharao, Konungen i Egypten, var uppkommen, och hade vunnit Gaser, och uppbränt det med eld, och slagit ihjäl de Cananeer, som i staden bodde, och hade gifvit honom sine dotter, Salomos hustru, till en skänk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Alltså byggde Salomo Gaser, och det nedra BethHoron,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Och Baalath, och Thadmor uti öknene, i landet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'Och alla kornhusstäder, som Salomo hade, och alla vagnsstäder, och resenärsstäder, och hvad som helst han lust hade till att bygga i Jerusalem, i Libanon, och hela landet, som under hans välde var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Och allt det folket, som igenblef af de Amoreer, Hetheer, Phereseer, Heveer och Jebuseer, som icke voro af Israels barnom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Deras barn, som de läto igenblifva efter sig i landena, hvilka Israels barn icke kunde tillspillogifva, dem gjorde Salomo skattskyldiga allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Men af Israels barnom gjorde han ingen till träl; utan lät dem vara krigsmän och sina tjenare, och Förstar, och riddare, och öfver hans vagnar och resenärar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Och de ämbetsmän, som voro öfver Salomos sysslor, voro femhundrad och femtio, som öfver folket rådde, och alla sysslor uträttade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Och Pharaos dotter drog upp ifrå Davids stad, uti sitt hus, som Salomo för henne byggt hade; då byggde han ock Millo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Och Salomo offrade tre resor om året bränneoffer, och tackoffer, på altaret, som han Herranom byggt hade, och rökte derpå för Herranom; och alltså vardt huset redo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Och Salomo gjorde desslikes skepp i EzionGeber, som vid Eloth ligger, på strandene vid det röda hafvet, uti de Edomeers land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Och Hiram sände sina tjenare till skepps, som förstodo sig på skepp, och till sjös förfarne voro, med Salomos tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Och de kommo till Ophir, och hemtade der fyrahundrad och tjugu centener guld, och förde till Konung Salomo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Och då Salomos rykte af Herrans Namn kom för Drottningen af rika Arabien, kom hon till att försöka honom med gåtor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Och hon kom till Jerusalem med en ganska stor skara, med cameler, som speceri båro, och med mycket guld och ädla stenar. Och då hon kom in till Konung Salomo, talade hon med honom allt det hon sig föresatt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Och Salomo sade henne det allt; och Konungenom var intet fördold, det han henne icke säga kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Då nu Drottningen af rika Arabien såg all Salomos visdom, och det hus, som han byggt hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Och rätterna på hans bord, och hans tjenares boningar, och hans tjenares ämbeten, och deras kläder, och hans skänkesvänner, och hans bränneoffer som han i Herrans hus offrade, kunde hon icke längre hålla sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Och sade till Konungen: Allt det jag i mitt land utaf ditt väsende, och af din visdom, hört hafver, det är sant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Och jag hafver icke velat trott det, tilldess jag är kommen, och hafver det med min ögon sett; och si, mig är icke hälften sagdt. Du hafver mer visdom och rikedomar, än ryktet är, som jag hört hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Salige äro dine män, och dine tjenare, som alltid för dig stå, och höra din visdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Lofvad vare Herren din Gud, som till dig lust haft hafver, så att han dig på Israels stol satt hafver; derföre, att Herren älskar Israel i evig tid, och hafver satt dig till Konung, att du rätt och redelighet göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Och hon gaf Konungenom hundrade och tjugu centener guld, och ganska mycket speceri, och ädla stenar. Der kom icke sedan så mycket speceri, såsom Drottningen af rika Arabien Konung Salomo gaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Dertill de Hirams skepp, som guld förde af Ophir, förde också ganska mycket hebenträ, och ädla stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Och Konungen lät göra af hebenträ pelare i Herrans hus, och i Konungshuset, och harpor och psaltare för sångare. Der kom icke sedan så mycket hebenträ, vardt ej heller sedt, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Och Konung Salomo gaf Drottningene af rika Arabien allt det hon begärade och beddes, förutan det han gaf henne af sig sjelf. Och hon vände om, och drog med sina tjenare i sitt land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Men det guld, som Salomo inkom årliga, var till vigt sexhundrad sex och sextio centener;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Förutan det af krämare och köpmän, och af apothekare, och ifrå de nästa Konungar, och ifrå de yppersta i landet kom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Och Konung Salomo lät göra tuhundrad spetsar af bästa guld; sexhundrad stycke guld lät han till hvar spets;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Och trehundrad sköldar, af bästa guld; ju tre pund guld till hvar sköld. Och Konungen lade dem uti det huset af Libanons skog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Och Konungen gjorde en stor stol af elphenben, och bedrog honom med ädlasta guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Och stolen hade sex trappor; och hufvudet af stolen var rundt baktill, och voro stolpar på båda sidor vid sätet, och tu lejon stodo vid stolparna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Och tolf lejon stodo på de sex trappor på båda sidor. Sådant är icke gjordt i något Konungarike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'All Konung Salomos dryckekar voro af guld; och käril uti huset af Libanons skog voro också af klart guld; förty silfver aktade man intet i Salomos tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Ty Konungens skepp, som till hafs foro med Hirams skepp, kommo en gång i hvar tre år, och förde guld, silfver, elphenben, apor och påfoglar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Alltså vardt Konung Salomo större med rikedomar och visdom, än alle Konungar på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Och all verlden begärade se Salomo, att de måtte höra den vishet, som Gud honom i hans hjerta gifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Och alle båro honom skänker, silfver och gyldene tyg, kläder och harnesk, örter, hästar, mulor, hvart år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Och Salomo drog tillhopa vagnar och resenärar, så att han hade tusende och fyrahundrad vagnar, och tolftusend resenärar; och han lät dem uti vagnsstäderna, och när Konungenom i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Och Konungen gjorde, att silfver i Jerusalem var så mycket som stenar, och cederträ så mycket som mulbärträ i dalarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Och man förde hästar utur Egypten till Salomo, och allahanda varor, och Konungens köpmän köpte samma varor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Och förde dem utur Egypten; hvar vagn för sexhundrad silfpenningar, och hvar häst för hundrade och femtio. Alltså förde man dem ock till alla de Hetheers Konungar, och till de Konungar i Syrien, genom deras hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Men Konung Salomo älskade många utländska qvinnor, Pharaos dotter, och Moabitiskor, Ammonitiskor, Edoinitiskor, Zidonitiskor och Hetheerskor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Af sådant folk, der Herren Israels barnom om sagt hade: Går icke till dem, och låter dem icke komma till eder; de varda förvisso bevekande edor hjerta efter sina gudar. Till dessa gaf sig Salomo, till att älska dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Och han hade sjuhundrad hustrur, Förstinnor, och trehundrad frillor; och hans hustrur bevekte hans hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Och då han nu gammal var, bevekte hans hustrur hans hjerta efter främmande gudar, så att hans hjerta icke var fulleliga med Herranom hans Gud, såsom hans faders Davids hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Alltså vandrade Salomo efter Astoreth, deras gud af Zidon, och Milcom, de Ammoniters styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Och Salomo gjorde det ondt var för Herranom, och följde icke Herran alldeles, såsom hans fader David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Då byggde Salomo en höjd till Chemos, de Moabiters styggelse, på berget som för Jerusalem ligger; och till Molech, de Ammoniters styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Alltså gjorde Salomo allom sinom utländskom hustrum, de der för sina gudar rökte och offrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Och Herren vardt vred på Salomo, att hans hjerta ifrå Herranom Israels Gud afvändt var, den honom två gånger synts hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'Och honom härom budit hade, att han icke skulle vandra efter andra gudar; och hade dock icke hållit det honom Herren budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Derföre sade Herren till Salomo: Efter sådant är skedt med dig, och du hafver mitt förbund och min bud icke hållit, som jag dig budit hafver, så vill jag ock, rifva riket ifrå dig, och gifva det dinom tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Dock i din tid vill jag icke göra det, för dins faders Davids skull; utan af dins sons hand vill jag rifva det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Dock vill jag icke allt riket afrifva; ena slägt vill jag gifva dinom son, för min tjenares Davids skull, och för Jerusalems skull, det jag utvalt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Och Herren uppväckte Salomo en fienda, Hadad den Edomeen, af Konungsligo säd, hvilken var i Edom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Ty då David var i Edom, och Joab den härhöfvitsmannen drog upp till att begrafva de slagna, slog han allt det mankön var i Edom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Förty Joab blef der sex månader, och hele Israel, intilldess han utrotade allt det mankön var i Edom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Då flydde Hadad, och med honom någre män Edomeer af hans faders tjenare, så att de kommo uti Egypten; men Hadad var en ung dräng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Och de stodo upp ifrån Midian, och kommo till Paran, och togo män med sig utaf Paran, och kommo uti Egypten titt Pharao, Konungen i Egypten. Han gaf honom ett hus, och förenämnd spis, och fick honom ett land in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Och Hadad fann stora nåd för Pharao, så att han ock gaf honom sina hustrus, Drottningenes Tahpenes syster, till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Och Tahpenes syster födde honom Genubath sin son; Och Tahpenes födde honom upp i Pharaos hus; så att Genubath var i Pharaos huse ibland Pharaos barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Då nu Hadad hörde uti Egypten, att David afsomnad var med sina fäder, och att Joab härhöfvitsmannen var död, sade han till Pharao: Låt mig draga i mitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Pharao sade till honom: Hvad fattas dig när mig, att du vill draga till ditt land? Han sade: Intet; utan låt mig fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Än uppväckte honom Gud en fienda, Reson, ElJada son, hvilken ifrå sin herra HadadEser, Konungen i Zoba, flydd var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Och församlade emot honom män, och vardt en höfvitsman för krigsknektar, den tid David slog dem ihjäl; och drogo till Damascon, och bodde der, och voro rådande i Damascon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Och han var Israels fiende, så länge Salomo lefde. Det är den skadan, som Hadad led; derföre hade han en vämjelse emot Israel, och blef rådandes i Syrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Dertill Jerobeam, Nebats son, en Ephrateer af Zareda, Salomos tjenare; och hans moder het Zeruga, en enka; hof också handena upp emot Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Och detta är saken, hvarföre han upphof handena emot Konungen: då Salomo byggde Millo, slöt han igen ett gap på sins faders Davids stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Och Jerobeam var en stridsam man; och då Salomo såg att mannen var snäll, satte han honom öfver alla Josephs hus utskylder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Men det begaf sig på den tiden, att Jerobeam gick utaf Jerusalem, och Propheten Ahia af Silo fann honom på vägenom; och han hade en ny mantel uppå; och de voro både allena på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Och Ahia fattade den nya mantelen, som han på hade, och ref honom sönder i tolf stycker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Och sade till Jerobeam: Tag tio stycker till dig; förty så säger Herren Israels Gud: Si, jag skall rifva riket utu Salomos hand, och gifva dig tio slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'En slägt skall han hafva för min tjenares Davids skull, och för staden Jerusalems skull, den jag utvalt hafver utur alla Israels slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Derföre att de hafva öfvergifvit mig, och tillbedit Astoreth, de Zidoniers gud, Chemos, de Moabiters gud, och Milcom, Ammons barnas gud, och icke vandrat i mina vägar, så att de måtte gjort hvad mig behagade, min bud och rätter, såsom David hans fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Jag vill ock icke taga hela riket utu hans hand; utan jag vill göra honom till en Första i hans lifstid, för Davids min tjenares skull, den jag utvalt hafver, den min bud och rätter hållit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Utu hans sons hand vill jag taga riket, och vill gifva dig tio slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Och hans son ena slägt, på det min tjenare David ju allstädes hafver ena lykto för mig uti den staden Jerusalem, den jag mig utvalt hafver, att jag mitt Namn der sätta skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Så vill jag nu taga dig, att du skall råda öfver allt det ditt hjerta begärar; och skall vara Konung öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Om du nu vill höra allt det jag dig bjudandes varder, och vandra i mina vägar, och göra hvad mig behagar, så att du håller mina rätter och bud, såsom min tjenare David gjort hafver, så vill jag vara med dig, och bygga dig ett beständigt hus, såsom jag David byggt hafver, och vill gifva dig Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Och vill dermed förnedra Davids säd; dock icke till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Men Salomo for efter att dräpa Jerobeam. Då stod Jerobeam upp, och flydde uti Egypten till Sisak, Konungen i Egypten, och blef i Egypten, tilldess Salomo blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Hvad mer af Salomo sägandes är, och allt det han gjort hafver, och hans visdom, det är skrifvet i Chrönicon om Salomo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Men tiden, som Salomo var Konung i Jerusalem, öfver hela Israel, var fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Och Salomo afsomnade med sina fäder, och vardt begrafven uti sins faders Davids stad; och hans son Rehabeam vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Och Rehabeam drog till Sichem; förty hela Israel var kommen till Sichem, till att göra honom till Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Och då Jerobeam, Nebats son, det hörde, der han ännu i Egypten var, dit han för Konung Salomo flydd var, kom han igen utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Och de sände bort, och läto kalla honom. Och Jerobeam samt med hela Israels menighet kommo, och talade med Rehabeam, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Din fader hafver gjort vårt ok för svårt; så gör nu du den hårda tjensten, och det svåra oket lättare, det han oss pålagt hafver, så vilje vi vara dig underdånige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Men han sade till dem: Går edra färde intill tredje dagen, och kommer så till mig igen. Och folket gick sina färde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Och Konung Rehabeam höll råd med de äldsta, som för hans fader Salomo stodo, då han lefde, och sade: Huru råden I, att vi måge gifva desso folkena svar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'De sade till honom: Om du i denna dag gör desso folkena en tjenst, och är dem till vilja, och hörer dem, och gifver dem god ord, så blifva de dig underdånige så länge du lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Men han öfvergaf de äldstas råd, som de honom gifvit hade; och höll ett råd med de unga, som med honom uppväxte voro, och för honom stodo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Och han sade till dem: Hvad råden I, det vi desso folkena svara skole, som till mig sagt hafva: Gör det oket lättare, som din fader uppå oss lagt hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Och de unge, som med honom uppväxte voro, sade till honom: Till folket, som till dig säger: Din fader hafver gjort vårt ok för svart, gör du oss det lättare; skall du säga: Mitt minsta finger skall tjockare vara än mins faders länder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Min fader hafver lagt på eder ett svårt ok; men jag skall ännu föröka det öfver eder. Min fader hafver tuktat eder med gisslar; jag skall tukta eder med scorpioner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Alltså kom Jerobeam med allo folkena till Rehabeam på tredje dagen, såsom Konungen talat hade, och sagt: Kommer igen till mig på tredje dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Och Konungen gaf folkena ett hårdt svar, och öfvergaf det råd, som de äldste honom gifvit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Och talade med dem efter de ungas råd, och sade: Min fader hafver gjort edart ok svårt; men jag vill ännu mer föröka det öfver eder. Min fader hafver tuktat eder med gisslar; men jag skall tukta eder med scorpioner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Alltså hörde Konungen intet folket; ty Herren vände det så, på det han skulle stadfästa sitt ord, som Herren genom Ahia af Silo sagt hade till Jerobeam, Nebats son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Då nu hele Israel såg, att Konungen intet ville höra dem, gaf folket Konungenom ett svar, och sade: Hvad del hafve vi i David, eller arf i Isai son? Israel, gack i dina hyddor; så se nu du till ditt hus, David. Alltså gick Israel i sina hyddor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Så att Rehabeam rådde allenast öfver de Israels barn, som bodde i Juda städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Och då Konung Rehabeam sände åstad Adoram räntomästaren, kastade hele Israel honom ihjäl med stenar; men Konungen Rehabeam steg med hast på en vagn, och flydde till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Alltså föll Israel ifrå Davids hus, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Då nu hele Israel hörde, att Jerobeam var igenkommen, sände de bort, och läto kalla honom till alla menighetena, och gjorde honom till Konung öfver hela Israel; och ingen följde Davids hus, utan Juda slägt allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Och då Rehabeam kom till Jerusalem, församlade han hela Juda hus, och BenJamins slägt, hundrade och åttatio tusend unga stridsamma män, till att strida emot Israels hus, och draga riket igen till Rehabeam, Salomos son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Men Guds ord kom till den Guds mannen Semaja, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Tala till Rehabeam, Salomos son, Juda Konung, och till hela Juda hus, och BenJamin, och till det andra folket, och säg:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Detta säger Herren: I skolen icke draga upp, och strida emot edra bröder Israels barn; hvar och en gånge åter hem; ty detta är skedt af mig. Och de lydde Herrans ord, och vände om, och gingo sin väg, såsom Herren sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Men Jerobeam byggde Sichem på Ephraims berg, och bodde deruti, och drog dädan ut, och byggde Pnuel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Men Jerobeam tänkte i sitt hjerta: Nu varder riket fallandes till Davids hus igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Om detta folk skall gå ditupp, till att offra i Herrans hus i Jerusalem, och detta folkets hjerta varder sig vändandes till deras herra Rehabeam, Juda Konung, och slå mig ihjäl, och falla igen till Rehabeam, Juda Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Och Konungen höll ett råd, och gjorde två gyldene kalfvar, och sade till dem: Det är eder för tungt gå upp till Jerusalem; si, der är din gud, Israel, som dig utur Egypti land fört hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Och satte endera i BethEl, och den andra i Dan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Och det vardt till synd; ty folket gick bort för dem ena, allt intill Dan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Han gjorde också ett höjdars hus, och gjorde Prester utaf de ringesta i folket, de icke af Levi barnom voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Och han gjorde en högtid, på femtonde dagen i åttonde månadenom, såsom den högtiden i Juda, och offrade på altarena. Så gjorde han i BethEl, att man offrade kalfvomen, som han gjort hade; och skickade i BethEl Prester till höjderna, som han gjort hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Och offrade på altaret, som han gjort hade i BethEl, på femtonde dagen i åttonde månadenom, hvilken han utu sitt hjerta upptänkt hade; och gjorde Israels barnom högtider, och offrade på altaret, det man röka skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Och si, en Guds man kom af Juda, genom Herrans ord, till BethEl. Och Jerobeam stod vid altaret till att röka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Och han ropade emot altaret genom Herrans ord, och sade: Altare, altare, så säger Herren: Si, Davids huse skall varda född en son, benämnd Josia, han skall på dig offra höjdernas Prester, som på dig röka, och uppbränna menniskoben på dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Och han gaf på den dagen ett tecken, och sade: Detta är tecknet, att Herren detta talat hafver: si, altaret skall remna, och askan, som derpå är, skall förspillas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Då nu Konung Jerobeam hörde ordet af den Guds mannen, som emot altaret i BethEl ropade, räckte han ut sin hand vid altaret, och sade: Tager fatt på honom. Och hans hand förtorkades, som han emot honom uträckt hade; och han kunde icke draga henne igen till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Och altaret remnade, och askan vardt förspilld af altaret, efter tecknet, som Guds mannen genom Herrans ord gifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Och Konungen svarade och sade till den Guds mannen: Bed Herrans dins Guds ansigte, och bed för mig, att min hand kommer till mig igen. Då bad Guds mannen Herrans ansigte, och Konungens hand kom till honom igen, och vardt såsom hon tillförene var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Och Konungen talade med Guds mannenom: Kom hem med mig, och vederqvick dig; jag vill gifva dig en skänk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Men Guds mannen sade till Konungen: Om du än gåfve mig halft ditt hus, så ginge jag dock icke med dig; ty jag vill i detta rum intet bröd äta, eller vatten dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Ty så är mig genom Herrans ord budet och sagdt: Du skall intet bröd äta, och intet vatten dricka, och icke komma den samma vägen tillbaka igen, som du gångit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Och han gick sina färde en annan väg, och kom icke den vägen tillbaka igen, som han till BethEl kommen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Men i BethEl bodde en gammal Prophet; till honom kommo hans söner, och förtäljde honom all verk, som Guds mannen på den dagen gjort hade i BethEl, och de ord, som han till Konungen sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Och deras fader sade till dem: Hvilken vägen hafver han farit? Och hans söner viste honom vägen, som Guds mannen farit hade, den af Juda kommen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Men han sade till sina söner: Sadler mig åsnan. Och då de hade sadlat honom åsnan, red han deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Och drog efter Guds mannen, och fann honom sittandes under en ek, och sade till honom: Äst du den Guds mannen, som af Juda kommen äst? Han sade: Ja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Han sade till honom: Kom med mig hem, och ät bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Han sade: Jag kan icke vända om med dig, och komma med dig; jag vill ej heller bröd äta, eller vatten dricka med dig, på detta rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Ty med mig är taladt vordet genom Herrans ord: Du skall der hvarken bröd äta, eller vatten dricka; du skall icke gå den vägen tillbaka igen, som du ditgången äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Han sade till honom: Jag är ock en Prophet såsom du, och en Ängel hafver talat med mig genom Herrans ord, och sagt: Haf honom hem med dig igen, att han må bröd äta, och vatten dricka. Men han lög för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Och han förde honom tillbaka igen, så att han åt bröd, och drack vatten i hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Och vid de såto till bords, kom Herrans ord till Propheten, som honom hade tillbaka haft;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Och han ropade till den Gudsmannen, som af Juda kommen var, och sade: Detta säger Herren: Derföre, att du hafver Herrans mun ohörig varit, och hafver icke hållit det bud, som Herren din Gud dig budit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Och hafver omvändt, ätit bröd, och vatten druckit, på det rum der han dig om sade: Du skall der hvarken bröd äta, eller vatten dricka; skall din lekamen icke komma uti dina faders graf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Och sedan han bröd ätit, och druckit hade, sadlade man åsnan åt den Propheten, som han igen haft hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Och då han bort drog, fann honom ett lejon på vägenom, och drap honom; och hans kropp låg kastad på vägen; och åsnan stod jemte honom, och lejonet stod när kroppenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Och då der gick folk framom, sågo de kroppen på vägen kastad, och lejonet ståndandes när kroppen; och de kommo och sade det i stadenom, der den gamle Propheten uti bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Då Propheten det hörde, som honom igenhaft hade, sade han: Det är den Guds mannen, som Herrans mun ohörig var; derföre hafver Herren gifvit honom lejonena; det hafver sönderkrossat honom och dräpit, efter det ord som Herren honom sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Och sade till sina söner: Sadler mig åsnan. Och de sadlade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Då drog han dit, och fann hans kropp kastad på vägen, och åsnan och lejonet ståndande der jemte kroppen; lejonet hade intet ätit af kroppen, och ej heller rifvit åsnan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Då tog Propheten den Guds mansens kropp upp, och lade honom på åsnan, och förde honom tillbaka igen; och kom uti den gamla Prophetens stad, att de måtte begråta honom, och begrafvan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Och han lade kroppen uti sina graf, och de begreto honom: Ack! min broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Och då de hade begrafvit honom, sade han till sina söner: När jag dör, så begrafver mig i de grafvene, som den Guds mannen uti begrafven är, och lägger min ben jemte vid hans ben;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Förty det varder skeendes, som han emot altaret i BethEl genom Herrans ord ropat hafver, och emot alla höjders hus, som i Samarie städer äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Men sedan detta skedt var, vände Jerobeam sig intet ifrå sin onda väg; utan förvände sig, och gjorde Prester till höjderna, utaf de ringesta i folket; hvilken honom täcktes, honom fyllde han handena, och han vardt Prest till höjderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Och detta vardt Jerobeams huse till synd, att han skulle förderfvas, och förgöras af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'På den tiden var Abia, Jerobeams son, krank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Och Jerobeam sade till sina hustru: Statt upp, och förkläd dig, så att ingen kan märka, att du äst Jerobeams hustru, och gack bort till Silo; si, der är den Propheten Ahia, den mig sade, att jag skulle varda Konung öfver detta folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Och tag med dig tio bröd, och kakor, och ett käril med hannog, och gack till honom, att han må säga dig, huru med piltenom gå skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Och Jerobeams hustru gjorde så, och stod upp, och gick bort till Silo, och kom i Ahia hus; men Ahia kunde intet se; ty hans ögon voro mörk vorden för ålders skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Men Herren sade till Ahia: Si, Jerobeams hustru kommer, att hon skall fråga ett ärende af dig om sin son, ty han är krank: så tala nu du med henne så och så. Då hon nu inkom, höll hon sig främmande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Som nu Ahia hörde dönen af hennes fötter, vid hon ingick, sade han: Kom hitin, du Jerobeams hustru; hvi håller du dig så främmande? Jag är sänder till dig ett hårdt bådskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Gack bort, och säg Jerobeam: Så säger Herren Israels Gud: Jag hafver upphöjt dig utu folkena, och satt dig till en Första öfver mitt folk Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'Och hafver rifvit riket ifrå Davids hus, och gifvit det dig; men du hafver intet varit såsom min tjenare David, den min bud höll, och vandrade efter mig med allo hjerta, så att han gjorde hvad mig ljuft var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Och du hafver illa gjort, öfver alla de som för dig varit hafva; du hafver gångit bort, och gjort dig andra gudar, och gjuten beläte, att du skulle reta mig till vrede; och hafver kastat mig bakom din rygg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Och si, jag skall låta komma olycko öfver Jerobeams hus, och förgöra af Jerobeam ock den uppå väggena pissar; den innelyckta, och den igenlefda i Israel; och skall utsopa Jerobeams hus efterkomman de, såsom man träck utsopar, tilldess det blifver allt ute med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Den som af Jerobeam dör i stadenom, honom skola hundarna äta; men den som dör på markene, honom skola himmelens foglar äta; ty Herren hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Så statt nu upp, och gack hem; och då din fot träder in i staden, skall pilten blifva död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Och hela Israel skall begråta honom, och skola begrafvan; ty denne allena af Jerobeam skall till grafva komma; förty något godt är funnet i honom för Herranom Israels Gud, i Jerobeams hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Och Herren skall uppväcka en Konung öfver Israel, han skall utrota Jerobeams hus på den dagen; och hvad är det nu allaredo sker?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Och Herren skall slå Israel, såsom rören böjas i vattnena; och skall utrycka Israel utu desso goda landena, som han deras fader gifvit hafver, och skall förströ dem bort öfver älfvena; derföre att de hafva gjort sig lundar till att förtörna Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Och skall öfvergifva Israel, för Jerobeams synds skull, hvilken syndat hafver och kommit Israel till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Och Jerobeams hustru stod upp, gick, och kom till Thirza; och då hon kom till tröskelen åt huset, blef pilten död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Och de begrofvo honom, och hele Israel begreto honom, efter Herrans ord, som han genom sin tjenare Propheten Ahia talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Hvad mer om Jerobeam sägandes är, huru han stridde och regerade, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Tiden, som Jerobeam regerade, var tu och tjugu år; och han af somnade med sina fäder. Och hans son Nadab vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Så var nu Rehabeam, Salomos son, Konung i Juda; ett och fyratio år gammal var Rehabeam, då han vardt Konung; och regerade i sjutton år i Jerusalem, i dem stadenom, som Herren utvalt hade utur alla Israels slägter, att han skulle sätta der sitt Namn uti. Hans moder het Naama, en Ammonitiska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Och Juda gjorde det ondt var för Herranom, och rette honom mera, än allt det deras fäder gjort hade, med deras synder som de gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Ty de byggde sig också höjder, stodar och lundar, på alla höga backar, och under all grön trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Och voro desslikes roffare i landena; och de gjorde all Hedningarnas styggelse, som Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Men i femte Konung Rehabeams åre drog Sisak, Konungen i Egypten, uppemot Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Och tog ut de håfvor utu Herrans hus, och utu Konungshuset, och allt det som der tagas kunde; och tog alla gyldene sköldar, som Salomo hade göra låtit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'I hvilkas stad Konung Rehabeam lät göra kopparsköldar, och befallde dem under de öfversta drabanternas hand, som dörrena vaktade för Konungshuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Och så ofta Konungen gick in uti Herrans hus, båro drabanterna dem; och hade dem åter uti drabantakammaren igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Hvad nu mer af Rehabeam sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Men emellan Rehabeam och Jerobeam var örlig, så länge de lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Och Rehabeam afsomnade med sina fäder, och vardt begrafven med sina fäder uti Davids stad; och hans moder het Naama, en Ammonitiska. Och hans son Abiam vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'På adertonde årena Konung Jerobeams, Nebats sons, vardt Abiam Konung i Juda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Och regerade tre år i Jerusalem. Hans moder het Maacha, Abisaloms dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Och han vandrade i alla sins faders synder, som han för honom gjort hade; och hans hjerta var icke rättsinnigt till Herran hans Gud, såsom hans faders Davids hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Men för Davids skull gaf Herren hans Gud honom ena lykto i Jerusalem, så att han uppväckte hans son efter honom, och behöll honom i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Derföre att David gjort hade det Herranom ljuft var, och var icke viken ifrån allt det han honom böd, så länge han lefde; förutan i den handelen med Uria den Hetheen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Men emellan Rehabeam och Jerobeam var örlig, så länge han lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Hvad nu mer af Abiam sägandes är, och allt det han gjort hafver; si, det är skrifvet uti Juda Konungars Chrönico. Och det var örlig emellan Abiam och Jerobeam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Och Abiam afsomnade med sina fäder; och de begrofvo honom uti Davids stad. Och Asa hans son vardt Konung uti hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Uti tjugonde årena Konungs Jerobeams öfver Israel, vardt Asa Konung i Juda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Och regerade ett och fyratio år i Jerusalem. Hans moder het Maacha, Abisaloms dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Och Asa gjorde det Herranom behageligit var, såsom hans fader David;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Och dref de roffare utu landet, och borttog alla de afgudar, som hans fäder gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Dertill satte han sina moder Maacha af ämbetet, för det hon Miplezeth gjort hade i lundenom; och Asa utrotade hennes Miplezeth, och uppbrände honom vid den bäcken Kidron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Men de höjder lade de icke bort; dock var Asa hjerta rättsinnigt till Herran, så länge han lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Och det silfver och guld, och tyg, som hans fader helgat hade, och hvad som helgadt var till Herrans hus, lät han komma derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Och emellan Asa och Baesa, Israels Konung, var örlig, så länge de lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Men Baesa, Israels Konung, drog upp emot Juda, och byggde Rama, att ingen skulle draga ut och in af Asa part, Konungens i Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Då tog Asa allt silfver och guld, som qvart var i Herrans hus skatt, och i Konungshusets skatt, och fick det i sina tjenares händer; och sände dem till Benhadad, Tabrimmons son, Hesions sons, Konungen i Syrien, som bodde i Damascon, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Ett förbund är emellan, mig och dig, och emellan min fader och din, fader; derföre skickar jag dig en, skänk, silfver och guld, att du ville låta det förbundet fara, som du hafver med Baesa, Israels Konung, att han må draga ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Benhadad hörde Konung Asa, och sände sina höfvitsmän emot Israels städer, och slog Ijon och Dan, och AbelBethMaacha, hela Cinneroth med hela Naphthali land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Då Baesa det hörde, vände han igen bygga Rama, och drog till Thirza igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Men Konung Asa lät båda öfver hela Juda: Ingen ursake sig; och de togo bort sten och trä af Rama, der Baesa med byggt hade. Och Konung Asa byggde dermed Geba BenJamin, och Mizpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Hvad nu mer af Asa sägandes är, och all hans magt, och allt det han gjorde, och de städer som han byggde, si, det är skrifvet uti Juda Konungars Chrönico; undantagno, att han på sinom ålder var krank i sina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Och Asa afsomnade med sina fader, och vardt begrafven med sina fader uti Davids sins faders stad. Och Josaphat hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Men Nadab, Jerobeams son, vardt Konung öfver Israel, uti de andra årena Asa, Juda Konungs; och rådde öfver Israel i tu år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Och gjorde det för Herranom ondt var, och vandrade i sins faders vägar, och i hans synder, der han med kom Israel till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Men Baesa, Ahia son, utaf Isaschars hus, gjorde ett förbund emot honom, och slog honom i Gibbethon, som var de Philisteers; ty Nadab och hele Israel belade Gibbethon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Så drap Baesa honom, uti tredje årena Asa, Juda Konungs; och vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Som han nu Konung var, slog han hela Jerobeams hus, och lät intet qvart blifva, det anda hade, af Jerobeam, tilldess han utrotade honom, efter Herrans ord, som han talat hade genom sin tjenare Ahia af Silo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'För Jerobeams synds skull, som han gjorde, och dermed han kom Israel till att synda; och med det retandet, dermed han rette Herran Israels Gud till vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Hvad nu mer af Nadab sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Och emellan Asa och Baesa, Israels Konung, var örlig, så länge de lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Uti tredje årena Asa, Juda Konungs, vardt Baesa, Ahia son, Konung öfver hela Israel i Thirza, fyra och tjugu år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Och gjorde det ondt var för Herranom, och vandrade i Jerobeams väg, och i hans synd, dermed han hade kommit Israel till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Så kom Herrans ord till Jehu, Hanani son, emot Baesa, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Derföre, att jag dig utu stoftet upphäfvit hafver, och gjort dig till en Första öfver mitt folk Israel, och du vandrar i Jerobeams väg, och kommer mitt folk Israel till att synda, så att du mig förtörnar genom deras synder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Si, så vill jag borttaga Baesa efterkommande, och hans hus efterkommande, och vill sätta ditt hus såsom Jerobeams hus, Nebats sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Den af Baesa dör i staden, honom skola hundar uppäta; och den af honom dör på markene, honom skola himmelens foglar uppäta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Hvad nu mer om Baesa sägandes är, och hvad han gjort hafver, och hans magt, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Och Baesa afsomnade med sina fäder, och vardt begrafven i Thirza; och hans son Ela vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Och Herrans ord kom genom Propheten Jehu, Hanani son, öfver Baesa, och öfver hans hus, och emot allt det onda, som han för Herranom gjort hade, till att förtörna honom genom sina händers verk, att det skulle varda såsom Jerobeams hus, och derföre, att han denna slagit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Uti sjette och tjugonde årena Asa, Juda Konungs, vardt Ela, Baesa son, Konung öfver Israel i Thirza, i tu år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Men hans tjenare Simri, en öfverste öfver hälften af vagnarna, gjorde ett förbund emot honom; men han var i Thirza, drack och var drucken i Arza hus, fogdans i Thirza.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Och Simri kom derin, och slog honom ihjäl, uti sjunde och tjugonde årena Asa, Juda Konungs; och blef Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Och då han var Konung, och satt på sin stol, slog han hela Baesa hus, och lät intet qvart blifva, icke den som på väggena pissar; dertill hans fränder och vänner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Alltså förgjorde Simri hela Baesa hus, efter Herrans ord, som han om Baesa talat hade, genom den Propheten Jehu;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'För alla Baesa och hans sons Ela synders skull, som de gjort hade, och kommo Israel till att synda, och förtörnade Herran Israels Gud i deras afguderi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Hvad nu mer af Ela sägandes är, och allt det han gjorde, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Uti sjunde och tjugonde årena Asa, Juda Konungs, vardt Simri Konung i sju dagar i Thirza; ty folket låg för Gibbethon de Philisteers.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Då nu folket i lägret hörde sägas, att Simri hade gjort ett förbund, och slagit Konungen ihjäl, gjorde hele Israel på samma dagen Amri, härhöfvitsmannen, till Konung öfver Israel i lägrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Och Amri drog upp, och hele Israel med honom, ifrå Gibbethon, och belade Thirza.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Då nu Simri såg, att staden skulle varda vunnen, gick han uti palatset i Konungshusena, och brände sig upp med Konungshusena, och blef död;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'För sina synders skull, som han gjort hade, så att han hade gjort det ondt var för Herranom, och vandrade uti Jerobeams väg, och i hans synd, som han gjorde, och kom Israel till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Hvad nu mer af Simri sägandes är, och huru han gjorde ett förbund, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'På den tiden söndrade sig folket Israel i två delar: en hälften höll sig intill Thibni, Ginaths son, och gjorde honom till Konung; den andra hälften höll sig intill Amri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Men det folk, som höll sig intill Amri, vardt starkare än det folk, som höll sig intill Thibni, Ginaths son. Och Thibni blef död, och så blef Amri Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Uti första och tretionde årena Asa, Juda Konungs, vardt Amri Konung öfver Israel i tolf år; och regerade i Thirza i sex år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Han köpte Samarie berg af Semer, för två centener silfver; och byggde uppå bergena, och kallade staden, som han byggde, efter Semers namn, som herre var på Samarie berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Och Amri gjorde det ondt var för Herranom, och var argare än alla de för honom varit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Och vandrade i alla Jerobeams vägar, Nebats sons, och i hans synder, dermed han kom Israel till att synda, så att de förtörnade Herran Israels Gud uti deras afguderi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Hvad nu mer af Amri sägandes är, och allt det han gjort hafver, och om hans magt som han bedref, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Och Amri afsomnade med sina fäder, och vardt begrafven i Samarien; och Achab hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Uti åttonde och tretionde årena Asa, Juda Konungs, vardt Achab, Amri son, Konung öfver Israel; och regerade öfver Israel i Samarien tu och tjugu år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Och gjorde det ondt var för Herranom, öfver alla dem som för honom varit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Och var honom icke nog, att han vandrade i Jerobeams, Nebats sons, synder; utan tog dertill Isebel, EthBaals dotter, Konungens i Zidon, till hustru, och gick bort, och tjente Baal, och tillbad honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Och uppsatte Baal ett altare uti Baals hus, det han honom byggde i Samarien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Och gjorde en lund; så att Achab mer gjorde till att förtörna Herran Israels Gud, än alle Israels Konungar, som för honom varit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'På samma tid byggde Hiel af BethEl Jericho. Det kostade honom hans första son Abiram, då han grundvalen lade; och hans yngsta son Segub, då han satte portarna derföre, efter Herrans ord, som han sagt hade genom Josua, Nuns son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Och Elia den Thisbiten, utaf de Gileads inbyggare, sade till Achab: Så sant som Herren Israels Gud lefver, för hvilkom jag står, det skall i dessa år hvarken dagg eller regn komma, utan jag säger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Och Herrans ord kom till honom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Gack bort hädan, och vänd dig österut, och fördölj dig vid den bäcken Cherith, som löper för Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Och du skall dricka af bäckenom; och jag hafver budit korpom, att de skola der föda dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Han gick dit, och gjorde efter Herrans ord, och gick bort, och satte sig vid bäcken Cherith, som löper för Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Och korpar förde honom bröd och kött, om morgon och om afton; och han drack utaf bäcken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Och det skedde efter några dagar, att bäcken förtorkades; ty intet regn vardt i landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Då kom Herrans ord till honom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Statt upp, och gack till Zarpath, som vid Zidon ligger, och blif der; ty jag hafver der befallt ene enko, att hon skall föda dig,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Och han stod upp och gick till Zarpath. Och då han kom till stadsporten, si, då var enkan der, och hemtade ved. Och han talade till henne, och sade: Hemta mig litet vatten i kärilet, att jag må dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Då hon nu åstad gick till att hemtat, ropade han efter henne, och sade: Bär mig ock en beta bröd med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Hon sade: Så sant som Herren din Gud lefver, jag hafver intet bröd, utan en hand full af mjöl uti skäppone, och litet oljo i krukone; och si, jag hafver hemtat ett trä eller tu; och går bort att reda det till, mig och minom son, att vi måge äta och dö;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elia sade till henne: Frukta dig intet; gack åstad, och gör såsom du sagt hafver; dock gör mig först ett litet bröd deraf, och bär mig det hitut; men dig och dinom son skall du ock så sedan göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Ty så säger Herren Israels Gud, att mjölet i skäppone skall icke varda uttärdt, och oljan i krukone skall icke förminskas, intill den dag Herren låter regna på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Hon gick åstad, och gjorde såsom Elia sagt hade. Och han åt; och hon desslikes, och hennes hus, en tid lång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Och vardt mjölet icke uttärdt i skäppone; och icke heller förminskades oljan i krukone, efter Herrans ord, som han genom Elia sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Sedan detta skedt var, vardt qvinnones, hans värdinnos, son krank; och hans krankhet vardt så stark, att ingen ande var mer uti honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Och hon sade till Elia: Hvad hafver jag med dig göra, du Guds man? Du äst ingången till mig, att mina missgerningar skulle ihågkommas, och min son dräpas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Han sade till henne: Få mig din son hit. Och han tog honom utu hennes sköte, och gick upp i salen, der han vistades, och lade honom på sina säng;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Och ropade till Herran, och sade: Herre, min Gud, hafver du ock så illa gjort emot denna enkona, som jag gäster när, att du dräper hennes, son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Och han räckte sig ut öfver pilten i tre gånger, och ropade till Herran, och sade: Herre min Gud, låt denna piltens själ åter komma i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Och Herren hörde Elia röst; och piltens själ kom igen till honom, och han fick lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Och Elia tog pilten, och bar honom neder utaf salen i huset, och fick honom hans moder, och sade: Si der, din son, lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Och qvinnan sade till Elia: Nu förnimmer jag, att du äst en Guds man, och Herrans ord i dinom mun är visst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Efter en lång tid kom Herrans ord till Elia, i tredje årena, och sade: Gack bort, och te dig för Achab, att jag må låta regna på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Och Elia gick åstad, och tedde sig för Achab; men en ganska hård tid var i Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Och Achab kallade Obadja sin hofmästare. Och Obadja fruktade Herran storliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Förty då Isebel utrotade Herrans Propheter, tog Obadja hundrade Propheter, och gömde dem i kulor, femtio här, och femtio der; och försörjde dem med bröd och vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Så sade nu Achab till Obadja: Drag igenom landet till alla vattubrunnar och bäcker, att vi måtte finna gräs, och behålla hästar och mular, så att boskapen icke all förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Och de delade sig i landet, så att de drogo det igenom. Achab drog allena på en väg, och Obadja desslikes allena på den andra vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Då nu Obadja var på vägenom, si, då mötte honom Elia. Och som han kände honom, föll han uppå sitt anlete, och sade: Äst du icke min herre Elia?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Han sade: Ja; gack och säg dinom herra: Si, Elia är här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Han sade: Hvad hafver jag syndat, att du vill gifva din tjenare i Achabs händer, att han skall dräpa mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Så sant som Herren din Gud lefver, det är intet folk eller Konungarike, dit min herre icke sändt hafver till att söka dig, och när de hafva sagt: Han är icke här, hafver han tagit en ed af det riket och folket, att man icke hade funnit dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Och du säger nu: Gack och säg dinom herra: Si, Elia är här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'När jag nu ginge ifrå dig, så toge Herrans Ande dig bort, jag vet icke hvart; och jag komme då och underviste det Achab, och funne dig icke, så sloge han mig ihjäl; men jag din tjenare fruktar Herran af minom ungdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Är minom herra icke undervist, hvad jag gjort hafver, då Isebel drap Herrans Propheter? att jag gömde hundrade Herrans Propheter, femtio här, och femtio der, uti kulor; och försörjde dem med bröd och vatten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Och nu säger du: Gack bort, och säg dinom herra: Elia är här; att han må dräpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elia sade: Så sant som Herren Zebaoth lefver, för hvilkom jag står, i dag skall jag te mig för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Då gick Obadja emot Achab, och sade honom detta. Och Achab gick emot Elia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Och då Achab såg Elia, sade Achab till honom: Äst du den som förvillar Israel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Han sade: Jag förvillar icke Israel, utan du och dins faders hus, dermed att I Herrans bud öfvergifvit hafven, och vandren efter Baalim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Nu väl, så sänd nu bort, och församla mig hela Israel på Carmels berg; och fyrahundrad och femtio Baals Propheter, och de fyrahundrad lundarnas Propheter, som äta vid Isebels bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Alltså sände Achab bort ibland all Israels barn, och församlade Propheterna på Carmels berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Då gick Elia fram för allt folket, och sade: Huru länge halten I på båda sidor? Är Herren Gud, så vandrer efter honom; men är Baal det, så vandrer efter honom. Och folket svarade honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Då sade Elia till folket: Jag allena är qvar blifven, en Herrans Prophet; men Baals Propheter äro fyrahundrade och femtio män,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Så får oss nu två stutar, och låter dem utvälja en stuten och stycka honom, och lägga honom på ved; men låte ingen eld komma dertill; så vill jag taga den andra stuten, och lägga honom på ved, och ej heller låta der någon eld till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Så åkaller I edars guds namn, och jag vill åkalla Herrans Namn; hvilken Gud, som nu svarar med elden, han vare Gud. Och hela folket svarade och sade: Det är rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Och Elia sade till Baals Propheter: Utväljer eder en stuten, och görer I först; förty I ären månge; och åkaller edars guds namn, och låter ingen eld dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Och de togo stuten, som han fick dem, och redde till, och åkallade Baals namn, ifrå morgonen allt intill middag, och sade: Baal, hör oss. Men der var ingen röst eller svar. Och de sprungo om altaret, såsom deras seder var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Då nu middag var, bespottade dem Elia, och sade: Roper högt; ty han är en gud; han begrundar, eller hafver något beställa, eller är ute på markene, eller sofver tilläfventyrs, att han måtte vaka upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Och de ropade högt, och riste sig med knifvar, och med prener, efter deras sed, så att blodet gick der ut efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Då nu middagen förgången var, propheterade de, intilldess man skulle göra spisoffer; och der var dock ingen röst, eller svar, eller tillhörare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Då sade Elia till allt folket: Kommer hit till mig. Och då allt folket gick fram till honom, botade han Herrans altare, som nederslaget var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Och tog tolf stenar, efter talet på Jacobs barnas slägter, till hvilken Herrans ord talade, och sade: Du skall heta Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Och byggde af de stenar ett altare i Herrans Namn, och gjorde ena graf kringom altaret, tu kornmått vid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Och redde till veden, och styckade stuten, och lade honom på veden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Och sade: Hemter fyra sår fulla med vatten, och gjuter det på bränneoffret och uppå veden; och sade: Görer det än en tid. Och de gjorde det än en tid. Och han sade: Görer det än tredje reson. Och de gjorde det i tredje reson.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Och vattnet lopp om altaret, och grafven vardt också full med vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Och som tid var till att offra spisoffer, gick Propheten Elia fram, och sade: Herre, Abrahams Gud, Isaacs, och Israels, låt i denna dag kunnigt varda, att du äst Gud i Israel, och jag din tjenare, och att jag allt detta efter ditt ord gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Hör mig, Herre, hör mig, att detta folket må veta att du, Herre, äst Gud; att du sedan må omvända deras hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Då föll Herrans eld neder, och uppbrände bränneoffret, veden, stenar och jord, och uppslekte vattnet i grafvene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Då allt folket såg det; föll det på sitt ansigte, och sade: Herren är Gud, Herren är Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Men Elia sade till dem: Tager fatt på Baals Propheter, att icke en af dem undslipper. Och de togo fatt på dem; och Elia förde dem neder till den bäcken Kison, och drap dem der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Och Elia sade till Achab: Drag upp, ät och drick; förty det dånar, såsom det ville komma ett stort regn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Och då Achab drog upp till att äta och dricka, gick Elia upp på kullen af Carmel, och böjde sig neder till jordena, och satte sitt hufvud emellan sin knä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Och talade till sin dräng: Gack ditupp, och se ut till hafvet. Han gick upp, och såg ut, och sade: Der är intet. Han sade: Gack åter ditupp sju resor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Och i sjunde resone sade han: Si, der går ett litet moln upp utu hafvet såsom en mans hand. Han sade: Gack upp, och säg Achab: Spänn före din vagn, och far ned, att regnet icke hinner dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Och förr än man såg till, vardt himmelen svart af moln och väder; och ett stort regn kom. Men Achab for, och kom till Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Och Herrans hand kom öfver Elia, och han gjordade sina länder, och lopp för Achab, tilldess han kom till Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Och Achab sade till Isebel allt det Elia gjort hade; och huru han hade dräpit alla Baals Propheter med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Då sände Isebel ett båd till Elia, och lät säga honom: Gudarne göre mig det och det, om jag icke, i morgon vid denna tiden, gör dine själ såsom ene af dessas själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Då han det såg, stod han upp, och gick hvart han ville, och kom till BerSeba i Juda, och lät der sin dräng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Men han gick bort uti öknena ena dagsreso, och kom derin, och satte sig under ett enebärsträ, och bad att hans själ måtte dö, och sade: Det är nog. Så tag nu, Herre, mina själ; jag är icke bättre än mine fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Och han lade sig, och sof under enebärsträt. Och si, Ängelen tog uppå honom, och sade till honom: Statt upp, och ät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Och han såg sig om; och si, vid hans hufvud låg ett glödbakadt bröd, och en kanna med vatten. Och då han ätit och druckit hade, lade han sig åter till att sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Och Herrans Ängel kom till honom annan gången igen, och tog på honom, och sade: Statt upp, och ät; ty du hafver en stor väg för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Och han stod upp, och åt, och drack, och gick af den matens kraft fyratio dagar och fyratio nätter intill Guds berg Horeb;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Och kom der uti ena kulo, och blef der öfver nattena. Och si, Herrans ord kom till honom, och sade till honom: Hvad gör du här, Elia?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Han sade: Jag hafver haft nit om Herran Gud Zebaoth; förty Israels barn hafva öfvergifvit ditt förbund, och nederbrutit din altare, och dräpit dina Propheter med svärd; och jag är allena igenblifven, och de fara efter att de måga taga mig lifvet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Han sade: Gack härut, och stig upp på berget inför Herran. Och si, Herren gick der framom, och ett stort starkt väder, som bröt berg, och sönderbråkade hällar inför Herranom; men icke var Herren i vädrena. Efter vädret kom en jordbäfning; men icke var Herren i jordbäfningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Och efter jordbäfningen kom en eld; men icke var Herren i eldenom. Och efter elden kom ett ljud af ett sakta väder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Då Elia det hörde, skylde han sitt ansigte med sin mantel, och gick ut, och steg i dörrena af kulone; och si, då kom en röst till honom, och sade: Hvad hafver du här göra, Elia?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Han sade: Jag hafver haft nit om Herran Gud Zebaoth; förty Israels barn hafva öfvergifvit ditt förbund, nederbrutit din altare, dräpit dina Propheter med svärd; och jag är allena igenblifven, och de stå derefter, att de måga taga mig lifvet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Men Herren sade till honom: Gack din väg igen, genom öknena in i Damascon; och gack derin, och smörj Hasael till Konung öfver Syrien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Och Jehu, Nimsi son, till Konung öfver Israel; och Elisa, Saphats son, af AbelMehola, till en Prophet i din stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Och skall ske, att den som undslipper Hasaels svärd, honom skall Jehu dräpa; och den som undslipper Jehu svärd, honom skall Elisa dräpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Och jag skall låta igenblifva sjutusend i Israel, nämliga all knä som sig icke hafva böjt för Baal, och hvar och en mun som honom icke kysst hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Och han gick dädan, och fann Elisa, Saphats son, der han plöjde med tolf par oxar, och han var sjelf ibland de tolf; och Elia gick till honom, och kastade sin mantel öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Men han öfvergaf oxarna, och lopp efter Elia, och sade: Låt mig kyssa min fader, och mina moder, så vill jag följa dig efter. Han sade till honom: Gack, och kom igen; ty jag hafver något beställa med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Och han lopp åter ifrå honom, och tog ett par oxar, och offrade dem, och kokade köttet med träredskapen till oxarna, och gaf folket, att de åto; och stod upp, och följde Elia efter och tjente honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Och Benhadad, Konungen i Syrien, församlade alla sina magt, och voro två och tretio Konungar med honom, och hästar och vagnar; och drog upp, och belade Samarien, och stridde deremot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Och sände båd till Achab, Israels Konung, in uti staden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Och lät säga honom: Så säger Benhadad: Ditt silfver och ditt guld är mitt; och dina hustrur, och din bästa barn äro också min.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Israels Konung svarade, och sade: Min herre Konung, såsom du sagt hafver, jag är din, och allt det jag hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Och båden kommo igen, och sade: Så säger Benhadad: Efter jag hafver sändt till dig, och låtit säga: Ditt silfver och ditt guld, dina hustrur och din barn skall du få mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Så vill jag i morgon på denna tiden sända mina tjenare till dig, att de ransaka ditt hus, och dina underdånares hus; och hvad dig kärt är, skola de taga i deras händer, och bära bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Då kallade Israels Konung alla landsens äldsta, och sade: Märker och ser, hvilket ondt han företager; han sände till mig om mina hustrur och barn, silfver och guld, och jag hafver det intet nekat honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Då sade till honom alle de gamle, och allt folket: Du skall intet höra honom, eller samtyckat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Och han sade till Benhadads båd: Säger minom herra Konungenom: Allt det du böd dinom tjenare i förstone, vill jag göra; men detta kan jag icke göra. Och båden gingo sina färde, och sade sådant igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Då sände Benhadad till honom, och lät säga honom: Gudarna göre mig det och det, om stoftet i Samarien skall räcka till att allt folket under mig må taga der en hand full af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Men Konungen i Israel svarade och sade: Säger: Den som lägger harnesket uppå, skall icke så berömma sig, såsom den det aflagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Då Benhadad det hörde, och drack med Konungarna i tjällen, sade han till sina tjenare: Gör er redo; och de gjorde redo emot staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Och si, en Prophet gick fram till Achab, Israels Konung, och sade: Så säger Herren: Du hafver ju sett allan den stora hopen; si, jag vill i dag gifva honom i dina hand, att du veta skall att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Achab sade: Genom hvem? Han sade: Så säger Herren: Genom landsfogdarnas tjenare. Han sade: Ho skall begynna striden? Han sade: Du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Då räknade han landsfogdarnas tjenare, och de voro tuhundrad och två och tretio; och räknade efter dem hela folket af all Israels barn, sjutusend män;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Och drogo ut om middag. Men Benhadad drack, och var drucken i tjällen, med de två och tretio Konungar, som honom till hjelp komne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Och landsfogdarnas tjenare drogo först ut. Då sände Benhadad ut; och de bådade honom, och sade: Det draga män utu Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Han sade: Griper dem lefvande, ehvad de äro utdragne till frid eller strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Då landsfogdarnas tjenare voro utdragne, och hären efter dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Slog hvar och en den han öfverkom. Och de Syrer flydde, och Israel jagade efter dem; och Benhadad, Konungen i Syrien, undslapp med hästar och resenärar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Och Israels Konung drog ut, och slog hästar och vagnar, så att han gjorde en stor slagtning på de Syrer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Då gick en Prophet till Israels Konung, och sade till honom: Gack bort, och förstärk dig, och märk och se hvad du göra skall; ty Konungen i Syrien varder igenkommandes emot dig, när året är ute.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Förty Konungens tjenare i Syrien sade till honom: Deras gudar äro bergsgudar, derföre hafva de vunnit oss. O! att vi måtte strida med dem på slättene; hvad gäller, vi skulle vinna dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Gör alltså: Tag bort Konungarna, hvar af sitt rum, och sätt öfverstar i deras stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Och skicka dig en här, sådana som hären var, som du mist hafver, och hästar och vagnar, såsom hine voro, och låt oss strida emot dem på slättene; hvad gäller, vi öfvervinne dem? Han hörde deras röst, och gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Som nu året omgånget var, skickade Benhadad de Syrer, och drog upp till Aphek, till att strida emot Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Och Israels barn skickade sig ock, och bespisade sig, och drogo dit emot dem, och lägrade sig emot dem, såsom två små getahjordar; men landet var fullt med Syrer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Och en Guds man gick fram, och sade till Israels Konung: Så säger Herren: Derföre, att de Syrer hafva sagt: Herren är en Gud på bergom, och icke en Gud i dalar; så hafver jag gifvit allan denna stora hopen uti dina hand, att I skolen veta att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Och de lägrade sig tvärtemot hina i sju dagar; på sjunde dagen drogo de tillhopa i strid. Och Israels barn slogo de Syrer hundradetusend fotfolk af, på en dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Och de som öfverblefvo, flydde till Aphek in i staden. Och murarna föllo uppå de sju och tjugu tusend män, som qvare blefvo. Och Benhadad flydde också in i staden, uti en liten kammar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Då sade hans tjenare till honom: Si, nu hafve vi hört, att Israels hus Konungar äro barmhertige Konungar; så låt oss taga säcker kringom våra länder, och rep kringom vår hufvud, och gå ut till Israels Konung; tilläfventyrs han låter dina själ lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Och de bundo säcker öfver sina länder, och rep om sin hufvud, och kommo till Israels Konung, och sade: Benhadad din tjenare låter dig säga: Käre, låt mina själ lefva. Han sade: Lefver han ännu, så är han min broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Och männerna togo med hast ordet af honom, och tydde det ut för sig, och sade: Ja, din broder Benhadad. Han sade: Kommer, och hafver honom hit. Då gick Benhadad ut till honom, och han lät honom sitta på sinom vagn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Och han sade till honom: De städer, som min fader dinom fader aftagit hafver, vill jag få dig igen; och gör dig gator i Damascon, såsom min fader gjort hafver i Samarien; så vill jag fara ifrå dig med ett förbund. Och han gjorde ett förbund med honom, och lät honom fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Då sade en man utaf de Propheters söner till sin nästa, igenom Herrans ord: Käre, slå mig; men han nekade sig vilja slå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Då sade han till honom: Derföre, att du icke hafver hört Herrans röst, si, så skall ett lejon slå dig, när du går ifrå mig. Och då han gick ifrå honom, fann honom ett lejon, och slog honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Och han fann en annan man, och sade: Käre, slå mig. Och mannen slog honom, och gjorde honom sår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Då gick den Propheten bort, och trädde fram för Konungen på vägenom, och förvandlade sitt ansigte med asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Och när Konungen for der framom, ropade han till Konungen, och sade: Din tjenare var utdragen midt i striden; och si, en man var afviken, och hade en man till mig, och sade: Förvara denna mannen; om han kommer bort, så skall din själ vara i hans själs stad, eller du skall gifva en centener silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Och då din tjenare der och der beställa hade, kom han sin väg. Konungen sade till honom: Det är din dom, som du sjelfver afsagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Så strök han med hast askona af ansigtet; och Israels Konung kände honom, att han var en af Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Och han sade till honom: Så säger Herren: Derföre, att du hafver släppt den man utu dina händer, som tillspillogifven var, skall din själ vara för hans själ, och ditt folk för hans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Men Israels Konung for sina färde, illa tillfrids och vred, i sitt hus, och kom till Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Sedan detta skedt var, begaf sig, att Naboth, en Jisreelit, hade en vingård i Jisreel, vid Achabs palats, Konungens i Samaria.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Och Achab talade med Naboth, och sade: Låt mig få din vingård; jag vill göra mig der en kålgård af, efter han ligger så när mitt hus; jag vill gifva dig en bättre vingård igen; eller, om dig så täckes, vill jag gifva dig der silfver före, så mycket han är värd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Men Naboth sade till Achab: Det låte Herren vara långt ifrå mig, att jag skulle låta dig få mina fäders arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Då kom Achab hem, illa tillfrids och vred, för det ordets skull, som Naboth den Jisreeliten till honom talat hade, och sagt: Jag vill icke låta dig få mina fäders arf. Och han lade sig uppå sin säng, och vände sitt anlete, och åt intet bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Då kom Isebel hans hustru in till honom, och sade till honom: Hvad är det, att din ande är så illa tillfrids, och du intet bröd äter?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Han sade till henne: Jag hafver talat till Naboth den Jisreeliten, och sagt: Låt mig få din vingård för penningar; eller, om du hafver der lust till, vill jag gifva dig en annan igen; men han sade: Jag vill icke låta dig få min vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Då sade Isebel hans hustru till honom: Hvad vore för ett rike i Israel, om du gjordet? Statt upp, och ät bröd, och var vid godt mod; jag vill skaffa dig Naboths den Jisreelitens vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Och hon skref bref under Achabs namn, och beseglade det med hans signet, och sände till de äldsta och öfversta i hans stad, de som bodde med Naboth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Och skref brefvet alltså: Låter utropa en fasto, och sätter Naboth främst ibland folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Och låter komma två Belials män fram för honom, som vittna, och säga: Du hafver välsignat Gud och Konungen; och förer honom ut, och stener honom till döds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'De äldste och hans stads öfverstar, som i hans stad bodde, gjorde såsom Isebel dem budit hade, såsom i brefvet skrifvet var, det hon till dem sändt hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Och läto utropa en fasto, och läto Naboth sitta öfverst ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Då kommo de två Belials män, och ställde sig framför honom, och vittnade emot Naboth inför folket, och sade: Naboth hafver välsignat Gud och Konungen. Då förde de honom ut för staden, och stenade honom ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Och de bådade Isebel, och sade: Naboth är stenad, och död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Då nu Isebel hörde, att Naboth var stenad, och död, sade hon till Achab: Statt upp, och tag in Naboths vingård den Jisreelitens, den han dig nekat hafver för penningar; förty Naboth lefver icke, utan är död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Då Achab hörde, att Naboth var död, stod han upp, att han skulle gå ned till Naboths den Jisreelitens vingård, och taga honom in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Men Herrans ord kom till Elia den Thisbiten, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Statt upp, och gack ned emot Israels Konung, som är i Samarien; si, han är i Naboths vingård, dit han nedergången är, till att taga honom in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Och tala med honom, och säg: Så säger Herren: Du hafver dräpit, dertill ock intagit. Och du skall tala med honom, och säga: Detta säger Herren: På den staden, der hundar hafva slekt Naboths blod, skola ock hundar sleka ditt blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Och Achab sade till Elia: Hafver du ju funnit mig för din fienda? Han sade: Ja, hafver jag så funnit dig; derföre, att du såld äst till att intet annat göra, än det ondt är för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Si, jag skall låta komma ondt öfver dig, och borttaga dina efterkommande, och skall utrota utaf Achab ock den som på väggena pissar, och den som innelyckt och igenlefd är i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Och skall göra ditt hus såsom Jerobeams hus, Nebats sons, och såsom Baesa hus, Ahia sons, för det retandets skull, der du mig med förtörnat hafver, och kommit Israel till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Och om Isebel talade Herren desslikes, och sade: Hundar skola uppäta Isebel vid murarna i Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Hvilken af Achab dör i stadenom, den skola hundar äta; och hvilken som dör på markene, den skola foglar under himmelen äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Alltså var ingen, den, så alldeles såld var till att göra det ondt var för Herranom, såsom Achab; ty hans hustru Isebel eggade honom dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Och han gjorde sig till en stor styggelse, så att han vandrade efter afgudar, såsom de Amoreer gjort hade, hvilka Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Då Achab dessa orden hörde, ref han sönder sin kläder, och drog en säck på sin kropp, och fastade, och sof i säckenom, och gick luto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Och Herrans ord kom till Elia den Thisbiten, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Hafver du icke sett, huru Achab bugar sig för mig? Efter han nu bugar sig för mig, vill jag icke låta komma det onda i hans dagar; men i hans sons tid skall jag låta komma det onda öfver hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Och gingo tre år om, att intet örlig var emellan de Syrer och Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'I tredje årena drog Josaphat, Juda Konung, ned till Israels Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Och Israels Konung sade till sina tjenare: Veten I icke, att Ramoth i Gilead är vårt, och vi sitte stilla, och tage det icke igen utu Konungens hand i Syrien?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Och sade till Josaphat: Vill du draga med mig i strid emot Ramoth i Gilead? Josaphat sade till Israels Konung: Jag vill vara såsom du, och mitt folk såsom ditt folk, och mina hästar såsom dina hästar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Och Josaphat sade till Israels Konung: Fråga dock i dag om Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Då församlade Israels Konung Propheter vid fyrahundrad män, och sade till dem: Skall jag draga till Ramoth i Gilead till strid, eller skall jag låta bestå det? De sade: Drag ditupp; Herren varder det gifvandes i Konungens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Men Josaphat sade: Är här nu ingen Herrans Prophet mer, att vi måge, fråga af honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Israels Konung sade till Josaphat: Der är ännu en man, Micha, Jimla son, af hvilkom vi måge fråga Herran; men jag är vred på honom, ty han spår mig intet godt, utan allt ondt. Josaphat sade: Konungen tale icke så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Då kallade Israels Konung en kamererare, och sade: Haf med hast Micha, Jimla son, hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Och Israels Konung, och Josaphat, Juda Konung, såto hvardera på sinom stol, klädde i Konungslig kläder, på platsen för portenom af Samarien; och alle Propheterna spådde för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Och Zedekia, Chenaana son, hade gjort sig jernhorn, och sade: Detta säger Herren: Härmed skall du stöta de Syrer, tilldess du gör ända på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Och alle Propheterna spådde sammalunda, och sade: Drag upp till Ramoth i Gilead, och far lyckosamliga; Herren varder det gifvandes i Konungens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Och bådet, som bortgånget var till att kalla Micha, sade till honom: Si, Propheternas tal är endrägteliga godt för Konungenom; så låt nu ditt tal ock vara såsom deras tal, och tala det godt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Micha sade: Så sant som Herren lefver, jag skall tala det som Herren mig sägandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Och då han kom till Konungen, sade Konungen till honom: Micha, skole vi draga till Ramoth i Gilead till att strida, eller skole vi låta det bestå? Han sade till honom: Ja, drag ditupp, och far lyckosamliga. Herren varder det gifvandes i Konungens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Konungen sade åter till honom: Jag besvär dig, att du icke annat säger mig än sanningen, i Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Han sade: Jag såg hela Israel förströdd på bergen såsom får, de ingen herdan hafva; och Herren sade: Hafva desse ingen herra? Hvar och en vände om hem igen med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Då sade Israels Konung till Josaphat: Hafver jag icke sagt dig, att han intet godt spår mig, utan allt ondt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Han sade: Derföre hör nu Herrans ord: Jag såg Herran sitta på sinom stol; och allan himmelska hären stå der när honom, på hans högra sido, och hans venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Och Herren sade: Ho vill komma Achab i det sinnet, att han drager upp, och faller i Ramoth i Gilead? Och en sade det, och den andre det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Då gick en ande ut, och steg fram för Herran, och sade: Jag vill komma honom i det sinnet. Herren sade till honom: Hvarmed?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Han sade: Jag vill utgå, och vill vara en falsk ande uti alla hans Propheters mun. Han sade: Du skall komma honom i det sinnet, och få framgång; gack åstad, och gör alltså.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Nu se, Herren hafver gifvit en falsk anda uti alla dessa dina Propheters mun; och Herren hafver talat ondt öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Då gick Zedekia fram, Chenaana son, och slog Micha vid kindbenet, och sade: Huru? Hafver då Herrans Ande öfvergifvit mig, och talat med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Micha sade: Du skall få set på den dagen, då du går utu den ena kammaren uti den andra, att du må förgömma dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Israels Konung sade: Tag Micha, och låt honom blifva när Amon borgamästaren, och när Joas, Konungens son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Och säg: Detta säger Konungen: Sätter denna i fängsle, och spiser honom med bedröfvelses bröd och vatten, tilldess jag kommer igen med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Micha sade: Kommer du med frid igen, så hafver icke Herren talat genom mig. Och sade: Hörer häruppå, allt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Alltså drog Israels Konung och Josaphat, Juda Konung, upp till Ramoth i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Och Israels Konung sade till Josaphat: Jag vill förkläda mig, och komma i stridena; men du klädd i din egna kläder. Israels Konung förklädde sig, och drog i stridena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Men Konungen i Syrien böd sina öfverstar öfver hans vagnar, som voro två och tretio, och sade: I skolen icke strida antingen emot små eller stora, utan emot Israels Konung allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Och då de öfverste sågo Josaphats vagnar, mente de att det hade varit Israels Konung, och föllo till honom med stridene; men Josaphat ropade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Då nu då öfverste för vagnarna sågo, att det var icke Israels Konung, vände de tillbaka igen ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Och en man bände sin båga hårdt, och sköt Israels Konung emellan magan och lungorna. Och han sade till sin foroman: Vänd dina hand, och för mig utu hären; ty jag är sår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Och striden vardt svår i den dagen. Och Konungen stod uppå vagnen emot de Syrer, och om aftonen blef han död; och blodet flöt utaf såret midt i vagnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Och man lät utropa i hären, då solen gick neder, och säga: Hvar och en gånge i sin stad, och i sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Alltså blef Konungen död, och vardt förd till Samarien; och de begrofvo honom i Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Och då de tvådde vagnen vid dammen för Samarien, slekte hundar hans blod; och skökor tvådde honom, efter Herrans ord, det han talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Hvad mer af Achab sägandes är, och hvad allt han gjort hafver, och om det elphenbenshus som han byggde, och om alla de städer som han byggde, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Alltså afsomnade Achab med sina fäder; och hans son Ahasia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Och Josaphat, Asa son, vardt Konung öfver Juda, i fjerde årena Achabs, Israels Konungs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Och var fem och tretio år gammal, då han vardt Konung, och regerade fem och tjugu år i Jerusalem; hans moder het Asuba, Silhi dotter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Och vandrade uti allom sins faders Asa väg, och gick icke derifrå, och gjorde det Herranom behagade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Dock kastade han icke bort de höjder; och folket offrade och rökte ännu på höjderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Och han hade frid med Israels Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Hvad nu mer af Josaphat sägandes är, och hans magt, hvad han gjort, och huru han stridt hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Och fördref han desslikes utu landena hvad ännu qvart var af de roffare, som i hans faders Asa tid igenblefne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Och ingen Konung var i Edom; men en höfvitsman var regent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Och Josaphat hade låtit göra skepp i hafvet, som skulle till Ophir att hemta guld; men de foro intet åstad; förty de vordo sönderslagne i EzionGeber.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'På den tiden sade Ahasia, Achabs son, till Josaphat: Låt mina tjenare fara med dina tjenare i skeppen; men Josaphat ville icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Och Josaphat afsomnade med sina fäder, och vardt begrafven med sina fäder uti Davids hans faders stad; och Joram hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ahasia, Achabs son, vardt Konung öfver Israel i Samarien, i sjuttonde årena i Josaphats, Juda Konungs, och regerade öfver Israel i tu år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Och gjorde det ondt var för Herranom, och vandrade i sins faders och sine moders väg, och i Jerobeams, Nebats sons, väg, hvilken Israel kom till att synda. Och han tjente Baal, och tillbad honom, och förtörnade Herran Israels Gud, såsom hans fader gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Och de Moabiter föllo af ifrån Israel, då Achab död var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Och Ahasia föll genom gallren i sinom sal i Samarien, och vardt krank; och sände ut bådskap, och sade till dem: Går bort, och fråger BaalSebub, den guden i Ekron, om jag skall vederfås af denna krankheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Men Herrans Ängel sade till Elia den Thisbiten: Statt upp, och gack emot Konungens bådskap i Samarien, och säg till dem: Är nu ingen Gud i Israel, att I behöfven gå bort, och fråga BaalSebub, Ekrons gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Derföre, så säger Herren: Du skall icke komma utaf sängene, der du dig på lagt hafver; utan skall döden dö. Och Elia gick sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Och då båden igenkommo till honom, sade han till dem: Hvi kommen I igen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'De sade till honom: En man kom upp emot oss, och sade till oss: Går tillbaka igen till Konungen, som eder utsändt hafver, och säger till honom: Detta säger Herren: Är nu ingen Gud i Israel, att du skall sända bort, och fråga BaalSebub, Ekrons gud? Derföre skall du icke komma af sängene, der du hafver lagt dig uppå; utan skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Han sade till dem: Hurudana var den mannen, som eder mötte, och sade detta till eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'De sade till honom: Mannen var luden, och en lädergjord om hans länder. Han sade: Det är Elia den Thisbiten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Och han sände bort till honom en höfvitsman öfver femtio, med de samma femtio. Och då han kom upp till honom, si, då satt han uppe på bergena; och han sade till honom: Du Guds man, Konungen säger: Du skall komma ned:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Elia svarade höfvitsmannen öfver femtio, och sade till honom: Är jag en Guds man, så falle eld af himmelen, och upptäre dig och dina femtio. Då föll eld af himmelen, och upptärde honom och hans femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Och han sände åter en: annan höfvitsman öfver femtio till honom, med hans femtio: Han sade till honom: Du Guds man, detta säger Konungen: Kom snarliga ned.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Elia svarade, och sade: Är jag en Guds man, så falle eld af himmelen, och upptäre dig och dina femtio. Då föll Guds eld af himmelen, och upptärde honom och hans femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Då sände han ännu den tredje höfvitsmannen öfver femtio, med hans femtio. Då han kom upp till honom, böjde han sin knä för Elia, och bad honom, och sade till honom: Du Guds man, låt mina själ, och dina tjenares, dessa femtios själar, något aktade varda för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Si, elden är fallen af himmelen, och hafver upptärt de första två höfvitsmän öfver femtio, med deras femtio; men nu låt mina själ något aktad varda för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Då sade Herrans Ängel till Elia: Gack ned med honom, och frukta dig intet för honom. Han stod upp, och gick ned med honom till Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Och han sade till honom: Så säger Herren: Derföre, att du sände bådskap bort, och lät fråga BaalSebub, Ekrons gud, likasom ingen Gud vore i Israel, hvilkens ord man fråga kunde, så skall du icke komma af sängene, der du hafver lagt dig uppå; utan skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Alltså blef han död, efter Herrans ord, det Elia talat hade. Och Joram vardt Konung i hans stad, i andra årena Jorams, Josaphats sons, Juda Konungs; ty han hade ingen son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Hvad nu mer af Ahasia sägandes är, hvad han gjort hafver, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Då nu Herren ville upptaga Elia i vädret till himmelen, gick Elia och Elisa från Gilgal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Och Elia sade till Elisa: Käre, blif här; ty Herren hafver sändt mig till BethEl; men Elisa sade: Så sant som Herren lefver, och din själ, jag öfvergifver dig icke. Och de kommo ned till BethEl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Då gingo de Propheters söner, som i BethEl voro, ut till Elisa, och sade till honom: Vetst du ock, att Herren varder i denna dag tagandes din herra ifrå ditt hufvud? Han sade: Jag vet det ock väl; tiger man stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Och Elia sade till honom: Elisa, käre, blif här; ty Herren hafver sändt mig till Jericho. Han sade: Så sant som Herren lefver, och din själ, jag öfvergifver dig icke. Och de kommo till Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Då gingo de Propheters söner, som i Jericho voro, till Elisa, och sade till honom: Vetst du ock, att Herren varder i denna dag tagandes din herra ifrå ditt hufvud? Han sade: Jag vet det ock väl; tiger man stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Och Elia sade till honom: Käre, blif här; förty Herren hafver sändt mig till Jordan. Han sade: Så sant som Herren lefver, och din själ, jag öfvergifver dig icke. Och de gingo både tillsamman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Men femtio män af Propheternas söner gingo bort, och blefvo ståndande tvärt öfver, långt ifrå dem; men de både stodo vid Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Då tog Elia sin mantel, och svepte honom ihop, och slog i vattnet, och det delade sig på båda sidor; så att de både gingo torre derigenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Och då de öfver kommo, sade Elia till Elisa: Bed hvad jag dig göra skall, förr än jag varder ifrå dig tagen. Elisa sade: Att din ande varder öfver mig, till att tala dubbelt så mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Han sade: Du hafver bedit en svår ting; dock, om du ser mig, när jag varder ifrå dig tagen, så sker det; hvar ock icke, så sker det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Och vid de gingo tillsamman och talade, si, då kom en brinnande vagn med brinnande hästar, och skiljde dem båda ifrå hvarannan; och Elia for så upp i vädret till himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Men Elisa såg det, och ropade: Min fader, min fader, Israels vagn, och hans resenärar; och såg honom intet mer. Och han fattade sin kläder, och ref dem i tu stycker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Och tog upp Elia mantel, som ifrå honom fallen var, och vände om, och gick till Jordans strand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Och tog den samma Elia mantel, som ifrå honom fallen var, och slog i vattnet, och sade: Hvar är nu Herren, Elia Gud? och slog i vattnet; så delade det sig på båda sidor, och Elisa gick derigenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Och då Propheternas söner, som i Jericho tvärsöfver voro, sågo honom, sade de: Elia ande blifver på Elisa; och gingo emot honom, och tillbådo på jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Och sade till honom: Si, ibland dina tjenare äro femtio starke män; låt dem gå och söka din herra; tilläfventyrs Herrans Ande hafver tagit honom, och kastat honom någorstäds uppå ett berg, eller någorstäds uti en dal. Han sade: Låter intet gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Men de nödgade honom, tilldess han skämdes, och sade: Låter gå dem. Och de sände åstad femtio män; och de sökte honom i tre dagar, och funno honom intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Och kommo åter till honom; och han blef i Jericho, och sade till dem: Sade jag icke eder, att I icke skullen gå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Och männerna i stadenom sade till Elisa: Si, det är godt att bo i denna staden, såsom min herre ser; men här är ondt vatten, och landet ofruktsamt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Han sade: Tager mig hit ett nytt kärile, och lägger salt deruti. Och de gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Då gick han ut till vattukällona, och kastade saltet deruti, och sade: Så säger Herren: Jag hafver gjort detta vattnet helbregda; ingen död eller ofruktsamhet skall härefter komma deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Alltså vardt vattnet helbregda allt intill denna dag, efter Elisa ord, som han talade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Och han gick upp till BethEl; och vid han var på vägen ditåt, kommo små piltar utaf staden, och begabbade honom, och sade till honom: Du skallote, kom upp; du skallote, kom upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Och han vände sig om; och då han såg dem, bannade han dem i Herrans Namn. Då kommo två björnar utu skogenom, och refvo två och fyratio piltar ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Dädan gick han upp på Carmels berg, och vände sedan om dädan till Samarien igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram, Achabs son, vardt Konung öfver Israel i Samarien, uti adertonde årena Josaphats, Juda Konungs; och regerade i tolf år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Och gjorde det ondt varför Herranom, dock icke såsom hans fader och hans moder; ty han kastade bort Baals stöder, som hans fader hade göra låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Men han blef vid Jerobeams, Nebats sons, synder, hvilken kom Israel till att synda; och trädde intet derifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Men Mesa, de Moabiters Konung, hade mång får, och han skattade Israels Konunge ull af hundradetusend lamb, och af hundradetusend vädrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Då nu Achab var död, föll de Moabiters Konung af ifrån Israels Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Då drog ut på den tiden Konung Joram af Samarien, och skickade hela Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Och sände bort till Josaphat, Juda Konung, och lät säga honom: De Moabiters Konung är affallen ifrå mig. Kom med mig till att strida emot de Moabiter. Han sade: Jag vill uppkomma; jag är såsom du, och mitt folk såsom ditt folk, och mine hästar såsom dine hästar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Och sade: Hvilken vägen vilje vi draga ditupp? Han sade: Den vägen igenom Edoms öken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Alltså drogo åstad Israels Konung, Juda Konung, och Edoms Konung. Och som de omkringdragit hade sju dagsresor, hade hären, och de öker, som med dem voro, intet vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Då sade Israels Konung: Ack, ve! Herren hafver dessa tre Konungar församlat, på det han skall gifva dem uti de Moabiters händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Men Josaphat sade: Är här ingen Herrans Prophet, att vi måge genom honom fråga Herran? Då svarade en ibland Israels Konungs tjenare, och sade: Här är Elisa, Saphats son, hvilken göt vatten på Elia händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josaphat sade: Herrans ord är när honom. Alltså drogo neder till honom Israels Konung, och Josaphat, och Edoms Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Då sade Elisa till Israels Konung: Hvad hafver du med mig skaffa? Gack bort till dins faders Propheter, och till dine moders Propheter. Israels Konung sade till honom: Nej; ty Herren hafver församlat dessa tre Konungar, på det han skall gifva dem uti de Moabiters händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elisa sade: Så sant som Herren Zebaoth lefver, för hvilkom jag står, om jag icke ansåge Josaphat, Juda Konung, jag ville icke anse dig eller akta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Så låter nu en spelman komma hit. Och då spelmannen spelade på strängerna, kom Herrans hand öfver honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Och han sade: Detta säger Herren: Görer grafver vid denna bäcken här och der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Förty så säger Herren: I skolen intet väder eller regn se; likväl skall bäcken varda full med vatten, så att I, och edart folk, och edra öker skola få dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Dertill är detta en ringa ting för Herranom; han skall ock gifva de Moabiter i edra händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Så att I skolen slå alla fasta städer, och alla utvalda städer, och skolen omkullhugga all god trä, och skolen förstoppa alla vattubrunnar, och skolen förderfva alla goda åkrar med stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Om morgonen, då man spisoffer offrade, si, då kom ett vatten på den vägen ifrån Edom, och fyllde landet med vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Då nu de Moabiter hörde, att Konungarna drogo upp till att strida emot dem, kallade de tillhopa alla, som vuxne voro att bära vapen, och derutöfver, och drogo intill gränson.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Och som de om morgonen bittida uppstode, och solen uppgick öfver vattnet, tyckte de Moabiter, att vattnet emot dem var rödt såsom blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Och de sade: Det är blod; Konungarna hafva slagits inbördes med svärd, och den ene hafver slagit den andra. Nu Moab, statt upp, och tag byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Men då de kommo till Israels lägre, reste Israel upp, och slog de Moabiter, och de flydde för dem; men de kommo in, och slogo Moab;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Bröto städerna neder, och hvar och en kastade sin sten på alla goda åkrar, och uppfyllde dem, och förstoppade alla vattubrunnar, och fällde all god trä, tilldess att allenast stenarna i tegelmuren qvare blefvo; och de kringhvärfde staden med slungor, och slogo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Då de Moabiters Konung såg att striden vardt honom för stark, tog han sjuhundrade män till sig, som svärd utdrogo, till att slå ut emot Edoms Konung; men de kunde icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Då tog han sin första son, som i hans stad skulle Konung vordit, och offrade honom till ett bränneoffer på muren. Då kom en stor vrede öfver Israel; så att de drogo ifrå honom, och vände till landet igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Och en qvinna utaf de Propheters söners hustrur ropade till Elisa, och sade: Din tjenare, min man, är död blefven; så vetst du, att han din tjenare fruktade Herran; nu kommer den han skyldig var, och vill taga båda mina söner till trälar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisa sade till henne: Hvad skall jag göra dig? Säg mig, hvad hafver du i huset? Hon sade: Din tjenarinna hafver intet i huset, utan ena kruko med oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Han sade: Gack bort, och beds af alla dina grannhustrur tom käril, väl mång;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Och gack in, och slut dörrena igen efter dig, med dina söner, och gjut i all kärilen; och när du hafver fyllt dem, så tag bort dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Hon gick bort, och slöt dörrena igen efter sig, samt med sina söner; de båro kärilen fram till henne, och hon göt uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Och då kärilen voro full, sade hon till sin son: Hemta mig ännu ett kärile. Han sade till henne: Här är intet kärile mer. Så stadnade oljan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Och hon gick bort, och sade det Guds mannenom. Han sade: Gack bort, sälj oljona, och betala dem du skyldig äst; men du och dine söner, lefver utaf det andra, som öfver är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Och det begaf sig på en tid, att Elisa gick till Sunem. Der var en rik qvinna, och hon höll honom uppe, så att han fick sig der mat. Och som han ofta färdades derigenom, gick han ju in till henne, och åt när henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Och hon sade till sin man: Si, jag förmärker, att denne Guds mannen är helig, som alltid går här fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Låt oss göra en liten brädesal, och sätta derin en säng, bord, stol, och ljusastaka; på det att, när han till oss kommer, må han der blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Så hände det sig på en tid, att han kom ditin, och lade sig i salen, och sof derinne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Och sade till sin tjenare Gehasi: Kalla den Sunamitiskona. Och då han hade kallat henne, gick hon fram för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Han sade till honom; Säg henne: Si, du hafver gjort oss alla denna tjenstena; hvad skall jag göra dig? Hafver du något värf till Konungen, eller till härhöfvitsmannen? Hon sade: Jag bor ibland mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Han sade: Hvad skall man då göra henne? Gehasi sade: Ack! hon hafver ingen son, och hennes man är gammal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Han sade: Kalla henne. Och då han hade kallat henne, kom hon i dörrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Och han sade: På denna tiden, när frukten kan lefva, skall du hafva en son i famnen. Hon sade: Ack! nej, min Herre, du Guds man, ljug icke för dine tjenarinno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Och qvinnan vardt hafvandes, och födde en son, på samma tiden då frukten lefva kunde, såsom Elisa hade sagt henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Då pilten vardt stor, hände sig, att han gick ut till sin fader, till skördemännerna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Och sade till sin fader: Ack! mitt hufvud, mitt hufvud. Han sade till sin tjenare: Haf honom bort till sina moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Och han tog honom, och hade honom till hans moder. Och hon satte honom i sitt sköte allt intill middagen; då blef han död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Och hon gick upp, och lade honom på Guds mansens säng, slöt till, och gick ut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Och kallade sin man, och sade: Sänd mig en af tjenarena, och ena åsninno; jag vill till Guds mannen, och komma igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Han sade: Hvi vill du till honom? Är dock i dag icke nymånad eller Sabbath. Hon sade: Väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Och hon sadlade åsninnona, och sade till tjenaren: Drif uppå, och låt oss icke töfva med ridandet, såsom jag säger dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Alltså drog hon åstad, och kom till Guds mannen på Carmels berg. Som nu Guds mannen såg henne komma, sade han till sin tjenare Gehasi: Si, den Sunamitiskan är der;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Så löp nu emot henne, och fråga henne, om henne, och hennes man, och son väl går. Hon sade: Väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Men då hon uppkom till Guds mannen på berget, fick hon honom om hans fötter. Och Gehasi gick fram, och ville drifva henne bort; men Guds mannen sade: Låt blifva henne; förty hennes själ är bedröfvad; och Herren hafver mig det fördolt, och icke låtit mig det förstå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Hon sade: När hafver jag bedts en son af min herra? Sade jag icke, att du icke skulle bespotta mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Han sade till Gehasi: Begjorda dina länder, och tag min staf i dina hand, och gack åstad; om någor möter dig, så helsa honom intet; och om någor helsar dig, så svara honom intet; och lägg min staf på piltens anlete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Men piltens moder sade: Så sant som Herren lefver, och din själ, jag släpper dig icke. Då stod han upp, och följde henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Men Gehasi var allaredo gången framför dem, och lade stafven på piltens anlete; men der var hvarken röst eller sinne. Och han gick tillbaka igen emot honom, och bådade honom, och sade: Pilten är icke uppväckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Och då Elisa kom i huset, si, då låg pilten död på hans säng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Och han gick in, och slöt igen dörrena om sig båda, och bad till Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Och steg upp, och lade sig öfver pilten, och lade sin mun på piltens mun, och sin ögon på hans ögon, och sina händer på hans händer, och räckte sig så ut öfver honom, så att piltens kropp vardt varm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Men han stod åter upp, och gick en gång hit och dit i huset, och steg upp, och räckte sig ut öfver honom. Då prustade pilten sju resor; sedan lät pilten ögonen upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Och han kallade Gehasi, och sade: Kalla Sunamitiskona. Och då han hade kallat henne, kom hon in till honom. Han sade: Tag här din son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Då kom hon, och föll till hans fötter, och tillbad på jordena; och tog sin son, och gick ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Då Elisa kom igen till Gilgal, vardt dyr tid i landena, och de Propheters söner bodde för honom. Och han sade till sin tjenare: Sätt fram en stor gryto, och koka ett mos för Propheternas söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Så gick en ut på markena till att hemta krydde; och han fann en kurbitsstjelk, och hemte deraf vildkurbits sitt kläde fullt. Och då han kom, skar han det i grytona till moset; förty de kände det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Och då de gåfvo det upp för männerna till att äta, och de åto af moset, ropade de, och sade: O! Guds man, döden i grytone; ty de kunde icke ätat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Han sade: Hafver hit mjöl; och han kastade det i grytona, och sade: Gif upp för folket, att de måga äta. Så var det intet bittert i grytone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Och en man kom ifrå BaalSalisa, och bar Guds mannenom förstlingsbröd, nämliga tjugu bjuggbröd, och ny säd i sin kjortel. Men han sade: Gif det folkena, att de äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Hans tjenare sade: Hvad kan det slå framför hundrade män? Han sade: Gif det folkena, att de måga äta; förty så säger Herren: De skola äta, och skall ändå öfverblifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Och han lade det fram för dem, så att de åto; och blef ändå öfver, efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naaman, Konungens härhöfvitsman af Syrien, var en härlig man för sin herra, och mycket aktad; förty genom honom hade Herren gifvit salighet i Syrien; och han var en mägtig man, dock spitelsk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Och krigsmännerna i Syrien voro utfallne, och hade bortfört en liten pigo utur Israels land; och hon var i tjenst när Naamans hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Hon sade till sina fru: Ack! att min herre vore när den Propheten i Samarien, den skulle väl göra honom fri ifrå hans spitelsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Då gick hon in till sin herra, och gaf honom det tillkänna, och sade: Så och så hafver den pigan af Israels land sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Konungen i Syrien sade: Så far dit, och jag vill skrifva Israels Konung ett bref till. Och han drog dit, och tog med sig tio centener silfver, och sextusend gylden, och tio högtidskläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Och förde brefvet till Israels Konung, och det lydde alltså: När detta bref kommer till dig, si, så vet att jag hafver sändt min tjenare Naaman till dig, att du gör honom fri ifrån hans spitelsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'När Israels Konung las brefvet, ref han sin kläder sönder, och sade: Är jag då Gud, att jag skulle kunna döda och lif gifva, efter han sänder till mig, att jag skall göra den mannen fri ifrå hans spitelsko? Märker och ser, huru han söker tillfälle emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Då Elisa den Guds mannen det hörde, att Israels Konung hade rifvit sin kläder sönder, sände han till honom, och lät säga honom: Hvi hafver du rifvit din kläder? Låt honom komma till mig, att han må förnimma att en Prophet är i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Alltså kom Naaman med hästar och vagnar, och höll för Elisa husdörr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Då sände Elisa ett båd till honom, och lät säga honom: Gack bort, och två dig sju resor i Jordan; och ditt kött skall komma sig till igen, och varda rent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Då vardt Naaman vred, och drog sina färde, och sade: Jag mente han skulle komma hitut till mig, och gå fram, och åkalla Herrans sins Guds Namn, och med sine hand taga på rummet, och så bota spitelskona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Äro icke Abana och Pharphars vatten i Damascon bättre än all vatten i Israel, att jag må två mig deruti, och varda ren? Och vände sig, och for sin väg med vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Då gingo hans tjenare till honom, och talade till honom, och sade: Min fader, om Propheten hade sagt dig något dråpeligit före, skulle du icke hafva gjort det? Huru mycket mer, medan han säger till dig: Två dig, så varder du ren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Då steg han af, och doppade sig i Jordan sju resor, såsom Guds mannen sagt hade; och hans kött kom till sig igen, såsom en ung drängs kött, och vardt ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Och han vände om igen till Guds mannen, med all sin skara. Och då han kom in, gick han fram för honom, och sade: Si, jag vet, att ingen Gud är i all land, utan i Israel; så tag nu välsignelse af dinom tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Men han sade: Så sant som Herren lefver, för hvilkom jag står, jag tager det icke. Och han nödgade honom, att han skulle tågat; men han ville icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Då sade Naaman: Må då icke dinom tjenare varda gifvet en börda af denna jordene, så mycket som två mular orka bära? ty din tjenare vill icke mer androm gudom offra, och bränneoffer göra, utan Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Att Herren ville derutinnan vara dinom tjenare nådelig, när jag tillbeder i Rimmons hus, när min herre går uti Rimmons hus till att tillbedja der, och han stödjer sig vid mina hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Han sade till honom: Far i frid. Och han for ifrå honom ett litet stycke vägs på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Då tänkte Gehasi, Gudsmannens Elisa tjenare: Si, min herre hafver spart denna Syren Naaman, så att han intet hafver tagit af honom, det han hit hade; så sant som Herren lefver, jag vill löpa efter honom, och taga något af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Alltså jagade Gehasi efter Naaman; och då Naaman såg, att han lopp efter honom, steg han af vagnen emot honom, och sade: Går det väl till?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Han sade: Ja; men min herre hafver sändt mig, och låter dig säga: Si, nu på stundene äro till mig komne ifrå Ephraims berg två unga män utaf de Propheters söner. Gif dem en centener silfver, och tu högtidskläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naaman sade: Gerna; tag två centener. Och han nödgade honom, och band två centener silfver i två säcker, och tu högtidskläder, och fick det två sina tjenare; och de båro det med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Och då han kom till mörkt rum, tog han det utaf deras händer, och lade det öfver en sido i huset, och lät männerna gå; och de gingo bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Då gick han fram för sin herra. Och Elisa sade till honom: Hvadan kommer du, Gehasi? Han sade: Din tjenare hafver hvarken hit eller dit gångit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Han sade till honom: Månde icke mitt hjerta vandra med dig, då mannen vände om igen ifrå sin vagn emot dig? Nu, du hafver tagit silfver och kläder, oljogårdar, vingårdar, får, oxar, tjenare och tjenarinnor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Men Naamans spitelska skall låda vid dig, och dina säd, till evig tid. Så gick han ut ifrå honom spitelsker såsom en snö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'De Propheters söner sade till Elisa: Si, rummet, der vi för dig bo, är oss för trångt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Låt oss gå till Jordan; och hvar och en hemte der timber, att vi måge bygga oss der ett rum till att bo uti. Han sade: Går åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Och en sade: Kom ock du, och gack med dina tjenare. Han sade: Jag vill gå med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Och han gick med dem. Och då de kommo till Jordan, höggo de trä neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Och som en af dem fällde ett trä, föll yxen i vattnet; och han ropade, och sade: Ack! ve, min herre; och hon är mig lånt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Men Guds mannen sade: Hvar är hon fallen? Och då han viste honom rummet, skar han ett trä af, och kastade det dit; och yxen flöt uppe.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Och han sade: Tag henne upp. Han räckte ut sina hand, och tog henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Och Konungen i Syrien förde örlig emot Israel. Och han rådfrågade med sina tjenare, och sade: Vi vilje lägra oss der och der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Men Guds mannen sände till Israels Konung, och lät säga honom: Tag dig till vara, att du icke drager till det rummet; förty de Syrer ligga der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Så sände då Israels Konung bort till det rummet, som Guds mannen om sade, förvarade det, och höll der vakt; och gjorde det icke en gång eller två gångor allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Då vardt Konungens hjerta i Syrien illa tillfreds deröfver, och kallade sina tjenare, och sade till dem: Viljen I då icke säga mig, hvilken af våra är flydd till Israels Konung?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Då sade en af hans tjenare: Icke så, min herre Konung; utan Elisa, den Propheten i Israel, säger Konungenom i Israel allt det du talar i kammaren, der din säng är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Han sade: Så går bort, och ser till hvar han är, att jag må sända bort och låta hemta honom. Och de underviste honom, och sade: Si, i Dothan är han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Då sände han dit hästar och vagnar, och en stor magt. Och som de ditkommo om nattena, belade de staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Och Guds mansens tjenare stod bittida upp, att han skulle gå ut; och si, då låg en här om staden, med hästar och vagnar. Då sade hans tjenare till honom: Ack! ve, min Herre, hvad vilje vi nu göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Han sade: Frukta dig intet; förty de äro flere som med oss äro, än de som med dem äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Och Elisa bad, och sade: Herre, öppna honom ögonen, att han må se. Då öppnade Herren tjenarenom hans ögon, att han fick se. Och si, då var berget fullt med brinnande hästar och vagnar omkring Elisa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Och då de kommo ditneder till honom, bad Elisa, och sade: Herre, slå detta folket med blindhet Och han slog dem med blindhet, efter Elisa ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Och Elisa sade till dem: Detta är icke den vägen, eller den staden; följer mig efter, jag vill föra eder till den man, som I söken; och förde dem till Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Som de kommo till Samarien, sade Elisa: Herre, öppna dessom ögonen, att de måga se. Och Herren öppnade dem ögonen, att de sågo. Och si, då voro de midt i Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Och Israels Konung, då han såg dem, sade han till Elisa: Min fader, skall jag slå dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Han sade: Du skall icke slå dem; de som du får med ditt svärd och båga, dem slå. Sätt dem vatten och bröd före, att de måga äta och dricka; och lät dem fara till sin herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Så vardt dem tillredd en stor måltid. Och när de hade ätit och druckit, lät han dem gå, så att de drogo till sin herra. Och sedan kom icke mer krigsfolk af Syrien i Israels land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Derefter begaf sig, att Benhadad, Konungen i Syrien, församlade all sin här, och drog upp, och belade Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Och en hård tid var i Samarien; men de belade staden, intilldess ett åsnahufvud galt åttatio silfpenningar; och en fjerdedel af ett kab dufvoträck fem silfpenningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Och då Israels Konung gick på murenom, ropade en qvinna till honom, och sade: Hjelp mig, min herre Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Han sade: Hjelper icke Herren dig, hvadan skulle jag hjelpa dig? Af loganom, eller af pressenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Och Konungen sade till henne: Hvad är dig? Hon sade: Denna qvinnan sade till mig: Få hit din son, att vi måge äta honom, i dag; i morgon vilje vi äta min son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Så hafve vi kokat min son, och ätit. Och jag sade till henne den andra dagen: Få hit din son, och låt oss äta; men hon undstack sin son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Då Konungen hörde qvinnones ord, ref han sin kläder sönder, vid han gick på murenom. Då såg allt folket, att han hade en säck på kroppenom, innan under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Och han sade: Gud göre mig det och det, om Elisa, Saphats sons, hufvud skall i dag blifva ståndandes på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Och Elisa satt i sitt hus. Och de äldste såto när honom. Och han sände en man framför sig. Men förr än bådet kom till honom sade han till de äldsta: Hafven I sett, huru denne mördaren hafver hitsändt, att taga mitt hufvud af? Ser till, när bådet kommer, att I lycken dörrena igen, och klämmer honom med dörrene; si, dönen af hans herras fötter följer efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Vid han ännu med dem talade, si, då kom bådet ned till honom, och sade: Si, detta onda kommer af Herranom; hvad skall jag mer vänta af Herranom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Men Elisa sade: Hörer Herrans ord; så säger Herren: I morgon på denna tiden skall en skäppa semlomjöl gälla en sikel, och två skeppor bjugg en sikel, i Samarie port.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Då svarade en riddare, vid hvilkens hand Konungen sig stödde, Guds mannenom, och sade: Om Herren än gjorde fenster på himmelen, huru kunde detta ske? Han sade: Si, du skall få se det med din ögon; men intet skall du äta deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Och fyra spitelske män voro utan porten, och den ene sade till den andra: Hvad vilje vi blifva här tilldess vi dö?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Det vi än ville gå in i staden, så är hård tid i stadenom, att vi måste dock der dö; blifve vi ock här, så måste vi ock dö. Så låt oss nu gå bort, och gifva oss till de Syrers här; låta de oss lefva, så lefve vi; dräpa de oss, så äre vi döde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Och de voro bittida uppe om morgonen, på det de skulle gå till de Syrers här. Och som de kommo till det främsta på lägret, si, då var der ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Ty Herren hade låtit de Syrer höra en gny af hästar och vagnar, och af en mägtig här, så att de sade till hvarannan: Si, Israels Konung hafver besoldat emot oss de Hetheers Konungar, och de Egyptiers Konungar, att de skola komma öfver oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Och stodo upp, och flydde bittida om morgonen, och läto blifva sina hyddor, hästar, åsnar och lägret, såsom det stod, och flydde med deras lif derifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Som nu de spitelske kommo till det främsta af lägret, gingo de in uti ena hyddo; åto och drucko, och togo silfver och guld, och kläder, och gingo bort, och förgömde det; och kommo igen, och gingo in uti en annor hyddo, och togo derut, och gingo bort, och förgömde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Men de sade till hvarannan: Låt oss icke så göra; denne dagen är ett godt bådskaps dag; om vi detta förtige, och bide intill ljus morgon, så varder vår missgerning funnen. Så låt oss nu gå bort och bebåda det i Konungshuset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Och då de kommo, ropade de vid stadsporten, och underviste dem och sade: Vi kommo uti de Syrers lägre, och si, der är ingen, ej heller någor menniskos röst; utan hästar och åsnar bundne, och hyddorna såsom de stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Då ropade man till porthållarena, att de skulle det derinne säga i Konungshuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Och Konungen stod upp om nattena, och sade till sina tjenare: Jag vill säga eder, huru de Syrer bära sig åt med oss; de veta att vi lide hunger, och äro utu lägret gångne, och hafva fördolt sig i markene, och tänka: När de gå utu staden, vilje vi gripa dem lefvande, och komma så i staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Då svarade en af hans tjenare, och sade: Man må taga de fem hästar, som ännu igenblefne äro härinne; si, de äro härinne igenblefne af hela hopen i Israel, de andre äro åtgångne; låt oss dem sända och beset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Då togo de två vagnhästar; och Konungen sände dem till i de Syrers lägre, och sade: Farer, och ser till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Och de drogo efter dem allt intill Jordan, si, då låg vägen full med kläder och tyg, som de Syrer hade ifrå sig kastat, då de hastade sig. Båden kommo igen, och underviste det Konungenom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Då gick folket ut, och skinnade de Syrers lägre. Och så galt en skäppa semlomjöl en sikel, och desslikes två skäppor bjugg ock en sikel, efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Men Konungen skickade den riddaren, vid hvilkens hand han stödde sig, i porten; och folket förtrampade honom i portenom, så att han blef död, såsom Guds mannen sagt hade, då Konungen hade gångit ned till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Och skedde såsom Guds mannen med Konungenom talat hade, då han sade: I morgon på denna tiden skola två skäppor bjugg gälla en sikel, och en skäppa semlomjöl en sikel, i Samarie port.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Och riddaren svarade Guds mannenom, och sade: Si, om Herren än gjorde fenster på himmelen, huru kunde detta ske? Men han sade: Si, med din ögon skall du se det, och intet äta deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Och det gick honom ock så; ty folket förtrampade honom i portenom, så att han blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elisa talade med den qvinnone, hvilkens son han hade lefvande gjort, och sade: Statt upp och gack dina färde med ditt hus, och var främmande hvar du kan; ty Herren varder kallandes en hunger, och han skall komma öfver landet i sju år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Qvinnan stod upp, och gjorde såsom Guds mannen sade: och drog åstad med sitt hus, och var främmande uti de Philisteers land i sju år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Då de sju åren förlidne voro, kom qvinnan åter utu de Philisteers land; och hon gick ut till att ropa till Konungen om sitt hus och åker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Då talade Konungen med Gehasi, den Guds mansens tjenare, och sade: Förtälj mig all de stora ting, som Elisa gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Och som han förtäljde Konungenom, huru han hade gjort en dödan lefvande, si, i det samma kom qvinnan dertill, hvilkens son han hade lefvande gjort, och ropade till Konungen om sitt hus och åker. Då sade Gehasi: Min herre Konung, detta är qvinnan, och detta är hennes son, som Elisa hafver lefvande gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Och Konungen frågade qvinnona, och hon förtäljde honom det. Då fick Konungen henne en kamererare, och sade: Fly henne igen allt det hennes är; dertill allt afgället af åkrenom, ifrå den tid hon öfvergaf landet intill nu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Och Elisa kom till Damascon; då låg Benhadad, Konungen i Syrien, krank; och honom vardt bådadt och sagdt: Den Guds mannen är kommen här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Då sade Konungen till Hasael: Tag skänker med dig, och gack emot den Guds mannen, och fråga genom honom Herran, och säg: Månn jag vederfås af denna krankheten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Hasael gick emot honom, och tog skänker med sig, och allahanda ägodelar i Damascon, fyratio camelers bördor. Och då han kom, gick han fram för honom, och sade: Din son Benhadad, Konungen i Syrien, hafver sändt mig till dig, och låter säga dig: Kan jag ock vederfås af denna krankheten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elisa sade till honom: Gack bort, och säg honom: Du skall vederfås; men Herren hafver undervist mig, att han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Och Guds mannen begynte se skarpt ut, och hade sig ömkeliga, och gret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Då sade Hasael: Hvi gråter min herre? Han sade: Jag vet hvad ondt du skall göra Israels barnom; du skall uppbränna deras fasta städer med eld, och deras unga män dräpa med svärd, och döda deras unga barn, och deras hafvande qvinnor sönderrifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hasael sade: Hvad är din tjenare, den hunden, att han sådana stor ting göra skall? Elisa sade: Herren hafver tett mig, att, du skall varda Konung i Syrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Och han gick sin väg ifrån Elisa, och kom till sin herra. Han sade till honom: Hvad sade dig Elisa? Han svarade: Han sade mig: Du skall vederfås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Men på den andra dagen tog han täckenet, och stack det i vatten, och bredde öfver sig; då blef han död. Och Hasael vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Uti femte årena Jorams, Achabs sons, Israels Konungs, i Josaphats, Juda Konungs, tid, vardt Joram, Josaphats son, regerande i Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Tu och tretio år gammal var han, då han vardt Konung, och regerade åtta år i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Och vandrade på Israels Konungars väg, såsom Achabs hus gjorde; ty Achabs dotter var hans hustru; och han gjorde det ondt var för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Men Herren ville icke förderfva Juda, för sin tjenare Davids skull, såsom han honom sagt hade, att gifva honom en lykto ibland hans barn i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Uti hans tid föllo de Edomeer af ifrå Juda, och gjorde en Konung öfver sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Förty Joram var dragen genom Zair, och alla vagnarna med honom, och hade ståndit upp om nattena, och slagit de Edomeer, som omkring honom voro; dertill ock de öfversta öfver vagnarna, så att folket flydde i sina hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Derföre föllo de Edomeer af ifrå Juda, allt intill denna dag. Föll ock desslikes Libna af på samma tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Hvad nu mer af Joram sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Och Joram afsomnade med sina fäder, och vardt begrafven med sina fäder uti Davids stad; och Ahasia hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Uti tolfte årena Jorams, Achabs sons, Israels Konungs, vardt Ahasia, Jorams son, Konung i Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Tu och tjugu år gammal var Ahasia, då han Konung vardt, och regerade ett år i Jerusalem; hans moder het Athalja, Amri dotter, Israels Konungs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Och han vandrade på Achabs hus väg, och gjorde det ondt var för Herranom, såsom Achabs hus; ty han var Achabs hus svåger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Och han drog med Joram, Achabs son, i strid emot Hasael, Konungen i Syrien, till Ramoth i Gilead; men de Syrer slogo Joram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Då vände Konung Joram tillbaka, att låta läka sig i Jisreel, för de sårs skull, som de Syrer honom slagit hade i Rama, då han stridde med Hasael, Konungenom i Syrien. Och Ahasia, Jorams son, Juda Konung, kom neder till att bese Joram, Achabs son i Jisreel; ty han låg krank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Elisa kallade en af de Propheters söner, och sade till honom: Gjorda dina länder, och tag denna oljokrukona med dig, och gack till Ramoth i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Och då du kommer dit, får du der se Jehu, Josaphats son, Nimsi sons, och gack in, och bed honom stå upp ibland sina bröder, och haf honom in uti den innersta kammaren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Och tag oljokrukona, och gjut den ut på hans hufvud, och säg: Detta säger Herren: Jag hafver smort dig till Konung öfver Israel. Och du skall låta upp dörrena, och fly, och icke förtöfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Och Prophet ens tjenare, den unge mannen, gick åstad till Ramoth i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Och då han inkom, si, då såto der höfvitsmännerna för hären. Och han sade: Höfvitsman, jag hafver något säga dig. Jehu sade: Hvilkom af oss alla? Han sade: Dig, höfvitsman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Då stod han upp, och gick in; men han göt oljona på hans hufvud, och sade till honom: Detta säger Herren Israels Gud: Jag hafver smort dig till Konung öfver Herrans folk Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Och du skall slå dins herras Achabs hus, att jag skall hämnas mina tjenares Propheternas blod, och alla Herrans tjenares lod, utur Isebels hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Så att hela Achabs hus skall förgås; och jag skall af Achab utrota den som på väggena pissar, och den innelyckta, och den igenlefda i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Och skall göra Achabs hus, såsom Jerobeams hus, Nebats sons, och såsom Baesa hus, Ahia sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Och hundar skola uppäta Isebel på åkren i Jisreel; och ingen skall begrafva henne. Och han lät upp dörrena, och flydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Och då Jehu gick ut till sins herras tjenare, sade de till honom: Går det allt väl till? Hvar efter är denne rasaren kommen till dig? Han sade till dem: I kännen dock mannen väl, och hvad han säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'De sade: Det är icke sant, säg du oss det. Han sade: Så och så hafver han talat med mig, och sagt: Detta säger Herren, jag hafver smort dig till. Konung öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Då hastade de sig, och hvar och en tog sin kläder, och lade under honom invid säjaren, och blåste med basuner, och sade: Jehu är Konung vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Alltså gjorde Jehu, Josaphats son, Nimsi sons, ett förbund emot Joram; men Joram låg för Ramoth i Gilead med hela Israel, emot Hasael, Konungen i Syrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Men Konung Joram var igenkommen, till att låta sig läka i Jisreel, af de sår som de Syrer honom slagit hade, då han stridde med Hasael, Konungenom i Syrien. Och Jehu sade: Är det så eder i sinnet, så skall ingen slippa utaf staden, att han går bort, och bådar det i Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Och han for upp, och drog till Jisreel; förty Joram låg der. Så var Ahasia, Juda Konung, nederdragen till att bese Joram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Men väktaren, som på tornet i Jisreel stod, fick se Jehu hop komma, och sade: Jag ser en hop. Då sade Joram: Tag en vagn, och sänd emot dem, och säg: Är allt fridsamt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Och foromannen for emot honom, och sade: Detta säger Konungen: Är allt fridsamt? Jehu sade: Hvad kommer friden dig vid? Far här bakefter mig. Väktaren förkunnade, och sade: Bådet är kommet till dem, och kommer intet igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Då sände han en annan foroman. Då han kom till dem, sade han: Detta säger Konungen: Är allt fridsamt? Jehu sade: Hvad kommer friden dig vid? Far här bakefter mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Det förkunnade väktaren, och sade: Han är kommen till dem, och kommer intet igen; och det är ett körande, såsom Jehu körande, Nimsi sons; ty han körer lika som han vore rasande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Då sade Joram: Sätter före. Och de satte före hans vagn. Och de drogo ut, Joram, Israels Konung, och Ahasia, Juda Konung, hvardera på sin vagn, att de skulle komma emot honom. Och de råkade honom på Naboths åker, den Jisreelitens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Och då Joram såg Jehu, sade han: Jehu, är allt fridsamt? Han sade: Hvad, frid? Dine moders Isebels horeri och trolldom hafver icke ännu ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Då vände Joram sina hand om, och flydde, och sade till Ahasia: Här är förräderi, Ahasia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Men Jehu fattade bågan, och sköt Joram emellan härderna, så att pilen gick ut igenom hjertat, och han föll uti sin vagn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Och Jehu sade till höfvitsmannen Bidkar: Tag och kasta honom uppå åkrastycket, Naboths den Jisreelitens; förty jag kommer ihåg, att du med mig forom efter hans fader på enom vagn, att Herren lade denna tungan uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Hvad gäller, sade Herren, jag skall vedergälla dig på denna åkren Naboths blod, och hans söners blod, det jag i går såg. Så tag honom nu, och kasta honom på åkren, efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Då Ahasia, Juda Konung, det såg, flydde han på den vägen till örtagårdshuset; men Jehu jagade efter honom, och böd desslikes slå honom på vagnenom in mot Gur, som ligger vid Jibleam; och han flydde till Megiddo, och blef der död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Och hans tjenare läto föra honom till Jerusalem; och begrofvo honom i hans graf med sina fäder uti Davids, stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Men Ahasia regerade öfver Juda i ellofte årena Jorams, Achabs sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Och då Jehu kom till Jisreel, och Isebel det fick veta, färgade hon sitt ansigte, och beprydde sitt hufvud, och såg ut genom fenstret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Och då Jehu kom in igenom porten, sade hon: Är det Simri väl afgånget, som drap sin herra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Och han hof sitt ansigte upp till fenstret, och sade: Ho är här när mig? Då vände sig två eller tre kamererare till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Han sade: Störter henne utföre. Och de störte henne utföre, så att väggen och hästarna vordo stänkte med hennes blod; och hon vardt förtrampad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Och då han var inkommen, och hade ätit och druckit, sade han: Beser dock den förbannada, och begrafver henne; ty hon är en Konungs dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Då de nu gingo bort till att begrafva henne, funno de intet af henne, utan hufvudskallen och fötterna och flata händerna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Och kommo igen, och sade honom det. Han sade: Detta är nu det, som Herren genom sin tjenare Elia, den Thisbiten, talade, och sade: På Jisreels åker skola hundar äta Isebels kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Alltså vardt Isebels as såsom en träck på markene uppå Jisreels åker, så att man intet säga kunde: Detta är Isebel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Och Achab hade sjutio söner i Samarien; och Jehu skref bref, och sände till Samarien till de öfversta i Israels stad, till de äldsta, och Achabs förmyndare, hvilket så lydde:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'När detta bref kommer till eder, när hvilkom edars herras söner äro, hans vagnar, hästar, faste städer och rustning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Så ser till, hvilken bäst och likast är ibland edars herras söner, och sätter honom på hans faders stol, och strider för edars herras hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Men de fruktade sig ganska fast, och sade: Si, två Konungar hafva icke blifvit ståndande för honom; huru skulle vi då stå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Och de som voro öfver huset, och öfver staden, och de äldste, och förmyndarena, sände bort till Jehu, och läto säga honom: Vi äre dine tjenare, vi vilje göra allt det du säger oss; vi vilje ingen göra till Konung; gör hvad dig täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Då skref han ett annat bref till dem; det lydde alltså: Ären I mine, och lyden mine röst, så tager hufvuden af de män edars herras söner, och förer dem i morgon bittida till mig i Jisreel. Och Konungssönerna voro sjutio män, och de ypperste i staden uppfödde dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Då nu brefvet kom till dem, togo de Konungssönerna, och dråpo sjutio män, och lade deras hufvud i korgar, och sände dem till honom i Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Och då bådet kom, och bådade honom det, och sade: De hafva fört hit Konungssönernas hufvud; sade han: Lägger dem i två hopar för stadsporten, intill morgons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Och om morgonen, när han utgick, trädde han dit, och sade till allt folket: Ären I rättvise? Si, hafver jag gjort ett förbund emot min herra, och dräpit honom; ho hafver då slagit alla dessa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Så må I ju se, att intet Herrans ord är på jordena fallet, som Herren talat hafver emot Achabs hus; och Herren hafver gjort såsom han talat hafver genom sin tjenare Elia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Alltså slog Jehu alla dem som qvare voro af Achabs hus i Jisreel, alla hans yppersta, hans vänner, och hans Prester, tilldess icke en var qvar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Och stod upp, och drog bort till Samarien. Men i vägen var ett herdahus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Der råkade Jehu vid Ahasia, Juda Konungs, bröder, och sade: Ho ären I? De sade: Vi äre Ahasia bröder, och drage ned till att helsa Konungens barn, och Drottningenes barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Han sade: Griper dem lefvande. Och de grepo dem lefvande, och dråpo dem vid brunnen när herdahuset, två och fyratio män; och lät icke en af dem slippa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Och då han drog dädan, fann han Jonadab, Rechabs son, den honom mötte, och helsade honom, och sade till honom: Är ditt hjerta rätt, såsom mitt hjerta med dino hjerta? Jonadab sade: Ja. Är det så, sade han, så räck mig dina hand. Och han räckte honom sina hand; och han lät honom sitta uppe när sig på vagnen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Och sade: Kom med mig, och se mitt nit om Herran. Och de förde honom med honom på hans vagn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Då han kom till Samarien, slog han allt det som qvart var af Achab i Samarien, tilldess han förgjorde honom, efter Herrans ord, som han till Elia talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Och Jehu församlade allt folket, och lät säga till dem: Achab hafver fögo tjent Baal; Jehu vill bättre tjena honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Så låt nu kalla alla Baals Propheter, alla hans tjenare, och alla hans Prester, till mig, så att ingen är borto; förty jag hafver ett stort offer till att göra Baal; hvilken borto är, den skall icke lefva. Men Jehu gjorde detta med listighet, att han måtte förgöra Baals tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Och Jehu sade: Helger Baal ena högtid, och låter den utropa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Och sände Jehu i hela Israel, och lät komma alla Baals tjenare, så att ingen qvar var, som icke kom. Och de kommo i Baals hus; så att Baals hus vardt fullt i all rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Då sade han till dem, som voro öfver klädehuset: Bärer ut kläder för alla Baals tjenare. Och de båro kläder ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Och Jehu gick in uti Baals hus med Jonadab, Rechabs son, och sade till Baals tjenare: Ransaker, och ser till, att ingen Herrans tjenare är ibland eder, utan Baals tjenare allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Och som de kommo in till att göra offer och bränneoffer, beställde Jehu sig åttatio män utanföre, och sade: Ho som släpper någon af männerna, som jag får under edra händer, hans själ skall vara för hans själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'När nu bränneoffret fullkomnadt var, sade Jehu till drabanterna och höfvitsmännerna: Går in, och slår dem allasamman; låter ingen komma derut. Och de slogo dem med svärdsegg, och drabanterna och höfvitsmännerna hofvo dem bort. Och de gingo till Baals hus stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Och togo ut de stodar i Baals hus, och brände dem upp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Och slogo sönder Baals stodar, samt med Baals hus; och gjorde der ett hemligt hus af, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Alltså förgjorde Jehu Baal utur Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Men ifrå Jerobeams, Nebats sons, synder, den Israel kom till att synda, gick Jehu icke, och öfvergaf icke de guldkalfvar i BethEl och i Dan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Och Herren sade till Jehu: Derföre, att du hafver viljog varit till att göra min vilja, och hafver gjort på Achabs hus allt det i mino hjerta var, skola dina söner sitta dig på Israel stol intill fjerde led.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Dock höll icke Jehu, att han i Herrans Israels Guds lag vandrade af allo hjerta; ty han trädde icke ifrå Jerobeams synder, som kom Israel till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'På den tiden begynte Herren ledas vid Israel; ty Hasael slog dem i alla Israels gränsor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Ifrå Jordan österut, och hela Gilead, de Gaditers, Rubeniters, och Manassiters land, ifrån Aroer, som ligger när den bäcken vid Arnon; och Gilead, och Basan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Hvad nu mer af Jehu sägande är, och allt det han gjort hafver, och all hans magt, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Och Jehu afsomnade med sina fäder; och de begrofvo honom i Samarien; och Joahas hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Men tiden, som Jehu öfver Israel regerade i Samarien, är åtta och tjugu år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Men Athalja, Ahasia moder, då hon såg, att hennes son var död, stod hon upp, och förgjorde all Konungslig säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Men Joseba, Konung Jorams dotter, Ahasia syster, tog Joas, Ahasia son, och stal honom ifrå Konungsbarnen, som dräpne vordo, med hans ammo i sängkammarenom, och hon förgömde honom för Athalja, så att han icke vardt dräpen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Och han vardt undstungen med henne i Herrans hus i sex år; och Athalja var rådandes i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Uti sjunde årena sände Presten Jojada bort, och tog till sig de öfversta öfver hundrade, med höfvitsmännerna och drabanterna, och lät komma dem till sig i Herrans hus, och gjorde ett förbund med dem, och tog en ed af dem i Herrans hus, och viste dem Konungens son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Och böd dem, och sade: Detta är det I göra skolen; tredjeparten af eder, hvilkens skifte om Sabbathsdagen uppå går, skolen hålla vakt i Konungshusena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Och en tredjepart skall vara vid den porten Sur; och en tredjepart skall vara vid den porten, som är bak drabanterna; och skolen hålla vakt för Massa hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Men två parter af eder allom, I som om Sabbathsdagen afgån, skolen vakta i Herrans hus när Konungen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Och skolen ställa eder rundt omkring Konungen, och hvar och en med sine värjo i handene; och ho som kommer in emellan väggarna, han skall dö; så att I ären när Konungen, då han ut och in går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Och de öfverste öfver hundrade gjorde allt det Presten Jojada dem budit hade; och togo sina män till sig, som på Sabbathsdagen uppå gingo, med de som på Sabbathsdagen af gingo, och kommo till Presten Jojada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Och Presten fick höfvitsmännerna spetsar, och sköldar, som hade varit Konung Davids, och voro i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Och drabanterna stodo omkring Konungen, hvar och en med sine värjo i handene; ifrå husens hörn på högra sidone, allt intill det hörnet på den venstra, intill altaret, och till huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Och han lät Konungens son komma fram, och satte ena krono på honom, och tog vittnesbördet, och gjorde honom till Konung, och voro glade, och klappade händerna tillhopa, och sade: Lycka ske Konungenom!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Och då Athalja fick höra ropet af folket, som lopp dertill, kom hon ut till folket i Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Och såg till, si, då stod Konungen invid stodena, såsom sedvänja var, och sångare och trummetare när Konungenom; och allt folket i landena var gladt, och blåste med trummeter. Då ref Athalja sin kläder, och sade: Uppror, uppror.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Men Presten Jojada böd de öfversta öfver hundrade, som voro satte öfver hären, och sade till dem: Hafver henne utu huset i gården; och om någor följer henne, han dräpes med svärd; ty Presten hade sagt, att hon icke skulle dö i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Och de båro händerna på henne, och hon gick in på den vägen, som hästarna till Konungshuset gå, och vardt der dräpen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Så gjorde Jojada ett förbund emellan Herran, och Konungen, och folket, att de skulle vara Herrans folk; desslikes ock emellan Konungen och folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Då gick allt folket i landena in uti Baals hus, och bröto hans altare ned; och sönderslogo hans beläte allt grant, och Matthan, Baals Prest, slogo de ihjäl inför altaret; och Presten beställde ämbeten uti Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Och tog de öfversta öfver hundrade, och de höfvitsmän och de drabanter, och allt folket i landena, och förde Konungen ned ifrå Herrans hus, och kommo den vägen ifrå drabantaporten intill Konungshuset; och han satte sig på Konungsstolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Och allt folket i landet var gladt, och staden vardt stilla. Men Athalja dråpo de med svärd i Konungshuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Och Joas var sju år gammal, då han vardt Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Uti sjunde årena Jehu vardt Joas Konung, och regerade i fyratio år i Jerusalem; hans moder het Zibja, af BerSeba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Och Joas gjorde det rätt var, och det Herranom väl behagade, så länge Presten Jojada lärde honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Undantagno, att han icke bortlade höjderna; ty folket offrade och rökte ännu på höjderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Och Joas sade till Presterna: Alla de penningar, som dertill helgade varda, att de skola läggas till Herrans hus, nämliga de penningar, som hvar och en gifver i skatt, och de penningar, som hvar och en löser sina själ med, och alla de penningar, som hvar och en offrar af fritt hjerta, dertill att det skall läggas till Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Det låter Presterna taga till sig, hvardera sin del; dermed skola de bota hvad som förfaller på (Herrans) hus, ehvar de finna att det förfallet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Då nu Presterna, allt intill tredje och tjugonde året Konungs Joas, icke botade hvad som förfallet var i husena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Kallade Konung Joas Presten Jojada, samt med Presterna, och sade till dem: Hvi boten I icke hvad som förfaller i husena? Så skolen I nu icke taga de penningar till eder, hvar och en sin del; utan skolen låta kommat till det, som förfallet är i husena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Och Presterna samtyckte inga penningar vilja taga af folkena, till att bota det förfallet var af huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Då tog Presten Jojada ena kisto, och gjorde der ett hål ofvanuppå, och satte henne på högra sidon vid altaret, der man ingår i Herrans hus. Och Presterna, som vakt höllo för dörrene, läto komma alla penningar deruti, som till Herrans hus fördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'När de nu sågo, att många penningar voro i kistone, så kom Konungens skrifvare upp, och öfverste Presten, och bundo penningarna tillhopa, och räknade hvad till Herrans hus funnet vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Och man gaf penningarna redo i handena dem som arbetade, och skickade voro till Herrans hus; och de gåfvo dem ut timbermannom, som byggde och arbetade på Herrans huse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Nämliga murmästarom, och stenhuggarom, och dem som trä och huggna stenar köpte: på det att det förfallna på Herrans hus måtte botadt varda, och hvad som helst de funno af nödene vara att botas skulle på huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Dock lät man icke göra silfskålar, bägare, bäcken, trummeter, eller något gyldene eller silfvertyg i Herrans hus, af de penningar, som till Herrans hus förde voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Utan man gaf dem arbetarena, att de dermed botade det förfallna på Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Och behöfde de män ingen räkenskap göra, som man fick penningarna, till att utgifva dem arbetarena; utan de handlade på sina tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Men de penningar af skuldoffer och syndoffer vordo icke förde uti Herrans hus; förty de voro Presternas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'På den tiden drog Hasael, Konungen i Syrien, upp, och stridde emot Gath, och vann det. Och då Hasael ställde sitt ansigte till att draga upp till Jerusalem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Tog Joas, Juda Konung, allt det helgada, som hans fader; Josaphat, Joram och Ahasia, Juda Konungar, helgat hade, och det han helgat hade; dertill allt det guld, som man fann i Herrans hus skatt, och i Konungshusena, och sände det till Hasael, Konungen i Syrien. Sedan drog han sina färde ifrå Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Hvad nu mer af Joas sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Och hans tjenare hofvo sig upp, och gjorde ett förbund, och slogo honom i Millo hus, der man nedergår till Silla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Ty Josachar, Simeaths son, och Josabad, Somers son, hans tjenare, slogo honom ihjäl; och man begrof honom med hans fäder uti Davids stad. Och Amazia hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Uti tredje och tjugonde årena Joas, Ahasia sons, Juda Konungs, vardt Joahas, Jehu son, Konung öfver Israel i Samarien, sjutton år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Och han gjorde det ondt var för Herranom, och vandrade efter Jerobeams synder, Nebats sons, hvilken Israel kom till att synda; och öfvergaf det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Och Herrans vrede förgrymmade sig öfver Israel, och gaf dem under Hasaels hand, Konungens i Syrien, och i Benhadads, Hasaels sons, hand, i deras lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Men Joahas bad Herrans ansigte, och Herren hörde honom; ty han såg på Israels jämmer, som Konungen i Syrien dem gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Och Herren gaf Israel en frälsare, som dem förde utu de Syrers våld; så att Israels barn bodde uti sina hyddor, såsom tillförene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Dock öfvergåfvo de icke Jerobeams hus synder, hvilken Israel kom till att synda, utan vandrade derutinnan; och den lunden i Samarien blef ståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Förty af Joahas folk var icke mer qvart blifvet, än femtio resenärer, tio vagnar, och tiotusend fotfolk; ty Konungen i Syrien hade slagit dem ihjäl, och gjort dem såsom tröskestoft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Hvad nu mer af Joahas sägandes är, och allt det han gjort hafver, och hans magt, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Och Joahas afsomnade med sina fäder, och man begrof honom i Samarien; och hans son Joas vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Uti sjunde och tretionde årena Joas, Juda Konungs, vardt Joas, Joahas son, Konung öfver Israel i Samarien, sexton år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Och gjorde det ondt var för Herranom, och öfvergaf icke alla Jerobeams, Nebats sons, synder, den Israel kom till att synda; utan vandrade derutinnan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Hvad nu mer af Joas sägandes är, och hvad han gjort hafver, och hans magt, huru han med Amazia, Juda Konung, stridt hafver, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Och Joas afsomnade med sina fader; och Jerobeam satt på hans stol. Men Joas vardt begrafven i Samarien när de Israels Konungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Då vardt Elisa krank, der han ock af död blef; och Joas, Israels Konung, kom ned till honom, och gret för honom, och sade: Min fader, min fader, Israels vagn, och hans resenärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elisa sade till honom: Tag bågan och pilarna. Och då han tog bågan och pilarna,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Sade han till Israels Konung: Bänd bågan med dine hand. Och han bände med sine hand. Och Elisa lade sina hand på Konungens hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Och sade: Låt upp fenstret österut; och han lät det upp. Och Elisa sade: Skjut; och han sköt. Han sade: En salighetspil af Herranom, en salighetspil emot de Syrer; och du skall slå de Syrer i Aphek, tilldess de blifva ändade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Och han sade: Tag pilarna. Och då han tog dem, sade han till Israels Konung: Slå på jordena. Och han slog tre gånger, och höll upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Då vardt Guds mannen vred på honom, och sade: Hade du slagit fem eller sex gånger, så skulle du hafva slagit de Syrer, tilldess du hade gjort en ända på dem; men nu skall du slå dem tre gånger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Då nu Elisa var död, och man hade begrafvit honom, föllo de Moabiters krigsfolk in uti landet på samma året.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Och det begaf sig, att de begrofvo en man; och som de fingo se krigsfolket, kastade de mannen uti Elisa graf; och då han kom vid Elisa ben, vardt han lefvandes, och stod upp på sina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Alltså tvingade nu Hasael, Konungen i Syrien, Israel, så länge Joahas lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Men Herren gjorde nåd med dem, och förbarmade sig öfver dem, och vände sig till dem för sitt förbunds skull med Abraham, Isaac och Jacob, och ville, icke förderfva dem; och förkastade dem icke heller ifrå sitt ansigte allt härtill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Och Hasael, Konungen i Syrien, blef död; och hans son Benhadad vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Men Joas vände om, och tog de städer igen utu Benhadads, Hasaels sons, hand, som han utu hans faders Joahas hand med strid tagit hade. Tre gånger slog Joas honom, och fick Israels städer igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Uti andro årena Joas, Joahas sons, Israels Konungs, vardt Amazia Konung, Joas, Juda. Konungs, son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Fem och tjugu åra gammal var han, då han vardt Konung; och regerade nio och tjugu år i Jerusalem; hans moder het Joaddan af Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Och han gjorde det Herranom väl behagade; dock icke såsom hans fader David, utan såsom hans fader Joas gjort hade, så gjorde han ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Ty höjderna vordo icke aflagda; utan folket offrade och rökte ännu på höjderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Då han nu var mägtig vorden i riket, slog han sina tjenare, som Konungen hans fader dräpit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Men dråparenas barn drap han icke; såsom ock skrifvet är i Mose lagbok, der Herren budit hade, och sagt: Fäderna skola icke dö för barnens skull, och barnen skola icke dö för fädernas skull; utan hvar och en skall dö för sina synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Han slog desslikes de Edomeer i saltdalenom, tiotusend, och vann den staden Sela med strid; och kallade honom Joktheel, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Då sände Amazia båd till Joas, Joahas son, Jehu sons, Israels Konung, och lät säga honom: Kom hit, och låt oss se hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Men Joas, Israels Konung, sände till Amazia, Juda Konung, och lät säga honom: Törnebusken, som i Libanon är, sände till cedreträt i Libanon, och sade: Gif dina dotter minom son till hustru; men vilddjuret på markene i Libanon lopp öfver törnebuskan, och förtrampade honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Du hafver slagit de Edomeer, deraf förhäfver sig ditt hjerta; behåll den prisen, och blif hemma; hvi söker du efter olycko, att du må falla, och Juda med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Men Amazia hörde honom intet. Så drog Joas, Israels Konung, upp; och de besågo hvarannan, han och Amazia, Juda Konung, i BethSemes, som i Juda ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Men Juda vardt slagen för Israel, så att hvar och en flydde i sina hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Och Joas, Israels Konung, grep Amazia, Juda Konung, Joas son, Ahasia sons, i BethSemes; och kom till Jerusalem, och ref omkull, murarna i, Jerusalem, ifrån Ephraims port, allt intill hörnporten, fyrahundrad alnar långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Och tog allt det guld och silfver, och tyg, som funnet vardt i Herrans hus, och i Konungshusens fatebur, dertill barnen, till pant; och drog åter till Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Hvad nu mer af Joas sägande är, det han gjort hafver, och hans magt, och huru han med Amazia, Juda Konung, stridde, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Och Joas afsomnade med sina fader, och vardt begrafven i Samarien ibland Israels Konungar; och hans son Jerobeam vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Men Amazia. Joas son, Juda Konungs, lefde efter Joas död, Joahas sons, Israels Konungs, i femton år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Hvad nu mer af Amazia sägandes är, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Och de gjorde ett förbund emot honom i Jerusalem; men han flydde till Lachis. Och de sände efter honom till Lachis, och dråpo honom der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Och de förde honom dädan på hästar; och han vardt begrafven i Jerusalem, när sina fäder uti Davids stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Och hela Juda folk togo Asaria, uti lians sextonde äre, och gjorde honom till Konung i hans faders Amazia stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Han byggde Elath, och fick det igen under Juda, sedan Konungen med hans fäder afsomnad var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Uti femtonde årena Amazia, Joas sons, Juda Konungs, vardt Jerobeam, Joas son, Konung öfver Israel i Samarien, ett och fyratio år,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Och gjorde det ondt varför Herranom, och öfvergaf icke alla Jerobeams, Nebats sons, synder, den Israel kom till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Men han tog igen Israels gränsor, ifrå Hamath allt intill hafvet, som ligger i hedmarkene, efter Herrans Israels Guds ord, som han sagt hade genom, sin tjenare Propheten Jona, Amitthai son, som var af GathHepher.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Ty Herren såg till Israels svåra jämmer, så att ock de innelyckte och igenlefde förgingos; och ingen hjelpare var i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Och Herren hade icke sagt, att han ville utskrapa Israels namn under himmelen; utan halp dem genom Jerobeam, Joas son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Hvad nu mer af Jerobeam sägandes är, och allt det han gjort hafver, och hans magt, huru han stridt hafver, och huru han igenfick Damascon och Hamath till Juda i Israel, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Och Jerobeam afsomnade med sina fäder, Israels Konungar; och hans son Zacharia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Uti sjunde och tjugonde årena Jerobeams, Israels Konungs, vardt Asaria Konung, Amazia son, Juda Konungs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Och var sexton åra gammal, då han Konung vardt, och regerade tu och femtio år i Jerusalem; hans moder het Jecholia af Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Och han gjorde det Herranom väl behagade, alldeles såsom hans fader Amazia;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Undantagno, att de icke bortlade höjderna; ty folket offrade och rökte ännu på höjderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Men Herren plågade Konungen, så att han var spitelsk allt intill döden, och bodde uti ett fritt hus; men Jotham, Konungens son, regerade huset, och dömde folket i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Hvad nu mer af Asaria sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Och Asaria afsomnade med sina fäder, och man begrof honom när sina fäder uti Davids stad; och hans son Jotham vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Uti åttonde och tretionde årena Asaria, Juda Konungs, vardt Zacharia, Jerobeams son, Konung öfver Israel i Samarien, i sex månader;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Och gjorde det ondt var för Herranom, såsom hans fäder gjort hade. Han vände icke igen ifrå Jerobeams synder, Nebats sons, den Israel kom till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Och Sallum, Jabes son, gjorde ett förbund emot honom, och slog honom för folkena, och drap honom; och vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Hvad mer af Zacharia sägandes är, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Och det är det som Herren till Jehu talat hade, sägandes: Din barn skola sitta på Israels stol, allt intill fjerde led. Och det skedde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, Jabes son, vardt Konung uti nionde och tretionde årena Usia, Juda Konungs, och regerade en månad i Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Ty Menahem, Gadi son, drog upp ifrå Thirza, och kom till Samarien, och slog Sallum, Jabes son, i Samarien, och drap honom; och vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Hvad nu mer af Sallum sägandes är, och om hans förbund, som han gjorde, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'På den tiden slog Menahem Thiphsah, med alla de som derinne voro, och dess gränsor, allt ifrå Thirza; derföre att de icke ville låta honom in; och slog alla deras hafvande qvinnor, och sönderref dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Uti nionde och tretionde årena Asaria, Juda Konungs, vardt Menahem, Gadi son, Konung öfver Israel i tio år, i Samarien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Och gjorde det ondt var för Herranom, och öfvergaf icke i sin lifstid Jerobeams synder, Nebats sons, den Israel kom till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Och Phul, Konungen i Assyrien, kom i landet; och Menahem gaf Phul tusende centener silfver, på det han skulle hålla med honom, och befästa honom i rikena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Och Menahem lade en skatt i Israel uppå de rikesta, femtio siklar silfver på hvar man, att han skulle gifva det Konungenom i Assyrien. Alltså drog Konungen af Assyrien hem igen, och blef icke i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Hvad nu mer af Menahem sägandes är, och allt det han gjort hafver, si, det är skrifvet i Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Och Menahem afsomnade med sina fader; och Pekahia hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Uti femtionde årena Asaria, Juda Konungs, vardt Pekahia, Menahems son, Konung öfver Israel i Samarien, i tu år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Och gjorde det ondt var för Herranom; ty han vände icke åter af Jerobeams, Nebats sons, synder, den Israel kom till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Och Pekah, Remalia son, hans riddare, gjorde ett förbund emot honom, och slog honom i Samarien, uti Konungshusets palats, med Argob, och Arie, och femtio män med honom af Gileads barn; och drap honom, och vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Hvad mer af Pekahia; sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Uti andra och femtionde årena Asaria, Juda Konungs, vardt Pekah, Remalia son, Konung öfver Israel i Samarien i tjugu år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Och gjorde det ondt var för Herranom; ty han vände icke åter af Jerobeams synder, Nebats sons, den Israel kom till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Uti Pekah, Israels Konungs, tid kom ThiglathPileser, Konungen i Assyrien, och tog Ijon, AbelBethMaacha, Janoha, Kedes, Hazor, Gilead, Galilea och hela Naphthali land, och förde dem bort i Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Och Hosea, Ela son, gjorde ett förbund emot Pekah, Remalia son, och slog honom ihjäl, och vardt Konung i hans stad, uti tjugonde årena Jothams, Usia sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Hvad nu mer af Pekah sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Israels Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Uti andra årena Pekah, Remalia sons, Israels Konungs, vardt Jotham Konung, Usia son, Juda Konungs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Och var fem och tjugu åra gammal, då han Konung vardt, och regerade i sexton år i Jerusalem; hans moder het Jerusa, Zadoks dotter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Och gjorde det Herranom väl behagade, alldeles såsom hans fader Usia gjort hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Undantagno, att han icke bortlade höjderna; ty folket offrade och rökte ännu på höjderna. Han byggde den höga porten på Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Hvad nu mer af Jotham sägandes är, och allt det han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'I den tiden begynte Herren sända till Juda Rezin, Konungen i Syrien, och Pekah, Remalia son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Och Jotham afsomnade med sina fäder, och vardt begrafven när sina fäder, uti sins faders Davids stad; och Ahas hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Uti sjuttonde årena Pekah, Remalia sons, vardt Ahas Konung, Jothams, Juda Konungs, son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Tjugu åra gammal var Ahas, då han vardt Konung, och regerade sexton år i Jerusalem, och gjorde intet det Herranom hans Gud behagade, såsom hans fader David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Ty han vandrade på Israels Konungars väg; dertill lät han sin son gå igenom eld, efter de Hedningars styggelse, hvilka Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Och han gjorde offer, och rökte på höjderna, och på alla backar, och under all grön trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'På den tiden drog Rezin, Konungen i Syrien, och Pekah, Remalia son, Israels Konung, upp till Jerusalem till att strida, och belade Ahas; men de kunde icke vinna det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'På samma tiden fick Rezin, Konungen i Syrien, Elath igen till Syrien, och dref Judarna utur Elath. Och de Syrier kommo, och bodde deruti, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Men Ahas sände båd till Thiglath Pileser, Konungen i Assyrien, och lät säga honom: Jag är din tjenare, och din son. Kom hitupp, och hjelp mig utu Konungens hand i Syrien, och Israels Konungs, hvilka sig emot mig upprest hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Och Ahas tog det silfver och guld, som i Herrans huse och uti Konungshusens fatebur funnet vardt, och sände Konungenom i Assyrien skänker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Och Konungen i Assyrien hörde honom; och drog upp till Damascon, och vann det; och förde dem bort till Kir, och drap Rezin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Och Konung Ahas drog emot ThiglathPileser, Konungen i Assyrien, till Damascon. Och då han såg ett altare, som i Damascon var, sände Konung Ahas ett mönster och en efterliknelse till Presten Uria, såsom det gjordt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Och Uria Presten byggde ett altare, och gjorde det efter det, som Konung Ahas honom sändt hade ifrå Damascon, tilldess Konung Ahas kom ifrå Damascon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Och då Konungen kom ifrå Damascon och såg altaret, offrade han deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Och upptände deruppå sitt bränneoffer, och spisoffer, och göt deruppå sitt drickoffer; och blodet af tackoffrena, som han offrade, lät han stänka på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Men det kopparaltaret, som för Herranom stod, tog han bort, så att det icke skulle stå emellan altaret och Herrans hus; utan satte det utmed sidona vid altaret norrut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Och Konung Ahas böd Prestenom Uria, och sade: På det stora altaret skall du upptända bränneoffer om morgonen, och spisoffer om aftonen, och Konungens bränneoffer, och hans spisoffer, och allt folkens bränneoffer i landena, samt med deras spisoffer, och drickoffer; och allt blodet af bränneoffret, och af allo andro offer skall du stänka deruppå; men om kopparaltaret vill jag vara förtänkt hvad jag göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Presten Uria gjorde allt det Konung Ahas befallde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Och Konung Ahas bröt bort sidorna af stolarna, och hof bort kettlarna deraf, och hafvet hof han utaf de kopparoxar, som voro derunder, och satte det uppå stengolfvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Dertill Sabbathspredikostolen, den de i husena byggt hade. Och Konungsgången utantill vände han i Herrans hus, för Konungens skull i Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Hvad nu mer af Ahas sägandes är? hvad han gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Och Ahas afsomnade med sina fäder, och vardt begrafven när sina fäder uti Davids stad; och Hiskia hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Uti tolfte årena Ahas, Juda Konungs, vardt Hosea, Ela son, Konung öfver Israel i Samarien, i nio år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Och gjorde det ondt var för Herranom, dock icke såsom de Israels Konungar, som för honom voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Emot honom drog upp Salmanasser, Konungen i Assyrien och Hosea vardt honom undergifven, så att han gaf honom skänker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Då Konungen i Assyrien fick veta, att Hosea hade ett förbund för händer, och hade sändt båd till So, Konungen i Egypten, och icke utgifva ville årliga skänkerna Konungenom i Assyrien; belade han honom, och kastade honom i fängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Och Konungen i Assyrien drog in i hela landet, och till Samarien, och belade det i tre år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Och uti nionde årena Hosea vann Konungen i Assyrien Samarien, och förde Israel bort i Assyrien, och satte dem i Halah, och i Habor vid den älfven Gosan, och uti de Meders städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Ty då Israels barn syndade emot Herran deras Gud, den dem utur Egypti land fört hade, utu Pharaos hand, Konungens i Egypten, och fruktade andra gudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Och vandrade efter Hedningarnas seder, hvilka Herren för Israels barn fördrifvit hade, och såsom Israels Konungar gjort hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Och skickade sig icke tillbörliga för Herranom sinom Gud; och byggde sig höjder i alla städer, både på slott och i fasta städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Och uppreste stodar och lundar på alla backar, och under all grön trä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Och rökte der på alla höjder, lika såsom Hedningarna, hvilka Herren för dem fördrifvit hade; och bedrefvo slem stycke, dermed de förtörnade Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Och tjente afgudar, om hvilka Herren dem sagt hade: Detta skolen I icke göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Och då Herren betygade i Israel och Juda, genom alla Propheter och Siare, och lät säga dem: Vänder om utaf edra onda vägar, och håller min bud och rätter, efter all de lag som jag edra fäder budit hafver, och jag genom mina tjenare Propheterna till eder sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Men de lydde intet, utan gjorde sig hårdnackade, såsom ock deras fäder gjort hade, hvilke icke trodde på Herran deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Dertill föraktade de hans bud, och hans förbund som han med deras fäder gjort hade, och hans vittnesbörd som han ibland dem gjort hade, och vandrade efter deras fåfängelighet, och vordo fåfängelige såsom Hedningarna, som omkring dem voro, om hvilka Herren dem budit hade, att de icke skulle göra såsom de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Men de öfvergåfvo all Herrans deras Guds bud, och gjorde sig två gjutna kalfvar, och lundar; och tillbådo allan himmelens här, och tjente Baal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Och läto sina söner och döttrar gå igenom eld, och foro med spådom och trolldom; och gåfvo sig till att göra det ondt var för Herranom, till att förtörna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Så vardt Herren ganska vred på Israel, och kastade dem bort ifrå sitt ansigte; så att intet blef qvart, utan Juda slägt allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Dertill höll icke heller Juda Herrans sins Guds bud, utan vandrade efter Israels seder, som de gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Derföre förkastade Herren all Israels säd, och plågade dem; och gaf dem i röfvarehänder, tilldess han kastade dem ifrå sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Förty Israel vardt söndrad ifrå Davids hus, och hade gjort sig Jerobeam, Nebats son, till Konung. Han vände Israel ifrå Herranom, och gjorde det så, att de svårliga syndade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Alltså vandrade Israels barn uti alla Jerobeams synder, som han hade åstadkommit, och icke återvände deraf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Intilldess Herren kastade Israel ifrå sitt ansigte, såsom han igenom alla sina tjenare Propheterna sagt hade. Så vardt då Israel bortförd utu sitt land in uti Assyrien, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Och Konungen af Assyrien lät komma folk af Babel, af Cutha, af Ava, af Hamath och Sepharvaim, och besatte de städer i Samarien uti Israels barnas stad; och de togo Samarien in, och bodde uti dess städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Men som de då begynte att bo der, och fruktade intet Herran, sände Herren lejon ibland dem, som slogo dem ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Och de läto säga Konungenom i Assyrien: De Hedningar, som du hafver låtit komma hit, och besatt med de städer i Samarien, veta intet af landsens Guds seder; derföre hafver han sändt lejon ibland dem, och si, de dräpa dem, efter de icke veta utaf landsens Guds seder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Konungen i Assyrien böd, och sade: Förer dit en af Presterna, som dädan bortförde äro; han fare dit, och bo der; och han läre dem landsens Guds seder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Så kom en af Presterna, som af Samarien bortförde voro, och satte sig i BethEl, och lärde dem, huru de skulle frukta Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Men hvart och ett folk gjorde sig sin gud, och satte dem uti de höjders hus, som de Samariter gjorde, hvart och ett folk uti sina städer, der de bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'De af Babel gjorde SuccothBenoth; de af Cuth gjorde Nergal; de af Hamath gjorde Asima;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'De af Ava gjorde Nibhas och Thartak; de af Sepharvaim brände upp sina söner Adrammelech och Anammelech, Sepharvaims gudom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Och efter de ock fruktade Herran, gjorde de honom Prester på höjderna utaf de ringesta ibland dem, och satte dem i höjdernas hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Alltså fruktade de Herran, och tjente likväl af gudomen, efter hvars folkens sed, dädan de förde voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Och intill denna dag göra de efter det gamla sättet, att de hvarken frukta Herran, eller göra hans seder och rätter, efter de lag och bud, som Herren Jacobs barn budit hafver, hvilkom han det namnet Israel gaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Och gjorde Herren ett förbund med dem, och böd dem, och sade: Frukter inga andra gudar, och tillbeder dem icke, och tjener dem icke, och offrer dem icke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Utan Herranom, som eder utur Egypti land fört hafver, med stora magt och uträcktom arm, honom frukter, honom tillbeder, och offrer honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Och håller de seder, rätter, lag och bud, som han eder hafver skrifva låtit; att I alltid gören derefter, och icke frukten andra gudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Och förgäter icke det förbund, som han med eder gjort hafver, att I icke frukten andra gudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Utan frukter Herran edar Gud; han varder eder hjelpandes ifrån alla edra fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Men desse lydde icke, utan gjorde efter sin förra sed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Alltså fruktade desse Hedningarna Herran, och tjente likväl sina gudar. Sammalunda gjorde ock deras barn och barnabarn, såsom deras fäder gjort hade, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Uti tredje årena Hosea, Ela sons, Israels Konungs, vardt Hiskia Konung, Ahas son, Juda Konungs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Och var fem och tjugu åra gammal, då han vardt Konung, och regerade nio och tjugu år i Jerusalem; hans moder het Abi, Zacharia dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Och han gjorde det godt var för Herranom, såsom hans fader David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Han lade bort de höjder, och bröt omkull stodarna, och utrotade lundarna, och slog sönder den kopparormen, som Mose gjort hade; ty allt intill den tiden hade Israels barn rökt för honom, och han kallade honom Nehusthan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Han förtröste på Herran Israels Gud, så att ingen hans like var efter honom, ej heller för honom, ibland alla Juda Konungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Han höll sig intill Herran, och trädde icke ifrå honom, och höll hans bud, som Herren hade budit Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Och Herren var med honom, och hvart han utdrog, handlade han visliga. Dertill föll han af ifrå Konungen i Assyrien, och var honom icke underdånig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Han slog ock de Philisteer, allt intill Gasa, och deras gränsor, både slott och fasta städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Uti fjerde årena Hiskia, Juda Konungs, det var sjunde året Hosea, Ela sons, Israels Konungs, då drog Salmanasser, Konungen i Assyrien, upp emot Samarien, och belade det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Och vann det efter tre år, uti sjette Hiskia åre, det är, uti nionde årena Hosea, Israels Konungs, så vardt Samarien vunnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Och Konungen af Assyrien förde Israel bort till Assyrien, och satte dem i Halah och Habor, vid den älfven Gosan, och uti de Meders städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Derföre, att de icke lydt hade Herrans sins Guds röst, och hade öfverträdt hans förbund; och allt det Mose Herrans tjenare budit hade, det hade de intet lydt, eller gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Men uti fjortonde årena Konungs Hiskia, drog upp Sanherib, Konungen i Assyrien, emot alla fasta städer i Juda, och tog dem in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Då sände Hiskia, Juda Konung, till Konungen af Assyrien i Lachis, och lät säga honom: Jag hafver syndat, vänd om ifrå mig; hvad du lägger mig uppå, det vill jag draga. Så lade Konungen af Assyrien på Hiskia, Juda Konung, trehundrad centener silfver, och tretio centener guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Alltså gaf Hiskia ut allt det silfver, som i Herrans hus, och i Konungshusets drätsel funnet vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'På den samma tiden slog Hiskia, Juda Konung, sönder dörrarna af Herrans tempel, och de skifvor, som han sjelf hade låtit bedraga dem med, och fick dem Konungenom af Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Och Konungen af Assyrien sände Tharthan, och öfversta kamereraren, och RabSake ifrå Lachis, till Konung Hiskia med stora magt till Jerusalem, och de drogo upp; och då de kommo, höllo de vid vattugrafvena af öfversta dammen, som ligger vid den vägen på valkareåkrenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Och de kallade Konungen. Då kom ut till dem Eliakim, Hilkia son, hofmästaren, och Sebna skrifvaren, och Joah, Asaphs son, cancelleren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Och RabSake sade till dem: Käre, säger Konung Hiskia: Så säger den store Konungen, Konungen af Assyrien: Hvad är detta för en tröst, der du förlåter dig uppå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Menar du, att du hafver ännu råd och magt till att strida? Hvaruppå förlåter då du dig nu, att du äst affallen ifrå mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Si, förlåter du dig uppå den sönderbråkade rörstafven Egypten? Hvilken som stöder sig vid honom, honom varder han gångandes upp i handena, och genomstinger henne; alltså är Pharao, Konungen i Egypten, allom dem som förlåta sig på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Om I ock viljen säga till mig: Vi förlåte oss på Herran vår Gud; är icke han den, hvilkens höjder och altare Hiskia hafver aflagt, och sagt till Juda och Jerusalem: För detta altaret, som i Jerusalem är, skolen I tillbedja?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Så gör nu samman en hop minom herra, Konungenom af Assyrien, så vill jag få dig tutusend hästar; lät se, om du kan åstadkomma dem, som deruppå rida måga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Huru vill du då blifva ståndandes för en den minsta höfdingan, mins herras underdåna, om du förlåter dig uppå Egypten, för vagnars och resenärars skull?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Menar du, att jag utan Herrans vilja är hit uppdragen, till att förderfva denna staden? Herren hafver mig det befallt: Drag upp i detta landet, och förderfva det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Då sade Eliakim, Hilkia son, och Sebna, och Joah, till RabSake: Tala med dina tjenare på Syrisko, ty vi förstå det, och tala icke med oss på Judisko, för folkens öron, som på muren är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Men RabSake sade till dem: Hafver nu min herre sändt mig till din herra, eller till dig, att jag dessa orden säga skulle? Ja, till de män som sitta på muren, att de skulle äta sin egen träck med eder, och dricka sitt piss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Alltså stod RabSake, och ropade med höga röst på Judisko, talade, och sade: Hörer den stora Konungens röst, Konungens af Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Detta säger Konungen: Låter icke Hiskia bedraga eder; ty han förmår icke fria eder utu mine hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Och låter icke Hiskia förtrösta eder på Herran, så att han säger: Herren skall fria oss, och denne stad skall icke gifven varda i Konungens händer af Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Hörer icke Hiskia; ty så säger Konungen af Assyrien: Görer mig till vilja, och kommer ut till mig, så skall hvar och en äta af sitt vinträ, och af sitt fikonaträ, och dricka af sin brunn:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Intilldess jag kommer, och hemtar eder uti ett land, det edro lande likt är, der korn, must, bröd, vingårdar, oljoträ, olja och hannog uti är, så fån I lefva, och icke dö; hörer intet Hiskia, ty han förförer eder, då han säger: Herren varder oss hjelpandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Hafva ock Hedningarnas gudar hvar och en hulpit sitt land ifrå Konungens hand i Assyrien?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Hvar äro de gudar i Hamath och Arphad? Hvar äro de gudar i Sepharvaim, Hena och Iva? Hafva de ock hulpit Samarien utu mine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Hvar är en gud ibland alla lands gudar, som sitt land friat hafver utu mina hand, att Herren nu skall fria Jerusalem utu mina hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Då tigde folket, och svarade honom intet; ty Konungen hade budit, och sagt: Svarer honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Så kom då Eliakim, Hilkia son, hofmästaren, och Sebna skrifvaren, och Joah, Asaphs son, cancelleren, till Hiskia med rifven kläder, och gåfvo honom tillkänna RabSake ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Då Konung Hiskia det hörde, ref han sin kläder, och drog en säck uppå sig, och gick in uti Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Och sände Eliakim hofmästaren, och Sebna skrifvaren, samt med de äldsta Presterna, klädda i säcker, till Propheten Esaia, Amos son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Och de sade till honom: Så säger Hiskia: Denne dagen är en bedröfvelses, bannors och förhädelses dag; barnen äro komne till födslon; men ingen magt är till att föda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Om tilläfventyrs Herren din Gud ville höra all RabSake ord, hvilken hans Herre, Konungen i Assyrien, utsändt hafver, till att tala förhädelse emot lefvandes Gud; och till att bannas med de ord, som Herren din Gud hört hafver; så upphäf nu din bön för dem som ännu igenlefde äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Och Konungens Hiskia tjenare kommo till Esaia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Då sade Esaia till dem: Så säger edrom herra: Detta säger Herren: Frukta dig intet för de ord, som du hört hafver, der Konungens tjenare af Assyrien mig med förhädt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Si, jag vill gifva honom en anda, att han skall få höra ett rykte, och draga tillbaka igen i sitt land; och jag vill fälla honom med svärd i hans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Och då RabSake kom igen, fann han Konungen af Assyrien stridandes emot Libna; förty han hade hört, att han var dragen ifrå Lachis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Och han fick höra om Thirhaka, Konungen i Ethiopien: Si, han är utdragen till att strida emot dig. Då vände han om, och sände båd till Hiskia, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Detta säger Hiskia, Juda Konung: Låt icke din Gud bedraga dig, på hvilken du dig förlåter, och säger: Jerusalem varder icke gifvet uti Konungens hand i Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Si, du hafver hört, hvad Konungarna i Assyrien gjort hafva allom landom, och gifvit dem tillspillo; och du skulle nu friad varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Hafva ock Hedningarnas gudar friat dem, hvilka mine fäder förderfvat hafva; Gosan, Haran, Reseph, och Edens barn, som i Thelassar voro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Hvar är Konungen i Hamath, Konungen i Arphad, Konungen i den staden Sepharvaim, Hena och Iva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Då Hiskia hade anammat brefvet af båden, och läsit det, gick han upp i Herrans hus, och upplät det för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Och bad inför Herranom, och sade: Herre Israels Gud, som sitter öfver Cherubim, du äst allena Gud i all rike på jorden; du hafver gjort himmel och jord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Herre, böj din öron, och hör; Herre, upplåt din ögon och se; och hör Sanheribs ord, den hitsändt hafver, till att tala hädelse emot lefvandes Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Det är sant, Herre, Konungarna i Assyrien hafva med svärd förlagt Hedningarna, och deras land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Och hafva kastat deras gudar i elden; ty de voro icke gudar, utan menniskors handaverk, stock och sten; derföre hafva de förlagt dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Men nu, Herre vår Gud, hjelp oss utu hans hand, på det all rike på jordene skola förstå, att du, Herre, allena äst Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Så sände Esaia, Amos son, till Hiskia, och lät säga honom: Detta säger Herren Israels Gud: Hvad du af mig bedit hafver om Sanherib, Konungen i Assyrien, det hafver jag hört.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Detta är det Herren emot honom talat hafver: Jungfrun, dottren Zion, föraktar dig, och bespottar dig; dottren Jerusalem rister hufvudet efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Hvem hafver du försmädat och förhädt? Öfver hvem hafver du upphöjt dina röst? Du hafver upphäfvit dina ögon emot den Heliga i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Du hafver genom din sändningabåd försmädat Herran, och sagt: Jag hafver genom mina många vagnar stigit upp på bergshöjderna, uppå Libanons sido; jag hafver afhuggit dess höga ceder, och utvalda furor, och är kommen intill yttersta herberget, i hans Carmels skog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Jag hafver grafvit, och utdruckit de främmande vatten, och hafver med mitt fotabjelle uttorkat all förvarad vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Men hafver du icke hört, att jag detta långt tillförene gjort hafver, och af begynnelsen hafver jag beredt det? Men nu hafver jag det komma låtit, att faste städer skulle förfalla till en öde stenhop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Och de som deruti bodde, skulle varda vanmägtige, och rädas och skämmas, och varda såsom örter på markene, och som gröna gräset till hö på taken, hvilket förtorkas förr än det moget varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Jag vet din boning, din utgång och ingång; och att du rasar emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Så efter du rasar emot mig, och ditt högmod är uppkommet för min öron, så skall jag sätta en ring i dina näso, och ett bett i din mun, och skall föra dig den vägen hem igen, som du hit kommen äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Och detta skall vara dig ett tecken: Uti detta år ät hvad som förtrampadt är; uti de andro årena hvad sjelft växer; uti tredje årena sår och uppskärer, och planterer vingårdar, och äter deras frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Och Juda hus, som frälst och igenblifvet är, skall ännu rota sig nedantill, och bära frukt ofvantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Ty utaf Jerusalem varda utgångande de som igenblefne äro; och utaf Zions berg de som undsluppne äro; Herrans Zebaoths nit varder detta görandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Derföre säger Herren om Konungen i Assyrien alltså: Han skall icke komma i denna staden, och ingen pil skjuta der in, och ingen sköld föra der före, och ingen vall uppkasta der omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Utan han skall draga den vägen tillbaka igen, som han kommen är, och skall intet komma i denna staden; Herren hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Och jag skall beskärma denna staden, så att jag honom hjelpa vill för mina skull, och för Davids min tjenares skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'På den samma nattena for Herrans Ängel ut, och slog i de Assyriers lägre hundradetusend, och fem och åttatio tusend män; och då de om morgonen bittida uppstodo, si, då låg allt fullt med döda kroppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Alltså bröt Sanherib, Konungen af Assyrien, upp, drog sina färde, och vände om, och blef i Nineve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Och då han tillbad i Nisrochs sins guds hus, slogo honom hans söner med svärd, Adrammelech och SarEzer, och undflydde in uti det landet Ararat; och hans son EsarHaddon vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'På den tiden vardt Hiskia dödsjuk; och Propheten Esaia, Amos son, kom till honom, och sade till honom: Så säger Herren: Skicka om ditt hus; ty du måste dö, och icke blifva lefvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Men han vände sitt ansigte till väggena, och bad till Herran, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Ack Herre! Kom dock ihåg, att jag hafver troliga vandrat för dig, och med rättsinnigt hjerta, och gjort det dig hafver ljuft varit. Och Hiskia gret svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Men som Esaia icke ännu halfväges igenom staden utkommen var, kom Herrans ord till honom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Vänd om, och säg Hiskia mins folks Första: Detta säger Herren dins faders Davids Gud: Jag hafver hört dina bön, och sett dina tårar; si, jag vill göra dig helbregda; tredje dagen härefter skall du uppgå i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Och jag skall förlänga ditt lif till femton år, och fria dig och denna staden utu Konungens hand i Assyrien, och beskärma denna staden för mina skull, och för min tjenares Davids skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Och Esaia sade: Får mig hit ett stycke fikon. Och när de hade det fått honom, lade han det på böldena, och han vardt helbregda,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Hiskia sade till Esaia: Hvad tecken är dertill, att Herren vill göra mig helbregda, och jag uppgå skall i Herrans hus tredje dagen härefter?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Esaia sade: Detta tecknet skall du hafva af Herranom, att Herren skall så göra med dig, som han sagt hafver; vill du att skuggen skall gå tio streck framåt, eller tio streck tillbaka?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Hiskia sade: Det är lätt, att skuggen går framåt tio streck, det vill jag icke; utan att han går tio streck tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Då åkallade Propheten Esaia Herran, och skuggen gick tillbaka tio streck, som han framåt gångit hade på Ahas säjare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'På den tiden sände Berodach Baladan, Baladans son, Konungen i Babel, bref och gåfvor till Hiskia; förty han hade hört, att Hiskia hade varit krank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Och Hiskia gjorde sig glad med dem, och viste dem hela örtahuset, silfver, guld, speceri, och den bästa oljon, och harneskhuset, och allt det i hans fatebur för handene var; och var intet i hans hus, och i allt hans våld, det Hiskia dem icke viste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Så kom Propheten Esaia till Konung Hiskia, och sade till honom: Hvad hafva desse männerna sagt? Och hvadan äro de komme till dig? Hiskia sade: De äro utaf fjerran land komne till mig, ifrå Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Han sade: Hvad hafva de sett i dino huse? Hiskia sade: De hafva sett allt det i mino huse är; och i mina håfvor är intet, som jag dem icke vist hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Då sade Esaia till Hiskia: Hör Herrans ord:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Si, den tid skall komma, att allt skall bortfördt varda utu ditt hus till; Babel, och allt det dine fäder församlat hafva intill denna dag; och skall intet igenlefdt varda, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Dertill de barn, som af dig komma, som du födandes varder, skola varda tagne till att vara kamererare i Konungens palats i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Hiskia sade till Esaia: Det är så godt, som Herren sagt hafver. Och sade ytterligare: Vare dock frid och sanning i min tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Hvad nu mer af Hiskia sägandes är, och all hans magt, och hvad han gjort hafver, och om dammen och vatturännorna, dermed han ledde vatten in i staden, si, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Och Hiskia afsomnade med sina fäder; och Manasse hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasse var tolf åra gammal, då han vardt Konung, och regerade fem och femtio år i Jerusalem; hans moder het Hephziba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Och han gjorde det ondt var för Herranom, efter Hedningarnas styggelse, som Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Och han afvände sig, och uppbyggde de höjder, som hans fader Hiskia nederbrutit hade, och uppsatte Baals altare, och gjorde lundar, såsom Achab, Israels Konung, gjort hade; och tillbad all himmelens här, och tjente dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Och byggde altare i Herrans hus, der Herren om sagt hade: Jag skall sätta mitt Namn i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Och han byggde allom himmelens här altare, uti båda gårdarna till Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Och lät sin son gå igenom eld, och aktade på foglarop och tecken, och höll spåmän och tecknatydare, och gjorde mycket det ondt var för Herranom, der han honom med förtörnade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Han satte ock en lundagud, den han gjort hade, i huset, om hvilket Herren till David och hans son Salomo sagt hade: Uti detta hus, och i Jerusalem, det jag utvalt hafver utur alla Israels slägter, vill jag sätta mitt Namn i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Och skall icke låta Israels fot mer röra sig ifrå det land, som jag deras fader gifvit hafver dock så, om de hålla och göra efter allt det jag budit hafver, och efter all de lag, som min tjenare Mose dem budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Men de lydde intet; utan Manasse förförde dem, så att de gjorde värre än Hedningarna, som Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Då talade Herren genom sina tjenare Propheterna, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Derföre, att Manasse, Juda Konung, hafver denna styggelsen gjort, som värre är än all den styggelse som de Amoreer gjort hafva, som för honom voro; och hafver desslikes kommit Juda till att synda med sina afgudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Derföre säger Herren Israels Gud alltså: Si, jag skall låta komma olycka öfver Jerusalem och Juda, så att hvilken som helst det får höra, honom skall det gälla i båda hans Öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Och jag skall utsträcka öfver Jerusalem Samarie snöre, och Achabs hus vigt; och skall utskölja Jerusalem, såsom man utsköljer diskar, och skall omstörta det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Och jag skall låta några af minom arfvedel blifva qvara, och gifva dem uti deras fiendars händer, att de skola varda till ett rof och sköfvel allom deras fiendom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Derföre, att de gjort hafva det mig illa behagar, och hafva förtörnat mig, ifrå den dag, då deras fäder foro utur Egypten, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Och utgöt Manasse ganska mycket oskyldigt blod, in tilldess Jerusalem på alla sidor fullt vardt; förutan de synder, der han med kom Juda till att synda, att de gjorde det ondt var för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Hvad nu mer af Manasse sägandes är, och allt det han gjort hafver, och om hans synder, som han bedref, si, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Och Manasse afsomnade med sina fäder, och vardt begrafven i trägårdenom vid lians hus, nämliga i Ussa trägård; och hans son Amon vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Tu och tjugu åra gammal var Amon, då han vardt Konung, och han regerade i tu år i Jerusalem; hans moder het Mesullemeth, Haruz dotter, af Jotba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Och han gjorde det Herranom illa behagade, såsom hans fader Manasse gjort hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Och vandrade i allan den väg, som hans fader vandrat hade, och tjente de afgudar, som hans fader tjent hade, och tillbad dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Och öfvergaf Herran sina fäders Gud, och vandrade icke på Herrans väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Och hans tjenare gjorde ett förbund emot Amon, och dråpo Konungen i hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Men folket i landena slog alla dem, som förbundet emot Konung Amon gjort hade. Och folket i landena gjorde Josia, hans son, till Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Hvad Amon nu mer gjort hafver, si, det är skrifvet i Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Och man begrof honom i hans graf, i Ussa trägärd; och hans son Josia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josia var åtta åra gammal, då han vardt Konung, och regerade ett och tretio år i Jerusalem; hans moder het Jedida, Adaja dotter, af Bozkath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Han gjorde det godt var för Herranom, och vandrade i allom sins faders Davids väg, och böjde hvarken på högra sidona, eller på den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Uti adertonde årena Konungs Josia, sände Konungen Saphan, Azalia son, Mesullams sons, skrifvaren, bort uti Herrans hus, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Gack upp till öfversta Presten Hilkia, att man må få honom de penningar, som till Herrans hus införde äro, och dörravaktarena församlat hafva af folkena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Att de måga gifva dem arbetarena, som beställde äro i Herrans hus, och gifva dem som arbeta på Herrans hus, och bota det som förfallet är i husena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Nämliga timbermannom, byggningsmannom, murmästarom, och dem som trä och huggen sten köpa skola, till husets förbättring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Dock så, att man ingen räkenskap skulle taga af dem för de penningar, som under deras hand antvardade vordo; utan de skulle handla dermed på sina tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Och öfverste Presten Hilkia sade till skrifvaren Saphan: Jag hafver funnit lagbokena uti Herrans hus; och Hilkia fick Saphan bokena, att han skulle den läsa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Och skrifvaren Saphan bar henne till Konungen, och bådade honom igen, och sade: Dine tjenare hafva tillhopahemtat de penningar, som i husena funne voro, och hafva utgifvit dem arbetarena, som beställde äro i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Och förtäljde skrifvaren Saphan Konungenom, och sade: Hilkia Presten fick mig ena bok; och Saphan las henne för Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Då Konungen hörde orden i lagbokene, ref han sin kläder sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Och Konungen böd Hilkia Prestenom, och Ahikam, Saphans sone, och Achbor, Michaja sone, och Saphan skrifvarenom, och Asaja, Konungens tjenare, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Går bort, och fråger Herran, för mig, för folket, och för hela Juda, om denna bokenes ord, som funnen är; ty det är en stor Herrans vrede, som är upptänd öfver oss; derföre, att våre fäder icke lydt hafva denna bokenes ord, att de måtte gjort allt det derutinnan skrifvet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Då gingo åstad Hilkia Presten, Ahikam, Achbor, Saphan och Asaja, till den Prophetissan Hulda, Sallums hustru, Thikva sons, Harhas sons, klädavaktarens; och hon bodde i Jerusalem i dem andra delenom, och de talade med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Men hon sade till dem: Detta säger Herren Israels Gud: Säger dem månne, som eder till mig sändt hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Så säger Herren: Si, jag skall låta komma olycko öfver detta rum, och dess inbyggare, efter all lagsens ord, som Juda Konung hafver läsa låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Derföre, att de hafva öfvergifvit mig, och rökt andra gudar, förtörnande mig med allt deras handaverk; derföre skall min vrede upptändas emot detta rum, och skall icke utsläckt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Men Juda Konunge, som eder utsändt hafver till att fråga Herran, skolen I så säga: Så säger Herren Israels Gud:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Derföre, att ditt hjerta hafver bevekt sig, af de ord, som, du hört hafver, och hafver ödmjukat dig för Herranom, då du hörde hvad jag sagt hade emot detta rum, och dess inbyggare, att de skulle varda till en förödelse och förbannelse, och hafver rifvit din kläder sönder, och hafver gråtit för mig, så hafver jag ock hört det, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Derföre vill jag samka dig till dina fäder, att du skall samkas i grafvena med frid, och din ögon icke se skola alla denna olyckona, som jag öfver detta rum föra skall. Och de sade Konungenom det igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Och Konungen sände bort, och till honom församlades alle de äldste i Juda och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Och Konungen gick upp i Herrans hus, och hvar man af Juda, och alle Jerusalems inbyggare med honom, Prester och Propheter, och allt folket, både små och store; och man las för deras öron all förbundsens boks ord, hvilken i Herrans hus funnen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Och Konungen gick in till en stod, och gjorde ett förbund för Herranom, att de skulle vandra efter Herranom, och hålla hans bud, vittnesbörd och rätter, af allt hjerta, och af allo själ, att de skulle upprätta detta förbunds ord, som skrifne stodo uti desso bok; och allt folket trädde uti förbundet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Och Konungen böd öfversta Prestenom Hilkia, och Prestenom af det andra skiftet, och dörravaktaromen, att de skulle utkasta af Herrans tempel allahanda tyg, som till Baal och lunden, och all himmelens här gjordt var; och de brände det upp utanför Jerusalem i Kidrons dal, och stoftet deraf vardt buret till BethEl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Och han afsatte de Camarim, hvilka Juda Konungar stiktat hade, till att röka på höjderna uti Juda städer, och omkring Jerusalem; desslikes Baals, solenes, månans, planeternas och all himmelens härs rökare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Och lät föra lunden utu Herrans hus, ut för Jerusalem, i Kidrons bäck; och brände honom upp i Kidrons bäck, och gjorde honom till stoft, och kastade stoftet uppå det meniga folks grifter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Och han bröt bort de roffarehus, som voro vid Herrans hus, der qvinnor uti vofvo tapeter till lunden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Och han lät församla alla Presterna utu Juda städer, och orenade de höjder, der Presterna rökte, ifrå Geba allt intill BerSeba; och han bröt bort portaltaren, som voro uti ingångenom i Josua stadsfogdans port, hvilken voro på venstra sidone, der man går till stadsporten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Dock offrade icke höjdernas Prester någon tid på Herrans altare i Jerusalem, utan åto af de osyrade brödena, ibland sina bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Han orenade ock Tophet, uti Hinnoms barnas dal, att ingen skulle låta gå sin son eller sina dotter genom eld för Molech;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Och tog bort de hästar, hvilka Juda Konungar solene uppsatt hade, i ingångenom åt Herrans hus, till NethanMelechs åminnelse, kamererarens, som i Parvarim var; och solenes vagnar brände han upp i eld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Så ock altaren på taken i Ahas sal, den Juda Konungar gjort hade; och de altare, som Manasse gjort hade uti de två gårdar åt Herrans hus, bröt Konungen bort, och lopp dädan, och kastade deras stoft i Kidrons bäck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Och de höjder, som för Jerusalem voro, på högra sidone, vid berget Mashith, som Salomo Israels Konung byggt hade till Astoreth, Zidons styggelse, och Chemos, Moabs styggelse, och Milcom, Ammons barnas styggelse, orenade Konungen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Och slog sönder stoderna, och utrotade lundarna, och uppfyllde deras rum med menniskoben;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Sammalunda ock det altaret i BethEl, höjden, som Jerobeam, Nebats son, gjort hade, den Israel hade kommit till att synda; det samma altaret bröt han neder, och höjdena, och brände upp höjdena, och gjorde henne till stoft, och brände upp lunden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Och Josia vände sig om, och fick se de grifter, som voro på bergena, och sände bort, och lät hemta benen utu grifterna, och uppbrände dem på altarena, och orenade det, efter Herrans ord, som Guds mannen utropat hade, den detta så föresagt hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Och han sade: Hvad är detta för en vård, som jag här ser? Och folket i stadenom sade till honom: Det är den Guds mansens grift, som af Juda kom, och detta utropade, som du gjort hafver med altarena i BethEl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Och han sade: Låt honom ligga; ingen röre hans ben. Alltså vordo hans ben friade, med den Prophetens ben, som utaf Samarien kommen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Han kastade ock bort all höjders hus uti Samarie städer, som Israels Konungar gjort hade, till att förtörna (Herran), och gjorde med dem alldeles såsom han i BethEl gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Och han offrade alla höjdernas Prester, som der voro, på altaren, och brände så menniskoben deruppå, och kom igen till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Och Konungen böd folkena, och sade: Håller Herranom edrom Gud Passah, såsom skrifvet är i denna förbunds bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Ty intet Passah var så hållet som detta, ifrå de domares tid, som Israel dömde, och i alla Israels Konungars och Juda Konungars tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Utan i adertonde årena Konungs Josia vardt detta Passah hållet Herranom i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Desslikes rensade Josia ut alla spåmän, tecknatydare, beläte och afgudar, och all styggelse, som i Juda land och i Jerusalem sedde vordo; på det han skulle upprätta lagsens ord, som skrifne stodo i bokene, som Presten Hilkia fann i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Hans like hade ingen Konung varit för honom, den så af allt hjerta, af allo själ, och alla krafter sig till Herran vände, efter all Mose lag; och efter honom kom ej heller hans like upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Dock vände icke Herren sig ifrå sine stora vredes grymhet, der han med öfver Juda förtörnad var, för all de retelses skull, dermed Manasse honom rett hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Och Herren sade: Jag vill ock kasta Juda ifrå mitt ansigte, såsom jag Israel bortkastat hafver; och skall förkasta denna staden, som jag utvalt hafver, nämliga Jerusalem, och det hus, der jag om sagt hafver: Mitt Namn skall vara der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Hvad nu mer af Josia sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Uti hans tid drog Pharao Necho, Konungen i Egypten, upp emot Konungen af Assyrien, vid den älfvena Phrat; men Konung Josia drog emot honom, och blef död i Megiddo, då han hade sett honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Och hans tjenare förde honom dödan ifrå Megiddo, och hade honom till Jerusalem, och begrofvo honom i hans graf; och folket i landena togo Joahas, Josia son, och smorde honom, och gjorde honom till Konung i hans faders stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Tre och tjugu åra gammal var Joahas, då han vardt Konung, och regerade tre månader i Jerusalem; hans moder het Hamutal, Jeremia dotter af Libna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Och han gjorde det ondt var för Herranom, såsom hans fäder gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Men PharaoNecho grep honom i Riblath i Hamaths land, att han icke regera skulle i Jerusalem; och lade en beskattning på landet, hundrade centener silfver, och en centener guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Och PharaoNecho gjorde Eliakim, Josia son, till Konung uti hans faders Josia stad, och vände hans namn Jojakim. Men Joahas tog han, och förde in uti Egypten; der blef han död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Och Jojakim gaf Pharao silfret och guldet; dock beskattade han landet, att han sådant silfver gifva kunde efter Pharaos befallning; hvar och en, efter sina förmågo, beskattade han till silfver och guld ibland folket i landena, att han det PharaoNecho gifva skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Fem och tjugu åra gammal var Jojakim, då han vardt Konung, och regerade ellofva år i Jerusalem; hans moder het Zebuda, Pedaja dotter af Ruma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Och han gjorde det ondt var för Herranom, såsom hans fäder gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Uti hans tid drog NebucadNezar upp, Konungen i Babel, och Jojakim vardt honom underdånig i tre år. Och han vände sig om, och föll ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Och Herren lät komma öfver honom krigsfolk, utu Chaldeen, utu Syrien, utu Moab, och ifrån Ammons barn; och lät komma dem i Juda, att de skulle förderfva honom, efter Herrans ord, det han talat hade genom sina tjenare Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Men det skedde Juda alltså, efter Herrans ord, på det han skulle kasta dem ifrå sitt ansigte för Manasse synds skull, som han gjort hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Och för det oskyldiga blods skull, som han utgöt, och gjorde Jerusalem fullt med oskyldigt blod; och derföre ville Herren icke förlåtat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Hvad nu mer af Jojakim sägandes är, och allt det han gjort hafver, si, det är skrifvet uti Juda Konungars Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Och Jojakim afsomnade med sina fäder, och hans son Jojachin vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Och Konungen i Egypten drog icke mer utu sitt land; förty Konungen i Babel hade honom borttagit allt det som Konungens i Egypten var, ifrån Egypti bäck allt intill den älfven Phrath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Aderton åra gammal var Jojachin, då han Konung vardt, och regerade tre månader i Jerusalem; hans moder het Nehustha, Elnathans dotter af Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Och han gjorde det ondt var för Herranom, såsom hans fader gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'På den tiden drogo NebucadNezars Konungens tjenare i Babel upp till Jerusalem, och kringlade staden med bålverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Och då NebucadNezar kom till staden med sina tjenare, belade han honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Men Jojachin, Juda Konung, gick ut till Konungen af Babel med sine moder, med sina tjenare, med sina öfverstar och kamererare. Och Konungen af Babel anammade honom i lians rikes åttonde åre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Och tog ut dädan alla håfvor uti Herrans hus, och i Konungshuset; och slog sönder all gyldene kärile, som Salomo, Israels Konung, gjort hade uti Herrans tempel, såsom Herren sagt hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Och förde bort hela Jerusalem, alla öfverstar, alla väldiga, tiotusend fångar, och alla timbermän, och alla smeder, och lät intet qvart blifva, utan det ringesta folket i landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Och förde bort Jojachin till Babel, Konungens moder, Konungens hustrur, och hans kamererare; desslikes de myndiga i landena förde han ock fångna bort ifrå Jerusalem till Babel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Och hvad bästa folket var, sjutusend, och de timbermän och smeder, tusende, alle starke krigsmän. Och Konungen af Babel förde dem till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Och Konungen af Babel gjorde Matthania, hans faderbroder, till Konung i hans stad, och förvände hans namn Zedekia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Ett och tjugu år gammal var Zedekia, då han vardt Konung, och regerade ellofva år i Jerusalem; hans moder het Hamital, Jeremia dotter af Libna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Och han gjorde det ondt var för Herranom, såsom Jojakim gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Ty det skedde alltså med Jerusalem och Juda utaf Herrans vrede, tilldess han kastade dem bort ifrå sitt ansigte. Och Zedekia vardt affällig ifrå Konungenom i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Och det begaf sig i nionde årena af hans rike, på tionde dagen i tionde månadenom, kom NebucadNezar, Konungen i Babel, med all sin magt för Jerusalem, och de lägrade sig der före, och byggde skansar allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Alltså vardt staden belagd, allt intill ellofte året af Konung Zedekia rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Men i nionde månadenom vardt hungren stark i stadenom, så att folket i landena hade intet äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Då föll man in i staden, och alle krigsmän flydde om nattena, den vägen ifrå porten, som går emellan de två murar åt Konungsträgården. Och de Chaldeer lågo omkring staden. Och han flydde den vägen åt hedmarkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Men de Chaldeers magt jagade efter Konungen, och grepo honom på hedmarkene vid Jericho. Och alle krigsmännerna, som när honom voro, vordo förskingrade ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Men Konungen grepo de, och förde honom upp till Konungen af Babel till Riblath; och de sade en dom öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Och de slogo Zedekia barn ihjäl för hans ögon, och stungo Zedekia hans ögon ut, och bundo honom med kedjor, och förde honom till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'På sjunde dagen i femte månadenom, det är nittonde året NebucadNezars, Konungens i Babel, kom NebusarAdan hofmästaren, Konungens tjenare i Babel, till Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Och uppbrände Herrans hus, och Konungshuset, och all hus i Jerusalem, och all stor hus brände han upp med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Och hela de Chaldeers magt, som med hofmästarenom var, bröt omkull murarna, som omkring Jerusalem voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Men det andra folket, som qvart var i stadenom, och de som till Konungen af Babel fallne voro, och det andra meniga folket, förde NebusarAdan hofmästaren bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Och af de ringesta i landena lät hofmästaren blifva till vingårdsmän, och åkermän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Men de kopparstodar i Herrans hus, och stolarna, och kopparhafvet, som i Herrans hus var, slogo de Chaldeer sönder, och förde kopparen till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Och grytor, skoflar, knifvar, skedar, och all kopparkärile, dermed man tjente, togo de bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Dertill tog hofmästaren pannor och bäcken, hvad af guld och silfver var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Två stodar, ett haf, och de stolar, som Salomo hade göra låtit till Herrans hus; kopparen af all denna tygen stod icke till vägandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Aderton alnar hög var en stoden, och knappen derpå var ock af koppar, och tre alnar hög; och gjordarne, och granatäplen allt omkring knappen, var ock allt af koppar; vid samma sättet var ock den andre stoden med gjordar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Och hofmästaren tog Presten Seraja af första skiftet, och Presten Zephania af det andra skiftet, och tre dörravaktare,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Och en kamerer utu stadenom, som öfver krigsmännerna satt var, och fem män, som allstädes hade ståndit för Konungenom, och i stadenom funne voro, och Sopher, härhöfvitsmannen, som folket i landena strida lärde, och sextio män af landsfolkena, som i stadenom funne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Dessa tog NebusarAdan hofmästaren, och förde dem till Konungen af Babel till Riblath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Och Konungen i Babel slog dem ihjäl i Riblath, i de landena Hamath. Alltså vardt Juda bortförd utu sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Men öfver det folk, som qvart blef i Juda land, som NebucadNezar, Konungen i Babel, qvart blifva lät, satte han Gedalja, Ahikams son, Saphans sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Då nu allt krigsfolkets höfvitsmän och männerna hörde, att Konungen af Babel hade uppsatt Gedalja, kommo de till Gedalja i Mizpa, nämliga Ismael, Nethania son, och Johanan, Kareahs son, och Seraja, Thanhumeths son, den Netophathiten, och Jaesania, Maachati son, samt med deras män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Och Gedalja svor dem, och deras män, och sade till dem: Frukter eder intet att vara de Chaldeers underdånar; blifver i landena, och varer Konungenom af Babel underdånige, så går eder väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Men i sjunde månadenom kom Ismael, Nethania son, Elisama sons, utaf Konungsliga slägt, och tio män med honom, och slogo Gedalja ihjäl; dertill de Judar och Chaldeer, som med honom voro i Mizpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Då reste sig upp allt folket, både små och store, och krigsöverstarna, och kommo in uti Egypten; förty de fruktade sig för de Chaldeer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Uti sjunde och tretionde årena, sedan Jojachin, Juda Konung, bortförd var, på sjunde och tjugonde dagen i tolfte månadenom, hof EvilMerodach, Konungen i Babel, uti första årena af sitt rike, Jojachins, Juda Konungs, hufvud upp utu fängslehuset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Och talade vänliga med honom, och satte hans stol utöfver de Konungars stolar, som när honom voro i Babel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Och förvandlade hans fängelsekläder; och han åt alltid inför honom i alla sina lifsdagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Och satte honom före hans del, den man honom alltid gifva skulle af Konungenom, hvar dag, så länge han lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalaleel, Jared,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Methusalah, Lamech,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noah, Sena, Ham, Japhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Japhets barn äro desse: Gomer, Magog, Madai, Javan, Thubal, Mesech, Thiras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Men Gomers barn äro: Ascenas, Riphath, Thogarma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Javans barn äro: Elisa, Tharsisa, Chittim, Dodam, Dodanim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Hams barn äro: Chus, Mizraim, Phut, Canaan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Men Chus barn äro desse: Seda, Havila, Sabtha, Raema, Sabtecha, Raema barn äro: Seba och Dedan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Men Chus födde Nimrod. Han begynte vara väldig på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Mizraim födde Ludim, Anamim, Lehabim, Naphthuhim,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Patrusim, Casluhim; af hvilkom utkomne äro de Philistim och Caphthorim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Men Canaan födde Zidon, sin första son, och Heth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Jebusi, Emori, Girgasi,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Hivi, Arki, Sini,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arvadi, Zemari och Hamathi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Sems barn äro desse: Elam, Assur, Arphachsad, Lud, Aram, Uz, Hul, Gether och Maseeh.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Men Arphachsad födde Salah; Salah födde Eber.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Men Eber vordo födde två söner; den ene het Peleg, derföre, att i hans tid vardt landet deladt; och hans broder het Jaketan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Jaketan födde Almodad, Saleph, Hazarmaveth, Jarah,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Usal, Dikela,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebal, Abimael, Seba,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ophir, Havila och Jobab. Desse äro alle Jaketans barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arphachsad, Salah,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Regu,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Tharah,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, det är Abraham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Men Abrahams barn äro: Isaac och Ismael.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Detta är deras ätter: den förste Ismaels son Nebajoth; Kedar, Adbeel, Mibsam,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duma, Massa, Hadad, Thema,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jethur, Naphis, Kedma. Desse äro Ismaels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Men Keturas barn, Abrahams frillos: hon födde Simran, Jaksan, Medan, Midian, Jisbak, Suah. Och Jaksans barn äro: Seba och Dedan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Och Midians barn äro: Epha, Epher, Hanoch, Abida, Eldaa. Desse äro alle Keturas barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraham födde Isaac. Isaacs barn äro: Esau och Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Esau barn äro: Eliphas, Reguel, Jeus, Jaelam, Korah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Eliphas barn äro: Teman, Omar, Zephi, Gatham, Kenas, Thimna, Amalek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Reguels barn äro: Nahath, Serah, Samma och Missa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Seirs barn äro: Lotan, Sobal, Zibeon, Ana, Dison, Ezer, Disan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lotans barn äro: Hori, Homam; och Thimna var Lotans syster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Sobals barn äro: Aljan, Manahat, Ebal, Zephi, Onam. Zibeons barn: Aja och Ana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Ana barn äro: Dison. Disons barn äro: Hamran, Esban, Jithran, Cheran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Ezers barn äro: Bilhan, Saavan, Jaachan. Disans barn äro: Uz och Aran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Desse äro de Konungar, som regerade uti Edoms land, förra än någor Konung regerade ibland Israels barn: Bela, Geors son; och hans stad het Dinhaba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Och då Bela blef död, vardt Konung i hans stad Jobab, Serahs son af Bozra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Då Jobab blef död, vardt Konung i hans stad Husam, utaf de Themaniters land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Då Husam blef död, vardt Konung i hans stad Hadad, Badads son, hvilken slog de Midianiter på de Moabiters mark; och hans stad het Avith.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Då Hadad blef död, vardt Konung i hans stad Samla af Masreka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Då Samla blef död, vardt Konung i hans stad Saul af Rehoboth vid älfvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Då Saul blef död, vardt Konung i hans stad Baalhanan, Achbors son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Då Baalhanan blef död, vardt Konung i hans stad Hadad; och hans stad het Pagi; och hans hustru het Mehetabeel, Matreds dotter, och Mesahabs dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Då Hadad blef död, vordo Förstar i Edom: den Försten Thimna, den Försten Alja, den Försten Jetheth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Den Försten Aholibama, den Försten Ela, den Försten Pinon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Den Försten Kenas, den Försten Theman, den Försten Mibzar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Den Försten Magdiel, den Försten Iram. Desse äro de Förstar i Edom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Desse äro Israels barn: Ruben, Simeon, Levi, Juda, Isaschar, Sebulon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph, BenJamin, Naphthali, Gad, Asser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Juda barn äro: Er, Onan, Sela; de tre vordo honom födde af Sua dotter den Cananeiskon. Men Er, den förste Juda son, var arg för Herranom, derföre drap han honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Men Thamar hans sonahustru födde honom Perez och Serah, så att all Juda barn voro fem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Perez barn äro: Hezron och Hamul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Men Serah barn äro: Simri, Ethan, Heman, Chalcol, Dara. Desse tillhopa äro fem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Charmi barn äro: Achar, hvilken bedröfvade Israel, då han förtog sig på det tillspillogifvet var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Ethans barn äro: Asaria.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Hezrons barn, som honom födde äro: Jerahmeel, Ram, Chelubai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram födde Amminadab; Amminadab födde Nahesson, den Förstan för Juda barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahesson födde Salma; Salma födde Boas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boas födde Obed; Obed födde Isai;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Isai födde sin första son Eliab, AbiNadab den andre, Simea den tredje,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nethaneel den fjerde, Raddai den femte,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozem den sjette, David den sjunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Och deras systrar voro: ZeruJa och Abigail. ZeruJa barn äro: Abisai, Joab, Asahel, de tre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Men Abigail födde Amasa; och Amasa fader var Jether, en Ismaelit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Caleb, Nezrons son, födde med den qvinnone Asuba och med Jerigoth; och desse äro hennes barn; Jeser, Sobab och Ardon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Då Asuba blef död, tog Caleb Ephrath; hon födde honom Hur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur födde Uri; Uri födde Bezaleel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Derefter besof Hezron Machirs dotter, Gileads faders; och han tog henne, då han var sextio åra gammal; och hon födde honom Segub.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segub födde Jair; han hade tre och tjugu städer i Gileads land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Och han tog utaf de samma Gesur och Aram, Jairs byar; dertill Kenath med dess döttrar, sextio städer. Desse äro alle Machirs barn, Gileads faders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Efter Hezrons död i CalebEphrata lefde Hezron sina hustru Abia; hon födde honom Ashur, Thekoa fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Jerahmeel, Hezrons förste son, hade barn; den förste Ram, Buna, Oren och Ozem, och Ahia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Och Jerahmeel hade ännu ena andra hustru, som het Atarah; hon är Onams moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Rams barn, Jerahmeels första sons, äro: Maaz, Jamin och Eker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Men Onam hade barn: Sammai och Jada. Sammai barn äro: Nadab och Abisur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Men Abisurs hustru het Abihail; hon födde honom Ahban och Molid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Nadabs barn äro: Seled och Appaim; och Seled blef död barnlös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Appaims barn äro: Jisei. Jisei barn äro: Sesan. Sesans barn äro: Ahlai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Jada barn, Sammai broders, äro: Jether och Jonathan; men Jether blef död barnlös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Men Jonathans barn äro: Peleth och Sasa. Det äro Jerahmeels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Men Sesan hade inga söner, utan döttrar. Och Sesan hade en Egyptisk tjenare, han het Jarha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Och Sesan gaf Jarha, sinom tjenare, sina dotter till hustru; hon födde honom Attai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Attai födde Nathan; Nathan födde Sabad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Sabad födde Ephlal; Ephlal födde Obed;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed födde Jehu; Jehu födde Asaria;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Asaria födde Helez; Helez födde Elasa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elasa födde Sismai; Sismai födde Sallum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallum födde Jekamia; Jekamia födde Elisama.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Calebs barn, Jerahmeels broders, äro: Mesa, hans förste son; han är Siphs fader, och Maresa barn, Hebrons faders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Hebrons barn äro: Korah, Thappuah, Rekem och Serna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Men Serna födde Raham, Jorkeams fader; Rekem födde Sammai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Sammai son het Maon; och Maon var Bethzurs fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Men Epha, Calebs frilla, födde Haran, Moza och Gases. Haran födde Gases.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Men Jahdai barn äro: Regem, Jotham, Gesan, Pelet, Epha och Saaph.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Men Maacha, Calebs frilla, födde Seber och Thirhana;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Och födde desslikes Saaph, Madmanna foder, och Seva, Machbena fader, och Gibea fader. Achsa var Calebs dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Desse voro Calebs barn, Hurs den förste sonens af Ephrata: Sobal, KiriathJearims fader,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, BethLehems fader, Hareph, BethGaders fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Och Sobal, KiriathJearims fader, hade söner; han såg halfva Manuhoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Men de slägter i KiriathJearim voro: de Jithriter, Puthiter, Sumathiter och Misraiter. Utaf dessom äro utkomne de Zorgathiter och Esthaoliter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Salma barn äro: BethLehem och de Netophathiter, kronorna till Joabs hus, och hälften af de Manathiter af den Zorgiten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Och de skrifvares slägter, som i Jabez bodde, äro: de Thirathiter, Simathiter, Suchathiter. Det äro de Kiniter, som komne äro af Hamath, BethRechabs fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Desse äro Davids barn, som honom födde äro i Hebron: den förste, Ammon, af Ahinoam den Jisreelitiskone; den andre, Daniel, af Abigail den Carmelitiskone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Den tredje, Absalom, Maachas son, Thalmai dotters, Konungens i Gesur; den fjerde, Adonia, Haggiths son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Den femte, SephathJa, af Abital; den sjette, Jithream, af hans hustru Egla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Desse sex äro honom födde i Hebron; förty han regerade der i sju år och sex månader; men i Jerusalem regerade han i tre och tretio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Och desse äro honom födde i Jerusalem: Simea, Sobab, Nathan, Salomo, de fyra, af BathSua, Ammiels dotter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Dertill Jibehar, Elisama, Eliphelet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Noga, Nepheg, Japhia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eljada, Eliphelet, de nio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Desse äro alle Davids barn, förutan de som frillobarn voro. Och Thamar var deras syster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomos son var Rehabeam. Hansson var Abia. Hans son var Asa. Hans son var Josaphat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Hans son var Joram. Hans son var Ahasia. Hans son var Joas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Hans son var Amazia. Hans son var Asaria. Hans son var Jotham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Hans son var Ahas. Hans son var Hiskia. Hans son var Manasse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Hans son var Amon. Hans son var Josia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Men Josia söner voro: Den förste, Johanan; den andre, Jojakim; den tredje, Zedekia; den fjerde, Sallum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Men Jojakims barn voro: Jechonia. Hans son var Zedekia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Jechonia barn, den fången vardt, voro: Sealthiel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkiram, Phedaja, Seneazar, Jekamia, Hosama, Nedabia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Phedaja barn voro: Serubbabel och Simei. Serubbabels barn voro: Mesullam och Hanania, och deras syster Selomith;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Dertill Hasuba, Ohel, Berechia, Hasadia, JusabHesed, de fem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Hanania barn voro: Pelatia och Jesaia. Hans son var Rephaja. Hans son var Arnan. Hans son var Obadja. Hans son var Sechania.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Men Sechania barn voro: Semaja, Semaja barn voro: Hattus, Jigeal, Bariah, Nearia, Saphat, de sex.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Nearia barn voro: Eljoenai, Hiskia, Asrikam, de tre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Eljoenai barn voro: Hodaja, Eljasib, Phelaja, Akkub, Johanan, Delaja, Anani, de sju.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Juda barn voro: Perez, Hezron, Charmi, Hur och Sobal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Men Reaja, Sobals son, födde Jahath. Jahath födde Ahumai och Lahad. Det äro de Zorgathiters slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Detta är den fadrens Ethams slägte: Jisreel, Jisma, Jidbas; och deras syster het Hazelelponi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Och Pnuel, Gedors fader, och Eser, Husa fader. Det äro Hurs barn, den första Ephrata sons, BethLehems faders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Men Ashur, Thekoa fader, hade två hustrur: Helea och Naara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Och Naara födde honom Ahusam, Hepher, Themeni, Ahastari. Det äro Naara barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Men Helea barn voro: Zereth, Jesohar och Ethnan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Men Coz födde Anub, och Hazobeba, och de Aharhels slägter, Harums sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Men Jabez var härligare än hans bröder; och hans moder kallade honom Jabez; ty hon sade: Jag hafver födt honom med bekymmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Och Jabez åkallade Israels Gud, och sade: Om du välsignar mig, och förvidgar mina gränsor, och din hand blifver med mig, och så skaffar med det onda, att det mig intet bekymrar. Och Gud lät ske som han bad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Men Chelub, Suahs broder, födde Mehir, det är Esthons fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Men Esthon födde Bethrapha, Paseah och Thehinna, fadren till den staden Nahas. Det äro de män af Recha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Kenas barn voro: Athniel och Seraja. Athniels barn voro: Hathath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Och Meonothai födde Ophra. Och Seraja födde Joab, en fader åt de timbermän i dalenom; ty de voro timbermän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Calebs barn, Jephunne sons, voro: Iru, Ela och Naam. Ela barn voro: Kenas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Jehaleleels barn voro: Siph, Sipha, Thiria och Asareel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Esra barn voro: Jether, Mered, Epher och Jalon, och Thahar med MirJam, Sammai, Jisbah Esthemoa fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Och hans hustru Judija födde Jered, Gedors fader, Heber, Socho fader, Jekuthiel, Sanoahs fader. Desse äro Bithias barn, Pharaos dotters, hvilka Mared tog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Den hustrunes Hodijas barn, Nahams systers, Kegila faders, voro: Hagarmi, och Esthemoa den Maachathiten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Simeons barn voro: Amnon, Rinnah, och Benhanan, Thilon. Jisei barn voro: Soheth och Bensoheth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Sela barn, Juda sons, voro: Er, Lecha fader, Laeda, Maresa fader, och de linväfvares slägter i Asbea hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Dertill Jokim, och de män af: Coseba, Joas, Saraph, hvilke husherrar voro i Moab, och bodde i Lahem; som de gamle säga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'De voro pottomakare, och bodde ibland planteringar och gårdar, när Konungenom i hans arbete, och kommo och blefvo der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Simeons barn voro: Nemuel, Jamin, Jarib, Serah, Saul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Hans son var Sallum. Hans son var Mibsam. Hans son var Misma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Misma barn voro: Hamuel. Hans son var Saccur. Hans son var Simei.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Simei hade sexton söner, och sex döttrar; och hans bröder hade icke mång barn; och all deras slägt förökade sig icke så mycket, som Juda barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Men de bodde i BerSeba, Molada, HazarSual,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Bilha, Ezem, Tholad,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Bethuel, Horma, Ziklag,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'BethMarchaboth, HazarSusim, BethBirei, Saarim. Det voro deras städer, allt intill Konung David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Dertill deras byar, Etham, Ain, Rimmon, Thochen, Asan, de fem städerna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Och alle de byar, som voro omkring dessa städerna, allt intill Baal. Det är deras boning, och deras ätt ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Och Mesobab, Jamlech, Josa, Amazia son,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel, Jehu Josibia son, Seraja sons, Asiels sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljoenai, Jaacoba, Jesohaja, Asaja, Adiel, Jisimiel, och Benaja,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Sisa, Siphei son, Allons sons, Jedaja sons, Simri sons, Semaja sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Desse voro namnkunnige Förstar uti deras ätter, och i deras fäders hus; och delade sig ut, efter det de voro månge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Och de drogo bort till att fara till Gedor, intill öster på dalen, på det de skulle söka bet för deras får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Och de funno feta och goda bet, och ett vidt land, stilla och rikt; ty i förtiden bodde der de af Ham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Och de som nu vid namn beskrifne äro, kommo i Hiskia tid, Juda Konungs, och slogo deras hyddor och boningar, som der funne vordo, och gjorde dem tillspillo, allt intill denna dag; och bodde i deras stad; ty der var bet för får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Och gingo ut af dem af Simeons barnom, femhundrad män, intill Seirs berg, med deras öfverstar; Pelatia, Nearia, Rephaja, och Ussiel, Jisei barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Och slogo de återlefde af de Amalekiter, som undsluppne voro; och bodde der allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Rubens barn, första Israels sons, ty han var förste sonen; men derföre, att han sins fäders säng besmittade, vardt hans förstfödslorätt gifven Josephs barnom, Israels sons; och han vardt icke räknad till förstfödslona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Ty Juda, som mägtig var ibland sina bröder, honom vardt Förstadömet för honom gifvet, och Joseph förstfödslorätten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Så äro nu Rubens, första Israels sons, barn: Hanoch, Pallu, Hezron och Charmi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Joels barn voro: Semaja. Hans son var Gog. Hans son var Simei.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Hans son var Micha. Hans son var Reaja. Hans son var Baal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Hans son var Beera, hvilken ThiglathPilneser, Konungen i Assyrien, bortförde fången; han är en Förste ibland de Rubeniter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Men hans bröder i deras ätter, då de i deras börd räknade vordo, hade Jegiel och Zacharia för höfvitsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Och Bela, Asas son, Serna sons, Joels sons, han bodde i Aroer, och intill Nebo och BaalMeon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Och bodde emot öster intill man kommer till öknena vid den älfvena Phrath; förty deras boskap var mycken i Gileads land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Och i Sauls tid förde de örlig emot de Hagariter, så att de föllo genom desses hand, och bodde i deras hyddor, in mot alla den östra ängden Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Gads barn bodde tvärtöfver ifrå dem, uti de landena Basan, allt intill Salcha:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel den främste, Sapham den andre, Jaenai och Saphat i Basan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Och deras bröder i deras fäders hus voro: Michael, Mesullam, Seba, Jorai, Jaecan, Sia och Eber, de sju.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Desse äro Abihails barn, Huri sons, Jaroahs sons, Gileads sons, Michaels sons, Jesisai sons, Jahdo sons, Bus sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, Abdiels son, Guni sons, var en öfverste uti deras fäders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Och bodde uti Gilead i Basan, och i dess döttrar, och i alla Sarons förstäder, allt intill dess ändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Desse vordo alle räknade i Jothams, Juda Konungs, och Jerobeams, Israels Konungs tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Rubens barn, de Gaditers, och de halfva slägtenes Manasse, voro stridsamme män, som sköld och svärd föra och båga spänna kunde, och förfarne till att strida; de voro fyra och fyratio tusend, och sjuhundrad och sextio, som i här drogo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Och då de stridde med de Hagariter, hulpo dem Jetur, Naphis och Nodab;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Och gåfvo de Hagariter i deras händer, och allt det som med dem var; förty de ropade till Gud i stridene, och han bönhörde dem; ty de trodde till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Och de förde bort deras boskap, femtiotusend camelar, tuhundrad och femtio tusend får, tutusend åsnar, och hundradtusend menniskors själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Och der föllo månge såre; ty striden var af Gudi. Och de bodde i deras stad allt intill den tiden de fångne vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'De halfva slägtenes Manasse barn bodde i de landena, ifrå Basan allt intill BaalHermon och Senir, och det berget Hermon, och de voro månge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Och desse voro höfvitsmän till deras fäders hus: Epher, Jisei, Eliel, Asriel, Jeremia, Hodavia, Jahdiel; väldige, mägtige män, och namnkunnige höfvitsmän uti deras fäders husom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Och då de förtogo sig emot deras fäders Gud, och i horeri gingo efter de folks gudar der i landena, som Gud för dem förgjort hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Uppväckte Israels Gud Phuls anda, Konungens i Assyrien, och ThiglathPilnesers anda, Konungens i Assyrien, och förde bort de Rubeniter, Gaditer och den halfva slägtena Manasse, och lät komma dem till Halah och Hober och Hara, och till den älfvena Gosan, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Levi barn voro: Gersom, Kehath och Merari.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Kehaths barn voro: Amram, Jizear, Hebron och Ussiel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Amrams barn voro: Aaron, Mose och MirJam. Aarons barn voro: Nadab, Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar födde Pinehas; Pinehas födde Abisua;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisua födde Bukki; Bukki födde Ussi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Ussi födde Serahia; Serahia födde Merajoth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajoth födde Amaria; Amaria födde Ahitob;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Ahitob födde Zadok; Zadok födde Ahimaaz;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Ahimaaz födde Asaria; Asaria födde Johanan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Johanan födde Asaria, hvilken Prest var i husena, som Salomo byggde i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Asaria födde Amaria; Amaria födde Ahitob;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Ahitob födde Zadok; Zadok födde Sallum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Sallum födde Hilkia; Hilkia födde Asaria;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Asaria födde Seraja; Seraja födde Jozadak;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Men Jozadak vardt med bortförd, då Herren lät bortföra Juda och Jerusalem fångna af NebucadNezar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Så äro nu Levi barn desse: Gersom, Kehath, Merari.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Gersoms barn heta alltså: Libni och Simei.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Kehaths barn heta: Amram, Jizear, Hebron och Ussiel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Merari barn heta: Maheli och Musi. Det äro de Leviters ätter efter deras fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Gersoms son var Libni; hans son var Jahath; hans son var Simma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Hans son var Joah; hans son var Iddo; hans son var Serah; hans son var Jeathrai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Men Kehaths son var Amminadab; hans son var Korah; hans son var As sir;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Hans son var Elkana; hans son var Ebjasaph; hans son var Assir;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Hans son var Tahath; hans son var Uriel; hans son var Ussia; hans son var Saul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Elkana barn voro: Amasai och Ahimoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Hans son var Elkana; hans son var ElkanaSophai; hans son var Nahath;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Hans son var Eliab; hans son var Jeroham; hans son var Elkana;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Hans son var Samuel; hans förstfödde var Vasni och Abija.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Merari son var Maheli; hans son var Libni; hans son var Simei; hans son var Ussa:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Hans son var Simea; hans son var Haggija; hans son var Asaja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Desse äro de som David satte till att sjunga i Herrans hus, då arken hvilade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Och tjente för boningene och vittnesbördsens tabernakel med sjungande, allt intill Salomo byggde Herrans hus i Jerusalem; och stodo efter deras sätt i deras ämbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Och desse äro de som stodo, och deras barn: Utaf Kehaths barnom var Heman sångaren, Joels son, Samuels sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Elkana sons, Jerohams sons, Eliels sons, Thoahs sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Zuphs sons, Elkana sons, Mahaths sons, Amasai sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Elkana sons, Joels sons, Asaria sons, Zephania sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Thahaths sons, Assirs sons, Ebjasaphs sons, Korahs sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Jizears sons, Kehaths sons, Levi sons, Israels sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Och hans broder Assaph stod på hans högra sido. Och Assaph var Berechia son, Simea sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Michaels sons, Baaseja sons, Malchija sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Ethni sons, Serahs sons, Adaja sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Ethans sons, Simma sons, Simei sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Jahaths sons, Gersoms sons, Levi sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Men deras bröder, Merari barn, stodo på venstra sidone, nämliga Ethan, Kisi son, Abdi sons, Malluchs sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Hasabia sons, Amazia sons, Hilkia sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Amzi sons, Bani sons, Sam ers sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Maheli sons, Musi sons, Merari sons, Levi sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Men deras bröder, Leviterna, voro skickade till allehanda ämbete uti Guds hus boning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Men Aaron och hans söner voro i det ämbetet, som var, upptända på bränneoffrets altare, och på rökaltarena, och till alla sysslor uti det aldrahelgaste, och till att försona Israel, såsom Mose Guds tjenare budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Aarons barn äro desse: Eleazar hans son; hans son var Pinehas; hans son var Abisua;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Hans son var Bukki; hans son var Ussi; hans son var Serahia;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Hans son var Merajoth; hans son var Amaria; hans son var Ahitob;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Hans son var Zadok; hans son var Ahimaaz.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Och detta är deras boning och säte uti deras gränsor, nämliga Aarons barnas af de Kehathiters ätt; ty lotten föll till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Och de gåfvo dem Hebron i Juda land, och dess förstäder allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Men stadsens mark och dess byar gåfvo de Caleb, Jephunne son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Så gåfvo de nu Aarons barnom de fristäder, Hebron och Libna, och dess förstäder, Jattir och Esthemoa, och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Hilen och dess förstäder, Debir och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Asan och dess förstäder, BethSemes och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Och af BenJamins slägte, Geba och dess förstäder, Alemeth och dess förstäder, Anathoth och dess förstäder; så att all städer i deras ätter voro tretton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Men dem androm Kehaths barnom deras ätter vordo, af den halfva Manasse slägte, genom lott gifne tio städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Gersoms barnom i deras ätter vordo i Isaschars slägte, och af Assers slägte, och af Naphthali slägte, och af Manasse slägt i Basan, tretton städer gifne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Merari barnom i deras ätter vordo genom lott gifne, af Rubens slägte, och af Gads slägte, och af Sebulons slägte, tolf städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Och Israels barn gåfvo också Leviterna städer, med deras förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Nämliga genom lott, af Juda barns slägte, och af Simeons barnas slägte, och BenJamins barnas slägte, de städer, som de vid namn före sade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Men Kehaths barnas ätt kommo städer till, af Ephraims slägtes gränsor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Så gåfvo de nu de andra Kehaths barnas ätt de fristäder, Sechem på Ephraims berg och dess förstäder, Geser och dess förstäder,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokmeam och dess förstäder, BethHoron och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajalon och dess förstäder, GathRimmon och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Dertill, af den halfva slägtene Manasse, Aner och dess förstäder, Bileam och dess förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Men Gersoms barnom gåfvo de, af de halfva Manasse slägtes ätt, Golan i Basa och dess förstäder, Astaroth och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'Af Isaschars slägte, Kades och dess förstäder, Daberath och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramoth och dess förstäder, Anem och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Af Assers slägte, Masal och dess förstäder, Abdon och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hukok och dess förstäder, Rehob och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'Af Naphthali slägte, Kedes i Galilea och dess förstäder, Hammon och dess förstäder, Kiriathaim och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Dem androm Merari barnom gåfvo de, af Sebulons slägte, Rimmono och dess förstäder, Thabor och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'Och på hinsidon Jordan tvärsöfver Jericho österut vid Jordan: Af Ruben slägte, Bezer i öknene och dess förstäder Jahzah och dess förstäder,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemoth och dess förstäder, Mephaath och dess förstäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Af Gads slägte, Ramoth i Gilead och dess förstäder, Mahanaim och dess förstäder,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hesbon och dess förstäder, Jaeser och dess förstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Isaschars barn voro: Thola, Phua, Jasub och Simrom, de fyra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Thola barn voro: Ussi, Rephaja, Jeriel, Jahmai, Jibsam och Samuel, hufvud uti deras fäders hus af Thola, och väldige män i deras ätter, vid det talet i Davids tid tu och tjugu tusend och sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Ussi barn voro: Jisraja. Jisraja barn voro: Michael, Obadja, Joel och Jissija, de fem; och voro alle höfvitsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Och med dem i deras ätter uti deras fäders hus voro väpnade härfolk till strid, sex och tretio tusend; ty de hade många hustrur och barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Och deras bröder i alla Isaschars ätter, väldige män, voro sju och åttatio tusend, och vordo alle räknade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'BenJamins barn voro: Bela, Becher och Jediael, de tre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Bela barn voro: Ezbon, Ussi, Ussiel, Jeremoth och Iri, de fem, höfvitsmän i fädernas hus, väldige män, och vordo räknade tu och tjugu tusend, och fyra och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Bechers barn voro: Semira, Joas, Elieser, Eljoenai, Omri, Jeremoth, Abia, Anathot och Alameth, de voro alle Bechers barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Och vordo räknade i deras ätter efter höfvitsmännerna i deras fäders hus, väldige män, tjugutusend och tuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Jediaels barn voro: Bilhan. Bilhans barn voro: Jeus, BenJamin, Ehud, Chenaana, Sethan, Tharsis och Ahisahar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'De voro alle Jediaels barn, fädernas höfvitsmän, väldige män, sjuttontusend tuhundrad, som i här utdrogo till att strida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Och Suppim och Huppim voro Irs barn; men Husim voro Achers barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Naphthali barn voro: Jahziel, Guni, Jezer och Sallum af Bilha barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manasse barn äro desse: Esriel, hvilken hans frilla Aramia födde; men han födde Machir, Gileads fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Och Machir gaf Huppim och Suppim hustrur, och hans syster het Maacha; hans andre son het Zelaphehad; och Zelaphehad hade döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Och Maacha, Machirs hustru, födde en son, den kallade hon Peres: och hans broder het Seres; och hans söner voro: Ulam och Rakem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Men Ulams son var Bedan. Detta är Gileads barn, Machirs sons, Manasse sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Och hans syster Molecheth födde Ishod, Abieser och Mahela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Och Semida hade dessa barnen: Ahjan, Sechem, Likhi och Aniam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Ephraims barn voro desse: Suthelah. Hans son var Bered; hans son var Thahath; hans son var Elada; hans son var Thahath;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Hans son var Sabad; hans son var Suthelah, Eser och Elad. Och de män i Gath, infödde i landena, dråpo dem, derföre att de nederdragne voro till att taga bort deras boskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Och deras fader Ephraim sörjde i långan tid, och hans bröder kommo till att hugsvala honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Och han besof sina hustru; hon vardt hafvandes, och födde en son, och han kallade hans namn Beria, derföre att illa tillgick i hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Hans dotter var Seera. Hon byggde nedra och öfra BethHoron och UssenSeera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Hans son var Repha; hans son var Reseph och Thelah; hans son var Thahan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Hans son var Laedan; hans son var Ammihud; hans son var Elisama;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Hans son var Nun; hans son var Josua.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Och deras ägor och boning var BethEl och dess döttrar, och österut af Naaran, och vesterut ifrå Geser och dess döttrar; Sechem och dess döttrar, allt intill Assa och dess döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Och intill Manasse barn, BethSean och dess döttrar; Thaanach och dess döttrar; Megiddo och dess döttrar; Dor och dess döttrar. Deruti bodde Josephs barn, Israels sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Assers barn voro desse: Jimna, Jisva, Jisvi, Beria, och Serah deras syster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Beria barn voro: Heber och Malchiel, det är Birsaviths fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heber födde Japhlet, Somer, Hotham, och Suah deras syster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Japhlets barn voro: Pasach, Bimhal och Asvath; desse voro Japhlets barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Somers barn voro: Ahi, Rohgah, Jehubba och Aram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Och hans broders Helems barn voro: Sopha, Jimna, Seles och Amal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Sopha barn voro: Suah, Harnepher, Sual, Beri, Jimra,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bszer, Hod, Samma, Silsa, Jithran och Beera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Jethers barn voro: Jephunne, Phispah och Ara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ulla barn voro: Arah, Haniel och Rizia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Desse voro alle Assers barn, höfvitsmän, i deras fäders hus utvalde, väldige män, och hufvud öfver Förstar, och vordo räknade i här till strids vid deras tal, sex och tjugu tusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'BenJamin födde Bela sin första son, Asbel den andra, Ahrah den tredje,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nohah den fjerde, Rapha den femte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Och Bela hade barn: Addar, Gera, Abihud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naaman, Ahoah,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sephuphan och Huram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Desse äro Ehuds barn, som hufvud voro för de fäder, som bodde i Geba, och drogo bort till Manahath;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Nämliga Naaman, Ahia och Gera, den samme förde dem bort; och han födde Ussa och Ahihud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Och Saharaim födde i Moabs land, (då han hade låtit dem ifrå sig) af Husim och Baara sinom hustrum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Och han födde af Hodes sine hustru Jobab, Zibia, Mesa, Malcham,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeuz, Sachia och Mirma. Desse äro hans barn, hufvud för fäderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Af Husim födde han Abitob och Elpaal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Elpaals barn voro: Eber, Misam och Samed; den samme byggde Ono och Lod, och dess döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Och Beria och Serna voro hufvud för fäderna ibland dem som bodde i Ajalon; de förjagade dem som bodde i Gath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Men hans broder, Sasak, Jeremoth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Sebadia, Arad, Ader,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michael, Jispa och Joha. Desse äro Beria barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Sebadia, Mesullam, Hiski, Heber,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jismerai, Jislia, Jobab. Desse äro Elpaals barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jakim, Sichri, Sabdi,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai, Zillethai, Eliel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja och Simrath. Desse äro Simri barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jispan, Eber, Eliel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Sichri, Hanan,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hanania, Elam, Anthothia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jiphdeja och Pnuel. Desse äro Sasaks barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Samserai, Seharia, Athalia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaresia, Elia och Sichri. Desse äro Jerohams barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Desse äro hufvud för fäderna i deras ätter; de bodde i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Men i Gibeon bodde fadren Gibeon; och hans hustru het Maacha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Och hans förste son var Abdon, Zur, Kis, Baal, Nadab,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahio och Secher.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Men Mikloth födde Simea; och de bodde tvärsemot deras bröder i Jerusalem med sinom brödrom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner födde Kis, Kis födde Saul, Saul födde Jonathan, MalchiSua, AbiNadab och Esbaal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Jonathans son var MeriBaal. MeriBaal födde Micha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Micha barn voro: Pithon, Melech, Thaerea och Ahas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Ahas födde Joadda. Joadda födde Alemeth, Asmaveth och Simri. Simri födde Moza.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Moza födde Binea; hans son var Rapha; hans son var Eleasa; hans son var Azel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Men Azel hade sex söner. De heto: Asrikam, Bochru, Ismael, Searia, Obadja, Hanan. De äro alle Azels söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Eseks barn, hans broders, voro: Ullam hans förste son, Jeus den andre, Eliphelet den tredje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Men Ullams barn voro väldige män, och välbehändige med bågar och hade många söner och sonasöner, hundrade och femtio. De äro alle af BenJamins barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Och hele Israel vardt räknad, och si, de äro uppskrifne i Israels och Juda Konungars bok, och nu bortförde till Babel för sina missgerningars skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'De som tillförene bodde på sina ägor och städer, nämliga Israel, Prester, Leviter och de Nethinim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Men i Jerusalem bodde någre af Juda barn, någre af BenJamins barn, någre af Ephraims och Manasse barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Nämliga utaf Perez barn, Juda sons, var Athai, Ammihuds son, Omri sons, Imri sons, Bani sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Men af Siloni, Asaja förste sonen, och hans andre söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Af Serahs barn, Jeguel och deras bröder, sexhundrad och niotio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Af BenJamins barn, Sallu, Mesullams son, Hodavia sons, Hassenua sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Och Jibneja, Jerohams son. Och Ela, Ussi son, Michri sons, och Mesullam, Sephatia son, Reguels sons, Jibneja sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Dertill deras bröder uti deras ätter, niohundrad och sex och femtio. Alle desse männerna voro höfvitsmän för fäderna uti deras fäders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Af Presterna, Jedaja, Jojarib, Jachin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Och Asaria, Hilkia son, Mesullams sons, Zadoks sons, Merajoths sons, Ahitobs sons, en Förste i Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Och Adaja, Jerohams son, Pashurs sons, Malchia sons; och Masai, Adiels son, Jahsera sons, Mesullams sons, Mesillemiths sons, Immers sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Dertill deras bröder höfvitsmän i deras fäders huse, tusende sjuhundrad och sextio starke män, till att beställa hvad ämbetet tillhörde i Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Men af Leviterna, af Merari barnom, Semaja, Hasubs son, Asrikams sons, Hasabia sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Och Bakbakkar, den timbermannen, och Galal; och Matthania, Micha son, Sichri sons, Assaphs sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Och Obadja, Semaja son, Galals sons, Jeduthuns sons, och Berechia, Asa son, Elkana sons, den som uti de Netophathiters byar bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Dörravaktarena voro: Sallum, Akkub, Talmon, Ahiman, med deras bröder; och Sallum, öfversten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Ty härtill hade vaktat för Konungsporten östantill Levi barn, i lägre,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Sallum, Kore son, Ebiasaphs sons, Korahs sons, och hans bröder utu hans faders hus, de Korhiter, vid ämbetets sysslo, att de vaktade vid tabernaklets dörrar, och deras fader i Herrans lägre, att de skulle vakta på ingången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Men Pinehas, Eleazars son, var Försten öfver dem, derföre att Herren hade tillförene varit med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zacharia, Meselemia son, var väktare vid vittnesbördsens tabernakels dörr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Alle desse voro utvalde till väktare vid dörrarna, tuhundrad och tolf. De voro räknade i deras byar. Och David och Samuel Siaren stiktade dem genom deras tro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Att de och deras barn skulle taga vara på Herrans hus, nämliga på tabernaklets hus, att de det vakta skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'De samme dörravaktare voro ställde på fyra sidor, östan, vestan, norr, söder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Men deras bröder voro i sina byar, så att de ju inkommo på sjunde dagen, till att alltid vara när dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Förty Leviterna voro dessom fyra öfversta dörravaktaromen betrodde, och de voro öfver kistorna och skatten i Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Och blefvo de öfver nattena omkring Guds hus; ty dem hörde vakten till, att de skulle upplåta hvar morgon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Och somlige af dem voro öfver ämbetstygen; förty de båro dem tald ut och in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Och somlige af dem voro beställde öfver kärilen, och öfver all helig redskap; öfver semlomjöl, öfver vin, öfver oljo, öfver rökelse, öfver rökverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Men Presternas barn gjorde somlige rökverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Mattithia utaf Leviterna, dem första Sallums sone, den Korhitens, voro betrodda pannorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Utaf de Kehathiter deras bröder, voro till att bereda skådobröden, så att de tillredde dem på hvar Sabbathsdag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Desse äro de sångare, höfvitsmän ibland Leviternas fäder, öfver kistorna skickade; förty dag och natt voro de der öfver i sysslomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Desse äro höfvitsmän förfäderna ibland Leviterna uti deras ätter; och bodde i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'I Gibeon bodde Jegiel, Gibeons fader; hans hustru het Maacha;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Och hans förste son Abdon, Zur, Kis, Baal, Ner, Nadab,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahio, Zacharia, Mikloth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Men Mikloth födde Simeam; de bodde också omkring deras bröder i Jerusalem, ibland sina bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner födde Kis. Kis födde Saul. Saul födde Jonathan, MalchiSua, AbiNadab, Esbaal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Jonathans son var Meribaal; Meribaal födde Micha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Micha barn voro: Pithon, Melech och Thahrea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahas födde Jaera. Jaera födde Alemeth, Asmaveth och Simri. Simri födde Moza.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Moza födde Binea. Hans son var Rephaja, Hans son var Eleasa. Hans son var Azel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Azel hade sex söner; de heto: Asrikam, Bochru, Ismael, Searia, Obadja, Hanan. Desse äro Azels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'De Philisteer stridde emot Israel, och de af Israel flydde för de Philisteer, och de slagne föllo på Gilboa berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Och de Philisteer gåfvo sig hardt in på Saul och hans söner, och slogo Jonathan, AbiNadab och MalchiSua, Sauls söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Och striden vardt skarp emot Saul; och de bågaskyttar kommo inpå honom, så att han blef sår af skyttorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Då sade Saul till sin vapnedragare: Drag ditt svärd ut, och stick mig igenom dermed, att desse oomskorne icke komma och fara skamliga med mig. Men hans vapnedragare ville icke; ty han fruktade sig svårliga. Då tog Saul sitt svärd, och föll deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Som nu hans vapnedragare såg, att Saul var död, föll han ock på svärdet, och blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Alltså blef Saul död, och hans tre söner, och hans hela hus tillika.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Då nu de män af Israel, som i dalenom voro, sågo att de voro flydde, och att Saul och hans söner voro döde, öfvergåfvo de sina städer, och flydde; och de Philisteer kommo, och bodde deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Den andra morgonen kommo de Philisteer till att afkläda de slagna, och funno Saul och hans söner liggande på Gilboa berg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Och klädde honom af, och togo hans hufvud och hans vapen, och sände uti de Philisteers land allt omkring, och läto förkunnat för deras afgudar och folkena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Och lade hans vapen i deras guds hus; och hans hufvud slogo de på Dagons hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Då nu alle de i Jabes i Gilead hörde allt det de Philisteer Saul gjort hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Reste de upp alle stridsamme män, och togo Sauls lekamen, och hans söners, och förde dem till Jabes, och begrofvo deras ben under den eken i Jabes; och fastade i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Alltså blef Saul död i sine missgerning, som han emot Herran gjort hade, emot Herrans ord, det han icke höll; också derföre, att han frågade spåqvinnona,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Och icke frågade Herran; derföre drap han honom, och vände riket till David, Isai son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Och hele Israel samlade sig: till David i Hebron, och sade: Si, vi äre ditt ben och ditt kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Och tillförene, medan Saul var Konung, förde du Israel ut och in; så hafver ock Herren din Gud sagt till dig: Du skall föda mitt folk Israel, och du skall vara en Förste öfver mitt folk Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Kommo också alle Israels äldste till Konungen i Hebron. Och David gjorde ett förbund med dem i Hebron för Herranom. Och de smorde David till Konung öfver Israel, efter Herrans ord, genom Samuel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Och David drog åstad, och hele Israel, till Jerusalem, det är Jebus; ty de Jebuseer bodde i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Och de borgare i Jebus sade till David: Du skall icke komma härin. Men David vann den borgen Zion, det är Davids stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Och David sade: Den som de Jebuseer först slår, han skall vara hufvud och öfverste. Då steg Joab, ZeruJa son, först upp, och vardt höfvitsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Och David bodde på borgene; deraf kallar man henne Davids stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Och han byggde staden omkring, ifrå Millo och sedan allt omkring; och Joab lät lefva dem som qvare voro i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Och David hade framgång, och kom sig före; och Herren Zebaoth var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Desse äro de öfverste ibland Davids väldiga, de der manliga höllo med honom i hans rike, när hela Israel, så att man gjorde honom till Konung, efter Herrans ord, öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Och detta är talet på Davids väldiga män: Jasabeam, Hachmoni son, den ypperste ibland tretio; han hof sin spets upp, och slog trehundrad i en gång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Näst honom var Eleazar, Dodo son, den Ahohiten, och han var ibland de tre väldiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Denne var med David, då de talade hädelse, och de Philisteer sig der församlat hade till strid; och var ett stycke åker fullt med bjugg, och folket flydde för de Philisteer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Och de trädde midt uppå åkerstycket, och undsatte det, och slogo de Philisteer; och Herren gaf en stor salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Och de tre utaf de yppersta tretio drogo neder till bergshällen till David, i den kulona Adullam; men de Philisteers lägre var i Rephaims dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Och David var i borgene; och de Philisteers folk var på den tid i BethLehem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Och David fick lusta, och sade: Ho vill gifva mig dricka af det vattnet i den brunnen i BethLehem, under portenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Då slogo desse tre genom de Philisteers lägre, och hemtade vatten utu brunnen i BethLehem, under portenom, och båro till David. Men han ville icke drickat, utan utgöt det Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Och sade: Det låte Gud vara långt ifrå mig, att jag detta göra skulle, och dricka dessa mäns blod i deras lifsfara; förty de hafva det hemtat med sins lifs fara; derföre ville han icke drickat. Det gjorde de tre hjeltar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abisai, Joabs broder, han var den ypperste ibland tre, och han hof sin spets upp, och slog trehundrad, och han var beprisad ibland tre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Och han den tredje härligare än de två, och var deras öfverste; men till de tre kom han icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, Jojada son, IsHails sons, den mycket bedrifvit hade, af Kabzeel, han slog tu de Moabiters lejon; och gick neder, och slog ett lejon midt i brunnenom i snötiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Han slog ock en Egyptisk man; han var fem alnar lång, och hade en spets i handene såsom ett väfträ; men han gick ned till honom med en staf, och tog honom spetsen utu handene, och drap honom med hans egen spets.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Det gjorde Benaja, Jojada son, och vardt beprisad ibland tre hjeltar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Och var den härligaste ibland tretio; men till de tre kom han icke; honom gjorde David till sitt hemliga råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'De stridsamme hjeltar äro desse: Asahel, Joabs broder, Elhanan, Dodo son af BethLehem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammoth den Haroriten, Helez den Peloniten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, Ikkes son, den Thekoiten, Abieser den Anthothiten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbechai den Husathiten, Ilai den Ahohiten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharai den Netophathiten, Heled, Baana son, den Netophathiten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ithai, Ribai son, af Gibea, BenJamins barnas, Benaja den Pirgathoniten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai af de bäcker Gaas, Abiel den Arbathiten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Asmaveth den Baharumiten, Eliahba den Saalboniten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Hasems barn den Gisonitens, Jonathan, Sage son, den Hararitens,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiam, Sachars son, den Hararitens, Eliphal, Urs son,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hepher den Mecherathiten, Ahija den Peloniten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hezro den Carin eliten, Naarai, Esbai son,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, Nathans broder, Mibhar, Hagri son,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zelek den Ammoniten, Naharai den Berothiten, Joabs vapnedragare, ZeruJa sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira den Jithriten, Gareb den Jithriten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uria den Hetheen, Sabad, Ahelai son,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, Sisa son, den Rubeniten, en höfvitsmän för de Rubeniter, och tretio voro under honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, Maacha son, Josaphat den Mithniten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ussija den Asthrathiten, Sama och Jegiel, Hothams söner, den Aroeritens,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, Simri son, Joha hans broder, den Thiziten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel den Mahaviten, Jeribai och Josavja, Elnaams söner, Jithma den Moabiten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obed, och Jasiel af Mezobaja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Och kommo desse till David i Ziklag, då han ännu flyktig var för Saul, Kis son; och de voro också ibland de hjeltar, som hulpo till strid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Och voro skickeliga med bågar, på båda händer, till stenar, pilar och bågar, af Sauls bröder, de af BenJamin voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Den ypperste Ahieser, och Joas, Semaa barn, den Gibeathitens, Jesiel, och Paleth, Asmaveths barn, Beracha, och Jehu den Anthothiten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Jismaja den Gibeoniten, väldig ibland tretio, och öfver tretio, Jeremia, Jahasiel, Johanan, Josabad den Gederathiten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Elusai, Jerimoth, Bealia, Semaria, Sephatia den Hariphiten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, Jissija, Asareel, Joeser, Jasabeam, de Korhiter,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joela, och Sebadia, Jerohams barn af Gedor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Af de Gaditer söndrade sig ut till David, på borgene i öknene, starke hjeltar och krigsmän, som sköld och spjut förde, och deras ansigte såsom lejons, och raske såsom rår uppå bergen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Den förste, Eser; den andre, Obadja; den tredje, Eliab;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Den fjerde, Mismanna; den femte, Jeremia;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Den sjette, Atthai; den sjunde, Eliel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Den åttonde, Johanan; den nionde, Elsabad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Den tionde, Jeremia; den ellofte, Machbannai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Desse voro af Gads barnom, höfvitsmän i härenom, den ringaste öfver hundrade, och den ypperste öfver tusende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Desse äro de, som öfver Jordan gingo i första månadenom, då han full var till båda bräddar, så att alle dalar jemne voro både östan och vestan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Kommo ock desslikes af BenJamins barn och Juda till Davids borg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Och David gick ut till dem, och svarade, och sade till dem: Om I kommen med frid till mig, och till att hjelpa mig, så skall mitt hjerta vara med eder; kommen I ock på arga list att vara mig emot, der dock ingen missgerning i mig är, så se våra fäders Gud dertill, och straffe det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Så iklädde Guds Ande Amasai höfvitsmannen öfver tretio, och han sade: Dine äre vi, David, och med dig hålle vi, du Isai son; frid, frid vare med dig; frid vare med dina hjelpare; förty din Gud hjelper dig. Då tog David dem till sig, och satte dem till höfvitsmän öfver krigsfolket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Och af Manasse föllo till David, då han kom med de Philisteer emot Saul till strid, och halp dem dock intet; ty de Philisteers Förstar gingo till råds, och viste honom bort ifrå sig, och sade: Om han fölle till sin herra Saul, så måtte det gälla vår hals.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Då han nu igen drog till Ziklag, föllo till honom af Manasse, Adna, Josabad, Jediael, Michael, Josabad, Elihu, Zillethai, höfvitsmän öfver tusende i Manasse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Och de hulpo David emot krigsfolket; ty de voro alle mägtige hjeltar, och vordo höfvitsmän öfver hären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Och kommo hvar dag någre till David, honom till hjelp, tilldess det vardt en stor här, såsom en Guds här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Och detta är talet på de höfvitsmän, som utrustade kommo till David i Hebron, till att vända Sauls rike till honom efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Juda barn, som sköld och spjut båro, voro sextusend och åttahundrad, väl utredde till strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Simeons barn, mägtige hjeltar till strid, sjutusend och hundrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Levi barn, fyratusend och sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Och Jojada, den Försten ibland dem af Aaron, med tretusend och sjuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Zadok den unge mannen, en mägtig hjelte, med sins faders hus, två och tjugu öfverste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'BenJamins barn, Sauls bröder, tretusend; ty allt intill den tiden höllo ännu månge med Sauls hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Ephraims barn, tjugutusend och åttahundrad, mägtige hjeltar och namnkunnige män uti deras faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Utaf den halfva slägt ene Manasse adertontusend, som vid namn nämnde vordo, att de skulle komma och göra David till Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Utaf Isaschars barn, de förståndige voro, då tiden så krafde, att man visste hvad Israel göra skulle, tuhundrad höfvitsmän; och alle deras bröder följde deras ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Utaf Sebulon, de som i här drogo till strid, väpnade med allahanda vapen till strid, femtiotusend, endrägtige till att skicka sig i ordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Utaf Naphthali tusend höfvitsmän, och med dem de som sköld och spjut förde, sju och tretio tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Utaf Dan väpnade till strid, åtta och tjugu tusend sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Utaf Asser, de som i här drogo väpnade till strid, fyratiotusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Ifrå hinsidon Jordan utaf de Rubeniter, Gaditer och den halfva Manasse slägten, med allahanda vapen till strid, hundrade och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Alle desse krigsmän, väl skickade till strid, kommo af allo hjerta till Hebron, att göra David till Konung öfver hela Israel; och var alla de andras af Israel ett hjerta, att man skulle göra David till Konung;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Och voro der när David i tre dagar, åto och drucko; förty deras bröder hade tillredt för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Och de som näst omkring dem voro, allt intill Isaschar, Sebulon och Naphthali, de förde bröd på åsnar, camelar, mular och oxar, till att äta; mjöl, fikon, russin, vin, oljo, oxar och får, allt fullt; ty en fröjd var i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Och David höll ett råd med de höfvitsmän öfver tusende, och öfver hundrade, och med alla Förstar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Och sade till hela Israels menighet: Täckes eder, och är det af Herranom vårom Gud, så låt oss allestäds utsända till de andra våra bröder i all Israels land, och till Presterna och Leviterna i städerna, der de förstäder hafva, att de varda till oss församlade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Och låt oss hem ta till oss igen vår Guds ark; ty i Sauls tid frågade vi intet efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Då sade hela menigheten, att man skulle så göra; ty detta täcktes allo folkena väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Alltså församlade David hela Israel allt ifrå Sihor vid Egypten, intilldess man kommer till Hamath, till att hemta Guds ark ifrå KiriathJearim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Och David drog upp med hela Israel till Baalath, det är KiriathJearim, som i Juda ligger, att han skulle dädan uppföra Herrans Guds ark, den på Cherubim sitter, der Namnet åkalladt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Och de läto föra Guds ark uppå en ny vagn, utur AbiNadabs hus. Men Ussa och Ahio drefvo vagnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Och David med hela Israel spelade framför Gudi med all magt, med sånger, med harpor, med psaltare, med trummor, med cymbaler, och med basuner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Som de nu kommo uppå den platsen Chidon, räckte Ussa ut sina hand, till att hålla arken; förty oxarne gingo afsides.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Då förgrymmade sig Herrans vrede öfver Ussa, och slog honom, derföre att han hade räckt sina hand ut på arken, så att han der död blef för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Då vardt David bedröfvad, att Herren hade sönderrifvit Ussa, och kallade det rummet PerezUssa, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Och David fruktade sig för Gud den dagen, och sade: Huru skall jag hafva Guds ark in till mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Derföre lät han icke föra in till sig Guds ark uti Davids stad, utan förde honom in uti ObedEdoms hus, den Gitthitens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Alltså blef Guds ark när ObedEdom i hans huse i tre månader. Och Herren välsignade ObedEdoms hus, och all det han hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Och Hiram, Konungen i Tyro, sände båd till David, och cedreträ, murmästare och timbermän, att de skulle bygga honom ett hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Och David förmärkte, att Herren hade stadfäst honom till Konung öfver Israel; ty hans rike steg upp för hans folks Israels skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Och David tog ännu flera hustrur i Jerusalem, och födde ännu flera söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Och de honom födde vordo i Jerusalem, heto alltså: Sammua, Sobab, Nathan, Salomo,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar, Elisua, Elephelet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Noga, Nepheg, Japhia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, BelJada, Eliphelet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Och då de Philisteer hörde, att David var smord till Konung öfver hela Israel, drogo de alle upp till att söka David. Då David det hörde, drog han ut emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Och de Philisteer kommo, och lade sig neder i Rephaims dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Men David frågade Gud, och sade: Skall jag draga upp emot de Philisteer, och vill du gifva dem i mina hand? Herren sade till honom: Drag upp, jag hafver gifvit dem i dina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Och då de drogo upp till BaalPerazim, slog David dem der. Och David sade: Gud hafver förskingrat mina fiendar genom mina hand, såsom vattnet förskingras. Deraf kallade de det rummet BaalPerazim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Och de läto der deras gudar, hvilka David böd uppbränna i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Men de Philisteer gjorde åter redo, och lade sig neder i dalenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Och David frågade åter Gud. Och Gud sade till honom: Du skall icke draga upp efter dem; utan böj ifrå dem, att du må komma emot dem in mot päronaträn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'När du då hörer ett ruskande ofvan i päronaträn gångandes, så far ut till stridena; ty Gud är der utdragen för dig, till att slå de Philisteers här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Och David gjorde såsom Gud honom budit hade. Och de slogo de Philisteers här, allt ifrå Gibeon intill Gaser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Och Davids namn gick ut i all land. Och Herren lät hans räddhåga komma öfver alla Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Och han byggde sig hus uti Davids stad, och tillredde ett rum till Guds ark, och gjorde ett tabernakel öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'På den tiden sade David: Guds ark bör icke bäras, utan af de Leviter; ty dem hafver Herren utvalt, att de skola bära Guds ark, och tjena honom evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Derföre församlade David hela Israel till Jerusalem, att de skulle bära Herrans ark upp i det rum, som han dertill beredt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Och David lät komma tillhopa Aarons barn, och Leviterna:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Utaf Kehats barn, Uriel, den öfversten, med hans bröder, tjugu och hundrade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Utaf Merari barn, Asaja, den öfversten, med hans bröder, tjugu och tuhundrade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Utaf Gersoms barn, Joel, den öfversten, med hans bröder, tretio och hundrade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Utaf Elisaphans barn, Semaja, den öfversten, med hans bröder, tuhundrade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Utaf Hebrons barn, Eliel, den öfversten, med hans bröder, åttatio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Utaf Ussiels barn, Amminadab, den öfversten, med hans bröder, tolf och hundrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Och David kallade Zadok och AbJathar, Presterna och Leviterna, nämliga Uriel, Asaja, Joel, Semaja, Eliel, Amminadab;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Och sade till dem: I ären hufvuden för fäderna ibland de Leviter; så helger eder nu och edra bröder, att I mågen uppbära Herrans Israels Guds ark dit, der jag honom tillredt hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Ty tillförene, när I icke voren tillstädes, gjorde Herren vår Gud en refvo ibland oss, derföre att vi icke sökte honom, såsom det borde sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Alltså helgade Presterna sig och Leviterna, att de skulle uppbära Herrans Israels Guds ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Och Levi barn båro Guds ark på sina axlar, med stängerna dervid, såsom Mose budit hade efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Och David sade till de öfverstar för de Leviter, att de skulle sätta sina bröder till sångare, med strängaspel, med psaltare, harpor och klingande cymbaler, så att de högt söngo och med fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Då beställde de Leviter Hem an, Joels son, och utaf hans bröder Assaph, Berechia son, och utaf Merari barn deras bröder, Ethan, Kusaja son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Och med dem deras bröder af det andra skiftet, nämliga Zacharia, Ben, Jaesiel, Semiramoth, Jehiel, Unni, Eliab, Benaja, Maaseja, Mattithia, Elipheleja, Mikneja, ObedEdom, Jegiel, dörravaktarena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Ty Heman, Assaph och Ethan voro sångare med kopparcymbaler, att klinga högt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Men Zacharia, Asiel, Semiramoth, Jehiel, Unni, Eliab, Maaseja och Benaja, med psaltare, till att sjunga efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Men Mattithia, Elipheleja, Mikneja, ObedEdom, Jegiel och Asasia, med harpor af åtta stränger, till att sjunga för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Men Chenanja, Leviternas öfverste sångmästare, att han skulle undervisa dem om sången, ty han var förståndig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Och Berechia och Elkana voro dörravaktare om arken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Men Sechania, Josaphat, Nethaneel, Amasai, Zacharia, Benaja, Elieser, Presterna, blåste med trummeter för Guds ark. Och ObedEdom och Jehia voro dörravaktare om arken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Alltså gingo David och de äldste i Israel, och de öfverste öfver tusende upp, till att hem ta Herrans förbunds ark utur ObedEdoms hus med fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Och medan Gud halp Leviterna, som båro Herrans förbunds ark, offrade man sju stutar och sju vädrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Och David hade en linnan kjortel uppå; så ock alle Leviter, som arken båro, och sångarena och Chenanja sångmästaren, med sångarena; hade också David en linnan lifkjortel uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Alltså båro hele Israel Herrans förbunds ark upp med fröjd, basuner, trummeter och klingande cymbaler, med psaltare och harpor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Då nu Herrans förbunds ark kom uti Davids stad, såg Michal, Sauls dotter, ut genom fenstret; och då hon fick se Konung David springa och spela, föraktade hon honom i sitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Då de båro Guds ark in, satte de honom uti tabernaklet, som David honom beredt hade; och offrade bränneoffer och tackoffer för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Och då David hade fullkomnat bränneoffren och tackoffren, välsignade han folket i Herrans Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Och utskifte hvarjom och enom i Israel, både man och qvinno, ett stycke bröd, och kött, och ett mätt vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Och han satte inför Herrans ark några Leviter till tjenare, att de skulle prisa, tacka och lofva Herran Israels Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Nämliga Assaph den första, Zacharia den andra, Jegiel, Semiramoth, Jehiel, Mattithia, Eliab, Benaja, ObedEdom; och Jegiel med psaltare och harpor; men Assaph med klingande cymbaler;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Och Benaja och Jahasiel, Presterna, med trummeter, alltid för Guds förbunds ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'På den tiden beställde David i förstone att tacka Herranom, genom Assaph och hans bröder:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Tacker Herranom, prediker hans Namn; förkunner ibland folken hans verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Sjunger honom, speler, och taler om all hans under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Lofver hans helga Namn; deras hjerta fröjde sig, som söka Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Söker efter Herran, och efter hans magt; söker hans ansigte alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Tänker på hans under, som han gjort hafver; på hans under, och hans ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'I Israels hans tjenares säd, I Jacobs hans utkorades barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Han är Herren vår Gud, han dömer i allo verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Kommer ihåg hans förbund evinnerliga; hvad han utlofvat hafver i tusende slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Hvilket han gjort hafver med Abraham, och hans ed med Isaac.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Och han satte det Jacob till en rätt, och Israel till ett evigt förbund,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Och sade: Jag skall gifva dig Canaans land, edar arfvedels lott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Då de få och ringa voro, och främlingar derinne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Och de drogo ifrå det ena folket till det andra, och utur ett rike bort till ett annat folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Han lät ingen göra dem skada; och för deras skull straffade han Konungar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Kommer icke vid mina smorda; och görer intet ondt mina Propheter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Sjunger Herranom all land; förkunner dageliga hans salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Förtäljer ibland Hedningarna hans härlighet; och hans under ibland folken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Ty Herren är stor, och fast loflig; och underlig öfver alla gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Förty alle Hedningars gudar äro afgudar; men Herren hafver gjort himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Det står härliga och kosteliga till för honom, och går krafteliga och gladeliga till i hans rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Bärer fram Herranom, I folk; bärer fram Herranom äro och magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Bärer fram Herrans Namne äro; bärer fram skänker, och kommer för honom, och tillbeder Herran i heligo prydelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'All verlden frukte för honom; han hafver befäst jordena, så att hon intet röres.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Fröjde sig himmelen, och jorden vare glad; och man må säga ibland Hedningarna, att Herren är rådandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Hafvet dåne, och hvad deruti är; och marken vare glad, och hvad deruppå är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Fröjde sig all trä i skogen för Herranom: ty han kommer till att döma jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Tacker Herranom, ty han är god, och hans barmhertighet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Och säger: Hjelp oss, Gud vår Frälsare, och församla oss, och hjelp oss ifrå Hedningarna, att vi måge tacka dino helgo Namne, och lofsäga dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Lofvad vare Herren Israels Gud, ifrån evighet till evighet; och allt folket säge Amen, och lofve Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Alltså lät han der för Herrans förbunds ark Assaph och hans bröder, till att tjena inför arken alltid, och hvar dag i sitt dagsverk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Men ObedEdom och hans bröder, åtta och sextio; och ObedEdom, Jeduthuns son, och Hosa till dörravaktare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Och Zadok Presten, och hans bröder Presterna, lät han inför Herrans tabernakel, på höjdene i Gibeon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Att de dageliga skulle göra Herranom bränneoffer, uppå bränneoffrens altare, om morgon och afton, såsom skrifvet står uti Herrans lag, som han Israel budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Och med dem Heman och Jeduthun, och de andra utvalda, som vid namn benämnde voro, till att tacka Herranom, att hans barmhertighet varar evinnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Och med dem Heman och Jeduthun, med trummeter och cymbaler, till att klinga, och med Guds strängaspel. Men Jeduthuns söner gjorde han till dörravaktare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Alltså drog allt folket sin väg, hvar och en i sitt hus. Drog också David bort till att välsigna sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Det begaf sig, då David bodde i sitt hus, sade han till Propheten Nathan: Si, jag bor uti cedrehus; och Herrans förbunds ark under tapeter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Nathan sade till David: Allt det i ditt hjerta är, det gör; ty Gud är med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Men i samma natt ene kom Guds ord till Nathan, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Gack och säg minom tjenare David: Detta säger Herren: Du skall icke bygga mig ett hus till boning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Förty jag hafver icke bott uti något hus, ifrå den dag, då jag Israels barn utförde, allt intill denna dagen; utan jag hafver varit der tabernaklet varit hafver, och boningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Ehvar jag vandrade i hela Israel, hafver jag ock någor tid talat till någon domare i Israel, den jag budit hafver, att föda mitt folk, och sagt: Hvi byggen I icke mig ett cedrehus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Så säg nu alltså till min tjenare David: Detta säger Herren Zebaoth: Jag hafver tagit dig utaf markene, der du följde fåren, att du skulle vara en Förste öfver mitt folk Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Och hafver varit med dig, ehvart du for, och hafver utrotat dina fiendar för dig; och hafver gjort dig ett namn, såsom de store på jordene namn hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Men jag skall sätta mino folke Israel ett rum, och skall plantera det, så att det skall der bo, och icke mer rördt varda; och arghetens barn skola icke mer qvälja det, såsom tillförene,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Och på den tiden, då jag böd domarena öfver mitt folk Israel. Och jag skall undertrycka alla dina fiendar; och förkunnar dig, att Herren vill bygga dig ett hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'När nu dine dagar ute äro, att du går till dina fäder, så skall jag uppväcka dina säd efter dig, den en af dina söner vara skall, honom vill jag bereda ett rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Han skall bygga mig ett hus, och jag vill stadfästa hans stol till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Jag skall vara hans fader, och han skall vara min son; och jag skall icke vända mina barmhertighet ifrå honom, såsom jag vände henne ifrå honom, som för dig var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Utan jag skall sätta honom i mitt hus, och uti mitt rike evinnerliga, så att hans stol skall blifva beständig i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Och då Nathan efter all desso ord och syn talat hade med David,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Kom Konung David, och blef inför Herranom, och sade: Ho är jag, Herre Gud? Och hvad är mitt hus, att du hafver låtit mig komma härtill?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Och dig hafver ändå icke tyckt det nog vara, Gud; utan du hafver ock öfver dins tjenares hus ännu talat om tillkommande ting i framtiden, och hafver sett till mig, Herre Gud, ofvanefter, såsom en menniska den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Hvad skall David mer säga till dig, att du skulle ära din tjenare? Du känner din tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Herre, för din tjenares skull, efter ditt hjerta hafver du all sådana stor ting gjort, att du skulle all storhet kunnoga göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Herre, ingen är din like, och ingen Gud är utan du, af hvilkom vi med vår öron hört hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Och hvar är något folk på jordene, såsom ditt folk Israel, dit en Gud gången är, till att förlossa sig ett folk, och göra sig sjelfvom ett Namn af stor och förskräckelig ting, till att utdrifva Hedningar för dino folke, som du utur Egypten förlossat hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Och hafver gjort ditt folk Israel dig till folk evinnerliga, och du, Herre, äst deras Gud vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Nu, Herre, det ord, som du talat hafver öfver din tjenare, och öfver hans hus, varde sant i evig tid, och gör såsom du sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Och ditt Namn varde sant och stort i evig tid, att man säga må: Herren Zebaoth Israels Gud är Gud i Israel; och dins tjenares Davids hus vare beständigt för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Ty du, min Gud, hafver öppnat din tjenares öra, att du vill bygga honom ett hus; derföre hafver din tjenare funnit, att han inför dig beder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Nu, Herre, du äst Gud, och du hafver sådana god ting sagt till din tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Tag nu till att välsigna dins tjenares hus, att det blifver evinnerliga för dig; ty hvad du, Herre, välsignar, det är välsignadt evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Derefter slog David de Philisteer, och undertryckte dem, och tog Gath och dess döttrar utu de Philisteers hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Slog han ock de Moabiter, så att de Moabiter vordo David underdånige, och förde honom skänker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Han slog ock HadarEser, Konungen i Zoba, uti Hamath, då han dit drog, till att uppresa sitt tecken vid den älfvena Phrath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Och David vann af honom tusende vagnar, sjutusend resenärar, och tjugutusend män till fots och David hasade alla vagnhästarna, och behöll hundrade vagnar qvara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Och de Syrer af Damasco kommo HadarEser, Konungenom i Zoba, till hjelp; men David slog de samma Syrer, tu och tjugu tusend män;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Och lade folk till Damascon i Syrien, så att de Syrer vordo David underdånige, och förde honom skänker; ty Herren halp David, ehvart han for.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Och David tog de gyldene sköldar, som HadarEsers tjenare hade, och förde dem till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Tog också David utu HadarEsers städer, Tibhath och Chun, ganska mycken koppar, af hvilkom Salomo kopparhafvet, och stoderna och kopparkärilen gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Och då Thou, Konungen i Hamath, hörde, att David hade slagit alla HadarEsers magt, Konungens i Zoba;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Sände han sin son Hadoram till Konung David, och lät helsa och välsigna honom, att han med HadarEser stridt, och honom slagit hade; ty Thou hade örlig med HadarEser. Och all gyldene, silfver, och kopparkärile,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Dem helgade Konung David Herranom, med det silfver och guld, som han tagit hade ifrå Hedningarna, nämliga ifrå de Edomeer, Moabiter, Ammoniter, Philisteer och Amalekiter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Och Abisai, ZeruJa son, slog de Edomeer i saltdalenom, adertontusend;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Och lade folk i Edomeen; så att alle Edomeer voro David underdånige; ty Herren halp David, ehvart han drog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Alltså regerade David öfver hela Israel, och höll rätt och rättvisa allo sino folke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, ZeruJa son, var öfver hären; Jojaphat, Ahiluds son, var canceller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Zadok, Ahitobs son, och AbiMelech, AbJathars son, voro Prester; Sausa var skrifvare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja, Jojada son, var öfver Crethi och Plethi; och de förste Davids söner voro Konungenom vid handen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Så begaf sig derefter, att Nahas, Ammons barnas Konung, blef död, och hans son vardt Konung i hans stad,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Då tänkte David: Jag vill göra barmhertighet på Hanun, Nahas son; ty hans fader hafver gjort barmhertighet med mig. Och han sände dit båd, till att hugsvala honom efter hans fader. Och då Davids tjenare kommo uti Ammons barnas land, till Hanun, att hugsvala honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Sade de Förstar för Ammons barn till Hanun: Menar du, att David ärar din fader för din ögon, att han sänder hugsvalare till dig? Ja, hans tjenare äro komne till dig, till att utfråga, bespana och bespeja landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Då tog Hanun Davids tjenare, och rakade dem, och skar deras kläder half bort allt intill länderna, och lät gå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Och de gingo sin väg, och bådade det David med några män. Han sände emot dem; förty männerna voro svårliga beskämde, och Konungen sade: Blifver i Jericho, tilldess edart skägg växer, sedan kommer då igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Då Ammons barn sågo, att de illa luktade för David, sände de bort, både Hanun och Ammons barn, tusende centener silfver, till att besolda sig vagnar och resenärar utu Mesopotamien, utu Syrien Maacha, och utu Zoba;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Och besoldade tu och tretio tusend vagnar, och Konungen i Maacha med hans folk. De kommo och lägrade sig för Medba. Och Ammons barn församlade sig desslikes utu sina städer, och kommo till strids.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Då David det hörde, sände han Joab dit, med hela de hjeltars här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Och Ammons barn voro utdragne, och skickade sig till strid för stadsporten; men Konungarna, som komne voro, höllo besynnerliga i markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Då nu Joab såg, att både för honom och bak honom var strid emot honom, utvalde han af alla unga män i Israel, och skickade sig emot de Syrer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Det andra folket fick han under Abisai sin broders hand, att de skulle draga emot Ammons barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Och sade: Om de Syrer varda mig för starke, så kom mig till hjelp; om Ammons barn varda dig för starke, så vill jag komma dig till hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Var tröst, och låt oss trösteliga handla för vårt folk, och för vår Guds städer. Herren göre hvad honom täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Och Joab drog fram med det folk, som med honom var, till att strida emot de Syrer; och de flydde för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Då nu Ammons barn sågo, att de Syrer flydde, flydde de ock för Abisai hans broder, och drogo in i staden; men Joab drog till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Som de Syrer sågo, att de för Israel slagne voro, sände de ut båd, och läto utkomma de Syrer på hinsidon älfven; och Sophach, HadarEsers härhöfvitsman, drog för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Då det blef sagdt David, församlade han hela Israel, och drog öfver Jordan; och då han kom till dem, skickade han sig emot dem. Och David skickade sig emot de Syrer till strid, och de stridde med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Men de Syrer flydde för Israel; och David slog af de Syrer sjutusend vagnar, och fyratiotusend män till fot; dertill drap han Sophach härhöfvitsmannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Då HadarEsers tjenare sågo, att de voro slagne för Israel, gjorde de frid med David och hans tjenare. Och de Syrer ville icke mer hjelpa Ammons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Och då året omgånget var, på den tid som Konungar utdraga, utförde Joab hären, och förderfvade Ammons barnas land; kom och belade Rabba; men David blef i Jerusalem. Och Joab slog Rabba, och bröt det neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Och David tog deras Konungs krono af hans hufvud, och fann deruti en centener gulds vigt och ädla stenar; och hon vardt satt på Davids hufvud; förde han ock ganska mycket rof utu staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Men folket derinne förde han ut, och lät sönderdela dem med sågar och jernhackor och kilar; alltså gjorde David alla Ammons barnas städer. Och David drog med folkena till Jerusalem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Derefter hof sig en strid upp i Gaser med de Philisteer. På den tiden slog Sibbechai, den Husathiten, Sippai, den utaf Rephaims barnom var, och undertryckte honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Och det hof sig ännu en strid upp med de Philisteer. Då slog Elhanan, Jairs son, Lahmi, Goliaths broder den Gitthiten, hvilkens spjutskaft var såsom ett väfträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Åter vardt en strid i Gath. Der var en stor man, han hade sex finger och sex tår, det gör fyra och tjugu. Han var också födder af Rapha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Han bespottade Israel; men Jonathan, Simea son, Davids broders, slog honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Desse voro födde af Rapha i Gath, och föllo genom Davids och hans tjenares hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Och Satan hof sig upp emot Israel, och gaf David in, att han lät räkna Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Och David sade till Joab, och till folkens öfverstar: Går bort, och räkner Israel, allt ifrå BerSeba intill Dan; och bärer till mig, att jag må veta talet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab sade: Herren föröke till sitt folk hundrade sinom så mycket som det nu är: Min herre Konung, äro de icke alle mins herras tjenare? Hvi frågar då min herre derefter? Hvi skulle en skuld komma på Israel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Men Konungens ord gick fram emot Joab; och Joab drog ut, och for omkring all Israel, och kom till Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Och fick David talet på det räknade folket; och det var af hela Israel ellofva sinom hundrade tusend män, som svärd utdrogo; och Juda fyrahundrade sinom tusend, och sjutiotusend män, som svärd utdrogo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Men Levi och BenJamin räknade han intet ibland dessa; förty Konungens ord var Joab en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Men Gudi misshagade detta; och han slog Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Och David sade till Gud: Jag hafver svårliga syndat, att jag detta gjort hafver; men nu tag dins tjenares missgerning bort; förty jag hafver fast dårliga gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Och Herren talade med Gad, Davids Siare, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Gack, tala med David, och säg: Detta säger Herren: Treggehanda sätter jag dig före; utvälj dig der ett af, det jag dig göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Då Gad kom till David, sade han till honom: Detta säger Herren:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Utvälj dig, antingen tre hård år, eller tre månaders flykt för dina ovänner, och för dina fiendars svärd, det du icke undkomma kan; eller tre dagar Herrans svärd och pestilentie i landena, så att Herrans Ängel förderfvar i alla Israels gränsor; så se nu till, hvad jag skall svara honom, som mig utsändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'David sade till Gad: Mig är fast ångest; dock vill jag falla i Herrans hand; ty hans barmhertighet är ganska stor; och icke falla i menniskohand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Då lät Herren komma pestilentie i Israel, så att sjutiotusend män föllo af Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Och Gud sände Ängelen till Jerusalem till att slå det; och när han förderfvade, såg Herren dertill, och ångrade det onda, och sade till Ängelen, som förderfvade: Det är nog, håll dina hand tillbaka. Men Herrans Ängel stod vid Arnans, den Jebuseens lado.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Och David hof upp sin ögon, och fick se Herrans Ängel stå emellan himmelen och jordena, och ett draget svärd i hans hand, uträckt öfver Jerusalem. Då föll David och de äldste på sin ansigte, klädde i säcker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Och David sade till Gud: Är icke jag den som lät räkna folket? Jag är den som syndade och det onda gjort hafver; dessa far, hvad hafva de gjort? Herre, min Gud, låt dina hand vara emot mig och mins faders hus, och icke emot ditt folk, till plågo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Och Herrans Ängel sade till Gad, att han skulle säga David, att David skulle gå upp, och resa Herranom ett altare i Arnans, den Jebuseens, lado.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Alltså gick David upp efter Gads ord, som han i Herrans Namn talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Men då Arnan vände sig, och såg Ängelen, han och hans fyra söner med honom, gömde de sig bort; ty Arnan tröskade vete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Som nu David gick till Arnan, såg Arnan och vardt varse David, och gick utaf ladone, och tillbad David på sitt ansigte till jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Och David sade till Arnan: Gif mig ladones rum, att jag må bygga Herranom ett altare deruppå; för fulla penningar skall du få mig det, att plågan på folket må återvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Arnan sade till David: Tag dig det, och gör, min herre Konung, såsom dig täckes. Si, jag gifver också oxarna till bränneoffret, och redskapen till ved, och hvete till spisoffer; alltsamman gifver jag det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Men Konung David sade till Arnan: Icke så, utan för fulla penningar vill jag köpat; ty jag vill icke taga det ditt är för Herranom, och göra bränneoffer till gifvins.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Alltså gaf David Arnan, för rummet, gyldene siktar till vigt sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Och David byggde dersammastäds Herranom ett altare, och offrade bränneoffer och tackoffer; och då han åkallade Herran, hörde han honom genom eld af himmelen uppå bränneoffrets altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Och Herren sade till Ängelen, att han skulle sticka sitt svärd i skidona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'På samma tiden, då David såg, att Herren hade hört honom uppå Arnans den Jebuseens plats, offrade han der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Ty Herrans tabernakel, som Mose i öknene gjort hade, och bränneoffrets altare, var i den tiden på höjdene i Gibeon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Men David kunde icke gå ditin för det, till att söka Gud; så var han förskräckt för Herrans Ängels svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Och David sade: Här skall Herrans Guds hus vara, och detta altaret till Israels bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Och David lät församla de främlingar, som i Israels land voro, och beställde stenhuggare, till att hugga sten till Guds hus byggning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Och David tillredde mycket jern till naglar åt dörrena i portomen, och hvad tillhopanaglas skulle; och så mycken koppar, att han icke stod till vägandes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Och cedreträ utan tal; förty de af Zidon och Tyro förde mycket cedreträ till David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Ty David tänkte: Min son Salomo är en ung pilt och späd; men huset, som Herranom byggas skall, måste vara stort, att dess namn och lof utgå må i all land derföre vill jag skaffa honom virke. Alltså skaffade David mycket virke, förr än han dödde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Och han kallade sin son Salomo, och böd honom bygga Herrans Israels Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Och sade till honom: Min son, jag hade i sinnet att bygga Herrans mins Guds Namne ett hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Men Herrans ord kom till mig, och sade: Du hafver mycket blod utgjutit, och fört stort örlig: derföre skall du icke bygga mino Namne hus, efter du så mycket blod utgjutit hafver för mig på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Si, din son, som dig skall född varda, han skall vara en rolig man; förty jag vill låta honom få ro för alla hans fiendar allt omkring. Han skall heta Salomo; ty jag skall gifva frid och rolighet öfver Israel uti hans lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Han skall bygga mino Namne ett hus; han skall vara min son, och jag skall vara hans fader, och jag skall stadfästa hans Konungsliga stol öfver Israel till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Så varder nu, min son, Herren med dig blifvandes, och du skall blifva lyckosam, att du må bygga Herranom dinom Gud ett hus, såsom han om dig sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Och Herren varder dig gifvandes klokhet och förstånd, och skall befalla dig Israel, att du skall hålla Herrans dins Guds lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Men då varder du lyckosam, när du håller dig, att du gör efter de seder och rätter, som Herren Mose budit hafver till Israel. Var tröst och vid godt mod, frukta dig intet, och gif dig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Si, jag hafver i minom fattigdom förskaffat till Herrans hus hundradetusend centener guld och tusende resor tusende centener silfver; dertill koppar och jern utan tal, ty det är fast mycket. Hafver jag också beställt timber och stenar, det kan du ännu föröka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Så hafver du många arbetare, stenhuggare och timbermän till sten och trä, och allahanda kloka på allahanda verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'På guld, silfver, koppar och jern utan tal. Så statt nu upp, och beställ det; Herren skall vara med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Och David böd allom öfverstom i Israel, att de skulle hjelpa hans son Salomo:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Är icke Herren edar Gud med eder, och hafver gifvit eder rolighet allt omkring? Ty han hafver gifvit landsens inbyggare uti edra händer, och landet är undergifvet vordet för Herranom, och för hans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Så gifver nu edor hjerta och edra själar, till att söka Herran edar Gud; och står upp, och bygger Herranom Gudi en helgedom, att man må bära Herrans förbunds ark och de heliga Guds kärilen in uti huset, som Herrans Namne skall bygdt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Alltså gjorde David Salomo, sin son, till Konung öfver Israel, då han gammal, och af lefvande mätt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Och David församlade alla öfverstar i Israel, och Presterna och Leviterna,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Att man skulle räkna Leviterna, ifrå tretio år och derutöfver; och deras tal var, ifrå hufvud till hufvud, det starke män voro, åtta och tretio tusend;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Af hvilkom voro fyra och tjugu tusend, som drefvo arbetet på Herrans hus; och sextusend ämbetsmän och domare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Och fyratusend dörravaktare; och fyratusend lofsångare Herranom med strängaspel, som jag till lofsång gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Och David gjorde en ordning ibland Levi barn, nämliga ibland Gerson, Kehath och Merari.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Då Gersoniter voro: Laedan och Simei.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Laedans barn: Den förste Jehiel, Setam och Joel, de tre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Men Simei barn voro: Selomith, Hasiel och Haran, de tre. Desse voro de ypperste ibland fäderna af Laedan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Voro också desse Simei barn: Jahath, Sina, Jeus och Beria. Desse fyra voro ock Simei barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahath var den förste, Sisa den andre. Men Jeus och Beria hade icke mång barn; derföre vordo de räknade för ens faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kehaths barn voro: Amram, Jizear, Hebron och Ussiel, de fyra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amrams barn voro: Aaron och Mose. Men Aaron vardt afskild, så att han vardt helgad till det aldrahelgasta, han och hans söner, till evig tid, till att röka för Herranom, och till att tjena och välsigna i Herrans Namn i evig tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Och Mose, den Guds mansens, barn vordo nämnde ibland de Leviters slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mose barn voro: Gersom och Elieser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Gersoms barn: Den förste var Sebuel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Eliesers barn: Den förste var Rehabia. Och Elieser hade inga annor barn; men Rehabia barn voro mycket flere.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Jizears barn voro: Selomith den förste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebrons barn voro: Jeria den förste, Amaria den andre, Jahasiel den tredje, och Jekameam den fjerde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Ussiels barn voro: Micha den förste, och Jissija den andre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Merari barn voro: Maheli och Musi. Maheli barn voro: Eleazar och Kis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Men Eleazar blef död, och hade inga söner, utan döttrar; och Kis barn, deras bröder, togo dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Musi barn voro: Maheli, Eder och Jeremoth, de tre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Detta äro Levi barn i deras faders hus, och de ypperste af fäderna, som räknade vordo, efter namnens tal efter hufvuden, hvilke gjorde de sysslor i ämbeten i Herrans hus, ifrå tjugu år, och derutöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Ty David sade: Herren Israels Gud hafver gifvit sino folke ro, och skall bo i Jerusalem till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Leviterna behöfde ock icke bära tabernaklet, med all dess redskap, efter deras ämbete;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Utan, efter Davids yttersta ord, vordo Levi barn räknade ifrå tjugu år, och derutöfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Att de skulle stå under Aarons barnas händer, till att tjena i Herrans hus, i gårdenom, och till kistorna, och till reningen, och till allahanda helgedom, och till alla ämbetens sysslor i Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Och till skådobröd, till semlomjöl, till spisoffer, till osyrade kakor, till pannor, till halster, och till all vigt och mått;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Och till att stå om morgonen, och tacka och lofva Herran; om aftonen desslikes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Och till att offra Herranom all bränneoffer på Sabbatherna, nymånadom och högtidom, efter talet och sättet, alltid för Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Att de skulle taga vara på vaktena vid vittnesbördsens tabernakel, och helgedomens; och Aarons barnas, deras bröders, till att tjena i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Men Aarons barnas ordning var denna: Aarons barn voro Nadab, Abihu, Eleazar och Ithamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Men Nadab och Abihu blefvo döde inför deras fader, och hade inga barn; och Eleazar och Ithamar vordo Prester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Och David skickade dem alltså, Zadok af Eleazars barn, och Ahimelech af Ithamars barn, efter deras tal och ämbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Och vordo Eleazars barn flere funne till yppersta starka män än Ithamars barn. Och han skickade dem alltså; nämliga sexton utaf Eleazars barn, till öfverstar ibland deras fäders hus; och åtta af Ithamars barn ibland deras fäders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Och han skifte dem efter lott, derföre, att både af Eleazars och Ithamars barn voro öfverstar i helgedomenom, och öfverstar för Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Och skrifvaren Semaja, Nethaneels son, utaf Leviterna, beskref dem för Konungenom, och för öfverstarna, och för Zadok Prestenom, och för Ahimelech, AbJathars son, och för öfversta fäderna ibland Presterna och Leviterna; nämliga ett fadershus för Eleazar, och det andra för Ithamar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Och förste lotten föll uppå Jojarib, den andre uppå Jedaja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Den tredje på Harim, den fjerde på Seorim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Den femte på Malchija, den sjette på Mijamin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Den sjunde på Hakkoz, den åttonde på Abia;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Den nionde på Jesua, den tionde på Sechania;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Den ellofte på EljaSib, den tolfte på Jakim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Den trettonde på Huppa, den fjortonde på Jesebeab;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Den femtonde på Bilga, den sextonde på Immer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Den sjuttonde på Hesir, den adertonde på Happizez;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Den nittonde på Petahja, den tjugonde på Jeheskel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Den förste och tjugonde på Jachin, den andre och tjugonde på Gamul;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Den tredje och tjugonde på Delaja, den fjerde och tjugonde på Mahasia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Detta är ordningen efter deras ämbeten, till att gå i Herrans hus efter deras sätt, under deras fader Aaron, såsom Herren Israels Gud dem budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Men utaf de andra Levi barn, af Amrams barn var Subael. Af Subaels barn var Jehdeja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Af Rehabia barn var den förste Jissija.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Men af de Jizeariter var Selomoth. Af Selomoths barn var Jahath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, '(Hebrons) barn voro: Jeria den förste, Amaria den andre, Jahasiel den tredje, Jekameam den fjerde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Ussiels barn voro: Micha. Utaf Micha barn var Samir.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Micha broder var Jissija. Utaf Jissija barn var Zacharia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Merari barn voro: Maheli och Musi; hans son var Jaasia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Merari barn, af Jaasia, hans son, voro: Soham, Saccur och Ibri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Men Maheli hade Eleazar, och Eleazar hade inga söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Af Kis: Kis barn voro: Jerahmeel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Musi barn voro: Maheli, Eder och Jerimoth. Detta äro de Leviters barn, i deras faders hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Och man kastade också för dem lott, bredovid deras bröder Aarons barn, inför Konung David och Zadok, och Ahimelech, och inför de öfversta fäderna af Prestomen och Levitomen, dem minsta brodrenom så väl som dem öfversta af fäderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Och David, samt med härhöfvitsmännerna, afskiljde till ämbete af Assaphs barn, Heman och Jeduthun, de Propheterna med harpor, psaltare och cymbaler; och de vordo talde till verket, efter sitt ämbete:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Utaf Assaphs barn: Saccur, Joseph, Nethania, Asarela, Assaphs barn, under Assaph, som propheterade när Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Af Jeduthun: Jeduthuns barn voro: Gedalia, Zeri, Jesaja, Hasabia, Mattithia, de sex, under deras fader Jeduthun, med harpor, hvilke propheterade till att tacka och lofva Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Af Heman: Hemans barn voro: Bukkija, Matthania, Ussiel, Sebuel, Jerimoth, Hanania, Hanani, Eliatha, Giddalthi, RomamthiEser, Josbekasa, Mallothi, Hothir och Mahasioth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Desse voro alle Hemans barn, Konungens Siares i Guds ordom, till att upphöja hornet; ty Gud hade gifvit Heman fjorton söner och tre döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Desse voro alle under deras fäder Assaph, Jeduthun och Heman, till att sjunga i Herrans hus med cymbaler, psaltare och harpor, efter ämbetet i Guds hus när Konungen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Och talet på dem, med deras bröder, som i Herrans sång lärde voro, allesammans mästare, tuhundrad åtta och åttatio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Och de kastade lott öfver deras ämbete, dem minsta såsom dem största; mästarenom såsom lärjunganom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Och den förste lotten föll på Joseph under Assaph; den andre på Gedalia, med hans bröder och söner, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Den tredje på Saccur, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Den fjerde på Jizri, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Den femte på Nethania, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Den sjette på Bukkija, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Den sjunde på Jesarela, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Den åttonde på Jesaja, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Den nionde på Matthania, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Den tionde på Simei, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Den ellofte på Asareel, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Den tolfte på Hasabia, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Den trettonde på Subael, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Den fjortonde på Mattithia, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Den femtonde på Jeremoth, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Den sextonde på Hanania, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Den sjuttonde på Josbekasa, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Den adertonde på Hanani, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Den nittonde på Mallothi, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Den tjugonde på Elijatha, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Den förste och tjugonde på Hothir, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Den andre och tjugonde på Giddalthi, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Den tredje och tjugonde på Mahasioth, med hans söner och bröder, de voro tolf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Den fjerde och tjugonde på RomamthiEser, med hans söner och bröder, de voro tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Om dörravaktarenas ordning: Utaf de Korhiter var Meselemia, Kore son, af Assaphs barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Meselemia barn voro desse: Den förstfödde Zacharia, den andre Jediael, den tredje Sebadja, den fjerde Jathniel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Den femte Elam, den sjette Johanan, den sjunde Eljoenai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Men ObedEdoms barn voro desse: Den förstfödde Semaja, den andre Josabad, den tredje Joah, den fjerde Sacar, den femte Nethaneel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Den sjette Ammiel, den sjunde Isaschar, den åttonde Peulthai; ty Gud hade välsignat honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Och hans sone Semaja vordo ock söner födde, som i deras fäders hus regerade; ty de voro starke hjeltar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Så voro nu Semaja barn: Othni, Rephael, Obed, och Elsabad, hvilkens bröder mägtige män voro, Elihu och Semachia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Desse voro alle utaf ObedEdoms barn; de med deras barn och bröder, mägtige män, skicklige till ämbete, två och sextio af ObedEdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselemia hade barn och bröder, mägtige män, aderton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Men Hosa utaf Merari barnom hade barn: Den ypperste Simri; ty den förstfödde var icke till, derföre satte hans fader honom främst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Den andre Hilkia, den tredje Tebalia, den fjerde Zacharia. All Hosa barn och bröder voro tretton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Detta är dörravaktarenas ordning, bland höfdingarna i ämbetet med deras bröder, till att tjena i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Och lotten vardt kastad dem litsla såväl som dem stora, i deras fäders hus till hvarjo dörrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Den lotten österut föll på Selemia; men hans sone Zacharia, hvilken en klok och rådig man var, kastade man lotten, och honom föll norrut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Men ObedEdom söderut, och hans sönom vid huset Asuppim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Och Suppim och Hosa, vesterut vid dörrena Sallecheth, på bränneoffers vägenom, der vakterna vid hvarandra stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Österut voro sex af Leviterna, norrut fyra om dagen, söderut fyra om dagen; men vid Asuppim ju två och två;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Vid Parbar, vesterut, fyra på vägenom, och två vid Parbar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Detta är dörravaktarenas ordning, ibland de Korhiters barn, och Merari barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Utaf Leviterna var Ahija öfver halvorna i Guds hus; och öfver de håfvor, som helgada vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Af Laedans barn, de Gersoniters barn; af Laedan voro höfdingar ibland fäderna, nämliga de Jehieliter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'De Jehieliters barn voro: Setham och hans broder Joel, öfver Herrans hus håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Utaf de Amramiter, Jizeariter, Hebroniter och Asieliter,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Var Sebuel, Gersoms son, Mose sons, en Förste öfver håfvorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Men hans broder Elieser hade en son Rehabia. Hans son var Jesaja; hans son var Joram; hans son var Sichri; hans son var Selomith.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Den samme Selomith och hans bröder voro öfver alla de helgada tings håfvor, hvilka Konung David helgade, och de öfverste fäderna ibland de öfversta öfver tusende och öfver hundrade, och de öfverste i härenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Utaf strid och rof hade de helgat det, till att förbättra Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Desslikes allt det Samuel Siaren, och Saul Kis son, och Abner, Ners son, och Joab, ZeruJa son, helgat hade; allt det helgada var under Selomiths hand, och hans bröders.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Utaf de Jizeariter var Chenanja med sina söner, till de verk utantill, öfver Israel befallningsmän och domare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Utaf de Hebroniter var Hasabia och hans bröder, mägtige män, tusende och sjuhundrade, öfver Israels ämbete, på desso sidone Jordan vesterut, till allahanda Herrans sysslo, och till att tjena Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Var ock ibland de Hebroniter Jeria, den ypperste ibland de Hebroniter, af fäderna i hans ätt. Det vordo ock af dem sökte och funne, uti fyrationde årena af Davids rike, mägtige män, i Jaeser i Gilead;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Och deras bröder, mägtige män, tutusend och sjuhundrad öfverste fäder. Och David satte dem öfver de Rubeniter, Gaditer, och öfver den halfva slägtena Manasse, till all Guds och Konungens ärende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Men Israels barn efter sitt tal voro höfdingar öfver fäderna, och öfver tusende, och öfver hundrade; och ämbetsmän, som på Konungen vaktade, efter deras ordning, till att draga till och frå, hvar i sin månad, i hvar månad om året. Hvart skiftet hade fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Öfver första skiftet i första månadenom var Jasabeam, Sabdiels son; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Men af Perez barnom var den öfverste öfver alla höfvitsmännerna i härarna i första månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Öfver det skiftet i den andra månaden var Dodai den Ahohiten; och Mikloth var Förste öfver hans skifte; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Den tredje härhöfvitsmannen i tredje månadenom, den öfverste, var Benaja, Jojada Prestens son; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Denne är Benaja, den hjelten ibland tretio, och öfver tretio; och hans skifte var under hans son Ammisabad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Den fjerde i fjerde månadenom var Asahel, Joabs broder, och efter honom Sebadia, hans son; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Den femte i femte månadenom var Samhuth den Jisrahiten; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Den sjette i sjette månadenom var Ira, Ikkes den Thekoitens son; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Den sjunde i sjunde månadenom var Helez den Peloniten, af Ephraims barn; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Den åttonde i åttonde månadenom var Sibbechai den Husathiten, af de Sarhiter; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Den nionde i nionde månadenom var Abieser den Anthothiten, af Jemini barn; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Den tionde i tionde månadenom var Maharai den Netophathiten, af de Serahiter; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Den ellofte i ellofte månadenom var Benaja den Pirgathoniten, af Ephraims barn; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Den tolfte i tolfte månadenom var Heldai den Netophathiten, af Athniel; och i hans skifte voro fyra och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Öfver Israels slägter voro desse: För de Rubeniter var Förste Elieser, Sichri son; för de Simeoniter var Sephatia, Maacha son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'För de Leviter var Hasabia, Kemuels son; för de Aaroniter var Zadok;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'För Juda var Elihu af Davids bröder; för Isaschar var Omri, Michaels son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'För Sebulon var Jismaja, Obadja son; för Naphthali var Jerimoth, Asriels son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'För Ephraims barn var Hosea, Asasia son; för den halfva slägtene Manasse var Joel, Phedaja son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'För den halfva slägtene Manasse i Gilead var Jiddo, Zacharia son; för BenJamin var Jaasiel, Abners son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'För Dan var Asarel, Jerohams son Detta äro de Förstar för Israels slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Men David tog intet tal af dem som voro tjugu åra, och der för nedan; ty Herren hade sagt, att han skulle föröka Israel såsom stjernorna på himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Men Joab, ZeruJa son, hade begynt räkna, och lyktade det icke; ty en vredo kom fördenskull öfver Israel, derföre kom det talet icke uti Konung Davids Chrönico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Öfver Konungens håfvor var Asmaveth, Adiels son; och öfver de håfvor på landena, i städer, byar och slott, var Jonathan, Ussija son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Öfver åkermännerna till landsbruket var Esri, Chelubs son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Öfver vingårdarna var Simei den Ramathiten; öfver vinkällarena och vinet var Sabdi den Siphmiten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Öfver oljogårdarna, och mulbärträ i markene var BaalHanan den Gederiten; öfver oljona var Joas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Öfver den boskap, som i bet var i Saron, var Sithrai den Saroniten; men öfver den boskap i dalomen var Saphat, Adlai son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Öfver camelarna var Obil den Ismaeliten; öfver åsnarna var Jehdeja den Meronothiten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Öfver fåren var Jasis den Hagariten, Desse voro alle öfverstar öfver Konung Davids ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Men Jonathan, Davids faderbroder, var rådgifvare, hofmästare och canceller; Jehiel, Hachmoni son, var när Konungens barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitophel var ock Konungens rådgifvare; Husai den Arachiten var Konungens vän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Efter Achitophel var Jojada, Benaja son, och AbJathar; men Joab var Konungens härhöfvitsman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Och David församlade till Jerusalem alla Israels öfverstar, nämliga Förstarna för slägterna, Förstarna för skiften, som på Konungen vaktade; Förstarna öfver tusende, och öfver hundrade; Förstarna öfver Konungens och hans söners ägodelar och boskap; med kamererare, krigsmän och alla mägtiga män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Och Konung David stod upp på sina fötter, och sade: Hörer härtill, mine bröder, och mitt folk: Jag hafver tagit mig före att bygga ett hus, der Herrans förbunds ark uti hvilas skulle, och en fotapall till vår Guds fötter, och hade redt mig till att bygga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Men Gud lät säga mig: Du skall icke bygga mino Namne hus; förty du äst en krigsman, och hafver blod utgjutit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Nu hafver Herren Israels Gud utvalt mig utu hela mins faders hus, att jag skulle vara Konung öfver Israel till evig tid; ty han hafver utvalt Juda till ett Förstadöme; och i Juda huse, mins faders hus, och ibland mins faders barn hafver han haft ynnest till mig, så att han gjorde mig till Konung öfver hela Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Och ibland alla, mina söner (ty Herren hafver gifvit mig många söner) hafver han utvalt min son Salomo, att han sitta skall på Herrans rikes stol öfver Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Och hafver sagt till mig: Din son Salomo skall bygga mitt hus och gårdar; ty jag hafver utvalt mig honom till son, och jag skall vara hans fäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Och skall stadfästa hans rike i evig tid, om han håller uppå att göra efter min bud och rätter, såsom i denna dag tillgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nu inför hela Israel Herrans menighet, och för vår Guds öron, så håller och söker all Herrans edars Guds bud; på det I mågen besitta detta goda landet, och ärfva det till edor barn efter eder, till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Och du, min son Salomo, känn dins faders Gud, och tjena honom af allt hjerta, och af en välviljog själ; ty Herren ransakar all hjerta, och förstår alla tankars uppsåt. Om du söker honom, så finner du honom; om du öfvergifver honom, så förkastar han dig till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Så se nu till, ty Herren hafver utvalt dig, att du skall bygga honom ett hus till helgedom. Var tröst, och gör så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Och David gaf sinom son Salomo en eftersyn till förhuset, och till sitt hus, och till maken, och till salen, och till kamrar innantill, och till nådastolens hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Dertill en eftersyn till allt det i hans sinne var, nämliga till gården åt Herrans hus, och till all maken omkring, till håfvorna i Guds hus, och de, helgada tings håfvor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Till Presternas och Leviternas skifte, och till alla sysslor i ämbeten uti Herrans hus, och till alla tjenstenes käril i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Guld efter gulds vigt, till allahanda tyg i hvart ämbetet, och allahanda silftyg, efter vigt, till allahanda redskap i hvart ämbetet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Och vigt till gyldene ljusastakar och gyldene lampor, hvarjom ljusastaka och hans lampor sina vigt; sammalunda ock till silfljusastakar gaf han vigt, till ljusastaka och hans lampor, efter hvars ljusastakans ämbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Gaf han desslikes guld till skådobrödsborden, till hvart bordet sina vigt; sammalunda ock silfver till silfborden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Och klart guld till gafflar, backen och kannor; och till gyldene skålar, hvar skål sina vigt; och till silfskålar, hvar skål sina vigt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Och till rökaltaret sina vigt, det aldraklaresta guld; och en eftersyn till vagnen för de gyldene Cherubim, så att de uträckte sig, och öfvertäckte Herrans förbunds ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Alltsammans, sade han, är mig gifvet, beskrifvet af Herrans hand, som mig underviste all eftersynenes verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Och David sade till sin son Salomo: Var tröst och frimodig, och gör så; frukta dig intet, och var icke förskräckt; Herren Gud, min Gud, skall vara med dig, och skall icke draga sina hand ifrå dig, eller förlåta dig, allt intill du all verk till ämbeten i Herrans hus fullkomnat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Si, Presternas och Leviternas ordning till all ämbeten i Guds hus, äro med dig i all ärende, och äro viljoge och förståndige till all ämbeten; dertill Förstarna och allt folket i alla dina handlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Och Konung David sade till hela menigheten: Gud hafver utvalt Salomo, en af mina söner, den ännu ung och späd är; men verket är stort, ty det är icke ens menniskos boning, utan Herrans Guds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Men jag hafver utaf alla mina krafter beredt till Guds hus, guld till gyldene, silfver till silfvers, koppar till koppars, jern till jerns, trä till träs redskap; onichstenar, infattada rubiner och spräcklota stenar, och allahanda ädla stenar, och marmorsten ganska mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Derutöfver, af ynnest till mins Guds hus, hafver jag det mitt eget är, guld och silfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Tretusend centener guld af Ophir, och sjutusend centener klart silfver, det gifver jag till Guds helga hus, utöfver allt det jag förskickat hafver till att öfverdraga väggarna i husen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Så att af guld blifver det af guld vara skall, och af silfver det af silfver vara skall, och till allahanda verk igenom mästarenas hand. Och ho är nu i dag friviljog till att fylla sina hand Herranom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Då voro Förstarna för fäderna, Förstarna för Israels slägter, Förstarna öfver tusend och öfver hundrad, och Förstarna öfver Konungsärenden, friviljoge;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Och gåfvo till ämbeten i Guds hus femtusend centener guld, och tiotusend gylden, och tiotusend centener koppar, och hundradetusend centener jern.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Och när hvilkom stenar funne vordo, dem gåfvo de till håfvor uti Herrans hus, under Jehiels hand, den Gersonitens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Och folket var gladt, att de så friviljoge voro; ty de gåfvo Herranom af allo hjerta friviljoge. Och Konung David fröjdade sig desslikes högeliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Och lofvade Herran, och sade inför hela menighetene: Lofvad vare du, Herre, Israels vår foders Gud, ifrån evighet till evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Dig, Herre, tillhörer majestät och magt, härlighet, seger och tack; ty allt det i himmelen och på jordene är, det är ditt; ditt, Herre, är riket, och du äst upphöjd öfver all ting till en öfversta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Dine äro rikedomar och härlighet för dig, du råder öfver all ting; i dine hand står kraft och magt, i dine hand står det att göra hvar och en stor och stark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nu, vår Gud, vi tacke dig, och prise dins härlighets Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Ty hvad är jag, hvad är mitt folk, att vi skulle åstadkomma kraft till att gifva friviljeliga, såsom nu tillgår? Ty af dig är det allt kommet, och af dine hand hafve vi det gifvit dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Förty vi äre främlingar och utländningar för dig, såsom alle våre fäder; vårt lefvande på jordene är såsom en skugge, och dväljs intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Herre vår Gud, all denna hopen, som vi tillskickat hafve till att bygga dino helgo Namne ett hus, är kommen ifrå dine hand; och ditt är det allt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Jag vet, min Gud, att du pröfvar hjertat, och enfaldighet är dig täck; derföre hafver jag allt detta utaf enfaldigo hjerta friviljeliga gifvit; och hafver nu sett med glädje ditt folk, som här för handene är, att det hafver friviljeliga gifvit dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Herre, våra fäders Abrahams, Isaacs och Israels Gud, bevara evinnerliga sådana håg och sinne i dins folks hjerta, och skicka deras hjerta till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Och minom son Salomo gif ett rättsinnigt hjerta, att han håller din bud, vittnesbörd och rätter, att han det allt gör, och bygger denna boning, som jag skickat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Och David sade till hela menighetena: Lofver Herran edar Gud. Och hela menigheten lofvade Herran deras fäders Gud, och bugade sig, och tillbådo Herran och Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Och de offrade Herranom offer; och den andra morgonen offrade de Herranom bränneoffer, tusende stutar, tusende vädrar, tusende lamb, med deras drickoffer; och offrade all hopen i hela Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Och åto och drucko den samma dagen för Herranom med stora glädje, och gjorde annan gången Salomo, Davids son, till Konung, och smorde honom Herranom till en Första, och Zadok till Prest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Alltså satt Salomo på Herrans stol, en Konung i sins faders Davids stad, och vardt lyckosam, och all Israel var honom hörsam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Och alle öfverstar och väldige, desslikes all Konung Davids barn, gåfvo sig under Konung Salomo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Och Herren gjorde Salomo ju större och större för hela Israel, och gaf honom ett härligit rike, att ingen för honom sådant öfver Israel haft hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Så var nu David, Isai son, Konung öfver hela Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Men tiden, som han öfver Israel Konung var, var fyratio år. I Hebron regerade han sju år, och i Jerusalem tre och tretio år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Och blef död i godom ålder, mätt af lefvande, rikedomar och äro; och hans son Salomo vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Men Konung Davids gerningar, både de första och de sista, si, de äro skrifna ibland Samuels den Siarens gerningar, och ibland den Prophetens Nathans gerningar, och ibland Gads den Siarens gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Med allt hans rike, välde och tid, som under honom förlupen är, både öfver Israel och all rike i landen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Och Salomo, Davids son, vardt i sitt rike förstärkt, och Herren hans Gud var med honom, och gjorde honom ju större och större.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Och Salomo talade med hela Israel, med de öfverstar öfver tusend och hundrade, med domare och alla Förstar i Israel, med de öfversta fäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Att de skulle gå, Salomo och hela menigheten med honom, bort till den höjden, som i Gibeon var; ty der var Guds vittnesbörds tabernakel, som Mose Herrans tjenare gjort hade i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Ty Guds ark hade David uppfört ifrå KiriathJearim, dit han för honom tillredt hade; förty han hade honom uppslagit ett tabernakel i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Men det kopparaltaret som Bezaleel, Uri son, Hurs sons, gjort hade, var der för Herrans tabernakel; och Salomo och menigheten plägade söka det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Och Salomo offrade för Herranom på kopparaltaret, som der för dörrene af vittnesbördsens tabernakel stod, tusende bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'I samma nattene syntes Gud Salomo, och sade till honom: Bed, hvad skall jag gifva dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Och Salomo sade till Gud: Du hafver gjort stora barmhertighet med minom fader David, och hafver gjort mig till Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Så låt nu, Herre Gud, din ord varda sann till min fader David; ty du hafver gjort mig till Konung öfver ett folk, det så mycket är som stoftet på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Så gif mig nu vishet och förstånd, att jag för detta folket må gå ut och in; ty ho förmår döma detta ditt myckna folk?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Då sade Gud till Salomo: Efter du hafver detta i sinnet, och hafver icke bedit om rikedomar, eller ägodelar, eller om härlighet, eller om dina fiendars själar, eller om långt lif; utan hafver bedit om visdom och förstånd, att du må döma mitt folk, der jag dig en Konung öfver gjort hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Så vare dig visdom och förstånd gifvet; dertill vill jag ock gifva dig rikedomar, ägodelar och härlighet, så att din like ibland Konungarna för dig icke varit hafver, ej heller varda skall efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Alltså kom Salomo ifrå höjdene, som i Gibeon var, till Jerusalem, ifrå vittnesbördsens tabernakel, och regerade öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Och Salomo församlade sig vagnar och resenärar, så att han åstadkom tusende och fyrahundrade vagnar, och tolftusend resenärar, och lät dem uti vagnsstäderna, och när Konungenom i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Och Konungen gjorde, att silfver och guld var i Jerusalem så mycket som stenar; och cedreträ så mycket som mulbärsträ i dalarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Och man förde Salomo hästar utur Egypten, och allahanda varor. Och Konungens köpmän köpte samma varor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Och förde dem utur Egypten, hvar vagn för sexhundrad silfpenningar, och hvar häst för hundrade och femtio; alltså förde man dem ock till alla de Hetheers Konungar, och till de Konungar i Syrien, genom deras hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Och Salomo satte sig före att bygga Herrans namne ett hus, och ett sins rikes hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Och afräknade sjutiotusend män till bördor, och åttatiotusend timbermän uppå berget, och tretusend och sexhundrad befallningsmän öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Och Salomo sände till Hyram, Konungen i Tyro, och lät säga honom: Såsom du med minom fader David gjorde, och sände honom cedreträ, att han skulle bygga sig ett hus, der han uti bo skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Si, jag vill bygga Herrans mins Guds Namne ett hus, att honom må helgadt varda, till att röka god rökverk för honom, och till alltid bereda skådobröd, och bränneoffer om morgon och afton, på Sabbather och nymånader, och på Herrans vår Guds högtider; till evig tid för Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Och det hus, som jag bygga vill, skall vara stort; förty vår Gud är större än alle gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Men ho är dess mägtig, att han bygger honom hus? Ty himmelen och alla himlars himlar kunna icke begripa honom. Ho skulle då jag vara, att jag skulle bygga honom hus? Utan att man må röka för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Så sänd mig nu en vis man, till att arbeta på guld, silfver, koppar, jern, skarlakan, rosenrödt, gult silke, och den som kan utgrafva med de visa, som när mig äro i Juda och Jerusalem, hvilka min fader David beställt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Och sänd mig cedreträ, furoträ och hebenträ af Libanon; förty jag vet, att dine tjenare kunna hugga trä på Libanon; och si, mine tjenare skola vara med dina tjenare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Att man tillreder mig mycket trä; ty huset, som jag bygga vill, skall vara stort och härligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Och si, jag vill gifva dina tjenare timbermannomen, som trä hugga, tjugutusend corar stött hvete, och tjugutusend corar bjugg, och tjugutusend bath vin, och tjugutusend bath oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Då sade Hyram, Konungen i Tyro, genom skrifvelse, och sände till Salomo: Derföre, att Herren hafver sitt folk kärt, hafver han gjort dig till Konung öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Och Hyram sade ytterligare: Lofvad vare Herren Israels Gud, som himmel och jord gjort hafver, att han gifvit hafver Konung David en visan, klokan och förståndigan son, som Herranom ett hus, och ett sins rikes hus bygga må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Så sänder jag nu en visan man, som förstånd hafver, nämliga Hyram Abiv;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Ene qvinnos son utaf Dans döttrar, och hans fader hade varit en Tyrer; han kan arbeta på guld, silfver, koppar, jern, sten, trä, skarlakan, gult silke, linnet, rosenrödt: och allahanda utgrafva, och göra allahanda konsteliga, det man honom föregifver, med dina visa, och med mins herras Konung Davids dins faders visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Så sände nu min herre hvete, bjugg, oljo och vin, till sina tjenare, såsom han sagt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Så vilje vi hugga trä på Libanon, så mycket som behöfves, och vilje låta det lägga i flottar i hafvet, in åt Japho; dädan må du låta föra det upp till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Och räknade Salomo alla främlingar i Israels land, efter det tal då David hans fader dem räknade; och vordo funne hundrade och femtio tusend, tretusend och sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Och han gjorde af dem sjutiotusend dragare, och åttatiotusend huggare på bergena, och tretusend och sexhundrad befallningsmän, som folket vid arbetet höllo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Och Salomo begynte till att bygga Herrans hus i Jerusalem, på Moria berg, det David hans fader utvist var, hvilket David tillredt hade för rum, på Arnans plats den Jebuseens;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Och tog till att bygga i dem andra månadenom, den andra dagen i fjerde årena af sitt rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Och alltså lade Salomo grundvalen, till att bygga Guds hus: i förstone, längden sextio alnar, bredden tjugu alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Och förhuset, för breddene af huset, var tjugu alnar långt, höjden var hundrade och tjugu alnar; och bedrog det innantill med klart guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Men det stora huset bedrog han med furoträ, och bedrog det med bästa guld, och gjorde deruppå palmar och kedjoverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Och bedrog huset med ädla stenar till prydelse; och guldet var Parvaims guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Och han bedrog huset, bjelkarna, dörrträn, väggarna och dörrarna med guld, och lät skära Cherubim på väggarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Han gjorde desslikes huset till det aldrahelgasta; dess längd var tjugu alnar efter husets bredd, och dess bredd var ock tjugu alnar; och bedrog det med bästa guld, vid sexhundrade centener.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Gaf han också till naglar femtio siklar guld i vigt; och bedrog salarna med guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Han gjorde ock uti dess aldrahelgastas huse två Cherubim, efter snickarekonst, och bedrog dem med guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Och längden af Cherubims vingar var tjugu alnar; så att en vingen hade fem alnar, och kom intill väggena af huset; den andre vingen hade ock fem alnar, och kom intill vingan af den andra Cherub.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Alltså hade ock en vingen af den andra Cherub fem alnar, och kom intill väggena af huset; och hans andre vinge ock fem alnar, och kom intill vingan af den andra Cherub;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Så att desse Cherubims vingar voro utsträckte tjugu alnar; och de stodo på sina fötter, och deras ansigte voro vänd åt huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Han gjorde ock en förlåt af gult verk, skarlakan, rosenrödt och linverk, och gjorde Cherubim deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Och han gjorde framför huset två stodar, fem och tretio alnar höga, och knappen der ofvanuppå fem alnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Och gjorde kedjoverk till choren, och satte ofvanuppå stoderna, och gjorde hundrade granatäple, och satte dem i det kedjoverket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Och reste de stoderna uppför templet, ena på den högra, och den andra på den venstra sidone; och kallade den på högra sidone Jachin, och den på venstra Boas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Han gjorde ock ett kopparaltare, tjugu alnar långt och bredt, och tio alnar högt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Och han gjorde ett gjutet haf, tio alnar bredt, ifrå den ena bräddene till den andra, rundt omkring, och fem alnar högt, och måttet omkring var tretio alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Och oxabeläte voro der nedan under, allt omkring; och voro två radar krusering omkring hafvet, det tio alnar bredt var, hvilke vidgjutne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Och det stod så på de tolf oxar, att tre vändes norrut, tre vesterut, tre söderut, och tre österut, och hafvet der ofvanuppå; och bakdelen af dem allom var inunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Tjockheten deraf var en tvärhand, och dess brädd var såsom ens bägares brädd, och en utsprungen ros; och det höll tretusend bath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Och han gjorde tio kettlar, af dem satte han fem på högra sidone, och fem på den venstra, till att två derutinnan hvad som bränneoffer tillhörde, att de skulle kasta det deruti; men hafvet var till att Presterna skulle två sig deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Han gjorde ock tio gyldene ljusastakar, såsom de vara skulle, och satte dem i templet, fem på den högra, och fem på den venstra sidone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Ock gjorde han tio bord, och satte dem i templet, fem på högra, och fem på venstra sidone; och han gjorde hundrade gyldene bäcken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Han gjorde ock en gård för Presterna, och en stor gård, och dörrar i gårdenom; och öfverdrog dörrarna med koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Och satte hafvet på högra sidone österut, sunnantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Och Hyram gjorde grytor, skoflar, och bäcken. Alltså lyktade Hyram arbetet, som Konung Salomo hade fått honom, på Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Nämliga de två stodar, med bukar, och knappar ofvanpå båda stoderna, och de båda vridna gjordar, till att betäcka båda bukarna åt knapparna, ofvanpå stoderna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Och de fyrahundrade granatäplen på de båda vridna gjordar, två radar granatäple på hvarjo gjordene, till att betäcka båda knapparnas bukar, som ofvanpå stoderna voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Ock gjorde han stolar, och kettlar uppå stolarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Och ett haf, och tolf oxar derunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Dertill grytor, skonar, gafflar och all deras tyg, gjorde Hyram Abiv åt Konung Salomo, till Herrans hus, utaf klar koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'I den ängden vid Jordan lät Konungen gjuta dem i lerjord, emellan Succoth och Zeredatha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Och Salomo gjorde all denna tygen ganska mång; så att vigten af den koppar icke utfrågas kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Och Salomo gjorde all tyg till Guds hus, nämliga gyldene altaret, bord till skådobröd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Ljusastakarna med deras lampor, af klart guld, att de skulle brinna för chorenom, såsom det borde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Och de blommor vid lamporna, och de näpor voro af guld; allt var af rent guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Dertill knifvar, bäcken, slefvar och släcketyg, voro af klart guld; och ingången, och hans dörr innantill, åt det aldrahelgasta, och dörrarna till tempelshuset, voro af guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Alltså vardt allt arbetet fullkomnadt, som Salomo gjorde på Herrans hus. Och Salomo lät komma derin allt det hans fader David helgat hade, nämliga silfver och guld, och allahanda tyg; och lade det in uti fataburen i Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Då församlade Salomo alla äldsta i Israel, alla höfdingar i slägterna, Förstar för fäderna i Israels barn, till Jerusalem, att de skulle låta uppkomma Herrans förbunds ark utu Davids stad, det är Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Och församlade sig till Konungen alle Israels män på högtidene, det är i sjunde månadenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Och kommo alle äldste i Israel; och de Leviter togo arken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Och båro honom upp, samt med vittnesbördsens tabernakel, och all helig tyg, som i tabernaklet voro; och Presterna Leviterna båro det allt med upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Men Konung Salomo och hela Israels menighet med honom, församlad inför arken, offrade får och fä, så mycket, att det ingen tälja eller räkna kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Alltså båro Presterna Herrans förbunds ark uti sitt rum, i husets chor, uti det aldrahelgasta, under Cherubims vingar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Så att Cherubim utsträckte sina vingar öfver arkens rum; och Cherubim öfvertäckte arken och hans stänger, ofvantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Men stängerna voro så långa, att man såg ändarna på dem för choren ifrån arkenom; men utantill såg man dem icke; och blef han der allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Och i arken var intet utan de två taflor, som Mose hade lagt deruti i Horeb, då Herren ett förbund gjorde med Israels barn, den tid de utur Egypten drogo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Och då Presterna gingo utu det helga; ty alle de Prester, som för handene voro, helgade sig, så att ock skiften icke hållne vordo,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Och de Leviter, med alla dem som under Assaph, Heman, Jeduthun, och deras barn och bröder, voro, klädde med linnen kläder, sjöngo med cymbaler, psaltare och harpor, och stodo österut ifrån altaret, och när dem tjugu och hundrade Prester, som blåste med trummeter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Och det var, såsom det hade varit allt en som trummetade, och sjöng, såsom man hörde ena röst, till att lofva och tacka Herranom; och då rösten upphof sig af trummeterna, cymbaler och annor strängaspel, och af Herrans lof, att han mild är, och hans barmhertighet varar till evig tid; då vardt Herrans hus uppfyldt med ett moln;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Så att Presterna icke stå kunde, till att tjena, för molnets skull; ty Herrans härlighet uppfyllde Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Då sade Salomo: Herren hafver sagt, att han vill bo i mörkrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Och jag hafver byggt ett hus dig till boning, och ett säte, der du bo skall till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Och Konungen vände sitt ansigte, och välsignade hela Israels menighet; ty hela Israels menighet stod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Och han sade: Lofvad vare Herren Israels Gud, som genom sin mun till min fader David talat, och med sine hand fullkomnat hafver, då han sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Efter den tiden, att jag mitt folk utur Egypti land förde, hafver jag ingen stad utvalt i alla Israels slägter, der ett hus att bygga, så att mitt Namn der vara skulle; hafver ej heller någon man utvalt, att han skulle vara en Förste öfver mitt folk Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Men Jerusalem hafver jag utvalt, att mitt Namn der vara skall; och David hafver jag utvalt, att han skall vara öfver mitt folk Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Och då min fader David i sinnet hade att bygga Herrans Israels Guds Namne ett hus,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Sade Herren till min fader David: Du hafver gjort väl, att du hafver i sinnet att bygga mino Namne ett hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Dock skall du icke bygga det huset, utan din son, som utaf dina länder komma skall, han skall bygga mino Namne hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Så hafver nu Herren stadfäst sitt ord, som han talat hafver; ty jag är uppkommen uti mins faders Davids stad, och sitter på Israels stol, såsom Herren sagt hafver; och hafver byggt ett hus Herrans Namne Israels Guds;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Och hafver satt deruti arken, der Herrans förbund uti är, det han med Israels barn gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Och han gick fram för Herrans altare, i hela Israels menighets närvaro, och uträckte sina händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Ty Salomo hade gjort en kopparkettil, och satt honom midt i gården, fem alnar lång och bred, och tre alnar hög: till den samma gick han, och föll neder på sin knä inför hela Israels menighet, och uträckte sina händer upp åt himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Och sade: Herre Israels Gud, det är ingen Gud dig liker, antingen i himmelen eller på jordene; du som håller förbund och barmhertighet dinom tjenarom, som vandra för dig af allt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Du hafver hållit din om tjenare David, minom fader, hvad du honom sagt hafver; med dinom mun hafver du sagt det, och med dine hand hafver du fullkomnat det, såsom det nu i denna dag tillgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nu, Herre Israels Gud, håll dinom tjenare David, minom fader, hvad du till honom talat hafver, och sagt: Dig skall icke fattas en man för mig, som sitta skall på Israels stol; dock, såframt din barn förvara sina vägar, att de vandra i min lag, såsom du för mig vandrat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Nu, Herre Israels Gud, låt din ord sann varda, som du dinom tjenare David sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Ty menar du ock, att Gud bor när menniskomen på jordene? Si, himmelen och alla himlars himlar kunna icke begripa dig; huru skulle då detta huset göra det, som jag byggt hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Men vänd dig, Herre, min Gud, till dins tjenares bön, och till hans begär, att du ville höra den bön och bedjande, som din tjenare för dig gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Att din ögon måga blifva öppne öfver detta hus dag och natt; öfver det rum, som du lofvat hafver, att ditt Namn der vara skall; att du ville höra den bön, som din tjenare på detta rum görandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Så hör nu dins tjenares, och dins folks Israels bön, som de bedjande varda i detta rum; och hör dertill ifrå det rum, der du bor i himmelen; och när du hörer, att du ville ock nådelig vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Om någor syndar emot sin nästa, och honom varder en ed pålagd, som han svärja skall; och den eden kommer för ditt altare i desso huse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Att du ville då höra af himmelen, och skaffa dinom tjenare rätt; att du ville vedergälla dem ogudaktiga, och gifva honom hans väg på hans hufvud, och gifva dem rättfärdiga rätt; och att du gifver honom efter hans rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Om ditt folk Israel för sina fiendar slaget varder, efter de emot dig syndat hafva; och de omvända sig, och bekänna ditt Namn, bedja och begära för dig i desso huse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Att du ville då höra dertill af himmelen, och vara dins folks Israels synder nådelig, och låta dem komma uti det land, som du dem och deras fäder gifvit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Om himmelen tillyckt varder, så att intet regnar, efter de emot dig syndat hafva; och de bedja i detta rum, och bekänna ditt Namn, och omvända sig ifrå sina synder, sedan du dem ödmjukat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Att du då ville höra dem i himmelen, och vara dina tjenares och dins folks Israels synder nådelig, att du lärer dem en god väg, der de uti vandra måga; och låter regna på ditt land, som du dino folke gifvit hafver till besittning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Om en hunger varder i landena, eller pestilentie, eller torka, brand, gräshoppor, gräsmatkar; eller om deras fiendar i landet belägga deras portar; eller eljest någor plåga eller krankhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Den då beder, eller begärar ibland allahanda menniskor, och ibland allt ditt folk Israel, då någor sina plågo och vedermödo känner, och uträcker sina händer till detta huset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Att du då ville höra dertill af himmelen, af dins bonings säte, och vara nådelig, och gifva hvarjom och enom efter alla hans vägar, efter som du känner hans hjerta; ty du allena känner menniskors barnas hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'På det att de skola frukta dig, och vandra på dina vägar alla dagar, så länge som de lefva i landet, som du våra fäder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Om ock en främmande, som icke är utaf ditt folk Israel, kommer af fjerran land, för ditt stora Namn och mägtiga hand och uträckta arms skull, och beder i desso huse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Att du ville höra dertill af himmelen, af dins bonings säte, och göra allt det, der han dig om åkallar; på det att all folk på jordene måga känna ditt Namn och frukta dig såsom ditt folk Israel, och förnimma att detta hus, som jag byggt hafver, efter ditt Namn nämndt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Om ditt folk utdrager i strid emot sina fiendar, den vägen som du dem sändandes varder, och de bedja till dig på den vägen emot denna staden, som du utvalt hafver, och till det hus, som jag dino Namne byggt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Att du då ville höra deras bön och begär af himmelen, och hjelpa dem till deras rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Om de varda syndande emot dig, efter ingen menniska är som icke syndar; och du varder vred på dem, och gifver dem för deras fiendar, att de föra dem bort fångna uti något land, fjerran eller när;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Och de omvända sig i sino hjerta, uti de lande der de uti fångne äro, och omvända sig, och bedja dig uti sins fängelses land, och säga: Vi hafve syndat, illa gjort och varit ogudaktige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'Och vända sig så till dig af allt hjerta, och af allo själ, uti sins fängelses land, der man dem fångna håller, och de bedja på den väg emot sitt land, som du deras fäder gifvit hafver, och emot den stad, som du utvalt hafver, och emot huset, som jag dino Namne byggt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Att du då ville höra deras bön och begär af himmelen, af dins bonings säte, och hjelpa dem till deras rätt, och vara dino folke nådelig, som emot dig syndat hafva,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Så låt nu, min Gud, din ögon öppna vara, och din öron gifva akt på bönen i detta rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Så statt nu upp, Herre Gud, till dina ro, du och dins magts ark; låt dina Prester, Herre Gud, varda iklädde med salighet, och dina heliga glädja sig öfver det goda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Herre Gud, vänd icke bort din Smordas ansigte; tänk uppå den barmhertighet, som din tjenare David lofvad är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Och då Salomo utbedit hade, föll en eld af himmelen, och förtärde bränneoffret och annat offer; och Herrans härlighet uppfyllde huset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Så att Presterna icke kunde ingå uti Herrans hus, så länge Herrans härlighet uppfyllde Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Och sågo all Israels barn elden falla neder, och Herrans härlighet öfver huset, och föllo ned med ansigtet till jordena på golfvet, och tillbådo, och tackade Herranom, att han är god, och hans barmhertighet varar till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Men Konungen och allt folket offrade för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Ty Konung Salomo offrade tu och tjugu tusend nöt, och hundrade och tjugu tusend får; och vigde så Guds hus, både Konungen och allt folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Men Presterna stodo i sine vakt, ock Leviterna med Herrans strängaspel, som Konung David hade låtit göra till att tacka Herranom, att hans barmhertighet varar till evig tid, med Davids psalmer, genom deras hand; och Presterna blåste i trummeterna emot dem, och hele Israel stod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Och Salomo helgade medelgården, som för Herrans hus var; ty han hade der offrat bränneoffer, och det feta af tackoffrena; förty kopparaltaret, som Salomo hade göra låtit, kunde icke räcka till allt bränneoffret, spisoffret, och till det feta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Och Salomo höll på den samma tiden ena högtid i sju dagar, och hele Israel med honom, en ganska stor menighet, allt ifrå Hamath, intill Egypti bäck;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Och höll på åttonde dagen ena församling; ty altarets vigning höllo de i sju dagar, och högtiden sammalunda i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Men på tredje och tjugonde dagen i sjunde månadenom lät han gå folket i deras hyddor, glädjandes och fröjdandes sig öfver allt det goda, som Herren med David, Salomo och sino folke Israel gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Allt så lyktade Salomo Herrans hus, och Konungshuset, och allt det i hans hjerta kommet var, till att göra i Herrans huse, och i sino huse, i goda måtto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Och Herren syntes Salomo om nattena, och sade till honom: Jag hafver hört dina bön, och utvalt mig detta rummet till ett offerhus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Si, om jag igenlycker himmelen, så att intet regnar, eller jag bjuder gräshoppor uppfräta landet, eller låter en pestilentie komma ibland mitt folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'Att de mitt folk ödmjuka, det efter mitt namn nämndt är; och de bedja och söka mitt ansigte, och omvända sig ifrå sina onda vägar; så vill jag af himmelen höra dertill, och förlåta dem deras synder, och bota deras land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Så skola nu min ögon öppna vara, och min öron gifva akt på bönerna i desso rumme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Och hafver jag nu utvalt och helgat detta hus, att mitt Namn skall vara der till evig tid, och min ögon och mitt hjerta skall vara der allstädes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Och om du varder vandrandes för mig, såsom din fader David vandrat hafver, så att du gör allt det jag befaller dig, och håller min bud och rätter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Så skall jag befästa dins rikes stol, såsom jag mig förbundit hafver med dinom fader David, sägandes: Dig skall icke fattas en man, som öfver Israel en herre vara skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Men om I afvänden eder, och öfvergifven mina rätter och bud, som jag eder förelagt hafver, och gången bort, och tjenen andra gudar, och tillbedjen dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Så skall jag utrota dem utu mitt land, som jag dem gifvit hafver; och detta hus, som jag mino Namne helgat hafver, skall jag bortkasta ifrå mitt ansigte, och skall gifva det till ett ordspråk och en fabel ibland all folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Och för desso huse, det aldrahögst vordet är, skola sig förskräcka alle de som der framom gå, och säga: Hvi hafver Herren så farit med desso lande, och med desso huse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Då skall man säga: Derföre, att de öfvergåfvo Herran deras fäders Gud, den dem utur Egypti land fört hade, och togo sig andra gudar, och tillbådo dem, och tjente dem; derföre hafver han låtit allt detta onda komma öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Och efter tjugu år, i hvilkom Salomo Herrans hus, och sitt hus byggde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Byggde han ock de städer, som Hyram gaf Salomo, och lät Israels barn bo deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Och Salomo drog till HamathZoba, och gjorde det fast;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Och byggde Thadmor i öknene, och alla kornstäder, som han byggde i Hamath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Han byggde ock öfra och nedra BethHoron, hvilka faste städer voro med murar, portar och bommar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Desslikes Baalath, och alla kornstäder som Salomo hade, och alla vagnsstäder, och resenärars städer, och allt det Salomo lyste att bygga, både i Jerusalem och på Libanon, och i allo hans väldes lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Allt det folk, som qvart blifvet var, af de Hetheer, Amoreer, Phereseer, Heveer och Jebuseer, som icke voro af Israels barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Och deras barn, som de efter sig left hade i landena, hvilka Israels barn icke förlagt hade, gjorde Salomo skattpligtiga, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Men af Israels barn gjorde Salomo inga trälar, till sitt arbete; utan de voro krigsmän, och öfver hans riddare, och öfver hans vagnar och resenärar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Och de öfverste Konung Salomos befallningsmän voro tuhundrad och femtio, som öfver folket rådde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Och Pharaos dotter lät Salomo hemta af Davids stad, uti det hus, som han för henne byggt hade; ty han sade: Min hustru skall icke bo uti Davids Israels Konungs huse; förty det är helgadt, efter Herrans ark der inkommen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Sedan offrade Salomo Herranom bränneoffer på Herrans altare, som han byggt hade för förhuset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Till att offra hvart på sin dag, efter Mose bud; på Sabbather, nymånader, och på bestämda tider, tre resor om året; nämliga på osyrade bröds högtidene, på veckohögtidene, och på löfhyddohögtidene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Och han satte Presterna i deras skifte till deras ämbete, såsom David hans fader det lagat hade; och Leviterna på deras vakt till att lofva och tjena för Presterna, hvar sin dag; och de dörravaktare i deras skifte, hvar vid sina dörr; ty så hade David den Guds mannen befallt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Och man vek icke ifrå Konungens bud, om Presterna och Leviterna, i någrahanda ärende och håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Alltså vardt redo hvad Salomo för händer haft hade, ifrå den dag, då Herrans hus grundadt vardt, intilldess han fullkomnade det; så att Herrans hus allt redo vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Så drog Salomo till EzionGeber, och till Eloth, vid hafsstrandena i Edoms land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Och Hyram sände honom skepp med sina tjenare, som sjöfarne voro; och de foro med Salomos tjenare till Ophir, och hemtade dädan fyrahundrad och femtio centener guld, och förde till Konung Salomo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Och då Drottningen af rika Arabien hörde Salomos rykte, kom hon med ganska stor skara till Jerusalem med cameler, som örter och guld båro, väl mycket, och ädla stenar, till att försöka Salomo med gåtor. Och då hon kom till Salomo, talade hon med honom allt det hon sig i sitt hjerta föresatt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Och Salomo sade henne allt det hon frågade; och Salomo var ingen ting fördold, det han icke sade henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Och då Drottningen af rika Arabien såg Salomos vishet, och huset, som han byggt hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'Maten på hans bord, boningarna för hans tjenare, hans tjenares ämbete, och deras kläder, hans skänkesvänner, med deras kläder, och hans sal, der man uppgick uti Herrans hus, kunde hon icke längre hålla sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Och hon sade till Konungen: Det är sant, hvad jag hört hafver uti mitt land, af ditt väsende, och af dinom visdom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Men jag ville icke tro deras ord, till dess jag kommen är, och hafver det sett med min ögon; och si, mig är icke hälften sagt af dinom stora visdom; det är mer med dig än ryktet, som jag hört hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Salige äro dine män, och salige desse dine tjenare, som alltid stå för dig, och höra din visdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Herren din Gud vare lofvad, som dig kär hafver, att han dig till en Konung på din stol satt hafver, Herranom dinom Gud; det gör, att din Gud hafver Israel kär, så att han vill dem vid magt hålla till evig tid; derföre hafver han satt dig öfver dem till en Konung, att du skall hålla rätt och redelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Och hon gaf Konungenom hundrade och tjugu centener guld, och ganska mycket örter, och ädla stenar: inga örter voro sådana som dessa, som Drottningen af rika Arabien Konung Salomo gaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Dertill Hyrams tjenare och Salomos tjenare, som guld förde ifrån Ophir, de förde ock hebenträ, och ädla stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Och Salomo lät göra trappor utaf hebenträ i Herrans hus, och i Konungshusena, och harpor och psaltare för sångare; ingen sådana trä voro tillförene sedd i Juda land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Men Konung Salomo gaf Drottningene af rika Arabien allt det hon begärade och beddes, utan det hon hade fört till Konungen. Och hon vände om, och drog i sitt land igen med sina tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Men det guld, som Salomo årliga tillfördt vardt, var sexhundrad sex och sextio centener;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Förutan det som krämare och köpmän förde; och alle Arabers Konungar, och herrarna i landen förde guld och silfver till Salomo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Och gjorde Konung Salomo tuhundrad spetsar af bästa guld; så att sexhundrad stycke guld kommo till hvar spets.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Och trehundrad sköldar af bästa guld, så att trehundrad stycke guld kommo till hvar sköld; och Konungen lät dem i huset af Libanons skog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Och Konungen gjorde en stor elphenbensstol, och öfverdrog honom med klart guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Och stolen hade sex trappor och en gyldene fotapall till stolen, och två stolpar, på båda sidor om sätet; och tu lejon stodo vid stolparna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Och tolf lejon stodo på de sex trappor, på båda sidor. En sådan är icke gjord i all Konungarike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Och all Konung Salomos drickekar voro af guld, och all käril i Libanons skogs huse voro af klart guld; förty silfver vardt intet aktadt i Salomos tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Ty Konungens skepp foro till sjös med Hyrams tjenare, och kommo en gång i hvar tre år, och förde guld, silfver, elphenben, apor och påfoglar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Alltså vardt Konung Salomo större, än alle Konungar på jordene, med rikedomar och vishet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Och alle Konungar på jordene begärade Salomos ansigte, att höra hans visdom, som Gud honom i hjertat gifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Och de förde honom årliga hvar och en sina skänkningar, silfkar och guldkar, kläder, harnesk, örter, hästar och mular.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Och Salomo hade fyratusend vagnshästar, och tolftusend resenärar, och man lät dem uti vagnsstäderna, och när Konungenom i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Och han var en herre öfver alla Konungar, allt ifrån älfvene intill de Philisteers land, och allt intill Egypti gränso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Och Konungen lät silfver i Jerusalem varda så mycket som stenar, och cederträ så mycket som mulbärsträ i dalarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Och man förde honom hästar utur Egypten, och utur all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Hvad nu mer af Salomo sägande är, både om hans första och om hans sista, si, det är skrifvet uti den Prophetens Nathans Chrönico, och uti Ahias Prophetia af Silo, och uti de syner Jeddo den Siarens, emot Jerobeam, Nebats son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Och Salomo regerade i Jerusalem öfver hela Israel i fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Och Salomo afsomnade med sina fäder, och man begrof honom uti Davids hans faders stad. Och Rehabeam, hans son, vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rehabeam drog till Sechem; ty hele Israel var kommen till Sechem, att göra honom till Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Och då Jerobeam, Nebats son, som i Egypten var, dit han för Konung Salomo flydd var, det hörde, kom han igen utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Och de sände bort, och läto kalla honom. Och Jerobeam kom med hela Israel; och de talade med Rehabeam, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Din fader hafver gjort vårt ok allt för hårdt; så lätta du ini dins faders hårda tjenst, och det svåra ok som han på oss lagt hafver, så vilje vi vara dig underdånige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Han sade till dem: Efter tre dagar kommer igen till mig. Och folket gick sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Och Konung Rehabeam rådfrågade med de äldsta, som för hans fader Salomo ståndit hade, medan han lefde, och sade: Hvad råden I, det jag skall svara desso folkena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'De talade med honom, och sade: Om du ställer dig vänliga till detta folk, och far väl åt dem, och gifver dem god ord, så blifva de dig underdånige i alla sina dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Men han lät blifva de äldstas råd, som de honom gifvit hade, och rådfrågade med de unga, som med honom uppväxte voro, och för honom stodo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Och sade till dem: Hvad råden I, det vi desso folkena svara skole, som med mig talat hafva, och sagt: Lätta oss det ok, som din fader på oss lagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Men de unge, som med honom uppväxte voro, talade med honom, och sade: Så skall du säga till folket, som till dig talat hafver, och säger: Din fader hafver gjort vårt ok allt för tungt, gör du vårt ok lättare; och säg till dem: Mitt minsta finger skall vara tjockare än mins faders länder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Hafver nu min fader för tungt ok lagt uppå eder, så skall jag ännu göra edart ok tyngre; min fader hafver tuktat eder med gisslar, men jag med scorpioner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Som nu Jerobeam och allt folket kom till Rehabeam på tredje dagen, såsom Konungen sagt hade: Kommer igen till mig på tredje dagen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Svarade Konungen dem hårdeliga; och Konung Rehabeam öfvergaf de äldstas råd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Och talade med dem efter de ungas råd, och sade: Hafver min fader gjort edart ok för svårt, så skall jag ännu göra det svårare; min fader hafver tuktat eder med gisslar, men jag med scorpioner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Alltså hörde Konungen folket intet; ty det vardt alltså vändt af Gudi, på det Herren skulle göra sitt ord fast, som han talat hade genom Ahia af Silo till Jerobeam, Nebats son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Då nu hele Israel såg, att Konungen intet hörde dem, svarade folket Konungenom, och sade: Hvad del hafve vi med David, eller arf med Isai son? Hvar och en af Israel drage till sina hyddor: Så se du nu till ditt hus, David. Och hele Israel gick i sina hyddor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Så att Rehabeam regerade allenast öfver de Israels barn, som bodde i Juda städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Då sände Konung Rehabeam Hadoram räntomästaren; men Israels barn stenade honom ihjäl. Och Konung Rehabeam steg med hast på sin vagn, och flydde till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Alltså föll Israel af ifrå Davids hus, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Då Rehabeam kom till Jerusalem, församlade han Juda hus och BenJamin, hundradetusend, och åttatiotusend unga män, som stridsamme voro, till att strida emot Israel, att de måtte komma åter riket under Rehabeam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Men Herrans ord kom till Semaja, den Guds mannen, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Tala till Rehabeam, Salomos son, Juda Konung, och till hela Israel, som under Juda och BenJamin är, och säg:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Detta säger Herren: I skolen icke draga upp, ej heller strida emot edra bröder; hvar och en gånge åter hem, förty det är skedt af mig. De lydde Herrans ord, och vände igen att draga emot Jerobeam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Men Rehabeam bodde i Jerusalem, och byggde de städer fasta i Juda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Nämliga BethLehem, Etham, Thekoa,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bethzur, Socho, Adullam,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gath, Maresa, Siph,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Lachis, Aseka,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Zorga, Ajalon och Hebron; hvilke voro de fastaste städer i Juda och BenJamin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Och han gjorde dem fasta, och satte der öfverstar in, och besörjde dem med spisning, oljo och vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Och i alla städer skaffade han sköldar och spjut, och gjorde dem ganska fasta. Och Juda och BenJamin voro under honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Och gåfvo sig till honom Presterna och Leviterna utaf hela Israel, och alla deras gränsor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Och de öfvergåfvo alla deras förstäder och håfvor, och kommo till Juda i Jerusalem; förty Jerobeam och hans söner fördrefvo dem, att de icke kunde bruka Herranom Presterskapet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Men han stiktade sig Prester till höjderna, och till djeflar, och kalfvar, som han göra lät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Och efter dem kommo, utaf all Israels slägter, de som sitt hjerta gåfvo till att fråga efter Herran Israels Gud, till Jerusalem, att de måtte offra Herranom sina fäders Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Och förstärkte alltså Juda rike, och styrkte Rehabeam, Salomos son, i tre år; ty de vandrade på Davids och Salomos väg i tre år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Och Rehabeam tog Mahalath, Jerimoths dotter, Davids sons, till hustru, och Abihail, Eliabs dotter, Isai sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Hon födde honom dessa söner: Jehus, Semaria och Saham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Derefter tog han Maacha, Absaloms dotter. Hon födde honom Abia, Attai, Sisa och Selomith.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Men Rehabeam hade Maacha, Absaloms dotter, kärare, än alla sina hustrur och frillor; ty han hade aderton hustrur, och sextio frillor, och födde åtta och tjugu söner, och sextio döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Och Rehabeam satte Abia, Maachas son, till ett hufvud och Första öfver hans bröder; ty han hade i sinnet göra honom till Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Och han växte till, och yppade sig för alla hans söner i Juda och BenJamins land, i alla fasta städer. Och han gaf dem spisning en stor hop; och han tog många hustrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Då Rehabeams rike vardt stadfäst och förstärkt, öfvergaf han Herrans lag, och hele Israel med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Men i femte årena Konungs Rehabeams drog upp Sisak, Konungen i Egypten, emot Jerusalem; förty de hade syndat emot Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Med tusende och tuhundrad vagnar, och med sextiotusend resenärar, och det folk var icke till räknande, som med honom kom utur Egypten, Lybia, Suchim och Ethiopien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Och han vann de fasta städer, som i Juda voro, och kom intill Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Så kom Semaja den Propheten till Rehabeam, och till de öfversta i Juda, som sig till Jerusalem församlat hade för Sisak, och sade till dem: Detta säger Herren: I hafven öfvergifvit mig, derföre hafver jag öfvergifvit eder i Sisaks hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Då ödmjukade sig de öfverste i Israel, med Konungenom, och sade: Herren är rättvis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Då Herren nu såg, att de ödmjukade sig, kom Herrans ord till Semaja, och sade: De hafva ödmjukat sig, derföre vill jag icke förderfva dem, utan jag vill gifva dem en liten undsättning, så att min vrede icke skall drypa på Jerusalem genom Sisak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Dock skola de varda honom underdånige, att de måga lära hvad det är att tjena mig, och tjena Konungariken i landomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Alltså drog Sisak, Konungen i Egypten, upp till Jerusalem, och tog ut de håfvor i Herrans hus, och de håfvor i Konungshusena, och förde alltsammans bort. Desslikes tog han ock de gyldene sköldar, som Salomo göra lät;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'I hvilkas stad Konung Rehabeam lät göra kopparsköldar, och befallde dem de öfversta för drabanterna, som vakt höllo för portenom af Konungshusena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Och så ofta som Konungen gick uti Herrans hus, kommo drabanterna, och båro dem, och lade dem åter i drabantakammaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Och efter han ödmjukade sig, vände sig Herrans vrede ifrå honom, så att icke allt förderfvadt vardt; ty det var ännu något godt i Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Alltså kom Konung Rehabeam sig före i Jerusalem, och regerade. Ett och fyratio år gammal var Rehabeam, då han vardt Konung, och regerade i sjutton år i Jerusalem, uti den stad som Herren utvalt hade utur all Israels slägter, att han der sitt Namn sätta skulle; hans moder het Naama, en Ammonitiska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Och han handlade illa, och skickade icke sitt hjerta till att söka Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Men Rehabeams gerningar, både de första och de sista, äro beskrifna uti den Prophetens Semaja, och i Iddo den Siarens gerningar, och upptecknade. Och örligade Rehabeam och Jerobeam så länge de lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Och Rehabeam afsomnade med sina fäder, och vardt begrafven uti Davids stad; och hans son Abia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Uti adertonde årena Konungs Jerobeams vardt Abia Konung i Juda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Och regerade tre år i Jerusalem; hans moder het Michaja, Uriels dotter, af Gibea. Och en strid hof sig upp emellan Abia och Jerobeam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Och Abia gjorde redo till strid med fyrahundradtusend unga män, starka till strid; men Jerobeam gjorde redo till att strida emot dem med åttahundradtusend starka unga män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Och Abia steg upp på Zemaraims berg, som ligger på Ephraims berg, och sade: Hörer härtill, Jerobeam, och hele Israel!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Veten I icke, att Herren Israels Gud hafver gifvit David Israels Konungarike till evig tid; honom och hans söner ett saltförbund?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Men Jerobeam, Nebats son, Salomos tjenare, Davids sons, kastade sig upp, och satte sig emot sin herra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Och till honom hafva gifvit sig lösaktige män och Belials barn, och hafva förstärkt sig emot Rehabeam, Salomos son; förty Rehabeam var ung, och af blödigt hjerta, så att han icke varde sig för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Nu menen I vilja sätta eder emot Herrans rike, ibland Davids söner; efter I ären en stor hop, och hafven gyldene kalfvar, som Jerobeam eder för gudar gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Hafven I icke fördrifvit Herrans Prester, Aarons söner, och Leviterna; och hafven gjort eder egna Prester, såsom folken i landen? Den som kommer till att fylla sina hand med en ung stut och sju vädrar, den varder Prest till dem som icke äro gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Men med oss är Herren vår Gud, den vi icke öfvergifve, och Presterna, som Herranom tjena, Aarons barn, och Leviterna i deras sysslor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Och upptända Herranom bränneoffer, hvar morgon och hvar afton, dertill det goda rökverket, och tillreda bröden på det rena bordet, och den gyldene stakan med sina lampor, så att de varda upptände hvar afton; ty vi behålle Herrans vår Guds vakt; men I hafven öfvergifvit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Si, med oss är Gud i spetsen, och hans Prester och trummeterna till att trummeta; så att man skall trummeta emot eder; I Israels barn, strider icke emot Herran edra fäders Gud; ty det varder eder icke väl bekommandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Men Jerobeam gjorde en bakhär, att han måtte komma bakuppå dem; så att desse voro frammanför Juda, och bakhären efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Då nu Juda vände sig om, si, då var strid både för och efter. Då ropade de till Herran, och Presterna trummetade med trummeter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Och hvar man i Juda skriade. Och då hvar man i Juda skriade, plågade Gud Jerobeam och hela Israel för Abia och Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Och Israels barn flydde för Juda; och Gud gaf dem i deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Och Abia med sitt folk gjorde en stor slagtning på dem; och föllo af Israel slagne femhundradtusend unge män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Alltså vordo Israels barn nedertryckte i den tiden; och Juda barn vordo tröste; förty de förläto sig på Herran deras fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Och Abia jagade efter Jerobeam, och vann honom städer af, BethEl med dess döttrar, Jesana med dess döttrar, och Ephron med dess döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Så att Jerobeam kom intet mer till magt, så länge Abia lefde. Och Herren plågade honom, så att han blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Då nu Abia vardt förstärkt, tog han fjorton hustrur, och födde två och tjugu söner och sexton döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Hvad nu mer af Abia sägande är, och om hans vägar, och hans gerningar, det är skrifvet uti den Prophetens Iddo Historia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Och Abia afsomnade med sina fader, och de begrofvo honom uti Davids stad; och Asa hans son vardt Konung i hans stad; uti den tiden var landet stilla i tio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Och Asa gjorde det rätt var, och det Herranom hans Gud väl behagade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Och kastade bort de främmande altare, och höjderna, och slog sönder stoderna, och högg af lundarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Och lät säga Juda, att de skulle söka Herran deras fäders Gud, och göra efter lagen och budorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Och han kastade bort utur alla Juda städer höjderna och afgudarna; ty riket var stilla för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Och han byggde fasta städer i Juda, medan landet stilla, och intet örlig emot honom var uti de årena; ty Herren gaf honom ro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Och han sade till Juda: Låt oss bygga dessa städerna, och låta gå murar deromkring, och torn, portar och bommar, efter vi hafve rolighet i landena; ty vi hafve sökt Herran vår Gud, ja, vi hafve sökt honom, och han hafver gifvit oss ro allt omkring. Alltså byggde de, och det gick väl fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Och Asa hade en här, som spjut och sköld båro: utaf Juda trehundradtusend, och utaf BenJamin de som sköld båro, och med båga kunde, tuhundradtusend, och åttatiotusend; och desse voro alle starke hjeltar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Så drog emot dem Serah den Ethiopen, med en mägtig här, tusende resor tusende, dertill trehundrade vagnar, och kommo intill Maresa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Och Asa drog ut emot honom; och de redde sig till strid uti den dalen Zephatha vid Maresa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Och Asa åkallade Herran sin Gud, och sade: Herre, när dig är ingen skilfång hjelpa, ibland många, eller der ingen magt är. Hjelp oss. Herre vår Gud; ty vi förlåte oss på dig, och i ditt Namn äro vi komne emot denna hopen; Herre vår Gud, för dig förmår ingen menniska något.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Och Herren plågade de Ethioper för Asa, och för Juda, så att de flydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Och Asa med folkena, som med honom var, jagade efter dem allt intill Gerar. Och de Ethioper föllo, så att ingen af dem blef lefvandes, utan de vordo nederlagde för Herranom, och för hans här; och de togo ganska mycket rof deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Och han slog alla städer omkring Gerar; ty Herrans fruktan kom öfver dem, och de skinnade alla städer; ty der var mycket rof inne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Slogo de också boskapens hyddor, och togo får ganska mycken, och camelar; och kommo igen till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Och uppå Asaria, Obeds son, kom Guds Ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Han gick ut emot Asa, och sade till honom: Hörer härtill, Asa, och hele Juda och BenJamin; Herren är med eder, efter I ären med honom; och när I söken honom, låter han sig af eder finna; om I ock öfvergifven honom, så öfvergifver han ock eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Men det skall vara många dagar i Israel, att der skall ingen rätter Gud vara; ingen Prest, som lärer; ingen lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Och när de omvända sig i sine nöd till Herran Israels Gud, och söka honom, så skall han låta sig finna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'På den tiden varder icke väl gångandes dem som ut och in gå; förty det varder ett stort buller öfver alla de som bo på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Ty det ena folket skall slå det andra, och en stad den andra; förty Gud skall förskräcka dem med allahanda ångest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Men I varer tröste, och drager icke edra händer ifrå; ty edart verk hafver sin lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Då Asa hörde dessa orden, och Obeds den Prophetens Prophetia, vardt han tröst, och kastade bort de styggelser utu hela Juda land och BenJamin, och utu städerna, som han vunnit hade på Ephraims berg, och förnyade Herrans altare, som för Herrans förhus stod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Och församlade hela Juda och BenJamin, och främlingarna när dem utaf Ephraim, Manasse och Simeon; förty till honom föllo månge af Israel, som de sågo att Herren hans Gud med honom var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Och de församlade sig till Jerusalem i tredje månadenom, i femtonde årena Asa rikes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Och offrade på den dagen Herranom utaf rofvet, som de hemtat hade, sjuhundrad nöt, och sjutusend får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Och de trädde uti förbundet, att de skulle söka Herran deras fäders Gud, af allt hjerta, och af allo själ;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Och hvilken som icke sökte Herran Israels Gud, han skulle dö, både liten och stor, både man och qvinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Och de svoro Herranom med höga röst, med rop, med trummeter och basuner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Och hele Juda fröjdade sig öfver eden; ty de hade svorit af allt hjerta, och de sökte honom af allom vilja, och han lät sig af dem finna; och Herren gaf dem ro allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Ock satte Konung Asa sina moder Maacha af ämbetet, för det hon stiktat hade uti Miplezeths lund; och Asa utrotade hennes Miplezeth, och sönderslog honom, och uppbrände honom vid Kidrons bäck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Men höjderna vordo icke bortlagda utur Israel; dock var Asa hjerta rättsinnigt, så länge han lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Och han lät komma in uti Guds hus hvad hans fader helgat hade, och hvad han helgat hade, silfver, guld och käril.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Och intet örlig var allt intill femte och tretionde året Asa rikes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Uti sjette och tretionde årena Asa rikes drog Baesa upp, Israels Konung, emot Juda, och byggde Rama, på det han skulle förmena Asa Juda Konung ut och in fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Men Asa tog af håfvorna uti Herrans hus, och i Konungshusena, silfver och guld, och sände till Benhadad, Konungen i Syrien, som bodde i Damascon, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Emellan dig och mig är ett förbund, emellan min och din fader; derföre hafver jag sändt dig silfver och guld, att du det förbund med Baesa, Konungenom i Israel, öfvergifva skall, att han må draga bort ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Benhadad lydde Konung Asa, och sände sina härförstar emot Israels städer; de slogo Ijon, Dan och AbelMajim, och alla Naphthali kornstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Då Baesa det hörde, vände han igen att bygga Rama, och höll upp af sitt verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Men Konung Asa tog till sig hela Juda, och de togo bort sten och trä ifrå Rama, der Baesa med byggde, och han byggde dermed Geba och Mizpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'På den tiden kom Hanani, Siaren, till Asa, Juda Konung, och sade till honom: Efter du förlätst dig på Konungen i Syrien, och hafver icke förlåtit dig på Herran din Gud; derföre är Konungens magt af Syrien undsluppen dina hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Voro icke de Ethioper och Lybier en mägta stor hop, med ganska många vagnar och resenärar? Likväl gaf Herren dem i dina hand, då du förlätst dig på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Förty Herrans ögon skåda all land, att han skall styrka dem, som af allt hjerta hålla sig intill honom. Du hafver gjort dårliga; derföre skall du ock härefter få örlig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Men Asa vardt vred på Siaren, och lade honom i fängelse; ty han knorrade emot honom om detta stycket. Och Asa undertryckte några af folket i den tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Men Asa gerningar, både de första och de sista, si, de äro skrifna uti Juda och Israels Konungars bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Och Asa vardt krank i sina fötter, uti nionde och tretionde årena sins rikes; och hans krankhet fick öfvermagten, och han sökte intet Herran i sine krankhet, utan läkare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Alltså afsomnade Asa med sina fäder, och blef död i första och fyrationde årena sins rikes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Och man begrof honom uti hans graf, som han sig hade grafva låtit uti Davids stad; och de lade honom på sin säng, hvilka man uppfyllt hade med godt rökverk, och allahanda speceri, efter apothekares konst gjordt; och gjorde ett ganska stort brännande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Och hans son Josaphat vardt Konung i hans stad, och vardt mägtig emot Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Och lade krigsfolk uti alla Juda fasta städer, och satte befallningsmän i Juda land, och i Ephraims städer, som hans fader Asa vunnit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Och Herren var med Josaphat; ty han vandrade i de förra Davids sins faders vägar, och sökte icke Baalim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Utan sins faders Gud, och vandrade i hans bud, och icke efter Israels gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Derföre stadfäste Herren honom riket; och hele Juda gaf Josaphat skänker; och han hade rikedomar och härlighet ganska mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Och då hans hjerta dristigt vardt i Herrans vägar, hof han också bort höjderna och lundarna utu Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Uti tredje årena sins rikes sände han sina Förstar, Benhail, Obadia, Zacharia, Nethaneel och Michaja, att de skulle lära i Juda städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Och med dem de Leviter, Semaja, Nethania, Sebadja, Asahel, Semiramoth, Jonathan, Adonia, Tobia och TobAdonia; och med dem Presterna, Elisama och Joram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Och de lärde i Juda, och hade Herrans lagbok med sig, och foro omkring i alla Juda städer, och lärde folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Och Herrans fruktan kom öfver all rike i de land, som lågo omkring Juda, så att de intet stridde emot Josaphat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Och de Philisteer förde Josaphat skänker, en hop silfver; och de Araber förde honom sjutusend och sjuhundrad vädrar, och sjutusend och sjuhundrad bockar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Alltså växte Josaphat till, och vardt ju större och större; och han byggde i Juda slott och kornstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Och hade mycket till skaffa i Juda städer; och voro stridsamme och väldige män i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Och detta var ordningen ibland deras fäders hus, som i Juda Öfverstar voro öfver tusende: Adna den öfversten, och med honom voro trehundradetusend väldige män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Näst honom var Johanan den öfversten, och med honom voro tuhundrade och åttatio tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Dernäst Amasia, Sichri son, den Herrans friviljoge, och med honom voro tuhundradetusend väldige män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Af BenJamins barn var Eljada en väldig man, och med honom voro tuhundradetusend, som med bågar och sköld färdige voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Efter honom var Josabad, och med honom voro hundrade och åttatio tusend färdige män till strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Desse vaktade alle på Konungen, förutan de som Konungen lagt hade uti de fasta städer i hela Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Och Josaphat hade stora rikedomar och härlighet, och befryndade sig med Achab.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Och efter tu år drog han ned till Achab till Samarien; och Achab lät slagta för honom, och för det folk som när honom var, mycken får och fä; och han kom honom dertill, att han skulle draga med honom upp till Ramoth i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Och Achab, Israels Konung, sade till Josaphat, Juda Konung: Drag med mig till Ramoth i Gilead. Han sade till honom: Jag är såsom du, och mitt folk såsom ditt folk, vi vilje med dig i stridena,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Men Josaphat sade till Israels Konung: Käre, fråga i denna dag Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Och Israels Konung församlade af Propheterna fyrahundrade män, och sade till dem: Skole vi, draga till Ramoth i Gilead i strid, eller skall jag låta det bestå? De sade: Drag upp, Gud varder det gifvandes i Konungens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Men Josaphat sade: Är här icke ännu någor Herrans Prophet, att vi måge fråga af honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Israels Konung sade till Josaphat: Här är ännu en man, att vi måge fråga Herran af honom; men jag är vred på honom, förty han spår intet godt öfver mig, utan alltid ondt, nämliga Micha, Jimla son. Josaphat sade: Konungen säge icke så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Och Israels Konung kallade en sin kamererare, och sade: Hemta med hast hit Micha, Jimla son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Och Israels Konung och Josaphat, Juda Konung, såto, hvardera på sin stol, beklädde; och de såto på platsen för ingångenom till porten i Samarien, och alle Propheterna spådde för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Och Zedekia, Chenaana son, gjorde sig jernhorn, och sade: Detta säger Herren: Härmed skall du stöta de Syrer, tilldess du gör ända med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Och alle Propheterna spådde detsamma, och sade: Drag upp till Ramoth i Gilead, och var lyckosam; Herren skall gifva det i Konungens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Och bådet, som åstad gånget var till att kalla Micha, talade med honom, och sade: Si, Propheternas tal är endrägteliga godt för Konungenom; käre, låt ock din ord vara såsom ensderas, och tala det godt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Micha sade: Så sant som Herren lefver, hvad min Gud sägandes varder, det vill jag tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Och då han kom till Konungen, sade Konungen till honom: Micha, skole vi draga till Ramoth i Gilead till strid, eller skall jag låta det blifva? Han sade: Drager upp, och eder ske lycka; det skall eder i edra händer gifvet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Men Konungen sade till honom: Jag besvär dig ännu en gång, att du säger mig icke annat än sanningen, i Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Då sade han: Jag såg hela Israel förströdd på bergen, såsom får, de ingen herdan hafva. Och Herren sade: Hafva desse ingen herra? Fare hvar och en hem igen med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Då sade Israels Konung till Josaphat: Sade icke jag dig, han spår intet godt öfver mig, utan ondt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Men han sade: Derföre hörer Herrans ord: Jag såg Herran sitta på sinom stol, och all den himmelska hären stod vid hans högra sido, och vid hans venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Och Herren sade: Ho vill tälja Achab, Israels Konung i det sinnet, att han drager upp, och faller i Ramoth i Gilead? Och då den ene sade så, och den andre så,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Kom fram en ande, och stod för Herranom, och sade: Jag vill tälja honom i det sinnet. Herren sade till honom: Hvarmed?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Han sade: Jag vill fara ut, och vara en falsk ande uti alla hans Propheters mun. Och han sade: Du skall tälja honom i det sinnet, och uträttat; far åstad, och gör alltså.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Nu si, Herren hafver gifvit en falsk anda uti dessa dina Propheters mun, och Herren hafver talat ondt öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Då trädde fram Zedekia, Chenaana son, och slog Micha vid kindbenet, och sade: Hvilken vägen är Herrans Ande gången ifrå mig, till att tala med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Micha sade: Si, du skall få set, då du kommer uti innersta kammaren, till att undstinga dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Men Israels Konung sade: Tager Micha, och låter honom blifva när Amon stadsfogdanom, och när Joas, Konungens son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Och säger: Så säger Konungen: Lägger denna i fängelse, och spiser honom med bedröfvelsens bröd och vatten, tilldess jag kommer igen med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Micha sade: Om du kommer igen med frid, så hafver icke Herren talat genom mig. Och han sade: Hörer härtill, allt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Alltså drog Israels Konung upp, och Josaphat, Juda Konung, till Ramoth i Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Och Israels Konung sade till Josaphat: Jag vill förkläda mig, och komma i stridena; men du haf din kläder uppå. Och Israels Konung förklädde sig; och de kommo i stridena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Men Konungen i Syrien hade budit sina öfversta resenärar, att de skulle strida emot ingen, antingen liten eller stor, utan emot Israels Konung allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Då nu de öfverste resenärerna fingo se Josaphat, tänkte de, det är Israels Konung: och drogo omkring till att strida uppå honom; men Josaphat ropade, och Herren halp honom, och Gud vände dem ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Ty då de öfverste resenärerna sågo, att det icke var Israels Konung, vände de sig bort ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Men en man bände sin båga hårdt, och sköt Israels Konung emellan magan och lungorna. Då sade han till sin foroman: Vänd dina hand, och för mig utu hären; förty jag är sår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Och striden växte till i den dagen. Och Israels Konung stod på sinom vagn emot de Syrer, allt intill aftonen; och blef död, när solen nedergick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Men Josaphat, Juda Konung, kom hem igen med frid till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Och gick ut emot honom. Jehu, Hanani son, Siaren, och sade till Konung Josaphat: Skulle du så hjelpa den ogudaktiga, och älska dem som Herran hata? Och fördenskull är öfver dig Herrans vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Så är dock likväl något godt funnet i dig, att du hafver borthäfvit de lundar utu landena, och hafver skickat ditt hjerta till att söka Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Alltså blef Josaphat i Jerusalem. Och han drog åter ut ibland folket, allt ifrå BerSeba, och in uppå Ephraims berg, och igenkallade dem till Herran deras fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Och han beställde domare i landena uti alla Juda fasta städer, ju några uti hvar stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Och sade till domarena: Ser till hvad I gören; förty I hållen icke menniskodom, utan Herrans, och han är med eder i domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Derföre, låter Herrans fruktan vara när eder. Tager eder vara, och görer så; ty när Herranom vårom Gud är ingen orätt, eller anseende till personer, ej heller tager han gåfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Ock satte Josaphat i Jerusalem utaf Leviterna och Presterna, och utaf de öfversta fäderna i Israel, öfver Herrans dom och saker, och lät dem bo i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Och böd dem och sade: Görer alltså uti Herrans fruktan, med tro och rätto hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Uti alla de saker, som komma till eder ifrån edra bröder, som bo i sina städer, emellan blod och blod, emellan lag och bud, emellan seder och rätter, skolen I undervisa dem, att de icke förbryta sig emot Herran, och en vrede må komma öfver eder, och edra bröder; görer alltså, så varden I icke brottslige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Si, Amaria Presten är öfverste öfver eder i alla Herrans saker; så är Sebadia, Ismaels son, Förste i Juda hus, i alla Konungssaker; så hafven I ämbetsmän Leviterna för eder. Varer tröste, och görer så, och Herren varder blifvandes med dem goda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Derefter kommo Moabs barn, Ammons barn, och med dem de af Ammonim, till att strida emot Josaphat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Och man kom, och bådade det Josaphat, och sade: Emot dig kommer ett mägta stort tal ifrå hinsidon hafvet, af Syrien, och si, de äro i HazezonThamar, det är EnGedi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Men Josaphat fruktade sig, och ställde sitt ansigte till att söka Herran, och lät utropa en fasto i hela Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Och Juda kom tillhopa, till att söka Herran; kommo ock utaf alla Juda städer till att söka Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Och Josaphat trädde in i menigheten af Juda och Jerusalem, uti Herrans hus inför nya gården;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'Och sade: Herre, våra fäders Gud, äst icke du Gud i himmelen, och råder öfver all Hedningarnas rike? Och i dine hand är kraft och magt, och ingen är, som emot dig stå kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Hafver du, vår Gud, icke fördrifvit detta lands inbyggare för dino folke Israel, och hafver gifvit det Abrahams dins väns säd till evig tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Så att de hafva bott deruti, och byggt dig derinne till ditt Namn en helgedom, och sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Om något ondt, svärd, straff, pestilentie, eller hård tid öfver oss komme, skulle vi stå för detta hus inför dig; förty ditt Namn är i desso huse; och ropa till dig i våra nöd, så ville du höra dertill och hjelpa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Nu si, Ammons barn, Moab, och de af Seirs berg, öfver hvilka du icke lät Israels barn draga, då de foro utur Egypti land, utan de måste vika af ifrå dem, och icke förderfva dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Och si, de låta oss det umgälla, och komma till att utdrifva oss utu ditt arf, som du oss gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Vår Gud, vill du icke döma dem? Ty i oss är ingen magt emot denna stora hopen, som emot oss kommer; vi vete icke hvad vi göra skole, utan vår ögon se till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Och hele Juda stod för Herranom med sin barn, hustrur och söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Men öfver Jahasiel, Sacharia son, Benaja sons, Jehiels sons, Matthania sons, den Leviten utaf Assaphs barn, kom Herrans Ande midt i menighetene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Och sade: Akter härtill, hele Juda, och I Jerusalems inbyggare, och Konung Josaphat; så säger Herren till eder: I skolen icke frukta eder, eller gifva eder för denna stora hopenom; ty det striden icke I, utan Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'I morgon skolen I draga ned till dem; och si, de draga upp till Ziz, och I skolen råka dem vid bäcken, för öknene Jeruel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Förty I skolen intet strida i denna sakene; allenast träder fram, och står, och ser Herrans salighet, den med eder är; Juda och Jerusalem, frukter eder intet, och gifver eder icke; i morgon drager ut emot dem. Herren är med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Då böjde sig Josaphat med sitt ansigte till jordena, och hela Juda och Jerusalems inbyggare föllo neder för Herranom, och tillbådo Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Och Leviterna utaf de Kehathiters barn, och utaf de Korinters barn, stodo upp till att lofva Herran Israels Gud med höga röst åt himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Och de voro bittida uppe om morgonen, och drogo ut till den öknen Thekoa. Och då de utdrogo, stod Josaphat och sade: Hörer härtill, Juda, och I Jerusalems inbyggare: Tror uppå Herran edar Gud, så varden I trygge; och tror hans Propheter, så sker eder lycka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Och han underviste folket, och satte sångare för Herranom, och dem som lofva skulle i heligom skrud, och gå för väpnade hären, och säga: Tacker Herranom, ty hans barmhertighet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Och då de begynte till att tacka och lofva, lät Herren bakhären, som emot Juda kommen var, komma in på Ammons barn, Moab, och dem af Seirs berg; och de slogo dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Då stodo Ammons barn och Moab emot dem af Seirs berg, till att förspilla och nederlägga dem; och då de hade gjort ända på dem af Seirs berg, halp den ene dem andra, att de ock förderfvade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Men då Juda kom till Mizpe vid öknen, vände de sig emot hopen; och si, då lågo de döde kroppar på jordene, så att ingen undsluppen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Och Josaphat kom med sitt folk till att byta deras rof, och funno ibland dem myckna ägodelar och kläder, och kostelig tyg; och skinnade dem, så att de icke mer kunde föra, och utbytte rofvet i tre dagar; ty det var ganska mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'På fjerde dagenom kommo de tillhopa uti lofsdalenom; förty der lofvade de Herran; deraf heter det rummet lofsdal, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Alltså vände hvar och en af Juda och Jerusalem tillbaka igen, och Josaphat för dem, så att de drogo till Jerusalem med fröjd; ty Herren hade gifvit dem en glädje öfver deras fiendar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Och drogo in uti Jerusalem med psaltare, harpor och trummeter, till Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Och Guds fruktan kom öfver all rike i landen, då de hörde, att Herren hade stridt emot Israels fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Alltså vardt Josaphats rike stilla; och Gud gaf honom ro allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Och Josaphat regerade öfver Juda; och var fem och tretio år gammal, då han Konung vardt, och regerade fem och tjugu år i Jerusalem. Hans moder het Asuba, Silhi dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Och han vandrade uti sins faders Asa väg, och gick intet derifrå, att han ju gjorde det Herranom väl täcktes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Undantagno, att de höjder icke borttagne vordo; förty folket hade ännu icke skickat sitt hjerta till deras fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Hvad nu mer af Josaphat sägande är, både det första och det sista, si, det är skrifvet i Jehu gerningar, Hanani sons, hvilka han upptecknat hafver uti Israels Konungars bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Derefter förenade sig Josaphat, Juda Konung, med Ahasia, Israels Konung, hvilken ogudaktig var med sitt väsende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Och han samfällde sig med honom till att göra skepp, att de skulle fara till sjös; och skeppen gjorde de i EzionGeber.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Men Elieser, Dodava son af Maresa, spådde emot Josaphat, och sade: Derföre, att du hafver förenat dig med Ahasia, hafver Herren omintetgjort din verk. Och skeppen vordo sönderslagne, och kunde intet till sjös fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Och Josaphat af somnade med sina fäder, och vardt begrafven när sina fader uti Davids stad; och hans son Joram vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Och han hade bröder, Josaphats söner, Asaria, Jehiel, Zacharia, Asaria, Michael, och SephatJa; desse voro alle Josaphats, Juda Konungs, barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Och deras fader gaf dem myckna gåfvor i silfver, guld och klenodier, med fasta städer i Juda; men riket gaf han Joram; ty han var den förstfödde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Då nu Joram uppkom öfver sins faders rike, och vardt dess mägtig, drap han alla sina bröder med svärd, dertill ock somliga af de öfverstar i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Tu och tretio år gammal var Joram, då han vardt Konung; och regerade åtta år i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Och vandrade uti Israels Konungars väg, såsom Achabs hus gjort hade; förty Achabs dotter var hans hustru; och han gjorde hvad Herranom illa behagade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Men Herren ville icke förderfva Davids hus, för det förbunds skull, som han med David gjort hade, såsom han sagt hade, att gifva honom ena lykto, och hans barnom i alla dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'I hans tid föllo de Edomeer af ifrå Juda, och gjorde öfver sig en Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Förty Joram var ditöfver dragen med sina öfverstar, och alla vagnarna med honom; och hade varit uppe om nattena, och slagit de Edomeer allt omkring sig, och öfverstarna för vagnarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Derföre föllo de Edomeer af ifrå Juda, allt intill denna dag. På samma tiden föll ock Libna ifrå honom; ty han öfvergaf Herran sina fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Gjorde han ock höjder på bergen i Juda, och kom dem i Jerusalem till horeri, och förförde Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Men en skrifvelse kom till honom ifrå den Propheten Elia, så lydandes: Detta säger Herren dins faders Davids Gud: Derföre, att du icke vandrat hafver uti dins faders Josaphats vägar, icke heller i Asa, Juda Konungs, vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Utan du vandrar uti Israels Konungars väg, och kommer Juda och dem i Jerusalem till horeri, efter Achabs hus horeri; och hafver dertill dräpit dina bröder af dins faders hus, som bättre voro än du;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Si, Herren skall slå dig med en stor plågo på ditt folk, på din barn, på dina hustrur, och uppå alla dina ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Och du skall få mycken sjukdom uti dina inelfver, tilldess att dina inelfver skola för sjukdoms skull utgå dag frå dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Alltså uppväckte Herren emot Joram de Philisteers anda, och de Arabers, som ligga vid Ethiopien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Och de drogo upp till Juda, och förstörde det, och förde bort alla håfvor, som för handene voro i Konungshusena; dertill hans söner och hans hustrur, så att honom blef ingen son qvar, förutan Joahas, hans yngste son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Och efter allt detta plågade Herren honom i hans inelfver med en sådana sjukdom, som icke stod till botandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Och som det nu varade dag frå dag, och då tu års tid förgången var, gingo hans inelfver ut af honom med hans sjukdom; och han blef död af ondom sjukdom; och de gjorde intet brännande öfver honom, såsom de hans fäder gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Tu och tretio år gammal var han, då han vardt Konung, och regerade i åtta år i Jerusalem, och vandrade så, att det icke mycket dogde; och de begrofvo honom i Davids stad; dock icke ibland Konungsgrifterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Och de i Jerusalem gjorde till Konung Ahasia hans yngsta son, i hans stad; förty krigsfolket, som utaf de Araber med här kommo, hade de första alla ihjälslagit; derföre vardt Ahasia Konung, Jorams son, Juda Konungs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Tu och fyratio år gammal var Ahasia, då han Konung vardt, och regerade ett år i Jerusalem. Hans moder het Athalja, Amri dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Han vandrade ock uti Achabs hus vägar; ty hans moder höll honom dertill, att han skulle göra det ondt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Derföre gjorde han det Herranom icke behagade, såsom Achabs hus; ty de voro hans rådgifvare efter hans faders död, så att de förderfvade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Och han vandrade efter deras råd, och han drog bort med Joram, Achabs son, Israels Konung, i strid, till Ramoth i Gilead, emot Hasael, Konungen i Syrien. Men de i Rama slogo Joram;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Så att han omvände, till att låta läka sig i Jisreel; förty han hade sår, som han fått hade i Rama, då han stridde med Hasael, Konungen i Syrien. Och Asaria, Jorams son, Juda Konungs, for ned till att bese Joram, Achabs son, i Jisreel, som krank låg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Ty den ofärden var så af Gudi Ahasia tillfogad, att han skulle komma till Joram, och så med Joram utdraga emot Jehu, Nimsi son, hvilken Herren smort hade, till att utrota Achabs hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Då nu Jehu höll uppå att straffa Achabs hus, fann han några öfverstar af Juda, och Ahasia bröders barn, som tjente, och drap dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Och han sökte Ahasia, och fick honom fatt, der han sig undstungit hade i Samarien; och han vardt hafder fram för Jehu. Han drap honom, och man begrof honom; ty de sade: Han är Josaphats son, hvilken efter Herran sökte af allt hjerta. Och var sedan ingen qvar utaf Ahasia huse, som Konung kunde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Då nu Athalja, Ahasia moder, såg att hennes son död var, stod hon upp, och förgjorde all Konungslig säd i Juda hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Men Josabeath, Konungens dotter, tog Johas, Ahasia son, och stal honom undan ibland Konungsbarnen, som dräpne vordo, och lät honom med hans ammo uti en sängakammar. Alltså fördolde honom för Athalja Josabeath, Konung Jorams dotter, Prestens Jojada hustru; ty hon var Ahasia syster; att han icke dräpen vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Och han var med dem i Guds hus fördold i sex år, medan Athalja regerade i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Uti sjunde årena tog Jojada dristighet till sig, och tog med sig i förbund de öfversta öfver hundrade, nämliga Asaria, Jerohams son, Ismael, Johanans son, Asaria, Obeds son, Maaseja, Adaja son, och Elisaphat, Sichri son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'De foro omkring Juda, och hade de Leviter tillhopa utur alla Juda städer, och de öfversta fäderna i Israel; och de kommo till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Och hela menigheten gjorde ett förbund i Guds hus med Konungenom; och han sade till dem: Si, Konungens son skall Konung vara, såsom Herren sagt hafver, öfver Davids barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Så skolen I nu alltså göra: tredjedelen af eder, som på Sabbathsdagenom uppå gå, skola vara ibland de Prester och Leviter, som dörravaktare äro vid dörrarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Tredjedelen i Konungshuset, och tredjedelen vid grundvalsdörrena; men allt folket skall vara i gårdenom till Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Och att ingen går uti Herrans hus, utan Presterna och Leviterna, som tjena, de skola gå derin; förty de äro helige; och allt folket vakte Herrans vakt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Och Leviterna skola gifva sig omkring Konungen, hvar och en med sine värjo i handene; och hvilken som går in i huset, han dräpes; och de skola vara när Konungenom, då han går ut och in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Och Leviterna, med hela Juda, gjorde såsom Presten Jojada budit hade. Och hvar och en tog sina män, som på Sabbathen uppå gingo, med dem som på Sabbathen af gingo: ty Presten Jojada lät icke komma de två hoparna ifrå hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Och Presten Jojada fick öfverstarna öfver hundrade spetsar och sköldar, och Konung Davids vapen, som i Guds hus voro:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Och ställde allt folket, hvar och en med sine värjo i handene, ifrå det högra hörnet i husena allt intill det venstra hörnet, till altaret, och till huset omkring Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Och de hade fram Konungens son, och satte krono uppå honom, och vittnesbördet, och gjorde honom till Konung. Och Jojada med hans söner smorde honom, och sade: Lycka ske Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Då Athalia hörde ropet af folket, som tillopp och lofvade Konungen, gick hon till folket i Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Och hon fick se, och si, Konungen stod i sitt rum i ingångenom, och öfverstarna och trummeterna omkring Konungen; och allt landsfolket var gladt, och blåste med trummeter, och sångarena med allahanda strängaspel skickade till att lofva. Då ref hon sin kläder, och sade: Uppror, uppror.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Men Presten Jojada drog sig ut med de öfversta öfver hundrade, som öfver hären voro, och sade till dem: Hafver henne utu huset i gården; och hvilken henne efterföljer, honom skall man dräpa med svärd. Förty Presten hade befallt, att man icke skulle dräpa henne i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Och de togo fatt på henne. Och då hon kom till hästaportens ingång, vid Konungshuset, dråpo de henne der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Och Jojada gjorde ett förbund emellan sig, och allt folket, och Konungen, att de skulle vara Herrans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Då gick allt folket uti Baals hus, och bröto det neder, och slogo sönder hans altare och beläte, och slogo ihjäl Matthan, Baals Prest, inför altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Och Jojada beställde ämbeten i Herrans hus, under Presterna, Leviterna, som David förskickat hade till Herrans hus, till att göra bränneoffer Herranom, såsom skrifvet står i Mose lag, med fröjd och sånger, som David diktat hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Och ställde dörravaktare vid dörrarna åt Herrans hus, att der skulle intet orent inkomma i någon måtto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Och han tog de öfversta öfver hundrade, och de mägtiga, och herrarna i folkena, och allt landsfolket, och hade Konungen neder ifrå Herrans hus; och förde honom in genom den höga porten af Konungshuset, och läto Konungen sätta sig på Konungsstolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Och allt landsfolket, var gladt, och staden var stilla; men Athalja varat dråpen med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas var sju år gammal, då han Konung vardt, och regerade fyratio år i Jerusalem. Hans moder het Zibja af BerSeba.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Och Joas gjorde det Herranom väl behagade, så länge Presten Jojada lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Och Jojada tog honom två hustrur, och han födde söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Derefter tog Joas till att förnya Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Och församlade Prester och Leviter, och sade till dem: Farer ut till alla Juda städer, och församler penningar utaf hela Israel, till att förbättra edars Guds hus årliga, och skynder eder till att göra så; men Leviterna fördröjde dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Då kallade Konungen Jojada den yppersta, och sade till honom: Hvi hafver du icke akt på Leviterna, att de låta införa af Juda och Jerusalem den hjelpeskatten, som Mose Herrans tjenare påbudit hade, att samkas skulle i Israel, till vittnesbördsens tabernakel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Förty den ogudaktiga Athalia och hennes söner hafva förderfvat Guds hus; och allt det som till Herrans hus helgadt var, hafva de lagt till Baalim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Så befallde Konungen, att man skulle göra ena kisto; och de satte henne utantill vid dörrena af Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Och lät utropa i Juda och Jerusalem, att man skulle införa Herranom den hjelpeskatten, som Guds tjenare Mose på Israel lagt hade i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Då fröjdade sig alle öfverstar, och allt folket, och gjorde tillhopa, och lade i kistona, intilldess hon full vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Och då tid var att kistan skulle hafvas fram af Leviterna, efter Konungens befallning, då de sågo, att der många penningar uti voro, så kom Konungens skrifvare, och den som af öfversta Prestenom befallning hade, och tömde kistona, och båro henne i sitt rum igen. Så gjorde de hvar dag, tilldess de samkade en ganska stor hop penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Och Konungen och Jojada fingo det arbetarena, som skaffare voro på Herrans hus; de samme lejde stenhuggare och timbermän, till att förnya Herrans hus, desslikes de mästare på jern och koppar, till att bättra Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Och arbetsmännerna arbetade, så att förbättringen på verket gick fram genom deras hand, och läto Guds hus komma sig till igen, och gjorde det fast.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Och då de hade det lyktat, båro de penningarna, som öfver voro, in för Konungen och Jojada; deraf gjordes käril till Herrans hus, käril till tjensten, och till bränneoffer, skedar, och gyldene silfvertyg. Och de offrade bränneoffer vid Herrans hus framgent, så länge Jojada lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Och Jojada vardt gammal och mätt af ålder, och blef död, och var hundrade och tretio år gammal, då han blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Och de begrofvo honom uti Davids stad, ibland Konungarna, derföre att han hade gjort väl med Israel, och med Gud och hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Efter Jojada död kommo de öfverste i Juda, och tillbådo Konungen; då hörde Konungen dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Och de öfvergåfvo Herrans deras fäders Guds hus, och tjente lundom och afgudom; så kom vrede öfver Juda och Jerusalem för dessa deras brotts skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Och han sände Propheter till dem, att de skulle omvända sig till Herran. Och de betygade dem; men de hörde dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Och Guds Ande utiklädde Sacharia, Jojada Prestens son. Han steg fram för folket, och sade till dem: Detta säger Gud: Hvi öfverträden I Herrans bud, det eder icke väl bekommandes varder? Efter I hafven öfvergifvit Herran, så varder han ock öfvergifvandes eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Men de gjorde ett förbund emot honom, och stenade honom, efter Konungens bud, i gårdenom för Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Och Konung Joas tänkte intet på den barmhertighet, som Jojada hans fader med honom gjort hade, utan drap hans son; men då han blef död, sade han: Herren varder detta seendes och sökandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Och då året var omgånget, drog upp de Syrers här, och kommo i Juda och Jerusalem, och förgjorde alla öfverstar i folkena; och allt deras rof sände de till Konungen i Damascon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Ty de Syrers magt kom med fögo folk, likväl gaf Herren i deras hand en ganska stor magt, derföre att de Herran deras fäders Gud öfvergifvit hade; desslikes lade de ock straff på Joas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Och då de drogo ifrå honom, läto de honom qvar i stora krankhet. Och hans tjenare gjorde ett förbund emot honom, för Prestens Jojada söners blods skull, och dråpo honom på hans säng, och han blef död; och man begrof honom uti Davids stad, dock icke ibland Konungagrifterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'De som förbundet gjorde emot honom voro desse: Sabad, Simeaths son, den Ammonitiskones, och Josabad, Simriths son, den Moabitiskones.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Men hans söner, och summan som under honom församlad var, och Guds hus byggning, si, de äro beskrifne uti Historien i Konungabokene. Och hans son Amazia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Fem och tjugu åra gammal var Amazia, då han Konung vardt, och regerade nio och tjugu år i Jerusalem; hans moder het Joaddan af Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Och han gjorde det Herranom väl behagade, dock icke af allt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Då nu hans rike stadfäst var, drap han sina tjenare, som hans fader Konungen slagit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Men deras barn drap han intet; förty det står så skrifvet i lagen i Mose bok, der Herren bjuder och säger: Fäderna skola icke dö för barnen, och icke barnen för fäderna; utan hvar och en skall för sina synd dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Och Amazia församlade Juda, och satte dem efter fädershusen, efter öfverstarna öfver tusende och öfver hundrade, i hela Juda och BenJamin; och talde dem allt ifrå tjugu år, och derutöfver, och fann dem trehundradtusend utvalda, som i här draga kunde, som spjut och sköld föra kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Dertill besoldade han utaf Israel hundradtusend starka krigsmän, för hundrade centener silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Men en Guds man kom till honom, och sade: Konung, låt icke Israels här komma med dig; förty Herren är icke med Israel, eller med all Ephraims barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Ty om du kommer till att bevisa dina dristighet i stridene, så låter Gud dig falla för dina fiendar; förty när Gudi står magten till att hjelpa, och till att stjelpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Amazia sade till Guds mannen: Hvad skall man då göra med de hundrade centener, som jag hafver gifvit de krigsmän af Israel? Guds mannen sade: Herren hafver väl mer än det är, som han dig gifva kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Då skiljde Amazia de krigsmän ifrå, som till honom af Ephraim komne voro, så att de gingo till deras rum igen. Då förgrymmade deras vrede sig svårliga emot Juda, och drogo hem igen illa tillfrids.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Men Amazia var tröst, och förde sitt folk ut, och drog ut i saltdalen, och slog af Seirs barn tiotusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Och Juda barn fångade af dem tiotusend lefvande; dem förde de uppå en bergsklint, och störte dem utför bergsklinten, att de alle sönderkrossades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Men de krigsmän, som Amazia hade ifrå sig sändt, så att de icke drogo med hans folk till stridena, lade sig neder i Juda städer, allt ifrå Samarien intill BethHoron, och slogo af dem tretusend, och togo mycket rof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Och då Amazia igenkom af de Edomeers slagtning, hade han med sig Seirs barnas afgudar, och satte dem sig till gudar, och tillbad dem, och rökte för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Då förgrymmade sig Herrans vrede öfver Amazia, och sände en Prophet till honom. Han sade till honom: Hvi söker du dess folks gudar, som sitt folk intet undsätta kunde ifrå dine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Och då han talade med honom, sade han till honom: Hafver man gjort dig till Konungens råd? Vänd igen; hvi vill du varda slagen? Då vände Propheten igen, och sade: Jag förmärker väl, att Gud hafver i sinnet förderfva dig, efter du detta gjort hafver, och hörer intet mitt råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Och Amazia, Juda Konung, var till råds, och sände bort till Joas, Joahas son, Jehu sons, Israels Konung, och lät säga honom: Kom, låt oss bese hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Men Joas, Israels Konung, sände till Amazia, Juda Konung, och lät säga honom: Törnebusken i Libanon sände till cedreträt i Libanon, och lät säga honom: Gif dina dotter minom son till hustru; men vilddjuren i Libanon lupo öfver törnebuskan, och trampade honom neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Du menar: Si, jag hafver slagit de Edomeer, der förhäfver sig ditt hjerta utaf, och berömmer sig. Nu sitt hemma; hvi söker du efter olycko, att du må falla, och Juda med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Men Amazia hörde det intet; förty det skedde af Gudi, på det att de skulle varda gifne i fiendahand; derföre, att de de Edomeers gudar sökt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Då drog Joas, Israels Konung, upp, och de besågo hvarannan, han och Amazia, Juda Konung, i BethSemes, som i Juda ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Men Juda vardt slagen för Israel, och flydde, hvar och en i sina hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Och Joas, Israels Konung, grep Amazia, Joas son, Joahas sons, Juda Konung, i BethSemes, och förde honom till Jerusalem, och bröt muren neder i Jerusalem, allt ifrån Ephraims port intill hörnporten, fyrahundrade alnar långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Och allt det guld och silfver, och all käril, som för handene voro i Guds hus när ObedEdom, och i fataburenom i Konungshusena, och barnen, tog han till pant med sig till Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Och Amazia, Joas son, Juda Konung, lefde efter Joas, Joahas sons, Israels Konungs, död i femton år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Hvad nu mer af Amazia sägande är, både det första och det sista, si, det är skrifvet uti Juda och Israels Konungars bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Och ifrå den tiden, att Amazia trädde ifrå Herranom, gjorde de ett förbund emot honom i Jerusalem; men han flydde till Lachis. Då sände de efter honom till Lachis, och dråpo honom der;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Och förde honom med hästar, och begrofvo honom när sina fäder uti Juda stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Då tog hele Juda folk Ussia, som var sexton åra gammal, och gjorde honom till Konung i hans faders Amazia stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Han byggde Eloth, och lät det igenkomma till Juda, sedan Konungen afsomnad var med sina fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Sexton åra gammal var Ussia, då han Konung vardt, och regerade tu och femtio år i Jerusalem; hans moder het Jecholia af Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Och han gjorde det Herranom väl behagade, såsom hans fader Amazia gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Och han sökte Gud, så länge Zacharia lefde, den läraren i Guds syner; och så länge han sökte Herren, lät honom Gud väl gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Ty han drog ut, och stridde emot de Philisteer, och bröt neder murarna i Gath, och murarna i Jabne, och murarna i Asdod, och ibland de Philisteer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Ty Gud halp honom emot de Philisteer, emot de Araber, dem i Gurbaal, och emot de Menniter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Och de Ammoniter gåfvo Ussia skänker, och han vardt namnkunnig allt intill der man kommer in i Egypten; ty han vardt ju starkare och starkare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Och Ussia byggde torn i Jerusalem på hörnportenom, och på dalportenom, och på annor hörn, och befäste dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Han byggde ock slott i öknene, och grof många brunnar; ty han hade mycken boskap, både i dalar och slättmark, desslikes åkermän och vingårdsmän på bergen, och på Carmel; förty han hade lust till åkerverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Och Ussia hade en magt till strid, af krigsmän som i här drogo, i tal räknade under Jegiels skrifvarens hand, och Maaseja befallningsmansens, under Hanania hand, den af Konungens öfverstar var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Och talet på de yppersta fäder af de starka örligsmän var tutusend och sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Och under deras hand härsmagten trehundradtusend, och sjutusend och femhundrad, skickelige till strid i härskraft, till att hjelpa Konungenom emot fienderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Och Ussia fick dem till hela hären sköldar, spjut, hjelmar, pansar, bågar, och slungor till att kasta sten med;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Och gjorde i Jerusalem bröstvärn konsteliga, som skulle vara på tornen och hörnen, till att der utskjuta med pil och stora stenar. Och hans rykte kom vidt ut, derföre, att honom besynnerliga hulpet vardt, tilldess han mägtig blef.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Och då han var mägtig vorden, hof hans hjerta sig upp till hans förderf; ty han förtog sig på Herranom sinom Gud, och gick in i Herrans tempel, till att röka på rökaltaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Men Asaria Presten gick efter honom, och åttatio Herrans Prester med honom, starke män;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Och stodo emot Konung Ussia, och sade till honom: Det hörer icke dig till, Ussia, att röka för Herranom; utan Prestomen, Aarons barnom, som till att röka helgade äro. Gack härutu helgedomenom; ty du förtager dig, och det kommer dig till ingen äro för Herranom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Men Ussia vardt vred, och hade ett rökelsekar i handene; och som han trätte med Presterna, gick spitelska ut i hans änne, för Presterna i Herrans hus, inför rökaltaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Och Asaria öfverste Presten vände sig till honom, och alle Presterna; och si, då var han spitelsk i hans änne; och de drefvo honom dädan. Skyndade han sig ock sjelf ut; ty hans plåga var af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Alltså var Konung Ussia spitelsk allt intill sin död, och bodde uti ett fritt hus spitelsk; ty han vardt utdrifven af Herrans hus. Men Jotham hans son stod Konungshuset före, och dömde folket i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Hvad nu mer af Ussia sägande är, både det första och det sista, hafver den Propheten Esaia, Amos son, skrifvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Och Ussia afsomnade med sina fäder, och de begrofvo honom med sina fäder i åkrenom när Konungagrafvarna; ty de sade: Han är spitelsk. Och Jotham hans son vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotham var fem och tjugu åra gammal, då han Konung vardt, och regerade i sexton år i Jerusalem; hans moder het Jerusa, Zadoks dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Och han gjorde det Herranom väl behagade, såsom hans fader Ussia gjort hade; undantagno, att han icke gick i Herrans tempel. Och folket bar sig ännu illa åt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Han byggde den höga porten i Herrans hus, och uppå muren Ophel byggde han mycket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Och byggde städer på Juda berg, och i skogomen byggde han slott och torn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Och han stridde med Ammons barnas Konung; och han vardt dem öfvermägtig; så att Ammons barn gåfvo honom i de samma årena hundrade centen er silfver, tio tusend corar hvete, och tiotusend corar bjugg; så mycket gåfvo ock Ammons barn honom i de andra och tredje årena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Alltså vardt Jotham mägtig; ty han skickade sina vägar för Herranom sinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Hvad nu mer af Jotham sägande är, och alla hans strider, och hans vägar, si, det är skrifvet i Israels och Juda Konungars bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Fem och tjugu åra gammal var han, då han Konung vardt; och regerade i sexton år i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Och Jotham afsomnade med sina fader; och de begrofvo honom i Davids stad. Och hans son Ahas vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Ahas var tjugu åra gammal, då han Konung vardt, och regerade i sexton år i Jerusalem; och gjorde icke det Herranom väl behagade, såsom hans fader David;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Utan han vandrade i Israels Konungars vägar, dertill gjorde han gjuten beläte till Baalim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Och rökte i Hinnoms barnas dal, och brände sina söner upp med eld, efter Hedningarnas styggelse, hvilka Herren för Israels barn fördrifvit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Och offrade, och rökte på höjder, på backar, och under all grön trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Derföre gaf Herren hans Gud honom i Konungens hand af Syrien, så att de slogo honom, och förde bort en stor hop af hans fångna, och läto komma till Damascon. Vardt han ock gifven under Israels Konungs hand, så att han gjorde en stor slagtning på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Ty Pekah, Remalia son, slog af Juda hundrade och tjugu tusend på en dag, som alle dugelige män voro; derföre, att de öfvergåfvo Herran deras fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Och Sichri, en väldig af Ephraim, drap Maaseja, Konungens son, Asrikam husförstan, och Elkana den yppersta näst Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Och Israels barn förde bort fångna af deras bröder tuhundradtusend qvinnor, söner och döttrar; och togo dertill stort rof af dem, och förde rofvet till Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Och var sammastäds en Herrans Prophet, som het Obed. Han gick ut emot hären, som till Samarien kom, och sade till dem: Si, efter Herren edra fäders Gud är vred på Juda, hafver han gifvit dem i edra händer; men I hafven så grufveliga slagit dem ihjäl, att det räcker upp till himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Nu menen I undertrycka eder Juda barn, och Jerusalem till trälar och trälinnor; är det nu icke skuld när eder emot Herran edar Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Så hörer mig nu och förer fångarna dit igen, dem I bortfört hafven af edra bröder; ty Herrans vrede förgrymmar sig öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Då hofvo sig upp någre de myndigaste af Ephraims barn, Asaria, Johanans son, Berisha, Mesillemoths son, Jehiskia, Sallums son, och Amasa, Handlat son, emot dem som utu hären kommo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Och sade till dem: I skolen icke hafva dessa fångar hitin; ty I kommen intet annat än skuld på oss för Herranom, på det I skolen desto flera göra våra synder och skulder; här är skuld nog tillförene, och vrede förgrymmar sig öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Då läto de väpnade fångarna och rofvet, inför öfverstarna, och inför hela menighetena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Då stodo de män upp, som nu vid namn nämnde voro, och togo fångarna, och alle de, som ibland dem nakne voro, klädde de, af det röfvadt var. Och då de hade klädt dem, drogo de skor uppå dem, och gåfvo dem mat och dryck, och smorde dem, och förde på åsnar alla dem, som svage voro, och läto komma dem till Jericho palmstaden, till deras bröder; och kommo igen till Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'På samma tiden sände Konung Ahas till Konungarna af Assur, att de skulle hjelpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Och de Edomeer kommo åter pånytt, och slogo Juda, och förde somliga bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Och de Philisteer lade sig neder i de städer på hedene, och sunnan på Juda, och vunno BethSemes, Ajalon, Gederoth och Socho, med dess döttrar, Thimna med dess döttrar, och Gimso med dess döttrar; och bodde deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Ty Herren plågade Juda för Ahas skull, Israels Konungs, derföre, att han hade blottat Juda, och förtog sig emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Och emot honom kom ThiglathPilneser, Konungen af Assur; han belade honom; men han kunde icke vinna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Och Ahas tog en del i Herrans hus, och i Konungshusena, och i de öfverstas, det han gaf Konungenom i Assur; men det halp honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Yttermera, i hans nöd förtog Konung Ahas sig ännu mer emot Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Och offrade gudomen i Damasco, som honom slagit hade, och sade: Konungens gudar af Syrien hjelpa honom; derföre vill jag offra dem, att de måga ock hjelpa mig; ändock de voro honom och helo Israel till fall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Och Ahas lade tillhopa de tyg i Guds hus, och slog dem sönder, och lyckte igen dörrarna af Herrans hus, och gjorde sig altare i hvarjo vrå i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Och i Juda städer, både här och der, gjorde han höjder till att röka androm gudom, och rette Herran sina fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Hvad nu mer af honom sägande är, och alla hans vägar, både första och sista, si, det är skrifvet i Juda och Israels Konungars bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Och Ahas afsomnade med sina fäder, och de begrofvo honom i stadenom i Jerusalem; ty de lade honom icke ibland Israels Konungars grifter. Och hans son Jehiskia vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Jehiskia var fem och tjugu åra gammal, då han Konung vardt, och regerade nio och tjugu år i Jerusalem; hans moder het Abija, Zacharia dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Och han gjorde det Herranom väl behagade, såsom hans fader David.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Han lät upp dörrarna på Herrans hus, i första månadenom af första årena sins rikes, och gjorde dem färdiga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Och lät komma derin Presterna och Leviterna, och församlade dem på breda gatone östantill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Och sade till dem: Hörer härtill, I Leviter: Helger eder nu, på det I mågen helga Herrans edra fäders Guds hus; och hafver ut orenligheten af helgedomenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Ty våre fäder hafva förtagit sig, och gjort det ondt var för Herranom vårom Gud, och hafva öfvergifvit honom; förty de hafva vändt sitt ansigte ifrå Herrans boning, och vändt ryggen till,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Och hafva igenlyckt dörrarna till förhuset, och utsläckt lamporna, och intet rökverk röka låtit, och intet bränneoffer gjort Israels Gudi i helgedomenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Deraf är Herrans vrede kommen öfver Juda och Jerusalem, och han hafver gifvit dem till att förskingras och förödas, så att man hvisslar åt dem, såsom I med edor ögon sen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Ty si, fördenskull äro våre fäder fallne genom svärd; våre söner, döttrar och hustrur äro bortförde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nu hafver jag i sinnet att göra med Herranom Israels Gud ett förbund, att hans vrede och grymhet må vända sig ifrån oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Nu, mine söner, varer icke försummelige; ty eder hafver Herren utkorat, att I skolen stå för honom, och att I skolen vara hans tjenare och rökare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Då stodo Leviterna upp, Mahath, Amasai son, och Joel, Asaria son af de Kehathiters barn; men af Merari barn, Kis, Abdi son, och Asaria, Jehaleleels son; af de Gersoniters barn, Joah, Simma son, och Eden, Joahs son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Och af Elizaphans barn, Simri och Jegiel; af Assaphs barn, Sacharia och Matthania;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Af Hemans barn, Jehiel och Simei; af Jeduthuns barn, Semaja och Usiel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Och de församlade sina bröder, och helgade sig, och gingo in, efter Konungens bud, af Herrans ord, till att rena Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Och Presterna gingo in uti Herrans hus, till att rena det, och lade all den orenhet, som i Herrans tempel funnen vardt, uppå gården åt Herrans hus; och Leviterna togo henne upp, och båro ut i Kidrons bäck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'På första dagen af första månadenom begynte de till att helga sig, och på åttonde dagen i den månaden gingo de uti Herrans förhus, och helgade Herrans hus åtta dagar, och fullkomnade det på sextonde dagen i första månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Och de gingo in till Konung Hiskia, och sade: Vi hafve renat hela Herrans hus, bränneoffrets altare, och all dess tyg; skådobrödens bord, och all dess tyg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Och all de kärile, som Konung Ahas, då han Konung var, bortkastat hade, då han syndade; dem hafve vi tillredt och helgat, si, de äro för Herrans altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Då var Konung Jehiskia bittida uppe, och församlade de öfversta i stadenom, och gick upp till Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Och hade fram sju stutar, sju vädrar, sju lamb och sju getabockar, till syndoffer, för riket, för helgedomen, och för Juda. Och han sade till Presterna Aarons barn, att de skulle offra på Herrans altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Då slagtade de stutarna, och Presterna togo blodet, och stänkte det på altaret; och slagtade vädrarna, och stänkte blodet på altaret; och slagtade lamben, och stänkte blodet på altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Och hade bockarna fram till syndoffer inför Konungen och menighetena, och lade sina händer på dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Och Presterna slagtade dem, och stänkte deras blod på altaret, till att försona hela Israel; ty Konungen hade befallt offra bränneoffer och syndoffer för hela Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Och han satte Leviterna i Herrans hus med cymbaler, psaltare och harpor, såsom David det befallt hade, och Gad, Konungens Siare, och den Propheten Nathan; ty det var Herrans bud igenom hans Propheter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Och Leviterna stodo med Davids strängaspel, och Presterna med trummeter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Och Hiskia bad dem göra bränneoffer på altarena; och som man begynte bränneoffret, begyntes ock på Herrans sång och trummeterna, och med mångahanda Davids, Israels Konungs, strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Och hela menigheten tillbad; Och sångarenas sång och trummeternas trummetning varade allt intilldess bränneoffret öfverfaret var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Då nu bränneoffret gjordt var, bugade sig Konungen, och alle de som när honom vid handen voro, och tillbådo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Och Konung Jehiskia, med öfverstarna, bad Leviterna lofva Herran, med Davids och den Siarens Assaphs dikt. Och de lofvade honom med glädje; och de böjde sig, och tillbådo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Och Jehiskia svarade, och sade: Nu hafven I fyllt edra händer Herranom; går fram och bärer fram offer och lofoffer till Herrans hus. Och menigheten bar fram offer och lofoffer; och hvar och en af friviljogt hjerta bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Och talet på bränneoffret, som menigheten frambar, var sjutio oxar, hundrade vädrar, och tuhundrad lamb; och allt detta till bränneoffer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Och de helgade sexhundrad oxar, och tretusend får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Men Presterna voro för få, och förmådde icke draga hudena af allo bränneoffrena; derföre togo de sina bröder Leviterna, tilldess det verk öfverståndet vardt, och så länge Presterna helgade sig; förty de Leviter stå lätteligare till att helga, än Presterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Var också bränneoffret mycket, med det feta af tackoffren, och drickoffret till bränneoffret. Alltså vardt ämbetet i Herrans hus redo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Och Jehiskia fröjdade sig med allo folkena, att man var så redo vorden med Gudi; ty det skedde med hastighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Och Jehiskia sände ut till hela Israel och Juda, och skref bref till Ephraim och Manasse, att de skulle komma till Herrans hus i Jerusalem, och hålla Passah Herranom Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Och Konungen höll ett råd med sina öfversta, och med hela menighetene i Jerusalem, till att hålla Passah i dem andra månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Förty de kunde icke hålla det på den samma tiden, derföre att Presterna icke nog helgade voro, och folket icke ännu tillhopakommet var till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Och det täcktes Konungenom väl, och hela menighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Och de beställde, att det så utropadt vardt i hela Israel, ifrå BerSeba allt intill Dan, att de skulle komma och hålla Passah Herranom Israels Gud i Jerusalem; ty de hade i långan tid icke hållit det, såsom det skrifvet står.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Och båden gingo åstad med brefven ifrå Konungens och hans öfverstars hand, igenom hela Israel och Juda, efter Konungens befallning, och sade: I Israels barn, vänder eder om till Herran, Abrahams, Isaacs och Israels Gud, så varder han sig vändandes till de undsluppna, som ännu återlefde äro ifrå Konungens hand i Assur;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Och varer icke såsom edre fäder och bröder, som sig emot Herran deras fäders Gud förtagit hafva; och han gaf dem till en förödelse, såsom I sjelfve sen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Så varer nu icke halsstyfve, såsom edra fäder; utan räcker Herranom edra hand, och kommer till hans helgedom, den han helgat hafver till evig tid; och tjener Herranom edrom Gud, så vänder sig hans vredes grymhet ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Förty, om I omvänden eder till Herran, så skola edra bröder och barn få barmhertighet för dem som dem fångna hålla, så att de skola komma åter i detta land igen; ty Herren edar Gud är nådelig och barmhertig, och varder icke vändandes sitt ansigte ifrån eder, om I omvänden eder till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Och båden gingo ifrå den ena staden till den andra, i Ephraims och Manasse land, och allt intill Sebulon; men de gjorde gabb utaf dem, och bespottade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Dock någre af Asser, och Manasse, och Sebulon, ödmjukade sig, och kommo till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Kom också Guds hand i Juda, så att han gaf dem endrägtigt hjerta, till att göra efter Konungens och de öfverstars bud, efter Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Och kom samman i Jerusalem en stor hop folk, till att hålla osyrade bröds högtidena i dem andra månadenom, en mägta stor menighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Och de stodo upp, och kastade bort de altare, som i Jerusalem voro, och allt rökverk hofvo de bort och kastade uti den bäcken Kidron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Och slagtade Passah på fjortonde dagen af den andra månaden; och Presterna och Leviterna blygdes, och helgade sig, och båro bränneoffer till Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Och stodo i deras ordning, såsom det sig borde, efter Mose den Guds mansens lag; och Presterna stänkte blodet af Leviternas hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Ty der voro månge i menighetene, som sig icke helgat hade; derföre slagtade Leviterna Passah för alla dem som icke rene voro, så att de Herranom helgade vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Var ock desslikes mycket folk af Ephraim, Manasse, Isaschar och Sebulon, som icke rene voro; utan åto Passahlambet, icke såsom skrifvet står; ty Jehiskia bad för dem, och sade: Herren, som milder är, varder dem allom nådelig,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Som ställa sitt hjerta till att söka Herran Gud, deras fäders Gud, och icke för den helga renselsens skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Och Herren hörde Jehiskia, och helade folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Alltså höllo Israels barn, som i Jerusalem funne vordo, osyrade bröds högtidena i sju dagar, med stora fröjd. Och Leviterna och Presterna lofvade Herran hvar dag, med Herrans mägtiga strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Och Jehiskia talade hjerteliga med alla Leviterna, som ett godt förstånd hade om Herran; och de åto öfver hela högtidena i sju dagar, och offrade, och tackade Herranom deras fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Och hela menigheten vardt till råds, att hålla det ännu i andra sju dagar, och höllo också de sju dagarna med glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Ty Hiskia, Juda Konung, gaf till häfoffer för menighetena tusende stutar, och sjutusend får; men de öfverste gåfvo till häfoffer för menighetene tusende stutar och tiotusend får; alltså helgade sig då månge Presterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Och gladdes hela menigheten Juda, Presterna och Leviterna, och hela menigheten, som af Israel kommen var, och främlingarna, som af Israels land komne voro, och de som i Juda bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Och var en stor glädje i Jerusalem; ty ifrå Salomos, Davids sons, Israels Konungs tid, hade sådana icke varit i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Och Presterna och Leviterna stodo upp, och välsignade folket; och deras röst vardt hörd, och deras bön kom inför hans helga boning i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Då detta alltså uträttadt var, drogo ut alle de Israeliter, som i Juda städer funne voro, och bröto ned stoderna, och höggo bort lundarna, och bröto ned höjderna och altaren, i hela Juda, BenJamin, Ephraim och Manasse, tilldess de gjorde en ända på dem. Och Israels barn drogo alle till sina ägor i sina städer igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Men Jehiskia ställde Presterna och Leviterna uti deras ordning, hvar och en efter sitt ämbete, både Prester och Leviter, till bränneoffer och tackoffer, att de skulle tjena, tacka och lofva, i portarna åt Herrans lägre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Och Konungen gaf sin del af sina håfvor till bränneoffer, om morgon och om afton, och till bränneoffer om Sabbatherna, och nymånadom, och högtidom, efter som skrifvet står i Herrans lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Och han sade till folket, som i Jerusalem bodde, att de skulle gifva Presterna och Leviterna delar, att de måtte desto bättre akta på Herrans lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Och då det talet kom ut, gåfvo Israels barn mycken förstling af säd, vin, oljo, hannog och allahanda årsväxt på markene; och allahanda tiond förde de in, ganska mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Förde också Israels barn och Juda, som i Juda städer bodde, tiond fram af fä och får, och tiond af det helgada som de Herranom sinom Gud helgat hade, och lade en hop här, och en hop der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Uti tredje månadenom begynte de att lägga hoparna, och i sjunde månadenom lyktade de det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Och då Jehiskia med de öfversta ingingo, och sågo hoparna, lofvade de Herran, och hans folk Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Och Jehiskia frågade Presterna och Leviterna om hoparna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Och Asaria Presten, den ypperste i Zadoks hus, sade till honom: Ifrå den tid man begynte införa häfoffret i Herrans hus, hafve vi ätit och äre mätte vordne, och här är ännu mycket qvart; förty Herren hafver välsignat sitt folk; derföre är denne hopen öfverblefven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Då befallde Konungen, att de skulle reda till kistor i Herrans hus; och de tillredde dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Och lade derin häfoffret, tionden, och det helgada, på sina tro. Och öfver det samma var skickad Chanania den Leviten, och Simei hans broder den andre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Och Jehiel, Asasia, Nahath, Asahel, Jerimoth, Josabad, Eliel, Jismacha, Mahath och Benaja, förskickade af Chanania och Simei hans broders hand, efter Konungens Jehiskia befallning. Men Asaria var öfverste i Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Och Kore, Jimna son, den Leviten, den dörravaktaren östantill, var öfver de friviljoga Guds gåfvor, som Herranom till häfoffer gifna vordo, och öfver det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Och under hans hand voro Eden, Minjamin, Jesua, Semaja, Amaria och Sechania, uti Presternas städer, på sina tro; att de skulle gifva sina bröder efter deras ordning, dem minsta såsom dem största;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Desslikes dem som för manspersoner räknade vordo, tre åra gamle, och derutöfver, ibland alla dem som uti Herrans hus gingo, hvar på sin dag till sitt ämbete, och i sine vakt efter sitt skifte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Sammalunda dem som för Prester räknade vordo, i deras fäders hus, och Leviterna, ifrå tjugu år och derutöfver, i deras vakt efter deras skifte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Dertill dem som räknade vordo ibland deras barn, hustrur, söner och döttrar, i hela menighetene; förty de helgade på sina tro det helgada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Voro också män vid namn nämnde ibland Aarons barn, Presterna uppå förstädernes mark, i alla städer, att de skulle del gifva alla manspersoner ibland Presterna, och allom dem som ibland Leviterna räknade vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Alltså gjorde Jehiskia i hela Juda, och gjorde det godt, rätt och sant var för Herranom sinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Och i all handel, som han tog sig före med Guds hus tjenste, efter lagen och buden, till att söka sin Gud, det gjorde han af allt hjerta; derföre gick han det ock väl igenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Efter denna handel och trohet kom Sanherib, Konungen i Assur, och drog in i Juda, och lägrade sig för de fasta städer, och hade i sinnet, att han ville taga det in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Då Jehiskia såg, att Sanherib kom, och hans ansigte stod till att strida emot Jerusalem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Vardt han till råds med sina öfversta och väldiga, att de skulle öfvertäcka vattnen af källorna, som utanför staden voro; och de hulpo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Och sig församlade mycket folk, och öfvertäckte alla källor och bäcker midt i landena, och sade, att de Konungar af Assur icke skola mycket vatten finna, när de komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Och han tog styrko till sig, och byggde igen alla murar, som förfallne voro, och gjorde torn deruppå; och byggde ändå derutanföre en annan mur. Och Millo gjorde han fast i Davids stad, och lät göra många värjor och sköldar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Och skickade höfvitsmän till strids med folket; och han församlade dem till sig på den breda gatona vid stadsporten, och talade hjerteliga till dem, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Varer tröste och vid godt mod; frukter eder intet, och gifver eder intet för Konungenom af Assur, eller för all den hop, som när honom är; ty med oss är en större än med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Med honom är en köttslig arm; men med oss är Herren vår Gud, att han skall hjelpa oss, och föra våra strid. Och folket förlät sig på Jehiskia, Juda Konungs, ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Derefter sände Sanherib, Konungen i Assur, sina tjenare till Jerusalem, ty han låg för Lachis, och all hans magt med honom, till Jehiskia, Juda Konung, och till hela Juda, som i Jerusalem var, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Detta säger Sanherib, Konungen i Assur: Hvar förtrösten I eder uppå, I som bon uti det belagda Jerusalem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Jehiskia förförer eder, att han må komma eder i döden, hunger och törst, och säger: Herren vår Gud skall undsätta oss utu Konungens hand af Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Är icke han den Jehiskia, som hans höjder och altare bortkastat hafver, och sagt till Juda och Jerusalem: För ett altare skolen I tillbedja, och deruppå röka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Veten I icke, hvad jag och mine fäder gjort hafva allom folkom i landen? Hafva ock Hedningarnas gudar i landen kunnat hjelpa deras land ifrå mine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Hvilken är den af alla dessa Hedningarnas gudar, som mina fäder nederlagdt hafva, som hafver kunnat hjelpa sitt folk utu mine hand; att edar Gud skulle förmå hjelpa eder utu mine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Så låter icke nu Hiskia bedraga eder, och låter icke tälja eder i sådant sinne, och tror honom intet; förty, medan ingen alla Hedningars och Konungarikens gud hafver kunnat hjelpa sitt folk ifrå mine och mina fäders hand, så varda icke heller edre gudar eder hjelpande ifrå mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Dertill talade hans tjenare ännu mer emot Herran Gud, och emot hans tjenare Jehiskia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Skref han ock bref ut, deruti han hädde Herran Israels Gud, och talade om honom, och sade: Såsom Hedningarnas gudar i landen icke hafva hulpit deras folk ifrå mine hand, så varder ock icke Jehiskia Gud hjelpandes hans folk ifrå mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Och de ropade med höga röst, på Judiskt mål, till folket i Jerusalem, som på muren voro, till att göra dem rädda och förskräckta, att de så måtte få staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Och talade de så emot Jerusalems Gud, såsom emot folkens gudar på jordene, hvilke menniskos handaverk voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Men Konung Jehiskia med Prophetenom Esaia, Amos son, bådo deremot, och ropade till himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Och Herren sände en Ängel, som förgjorde alla de väldiga i hären, och Förstarna och öfverstarna i Konungens lägre af Assyrien; så att han med skam drog åter till sitt land igen. Och då han gick uti sins guds hus, dråpo honom der med svärd, de som af hans eget lif komne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Alltså halp Herren Jehiskia, och dem i Jerusalem, utu Sanheribs hand, Konungens i Assyrien, och alla andras; och bevarade dem för allom omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Så att månge båro skänker Herranom till Jerusalem, och klenodier Jehiskia, Juda Konung. Och han vardt sedan högt räknad för alla Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'På den tiden vardt Jehiskia dödsjuk, och han bad Herran; han hörde honom, och gaf honom ett tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Dock vedergalt icke Jehiskia, efter som honom gifvet var; ty hans hjerta upphof sig; derföre kom vrede öfver honom, och öfver Juda, och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Men Jehiskia ödmjukade sig, att hans hjerta hade upphäfvit sig, samt med dem i Jerusalem; derföre kom Herrans vrede icke öfver dem, så länge Jehiskia lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Och Jehiskia hade ganska stora rikedomar och härlighet; och han gjorde sig en skatt af silfver, guld, ädla stenar, örter, sköldar och allahanda kostelig tyg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Och hus till inkommandes årsväxt, vin och oljo; och stall för allahanda boskap, och hus för får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Och han byggde sig städer, och hade boskap, får och fä till en stor hop; förty Gud gaf honom ganska många ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Han är den Jehiskia, som igentäppte den öfra vattukällona i Gihon, och ledde henne nedåt, vester om Davids stad. Och var Jehiskia lyckosam i alla sina gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Men då de öfverstars sändningabåd af Babel till honom sände voro, att fråga efter det undertecken, som i landena skedt var, öfvergaf Gud honom, så att han försökte honom; på det att kunnigt skulle varda allt det i hans hjerta var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Hvad nu mer af Jehiskia sägande är, och om hans barmhertighet, si, det är skrifvet i den Propheten Esaia, Amos sons, syn, uti Juda och Israels Konungars bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Och Jehiskia afsomnade med sina fäder, och de begrofvo honom öfver Davids barnas grifter; och hele Juda och de i Jerusalem gjorde honom äro i hans död. Och hans son Manasse vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasse var tolf åra gammal, då han Konung vardt, och regerade fem och femtio år i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Och gjorde det ondt var för Herranom, efter Hedningarnas styggelse, som Herren för Israels barn fördrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Och han afvände sig, och uppbyggde höjder, som hans fader Jehiskia nederslagit hade, och stiktade altare till Baalim, och gjorde lundar, och tillbad allan himmelens är, och tjente dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Han byggde ock altare i Herrans hus, om hvilket Herren sagt hade: I Jerusalem skall mitt Namn vara i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Och han byggde altare till allan himmelens här, i båda gårdarna åt Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Och han lät sina söner gå genom eld uti Hinnoms sons dal, och utvalde dagar, och aktade på foglarop, och brukade trolldom, och stiktade spåmän och tecknatydare, och gjorde mycket det Herranom illa behagade, till att reta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Han satte desslikes beläte och afgudar, som han i Guds hus göra lät, der Gud om sagt hade till David, och hans son Salomo: Uti detta hus, i Jerusalem, som jag utvalt hafver för alla Israels slägter, vill jag sätta mitt Namn i evig tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Och skall icke mer låta Israels fot vika ifrå landena, som jag deras fäder beställt hafver; så framt de hålla sig, så att de göra allt det jag dem budit hafver, i all lag, bud och rätter, igenom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Men Manasse förförde Juda och dem i Jerusalem, så att de gjorde värre än Hedningarna, som Herren för Israels barn förgjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Och när Herren lät tala till Manasse och hans folk, aktade de det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Derföre lät Herren komma öfver dem de öfverstar öfver Konungens här i Assur; de togo Manasse fången i fjettrar, och bundo honom med kedjor, och förde honom till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Och som han var i ångest, bad han Herran sin Gud, och ödmjukade sig storliga för sina fäders Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Och bad honom innerliga. Då hörde han hans bön, och lät honom komma till Jerusalem igen till sitt rike. Och besinnade då Manasse, att Herren är Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Derefter byggde han de yttersta murarna till Davids stad, vestantill vid Gihon i bäckenom, och der man ingår genom fiskaporten, och allt omkring intill Ophel, och gjorde dem ganska höga; och satte höfvitsmän uti Juda fasta städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Och kastade bort de främmande gudar och afgudar utu Herrans hus, och all altare, som han byggt hade på Herrans hus berg, och i Jerusalem, och kastade dem ut för staden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Och uppfärdade Herrans altare, och offrade deruppå tackoffer och lofoffer, och befallde Juda, att de skulle tjena Herranom Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Likväl offrade folket ännu på höjderna; dock Herranom deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Hvad nu mera af Manasse sägande är, och om hans bön till sin Gud, och om de ord, som Siarena med honom talade i Herrans Israels Guds Namn, si, det är ibland Israels Konungars gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Och om hans bön, och huru han bönhörd vardt, och alla hans synder och missgerningar, och rummet, der han höjder uppå byggde, och lundar och afgudar stiktade, förr än han ödmjukad vardt, si, det är allt skrifvet ibland Siarenas gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Och Manasse afsomnade med sina fäder, och de begrofvo honom i hans hus; och hans son Amon vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Tu och tjugu år gammal var Amon, då han Konung vardt, och regerade tu år i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Och gjorde det ondt var för Herranom, såsom hans fader Manasse gjort hade; och Amon offrade allom afgudom, som hans fader Manasse gjort hade, och tjente dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Men han ödmjukade sig intet för Herranom, såsom hans fader Manasse sig ödmjukat hade; ty denne Amon förökade skuldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Och hans tjenare gjorde ett förbund emot honom, och dråpo honom i hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Då slog folket i landena alla dem som förbundet emot Konung Amon gjort hade; och folket i landena gjorde hans son Josia till Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Åtta åra gammal var Josia, då han Konung varat, och regerade ett och tretio år i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Och gjorde det godt var för Herranom, och vandrade uti sins faders Davids vägom, och vek hvarken på den högra eller venstra sidona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Ty i åttonde årena af sitt rike, medan han ännu en dräng var, begynte han att söka sins faders Davids Gud. Och i tolfte årena begynte han till att rensa Juda och Jerusalem af höjder, och lundar, och afgudar, och gjuten beläte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Och lät afbryta för sig Baalims altare; och beläten deruppå högg han neder; och de lundar, och afgudar, och beläte, slog han sönder, och gjorde dem till stoft, och strödde dem på deras grifter, som för dem offrat hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Och brände upp Presternas ben på altaren, och rensade alltså Juda och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Sammalunda i Manasse städer, Ephraim, Simeon, och allt intill Naphthali, uti deras ökner, allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Och då han hade afbrutit altaren och lundarna, och afgudarna sönderkrossat, och all beläte sönderslagit i hela Israels land, drog han åter till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Uti adertonde årena sins rikes, då han landet och huset renat hade, sände han Saphan, Azalia son, och Maaseja stadsfogdan, och Joah. Joahas son, cancelleren, till att förbättra Herrans sins Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Och de kommo till den öfversta Presten Hilkia, och man fick dem de penningar, som till Guds hus införde voro, hvilka Leviterna, som dörrarna vaktade, församlat hade, af Manasse, Ephraim, och af allom igenlefdom i Israel, och af hela Juda och BenJamin, och af dem som i Jerusalem bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Och de gåfvo dem uti arbetarenas händer, som beställde voro till Herrans hus; och de gåfvo dem som arbetade på Herrans hus, der det förfallet var, att de skulle förbättra huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'De samme gåfvo dem sedan timbermannom och byggningsmannom, till att köpa huggen sten, och höfladt trä till bjelkar, på de hus, som Juda Konungar förderfvat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Och männerna arbetade på verket på sina tro; och öfver dem voro skickade Jahath, och Obadja, Leviter, utaf Merari barn; Sacharia och Mesullam, utaf de Kehathiters barn, till att drifva arbetet; och voro alle Leviter, som på strängaspel kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Men öfver dragare, och dem som drefvo till allahanda arbete i all ämbeten, voro utaf Leviterna, skrifvare, ämbetsmän och dörravaktare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Och då de togo ut penningarna, som i Herrans hus inlagde voro, fann Hilkia Presten lagbokena, som Herren genom Mose gifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Och Hilkia svarade, och sade till Saphan skrifvaren: Jag hafver funnit lagbokena i Herrans hus. Och Hilkia fick Saphan bokena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Och Saphan bar henne till Konungen, och gaf Konungenom svar igen, och sade: Allt det i dina tjenares händer befaldt är, det göra de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Och de penningar, som i Herrans hus funne äro, hafva de lagt ihop, och fått dem föreståndarenom och arbetaromen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Och Saphan skrifvaren underviste Konungen, och sade: Hilkia Presten hafver fått mig ena bok. Och Saphan las deruti för Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Och då Konungen hörde lagsens ord, ref han sin kläder sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Och Konungen böd Hilkia, och Ahikam, Saphans son, och Abdon, Micha son, och Saphan skrifvarenom, och Asaja, Konungens tjenare, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Går bort, och fråger Herran för mig, och för dem som qvare äro i Israel, och för Juda, om bokens ord, som funnen är; förty Herrans grymhet är stor, som öfver oss upptänd är, att våre fäder icke hållit hafva Herrans ord, att de måtte gjort såsom i desso bok skrifvet står.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Då gick Hilkia, samt med de andra, som af Konungenom sände voro, bort till den Prophetissan Hulda, Sallums hustru, Thakehaths sons, Hasra sons, klädevaktarens, som i Jerusalem bodde, uti den andra delenom, och talade detta med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Och hon sade till dem: Detta säger Herren Israels Gud: Säger dem mannenom, som eder till mig sändt hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Detta säger Herren: Si jag skall låta komma olycko öfver detta rum, och dess inbyggare, nämliga all de förbannelse, som i bokene skrifven stå, som för Juda Konung läsen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Derföre, att de hafva öfvergifvit mig, och rökt androm gudom, så att de hafva rett mig med allt deras händers verk; och min grymhet skall upptänd varda öfver detta rum, och icke utsläckt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Och Juda Konunge, som eder utsändt hafver till att fråga Herran, skolen I så säga: Detta säger Herren Israels Gud, om de ord, som du hörde:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Derföre, att ditt hjerta hafver bevekt sig, och du hafver ödmjukat dig för Gudi, då du hans ord hörde emot detta rum, och emot dess inbyggare, och hafver ödmjukat dig för mig, och rifvit din kläder, och gråtit för mig; så hafver jag ock hört dig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Si, jag vill samka dig till dina fader, att du uti dina graf med frid samkad varder, att din ögon icke skola se all denna olyckon, som jag öfver detta rum och dess inbyggare skall komma låta. Och de sade Konungenom detta igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Då sände Konungen bort, och lät tillhopakomma alla de äldsta i Juda och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Och Konungen gick upp i Herrans hus, och hvar man i Juda, och inbyggarena i Jerusalem, Presterna, Leviterna, och allt folket, både små och store; och vordo för deras öron läsen all ord i förbundsens bok, som i Herrans hus funnen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Och Konungen gick i sitt rum, och gjorde ett förbund för Herranom, att man skulle vandra efter Herranom, till att hålla hans bud, vittnesbörd och rätter, af allt hjerta, och af allo själ, till att göra efter all förbundsens ord, som skrifne stodo i desso bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Och stodo der alle de, som i Jerusalem och i BenJamin för handene voro. Och Jerusalems inbyggare gjorde efter Guds förbund, deras fäders Guds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Och Josia hof bort all styggelse utur all land, som Israels barnas voro, och skaffade att alle de, som i Israel funne vordo, tjente Herranom deras Gud. Så länge Josia lefde, veko de intet ifrå Herranom deras fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Och Josia höll Herranom Passah i Jerusalem; och slagtade Passah på fjortonde dagenom i första månaden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Och han ställde Presterna uti deras vakt, och styrkte dem till deras ämbete i Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Och sade till Leviterna, som hela Israel lärde, och Herranom helgade voro: Låter den helga arken uti huset, som Salomo, Davids son, Israels Konung, byggt hafver; I skolen icke bära honom på axlarna; så tjener nu Herranom edrom Gud, och hans folke Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Och skicker edra fäders hus, i edor skifte, såsom de beskrifne äro af David, Israels Konung, och hans son Salomo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Och står i helgedomenom efter fädernas hus skifte ibland edra bröder af folket, och desslikes fädernas hus skifte ibland Leviterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Och slagter Passah, och helger eder, och skicker edra bröder, att de göra efter Herrans ord genom Mose.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Och Josia gaf till häfoffer för den meniga man lamb och kid, alltsammans till Passah, för alla dem som vid handena voro, på talet tretiotusend, och tretusend nöt; alltsammans af Konungens ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Hans Förstar gåfvo till häfoffer friviljoge för folket, och för Presterna och Leviterna; nämliga Hilkia, Sacharia och Jehiel, Förstarna i Guds hus, ibland Presterna till Passah, tutusend och sexhundrad (lamb och kid), dertill trehundrad nöt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Men Chanania, Semaja, Nethaneel, och hans bröder, Hasabia, Jejel och Josabad öfverstar för Leviterna, gåfvo Levitomen häfoffer till Passah, femtusend (lamb och kid), och dertill femhundrad nöt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Alltså vardt Gudstjenst beskickad, och Presterna stodo i sitt rum, och Leviterna i sin ordning, efter Konungens bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Och de slagtade Passah, och Presterna togo af deras händer och stänkte, och Leviterna drogo thy hudena af;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Och gjorde bränneoffer deraf, att de skulle dela det ut ibland fädershusen uti deras meniga hop, till att offrat Herranom, såsom skrifvet står i Mose bok; sammaledes gjorde de ock med oxarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Och de kokade Passah vid eld, såsom det sig borde; men hvad som helgadt var, kokade de i grytor, kettlar och pannor, och de gjorde det med hast för meniga hopen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Derefter redde de ock för sig, och för Presterna; förty Presterna, Aarons söner, hade att skaffa med bränneoffret, och med det feta, allt intill nattena; derföre måste Leviterna tillreda för sig och för Presterna, Aarons söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Och sångarena, Assaphs barn, stodo i sitt rum, efter Davids bud, och Assaphs, och Hemans, och Jeduthuns, Konungens Siares; och dörravaktarena vid alla dörrarna, och de veko intet ifrå sitt ämbete; ty Leviterna, deras bröder, redde till för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Alltså vardt beskickad all Herrans tjenst på den dagen, så att man höll Passah, och bränneoffer gjorde på Herrans altare, efter Konung Josia bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Alltså höllo Israels barn, som vid handen voro, Passah i den tiden, och osyrade bröds högtid i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Intet Passah var i Israel hållet, såsom detta, allt ifrå den Propheten Samuels tid; och ingen Israels Konung hade sådant Passah hållit, såsom Josia Passah höll, och Presterna, Leviterna, hela Juda och det af Israel för handen var, och Jerusalems inbyggare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Uti adertonde årena af Josia rike vardt detta Passah hållet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Derefter, när Josia huset tillredt hade, drog Necho, Konungen i Egypten, upp, till att strida emot Carchemis vid Phrath; och Josia drog ut emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Men han sände båd till honom, och lät säga honom: Hvad hafver jag med dig göra, Juda Konung? Jag kommer icke nu emot dig, utan jag strider emot ett (annat) hus; och Gud hafver sagt, att jag skulle skynda mig; håll upp att göra emot Gud, som med mig är, att han icke förderfvar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Men Josia vände icke sitt ansigte ifrå honom, utan ställde sig till att strida emot honom; och lydde intet Necho ord utaf Guds mun, och kom till att strida med honom på den slättene vid Megiddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Och skyttorna sköto Konung Josia. Och Konungen sade till sina tjenare: Förer mig hädan; ty jag är illa sår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Och hans tjenare togo honom af vagnen, och lade honom på hans andra vagn, och förde honom till Jerusalem. Och han blef död, och vardt begrafven ibland sina fäders grifter; och hele Juda och Jerusalem sörjde för Josia skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Och Jeremia jämrade sig öfver Josia; och alle sångare och sångerskor höllo deras klagovisor öfver Josia, allt intill denna dag, och gjorde en sedvänjo deraf i Israel; si, det är skrifvet uti de klagovisor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Hvad nu mer af Josia sägande är, och om hans barmhertighet, efter skriftene i Herrans lag,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'Och hans gerningar, både de första och de sista, si, det är skrifvet uti Israels och Juda Konungars bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Och folket i landena tog Joahas, Josia son, och gjorde honom till Konung i hans faders stad i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Tre och tjugu åra gammal var Joahas, då han Konung vardt och regerade i tre månader i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Ty Konungen i Egypten satte honom af i Jerusalem, och beskattade landet till hundrade centener silfver, och en centener guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Och Konungen i Egypten gjorde Eliakim, hans broder, till Konung öfver Juda och Jerusalem, och förvände hans namn Jojakim; men Necho tog hans broder Joahas, och förde honom uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Fem och tjugu åra gammal var Jojakim, då han Konung vardt; och regerade ellofva år i Jerusalem, och gjorde det ondt var för Herranom sinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Och NebucadNezar, Konungen i Babel, drog upp emot honom, och band honom med kedjor, att han skulle föra honom till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Och förde NebucadNezar någor Herrans hus kärile till Babel, och satte dem uti sitt tempel i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Hvad nu mer af Jojakim sägande är, och hans styggelse, som han gjorde, och med honom funnen vordo, si, de äro skrifne uti Israels och Juda Konungars bok: och hans son Jojachin vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Åtta åra gammal var Jojachin, då han Konung vardt, och regerade i tre månader och tio dagar i Jerusalem, och gjorde det Herranom illa behagade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Då nu året omgick, sände NebucadNezar, och lät hemta honom till Babel, med de kosteliga tygen i Herrans hus; och man gjorde Zedekia hans broder till Konung öfver Juda och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Ett och tjugu åra gammal var Zedekia, då han Konung vardt; och regerade ellofva år i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Och gjorde det ondt var för Herranom sinom Gud, och ödmjukade sig intet för den Propheten Jeremia, som talade utaf Herrans mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Dertill vardt han affällig ifrå NebucadNezar, Konungenom i Babel, hvilken af honom en ed vid Gud tagit hade; och vardt halsstyf, och förstockade sitt hjerta, så att han intet omvände sig till Herran Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Sammalunda alle öfverstarna ibland Presterna, samt med folket, syndade svårliga, och förtogo sig med allahanda Hedningastyggelse, och orenade Herrans hus, det han helgat hade i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Och Herren deras fäders Gud sände till dem med sin bådskap bittida; ty han skonade sitt folk och sina boning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Men de begabbade Guds bådskap, och föraktade hans ord, och bespottade hans Propheter, intilldess Herrans grymhet växte öfver hans folk, att dem nu intet mer stod till botande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Ty han förde öfver dem de Chaldeers Konung, och lät dräpa deras unga män med svärd, uti deras helgedoms huse, och skonade hvarken piltar eller pigor, hvarken åldrigom eller utgamlom; alla gaf han dem i hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Och all tyg i Guds hus, stor och små, håfvorna i Herrans hus, och Konungens och hans Förstars håfvor; allt lät han föra till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Och de brände upp Guds hus, och bröto ned murarna i Jerusalem; och all deras palats brände de upp med eld, så att all deras kosteliga ting blefvo förfaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Och de som för svärdet undsluppo, fördes till Babel, och vordo hans och hans söners trälar, tilldess riket kom till de Perser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'På det att fullkomnas skulle Herrans ord genom Jeremia mun, tilldess att landet hade fyllest i sina Sabbather; förty hele tiden af förderfvelsen var Sabbath, intilldess sjutio år fullkomnade vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Men i första årena Cores, Konungens i Persien, på det fullkomnadt skulle varda Herrans ord, taladt genom Jeremia mun, uppväckte Herren Cores anda, Konungens i Persien, att han lät utropa öfver allt sitt rike, ja ock med bref, och säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Detta säger Cores, Konungen i Persien: Herren Gud af himmelen hafver gifvit mig all rike i landen, och hafver befallt mig bygga sig ett hus i Jerusalem i Juda; hvilken som nu ibland eder är af hans folk, med honom vare Herren hans Gud, och drage ditupp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Uti första årena Cores, Konungens i Persien, på det fullkomnas skulle Herrans ord, taladt igenom Jeremia mun, uppväckte Herren Cores anda, Konungens i Persien, att han lät utropa i all sitt rike, och igenom skrifvelse, och säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Detta säger Cores, Konungen i Persien: Herren Gud i himmelen hafver gifvit mig all rike i landen, och hafver befallt mig bygga sig ett hus i Jerusalem, i Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Hvilken som nu ibland eder är af hans folk, med honom vare hans Gud, och han drage upp till Jerusalem i Juda, och uppbygge Herrans Israels Guds hus; han är den Gud, som i Jerusalem är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Och hvilken som ännu igenlefd är, ehvar som helst han en främling är, honom hjelpe folket i det rum med silfver och guld, med gods och boskap, af en fri vilja, till Guds hus i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Då stodo upp de öfverste fäder af Juda och BenJamin, och Presterna och Leviterna, alle, hvilkas anda Gud uppväckte till att draga upp, och bygga Herrans hus i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Och alle de som voro omkring dem, styrkte deras hand med silfver och gyldene tyg, med gods och boskap, och klenodier; förutan det de friviljoge gåfvo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Och Konung Cores fick ut Herrans hus kärile, som NebucadNezar utu Jerusalem tagit hade, och låtit lägga uti sins guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Och Konung Cores i Persien fick dem ut igenom Mithredath räntomästaren, och uträknade dem Sesbazar, Förstanom i Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Och detta är talet: tretio gyldene bäcken, och tusende silfverbäcken, nio och tjugu knifvar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Tretio gyldene skålar, och de andra silfskålar, fyrahundrad och tio, och annor kärile tusende;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Så att all kärilen både af guld och silfver voro femtusend och fyrahundrad. All dem förde Sesbazar upp, med dem som utu fängelset uppdrogo ifrå Babel till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Desse äro de barn utu landen, som uppdrogo utu fängelset, hvilka NebucadNezar, Konungen i Babel, hade fört till Babel, och igenkommo till Jerusalem och Juda, hvar och en uti sin stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Och kommo med Serubbabel: Jesua, Nehemia, Seraja, Reelaja, Mardechai, Bilsan, Mispar, Bigvai, Rehum, och Baana. Detta är nu talet af männerna i Israels folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Paros barn, tutusend hundrade två och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Sephatja barn, trehundrad två och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Arahs barn, sjuhundrad fem och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'PahathMoabs barn, utaf Jesua Joabs barnom, tutusend åttahundrad och tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Elams barn, tusende tuhundrad fyra och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Sattu barn, niohundrad fem och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Saccai barn, sjuhundrad och sextio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Bani barn, sexhundrad två och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Bebai barn, sexhundrad tre och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Asgads barn, tusende tuhundrad två och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikams barn, sexhundrad sex och sextio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Bigvai barn, tutusend sex och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Adins barn, fyrahundrad fyra och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Aters barn af Jehiskia, åtta och niotio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Bezai barn, trehundrad tre och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Jorahs barn, hundrade och tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Hasums barn, tuhundrad tre och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Gibbars barn, fem och niotio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'BethLehems barn, hundrade tre och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Netopha män, sex och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'De män af Anathoth, hundrade åtta och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Asmaveths barn, två och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'De barn af KiriathArim, Chephira, och Beeroth, sjuhundrad tre och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'De barn af Rama och Gaba, sexhundrad en och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'De män af Michmas, hundrade två och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'De män af BethEl och Aj, tuhundrad tre och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Nebo barn, två och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'De män af Magbis, hundrade sex och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'De andra Elams barn, tusende tuhundrad fyra och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Harims barn, trehundrad och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Lod, Hadid och Ono barn, sjuhundrad fem och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Jereho barn, trehundrad fem och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Senaa barn, tretusend sexhundrad och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Presterna: Jedaja barn, af Jesua huse, niohundrad tre och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Immers barn, tusende två och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pashurs barn, tusende tuhundrad sju och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Horims barn, tusende och sjutton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Leviterna: Jesua barn, och Kadmiel, af Hodavia barnom, fyra och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Sångarena: Assaphs barn, hundrade åtta och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Dörravaktarenas barn: Sallums barn, Aters barn, Talmons barn, Akkubs barn, Hatita barn, och Sobai barn; alle tillhopa hundrade nio och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'De Nethinim: Ziha barn, Hasupha barn, Thabaoths barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Keros barn, Siaha barn, Padons barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebana barn, Hagaba barn, Akkubs barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Hagabs barn, Samlai barn, Hanans barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Giddels barn, Gahars barn, Reaja barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Rezins barn, Nekoda barn, Gassams barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Ussa barn, Paseahs barn, Besai barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asna barn, Mennims barn, Nephusims barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbuks barn, Hakupha barn, Harhurs barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Bazluts barn, Mehida barn, Harsa barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkos barn, Sisera barn, Thamahs barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Neziahs barn, Hatipha barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Salomos tjenares barn: Sotai barn, Sopherets barn, Peruda barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jaala barn, Darkons barn, Giddels barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Sephatja barn, Hattils barn, Pochereths barn af Zebaim, Ami barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Alle Nethinim, och Salomos tjenares barn, voro tillhopa trehundrad två och niotio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Och desse drogo också med upp af ThelMelah, ThelHarsa, Cherub, Addan och Immer; men de kunde icke utvisa sina fäders hus, eller ock sina säd, om de voro af Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delaja barn, Tobia barn, Nekoda barn, sexhundrad två och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Och af Prestabarnen: Habaja barn, Koz barn, Barsillai barn, den en hustru tog utaf Barsillai den Gileaditens döttrar, och vardt nämnd under deras namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'De samme sökte efter deras börds skrifter, och funno dem intet; derföre vordo de Presterskapet qvitte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Och Thirsatha sade till dem, att de icke skulle äta utaf det aldrahelgasta, tilldess en Prest uppstode med Ljus och Fullkomlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Hela menigheten, såsom en man, var tu och fyratio tusend, trehundrad och sextio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Förutan deras tjenare och tjenarinnor, de voro sjutusend trehundrad sju och tretio; och hade tuhundrad sångare, och sångerskor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Sjuhundrad sex och tretio hästar, tuhundrad fem och fyratio mular;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Fyrahundrad fem och tretio camelar, och sextusend sjuhundrad och tjugu åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Och somlige utaf öfversta fäderna, när de kommo till Herrans hus i Jerusalem, vordo de friviljoge till Guds hus, att man skulle det sätta uppå sitt rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Och gåfvo, efter sina förmågo, till drätselen åt verket, ett och sextio tusend gylden, och fem tusend pund silfver, och hundrade Prestakjortlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Alltså satte sig Presterna och Leviterna, och somlige af folket, och sångarena och dörravaktarena, och de Nethinim, uti sina städer; och hele Israel i sina städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Och då sjunde månaden kom, och Israels barn nu voro i sina städer, kom folket tillhopa, såsom en man, till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Och Jesua, Jozadaks son, och hans bröder Presterna, och Serubbabel, Sealthiels son, och hans bröder stodo upp, och byggde Israels Guds altare, till att offra bränneoffer deruppå, såsom skrifvet står i Mose dens Guds mansens lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Och de satte altaret uppå sin fot; ty en förskräckelse var ibland dem, för folket i landen; och offrade Herranom bränneoffer deruppå om morgon och afton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Och de höllo löfhyddohögtid, såsom det skrifvet står, och gjorde bränneoffer hvar dag, efter det tal som det sig borde, hvar dagen sitt offer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Derefter ock de dageliga bränneoffer, och nymånadas, och alla Herrans högtidsdagars, som helgade voro, och all friviljog offer, som de Herranom friviljeliga gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'På första dagen i sjunde månadenom begynte de att göra Herranom bränneoffer; men grundvalen till Herrans tempel var ännu icke lagd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Men de gåfvo stenhuggarom och timbermannom penningar, och spis, och dryck, och oljo, dem i Zidon och Tyro, att de skulle låta komma cedreträ af Libanon till sjös intill Japho; efter Cores, Konungens af Persien, befallning till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Uti andro årena, sedan de kommo till Guds hus i Jerusalem, uti dem andra månadenom, begynte Serubbabel, Sealthiels son, och Jesua, Jozadaks son, och de andre af deras bröder, Prester och Leviter, och alle de som af fängelset komne voro till Jerusalem; och skickade Leviterna, allt ifrå tjugu år och derutöfver, att de skulle drifva verket på Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Och Jesua stod, med sina söner och bröder, och Kadmiel, med sina söner, och Juda barn, såsom en man, till att drifva arbetarena på Guds hus; nämliga Henadads barn, med deras barn, och deras bröder Leviterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Och då byggningsmännerna lade grundvalen på Herrans tempel, stodo Presterna klädde, med trummeter, och Leviterna, Assaphs barn, med cymbaler, till att lofva Herran, med Davids dikt, Israels Konungs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Och söngo emot hvarannan, med lof och tacksägelse Herranom, att han god är, och hans barmhertighet varar i evighet öfver Israel. Och allt folket upphof sin röst till Herrans lof, att grunden på Herrans hus lagd var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Men månge af de gamla Prester och Leviter, och öfverste fäder, som det förra huset sett hade i dess grundval, och detta hus var för deras ögon, greto med höga röst; dock upphöjde månge sina röst till glädje;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Så att folket icke kunde känna det glädjerop, för gråtropet i folkena; ty folket ropade högt, så att man hörde ropet långt ifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Då nu Juda och BenJamins motståndare hörde, att fängelsens barn byggde Herranom Israels Gud templet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Kommo de till Serubbabel, och till öfversta fäderna, och sade till dem: Vi vilje bygga med eder; förty vi söke edar Gud lika som I; och vi hafve offrat allt ifrå den tid EsarHaddon, Konungen i Assur, förde oss hitupp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Men Serubbabel och Jesua, och de andre öfverste fäder i Israel, svarade dem: Det betämmer sig icke, att vi och I bygge vår Guds hus; utan vi vilje allena bygga Herranom Israels Gud, såsom Cores, Konungen i Persien, budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Då hindrade folket i landena Juda folks hand, och afskräckte dem af byggningene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Och lejde rådgifvare emot dem, och förhindrade deras råd, så länge Cores, Konungen i Persien, lefde, intill Darios regemente, Konungens i Persien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Men då Ahasveros vardt Konung, uti hans rikes begynnelse, skrefvo de ett klagomål emot dem af Juda och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Och uti Arthahsasta tid skref Bislam, Mithredath, Tabeel, och de andre af deras Råd, till Arthahsasta, Konungen i Persien; och skriften i brefvet var på Syrisk skrifven, och vardt på Syrisk uttydd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rehum cancelleren och Simsai skrifvaren skrefvo detta bref emot Jerusalem till Konung Arthahsasta:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Vi Rehum canceller, och Simsai skrifvare, och andre i det Rådet; af Dina, af Apharsach, af Tharpelath, af Persien, af Arach, af Babel, af Susan, af Deha, och af Elam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'Och de andre folk, hvilken den store och högprisade Asnappar försändt hade, och satt uti Samarie städer, och andre på desso sidon älfven, och i Canaan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Och detta är brefvets lydelse, som de till Konung Arthahsasta sände: Dine tjenare, de män på desso sidona älfven, och Cheeneth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Kunnigt vare Konungenom, att de Judar, som ifrå dig hitupp till oss komne äro till Jerusalem, i den upproriska och onda staden, bygga honom upp, och göra hans murar, och låta uppgå dem af grunden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Så må nu Konungen veta, om denne stad uppbyggd varder, och murarna igen uppsatte, så varda de icke gifvande skatt, tull och årliga utskylder, och deras anslag varder kommandes Konungarna till skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Så, efter vi alle hafve varit med, och nederlagt templet, hafve vi icke länger kunnat se på Konungens föraktelse; derföre sände vi nu, och låtom det kungöra Konungenom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Att man låte söka i dina fäders Chrönicor; så skall du finna i samma Chrönicor, och förfara, att denne staden är upprorisk, och Konungom och landom skadelig, och kommer desslikes andra till affall af ålder; derföre staden ock förstörd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Ty gifve vi Konungenom till förstå, att, om denne stad uppbyggd varder, och dess murar uppsatte, så behåller du intet för dem på desso sidon älfven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Då sände Konungen ett svar till Rehum cancelleren, och Simsai skrifvaren, och de andra i deras Råd, som i Samarien bodde, och de andra på hinsidon älfvena: Frid och helso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Brefvet, som I till oss sändt hafven, är uppenbarliga läsit för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Och är af mig befaldt, att man söka skulle, och är funnet, att denne stad af ålder hafver kastat sig upp emot Konungar; och uppror och affall sker deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Hafva också mägtige Konungar varit i Jerusalem, som rådit hafva öfver allt det som hinsidon älfven är; så att dem hafver tull, skatt och årliga utskylder gifven varit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Så görer nu efter denna befallning: Förtager de samma män, att staden icke byggd varder, intilldess befallning af mig gifven varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Så ser nu till, att I härutinnan icke försummelige ären, att Konungenom ingen skada häraf sker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Då nu Konungens Arthahsasta bref läset vardt för Rehum och Simsai skrifvarenom, och deras Råd, drogo de straxt upp till Jerusalem till Judarna, och förhindrade dem med arm och välde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Då höll upp arbetet på Guds hus i Jerusalem, och blef tillbaka, allt intill det andra året Darios, Konungens i Persien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Och de Propheter Haggai och Zacharia, Iddo son, propheterade till Judarna, som i Juda och Jerusalem bodde, i Israels Guds Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Då stodo Serubbabel upp, Sealthiels son, och Jesua, Jozadaks son, och begynte till att bygga Guds hus i Jerusalem; och med dem Guds Propheter, som dem styrkte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'På den tiden kom till dem Thathnai, landshöfdingen på denna sidon älfven, och SetharBosnai, och deras Råd, och sade alltså till dem: Ho hafver befallt eder att bygga detta huset, och uppsätta dess murar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Då sade vi dem, huru männerna heto, som desso byggning för händer hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Men deras Guds öga kom uppå Judarnas äldsta, så att dem icke förtaget vardt, tilldess man måtte låta komma sakena till Darios, och en skrifvelse derom igenkomme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Och detta är brefvets innehållelse, som Thathnai, landshöfdingen på desso sidon älfven, och SetharBosnai, och deras Råd af Apharsach, som på desso sidona älfven voro, sände till Konung Darios.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Och de ord, som de till honom sände, lydde alltså: Konungenom Darios allan frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Konungenom vare vetterligit, att vi komme uti Judiska landet, till den stora Gudens hus, hvilket man bygger med allahanda stenar, och bjelkar lägger man i väggarna, och arbetet går fast fram i deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Men vi hafve frågat de äldsta, och sagt till dem alltså: Ho hafver befallt eder bygga detta hus, och uppsätta dess murar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Ock frågade vi, huru de heto, på det vi skulle det låta dig förstå, och vi hafve de mäns namn beskrifna, som deras öfverstar äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Men de gåfvo oss dessa ord för svar, och sade: Vi äre himmelens och jordenes Guds tjenare, och bygge det hus upp, som för mång år bygdt var, hvilket en stor Israels Konung byggt och uppsatt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Men då våre fäder förtörnade Gud af himmelen, gaf han dem uti NebucadNezars hand, Konungens i Babel, den Chaldeens; han slog detta hus ned, och förde bort folket till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Men i första årena Cores, Konungens i Babel, befallde samme Konung Cores att bygga detta Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Ty ock de gyldene och silfverkärile i Guds hus, som NebucadNezar utu templet i Jerusalem tagit hade, och fört uti det templet i Babel, dem tog Konung Cores utu templet i Babel, ock fick dem Sesbazar vid namn, den han för en landshöfdinga satte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Och sade till honom: Tag dessa kärilen; far bort, och för dem uti templet i Jerusalem, och låt uppbygga Guds hus i sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Då kom samme Sesbazar, och lade grundvalen till Guds hus i Jerusalem. Ifrå den tiden hafver man byggt, och är ännu icke fullkomnadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Om nu Konungenom täckes, så låte söka i Konungens skatthuse, som i Babel är, om det så befaldt är af Konung Cores, att bygga Guds hus i Jerusalem, och sände till oss Konungens mening härom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Då befallde Konung Darios, att man söka skulle i cancelliet, uti Konungens skatthus, som i Babel låg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Då fann man i Ahmeta, på det slottet som i Meden ligger, ena bok, och derutinnan var ett sådana ärende beskrifvet:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Uti första årena Konungs Cores befallde Konung Cores uppbygga Guds hus i Jerusalem, på det rum der man offrar, och grundval lägga, till sextio alnars höjd, till bredden ock sextio alnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Och tre väggar af allahanda stenar, och en vägg af trä; och kosten skall gifven varda utaf Konungshuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Dertill de Guds hus gyldene och silfvertyg, som NebucadNezar uti templet i Jerusalem tagit, och till Babel fört hade, skall man igengifva, så att de skola igenförde varda uti templet i Jerusalem, i sitt rum, i Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Så farer nu långt ifrå dem, du Thathnai, landshöfdinge hinsidon vid älfven, och SetharBosnai, och deras Råd af Apharsach, som hinsidon älfven ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Låter dem arbeta på Guds hus, så att Judarnas höfvitsman och deras äldsta måga bygga Guds hus på sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Är också af mig befaldt, hvad man de äldsta i Juda utfå skall, till att bygga Guds hus, nämliga att man skall fliteliga taga utaf Konungens drätsel, det är, af den ränto hinsidon älfven, och gifva männerna, och att man icke förhindrar dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Och om de behöfva kalfvar, lamb, eller bockar, till bränneoffer till himmelens Gud, hvete, salt, vin och oljo, efter Presternas sed i Jerusalem, skall man dem gifva dagliga hvad de behöfva; och att detta sker oförsummeliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Att de måga offra till en söt lukt Gudi i himmelen, och bedja för Konungens lif, och hans barnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Af mig är denna befallning gifven; och hvilken menniska denna orden förvänder, utaf hans hus skall man taga en bjelka, och resa honom upp, och hängan deruti, och hans hus skall skamliga förstördt varda för den gernings skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Och Gud, som hafver låtit sitt namn bo der, förstöre alla Konungar, och folk, som sina hand uträcka, till att förstöra och nederslå Guds hus i Jerusalem; jag Darios hafver detta befallt, att detta skall ock så alldeles fullföljdt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Då gjorde det Thathnai landshöfdingen hinsidon älfven, och SetharBosnai med deras Råd, till hvilka Konung Darios sändt hade, fliteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Och Judarnas äldste byggde, och det gick för handena, efter den Prophetens Haggai och Zacharia, Iddo sons, Prophetia. Och de byggde, och uppsatte, efter Israels Guds befallning, och efter Cores, Darios och Arthahsasta, Konungarnas i Persien, befallning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Och fullkomnade huset, intill tredje dagen i dem månadenom Adar, det var sjette året af Konung Darios rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Och Israels barn, Presterna, Leviterna, och de andre fängelsens barnen, höllo Guds hus vigning med glädje;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Och offrade i Guds hus vigning hundrade kalfvar, tuhundrad lamb, fyrahundrad bockar; och till syndoffer för hela Israel, tolf getabockar, efter slägternas tal i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Och de satte Presterna i deras ordning, och Leviterna i deras vakt, till att tjena Gudi, som i Jerusalem är; såsom skrifvet står i Mose bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Och fängelsens barn höllo Passah på fjortonde dagen i dem första månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Ty Presterna och Leviterna hade renat sig, så att de alle rene voro, såsom en man; och de slagtade Passah för all fängelsens barn, och för deras bröder Presterna, och för sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Och Israels barn, som af fängelsen voro igenkomne, och alle de som sig till dem afskiljt hade ifrå Hedningarnas orenhet i landena, till att söka Herran Israels Gud, åto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Och höllo osyrade bröds högtid i sju dagar med glädje; förty Herren hade gjort dem glada, och vändt Konungens hjerta af Assur till dem, så att deras händer styrkta vordo i verket på Guds hus, den Israels Gud är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Sedan detta skedt var i Arthahsasta rike, Konungens i Persien, kom ned af Babel Esra, Seraja son, Asaria sons, Hilkia sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Sallums sons, Zadoks sons, Ahitobs sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Amaria sons, Asaria sons, Merajoths sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Serahja sons, Ussi sons, Bukki sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Abisua sons, Pinehas sons, Eleazars sons, Aarons den öfversta Prestens sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Hvilken en skickelig Skriftlärder var i Mose lag, som Herren Israels Gud gifvit hade; och Konungen gaf honom allt det han begärade, efter Herrans Guds hand öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Och drogo någre upp af Israels barn, Prester, Leviter, sångare, dörravaktare, och Nethinim, till Jerusalem, i sjunde årena Konungens Arthahsasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Och de kommo till Jerusalem i femte månadenom, det är sjunde året Konungens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Förty på första dagen i första månadenom vardt han till råds att uppdraga ifrå Babel; och på första dagen i femte månadenom kom han till Jerusalem, efter Guds goda hand öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Ty Esra skickade sitt hjerta till att söka Herrans lag, och till att göra och lära i Israel bud och rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Och detta är brefvets innehåll, som Konung Arthahsasta gaf Esra Prestenom, dem Skriftlärda, hvilken en lärare var i Herrans ord, och hans bud öfver Israel:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Arthahsasta, Konung öfver alla Konungar, Esra Prestenom, dem Skriftlärda i Guds lag af himmelen, frid och helso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Af mig är befaldt, att alle de af Israels folk, som friviljoge äro i mitt rike, och Presterna, och Leviterna, till att fara till Jerusalem, att de måga fara med dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Utsände af Konungenom, och af de sju rådherrar, till att besöka Juda och Jerusalem, efter dins Guds lag, hvilken i dine hand är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'Och att du medtager silfver och guld, som Konungen och hans rådherrar friviljoge gifva Israels Gudi, hvilkens boning i Jerusalem är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Och allahanda silfver och guld, som du finna kan i hela Babels landskap, med det som folket och Presterna friviljoge gifva till Guds hus i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Allt detta tag, och köp fliteliga för de samma penningar kalfvar, lamb, bockar och spisoffer, och drickoffer, att man må offra uppå altaret vid edars Guds hus i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Dertill hvad dig och dina bröder täckes att göra af de penningar, som öfverblifva, det görer efter edars Guds vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Och de tyg, som dig antvardas, till ämbetet i dins Guds huse, öfverantvarda dem inför Gud i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Hvad sedan mer af nödene är till dins Guds hus, det du behöfver utgifva, det låt utgifva utu Konungens kammar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Jag, Konung Arthahsasta, hafver detta befallt räntomästaromen på hinsidon älfven, så att hvad Esra Presten, den Skriftlärde i Guds lag af himmelen, af eder äskar, att I det fliteliga gören;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Allt intill hundrade centener silfver, och intill hundrade corer hvete, och till hundrade bath vin, och till hundrade bath oljo, och salt utan mått;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Allt det der hörer till Guds lag af himmelen, att man det fliteliga låter komma till Guds hus af himmelen; att en vrede icke må komma öfver Konungens rike, och hans barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Och eder skall vetterligit vara, att I icke magt hafven att lägga någon utskuld, tull eller årliga ränto på någon Prest, Levit, sångare, dörravaktare, Nethinim, och tjenare i denna Guds huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Men du, Esra, efter dins Guds visdom, som i dine hand är, uppsätt domare och lagmän, som allt folket döma måga, som på hinsidon älfven är, alla de som veta dins Guds lag, alla de som icke veta dem, dem lär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Och alle de som icke med flit göra dins Guds lag, och Konungens lag, de skola straxt hafva sin dom för sina gernings skull, antingen till döds eller till landsflykt, eller till penningaplikt, eller till fängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Lofvad vare Herren våra fäders Gud, som sådant Konungenom ingifvit hafver, att han skulle bepryda Herrans hus i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'Och tillböjt sina barmhertighet till mig, för Konungenom, och hans rådherrar, och alla Konungens väldiga. Och jag vardt styrkt efter Herrans mins Guds hand öfver mig, och församlade de yppersta i Israels hus, att de med mig ditupp drogo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Desse äro hufvuden för deras fäder, som räknade vordo, och med mig uppdrogo ifrå Babel, i den tiden, då Konung Arthahsasta regerade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Af Pinehas barn: Gersom. Af Ithamars barn: Daniel. Af Davids barn: Hattus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Af Sechania barn, Paros barn: Zacharia, och med honom räknade hundrade och femtio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Af PahathMoabs barn: Eljoenai, Seraja son, och med honom tuhundrad män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Af Sechania barn: Jahasiels son, och med honom trehundrad män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Af Adins barn: Ebed, Jonathans son, och med honom femtio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Af Elams barn: Jesaia, Athalia son, och med honom sjutio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Af Sephatja barn: Sebadja, Michaels son, och med honom åttatio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Af Joabs barn: Obadja, Jehiels son, och med honom tuhundrad och aderton män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Af Selomiths barn: Josiphia son, och med honom hundrade och sextio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Af Bebai barn: Zacharia, Bebai son, och med honom åtta och tjugu män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Af Asgads barn: Johanan, Katans son, och med honom hundrade och tio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Af de sista Adonikams barn; och heto alltså: Eliphelet, Jehiel och Semaja, och med dem sextio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Af Bigvai barn: Uthai och Sabbud, och med dem sjutio män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Och jag församlade dem till älfvena, som kommer till Ahava; och blefvom der i tre dagar. Och då jag gaf akt uppå folket och Presterna, fann jag der inga Leviter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Då sände jag till Elieser, Ariel, Semaja, Elnathan, Jarib, Elnathan, Nathan, Zacharia och Mesullam, öfverstar; och Jojarib och Elnathan, lärare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Och sände dem ut till Iddo öfverstan, till Casiphja, att de skulle hemta oss tjenare uti vår Guds hus. Och jag gaf dem in hvad de tala skulle med Iddo och hans bröder, de Nethinim i Casiphja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Och de hade till oss, efter Guds goda hand öfver oss, en klok man utaf Maheli barn, Levi sons, Israels sons, Serebia, med hans söner och bröder, aderton;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Och Hasabia, och med honom Jesaia af Merari barn, med hans bröder och deras söner, tjugu;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Och af de Nethinim, hvilka David och Förstarna gåfvo till att tjena Leviterna, tuhundrad och tjugu, alle nämnde vid namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Och jag lät der vid älfvena, vid Ahava, utropa ena fasto, att vi skulle ödmjuka oss för vårom Gud, till att söka af honom en rättan väg för oss, och vår barn, och alla våra håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Ty jag skämdes bedas ledsagare och resenärar af Konungenom, att de skulle hjelpa oss för fienderna på vägenom; förty vi hade sagt Konungenom: Vår Guds hand är till det bästa öfver alla de honom söka; och hans starkhet och vrede öfver alla dem, som honom öfvergifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Alltså fastade vi, och sökte detta af vårom Gud, och han hörde oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Och jag afskiljde tolf af de öfversta Presterna, Serebia och Hasabia, och med dem tio deras bröder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Och vog dem till silfver, och guld, och tyg till häfoffer i vår Guds hus, hvilka Konungen, och hans rådherrar, och Förstar, och hele Israel, som för handene var, till häfoffer gifvit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Och vog dem till i deras hand sexhundrad och femtio centener silfver, och i silfvertyg hundrade centener, och i guld hundrade centener;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Tjugu gyldene skålar, de höllo tusende gylden, och tu god kostelig kopparkäril, klar såsom guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Och sade till dem: I ären helige Herranom; så äro ock kärilen helig; dertill det frigifna silfver och guld Herranom edra fäders Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Så vaker, och bevarer det, tilldess I vägen det inför öfversta Presterna, och Leviterna, och öfversta fäderna i Israel i Jerusalem, uti Herrans hus kistor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Då togo Presterna och Leviterna det vägna silfret, och guldet, och kärilen, att de skulle föra det till Jerusalem, till vår Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Alltså fore vi ifrån älfvene Ahava, på tolfte dagen i första månadenom, att vi skulle draga till Jerusalem; och vår Guds hand var öfver oss, och bevarade oss ifrå fiendernas hand och försåt på vägenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Och vi komme till Jerusalem, och blefvom der i tre dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'På fjerde dagenom vardt väget silfret och guldet, och kärilen uti vår Guds hus, under Meremoths hand, Uria sons Prestens, och med honom var Eleazar, Pinehas son; och med dem Josabath, Jesua son, och Noadja, Binnui son, de Leviter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Efter hvars tal och vigt; och vigten vardt på den tiden all beskrifven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Och fängelsens barn, som utu fängelset komne voro, offrade bränneoffer Israels Gudi, tolf stutar för hela Israel, sex och niotio vädrar, sju och sjutio lamb, tolf bockar till syndoffer; alltsammans till bränneoffer Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Och de antvardade Konungens befallning Konungens ämbetsmän och landshöfdingom på denne sidon älfven; och de upphöjde folket, och Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Då nu allt detta bestäldt var, gingo till mig de öfverste, och sade: Israels folk, och Presterna, och Leviterna, äro icke afskilde ifrå folken i landen, efter deras styggelse, som är de Cananeers, Hetheers, Phereseers, Jebuseers, Ammoniters, Moabiters, Egyptiers och Amoreers.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Förty de hafva tagit deras döttrar, och deras söner, och gjort den helga sädena menliga med folken i landen; och öfverstarnas och rådherrarnas hand var den första i denna missgerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Då jag detta hörde, ref jag min kläder och min kjortel sönder, och utryckte mitt hufvudhår och skägg, och satt ensam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Och sig församlade till mig alle de som Israels Guds ord fruktade, för deras öfverträdelse, som i fängelset varit hade; och jag satt ensam allt intill aftonoffret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Och vid aftonoffret stod jag upp af min jämmer, och ref min kläder och min kjortel sönder, och föll uppå min knä, och uträckte mina händer till Herran min Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Och sade: Min Gud, jag skämmes och blyges att upphäfva min ögon till dig, min Gud; ty vår missgerning är vuxen öfver vårt hufvud, och vår skuld är stor upp till himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Allt ifrå våra fäders tid hafve vi varit i stora skuld, allt intill denna dag; och för våra missgerningars skull äre vi, och våre Konungar och Prester, gifne i Konungarnas hand i landen, uti svärd, i fängelse, i rof, och i ansigtes blygd, såsom det går i denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Så är oss dock nu någon liten tid nåde af Herranom vårom Gud vederfaren, att ännu något af oss är qvart blifvet, att han skulle gifva oss en nagla i sitt helga rum, och att vår Gud skulle upplysa vår ögon, och gifva oss ännu ett litet lif i vår träldom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Förty vi äre trälar, och vår Gud hafver icke förlåtit oss, ändock vi trälar äre; och hafver böjt till oss barmhertighet för Konungarna i Persien, att de läto oss lefva, och upphöja vår Guds hus, och upprätta dess förstöring, och gifva oss en gård i Juda och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Nu, hvad skole vi säga, vår Gud, efter detta? Att vi din bud öfvergifvit hafve,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Som du genom dina tjenare Propheterna budit hafver, och sagt: Det land, som I uti kommen till att besitta det, är ett orent land, igenom folkens orenhet i landen, uti deras styggelse, med hvilken de hafva uppfyllt det med orenhet allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Så skolen I nu icke gifva edra döttrar deras söner, och deras döttrar skolen I icke taga edrom sönom, och söker icke deras frid eller välfärd i evig tid; på det I skolen blifva mägtige, och äta det goda i landena, och lefva det edrom barnom till arfs i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Och efter allt det som öfver oss kommet är för våra onda gerningars och stora synders skull, hafver du vår Gud öfversett med oss det vi illa gjort hafve, och hafver gifvit oss en förlossning, såsom det nu är för ögonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Men vi hafve vändt oss om, och låtit din bud fara, så att vi hafve befryndat oss med desso styggelsens folke; vill du då vred vara öfver oss, tilldess det allt ute är, så att intet qvart blifver, eller ingen förlossning mer är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Herre, Israels Gud, du äst rättfärdig, ty vi äre igenblefne och behållne, såsom det i denna dag för ögon är; si, vi äre för dig uti vår skuld; ty fördenskull kan man intet blifva ståndandes för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Då Esra så bad, bekände och gret, och låg inför Guds hus, församlade sig till honom utaf Israel en ganska stor menighet af män, qvinnor och barn; förty folket gret svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Och Sechania, Jehiels son, af Elams barn, svarade, och sade till Esra: Si, vi hafve förtagit oss emot vår Gud, att vi hafve tagit oss främmande hustrur utaf landsens folk; men här är ännu hopp derom i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Så låt oss nu göra ett förbund med vårom Gud, så att vi utdrifve alla hustrur, och dem som af dem födde äro, efter Herrans råd, och deras som frukta vår Guds bud, att man må göra efter lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Så statt nu upp; ty det hörer dig till: Vi vilje vara med dig; var vid en god tröst, och gör så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Då stod Esra upp, och tog en ed af de öfversta Presterna, och Leviterna, och hela Israel, att de skulle göra efter detta talet. Och de svoro det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Och Esra stod upp inför Guds hus, och gick in uti Johanans, Eljasibs sons, kammar. Och då han ditkom, åt han intet bröd, och drack intet vatten; förty han sörjde öfver deras öfverträdelse, som i fängelset varit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Och de läto utropa i Juda och Jerusalem, till all fängelsens barn, att de skulle församla sig till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Och hvilken som icke komme innan tre dagar, efter öfverstarnas och de äldstas råd, hans ägodelar skulle alla tillspillogifvas, och han afskiljas ifrå fångarnas menighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Då församlade sig alle Juda män och BenJamin till Jerusalem, innan tre dagar; det är, på tjugonde dagen i den nionde månadenom. Och allt folket satt uppå gatone inför Guds hus, och bäfvade för detta ärendes skull, och för regnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Och Esra Presten stod upp, och sade till dem: I hafven förtagit eder, i det att I hafven tagit främmande hustrur, på det I skullen ännu föröka Israels skuld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Så bekänner nu Herran edra fäders Gud, och görer det honom ljuft är, och skiljer eder ifrå landsens folk, och ifrå de främmande hustrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Då svarade hela menigheten, och sade med höga röst: Ske såsom du oss sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Men folket är mycket, och regnväder, och kan icke stå ute; så är det icke heller ens eller två dagars gerning; ty vi hafve sådana öfverträdelse mycken gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Låt oss beställa våra öfverstar i hela menighetene, att alle de i våra städer, som främmande hustrur tagit hafva, komma på bestämd tid; och de äldste i hvar staden, och deras domare med, tilldess vår Guds vrede må ifrån oss vänd varda i denna sakene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Då vordo beställde Jonathan, Asahels son, och Jahesia, Thikva son, öfver denna saken; och Mesullam, och Sabbethai Leviterna hulpo dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Och fängelsens barn gjorde alltså. Och Presten Esra, och de ypperste fäderne i deras fäders hus, och alle de nu nämnde äro, afskiljde sig, och satte sig på första dagen i tionde månadenom till att ransaka om detta ärendet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Och de uträttade det på alla de män, som främmande hustrur hade, på första dagen i första månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Och vordo funne ibland Presternas barn, som främmande hustrur tagit hade, nämliga ibland Jesua barn, Jozadaks sons, och hans bröder: Maaseja, Elieser, Jarib och Gedalia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Och de gåfvo deras hand deruppå, att de ville utdrifva hustrurna; och till deras skuldoffer offra en vädur för sina skuld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Ibland Immers barn: Hanani och Sebadia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Ibland Harims barn: Maaseja, Elia, Semaja, Jehiel och Ussia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Ibland Pashurs barn: Eljoenai, Maaseja, Ismael, Nethaneel, Josabad och Eleasa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Ibland Leviterna: Josabad, Simei och Kelaja, den är Kelita; Pethabja, Juda och Elieser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Ibland sångarena: Eljasib. Ibland dörravaktarena: Sallum, Telem och Uri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Utaf Israel: Ibland Paros barn: Ramia, Jissija, Malchija, Mijamin, Eleazar, Malchija och Benaja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Ibland Elams barn: Mattania, Zacharia, Jehiel, Abdi, Jeremoth och Elia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Ibland Sattu barn: Eljoenai, Eljasib, Mattania, Jeremoth, Sabad och Asisa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Ibland Bebai barn: Johanan, Hanania, Sabbai och Athlai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Ibland Bani barn: Mesullam, Malluch, Adaja, Jasub, Seal och Jeramoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Ibland PahathMoabs barn: Adna, Chelal, Benaja, Maaseja, Mattania, Bezaleel, Binnui och Manasse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Ibland Harims barn: Elieser, Jissija, Malchija, Semaja, Simeon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'BenJamin, Malluch och Semaria.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Ibland Hasums barn: Mattenai, Mattatta, Sabad, Elipheleth, Jeremai, Manasse och Simi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Ibland Bani barn: Maadai, Amram, Uel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedja, Cheluhu,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Banja, Meremoth, Eljasib,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattania, Mattenai, Jaasav,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani, Binnui, Simi,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemia, Nathan, Adaja,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Machnadbai, Sasai, Sarai,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asareel, Selemia, Semaria,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amaria och Joseph.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Ibland Nebo barn: Jegiel, Mattithia, Sabad, Sebina, Jaddai, Joel och Benaja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Desse hade alle tagit främmande hustrur; och voro somlige ibland de samma hustrur, som barn födt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Dessa äro Nehemia, Hachalja sons, ord. Det begaf sig uti dem månadenom Chislev, i tjugonde årena, att jag var i Susan på slottet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Då kom Hanani, en af mina bröder, med några män utaf Juda; och jag frågade dem, huru det gick med Judarna, som behållne och igenlefde voro af fängelset; och huru det tillgick i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Och de sade till mig: De igenlefde af fängelset äro der i landena uti stor vedermödo och försmädelse; murarna i Jerusalem äro nederbrutne, och dess portar uppbrände med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Då jag nu sådana ord hörde, satt jag och gret, och jämrade mig i några dagar, och fastade, och bad inför Gud af himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Och sade: Ack! Herre Gud af himmelen, du store och förskräckelige Gud, som håller förbund och barmhertighet dem som dig älska och hålla din bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Låt dock din öron höra härtill, och din ögon öppne vara, så att du hörer dins tjenares bön, som jag nu beder inför dig, både dag och natt, för dina tjenare Israels barn, och bekänner Israels barnas synd, som vi emot dig gjort hafve; och jag med mins faders hus hafvom också syndat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Vi äre vordne förderfvade, att vi icke hafve hållit din bud, befallningar och rätter, som du dinom tjenare Mose budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Men tänk dock uppå det ord, som du dinom tjenare Mose böd, och sade: Om I förtagen eder, så vill jag förströ eder ibland folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Men om I omvänden eder till mig, och hållen min bud, och gören dem; och om I än bortdrefne voren allt intill himmelens ända, så vill jag dock dädan församla eder, och skall låta eder komma till det rum, som jag utvalt hafver, till att mitt Namn der bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'De äro dock dine tjenare, och ditt folk, som du förlossat hafver, igenom dina stora kraft och mägtiga hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ack! Herre, låt din öron höra till din tjenares bön, och till dina tjenares bön, som begära frukta ditt Namn; och låt lyckosamliga tillgå i dag med dinom tjenare, och gif honom barmhertighet för denna mannenom. Ty jag var Konungens skänk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Uti den månaden Nisan, i tjugonde årena Konungs Arthahsasta, då vin stod för honom, tog jag vinet upp, och fick Konungenom; och jag var icke lustig för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Då sade Konungen till mig: Hvi ser du så illa ut? Du är ju icke krank? Det äret icke, utan du äst bedröfvad. Men jag fruktade mig svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Då sade jag till Konungen: Konungen lefve evinnerliga! Skulle jag icke se illa ut? Den staden, der mina fäders begrafningshus är, ligger öde, och dess portar äro med eld uppbrände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Då sade Konungen till mig: Hvad är då ditt begär? Då bad jag Gud af himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Och sade till Konungen: Om Konungenom så godt tyckte, och din tjenare funne nåd för dig, att du ville sända mig till Juda, till den staden, der mina fäder begrafne äro, att jag måtte uppbygga honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Och Konungen sade till mig, och Drottningen, som jemte honom satt: Huru lång kan din resa varda? Och när kan du komma igen? Och Konungenom föll i sinnet, att han skulle sända mig åstad. Och jag satte honom en bestämd tid före;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Och sade till Konungen: Om Konungenom så godt tycker, så gifve han mig bref till landshöfdingarna på hinsidon älfvena, att de ledsaga mig derigenom, tilldess jag kommer in i Juda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Och bref till Assaph, Konungens skogshöfvitsman, att han låter mig få trä till bjelkar åt portarna i palatset i husena, och till stadsmurarna, och till huset, der jag infara skall. Och Konungen gaf mig det, efter mins Guds goda hand öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Och då jag kom till landshöfdingarna på hinsidon älfvena, fick jag dem Konungens bref. Och Konungen sände med mig höfvitsmän och resenärar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Då nu Saneballat den Horoniten, och Tobia tjenaren, den Ammoniten, det hörde, förtröt det dem svårliga, att någor menniska kommen var, som något godt sökte för Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Och då jag kom till Jerusalem, och hade varit der i tre dagar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Stod jag om nattena upp, och någre få män med mig; ty jag sade det ingen menniska, hvad mig min Gud ingifvit hade till att göra med Jerusalem; och intet djur var med mig, utan det jag red uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Och jag red ut genom dalporten om nattena, och framom drakabrunnen, och åt dyngoportenom, och besåg Jerusalems murar, som sönder voro, och portarna, som med eld uppbrände voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Och gick öfver till brunnporten, och till Konungsdammen; och var intet rum, der djuret, som under mig var, uppå gå kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Så drog jag om nattena bort åt bäcken, och besåg murarna, och vände om, och kom igenom dalporten hem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Och öfverstarna visste icke hvart jag gick, eller hvad jag gjorde; förty jag hade ändå intet sagt Judarna, och Presterna, rådherrarna och öfverstarna, och dem androm, som uppå verket arbetade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Så sade jag dem nu: I sen den uselhet, som vi uti äre, att Jerusalem ligger öde, och dess portar äro med eld uppbrände; kommer, låter oss bygga murarna till Jerusalem, att vi icke länger skola vara till en försmädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Och jag lät dem förstå min Guds hand, den öfver mig god var; dertill Konungens ord, som han med mig talat hade. Och de sade: Så låt oss nu vara uppe. Och vi byggde, och deras händer voro tröste till godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Då nu Saneballat den Horoniten, och Tobia tjenaren, den Ammoniten, och Gesem den Araben, hörde det, begabbade de oss, och föraktade oss, och sade: Hvad är det I gören? Viljen I åter falla af ifrå Konungenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Då svarade jag dem, och sade: Gud af himmelen gifver oss lycko; ty vi hans tjenare hafve uppe varit, och byggom; men I hafven ingen del eller rätt, eller åminnelse i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Och Eljasib, öfverste Presten, stod upp med sina bröder Presterna, och byggde fåraporten; honom helgade de, och satte in hans dörrar; men de helgade honom allt intill det tornet Mea, nämliga allt intill det tornet Hananeel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Bredevid dem byggde de män af Jericho; och näst dem byggde Saccur, Imri son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Men fiskaporten byggde Senaa barn; honom täckte de, och satte in hans dörrar, lås och bommar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Näst dem byggde Meremoth, Uria son, Hakkoz sons; näst dem byggde Mesullam, Berechia son, Mesesabeels sons; näst dem byggde Zadok, Baana son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Näst dem byggde de af Thekoa; men deras väldige böjde icke sin hals till sins herras tjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Den gamla porten byggde Jojada, Paseahs son, och Mesullam, Besodeja son; honom täckte de, och satte in hans dörrar, och lås och bommar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Näst dem byggde Melatia af Gibeon, och Jadon af Merono, män af Gibeon och Mizpa, på landshöfdingans säte, på denna sidon älfven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Näst efter honom byggde Ussiel, Harhaja son, guldsmeden; näst honom byggde Hanania, apothekarens son, och de förstärkte Jerusalem allt intill de breda murar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Näst honom byggde Rephaja, Hurs son, öfversten öfver en half fjerding af Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Näst honom byggde Jedaja, Harumaphs son, tvärtöfver sitt hus; näst honom byggde Hattus, Hasabenja son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Men Malchija, Harims son, och Hasub, Pahath Moabs son, byggde ett annat stycke, och tornet med ugnarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Näst honom byggde Sallum, Halohes son, öfversten för en half fjerding i Jerusalem, han och hans döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Dalporten byggde Hanun och borgarena af Sanoah; de byggde honom, och satte in hans dörrar, och lås och bommar, och tusende alnar på murenom allt intill dyngoporten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Men dyngoporten byggde Malchija, Rechabs son, öfversten i vingårdsmännernas fjerding; han byggde honom, och satte in hans dörrar, lås och bommar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Brunnporten byggde Sallum, CholHose son, en öfverste för en fjerding i Mizpa; han byggde honom, och täckten, och satte in hans dörrar, lås och bommar; dertill ock murarna vid dammen Selah, vid Konungsörtagården, allt intill trapporna, som gå nederåt ifrå Davids stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Näst honom byggde Nehemia, Asbuks son, öfversten för den halfva fjerdingen i BethZur, allt intill gentemot Davids grafvar, och allt intill den dammen Asuja, och allt intill de väldigas hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Efter honom byggde de Leviter, Rehum, Bani son; bredevid honom byggde Hasabia, öfversten för halfva fjerdingen i Kegila, i hans fjerding.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Efter honom byggde deras bröder Bavai, Henadads son, öfversten för en half fjerding i Kegila.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Efter honom byggde Eser, Jesua son, öfversten i Mizpa, ett annat stycke, inåt harneskhushörnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Efter honom, uppå berget, byggde Baruch, Sabbi son, ett annat stycke, ifrå hörnet allt intill Eljasibs öfversta Prestens husdörr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Efter honom byggde Meremoth, Uria son, Hakkoz sons, ett annat stycke, ifrån Eljasibs husdörr, allt intill ändan af Eljasibs hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Efter honom byggde Presterna, de män af landsbygdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Efter dem byggde BenJamin och Hasub, tvärsöfver deras hus; efter dem byggde Asaria, Maaseja son, Anania sons, jemte sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Efter honom byggde Binnui, Henadads son, ett annat stycke, ifrån Asaria hus intill båget, och allt intill hörnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, Usai son, emot båget, och det höga tornet, som synes utaf Konungshuset, vid fångahusens gård; efter honom Pedaja, Paros son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Men de Nethinim bodde uti Ophel, allt intill vattuporten österut, der tornet ut synes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Efter dem byggde de af Thekoa ett annat stycke, tvärtemot det stora tornet, som ut synes, allt intill murarna Ophel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Men ifrå hästaporten byggde Presterna, hvardera emot sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Efter dem byggde Zadok, Immers son, emot sitt hus; efter honom byggde Semaja, Sechania son, den dörravaktaren, östantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Efter honom byggde Hanania, Selemia son, och Hanun, Zalaphs son, den sjette, ett annat stycke; efter honom byggde Mesullam, Berechia son, emot sin fatabur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Efter honom byggde Malchija guldsmedssonen, allt intill de Nethinims och krämares hus, emot rådsporten, och intill hörnsalen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Och emellan hörnsalen allt intill fåraporten byggde guldsmederna och krämarena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Då nu Saneballat hörde, att vi byggde murarna, vardt han vred, och förgrymmade sig svårliga; och han bespottade Judarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Och sade för sina bröder, och för de väldiga i Samarien: Hvad göra de vanmägtige Judar? Månn man så skola låta betämma dem? Månn de skola offra? Månn de skola en dag fullkomna det? Månn de göra stenarna lefvande af stofthopar, som förbrände äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Men Tobia den Ammoniten, som när honom var, sade: Låt bygga dem; när räfvarna löpa ditupp, skola de väl sönderrifva deras stenmurar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Hör, vår Gud, huru föraktade äre vi; vänd deras försmädelse in uppå deras hufvud, så att du gifver dem uti föraktelse i deras fängelses lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Öfverskyl icke deras missgerning, och bortskrapa icke deras synd för dig; förty de hafva rett byggningsmännerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Men vi byggde murarna, och fogde dem alla tillhopa intill halfva höjd; och folket fick hjerta till att arbeta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Då nu Saneballat och Tobia, och de Araber och Ammoniter, och Asdoditer hörde, att murarna i Jerusalem voro igenbyggde, och de hade begynt igentäppa det öppet var, vordo de ganska vrede;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Och gjorde alla ett förbund tillhopa, att de skulle komma och strida emot Jerusalem, och göra en villo derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Men vi bådom vår Gud, och satte vakt uppå dem dag och natt, emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Och Juda sade: Dragarenas magt är allt för svag, och gruset är för mycket; vi kunne icke bygga uppå murenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Men våre fiender tänkte: De skola icke få vetat, eller set, förr än vi komme midt i hopen uppå dem, och slå dem ihjäl, och förhindre arbetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Då nu Judarna, som när dem bodde, kommo, och sade oss det väl tio gånger, af all rum, der de omkring oss bodde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Då satte jag nedre utmed muren i grafvene folket, efter deras slägter, med deras svärd, spetsar och bågar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Och besåg det, och stod upp, och sade till rådherrarna, och öfverstarna, och till det andra folket: Frukter eder intet för dem; tänker uppå den stora förskräckeliga Herran, och strider för edra bröder, söner, döttrar, hustrur och hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Då nu våre fiender hörde, att vi hade fått vetat, gjorde Gud deras råd omintet; och vi vände oss åter alle till muren, hvar och en till sitt arbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Och det skedde sedan, att hälften af de unga män gjorde arbetet; den andre hälften höllo spetsar, sköldar, bågar, och pansar; och öfverstarne stodo bakför hela Juda hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'De som byggde på muren, och de som båro bördor ifrå dem som uppå ladde; med den ena handene gjorde de arbetet, och med den andra höllo de värjona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Och hvar och en af dem, som byggde, hade sitt svärd bundet vid sidona, och byggde så; och den som blåste med basunen, var när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Och jag sade till rådherrarna, och öfverstarna, och till det andra folket: Arbetet är stort och vidt, och vi äre förströdde på murenom, långt ifrå hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'På hvilket rum I nu hören blåsa i basunen, dit kommer till oss. Vår Gud varder för oss stridandes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Och vi vilje arbeta på verket; och hälften af dem höll spetsar, allt ifrå morgonrodnan intill stjernorna uppgingo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Ock sade jag på den tiden till folket: Hvar och en blifve med sinom dräng öfver natten i Jerusalem, att vi om nattena tage vara på vaktena, och om dagen på arbetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Men jag och mine bröder, och mine tjenare, och de män i vaktene efter mig, drogo intet vår kläder af, när någor i vattnet gick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Och sig upphof ett stort rop af folket, och deras hustrur, emot sina bröder Judarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Och voro somlige, som sade: Våre söner och döttrar äro allt för månge; låt oss taga säd, och äta, att vi måge lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Och somlige sade: Låt oss utsätta våra åkrar, vingårdar och hus, och taga säd i denna hårda tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Somlige sade: Låt oss låna penningar på ränto till Konungen, på våra åkrar och vingårdar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Ty våra bröders kropp är såsom vår kropp, och deras barn såsom vår barn; eljest gifve vi våra söner och döttrar i träldom, och äre allaredo våra döttrar somliga undergifna, och ingen magt är i våra händer; komma också våra åkrar och vingårdar androm tillhanda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Då jag nu deras rop och dessa orden hörde, vardt jag ganska vred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Och mitt hjerta fick till råds, att jag straffade rådherrarna och öfverstarna, och sade till dem: Viljen I drifva ocker, den ene på den andra? Och jag hade tillhopa emot dem en stor församling;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Och sade till dem: Vi hafve igenköpt våra bröder Judarna, som Hedningomen sålde voro, efter våra förmågo; och I viljen också sälja edra bröder, de vi till oss köpt hafve? Då tego de, och funno intet till att svara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Och jag sade: Det är icke godt, som I gören. Skullen I icke vandra i Gudsfruktan, för Hedningarnas försmädelses skull, våra fiendars?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Jag och mine bröder, och mine tjenare, hafvom ock fått dem penningar och säd; men ockret vilje vi låta blifva tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Så får dem nu i denna dag igen sina åkrar, vingårdar, oljogårdar och hus, och hundradedelen af penningomen för säd, vin och oljo, som I på dem ockrat hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Då sade de: Vi vilje få dem det igen, och vilje intet äska af dem; och vilje göra såsom du sagt hafver. Och jag kallade Presterna, och tog en ed af dem, att de så göra skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Och jag skuddade mitt sköte ut, och sade: Så skudde Gud hvar och en af sitt hus, och ifrå hans arbete, den icke blifver vid detta ord, så att han blifve utskuddad och blottad. Och hela församlingen sade Amen; och lofvade Herran. Och folket gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Desslikes, ifrå den tiden, då mig vardt befaldt att vara landshöfding i Juda land, nämliga ifrå tjugonde årena, allt intill annat och tretionde året Konungs Arthahsasta, det är i tolf år, höll jag mig och mina bröder intet af höfdingakoste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Förty de förre landshöfdingar, som för mig varit hade, hade besvärat folket, och hade tagit af dem bröd och vin, och dertill fyratio siklar silfver, och deras tjenare hade haft sig väldeliga med folket; men jag gjorde icke så, för Gudsfruktans skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Arbetade jag ock på murarbetet, och köpte ingen åker; och alle mine tjenare måste der komma samman till arbetes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Dertill voro ock af Judarna och Förstarna hundrade och femtio vid mitt bord, som till mig komne voro ifrå Hedningarna, som kringom oss äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Och man måste beställa mig om dagen en oxa, och sex utvald får, och foglar, och ju i tio dagar allahanda vin tillfyllest. Likväl äskade jag intet höfdingakosten; förty tungen var svår på folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Min Gud, betänk mig till godo allt det jag desso folkena gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Då Saneballat, Tobia och Gesem den Araben, och andre våre fiender förnummo, att jag murarna byggt hade, och intet gap var mer deruppå; ändock jag ändå på den tiden icke upphängt hade dörrarna i portomen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Sände Saneballat och Gesem till mig, och läto säga mig: Kom, och låt oss komma tillsammans på bygdene, på slättene vid den staden Ono. Och de aktade göra mig ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Men jag sände båd till dem, och lät säga dem; Jag hafver ett stort verk till att uträtta, jag kan icke komma neder; det måtte försummadt blifva, om jag tager handena af, och far neder till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'De sände väl fyra gånger till mig vid samma sinnet; och jag svarade dem allt vid samma sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Då sände Saneballat femte gången sin tjenare till mig, med ett öppet bref i hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Derutinnan var skrifvet: Det är kommet för Hedningarna, och Gesem hafver det sagt, att du och Judarna viljen affalla; derföre uppbygger du murarna, och du vill vara deras Konung i denna sakene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Och du hafver beställt dig Propheter, som om dig skola utropa i Jerusalem, och säga: Han är Juda Konung. Sådant kommer för Konungen. Så kom nu, låt oss rådslå med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Men jag sände till honom, och lät säga honom: Detta är icke skedt, som du säger, du hafver diktat det af ditt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Ty de ville alle rädda oss, och mente: De varda aflåtande af arbetet, och varda stille. Men jag förstärkte mina hand desto mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Och jag kom uti Semaja hus, Delaja sons, Mehetabeels sons, och han hade innelyckt sig; och sade: Låt oss komma tillhopa i Guds hus, midt i templet, och sluta dörrarna till af templet; förty de varda kommande till att dräpa dig, och komma om nattena, att de skola slå dig ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Men jag sade: Skulle en sådana man fly? Skulle en sådana man, som jag är, gå uti templet, på det han skall blifva lefvandes? Jag vill icke gå derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Ty jag förmärkte, att Gud hade intet sändt honom. Han spådde väl sådant om mig; men Tobia och Saneballat hade gifvit honom penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Derföre tog han penningar, på det jag skulle taga en fruktan till mig, och göra så, och synda; och de skulle hafva ett ondt rop uppå mig, dermed de måtte förlasta mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Tänk, min Gud, på Tobia och Saneballat, efter dessa deras gerningar, och på Propheten Noadja, och de andra Propheterna, som mig afskräcka ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Och muren vardt redo på femte och tjugonde dagen af den månaden Elul, i två och femtio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Och då alle våre fiender det hörde, fruktade sig alle Hedningar, som omkring oss voro, och deras mod förföll dem; förty de märkte, att detta verk var af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Voro ock på den tiden månge af Juda öfverstar, hvilkas bref gingo till Tobia; och ifrå Tobia till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Ty de voro månge i Juda, som honom besvorne voro; förty han var Sechania svåger, Arahs sons; och hans son Johanan hade Mesullams dotter, Berechia sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Och de talade godt om honom för mig, och förde mitt tal ut för honom. Så sände nu Tobia bref till att afskräcka mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Då vi nu hade byggt murarna, hängde jag portarna före, och vordo beställde porthållare, sångare och Leviter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Och jag böd min broder Hanani, och Hanania palatsfogdanom i Jerusalem; ty han var en trofast man, och gudfruktig för många andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Och sade till dem: Man skall icke upplåta portarna i Jerusalem, tilldess solen varder varm; och medan man ännu arbetar, skall man slå portarna till, och bommen före. Och vaktare vordo beställde utaf borgarena i Jerusalem, hvar och en på sine vakt, och om sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Och staden var vid till rum, och stor; men folket litet derinne, och husen voro icke uppbyggd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Och min Gud gaf mig i hjertat, att jag församlade rådherrarna och öfverstarna, och folket, till att räkna dem; och jag fann ett register på mantalet, deras som tillförene uppkomne voro, och fann deruti så skrifvet:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Desse äro landsens barn, som uppkomne voro utaf fängelset, af dem som NebucadNezar, Konungen i Babel, hade bortfört, och i Jerusalem bodde, och i Juda, hvar och en i sin stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Och voro komne med Serubbabel: Jesua, Nehemia, Asaria, Raamja, Nahamani, Mordechai, Bilsan, Misperet, Bigvai, Nehum och Baana. Detta är talet af männerna af Israels folk:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Paros barn voro tutusend hundrade två och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Sephatja barn, trehundrad två och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Arahs barn, sexhundrad två och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'PahathMoabs barn, ibland Jesua och Joabs barn, tutusend åttahundrad och aderton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Elams barn, tusende tuhundrad fyra och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Sattu barn, åttahundrad fem och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Saccai barn, sjuhundrad och sextio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binnui barn, sexhundrad åtta och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Bebai barn, sexhundrad åtta och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Asgads barn, tutusend trehundrad två och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adonikams barn, sexhundrad sju och sextio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvai barn, tutusend sju och sextio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Adins barn, sexhundrad fem och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Aters barn af Hiskia, åtta och niotio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Hasums barn, trehundrad åtta och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Bezai barn, trehundrad fyra och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Hariphs barn, hundrade och tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Gibeons barn, fem och niotio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'De män af BethLehem och Nethopha, hundrade åtta och åttatio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'De män af Anathot, hundrade åtta och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'De män af BethAsmaveth, två och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'De män af KiriathJearim, Chephira och Beeroth, sjuhundrad tre och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'De män af Rama och Gaba, sexhundrad en och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'De män af Michmas, hundrade två och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'De män af BethEl och Aj, hundrade tre och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'De män af Nebo dess andras, två och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Dens andras Elams barn, tusende tuhundrad fyra och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Harims barn, trehundrad och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Jerecho barn, trehundrad fem och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Lod, Hadid, och Ono barn, sjuhundrad en och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Senaa barn, tretusend niohundrad och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Presterna: Jedaja barn, af Jesua hus, niohundrad tre och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Immers barn, tusende två och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pashurs barn, tusende tuhundrad sju och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Harims barn, tusende och sjutton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Leviterna: Jesua barn, af Kadmiel, ibland Hodeva barn, fyra och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Sångarena: Assaphs barn, hundrade åtta och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Dörravaktarena: Sallums barn, Aters barn, Talmons barn, Akkubs barn, Hatita barn, Sobai barn; alle tillhopa hundrade åtta och tretio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'De Nethinim: Ziha barn, Hasupha barn, Tabaoths barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Keros barn, Sia barn, Padons barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Lebana barn, Hagaba barn, Salmai barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Hanans barn, Giddels barn, Gahars barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reaja barn, Rezins barn, Nekoda barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gassams barn, Ussa barn, Paseahs barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Besai barn, Meunims barn, Nephisesims barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbuks barn, Hakupha barn, Harhurs barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Bazliths barn, Mehida barn, Harsa barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkos barn, Sisera barn, Thamahs barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Neziahs barn, Hathipha barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Salomos tjenares barn: Sotai barn, Sophereths barn, Perida barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Jaala barn, Darkons barn, Giddels barn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Sephatja barn, Hattils barn, Pocherets barn af Zebaim, Amons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Alle de Nethinim, och Salomos tjenares barn, voro trehundrad två och niotio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Desse drogo också med upp, af ThelMelah, ThelHarsa, Cherub, Addon och Immer; men de kunde icke bevisa deras fäders hus, eller deras säd, om de voro af Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delaja barn, Tobia barn, Nekoda barn, voro sexhundrad två och fyratio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Och af Presterna: Habaja barn, Hakkoz barn, Barsillai barn, hvilken hustru tog af Barsillai den Gileaditens döttrar, och vardt efter deras namn nämnd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Desse sökte deras börds register; och då de icke funno det, vordo de qvitte vid Presterskapet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Och Thirsatha sade till dem, att de icke skulle äta utaf det aldrahelgaste, intilldess en Prest uppkomme med Ljus och Fullkomlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Hela menigheten, såsom en man, var tu och fyratio tusend trehundrad och sextio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Undantagne deras tjenare och tjenarinnor, de voro sjutusend trehundrad sju och tretio; och de hade tuhundrad fem och fyratio sångare och sångerskor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Sjuhundrad sex och tretio hästar; tuhundrad fem och fyratio mular;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Fyrahundrad fem och tretio camelar; sextusend sjuhundrad och tjugu åsnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Och somlige af öfversta fäderna gåfvo till verket: Thirsatha gaf till drätselen tusende gylden, och femtio bäcken, femhundrad och tretio Prestakjortlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Och somlige af de öfversta fäder gåfvo i drätselen till verket tjugutusend gylden, tutusend och tuhundrad pund silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Och det andra folket gaf tjugutusend gylden, och tutusend pund silfver, och sju och sextio Prestakjortlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Och Presterna, och Leviterna, och dörravaktarena, sångare, och somlige af folket, och de Nethinim, och hele Israel, satte sig uti sina städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Då nu sjunde månaden kom, och Israels barn voro i sina städer, församlade sig allt folket, såsom en man, på breda gatone inför vattuporten, och sade till Esra den skriftlärda, att han skulle hemta fram Mose lagbok, som Herren Israel budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Och Esra Presten hemtade fram lagen inför menighetena, både män och qvinnor, och för alla dem som det förstå kunde, på första dagen i sjunde månadenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Och las deruti, på breda gatone, som för vattuporten är, allt ifrå morgonlysningen intill middag, för män och qvinnor, och för dem som det förstå kunde; och hela folkens öron voro vänd till lagbokena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Och Esra den Skriftlärde stod uppå en hög trästol, den de till predikan gjort hade; och när honom stodo Mattithia, Sema, Anaja, Uria, Hilkia och Maaseja, på hans högra sido; och på hans venstra Pedaja, Misael, Malchija, Hasum, Hasbadana, Zacharia och Mesullam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Och Esra lät upp bokena för hela folket; förty han stod högt öfver allt folket; och då han upplät henne, stod allt folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Och Esra lofvade Herran den stora Guden; och allt folket svarade: Amen, Amen, med uppräckta händer; och bugade sig, och tillbådo Herran med ansigtet ned på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Och Jesua, Bani, Serebia, Jamin, Akkub, Sabbethai, Hodija, Maaseja, Kelita, Asaria, Josabad, Hanan, Pelaja, och Leviterna, beställde att folket gaf akt uppå lagen; och folket stod uppå sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Och de läste uti Guds lagbok klarliga och förståndeliga, så att man förstod, då läset vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Och Nehemia, hvilken är Thirsatha, och Esra Presten, den Skriftlärde, och Leviterna, som folket höllo till att akta på, sade till allt folket: Denne dagen är helig Herranom edrom Gud; derföre sörjer intet, och gråter icke; ty allt folket gret, då de hörde lagsens ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Derföre sade han till dem: Går bort, och äter det feta, och dricker det söta, och sänder dem ock delar, som intet för sig tillredt hafva; förty denne dagen är helig vårom Herra. Derföre bekymrer eder icke; ty fröjd i Herranom är edor starkhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Och Leviterna stillade allt folket, och sade: Varer tyste, ty dagen är helig; bekymrens intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Och allt folket gick bort till att äta, dricka och del sända, och gjorde sig en stor glädje; förty de hade förståndit orden, som man dem förkunnat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'På annan dagen församlade sig öfversta fäderna ibland allt folket, och Presterna, och Leviterna, till Esra den Skriftlärda, att han skulle undervisa dem i lagsens ordom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Och de funno beskrifvet i lagen, att Herren genom Mose budit hade, att Israels barn skulle bo i löfhyddor, på den högtidene i sjunde månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Och de läto det varda kunnigt, och utropadt i alla deras städer, och i Jerusalem, och sade: Går ut uppå berget, och hemter oljoqvistar, balsamqvistar, myrthenqvistar, palmqvistar och qvistar af tjockqvistadt trä, att man må göra löfhyddor, såsom skrifvet står.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Och folket gick ut, och hemtade, och gjorde sig löfhyddor, hvar uppå sitt tak, och i sina gårdar, och i Guds hus gårdar; och uppå den breda gatone vid vattuporten, och uppå den breda gatone vid Ephraims port.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Och hela menigheten af dem, som af fängelset igenkomne voro, gjorde löfhyddor, och bodde deruti; ty Israels barn hade ifrå Josua, Nuns sons, tid, allt intill denna dag, intet så gjort; och var en ganska stor glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Och vardt hvar dag läset i Guds lagbok, ifrå första dagen allt intill den yttersta; och de höllo den högtiden i sju dagar; och på åttonde dagen församlingenes dag, såsom det borde sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'På fjerde och tjugonde dagen i denna månadenom kommo Israels barn tillsammans med fasto, och säcker, och mull uppå dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Och afskiljde Israels säd ifrån all främmande barn, och gingo fram, och bekände sina synder och sina fäders missgerning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Och stodo upp i sin rum; och man las i Herrans deras Guds lagbok, fyra gånger om dagen; och de bekände och tillbådo Herran sin Gud, fyra gånger om dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Och Leviterna stodo upp i höjdene; nämliga Jesua, Bani, Kadmiel, Sebanja, Bunni, Serebia, Bani och Chenani, och ropade högt till Herran deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Och Leviterna, Jesua, Kadmiel, Bani, Hasabnia, Serebia, Hodija, Sebanja, Pethahja, sade: Står upp, och lofver Herran edar Gud ifrån evighet till evighet; och man lofve dins härlighets Namn, hvilken upphöjd är med all välsignelse och lof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Herre, du äret allena; du hafver gjort himmelen och alla himlars himlar, med all deras här, jordena och allt det deruppå är, hafvet och allt det derinne är; du gör allt lefvande, och den himmelske hären tillbeder dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Du äst Herren Gud, som Abram utvalde, och förde honom ut ifrån Ur i Chaldeen, och nämnde honom Abraham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Och du fann hans hjerta trofast för dig, och gjorde ett förbund med honom, till att gifva hans säd de Cananeers, Hetheers, Amoreers, Phereseers, Jebuseers och Girgaseers land; och du hafver hållit din ord; ty du äst rättfärdig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Och du hafver sett till våra fäders jämmer i Egypten, och hört deras rop vid röda hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Och gjort tecken och under på Pharao, och alla hans tjenare, och på allt folket i hans land; ty du förnam, att de voro stolte emot dem; och hafver gjort dig ett Namn, såsom det i denna dag för ögon är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Och hafver åtskiljt hafvet för dem, så att de gingo torre midt igenom hafvet; och kastat deras förföljare i djupet, såsom stenar i mägtig vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Och fört dem om dagen uti en molnstod, och om nattena uti en eldstod, till att lysa dem på vägen, den de drogo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Och hafver nederstigit uppå berget Sinai, och talat med dem af himmelen, och gifvit dem rättvisa rätter, och trofast lag, god bud och seder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Och kungjort dem din helga Sabbath; och budit dem bud, seder och lag, genom din tjenare Mose;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Och gifvit dem bröd af himmelen, då de hungrade, och låtit gå vatten utaf bergklippone, då dem törste; och sagt dem, att de skulle gå in, och taga in landet, der du dina hand öfver upplyft hade, att du skulle det gifva dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Men våre fäder vordo stolte och halsstyfve, så att de icke lydde din bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Och ville icke höra dem, och tänkte intet uppå din under, som du med dem gjort hade; utan vordo halsstyfve, och uppkastade en höfvitsman, att de skulle vända sig till sin träldom i sine olydno; men du, (min) Gud, gaf dem till, och var dem nådelig, barmhertig, tålig, och af en stor barmhertighet, och öfvergaf dem icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Och ändock de gjorde en gjuten kalf, och sade: Det är din Gud, som dig utur Egypti land fört hafver; och gjorde stor försmädelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Likväl öfvergaf du dem icke i öknene, efter din stora barmhertighet; och molnstoden vek icke ifrå dem om dagen, att ledsaga dem på vägen; ej heller eldstoden om nattena, till att lysa dem på vägen, den de drogo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Och du gafst din goda Anda, till att undervisa dem; och ditt Man vände du icke ifrå deras mun, och gaf dem vatten, när dem törste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'I fyratio år besörjde du dem i öknene, så att dem intet fattades; deras kläder föråldrades intet, och deras fötter svullnade intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Och gaf dem rike och folk, och fördelade dem här och der, så att de intogo Sihons land, Konungens i Hesbon, och Ogs land, Konungens i Basan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Ock förökade du deras barn, såsom stjernorna på himmelen, och lät komma dem i landet, det du deras fäder tillsagt hade, att de skulle draga derin, och intaga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Och barnen kommo derin, och togo landet in; och du undertryckte för dem landsens inbyggare, de Cananeer, och gafst dem uti deras händer, och deras Konungar, och folken i landena, så att de gjorde med dem efter sin vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Och de vunno fasta städer, och ett fett land, och intogo hus full med allahanda ägodelar, uthuggna brunnar, vingårdar, oljogårdar och trä, der man af äter, väl mång. Och de åto och vordo mätte och fete, och lefde i vällust af dine stora godhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Men de vordo olydige, och vordo dig genstörtige, och kastade din lag tillrygga bakom sig, och slogo ihjäl dina Propheter, som dem betygade att de skulle omvända sig till dig; och gjorde stor försmädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Derföre gafst du dem uti deras fiendars hand, hvilke dem betvingade; och uti deras ångests tid ropade de till dig; och du hörde dem af himmelen, och genom dina stora barmhertighet gafst du dem frälsare, som dem hulpo utu deras fiendars hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'När de nu till rolighet kommo, vände de om igen, till att göra det ondt var för dig; så öfvergaf du dem uti deras fiendars hand, att de skulle råda öfver dem. Så omvände de sig då, och ropade till dig; och du hörde dem af himmelen, och halp dem efter dina stora barmhertighet i flera resor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Och du lät betyga dem, att de skulle omvända sig till din lag; men de voro stolte, och lydde intet din bud, och syndade emot dina rätter; hvilka om en menniska gör, lefver hon derutinnan; och vände sina skuldror bort, och vordo halsstyfve, och lydde intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Och du fördröjde i mång år med dem, och lät betyga dem genom din Anda i dina Propheter; men de skötte der intet om, derföre hafver du gifvit dem i folks hand i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Dock, af dine stora barmhertighet, hafver du icke platt gjort ända på dem, eller öfvergifvit dem; förty du äst en nådelig och barmhertig Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Nu, vår Gud, du store Gud, mägtige och förskräckelige, du som håller förbund och barmhertighet; akta icke ringa all den vedermöda, som på oss drabbat hafver, och på våra Konungar, Förstar, Prester, Propheter, fäder, och allt ditt folk, ifrå Konungarnas tid i Assur, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Du äst rättvis i allt det du hafver låtit komma öfver oss; ty du hafver gjort rätt, men vi hafve varit ogudaktige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Och våre Konungar, Förstar, Prester och fäder, hafva icke gjort efter din lag, och intet aktat på din bud och vittnesbörd, som du hafver låtit betyga dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Och de hafva icke tjent dig i sitt rike, och i dina stora ägodelar, som du dem gifvit hafver, och uti det vida och feta landet, som du dem infått hafver, och hafva icke omvändt sig ifrå sitt onda väsende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Si, vi äre i denna dag trälar, och i de lande, som du våra fäder gafst, till att äta dess frukt och goda, si, der äre vi trälar uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Och dess årsväxt förökar sig Konungomen, som du öfver oss satt hafver för våra synders skull; och de råda öfver våra kroppar och vår boskap, efter sin vilja; och vi äre i stor nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Och i allt detta göre vi nu ett fast förbund, och skrifvom, och låte våra Förstar, Leviter och Prester besegla det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Men de som beseglade det, voro desse: Nehemia Thirsatha, Hachalia son, och Zedekia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraja, Asaria, Jeremia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pashur, Amaria, Malchija,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebanja, Malluch,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Meremoth, Obadja,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginnethon, Baruch,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullam, Abia, Mijamin,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maasia, Bilgai, och Semaja: De voro Presterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Men Leviterna voro: Jesua, Asanja son, Binnui af Henadads barnom, Kadmiel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Och deras bröder, Sebanja, Hodija, Kelita, Pelaja, Hanan,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Micha, Rehop, Hasabia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Saccur, Serebia, Sebanja,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodija, Bani och Beninu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hufvuden i folken voro: Paros, PahathMoab, Elam, Sattu, Bani,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Asgad, Bebai,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonia, Bigvai, Adin,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Hiskia, Assur,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodija, Hasum, Bezai,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hariph, Anathoth, Nebai,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesullam, Hesir,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesesabeel, Zadok, Jaddua,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatja, Hanan, Anaja,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hosea, Hanania, Hasub,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hallohes, Pilha, Sobek,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabna, Maaseja,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Ahija, Hanan, Anan,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluch, Harim och Baana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Och det andra folket, Presterna, Leviterna, dörravaktarena, sångarena, Nethinim, och alle de som hade söndrat sig ifrå folken i landen, intill Guds lag, med sina hustrur, söner och döttrar, alle de som det kunde förstå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Och deras mägtige, togo sig det till för sina bröder, och de kommo till att svärja och förpligta sig med ed, till att vandra i Guds lag, som igenom Guds tjenare Mose gifven är, att de hålla och göra ville efter all Herrans vår Guds bud, rätter och seder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Och att vi icke skulle gifva folken i landena våra döttrar; ej heller vårom sönom taga deras döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Desslikes, när folket i landet förer om Sabbathsdagen någon varo och allahanda spisning, till att sälja, att vi icke ville taga det af dem om Sabbathen och helgedagar; och att vi i sjunde årena ville göra förlösning på allahanda tunga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Och lägga ett bud uppå oss, att vi årliga gifva skulle en tridiung af en sikel silfver, till tjensten i vår Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Nämliga till skådobröd, till dagligit spisoffer, till dagligit bränneoffer, på Sabbaths, nymånads och högtidsdagom, och till det helgada, och till syndoffer, der Israel skulle med försonad varda, och till all verk i vår Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Och vi kastade lott emellan Presterna, Leviterna och folket, om vedoffer, det man till vår Guds hus årliga framföra skulle, efter våra fäders hus, på bestämd tid, att bränna på Herrans vår Guds altare, såsom det i lagen skrifvet är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Och till att årliga frambära förstlingen af vårt land, och förstlingen af allo frukt, af all trä till Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Och förstlingen af våra söner, och af vår boskap, såsom det i lagen skrifvet står; och förstlingen af vårt fä, och af vår får, att vi allt detta skulle hafva in uti vår Guds hus till Presterna, som i vår Guds hus tjena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Och att vi ville frambära förstlingen af vår deg, och vårt häfoffer, och frukt af allahanda trä, vin och oljo, till Presterna, i kistorna vid vår Guds hus; och vårt lands tiond till Leviterna, så att Leviterna skulle hafva tionden i alla städer, der vårt åkerverk är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Och Presten Aarons son skall ock del hafva af Leviternas tiond, med Leviterna; så att Leviterna skola bära tionden af sine tiond upp till vår Guds hus, i kistorna, uti skatthuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Ty Israels barn, och Levi barn, skola bära häfoffret af säd, vin och oljo, upp i kistorna. Dersammastäds äro helgedomens kärile, och Presterna, som der tjena, och dörravaktare, och sångare; att vi vår Guds hus icke öfvergifve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Och öfverstarna för folket bodde i Jerusalem; men det andra folket kastade lott derom, att af tio skulle en del draga till Jerusalem, den helga staden, till att bo der, och nio delar i städerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Och folket välsignade alla de män, som friviljoge voro till att bo i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Desse äro hufvuden i landskapen, de som i Jerusalem bodde; men i Juda städer bodde hvar och en på sina ägor, som i deras städer voro; nämliga Israel, Presterna, Leviterna, Nethinim och Salomos tjenares barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Och i Jerusalem bodde någre af Juda barn, och BenJamin. Af Juda barn: Athaja, Ussia son, Zacharia sons, Amaria sons, Sephatja sons, Mahalaleels sons, af Parez barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Och Maaseja, Baruchs son. CholHose sons, Hasaja sons, Adaja sons, Jojaribs sons, Zacharia sons, Siloni sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'All Parez barn, som i Jerusalem bodde, voro fyrahundrad åtta och sextio dugelige män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Desse äro BenJamins barn: Sallu, Mesullams son, Joeds sons, Pedaja sons, Kolaja sons, Maasesa sons, Ithiels sons, Jesaja sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'Och efter honom Gabbai, Sallia, niohundrad åtta och tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Och Joel, Sichri son, var deras föreståndare; och Juda, Hasuna son, öfver den andra delen i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Af Presterna bodde: Jedaja, Jojaribs son, Jachin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, Hilkia son, Mesullams sons, Zadoks sons, Merajoths sons, Ahitobs sons, var Förste i Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Och deras bröder, som i husena skaffa hade, voro åttahundrad två och tjugu. Och Adaja, Jerohams son, Pelalja sons, Amzi sons, Zacharia sons, Pashurs sons, Malchija sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'Och hans bröder öfverstar ibland fäderna, voro tuhundrad två och fyratio; och Amassai, Asareels son, Ahsai sons, Mesillemoths sons, Immers sons,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'Och deras bröder, väldige män, voro hundrade åtta och tjugu; och deras föreståndare var Sabdiel, Gedolims son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Af Leviterna: Semaja, Hasubs son, Asrikams sons, Hasabia sons, Bunni sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Och Sabbethai, och Josabad af Leviternas öfverstar, uti de ärende, som utantill voro vid Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Och Matthania, Micha son, Sabdi sons, Assaphs sons, den hufvudet var till att begynna tacksägelse i bönene; och Bakbukia den andre ibland sina bröder; och Abda, Sammua son, Galals sons, Jeduthuns sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Alle Leviterna i dem helga stadenom voro tuhundrad fyra och åttatio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Och dörravaktarena, Akkub och Talmon, och deras bröder, som vid dörrarna vaktade, voro hundrade två och sjutio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Men de andre Israel, Prester och Leviter, voro uti alla Juda städer, hvar och en i sinom arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Och de Nethinim bodde i Ophel; och Ziha, och Gispa hörde till de Nethinim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Föreståndaren öfver de Leviter i Jerusalem var Ussi, Bani son, Hasabia sons, Mattania sons, Micha sons. Utaf Assaphs barn voro sångare vid tjensten i Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Förty Konungens bud var öfver dem, att sångarena skulle handla troliga, hvar och en på den dag, som honom borde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Och Petahja, Mesesabeels son, af Serahs barn, Juda sons, var i Konungens stad i all ärende till folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Och Juda barn, som ute voro på bygdene i sin land, bodde somlige i KiriathArba, och i dess döttrom, och i Dibon, och i dess döttrom, och i Kabzeel, och dess döttrom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'Och i Jesua, Molada, BethPhalet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'HazarSual, BerSeba, och dess döttrom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'Och i Ziklag, och Mechona, och dess döttrom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'Och i EnRimmon, Sarega, Jarmuth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Sanoah, Adullam, och dess döttrom; i Lachis, och på dess mark; i Aseka, och i dess döttrom. Och de lägrade sig, allt ifrå BerSeba intill Hinnoms dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Men BenJamins barn af Geba bodde i Michmas, Aija, BethEl och dess döttrar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Och i Anathoth, Nob, Anania,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hazor, Rama, Gittaim,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Zeboim, Neballat,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod, Ono, i timberdalenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Och somlige Leviterna, som del hade i Juda, bodde ibland BenJamin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Desse äro de Prester och Leviter, som uppdrogo med Serubbabel, Sealthiels son, och Jesua: Seraja, Jeremia, Esra,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amaria, Malluch, Hattus,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sechania, Rehum, Meremoth,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnethoi, Abia,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadia, Bilga,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Jojarib, Jedaja,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Hilkia och Jedaja. Desse voro hufvuden ibland Presterna, och deras bröder i Jesua tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Men Leviterna voro desse: Jesua, Binnui, Kadmiel, Serebia, Juda och Mattania, öfver tackämbetet, han och hans bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Bakbukia och Unni, deras bröder, voro omkring dem i vakt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua födde Jojakim. Jojakim födde Eljasib. Eljasib födde Jojada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada födde Jonathan. Jonathan födde Jaddua.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Och i Jojakims tid voro desse öfverste fäder ibland Presterna, nämliga af Seraja var Meraja; af Jeremia var Hanania;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Af Esra var Mesullam; af Amaria var Johanan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Af Malluch var Jonathan; af Sebania var Joseph;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Af Harim var Adna; af Merajoth var Helkai;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Af Iddo var Zacharia; af Ginnethon var Mesullam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Af Abia var Sichri; af MinjaminMoadia var Piltai;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Af Bilga var Sammua; af Semaja var Jonathan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Af Jojarib var Mattenai; af Jedaja var Ussi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Af Sallai var Kallai; af Amok var Eber;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Af Hilkia var Hasabia; af Jedaja var Nethaneel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Och i Eljasibs tid, Jojada, Johanan och Jaddua, vordo öfverste fäderna ibland Leviterna och Presterna beskrifne, under Darios, den Persens rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Men Levi barn, öfverste fäderna vordo beskrifne i Chrönicon, allt intill Johanans tid, Eljasibs sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Och desse voro öfverstarne i Leviterna: Hasabia, Serebia och Jesua, Kadmiels son; och deras bröder jemte dem, till att lofva och tacka, såsom den Guds mannen David det budit hade, den ena vakten vid den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattania, Bakbukia, Obadja, Mesullam, Talmon och Akkub, voro dörravaktare i vaktene vid dörrena i portomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Desse voro i Jojakims tid, Jesua sons, Jozadaks sons; och i Nehemia den landshöfdingans, och Prestens Esra den Skriftlärdas tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Och uti murens vigning i Jerusalem sökte man Leviterna utur all deras rum, att man skulle hafva dem till Jerusalem, till att hålla vigning med glädje, med tacksägelse, med sång, med cymbaler, psaltare och harpor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Och sig församlade sångarenas barn, och af den ängden omkring Jerusalem, och af Netophati byar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Och af Gilgals hus, och af den mark i Geba, och Asmaveth; förty sångarena hade byggt sig byar omkring Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Och Presterna och Leviterna renade sig, och renade folket, portarna och muren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Och jag lät Juda Förstar stiga upp på muren, och beställde två stora tackchorar; de gingo åstad, den ene på högra sidone ofvan uppå murenom, åt dyngoporten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Och efter dem gick Hosaja, och hälften af Juda Förstar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Och Asaria, Esra, Mesullam,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, BenJamin, Semaja och Jeremia;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Och någre af Prestabarnen med trummeter, nämliga Zacharia, Jonathans son, Semaja sons, Mattania sons, Michaja sons, Saccurs sons, Assaphs sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'Och hans bröder, Semaja, Asareel, Milalai, Gilalai, Maai, Nethaneel och Juda, Hanani med den Guds mansens Davids strängaspel; men Esra den Skriftlärde för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Och vid brunnporten, gentöfver dem, gingo de på trappomen åt Davids stad, uppåt muren om Davids hus, allt intill vattuporten östantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Den andre tackchoren gick tvärsifrå dem, och jag efter honom, och hälften af folket, utåt murenom uppåt ugnatornet, allt intill den breda muren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'Och uppåt Ephraims port, och till gamla porten, och till fiskaporten, och till Hananeels torn, och till Mea torn, allt intill fåraporten; och blefvo ståndande i fängelseportenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Och stodo alltså de två tackchorer uti Guds huse, och jag, och hälften af öfverstarna med mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Och Presterna, nämliga Eljakim, Maaseja, Minjamin, Michaja, Eljoenai, Zacharia, Hanania, med trummeter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'Och Maaseja, Semaja, Eleasar, Ussi, Johanan, Malchija, Elam och Eser; och sångarena söngo högt; och Jisrahja var föreståndaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Och stor offer vordo offrad på den samma dagen, och de voro glade; ty Gud hade gjort dem en stor glädje, så att både qvinnor och barn fröjdade sig; och Jerusalems glädje hördes långan väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'På den tiden vordo män förskickade öfver skattkistona, der häfoffer, förstling och tiond uti var, att de skulle samka tillhopa af åkromen omkring städerna, till att utdela efter lagen för Prester och Leviter; ty Juda hade en glädje af Presterna och Leviterna, att de stodo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Och de höllo sins Guds vakt, och reningenes vakt; och sångarena och dörravaktarena stodo efter Davids och hans sons Salomos bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Förty i Davids och Assaphs tid vordo stiktade öfverste sångare, och lofsånger, och tacksägningar till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Men hele Israel gaf sångarena och dörravaktarena delar uti Serubbabels och Nehemia tid, hvar dagen sin del. Och de gåfvo af det helgada Levitomen; och Leviterna gåfvo Aarons barnom af det helgada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Och på den tid vardt Mose bok läsen för folkens öron; och vardt funnet deruti skrifvet, att de Ammoniter och de Moabiter skulle aldrig komma uti Guds församling;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Derföre, att de icke mötte Israels barnom med bröd och vatten, utan lejde Bileam emot dem, att han skulle förbanna dem; ändock vår Gud vände den förbannelsen uti välsignelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Då de nu hörde denna lagen, afskiljde de allt blandningsfolk ifrån Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Och tillförene hade Presten Eljasib lagt Tobia håfvor uti offerkammaren, i vår Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Förty han hade gjort honom en stor kammar, der de hade tillförene lagt spisoffer, rökelse, redskap och tiond af säd, vin och oljo, efter Leviternas, sångarenas och dörravaktarenas bud; dertill Presternas häfoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Men i allt detta var jag icke i Jerusalem; ty uti andra och tretionde årena Arthahsasta, Konungens i Babel, kom jag till Konungen; och efter några dagar förvärfde jag lof af Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Och jag drog åter till Jerusalem; och jag förmärkte, att det icke godt var, som Eljasib med Tobia gjort hade, i det han gjorde honom en kammar i gårdenom till Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Och mig förtröt det svårliga; och jag kastade all Tobia hus tyg ut för kammaren,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Och bad, att de skulle rena kamrarna; och jag lät komma dit i samma staden Guds hus tyg, spisoffer och rökelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Och jag förnam, att Leviternas delar vordo dem icke gifne; för hvilka sak Leviterna och sångarena voro bortflydde, hvar till sin åker, till att arbeta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Då straffade jag öfverstarna, och sade: Hvi öfvergifve vi Guds hus? Men jag församlade dem, och satte dem i sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Och hele Juda lät komma fram tiond af säd, vin och oljo, i drätselen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Och jag satte öfver drätselen Selemia Presten, och Zadok den Skriftlärda, och af Leviterna, Pedaja; och under deras hand Hanan, Saccurs son, Mattania sons; förty de voro hållne för trogna män, och dem vardt befaldt utskifta sinom brödrom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Tänk uppå mig, min Gud, derföre, och bortkasta icke mina barmhertighet, som jag med mins Guds huse, och i hans vakt, gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'På samma tiden såg jag i Juda trampas i presserna om Sabbathen, och införas kärfvar, och åsnar ladda med vin, drufvor, fikon och allahanda bördor, till Jerusalem, på Sabbathsdagen; och jag betygade dem på den dagen, då de sålde spisningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Bodde desslikes Tyrer derinne; de förde fisk och allahanda varor, och sålde det på Sabbatherna, Juda barnom och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Då straffade jag de öfversta i Juda, och sade till dem: Hvad är det för en ond ting, som I gören, och bryten Sabbathsdagen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Gjorde icke våre fäder så, och vår Gud lät komma alla denna olyckon öfver oss, och öfver denna staden? Och I gören ännu vredena öfver Israel större, brytande Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Och då portarna i Jerusalem uppdragne voro för Sabbathen, böd jag tillsluta portarna, och befallde, att man icke skulle upplåta dem intill efter Sabbathen; och jag satte några af mina tjenare vid portarna, att ingen börda skulle föras derin om Sabbathsdagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Så blefvo de krämare och köpmän, med allahanda varor, om nattena, utanför porten af Jerusalem, en gång och annan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Då betygade jag dem, och sade till dem: Hvi blifven I om nattene utanför muren? Om I gören så mer, skall min hand komma uppå eder. Ifrå den tiden kommo de intet om Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Och jag sade till Leviterna, som rene voro, att de skulle komma och vakta portarna, till att helga Sabbathsdagen. Min Gud, tänk ock på mig för detta här, och skona mig efter dina stora barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Jag såg ock på den tiden, att Judarna togo sig hustrur af Asdod, Ammon och Moab;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Och deras barn talade half Asdodisko, och kunde icke tala Judisko, utan efter hvars folkens mål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Och jag straffade dem, och bannade dem, och slog några män, och hårdrog dem, och tog en ed af dem vid Gud: I skolen icke gifva edra döttrar deras söner, icke heller taga deras döttrar till edra söner, eller till eder sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Hafver icke Salomo, Israels Konung, syndat dermed? Och var dock ibland många Hedningar ingen Konung honom lik. Och han var sinom Gud kär; och Gud satte honom till Konung öfver hela Israel. Likväl kommo de utländska qvinnor honom till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Hafven I det icke hört, medan I sådant stort ondt gören, och förtagen eder emot vår Gud med främmande qvinnors giftermål?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Och en af Jojada barn, Eljasibs sons, öfversta Prestens, hade befryndat sig med Saneballat den Horoniten; men jag dref honom ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Tänk uppå dem, min Gud, som besmitta Presterskapet, och Presterskapens förbund, och Leviternas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Alltså renade jag dem ifrån alla utländska; och beställde Presternas och Leviternas vakt, hvar och en till sitt ämbete;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Och till att offra ved, på bestämd tid, och förstling. Tänk uppå mig, Gud, till det bästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Uti Ahasveros tid, hvilken rådandes var, allt ifrån Indien intill Ethiopien, öfver hundrade sju och tjugu land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Då han satt på sinom Konungsliga stol, i den staden Susan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'I tredje årena hans rikes, gjorde han ett gästabåd när sig, åt alla sina Förstar och tjenare; nämliga dem väldigom i Persien och Meden, landshöfdingom och öfverstom i sin land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'På det han skulle låta se sins rikes härliga rikedomar och det kosteliga prål af sitt majestät, i många dagar, nämliga i hundrade och åttatio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Då de dagar ute voro, gjorde Konungen ett gästabåd allo folkena, som i stadenom Susan var, både stora och små, i sju dagar, uti en sal i trägårdenom invid Konungshuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Der voro upphängd hvit, röd och gul tapeter, fattad med linnen och skarlakanståg, uti silfringar på marmorstodar. Bänkerna voro af guld och silfver, på golfvena, som lagdt var med grön, hvit, gul och svart marmorsten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Och dryckerna bar man in uti gyldene kar, och ju annor och annor kar, och Konungsligit vin tillfyllest, såsom Konungen det väl förmådde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Och man lade ingom före hvad han dricka skulle; ty Konungen hade befallt alla föreståndarena i sitt hus, att hvar och en skulle göra såsom honom lyste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Och Drottningen Vasthi gjorde också ett gästabåd för qvinnorna uti Konungshusena, der Konung Ahasveros plägade vistas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Och på sjunde dagen, då Konungen vardt lustig af vinet, sade han till Mehuman, Bistha, Harbona, Bigtha, Abagtha, Sethar och Charcas, de sju kamererare, som för Konung Ahasveros tjente,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Att de skulle hafva Drottning Vasthi in för Konungen, med Drottningakrono, på det han skulle låta folket och Förstarna se hennes dägelighet; ty hon var dägelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Men Drottning Vasthi ville icke komma efter Konungens ord, genom hans kamererare. Då vardt Konungen ganska vred, och upptänd i grymhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Och Konungen sade till de visa, som i landsseder förfarne voro; ty Konungens ärende måste hafvas inför alla förståndiga i lag och rätt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'Men de näste, som när honom voro, voro Charsena, Sethar, Admatha, Tharsis, Meres, Marsena och Memuchan, de sju Förstar af Persien och Meden, som sågo på Konungens ansigte, och såto främst i rikena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Hvad man göra skulle Drottning Vasthi för en rätt, derföre, att hon icke gjort hade efter Konungens ord, genom hans kamererare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Då sade Memuchan inför Konungenom och Förstarna: Drottning Vasthi hafver icke allenast illa gjort emot Konungen, utan ock emot alla Förstar, och allt folk uti Konung Ahasveros landom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Förty detta stycket af Drottningen kommer väl ut till alla qvinnor, så att de skola förakta sina män för sin ögon, och skola säga: Konung Ahasveros böd Drottningene Vasthi komma inför sig, men hon ville icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Så varda nu de Förstinnor i Persien och Meden sammalunda sägande till alla Konungens Förstar, när de få detta Drottningenes stycke höra; så skall föraktelse och vrede nog upphäfva sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Om Konungenom så täckes, så låte han ett Konungsligit bud af sig utgå, och skrifva efter de Persers och Meders lag, hvilken man icke öfverträda tör, att Vasthi icke mer skall komma inför Konung Ahasveros; och Konungen gifve hennes rike hennes nästo, den bättre är än hon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Och att detta Konungens bref, som göras skall, må förkunnadt varda i hela rikena, det väl stort är, att alla qvinnor måga hålla sina män för ögon, ibland både små och stora.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Detta täcktes Konungenom och Förstarna; och Konungen gjorde efter Memuchans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Då vordo bref utsänd i all Konungens land, i hvart landet efter dess skrift, och till hvart folk efter dess tungomål, att hvar och en man skulle vara husbonde i sitt hus; och lät tala efter sins folks tungomål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Sedan detta skedt var, när Konungens Ahasveros vrede hade saktat sig, kom han Vasthi ihåg, hvad hon gjort hade, och hvad om henne beslutet var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Då sade Konungens svenner, som honom tjente: Man söke Konungenom upp dägeliga unga jungfrur;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Och Konungen beställe skådare i all land i sitt rike, att de låta komma tillhopa alla dägeliga unga jungfrur, intill den staden Susan i fruhuset, under Hegai hand, Konungens kamererares, hvilken qvinnorna vakta skulle, och få dem deras skrud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Och hvilken pigan Konungenom täckes, den blifve Drottning i Vasthis stad. Det behagade Konungenom, och han gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Då var en Judisk man i Susans stad, han het Mardechai, Jairs son, Simei sons, Kis sons, Jemini sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Den med bortförd var ifrå Jerusalem, då Jechonia, Juda Konung, bortförd var, hvilken NebucadNezar, Konungen i Babel, bortförde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Och han var förmyndare till Hadassa, denna är Esther, sins faderbroders dotter; förty hon hade hvarken fader eller moder, och hon var en fager och dägelig piga; och då hennes fader och moder blefvo döde, tog Mardechai henne för sin dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Då Konungens bud och beslut vardt kunnigt, och många pigor voro tillhopahemtade till staden Susan, under Hegai hand, vardt Esther ock tagen uti Konungshuset, under Hegai hand, qvinnovaktarens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Och pigan täcktes honom, och hon fann barmhertighet för honom; och han skyndade sig med hennes skrud, att han skulle få henne hennes del, och sju dägeliga pigor utaf Konungshuset dertill; och han satte henne med hennes pigor uti bästa rummet i fruhuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Och Esther sade honom intet utaf sitt folk, eller sitt slägte; förty Mardechai hade budit henne, att hon skulle icke sägat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Och Mardechai spatserade hvar dag i gårdenom åt fruhuset, att han måtte förnimma, om väl ginge med Esther, och hvad med henne ske kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Då nu hvarjo pigones bestämda tid kom, att hon skulle komma till Konungen Ahasveros, sedan hon hade varit i tolf månader i fruprydning; förty deras prydelse måste så mycken tid hafva, nämliga sex månader med balsam och myrrham, och sex månader med godt speceri, så voro då qvinnorna tillprydda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Och så gick då en piga in till Konungen; och hvilka hon ville, måste man få henne, som med henne gå skulle ifrå fruhuset till Konungshuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Och när en om aftonen inkom, gick hon om morgonen ifrå honom in uti det andra fruhuset, under Saasgas hand, Konungens kamererares, frillovaktarens; och hon måste icke komma igen till Konungen, utan Konungenom täcktes, och han lät kalla henne vid namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Då nu Esthers tid kom, Abihails dotters, Mardechai faderbroders, den henne för dotter tagit hade, att hon skulle komma till Konungen, begärade hon intet annat, än det Hegai, Konungens kamererare, qvinnovaktaren, sade henne före. Och Esther fann nåd för alla dem, som sågo uppå henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Men Esther vardt tagen till Konungen Ahasveros, uti Konungshuset, i tionde månadenom, den Thebeth kallas; i sjunde årena hans rikes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Och Konungen fick Esther kär öfver alla qvinnor, och hon fann nåd och barmhertighet för honom, för alla jungfrur; och han satte Drottningakrono uppå hennes hufvud, och gjorde henne till Drottning i Vasthis stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Och Konungen gjorde ett stort gästabåd, till alla sina Förstar och tjenare; det gästabådet var för Esthers skull; och lät landen hafva rolighet, och gaf ut Konungsliga skänker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Och då man annan gång församlade jungfrur, satt Mardechai vid Konungens dörr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Och Esther hade ännu icke sagt sitt slägte, eller folk, såsom Mardechai henne budit hade; ty Esther gjorde efter Mardechai ord, lika som då han hennes förmyndare var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'På samma tiden, då Mardechai vid Konungens dörr satt, vordo två Konungens kamererare vrede, Bigthan och Theres, som dörrena vaktade, och hade i sinnet, att de ville slå uppå Konungen Ahasveros.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Det förnam Mardechai, och lät Drottningena Esther få veta det; och Esther sade det för Konungenom, på Mardechai vägnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Och då man ransakade derefter, vardt det så funnet; och de vordo både hängde i trän; och det vardt beskrifvet i Chrönicon för Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Sedan detta skedt var, uppsatte Konungen Haman, Medatha son, den Agagiten, och upphöjde honom; och satte hans stol öfver alla Förstar, som när honom voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Och alle Konungens tjenare, som för Konungens dörr vistades, böjde knän och tillbådo Haman; ty Konung Ahasveros hade så budit. Men Mardechai böjde icke knän, och tillbad honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Då sade Konungens tjenare, som för Konungens dörr voro, till Mardechai: Hvi öfverträder du Konungens bud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Och som de hvar dag sade honom sådant, och han skötte intet derom, sade de det för Haman, att de skulle få se, om Mardechai ville blifva ståndandes vid sin ord; ty han hade sagt dem, att han var en Jude.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Och då Haman såg, att Mardechai icke böjde honom knän, ej heller tillbad honom, vardt han full med grymhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Och räknade för litet, att han skulle bära sina hand på Mardechai allena; ty de hade sagt honom om Mardechai folk; utan han for efter att förgöra Mardechai folk, alla de Judar som i hela Ahasveros rike voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Uti första månadenom, det är i den månaden Nisan, i tolfte årena Konungs Ahasveros, vardt lotten kastad för Haman, ifrå den ena dagen till den andra, och ifrå månad, allt intill den tolfte månaden, det är den månaden Adar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Och Haman sade till Konung Ahasveros: Ett folk är förströdt, och hafver delat sig ibland all folk i all dins rikes land, och deras lag äro annor än all folks, och de göra icke efter Konungens lag; och Konungenom står icke till görande att låta dem så blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Om Konungenom så täckes, så skrifve att man förgör dem; så vill jag uppväga tiotusend centener silfver i arbetares hand, till att låta inkomma uti Konungens kammar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Då tog Konungen sin ring af handene, och fick Haman, Medatha son, dem Agagitenom, Judarnas fienda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Och Konungen sade till Haman: Silfret vare dig skänkt, och folket dertill, att du må dermed göra hvad dig täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Då kallade man Konungens skrifvare, på trettonde dagen i första månadenom; och vardt skrifvet, såsom Haman befallde, till Konungens Förstar och till landshöfdingarna, både här och der i landen, och till höfvitsmännerna för hvart folket i landen här och der, efter hvars och ens folks skrift, och efter deras mål, under Konung Ahasveros namn, och med Konungens insegel försegladt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Och brefven vordo försänd med båd, uti all Konungens land, till att förgöra, dräpa och förlägga alla Judar, både unga och gamla, barn och qvinnor, allt på en dag, nämliga på trettonde dagen i tolfte månadenom, det är den månaden Adar; och till att sköfla deras gods.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Alltså höll brefvet inne, att ett båd utgånget var i all land, till att förkunna all folk, att de på den samma dagen skulle redo vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Och båden gingo ut med hast, efter Konungens befallning, och i staden Susan vardt uppslaget ett påbud; och Konungen och Haman såto och drucko; och staden Susan vardt bekymrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Då Mardechai förnam hvad skedt var, ref han sin kläder sönder, och drog en säck uppå, och strödde asko uppå sig; och gick ut midt i staden, ropandes högeliga och klageliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Och kom inför Konungens dörr; ty ingen måtte komma in genom Konungens dörr, som en säck hade på sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Och i all land, dit som Konungens ord och bud räckte, var en stor jämmer ibland Judarna; och månge fastade och greto, sörjde, och lågo i säcker och i asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Då kommo Esthers tjenstepigor, och hennes kamererare, och sade henne det. Då vardt Drottningen svårliga förfärad; och hon sände kläder till Mardechai, att han skulle draga dem uppå, och lägga säcken af sig; men han tog dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Då kallade Esther Hatach, en af Konungens kamererare, som för henne stod, och gaf honom befallning till Mardechai, att hon måtte få veta hvad det vore, och hvi han gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Då gick Hatach ut till Mardechai, der han stod på gatone i stadenom, utanför Konungens port.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Och Mardechai sade honom allt det honom händt var, och summon af silfret, som Haman tillredt hade, till att väga in uti Konungens kammar, för Judarnas skull, att han måtte förgöra dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Och fick honom afskriftena af budet, som i Susan uppslaget var på deras förderf, att han skulle det låta se Esther; och böd henne att hon skulle ingå till Konungen, och bedas en bön af honom, och få veta af honom om sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'När Hatach kom in, och sade Esther Mardechai ord,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Sade Esther till Hatach, och lät säga Mardechai:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Det veta alle Konungens tjenare och folken i Konungens land, att hvilken som ingår till Konungen i den inra gården, vare sig man eller qvinna, den icke kallad är, den skall efter lagen straxt dö, utan så är, att Konungen räcker ut emot honom den gyldene spiron, att han dermed må lefvandes blifva; men jag är nu intet kallad i tretio dagar, till att komma in till Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Då denna Esthers ord vordo sagd Mardechai,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Bad Mardechai säga henne igen: Tänk icke det, att du undsätter ditt lif, efter du äst i Konungens hus, för alla Judar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Förty om du i denna gången tiger stilla, så kommer Judomen en hjelp och undsättning af en annan väg, och du och dins faders hus varder förgåendes; och ho vet, om du icke för denna tidens skull äst kommen till riket?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Esther lät svara Mardechai:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Så gack nu bort, och församla alla Judar, som i Susan för handene äro; och faster för mig, så att I icke äten eller dricken i tre dygn, hvarken dag eller natt; jag och mina tjenarinnor vilje också fasta; och så vill jag gå in för Konungen, emot budet; blifver jag borto, så är jag borto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Mardechai gick bort, och gjorde alltså, som Esther honom budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'På tredje dagen klädde Esther sig i Drottningaklädning, och gick in i gården för Konungshuset, innerst emot Konungsmaket; och Konungen satt på sinom Konungsliga stol i Konungshusena, tvärt emot dörrena i huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Och då Konungen såg Esther Drottningena stå i gårdenom, fann hon nåde för hans ögon; och Konungen räckte ut den gyldene spiron i sine hand emot Esther. Så gick Esther fram, och tog på ändan af spirone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Då sade Konungen till henne: Hvad vill du, Drottning Esther, och hvad begärar du? Ja, ock hälften af riket skall dig gifvet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Esther sade: Om Konungenom täckes, så komme Konungen och Haman i dag till en måltid, som jag tillredt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Konungen sade: Skynder eder, att Haman må göra, som Esther sagt hafver. Och Konungen och Haman kommo till måltiden, som Esther tillredt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Då sade Konungen till Esther, när han vin druckit hade: Hvad bedes du? Det skall dig gifvet varda; och hvad begärar du? Ja, ock hälften af mitt rike, det skall dig ske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Esther svarade, och sade: Min bön och begär är:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Hafver jag funnit nåd för Konungenom, och Konungenom täckes gifva mig min bön, och göra mitt begär, så komme Konungen och Haman till måltid, som jag för dem tillreda vill, så vill jag i morgon göra som Konungen sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Så gick Haman den dagen glad derut, och lustig; och då han såg Mardechai vid Konungens dörr, att han icke uppstod, och icke en tid rörde sig för honom, vardt han full med vrede öfver Mardechai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Men Haman lät det intet bekomma sig; och då han hemkom, sände han, och lät kalla sina vänner, och sina hustru Seres;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Och förtäljde för dem sina rikedomars härlighet, och sina barnas myckenhet, och huru Konungen hade gjort honom väldigan, och att han upphöjd var öfver Konungens Förstar och tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Och sade Haman ytterligare: Ock hafver Drottningen Esther ingen låtit komma med Konungenom till den måltid, som hon tillredt hade, utan mig; och är jag desslikes i morgon buden till henne, med Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Men med detta allt kan jag intet vara tillfrids, så länge jag ser den Judan Mardechai sitta för Konungens dörr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Då sade till honom hans hustru Seres, och alle hans vänner: Låt uppresa en galga, femtio alnar hög, och säg i morgon Konungenom, att man låter hänga der Mardechai uti; så kommer du med Konungenom glad till måltid. Det täcktes Haman väl, och han lät uppresa en galga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Uti den samma nattene kunde Konungen intet sofva, och lät hemta Chrönicor och Historier; och de vordo läsna för Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Då råkade man der uppå, der skrifvet var, huru Mardechai hade gjort förvaring, att de två Konungens kamererare, Bigthan och Theres, som vaktade vid dörrena, hade i sinnet slå uppå Konungen Ahasveros.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Och Konungen sade: Hvad hafve vi gjort Mardechai till äro och lön derföre? Då sade Konungens svenner, som honom tjente; Honom är intet skedt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Och Konungen sade: Ho är der i gårdenom? Ty Haman var kommen i gården, utanför Konungshuset, att han skulle säga Konungenom om Mardechai, att han måtte hänga i galganom, som han honom tillredt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Och Konungens svenner sade till honom: Si, Haman står ute på gårdenom. Konungen sade: Låt honom komma in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Då Haman kom in, sade Konungen till honom: Hvad skall man göra dem manne, som Konungen gerna ära vill? Men Haman tänkte i sitt hjerta: Hvem skulle Konungen gerna vilja göra äro, utan mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Och Haman sade till Konungen: Den man, som Konungen gerna vill ära,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Honom skall man hafva fram, och kläda uppå honom Konungslig kläder, de Konungen plägar draga, och den häst, som Konungen plägar uppå rida, och att man sätter en Konungslig krono på hans hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Och man må få den klädningen och hästen uti en Konungens Förstas hand, att han ikläder den man, som Konungen gerna ära vill, och förer honom på hästenom öfver stadsgatorna, och låter ropa framför honom: Så skall man göra dem, som Konungen gerna ära vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Konungen sade till Haman: Skynda dig, och tag klädningen och hästen, såsom du sagt hafver, och gör alltså med dem Judanom Mardechai, som för Konungens dörr sitter; och låt intet fattas af allt det du sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Så tog Haman klädningen och hästen, och klädde på Mardechai, och förde honom på stadsgatone, och ropade framför honom: Så skall man göra dem manne, som Konungen gerna ära vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Och Mardechai kom igen inför Konungens dörr; men Haman skyndade sig hem, och sörjde med skyldt hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Och förtäljde sine hustru Seres, och allom sinom vännom, allt det honom händt hade. Då sade till honom hans vise, och hans hustru Seres: Är Mardechai af Juda säd, för hvilkom du hafver begynt att falla, så hafver du ingen magt med honom, utan du måste falla för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Vid de ännu med honom talade, kommo Konungens kamererare dertill, och hastade på Haman, till att komma till måltidena, som Esther tillredt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Då Konungen kom neder med Haman till måltiden, som Drottningen Esther tillredt hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Sade Konungen till Esther, på den andra dagen, då han vin druckit hade: Hvad bedes du, Drottning Esther, det man dig gifva må? Och hvad begärar du? Ja, ock halfva riket, det skall ske dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Drottningen Esther svarade, och sade: Hafver jag funnit nåd för dig, o Konung, och om Konungenom så täckes, så gif mig mitt lif för mina böns skull, och mitt folk för mitt begärs skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Ty vi äro sålde, jag och mitt folk, till att vi skole förgöras, slås ihjäl och förläggas; Gud gifve, att vi dock hade till trälar och trälinnor sålde varit, så ville jag hafva tegat; och hade då fienden icke gjort Konungenom skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Konungen Ahasveros talade, och sade till Drottningen Esther: Hvilken är den? Eller ho är den som sådant tör sätta sig i sinnet att göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Esther sade: Den fienden och hataren är denne onde Haman. Men Haman vardt förskräckt för Konungenom och Drottningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Och Konungen stod upp ifrå måltidene, och ifrå vinet, i sine grymhet, och gick in uti trägården vid huset; och Haman stod upp, och bad Drottningena Esther om sitt lif; ty han såg, att honom var ondt beredt af Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Och då Konungen kom åter igen af trägårdenom vid huset, in uti salen, der man ätit hade, lutade Haman inpå bänken, der Esther på satt. Då sade Konungen: Vill han ock öfverfalla Drottningena här i husena när mig? Då det ordet gick utu Konungens mun, förskylde de Hamans ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Och Harbona, en af kamererarena inför Konungenom, sade: Si, uti Hamans hus står en galge femtio alnar hög, som han till Mardechai gjort hafver, hvilken för Konungenom godt talat hafver. Konungen sade: Låt hänga honom deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Alltså hängde man Haman i galgan, som han till Mardechai gjort hade. Sedan saktade sig Konungens vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'På den dagen gaf Konungen Ahasveros Drottningene Esther Hamans, Judarnas fiendas, hus; och Mardechai kom för Konungen; förty Esther lät förstå, huru han var henne åkommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Och Konungen tog sin ring af, som han af Haman tagit hade, och fick Mardechai. Och Esther satte Mardechai öfver Hamans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Och Esther talade ytterligare för Konungenom, och föll honom till fota, gret och bad honom, att han skulle tillintetgöra Hamans den Agagitens ondsko, och hans uppsåt, som han emot Judarna för händer hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Och Konungen räckte den gyldene spiron till Esther. Då stod Esther upp, och trädde fram för Konungen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Och sade: Om Konungenom täckes, och jag hafver funnit nåd för honom, och det så vore Konungenom beläget, och om jag täckes honom; så skrifve man, att Hamans uppsåts bref, Medatha sons, den Agagitens, måga varda igenkallade, de han utskrifvit hafver till att förgöra Judarna i all Konungens land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Ty huru kan jag lida det onda, som mitt folk uppå gäller? Och huru kan jag se uppå min slägts förderf?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Då sade Konungen Ahasveros till Drottningen Esther, och till Mardechai den Judan: Si, jag hafver gifvet Esther Hamans hus, och honom hafver man hängt i en galga, derföre att han bar sina hand på Judarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Så skrifver I nu ut för Judarna, såsom eder täckes, under Konungens namn, och besegler med Konungens ring; förty de skrifvelse, som under Konungens namn skrifvas, och med Konungens ring beseglade varda, dem måtte ingen igenkalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Så vordo Konungens skrifvare kallade, på den tiden i tredje månadenom, det är den månaden Sivan, på tredje och tjugonde dagen; och vardt skrifvet såsom Mardechai böd, till Judarna, och till Förstarna, landshöfdingarna och höfvitsmännerna i landen, allt ifrån Indien intill Ethiopien, nämliga i hundrade sju och tjugu land; hvarjo lande efter sina skrift, hvarjo folke efter sitt mål, och Judomen efter deras skrift och mål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Och det skrefs under Konung Ahasveros namn, och med Konungens ring beseglades; och han sände brefven med ridande båd på unga mular.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Och befallde Judomen, der som de voro i städerna, att de skulle församla sig, och stå för deras lif, och förgöra, dräpa och förlägga, all lands och folks magt, som dem bedröfvade, med deras barn och qvinnor, och taga deras gods:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'På en dag i all Konungens Ahasveros land, nämliga på trettonde dagen i tolfte månadenom, det är den månaden Adar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Och brefvets innehållelse var, att ett bud utgifvet var i all land, till att kungöra all folk, att Judarna skulle på den dagen redo vara till att hämnas öfver deras fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Och de ridande båden på mular redo ut snarliga och med hast, efter Konungens ord; och påbudet vardt uppslaget i Susans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Men Mardechai gick ut ifrå Konungenom, i Konungsligom klädom, gult och hvitt, och med en stor guldkrono, klädd uti en linnen och purpurmantel; och staden Susan fröjdade sig och var glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Men Judomen var uppgånget ljus och fröjd, glädje och ära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Och i all land och städer, dit Konungens ord och bud räckte, der vardt ibland Judarna fröjd, glädje, lust och goda dagar; så att månge af folken i landen vordo Judar; ty Judarnas fruktan kom öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Uti tolfte månadenom, det är den månaden Adar, på trettonde dagen, hvilken Konungens ord och bud förelagt hade, att man det göra skulle; rätt uppå samma dagen, då fienderna skulle öfverfallit Judarna, vände det sig så, att Judarna skulle öfverfalla sina fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Så församlade Judarne sig i deras städer, i allom Konungs Ahasveros landom, att de skulle göra anfall på dem som dem ondt ämnade; och ingen kunde stå emot dem; förty deras fruktan var kommen öfver all folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Och alle öfverstarna i landen, och Förstarna, och landshöfdingarna, och Konungens ämbetsmän höllo Judarna i äro; ty Mardechai fruktan kom öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Förty Mardechai var myndig i Konungens hus, och hans rykte hördes i all land, huru han växte till, och vardt väldig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Alltså slogo Judarna alla sina fiendar med svärd, dråpo och nederlade dem; och gjorde efter sin vilja på dem som dem fiender voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Och i Susans stad slogo Judarna och dråpo femhundrad män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Dertill slogo de Parsandatha, Dalphon, Aspatha,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Poratha, Adalja, Aridatha,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmastha, Arisai, Aridai, Vajesatha,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'De tio Hamans söner, Medatha sons, Judarnas fiendas; men vid deras ägodelar kommo de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'På samma tiden kom talet på de slagna i Susans stad inför Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Och Konungen sade till Drottningen Esther: Judarna hafva i Susans stad slagit och nederlagt femhundrad män, och de tio Hamans söner; hvad skola de göra i de andra Konungens land? Hvad bedes du, att man dig gifva skall? Och hvad begärar du mer, att man göra skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Esther sade: Om Konungenom täcktes, så låte han ock i morgon Judarna göra i Susan efter det bud, som i dag varit hafver, att de måga hänga de tio Hamans söner i galga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Och Konungen befallde att göra så; och budet vardt i Susan uppslaget, och de tio Hamans söner vordo hängde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Och Judarna församlade sig i Susan på fjortonde dagen i den månaden Adar, och slogo ihjäl i Susan trehundrad män; men vid deras ägodelar kommo de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Men de andre Judar i Konungens landom kommo tillsamman, och stodo för sitt lif, att de måtte göra sig rolighet för sina fiendar, och slogo sina fiendar fem och sjutio tusend; men vid deras ägodelar kommo de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Detta skedde på trettonde dagen i den månaden Adar; och på fjortonde dagen i samma månadenom höllo de hvilo; den gjorde de sig till en vällusts och fröjds dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Men de Judar i Susan voro tillsammankomne, både på trettonde och fjortonde dagen, och höllo hvilo på femtonde dagen; och den dagen gjorde man till en vällusts och glädjes dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Derföre gjorde de Judar, som på bygdene och i småstäderna bodde, den fjortonde dagen i den månaden Adar till en vällusts och glädjes dag, och sände den ene dem andra skänker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Och Mardechai skref allt detta som skedt var, och sände brefven till alla Judar, som voro uti all Konung Ahasveros land, både när och fjerran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Att de skulle vedertaga och hålla den fjortonde och femtonde dagen i den månadenom Adar, hvart år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Efter de dagar, i hvilka Judarna till ro komne voro för sina fiendar, och efter den månaden, i hvilkom deras sorg och glädje, och deras gråt i vällust vänd vardt; att de skulle dem hålla för vällusts och glädjes dagar, och sända den ene dem andra skänker, och dela med de fattiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Och Judarna togo dervid, och gjorde som de begynt hade, och det Mardechai till dem skref;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Huruledes Haman, Medatha son, den Agagiten, alla Judars fiende, hade i sinnet att förgöra alla Judar, och låta kasta lott, till att förskräcka och förgöra dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Och huru Esther hade ingångit till Konungen och beställt, att hans onda uppsåt, som han emot Judarna tänkte, måtte genom bref vändas inpå hans hufvud; och huru man honom och hans söner hade hängt i galga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Af hvilko desse dagar kallades Purim, efter lottsnamnet, efter all detta brefs ord, och hvad de sjelfve sett hade, och hvad till dem räckt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Och Judarna togo det uppå sig och sina säd, och uppå alla dem som gåfvo sig till dem, att de icke ville gå härifrå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Att de ju ville hålla dessa två dagarna hvart år, såsom de föreskrefne och förelagde voro, så att desse dagar icke skulle förgätne, utan hållne varda, barn efter barn i alla slägter, i all land och städer; det äro de dagar Purim, hvilke icke skola brutne varda ibland Judarna, och deras åminnelse icke förgås när deras säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Och Drottningen Esther, Abihails dotter, och Mardechai den Juden, skrefvo med alla magt, till att fast göra detta andra brefvet om Purim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Och sände brefven till alla Judar, uti de hundrade sju och tjugu land i Konungs Ahasveros rike, med vänlig och trofast ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Att de skulle hålla dessa dagar Purim på deras bestämda tid, såsom Mardechai den Juden, och Drottningen Esther dem förelagt hade; såsom de uppå sina själar och uppå sina säd anammat hade det ärendet om fastone och ropet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Och Esther befallde stadfästa detta ärendet om Purim, och skrifva uti en bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Och Konung Ahasveros lade en skatt uppå landet, och uppå öarna i hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Men allt det under hans våld och magt skedde, och om den stora härlighet, som Konungen gaf Mardechai, si, det är skrifvet uti de Konungars Chrönico i Meden och Persien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Ty Mardechai den Juden var den andre näst Konungenom Ahasveros, och stor ibland Judarna, och täck för alla sina bröder; den der sökte det godt var för sitt folk, och talade det bästa för allo sino säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'En man var uti det landet Uz, som het Job; han var from och rättfärdig, gudfruktig, och flydde det onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Och honom vordo födde sju söner och tre döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Och han ägde sjutusend får, tretusend camelar, femhundrade par oxar, och femhundrade åsninnor, och ganska mycket tjenstefolk; och han var mägtigare än alle de i österlanden bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Och hans söner gingo bort, och gjorde gästabåd, hvar sin dag i sitt hus; och sände bort, och läto bjuda sina tre systrar, till att äta och dricka med sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Och när en gästabådsdagen ute var, sände Job bort och helgade dem; och stod bittida upp om morgonen, och offrade bränneoffer, efter allas deras tal. Förty Job tänkte: Mine söner kunna hafva syndat, och välsignat Gud i sin hjerta. Så gjorde Job hvar dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Men det hände på en dag, då Guds barn kommo, och trädde fram för Herran, kom Satan ock med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Men Herren sade till Satan: Hvadan kommer du? Satan svarade Herranom, och sade: Jag hafver farit genom landet allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Då sade Herren till Satan: Hafver du icke gifvit akt uppå min tjenare Job? Ty hans like är icke i landena, from och rättfärdig, gudfruktig, och flyr det onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Satan svarade Herranom, och sade: Menar du, att Job fruktar Gud förgäfves?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Hafver du dock förvarat honom, hans hus, och allt det han hafver allt omkring. Du hafver välsignat hans handaverk, och hans gods hafver utspridt sig i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Men räck ut dina hand, och kom vid allt det han äger; det gäller, han skall välsigna dig i ansigtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Herren sade till Satan: Si, allt det han äger vare i dine hand, allena vid honom sjelfvan kom icke dina hand. Då gick Satan ut ifrå Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Men den dagen, då hans söner och döttrar åto och drucko vin i deras äldsta broders hus,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Kom ett båd till Job, och sade: Man plöjde med oxarna, och åsninnorna gingo der när i bet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Då föllo de af rika Arabien till, och togo dem, och slogo drängerna med svärdsegg; och jag undslapp allena, att jag skulle säga dig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Medan han ännu talade, kom en annar, och sade: Guds eld föll af himmelen, och brände upp fåren och drängerna, och förtärde dem; och jag slapp allena undan, att jag skulle säga dig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Medan han ännu talade, kom en och sade: De Chaldeer gjorde tre spetsar, föllo till camelarna, och togo dem, och slogo drängerna med svärdsegg; och jag slapp allena undan, att jag skulle säga dig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Medan han ännu talade, kom en och sade: Dine söner och döttrar åto och drucko i deras äldsta broders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Och si, der kom ett stort väder utaf öknene, och stötte på husens fyra hörn, och kastade det på piltarna, att de blefvo döde; och jag slapp allena undan, att jag skulle säga dig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Då stod Job upp, och ref sönder sin kläder, och ref sig i hufvudet, och föll ned på jordena, och tillbad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Och sade: Jag är naken kommen af mine moders lif; naken skall jag åter fara dit; Herren gaf, och Herren tog; välsignadt vare Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'I allt detta syndade Job intet, och gjorde intet dårligit emot Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Det begaf sig på en dag, då Guds barn kommo, och trädde fram för Herran, att Satan ock kom med dem, och trädde fram för Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Då sade Herren till Satan: Hvadan kommer du? Satan svarade Herranom, och sade: Jag hafver farit genom landet allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Herren sade till Satan: Hafver du icke gifvit akt på min tjenare Job? Ty hans like är icke i landena, from och rättfärdig, gudfruktig, och flyr det onda, och står ännu i sine fromhet; och du eggade mig, att jag utan sak hafver förderfvat honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Satan svarade Herranom, och sade: Hud för hud, och allt det en man hafver, låter han för sitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Men räck ut dina hand, och kom vid hans ben och kött; det gäller, han skall välsigna dig i ansigtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Herren sade till, Satan: Si, han vare i dine hand; dock skona hans lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Då for Satan ut ifrå Herrans ansigte, och slog Job med ond sår, ifrå hans fotablad upp till hans hjessa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Och han tog ett stycke af en potto, och skrapade af sig dermed, och satt i asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Och hans hustru sade till honom: Står du ännu i dine fromhet? Välsigna Gud, och dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Men han sade till henne: Du talar såsom de dåraktiga qvinnor tala. Hafve vi fått godt af Gudi, skole vi ock icke anamma det onda? Uti allt detta syndade Job icke med sina läppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Då nu tre Jobs vänner hörde all den olycka, som öfver honom kommen var, kommo de hvar af sin stad: Eliphas af Thema, Bildad af Suah, och Zophar af Naema; ty de vordo öfverens, att de skulle komma och ömka sig öfver honom, och trösta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Och då de upphofvo sin ögon långt ifrå, kände de honom intet; och upphofvo sina röst, och greto, och hvardera ref sin kläder sönder, och kastade jord på sin hufvud upp åt himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Och såto med honom på jordene i sju dagar och sju nätter, och talade intet med honom; ty de sågo, att hans sveda var ganska stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Derefter upplät Job sin mun, och förbannade sin dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Utbrast, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Den dagen vare förtappad, på hvilkom jag född är; och den natten, då man sade: En man är aflad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Den samme dagen vare mörk, och Gud fråge intet efter honom ofvanefter; ingen klarhet skine öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Mörkret behålle honom, och töcken blifve öfver honom med tjockt moln; och dimba om dagen göre honom gräselig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Den samma nattena begripe mörker; och glädje sig icke ibland årsens dagar, och komme icke i månadetalet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Si, vare den natten ensam, och ingen glädje komme deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'De der dagen förbanna, de förbanne henne; och de som redo äro till att uppväcka Leviathan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Hennes stjernor varde mörka; förvänte ljus, och det komme intet; och se intet morgonrodnans ögnabryn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Att hon icke igenlyckte mins lifs dörr, och icke bortgömde olyckona för min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Hvi blef jag icke straxt död i moderlifvet? Hvi vardt jag icke förgjord, då jag utu moderlifvet kommen var?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Hvi hafva de tagit mig upp i skötet? Hvi hafver jag ditt spenar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Så låge jag nu, och vore stilla; sofve och hade ro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Med Konungar och rådherrar på jordene, som bygga det öde är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Eller med Förstar, som guld hafva, och sin hus full med silfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Eller som den der otida född är fördold, och vore icke till; såsom de unga barn, som aldrig hafva sett ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Der måste ju de ogudaktige låta af sitt öfvervåld; der hvilas dock de som mycket omak haft hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Der hafva fångar frid med androm, och höra icke trugarens röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Der äro både små och store; tjenaren och den som ifrå sin herra fri är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Hvi är ljus gifvet dem arma, och lif de bedröfvade hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, '(De der vänta efter döden, och han kommer icke; och uppgrofvo honom väl utu fördold rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'De der fröjda sig mycket, och äro glade, att de kunna få grafvena;)');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Och dem månne, hvilkens väg fördold är, och för honom af Gudi skyld varder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Förty min suckan är min dagliga spis; mine tårar äro min dryck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Ty det jag fruktade, det är kommet öfver mig; och det jag räddes, hafver råkat på mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Var jag icke lyckosam? Var jag icke stilla? Hade jag icke goda ro? Och sådana oro kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Då svarade Eliphas af Thema, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Du lider tilläfventyrs icke gerna, om man försöker att tala med dig? Men ho kan låtat?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Si, du hafver undervisat många, och styrkt trötta händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Ditt tal hafver upprest dem, som fallne voro; och bäfvande knä hafver du förstärkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Men nu, medan det kommer på dig, varder du förtvinad; och nu, medan det drabbar på dig, förskräckes du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Ja, der är nu din (Guds) fruktan, din tröst, ditt hopp, och din fromhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Käre, tänk uppå, hvar är någor oskyldiger förgången? Eller hvar äro de rättfärdige någon tid utrotade?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Såsom jag väl sett hafver, de som vedermödo plöjde, och olycko sådde, de skåro det ock upp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Att de äro genom Guds anda förgångne, och af hans vredes anda förgjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Lejonens rytande, och lejinnones röst, och de unga lejons tänder äro sönderbrutna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Lejonet är förgånget, att det icke mera röfvar; och de unga lejon äro förskingrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Och till mig är kommet ett hemligit ord, och mitt öra hafver deraf fått något märkeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Då jag begrundade nattenes syner, då sömnen faller på menniskorna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Då kom fruktan och bäfvande mig uppå, och all min ben förskräcktes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Och då anden gick framom mig, reste mig håret på minom kropp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Då stod en för min ögon, och dess skapnad kände jag intet; han var stilla, och jag hörde ena röst:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Huru kan en menniska vara rättfärdigare än Gud; eller en man vara renare än han, som honom gjort hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Si, ibland sina tjenare finner han icke trohet, och i sinom Änglom finner han dårhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Huru mycket mer de som bo i lerhus; och de der grundade äro på jordene, skola förtäras af matk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Det varar ifrå morgonen intill aftonen, så varda de upphuggne; och förr än de varda det varse, äro de platt borto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Och deras käraste förgås; och dö ock oförvarandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Nämn mig en, hvad gäller, om du någon finner; och se dig om någorstäds efter en helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Men en dåra dräper väl vreden, och en ovisan dödar nitet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Jag såg en dåra väl rotad, och jag bannade straxt hans huse:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Hans barn skola vara fjerran ifrå helsone, och skola varda sönderkrossade i porten, der ingen hjelpare är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Hans säd skall den hungrige uppäta, och de väpnade skola taga henne; och hans gods skola de törstige utsupa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Förty vedermödan går icke upp af jordene, och olyckan växer icke upp af åkrenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Utan menniskan varder född till olycko, såsom foglarna till att flyga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Dock vill jag nu tala om Gud, och handla om honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Som gör mägtig ting, de der icke ransakas kunna; och under, som icke räknas kunna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Den der regn gifver på jordena, och låter vatten komma på markena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Den der upphöjer de nedriga, och upphjelper de förtryckta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Han gör deras anslag, som listige äro till intet, att deras hand intet kan uträtta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Han begriper de visa i deras listighet, och gör de klokas råd till galenskap;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Att de om dagen löpa i mörkrena, och famla om middagen såsom om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Och han hjelper den fattiga ifrå svärdet, och ifrå deras mun; och utu dens väldigas hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Och är dens fattigas tröst, att orättfärdigheten måste hålla sin mun till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Si, salig är den menniska, den Gud straffar; derföre förkasta icke dens Allsmägtigas tuktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Ty han sargar, och läker; han slår, och hans hand helar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Utaf sex bedröfvelser frälsar han dig, och i den sjunde kommer intet ondt vid dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'I dyr tid frälsar han dig ifrå döden, och i stridene ifrå svärdsens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Han skall skyla dig för tungones gissel, att du icke skall frukta för förderf, då det kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Uti förderf och hunger skall du le, och icke frukta för vilddjuren i landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Utan ditt förbund skall vara med stenom på markene; och vilddjuren i landena skola hålla frid med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Och du skall förnimma, att din hydda hafver frid, och skall försörja dina boning, och icke synda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Och skall förnimma, att din säd skall varda mycken, och dine efterkommande såsom gräs på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Och skall i ålderdomen komma till grafva, såsom en hvetekärfve införd varder, i rättom tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Si, det hafve vi ransakat, och det är så; hör dertill, och rätta dig derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'När man voge min jämmer, och lade allt mitt lidande på ena våg,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Så skulle det vara svårare, än sanden i hafvet; derföre är förgäfves hvad jag säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Förty dens Allsmägtigas pilar stå i mig, hvilkens grymhet utsuper allan min anda; och Guds förskräckelse äro ställd uppå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Icke ropar vildåsnen, när han hafver gräs; ej heller oxen, då han hafver foder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Kan man ock äta det som osaltadt är? Eller månn någor vilja smaka det hvita om äggeblomman?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Der min själ tillförene vämjade vid, det är nu min mat för värks skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'O! att min bön måtte ske, och Gud gåfve mig det jag förhoppas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Att Gud toge till att sönderslå mig, och låte sina hand sönderkrossa mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Så hade jag ändå tröst, och ville bedja i minom sjukdom, att han icke skonade mig; jag hafver dock icke nekat dens Heligas tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Hvad är min kraft, att jag skulle kunna härda ut? Och hvad är min ändalykt, att min själ skulle vara tålig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Min kraft är dock icke af sten, ej är heller mitt kött af koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Hafver jag dock ingenstäds hjelp; och ingen ting vill gå fram med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Den der icke bevisar sinom nästa barmhertighet, han öfvergifver dens Allsmägtigas fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Mine bröder gå förakteliga framom mig, såsom en bäck; såsom en ström framom flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Dock de som rädas för rimfrostet, öfver dem varder fallandes snö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Den tid hetten tvingar dem, skola de försmäkta; och när det hett blifver, skola de förgås utaf sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Deras väg går afsides bort; de vandra der intet vägadt är, och förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'De se uppå Thema vägar; på rika Arabiens stigar akta de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Men de skola komma på skam, då det är aldrasäkrast; och skola skämma sig, då de deruppå komne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Ty I ären nu komne till mig; och medan I sen jämmer, frukten I eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Hafver jag ock sagt: Bärer hit, och skänker mig af edro förmågo?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Och hjelper mig utu fiendans hand? Och förlosser mig utu tyranners händer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Lärer mig, jag vill tiga; och det jag icke vet, det underviser mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Hvi straffen I rättfärdigt tal? Hvilken är ibland eder, som det straffa kan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'I sätten samman ord, allenast till att straffa, och gören med ordom ett förtvifladt mod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'I öfverfallen en fattigan faderlösan, och rycken edar nästa upp med rötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Dock, medan I hafven begynt, ser uppå mig, om jag varder beslagen med någon lögn för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Svarer hvad som rätt är; min svar skola väl blifva rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Hvad gäller, min tunga hafver icke orätt, och min mun föregifver icke ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Måste icke menniskan alltid vara i strid på jordene; och hennes dagar äro såsom en dagakarls?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Såsom en dräng åstundar skuggan, och en dagakarl, att hans arbete må vara ute;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Så hafver jag väl arbetat hela månaden fåfängt, och bedröfvada nätter äro mig många vordna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'När jag lägger mig, säger jag: När månn jag skola uppstå? Och sedan räknar jag, när afton skall varda; ty jag var hvarjom manne en styggelse intill mörkret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mitt kött är fullt med matk och mull allt omkring; min hud är sammanskrynkt och till intet vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Mine dagar äro snarare bortflogne än en väfspole; och äro förledne utan all förtöfvan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Tänk uppå, att mitt lif är ett väder, och min ögon komma icke igen till att se det goda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Och intet lefvandes öga varder mig mera seendes; din ögon se på mig, deröfver förgås jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Molnet varder allt, och går bort; så ock den som far neder i helvetet, han kommer icke upp igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Och besitter icke sitt hus igen, och hans rum blifver öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Derföre vill jag ock icke förmena minom mun; jag vill tala i mins hjertas ångest, och vill utsäga min själs bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Är jag ett haf, eller en hvalfisk, att du så förvarar mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Ty jag tänkte: Min säng skall trösta mig; mitt lägre skall lisa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'När jag talar med mig sjelf, så förskräcker du mig med drömmar, och gör mig förfärelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Att min själ önskar sig vara hängd, och min ben döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Jag begärar intet mer lefva; håll upp af mig; ty mine dagar äro fåfängelige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Hvad är en menniska, att du aktar henne högt, och bekymrar dig med henne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Du hemsöker henne dagliga, och försöker henne alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Hvi går du icke ifrå mig, och släpper mig, så länge jag uppsvälger min spott?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Hafver jag syndat, hvad skall jag göra dig, o du menniskors gömmare? Hvi gjorde du mig, att jag uppå dig stöta skulle, och är mig sjelfvom till tunga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Och hvi förlåter du mig icke mina missgerning, och tager icke bort mina synd? Ty nu skall jag lägga mig i mull; och när man om morgonen söker mig, är jag då intet till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Då svarade Bildad af Suah, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Huru länge vill du sådana tala, och låta dins muns tal hafva ett sådant högmod?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Menar du, att Gud dömmer orätt; eller den Allsmägtige skall vrida rätten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Om dine söner hafva syndat för honom, så hafver han förkastat dem för deras missgernings skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Men om du i tid gifver dig in till Gud, och beder den Allsmägtiga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Och om du äst ren och from, så varder han uppvakandes till dig, och varder åter upprättandes boningen för dina rättfärdighets skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Och der du tillförene hafver haft litet, skall det härefter ganska mycket förökas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Ty fråga de slägter, som i förtiden varit hafva, och tag dig före att fråga deras fäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Ty vi äre såsom i går komne, och vete intet; vårt lif är en skugge på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'De skola lära dig, och säga dig det, och gifva sitt tal före utaf sitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Icke kan säfvet växa, utan det står i vätsko; eller gräs växa utan vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Eljest, medan det än står i blomster, förr än det afhugget varder, förtorkas det, förr än man hö bergar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Så går allom dem som förgäta Gud, och de skrymtares hopp varder förtappadt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Ty hans tröst blifver omintet, och hans hopp såsom ett dvergsnät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Han förlåter sig på sitt hus, och skall dock icke, bestå; han skall hålla sig derintill, och dock icke beständig blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Det grönskas väl förr än solen kommer, och qvistar växa uti dess örtagård;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Dess säd står tjock vid källor, och dess hus på stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Men när han uppsluker honom af sitt rum, ställer han sig emot honom, såsom han kände honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Si, detta är fröjden i dess väsende; och annor växa upp igen af stoftet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Derföre, si, att Gud icke förkastar de goda, och icke uppehåller de ondas hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Tilldess din mun varder full med löje, och dine läppar fulle med fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Men de, som dig hata, skola komma på skam, och de ogudaktigas boning skall icke blifva beståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Job svarade och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Ja, jag vet det fullväl, att så är, att en menniska icke kan bestå rättfärdig för Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Täckes honom träta med honom, så kan han icke svara honom ett emot tusende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Han är vis och mägtig; hvem hafver det dock gått väl af, som sig hafver satt emot honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Han försätter bergen, förr än de det förnimma; hvilka han i sine vrede omkastar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Han rörer jordena af sitt rum, så att hennes pelare bäfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Han talar till solena, så går hon intet upp, och han förseglar stjernorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Han allena utsträcker himmelen, och går på hafsens vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Han gör Karlavagnen (på himmelen) och Orion; sjustjernorna, och de stjernor söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Han gör mägtig ting, som man icke utransaka kan, och under, deruppå intet tal är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Si, han går framom mig, förr än jag varder det varse; och han förvandlar sig, förr än jag det märker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Si, om han går hasteliga bort, ho vill hemta honom igen? Ho vill säga till honom: Hvad gör du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Han är Gud, hans vrede kan ingen stilla; under honom måste buga sig de stolta herrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Huru skulle jag då svara honom, och finna några ord emot honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Om jag än rätt hafver, så kan jag dock likväl intet svara honom; utan måste i rättenom bedjas före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Och om jag än åkallade honom, och han hörde mig; så tror jag dock icke, att han hörer mina röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Ty han far öfver mig med storm, och gör mig såren mång utan sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Han låter icke min anda vederqvickas, utan gör mig full med bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Vill man magt, så är han för mägtig; vill man rätten, ho vill vittna med mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Om jag säger att jag är rättfärdig, så fördömer han mig dock; är jag from, så för han mig dock till ondan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Är jag än from, så tör min själ dock intet hålla sig dervid; jag begärer intet mer lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Det är det som jag sagt hafver; han förgör både den goda, och den ogudaktiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'När han begynner till att slå, så dräper han straxt, och begabbar de oskyldigas frestelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Men landet varder gifvet under dens ogudaktigas hand, att han undertrycker dess domare; är det icke så, huru skulle det annars vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Mine dagar hafva varit snarare än en löpare; de hafva flytt, och hafva intet godt sett.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'De äro förgångne såsom stark skepp; såsom en örn flyger till maten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'När jag tänker: Jag vill glömma bort min klagan; jag vill förvandla mitt ansigte, och vederqvicka mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Så fruktar jag mig för all min sveda, vetandes, att du icke låter mig vara oskyldig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Är jag nu ogudaktig, hvi hafver jag då sådana onyttiga vedermödo?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Om jag än tvådde mig i snö, och gjorde mina händer rena i källo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Så doppar du mig dock i träck, och min kläder varda mig illa ståndande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Ty han är icke min like, dem jag svara kunde, att vi måtte både komma för rätten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Det är ingen, som oss åtskiljer; som sätter sina hand emellan oss båda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Han tage sitt ris ifrå mig, och låte sin förskräckelse komma ifrå mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Att jag må tala, och icke mer torf frukta för honom; ty jag vet mig oskyldig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Min själ grufvar sig för mitt lif; min klagan vill jag låta fara fort, och tala i mine själs bedröfvelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Och säga till Gud: Fördöm mig icke; låt mig få veta, hvarföre du träter med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Hafver du der lust till, att du brukar öfvervåld; och förkastar mig, hvilken dina händer gjort hafva; och låter de ogudaktigas anslag komma till äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Hafver du ock då köttslig ögon? Eller ser du såsom en menniska ser?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Eller är din tid såsom ens menniskos tid; eller din år såsom ens mans år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Att du frågar efter mina orättfärdighet, och uppsöker mina synd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Ändå du vetst, att jag icke är ogudaktig; ändå det är ingen, som kan fria ifrå dine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Dina händer hafva fliteliga gjort mig, och allansamman beredt mig; och du nedsänker mig så alldeles.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Tänk dock uppå, att du hafver gjort mig af ler, och skall åter låta mig komma till jord igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Hafver du icke molkat mig såsom mjölk, och låtit mig ystas såsom ost?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Du hafver klädt mig uti hud och kött; med ben och senor hafver du sammanfogat mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Lif och välgerning hafver du gjort mig, och ditt uppseende bevarar min anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Och ändå att du fördöljer sådana i ditt hjerta, så vet jag dock likväl, att du kommer det ihåg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Om jag syndar, så märker du det straxt, och låter mina missgerning icke vara ostraffad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Är jag ogudaktig, så är mig ve; är jag rättfärdig, så tör jag likväl icke upplyfta mitt hufvud, som den der full är med föraktelse, och ser mina eländhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Och såsom ett upprest lejon jagar du mig, och handlar åter grufveliga med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Du förnyar din vittne emot mig, och gör dina vrede mycken öfver mig; mig plågar det ena öfver det andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Hvi hafver du låtit mig komma utaf moderlifvet? Ack! att jag dock hade varit förgjord, att intet öga hade sett mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Så vore jag, såsom den der intet hafver varit till, buren ifrå moderlifvet till grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Vill då icke mitt korta lif hafva en ända? Vill du icke låta af mig, att jag något litet måtte vederqvickas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Förr än jag går bort, och kommer intet igen, nämliga i mörkrens och töcknones land?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Det ett land är, hvilkets ljus är tjocka mörkret, och der som ingen skickelighet är; der skenet är såsom en töckna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Då svarade Zophar af Naema, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'När en hafver länge talat, måste han ock icke höra? Eller skall en sqvallrare alltid hafva rätt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Måste man tiga för dig allena, att du försmäder, och ingen skall genhöfta dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Du säger: Min lärdom är ren, och klar är jag för din ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Ack! att Gud talade med dig, och uppläte sina läppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Och tedde dig hvad han ännu hemliga vet; ty han hade ännu väl mer med dig; på det att du måtte veta, att han icke tänker på alla dina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Menar du, att du vetst så mycket som Gud vet; och vill alltså fullkomliga råkat, såsom den Allsmägtige?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Han är högre än himmelen, hvad vill du göra? djupare än helvetet, huru kan du kännan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Längre än jorden, och bredare än hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Om han all ting omvände eller fördolde, eller kastade dem i en hop, ho vill förmena honom det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Han känner de fåfängeliga män, och ser odygdena, och skulle han icke förståt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'En fåfängelig man högmodas, och en född menniska vill vara såsom en ung vildåsne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Hade du ställt ditt hjerta (till Gud), och uppräckt dina händer till honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Hade du långt ifrå dig bortkastat missgerningena, som är i din hand, att ingen orätt hade bott i dine hyddo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Så måtte du upplyft ditt ansigte utan last, och vorde fast ståndandes, och intet fruktandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Så vorde du ock förgätandes uselhetena, och såsom det vattnet, som framlupet är, komme du det icke ihåg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Och din lifstid vorde uppgångandes såsom en middag, och vorde skinandes såsom en morgon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Och du måtte förtrösta dig, att hopp vore på färde; och vorde med rolighet kommandes i grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Och du skulle lägga dig, och ingen skulle rädda dig; och månge skulle knekta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Men de ogudaktigas ögon skola försmäkta, och skola icke undkomma kunna; ty deras hopp skall fela deras själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Då svarade Job, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Ja, I ären rätte männerna; med eder blifver visheten död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Jag hafver så väl ett hjerta som I, och är icke ringare än I; och ho är den som sådana icke vet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Den som af sin nästa begabbad varder, han må åkalla Gud, han varder honom hörandes: Den rättfärdige och fromme måste varda begabbad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Och är dem rikom såsom en lampa, föraktad i deras hjerta, dock tillredd, att de skola deruppå stöta fötterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Röfvarenas hyddor hafva nog, och de rasa dristeliga emot Gud; ändå att Gud hafver gifvit dem det i deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Fråga dock djuren, de skola lärat dig, och foglarna under himmelen, de skola sägat dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Eller tala med jordene, och hon skall lärat dig, och fiskarna i hafvet skola förkunnat dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Ho är den som allt sådant icke vet, att Herrans hand hafver det gjort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Att i hans hand är alles dess själ, som lefvandes är, och alla menniskors kötts ande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Profvar icke örat talet, och munnen smakar maten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Ja, när fäderna är vishet, och förstånd när de gamla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'När honom är vishet och magt, råd och förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Si, när han bryter neder, så hjelper intet bygga; när han någon innelycker, så kan ingen utsläppa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Si, när han förhåller vattnet, så torkas allt, och när han släpper det löst, så omstörter det landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Han är stark, och går det igenom; hans är den som villo far; så ock den som förförer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Han förer de kloka såsom ett rof, och gör domarena galna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Han förlossar utu Konungars tvång, och binder med ett bälte deras länder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Presterna förer han såsom ett rof, och de fasta låter han fela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Han bortvänder de sannfärdigas läppar, och de gamlas seder tager han bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Han utgjuter föraktelse på Förstarna, och gör de mägtigas förbund löst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Han öppnar de mörka grund, och förer mörkret ut i ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Han gör somliga till stort folk, och gör dem åter till intet; han utsprider ett folk, och fördrifver det åter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Han förvänder hjertat i öfverstarna för folket i landena, och låter dem fara ville i vildmarkene, der ingen väg är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Att de famla i mörkret utan ljus, och förvillar dem såsom de druckna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Si, allt detta hafver mitt öga sett, och mitt öra hört, och hafver det förstått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Det I veten, det vet jag ock, och är intet ringare än I;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Dock vill jag tala om den Allsmägtiga, och hafver vilja till att träta med Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Ty I uttyden det falskeliga, och ären alle onyttige läkare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Ack! att I kunden tiga, så vorden I vise.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Hörer dock mitt straff, och akter på sakena, der jag talar om.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Viljen I försvara Gud med orätt; och för honom bruka svek?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Viljen I anse hans person? Viljen I gifva eder i försvar för Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Skall det ock blifva eder väl gångandes, då han skall döma eder? Menen I, att I skolen gäcka honom, såsom man gäckar ena mennisko?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Han varder eder straffandes, om I hemliga ansen personen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Månn han icke förskräcka eder, när han kommer fram? Och hans fruktan varder fallandes öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Edor åminnelse varder liknad vid asko, och edra rygger skola vara såsom en lerhop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Tiger för mig, att jag må tala; det skall icke fela för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Hvi skall jag bita mitt kött med mina tänder, och sätta mina själ i mina händer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Si, han varder mig dock dräpandes, och jag kan icke afbidat; dock vill jag straffa mina vägar för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Han blifver ju min helsa; ty ingen skrymtare kommer för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Hörer mitt tal, och min uttydelse för edor öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Si, jag hafver allaredo sagt domen af; jag vet, att jag varder rättfärdig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Ho är den som vill gå till rätta med mig? Men nu måste jag tiga, och förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Tveggehanda gör mig icke; så vill jag icke gömma mig bort för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Låt dina hand vara långt ifrå mig, och din förskräckelse förskräcke mig icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Kalla mig, och jag vill svara dig; eller jag vill tala, och svara du mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Huru många äro mina missgerningar och synder? Låt mig få veta min öfverträdelse och synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Hvi fördöljer du ditt ansigte, och håller mig för din fienda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Vill du så hård vara emot ett flygande löf; och förfölja ett torrt halmstrå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Ty du tillskrifver mig bedröfvelse, och vill förderfva mig för mins ungdoms synders skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Du hafver satt min fot i en stock, och gifver akt på alla mina stigar, och ser på all min fotspår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Jag, som dock förgås som ett ruttet as, och som ett kläde, det ätet varder af mal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Menniskan, af qvinno född, lefver en liten tid, och är full med orolighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Växer upp som ett blomster, och faller af; flyr bort som en skugge, och blifver icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Och öfver en sådana upplåter du din ögon, och drager mig för dig i rätten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Ho vill finna en renan när dem, der ingen ren är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Han hafver sin förelagda tid; hans månaders tal är när dig; du hafver satt honom ett mål före, derutöfver varder han icke gångandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Gack ifrå honom, att han må hvilas, så länge hans tid kommer, den han såsom en dagakarl bidar efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Ett trä hafver hopp, om det än är afhugget, att det skall åter förvandla sig, och dess telningar vända icke igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Ändock dess rot föråldras i jordene, och stubben dör i mullene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Så grönskas han dock åter af vattnets lukt, och växer lika som han plantad vore.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Men hvar är en menniska, då hon död, förgången och borto är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Såsom ett vatten löper utur en sjö, och såsom en bäck utlöper och förtorkas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Så är en menniska, då hon lägges ned, och varder intet uppståndandes, och varder intet uppvaknandes, så länge himmelen varar, och varder icke uppväckt af sinom sömn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Ack! att du fördolde mig i helvete, och fördolde mig, så länge din vrede afgår, och satte mig ett mål, att du ville tänka uppå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Menar du, att en död menniska skall åter lefva igen? Jag förbidar dagliga, medan jag strider, tilldess min förvandling kommer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Att du ville kalla mig, och jag måtte svara dig; och du ville icke förkasta ditt handaverk:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Ty du hafver allaredo talt min tren; men akta dock icke uppå mina synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Min öfverträdelse hafver du förseglat uti ett knippe, och sammanfattat mina missgerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Förfaller dock ett berg, och förgås, och en klippa går af sitt rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Vattnet sköljer stenarna bort, och floden förer jordena bort; men menniskones hopp är förloradt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Ty du stöter henne platt omkull, så att hon förgås; du förvandlar hennes väsende, och låter henne fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Äro hennes barn i äro, det vet hon icke; eller om de äro föraktelige, det förnimmer hon intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Medan hon är i köttena, måste hon hafva sveda; och medan hennes själ är än när henne, måste hon lida vedermödo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Då svarade Eliphas af Thema, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Skall en vis man tala så i vädret, och uppfylla sin buk med väder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Du straffar med onyttigom ordom, och ditt tal kommer intet till gagns.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Du hafver bortkastat räddhågan, och talar förakteliga för Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Ty så lärer din ondska din mun, och du hafver utvalt ena skalkatungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Din mun skall fördöma dig, och icke jag; dina läppar skola svara dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Äst du den första menniska, som född är? Äst du för all berg aflader?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Hafver du hört Guds hemliga råd? Och är sjelfva visdomen ringare än du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Hvad vetst du, det vi icke vete? Hvad förstår du, det som icke är när oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Gråhårote och gamle äro när oss, som länger hafva lefvat än dine fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Skulle Guds hugsvalelse så ringa aktas för dig? Men du hafver något hemligit stycke när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Hvad tager ditt hjerta före? Hvi ser du så stolt ut?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Hvi sätter ditt sinne sig emot Gud, att du låter sådana ord gå af dinom mun?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Hvad är en menniska, att hon skulle vara ren; och att han skulle vara rättfärdig, som af qvinno född är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Si, ibland hans helga är ingen ostraffelig, och himlarna äro icke rene för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Huru mycket mer menniskan, som är stygg och ond; den der orättfärdighetena dricker såsom vatten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Jag vill visa dig det, hör mig; jag vill förtälja dig, hvad jag sett hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Hvad de vise sagt hafva, och för deras fader icke hafver fördoldt varit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Hvilkom allena landet gifvet är, så att ingen främmande må gå ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'En ogudaktig bäfvar i alla sina lifsdagar, och enom tyrann är hans åratal fördoldt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Hvad han hörer, det förskräcker honom; och ändå att frid är, så hafver han dock den sorg, att han skall förderfvas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Han tror icke, att han skall kunna undfly olyckona, och förmodar sig alltid svärdet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'När han far ut hit och dit efter sin näring, så tycker honom att hans olyckos tid är för handene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Ångest och nöd förskräcka honom, och slå honom ned, såsom en Konung med enom här;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Ty han hafver utsträckt sina hand emot Gud, och emot den Allsmägtiga förstärkt sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Han löper med hufvudet emot honom, och står halsstyf emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Han hafver upphäfvit sig emot honom, och satt sig hårdt emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Men han skall bo i nederslagna städer, der inga hus äro; utan ligga i enom hop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Han skall icke varda rik, och hans gods skall icke förökas; och skall icke utspridas i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Han skall icke undfly olycko; eldslågen skall förtorka hans grenar; och skall varda borttagen af hans muns anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Han är så bedragen, att han icke tror att det skall varda värre med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Han får en ända, när honom obeqvämt är; och hans gren skall icke grönskas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Han varder afhemtad såsom en omogen drufva af vinträt, och såsom ett oljoträ bortfaller sitt blomster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Ty de skrymtares församling skall blifva ensam, och elden skall förtära hans hus, som gåfvor tager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Han anar olycko, och föder vedermödo; och deras buk bär list fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Jag hafver sådana ofta hört; I ären alle arme hugsvalare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'När vilja dock dessa lösa ord hafva en ända? Eller hvad fattas dig, att du så svarar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Jag kunde ock väl tala såsom I; jag ville att edor själ vore i mine själs stad; jag ville ock finna ord emot eder, och så rista mitt hufvud öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Jag ville styrka eder med munnen, och tala af sinnet med mina läppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Men om jag än talar, så skonar min svede mig dock intet; låter jag ock blifvat, så går han dock intet ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Men nu gör han mig vedermödo, och förstörer all min ledamot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Han hafver mig gjort skrynkotan, och vittnar emot mig; och min motståndare hafver sig upp emot mig, och svarar emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Hans vrede sliter mig, och den som är mig vred, biter samman tänderna öfver mig; min motståndare ser hvasst med sin ögon på mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'De gapa med sin mun emot mig, och hafva hånliga slagit mig vid mitt kindben; de hafva tillhopa släckt sin harm på mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Gud hafver öfvergifvit mig dem orättfärdiga, och låtit mig komma i de ogudaktigas händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Jag var rik, men han hafver mig gjort till intet; han hafver tagit mig vid halsen, och sönderslitit mig, och uppsatt mig sig till ett mål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Han hafver kringhvärft mig med sina skyttor; han hafver sargat mina njurar, och intet skonat; han hafver utgjutit min galla på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Han hafver gjort mig ett sår öfver det andra; han hafver öfverfallit mig såsom en kämpe.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Jag hafver sömmat en säck på mina hud, och hafver lagt mitt horn i mull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mitt ansigte är svullet af gråt, och min ögonlock äro vorden mörk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Ändock att ingen orättfärdighet är i mine hand, och min bön är ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Ack jord! öfvertäck icke mitt blod, och mitt rop hafve intet rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Och si nu, mitt vittne är i himmelen, och den mig känner är i höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Mine vänner äro mine begabbare; mitt öga fäller tårar till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Om en man kunde gå till rätta med Gud, såsom menniskors barn med sin nästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Men de förelagda år äro komne; och jag går den vägen bort, den jag aldrig igen kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Min ande är svag, och mine dagar äro afkortade, och grafven är för handene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Ingen är bedragen af mig; likväl måste mitt öga derföre blifva i bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Om du än ville hafva borgen af mig; ho ville lofva för mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Förstånd hafver du för deras hjerta fördolt; derföre skall du icke upphöja dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Han rosar fast bytet för sinom vännom; men hans barnas ögon skola försmäkta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Han hafver satt mig till ett ordspråk ibland folk, och jag måste vara ett under ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Mitt ansigte är mörkt vordet för sorgs skull, och all min ledamot äro såsom en skugge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Öfver detta varda de rättfärdige häpne, och de oskyldige varda sättande sig emot skrymtarena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Den rättfärdige varder behållandes sin väg, och den som rena händer hafver, varder stark blifvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Nu väl, vänder eder alle hit, och kommer; jag varder dock icke finnandes någon visan ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Mine dagar äro förgångne; min anslag äro förskingrade, som mitt hjerta besatt hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Och hafva gjort dag af nattene, och af dagenom natt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Om än jag fast länge bidde, så är dock helvetet mitt hus, och min säng är i mörkrena uppgjord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Förgängelsen kallade jag min fader, och matkarna mina moder, och mina syster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Efter hvad skall jag bida? Och ho aktar mitt hopp?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Neder i helvetet varder det farandes, och varder med mig liggandes i mullene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Då svarade Bildad af Suah, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'När viljen I göra en ända på att tala? Akter dock till; sedan vilje vi tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Hvi varde vi aktade (för dig) såsom oskälig djur, och äre så orene för edor ögon?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Vill du brista för hätskhets skull? Menar du, att för dina skull skall jorden öfvergifven varda, och hälleberget utaf sitt rum försatt varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Och skall dens ogudaktigas ljus utslockna, och gnistan af hans eld skall intet lysa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Ljuset i hans hyddo skall varda till mörker, och hans lykta öfver honom skall utsläckt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Hans håfvors tillgångar skola varda trånga, och hans anslag skall fela honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Ty han är med sina fötter förd i snarona, och vandrar i nätet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'En snara skall hålla hans häl, och de törstige skola få fatt på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Hans snara är lagd på jordene, och hans gildre på hans stig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'På alla sidor skola hastig förfärelse förskräcka honom, så att han icke skall veta hvartut han skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Hunger skall blifva hans håfvor, och uselhet skall blifva honom tillredd, och hänga vid honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Hans huds starkhet skall förtärd varda, och hans starkhet skall dödsens Förste förtära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Hans tröst skall utrotas utu hans hyddo, och de skola drifva honom till förskräckelsens Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Uti hans hyddo skall intet blifva; öfver hans palats skall svafvel strödt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Nedantill skola hans rötter förtorkas, och ofvanuppå afskäras hans säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Hans åminnelse skall förgås i landena, och skall intet namn hafva på gatone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Han skall fördrifven varda ifrå ljusena i mörkret, och af jordene bortkastad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Han skall ingen barn hafva, och ingen barnabarn i sin folk; honom skall ingen qvar blifva i hans slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'De som efter honom komma, skola gifva sig öfver hans dag; och dem, som för honom äro, skall fruktan uppå komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Detta är dens orättfärdigas boning; och detta är rummet till honom, som intet vet af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Hvi plågen I dock mina själ, och döfven mig neder med ordom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'I hafven nu i tio gångor hädat mig, och I skämmen eder intet, att I så omdrifven mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Far jag vill, så far jag mig vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Men I upphäfven eder sannerliga emot mig, och straffen mig till min smälek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Märker dock en gång, att Gud gör mig orätt, och hafver invefvat mig uti sin garn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Si, om jag än ropar öfver öfvervåld, så varder jag dock intet hörd; jag ropar, och här är ingen rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Han hafver igentäppt min väg, att jag icke kan gå der fram; och hafver satt mörker uppå min stig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Han hafver utuklädt mig mina äro, och tagit kronona utaf mitt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Han hafver sönderbråkat mig allt omkring, och låter mig gå; och hafver uppryckt mitt hopp såsom ett trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Hans vrede hafver förgrymmat sig öfver mig, och han håller mig för sin fienda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Hans krigsmän äro tillika komne, och hafva lagt sin väg öfver mig; och hafva lägrat sig allt omkring mina hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Han hafver låtit komma mina bröder långt ifrå mig, och mine kände vänner äro mig främmande vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Mine näste hafva unddragit sig, och mine vänner hafva förgätit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Mitt husfolk och mina tjensteqvinnor hålla mig för främmande; jag är vorden okänd för deras ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Jag ropade min tjenare, och han svarade mig intet; jag måste bedja honom med min egen mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Min hustru stygges vid min anda; jag måste knekta mins lifs barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Förakta också mig de unga barn; om jag uppreser mig, så tala de emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Alle mine trogne vänner hafva styggelse vid mig, och de jag kär hade, hafva vändt sig emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Min ben låda vid min hud och kött; jag kan med hudene icke skyla mina tänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Förbarmer eder öfver mig; förbarmer eder öfver mig, ju I mine vänner; ty Guds hand hafver kommit vid mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Hvi förföljen I mig såväl som Gud, och kunnen af mitt kött icke mätte varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ack! att mitt tal måtte skrifvet varda; ack! att det måtte uti en bok satt varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Med en jernstyl ingrafvet uti bly; och till en evig åminnelse hugget i sten:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Jag vet att min Förlossare lefver; och han skall på sistone uppväcka mig af jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Och jag skall sedan med desso mine hud omklädd varda, och skall i mitt kött få se Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Honom skall jag mig se, och min ögon skola skåda honom, och ingen annan. Mine njurar äro upptärde uti mino sköte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Ty I sägen: Huru skole vi förfölja honom, och finna en sak emot honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Frukter eder för svärdet; förty svärdet är en hämnd öfver missgerningar; på det I veta mågen, att näpst är till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Då svarade Zophar af Naema, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Deruppå måste jag svara, och kan icke bida;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Och vill gerna höra, ho mig det straffa och lasta skall; ty mins förstånds ande skall svara för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Vetst du icke, att alltid så tillgånget är, ifrå den tiden menniskorna på jordene varit hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Att de ogudaktigas berömmelse står icke länge, och skrymtares glädje varar ett ögnablick?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Om hans höjd än räckte upp i himmelen, och hans hufvud komme intill skyn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Så måste han dock på sistone förgås såsom träck; så att de, som se uppå honom, skola säga: Hvar är han?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Såsom en dröm förgår, så skall han ej heller funnen varda; och såsom en syn, den om nattena försvinner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Det öga, som honom sett hafver, det ser honom intet mer; och hans rum skall icke mer se honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Hans barn skola tigga gå, och hans hand skall gifva honom vedermödo till löna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Hans ben skola umgälla hans ungdoms synder; och skola lägga sig i jordene med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Om än ondskan smakar honom väl uti hans mun, skall hon dock fela honom på hans tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Hon skall varda förhållen, och icke tillåten; och skall varda honom förtagen i hans hals.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Hans mat skall förvända sig i hans buk uti ormagalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'De ägodelar, som han uppsvulgit hafver, måste han åter utspy; och Gud skall drifva dem utu hans buk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Han skall suga huggormagalla, och ormatunga skall dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Han skall icke få se de strömmar eller vattubäckar, som med hannog och smör flyta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Han skall arbeta, och intet nyttjat; och hans ägodelar skola varda annars mans, så att han icke skall hafva hugnad utaf dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Förty han hafver undertryckt och förlåtit den fattiga; han hafver rifvit till sig hus, de han intet byggt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Ty hans buk kunde icke full varda; och skall icke igenom sina kosteliga ägodelar undkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Af hans mat skall intet qvart vara; derföre skola hans goda dagar intet varaktige blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Om han än öfverflödar, och hafver nog, skall honom dock likväl ångest ske; alla händers möda skall öfver honom komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Hans buk skall honom en gång full varda; och han skall sända sina vredes grymhet öfver honom; han skall öfver honom regna låta sina strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Han skall fly för jernharnesk, och kopparbågen skall förjaga honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Ett draget svärd skall gå igenom honom, och svärds blänkande, som honom skall bittert varda, skall med förskräckelse gå öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Intet mörker är, som honom skyla må; en eld skall förtära honom, den intet uppblåst är; och den som qvar blifver i hans hyddo, honom skall illa gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Himmelen skall uppenbara hans ondsko, och jorden skall sätta sig upp emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Hans säd i hans huse skall bortförd varda, förspilld uti hans vredes dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Detta är en ogudaktigs menniskos lön när Gudi, och hans ords arf när Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Job svarade och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Hörer dock till min ord, och låter säga eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Hafver tålamod med mig, att jag ock må tala; och görer sedan spott af mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Månn jag handla med en mennisko, att min ande icke skulle härutinnan ångse varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Vänder eder hit till mig; I skolen förundra eder, och måsten lägga handena på munnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'När jag tänker deruppå, så förskräckes jag; och ett bäfvande kommer uppå mitt kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Hvi lefva då de ogudaktige, varda gamle, och växa till i ägodelar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Deras säd är säker omkring dem, och deras afföda är när dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Deras hus hafver frid för räddhåga, och Guds ris är icke öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Deras oxa släpper man till, ock missgår icke; deras ko kalfvar, och är icke ofruktsam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Deras unga barn gå ut såsom en hjord, och deras barn springa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'De fröjda sig med trummor och harpor, och äro glade med pipande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'De varda gamle med göda dagar, och förskräckas som nogast ett ögnablick för helvetet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'De dock säga till Gud: Gack bort ifrån oss; vi vilje intet veta af dina vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Ho är den Allsmägtige, att vi honom tjena skole? Eller hvad kan det båta oss, om vi löpe emot honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Men si, deras ägodelar stå icke uti deras händer; derföre skall de ogudaktigas sinne vara långt ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Huru varder de ogudaktigas lykta utsläckt; och deras förderf kommer öfver dem? Han skall utskifta jämmer i sine vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'De skola varda såsom strå för vädret, och såsom agnar, hvilka stormen bortförer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Gud förvarar hans barnom bedröfvelse; när han skall löna honom, då skall man förnimmat,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Hans ögon skola se hans förderf, och af dens Allsmägtigas vrede skall han dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Ty ho skall hafva behag till hans hus efter honom? Och hans månaders tal skall näppliga halft blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Ho vill lära Gud, den ock dömer de höga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Denne dör frisk och helbregda, rik och säll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Hans mjölkekar äro full med mjölk, och hans ben varda full med märg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Men en annan dör med bedröfvada själ, och hafver aldrig ätit i glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Och de ligga tillhopa med hvarannan i jordene, och matkar öfvertäcka dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Si, jag känner väl edra tankar, och edor vrånga anslag emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Ty I sägen: Hvar är Förstans hus? Och hvar äro hyddorna, der de ogudaktige bodde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Talen I dock derom såsom meniga folket; och veten icke hvad de andras väsende betyder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Ty den onde varder behållen intill förderfvelsens dag, och intill vredenes dag blifver han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Ho vill säga hvad han förtjenar, när man det utvärtes anser? Ho vill vedergälla honom hvad han gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Men han varder bortdragen till grafvena, och man vaktar efter honom i högomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Bäckaslem behagar honom väl, och alla menniskor varda dragna efter honom; och uppå dem, som för honom varit hafva, är intet tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Huru trösten I mig så fåfängt, och edor svar finnas dock orätt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Då svarade Eliphas af Thema, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Menar du att en man kan liknas vid Gud; eller någor är så klok, att han kan likna sig vid honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Menar du att dem Allsmägtiga behagar, att du räknar dig så from? Eller hvad hjelper det honom, om än dine vägar utan brist voro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Menar du han fruktar att straffa dig, och gå till rätta med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ja, din ondska är fast stor, och uppå din orättfärdighet är ingen ände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Du hafver tagit af dinom broder pant utan sak; du hafver dragit kläden af dem nakna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Du hafver icke gifvit dem trötta vatten dricka; du hafver nekat dem hungroga ditt bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Du hafver brukat våld i landena, och bott deruti med stort prål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Enkor hafver du låtit gå ohulpna, och sönderbrutit de faderlösas armar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Derföre äst du omvefvad med snaro, och fruktan hafver dig hasteliga förskräckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Skulle du då icke se mörkret, och vattufloden icke öfvertäcka dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Si, Gud är hög i himmelen, och ser stjernorna uppe i höjdene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Och du säger: Hvad vet Gud? Skulle han kunna döma det i mörkret är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Skyn skyler för honom, och han ser intet; han vandrar i himmelens omgång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Vill du akta på verldenes lopp, der de orättfärdige uti gångne äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Hvilke förgångne äro, förr än tid var, och vattnet hafver bortsköljt deras grund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'De som till Gud sade: Far ifrån oss; hvad skulle den Allsmägtige kunna göra dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Ändock han uppfyllde deras hus med ägodelar; men de ogudaktigas råd vare långt ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'De rättfärdige skola få det se, och glädja sig; och den oskyldige skall bespotta dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Deras väsende skall försvinna, och det qvart är af dem, skall elden förtära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Så förlika dig nu med honom, och haf frid; derutaf skall du hafva mycket godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Hör lagen utaf hans mun, och fatta hans tal uti ditt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Om du omvänder dig till den Allsmägtiga, så skall du uppbyggd varda; och kasta det orätt är långt ifrå dine hyddo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Så skall han gifva guld igen för stoft, och för sten gyldene bäcker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Och du skall hafva guld nog, och silfver skall dig med hopom tillfalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Då skall du hafva din lust i dem Allsmägtiga, och upplyfta ditt anlete till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Du skall bedja honom, och han skall höra dig; och ditt löfte skall du betala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Ehvad du tager dig före, det skall han låta dig väl af gå; och ljus skall skina på dina vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Förty de som sig ödmjuka, dem upphöjer han; och den som sin ögon nederslår, han skall blifva frälst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Och den oskyldige skall hulpen varda; för sina händers renhets skull skall han hulpen varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Mitt tal blifver ännu bedröfvadt; min magt är svag för mitt suckandes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ack! det jag visste, huru jag skulle finna honom, och komma till hans stol;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Och sätta min rätt fram för honom, och uppfylla min mun med straff;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Och förfara hvad ord han mig svara ville, och förnimma hvad han mig sägandes vorde!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Vill han med stora magt träta med mig? Han ställe sig icke så emot mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Utan lägge mig före hvad likt är, så vill jag väl vinna min rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Men går jag rätt framåt, så är han der intet; går jag tillbaka, så varder jag honom intet varse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Är han på venstra sidone, så fattar jag honom intet; förgömmer han sig på högra sidone, så ser jag honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Men han känner väl min väg; han försöke mig, så skall jag funnen varda såsom guld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Ty jag sätter min fot uppå hans fjät, och håller hans väg, och viker intet deraf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Och träder intet ifrå hans läppars bud, och bevarar hans muns ord, mer än jag skyldig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Han är enig; ho vill svara honom? Och han gör allt som han vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Och om han mig än vedergäller hvad jag förtjent hafver, så står ändå för honom mycket tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Derföre är jag förskräckt för honom, och när jag det märker, så fruktar jag mig för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Gud hafver gjort mitt hjerta blödigt, och den Allsmägtige hafver mig förskräckt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Ty mörkret vänder icke åter med mig, och mörker vill för mig intet bortgömdt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Hvi skulle tiderna dem Allsmägtiga icke fördolda vara? Och de honom känna, se intet hans dagar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'De flytta råmärken, de röfva bort hjorden, och föda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'De drifva bort de faderlösas åsna, och taga enkones oxa till pant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'De fattige måste vika för dem, och de torftige i landena måste förgömma sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Si, vilddjuren i öknene gå ut, såsom de pläga, bittida till rofs, att de skola bereda mat för ungarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'De uppskära af den åker, som dem intet tillhörer; och berga den vingård, som de med orätt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'De nakna låta de ligga, och låta dem intet öfvertäckelse i frostena, hvilkom de deras kläder borttagit hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Så att de måste hålla sig i bergskrefvom, när en regnskur af bergen faller neder uppå dem; efter de eljest ingen råd hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'De slita barnet ifrå bröstet, och göra det faderlöst; och göra menniskorna fattiga med pantande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Den nakna låta de gå utan kläder, och dem hungroga borttaga de axen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'De tvinga dem till att göra oljo uppå deras qvarn, och trampa deras pressar, och låta dem likväl törsta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'De göra folket i staden suckande, och dess slagnas själar ropande; och Gud straffar dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Derföre äro de affallne ifrå ljusena, och känna icke dess väg, och vända icke om till dess stigar igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'I lysningene står mördaren upp, och dräper den fattiga och torftiga; och om nattena är han som en tjuf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Horkarlens öga hafver akt på skymningena, och säger: Mig ser intet öga; och han förtäcker sitt anlete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'I mörkrena bryter han sig in i husen; om dagen gömma de sig med hvarannan, och vilja intet veta af ljusena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Ty om än morgonen kommer dem, är det dem såsom ett mörker; förty han förnimmer mörkrens förskräckelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Han far lätteliga åstad såsom uppå ett vatten; hans håfvor varda icke stora i landena, och han brukar intet sin vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Helvetet tager bort dem som synda, såsom hette och torka förtärer snövattnet bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'De barmhertige skola förgäta honom; hans lust varder full med matk; man skall icke mer tänka uppå honom; han skall sönderbruten varda såsom ett ruttet trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Han hafver bedröfvat den ensamma, som intet föder; och enkone hafver han intet godt gjort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Och hafver dragit de mägtiga under sig med sine kraft. När han står, skall han icke viss vara uppå sitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Han gör sig sjelf en trygghet, der han sig uppå förlåter; dock se hans ögon uppå deras handel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'De äro en liten tid upphäfne; men de varda omintet, och undertryckte, och taga en ända såsom all ting; och såsom agnar på axen skola de afslagne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Är det icke så? Nu väl, ho vill straffa mig för lögn, och göra min ord om intet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Då svarade Bildad af Suah, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Är icke herrskap och fruktan när honom, hvilken frid gör ibland sina högsta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Ho kan räkna hans krigsmän? Och öfver hvem uppgår icke hans ljus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Och huru kan en menniska rättfärdig varda för Gudi? Eller huru kan ene qvinnos barn rent vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Si månen skin icke ännu, och stjernorna äro ännu icke rena för hans ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Huru mycket mindre en menniska, den malen, och ens menniskos barn, den matken?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Job svarade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Hvem äst du biståndig? Dem som ingen magt hafver? Hjelper du honom, som ingen starkhet hafver i armenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Hvem gifver du råd? Dem som intet vet? Och du bär fram dina stora gerningar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'För hvem talar du? Och inför hvem går anden ifrå dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'De Reser ängslas under vattnen, och de som när dem bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Helvetet är bart för honom, och förderfvet hafver intet öfvertäckelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Han sträcker ut nordet på ingo, och hänger jordena uppå intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Vattnet samkar han i sina skyar, och skyarna remna icke derunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Han håller sin stol, och utbreder sin sky derföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Han hafver satt ett mål om vattnet, intilldess ljus och mörker blifver ändadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Himmelens stodar skälfva, och gifva sig för hans näpst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'För hans kraft varder hafvet hasteliga stormande, och för hans klokhet stillar sig hafsens höghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'På himmelen varder det klart igenom hans väder, och hans hand drifver bort hvalfisken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Si, alltså går det till med hans gerningar; men hvad besynnerligit hafve vi derutinnan hört? Ho kan förstå hans magts dunder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Och Job höll talet fram; hof upp sitt ordspråk, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Så sant som Gud lefver, den mig min rätt förvägrar, och den Allsmägtige, som mina själ bedröfvar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Så länge min ande i mig är, och andedrägten af Gudi i mino näso är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Mine läppar skola intet orätt tala, och min tunga skall intet bedrägeri för händer hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Bort det ifrå mig, att jag skulle gifva eder rätt; intilldess min ände kommer, skall jag icke vika ifrå mine fromhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Ifrå mine rättfärdighet, som jag håller vill jag icke gå; mitt samvet gnager mig intet för alla mina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Men min fiende varder funnen ogudaktig, och min motståndare orättvis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Ty hvad är ens skrymtares hopp, att han så girig är; och Gud rycker dock hans själ bort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Menar du, att Gud skall höra hans röst, när ångest kommer honom uppå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Huru kan han hafva lust till den Allsmägtiga, och något åkalla honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Jag vill lära eder om Guds hand, och hvad för dem Allsmäktiga gäller, vill jag icke dölja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Si, I hållen eder alle, att I ären vise; hvi gifven I då sådana onyttig ting före?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Detta är en ogudaktig menniskos lön när Gudi, och de tyranners arf, som de af dem Allsmägtiga få skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Om han får mång barn, så skola de höra svärdet till; och hans afföda skall icke af bröd mätt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Hans återlefde skola i dödenom begrafne varda, och hans enkor skola intet gråta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Om han samkar penningar tillhopa såsom stoft, och tillreder sig kläder såsom ler,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Så skall han väl tillredat; men den rättfärdige skall kläda sig deruti, och den oskyldige skall utskifta penningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Han bygger sitt hus såsom en spindel, såsom en väktare gör sig ett skjul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'När den rike nedläggs, skall han intet få med sig; han skall upplåta sin ögon, och finna intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Honom skall öfverfalla förskräckelse såsom vatten; om nattena skall stormväder taga honom bort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Östanväder skall föra honom bort, att han skall förgås; och oväder skall drifva honom af hans rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Detta skall han låta komma öfver honom, och skall intet skona honom; allt skall det gå honom ifrå hända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Man skall klappa händer tillhopa öfver honom, och hvissla öfver honom, der han varit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Silfret hafver sin gång, och guldet sitt rum, der det verkas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Jern tager man utaf jordene, och utaf stenar smälter man koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'På mörkret varder ju en tid ände, och finner ju någor på sistone det fördolda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Det springer ut en sådana bäck, att de, som bo deromkring, icke kunna gå deröfver till fots; han varder menniskomen allt för djup, och flyter sin kos.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Man får ock eld nedan utu jordene; der dock ofvantill bröd växer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Man finner saphir på somlig rum, och jordklimpar, der guld är uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Den stigen hafver ingen fogel kunnat, och intet gamsöga sett;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'De stolta barn hafva icke trampat honom, och intet lejon gångit deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Bär man också handena på stenen, och grafver bergen omkull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Man grafver bäcker utu hällebergen, och allt det kosteligit är, ser ögat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Man förtager strömmom vattnet, och hafver fram i ljuset det derutinnan fördoldt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Huru vill man nu vishet finna, och hvar är rummet till förståndighet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Ingen vet hvar hon ligger; och varder icke funnen i de lefvandes lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Afgrundet säger: Hon är icke i mig; och hafvet säger: När mig är hon icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Man kan icke gifva der penningar före, ej heller silfver uppväga, till att betala henne med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Hon räknas icke vid Ophiriskt guld, eller vid kostelig onich och saphir;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Guld och diamant kan icke liknas dervid, ej heller kan hon tillbytas för gyldene klenodier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Ramoth och Gabis aktar man intet; hon är högre aktad än perlor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Topats af Ethiopien varder icke lika skattad emot henne, och det renaste guld gäller icke deremot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Hvadan kommer då visheten? Och hvar är rummet till förståndigheten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Hon är fördold för allas lefvandes ögon, och öfverskyld för foglarna under himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Fördömelsen och döden säga: Vi hafve med vår öron hört hennes rykte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Gud vet vägen dertill, och känner hennes rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Förty han ser jordenes ända, och skådar allt det under himmelen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Så att han gifver vädrena sina vigt, och vattnena sitt matt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Då han satte regnena ett mål före, och tordönenom och ljungeldenom sin väg,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Då såg han henne, och räknade henne; tillredde henne, och fann henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Och sade till menniskona: Si, Herrans fruktan är vishet; och fly det onda är förståndighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Och Job hof åter upp sitt ordspråk, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Ack! att jag vore såsom uti de förra månader, uti de dagar då Gud bevarade mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Då hans lykta sken öfver mitt hufvud, och jag i mörkrena gick vid hans ljus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Såsom jag var i min ungdoms tid, då Guds hemlighet var öfver mina hyddo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Då den Allsmägtige ännu med mig var, och mine tjenare allt omkring mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Då jag tvådde min väg uti smör, och hälleberget utgöt mig oljoflodar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Då jag utgick till stadsporten, och lät bereda mig mitt säte på gatone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Då mig ynglingar sågo, och undstungo sig, och de gamle uppstodo för mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Då de öfverste igen vände att tala, och lade sina hand på sin mun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Då Förstarnas röst gömde sig undan, och deras tunga lådde vid deras gom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Ty hvilkens öra mig hörde, den prisade mig saligan; och hvilkens öga mig såg, den vittnade om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Förty jag halp den fattiga, som ropade, och den faderlösa, som ingen hjelpare hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Dens välsignelse, som förgås skulle, kom öfver mig; och jag tröstade enkones hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Rättfärdighet var min klädebonad, den iklädde jag såsom en kjortel; och min dom var min skrud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Jag var dens blindas öga, och dens haltas fot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Jag var de fattigas fader, och hvilken sak jag icke visste, den utfrågade jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Jag sönderslog dens orättfärdigas oxlatänder, och tog rofvet utu hans tänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Jag tänkte: Jag vill dö uti mitt näste, och göra mina dagar många såsom sand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Min säd gick upp af vätsko, och dagg blef öfver min årsväxt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Min härlighet förnyade sig för mig, och min båge förvandlade sig i mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'De hörde mig, och tigde; och vaktade uppå mitt råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Efter min ord talade ingen mer, och mitt tal dröp på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'De vaktade på mig såsom på regn, och uppgapade med munnen såsom efter aftonregn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Om jag log till dem, förläto de sig intet deruppå; och torde intet bedröfva mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'När jag ville komma till deras handlingar, så måste jag sitta främst; och bodde såsom en Konung ibland krigsfolk, då jag hugsvalade dem som sorgfulle voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Nu le de att mig, som yngre äro än jag; hvilkas fäder jag icke ville vårdat sätta ibland mins hjords hundar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Hvilkas förmågo jag för intet höll; de icke till ålders komma kunde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'De som för hungers skull och bekymmer ensamme flydde in i öknena, nyliga förderfvade och elände vordne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'De som nesslo uppryckte omkring buskarna, och enerötter var deras mat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Och då de dem uppryckte, fröjdades de deröfver såsom en tjuf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Vid de stygga bäcker bodde de, uti jordkulor och bergskrefvor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Emellan buskar ropade de, och ibland tistlar församlade de sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'De lösa och föraktada menniskors barn, de som ringast voro i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Nu är jag deras strängaspel vorden, och måste vara deras nymäre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'De styggas vid mig, och draga sig långt ifrå mig; och spara icke att spotta för mitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Ty han hafver spänt mina seno, och hafver ödmjukat mig; och lagt ett betsel i munnen uppå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'På högra sidone, der jag grönskades, satte de sig upp emot mig; och stötte mina fötter bort, och gjorde en väg öfver mig, till att förderfva mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'De hafva förspillt mina stigar; det var dem så lätt att göra mig skada, att de ingen hjelp behöfde dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'De äro inkomne såsom genom stora refvor, och äro utan ordan infallne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Förskräckelse hafver vändt sig emot mig, och såsom ett väder förföljt mina frihet, och såsom en löpande sky mina helso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Men nu utgjuter sig min själ öfver mig, och mine sorgedagar hafva fattat mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Om nattena varda min ben allestäds igenomborrad; och de, som mig jaga, läggar sig intet till att sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Genom stora kraft varder jag margalunda klädd; och de begjorda mig dermed, såsom igenom min kjortels hufvudsmog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Man hafver trampat mig i träck, och aktat mig lika emot stoft och asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Ropar jag till dig, så svarar du mig intet; går jag fram, så aktar du mig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Du äst mig förvänd till en grufveligan, och drager ditt hat till mig med dine hands starkhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Du lyfter mig upp, och låter mig fara uppå vädrena, och försmälter mig krafteliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Ty jag vet, du öfverantvardar mig dödenom; der är det hus, som allom lefvandom förelagdt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Dock räcker han icke sina hand ut in i benhuset, och de varda ej ropande öfver sitt förderf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Jag gret ju uti den hårda tiden, och min själ varkunnade sig öfver den fattiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Jag vänte det goda, och det onda kom; jag vänte ljuset, och mörkret kom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Mina inelfvor sjuda, och hålla intet upp; mig är uppåkommen sorgetid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Jag går bedröfvad, ändock jag på ingen vredgas; jag står upp i menighetene och ropar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Jag är drakars broder, och strutsfoglars stallbroder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Min hud öfver mig är svart vorden, och min ben är förtorkad af hetta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Min harpa är vorden en klagan, och min pipa en gråt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Jag hafver gjort ett förbund med min ögon, att jag intet skall sköta efter någon jungfru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Men hvad gifver mig Gud till löna ofvan efter, och hvad arfvedel den Allsmägtige af höjdene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Skulle icke heldre den orättfärdige hafva den vedermödona, och en ogerningsman sådana jämmer lida?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Ser han icke mina vägar, och räknar alla mina gånger?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Hafver jag vandrat i fåfängelighet, eller min fot skyndat sig till bedrägeri?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Man väge mig på en rätt våg, så skall Gud förnimma min fromhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Hafver min gång vikit utaf vägen, och mitt hjerta efterföljt min ögon, och något lådat vid mina händer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Så låt mig så, och en annar äte det; och min ätt varde utrotad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Hafver mitt hjerta låtit sig draga till qvinno, och hafver vaktat vid mins nästas dörr,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Så varde min hustru af enom androm skämd, och andre besofve henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Ty det är en last och en missgerning för domarena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Ty det vore en eld, som förtärer intill förderf, och all min tilldrägt utrotade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Hafver jag föraktat, mins tjenares eller mine tjenarinnos rätt, då de med mig trätte?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Hvad ville jag göra, när Gud reser sig upp? Och hvad ville jag svara, när han hemsöker?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Hafver ock icke han gjort honom, den mig i moderlifvet gjorde; och hafver ju så väl tillredt honom i lifvena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Hafver jag dem torftigom förnekat hvad de begärde, och låtit enkones ögon försmäkta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Hafver jag ätit min beta allena, att den faderlöse icke också hafver ätit deraf?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Ty ifrå minom ungdom hafver jag hållit mig såsom en fader, och allt ifrå mitt moderlif hafver jag gerna hugsvalat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Hafver jag någon sett förgås, derföre att han icke hade kläder; och låtit den fattiga gå oskyldan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Hafva icke hans sidor välsignat mig, då han af min lambs skinn värmad vardt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Hafver jag låtit komma mina hand vid den faderlösa, ändock jag såg mig i portenom magt hafva,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Så falle mina skuldror ifrå mina axlar, och min arm gånge sönder ifrå läggenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Ty jag fruktade Gud såsom en olycko öfver mig, och kunde hans tunga icke bära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Hafver jag satt guld till min tröst, och sagt till guldklimpen: Du äst mitt hopp?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Hafver jag gladt mig, att jag myckna ägodelar hade, och min hand allahanda förvärfvat hade?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Hafver jag sett på ljuset, då det klarliga sken, och på månan, då han i fyllo gick?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Hafver mitt hjerta hemliga låtit sig tälja i det sinnet, att min mun skulle kyssa mina hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Hvilket ock en missgerning är för domarena; förty dermed hade jag nekat Gud i höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Hafver jag gladt mig, när minom fiende gick illa, och upphäfvit mig, att olycka råkade uppå honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Ty jag lät min mun icke synda, så att han önskade hans själ ena banno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Hafva icke de män i mine hyddo måst säga: Ack! att vi icke måtte af hans kött mättade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Ute måste den främmande icke blifva; utan dem vägfarande lät jag mina dörr upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Hafver jag såsom en menniska skylt mina skalkhet, att jag skulle hemliga fördölja min missgerning?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Hafver jag grufvat mig för stora hopen; eller hafver frändernas föraktelse mig förskräckt? Jag blef stilla, och gick icke ut genom dörrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Ho gifver mig en förhörare, att den Allsmägtige må höra mitt begär? Att någor måtte skrifva en bok om mine sak;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Så ville jag taga henne uppå mine axlar, och ombinda mig henne såsom en krono.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Jag ville förkunna talet på mina gånger, och såsom en Förste ville jag det frambära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Om min jord ropar emot mig, och dess fårar alle tillika gråta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Hafver jag dess frukt obetalad ätit, och gjort åkermännernas lefverne tungt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Så växe mig tistel för hvete, och törne för bjugg. En ända hafva Jobs ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Då vände de tre män åter att svara Job; efter han höll sig rättfärdigan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Men Elihu, Baracheels son, af Bus af Kams slägte, vardt vreder uppå Job, att han höll sina själ rättfärdigare än Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Ock vardt han vred uppå de tre hans vänner, att de intet svar funno, och dock fördömde Job.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Ty Elihu hade bidt, så länge de hade talat med Job, efter de voro äldre än han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Derföre, då, han såg, att intet svar var i de tre mäns mun, vardt han vred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Och så svarade Elihu, Baracheels son, af Bus, och sade: Jag är ung, och I ären gamle, derföre hafver jag skytt, och fruktat bevisa min konst på eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Jag tänkte: Låt åren tala, och åldren bevisa vishet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Men anden är i menniskone, och dens Allsmägtigas Ande gör henne förståndiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Mästarena äro icke de visaste, och de gamle förstå icke hvad rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Derföre vill jag ock tala; hör härtill, jag vill ock bevisa mina konst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Si, jag hafver bidt, medan I talat hafven; jag hafver gifvit akt på edart förstånd, tilldess I hafven gjort en ända på edart tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Och jag hafver haft akt uppå eder, och si, ingen är ibland eder, som Job straffa, eller till hans ord svara kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'I mågen tilläfventyrs säga: Vi hafve drabbat på vishetena, att Gud hafver bortkastat honom, och ingen annar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Det talet gör mig icke fyllest; jag vill intet svara honom, efter som I taladen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Ack! de uppgifvas, och kunna intet mer svara; de kunna intet mer tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Efter jag nu bidt hafver, och de kunna intet tala; förty de stå tyste, och svara intet mer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Vill jag dock svara min part, och bevisa mina konst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Ty jag är så full med ordom, att min ande ängslas i minom buk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Si, min buk är såsom must, dem tilltäppt är, hvilken ny fat sönderslår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Jag måste tala, att jag må få andas; jag måste upplycka mina läppar och svara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Jag vill på ingens person se, och ingo mennisko till vilja tala;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Förty jag vet icke, om jag så gjorde, om min skapare innan en kort tid mig borttagandes vorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Hör dock, Job, mitt tal, och gif akt på all min ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Si, jag låter min mun upp, och min tunga skall tala i minom mun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Mitt hjerta skall tala rätt, och mine läppar skola säga ett rent förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Guds Ande hafver gjort mig, och dens Allsmägtigas Ande hafver gifvit mig lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Kan du, så svara mig; kom fram jemte mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Si, jag hörer Gudi till, såsom du säger, och utaf jord är jag också gjord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Dock du torf icke förfäras för mig, och min hand skall icke vara dig för svår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Du hafver talat för min öron; dins ords röst måste jag höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Jag är ren och utan all last, oskyldig, och hafver ingen synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Si, han hafver funnit en sak emot mig, derföre håller han mig för sin fienda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Han hafver satt min fot i stocken, och förvarat alla mina vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Si, rätt derutaf besluter jag emot dig, att du icke äst rättfärdig; ty Gud är mer än en menniska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Hvi vill du träta med honom, att han icke gör dig räkenskap på allt det han gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Om Gud en gång något befaller, skall man då icke först se derefter, om det rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Uti synenes dröm om nattene, när sömnen faller uppå menniskorna, när de sofva på sängene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Då öppnar han menniskors öra; och förskräcker dem, och näpser dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'På det han skall vända menniskona ifrån olycko, och förvara henne för öfvermod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Han skonar hennes själ för förderf, och hans lif, att det icke skall falla i svärdet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Och näpser honom med sveda uppå hans säng, och all hans ben mägteliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Och far så med honom, att honom vämjes vid maten, och hans sjal icke hafver lust till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Hans kött försvinner, så att man intet ser det, och hans ben förkrossas, så att man icke gerna ser dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Att hans själ nalkas till förderf, och hans lif till de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Om nu en Ängel, en af tusende, trädde fram för honom, till att förkunna menniskone Guds rättfärdighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Då skall han förbarma sig öfver honom, och säga: Han skall förlossad varda, att han icke skall fara neder i förderfvet; ty jag hafver funnit en försoning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Hans kött komme sig till igen, såsom i ungdomen, och låt honom åter varda ung igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Han skall bedja Gud, den skall bevisa honom nåder; han skall se sitt ansigte med glädje, och skall vedergälla menniskone hennes rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Han skall för menniskomen bekänna, och säga: Jag hafver syndat och illa gjort, och mig är ännu för litet skedt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Han hafver förlossat mina själ, att hon icke skulle komma i förderf; utan mitt lif skulle få se ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Si, allt detta gör Gud två eller tre gångor med hvarjom och enom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'På det han skall hemta hans själ igen utu förderfvet; och upplyser honom med de lefvandes ljuse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Gif akt häruppå, Job, och hör härtill, och tig, att jag må tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Men hafver du något att tala, så svara mig. Säg, äst du rättfärdig; jag vill gerna hörat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Hafver du ock intet, så hör mig, och tig; jag vill lära dig visdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Och Elihu svarade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Hörer, I vise, mitt tal, och I förståndige, akter på mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Ty örat pröfvar talet, och munnen smakar maten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Låt oss utvälja en dom, att vi måge emellan oss känna hvad godt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Ty Job hafver sagt: Jag är rättfärdig, och Gud hafver förvägrat mig min rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Jag måste ljuga, om jag än rätt hade; jag varder plågad af min skott, om jag än det intet förskyllat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Ho är en sådana, som Job; som gabberi dricker såsom vatten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'Och går på vägenom med illgerningsmän, så att han vandrar med ogudaktiga män?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Ty han hafver sagt: Om än någor rätt färdig vore, så gäller han dock intet när Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Hörer mig, I vise män: Bort det, att Gud skulle vara ogudaktig, och den Allsmägtige orättvis;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Utan han lönar menniskone, efter som hon hafver förtjent; och drabbar uppå hvar och en efter hans gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Utan tvifvel, Gud fördömer ingen med orätt, och den Allsmägtige böjer icke rätten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Ho hafver skickat det uppå jordene är, och ho hafver satt hela jordenes krets?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Om han det toge sig före, kunde han allas anda och lif till sig samla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Allt kött vorde tillhopa förgåendes, och menniskan vorde åter till asko igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Hafver du förstånd, så hör detta, och gif akt på mins tals röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Skulle någon fördenskull tvinga rätten, att han hatar honom? Och derföre att du stolt äst, skulle du fördenskull fördöma den rättfärdiga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Skulle någor säga till Konungen: Du Belial? och till Förstarna: I ogudaktige?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Den dock icke ser på Förstarnas person, och känner icke mer den härliga än den fattiga; förty de äro alle hans handaverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Med hast måste menniskorna dö, och om midnattstid förskräckas och förgås; de mägtige varda kraftlöse borttagne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Ty hans ögon se uppå hvars och ens vägar, och han skådar alla deras gånger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Intet mörker eller skygd är, att ogerningsmän måga sig der fördölja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Ty det varder ingom tillstadt, att han kommer med Gud till rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Han förgör många stolta, som icke stå till att räkna; och sätter andra i deras stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Derföre, att han känner deras gerningar; och omstörter dem om nattena, att de skola sönderkrossade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Han kastar de ogudaktiga uti en hop, der man gerna ser det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Derföre, att de icke hafva följt honom efter, och förstodo ingen af hans vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Att de fattigas rop skulle komma inför honom, och han dens eländas rop höra måtte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Om han frid gifver, ho vill fördöma? Och om han förskyler anletet, ho vill se uppå honom ibland folken och menniskorna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Så låter han nu en skrymtare regera, till att plåga folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'För Guds skull vill jag lida talet, och icke förmenat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Hafver jag icke drabbat rätt, lär du mig bättre; hafver jag orätt handlat, vill jag icke göra så mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Man vänter nu svar af dig; ty du förkastar all ting, och du hafver begynt det, och icke jag. Vetst du nu något, så tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Visa män låter jag väl tala, och en vis man hörer mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Men Job talar ovisliga, och hans ord äro icke vis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Min Fader, låt Job försökt varda allt intill ändan, derföre att han vänder sig till orättfärdiga menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Han hafver utöfver sina synd ännu dertill hädat; derföre låt honom inför oss slagen varda; och träte sedan med sinom ordom inför Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Och Elihu svarade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Håller du det för rätt, att du säger: Jag är rättvisare än Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Ty du säger: Ho blifver något räknad för dig? Hvad hjelper det, om jag håller mig ifrå synd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Jag vill svara dig med ordom, och dinom vännom med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Se upp till himmelen, och skåda; och se uppå skyarna, att de äro dig för höge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Om du syndar, hvad kan du skaffa emot honom? Och om din ondska är stor, hvad kan du göra honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Och om du äst rättfärdig, hvad kan du gifva honom, eller hvad kan han taga af dina händer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Ene mennisko, såsom du äst, må din ondska något göra, och ene menniskos barne din rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'De samme måga ropa, när dem mycket öfvervåld sker, och ropa öfver de väldigas arm;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'De der intet säga: Hvar är Gud, min skapare, som sånger gör om nattena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Den oss gör lärdare än djuren på jordene, och visare än foglarna under himmelen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Men de skola der ock ropa öfver de ondas högmod, och han skall intet höra dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Ty Gud hörer icke fåfängelighetena, och den Allsmägtige ser der intet till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Nu säger du; Du ser honom intet; men en dom är för honom, allenast förbida honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Om hans vrede icke så hastigt hemsöker, och intet sköter, att der så många laster äro,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Derföre hafver Job fåfängt öppnat sin mun; och gifver onyttig ord före med oförnuft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihu talade ytterligare, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Töfva ännu litet, jag vill visa dig det; ty jag hafver ännu på Guds vägnar något säga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Jag vill hemta mitt förstånd fjerranefter, och bevisa, att min skapare är rättvis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Mitt tal skall utan tvifvel intet falskt vara; mitt förstånd skall utan fel vara för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Si, Gud förkastar icke de mägtiga; ty han är ock mägtig af hjertans kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Den ogudaktiga bevarar han icke; utan hjelper den arma till rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Han vänder icke sin ögon ifrå den rättfärdiga; och Konungarna låter han sitta på stolenom i evig tid, att de höge blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Och om fångar ligga i bojor, och bundne med tåg jämmerliga,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Så gifver han dem tillkänna hvad de gjort hafva; och deras odygd, att de hafva brukat våld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Och öppnar dem örat till tuktan, och säger dem, att de skola omvända sig ifrå det orätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Om de höra och tjena honom, så skola de i godom dagom gamle varda, och lefva med lust.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Höra de icke, så skola de falla för svärd, och förgås förr än de varda det varse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'De skrymtare, när vreden kommer uppå dem, ropa de intet, när de fångne ligga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Så skall deras själ dö med qval, och deras lif ibland bolare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Men den arma skall han, hjelpa utu hans armod, och öppnar dem arma örat i bedröfvelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Han skall taga dig utur ångestens vida mun, den ingen botten hafver, och ditt bord skall hafva ro, uppfyldt med allt godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Men du gör de ogudaktigas sak godan, så att deras sak och rätt blifver behållen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Se till, om icke otålighet hafver rört dig i qvalena; eller stora gåfvor icke hafva böjt dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Menar du, att din väldighet skall bestå kunna utan bedröfvelse; eller eljest någon starkhet eller förmåga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Du torf icke begära nattena till att öfverfalla menniskorna i deras rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Vakta dig, och vänd dig icke till det orätt är, såsom du för jämmers skull dig företagit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Si, Gud är för hög i sine kraft; ho är en lagförare såsom han är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Ho vill hemsöka öfver honom hans väg? Och ho vill säga till honom: Du gör orätt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Tänk uppå, att du intet vetst hans verk, såsom menniskorna sjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Ty alla menniskor se det, menniskorna se det fjerran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Si, Gud är stor och okänd; hans åratal kan ingen utfråga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Han gör vattnet till små droppar, och drifver sina skyar samman till regn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Så att skyarna flyta, och drypa fast uppå menniskorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Då han tager sig före att skingra sina skyar, och tager sitt täckelse bort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Si, så utbreder han sitt ljus öfver dem, och öfvertäcker hafvet, dädan de komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Ty dermed dömer han folket, och gifver dem mat tillfyllest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Han håller händerna före, och betäcker ljuset, och bjuder thy, att det skall igenkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Om det samma förkunnar hans herde, och hans boskap om skyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Deraf förskräcker sig mitt hjerta, och bäfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Hörer hans rösts skall, och det ljud som utaf hans mun går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Han ser under alla himlar, och hans ljus skin uppå jordenes ändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Efter honom bullrar dundret, han dundrar med ett stort skall; och när hans dundrande hördt varder, kan man intet förhålla det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Gud dundrar med sitt dunder grufveliga, och gör stor ting, och varder dock intet känd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Han talar till snön, så är han straxt här på jordene, och till regnskuren, så är regnskuren der med magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Man förgömmer sig ibland alla menniskor, att folket skall känna hans verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Vilddjuret kryper uti skjul, och blifver i sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Sunnanefter kommer väder, och nordanefter köld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Af Guds anda kommer frost, och stort vatten, då han utgjuter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'De tjocke skyar skilja sig, att klart skall varda, och igenom molnet utbrister hans ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Han vänder skyarna hvart han vill, att de skola göra allt det han bjuder dem på jordenes krets;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Ehvad det är öfver en slägt, eller öfver ett land, då man finner honom barmhertigan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Akta deruppå, Job; statt och förnim Guds under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Vetst du, när Gud låter detta komma öfver dem; och när han låter sina skyars ljus utgå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Vetst du, huru skyarna utsprida sig; hvilka under de fullkomlige veta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Att din kläder varm äro, då landet är stilla af sunnanväder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Ja, du utbreder icke skyarna med honom, hvilke starke äro, och anseende såsom en grund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Låt oss höra hvad vi skole säga honom; förty vi räcke icke intill honom för mörker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Ho skall förtälja honom hvad jag talar? Om någor talar, han varder uppsluken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Nu ser man icke ljuset, som inom skyn lyser; men när vädret blås, göres det klart.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Ifrå nordan kommer guld, den förskräckelige Gudi till lof;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Men den Allsmägtiga kunna de intet finna, den så stor är i magtene; ty han måste ingen räkenskap göra af sinom rätt och rättfärdigom sakom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Derföre måste menniskorna frukta honom, och han fruktar inga visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Och Herren svarade Job uti ett väder, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Hvilken är den som i sina tankar så fela vill, och talar så med oförnuft?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Gjorda dina länder såsom en man; jag vill fråga dig: Säg, äst du så klok?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Hvar vast du, då jag grundade jordena? Säg mig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Vetst du, ho henne hafver satt sitt mått; eller ho hafver dragit något snöre öfver henne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Eller hvaruppå står hennes fotafäste; eller ho hafver henne en hörnsten lagt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Då morgonstjernorna tillsammans lofvade mig, och all Guds barn fröjdade sig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Ho hafver tillslutit hafvet med sina dörrar, då det utbrast såsom utu moderlifve;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Då jag klädde det med skyar, och invefvade det i töckno, såsom i lindakläde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Då jag förtog thy dess flod med minom dam, och satte thy bom och dörrar före;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'Och sade: Allt härintill skall du komma, och icke vidare; här skola dina stolta böljor sätta sig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Hafver du i dinom tid budit morgonen, och vist morgonrodnanom sitt rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Att jordenes ändar måga fattade varda, och de ogudaktige der utskuddade blifva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Inseglet skall sig förvandla såsom ler, så att de skola blifva såsom ett kläde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Och dem ogudaktigom skall deras ljus förtaget varda, och de högfärdigas arm skall sönderbruten varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Hafver du kommit uti hafsens grund, och vandrat uti djupsens fjät?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Hafva dödsens dörrar någon tid upplåtit sig för dig; eller hafver du sett dörrarna åt mörkret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Hafver du förnummit huru bred jorden är? Låt höra, vetst du allt detta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Hvilken är vägen dit, der ljuset bor, och hvilket är mörkrens rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Att du måtte aftaga dess gränso, och märka stigen till dess hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Visste du, att du skulle på den tiden född varda, och huru många dina dagar blifva skulle?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Hafver du der varit, dädan snön kommer; eller hafver du sett, hvadan haglet kommer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Hvilka jag bevarat hafver intill bedröfvelsens dag, intill stridenes och örligets dag?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Genom hvilken vägen delar sig ljuset, och östanväder uppkommer på jordena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Ho hafver utskift regnskurene sitt lopp, och ljungeldenom och dundrena vägen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Så att det regnar uppå jordena, der ingen är, i öknene, der ingen menniska är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Att det skall uppfylla ödemarken och öknen, och kommer gräset till att växa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Ho är regnets fader? Ho hafver födt daggenes droppar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Utu hvars lif är isen utgången; och ho hafver födt rimfrostet under himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Att vattnet skulle fördoldt varda såsom under stenar, och djupet blifver ofvanuppå ståndandes?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Kan du binda tillsammans sjustjärnornas band, eller upplösa Orions band?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Kan du hemta morgonstjernorna fram i sin tid, eller föra vagnen på himmelen öfver sin barn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Vetst du, huru himmelen skall regeras; eller kan du sätta ett herradöme öfver honom på jordene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Kan du föra dina dunder högt uppe i skynom, att vattnens myckenhet dig öfvertäcker?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Kan du utsläppa ljungeldar, att de fara åstad, och säga: Här äre vi?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Ho hafver satt visdomen uti det fördolda? Ho hafver gifvit tankomen förstånd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Ho är så vis, att han skyarna räkna kan? Ho kan förstoppa vattuläglarna i himmelen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'När stoftet är vått vordet, så att det tillhopalöper, och klimparne låda tillsammans?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Kan du gifva lejinnone hennes rof i jagtene; och mätta de unga lejonen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Så att de lägga sig uti sitt rum, och stilla ligga i kulone på vakt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Ho reder korpenom mat, när hans ungar ropa till Gud, och veta icke hvar deras mat är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Kan du sätta tiden, när stengetterna skola kidla på bergen? Eller hafver du märkt, när hindarna gå hafvande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Hafver du räknat deras månader, när de fulle varda; eller vetst du tiden, när de skola föda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'De böja sig, när de föda, och rifva sig, och låta ut sina ungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Deras ungar varda fete, och växa ute; de gå ut, och komma intet till dem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Ho hafver låtit vildåsnan så fri gå? Ho hafver vildåsnans band upplöst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Hvilkom jag markena till hus gifvit hafver, och öknena till boning?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Han gör lek af stadsbullret; plågarenas trug hörer han intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Han ser efter bergen, der hans bet är, och söker hvar grönt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Menar du, att enhörningen skall tjena dig, och skall blifva vid dina krubbo?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Kan du binda honom oket uppå i dina fårar, så att han efter dig plog drager i dalomen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Kan du förlåta dig på honom, deraf att han mycket förmår, och låta honom för dig arbeta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Kan du betro honom, att han drager dig dina säd hem igen, och församlar henne i dina lado?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Påfoglens vingar äro skönare än storkens, eller strutsfoglens vingar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Som sin ägg lägger i jordena, och låter heta jordena utkläcka dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Han förgäter, att de måga varda trampade, och något vilddjur sönderslår dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Han är så hård emot sina ungar, likasom de icke voro hans; han aktar icke, att han arbetar fåfängt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Ty Gud hafver förtagit honom visdom, och hafver intet förstånd gifvit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'På den tiden han reser sig, upphöjer han sig, och bespottar både häst och man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Kan du gifva hästenom kraft; eller kan du pryda hans hals med hans gnäggande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Kan du förfara honom såsom gräshoppor? Hvad förfärligit är, det är hans nos pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Han rifver jordena, och är frimodig i sin starkhet; och drager ut emot den väpnada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Han bespottar räddhågan, och förfäras intet; och flyr icke för svärd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Det ännu kogret emot honom skallrade, och glimmade både glafven och sköld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Han skälfver och rasar, och trampar jordena; och tror intet, att trummeten lyder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'När trummeten fast klingar, säger han huj; och känner lukten af stridene lång väg, Förstarnas rop och fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Flyger höken genom ditt förstånd, och utbreder sina vingar söderut?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Flyger örnen så högt af din befallning, att han gör sitt näste i höjdene? I bergklippon bor han, och blifver i bergskrefvom, och i fast rum. Dädan af skådar han efter mat, och hans ögon se långt bort. Hans ungar supa blod, och hvar en åtel är, der är han. Och Herren svarade Job, och sade: Den som vill träta med den Allsmägtiga, skulle han draga sig undan? Och den som vill straffa Gud, måste han icke svara? Job svarade Herranom, och sade: Si, jag hafver bannats, hvad skall jag svara? Jag vill lägga mina hand uppå min mun. Jag hafver en gång talat, derföre vill jag icke mer svara; på en annan tid vill jag icke göra det mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Och Herren svarade Job utur ett väder, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Gjorda dina länder som en man. Jag vill fråga dig, och säg du mig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Skulle du göra min dom omintet, och fördöma mig, på det du skall vara rättfärdig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Och hafver du en arm såsom Gud, och kan du med lika röst dundra, såsom han gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Bepryd dig med härlighet, och upphäf dig; kläd dig med lof och äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Strö ut dins grymhets vrede; se uppå alla högmodiga, och böj dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Och förtryck de ogudaktiga, der de äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Begraf dem tillsammans i jordene, och försänk deras prål uti det fördolda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Så vill jag ock bekänna dig, att din högra hand dig hjelpa kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Si, Behemoth, den jag bredovid dig gjort hafver, han skall äta hö såsom en oxe.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Si, hans kraft är uti hans länder, och hans förmåga i hans buks nafla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Hans stjert sträcker sig ut såsom ett ceder; hans hemlig tings senor äro förvecklada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Hans ben äro såsom kopparrör; hans benlägger såsom jernstafrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Han är begynnelsen af Guds vägar, den honom gjort hafver, han öfverfaller honom med sitt svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Bergen bära honom gräs, och all vilddjur spela der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Han ligger i skuggan fördold, i rör och i träck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Busken öfvertäcker honom med sin skugga, och pilträ vid bäcker öfvertäcka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Si, han uppsluker strömmen, och grufvar sig intet; han låter sig tycka, att han vill uttömma Jordanen med sin mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Likväl griper man honom med sin egen ögon, och med snöre igenomborrar man honom hans näso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Kan du draga Leviathan med en krok, och fatta hans tungo med ett snöre?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Kan du sätta honom en ring i näsona, och borra honom hans kindben igenom med en syl?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Menar du, att han skall mycket bedjas före, eller smeka dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Menar du, att du kan göra ett förbund med honom, att du må hafva honom till en träl evinnerliga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Kan du spela med honom såsom med en fogel; eller binda honom dinom pigom? Menar du, att sällskapet skola skära honom sönder, att han blifver utdelad ibland köpmännerna? Kan du fylla ena not med hans hud, och någon fiskaryssjo med hans hufvud? När du kommer dina hand vid honom, så kom ihåg, att det en strid är, den du icke uthålla kan. Si, hans hopp skall fela honom, och han skall uppenbarligen fördrifven varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Ingen är så dristig, att han honom uppväcka tör. Ho är då den, som för mig bestå kan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Ho hafver något gifvit mig tillförene, att jag må honom det vedergälla? Mitt är allt det under hela himmelen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Jag vill icke förtiga hans kraft; ej heller hans magt, eller huru välskapad han är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Ho kan upptäcka honom hans kläde? Eller ho tör vågat, att fatta honom i tänderna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Ho kan öppna hans anletes kindben? Förskräckeliga stå hans tänder allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Hans fjäll äro lika som sköldar, sammanfäste hvar i annan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Det ena hänger in i det andra, så att vädret icke går deremellan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Det hänger hvar i annan, och hålla sig tillsammans, så att de icke kunna skiljas åt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Hans njusande är såsom ett glimmande ljus; hans ögon äro såsom morgonrodnans ögnahvarf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Utaf hans mun fara bloss och eldbrandar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Utaf hans näso går rök, såsom utaf heta grytor och kettlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Hans ande är glödande kol, och utu hans mun går låge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Han hafver en starkan hals, och det är honom lust, då han något förderfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Hans kötts ledamot hänga vid hvartannat; de äro faste i honom, att han icke rörd varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Hans hjerta är hårdt såsom sten, och så fast som ett stycke af understenen i qvarnene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'När han reser sig, förfära sig de starke; och när han får dem fatt, är der ingen nåde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Om man vill till honom med svärd, så rörer han sig intet; eller med spets, skott och harnesk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Han aktar jern såsom strå, och koppar såsom ruttet trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Ingen skytte förjagar honom; slungostenar äro honom såsom agnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Hammaren aktar han såsom strå; han bespottar de bäfvande spetsar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Han kan ligga på skarpt grus; han lägger sig uppå det skarpt är, såsom på dyngo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Han gör, att djupa hafvet sjuder såsom en gryta, och rörer det ihop, såsom man blandar ena salvo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Efter honom är vägen ljus; djupet aktar han såsom en gamlan gråhårotan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'På jordene kan ingen liknas honom; han är gjord till att vara utan fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Han föraktar allt det högt är; han är Konung öfver alla högmodiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Och Job svarade Herranom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Jag vet, att du all ting förmår; och ingen tanke är för dig fördold.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Det är en fåvitsk man, som menar fördölja sitt råd; derföre hafver jag ovisliga talat det mig för högt är, och det jag icke förstår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Så hör nu, låt mig tala; jag vill fråga dig, lär mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Jag hafver hört dig med öronen, och min ögon se dig ock nu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Derföre gifver jag mig skuld, och gör bot i stoft och asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Då nu Herren dessa orden med Job talat hade, sade Herren till Eliphas af Thema: Min vrede är förgrymmad öfver dig, och öfver dina två vänner; förty I hafven icke rätteliga talat om mig, såsom min tjenare Job.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Så tager nu sju stutar, och sju vädrar, och går bort till min tjenare Job, och offrer bränneoffer för eder, och låter min tjenare Job bedja för eder; förty honom vill jag anse, så att jag icke skall låta eder se, huru I hafven bedrifvit ena dårhet; förty I hafven icke rätt talat, såsom min tjenare Job.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Då gingo bort Eliphas af Thema, Bildad af Suah, och Sophar af Naema, och gjorde såsom Herren dem sagt hade; och Herren såg till Jobs person;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Och Herren vände Jobs fängelse, då han bad för sina vänner; och Herren gaf Job dubbelt så mycket, som han tillförene haft hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Och till honom kommo alle hans bröder, och alla hans systrar, och alle de honom tillförene kände, och åto med honom i hans hus, och vände sig till honom, och hugsvalade honom öfver allt det onda, som Herren hade låtit komma öfver honom; och hvardera gaf honom ett stycke penningar, och ett gyldene klenodium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Och Herren välsignade Job mer än tillförene; så att han fick fjortontusend får, och sextusend camelar, och tusende par oxar, och tusende åsnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Och fick sju söner och tre döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Och kallade den första Jemima, den andra Kezia, och den tredje KerenHappuch.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Och vordo icke funna så dägeliga qvinnor i all land, såsom Jobs döttrar; och deras fader gaf dem arfvedel med deras bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Och Job lefde derefter hundrade och fyratio år, så att han fick se sin barn och barnabarn, allt intill fjerde led.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Och Job blef död, gammal och mätt af lefvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Säll är den, som icke vandrar uti de ogudaktigas råd, och icke träder in uppå de syndares väg; ej heller sitter der de bespottare sitta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Utan hafver lust till Herrans lag, och talar om hans lag både dag och natt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Han är såsom ett trä, planteradt vid vattubäcker, hvilket sina frukt bär i sinom tid, och dess löf förfalna intet; och hvad han gör, det lyckas väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Men de ogudaktige äro icke så; utan såsom agnar, som vädret bortförer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Derföre blifva icke de ogudaktige i domenom, eller syndarena i de rättfärdigas församling.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Ty Herren känner de rättfärdigas väg; men de ogudaktigas väg förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Hvarföre vredgas Hedningarna, och folken tala så fåfängt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Konungarna på jordene resa sig upp, och herrarna rådslå med hvarannan emot Herran och hans Smorda:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Låt oss sönderslita deras bojor, och kasta deras band bort ifrån oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Men den i himmelen bor, begabbar dem, och Herren bespottar dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Han skall en gång tala med dem i sine vrede, och med sine grymhet skall han förskräcka dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Men jag hafver insatt min Konung på mitt helga berg Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Jag vill om ett sådant sätt predika, som Herren till mig sagt hafver: Du äst min Son, i dag hafver jag födt dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Äska, af mig, så vill jag gifva dig Hedningarna till arfs, och verldenes ändar till egendom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Du skall sönderslå dem med jernspiro; såsom lerpottor skall du sönderkrossa dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Så låter nu undervisa eder, I Konungar; och låter tukta eder, I domare på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Tjener Herranom med fruktan, och fröjder eder med bäfvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Hyller Sonen, att han icke förtörnas, och I förgås på, vägenom; ty hans vrede skall snart begynna att bränna; men salige äro alle de som trösta på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'En Psalm Davids, då han flydde för sin son Absalom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Ack! Herre, huru månge äro mine fiender! Och så månge sätta sig upp emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Månge säga om mina själ: Hon hafver ingen hjelp när Gudi. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Men du, Herre, äst skölden för mig, och den mig till äro sätter, och mitt hufvud upprätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Jag ropar till Herran med mine röst, så hörer han mig af sitt helga berg. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Jag ligger och sofver, och vaknar upp; ty Herren uppehåller mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Jag fruktar mig intet för mång hundrad tusend, de som lägga sig emot mig allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Upp, Herre, och hjelp mig, min Gud; ty du slår alla mina fiendar på kindbenet, och sönderbryter de ogudaktigas tänder. När Herranom finner man hjelp; och din välsignelse öfver ditt folk. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'En Psalm Davids, till att föresjunga på strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Hör mig, när jag ropar, mine rättfärdighets Gud; du som tröstar mig i ångest; var mig nådelig, och hör mina bön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'I herrar, huru länge skall min ära skämd varda? Hvi hafven I fåfängeligheten så kär, och älsken lögnen? Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Besinner dock, att Herren förer sina heliga underliga; Herren hörer, när jag åkallar honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Varden I vrede, så synder icke; taler med edor hjerta på edra sänger, och bider. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Offrer rättfärdighet, och tröster uppå Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Månge säga: Huru skulle den visa oss hvad godt är? Men upplyft, Herre, öfver oss dins ansigtes ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Du fröjdar mitt hjerta, ändock de andre mycket vin och korn hafva. Jag ligger och sofver allstinges i frid; ty allena du, Herre, hjelper mig, att jag må säker bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'En Psalm Davids, till att föresjunga för arfvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Herre, hör min ord; gif akt uppå mitt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Gif akt uppå, mitt rop, min Konung, och min Gud; ty jag vill bedja inför dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Herre, bittida hör mina röst; bittida vill jag skicka mig till dig, och taga der vara, uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Ty du äst icke den Gud, hvilkom ett ogudaktigt väsende behagar; den der ond är, han blifver icke för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'De storordige bestå intet för din ögon; alla ogerningsmän hatar du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Du förgör de lögnaktiga; Herren hafver en styggelse vid de blodgiruga och falska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Men jag vill gå in i ditt hus på, dina stora barmhertighet, och tillbedja emot ditt helga tempel i dine fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Herre, led mig i dine rättfärdighet, för mina fiendars skull; gör din väg rättan för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Ty uti deras mun är intet visst: deras innersta är vedermöda; deras strupe är en öppen graf; med deras tungor skrymta de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Döm dem, Gud, att de måga falla af sitt uppsåt; drif dem ut för deras stora öfverträdelses skull; ty de äre dig gensträfvige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Låt glädja sig alla dem som trösta uppå dig, evinnerliga låt dem fröjda sig; ty du beskärmar dem; låt dem i dig glade vara, som ditt Namn kärt hafva. Ty du, Herre, välsignar de rättfärdiga; du kröner dem med nåde, såsom med en sköld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'En Psalm Davids, till att föresjunga på åtta stränger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Ack! Herre, straffa mig icke i dina vrede, och näps mig icke i dine grymhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Herre, var mig nådelig, ty jag är svag; hela mig, Herre, ty mine ben äro förskräckte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Och min själ är svårliga förskräckt; ack! Herre, huru länge?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Vänd dig, Herre, och undsätt mina själ; hjelp mig för dina mildhets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Ty i döden tänker man intet på dig; ho vill tacka dig i helvete?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Jag är så trött af suckande; jag gör mina säng flytande i hela nattene, och väter mitt lägre med mina tårar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Mitt ansigte är förfallet af sorg, och är gammalt vordet; ty jag varder trängd på alla sidor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Viker ifrå mig, alle ogerningsmän; ty Herren hörer min gråt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Herren hörer mina bön; mina bön anammar Herren. Alle mine fiender komme på skam, och förskräckes svårliga; vände sig tillbaka, och komme på skam hasteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Davids oskyldighet, der han om söng Herranom, för Chus ords skull, den Jeminitens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Uppå dig, Herre, tröstar jag, min Gud; hjelp mig ifrån alla mina förföljare, och undsätt mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Att de icke få mina själ fatt såsom lejon, och sönderslita henne efter ingen hjelpare är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Herre min Gud, hafver jag sådant gjort, och är orätt i mina händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Hafver jag vedergullit dem ondt, som mig med frid läto, eller gjort dem skada, som mine fiender voro utan sak;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Så förfölje min fiende mina själ, och få henne fatt, och nedtrampe mitt lif på markena, och lägge mina äro uti stoft. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Statt upp, Herre, i dine vrede; upphäf dig öfver mina fiendars grymhet; och hjelp mig åter in i det ämbete, som du mig befallt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Att folket må åter församla sig till dig; och för deras skull kom upp igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Herren är domare öfver folken; döm mig, Herre, efter mina rättfärdighet och fromhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Låt på de ogudaktigas ondsko en ände varda, och fordra de rättfärdiga; ty du, rättfärdige Gud, pröfvar hjerta och njurar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Min sköld är när Gudi, hvilken de rätthjertade hjelper.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Gud är en rätt domare, och en Gud, som dageliga hotas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Vill man icke omvända sig, så hafver han hvässt sitt svärd, och spänt sin båga och måttar till;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Och hafver lagt der dödelig skott uppå; sina pilar hafver han tillredt, till att förderfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Si, denne hafver ondt i sinnet, med olycko är han hafvandes; men ett fel skall han föda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Han hafver grafvit ena grop, och kastat der grant ut, och är i den gropena fallen, som han gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Hans olycka skall uppå hans hufvud komma, och hans arghet uppå hans hjessa falla. Jag tackar Herranom för hans rättfärdighets skull, och vill lofva Herrans Namn, dens Aldrahögstas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'En Psalm Davids, till att föresjunga på Gittith.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Herre, vår Herre, huru härligit är ditt Namn i all land, der man tackar dig i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Utaf unga barnas och spenabarnas mun hafver du ena magt upprättat, för dina ovänners skull; att du skall nederlägga ovännen, och den hämndgiruga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Ty jag skall se himlarna, dins fingers verk; månan och stjernorna, som du beredt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Hvad är menniskan, att du tänker på henne; eller menniskones son, att du låter dig vårda om honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Du skall låta honom en liten tid af Gudi öfvergifven varda; men med äro och härlighet skall du kröna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Du skall göra honom till en herra öfver dina händers verk; all ting hafver du under hans fötter lagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Får och fä alltsamman; vilddjuren också dertill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Foglarna under himmelen, och fiskarna i hafvet, och hvad i hafvena går. Herre, vår Herre, huru härligit är ditt Namn i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'En Psalm Davids, om den sköna, ungdomen, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Jag tackar Herranom af allt hjerta, och förtäljer all din under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Jag fröjdar mig, och är glad i dig; och lofvar ditt Namn, du Aldrahögste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Att du mina ovänner tillbakadrifvit hafver; de äro fallne och förgångne för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Ty du drifver min rätt och min sak; du sitter på stolen en rätt domare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Du straffar Hedningarna, och förgör de ogudaktiga; deras namn utskrapar du till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Fiendernas svärd hafva en ända; städerna hafver du omstört; deras åminnelse är förgången med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Men Herren blifver evinnerliga; sin stol hafver han beredt till doms.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Och han skall döma jordenes krets rätt, och regera folket rättsinneliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Och Herren är dens fattigas beskärm; ett beskärm i nödene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Derföre hoppas till dig de som ditt Namn känna; ty du förlåter icke dem som söka dig, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Lofver Herran, den i Zion bor; förkunner ibland folken hans verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Ty han kommer ihåg, och frågar efter deras blod; han förgäter icke de fattigas rop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Herre, var mig nådelig; se till mitt elände ibland ovänner, du som upphäfver mig utu dödsens portom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'På det jag skall förtälja all din pris uti dottrenes Zions portom; att jag öfver dina hjelp glad vara må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Hedningarna äro försänkte uti den grop, som de tillredt hade; deras fot är fången i nätet, som de uppställt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Så förnimmer man, att Herren skaffar rätt; den ogudaktige är besnärd uti sina händers verk, genom ordet. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Ack! att de ogudaktiga till helvetet vände vorde, och alle Hedningar, som Gud förgäta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Ty han skall icke så allstinges förgäta den fattiga; och de eländas hopp skall icke förtappadt varda evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Herre, statt upp, att menniskorna icke få öfverhandena; låt alla Hedningar för dig dömda varda. Gif dem, Herre, en mästare, att Hedningarna måga förnimma att de menniskor äro. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Herre, hvi träder du så långt ifrå fördöljer dig i nödenes tid?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Så länge den ogudaktige öfverhandena hafver, måste den elände lida; de hålla med hvarannan, och upptänka arga list.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Ty den ogudaktige berömmer sig af sitt sjelfsvåld; och den giruge välsignar sig, och lastar Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Den ogudaktige är så stolt och vred, att han frågar efter ingen; uti alla sina tankar håller han Gud för intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Han håller fram med det han förehafver; dine domar äro fjerran ifrå honom; han handlar högmodeliga med alla sina fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Han säger i sitt hjerta: Jag varder aldrig omstött; det skall ingen nöd hafva i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Hans mun är full med bannor, falskhet och bedrägeri; hans tunga kommer mödo och arbete åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Han sitter i försåt i gårdomen; han dräper de oskyldiga hemliga; hans ögon vakta efter de fattiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Han vaktar i hemlig rum, såsom ett lejon i kulone; han vaktar efter, att han må gripa den elända; och han griper honom, då han drager honom i sitt nät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Han förkrossar och nedertrycker, och till jordena slår den fattiga med våld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Han säger i sitt hjerta: Gud hafver förgätit det; han hafver bortdolt sitt ansigte, han ser det aldrig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Statt upp, Herre Gud; upphäf dina hand; förgät icke den elända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Hvi skall den ogudaktige försmäda Gud, och i sitt hjerta säga: Du sköter der intet om?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Du ser det ju; förty du skådar vedermödo och jämmer, det står i dina händer; de fattige befalla det dig; du äst de faderlösas hjelpare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Bryt sönder dens ogudaktigas arm, och besök det onda; så skall man hans ogudaktiga väsende intet mer finna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Herren är Konung alltid och evinnerliga; Hedningarna måste förgås utu hans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'De fattigas trängtan hörer du, Herre; deras hjerta är visst, att ditt öra aktar deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Att du skaffar dem faderlösa och fattiga rätt; att menniskan icke mer skall högmodas på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'En Psalm Davids, till att föresjunga. Jag förtröstar på Herran; huru sägen I då till mina själ, att hon skall flyga, såsom en fogel på edro berge?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Ty si, de ogudaktige spänna bågan, och lägga sina pilar på strängen, till att dermed hemliga skjuta de fromma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Ty de sönderrifva grunden; hvad skulle den rättfärdige uträtta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Herren är i sitt helga tempel; Herrans stol är i himmelen; hans ögon se deruppå; hans ögnahvarf pröfva menniskors barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Herren pröfvar den rättfärdiga; hans själ hatar den ogudaktiga, och dem der gerna orätt bruka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Han skall låta regna öfver de ogudaktiga ljungande, eld och svafvel; och skall gifva dem oväder till löna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Herren är rättfärdig, och hafver rätthetena kär; derföre, att deras ansigte skådar uppå det rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'En Psalm Davids, till att föresjunga på åtta stränger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Hjelp, Herre; de helige äro förminskade; och de trogne äro få ibland menniskors barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Den ene talar med den andra onyttig ting; och skrymta, och lära utaf oens hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Herren utrote allt skrymteri och de tungo, som stor ord talar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'De der säga: Vår tunga skall hafva öfverhandena; oss bör tala; ho är vår herre?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Efter nu de elände förtryckte varda, och de fattige sucka, vill jag upp, säger Herren; jag vill skaffa en hjelp, att man frimodeliga lära skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Herrans tal är klart, såsom genomluttradt silfver i enom lerdegel, bepröfvadt sju resor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Du Herre, bevara dem, och förvara oss för detta slägtet, till evig tid. Ty det varder allestäds fullt med ogudaktiga, der sådana löst folk ibland menniskorna rådande är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Herre, huru länge vill du så platt förgäta mig? Huru länge fördöljer du ditt ansigte för mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Huru länge skall jag sörja i mine själ, och ängslas i mitt hjerta dagliga? Huru länge skall min ovän förhäfva sig öfver mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Skåda dock, och hör mig, Herre min Gud; upplys min ögon, att jag icke bortsomnar i dödenom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Att min ovän icke skall berömma sig att han är mig öfvermägtig vorden, och mine motståndare glädja sig att jag nedre ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Men jag tröstar deruppå, att du så nådelig äst; mitt hjerta gläder sig, att du så gerna hjelper. Jag vill sjunga Herranom, att han så väl emot mig gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'En Psalm Davids, till att föresjunga. De dårar säga i sitt hjerta: Det är ingen Gud till; de doga intet, och äro en styggelse med sitt väsende; det är ingen, som väl gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Herren såg af himmelen uppå menniskors barn, att han se skulle om der någor förståndig vore, och efter Gud frågade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Men de äro alle afvekne, och allesammans odogse; det är ingen, som väl gör, ja icke en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Vill då ingen af de ogerningsmän det märka? de som mitt folk uppfräta, på det de måga föda sig; men Herran åkalla de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Der frukta de sig; men Gud är när de rättfärdigas slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'I skämmen den fattigas råd; men Gud är hans tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ack! att hjelpen af Zion öfver Israel komme, och Herren sitt fångna folk förlossade; så skulle Jacob glad vara, och Israel fröjda sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'En Psalm Davids. Herre, ho skall bo i dine hyddo? Ho skall blifva på ditt helga berg?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Den som vandrar utan vank, och gör rätt, och talar sanningen af hjertat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Den med sine tungo icke förtalar, och icke gör sin nästa ondt, och sin nästa icke skämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Den som de ogudaktiga för intet aktar; men dem som Herran frukta, ärar han, den som sinom nästa svär, och håller det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Den som icke gifver sina penningar på ocker, och tager icke skänker öfver den oskyldiga. Den det gör, han skall blifva vid sig evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Ett gyldene klenodium Davids. Bevara mig, Gud; förty jag tröstar uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Jag hafver sagt till Herran: Du äst ju Herren; jag måste för dina skull lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'För de heliga, som på jordene äro, och för de härliga, till dem hafver jag allt mitt behag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Men de som efter en annan löpa, skola stor bedröfvelse hafva; jag vill icke offra deras drickoffer med blod, eller föra deras namn i minom mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Men Herren är mitt gods och min del; du uppehåller min arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Lotten är mig fallen i det lustiga; mig är en skön arfvedel tillfallen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Jag lofvar Herran, den mig råd gifvit hafver; tukta mig också mine njurar om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Jag hafver Herran för ögon alltid: ty han är mig på högra handene; derföre skall jag väl blifva vid mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Derföre gläder sig mitt hjerta, och min ära är glad, och mitt kött skall säkert ligga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Ty du skall icke låta mina själ uti helvete; och icke tillstädja, att din Helige ser förgängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Du kungör mig vägen till lifvet; för dig är glädje tillfyllest, och lustigt väsende på dine högra hand evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'En bön Davids. Herre, hör rätthetena; gif akt uppå mitt rop, förnim mina bön, den icke utaf en falsk mun går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Tala du i mine sak, och se du uppå hvad rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Du pröfvar mitt hjerta, och besöker det om nattena, och ransakar mig, och finner intet; jag hafver satt mig före, att min mun icke öfverträda skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Jag förvarar mig i dina läppars orde, för menniskors gerningar, på mördarens väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Behåll min gång på dinom stigom, att min steg icke slinta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Jag ropar till dig, att du Gud ville höra, mig; böj din öron till mig, hör mitt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Bevisa, dina underliga godhet, du, deras Frälsare, som trösta uppå dig, emot dem som sig emot dina högra hand sätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Bevara mig såsom en ögnasten; beskärma mig under dina vingars skugga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'För de ogudaktiga, som mig förhärja; för mina ovänner, som efter mina själ stå allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Deras fete hålla tillsamman; de tala med sin mun stor ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Hvar vi gå, så äro de kringom oss; sina ögon ställa de derefter, att de måga slå oss till jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Såsom ett lejon, som rof begärar; såsom ett ungt lejon, som i kulone sitter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Herre, statt upp, öfverfall honom, och nederslå honom; undsätt mina själ ifrå de ogudaktiga, med ditt svärd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Ifrå dine hands menniskom, Herre, ifrå denne verldenes menniskom, hvilka sin del hafva medan de lefva; dem du buken fyller med dina håfvor; de der barn nog hafva, och låta sina återlefvor sinom barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Men jag vill skåda ditt ansigte i rättfärdighet; jag vill mätt varda, när jag uppvakar efter ditt beläte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'En Psalm, till att föresjunga, Davids, Herrans tjenares; hvilken denna visos ord talade till Herran, på den tid Herren honom hulpit hade ifrå hans fiendars hand, och ifrå Sauls hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Och sade: Hjerteliga, kär hafver jag dig, Herre, min starkhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Herre, min klippa, min borg, min förlossare; min Gud, min tröst, den jag mig vid håller; min sköld, och min salighets horn, och mitt beskydd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Jag vill lofva och åkalla Herren; så blifver jag ifrå mina ovänner förlöst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Ty dödsens band hafva, omfattat mig, och Belials bäcker förskräckt mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Helvetes band hafva omfattat mig, och dödsens snaror öfverfallit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'När jag är i ångest, så åkallar jag Herran, och ropar till min Gud; så hörer han mina röst af sitt tempel, och mitt rop kommer för honom till hans öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Jorden bäfvade och gaf sig, och bergens grundvalar rördes och bäfvade, då han vred var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Damb gick upp af hans näso, och förtärande eld af hans mun; så att det ljungade deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Han böjde himmelen, och for neder, och mörker var under hans fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Och han för uppå Cherub, och flög; han sväfde på vädrens vingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Hans tjäll omkring honom var mörker, och svart tjockt moln, der han inne fördold var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Af skenet för honom delte sig skyn, med hagel och ljungande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Och Herren dundrade i himmelen; och den Högste lät sitt dunder ut, med hagel och ljungande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Han sköt sina skott, och förströdde dem; han lät fast ljunga, och förskräckte dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Der såg man vattuådrorna; och jordenes grund vardt blottad, Herre, af ditt straff, af dine näsos anda och blåst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Han sände utaf höjdene, och hemtade mig; och drog mig utu stor vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Han halp mig ifrå mina starka fiendar; ifrå mina hatare, som mig för mägtige voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'De mig öfverföllo i mins motgångs tid; och Herren vardt min tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Och han förde mig ut på rymdena; han tog mig derut; ty han hade lust till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Herren gör väl emot mig, efter mina rättfärdighet; han vedergäller mig efter mina händers renhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Ty jag håller Herrans vägar, och är icke ogudaktig emot min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Ty alla hans rätter hafver jag för ögon, och hans bud kastar jag icke ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Men jag; är utan vank för honom, och bevarar mig för min synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Derföre vedergäller mig Herren, efter mina rättfärdighet; efter mina händers renhet för hans ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Med de heliga äst du helig; och med de fromma, äst du from;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Och med de rena äst du ren; och vid de afvoga ställer du dig afvog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Ty du hjelper det elända folket, och de höga ögon förnedrar du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Ty du upplyser mina lykto; Herren, min Gud, gör mitt mörker ljust.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Ty med dig kan jag nederlägga krigsfolk, och med minom Gud öfver muren springa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Guds vägar äro utan vank; Herrans tal äro genomluttrad; han är en sköld allom dem som trösta uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Ty ho är en Gud, utan Herren; eller en starker, utan vår Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Gud omgjordar mig med kraft, och gör mina vägar utan vank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Han gör mina fötter lika som hjortars, och sätter mig på mina höjder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Han lärer mina hand strida, och min arm spänna kopparbågan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Och du gifver mig dins salighets sköld, och din högra hand stärker mig; och när du förnedrar mig, gör du mig storan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Du gör under mig rum till att gå, att mina fötter icke skola slinta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Jag vill jaga efter mina fiendar, och gripa dem; och intet omvända, tilldess jag hafver nederlagt dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Jag skall slå dem, och de skola icke kunna mig emotstå; de måste falla under mina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Du kan rusta mig med starkhet till strid; du kan kasta dem under mig, som sig emot mig sätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Du gifver mig mina fiendar på flyktena, att jag må förstöra mina hatare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'De ropa, men der är ingen hjelpare: till Herran, men han svarar dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Jag skall sönderstöta dem som stoft för vädret; jag skall bortkasta dem såsom träck på gatomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Du hjelper mig ifrå det trätosamma folket, och gör mig till ett hufvud ibland Hedningarna; ett folk, som jag intet kände, tjenar mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Det hörer mig med hörsam öron; men de främmande barn förneka mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'De främmande barn försmäkta, och brytas i sina bojor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Herren lefver, och lofvad vare min tröst; och mins salighets Gud varde upphöjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Gud, som mig hämnd gifver, och tvingar folken under mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Den mig hjelper ifrå mina fiendar, och upphöjer mig ifrå dem, som sätta sig emot mig; du hjelper mig ifrå de vrånga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Derföre vill jag tacka dig, Herre, ibland Hedningarna, och lofsjunga dino Namne; Den sinom Konung stor salighet bevisar, och gör sinom smorda godt; David, och hans säd evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Himlarna förtälja Guds äro, och fästet förkunnar hans händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'En dag säger det dem andra, och en natt kungör det de andro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Intet mål eller tal är, der man deras röst icke hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Deras snöre går ut i all land, och deras tal intill verldenes ändar; han hafver gjort solene ena hyddo i dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Och hon går ut såsom en brudgumme utu sinom kammar, och fröjdar sig såsom en hjelte till att löpa vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Hon går upp vid himmelens ända, och löper omkring åter till samma ändan; och intet blifver för hennes hetta förskyldt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Herrans lag är utan vank, och vederqvicker själarna; Herrans vittnesbörd är visst, och gör de enfaldiga visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Herrans befallningar äro rätta, och fröjda hjertat; Herrans bud äro klar, och upplysa ögonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Herrans fruktan är ren, och blifver evinnerliga; Herrans rätter äro sanne, allesamman rättfärdige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'De äro kosteligare än guld, och mycket fint guld; de äro sötare än hannog, och hannogskaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Ock varder din tjenare igenom dem förmanad; och den dem håller, han hafver stor lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Ho kan märka huru ofta han bryter? Förlåt mig mina hemliga brister.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Bevara ock din tjenare för de stolta, att de icke få råda öfver mig; så blifver jag utan vank, och oskyldig för stor missgerning. Låt dig täckas mins muns tal, och mins hjertans tankar för dig, Herre, min tröst och min förlossare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Herren höre dig i nödene; Jacobs Guds Namn beskydde dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Han sände dig hjelp af helgedomenom, och styrke dig utaf Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Han tänke uppå all din spisoffer; och din bränneoffer vare fet. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Han gifve dig hvad ditt hjerta begärar, och fullborde all din anslag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Vi fröjde oss, att du oss hjelper; och i vår Guds Namn rese vi baneret upp; Herren fullborde alla dina böner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Nu märker jag, att Herren hjelper sin smorda, och hörer honom i sinom helga himmel; hans högra hand hjelper väldeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'De andre förlåta sig på vagnar och hästar; men vi tänke på Herrans vår Guds Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'De äro nederstötte och fallne; men vi stå upprätte. Hjelp, Herre; Konungen höre oss, när vi rope.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Herre, Konungen fröjdar sig i dine kraft; och huru ganska glad är han af dine hjelp!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Du gifver honom hans hjertas önskan, och förvägrar intet hvad hans mun beder. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Ty du öfverskuddar honom med god välsignelse; du sätter ena gyldene krono uppå hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Han beder dig om lif; så gifver du honom ett långt lif, alltid och evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Han hafver stora äro af dine hjelp; du lägger lof och prydelse uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Ty du sätter honom till en välsignelse evinnerliga; du fröjdar honom med dins anletes fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Ty Konungen hoppas uppå Herran, och skall igenom dens Högstas godhet fast blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Din hand skall finna alla dina fiendar; din högra hand skall finna dem som dig hata.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Du skall göra dem såsom en glödande ugn, när du dertill ser; Herren skall uppsluka dem i sine vrede; elden skall uppfräta dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Deras frukt skall du förgöra utaf jordene, och deras säd ifrå menniskors barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Ty de tänkte att göra dig ondt, och togo de råd före, som de icke fullborda kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Ty du skall göra dem till skuldror; med dina strängar skall du emot deras anlete skjuta. Herre, upphöj dig i dine kraft; så vilje vi sjunga och lofva dina magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'En Psalm Davids, till att föresjunga, om hindena som bittida jagad varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Min Gud, min Gud, hvi hafver du öfvergifvit mig? Jag ryter; men min hjelp är fjerran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Min Gud, om dagen ropar jag, så svarar du intet; och om nattena tiger jag ock intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Men du äst helig, du som bor ibland Israels lof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Våre fäder hoppades uppå dig; och då de hoppades, halp du dem ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Till dig ropade de, och vordo hulpne; de hoppades på dig, och vordo icke till skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Men jag är en matk, och icke menniska; menniskors gabberi, och folks föraktelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Alle de som mig se, bespotta mig, gapa upp med munnen, och rista hufvudet:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Han klage det Herranom; han hjelpe honom ut, och undsätte honom, om han hafver lust till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Ty du hafver dragit mig utu mitt moderlif; och vast min tröst, då jag än vid mine moders bröst låg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'På dig är jag kastad utaf moderlifvet; du äst min Gud, allt ifrå mine moders lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Var icke långt ifrå mig; ty ångest är hardt när; ty här är ingen hjelpare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Store stutar hafva belagt mig; fete oxar hafva omhvärft mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'De uppgapa med sin mun emot mig, såsom ett glupande och rytande lejon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Jag är utgjuten såsom vatten; all min ben hafva skiljts åt; mitt hjerta i mitt lif är såsom ett smält vax.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Mina krafter äro borttorkade, såsom ett stycke af en potto; och min tunga lådar vid min gom, och du lägger mig uti dödsens stoft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Ty hundar hafva kringhvärft mig, och de ondas rote hafver ställt sig omkring mig; mina händer och fötter hafva de genomborrat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Jag måtte tälja all min ben; men de skåda och se sin lust på mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'De byta min kläder emellan sig, och kasta lott om min klädnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Men du, Herre, var icke fjerran; min starkhet, skynda dig till att hjelpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Fria mina själ ifrå svärdet, mina ensamma ifrå hundarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Hjelp mig utu lejonens mun, och fria mig ifrån enhörningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Jag vill predika ditt Namn minom brödrom; jag vill prisa dig i församlingene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Lofver Herran, I som frukten honom; honom äre all Jacobs säd, och honom vörde all Israels säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Ty han hafver icke föraktat eller försmått dens fattiga eländhet; och icke förskylt sitt ansigte för honom; och då han ropade till honom, hörde han det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Dig vill jag prisa, uti den stora församlingene; jag vill betala mitt löfte inför dem som frukta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'De elände skola äta, att de mätte varda; och de som efter Herran fråga, skola prisa honom; edart hjerta skall lefva evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Tänke derpå alla verldenes ändar, och omvände sig till Herran; och alla Hedningars slägter tillbedje för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Herren hafver ett rike, och han råder ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Alle fete på jordene skola äta, och tillbedja; för honom skola knäböja alle de som i stoft ligga, och de der med bekymmer lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Han skall få ena säd, den honom tjenar; om Herran skall man förkunna intill barnabarn. De skola, komma och predika hans rättfärdighet de folke, som födas skall, att han det gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'En Psalm Davids. Herren är min herde, mig skall intet fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Han föder mig på en grön äng, och förer mig till friskt vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Han vederqvicker mina själ; han förer mig in på rätta vägen, för sitt Namns skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Och om jag än vandrade i enom mörkom dal, fruktade jag intet ondt; ty du äst när mig; din käpp och staf trösta mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Du bereder till mig ett bord emot mins fiendar; du smörjer mitt hufvud med oljo, och inskänker fullt för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Godhet och barmhertighet skola följa mig i alla mina lifsdagar; och jag skall blifva i Herrans hus evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'En Psalm Davids. Jorden är Herrans, och hvad deruti är; jordenes krets, och hvad derpå bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Ty han hafver grundat henne på hafvena, och på floderna beredt henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Ho skall gå uppå Herrans berg? Och ho kan stå uti hans helga rum?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Den oskyldiga händer hafver, och renhjertad är; den ej lust hafver till lösaktiga läro, och svär icke falskeliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Han skall undfå välsignelse af Herranom, och rättfärdighet af sins helsos Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Detta är den slägt, som efter honom frågar, den ditt ansigte, Jacob, söker. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Görer portarna vida, och dörrarna i verldene höga, att ärones Konung må draga derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Hvilken är den samme ärones Konung? Det är Herren, stark och mägtig, Herren mägtig i strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Görer portarna vida, och dörrarna i verldene höga, att ärones Konung må draga derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Hvilken är den samme ärones Konung? Det är Herren Zebaoth; han är ärones Konung. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'En Psalm Davids. Efter dig, Herre, längtar jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Min Gud, Jag hoppas uppå dig; låt mig icke komma på skam, att mine ovänner icke skola glädja sig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Ty ingen kommer på skam, den dig förbidar; men de löse föraktare komma på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Herre, visa mig dina vägar, och lär mig dina stigar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Led mig i dine sanning, och lär mig; ty du äst den Gud, som mig hjelper; dagliga förbidar jag dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Tänk Herre, på dina barmhertighet, och uppå dina godhet, den af verldenes begynnelse varit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Tänk icke uppå mins ungdoms synder, och min öfverträdelse; men tänk uppå mig, efter dina barmhertighet, för dina godhets skull, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Herren är god och from; derföre undervisar han syndarena på vägenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Han leder de elända rätt, och lärer de elända sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Alle Herrans vägar äro godhet och sanning, dem som hans förbund och vittnesbörd hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'För ditt Namns skull, Herre, var mine missgerning nådelig, den stor är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Hvilken är den der fruktar Herran, han skall lära honom den bästa vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Hans själ skall bo i det goda, och hans säd skall besitta landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Herrans hemlighet är ibland dem som frukta honom; och sitt förbund låter han dem få veta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Mine ögon se alltid till Herran; ty han skall taga min fot utu nätet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Vänd dig till mig, och var mig nådelig; ty jag är ensam och elände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Mins hjertans ångest är stor; för mig utu mine nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Se uppå min jämmer och eländhet, och förlåt mig alla mina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Se deruppå, att mine fiender så månge äro, och hata mig med orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Bevara min själ, och fräls mig; låt mig icke komma på skam, ty jag förtröstar uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Fromhet och rätthet, bevare mig; ty jag förbidar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Gud löse Israel utaf allo sine nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'En Psalm Davids. Herre, skaffa mig rätt; ty jag är oskyldig. Jag hoppas på Herran; derföre skall jag icke falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Pröfva mig, Herre, och försök mig; ransaka mina njurar och mitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Ty din godhet är för min ögon, och jag vandrar i dine sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Jag sitter icke när de fåfänga, menniskor, och hafver icke omgängelse med de falska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Jag hatar de ondas församling, och sitter icke när de ogudaktiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Jag tvår mina händer med oskyldighet, och håller mig, Herre, intill ditt altare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Der man hörer tacksägelses röst, och der man predikar all din under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Herre, jag hafver dins hus boning kär, och det rum der din ära bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Ryck icke mina själ bort med syndarena, eller mitt lif med de blodgiruga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Hvilke omgå med arga list, och taga gerna gåfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Men jag vandrar oskyldeliga; förlös mig, och var mig nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Min fot går rätt; i församlingene vill jag lofva dig, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'En Psalm Davids. Herren är mitt ljus och min helsa; för hvem skall jag frukta mig? Herren är mins lifs kraft; för hvem skulle jag grufva mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Derföre, om de onde mine motståndare och fiender till mig vilja, till att fräta mitt kött, måste de stöta sig och falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Om än en här lade sig emot mig, så fruktade sig ändå mitt hjerta intet; om en strid hofve sig upp emot mig, så förlåter jag mig uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Ett beder jag af Herranom, det hade jag gerna; att jag i Herrans hus blifva må i alla mina lifsdagar, till att skåda den sköna Herrans Gudstjenst, och besöka hans tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Ty han öfvertäcker mig i sine hyddo i ondom tid; han förgömmer mig hemliga i sitt tjäll, och upphöjer mig på ene klippo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Och skall nu upphöja mitt hufvud öfver mina fiendar, som omkring mig äro; så vill jag i hans hyddo lof offra; jag vill sjunga och lofsäga Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Herre, hör mina röst, när jag ropar; var mig nådelig, och hör mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mitt hjerta håller dig ditt ord före: I skolen söka mitt ansigte; derföre söker jag ock, Herre, ditt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Fördölj icke ditt ansigte för mig, och bortdrif icke din tjenare i vredene; ty du äst min hjelp; öfvergif mig icke, och drag icke handena ifrå mig, Gud, min salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Ty min fader och min moder öfvergifva mig; men Herren upptager mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Herre, visa mig din väg, och led mig på den rätta stigen, för mina fiendars skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Gif mig icke uti mina fiendars vilja; ty falsk vittne stå emot mig, och göra mig orätt skamlöst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Men jag tror dock, att jag se skall Herrans goda, uti de lefvandes lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Förbida Herran; var tröst och oförfärad, och förbida Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'En Psalm Davids. När jag ropar till dig, Herre, min tröst, så tig mig icke; på det, när du tiger, jag icke varder dem lik, som i kulona fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Hör mine böns röst, när jag ropar till dig; när jag upplyfter mina händer till din helga chor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Drag mig icke bort ibland de ogudaktiga, och ibland de ogerningsmän, som vänliga tala med sin nästa, och hafva ondt i hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Gif dem efter sina gerningar, och efter sitt onda väsende; gif dem efter sina händers verk; betala dem det de förtjent hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Ty de vilja icke akta uppå Herrans gerningar, eller uppå hans händers verk; derföre skall han nederslå, och icke uppbygga dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Lofvad vare Herran; ty han hafver hört mine böns röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Herren är min starkhet, och min sköld; uppå honom hoppades mitt hjerta, och mig är hulpet; och mitt hjerta är gladt, och jag vill tacka honom med mine viso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Herren är deras starkhet; han är den starke, som sin smorda hjelper.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Hjelp ditt folk, och välsigna ditt arf, och föd dem, och upphöj dem till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'En Psalm Davids. Bärer fram Herranom, I väldige; bärer fram Herranom äro och starkhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Bärer fram Herranom hans Namns äro; tillbedjer Herran i heligo prydning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Herrans röst går på vattnen; ärones Gud dundrar; Herren på stor vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Herrans röst går med magt; Herrans röst går härliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Herrans röst sönderbryter cedrer; Herren sönderbryter cedrer i Libanon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Och låter dem springa såsom en kalf; Libanon och Sirion, såsom en ung enhörning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Herrans röst afhugger såsom en eldslåge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Herrans röst berörer öknena; Herrans röst berörer öknena Kades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Herrans röst berörer hinderna, och blottar skogarna; och i hans tempel skall hvar och en säga honom äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Herren sitter till att göra ena flod, och Herren blifver en Konung i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Herren skall gifva sino folke kraft; Herren skall välsigna sitt folk med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'En Psalm, till att sjunga om Davids hus vigning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Jag prisar dig, Herre: ty du hafver upphöjt mig, och låter icke mina fiendar glädja sig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Herre min Gud, då jag ropade till dig, gjorde du mig helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Herre, du hafver fört mina själ utu helvetet; du hafver behållit mig lefvande, der de i helvetet foro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'I Helige, lofsjunger Herranom, och tacker i hans helga högtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Ty hans vrede varar ett ögnablick, och han hafver lust till lif; om aftonen varar gråten, men om morgonen glädjen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Men jag sade, då mig väl gick: Jag skall aldrig omkull ligga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Ty du, Herre, hafver igenom din goda vilja gjort mitt berg starkt; men då du bortdolde ditt ansigte, förskräcktes jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Jag vill, Herre, ropa till dig; Herran vill jag bedja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Hvad nytta är i mitt blod, när jag död är? Månn ock stoftet tacka dig, och förkunna dina trohet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Hör, Herre, och var mig nådelig; Herre, var min hjelpare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Du hafver förvandlat mig min klagan uti fröjd; du hafver afklädt mig min säck, och omgjordat mig med glädje; På det min ära skall lofsjunga dig, och icke tyst varda. Herre, min Gud, jag vill dig tacka i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Herre, uppå dig förtröstar jag, låt mig aldrig på skam komma; fräls mig genom dina rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Böj din öron till mig, hasteliga hjelp mig; var mig en stark klippa och en borg, att du hjelper mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Ty du äst min klippa och min borg; att du dock för ditt Namns skull mig leda och föra ville;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Att du ville draga mig utu nätet, som de för mig ställt hafva; ty du äst min starkhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Uti dina händer befaller jag min anda; du hafver mig förlöst, Herre, du trofaste Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Jag hatar dem som hålla uppå lösaktiga läro; men jag hoppas till Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Jag fröjdar mig, och är glad öfver dina godhet; att du anser mitt elände, och känner mina själ i nödene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Och du öfvergifver mig icke uti fiendans händer; du sätter mina fötter uppå vidt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Herre, var mig nådelig, ty mig är ångest; mitt ansigte är förfallet för sorgs skull, dertill min själ och min buk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Ty mitt lefvande är förtärdt vordet af bedröfvelse, och mine år af suckande; min kraft är igenom mina missgerning förfallen, och min ben äro försmäktade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Det går mig så illa, att jag är en stor försmädelse vorden minom grannom, och en styggelse minom kändom; de som mig se på gatone, de fly för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Jag är förgäten af hjertat, såsom en döder; jag är vorden såsom ett sönderslaget kärile.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Ty månge försmäda mig illa, så att hvar man skyr vid mig; de rådslå med hvarannan om mig, och akta taga mig lifvet bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Men jag, Herre, hoppas uppå dig, och säger: Du äst min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Min tid står i dina händer; hjelp mig utu mina fiendars hand, och ifrå dem som mig förfölja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Låt ditt ansigte lysa öfver din tjenare; hjelp mig genom dina godhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Herre, låt mig icke till skam varda, ty jag åkallar dig; de ogudaktige varde till skam, och tystade i helvete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Tystne de falske munnar, som tala emot den rättfärdiga hårdeliga, högmodiga och hånliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Huru stor är din godhet, den du dem, som dig frukta, bevarat hafver; och bevisar dem, som trösta uppå dig, inför menniskors barn!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Du förgömmer dem hemliga när dig för hvars mans trug; du förskyler dem i hyddone för de trätosamma tungor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Lofvad vare Herren, att han mig en underlig godhet bevisat hafver, i enom fastom stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Ty jag sade i mine häpenhet: Jag är bortdrifven ifrå dine ögon; likväl hörde du mine böns röst, då jag till dig ropade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Älsker Herran, alle hans helige. Herren bevarar de trogna, och vedergäller dem rikeliga, som högmod öfva. Varer tröste och oförfärade, alle I, som Herran förbiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'En undervisning Davids. Säll är den, hvilkom öfverträdelsen förlåten är, dem synden öfverskyld är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Säll är den menniska, som Herren icke tillräknar missgerning; i hvilkens anda ingen falskhet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Ty då jag ville förtigat, försmäktade min ben, genom min dagliga gråt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Ty din hand var dag och natt svår på mig, så att min vätska borttorkades, såsom det om sommaren torrt varder. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Derföre bekänner jag dig mina synd, och förskyler intet mina missgerning. Jag sade: Jag vill bekänna för Herranom min öfverträdelse; då förlätst du mig mine synds missgerning. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'För detta skola alle helige bedja dig i rättom tid; derföre, när store vattufloder komma, skola de intet räcka intill dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Du äst mitt beskärm, bevara mig dock för ångest; att jag förlossad må ganska gladeliga fröjdas. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Jag vill undervisa dig, och lära dig vägen, den du vandra skall; jag skall leda dig med mine ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Varer icke såsom hästar och mular, som intet förstånd hafva; hvilkom man måste lägga bett och betsel i munnen, om de icke till dig vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Den ogudaktige hafver många plågor; men den som hoppas uppå Herran, honom skall barmhertighet omfatta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Fröjder eder af Herranom, och varer glade, I rättfärdige; och berömmer eder, alle I fromme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Fröjder eder af Herranom, I rättfärdige; de fromme skola prise honom härliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Tacker Herranom med harpor; och lofsjunger honom på psaltare af tio stränger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Sjunger honom en ny viso; sjunger väl på strängaspel med klingande ljud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Ty Herrans ord är sannfärdigt; och hvad han lofvar, det håller han visserliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Han älskar rättfärdighet och dom; jorden är full af Herrans godhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Himmelen är gjord genom Herrans ord, och all hans här genom hans muns anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Han håller vattnet i hafvet tillsammans, såsom uti en lägel; och lägger djupen i det fördolda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'All verlden frukte Herran; honom rädes allt det som på jordene bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Ty om han säger, så sker det; om han bjuder, så är det gjordt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Herren gör Hedningarnas råd omintet, och vänder folks tankar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Men Herrans råd blifver evinnerliga; hans hjertas tankar i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Saligt är det folk, hvilkets Gud Herren är; det folk, som han till ett arf utkorat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Herren skådar neder af himmelen, och ser all menniskors barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Utaf sinom fasta stol ser han uppå alla de som på jordene bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Han böjer allas deras hjerta; han aktar uppå alla deras gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Enom Konung hjelper intet hans stora magt; enom kämpa varder icke hulpet genom hans stora kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Hästar hjelpa ock intet, och deras stora starkhet frälsar intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Si, Herrans öga ser uppå dem som frukta honom; de som uppå hans godhet trösta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Att han skall fria deras själ ifrå dödenom, och föda dem i hårdom tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Vår själ väntar efter Herranom; han är vår hjelp och sköld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Ty vårt hjerta gläder sig af honom, och vi hoppes på hans helga Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Din godhet, Herre, vare öfver oss, såsom vi på dig förtröste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'En Psalm Davids, då han förvandlade sitt ansigte för Abimelech, den honom ifrå sig dref, och han gick sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Jag vill lofva Herran i allom tid; hans lof skall alltid vara i minom mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Min själ skall berömma sig af Herranom, att de elände skola höra det, och glädja sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Priser med mig Herran, och låter oss med hvarannan upphöja hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Då jag sökte Herran, svarade han mig, och frälste mig utur all min fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'De som uppå honom se, de varda upplyste, och deras ansigte varder icke till skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'De denne elände ropade, hörde honom Herren; och halp honom utur all hans nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Herrans Ängel lägrar sig omkring dem som frukta honom, och hjelper dem ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Smaker och ser, huru ljuflig Herren är; säll är den som tröster uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Frukter Herran, I hans helige; ty de som frukta honom, de hafva ingen brist.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'De rike skola törstige vara och hungra; men de som Herran söka, hafva ingen brist på något godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kommer hit, barn, hörer mig; jag vill lära eder Herrans fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Hvilken är den som ett godt lefvande begärar, och gerna goda dagar hade?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Bevara dina tungo för det ondt är, och dina läppar, att de intet bedägeri tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Låt af det onda, och gör det goda; sök friden, och far efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Herrans ögon se uppå de rättfärdiga, och hans öron på deras ropande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Men Herrans ansigte står öfver dem som ondt göra, så att han utskrapar deras åminnelse af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Då de rättfärdige ropa, så hörer Herren; och hjelper dem utur alla deras nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Herren är hardt när dem som ett förbråkadt hjerta hafva; och hjelper dem som ett bedröfvadt mod hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Den rättfärdige måste mycket lida; men Herren hjelper honom utu thy allo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Han bevarar honom all hans ben, att icke ett sönderbrutet varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Den ogudaktiga skall det onda dräpa; och de som hata den rättfärdiga, de skola brottslige varda. Herren förlöser sina tjenares själar; och alle de som trösta på honom, skola icke varda brottslige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'En Psalm Davids. Herre, trät med dem som med mig träta; strid emot dem som på mig strida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Tag sköld och spjut, och statt upp till att hjelpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Drag fram glafven, och beskydda mig emot mina förföljare. Säg till mina själ: Jag är din hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Skämme sig, och varde bespottade, alle de som efter mina själ stå; vände tillrygga, och varde till skam, de som mig ondt vilja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Varde såsom agnar för väder, och Herrans Ängel bortdrifve dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Deras väg varde mörk och slipper; och Herrans Ängel förfölje dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Ty de hafva utan sak ställt mig sin nät till förderf, och hafva utan skuld grafvit mine själ en grop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Han varde oförsedt öfverfallen, och hans nät, som han ställt hafver, fånge honom; och han varde deruti öfverfallen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Men min själ fröjde sig af Herranom, och vare glad af hans hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'All min ben säge: Herre, ho är din like? du som hjelper den elända ifrå den honom för stark är, och den elända och fattiga ifrå sina röfvare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Der träda vrång vittne fram, och de vittna öfver mig, dess jag intet skyldig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'De göra mig ondt för godt, att min själ måste vara, såsom hon intet godt gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Men jag, när de kranke voro, drog en säck uppå; plågade mig med fastande, och bad träget af hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Jag höll mig, såsom det hade varit min vän och broder. Jag gick sorgse, såsom den der sörjer om sine moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Men de glädja sig öfver min skada, och församla sig; de halte församla sig emot mig oförsedt; de rifva, och hålla intet upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Med dem, som skrymta och begabba för bukens skull, bita de sina tänder tillsamman öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Herre, huru länge vill du se häruppå? Fräls dock mina själ ifrå deras buller, och mina ensamma ifrå de unga lejon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Jag vill tacka dig uti den stora församlingene, och ibland mycket folk vill jag prisa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Låt dem icke glädja sig öfver mig, som mig utan skäl fiender äro; eller begabba med ögonen, som utan skuld hata mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Ty de akta göra skada, och söka falska saker emot de stilla i landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Och gapa med sin mun vidt upp emot mig, och säga: Så, så, det se vi gerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Herre, du ser det, tig icke. Herre, var icke långt borto ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Uppväck dig, och vaka upp till min rätt, och till mina sak, min Gud och Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Herre, min Gud, döm mig efter dina rättfärdighet, att de icke skola glädja sig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Låt dem icke säga i sin hjerta: Så, så, det ville vi. Låt dem icke säga: Vi hafve uppsvulgit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Skämme sig, och till blygd varde, alle de som glädja sig öfver min ofärd. Varde med blygd och skam iklädde de som berömma sig emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Berömme och glädje sig de som mig unna, att jag behåller rätt; och alltid säge: Lofvad vare Herren högeliga, den sinom tjenare godt vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Och min tunga skall tala om dine rättfärdighet, och prisa dig dagliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'En Psalm Davids, Herrans tjenares, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Jag säger i sanningene, att de ogudaktige arge skalkar äro; ty när dem är ingen Gudsfruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'De rosa hvarannan inbördes, att de måga främja sina onda saker, och skämma andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'All deras lära är skadelig och lögn; de låta ock intet undervisa sig, att de måtte något godt göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Utan de tänka till skada på deras säng; och stå faste på den onda vägen, och sky för intet ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Herre, din godhet räcker så vidt som himmelen är, och din sanning så vidt som skyarna gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Din rättfärdighet står såsom Guds berg, och dine rätter såsom stor djup. Herre, du hjelper både menniskom och fänad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Huru dyr är din godhet, Gud, att menniskors barn tröst hafva under dina vingars skugga!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'De varda druckne utaf dins hus rika håfvor, och du skänker dem med vällust, såsom med enom ström.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Ty när dig är en lefvandes källa, och i dino ljuse se vi ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Utbred dina godhet öfver dem som känna dig, och dina rättfärdighet öfver de fromma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Låt mig icke undertrampad varda af de stolta, och de ogudaktigas hand omstörte mig icke; Utan låt de ogerningsmän der falla, att de måga bortdrifne varda, och icke bestå kunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'En Psalm Davids. Harmas icke öfver de onda; var icke nitisk öfver de ogerningsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Ty såsom gräs varda de snart afhuggne, och såsom gröna örter skola de förvissna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Haf hopp till Herran, och gör det godt är; blif i landet, och föd dig redeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Haf dina lust i Herranom; han skall gifva dig hvad ditt hjerta önskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Befalla Herranom din väg, och hoppas uppå honom; han skall väl görat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Och skall frambära dina rättfärdighet såsom ett ljus, och din rätt såsom en middag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Förbida Herran, och vänt efter honom. Harmas icke öfver den, hvilkom all ting, efter hans vilja, lyckosamliga framgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Håll tillbaka af vrede, och öfvergif grymhet; blif icke vred, så att du ock illa gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Ty de onda skola utrotade varda; men de, som vänta efter Herran, skola ärfva landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Det är ännu en liten tid, så är den ogudaktige intet mer; och när du efter hans rum ser, skall han borto vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Men de elände skola ärfva landet, och lust hafva i storom frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Den ogudaktige trugar den rättfärdiga, och biter sina tänder tillsamman öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Men Herren ler åt honom; ty han ser att hans dag kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'De ogudaktige draga ut svärdet, och bända sin båga, att de skola fälla den elända och fattiga, och slagta de fromma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Men deras svärd skall gå in i deras hjerta, och deras båge skall sönderbrista.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Det litsla, som en rättfärdig hafver, är bättre än många ogudaktigas stora håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Ty de ogudaktigas arm skall sönderbrytas; men Herren håller de rättfärdiga vid magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Herren känner de frommas dagar, och deras gods skall blifva evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'De skola icke på skam komma i den onda tiden, och i hårdom årom skola de nog hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Ty de ogudaktige skola förgås; och Herrans fiender, om de än vore såsom en kostelig äng, skola de likväl försvinna, såsom en rök försvinner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Den ogudaktige borgar, och betalar intet; men den rättfärdige är barmhertig och mild.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Ty hans välsignade ärfva landet; men hans förbannade varda utrotade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Af Herranom varder sådana mans gång främjad, och han hafver lust till hans väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Om han faller, varder han ej bortkastad; ty Herren håller honom vid handen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Jag hafver ung varit, och är gammal vorden, och hafver ännu aldrig sett den rättfärdiga förlåten, eller hans säd efter bröd gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Han är alltid barmhertig, och lånar gerna; och hans säd skall välsignad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Låt af det onda, och gör det goda, och blif i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Ty Herren älskar rätten, och öfvergifver icke sina heliga; evinnerliga varda de bevarade; men de ogudaktigas säd skall utrotad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'De rättfärdige ärfva landet, och blifva derinne evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Dens rättfärdigas mun talar vishet, och hans tunga lärer rätten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Hans Guds lag är i hans hjerta; hans steg slinta icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Den ogudaktige vaktar uppå den rättfärdiga, och aktar dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Men Herren låter honom icke uti hans händer, och fördömer honom icke, då han dömd varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Förbida Herran, och håll hans väg, så skall han upphöja dig, så att du skall ärfva landet. Du skall se, att de ogudaktige utrotade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Jag hafver sett en ogudaktig, den var fast väldig, och utbredde sig, och grönskades såsom ett laurbärsträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Då man gick der framom, si, så var han borto; jag frågade efter honom, då vardt han ingenstäds funnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Blif from, och håll dig rätt; ty slikom skall det på sistone väl gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Men de öfverträdare skola tillsammans förgås, och de ogudaktige på sistone utrotade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Men Herren hjelper de rättfärdiga; han är deras starkhet i nöd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Och Herren skall vara dem biståndig, och hjelpa dem; han skall undsätta dem ifrå de ogudaktiga, och frälsa dem; ty de trösta uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'En Psalm Davids, till åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Herre, straffa mig icke i dine vrede, och näps mig icke i dine grymhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Ty din skott äro fastnad i mig, och din hand trycker mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Det är intet helbregda på min kropp, för ditt hots skull; och ingen frid är i minom benom, för mina synders skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Ty mina synder gå öfver mitt hufvud; såsom en tung börda äro de mig för svåra vordna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Min sår lukta och ruttna, för min galenskaps skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Jag går krokot och mycket luto; hela dagen går jag sorgse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Ty mina länder borttorkas med allo, och intet helbregda är på minom kropp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Jag är allt för mycket förkrossad och sönderslagen; jag ryter för mins hjertas oros skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Herre, för dig är allt mitt begär; och min suckan är dig intet fördold.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mitt hjerta bäfvar; min kraft hafver mig förlåtit, och mins ögons ljus är icke när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Mine vänner och fränder stå gent mot mig, och se mina plågo, och mine näste träda fast fjerran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Och de der efter mina själ stå, de gildra för mig; och de som mig ondt vilja, rådslå huru de skada göra måga, och gå om med all list.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Men jag måste vara såsom en döfver, och höra intet; och såsom en dumbe, den sin mun intet upplåter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Och måste vara såsom en den der intet hörer, och den der ingen gensvar i sinom mun hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Men jag bidar, Herre, efter dig; du, Herre min Gud, varder mig hörandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Ty jag tänker, att de ju icke skola glädjas öfver mig; om min fot stapplade, skulle de högeligen berömma sig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Ty jag är gjord till att lida, och min värk är alltid för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Ty jag gör mina missgerning kunnoga, och sörjer för mina synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Men mine fiender lefva, och äro mägtige; de mig utan skuld hata, äro store.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Och de mig ondt göra för godt, sätta sig emot mig; derföre, att jag far efter det godt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Förlåt mig icke, Herre; min Gud, var icke långt ifrå mig. Skynda dig till att göra mig bistånd, Herre, min hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'En Psalm Davids, till att föresjunga för Jeduthun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Jag hafver satt mig före, jag vill taga mig vara, att jag icke syndar med mine tungo; jag vill hålla min mun tillbaka såsom med bett; efter jag så måste se den ogudaktiga för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Jag är tystnad och stilla vorden, och tiger om glädjena; och måste fräta mina sorg i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Mitt hjerta är brinnande i mig, och när jag tänker deruppå, varder jag upptänd; jag talar med mine tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Men, Herre, lär mig dock, att det måste få en ända med mig, och mitt lif ett mål hafva, och jag hädan måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Si, mine dagar äro en tvärhand för dig, och mitt lif är såsom intet för dig. Huru platt intet äro alla menniskor, de dock så säkre lefva. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'De gå bort såsom en skugge, och göra sig mycken onyttig oro; de samka tillhopa, och veta icke ho det få skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Nu, Herre, vid hvad skall jag trösta mig? Uppå dig hoppas jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Fräls mig ifrån alla mina synder, och låt mig icke dem galnom till spott varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Jag vill tiga, och icke upplåta min mun; du skall väl görat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Vänd dina plågo ifrå mig; ty jag är försmäktad för dine hands straff.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'När du en tuktar för syndenes skull, så varder hans fägring förtärd såsom af mal. Ack! huru platt intet äro dock alla menniskor. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Hör mina bön, Herre, och förnim mitt ropande, och tig icke öfver mina tårar; ty jag är en främling för dig, och en gäst såsom alle mine fäder. Håll upp af mig, att jag vederqvicker mig, förr än jag bortfar, och är icke mer här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Jag förbidde Herran; och han böjde sig till mig, och hörde mitt rop;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Och drog mig utu den grufveliga kulone, och utu träcken; och satte mina fötter uppå ett hälleberg, så att jag visst gå kan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Och hafver gifvit mig en ny viso i munnen till att lofva vår Gud. Det skola månge se, och frukta Herran, och hoppas uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Säll är den som sitt hopp sätter till Herran, och icke vänder sig till de högfärdiga, och de der med lögn umgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Herre, min Gud, stor äro din under, och dine tankar som du på oss bevisar; dig är ingen ting lik. Jag vill förkunna dem, och deraf säga, ändock de stå icke till att räkna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Offer och spisoffer behaga dig intet; men öronen hafver du öppnat mig. Du vill hvarken bränneoffer eller syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Då sade jag: Si, jag kommer; i bokene är skrifvet om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Din vilja, min Gud, gör jag gerna; och din lag hafver jag i mitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Jag vill predika rättfärdigheten uti den stora församlingen. Si, jag vill icke låta stoppa mig munnen till; Herre, du vetst det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Dina rättfärdighet fördöljer jag icke i mitt hjerta; om dina sanning och om dina salighet talar jag. Jag fördöljer icke dina godhet och trohet, uti den stora församlingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Men, Herre, vänd dock icke dina barmhertighet ifrå mig; låt dina godhet och trohet bevara mig alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Ty mig är ondt uppåkommet, der intet tal på är; mina synder hafva tagit mig fatt, så att jag icke se kan; de äro flera än håren på mitt hufvud, och mitt hjerta hafver öfvergifvit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Låt det täckas, dig, Herre, att du undsätter mig; skynda dig, Herre, till att hjelpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Skämme sig, och på skam komme, alle de som efter mina själ stå, att de skola förgöra henne; falle tillrygga, och komme på skam de mig ondt unna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Förskräcke sig uti sine skam de som öfver mig ropa: Så, så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Fröjde sig och vare glade i dig, alle de som fråga efter dig; och de som dina salighet älska, säga alltid: Herren vare högeliga lofvad. Ty jag är fattig och elände, men Herren sörjer för mig. Du äst min hjelpare och förlossare; min Gud, förtöfva icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Säll är den, som låter sig vårda; om den fattiga; honom skall Herren hjelpa i den onda tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Herren skall bevara honom, och hålla honom i lifve, och låta honom gå väl på jordene, och icke gifva honom uti hans fiendars vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Herren skall vederqvicka honom på hans sotesäng; du hjelper honom ifrån alla hans krankhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Jag sade: Herre, var mig nådelig; hela mina själ, ty jag hafver syndat emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Mine ovänner talade ondt emot mig: När kan han dö, och hans namn förgås?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'De komma till att skåda, och menat dock intet af hjertat; utan söka något, det de lasta måga, gå bort och förat ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Alle de som mig hata, tassla tillhopa emot mig, och tänka ondt öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'De hafva beslutit ett skalkastycke öfver mig: När han ligger, skall han intet uppstå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Och min vän, den jag mig betrodde, den mitt bröd åt, trampade mig under fötterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Men du, Herre, var mig nådelig, och hjelp mig upp, så vill jag vedergälla dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Derpå märker jag, att du ett behag till mig hafver, att min fiende icke skall glädja sig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Men mig uppehåller du för mina fromhets skull, och ställer mig inför ditt ansigte evinnerliga. Lofvad vare Herren, Israels Gud, ifrån nu, allt intill evighet. Amen, Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'En undervisning, Korah barnas, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Såsom hjorten ropar efter friskt vatten, så ropar min själ, Gud, till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Min själ törster efter Gud, efter den lefvande Gud. När skall jag dertill komma, att jag måtte se Guds ansigte?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Mine tårar äro min spis dag och natt, då man dagliga till mig säger: Hvar är nu din Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'När jag nu derpå tänker, så utgjuter jag mitt hjerta vid mig sjelfvan; ty jag ville gerna gå med hopenom, och med dem vandra till Guds hus; med glädje och tacksägelse ibland hopen som högtid hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Hvad bedröfvar du dig, min själ, och äst så orolig i mig? Hoppas uppå Gud; ty jag skall ännu tacka honom, att han hjelper mig med sitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Min Gud, bedröfvad är min själ i mig; derföre tänker jag på dig, i det land vid Jordan, och Hermonim, på de litsla bergena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Dine floder fräsa fast, så att ett djup brusar här, och ett djup der; alle dine vattuvågor och böljor utöfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Om dagen hafver Herren utlofvat sina godhet, och om nattene sjunger jag honom, och beder till mins lifs Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Jag säger till Gud, min klippa: Hvi hafver du förgätit mig? Hvi måste jag gå så sorgse, när min fiende mig tränger?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Det är såsom ett mord i mina ben, att mine fiender skämma mig; då de dagliga till mig säga: Hvar är nu din Gud? Hvad bedröfvar du dig, min själ, och äst så orolig i mig? Hoppas uppå Gud; ty jag skall ännu tacka honom, att han mitt ansigtes hjelp och min Gud är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Döm mig, Gud, och uträtta min sak emot det oheliga folk; och fräls mig ifrå de falska och onda menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Ty du äst, Gud, min starkhet; hvi bortdrifver du mig? Hvi låter du mig gå så sorgse, då min fiende tränger mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sänd ditt ljus och dina sanning, att de leda mig, och föra mig till ditt helga berg, och till dina boning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Att jag ingår till Guds altare, till Gud, som min glädje och fröjd är, och tackar dig, Gud, på harpo, min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Hvad bedröfvar du dig, min själ, och äst så orolig i mig? Hoppas uppå Gud; ty jag skall ännu tacka honom, att han mitt ansigtes hjelp och min Gud är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'En undervisning Korah barnas, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Gud, vi hafve med våra öron hört, våre fäder hafva det förtäljt oss, hvad du i deras dagar gjort hafver fordom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Du hafver med dine hand fördrifvit Hedningarna; men dem hafver du insatt. Du hafver förderfvat folken; men dem hafver du utvidgat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Ty de hafva icke intagit landet genom sitt svärd, och deras arm halp dem intet; utan din högra hand, din arm och ditt ansigtes ljus; ty du hade ett behag till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Gud, du äst den samme min Konung, som Jacob hjelp tillsäger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Igenom dig skole vi nederslå våra fiendar. I ditt Namn vilje vi undertrampa dem som sig emot oss sätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Ty Jag förlåter mig icke uppå min båga, och mitt svärd kan intet hjelpa mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Utan du hjelper oss ifrå våra fiendar, och gör dem till skam, som hata oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Vi vilje dagliga berömma oss af Gudi, och tacka dino Namne evinnerliga. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Hvi bortdrifver du då nu oss, och låter oss till skam varda; och drager icke ut i vårom här?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Du låter oss fly för våra fiendar, att de, som oss hata, skola beröfva oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Du låter uppäta oss såsom får, och förströr oss ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Du säljer ditt folk förgäfves, och tager der intet före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Du gör oss till smälek vårom grannom; till spott och hån dem som omkring oss äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Du gör oss till ett ordspråk ibland Hedningarna, och att folken rista hufvudet öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Dagliga är min smälek för mig, och mitt ansigte är fullt med skam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Att jag måste de försmädare och lastare höra, och fienderna och de hämndgiruga se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Allt detta är öfver oss kommet, och vi hafve dock intet förgätit dig, eller otroliga i ditt förbund handlat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Vårt hjerta är icke affallet, eller vår gång viken ifrå din väg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Att du så sönderslår oss ibland drakar, och öfvertäcker oss med mörker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Om vi vår Guds Namn förgätit hade, och våra händer upplyft till en främmande Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Det kunde Gud väl finna. Nu känner han ju vår hjertans grund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Ty vi varde ju dagliga för dina skull dräpne, och äro räknade såsom slagtefår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Uppväck dig, Herre; hvi sofver du? Vaka upp, och bortdrif oss icke med allo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Hvi fördöljer du ditt ansigte; och förgäter vårt elände och tvång?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Ty vår själ är nederböjd till jordena; vår buk låder vid jordena. Statt upp, hjelp oss, och förlös oss, för dina godhets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'En brudvisa och undervisning, Korah barnas, om rosena, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Mitt hjerta diktar en skön viso, jag vill sjunga om en Konung; min tunga är en god skrifvares penne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Du äst den dägeligaste ibland menniskors barn. Täckelige äro dine läppar; derföre välsignar dig Gud evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Bind ditt svärd vid din sido, du hjelte; och pryd dig härliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Lyckosamliga gånge dig i dinom skrud; drag fram för sanningenes skull, och till att behålla de elända vid rätt; så skall din högra hand bevisa under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Skarp äro din skott; så att folken för dig skola nederfalla, midt ibland Konungens fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Gud, din stol blifver alltid och i evighet; dins rikes spira är en rättvis spira.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Du älskar rättfärdigheten, och hatar ogudaktigt väsende; derföre hafver Gud, din Gud, smort dig med glädjenes oljo, mer än dina medbröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Dina kläder äro klart myrrham, aloe och kezia; när du i dine sköna härlighet utu de elphenbenspalats utgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Uti dinom skrud gå Konungadöttrar. Bruden står på dine högra hand, uti klart kosteligit guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Hör dotter, se uppå, och böj dina öron; förgät ditt folk, och dins faders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Så skall Konungen få lust till dina dägelighet; ty han är din Herre, och du skall tillbedja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Dottren Tyrus skall vara der med skänker; de rike i folkena skola bedja inför dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Konungens dotter är ganska härlig invärtes; hon är klädd i gyldene stycke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Man förer henne uti stickad kläder in till Konungen; och hennes leksystrar, jungfrurna, som efter henne gå, förer man till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Man förer dem med glädje och gamman, och de gå in i Konungens palats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Uti dina fäders stad skall du söner få; dem skall du sätta till Förstar i hela verldene. Jag skall tänka uppå ditt Namn, barn efter barn; derföre skola folken tacka dig alltid och i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'En visa, Korah barnas, om ungdomen, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Gud är vår tillflykt och starkhet; en hjelp uti de stora bedröfvelser, som oss uppåkomne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Derföre frukte vi oss intet, om än verlden förginges, och bergen midt i hafvet sönko;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Om än hafvet rasade och svallade, så att för dess bullers skull bergen omkullföllo. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Likväl skall Guds stad lustig blifva med sina brunnar, der dens Högstas helga boningar äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Gud är när dem derinne; derföre skall han väl blifva. Gud hjelper honom bittida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Hedningarna måste förtvifla, och Konungariken falla; jorden måste förgås, då han sig höra låter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Herren Zebaoth är med oss. Jacobs Gud är vårt beskydd. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Kommer, och ser Herrans verk, den på jordene sådana förstöring gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Den örlig stillar i hela verldene, sönderbryter bågan, sönderbråkar spetsen, och uppbränner vagnarna med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Varer stilla, och besinner att jag är Gud. Jag skall vinna pris ibland Hedningarna; jag skall vinna pris på jordene. Herren Zebaoth är med oss. Jacobs Gud är vårt beskydd. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'En Psalm, till att föresjunga, Korah barnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Klapper med händerna, all folk, och fröjdens Gudi med gladsamma röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Ty Herren, den Aldrahögste, är förskräckelig, en stor Konung på hela jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Han skall tvinga folk under oss, och Hedningar under våra fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Han utväljer oss till en arfvedel, Jacobs härlighet, den han älskar. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Gud är uppfaren med fröjd, och Herren med klar basun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Lofsjunger, lofsjunger Gudi; lofsjunger, lofsjunger vårom Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Ty Gud är Konung på hela jordene. Lofsjunger honom förnufteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Gud är Konung öfver Hedningarna. Gud sitter på sinom helga stol. Förstarne ibland folken äro församlada till ett folk Abrahams Gudi; ty Gud är fast upphöjd, när herrarna på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'En Psalmvisa, Korah barnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Stor är Herren, och högt berömd, uti vår Guds stad, på hans helga berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Det berget Zion är såsom en skön telning, på hvilko hela landet tröster; på den sidone norrut ligger den stora Konungens stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Gud är känd i hans palats, att han beskärmaren är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Ty si, Konungar äro församlade, och med hvarannan framdragne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'De hafva förundrat sig, då de detta sågo; vordo häpne och omstörta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Bäfvande är dem der påkommet, ångest såsom ene födande qvinno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Du sönderbråkar skeppen i hafvet, igenom östanväder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Såsom vi hört hafve, så se vi det på Herrans Zebaoths stad, vår Guds stad. Gud håller honom vid magt evinnerliga. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Gud, vi förbide dina godhet i ditt tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Gud, såsom ditt Namn, så är ock ditt lof, allt intill verldenes ändar; din högra hand är full med rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Berget Zion fröjde sig, och Juda döttrar vare glada, för dina rätters skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Går omkring Zion och beskåder det; täljer dess torn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Gifver granna akt uppå dess murar, och upphöjer dess palats; på det man derom må förkunna för efterkommanderna. Ty denne Guden är vår Gud, alltid och evinnerliga; han förer oss såsom ungdomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'En Psalm, till att föresjunga, Korah barnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Hörer till, all folk; akter häruppå, alle I, som på denna tid lefven;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Både den menige man och herrar, både rike och fattige; den ene med den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Min mun skall tala vishet, och mitt hjerta förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Vi vilje ett godt ordspråk höra, och en skön dikt på harpo spela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Hvi skulle jag frukta mig i de onda dagar, när mina förtryckares ondska omfattar mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Hvilke sig förlåta uppå sitt gods, och trotsa uppå sina stora rikedomar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Kan dock en broder ingen förlösa, eller Gudi någon försona;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Ty det kostar för mycket att förlösa deras själ; så att han måste låta det bestå evinnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Om han ock än länge lefver, och grafvena icke ser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Ty man skall se, att sådana vise dock dö, så väl som de dårar och galne förgås, och måste låta sitt gods androm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Med deras tankar står det alltså: Deras hus vara förutan ända, deras boningar blifva ifrå slägte till slägte, och de hafva stora äro på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Likväl kunna de icke blifva i sådana värdighet; utan måste hädan såsom fä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Denna deras handel är allsamman galenskap; likväl lofva det deras efterkommande med sin mun. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'De ligga i helvete såsom får, döden gnager dem; men de fromme skola hasteliga få råda öfver dem, och deras trotsan måste förgås; uti helvete måste de blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Men Gud skall förlösa mina själ utu helvetes våld; ty han hafver upptagit mig. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Sköt der intet om, när en rik varder, om hans huses härlighet stor varder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Ty han skall i sin dödstid intet med sig taga, och hans härlighet far intet efter honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Utan han tröstar på detta goda lefvandet, och prisar det, när en gör sig goda dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Så fara de efter sina fäder, och få aldrig se ljuset. Korteliga: När en menniska är i värdighet, och hafver icke förstånd, så far hon hädan såsom fä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'En Psalm Assaphs. Herren Gud den mägtige talar, och kallar verldena, ifrå solenes uppgång, allt intill nedergången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Af Zion går upp Guds härliga sken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Vår Gud kommer, och tiger intet. Förtärande eld går för honom, och omkring honom en mägtig storm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Han kallar himmel och jord, att han skall döma sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Församler mig mina heliga, som förbundet mer akta än offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Och himlarna skola förkunna hans rättfärdighet; ty Gud är domaren. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Hör, mitt folk, låt mig tala; Israel, låt mig ibland dig betyga: Jag Gud är din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'För ditt offers skull straffar jag dig intet; äro dock dine bränneoffer alltid för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Jag vill icke taga oxar utu ditt hus, eller bockar utu dine stall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Ty all djur i skogenom äro mine, och boskapen på bergen, der de vid tusendetal gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Jag känner alla foglar på bergen, och allahanda djur på markene äro för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Om mig hungrade, ville jag intet säga dig deraf; ty jordenes krets är min, och allt det deruti är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Menar du, att jag oxakött äta vill, eller bockablod dricka?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Offra Gudi tackoffer, och betala dem Högsta ditt löfte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Och åkalla mig i nödene; så vill jag hjelpa dig, så skall du prisa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Men till den ogudaktige säger Gud: Hvi förkunnar du mina rätter, och tager mitt förbund i din mun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Efter du dock hatar tuktan, och kastar min ord bakom dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'När du ser en tjuf, så löper du med honom, och hafver din del med horkarlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Din mun låter du tala det ondt är, och din tunga bedrifver falskhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Du sitter och talar emot din broder; dine moders son förtalar du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Detta gör du, och jag tiger. Det menar du, att jag skulle vara lika som du; men jag skall straffa dig, och sätta dig det under ögonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Märker dock det, I som Gud förgäten, att jag icke en gång bortrycker, och är så ingen förlösare mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Den der tack offrar, han prisar mig; och der är vägen, att jag visar honom Guds salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'En Psalm Davids, till att föresjunga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Då den Propheten Nathan till honom kom, när han till BathSeba ingången var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Gud, var mig nådelig, efter dina godhet, och afplana mina synd, efter dina stora barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Två mig väl af mine missgerning, och rensa mig ifrå mine synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Förty jag känner mina missgerning, och min synd är alltid för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Mot dig allena hafver jag syndat, och illa gjort för dig; på det du må rätt blifva i din ord, och icke straffad blifva, då du dömd varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Si, jag är af syndelig säd född, och min moder hafver mig i synd aflat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Si, du hafver lust till sanningen, den i det fördolda ligger; du låter mig veta den hemliga visheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Skära mig med isop, att jag må ren varda; två mig, att jag må snöhvit varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Låt mig höra glädje och fröjd, att de ben, som du förkrossat hafver, måga fröjda sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Vänd bort ditt ansigte ifrå mina synder, och afplana alla mina missgerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Skapa i mig, Gud, ett rent hjerta, och gif i mig en ny viss anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Förkasta mig icke ifrå ditt ansigte, och tag icke din Helga Anda ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Tröst mig igen med dine hjelp, och den frimodige anden uppehålle mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Ty jag vill lära öfverträdarena dina vägar, att syndarena måga vända sig till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Fräls mig ifrå blodskulder, Gud, som min Gud och Frälsare är; att min tunga må lofva dina rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Herre, upplåt mina läppar, att min mun må förkunna din pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Ty du hafver icke lust till offer, eljest ville jag väl gifva dig det; och bränneoffer behaga dig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'De offer, som Gudi behaga, äro en bedröfvad ande. Ett bedröfvadt och förkrossadt hjerta varder du, Gud, icke föraktandes. Gör väl vid Zion, efter dina nåde; uppbygg murarna i Jerusalem. Då skola dig behaga rättfärdighetenes offer, bränneoffer och heloffer; då skall man oxar uppå ditt altare offra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'En undervisning Davids, till att föresjunga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Då Doeg den Edomeen kom, och bebådade Saul, och sade: David är uti Ahimelechs hus kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Hvad högmodas du, tyrann, att du kan skada göra? efter dock Guds godhet ännu dagliga varar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Din tunga far efter skada, och skär med lögn, såsom en skarp rakoknif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Du talar heldre ondt än godt, och heldre falskt än rätt. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Du talar gerna allt det som till förderf tjenar, med falska tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Derföre skall ock Gud med allo förderfva dig, och sönderkrossa dig, och utu hyddone rycka dig, och utu de lefvandes lande utrota dig. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Och de rättfärdige skola det se, och frukta sig, och skola le åt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Si, det är den man, som icke höll Gud för sina tröst; utan förlät sig uppå sin stora rikedom, och var mägtig till att göra skada. Men jag skall blifva såsom ett grönt; oliveträ i Guds hus; jag förlåter mig på Guds godhet alltid och förutan ända. Jag tackar dig evinnerliga, ty du kan väl görat, och vill förbida ditt Namn, ty dine helige hafva der fröjd utinnan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'En undervisning Davids, i chorenom ymsom till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'De galne säga i sitt hjerta: Det är ingen Gud till; de doga intet, och äro en styggelse vordne uti deras onda väsende; ingen är som godt gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Gud såg af himmelen uppå menniskors barn, att han måtte se, om der någor förståndig vore, den efter Gud frågade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Men de äro alle affallne, och allesammans odugelige; der är ingen, som godt gör, ja, icke en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Vilja då de ogerningsmän icke låta säga sig, de der mitt folk fräta, på det de skola föda sig? Gud åkalla de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Men der frukta de sig, der intet fruktande är; ty Gud förskingrar de plågares ben. Du gör dem till skam, ty Gud förmår dem. Ack, att den hjelp utaf Zion öfver Israel komma måtte, och Gud sitt fångna folk förlöste; så skulle Jacob fröjda sig, och Israel glad vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'En undervisning Davids, till att föresjunga på strängaspel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Då de af Siph kommo, och sade till Saul: David hafver fördolt sig när oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Hjelp mig, Gud, genom ditt Namn, och skaffa mig rätt genom dina magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Gud, hör min bön; förnim mins muns tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Ty stolte sätta sig emot mig, och våldsverkare stå efter mina själ; och hafva intet Gud för ögon. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Si, Gud står med mig; Herren uppehåller mina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Han skall betala minom fiendom det onda; förstör dem genom dina trohet; Så vill jag göra dig ett glädjeoffer, och tacka, Herre, dino Namne, att det så trösteligit är. Ty du hjelper mig utur all min nöd, att mina ögon måga på mina fiendar lust se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'En undervisning Davids, till att föresjunga på strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Gud, hör mina bön, och fördölj dig icke för mitt bedjande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Akta uppå mig, och hör mig, huru jämmerliga jag klagar och gråter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Att fienden så ropar, och den ogudaktige tränger; ty de vilja komma mig på skada, och äro mig svårliga vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Mitt hjerta ängslas i mitt lif, och dödsens fruktan är fallen uppå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Fruktan och bäfvande är mig uppåkommet, och grufvelse hafver öfverfallit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Jag sade: O! hade jag vingar såsom dufvor, att jag måtte flyga, och någorstäds blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Si, så ville jag draga mig långt bort, och blifva i öknene. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Jag ville skynda mig, att jag måtte undkomma för storm och oväder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Gör, Herre, deras tungor oens, och låt dem förgås; ty jag ser orätt och trätor i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Sådant går dag och natt allt omkring, innan hans murar; möda och arbete är derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Orätten regerar derinne; lögn och bedrägeri vänder intet igen uppå hans gator.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Om min fiende skämde mig, ville jag det lida; och om min hatare trugade mig, ville jag gömma mig bort för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Men du äst min stallbroder, min skaffare, och min kände vän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Vi, som vänliga omginges inbördes med hvarannan, vi vandrade i Guds hus tillhopa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Döden öfverfalle dem, och fare sig lefvande uti helvetet; ty all skalkhet är uti deras hop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Men jag vill ropa till Gud, och Herren skall hjelpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Om afton, morgon och middag vill jag klaga och gråta; så skall han höra mina röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Han förlöser mina själ ifrå dem som vilja till verka med mig, och skaffar henne ro; ty de äro många emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Gud skall hörat, och späka dem, den alltid blifver. Sela. Ty de vända sig icke, och frukta Gud intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Ty de lägga sina händer uppå hans fridsamma, och ohelga hans förbund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Deras mun är halare än smör, och hafva dock örlig i sinnet; deras ord äro lenare än olja, och äro dock bar svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Kasta dina omsorg uppå Herran, han skall försörja dig; och skall icke låta den rättfärdiga i oro blifva till evig tid. Men Gud, du skall nederstörta dem uti den djupa kulona; de blodgiruge och falske skola icke komma till sin halfva ålder; men jag hoppas uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Ett gyldene klenodium Davids, till att föresjunga, om den dumba dufvona ibland de främmanda, då de Philisteer grepo honom i Gath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Gud, var mig nådelig, ty menniskor vilja nedersänka mig; dagliga strida de, och tränga mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Mine fiender nedersänka mig dagliga ty månge strida emot mig högmodeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'När jag fruktar mig, så hoppas jag uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Jag vill prisa Guds ord; på Gud vill jag hoppas, och intet frukta mig. Hvad skulle något kött göra mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Dagliga strida de emot min ord; alle deras tankar äro, att de må göra mig ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'De hålla tillhopa, och vakta, och taga vara uppå mina hälar, huru de mina själ gripa måga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Hvad de ondt göra, det är allaredo tillgifvet (säga de). Gud störte sådana menniskor neder utan alla nåde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Räkna min flykt; fatta mina tårar uti din lägel; utan tvifvel räknar du dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Då måste mina fiender tillbakavända. När jag ropar, förmärker jag, att du min Gud äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Jag vill prisa Guds ord; Herrans ord vill jag prisa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Uppå Gud hoppas jag, och fruktar mig intet; hvad kunna menniskor göra mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Jag hafver gjort dig löfte, Gud, att jag dig tacka vill. Ty du hafver frälst mina själ ifrå döden, mina fötter ifrå fall; att jag må vandra för Gudi uti de lefvandes ljuse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Ett gyldene klenodium Davids, till att föresjunga, att han icke borto blef, då han för Saul flydde in i kulona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Gud, var mig nådelig, var mig nådelig; ty uppå dig tröstar min själ, och under dina vingars skugga hafver jag tillflykt, tilldess att det onda går öfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Jag ropar till Gud, den Aldrahögsta; till Gud, den på min jämmer en ända gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Han sänder af himmelen, och hjelper mig ifrå mina förtryckares försmädelse. Sela. Gud sänder sina godhet och trohet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Jag ligger med mine själ ibland lejon. Menniskors barn äro lågar; deras tänder äro spjut och pilar, och deras tungor skarp svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Upphöj dig, Gud, öfver himmelen, och dina äro öfver alla verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'De ställa för min gång nät, och nedertrycka mina själ; de grafva för mig ena grop, och falla sjelfve deruti. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Mitt hjerta är redo, Gud, mitt hjerta är redo, att jag skall sjunga och lofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Vaka upp, min ära, vaka upp, psaltare och harpor; bittida vill jag uppvaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Herre, jag vill tacka dig ibland folken; jag vill lofsjunga dig ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Ty din godhet är så vidt som himmelen är, och din sannfärdighet så vidt som skyarna gå. Upphöj dig, Gud, öfver himmelen, och din ära öfver alla verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Ett gyldene klenodium Davids, till att föresjunga, att han icke förgicks.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Ären I då dumbar, att I icke tala viljen hvad rätt är; och döma hvad likt är, I menniskors barn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Ja, af blotta ondsko gören I orätt i landena; och följen efter med edra händer, och gören öfvervåld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'De ogudaktige äro afvoge af moderlifvet; de ljugare fara ville allt ifrå moderlifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'De rasa såsom en orm rasar; såsom en döf huggorm, den sitt öra tillstoppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Att han icke skall höra kjusarens röst; besvärjarens, den väl besvärja kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Gud, sönderbryt deras tänder i deras mun. Sönderslå, Herre, oxlatänderna af de unga lejon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'De skola förgås såsom vatten, det bortflyter. De skjuta med sina pilar, men de gå sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'De förgås, såsom en snigel försmäktas; såsom ene qvinnos otidig börd, se de intet solena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Förr än edor törne på buskanom mogne varda, skall vreden i växtenom bortrycka dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Den rättfärdige skall glädja sig, när han en sådana hämnd ser; och skall två sina fötter uti dens ogudaktigas blod; Att man skall säga: Den rättfärdige måste det ju njuta; Gud är ju ännu domare på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Ett gyldene klenodium Davids, till att föresjunga, att han icke borto blef, då Saul sände bort, och lät bevara hans hus, på det att han måtte dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Fräls mig, min Gud, ifrå mina fiendar, och beskydda mig för dem som sig emot mig sätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Fräls mig ifrå de ogerningsmän, och hjelp mig ifrå de blodgiriga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Ty si, Herre, de vakta efter mina själ; de starke församla sig emot mig, utan min skuld och missgerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'De löpa, utan min skuld, och bereda sig. Vaka upp, och möt mig, och se dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Du, Herre Gud Zebaoth, Israels Gud, vaka upp, och hemsök alla Hedningar. Var ingom nådelig af dem, som sådane förstockade ogerningsmän äro. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Om aftonen låt dem ock tjuta igen, såsom hundar, och löpa omkring i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Si, de tala med hvarannan; svärd äro i deras läppar. Ho skulle det höra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Men, Herre, du skall le åt dem, och bespotta alla Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'För deras magt håller jag mig intill dig; ty Gud är mitt beskärm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Gud bevisar mig rikeliga sina godhet; Gud låter mig lust se på mina fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Dräp dem icke, att mitt folk icke förgäter det; men förströ dem med dine magt, Herre, vår sköld, och nedslå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Deras lära är allsamman synd, och blifva fast i sine högfärd; och predika intet annat än bannor och motsägelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Förgör dem utan alla nåd; förgör dem, så att de intet mer äro, och besinna måga, att Gud är rådandes i Jacob, öfver alla verldena. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Om aftonen låt dem ock tjuta igen, såsom hundar, och löpa omkring i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Låt dem löpa hit och dit efter mat, och tjuta om de icke mätte varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Men jag vill sjunga om dina magt, och lofva om morgonen dina godhet; ty du äst mitt beskärm och tillflykt i mine nöd. Jag vill lofsjunga dig, min tröst; ty du, Gud, äst mitt beskärm, och min gunstige Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Ett gyldene klenodium Davids, till att föresjunga, om ett gyldene rosenspann, till att lära;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Då han stridt hade med de Syrer i Mesopotamien, och med de Syrer af Zoba; då Joab omvände, och slog de Edomeer i saltdalenom, tolftusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Gud, du som oss bortdrifvit och förstrött hafver, och vast vred, trösta oss igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Du, som jordena hafver berört och remna låtit, hela hennes refvor, den så förfallen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Ty du hafver bevist dino folke ett hårdt ting; du hafver gifvit oss en dryck vin, att vi omkullfalla måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Men du hafver dock gifvit ett tecken dem som dig frukta; hvilket de uppreste, att de skulle säkre vara. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'På det dine vänner skola förlöste varda; så hjelp nu med dine högra hand, och hör oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Gud talar i sinom helgedom, dess gläder jag mig; och vill dela Sichem, och afmäta Succoths dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Gilead är min, min är Manasse; Ephraim är mins hufvuds magt; Juda är min Förste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moab är mitt tvättekar; mina skor sträcker jag utöfver Edom; Philistea fägnar mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Ho vill föra mig uti en fast stad? Ho leder mig intill Edom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Skall icke du göra det, Gud, som oss bortdrifver; och icke utdrager, Gud, med vår här? Skaffa oss bistånd i nödene; ty menniskors hjelp är fåfäng. Med Gudi vilje vi mägtig ting göra; han skall underträda våra fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'En Psalm Davids, till att föresjunga på strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Hör, Gud, mitt rop, och akta uppå mina bön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Härnedre på jordene ropar jag till dig, när mitt hjerta i ångest är: För mig dock uppå en hög klippo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Ty du äst min tillflykt; ett starkt torn för mina fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Jag vill bo uti dine hyddo till evig tid, och min tröst hafva under dina vingar. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Ty du, Gud, hörer mina löften; du lönar dem väl, som ditt Namn frukta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Du gifver Konungenom långt lif, att hans år vara ifrå slägte till slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Att han må evigliga för Gudi sittandes blifva. Bevisa honom godhet och trohet, att de bevara honom; Så vill jag lofsjunga dino Namne evinnerliga, att jag må betala mina löften dageliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'En Psalm Davids, för Jeduthun, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Min själ väntar allenast i stillhet efter Gud, den mig hjelper.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Ty han är min tröst, min hjelp, mitt beskärm; att intet ondt skall omstörta mig, ehuru stort det ock är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Huru länge gån I så alle enom efter; att I mågen dräpa honom, såsom en lutande vägg, och en remnad mur?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'De tänka allenast, huru de måga förtrycka honom; vinnlägga sig om lögn, gifva god ord; men i hjertana banna de. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Men min själ väntar allenast efter Gud; ty han är mitt hopp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Han är min tröst, min hjelp, och mitt beskärm, att jag icke faller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'När Gudi är min salighet, min ära, mins starkhets klippa; mitt hopp är till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Hoppens uppå honom alltid; I folk, utgjuter edor hjerta för honom. Gud är vårt hopp. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Men menniskorna äro dock ju intet; de myndige fela ock. De väga mindre än intet, så månge som de äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Förlåter eder icke uppå orätt och öfvervåld; håller eder icke till sådant, det intet värdt är. Faller eder rikedom till, så lägger icke hjertat deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Gud hafver ett ord talat; det hafver jag ofta hört, att Gud allena mägtig är. Och du, Herre, äst nådelig; och lönar hvarjom och enom såsom han förtjenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'En Psalm Davids, då han var i Juda öken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Gud, du äst min Gud, bittida vakar jag upp till dig. Min själ törstar efter dig, mitt kött längtar efter dig, uti ett torrt och törstigt land, der intet vatten är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Der ser jag efter dig i dinom helgedom, att jag måtte skåda dina magt och äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Ty din godhet är bättre än lif. Mine läppar prisa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Der ville jag gerna lofva dig i mina lifsdagar, och upplyfta mina händer, i ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Det vore mins hjertas fröjd och lust, då jag dig med gladom mun lofva skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'När jag mig i säng lägger, så tänker jag uppå dig; när jag uppvaknar, så talar jag om dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Ty du äst min hjelpare, och under dina vingars skugga vill jag fröjda mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Min själ håller sig intill dig; din högra hand uppehåller mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Men de stå efter mina själ, till att öfverfalla mig; de måste under jordena nederfara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'De måste falla i svärd, och räfvomen till lott blifva. Men Konungen fröjdar sig i Gudi; den vid honom svär, han skall prisad varda; ty de lögnmunnar skola tillstoppade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Hör, Gud, mina röst, i mine klagan. Bevara mitt lif för den grufveliga fiendan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Förskyl mig för de ondas församling; för deras hop, som illa göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'De der skärpa sina tungor, såsom ett svärd, och skjuta med sina förgiftiga ord, såsom med pilar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Att de måga lönliga skjuta den fromma; med hast skjuta de uppå honom, utan all fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'De äro djerfve med sin onda anslag, och talas vid, huru de snaror lägga vilja, och säga: Ho kan se dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'De dikta skalkhet, och hållat hemliga; de äro illfundige, och hafva listig skalkastycke före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Men Gud skall hasteliga skjuta dem, så att dem skall svida efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Deras egen tunga skall fälla dem; så att dem bespotta skall hvar och en, som dem ser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Och alla menniskor, som det se, skola frukta sig, och säga: Det hafver Gud gjort; och förmärka, att det är hans gerning. De rättfärdige skola fröjda sig af Herranom, och förtrösta uppå honom, och alla fromma hjertan skola deraf berömma sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'En Psalm Davids, för en viso till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Gud, man lofvar dig i stillhet i Zion, och dig betalar man löfte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Du hörer bön, derföre kommer allt kött till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Vår missgerning trycker oss hardeliga. Förlåt oss våra synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Säll är den du utväljer, och hafver honom till dig, att han skall bo i dina gårdar; han hafver en rik tröst af ditt hus, det helga templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Hör oss, efter den underliga rättfärdigheten, Gud vår salighet; du, som äst allas hopp, på jordene, och fjerran på hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Du, som bergen stadig gör i sine kraft, och begjordad äst med magt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Du, som stillar hafsens fräsande, dess böljors fräsande, och folks buller;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Att de, som vid de landsändar bo, skola förskräcka sig för din tecken; du gläder allt det som röres, både om morgon och om afton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Du besöker landet, och vattnar det, och gör det mycket rikt; Guds källa hafver vatten tillfyllest; du låter dess korn väl trifvas; ty alltså brukar du landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Du vattnar dess fårar, och fuktar det upplöjdt är; med regn gör du det blött, och välsignar dess växt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Du kröner året med ditt goda, och din fotspår drypa af fetma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'De boningar i öknena äro ock feta, så att de drypa; och högarna äro allt omkring lustige. Hjordmarken är full med får, och dalarna stå tjockt med säd; så att man glädes dervid, och sjunger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'En Psalmvisa, till att föresjunga. Fröjdens Gudi, all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Lofsjunger, till att ära hans Namn; priser honom härliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Säger till Gud: Huru underliga äro dina gerningar! Dinom fiendom skall fela för dine stora magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'All land tillbedje dig, och lofsjunge dig; lofsjunge dino Namne. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Kommer och ser uppå Guds verk; den så underlig är i sina gerningar, ibland menniskors barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Han förvandlar hafvet uti det torra, så att man till fot öfver vattnet går. Dess fröjde vi oss i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Han är rådandes med sine kraft evinnerliga; hans ögon skåda på folken. De affällige skola icke kunna upphäfva sig. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Lofver, I folk, vår Gud; låter hans lof vidt hördt varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Den våra själ vid lif behåller, och låter våra fötter icke slinta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Ty, Gud, du hafver försökt oss, och pröfvat oss, såsom silfver pröfvadt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Du hafver fört oss uti häktelse; du hafver lagt en tunga på våra länder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Du hafver låtit komma menniskor öfver vårt hufvud. Vi äre komne i eld och i vatten; men du hafver utfört oss, och vederqvickt oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Derföre vill jag med bränneoffer gå in uti ditt hus, och betala dig mina löften;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Såsom jag mina läppar upplåtit hafver, och min mun talat hafver, i mine nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Jag vill göra dig fet bränneoffer af brändom vädrom; jag vill offra oxar och bockar. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Kommer hit, hörer till, alle I som Gud frukten; jag vill förtälja, hvad han mine själ gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Till honom ropade jag med min mun, och prisade honom med mine tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Om jag något orätt förehade i mitt hjerta, så, vorde Herren mig ej hörandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Derföre hörer mig Gud, och aktar uppå min bön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Lofvad vare Gud, den mina bön icke förkastar, eller vänder sina godhet ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'En Psalmvisa, till att föresjunga på strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Gud vare oss nådelig, och välsigne oss; han låte sitt ansigte lysa oss; Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Att vi på jordene måge känna hans väg, ibland alla Hedningar hans salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Gud, dig tacke folk; all folk tacke dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Folken fröjde sig och glädjes, att du dömer folken rätt, och regerar folken på jordene. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Gud, dig tacke folk; all folk tacke dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Landet gifver sina frukt. Gud, vår Gud välsigna oss. Gud välsigne oss, och all verlden frukte honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'En Psalmvisa Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Gud stånde upp, att hans fiender måga förströdde varda, och de honom hata, fly för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Fördrif dem, såsom en rök fördrifven varder; såsom vax försmälter för eld, så förgånge de ogudaktige för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Men de rättfärdige fröjde sig, och vare glade för Gudi, och fröjde sig af hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Sjunger Gudi, lofsjunger hans Namne; görer honom väg, som sakta framfar; han heter Herren; och glädjens för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Den en fader är åt faderlösa, och en domare för enkom; han är Gud i sin helga boning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'En Gud, som dem ensammom gifver huset fullt med barn; den der fångar utförer i rättom tid, och låter de affälliga blifva i det torra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Gud, då du utdrogst för ditt folk, då du gick i öknene; Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Då bäfvade jorden, och himlarna dröpo för denna Guden i Sinai; för Gudi, som Israels Gud är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Men nu gifver du, Gud, ett nådeligit regn; och ditt arf, det torrt är, vederqvicker du;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Att din djur måga bo deruti. Gud, du vederqvicker de elända med dine godhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Herren gifver ordet, med en stor Evangelisters skara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Konungarna för härarna äro med hvarannan vänner, och husäran utskifter rofvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'När I liggen i markene, så glimmar det såsom dufvovingar, hvilke såsom silfver och guld glittra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'När den Allsmägtige allestäds ibland dem Konungar sätter, så varder klart, der mörkt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Guds berg är ett fruktsamt berg, ett stort och fruktsamt berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Hvi springen I, stor berg? Gud hafver lust till att bo på detta berget, och Herren blifver der ock evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Guds vagn är mång tusende tusend. Herren är ibland dem på det helga Sinai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Du hafver farit upp i höjdena, och hafver fångat fängelset; du hafver undfått gåfvor för menniskorna; de affällige ock, att Herren Gud skall ändå likväl blifva der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Lofvad vare Herren dagliga. Gud lägger oss ena bördo uppå; men han hjelper oss ock. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Vi hafve en Gud, en Gud, den der hjelper, och Herran, Herran, den ifrå döden frälsar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Men Gud skall sönderslå hufvudet på sina fiendar, samt med deras hjessa, som blifva i deras synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Dock säger Herren: Jag vill hemta somliga ibland de feta; utu hafsens djup vill jag somliga hemta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Derföre skall din fot uti fiendernas blod färgad varda, och dine hundar skola det slicka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Man ser, Gud, huru du går; huru du, min Gud och Konung, i helgedomenom går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'De sångare gå framföre, der näst de spelmän, ibland pigor som slå på trummor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Lofver Herran Gud i församlingomen, för Israels brunn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Der är rådandes ibland dem den litsle BenJamin, Juda Förstar, med deras hopar, Sebulons Förstar, Naphthali Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Din Gud hafver upprättat ditt rike, det stärk, Gud, i oss; ty det är ditt verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'För ditt tempels skull i Jerusalem, skola Konungar föra dig skänker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Straffa djuret i rören, oxahoparna ibland deras kalfvar, de der drifva för penningars skull. Han förströr de folk, som gerna örliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'De Förstar utur Egypten skola komma; Ethiopien skall utsträcka sina händer till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'I Konungariken på jordene, sjunger Gudi; lofsjunger Herranom. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Den der vistas i himmelen, allestädes af begynnelsen; si, han skall gifva sino dundre kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Gifver Gudi magten; hans härlighet är i Israel, och hans magt i skyn. Gud är underlig i sinom helgedom; han är Israels Gud, han skall gifva folkena magt och kraft. Lofvad vare Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'En Psalm Davids, om roserna, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Gud, hjelp mig, ty vatten går allt intill mina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Jag sjunker ned i djup dy, der ingen botten uti är; jag är kommen i djup vatten, och floden vill fördränka mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Jag hafver ropat mig tröttan, min hals är hes, synen förgås mig; att jag så länge måste bida efter min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'De som mig utan skuld hata, äro flere än jag håren på hufvudet hafver; de som mig med oskäl förfölja och förderfva, äro mägtige; jag måste betala det jag intet röfvat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Gud, du vetst min galenskap, och mina skulder äro dig intet förskylda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Låt dem icke på mig till skam komma, som dig förbida, Herre, Herre Zebaoth; låt dem icke till blygd komma, som dig söka, Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Ty för dina skuld lider jag försmädelse; mitt ansigte är fullt med blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Jag är minom brödrom främmande vorden, och okänd mins moders barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Ty dins hus nitälskan uppfräter mig, och deras försmädelser, som dig häda, falla uppå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Och jag gret, och fastade bitterliga; och man begabbade mig dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Jag drog en säck uppå; men de gjorde der lek af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'De som i porten sitta, tassla om mig, och i dryckenskap qväder man om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Men jag beder, Herre, till dig, i behagelig tid; Gud, efter dina stora godhet, hör mig med dine trofasta hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Upptag mig utu träcken, att jag icke nedersjunker; att jag må frälst varda ifrå mina hatare, och utu de djupa vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Att vattufloden icke fördränker mig, och djupet icke uppsluker mig, och gapet på gropene icke igentäppes öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Hör mig, Herre, ty din godhet är tröstelig. Vänd dig till mig efter dina stora barmhertighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Och bortgöm icke ditt ansigte för dinom tjenare; ty mig är ångest. Hör mig snarliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Nalka dig till mina själ, och förlossa henne; förlossa mig för mina fiendars skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Du vetst min försmädelse, skam och blygd; alle mine fiender äro för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Försmädelse bråkar mig hjertat sönder, och kränker mig; jag vänter, att någor ville varkunna sig, men der är ingen; och efter hugsvalare, men jag finner ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Och de gåfvo mig galla äta, och ättiko dricka uti minom stora törst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Deras bord varde för dem en snara, till vedergällning, och till ena fällo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Deras ögon varde mörk, så att de intet se; och deras länder låt städse ostadiga vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Utgjut dina ogunst uppå dem, och din grymma vrede gripe dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Deras boning varde öde, och ingen vare som uti deras hyddom bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Ty de förfölja den du slagit hafver, och berömma att du slår dina illa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Låt dem falla uti den ena synden efter den andra, att de icke komma till dina rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Utskrapa dem utu de lefvandes bok; att de med de rättfärdiga icke uppskrefne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Men jag är elände, och hafver ondt; Gud, din hjelp beskydde mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Jag vill lofva Guds Namn med en viso, och vill högeliga ära honom med tacksägelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Det skall bättre täckas Herranom, än en stut, den horn och klöfvar hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'De elände se det, och glädja sig; och de som Gud söka, dem skall hjertat lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Ty Herren hörer de fattiga, och föraktar icke sina fångna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Honom lofve himmelen, jorden och hafvet, och allt det deruti röres.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Ty Gud skall hjelpa Zion, och bygga Juda städer; att man der bo skall, och besitta dem. Och hans tjenares säd skall ärfva dem; och de som hans Namn älska, skola blifva derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'En Psalm Davids, till att föresjunga, till åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Skynda dig, Gud, till att frälsa mig; Herre, till att hjelpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Skämme sig, och komme på skam, de som efter mine själ stå; vände tillrygga, och komme på skam, de mig ondt önska;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Att de måtte på skam komma igen, som öfver mig ropa: Så, så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Fröjde, och glädje sig i dig, de som efter dig fråga; och de som dina salighet älska, säga alltid: Gud vare högeliga lofvad. Men jag är eländig och fattig; Gud, var snar till mig; ty du äst min hjelpare och förlossare; min Herre, fördröj icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Herre, jag förtröstar uppå dig, låt mig aldrig på skam komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Fräls mig genom dina rättfärdighet, och hjelp mig ut; böj din öron till mig, och hjelp mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Var mig en stark tröst, dit jag alltid fly må, du som lofvat hafver att hjelpa mig; ty du äst min klippa och min borg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Min Gud, hjelp mig utu dens ogudaktigas hand, utu dens orättfärdigas och tyrannens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Ty du äst min tillflykt, Herre, Herre; mitt hopp allt ifrå minom ungdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Uppå dig hafver jag förlåtit mig, allt ifrå moderlifvet; du hafver dragit mig utu mine moders lif; min berömmelse är alltid af dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Jag är för mångom ett vidunder; men du äst min starka tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Låt min mun full vara af ditt lof och pris dagliga dags.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Förkasta mig icke uti min ålderdom; öfvergif mig icke, när jag svag varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Ty mine fiender tala emot mig, och de som efter mina själ vakta, de rådslå tillhopa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Och säga: Gud hafver öfvergifvit honom; jager efter, och griper honom; ty der är ingen hjelpare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Gud, var icke långt borto ifrå mig; min Gud, skynda dig till att hjelpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Skämme sig och förgås, de som emot mine själ äro; varde med skam och hån öfvertäckte, de som mitt värsta söka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Men jag vill alltid bida, och vill alltid föröka ditt lof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Min mun skall förkunna dina rättfärdighet, dagliga dags dina salighet, den jag icke alla räkna kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Jag går i Herrans, Herrans kraft; jag prisar dina rättfärdighet, ja, din allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Gud, du hafver lärt mig af min ungdom; derföre förkunnar jag ännu din under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Ock förlåt mig icke, Gud, i ålderdomen, när jag grå varder; tilldess jag förkunnar din arm barnabarnom, och dina magt allom dem som komma skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Gud, din rättfärdighet är hög, du som stor ting gör. Gud, ho är dig lik?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Ty du låter mig förfara mycken och stor ångest, och gör mig åter lefvande; och hemtar mig åter upp utu jordenes djup.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Du gör mig ganska storan, och styrker mig igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Så tackar jag ock dig med psaltarespel, för dina trofasthet, min Gud. Jag lofsjunger dig på harpor, du Helige i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Mine läppar och min själ, som du förlöst hafver, äro glade, och lofsjunga dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Ock talar min tunga dagliga dags om dina rättfärdighet; ty skämma måga sig, och på skam komma, de som mitt värsta söka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Salomos. Gud, gif Konungenom din dom, och dina rättfärdighet Konungens son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Att han må föra ditt folk till rättfärdighet, och hjelpa dina elända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Låt bergen frambära frid ibland folket, och högarna rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Han skall behålla det elända folk vid rätt, och hjelpa de fattiga, och förtrycka de försmädare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Man skall frukta dig, så länge sol och måne varar, ifrå barn och intill barnabarn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Han skall nederkomma såsom regn uppå ullskinn; såsom droppar, de der markena fukta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'I hans tid skall den rättfärdiga blomstras, och stor frid, tilldess att månen intet mer är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Han skall varda rådandes ifrå det ena hafvet till det andra, och ifrån älfvene allt intill verldenes ändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'För honom skola buga de som i öknene äro, och hans fiender skola sleka stoftet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'De Konungar vid hafvet och på öarna skola bära fram skänker; de Konungar utaf rika Arabien och Seba skola tillföra gåfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Alle Konungar skola tillbedja honom; alle Hedningar skola tjena honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Ty han skall frälsa den fattiga som ropar, och den elända som ingen hjelpare hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Han skall vara dem usla och fattiga nådelig, och de fattigas själar skall han hjelpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Han skall förlösa deras själar utu bedrägeri och öfvervåld, och deras blod skall dyrt aktadt varda för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Han skall lefva, och man skall gifva honom af guld utu rika Arabien, och man skall alltid bedja inför honom, dagliga skall man lofva honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'På jordene ofvanpå bergen skall korn stå tjockt; hans frukt skall bäfva såsom Libanon, och skall grönskas i städerna, såsom gräs på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Hans Namn skall blifva evinnerliga; så länge solen varar, skall hans Namn räcka intill efterkommanderna; och genom honom skola de välsignade varda; alle Hedningar skola prisa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Lofvad vare Herren Gud, Israels Gud, den allena under gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Och lofvadt vare hans härliga Namn evinnerliga; och all land varde full med hans äro. Amen, Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'En ända hafva Davids böner, Isai sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'En Psalm Assaphs. Visserliga hafver Israel Gud till tröst, der man rent hjerta hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Men jag hade sånär stapplat med mina fötter; mine steg hade fulltnär sluntit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Ty mig förtröt om de stortaliga, då jag såg, att dem ogudaktigom väl gick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Ty de äro i ingen dödsfara, utan stå faste såsom ett palats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'De äro icke i olycko, såsom andra menniskor, och varda icke, såsom andra menniskor, plågade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Derföre måste deras stolthet vara en kostelig ting, och deras öfvervåld måste heta allt väl gjordt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'De svälla i ansigtet som en fet buk; de göra hvad dem lyster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'De förakta all ting, och tala illa derom; och tala och lasta högmodeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Hvad de tala, det måste vara taladt neder af himmelen; hvad de säga, det måste gälla på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Derföre faller dem den menige man till; förty de nyttja deras vatten tillfyllest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Och säga: Hvad skulle Gud fråga efter dem? Hvad skulle den Högste sköta om dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Si, det äro de ogudaktige, de äro lyckosamme i verldene, och varda rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Skall det då fåfängt vara, att mitt hjerta ostraffeliga lefver, och jag mina händer i oskyldighet tvår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Och varder plågad dagliga, och min näpst är hvar morgon för handene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Jag hade fulltnär så sagt som de; men si, dermed hade jag fördömt all din barn, som någon tid varit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Jag tänkte till att jag det begripa måtte; men det var mig för svårt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Tilldess jag gick in uti Guds helgedom, och märkte uppå deras ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Men du satte dem på det hala, och förstörte dem i grund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Huru snart varda de till intet! De förgås, och få en ända med förskräckelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Såsom en dröm, när en uppvaknar; så gör du, Herre, deras beläte i stadenom försmädt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Men det gör mig ondt i hjertat, och stinger mig i mina njurar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Att jag måste vara en dåre, och intet veta; och måste vara som ett vilddjur för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Likväl blifver jag städse vid dig; ty du håller mig vid mina högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Du leder mig efter ditt råd, och upptager mig på ändalyktone med äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'När jag hafver dig, så frågar jag efter himmel och jord intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Om mig än kropp och själ försmäktade, så äst du dock, Gud, alltid mins hjertas tröst, och min del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Ty si, de som ifrå dig vika, de skola förgås. Du förgör alla dem som emot dig hor bedrifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Men det är min glädje, att jag håller mig intill Gud, och sätter mitt hopp till Herran, Herran, att jag må förkunna, huru du det gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'En undervisning Assaphs. Gud, hvi förkastar du oss så alldeles; och äst så grymmeliga vred öfver dina fosterfår?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Tänk uppå dina menighet, den du af ålder förvärfvat, och dig till arfvedel förlöst hafver; uppå Zions berg, der du bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Trampa dem på fötterna, och stöt dem platt neder i grund. Fienden hafver all ting förderfvat i helgedomenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Dina ovänner ryta uti dinom husom, och sätta sina afgudar der in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Man ser yxerna ofvantill blänka, såsom man i en skog högge;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Och sönderhugga all dess tafvelverk med yxer och bilor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'De uppbränna din helgedom; de oskära dins Namns boning i grund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'De tala i sitt hjerta: Låter oss skinna dem; de uppbränna all Guds hus i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Vår tecken se vi intet, och ingen Prophet predikar mer, och ingen, lärare lärer oss mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Ack! Gud, huru länge skall ovännen försmäda; och fienden så alldeles förlasta ditt Namn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Hvi vänder du dina hand ifrå, och dina högra hand så platt ifrå ditt sköt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Men Gud är min Konung af ålder; den all hjelp gör, som på jordene sker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Du sönderdelar hafvet genom dina kraft, och sönderslår drakarnas hufvud i vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Du sönderkrossar hufvuden af hvalfiskarna, och gifver dem folkena i öknene till spis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Du låter uppvälla källor och bäcker; du låter borttorkas starka strömmar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Dag och natt äro dine; du gör, att både sol och stjernor sitt vissa lopp hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Du sätter hvarjo lande sina gränsor; sommar och vinter gör du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Så betänk dock det, att fienden försmäder Herran, och ett galet folk lastar ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Gif dock icke dins turturdufvos själ vilddjurena, och förgät icke så platt dina fattiga kreatur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Tänk uppå förbundet; ty landet är allt omkring jämmerliga förhärjadt, och husen äro nederrifne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Låt icke de ringa afgå med skam; ty de fattige och elände lofva ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Upp, o Gud, och uträtta dina sak; tänk uppå den försmädelse, som dig dagliga af de galna vederfars.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Förgät icke dina fiendars skri; dina ovänners rasande varder ju längre ju större.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'En Psalm och visa Assaphs, att han icke förgicks, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Vi tacke dig, Gud, vi tacke dig, och förkunne din under, att ditt Namn så när är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Ty i sinom tid skall jag rätt döma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Jorden bäfvar, och alle de derpå bo; men jag håller hennes pelare stadiga. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Jag sade till de stortaliga: Berömmer eder icke så; och till de ogudaktiga: Trugens icke uppå välde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Trugens icke så fast uppå edart välde; taler icke så halsstyft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Det hafver ingen nöd hvarken af östan eller vestan, eller af de berg i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Ty Gud är domare; denna förnedrar han, och den andra upphöjer han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Ty Herren hafver en skål i handene, och med starkt vin fullt inskänkt, och skänker derutaf; men de ogudaktige måste alle dricka, och utsupa dräggena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Men jag vill förkunna evinnerliga, och lofsjunga Jacobs Gudi; Och vill sönderbryta allt de ogudaktigas våld; att de rättfärdigas välde skall upphöjdt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'En Psalm och visa Assaphs, på strängaspel, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Gud är känd i Juda; i Israel är hans Namn härligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'I Salem är hans tjäll, och hans boning i Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Der sönderbryter han bågans pilar, sköld, svärd och strid. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Du äst härligare och mägtigare, än de röfvareberg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'De stolte måste beröfvade varda, och afsomna; och alle krigare måste låta händerna falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'För ditt näpsande, Jacobs Gud, faller i sömn både vagn och häst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Du äst förskräckelig; ho kan för dig stå, då du vred äst?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'När du låter höra domen af himmelen, så förskräckes jorden, och varder stilla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'När Gud uppstår till att döma, på det han skall hjelpa alla elända på jordene. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'När du ena mennisko straffar, så måste man bekänna dig, att du redo äst till att straffa andra flera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Lofver, och håller det Herranom edrom Gud, alle I som omkring honom ären. Bärer fram skänker dem förskräckeliga; Den der Förstomen borttager modet, och förskräckelig är ibland Konungarna på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'En Psalm Assaphs, för Jeduthun, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Jag ropar med mine röst till Gud; till Gud ropar jag, och han hörer mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Uti mine nöds tid söker jag Herran; min hand är om nattena uträckt, och håller intet upp; ty min själ vill sig icke trösta låta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'När jag bedröfvad är, så tänker jag uppå Gud; när mitt hjerta i ångest är, så talar jag. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Min ögon håller du, att de vaka. Jag är så vanmägtig, att jag icke tala kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Jag tänker uppå den gamla tiden, på de förra år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Jag tänker om nattena på mitt strängaspel, och talar med mino hjerta; min ande ransakar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Månn då Herren förkasta evinnerliga; och ingen nåd mer bevisa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Är det så alldeles ute med hans godhet; och hafver tillsägelsen en ända?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Hafver då Gud förgätit att vara nådelig; och tillyckt sina barmhertighet för vredes skull? Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Men dock sade jag: Dermed qväl jag mig sjelf; den Högstas högra hand kan all ting förvandla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Derföre tänker jag uppå Herrans gerningar; ja, jag tänker uppå din förra under;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Och talar om all din verk, och säger om din anslag:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Gud, din väg är helig; hvar är en så mägtig Gud, såsom du, Gud, äst?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Du äst den Gud, som under gör; du hafver bevisat dina magt ibland folken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Du hafver förlossat ditt folk väldeliga, Jacobs barn och Josephs. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Vattnen sågo dig, Gud, vattnen sågo dig, och ängslades; och djupen stormade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'De tjocke skyar utgöto vatten; skyarna dundrade, och skotten foro deribland.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Det dundrade i himmelen, ditt ljungande lyste på jordene; jorden rördes och bäfvade deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Din väg var i hafvet, och din stig i stort vatten; och man fann dock intet din fotspår. Du förde ditt folk, såsom en fårahjord, genom Mose och Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'En undervisning Assaphs. Hör, mitt folk, min lag; böjer edor öron till mins muns tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Jag vill öppna min mun till ordspråk, och vill förtälja gamla hemligheter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'De vi hört hafve och vetom, och våra fäder oss förtäljt hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Att vi det icke fördölja skulle deras barnom, som efter komma skulle; utan förkunna Herrans lof, och hans magt och under, som han gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Han upprättade ett vittnesbörd i Jacob, och gaf en lag i Israel, den han våra fäder böd, till att lära deras barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'På det att efterkommanderna måtte det lära, och de barn, som ännu skulle födde varda; då de uppkommo, att de ock förkunnade det sinom barnom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Att de skulle sätta sitt hopp till Gud, och icke förgäta Guds verk, och hålla hans bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Och icke varda, såsom deras fäder, en affällig och ohörsam art; hvilkom deras hjerta icke fast var, och deras ande höll sig icke troliga till Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Såsom Ephraims barn, som väpnade voro och förde bågan, föllo af i stridstidenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'De höllo icke Guds förbund, och ville icke vandra i hans lag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Och förgåto hans verk, och hans under, som han dem bevist hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'För deras fäder gjorde han under, i Egypti land, på den markene Zoan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Han åtskiljde hafvet, och lät dem gå derigenom, och satte vattnet såsom en mur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Han ledde dem om dagen med en molnsky, och om nattena med en klar eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Han lät bergsklippona remna i öknene, och gaf dem dricka vatten tillfyllest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Och lät bäcker flyta utu bergsklippone, att de flöto derut, såsom vattuströmmar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Likväl syndade de ännu emot honom, och förtörnade den Högsta i öknene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Och försökte Gud, i deras hjerta, att de spis beddes till deras själar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Och talade emot Gud, och sade: Ja, skulle väl Gud kunna bereda ett bord i öknene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Si, han hafver väl slagit bergsklippona, att vatten utflöt, och bäcker sig utgåfvo; men huru kan han gifva bröd, och skaffa sino folke kött?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Då nu Herren det hörde, vardt han upptänd; och eld gick upp i Jacob, och vrede kom öfver Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Att de icke trodde uppå Gud, och hoppades icke uppå hans hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Och han böd skyarna ofvantill, och upplät himmelens dörrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Och lät regna Man till dem till mats, och gaf dem himmelsbröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'De åto änglabröd; han sände dem mat tillfyllest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Han lät blåsa östanväder under himmelen, och genom sina starkhet upprörde sunnanväder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Och lät kött regna uppå dem såsom stoft, och foglar såsom sanden i hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Och lät dem falla i deras lägre, allestäds der de bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Då åto de, och vordo för mätte; han lät dem släcka sin lusta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Då de ännu sin lusta icke släckt hade, och de ännu åto deraf,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Så kom Guds vrede öfver dem; och drap de yppersta ibland dem, och nederslog de bästa i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Men öfver allt detta syndade de ännu mer, och trodde intet uppå hans under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Derföre lät han dem dö bort, så att de intet fingo, och måste i deras lifsdagar plågade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'När han drap dem, sökte de honom, och vände sig bittida till Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Och tänkte, att Gud är deras tröst, och Gud den Högste deras förlösare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Och skrymtade för honom med deras mun, och lögo för honom med deras tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Men deras hjerta var icke fast intill honom, och höllo sig icke troliga intill hans förbund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Men han var barmhertig, och förlät missgerningarna, och förgjorde dem icke; och afvände ofta sina vrede, och lät icke alla sina vrede gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Ty han tänkte att de äro kött; ett väder, som bortfar, och kommer intet igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'De förtörnade honom ganska ofta i öknene, och bekymrade honom i ödemarkene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'De försökte Gud framgent, och rette den Heliga i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'De tänkte intet uppå hans hand, den dagen då han förlöste dem ifrå fienderna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Såsom han sina tecken gjort hade uti Egypten, och sina under i det landet Zoan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Då han deras vatten i blod vände; så att de af deras bäcker icke dricka kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Då han ohyro ibland dem sände, som dem åto, och paddor, som dem förderfvade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Och gaf deras frukt gräsmatkom, och deras säd gräshoppom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Då han deras vinträ med hagel förderfvade, och deras mulbärsträ med stort hagel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Då han deras boskap slog med hagel, och deras hjordar med ljungande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Då han i sina grymma vrede sände ibland dem onda änglar, och lät dem härja och förderfva, och skada göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Då han lät sina vrede gå, och icke skonade deras själom för dödenom, och lät deras boskap dö af pestilentie.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Då han i Egypten allt förstfödt slog, de första arfvingar i Hams hyddom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Och lät sitt folk utdraga såsom får, och förde dem såsom en hjord i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Och han ledde dem säkra, så att de intet fruktade sig; men deras fiendar öfvertäckte hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Och lät dem komma i sina helga gränsor, till detta berg, hvilket hans högra hand förvärfvat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Och fördref för dem folk, och lät dem utskifta arfvet, och lät Israels slägter bo i deras hyddom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Men de försökte och förtörnade Gud, den Högsta, och höllo intet hans vittnesbörd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Och föllo tillbaka, och föraktade all ting, såsom deras fäder; och höllo intet, såsom en lös båge;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Och förtörnade honom med sina höjder, och rette honom med sina afgudar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Och då Gud det hörde, vardt han upptänd, och förkastade Israel svårliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Så att han lät fara sina boning i Silo, den hyddo, der han ibland menniskor bodde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Och gaf deras magt uti fängelse, och deras härlighet uti fiendans händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Och öfvergaf sitt folk för svärd, och var upptänd emot sitt arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Deras unga män förtärde elden, och deras jungfrur måste ogifta blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Deras Prester föllo genom svärd, och inga enkor voro, de der gråta skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Och Herren vaknade upp, såsom en sofvande, och såsom en stark glad är, den ifrå vin kommer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Och slog sina fiendar baktill, och hängde en evig skam uppå dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Och förkastade Josephs hyddo, och utvalde icke Ephraims slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Utan utvalde Juda slägte, det berget Zion, som han älskade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Och byggde sin helgedom högt, såsom ett land det evinnerliga fast stå skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Och utvalde sin tjenare David, och tog honom utu fårahusen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Ifrå de däggande får hemtade han honom, att han hans folk Jacob föda skulle, och hans arf Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Och han födde dem också med all trohet, och regerade dem med all flit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'En Psalm Assaphs. Gud, Hedningarna äro in i ditt arf fallne; de hafva orenat ditt helga tempel, och af Jerusalem stenhopar gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'De hafva gifvit dina tjenares lekamen foglomen under himmelen till att äta, och dina heligas kött djuromen på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'De hafva utgjutit deras blod omkring Jerusalem, såsom vatten; och der var ingen, som begrof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Vi äre vårom grannom till en försmädelse vordne; till spott och hån dem som omkring oss äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Herre, huru länge vill du så allstings vred vara; och ditt nit, såsom en eld, brinna låta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Utgjut dina grymhet öfver Hedningarna, de dig intet känna, och uppå de Konungariken, som ditt Namn intet åkalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Ty de hafva uppätit Jacob, och hans hus förödt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Tänk icke uppå våra förra missgerningar. Förbarma dig öfver oss snarliga, ty vi äre fast eländige vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Hjelp du oss, Gud vår hjelpare, för dins Namns äros skull; fräls oss, och förlåt oss våra synder, för ditt Namns skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Hvi låter du Hedningarna säga: Hvar är nu deras Gud? Låt hämnden öfver dina tjenares blod, som utgjutet är, kunnig varda, ibland Hedningarna, för vår ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Låt för dig komma de fångars suckande; efter din stora arm behåll dödsens barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Och vedergäll vårom grannom sjufaldt uti deras sköte deras försmädelse, der de dig, Herre, med försmädt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Men vi, ditt folk och din fosterfår, tackom dig evinnerliga, och förkunnom ditt lof förutan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'En Psalm Assaphs, om gyldene rosena, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Hör, Israels Herde, du som leder Joseph såsom får; bete dig, du som sitter på Cherubim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Uppväck dina magt, du som för Ephraim, BenJamin och Manasse äst, och kom oss till hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Gud, tröst oss, och låt ditt ansigte lysa, så varde vi hulpne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Herre Gud Zebaoth, huru länge vill du vred vara öfver dins folks bön?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Du spisar dem med tårars bröd, och skänker dem ett stort mått, fullt med tårar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Du lätst alla våra grannar banna oss, och våra fiendar bespotta oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Gud Zebaoth, tröst oss; låt ditt ansigte lysa, så varde vi hulpne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Du hafver hemtat ditt vinträ utur Egypten, och hafver fördrifvit Hedningarna, och planterat det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Du hafver röjt vägen för thy, och låtit det väl rota sig, så att det hafver uppfyllt landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Bergen äro med dess skugga öfvertäckte, och med dess qvistar Guds cedreträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Du hafver utsträckt dess qvistar intill hafvet, och dess telningar allt intill älfvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Hvi hafver du så sönderbrutit dess gård, att deraf rifver allt det som der framom går?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'De vildsvin hafva uppgräfvit det, och de vilddjur hafva afbitit det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Gud Zebaoth, vänd dig dock; skåda neder af himmelen, och se härtill, och besök detta vinträt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Och håll det vid magt, som din högra hand planterat hafver, och det du dig stadeliga utvalt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Se dertill, och straffat; att på det brännande och rifvande må en ände varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Din hand beskydde dins högra hands folk, och de menniskor, som du dig stadeliga utvalt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Så vilje vi intet ifrå dig vika. Låt oss lefva, så vilje vi åkalla ditt Namn. Herre Gud Zebaoth, tröst oss. Låt ditt ansigte lysa, så varde vi hulpne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'På Gittith, till att föresjunga, Assaphs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Sjunger Gudi gladeliga, den vår starkhet är; fröjdens Jacobs Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Tager Psalmer, och för hit trummor, lusteliga harpor med psaltare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Blåser med basuner i nymånaden, i våra löfhyddohögtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Ty detta är en sed i Israel, och en Jacobs Guds rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Det hafver han till ett vittnesbörd satt i Joseph, då de utur Egypti land drogo, och främmande tungomål hört hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Och jag deras axlar ifrån bördone friade, och deras händer vid krukorna qvitta vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Då du åkallade mig i nödene, halp jag dig ut, och bönhörde dig, då tordönen öfverföll dig; och försökte dig vid trätovattnet. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Hör, mitt folk, jag vill betyga ibland dig; Israel, du skall höra mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Att ibland dig ingen annar Gud är, och du ingen främmande Gud tillbeder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Jag är Herren din Gud, som dig utur Egypti land fört hafver. Låt din mun vidt upp, låt mig uppfylla honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Men mitt folk hörde intet mina röst, och Israel är intet om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Så hafver jag låtit dem uti deras hjertas sinne, att de måga vandra efter sitt råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Om mitt folk ville mig hörsamt vara, och Israel på minom vägom gå,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Så ville jag snart nederlägga deras fiendar, och vända mina hand emot deras motståndare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Och de som Herran hata, skulle fela uppå honom; men deras tid skulle evinnerliga vara, Och jag skulle spisa dem med bästa hvete, och mätta dem med hannog utu hälleberget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'En Psalm Assaphs. Gud står uti Guds församling, och är domare ibland gudarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Huru länge viljen I döma orätt, och föresätta de ogudaktigas person? Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Skaffer dem fattiga och faderlösa rätt, och hjelper dem elända och torftiga till rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Hjelper den föraktada och fattiga, och förlöser honom utu de ogudaktigas våld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Men de låta intet säga sig, och aktat intet; de gå allt i mörkret; derföre måste alla landsens grundvalar falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Jag hafver väl sagt: I ären gudar, och allesammans dens Högstas barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Men I måsten dö såsom menniskor, och såsom en tyrann förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Statt upp, Gud, och döm jordena; ty du äst en Herre öfver alla Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'En Psalmvisa Assaphs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Gud, tig dock icke så, och var dock icke så stilla; Gud, lid det dock icke så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Ty si, dine fiender rasa, och de som dig hata, sätta upp hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'De hafva listig anslag emot ditt folk, och rådslå emot dina fördolda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Kommer, säga de, låter oss utrota dem, så att de intet folk äro; att på Israels namn icke skall mer tänkt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Ty de hafva förenat sig med hvarannan, och ett förbund emot dig gjort:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'De Edomeers hyddor, och de Ismaeliters, de Moabiters, och Hagariters,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'De Gebaliters, Ammoniters, och Amalekiters, de Philisteers, samt med dem i Tyro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Assur hafver ock gifvit sig till dem, och hjelpa Lots barnom. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Gör dem såsom de Midianiter, såsom Sisera, såsom Jabin vid den bäcken Kison;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Hvilke förderfvade vordo vid Endor, och vordo till träck på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Gör deras Förstar såsom Oreb och Seeb; alle deras öfverstar, såsom Seba och Zalmunna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'De der säga: Vi vilje intaga Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Min Gud, gör dem såsom en hvärfvel, och såsom strå för väder,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Såsom en eld, den skog förbränner, och såsom en låga, den berg upptänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Alltså förfölj dem med ditt väder, och förskräck dem med ditt oväder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Gör deras ansigten fulla med blygd, att de efter ditt Namn. Herre, söka måste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Skämme sig, och förskräckes alltid ju mer och mer, och till skam komme, och förgås. Så skola de förnimma, att du med ditt Namn heter Herre allena, och den Högste i allo verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'En Psalm Korah barnas, på Gittith, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Huru lustige äro dina boningar, Herre Zebaoth!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Min själ längtar och trängtar efter Herrans gårdar. Min kropp och själ fröjda sig uti lefvandes Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Ty foglen hafver funnit ett hus, och svalan sitt bo, der de sina ungar lägga; nämliga ditt altare, Herre Zebaoth, min Konung och min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Salige äro de som i dino huse bo, de lofva dig till evig tid. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Salige äro de menniskor, som dig för sin starkhet hålla, och af hjertat efter dig vandra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'De der gå genom jämmerdalen, och göra der källor; och lärarena varda med mycken välsignelse prydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'De vinna den ena segren efter den andra, att man se må, att den rätte Guden är i Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Herre Gud Zebaoth, hör min bön; akta härtill, Jacobs Gud. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Gud, vår sköld, skåda dock; se uppå din smordas rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Ty en dag uti dina gårdar är bättre, än eljest tusende. Jag vill heldre vakta dörrena uti mins Guds huse, än länge bo uti de ogudaktigas hyddom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Ty Herren Gud är sol och sköld. Herren gifver nåd och äro; dem frommom skall intet godt fattas. Herre Zebaoth, säll är den menniska, som sig förlåter uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'En Psalm Korah barnas, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Herre, du som fordom vast dino lande nådelig, och förlossade de fångar af Jacob;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Du som tillförene dino folke missgerning förlåtit hafver, och alla deras synder öfvertäckt; Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Du som tillförene alla dina vrede borttagit hafver, och vändt dig ifrå dine vredes grymhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Tröst oss, Gud vår Frälsare, och låt af dine ogunst till oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Vill du då till evig tid uppå oss vred vara; och låt dina vrede gå evinnerliga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Vill du då icke åter vederqvicka oss; att ditt folk må glädja sig öfver dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Herre, bete oss dina nåde, och hjelp oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Ack! att jag höra måtte, det Herren Gud talar, att han sino folke och sinom heligom frid tillsade; på det de icke skola på någon galenskap komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Dock är ju hans hjelp när dem som frukta honom, att i vårt land skall ära bo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Att godhet och trohet mötas tillsamman, rättfärdighet och frid kyssas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Att trohet må växa på jordene, och rättfärdighet skåda neder af himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Att ock Herren oss godt gör; på det vårt land må sina frukt gifva; Att rättfärdighet må ändå för honom blifva, och sin rätta gång hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'En bön Davids. Herre, böj neder dina öron, och hör mig; ty jag är elände och fattig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Bevara mina själ, ty jag är helig; hjelp du, min Gud, dinom tjenare, som sig uppå dig förlåter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Herre, var mig nådelig; ty jag ropar dagliga till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Fröjda dins tjenares själ; förty efter dig, Herre, trängtar jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Ty du, Herre, äst god och nådelig, af stor godhet allom dem som åkalla dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Förnim, Herre, mina bön, och akta uppå mina böns röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Uti mine nöd åkallar jag dig, att du dock ville höra mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Herre, dig är ingen lik ibland gudarna, och ingen är, som så göra kan som du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Alle Hedningar, de du gjort hafver, skola komma och tillbedja för dig, Herre, och ära ditt Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Att du så stor äst, och gör under, och allena Gud äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Visa mig, Herre, din väg, att jag må vandra i dine sanning; behåll mitt hjerta vid det ena, att jag ditt Namn fruktar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Jag tackar dig, Herre, min Gud, af allt mitt hjerta, och ärar ditt Namn evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Ty din godhet är stor öfver mig, och du hafver frälst mina själ utu det djupa helvetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Gud, de stolte sätta sig emot mig, och de tyranners hop står mig efter mina själ, och hafva dig intet för ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Men du, Herre Gud, äst barmhertig och nådelig, tålig, och af stora mildhet och trohet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Vänd dig till mig, var mig nådelig; stärk din tjenare med dine magt, och hjelp dine tjenarinnos son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Gör ett tecken med mig, att mig väl går, att de set, som mig hata, och skämma sig, att du med mig står, Herre, och tröstar mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'En Psalmvisa Korah barnas. Han är fast grundad på de helga bergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Herren älskar Zions portar, öfver alla Jacobs boningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Härlig ting varda i dig predikade, du Guds stad. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Jag vill predika låta för Rahab och Babel, att de mig känna skola. Si, de Philisteer och Tyrer, samt med de Ethioper, varda der födde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Man skall i Zion säga, att allahanda folk derinne födt varder, och att han, den Högste, bygger honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Herren skall predika låta i allahanda tungomål, att ock någre af dem skola der födde varda. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Och de sångare skola alle i dig sjunga till skiftes, såsom i en dans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'En Psalmvisa Korah barnas, till att föresjunga, om de eländas svaghet; en undervisning Hemans, dens Esrahitens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Herre Gud, min Frälsare, jag ropar dag och natt inför dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Låt mina bön komma inför dig; böj din öron till mitt ropande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Ty min själ är full med jämmer, och mitt lif är hardt när helvetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Jag är aktad lik vid dem som i kulona fara; jag är såsom en man, den ingen hjelp hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Jag ligger ibland de döda öfvergifven, såsom de slagne, de i grafvene ligga; på hvilka du intet mer tänker, och de ifrå dine hand afskilde äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Du hafver lagt mig i gropena neder, uti mörkret och i djupet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Din grymhet trycker mig, och tränger mig med allom dinom böljom. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Mina vänner hafver du låtit komma långt ifrå mig; du hafver gjort mig dem till en styggelse; jag ligger fången, och kan icke utkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Mitt ansigte är jämmerligit för vedermödos skull. Herre, jag åkallar dig dagliga; jag uträcker mina händer till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Månn du då göra under ibland de döda? Eller månn de döda uppstå och tacka dig? Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Månn man uti grafvena förtälja dina godhet; och dina trohet uti förderfvet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Kunna då dina under uti mörkret kända varda; eller din rättfärdighet i de lande, der all ting förgätas?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Men jag ropar till dig, Herre, och min bön kommer bittida för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Hvi förkastar du, Herre, mina själ; och förskyler ditt ansigte för mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Jag är elände och vanmägtig, att jag så bortkastad är. Jag lider ditt förskräckande, så att jag fulltnär förtviflar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Din grymhet går öfver mig, ditt förskräckande trycker mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'De omlägga mig dagliga såsom vatten, och omhvärfva mig tillsammans. Du gör, att mina vänner och näste, och mine kände draga sig långt ifrå mig, för sådana jämmers skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'En undervisning Ethans, dens Esrahitens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Jag vill sjunga om Herrans nåde evinnerliga, och hans sanning förkunna med minom mun, ifrå slägte till slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Och säger alltså, att en evig nåd skall uppgå; och du varder dina sanning i himmelen troliga hållandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Jag hafver gjort ett förbund med minom utkorade; minom tjenare David hafver jag svorit:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Jag skall förskaffa dig en evig säd, och bygga din stol ifrå slägte till slägte. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Och himlarna, Herre, skola prisa din under, och dina sanning, uti de heligas församling.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Ty ho kan i skyn liknas vid Herran; och ibland gudarnas barn Herranom lik vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Gud är fast mägtig uti de heligas församling, och underlig öfver alla de som omkring honom äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Herre Gud Zebaoth, ho är såsom du, en mägtig Herre? Och din sanning är allt omkring dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Du råder öfver det stormande hafvet; du styrer dess böljor, när de upphäfva sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Du slår Rahab till döds; du förströr dina fiendar, med dinom starka arm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Himmel och jord äro din; du hafver grundat jordenes krets, och hvad deruti är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Norr och söder hafver du skapat; Thabor och Hermon fröjdar sig i ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Du hafver en väldig arm; stark är din hand, och hög är din högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Rättfärdighet och dom är dins stols stadfästelse; nåd och sanning äro för ditt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Väl är de folke, som fröjdas kan; Herre, de skola vandra i dins ansigtes ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'De skola dagliga öfver ditt Namn glade vara, och i dine rättfärdighet härlige vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Ty du äst deras starkhets berömmelse, och genom dina nåde skall du upphöja vårt horn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Ty Herren är vår sköld, och den Helige i Israel är vår Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'På den tiden talade du i en syn till dina heliga, och sade: Jag hafver uppväckt en hjelta, den hjelpa skall; jag hafver upphöjt en utkoradan utu folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Jag hafver funnit min tjenare David; jag hafver smort honom med mina helga oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Min hand uppehåller honom, och min arm skall styrka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Fienderna skola icke vara honom öfvermägtige, och de orättfärdige skola icke förtrycka honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Utan jag skall slå hans ovänner för honom, och de honom hata, vill jag plåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Men min sanning och nåd skall när honom vara; och hans horn skall i mitt Namn upphöjdt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Jag skall sätta hans hand uti hafvet, och hans högra hand uti älfverna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Han skall kalla mig alltså: Du äst min fader, min Gud och tröst, den mig hjelper.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Och jag skall göra honom till första sonen, den aldrahögsta ibland Konungarna på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Jag vill behålla honom mina nåd evinnerliga, och mitt förbund skall honom fast blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Jag skall gifva honom en evig säd, och hans stol uppehålla, så länge himmelen varar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Men om hans barn min lag öfvergifva, och i minom rättom icke vandra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Om de mina stadgar ohelga, och min bud icke hålla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Så vill jag hemsöka deras synd med ris, och deras missgerningar med plågor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Men mina nåd vill jag icke vända ifrå honom, och icke låta mina sanning fela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Jag vill icke ohelga mitt förbund, och icke ogildt göra hvad af minom mun utgånget är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Jag hafver en gång svorit vid mina helighet: Jag vill icke ljuga for David;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Hans säd skall evig vara, och hans stol för mig såsom solen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Såsom månen skall han evinnerliga vid magt hållen varda, och såsom de vittne i skyn viss vara. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Men nu bortdrifver du och förkastar, och vredgas med dinom smorda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Du bryter dins tjenares förbund, och trampar hans krono neder på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Du nederrifver alla hans murar, och låter hans fäste afbrytas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Honom beröfva alle de der framom gå; han är sinom grannom ett gabberi vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Du upphöjer hans ovänners högra hand, och gläder alla hans fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Ock hafver du hans svärds kraft borttagit, och låter honom ingen seger vinna i stridene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Du förstörer hans renhet, och kastar hans stol till jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Du förkortar hans ungdoms tid, och betäcker honom med blygd. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Herre, huru länge vill du dig så allstinges fördölja; och låta dina grymhet brinna såsom en eld?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Tänk huru stackot mitt lif är; hvi vill du alla menniskor fåfängt skapat hafva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Hvilken är den der lefver, och intet ser döden; den sina själ friar utu helvetes hand? Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Herre, hvar är den förra din nåd, den du David i dine sanning svorit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Tänk, Herre, på dina tjenares försmädelse, den jag bär i mitt sköt, af allom så mångom folkom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Dermed, Herre, dine fiender dig försmäda; der de med försmäda, och med fötterna trampa på din smorda. Lofvad vare Herren evinnerliga. Amen, Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'En bön Mose dens Guds mansens. Herre, du äst vår tillflykt, ifrå slägte till slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Förr än bergen vordo, och jorden och verlden skapade blefvo, äst du Gud, af evighet till evighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Du som låter menniskorna dö, och säger: Kommer igen, I menniskors barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Ty tusende år äro för dig såsom den dag i går framgick, och såsom en nattväkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Du låter dem gå sin kos såsom en ström; och äro såsom en sömn; likasom gräs, det dock snarliga förvissnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Det der bittida blomstras, och snart vissnar; och på aftonen afhugget varder, och förtorkas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Det gör din vrede, att vi så förgås, och din grymhet, att vi så hasteliga hädan måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Ty våra missgerningar sätter du för dig, våra okända synder i ljuset för ditt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Derföre gå alle våre dagar sin kos genom dina vrede; vi lykte vår år såsom ett tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Vårt lif varar sjutio år, åt högsta åttatio år; och då det bäst varit; hafver, så hafver det möda och arbete varit; ty det går snart sin kos, lika som vi flöge bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Men ho tror det, att du så svårliga vredgas? Och ho fruktar sig för sådana dine grymhet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Lär oss betänka, att vi dö måste, på det vi måge förståndige varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Herre, vänd dig dock till oss igen, och var dinom tjenarom nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Uppfyll oss bittida med dine nåd; så vilje vi fröjdas, och glade vara i våra lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Gläd oss igen, efter det du oss så länge plågat hafver, efter det vi så länge olycko lidit hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Bete dinom tjenarom dina gerningar, och dina äro deras barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Och Herren, vår Gud, vare oss blid, och främje våra händers verk med oss; ja våra händers verk främje han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Den der under dens Högstas bekärm sitter, och under dens Allsmägtigas skugga blifver,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Han säger till Herran: Mitt hopp och min borg; min Gud, den jag hoppas uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Ty han frälsar dig ifrå jägarens snaro, och ifrå den skadeliga pestilentie.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Han skall betäcka dig med sina fjädrar, och ditt hopp skall vara under hans vingar; hans sanning är spjut och sköld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Att du icke torf förskräckas för nattenes stygghet; för de skott, som om dagen flyga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'För pestilentie, som i mörkrena vankar; för den sjuko, som om middagen förderfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Om tusende falla vid dina sido, och tiotusende vid dina högra sido, så skall det dock intet drabba uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Ja, du skall med din ögon se lust, och skåda huru dem ogudaktigom vedergullet varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Ty Herren är ditt hopp; den Högste är din tillflykt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Dig varder intet ondt vederfarandes, och ingen plåga skall nalkas dine hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Ty han hafver befallt sinom Änglom om dig, att de skola bevara dig på allom dinom vägom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'De skola bära dig på händerna, att du icke stöter din fot på stenen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'På lejon och huggormar skall du gå, och trampa uppå det unga lejonet och drakan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Han begärar mig, ty vill jag uthjelpa honom; han känner mitt Namn, derföre vill jag beskydda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Han åkallar mig, ty vill jag höra honom; jag är när honom i nödene; jag skall taga honom derut, och låta honom till äro komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Jag skall mätta honom med långt lit, och skall bete honom mina salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'En Psalm till att sjunga på Sabbathsdagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Det är en kostelig ting att tacka Herranom, och lofsjunga dino Namne, du Aldrahögste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Om morgonen förkunna dina nåde. och om aftonen dina sanning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'På tio stränger, och psaltare; med spelande på harpo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Ty, Herre, du låter mig gladeligen sjunga om dine verk, och jag berömmer dina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Herre, huru äro dine verk så store! dine tankar äro så svåra djupe.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'En galen tror det intet, och en dåre aktar sådant intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'De ogudaktige grönskas såsom gräs, och de ogerningsmän blomstras alle; tilldess de förderfvade varda till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Men du, Herre, äst den Högste, och blifver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Ty si, dine fiender, Herre, si, dine fiender skola förgås, och alle ogerningsmän måste förströdde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Men mitt horn skall upphöjdt varda, såsom ens enhörnings, och jag varda smord med färska oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Och mitt öga skall lust se på mina fiendar, och mitt öra skall lust höra på de arga, som sig emot mig sätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Den rättfärdige skall grönskas, såsom ett palmträ; han skall växa, såsom ett cedreträ på Libanon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'De der planterade äro uti Herrans hus, de skola i vår Guds gårdom grönskas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Och om de än gamle varda, skola de likväl blomstras, fruktsamme och färske vara; Att de förkunna skola, att Herren så from är; min tröst, och intet orätt är i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Herren är Konung och härliga beprydd; Herren är beprydd, och hafver begynt ett rike, så vidt som verlden är, och tillredt det, att det blifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Ifrå den tiden står din stol fast; du äst evig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Herre, vattuströmmarna upphäfva sig, vattuströmmarna upphäfva sitt fräsande; vattuströmmarna upphäfva sina böljor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'De vågar i hafvet äro stora, och fräsa grufveliga; men Herren är ännu större i höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Din ord äro en rätt lära; helighet, Herre, är dins hus prydning evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Herre Gud, hvilkom hämnden tillhörer; Gud, hvilkom hämnden tillhörer, bete dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Upphöj dig, du verldenes domare; vedergäll dem högfärdigom det de förtjena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Herre, huru länge skola de ogudaktige, huru länge skola de ogudaktige pråla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Och så högmodeliga tala; och alle ogerningsmän så berömma sig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Herre, de förtrycka ditt folk, och plåga ditt arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Enkor och främlingar dräpa de, och faderlösa döda de;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Och säga: Herren ser det intet; och Jacobs Gud aktar det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Märker dock, I galne ibland folket; och I dårar, när viljen I vise varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Den der örat planterat hafver, skulle han icke höra? Den der ögat gjort hafver, skulle han icke se?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Den der Hedningarna näpser, skulle han icke straffa? den der menniskorna lärer hvad de veta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Men Herren vet menniskornas tankar, att de fåfängelige äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Säll är den som du, Herre, tuktar, och lärer honom genom din lag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Att han tålamod hafva må, då illa går; tilldess dem ogudaktiga grafven beredd varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Ty Herren skall icke förkasta sitt folk, eller öfvergifva sitt arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Ty rätt måste dock blifva rätt; och thy måste all from hjerta tillfalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Ho står med mig emot de onda? Ho träder till mig emot de ogerningsmän?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Om Herren icke hulpe mig, så låge min själ fulltnär uti det stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Jag sade: Min fot hafver stapplat; men din nåd, Herre, uppehöll mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Jag hade mycket bekymmer i mitt hjerta; men din tröst gladde mina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Du kommer ju aldrig öfverens med dem skadeliga stolenom, som lagen illa uttyder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'De rusta sig emot dens rättfärdigas själ, och fördöma oskyldigt blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Men Herren är mitt beskärm, min Gud är mitt hopps tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Och han skall vedergälla dem deras orätt, och skall förgöra dem för deras ondskos skull; Herren, vår Gud, skall förgöra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Kommer, låter oss glädjas Herranom, och fröjdas för vår salighets tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Låt oss med tack komma inför hans ansigte, och fröjdas för honom med Psalmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Ty Herren är en stor Gud, och en stor Konung öfver alla gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Ty i hans hand är hvad som jorden bär, och bergshöjderna äro också hans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Ty hans är hafvet, och hans händer hafva det torra beredt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Kommer, låter oss tillbedja, och knäböja, och nederfalla för Herranom, den oss gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Ty han är vår Gud, och vi hans fosterfolk, och hans händers får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'I dag om I hans röst hören, så förstocker icke edor hjerta, såsom i Meriba skedde, såsom i Massa i öknene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Der edre fäder försökte mig, förnummo och sågo min verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Att jag i fyratio år mödo hade med detta folk, och sade: Det är sådant folk, att deras hjerta alltid vill den orätta vägen, och de mina vägar icke lära vilja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Så att jag svor i mine vrede: De skola icke komma till mina rolighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Sjunger Herranom en ny viso; sjunger Herranom all verlden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Sjunger Herranom, och lofver hans Namn; prediker den ena dagen efter den andra hans salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Förtäljer ibland Hedningarna hans äro, ibland all folk hans under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Ty Herren är stor, och högt prisandes; underlig öfver alla gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Ty alle folkens gudar äro afgudar; men Herren hafver gjort himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Det står härliga och kosteliga till för honom, och går väldeliga och lofliga till i hans helgedom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'I folk, bärer fram Herranom; bärer fram Herranom äro och magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Bärer fram Herranom hans Namns äro; bärer skänker, och kommer i hans gårdar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Tillbedjer Herran i heligo prydning; hela verlden frukte honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Säger ibland Hedningarna, att Herren är Konung, och hafver sitt rike, så vidt som verlden är, beredt, att det blifva skall; och dömer folken rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Himmelen fröjde sig, och jorden vare glad. hafvet fräse, och hvad deruti är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Marken vare glad, och allt det derpå är, och låter all trä i skogen fröjda sig,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'För Herranom; ty han kommer; ty han kommer till att döma jordena; han skall döma jordenes krets med rättfärdighet, och folken med sine sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Herren är Konung, dess fröjde sig jorden, och öarna fröjde sig, så månge som de äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Moln och mörker är omkring honom; rättfärdighet och dom är hans stols stadfästelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Eld går framför honom, och uppbränner hans ovänner allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Hans ljungande lyser på jordenes krets; jorden ser det, och förskräckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Bergen försmälta såsom vax för Herranom; för hela jorderikes Herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Himlarna förkunna hans rättfärdighet; och all folk se hans äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Skämme sig alle de som belätom tjena, och berömma sig af afgudar; tillbedjer honom alle gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Zion hörer det, och är glad; och Juda döttrar fröjda sig, Herre, öfver ditt regemente.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Ty du, Herre, äst den Högste i all land; du är fast upphöjd öfver alla gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'I som älsken Herran, hater det onda; (Herren) bevarar sina heligas själar; ifrå de ogudaktigas hand skall han frälsa dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Dem rättfärdiga skall alltid ljus uppgå igen, och frommom hjertom glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'I rättfärdige, fröjder eder af Herranom, och tacker honom, och priser hans helighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'En Psalm. Sjunger Herranom en ny viso, ty han gör underlig ting; han vinner seger med sine högra hand, och med sinom helga arm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Herren låter förkunna sina salighet; för folken låter han uppenbara sina rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Han tänker uppå sina nåde och sanning Israels huse; alle verldenes ändar se vår Guds salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Glädjens Herranom, all verlden; sjunger, priser och lofver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Lofver Herran med harpor, med harpor och psalmer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Med trummeter och basuner; fröjdens för Herranom, Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Hafvet fräse, och hvad deruti är; jordenes krets, och de deruppå bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Vattuströmmarna fröjde sig, och all berg vare glad,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'För Herranom; ty han kommer till att döma jordena; han skall döma jordenes krets med rättfärdighet, och folken med rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Herren är Konung, derföre vredgas folken; han sitter på Cherubim, derföre upprörer sig verlden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Herren är stor i Zion, och hög öfver all folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Man tacke ditt stora och underliga Namn, det heligt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Uti denna Konungens rike älskar man det rätt är; du gifver fromhet, du skaffar dom och rättfärdighet i Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Upphöjer Herran vår Gud; tillbedjer vid hans fotapall; ty han är helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mose och Aaron ibland hans Prester, och Samuel ibland dem som hans Namn åkalla; de åkallade Herran, och han bönhörde dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Han talade med dem genom en molnstod; de höllo hans vittnesbörd och bud, som han dem gaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Herre, du äst vår Gud; du bönhörde dem; du, Gud, gaf dem till, och straffade deras verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Upphöjer Herran vår Gud, och tillbedjer på hans helga berg; tv Herren vår Gud är helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'En Tackpsalm. Fröjdens Herranom, all verlden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Tjener Herranom med fröjd; kommer för hans ansigte med glädskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Förnimmer, att Herren är Gud; han hafver gjort oss, och icke vi sjelfve, till sitt folk, och till sin fosterfår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Går in i hans portar med tackande; uti hans gårdar med lofvande; tacker honom, lofver hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Ty Herren är god, och hans nåd varar evinnerliga, och hans sanning ifrå slägte till slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'En Psalm Davids. Om nåd och rätt vill jag sjunga; och dig, Herre, lofsäga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Jag handlar försigteliga och redeliga med dem som mig tillhöra, och vandrar troliga i mitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Jag tager mig ingen ond sak före; jag hatar öfverträdaren, och låter honom icke när mig blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Ett vrångt hjerta måste vika ifrå mig; den onda lider jag icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Den sin nästa hemliga baktalar, honom förgör jag; den der storlåtig är och högt sinne hafver, honom lider jag icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Mine ögon se efter de trogna i landena, att de måga när mig bo; och hafver gerna fromma tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Falskt folk håller jag icke i mitt hus; ljugare trifvas icke när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Bittida förgör jag alla ogudaktiga i landena, att jag må utrota alla ogerningsmän utu Herrans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'En Bön dens eländas, när han bedröfvad är, och sin klagan för Herranom utgjuter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Herre, hör mina bön, och låt mitt ropande till dig komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Fördölj icke ditt ansigte för mig; i nödene böj dina öron till mig; när jag åkallar, så bönhör mig snarliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Ty mine dagar äro bortgångne såsom en rök, och mine ben äro förbrände såsom en brand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Mitt hjerta är slaget, och förtorkadt såsom hö; så att jag ock förgäter äta mitt bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Mine ben låda vid mitt kött, af gråtande och suckande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Jag är lika som en pelikan i öknene; jag är lika som en stenuggla uti de förstörda städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Jag vakar, och är såsom en ensam fogel på taket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Dagliga försmäda mig mine fiender, och de som mig bespotta, svärja vid mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Ty jag äter asko såsom bröd, och blandar min dryck med gråt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'För ditt hots och vredes skull; att du hafver upphöjt mig, och i grund nederslagit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mine dagar äro framgångne såsom en skugge, och jag borttorkas såsom gräs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Men du, Herre, blifver evinnerliga, och din åminnelse ifrå slägte till slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Statt upp, och förbarma dig öfver Zion; ty det är tid, att du äst nådelig, och stunden är kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Ty dine tjenare ville gerna, att det skulle bygdt varda, och sågo gerna, att dess sten och kalk tillredd vorde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Att Hedningarna måtte frukta ditt Namn, Herre, och alle Konungar på jordene dina äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Att Herren bygger Zion, och låter se sig i sin äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Han vänder sig till de öfvergifnas bön, och försmår icke deras bön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Det varde beskrifvet för de efterkommande; och det folk, som skall skapadt varda, skall lofva Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Ty han skådar af sine helga högd, och Herren ser af himmelen på jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Att han skall höra dens fångnas suckande, och förlossa dödsens barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'På det de skola i Zion predika Herrans Namn, och hans lof i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'När folken sammankomma, och Konungariken, till att tjena Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Han tvingar på vägenom mina kraft; han förkortar mina dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Jag säger: Min Gud, tag mig icke bort i mina halfva dagar; dina år vara evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Du hafver tillförene grundat jordena, och himlarna äro dina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'De måste förgås, men du blifver; de skola alle föråldras såsom ett kläde; de skola förvandlade varda såsom en klädnad, när du förvandlar dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Men du blifver såsom du äst, och dine år taga ingen ända. Dina tjenares barn varda blifvande, och deras säd skall trifvas för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'En Psalm Davids. Lofva Herran, min själ, och allt det uti mig är, hans helga Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Lofva Herran, min själ, och förgät icke, hvad godt han dig gjort hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Den dig alla dina synder förlåter, och helar alla dina brister;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Den ditt lif förlöser ifrå förderf, och kröner dig med nåd och barmhertighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Den dig uppfyller med tröst, att du dägelig varder, och gör dig ung och frisk såsom en örn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Herren skaffar rättfärdighet och dom, allom dem som orätt lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Han hafver låtit Mose veta sina vägar; Israels barn sin verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Barmhertig och nådelig är Herren, tålig och af stora mildhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Han träter icke till evig tid, och vredgas icke evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Han handlar icke med oss efter våra synder, och vedergäller oss icke efter våra missgerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Ty så hög som himmelen öfver jordena är, låter han sina nåd väldig vara öfver dem som frukta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Så långt som öster är ifrå vester, låter han vår öfverträdelse vara ifrån oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Såsom en fader förbarmar sig öfver barnen, så förbarmar sig Herren öfver dem som frukta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Ty han vet hvad vi för ett verk äre; han tänker derpå, att vi stoft äre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'En menniska är i sitt lefvande såsom gräs; hon blomstras såsom ett blomster på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'När vädret deröfver går, så är det intet mer der, och dess rum känner det intet mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Men Herrans nåd varar ifrån evighet till evighet, öfver dem som frukta honom; och hans rättfärdighet intill barnabarn,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'När dem som hans förbund hålla, och tänka uppå hans bud, att de derefter göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Herren hafver beredt sin stol i himmelen, och hans rike skall råda öfver allt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Lofver Herran, I hans Änglar, I starke hjeltar, som hans befallning uträtten, att man hans ords röst höra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Lofver Herran, alle hans härar; I hans tjenare, som hans vilja gören.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Lofver Herran, all hans verk uti all hans herradömes rum; min själ lofve Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Lofva Herran, min själ; Herre, min Gud, du äst ganska härlig, du äst dägelig och allstinges väl beprydd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Ljus är din klädnad, som du uppå hafver; du utsträcker himmelen såsom ett tapet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Du hvälfver honom ofvan med vatten; du far i skyn såsom i en vagn, och går på vädrens vingar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Du, som gör dina Änglar till väder, och dina tjenare till eldslåga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Du, som grundar jordena på hennes botten, så att hon blifver i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Med djupet betäcker du henne, såsom med ett kläde, och vatten stå öfver bergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Men för ditt näpsande fly de; för ditt dundrande fara de bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Bergen resa högt upp, och dalarna sätta sig ned i det rum, som du dem skickat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Du hafver satt ett mål, der komma de intet öfver; och måga icke åter betäcka jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Du låter källor uppbrista i dalomen, så att vatten emellan bergen flyta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Att all djur på markene måga dricka, och vildåsnarna sin törst släcka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'När dem sitta himmelens foglar, och sjunga på qvistarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Du fuktar bergen ofvanefter; du gör landet fullt med frukt, den du förskaffar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Du låter gräs växa för boskapen, och säd menniskomen till nytto; att du skall låta komma bröd utaf jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Och att vin skall fröjda menniskones hjerta, och hennes ansigte dägeligit varda af oljo, och bröd styrka menniskones hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Att Herrans trä skola full med must stå; de cedreträ på Libanon, som han planterat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Der hafva foglarna sitt näste, och hägrar bo uppe i furoträn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'De höga berg äro de stengetters tillflykt, och stenklyfterna de kunilers.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Du gör månan, till att derefter skifta året; solen vet sin nedergång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Du gör mörker, att natt varder; då draga sig all vilddjur ut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'De unga lejon, som ryta efter rof, och sin mat söka af Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Men när solen uppgår, draga de bort, och lägga sig uti sina kulor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Så går då menniskan ut till sitt arbete, och till sitt åkerverk intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Herre, huru äro din verk så stor och mång! Du hafver visliga skickat dem all, och jorden är full af dina ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Hafvet, det så stort och vidt är, der kräla uti, utan tal, både stor och liten djur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Der gå skepp; der äro hvalfiskar, som du gjort hafver, att de deruti leka skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Allt vänter efter dig, att du skall gifva dem mat i sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Då du gifver dem, så samla de; när du upplåter dina hand, så varda de med god ting mättade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Om du fördöljer ditt ansigte, så varda de förskräckte; du tager deras anda bort, så förgås de, och varda åter till stoft igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Du låter ut din anda, så varda de skapade, och du förnyar jordenes ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Herrans ära är evig; Herren hafver behag till sin verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Han ser uppå jordena, så bäfvar hon; han kommer vid bergen, så ryka de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Jag vill sjunga Herranom i mina lifsdagar, och lofva min Gud, så länge jag är till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Mitt tal behage honom väl; jag gläder mig af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Syndarena hafve en ända på jordene, och de ogudaktige vare icke mer till; lofva, min själ, Herran. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Tacker Herranom, och prediker hans Namn; förkunner hans verk ibland folken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Sjunger om honom, och lofver honom; taler om all hans under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Lofver hans helga Namn; deras hjerta, som Herran söka, glädje sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Fråger efter Herranom, och efter hans magt; söker hans ansigte alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Tänker uppå hans underliga verk, som han gjort hafver; uppå hans under, och uppå hans ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'I Abrahams hans tjenares säd, I Jacobs hans utkorades barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Han är Herren vår Gud; han dömer i hela verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Han tänker evinnerliga uppå sitt förbund; på det ord han lofvat hafver till mång tusend, slägte ifrå slägte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Det han gjort hafver med Abraham; och på eden med Isaac;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Och satte det Jacob till en rätt, och Israel till ett evigt förbund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Och sade: Dig vill jag gifva det landet Canaan, edars arfs lott;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Då de få och ringa voro, och främlingar derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Och de foro ifrå folk till folk; ifrå det ena riket till annat folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Han lät ingen menniska göra dem skada, och näpste Konungar för deras skull:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Kommer intet vid mina smorda, och görer intet ondt minom Prophetom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Och han lät en dyr tid komma i landet, och förtog dem allt bröds uppehälle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Han sände en man framför dem; Joseph vardt såld till en träl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'De tvingade hans fötter i fjettrar; hans kropp måste jern ligga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Tilldess hans ord kom, och Herrans tal pröfvade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Då sände Konungen bort, och lät gifva honom lös; herren öfver folken böd låta honom ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Han satte honom till en herra öfver sitt hus; till en föreståndare öfver alla sina ägodelar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Att han skulle undervisa hans Förstar, efter sitt sätt, och lära hans äldsta vishet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Och Israel for in uti Egypten, och Jacob vardt en främling i Hams land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Och han lät sitt folk svåliga växa, och gjorde dem mägtigare än deras fiender.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Han förvände deras hjerta, så att de hans folk hätske vordo, och tänkte till att förtrycka hans tjenare med list.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Han sände sin tjenare Mose; Aaron, den han utvalt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'De samme gjorde hans tecken ibland dem, och hans under i Hams land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Han lät mörker komma, och gjordet mörkt; och de voro icke hans ordom ohörsamme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Han förvände deras vatten i blod, och dräp deras fiskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Deras land gaf myckna paddor ifrå sig; ja, uti deras Konungars kamrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Han sade, då kom ohyra; löss uti alla deras landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Han gaf dem hagel till regn; eldslåga uti deras land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Och slog deras vinträ och fikonaträ, och förderfvade trän i deras landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Han sade, då kommo gräshoppor, gräsmatkar otalige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Och de uppåto allt gräset i deras land, och uppfrätte frukten på deras mark;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Och slog allt förstfödt uti deras land, alla deras första arfvingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Och han förde dem ut med silfver och guld, och ibland deras slägter var ingen krank.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Egypten var glad, att de utdrogo; ty deras fruktan var uppå dem fallen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Han utsträckte en molnsky till skjul, och eld om nattena till att lysa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'De bådo, och han lät komma åkerhöns; och han mättade dem med himmelsbröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Han öppnade bergsklippona, och vatten flöt derut, så att bäcker flöto i torra öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Ty han tänkte på sitt helga ord, det han till Abraham sin tjenare talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Alltså förde han sitt folk ut med fröjd, och sina utkorade med glädje;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Och gaf dem Hedningarnas land, så att de folks gods intogo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'På det de skulle hålla hans rätter, och bevara hans lag. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halleluja. Tacker Herranom, ty han är mild, och hans godhet varar i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Ho kan uttala Herrans dråpeliga gerningar? och prisa all hans lofliga verk?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Salige äro de som budet hålla, och göra alltid rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Herre, tänk på mig efter den nåd, som du dino folke lofvat hafver; bevisa oss dina hjelp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Att vi måge se dina utkorades välfärd, och glädja oss att dino folke väl går, och berömma oss med dinom arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Vi hafve syndat med våra fäder; vi hafve misshandlat, och hafve ogudaktige varit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Våre fäder uti Egypten ville icke förstå din under; de tänkte icke på dina stora godhet, och voro ohörige vid hafvet, nämliga röda hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Men han halp dem för sitt Namns skull, så att han sina magt beviste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Och han näpste röda hafvet, och det vardt torrt; och förde dem genom djupen, såsom genom ena öken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Och halp dem ifrå deras hand, som dem hatade, och förlossade dem ifrå fiendans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Och vattnet fördränkte deras fiendar, så att icke en qvar blef.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Då trodde de uppå hans ord, och söngo hans lof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Men de förgåto snarliga hans gerningar, och bidde intet efter hans råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Och de fingo lusta i öknene, och försökte Gud uti ödemarkene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Men han gaf dem deras bön, och sände dem nog, tilldess dem vämjade dervid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Och de satte sig upp emot Mose i lägrena; emot Aaron, Herrans heliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Jorden öppnade sig, och uppsvalg Dathan, och öfvertäckte Abirams rota.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Och eld vardt ibland deras rota upptänd; lågen uppbrände de ogudaktiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'De gjorde en kalf i Horeb, och tillbådo det gjutna belätet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Och förvandlade sina äro uti ens oxas liknelse, den gräs äter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'De förgåto Gud sin Frälsare, som så stor ting uti Egypten gjort hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Vidunder i Hams land, och förskräckeliga gerningar i röda hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Och han sade, att han ville förgöra dem, om Mose hans utkorade den plågan icke förtagit hade, och afvändt hans grymhet, att han icke platt skulle förderfva dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Och de föraktade det lustiga landet; de trodde icke hans ordom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Och knorrade i deras hyddom; de lydde intet Herrans röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Och han hof upp sina hand emot dem, att han skulle nederslå dem i öknene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Och kasta deras säd ibland Hedningarna, och förströ dem i landen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Och de gåfvo sig till BaalPeor, och åto af de döda afgudars offer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Och förtörnade honom med sin verk; då kom ock en plåga ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Då trädde Pinehas fram, och förlikte sakena, och plågan vände åter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Och det vardt honom räknadt till rättfärdighet, ifrå slägte till slägte, i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Och de förtörnade honom vid trätovattnet; och de plågade Mose illa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Ty de bedröfvade honom hans hjerta, så att någor ord undföllo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'De förgjorde ock icke de folk, som dock Herren dem budit hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Utan de blandade sig ibland Hedningarna, och lärde deras verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Och tjente deras afgudom; de kommo dem på förargelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Och de offrade sina söner, och sina döttrar djeflom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Och utgöto oskyldigt blod, sina söners och döttrars blod, som de offrade Canaans afgudom; så att landet med blodskulder besmittadt vardt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Och orenade sig med sinom gerningom, och hor bedrefvo med sin verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Då förgrymmade sig Herrans vrede öfver sitt folk, och han fick en styggelse till sitt arf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Och gaf dem uti Hedningars händer; så att öfver dem rådde de som dem hätske voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Och deras fiender plågade dem, och de vordo kufvade under deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Han förlossade dem ofta; men de förtörnade honom med sin verk, och vordo få för deras missgerningars skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Och han såg till deras nöd, då han deras klagan hörde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Och tänkte på sitt förbund, som han med dem gjort hade; och det ångrade honom efter hans stora godhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Och lät dem komma till barmhertighet, för allom dem som dem fångat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Hjelp oss, Herre vår Gud, och för oss tillhopa ut ifrå Hedningarna; att vi måge tacka ditt helga Namn, och begå ditt lof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Lofvad vare Herren, Israels Gud, ifrån evighet i evighet; och allt folk säga: Amen. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Tacker Herranom, ty han är mild, och hans godhet varar i evighet:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Säger I, som af Herranom förlöste ären, de han utu nöd förlöst hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Och de han utu landen tillsammanhemtat hafver, ifrån östan, ifrå vestan, ifrå nordan, och ifrå hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'De der vilse gingo i öknene, der ingen väg var, och funno ingen stad, der de bo kunde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Hungroge och törstige, och deras själ försmäktade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Och de ropade till Herran i deras nöd, och han frälste dem utu deras ångest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Och förde dem en rättan väg, att de gingo till den stad, der de bo kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'De skola tacka Herranom för hans godhet, och för hans under, som han med menniskors barn gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Att han mättar den törstiga själen, och fyller den hungroga själen med god ting;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'De der sitta måste i mörker och dödsens skugga, fångne i tvång och i jern.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Derföre, att de Guds bud ohörsamme varit hade, och dens Högstas lag försmädat hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Derföre måste deras hjerta med olycka plågadt varda; så att de omkull lågo, och ingen halp dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Och de ropade till Herran i deras nöd, och han halp dem utu deras ångest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Och förde dem utu mörkret och dödsens skugga, och slet deras band sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'De skola tacka Herranom för hans godhet, och för hans under, som han med menniskors barn gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Att han sönderbryter kopparportar, och sönderslår jernbommar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'De galne vordo plågade för deras öfverträdelses skull, och för deras synders skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'De vämjade vid all mat, och vordo dödsjuke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Och de ropade till Herran i deras nöd, och han halp dem utu deras ångest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Han sände sitt ord, och gjorde dem helbregda, och frälste dem, att de icke blefvo döde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'De skola tacka Herranom för hans godhet, och för hans under, som han med menniskors barn gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Och offra tacksägelse, och förtälja hans verk med glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'De som med skepp på hafvet fara, och drifva sin handel till sjös;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'De hafva förnummit Herrans verk, och hans under i hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'När han sade, att ett stormväder uppkastade sig, som böljorna upplyfte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Och de foro upp åt himmelen, och foro neder i afgrunden, att deras själ förtviflade för ångest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Så att de raglade och stapplade, såsom en drucken, och visste ingen råd mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Och de ropade till Herran i sine nöd, och han förde dem utu deras ångest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Och stillte stormen, att böljorna saktade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Och de vordo glade, att det stilla vardt; och han förde dem till lands efter deras önska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'De skola tacka Herranom för hans godhet, och för hans under, som han med menniskors barn gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Och prisa honom i församlingene, och inför de äldsta lofva honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'De, hvilkas bäcker förtorkades, och vattukällor vände igen flyta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Så att ett fruktsamt land intet bar, för deras ondskos skull, som deruti bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Och det som torrt var gjorde han vatturikt, och på torra landena vattukällor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Och satte dit de hungroga, att de beredde en stad, der de bo kunde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Och så åkrar, och vingårdar plantera måtte, och årliga frukt få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Och han dem välsignade, så att de sig svårliga förökade, och dem mycken boskap gaf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'De der nedertryckte och försvagade voro af de onda, som dem tvungit och trängt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Då föraktelse uppå Förstarna utgjuten var, så att i hela landena stod bistert och ödeliga till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Och han den fattiga beskyddade för uselhet, och hans slägte förmerade, såsom en fårahjord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Detta skola de fromme se, och glädja sig; och alla ondsko skall munnen tillstoppad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Hvilken är vis och behåller detta? Så skola de märka, huru många välgerningar Herren beviser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'En Psalmvisa Davids.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Gud, det är mitt rätta allvar, jag vill sjunga. och lofva; min ära också.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Vaka upp, psaltare och harpa, jag vill bittida uppe vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Jag vill tacka dig, Herre, ibland folken; jag vill lofsjunga dig ibland menniskorna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Ty din nåd räcker så vidt som himmelen är; och din sanning så vidt som skyarna gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Upphöj dig, Gud, öfver himmelen, och din äro öfver all land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'På det dine älskelige vänner måga förlossade varda; hjelp med dina högra hand, och bönhör mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gud talar i sinom helgedom, dess gläder jag mig; och vill skifta Sichem, och afmäta den dalen Succoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Gilead är min, Manasse är ock min, och Ephraim är mins hufvuds magt. Juda är min Förste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moab är mitt tvättekar; jag vill sträcka mina skor öfver Edom; öfver de Philisteer vill jag fröjdas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Ho vill föra mig uti en fast stad? Ho vill leda mig intill Edom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Skall icke du göra det, Gud, som oss förkastat hafver, och drager icke ut, Gud, med vårom här?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Skaffa oss bistånd i nödene; ty menniskos hjelp är fåfängelig. I Gudi vilje vi bevisa manlig verk; han skall underträda våra fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'En Psalm Davids, till att föresjunga. Gud, mitt lof, tig icke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Ty de hafva upplåtit sin ogudaktiga och falska mun emot mig, och tala emot mig med falska tungor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Och de tala hätskeliga emot mig allestäds, och strida emot mig utan sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Derföre, att jag älskar dem, äro de emot mig; men jag beder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'De bevisa mig ondt för godt, och hat för min kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Sätt ogudaktiga öfver honom, och Satan stånde på hans högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Den som sig af honom lära låter, hans lefverne vare ogudaktigt, och hans bön vare synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Varde hans dagar få, och hans ämbete tage en annar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Varde hans barn faderlös, och hans hustru enka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Hans barn gånge husvill och tigge, och söke, såsom de der förderfvade äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'De ockrare utsuge allt det han hafver, och de främmande bortröfve hans gods.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Och ingen bevise honom godt, och ingen förbarme sig öfver hans faderlösa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Hans efterkommande varde utrotade; deras namn varde i androm led utplånad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'På hans fäders missgerning varde tänkt för Herranom, och hans moders synd varde intet utplånad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Herren låte dem aldrig komma utu sin ögnasyn, och deras åminnelse varde utrotad på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Derföre att han så platt ingen barmhertighet hade; utan förföljde den elända och fattiga, och den bedröfvada, till att dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Och han ville hafva förbannelse, den skall ock komma honom; han ville icke välsignelse, så skall hon ock vara långt ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Och han drog förbannelse uppå sig, såsom sina skjorto; och hon är ingången i hans inelfver, såsom vatten, och såsom olja uti hans ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Hon varde honom såsom en klädnad, den han uppå sig hafver, och såsom ett bälte, der han allestädes omgjordar sig med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Alltså ske dem af Herranom, som mig emot äro, och tala ondt emot mina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Men du, Herre, Herre, var du med mig för ditt Namns skull; ty din nåd är min tröst, fräls mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Ty jag är fattig och elände; mitt hjerta är bedröfvadt i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Jag går bort såsom en skugge, den fördrifven varder, och varder förjagad såsom gräshoppor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Min knä äro svage af fasto, och mitt kött är magert, och hafver ingen fetma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Och jag måste vara deras begabberi; när de se mig, rista de sitt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Gör mig bistånd, Herre, min Gud; hjelp mig efter dina nåd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Att de måga förnimma, att det är din hand; att du, Herre, detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Förbanna de, så välsigna du; sätta de sig emot mig, så varde de till skam; men din tjenare glädje sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Mine motståndare varde med försmädelse beklädde, och varde med sine skam öfvertäckte, såsom med en kjortel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Jag vill mycket tacka Herranom med min mun, och lofva honom ibland många.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Ty han står dem fattiga på högra handene, att han skall hjelpa honom ifrå dem som hans lif fördöma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'En Psalm Davids. Herren sade till min Herra: Sätt dig på mina högra hand, tilldess jag lägger dina fiendar till din fotapall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Herren skall sända dins rikes spiro utaf Zion; var rådandes ibland dina fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Efter din seger skall ditt folk välviljeliga offra dig i heligo prydning; dine barn varda dig födde såsom daggen af morgonrodnaden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Herren hafver svorit, och honom skall det intet ångra: Du äst en Prest evinnerliga, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Herren på dine högra hand skall slå Konunga i sine vredes tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Han skall döma ibland Hedningarna; han skall göra stora slagtningar. Han skall sönderkrossa hufvudet öfver stor land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Han skall dricka af bäcken på vägenom, derföre skall han upphäfva hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halleluja. Jag tackar Herranom af allo hjerta, uti de frommas råd, och i församlingene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Store äro Herrans verk; den som uppå dem aktar, hafver lust deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Hvad han skickar, det är lofligit och härligit, och hans rättfärdighet blifver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Han hafver gjort en åminnelse till sina under, den nådelige och barmhertige Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Han gifver mat dem som frukta honom; han tänker evinnerliga uppå sitt förbund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Han låter förkunna små väldiga gerningar sino folke, att han skall gifva dem Hedningarnas arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Hans händers verk äro sanning och rätt; all hans bud äro rättsinnige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'De blifva vid magt alltid och evinnerliga, och ske troliga och redeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Han sänder sino folke förlossning; han lofvar, att hans förbund skall evinnerliga blifva; heligt och förskräckeligit är hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Herrans fruktan är vishetenes begynnelse; det är ett godt förstånd, den derefter gör; hans lof blifver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halleluja. Säll är den som Herran fruktar, den som stor lust hafver till hans bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Hans säd skall väldig vara på jordene; de frommas slägte skall välsignadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Rikedom och ymnoghet skall vara i hans hus, och hans rättfärdighet blifver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Dem fromma går ljus upp i mörkret, af den nådeliga, barmhertiga och rättfärdiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Säll är den som barmhertig är, och gerna lånar; och lagar så sina saker, att han ingom orätt gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Ty han skall blifva evinnerliga; den rättfärdige skall aldrig förgäten varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'När en plåga kommer, fruktar han sig intet; hans hjerta hoppas stadeliga uppå Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Hans hjerta är tröst, och fruktar sig intet, tilldess han på sina fiendar lust ser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Han utströr, och gifver dem fattigom; hans rättfärdighet blifver evinnerliga; hans horn skall upphöjdt varda med äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Den ogudaktige skall det se, och honom skall förtrytat; sina tänder skall han bita tillsamman, och förgås; ty hvad de ogudaktige gerna vilja, det blifver omintet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja. Lofver, I Herrans tjenare, lofver Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Lofvadt vare Herrans Namn, ifrå nu och i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Ifrå solenes uppgång, allt intill nedergången, vare Herrans Namn lofvadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Herren är hög öfver alla Hedningar; hans ära går så vidt som himmelen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Hvilken är såsom Herren vår Gud, den sig så högt satt hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Och ser uppå det nedriga, i himmelen och på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Den som den ringa upprättar utu stoftet, och upplyfter den fattiga utu träcken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Att han skall sätta honom bredovid Förstar, vid hans folks Förstar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Den der låter den ofruktsamma bo i huset, att hon en glad barnamoder varder! Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Då Israel ut ur Egypten drog, Jacobs hus ifrå främmande folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Då vardt Juda hans helgedom, Israel hans välde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Hafvet såg det, och flydde; Jordanen vände tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Bergen sprungo såsom lamb; högarna såsom ung får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Hvad var dig, du haf, att du flydde; och du Jordan, att du tillbakavände?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'I berg, att I sprungen såsom lamb; I högar, såsom ung får?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'För Herranom bäfvade jorden, för Jacobs Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Den bergsklipporna förvandlar uti vattusjöar, och stenen i vattukällor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Icke oss, Herre, icke oss, utan dino Namne, gif ärona, för dina nåde och sannings skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Hvi skulle Hedningarna säga: Hvar är nu deras Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Men vår Gud är i himmelen; han kan göra hvad han vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Men deras afgudar äro silfver och guld, med menniskors händer gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'De hafva mun, och tala intet; de hafva ögon, och se intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'De hafva öron, och höra intet; de hafva näso, och lukta intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'De hafva händer, och taga intet; fötter hafva de, och gå intet; och tala intet genom deras hals.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'De som sådana göra, äro likaså, alle de som hoppas uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Men Israel hoppes uppå Herran; han är deras hjelp och sköld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Aarons hus hoppes uppå Herran; han är deras hjelp och sköld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'De der Herran frukta, hoppes ock uppå Herran; han är deras hjelp och sköld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Herren tänker uppå oss, och välsignar oss; han välsignar Israels hus, han välsignar Aarons hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Han välsignar dem som frukta Herran, både små och stora.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Herren välsigne eder, ju mer och mer, eder och edor barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'I ären Herrans välsignade, den himmel och jord gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Himmelen allt omkring är Herrans; men jordena hafver han gifvit menniskors barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'De döde kunna dig, Herre, intet lofva; ej heller de som nederfara i det stilla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Utan vi lofve Herran, ifrå nu och i evighet. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Det är mig ljuft, att Herren hörer mina röst och mina bön;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Att han böjer sina öron till mig; derföre vill jag åkalla honom i mina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Dödsens snaror hade omfattat mig, och helvetes ångest hade råkat uppå mig; jag kom i jämmer och nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Men jag åkallade Herrans Namn: O! Herre, fräls mina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Herren är nådelig och rättfärdig, och vår Gud är barmhertig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Herren bevarar de enfaldiga; när jag nederligger så hjelper han mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Var nu åter tillfrids, min själ; ty Herren gör dig godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Ty du hafver uttagit mina själ utu dödenom, mina ögon ifrå tårar, min fot ifrå fall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Jag vill vandra för Herranom uti de lefvandes lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Jag tror, derföre talar jag; men jag varder svårliga plågad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Jag sade i min häpenhet: Alla menniskor äro lögnaktige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Huru skall jag vedergälla Herranom alla hans välgerningar, som han mig gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Jag vill taga den helsosamma kalken, och predika Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Jag vill betala mina löften Herranom, för allt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Hans helgons död är dyr hållen för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'O! Herre, jag är din tjenare; jag är din tjenare, dine tjenarinnos son; du hafver sönderslitit mina band.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Dig vill jag offra tacksägelse, och predika Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Jag vill betala mina löften Herranom, för allt hans folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Uti gårdarna åt Herrans hus, uti dig, Jerusalem. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Lofver Herran, alle Hedningar; priser honom, all folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Ty hans nåd är väldig öfver oss, och Herrans sanning (varar) i evighet. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Tacker Herranom, ty han är mild, och hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Nu säge Israel: Hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Nu säge Aarons hus: Hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Nu säge de som Herran frukta: Hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Uti ångest åkallade jag Herran; och Herren bönhörde mig, och tröste mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Herren är med mig, derföre fruktar jag mig intet; hvad kunna menniskor göra mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Herren är med mig, till att hjelpa mig; och jag vill lust se på mina fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Det är godt att förtrösta på Herran, och icke förlåta sig på menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Det är godt att förtrösta uppå Herran, och icke förlåta sig på Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Alle Hedningar belägga mig; men i Herrans Namn vill jag förgöra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'De kringhvärfva mig på alla sidor; men i Herrans Namn vill jag nederlägga dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'De omlägga mig såsom bi, de släcka såsom eld i törne; men i Herrans Namn vill jag förgöra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Man stöter mig, att jag falla skall; men Herren hjelper mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Herren är min magt, och min psalm; och är min salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Man sjunger med glädje om seger uti de rättfärdigas hyddom; Herrans högra hand behåller segren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Herrans högra hand är upphöjd; Herrans högra hand behåller segren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Jag skall icke dö, utan lefva, och förkunna Herrans gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Herren näpser mig väl; men han gifver mig icke dödenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Upplåter mig rättfärdighetenes portar, att jag må der ingå, och tacka Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Det är Herrans port, de rättfärdige skola der ingå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Jag tackar dig, att du näpste mig, och halp mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Den stenen, som byggningsmännerna förkastade, är till en hörnsten vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Det är skedt af Herranom, och är ett under för vår ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Detta är den dagen, den Herren gör; låt oss på honom fröjdas och glädjas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'O! Herre, hjelp; o! Herre, låt väl gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Lofvad vare den som kommer i Herrans Namn; vi välsigne eder, som af Herrans hus ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Herren är Gud, den oss upplyser; pryder högtidena med löf, allt intill hornen på altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Du äst min Gud, och jag tackar dig; min Gud, jag vill prisa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Tacker Herranom, ty han är mild, och hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Salige äro de som utan vank lefva, de som i Herrans lag vandra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Salige äro de som hans vittnesbörd hålla; de som af allo hjerta söka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Ty de som på hans vägom vandra, de göra intet ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Du hafver budit, att hålla dina befallningar fliteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'O! att mitt lif hölle dina rätter med fullt allvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'När jag skådar uppå all din bud, så kommer jag icke på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Jag tackar dig af rätt hjerta, att du lärer mig dina rättfärdighets rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Dina rätter vill jag hålla; öfvergif mig dock aldrig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Huru skall en yngling sin väg ostraffeliga gå? När han håller sig efter din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Jag söker dig af allo hjerta; Låt mig icke fela om din bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Jag behåller din ord i mitt hjerta, på det jag icke skall synda emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Lofvad vare du, Herre; lär mig dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Jag vill med mina läppar förtälja alla dins muns rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Jag fröjdar mig af dins vittnesbörds väg, såsom af allahanda rikedomar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Jag talar det du befallt hafver, och ser på dina vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Jag hafver lust till dina rätter, och förgäter icke din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Gör väl med din tjenare, att jag må lefva och hålla din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Öppna mig ögonen, att jag må se under i din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Jag är en gäst på jordene; fördölj icke din bud för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Min själ är all sönderkrossad för trängtans skull, efter dina rätter alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Du näpser de stolta; förbannade äro de som vika ifrå din bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Vänd ifrå mig försmädelse och föraktelse; ty jag håller din vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Sitta ock Förstarna och tala emot mig; men din tjenare talar om dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Jag hafver lust till din vittnesbörd; de äro mine rådgifvare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Min själ ligger i stoft; vederqvick mig efter ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Jag förtäljer mina vägar, och du bönhörer mig; lär mig dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Undervisa mig dina befallningars väg, så vill jag tala om din under.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Jag grämer mig så att hjertat mig försmäktas; styrk mig efter ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Vänd ifrå mig den falska vägen, och unna mig din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Jag hafver utvalt sanningenes väg; dina rätter hafver jag mig föresatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Jag håller mig intill din vittnesbörd; Herre, låt mig icke på skam komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'När du mitt hjerta tröstar, så löper jag dins buds väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Lär mig, Herre, dina rätters väg, att jag må bevara dem intill ändan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Undervisa mig, att jag må bevara din lag, och hålla dem af allo hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'För mig in på din buds stig, ty jag hafver der lust till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Böj mitt hjerta till din vittnesbörd, och icke till girighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Vänd bort min ögon, att de icke se efter onyttig läro; utan vederqvick mig på dinom väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Låt din tjenare hålla din bud stadeliga för din ord, att jag må frukta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Vänd ifrå mig den försmädelse, som jag fruktar; ty dine rätter äro lustige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Si, jag begärar dina befallningar; vederqvick mig med dine rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Herre, låt mig vederfaras dina nåd; dina hjelp efter ditt ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Att jag mina lastare svara må; ty jag förlåter mig uppå ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Och tag ju icke ifrå minom mun sanningenes ord; ty jag hoppas uppå dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Jag vill hålla din lag allstädes, alltid och evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Och jag vandrar i glädje; ty jag söker dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Jag talar om din vittnesbörd inför Konungar, och blyges intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Och hafver lust till din bud, och de äro mig käre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Och lyfter mina händer upp till din bud, de mig kär äro; och talar om dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Tänk dinom tjenare uppå ditt ord, på hvilket du låter mig hoppas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Det är min tröst i mitt elände; ty ditt ord vederqvicker mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'De stolte hafva deras gabberi af mig; likväl viker jag icke ifrå din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Herre, när jag tänker, huru du af verldenes begynnelse dömt hafver, så varder jag tröstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Jag brinner innan, för de ogudaktiges skull, som din lag öfvergifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Dine rätter äro min visa i mino huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Herre, jag tänker om nattena på ditt Namn, och håller din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Det är min skatt, att jag dina befallningar håller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Jag hafver sagt, Herre: Det skall mitt arf vara, att jag dina vägar håller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Jag beder inför ditt ansigte af allo hjerta; var mig nådelig efter ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Jag betraktar mina vägar, och vänder mina fötter till din vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Jag skyndar mig, och dröjer intet, till att hålla din bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'De ogudaktigas rote beröfvar mig; men jag förgäter intet din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Om midnatt står jag upp, till att tacka dig för dina rättfärdighets rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Jag håller mig till alla dem som frukta dig, och dina befallningar hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Herre, jorden är full af dine godhet; lär mig dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Du gör dinom tjenare godt, Herre, efter ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Lär mig goda seder och förståndighet; ty jag tror dinom budom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Förr än jag späkt vardt, for jag vill; men nu håller jag ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Du äst mild och god; lär mig dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'De stolte dikta lögn öfver mig; men jag håller dina befallningar af allt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Deras hjerta är fett vordet, såsom flott; men jag hafver lust till din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Det är mig ljuft att du hafver späkt mig, att jag må lära dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Dins muns lag är mig täckare, än mång tusend stycke guld och silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Din hand hafver gjort och beredt mig; undervisa mig, att jag må lära din bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'De som dig frukta, de se mig, och glädja sig; ty jag hoppas uppå din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Herre, jag vet att dina domar äro rätte, och du hafver troliga späkt mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Din nåd vare min tröst, såsom du dinom tjenare lofvat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Låt mig vederfaras dina barmhertighet, att jag må lefva; ty jag hafver lust till din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Ack! att de stolte måtte komma på skam, som mig med lögn nedertrycka; men jag talar om dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Ack! att de måtte hålla sig till mig, som dig frukta, och känna din vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Mitt hjerta blifve rättsinnigt i dinom rättom, att jag icke på skam kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Min själ trängtar efter dina salighet; jag hoppas uppå ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Min ögon trängta efter ditt ord, och säga: När vill du trösta mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Ty jag är såsom en lägel i rök; dina rätter förgäter jag icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Huru länge skall din tjenare bida? När vill du dom hålla öfver mina förföljare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'De stolte grafva mig gropar, hvilka intet äro efter din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Dine bud äro alltsamman sanning; de förfölja mig med lögn, hjelp mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'De hade fulltnär förgjort mig på jordene; men jag öfvergifver icke dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Vederqvick mig genom dina nåd, att jag må hålla dins muns vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Herre, ditt ord blifver evinnerliga, så vidt som himmelen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Din sanning varar i evighet; du hafver tillredt jordena, och hon blifver ståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Det blifver dagliga efter ditt ord; ty all ting måste tjena dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Om din lag icke hade min tröst varit, så vore jag förgången i mitt elände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Jag vill aldrig förgäta dina befallningar; ty du vederqvicker mig med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Jag är din, hjelp mig; ty jag söker dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'De ogudaktige vakta uppå mig, att de måga förgöra mig; men jag aktar uppå din vittnesbörd,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Jag hafver på all ting en ända sett; men ditt bud är varaktigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Huru hafver jag din lag så kär; dageliga talar jag derom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Du gör mig med ditt bud visare, än mina fiender äro; ty det är evinnerliga min skatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Jag är lärdare, än alle mine lärare; ty din vittnesbörd äro mitt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Jag är förståndigare, än de gamle; ty jag håller dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Jag förtager minom fotom alla onda vägar, att jag må hålla din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Jag viker icke ifrå dina rätter; ty du lärer mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Din ord äro minom mun sötare än hannog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Ditt ord gör mig förståndigan; derföre hatar jag alla falska vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Ditt ord är mina fötters lykta, och ett ljus på minom vägom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Jag svär, och vill hållat, att jag dina rättfärdighets rätter hålla vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Jag är svårliga plågad; Herre, vederqvick mig efter ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Låt dig behaga, Herre, mins muns välviljoga offer, och lär mig dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Jag bär mina själ i mina händer alltid, och jag förgäter icke din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'De ogudaktige sätta mig snaror; men jag far icke vill ifrå dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Din vittnesbörd äro mitt eviga arf; ty de äro mins hjertas fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Jag böjer mitt hjerta till att göra efter dina rätter alltid och evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Jag hatar de ostadiga andar, och älskar din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Du äst mitt beskärm och sköld; jag hoppas uppå ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Viker ifrå mig, I onde; jag vill hålla min Guds bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Uppehåll mig igenom ditt ord, att jag må lefva; och låt mig icke på skam komma med mitt hopp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Stärk mig, att jag må blifva salig; så vill jag alltid lust hafva till dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Du förtrampar alla dem som villa gå om dina rätter; ty deras bedrägeri är alltsammans lögn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Du bortkastar alla ogudaktiga på jordene som slagg; derföre älskar jag din vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Jag fruktar mig för dig, så att mitt kött skälfver; och förskräcker mig for dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Jag aktar uppå rätt och rättfärdighet; öfvergif mig icke dem som mig öfvervåld göra vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Beskärma du din tjenare, och tröst honom, att de stolte icke göra mig öfvervåld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Mina ögon trängta efter dina salighet, och efter dine rättfärdighets ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Handla med dinom tjenare efter dina nåd; och lär mig dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Jag är din tjenare; undervisa mig, att jag må känna din vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Det är tid, att Herren gör der något till; de hafva omintetgjort din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Derföre älskar jag din bud, öfver guld och öfver fint guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Derföre håller jag rätt fram i alla dina befallningar; jag hatar allan falskan väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Underliga äro din vittnesbörd, derföre håller dem min själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'När ditt ord uppenbaradt varder, så fröjdar det, och gör de enfaldiga visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Jag öppnar min mun, och begärar din bud; ty mig längtar efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Vänd dig till mig, och var mig nådelig, såsom du plägar göra dem som ditt Namn älska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Låt min gång viss vara i dino orde, och låt ingen orätt öfver mig råda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Förlös mig ifrå menniskors orätt; så vill jag hålla dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Låt ditt ansigte lysa öfver din tjenare, och lär mig dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Mine ögon flyta med vatten, att man icke håller din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Herre, du äst rättfärdig, och rätt är ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Du hafver dina rättfärdighets vittnesbörd, och sanningena hårdeliga budit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Jag hafver när harmats till döds, att mine ovänner hafva din ord förgätit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Ditt ord är väl bepröfvadt, och din tjenare hafver det kärt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Jag är ringa och föraktad; men jag förgäter icke dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Din rättfärdighet är en evig rättfärdighet, och din lag är sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Ångest och nöd hafva drabbat uppå mig; men jag hafver lust till din bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Dins vittnesbörds rättfärdighet är evig; undervisa mig, så lefver jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Jag ropar af allo hjerta, bönhör mig, Herre, att jag må hålla dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Jag ropar till dig, hjelp mig, att jag må hålla din vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Jag kommer bittida, och ropar; uppå ditt ord hoppas jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Jag vakar bittida upp, att jag må handla om din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Hör mina röst efter dina nåde: Herre, vederqvick mig efter dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Mine arge förföljare vilja till mig, och äro långt ifrå din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Herre, du äst hardt när, och din bud äro alltsamman sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Men jag vet det långt tillförene, att du din vittnesbörd evinnerliga grundat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Se uppå mitt elände, och fräls mig; hjelp mig ut; förty jag förgäter icke din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Uträtta min sak, och förlossa mig; vederqvick mig igenom ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Saligheten är långt ifrå de ogudaktiga; ty de akta intet dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Herre, din barmhertighet är stor; vederqvick mig efter dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Mine förföljare och ovänner äro månge; men jag viker icke ifrå din vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Jag ser de föraktare, och det gör mig ondt, att de icke hålla din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Si, jag älskar dina befallningar; Herre, vederqvick mig efter din nåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Ditt ord hafver af begynnelsen varit sanning; alle dine rättfärdighets rätter vara evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Förstarna förfölja mig utan sak, och mitt hjerta fruktar sig för din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Jag gläder mig öfver din ord, såsom en den stort byte får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Lögnene är jag hätsk, och stygges dervid, men din lag hafver jag kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Jag lofvar dig sju resor om dagen, för dine rättfärdighets rätters skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Stor frid hafva de som din lag älska, och de skola icke stappla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Herre, jag väntar efter din salighet, och gör efter din bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Min själ håller din vittnesbörd, och hafver dem mycket kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Jag håller dina befallningar, och dina vittnesbörder; ty alle mine vägar äro för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Herre, låt min klagan för dig komma; undervisa mig efter ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Låt mina bön komma för dig; fräls mig efter ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Mine läppar skola lofva, när du lärer mig dina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Min tunga skall tala om ditt ord; ty all din bud äro rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Låt dina hand vara mig biståndiga; ty jag hafver utkorat dina befallningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Herre, jag längtar efter din salighet, och hafver lust till din lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Låt mina själ lefva, att hon må lofva dig, och dine rätter hjelpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Jag är såsom ett villfarande och borttappadt får; sök din tjenare, ty jag förgäter icke din bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'En visa i högre choren. Jag ropar till Herran i mine nöd, och han bönhörer mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Herre, fräls mina själ ifrå lögnaktiga munnar, och ifrå falska tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Hvad kan den falska tungan göra dig? Och hvad kan hon uträtta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Hon är såsom ens väldigs skarpe pilar, såsom eld i enebärsträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Ve mig, att jag en främling är ibland Mesech; jag måste bo ibland Kedars hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Det varder mine själ långt att bo när dem, som friden hata.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Jag håller frid; men när jag talar, så taga de till att örliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'En visa i högre choren. Jag lyfter min ögon upp till bergen, ifrå hvilkom mig hjelp kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Min hjelp kommer ifrå Herranom, den himmel och jord gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Han skall icke låta din fot slinta; och den dig bevarar, han sofver icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Si, den som Israel bevarar, han är icke sömnog eller sofver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Herren bevarar dig; Herren är din skygd öfver dina högra hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Att solen icke skall skada dig om dagen, eller månen om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Herren bevare dig för allt ondt; han bevare dina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Herren bevara din utgång och ingång, ifrå nu och i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'En visa Davids i högre choren. Jag glädes i det mig sagdt är, att vi skole gå in uti Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Och att våre fötter skola stå i dinom portom, Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalem är bygdt, att det skall vara en stad, der man tillsammankomma skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Dit slägterna uppgå skola, nämliga Herrans slägter, till att predika Israels folke, till att tacka Herrans Namne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Ty der äro satte stolar till doms, Davids hus stolar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Önsker Jerusalem lycko; dem gånge väl, som dig älska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Frid vare innan dina murar, och lycka i dina palats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'För mina bröders och fränders skull vill jag dig frid önska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'För Herrans vår Guds hus skull vill jag ditt bästa söka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'En visa i högre choren. Jag lyfter min ögon upp till dig, du som i himmelen sitter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Si, såsom tjenarenas ögon uppå deras herrars händer se; såsom tjenarinnones ögon uppå sine frues händer; alltså se vår ögon uppå Herran vår Gud, tilldess han oss nådelig varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Var oss nådelig, Herre, var oss nådelig; ty vi äre fast fulle med föraktelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Fast full är vår själ af de stoltas begabberi, och de högfärdigas föraktelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'En visa Davids i högre choren. Om Herren icke med oss vore; så säge Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Om Herren icke med oss vore, när menniskorna sig emot oss sätta,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Så uppsvulge de oss lefvande, då deras vrede sig öfver oss förgrymmar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Så fördränkte oss vatten; strömmar ginge öfver våra själar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Vatten ginge allt för högt öfver våra själar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Lofvad vare Herren, att han icke gifver oss till rofs uti deras tänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Vår själ är undkommen, såsom en fogel ens foglafängares snaro; snaran är söndergången, och vi äre löse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Vår hjelp står i Herrans Namn, den himmel och jord gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'En visa i högre choren. De som hoppas uppå Herran, de skola icke falla, utan evinnerliga blifva, såsom det berget Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Omkring Jerusalem äro berg; och Herren är omkring sitt folk, ifrå nu och i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Ty de ogudaktigas spira skall icke blifva öfver de rättfärdigas hop; på det de rättfärdige icke skola uträcka sina hand till orättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Herre, gör väl vid dem som gode och fromhjertade äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Men de som afvika uppå deras vrånga vägar, dem skall Herren bortdrifva med de ogerningsmän. Men frid vare öfver Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'En visa i högre choren. När Herren Zions fångar lösandes varder, så skole vi varda såsom drömmande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Då skall vår mun full med löje varda, och vår tunga full med fröjd: då skall man säga ibland Hedningarna: Herren hafver gjort stor ting med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Herren hafver gjort stor ting med oss; dess äre vi glade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Herre, vänd vårt fängelse, såsom du de strömmar söderut uttorkat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'De som med tårar så, skola med glädje uppskära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'De gå åstad och gråta, och bära ut ädla säd; och komma med glädje, och bära sina kärfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'En visa Salomos, i högre choren. Om Herren icke bygger huset, så arbeta de fåfängt, som derpå bygga; om Herren icke förvarar staden, så vaka väktarena fåfängt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Det är fåfängt, att I bittida uppstån, och sent gån till hvilo, och äten edart bröd med sorg; ty han gifver det sina vänner, vid de sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Si, barn äro en Herrans gåfva, och lifsfrukt är en skänk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Lika som skott uti en stark mans hand, så äro ock de unge dränger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Säll är den som sitt koger af dem full hafver; de komma icke på skam, då de med sina fiendar handla i portenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'En visa i högre choren. Säll är den som fruktar Herran, och på hans vägar går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Du skall föda dig af dina händers arbete; säll äst du, och väl är dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Din hustru skall vara såsom ett fruktsamt vinträ, allt omkring i ditt hus; dine barn såsom oliveqvistar kringom ditt bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Si, alltså varder välsignad den man, som Herran fruktar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Herren skall välsigna dig af Zion, att du skall få se Jerusalems välfärd, i alla dina lifsdagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Och skall få se din barnabarn; frid öfver Israel!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'En visa i högre choren. De hafva ofta trängt mig, allt ifrå min ungdom; så säge Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'De hafva ofta trängt mig, allt ifrå min ungdom; men de vordo mig icke öfvermägtige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'De plöjare hafva plöjt på min rygg, och dragit sina fårar långa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Herren, som rättfärdig är, hafver de ogudaktigas rep afhuggit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Ack! att på skam komma måtte och tillbakavända, alle de som Zion hätske äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Ack! att de måtte vara såsom gräs på taken, hvilket förtorkas, förr än det uppskärs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Af hvilkom skördemannen icke uppfyller sina hand, ej heller han, som binder kärfvarna, sin famn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Och de, som framom gå icke säga: Herrans välsignelse vare öfver eder; vi välsigne eder i Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'En visa i högre choren. Utu djupen ropar jag till dig, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Herre, hör mina röst; låt din öron akta uppå mins böns röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Om du, Herre, vill tillräkna synderna, Herre, ho kan blifva beståndandes?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Ty när dig är förlåtelse, att man skall frukta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Jag vänter efter Herran; min själ vänter, och jag hoppas uppå hans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Min själ vänter efter Herran, ifrå den ena morgonväkten till den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israel hoppes uppå Herran; ty när Herranom är nåd, och mycken förlossning när honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Och han skall förlossa Israel ifrån alla hans synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'En visa Davids i högre choren. Herre, mitt hjerta. är icke högfärdigt, och mina ögon äro icke stolta; och jag vandrar icke i stor ting, de mig för höge äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'När jag icke satte och stillte mina själ, så vardt min själ afvand, såsom en ifrå sine moder afvand varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israel hoppes uppå Herran, ifrå nu och i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'En visa i högre choren. Tänk, Herre, uppå David, och uppå allt hans lidande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Hvilken Herranom svor, och lofvade dem mägtiga i Jacob:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Jag vill icke gå i mins hus hyddo, eller lägga mig på mine sängs lägre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Jag vill icke låta mina ögon sofva, eller mina ögnalock sömnoga vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Tilldess jag må finna ett rum för Herranom, till en boning dem mägtiga i Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Si, vi höre derom i Ephrata; vi hafve funnit det på skogsmarkene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Vi vilje gå in uti hans boningar, och tillbedja inför hans fotapall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Herre, statt upp till dina ro, du och din magts ark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Låt dina Prester kläda sig med rättfärdighet, och dina heliga glädja sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Tag icke bort dins smordas regemente, for din tjenare Davids skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Herren hafver svorit David en sannan ed, der skall han intet ifrå träda: Jag skall sätta dig dins lifs frukt uppå din stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Om dina barn hålla mitt förbund, och min vittnesbörd, som jag dem lärandes varder, så skola ock deras barn sitta på dinom stol evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Ty Herren hafver utvalt Zion, och hafver lust till att bo der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Detta är min hvila evinnerliga, här vill jag bo; ty här behagar mig väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Jag vill välsigna dess spis, och gifva dess fattigom bröd nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Dess Prester vill jag bekläda med salighet, och dess helige skola glädja sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Dersammastäds skall uppgå Davids horn; jag hafver tillredt minom smorda ena lykto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Hans fiendar vill jag bekläda med skam; men öfver honom skall hans krona blomstras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'En visa Davids i högre choren. Si, huru godt och lustigt är det, att bröder bo endrägteliga tillsammans;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Såsom kosteligit balsam är, det af Aarons hufvud flyter neder i allt hans skägg, det nederflyter uppå hans kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Såsom Hermons dagg, och den på Zions berg nederfaller; ty dersammastäds lofvar Herren välsignelse och lif till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'En visa i högre choren. Si, lofver Herran, alle Herrans tjenare; I som stån om nattena i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Lyfter edra händer upp i helgedomenom, och lofver Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Herren välsigne dig af Zion, den himmel och jord gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halleluja. Lofver Herrans Namn; lofver, I Herrans tjenare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'I som stån i Herrans hus, uti vår Guds gårdar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Lofver Herran, ty Herren är god; lofsjunger hans Namn, ty det är ljufligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Ty Herren hafver utvalt sig Jacob; Israel till sin egendom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Ty jag vet, att Herren är stor; och vår Herre för alla gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Allt det Herren vill, det gör han, i himmelen, på jordene, i hafvet, och i all djup;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Den der låter skyarna uppgå af jordenes ända; den der ljungelden gör, samt med regnet; den der vädret utu hemlig rum komma låter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Den der förstfödingen slog uti Egypten, både af menniskor och af boskap;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Och lät sina tecken och under komma öfver dig, Egypti land, öfver Pharao och alla hans tjenare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Den mång folk slog, och drap mägtiga Konungar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihon, de Amoreers Konung, och Og, Konungen i Basan, och all Konungarike i Canaan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Och gaf deras land till arfs, till arfs sino folke Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Herre, ditt Namn varar i evighet; din åminnelse, Herre, varar förutan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Ty Herren skall döma sitt folk, och vara sina tjenare nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'De Hedningars gudar äro silfver och guld, med menniskors händer gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'De hafva mun, och tala intet; de hafva ögon, och se intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'De hafva öron, och höra intet, och ingen ande är i deras mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'De som sådana göra, äro lika så; alle de som hoppas på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Israels hus lofve Herran; lofver Herran, I af Aarons hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'I af Levi hus, lofver Herran; I som frukten Herran, lofver Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Lofvad vare Herren af Zion, den i Jerusalem bor. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Tacker Herranom, ty han är god; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Tacker alla gudars Gudi; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Tacker alla herrars Herra; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Den stor under gör allena; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Den himlarna skickeliga gjort hafver; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Den jordena på vatten utsträckt hafver; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Den stor ljus gjort hafver; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Solena till att förestå dagenom; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Månan och stjernorna till att förestå nattena; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Den Egypten slog på deras förstfödingar; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Och utförde Israel ifrå dem; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Med väldiga hand och uträcktom arm; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Den röda hafvet skifte i två delar; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Och lät Israel derigenom gå; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Den Pharao och hans här i röda hafvet störte; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Den sitt folk förde genom öknena; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Den stora Konungar slog; ty hans godhet varar evinnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Och drap mägtiga Konungar; ty hans godhet varar evinnerliga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihon, de Amoreers Konung; ty hans godhet varar evinnerliga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Och Og, Konungen i Basan; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Och gaf deras land till arfs; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Till arfs sinom tjenare Israel; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Ty han tänkte på oss, då vi undertryckte voro; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Och förlossade oss ifrå våra fiendar; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Den allo kötte mat gifver; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Tacker Gudi af himmelen; ty hans godhet varar evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Vid de älfver i Babel såte vi och grete, då vi på Zion tänkte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Våra harpor hängde vi på pilträ, som der äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Ty der bådo de oss sjunga, som oss fångna höllo, och i vår gråt glade vara: Sjunger oss ena af Zions Visor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Huru skulle vi sjunga Herrans viso i främmande land?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Om jag förgäter dig, Jerusalem, så varde min högra hand förgäten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Min tunga låde vid min gom, om jag icke tänker uppå dig; om jag icke låter Jerusalem min högsta glädje vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Herre, mins uppå Edoms barn, på Jerusalems dag; de der säga: Slår ned, slår ned i grund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Du förstörda dotter Babel, säll är den dig vedergäller, såsom du oss gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Säll är den, som dina unga barn tager, och slår dem emot stenen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Davids. Jag tackar dig af allo hjerta; inför gudarna vill jag lofsjunga dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Jag vill tillbedja emot ditt helga tempel, och tacka dino Namne för dina godhet och trohet; ty du hafver gjort ditt Namn härligit öfver all ting, genom ditt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'När jag åkallar dig, så bönhör mig, och gif mine själ stora kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Herre, alle Konungar på jordene tacka dig, att de höra dins muns ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Och sjunga på Herrans vägom, att Herrans ära stor är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Ty Herren är hög, och ser uppå det nedriga, och känner de högmodiga. fjerran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Om jag midt i ångest vandrar, så vederqvicker du mig, och räcker dina hand öfver mina fiendars vrede; och hjelper mig med dine högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Herren skall göra der en ända uppå för mina skuld; Herre, din godhet är evig; förlåt dock icke dina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'En Psalm Davids, till att föresjunga. Herre, du utransakar mig, och känner mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Ehvad jag sitter eller uppstår, vetst du det; du förstår mina tankar fjerran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Ehvad jag går, eller ligger, så äst du omkring mig, och ser alla mina vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Ty si, det är intet ord på mine tungo, det du, Herre, icke allt vetst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Du skaffar hvad jag både förr och efter gör, och håller dina hand öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Sådana kunskap är mig för underlig, och för hög; jag kan icke begripat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Hvart skall jag gå för dinom anda? Och hvart skall jag fly för ditt ansigte?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Fore jag upp i himmelen, så äst du der. Bäddade jag åt mig i helvete, si, så äst du ock der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Toge jag morgonrodnans vingar, och blefve ytterst i hafvet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Så skulle dock din hand der föra mig, och din högra hand hålla mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Om jag sade: Mörker må betäcka mig, så måste natten ock vara ljus omkring mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Ty ock mörkret är icke mörkt när dig, och natten lyser såsom dagen; mörkret är såsom ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Du hafver mina njurar i dine magt; du vast öfver mig i moderlifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Jag tackar dig derföre, att jag underliga gjord är. Underlig äro din verk, och det besinnar min själ väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Mine ben voro dig intet fördolde, då jag uti det hemliga gjord var; då jag skapad vardt nedre i jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Din ögon sågo mig, då jag ännu oberedd var; och alla dagar voro uti dine bok skrefne, de ännu varda skulle, och ingen af dem kommen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Men huru kostelige äro för mig, Gud, dina tankar! O! huru stort är deras tal!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Skulle jag räkna dem, så vorde de flere än sanden. När jag uppvaknar, är jag ändå när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Ack! Gud, att du dråpe de ogudaktiga, och de blodgirige ifrå mig vika måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Ty de tala om dig försmädeliga, och dine ovänner upphäfva sig utan sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Jag hatar ju, Herre, de som dig hata, och mig förtryter om dem, att de sig emot dig sätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Jag hatar dem med rätt allvar; derföre äro de mig hätske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Utransaka mig, Gud, och få veta mitt hjerta. Bepröfva mig, och förnim, huru jag menar det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Och se till, om jag på enom ondom väg är, och led mig på den eviga vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'En Psalm Davids, till att föresjunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Fräls mig, Herre, ifrån onda menniskor; bevara mig för vrångvisa män;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'De der ondt tänka i sin hjerta, och dagliga komma örlig åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'De hvässa sina tungo såsom en orm; huggormaförgift är under deras läppar. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Bevara mig, Herre, för de ogudaktigas hand. Bevara mig för vrångvisa menniskor, de der tänka till att omstöta min gång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'De högfärdige sätta mig snaror, och utsträcka mig rep till nät, och gildra för mig vid vägen. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Men jag säger till Herran: Du äst min Gud; Herre, förnim mine böns röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Herre, Herre, min starka hjelp; du beskärmar mitt hufvud i stridstidenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Herre, låt icke dem ogudaktiga sitt begär; styrk icke hans onda vilja; de måtte högmodas deraf. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Det onda, der mine fiender om rådslå, falle uppå deras hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Han skall utskudda öfver dem ljungeld. Han skall med eld slå dem djupt neder i jordena, så att de aldrig mer uppstå skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'En ond mun skall ingen lycko hafva på jordene. En vrångvis ond menniska skall förjagad och omstört varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Ty jag vet, att Herren skall uträtta dens eländas sak, och dens fattigas rätt. Och skola de rättfärdige tacka dino Namne, och de fromme skola för ditt ansigte blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'En Psalm Davids. Herre, jag ropar till dig, skynda dig till mig. Förnim mina röst, när jag åkallar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Min bön gälle inför dig såsom ett rökoffer; mina händers upphäfvande, såsom ett aftonoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Herre, bevara min mun, och bevara mina läppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Böj icke mitt hjerta till något det ondt är, till att föra ett ogudaktigt väsende med de ogerningsmän; att jag icke äter af det som dem lyster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Den rättfärdige slå mig vänliga, och straffe mig. Det skall göra mig så godt, som balsam på mitt hufvud; ty jag beder städse, att de icke skola göra mig skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Deras lärare störte öfver en sten; så skall man då sedan höra mina läro, att hon lustig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Vår ben äro förströdd allt intill helvetet, såsom då en upprifver och uppkastar jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Ty uppå dig, Herre, Herre, se min ögon. Jag tröster uppå dig; bortkasta icke mina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Bevara mig för den snaro, som de mig satt hafva, och för de ogerningsmäns gildre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'De ogudaktige falle med hvarannan uti sina egna nät; men jag gånge alltid framom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'En undervisning Davids, till att bedja, då han uti kulone var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Jag ropar till Herran med mine röst, och beder Herran med mine röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Jag utgjuter mitt tal för honom, och gifver honom mina nöd före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'När min ande i ångest är, så låter du dig vårda om mig. De sätta för mig snaror på vägen, der jag går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Skåda på högra handena; och se, der vill ingen känna mig. Jag kan icke undfly; ingen låter sig vårda om mine själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Herre, till dig ropar jag, och säger: Du äst mitt hopp, min del uti de lefvandes land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Akta uppå min klagan; ty jag varder svårliga plågad. Hjelp mig ifrå mina förföljare; ty de äro mig för mägtige. För mina själ utu fångahuset, att jag må tacka ditt Namn. De rättfärdige skola församla sig till mig, när du väl emot mig gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'En Psalm Davids. Herre, hör mina bön, förnim mina bön, för dina sannings skull; bönhör mig, för dina rättfärdighets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Och gack icke till doms med din tjenare; ty för dig är ingen lefvandes rättfärdig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Ty fienden förföljer mina själ, och sönderslår mitt lif till jordena. Han lägger mig i mörkret, såsom de döda i verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Och min ande är i mig bedröfvad; mitt hjerta är mig i mitt lif förtärdt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Jag tänker uppå de förra tider; jag talar om alla dina gerningar, och säger af dina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Jag uträcker mina händer till dig; min själ törster efter dig, såsom en torrjord. Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Herre, bönhör mig snarliga, min ande förgås; göm icke ditt ansigte bort ifrå mig, att jag dem icke lik varder, som i kulona fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Låt mig bittida höra din nåd; ty jag hoppas på dig. Kungör mig den väg, der jag uppå gå skall; ty mig trängtar efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Hjelp mig, Herre, ifrå mina fiendar; till dig hafver jag tillflykt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Lär mig göra efter ditt behag; ty du äst min Gud. Din gode Ande före mig på en jemn väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Herre, vederqvick mig, för ditt Namns skull; för mina själ utu nödene, för dina rättfärdighets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Och förgör mina fiendar, för dina godhets skull, och förgör alla de som mina själ bedröfva; ty jag är din tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'En Psalm Davids. Lofvad vare Herren, min tröst, den mina händer lärer strida, och mina finger örliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Min barmhertighet och min borg, mitt beskärm och min hjelpare, min sköld, på den jag tröster; den mitt folk under mig tvingar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Herre, hvad är menniskan, att du så låter dig vårda om henne; och menniskones son, att du så aktar uppå honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Är dock menniskan lika som intet. Hennes tid går bort såsom en skugge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Herre, böj din himmel, och stig härned; tag uppå bergen, att de ryka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Låt ljunga, och förströ dem; skjut dina skott, och förskräck dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Sänd dina hand af höjdene, och förlossa mig, och fräls mig ifrå stor vatten, ifrå de främmande barnas händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Hvilkas lära är onyttig, och deras gerningar falska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Gud, jag vill sjunga dig en ny viso; jag vill spela dig på psaltare af tio stränger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Du, som gifver Konungomen seger, och förlöser din tjenare David ifrå dens ondas mordsvärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Förlös mig ock, och hjelp mig ifrå de främmande barnas hand; hvilkas lära är onyttig, och deras gerningar falska;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Att våre söner måga uppväxa i deras ungdom, såsom plantor; och våra döttrar, såsom beprydde svalar, såsom palats;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Och våra visthus fulle vara, de der spisning utgifva kunna, den ena efter den andra; att våra får måga bära tusend och hundrade tusend, i våra afvelsgårdar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Att våre oxar måga mycket arbete göra; att ingen skade, ingen olycka eller klagan på våra gator är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Saligt är det folk, hvilko alltså går; men saligt är det folk, hvilkets Gud Herren är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Ett lof Davids. Jag vill upphöja dig, min Gud, du Konung, och ditt Namn lofva alltid och förutan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Jag vill dagliga lofva dig, och ditt Namn prisa alltid och förutan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Herren är stor, och mycket loflig, och hans storhet är osägelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Barnabarn skola prisa dina verk, och tala om ditt välde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Jag vill tala om dina härliga stora äro, och om dina under;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Att man skall tala om dina härliga gerningar, och att man förtäljer dina härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Att man skall prisa dina stora godhet, och lofva dina rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Nådelig och barmhertig är Herren, tålig och af stor godhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Herren är allom god, och förbarmar sig öfver all sin verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'All din verk, Herre, skola tacka dig, och dine helige lofva dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Och prisa dins rikes äro, och tala om ditt välde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Att ditt välde må menniskors barnom kunnogt varda, och dins rikes härliga majestät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Ditt rike är ett evigt rike, och ditt herradöme varar förutan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Herren uppehåller alla de som falla, och uppreser alla de som nederslagne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Allas ögon vänta efter dig, och du gifver dem sin spis i sinom tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Du upplåter dina hand, och uppfyller allt det som lefver med behag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Herren är rättfärdig i alla sina vägar, och helig i alla sina gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Herren är när allom dem som åkalla honom, allom dem som med allvar åkalla honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Han gör hvad de gudfruktige begära, och hörer deras rop, och hjelper dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Herren bevarar alla de honom älska, och skall förgöra alla ogudaktiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Min mun skall säga Herrans lof; allt kött lofve hans helga Namn alltid, och förutan ända!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja. Lofva Herran, min själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Jag vill lofva Herran, så länge jag lefver, och lofsjunga minom Gud, så länge jag här är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Förlåter eder icke uppå Förstar; de äro menniskor, de kunna intet hjelpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Ty menniskones ande måste sin väg, och hon måste åter till jord varda; då äro förtappade alle hennes anslag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Säll är den, hvilkens hjelp Jacobs Gud är; hvilkens hopp på Herran hans Gud står;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Den himmelen, jordena, hafvet och allt det derinne är, gjort hafver; den tro håller evinnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Den rätt skaffar dem som våld lida: den de hungroga spisar. Herren löser de fångna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Herren gör de blinda seende; Herren upprättar de som nederslagne äro; Herren älskar de rättfärdiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Herren bevarar de främlingar och faderlösa, och uppehåller enkorna, och tillbakavänder de ogudaktigas väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Herren är Konung evinnerliga, din Gud, Zion, förutan ända. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Lofver Herran; ty att lofva vår Gud är en kostelig ting; det lofvet är ljufligit och dägeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Herren bygger Jerusalem, och sammanhemtar de fördrefna i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Han helar dem som ett förkrossadt hjerta hafva, och förbinder deras sveda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Han räknar stjernorna, och nämner dem alla vid namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Vår Herre är stor, och stor är hans magt; och det är obegripeligit, huru han regerar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Herren upprättar de elända, och slår de ogudaktiga till jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Sjunger till skiftes Herranom med tacksägelse, och lofver vår Gud med harpo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Den himmelen med skyar betäcker, och gifver regn på jordena; den gräs på bergen växa låter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Den boskapenom sitt foder gifver; dem unga korpomen, som ropa till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Han hafver inga lust till hästars starkhet; icke heller behag till någors mans ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Herren hafver behag till dem som frukta honom; dem som uppå hans godhet hoppas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Prisa, Jerusalem, Herran; lofva, Zion, din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Ty han gör bommarna fasta för dina portar, och välsignar din barn i dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Han skaffar dinom gränsom frid, och mättar dig med bästa hvete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Han sänder sitt tal uppå jordena; hans ord löper snarliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Han gifver snö såsom ull; han strör rimfrost såsom asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Han kastar sitt hagel såsom betar. Ho kan blifva för hans frost?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Han säger, så försmälter det; han låter sitt väder blåsa, så töar det upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Han kungör Jacob sitt ord, Israel sina seder och rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Så gör han ingom Hedningom; ej heller låter dem veta sina rätter. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halleluja. Lofver, I himlar, Herran; lofver honom i höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Lofver honom, alle hans Änglar; lofver honom, all hans här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Lofver honom, sol och måne; lofver honom, alla skinande stjernor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Lofver honom, I himlar, allt omkring, och de vatten, som ofvan himmelen äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'De skola lofva Herrans Namn; ty han bjuder, så varder det skapadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Han håller dem alltid och evinnerliga; han skickar dem, att de icke annorlunda gå måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Lofver Herran på jordene; I hvalfiskar och all djup;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Eld, hagel, snö och dimba, stormväder, de hans ord uträtta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Berg, och alle högar; fruktsam trä, och alle cedrer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Djur och all fänad; krypande djur, och foglar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'I Konungar på jordene, och all folk; Förstar, och alle domare på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Ynglingar och jungfrur; de gamle med de unga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Skolen lofva Herrans Namn; ty hans Namn allena är högt; hans lof går så vidt som himmel och jord är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Och han upphöjer sins folks horn; alle hans helige skola lofva, Israels barn, det folk, som honom tjenar. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halleluja. Sjunger Herranom en ny viso; de heligas församling skall lofva honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Israel glädje sig af den honom gjort hafver; Zions barn vare glade öfver sin Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'De skola lofva hans Namn i dans; med trummor och harpor skola de spela honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Ty Herren hafver ett behag till sitt folk; han hjelper den elända härliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'De helige skola glade vara, och prisa, och lofva i deras säng;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Deras mun skall upphöja Gud; och skola hafva skarp svärd i sina händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Att de skola hämnas ibland Hedningarna, och straffa ibland folken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Till att binda deras Konungar med kedjor, och deras ädlingar med jernfjettrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Att de skola göra dem den rätt, derom skrifvet står: Denna ärona skola alle hans heliga hafva. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halleluja. Lofver Gud i hans helgedom; lofver honom uti hans magts fäste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Lofver honom i hans dråpeliga gerningar; lofver honom i hans stora härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Lofver honom med basuner; lofver honom med psaltare och harpor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Lofver honom med trummor och danser; lofver honom med stränger och pipor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Lofver honom med klara cymbaler; lofver honom med välklingande cymbaler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Allt det anda hafver lofve Herran. Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Detta är Salomos Ordspråk, Davids sons, Israels Konungs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Till att deraf lära vishet och tukt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Förstånd, klokhet, rättfärdighet, dom och fromhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Att de fåkunnige måga varda vise, och de ynglingar förnuftige och försigtige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Den der vis är, han hörer till, och förbättrar sig; och den der förståndig är, han tager vid råd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Att han skall förstå ordspråk, och deras uttydelse; de visas läro, och deras gåtor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Herrans fruktan är begynnelsen till att lära; de galna förakta vishet och tuktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Min son, hör dins faders tuktan, och förlåt icke dine moders bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Ty detta är dino hufvude en skön prydning, och en kedja om din hals.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Min son, om skalkar locka dig, så följ icke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Om de säga: Gack med oss, vi vilje vakta efter blod, och gildra för den oskyldiga utan sak;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Vi vilje dem uppsluka lefvande, såsom helvetet; och de fromma, såsom dem der neder i grafvena fara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Vi vilje finna stora ägodelar; vi vilje fylla vår hus med rof;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Vågat med oss; en pung skall vara allas våras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Min son, vandra intet den vägen med dem; vakta din fot för deras stig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Ty deras fötter löpa till det ondt är, och skynda sig till att utgjuta blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Ty det är fåfängt utkasta nät för foglarnas ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Och vakta de sjelfve efter hvarsannars blod; och den ene står efter den andras lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Alltså göra alle girige, att den ene tager dem andra lifvet bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Visheten klagar ute, och låter höra sig på gatomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Hon ropar i partomen ut för folket; hon talar sin ord i stadenom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Huru länge viljen I, fåkunnige, fåkunnige vara; och de bespottare lust hafva till gabberi, och de galne hata lärdom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Vänder eder till mitt straff; si, jag vill utsäga eder min anda, och göra eder min ord kunnig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Efter jag nu kallar, och I neken det; jag räcker mina hand ut, och ingen aktar dertill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Och I låten fara all min råd, och viljen icke mitt straff;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Så vill jag ock le åt edro ofärd, och begabba eder, när det kommer som I frukten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'När öfver eder kommer, såsom en storm, det I frukten, och edor ofärd såsom ett väder; när öfver eder kommer ångest och nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Då skola de åkalla mig, men jag skall intet svara; de skola bittida söka mig, och intet finna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Derföre, att de hatade lärdom, och ville icke hafva Herrans fruktan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Ville icke mitt råd, och lastade all min straff.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Så skola de äta af sins väsendes frukt, och af sin råd mätte varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Att de fåkunnigas luste dräper dem, och de galnas lycka förgör dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Men den mig hörer, han skall säker blifva, och nog hafva, och för intet ondt frukta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Min son, vill du anamma mitt tal, och min bud när dig behålla,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Så låt din öron gifva akt på vishet, och böj ditt hjerta dertill med flit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Ty om du far derefter med flit, och beder derom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Om du söker efter henne, såsom efter silfver, och letar efter henne, såsom efter en skatt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Så skall du förstå Herrans fruktan, och Guds kunskap finna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Ty Herren gifver vishet, och utaf hans mun kommer vett och förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Han låter dem redeligom väl gå, och beskärmar de fromma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Och bevarar dem som rätt göra, och bevarar sina heligas väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Då skall du förstå rättfärdighet, och dom; och fromhet, och allan godan väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Om vishet faller dig på hjertat, så att du gerna lärer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Så skall godt råd bevara dig, och förstånd skall gömma dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Att du icke råkar in uppå de ondas väg, eller ibland dem som tala det vrångt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Och öfvergifva den rätta vägen, och gå mörka stigar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'De der glädjas att göra illa, och äro glade uti sitt onda och vrångvisa väsende;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Hvilke sin väg förvända, och följa villstigar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Att du icke råkar in till ens annars hustru, och den icke din är, den slät ord gjfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Och öfvergi!ver sins ungdoms herra, och förgäter sins Guds förbund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Ty hennes hus böjer sig till döden och hennes gånger till de förtappade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Alle de som ingå till henne, de komma intet igen, och fatta icke lifsens väg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Att du må vandra på en god väg, och blifva på rätta stråtene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Ty de rättfärdige skola bo i landena, och de fromme skola derinne blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Men de ogudaktige skola utu landena utrotade varda, och de föraktare skola derut förgjorde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Min son, förgät icke min lag, och ditt hjerta behålle min bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Ty de skola skaffa dig långt lif, och god år, och frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Nåd och trohet skola icke förlåta dig. Häng dem på din hals, och skrif dem uti dins hjertas taflo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Så skall du finna ynnest och klokhet, den Gudi och menniskom täck är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Förlåt dig på Herran af allt hjerta, och förlåt dig icke uppå ditt förstånd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Utan tänk uppå honom i allom dinom vägom, så skall han föra dig rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Låt dig icke tycka att du äst vis, utan frukta Herran, och vik ifrå det ondt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Det skall vara dinom nafla helsosamt, och vederqvicka din ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Hedra Herran af dina ägodelar, och af all dins årsväxts förstling;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Så skola dina lador fulla varda, och dine presser med must öfverflyta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Min son, förkasta icke Herrans tuktan, och var icke otålig, då han straffar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Ty hvilken Herren älskar, honom straffar han, och hafver ett behag till honom, såsom en fader till sonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Säll är den menniska, som vishet finner, och den menniska, hvilko förstånd tillflyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Ty det är bättre hafva henne än silfver, och hennes frukt bättre än guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Hon är ädlare än perlor, och allt det du önska må, är henne icke likt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Långt lif är på hennes högra hand, på hennes venstra är rikedom och ära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Hennes vägar äro lustige vägar, och alle hennes stigar äro frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Hon är lifsens trä allom dem som fatta henne; och salige äro de som hålla henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Ty Herren hafver grundat jordena genom vishet, och genom sitt råd tillredt himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Genom hans ord äro djupen åtskild, och skyarna med dagg drypande vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Min son, låt henne icke ifrå din ögon vika, så skall du lyckosam och klok varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Det skall vara dine själs lif, och din mun skall täck vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Då skall du på dinom väg säker vandra, att din fot icke stöter sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Lägger du dig, så skall du intet frukta dig, utan sofva sötliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Att du icke betorf frukta dig för hastig förskräckelse, eller för de ogudaktigas storm, då han kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Ty Herren är din tröst; han bevarar din fot, att han icke fången varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Neka dig icke att göra dem torftiga godt, om din hand af Gudi hafver magt sådant göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Säg icke till din vän: Gack bort, och kom igen, i morgon vill jag gifva dig; der du dock det nu hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Far icke efter att göra dinom vän ondt, den uppå god tro när dig bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Kifva med ingom utan sak, om han dig intet ondt gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Följ icke en vrång man efter, och utvälj ingen af hans vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Ty Herren stygges vid den affälliga, och hans hemlighet är när de fromma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Uti dens ogudaktigas hus är Herrans förbannelse; men dens rättfärdigas hus varder välsignadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Han skall bespotta de bespottare; men dem eländom skall han nåd gifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'De vise skola ärfva äro; men om de galne än högt uppkomma, varda de likväl till skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Hörer, min barn, edars faders tuktan, och akter uppå, att I mågen lära och kloke varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Ty jag gifver eder en god lärdom; öfvergifver icke min lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Ty jag var mins faders son, späd, och den endaste for mine moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Och han lärde mig, och sade: Låt ditt hjerta anamma min ord; håll min bud, så får du lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Anamma vishet, anamma förstånd; förgät icke, och vik icke ifrå mins muns tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Öfvergif henne icke, så skall hon behålla dig; älska henne, så skall hon bevara dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Ty vishetenes begynnelse är, när man gerna hörer henne, och hafver klokhetena kärare, än alla ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Akta henne högt, så skall hon upphöja dig, och skall komma dig till äro, om du hafver henne kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Hon skall ditt hufvud härliga pryda, och hedra dig med en dägelig krono.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Så hör, min son, och tag vid mitt tal, så skola din år mång varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Jag vill föra dig på vishetenes väg; jag vill leda dig på rätta stigen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Så att, när du går, skall din gång icke varda dig tung, och när du löper, skall du icke stöta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Anamma tuktan, öfvergif henne icke; bevara henne, ty hon är ditt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Kom icke uppå de ogudaktigas stig, och träd icke uppå de ondas väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Låt fara honom, och gack icke på honom; vik ifrå honom, och gack framom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Ty de sofva icke, utan de hafva gjort illa, och gifva sig icke ro, utan de hafva gjort skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Ty de föda sig af ogudaktigt bröd; och dricka af vrånghetenes vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Men de rättfärdigas stig skin såsom ett ljus, hvilket framgår, och lyser allt intill fullan dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Men de ogudaktigas väg är såsom mörker, och de veta icke, hvar de fallande varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Min son, akta uppå min ord, och böj din öron till mitt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Låt dem icke komma ifrå din ögon; behåll dem i ditt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Ty de äro lif dem som finna dem, och helsosam deras hela kroppe.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Bevara ditt hjerta med all flit; ty derutaf går lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Låt bort ifrå dig en ond mun, och vrånga läppar låt långt vara ifrå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Låt din ögon se rätt fram för sig, och din ögnalock se rätt fram för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Låt din fot gå lika, så går du visst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Vik hvarken på högra eller på venstra sidona; vänd din fot ifrå det ondt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Min son, gif akt uppå mina vishet, böj din öron till mina läro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Att du må behålla god råd, och din mun veta beskedlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Ty ene skökos läppar äro en hannogskaka, och hennes hals är halare än olja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Men framdeles bäsk som malört, och skarp såsom ett tveeggadt svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Hennes fötter löpa neder till döden; hennes råd gånger få helvetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Hon går icke rätt fram på lifsens väg; ostadig äro hennes steg, så att hon icke vet hvart hon går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Så hörer mig nu, min barn, och viker icke ifrå mins muns tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Låt dina vägar vara fjerran ifrå henne, och nalkas intet intill hennes husdörr;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Att du icke skall gifva dina äro dem främmandom, och din år dem grymma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Att främmande icke skola mätta sig af dine förmågo, och ditt arbete icke vara uti ens annars hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Och du måtte framdeles sucka, när du ditt lif och gods förtärt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Och säga: Ack! huru hafver jag hatat tuktan, och mitt hjerta straff försmått;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Och hafver icke lydt mina lärares röst, och icke böjt min öron till dem som mig lärde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Jag är fulltnär i all olycko kommen, att jag den meniga hopen och sällskapet följt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Drick vatten utaf dina gropar, och hvad af dinom brunn utflyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Låt dina källor utflyta, och vattubäckerna uppå gatorna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Men haf du dem allena, och ingen främmande med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Din brunn vare välsignad, och gläd dig af dins ungdoms hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Hon är ljuflig såsom en hind, och täck såsom en rå; låt hennes kärlek alltid mätta dig, och förlusta dig alltid uti hennes kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Min son, hvi vill du förlusta dig med en främmande, och famntager ens annars?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Ty hvars och ens mans vägar äro för Herranom, och han mäter alla deras gångar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Dens ogudaktigas misshandel skall gripa honom, och med sina synders snaro skall han hållen varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Han skall dö, derföre att han icke vill låta lära sig, och för sin stora dårskaps skull vill fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Min son, varder du lofvetsman för din nästa, så hafver du häktat dina hand intill en främmanda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Du äst invefvad med dins muns tal, och gripen uti dins muns ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Så gör dock, min son, alltså, och undsätt dig; ty du äst kommen dinom nästa i händer; löp, skynda dig, och drif din nästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Låt icke din ögon sofva, eller din ögnahvarf sömnig vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Uthjelp dig, såsom en rå utu handene, och såsom en fogel utu foglafängarens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Gack bort till myrona, du later; se uppå hennes seder, och lär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Ändock hon ingen Första eller höfvitsman, eller herra hafver,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Tillreder hon dock likväl sitt bröd om sommaren, och samkar sin mat i andene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Huru länge ligger du, later? När vill du uppstå af dinom sömn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Ja, sof ännu litet, tag der ännu en sömn före; lägg ännu litet händerna tillhopa, att du må sofva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Så skall fattigdomen med hast komma öfver dig, såsom en vandrare, och armod såsom en väpnad man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'En bedrägelig menniska, en skadelig man går med vrångom mun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Vinkar med ögonen, tecknar med foten, viser med fingren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Tänker alltid något ondt och argt i sitt hjerta, och kommer trätor åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Derföre skall honom hans ofärd hasteliga komma; och skall med snarhet sönderbråkad varda, så att der ingen hjelp vara skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Si, sex stycke hatar Herren, och vid det sjunde hafver han en styggelse:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Högfärdig ögon, falsk tungo, händer som utgjuta oskyldigt blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Hjerta som med arga list umgår, fötter som snare äro till att göra skada;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Ett falskt vittne som icke skämmes att tala lögn, och den der träto emellan bröder åstadkommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Min son, bevara dins faders bud, och låt icke fara dine moders lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Bind dem tillhopa på ditt hjerta dageliga, och häng dem på din hals;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'När du går, att de leda dig; när du ligger, att de bevara dig; när du uppvaknar, att de äro ditt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Ty budet är en lykta, och lagen är ett ljus; och tuktans straff är lifsens väg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'På det du må bevarad blifva för en ond qvinno; för enes främmandes släta tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Låt hennes dägelighet icke göra dig lusta i ditt hjerta, och förtag dig icke på hennes ögnahvarf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Ty en sköka tager enom sitt bröd ifrå; men en gift qvinna fångar ädla lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Kan ock någor behålla eld i barmen, så att hans kläder icke brinna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Huru skulle någor gå på glöd, så att hans fötter icke brände varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Alltså går det honom, som till sins nästas hustru går; der blifver ingen ostraffad, den vid henne kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Det är enom tjuf icke så stor skam, om han stjäl till att mätta sina själ, då honom hungrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Och om han gripen varder, gifver han det sjufaldt igen, och lägger dertill alla ägodelarna i sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Men den som med ene qvinno hor bedrifver, han är en dåre, och förer sitt lif uti förderf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Dertill skall plåga och skam komma uppå honom, och hans skam skall intet utskrapad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Ty mansens harm hafver nit, och skonar intet på hämndenes tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Och ser icke till någon person, den försona måtte; och tager intet vid, om du än mycket skänka ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Min son, behåll min ord, och göm min bud när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Behåll min bud, så får du lefva, och min lag såsom din ögnasten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Bind dem på din finger, skrif dem pådins hjertas taflo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Säg till vishetena: Du äst min syster, och kalla klokhetena dina fränko;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Att du bevarad varder för en främmande qvinno, för ens annars, som slät ord gifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Ty i fenstret på mitt hus såg jag ut genom gallret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Och såg ibland de fåkunniga, och vardt varse ibland barn en galen yngling.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Den gick på gatone utmed ett hörn, och trädde in uppå vägen åt hennes hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'I skymningene, om aftonen af dagenom, då det natt vardt, och mörkt var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Och si, der mötte honom en qvinna, i skökoklädnad, listig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Vildsinnad och ostyrig, så att hennes fötter icke kunde blifva i sitt hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Nu är hon ute, nu på gatone, och vaktar vid all hörn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Hon tog honom fatt, och kysste honom utan skam, och sade till honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Jag hafver i dag betalat tackoffer för mig, och mitt löfte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Derföre är jag utgången till att möta dig, till att söka ditt ansigte bittida, och hafver funnit dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Jag hafver skönliga tillpyntat min säng, med brokot täcken utur Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Jag hafver bestänkt min sängekammar med myrrham, aloes och kanel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Kom, låt oss bola allt intill morgonen, och låt oss älskog sköta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Ty mannen är icke hemma; han är bortfaren långväga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Han hafver tagit penningasäcken med sig; han skall först hemkomma till högtidsdagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Hon talade för honom med mång ord, och fick honom in med sin släta mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Han går straxt in med henne, såsom en oxe till att slagtas ledd varder, och såsom till en fjetter, der man de dårar med näpser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Tilldess hon med enom pil skjuter honom igenom lefrena, och såsom en fogel skyndar sig till snarona, och vet icke att det gäller honom om lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Så hörer mig nu, min barn, och märker uppå mins muns tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Låt ditt hjerta icke vika in uppå hennes väg, och låt icke förföra dig in uppå hennes stigar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Ty hon hafver många sargat och fällt, och allehanda mägtige äro dräpne af henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Hennes hus äro helvetes vägar, der man nederfar uti dödsens kammar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Ropar icke visheten, och klokheten låter sig höra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Uppenbara på vägen, och på stråtene står hon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Vid stadsportarna, der man ingår, ropar hon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'O! I män, jag ropar till eder; och ropar till folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Akter, I oförnuftige, uppå vishet, och I dårar, lägger det på hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Hörer, ty jag vill tala det märkeligit är, och lära det rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Ty min mun skall tala sanningen, och mina läppar skola hata det ogudaktigt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'All mins muns tal är rätt; der är intet vrångt eller falskt inne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'De äro all klar dem som förstå dem, och rätt dem som vilja anamma dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Tager vid min tuktan heldre än silfver, och akter lärdom högre än kosteligit guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Ty vishet är bättre än perlor, och allt det man önska må, kan intet liknas henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Jag, vishet, bor när klokhetene, och jag kan gifva god råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Herrans fruktan hatar det arga, högfärd, högmod och ondan väg; och jag kan icke lida en vrångan mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Mitt är både råd och dåd; jag hafver förstånd och magt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Genom mig regera Konungarna, och rådherrarna stadga rätthet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Genom mig råda Förstarna, regenter och alle domare på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Jag älskar dem som mig älska; och de som mig bittida söka, de finna mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Rikedom och ära är när mig, varaktigt gods och rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Min frukt är bättre än guld och fint guld, och min tilldrägt bättre än utkoradt silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Jag vandrar på rätta vägen, på domsens stigar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Att jag skall väl besörja dem som mig älska, och uppfylla deras håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Herren hafver haft mig i sina vägars begynnelse; förr hans gerningar var jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Jag är insatt af evighet, af begynnelsen, förr jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Då djupen ännu intet voro, då var jag allaredo beredd; då källorna icke ännu runno med vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Förr än bergen grundad voro, förr än högarna, var jag beredd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Han hade icke ännu gjort jordena, och hvad derpå är, eller jordenes berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Då han beredde himmelen, var jag der; då han fattade djupen med sitt mål;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Då han befäste skyarna ofvantill; då han befäste djupsens källor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Då han satte hafvena sitt mål, och vattnena, att de icke skulle gå öfver sina befallning; då han lade jordenes grund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Då var jag verkandes med honom, och hade mina lust dagliga, och spelade för honom alltid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Och spelade på hans jords krets, och min lust var med menniskors barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Så hörer mig nu, min barn; salige äro de som min väg behålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Hörer tuktan, och varer vise, och låter icke fara henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Säll är den menniska, som mig hörer, så att han vakar vid mina dörr dagliga, att han vaktar vid min dörrträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Den mig finner, han finner lifvet, och skall få behag af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Men den som syndar emot mig, han skadar sina själ; alle de mig hata, de älska döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Visheten byggde sitt hus, och högg sju pelare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Och slagtade sin boskap, skänkte sitt vin, och tillredde sitt bord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Och sände sina tjenarinnor ut, till att bjuda upp på stadsens palats:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Den fåkunnig är, han komme hit; och till de dårar sade hon:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Kommer, äter af mitt bröd, och dricker af vinet, som jag skänker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Öfvergifver det galna väsendet, så fån I lefva; och går på förståndsens väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Hvilken som tuktar bespottaren, han får skam igen; och den som straffar en ogudaktigan, han varder försmädad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Straffa bespottaren intet, att han icke hatar dig; straffa den visa, han skall älska dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Gif dem visa, så skall han ännu visare varda; lär den rättfärdiga, så växer han till i lärdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Vishetenes begynnelse är Herrans fruktan, och förstånd lärer hvad heligt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Ty igenom mig skola dine dagar månge varda, och dins lifs år dig flere varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Äst du vis, så äst du dig vis; äst du en bespottare, så måste du umgälla det allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Men en galen ostadig qvinna, full med sqvaller, och fåvitsk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Sitter i sins hus dörr, på en stol, högt uppe i stadenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Till att bjuda alla de der framom gå, och rättelliga vandra på sinom vägom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Den der fåkunnig är, han komme hit. Och till de dårar säger hon:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Stulet vatten är sött, och fördoldt bröd är lustigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Men han vet icke, att der äro de döde, och hennes gäster uti djupa helvetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'En vis son är sins faders glädje; men en galen son är sine moders grämelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Orätt gods hjelper intet; men rättfärdighet friar ifrå döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Herren låter icke de rättfärdigas själar hunger lida; men han omstörter de ogudaktigas arghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'En lat hand gör fattigan; men en idog hand gör rikan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Den som församlar om sommaren, han är klok; men den som i andene sofver, han kommer på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Välsignelse är öfver dens rättfärdigas hufvud; men de ogudaktigas mun skall deras vrånghet öfverfalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'De rättfärdigas åminnelse blifver uti välsignelse; men de ogudaktigas namn skall förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Den af hjertat vis är, han anammar buden; men den en galen mun hafver, han varder slagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Den der ostraffeliga lefver, han lefver säkert; men den der vrång är på sina vägar, han skall uppenbar varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Den der vinkar med ögonen, han kommer vedermödo åstad; och den en galen mun hafver, han varder slagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Dens rättfärdigas mun är en lefvandes källa; men de ogudaktigas mun skall deras vrånghet öfverfalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Hat uppväcker träto; men kärlek öfverskyler all öfverträdelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Uti de förståndigas läppar finner man vishet; men till ens dåras rygg hörer ris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'De vise bevara lärdom; men de dårars mun är hardt när förskräckelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Dens rikas gods är hans faste stad; men fattigdom gör de fattiga blödiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Den rättfärdige arbetar till lifvet; men den ogudaktige brukar sina tilldrägt till synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Hålla tuktan är vägen till lifvet; men den som bortkastar straff, han far vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Falske munnar skyla hat, och den der baktalar, han är en dåre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Der mång ord äro, der är icke synden borto; men den sina läppar håller, han är klok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Dens rättfärdigas tunga är kosteligt silfver; men de ogudaktigas hjerta är intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Dens rättfärdigas läppar föda många; men de galne skola dö uti deras galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Herrans välsignelse gör rikan utan mödo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'En dåre bedrifver det ondt är, och gör sig der ett löje af; men den man är vis, som tager der vara uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Hvad den ogudaktige fruktar, det vederfars honom; och hvad de rättfärdige begära, det varder dem gifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Den ogudaktige är såsom ett väder, det framom går, och är icke mer till; men den rättfärdige består evigliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Såsom ättika gör ondt tandomen, och rök ögonen, så gör en försummelig dem ondt, som sända honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Herrans fruktan förmerar dagarna; men de ogudaktigas år varda förkortad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Dens rättfardigas väntan skall fröjd varda; men de ogudaktigas hopp skall förtappadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Herrans väg är dens frommas tröst; men de ogerningsmän äro blödige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Den rättfärdige varder aldrig nederslagen; men de ogudaktige skola icke blifva i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Dens rättfärdigas mun bär fram vishet; men de vrångas mun skall utrotad blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Dens rättfärdigas läppar lära helsosam ting; men de ogudaktigas mun är vrång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Falsk våg är Herranom en styggelse; men en full vigt är honom behagelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Der stolthet är, der är ock föraktelse; men vishet är när de ödmjuka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Oskyldighet skall ledade fromma; men ondskan skall förstöra de föraktare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Gods hjelper intet på vredenes dag; men rättfärdighet frälsar ifrå döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Dens frommas rättfärdighet gör hans väg rättan; men den ogudaktige skall falla genom sitt ogudaktiga väsende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'De frommas rättfärdighet skall fria dem; men de föraktare varda fångne uti sine skalkhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'När den ogudaktiga menniskan dör, så är hoppet borto; och det de orättfärdige vänta, blifver omintet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Den rättfärdige varder förlossad utu nöd, och den ogudaktige kommer i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Genom skrymtarens mun varder hans näste förderfvad; men de rättfärdige märka det, och varda förlossade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'En stad gläder sig, när dem rättfärdigom väl går, och der de ogudaktige förgöras varder man glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Genom de frommas välsignelse varder en stad upphöjd; men genom dens ogudaktigas mun varder han nederbruten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Den som sin nästa skämmer, han är en dåre; men en förståndig man stillar det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'En baktalare röjer hvad han hemliga vet; men den som ett trofast hjerta hafver, han döljer det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Der intet råd är, der far folket illa; men der månge rådgifvare äro, der går det väl till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Den som för en annan i borgan går, han får skada; men den sig för borgan vaktar, han är säker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Den qvinna hafver ynnest, som ärona bevarar; men det äro de starke, som rikedomar bevara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'En barmhertig man gör sinom kropp godt; men en obarmhertig bedröfvar ock sitt kött och blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'De ogudaktigas verk skall fela; men den som rättfärdighet sår, det är icke fåfängt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Ty rättfärdighet fordrar till lifs; men fara efter ondt, det fordrar till döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Herren hafver en styggelse till vrång hjerta, och ett behag till de fromma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Dem ondom hjelper intet, om de än alle lade händer tillsamman; men de rättfärdigas säd skall hulpen varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'En dägelig qvinna utan tukt är lika som en so med ett gyldene spann på näsone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'De rätträrdigas önskan måste dock väl gå, och det de ogudaktige vänta, är olycka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Den ene skiftar ut, och får alltid mer; men den andre är nidsk, der han icke skall, och varder dock fattigare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Den själ, som rikeliga välsignar, varder fet; och den som drucknan gör, han skall ock drucken varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Den som korn innehåller, honom banna menniskorna; men välsignelse kommer öfver honom, som det säljer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Den som något godt söker, honom vederfars godt; men den som efter ondt far, det skall hända honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Den sig uppå sina rikedomar förlåter, han skall förgås; men de rättfärdige skola grönskas såsom löf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Den som sitt eget hus bedröfvar, han skall få väder till arfvedel; och en dåre måste dens visas tjenare vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Dens rättfärdigas frukt är lifsens trä, och en vis man låter sig om menniskorna hjerteliga vårda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Efter den rättfärdige på jordene lida måste; huru mycket mer den ogudaktige och syndaren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Den sig gerna straffa låter, han varder klok; men den der ostraffad vara vill, han blifver en dåre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Den der from är, honom vederfars tröst af Herranom; men en ond man varder förkastad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ett ogudaktigt väsende främjar menniskona intet; men dens rättfärdigas rot skall blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'En idog qvinna är sins mans krona; men en oidog är såsom var i hans ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'De rättfärdigas tankar äro redelige; men de ogudaktigas anslag äro bedrägeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'De ogudaktigas anslag vakta efter blod; men de frommas mun friar dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'De ogudaktige skola varda omstörte, och icke mer vara till; men dens rättfärdigas hus blifver beståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Ett godt råd varder (dock på ändalyktene) lofvadt; men arg list kommer på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Den som ringa är, och tager vara uppå sitt, han är bättre än den der stor vill vara, och honom fattas bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Den rättfärdige förbarmar sig öfver sin ök; men de ogudaktigas hjerta är obarmhertigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Den som sin åker brukar, han skall få bröd tillfyllest; men den som går efter de ting, som intet af nödene äro, han är en dåre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Dens ogudaktigas lust är till att göra skada; men dens rättfärdigas rot skall bära frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Den onde varder gripen i sin egen falska ord; men den rättfärdige undkommer ångest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Mycket godt kommer enom genom munsens frukt; och menniskone varder vedergullet efter som hennes händer förtjent hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Enom dåra behagar hans sed väl; men den der råde lyder, han är vis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'En dåre beviser sina vrede snarliga; men den der smälek fördöljer, han är vis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Den som sannfärdig är, han säger hvad rätt är; men ett falskt vittne bedrager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Den der ovarliga talar, han stinger såsom ett svärd; men de visas tunga är helsosam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'En sannfärdig mun består evigliga; men en falsk tunga består icke länge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'De som något ondt råda, bedraga sig sjelfva; men de som tillfrid råda, de skola glädja sig deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Dem rättfärdiga varder intet ondt vederfarandes; men de ogudaktige skola med olycko fulla varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Falske munnar äro Herranom en styggelse; men de som troliga handla, de behaga honom väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'En vis man gör icke mycket af sin klokhet; men de dårars hjerta utropar sin dårskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'En trifven hand skall varda väldig; men den som som lat är, hon måste skatt gifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Sorg i hjertana kränker; men ett vänligit ord fröjdar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Den rättfärdige hafver bättre än hans näste; men de ogudaktigas väg förförer dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Enom latom lyckas icke hans handel; men en trifven menniska varder rik.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'På rättom väg är lif, och på farnom stig är ingen död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'En vis son låter fadren tukta sig; men en bespottare lyder icke straff.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Munsens frukt nyttjar man; men de föraktare tänka icke annat än vrånghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Den sin mun bevarar, han bevarar sitt lif; men den som sin mun orådeliga upplåter, han kommer i förskräckelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Den late begärar, och får dock intet; men de trefne få nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Den rättfärdige är lögnenes fiende; men den ogudaktiga skämmer, och försmäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Rättfärdighet bevarar den oskyldiga; men det ogudaktiga väsendet förer en till synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Mången är fattig i stor rikedom, och mången är rik i sinom fattigdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Med rikedom kan en hjelpa sitt lif; men en fattig man hörer icke straff.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'De rättfärdigas ljus gör gladsamma; men de ogudaktigas lykta skall utslockna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Ibland de högmodiga är alltid träta; men vishet gör förnuftigt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Rikedom varder liten, när man förslöser honom; men det man tillsammanhåller, det varder stort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Det hopp, som fördröjes, gör ängslo i hjertat; men när det kommer, som man begärar, det är ett lifsträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Den som föraktar ordet, han förderfvar sig sjelf; men den som fruktar budet, han skall få frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Dens visas lära är en lefvandes källa, till att undvika dödsens snaro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Ett godt råd bekommer väl; men de föraktares väg gör ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'En kloker gör all ting med förnuft men en dåre utsprider dårskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Ett ogudaktigt bådskap bär ondt fram; men ett troget båd är helsosamt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Den som tuktan låter fara, han hafver fattigdom och skam; den sig gerna straffa låter, han skall till äro komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'När det kommer, som man begärar, det gör hjertana godt; men den som flyr det onda, han är dem galnom en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Den som med visom omgår, han varder vis; men den som de dårars stallbroder är, han får olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Det onda följer syndarena efter; men dem rättfärdigom varder godt vedergullet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Den gode skall hafva arfvingar intill barnabarn, men syndarens gods skall varda spardt till den rättfärdiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Mycken spis är uti de fattigas åker; men somliga församla med orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Den sitt ris spar, han hatar sitt barn; men den som det kärt hafver, han näpser det i tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Den rättfärdige äter, att hans själ må mätt varda; men de ogudaktigas buk hafver aldrig nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Genom visa qvinnor varder huset bygdt; men en galen bryter det neder med sina åthäfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Den som Herran fruktar, han går på rätta vägen; men den honom föraktar, han viker af hans väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Dårar tala tyranniskt; men de vise bevara sin mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Der icke oxar äro, der är krubban ren; men der oxen hafver nog skaffa, der är nog inkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Ett troget vittne ljuger icke; men ett falskt vittne talar dristeliga lögn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Bespottaren söker vishet, och finner henne intet; men dem förståndiga är vishet lätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Kommer du till en dåra, der finner du icke ett förnumstigt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Det är dens klokas vishet, att han aktar uppå sin väg; men det är ens dåras galenskap, att det är alltsammans bedrägeri med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'De dårar drifva deras gabberi med syndene; men de fromme hafva lust till de fromma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'När hjertat sörjandes är, så hjelper ingen utvärtes glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'De ogudaktigas hus varder förgjordt; men de frommas hydda skall grönskas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Mångom behagar en väg väl; men på ändalyktene leder han honom till döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Efter löje kommer sorg, och änden på glädjene är ångest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Ene lösaktiga mennisko varder gåendes såsom han handlar; men en from man skall vara öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'En fåkunnig man tror hvart ord; men en förståndig man aktar på sin gång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'En vis man hafver fruktan, och flyr det arga; men en dåre söker fram dristeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'En otålig menniska gör galen ting; men en försigtig man hatar det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'De flåkote handla ovarliga; men det är de förståndigas krona, att de varliga handla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'De onde måste buga för de goda, och de ogudaktige uti dens rättfärdigas portom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'En fattigan hatar ock hans näste; men de rike hafva många vänner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Syndaren föraktar sin nästa; men säll är den som förbarmar sig öfver den elända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'De som med illfundighet umgå, dem skall det fela; men der som godt tänka, dem skall trohet och godhet vederfaras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Der man arbetar, der är nog; men der man umgår med ordom, der är fattigdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Dem visom är deras rikedom en krona; men de dårars galenskap blifver galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Ett troget vittne friar lifvet; men ett falskt vittne bedrager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Den som Herran fruktar, han hafver ett tryggt fäste, och hans barn varda också beskärmad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Herrans fruktan är lifsens källa, att man må undfly dödsens snaro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Der en Konung mycket folk hafver, det är hans härlighet; men der litet folk är, det gör en herra blödig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Den som tålig är, han är vis; men den som otålig är, han uppenbarar sin galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Ett blidt hjerta är kroppsens lif; men afund är var i benen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Den som försmäder den fattiga, han lastar hans skapare; men den som förbarmar sig öfver den fattiga, han ärar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Den ogudaktige består icke uti sine olycko; men den rättfärdige är ock i dödenom frimodig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Uti dens förståndigas hjerta hvilar visheten, och varder uppenbar ibland dårar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Rättfärdighet upphöjer ett folk; men synd är folkets förderf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'En klok tjenare behagar Konungenom väl; men en skamlig tjenare lider han icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Ett mjukt svar stillar vrede; men ett hårdt ord kommer harm åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'De visas tunga gör lärdomen ljuflig; de dårars mun utsputar alltid galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Herrans ögon skåda i all rum, både onda och goda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'En helsosam tunga är lifsens trä; men en lögnaktig gör hjertans sorg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'En dåre lastar sins faders tuktan; men den som tager vid straff, han varder klok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Uti dens rättfärdigas hus äro ägodelar nog; men uti dens ogudaktigas tilldrägt är förderf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'De visas mun utströr god råd; men de dårars hjerta är icke så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Dens ogudaktigas offer är Herranom en styggelse; men de frommas bön är honom behagelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Dens ogudaktigas väg är Herranom en styggelse; men den der far efter rättfärdighet, han varder älskad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Det är en ond tuktan, öfvergifva vägen; och den der straff hatar, han måste dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Helvete och förderf är för Herranom; huru mycket mer menniskornas hjerta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'En bespottare älskar icke den honom straffar, och går icke till den visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Ett gladt hjerta gör ett blidt ansigte; men när hjertat bekymradt är, så faller ock modet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Ett klokt hjerta handlar visliga; men de öfverdådige dårar regera dårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'En bedröfvad menniska hafver aldrig en god dag; men ett godt mod är ett dageligit gästabåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Bättre är något lite med Herrans fruktan, än en stor skatt med oro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Bättre är en rätt kål med kärlek, än en gödd oxe med hat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'En sticken man kommer träto åstad; men en tålig man stillar kif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Dens latas väg är full med törne; men de frommas väg är väl slät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'En vis son fröjdar fadren, och en galen menniska skämmer sina moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Enom dåra är galenskapen en glädje; men en förståndig man blifver på rätta vägenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'De anslag varda till intet, der icke råd är med; men der månge rådgifvare äro, blifva de beståndande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Det är enom glädje, att man honom skäliga svarar, och ett ord i sinom tid är ganska täckeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Lifsens väg leder den visa uppåt, på det han skall undvika helvetet, som nedatill är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Herren skall nederslå de högfärdigas hus, och stadfästa enkones gränso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'De argas anslog äro Herranom en styggelse; men ett skäligit tal är täckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Men girige förstörer sitt eget hus; men den som mutor hatar, han skall lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Dens rättfärdigas hjerta betänker, hvad svaras skall; men de ogudaktigas mun utöser ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Herren är långt ifrå de ogudaktiga; men de rättfärdigas bön hörer han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Ett blidt ansigte gläder hjertat; ett godt ryckte gör benen fet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Det öra, som hörer lifsens straff, det skall bo ibland de visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Den som icke låter sig aga, han gör sig sjelf till intet; men den som straff hörer han varder klok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Herrans fruktan är en tuktan till vishet, och förr än man till äro kommer, måste man lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'En menniska sätter sig väl före i hjertat; men af Herranom kommer, hvad tungan tala skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Hvarjom och enom tyckas hans vägar rene vara; men Herren allena gör hjertat visst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Befalla Herranom din verk, så gå din anslag fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Herren gör all ting för sin egen skull; desslikes ock den ogudaktiga till en ondan dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'All högmodig hjerta äro Herranom en styggelse, och skola icke ostraffad blifva, om de än alle tillhopa höllo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Genom godhet och trohet varder en missgerning försonad, och genom Herrans fruktan undflyr man det onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Om någors mans vägar behaga Herranom, så gör han ock hans ovänner tillfrids med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Bättre är litet med rättfärdighet, än mycken tilldrägt med orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Menniskones hjerta sätter sig sina vägar före; men Herren allena gifver, att de framgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Prophetia (är) i Konungens mun; hans mun felar intet i domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Rätt våg och vigt är af Herranom; och all pund i säckenom äro hans verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Om Konungarna orätt göra, så äro de en styggelse; ty genom rättfärdighet varder Konungssätet fast.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Rätt råd behagar Konungenom, och den som rätt råder, han varder älskad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Konungens vrede är dödsens bådskap, och en vis man försonar honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'När Konungens ansigte är ljufligit, det är lifvet, och hans ynnest är såsom ett aftonregn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Tag vishet till dig, ty hon är bättre än guld; och hafva förstånd är ädlare än silfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'De frommas väg flyr det arga, och den sin väg bevarar, han behåller sitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Den som ett nederfall skall få, han varder tillförene högmodig, och stort sinne går för fallet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Bättre är ödmjuk vara med de elända, än utskifta rof med de högfärdiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Den ena sak visliga företager, han finner lycko, och säll är den som sig förlåter på Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'En förståndig varder berömd for en vis man, och ljuft tal lärer väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Klokhet är en lefvandes källa honom, som hafver henne; men de dårars tuktan är galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Ett vist hjerta talar klokliga, och lärer väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Ljuftig ord äro en hannogskaka; de trösta själena, och uppfriska benen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Mångom behagar en väg väl, men hans yttersta drager till döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Mången man kommer i stor olycko genom sin egen mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'En lösaktig menniska gräfver efter olycko, och i hennes mun brinner eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'En vrång menniska kommer träto åstad, och en lackare gör Förstar oens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'En arg menniska lockar sin nästa, och förer honom in på en ondan väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Den som blinkar med ögonen, han tänker intet godt; och den som biter läpparna, han fullkomnar ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Gå hår äro en hederskrona, den på rättfärdighetenes väg funnen varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'En tålig man är bättre än en stark; och den, som råder sitt sinne, är bättre än en som städer vinner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Lotten varder kastad i skötet; men han faller hvart Herren vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'En torr bete, der man låter sig med nöja, är bättre än ett fullt visthus med träto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'En klok tjenare skall råda öfver snöplig barn, och skall utskifta arfvet emellan bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Såsom elden pröfvar silfret, och ugnen guld, alltså pröfvar Herren hjertan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'En ond menniska aktar uppå onda munnar, och en falsk menniska hörer gerna en skadelig tungo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Den som den fattiga bespottar, han försmäder hans skapare; och den som gläder sig af annars ofärd, han skall icke ostraffad blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'De gamlas krona äro barnabarn, och barnas ära äro deras fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Det står icke en dåra väl att tala om hög ting, mycket mindre en Första, att han gerna ljuger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Gåfva är en ädelsten; hvart man henne bär, så främjar hon väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Den som synd skyler, han förskaffar vänskap; men den som sakena röjer, han gör Förstar oens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Ord förskräcka mer en förståndigan, än hundrade hugg en dåra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Ett bittert hjerta söker efter att göra skada; men en grufvelig ängel skall komma öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Bättre är möta en björn, den ungarna borttagne äro, än enom dåra i hans galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Den som vedergäller godt med ondo, af hans hus skall det onda icke återvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Begynnelse till träto är såsom ett vatten, det sig utskär; haf alltså du kif fördrag, förr än du der inmängd varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Den som den ogudaktiga dömer godan, och den som fördömer den rättfärdiga, de äro både Herranom en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Hvad skall en dåre med penningar i handene, efter han icke hafver hjerta till att köpa vishet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'En vän älskar alltid, och en broder varder rönt i nödene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Det är en dåre, som handena räcker, och går i borgan för sin nästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Den som kif älskar, han älskar synd; och den sina dörr höga gör, han far efter olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Ett vrångt hjerta finner intet godt; och den som en ond tungo hafver, han faller i olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'En dåre gör sig sjelf sorg, och en dåras fader hafver ingen glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Ett gladt hjerta gör lifvet lustigt; men ett bedröfvadt sinne uttorkar benen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Den ogudaktige tager gerna hemliga gåfvor, till att böja rättsens väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'En förståndig man bär sig visliga åt; en dåre kastar ögonen hit och dit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'En galen son är sins faders grämelse, och sine modets bedröfvelse, den honom födt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Det är icke godt att man oförrättar den rättfärdiga, eller att man slår Förstan, som rätt regerar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'En förnumstig man hafver hof med sitt tal, och en förståndig man håller sin anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Om en dåre tigde, vorde han ock vis räknad, och förståndig, om han munnen tillhölle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Den som lust hafver till att komma tvedrägt åstad, han söker efter träto, ehvar han kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'En dåre hafver icke lust till förstånd, utan till hvad han hafver i hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Der den ogudaktige råder, der kommer föraktelse och försmädelse med hån.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Orden uti ens mun äro såsom djup vatten, och vishetenes källa är en full ström.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Det är icke godt att se till dens ogudaktigas person, till att nedertrycka den rättfärdiga i domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Ens dåras läppar komma med kif, och hans mun far efter hugg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Ens dåras mun skämmer sig sjelf, och hans läppar fånga hans egen själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Ens lackares ord äro hugg, och de gå en genom hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Den som lat är i sitt arbete, han är hans broder som skada gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Herrans Namn är ett fast slott; den rättfärdige löper dit, och varder beskärmad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Dens rikas gods är honom en fast stad, och såsom en hög mur allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Då en skall ett nederfall få, så varder hans hjerta tillförene stolt; och förr än man till äro kommer, måste man lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Den som svarar förr än han hörer, honom är det en galenskap och skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Den som ett gladt hjerta hafver, han vet hålla sig uti sitt lidande; men när anden är bedröfvad, hvad kan en lida?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Ett förståndigt hjerta vet hålla sig förnufteliga; och de vise höra gerna, att man förnufteliga handlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Menniskones skänker göra honom rum, och hafva honom fram för de stora herrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Hvar och en är i förstone i sine sak rätt; men kommer hans nästa dertill, så finner det sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Lotten stillar träto, och skiljer emellan de mägtiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'En broder, som fast står, han är såsom en fast stad; och de, som för hvarann strida, såsom en bom för ett slott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Enom man varder lönt efter som hans mun talat hafver, och han varder mättad af sina läppars frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Döden och lifvet står i tunganes våld; den henne älskar, han får äta af hennes frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Den som ena ägta hustru finner, han finner godt, och får välsignelse af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'En fattig man talar med ödmjukhet; en rik man svarar stolteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'En trofast vän älskar mer, och står fastare, än en broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'En fattig man, den i sine fromhet vandrar, är bättre än en vrång man med sina läppar, den dock en dåre är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Der man icke med förnuft handlar, der går det intet väl till; och den som snar är på fötterna, han stöter sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Ens menniskos galenskap förförer hans väg, att hans hjerta emot Herran vredgas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Gods gör många vänner; men den fattige varder af sinom vännom förlåten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Ett falskt vittne blifver icke ostraffadt; och den der lögn dristeliga talar, han skall icke undslippa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Månge vakta uppå Förstans person; och alle äro dens vänner, som skänker gifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Den fattiga hata alle hans bröder, ja, ock hans vänner draga sig långt ifrå honom; och den som sig uppå ord förlåter, han får intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Den der klok är, han älskar sitt lif; och den förståndige finner godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Ett falskt vittne blifver icke ostraffadt; och den der lögn dristeliga talar, han skall förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Dem galna höfves icke väl goda dagar, mycket mindre enom tjenare att råda öfver Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Den der tålig är, han är en klok menniska; och det är honom ärligit, att han odygd öfverse kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Konungens ogunst är såsom ens ungs lejons rytande; men hans gunst är såsom dagg på gräs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'En galen son är sins faders sorg, och en trätosam qvinna ett stadigt drypande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Hus och ägodelar ärfvas af föräldrom; men en förnuftig hustru kommer af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Lathet hafver sömn med sig, och en fåfäng själ skall hunger lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Den som budet bevarar, han bevarar sitt lif; men den sin väg föraktar, han skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Den som förbarmar sig öfver den fattiga, han lånar Herranom; han skall vedergälla honom godt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Tukta din son, medan något hopp är; men låt icke dina själ dragas till att döda honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Ty stor harm kommer skada åstad; derföre låt honom lös, så kan du mer tukta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Hör råd, och tag vid tuktan, att du sedan må vis varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Mång anslag äro uti ens mans hjerta; men Herrans råd blifver beståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Menniskona pryder hennes välgerning; och en fattig man är bättre än en ljugare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Herrans fruktan fordrar till lifs; och skall mätt varda, att intet ondt skall hemsöka henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Den late gömmer sina hand i barmen, och förer henne icke till munnen igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Slår man bespottaren, så blifver den fåkunnige vis; straffar man en förståndigan, så varder han förnuftig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Den som fadren förlägger, och modrena fördrifver, han är ett skamligit och förbannadt barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Låt af, min son, att höra den tuktan, som förer ifrå förnuftig Iäro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Ett vrångt vittne bespottar domen; och de ogudaktigas mun uppslukar orätthetena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Bespottarom är straff beredt, och slag på de dårars rygg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Vin gör lösaktigt folk, och starka drycker göra buller; den som dertill lust hafver, han varder aldrig vis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Konungens förskräckelse är såsom ens ungs lejons rytande; den honom förtörnar, han syndar emot sitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Det är enom man en ära, att han är utan träto; men de som gerna träta, de äro allesamman dårar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'För kölds skull vill den late icke plöja; så måste han i andene tigga och intet få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Rådet uti ens mans hjerta är såsom djup vatten; men en förståndig kan märka, hvad han menar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Månge menniskor varda fromme kallade; men ho skall finna en, den rättsliga from är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'En rättfärdig, den i sine fromhet vandrar, hans barnom varder väl gångandes efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'En Konung, den på stolenom sitter till att döma, han förskingrar allt argt med sin ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Ho kan säga: Jag är ren i mitt hjerta, och klar ifrå mina synder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Mångahanda vigt och mått, både är Herranom en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Man känner ock en dräng på hans väsende, om han from och redelig vara vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ett hörande öra, och seende öga, Herren gör dem båda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Älska icke sömn, att du icke skall fattig varda; låt din ögon vaken vara, så får du bröd nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Ondt, ondt säger man, då man hafver det; men då det borto är, så rosar man det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Man finner guld och många perlor; men en förnuftig mun är ett ädla klenodium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Tag honom sin kläde bort, som för en annan i borgan går, och panta honom för den okändas skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Stulet bröd smakar hvarjom och enom väl; men derefter skall honom munnen full varda med hvassa stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Anslag bestå, då man förer dem med råd; och krig skall man med förnuft föra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Var unbevarad med den som hemlighet uppenbarar, och med baktalare, och med falskom mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Den sinom fader och sine moder bannar, hans lykta skall utslockna midt i mörkret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Det arf, der man allt för mycket hastar till det varder på sistone icke välsignadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Säg icke: Jag vill vedergälla det onda. Förbida Herran, han skall hjelpa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Mångahanda vigt är Herranom en styggelse; och en falsk våg är icke god.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Hvars och ens gånger komma af Herranom; hvilken menniska förstår sin väg?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Det är menniskone en snara, lasta det helga, och sedan söka löfte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'En vis Konung förskingrar de ogudaktiga, och låter gå hjulet öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Herrans lykta är menniskones ande; han går igenom hela hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Fromhet och sannfärdighet bevara Konungen, och hans säte består genom fromhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Unga mäns starkhet är deras pris, och de gamlas grå hår är deras prydning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Sår fördrifver det onda, och hela hjertans skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Konungens hjerta är uti Herrans hand, såsom vattubäcker; och han böjer det hvart han vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Hvar och en tycker sin väg rättan vara; men Herren allena gör hjertan viss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Göra väl och rätt är Herranom kärare än offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Högfärdig ögon, och ett stolt sinne, och de ogudaktigas lykta, är synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'En idogs mans anslag draga in ymnoghet; men den som allt för hastig är, han varder fattig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Den som en skatt samkar med lögn, honom skall fela; och han skall falla ibland dem som döden söka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'De ogudaktigas röfvande skall förskräcka dem; ty de ville icke göra hvad rätt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Den en främmande väg går, han är vrångvis; men den som går i sine befallning, hans verk är rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Bättre är bo uti en vrå på taket, än med en trätosam qvinna uti ett stort hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Dens ogudaktigas själ önskar ondt, och unnar sinom nästa intet godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'När bespottaren straffad varder, varda de fåkunnige vise; och när man underviser en visan, så varder han förnuftig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'En rättfärdig håller sig visliga emot dens ogudaktigas hus; men de ogudaktige tänka till att göra skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Den som tillstoppar sin öron för dens fattigas rop, han skall ock ropa, och intet hörd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'En hemlig gåfva stillar vrede, och en skänk i skötet aldrastörsta ogunst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Det är dem rättfärdiga en glädje, att göra det rätt är; men fruktan blifver dem som illa göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'En menniska, som ifrå klokhetenes väg, hon skall blifva uti de dödas hop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Den som gerna lefver i vällust, han skall blifva fattig; och den der vin och oljo älskar, han varder icke rik.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Den ogudaktige måste i dens rättfärdigas stad utgifven varda, och föraktaren för de fromma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Bättre är att bo uti ett öde land, än när en trätosamma och ensinnada qvinno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Uti dens visas hus är en lustig skatt, och olja; men en dåre förtärer det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Den som far efter barmhertighet och godhet, han finner lif, barmhertighet och äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'En vis man vinner de starkas stad, och omstörter hans magt genom hans säkerhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Den sin mun och tungo bevarar, han bevarar sina själ för ångest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Den som stolt och öfverdådig är, han kallas en lösaktig menniska, den i vredene stolthet bevisar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Den late dör öfver sine önsko; ty hans händer vilja intet göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Han önskar dagliga; men den rättfärdige gifver, och nekar intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'De ogudaktigas offer är en styggelse; ty det varder i synd offradt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Ett lögnaktigt vittne skall förgås; men den som höra gitter, honom låter man ock tala igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Den ogudaktige löper igenom med hufvudet; men den der from är, hans väg blifver beståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Ingen vishet, intet förstånd, ingen konst hjelper emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Hästar varda tillredde till stridsdagen; men segren kommer af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Rykte är kosteligare än stor rikedom; och ynnest bättre än silfver och guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Rike och fattige måste vara ibland hvarannan; Herren hafver gjort dem alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Den kloke ser det onda, och tager sig vara; de oförnuftige löpa igenom, och få skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Der man lider i Herrans fruktan, der är rikedom, ära och lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Spjut och snaror äro på dens vrångas väg; men den som drager sig der långt ifrå, han bevarar sitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Såsom man vän ett barn, så låter det icke af, då det gammalt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Den rike råder öfver de fattiga, och den som borgar, han är hans träl som lånar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Den som orätt sår, han skall uppskära vedermödo, och skall igenom sins ondskos ris förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Ett mildt öga varder välsignadt; ty han gifver af sitt bröd dem fattiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Drif ut bespottaren, så kommer kifvet bort; så vänder igen träta och smälek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Den som ett trofast hjerta hafver, och täckeliga talar, hans vän är Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Herrans ögon bevara godt råd; men föraktarens ord omstörter han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Den late säger: Ett lejon är ute; jag måtte varda dräpen på gatone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Ens skökos mun är en djup grop; dem Herren ogunstig är, han faller deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Galenskap är i piltens hjerta; men tuktans ris drifver den långt ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Den som den fattiga orätt gör, på det hans gods må mycket varda, han skall ock gifva enom rikom, och fattig varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Böj din öron, och hör de visas ord, och lägg uppå hjertat mina läro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Ty det skall väl bekomma dig, om du dem när dig behåller; och de skola tillsammans genom din mun väl lyckas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Att ditt hopp skall vara intill Herran, måste jag dig om sådant dagliga förmana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Hafver jag icke margfaldeliga skrifvit dig före, med råd och läro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'På det jag skulle visa dig en vissan grund till sanningena, att du måtte kunna rätteliga svara dem som dig sända?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Beröfva icke den fattiga, ändock han fattig är; och undertryck icke den elända i portenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Ty Herren skall handla deras sak, och skall förtrycka deras förtryckare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Gif dig icke i sällskap med en vredsam man, och håll dig icke intill en grym man;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Att du tilläfventyrs icke lärer hans väg, och får dine själs förargelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Var icke när dem som sina hand förpligta, och för skuld i borgan gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Ty om du icke hafver till att betala, så tager man dina säng bort under dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'För icke tillbaka de förra råmärke, som dine fäder gjort hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Ser du en man endigan i sin ärende, han skall stå för Konungenom; och skall icke stå för de oädla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'När du sitter och äter med enom herra, så gif akt uppå, hvad för dig handladt varder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Och sätt en knif på din hals, om du vill behålla lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Önska dig icke af hans mat; ty det är falskt bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Möd dig icke till att varda rik, och vänd igen af dina funder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Låt icke din ögon flyga efter det som du icke få kan; ty detsamma gör sig vingar såsom en örn, och flyger upp åt himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Ät icke bröd med en afundsfull, och önska dig icke hans mat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Ty såsom ett spökelse är han innantill. Han säger: Ät och drick; och hans hjerta är dock icke till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Dine betar, som du ätit hafver, måste du utspy; och måste din vänliga ord förtappat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Tala icke för ens dåras öron; ty han föraktar dins tals klokhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'För icke tillbaka de förra råmärke, och gack icke in uppå de faderlösas åker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Ty deras förlösare är mägtig; han skall uträtta deras sak emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Gif ditt hjerta till tuktan, och din öron till förnuftigt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Låt icke af att tukta pilten; ty om du slår honom med ris, så betorf man icke dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Du slår honom med ris; men du friar hans själ ifrå helvetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Min son, om du vis är, så gläder sig ock mitt hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Och mine njurar äro glade, när dina läppar tala det rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Ditt hjerta följe icke syndarom; utan var dagliga uti Herrans fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Ty det skall vara dig framdeles godt, och ditt väntande skall icke fela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Hör, min son, och var vis; och styr ditt hjerta in på vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Var icke ibland drinkare och slösare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Ty de drinkare och slösare varda fattige, och en sofvare måste rifven kläder bära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Hör din fader, den dig födt hafver, och förakta icke dina moder, då hon gammal varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Köp sanningena, och sälj icke bort henne; vishet, tuktan och förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Dens rättfärdigas fader gläder sig; och den som en visan födt hafver, han är glad deröfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Låt din fader och dina moder glädja sig, och glädje sig den dig födt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Gif mig, min son, ditt hjerta, och låt dinom ögom mina vägar behaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Ty en sköka är en djup grop, och horkonan är en trång grop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Och vaktar hon såsom en röfvare, och de oaktsamma ibland menniskorna samkar hon till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Hvar är ve? Hvar är sorg? Hvar är kif? Hvar är klagan? Hvar äro sår utan sak? Hvar äro röd ögon?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Nämliga der man dryckenskap öfvar, och kommer till att utdricka hvad inskänkt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Se icke till vinet, att det så rödt är, och står så dägeligit i glasena, och går lätteliga in;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Men på sistone biter det såsom en orm, och stinger såsom en huggorm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Så se din ögon efter andra qvinnor; och ditt hjerta talar oskälig ting;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Och du blifver såsom en den der sofver midt i hafvet, och såsom den der sofver ofvanpå en mast.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'De slå mig, och det gör mig intet ondt; de stöta mig, men jag känner det intet. När skall jag uppvaka, att jag måtte komma till drycks igen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Följ icke onda menniskor, och begär icke att vara när dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Ty deras hjerta står efter skada, och deras läppar råda till ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Genom vishet varder ett hus bygdt, och genom förstånd vid magt hållet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Genom skickelig hushållning varda husen full med allahanda kosteliga och härliga rikedomar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'En vis man är stark, och en förnuftig man är mägtig af krafter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Ty med råd måste man örlig föra; och der månge rådgifvare äro, der är segren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Vishet är dem galna allt för hög; han tör icke upplåta sin mun i portenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Den sig sjelfvom skada gör, honom kallar man väl en hufvudskalk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Ens dåras tanke är synd, och en bespottare är en styggelse för menniskomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Den är icke stark, som i nödene icke fast är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Hjelp dem som man döda vill, och drag dig icke undan för dem som man dräpa vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Säger du: Si, vi förståt intet; menar du, att den der hjertan vet, märker det icke; och den der på själena akt hafver, känner det icke; och lönar menniskone efter hennes gerningar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Ät, min son, hannog, ty det är godt; och hannogskaka är söt i dinom hals.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Alltså lär vishetena för dina själ; när du finner henne, så varder det framdeles väl gåendes, och ditt hopp skall icke fåfängt vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Vakta icke, såsom en ogudaktig, uppå dens rättfärdigas hus; förspill icke hans hvilo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Ty en rättfärdig faller sju resor, och står åter upp; men de ogudaktige falla uti olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Gläd dig icke öfver dins oväns fall, och ditt hjerta fröjde sig icke öfver hans olycka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Herren måtte det se, och honom det illa behaga, och vända sina vrede ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Vredgas icke öfver den onda, och haf icke nit öfver de ogudaktiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Ty den onde hafver intet till hoppandes, och de ogudaktigas lykta skall utslockna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Min son, frukta Herran och Konungen, och blanda dig icke ibland de upproriska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Ty deras förderf skall med hast uppstiga; och ho vet, när begges olycka kommer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Detta kommer ock ifrå de visa. Anse personen i domenom är icke godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Den som till den ogudaktiga säger: Du äst from; honom banna menniskorna, och folket hatar honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Men de som straffa honom, de behaga väl; och en rik välsignelse kommer öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Ett redeligit svar är såsom ett ljuft kyssande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Beställ din ärende ute, och bruka din åker; sedan bygg ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Var icke vittne utan sak emot din nästa, och bedrag icke med dinom mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Säg icke: Såsom man gör mig, så vill jag göra igen, och vedergälla hvarjom och enom hans gerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Jag gick framom dens latas åker, och om dens galnas vingård;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Och si, der var icke annat än nässlor på, och stod full med tistel, och muren var omkullfallen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Då jag det såg, lade jag det på hjertat, och skådade, och lärde deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Du vill ännu något litet sofva, och ännu något litet sömnig vara, och ännu litet sammanlägga händerna till att hvila;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'Men din armod skall komma dig, såsom en vandrare, och din fattigdom, såsom en väpnad man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Desse äro ock Salomos Ordspråk, hvilka här tillsatt hafva Hiskia män, Juda Konungs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Det är Guds ära ena sak fördölja; men Konungars ära är ena sak utransaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Himmelen är hög, och jorden djup; men Konungars hjerta är oransakeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Man kastar bort slagget ifrå silfret, så varder der ett rent käril utaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Man kastar ett ogudaktigt väsende bort ifrå Konungenom, så varder hans säte med rättfärdighet befäst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Pråla icke för Konungenom, och träd icke fram der de store stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Ty det är dig bättre, när man till dig säger: Gack hitupp; än att du skulle för Förstanom förnedrad varda, det din ögon se måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Var icke hastig till att träta: ty hvad vill du sedan göra, när din nästa dig skämt hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Handla dina sak med din nästa, och uppenbara icke ens annars hemlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'På det att den det hörer icke skall tala dig illa till, och ditt onda rykte icke återvänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Ett ord i sinom tid taladt är såsom ett gyldene äple uti silfskålom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Den som en visan straffar, och han lyder honom, det är såsom en gyldene örnaring, och ett gyldene halsband.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Lika som snököld i andstiden, så är ett troget bådskap honom, som det sändt hafver, och vederqvicker sins herras själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Den der mycket talar, och håller intet, är såsom ett moln och väder utan regn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Genom tålamod varder en Förste blidkad, och en len tunga stillar hårdhetena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Finner du hannog, så ät så mycket som behöfves af honom, att du icke för mätt varder, och spyr det ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Drag din fot tillbaka ifrå dins nästas hus; han måste ledas vid dig, och varda dig vred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Den som emot sin nästa falskt vittnesbörd talar, han är ett spjut, svärd och skarp pil.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Föraktarens hopp i nödenes tid är såsom en rutten tand, och en oviss fot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Den för ett bedröfvadt hjerta visor qväder, det är såsom en sönderrifven klädnad om vintren, och ättika på krito.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Hungrar din ovän, så spisa honom med bröd; törstar han, så gif honom vatten dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Ty du samkar kol tillhopa uppå hans hufvud, och Herren vedergäller dig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Nordanväder gör storm, och en hemlig tunga gör ett oblidt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Det är bättre att sitta uti en vrå på taket, än när en trätosamma qvinno i ett stort nus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Ett godt rykte utaf fjerran land är lika som kallt vatten ene törstigo själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'En rättfärdig, som för enom ogudaktigom faller, är såsom en rörd brunn och en förderfvad källa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Den som för mycken hannog äter, det är icke godt; och den svår ting utransakar, det varder honom för svårt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'En man, som sin anda icke hålla kan, han är såsom en öppen stad utan murar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Lika som snö om sommaren, och regn i andene, så höfves icke enom dåra ära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Lika som en fogel bortfar, och en svala flyger, alltså biter intet en oförtjent banna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Hästenom en gissel, och åsnanom ett betsel, och dåranom ett ris på ryggen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Svara icke dåranom efter hans dårskap, att du honom icke lik varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Men svara dåranom efter hans dårskap, att han icke skall låta sig tycka, att han är vis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Den ena sak genom ett galet bådskap beställer, han är såsom en halter på fötterna, och tager skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Såsom enom krympling står att dansa, alltså står enom dåra tala om vishet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Den enom dåra äro tillägger, det är lika som man kastade en ädla sten uppå en stenrösjo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Ett ordspråk uti ens dåras mun är såsom en törneqvist, den uti ens druckens mans hand stinger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'En god mästare gör ett ting rätt; men den som en klåpare lejer, honom varder det förderfvadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Såsom en hund uppäter sina spyor igen, alltså är en dåre som sin galenskap på nytt bedrifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'När du en ser, som sig tycker vis vara, det är mera hopp uppå en dåra, än på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Den late säger: Det är ett ungt lejon på vägenom, och ett lejon på gatone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'En later vänder sig i sängene, lika som en dörr på dörrajernen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Den late gömmer sina hand i barmen, och det varder honom tungt, att han skall bära henne åt munnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'En later tycker sig visare vara än sju, som seder lära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Den som framgår, och blandar sig uti annars kif, han är lika som en, den der drager en hund med öronen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Lika som en hemliga med skott och pilar skjuter, och dräper;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Alltså gör en falsk menniska med sin nästa, och säger sedan: Det var mitt skämt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Då intet mer ved är, slocknar elden; och när klaffaren är borta, vänder trätan åter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Såsom kolen glöd, och veden eld, alltså kommer en trätosam man kif åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Klaffarens ord äro såsom hugg, och de gå igenom hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'En förgiftig mun, och ondt hjerta, är såsom en lerpotta med silfslagg öfverdragen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Fienden varder känd vid sitt tal, och när han nalkas, far han med falskhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Då han smeker med sitt mjuka tal, tro honom intet; ty sju styggelser äro uti hans hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Den som hat hemliga håller, till att göra skada, hans ondska skall den meniga man uppenbar varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Den ena grop gör, han skall falla deruti; och den en sten välter, uppå honom skall han komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'En falsk tunga hatar den henne straffar, och en smeken mun kommer förderf åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Beröm dig icke af morgondagen; ty du vetst icke hvad i dag hända kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Låt en annan lofva dig, och icke din mun; en främmande, och icke dina egna läppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Stenen är svår, och sanden är tung; men ens dåras vrede är svårare än de både.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Vrede är en grym ting, och harm är en storm; och ho kan bestå för afund?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Uppenbara straff är bättre än hemlig kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Älskarens slag äro trofast; men hatarens kyssande bedrägeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'En mätt själ trampar väl på hannogskakona; men ene hungrogo själ är allt bittert sött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Såsom en fogel, den ifrå sitt näste viker, alltså är den som ifrå sitt rum viker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Hjertat fröjdar sig af salvo och rökverk; men en vän är behagelig för själenes råds skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Din vän och dins faders vän förlåt icke, och gack icke uti dins broders hus, när dig illa går; ty en granne vid handena är bättre, än en broder långt borto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Var vis, min son, så gläder sig mitt hjerta, så vill jag svara honom, som mig försmäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'En vis man ser det onda, och gömmer sig undan; men de fåkunnige gå derigenom, och få skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Tag honom sin klädnad bort, som för en annan i borgan går, och panta honom för dens främmandes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Den sin nästa med höga röst välsignar, och står bittida upp, det varder honom för en banno räknadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'En trätosam qvinna, och ett stadigt drypande då fast regnar, varda väl vid hvarannan liknad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Den henne uppehåller, han håller väder, och vill fatta oljona med handene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'En knif hvetter den andra, och en man den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Den sitt fikonaträ bevarar, han äter frukten deraf; och den sin herra bevarar, han varder ärad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Lika som skuggen i vattnet är emot ansigtet; alltså är ens menniskos hjerta emot den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Helvetet och förderfvet varda aldrig full, och menniskornas ögon varda ock aldrig mätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'En man varder igenom rosarens mun bepröfvad, såsom silfret i degelen, och guldet i ugnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Om du stötte en dåra i mortare, med stötare, såsom gryn, så går dock hans galenskap icke ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Tag vara uppå ditt får, och låt vårda dig om din hjord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Ty gods varar icke evinnerliga, och kronan varar icke till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Gräset är uppgånget, och hö är för handene, och på bergen varda örter församlade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Lamben kläda dig, och bockarna gifva dig åkerhyrona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Du hafver getamjölk nog till dins hus spis, och till dina tjenarinnors födo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Den ogudaktige flyr, och ingen jagar honom; men den rättfardige är frimodig, såsom ett ungt lejon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'För landsens synders skull varda många förvandlingar i Förstadömen; men för deras skull, som förståndige och förnuftige äro, blifva de länge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'En armling, som de fattiga oförrättar, är såsom väta, den fruktena förderfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'De som lagen öfvergifva, lofva den ogudaktiga; men de som bevara lagen, äro dem ogunstige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Onde menniskor akta intet uppå rätt; men de som efter Herran fråga, de akta uppå all ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Bättre är en fattig, den i sine fromhet vandrar, än en rik man, den i vrångom vägom går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Den der lagen bevarar, han är ett förståndigt barn; men den som slösare uppehåller, han skämmer sin fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Den sitt gods förmerar med ocker och vinning, han församlar det dem fattigom till nytto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Den sitt öra afvänder till att höra lagen, hans bön är en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Den som de fromma förförer in uppå en ond väg, han varder i sina grop fallandes; men de fromme skola det goda ärfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'En rik man tycker, att han är vis; men en fattig förståndig märker honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'När de rättfärdige hafva öfverhandena, så går det ganska väl till; men när ogudaktige uppkomma, så varder en omvändning i folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Den sina missgerning nekar, honom varder icke väl gångandes; men den henne bekänner och öfvergifver, han skall få barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Säll är den som städse fruktar; men den som halsstyf är, han faller i olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'En ogudaktig, som öfver ett fattigt folk regerar, han är ett rytande lejon, och en girig björn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'När en Förste utan förstånd är, så sker mycken orätt; men den der girighet hatar, han skall länge lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'En menniska, som uppå ens själs blod orätt gör, han varder icke behållen, det han än i kulona fore.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Den der i fromhet vandrar, han blifver vid sig; men den en ond väg går, han måste engång falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Den sin åker brukar, han skall få bröd nog; men den der far efter att gå fåfäng, han skall få fattigdom nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'En trofast man varder mycket välsignad; men den der fiker efter att varda rik, han skall icke oskyldig blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Anse personen är icke godt; ty han gjorde väl illa för ett stycke bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Den som hastar efter rikedom, och är nidsk, han vet icke, att honom skall nöd uppåkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Den ena mennisko straffar, han skall sedan ynnest finna, mer än den der smekrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Den som tager ifrå fader eller moder, och säger: Det är icke synd; han är förderfvarens stallbroder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'En högmodig man uppväcker träto; men den som förlåter sig uppå Herran, han varder fet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Den sig uppå sitt hjerta förlåter, han är en dåre; men den som går med vishet, han skall friad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Den som den fattiga gifver, honom skall intet fattas; men den som sin ögon afvänder, med honom skall det fast tillbakagå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'När de ogudaktige uppkomma, så förgömmer sig folket; men när de förgås, så varda de rättfärdige månge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Hvilken som emot straff genstörtig är, han skall med hast förderfvad varda, utan all hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'När de rättfärdige månge äro, så glädes folket; men när den ogudaktige regerar, så suckar folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Den som vishet älskar, han gläder sin fader; men den som skökor uppehåller, han mister sina ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'En Konung upprätter landet genom rätt; men en girig förderfvar det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Den som smekrar med sin nästa, han utbreder ett nät för hans fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'När en ond syndar, besnärjer han sig sjelf; men en rättfärdig fröjdar sig, och hafver glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Den rättfärdige känner den fattigas sak; den ogudaktige aktar ingen förnuft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'De bespottare föra en stad i olycko; men de vise stilla vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'När en vis med en dåra till handel kommer, han vare vred eller glad, så hafver han dock ingen ro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'De blodgirige hata den fromma; men de rättfärdige vårda sig om hans själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'En dåre gjuter sin anda allan ut; men en vis man håller tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'En herre, som till lögn lust hafver, hans tjenare äro alle ogudaktige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Fattige och ockrare bo ibland hvarannan; begges deras ögon upplyser Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'En Konung, som de fattiga troliga dömer, hans säte blifver evigliga beståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Ris och straff gifver vishet; men ett barn, som hafver sjelfsvåld, skämmer sina moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Der månge ogudaktige äro, der äro många synder; men de rättfärdige skola se deras fall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Tukta din son, så skall han vederqvicka dig, och göra dine själ vällust.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'När Prophetien ute är, så förskingras folket; men väl är honom, som lagen vid magt håller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'En tjenare låter icke näpsa sig med ordom; förty, om han än förstår det, så tager han sig dock intet deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Ser du en, som snar är till att tala, det är mera hopp uppå en dåra, än uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Om en tjenare varder af ungdom kräseliga hållen, så vill han sedan vara en herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'En vredsam man kommer träto åstad, och en harmse man gör många synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Menniskones högfärd skall omstörta henne; men ära skall upphöja den ödmjuka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Den som med tjufvar del hafver, hörer bannas; och säger icke till, han hatar sitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Den som rädes för menniskom, han kommer på fall; men den som sig förlåter uppå Herran, han varder beskyddad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Månge söka ens Förstas ansigte; men hvars och ens dom kommer af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'En orättfärdig man är dem rättfärdigom en styggelse; och den som på en rätt väg är, han är dens ogudaktigas styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Detta är Agurs, Jake sons, ord, lära och tal; dens mansens, till Ithiel, ja till Ithiel och Uchal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Ty jag är den aldragalnaste, och menniskors förstånd är icke när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Jag hafver icke lärt vishet; och hvad heligt är, vet jag icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Hvilken far upp till himmelen, och neder? Ho fattar vädret i sina händer? Ho binder vattnet uti ett kläde? Ho hafver stadfäst alla verldenes ändar? Huru heter han? Och huru heter hans Son? Vetst du det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'All Guds ord äro genomluttrad, och äro en sköld dem som tro uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Lägg intet till hans ord, att han icke skall straffa dig, och du varder lögnaktig funnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Tu ting bedes jag af dig, att du dock icke ville neka mig dem, förr än jag dör:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Afguderi och lögn låt vara långt ifrå mig; fattigdom och rikedom gif mig icke, men låt mig min afskilda del af spis få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Jag måtte eljest, om jag alltför mätt vorde, neka och säga: Ho är Herren? eller, om jag alltför fattig vorde, måtte stjäla, och förtaga mig på mins Guds Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Förråd icke tjenaren för hans herra, att han icke bannar dig, och du kommer i skuld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Det är ett slägte, som banna sin fader, och icke välsigna sina moder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Ett slägte, som sig tycker rent vara, och äro dock icke ifrå sinom träck rene tvagne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Ett slägte, som sin ögon högt upphäfva, och sin ögnahvarf högt upphålla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Ett slägte, som hafver svärd för tänder, hvilke med sina oxlatänder uppfräta och förtära de elända i landena, och de fattiga ibland menniskorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Iglen har två döttrar: Bär hit, Bär hit. Tre ting stå icke till att mätta, och det fjerde säger icke: Det är nog:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Helvetet, en ofruktsam qvinnos lif; jorden varder icke af vattnet mätt; och elden säger icke: Det är nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Ett öga, som bespottar fadren, och försmår att lyda modrene, det måste korparna vid bäcken uthugga, och de unga örnar uppfräta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Tre ting äro mig förunderlige, och det fjerde vet jag icke:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Örnens väg i vädret; ormens väg på hälleberget; skeppets väg midt i hafvet; och ens mans väg till ena pigo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Alltså är horkonones väg; hon uppsluker, och stryker sig om munnen, och säger: Jag hafver intet illa gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Ett land varder igenom tre ting oroligit, och det fjerde kan det icke fördiaga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'En tjenare, då han Konung varder; en dåre, då han alltför mätt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'En vanartig, då hon gift varder; och en tjenarinna, då hon sina frues artving varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Fyra äro små ting på jordene, och klokare än de vise:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Myrorna, ett svagt folk, likväl skaffa de om sommaren sin spis;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Kuniler, ett svagt folk, likväl göra de sitt hus i bergsklippomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Gräshoppor hafva ingen Konung, likväl draga de ut med hela hopar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Spindelen virkar med sina händer, och är i Konungapalats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Tre ting hafva en skön gång, och det fjerde går väl:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Lejonet mägtigt ibland djuren, och vänder icke tillbaka för någrom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'En vedehund med starka länder; och en vädur; och en Konung, dem ingen sig emotsätta tör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Hafver du varit fåvitsk, och upphäfvit dig, och haft ondt för händer, så lägg handena på munnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Då man mjölk kärnar, gör man der smör utaf; och den der näsona trycker, han tvingar der blod ut; och den der vrede uppväcker, han tvingar der träto ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Detta är Konung Lemuels ord, den lära, som honom hans moder lärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Ack! min utkorade; ack! du mins lifs son; ack! min önskade son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Låt icke qvinnor få dina förmågo, och gack icke de vägar, der Konungar förderfva sig på.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'O! icke Konungom, Lemuel; gif icke Konungom vin dricka, eller Förstom starka drycker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Att de icke dricka, och förgäta rätthetena, och förvända de elända menniskors sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Gif starka drycker dem som förgöras skola, och vin bedröfvadom själom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Att de måga dricka, och förgäta sina vedermödo, och icke mer ihågkomma sin jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Låt din mun upp för de dumbar, och för allas deras sak, som förlåtne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Låt din mun upp, och döm rätt, och hämnas den elända och fattiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Hvilkom en dygdelig qvinna beskärd är, hon är mycket ädlare, än aldrakosteligaste perlor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Hennes mans hjerta tör förlåta sig uppå henne, och bergning skall honom icke fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Hon gör honom ljuft, och icke ledt, i alla sina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Hon brukar sig på ull och lin, och arbetar gerna med sina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Hon är såsom ett köpmanskepp, som sina bergning fjerranefter hemtar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Hon står om nattene upp, och gifver sitt husfolk mat, och sina tjenarinnor deras del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Hon tänker på en åker, och köper honom; och planterar en vingård af sina händers frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Hon gjordar sina länder fast, och stärker sina armar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Hon märker, hvar hennes handel kan hafva förkofring; hennes lykta utsläckes icke om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Hon räcker ut sina hand till rocken, och hennes finger fatta tenen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Hon utsträcker sina händer till den fattiga, och räcker sina hand dem torftiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Hon fruktar icke sino huse för snö; ty hela hennes hus hafver dubbel kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Hon gör sig täcken; hvitt silke, och purpur är hennes kläde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Hennes man är prisad i portomen, när han sitter när landsens äldsta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Hon gör en kjortel, och säljer honom; ett bälte får hon krämarenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Hennes prydning är, att hon renlig och flitig är; och framdeles skall hon le.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Hon upplåter sin mun med vishet, och på hennes tungo är täckelig lära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Hon ser till, huru det i hennes hus tillstår, och äter icke sitt bröd i lättja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Hennes söner komma upp, och prisa henne saliga; hennes man lofvar henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Många döttrar samka rikedom; men du öfvergår dem alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Täckeligt och dägelig vara är intet; en qvinna, som Herran fruktar, den skall man lofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Hon skall rosad varda af sina händers frukt, och hennes gerningar skola lofva henne i portomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Detta är Predikarens ord, Davids sons, Konungs i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Allt är fåfängelighet, sade Predikaren; allt är icke annat än fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Hvad hafver menniskan mer af alla sine mödo, som hon hafver under solene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'En slägt förgås, den andra kommer till; men jorden blifver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Solen går upp, och går neder, och löper till sitt rum, att hon der igen uppgå skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Vädret går söder ut, och kommer norr igen, och åter på det rum igen, der det begynte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Alla floder löpa i hafvet, dock varder icke hafvet dess fullare; till det rum, der de utflyta, dit flyta de igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'All ting är mödosam, så att ingen kan uttalat. Ögat ser sig aldrig mätt, och örat hörer sig aldrig mätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Hvad är det, som skedt är? Detsamma, som härefter ske skall. Hvad är det man gjort hafver? Detsamma, som man härefter ännu göra skall; och sker intet nytt under solene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Sker ock något, der man af sägs kan: Si, det är nytt? Ty det är ock förr skedt i de förra tider, som för oss varit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Man kommer intet ihåg, huru det tillförene gånget är, ej heller kommer man ihåg, hvad härefter kommer, när dem som tillkommande äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Jag, Predikare, var Konung öfver Israel i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Och gaf mitt hjerta till att visliga söka och ransaka allt det man gör under himmelen. Sådana usla mödo hafver Gud gifvit menniskors barn, att de sig deruti qvälja skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Jag såg på allt det under solene sker, och si, det var allt fåfängelighet och jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Krokot kan icke varda rätt; icke heller kunna bristerna varda räknade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Jag sade i mitt hjerta: Si, jag är härlig vorden, och hafver mer vishet, än alla de som för mig varit hafva i Jerusalem, och mitt hjerta hafver mycket lärt och försökt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Och gaf också mitt hjerta dertill, att jag måtte lära vishet, och dårskap, och klokhet; men jag förnam, att det är ock möda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Ty der mycken vishet är, der är mycken grämelse; och den mycket försöker, han måste mycket lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Jag sade i mitt hjerta: Nu väl, jag vill lefva väl, och göra mig goda dagar; men si, det var ock fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Jag sade till löjet: Du äst galet; och till glädjena: Hvad gör du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Då tänkte Jag i mitt hjerta att hålla mitt kött ifrå vin, och hålla mitt hjerta till vishet, att jag måtte klok varda, tilldess jag måtte lära, hvad menniskomen nyttigt vore till att göra, så länge de lefva under himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Jag gjorde stor ting; jag byggde hus, planterade vingårdar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Jag gjorde mig örtagårdar och trägårdar, och planterade deruti allehanda fruktsam trä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Jag gjorde mig dammar, till att vattna skogen af de gröna trä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Jag hade tjenare och tjenarinnor, och tjenstefolk; jag hade större ägodelar i fä och får, än alle de som för mig voro i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Jag församlade mig ock silfver och guld, och en skatt af Konungom och landom; jag beställde mig sångare och sångerskor, och menniskors vällust, allahanda strängaspel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Och förkofrade mig öfver alla de som för mig varit hade i Jerusalem; blef ock vishet när mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Och allt det min ögon önskade, lät jag dem få, och förtog mino hjerta ingen glädje, så att det gladdes af allt mitt arbete. Och det höll jag för min del af allt mitt arbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Men då jag såg på all min verk, som min hand gjort hade, och den mödo, som jag haft hade; si, då var det allt fåfängelighet och jämmer, och intet annat under solene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Då vände jag mig till att se vishet (och klokhet), galenskap och dårskap; ty hvilken är den menniska, som det göra kan efter Konungenom, den henne gjort hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Då såg jag, att visheten öfvergick dårskapen, såsom ljuset mörkret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Så att den vise hafver sin ögon i hufvudet, men de dårar gå i mörkret; och märkte dock, att dem ena går som dem andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Då tänkte jag i mitt hjerta: Medan dem galnom går såsom mig, hvarföre hafver jag då farit efter vishet? Då tänkte jag i mitt hjerta, att sådant är ock fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Ty man tänker icke på den visa evinnerliga, såsom icke heller på den galna; och de tillkommande dagar förgäta allt; och såsom den vise dör, så ock den galne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Derföre leddes mig lefva; ty det behagade mig illa allt det under solene sker, att det så allstings fåfängeligit och mödosamt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Och mig leddes vid allt mitt arbete som jag under solene hade, att jag måste lefva det ene mennisko, som efter mig komma skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Ty ho vet, om han skall varda vis eller galen; och skall dock råda öfver allt mitt arbete, det jag hafver visliga gjort under solen. Det är ock fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Derföre vände jag mig, att mitt hjerta skulle aflåta af allo arbete, som jag gjorde under solene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Ty en menniska, som sitt arbete med vishet, förnuft och skickelighet gjort hafver, det måste hon låta enom androm till arfs, den deruppå intet arbetat hafver; det är ock fåfängelighet, och en stor olycka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Ty hvad får menniskan af allt sitt arbete, och hjertans bekymmer, hon hafver under solene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Utan sveda, grämelse och sorg, i alla sina lifsdagar; så att ock hennes hjerta icke kan hafva ro om nattena? Det är ock fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Är då nu menniskone icke bättre äta och dricka, och göra sine själ goda dagar i sitt arbete? Men det såg jag ock, att det kommer af Guds hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Ty ho hafver gladare ätit, och kräseligare lefvat, än jag?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Ty den menniska, som honom täck är, gifver han vishet, förnuft och glädje; men syndarenom gifver han olycko, att han församlar och lägger tillhopa, och det varder dock dem gifvet, som Gudi täck är; ty är det ock icke annat än jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'All ting hafva sin tid, och allt det man företager under himmelen hafver sina stund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Födas hafver sin tid, dö hafver sin tid; plantera hafver sin tid, upprycka det som planteradt är hafver sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Dräpa hafver sin tid, läka hafver sin tid; nederbryta hafver sin tid, bygga hafver sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Gråta hafver sin tid, le hafver sin tid; klaga hafver sin tid, dansa hafver sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Förkasta sten hafver sin tid, församia sten hafver sin tid; famntaga hafver sin tid, hafva famntag fördrag hafver sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Uppsöka hafver sin tid, borttappa hafver sin tid; behålla hafver sin tid, bortkasta hafver sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Sönderrifva hafver sin tid, sammansömma hafver sin tid; tiga hafver sin tid, tala hafver sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Älska hafver sin tid, hata hafver sin tid; strid hafver sin tid, frid hafver sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Man arbete huru man vill, så kan man intet mer uträtta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Deraf såg jag den mödo, som Gud menniskomen gifvit hafver, att de deruti skola plågade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Men han gör all ting väl i sinom tid, och låter deras hjerta ängslas derom, huru det gå skall i verldene; ty menniskan kan dock icke finna uppå det verk, som Gud gör, hvarken begynnelse eller ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Derföre märkte jag, att intet är bättre deruti, än att vara glad, och fara väl med sig i sina dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Ty hvar och en menniska, som äter och dricker, och är vid ett godt mod i allt sitt arbete, det är en Guds gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Jag märker, att allt det som Gud gör, det består alltid; man kan intet lägga dertill, eller taga derifrå; och sådant gör Gud, på det att man skall frukta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Hvad Gud gör, det blitver så, och hvad han göra vill, det måste ske; ty han tänker dertill, och fullföljer det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Ytterligare såg jag under solene domaresäte, der var ett ogudaktigt väsende; och rättvisones säte, der voro ogudaktige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Då tänkte jag i mitt hjerta: Gud måste döma den rättfärdiga och den ogudaktiga; ty allt det man företager, hafver sin tid, och all verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Jag sade i mitt hjerla om menniskors väsende: Skulle Gud utvälja dem, och låter det dock synas som de voro fä?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Ty menniskone går såsom fä; såsom det dör, så dör ock hon, och hafva alle enahanda anda; och menniskan hafver intet mer än fä; ty allt är fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Allt far till ett rum; allt är gjordt af stoft, och varder till stoft igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Ho vet, om menniskones ande far uppåt, och fänadens ande nederåt, under jordena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Derföre säger jag, att intet är bättre, än att en menniska är glad i sitt arbete; ty det är hennes del. Ty ho vill dertill komma henne, att hon ser hvad efter henne ske skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Jag vände mig, och såg på alla dem som orätt lida under solene; och si, der voro deras tårar, som orätt lida, och hade ingen tröstare; och de, som orätt gjorde, voro alltför mägtige, så att de ingen tröstaro få kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Då prisade jag de döda, som allaredo afledne voro, mer än de lefvande, som ännu lif hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Och den som ännu icke är till, mer än dem båda, och icke försöker det onda, som under solene sker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Jag såg på arbete och skickelighet i alla saker; der hatar hvar annan. Det är ock intet annat, än fåfängelighet och bekymmer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Ty en dåre knäpper samman händerna, och fräter sitt kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Bättre är en hand full i rolighet, än båda händerna fulla i mödo och jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Jag vände mig, och såg fåfängelighet under solene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'En är ensam, och icke sjelf annar, och hafver hvarken barn eller syskon; likväl är ingen ände på hans arbete, och hans ögon varda aldrig mätt af rikedomar. För hvem arbetar jag dock, och gör icke mine själ godt? Det är ju ock fåfängelighet, och ondt bekymmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Så är nu bättre två än en; ty de hafva dock gagn af deras arbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Faller en af dem, så hjelper hans stallbroder honom upp igen. Ve honom, som är allena; faller han, så är ingen annar för handene, som honom upphjelper.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Och när två ligga tillhopa, värma de sig; huru kan en ensammer blifva varm?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'En kan varda öfvervunnen, men två kunna stå emot; ty ett trefaldt rep går icke lätteliga sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Ett fattigt barn och vist är bättre än en gammal Konung, som en dåre är, och kan icke taga sig vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'En kommer utaf fängelse till Konungavälde, och en, som i Konungavälde född är, varder fattig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Och jag såg, att alle lefvande under solene vandrade med ett annat barn, som i dess andras stad uppkomma skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Och på folket, som för honom gick, var ingen ände; och de som efter honom gingo, gladdes dock intet vid honom; det är ju ock intet annat, än fåfängelighet och jämmer. Bevara din fot, när du går till Guds hus, och kom till att höra; det är bättre, än de dårars offer; ty de veta icke hvad ondt de göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Var icke för hastig med dinom mun, och låt ditt hjerta icke hasta till att något tala inför Gud; ty Gud är i himmelen, och du på jordene; derföre låt din ord vara få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Ty der många omsorger äro, der komma drömmer, och der mång ord äro, der hörer man en dåra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'När du gör Gudi ett löfte, så fördröj icke fullkomnat; ty han hafver intet behag till dårar. Hvad du lofvar, det håll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Det är bättre att du intet lofvar, än att du icke håller det du lofvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Städ icke dinom mun, att han förförer ditt kött, och säg icke för Ängelen: Jag är oskyldig. Gud måtte vredgas öfver dina röst, och fördöma all dina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Der månge drömmer äro, der är fåfängelighet, och många ord; men frukta du Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Ser du enom fattigom ske orätt, och rätt och rättviso i landena borttagas, förundra dig icke deröfver; ty det är ännu en högre väktare öfver de höga, och äro ännu högre öfver de båda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Deröfver är Konungen i hela landet, att marken må varda brukad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Den som älskar penningen, han varder aldrig mätt af penningar, och den der rikedom kär hafver, han skall ingen nytto få deraf; det är ock fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Ty der mycket gods är, der äro månge som ätat; och hvad nytto hafver han deraf, som det hafver, annat än att han ser deruppå med ögonen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Den der arbetar, honom är sömnen söt, ehvad han hafver litet eller mycket ätit; men dens rikas öfverflödighet städer honom icke sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Det är en ond plåga, som jag såg under solene, nämliga att rikedomar varda förvarade honom till skada, som dem äger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Ty den rike förgås med stor jämmer; och om han hafver födt en son, honom blifver intet i händerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Såsom han är naken kommen af sitt moderlif, så far han bort igen, som han kommen är, och tager intet med sig af allt sitt arbete i sine hand, när han bortfar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Det är en ond plåga, att han så hädanfar, som han kommen är; hvad hjelper det honom då, att han i vädret arbetat hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Alla sina lifsdagar hafver han ätit i mörkret, och i stor grämelse, och krankhet, och bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Så håller jag det nu for det bästa, när man äter och dricker, och är vid ett godt mod, i allt arbete, som en gör under solene alla sina lifsdagar, som Gud honom gifver; ty det är hans del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Ty hvilko mennisko Gud gifver rikedom, och ägodelar, och välde, att hon deraf äter och dricker på sin del, och är glad i sitt arbete, det är en Guds gåfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Ty han tänker icke mycket på detta elända lifvet, efter Gud fröjdar hans hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Det är ett ondt ting, som jag såg under solene, och är allmänneligit med menniskorna:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'En, hvilkom Gud hafver gifvit rikedom, ägodelar och äro, och honom fattas intet, det hans hjerta begärar, och Gud gifver honom dock icke magt till att nyttjat, utan en annar förtärer det; det är fåfängelighet, och en ond plåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Födde han än hundrade barn, och hade så långt lif, att han i mång år lefde, och hans själ kunde icke mätta sig af ägodelar, och blefve utan graf; om honom säger jag, att en otida född är bättre än han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Ty han kommer i fåfängelighet, och i mörker far han bort, och hans namn blifver betäckt i mörker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Han hafver ingen glädje af solene, och hafver ingen ro, hvarken här eller der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Om han än lefde i tutusend år, så är han aldrig väl tillfrids. Kommer det icke allt uti ett rum?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Hvarjo och ene mennisko är arbete pålagdt, efter hennes mått; men hjertat kan icke blifva dervid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Ty hvad uträttar en vis mer än en dåre? Hvad tager sig den fattige före, att han vill vara ibland de lefvande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Det är bättre att bruka de ägodelar, som för handene äro, än fara efter andra; det är ock fåfängelighet och jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Hvad äret? Fastän en högt berömder är, så vet man dock, att han är en menniska, och kan icke träta med det som honom for mägtig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Ty fåfängeligheten är alltör mycken. Hvad hafver en menniska mer deraf?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Ty ho vet hvad menniskone nyttigt är i sin lifstid, medan hon lefver i sine fåfängelighet, hvilken är som en skugge? Eller ho vill säga menniskone, hvad efter henne komma skall under solene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Ett godt rykte är bättre än god salva, och dödsens dag bättre än födelsedagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Bättre är gå i sorgahus än i gästabådshus; uti det ena är alla menniskors ändalykt, och den lefvande lägger det uppå hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Sörja är bättre än le; ty genom sorg varder hjertat förbättradt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'De visas hjerta är i sorgahuset, och dårars hjerta i glädjehuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Bättre är höra dens visas straff, än att höra dårars sång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Ty dårars löje är såsom sprakande af törne under grytone; och det är ock fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'En genvördig gör en visan oviljog, och förderfvar ett mildt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Änden på ett ting är bättre än dess begynnelse; en tålig ande är bättre än en hög ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Var icke hastig till vrede; ty vreden hvilar uti ens dåras hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Säg icke: Hvad är det, att de förra dagar voro bättre än denne? Ty du frågar sådant icke visliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Vishet är god mild arfvedelen, och hjelper, att en kan glädja sig af solene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Ty vishet beskärmar; penningar beskärma ock; men visheten gifver lif honom, som henne hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Se på Guds verk; ty ho kan rätta det han gör krokot?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'I goda dagar var glad, och den onda dagen tag ock till godo; ty denna skapade Gud jemte den andra, att menniskan icke skall veta hvad tillkommande är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Jag hafver allahanda sett i mine fåfängelighets tid: Det är en rättfärdig, och förgås i sine rättfärdighet; och det är en ogudaktig, som länge lefver i sine ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Var icke allt för mycket rättfärdig, ej heller för mycket vis, att du icke förderfvar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Var icke allt för mycket ogudaktig, och galnas icke, att du icke dör i otid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Det är godt att du detta fattar, och att du ock icke släpper det andra utu dina hand; ty den der Gud fruktar, han undkommer det allt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Vishet stärker den visa, mer än tio väldige, som i stadenom äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Ty det är ingen menniska på jordene, som godt gör, och icke syndar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Lägg ock icke på hjertat allt det man säger; på det du icke skall höra din tjenare banna dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Ty ditt hjerta vet, att du ock ofta androm bannat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Sådant allt hafver jag försökt visliga. Jag tänkte: Jag vill vara vis; men visheten kom långt ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Det är fjerran, hvad skall det varda? Och det är fast djupt, ho kan finnat?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Jag vände mitt hjerta till att förfara, och uppspörja, och uppsöka vishet och konst, till att förfara de ogudaktigas dårhet, och de galnas villfarelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Och fann, att en sådana qvinna, hvilkens hjerta är nät och snara, och hennes händer bojor äro, är bittrare än döden. Den Gudi täck är, han undkommer henne; men syndaren varder genom henne fången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Si, det hafver jag funnit, säger Predikaren, hvart efter det andra, att jag måtte finna konst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Och min själ söker ännu, och hafver intet funnit. Ibland tusende hafver jag funnit en man; men ingen qvinno hafver jag funnit ibland alla. Allena skåda härtill: Jag hafver funnit, att Gud hafver gjort menniskona rätta; men de söka många konster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Ho är som en vis? Och ho kan det uttyda? Menniskones vishet upplyser hennes ansigte; men den der oförvägen är, honom hatar man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Jag håller Konungens ord, och Guds ed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Var icke för hastig till att gå ifrå hans ansigte, och blif icke i en ond sak; ty han gör hvad honom lyster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'I Konungens ord är magt, och ho kan säga till honom: Hvad gör du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Den der budet håller, han skall intet ondt försöka; men ens vis mans hjerta vet tid och sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Ty hvart och ett anslag hafver sin tid och sätt; ty menniskones olycka är mycken med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Ty hon vet icke hvad varit hafver; och ho kan säga henne, hvad varda skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'En menniska hafver icke magt öfver andan, till att förmena andan; och hafver icke magt i dödsens tid, och varder icke lös gifven i stridene; och ett ogudaktigt väsende hjelper den ogudaktiga intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Allt det hafver jag sett, och gaf mitt hjerta till all verk, som ske under solene; en menniska råder understundom öfver den andra, sig till skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Och der såg jag ogudaktiga, som begrafne voro; som gångit och vandrat hade i heligt rum, och voro förgätne i staden, att de så gjort hade; det är ock fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Efter det icke straxt går domen öfver onda gerningar, varder menniskones hjerta fullt till att göra ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Om en syndare hundrade resor illa gör, och dock länge lefver, så vet jag likväl, att dem varder väl gångande, som Gud frukta, de som hans ansigte frukta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Ty dem ogudaktiga varder icke väl gångandes, och såsom en skugge skola de icke länge lefva, som icke Gud frukta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Det är en fåfängelighet, som sker uppå jordene. Någre äro rättfärdige, och dem går, såsom de hade de ogudaktigas gerningar gjort; och någre äro ogudaktige, och dem går, såsom de hade de rättfärdigas gerningar gjort. Jag sade: Det är ock fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Derföre prisade jag glädjena, att menniskan intet bättre hafver under solene, än äta och dricka, och vara glad; och sådant får hon af sitt arbete i sine lifsdagar, som Gud henne gifver under solene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Jag gaf mitt hjerta till att veta vishet, och till att skåda den vedermödo, som på jordene sker; att ock en hvarken dag eller natt får sömn i sin ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Och jag såg all Guds verk; ty en menniska kan icke finna det verk, som under solene sker; och ju mer menniskan arbetar till att söka, ju mindre finner hon. Om hon än säger: Jag är vis, och vet det, så kan hon dock icke finnat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Ty jag hafver allt sådant lagt på hjertat, till att ransaka allt detta, att någre rättfärdige och vise äro, hvilkes underdåner i Guds hand äro. Dock vet ingen menniska någors kärlek, eller hat, som han hafver för sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Det vederfars så dem ena som dem andra, dem rättfärdiga, såsom dem orättfärdiga; dem goda och rena, såsom dem orena; dem som offrar, såsom honom som intet offrar. Såsom det går dem goda, så går det ock syndarenom; såsom menedarenom går, så går ock honom, som eden fruktar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Det är en ond ting ibland allt det som under solene sker, att dem ena så går som dem andra; deraf varder ock menniskones hjerta fullt med arghet, och galenskap är i deras hjerta, så länge de lefva; sedan måste de dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Hvad skall man då af de båda utvälja? Så länge som man lefver, skall man hoppas; ty en lefvande hund är bättre än ett dödt lejon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Ty de lefvande veta, att de skola dö; men de döde veta intet, de förtjena ock intet mer; ty deras åminnelse är förgäten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Så att man icke mer älskar dem, hatar eller afundas vid dem; och hafva ingen del mer på verldene i allo thy, som under solene sker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Så gack bort, och ät ditt bröd med fröjd, drick ditt vin med godt mod; ty din verk täckas Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Låt din kläder alltid vara hvit, och låt icke fattas salvo på ditt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Bruka din tid med dine hustru, den du älskar, så länge du behåller detta fåfängeliga lifvet, det (Gud) dig under solene gifvit hafver, så länge ditt fåfängeliga lif varar; ty det är din del i lifvena, och i ditt arbete, som dig under solene gifvit är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Allt det dig förekommer att göra, det gör friliga; ty i grafvene, dit du far, är hvarken gerning, konst, förnuft eller vishet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Jag vände mig, och såg huru det tillgår under solene, att det icke hjelper till att löpa, att man är snar; till strid hjelper icke, att man är stark; till bergning hjelper icke, att en är snäll; till rikedom hjelper icke vara klok; att en hafver ynnest, hjelper icke att han sin tingest väl kan; utan det står allt till tiden och lyckona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Ock vet menniskan icke sin tid; utan såsom fiskarna varda fångne med en skadelig krok, och såsom foglarna varda fångne med snarone, så varda ock menniskorna bortryckte i ondom tid, när han hasteliga kommer öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Jag hafver ock sett denna vishetena under solene, den mig stor syntes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Att en liten stad var, och fögo folk derinne, och kom en mägtig Konung, och belade honom, och byggde stor bålverk der omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Och derinne vardt funnen en fattig vis man, den med sine vishet kunde hjelpa staden, och ingen menniska tänkte på den samma fattiga mannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Då sade jag: Vishet är ju bättre än starkhet. Likväl vardt dens fattigas vishet föraktad, och hans ord vordo intet hörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Detta våller, de visas ord gälla mer när de stilla, än herrarnas rop när de dårar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Ty vishet är bättre än harnesk; men en endaste skalk förderfvar mycket godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Onda flugor förderfva goda salvo; derföre är dårskap stundom bättre än vishet och ära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Ty dens visas hjerta är på hans högra hand; men dens galnas hjerta är på hans venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Och ändå att den galne sjelf galen är i sin anslag, håller han likväl alla för galna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Derföre, om ens väldigs mans trug hafver framgång emot din vilja, så gif dig icke öfver; ty unddraga stillar mycket ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Det är ännu en usel ting, som jag såg under solene, nämliga oförstånd, det ibland de väldiga allmänneligit är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Att en dåre sitter i stora värdighet, och de rike sitta nedre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Jag såg tjenare på hästar, och Förstar gå till fots, såsom tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Men den ena grop grafver, han skall sjelf falla deruti; och den en gård rifver, honom skall stinga en orm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Den der stenar bortvältar, han skall hafva der mödo med; den som ved klyfver, han varder sargad deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Då ett jern slött varder, och mister skarphetena, så måste man med mödo hvässat igen; alltså följer ock visdom efter flit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'En lackare är icke bättre än en orm, som obesvoren stinger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'De ord, som gå af ens vis mans mun, äro täckelig; men ens dåras läppar uppsvälja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Begynnelsen på hans ord är dårskap, och änden är skadelig galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'En dåre hafver mång ord; ty menniskan vet icke hvad varit hafver; och ho vill säga henne, hvad efter henne komma skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'De dårars arbete varder dem svårt, efter man icke vet gå in i staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Ve dig, land, hvilkets Konung barn är, och hvilkets Förstar bittida äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Väl är dig, land, hvilkets Konung ädla är, och hvilkets Förstar äta i rättom tid, till styrko, och icke till vällust.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Ty för lättjas skull förfalla bjelkarna, och för försummeliga händers skull varder huset drypande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Det våller, att de bereda bröd till vällust, och vinet måste glädja de lefvande, och penningen måste dem allt uträtta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Banna icke Konungenom i ditt hjerta, och banna icke dem rika i dinom sängakammar; ty foglarna under himmelen föra dina röst, och de der vingar hafva, säga det efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Låt ditt bröd fara öfver vatten, så varder du det finnandes i längdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Skift ut emellan sju, ock emellan åtta; ty du vetst icke, hvad olycka på jordene komma kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'När molnskyarna fulle äro, så gifva de regn på jordena; och när trät faller, det falle söderut, eller norrut, på hvilket rum det faller, der blifver det liggandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Den som aktar på vädret, han sår intet, och den som uppå skyarna skådar, han skär intet upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Såsom du icke vetst vädrens väg, och huru benen i moderlifvet tillredd varda, så kan du ock icke veta Guds verk, som han allt gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Så dina säd om morgonen, och håll icke upp med dine hand om aftonen; ty du vetst icke, hvilketdera bättre lyckas kan; och om både lyckades, så vore det dess bättre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Ljuset är sött, och ögonen är ljuft att se solena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Om en menniska i lång tid lefver, och är glad i all ting, så tänker han dock allenast på de onda dagar, att de så månge äro; ty allt det honom vederfars, är fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Så gläd dig nu, du yngling, i dinom ungdom, och låt ditt hjerta vara gladt i dinom ungdom; gör hvad dino hjerta lyster, och dinom ögom behagar; och vet, att Gud skall, för allt detta, hafva dig fram för domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Lägg bort sorg utaf ditt hjerta, och kasta bort det onda ifrå dinom kropp; ty barndom och ungdom är fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Tänk uppå din Skapare i dinom ungdom, förr än de onda dagar komma, och åran nalkas, då du varder sägandes: De behaga mig intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Förr än solen och ljuset, månen och stjernorna mörka varda, och molnen igenkomma efter regn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'På den tid, då väktarena i huset darra, och de starke kröka sig, och mölnarena stå fåfänge, derföre att de så få vordne äro; och synen varder mörk genom fenstren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'Och dörrarna på gatone tillslutna varda, så att rösten af qvarnene tystnar, och uppvaknar när foglen sjunger, och sångsens döttrar varda nedertryckta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Så att de ock för höjderna frukta sig, och rädas på vägen; när mandelträt blomstras, och gräshoppan förtynges, och all lust förgås; ty menniskan far dit hon evinnerliga blifva skall; och de som gråta, gå omkring på gatone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Förrän silftåget bortkommer, och guldkällan utlöper, och ämbaret gistnar vid brunnen, och hjulet söndergår vid brunnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Ty stoftet måste åter komma till jord igen, såsom det varit hafver, och anden till Gud igen, den honom gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Allt är fåfängelighet, sade Predikaren; allt är fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Den samme Predikaren var icke allenast vis; utan han lärde ock folket god lärdom, och märkte, och utransakade, och sammansatte mång ordspråk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Predikaren sökte, att han måtte finna tacknämlig ord, och skref rätt sanningenes ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Denna de visas ord äro spjut och naglar, skrefne genom församlingenes mästare, och gifne af enom herda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Tag dig vara, min son, för andra flere; ty ingen ände är uppå att dikta böcker, och mycken predikan gör kroppen trött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Låt oss höra hufvudsummona till all lärdom: Frukta Gud, och håll hans bud; ty det hörer allom menniskom till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Ty Gud skall hafva fram alla gerningar för domen; ja, ock de der fördolda äro, ehvad de äro goda eller onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Salomos Höga Visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Han kysse mig med sins muns kyssande; ty din bröst äro ljufligare än vin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Att man må lukta din goda salvo; ditt Namn är en utgjuten salva; derföre hafva pigorna dig kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Drag mig efter dig, så löpe vi; Konungen förde mig in uti sin kammar: Vi fröjde oss, och äre glade öfver dig; vi tänke uppå din bröst mer än uppå vin; de fromme älska dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Jag är svart, men ganska täck, I Jerusalems döttrar, såsom Kedars hyddor, såsom Salomos tapeter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ser icke derefter, att jag så svart är; ty solen hafver bränt mig; mins moders barn vredgas emot mig. Man hafver satt mig till vingårdsvaktersko; men min vingård, den jag hade, bevarade jag icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Säg mig du, den min själ älskar, hvar du beter, hvar du hvilar om middagen; att jag icke skall gå hit och dit, till dina stallbröders hjordar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Känner du dig icke, du dägeligasta ibland qvinnor, så gack uppå fårens fotspår, och bet din kid vid herdahusen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Jag liknar dig, min kära, vid mitt resigtyg, vid Pharaos vagnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Dina kinder stå ljufliga i spann, och din hals i kedjo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Vi vilje göra dig gyldene spann med silfdoppor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Då Konungen vände sig hit, gaf min nardus sina lukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Min vän är mig ett knippe af myrrham, det emellan min bröst hänger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Min vän är mig en drufva Copher, uti de vingårdar i EnGedi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Si, min kära, du äst dägelig; dägelig äst du, din ögon äro såsom dufvoögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Si, min vän, du äst dägelig och ljuflig; vår säng grönskas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Vår hus bjelkar äro cedreträ; våre sparrar äro cypress.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Jag är ett blomster i Saron, och en lilja i dalenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Såsom en ros ibland törne, så är min kära ibland döttrarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Såsom ett äpleträ ibland skogsträ, så är min vän ibland sönerna; jag sitter under dens skugga, som jag begärar, och hans frukt är minom hals söt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Han hafver mig in uti vinkällaren, och kärleken är hans baner öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Han vederqvicker mig med blomster, och uppfriskar mig med äple; ty jag är krank af älskog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Hans venstra hand ligger under mitt hufvud, och hans högra hand omfamnar mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Jag besvär eder, Jerusalems döttrar, vid rår, eller vid hinder i markene, att I icke uppväcken eller omaken mina käresto, tilldess henne sjelf lyster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Detta är mins väns röst; si, han kommer, och springer på bergen, och springer på högarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Min vän är lik enom råbock, eller ungom hjort; si, han står bak vår vägg, och ser genom fenstret, och gluggar genom gallret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Min vän svarar, och säger till mig: Statt upp, min kära, min dägeliga, och kom hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Ty si, vintren är förgången, regnet är öfverståndet, och är sin väg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Blomstren äro utgångna på markene; vårtiden är kommen, och turturdufvan låter sig höra i vårt land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Fikonaträt är knoppadt, vinträn blomstras, och gifva sina lukt; statt upp, min kära, och kom, min dägeliga, kom hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Min dufva uti stenklyftor, uti bergsrefvor, låt mig se ditt ansigte, låt mig höra dina röst; ty din röst är söt, och ditt ansigte ljufligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Tager oss räfvar, de små räfvar, som förderfva vingårdar; ty våra vingårdar blomstras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Min vän är min, och jag är hans, den der beter ibland roser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Intilldess att dagen sval varder, och skuggorna afvika; vänd om, blif såsom en rå, min vän, eller såsom en ung hjort på skiljebergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Jag sökte om nattena i mine säng den min själ kär hade; jag sökte, men jag fann honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Jag vill stå upp och gå omkring i staden, på gator och gränder, och söka den min själ kär hafver; jag sökte, men jag fann honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Mig funno väktarena, som kringom i staden gå: Hafven I icke sett den min själ kär hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Då jag kom litet framom dem, så fann jag den min själ kär hafver; jag håller honom, och vill icke öfvergifva honom, tilldess jag hafver honom in uti mins moders hus, uti mins moders kammar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Jag besvär eder, I Jerusalems döttrar, vid rår och hinder på markene, att I icke uppväcken mina käro, eller omaken henne, tilldess henne sjelf lyster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Ho är denna, som uppgår utur öknene, såsom en rök af myrrham, rökelse och allahanda apothekares pulver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Si, omkring Salomos säng stå sextio starke, utaf de starka i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Alle hålla de svärd, och äro behändige till strids; hvardera hafver sitt svärd vid sina sido, för fruktans skull, om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Konung Salomo lät göra sig ett sängerum af Libanons trä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Dess stodar voro af silfver, täckelsen af guld, sätet af purpur, bottnen deruti var lusteliga lagd för Jerusalems döttrars skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Går ut, I Zions döttrar, och skåder Konung Salomo, i den krono, der hans moder honom med krönt hafver, på hans bröllopsdag, och på hans hjertas fröjds dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Si, min kära, du äst dägelig, si, dägelig äst du; din ögon äro såsom dufvoögon, emellan dina lockar; ditt hår är såsom getahjordar, som klippte äro på det berget Gilead.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Dina tänder äro såsom hjordar med afklippta ull, som tvagne komma utu vattnet, hvilke allesamman äro hafvande med tvillingar, och ingen af dem är ofruktsam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Dine läppar äro såsom ett rosenfärgadt snöre, och ditt tal ljufligit; dine kinder såsom skörden på granatäplet, emellan dina lockar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Din hals är såsom Davids torn, gjord med bröstvärn, der tusende sköldar uppå hänga, och allahanda de starkas vapen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Din tu bröst äro såsom två unga råtvillingar, hvilke ibland roser i bet gå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Tilldess dagen sval varder, och skuggorna afvika; jag vill gå till myrrhamsberget, och rökelsehögen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Du äst med allone dägelig, min kära, och ingen fläck är på dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Kom, min brud, ifrå Libanon, kom ifrå Libanon; gack in, träd hit ifrån Amana kulle, ifrå Senir och Hermons kulle, ifrå lejonens boning, ifrå de leoparders berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Du hafver tagit mig hjertat bort, min syster, kära brud, med ett ditt öga, och med ene dine halskedjo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Huru dägelig äro din bröst, min syster, kära brud; din bröst äro lustigare än vin, och din salvos lukt öfvergår alla örter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Dine läppar, min brud, äro såsom drypande hannogskaka; hannog och mjölk är under dine tungo, och din kläders lukt är såsom lukt af Libanon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Min syster, kära brud, du äst en tillsluten örtagård; en tillsluten källa, en förseglad brunn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Din frukt är såsom en lustgård af granatäple med ädla frukter, cyper med nardus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Nardus med saffran, calmus och canel, med allahanda Libanons trä; myrrham och aloes med alla bästa örter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Såsom en örtegårds brunn, såsom en brunn af lefvande vatten, det af Libanon flyter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Statt upp, nordanväder, och kom, sunnanväder, och blås igenom min örtegård, att hans örter måga drypa. Min vän komme uti sin örtegård, och äte sina ädla frukter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Jag kom, min syster, kära brud, uti min örtegård; jag hafver mitt myrrham, samt med mina örter, uppskurit; jag hafver ätit mina hannogskako, samt med minom hannog; jag hafver druckit mitt vin med mine mjölk; äter, mine käre, och dricker, mine vänner, och varder druckne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Jag sofver, och mitt hjerta vakar; der är mins väns röst, som klappar; låt mig upp, min kära, min syster, min dufva, min fromma; ty mitt hufvud är fullt med dagg, och mine lockar fulle med nattenes droppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Jag hafver afklädt min kjortel; huru skulle jag åter kläda honom uppå igen? Jag hafver tvagit mina fötter; huru skulle jag besmitta dem igen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Men min vän stack sina hand in genom ett hål, och mitt lif darrade dervid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Då stod jag upp, att jag skulle låta minom vän upp; mina händer drupo af myrrham, och myrrham lopp öfver mina finger på stängelen åt låset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Och då jag minom vän upplåtit hade, var han borto, och sin väg gången. Då gick min själ ut efter hans ord; jag sökte honom, men jag fann honom intet; jag ropade, men han svarade mig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Väktarena, som omkringgå i stadenom, funno mig, de slogo mig till sårs; väktarena på murenom togo mig bort mitt hufvudkläde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Jag besvär eder, Jerusalems döttrar; finnen I min vän, så säger honom, att jag för älskog krank ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Hvad är din vän för andra vänner, o du aldradägeligasta ibland qvinnor? Hvad är din vän för andra vänner, att du så hafver besvorit oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Min vän är hvit och röd, utkorad ibland mång tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Hans hufvud är det bästa guld; hans hår är krusadt, svart såsom en korp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Hans ögon äro såsom dufvoögon vid vattubäcker, tvagne med mjölk, och stå full.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Hans kinder äro såsom apothekares växande örtesängar; hans läppar äro såsom roser, de der drypa af flytande myrrham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Hans händer äro såsom guldringar, fulle med turkoser; hans lif är såsom rent elphenben, besatt med saphirer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Hans ben äro såsom marmors pelare, grundade uppå gyldene fötter; hans skapnad är såsom Libanon, utkorad såsom cedreträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Hans hals är söt och ganska lustig: En sådana är min vän; min vän är sådana, I Jerusalems döttrar. Hvart är då din vän gången, o du dägeligasta ibland qvinnor? Hvart hafver din vän vändt sig, så vilje vi honom söka med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Min vän är nedergången uti sin örtagård, till örtasängarna, att han sig der förlusta skall i örtagårdarna, och hemta roser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Min vän är min, och jag är hans, den sig ibland roser förlustar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Du äst dägelig, min kära, såsom Thirza; lustig såsom Jerusalem, förskräckelig såsom en härordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Vänd din ögon ifrå mig, förty de göra mig brinnande; ditt hår är såsom en getahjord, de som på berget Gilead klippte äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Dine tänder äro såsom en fårahjord, de der tvagne komma utu vatten, hvilke allesammans äro med tvillingar hafvande, och ingen ibland dem är ofruktsam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Dine kinder äro såsom skörden på granatäplet, emellan dina lockar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Sextio äro Drottningarna, och åttatio frillorna, och på jungfrurna är intet tal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Men en är min dufva, min fromma; en är sine moder kärast, och sine moders utkorada. Då döttrarna sågo henne, prisade de henne saliga; Drottningarna och frillorna lofvade henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Ho är denna, som uppgår såsom en morgonrodne, dägelig såsom månen, utkorad såsom solen, förskräckelig såsom en härordan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Jag är nedergången i nöttagården, till att skåda telningarna vid bäcken; till att skåda, om vinträt blomstrades, om granatäplen grönskades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Min själ visste icke, att han mig intill AmmiNadibs vagnar satt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Vänd om, vänd om, o Sulamith; vänd om, vänd om, att vi måge skåda dig; hvad sen I på Sulamith annat, än dans i Mahanaim?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Huru dägelig är din gång i skorna, du Förstas dotter! Dina länder stå lika vid hvarandra, såsom tu spann, de ens mästares hand gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Din nafle är såsom en rund skål, den aldrig dryck fattas; din buk är såsom en hvetehop, omsatt med roser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Din tu bröst äro såsom två unge råtvillingar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Din hals är såsom ett elphenbenstorn, din ögon äro såsom de dammar i Hesbon vid den porten Bathrabbim; din näsa är såsom tornet af Libanon, hvilket sig vänder emot Damascon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Ditt hufvud står på dig såsom Carmel; håret på ditt hufvud är såsom Konungens purpur i fållar bunden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Huru dägelig och huru ljuflig äst du, kära, i vällust!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Din längd är lik vid ett palmträ; och din bröst vid vindrufvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Jag sade: Jag måste stiga upp i palmträt, och fatta dess qvistar; låt din bröst vara såsom drufvor på vinträ, och lukten af dine näso såsom äple;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Och din hals såsom godt vin, det minom vän lätteliga ingår; och tala om gammal ärende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Min vän är min, och han håller sig ock till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Kom, min vän, låt oss gå ut på markena, och vistas i landsbyarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Att vi måge bittida uppstå till vingårdarna, och få se, om vinträt blomstras, och hafver fått knoppar; om de granatäple utgångne äro; der vill jag gifva dig min bröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Liljorna gifva sin lukt, och för våra dörr allahanda ädla frukter; min vän, jag hafver bevarat åt dig både nytt och gammalt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'O! att jag måtte finna dig ute, min broder, du, som mins moders bröst suger, och måtte få kyssa dig; att ock ingen föraktade mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Jag ville taga dig, och hafva dig uti mine moders hus, der du mig lära skulle; der ville jag skänka dig kryddadt vin, och must af min granatäple.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Hans venstra hand ligger under mitt hufvud, och hans högra hand omfamnar mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Jag besvär eder, Jerusalems döttrar, att I icke uppväcken mina käro, eller omaken henne, tilldess henne sjelf lyster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Ho är denna, som uppkommer ifrån öknene, och stöder sig in uppå sin vän? Under äpleträt väcker jag dig, der din moder dig födt hafver; der hon, som dig födde, med dig legat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Sätt mig såsom ett insegel på ditt hjerta, och såsom ett insegel uppå din arm; ty kärleken är stark såsom döden, och nitälskan är fast såsom helvetet; dess glöd är brinnande, och en Herrans låge;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Så att ock mycket vatten icke förmå utsläcka kärleken, eller strömmar fördränka honom; om en ville gifva alla ägodelar i sino huse för kärleken, så gulle det alltsammans intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Vår syster är liten, och hafver ingen bröst; hvad skole vi göra till vår syster, när man nu skall tala henne till?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Är hon en mur, så vilje vi göra silfverbålverk deruppå; är hon en dörr, så vilje vi befästa henne med cedrebräde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Jag är en mur, och min bröst äro såsom torn, deraf är jag vorden för hans ögon såsom den der frid finner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomo hafver en vingård i BaalHamon; den vingården fick han vaktarom, att hvardera skulle gifva, för hans frukt, tusende silfpenningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Min vingård är för mig. Dig Salomo bör tusende; men vaktaromen öfver hans frukter, tuhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Du, som bor i örtagårdarna, sällskapen akta deruppå; låt mig höra dina röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Fly, min vän, och var lik ene rå, eller enom ungom hjort, in på örtabergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Detta är Esaia syn, Amos sons, den han såg om Judo och Jerusalem, uti Ussia, Jothams, Ahas och Jehiskia, Juda Konungars, tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Hörer, I himlar, och du jord, fattat med öronen; ty Herren talar: Jag hafver uppfödt barn, och upphöjt, och de äro mig affällige vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'En oxe känner sin herra, och en åsne sins herras krubbo; men Israel känner det intet, och mitt folk förstår det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ack! ve det syndiga folket; det folket af stor misshandel, den arga säden, de skadeliga barnen, som öfvergifva Herran, försmäda, den Heliga i Israel, och vända tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Hvad skall man mer slå eder, medan I afviken ju desto mer? Hela hufvudet är krankt, hela hjertat är försmäktadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Ifrå fotbjellet allt upp till hufvudet är der intet helt uppå; utan sår, svullnad och etterböld, de der intet plåstrade, eller förbundne, eller med olja mökte äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Edart land är öde; edra städer äro uppbrände med eld; främmande förtära eder åker för edor ögon, och han är öde, såsom det de främmande förhärjat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Men hvad ännu qvart är af dottrene Zion, det är lika som en hydda uti enom vingård, och såsom en vaktebod uti stubbåkren; såsom en förhärjad stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Om Herren Zebaoth icke läte oss något litet igenblifva, så vore vi lika som Sodom, och lika som Gomorra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Hörer Herrans ord, I Sodomitiske Förstar; fatta med öronen vår Guds lag, du Gomorriska folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Hvad skall jag med edart myckna offer? säger Herren; jag är mätt af vädrars bränneoffer, och af de göddas talg, och hafver ingen lust till oxars, lambars och bockars blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Då I kommen in till att te eder för mig; ho äskar sådant af edra händer, att I skullen träda in uppå mina gårdar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Hafver icke mer spisoffer fram fåfängt; rökverk är mig styggeligit; nymånader och Sabbather, då I sammankommen, må jag icke lida; ty I bedrifven afguderi och våld i dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Min själ hatar edra nymånadar och årstider; jag är ledse dervid, jag orkar icke lida dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Och om I än uträcken edra händer, så bortgömmer jag dock min ögon ifrån eder; och om I än mycket bedjen, så hörer jag eder dock intet; ty edra händer äro fulla med blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Tvår eder, görer eder rena, lägger bort edart onda väsende ifrå min ögon; vänder igen af det onda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Lärer göra det godt är, farer efter det som rätt är, hjelper dem förtryckta, skaffer dem faderlösa rätt, och hjelper enkones sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Så kommer då sedan, och låter oss gå med hvarannan till rätta, säger Herren: Om edra synder än voro blodröda, så skola de dock varda snöhvita; och om de än voro såsom rosenfärga, så skola de dock varda såsom en ull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Viljen I höra mig, så skolen I nyttja landsens goda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Viljen I ock icke, utan ären ohörsamme, så skolen I af svärd förtärde varda; ty Herrans mun säger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Huru kommer det till, att den fromme staden är vorden en sköka? Han var full med rätthet, rättvisan bodde derinne; men nu mördare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Ditt silfver är vordet slagg, och ditt vin förmängdt med vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Dine Förstar äro affällige, och tjufvars stallbröder; de taga alle gerna gåfvor, och fara efter skänker; dem faderlösa skaffa de icke rätt, och enkones sak kommer intet inför dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Derföre säger Herren, Herren Zebaoth, den mäktige i Israel: Ack ve! Jag måste trösta mig igenom mina fiendar, och hämna mig igenom mina ovänner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Och måste vända mina hand emot dig, och utrensa ditt slagg som aldrarenast, och borttaga allt ditt tenn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Och gifva dig åter domare igen, såsom de voro tillförene, och rådherrar, såsom i begynnelsen; då skall du heta rättvisones stad, och en from stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Zion måste igenom rätt förlossad varda, och hans fångar igenom rättfärdighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Att de öfverträdare och syndare skola tillsamman sönderkrossade varda, och de, som öfvergifva Herran, förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Ty de måste komma på skam öfver de ekar, der I lust till hafven, och blygas öfver de lustgårdar, som I utväljen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'När I varden såsom en ek med torr löf, och såsom en lustgård utan vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'När beskärmet varder såsom blår, och dess verk såsom en gnista; och både tillhopa brinnen, så att ingen utsläcker det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Detta är det Esaia, Amos son, såg om Juda och Jerusalem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Uti yttersta tiden skall det berget, der Herrans hus är, tillredt varda, högre än all berg, och öfver all berg upphöjdt varda; och alle Hedningar skola löpa dertill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Och mycket folk gå dit, och säga: Kommer, och låter oss gå upp på Herrans berg, till Jacobs Guds hus, att han lärer oss sina vägar, och vi vandrom på hans stigar; ty af Zion skall lagen utgå, och Herrans ord af Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Och han skall döma ibland Hedningarna, och straffa mång folk; då skola de göra sin svärd till plogbillar, och sin spjut till liar; ty intet folk skall upplyfta svärd emot det andra, och skola nu intet lära mer att örliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Kommer, I af Jacobs hus, låt oss vandra uti Herrans ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Men du hafver låtit fara ditt folk, Jacobs hus; ty de bedrifvat mer än de österländningar, och äro dagaväljare såsom de Philisteer; och låta de främmande barn varda mång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Deras land är fullt med silfver och guld, och på deras rikedom är ingen ände; deras land är fullt med hästar, och på deras vagnar är ingen ände.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Deras land är också fullt med afgudar, och de tillbedja sitt handaverk, det deras finger gjort hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Der bugar den menige man, der ödmjuka sig de myndige; det varder du icke förlåtandes dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Gack in uti bergen, och bortgöm dig uti jordene, för Herrans fruktan, och för hans härliga majestät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Förty all hög ögon skola förnedrad varda, och hvad högt är ibland menniskor, det måste bocka sig; men Herren skall på den tid allena hög vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Ty Herrans Zebaoths dag skall gå öfver allt högfärdigt och högt, och öfver allt upphäfvet, att det skall förnedradt varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Och öfver all hög och upphäfven cedreträ i Libanon, och öfver alla ekar i Basan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Öfver all hög berg, och öfver alla upphöjda backar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Öfver all hög torn, och öfver alla fasta murar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'Öfver all skepp i hafvet, och öfver all kostelig skepps baner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Att sig böja måste all höghet, och sig ödmjuka hvad högt är ibland menniskorna; och Herren allena hög vara på den tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Och afgudarna skola platt förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Så skall man gå in uti bergskrefvor, och uti jordkulor, för Herrans fruktan, och för hans härliga majestät, då han tager till att förskräcka jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'På den tiden skall hvar och en bortkasta sina silfverafgudar, och gyldene afgudar, som han sig hafver göra låtit till att tillbedja, och till att ära mullvärplar och flädermöss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'På det han må krypa in uti stenklyftor, och i bergskrefvor, för Herrans fruktan, och för hans härliga majestät, då han tager till att förskräcka jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Så befatter eder intet med menniskone, som anda hafver i näsone; ty I veten icke, huru högt han är aktad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Ty si, Herren, Herren Zebaoth skall borttaga, af Jerusalem och Juda, allt uppehälle, bröds uppehälle, vattens uppehälle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Starka och krigsmän; domare, Propheter, spåmän och åldersmän;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Höfvitsmän öfver femtio, och ärliga män; rådmän och visa ämbetsmän, och vältalande män;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Och skall gifva dem ynglingar till Förstar, och barnslige skola råda öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Och plågare skola vara i folkena, den ene öfver den andra, och hvar öfver sin nästa; och den, som yngre är, skall vara stolt öfver den gamla, och en lösaktig emot den ärliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Då skall en fatta sin broder utu sins faders hus: Du hafver kläder, var vår Förste, hjelp du detta ofallet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Men han skall på den tiden svärja, och säga: Jag är ingen läkare; i mino huse är hvarken bröd eller kläder; sätter mig icke till en Första öfver folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Ty Jerusalem faller, och Juda ligger omkull; efter deras tunga och anslag är emot Herranom, så att de hans majestäts ögon emot sträfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'De skyla intet sitt väsende, och berömma sig af sina synder, lika som de i Sodom, och dölja dem intet; ve deras själar; ty dermed föra de sig sjelfva på allt ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Prediker om de rättfärdiga, att de stå väl; ty de skola äta sina gerningars frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Men ve dem ogudaktigom; ty de äro onde, och det skall varda dem betaladt, lika som de det förtjena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Barn äro mins folks plågare, och qvinnor råda öfver dem. Mitt folk, dine ledare förföra dig, och förderfva vägen den du gå skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Men Herren står der, till att gå till rätta, och är framgången till att döma folken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Och Herren kommer till domen med sins folks äldsta, och med sina Förstar; ty I hafven förderfvat vingården; och rofvet ifrå de fattige är i edart hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Hvi förtrampen I mitt folk, och förkrossen dens fattigas person, säger Herren, Herren Zebaoth?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Och Herren säger: Derföre, att Zions döttrar äro stolta, och gå med rakom hals, med färgadt ansigte; gå och svansa, och hafva kosteliga skor på sina fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Så skall Herren göra Zions döttrars hufvud skallot; och Herren skall bortrycka deras sköna hår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'På den tiden skall Herren borttaga prydningen af de kosteliga skor, och häkter, spänne,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Kedjor, armspänne, hufvor,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Flitter, bräm, snöre, desmoknappar, öronspann,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Ringar, ännespann,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Högtidskläder, kåpor, hvifvar, pungar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Speglar, snöretröjor, bordor och sommarkläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Och der skall vara stank för goda lukt, och ett löst band för bälte, och ett skallot hufvud för krusadt hår, och för en vid mantel en trång säck; allt detta i staden för din dägelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Ditt meniga folk skall falla genom svärd, och dine krigsmän i strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Och hans portar skola sörja och gräma sig, och han skall sitta jämmerliga på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Och på den tiden skola sju qvinnor fatta en man, och säga: Vi vilje sjelfva föda och kläda oss, allenast låt oss nämnas efter ditt namn, att vår försmädelse må ifrån oss tagen varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Uti den tiden skall Herrans Telning vara kär och kostelig, och jordenes Frukt härlig och skön med dem som behållne blifva i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Och hvilken i Zion återlefves, och igenblifver i Jerusalem, han skall kallas helig, hvar och en som skrifven är ibland de lefvande i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Då varder Herren aftvåendes Zions döttrars smitto, och fördrifvandes Jerusalems blodskulder derut, genom Andan, som döma och en eld upptända skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Och Herren skall skapa öfver alla Zions bergs boningar, och hvar som helst det församladt är, moln och rök om dagen, och sken af eld, som brinner om nattena; ty en skärm skall vara öfver allt det härligit är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Och ett skjul skall varda till en skygd om dagen för hettanom, och en tillflykt till att gömma sig för storm och regn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Nu väl, jag vill sjunga minom vän ens mins väns viso om hans vingård. Min vän hafver en vingård, på ett fett rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Och han gärde omkring honom, och med stenhopar bevarade, och satte ädla vinträ deruti; han byggde ock ett torn deruti, och grof der en press, och vänte efter, att han skulle bära vindrufvor; men han bar vilddrufvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Nu dömer, I Jerusalems inbyggare, och I Juda män, emellan mig och min vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Hvad skulle man dock mer göra minom vingård, det jag honom icke gjort hafver? Hvi hafver han burit vilddrufvor, då jag vänte efter, att han skulle burit drufvor?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Nu väl, jag vill kungöra eder, hvad jag minom vingård göra vill: Hans gård skall borttagen varda, på det han skall ödelagd blifva, och hans mur skall sönderrifven varda, på det han skall förtrampad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Jag skall låta honom ligga öde, att ingen skall skäran eller grafvan, utan tistel och törne derinne växa; och skall bjuda skyarna, att de icke regna deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Så är nu Herrans Zebaoths vingård Israels hus, och Juda män hans lustiga plantering; han vänter efter rätt, si, så är här icke annat än öfvervåld; efter rättviso, si, så är här alltsammans klagomål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Ve dem som draga det ena huset intill det andra, och komma den ena åkren intill den andra, tilldess att intet rum mer är, att de skola besitta landet allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Det är för Herrans Zebaoths öron; hvad gäller, om de många hus icke skola öde varda, och de stora och sköna utan inbyggare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Ty tio vingårdsfjällar skola icke gifva mer än ett åm, och en tunna säd skall icke gifva utan ena skäppo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Ve dem som om morgonen bittida uppe äro, till att beflita sig om dryck, och sitta intill nattena, att de af vin hete varda skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Och hafva harpor, psaltare, trummor, pipor och vin, i deras collats; och se intet uppå Herrans verk, och akta intet uppå hans händers gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Derföre måste mitt folk varda bortfördt oförvarandes, och deras härlige hunger lida, och deras meniga folk törst lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Derföre hafver helvetet utvidgat sina själ, och uppgapat med sina käftar utan, måtto, att nederfara skola både deras härlige och den menige man, både deras rike och glade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Att hvar och en skall bocka sig, och hvar och en ödmjukad varda, och de högfärdigas ögon ödmjukad blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Men Herren Zebaoth uppböjd varda i domenom, och Gud, den Helige, helgad varda i rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Så skola då lamb i bet gå i deras stad, och främlingar skola sig nära uti de fetas öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Ve dem som kobbla sig tillhopa, med fåfängelig band, till att göra orätt, och lika som med vagnsrep, till att synda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Och säga: Låt hans verk skynda sig och snart komma, att vi måge set; låt dens Heligas i Israel anslag nalkas och komma, att vi måge vetat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Ve dem som kalla det onda godt, och det goda ondt; de der af mörkret ljus göra, och af ljuset mörker; de der göra sött af sura, och surt af söto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Ve dem som för sig sjelfva vise äro, och hålla sig sjelfva för kloka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Ve dem som hjeltar äro till att dricka vin, och kämpar till att dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'De der gifva den ogudaktiga rätt för gåfvors skull, och vända de rättfärdigas rätt ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Derföre, lika som eldslåge förtärer halm, och borttager agnar, alltså skall deras rot förruttna, och deras telningar bortflyga såsom stoft; förty de förakta Herrans Zebaoths lag, och försmäda dens Heligas ord i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Derföre förgrymmar sig Herrans vrede öfver hans folk, och uträcker sina hand öfver dem, och slår dem, så att bergen bäfva, och deras kroppar äro lika som träck på gatone; och uti allt detta vänder icke hans vrede åter, utan hans hand är ännu uträckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Ty han skall uppresa ett baner fjerran ibland Hedningarna, och locka dem ifrå jordenes ända; och si, hastigt och snarliga komma de;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Och ingen ibland dem är trött eller svag; ingen är sömnig eller sofver; ingom lossas bältet af hans länder, och ingen sliter en skorem sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Deras pilar äro skarpe, och alle deras bågar spände; deras hästahofvar äro såsom stenar, och deras hjul såsom ett stormväder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'De ryta som lejon, och ryta som ung lejon; de skola fräsa, och taga rof, och behållat, så att ingen undsätter det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Och skall på den tiden fräsa öfver dem lika som ett haf; när man då ser uppå landet, så är det mörkt af ångest, och ljuset skin intet mer för mörkrets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Uti det året, då Konung Ussia blef död, såg jag Herran sitta på en hög och härlig stol, och hans klädefåll uppfyllde templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Seraphim stodo öfver honom, hvardera hade sex vingar; med två betäckte de sitt anlete; med två betäckte de sina fötter, och med två flögo de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Och den ene ropade till den andra, och sade: Helig, Helig, Helig är Herren Zebaoth; hela jorden är full med hans äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Så att öfre dörrstocken bäfvade af deras rops röst, och huset vardt fullt med rök.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Då sade jag: Ve mig, jag förgås; ty jag hafver orena läppar, och bor ibland ett folk som orena läppar hafver; ty jag hafver sett Konungen, Herran Zebaoth, med min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Då flög en af Seraphim till mig, och hade ett glödande kol uti handene, det han med en tång tog af altaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Och kom vid min mun, och sade: Si, härmed hafver jag kommit vid dina läppar, att din missgerning skall varda ifrå dig tagen, och din synd försonad vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Och jag hörde Herrans röst, att han sade: Hvem skall jag sända? Hvilken vill vara vårt bådskap? Men jag sade: Här är jag, sänd mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Och han sade: Gack åstad, och säg till detta folket: Hörer, och förstår det icke; ser, och märker det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Förstocka detta folks hjerta, och låt deras öron lomhörd varda, och förblinda deras ögon, att de intet se med sin ögon, eller höra med sin öron, eller förstå med sitt hjerta, och omvända sig, och varda salige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Men jag sade: Herre, huru länge? Han sade: Tilldess, att städerna öde varda utan inbyggare, och husen utan folk, och marken ligger platt öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Ty Herren skall låta folket komma, långt bort, så att landet skall svårliga öfvergifvet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Dock skall ännu tiondedelen blifva derinne; ty det skall varda bortfördt och förhärjadt, såsom en ek och lind, som ännu hafva bålen, ändock deras löf afslagne, varda; en helig säd skall sådana bål vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Det begaf sig uti Ahas, Jothams sons, Ussia sons, Juda Konungs, tid, drog Rezin, Konungen i Syrien, och Pekah, Remalia son, Israels Konung, upp till Jerusalem, till att örliga deremot; men de kunde intet öfvervinna det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Då vardt Davids huse sagdt: De Syror förlåta sig uppå Ephraim. Då bäfvade honom hjertat, och hans folks hjerta, lika som trän i skogenom bäfva för vädret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Men Herren talade till Esaia: Gack ut emot Ahas, du och din son SearJasub, till ändan af vatturännone vid öfra dammen, på den vägen vid färgarens åker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Och säg till honom: Vara dig, och blir stilla, frukta dig intet, och ditt hjerta vare oförskräckt för dessa två rykande släckebrandar; nämliga för Rezins och de Syrers, och Remalia sons vrede;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Att de Syror hafva gjort ett ondt rådslag emot dig, samt med Ephraim och Remalia son, och säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Vi vilje upp till Juda, och förskräcka honom, och skifta oss emellan, och göra Tabeels son till Konung derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Ty så säger Herren, Herren: Det skall intet så bestå eller så ske;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Utan lika som Damascus är hufvudet i Syrien, så skall Rezin vara hufvudet i Damasco. Och efter fem och sextio år skall det vara ute med Ephraim, att de icke mer skola vara något folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Och lika som Samarien är hufvudet i Ephraim, så skall Remalia son vara hufvudet i Samarien. Tron I icke, så felar det med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Och Herren talade åter till Ahas, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Äska dig ett tecken af Herranom, dinom Gud, antingen nedre i helvetet, eller ofvantill i höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Men Ahas sade: Jag äskar intet, att jag icke skall försöka Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Då sade han: Nu väl, så hörer I af Davids hus; är det eder litet, att I gören menniskom emot, utan att I ock gören min Gud emot?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Derföre skall Herren sjelf gifva eder ett tecken; si, en Jungfru är hafvandes, och skall föda en son, den skall hon kalla ImmanuEl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Smör och hannog skall han äta, att han skall veta förkasta det onda, och utvälja det goda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Ty förr än pilten lärer förkasta det ondt är, och utvälja det godt är, skall det land, der du grufvar dig före, öfvergifvet varda af sina två Konungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Men öfver dig, öfver ditt folk och öfver dins faders hus, skall Herren, genom Konungen af Assyrien, komma låta dagar, de icke komne äro, sedan Ephraim ifrå Juda skiljdes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Ty på den tiden skall Herren hvissla till flugorna vid ändan på Egypti älfver, och till bin i Assurs land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Att de skola komma, och allesammans lägga sig vid bäcker och stenklyftor, och all hål trä, och uti all hål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'På den samma tiden skall Herren raka hufvudet, och håret af fötterna, och taga bort skägget genom en lejd rakoknif; nämliga genom dem som på hinsidon älfvena äro, det är, genom Konungen af Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'På den samma tiden skall en man föda en hop kor, och två hjordar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Och skall hafva så mycket till att molka, att han smör äta skall; ty den som i landens igenlefves, han skall äta smör och hannog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Ty det skall ske på den tiden, att der nu tusende vinträd stå, tusende silfpenningar värd, der skall vara törne och tistel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Så att man måste gå dit med pil och båga; ty uti hela landet skall törne och tistel vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Så att man icke komma kan till alla de berg, som man plägar uppgrafva med hacko, för tistlars och törnes styggelses skull; utan man skall låta oxar gå deruppå och får deröfver trampa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Och Herren sade till mig: Tag dig ett stort bref, och skrif deruti med en menniskos styl: Röfva snart; hasta till byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Och jag tog till mig tu trogen vittne, Presten Uria, och Zacharia, Jeberechia son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Och gick till ena Prophetisso; hon vardt hafvandes, och födde en son; och Herren sade till mig: Kalla honom: Röfva snart; hasta till byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Ty förr än pilten skall kunna säga: Käre fader, kära moder; skall Damascos magt och Samarie byte borttaget varda, genom Konungen af Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Och Herren talade ytterligare med mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Efter detta folket föraktar det vattnet i Siloa, hvilket så stilla löper, och tröster uppå Rezin och Remalia son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Si, så skall Herren låta komma öfver dem starkt och mycket strömvatten; nämliga Konungen af Assyrien, och all hans härlighet, att de skola fara öfver alla deras bäcker, och gå öfver alla deras stränder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Och skola infalla uti Juda, och flöda, och gå öfver, tilldess att de räcka upp till halsen; och skola utsträcka sina vingar, så att de uppfylla ditt land, o ImmanuEl, så vidt som det är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Varer vrede, I folk, och gifver likväl flyktena; hörer, I alle som ären i fjerran land, ruster eder, och gifver dock flyktena; ruster eder, och gifver dock flyktena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Besluter ett råd, och der varde intet af, talens vid, och det bestå intet; ty här är ImmanuEl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Ty så säger Herren till mig, lika som han fattade mig vid handena, och underviste mig, att jag icke skulle vandra på detta folks väg, och säger:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'I skolen icke säga: Förbund. Detta folk talar om intet annat, utan om förbund. Frukter eder icke såsom de göra, och grufver eder icke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Utan helger Herran Zebaoth; honom låter vara edor fruktan och förskräckelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Så skall han varda en helgelse; men en stötesten och en förargelseklippa dem tvem Israels husom, Jerusalems inbyggarom till snaro och fall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Så att månge af dem skola derpå stöta sig, falla och sönderkrossas, besnärjas och fångne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Bind samman vittnesbördet; försegla lagen intill mina lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Ty jag hoppas uppå Herran, den sitt anlete för Jacobs hus bortgömt hafver; men jag vänter efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Si, här är jag, och barnen som Herren mig gifvit hafver, till ett tecken och under i Israel, af Herranom Zebaoth, den der bor på bergena Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Men då de säga till eder: I måsten fråga af spåmän och tecknatydare, de der mycket tala och disputera, så skolen I säga: Skall icke ett folk fråga sin Gud? Skall man fråga de döda om de lefvande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Ja, efter lag och vittnesbörd; om de det icke säga, så skola de icke få morgonrodnan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Utan skola gå, omkring i landena slagne och hungroge; men när de hunger lida, så skola de vrede varda, och banna sinom Konung och sinom Gud, och se upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'De skola ock se neder på Jordena, och intet finna annat än bedröfvelse och mörker; ty de äro förmörkrade i ångest, och gå ville i mörkret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Ty det varder väl ett annat mörker, det dem bekymrar, än i förtiden var, då det lätteliga tillgick i Sebulons land, och i Naphthalims land, och derefter svårare vardt vid hafsvägen, på denna sidone Jordanen, vid Hedningarnas Galilea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Det folket, som i mörkret vandrar, ser ett stort ljus; och öfver dem, som bo i mörko lande, skin det klarliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Du gör folket mycket, dermed gör du icke glädjena, myckna; men för dig varder man sig glädjandes, såsom man glädes i skördandene, såsom man glad är, när man utskifter byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Ty du hafver sönderbrutit deras bördos ok, och deras skuldrors ris, och deras plågares staf, lika som i Midians tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Ty allt krig, med storm och blodig klädnad, skall uppbrännas, och af eld förtärdt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Ty oss är födt ett barn, en Son är oss gifven, hvilkens herradöme är uppå hans axlar; och han heter Underlig, Råd, Gud, Hjelte, Evig Fader, Fridförste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'På det hans herradöme skall stort varda, och på friden ingen ände, på Davids säte och hans rike, att han det bereda, och stärka skall med dom och rättfärdighet, ifrå nu allt intill evighet; detta skall Herrans Zebaoths nitälskan göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Herren hafver sändt ett ord i Jacob, och det är fallet i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Att allt Ephraims folk och Samarie inbyggare skola det få veta, hvilke i högmod och stolt sinne säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Tegelstenar äro fallne; men vi vilje bygga det upp igen med huggen sten; man hafver afhuggit mulbärsträ, så vilje vi sätta i samma staden cedreträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Ty Herren skall uppresa Rezins krigsfolk emot dem, och gadda deras fiendar tillhopa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'De Syrer före, och de Philisteer efter, att de skola uppfräta Israel med fullom mun. Uti allt detta stillas icke ännu hans vrede; hans hand är ännu uträckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Så vänder sig ej heller folket till honom, som dem slår, och fråga intet efter Herran Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Derföre skall Herren afhugga af Israel både hufvud och stjert, både qvist och stubbs, på en dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'De gamle och ärlige äro hufvudet; men Propheterna, som falskt lära, äro stjerten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Ty detta folks ledare äro förförare; och de som sig leda låta, äro förtappade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Derföre kan Herren intet glädja sig öfver deras unga män, eller förbarma, sig öfver deras faderlösa och enkor; ty de äro allesammans skrymtare och onde, och hvar och en mun talar galenskap. Uti allt detta stillas icke ännu hans vrede; hans hand är ännu uträckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Ty det ogudaktiga väsendet är upptändt såsom en eld, och förtärer törne och tistlar, och brinner såsom uti en tjock skog, och gifver högan rök.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Förty uti Herrans Zebaoths vrede är landet förmörkradt, så att folket är lika, som en eldsmat; ingen skonar den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Röfva de på högra sidone, så lida de hunger; äta de på venstra sidone, så varda, de icke mätte; hvar och en äter sins arms kött;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manasse Ephraim, Ephraim Manasse, och de båda, tillsammans emot Juda. Uti allt detta stillas icke ännu hans vrede; hans hand är ännu uträckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Ve dem Skriftlärdom, som orätt lag göra, och vrångan dom skrifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'På det de skola vränga dens fattigas sak, och bruka våld uti de eländas rätt i mitt folk; så att enkor måste vara deras rof, och de faderlöse deras byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Hvad viljen I göra på hemsökningenes och olyckones dag, den fjerran efter kommer? Till hvem viljen I fly om hjelp? Och hvar viljen I låta edra äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Att hon icke under de fångna böjd varder, och ibland slagna faller? Uti allt detta är hans vrede icke stillad; hans hand är ännu uträckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Ack! ve Assur, den mine vredes ris, och deras hand mine grymhets staf är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Jag vill sända honom emot ett skrymtaktigt folk, och gifva honom befallning emot mine vredes folk, att han det skinna och utbyta skall, och förtrampa det såsom träck på gatone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Ändock han det så icke menar, och hans hjerta så icke tänker; utan hans hjerta står till att förderfva och utrota mång folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Ty han säger: Äro icke mine Förstar allesammans Konungar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Är icke Calno såsom Charchemis? Är icke Hamath såsom Arphad? Är icke Samarien såsom Damascus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Såsom min hand funnit hafver afgudarnas Konungarike; ändock deras afgudar starkare voro, än de i Jerusalem och Samarien äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Skulle jag icke göra Jerusalem och dess afgudom, såsom jag Samarien och dess afgudom gjort hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Men när Herren hafver all sin verk uträttat på Zions berg och i Jerusalem, så vill jag hemsöka den högmodiga Konungens frukt af Assyrien, och hans högfärdiga ögons prål;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Derföre, att han säger: Jag hafver uträttat det med mina händers kraft och igenom mina vishet; ty jag är klok. Jag hafver annorlunda delat landen, och deras ägodelar röfvat, och såsom en väldig slagit deras inbyggare till jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Och min hand hafver funnit folken, lika som ett hönonäste, så att jag hafver all land tillhopasamlat, lika som man församlar ägg, som öfvergifne äro; der ingen ena fjäder rörer, eller upplåter sitt näf, eller korrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Kan ock en yxe berömma sig emot honom, som hugger med henne; eller en såg trugas emot honom, som drager henne? Såsom den sig berömma kan, den en käpp bär, och upplyfter och bär honom så lätteliga, som han intet trä vore.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Derföre skall Herren, Herren Zebaoth sända en magerhet ibland hans feta, och skall upptända hans härlighet, att hon skall brinna såsom en eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Och Israels ljus skall varda en eld, och hans helige skall varda en låge; och skall upptända och förtära hans törne och tistlar på en dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Och hans skogs och marks härlighet skall till intet blifva både själ och kropp, och skall förgås och försvinna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Så att hans skogs återlefda trä måga räknad varda, att ett barn må uppskrifva dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'På den tiden skola de igenlefde i Israel, och de som af Jacobs hus behållne blifva, icke mer förlåta sig uppå honom, som dem slår; utan skola förlåta sig uppå Herran, den Heliga i Israel, uti sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'De igenlefde skola omvända sig, ja de igenlefde i Jacob, till Gud den starka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Ty om ditt folk, o Israel, är lika som sanden i hafvet, så skola dock de igenlefde af dem omvände varda; ty då förderfvet stilladt varder, så skall öfversvinnande stor rättfärdighet komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Ty Herren, Herren Zebaoth skall låta gå ett förderf; men han stillar det dock i hela landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Derföre säger Herren, Herren Zebaoth: Frukta dig icke, mitt folk, som i Zion bor, för Assur; han skall slå dig med ris, och upplyfta sin staf emot dig, såsom uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Ty efter en ganska liten tid skall ogunsten och min vrede öfver deras odygd få en ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Då skall Herren Zebaoth uppväcka en gissel öfver dem, lika som uti Midians slagtning på det hälleberget Oreb; och skall upphäfva sin staf, den han på hafvet brukade, lika som uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'På den tiden skall hans börda bortvika ifrå dina skuldror, och hans ok ifrå dinom hals; ty oket skall förruttna af fetma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Han kommer till Ajath, han drager igenom Migron; han mönstrar sin här i Michmas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'De draga framom vårt lägre Geba; Rama förskräckes; Gibeath Sauls flyr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Du dotter Gallim, ropa högt; se till, du Laisa, du elända Anathoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena viker undan; de borgare i Gebim löpa sin kos.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Man blifver tilläfventyrs en dag i Nob, så skall han vända sina hand till dottrenes Zions berg, och emot den högen Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Men si, Herren, Herren Zebaoth skall afhugga qvistarna med magt, och afstäcka det högt står, så att de höge skola förnedrade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Och den tjocke skogen skall med jern omkullhuggen varda, och Libanon skall falla genom den mägtiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Och ett Ris skall uppgå, utaf Isai slägte, och en Telning utaf hans rot frukt bära;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'På hvilkom skall hvilas Herrans Ande, vishets och förstånds ande, råds och starkhets ande, kunskaps och Herrans fruktans ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Han skall inblåsa honom Herrans fruktan, att han icke skall döma efter som ögonen se, eller straffa efter som öronen höra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Utan skall med rättviso döma de fattiga, och med dom straffa de elända på jordene, och skall slå jordena med sins muns staf, och med sina läppars anda dräpa de ogudaktiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Rättvisa skall vara hans länders bälte, och trohet hans njurars bälte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Ulfvar skola bo tillsammans med lamb, och parder ligga ibland kid; en liten dräng skall tillhopa drifva kalfvar, och ung lejon, och gödeboskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Kor och björnar skola gå i bet, och deras ungar tillhopa ligga, och lejonen skola äta halm, såsom oxar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Och ett spenabarn skall lust hafva vid en huggorms hål, och ett afvandt barn skall stinga sina hand uti ena basiliskes kulo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Man skall ingen sarga eller förderfva på mitt helga berg; ty landet är fullt af Herrans kunskap, lika som med hafsens vatten betäckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Och det skall ske på den tiden, att Isai rot, som står till folks baner, der skola Hedningarna fråga efter, och hans hvila skall vara ära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Och Herren skall på den tiden än en gång uträcka sina hand, att han skall få det återlefda af sitt folk, det qvart blifvet är för de Assyrier, Egyptier, Pathros, Ethioper, Elamiter, Sinear, Hamath, och för hafsens öar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Och skall uppresa ett baner ibland Hedningarna, och sammanhemta de fördrefna af Israel, och församla de förskingrada af Juda, af fyra jordenes ändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Och det nit emot Ephraim skall återvända, och Juda fiender skola utrotade varda, så att Ephraim icke hatar Juda, och Juda icke skall vara emot Ephraim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Men de skola vara de Philisteer på halsen vesterut, och beröfva alla de som österut bo; Edom och Moab skola gå dem tillhanda; Ammons barn skola hörsam vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Och Herren skall tillspillogifva hafsens ström uti Egypten, och skall låta gå sina hand öfver älfvena med starkt väder, och slå de sju strömmar, så att man må gå torrskodd deröfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Och skall vara dem qvarlefdom af sitt folk, som igenblifvet är för de Assyrier, en väg; såsom Israel skedde på den tiden, de utur Egypti land drogo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'På den tiden skall du säga: Jag tackar dig, Herre, att du hafver varit vred på mig; och din vrede hafver sig vändt, och du tröster mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Si, Gud är min helsa; jag är säker, och fruktar mig intet; ty Herren Gud är min starkhet och min psalm, och är min helsa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'I skolen ösa vatten med glädje utu helsobrunnomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Och skolen säga på den tiden: Tacker Herranom; prediker hans Namn; görer hans anslag kunnig ibland folken; förkunner, att hans Namn högt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Lofsjunger Herranom; ty han hafver härliga bevist sig; detta vare kunnigt i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Fröjda dig och var glad, du inbyggerska i Zion; ty Israels Helige är stor när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Detta är tungen öfver Babel, som Esaia, Amos son, såg:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Reser upp baner på högo berge; ropar fast emot dem; slår upp handena; låter indraga genom förstarnas portar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Jag hafver budit minom helgedom, och kallat mina starka till mina vrede, hvilke glade äro uti mine härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Der är ett rop af en stor hop på bergomen, såsom af ett stort folk; ett rop lika som en gny af församladt Hedningars rike; Herren Zebaoth rustar en här till strids;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Hvilke utaf fjerran land komma ifrå himmelens ända; ja, Herren sjelfver, samt med sins vredes här, till att förderfva hela landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Jämrar eder; ty Herrans dag är hardt när; han kommer såsom en förödelse af dem Allsmägtiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Derföre skola alla händer nederfalla, och all menniskors hjerta gifva sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Förskräckelse, ångest och värk skall komma dem uppå; de skola hafva vedermödo, såsom en den der barn föder; den ena skall grufva sig vid den andra; röd som en eld skola deras ansigte vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Ty si, Herrans dag kommer grufvelig, vred, grym, till att förderfva landet, och till att förgöra syndarena deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Ty stjernorna på himmelen, och hans Orion skina icke klart; solen går mörk upp, och månen skin mörkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Jag skall hemsöka jordenes krets, för hennes ondskas skull, och de ogudaktiga, för deras odygds skull; och skall göra en ända, uppå de stoltas högmod, och ödmjuka de väldigas högfärd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Så att en man skall dyrare varda än fint guld, och en menniska mer värd än ett stycke guld af Ophir.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Derföre skall jag röra himmelen, så att jorden skall bäfva utaf sitt rum, igenom Herrans Zebaoths vrede, och igenom hans vredes dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Och han skall vara såsom en förjagad rå, och såsom en hjord utan herda; så att hvar och en skall vända till sitt folk igen, och hvar och en fly uti sitt land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Derföre att hvilken sig derinne finna låter, han skall igenomstungen varda, och den der när är, skall igenom svärd falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Skola ock deras barn för deras ögon dräpne varda, deras hus skinnad, och deras hustrur skämda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Ty si, jag skall uppväcka de Meder öfver dem, hvilke intet silfver söka, eller efter något guld fråga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Utan att skjuta de unga män ihjäl med bågar, och icke förbarma sig öfver frukten i moderlifvet, eller barn skona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Alltså skall Babel, det aldraskönesta ibland riken, de Chaldeers härliga prål, omstört varda af Gudi, lika som Sodom och Gomorra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Så att man sedan der intet bo skall, eller någor der blifva i evig tid; att ock de Araber der ingen hyddo göra skola, och de herdar der inga bodar uppsätta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Utan stygge foglar skola der lägga sig, och deras hus full med odjur vara, och strutser skola der bo, och gastar skola der springa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Och ugglor sjunga uti hans palats, och drakar uti de lustiga borger. Och hans tid varder snart kommandes, och hans dagar skola intet dröjas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Ty Herren skall förbarma sig öfver Jacob, och ännu utkora Israel, och sätta dem uti sitt land: och främlingar skola gifva sig till dem, och hålla sig intill Jacobs hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Och folk skola, dem till sig taga, och hafva dem in till sitt rum, så att Israels hus skall äga dem uti Herrans land till tjenare och tjenarinnor; och skola hålla dem fångna, af hvilkom de fångne voro, och skola råda öfver sina plågare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Och på den tiden, då Herren varder dig ro gifvandes ifrå din jämmer och vedermöda, och ifrå den hårda träldom, der du uti varit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Så skall du föra ett sådant ordspråk emot Konungen af Babel, och säga: Huru är det nu ute med plågarenom, och beskattningen hafver en ända?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Herren hafver sönderbrutit de ogudaktigas ris, de väldigas ris;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Den som folk slog i grymhet utan återvändo, och med stränghet rådandes var öfver Hedningarna, och förföljde dem utan barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Nu hafver dock hela verlden ro, och är stilla, och fröjdar sig i glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Ock fröjda sig furoträn öfver dig, och de cedreträ i Libanon (och säga): Efter du ligger, så kommer ingen upp, som oss afhugger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Helvetet dernedre bäfvade för dig, emot din tillkommelse; det uppväcker dig de döda, alla verldenes bockar, och bad alla Hedningarnas Konungar uppstå utaf sina stolar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Att de skulle, en efter den andra, tala, och säga till dig: Du äst ock slagen lika som vi, och dig går lika som oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Ditt prål är neder till helvete faret, samt med dina harpors klingande; mal skall vara din säng, och matkar ditt öfvertäckelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Huru äst du af himmelen fallen, du sköna morgonstjerna? Huru äst du till jordena fallen, du som försvagade Hedningarna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Tänkte du dock uti ditt hjerta: Jag vill stiga upp i himmelen, och förhöja min stol upp öfver Guds stjernor. Jag vill sätta mig på vittnesbördsens berg, på den sidon norrut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Jag vill fara öfver de höga skyar, och vara den Aldrahögsta lik.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Ja, till helvetes far du, vid kulones sida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Den dig ser, han skall skåda dig, och se uppå dig (och säga): Är det den man, som verldena skälfvande gjorde, och Konungariken bäfvande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Den der jordenes krets ödelade, och städerna derinne nederslog, och gaf icke sina fångar lösa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Allesamman Hedningarnas Konungar ligga dock med äro, hvar och en i sitt hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Men du äst förkastad utu dine graf, såsom en förderfvad gren, såsom de slagnas klädnad, som med svärd ihjälstungne äro, hvilke nederfara till helvetes stenar, såsom ett förtrampadt as.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Du skall icke såsom de begrafven varda; ty du hafver förderfvat ditt land, och slagit ditt folk; ty man skall aldrig tänka på den ondskofulla sädena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Reder till, att man må slagta hans barn, för deras fäders missgerningars skull, att de icke uppkomma eller ärfva landet, eller göra jordenes krets fullan med fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Och jag skall öfver dem komma säger Herren Zebaoth, och i Babel utrota hans åminnelse, hans igenlefda, affödo och efterkommande, säger Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Och skall göra honom igelkottom till arfs, och till en vattusjö, och skall sopa honom med förderfvelsens qvast, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Herren Zebaoth hafver svorit, och sagt: Hvad gäller, att det skall så ske som jag tänker, och skall så blifva, som jag i sinnet hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Att Assur nederlagd varder i mitt land, och jag förtrampar honom på min berg; på det hans ok skall af dem taget varda, och hans börda af deras hals komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Detta äro de anslag, som han hafver öfver all land, och det är den uträckta hand öfver alla Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Ty Herren Zebaoth hafver det beslutit; ho vill förmenat? Och hans hand är uträckt; ho kan afvända henne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'I det året, då Konung Ahas blef död, vardt denne tungen sedd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Fröjda dig icke så fast, du Philistea, att det ris, som dig slog, sönderbrutet är; ty utaf ormsens rot skall komma en basilisk, och hans frukt skall vara en brinnande flygande drake.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Ty de torftigas förstfödingar skola berga sig, och de fattige tryggeliga hvila sig; men dina rot vill jag dräpa med hunger, och skall han förgöra dina igenlefda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Jämra dig, du port, ropa, du stad, hela Philistea är förtviflad; ty nordanefter kommer en rök, och ingen ensam är uti hans tjäll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Och hvad varda Hedningarnas båd sägande? Nämliga att Herren hafver grundat Zion, och der skola hans folks elände hafva tillflykt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Detta är tungen öfver Moab: Om nattena kommer förstöring öfver Ar i Moab, det är sin kos; om nattena, kommer förstöring öfver Kir i Moab, det är sin kos.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'De gå upp till Baith och Dibon till altaren, att de skola gråta och jämra sig öfver Nebo och Medba i Moab: All hufvud är rakad, allt skägg är afskuret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'På deras gator gå de omsvepte i säcker; på deras tak och gatom jämra de sig alle, och gå neder gråtande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbon och Eleale ropa, så att man hörer det intill Jahaz; derföre jämra sig de väpnade i Moab, ty deras själ går illa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mitt hjerta ropar till Moab, deras flyktige fly ifrå den treggaåra kon allt intill Zoar; ty de gå upp till Luhith och gråta; och på den vägenom till Horonaim upphäfver sig ett jämmerrop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Ty de vatten i Nimrim torkas bort, så att höet förtorkas der, och gräset förvissnar, och växer ingen grön ört.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Ty de ägodelar, som de församlat, och de folk, som de tillrustat hafva, förer man öfver pilträbäcken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Ropet går omkring uti Moabs gränsor de gråta allt intill Eglaim, och gråta vid den brunnen Elim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Ty de vatten i Dimon äro full med blod; dertill vill jag ännu låta mer komma öfver Dimon, både öfver dem som behållne äro i Moab lejonens, och öfver dem igenlefda i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Sänder ut, I landsherrar, lamb ifrå Sela utur öknene, till dottrenes Zions berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Men såsom en fogel bortflyger, den utaf sitt näste drifven är, så skall det ske med Moabs döttrar, då de draga framom Arnon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Hafver råd tillhopa, håller dom; gör dig middagsskuggan såsom en natt; fördölj de fördrefna, och utrödj icke de flyktiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Låt mina fördrefna hafva herberge när dig; Moab, var du deras skärm för förderfvarenom, så får plågaren en ända, förstöraren vänder åter, och förtramparen låter af i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Men en stol varder tillredd af nåde, att en skall deruppå sitta i sanning, uti Davids hyddo, och döma, och söka efter rätt, och främja rättvisona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Men vi höre af Moabs högmod, att han fast högmodig är, så att ock hans högmod, stolthet och vrede är större, än hans magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Derföre skall en Moabit gråta öfver den andra; allesamman skola de gråta, öfver den stadsens KirHareseths grundvalar skola de halte sucka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Ty Hesbon är vorden en ödemark; vinträt i Sibma är förderfvadt; herrarna ibland Hedningarna hafva förtrampat hans ädla vinträ, och äro komne allt intill Jaeser, och draga omkring uti öknene; hans vinqvistar äro förskingrade, och öfver hafvet förde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Derföre gråter jag för Jaesers skull, och för vinträt i Sibma, och utgjuter många tårar för Hesbon och Eleale; ty en sång är fallen uti din sommar, och uti dina and;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Så att fröjd och glädje återvänder på markene, och i vingårdomen fröjdas eller ropar man intet; man trampar intet vin i pressomen; jag hafver gjort en ända, på sången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Derföre lommar mitt hjerta öfver Moab, såsom en harpa, och mina inelfver öfver KirHares.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Då skall uppenbart varda, huru Moab är ledse vid altaren, och huru han till sina kyrko gången är till att bedja, och hafver dock intet kunnat skaffa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Detta är det Herren på den tiden emot Moab talade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Men nu talar Herren, och säger: Uti tre år, såsom en legodrängs år äro, skall Moabs härlighet, som stor och mycken är, klen varda, så att der skall ganska litet qvart blifva, och icke mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Detta är tungan öfver Damascon: Si, Damascus skall ingen stad nu mer vara, utan en förfallen stenhop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Aroers städer skola, öfvergifne varda, så att hjordar skola der i bet gå, och ingen skall drifva dem ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Och det skall ute vara med Ephraims fäste, och Konungariket i Damasco; och det öfverblefna i Syrien skall vara såsom Israels barnas härlighet, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'På den tiden skall Jacobs härlighet tunn varda, och hans feta kropp skall mager blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Ty han skall varda såsom när en insamlade säd i andene, och såsom när en inbergade ax med sin arm, och såsom en upphemte ax i Rephaims dal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Och en efterhemtning blefve, såsom när man rister ett oljoträ och der tu eller tre bär qvarsitta uppe i skatanom; eller såsom fyra eller fem bär hänga qvar på qvistarna, säger Herren Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'På den tiden skall menniskan hålla sig intill honom, som henne gjort hafver, och hennes ögon skola se på den Heliga i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Och skall icke hålla sig till altaren, som hennes händer gjort hafva, och icke se till det hennes finger gjort hafva, antingen till lundar eller beläte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'På den tiden skola hans starkhets städer varda såsom en öfvergifven telning och qvist, som öfvergifven var för Israels barn, och skola öde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Ty du hafver förgätit Gud, den din helsa, är, och icke tänkt uppå dina starkhets klippo; derföre skall du sätta lustiga plantor, men du skall dermed satt hafva vinqvisten åt främmandom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'I planterningenes tid skall du väl taga vara uppå, att din säd må tideliga växa; men åt höstenom, när du skall inberga kärfvarna, skall du få ens bedröfvadas sorg derföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Ack! ve det öfvermåtto myckna folket; såsom hafvet skall det brusa, och folkens rumor varder stormandes, såsom stor vatten storma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Ja, såsom stor vatten storma, så skola folken storma; men han skall näpsa dem, och de skola fly lång väg bort; och skall förfölja dem, såsom stoftena på bergen sker af vädret, och såsom enom väderhvirfvel sker af stormenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Om aftonen, si, så är förskräckelse på färde, och förr än morgonen varder, så äro de intet till. Detta är deras lön, som oss röfva, och deras arfvedel, som taga oss vårt ifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Ve thy landena, som far i skugganom under segel, på desso sidone Ethiopiens floder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Hvilket bådskap sänder till hafs, och i rörskepp far på vattnen. Går åstad, I snare bådskap, till det folk, som rifvet och skinnadt är, till det folk, som grufveligare är än något annat; till det folk, som här och der utmätet och förtrampadt är, hvilkets land vattuströmmar intaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Alle I, som bon på jordene, och I, som i landena sitten, skolen se huru man skall uppresa baneret på bergen, och höra huru man med trummeterna blåsa skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Ty all säger Herren till mig: Jag vill vara stilla, och tillse i mine hyddo; såsom en hette, den der uttorkar regn, och såsom en dagg i skördandenes hetta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Ty för skördandena skall växten förminskas, och den omogna frukten förtorkas, medan hon ännu står i blomma, så att man måste afskära qvistarna med skäro, och afhugga vinträn, och kasta dem bort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Att man måste låta ligga dem tillsammans foglomen på bergen, och djuromen i landena, att foglarna bygga om sommaren der sitt näste uti, och allahanda djur i landena ligga deruti om vinteren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'På den tiden skall det refna och skinnade folket, det grufveligare är än något annat, det här och der afmätet och nedertrampadt är, hvilkets land vattuströmmarna intaga föra Herranom Zebaoth skänker, på det rum, der Herrans Zebaoths Namn är, till Zions berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Detta är tungen öfver Egypti land: Si, Herren skall fara uti enom snarom sky, och komma in uti Egypten; då skola de afgudar uti Egypten bäfva för honom, och de Egyptiers hjerta skall gifva sig i dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Och jag skall hetsa, de Egyptier på hvarannan, att en broder skall strida emot den andra, en vän emot den andra, en stad emot den andra, ett rike emot det andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Och de Egyptiers mod skall förgås i dem, och jag skall göra deras anslag omintet; så skola de då fråga deras afgudar och Prester, och spåmän och tecknatydare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Men jag skall gifva de Egyptier uti grufveliga herrars händer; och en hård Konung skall råda öfver dem, säger den rådandes Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Och vattnet i hafvet skall uttorkas; dertill skola ock strömmarna, bortsjunka och försvinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Älfverna skola utlöpa, så att dammsjöarna skola förminskas och torre varda; rör och säf förvissna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Och gräset vid bäckerna, och all säd vid vattnet skall förfalna, förderfvas och till intet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Och fiskarena skola sörja, och alle de, som fiskakrok kasta i vattnet, skola beklaga sig; och de, som nät utkasta i vattnet, skola bedröfvade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'De skola afgå med skam, som god garn göra, och nät binda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Och de som fiskakistor hafva, med alla dem som dammar för lön göra, skola ångse varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'De Förstar i Zoan äro dårar, Pharaos vise rådgifvare äro i deras råd galne vordne. Hvi sägen I dock om Pharao: Jag är visamannabarn, och är af gamla Konungar kommen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Hvar äro då nu dine vise? Låt dem förkunna, och undervisa dig, hvad Herren Zebaoth öfver Egypten beslutit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Men de Förstar i Zoan äro vordne till dårar; de Förstar i Noph äro bedragne; de förföra samt med Egypten hörnstenen för slägten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Ty Herren hafver utgjutit en villoanda ibland dem, att de skola förföra Egypten uti allt det de göra, såsom en drucken ragar, då han spyr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Och Egypten skall ingen hafva, den der för hufvud eller stjert, bål eller gren är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'På den tiden skall Egypten vara såsom qvinnor, och frukta sig, och förskräckas, då Herren Zebaoth veftar handena öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Och Egypten skall frukta sig för Juda lande, så att den der tänker uppå, han skall förskräckas öfver Herrans Zebaoths råd, som han öfver det beslutit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Uti den tiden skola fem städer uti Egypti land tala efter Canaans mål, och svärja vid Herran Zebaoth; en af dem skall heta Irheres.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'På den samma tiden skall Herrans Zebaoths altare vara midt uti Egypti land, och en Herrans vårdsten i gränsone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Den ett tecken och vittne vara skall Herranom Zebaoth uti Egypti land; ty de skola ropa till Herran, för sina plågares skull, och han skall sända dem en Frälsare och mästare, som dem hjelpa skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Ty Herren skall af, de Egyptier känd varda; och de Egyptier skola känna Herran på den tiden, och skola tjena honom med offer och spisoffer, och skola göra Herranom löfte, och hålla det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Och Herren skall slå de Egyptier, och hela dem; ty de skola omvända sig till Herran, och han skall låta bedja sig, och hela dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'På den tiden skall en väg vara ifrån Egypten in uti Assyrien, så att de Assyrier skola komma in uti Egypten, och de Egyptier in uti Assyrien, och både Egyptier och Assyrier Gudi tjena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'På samma tiden skall Israel vara sjelf tredje, med de Egyptier och Assyrier, genom den välsignelse, som på jordene vara skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Ty Herren Zebaoth skall välsigna dem, och säga: Välsignad äst du Egypten, mitt folk, och du Assur, mina händers verk, och du Israel, mitt arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Uti det året, då Tharthan kom till Asdod, hvilken Sargon, Konungen i Assyrien, utsändt hade, och stridde emot Asdod, och vann det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'På samma tid talade Herren, genom Esaia, Amos son, och sade: Gack bort, och drag säcken af dina länder, och drag dina skor af dina fötter. Och han gjorde så, gick nakot och barfött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Då sade Herren: Lika som min tjenare Esaia går nakot och barfött, till treåra tecken och under öfver Egypten och Ethiopien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Alltså skall Konungen i Assyrien drifva den fångna Egypten, och förderfva Ethiopien, både unga och gamla, nakota och barfötta, med blottad skam, Egypten till blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Och de skola förskräckas, och med skam bestå öfver Ethiopien, der de förläto sig uppå; och tvärtom Ethiopien, öfver de Egyptier, af hvilkom de sig berömde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Och dessa öars inbyggare skola säga på den tiden: Är det vår tillflykt, dit vi flytt hafve efter hjelp, att vi skulle hulpne varda ifrå Konungenom i Assyrien? Ja, skönliga äre vi undsluppne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Detta är tungen öfver öknena vid hafvet: Såsom ett väder kommer ifrå sunnan, det all ting omvänder, så kommer det utur öknene, utur ett grufveligit land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Ty mig är betedd en hård syn: En föraktare kommer emot den andra; och en förstörare emot den andra; drag upp, Elam, belägg dem, Madai; jag skall göra en ända uppå allt hans suckande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Derföre äro mina länder fulla mes värk, och ångest hafver begripit mig, såsom ena barnafödersko; jag kröker mig, när jag hörer det, och förskräckes, när jag ser deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Mitt hjerta bäfvar; grufvelse hafver mig förskräckt; jag hafver derföre uti den ljufva nattene ingen ro haft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Ja, tillred ett bord, låt vaka på vaktene, äter, dricker; står upp, I Förstar, smörjer skölden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Ty Herren säger till mig alltså: Gack bort och beställ en väktare, den som tillser och tillsäger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Men han ser resenärer rida och fara med hästar, åsnar, och camelar, och hafver granneliga akt deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Och ett lejon ropade: Herre, jag står på vaktene alltjemt om dagen, och står i mine vakt alla nätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Och si, der kommer en på enom vagn, han svarar, och säger: Babel är fallet; det är fallet, och all dess gudars beläte äro slagne ned till markena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'O! min loge, der jag på tröskar; hvad jag af Herranom Zebaoth Israels Gudi hört hafver, det förkunnar jag eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Detta är tungen öfver Duma: Man ropar till mig utaf Seir: Väktare, hvad lider natten? Väktare, hvad lider natten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Väktaren sade: Då morgonen än kommer, så skall det ändå vara natt; om I än frågen, så skolen I likväl igenkomma och åter fråga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Detta är tungen öfver Arabien: I skolen bo uti skogenom i Arabien, på den vägen åt Dedanim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Bärer vatten emot den törstiga, I som bon uti Thema land; bjuder dem flyktigom bröd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Förty de flyr för svärd, ja, för draget svärd, för spändom båga, för storo strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Ty alltså, säger Herren till mig: Ännu innan ett år, såsom legodrängers år äro, skall all Kedars härlighet förgås;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Och de qvarblefne skyttar af hjeltarna i Kedar skola mindre varda; ty Herren Israels Gud hafver det så sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Detta är tungen öfver synedalen: Hvad är eder, att I så alle löpen på taken?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Du vast full med gny, en stad full med folk, en glad stad; dine slagne äro icke med svärd slagne, och icke döde blefne i strid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Utan alle dine höfvitsmän äro tillika bortvekne för båga, och fångne; alle de, Som man uti dig funnit hafver, äro fångne, och långt bortflydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Derföre säger jag: Går ifrå mig, låter mig bitterliga gråta; farer icke efter att hugsvala mig öfver mins folks dotters förstöring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Ty det är en bullers, förtryckelses och bekymmers dag af Herranom Zebaoth, i synedalenom, för murarnas undergrafnings skull, och för ropets skull på berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Ty Elam drager med koger, vagnar, folk och resenärar, och Kir glimmar af sköldar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Och skall ske, att dina utkorade dalar skola med vagnar fulle varda, och resenärer skola lägga sig för portarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Då skall Juda förlåt öppnad varda, att man skall kunna se, på den tiden, tygen uti skogshuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Och I skolen se refvorna många vara på Davids stad, och skolen församla vatten uti dem nedra dammenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'I skolen ock räkna, husen i Jerusalem, ja, I skolen afbryta husen, till att befästa murarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Och I skolen göra ena vattugraf, emellan båda murarna af den gamla dammens vatten; likväl sen I icke uppå den som detta gör, och skåden icke på den som sådant beställt hafver fjerranefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Derföre skall Herren, Herren Zebaoth på den tiden låta utropa, att man skall gråta och jämra sig, och kulla sig, och draga säck uppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Ändock nu, si; intet annat är än glädje, slagta oxar, dräpa får, äta kött, dricka vin, och säga: Låt oss äta och dricka, vi måste dock i morgon dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Detta är för Herrans Zebaoths öron uppenbart. Hvad gäller, om eder denna missgerningen förlåtas skall, tilldess I dön, säger Herren, Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Så säger Herren, Herren Zebaoth: Gack in till räntomästaren Sebna, hofmästaren, och säg till honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Hvad hafver du här? Hvem hörer du till? att du låter dig hugga en graf, såsom den der låter sig hugga en graf i höjdene, och såsom den der låter sig göra en boning i bergklippone?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Si, Herren skall förkasta dig, såsom en stark man någon bortkastar, och nederkrafsa dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Och skall omdrifva dig, såsom ett klot på vida mark; der skall du dö, der skola dina kosteliga vagnar blifva med dins herras hus försmädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Och jag skall störta dig ifrå ditt stånd, och sätta dig af ditt ämbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Och på den tiden vill jag kalla min tjenare Eliakim, Hilkia son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Och draga din kjortel uppå honom, och omgjorda honom med ditt bälte, och gifva ditt välde uti hans hand, att han skall vara deras fader, som i Jerusalem och Juda hus bo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Och skall lägga Davids hus nyckel uppå hans axlar, att han skall upplåta, och ingen skall tillsluta; att han skall tillsluta, och ingen upplåta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Och jag vill inslå honom för en nagla på ett fast rum, och han skall hafva ärones stol uti sins faders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Att man skall hänga uppå honom all hans faders hus härlighet, barn och barnabarn, all små tyg, både dryckekar och allahanda strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'På den tiden, säger Herren Zebaoth, skall nagelen borttagen varda, den på det fasta rummet står, så att han skall söndergå och falla, och hans börda förgås; ty Herren säger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Detta är tungen öfver Tyro: Jämrer eder, I skepp på hafvena; ty det är förstördt, så att der är intet hus, ej heller far någor dit; utu det land Chittim skola de varda dess var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Öarnas inbyggare äro stilla vordne; de köpmän af Zidon, som till sjös foro, uppfyllde dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Och allahanda frukt, som växer vid Zihor, och säd vid älfvena, det förde man derin öfver stor vatten; och du vast Hedningarnas stapol vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Du må väl förskräckas, Zidon; ty hafvet, ja, den fastesta vid hafvet säger: Jag är intet hafvandes, jag föder intet, så uppföder jag ock inga ynglingar, och uppfostrar inga jungfrur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Såsom man förskräcktes, då man hörde om Egypten, så skall man ock förskräckas, då man får höra om Tyro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Farer till sjös, jämrer eder, I som bon på öarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Är icke detta eder glädjestad, den sig berömmer af sinom stora ålder? Hans fötter skola föra honom långan väg bort till att vandra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Ho hade det betänkt, att thy krönta Tyro skulle så gå, efter dess köpmän äro Förstar, och dess krämare de härligaste i landena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Herren Zebaoth hafver det så betänkt, på det han skall försvaga allt prål i den lustiga staden, och förakteliga göra alla de härliga i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Far igenom ditt land, såsom en ström, du hafsens dotter; der är intet bälte mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Han uträcker sina hand öfver hafvet, och förskräcker Konungarike; Herren bjuder öfver Canaan, till att förgöra hans mägtiga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Och säger: Du skall icke mer glad vara, du beskämda Zidons dotter; o Chittim, statt upp, och far din väg, ty du skall icke blifva der;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Utan i de Chaldeers land, det intet folk var; utan Assur hafver det uppbyggt för skepp, och upprest der fast torn, och uppbyggt palats; och är likväl förstörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Jämrer eder, I skepp på hafvena; ty edor magt är omintet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'På den tiden skall Tyrus förgäten varda i sjutio år, så länge en Konung lefva må; men efter sjutio år skall man sjunga en skökoviso om Tyro:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Tag harpona, gack omkring i staden, du förglömda, sköka, spela fast på strängaspel, och sjung trösteliga, att man må åter tänka uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Ty efter sjutio år skall Herren besöka Tyrum, att han skall åter komma till sin skökolön, och bedrifva boleri med all Konungarike på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Men hans köpmanshandel och skökolön skall varda helig Herranom; man varder det icke församlande för en skatt, ej heller fördöljande; utan de som för Herranom bo, skola hafva hans köpmansgods, att de skola deraf äta, och mätte varda, och väl klädde vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Si, Herren gör landet tomt och öde, och omstörtar hvad deruti är, och förströr dess inbyggare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Och Prestenom går såsom folkena; herranom såsom tjenarenom, frune såsom tärnone; så honom som säljer, som honom som köper, honom som lånar, såsom honom som borgar; kräfvarenom, såsom gäldenärenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Ty landet skall varda tomt och skinnadt; ty Herren hafver detta sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Landet står jämmerliga, och förderfvas; jordenes krets förvanskas och förderfvas; de högste af folket i landena förminskas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Landet är oskärdt vordet af sina inbyggare; förty att de öfverträda lagen, och förvandla buden, och låta det eviga förbundet fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Derföre uppfräter förbannelse landet; ty de som deruti bo, förskylla det; derföre borttorkas landsens inbyggare, så att fögo folk qvart blifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Vinet försvinner, vinträt förvissnar, och alle de, som af hjertat glade voro, sucka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Fröjd af trummor håller upp, de gladas lust är ute; harpors fröjd hafver en ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Man sjunger intet, der man vin dricker, och god dryck är bitter dem som dricka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Den tomme staden är nederbruten; all hus äro tillsluten, så att ingen går derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Man klagar efter vin på gatone, all glädje är borto, all landsens fröjd är sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Icke annat än förödelse är blifvet i stadenom, och portarna stå öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Ty det går i landena och med folkena, lika som när ett oljoträ afplockadt är; såsom när man efterhämtar, då vinanden ute är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'De samme upphäfva deras röst och lofva, och glädjas öfver Herrans härlighet ifrå hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Så priser nu Herran i dalomen; på hafsens öar Herrans Israels Guds Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Vi höre lofsång ifrå jordenes ända, den Rättfärdiga till äro; och jag måste säga: Hvi är jag dock så mager? Hvi är jag dock så mager? Ve mig! ty föraktarena förakta, ja, föraktarena förakta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Derföre kommer öfver eder, landsens inbyggare, förskräckelse, grop och snara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Och om en undflydde för förskräckelsens rop, så faller han dock likväl uti gropena. Kommer han utu gropene, så varder han dock fången i snarone; ty fenstren i höjdene äro upplåtna, och jordenes grundvalar bäfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Landena varder illa gångandes; det skall icke trifvas, utan måste förfalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Landet skall raga hit och dit, såsom en drucken, och bortfördt varda, lika som en hydda; ty dess missgerningar trycka det, så att det falla måste, och kan icke blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'På den tiden skall Herren besöka det höga herrskapet, som i höjdene är, och jorderikes Konungar, som på jordene äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Att de skola tillhopasamkas såsom ett knippe till gropena, och skola förslutne varda uti fångahuse, och efter lång tid åter besökte varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Och månen skall skämma sig, och solen blygas; då Herren Zebaoth skall Konung varda på berget Zion, och i Jerusalem, och för sina äldsta i härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Herre, du äst min Gud; dig prisar jag; jag lofvar ditt Namn; ty du gör under, din gamla anslag äro trofast och sannfärdig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Ty du gör staden till en stenhop, den fasta staden, att han uti en hop ligger; de främmandes palats, så att det icke mer en stad är, och aldrig mer uppbyggd varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Derföre ärar dig ett mägtigt folk; de väldiga Hedningars städer frukta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Ty du äst dens fattigas starkhet, dens armas starkhet i bedröfvelsen, en tillflykt för oväder, en skygd för hetta, då de tyranner rasa såsom en storm emot en vägg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Du ödmjukar de främmandes storm, såsom en hette i torrt rum, så att hetten skall förderfva de tyranners vinqvistar; och skyarna gifva ändock skugga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Och Herren Zebaoth skall göra till all folk ett fett gästabåd på desso bergena; ett gästabåd af klart vin, af feto, af märg, af vin, der ingen drägg uti är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Och han skall på desso bergena bortlägga svepklädet, der all folk med besvept äro, och täckeklädet, der alle Hedningar men betäckte äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Ty döden skall platt uppsluken varda; och Herren Herren skall aftvå tårarna af all ansigte, och skall borttaga sins folks försmädelse i all land; ty Herren hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'På den tiden skall man säga: Si, det är vår Gud, den vi förbide, och han skall hjelpa, oss; det är Herren; vi förbide honom, att vi skole fröjda oss, och glade vara i hans salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Ty Herrans hand hvilas på desso bergena; och Moab skall derunder förkrossad varda, såsom strå söndertröskadt varder, och såsom träck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Och han skall utsträcka sina händer midt ibland dem, såsom en simmande dem uträcker till att simma, och förnedra deras prål med sina händers arm;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Och skall nederböja edra murars höga fäste, förnedra, och kasta dem i stoft på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'På den tiden skall man sjunga, en sådana viso i Juda land: Vi hafve en fast stad, murar och värn äro helsa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Låter upp portarna, att det rättfärdiga folket, som tro bevarar, må gå härin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Du håller allstädes frid vid magt, efter visst löfte; ty man förlåter sig uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Derföre förlåter eder uppå Herran evinnerliga; ty Herren Gud är en klippa evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Och han nederböjer dem som i höjdene bo; den höga staden förnedrar han; ja, han stöter honom neder till jordena, så att han ligger i stoftet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Att han med fötter trampad varder; ja, med de fattigas fötter; de arme skola trampa deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Men de rättfärdigas väg är slät; de rättfärdigas stig gör du rättan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Ty vi vänte efter dig, Herre, uti dins rätts väg; hjertans lust står till ditt Namn och ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Af hjertat begärar jag dig om nattena; med minom anda i mig vakar jag bittida upp till dig; ty der din rätt är på jordene, der lära jorderikes inbyggare rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Men om än dem ogudaktigom nåde tillbuden varder, så lära de dock icke rättfärdighet; utan på jordene, der rätt ske skulle, göra de det ondt är; ty de se intet Herrans härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Herre, din hand är upphöjd, det se de intet; men när de få se det, så skola de på skam komma, uti nit öfver Hedningarna; dertill skall du förtära dem med eld, der du dina fiendar med förtärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Men oss, Herre, varder du frid skaffandes; ty allt det vi uträtte, det hafver du gifvit oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Herre, vår Gud, det råda väl andre herrar öfver oss utan dig; men vi tänke dock allena uppå dig och ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'De döde få icke lif, de afledne stå icke upp; ty du hafver sökt dem, och förgjort dem, och all deras åminnelse tillintetgjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Men, Herre, du håller det fram ibland Hedningarna, du håller det alltså fram ibland Hedningarna; du beviser dina härlighet, och kommer långt bort, allt intill verldenes ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Herre, när bedröfvelse på färde är, så söker man dig; när du tuktar dem, så ropa de med ängslan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Lika som en hafvandes qvinna, då det lider till födslostundena, så är henne ångest, ropar i sin värk; alltså går ock oss, Herre, för ditt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Vi äre också hafvande, och hafvom ångest, att vi som nogast kunne andas; dock kunne vi intet hjelpa jordene, och inbyggarena på jordenes krets vilja icke falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Men dine döde skola lefva, och med lekamenom uppstå igen. Vaker upp och berömmer eder, I som liggen under jordene; ty din dagg är en grön marks dagg, och jorden skall gifva ifrå sig de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Gack bort, mitt folk, uti en kammar, och slut dörrena igen efter dig; fördölj dig ett litet ögnablick, så länge vreden går öfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Ty si, Herren varder utgångandes af sitt rum, till att besöka jordenes inbyggares ondsko öfver dem, så att jorden skall uppenbara deras blod, och icke mer öfverskyla dem som på henne slagne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'På den tiden skall Herren, med sitt hårda, stora och starka svärd, hemsöka Leviathan, som en raker orm är, och Leviathan, som en krokot orm är, och skall dräpa drakan i hafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'På den tiden skall man sjunga om bästa vinsens vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Jag Herren bevarar honom, och vattnar honom i tid, att man icke skall mista hans löf; jag skall bevara honom dag och natt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Gud är icke vred på mig. Ack! att jag strida måtte med tistel och törne, så ville jag till dem, och uppbränna dem alla tillsammans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Han skall hålla mig vid magt, och skaffa mig frid; frid skall han ändå skaffa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Det varder likväl ännu dertill kommandes, att Jacob skall rota sig, och Israel skall grönskas och blomstras, så att de skola uppfylla jordenes krets med frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Varder han dock icke slagen, såsom hans fiender slå honom, och varder icke dräpen, såsom hans fiender honom dräpa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Utan med mått dömer du dem, och låter dem lös, sedan du dem bedröfvat hafver, med ditt hårda väder, som är med östanväder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Derföre skall derigenom Jacobs synd återvända; och det är nyttan deraf, att hans synd borttagen varder; då han gör alla altarens stenar, såsom sönderstötta stenar, till asko, att inga lundar eller beläte nu mer blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Ty den faste staden måste ensam varda, de sköna hus bortkastad och öfvergifne blifva, såsom en öken; så att kalfvar skola der gå i bet, och vistas der, och afbita der qvistarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Hans qvistar skola brista sönder för torrhet, så att qvinnor skola komma och göra der eld med; ty det är ett oförståndigt folk; derföre varder ej heller förbarmandes sig öfver dem den dem gjort hafver, och den dem skapat hafver skall icke vara dem nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'På den tiden skall Herren kasta ifrå stranden af älfvene, allt intill Egypti älf; och I, Israels barn, skolen församlade varda, den ene efter den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'På den tiden skall man blåsa med en stor basun, så skola komma de förtappade uti Assurs land, och de fördrefne uti Egypti land, och skola tillbedja Herran, på det helga berget i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Ve den stolta kronone, de drucknas af Ephraim, det falnade blomstret, hans lustiga härlighets, hvilket öfver den feta dalen står, deras som af vin raga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Si! en starker och mägtiger af Herranom, såsom en hagelstorm, såsom ett skadeligit väder, såsom en vattustorm, den starkeliga infaller, skall uti landet med våld insläppt varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Att den stolta kronan, och drucknas af Ephraim, skall med fötter trampad varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Och det falnade blomstret, hans lustiga härlighets, hvilket öfver den feta dalen står, skall varda såsom det bittida på sommaren mognas, hvilket förgås, medan man ännu ser det hänga på sina qvistar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'På den tiden skall Herren Zebaoth vara dem igenlefdom af sitt folk en lustig krona, och en härlig krans;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Och en doms ande honom som för rätta sitter, och en starkhet dem som igenkomma af stridene till porten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Dertill äro ock dessa galne vordne af vin, och raga af starkom dryck; ty både Prester och Propheter äro galne af starkom dryck. De äro drunknade uti vin, och raga af starkom dryck; de äro galne i Prophetien, och drabba icke rätt i domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Ty all bord äro full med spyor, och slemhet allstädes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Hvem skall han då lära vishet? Hvem skall han då låta predikan förstå? Dem afvandom af mjölkene, dem aftagnom ifrå bröstet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Ty de säga: Bjud, bjud, bjud, bjud; bida, bida, bida, bida, här litet, der litet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Nu väl, han skall en gång med spotskliga läppar och med ett annat tungomål tala till detta folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Hvilko nu detta predikadt varder: Så hafver man ro, så vederqvicker man de trötta, så varder man stilla; och vilja dock icke höra denna predikanen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Derföre skall dem ock Herrans ord alltså varda: Bjud, bjud, bjud, bjud; bida, bida, bida, bida, här litet, der litet; att de skola gå bort, och falla tillbaka, förkrossas, besnärde och fångne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Så hörer nu Herrans ord, I bespottare, som rådande ären öfver detta folk som i Jerusalem är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Ty I sägen: Vi hafve gjort ett förbund med döden, och förvete oss med helvetet. När en flod kommer, skall hon intet drabba på oss; ty vi hafve gjort oss en falsk tillflykt, och gjort oss en bedrägelig skärm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Derföre säger Herren Herren alltså: Si, jag lägger i Zion en grundsten, en pröfvosten, en kostelig hörnsten, den väl grundad är. Den der tror, han skall icke förskräckas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Och jag skall göra domen till ett rättesnöre, och rättfärdighetena, till en vigt. Så skall haglet drifva den falska tillflykten bort, och vatten skall föra skärmen bort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Att edart förbund med döden skall löst varda, och edart förvetande med helvetet skall icke bestå, och när en flod går fram, skall hon förtrampa eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Så snart hon framgår, skall hon taga eder bort. Kommer hon om morgonen, så sker det om morgonen; sammalunda, ehvad hon kommer dag eller natt; ty straffet allena lärer gifva akt uppå orden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Ty sängen är för trång, så att intet öfver är, och täckenet så stackot, att man måste krympa sig derunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Ty Herren skall uppstå lika som på de bergena Perazim, och vredgas, såsom uti Gibeons dal; på det han skall göra sitt verk vid ett annat sätt, och att han sitt arbete göra skall vid ett annat sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Så lägger nu bort edart begabberi, på det edor band icke skola hårdare varda; ty jag hafver hört en förderfvelse och afkortelse, den af Herranom, Herranom Zebaoth ske skall i allo verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Fatter med öronen, och hörer mina röst; märker åt, och hörer mitt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Plöjer eller träder, eller arbetar ock en åkerman sin åker alltid till säd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Är icke så? När han hafver gjort honom jemn, så sår han deruti ärter, och kastar kummin, och sår hvete och bjugg, hvart och ett dit som han det hafva vill, och hafra på sitt rum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Alltså, tuktar ock dem deras Gud med straff, och lärer dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Ty man tröskar icke ärter med slago, och låter man ej heller vagnshjulet gå öfver kummin; utan ärter slår man ut med en staf, och kummin med ett spö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Man mal det till bröds, och man tröskar det icke alldeles till intet, när man med vagnshjul och hästar uttröskar det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Detta sker ock af Herranom Zebaoth; ty hans råd är underligit, och går det härliga igenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Ve Ariel, Ariel, du Davids lägres stad. I begån årstider, och hållen helga dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Men jag skall tränga Ariel, så att han skall sörja och jämra sig, och vara mig en sannskyldig Ariel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Ty jag skall belägga dig allt omkring, och skall tränga dig med bålverk, och skall låta uppsätta vallar omkring dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Då skall du förnedrad varda, och tala utu jordene, och mumla med ditt tal utu stoftet, att din röst skall vara såsom en spåkarls utu jordene, och ditt tal skall hviskande vara utu stoftet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Och de som dig förskingra, skola vara så månge som ett grant stoft; och de tyranner så månge såsom fjukande agnar; och det skall ganska hastigt ske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Ty du skall af Herranom Zebaoth hemsökt varda, med väder, och med jordbäfning, och stor dunder; med väderhvirfvel och storm, och med förtärande eldslåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Men såsom en natts syn i dröm, så skola alle de många Hedningar vara, de der strida emot Ariel; samt med all deras här och bålverke, och dem som tränga honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Ty såsom enom hungrogom drömmer, att han äter; men då han uppvakar, så är hans själ ännu tom; och såsom enom törstigom drömmer, att han dricker; men när han uppvakar, är han magtlös och törstig; alltså skola ock de månge Hedningar vara, som emot Zions berg strida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Varder häpne och försoffade; förblindens och varder druckne, dock icke af vin; rager, dock icke af starkom dryck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Ty Herren hafver eder inskänkt en svår sömns anda, och tillyckt edor ögon; edra Propheter och Förstar, samt med de Siare, hafver han förblindat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Så att allas syner skola vara eder såsom ens beseglad boks ord, hvilka som man får enom, som läsa, kan, och säger: Käre, läs häruti; och han säger: Jag kan icke; ty hon är beseglad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Eller, lika som man finge enom, som intet läsa kunde, och sade: Käre, läs häruti; och han sade: Jag kan intet läsa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Och Herren säger: Derföre, att detta folket nalkas mig med sinom mun, och hedrar mig med sina läppar, men deras hjerta är långt ifrå mig, och frukta mig efter menniskors bud, som de lära;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Si, så vill jag ock underliga handla med detta folk, allt som underligast och sällsynligast; så att deras visas vishet skall förgås, och deras klokas förstånd skall förblindadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Ve dem som fördolde vilja vara för Herranom, till att förskyla deras uppsåt, och hålla deras gerningar i mörkret, och säga: Ho ser oss? Och ho känner oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Hvi ären I så vrånge? lika som en krukomakares ler tänkte, och ett verk sade om sin mästare: Han hafver icke gjort mig; och en potta sade till sin makare: Han känner mig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Nu väl, innan en ganska liten tid skall Libanon varda en åkermark, och åkermarken skall en skog räknad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Ty på den samma tiden skola de döfve höra bokenes ord, och de blindas ögon skola se utu mörkret och skummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Och de elände skola åter hafva glädje i Herranom, och de fattige ibland menniskorna skola glädja sig uti Israels Heliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'När de tyranner en ända hafva, och det med de begabbare ute blifver; och förgjorde varda alle de som vaka efter att komma vedermödo åstad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Hvilke komma menniskorna till att synda genom predikan, och gå dem efter som straffa dem i portenom, och vika ifrå rätthetene genom lögn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Derföre säger Herren, som Abraham förlossat hafver, till Jacobs hus alltså: Jacob skall icke mer på skam komma, och hans anlete skall icke mer skämmas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Ty när de få se deras barn, mina händers verk ibland dem, skola de helga mitt Namn, och skola helga den Heliga i Jacob, och frukta Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Ty de, som en villoanda hafva, skola taga vid förstånd, och de bladdrare skola sig lära låta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Ve de affälliga barnen, säger Herren; de som rådslå utan mig, och utan min Anda beskydd söka, samla synd öfver synd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'De som draga neder uti Egypten, och fråga intet min mun, att de skola stärka sig med Pharaos magt, och beskärma sig under Egypti skugga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Ty Pharaos starkhet skall eder på skam komma, och det beskydd under Egypti skugga till försmädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Deras Förstar hafva varit i Zoan, och deras bådskap äro till Hanes komne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Men de måste likväl allesamman på skam komma, öfver det folk som dem till intet bestånd vara kan, antingen med hjelp; eller eljest till nytto; utan allenast till skam och hån.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Detta är tungen öfver de djur, som draga söderåt; der lejon och lejinnor äro, ja, huggormar och brinnande flygande drakar, uti bedröfvelses och jämmers lande. De föra deras gods på fålars rygg, och deras skatt på camelers rygg, till det folk som dem intet till nytto vara kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Ty Egypten är intet, och dess hjelp är fåfäng; derföre predikar jag eder deraf alltså: Rahab skall sitta stilla dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Så gack nu, och skrif detta för dem på en taflo, och teckna det uti en bok, att det må blifva evinnerliga och utan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Ty det är ett ohörsamt folk, och lögnaktig barn, som Herrans lag icke höra vilja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Utan säga till Siarena: I skolen intet se; och till skådarena: I skolen intet skåda oss den rätta läron; men prediker oss ljufliga, skåder oss bedrägeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Viker af vägen, öfvergifver denna stigen; låter Israels Heliga återvända när oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Derföre säger Israels Helige alltså: Efter thy I förkasten detta ordet, och förtrösten uppå försmädare och förförare, och förlåten eder deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Så skall denna missgerningen vara eder såsom en refva på en hög mur, då han begynner remna, hvilken hastigt omkullfaller och förkrossas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Såsom ett lerkäril sönderkrossadt vorde, det man sönderkrossar, och skonar thy intet, tilldess man deraf icke finner ett stycke så stort, att man dermed kan eld taga af en eldstad, eller vatten ösa utur en brunn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Ty så säger Herren Herren, den Helige i Israel: Om I stilla blifven, så vorde eder hulpet; genom stillhet och hopp vorden I starke; men I villen icke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Och saden: Nej; utan vi vilje fly till hästar; derföre skolen I flyktige varda; och uppå löpare vilje vi rida; derföre skola edra förföljare varda eder för snare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Ty tusende af eder skola fly för ens mans rop allena; ja, för fem skolen I fly allesammans, tilldess af eder skola igenblifva, såsom ett mastträ, ofvanuppå ett berg, och såsom ett baner ofvanuppå en hög.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Derföre bidar Herren, att han skall vara eder nådelig, och är uppstånden, att han skall förbarma sig öfver eder; ty Herren är en Gud, som handlar med dom. Väl är allom dem som förbida honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Ty Zions folk skall bo i Jerusalem; du skall icke gråta. Han skall varda dig nådelig, när du ropar; han varder dig svarandes, så snart han det hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Och Herren skall uti edor bedröfvelse gifva eder bröd, och vatten uti edor ångest; ty han låter icke dina lärare mer bortflyga; utan din ögon skola se dina lärare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Och din öron skola höra ordet efter dig, så sägandes: Detta är vägen, går honom, och eljest hvarken på högra handena, eller på den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Och I skolen ohelga edra besilfrada afgudar, och edor belätes gyldene kläder, och skolen bortkasta dem såsom träck, och säga till dem: Härut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Så skall han gifva dine säd, som du på åkrenom sått hafver, regn och bröd af åkrens årsväxt, och det öfvernog, och din boskap skall på den tiden gå i bet på en vid gräsmark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Oxar och fålar, der åkren med brukas, skola blandadt korn äta, det kastadt är med kastoskofvel och vanno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Och på all stor berg, och på alla stora högar, skola åtskilde vattuströmmar gå, på den stora slagtningenes tid, när tornen falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Och månans sken skall varda såsom solenes sken, och solenes sken skall varda sju resor klarare än det nu är, på den tid då Herren förbinda skall sins folks skada, och hela deras sår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Si, Herrans Namn kommer fjerranefter; hans vrede bränner, och är ganska svår; hans läppar äro fulle med grymhet, och hans tunga såsom en förtärande eld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Och hans ande såsom en vattuflod, den upp till halsen räcker, till att förströ Hedningarna, tilldess de omintet varda, och drifva folken hit och dit med ett betsel uti deras mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Då skolen I sjunga, såsom på en helgedagsnatt, och fröjda eder af hjertat, lika som så man går med en pipo till Herrans berg, till Israels tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Och Herren skall låta höra sina härliga röst, att man må se hans uträckta arm, med vredsamt trug, och med en förtärande eldslåga, med strålar, med starkt regn, och med hagel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Ty Assur skall förskräckt varda för Herrans röst, den honom med ris slår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Ty riset skall väl drabba och bita igenom, då Herren det öfver dom förer med trummor och harpor, och allestäds emot dem strider.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Ty gropen är tillredd sedan i går; ja, hon är ock Konungenom tillredd, djup och vid nog. Så är boningen derinne, eld och mycken ved. Herrans ande skall upptända henne såsom en svafvelström.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Ve dem som draga neder till Egypten efter hjelp, och förlåta sig uppå hästar, och trösta uppå vagnar, att de månge äro, och uppå resenärar, derföre att de fast starke äro; och hålla sig icke intill den Heliga i Israel, och fråga intet efter Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Men han är vis, och låter komma olycko, och vänder icke sin ord; utan varder sig uppresandes emot de ondas hus, och emot de ogerningsmäns hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Ty Egypten är menniska, och icke Gud; och deras hästar äro kött, och icke ande; och Herren skall uträcka sina hand, så att hjelparen skall raga, och den som hulpen varder, han skall falla, och tillhopa, förgås, den ene med den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Ty så säger Herren till mig: Lika som ett lejon och ett ungt lejon ryter öfver sitt rof, då en hop med herdar ropa uppå det, så förskräckes det intet för deras rop, och är intet rädt för det de äro månge; alltså skall Herren Zebaoth fara ned, till att strida på Zions berg, och uppå dess hög.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Och Herren Zebaoth skall beskärma Jerusalem, såsom foglar göra med vingarna; beskydda, hjelpa, derinne vistas, och undsätta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Vänder om, I Israels barn, I som fast afvikit hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Ty på den tiden skall hvar och en förkasta sina silfvers och gyldene afgudar, hvilka eder edra händer gjort hafva till synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Och Assur skall falla, icke genom mans svärd, och skall förtärd varda, icke genom menniskosvärd; och skall dock för svärd fly, och hans unge män skola skattskyldige varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Och deras klippa skall för fruktans skull bortdraga, och hans Förstar skola för baneret flykten gifva, säger Herren, den i Zion en eld hafver, och en ugn i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Si, en Konung varder regerandes med rättviso; och Förstarna, varda rådande till att hålla rätten vid magt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Att hvar man skall vara såsom en den der för väder bevarad är, och såsom en den der för skurregn förskyld är; såsom vattubäcker på en torr plats, såsom skuggan af ett stort berg uti torro lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Och de seende ögon skola icke låta förblinda sig, och de tillhörares öron skola grant påmärka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Och de galne skola lära klokhet, och den stumma tungan skall färdig varda, och renliga tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'En dåre skall icke mer varda kallad en Förste, ej heller en giriger en herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Ty en dåre talar om dårhet, och hans hjerta umgår med det ondt är, att han skall åstadkomma skrymteri, och predika om Herran villfarelse; att han dermed de hungroga själar utsvälta skall, och förmena dem törstiga drycken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Ty dens girigas regerande är icke utan skada; ty han finner listighet till att förderfva de elända med falskom ordom, då han den fattigas rätt tala skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Men Förstar skola hafva Förstliga tankar, och blifva dervid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Står upp, I stolta qvinnor, hörer mina röst; I döttrar, som så säkra ären, fatter med öronen mitt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Det är på år och dag till görandes, så skolen I, som säkra ären, bäfva; ty det varder ingen vinand, så blifver ock ingen upphemtning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Förskräcker eder, I stolta qvinnor; bäfver, I säkra. Det skall ske, att I skolen varda afklädda, blottada, gjordada om länderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Man skall beklaga om åkrar, ja, om de lustiga åkrar, och om de fruktamma vinträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Ty på mins folks åker skall växa törn och tistel; ja, ock öfver all glädjehus uti den glada staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Ty palatsen skola öfvergifven varda, och det stora mantalet i stadenom skall förminskas, så att torn och fäste skola blifva till eviga kulor, och vilddjurom till glädje, hjordom till bet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Tilldess att öfver oss utgjuten varder Anden af höjdene. Så skall då öknen varda till en åkermark, och åkermarken skall för en skog räknad blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Och rätten skall bo i öknene, och rättfärdigheten blifva på åkermarkene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Och rättfärdighetenes frukt skall vara frid, och rättfärdighetenes nytta skall vara evig stillhet och säkerhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Så att mitt folk skall bo uti fridshusom, uti trygga boningar, och i skön rolighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Men hagel skall vara nedre i skogenom, och staden skall ligga lågt nedre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Väl eder, som sån allestäds vid vattnet; ty der mågen I låta oxars och åsnars fötter gå uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Men ve dig, du förstörare, menar du, att du icke skall förstörd varda; och du föraktare, menar du, att man icke skall förakta, dig? När du hafver fullbordat din förstöring, skall du ock förstörd varda; när du hafver fullkomnat din föraktelse, så skall man förakta dig igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Herre, var oss nådelig; ty efter dig bide vi. Var deras arm bittida, så ock vår helsa uti bedröfvelsens tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Låt folken fly för det stora bullret, och Hedningarna förströdde varda, när du uppreser dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Då skall man taga eder upp såsom ett rof; såsom man upptager gräshoppor, och såsom man borträddar flogmatkar, då han öfverfaller dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Herren är upphöjd; ty han bor i höjdena. Han hafver gjort Zion full med dom och rättfärdighet~');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Och i din tid skall vara trohet och magt; helsa, vishet, klokhet och Herrans fruktan skola vara hans håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Si! deras bådskap ropa ute; fridsens Änglar gråta bitterliga (och säga):');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Stigarna äro öde, ingen går på vägomen mer; han håller intet förbund, han förkastar städerna, och aktar folket intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Landet står jämmerliga och ömkeliga; Libanon står skamliga förhuggen; Saron är såsom en slät mark, och Basan och Carmel äro förlagde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nu vill jag uppstå, säger Herren; nu vill jag upphöja mig; nu vill jag högt uppkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Med halm gån I hafvande, och strå föden I; eld skall uppäta eder med edart mod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Ty folken skola, till kalk uppbrände varda, såsom man afhugget törne upptänder med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Så hörer nu, I som fjerran åren, hvad jag gjort hafver, och I som när ären, märker mina starkhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'De syndare i Zion äro förskräckte; bäfvan är kommen de skrymtare uppå, och säga: Ho är ibland oss; som vid en förtärande eld bo kan? Ho är ibland oss, som vid en evig glöd bo kan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Den som vandrar uti rättfärdighet, och talar det rätt är; den som orätt hatar och girighet, och drager sina händer ifrå, att han icke tager mutor; den som stoppar sin öron till, att han icke hörer blodskulder, och håller sin ögon till, att han intet argt ser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Han skall bo i höjdene, och klipporna skola vara hans fäste och beskydd; hans bröd skall varda honom gifvet; på sitt vatten skall han vara viss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Din ögon skola få se Konungen i hans härlighet; du skall se landet förvidgadt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Så att ditt hjerta skall fast förundra sig, och säga: Hvar äro nu de Skriftlärde? Hvar äro rådgifvarena? Hvar äro cancellererna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Dertill skall du intet se det starka folket; det folk af djupt mål, dem man intet förnimma kan, och af outtydeliga tungo, den man icke förstå kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Se Zion, vår högtids stad; din ögon skola få se Jerusalem, en härlig boning; ett tabernakel, det icke bortfördt varder, hvilkets pålar skola aldrig upptagne varda, och hvilkets tåg aldrig skola sönderslitne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Ty Herren skall vara der mägtig när oss, och skola der vara vida vattugrafvar, så att intet roderskepp kan fara deröfver, ej heller några galejer dit skeppa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Ty Herren är vår domare, Herren är vår mästare, Herren är vår Konung; han hjelper oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Låt dem sätta på tågen, de skola likväl intet hålla. Alltså skola de ej heller utslå deras fåneko på mastene. Då skall mycket kosteligit byte utdeladt varda, så att de halte ock röfva skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Och ingen inbyggare skall säga: Jag är svag; (ty) folket, som deruti bor, skall hafva syndernas förlåtelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Kommer, I Hedningar, och hörer; I folk, akter uppå; jorden höre till, och hvad derinne är, verldenes krets med sin växt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Ty Herren är vred uppå alla Hedningar; och förtörnad uppå alla deras härar. Han skall gifva dem tillspillo, och öfverantvarda, dem till slagning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Deras slagne skola bortkastade varda, att stanken af deras kroppar skall uppgå, och bergen flyta i deras blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Och all himmelens här skall förruttna, och himmelen skall varda sammanlagd såsom ett bref; och all hans här skall förfalna, såsom ett löf förfalnar på vinträ, och såsom ett torrt löf på fikonaträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Ty mitt svärd är drucket i himmelen, och si, det skall fara neder på Edom, och öfver det spillgifna folket till straff.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Herrans svärd är fullt med blod, och är fett af fetma, af lambablod och bockablod, af vädrars njuratalg; ty Herren håller ett offer i Bozra, och en stor slagtning i Edoms land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'De enhörningar måste ock fara neder med dem, och stutarna med de gödda oxar; ty deras land måste drucket varda af blod, och deras jord fet varda af fetma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Ty det är Herrans hämndadagar, och ett vedergälloår, till att hämnas Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Då skola dess bäck er varda till tjäro, och dess jord till svafvel; ja, dess land skall varda till brinnande tjäro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Den hvarken dag eller natt utslockna skall; utan evinnerliga skall rök uppgå deraf, och skall öde blifva utan ända, så att ingen skall gå derigenom i evig tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Utan rördrommar och ufvar skola hafva det inne; nattugglor och korpar skola der bo; ty han skall draga ett snöre deröfver, att det skall öde varda, och ett murlod, att det skall tomt blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Så att dess herrar skola heta herrar utan land, och alle dess Förstar få en ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Och skola törne växa uti dess palats, nässlor och tistlar uti dess borger; och skola varda en drakaboning, och bet för strutsar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Då skola der troll och spökelse löpa hvar om annan, och en gast skall möta den andra; elfvor skola ock hafva der herberge, och finna der ro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Ufven skall ock hafva der sitt näste, och värpa der, ligga der, och utkläcka der, under dess skugga; och glador skola komma der tillsammans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Söker nu uti Herrans bok, och läser: Icke ett af dessa stycken skall fela; man skall ej sakna deraf antingen ett eller annat; ty han är den der igenom min mun bjuder, och hans Ande är den det tillhopahemtar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Han kastar lott öfver dem, och hans hand delar ut måttet ibland dem, att de skola hafva der arfvedel inne evinnerliga, och blifva deruti utan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Men öknen och ödemarken skall lustig varda, och vildmarken skall glädjas och blomstras, såsom en lilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Hon skall blomstras och fröjdas i all lust och glädje; ty Libanons härlighet är henne gifven, Carmels och Sarons skönhet. De se Herrans härlighet, vår Guds majestät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Stärker de trötta händer, och vederqvicker de magtlösa knä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Säger till de förtviflada hjerta: Varer vid godt mod, frukter eder intet. Si, edar Gud, som vedergäller, han kommer till att hämnas, och skall hjelpa eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Då skola de blindas ögon upplåtne varda, och de döfvas öron skola, öppnade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Då skola de halte springa såsom en hjort, och de dumbas tunga skall lofsjunga; ty vatten skola flyta i öknene hit och dit, och strömmar i vildmarkene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Och der tillförene hafver torrt varit, der skola dammar vara, och der vattulöst hafver varit, der skola rinnande källor vara; der tillförene ormar legat hafva, der skall gräs, rö och säf stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Och der, skall vara en stig och väg, hvilken den helige vägen heta skall, så att ingen oren skall gå deruppå, och den samme skall vara för dem, att man deruppå gå skall; så att ock det fåvitske icke behöfva der ville fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Der skall intet lejon vara, och intet rifvande djur träda deruppå, eller der funnet varda; utan man skall gå der fri och säker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Och Herrans förlöste skola igenkomma, och komma till Zion med glädje; evig fröjd skall vara öfver deras hufvud; lust och glädje skola de få, och värk och suckan måste bortgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Och det begaf sig, uti fjortonde årena Konungs Hiskia, drog Konungen af Assyrien, Sanherib, upp emot alla Juda, fasta städer och vann dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Och Konungen af Assyrien sände RabSake, ifrå Lachis till Jerusalem, till Konung Hiskia, med stora magt, och han trädde fram till vatturännilen af öfra dammen, på den vägen vid klädefärgarens åker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Och gingo ut till honom Eliakim, Hilkia son, hofmästaren, och Sebna skrifvaren, och Joah, Assaphs son, cancelleren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Och RabSake sade till dem: Säger dock Hiskia: Så säger den store Konungen, Konungen i Assyrien: Hvad är det för en tröst, der du förlåter dig uppå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Jag gissar väl, att du låter dig tycka, att du ännu råd och kraft hafver till att strida. Uppå hvem förlåter du dig då, att du äst mig affällig vorden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Förlåter du dig uppå den sönderbrutna rörstafven Egypten, hvilken, då man stödjer sig vid honom, går han honom upp i handena, och genomstinger henne? Alltså gör Pharao, Konungen uti Egypten, allom dem som förlåta sig uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Om du vill säga mig: Vi förlåte oss uppå Herran vår Gud; är nu icke han den, hvilkens höjder och altare Hiskia bortkastat hafver, och sagt till Juda och Jerusalem: För detta altaret skolen I tillbedja?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Nu väl, tag det före med minom herra, Konungenom i Assyrien, jag vill få dig tutusend hästar; låt se, om du kan när dig åstadkomma de som rida deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Huru vill du då blifva för enom höfvitsman, den en af mins herras ringesta tjenare är? Och du förlåter dig uppå Egypten, för vagnars och resenärars skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Dertill, menar du, att jag utan Herran hit uppdragen är uti landet, till att förderfva det? Ja, Herren sade till mig: Drag upp i detta land; och förderfva det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Men Eliakim, och Sebna, och Joah sade till RabSake: Käre, tala med dina tjenare på Syrisko; ty vi förstå det väl; och tala icke på Judisko med oss, för folksens öron, som på muren är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Då sade RabSake: Menar du, att min herre hafver sändt mig till din herra, eller till dig, att tala dessa orden; och icke mycket mer till de män, som på muren sitta; att de med eder skola äta sin egen träck, och dricka af sitt eget vatten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Och RabSake stod, och ropade högt på Judisko, och sade: Hörer den stora Konungens ord, Konungens i Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Så säger Konungen: Låter icke Hiskia bedraga eder; ty han kan intet frälsa eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Och låter icke Hiskia, förtrösta eder uppå Herran, att han säger: Herren skall hjelpa oss, och denne staden skall icke gifven varda uti Konungens hand af Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Hörer Hiskia intet: ty så säger Konungen af Assyrien: Görer mig till vilja, och går till mig ut, så skolen I hvar och en äta af sitt vinträ, och af sitt fikonaträ, och dricka af sin brunn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Tilldess jag kommer, och hemtar eder uti ett land, sådant som edart land är; ett land, der korn och vin uti är; ett land, der bröd och vingårdar uti äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Låter icke Hiskia bedraga eder, att han säger: Herren skall förlossa oss. Hafva ock Hedningarnas gudar hvar friat sitt land ifrå Konungens hand af Assyrien?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Hvar äro de gudar i Hamath och Arphad? Hvar äro de gudar i Sepharvaim? Hafva de ock friat Samarien utu mine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Hvilken af alla dessa lands gudar hafver hulpit sitt land utu mine hand, att Herren skulle frälsa Jerusalem för mine hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Men de tigde stilla, och svarade honom intet; ty Konungen hade budit, och sagt: Svarer honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Då kommo Eliakim, Hilkia son, hofmästaren, och Sebna skrifvaren, och Joah, Assaphs son, cancelleren, med sönderrifven kläder, och gåfvo honom tillkänna RabSake ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Då nu Konung Hiskia detta hörde, ref han sin kläder sönder, och svepte en säck omkring sig, och gick in uti Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Och sände Eliakim, hofmästaren, och Sebna skrifvaren, med de äldsta Presterna, omsvepta med säcker, till Propheten Esaia, Amos son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Att de skulle säga till honom: Så säger Hiskia: Detta är en bedröfvelses, straffs och försmädelses dag, och går såsom när barnen äro komne till födelsen, och ingen magt är till att föda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'O! att dock Herren din Gud ville höra RabSake ord, hvilken hans herre, Konungen i Assyrien, utsände till att försmäda lefvandes Gud, och till att förlasta med sådana ordom, som Herren din Gud hört hafver; och att du ville upphäfva ena bön för de igenlefda, som ännu för handene äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Och Konungens Hiskia tjenare kommo till Esaia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Men Esaia sade till dem: Så säger edrom herra: Herren säger alltså: Frukta dig intet för de ord, som du hört hafver, med hvilkom Konungens tjenare af Assyrien mig försmädat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Si, jag skall göra honom ett annat mod, och han skall något få höra, deraf han skall igen hemfara i sitt land, och jag skall falla honom med svärd uti hans land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Men då RabSake igenkom, fann han Konungen af Assyrien stridandes emot Libna; ty han hade hört, att han var ifrå Lachis dragen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Förty ett rykte kom ifrå Thirhaka, de Ethiopers Konung, sägandes: Han är utdragen emot dig till att strida. Då han nu detta hörde, sände han båd till Hiskia, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Säger Hiskia, Juda Konunge, alltså: Låt icke din Gud bedraga dig, den du förlåter dig uppå, och säger: Jerusalem skall icke gifvit varda uti Konungens hand af Assyrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Si, du hafver hört, hvad de Konungar af Assyrien allom landom gjort hafva, och förderfvat dem; och du skulle friad varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Hafva ock Hedningarnas gudar undsatt de land, som mine fäder förderfvat hafva; såsom är Gosan, Haran, Rezeph, och Edens barn i Thelassar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Hvar är Konungen i Hamath, och Konungen i Arphad, och Konungen i den stadenom Sepharvaim, Heva och Iva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Och då Hiskia hade undfått brefvet af båden, och läsit det, gick han upp till Herrans hus, och höll det ut för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Och Hiskia bad till Herran, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Herre Zebaoth, du Israels Gud, som öfver Cherubim sitter, du äst allena Gud öfver all Konungarike på jordene; du hafver gjort himmel och jord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Herre, nederböj din öron, och hör; Herre, låt upp din ögon, och se; hör dock all Sanheribs ord, som han utsändt hafver, till att försmäda lefvandes Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Sant är det, Herre, Konungarna i Assyrien hafva öde gjort all Konungarike med deras land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Och hafva kastat deras gudar uti eld; ty de voro icke gudar, utan menniskohänders verk, trä och sten; de äro förgjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Men nu, Herre, vår Gud, hjelp oss ifrå hans hand, på det att all Konungarike på jordene måga förnimma, att du äst Herre allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Då sände Esaia, Amos son, till Hiskia, och lät säga honom: Så säger Herren Israels Gud, om det du mig bedit hafver om Konung Sanherib af Assyrien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Så är detta det Herren om honom säger: Jungfrun, dottren Zion, föraktar dig, och bespottar dig, och dottren Jerusalem rister hufvudet efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Hvem hafver du förhädt och försmädt? Öfver hvem hafver du upphäfvit röstena? Och du hafver upphäfvit din ögon emot den Heliga i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Genom dina tjenare hafver du försmädat Herran, och säger: Genom mina många vagnar är jag uppdragen uppå bergshöjderna vid Libanons sido, och hafver afhuggit hans höga cedreträ, med de utkorade furoträ, och är kommen öfver höjdena, intill ändan på denna skogen på landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Jag hafver grafvit och druckit vattnet, och mitt fotbjelle hafver uttorkat all förvarad vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Men hafver du icke hört, att jag i förtiden alltså gjort, och af ålder så handlat hafver, och gör desslikes så ännu, att fasto städer förstöras uti stenhopar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Och deras inbyggare försvagade och förtviflade varda, och på skam komma, och varda till gräs på markene, och till grön ört, såsom hö på taken, hvilket borttorkas, förr än det moget varder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Men jag känner dina boning väl, ditt uttåg och intåg, och ditt rasande emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Efter du nu rasar emot mig, och ditt högmod är kommet upp för min öron, skall jag sätta dig en ring i dina näso, och ett bett i din mun, och skall föra dig den vägen hem igen, den du kommen äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Och detta skall vara dig för ett tecken: Ät i detta året hvad förtrampadt är; uti de andra årena hvad sjelft växer; uti tredje årena sår och uppskärer, planterer vingårdar, och äter deras frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Ty de frälste af Juda hus, och de öfverblefne, skola åter rota sig nedantill, och ofvantill bära frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Ty utaf Jerusalem skola ännu utgå de som qvarblefne äro, och de frälste utaf Zions berg. Detta skall Herrans Zebaoths nitälskan göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Derföre säger Herren om Konungen af Assyrien alltså: Hall skall icke komma in uti denna staden, och skall ej heller skjuta der en pil in, och icke en sköld komma der före, och skall han ingen skans göra deromkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Utan skall vända den vägen om igen, som han kommen är, så att han uti denna staden intet kommer, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Ty jag vill beskydda denna staden, så att jag skall uthjelpa honom för mina skull, och för min tjenares Davids skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Då for ut en Herrans Ängel, och slog uti det Assyriska lägret hundrade fem och åttatio tusend män; och då de om morgonen bittida uppstodo, si, då låg der allt fullt med döda kroppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Och Konungen af Assyrien, Sanherib, bröt upp, drog sina färde, och vände om hem igen, och blef i Nineve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Och det begaf sig, att då han tillbad uti sins guds Nisrochs huse, slogo honom hans söner Adrammelech och SarEzer med svärd, och flydde in uti det landet Ararat; och hans son EsarHaddon vardt Konung i hans stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'På den tiden vardt Hiskia dödssjuk. Och Propheten Esaia, Amos son, kom till honom, och sade till honom: Så säger Herren: Beställ om ditt hus; ty du måste dö, och icke vid lif blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Då vände Hiskia sitt ansigte till väggena, och bad till Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Och sade: Tänk dock, Herre, huru jag för dig vandrat hafver uti sanning, med fullkommeligo hjerta, och hafver gjort hvad dig hafver täckt varit. Och Hiskia gret svårliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Då kom Herrans ord till Esaia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Gack bort, och säg Hiskia: Så säger Herren dins faders Davids Gud: Jag hafver hört dina bön, och sett dina tårar; si, jag vill ännu föröka dina dagar femton år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Och skall fria dig med denna staden utu Konungens hand af Assyrien; ty jag vill väl beskärma denna staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Och haf detta för ett tecken af Herranom, att Herren detta göra skall, som han sagt hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Si, jag vill tillbakadraga skuggan på Ahas säjare; tio streck, de han öfverlupit hafver; så att solen skall gå tillbaka tio streck, de hon på säjaren öfverlupit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Detta är Hiskia skrift, Juda Konungs, då han hade krank varit, och var helbregda vorden af sine krankhet:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Jag sade: Nu måste jag fara till helvetes portar, förr än jag det mig förmodde, och tänkte ännu länger lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Jag sade: Nu måste jag icke mer se Herran, ja, Herran uti de lefvandes lande; nu måste jag icke mer se menniskor, när dem som deras tid utlefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Min tid är borto, och ifrå mig tagen, såsom ens herdas hydda; och jag skär mitt lif tvärtaf såsom en väfvare; han sliter mig sönder såsom en klen tråd; du lyktar dagen för mig, förr än aftonen kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Jag tänkte: Måtte jag dock lefva till morgons; men han sönderbröt mig all min ben, såsom ett lejon; ty du lyktar dagen för mig, förr än aftonen kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Jag lät såsom en trana och en svala, och knurlade såsom en dufva; min ögon ville mig brista. Herre, jag lider nöd, lisa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'O! huru vill jag (gladeliga) tala, efter han mig tillsagt hafver, och gör det ock; derföre vill jag i alla mina lifsdagar tacka för denna min själs bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Herre, deraf lefver man, och mins andas lif står alltsammans derutinnan; ty du lätst mig somna, och gjorde mig lefvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Si, om tröst var mig stor ängslan; men du lätst dig vårda om mina själ ganska hjerteliga, att hon icke förderfvas skulle; ty du kastade alla mina synder bakom dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Ty helvetet lofvar dig intet; så prisar dig icke heller döden, och de som uti gropena fara, vänta intet efter dina sanning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Utan allena de, som lefva, lofva dig, såsom ock jag nu gör. Fadren skall lära barnen dina sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Herre, hjelp mig, så vilje vi sjunga mina visor, så länge vi lefve, uti Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Och Esaia bad, att man skulle taga ett plåster af fikon, och lägga uppå hans böld, att han måtte helbregda varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Men Hiskia sade: Hvilket ett tecken är detta, att jag upp till Herrans hus gå skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'På den tiden sände MerodachBaladan, Baladans son, Konungen i Babel, bref och skänker till Hiskia; ty han hade hört, att han hade varit sjuk, och var helbregda vorden igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Då fröjdade sig Hiskia, och viste dem fataburen, silfver och guld, speceri, kostelig salvo, och all sin tyghus, och all den skatt, som han hade. Ingen ting var, som Hiskia dem icke viste, i sino huse och i sitt våld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Då kom Propheten Esaia till Konungen Hiskia, och sade till honom: Hvad säga dessa männerna, och hvadan komma de till dig? Hiskia sade: De komma fjerranefter till mig, nämliga ifrå Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Men han sade: Hvad hafva de sett uti dino huse? Hiskia sade: Allt det i mino huse är, hafva de sett, och intet är i mina håfvor, det jag dem icke vist hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Och Esaia sade till Hiskia: Hör Herrans Zebaoths ord:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Si, den tid kommer, att allt det uti dino huse är, och hvad dine fäder församlat hafva, intill denna dag, skall till Babel bortfördt varda, så att intet skall qvart blifva, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Dertill skola de taga din barn, som af dig komma skola, och du födandes varder, och de måste vara kamererare i Konungens gård i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Och Hiskia sade till Esaia: Herrans ord är godt, det du talar; och sade: Vare dock frid och trohet i mina dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Tröster, tröstar mitt folk, säger edar Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Taler ljufliga med Jerusalem, och prediker för thy, att dess tid är fullbordad; ty dess missgerning är förlåten; ty det hafver fångit dubbelt af Herrans hand för alla sina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Ens Predikares röst är i öknene: Bereder Herranom väg, görer en jemnan stig på markene vårom Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Alle dalar skola upphöjde varda, och all berg och högar skola förnedrade varda, och det ojemnt är skall jemnas, och det oslätt är skall slätt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Ty Herrans härlighet skall uppenbarad varda; och allt kött skall tillsammans se, att Herrans mun talar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'En röst säger: Predika. Och han sade: Hvad skall jag predika? Allt kött är hö, och all dess godhet är såsom ett blomster i markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Höet torkas bort, blomstret förvissnar; ty Herrans ande blås derin; ja, folket är höet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Höet torkas bort, blomstret förvissnar; men vår Guds ord blifver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Zion, du som predikar, stig upp på ett högt berg; Jerusalem, du som predikar, häf upp dina röst med magt. Häf upp, och frukta dig intet; säg Juda städer: Si, der är edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Ty si, Herren, Herren kommer väldeliga, och hans arm skall varda rådandes. Si, hans arbete och hans gerning skall icke varda utan frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Han skall föda sin hjord såsom en herde; han skall församla lamben i sin famn, och bära dem i sitt sköt, och fordra de lambdigra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Ho mäter vattnet med handene, och fattar himmelen med sin spann, och begriper jordena med tre fingers mått, och väger bergen med en vigt, och högarna med en våg?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Ho undervisar Herrans Anda; och hvad rådgifvare lärer honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Hvem frågar han om råd, den honom förstånd gifver, och lärer honom rättsens väg, och lärer honom klokhet, och viser honom förståndsens väg?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Si, Hedningarna äro aktade såsom en droppe den uti ämbaret blifver, och såsom ett grand det i vågskålene blifver. Si, öarna äro såsom ett litet stoft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Libanon vore allt för litet till eld, och dess djur allt för få till bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Alle Hedningar äro intet för honom, och såsom platt intet aktade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Vid hvem viljen I då likna Gud? Eller hvad viljen I göra honom för en liknelse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'En mästare gjuter väl ett beläte, och guldsmeden förgyller det, och gör silfkedjor deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Sammalunda, den ett armt häfoffer förmår, han utväljer ett trä, som icke förruttnar, och söker en klok mästare dertill, den ett beläte bereder, som blifver beståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Veten I intet? Hören I intet? Är detta icke kungjordt eder tillförene? Hafven I icke förstått det af jordenes begynnelse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Han sitter öfver jordenes krets, och de som bo deruppå äro såsom gräshoppor; den der himmelen uttänjer såsom ett tunnt skinn, och utsträcker det såsom ett tjäll, der man bor uti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Den der Förstarna omintetgör, och domarena på jordene förlägger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Lika som deras slägte hvarken hade plantering eller säd, eller rot i jordene; så att de borttorkas, när ett väder blås på dem, och en väderflaga förer dem bort, såsom agnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Vid hvem viljen I då likna mig, den jag lik är? säger den Helige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Upplyfter edor ögon i höjdena, och ser; ho hafver de ting skapat, och förer deras här fram efter tal? Den som kallar dem alla vid namn. Hans förmåga och starka kraft är så stor, att honom icke ett fela kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Hvi säger du då, Jacob, och du, Israel, talar: Min väg är Herranom fördold, och min rätt går framom min Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Vetst du icke? Hafver du icke hört? Herren, den evige Gud, som jordenes ändar skapat hafver, varder hvarken trött eller mödd. Hans förstånd är oransakeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Han gifver dem trötta kraft, och dem magtlösom starkhet nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'De ynglingar varda trötte, och uppgifvas, och de kanske män falla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Men de som vänta efter Herran, de få en ny kraft, så att de skola uppfara med vingar såsom örnar; de skola löpa, och icke uppgifvas; de skola vandra, och icke trötte varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Tige öarna för mig, och folken stärke sig, träde fram, och tale; låt oss gå till rätta med hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Ho hafver uppväckt den rättfärdiga östanefter? Ho kallade honom att han gå skulle? Ho gaf Hedningarna och Konungarna för honom, att han dem öfvermägtig vardt, och gaf dem för hans svärd, såsom stoft, och för hans båga, såsom förströdda agnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Och han jagade efter dem, och gick det igenom med frid, och vardt intet trött af vägen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Ho verkar det, och gör det, och kallar alla menniskor, den ena efter den andra, allt ifrå begynnelsen? Jag Herren är både den förste och den siste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Då öarna sågo det, fruktade de sig, och jordenes ändar förskräckte sig; de nalkades, och kommo fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Den ene halp den andra, och sade till sin nästa: Var tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Timbermannen tog guldsmeden till sig, och gjorde bleckskifvorna släta med hammaren på städet, och sade: Det vill väl stå. Och de fäste det med naglar, att det icke skulle stå ostadigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Men du Israel, min tjenare, Jacob, den jag utvalt hafver, du Abrahams mins väns säd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Den jag styrkt hafver allt ifrå verldenes ända, och hafver kallat dig, ifrå hennes väldiga, och sade till dig: Du skall vara min tjenare; ty jag utkorar dig, och bortkastar dig icke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Frukta dig intet, jag är med dig; vik icke af, ty jag är din Gud. Jag styrker dig, jag hjelper dig ock, jag håller dig vid magt, genom mina rättfärdighets högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Si, alle de som dig hätske äro, skola till spott och skam varda, och blifva såsom intet, och de män, som med dig träta, skola förgås;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Så att du skall fråga efter dem, och icke finna dem. De män, som med dig kifva, skola, varda såsom intet, och de män, som emot dig strida, skola få en ända;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Ty jag är Herren din Gud, den dina högra hand stärker, och säger till dig: Frukta dig intet; jag hjelper dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Så frukta dig nu intet, du matker Jacob, I fattige hop Israel. Jag hjelper dig, säger Herren, och din förlossare, den Helige i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Si, jag hafver gjort dig till en ny skarp tröskovagn, den taggar hafver, att du skall tröska berg och sönderstöta dem, och göra högarna såsom stoft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Du skall förströ dem, att vädret skall föra dem bort, och väderflagor förskingra dem; men du skall vara glad i Herranom, och berömma dig af Israels Heliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'De elände och fattige söka vatten, och der är intet. Deras tunga borttorkas för törst; men jag Herren vill höra dem. Jag Israels Gud vill icke öfvergifva dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Utan jag vill öppna vattufloder på höjderna, och källor midt på markene. Jag vill göra öknena till vattusjöar, och torra landet till vattukällor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Jag vill gifva i öknene cedren, furo, myrten och oljoträ. Jag vill gifva på markene gran, bok och buxbom tillhopa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'På det man må se och känna, och förmärka och förstå tillsammans, att Herrans hand hafver detta gjort, och den Helige i Israel hafver detta skapat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Så låter edra sak komma fram, säger Herren. Bärer fram der I uppå stån, säger Konungen i Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Låt dem träda fram, och förkunna oss hvad tillkommande är; förkunner oss och propheterer något framföreåt; låt oss akta deruppå med vår hjerta, och märka huru det härefter gå skall, eller låter oss dock höra hvad tillkommande är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Förkunner oss hvad härefter komma skall, så vilje vi märka, att I ären gudar. Görer antingen godt eller ondt, så vilje vi derom tala, och skåda tillsammans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Si, I ären af intet, och edart verk är ock intet, och den eder utväljer, är en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Men jag uppväcker en af nordan, och han kommer östanefter. Han skall predika dem i mitt Namn, och han skall gå öfver de väldiga, såsom öfver ler, och skall trampa ler, såsom en krukomakare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Ho kan något förkunna af begynnelsen, att vi måge begripat; eller prophetera framföreåt, att vi måge säga: Du talar rätt? Men här är ingen förkunnare, ingen som något höra låter, ingen som af eder ett ord höra må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Jag är den förste, som till Zion säger; Si, der är det, och gifver Jerusalem Predikare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Men jag skådar dit, men der är ingen; och ser ibland dem, men der är ingen rådgifvare. Jag frågar dem, men då svara de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Si, det är alltsammans vedermöda, och intet med deras väsende; deras afgudar äro icke utan ett väder och fåfängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Si min Tjenare, jag uppehåller honom, och min utkorade, i hvilkom min själ väl behagar. Jag hafver gifvit honom min Anda; han skall låta komma rätt ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Han skall icke skria eller ropa, och hans röst skall man icke höra på gatomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'En förbråkad rö skall han icke sönderbryta, och en rykande veka skall han icke utsläcka. Han skall lära hålla rätten i sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Han skall icke vara knorrisk eller grufvelig, på det han skall sätta rätt på jordene; och öarna skola vänta efter hans lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Så säger Herren Gud, som himmelen skapar och utsträcker, den som jordena gör med det deruppå växer; den som folkena, som deruppå är, gifver lif, och anda dem som gå deruppå:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Jag Herren hafver kallat dig i rättfärdighet, och fattat dig vid handena, och bevarat dig, och hafver gifvit dig till ett förbund i folkena, Hedningomen till ett ljus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Att du skall öppna de blindas ögon, och föra fångarna utu fängelse, och de som sitta i mörkret utu fångahuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Jag Herren, det är mitt Namn; och jag skall icke gifva mina äro enom androm, ej heller mitt lof afgudomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Si, hvad komma skall förkunnar jag framföreåt, och förkunnar ny ting; förr än det sker, låter jag eder det höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Sjunger Herranom en ny viso, hans lof är intill verldenes ändar; de som i hafvet fara, och hvad deruti är; öarna, och de som der bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Roper högt, I öken och städer deruti, samt med de byar der Kedar bor; sig fröjde de som bo på klippomen, och rope utaf bergshöjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Låter dem gifva Herranom ärona, och förkunna hans lof på öarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Herren varder utdragandes såsom en rese; han skall uppväcka nit såsom en krigsman; han skall fröjda sig, och ett gny göra; han skall sinom fiendom öfverhändig blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Jag tiger väl till en tid, och är stilla och håller mig; men nu vill jag ropa såsom en barnföderska; jag skall föröda och uppsvälja dem alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Jag skall föröda berg och högar, och borttorka allt deras gräs; och skall göra vattuströmmarna till öar, och uttorka sjöarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Men de blinda vill jag leda på den vägen, som de icke veta; Jag vill föra dem på de stigar, som de icke känna; jag vill sätta mörkret för dem till ett ljus, och det oslätt är, till jemnhet; detta vill jag göra dem, och icke öfvergifva dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Men de som förlåta sig på afgudar, och säga till gjuten beläte: I ären våre gudar; de skola tillbakavända, och till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Hörer, I döfve, och ser härtill, I blinde, att I mågen se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Ho är så blind som min tjenare? Och ho är så döf som mitt bådskap, den jag sänder? Ho är så blind som den fullkomlige, och så blind såsom Herrans tjenare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Man predikar väl mycket, men de hållat intet; man säger dem nog, men de vilja icke hörat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Likväl vill Herren dem godt, för sina rättfärdighets skull, och att han skall göra sin lag härlig och stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Det är ett bedröfvadt och skinnadt folk; de äro allesammans besnärde uti kulor, och bortgömde i fångahus; de äro vordne till rof, och ingen hjelpare är; beskinnade, och ingen är, som säger: Få dem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Hvilken är ibland eder, som aktar härtill; märker, och hörer hvad härefter kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Ho hafver öfvergifvit Jacob till sköfvels, och Israel röfvarom? Hafver icke Herren gjort det, emot hvilkom vi syndat hafve? Och de ville icke vandra på hans vägar, och lydde icke hans lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Derföre hafver han utskuddat öfver dem sina vredes grymhet, och en krigsmagt, och hafver upptändt dem allt omkring; men de aktade det intet. Han fängde uppå dem, men de lade det intet uppå hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Och nu, säger Herren, den dig skapat hafver, Jacob, och den dig gjort hafver, Israel: Frukta dig intet; ty jag hafver förlossat dig; jag hafver kallat dig vid ditt namn, du äst min.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Ty om du går igenom vatten, vill jag vara när dig, att strömmarna icke skola dränka dig; och om du går uti elden, skall du intet bränna dig, och lågen skall intet bita uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Ty jag är Herren din Gud, den Helige i Israel, din Frälsare. Jag hafver gifvit Egypten, Ethiopien och Seba till försoning i din stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Efter du så dyr för min ögon aktad äst, måste du ock härlig vara, och jag hafver dig kär; derföre gifver jag menniskor uti din stad, och folk för dina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Så frukta dig nu intet; ty jag är när dig. Jag vill låta komma dina säd östanefter, och vill församla dig vestanefter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Och skall säga till norr: Gif; och till söder: Förhåll icke; haf mina söner hit från fjerran, och mina döttrar ifrå verldenes ända;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Alle de som med mino Namne nämnde äro, nämliga de jag skapat hafver till mina härlighet, tillredt dem, och gjort dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Låt framträda det blinda folket, som dock ögon hafver, och de döfva, som dock öron hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Låt alla Hedningar tillhopakomma, och folken församla sig; hvilken är ibland dem som detta förkunna kan, och låta oss höra framföreåt hvad som ske skall? Låt dem hafva deras vittne fram, och bevisat, så får man hörat, och säga: Det är sanningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Men I ären min vittne, säger Herren, och min tjenare, den jag utvalt hafver; på det I skolen vetat, och tro mig, och förståt, att jag äret. Förr mig är ingen Gud gjord, så varder ock ingen efter mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Jag, Jag är Herren, och utan mig är ingen Frälsare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Jag hafver förkunnat det, och hafver desslikes hulpit, och hafver eder det säga låtit, och ingen främmande gud är ibland eder. I ären min vittne, säger Herren, så är jag Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Och är jag förr än någor dag var, och ingen är den som utu mine hand frälsa kan. Jag verkar, ho vill afvända det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Så säger Herren, edar förlossare, den Helige i Israel: För edra skull hafver jag till Babel sändt, och hafver nederslagit alla bommar, och jagat de sörjande Chaldeer till skepps.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Jag är Herren, edar Helige, som Israel skapat hafver, edar Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Så säger Herren, som en väg gör i hafvet, och en stig i stark vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Den der utförer vagn och häst, här och magt, så att de i enom hop ligga, och intet uppstå; att de utslockna, såsom en veke utslocknar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Tänker icke uppå det gamla, och akter icke uppå det förra varit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Ty si, jag vill göra en ny ting; rätt nu skall det uppgå, att I skolen förnimma, att jag gör en väg i öknene, och vattuströmmar uti ödemarkene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Att djuret på markene skall prisa mig, drakar och strutser; ty jag vill gifva vatten uti öknene, och strömmar uti ödemarkene, till att gifva mino folke, minom utkoradom dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Detta folket hafver jag tillredt mig, det skall förtälja min pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Icke att du Jacob hafver kallat mig, eller att du Israel hafver arbetat om mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Icke hafver du framburit mig dins bränneoffers får, eller hedrat mig med ditt offer. Jag hafver icke haft lust till dina tjenst i spisoffer; jag hafver ej heller lust af ditt arbete uti rökelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Mig hafver du icke köpt calmos för penningar; mig hafver du icke fyllt med dins offers fetma; ja, mig hafver du arbete gjort uti dinom syndom, och gjort mig mödo uti dinom missgerningom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Jag, Jag utstryker din öfverträdelse för mina skull, och kommer dina synder intet ihåg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Drag mig till minnes; låt oss gå med hvarannan till rätta; säg, huru du vill rättfärdig varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Dine fäder hafva syndat, och dine lärare hafva misshandlat emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Derföre hafver jag ohelgat helgedomens Förstar, och gifvit Jacob tillspillo, och Israel till försmädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Så hör nu, min tjenare Jacob, och Israel, den jag utkorat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Så säger Herren, den dig gjort och tillredt hafver, och den dig biståndig är allt ifrå moderlifvet: Frukta dig intet, min tjenare Jacob, och du fromme, den jag utkorat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Ty jag vill utgjuta vatten uppå, den törstiga, och strömmar uppå den torra; jag vill utgjuta min Anda uppå dina säd, och min välsignelse uppå dina efterkommande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Att de växa skola såsom gräs, såsom pilträ vid vattubäcker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Denne skall säga: Jag är Herrans, och den andre varder nämnd med Jacobs namn; och denne skall tillskrifva Herranom med sine hand, och skall med Israels namn nämnd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Så säger Herren Israels Konung, och hans förlossare, Herren Zebaoth: Jag är den förste, och jag är den siste, och utan mig är ingen Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Och ho är mig lik, den der kallar och förkunnar, och bereder mig det, jag som folken sätter ifrå verldenes begynnelse? Låt dem förkunna tecken, och hvad komma skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Frukter eder intet, och varer icke förskräckte. Hafver jag icke på den tiden låtit det höra, och förkunnat dig det? fy I ären min vittne: Är någor Gud utan mig? Ingen tröst är, jag vet ju ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'De afgudamakare äro allesammans fåfängelige, och der de mycket af hålla är intet nyttigt; de äro deras vittne, och se intet, märka ock intet; derföre måste de på skam komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Ho äro de som en gud göra, och gjuta en afgud, den intet nyttig är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Si, alle deras stallbröder komma på skam; ty de äro mästare utaf menniskom. Om de alle tillsammanträdde, så måste de likväl frukta sig, och på skam komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Den ene smider jernet med tång, arbetar det i glödene, och bereder det med hammaren, och arbetar deruppå med alla sins arms magt; lider ock hunger, tilldess han icke mer förmår; dricker ock icke vatten, tilldess han vanmägtas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Den andre timbrar på trä, och mäter det med snöre, och utmärker det med krito, och tillhugger det, och afcirklar det, och gör det till ett mansbeläte, såsom en dägelig menniska, den i huse bo skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Han går ibland trän i skogenom, att han skall hugga cedreträ, och taga bok och ek; ja, ett cedreträ, det planteradt, och af regne växt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Och doger menniskomen till att bränna; deraf man tager till att värma sig med, och det man upptänder till att baka der bröd med; af det samma gör han en gud, och tillbeder det; han gör en afgud deraf, och faller der på knä före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Hälftena uppbränner han i eldenom, och vid den andra hälftena äter han kött; han steker ena stek, och mättar sig; värmer sig, och säger: Huj, jag är varm vorden; jag hafver min lust af eldenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Men det qvart är gör han till en gud, att det skall vara hans afgud; der knäfaller han före, och böjer sig före, och beder, och säger: Frälsa mig, ty du äst min gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'De veta intet, och förstå intet; ty de äro förblindade, så att deras ögon se intet, och deras hjerta kunna intet märka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Och de gå icke till sitt hjerta; der är intet förnuft eller förstånd, att de dock tänka måtte: Jag hafver hälftena uppbränt i eldenom, och hafver på kolen bröd bakat, och stekt kött, och ätit, och skulle jag nu det som qvart är göra till en styggelse? Och skulle jag knäfalla för enom stock?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Det gifver asko, och kjuser hjertat, som sig dertill böjer, och kan icke fria sina själ; likväl tänker han icke: Månn icke något bedrägeri vara i mine högra hand?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Tänk deruppå, Jacob och Israel; ty du äst min tjenare; jag hafver beredt dig, att du skall vara min tjenare. Israel, förgät mig icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Jag utstryker dina missgerningar såsom ett moln, och dina, synder såsom ena dimbo. Vänd dig till mig; ty jag förlossar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Fröjder eder, I himlar; Herren hafver det gjort. Jubilera, du jord, härnedre; I berg, glädjens med fröjd, skogen och all trän deruti; ty Herren hafver förlossat Jacob, och är härlig i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Så säger Herren, din förlossare, den dig af moderlifvet beredt hafver: Jag är Herren, som allt gör, den der utsträcker himmelen allena, och utvidgar jordena utan hjelp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Den de spåmans tecken omintetgör, och gör de tecknatydare galna; den de visa tillbakadrifver, och gör deras konst till dårskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Men han stadfäster sins tjenares ord, och sins bådskaps råd fullkomnar; den till Jerusalem säger: Var besutten; och till Juda städer: Varer byggde; och jag upprättar deras öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Jag, som talar till djupet: Försvinn; och till strömmarna: Förtorkens;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Jag, som säger till Cores: Han är min herde, och skall fullkomna all min vilja, så att man skall säga till Jerusalem: Var byggd; och till templet: Var grundadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Så säger Herren till Cores, sin smorda, den jag vid hans högra hand fattar, att jag skall underkufva Hedningarna för honom, och lösa Konungenom svärdet ifrå; på det att portarna skola öppnade varda för honom, och dörrarna icke igenlästa blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Jag vill gå för dig, och göra backarna till jemna mark; jag vill sönderslå de koppardörrar, och sönderbryta de jernbommar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Och skall gifva dig de fördolda rikedomar, och de bortgömda klenodier, på det att du skall förnimma att jag, Herren Israels Gud, dig vid ditt namn nämnt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'För Jacob min tjenares skull, och för Israel mins utkorades skull; ja, jag kallade dig vid ditt namn, och nämnde dig, då du ännu intet kände mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Jag är Herren, och eljest ingen mer; ingen Gud är utan jag. Jag tillrustade dig, då du ännu intet kände mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'På det man skall förnimma, både ifrån östan och vestan, att utan mig är intet; jag är Herren, och ingen mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Jag, som gör ljuset, och skapar mörkret; jag, som frid gifver, och skapar det onda; jag är Herren, som allt detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Dryper, I himlar, ofvanefter, och skyn regne rättfärdighet; jorden öppne sig, och bäre salighet, och rättfärdighet växe till med, jag Herren skapar honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Ve honom, som träter med sinom skapare, nämliga krukan med krukomakaren. Månn leret säga till krukomakaren: Hvad gör du? Du bevisar icke dina händer på ditt verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Ve honom, som till fadren säger: Hvi hafver du aflat mig? och till qvinnona: Hvi födde du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Så säger Herren, den Helige i Israel, och hans mästare: Äsker tecken af mig, viser min barn och mina händers verk till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Jag hafver gjort jordena, och skapat menniskona deruppå; jag är den, hvilkens händer himmelen utsträckt hafva, och budit allom hans här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Jag hafver uppväckt honom uti rättfärdighet, och jag skall göra alla hans vägar släta; han skall bygga min stad, och låta mina fångar lösa, icke för penningar eller gåfvor, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Så säger Herren: De Egyptiers handel, och de Ethiopers förvärfning, och det stora folket i Seba, skola gifva sig under dig, och vara dine egne; de skola följa dig, uti fjettrar skola de gå, och skola nederfalla för dig, och bedja dig; ty när dig är Gud, och är eljest ingen gud mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Sannerliga äst du en fördold Gud, du Israels Gud, Frälsaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Men de afgudamakare måste allesammans med skam och hån bestå, och med hvarannan med blygd afgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Men Israel varder förlossad genom Herran evinnerliga; och skall icke till skam och spott varda någon tid i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Ty så säger Herren, som himmelen skapat hafver, Gud, som jordena beredt hafver, och hafver gjort henne och tillredt, och icke så gjort henne, att hon skulle tom vara; utan hafver tillredt henne, att man skall bo deruppå. Jag är Herren, och ingen mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Jag hafver icke hemliga talat uti något mörkt rum på jordene; jag hafver icke fåfängt sagt till Jacobs säd: Söker mig; ty jag är Herren, som om rättfärdighet talar, och förkunnar det rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Låt församla sig och tillhopa framkomma Hedningarnas hjeltar, de der intet veta, och bära deras afgudars stockar, och bedja den gud, som dem intet hjelpa kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Förkunner och kommer hit, rådslår tillsamman. Ho hafver detta låtit säga af ålder, och på den tiden förkunnat det? Hafver icke jag Herren gjort det? Och är eljest ingen Gud utan jag; en rätt Gud och Frälsare, och ingen är utan jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Vänder eder till mig, så varden I salige, alle verldenes ändar; ty jag är Gud, och ingen mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Jag svär vid mig sjelf, och ett rättfärdighets ord går utaf min mun, der skall det blifva vid; nämliga, mig skola, all knä böjas, och alla tungor svärja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, '(Och säga:) Uti Herranom hafver jag rättfärdighet och starkhet. Desse skola ock komma till honom; men alle de, som honom emotstå, måste till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Ty uti Herranom varder all Israels säd rättfärdigad, och skall berömma sig af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel lutar fast, Nebo är fallen, deras afgudar äro vordne djurom och ökom till tunga, att de skola bära sig trötta af edra bördo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Ja, de falla, och luta allesamman, och kunna icke bortbära bördona; utan deras själ måste gå i fängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Hörer mig, I af Jacobs hus, och alle återlefde af Israels hus; I som i lifve bärens, och i qvede liggen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Ja, jag skall bära eder intill åldren, och intilldess I grå varden; jag skall görat; jag skall upplyfta, och bära, och hjelpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Vid hvem viljen I likna mig, och vid hvem mäten I mig, den jag lik skulle vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'De slå guld utu säcken, och väga ut silfver med vigt, och leja guldsmeden, att han gör der en gud af, för hvilkom de knäfalla och tillbedja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'De taga honom uppå axlarna, och bära honom, och sätta honom på sitt rum; der står han, och kommer intet utaf sitt rum; ropar någor till honom, då svarar han intet, och hjelper honom intet af hans nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'På sådant tänker dock, och varer faste; I öfverträdare, går till edart hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Tänker uppå det i förtiden af ålder varit hafver; ty jag är Gud, och ingen mer, i en Gud hvilkens like ingenstäds är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Jag, som förkunnar tillförene, hvad härefter komma skall, och tillförene förrän det sker, och säger: Mitt råd blifver ståndandes, och jag gör allt det mig täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Jag kallar en fogel östanefter, och en man som min anslag fullkomnar af fjerran land. Hvad jag säger, det låter jag ske; hvad jag tänker, det gör jag ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Hörer mig, I stolthjertade, I som långt ären ifrå rättfärdighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Jag hafver låtit mina rättfärdighet när komma; hon är icke långt borto, och min salighet dröjer icke; ty jag vill gifva salighet I Zion, och mina härlighet i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Stig neder, jungfru, du dotter Babel; sätt dig i stoftet, sätt dig uppå jordena; ty de Chaldeers dotter hafver ingen stol mer; man skall icke mer kalla dig den sköna och lustiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Tag qvarnena, och mal mjöl; lös upp dina lockar, drag af skorna, blotta benen, vad öfver flodena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Att din skam skall upptäckt, och din blygd sedd varda. Jag skall hämnas, och ingen menniska skall bedja mig det af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, '(Detta gör) vår förlossare, den der heter Herren Zebaoth, den Helige i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Sätt dig uti det stilla; gack in uti mörkret, du Chaldeers dotter; ty du skall icke mer heta fru öfver Konungarike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Ty då jag på mitt folk vred var, och ohelgade min arfvedel, öfvergaf jag dem uti dina hand; men du beviste dem ingen barmhertighet, och öfver de gamla, gjorde du oket alltför svårt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Och tänkte: Jag är en Drottning evinnerliga; du hafver härtilldags ännu icke fattat det i hjertat, eller tänkt deruppå, huru det skulle gå med dem i framtiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Så hör nu detta, du som i vällust lefver, och så säker sitter, och säger i ditt hjerta: Jag äret, och ingen mer; jag blifver icke enka, eller ofruktsam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Båda, dessa stycken skola dig hasteliga öfvergå på en dag, att du en barnlös och enka blifva skall; ja, fullkommeliga skola de öfver dig komma, för dina många trollkarlars skull, och för dina besvärjares skull, af hvilkom en stor hop när dig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Ty du hafver förlåtit dig uppå dins ondsko, då du tänkte: Man ser mig intet. Din vishet och konst hafver förstört dig, att du säger i ditt hjerta: Jag äret, och ingen mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Derföre skall en olycka komma öfver dig, så att du icke skall veta, när hon kommer; och ett ofall skall falla uppå dig, det du icke skall försona kunna; ty med hast skall ett skörl komma öfver dig, det du icke förser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Så gack nu fram med dina besvärjare, och med dina många trollkarlar, ibland hvilka du dig ifrå din ungdom bemödt hafver; om du kunde behjelpa dig, om du kunde stärka dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Ty du äst trött för dina många anslags skull; gånge fram och hjelpe dig de mästare i himmelens lopp, och de stjernokikare, som efter månader räkna, hvad öfver dig komma skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Si, de äro såsom strå, hvilket elden uppbränner; de kunna icke fria deras lif för låganom; ty ingen glöd skall blifva, der man må värma sig vid, eller eld, der man vid sitta kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Alltså äro de, under hvilka du dig bemödt hafver, dine köpmän af din ungdom; hvar och en varder gångandes sin gång hit och dit, och du hafver ingen hjelpare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Hörer detta, I af Jacobs hus, I som nämnens af Israel! namn, och af Juda vatten flutne ären; som svärjen vid Herrans Namn, och ihågkommen Israels Gud, dock icke i sanningene eller rättfärdighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Ty de nämna sig af dem heliga stadenom, och trösta uppå Israels Gud; som kallas Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Jag hafver tillförene förkunnat detta tillkommande; utaf minom mun är det gånget, och jag hafver låtit säga det; och gör det också med hast, att det kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Ty jag vet, att du äst hård, och ditt halsband är en jernsena, och ditt änne är af koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Jag hafver förkunnat dig det tillförene, och hafver låtit säga dig det, förr än det kom; på det att du icke skulle säga: Min afgud gör det, och mitt beläte, och min afgud hafver det befallt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Allt detta hörde och såg du, och hafver dock icke förkunnat det; ty jag hafver tillförene låtit säga dig ny och fördold ting, de du icke visste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Men nu är det skapadt, och icke på den tiden, och du hafver icke hört deraf en dag tillförene; på det du icke skulle säga: Si, det visste jag väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Ty du hörde det intet, och visste det ock intet, och ditt öra var på den tiden icke öppnadt; men jag visste väl, att du skulle föraktat, och äst en öfverträdare kallad allt ifrå moderlifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Derföre är jag för mitt Namns skull långmodig, och för min pris skull vill jag, dig till nytto, hålla tillbaka, att du icke skall utrotad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Si, jag vill bepröfva dig, men icke såsom silfver; utan jag vill göra dig utkoradan uti bedröfvelsens ugn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'För mina skull, ja, för mina skull vill jag görat; på det jag icke skall försmädad varda; ty jag vill icke gifva mina äro enom androm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Hör mig, Jacob, och du Israel, min kallade: Jag äret; jag är den förste, jag är den siste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Min hand hafver grundat jordena, och min högra hand hafver omspannat himmelen; hvad jag kallar, det står straxt redo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Församler eder alle, och hörer: Hvilken är ibland dessa, som detta förkunna kan? Herren älskar honom; derföre skall han bevisa sin vilja på Babel, och sin arm på de Chaldeer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Tag, ja, Jag hafver sagt det, jag hafver kallat honom; jag vill ock låta honom komma, och hans väg skall honom lyckas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Går hit till mig, och hörer detta: Jag hafver tillförene icke hemliga talat; ifrå den tiden, då det taladt vardt, är jag der. Och nu sänder mig Herren Herren, och hans Ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Så säger Herren, din förlossare, den Helige i Israel: Jag är Herren din Gud, den dig lärer hvad nyttigt är, och leder dig på den vägen, som du går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'O! att du ville akta uppå, min bud; så skulle din frid vara såsom en vattuström, och din rättfärdighet såsom hafsens våg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Och din säd skulle varda såsom sand, och dins lifs frukt såsom hans små stenar; hvilkens namn icke skulle utrotadt varda, eller utstruket för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Går ut af Babel, flyr ifrå de Chaldeer med glada röst; förkunner, och låter det höra, förer det ut allt intill verldenes ända; säger: Herren hafver förlossat sin tjenare Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'De hade ingen törst, då han ledde dem i öknene; han lät dem flyta vatten ut af bergklippone, han klöf bergklippona, och der rann ut vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Men de ogudaktige, säger Herren, hafva ingen frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Hörer mig, I öar, och I folk, som fjerran ären, gifver akt häruppå: Herren hafver kallat mig af moderlifvet; han hafver tänkt uppå mitt namn, medan jag ännu i moderlifvet var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Och hafver gjort min mun såsom ett skarpt svärd; han hafver öfverskylt mig med sine hands skugga; han hafver gjort mig till en blankan pil, och stungit mig uti sitt koger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Och säger till mig: Du äst min tjenare, Israel, genom hvilken jag vill prisad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Men jag tänkte: Jag arbetade fåfängt, jag hafver fåfängt och onytteliga förtärt mina kraft häruppå; ändock min sak är Herrans, och mitt ämbete hörer minom Gud till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Och nu, säger Herren, som mig af moderlifvet till sin tjenare beredt hafver, af jag skulle omvända Jacob till honom, på det Israel icke skulle blifva borto; derföre är jag härlig för Herranom, och min Gud är min starkhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Och säger: Det är en ringa ting, att du äst min tjenare, till att upprätta Jacobs slägter, och igenföra det förskingrada i Israel; utan jag hafver ock gjort dig till Hedningarnas ljus, att du skall vara min salighet intill verldenes ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Så säger Herren Israels förlossare, hans Helige, till de föraktada själar, till det folk der man styggelse vid hafver, till den tjenaren som under tyranner är: Konungar skola se och uppstå, och Förstar skola tillbedja för Herrans skull, som trofast är; för den Heligas skull i Israel, den dig utkorat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Detta säger Herren: Jag hafver bönhört dig i behagelig tid, och hafver hulpit dig på salighetenes dag, och hafver bevarat dig, och satt dig till ett förbund i folkena, att du skall upprätta landet, och intaga de förderfvada arf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Till att säga till de fångar: Går ut; och till dem i mörkret: Kommer fram; att de skola föda sig på vägarna, och hafva deras födo på alla högar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'De skola hvarken hungra eller törsta; dem skall ingen hette eller solen stinga; ty deras förbarmare skall föra dem, och leda dem till vattukällor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Jag skall göra all mina berg till vägar, och mine stigar skola trampade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Si, desse skola komma fjerranefter, och si, de andre ifrån nordan, och desse ifrån hafvet, och de andre ifrån Sinims land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Fröjder eder, I himlar, gläd dig, du jord, lofsäger, I berg, med fröjd; ty Herren hafver hugsvalat sitt folk, och förbarmat sig öfver sina elända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Men Zion säger: Herren hafver öfvergifvit mig, Herren hafver förgätit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Månn ock en qvinna kunna förgäta sitt barn, så att hon icke förbarmar sig öfver sins lifs son? Och om hon än förgäten, så vill jag dock icke förgäta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Si, uppå händerna hafver jag upptecknat dig. Dina murar äro alltid för mig,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Dine uppbyggare skola skynda sig; men dine nederbrytare och förstörare skola draga sig derifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Lyft din ögon upp allt omkring och se: Alle desse komma församlade till dig; så sant som jag lefver, säger Herren, du skall med allo desso, såsom med en skrud, utiklädd varda, och skall dermed omsvepa dig som en brud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Ty ditt förödda, förstörda och förderfvade land skall då varda dig allt för trångt till att bo uti, när dine förderfvare långt ifrå dig komma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Så att dins ofruktsamhets barn skola ännu säga för din öron: Rummet är mig för trångt; sitt åt dig, att jag må bo när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Men du skall säga i ditt hjerta: Ho hafver mig dessa födt? Jag är ofruktsam, ensam, fördrifven och utskjuten; ho hafver mig dessa uppfödt? Si, jag var ensam öfvergifven; hvar voro då desse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Så säger Herren Herren: Si, jag vill upplyfta min hand till Hedningarna, och uppresa mitt baner till folken, så skola de bära dina söner fram på armarna, och draga dina döttrar på axlarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Och Konungar skola vara dine skaffare, och deras Förstinnor dina ammor. De skola för dig nederfalla till jordena på ansigtet, och sleka dina fötters stoft. Då skall du förnimma, att jag är Herren, på hvilkom ingen till skam varder, som hoppas uppå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Kan man ock taga enom kämpa hans rof bort, eller kan man lösgöra ens rättfärdigs fångar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Ty så säger Herren: Nu skola de fångar kämpanom borttagne varda, och dess starkas rof löst varda, och jag skall träta med dina trätare, och hjelpa dina barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Och jag skall spisa dina plågare med deras eget kött, och de skola druckne varda af sitt eget blod, såsom af sött vin; och allt kött skall förnimma, att jag är Herren din Frälsare, och din förlossare, den mägtige i Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Så säger Herren: Hvar är edors moders skiljobref, med hvilko jag eder öfvergifvit hafver? Eller ho är min ockrare, dem jag eder sålt hafver? Si, I ären för edra synders skull sålde, och edor moder är, för edor öfverträdelses skull, öfvergifven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Hvi kom jag, och der var ingen? Jag ropade, och ingen svarade. Är min hand nu så kort vorden, att hon intet förlossa kan, eller är med mig ingen kraft till att frälsa? Si, med mitt straff gör jag hafvet torrt, och gör vattuströmmarna såsom en öken, så att deras fiskar illa lukta för vattunöds skull, och blifva döde af törst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Jag kläder himmelen med mörker, och gör hans öfvertäckelse såsom en säck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Herren Herren hafver gifvit mig en lärd tungo, att jag vet tala med dem trötta i rättom tid; han väcker mig hvar morgon; han väcker mig örat, att jag hörer såsom en lärjunge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Herren Herren hafver öppnat mig örat, och jag är icke ohörsam, och går icke tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Jag höll min rygg till dem som mig slogo, och min kindben dem som mig ryckte; mitt ansigte vände jag icke bort för försmädelse och spott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Ty Herren Herren hjelper mig, derföre kommer jag icke på skam; derföre hafver jag hållit mitt ansigte fram såsom en flintosten; ty jag vet, att jag icke på skam kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Den är när, som mig rättfärdigar. Ho vill träta med mig? Låt oss tillhopa gå; ho är den som rätt hafver emot mig? Han komme hit till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Si, Herren Herren hjelper mig. Ho är den mig fördöma vill? Si, de skola allesammans föråldras, såsom ett kläde; mal skall uppäta dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Ho är den ibland eder, som fruktar Herran, den hans tjenares röst lyder? Den i mörkret vandrar, och honom skin intet; han hoppes uppå Herrans Namn, och förlåte sig uppå sin Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Si, I alle, som upptänden en eld, väpnade med låga, vandrer uti edars elds ljus, och i låganom, som I upptändt hafven; detta vederfars eder af mine hand; uti värk skolen I ligga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Hörer mig, I som efter rättfärdighet faren, I som Herran söken; ser uppå klippona, dädan I afhuggne ären, och uppå brunnsgropena, dädan I utgrafne ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Ser uppå Abraham, edar fader, och Sara, den eder födt hafver; ty jag kallade honom, då han ännu ensam var, och välsignade honom, och förmerade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Ty Herren hugsvalar Zion, han tröster all dess öde, och gör dess öde såsom lustgårdar, och dess hedmark såsom en Herrans örtegård; glädje och fröjd skall man finna derinne, tack och lofsång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Gifver akt uppå mig, mitt folk, och hörer mig, min allmoge; ty af mig skall utgå en lag, och min rätt vill jag sätta folkom till ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Ty min rättfärdighet är när; min salighet drager ut, och mina armar skola döma folken; öarna förbida mig, och vakta uppå min arm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Lyfter edor ögon upp till himmelen, och skåder neder uppå jordena; ty himmelen skall förgås såsom en rök, och jorden föråldras såsom ett kläde, och de som bo deruppå skola dö bort, såsom detta; men min salighet blifver evinnerliga, och min rättfärdighet skall icke återvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Hörer mig, I som kännen rättfärdighetena, du folk i hvilkets hjerta min lag är; frukter eder intet, när menniskorna försmäda eder, och gifver eder icke, när de förhäda eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Ty mal skall uppäta dem såsom ett kläde, och matkar skola äta dem såsom ull; men min rättfärdighet blifver evinnerliga, och min salighet förutan ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Upp, upp, kläd dig i starkhet, du Herrans arm; upp, såsom i förtiden af ålder. Äst icke du den som de högmodiga slagit, och drakan sargat hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Äst icke du den som uttorkade hafvet, det djupa vattnet; den som gjorde hafsbottnen till en väg, så att de förlossade gingo derigenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Alltså; skola Herrans förlossade vända om, och komma till Zion med fröjd, och evig glädje skall vara på deras hufvud; glädje och fröjd skall fatta dem, sorg och suckan skall ifrå dem fly.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Jag, Jag är edar tröstare. Ho äst du då, att du fruktar dig för menniskor, de dock dö, och för menniskobarn, hvilke såsom hö förtärde varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Och förgäter Herran, den dig gjort hafver, den der himmelen utsträcker, och jordena grundar? Men du fruktar dig alltid hela dagen för plågarens grymhet, då han tager till att förderfva. Hvar blef plågarens grymhet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Då han måste hasta sig och löpa omkring, att han skulle lös gifva, och de icke döde blefvo i förderfvelsen, ej heller någon brist på bröd hade?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Ty jag är Herren din Gud, den der hafvet rörer, så att dess böljor fräsa. Hans Namn heter Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Jag sätter min ord uti din mun, och öfvertäcker dig under mina händers skugga, på det jag skall plantera himmelen och grunda jordena, och säga till Zion: Du äst mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Vaka upp, vaka, upp, statt upp, Jerusalem, du som af Herrans hand hans grymhets kalk druckit hafver; dräggen af dvalakalken hafver du utdruckit, och uppslekt dropparna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Det var ingen af all de barn, som hon födt hade, som henne ledde; ingen af all de barn, de hon uppfödt hade, som henne vid handena tog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Desse tu stycke äro dig påkomne; ho ömkade sig öfver dig? Förstöring, skade, hunger och svärd var der; ho skulle hugsvala dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Din barn voro försmäktade, de lågo på alla gator, såsom en besnärd skogsoxe; fulle med vrede af Herranom, och med straff af dinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Derföre hör detta, du elända, och druckna utan vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Så säger den som råder öfver dig, Herren, och din Gud, den sitt folk hämnas: Si, jag tager den dvalakalken utu dine hand, samt med dräggene af mine vredes kalk, du skall icke mer dricka honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Utan jag skall få honom dina plågare i handena, de som till dina själ sade: Bocka dig, att vi måge gå öfver dig, och lägg din rygg på jordena, och som ena gato, att man må löpa deröfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Statt upp, statt upp, Zion, ikläd dig dina starkhet; pryd dig härliga, du helige stad Jerusalem; ty härefter skall ingen oomskoren eller oren regera i dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Statt upp utu stoftet, statt upp, du fångna Jerusalem; gör dig lös af din halsband, du fångna dotter Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Ty alltså säger Herren: I ären sålde för intet; I skolen ock utan penningar löste varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Ty så säger Herren Herren: Mitt folk drog i förstone neder uti Egypten, på det de skulle vara der gäster; och Assur hafver gjort dem öfvervåld utan sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Men huru skall man här bära sig åt med? säger Herren. Mitt folk varder förgäfves förfördt. De som råda öfver dem, komma dem till att gråta, säger Herren; och mitt Namn varder alltid dag ifrån dag försmädadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Derföre skall mitt folk känna mitt Namn på den tiden; ty si, jag vill sjelf tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'O! huru ljuflige äro på bergomen bådbärarenas fötter, de som frid förkunna; predika godt, förkunna salighetena; de som säga till Zion: Din Gud är Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Dine vaktare ropa högt med deras röst, och fröjdas tillhopa; ty man skall se med ögonen, när Herren omvänder Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Fröjde och glädje sig tillsammans Jerusalems öde; ty Herren hafver tröstat sitt folk, och förlossat Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Herren hafver uppenbarat sin helga arm för alla Hedningars ögon, så att alle verldenes ändar skola se vår Guds salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Viker, viker, drager ut dädan, och kommer vid intet orent; går ut ifrå dem, rener eder, I som Herrans tyg bären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Ty I skolen icke draga ut med hast, eller vandra med flykt; ty Herren skall draga för eder, och Israels Gud skall församla eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Si, min tjenare skall visliga regera, och skall upphöjd och ganska högt uppsatt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Så att månge skola förarga sig öfver dig, efter hans skapnad är ledare än andra menniskors, och hans anseende än menniskors barnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Men alltså skall han bestänka många Hedningar, att ock Konungar skola hålla sin mun för honom; ty dem som intet deraf förkunnadt är, de skola se det med lust, och de som intet deraf hört hafva, de skola besinnat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Men ho tror vår predikan, och hvem varder Herrans arm uppenbarad?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Ty han rinner upp för honom såsom en vidja, och såsom en rot utu torro jord; han hafver ingen skapnad eller dägelighet. Vi såge honom; men der var ingen den skapnad, som oss kunde behaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Han var den aldraföraktadaste och vanvördaste, full med värk och krankhet; han var så föraktad, att man gömde bort ansigtet för honom; derföre aktade vi honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Sannerliga han bar våra krankhet, och lade uppå sig vår sveda; men vi hölle honom för den som plågad och af Gudi slagen och pinter var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Men han är sargad för våra missgerningars skull, och slagen för våra synders skull; näpsten ligger uppå honom, på det att vi skulle frid hafva, och genom hans sår äre vi helade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Vi ginge alle uti villfarelse, såsom får; hvar och en såg uppå sin väg; men Herren kastade allas våra synder uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Då han näpst och plågad vardt, lät han icke upp sin mun; såsom ett lamb, det till slagtning ledes, och såsom ett får, det stilla tiger för sinom klippare, och låter icke upp sin mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Men han är tagen utur ångest och dom. Ho kan uttala hans lifslängd? Ty han är bortryckt utaf de lefvandes land, då han för mins folks missgerningar plågad var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Och han är begrafven såsom de ogudaktige, och döder såsom en rik; ändock han ingom orätt gjort hade, ej heller något svek uti hans mun var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Men Herren ville alltså slå honom med krankhet. När han sitt lif till skuldoffer gifvit hafver, så skall han få säd, och länge lefva, och Herrans uppsåt skall uti hans hand framgång hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Derföre, att hans själ arbetat hafver, skall han få se sina lust, och nog hafva, och genom sin kunskap skall han, min tjenare, den rättfärdige, många rättfärdiga göra; ty han bär deras synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Derföre vill jag gifva honom ganska mycket till byte, och han skall hafva de starka till rof; derföre att han gifvit sitt lif i döden, och vardt ogerningsmannom lik räknad, och mångas synder bar, och bad för öfverträdarena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Fröjda dig, du ofruktsamma, du som intet föder; gläd dig med fröjd och berömmelse, du som intet hafvandes är; ty den ensamma hafver flera barn än den som man hafver, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Förvidga din pauluns rum, och utsträck tapeten åt din tjäll; spar icke, förläng din tåg, och befäst dina pålar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Ty du skall brista ut på högra sidon och den venstra, och din säd skall ärfa Hedningarna, och bo uti de förödda städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Frukta dig intet; ty du skall icke till skam varda. Var icke blödig; ty du skall icke varda till blygd, utan du skall förgäta dins jungfrudoms blygd, och din enkodoms neso icke mer ihågkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Ty den dig gjort hafver, han är din man; Herren Zebaoth är hans Namn; och din förlossare, den Helige i Israel, den alla verldenes Gud kallad varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Ty Herren hafver låtit dig vara uti det ryktet, att du äst såsom en öfvergifven och af hjertat bedröfvad qvinna, och såsom en ung hustru, den bortdrifven är, säger din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Jag hafver uti ett litet ögnablick öfvergifvit dig; men med stor barmhertighet vill jag församla dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Jag hafver, uti vredenes ögnablick, som snarast gömt bort mitt ansigte för dig; men med eviga nåd vill jag förbarma mig öfver dig, säger Herren, din förlossare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Ty detta skall vara mig såsom Noahs flod; då jag svor, att Noahs flod icke mer skulle gå öfver jordena; alltså hafver jag svorit, att jag icke skall vredgas öfver dig, eller näpsa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Ty bergen skola väl vika, och högarna falla; men min nåd skall icke vika ifrå dig, och mins frids förbund skall icke förfalla, säger Herren, din förbarmare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Du elända, öfver hvilka alle väder gå, och du tröstlösa, si, jag vill lägga dina stenar såsom en prydning, och lägga din grundval med saphirer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Och din fenster göra af christall, och dina portar af rubiner, och alla dina gränsor af utkorada stenar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Och all din barn lärd af Herranom, och stor frid dinom barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Du skall genom rättfärdighet beredd varda; du skall vara långt ifrån öfvervåld och orätt, så att du icke skall torfva frukta dig derföre; och ifrå förskräckelse, ty det skall icke nalkas dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Si, ho vill församla sig emot dig, och öfverfalla dig, då de församla sig utan mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Si, jag gör det, att smeden, som uppblås kolen i elden, han gör der ett tyg af, till sitt verk; ty jag gör ock, att förderfvaren förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Ty hvart och ett tyg, som emot dig tillredt varder, thy skall icke väl gå; och hvar och en tunga, som sig uppsätter emot dig, den skall du fördöma i dome. Detta är Herrans tjenares arf, och deras rättfärdighet af mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Nu väl, alle I, som törstige ären, kommer hit till vatten; och I som icke penningar hafven, kommer hit, köper och äter; kommer hit, och köper utan penningar och för intet, både vin och mjölk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Hvi läggen I ut penningar, der intet bröd är; och edart arbete, deraf I intet mätte varden? Hörer mig, och äter det godt är, så skall edor själ fet varda, i vällust.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Böjer edor öron hit, och kommer till mig; hörer, så får edor själ lefva; ty jag vill göra med eder ett evigt förbund, nämliga Davids vissa nåder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Si, jag hafver satt honom till ett vittne i folkena, till en Första och lärare för folken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Si, du skall kalla Hedningar, de du intet känner; och Hedningar, som intet känna dig, skola löpa till dig, för Herrans dins Guds skull, dens Heligas i Israel, den dig prisar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Söker Herran, medan man kan finna honom; åkaller honom, medan han när är,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Den ogudaktige öfvergifve sin väg, och syndaren sina tankar; och omvände sig till Herran, så förbarmar han sig öfver honom; och till vår Gud, ty när honom är mycken förlåtelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Ty mine tankar äro icke edre tankar, och edre vägar äro icke mine vägar, säger Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Utan så mycket himmelen är högre än jorden, så äro ock mine vägar högre än edre vägar, och mine tankar är edre tankar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Ty lika som regnet och snön faller af himmelen, och kommer icke åter dit igen, utan fuktar jordena, och gör henne fruktsamma och bärande, så att hon gifver säd till att så, och bröd till att äta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Alltså skall ock ordet vara, som utaf minom mun går. Det skall icke återkomma till mig fåfängt; utan göra det mig täckes, och det skall framgång hafva uti thy jag utsänder det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Ty I skolen utgå i glädje, och i frid ledsagade varda; berg och högar skola fröjdas för eder med glädje, och all trä på markene klappa med händerna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Furu skall uppväxa för törne, och myrten för törnebuskar; och Herranom skall vara ett Namn och ett evigt tecken, det icke skall utrotadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Så säger Herren: Håller rätt, och görer rättfärdighet; ty min salighet är när, att hon kommer, och min rättfärdighet, att hon uppenbar varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Väl är de mennisko, som detta gör, och menniskos barne, som det fast håller; så att hon håller Sabbathen, och icke ohelgar honom, och håller sina hand, att hon intet argt gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Och den främmande, som sig till Herran gifvit hafver, skall icke säga: Herren varder mig afskiljandes ifrå sitt folk; och den snöpte skall icke säga: Si jag är ett torrt trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Ty så säger Herren till de snöpta, som hålla mina Sabbather, och utvälja det mig behagar, och fatta mitt förbund fast:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Dem skall jag gifva ett rum i mitt hus, och i mina murar, och ett bättre namn än sönom och döttrom; ett evigt namn skall jag gifva dem, det icke förgås skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Och de främmandes barn, som sig till Herran gifvit hafva, att de skola honom tjena och älska Herrans Namn, på det de skola vara hans tjenare, hvar och en som Sabbathen håller, så att han icke ohelgar honom, och håller mitt förbund fast;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'De samma skall jag hafva till mitt helga berg, och skall glädja dem uti mitt bönehus; och deras offer och bränneoffer skola vara mig tacknämliga på mitt altare; ty mitt hus kallas ett bönehus allom folkom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Herren Herren, som de fördrefna af Israel församlar, säger: Jag vill ännu mer församla till den hopen, som församlad är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'All djur på markene kommer och äter; ja, all djur i skogenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Alle deras vaktare äro blinde, de veta allesamman intet; tyste hundar äro de, och kunna intet straffa; äro late, ligga och sofva gerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Men de äro starke hundar till kroppen, så att de aldrig kunna mätte varda. Si, herdarna veta intet förstånd; hvar och en ser uppå sin väg; hvar och en girigas för sig i sitt stånd:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Kommer, låter oss hemta vin, och dricka oss druckna, och vara så i morgon som i dag, och ändå mycket mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Men den rättfärdige förgås, och ingen är som lägger det uppå hjertat, och helgo män varda bortryckte, och ingen aktar deruppå; ty de rättfärdige varda borttagne för olyckone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Och de som redeliga för sig vandrat hafva, komma till frid, och hvilas uti deras kamrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Kommer härfram, I trollkonobarn, I horkarlars och horors säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Med hvem viljen I nu hafva edra lust? Öfver hvem viljen I nu gapa med munnenom, och räcka ut tungona? Ären I icke öfverträdelsens barn och en falsk säd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'I som så hete ären till afgudar under all grön trä, och slagten barn vid bäckerna under bergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Ditt väsende är med de släta stenar i bäckenom; de äro din del, dem utgjuter du ditt dryckoffer, då du spisoffer offrar. Skulle jag dertill lust hafva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Du gör dina säng på ett högt resigt berg, och går desslikes sjelf ditupp till att offra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Och bak dörrena och dörrträn sätter du din åminnelse; ty du välter dig ifrå mig, och går upp, och utvidgar dina säng, och förbinder dig med dem; du älskar deras säng, ehvar du ser dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Du far till Konungen med oljo, och hafver mångahanda krydder, och sänder din bådskap långväga, och äst förnedrad allt intill helvetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Du mödde dig uti dina många vägar, och sade icke: Hvila dig något litet; utan efter du finner dine hands lefverne, varder du intet trött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'För hvem äst du så bekymrad och fruktar dig? Efter du dock far med lögn, och kommer intet mig ihåg, och lägger det intet på hjertat; menar du, att jag skall allstädes tiga, att du så platt intet fruktar mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Men jag skall uppenbara dina rättfärdighet och din verk, att de dig intet nyttig vara skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Då du ropandes varder, så låt ditt sällskap hjelpa dig; men vädret skall alla föra dem bort, och fåfängelighet skall taga dem bort. Men den som tröster uppå mig, han skall ärfva landet, och besitta mitt helga berg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Och skall säga: Görer väg, görer väg, rödjer vägen; hafver bort det som hindrar af mins folks väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Ty alltså säger den Höge och högt besittne, den evinnerliga bor, hvilkens Namn är heligt: Jag, som bor i höjdene, och i helgedomenom, och när dem som en förkrossad och ödmjuk anda hafva, på det jag skall vederqvicka de ödmjukades anda, och hela de förkrossades hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Jag vill icke träta evinnerliga, och icke vred vara i evig tid; utan en Ande skall blåsa ifrå mitt ansigte, och jag skall göra lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Jag var vred uppå deras girighets odygd, och slog dem; fördöljde mig, och var vred. Då gingo de hit och dit uti deras hjertas väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Men då jag såg uppå deras väg, helade jag dem, och ledde dem, och gaf dem åter tröst, och dem som sörjde öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Jag skall skapa utvidgada läppar, de som predika skola: Frid, frid, både dem som fjerran, och dem som vid handen äro, säger Herren; och vill hela dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Men de ogudaktige äro såsom ett stormande haf, det icke stilla vara kan, och dess vågar häfva upp träck och orenlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'De ogudaktige hafva icke frid, säger min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Ropa trösteliga, spar icke; upphäf dina röst såsom en basun, och förkunna mino folke deras öfverträdelse, och Jacobs hus deras synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'De söka mig dagliga, och vilja veta mine vägar, såsom ett folk det allaredo rättfärdighet gjort hade, och sins Guds rätt icke öfvergifvit hade; de äska mig i rätten, och vilja med sinom Gud till rätta gå:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Hvarföre faste vi, och du ser der intet uppå? Hvi tvinge vi vår kropp, och du vill intet veta deraf? Si, när I fasten, så bruken I edar vilja, och trugen alla edra gäldenärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Si, I fasten till att träta och kifva, och slån med näfvanom oskäliga. Faster icke såsom I nu gören, att ett rop skall af eder i höjdene hördt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Skulle det vara en fasta, den jag utvälja skulle, att en menniska tvingar om dagen sin kropp, eller hänger sitt hufvud såsom ett säf, eller ligger i säck och asko? Viljen I det kalla fasto, och den dag, som Herranom tacknämlig är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Men detta är den fasta, som jag utväljer: Gif lösa dem som du med orätt bundit hafver, släpp dem som du betungar, gif dem fri som du tvingar, haf bort allahanda tunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Bryt dem hungroga ditt bröd, och de som elände äro haf uti hus; om du ser en nakot, så kläd honom, och drag dig icke undan för ditt kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Allt då skall ditt ljus utbrista såsom en morgonrodne, och din förbättring skall snarliga växa till, och din rättfärdighet varder för dig gångandes, och Herrans härlighet skall taga dig till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Då skall du åkalla, och Herren skall svara dig, och du skall ropa, och han skall säga: Si, här är jag. Om du ingen besvärar när dig, eller finger räcker, eller illa talar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Och utskuddar dina själ dem hungroga, och mättar de elända själar; så skall ditt ljus uppgå uti mörkret, och din skymning skall vara såsom middagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Och Herren skall föra dig alltid, och mätta dina själ uti torkone, och styrka din ben; och du skall vara såsom en vattnad örtegård, och såsom en vattukälla, hvilko aldrig vatten fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Och genom dig skall uppbygdt varda det länge öde legat hafver, och du skall lägga en grund, den i evig tid blifva skall; och skall kallas den der refna gårdar bygger, och vägar bättrar, att man der bo kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Om du vänder din fot ifrå Sabbathen, så att du icke gör, på minom helgedag, hvad som dig tyckes, så skall det kallas en lustig Sabbath, till att helga och prisa Herran; ty så varder du honom prisandes, när du icke gör dina vägar, eller varder funnen uti det som dig täckes, eller hvad du talar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Allt då skall du hafva lust i Herranom, och jag skall föra dig öfver höjderna på jordene, och skall spisa dig med dins faders Jacobs arf; ty Herrans mun säger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Si, Herrans hand är icke för kort, så att han icke hjelpa, kan; och hans öron äro icke lomhörd vorden, att han intet hörer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Utan edor ondska åtskiljer eder och edar Gud ifrå hvarannan; och edra synder gömma bort hans ansigte ifrån eder, att I icke hörde varden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Ty edra händer äro med blod besmittade, och edor finger med odygd; edra läppar tala lögn; edor tunga diktar orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Det är ingen, som om rättfärdighet predikar, eller troliga dömer; man tröster uppå fåfängelighet, och talar intet det något doger; med olycko äro de hafvande, och föda vedermödo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'De ligga på basiliskes äggom, och väfva dvergsnät. Äter man af deras ägg, så måste man dö; trådar man ock deruppå, så får man en huggorm derut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Deras dvergsnät doga intet till kläder, och deras verk doger intet till öfvertäckelse; ty deras verk är möda, och uti deras händer är orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Deras fötter löpa till ondt, och äro snare till att utgjuta oskyldigt blod; deras tankar äro vedermöda; deras väg är skade och förderf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'De känna icke fridsens väg, och ingen rätt är uti deras gånger. De äro vrånge på deras vägom; den som der går uppå, han hafver aldrig frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Derföre är rätten långt ifrån oss, och vi få icke rättvisona; vi bide efter ljus, si, så varder det mörker; efter sken, och si, vi vandre i töckno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Vi famle efter väggene såsom de blinde, och trefve såsom de der inga ögon hafva; vi stöte oss om middagen såsom i skymningene; vi äre i mörkret såsom de döde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Vi vråle alle såsom björnar, och knurle såsom dufvor; ty vi bide efter rätten, och si, der är ingen; efter salighet, och si, hon är fjerran ibland oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Ty vår öfverträdelse för dig är alltför mycken, och våra synder svara emot oss; ty vår öfverträdelse är när oss, och vi synde vetande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Med öfverträdelse och lögn emot Herran; med fråvändning ifrå vår Gud, till att tala orätt och olydighet, tänka och dikta falsk ord utu hjertana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Derföre är ock rätten tillbakaviken, och rättvisan fjerran gången; ty sanningen faller uppå gatone, och: redelighet kan icke komma fram;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Sanningen är borto, och den som viker ifrå det onda, han måste hvars mans rof vara. Sådant ser Herren, och det behagar honom illa, att ingen rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Och han ser, att der är ingen, och förundrar sig, att ingen lägger sig der ut före; derföre hjelper han honom sjelf med sinom arm, och hans rättfärdighet uppehåller honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Ty han drager rättfärdighet uppå såsom ett pansar, och sätter salighetenes hjelm uppå sitt hufvud; och ikläder sig till att hämnas, och drager uppå sig nit såsom en kjortel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Såsom den der sinom motståndarom vedergälla, och sina fiendar med grymhet betala vill; ja, öomen vill han betala;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Att Herrans Namn må fruktadt varda ifrån vestan, och hans härlighet ifrån östan, när han kommandes varder såsom en förhållen ström, den Herrans väder åstad drifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Ty dem i Zion skall komma en förlossare, och dem som sig omvända ifrå synderna i Jacob, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Och jag gör detta förbund med dem, säger Herren: Min ande, som när dig är, och min ord, de jag uti din mun satt hafver, skola icke vika ifrå dinom mun, ej heller ifrå dine säds och barnabarns mun, säger Herren, ifrå nu och i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Statt upp, var ljus; ty ditt ljus kommer, och Herrans härlighet går upp öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Ty si, mörker öfvertäcker jordena, och mörkhet folken; men öfver dig uppgår Herren, och hans härlighet skall synas öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Och Hedningarna skola vandra i dino ljuse, och Konungar uti skenet, som uppgår öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Lyft upp din ögon, och se omkring dig; desse alle församlade komma till dig; dine söner skola komma fjerranefter, och dina döttrar vid sidona uppfödda varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Då skall du se dina lust, och utbrista, och ditt hjerta skall förundra och utvidga sig, när den stora hopen vid hafvet vänder sig till dig, och Hedningarnas magt kommer till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Ty de månge cameler skola öfvertäcka dig, de löpare af Midian och Epha. Af Saba skola de alle komma, guld och rökelse föra, och Herrans lof förkunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Alle hjordar i Kedar skola till dig församlade varda, och Nebajoths bockar skola tjena dig; de skola uppå mitt tacknämliga altare offrade varda; ty jag vill pryda mins härlighets hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Hvilke äro de som flyga såsom skyar, och såsom dufvor till deras fenster?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Öarna förbida mig, och skeppen i hafvet för långan tid, att de skola hafva din barn fram ifrå fjerran, samt med deras silfver och guld, Herrans dins Guds Namne, och den Heliga i Israel, den dig härligan gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Främmande skola bygga dina murar, och deras Konungar skola tjena dig; ty uti mine vrede hafver jag slagit dig, och i mine nåd förbarmar jag mig öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Och dine portar skola städse öppne stå, hvarken dag eller natt tillslutne varda, att Hedningarnas magt skall till dig hafd varda, och deras Konungar tillförde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Ty hvilke Hedningar eller Konungarike icke vilja tjena dig, de skola förgås, och Hedningarna förödde blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Libanons härlighet skall till dig komma; furu, bok och buxbom tillsammans, till att bepryda mins helgedoms rum; ty jag vill mina fötters rum härligit göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Skola ock de, som dig undertryckt hafva, bugande komma till dig, och alle de, som dig försmädat hafva, skola nederfalla till dina fötter, och skola kalla, dig en Herrans stad, ett Zion dens Heligas i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Ty derföre, att du hafver varit öfvergifven och förhatad, der ingen gick, vill jag göra dig till härlighet evinnerliga, och till glädje utan ända;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Så att du skall suga mjölk af Hedningomen, och Konungabröst skola dig suga gifva; på det du skall förnimma, att jag, Herren, är din Frälsare, och jag, den mägtiga i Jacob, är din förlossare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Jag vill låta komma guld för koppar, och silfver för jern, och koppar för trä, och jern för sten; och vill så görat, att dine föreståndare skola, frid lära, och dine skaffare predika rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Man skall ingen orätt mer höra uti ditt land, ej heller skada eller förderf uti dina gränsor; utan dine murar skola heta salighet, och dine portar lof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Solen skall icke mer skina dig om dagen, och månens sken skall icke mer lysa dig; utan Herren varder ditt eviga ljus, och din Gud skall din pris vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Din sol skall icke mer nedergå, eller din måne tappa sitt sken; ty Herren skall vara ditt eviga ljus, och dine sorgedagar skola en ända hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Och ditt folk skola allesamman vara rättfärdige, och skola besitta jordena evinnerliga; såsom de der mine planterings qvist, och mina händers verk äro, till pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Utaf dem minsta skola varda tusende, och utaf dem ringesta ett mägtigt folk; Jag, Herren, vill detta i sinom tid snarliga uträtta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Herrans, Herrans Ande är med mig, derföre hafver Herren smort mig; han hafver sändt mig till att predika dem eländom, till att förbinda de förkrossada hjerta, till att predika de fångar förlossning, och dem bundnom öppning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Till att predika ett nådeligit Herrans år, och en vår Guds hämndadag, till att hugsvala alla sörjande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Till att skaffa dem sörjandom i Zion, att dem skall prydning för asko, glädjeolja för sorg, och skön kläder för en bedröfvad anda gifven varda, att de skola kallas rättfärdighetenes trä, Herrans plantering till pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'De skola uppbygga de gamla öden, och låta uppkomma det i förtiden förstördt är; de skola förnya de öde städer, som ifrå slägte till slägte hafva förstörde legat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Främmande skola stå och föda edra hjordar, och utländningar skola vara edra åkermän och vingårdsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Men I skolen heta Herrans Prester, och man skall kalla eder vår Guds tjenare; och skolen äta Hedningarnes ägodelar, och berömma eder af deras härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'För edor försmädelse skall dubbelt komma, och för skammena skola de på deras åker glade vara; ty de skola dubbelt äga i deras land; eviga glädje skola de hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Ty jag är Herren, som rätten älskar, och hatar rofs bränneoffer; och jag vill skaffa, att deras arbete icke skall förtappadt vara, och ett evigt förbund vill jag göra med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Och man skall känna deras säd ibland Hedningarna, och deras efterkommande ibland folken; så att den der ser dem, skall känna dem, att de en säd äro som välsignad är af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Jag fröjdar mig i Herranom, och min själ är glad i minom Gud; ty han hafver mig utiklädt med salighetenes kläder, och dragit uppå mig rättfärdighetenes kjortel, såsom en brudgumme i sitt prål, såsom en Prest i sin prydning, och såsom en brud hofverar uti sin skrud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Ty såsom frukten växer utu jordene, och fröet uppgår i örtagårdenom; alltså skall rättfärdighet och lof uppgå för alla Hedningar af Herranom Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'För Zions skull vill jag icke tiga, och för Jerusalems skull vill jag icke hållat inne; tilldess dess rättfärdighet uppgår såsom ett sken, och dess salighet brinner såsom ett bloss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Att Hedningarna måga se dina rättfärdighet, och alle Konungar dina härlighet, och du skall med ett nytt namn nämnd varda, hvilket Herrans mun nämna skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Och du skall vara en skön krona uti Herrans hand; och en Konungslig hatt uti dins Guds hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Man skall icke mer kalla dig den öfvergifna, ej heller ditt land ett öde; utan du skall kallas: Min lust i henne, och ditt land: Det hafver en Herra; ty Herren hafver lust till dig, och ditt land hafver en Herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Ty såsom en ung man hafver ena jungfru kär, så skola din barn hafva dig kär; och såsom en brudgumme gläder sig öfver brudena, så skall ock din Gud fröjda sig öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'O Jerusalem! jag vill beställa väktare uppå dina murar, de som icke tiga skola hvarken dag eller natt: och de som på Herran tänka skola, på det att när eder intet tyst vara skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Och I icke skolen tiga om honom, tilldess Jerusalem varder beredt, och satt till ett lof uppå jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Herren hafver svorit vid sina högra, hand, och vid sins magts arm: Jag vill icke mer gifva dina säd dinom fiendom till att äta, ej heller din must, der du uppå arbetat hafver, de främmande dricka låta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Utan de som insamla det, de skola ock ätat, och lofva Herran; och de som införat, skola dricka det uti mins helgedoms gårdar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Går, går genom porten; bereder folkena väg; görer väg, görer väg; rödjer bort stenarna, reser ett baner upp emot folken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Si, Herren låter höra sig allt intill verldenes ända: Säger dottrene Zion: Si, din salighet kommer; si, hans arbete och hans verk skall icke vara utan frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Man skall kalla dem det heliga folket, Herrans förlossade; och dig skall man kalla den besökta, och icke öfvergifna staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Ho är den som ifrån Edom kommer, med färgad kläder ifrå Bozra; den så beprydd är i sin kläder, och går i sine stora kraft? Jag är den som rättfärdighet lärer, och är en mästare till att hjelpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Hvi är då din klädnad så röd, och din kläder såsom en vintrampares?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Jag trampar vinpressen allena, och ingen af folken är med mig; jag hafver trampat dem i mine vrede, och nedertrådat dem i mine grymhet; deraf hafver deras blod stänkt min kläder, och jag hafver besmittat all min kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Ty jag hafver tagit mig en hämndadag före; året till att förlossa de mina är kommet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Ty jag såg mig om, och der var ingen hjelpare; och jag var i förskräckelse, och ingen uppehöll mig; utan min arm måste hjelpa mig, och min vrede uppehöll mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Derföre hafver jag förtrampat folken uti mine vrede, och gjort dem druckna uti mine grymhet, och stött deras seger till markena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Herrans barmhertighet vill jag ihågkomma, och Herrans lof, i allt det Herren oss gjort hafver, och det myckna goda med Israels hus, som han dem gjort hafver, genom sina barmhertighet och stora mildhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Ty han sade: De äro ju mitt folk, barn som icke falsk äro; derföre var han deras Frälsare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Den som dem bedröfvade, han bedröfvade ock honom; och Ängelen, som för honom är, halp dem; han förlossade dem, derföre att han älskade dem, och skonade dem; han tog dem upp, och bar dem alltid af ålder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Men de förbittrade och bedröfvade hans Helga Anda; derföre blef han deras fiende, och stridde emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Och han tänkte åter på de förledna tider, på Mose som i hans folk var: Hvar är då nu den som förde dem utu hafvet, samt med sins hjords herda? Hvar är den som sin Helga Anda i dem gaf?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Den Mose ledde vid högra handena, genom sin härliga arm; den der vattnet skiljde för dem, på det han skulle göra sig ett evigt namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Den der förde dem igenom djupen, såsom hästar i öknene, de der intet snafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Såsom fä, det der nedergår på markene, det Herrans Ande drifver; alltså hafver du ock fört ditt folk, på det du skulle göra dig ett härligit namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Så se nu af himmelen, och skåda neder af dine helga och härliga boning; hvar är nu ditt nit, din magt? Din stora hjerteliga barmhertighet håller sig hårdeliga emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Äst du dock vår fader; ty Abraham vet intet af oss, och Israel känner oss intet; men du, Herre, äst vår fader, och vår förlossare, af ålder är det ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Hvi låter du oss, Herre, ville fara ifrå dina vägar, och vårt hjerta förstockas, så att vi icke frukte dig? Vänd om för dina tjenares skull, för ditt arfs slägtes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'De besitta ditt helga folk snart alltsamman; våre motståndare nedertrampa din helgedom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Vi äre såsom tillförene, då du icke rådde öfver oss, och då vi efter ditt Namn icke nämnde vorom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'O! att du ville låta himmelen remna, och du fore hitneder, att bergen för dig flyta måtte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Såsom ett hett vatten för kraftigom eld försjuder, att ditt Namn måtte kunnigt varda ibland dina fiendar, och Hedningarna måste darra för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Genom de under, som du gör, de man sig intet förser, då du nederfor, och bergen försmulto för dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Såsom af verldenes begynnelse icke hördt är; det ock intet öra förnummit, och intet öga sett hafver, utan du Gud, hvad dem sker, som förbida honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Du mötte de glada, och dem som rättfärdighet brukade, och på dinom vägom tänkte uppå dig; si, du vast väl vred, då vi syndade, och länge blefvo deruti; men oss vardt ändå hulpet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Men nu äre vi allesammans såsom de orene, och alla våra rättfärdigheter äro såsom ett orent kläde; vi äre alle bortfalnade såsom löf, och våra synder föra oss bort såsom ett väder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Ingen åkallar ditt Namn, eller uppstår till att hålla sig intill dig; ty du gömmer bort ditt ansigte för oss, och låter oss försmäkta uti våra synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Men nu, Herre, du äst vår Fader; vi äre ler. Du äst vår mästare, och vi äre alle dina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Herre, var icke för fast vred, och tänk icke på syndena evinnerliga; se dock deruppå, att vi alle äre ditt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Dins helgedoms städer äro öde vordne; Zion är öde vordet; Jerusalem ligger förstördt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Vår helighets och härlighets hus, der våre fäder dig utinnan lofvat hafva, är uppbrändt med eld, och allt det kosteliga, som vi hadom, är till skam gjordt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Vill du, Herre, vara så hård härutinnan, och stilla sitta, och så svårliga, nederslå oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Jag varder sökt af dem som intet efter mig frågade; jag varder funnen af dem som intet sökte mig; och till Hedningarna, som mitt Namn intet åkallade, säger jag: Här är jag, här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Ty jag uträcker mina händer hela dagen till ett ohörsamt folk, som efter sina tankar vandrar på den väg, som intet god är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Ett folk, som mig förtörnar, är alltid för mitt ansigte; offrar i örtagårdom, och röker på tegelstenar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Bor ibland grifter, och håller sig uti kulor; äta svinakött, och hafva förbudet såd uti deras grytor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Och säga: Blif hemma, och kom intet vid mig; ty jag skall helga dig. Desse skola varda en rök i mine vrede, en eld, som brinner hela dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Si, det står skrifvet för mig: Jag vill icke tiga, utan betala; ja, jag vill betala dem i deras sköt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Både deras missgerningar, och deras fäders missgerningar tillsammans, säger Herren; de som på bergen rökt, och mig på högarna försmädat hafva; jag skall mäta dem deras förra väsende uti deras sköt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Så säger Herren: Likasom då man must finner uti vindrufvone, och säger: Förderfva det icke, ty der är en välsignelse uti; alltså vill jag för mina tjenares skull göra, att jag icke förderfvar det allt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Utan vill låta växa utaf Jacob säd, och af Juda den som mitt berg besitta skall; ty mine utkorade skola besitta det, och mine tjenare skola der bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Och Saron skall vara ett hus för hjordar, och Achors dal skall ett fälägre varda, mino folke som mig söka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Men I som Herran förlåten, och mitt helga berg förgäten, och uppresen till Gad ett bord, och skänken fullt in af drickoffer för Meni;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Nu väl, jag vill uträkna eder till svärd, så att I alla måsten bocka eder till slagtning; derföre, att jag kallade, och I svaraden intet; jag talade, och I hörden intet, utan gjorden det mig misstyckte, och utvalden det mig intet täckt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Derföre säger Herren Herren alltså: Si, mine tjenare skola äta; men I skolen hungra; Si, mine tjenare skola dricka, men I skolen törsta; si, mine tjenare skola glade vara, men I skolen till skam varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Si, mine tjenare skola fröjda sig för godt mods skull; men I skolen för hjertans sorgs skull ropa, och för jämmer gråta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Och skolen låta edor namn minom utkoradom till ett svärjande: och Herren Herren skall döda dig, och nämna sina tjenare med ett annat namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Så att den som sig välsignar på jordene, han skall välsigna sig uti den rätta Guden; och den som svär på jordene, han skall svärja vid den rätta Guden; ty de förra bedröfvelser äro förgätne, och äro förskyld för min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Ty si, jag vill skapa en ny himmel, och ena nya jord; så att man intet mer skall komma den förra, ihåg, eller lägga dem på hjertat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Utan de skola fröjda sig evinnerliga, och glade vara öfver det som jag skapar; ty si, jag vill skapa Jerusalem till fröjd, och dess folk till glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Och jag vill glad vara öfver Jerusalem, och fröjda mig öfver mitt folk; och gråtoröst eller klagoröst skall icke mer derinne hörd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Der skola icke mer vara barn, som icke räcka till deras dagar, eller gamle som deras år icke uppfylla; utan hundradeåra barn skola dö, och de hundradeåra syndare skola förbannade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'De skola bygga hus, och bo deruti; de skola plantera vingårdar, och äta fruktena af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'De skola icke bygga, att en annar bor deruti, och icke plantera, att en annar äter; ty mins folks dagar skola vara såsom ett träs dagar, och deras händers verk skall föråldras när mina utkorade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'De skola icke arbeta fåfängt, eller föda otidiga födslo; ty de äro Herrans välsignadas säd, och deras efterkommande med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Och skall ske, att förr än de ropa, vill jag svara; medan de ännu tala, vill jag höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Ulfven och lambet skola gå i bet tillsamman; lejonet skall äta strå, såsom ett nöt, och ormen skall äta jord; de skola ingen skada eller förderf göra på hela mitt helga berg, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Så säger Herren: Himmelen är min stol, och jorden är min fotapall; hvad är det då för ett hus, som I mig bygga viljen? Eller hvar är det rummet, der jag hvila skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Min hand hafver gjort allt det som är, säger Herren; men jag ser till den elända, och till den som en förkrossad anda hafver, och till den som fruktar för mitt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Ty den en oxa slagtar, är lika som han en man sloge; den ett får offrar, är såsom den der halsen sönderbröte af en hund; den spisoffer frambär, är såsom den der svinablod offrar; den som uppå rökelse tänker, han är såsom den det orätt är prisar; sådant utvälja de uti deras vägar, och deras själ hafver lust i deras styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Derföre vill jag ock utvälja det de tänka förvara sig före; det de frukta, vill jag låta kom öfver dem; derföre, att jag kallade, och ingen svarade; att jag talade, och de hörde intet, och gjorde det mig misshagade, och utvalde det mig icke täckt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Hörer Herrans ord, I som frukten för hans ord: Edre bröder, som eder hata, och afskilja eder för mitt Namns skull, säga: Låter se, huru härlig Herren är; låter se honom till edra glädje; de skola till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Ty man skall få höra en rumors röst i stadenom, en röst af templet; en Herrans röst, som sinom fiendom vedergäller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Hon föder förr än hon får någon värk; förr än hennes nöd kommer, föder hon en pilt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Ho hafver någon tid nu sådant hört? Ho hafver någon tid sådant sett? Kan ock, förr än ett land värk får, ett folk tillika födt varda? Nu hafver ju Zion födt sin barn utan värk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Skulle jag andra låta öppna moderlifvet, och sjelf ock icke föda? säger Herren. Skulle jag Iåta andra föda, och sjelf tillyckt vara? säger din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Fröjder eder med Jerusalem, och varer glade öfver thy, alle I som det kärt hafven; fröjder eder med thy, alle I som deröfver sörjt hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Ty derföre skolen I suga, och mätte varda af dess hugsvalelses bröst; I skolen derföre suga, och lust hafva af dess härlighets fullhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Ty alltså säger Herren: Si, jag utbreder frid dervid såsom en ström, och Hedningarnas härlighet såsom en utsläppt bäck; då skolen I suga; I skolen i famna borne varda, och på knän skall man ljufliga hålla eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Jag vill hugsvala eder, såsom modren hugsvalar någon; ja, I skolen af Jerusalem lust hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'I skolen få set, och edart hjerta skall glädja sig, och edor ben skola grönskas såsom gräs; då skall man känna Herrans hand på hans tjenare, och hans vrede på hans fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Ty si, Herren skall komma med eld, och hans vagnar såsom ett stormväder; att han skall vedergälla uti sine vredes grymhet, och hans straff uti en eldslåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Ty Herren skall döma igenom eld, och genom sitt svärd, allt kött, och de dräpne af Herranom skola vara månge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'De som helga och rena sig i örtegårdar, den ene här, den andre der, och äta svinakött, styggelse och möss, skola tillsammans borttagne varda, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Ty jag vill komma och församla deras gerningar och tankar, samt med alla Hedningar och tungomål, att de skola komma och se mina härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Och jag vill gifva ett tecken ibland dem, och sända några af dem, som frälste äro, till Hedningarna vid hafvet; till Phul och Lud, till de bågaskyttar, till Thubal och Javan; och fjerran bort till de öar, der man intet af hört hafver, och de mina härlighet intet sett hafva; och skola förkunna mina härlighet ibland Hedningarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Och skola draga dertill alla edra bröder utaf allom Hedningom, Herranom till ett spisoffer, på hästar och på vagnar, på bårar, mular, på kärror, till Jerusalem, mitt helga berg, säger Herren, lika som Israels barn bära spisoffer i rena kärile, till Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Och jag vill utaf de samma taga Prester och Leviter, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Ty lika som den nye himmelen och den nya jorden, de jag skapar, stå för mig, säger Herren; alltså skall ock edor säd och namn stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Och allt kött skall komma, den ena månaden efter den andra, och den ena Sabbathen efter den andra, till att tillbedja för mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Och de skola gå ut, och se de menniskors kroppar; som emot mig misshandlat hafva; ty deras matk skall icke dö, och deras eld skall icke utslockna, och skola vara en styggelse för allt kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Detta är Jeremia ord, Hilkia sons, af de Prester i Anathoth, i BenJamins land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Till hvilken skedde Herrans ord i Josia tid, Amons sons, Juda Konungs, uti trettonde årena af hans rike;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Och sedan intill Jojakims tid, Josia sons, Juda Konungs, allt intill ändan på ellofte årena Zedekia, Josia sons, Juda Konungs, intill Jerusalems fängelse, i femte månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Jag kände dig, förr än jag tillredde dig i moderlifvet, och utkorade dig, förr än du af modrene född vardt, och satte dig till en Prophet ibland mång folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Men jag sade: Ack! Herre Herre, jag doger intet till att predika, ty jag är för ung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Då sade Herren till mig: Säg icke: Jag är för ung; utan du skall gå dit jag sänder dig, och predika hvad jag befaller dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Frukta dig intet för dem; ty jag är när dig, och vill frälsa dig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Och Herren räckte ut sina hand, och tog uppå min mun; och Herren sade till mig: Si, jag sätter min ord i din mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Si, jag sätter dig i dag öfver folk och rike, att du skall upprycka, nederbryta, förstöra och förderfva, och bygga, och plantera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Och Herrans ord skedde till mig, och sade: Jeremia, hvad ser du? Jag sade: Jag ser en vakande staf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Och Herren sade till mig: Rätt hafver du sett; ty jag vill vaka öfver mitt ord, att jag det göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Och Herrans ord skedde annan gången till mig, och sade: Hvad ser du? Jag sade: Jag ser en het sjudande gryto nordanefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Och Herren sade till mig: Nordanefter skall ondt komma öfver alla de som i landena bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Ty si, jag vill kalla alla Förstar uti de rike norrut, säger Herren, att de skola komma och sätta sin säte inför portarna i Jerusalem, och allt omkring murarna, och för alla Juda städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Och jag skall låta rätten gå öfver dem, för alla deras ondskos skull, att de öfvergifva mig, och röka androm gudom, och tillbedja sina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Så begjorda nu dina länder, och statt upp, och predika dem allt det jag bjuder dig; frukta dig intet för dem, lika som jag skulle afskräcka dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Ty jag vill i denna dag göra dig till en fast stad, till en jernpelare, och till en kopparmur i hela landena, emot Juda Konungar, emot hans Förstar, emot hans Prester, emot folket i landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Så att, om de än strida emot dig, skola de likväl intet öfvervinna dig; ty jag är när dig, säger Herren, att jag skall frälsa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Gack bort, och predika uppenbarliga i Jerusalem, och säg: Så säger Herren: Jag tänker uppå den välgerning, som dig skedde i dinom ungdom, och den kärlek, som jag dig beviste, då du vast dägelig, då du följde mig i öknene, uti det land der man intet sår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Då Israel Herrans egen var, och hans första, frukt; den honom fräta ville, han måste få skuld, och olycka öfver honom komma, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Hörer Herrans ord, I af Jacobs hus, och all slägte af Israels hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Detta säger Herren: Hvad hafver edra fäder fattats uppå mig, att de trädde ifrå mig, och föllo intill de onyttiga afgudar, der de dock intet förvärfde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Och tänkte icke ens: Hvar är Herren, den oss utur Egypti land förde, och ledde oss i öknene, uti en öde vildmark, uti en torro och mörko mark, uti de mark der ingen vistades, eller någor menniska bodde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Och jag hade eder in uti ett godt land, att I dess frukt och dess goda äta skullen; och då I der inkommen, orenaden I mitt land, och gjorden mitt arf till en styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Presterna tänkte intet: Hvar är Herren? Och de lärde aktade mig intet; och herdarna förde folket ifrå mig, och Propheterna propheterade om Baal, och föllo intill de onyttiga afgudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Jag måste ju alltid träta med eder, och edrom barnabarnom, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Går bort till Chittims öar, och ser till, och sänder till Kedar, och märker granneliga, och skåder till, om det går så der till;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Om Hedningarna omskifta sina gudar, ändock de inga gudar äro, och mitt folk hafver likväl omskift sina härlighet uti en onyttig afgud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Måtte dock himmelen gifva sig dervid, förskräckas och bäfva, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Ty mitt folk gör en dubbel synd: Mig, som är en lefvande källa, öfvergifva de, och göra sig brunnar, ja, usla brunnar; ty de gifva intet vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Är då Israel en träl eller lifegen, att han hvars mans rof vara måste?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Ty lejonen ryta öfver honom, och ropa, och föröda hans land, och förbränna hans städer, så att der bor ingen uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'De af Noph och Thahpanhes förkrossa dig hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Detta gör du dig sjelf, i det att du öfvergifver Herran din Gud, så ofta han dig den rätta vägen leda vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Hvad hjelper dig det, att du far in uti Egypten, och vill dricka af det vattnet Sihor? Och hvad hjelper dig det, att du far till Assyrien, och vill dricka af älfvene (Phrath)?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Det är dine ondskos skull, att du så plågad varder, och dine olydnos, att du så näpst varder: Alltså, måste du få veta och förfara, hvad jämmer och sorg det med sig hafver, att du öfvergifver Herran din Gud, och icke fruktar mig, säger Herren, Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Ty du hafver af ålder sönderbrutit ditt ok, och sönderslitit din band, och sagt: Jag vill icke så undertryckt vara; utan uppå all hög berg och under all grön trä lopp du efter horeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Men jag hade planterat dig till ett sött vinträ, och till en ganska rättsinnig säd; huru äst du då nu mig vorden till ett bittert vildt vinträ?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Och om du än tvådde dig med lut, och toge der mycken såpo till, så synes dock din ondsko dessmer för mig, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Huru tör du då säga: Jag är intet oren: jag håller mig icke intill Baalim? Se till, huru du hafver bedrifvit det i dalenom, och betänk, huru du gjort hafver; du lopp omkring såsom en camelinna uti sinom hetta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Och såsom vildåsnen plägar i öknene, då han af stor hetta så oförvägen löper, att ingen kan stilla honom. Den som det veta vill, han torf icke vida löpa; på vexledagomen ser man det väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Käre, håll dock stilla, och löp icke så oförvägen; men du sade: Der varder intet af; jag måste bola med de främmande, och löpa efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Lika som en tjuf kommer till skam, då han gripen varder; alltså skall Israels hus på skam komma, samt med deras Konungar, Förstar, Prester och Propheter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Hvilke till trät säga: Du äst min fader; och till stenen: Du hafver födt mig; ty de vände ryggen till mig, och icke ansigtet; men när nöd är på, så säga de: Upp, och hjelp oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Hvar äro då dine gudar, som du dig gjort hafver? Bed dem stå upp; låt se, om de kunna hjelpa dig i dine nöd; ty så många städer, så många gudar hafver du, Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Hvad viljen I ännu gå till rätta med mig? I ären alle ifrå mig fallne, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'All hugg äro förgäfves på edor barn, de låta dock intet tukta sig; ty edart svärd uppfräter likväl edra Propheter, såsom ett grymt lejon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Du onda art, gif akt uppå Herrans ord: Är jag nu vorden Israel till en öken eller ödemark? Hvi säger då mitt folk: Vi äre herrar, och vilje intet löpa efter dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'En jungfru förgäter dock icke sin krans, eller en brud sina hedersgåfvo; men mitt folk förgäter mig evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Hvad bepryder du mycket ditt väsende, att jag skall vara dig nådelig? Under sådana sken bedrifver du ju mer och mer ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Dertill finner man de fattigas och oskyldigas själars blod när dig i all rum; och det är icke hemligit, utan uppenbart uti de samma rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Och du säger ännu: Jag är oskyldig; han vände sina vrede ifrå mig; si, jag vill gå till rätta med dig om det du säger: Jag hafver icke syndat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Hvi hvekar du så mycket, och faller nu hit och nu dit? Men du skall till skam varda med Egypten, lika som du med Assyrien till skam vorden äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Ty du måste ock dädan draga, och slå dina händer tillhopa uppå hufvudet; ty Herren skall låta ditt hopp fela, och intet skall lyckas dig när dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Man säger: När en man skiljer sina hustru ifrå sig, och hon far ifrå honom och tager en annan man, tör han ock taga henne till sig igen? Vorde icke då landet orenadt? Men du hafver bolat med många bolar, dock kom igen till mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Lyft din ögon upp i höjdena, och se till, huru du allestäds horeri bedrifver; på vägomen sitter du, och vaktar uppå dem, likasom en röfvare i öknene, och orenar landet med ditt horeri och din ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Derföre måste ock arlaregn borto blifva, och intet serlaregn komma; du hafver ett skökoansigte; du vill icke mer skämmas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Och ropar likväl till mig: Käre fader, du mins ungdoms mästare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Vill du dock vred vara evinnerliga, och icke aflåta af dine grymhet? Si, du lärer och gör det ondt är, och låter intet styra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Och Herren sade till mig, i Konung Josia tid: Hafver du ock sett hvad Israel, den affälliga, gjorde? Hon gick bort uppå all hög berg, och under all grön trä, och bedref der horeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Och jag sade, då hon detta alltsammans gjort hade: Vänd dig om till mig; men hon vände sig intet; och hennes syster Juda, den förhärda, såg det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Och jag såg, att ändock jag den affälliga Israels horeri straffade, och öfvergaf henne, och gaf henne ett skiljobref, likväl fruktar sig hennes syster, den förhärda Juda, intet; utan går bort, och bedrifver också horeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Och af hennes horeris rykte är landet orenadt; förty hon bedrifver horeri med stock och sten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Och i allt detta omvänder sig den förhärda Juda, hennes syster, intet till mig af allt hjerta; utan skrymtar, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Och Herren sade till mig: Den affälliga Israel är from räknandes emot den förhärda Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Gack bort, och predika norrut alltså, och säg: Vänd om du affälliga Israel, säger Herren, så vill jag intet vända mitt ansigte ifrån eder; ty jag är barmhertig, säger Herren, och vill icke vredgas evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Allenast känn dina missgerningar, att du emot Herran din Gud syndat hafver, och hit och dit lupit till främmande gudar, under all grön trä, och hafver icke lydt mine röst, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Omvänder eder, I affälliga barn, säger Herren; ty jag vill trolofva eder mig, och vill hemta eder, så att en skall föra en hel stad, och två ett helt land, och jag skall låta eder komma till Zion;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Och skall gifva eder herdar, efter mitt hjerta, de eder föda skola med lärdom och vishet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Och det skall ske, när I växen till, och ären månge vordne i landena, så skall man, säger Herren, på den tiden intet mer tala om Herrans förbunds ark, och intet mer komma honom ihåg, eller deraf predika, eller besöka honom, eller något mer offra der;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Utan på den tiden skall man kalla Jerusalem Herrans säte, och alle Hedningar skola församla sig dit, för Herrans Namns skull i Jerusalem; och skola icke mer vandra efter sins onda hjertas tankar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'På den tiden skall Juda hus gå till Israels hus, och skola tillsammans komma nordanefter, in uti det land som jag edra fäder till arfs gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Och jag säger dig till: O! huru mång barn vill jag gifva dig, och det goda landet, det sköna arfvet, nämliga Hedningarnas kärna. Och jag säger dig till: Du skall på den tiden kalla mig käre Fader, och intet vika ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Men Israels hus aktar mig intet, likasom en qvinna nu icke mer aktar sin bola, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Derföre skall man få höra en klagelig gråt och jämmer af Israels barn på högarna; derföre, att de illa gjort, och Herran sin Gud förgätit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Så vänder nu om, I affällige barn, så vill jag hela eder af edro olydno. Si, vi komme till dig; ty du äst Herren vår Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Sannerliga, det är icke utan bedrägeri med de högar, och med all berg; sannerliga, Israel hafver ingen hjelp, utan allena af Herranom vårom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Och våra fäders stiktningar, de vi af ungdom hållit hafva, måste afgå med skam; samt med deras får, fä, söner och döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Ty der vi förläte oss uppå, det är oss nu alltsammans till skam; och der vi tröste uppå, der måste vi nu skämmas vid; ty vi syndadom dermed emot Herran vår Gud, både vi och våre fäder, allt ifrå vår ungdom och intill denna dag, och lyddom icke Herrans vår Guds röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Vill du omvända dig, Israel, säger Herren, så vänd dig till mig; och om du bortlägger din styggelse ifrå mitt ansigte, så skall du icke bortdrifven varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Då skall du svärja, utan skrymteri, rätt och heligt: Så visst som Herren lefver; och Hedningarna skola i honom välsignade varda, och berömma sig af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Ty så säger Herren till dem i Juda och i Jerusalem: Plöjer på nytt, och sår icke ibland törne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Omskärer eder Herranom, och lägger bort edars hjertas förhud, I Juda män, och Jerusalems inbyggare; på det min grymhet icke skall utfara såsom en eld, och brinna så, att henne ingen utsläcka, kan, för edra ondskos skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Ja, förkunner då i Juda, och roper högt i Jerusalem, och säger: Blåser upp trummeter i landena. Roper med höga röst, och säger: Församler eder, och låter oss draga in uti fasta städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Uppreser ett baner i Zion, skicker eder i rotar, och töfver icke; ty jag låter komma hit en olycko ifrå nordan, och en stor jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Lejonet kommer utdragandes utu sine kulo, och Hedningarnas förderfvare drager ut ifrå sitt rum; på det han skall föröda ditt land, och uppbränna dina städer, så att der skall ingen bo uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Derföre drager säcker uppå; gråter, och jämrer eder; ty Herrans grymma vrede vill icke ifrån oss återvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'På den tiden, säger Herren, skall Konungens och Förstarnas hjerta förfalla; Presterna skola varda förfärade, och Propheterna förskräckte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Men jag sade: Ack! Herre Herre, du hafver det desso folke och Jerusalem fast mycket fela låtit, då de sade: Det skall vara frid när eder, ändock svärdet räcker allt intill själena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'På den tiden skall man säga till detta folket, och till Jerusalem: Ett torrt väder kommer utöfver bergen, såsom utur öknene, på den vägen till mins folks dotter, icke till att kasta eller rensa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Ja, ett väder kommer, som dem alltför starkt vara skall; så vill jag då ock gå till rätta med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Si, han far bortåt såsom en sky, och hans vagnar äro såsom ett stormväder; hans hästar äro snarare än örnar; ve oss, vi måste förderfvade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Så två nu, Jerusalem, ditt hjerta ifrå ondskone, på det att dig må hulpet varda; huru länge skola de skadeliga läror när dig blifva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Ty af Dan kommer ett rop, och ett ondt bådskap ifrån Ephraims berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Förkunner det ibland Hedningarna; si, låter ryktet komma intill Jerusalem, att vaktare komma af fjerran landom, och skola skria emot Juda städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'De skola belägga dem allt omkring, såsom vaktare på markene; ty de hafva förtörnat mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Det hafver du till lön för ditt väsende och dina gerningar; då skall ditt hjerta känna, huru stor din ondska är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'O! huru är mig så ondt i hjertat; mitt hjerta bultar i kroppen, och hafver ingen ro; ty min själ hörer basunaljud, och en slagtning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Och ett mordskri öfver det andra; ty hela landet varder förhärjadt; med hast varda mina hyddor och min tjäll förstörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Huru länge skall jag nu se baneren, och höra basunaljudet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Men mitt folk är galet, och tror mig intet; galne äro de, och aktat intet; vise nog äro de till att göra det ondt är; men att göra det godt är, vilja de icke lära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Jag såg uppå jordena, si, hon var tom och öde; och uppå himmelen, och han var mörk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Jag såg uppå bergen, och si, de bäfvade, och alle högar darrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Jag såg, och si, der var ingen menniska; och alle foglar under himmelen voro bortflogne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Jag såg, och si, åkermarken var öde, och alle städer derinne voro nederbrutne af Herranom, och af hans grymma vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Ty så säger Herren: Hela landet skall öde varda, och jag skall platt intet skona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Derföre skall jorden vara bedröfvad, och himmelen ofvantill sörjande; ty jag hafver det sagt; jag hafver beslutit det, och det skall intet ångra mig; jag vill ock intet öfvergifvat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Alle städer skola fly för resenärers och skyttars rop, och löpa uti tjocka skogar, och krypa in uti stenklyftor; alle städer skola stå öde, så att der bor ingen uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Hvad Till du göra, du förstörda? Om du än prydde dig med purpurkläde, och med gyldene klenodier, och färgade ditt ansigte, så pryder du dig dock fåfängt; ty de som nu hofvera för dig, de skola förakta dig; de skola gå efter ditt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Förty jag hörer ett rop, såsom enes den der föder; en ångest, såsom enes den der i första barnsnöd är; ett dottrenes Zions rop, den der klagar och utslår händerna: Ack! ve mig, jag måste nästan förgås för dråps skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Går omkring gatorna i Jerusalem, och ser till, och förfarer; och söker på dess gator, om I någon finnen, som rätt gör, och efter trona, så vill jag vara honom nådelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Och om de än sade: Så sant som Herren lefver; så svärja de dock falskeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Herre, din ögon se efter trone. Du slår dem, och de kännat intet; du plågar dem, men de bättra sig intet; de hafva ett ansigte hårdare än sten, och vilja icke omvända sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Men jag tänkte: Må ske, att den arme hopen är oförståndig; vet intet af Herrans väg, och af sins Guds rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Jag vill gå till de väldiga, och tala med dem; de måste ju veta af Herrans väg, och sins Guds rätt; men de samme hade alle sönderbrutit oket, och sönderslitit banden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Derföre skall ock lejonet, som af skogen kommer, sönderrifva dem, och ulfven af öknene skall förderfva dem, och parden skall vakta på deras städer; alla de som der utgå, skall han uppäta; ty deras synder äro alltför många, och de äro vordne förhärde uti sine olydno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Huru skall jag då vara dig nådelig; efter din barn öfvergifva mig, och svärja vid den som ingen gud är? Och nu, medan jag dem mättat hafver, bedrifva de hor, och löpa uti horohus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Hvar och en vrenskas efter sin nästas hustru, såsom välfodrade stodhästar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Och skulle jag icke för sådant hemsöka dem, säger Herren; och skulle min själ icke hämnas öfver sådant folk, som detta är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Bestormer hans murar och kaster dem omkull, och skoner intet; förer bort hans vinqvistar; ty de äro icke Herrans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Utan de förakta mig, både Israels hus, och Juda hus, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'De förneka Herran, och säga: Det är icke han, och oss varder icke så illa gåendes; svärd och hunger kommer intet öfver oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Propheterna tala mycket i vädret, och hafva intet Guds ord; det gånge dem så sjelfvom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Derföre säger Herren Gud Zebaoth: Efter I sådana tal hafven, si, så vill jag göra min ord i dinom mun till en eld, och detta folk till trä, och han skall förtära dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Si, jag skall låta komma öfver eder af Israels hus, säger Herren, ett folk fjerranefter; ett mägtigt folk, hvilket det första folk varit hafver; ett folk, hvilkets tungomål du intet förstår, och intet förnimma kan, hvad de säga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Deras koger äro öppna grifter; ja, de äro allesamman hjeltar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'De skola förtära din säd och ditt bröd; de skola uppäta dina söner och döttrar; de skola uppsluka din får och ditt fä; de skola förtära din vinträ, och fikonaträ; dina fasta städer, der du förlåter dig uppå, skola de förderfva med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Och jag skall på den tid, säger Herren, intet skona eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Och om de varda sägande: Hvi gör Herren vår Gud oss allt detta? så skall du svara dem: Lika som I hafven öfvergifvit mig, och tjenen främmande gudar, uti edart eget land; alltså skolen I ock tjena främmandom uti ett land, det icke edart är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Detta skolen I förkunna i Jacobs hus, och predika i Juda, och säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Hörer till, I galna folk, som intet förstånd hafven; I som ögon hafven, och sen intet; öron hafven, och hören intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Viljen I icke frukta mig, säger Herren, och intet förskräckas för mig, som sätter hafvena sina strand, derinnan det alltid blifva måste, och der intet öfvergå? Och om det än svaller, så förmår det dock intet; och om dess böljor än fast bullra, så måste de dock icke der öfvergå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Men detta folket hafver ett affälligt och ohörsamt hjerta; blifva affällige, och hållat så allt framåt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Och säga icke en tid i sitt hjerta: Låt oss dock frukta Herran vår Gud, den oss arlaregn och serlaregn gifver i rättom tid; och bevarar oss årsväxten troliga och årliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Men edra missgerningar förhindra detta, och edra synder vända detta goda ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Ty man finner ibland mitt folk ogudaktiga, de der ställa snaror och gildre för menniskorna, att de måga fånga dem, lika som foglafångare göra med klofvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Och deras hus äro full med bedrägeri, lika som en foglabur är full med lockofoglar; deraf varda de väldige, rike och fete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'De omgå med ond stycker; de hålla ingen rätt; den faderlösa främja de icke i hans sak, dock går dem väl, och hjelpa icke den fattiga till rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Skulle jag det icke hemsöka, säger Herren; och skulle min själ icke hämnas uppå sådant folk, som detta är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Det står grufveliga och styggeliga till i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Propheterna lära falskt, och Presterna äro herrar i deras ämbete, och mitt folk vill gerna så hafvat; huru vill eder gå för sådant på sistone?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Församler eder, I BenJamins barn utu Jerusalem, och blåser i trummeter på Thekoa vakt, och reser upp ett baner på BethCherems vakt; ty en olycka är på färde ifrå nordan, och en stor jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Dottren Zion är såsom en dägelig och lustig äng;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Men der skola herdar komma öfver henne med deras hjord; de skola uppslå sin tjäll allt omkring henne, och i bet ligga hvar på sitt rum (och säga):');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Ruster eder till strid emot henne; upp, låter oss draga upp, medan det ännu bittida dags är; ej! det kommer aftonen, och skuggen varder stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Nu väl, låt oss nu vara uppe, det vi än skulle draga ditupp om nattena, och förderfva hennes palats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Ty så säger Herren Zebaoth: Fäller trä, och görer bålverk emot Jerusalem; ty det är en stad, som hemsökt skall varda; är der dock alltsammans orätt inne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Och likasom en källa uppväller sitt vatten, så uppväller ock hans ondska; hans orätt och öfvervåld ropar upp i himmelen; sitt mord och slag bedrifva de dagliga för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Bättra dig, Jerusalem, förr än mitt hjerta vänder sig ifrå dig, och jag gör dig till ett öde land, der ingen uti bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Detta säger Herren Zebaoth: Hvad qvart blifvet är af Israel, det måste ock efteråt afhemtadt varda, lika som ett vinträ; vinhemtaren skall afhemta uti korgen det ena efter det andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Ack! med hvem skall jag dock tala och betyga, att dock någor ville hörat? Men deras öron äro oomskorne; de kunna icke hörat; si, de hålla Herrans ord för gäckeri, och vilja det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Derföre är jag så full af Herrans trugande, att jag icke kan låtat; gjut ut både öfver barnen på gatone, och öfver de män i Rådet allt tillsammans; ty både man och qvinna, både åldrig och utgammal skola fångne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Deras hus skola komma främmande tillhanda, samt med åkrar och hustrur; ty jag vill uträcka mina hand, säger Herren, öfver landsens inbyggare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Ty de fara allesammans efter girighet, både små och store; och både Propheter och Prester lära allesamman falska Gudstjenst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Och trösta mitt folk i deras olycko, att de skola det ringa akta, och säga: Det står väl till, det står väl till; och det står dock intet väl till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Derföre skola de komma på skam, att de sådana styggelse bedrifva; ändock de vilja oskämde vara, och vilja intet skämma sig; derföre måste de falla hvar öfver annan; och när jag varder dem hemsökandes, skola de falla, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Detta säger Herren: Går uppå vägarna, och ser till, och fråger efter de förra vägar, hvilken den gode vägen är, och vandrer deruppå, så skolen I finna ro för edra själar; men de sade: Vi göre det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Jag hafver satt väktare öfver eder; akter uppå trummeternas ljud; men de sade: Vi göret intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Derföre hörer, I Hedningar, och akter häruppå, samt med edart folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Du jord, hör till: Si, jag vill låta komma en olycko öfver detta folk, nämliga deras förtjenta lön, att de icke akta min ord, och förkasta min lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Hvad frågar jag efter rökelse, som kommer af rika Arabien, och efter god canel, som kommer utaf fjerran land? Edor bränneoffer äro mig intet tacknämlig, och edor offer behaga mig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Derföre säger Herren alltså: Si, jag vill sätta desso folkena en förargelse, der både fäder och barn skola sig tillsammans uppå stöta, och skola förgås, den ene grannen med den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Detta säger Herren: Si, ett folk varder kommandes nordanefter, och ett stort folk skall uppresa sig hardt vid vårt land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'De der båga och spets föra; det är grufveligit, och utan barmhertighet; de fräsa såsom ett stormande haf, och rida på hästar, rustade såsom krigsfolk, emot dig, du dotter Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'När vi få höra af dem, så skola oss våra händer nedfalla; oss varder ångest och ve, lika som ene i barnsnöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ingen gånge ut på markena, och ingen ut uppå vägarna; ty det är allestäds osäkert för fiendans svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'O! du mins folks dotter, drag en säck uppå, och lägg dig i asko; haf sorg lika som för enda sonen, och beklaga dig lika som de der högeliga bedröfvade äro; ty förderfvaren kommer öfver oss hasteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Jag hafver satt dig till en smältare i mitt folk, det så hårdt är; att du deras väsende förfara och bepröfva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'De äro allesamman affällige, vandrande förrädeliga; de äro allesamman förderfvad koppar och jern.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Blåsbälgen är förbränd, blyet försvinner, smältningen är förgäfves; ty det onda är icke ifråskildt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Derföre heta de ock ett förkastadt silfver; ty Herren hafver förkastat dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Detta är det ord, som skedde till Jeremia af Herranom, som sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Gack och statt i portenom åt Herrans hus, och predika der detta ordet, och säg: Hörer Herrans ord, I alle af Juda, I som gån genom denna porten, till att tillbedja Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Så säger Herren Zebaoth, Israels Gud: Bättrer edart lefverne och väsende, så vill jag bo när eder i desso rumme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Förlåter eder icke uppå lögn, sägande: Här är Herrans tempel, här är Herrans tempel, här är Herrans tempel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Utan bättrer edart lefverne och väsende, att I gören hvarannan rätt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Och görer främlingenom, dem faderlösa och enkone intet öfvervåld; och utgjuter intet oskyldigt blod i desso rumme, och följer icke andra gudar efter, till edar egen skada;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Så vill jag evinnerliga bo när eder i desso rumme, i landena som jag edra fäder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Men nu förlåten I eder på lögn, den intet nyttig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Dertill ären I tjufvar, mördare, horkarlar, och menedare, och röken inför Baal, och följen främmande gudar efter; de I intet kännen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Sedan kommen I då, och gån fram för mig i desso huse, det efter mitt Namn nämndt är, och sägen: Det hafver ingen nöd med oss, medan vi sådana styggelse görom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Hållen I då detta hus, som efter mitt Namn nämndt är, för ena mördarekulo? Si, jag ser det väl, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Går bort till mitt rum i Silo, der mitt Namn tillförene bott hafver, och ser till, hvad jag der gjort hafver, för mins folks Israels ondskos skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Efter I nu alle sådana stycke bedrifven, säger Herren, och jag eder tidt och ofta predika låter, och I viljen icke hörat; jag ropar, och I viljen intet svara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Så vill jag sammalunda göra med de hus, som efter mitt Namn nämndt är, der I eder uppå förlåten, och med det rum, som jag edra fäder gifvit hafver, likasom jag med Silo gjort hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Och skall kasta eder bort ifrå mitt ansigte, likasom jag bortkastat hafver alla edra bröder, alla Ephrahims säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Och skall du intet bedja för detta folk, ej heller någon klagan eller bön förebära, eller lägga dig ut för dem inför mig; ty jag vill intet höra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Ty ser du icke hvad de göra i Juda städer, och på gatomen i Jerusalem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Barnen hemta veden, och fäderna göra upp elden, och qvinnorna göra degen, att de skola baka himmelens Drottning kakor, och gifva främmande gudar drickoffer, på det de skola förtörna mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Men de skola icke göra mig der ondt med, säger Herren, utan sig sjelfvom, och skola till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Derföre säger Herren Herren: Si, min vrede och min grymhet är utgjuten öfver detta rum, både öfver folk och fä, öfver trän på markene, och öfver fruktena på jordene; och skall brinna, så att ingen skall kunna släckat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Detta säger Herren Zebaoth, Israels Gud: Görer edor bränneoffer och annor offer tillhopa, och äter kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Ty på den dagen, då jag förde edra fäder utur Egypti land, hafver jag intet sagt eller budit dem om bränneoffer och annat offer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Utan detta böd jag dem, och sade: Lyder min ord, så vill jag vara edar Gud, och I skolen vara mitt folk; och vandrer på alla de vägar, som jag bjuder eder, på det eder skall väl gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Men de ville intet höra, eller böja sin öron härtill, utan vandrade efter sitt eget råd, och efter sin onda hjertas tycko, och gingo tillbaka, och icke framåt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Ja, ifrå den dagen att jag edra fäder utu Egypti land förde, och intill denna dag, hafver jag dagliga sändt till eder alla mina tjenare Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Men de ville intet höra, eller böja sin öron, utan äro halsstyfve, och görat än värre än deras fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Och om du än allt detta säger dem, så höra de dock intet; ropar du, så svara de dock intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Derföre säg till dem: Detta är det folk, som Herran sin Gud icke hörer, eller sig bättra vill; den rätta läran är platt borto, och de predika der nu intet mer af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Skär ditt hår af, och kasta det ifrå dig, och jämra dig klageliga på högomen; ty Herren hafver förkastat och bortdrifvit detta slägtet, der han öfver förtörnad är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Förty Juda barn göra det ondt är för min ögon, säger Herren; de sätta sina styggelser uti det hus, som efter mitt Namn nämndt är, på det de skola orena det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Och bygga de altare Thopheth uti Hinnoms sons dal, att de skola uppbränna deras söner och döttrar i eld, hvilket jag aldrig budit, eller någor tid i sinnet fått hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Derföre, si, den tiden kommer, säger Herren, att man intet mer skall kalla det Thopheth, och Hinnoms sons dal, utan dråpodal; och Thopheth skall varda fullt med dödas grifter, derföre, att der intet annat rum på färde är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Och detta folks kroppar skola himmelens foglom, och djuromen på jordene, till spis varda, och ingen skall drifva dem derifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Och jag skall uti Juda städer, och på gatorna i Jerusalem, borttaga glädjes och fröjds rop, och brudgummes och bruds röst; ty landet skall öde vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'På den samma tiden, säger Herren, skall man kasta Juda Konungars ben, Förstarnas ben, Presternas ben, Propheternas ben, borgarenas ben i Jerusalem, utu deras grifter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Och man skall förskingra dem under solene, månan, och alla himmelens här, hvilka de älskat, och dem tjent, och dem efterföljt, och sökt, och tillbedit hafva; de skola intet mer upphemtade och begrafne varda, utan vara träck på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Och alle de qvarlefde af desso onde folke, på ehvad rum de äro, dit jag dem bortdrifvit hafver, skola heldre vilja vara döde än lefvande, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Derföre säg till dem: Detta säger Herren: Hvar är någor, om han faller, den icke gerna står upp igen? Hvar är någor, som villo går, den icke gerna kommer uppå rätta vägen igen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Likväl vill ju detta folket i Jerusalem gå villo, utan återvändo; de stå så hårdt på den falska Gudstjenstene, att de intet vilja låta sig derifrån afvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Jag ser och hörer, att de lära icke rätt; ingen är den som ångrar sina ondsko, och säger: Hvad gör jag dock? De löpa alle sitt lopp, lika, som en grym häst i stridene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'En stork under himmelen vet sin tid; en turturdufva, trana och svala, märka sin tid, när de igenkomma skola; men mitt folk vill icke veta Herrans rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Huru kunnen I dock säga: Vi vete hvad rätt är, och hafvom Herrans lag för oss? Är det dock icke utan lögn, hvad de Skriftlärde gifva oss före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Derföre måste sådane lärare komma på skam, förskräckte och fångne varda; ty hvad godt kunna de lära, då de Herrans ord förkasta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Derföre skall jag gifva deras hustrur främmandom, och deras åker dem som dem förjaga skola; ty de fara efter girighet, den ene med den andra, både små och store; och både Prester och Propheter lära falska Gudstjenst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Och trösta mitt folk uti deras olycko, att de skola det ringa akta, och säga: Det står väl till, det står väl till; och det står dock intet väl till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Derföre skola de komma på skam, att de sådana styggelse bedrifva; ändock de vilja oskämde vara, och vilja intet skämma sig; derföre måste de falla hvar öfver annan; och när jag varder dem hemsökandes, skola de falla, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Jag vill så afhemta dem, säger Herren, att inga drufvor skola blifva qvara på vinträt, och ingen fikon på fikonaträt; ja, löfven skola ock affalla, och det jag dem gifvit hafver, det skall dem ifråtaget varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Hvar skole vi då bo? Ja, församler eder då, och låt oss draga in uti de fasta städer, och vänta der efter hjelp; ty Herren, vår Gud, varder oss hjelpandes med en bitter dryck att vi så synde emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Ja, förlåter eder deruppå, att det skall ingen nöd hafva, ändock intet godt för handene är; och att I skolen helade varda, ändock icke annat än ond sår för handene är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Man hörer allaredo ifrå Dan gnyn af deras hästar, och deras hingstar skria, så att hela landet bäfvar derföre; och de komma, och skola uppfräta landet med allt det deruti är, staden samt med alla de som deruti bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Ty si, jag skall sända ormar och basilisker ibland eder, de intet besvorne äro; de skola stinga eder, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Så skall jag hugsvala mig af mine ångest och hjertans sorg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Si, mins folks dotter skall ropa ifrå fjerran land: Vill nu Herren icke mer vara (Gud) i Zion? Eller skall det ingen Konung mer hafva? Ja, hvi hafva de så förtörnat mig med sin beläte, och främmande fåfänga Gudstjenst?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Skördetiden är framliden, sommaren är sin väg; och oss är ingen hjelp kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Mig ömkar svårliga, att mitt folk så förderfvadt är; jag grämer mig, och hafver ganska ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Är då nu ingen salva, i Gilead? Eller är der ingen läkare? Hvarföre är då mins folks dotter icke helad?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Ack! det jag vatten nog hade i mitt hufvud, och min ögon voro en tårekälla, att jag natt och dag begråta måtte de slagna i mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Ack! det jag ett herberge hade i öknene, så ville jag öfvergifva mitt folk, och draga ifrå dem; ty de äro allesammans horkarlar, och en arg hop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'De skjuta med sina tungor allesammans lögn, och ingen sanning, och fara allt med våld i landena, och gå ifrå den ena ondskone till den andra, och akta mig intet, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Hvar och en tage sig vara för sinom nästa, och tro icke heller sinom broder; ty en broder undertrycker den andra, och en vän förråder den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'En vän gäckar den andra, och tala icke ett sant ord; de vinnlägga sig derom, huru den ene skall bedraga den andra, och dem tycker illa vara, att de ännu icke kunna görat värre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Der är allestäds bedrägeri ibland dem, och för bedrägeris skull vilja de icke känna mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Derföre säger Herren Zebaoth alltså: Si, jag vill smälta och probera dem; ty hvad skall jag annars göra, medan mitt folk så ställer sig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Deras falska tungor äro mordskott; med sin mun tala de vänliga med sinom nästa; men i hjertat vakta de efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Skulle jag nu icke sådant hemsöka uppå dem, säger Herren, och skulle min själ icke hämnas öfver sådant folk, som detta är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Jag måste gråta och jämra mig på bergen, och beklaga mig vid de fäbodar i öknene; ty de äro så platt förhärjade, att der bor ingen mer, och man hörer der nu intet färop mer; både himmelens foglar och djuren äro alle borto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Och jag skall göra Jerusalem till en stenhop, och till en drakaboning; och skall ödelägga Juda städer, att der ingen inne bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Ack! att nu någor vis vore, och lade det uppå hjertat, och förkunnade hvad Herrans mun till honom säger: Hvarföre dock landet så förderfvadt och härjadt varder, likasom en ödemark, der ingen vistas?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Och Herren sade: Derföre, att de öfvergifva min lag, som jag dem föregifvit hafver, och lyda intet min ord, och lefva der ej heller efter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Utan följa sins hjertas tycko, och Baalim, såsom deras fäder dem lärt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Derföre säger Herren Zebaoth, Israels Gud: Si, jag skall spisa detta folket med malört, och gifva dem galla dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Jag skall förskingra dem ibland Hedningarna, hvilka hvarken de eller deras fäder känna, och skall sända svärd efter dem, tilldess det blifver ute med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Så säger Herren Zebaoth: Skaffer och beställer gråterskor, att de komma; och sänder efter de som det väl kunna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Och begråta oss med hast, att vår ögon måga rinna med tårar, och var ögnahvarf flyta med vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Att man må höra en klagogråt i Zion, nämliga alltså: Ack! huru äre vi så platt förstörde och till skam vordne? Vi måste rymma landet; ty våra boningar äro nederslagna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Så hörer nu, I qvinnor, Herrans ord, och edor öron fatte hans muns tal; lärer edra döttrar gråta, och den ena läre den andra klagogråt, nämliga alltså:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Döden är igenom vår fenster infallen, och uti vår palats kommen, till att dräpa barnen på gatone, och ynglingarna i gränderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Säg: Så säger Herren: Menniskors kroppar skola ligga såsom träck på markene, och såsom kärfvar efter skördomannen, de ingen upptager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Detta säger Herren: En vis berömme sig intet af sine vishet; an stark berömme sig intet af sin starkhet; en rik berömme sig intet af sin rikedom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Utan den som sig berömma vill, han berömme sig deraf, att han vet och känner mig, att jag är Herren, som gör barmhertighet, rätt och rättfärdighet på jordene; ty sådant behagar mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Si, den tid kommer, säger Herren, att jag hemsöka skall alla de omskorna med de oomskorna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Nämliga Egypten, Juda, Edom, Ammons barn, Moab, och alla de som bo uti de rum i öknene; ty alle Hedningar hafva oomskoren förhud; men hela Israels hus hafver oomskoret hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Hörer hvad Herren säger till eder, I af Israels hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Detta säger Herren: I skolen icke lära Hedningarnas sätt, och skolen intet frukta eder för himmelens tecken, såsom Hedningarna frukta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Ty Hedningarnas gudar äro icke utan fåfängelighet; de hugga ett trä i skogenom, och mästaren gör det till med en yxa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Och pryder det med silf och guld, och fäster det vid, med naglar och hamrar, att det icke omkullfalla skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Sådant är nu intet annat, än öfverdragna stodar; de kunna intet tala; så måste man ock bära dem; ty de kunna intet gå. Derföre skolen I intet frukta eder för dem; förty de kunna hvarken hjelpa eller stjelpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Men dig, Herre, är ingen lik; du äst stor, och ditt Namn är stort, och du kan det bevisa med gerningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Ho skulle icke frukta dig, du Hedningarnas Konung? Dig skall man ju lyda; ty ibland alla Hedningarnas visa, och i all Konungarike, är ingen din like.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'De äro allesamman dårar och galne; ty ett trä måste ju vara en platt fåfäng Gudstjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Silfskifvor förer man till på hafvet; guld ifrån Uphas, af mästare och guldsmeder beredt; gult silke och purpur kläder man uppå dem, och äro alltsammans slöga, mäns verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Men Herren är en rätt Gud, en lefvandes Gud, en evig Konung; för hans vrede bäfvar jorden, och Hedningarna kunna icke fördraga hans trug.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Så säger nu alltså till dem: De gudar, som himmel och jord icke gjort hafva, förgånge af jorden, och under himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Men han hafver gjort jordena genom sina kraft, och verldenes krets beredt genom sina vishet; och utsträckt himmelen genom sitt förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Då han dundrar, så är mycket vatten under himmelen, och drager upp dimbona ifrå jordenes anda; han gör ljungelden i regnet, och låter vädret kommer ifrå hemlig rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Alla menniskor äro dårar med sine konst, och alle guldsmeder stå med skam med sin beläte; ty deras beläte äro bedrägeri, och hafva intet lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Det är alltsammans ett fåfängt och bedrägeligit verk; de måste förgås, då de hemsökte varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Men sådan är icke han, som Jacobs lott är; utan han är den som all ting skapat hafver, och Israel är hans arfvedel; han heter Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Tag din handel bort utu landena, du som bor i den fasta (staden).');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Ty så säger Herren: Si, jag skall i denna resone bortslunga landsens inbyggare, och så plåga dem, att de det känna skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Ack! min jämmer och hjertans sorg; men jag tänker, att det är min plåga; jag måste lida henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Mitt tjäll är förstördt, och all min tåg äro sönder; min barn äro borto, och icke mer för handene; ingen upprättar min hyddo igen, och mitt tjäll slår ingen upp igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Ty herdarna äro till dårar vordne, och fråga intet efter Herran; derföre kunna de ock intet rätt lära, utan förskingra hjorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Si, ett rykte kommer, och ett stort bäfvande af det landet norrut, att Juda städer skola ödeläggas, och till drakaboningar varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Jag vet, Herre, att menniskones väg står icke till henne; och det står i ingens mans magt, huru han vandra eller sin gång styra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Näps mig, Herre, dock med måttelighet, och icke uti dine grymhet; på det du icke skall platt göra mig till intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Men gjut dina vrede ut öfver Hedningarna som intet känna dig, och öfver de slägte som intet åkalla ditt Namn: ty de hafva uppfrätit och uppsvulgit Jacob; de hafva gjort en ända med honom, och hans boning förödt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Detta är det ord som till Jeremia skedde af Herranom, som sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Hörer detta förbunds ord, att I mågen säga dem till Juda och Jerusalems inbyggare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Och säg till dem: Så säger Herren Israels Gud: Förbannad vare den som icke lyder detta förbunds ord,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Som jag edra fäder böd på den dag jag dem utur Egypti land förde, utur jernugnen, och sade: Hörer mina röst, och görer som jag eder budit hafver; så skolen I vara mitt folk, och jag vill vara edar Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'På det jag må hålla den ed, som jag edra fäder svorit hafver till att gifva dem ett land, der mjölk och hannog uti flyter, såsom det i denna dag för ögon är. Jag svarade, och sade: Ja, Herre, det ske alltså.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Och Herren sade till mig: Predika alla dessa orden uti Juda städer, och uppå gatorna i Jerusalem, och säg: Hörer detta förbunds ord, och görer derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Ty jag hafver betygat edra fäder, ifrå den dagen jag dem utur Egypti land förde, intill denna dag, och betygade städse, och sade: Hörer mina röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Men de hörde intet, och böjde ej heller sin öron härtill, utan hvar och en gick efter sins onda hjertas tycko; derföre vill jag ock öfver dem gå låta, all detta förbunds ord, det jag dem böd att de göra skulle, och de dock derefter icke gjort hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Herren sade till mig: Jag vet väl, huru de i Juda och Jerusalem gadda sig tillhopa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'De vända sig till sina förfäders synder, hvilke min ord ej heller höra ville, utan följde också andra gudar efter, och tjente dem; alltså hafver Israel hus och Juda hus nu (allstädes) brutit mitt förbund, det jag med deras fäder gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Derföre, si, säger Herren: Jag vill låta en olycko gå öfver dem, den de icke undkomma skola; och när de ropa till mig, så vill jag intet höra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Så låt då Juda städer och Jerusalems inbyggare gå bort, och ropa till de gudar, hvilkom de rökt hafva; men de skola intet hjelpa dem i deras nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Ty så många städer, så många gudar hafver du, Juda, och så många gator som i Jerusalem äro, så mång blygdealtare hafven I uppsatt, till att röka för Baal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Så bed nu du intet för detta folk, och haf ingen åkallan eller bön för dem; ty jag vill intet höra dem, när de ropa till mig i sine nöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Hvad hafva mine vänner till att skaffa i mitt hus? De bedrifva alla falskhet, och mena det heliga köttet skall taga det bort af dem; och när de illa göra, så äro de glade deröfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Herren kallade dig ett grönt, skönt, fruktsamt oljoträ; men nu hafver han med ett stort mordskri, upptändt en eld deromkring, så att dess qvistar måste förderfvade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Ty Herren Zebaoth, som dig planterat hafver, hafver lofvat dig ondt, för Israels hus, och Juda hus ondskos skull, den de bedrifva, så att de förtörna mig, i det de röka för Baal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Herren hafver mig det uppenbarat, så att jag det vet; och viste mig hvad de hafva för händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Nämliga att de vilja slagta mig, likasom ett armt får; ty jag visste icke, att de emot mig rådslagit hade, och sagt: Låt oss förderfva trät med sine frukt, och utrota honom utu de lefvandes land, att på hans namn skall aldrig mer tänkt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Men du, Herre Zebaoth, du rättvise domare, du som bepröfvar njurar och hjerta, låt mig se dina hämnd öfver dem; ty jag hafver befallt dig mina sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Derföre säger Herren alltså emot dem i Anathoth, hvilke efter ditt lif stå, och säga: Spå oss intet i Herrans Namn, om du annars icke dö vill af våra händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Derföre säger Herren Zebaoth alltså: Si, jag vill hemsöka dem; deras unge män skola med svärd dräpne varda, och deras söner och döttrar af hunger dö;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Så att intet af dem skall qvart blifva; ty jag skall låta en olycko gå öfver dem i Anathoth, på det året då de skola hemsökte varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Herre, om jag än med dig ville till rätta gå, så behåller du dock rätten; likväl måste jag tala med dig om rätten: Hvi går dem ogudaktigom så väl, och de föraktare hafva allahanda nog?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Du planterar dem, att de rota sig, och växa, och bära frukt; du låter dem mycket tala om dig, och du näpser dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Men mig, Herre, känner du, och ser mig, och pröfvar mitt hjerta för dig; men dem låter du gå fri, likasom får, att de skola slagtade varda; och skonar dem, på det de skola dräpne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Huru länge skall dock landet stå så jämmerliga, och gräset på markene allestäds borttorkas för inbyggarenas ondskos skull, att både djur och foglar der intet mer äro? Ty de säga: Ja, han vet mycket huru oss gå skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Om de göra dig plats, som till fot gå, huru vill dig gå, då du med resenärer löpa skall? Och om du söker efter säkerhet uti de lande der frid är, hvad vill då med dig varda vid den högmodiga Jordanen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Ty dine bröder, och dins faders hus förakta dig ock, och ropa Jadut öfver dig; derföre tro du dem intet, om de än tala vänliga med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Derföre hafver jag måst öfvergifva mitt hus, och fly mitt arf, och gifva mina älskeliga själ uti fiendahand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mitt arf är mig vordet såsom ett lejon i skogenom, och ryter emot mig; derföre är jag thy harmse vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Mitt arf är såsom en spräklot fogel, om hvilken foglarna församla sig; upp, och församler eder, all djur på markene; kommer och äter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Månge herdar hafva förderfvat min vingård, och förtrampat min åker; de hafva gjort min sköna åker till en öken; de hafva gjort honom öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Jag ser allaredo, huru jämmerliga han förödd är; ja, hela landet är öde; men ingen vill läggat uppå hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Ty de förderfvare komma öfver alla högar i öknene, och Herrans frätande svärd ifrå den ena landsens ända intill den andra; och intet kött skall frid hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'De så hvete, men tistel skola de uppskära; de göra sig omak nog, men de skola intet nyttjat; de skola icke glädjas af sinom årsväxt, för Herrans grymma vredes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Detta säger Herren emot alla mina onda grannar, som antasta den arfvedel som jag mino folke Israel utskift hafver; si, jag skall rycka dem utu deras land, och taga Juda hus midt ut ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Och när jag hafver uttagit dem, skall jag åter förbarma mig öfver dem, och skall låta hvar och en komma till sin arfvedel, och till sitt land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Och det skall ske, om de lära af mitt folk, att de svärja vid mitt Namn: Så visst som Herren lefver; lika som de tillförene hafva lärt mitt folk svärja vid Baal, så skola de uppbyggas ibland mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Men om de icke höra vilja, så skall jag det folket utrycka, och förgöra det, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Detta, säger Herren till mig: Gack bort, och köp dig en linnen gjording, och gjorda dina länder dermed, och gör honom icke våtan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Och jag köpte en gjording, efter Herrans befallning, och band honom kringom mina länder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Så skedde Herrans ord annan gången till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Tag den gjordingen, som du köpt, och om dina länder bundit hafver, och statt upp, och gack bort till Phrath, och göm honom der uti ena stenklyfto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Jag gick åstad, och gömde honom invid Phrath, som Herren mig budit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Men en lång tid derefter sade Herren till mig: Statt upp, och gack bort till Phrath, och tag den gjordingen igen, som jag bad dig der bortgömma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Jag gick bort till Phrath, och grof honom upp, och tog gjordingen af det rum, der jag honom lagt hade; och si, gjordingen var förderfvad, så att han intet mer dogde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Då skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Detta säger Herren: Lika så skall jag förderfva den stora högfärden i Juda och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Det onda folket, som min ord icke höra vilja, utan gå efter sin hjertas tycko, och följa andra gudar, till att tjena och tillbedja dem, de skola varda lika som gjordingen, den intet mer doger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Ty lika som en man binder gjordingen om sina länder, alltså hafver jag, säger Herren, omgjordat mig hela Israels hus, och hela Juda hus, att de skulle vara mitt folk, till ett namn, lof och äro; men de ville icke höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Så säg dem nu detta ordet: Detta säger Herren Israels Gud: Alle läglar skola med vin fyllde varda; så skola de säga till dig: Ho vet det icke, att man skall fylla läglarna med vin?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Så säg till dem: Detta säger Herren: Si, jag skall fylla alla de som i detta land bo; Konungarna, som på Davids stol sitta, Presterna och Propheterna, och alla Jerusalems inbyggare, så att de druckne varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Och skall förströ dem, den ena med den andra, fäderna samt med barnen, säger Herren; och skall hvarken skona eller öfverse, eller barmhertig vara öfver deras förderf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Så hörer nu, och märker till, och trotser icke; ty Herren hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Gifver Herranom edrom Gudi ärona, förr än det mörkt varder, och förr än edre fötter stöta sig på de mörka berg; så att I vänten efter ljuset, och han skall dock görat allt till mörker och skugga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Men viljen I detta icke höra, så måste dock min själ hemliga gråta öfver sådana stolthet; mina ögon måste med tårar flyta, att Herrans hjord fången varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Säg Konungenom och Drottningene: Sätter eder neder; ty härlighetenes krona är eder af hufvudet fallen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'De städer söderut äro tillslutne, och ingen är som dem upplåter; hela Juda är allsamman bortförd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Upplyfter edor ögon, och ser huru de nordanefter komma; hvar är nu hjorden, som dig befallen var, din härliga hjord?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Hvad vill du säga, då han dig så hemsökandes varder? du hafver så vant dem emot dig, att de Förstar och höfdingar vara vilja; hvad gäller, dig varder ångest uppåkommandes, lika som ene qvinno i barnsnöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Och om du i dino hjerta säga ville: Hvarföre vederfars mig dock sådant? för dina många missgerningars skull är din blygd upptäckt, och din ben blottad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Kan ock en Ethioper förvandla sina hud, eller en parde sina fläckar? Så kunnen I ock något godt göra, efter I ondt vane ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Derföre vill jag; förskingra dem likasom strå, det för vädrena uti öknene drifvet varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Det skall vara din lön och din del, som jag dig tillmätit hafver, säger Herren; derföre, att du mig förgätit hafver, och förtröste uppå lögn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Så vill jag ock högt upptäcka dina blygd, att man dina skam väl se skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Förty jag hafver sett ditt horeri, dina kättjo, ditt oförskämda boleri: ja, din styggelse både på högom och på åkrom; ve dig, Jerusalem; när vill du dock någon tid renad varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Detta är det ord, som Herren till Jeremia sade, om den dyra tiden:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Juda ligger jämmerliga, hans portar stå i en ömkelig måtto; det står klageliga till i landena, och i Jerusalem är ett stort rop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'De store sända de små efter vatten; men då de komma till brunnen, så finna de intet vatten, och bära sina käril tom hem igen; de gå sorgse och bedröfvade, och omsvepa sin hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Derföre, att jorden refnar, efter intet regnar på jordena; åkermännerna, gå sorgse, och omsvepa sin hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Ty ock hinderna, som på markena kalfva, öfvergifva sina kalfvar, efter intet gräs växer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Vildåsnarna stå på bergen, och lukta efter vädret, lika som drakar, och försmäkta, efter ingen ört växer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Ack! Herre, våra missgerningar hafva det ju förtjent; men hjelp dock för ditt Namns skull; ty vår ohörighet är stor, der vi emot dig med syndat hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Du äst Israels tröst, och hans nödhjelpare; hvi skickar du dig, lika som du vore främmande i landena, och såsom en gäst, den icke mer än ena natt derinne ligger?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Hvi hafver du dig såsom en hjelte, som förtviflad är; och som en kämpe, den intet hjelpa kan? Du äst ju dock ibland oss, Herre, och vi nämnes efter ditt Namn; öfvergif oss icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Så säger Herren om detta folket: De löpa gerna hit och dit, och blifva icke gerna hemma; derföre hafver Herren ingen vilja till dem; utan han tänker nu uppå deras missgerningar, och vill hemsöka deras synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Och Herren sade till mig: Du skall intet bedja för detta folk om nåde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Ty om de än fastade, så vill jag dock intet höra deras bön; och om de än hade bränneoffer och spisoffer fram, så behaga de mig dock intet; utan jag vill göra en ända uppå dem med svärd, hunger och pestilentie.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Då sade jag: Ack Herre Herre! Si, Propheterna säga dem: I skolen intet svärd se, och ingen dyr tid få när eder; men jag skall gifva eder en god frid i detta rummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Och Herren sade till mig: Propheterna, spå lögn i mitt Namn; jag hafver intet sändt dem, och intet befallt dem, och intet talat med dem; de predika eder falska syner, spådom, afguderi, och sins hjertans bedrägeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Derföre säger Herren om de Propheter, som i mitt Namn prophetera, ändock jag dem intet sändt hafver, och de likväl predika, att intet svärd eller dyr tid skall komma i detta land: Sådana Propheter skola dö genom svärd och hunger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Och folket, hvilko de prophetera, skola af svärd och hunger ligga här och der på gatomen i Jerusalem, att ingen skall begrafva dem; sammalunda ock deras hustrur, söner och döttrar; och jag skall gjuta deras ondsko uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Och du skall säga till dem detta ordet: Min ögon flyta med tårar dag och natt, och vända intet åter; ty jungfrun, mins folks dotter, är grufveliga plågad, och jämmerliga slagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Går jag ut på markena, si, så ligga der de slagne med svärd; kommer jag in uti staden, så ligga der de försmäktade af hunger; ty ock Propheterna och Presterna måste bortdraga uti ett land, det de intet känna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Hafver du då förkastat Juda? Eller hafver din själ en vämjelse till Zion? Hvi hafver du så slagit oss, att oss ingen hela kan? Vi hoppades, att det skulle frid varda, men här kommer intet godt; vi hoppades, att vi skulle helade varda, och si, här är nu mera vedermöda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Herre, vi kännom vårt ogudaktiga väsende, och våra fäders missgerningar; ty vi hafve syndat emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Men, för ditt Namns skull, låt oss icke skämde varda; låt dine härlighets säte icke begabbadt varda; kom dock ihåg, och låt icke ditt förbund med oss återvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Det är dock ingen ibland Hedningarnas afgudar, som regn gifva kan; himmelen kan ock icke regna. Du äst ju Herren vår Gud, uppå hvilken vi hoppas; ty du kan alltsammans detta göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Och Herren sade till mig: Det än Mose och Samuel före mig stode, så hafver jag dock intet hjerta till detta folket, drif dem bort ifrå mig, och låt dem fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Och om de säga, till dig: Hvart skole vi? så säg nu till dem: Detta säger Herren: Hvem döden drabbar, uppå honom drabbe han; hvem svärdet drabbar, uppå honom drabbe det; hvem hungren drabbar, uppå honom drabbe han; hvem fängelse drabbar, uppå honom drabbe det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Ty jag vill hemsöka dem med fyrahanda plågor, säger Herren; med svärd, att de skola slagne varda; med hundar, som dem bortsläpa skola; med himmelens foglar, och med djuren på jordene, att de skola uppätne varda, och förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Och jag skall låta drifva dem hit och dit, i all rike på jordene, för Manasse skull, Jehiskia sons, Juda Konungs, för det han i Jerusalem bedrifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Ho vill då förbarma sig öfver dig, Jerusalem? Ho vill då medlidande med dig hafva? Ho skall då gå bort och förvärfva dig frid?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Du hafver öfvergifvit mig, säger Herren, och äst affällig vorden ifrå mig; derföre hafver jag uträckt mina hand emot dig, att jag skall förderfva dig; mig ledes vid att förbarma mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Jag skall kasta dem med en kastoskofvel bort utu landet; och mitt folk, som sig icke ifrå sitt väsende omvända vilja, dem skall jag allasamman faderlösa göra och förderfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Mig skola ibland dem flera enkor varda, än sanden i hafvet är; jag skall låta komma öfver de unga mäns moder en uppenbara förderfvare; och dermed låta öfverfalla staden hasteliga och oförseendes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Så att den som sju barn hafver, hon skall elända varda, och af hjertat sucka; ty deras sol skall bittida på dagenom nedergå, att deras berömmelse och glädje skall en ända hafva, och de som qvare blifva, skall jag gifva uti svärd för deras fiendar, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Ack! min moder, att du mig födt hafver, öfver hvilken hvar man Jadut ropar i hela landena; hafver jag dock uppå ocker hvarken lånt eller tagit, likväl bannar mig hvar man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Herren sade: Nu väl, jag skall somliga af eder igen behålla; ty det skall åter väl gå, och jag skall komma eder till hjelp i nöd och ångest, ibland fienderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Menar du, att icke någorstäds något jern är, som kan sönderslå det jern och koppar nordanefter?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Men jag skall tillförene gifva edart gods och ägodelar till sköfvels, så att I skolen få der intet före, och det för alla edra synders skull, som I uti alla edra gränsor bedrifvit hafven;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Och skall låta eder komma bort till edra fiendar, uti ett land det I intet kännen; ty elden i mine vrede är öfver eder uppågången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Ack! Herre, du vetst det, kom oss ihåg, och låt dig om oss vårda, och hämnas oss uppå våra förföljare. Anamma oss, och fördröj icke dina vrede öfver dem; ty du vetst, att vi för dina skull försmädde varde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Emedan håller oss ditt ord uppe, då vi det få; och det samma ditt ord är vår hjertas fröjd och tröst; ty vi äre ju nämnde efter ditt Namn, Herre Gud Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Vi gifve oss icke i sällskap till de begabbare, eller fröjdom oss med dem; utan blifve ensamme, för dine hands fruktans skull; tv du vredgas svårliga öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Hvi varar då vår vedermöda så länge, och vår sår äro så ganska ond, att dem ingen hela kan? Du äst oss vorden lika som en källa, den intet mer rinna vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Derföre säger Herren alltså: Om du håller dig intill mig, så vill jag hålla mig till dig, och du skall blifva min Predikare; och om du lärer de fromma skilja sig ifrå de onda, så, skall du vara min lärare, och förr än du skulle falla intill dem, skola de falla till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Ty jag hafver gjort dig till en fast kopparmur emot detta folket; om de emot dig strida, så skola de dock intet förmå emot dig; ty jag är när dig, till att hjelpa dig och frälsa dig, säger Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Och skall frälsa dig utu de högmodigas hand, och förlossa dig utu de tyranners hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Du skall ingen hustru taga dig, eller föda några söner eller döttrar i desso rumme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Ty så säger Herren om de söner och döttrar, som i detta rummet födde varda, och om mödrarna som dem föda, och om deras fäder som dem föda i desso lande:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'De skola dö af krankheter, och hvarken begråtne eller begrafne varda; utan skola till träck varda på markene; dertill skola de ock genom svärd och hunger förgås, och deras kroppar skola foglom under himmelen och djurom på markene till spis varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Ty så säger Herren: Du skall icke gå till begängelse, och skall ej heller någorstäds gå till begråtning, eller medlidande öfver dem hafva; ty jag hafver tagit min frid ifrå desso folke, säger Herren, samt med mine nåd och barmhertighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Att både store och små skola dö i desso lande, och intet begrafne, eller begråtne varda; och ingen skall rifva sig, eller raka sitt hår öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Och man skall ej heller utskifta bröd i den begråtning, till att hugsvala dem öfver liket; och ej heller gifva dem dricka af tröstebägarenom öfver fader och moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Derföre skall du intet gå in uti något dryckohus, till att sitta när dem; eller till att äta, eller till att dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Ty så säger Herren Zebaoth, Israels Gud: Si, jag skall borttaga af desso rummena för edor ögon, och medan I än lefven, fröjds och glädjes röst, brudgummes och bruds röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Och när du allt detta desso folkena sagt hafver, och de säga till dig: Hvi talar Herren öfver oss alla denna stora olyckona? Hvilken är den missgerning eller synd, der vi med emot Herran vår Gud syndat hafve?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Så skall du säga dem: Derföre att edra fäder, säger Herren, hafva öfvergifvit mig, och följt andra gudar, tjent dem, och tillbedit dem; men mig hafva de förlåtit, och intet hållit min lag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Och I ännu värre gören, än edre fäder; ty si, hvar och en lefver efter sins ondas hjertas tycko, på, det han icke skall lyda mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Derföre skall jag drifva eder utu detta landet, in uti ett land der hvarken I eller edre fäder af veten; der skolen I tjena andra gudar, dag och natt; och der skall jag ingen nåde bevisa eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Derföre, si, den tiden kommer, säger Herren, att man intet mer skall säga: Så sant som Herren lefver, som Israels barn utur Egypti land fört hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Utan, så sant som Herren lefver, som Israels barn fört hafver utu nordlanden, och utur all land, dit han dem utdrifvit hafver; ty jag skall låta dem igen komma uti det land, som jag deras fäder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Si, jag skall utsända många fiskare, säger Herren, de skola fiska dem; och derefter skall jag utsända många jägare, de skola fånga dem på all berg, på alla högar, och i alla stenklyftor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Ty min ögon se uppå alla deras vägar, att de icke skola kunna gömma sig för mig; och deras missgerning är för min ögon fördold.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Men tillförene skall jag dubbelt betala deras missgerning och synd; derföre, att de hafva orenat mitt land med deras afguderis lik, och gjort mitt land fullt med sin styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Herre, du äst min starkhet och kraft, och min tillflykt uti nödene. Hedningarna skola komma till dig af verldenes ändar, och säga: Våre fäder hafva haft falska och fåfänga gudar, som intet hjelpa kunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Huru kan en menniska göra dem till gudar, som inge gudar äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Derföre si, nu vill jag lära dem, och göra dem mina hand och mitt välde kunnigt, att de skola förnimma att jag heter Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Juda synd är med jernstyl och med skarp diamant skrifven, och uti deras hjertas taflor grafven, och uppå hornen af deras altare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Att deras barn skola ihågkomma de samma altare och lundar, vid de gröna trä, på de höga berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Men jag skall gifva dina höjder till sköfvels, både på berg och slätter, samt med dina håfvor, och alla dina ägodelar, för syndernas skull, i alla dina gränsor bedrefna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Och du skall varda utdrifven utu ditt arf, som jag dig gifvit hafver, och jag skall göra dig till dina fiendars träl, uti ett land det du intet känner; ty I hafven upptändt mine vredes eld, den evinnerliga brinna skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Detta säger Herren: Förbannad är den man som förlåter sig uppå mennisko, och sätter kött sig till arm, och viker med sitt hjerta ifrå Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Han skall varda såsom ljung i öknene, och skall intet få se den tillkommande tröstena; utan skall blifva uti det torra i öknene, uti en ofruktsam och öde mark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Men välsignad är den man, som förlåter sig uppå Herran, och Herren hans tröst är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Han är lika som ett trä, det vid vatten planteradt och vid en bäck berotadt är; ty om än en hette kommer, så fruktar det sig dock intet, utan dess löf blifva grön; och sörjer intet, när ett torrt år kommer, men det bär frukt utan upphåll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Ett argt, illfundigt ting öfver all ting är hjertat; ho kan utransakat?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Jag Herren kan utransaka hjertat, och pröfva njurarna, och gifver hvarjom och enom efter hans vägar, och efter hans gerningars frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Ty lika som en fogel, som lägger sig uppå ägg, och utkläcker dem icke, alltså är den som orätt gods församlar; ty han måste derifrå, då han det aldraminst tänker; och måste dock på sistone hafva spott dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Men vår helgedoms rum, nämliga Guds härlighets säte, är alltid fast blifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Ty, Herre, du äst Israels hopp; alle de som dig förlåta, måste till skam varda, och de affällige måste på jordene skrefne varda; ty de öfvergifva Herran, som är en lefvandes vattens källa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Hela du mig, Herre, så varder jag hel; hjelp du mig, så är mig hulpet; ty du äst min berömmelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Si, de säga till mig: Hvar är då Herrans ord? Käre, låt kommat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Men jag hafver fördenskull icke flytt ifrå dig, min herde; så hafver jag ock intet begärat menniskors ros, det vetst du; hvad jag predikat hafver, det är rätt inför dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Var icke du mig förskräckelig, min tröst i nödene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Låt dem till skam komma, som mig förfölja, och icke mig; låt dem förskräckas, och icke mig; låt olyckones dag öfver dem gå, och sönderslå dem dubbelt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Så säger Herren till mig: Gack, och statt i folkens port, der Juda Konungar ut och in gå, och i alla portar i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Och säg till dem: Hörer Herrans ord, I Juda Konungar, och hele Juda, och alle Jerusalems inbyggare, som igenom denna porten ingån.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Detta säger Herren: Vakter eder, och bärer ingen bördo om Sabbathsdagen, genom portarna, in i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Och förer ingen klef på Sabbathsdagen utur edor hus, och görer intet arbete; utan helger Sabbathsdagen, såsom jag edra fäder budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Men de höra intet, och böja intet sin öron, utan blifva halsstyfve, på det de ju icke skola höra, eller ock låta säga sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Om I hören mig, säger Herren, så att I ingen bördo bären om Sabbathsdagen genom denna stadsporten, utan helgen honom, och gören intet arbete på dem dagenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Så skola ock igenom denna stadsporten ut och in gå Konungar och Förstar, som på Davids stol sitta, och rida, och fara både med vagn och hästar, de och deras Förstar, samt med alla de som i Juda och Jerusalem bo; och denna staden skall evinnerliga besutten varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Och skola komma utaf Juda städer, och de omkring Jerusalem ligga, och utaf BenJamins land, af dalom och bergom, och sunnanefter, de der framföra skola bränneoffer, offer, spisoffer, och tackoffer, till Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Men om I icke hören mig, så att I helgen Sabbathsdagen, och ingen bördo bären in genom de portar i Jerusalem på Sabbathsdagenom, skall jag upptända en eld i dess portar, den husen i Jerusalem förtära skall, och intet utsläckt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Detta är det ord, som skedde af Herranom till Jeremia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Statt upp, och gack ned uti krukomakarens hus; der vill jag låta dig höra min ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Och jag gick ned i krukomakarens hus, och si, han arbetade på skifvone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Och krukan, som han utaf lerena gjorde, gick honom sönder i händerna; då gjorde han åter ena andra kruko, såsom honom täcktes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Då skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Kan jag ock icke skicka mig, såsom denne krukomakaren, med eder af Israels huse, säger Herren? Si, såsom leret är i krukomakarens hand, så ären ock I af Israels hus i mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Hasteliga talar jag emot ett folk och rike, att jag det utrota, förhärja, och förderfva vill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Men om det omvänder sig ifrå sine ondsko, den jag emot talar, så skall jag ock låta mig ångra det onda, som jag tänkte göra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Och hasteliga talar jag om ett folk och rike, att jag det uppbygga och plantera vill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Men gör det illa för min ögon, så att det icke hörer mina röst, så skall jag ock låta mig ångra det goda, som jag dem lofvat hafver, att jag dem göra skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Så säg nu till dem i Juda, och till Jerusalems inbyggare: Detta säger Herren: Si, jag bereder eder ena olycko, och tänker något emot eder; derföre vände sig hvar och en ifrå sitt onda väsende, och bättrer edart väsende och anslag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Men de sade: Der varder intet utaf; vi vilje vandra efter våra tankar, och göra hvar och en efter sins onda hjertas tycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Derföre säger Herren: Fråger dock ibland Hedningarna: Ho hafver någon tid sådant hört, att jungfrun Israel så ganska grufveliga ting gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Blifver dock snön längre på stenomen i markene, då det snögar ned af Libanon; och regnvattnet förlöper icke så snart,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Som mitt folk mig förgäter. De röka gudom, och komma förargelse åstad, utan återvändo, på sinom stigom, och gånga på otrampadom vägom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'På det deras land skall till öde varda, dem till evig skam, så att den der framom går, skall sig förundra, och rista hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Ty jag skall, genom ett östanväder, förskingra dem för deras fiendar; jag skall visa dem ryggen, och icke anletet, då de förderfvas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Men de sade: Kommer, och låter oss gå till råds emot Jeremia; ty Presterna kunna icke fara ville i lagen, och de gamlas råd icke fela, och Propheterna kunna icke lära orätt. Kommer, och låter oss slå honom ihjäl med tungone, och passa intet uppå hvad han säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Herre, akta uppå mig, och hör mina motståndares röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Är det rätt, att man vedergäller ondt för godt? Ty de hafva grafvit mine själ ena grop. Kom dock ihåg, huru jag för dig stått hafver, så att jag talade deras bästa, och vände dina grymhet ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Så straffa nu deras barn med hunger, och låt dem i svärd falla, att deras hustrur och enkor utan barn blifva, och deras män ihjälslagne, och deras unga män i strid genom svärd dräpne varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Att ett rop utaf deras husom må hördt varda, huru du med hast hafver låtit krigsfolk komma öfver dem; ty de hafva grafvit ena grop till att fånga mig, och lagt ena snaro för mina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Och efter du, Herre, vetst all deras anslag emot mig, att de vilja dräpa mig; så förlåt dem icke deras missgerning, och låt deras synder icke utstrukna varda för dig; låt dem störta inför dig, och handla med dem efter dina vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Så sade Herren: Gack bort, och köp dig ena lerkruko af krukomakarenom, samt med några af de äldsta i folket, och de äldsta för Presterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Och gack bort uti Hinnoms sons dal, som ligger för tegelportenom, och predika der de ord, som jag säger dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Och säg: Hörer Herrans ord, I Juda Konungar, och Jerusalems inbyggare: Så säger Herren Zebaoth, Israels Gud: Si, jag vill låta en sådana olycko komma öfver detta rummet, att den det hörer, honom skall gälla i öronen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Derföre, att de hafva öfvergifvit mig, och gifvit detta rummet enom främmande gud, och rökt deruti androm gudom, hvilka hvarken de, eller deras fäder, eller Juda Konungar känt hafva, och hafva gjort detta rummet fullt med oskyldigt blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Ty de hafva byggt höjder till Baal, till att uppbränna sin barn Baal, till bränneoffer, hvilket jag dem hvarken budit eller derom talat hafver, och ej heller någon tid uti mitt hjerta kommet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Derföre si, den tid varder kommandes, säger Herren, att man detta rummet inte mer kalla skall Thopheth, eller Hinnoms sons dal, utan dråpodal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Ty jag skall förstöra Juda och Jerusalems Gudstjenst i desso rummena, och skall låta dem falla genom svärd för deras fiendar, och deras hand, som efter deras lif stå; och skall gifva deras kroppar foglarna under himmelen, och djuren på markene till mat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Och skall göra denna staden öde, och till spott, så att alle de, som gå der fram, skola förundra uppå alla hans plågor, och bespotta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Jag skall låta dem äta sina söners och döttrars kött, och en skall äta dens andras kött, uti den nöd och ångest, dermed deras fiender, och de, som efter deras lif stå, dem tränga skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Och du skall sönderslå krukona för de män, som med dig gångne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Och säg till dem: Detta säger Herren Zebaoth: Rätt så som man sönderslår en krukomakares käril, så att det icke kan igen helt varda, så skall jag ock sönderkrossa detta folk och denna stad, och skola i Thopheth begrafne varda, derföre, att der skall eljest intet rum vara till begrafning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Så vill jag göra med desso rummena, och dess inbyggare, säger Herren, att denne staden skall varda lika som Thopheth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Dertill skola de hus i Jerusalem, och Juda Konungars hus, ju så oren varda, som det rummet Thopheth, ja, all hus, der de på, taken allom himmelens här rökt hafva, och androm gudom drickoffer offrat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Och då Jeremia, igenkom ifrå Thopheth, dit Herren honom sändt hade, till att prophetera, gick han in i gården åt Herrans hus, och sade till allt folket:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Detta säger Herren Zebaoth, Israels Gud: Si, jag skall låta komma öfver denna staden, och öfver alla hans städer, all den olycko, som jag emot dem talat hafver; derföre, att de äro halsstyfve, och min ord intet höra vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Men då Pashur, Immers son, Prestens, den för en öfversta i Herrans hus satt var, hörde Jeremia prophetera dessa orden,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Slog han Propheten Jeremia, och kastade honom i fängelse, i den öfra portenom BenJamins, hvilken på Herrans huse är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Och då morgonen kom, tog Pashur Jeremia åter utu fängelset. Då sade Jeremia till honom: Herren kallar dig icke Pashur, utan Magor allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Ty så säger Herren: Si, jag skall gifva dig, samt med alla dina vänner, uti en fruktan, och de skola falla genom dina fiendars svärd; det skall du se med din ögon; och jag skall öfvergifva hela Juda uti Konungens hand af Babel; han skall föra dem bort till Babel, och dräpa dem med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Och jag skall gifva allt godset i denna staden, samt med allt hans arbete och alla klenodier, alla Juda Konungars håfvor, uti deras fiendars hand, så att de skola dem skinna, borttaga och till Babel föra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Och du, Pashur, skall med allt ditt husfolk gå fången, och till Babel komma; der skall du dö, och begrafven varda, samt med alla dina vänner, hvilkom du lögn predikar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Herre, du hafver dragit mig, och jag hafver mig draga låtit; du hafver varit mig för stark, och hafver vunnit; men jag är deröfver kommen till spott dagliga, och hvar man gör gäck af mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Ty sedan jag talat, ropat och predikat hafver om den plågan och förderfvet, är mig Herrans ord vordet till hån och spott dagliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Då föll mig i sinnet: Jag vill intet mer tänka uppå honom, och intet mer predika i hans Namn; men i mino hjerta och minom benom vardt lika som en brinnande eld insluten, så att jag icke förmådde det lida, och var hardt när förgången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Ty jag hörer, huru månge banna mig, och jag måste allestäds vara rädder. Anklager, vi vilje anklaga honom, säga alle mine vänner och stallbröder; om vi kunne blifva honom öfvermägtige, och komma åt honom, och hämnas öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Men Herren är med mig, såsom en stark hjelte; derföre skola mine förföljare falla, och icke vinna, utan skola på stor skam komma, derföre att de så dårliga handla; evig skall den skammen vara, och skall icke förgäten varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Och nu, Herre Zebaoth, du som pröfvar de rättfärdiga, och ser njurar och hjerta, låt mig se dina hämnd öfver dem; ty jag hafver befallt dig min sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Sjunger Herranom, lofver Herran, som hjelper dens fattigas lif utu de ondas händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Förbannad vare den dag, der jag uti född var; den dagen vare osignad, på hvilkom min moder mig födt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Förbannad vare den som minom fader god tidende bar, och sade: Du hafver fått en ungan son, på det han skulle glädja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Den mannen vare såsom de städer som Herren omvände, och honom det intet ångrade; han höre ett skriande om morgonen, och om middagen ett jämrande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Att du dock icke hafver dräpit mig i moderlifvena; att min moder måtte varit min graf, och hennes lif måtte evinnerliga hafvandes varit!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Hvi är jag dock utu moderlifvena framkommen, att jag sådana jämmer och hjertans sorg se måste, och slita mina dagar med skam?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Detta är det ord, som af Herranom skedde till Jeremia, då Konung Zedekia sände till honom Pashur, Malchia son, och Zephanja, Maaseja Prestens son, och lät säga honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Fråga dock Herran för oss; ty NebucadNezar, Konungen i Babel, örligar emot oss; att Herren dock ville göra med oss efter all sin under, på det han må draga ifrån oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Jeremia sade till dem: Detta säger till Zedekia:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Så säger Herren Israels Gud: Si, jag skall vända de vapen tillbaka, som I uti edra händer hafven, der I med striden emot Konungen i Babel, och emot de Chaldeer, som eder omkring murarna belagt hafva; och skall församla dem i en hop midt i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Och jag skall strida emot eder med uträckto hand, med starkom arm, med stor vrede, grymhet och obarmhertighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Och skall slå inbyggarena i denna stadenom, både folk och fä, så att de skola dö i en stor pestilentie.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Och derefter, säger Herren, skall jag gifva Zedekia, Juda Konung, samt med hans tjenare, och folkena, som i denna stadenom af pestilentie, svärd och hunger qvarlefde äro, uti NebucadNezars händer, Konungens i Babel, och uti deras fiendars händer, och uti deras händer som efter deras lif stå, att han så skall slå dem med svärdsegg, att der ingen skonan, eller nåde, eller barmhertighet med skall vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Och säg desso folkena: Så säger Herren: Si, jag sätter eder före vägen till lifvet, och vägen till döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Hvilken som blifver i denna stadenom, han måste dö igenom svärd, hunger och pestilentie; men den som gifver sig ut till de Chaldeer, som eder belägga, han skall blifva lefvandes, och skall behålla sitt lif, likasom ett byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Ty jag hafver ställt mitt ansigte öfver denna staden till olycko, och till intet godt, säger Herren; han skall Konungenom i Babel öfvergifven varda, att han skall uppbränna honom med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Och hörer Herrans ord, I af Juda Konungs huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Du Davids hus, detta säger Herren: Håller domen om morgonen, och hjelper den beröfvada utu våldsverkarens hand, på det min grymhet icke skall utfara lika som en eld, och brinna så, att det ingen utsläcka kan, för edart onda väsendes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Si, säger Herren: Jag säger dig, du som bor i dalenom, på bergen och på jemna markene, och säger: Ho vill öfverfalla oss, eller komma in uti vårt fäste?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Jag vill hemsöka eder, säger Herren, efter edra gerningars frukt; jag skall upptända en eld uti edar skog, han skall förtära allt det deromkring är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Detta säger Herren: Gack ned i Juda Konungs hus, och tala der detta ordet:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Och säg: Hör Herrans ord, du Juda Konung, som på Davids stol sitter, både du, och dine tjenare, och ditt folk, som igenom dessa portarna ingån;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Så säger Herren: Håller rätt och rättviso, Och hjelper den beröfvada utu våldsverkarens hand; och oförrätter icke främlingen, den faderlösa och enkona, och görer ingom öfvervåld, och utgjuter icke oskyldigt; blod i detta rummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Om I detta gören, så skola Konungarna, som på Davids stol sitta, infara genom desses hus portar, både till vagn och till häst, samt med deras tjenare och folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Men om I detta, icke hören, så hafver jag svorit vid mig sjelf, säger Herren: Detta hus skall förstördt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Ty så säger Herren om Juda Konungs hus: Gilead, du äst mig hufvudet i Libanon; hvad gäller, jag skall göra dig till öde, och städerna utan inbyggare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Ty jag hafver beställt förderfvare öfver dig, hvar och en med sin vapen; de skola omkullhugga, din utvalda cedreträ, och kasta dem i elden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Så skola månge Hedningar gå framom denna staden, och säga emellan sig: Hvi hafver Herren alltså, handlat med denna stora stadenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Och man skall svara: Derföre, att de Herrans sins Guds förbund öfvergifvit hafva, och tillbedit andra gudar, och tjent dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Gråter icke öfver de döda, och grämer eder icke öfver dem; men gråter öfver den der bortfar, och skall aldrig igenkomma, att han sitt fädernesland mer se må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Ty så säger Herren om Sallum, Josia son, Juda Konungs, som Konung är uti sins faders Josia stad, som utfaren är af detta rum: Han skall intet komma här igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Utan måste dö uti det rum, dit han för en fånga förd är, och skall detta land intet mer se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Ve honom, som uppbygger sitt hus med synd, och sin mak med orätt; den sin nästa för intet arbeta låter, och icke gifver honom sin lön;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Och tänker: Nu väl, jag vill bygga mig ett stort hus, och ett vidt palats; och låter hugga sig fenster deruppå, och panelar det med cedreträ, och målar det rödt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Menar du, att du vill vara Konung, efter du prålar med cedreträ? Hafver din fader ock icke ätit och druckit, och blef ändock likväl vid rätt och rättfärdighet; och honom gick väl?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Han halp dem elända och fattiga till rätt, och det gick honom väl af. Är icke detta rättsliga känna mig? säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Men din ögon och ditt hjerta stå intet alltså, utan på din girighet, på att utgjuta oskyldigt blod, till att göra öfvervåld och orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Derföre säger Herren om Jojakim, Josia son, Juda Konung: Man skall intet begråta honom (sägandes): Ack broder, ack syster! Man skall intet begråta honom (sägandes): Ack herre, ack ädling!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Han skall likasom en åsne begrafven varda, försläpad och utkastad i porten i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Ja, gack ock nu upp på Libanon, och ropa, och låt dig höra i Basan, och ropa af Abarim; ty alle dine älskare äro ömkelige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Jag hafver tillförene sagt dig det, då det ännu väl stod med dig; men du sade: Jag vill intet hörat. Alltså hafver du gjort alla dina lifsdagar, att du intet hafver hört mina röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Vädret drifver alla dina herdar, och dine älskare fara bort fångne; der måste du till spott och skam varda, för alla dina ondskos skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Du som nu i Libanon bor, och hafver din näste i cedreträ, huru skönliga skall du se ut, när dig värk och sveda uppåkommer, såsom ene i barnsnöd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Så sant som jag lefver, säger Herren: Om Chonia, Jojakims son, Juda Konung, vore en signetsring på mine högra hand, så skulle jag ändå rifva dig deraf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Och gifva dig dem i händer, som efter ditt lif stå, och för hvilkom du dig fruktar, nämliga uti NebucadNezars händer, Konungens i Babel, och de Chaldeers;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Och skall drifva dig, och dina moder, som dig födt hafver, uti ett annat land, der edart fädernesland icke är, och der skolen I dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Och uti det land, der de af hjertat gerna igen voro, skola de icke igenkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Hvilken en elände, föraktad och fördrifven man är dock Chonia! Ett vanvördt och uselt fat! Ack! huru är han dock, samt med sine säd, fördrifven, och uti ett obekant land kastad!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'O land, land, land, hör Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Detta säger Herren: Skrifver denna mannen upp för en förderfvad; för en man dem i sina lifsdagar intet lyckas skall; ty han skall icke hafva den lyckona, att någor af hans säd skall sitta på Davids stol, och länger öfver Juda råda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Ve eder, herdar, I som förderfven och förskingren min fosterhjord, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Derföre säger Herren, Israels Gud, om de herdar, som mitt folk regera: I hafven förskingrat min hjord, och bortdrifvit, och icke besökt honom; si, jag skall hemsöka eder, för edart onda väsendes skull, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Och jag skall församla, det qvart är af minom hjord, utur all land, dit jag dem utdrifvit hafver, och skall hafva dem hem igen till deras hus, att de skola växa och förökas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Och jag skall sätta herdar öfver dem, som dem sköta skola, att de icke mer skola frukta sig eller förskräckas, eller hemsökte varda, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Si, den tiden kommer, säger Herren, att jag skall uppväcka David rättfärdighetenes frukt; och det skall vara en Konung, den väl regera skall, och skall upprätta rätt och rättfärdighet på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'På den tiden skall Juda hulpen varda, och Israel säker bo; och detta skall vara hans namn, det man honom kalla skall: Herren vår rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Derföre, si, den tid skall komma, säger Herren, då man nu intet mer skall säga: Så sant som Herren lefver, som Israels barn utur Egypti land fört hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Utan: Så sant som Herren lefver, som Israels hus säd utförde, och hade af nordlanden, och utur all land, dit jag dem fördrifvit hafver, så att de skola nu bo i sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Emot Propheterna: Mitt hjerta vill mig brista i mino lifve, all min ben darra; mig är lika som enom drucknom manne, och lika som enom den af vin ragar, för Herranom, och för hans heliga ordom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Att landet så fullt med horkarlar är, att landet så jämmerliga står, att det så förbannadt är, och ängarna i öknene förtorkas; och deras lefverne är ondt, och deras regemente doger intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Ty både Propheter och Prester äro skalkar; och jag finner också deras ondska i mino huse, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Derföre är deras väg lika som en slipper väg i mörkrena, der de uppå falla; ty Jag skall låta komma olycko öfver dem, deras hemsökningsår, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Med de Propheter i Samarien hafver jag sett galenskap, att de propheterade i Baal och förförde mitt folk Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Men med de Propheter i Jerusalem ser jag en styggelse; huru de bedrifva hor, och fara med lögn, och styrka de onda, på det att ju ingen skall omvända sig af sine ondsko. De äro alle för mig lika som Sodoma, och dess inbyggare lika som Gomorra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Derföre säger Herren Zebaoth om Propheterna alltså: Si, jag skall spisa dem med malört, och gifva dem galla dricka; ty ifrå Propheterna i Jerusalem kommer ut skrymteri öfver hela landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Detta säger Herren Zebaoth: Hörer intet Propheternas ord, de eder prophetera; de bedraga eder, ty de predika sins hjertas syner, och icke utaf Herrans mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'De säga dem som mig försmäda: Herren hafver det sagt: Eder varder väl gångandes; och allom dem som vandra efter sins hjertas tycko, säga de: Det kommer ingen olycka öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Ty ho hafver varit i Herrans råd, den hans ord sett och hört hafver? Ho hafver förmärkt och hört hans ord?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Si, ett Herrans väder skall komma med grymhet, och ett förskräckeligit oväder falla de ogudaktiga öfver hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Och Herrans vrede skall icke upphålla, tilldess han gör och uträttar det han i sinnet hafver. Härefter skolen I väl förvarat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Jag sände intet Propheterna, likväl lupo de; jag talade intet med dem, likväl propheterade de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Ty om de hade blifvit vid mitt råd och hade predikat mino folke min ord, så hade de omvändt dem ifrå deras onda väsende, och ifrå deras onda lefverne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Är jag icke en Gud, den hardt när är, säger Herren, och icke en Gud, den fjerran är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Menar du, att någor kan så hemliga fördölja sig, att jag icke kan se honom? säger Herren. Är icke jag den som uppfyller himmel och jord? säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Jag hörer väl, att Propheterna predika, och prophetera lögn i mitt Namn, och säga: Mig hafver drömt, mig hafver drömt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'När vilja nu Propheterna igenvända? de der lögn prophetera, och prophetera sins hjertas bedrägeri;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Och vilja, att mitt folk skall förgäta mitt Namn, för deras drömmars skull, som den ene för den andra predikar, såsom deras fäder förgåto mitt Namn för Baals skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'En Prophet, som drömmar hafver, han predike drömmar; men den som mitt ord hafver, han predike mitt ord rätt. Huru när kommer agnar och hvete tillhopa? säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Är icke mitt ord lika som en eld, säger Herren, och såsom en hammar, den berg sönderslår?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Derföre, si: Jag vill till de Propheter, säger Herren, som min ord stjäla den ene dem andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Si, jag vill till de Propheter, säger Herren, som sitt eget ord föra, och säga: Han hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Si, jag vill till de som falska drömmar prophetera, säger Herren, och predika dem, och förföra mitt folk med sine lögn och lösaktig ting; efter jag dock intet hafver sändt dem, och intet befallt dem, och de ej heller desso folkena nyttige äro, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Om detta folk, eller en Prophet, eller en Prest varder dig frågandes, och säger: Hvilket är Herrans tunge? så skall du säga till dem, hvad den tungen är: Jag skall bortkasta eder, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Och om en Prophet, eller Prest, eller folk varder sägandes: Det är Herrans tunge; densamma skall jag hemsöka, och hans hus dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Men så skall den ene tala med dem andra, och säga sig emellan: Hvad svarar Herren? Och hvad säger Herren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Och kaller det icke mer Herrans tunga; ty hvarjom och enom skall hans egen ord vara till en tunga, efter I alltså lefvandes Guds, Herrans Zebaoths, vårs Guds ord förvänden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Derföre skolen I säga till Propheten alltså: Hvad svarar Herren dig? Och hvad säger Herren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Nu medan I sägen Herrans tunge, derföre säger Herren alltså: Efter I kallen ordet Herrans tunga, och jag till eder sändt hafver, och hafver säga låtit, att I icke skullen kallat Herrans tunga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Si, så skall jag taga eder bort, och bortkasta eder samt med stadenom, som jag eder och edra fäder gifvit hafver, ifrå mitt ansigte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Och skall foga eder en evig skam till, och en evig försmädelse, den aldrig förgäten skall varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Si, Herren viste mig två fikonakorgar, satta inför Herrans tempel, sedan NebucadNezar, Konungen i Babel, hade bortfört Jechonia, Jojakims son, Juda Konung, samt med Juda Förstar, timbermän och smeder, ifrå Jerusalem, och låtit dem komma till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Uti dem ena korgenom voro ganska god fikon, såsom de först mogna fikonen äro; uti dem andra korgenom voro ganska ond fikon, så att man intet kunde äta dem, så ond voro de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Och Herren sade till mig: Jeremia, hvad ser du? Jag sade: Fikon; de goda fikonen äro ganska god, och de onda äro fast ond, så att man intet kan äta dem, så ond äro de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Då skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Detta säger Herren, Israels Gud: Likasom dessa fikonen äro god, alltså skall jag nådeliga upptaga de fångar af Juda, hvilka jag hafver låtit hädanfara in uti de Chaldeers land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Och skall nådeliga se till dem, och skall låta dem komma hit i landet igen, och skall uppbygga dem, och icke nederslå; jag skall plantera dem, och icke upprycka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Och skall gifva dem hjerta till att känna mig, att jag är Herren, och de skola vara mitt folk, och jag vill vara deras Gud; ty de skola af allt hjerta vända sig till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Men lika som de onda fikon så ond äro, att man dem icke äta kan, säger Herren; alltså vill jag bortgifva Zedekia, Juda Konung, samt med hans Förstar, och hvad qvart blifvet är i Jerusalem; de som äro qvarblefne i detta landet, och de som uti Egypti land bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Jag skall foga dem olycko till, och icke låta dem blifva i något rike på jordene, så att de skola komma till skam, till ett ordspråk, till en fabel, och till bannor, i all rum, dit jag dem bortdrifvandes varder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Och skall sända svärd, hunger och pestilentie ibland dem, tilldess de skola förgås af landena, som jag dem och deras fäder gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Detta är det ord, som till Jeremia skedde, öfver allt Juda folk, uti fjerde årena Jojakims, Josia sons, Juda Konungs, hvilket det första året är NebucadNezars, Konungens i Babel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Hvilket ock Propheten Jeremia talade till allt Juda folk, och till alla Jerusalems inbyggare, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Herrans ord är skedt till mig, ifrå trettonde årena Josia, Amos sons, Juda Konungs, allt intill denna dag, och jag hafver det nu i tre och tjugu år med flit predikat eder; men I hafven icke velat hörat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Så hafver ock Herren sändt till eder alla sina tjenare Propheterna ganska fliteliga; men I hafven intet velat höra dem, eller böja edor öron dertill, att I måtten hörat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Då han sade: Omvänder eder hvar och en af sinom onda väg, och ifrån edart onda väsende; så skolen I blifva i landena, som Herren eder och edra fäder gifvit hafver, i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Efterföljer icke andra gudar, så att I tjenen och tillbedjen dem, på det I icke skolen förtörna mig, genom edra händers verk, och jag eder olycko tillfoga må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Men I villen intet höra mig, säger Herren, på det I ju skullen förtörna mig, genom edra händers verk, till edor egen olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Derföre så säger Herren Zebaoth: Efter I icke villen höra min ord,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Si, så skall jag utsända och komma låta allt folk af nordan, säger Herren, och min tjenare NebucadNezar, Konungen i Babel, och skall låta dem komma öfver detta land, och öfver dem som deruti bo, och öfver allt detta folk som häromkring ligger, och skall gifva dem till spillo och förderfvelse, och göra dem till hån och evigt öde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Och skall taga ifrå dem all glädjesång, brudgummes och bruds röst, qvarns röst, och lyktos ljus:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Så att allt detta landet skall öde och förstördt ligga; och skola denna folken tjena Konungen i Babel i sjutio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Men när de sjutio år ute äro, så skall jag hemsöka Konungen i Babel, och allt det folket, säger Herren, för deras missgerningars skull; dertill ock de Chaldeers land, och skall görat till ett evigt öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Alltså skall jag låta komma öfver detta land all min ord, som jag emot det talat hafver, nämliga allt det i denna bok skrifvet står, det Jeremia öfver all folk spått hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Och de skola också tjena, ändock de mägtig folk och väldige Konungar äro. Alltså skall jag vedergälla dem efter förtjenst, och efter deras händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Ty så säger Herren, Israels Gud, till mig: Tag denna vinbägaren, fullan med vrede utaf mine hand, och skänk derutaf allom folkom, dem jag sänder dig till;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Att de måga dricka, raga och blifva galne, för svärdena som jag ibland dem sända skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Och jag tog bägaren af Herrans hand, och skänkte allom folkom, der Herren sände mig till;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Nämliga Jerusalem, Juda städer, hans Konungar och Förstar, att de skola öde och förstörde ligga, och skola vara till hån och bannor, såsom det nu i denna dag tillstår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Desslikes Pharao, Konungenom i Egypten, samt med hans tjenarom, hans Förstar och allt hans folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'All land vesterut; allom Konungom i Uz land, allom Konungom i de Palestiners land, samt med Askelon, Gasa, Ekron, och dem igenlefdom i Asdod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Dem af Edom, dem af Moab, Ammons barnom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'Allom Konungom i Tyro; allom Konungom i Zidon; Konungomen i de öar på hinsidone hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dem af Dedan, dem af Thema, dem af Bus, och allom Förstom i de landsändar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'Allom Konungom i Arabien, allom Konungom vesterut, de i öknene bo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Allom Konungom i Simri, allom Konungom i Elam, allom Konungom i Meden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'Allom Konungom norrut, både när och fjerran, den ene med den andra; och allom Konungom på jordene, som på jordenes krets äro; och Konung Sesach skall dricka efter dessa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Och säg till dem: Detta säger Herren Zebaoth, Israels Gud: Dricker, att I druckne varden, spyn och fallen, och icke kunnen uppstå, för svärdet som jag ibland eder sända skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Och om de icke vilja taga bägaren af dine hand och dricka, så säg till dem: Alltså säger Herren Zebaoth: I skolen dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Ty si, uti dem stadenom, som af mitt Namn nämnd är, begynner jag till att plåga; menen I, att I skolen ostraffade blifva? I skolen intet ostraffade blifva; ty jag kallar svärdet öfver alla de som bo på jordene, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Och du skall prophetera dem all dessa orden, och säg till dem: Herren skall ryta utu höjdene, och låta höra sin dunder utaf sine heliga boning; han skall ryta öfver sina boning, han skall sjunga ena viso, lika som en vintrampare, öfver alla landsens inbyggare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Hvilkens ljud skall höras intill verldenes ända; ty Herren hafver till att skaffa i rätta med Hedningomen, och skall hålla en dom med allt kött; de ogudaktiga skall han gifva under svärd, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Detta säger Herren Zebaoth: Si, en plåga skall komma ifrå det ena folket till det andra, och ett stort väder skall uppväckt varda ifrå landsens sido.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Så, skola de slagne af Herranom på samma tid ligga, ifrå den ena jordenes ända till den andra ändan. De skola intet varda begråtne, eller upptagne, eller begrafne, utan måste ligga på markene, och till träck blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Jämrer eder nu, I herdar, och roper, och välter eder I asko, I väldige öfver hjorden; ty tiden är kommen, att I skolen slagtade och förströdde varda, och skolen sönderfalla, såsom ett kosteligit fat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Och herdarna skola icke kunna fly, och de väldige öfver hjorden skola icke undkomma kunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Så, skola herdarna ropa, och de väldige öfver hjorden skola jämra sig, att Herren så hafver ödelagt deras bet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Och deras ängar, der så väl tillstod, äro förderfvada, af Herrans grymma vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Han hafver öfvergifvit sina hyddo, lika som ett ungt lejon; och så är deras land förstördt af tyrannens vrede, och af hans grymma vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Uti Jojakims rikes begynnelse, Josia sons, Juda Konungs, skedde detta ord af Herranom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Detta säger Herren: Gack in uti gården, åt Herrans hus, och predika för alla Juda städer, som der ingå till att tillbedja i Herrans hus, all de ord som jag dig befallt hafver att säga dem, och lägg der inte bort af;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Om de tilläfventyrs höra kunna och omvända sig, hvar och en ifrå sitt onda väsende, på det jag ock måtte ångra mig det onda, som jag tänker att göra dem, för deras onda väsendes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Och säg till dem: Detta säger Herren: Om I icke hören mig, så att I vandren uti min lag, som jag eder föresatt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Att I hören mina tjenares Propheternas ord, de jag städse till eder sändt hafver, och I dock intet höra villen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Så skall jag göra med desso huse likasom med Silo, och göra denna staden allom Hedningom på jordene till bannor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Då nu Presterna, Propheterna och allt folket hörde Jeremia, att han sådana ord talade i Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Och Jeremia nu uttalat hade allt det Herren honom befallt hade att säga allo folkena, grepo honom Presterna, Propheterna och allt folket, och sade: Du måste dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Hvi djerfves du prophetera i Herrans Namn, och säga: Det skall så gå med desso husena likasom med Silo, och denne staden skall så öde varda, att der ingen mer inne bor? Och allt folket församlade sig i Herrans hus emot Jeremia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Då nu Juda Förstar det hörde, gingo de utu Konungshuset upp i Herrans hus, och satte sig för Herrans nya port.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Och Presterna och Propheterna talade inför Förstarna och allo folkena, och sade: Denne är döden värd; ty han hafver predikat emot denna staden, såsom I med eder öron hört hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Men Jeremia sade till alla Förstarna, och till allt folket: Herren hafver sändt mig, att jag detta allt, som I hört hafven, predika skulle, emot detta huset, och emot denna staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Så bättrer nu edart väsende, och handel, och hörer Herrans edars Guds röst, så skall ock Herren låta sig ångra det onda, som han emot eder talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Si, jag är i edra händer: I mågen göra med mig, såsom eder godt och rätt tyckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Dock skolen I veta, att om I dräpen mig, så läggen I oskyldigt blod uppå eder sjelfva, uppå denna staden och hans inbyggare; ty i sanningene hafver Herren sändt mig till eder, att jag allt detta för edor öron tala skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Då sade Förstarna, och allt folket, till Presterna och Propheterna: Denne är icke saker till döds; ty han hafver talat till oss i Herrans vår Guds Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Och någre af de äldsta i landena stodo upp, och talade till hela hopen af folket, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Uti Hiskia, Juda Konungs, tid var en Prophet benämnd Micha af Moresa; han talade till allt Juda folk, och sade: Detta säger Herren Zebaoth: Zion skall upplöjd varda såsom en åker, och Jerusalem skall blifva till en stenhop, och (Herrans) hus berg till en vildan skog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Likväl lät Hiskia, Juda Konung, och hela Juda icke fördenskull döda honom; ja, de fruktade heldre Herran, och bådo inför Herranom; då ångrade ock Herren det onda, som han emot dem talat hade. Derföre göre vi ganska illa emot våra själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Var också en, den der propheterade i Herrans Namn, Uria, Semaja son, af Kiriath Jearim; den samme propheterade emot denna staden, och emot detta landet, lika som Jeremia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Men då Konung Jojakim, och alle hans väldige och Förstar, hans ord hörde, ville Konungen låta döda honom. Och Uria förnam det, fruktade sig, och flydde, och for in uti Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Men Konung Jojakim sände några män in uti Egypten, ElNathan, Achbors son, och andra med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'De förde honom utur Egypten, och hade honom in till Konung Jojakim; han lät då dräpa honom med svärd, och lät begrafva hans kropp snöpliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Alltså var Ahikams, Saphans sons, hand med Jeremia, att han icke kom i folkens händer, att de hade mått dräpit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Uti Jojakims rikes begynnelse, Josia sons, Juda Konungs, skedde detta ordet af Herranom till Jeremia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Detta säger Herren till mig: Gör dig ett ok, och häng det på din hals;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Och sänd det till Konungen i Edom, till Konungen i Moab, till Konungen öfver Ammons barn, till Konungen i Tyro, och till Konungen i Zidon, med de sändningabåd, som till Zedekia, Juda Konung, till Jerusalem komne äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Och befall dem, att de säga sina herrar: Detta säger Herren Zebaoth, Israels Gud: Så skolen I säga edra herrar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Jag hafvet gjort jordena, och menniskona, och djuren, som på jordene äro, genom mina stora kraft och uträcktom arm, och gifver henne hvem jag vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Men nu hafver jag gifvit all denna landen uti mins tjenares hand, NebucadNezars, Konungens i Babel, och hafver desslikes gifvit honom de vilddjur på markene, att de honom tjena skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Och all folk skola tjena honom, hans sone, och hans sonasone, tilldess hans lands tid ock kommer; då mång folk och stora Konungar skola låta tjena sig af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Men hvilket folk och rike icke vill tjena Konungenom af Babel, NebucadNezar, och hvilken som icke gifver sin hals under Konungens ok af Babel, det folket skall jag hemsöka med svärd, hunger och pestilentie, säger Herren, tilldess jag förgör dem genom hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Derföre hörer intet edra Propheter, spåmän, drömtydare, dagsväljare och trollkarlar, som säga eder: I varden intet tjenande Konungenom af Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Förty de spå eder lögn, på det de skola draga eder långt bort utur edart land, och jag då utdrifver eder, och I förgåns.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Ty hvilket folk, som böjer sin hals under Konungens ok i Babel, och tjenar honom, dem skall jag låta blifva uti sitt land, att de måga der bygga och bo, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Och jag talade allt detta, till Zedekia, Juda Konung, och sade: Böjer edar hals under Konungens ok i Babel, och tjener honom och hans folke, så skolen I blifva lefvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Hvi viljen I dö, du och ditt folk, genom svärd, hunger och pestilentie; såsom Herren sagt hafver öfver det folk, som Konungenom i Babel icke tjena, vill?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Derföre hörer de Propheters ord intet, som säga eder: I varden intet tjenande Konungenom af Babel; ty de prophetera eder lögn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Och jag hafver intet sändt dem, säger Herren, utan de prophetera lögn i mitt Namn på det jag skall utdrifva eder, och I förgås samt med Propheterna, som eder prophetera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Och till Presterna, och till allt detta folket talade jag, och sade: Detta säger Herren: Hörer edra Propheters ord intet, som eder prophetera, och säga: Si, de kärile af Herrans hus komma nu snart ifrå Babel hem igen; förty de prophetera eder lögn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Hörer dem intet; utan tjener Konungenom af Babel, så blifven I lefvande. Hvi skulle dock denna staden varda till ett öde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Äro de Propheter, och hafva Herrans ord, så låt dem det Herranom Zebaoth afbedja, att de qvarblefne kärilen i Herrans hus och Juda Konungs hus, och i Jerusalem, icke också till Babel förde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Ty så säger Herren Zebaoth om stodarna, och om hafvet, och om stolarna, och om de tyg, som ännu qvarblefna äro i denna staden,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'De NebucadNezar, Konungen i Babel, icke borttog, då han bortförde Jechonia, Jojakims son, Juda Konung, ifrå Jerusalem till Babel, samt med alla Förstarna i Juda och Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Ty så säger Herren Zebaoth, Israels Gud, om de tyg som ännu qvarblefne äro i Herrans hus, och i Juda Konungs hus, och i Jerusalem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'De skola till Babel förde varda, och der blifva intill den dagen, jag söker dem, säger Herren; och jag låter dem åter här uppkomma till detta rummet igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Och i det samma året, uti Zedekia, Juda Konungs, rikes begynnelse, i femte månadenom af fjerde årena, talade Hanania, Assurs son, en Prophet af Gibeon, till mig uti Herrans hus, i Presternas och allt folkens närvaro, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Detta säger Herren Zebaoth, Israels Gud: Jag hafver sönderbrutit Konungens ok i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Och förr än tu år förlidna äro, skall jag låta åter igenkomma till detta rummet alla Herrans hus kärile, hvilka NebucadNezar, Konungen i Babel, hädantagit och till Babel fört hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Dertill skall jag ock låta Jechonia, Jojakims son, Juda Konung, samt med alla fångar af Juda, som till Babel förde äro, komma till detta rummet igen, säger Herren; ty jag skall sönderbryta Konungens ok i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Då svarade Propheten Jeremia till den Propheten Hanania, uti Presternas och allt folkens närvaro, som i Herrans hus stodo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Och sade: Amen! Herren göre alltså; Herren stadfäste din ord, som du spått hafver, att han låter Herrans hus kärile, samt med alla fångna, komma till detta rummet igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Men hör dock likväl detta ordet, som jag för din öron, och allt folkens öron, talar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'De Propheter, som för mig och för dig varit hafva af ålder, de hafva propheterat emot mång land och stor rike, om örlig, om olycko, och om pestilentie.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Men när en Prophet propheterar om frid, så varder man kännandes, om Herren honom i sanningene sändt hafver, då hans ord fullkomnad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Då tog Hanania oket af Prophetens Jeremia hals, och sönderbröt det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Och Hanania sade, i allt folkens närvaro: Detta säger Herren: Likaså skall jag sönderbryta NebucadNezars ok, Konungens i Babel, af all folks hals, förr än tu år förlidna äro. Och Propheten Jeremia gick sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Men Herrans ord skedde till Jeremia, sedan den Propheten Hanania hade sönderbrutit oket af Jeremia Prophetens hals, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Gack bort, och säg Hanania: Detta säger Herren: Du hafver sönderbrutit träoket, så gör nu ett jernok i samma staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Ty detta säger Herren Zebaoth, Israels Gud: Ett jernok hafver jag hängt allo desso folkena på halsen, der de med tjena skola NebucadNezar, Konungen i Babel, och de måste tjena honom; ty jag hafver ock gifvit honom vilddjuren på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Och Propheten Jeremia sade till den Propheten Hanania: Hör dock, Hanania; Herren hafver intet sändt dig, och du hafver åstadkommit, att detta folket förlåter sig uppå lögn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Derföre säger Herren alltså: Si, jag skall taga dig bort utaf jordene; i detta året skall du dö: ty du hafver med ditt tal afvändt dem ifrå Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Och så blef den Propheten Hanania död, på det samma året, i sjunde månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Detta äro de ord, i de brefvena, som Propheten Jeremia sände af Jerusalem, till de igenlefda äldsta som bortförde voro, och till Presterna, och Propheterna, och till allt folket, som NebucadNezar ifrå Jerusalem till Babel bortfört hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Sedan Konung Jechonia och Drottningen, med kamererarena, och Förstarna i Juda och Jerusalem, samt med timbermän och smeder i Jerusalem, borto voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Genom Elasa, Saphans son, och Gemaria, Hilkia son, hvilka Zedekia, Juda Konung, sände till Babel, till NebucadNezar, Konungen i Babel, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Detta säger Herren Zebaoth, Israels Gud, till alla fångar, som jag hafver låtit bortföra ifrå Jerusalem till Babel:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Bygger hus, der I uti bo kunnen; planterer trädgårdar, der I frukt af äta mågen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Tager eder hustrur, och föder söner och döttrar; gifver edra söner hustrur, och gifver edra döttrar män, att de måga föda söner och döttrar; föröker eder der, så att I icke ären få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Söker stadsens bästa, dit jag hafver låtit bortföra eder, och beder för honom till Herran; ty då honom väl går, så går eder ock väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Ty detta, säger Herren Zebaoth, Israels Gud: Låter icke de Propheter, som när eder äro, och de spåmän bedraga eder, och sköter intet edra drömmar som I drömmen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Ty de spå eder lögn i mitt Namn; jag hafver intet sändt dem, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Ty så säger Herren; När i Babel sjutio år ute äro, så skall jag besöka eder, och skall uppväcka mitt nådeliga ord öfver eder, att jag skall låta eder komma till detta rum igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Ty jag vet väl, hvad tankar jag hafver om eder, säger Herren, nämliga fridsens tankar, och icke bedröfvelsens, att jag skall gifva eder den ända, som I vänten efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Och I skolen åkalla mig, och gå och bedja mig, och jag skall höra eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'I skolen söka mig, och finna mig; ty om I mig af allt hjerta söken,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Så skall jag låta mig finna af eder, säger Herren; och jag skall vända edart fängelse, och församla eder utur all folk, och utaf all rum, dit jag eder utdrifvit hafver, säger Herren; och skall låta eder återkomma till detta rum igen, dädan jag eder hafver bortföra låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Ty I menen, att Herren hafver uppväckt eder Propheter i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Ty detta säger Herren om Konungen, som på Davids stol sitter, och om allt folket, som i denna stadenom bor, nämliga om edra bröder, som med eder uti fängelset icke utdragne äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Ja, så säger Herren Zebaoth: Si, jag skall sända ibland dem svärd, hunger och pestilentie, och skall så ställa mig med dem, lika som med de onda fikon, de man vämjar vid att äta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Och skall förfölja dem med svärd, hunger och pestilentie, och skall icke låta dem blifva, uti något rike på jordene, så att de skola varda till bannor, till under, till hån och spott, ibland all folk, dit jag dem utdrifvandes varder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Derföre, att de icke hafva hört min ord, säger Herren, de jag städse med mina tjenare Propheterna till eder sändt hafver; men I villen intet höra, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Men I alle, som fångne bortförde ären, de jag hafver ifrå Jerusalem till Babel draga låtit, hörer Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Detta säger Herren Zebaoth, Israels Gud, emot Achab, Kolaja son, och emot Zedekia, Maaseja son, hvilke eder lögn spå i mitt Namn: Si, jag skall gifva dem uti NebucadNezars händer, Konungens i Babel; han skall låta slå dem för edor ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Så att man skall göra bannor af dem ibland alla fångar af Juda, som i Babel äro, och säga: Herren göre dig lika som Zedekia och Achab, hvilka Konungen af Babel på eld steka lät;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Derföre att de bedrefvo en galenskap i Israel, och bedrefvo hor med annars mans hustrur, och predikade lögn i mitt Namn, det jag dem intet befallt hade. Detta vet jag, och betygar det, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Och emot Semaja af Nehelam skall du säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Detta säger Herren Zebaoth, Israels Gud; derföre, att du under ditt namn hafver bref sändt till allt folket, som i Jerusalem är, och till Presten Zephanja, Maaseja son, och till alla Presterna, och sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Herren hafver satt dig till en Prest uti Prestens Jehojada stad, att I skolen tillsiare vara uti Herrans hus öfver alla ursinniga och spåmän, att du skall sätta dem i fångahus och i stock;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Och nu, hvi straffar du då icke Jeremia af Anathoth, den eder propheterar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Derföre, att han till oss i Babel sändt hafver, och låtit säga: Det skall ännu länge vara; bygger hus, der I uti bon, och planterer trägårdar, att I äten der frukt af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Och Zephanja Presten hade läsit det samma brefvet, och låtit Jeremia Propheten höra det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Derföre skedde Herrans ord till Jeremia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Sänd bort till alla fångarna, och låt säga dem: Detta säger Herren emot Semaja af Nehelam: Derföre, att Semaja propheterar eder, och jag hafver dock intet sändt honom, och hafver gjort, att I förlåten eder uppå lögn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Derföre säger Herren alltså: Si, jag skall hemsöka Semaja af Nehelam, samt med hans säd, så att ingen af hans skall blifva ibland detta folket, och skall icke se det goda, som jag desso mino folke göra vill, säger Herren; ty han hafver med sitt tal afvändt dem ifrå Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Detta är det ord, som af Herranom skedde till Jeremia:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Detta säger Herren, Israels Gud: Skrif dig all de orden uti ena bok, de jag talar till dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Ty si, den tiden kommer, säger Herren, att jag mins folks fängelse, både Israels och Juda, vända skall, säger Herren, och skall låta dem igenkomma uti det land, som jag deras fäder gifvit hafver, att de det besitta skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Och dessa äro de ord, som Herren talade om Israel och Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Ty så säger Herren: Sant året, det går ju ömkeliga till med eder; det är intet annat än fruktan på färde, och ingen frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Men fråger dock derefter, och ser till, om en mansperson föda kan? Huru går det då till, att jag ser alla män hålla sina händer uppå sina länder, såsom qvinnor i barnsnöd, och att all ansigte så blek äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Ack! det är ju en stor dag, och hans like hafver icke varit; och en bedröfvelsetid är i Jacob, likväl skall dem der uthulpet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Men det skall ske på den tiden, säger Herren Zebaoth, att jag hans ok sönderbryta skall af dinom hals, och slita din band sönder, att du deruti dem främmandom intet mer tjena skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Utan de skola tjena Herranom sinom Gud, och sinom Konung David, den jag dem uppväcka skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Derföre frukta du dig intet, min tjenare Jacob, säger Herren, och gif dig icke, Israel; ty si, jag vill hjelpa dig utu fjerran land, och dina säd utu sins fängelses land; så att Jacob skall igenkomma, lefva i frid, och nog hafva, och ingen skall förskräcka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Ty jag är när dig, säger Herren, att jag skall hjelpa dig; ty jag skall göra en ända med alla de Hedningar, dit jag dig förskingrat hafver; men med dig vill jag icke ända göra; men jag vill näpsa dig med måttelighet, på det du icke skall hålla dig oskyldig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Ty detta säger Herren: Din skade är allt för stor, och din sår äro allt för ond.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Dina sak handlar ingen, att han måtte förbinda dem; dig kan ingen läka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Alle dine älskare förgäta dig, och fråga der intet efter. Jag hafver slagit dig, lika som jag sloge en fienda, och såsom en obarmhertig stupat dig för dina stora missgerningars skull, och för dina starka synders skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Hvad ropar du öfver din skada, och öfver din stora värk? Hafver jag dock detta gjort dig för dina stora missgerningar, och för dina starka synders skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Derföre, alle de som dig frätit hafva, de skola uppfrätne varda, och alle de som dig ångest gjort hafva, skola fångne varda, och de som dig beröfvat hafva, skola beröfvade varda, och alle de som dig skinnat hafva, skola skinnade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Men dig vill jag åter helbregda göra, och hela din sår, säger Herren; derföre, att man kallar dig den fördrefna; och Zion, den der ingen efterfrågar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Detta säger Herren: Si, jag skall vända Jacobs hyddors fängelse, och förbarma mig öfver hans boning; och staden skall åter utur askone uppbyggd varda, och templet skall stå som det stå skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Och lof och fröjd skall gå derut: ty jag skall föröka, dem, och icke förminska; Jag skall göra dem stora, och icke mindre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Hans söner skola vara såsom tillförene, och hans menighet skall trifvas för mig; ty jag vill alla dem hemsöka, som honom plåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Och hans väldige skall utaf honom sjelfvom född varda, och hans Herre komma utaf honom sjelfvom, och jag skall låta honom nalkas mig, och han skall för mig komma; tv hvilken är den eljest, som med så viljogt hjerta nalkas mig? säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Och I skolen vara mitt folk, och jag skall vara edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Si, ett Herrans väder skall komma med grymhet; ett förskräckeligit oväder skall falla de ogudaktiga öfver hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Ty Herrans grymma vrede skall icke upphålla, tilldess han gör och uträttar hvad han i sinnet hafver; på sistone skolen I väl förnimma det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'På den samma tiden, säger Herren, skall jag vara alla Israels slägters Gud, och de skola vara mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Så säger Herren: Det folk, som qvar blifvet är för svärdet, hafver funnit nåde i öknene; Israel drager bort till sina ro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Herren hafver mig synts i fjerran land. Jag hafver ju alltid och allstädes haft dig kär; derföre hafver jag dragit dig till mig af blotta barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Nu väl, jag skall åter uppbygga dig, så att du skall uppbyggd heta, du jungfru Israel; du skall ännu med fröjd slå i trummo, och utgå i dans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Du skall åter plantera vingårdar på Samarie bergom; plantera skall man, och pipa dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Ty den tiden skall ännu komma, att vaktare på Ephraims berg ropa skola: Upp, och låter oss gå upp till Zion, till Herran vår Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Ty så säger Herren: Roper öfver Jacob med glädje, och fröjder eder öfver hufvudet ibland Hedningarna. Roper högt, priser, och säger: Herre, hjelp dino folke, dem igenblefnom i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Si, jag skall låta dem komma utu nordlandet, och vill församla dem ifrå jordenes ändar, både blinda, halta, hafvande qvinnor, och dem som nyfödt hafva, så att de skola i en stor hop hit igenkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'De skola komma gråtande och bedjande, så skall jag leda dem. Jag skall leda dem utmed vattubäcker en slätan väg, att de icke skola stöta sig; ty jag är Israels fader, så är Ephraim min förstfödde son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Hörer, I Hedningar, Herrans ord, och förkunner det fjerran på öomen, och säger: Den som Israel förskingrat hafver, han varder honom ock igen församlandes, och skall taga vara uppå honom, såsom en herde på sin hjord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Herren skall förlossa Jacob, och hjelpa honom utu dens mägtigas hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Och de skola komma och glädjas på Zions höjd, och skola med hopom söka intill Herrans gåfvor, nämliga till korn, must, oljo, och ung får, och oxar; så att deras själ skall varda lika som en vatturik örtegård, och skola intet mer bekymrade vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Alltså skola, jungfrurna lustiga vara i dans: dertill unge män och gamle, den ene med den andra; ty jag skall förvandla deras ångest i glädje, och trösta dem, och fröjda dem efter deras bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Och jag skall göra Presternas hjerta fullt med glädje, och mitt folk skall mina gåfvor hafva tillfyllest, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Detta säger Herren: Man hörer en klagelig röst och bitterlig gråt i höjdene. Rachel begråter sin barn, och vill intet låta sig trösta öfver sin barn; ty det är ute med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Men Herren säger alltså: Låt af ditt ropande och gråtande, och dina ögons tårar; ty ditt arbete är icke förgäfves, säger Herren. De skola, igenkomma utu fiendaland.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Och dine efterkommande hafva mycket godt vänta, säger Herren; ty dina barn skola komma uti sitt land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Jag hafver väl hört, huru Ephraim klagar: Du hafver späkt mig, och jag är ock späkt lika som en kåt kalf. Omvänd du mig, så varder jag omvänd; ty du Herre, äst min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'När jag omvänd vardt, så gjorde jag bättring; ty sedan jag lärde veta, slår jag mig uppå länderna; ty jag är på skam kommen, och blyges; ty jag måste lida det hån, som jag tillförene förtjent hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Är icke Ephraim min älskelige son, och mitt kära barn? Ty jag kommer nu väl ihåg, hvad jag med honom talat hafver; derföre brister mig mitt hjerta för hans skull, att jag måste förbarma mig öfver honom, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Uppsätt dig åminnelsetecken, sätt dig sörjotecken, och styr ditt hjerta in uppå den rätta vägen, der du på vandra skall. Vänd om, du jungfru Israel, vänd om igen till dessa dina städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Huru länge vill du vända dig bort, du affälliga dotter, den jag igenhemta vill? Ty Herren skall något nytt skapa i landena; en qvinna skall omfatta en man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Detta säger Herren Zebaoth, Israels Gud: Man skall ännu säga detta ordet i Juda land, och i dess städer, då jag deras fängelse vändandes varder: Herren välsigne dig, du rättvisones boning, du helga berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Och Juda, samt med alla sina städer, skola bo derinne; dertill åkermän, och de som med hjord omkringfara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Ty jag skall vederqvicka de trötta själar, och mätta de bekymrada själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Derföre vakade jag upp, och såg mig om, och hade så sött sofvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Si, den tid kommer, säger Herren, att jag skall beså Israels hus och Juda hus, både med folk och fä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Och som jag öfver dem vakat hafver, till att upprycka, sönderrifva, omkullslå, förderfva, och till att plåga; så skall jag ock vaka, öfver dem, till att uppbygga och plantera, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'På den samma tiden skall man intet mer säga: Fäderna hafva ätit sura vindrufvor, och barnens tänder äro ömma vordna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Utan hvar och en skall dö för sina missgerning; och hvilken menniska, som sura vindrufvor äter, honom skola hans tänder ömma varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Si, den tid kommer, säger Herren, då skall jag göra ett nytt förbund med Israels hus, och med Juda hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Icke sådant, som det förra förbundet var, det jag med deras fäder gjorde, då jag tog dem vid handena, att jag skulle föra dem utur Egypti land; hvilket förbund de intet hållit hafva, och jag måste tvinga dem, säger Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Utan detta skall vara förbundet, som jag skall göra med Israels hus, efter denna tiden, säger Herren. Jag skall gifva min lag uti deras hjerta, och skrifva dem uti deras sinne; och de skola vara mitt folk, så vill jag vara deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Och ingen skall lära den andra, icke en broder den andra, och säga: Känn Herran; utan de skola alle känna mig, både små och stora, säger Herren; ty jag vill förlåta dem deras missgerningar, och aldrig komma deras synder mer ihåg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Detta säger Herren, som gifver solena dagenom till ett ljus, och månan och stjernorna, efter deras lopp, nattene till ljus; den som rörer hafvet, att dess böljor fräsa; Herren Zebaoth är hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'När denna ordningen afkommer för mig, säger Herren, så skall ock Israels säd återvända, så att det icke mer skall vara ett folk för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Detta säger Herren: Om man kan mäla himmelen ofvantill, och utransaka jordenes grund, så skall jag ock förkasta hela Israels säd, för allt det som de göra, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Si, den tid kommer, säger Herren, att Herrans stad skall uppbyggd varda, ifrå Hananeels torn allt intill hörnaporten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Och rättesnöret skall gå derifrå länger ut, allt intill den högen Gareb, och vända sig inåt Goath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Och hele dödodalen, och askoplatsen, samt med hela dödåkrenom, allt intill Kidrons bäck, intill hörnet af hästaportenom österut, skall varda helig Herranom, så att det aldrig mer skall omkullrifvet eller afbrutet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Detta är det ord, som af Herranom skedde till Jeremia i tionde årena Zedekia, Juda Konungs, hvilket det adertonde året är NebucadNezars.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Då belade Konungens här af Babel Jerusalem; men Propheten Jeremia låg fången i gården för fångahuset, i Juda Konungs hus,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Der Zedekia, Juda Konung, hade låtit inlägga honom, sägandes: Hvi propheterar du, och säger: Detta säger Herren: Si, jag gifver denna staden uti Konungens händer i Babel, och skall vinna honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Och Zedekia, Juda Konung, skall icke undkomma de Chaldeer, utan jag skall gifva honom uti Konungens händer af Babel, så att han skall muntliga tala med honom, och med sin ögon se honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Och han skall föra Zedekia till Babel, der skall han ock blifva, till dess jag söker honom, säger Herren; ty om I än striden emot de Chaldeer, skall det dock intet lyckas eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Och Jeremia sade: Herrans ord är skedt till mig, och säger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Si, Hanameel, Sallums son, dins faderbroders, kommer till dig, och skall säga: Käre, köp du min åker i Anathoth; ty du hafver nästa bördrätten dertill, att du skall köpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Alltså kom Hanameel, min faderbroders son, till mig, såsom Herren sagt hade, i gården för fångahuset, och sade till mig: Käre, köp min åker i Anathoth, som ligger i BenJamins land; ty du hafver arfrätt dertill, och du äst den näste. Käre, köp honom. Då förmärkte jag, att det var Herrans ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Och köpte åkren af Hanameel, mins faderbroders son, i Anathoth, och vog honom penningarna till, sju siklar och tio silfpenningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Och skref ett bref, och förseglade det, och tog vittne deruppå, och vog upp penningarna på en vågskål;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Och tog det förseglade köpbrefvet till mig, efter rätten och sedvänjan, och en öppen utskrift;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Och fick köpbrefvet Baruch, Neria sone, Mahaseja sons, uti Hanameels, mins faderbroders sons, och de vittnes, som i köpbrefvena stodo, och alla Judarnas närvaro, som i gården för fångahuset såto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Och befallde Baruch för deras ögon, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Detta säger Herren Zebaoth, Israels Gud: Tag dessa brefven, det förseglade köpbrefvet, samt med denna öppna utskriftene, och lägg dem uti ett lerkäril, att de måga ligga förvarade i lång tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Ty så säger Herren Zebaoth, Israels Gud: Ännu skall man köpa hus, åkrar och vingårdar, i desso landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Och då jag hade fått Baruch, Neria sone, köpbrefvet, bad jag till Herran, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'O Herre Herre, si, du hafver gjort himmel och jord genom dina stora kraft, och genom din uträckta arm, och ingen ting är för dig omöjelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Du, som mångom tusendom väl gör, och vedergäller fädernas missgerningar uti deras barnas sköte efter dem; du store och starke Gud, Herre Zebaoth är ditt Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Stor i råd och mägtig i gerningom; och din ögon stå öppne öfver alla menniskors barnas vägar, att du skall gifva, hvarjom och enom efter sitt väsende, och efter sins väsendes frukt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Du, som uti Egypti land tecken och under gjorde, allt intill denna dag, både med Israel och med menniskomen, och gjorde dig ett Namn, såsom det i denna dag är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Och förde ditt folk Israel utur Egypti land, genom tecken och under, genom ena mägtiga hand, med enom uträcktom arm, och genom stor förskräckning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'Och gaf dem detta landet, hvilket du deras fäder svorit hade att du dem det gifva ville; ett land, der mjölk och hannog uti flöt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Och då de der inkommo och besåto det, hörde de intet dina röst, och vandrade ej heller efter din lag, och allt det du dem budit hade, att de göra skulle, det gjorde de intet; derföre du ock hafver låtit dem alla denna olyckona vederfaras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Si, denne staden är belagd, så att han måste vunnen, och för svärd, hunger och pestilentie, uti de Chaldeers händer, som emot honom strida, gifven varda; och lika som du sagt hafver, så går det nu, det ser du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Och du, Herre Herre, säger till mig: Köp du en åker för penningar, och tag vittne deruppå; ändock staden skall varde, gifven uti de Chaldeers händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Och Herrans ord skedde till Jeremia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Si, jag Herren är en Gud öfver allt kött; skulle något vara mig omöjeligit?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Derföre säger Herren alltså: Si, jag gifver denna staden uti de Chaldeers händer, och uti NebucadNezars hand, Konungens i Babel, och han skall vinna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Och de Chaldeer, som emot denna staden strida, skola komma härin, och tända här elden uppå, och bränna honom upp, samt med husen, der de Baal på taken rökt, och androm gudom drickoffer offrat hafva, på det de skulle förtörna mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Ty Israels barn och Juda barn hafva af deras ungdom gjort det mig illa behagar, och Israels barn hafva förtörnat mig genom sina händers verk, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Ty ifrå den tiden, att denne staden byggd var, intill denna dag, hafver han gjort mig vredan och grymman, så att jag måste bortkasta honom ifrå mitt ansigte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'För alla Israels barnas och Juda barnas ondskos skull, den de bedrifvit hafva, på det de skulle förtörna mig, de, deras Konungar, Förstar, Prester och Propheter, och de som bo i Juda och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'De hafva vändt mig ryggen till, och icke ansigtet, ändock jag lät allstädes lära dem; men de ville intet höra eller bättra sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Dertill hafva de satt sin styggelse uti det hus, som namn hafver af mig, på det de skulle det orena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Och hafva byggt Baals höjder, i Hinnoms sons dal, på det de skulle uppbränna sina söner och döttrar för Molech, der jag dem intet om befallt hafver, och kom mig icke heller någon tid i sinnet, att de sådana styggelse göra skulle, med hvilko de så kommo Juda till att synda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Och nu fördenskull säger Herren Israels Gud alltså om denna staden, der I om sägen, att han skall för svärd, hunger och pestilentie, uti Konungens händer af Babel gifven varda:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Si, jag skall församla dem utur all land, dit jag dem bortdrifver, genom mina stora vrede, grymhet och obarmhertighet, och skall låta komma dem åter till detta rummet igen, att de skola bo trygge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Och de skola vara mitt folk, så vill jag vara deras Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Och skall gifva dem ens hjerta och väsende, att de skola frukta mig i alla sina lifsdagar, på det dem och deras barnom, efter dem, skall väl gå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Och skall göra ett evigt förbund med dem, så att jag icke vill aflåta att göra dem godt; och skall gifva dem min fruktan i hjertat, att de icke skola vika ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Och det skall vara min lust, att jag må göra dem godt; och jag skall plantera dem i desso lande troliga, af allt hjerta och af allo själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Ty så säger Herren: Likasom jag öfver detta folket hafver komma låtit alla denna stora olyckona, alltså skall jag ock låta komma öfver dem allt det goda, som jag till dem sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Och det skola ännu åkrar köpte varda i desso lande, om hvilket I sägen: Det skall öde ligga, så att hvarken folk eller fä deruti blifva skall, och skall varda gifvet uti de Chaldeers händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Likväl skall man ännu köpa, åkrar för penningar, och bebrefva, försegla och betyga uti BenJamins land, och omkring Jerusalem, och uti Juda städer, uti de städer på bergomen, uti de städer i dalomen, och uti de städer söderut; ty jag skall vända deras fängelse, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Och Herrans ord skedde till Jeremia annan gången, då han ännu innelyckter var i gården för fångahuset, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Detta säger Herren, som detta gör, Herren, som detta verkar och uträttar; Herre är mitt Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Ropa till mig, så vill jag svara dig, och skall kungöra dig stor och mägtig ting, de du intet vetst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Ty så säger Herren, Israels Gud, om denna stadsens hus, och om Juda Konungars hus, som nederbrutna äro, till att göra bålverk till värn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Och om dem som här inkomne äro, på det de skola strida emot de Chaldeer, att de måga uppfylla honom med döda, kroppar, hvilka jag i mine vrede och grymhet slå skall; ty jag hafver förgömt mitt ansigte för denna stadenom, för alla deras ondskos skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Si, jag vill förbinda, deras sår, och göra dem helbregda, och skall tillåta dem deras bön om frid och trohet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Ty jag vill vända Juda fängelse, och Israels fängelse, och skall uppbygga dem, lika såsom af begynnelsen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Och skall rena dem af all missgerning, der de med emot mig syndat hafva, och skall förlåta dem all missgerning, der de med emot mig syndat och öfverträdt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Och det skall vara mig till ett glädjenamn, berömmelse och pris ibland alla Hedningar på jordene, då de få höra allt det goda, som jag dem gör; och skola förundra sig och förskräckas öfver allt det goda, och öfver all den frid, som jag dem gifva vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Detta säger Herren: Uti detta rummet, der I om sägen, det är öde, efter hvarken folk eller fä i Juda städer, och på gatomen i Jerusalem, blifver; de så förödde äro, att der hvarken folk, borgare eller boskap, uti är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Der skall man ännu åter höra rop af fröjd och glädskap, brudgummes och bruds röst, och deras röst, som säga: Tacker Herranom Zebaoth, ty Herren är god, och gör ju alltid väl i evighet, och deras, som tackoffer frambära till Herrans hus; ty jag skall omvända landsens fängelse, lika som af begynnelsen, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Så säger Herren Zebaoth: Uti detta rummet, det så öde är, att hvarken folk eller fä deruti är, och i alla dess städer, skola ännu herdars hus vara, som hjordar föda skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Både i de städer på bergomen, och i de städer i dalomen, och i de städer söderut, i BenJamins land, och omkring Jerusalem, och i Juda städer, der skola ännu ut och in gå räknade hjordar, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Si, den tid kommer, säger Herren, att jag det goda ordet uppväcka skall, som jag till Israels hus och Juda hus talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Uti de samma dagar, och i den samma tiden skall jag låta uppgå David rättfärdighetenes frukt (och det skall vara en Konung, som väl regera skall), och skall upprätta rätt och rättfärdighet på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'På den samma tiden skall Juda frälst varda, och Jerusalem säker bo, och man skall kalla honom Herren vår rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Ty så säger Herren: Det skall icke fela, en af David skall sitta på Israels hus stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Desslikes skall ej heller någon tid fela, att Prester och Leviter skola vara för mig, som bränneoffer göra, och spisoffer upptända, och offer slagta, i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Och Herrans ord skedde till Jeremia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Detta säger Herren: Om mitt förbund med dag och natt återvänder, att ingen dag eller natt är i sinom tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Så skall ock mitt förbund omintet varda med minom tjenare David, att han ingen son skall hafva till en Konung på sinom stol, och med Leviterna och Presterna mina tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Lika som man intet räkna, kan himmelens här, eller mäta sanden i hafvet; alltså skall jag föröka mins tjenares Davids säd, och Leviterna, som mig tjena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Och Herrans ord skedde till Jeremia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Hafver du icke sett hvad detta folket talar, och säger: Hafver dock Herren de två slägterna förkastat, som han utkorat hade? och försmäda mitt folk, lika som de intet mer skulle vara mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Detta säger Herren: Håller jag icke mitt förbund med dag och natt, och den ordning med himmel och jord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Så vill jag ock förkasta Jacobs och Davids mina tjenares säd, att jag af deras säd icke tager dem, som råda skola öfver Abrahams, Isaacs och Jacobs säd; ty jag skall omvända deras fängelse, och förbarma mig öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Detta är det ord, som af Herranom skedde till Jeremia, då NebucadNezar, Konungen i Babel, samt med allom sinom här, och med all rike på jordene, som under hans välde voro, och med all folk, örligade mot Jerusalem, och alla dess städer, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Detta säger Herren Israels Gud: Gack bort, och tala med Zedekia, Juda Konung, och säg till honom: Så säger Herren: Si, jag skall gifva denna staden uti Konungens händer i Babel, och han skall bränna honom upp i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Och du skall icke undkomma hans hand, utan varda gripen, och i hans hand gifven, så att du skall se honom med ögonen, och muntliga tala med honom, och till Babel komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Så hör dock, du Zedekia, Juda Konung, Herrans ord; detta säger Herren om dig: Du skall icke dö genom svärd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Utan du skall dö i frid; och lika som man hafver bränt öfver dina fäder, de förra Konungar, som för dig varit hafva, så skall man ock bränna öfver dig, och begråta dig: Ack! herre; ty jag hafver det sagt, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Och Propheten Jeremia talade all dessa, orden till Zedekia, Juda Konung, i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Då Konungens här i Babel allaredo stridde emot Jerusalem, och emot alla qvarlefda Juda städer, nämliga emot Lachis och Aseka; ty desse, såsom de fastaste städer, voro ännu qvarblefne af Juda städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Detta är det ord, som af Herranom skedde till Jeremia, sedan Konung Zedekia ett förbund gjort hade med allo folkena i Jerusalem, till att utropa ett friår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Så att hvar och en skulle gifva sin träl och hvar och en sina trälinno fri, de der Ebreer och Ebreiske voro, att den ene Juden icke skulle vara dens andras träl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Då lydde honom alle Förstarna, och allt folket, som det förbund undergångit hade, att hvar och en skulle gifva sin träl och trälinno fri, och icke mer hålla dem för lifegna, och gåfvo dem lösa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Men något derefter vände de om igen, och togo de trälar och trälinnor åter till sig, som de frigifvit hade, och tvingade dem, att de trälar och trälinnor vara måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Då skedde Herrans ord till Jeremia af Herranom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Detta säger Herren, Israels Gud: Jag hafver gjort ett förbund med edra fäder, då jag förde dem utur Egypti land, utu träldomens hus, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Då sju år förlidne äro, så skall hvar och en låta sin broder, den en Ebreer är, och sig honom sålt, och i sex år tjent hafver, fri och lös; men edra fäder hörde mig intet, och böjde intet sin öron dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Så hafven I nu i dag omvändt eder, och gjort det mig väl behagade, att I låten utropa ett friår, hvar och en sinom nästa, och hafven deruppå gjort ett förbund inför mig uti de huse, som efter mitt Namn nämndt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Men I hafven åter sedan trädt derifrå, och ohelgat mitt Namn, och hvar och en igentagit sin träl och trälinno, de I haden frigifvit, att de skulle vara sine egne, och tvingen dem nu att de edre trälar och trälinnor vara måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Derföre säger Herren alltså: I hörden icke mig, att I måtten utropat ett friår, hvar och en sinom broder, och sinom nästa. Si, så ropar jag, säger Herren, eder ett friår ut, till svärd, till pestilentie, till hunger; och skall icke låta eder bliva uti något rike på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Och de som öfverträda mitt förbund, och icke hålla dess förbunds ord, som de för mig gjort hafva, dem skall jag så göra, lika som dem kalfvenom, den de i tu stycke höggo, och emellan båda stycken gingo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Nämliga Juda Förstar, Jerusalems Förstar, de kamererare, Presterna, och allt folket i landena, som emellan stycken af kalfven gångne äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Och skall gifva dem uti deras fiendars hand, och deras som efter deras lif stå, att deras kroppar skola foglomen under himmelen och djuromen på jordene till spis varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Och Zedekia, Juda Konung, och hans Förstar, skall jag gifva uti deras fiendars händer, och i deras som efter deras lif stå, och i Konungens härs händer af Babel, hvilken nu ifrån eder afdragen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Ty si, jag vill befalla dem, säger Herren, och skall åter låta dem komma inför denna staden, och de skola strida emot honom, och vinna honom, och uppbränna honom i eld; och jag skall föröda Juda städer, så att der ingen mer bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Detta är det ord, som af Herranom skedde till Jeremia, i Jojakims, Josia sons, Juda Konungs, tid, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Gack bort uti de Rechabiters hus, och tala med dem, och haf dem in uti Herrans hus uti en kammar, och skänk dem vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Då tog jag Jaasanja, Jeremia son, Habazinia sons, samt med hans bröder, och alla hans söner, och hela de Rechabiters hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'Och hade dem in uti Herrans hus, uti Hanans barnas, Jigdalja sons, den Guds mansens, kammar, hvilken vid Förstarnas kammar är, ofvanför Maaseja, Sallums sons, dörravaktarens kammar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Och jag satte de Rechabiters hus barnom kannor före, fulla med vin, och skålar, och sade till dem: Dricker vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Men de svarade: Vi dricke intet vin; ty vår fader Jonadab, Rechabs son, hafver budit oss, och sagt: I och edor barn skolen aldrig något vin dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Och intet hus bygga, ingen säd så, ingen vingård plantera, eller hafva; utan skolen bo i tjäll i alla edra lifsdagar; på det I mågen länge lefva i landena, der I uti vandren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Alltså lydom vi vår faders röst, Jonadabs, Rechabs sons, i allt det han oss budit hafver, så att vi intet vin dricke i våra lifsdagar, hvarken vi eller våra hustrur, eller söner, eller döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Och byggom ej heller någor hus, der vi uti bo, och hafvom hvarken vingårdar, eller åkrar, eller säd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Utan bom uti tjäll, och lydom, och görom all ting, såsom vår fader Jonadab oss budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Men då NebuchadNezar, Konungen i Babel, drog hitupp i landet, sade vi: Kommer, låter oss draga till Jerusalem, för de Chaldeers och Syrers här; och så hafve vi sedan blifvit här i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Då skedde Herrans ord till Jeremia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Detta säger Herren Zebaoth, Israels Gud: Gack bort, och säg till dem i Juda, och till de inbyggare i Jerusalem: Viljen I då icke bättra eder, så att I lyden min ord? säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Jonadabs ord, Rechabs sons, som han sinom barnom budit hafver, att de intet vin dricka skulle, de varda hållen, så att de dricka intet vin intill denna dag, derföre att de lyda deras faders bud; men jag hafver tidigt låtit predika eder, likväl hören I mig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Så hafver jag ock tidigt sändt till eder alla mina tjenare Propheterna, och låtit säga: Vänder eder om, hvar och en ifrå sitt onda väsende, och bättrer edart lefverne, och efterföljer icke andra gudar, till att tjena dem, så skolen I blifva i landena, som jag eder och edra fäder gifvit hafver; men I villen icke böja edor öron dertill, eller höra mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Ändock Jonadabs barn, Rechabs sons, sins faders bud hållit hafva, som han dem budit hafver; men detta, folket hörer mig Intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Derföre så säger Herren Gud Zebaoth, och Israels Gud: Si, jag skall låta komma öfver Juda, och alla Jerusalems inbyggare, all den olycko, som jag emot dem talat hafver; derföre, att jag hafver talat till dem, och de ville intet höra; jag hafver ropat, men de ville intet svara mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Och till de Rechabiters hus sade Jeremia: Detta säger Herren Zebaoth, Israels Gud; derföre att I edars faders Jonadabs bud lydt hafven, och hållit all hans bud, och allt det gjort, som han eder budit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Derföre säger Herren Zebaoth, Israels Gud, alltså: Det skall aldrig fela Jonadab, Rechabs sone, att ju någor af hans säd alltid för mig stå skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Uti fjerde årena Jojakims, Josia sons, Juda Konungs, skedde detta ordet till Jeremia af Herranom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Tag ena bok, och skrif deruti allt det tal, som jag till dig talat hafver öfver Israel, öfver Juda, och all folk, ifrå den tiden, då jag till dig talat hafver, nämliga ifrå Josia tid, allt intill denna dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Om tilläfventyrs Juda hus, när de höra all den olycko, som jag hafver i sinnet att göra dem, sig omvända måga, hvar och en ifrå sitt onda väsende, på det jag måtte förlåta dem deras missgerningar och synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Då kallade Jeremia Baruch, Neria son. Den samme Baruch skref uti ena bok af Jeremia mun all Herrans ord, som han till honom talat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Och Jeremia böd Baruch, och sade: Jag är fången, så att jag icke kan gå uti Herrans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Men gack du derin, och läs bokena, der du Herrans ord af minom mun uti skrifvit hafver, för folkena i Herrans hus, på fastodagomen; och skall desslikes läsa dem för hela Juda öron, som uti deras städer inkomma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Om de tilläfventyrs måtte ödmjuka sig med bedjande inför Herranom, och omvända sig, hvar och en ifrå sitt onda väsende; ty vreden och grymheten är stor, der Herren emot detta folket om talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Och Baruch, Neria son, gjorde allt det Propheten Jeremia honom befallt hade, och las Herrans ord utu bokene, i Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Men det begaf sig uti femte årena Jojakims, Josia, sons, Juda Konungs, uti nionde månadenom, att man förkunnade ena fasto för Herranom allo folkena i Jerusalem, och allo folkena, som utaf Juda städer till Jerusalem kommo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Och Baruch las utu bokene Jeremia ord i Herrans hus, uti Gemaria kammar, Saphans sons, cancellerens, i öfra gårdenom, inför den nya porten åt Herrans hus, för allo folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Då nu Michaja, Gemaria son, Saphans sons, all Herrans ord utu bokene hört hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Gick han ned uti Konungshuset, uti cancelliet; och si, der såto alle Förstarna, Elisama cancelleren, Delaja, Semaja son, ElNathan, Achbors son, Gemaria, Saphans son, och Zedekia, Hanania son, samt med alla Förstarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Och Michaja förkunnade dem all de ord, som han hört hade, då Baruch las utu bokene för folkens öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Då sände alle Förstarna Judi, Nethania son, Selemia sons, Cusi sons, efter Baruch, och läto säga honom: Tag den bokena med dig, der du utu för folkena läsit hafver, och kom hit. Och Baruch, Neria son, tog bokena med sig, och kom till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Och de sade till honom: Sätt dig, och läs, att vi måge hörat. Och Baruch las för deras öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Och då de all orden hört hade, förskräcktes de hvar emot den andra, och sade till Baruch: Vi vilje förkunna Konungenom all dessa orden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Och sporde de Baruch: Säg oss, huru hafver du skrifvit all dessa orden utu hans mun?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baruch sade till dem: Han las mig all dessa orden till, utaf sinom mun, och jag skref dem med bläck uti bokena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Då sade Förstarna till Baruch: Gack bort, och förgöm dig med Jeremia, så att ingen vet hvar I ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Men de gingo in till Konungen i förpalatset, och läto bokena blifva qvara i Elisama cancellerens kammar, och sade för Konungenom all dessa orden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Då sände Konungen Judi åstad, till att hemta bokena. Han tog henne utur Elisama cancellerens kammar, och Judi las henne för Konungenom, och allom Förstomen, som för Konungenom stodo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Men Konungen satt i vinterhusena, för skorstenen, i nionde månadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Som nu Judi tre eller fyra blad läsit hade, skar han henne sönder med enom skrifknif, och kastade i elden, som i skorstenenom var, tilldess boken platt uppbrändes i eldenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Och ingen förskräckte sig eller sönderref sin kläder, hvarken Konungen, eller hans tjenare, hvilke dock all dessa orden hört hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Ändock ElNathan, Delaja och Gemaria bådo Konungen, att han dock icke ville uppbränna bokena; men han hörde dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Dertill böd ändå Konungen Jerahmeel, Hammelechs sone, och Seraja, Asriels sone, och Selemja, Abdeels sone, att de skulle gripa Baruch skrifvaren, och Jeremia Propheten; men Herren hade förgömt dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Då skedde Herrans ord till Jeremia, sedan Konungen hade uppbränt bokena, och de ord, som Baruch utaf Jeremia mun skrifvit hade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Tag dig åter en annor bok, och skrif all de förra orden deruti, som i den första bokene stodo, den Jojakim, Juda Konung, uppbränt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Och säg till Jojakim, Juda Konung: Detta säger Herren: Du hafver uppbränt bokena, och sagt: Hvi hafver du deruti skrifvit, att Konungen af Babel komma skall och förderfva detta landet, och görat så att hvarken folk eller fä mer derinne blifva skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Derföre säger Herren om Jojakim, Juda Konung: Det skall ingen af hans säd sitta på Davids stol, och hans kropp skall utkastad varda, och ligga i hetta om dagen, och i frost om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Och jag skall hemsöka honom, och hans säd, och hans tjenare, för deras missgerningars skull, och jag skall låta komma öfver dem, och öfver Jerusalems inbyggare, och öfver dem i Juda, alla den olycko, som jag till dem talat hafver, och de dock intet höra ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Så tog Jeremia en annan bok, och fick henne Baruch, Neria sone, skrifvarenom: och han skref deruti, af Jeremia mun, all de ord som i bokene stodo, som Jojakim, Juda Konung, hade i eld uppbränna låtit; och till de samma vordo ännu mycket flere ord tillagd, än de förra voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Och Zedekia, Josia son, vardt Konung uti Chonia stad, Jojakims sons; ty NebucadNezar, Konungen i Babel, gjorde honom till Konung i Juda land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Men han, och hans tjenare, och folket i landena, lydde intet Herrans ord, som han genom Propheten Jeremia talade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Likväl sände Konung Zedekia Jehuchal, Selemja son, och Zephania, Maaseja son, Presten, till Propheten Jeremia, och lät säga honom: Bed Herran vår Gud för oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Ty Jeremia gick nu ut och in ibland folket, och ingen lade honom nu i fängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Så var Pharaos här dragen utur Egypten; och de Chaldeer, som för Jerusalem lågo, då de sådant rykte hörde, voro ifrå Jerusalem afdragne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Och Herrans ord skedde till Propheten Jeremia, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Detta säger Herren, Israels Gud: Så säger till Juda Konung, den eder till mig sändt hafver, till att fråga mig: Si, Pharaos här, som eder till hjelp utdragen är, skall åter draga hem igen uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Och de Chaldeer skola komma igen, och strida emot denna staden, och vinna honom, och uppbränna honom i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Derföre säger Herren alltså: Bedrager icke edra själar, så att I tänken: De Chaldeer draga väl sin väg; de skola intet draga sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Och om I än slogen hela de Chaldeers här, som emot eder strida, och någre af dem qvare blefve såre, så skulle de ändå resa sig upp, hvar och till i sitt tjäll, och uppbränna denna staden med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Som nu de Chaldeers här ifrå Jerusalem afdragen var, för Pharaos härs skull,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Gick Jeremia utu Jerusalem, och ville gå uti BenJamins land, till att bestyra der om några ägor ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Och då han kom uti BenJamins port, så var der en skickad för en portvaktare, benämnd Jirija, Selemja son, Hanania sons; den samme tog fatt uppå Propheten Jeremia, och sade: Du Vill falla till de Chaldeer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremia sade: Det är icke sant; jag vill intet falla till de Chaldeer. Men Jirija ville intet höra honom, utan grep Jeremia, och hade honom bort till Förstarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Och Förstarna vordo vrede uppå Jeremia, och läto slå honom, och kastade honom i fängelse, uti Jonathans, skrifvarens, hus; den samma satte de till stockmästare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Alltså gick Jeremia in uti kulona och fängelset, och låg der i långan tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Och Konung Zedekia sände bort, och lät hemta honom, och frågade honom hemliga i sitt hus, och sade: Är ock något ord på färde af Herranom? Jeremia sade: Ja, ty du skall Konungenom i Babel i händer gifven varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Och Jeremia sade till Konungen Zedekia: Hvad hafver jag brutit emot dig, dina tjenare och detta folk, att de hafva kastat mig i fängelse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Hvar äro nu edra Propheter, som eder spådde, och sade: Konungen i Babel varder intet kommandes öfver eder, eller öfver detta landet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Och nu, min Herre Konung, hör mig och låt mina bön något gälla för dig, och låt mig icke återsändas uti Jonathans, skrifvarens, hus, att jag der dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Då befallde Konung Zedekia, att man skulle bevara Jeremia uti gårdenom för fångahuset, och lät gifva honom om dagen ett bröd af bakarebodene, tilldess allt brödet i stadenom åtgånget var. Alltså, blef då Jeremia uti gårdenom för fångahuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Men Sephatja, Matthans son, och Gedalia, Pashurs son, och Juchal, Selemja son, och Pashur, Malchia son, hörde de orden, som Jeremia till allt folket talade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Detta säger Herren: Den som blifver i denna stadenom, han måste dö för svärd, hunger och pestilentie; men den som utgår till de Chaldeer, han skall blifva lefvandes, och gå af med sitt lif, såsom med ett byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Ty så säger Herren: Denne staden skall gifven varda Konungens här af Babel, och de skola vinna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Då sade Förstarna till Konungen: Låt dock dräpa denna mannen; ty med det sättet afvänder han det krigsfolk, som ännu qvart är i denna stadenom; sammalunda ock allt folket, efter han sådana ord till dem säger; ty den mannen söker icke efter det som folkets bästa är, utan det värsta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Konungen Zedekia sade: Si, han är i edra händer; ty Konungen förmår intet emot eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Då togo de Jeremia, och kastade honom uti Malchia kulo, Hammelechs sons, den på gården för fångahuset var; och släppte honom med tåg neder i kulona, der intet vatten, utan träck, uti var; och Jeremia sank neder i träcken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Då nu EbedMelech, den Ethiopen, en kamererare i Konungshusena, hörde att de hade kastat Jeremia uti kulona, och Konungen satt uti BenJamins port,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Så gick EbedMelech utu Konungshusena, och talade med Konungenom, och sade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Min herre Konung, de män handla illa med Propheten Jeremia, att de hafva kastat honom i kulona, der han må af hunger dö; ty i stadenom är intet bröd mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Då befallde Konungen EbedMelech den Ethiopen, och sade: Tag tretio män med dig af dessa, och tag Propheten Jeremia upp utu kulone, förr än han dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Och EbedMelech tog männerna med sig, och gick uti Konungshuset under fataburen, och tog der gamla och utslitna paltor, och lät dem neder med ett rep till Jeremia i kulona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Och EbedMelech, den Ethiopen, sade till Jeremia: Låt denna gamla och utslitna paltorna under dina armar omkring repet. Och Jeremia gjorde så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Och de drogo Jeremia upp med repena utu kulone, och Jeremia blef så i gårdenom för fångahuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Och Konung Zedekia sände bort, och lät hemta Propheten Jeremia till sig, till den tredje ingången på Herrans hus; och Konungen sade till Jeremia: Jag vill fråga dig något; käre, fördölj intet för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremia sade till Zedekia: Om jag säger dig något, så dräper du mig dock; och om jag gifver dig råd, så lyder du mig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Då svor Konung Zedekia Jeremia hemliga, och sade: Så sant som Herren lefver, den oss denna själena gjort hafver, vill jag icke dräpa dig, eller få dig de män i händer, som efter ditt lif stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Och Jeremia sade till Zedekia: Detta säger Herren Gud Zebaoth, Israels Gud: Om du utgår till Konungens Förstar af Babel, så skall du blifva lefvandes, och denne staden skall icke uppbränd varda, utan du och ditt hus skolen vid lif blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Men om du icke utgår till Konungens Förstar af Babel, så varder denne staden uti de Chaldeers händer gifven, och de skola uppbränna honom i eld, och du skall ej heller undkomma deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Konung Zedekia sade till Jeremia: Jag befruktar mig, att jag må varda gifven de Judar i händer, som till de Chaldeer fallne äro, att de skola bespotta mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Jeremia sade: Man varder dig intet gifvandes; käre, hör dock Herrans röst, den jag dig säger; så skall dig väl gå, och du skall lefvandes blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Men om du icke utgår, så är detta det ord, som Herren mig undervist hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Si, alla de qvinnor, som ännu qvara äro uti Juda Konungs hus, de måste ut till Konungens Förstar af Babel; de samma skola då säga: Ack! dine tröstare hafva bedragit och förfört dig, och fört dig neder i träcken, och låta dig nu ligga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Alltså skola då alla dina hustrur och barn utkomma till de Chaldeer, och du sjelf skall icke kunna undkomma deras händer; utan du skall varda gripen af Konungenom i Babel, och denne staden skall med eld uppbränd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Och Zedekia sade till Jeremia: Si till, att ingen får dessa orden veta, så varder du icke dödad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Och om Förstarna få veta, att jag hafver talat med dig, och de komma till dig, och säga: Säg, hvad hafver du talat med Konungenom? dölj det icke för oss, så vilje vi icke dräpa dig; och hvad hafver Konungen talat med dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Så säg till dem: Jag hafver bedit Konungen, att han icke skall låta mig åter komma uti Jonathans hus igen, att jag icke blifver der död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Då kommo alle Förstarna till Jeremia, och frågade honom; och han sade dem, såsom Konungen honom befallt hade. Så öfvergåfvo de honom, efter de intet kunde förfara af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Och Jeremia blef uti gårdenom för fångahuset, allt intill den dagen då Jerusalem vunnet vardt; och der var han, då Jerusalem vardt vunnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Uti nionde årena Zedekia, Juda Konungs, i tionde månadenom, kom NebucadNezar, Konungen i Babel, och all hans här, för Jerusalem, och belade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Och i ellofte årena Zedekia, på nionde dagen, i fjerde månadenom, föllo de in i staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Och alle Konungens Förstar af Babel droga derin, och höllo i medlersta portenom, nämliga NergalSarEzer, Samgar Nebo, Sarsechim, öfverste kamereraren, NergalSarEzer, hofmästaren, och alle andre Konungens Förstar af Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Som nu Zedekia, Juda Konung, samt med sitt krigsfolk dem såg, flydde de om nattene utu stadenom vid Konungsörtagården, genom den porten emellan de två murar, och drogo bort åt markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Men de Chaldeers här jagade efter dem, och fingo fatt på Zedekia, i den markene vid Jericho, och fångade honom, och förde honom till NebucadNezar, Konungen i Babel, till Riblath, hvilket uti de landena Hamath ligger. Han sade en dom öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Och Konungen i Babel lät dräpa Zedekia barn, för hans ögon, i Riblath, och drap alla Juda Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Men Zedekia lät han stinga ögonen ut, och binda honom med kedjor, att han skulle föra honom till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Och de Chaldeer brände upp både Konungahuset och borgarehusen, och bröto ned murarna i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Men hvad som ännu af folkens qvar i stadenom var, och de som eljest till honom fallne voro, dem förde NebuzarAdan, höfvitsmannen, allasammans fångna till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Men några af det fattiga folket, som intet hade, lät NebuzarAdan, höfvitsmannen, på den tiden qvara blifva i Juda land, och fick dem vingårdar och åkrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Men NebucadNezar, Konungen i Babel, hade befallt NebuzarAdan, höfvitsmannenom, om Jeremia, och sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Tag honom, och rama hans bästa, och gör honom intet ondt, utan såsom han det begärar af dig, så gör med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Då sände NebuzarAdan höfvitsmannen, och Nebusasban öfverste kamereraren, NergalSarEzer hofmästaren, och alle Konungens Förstar i Babel bort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Och läto hemta Jeremia utaf gårdenom för fångahuset, och befallde honom Gedalia, Ahikams sone, Saphans sons, att han skulle hafva honom uti sitt hus, och att han skulle blifva när folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Var ock Herrans ord kommet till Jeremia, medan han ännu i gårdenom för fångahuset fången låg, och hade sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Gack bort, och säg EbedMelech Ethiopenom: Detta säger Herren Zebaoth, Israels Gud: Si, jag skall låta komma min ord öfver denna staden, till olycko, och till intet godt, Och du skall det se på den tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Men dig vill jag fria på den tiden, säger Herren, och skall icke gifva dig dem i händer, som du fruktar dig före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Ty jag skall hjelpa dig derut, så att du icke skall falla genom svärd, utan skall gå af med ditt lif, såsom med ett byte; derföre att du hafver satt dina tröst uppå mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Detta är det ord, som af Herranom skedde till Jeremia, då NebuzarAdan, höfvitsmannen, gaf honom lös i Rama; ty han var ock bunden med kedjor ibland alla dem som i Jerusalem och Juda fångne voro, att man dem till Babel bortföra skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Då nu höfvitsmannen hade låtit hemta Jeremia till sig, sade han till honom: Herren din Gud hafver talat denna olyckona öfver detta rummet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Och Herren hafver också låtit kommat, och gjort som han det sagt hafver; ty I hafven syndat emot Herran, och icke lydt hans röst, derföre är eder sådant vederfaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Nu si, jag hafver i dag gjort dig lös utu kedjorna, der dina händer med bundna voro; lyster dig draga med mig till Babel, så kom, jag vill veta ditt bästa; lyster dig ock icke draga med mig till Babel, så låt det blifva; Si, der hafver du hela landet för dig; hvar dig tycker godt vara och dig behagar, dit gack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Ty fram länger varder ingen omvändning mer; derföre må du vända om igen till Gedalia, Ahikams son, Saphans sons, den Konungen i Babel öfver Juda städer satt hafver, och blifva när honom ibland folket, eller gå bort, dit dig bäst täckes. Och höfvitsmannen gaf honom täring och skänker, och lät honom gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Alltså kom Jeremia till Gedalia, Ahikams son, i Mizpa, och blef när honom ibland folket, som ännu i landena qvart blifvet var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Då nu de höfvitsmän, som i markene lågo, samt med deras folk, fingo veta, att Konungen i Babel hade satt Gedalia, Ahikams son, öfver landet, och både öfver män och qvinnor, barn och de ringesta i landena, som till Babel icke förde voro,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Kommo de till Gedalia i Mizpa, nämliga: Ismael, Nethanja son, Johanan och Jonathan, Kareahs söner, och Seraja, Thanhumeths son, och Ephai söner af Nethophat, och Jesania, Mahachati son, samt med deras män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Och Gedalia, Ahikams son, Saphans sons, gjorde dem och deras män en ed, och sade: Frukter eder intet att vara de Chaldeer underdånige; blifver i landena, och varer Konungenom i Babel underdånige, så varder eder väl gåendes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Si, jag bor här i Mizpa, på det jag skall tjena de Chaldeer, som till oss komma; derföre församler in vin, och fikon, och oljo, och låter det uti edor fat, och bor uti edra städer, som I fått hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Och alle de Judar, som i Moabs land voro, och Ammons barnas, och i Edom, och i all land, då de hörde att Konungen i Babel hade låtit somliga qvara blifva i Juda, och satt Gedalia, Ahikams son, Saphans sons, öfver dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Kommo de alle igen ifrån all rum, dit de hade fördrefne varit, in uti Juda land, till Gedalia i Mizpa, och församlade in ganska mycket vin och fikon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Men Johanan, Kareahs son, samt med alla höfvitsmännerna, som i markene legat hade, kommo till Gedalia i Mizpa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'Och sade till honom: Vetst du ock, att Baalis, Ammons barnas Konung, hafver sändt hit Ismael, Nethanja son, att han skall slå dig ihjäl. Så ville Gedalia, Ahikans son, icke tro dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Då sade Johanan, Kareahs son, till Gedalia hemliga i Mizpa: Käre, jag vill gå bort, och slå Ismael, Nethanja son, ihjäl, så att ingen skall få vetat; hvi skall han slå dig, att alle de Judar, som till dig församlade äro, skola förströdde varda, och de som ännu af Juda qvare blefne äro, förgås?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Men Gedalia, Ahikams son, sade till Johanan, Kareahs son: Det skall du icke göra; det är intet sant, som du om Ismael säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Men i sjunde månadenom kom Ismael, Nethanja son, Elisama sons, af Konungsligo slägt, samt med Konungens öfverstar, och tio män med honom, till Gedalia, Ahikams son, i Mizpa, och der åto de tillhopa med hvarannan i Mizpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Och Ismael, Nethanja son, stod upp, och de tio män som med honom voro, och slogo Gedalia, Ahikams son, Saphans sons, ihjäl med svärd, derföre att Konungen i Babel honom öfver hela landet satt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Dertill slog Ismael alla de Judar, som när Gedalia voro i Mizpa, och de Chaldeer som der funnos, och alla krigsmännerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Den andra dagen derefter, sedan Gedalia son var, och det ännu ingen visste,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Kommo åttatio män af Sichem, af Silo, och Samarien, och hade rakat af skägget, och sönderrifvit sin kläder, och sargat sig, och båro spisoffer och rökelse med sig, att de det skulle offra uti Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Och Ismael, Nethanja son, gick ut ifrå Mizpa emot dem; gick och gret. Som han nu kom till dem, sade han till dem: I skolen komma till Gedalia, Ahikams son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Men då de kommo midt in uti staden, drap dem Ismael, Nethanja son, och de män, som med honom voro, vid brunnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Men der voro tio män ibland, de sade till Ismael: Käre, slå oss icke ihjäl; vi hafve ägodelar i åkrenom, af hvete, bjugg, oljo och hannog. Alltså höll han upp, och drap dem icke med de andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Men brunnen, der Ismael de dödas kroppar uti kastade, som han slagit hade, samt med Gedalia, är den som Konung Asa göra lät emot Baesa, Israels Konung; honom uppfyllde nu Ismael, Nethanja son, med de slagna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Och det folk, som qvart var i Mizpa, och Konungens döttrar, förde Ismael, Nethanja son, bort för fångar, samt med allt det folk som igenlåtet var i Mizpa, öfver hvilka NebuzarAdan, höfvitsmannen, Gedalia, Ahikams son, satt hade, och drog bort, och ville öfver in till Ammons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Men då Johanan, Kareahs son, med alla de höfvitsmän som med honom voro, fingo veta allt det onda, som Ismael, Nethanja son, bedrifvit hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Togo de allt folket till sig, och drogo bort emot Ismael, Nethanja son, till strids, och kommo till honom vid det stora vattnet i Gibeon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Då nu allt folket, som var med Ismael, sågo Johanan, Kareahs son, och alla de höfvitsmän som när honom voro, vordo de glade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Och allt det folk, som Ismael hade bortfört ifrå Mizpa, vände tillbaka, och föllo intill Johanan, Kareahs son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Men Ismael, Nethanja son, undkom Johanan med åtta män, och drog in till Ammons barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Och Johanan, Kareahs son, samt med alla höfvitsmännerna som med honom voro, toga allt det qvarblefna folket (som de igentagit hade ifrån Ismael, Nethanja son) af Mizpa till sig, efter det Gedalia, Ahikams son, slagen var, nämliga krigsmän, qvinnor och barn, och kamererare, som de af Gibeon igenhemtat hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Och droga bortåt, och kommo till herberge till Chimham vid BethLehem, och ville draga in uti Egypten,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'För de Chaldeer; förty de fruktade sig för dem, efter Ismael, Nethanja son, hade dräpit Gedalia, Ahikams son, den Konungen i Babel öfver landet satt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Då trädde fram alle höfvitsmännerna, Johanan, Kareahs son, Jesanja, Hosaja son, samt med allo folkena, både små och stora;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'Och sade till Propheten Jeremia: Käre, låt våra bön något gälla för dig, och bed för oss Herran din Gud, om alla dessa igenlefda; ty, dess värr! vi äre få igenblefne af mångom, såsom du sjelfver oss ser med din ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Att Herren din Gud ville kungöra oss, hvart vi draga, och hvad vi göra skole.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Och Propheten Jeremia sade till dem: Nu väl, jag vill höra eder; och si, jag vill bedja Herran edar Gud, såsom I sagt hafven; och allt det Herren eder svarar, det vill jag kungöra eder, och vill intet dölja undan för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Och de sade till Jeremia: Herren vare ett visst och sant vittne emellan oss, om vi icke göre allt det Herren din Gud genom dig oss befallandes varder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Vare sig godt eller ondt, så vilje vi lyda Herrans vår Guds röst, den vi sände dig till; på det oss må väl gå, då vi Herrans vår Guds röst lyde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Efter tio dagar skedde Herrans ord till Jeremia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Då kallade han Johanan, Kareahs son, och alla höfvitsmännerna, som när honom voro, och allt folket, både små och stora;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'Och sade till dem: Detta säger Herren, Israels Gud, till hvilken I mig sändt hafven, att jag skulle bära edor bön fram för honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Om I blifven i dessa lande, så vill jag uppbygga och icke omkullslå eder; Jag skall plantera och icke upprycka eder; ty det onda, som jag eder gjort hafver, det ångrar mig allaredo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'I skolen väl säkre vara för Konungenom i Babel, den I rädens före, säger Herren; I skolen intet frukta honom; ty jag vill vara när eder, att jag skall hjelpa och frälsa eder ifrå hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Jag skall bevisa eder barmhertighet, och förbarma mig öfver eder, och föra eder uti edart land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Men om I sägen: Vi vilje icke blifva i desso landena; på det I ju icke skolen lyda Herrans edars Guds röst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'Utan sägen: Nej, vi vilje draga in uti Egypti land, på det vi intet örlig se måge, eller höra basuners ljud, och ingen hunger för bröds brists skull lida, der vilje vi blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Nu, så hörer Herrans ord, I qvarblefne af Juda; detta säger Herren Zebaoth, Israels Gud: Om I ställen edor ansigte till att draga in uti Egypten, så att I viljen der blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Så skall svärdet, der I frukten eder före, drabba på eder uti Egypti land; och hungren, den I rädens före, skall allestädes följa eder uti Egypten, och skolen der dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Ty vare sig ho de kunna, som sitt ansigte dit ställa, att de vilja draga in uti Egypten, der till att blifva, de skola dö genom svärd, hunger och pestilentie; och ingen skall qvar blifva, eller undslippa det onda, som jag skall öfver dem komma låta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Ty så säger Herren Zebaoth, Israels Gud: Likasom min vrede och grymhet är gången öfver Jerusalems inbyggare, så skall hon ock gå öfver eder, om I dragen in uti Egypten; på det I skolen varda till bannor, till under, till svärjande, och till skam, och aldrig mer få se detta rummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Herrans ord gäller eder till, I qvarblefne af Juda, att I icke dragen in uti Egypten; derföre veter, att jag i dag betygar eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Eljest sen I edra själar illa före; ty I sänden mig till Herran edar Gud, och saden: Bed Herran vår Gud för oss; och allt det Herren vår Gud sägandes varder, det kungör oss, så vilje vi göra derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Det hafver jag nu i dag låtit eder få veta; men I hafven intet velat höra Herrans edars Guds röst, eller allt det han mig till eder befallt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Så skolen I nu veta, att I genom svärd, hunger och pestilentie, dö måsten, uti det rum, dit I akten att draga, att I der bo skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Då Jeremia all Herrans deras Guds ord till allt folket uttalat hade, såsom Herren deras Gud honom all dessa ord till dem befallt hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Sade Asaria, Hosaja son, och Johanan, Kareahs son, och alle öfverdådige män till Jeremia: Du ljuger; Herren vår Gud hafver intet sändt dig till oss, eller sagt: I skolen icke draga in uti Egypten, till att bo der;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Men Baruch, Neria son, eggar dig emot oss, på det vi skolom de Chaldeer öfvergifne varda, att de skola döda oss, och bortföra oss till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Alltså ville Johanan, Kareahs son, och alle höfvitsmännerna, samt med allo folkena, intet lyda Herrans röst, att de måtte blifvit i Juda lande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Utan Johanan, Kareahs son, och alle höfvitsmännerna togo till sig alla qvarlefda af Juda, de som ifrån all folk dit flydde och igenkomne voro, till att bo i Juda lande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Nämliga män, qvinnor och barn; dertill Konungens döttrar, och alla själar som NebuzarAdan, höfvitsmannen när Gedalia, Ahikams sone, Saphans sons, låtit hade, och Propheten Jeremia, och Baruch, Neria son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Och drogo in uti Egypti land; ty de ville intet höra Herrans röst; och kommo till Thahpanhes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Och Herrans ord skedde till Jeremia i Thahpanhes, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Tag stora stenar, och graf dem neder uti enom tegelugn, som är vid porten åt Pharaos hus i Thahpanhes, så att de män af Juda se deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Och säg till dem: Så säger Herren Zebaoth, Israels Gud: Si jag skall sända bort, och låta hemta min tjenare NebucadNezar, Konungen i Babel, och skall sätta hans stol ofvanuppå dessa stenarna, som jag här nedgräfvit hafver, och han skall slå sin tjäll deröfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Och han skall komma, och slå Egypti land, och dräpa hvem det uppå råkar; för fångar bortföra hvem det uppå råkar; med svärd slå hvem det uppå råkar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Och jag skall tända eld uppå de afgudars hus uti Egypten, att han dem uppbränner och bortförer; och han skall utikläda sig Egypti land, lika som en herde utikläder sig sin mantel, och draga sin väg dädan med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Och han skall sönderslå de belätestodar i BethSemes, i Egypti land, och uppbränna de afgudakyrkor uti Egypten med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Detta är det ord, som till Jeremia, skedde, till alla Judar som uti Egypti land bodde; nämliga i Migdol, i Thahpanhes, i Noph, och de som I det landet Pathros bodde, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Detta säger Herren Zebaoth, Israels Gud: I hafven sett allt det onda, som jag hafver komma låtit öfver Jerusalem, och öfver alla Juda städer, och si, i denna dag äro de öde, och der bor ingen uti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Och det för deras ondskos skull, som de bedrefvo, på det de skulle förtörna mig, och gingo bort, och rökte, och tjente androm gudom, hvilka hvarken de, eller I, eller edre fäder, känden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Och jag sände tidigt till eder alla mina tjenare Propheterna, och lät säga eder: Görer dock icke sådana styggelse, de jag hatar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Men de lydde intet, och böjde ej heller sin öron ifrå sine ondsko, att de måtte omvändt sig, och androm gudom icke rökt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Derföre upptändes ock min vrede och grymhet, och brann öfver Juda städer, och öfver gatorna i Jerusalem, så att de äro förstörde och öde vordne, såsom det i denna dag finnes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Nu, så säger Herren Gud Zebaoth, Israels Gud: Hvi gören I dock detta stora onda emot edart eget lif? på det ibland eder skall utrotad varda både man och qvinna, både barn och spenabarn af Juda, och intet af eder qvart blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Att I så förtörnen mig genom edra händers verk, och röken androm gudom uti Egypti land, dit I dragne ären, till att bo der; på det I skolen utrotade varda, och komma till bannor och försmädelse ibland alla Hedningar på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Hafven I förgätit edra fäders olycko, Juda Konungars olycko, deras hustrurs olycko, dertill edra egna olycko, och edra hustrurs olycko, som vederfaren är uti Juda land, och på gatomen i Jerusalem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Likväl äro de ännu intill denna dag intet ödmjukade, och rädas heller intet; och vandra icke uti min lag och rätter, som jag eder och edra fäder föresatt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Derföre säger Herren Zebaoth, Israels Gud, alltså: Si, jag skall sätta mitt ansigte emot eder till en olycko, och hela Juda skall utrotad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Och jag skall taga de öfverblefna af Juda, som sitt ansigte ställt hafva till att draga in uti Egypti land, och bo der; en ände skall varda med dem allom uti Egypti land; genom svärd skola de falla, och genom hunger skola de förgås, både små och store; de skola dö genom svärd och hunger, och skola varda till ett svärjande, vidunder, bannor och försmädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Jag skall också hemsöka Egypti lands inbyggare med svärd, hunger och pestilentie, lika som jag i Jerusalem gjort hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Så att ingen af Juda återlefvor skall undkomma eller igenblifva, hvilka dock fördenskull hit i Egypti land dragne äro, till att bo här, att de åter måtte komma uti Juda land igen, dit de gerna igenkomma ville, och bo der; men de skola intet komma dit igen, undantagnom dem allena, som hädan fly.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Då svarade alle män, som väl visste att deras hustrur rökte androm gudom, och alla qvinnor, som der i en stor hop stodo, samt med allo folkena, som uti Egypti land och i Pathros bodde, och sade till Jeremia:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Efter det ord, som du oss säger i Herrans Namn, vilje vi intet höra dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Utan vi vilje göra efter allt det ord, som utaf vårom mun går, och vilje röka himmelens Drottning, och offra henne drickoffer, såsom vi och våre fäder, våre Konungar och Förstar, gjort hafva i Juda städer, och uppå gatomen i Jerusalem; då hade vi ock bröd nog, och oss gick väl, och sågom ingen olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Men sedan vi återvände att röka himmelens Drottning, och offra henne drickoffer, hafve vi alla vedermödo lidit, och äre genom svärd och hunger förgångne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Och om vi än röke himmelens Drottning, och drickoffer offre, det göre vi ju icke utan våra mäns vilja, att vi bake henne kakor, och drickoffer offre till hennes tjenst?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Då sade Jeremia till allt folket, både män, qvinnor och allt folket, som honom så svarat hade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Ja, jag menar ock, att Herren hafver tänkt uppå det rökande, som I uti Juda städer och på Jerusalems gator bedrifvit hafven, samt med edra fäder, Konungar, Förstar, och allt folket i landena, och hafver lagt det uppå hjertat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Så att Herren icke mer lida kunde edart onda väsende och styggelse, som I gjorden; derföre ock edart land är vordet till öde, vidunder, och till bannor, så att der ingen inne bor, såsom det i denna dag tillgår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Derföre att I rökten, och emot Herran syndaden, och icke lydden Herrans röst, och vandraden i hans lag, rätter och vittnesbörder; fördenskull är eder ock sådana olycka vederfaren, såsom det i denna dag befinnes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Och Jeremia sade till allt folket, och till alla qvinnorna: Hörer Herrans ord, alle I af Juda, som uti Egypti land ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Detta, säger Herren Zebaoth, Israels Gud: I och edra qvinnor hafva med edrom mun talat, och med edra händer fullkomnat det I saden: Vi vilje hålla vår löfte, som vi himmelens Drottning lofvat hafve, att vi henne röke, och drickoffer offre; nu väl, I hafven hållit edart löfte, och fullföljt det med gerningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Så hörer nu Herrans ord, I alle af Juda, I som bon uti Egypti land; si, jag svär vid mitt stora Namn, säger Herren, att mitt Namn icke mer skall, genom någors mans munn af Juda, uti hela Egypti land nämndt varda, den der säger: Så visst som Herren Herren lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Si, jag vill vaka öfver dem till ondt, och intet godt, så att ho som af Juda uti Egypti land är, han skall genom svärd och hunger förgås, tilldess att det hafver en ända med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Men de som svärdet undkomma, de skola likväl komma utur Egypti land in uti Juda. land igen, med en liten hop; och alltså skola då alle de öfverblefne af Juda, som in uti Egypti land dragne voro, till att bo der, förnimma, hvilkens ord sant vordet är, mitt eller deras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Och detta skall vara till ett tecken, säger Herren, att jag eder i desso rummena hemsöka vill, på det I skolen veta, att min ord skola sann varda öfver eder till olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Så säger Herren: Si, jag skall öfvergifva Pharao Hophra, Konungen i Egypten, uti hans fiendars händer, och deras som efter hans lif stå, likasom jag Zedekia, Juda Konung, öfvergifvit hafver uti NebucadNezars, Konungens i Babel, hans fiendas, hand, och den efter hans lif stod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Detta är det ord, som Propheten Jeremia talade till Baruch, Neria son, då han dessa orden skref i ene bok, utaf Jeremia mun, uti fjerde årena Jojakims, Josia sons, Juda Konungs, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Detta säger Herren, Israels Gud, om dig, Baruch:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Du sade: Ve mig, huru hafver Herren fogat mig jämmer till uppå min värk; jag suckar mig tröttan, och finner ingen ro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Säg honom alltså: Så säger Herren: Si, det jag uppbyggt hafver, det bryter jag neder, och det jag planterat hafver, det upprycker jag, samt med allt detta mitt eget land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Och du begärar dig stor ting? Begära det intet; ty Si, jag vill låta olycko komma öfver allt kött, säger Herren; men dina själ vill jag gifva dig till ett byte, ehvart du drager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Detta är Herrans ord, som till Propheten Jeremia skedde emot alla Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Emot Egypten. Emot Pharao Necho här, Konungens i Egypten, hvilken låg vid den älfven Phrath i Charchemis, den NebucadNezar, Konungen i Babel, slog, uti fjerde årena Jojakims, Josia, sons, Juda Konungs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Reder till sköld och spjut, och drager ut till slags.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Spänner hästar före, och låter resenärer stiga till häst; sätter hjelmar uppå, och hvässer spjut, och drager pansare uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Men huru kommer det till, jag ser att de äro förtviflade, och gifva flykt, och deras hjeltar slagne äro? De fly, så att de intet se sig om; förskräckelse är på alla sidor, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Den raske kan icke undfly, eller den starke undkomma; norrut vid den älfven Phrath äro de fallne och nederlagde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Hvar är nu den som hit uppdrog såsom en ström, och hans böljor upplyfte sig såsom i älfvene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egypten drog upp såsom en ström, och hans böljor upplyfte sig såsom i älfvene, och sade: Jag vill draga upp, och öfvertäcka landet, och förderfva staden, samt med dem som bo derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Nu väl, sitter upp på hästarna; ruller åstad med vagnarna; låter de hjeltar utdraga; de Ethioper och utaf Libyen, som sköld föra; och de skyttar af Lydien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Ty detta är Herrans Herrans Zebaoths dag, en hämndadag, att han skall hämnas öfver sina fiendar; svärdet skall fräta, och af deras blod fullt och drucket varda; ty de måste varda Herranom Herranom Zebaoth ett slagtoffer, i nordlanden vid den älfvena Phrath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Gack upp till Gilead, och hemta salvo, du jungfru dotter utur Egypten; men det är fåfängt, att du mycken läkedom brukar, du varder dock intet helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Din skam är ibland Hedningarna kunnig vorden; af ditt jämrande är landet fullt; ty den ene hjelten faller öfver den andra, och ligga både tillsammans omkull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Detta är Herrans ord, som han talade till Propheten Jeremia, då NebucadNezar, Konungen i Babel, åstad drog, till att slå Egypti land:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Förkunner det uti Egypten, och säger till uti Migdal; låter hörat i Noph och Thahpanhes, och säger: Ställ dig till värn; ty svärdet skall uppfräta allt det omkring dig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Huru går det till, att dine väldige falla till markena, och kunna icke blifva ståndande? Herren hafver så stört dem omkull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Han gör det, att månge af dem falla, att den ene med den andra omkull ligger. Så sade de: Upp, låter oss draga till vårt folk uti vårt fädernesland igen, för tyrannens svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Det samma rope man efter dem: Pharao, Konungen i Egypten, ligger; han hafver öfvergifvit sin tjäll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Så sant som jag lefver, säger den Konungen, som Herren Zebaoth heter: Han skall komma farandes så hög som det berget Thabor ibland bergen är, och lika som Carmel vid hafvet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Skicka dig till att färdas, du inbyggerska, dotter Egypten; ty Noph skall varda öde, och uppbrändt, så att ingen skall bo deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Egypten är en ganska skön kalf; men slagtaren kommer nordanefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Och de då dagakarlar, som bo derinne, äro ock såsom gödde kalfvar; men de måste dock likväl vända om, varda alle tillsammans flyktige, och skola intet kunna bestå; ty deras o1yckos dag skall öfver dem komma, nämliga deras hemsöknings tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'De komma så att en gny går af harnesket, och komma med härskraft, och föra yxer öfver dem såsom vedahuggare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'De samme skola så hugga uti deras skog, säger Herren, att det skall intet kunna räknas; ty de äro flere än gräshoppor, de ingen räkna kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Dottren Egypten står med skam; ty hon är thy nordländsko folkena i händer gifven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Herren Zebaoth, Israels Gud, säger: Si, jag vill hemsöka det ämbetes folk i No, och Pharao och Egypten, samt med sina gudar och Konungar; ja, Pharao, med alla de som förlåta sig uppå honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Så att jag skall gifva dem i deras händer, som efter deras lif stå, och uti NebucadNezars, Konungens i Babel, och hans tjenares händer; och sedan skall du besitten varda, lika som i förtiden, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Men du, min tjenare Jacob, frukta dig intet, och du Israel, förtvifla intet; ty si, jag skall hjelpa dig fjerranefter, och dina säd utu sins fängelses lande, så att Jacob skall igenkomma, och vara i frid, och hafva nog, och ingen skall förskräcka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Derföre frukta dig intet, du Jacob, min tjenare, säger Herren; ty jag är när dig. Med allom Hedningom, dit jag dig fördrifvit hafver, skall jag en ända göra; men på dig vill jag icke göra en ända, utan skall näpsa dig med måttelighet, på det jag icke skall låta dig blifva ostraffad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Detta är Herrans ord, som skedde till Propheten Jeremia, emot de Philisteer, förr än Pharao slog Gaza.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Så säger Herren: Si, vatten skola uppkomma nordanefter, hvilka en flod göra skola, så att både landet och hvad deruppå är, och städerna, med dem som deruti bo, skola sin väg drifva; och menniskorna skola ropa, och alle landsens inbyggare jämra sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'För den gnys skull af deras starka hästar, som der löpa, och för det buller af deras vagnar, och deras hjuls slamrande, så att fäderna icke skola se sig om efter barnen, så förtviflade skola de vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'För den dagen, som kommer till att förstöra, alla Philisteer, och utrota Tyrus och Zidon, samt med andra deras hjelpare; ty Herren skall förstöra de Philisteer, och de öar Caphtor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Gaza skall skallot varda, och Askelon, samt med de igenlefda, uti deras dalar förderfvas; huru länge vill du örliga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'O! du Herrans svärd, när vill du dock hålla upp? Far dock uti dina skido, och hvila dig, och var stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Men huru kan du uppehålla, medan Herren hafver gifvit dig befallning emot Askelon, och ställt dig emot hamnarna vid hafvet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Emot Moab. Så säger Herren Zebaoth, Israels Gud: Ve dem stadenom Nebo; ty han är förstörd, och ligger ömkeliga; Kiriathaim är vunnen, fästet står ömkeliga, och är nederrifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Moabs tröst är ute, den han af Hesbon hade; ty man hafver något ondt i tankanom emot honom, nämliga: Kommer, vi vilje utrota honom, att han intet folk mer vara skall; och du, Madmen, måste ock förderfvad varda, svärdet skall efter dig komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Man hörer ett rop i Horonaim, om förderfvelse och stor jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab är nederslagen; man hörer hans unga barn ropa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Ty de gå gråtande den vägen upp åt Luhit, och fienderna höra ett Jämmerrop på den vägen neder ifrå Horonaim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Nämliga: Skynder eder bort, och undsätter edart lif; men du skall vara såsom ljung i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Derföre, att du förlätst dig uppå dina byggning, och uppå dina håfvor, skall du ock vunnen varda. Och Chemos måste ut, och draga sin väg fången, samt med sina Prester och Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Ty förderfvaren skall komma öfver alla städerna, att icke en stad undslippa skall; der skola både dalarna förderfvas, och slättmarken förstörd varda; ty Herren hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Käre, låter Moab blomstras; han skall utblomstrat hafva, och hans städer skola öde ligga, att der ingen uti bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Förbannad vare den som Herrans verk gör försummeliga; förbannad vare den som sitt svärd upphåller, att det intet blod utgjuter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moab hafver af sinom ungdom varit säker, och hafver på sine drägg stilla legat, och hafver icke någon tid varit ugjuten af det ena fatet uti det andra, och icke någon tid bortfarit uti fängelse; derföre är honom hans smak qvarblifven, och hans lukt hafver intet förvandlat sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Derföre, si, säger Herren, den tiden kommer, att jag skall sända honom uttappare, som honom uttappa skola, och göra hans fat tom, och sönderslå, hans läglar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Och Moab skall öfver Chemos till skam varda, lika som Israels hus öfver BethEl till skam vordet är, der de dock förläto sig uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Huru djerfvens I säga: Vi äre hjeltar och de rätte krigsmän;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Ändock Moab måste förstörd varda, och hans städer bestegne, och hans bäste män måste nedergå till att dräpas? säger Konungen, som heter Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Ty Moabs ofärd varder snart kommandes, och hans olycka skall väl hasta sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Käre, hafver dock medlidande med honom, I som omkring honom bon, och hans namn kännen, och sägen: Huru är det starka riset och den härlige stafven så sönderbruten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Stig neder af härlighetene, du dotter som i Dibon bor, och sätt dig på det torra; ty Moabs föfderfvare skall komma upp till dig, och sönderbryta din fäste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Gack in på vägen, och se till, du inbyggerska i Aroer; fråga dem som flydde och undsluppne äro, och säg: Huru går det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Ack! Moab är förödd och förderfvad; jämrer eder, och roper, förkunner det i Arnon, att Moab förderfvad är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Straffet är gånget öfver slättmarkena, nämliga öfver Holon, Jahza, Mephaath,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Dibon, Nebo, BethDiblathaim,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Kiriathaim, BethGamul, BethMeon,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Kirioth, Bozra, och öfver alla de städer i Moabs land, ehvad de ligga fjerran eller när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Moabs horn är afhugget, och hans arm är sönderbruten, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Gör honom drucknan, ty han hafver upphäfvit sig emot Herran, att han må spy sig, och vrida händerna, på det han ock må till spott varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Ty Israel hafver varit ditt gabberi, lika som han hade varit funnen ibland tjufvar; och efter du sådant emot honom talat hafver, måste du ock bortföras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'O! I Moabs inbyggare, öfvergifver städerna, och bor uti bergklippomen, och görer likasom dufvorna, som bo högt upp i hålen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Man hafver ju alltid sagt om den stolta Moab, att han fast stolt är, högfärdig, högmodig, trotsig och storsinnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Men Herren säger: Jag känner väl hans vrede, att han icke så mycket förmår, och tager sig före att göra mer än i hans magt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Derföre måste jag jämra mig öfver Moab, och ropa öfver hela Moab, och sörja öfver det folk i Kirheres.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Jag måste gråta öfver dig, Jaeser, du vingård i Sibma; ty dine vinqvistar äro farne öfver hafvet, och komne intill Jaesers haf; förderfvaren är fallen in uti dina säd och vinhemtning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Fröjd och glädje är borto af markene, och af Moabs land, och man skall intet vin mer pressa der, vintramparen skall intet; mer sjunga sina viso,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'För det ropets skull i Hesbon, allt in till Eleale, hvilket man hörer intill Jahza, ifrå Zoar den treggaårs kona, intill Horonaim; ty Nimrims vatten skola ock uttorkas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Och jag skall, säger Herren, i Moab dermed en ända göra, att de icke mer skola offra på höjderna, och röka sinom gudom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Derföre ryter mitt hjerta öfver Moab, lika som en trummete, och öfver det folk i Kirheres ryter mitt hjerta, såsom en trummete; ty de hafva fast förtagit sig, derföre måste de förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'All hufvud skola varda kullot, och allt skägg afrakadt; alla händer skola refna varda, och hvar man skall draga säcker uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'På all tak och gator allestäds i Moab skall man gråta; ty Jag hafver sönderslagit Moab, likasom ett onyttigt fat, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'O! huru är han förderfvad, hum jämrar han sig, huru skamliga hänger han hufvudet; och Moab är vorden till spott och till en förskräckelse allom dem som deromkring bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Ty så säger Herren: Si, han flyger bortåt, såsom en örn, och uträcker sina vingar öfver Moab.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kiriath är vunnen, och de fasta städer äro intagne, och de hjeltars hjerta i Moab skall på den tiden vara lika som ene qvinnos hjerta i barnsnöd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Ty Moab måste förderfvad varda, så att han intet folk mer vara skall, derföre att han hafver förhäfvit sig emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Fruktan, kula och snara kommer öfver dig, du inbyggare i Moab, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Den som fruktan undkommer, han skall falla uti kulona, och den utu kulone kommer, han skall varda fången i snarone; då skall jag låta komma öfver Moab hans hemsöknings år, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'De som undlöpa utu slagtningene, skola söka tillflykt i Hesbon; men en eld skall gå utaf Hesbon, och en låge utaf Sihon, hvilken de rum i Moab och det stridsamma folket förtära skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Ve dig, Moab, förloradt är Chemos folk; ty man hafver tagit dina söner och döttrar, och fört dem bort fångna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Men uti tillkommande tid skall jag omvända Moabs fängelse, säger Herren. Det vare nu sagdt om straffet öfver Moab.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Emot Ammons barn säger Herren alltså: Hafver nu Israel inga barn, eller hafver han inga arfvingar? Hvi besitter då Malcham Gads land, och hans folk bor i hans städer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Derföre, si; den tiden kommer, säger Herren, att jag skall låta, höra ett krigsskri öfver Rabbath, Ammons barnas, att det skall öde ligga uti en hop, och dess döttrar med eld uppbrända varda; men Israel skall besitta dem, af hvilkom de hafva besuttne varit, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Jämra dig, o Hesbon, ty Aj är förstörd; roper, I Rabba döttrar, och drager säcker uppå, gråter och löper omkring på murarna; ty Malcham varder fången bortförd, samt med sina Prester och Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Hvad trotsar du uppå dina dalar? Dine dalar äro fördränkte, du ohörsamma dotter, som förlåter dig uppå dina rikedomar, och säger i ditt hjerta: Ho tör komma till mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Si detta säger Herren Herren Zebaoth: Jag skall låta komma en fruktan öfver dig, af allom dem som kring dig bo, så att hvar och en skall på sin väg bortdrifven varda, ifrå den andra, och ingen skall vara den som de flyktiga församlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Men derefter skall jag omvända Ammons barnas fängelse, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Emot Edom. Detta säger Herren Zebaoth: Är nu ingen vishet mer i Theman? Är nu intet råd mer när barnen? Är deras vishet ute?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Flyr, vänder eder om, och gömmer eder djupt neder, I borgare i Dedan; ty jag låter en ofärd komma öfver Esau, hans hemsöknings tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Vinhemtare skola komma öfver dig, de der intet skola lefva dig efter sig, och tjufvar om nattena skola komma öfver dig, de skola stjäla sig nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Ty jag hafver blottat Esau, och uppenbarat hans hemlig rum, så att han kan icke undstinga sig; hans säd, hans bröder, och hans grannar äro förstörde, att ingen af dem mer för handene är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Dock hvad der qvart blifver af dina faderlösa, dem vill jag lifvet unna, och dina enkor skola hoppas uppå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Ty så säger Herren: Si, de som intet förskyllt hafva att dricka kalken, de måste drickan, och du skulle ostraffad blifva? Du skall intet ostraffad blifva; utan du måste ock drickan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Ty jag hafver svorit vid mig sjelf, säger Herren, att Bozra skall vara till ett vidunder, försmädelse, förödning och bannor, och alle hans städer till ett evigt öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Jag hafver hört af Herranom, att ett bådskap är sändt till Hedningarna: Församler eder, och kommer hit emot honom, och strider.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Ty si, jag hafver förnedrat dig ibland Hedningarna, och förakteligan gjort ibland menniskorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Din öfverdådighet och dins hjertans högmod hafver bedragit dig, efter du bor i bergklyftor, ock hafver hög berg inne; om du ditt näste så högt gjorde som en örn, så skall jag ändå likväl störta dig der neder, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Alltså skall Edom öde varda, att allo de der framom gå, skola förundra sig, och hvissla öfver alla hans plågor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Likasom Sodoma och Gomorra, samt med sina grannar, omstört är, säger Herren, så att ingen bor der, eller någor menniska derinne blifva kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Ty si, han kommer upp lika som ett lejon ifrå den stolta Jordan, emot de fasta hyddor; ty jag vill låta honom snarliga löpa dit; och ho vet, hvilken den ynglingen är, den jag emot dem rusta skall? Ty ho är mig lik, ho vill lära mig? Och hvilken är den herden, som mig emotstå kan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Så hörer nu Herrans rådslag, som han öfver Edom hafver, och hans tankar, som han öfver Themans inbyggare hafver: Hvad gäller, att vallebarnen skola bortsläpa dem, och förstöra deras boning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Så att jorden skall bäfva i deras fall, och deras rop skall man höra på röda hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Si, han flyger upp såsom en örn, och skall uträcka sina vingar öfver Bozra; på den tiden skall de hjeltars hjerta i Edom vara lika som ene qvinnos hjerta i barnsnöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Emot Damascon. Hamath och Arpad stå jämmerliga, de äro förtviflade; ty de höra ond tidende: De som vid hafvet bo äro förskräckte, så att de kunna ingen ro hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damascus är förtviflad, och gifver flyktena; han darrar, och är i ångest och värk, likasom en qvinna i barnsnöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Huru? Är han nu icke öfvergifven, den beprisade och säkre staden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Derföre skola hans unge män ligga på hans gator, och alle hans krigsmän falla på den tiden, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Och jag skall sticka eld på murarna i Damascon, att han Benhadads palats upptära skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Emot Kedar och Hazors riken, hvilka NebucadNezar, Konungen i Babel, slog. Detta säger Herren: Upp, drager upp till Kedar, och förstörer de barn österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Man skall taga dem deras hyddor och hjordar bort, deras tjäll och all deras tyg; och cameler skola de bortföra, och man skall förskräckeliga ropa öfver dem allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Flyr, låter lida eder dädan, gömmer eder djupt neder, I inbyggare i Hazor, säger Herren; ty NebucadNezar, Konungen i Babel, hafver rådslagit om eder, och hafver något i sinnet emot eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Nu upp, drager upp emot ett folk, som nog hafver, och bor säkert, säger Herren; de hafva hvarken portar eller bommar, och de bo allena för sig,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Deras cameler skola bortröfvade varda, och deras myckna boskap borttagen; och jag skall förströ dem i alla väder, de der i vråar bo; och på alla sidor skall jag låta deras olycka komma öfver dem, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Och Hazor skall varda till en drakaboning, och till ett evigt öde, så att der ingen bo skall, och ingen menniska deruti vistas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Detta är Herrans ord, som skedde till Jeremia Propheten, emot Elam, uti Zedekia, Juda Konungs rikes begynnelse, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Så säger Herren Zebaoth: Si, jag skall sönderbryta Elams båga, deras yppersta magt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Och skall låta komma öfver dem de fyra väder, utaf fyra himmelens ändar, och skall förströ dem uti all de vädren, att intet folk vara skall, dit icke ju någre fördrefne af Elam komma skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Och jag skall göra Elam förtviflad för deras fiendar, och för dem som stå efter deras lif, och låta olycko komma öfver dem med mine grymma vrede, säger Herren; och skall sända svärdet efter dem, tilldess jag gör en ända uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Min stol skall jag sätta i Elam, och skall förgöra der både Konung och Förstar, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Men i tillkommande tid skall jag vända Elams fängelse om igen, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Detta är det ord som Herren, genom Propheten Jeremia, talat hafver emot Babel, och de Chaldeers land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Förkunner ibland Hedningarna, och låter det kunnigt varda; reser ett baner upp, utroper det, och fördöljer det icke, och säger: Babel är vunnen, Bel står med skam, Merodach är sönderkrossad, hans afgudar äro till skam vordne, och hans gudar äro sönderslagne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Ty nordanefter skall uppkomma ett folk emot dem; det skall göra deras land öde, så att ingen skall bo deruti, utan både folk och fä, dädan fly.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Uti de dagar, och i den tiden, säger Herren, skola Israels barn, samt med Juda barn, komma, och skola gå och gråta, och söka Herran sin Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'De skola fråga efter den vägen åt Zion, och vända sig dit: Kommer, och vi vilje hålla oss intill Herran med ett evigt förbund, det aldrig skall förgätet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Ty mitt folk är vordet likasom en borttappad hjord; deras herdar hafva förfört dem, och låtit dem villo gå på bergomen, så att de ifrå berg till högar gångne äro, och hafva förgätit sina hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Allt det som till dem kom, det uppåt dem; och deras fiender sade: Vi göre intet orätt; ty de hafva syndat emot Herran, uti rättfärdighetenes boning, och emot Herran, som deras fäders hopp är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Flyr utu Babel, och drager utu Chaldee land, och skicker eder såsom bockar framför hjorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Ty si, jag skall uppväcka stor folk med hopom utu nordlandet, och låta dem uppkomma inför Babel; de skola rusta sig emot honom, och skola vinna honom; deras pilar äro likasom en god krigsmans, den intet misto skjuter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Och Chaldee land skall varda till ett rof, så att alle de, som röfva det, skola der nog af hafva, säger Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Derföre, att I glädjens deraf och berömmen eder, att I min arfvedel skinnat hafven, och springen likasom kåta kalfvar, och vrenskens likasom starka hästar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Edor moder står med stor skam, och den eder födt hafver, är till spott vorden; si, ibland Hedningarna är hon den aldraringasta, öfvergifven, torr och öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Ty för Herrans vredes skull måste han obyggd och allstinges öde ligga, så att alle de, som framgå om Babel, skola förundra sig, och hvissla öfver alla hans plågor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Ruster eder emot Babel allt omkring, alle skyttar; skjuter till honom, sparar icke pilarna; ty han hafver syndat emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Skrier öfver honom allt omkring; han måste gifva sig; hans grundvalar äro fallne, hans murar äro afbrutne; ty det är Herrans hämnd. Hämnens öfver honom, görer honom lika som han gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Utroter af Babel både den der sår, och den der uppskär, att hvar och en för tyrannens svärd vänder sig till sitt folk, och hvar och en flyr uti sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israel hafver måst vara en förströdd hjord, hvilken lejonen förskingrat hafva: Först uppåt honom Konungen i Assyrien; sedan förderfvade honom NebucadNezar, Konungen i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Derföre säger Herren Zebaoth, Israels Gud, alltså: Si, jag skall hemsöka Konungen af Babel, och hans land, likasom jag Konungen af Assyrien hemsökt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Men Israel skall jag låta komma hem till sin boning igen, att han skall föds sig i Carmel och Basan; och på Ephraims berg och Gilead skall hans själ mättad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'I den tiden och i de dagar skall man söka efter Israels missgerning, säger Herren, men man skall ingen finna; och Juda synd, och der skall ingen funnen varda; ty jag skall se utöfver med dem som jag igenblifva låter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Drag upp emot det land, som hela verldena trugat hafver, drag ditupp, och hemsök inbyggarena; förhärja och förspill deras efterkommande, säger Herren, och gör allt det jag dig befallt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Det är ett krigsrop i landena, och stor jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Huru går det till, att alla verldenes hammar sönderbruten och sönderslagen är? Huru går det till, att Babel ett öde vorden är ibland alla Hedningar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Jag hafver gildrat för dig, Babel, derföre äst du ock fången, förr än du dess försåg dig; man hafver råkat uppå dig, och du äst gripen; ty du hafver rett Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Herren hafver upplåtit sin fatabur, och haft fram sine vredes vapen; ty sådant hafver Herren, Herren Zebaoth uti de Chaldeers land beställt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Kommer hit emot honom, I ifrån ändanom, öppner hans kornhus; kaster honom uti en hop, och gifver honom till spillo, så att der intet qvart blifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Dräper all hans barn, hafver dem ned till att slagtas; ve dem, ty dagen är kommen, deras hemsöknings tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Man hörer ett rop af de flyktiga, och af de som undsluppne äro utu Babels land; på det de skola förkunna i Zion Herrans vår Guds hämnd, och hans tempels hämnd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Kaller många emot Babel; belägger honom allt omkring, alle bågaskyttar, och låter ingen undslippa; vedergäller honom såsom han förtjent hafver; lika som han gjort hafver, så görer honom igen; ty han hafver högmodeliga handlat emot Herran, den Heliga i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Derföre skola hans unge män falla uppå hans gator, och alle hans krigsmän förgås på den tiden, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Si, du stolte, jag vill till dig, säger Herren, Herren Zebaoth; ty din dag är kommen, dine hemsöknings tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Då skall den stolte störta och falla, så att ingen skall upprätta honom; jag skall upptända hans städer med eld, den upptära skall allt det deromkring är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Detta säger Herren Zebaoth: Si, Israels barn, samt med Juda barn, måste våld och orätt lida; alle de som dem för fångar bortfört hafva, de hålla dem, och vilja icke gifva dem lös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Men deras förlossare är stark, han heter Herren Zebaoth, han skall så uträtta deras sak, att han skall göra landet bäfvande, och inbyggarena i Babel darrande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Svärdet skall komma, säger Herren, öfver de Chaldeer, och öfver de inbyggare i Babel, och öfver hans Förstar, och öfver hans visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Svärdet skall komma öfver hans spåmän, att de skola till dårar varda; svärdet skall komma öfver hans starka, att de skola förtvifla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Svärdet skall komma öfver hans hästar och vagnar, och till alla menighetena, som derinne är, så att de skola varda såsom qvinnor; svärdet skall komma öfver hans fatabur, att han skall sköflad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Torka skall komma öfver hans vatten, att det skall uttorkas; ty det är ett afgudaland, och de trotsa uppå sina stygga afgudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Derföre skola odjur och stygge foglar bo derinne, och unge strutser; och skall aldrig mer besutten varda, eller någon derinne vistas i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Likasom Gud Sodom och Gomorra, samt med deras grannar, omstört hafver, säger Herren, att der ingen uti bo skall, eller någor menniska derinne vistas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Si, ett folk kommer nordanefter; månge Hedningar och månge Konungar skola uppresa sig ifrå landsens sido.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'De hafva båga och sköld, de äro grufvelige och obarmhertige; deras rop är såsom en dön af hafvet; de rida på hästar, rustade såsom krigsmän, emot dig, du dotter Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'När Konungen i Babel deras rykte hörandes varder, då skall honom händer nederfalla; ångest och sorg skall honom uppåkomma, likasom ene qvinno uti barnsnöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Si, han kommer upp, såsom ett lejon, ifrå den stolta Jordan, emot de fasta hyddor; ty jag skall låta honom hasteliga löpa dit, och ho vet hvilken den ynglingen är, den jag emot dem rusta skall? Ty ho är min like, ho vill lära mig? Och hvilken är den herden, som emot mig stå kan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Så hörer nu Herrans rådslag, det han öfver Babel hafver, och hans tankar, som han öfver de inbyggare uti de Chaldeers land hafver: Hvad gäller, att vallebarnen skola bortsläpa dem, och förstöra deras boning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Och jorden skall bäfva af det skriet, och skall ibland Hedningarna spordt varda, då Babel vunnen varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Detta säger Herren: Si, jag skall uppväcka ett skarpt väder emot Babel, och emot hans inbyggare, som sig emot mig satt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Jag skall sända kastare till Babel, hvilka honom kasta skola, och utsopa hans land; desse skola vara allstädes omkring honom, på hans olyckos dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Ty hans skyttar skola intet kunna skjuta, och hans väpnade skola intet kunna värja sig; så skoner nu intet hans unga män, gifver all hans här till spillo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Så att de slagne ligga uti de Chaldeers land, och de genomstungne på hans gator.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Ty Israel och Juda skola icke öfvergifne varda af Herranom Zebaoth, deras Gud, såsom enkor; ändock deras land hafver högeliga förbrutit sig uppå den Heliga i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Flyr utaf Babel, på det hvar och en må undsätta sina själ, att I icke förgås uti hans ondsko; ty detta är Herrans hämndatid, och han vill betala honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Den gyldene kalken i Babel, som alla verldena hafver druckna gjort, är uti Herrans hand; alle Hedningar hafva druckit af hans vin, derföre äro Hedningarna så galne vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Huru hasteliga är Babel fallen och sönderslagen; jämrer eder öfver honom; tager ock salvo till hans sår, om han tilläfventyrs måtte helad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Vi läke Babel; men han vill intet läkt varda; så låter nu fara honom, och låt oss hvar och en draga uti sitt land; ty hans straff räcker allt upp till himmelen, och sträcker sig upp till skyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Herren hafver framhaft våra rättfärdighet; kommer och låter oss förtälja Herrans vår Guds verk i Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Ja, hvässer nu pilarna väl, och tillreder sköldarna. Herren hafver uppväckt Konungarnas mod i Meden; ty hans tankar stå emot Babel, att han skall förderfva honom; ty detta är Herrans hämnd, hans tempels hämnd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Ja, reser nu baner upp på murarna i Babel, skicker vakt, sätter väktare, beställer håll; ty Herren tänker något, och skall desslikes fullfölja det han emot Babels inbyggare talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Du som vill stor vatten bor, och stora rikedomar hafver, din ände är kommen, och din girighet är ute;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Herren Zebaoth hafver svorit vid sina själ: Jag skall uppfylla dig med menniskor, likasom med gräsmatkar, de skola sjunga dig ena viso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Den som jordena, genom sin kraft, gjort hafver, och beredde verldenes krets genom sina vishet, och himmelen skickeliga utsträckte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Då han dundrar, så varder under himmelen mycket vatten, han uppdrager moln ifrå jordenes ända; han gör ljungeld i regnena, och låter vädret komma utu hemlig rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Alla menniskor äro dårar med sine konst, och alle guldsmeder bestå med skam med sin beläte; ty deras beläte äro bedrägeri, och hafva intet lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'De äro icke annat än fåfängelighet och förförisk verk; de måste förgås, då de hemsökte varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Men så är icke han, som Jacobs del är, utan han, som all ting gör, den äret, och Israel är hans arfs staf; Herren Zebaoth är hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Du äst min hammar och krigsvapen, genom dig skall jag slå folk och förderfva riken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Jag skall slå dina hästar och resenärer, jag skall sönderslå dina vagnar och deras foromän;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Jag skall slå dina män och qvinnor; jag skall slå dina gamla och dina ynglingar; jag skall slå dräng och pigo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Jag skall slå din herda och hjord; jag skall slå dina åkermän och ok; jag skall slå dina Förstar och herrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Ty jag vill vedergälla Babel, och allom Chaldeers inbyggarom, alla deras ondsko, som de uppå Zion bedrifvit hafva, för edor ögon, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Si, jag skall till dig, du skadeliga berg, som hela verldena förderfvar, säger Herren; jag skall sträcka mina hand öfver dig, och välta dig neder af bergena, och göra ett förbrändt berg af dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Att man af dig hvarken hörnstenar eller grundstenar taga kan; utan ett evigt öde skall du vara, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Reser upp baner i landena, blåser med basun ibland Hedningarna, ruster Hedningarna emot honom, kaller emot honom de Konungarike Ararat, Minni och Ascenas, beställer höfvitsmän emot honom, hafver hästar fram, likasom snorrande bromser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Ruster Hedningarna emot honom, nämliga Konungarna af Meden, samt med deras Förstar och herrar, och allt deras väldes land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Och landet skall bäfva och förskräckas; förty Herrans tankar vilja fullkomnade varda emot Babel, att han gör Babels land till ett öde, der ingen uti bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'De hjeltar i Babel skola icke töra draga ut till strids, utan blifva på fästen; deras starkhet är borto, och äro vordne såsom qvinnor; hans boningar äro upptände, och hans bommar sönderbrutne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Här löper den ene om den andra, och det ena bådskapet möter thy andro, till att kungöra Konungenom i Babel, att hans stad vunnen är allt intill ändan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Och hamnarna intagna, och sjöarna utbrände, och krigsfolket blödigt vordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Ty detta säger Herren Zebaoth, Israels Gud: Dottren Babel är såsom en tröskeloge, när man derpå tröskar; hennes skördeand varder snart kommandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'NebucadNezar, Konungen i Babel, hafver uppfrätit mig, och omstört mig; han hafver gjort ett tomt käril af mig; han hafver uppslukat mig likasom en drake; han hafver fyllt sin buk af mine kräselighet; han hafver bortdrifvit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Men nu finner sig öfver Babel den arghet, som uppå mig och mitt kött bedrifven är, säger inbyggerskan i Zion; och mitt blod, öfver de inbyggare i Chaldeen, säger Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Derföre säger Herren alltså: Si, jag skall uträtta dig dina sak, och hämnas dig; jag skall uttorka hans haf, och förtorka låta hans brunnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Och Babel skall varda till en stenhop, och till en drakaboning, till ett vidunder, och till ett hvisslande, att der ingen uti bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'De skola allesamman ryta såsom lejon, och ropa likasom de unga lejon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Jag skall sätta dem med deras drickande uti hetta, och göra dem druckna, att de skola glade varda, och sofva en evig sömn, af hvilkom de aldrig uppvakna skola, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Jag skall nederföra dem likasom lamb, till att slagtas, såsom vädrar och bockar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Huru är Sesach så vunnen, och den beprisade i allo verldene så intagen? Huru är Babel så till ett under vorden ibland Hedningarna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Ett haf är gånget öfver Babel, och med dess många böljor är han öfvertäckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Hans städer äro öfvergifne, och till ett torrt ödeland vordne; till ett land, der ingen uti bor, och der ingen menniska uti vandrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Ty jag hafver hemsökt Bel i Babel, och rifvit utu hans hals det han uppsvulgit hade, och Hedningarna skola intet mer löpa till honom; ty murarna i Babel äro också nederfallne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Drager derut, mitt folk; hvar och en undsätte sina själ för Herrans grymma vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Edor hjerta måtte eljest vek varda, och uppgifvas för det rykte, som man i landena höra skall; ty uti eno årena skall ett rykte gå, och sedan i andra årena också ett rykte om våld i landena, och en Förste skall vara emot den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Derföre si, den tid kommer, att jag de afgudar i Babel hemsöka skall, och deras hela land till skam varda skall, och hans slagne derinne ligga skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Himmel och jord, och hvad deruti är, skola glädja sig öfver Babel, att hans förstörare nordanefter komne äro, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Och lika som Babel i Israel de slagna fällt hafver, alltså skola de slagne i Babel fällde varda uti hela landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Så drager nu edar väg, I som svärdet undflytt hafven, och töfver icke länge; tänker uppå Herran uti fjerran land, och låter Jerusalem ligga eder i hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Vi vorom till skam komne, då vi den försmädelse höra måste, och skammen betäckte vår ansigte, då de främmande kommo öfver Herrans hus helgedom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Derföre, si, den tid kommer, säger Herren att jag hans afgudar hemsöka skall, och i hela landena skola de dödssåre sucka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Och om Babel uppstege i himmelen och satte sina magt uti de höga fäste, så skola dock förstörare ifrå mig komma öfver honom, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Man hörer ena röst i Babel, och en stor jämmer i de Chaldeers land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Ty Herren förderfvar Babel; han förderfvar honom med så stort skri och rumor, att hans böljor fräsa likasom stor vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Ty förstöraren är kommen öfver Babel, hans hjeltar varda grepne, deras bågar varda sönderbrutne; ty hämndenes Gud, Herren, betalar honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Jag skall göra hans Förstar, visa, herrar och höfvitsmän, och krigsmän druckna, så att de skola sofva en evig sömn, der de icke mer af uppvakna skola, säger Konungen, som heter Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Detta säger Herren Zebaoth: Murarna om den stora Babel skola undergrafne varda, och hans höga portar uppbrännas med eld, att Hedningarnas arbete skall fåfängt vara, och uppbrännas hvad folken med mödo uppbyggt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Detta är det ord, som Propheten Jeremia befallde SeraJa, Neria sone, Mahsea sons, då han med Zedekia, Juda Konung, drog till Babel, uti fjerde årena hans rikes. Och SeraJa var en fridsam Förste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Och Jeremia skref all den olycko, som öfver Babel komma skulle, uti ene bok, nämliga all denna orden, som emot Babel skrifne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Och Jeremia sade till SeraJa: Då du kommer till Babel, så se till och läs alla dessa orden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Och säg: Herre, du hafver talat emot detta rummet, att du ville förderfva det, så att ingen skulle bo häruti, hvarken folk eller fä, utan vara till ett evigt öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Och när du hafver utläsit bokena, så bind en sten dervid, och kasta henne uti Phrath;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'Och säg: Alltså skall Babel försänkt varda, och icke uppkomma igen, för den olycko, som jag skall öfver honom komma låta, utan förgås. Allt härtill hafver Jeremia talat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Zedekia var ett och tjugu åra gammal, då han Konung vardt, och regerade i ellofva år i Jerusalem; hans moder het Hamutal, Jeremia dotter i Libna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Och gjorde det Herranom illa behagade, likasom Jojakim gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Ty Herrans vrede gick öfver Jerusalem och Juda, tilldess han förkastade dem ifrå sitt ansigte; och Zedekia föll af ifrå Konungen i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Men i nionde årena af hans rike, på tionde dagen i tionde månadenom, kom NebucadNezar, Konungen i Babel, med all sin här emot Jerusalem, och belade honom, och beskansade honom allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Och staden var så belagd, allt intill ellofte året Konungs Zedekia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Men på nionde dagen i fjerde månadenom fick hungren öfverhandena i stadenom, och landsfolket hade intet mer till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Då föll man in i staden, och allt krigsfolket gåfvo flyktena, och drogo utu staden om nattene, på den vägen åt den porten emellan de två murar, ut vid Konungsörtagården; men de Chaldeer lågo kringom staden; och desse drogo sin väg bortåt i markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Då jagade de Chaldeers här efter Konungen, och fingo Zedekia fatt, uti den markene vid Jericho; då, förströdde sig all hans här ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Och de togo Konungen till fånga, och förde honom upp till Konungen af Babel, till Riblath, det i Hamaths land ligger; han sade en dom öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Der lät Konungen af Babel dräpa Zedekia barn för hans ögon, och drap alla Juda Förstar i Riblath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Men Zedekia lät han stinga ögonen ut, och lät binda honom med två kedjor; och Konungen af Babel förde honom alltså till Babel, och lade honom uti fängelse, intilldess han blef död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'På tionde dagen i femte månadenom, hvilket det nittonde året var NebucadNezars, Konungens i Babel, kom NebuzarAdan, höfvitsmannen, den alltid var när Konungenom i Babel, till Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Och uppbrände Herrans hus, och Konungshuset, och all hus i Jerusalem; all stor hus uppbrände han i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Och all de Chaldeers bär, som med höfvitsmannenom var, refvo ned alla murarna i Jerusalem allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Men det fattiga folk, och annat folk, som ännu qvart var i stadenom, och de som till Konungen af Babel fallne voro, och det qvarblefna handtverksfolket, förde NebuzarAdan, höfvitsmannen, fångna bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Och af det fattiga folket i landena lät NebuzarAdan, höfvitsmannen, några blifva qvara, till vingårdsfolk och åkerfolk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Men de kopparstodar, som voro i Herrans hus, och stolarna, och kopparhafvet i Herrans hus, slogo de Chaldeer sönder, och förde allan kopparen deraf till Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Och kettlar, skoflar, knifvar, bäcken, skålar och all koppartyg, de man uti Gudstjenst plägade bruka, togo de bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Dertill tog höfvitsmannen bort allt det af guld och silfver var, i kannor, rökpannor, bäcken, kettlar, ljusastakar, skedar, och skålar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'De två stodarna, det ena hafvet, de tolf kopparoxar, som under foten stodo, hvilka Konung Salomo hade göra låtit till Herrans hus; kopparen af all denna tygen var öfvermåtton mycken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Men båda stoderna voro hvardera aderton alnar hög, och ett tolfalna snöre var måttet omkring henne, och var fyra finger tjock, och var ihål;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Och stod på hvardera en kopparknapp fem alnar hög, och gjordar och granatäple voro på hvar knappen allt omkring, alltsammans af koppar; och den ena stoden var såsom den andra; granatäplen också.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Och voro granatäplen deruppå sex och niotio; all granatäplen voro hundrade på ene gjord allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Och höfvitsmannen tog den Presten SeraJa, utaf första ordningen, och den Presten Zephanja, utaf den andra ordningen, och tre dörravaktare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Och en kamererare utaf stadenom, som öfver krigsfolket satt var, och sju män, som när Konungenom vara måste, hvilka i stadenom funne vordo; dertill Sopher, den härförstan, den landsfolket mönstra plägade; dertill sextio män af landsfolket, som i stadenom funne vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Dessa tog NebuzarAdan, höfvitsmannen, och förde dem till Konungen i Babel, i Riblath.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Och Konungen i Babel slog dem ihjäl i Riblath, det i Hamath lande ligger. Alltså vardt Juda bortförd utu sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Detta är det folk, som NebucadNezar bortförde, nämliga, uti sjunde årena, tretusend och tre och tjugu Judar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Men uti adertonde årena NebucadNezars, åttahundrad och två och tretio själar utaf Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Och i tredje och tjugonde årena NebucadNezars förde NebuzarAdan, höfvitsmannen, bort sjuhundrad och fem och fyratio själar af Juda; alla själarna äro fyratusend och sexhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Men uti sjunde och tretionde årena derefter att Jojachin, Juda Konung, bortförd var; på femte och tjugonde dagen i tolfte månadenom, upphof EvilMerodach, Konungen i Babel, uti de årena då han Konung vardt, Jojachins, Juda Konungs, hufvud, och lät honom utu fängelset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Och talade med honom vänliga; och satte hans stol utöfver de Konungars stolar, som när honom voro i Babel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Och förvandlade honom hans fängelses kläder; och han åt inför honom alltid i sina lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Och honom vardt alltid gifvet af Konungenom i Babel hans uppehälle, såsom honom förskickadt var i all hans lifstid, allt intill hans ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Huru ligger den staden så öde, som full med folk var? Han är likasom en enka; den som en Förstinna ibland Hedningarna, och en Drottning i landen var, hon måste nu tjena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Hon gråter om nattena, så att tårarna löpa neder på kindbenen; ingen är ibland alla hennes vänner, som hugsvalar henne; alle hennes näste förakta henne, och äro hennes fiender vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda är fången i elände och svår träldom han bor ibland Hedningar, och finner ingen ro; alle hans förföljare fara illa med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Vägarna till Zion ligga öde, efter ingen kommer till högtiden; alle hans portar stå öde, hans Prester sucka, hans jungfrur se ömkeliga ut, och han är bedröfvad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Hans ovänner sväfva allt i höjdene, hans fiendom går väl; ty Herren hafver gjort honom full med jämmer, för hans stora synders skull, och hans barn äro i fängelse bortdrefne för fiendanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'All fägring är borto för dottrene Zion; hennes Förstar äro lika som vädrar, de der ingen bet finna, och gå vanmägtige för plågsrenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jerusalem kommer ihåg i denna tid, huru elände och öfvergifven han är, och huru mycket godt han af ålder haft hafver, medan allt hans folk nederligger för fiendanom, och ingen är som hjelper; hans fiender se sina lust uppå honom, och bespotta hans Sabbather.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalem hafver syndat, derföre måste han vara lika som en oren qvinna. Alle de som ärade honom, de försmå honom nu, efter de se hans skam; men han suckar, och faller neder till markena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Hans orenlighet låder vid hans klädefållar; han hade icke trott att honom på sistone så gå skulle; han är ju allt för grufveliga nederstött, och hafver dertill ingen, som tröster honom. Ack Herre! se uppå mitt elände; ty fienden högmodas fast.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Fienden hafver kommit sina hand vid alla hans klenodier; ty han måste se deruppå, att Hedningarna gingo in uti hans helgedom, om hvilka du budit hafver, att de icke skulle komma uti dina församling.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Allt hans folk suckar och går om bröd, sin klenodier gåfvo de för mat, på det de skulle vederqvicka själena. Ack Herre! se dock till, och skåda huru föraktelig jag vorden är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Eder allom säger jag, som gån här framom: Skåder dock och ser till, om någor värk kan vara sådana som min värk, den mig så uppäter; ty Herren hafver gjort mig full med jämmer, på sine grymma vredes dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Han hafver sändt en eld af höjdene uti min ben, och låtit honom der mägtig vara; han hafver utsatt ett nät för mina fötter, och stött mig tillbaka; han hafver gjort mig till ett öde, så att jag sörja måste hela dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Mina svåra synder hafva uppvaknat genom hans straff, och alla tillsammans kommit mig uppå halsen, så att all min kraft mig förgås; Herren hafver så farit med mig, att jag icke mer uppkomma kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Herren hafver nedertrampat alla mina starka, som jag hade; han hafver låtit utropa öfver mig en högtid, till att förderfva mina unga män; Herren hafver låtit jungfruna, dottrena Juda, trampa en press.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Derföre gråter jag så, och båda min ögon flyta med vatten; ty hugsvalaren, som mina själ vederqvicka skulle, är långt bort ifrå mig. Min barn äro borto; ty fienden hafver öfverhandena fått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Zion räcker sina händer ut, och der är dock ingen, som honom tröster; ty Herren hafver budit allt omkring Jacob hans fiendom, att Jerusalem skall emellan dem vara lika som en oren qvinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Herren är rättfärdig, ty jag hafver varit hans mun ohörsam; hörer, all folk, och ser min värk; mina jungfrur och ynglingar äro gångne uti fängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Jag kallade på mina vänner, men de hafva bedragit mig; mine Prester och äldste i stadenom äro försmäktade; ty de gå om bröd, på det de skola vederqvicka sina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Ack Herre! se dock huru bedröfvad jag är, att det gör mig ondt i allt mitt lif; mitt hjerta dänger i minom kropp, ty jag är uppfylld med stor bitterhet; ute hafver svärdet, och inne i husena döden gjort mig till en enko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Man hörer väl, att jag suckar, och hafver dock ingen tröstare; alle mine fiender höra mina olycko, och glädja sig, det gör du; så låt då den dagen komma, som du utropat hafver, att dem skall gå lika som mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Låt alla deras ondsko komma inför dig, och gör med dem, såsom du med mig, för alla mina missgerningars skull, gjort hafver; ty mitt suckande är stort, och mitt hjerta är bedröfvadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Huru hafver Herren förmörkrat dottrena Zion med sine vrede? Han hafver kastat Israels härlighet af himmelen neder på jordena; han hafver icke tänkt uppå sin fotapall, i sine vredes dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Herren hafver utan barmhertighet alla Jacobs boningar förlagt; han hafver i sine grymhet afbrutit dottrenes Juda fäste, och slagit dem omkull, han hafver oskärat både hennes rike och hennes Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Han hafver sönderbrutit Israels starkhet uti sine grymma vrede; han hafver dragit sina högra hand tillbaka, då fienden kom, och hafver upptändt en eld i Jacob, den allt omkring förtärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Han hafver spänt sin båga, lika som en fiende; sina högra hand hafver han fört såsom en ovän, och dräpit allt det som lustigt var till seendes, och utgjutit sina grymnet, lika som en eld uti dottrenes Zions hyddo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Herren är lika som en fiende; han hafver omstört Israel, han hafver omstört alla hans palats, och förderfvat hans fäste; han hafver gjort dottrene Juda mycken klagan och sorg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Han hafver uppgrafvit hans tjäll, lika som en örtegård, och förderfvat hans boning; Herren hafver låtit förgäta i Zion både helgedag och Sabbath, och låtit i sine grymma vrede skämma både Konung och Prest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Herren hafver förkastat sitt altare, och tillspillogifvit sin helgedom; han hafver gifvit hans palats murar uti fiendans händer, så att de hafva ropat i Herrans hus, lika som uppå enom helgedag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Herren tänkte till att förderfva dottrenes Zions murar; han drog snöret deröfver, och icke afvände sina hand, tilldess han henne förderfvade; tornen stå ömkeliga, och muren ligger jämmerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Hans portar ligga djupt neder i jordene; hans bommar hafver han sönderbrutit, och tillintetgjort; hans Konungar och Förstar äro ibland Hedningarna, der de intet kunna öfva lagen, och hans Propheter hafva ingen syn af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Dottrenes Zions äldste ligga på jordene, och äro tyste; de kasta stoft uppå sin hufvud, och hafva dragit säcker uppå sig Jerusalems jungfrur hänga deras hufvud neder åt jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Jag hafver nästan gråtit mig ögonen ut, så att det gör mig ondt i mitt lif; min lefver är utgjuten uppå jordena, öfver mins folks dotters jämmer, då spenabarn och öfvermagar försmäktades på gatomen i stadenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Då de sade till sina mödrar: Hvar är bröd och vin? då de försmäktades på gatomen i stadenom, såsom de der dödssåre voro, och uppgåfvo sin anda i deras mödrars famn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'O du dotter Jerusalem, hvem skall jag likna dig vid? Och för hvad skall jag hålla dig, du jungfru dotter Zion? Vid hvad skall jag likna dig, der jag dig med trösta måtte. Ty din skade är stor, lika som ett haf; ho kan hela dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Dine Propheter hafva dig predikat lösa och dåraktiga syner, och icke uppenbarat dig dina missgerning, der de med måtte förtagit dig ditt fängelse; utan hafva predikat dig lösa predikan, på det de skulle predika dig utu landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Alle de som der framom gå, de klappa med händerna, hvissla åt dig, och rista hufvudet öfver dottrena Jerusalem: Är detta den staden, der man af säger, att han är den aldraskönaste, af hvilkom allt landet gläder sig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Alle dine fiender gapa med munnen emot dig; hvissla till dig, gnissla med tänderna, och säga: Huj, vi hafve förderfvat honom; detta är den dagen, som vi begärat hafve; vi hafve fått det, vi hafve lefvat så länge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Herren hafver gjort det han i sinnet hade; han hafver fullkomnat sitt ord, som han långt tillförene budit hade; han hafver förderfvat utan barmhertighet; han hafver fröjdat fiendan öfver dig, och upphöjt dina ovänners magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Deras hjerto ropade till Herran: O du dottrenes Zions mur, låt tårar flyta både dag och natt, lika som en bäck; håll intet upp, och din ögnasten vände intet åter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Statt upp om nattena, och ropa; utgjut ditt hjerta i första väktene inför Herranom, lika som vatten; lyft upp dina händer till honom, för din unga barns själar, som af hunger dö i all gatomot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Herre, skåda dock; och se till hvem du så förderfvat hafver. Skola nu qvinnorna äta sin lifsfrukt, de yngsta barnen, som näppliga en spann lång äro? Skola Propheterna och Presterna uti Herrans helgedom så dräpne varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'På gatorna, neder på jordene, lågo både unge och gamle; mina jungfrur och ynglingar, äro fallne genom svärd; du hafver dräpit på dine vredes dag, du hafver slagtat utan barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Du hafver kallat mina fiendar allt omkring, lika som till en helgedag, så att på Herrans vredes dag ingen undsluppen och igenlefd är; de som jag uppfödt och uppfostrat hafver, dem hafver fienden förgjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Jag är en elände man, den hans grymhets ris se måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Han hafver ledt mig, och låtit mig gå i mörkrena, och icke i ljusena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Han hafver vändt sina hand emot mig, och handlar fast annorlunda med mig alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Han hafver gjort mitt kött och mina hud gammal, och sönderslagit min ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Han hafver byggt emot mig, och bevefvat mig uti galla och mödo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Han hafver lagt mig uti mörkret, lika som de döda i verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Han hafver innemurat mig, så att jag icke utkomma kan, och satt mig uti hårda fjettrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Och om jag än ropade och både, så stoppar han öronen till för mina bön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Han hafver igenmurat min väg med huggen sten, och mina stigar igentäppt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Han hafver vaktat efter mig lika som en björn, lika som ett lejon i lönlig rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Han hafver låtit mig fela om vägen; han hafver rifvit mig i stycken sönder, och tillintetgjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Han hafver spänt sin båga, och satt mig; såsom ett mål för pilenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Han hafver utaf kogret låtit skjuta mig i mina njurar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Jag är vorden till spott allo mino folke, och deras dagliga visa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Han hafver måttat mig med bitterhet, och gifvit mig malört dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Han hafver slagit mina tänder sönder i små stycke, och vältrat mig uti asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Min själ är fördrifven ifrå fridenom; goda, dagar måste jag förgäta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Jag sade: Mitt hopp är ute, att jag någon tid mer skall vara när Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Kom dock ihåg, huru jag är elände och öfvergifven, och malört och galla druckit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Du varder ju deruppå tänkandes; ty min själ säger mig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Det lägger jag på hjertat, derföre hoppas mig ännu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Herrans mildhet är det, att ännu icke är ute med oss; hans barmhertighet hafver än nu icke ända;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Utan hon är hvar morgon ny, och din trohet är stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Herren är min del, säger min själ; derför vill jag hoppas uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Ty Herren är god dem som hoppas uppå honom, och den själ som frågar efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Det är en kostelig ting, att man är tålig, och hoppas uppå Herrans hjelp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Det är en kostelig ting, att man drager oket i ungdomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Att en, som öfvergifven är, hafver tålamod, när honom något uppåkommer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Och sätter sin mun uti stoft, och vänter efter hoppet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Och låtter slå sig vid kindbenet, och lägger mycken försmädelse uppå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Ty Herren drifver icke ifrå sig evinnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Utan han bedröfvar väl; men han förbarmar sig igen, efter sin stora mildhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Ty han plågar och bedröfvar icke menniskona af hjertat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Lika som han ville platt undertrycka låta de elända på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Och låta deras sak för Gudi orätta vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Och dem falskeliga döma låta, lika som Herren såge det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Ho tör då säga, att sådant sker utan Herrans befallning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Och att hvarken ondt eller godt kommer igenom hans befallning?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Hvi knorra då menniskorna alltså, medan de lefva? Hvar och en knorre emot sina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Och låt oss ransaka och söka vårt väsende, och omvända oss till Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Låt oss upplyfta vår hjerta, samt med händerna, till Gud i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Vi, vi hafve syndat, och olydige varit; derföre hafver du med rätta intet skonat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Utan du hafver förmörkrat oss med vrede, och förföljt och dräpit utan barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Du hafver betäckt dig med en sky, att ingen bön derigenom komma kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Du hafver gjort oss till träck och slemhet ibland folken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Alle våre fiender gapa med munnen emot oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Vi varde förtryckte och plågade med förskräckelse och ångest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Min ögon rinna med vattubäcker, öfver mins folks dotters jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Min ögon flyta, och kunna icke aflåta; ty der är ingen återvända;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Tilldess Herren af himmelen skådar härned, och ser dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mitt öga fräter mig lifvet bort, för alla mins stads döttrars skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Mine fiender hafva besnärt mig, lika som en fågel, utan sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'De hafva förgjort mitt lif uti ene kulo, och kastat uppå mig stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'De hafva ock begjutit mitt hufvud med vatten; då sade jag: Nu är det platt ute med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Men jag åkallade ditt Namn, Herre, nedan utu kulone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Och du hörde mina röst: Bortgöm icke din öron för mitt suckande och ropande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Nalka dig till mig, när jag åkallar dig och säg; Frukta dig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Uträtta, du Herre, mins själs sak, och förlossa mitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Herre, se dock till, huru orätt mig sker, och hjelp mig till min rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Du ser alla deras hämnd, och alla deras tankar emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Herre, du hörer deras försmädelse, och alla deras tankar öfver mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Mina motståndares läppar, och deras rådslag emot mig dagliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Se dock, ehvad de sig lägga eller uppstå, så qväda de visor om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Vedergäll dem, Herre, såsom de förtjent hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Låt dem deras hjerta förskräckas och känna dina banno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Förfölj dem med grymhet, och förgör dem under Herrans himmel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Huru är guldet så platt förmörkradt, och det fina guldet så platt förvandladt, och helgedomens stenar ligga förströdde på alla gator?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'De ädla Zions barn, lik räknad vid guld, huru äro de nu lik räknad vid lerkärile, de en pottomakares werk äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Drakarna gifva sinom ungom spenarna, och dägga dem; men mins folks dotter måste obarmhertig vara, lika som en struts i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Spenabarnena låder för törsts skull tungan vid dess gom; de unga barn ropa efter bröd, och ingen är som dem det utskifter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'De som tillförene åto det aldrakräseligaste, de försmäkta nu på gatomen; de som tillförene uppfödde voro i silke, de måste nu ligga i träck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Mins folks dotters synd är större, än Sodoms synd, den uti ett ögnablick omstört vardt, och ingen hand kom dervid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Hennes Nazareer voro renare än snö, och blankare än mjölk; deras färga var rödare än korall, deras anseende var som en saphir.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Men nu är deras ansigte så förmörkradt af svarthet, att man icke känner dem på gatomen; deras hud låder intill deras ben, och äro så torre som ett trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Dem dräpnom med svärd var bättre än dem som af hunger dödde, hvilke försmäkta och förgås måste för hungers skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'De aldrabarmhertigasta qvinnorna måste koka sin egen barn; på det de skulle hafva dem till mats, uti mins folks dotters jämmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Herren hafver fullkomnat sina grymhet, han hafver utgjutit sina grymma vrede; han hafver i Zion upptändt en eld, hvilken ock hans grundval upptärt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Konungarna på jordene hade intet trott det, eller alla menniskor på verldene, att ovännen och fienden skulle igenom Jerusalems portar kommit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Men det är skedt för hans Propheters synder, och för hans Presters missgerningars skull, hvilka derinne utgöto de rättfärdigas blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'De gingo hit och dit på gatomen, lika som blinde, och voro besölade i blod; och kunde ock ej komma vid deras kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Utan ropade till dem: Viker undan, I orene, viker, viker, kommer vid ingen ting; ty de skydde vid dem, och flydde för dem, så att man ock sade ibland Hedningarna: De blifva der icke länge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Derföre hafver Herrans vrede förstrött dem, och vill icke mer se uppå dem, efter de icke ärade Presterna, och icke voro barmhertige öfver de äldsta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Likväl gapade vår ögon efter fåfängelig hjelp, tilldess de trötte vordo, då vi vänte efter ett folk, som oss dock intet hjelpa kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Man jagade oss, så att vi icke gå torde på vårom gatom; då kom ock vår ände, våra dagar äro ute, vår ände är kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Våre förföljare voro snarare än örnar under himmelen; på bergomen hafva de förföljt oss, och i öknene vaktat efter oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Herrans smorde, som vår tröst var, är fången vorden i deras kulor, då de oss förstörde, på hvilken vi tröste, att vi under hans skugga ibland Hedningarna lefva skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Ja, fröjda dig, och var glad, du dotter Edom, som bor i Uz lande; ty kalken skall ock komma öfver dig; du måste också drucken och blottad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Men din ondska hafver en ända, du dotter Zion; han skall icke mer låta bortföra dig; men dina ondsko, du dotter Edom, skall han hemsöka, och upptäcka dina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Tänk uppå, Herre, huru oss går; skåda och se uppå vår smälek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Vårt arf är främmandom till del vordet, och vår hus utländskom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Vi äre faderlöse, och hafvom ingen fader våra mödrar äro såsom enkor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Vattnet, som oss tillhörde, måste vi dricka för penningar, vår egen ved måste vi betala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Tvång ligger oss på halsen, och om vi än trötte varda, så gifs oss dock ingen hvila.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Vi hafve måst gifva oss under Egypten och Assur, på det vi dock måtte få bröd, och äta oss mätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Våre fäder hafva syndat, och äro icke mer för handene, och vi måste deras missgerningar umgälla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Tjenare äro rådande öfver oss, och ingen är, som oss utu deras hand förlossar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Vi måste hemta vårt bröd med vår lifsfara för svärdena uti öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Vår hud är förbränd såsom uti enom ugn, för den grufveliga hungren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'De hafva skämt qvinnorna i Zion, och jungfrurna uti Juda städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Förstarna äro af dem upphängde, och de gamlas person hafver man intet ärat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Ynglingarna hafva måst draga qvarnena, och de unge stupa under vedabördor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'De gamle sitta intet mer i portarna, och ynglingar bruka intet mer strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Vår hjertas glädje hafver en ända, vår dans är vänd uti klagogråt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Af vårt hufvud är kronan fallen: Ack ve! att vi så syndat hafve!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Derföre är ock vårt hjerta bedröfvadt, och vår ögon förmörkrad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'För Zions bergs skull, att det så öde ligger, att räfvarna löpa deröfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Men du, Herre, som blifver evinnerliga, och din stol i evig tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Hvi vill du så platt förgäta oss, och så länge platt öfvergifva oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Hemta oss, Herre, åter till dig, att vi måge komma hem igen; förnya våra dagar, lika som de fordom voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Ty du hafver förkastat oss, och är allt svårliga öfver oss förtörnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Uti tretionde årena, på femte dagen i fjerde månadenom, då jag var ibland de fångna vid den älfvena Chebar, öppnade sig himmelen, och Gud viste mig syner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Den samme femte dagen var uti femte årena, efter att Jojachin, Juda Konung, var fången bortförd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Då skedde Herrans ord till Hesekiel, Busi son, Prestens, uti de Chaldeers lande, vid den älfvena Chebar; der kom Herrans hand öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Och jag såg, och si, der kom ett stormväder nordanefter, med en stor molnsky full med eld, så att det glimmade allt omkring; och midt uti eldenom var det ganska klart.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Och derinnan uti var lika som fyra djur, och ett af dem var såsom en menniska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Och de hade hvartdera fyra ansigte och fyra vingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Och deras ben stodo rätt; men deras fötter voro lika som oxafötter, och glimmade såsom glödande koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Och hade menniskohänder under deras vingar, på deras fyra sidor; ty de hade alle fyra deras ansigte och deras vingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Och vingarna voro ju hvar vid annan; och då de gingo, så behöfde de intet vända sig, utan hvart de gingo, gingo de rätt framåt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Deras ansigte på högre sidone af de fyra voro lika som menniskos och lejons; men på venstra sidone af de fyra voro deras ansigte lika som oxars och örns.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Och deras ansigte och vingar voro ofvantill uträckte, så att ju två vingar tillsammans slogo, och med två vingar skylde de sina kroppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Hvart de gingo, då gingo de rätt framåt och de gingo dit som vädret bar, och behöfde intet vända sig, då de gingo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Och djuren voro anseende lika som dödande kol, de der brinna, och lika som bloss emellan djuren; men elden gaf ett glimmande ifrå sig, och utur eldenom gick ett ljungande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Och djuren lupo hit och dit, lika som en ljungeld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Som jag nu så såg dessa djuren, si, då stod der ett hjul på jordene när de fyra djuren, och var anseendes lika som fyra hjul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Och de hjulen voro lika som en turkos, och voro alla fyra, det ena som det andra; och de voro anseende lika som ett hjul vore i de andro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'När de skulle gå, så kunde de gå på alla fyra sidor, och behöfde intet vända sig, när de gingo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Deras lötar och höjd voro förskräckelig, och deras lötar voro full med ögon allt omkring på alla fyra hjulen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Och när djuren gingo, så gingo ock hjulen när dem; och då djuren upplyfte sig ifrå jordene, så upplyfte ock hjulen sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Hvart vädret gick, dit gingo de ock, och hjulen upplyfte sig med dem; ty ett starkt väder var i hjulomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'När de gingo, så gingo desse ock; när de stodo, så stodo desse ock; och när de upplyfte sig ifrå jordene, så upplyfte sig i ock hjulen när dem; ty ett starkt väder var i hjulomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Men ofvanpå djuren var lika som himmelen, såsom en christall, förskräckelig, rätt öfver dem utsträckt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Så att under himmelen stodo deras vingar, den ene rätt emot den andra; och två vingar öfvertäckte hvarsderas kropp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Och jag hörde vingarna dåna, lika som stor vatten, och lika som en dön dens Allsmägtigas, när de gingo, och lika som en gny af enom här; men när de stilla stodo, så läto de vingarna neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Och när de stilla stodo, och läto vingarna neder, så dundrade i himmelen öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Och öfver himmelen, som öfver dem var, var lika som en saphir, såsom en stol, och på dem stolenom satt en, lik ene mennisko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Och jag såg, och det var såsom ett klart ljus; och innantill var det såsom en eld allt omkring; ifrå hans länder upp och neder såg jag såsom en eld blänka allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Lika som regnbågen synes i molnskynom, när regnat hafver, så blänkte det allt omkring. Detta var Herrans härlighets anseende; och då jag det sett hade, föll jag uppå mitt ansigte, och hörde en tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Och han sade till mig: Du menniskobarn, statt upp på dina fötter, så vill jag tala med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Och då han så talade med mig kom jag åter till mig igen, och stod upp på mina fötter, och hörde uppå honom, som talade med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Och han sade till mig: Du menniskobarn, jag sänder dig till Israels barn, till det affälliga folket, som ifrå mig fallit hafva; de, med deras fäder, hafva allt intill denna dag brutit mig emot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Men de barn, som jag sänder dig till äro hårdnackade. och förstockade i hjertat; till dem skall du säga: Detta säger Herren Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Ehvad de hörat eller låtat: Det är väl ett ohörsamt folk; så skola de dock likväl veta, att en Prophet ibland dem är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Och du menniskobarn skall intet frukta dig för dem, huru de döma dig; der äro väl gensträfvoge, och hvass törne emot dig, och du bor ibland scorpioner; men du skall intet frukta dig, huru de döma dig, eller förfära dig för deras trug, ändock de väl ett ohörsamt folk äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Utan du skall säga dem min ord, ehvad de hörat eller låtat; ty det är ett ohörsamt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Men du menniskobarn, hör du hvad jag dig säger, och var icke ohörsam, lika som de ett ohörsamt folk äro; låt upp din mun, och åt hvad jag dig gifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Och jag såg, och si, en hand vardt uträckt till mig; den hade ett sammanviket bref;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Hvilket hon upplät för mig, och der var beskrifvet utan och innan, och der var uti skrifvet klagan, ack och ve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Och han sade till mig: Du menniskobarn, ät hvad för dig är, nämliga detta brefvet, och gack bort och predika Israels huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Då lät jag min mun upp, och han gaf mig brefvet till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Och han sade till mig: Du menniskobarn, du måste detta brefvet, som jag gifver dig, äta i ditt lif, och fylla din buk dermed; då åt jag det, och det var i minom mun så sött som hannog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Och han sade till mig: Du menniskobarn, gack bort till Israels hus, och predika dem min ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Ty jag sänder dig ju icke till ett folk, som ett främmande mål och okunniga tungo hafver, utan till Israels hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Ja, icke till stor folk, som främmande mål och okunniga tungo hafva, hvilkas ord du icke förstå kan; och om jag än sände dig till dem, så skulle de dock gerna höra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Men Israels hus vill intet höra dig, ty de vilja icke höra mig sjelfvan; förty hela Israels hus hafver ena hårda panno och förstockadt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Men dock hafver jag gjort ditt ansigte hårdt emot deras ansigte, och dina panno emot deras panno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Ja, jag hafver gjort dina panno så hårda som en diamant, och hårdare än en bergklippo; derföre frukta dig intet, och var intet förskräckt för dem, att de ett sådant ohörsamt folk äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Och han sade till mig: Du menniskobarn, all min ord, som jag säger dig, dem fatta med hjerta, och hör med öron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Och gack bort till dins folks fångar, och predika dem, och säg till dem: Detta säger Herren Herren, ehvad de hörat eller låtat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Och ett väder lyfte mig upp, och jag hörde bak mig en dön, lika som af en stor jordbäfning: Välsignad vare Herrans härlighet i sitt rum!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Och jag hörde ett ruskande af djurens vingar, hvilka sig slogo emot hvarannan; och bullret af hjulen, som hardt när dem voro, och dönen utaf en stor jordbäfning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Då lyfte vädret mig upp, och förde mig bort; och jag for bort, och vardt svårliga förfärad; men Herrans hand höll mig fastan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Och jag kom till de fångar, som bodde vid den älfvena Chebar, i skördatidenom, och satte mig när dem som der såto, och blef der med dem i sju dagar ganska sorgfull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Och då de sju dagar framledne voro, skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Du menniskobarn, jag hafver satt dig till en väktare öfver Israels hus; du skall höra ordet af minom mun, och göra dem ena förvarning på mina vägnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Om jag säger dem ogudaktiga: Du måste döden dö; och du förvarar honom icke, och säger honom det icke, att den ogudaktige tager sig vara för sitt ogudaktiga väsende, på det han må blifva lefvandes; så skall den ogudaktige dö för sina synders skull, men hans blod vill jag kräfva utu dine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Men om du förvarar den ogudaktiga, och han icke omvänder sig ifrå sitt gudaktiga väsende och vägar, så skall han för sina synders skull dö; men du hafver friat dina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Och om en rättfärdig vänder sig ifrå sine rättfärdighet, och gör det ondt är, så skall jag låta honom stöta sig, så att han måste dö; ty efter du icke hafver förvarat honom, skall han för sina synders skull dö, och hans rättfärdighet, som han gjort hafver, skall icke ansedd varda; men hans blod skall jag äska utu dine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Men om du förvarar den rättfärdiga att han icke syndar, och han syndar också intet, så skall han lefva; ty han hafver tagit sig der vara före, och du hafver friat dina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Och dersammastäds kom Herrans hand öfver mig, och sade till mig: Statt upp, och gack ut i markena, der vill jag tala med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Och jag stod upp, och gick ut i markena, och si, då stod der Herrans härlighet, lika som jag henne vid älfvena Chebar sett hade; och jag föll neder uppå mitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Och jag vardt vederqvickt, och stod upp på mina fötter; och han talade med mig, och sade till mig: Gack, och innelyck dig uti dino huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Och du menniskobarn, si, man skall lägga hand uppå dig, och binda dig dermed, att du icke skall komma ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Och jag skall låta dina tungo låda vid din gom, så att du skall varda en dumbe, och intet mer kunna straffa dem; ty det är ett ohörsamt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Men när jag talar med dig, så vill jag öppna dig munnen, att du till dem säga skall: Detta säger Herren Herren: den det hörer, han höret; den det låter, han låtet; ty det är ett ohörsamt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Och du menniskobarn, tag en tegelsten; den lägg för dig, och utkasta deruppå Jerusalems stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Och gör en bestallning deromkring, och bygg ett bålverk derom, och gör en torfvall derom, och gör en här derom, och sätt krigstyg allt deromkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Men för dig tag ena jernpanno; den låt vara för en jernmur emellan dig och staden, och ställ ditt ansigte emot honom, och belägg honom; det vare Israels huse ett tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Du skall ock lägga dig på dina venstra sido, ock Israels hus missgerningar ofvanuppå. I så många dagar, som du ligger deruppå, så länge skall du ock bära deras missgerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Men jag vill göra dig deras missgerningars år till dagatal, nämliga trehundrade och niotio dagar; så länge skall du bära Israels hus missgerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Och när du detta fullkomnat hafver, skall du sedan lägga dig uppå dina högra sido, och skall bära Juda hus missgerningar i fyratio dagar; ty jag gifver dig här ock ju en dag för hvart år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Och ställ ditt ansigte och din blotta arm emot det belagda Jerusalem, och prophetera deremot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Och si, jag vill lägga hand uppå dig, så att du icke skall kunna vända dig af den ena sidone uppå den andra, tilldess du hafver ändat dina beläggningsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Så tag nu till dig hvete, bjugg, bönor, ärter, hers och hafra, och lägg det alltsammans uti ett fat, och gör dig så mång bröd deraf, som dagarna månge äro, i hvilkom du uppå dine sida ligga skall, att du hafver deraf till att äta i trehundrade och niotio dagar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Så att din mat, som du hvar dagen äta måste, skall vara tjugu siklar svår; detta skall du äta, ifrå den ena tiden till den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Vattnet skall du ock dricka efter mått, nämliga sjettedelen af ett hin; och det skall du dricka, ifrå den ena tiden till den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Bjuggkakor skall du äta, hvilka du för deras ögon vid menniskoträck baka skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Och Herren sade: Alltså skola Israels barn äta sitt orena bröd ibland Hedningarna, dit jag dem bortdrifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Men jag sade: Ack Herre Herre! si, min själ är ännu aldrig oren vorden; ty jag hafver aldrig, ifrå min ungdom allt intill denna tiden, ätit af något as, eller det som hafver rifvet varit, och intet orent kött är någon tid uti min mun kommet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Men han sade till mig: Si, jag vill tillåta dig koträck för menniskoträck, der du ditt bröd vid göra skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Och sade till mig: Du menniskobarn, si, jag skall borttaga bröds uppehälle i Jerusalem, så att de skola äta bröd efter vigt, och med bekymmer, och dricka vatten efter mått, med bekymmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Derföre, att det skall fattas både bröd och vatten, och den ene skall sörja med dem andra, och försmäkta uti sina missgerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Och du menniskobarn, tag ett svärd, så skarpt som en rakoknif, och raka dermed ditt hufvud, och ditt skägg, och tag ena vågskål, och skift håren dermed ifrå hvartannat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'En tredjepart skall du uppbränna i eld midt i stadenom, då beläggningsdagarna ute äro; annan tredjedelen tag, och slå den med svärd allt omkring; den yttersta tredjedelen kasta uti vädret, att jag må draga ut svärdet efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Men litet deraf tag, och bind vid din mantels flik.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Och tag åter något deraf, och kasta det i elden, och bränn det upp i eldenom; deraf skall en eld utkomma öfver hela Israels hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Så säger Herren Herren: Detta är Jerusalem, som jag ibland Hedningarna satt hafver, och land der allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Men han hafver omvändt min lag uti ena ogudaktiga läro, mera än Hedningarna, och mina rätter mer än landen, som omkring honom ligga; ty de förkasta min lag, och vilja icke lefva efter mina rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Derföre säger Herren Herren alltså: Efter I större ondsko bedrifven, än Hedningarna, som omkring eder äro, och intet lefven efter min bud, och gören intet efter mina rätter, utan gören efter Hedningars sätt, som omkring eder äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Derföre säger Herren Herren alltså: Si, jag skall ock till dig, och skall låta gå en dom öfver dig, att Hedningarna skola se deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Och skall så göra med dig som jag aldrig någon tid gjort hafver, ej heller härefter göra skall, för all din styggelses skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Så att i dig skola fäderna äta sin barn, och barnen sina fäder; och skall låta en sådana dom gå öfver dig, att alle dine igenlefde skola i all väder förströdde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Derföre, så sant som jag lefver, säger Herren Herren, efter du hafver med din styggelse och afgudom orenat min helgedom, skall jag ock bortskrapa dig, och mitt öga skall intet skona dig, eller se öfver med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Tredjedelen af dig skall dö af pestilentie, och förgås af hunger; och den andre tredjedelen skall falla för svärd allt omkring dig; och den yttersta tredjedelen skall jag förströ i alla väder, och draga ut svärdet efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Alltså skall min vrede fullkomnad varda, och min grymhet öfver dem uträttad varda, att jag skall få en hugnad öfver dem; och de skola förnimma, att jag Herren i mitt nit talat hafver, när jag mina grymhet uppå dem uträttat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Jag skall sätta dig till ett öde, och till en försmädelse för alla Hedningar, som omkring dig äro; för allas deras ögon, som der framom gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Och du skall vara till en försmädelse, hån, exempel och vidunder allom Hedningom, som omkring dig äro, när jag låter rätten gå öfver dig med vrede, grymhet och vredeligit straff; det säger jag Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Och när jag onda hungrens pilar ibland dem skjutandes varder, hvilke skadelige vara skola, och jag dem utskjuta skall till att förderfva eder, och låta hungren ju större och större varda öfver eder, och taga bort ifrån eder bröds uppehälle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Ja, hunger och ond vilddjur skall jag låta komma ibland eder, de skola göra eder barnlösa; och der skall pestilentie och blod vanka ibland dig; och svärdet skall jag låta komma öfver dig; Jag Herren hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Du menniskobarn, vänd ditt ansigte åt Israels berg, och prophetera emot dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Och säg: I Israels berg, hörer Herrans Herrans ord; detta säger Herren Herren, både till berg och högar, både till bäckar och dalar: Si, jag skall låta komma svärdet öfver eder och förgöra edra höjder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Att edor altare skola förödd varda, och edra afgudar sönderslagne och skall låta ihjälslå edra kroppar inför beläten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Ja, jag skall fälla Israels barnas kroppar inför edor beläte, och förströ edor ben kringom edor altare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Der I bon, der skola städerna öde varda, och höjderna ödeläggas; ty man skall förlägga edor altare, och göra dem öde, och sönderslå edra afgudar, och göra dem till intet och sönderslå edor beläte, och förlägga det I stiktat hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Och de slagne skola ligga ibland eder, att I skolen förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Men jag vill låta några igenblifva af eder, de der svärdet undslippa skola ibland Hedningarna, när jag eder i landen förstrött hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'De samme edre igenblefne skola då tänka uppå mig ibland Hedningarna, der de fångne vara måste, när jag förkrossat hafver deras horiska hjerta, det ifrå mig viket är, och deras horiska ögon, som efter deras afgudar sett hafva; och dem skall ångra den ondska, som de genom all sin styggelse bedrifvit hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Och skola förnimma, att jag är Herren, och hafver icke fåfängt talat, att jag sådana olycka skulle göra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Detta säger Herren Herren: Slå dina händer samman, och stampa med dina fötter, och säg ve öfver all den ondskas styggelse i Israels hus, för hvilkas skull de genom svärd, hunger och pestilentie falla måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Den som långt borto är, han skall dö af pestilentie, och den hardt när är, han skall falla genom svärd; men den som öfverblifver, och derföre förvarad är, han skall dö af hunger; alltså skall jag fullkomna mina grymhet ibland dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Att I förnimma skolen, att jag är Herren, när deras slagne skola ligga ibland deras afgudar omkring deras altare, på alla högar, och på all berg, och under all grön trä, och under alla tjocka ekar, i hvilka rum de allahanda afgudom sött rökoffer gjort hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Jag skall utsträcka mina hand emot dem, och göra landet tomt och öde, allt ifrån öknene intill Diblath, ehvar de bo; och de skola förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Du menniskobarn, detta säger Herren Herren om Israels land: Änden kommer, änden kommer öfver alla fyra landsens ändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nu kommer änden öfver dig; ty jag skall sända mina grymhet öfver dig, och skall döma dig såsom du förtjent hafver, och skall gifva dig hvad all din styggelse tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Mitt öga skall intet skona dig, eller se öfver med dig; utan jag skall gifva dig såsom du förtjent hafver, och din styggelse skola komma ibland dig, att I förnimma skolen, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Detta säger Herren Herren: Si, en olycka kommer efter den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Änden kommer, änden kommer, han stöter uppå dig; si, han kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Han går allaredo upp, och kommer fram öfver dig, du landsens inbyggare; tiden kommer, jämmerdagen är hardt när, då intet sjungande på bergomen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nu då jag snarliga gjuta mina grymhet öfver dig, och fullkomna mina vrede uppå dig, och döma dig såsom du förtjent hafver, och gifva dig hvad all din styggelse tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Mitt öga skall intet skona dig, eller se öfver med dig; utan jag skall gifva dig såsom du förtjent hafver, och din styggelse skola komma ibland dig, att I förnimma skolen, att jag är Herren som eder slår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Si dagen, si, han kommer, han kommer fram; riset blomstras, och den stolte grönskas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Tyrannen hafver upprest sig till ett ris öfver de ogudaktiga; så att intet af dem, eller af deras folk, eller af deras hop skall någon tröst få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Derföre kommer tiden, dagen nalkas; köparen fröjde sig intet, och säljaren sörje intet; ty vreden kommer öfver alla deras rikedomar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Derföre skall säljaren intet mer sköta om sitt sålda gods, ty den som lefver, han skall hafva det; förty Prophetien om all deras rikedom skall intet tillbakagå; derföre förhärde sig ingen i sina missgerning, genom sina rikedomar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Låter man blåsa i basunen, och tillreda all ting, der varder dock ingen till slags utdragandes; ty min grymhet går öfver allt hans folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Ute på gatomen går svärdet, i husomen går pestilentie och hunger; den på markene är, han måste dö genom svärd; men den i stadenom är, honom skall hunger och pestilentie uppfräta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Och de som undfly af dem, de måste vara på bergomen, och lika som dufvor i dalomen, hvilke alle tillsammans qvida, hvar och en för sina missgernings skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Alla händer skola nederfalla, och all knä skola vara ostadig som vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Och de skola kläda sig i säcker, och med fruktan öfvergjutne varda, och all ansigte jämmerliga utse, och all hufvud skola kullot varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'De skola kasta sitt silfver ut uppå gatorna, och sitt guld akta såsom träck; ty deras silfver och guld skall intet kunna hjelpa dem, på Herrans vredes dag; och skola dock intet kunna mätta sina själ deraf, eller fylla sin buk deraf; ty det hafver varit dem en förargelse, till deras missgerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Af sin ädla klenodier der de högfärd med bedrefvo, hafva de sin grufvelses och styggelses beläte gjort, derföre skall jag göra dem det till orenlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Och skall gifva det främmandom i händer, att de det bortröfva skola, och dem ogudaktigom på jordene till ett byte, att de skola ohelga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Jag skall vända mitt ansigte derifrå, att de ju min skatt väl ohelga skola; ja röfvare skola komma deröfver, och ohelga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Gör en gård omkring dem; ty landet är fullt med blodskulder, och staden full med öfvervåld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Så skall jag låta komma de argesta ibland Hedningarna, att de skola taga deras hus in; och skall göra en ända på de väldigas högfärd, och ohelga deras kyrkor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Uppryckaren kommer; så skola de frid söka, och han skall intet vara der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'En olycka skall komma efter den andra, ett rykte öfver det andra; så skola de då söka ena syn när Prophetanom; men der skall hvarken lagen mer vara när Prestenom, eller råd när de gamla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Konungen skall vara bedröfvad, och Förstarna skola sorgeliga klädde vara, och folkens händer i landena skola förtviflada vara: Jag skall så ställa mig med dem, såsom de lefvat hafva, och skall döma dem, såsom de förtjent hafva, att de skola förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Och det begaf sig uti sjette årena, på femte dagen i sjette månadenom, att jag satt i mino huse, och de äldste af Juda såta för mig; der föll Herrans Herrans hand öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Och si, jag såg, att hvad som nedanför hans länder var, det var lika som en eld, men ofvan hans länder var det ganska klart.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Och han räckte ut lika som ena hand, och fattade mig i mitt hufvudhår; så upptog mig ett väder emellan himmel och jord, och förde mig till Jerusalem uti ene Guds syn, till den innersta dörrena, som norrut är, der ett beläte stod, husherranom till förtret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Och si, der var Israels Guds härlighet, lika som jag henne tillförene sett hade i markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Och han sade till mig: Du menniskobarn, lyft din ögon upp norrut. Och då jag upplyfte min ögon norrut, si, då stod det förtretliga belätet norrut vid altareporten, der man ingår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Och han sade till mig: Du menniskobarn, ser du ock hvad desse göra; nämliga den stora styggelsen, som Israels hus här gör, att de ju skola drifva mig långt ifrå minom helgedom? Men du skall ännu se större styggelser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Och han hade mig intill gårdsens port, och jag såg, och si, der var ett hål på väggene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Och han sade till mig: Du menniskobarn, bryt igenom väggena. Och som jag bröt igenom väggena, si, då var der en dörr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Och han sade till mig: Gack derin, och se de slemma styggelser, som de här göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Och då jag kom in, och såg till, si, då voro der allahanda beläte, matkars och djurs, alltsammans styggelse, och allahanda Israels hus afgudar, allestäds omkring väggarna gjorda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'För hvilkom stodo sjutio män af de äldsta i Israels hus. och Jaasanja, Saphans son, stod också ibland dem; och hvardera hade sitt rökverk i handene, och ett tjockt damb gick upp af rökverket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Och han sade till mig: Du menniskobarn, ser du hvad de äldste af Israels hus göra i mörkrena, hvar och en i sin skönasta kammar? Ty de säga: Herren ser oss intet, utan Herren hafver öfvergifvit landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Och han sade till mig: Du skall ännu se större styggelser, som de göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Och han hade mig intill den porten på Herrans hus, som nordantill är, och si, der såta qvinnor, som begreto Thammus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Och han sade till mig: Du menniskobarn, ser du detta? Men du skall ännu större styggelser se, än desse äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Och han hade mig in uti inra gården åt Herrans hus; och si, för dörrene åt Herrans tempel, emellan förhuset och altaret, voro fem och tjugu män, som hade vändt sin rygg åt Herrans tempel, och ansigtet österut, och tillbådo emot solenes uppgång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Och han sade till mig: Du menniskobarn, ser du detta? Är detta Juda huse en ringa ting, att de här all sådana styggelser göra, efter de dock eljest öfver allt landet öfvervåld och orätt bedrifva, och fara till och reta mig; och si, de hålla en löfqvist för näsone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Derföre skall jag ock handla emot dem med grymhet, och mitt öga skall hvarken skona dem, eller öfverse med dem; och om de än ropa med höga röst för min öron, så vill jag dock intet höra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Och han ropade med höga röst för min öron, och sade: Det är för handene, att staden skall hemsökt varda, och hvar och en hafve ett mordvapen i sine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Och si, der kommo sex män på vägen ifrå öfra portenom, som norrut är, och hvar och en hade ett skadeligit vapen i sine hand; men der var en ibland dem, som hade linnkläder uppå, och ett skriftyg vid sina sido, och de gingo in, och trädde intill kopparaltaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Och Israels Guds härlighet steg upp ifrå Cherub, öfver hvilkom hon var, intill huströskelen, och ropade till honom, som linnkläden på hade, och skriftyget vid sina sido.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Och Herren sade till honom: Gack igenom Jerusalems stad, och teckna de män i ännet med ett tecken, som sucka och jämra sig öfver den styggelse, som derinne sker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Men till de andra sade han, mig åhörande: Går efter dessom igenom staden, och slår derinne; edor ögon skola ingen skona, eller med någon öfverse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Slår både gamla, ynglingar, jungfrur, barn och qvinnor, till döds; men de som tecknet hafva på sig, ingen af dem skolen I vederkomma; begynner först uppå minom helgedom. Och de begynte på de gamla män, som för husena voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Och han sade till dem: Ohelger huset och görer gårdarna fulla med döda kroppar; går här ut. Och de gingo ut, och slogo i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Och då de utslagit hade, var jag ännu qvar blifven, och jag föll på mitt ansigte, ropade och sade: Ack! Herre Herre, vill du då förgöra alla de qvarlefda i Israel, att du så utgjuter dina vrede öfver Jerusalem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Och han sade till mig: Israels hus och Juda hus missgerning är allt för stor; det är icke annat än öfvervåld och orätt i landena och i stadenom; ty de säga: Herren hafver öfvergifvit landet, och Herren ser oss intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Derföre skall mitt öga ock intet skona, och ingen nåd bevisa; utan jag skall göra med dem, som de förtjent hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Och si, den mannen, som linnkläden uppå hade, och skriftyget vid sina sido, svarade, och sade: Jag hafver gjort såsom du mig budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Och jag såg, och si, på himmelen, ofvan Cherubims hufvud, var lika som en saphir, och ofvanpå honom var lika som en stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Och han sade till den mannen i linnkläden: Gack in emellan hjulen under Cherub, och tag händerna fulla med glödande kol, som emellan Cherubim äro, och strö dem öfver staden; och han gick in, så att jag såg då han der ingick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Men Cherubim stod på högra sidone i husena och gården vardt innantill full med töckno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Och Herrans härlighet reste sig upp af Cherub, allt intill huströskelen, och huset vardt fullt med töckno, och gården full med sken af Herrans härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Och man hörde vingarna af Cherubim döna, allt ut uppå gården, lika som allsmägtigs Guds röst, då han talar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Och då han hade budit mannenom i de linna kläden, och sagt: Tag eld emellan hjulen under Cherubim; gick han derin, och trädde intill hjulet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Och Cherub räckte ut sina hand emellan Cherubim till elden, som var emellan Cherubim, tog deraf, och fick mannenom i linnklädomen i händerna; han tog dervid, och gick ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Och det syntes på Cherubim, lika som ens menniskos hand under deras vingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Och jag såg, och si, fyra hjul stodo när Cherubim, vid hvar Cherub ett hjul; och hjulen voro uppåseende lika som en turkos;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Och voro alla fyra, det ena såsom det andra, lika som ett hjul hade varit uti de andro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'När ett af dem gick så gingo de alla fyra, och de behöfde icke vända sig, när de gingo; utan hvart det främsta gick, dit gingo de efter, och behöfde intet vända sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Samt med deras hela kropp, rygg, händer och vingar; och hjulen voro full med ögon allt omkring på alla fyra hjulen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Och han kallade hjulen klot, så att jag det hörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Så voro der ock fyra ansigte; det första ansigtet var en Cherub, det andra var en menniska, det tredje ett lejon, det fjerde en örn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Och Cherubim sväfde i höjdene; det är rätt detsamma djuret, som jag såg vid den älfvena Chebar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'När Cherubim gingo, så gingo ock hjulen när dem; och då Cherubim fläktade med vingarna, att de skulle lyfta sig upp ifrå jordene, så gingo ock hjulen intet ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'När de stodo, så stodo desse ock; upplyfte de sig, så upplyfte ock desse sig; ty ett starkt väder var i dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Och Herrans härlighet gick återigen ifrå huströskelen, och satte sig ofvanpå Cherubim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Då fläktade Cherubim med sina vingar, och upplyfte sig ifrå jordene för min ögon; och då de utgingo, gingo hjulen när dem, och de trädde uti dörrena af Herrans hus östantill, och Israels Guds härlighet var ofvanuppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Detta är det djuret, som jag såg under Israels Gud, vid den älfvena Chebar, och förmärkte att det voro Cherubim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Och hvartdera hade ju fyra ansigten, och fyra vingar, och under vingomen lika som menniskohänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Deras ansigte var lika som jag dem såg vid älfvena Chebar; och de gingo rätt framåt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Och ett väder lyfte mig upp, och förde mig inför porten åt Herrans hus, hvilken österut är; och si, i den porten voro fem och tjugu män; och jag såg ibland dem Jaasanja, Assurs son, och Pelatja, Benaja son, som Förstar voro i folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Och han sade till mig: Du menniskobarn, desse män hafva de tankar som vilja illa lyktas, och de anslag som denna stadenom skada skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Ty de säga: Det är intet så när, låt oss man bygga hus; han är grytan, vi äre köttet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Derföre skall du menniskobarn prophetera emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Och Herrans Ande föll öfver mig, och sade till mig: Säg, detta säger Herren; I af Israels hus hafven talat rätt, edra tankar känner jag väl;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'I hafven dräpit alltför många i denna stadenom, och hans gator ligga fulla med döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Derföre säger Herren Herren alltså: De som I derinne dräpit hafven, de äro köttet, och han är grytan; men I måsten härut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Svärdet, som I frukten, det skall jag låta komma öfver eder, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Jag skall drifva eder derut, och gifva eder främmandom i händer, och skall göra eder edran rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'I skolen falla genom svärd; i Israels gränsor skall jag döma eder, och I skolen förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Men staden skall intet vara edor gryta, ej heller I köttet derinne; utan i Israels gränsor skall jag döma eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Och I skolen förnimma, att jag är Herren; ty I hafven icke vandrat efter min bud, och intet hållit mina rätter; utan gjort efter Hedningarnas sätt, som omkring eder äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Och då jag så propheterade, blef Pelatja, Benaja son, död. Och jag föll uppå mitt ansigte, och ropade med höga röst, och sade: Ack! Herre Herre, du gör platt en ända med de igenlefda af Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Då skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Du menniskobarn, dine bröder och närskylde fränder, och hela Israels hus, som ännu i Jerusalem bo, säga väl emellan sig: De andre äro långt bortflydde ifrå Herranom; men vi hafve landet inne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Derföre säg du: Detta säger Herren Herren: Ja, jag hafver låtit drifva dem långt bort ibland Hedningarna, och förstrött dem i landen; så vill jag dock snarliga vara deras hjelp i de land, dit de komne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Derföre säg du: Detta säger Herren Herren: Jag skall församla eder ifrå folken utu de land, dit I förströdde ären, och gifva eder Israels land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Dit skola de komma, och taga derut all styggelse och vämjelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Och jag vill gifva eder ett endrägtigt hjerta, och en ny Ända ingifva uti eder, och skall borttaga det stenhjertat utur edar kropp, och gifva eder ett kötthjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'På det de skola vandra i min bud, och hålla mina rätter, och göra derefter; och de skola vara mitt folk, så vill jag vara deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Men dem som vandra efter sin hjertas styggelse och grufvelse, dem skall jag lägga deras väsende uppå deras hufvud, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Då fläktade Cherubim med sinom vingom, och hjulen gingo bredovid dem, och Israels Guds härlighet var ofvanuppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Och Herrans härlighet uppfor utu staden, och satte sig uppå det berget, som ligger östan för stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Och ett väder upptog mig, och förde mig, i ene syn och i Guds Anda, in uti Chaldee land, till fångarna; och den synen, som jag sett hade, försvann för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Och jag sade fångamen all Herrans ord, som han mig vist hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Du menniskobarn, du bor ibland ett ohörsamt folk, hvilke väl ögon hafva, att de se måtte, och vilja dock intet se; öron, att de höra måtte, och vilja dock intet höra; utan äro ett ohörsamt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Derföre, du menniskobarn, skicka dig som du ville färdas, och drag din väg om ljusa dagen för deras ögon; du skall bortfara ifrå ditt rum till ett annat rum för deras ögon; om de tilläfventyrs märka vilja, att de ett ohörsamt folk äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Och du skall hafva din tyg framme, lika som du färdas ville om ljusa dagen för deras ögon; och du skall draga din väg om aftonen för deras ögon, lika som man bortfar, då man vandra vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Och du skall bryta dig genom väggena för deras ögon, och gack der ut igenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Och du skall tagat uppå dina skuldror, för deras ögon, och när mörkt ordet är, din väg draga; du skall binda om ditt ansigte, att du icke skall se landet; ty jag hafver satt dig Israels hus till ett vidunder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Och jag gjorde såsom mig befaldt var, och bar min tyg fram, lika som jag färdas skulle om ljusan dag, och om aftonen bröt jag genom väggena med handene; och som det var mörkt vordet, tog jag det på skuldrorna, och bar det ut för deras ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Och om morgonen bittida skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Du menniskobarn, hafver Israels hus, det ohörsamma folket, icke sagt till dig: Hvad gör du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Så säg till dem: Detta säger Herren Herren: Denne tungen gäller Förstan uppå i Jerusalem, och hela Israels hus, som der är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Säg: Jag är edart vidunder; lika som jag gjort hafver, alltså skall eder ske, att I måsten färdas och fångne förde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Deras Förste skall bortförd varda på skuldrom i mörkrena, och måste gå ut igenom väggena, den de bryta skola, att de skola draga derigenom; hans ansigte skall förskylas, att han icke med något öga ser landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Jag skall ock kasta mitt nät öfver honom, att han i mine jagt fången varda skall; och jag vill låta honom komma till Babel uti de Chaldeers land, det han dock intet se skall och der måste han dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Och alle de som omkring honom äro, hans hjelpare och hans anhang, skall jag förströ i all väder, och draga ut svärdet efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Alltså skola de förnimma, att jag är Herren, när jag bortdrifver dem ibland Hedningarna, och förstör dem i landen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Men jag skall låta några få af dem igenblifva för svärdena, hungern och pestilentien, att de skola förtälja deras styggelse, ibland Hedningarna, dit de kommande varda, och skola förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Du menniskobarn, du skall äta ditt bröd med bäfvande, och dricka ditt vatten med darrande och sorg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Och säg till folket i landena: Detta säger Herren om inbyggarena i Jerusalem i Israels land: De skola äta sitt bröd i sorg, och dricka sitt vatten i elände: ty landet skall öde varda ifrån allt det deruti är, för alla inbyggarenas ondskas skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Och de städer, som väl besatte äro, skola tomme, och landet öde varda. Alltså skolen I förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Du menniskobarn hvad hafven I för ett ordspråk uti Israels land, och sägen: Efter det dröjes så länge, så blifver nu intet mer af edra Prophetier?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Derföre säg till dem: Detta säger Herren Herren: Jag skall lägga det ordspråket neder, att man det intet mer bruka skall i Israel; och säg till dem: Tiden är hardt när, och allt det som propheteradt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Ty I skolen nu härefter förnimma, att ingen syn fela skall, eller någon Prophetie ljuga emot Israels hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Ty Jag är Herren; hvad jag talar, det skall ske, och intet länger fördröjdt varda; utan i edor tid, I ohörsamma folk, skall jag göra det jag talar, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Du menniskobarn, si, Israels hus säger: Den synen, som denne ser, dit är ännu långt, och propheterar om den tid, som ännu långt borto är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Derföre säg till dem: Så säger Herren Herren: Det jag talar, det skall icke länger fördröjdt varda; utan skall ske, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Du menniskobarn, prophetera emot Israels Propheter, och säg till dem som utaf sitt eget hjerta prophetera: Hörer Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Detta säger Herren Herren: Ve dem galna Prophetomen, som sin egen anda följa, och hafva dock ingen syn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'O Israel! dine Propheter äro lika som räfvar i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'De träda icke framför gapet, och göra sig icke till en mur omkring Israels hus, och stå intet i stridene på Herrans dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Deras syner äro intet, och deras Prophetie är icke utan lögn; de säga: Herren hafver det sagt; ändock Herren hafver intet sändt dem, och vinnlägga sig, att de kunna hålla sin ord vid magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Äro icke edra syner intet, och edor Prophetie alltsammans lögn? Och I sägen likväl: Herren hafver det sagt; ändock jag det intet sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Derföre säger Herren Herren alltså: Efter I prediken det, der intet af varder, och propheteren lögn, så vill jag till eder, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Och min hand skall komma öfver de Propheter, som predika det, der intet utaf varder, och prophetera lögn; de skola intet vara uti mins folks församling, och uti Israels hus tal icke beskrefne varda, eller komma uti Israels land; och I skolen förnimma, att jag är Herren Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Derföre, att de förföra mitt folk, och säga: Frid, ändock der är ingen frid; folket bygger upp väggena; men de bestryka henne med lös kalk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Säg till de bestrykare, som med lösom kalk bestryka, att det varder affallandes; ty ett slagregn varder kommandes, och stort hagel fallandes, och en väderhvirfvel skall storma deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Si, så skall väggen falla; hvad gäller, man varder då till eder sägandes: Hvar är nu den bestrykningen, som I strukit hafven?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Detta säger Herren Herren: Jag skall låta storma en väderhvirfvel i mine grymhet, och ett slagregn i mine vrede, och stora hagelstenar i barm, de skola allt omkullslå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Och så skall jag omkullslå väggena, den I med lös kalk bestrukit hafven, och kasta henne till jordena, så att man skall se hennes grundval, att hon nedre ligger; och I skolen också derinne förgås, och förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Alltså skall jag fullkomna mina grymhet på väggene, och uppå dem som henne med lösom kalk bestryka, och säga till eder: Här är hvarken vägg eller bestrykare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Detta äro Israels Propheter, som till Jerusalem prophetera, och predika om frid, ändock der ingen frid är, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Och du menniskobarn, ställ ditt ansigte emot döttrarna i ditt folk, hvilka prophetera utaf sitt hjerta; och prophetera emot dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'Och säg: Detta säger Herren Herren: Ve eder, som gören menniskomen hyende under armarna, och örnagott under hufvuden, både ungom och gamlom, till att fånga själar; när I nu hafven fångat själarna i mitt folk, så sägen I dem lif till;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Och ohelgen mig i mitt folk, för en hand full med bjugg, och för en beta bröd, dermed att I dömen de själar till döds, som dock intet dö skulle, och dömen dem till lifs, som dock icke lefva skulle, genom edra lögn ibland mitt folk, som lögn gerna hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Derföre säger Herren Herren: Si, jag vill till edor hyende, der I själarna med gripen och förtrösten, och skall rycka dem bort undan edra armar, och de själar, som I gripen och förtrösten, lösa göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Och skall sönderrifva edor örnagott, och fria mitt folk utur edra hand, att I intet mer skolen gripa dem; och I skolen förnimma, att jag; är Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Derföre, att I falskeliga bedröfven de rättfärdigas hjerta, hvilka jag intet bedröfvat hafver, och hafven styrkt de ogudaktigas händer, så att de intet omvända sig ifrå sitt onda väsende, på det de måtte lefvande blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Derföre skolen I intet mer predika onyttiga läro, eller prophetera; utan jag skall fria mitt folk utur edra händer, och I skolen förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Och till mig komma någre af de äldsta i Israel, och satte sig när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Då skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Du menniskobarn, desse männerna hänga med sitt hjerta intill sina afgudar, och hålla fast uppå sins horeris förargelse; skulle jag då svara dem, när de fråga mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Derföre tala med dem, och säg till dem: Detta säger Herren Herren: Hvilken menniska af Israels hus hänger med sitt hjerta intill sina afgudar, och håller fast uppå sins afguderis förargelse, och kommer till Propheten, så vill jag, Herren, svara honom, såsom han förtjent hafver med sitt stora afguderi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'På det Israels hus skall bedraget varda i sitt hjerta, derföre att de ifrå mig trädt hafva, genom mångahanda, afguderi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Derföre skall du säga till Israels hus: Detta säger Herren Herren: Vänder eder om, och träder ifrån edart afguderi, och vänder edor ansigte ifrån all edor styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Ty hvilken menniska af Israels hus, eller någor främling, som i Israel bor, viker ifrå mig, och med sitt hjerta hänger till sina afgudar, och fast håller uppå sins afguderis förargelse, och kommer till Propheten, på det han skall fråga mig genom honom; honom vill jag, Herren, sjelfver svara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Och skall sätta mitt ansigte emot honom, och göra honom till ett tecken och ordspråk, och skall rycka honom utu mitt folk, att I förnimma skolen, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Men om en förförder Prophet något predikar, honom vill ock jag, Herren, låta förförd varda, och skall uträcka mina hand öfver honom, och utrota honom utu mitt folk Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Alltså skola de både umgälla sina missgerning; lika som frågarens missgerning, så skall ock Prophetens missgerning vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'På det de icke mer skola förföra Israels hus ifrå mig, och icke mer orena sig uti allehanda, sin öfverträdelse; utan skola vara mitt folk, och jag skall vara deras Gud, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Du menniskobarn, när landet syndar emot mig, och dertill försmädar mig, så skall jag räcka mina hand öfver det, och borttaga bröds uppehälle, och sända der hunger in, att jag skall förgöra der både folk och fä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Och om än de tre männerna Noah, Daniel, och Job, derinne voro, så skulle de allenast kunna fria sina egna själar, genom sina rättfärdighet, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Och om jag läte komma ond djur in uti landet, hvilke folket bortjagade, och förödde det, så att der ingen kunde inne vandra för djurens skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Och om desse tre männerna voro derinne; så, sant som jag lefver, säger Herren Herren, de skulle hvarken kunna fria söner eller döttrar, utan allena sig sjelfva, och landet måste öde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Eller om jag läte komma svärd uppå landet, och sade: Svärd, far igenom landet; och vorde alltså både folk och fä förgjordt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Och om de tre män voro derinne; så sant som jag lefver, säger Herren Herren, de skulle hvarken kunna fria söner eller döttrar; utan de allena skulle friade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Eller om jag sände pestilentie uti landet, och utgöte mina grymhet deröfver, och det blod kostade, så att jag förgjorde både folk och fä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Och om Noah, Daniel, och Job, voro derinne; så sant som jag lefver, säger Herren Herren, de skulle icke, igenom sina rättfärdighet, hvarken kunna undsätta söner eller döttrar, utan allena sina egna själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Ty så säger Herren Herren: Om jag sände mina fyra onda plågor, som är svärd, hunger, ond djur och pestilentie, öfver Jerusalem, så att jag derinne förgjorde både folk och fä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Si, så skola någre derinne igenlefvas och undslippa, hvilke söner och döttrar der utföra skola, och komma hit till eder, att I se skolen, huru dem går, och trösta eder öfver den olycko, som jag öfver Jerusalem hafver komma låtit, samt med allt annat, det jag öfver dem hafver komma låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'De skola vara edor tröst, då I fån se huru dem går, och kunnen besinna, att jag icke utan sak gjort hafver, hvad jag derinne gjort hafver, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Du menniskobarn, hvad är ett torrt vinträ för annat trä, eller en vinqvist för annat trä i skogen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Tager man dem och gör der något utaf? Eller är man der en nagla utaf, der man något på hänga kan (såsom man gör af annat trä)?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Si, man kastar det i elden, att det förtärdt varder, så att båda dess ändar förtärer elden, och dess medelsta brinner upp. Hvartill skulle det nu doga, doger det ock till någors?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Si, då det ännu helt var, kunde man intet göra deraf; huru mycket mindre kan man nu härefter göra deraf, då elden det förtärt och uppbränt hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Derföre säger Herren Herren: Lika som jag gifver de torra vinqvistar eldenom, till att förtära för annat trä, så skall jag ock göra med Jerusalems inbyggare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Och skall sätta mitt ansigte emot dem, att de icke skola undkomma elden, utan elden skall uppfräta dem; och I skolen förnimma, att jag är Herren, när jag sätter mitt ansigte emot dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Och gör landet öde; efter de hafva försmädat mig, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Du menniskobarn, uppenbara Jerusalems stad sin styggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Och säg: Detta säger Herren Herren till Jerusalem: Ditt fädernesland och ditt slägte är utaf de Cananeers land; din fader af de Amoreer, och din moder af de Hetheer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Ditt slägte hafver icke skorit dig naflan bort, då du född vardt; så hafver man ej heller badat dig med vatten, att du måtte ren vordit, ej heller bestrukit med salt, ej heller bebundit med linda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Ty ingen ömkade sig öfver dig, att han måtte förbarmat sig öfver dig, och bevist dig något af denna stycken; utan du vardt kastad ut på markena; så föraktad var din själ, då du född vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Men jag gick framom dig, och såg dig liggande i ditt blod, och sade till dig: Du skall lefva, då du så uti ditt blod lågst; ja, till dig sade jag, då du så i ditt blod lågst: Du skall lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Och jag hafver uppfödt dig, och låtit dig stor varda, lika som en frukt på markene, och vast nu uppvuxen, och stor och dägelig vorden; din bröst voro växt, och du hade fått skönt långt hår; men du vast ännu nakot och blygelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Och jag gick framom dig, och såg uppå dig, och si, du vast manväxt: Då bredde jag mina kjortels flik öfver dig, och öfvertäckte dina blygd; och jag trolofvade dig, och gaf mig uti förbund med dig, säger Herren Herren, att du skulle vara min.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Och jag tvådde dig med vatten, och utvaskade dig af ditt blod, och smorde dig med balsam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Och klädde dig med stickad kläder, och drog sköna skor uppå dig; jag gaf dig skön kläder, och gaf dig silkesdok;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Och beprydde dig med klenodier, och lade smide på dina armar, och kedjor uppå din hals;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Och gaf dig, ett ännespann i ditt änne, och örnaringar i din öron, och en skön krono uppå ditt hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Summa, du blefst beprydd med guld, och med silfver, och beklädd med bästa linnkläde, silke och stickad verk; du åt ock semlobröd, hannog och oljo, och vast öfvermåtton dägelig, och fick ett rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Och ditt rykte gick vida ut ibland Hedningarna, för dina fägrings skull, den ganska fullkomlig var, genom sådana prydning, som jag uppå dig hängt hade, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Men du förlätst dig uppå dina fägring; och efter du så beprisad vast, bedref du horeri, så att du gjorde dig menliga hvarjom och enom, som framom gick, och gjorde hans vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Och du tog af din kläder, och gjorde dig brokot altare deraf, och bedraf ditt horeri deruppå, såsom aldrig någon tid skedt är, eller ske skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Och du tog ock din sköna tyg, som jag dig af mitt guld och silfver gifvit hade, och gjorde dig mansbeläte deraf, och bedref ditt horeri med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Och tog din stickade kläder, och betäckte dem dermed; och mina oljo och rökverk lade du fram för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Min mat, som jag dig gaf till att äta, semlor, oljo och hannog, lade du för dem till en söt rök; ja det kom dertill, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Du togst dina söner och döttrar, som du mig födt hade, och offrade dem, dem till spis; menar du nu, att det en ringa ting är med ditt horeri;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Att du slagtar min barn, och låter dem för dem uppbränna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Likväl hafver du, i all din styggelse och horeri, icke ens tänkt uppå dins ungdoms tid, huru blott och nakot du vast, och lågst i ditt blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Öfver alla dessa dina ondsko, ack ve! ve dig, säger Herren Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Byggde du dig bergkyrkor, och gjorde dig bergaltare på alla gator;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Och främst på alla vägar byggde du dig bergaltare, och gjorde dina fägring till en styggelse; du neg med din ben för alla de der framgingo, och bedref stort boleri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Först bedraf du boleri med dinom grannom, Egypti barnom, hvilke stort kött hade, och brukade stort boleri, till att reta mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Men jag räckte mina hand ut emot dig, och styrde sådana ditt sätt, och öfvergaf dig uti dina fiendars vilja, de Philisteers döttrars, hvilke skämdes för ditt skamlösa väsende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Sedan bedref du boleri med Assurs barnom, och kunde dess icke mätt varda; ja, då du hade bedrifvit boleri med dem, och dess icke mätt varda kunde,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Förökade du ändå ditt boleri med köpmän af Chaldeen; så kunde du ändå der, med icke mätt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Huru skall jag dock omskära ditt hjerta? säger Herren Herren, efter du sådana enes arga horos gerningar gör,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Dermed att du byggde dine bergkyrkor främst på alla vägar, och gjorde din altare på alla gator; dertill vast du icke såsom en annor sköka, den man med penningar köpa måste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Eller som en horkona, som uti sins mans stad, tillåter en annan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Ty allom androm skökom gifver man penningar, men du gifver allom dinom bolarom penningar till, och begåfvar dem; att de allstädes till dig komma skola, till att bedrifva boleri med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Och man finner i dig, i ditt horeri, tvärtemot det vandt är med andra qvinnor; efter man intet löper efter dig; utan du gifver ock penningar till, och man gifver dig inga penningar, alltså gör du då tvärtom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Derföre, du sköka, hör Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Detta säger Herren Herren: Efter du så gerna gifver penningar till, och upptäcker dina skam igenom ditt boleri emot dina bolar, och emot alla dins styggelses afgudar, och utgjuter dina barnas blod, hvilka du dem offrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Derföre, si, jag skall församla alla dina bolar, med hvilkom du hafver vällust bedrifvit, samt med allom dem som du för vänner håller, till dina fiendar, och jag skall församla dem båda emot dig allestäds, och skall upptäcka dina skam, att de alla dina skam se skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Och skall låta gå ene horos och blodsutgjuterskos rätt öfver dig, och skall utgjuta ditt blod med grymhet och nit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Och skall gifva dig uti deras händer, att de skola afbryta dina bergkyrkor, och din bergaltare nederrifva, och afkläda dig din kläder, och borttaga dig din sköna tyg, och låta dig sitta nakota och blotta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Och de skola låta komma emot dig stora hopar med folk, hvilka dig stena skola, och hugga dig alla sönder med sin svärd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Och uppbränna din hus med eld, och göra dig din rätt för många qvinnors ögon; alltså skall jag göra en ända med ditt horeri, att du icke mer skall gifva penningar till;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Och skall släcka min harm uppå dig, och mätta mitt nit uppå dig, att jag må tillfrids varda, och icke mer behöfva vredgas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Derföre, att du icke ihågkom dins ungdoms tid; utan rette mig med allt detta; derföre vill jag ock lägga alla dina vägar uppå ditt hufvud, säger Herren Herren; ty du frågar der intet efter, att du så öfverdådeliga allehanda styggelse bedrifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Si, alle de som ordspråk pläga bruka, de skola detta ordspråket säga om dig: Dottren är såsom modren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Du äst dine moders dotter, hvilken ifrå sin man och barn lopp; och äst dina systrars syster, hvilka ifrå sina män och barn lupo; edor moder är Hetheisk, och edar fader en Amoreer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Samarien är din äldre syster, med sina döttrar, som bo på venstra sidone vid dig, och Sodom är din yngre syster, med sina döttrar, som bo på högra sidone vid dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Ändock du likväl icke lefvat hafver efter deras väsende, eller gjort efter deras styggelse, der fattas icke mycket uti, att du icke slemmare ting gjort hafver än de, i allt ditt väsende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Så sant som jag lefver, säger Herren Herren; Sodom din syster, samt med sina döttrar, hafver så icke gjort, som du och dina döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Si, det var dine systers Sodoms missgerning: högmod och all tings öfverflödighet, och god frid, den hon och hennes döttrar hade; men dem fattiga och torftiga gjorde de icke (gerna) hjelp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Utan voro stolta, och gjorde styggelse för mig; derföre hafver jag ock bortkastat dem, då jag begynte se dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Så hafver ock Samarien icke gjort hälftena af dina synder; utan du hafver så mycket mer gjort dina styggelser än hon, att du hafver gjort dina systrar fromma emot all din styggelser, som du gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Så bär ock nu dina skam, du som dina systrar fromma gör genom dina synder, i hvilkom du större styggelser, än de, gjort hafver, och hafver gjort dem frommare än du äst; så skäm dig nu, och bär din skam, att du dina systrar fromma gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Men jag skall omvända deras fängelse, nämliga desse Sodoms fängelse, och hennes döttrars, och desse Samaries fängelse, och hennes döttrars, och desse dins fängelses fångar, samt med dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Så att du måste bära dina skam och hån, för allt det du gjort hafver, och I ändå likväl tröstade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Och din syster, denna Sodom, och hennes döttrar, skola omvända varda, lika som de tillförene varit hafva, och Samarien och hennes döttrar skola omvända varda, lika som de tillförene varit hafva; du också med dina döttrar skolen omvända varda, lika som I tillförene varit hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Och du skall icke mer prisa den samma dina syster Sodom, såsom på dins högmods tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Då din ondska ännu icke upptäckt var, såsom på den tiden då Syrie döttrar och de Philisteers döttrar allestäds skämde dig, och föraktade dig allt omkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Då I måsten bära edra laster och styggelser, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Ty så säger Herren Herren: Jag skall göra dig lika som du gjort hafver, att du föraktade eden och bröt förbundet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Men jag vill tänka uppå, mitt förbund, som jag med dig gjort hafver i dins ungdoms tid; och skall göra ett evigt förbund med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Så skall du komma dina vägar ihåg, och skämmas; då du dina äldre och yngre systrar till dig tagandes varder, de jag dig till döttrar gifva skall, dock icke af ditt förbund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Utan jag vill göra mitt förbund med dig, att du förnimma skall, att jag är Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'På det du skall tänka deruppå och skämmas, och för skams skull icke djerfvas upplåta din mun, när jag dig förlåtandes varder allt det du gjort hafver, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Du menniskobarn, gif Israels huse ena gåto och liknelse före;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Och säg: Detta säger Herren Herren: En stor örn, med stora flygt och långa vingar, och full med fjädrar och brokot, kom uppå Libanon, och tog qvistarna bort af cedreträn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Och bröt den öfversta skatan af, och förde honom in uti krämarelandet, och satte honom uti den staden, der handlingen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Han tog ock frö af de landena, och sådde det uti det samma goda landet, der mycket vatten var, och satte det såsom ett pilträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Och det växte, och vardt ett stort vinträ, dock ganska lågt; ty dess qvistar böjde sig neder emot sina rot, och var alltså ett vinträ, det qvistar och löf fick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Och der var en annar stor örn, med stora vingar och många fjädrar; och si, detta vinträt hade en längtan i sina rötter till denna örnen, och uträckte sina qvistar emot honom, att det måtte vattnadt varda af hans dike;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Och var dock på eno gode lande vid mycket vatten planteradt, så att det väl hade mått fått qvistar, frukt burit, och ett stort vinträ, vordit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Så säg nu: Alltså säger Herren Herren: Skulle det trifvas? Ja, man skall upprycka dess fötter, och afrifva dess frukt, och man skall förtorka alla dess uppväxta qvistar, att de förfalna; och det skall icke ske genom en stor arm eller mycket folk, att man må föra honom af dess rötter bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Si, det är planteradt; men skulle det trifvas? Ja, så snart der kommer ett östanväder till, så skall det förtorkas på sin dike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Käre, säg till det ohörsamma folket: Veten I icke hvad detta är? Och säg: Si, Konungen af Babel kom till Jerusalem, och tog hans Konung och hans Förstar, och förde dem bort till sig uti Babel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Och tog en, af Konungsligo säd, och gjorde ett förbund med honom, och tog en ed af honom; men de väldiga i landens tog han bort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'På det att riket skulle ödmjukadt blifva, och icke upphäfva sig, att förbundet måtte hållet varda och ståndande blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Men den, samma säden föll af ifrå honom, och sände sitt bådskap uti Egypten, att man skulle sända honom hästar och mycket folk; skulle det lycka sig med honom? Eller skulle han komma der väl af med, som sådant gör? Och den som förbund bryter, skulle han slippa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Så sant, som jag lefver, säger Herren Herren, uti den Konungens rum, som honom till Konung satte, hvilkens ed han föraktade, och hvilkens förbund han bröt, der skall han dö, nämliga i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Och skall Pharao intet blifva ståndandes med honom i örligena, med storom här och mycket folk; då man torfvallar uppkasta, och bålverk uppbygga skall, på det att mycket folk skall slaget blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Ty efter han hafver föraktat eden, och brutit förbundet, der han sina hand uppå räckt hafver, ock allt sådant bedrifver, skall han intet kunna undslippa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Derföre säger Herren Herren alltså: Så sant som jag lefver, skall jag låta min ed, den han föraktat hafver, och mitt förbund, som han brutit hafver, komma öfver hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Ty jag skall kasta mitt nät öfver honom, och han måste i min garn fången varda, och jag skall låta honom komma till Babel, och der vill jag vara i rätta med honom; derföre, att han sig så emot mig förgripit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Och alle hans flyktige, som till honom hålla sig, skola falla genom svärd, och de, som af dem slippa, skola i all väder förströdde varda: och I skolen förnimma, att jag, Herren, hafver detta talat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Detta säger Herren Herren: Jag skall också taga en telning af ett högt cedreträ, och bryta honom af, öfverst uppå dess qvistom, och skall plantera honom uppå ett högt berg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Nämliga på det höga berget Israel vill jag plantera honom, på det han skall gro och bära frukt, och varda ett stort cedreträ, så att allehanda foglar skola kunna bo och blifva under honom, och under hans qvistars skugga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Och all trä på markene skola förnimma att jag, Herren, hafver det höga trät förnedrat, och det låga trät upphöjt, och det gröna trät förtorkat, och det torra trät grönskande gjort; jag, Herren, talar det, och gör de också.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Hvad drifven I ibland eder, uti Israels land, detta ordspråket, och sägen: Fäderna hafva ätit sura vindrufvor, men barnomen äro tänderna deraf ömma vordna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Så sant som jag lefver; säger Herren Herren, sådant ordspråk skall intet mer gå ibland eder i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Ty si, alla själar äro mina; fadrens själ är så väl min, som, sonens själ; hvilken själ som syndar, hon skall dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Om nu en menniska är from, den der rätt och väl gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Den på bergomen icke äter, den sin ögon icke upphäfver till Israels hus afgudar; och sina nästas hustru icke besmittar, och icke ligger när qvinno uti hennes krankhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Den ingom skada gör; den gäldenäromen sin pant igengifver; den ingom något ifråtager med våld; den sitt bröd delar med dem hungroga, och kläder den nakota;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Den intet ockrar; den ingen slem vinning tager; den icke hjelper till att göra orätt; den emellan menniskorna rätt dömer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Den efter mina rätter vandrar, och min bud håller, så att han allvarliga gör derefter; det är en from man, han skall få lefva, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Men om han föder en son, och den samme varder en mördare, den der blod utgjuter, eller något af dessa stycke gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Och intet af de andra stycken gör; utan äter på bergom, och besmittar sins nästas hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Gör dem fattiga och elända skada; tager något med våld; icke igengifver pant; upphäfver sin ögon till afgudar, dermed han en styggelse bedrifver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Får ut på ocker; tager vinning; skulle han lefva? Han skall icke lefva; utan efter han sådana styggelse gjort hafver, så skall han döden dö; hans blod skall vara öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Men om han föder en son, den der alla sådana synder ser, som hans fader gör, och han fruktar sig, och så icke gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Äter icke på bergom; upphäfver icke sin ögon till Israels hus afgudar; besmittar icke sins nästas hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Gör ingom skada; behåller icke pant; tager intet med våld; delar sitt bröd med dem hungroga, och kläder den nakota;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Hjelper icke emot den elända; tager intet ocker eller slem vinning; utan håller min bud, och lefver efter mina rätter; han skall intet dö för sins faders missgernings skull, utan lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Men hans fader, den våld och orätt brukat hafver, och ibland sitt folk; det som intet doger, gjort hafver: si, han skall dö för sina missgernings skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Så sägen I: Hvi skall sonen icke bära sins faders missgerning? Derföre, att han hafver gjort rätt och väl, och hållit och gjort alla mina rätter, skall han lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Ty hvilken själ som syndar, hon skall dö; sonen skall icke bära fadrens missgerning; och fadren skall icke bära sonens missgerning, utan dens rättfärdigas fromhet skall vara öfver honom, och dens orättfärdigas arghet skall vara öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Men om en ogudaktig omvänder sig ifrån alla sina synder, som han gjort hafver, och håller alla mina rätter, och gör rätt och väl, så skall han lefva, och icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Men på all hans öfverträdelse, som han gjort hafver, skall intet tänkt varda; utan skall lefva, för den rättfärdighets skull, som han gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Menar du, att jag lust hafver öfver dens ogudaktigas död, säger Herren Herren, och icke mycket mer, att han omvänder sig ifrå sitt onda väsende, och lefver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Och om den rättfärdige vänder sig ifrå sine rättfärdighet, och gör det ondt är, och lefver efter all den styggelse som en ogudaktig gör, skulle han lefva? Ja, all hans rättfärdighet, som han gjort hafver, skall intet ihågkommen varda; utan han skall dö uti sin öfverträdelse och syndom, som han gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Och ändå sägen I: Herren handlar icke rätt. Derföre hörer nu, I af Israels hus: Hafver jag icke rätt, och I orätt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Ty när den rättfärdige vänder sig ifrå sine rättfärdighet, och gör det ondt är, så måste han dö; men han måste dö för sina ondskos skull, som han gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Tvärtom, när den ogudaktige vänder sig ifrå sine orättfärdighet, som han gjort hafver, och gör nu rätt och väl, han varder behållandes sina själ lefvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Ty efter han fruktar sig, och vänder åter af sine ondsko, så skall han lefva, och icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Och ännu säga de af Israels hus: Herren handlar icke rätt. Skulle jag hafva orätt? I af Israels hus hafven orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Derföre vill jag döma eder, I af Israels hus, hvar och en efter hans väsende, säger Herren Herren. Derföre vänder eder om, och låter eder omvända, på det I icke skolen falla för missgerningenes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Kaster ifrån eder all edor öfverträdelse, der I med öfverträdt hafven, och görer eder ett nytt hjerta, och ny anda; ty hvi vill du så dö, du Israels hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Ty jag hafver ingen lust till hans död, som dör, säger Herren Herren; derföre omvänder eder, så fån I lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Men gör en klagogråt öfver Israels Förstar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'Och säg: Hvi ligger din moder lejinnan ibland lejinnorna, och uppföder sina ungar ibland de unga lejon?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'En af dem födde hon upp, och der vardt ett ungt lejon utaf, det vande sig till att rifva och uppäta menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Då Hedningarna hörde sådant om det, grepo de det uti deras kulor, och förde det i kedjor in uti Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Då nu modren såg, sedan hon hade länge hoppats, att hennes hopp var borto, tog hon en annan af sina ungar, och gjorde der ett ungt lejon af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Då det vandrade ibland lejinnorna, vardt det ett ungt lejon, det också vandes till att rifva och uppäta menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Det förderfvade deras hus och deras städer, så att landet, och hvad deruti var, grufvade sig för dess rytandes röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Då lade Hedningarna sig af all land kringom det, och kastade ett nät öfver det, och grepo det i dess kulor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Och satte det uti ett galler, och förde det i kedjor till Konungen i Babel; och man lät förvara det, att dess röst intet mer skulle hörd varda på Israels bergom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Din moder var lika som ett vinträ, som vid vatten planteradt var, och dess frukt och qvistar vuxo af det myckna vattnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Att dess qvistar så starke vordo, att de till herraspiror dogde, och det vardt högt ibland vinträn. Och då man såg, att det så högt var och många qvistar hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Vardt det i grymhet rifvet neder till jordena och förkastadt; östanväder förtorkade dess frukt, och dess starke qvistar vordo sönderbrutne, så att de borttorkades, och uppbrände vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Men nu är det planteradt i öknene, uti eno torro och törstigo lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Och en eld gick utaf dess starka qvistar, den förtärde dess frukt, så att der inge starka qvistar mer uppå äro till några herraspiro; det är en klagelig och jämmerlig ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Och det begaf sig i sjunde årena, på tionde dagen i femte månadenom, kommo någre af de äldsta i Israel till att fråga Herran, och satte sig neder för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Då skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Du menniskobarn, tala med Israels äldsta, och säg till dem: Detta säger Herren Herren: Ären I komne till att fråga mig? Så sant som jag lefver, jag vill intet svar gifva eder, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Men vill du menniskobarn straffa dem, så må du straffa dem alltså: Håll dem före deras fäders styggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Och säg till dem: Detta säger Herren Herren: På den tid jag utvalde Israel, upphof jag mina hand till Jacobs hus säd, och lät dem känna mig uti Egypti land; ja, jag upphof mina hand till dem, och sade: Jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Men jag upphof på samma tid mina hand, att jag skulle föra, dem utur Egypti land, in uti ett land som jag dem försett hade, det med mjölk och hannog flyter; ett ädla land för all land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Och sade till dem: Hvar och en kaste bort styggelsen för sin ögon, och orener icke eder på Egypti afgudar; ty jag är Herren edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Men de voro mig ohörsamme, och ville intet höra mig, och ingen af dem kastade sin styggelse bort för sin ögon, och öfvergåfvo icke Egypti afgudar; då tänkte jag utgjuta mina grymhet öfver dem, och låta alla mina vrede gå öfver dem, midt uti Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Men jag lät det tillbaka, för mitt Namns skull, att det icke skulle ohelgadt varda för Hedningomen, ibland hvilka de voro, och för hvilkom jag hade gifvit mig dem tillkänna, att jag dem utur Egypti land föra ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Och då jag; dem utur Egypti land fört hade, och låtit dem komma in uti öknena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Gaf jag dem min bud, och lärde dem mina rätter, genom hvilka menniskan lefver, den dem håller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Jag gaf dem ock min Sabbath, till ett tecken emellan mig och dem, på det de skulle lära, att jag är Herren, som dem helgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Men Israels hus var mig också ohörsamt uti öknene, och lefde intet efter min bud, och föraktade mina rätter, genom hvilka menniskan lefver, som dem håller, och ohelgade min Sabbath ganska svårliga; då tänkte jag utgjuta mina grymhet öfver dem uti öknene, och platt förgöra dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Men jag lät det tillbaka, för mitt Namns skull, att det icke skulle ohelgadt varda ibland Hedningarna, för hvilkom jag dem utfört hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Ock hof jag mina hand upp emot dem i öknene, att jag icke ville låta dem komma in uti det land, som jag dem gifvit hade, det med mjölk och hannog flyter; ett ädla land för alla land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Derföre, att de föraktade mina rätter, och lefde icke efter min bud, och mina Sabbather ohelgade; ty de vandrade efter deras hjertas afgudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Men mitt öga skonade dem, att jag icke förderfvade eller platt förgjorde dem i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Och jag sade till deras barn i öknene: I skolen icke lefva efter edra fäders bud, och icke hålla deras rätter, och icke orena eder uppå deras afgudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Ty jag är Herren edar Gud; efter min bud skolen I lefva, och mina rätter skolen I hålla, och göra derefter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Och mina Sabbather skolen I helga, att de skola vara ett tecken emellan mig och eder, på det I veta skolen att jag, Herren, är edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Men barnen voro mig ock ohörsam, lefde icke efter min bud, höllo ock icke mina rätter, så att de gjorde derefter, genom hvilka menniskan lefver, den dem håller, och ohelgade mina Sabbather; då tänkte jag utgjuta mina grymhet öfver dem, och låta alla mina vrede gå öfver dem i öknene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Men jag vände mina hand, och lät det tillbaka, för mitt Namns skull, att det icke skulle ohelgadt varda för Hedningomen, för hvilkom jag dem utfört hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Jag hof ock mina hand upp emot dem i öknene, att jag skulle förströ dem ibland Hedningarna, och förskingra dem i landen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Derföre, att de icke höllo min bud, och föraktade mina rätter, och ohelgade mina Sabbather, och sågo efter deras fäders afgudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Derföre gaf jag dem den lära, som intet god är; och de rätter, uti hvilka de intet lif hafva kunna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Och förkastade dem med deras offer då de uppbrände i eld all förstföding; på det jag skulle bedröfva dem, och de lära skulle, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Derföre tala, du menniskobarn, med Israels hus, och säg till dem: Detta säger Herren Herren: Edra fäder hafva ännu mer försmädat och trotsat mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Ty då jag hade låtit dem komma in uti landet, öfver hvilket jag mina hand upphäfvit hade, att jag skulle det gifva dem; hvar de någorstäds sågo en hög backa, eller tjockqvistadt trä, der offrade de sitt offer, och båro dit sina obehageliga gåfvor, och rökte der sin söta rök, och utgöto der sitt drickoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Men jag sade till dem: Hvad skall dock den höjden, dit I gån? Och så kallades det en höjd, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Derföre säg till Israels hus: Detta säger Herren Herren: I orenen eder uti edra fäders väsende, och bedrifven horeri med edor styggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Och besmitten eder på edra afgudar, hvilkom I offren edra gåfvor, och uppbrännen edra söner och döttrar i eld, allt intill denna dag; och jag skulle gifva eder af Israels hus svar? Så sant som jag lefver, säger Herren Herren, jag skall intet svar gifva eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Dertill, då I tänken: Vi vilje göra lika som Hedningarna, och såsom annor folk i landen, och tillbedja stockar och stenar, skall det fela eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Så sant som jag lefver, säger Herren Herren, jag skall råda öfver eder med starka hand och uträcktom arm, och med utgjuten grymhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Och skall föra eder ifrå folken, och församla eder utu de land, dit I förströdde ären, med starka hand, med uträcktom arm, och med utgjuten grymhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Och skall låta eder komma uti folks öken, och der vara i rätta med eder, ansigte emot ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Lika som jag med edra fäder uti öknene vid Egypten i rätta var, rätt så skall jag vara i rätta med eder, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Jag skall låta komma eder under riset, och tvinga eder uti förbundsens bandom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Och jag skall utfäja de affälliga, och de som emot mig öfverträda, ibland eder; ja, jag skall föra dem utu det land, der I nu bon, och intet låta dem komma in uti Israels land, att I lära skolen, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Derföre, I af Israels hus, detta säger Herren Herren: Efter I ju intet viljen höra mig, så görer som eder täckes, och hvar edra tjene sinom afgud; men mitt helga Namn låter härefter oskämdt vara, med edor offer och afgudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Ty detta säger Herren Herren: På mino heligo berge, på de höga bergena Israel, der skall hela Israels hus, och alle de som i landet äro, tjena mig; der skola de vara mig tacknämlige, och der skall jag äska uppå edor häfoffer och edars offers förstling, med allt det I mig helgen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'I skolen varda mig tacknämlige med sötom rök, när jag låter eder komma ifrå folken, och varder eder församlande utu landen, dit I förströdde ären, och jag skull varda helgad i eder för Hedningomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Och I skolen förnimma, att jag är Herren, när jag hafver låtit eder komma in uti Israels land, uti det land, om hvilket jag upphof mina hand, att jag det edra fäder gifva skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Der skolen I tänka uppå edart väsende, och uppå all edar handel, der I utinnan orenade ären, och skolen hafva ett misshag till all edor ondsko, som I bedrifvit hafven;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Och skolen förnimma, att jag är Herren, när jag gör med eder för mitt Namns skull, och icke efter edart onda väsende och skadeliga handel, du Israels hus, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Du menniskobarn, ställ ditt ansigte emot Theman, och tala söderut, och prophetera emot den skogen i den markene söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'Och säg till den skogen söderut: Hör Herrans ord. Detta säger Herren Herren: Si, jag skall upptända i dig en eld, han skall förtära både färsk trä och torr, så att man icke skall kunna utsläcka hans låga; utan allt det som ifrå sunnan norråt står, det skall uppbrändt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'Och allt kött skall se att jag, Herren, det upptändt hafver, och ingen det utsläcka kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Och jag sade: Ack Herre Herre! de säga om mig: Denne talar icke annat än förtäckt ord:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Du menniskobarn, ställ ditt ansigte emot Jerusalem, och tala emot helgedomen, och prophetera emot Israels land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Och säg till Israels land: Detta säger Herren: Si, jag vill till dig, jag skall draga mitt svärd utu skidone, och skall dräpa i dig både rättfärdiga och orättfärdiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Efter jag nu i dig både rättfärdiga och orättfärdiga dräpa vill, så skall mitt svärd fara utu skidone öfver allt kött, ifrå sunnan intill norr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Och allt kött skall förnimma, att jag, Herren, hafver dragit mitt svärd utu skidone, och det skall icke igen instunget varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Och du menniskobarn skall sucka, intilldess att länderna värka uppå dig; ja, bitterliga skall du sucka så att de se det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Och när de så säga till dig: Hvi suckar du? så skall du säga: För det ryktets skull, som kommer, för hvilko all hjerta förskräckas, och alla händer falla neder, allt mod faller, och all knä flyta såsom vatten; si, det kommer, och det skall ske, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Du menniskobarn, prophetera, och säg: Detta säger Herren: Svärdet, ja, svärdet är skärpt och uppfäjadt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Det är skärpt, att det slagta skall; det är fäjadt, att det blänka skall. O huru glade vilje vi vara, om han än gjorde all trä till ris öfver de onda barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Men han hafver utfått ett svärd till att fäja, att man det taga skall; det är skärpt och fäjadt, att man det uti dråparens händer gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Ropa och jämra dig, du menniskobarn; ty det går öfver mitt folk, och öfver alla de der rådande äro i Israel, hvilke till svärdet, samt med mino folke, församlade äro; derföre slå uppå dina länder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Ty han hafver ofta näpst dem; hvad hafver det hulpit? De onda barnas ris vill intet hjelpa, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Och du menniskobarn, prophetera, och slå dina händer tillsamman; ty svärdet skall komma tvefaldt, ja trefaldt; ett mordsvärd, en stor slagtnings svärd, så att det drabba skall i kamrarna, dit de fly.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Jag skall låta klinga svärdet, så att hjertan skola förskräckas, och månge falla skola i alla deras portar; ack! huru blänker det, och hugger åstad till slagtning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Och säga: Hugg, både på högra sidone och den venstra, hvad som förekommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Så vill jag då med mina händer vara glad deröfver, och låta mina vrede gå; jag, Herren, hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Du menniskobarn, gör två vägar, på hvilka komma skall Konungens svärd af Babel; men de skola både gå ifrån ett land; och sätt ett tecken främst på vägen åt stadenom, att det dit visa skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Och gör vägen, så att svärdet må, komma till Rabbath, Ammons barnas, och i Juda, till den fasta staden Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Ty Konungen i Babel skall sätta sig i vägaskälet, främst på båda vägarna, att han skall låta spå för sig, skjuta med pilar om lott, fråga sina afgudar, och skåda lefrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Och spåmen skall visa på högra sidona inåt Jerusalem; att han skall låta föra dit bockar, och stöta der hål uppå, och öfverfalla honom med stort rop och mord, och att han skall låta föra bockar inför portarna, och göra der en vall, och bygga der bålverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Men den spådomen skall honom tycka falsk vara, han svärje så högt som han vill; men han skall tänka uppå missgerningarna, att han skall vinna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Derföre säger Herren Herren alltså: Derföre, att uppå eder tänkt varder för edra missgerningars skull, och eder ohörighet är uppenbar, att man ser edra synder, i allt det I hafven för händer; ja, derföre, att uppå eder tänkt varder, skolen I med våld fångne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Och du ogudaktige och fördömde Förste i Israel, hvilkens dag komma skall när missgerningen till ända kommen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Detta säger Herren Herren: Lägg bort hatten, och tag af kronona; ty der skall hvarken hatt eller krona blifva; utan den sig upphöjt hafver, han skall förnedrad varda, och den sig förnedrat hafver, han skall upphöjd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Jag skall göra den kronona till intet, till intet, till intet; tilldess han kommer, som henne hafva skall; honom vill jag gifva henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Och du menniskobarn, prophetera, och säg: Detta säger Herren Herren om Ammons barn, och om deras försmädande, och säg: Svärdet, svärdet är utdraget, att det slagta skall; det är uppfäjadt, att det dräpa skall, och skall blänka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Derföre, att du lät säga dig falska syner och lögnspådom, på det du ock skall öfvergifven varda ibland de ogudaktiga slagna, hvilkom dagen kom, då missgerningen till ända kommen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Och om det än uti skidona igen instunget vorde, så vill jag dock döma dig, på det rum der du skapad äst, och i det land der du född äst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Och vill utgjuta mina vrede öfver dig; jag skall uppblåsa mine grymhets eld, och öfverantvarda dig sådana menniskom i händer, som bränna och förderfva kunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Du måste varda eldenom till spis, och ditt blod måste i landena utgjutet varda, och man skall icke mer tänka uppå dig; ty jag, Herren, hafver det talat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Du menniskobarn, vill du icke straffa den mordiska staden, och hålla honom före all hans styggelse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Säg: Så säger Herren Herren: O du stad, som utgjuter dinas blod, på det din tid skall komma, och du, som afgudar gör när dig, på det du skall orena dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Du förbryter dig på det blod, som du utgjuter, och orenar dig uppå de afgudar, som du gör, dermed du låter dina dagar nalkas, och beställer att din år komma måste; derföre skull jag göra dig till spott ibland Hedningarna, och till hån i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Både när och fjerran skola de bespotta dig, så att du måste hafva ett skändeligit rykte, och stor jämmer lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Si, Förstarna i Israel hvar och en är mägtig när dig, till att utgjuta blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Fader och moder förakta de; främlinganom göra de våld och orätt; enkor och faderlös barn förtrycka de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Du föraktar min helgedom, och ohelgar mina Sabbather.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Förrädare äro uti dig, på det de skola utgjuta blod; de äta på bergomen, och handla vrångvisliga i dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'De blotta fädernas blygd, och nödga qvinnorna i deras krankhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Och bedrifva styggelig ting, hvar och en med sin skyldmans hustru; de skämma sina egna söners hustrur öfverdådeliga; de göra sina egna systrar, sina fäders döttrar, skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'De taga gåfvor, till att utgjuta blod; de ockra och vinna på hvarannan, och bruka girighet emot sin nästa, och öfverfalla hvarannan, och förgäta mig, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Si, jag slår mina händer tillsamman öfver den girighet, som du bedrifver, och öfver det blod, som i dig utgjutet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Men menar du, att ditt hjerta kan det lida, eller dina händer det fördraga, på den tid, när jag det med dig görandes varder? Jag, Herren, hafver det sagt, och vill också görat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Och skall förströ dig ibland Hedningarna, och bortdrifva dig i landena; och skall göra en ända på dina slemhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Så, att du skall ibland Hedningarna aktad varda, såsom en förbannad, och förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Du menniskobarn, Israels hus är vordet mig till slagg; all deras koppar, tenn, jern och bly, är i ugnenom vordet till slagg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Derföre säger Herren Herren alltså: Efter I nu alle ären slagg vordne, si, så skall jag samka eder tillhopa i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Lika som man tillhopasamkar silfver, koppar, jern, bly och tenn, in uti en ugn, att man må, uppblåsa der en eld under, och smälta det; alltså vill jag ock, i mine vrede och grymhet, sammansamka, inlägga och smälta eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Ja, jag skall sammansamka eder, och uppblåsa mine vredes eld under eder, att I deruti försmälta skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Lika som silfret smälter i ugnenom, så skolen I ock derinne smälta, och förnimma att jag, Herren, hafver utgjutit mina grymhet öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Du menniskobarn, säg till dem: Du äst ett land, som intet står till rensande, såsom ett, der intet regn uppå kommer på vredenes tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'De Propheter, som derinne äro, hafva sig tillhopagaddat, att de skola uppfräta själar, lika som ett rytande lejon, då det röfvar; de rifva till sig gods och penningar, och göra der många enkor inne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Dess Prester drifva orätt under lagsens namn, och ohelga min helgedom; de hålla ingen åtskilnad, emellan heligt och oheligt, och akta intet hvad rent eller orent är, och sköta intet om mina Sabbather, och jag varder ohelgad ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Dess Förstar derinne äro lika som glupande ulfvar, till att utgjuta blod, och förgöra själar för sina girighets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Och dess Propheter bestryka dem med obrukad kalk, predika fåfängelighet, och prophetera dem lögn, och säga: Detta säger Herren Herren; ändock att Herren hafver det intet sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Folket i landena brukar våld, och röfva fritt, och öfverfalla de fattiga och elända, och göra främlingomen öfvervåld och orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Jag sökte ibland dem, om någor ville förtaga och stilla vredena för mig, att jag icke skulle förderfva landet; men jag fann ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Derföre utgöt jag mina vrede öfver dem, och med mine grymhets eld gjorde jag en ända med dem, och gaf dem deras förtjenst uppå deras hufvud, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Du menniskobarn, det voro två qvinnor, ene moders döttrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Dessa bedrefvo horeri uti Egypten, allt ifrå sin ungdom; der läto de handtera sin bröst, och i ungdomenom krama sina spenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Den äldre het Ahala, och hennes syster Ahaliba; och jag tog dem till ägta, och de födde mig söner och döttrar; och Ahala het Samarien, och Ahaliba Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ahala bedrat horeri, då jag hade tagit henne, och var brinnande till sina bolar, nämliga till de Assyrier, som till henne kommo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Till herrar och Förstar, som med silke beklädde voro, och till alla unga lustiga karlar, till resenärar (och vagnar);');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Och bolade med alla dägeliga karlar i Assyrien, och orenade sig men allom deras afgudom, ehvar hon till någon upptänd vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Dertill öfvergaf hon icke sitt horeri med dem uti Egypten, hvilke när henne legat hade ifrå hennes ungdom, och hennes bröst i hennes ungdom kramat, och stort horeri med henne bedrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Då öfvergaf jag henne uti hennes bolars, Assurs barnas, hand, till hvilka hon i lust brinnandes var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'De upptäckte hennes skam, och togo hennes söner och döttrar bort, men henne dråpo de med svärd; och ryktet kom ut, att denna qvinnan straffad var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Då nu hennes syster Ahaliba det såg, brann hon i lusta mycket värre än den andra, och bedref horeri mer än hennes syster;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Och var upptänd till Assurs barn, till herrar och Förstar, som till henne välklädde kommo, till resenärar (och vagnar), och till alla unga lustiga karlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Då såg jag, att de båda hade i lika måtto orenat sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Dock dessa bedref sitt horeri mer; ty då hon såg målade män på väggene i röd färgo, de Chaldeers beläte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Begjordade om deras länder, och spetsota, brokota hattar på deras hufvud, och alle anseende voro såsom väldige män, efter den drägt, som Babels och de Chaldeers barn i deras land hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Brann hon i lusta till dem, så snart hon dem varse vardt, och sände bådskap till dem in uti Chaldeen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Då nu Babels barn till henne kommo, till att sofva när henne, vardt hon genom dem orenad uti sitt horeri, och vardt så orenad, att hon leddes vid dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Och då hennes horeri och skam så allstinges uppenbar var, leddes jag ock vid henne, lika som jag vid hennes syster var ledse vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Men hon bedref sitt horeri, ju mer och mer, och tänkte uppå sins ungdoms tid, då hon sitt horeri bedreref uti Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Och brann i lusta till sina bolar, hvilkas luste var lika som åsnars och hästars.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Och du bedref dina otukt, lika som i dinom ungdom, då de uti Egypten handterade din bröst, och dina spenar kramade vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Derföre, o Ahaliba, detta säger Herren Herren: Si, dina bolar, hvilka du leddes vid, skall jag uppväcka emot dig, och skall låta dem komma allt omkring dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Nämliga Babels barn, och alla Chaldeer, med höfvitsmän, Förstar och herrar, och alla Assyrier med dem, dägeliga unga män, alla Förstar och herrar, riddare och ädlingar, och allahanda resenärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Och de skola komma öfver dig med resigtyg, och med en stor hop folk, och skola belägga dig med spetsar, sköldar och hjelmar, allt omkring; dem vill jag befalla rätten, att de skola döma öfver dig, efter sin rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Jag skall låta mitt nit gå öfver dig, så att de skola handla obarmherteliga med dig; de skola skära dig näsa och öron af, och hvad qvart blifver, det skall falla genom svärd; de skola taga dina söner och döttrar bort, och uppbränna det qvart är i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'De skola draga dig din kläder utaf, och borttaga din prydning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Alltså skall jag göra en ända uppå dine otukt, och ditt horeri med Egypti land, att du icke mer skall upphäfva din ögon efter dem, och icke mer tänka uppå Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Ty så säger Herren Herren: Si, jag skall öfverantvarda dig dem i händer, hvilkas fiende du äst, och på hvilka du hafver släckt din lusta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'De skola hafva sig med dig såsom fiender, och taga bort allt det du hafver sammandragit, och låta dig nakota och blotta, att din skam skall upptäckt varda, samt med dine otukt och horeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Detta skall dig ske för ditt horeris skull, som du med Hedningomen bedrifvit hafver, och orenat dig på deras afgudom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Du hafver gångit på dine systers väg; derföre gifver jag dig ock hennes kalk uti dina hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Detta säger Herren Herren: Du måste dricka dine systers kalk, så djup och så vid som han är; du skall varda till så stort spott och hån, att det skall vara olideligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Du måste dig drucken dricka af den starka drycken och jämren; ty dine systers Samarie kalk är en jämmers och sorgekalk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Den samma måste du slätt utdricka, och slå honom i stycker sönder, och sönderrifva din bröst; ty jag hafver det sagt, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Derföre säger Herren Herren alltså: Derföre, att du hafver förgätit mig, och kastat mig bakom din rygg, så bär ock nu dina otukt och ditt horeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Och Herren sade till mig: Du menniskobarn, vill du icke straffa Ahala och Ahaliba, och hålla dem före deras styggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Huru de hafva bedrifvit horeri, och utgjutit blod, och bedrifvit horeri med afgudom? Dertill uppbrände de sin barn, som de mig födt hade, dem till offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Derutöfver hafva de gjort mig detta: De orenade min helgedom på den tiden, och ohelgade mina Sabbather.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Ty då de slagtade af gudomen sin barn, gingo de på samma dagen in uti min helgedom, till att ohelga honom: si, sådant hafva de begått uti mino huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'De hafva ock sändt båd efter män som utu fjerran land komma skulle; och si, när de kommo, badade du dig, och färgade dig, och prydde dig med smide, dem till äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Och satt på ena sköna säng, för hvilko stod ett bord tillredt; der rökte du uppå, och offrade min oljo deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Der var ett stort glädjerop; och mannomen, som vida vägna ifrå mycket folk och af öknene komne voro, gåfvo de smide uppå deras armar, och sköna kransar på deras hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Men jag tänkte: Hon är van med hor af ålder; hon kan intet återvända af boleri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Ty man går till henne in, lika som man till ena sköko ingår; rätt så går man till Ahala och Ahaliba, de otuktiga qvinnor, in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Derföre skola de män, som rätten fullfölja, straffa dem, lika som man horkonor och blodsutgjuterskor straffa skall; ty de äro horkonor, och deras händer äro fulla med blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Alltså säger Herren Herren: För upp öfver dem en stor hop, och gif dem till sköfvels och rof;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Att de måga stena dem, och stinga dem igenom med sin svärd, och dräpa deras söner och döttrar, och bränna deras hus upp med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Alltså skall jag göra en ända på otuktena i landena, så att alla qvinnor skola se dervid, och icke göra efter slika otukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Och man skall lägga edra otukt uppå eder, och I skolen bära edra afgudars synder, på det I skolen förnimma, att jag är Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Och Herrans ord skedde till mig, i nionde årena, på tionde dagen i tionde månadenom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Du menniskobarn, skrif denna dagen upp, ja rätt denna dagen; ty Konungen i Babel hafver rätt på denna dagen rustat sig emot Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Och gif de ohörsammo folkena en liknelse före, och säg till dem: Detta säger Herren Herren: Sätt till ena gryto, sätt henne till, och gjut der vatten in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Lägg stycken tillsammans deruti, de derin skola, och de bästa stycken, låret och bogen; och fyll henne med bästa märgstycken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Tag det bästa af hjordenom, och gör en eld derunder, till att koka märgstycken, och låt det flux sjuda, och låt märgstycken väl kokas deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Derföre säger Herren Herren alltså: O den mordiska staden, den en sådana gryta är, i hvilko de vederbrända vederläder, och vill intet afgå; tag derut det ena stycket efter det andra, och du torf icke kasta lott om, hvilket först ut skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Ty hang blod är derinne, den han på ena bara häll, och icke på jordena utgjutit hafver, der man dock hade kunnat betäckt det med jord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Och jag hafver också fördenskull samma blod låtit utgjuta uppå ena bara häll, att det icke skulle kunna förskylas; på det grymheten skulle komma öfver dem, och det måtte hämnadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Derföre säger Herren Herren alltså: O du mordiska stad, den jag till en stor eld göra vill:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Bär hit mycken ved; tänd upp elden, att köttet må sudet varda, och bekrydda det väl, att märgstycken vederbrinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Sätt ock grytona tomma uppå elden, på det hon må varda het, och hennes koppar förbrinna, om hennes orenhet bortsmältas, och hennes vederbränna afgå kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Men den vederbrännan, ehuru fast det ock brinner, vill likväl intet afgå; ty det är allt för mycket vederbrändt, och måste försmälta i eldenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Din orenhet är så förhärd, att om jag än gerna ville rensa dig, så, vill du dock intet låta rensa dig ifrå dine orenhet; derföre kan du nu härefter intet mer ren varda igen, tilldess min grymhet hafver släckt sig uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Jag, Herren, hafver det talat; det skall komma, jag skall görat, och intet försummat; jag vill intet skona, eller låta mig det ångra; utan de skola döma dig, efter som du lefvat och gjort hafver, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Du menniskobarn, si, jag skall, genom ena plågo, taga dig bort dins ögons lust; men du skall intet beklaga dig, eller gråta, eller fälla några tårar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Hemliga må du sucka, men ingen dödsklagan föra; utan skall lägga din skrud uppå, och draga dina skor uppå; du skall icke skyla din mun och icke äta sorgebröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Och då jag om morgonen bittida med folkena talat hade, blef mig om aftonen min hustru död; och jag gjorde i den andra morgonen såsom mig befaldt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Och folket sade till mig: Vill du icke kungöra oss, hvad det betyder, som du gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Och jag sade till dem: Herren hafver talat med mig, och sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Säg Israels huse, att Herren Herren säger alltså: Si, jag skall ohelga min helgedom, den edor högsta tröst, edor ögons lust, och edor hjertas önskan är; och edra söner och döttrar, dem I öfvergifva måsten, skola falla genom svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Och I måsten göra, lika som jag gjort hafver; edar mun måsten I intet skyla, och intet sorgebröd äta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Utan skolen sätta edar skrud uppå edor hufvud, och draga edra skor uppå; I skolen intet beklaga eder, eller gråta; utan försmäkta öfver edra synder, och sucka hvar med annar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Och Hesekiel skall allstå vara eder ett tecken, att I göra måsten lika som han gjort hafver, när det så kommer; på det I förnimma skolen, att jag är Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Och du menniskobarn, på den tiden, då jag ifrå dem tager deras magt och tröst, deras ögons lust, och deras hjertas önsko, deras söner och döttrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Ja, på den samma tiden skall en, den der undsluppen är, komma till dig, och förkunna dig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'På den tiden skall din mun, emot den som undsluppen är, upplåten varda, att du skall tala, och icke mer tiga; ty då måste vara dem ett tecken, på det de skola förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Du menniskobarn, ställ ditt ansigte emot Ammons barn, och prophetera emot dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Och säg till Ammons barn: Hörer Herrans Herrans ord: Så säger Herren Herren: Derföre, att I om min helgedom sägen: Hej, det är ohelgadt, och om Israels land: Det är förödt, och om Juda, hus: Det är i fängelse bortfördt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Derföre, si, jag skall öfvergifva dig dem österländska barnomen, att de skola bygga der sina borger, och göra der sina boning; de skola äta dina frukt, och dricka dina mjölk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Och jag skall göra Rabbach till camelastall, och Ammons barn till fårastall; och I skolen förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Ty så säger Herren Herren: Derföre, att du klappade med dina händer, och stampade med dina fötter, och så hånliga gladde dig af att hjerta öfver Israels land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Derföre, si, jag skall uträcka mina hand öfver dig, och gifva dig Hedningomen till spis, och utrota dig ifrå folken, och förgöra dig utu landen, och nederlägga dig, och du skall förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Detta säger Herren Herren: Derföre, att Moab och Seir sagt hafva: Si, Juda hus är lika som andra Hedningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Si, så skall jag öppna Moab sidona i hans städer, och i hans gränsom, dess kosteliga landsens, BethJesimoth, Baal Meon och Kiriathaim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Dem österländska barnomen, samt med Ammons barnom, och skall gifva dem dem till arfs, så att man uppå Ammons barn intet mer tänka skall ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Och skall jag låta gå rätten öfver Moab, att de skola förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Så säger Herren Herren: Derföre att Edom hafver hämnat sig öfver Juda hus, och är med sine hämnd brottslig vorden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Derföre säger Herren Herren alltså: Jag skall uträcka mina hand öfver Edom, och utrota der både folk och fä, och göra det öde, allt ifrå Theman intill Dedan, och fälla dem genom svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Och skall åter hämnas öfver Edom, genom mitt folk Israel, och de skola göra med Edom efter mina vrede och grymhet, att de skola förnimma mina hämnd, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Detta säger Herren Herren: Derföre att de Philisteer hafva hämnats, och släckt sitt gamla hat, efter all sin vilja, med mins folks skada;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Derföre säger Herren Herren alltså: Si, jag skall uträcka mina hand öfver de Philisteer, och förgöra de dräpare, och förstöra dem, som igenlefvas vid hafshamnena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Och göra en stor hämnd uppå dem, och näpsa dem med grymhet; att de förnimma skola att jag är Herren, när jag hafver mina hämnd öfver dem gå låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Och det begaf sig i ellofte årena, på första dagen i (första) månadenom, skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Du menniskobarn, derföre att Tyrus säger om Jerusalem: Hej, de folks portar äro sönderbrutne; hon måste draga in till mig, jag måste herberga den förstörda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Derföre säger Herren Herren alltså: Si, jag vill till dig, du Tyrus, och skall låta många Hedningar utkomma öfver dig, lika som hafvet upplyfter sig med sina böljor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'De skola förderfva murarna i Tyro, och afbryta hans torn; ja, jag skall ock bortsopa stoftet derut, och göra ena bara klippo af honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Och ett skär i hafvena, der man uppå utsträcker fiskagarn; ty jag hafver det talat, säger Herren Herren; och han skall varda Hedningomen till rof;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Och hans döttrar, som i markene ligga, skola genom svärd dräpna varda, och skola förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Ty så säger Herren Herren: Si, jag skall låta komma öfver Tyro NebucadNezar, Konungen i Babel, nordanefter, den en Konung är öfver alla Konungar, med hästar, vagnar, resenärar, och med en stor hop folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Han skall dräpa med svärd dina döttrar, som i markene ligga; men emot dig skall han bygga bålverk, och göra en torfvall, och upphäfva sköldar emot dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Han skall med bockar omkullstöta dina murar, och med sin vapen nederrifva din torn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Stoftet af hans många hästar skall betäcka dig; så skola ock dine murar bäfva af dönen af hans hästar, vagnar och resenärar, när han indrager genom dina portar, såsom man plägar indraga uti den stad, som nederrifven är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Han skall med sina hästars fötter förtrampa alla dina gator; ditt folk skall han dräpa med svärd, och rifva dina starka stodar neder till jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'De skola röfva ditt gods bort, och sköfla din handel; dina murar skola de afbryta, och rifva din sköna hus omkull, och skola kasta dina stenar, trä och stoft, i vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Alltså skall jag göra en ända uppå dins sångs ljud, att man intet mer höra skall klanget af dina harpor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Och jag skall göra ena bara klippo af dig, och ett skär, der man fiskagarn uppå, utsträcker, så att du skall der öde ligga; ty jag är Herren, den detta talar, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Detta säger Herren Herren emot Tyrus: Hvad gäller, att öarna skola bäfva, när du så grufveliga förfaller, och dine sargade sucka, hvilke uti dig skola dräpne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Alle Förstar vid hafvet skola stiga ned af deras säte, och lägga sina kjortlar ifrå sig, och draga af sig sin stickada kläder och skola gå i sorgekläder, och sitta på jordene, och skola förskräckas och häpne varda öfver ditt hastiga fall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'De skola beklaga sig öfver dig, och säga om dig: Ack! huru äst du så platt öde vorden, du namnkunnige stad, du som vid hafvet lågst, och så mägtig vast i hafvena, samt med dina inbyggare, att hela landet måste frukta för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Ack! huru gifva sig öarna öfver ditt fall, ja, öarna i hafvena förskräcka sig för dine ofärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Så säger Herren Herren; Jag skall göra dig till en öde stad, lika som andra städer der ingen uti bor, och låta komma en stor flod öfver dig, att stor vatten skola öfvertäcka dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Och jag skall störta dig neder till dem som fara uti kulona, till de döda, och skall störta dig neder under jordena, och göra dig lika som ett evigt öde, med dem som uti kulona fara; på det att ingen skall bo uti dig, och du icke mer så pråla skall ibland de lefvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Ty hasteliga skall jag göra en ända med dig, att du icke mer skall vara till: så att, när man frågar efter dig, skall då ingen mer kunna finna dig, till evig tid, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Du menniskobarn, gör klagogråt öfver Tyrus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'Och säg till Tyrus, som ligger vid hafvet, och handlar med många öars folk: Detta säger Herren Herren: O Tyrus, du hafver sagt: Jag är den aldraskönaste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Dina gränsor äro midt i hafvena, och dina byggningsmän hafva tillpyntat dig som aldraskönast.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Allt ditt brädeverk hafva de gjort af furoträ af Senir, och låtit föra cedreträ ifrå Libanon, och gjort din mastträ derutaf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Och dina åror af eketrä ifrå Basan, och dina bänkar af elphenben, och stolar af Chittims öar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Ditt segel var af stickadt silke, utaf Egypten, och ditt märke stickadt deruti, och ditt täckelse af gult silke och purpur, ifrå de öar Elisa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'De af Zidon och Arvad voro dine båtsmän, och du hade skickeliga män i Tyro till skeppare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'De äldste och kloke af Gebal måste bygga din skepp; all skepp i hafvena och skeppfolk fann man när dig, de hade sin handel när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'De utaf Persien, Lydien och Libyen voro ditt krigsfolk, hvilke sina sköldar och hjelmar uti dig upphängde, och dermed beprydde dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'De af Arvad voro i dinom här, allt omkring på dina murar, och väktare på din torn; de hängde allestäds sina sköldar på murarna allt omkring, och gjorde dig så dägeligan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Du hade din handel på hafvens, och lät komma allahanda varor, silfver, jern, tenn och bly, in uppå din marknad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Thubal och Mesech handlade med dig, och förde trälar och koppar in uppå din marknad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'De af Thogarma förde dig hästar, och vagnar, och mular, in på din marknad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'De af Dedan voro dine köpmän, och du handlade allestäds på öomen; de sålde dig elphenben och hebenträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'De Syrer hemtade ifrå dig ditt arbete, som du gjorde, och förde rubin, purpur, tapeter, silke och fogel, och christall, in på din marknad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda och Israels land handlade ock med dig, och förde dig till din marknad hvete af Minnith, och balsam, och hannog, och oljo, och mastix.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Hemtade ock Damascus ditt arbete ifrå dig, och allahanda varo, för starkt vin och kosteliga ull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Dan och Javan, och Meussal förde ock på din marknad jernverk, casia och calmus, att du dermed handla skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan handlade med dig med täcken, der man uppå sitter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabien, och alle Förstar af Kedar, handlade med dig, med får, vädrar och bockar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'De köpmän af Seba och Raema handlade med dig, och förde till din marknad allahanda kosteligit speceri, och ädla stenar och guld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran, och Canne, och Eden, samt med de köpmän af Seba, Assur och Chilmad, voro ock dine köpmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Alle handlade de med dig, med kosteligit kläde, med silkes och stickade mantlar, hvilka de uti kosteliga cedrekistor och väl förvarad, till din marknad förde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Men skeppen utaf hafvet voro de yppersta i dinom marknad; alltså äst du mycket rik och härlig vorden midt i hafvena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Och dine skeppmän förde till dig på stort vatten. Men ett östanväder skall sönderbråka dig midt uppå hafvena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Så att dina varor, köpmän, handlare, skaffare, skeppare och skeppbyggare, och dine handterare, och alle dine örligsmän, och allt folket i dig, skola förgås midt uppå hafvena, på den tiden du nederlägges;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Så att ock hamnerna varda bäfvande, för dina skeppares rops skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Och alle de som med årom ro, samt med båtsmän och styromän, skola stiga utu skeppen upp på landet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Och högt ropa öfver dig, bitterliga klaga, och kasta stoft uppå sitt hufvud, och besöla sig i asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'De skola raka sig håret af öfver dig, och draga säcker uppå sig, och af hjertat bitterliga gråta öfver dig och sörja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Och skola deras barn begråta dig: Ack! ho är någon tid så stilla vorden på hafvena, som du Tyrus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Då du dref din handel på hafvena, gjorde du mång land rik; ja, med dina många varor, och dinom köpenskap, gjorde du Konungarna på jordena rika.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Men nu äst du af hafvena stört uti det rätta djupa vattnet, så att din handel och allt ditt folk i dig förgånget är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Alle de, som på öarna bo, förskräckas öfver dig, och deras Konungar grufva sig, och se ömkeliga ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'De köpmän i landena hvissla till dig, att du så hastigt förgången äst, och kan intet mer uppkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Du menniskobarn, säg Förstanom Tyrus: Detta säger Herren Herren: Derföre, att ditt hjerta upphäfver sig, och säger: Jag är Gud; jag sitter på enom stol, såsom en Gud midt uppå hafvena; ändock du äst en menniska, och icke Gud, likväl förhäfver sig ditt hjerta, lika som du vore Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Si, du håller dig klokare än Daniel, så att dig skall intet fördoldt vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Och hafver, genom dina klokhet och förstånd, kommit sådana magt åstad, och församlat rikedomar af guld och silfver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Och hafver, genom dina stora vishet och handtering, till så stora magt kommit; deraf äst du så stolt vorden, att du så mägtig äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Derföre säger Herren Herren alltså: Efter ditt hjerta förhäfver sig, lika som du vore Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Derföre, si, jag skall sända främmande öfver dig, nämliga Hedningarnas tyranner; de skola utdraga sin svärd öfver dina sköna vishet, och göra dina stora äro till skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'De skola störta dig neder i kulona, så att du skall dö midt i hafvena, lika som de slagne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Hvad gäller, om du då för dina dråpare säga skall: Jag är Gud; ändock du ingen Gud äst, utan en menniska, och äst uti dina dråpares hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Du skall dö, lika som de oomskorne, af de främmandes hand; ty jag hafver det sagt, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Du menniskobarn, gör en klagogråt öfver Konungen i Tyrus, och säg till honom: Detta säger Herren Herren: Du äst det aldrahärligasta af ett skönt verk, full med vishet, och öfvermåtton dägelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Du äst en Guds lustgård, och beprydd med allahanda ädla stenar, nämliga med sarder, topatser, diamanter, turkos, omchin, jaspis, saphir, rubin, smaragder och guld, och hafver af begynnelsen, sedan du Konung vardt, prålat med pipo och trummo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Du äst lika som en Cherub, den sig vida uträcker och täcker; och jag hafver satt dig uppå Guds heliga berg, att du ibland carbunkler vandra skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Och vast ganska dägelig af begynnelsen, tilldess din ondska funnen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Ty du äst invärtes full med ondsko vorden, af dine stora handtering, och hafver syndat; derföre skall jag ohelga dig ifrå Guds berg, och skall bortkasta dig, du uträckte Cherub, ifrå de carbunkler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Och efter ditt hjerta förhäfver sig, att du så dägelig äst, och du hafver låtit dina klokhet bedraga dig i ditt prål; derföre skall jag störta dig till jordena, och göra ett vidunder af dig för Konungarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Ty du hafver förderfvat din helgedom, med dine stora ondsko och orättom handel; derföre skall jag låta en eld utgå af dig, den dig förtära skall, och vill göra dig till asko på jordene, så att hela verlden skall se deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Alle de som känna dig ibland Hedningarna, skola grufva sig öfver dig, att du så hastigt förgången äst, och aldrig mer uppkomma kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Du menniskobarn, ställ ditt ansigte emot Zidon, och prophetera emot honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Och säg: Detta säger Herren Herren: Si, jag vill till dig, Zidon, och skall vinna pris uppå dig; att man förnimma skall att jag är Herren, när jag låter gå rätten öfver honom, och uppå honom beviser att jag är helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Och jag skall sända ibland honom pestilentie, och blodsutgjutelse uppå hans gator, och de skola dödssåre falla derinne genom svärd, det öfver dem gå skall allt omkring; och de skola förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Och skall sedan allt omkring Israels hus, der deras fiender äro, intet törne blifva, som dem stinga, eller tistel, som dem ondt göra skola; på det de förnimma skola, att jag är Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Detta säger Herren Herren: När jag Israels hus församlandes varder ifrå folken, dit de förströdde äro, så skall jag uppå, dem bevisa för Hedningomen, att jag är helig; och de skola bo uti sitt land, det jag minom tjenare Jacob gifvit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Och skola bo säkre derinne, och bygga hus, och plantera vingårdar; ja, säkreskola de bo, när jag låter gå rätten öfver alla deras fiendar allt omkring; och de skola förnimma att jag, Herren, är deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Uti tionde årena, på tolfte dagen i tionde månadenom, skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Du menniskobarn, ställ ditt ansigte emot Pharao, Konungen i Egypten, och prophetera emot honom, och emot hela Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Predika, och säg: Detta säger Herren Herren: Si, jag vill till dig, Pharao, du Konung i Egypten, du store drake, som i vattnena ligger, och säger: Strömmen är min, och jag hafver gjort mig honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Men jag skall lägga dig ett bett i munnen, och hänga fiskarna i dina floder vid din fjäll, och skall draga dig utu dinom ström, samt med alla fiskar i dina floder, som vid din fjäll hänga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Jag skall kasta dig med fiskarna bort utu din vatten, in uti öknena; du skall falla uppå markene, och intet igen upphemtad eller församlad varda, utan blifva djuromen på markene, och foglomen under himmelen, till ett as.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Och alle de, som bo uti Egypten, skola förnimma att jag är Herren, derföre att de Israels huse en rörstaf voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Hvilken, då de honom fattade, söndergick, och stack dem genom sidona; när de stödde sig vid honom, gick han sönder, och stack dem i ländena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Derföre säger Herren Herren alltså: Si, jag vill låta svärdet komma öfver dig, och utrota i dig både folk och fä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Och Egypti land skall varda tomt och öde, och de skola förnimma, att jag är Herren; derföre, att han säger: Strömmen är min, och jag hafver gjort honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Derföre, si, jag vill till dig, och till dina strömmar, och skall göra Egypti land tomt och öde, ifrå det tornet i Sevene, allt intill Ethiopiens gränsor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Att deruti hvarken fä eller folk gå eller bo skola, i fyratio år långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Ty jag vill göra Egypti land öde, såsom dess öde gränsor, och låta dess städer öde ligga, såsom andra öde städer, i fyratio år långt; och skall förströ de Egyptier ibland Hedningarna, och förjaga dem bort i landen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Dock detta säger Herren Herren: När de fyratio år ute äro, så skall jag åter samka de Egyptier tillhopa ifrå folken, dit de förströdde varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Och skall omvända Egypti fängelse, och låta dem komma uti Patros land igen, det deras fädernesland är, och skola vara der ett fögo rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Ty det skall vara litet emot annor rike, och intet mer rådandes vara öfver Hedningarna; och jag skall förminska dem, så att de intet råda skola öfver Hedningarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Att Israels hus icke skall mer förlåta sig uppå dem, och synda dermed, att de hålla sig intill dem, och skola förnimma, att jag är Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Och det begaf sig uti sjunde och tjugonde årena, på första dagenom i första månadenom, skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Du menniskobarn, NebucadNezar, Konungen i Babel, hafver fört sin här med stor mödo inför Tyrus, så att all hufvud voro skallot, och alle axlar försletne; och hans arbete är dock ännu honom eller hans här för Tyrus intet lönt vordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Derföre säger Herren Herren alltså: Si, jag skall gifva NebucadNezar, Konungen af Babel, Egypti land, att han skall taga bort allt dess gods, och skall skinna och beröfva det, på det han må gifva sinom här sold;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Men Egypti land vill jag gifva honom för sitt arbete, som han derpå gjort hafver; ty de hafva tjent mig, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'På den tiden skall jag låta växa Israels hus horn, och skall upplåta din mun ibland dem, att de skola, förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Du menniskobarn, prophetera, och säg: Detta säger Herren Herren: Jämrer eder, och säger: Ack! ve den dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Ty dagen är hardt när; ja, Herrans dag är hardt när, en mörk dag; tiden är för handene, att Hedningarna komma skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Och svärdet skall komma öfver Egypten, och Ethiopien måste förskräckas, när de slagne uti Egypten falla, och dess folk bortfördt, och dess grundval upprifven varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Ethiopien, och Libyen, och Lydien, med allahanda folk, och Chub, och de som utaf förbundsens land äro, skola med dem falla genom svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Detta säger Herren: Egypti försvarare måste falla, och dess magts högfärd måste förgås; ifrå tornet i Sevene skola de falla genom svärd, säger Herren Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Och skola öde varda, såsom deras öde gränsor, och deras städer öde ligga ibland andra öde städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Att de skola förnimma, att jag är Herren, då jag gör en eld uti Egypten, så att alle de, som dem hjelpa, skola förderfvade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'På den tiden skola bådskap draga ut ifrå mig till skepps, till att förskräcka Ethiopien, det nu så säkert är, och en förskräckelse skall vara ibland dem, lika som det gick med Egypten, då dess tid kom; ty si, det kommer visserliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Detta säger Herren Herren: Jag skall förminska den myckenhet uti Egypten, genom NebucadNezar, Konungen i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Ty han och hans folk med honom, samt med Hedningarnas tyranner, äro dertill kallade, att de skola förderfva landet, och skola utdraga sin svärd emot Egypten, så att landet skall allestäds med slagna fullt ligga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Och jag skall uttorka strömmarna, och sälja landet uti arga menniskors händer, och skall föröda landet, och hvad deruti är, genom främmande; jag, Herren, hafver talat det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Detta säger Herren Herren: Jag skall förgöra de beläte i Noph, och göra en ända uppå afgudarna, och Egypten skall ingen Första mer hafva, och skall sända en förskräckelse uti Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Jag skall göra Patros öde, och upptända en eld i Zoan, och låta rätten gå öfver No;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Och skall utgjuta min grymhet öfver Sin, det Egypti fasthet är, och skall utrota den myckenhet i No.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Jag skall upptända en eld uti Egypten, och Sin skall ske ångest och nöd, och No skall nederrifvet varda, och Noph dagliga bedröfvas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'De unge män i Aven och PhiBeseth skola falla genom svärd, och qvinnorna fångna bortförda varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Thahpanhes skall hafva en mörkan dag, då jag Egypti ok slåendes varder, så att hans magts högfärd skall derinne en ända hafva; han skall med en sky öfvertäckt varda, och hans döttrar skola fångna bortförda varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Och jag skall låta rätten gå öfver Egypten, att de skola förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Och det begaf sig i ellofte årena, på sjunde dagen i första månadenom, skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Du menniskobarn, jag skall sönderbryta Pharaos arm, Konungens i Egypten; och si, han skall intet förbunden varda, att han helas må; eller med bandom tillbunden varda, att han må stark blifva, och ett svärd fatta kunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Derföre säger Herren Herren alltså: Si, jag vill till Pharao, Konungen i Egypten, och skall bryta hans armar sönder, både den starka och den svaga, att svärdet skall falla honom utu hans hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Och skall förströ de Egyptier ibland Hedningarna, och förjaga dem i landen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Men Konungens armar af Babel vill jag stärka, och gifva honom mitt svärd i hans hand; och skall bryta Pharaos armar sönder, så att han för honom stånka skall, lika som en den till döds sår är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Ja, jag vill stärka Konungens armar af Babel, på det Pharaos armar skola sönderbråkade varda; att de skola veta att jag är Herren, när jag gifver Konungenom af Babel svärdet i handena, att han det öfver Egypti land utdraga skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Och jag förströr de Egyptier ibland Hedningarna, och förjagar dem i landen, att de skola förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Och det begaf sig i ellofte årena, på första dagen i tredje månadenom, skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Du menniskobarn, säg till Pharao, Konungen i Egypten, och till allt hans folk: Huru stor menar du då att du äst?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Si, Assur var lika som ett cedreträ på Libanon, med sköna grenar, och tjockt af löf, och ganska högt, så att dess skate stod högt upp ibland stora tjocka qvistar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Det hade vatten nog, att det högt vardt, och många källor, att det starkt vardt; dess strömmar gingo allt omkring dess rot, och dess bäcker till all trä i skogenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Derföre är det högre vordet än all trä på markene, och fick många grenar och långa qvistar; ty det hade vatten nog till att utbreda sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Alle himmelens foglar bodde uppå dess qvistar, och all vilddjur hade ungar under dess grenar, och under dess skugga bodde mång och stor folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Det hade sköna, stora och långa grenar; ty dess rot hade mycket vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Och intet cedreträ var desso likt i Guds lustgård; furoträn voro dess grenom intet liknande, och mandelträn voro intet emot dess qvistar; ja, det var så dägeligit, att det öfvergick all trä i Guds lustgård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Jag hafver gjort det så skönt, att det fick så många qvistar, att all lustig trä i Guds lustgård båro afund dervid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Derföre säger Herren Herren alltså: Efter han så hög vorden är, att hans skate stod ibland stora, höga, tjocka qvistar, och hans hjerta upphof sig, att han så hög var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Derföre hafver jag gifvit honom dem mägtigasta ibland Hedningarna i händer; han skall vara till verka med honom, och fördrifvan, såsom han med sitt ogudaktiga väsende förtjent hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Att främmande skola utrota honom, nämliga Hedningarnas tyranner, och förskingra honom, att hans qvistar skola ligga på all berg, och i alla dalar, och hans qvistar sönderbrutne vid alla bäcker i landena, så att all folk på jordene måste bortdraga undan hans skugga, och öfvergifva honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Och alle himmelens foglar såto på hans kullfallna bål, och all vilddjur lade sig på hans afhuggna qvistar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'På det härefter intet trä vid vatten skall förhäfva sig af sine höjd, att dess skate ibland stora, tjocka qvistar står, och att intet trä vid vatten skall förhäfva sig öfver de andra; ty de måste alle under jordena, och dödenom öfvergifne varda, lika som andra menniskor, de der uti kulona fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Detta säger Herren Herren: På den tiden, då han nederfor till helvetes, då gjorde jag en klagolåt, att djupet öfvertäckte honom, och hans strömmar måste stilla stå, och de stora vattnen intet löpa kunde; och gjorde det så, att Libanon sörjde öfver honom, och all trä i markene förtorkades öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Jag förskräckte Hedningarna, då de hörde honom falla, då jag nederstörte honom till helvetes, med dem som uti kulona fara; och all lustig trä under jordene unte honom det väl, de ädlesta och bästa på Libanon, och all de som vid vatten ståndit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Ty de måste ock med honom neder åt helvetet, till de slagna med svärd, efter de under hans arms skugga ibland Hedningarna bott hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Huru stor menar du då att du äst, med ditt prål och härlighet, ibland de lustiga trän? Ty du måste med de lustiga trän fara neder under jordena, och ligga ibland de oomskorna, hvilke med svärd slagne äro; alltså skall det gå dig, Pharao, med allo dino folke, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Och det begaf sig i tolfte årena, på första dagen i tolfte månadenom, skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Du menniskobarn, gör en klagogråt öfver Pharao, Konungen i Egypten, och säg till honom: Du äst lika som ett lejon ibland Hedningarna, och såsom en hafsorm, och springer uti dina strömmar, och upprörer vattnet med dina fötter, och gör dess strömmar orena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Detta säger Herren Herren: Jag skall utkasta mitt nät öfver dig med en stor hop folk, hvilke dig skola jaga in uti min garn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Och jag skall draga dig i land, och kasta dig uppå markena, att alle himmelens foglar skola sitta på dig, och all djur på jordene af dig mätt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Och jag skall kasta ditt as uppå bergen, och med dine höjd uppfylla dalar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Landet, der du uti simmar, det skall jag med ditt blod rödt göra, allt intill bergen, så att bäckerna skola af dig fulle varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Och när det nu med dig allt ute är, så skall jag betäcka himmelen, och förmörkra hans stjernor, och öfverdraga solena med moln, och månen skall icke skina.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Allt ljus på himmelen skall jag låta sörja öfver dig, och vill göra ett mörker i ditt land, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Dertill skall jag göra dig mångom till ett förskräckeligit exempel, då jag låter Hedningarna förnimma dina plåga, och mång land, som du intet känner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Mång folk skola grufva sig öfver dig, och deras Konungar förskräckas, när jag låter mitt svärd blänka emot dem, och skola med hast förfäras, att hjertat må gifva sig i dem öfver ditt fall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Ty så säger Herren Herren: Konungens svärd af Babel skall dräpa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Och jag skall fälla ditt folk genom hjeltars svärd, och genom allahanda Hedningars tyranner; de skola förhärja all Egypti härlighet, och nederlägga all dess folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Och jag skall förgöra all dess djur vid de stora vattnen, att ingens menniskos fot, och ingens djurs klöf skall dem oren göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Si, då vill jag göra deras vatten klar, att deras strömmar skola flyta såsom olja, säger Herren Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'När jag hafver förlagt Egypti land, och allt, det i landena är, öde gjort, och slagit alla de som deruti bo, att de skola veta att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Det skall vara en jämmer, den man väl begråta må; ja, många Hedningarnas döttrar skola sådana gråt begå öfver Egypten, och allt dess folk skall man begråta, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Och i tolfte årena, på femtonde dagen i samma månadenom, skedde Herrans ord till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Du menniskobarn, begråt folket uti Egypten, och stört det, samt med de starka Hedningars döttrar, neder under jordena, till dem som uti kulona fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Hvar är nu ditt prål? Stig neder, och lägg dig när de oomskorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'De skola falla ibland de slagna med svärd; svärdet är allaredo fattadt, och utdraget öfver allt dess folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Derom skola tala i helvete de starke hjeltar, med deras hjelpare, hvilke alle der nederfarne äro, och ligga der ibland de oomskorna och slagna med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Der ligger Assur med allt sitt folk, allt omkring begrafven, hvilke alle slagne och genom svärd fallne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Deras grafver äro djupt i kulone, och hans folk ligger allestäds omkring begrafvet, hvilke alle slagne och genom svärd fallne äro, der hela verlden fruktade sig före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Der ligger ock Elam, med allom sinom hop omkring begrafven, hvilke alle slagne och genom svärd fallne, och dit nederfarne äro, såsom de oomskorne, under jordena; der ock hela verlden för fruktade, och måste bära sina skam med dem som uti kulona fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Man hafver lagt dem ibland de slagna, samt med allom deras hop, och de ligga omkring begrafne, och äro alle såsom de oomskome och slagne med svärd, för hvilkom ock hela verlden sig frukta måste; och måste bära sina skam med dem som i kulona fara, och blifva ibland de slagna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Der ligger Mesech och Thubal, med all sin hop omkring begrafven, hvilke alle oomskorne och med svärd slagne äro, för hvilkom ock sig hela verlden frukta måste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Och alle andre hjeltar, som ibland de oomskorne fallne och med deras krigsvärjor till helvetes farne äro, och hafva måst lägga sin svärd under sin hufvud, och deras missgerning öfver deras ben kommen är, hvilke dock förfärlige hjeltar voro i hela verldene; alltså måste de ligga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Så skall du ock visserliga ibland de oomskorna sönderkrossad varda, och ligga ibland dem som med svärd slagne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Der ligger Edom, med sina Konungar och alla sina Förstar, ibland de slagna med svärd, och ibland de oomskorna, med andra som i kulona fara, hvilke dock mägtige varit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Ja, alle Förstar nordanefter måste ock dit, och alle Zidonier som med de slagna nederfarne äro, och deras förskräckeliga magt är till skam vorden, och de måste ligga ibland de oomskorna, och dem som med svärd slagne äro, och bära sina skam, samt med dem som uti kulona fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Dessa skall Pharao få se, och hugna sig med allo sino folke, som under honom med svärd slagne äro, och med sinom hela här, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Ty hela verlden skall dock en dag frukta sig för mig, att Pharao och all hans hop, ibland de oomskorna och med svärd slagna, ligga skall, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Du menniskobarn, predika emot ditt folk, och säg till dem: Om jag läte komma svärdet öfver landet, och folket i landena toge en man ibland sig, och gjorde honom till sin väktare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'Och han såge svärdet komma öfver landet, och blåste uti trummeten, och förvarade folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Hvilken som nu trummetens ljud hörde, och ville icke taga sig vara, och svärdet komme och toge honom bort, hans blod vare öfver hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Ty han hörde trummetens ljud, och tog sig likväl intet till vara; derföre vare hans blod öfver honom; men den som tager sig vara, han, undsätter sitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Men om väktaren såge svärdet komma, och han icke blåste i trummeten, och icke förvarade sitt folk, och svärdet komme och toge några bort, de samme vordo väl för sina synders skull borttagne; men deras blod skall jag kräfva utu väktarens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Och nu du menniskobarn, jag hafver satt dig till en väktare öfver Israels hus; när du hörer något utaf minom mun, att du dem på mina vägnar förvara skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'När jag nu säger till den ogudaktiga: Du ogudaktige måste döden dö; och du säger honom det icke, att den ogudaktige må taga sig till vara for sitt väsende; så skall väl den ogudaktige dö för sitt ogudaktiga väsendes skull, men hans blod vill jag kräfva utu dine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Men förvarar du den ogudaktiga för hans väsende, att han må vända sig derifrå, och han icke vill vända sig ifrå sitt väsende; så skall han för sina synders skull dö, och du hafver frälst dina själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Derföre, du menniskobarn, säg Israels huse: Så hafven I sagt: Vår ondska och våra synder ligga på oss, att vi derunder förgås; huru kunne vi då lefva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Så säg nu till dem: Så sant som jag lefver, säger Herren Herren, jag hafver ingen lust till dens ogudaktigas död, utan att den ogudaktige omvänder sig ifrå sitt väsende och lefver; så omvänder eder dock nu ifrån edart onda väsende; hvi viljen I dö, I af Israels hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Och du menniskobarn, säg till ditt folk: När en rättfärdig gör något ondt, så skall det intet hjelpa honom, att han from varit hafver; och när en ogudaktig from varder, så skall det intet skada honom, att han ogudaktig varit hafver; så kan ock den rättfärdige icke lefva, om han syndar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Ty då jag säger till den rättfärdiga, han skall lefva, och han förlåter sig på sina rättfärdighet, och gör något ondt, så skall all hans fromhet intet ansedd varda, utan han skall dö i sine ondsko, den han gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Men om jag säger till den ogudaktiga, att han skall dö, och han omvänder sig ifrå sina synder, och gör det som rätt och godt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Så att den ogudaktige pant igengifver, och betalar hvad han röfvat hafver, och vandrar efter lifsens ord, så att han intet ondt gör, så skall han lefva, och icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Och alla hans synder, som han gjort hafver, skola förlåtna varda; ty han gör nu det som rätt och godt är, derföre skall han lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Så säger ännu ditt folk: Herren dömer icke rätt; ändock de orätt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Ty om den rättfärdige vänder sig ifrå sine rättfärdighet, och gör något ondt, så dör han ju med skäl derföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Och om den ogudaktige omvänder sig ifrå sitt ogudaktiga väsende, och gör det rätt och godt är, så skall han ju med skäl lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Likväl, sägen I: Herren dömer icke rätt; ändock jag dömer eder af Israels hus, hvar och en efter hans väsende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Och det begaf sig i tolfte årena af vårt fängelse, på femte dagen i tionde månadenom, kom till mig en, som undsluppen var ifrå Jerusalem, och sade: Staden är slagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Och Herrans hand var öfver mig om aftonen, förr än den undsluppne kom, och upplät mig min mun, tilldess han om morgonen till mig kom; och upplät så min mun, att jag intet mer tiga kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Du menniskobarn, de inbyggare i desso öde, i Israels land, säga alltså: Abraham var icke utan en man, och ärfde detta land; men vi ärom månge, så ärfve vi landet rätteligare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Derföre säg till dem: Detta säger Herren Herren: I hafven ätit blod, och upplyft edor ögon till afgudar, och utgjutit blod; och I menen, att I viljen besitta landet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Ja, I hållen fast på att mörda, och gören styggelse, och den ene skämmer den andras hustru; och menen, att I viljen besitta landet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Så säg till dem: Detta säger Herren Herren: Så sant som jag lefver, alle de som i öknene bo, de skola falla genom svärd, och hvad på markene är, det vill jag gifva djuromen till att uppäta, och de som i fäste och i kulom äro, de skola dö af pestilentie;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Ty jag vill platt föröda landet, och göra en ända uppå dess högmod och magt, att Israels berg så öde skola varda, att ingen skall der framgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Och de skola förnimma, att jag är Herren, när jag hafver platt förödt, landet, för all deras styggelses skull, som de göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Och du menniskobarn, ditt folk talar emot dig här och der på gatomen, och för portarna, och den ene säger till den andra: Käre, kommer och låter oss höra, hvad dock Herrans ord är, som han säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Och de skola komma till dig uti församlingene, och sitta för dig såsom mitt folk, och skola höra din ord; men intet göra derefter, utan skola hvissla åt dig, och likväl lefva framgent efter sina girighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Och si, du måste vara deras visa, den de gerna sjunga och spela skola; alltså skola de höra din ord, och intet göra derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Men när det kommer, som komma skall, si, så skola de förnimma, att en Prophet ibland dem varit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Du menniskobarn, prophetera emot Israels herdar; prophetera, och säg till dem: Detta säger Herren Herren: Ve Israels herdom, hvilke föda sig sjelfva; skulle icke herdarna föda hjorden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Men I åten det feta, och klädden eder med ullene, och slagtaden det gödda; men fåren villen I intet föda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'De svaga stärkten I intet, och de sjuka heladen I intet, det såra förbunden I intet, det förvillda hemtaden I icke igen, och det borttappada uppsökten I icke; utan strängeliga och hårdeliga hafven I rådit öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Och min får äro förskingrade, lika som de der ingen herdan hafva, och äro allom vilddjurom till spis vordne, och platt förskingrade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Och gå ville här och der på bergen, och på allom högom backom, och äro förströdd öfver hela landet; och ingen är, som efter dem frågar, eller något sköter om dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Derföre hörer, I herdar, Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Så sant som jag lefver, säger Herren Herren: Efter I låten min får till rofs, och min hjord allom vilddjurom till spis varda, medan de ingen herdan hafva, och mine herdar intet fråga efter min hjord, utan äro sådana herdar, som föda sig sjelfva, men min får vilja de intet föda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Derföre, I herdar, hörer Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Detta säger Herren Herren: Si, jag vill till de herdar, och skall kräfva min hjord utu deras händer, och skall göra en ända med dem, att de skola intet mer herdar vara, och skola intet mer föda sig sjelfva; jag skall frälsa min får utu deras mun, att de intet mer skola uppäta dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Ty så säger Herren Herren: Si, jag skall sjelf taga min hjord till mig, och besöka dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Lika som en herde besöker sin får, då de ifrå sinom hjord förvillde äro; alltså skall jag besöka min får, och skall förlossa dem ifrån all rum, dit de hafva förströdde varit, på den tiden då mulet och mörkt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Jag skall utföra dem ifrån all folk, och församla dem utur all land, och skall föra dem uti deras land, och skall föda dem på Israels bergom, och i allom dalom, och på alla lustiga platser i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Jag skall låta dem komma på de bästa betena, och deras hyddor skola stå på de höga berg i Israel; der skola de ligga uti roliga hyddor, och hafva feta ben på Israels bergom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Jag vill sjelf föda min får, och skall låta dem lägra sig, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Jag skall uppsöka det borttappada, och igenhemta det förvillda, och förbinda det sargada, och stärka det svaga; och hvad fett och starkt är, skall jag bevara; och skall sköta dem såsom de betorfvat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Men till eder, min hjord, säger Herren Herren alltså: Si, jag vill döma emellan får och får, och emellan vädrar och bockar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Är det icke nog, att I så goda bet hafven, och så öfverflödeliga, att I förtrampen det med fötterna; och så sköna källor, till att dricka så öfverflödeliga, att I träden deruti med fötterna, och gören dem orena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Så att min får äta måste det I förtrampat hafven, och dricka det I med edra fötter orent gjort hafven?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Derföre, Så säger Herren Herren till dem: Si, jag skall döma emellan de feta och magra fåren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Derföre, att I springen till med fötterna, och stöten de svaga ifrån eder med edrom hornom, tilldess I förskingren dem all bort ifrån eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Och skall hjelpa minom hjord, att de intet mer skola till rof varda, och skall döma emellan får och får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Och jag skall uppväcka dem en enig Herda, den dem föda skall, nämliga min tjenare David; han skall föda dem, och skall vara deras herde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Och jag, Herren, skall vara deras Gud; men min tjenare David skall vara Försten ibland dem, det säger jag, Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Och jag vill göra ett fridsförbund med dem, och borttaga all ond djur utu landena, att de skola säkre bo i öknene, och i skogomen sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Jag skall välsigna dem och alla mina högar allt omkring, och låta regna uppå dem i rättom tid; det skall vara ett nådeligit regn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Så att trän på markene skola bära sina frukt, och jorden gifva sin växt, och de skola bo säkre i landena, och skola förnimma att jag är Herren, när jag hafver sönderbrutit deras ok, och hulpit dem ifrå deras hand, som de tjena måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Och de skola icke mer varda Hedningomen till rof, och ingen djur på jordene skola mer uppäta dem; utan skola bo säkre utan all fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Och jag skall uppväcka dem ena berömda planto, att de icke mer skola lida hunger i landena, och ingen försmädelse mer lida ibland Hedningarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Och skola veta att jag, Herren deras Gud, när dem är, och att de af Israels hus äro mitt folk, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Ja, I menniskor skolen vara min fosterfår, och jag vill vara edar Gud, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Och Herrans ord skedde till mig, och sade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Du menniskobarn, ställ ditt ansigte emot Seirs berg, och prophetera deremot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Och säg till det: Detta säger Herren Herren: Si, jag vill till dig, du Seirs berg, och utsträcka mina hand emot dig, och göra dig slätt öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Jag skall förlägga dina städer, att du skall varda till ett öde, och förnimma att jag är Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Derföre, att I ju alltid ären Israels barnas fiender, och jagen dem uti svärd, då dem missgår, och deras synder straffade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Derföre, så sant som jag lefver, säger Herren Herren, vill jag ock göra dig blödande, och skall det blödandet icke undslippa; efter du hafver lust till blod, skall du blödandet icke undslippa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Och jag skall göra Seirs berg tomt och öde, så att ingen skall deruppå vandra eller gå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Och skall göra dess berg och alla högar, dalar och alla bäcker, fulla med döda, som med svärd skola slagne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Ja, till ett evigt öde vill jag göra dig, att ingen uti dina städer bo skall, och I skolen förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Och derföre, att du säger: Dessa båda folken, med deras land, måste varda min, och vi vilje taga dem in, bodde än Herren deruti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Derföre, så sant som jag lefver, säger Herren Herren, skall jag göra med dig efter dine vrede och hat, lika som du med dem gjort hafver af blott hat, och skall varda känd när dem, när jag dig straffat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Och du skall förnimma, att jag, Herren, all din försmädelse hört hafver, som du emot Israels berg talat hafver, och sagt: Huj, de äro förödde, och oss gifne till att förderfva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Och hafven berömt eder emot mig, och talat högmodeliga emot mig; det hafver jag hört.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Så säger nu Herren Herren: Efter du hafver allestäds fröjdat dig i ditt land, så skall jag göra dig till ett öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Och lika som du hafver fröjdat dig, och ment att du skulle intaga Israels hus, derföre att det öde var, rätt så vill jag göra med dig, att Seirs berg måste öde varda, samt med hela Edom; och de skola förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Och du menniskobarn, prophetera Israels bergom, och säg: Hörer Herrans ord, I Israels berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Detta säger Herren Herren: Derföre, att fienden säger om eder: Hej, de fasta bergen äro nu vår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Derföre prophetera, och säg: Detta säger Herren Herren: Efter man allestäds föröder och förlägger eder, och I ären dem igenblefna Hedningomen till lott, hvilke allestäds bespotta eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Derföre hörer, I Israels berg, Herrans Herrans ord: Så säger Herren Herren både till berg och högar, till bäcker och dalar, till det förlagda öde, och dess öfvergifna städer, som dem igenlefda Hedningomen allt omkring till rof och spott vordne äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Ja, så säger Herren Herren: Jag hafver i mitt brinnande nit talat emot de qvarblefna Hedningarna, och emot hela Edom, som mitt land intagit hafva med stor berömmelse och högmod, till att förhärja och förlägga det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Derföre prophetera om Israels land, och säg till berg och högar, till bäcker och dalar: Detta säger Herren Herren: Si, jag hafver talat i mitt nit och grymhet, efter I sådana försmädelse af Hedningomen lida måsten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Derföre säger Herren Herren alltså: Jag upphäfver mina hand, att edra grannar, Hedningarna allt omkring skola åter bära sina skam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Men I, Israels berg, skolen grönskas igen, och bära edra frukt mino folke Israel, och det skall ske snarliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Ty si, jag vill vända mig till eder igen, och se till eder, på det I skolen brukade och sådde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Och jag vill göra, att I månge varden, ja, hela Israels hus och städerna skola åter besatte, och öden byggd varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Ja, jag skall gifva eder folk och fä nog, att I skolen föröka eder, och växa till; och jag skall sätta eder derin igen, der tillförene bodden, och skall göra eder mer till godo, än någon tid tillförene, och I skolen förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Jag skall låta komma folk till eder, hvilke mitt folk Israel vara skola; de skola besitta dig, och du skall vara deras arfvedel, och skall icke mer arfvingalös varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Detta säger Herren Herren: Efter man detta säger om eder: Du hafver många menniskor uppätit, och hafver gjort ditt folk arfvingalöst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Derföre skall du nu intet mer uppäta menniskor, eller göra ditt folk arfvingalöst, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Och Hedningarna skola icke mer bespotta dig, eller försmäda dig ibland folk, och du skall intet mer förtappa ditt folk, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Och Herrans ord skedde ytterligare till mig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Du menniskobarn, då Israels hus i sitt land bodde, och orenade det med sitt väsende och gerningom, så att deras väsende var för mig, såsom ene qvinnos orenhet uti hennes krankhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Då utgöt jag mina grymhet öfver dem, för det blods skull som de i landena utgjutit, och det genom sina afgudar orenat hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Och jag förströdde dem ibland Hedningarna, och förjagade dem uti landen, och dömde dem efter deras väsende och gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Och höllo sig lika som Hedningarna, dit de kommo, och ohelgade mitt helga Namn, så att man sade om dem: Är detta Herrans folk, som utu sitt land draga måste?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Men jag förskonade, för mitt helga Namns skull, hvilket Israels hus ohelgade ibland Hedningarna, dit de kommo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Derföre skall du säga till Israels hus: Detta säger Herren Herren: Jag gör det icke för edra skull, I af Israels hus, utan för mitt helga Namns skull, det I ohelgat hafven ibland Hedningarna, till hvilka I komne ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Ty jag vill helga och stort göra mitt Namn, det genom eder för Hedningomen ohelgadt är, det I ibland dem ohelgat hafven; och Hedningarna skola förnimma, att jag är Herren, säger Herren Herren, när jag bevisar mig för dem uppå eder, att jag är helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Ty jag vill hemta eder ifrå Hedningarna, och församla eder utur all land, och låta eder komma uti edart land igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Och vill gjuta rent vatten uppå eder, att I skolen rene varda ifrån all edor orenhet; och ifrån alla edra afgudar skall jag rensa eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Och jag skall gifva eder ett nytt hjerta, och en ny Anda uti eder, och taga bort utur edart kött det stenhjertat, och gifva eder ett hjerta af kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Jag skall gifva min Anda i eder, och göra ett sådana folk af eder, som i min bud vandra, och mina rätter hålla, och derefter göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Och I skolen bo uti det land, som jag edra fäder gifvit hafver, och skolen vara mitt folk, och jag skall vara edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Jag skall göra eder lös ifrån all edor orenhet, och skall säga till sädena, att hon väl trifvas skall, och skall låta eder ingen hunger lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Jag vill föröka fruktena på trän, och växten på markene, på det Hedningarna icke mer skola bespotta eder med hunger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Si, då skolen I tänka uppå edart onda väsende, och edra gerningar, de icke goda voro, och eder skall ångra edra synder och afguderi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Detta vill jag göra, icke för edra skull, säger Herren Herren, att I det veta skolen; utan I måsten då skola skämma eder och blygas, I af Israels hus, öfver edart väsende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Detta säger Herren Herren: På, den tiden, då jag eder rensandes varder ifrån alla edra synder, så vill jag åter besätta dessa städer, och de öde skola åter byggde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Och det förstörda landet skall igen plöjdt varda, derföre att det förhärjat var, att alle, de der framgå, skola det se;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Och säga: Detta landet var färderfvadt, och nu är det lika som en lustgård, och dessa städerna voro förstörde, nederrefne och öde, och stå nu väl uppbyggde, och äro fulle med folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Och de qvarblefne Hedningarna allt omkring eder skola förnimma, att jag är Herren, den der uppbygger hvad nederrifvet är, och planterar det förhärjadt är; jag, Herren, säger det, och gör det ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Detta säger Herren Herren: Israels hus skall finna mig igen, att jag bevisar mig emot dem, och jag skall föröka dem, lika som en menniskohjord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Såsom en helig hjord, såsom en hjord i Jerusalem, på deras högtider, så skola de förhärjade städer varda fulle med menniskohjordar, och skola förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Och Herrans hand fattade mig, och förde mig ut i Herrans Anda, och satte mig på en slättmark, den full låg med (dödas) ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Och han ledde mig derigenom allt omkring, och si, benen lågo der ganska mång på markene, och si, de voro platt förtorkade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Och han sade till mig: Du menniskobarn, menar du ock, att dessa benen åter måga lefvande varda? Och jag sade: Du vetst det, Herre Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Och han sade till mig: Prophetera om dessa benen, och säg till dem: I förtorkade ben, hörer Herrans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Detta säger Herren Herren om dessa benen: Si, jag skall låta komma anda uti eder, att I skolen lefvande varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Jag skall gifva eder senor, och låta kött växa öfver eder, och draga öfver eder hud, och skall gifva eder anda, att I åter Iefvande varden, och skolen förnimma att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Och jag propheterade, såsom mig befaldt var; och der vardt en stor gny, då jag propheterade, och si, benen rörde sig, och kommo åter tillhopa, hvart och ett till sitt ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Och jag såg, och si, der växte senor och kött uppå; och han öfverdrog dem med hud; men der var ännu ingen ande uti dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Och han sade till mig: Prophetera till andan; prophetera, du menniskobarn, och säg till andan: Detta säger Herren Herren: Du ande, kom härtill ifrå de fyra väder, och blås uppå dessa döda, att de varda lefvande igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Och jag propheterade, såsom han mig befallt hade; då kom ande uti dem, och de vordo lefvande igen, och reste sig upp på sina fötter, och de voro en ganska stor hop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Och han sade till mig: Du menniskobarn, dessa benen äro hela Israels hus; si, de säga nu: Vi äre torr ben, och vårt hopp är ute, och vi äre förtappade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Derföre prophetera, och säg till dem: Detta säger Herren Herren: Si, jag skall upplåta edra grifter, och vill hemta eder, mitt folk, derut, och låta komma eder uti Israels land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Och I skolen förnimma, att jag är Herren, då jag hafver öppnat edra grifter, och haft eder, mitt folk, derut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Och jag skall gifva min anda uti eder, att I skolen få lif igen, och jag skall sätta eder uti edart land igen, och I skolen förnimma, att jag är Herren; jag talar det, och jag gör det ock, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Du menniskobarn, gör dig en taflo, och skrif deruppå om Juda och deras medbröder, Israels barn; och gör ändå en taflo, och skrif deruppå om Josephs och Ephraims slägte, och om hela Israels hus, deras medbröder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Och fatta dem båda tillsammans uti dina hand, så att det varder allt en tafla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Om nu ditt folk talar till dig, och säger: Vill du icke kungöra oss, hvad du dermed menar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Så säg till dem: Detta säger Herren Herren: Si, jag vill taga Josephs slägt, den när Ephraim är, samt med deras medbröder Israels slägte, och skall lägga dem intill Juda slägte och göra en slägt af dem bådom i mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Och du skall alltså hålla de taflor, der du uppå skrifvit hafver, uti dine hand, att de måga det se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Och du skall säga till dem: Detta säger Herren Herren: Si, jag vill hemta Israels barn ifrå Hedningarna dit de dragne äro, och skall församla dem ifrån alla orter, och skall låta dem komma uti sitt land igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Och göra allt ett folk utaf dem i landena på Israels bergom; och de skola allesamman hafva en Konung, och skola icke mer tu folk eller uti tu Konungarike delad vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'De skola ej heller mer orena sig med sina afgudar och styggelse, och allahanda synder. Jag skall hjelpa dem utur all rum, der de syndat hafva, och skall rensa dem; och de skola vara mitt folk, och jag vill vara deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Och min tjenare David skall vara deras Konung, och allas deras enige herde; och skola vandra i minom rättom, och hålla min bud, och göra derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Och de skola åter bo i landena, som jag minom tjenare Jacob gifvit hafver, der edra fäder uti bott hafva; de, och deras barn och barnabarn, skola bo deruti evinnerliga, och min tjenare David skall vara deras Förste evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Och jag skall göra med dem ett nåds förbund; det skall vara ett evigt förbund med dem; och skall uppehålla dem, och föröka dem, och min helgedom skall vara ibland dem evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Och jag skall bo ibland dem, och vara deras Gud, och de skola vara mitt folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Så att ock Hedningarna skola förnimma, att jag är Herren, den Israel helig gör, och min helgedom skall vara när dem evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Du menniskobarn, vänd dig emot Gog, som i Magogs land är, och en Förste är af de herrar i Mesech och Thubal, och prophetera om honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'Och säg: Detta säger Herren Herren: Si, jag vill till dig, Gog, du som en Förste äst af de herrar i Mesech och Thubal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Si, jag vill böja dig omkring, och lägga dig ett betsel i munnen, och vill föra dig ut med allom dinom här, hästar och män, hvilke alle väl utredde äro, och utaf dem är en stor hop, som allesammans föra spets, och sköld, och svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Du hafver med dig Perser, Ethioper och Libyer, hvilke allesammans föra sköld och hjelm;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Dertill Gomer, och all hans här, samt med Thogarma hus, som norrut ligger, med allom hans här; ja, du hafver mycket folk med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Nu väl, rusta dig väl, du och alle dine hopar, som med dig äro, och var du deras höfvitsman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Du skall likväl på sistone straffad varda; på yttersta tidenom skall du komma in uti det land, som med svärd igentaget, och utaf mång folk tillsammankommet är, nämliga in på Israels berg, hvilke i lång tid öde varit hafva, och nu utförd äro ifrå mång folk, och bo alle säkre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Du skall uppdraga och komma med en stor storm, och skall vara såsom ett moln, det landet öfvertäcker, du och all din här, och det myckna folket med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Detta säger Herren Herren: På den tiden skall du sådant taga dig före, och skall hafva ondt i sinnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Och tänka: Jag vill öfverfalla det obevarada landet, och komma öfver dem som säkre och utan sorg bo, såsom de der alle sitta utan murar, och hafva hvarken bommar eller portar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'På det du må röfva och skinna, och låta dina hand gå öfver de förstörda, som igenkomne äro, och öfver det folk, som utaf Hedningomen sammanhemtadt är, och skickar sig till att berga sig, och som nogast hafver satt sig, och midt i landena bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Rika Arabien, Dedan, och de köpmän på hafvena, och alle de väldige, som der äro, de skola säga till dig: Jag menar ju du äst rätt kommen till att röfva, och hafver församlat dina hopar till att sköfla, på det du skall borttaga silfver och guld, och församla boskap och ägodelar, och stort rof drifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Derföre prophetera, du menniskobarn, och säg till Gog: Detta säger Herren Herren: Månn du icke märkat, när mitt folk Israel säkert bor?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Så kommer du då ifrå ditt rum, nämliga ifrå de ändar norrut, du och mycket folk med dig, alle till häst, en stor hop, och en mägtig här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Och du skall draga upp öfver mitt folk Israel, lika som ett moln, det landet öfvertäcker. Sådant skall ske på yttersta tidenom; men jag vill derföre låta dig komma in uti mitt land, på det att Hedningarna skola lära känna mig, när jag på dig, o Gog, helgad varder för deras ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Detta säger Herren Herren: Du äst den, der jag i förtiden af sagt hafver, genom mina tjenare Propheterna i Israel, hvilke på den tiden propheterade, att jag ville dig öfver dem komma låta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Och det skall ske på den tiden, när Gog komma skall öfver Israels land, säger Herren Herren, skall min vrede uppstiga uti mine grymhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Och jag talar detta i mitt nit, och i mine vredes eld; ty på den tiden skall ett stort bäfvande varda i Israels land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Att för mitt ansigte bäfva skola fiskarna i hafvet, foglarna under himmelen, djuren på markene, och allt det som kräker och röres på jordene, och alla menniskor, som på jordene äro, och bergen skola omstört varda, och väggar och alle murar nederfalla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Men jag skall kalla svärdet öfver honom, på allom minom bergom, säger Herren Herren, så att hvars och ens svärd skall vara emot den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Och jag skall döma honom med pestilentie och blod, och skall låta regna slagregn med hagelsten, eld och svafvel, uppå honom och hans här, och uppå det myckna folket, som med honom är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Alltså skall jag då härlig, helig och kunnig varda för många Hedningar, att de förnimma skola att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Och du menniskobarn, prophetera emot Gog, och säg: Detta säger Herren Herren: Si, jag vill till dig, Gog, du som en Förste äst af de herrar i Mesech och Thubal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Si, jag skall böja dig omkring, och utlocka dig, och hemta dig ifrå de ändar nordanefter, och låta dig komma in på Israels berg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Och skall slå bågan utu dine venstra hand, och bortkasta dina pilar utu dine högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'På Israels bergom skall du nederlagd varda, du med allom dinom här, och med det folk som när dig är. Jag skall gifva dig foglom ehvadan de flyga, och djurom på markene till spis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Du skall falla på markene; ty jag, Herren Herren, hafver det sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Och jag skall kasta eld uppå Magog, och uppå dem som i öarna säkre bo, och de skola förnimma, att jag är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Ty jag vill göra mitt helga Namn kunnigt ibland mitt folk Israel, och skall icke längre låta skämma mitt helga Namn; utan Hedningarne skola förnimma, att jag är Herren, den Helige i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Si, det är allaredo kommet och skedt, säger Herren Herren; det är den dagen, der jag om talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Och borgarena uti Israels städer skola utgå, och göra en eld, och uppbränna vapnen, sköldar, spetsar, bågar, pilar, stafrar och stänger, och skola dermed uppehålla eld i sju år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Så att man intet skall behöfva sammanhemta någon ved på markene, eller hugga i skogenom, utan med de vapen skola de uppehålla eld, och skola skinna dem, af hvilkom de skinnade voro, och sköfla dem, af hvilkom de sköflade voro, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Och det skall på den tiden ske, att jag skall gifva Gog ett rum till begrafning i Israel, nämliga den dalen der man går till hafvet österut; så att de der framgå, skola grufva sig derföre, efter man der hafver begrafvit Gog med sinom hop; och det skall kallas Gogs hops dal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Men Israels hus skall begrafva dem i sju månader långt, att landet skall dermed rensadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Ja, allt folket i landena skall hafva till skaffa med deras begrafning, och skall hafva berömmelse deraf, att jag på den dagen mina härlighet bevisat hafver, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Och de skola utskicka män, som allestäds gå omkring i landena, och med dem dödgrafvare, till att begrafva de igenblefna på landena, att det må rensadt varda; efter sju månader skola de begynna ransaka derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Och de som omkring landet gå, och någorstäds ene menniskos ben se, de skola uppresa der ett tecken, tilldess att dödgrafvarena begrafva dem också med uti Gogs hops dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Så skall ock staden heta der Hamona. Alltså skola de rensa landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Nu, du menniskobarn, så säger Herren Herren: Säg allom foglom, ehvadan de flyga, och allom djurom på markene: Församler eder, och kommer hit, kommer tillhopa allt omkring till mitt slagtoffer, det jag slagtar eder till ett stort slagtoffer, på Israels bergom; och äter kött, och dricker blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'De starkas kött skolen I äta, och förstarnas blod på jordene skolen I dricka; vädrars, lambars, bockars, oxars, hvilke allesammans fete och välgödde äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Och skolen äta det feta, så att i mätte varden, och dricka blodet, att I druckne varden af det slagtoffer, som jag eder slagtar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Mätter eder nu öfver mitt bord, af hästar och resenärar, af starkom och allahanda krigsfolke, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Och jag skall låta komma mina härlighet ibland Hedningarna, att alle Hedningar skola se min dom, som jag hafver gå låtit, och mina hand, den jag uppå dem lagt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Och Israels hus alltså, förnimma skall, att jag, Herren, är deras Gud, ifrå den dagen och allt framåt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Och desslikes alle Hedningar skola förnimma, att Israels hus för sina missgerningars skull, och för det de emot mig syndat hade, bortförde voro; hvarföre jag fördolde mitt ansigte för dem, och öfvergaf dem uti deras fiendars händer, så att de allesamman genom svärd falla måste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Såsom deras synder och öfverträdelse förtjent hade, gjorde jag dem, och fördolde alltså mitt ansigte för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Derföre så säger Herren Herren: Nu vill jag förlossa Jacobs fångar, och förbarma mig öfver hela Israels hus, och nit hafva om mitt helga Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Men de skola gerna bära sin försmädelse och sina synder, der de med emot mig syndat hafva, när de säkre uti sitt land bo måga, så att dem ingen förskräcker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Och jag dem ifrå, folken hem igen hemtat, och utu deras fiendars land församlat hafver, och jag i dem helgad vorden är, inför många Hedningars ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Alltså skola de förnimma, att jag, Herren, är deras Gud, som dem hafver Iåtit bortföra ibland Hedningarna, och åter låtit församla dem uti sitt land igen, och icke en af dem der blifva låtit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Och skall icke mer fördölja mitt ansigte för dem; ty jag hafver utgjutit min Anda öfver Israels hus, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Uti femte och tjugonde årena af vårt fängelse, på tionde dagen i första månadenom, det är det fjortonde året efter att staden förderfvad vardt, rätt på samma dagen kom Herrans hand öfver mig, och förde mig ditbort,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Genom Guds syn, nämliga uti Israels land, och satte mig uppå ett ganska högt berg; der såg jag ena syn uppe, lika som en byggd stad söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Och då han mig ditfört hade, si, då var der en man, hvilkens ansigte blänkte lika som koppar; han stod i portenom, och hade ett mätesnöre och ena mälestång i sine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Och han sade till mig: Du menniskobarn, se och hör grant till, och tag väl vara uppå hvad jag dig visa vill; ty fördenskull hafver jag haft dig hit, att jag dig det visa skall; på det att du allt det, som du här ser, Israels huse förkunna skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Och si, der gick en mur utanom huset; allt omkring, och mannen hade mälestångena i handene; den var sex alnar och en tvärhand lång; och han mälte byggningen till vidd och höjd, allt med ene stång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Och han kom till porten, som österut låg, och gick der uppåt hans trappor, och mälte syllena åt porten, hvartdera en stång bred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Och kamrarna, som på båda sidor vid porten voro, mälte han ock, efter längden en stång, och efter bredden en stång; och rummet emellan kamrarna var fem alnar bredt. Och han mälte också syllena under förhuset, innanför porten, en stång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Och han mälte förhuset innan porten; det var en stång;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Och mälte förhuset till porten, åtta alnar, och dess hofmäjor deruppå, hvilka voro två alnar; men förhuset stöd innanför portenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Och kamrarna voro tre på hvarjo sidone vid porten östantill, ju en så vid som den andre; och på båda sidor stodo hofmäjor, hvilka voro lika stora.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Sedan mälte han bredden till dörren i porten, nämliga tio alnar, och höjden åt portenom, tretton alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Och frammanför kamrarna voro rum på båda sidor, ju en aln brede; men kamrama voro ju sex alnar på båda sidor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Dertill mälte han hela rummet ifrå kammaren på den ena sidone vid porten allt intill kammaren på den andra sidone, det voro fem och tjugu alnar, och den ena dörren stod emot den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Han gjorde ock torn, sextio alnar hög, och för hvart tornet en fri plan, vid porten allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Och intill förhuset åt innersta portenom, der man ingår, voro femtio alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Och der voro smal fenster på kamrarna och tornen innantill, vid porten allt omkring; alltså voro ock fenster på förhusen allt omkring, och ofvanuppå tornen allt omkring var ett skönt löfverk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Och han hade mig fram bätter intill den yttra gården; och si, der voro kamrar och golf framför gårdenom allt omkring, och tretio kamrar på golfvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Och golfvet emellan båda portarna nedantill var så långt, som ifrå den ena porten intill den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Och han mälte breddena af den nedra porten för den inra gården utantill, hundrade alnar både emot öster och norr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Alltså mälte han ock porten, som norrut låg, till yttra gården, till längd och bredd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Den hade ock hvarjo sidone tre kamrar; och hade desslikes sin torn och förhus, lika så stor som uppå den förra porten, femtio alnar i längdene, och fem och tjugu alnar i breddene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Och hade sammalunda sin fenster och sina förhus, och löfverk på tornen, lika som den porten östantill, och hade sju trappor, der man uppgick, och hade sin förhus der före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Och han mälte hundrade alnar ifrå den ena porten intill den andra; och porten till det inra förhuset var tvärtemot den porten som var norrut, och östantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Derefter hade han mig ock ut söderuppå; och si, der var ock en port, och han mälte hans torn och förhus, lika så stor som de andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'De hade ock fenster och förhus omkring, lika som de andra fenster, femtio alnar långt, och fem och tjugu alnar bredt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Och der voro också sju trappor uppföre, och ett förhus der före, och löfverk i hans torn på hvar sido.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Och han mälte också den porten åt inra gården söderut, nämliga hundrade alnar ifrå den ena södra porten till den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Och han hade mig fram bätter genom den södra porten in uti inra gården, och mälte den samma porten sunnantill, lika så stor som de andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Med hans kamrar, tom och förhus, och med fenster och förhus deruppå, lika så stor som de andra allt omkring, femtio alnar långt och fem och tjugu alnar bredt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Och der gick ett förhus omkring, fem och tjugu alnar högt, och fem alnar bredt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Det samma stod frammanför den yttra gården, och hade också löfverk på sin torn; men der voro åtta trappor, der man uppgick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Sedan hade han mig ock till den inra porten österut, och mälte honom lika så stor som de andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Med hans kamrar, torn och förhus, och deras fenster, och förhus allt omkring, lika så stor som de andra, femtio alnar långt, och fem och tjugu alnar bredt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Och hade också ett förhus emot den yttra gården, och löfverk på tornen på båda sidor, och åtta trappor uppföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Sedan hade han mig ock till den porten norrut; den mälte han lika så stor som de andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Med hans kamrar, torn och förhus, och deras fenster, och förhus allt omkring, femtio alnar långt, och fem och tjugu alnar bredt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Och hade också ett förhus emot den yttra gården, och löfverk på tornen på båda sidor, och åtta trappor uppföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Och nedanpå tornen till hvar porten var en kammar med en dörr, der man tvådde bränneoffret inne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Men uti förhusena för portenom stodo på hvar sidon tu bord, der man bränneoffer, syndoffer och skuldoffer uppå slagta skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Och utantill vid sidorna, der man uppgår till porten norrut, stodo ock tu bord, och uppå den andra sidone, vid portens förhus, ock tu bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Alltså stodo på hvar sidon för portenom fyra bord, det äro åtta bord tillsammans, der man uppå slagtade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Och de fyra borden, gjorde till bränneoffer, voro af huggen sten, ju halfannor aln lång och bred, och en aln hög; der man uppå lade allahanda tyg, der man bränneoffer och annor offer med slagtade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Och der gingo listor omkring, inböjda en tvärhand höga; och uppå de borden skulle man lägga offerköttet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Och utanför den inra porten voro kamrar till sångare uti inra gården, en vid sidona åt den porten nordantill; han vände sig söderuppå: den andre vid sidona åt den porten östantill, den vände sig norruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Och han sade till mig: Den kammaren söderuppå liggandes hörer dem Prestomen till, som i husena tjena skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Men den kammaren norruppå hörer dem Prestomen till, som till altaret tjena; det äro Zadoks barn, hvilke allena af Levi barnom skola träda fram för Herran, till att tjena honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Och han mälte planen i husena, nämliga hundrade alnar långt, och hundrade alnar bredt, i fyrkant; och altaret stod rätt frammanför templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Och han hade mig in uti förhuset åt templet, och mälte porten af förhuset, och väggarna på båda sidor; de voro hvardera fem alnar breda, och hvar dörren på båda sidor var tre alnar bred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Men förhuset var tjugu alnar högt, och ellofva alnar bredt, och hade trappor, der man uppgick; och pelare stodo nedan under tornen, en på hvar sido.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Och han hade mig in uti templet, och mälte pelarena; de höllo på hvar sidon sex alnars bredd, så bredt som huset var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Och dörren var tio alnar bred; men väggarna på båda sidor vid dörrena voro hvardera fem alnar breda; och han mälte rummet i templena; det höll fyratio alnar i längdene, och tjugu alnar i breddene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Och han gick in uti det inra, och mälte pelaren till porten; den höll två alnar, och porten höll sex alnar, och var hela portens bredd sju alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Och han mälte tjugu alnar i längdene, och tjugu alnar i breddene, innantill i templena, och han sade till mig: Detta är det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Och han mälte sex alnar högt på väggarna af templet; der voro gånger uppe allestäds omkring, skifte uti kamrar; de voro allestäds fyra alnar vide.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Och de samma kamrarna voro på hvar sidan tre och tretio, ju den ene vid den andra; och der stodo pelare nedre utmed väggarna af huset allt omkring, som uppehöllo dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Och ofvanuppå dessom voro ännu flere gånger omkring, och voro gångerna ofvantill vidare, så att man gick utaf den nedersta upp uti den medlersta, och utaf dem medleresta in uti den öfversta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Och hvar stod i ju sex alnar öfver den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Och öfversta gångens bredd var fem alnar, och pelarena båro uppe gångerna på husena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Och det var ju, ifrå den ena väggene i husena intill den andra, tjugu alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Och der voro två dörrar upp till vindstenen, en norrut, den andra söderut; och vindstenen var fem alnar vid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Och muren vesterut var fem och sjutio alnar bred, och niotio alnar lång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Och han mälte längdena af huset, den hade öfverallt hundrade alnar mur, och hvad dermed var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Och vidden frammanför huset, östantill, med det som dervid stod, var också hundrade alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Och han mälte längdena af byggningene, med allt det dervid stod, ifrå den ena ändan till den andra; det var på hvar sidon hundrade alnar, med det inra templet och förhusen i gårdenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Samt med dörrar, fenster, hörn och de tre gånger, och brädeverk allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Han mälte ock huru högt det var ifrå jordene upp till fenstren, och huru bred fenstren vara skulle, och mälte ifrå dörrene allt intill det aldrahelgasta, utantill och innantill allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Och på hela husena allt omkring ifrå nedan och allt uppåt, på dörrom och väggom, voro Cherubim och löfverk, gjordt emellan Cherub och Cherub, och hvar Cherub hade tu hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'På ene sidone såsom ens menniskos hufvud, på den andra sidone såsom ett lejons hufvud; detta var gjordt i hela huset rundtomkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Frå golfvet allt uppåt öfver dörren voro Cherubim och löfverk gjorde; desslikes på väggena af templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Och dörren i templet var fyrkant, och all ting var slögliga fogadt in uti det andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Och träaltaret var tre alnar högt, och två alnar långt och bredt, och dess hörn och alla dess sidor voro af trä. Och han sade till mig: Detta är bordet, som för Herranom stå skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Och dörrarna, både åt templet och åt det aldrahelgasta,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Hade två vingar, de man upp och till lät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Och der voro också Cherubim och löfverk uppå, lika som på väggomen, och der voro starke bommar före in mot förhuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Och voro trång fenster, och mycket löfverk allt omkring, på förhusens, och på väggomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Och han hade mig ut bort uti yttra gården norrut, ibland de kamrar som lågo emot den byggningen, som vid templet stod, och emot templet norrut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Hvilken plan hundrade alnar lång var, ifrå portenom norrut, och femtio alnar bred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Tjugu alnar voro emot den inra gården, och emot golfvet i yttra gårdenom, och tretio alnar ifrå det ena hörnet intill det andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Och innantill för kamrarna var en plan, tio alnar bred; en väg af en aln, och deras dörrar norrut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Och ofvan denna kamrarna voro andre trängre kamrar; ty rummet i de nedra och medelkamrarna var icke stort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Ty det var tregge bottnar högt, och hade dock inga pelare, såsom gårdarna pelare hade; utan voro satte slätt hvar uppå den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Och den yttre gården var omfattad med en mur, der kamrarna vid stodo; den var femtio alnar lång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Och kamrarna stodo hvar efter den andra, och femtio alnar långt vid yttra gården; men rummet för templet var hundrade alnar långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Och nedanför kamrarna var en plan österut, der man utur yttra gårdenom gick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Och vid muren östantill voro ock kamrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Och der var också en plan före, lika som för de andra kamrarna nordantill; och all ting var lika, med längd, bredd, och allt det deruppå var, såsom tillförene på de andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Och sunnantill voro ock lika sådana kamrar, med dörrar, och för planenom var den dörren söderut, der man framkommer ifrå den muren som östantill ligger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Och han sade till mig: De kamrar norrut, och de kamrar söderut emot templet, de höra till helgedomen, der Presterna inne äta, då de offra Herranom det aldrahelgasta offret, och de skola der inlägga det aldrahelgasta offret, nämliga spisoffer, syndoffer och skuldoffer; ty det är ett heligt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Och då Presterna gå derin, skola de icke gå åter utu helgedomenom igen uti yttra gården; utan skola tillförene aflägga sin kläder, der de uti tjent hafva, in uti samma kammaren; ty de äro helig; och de skola draga sin andra kläder uppå, och sedan utgå ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Och då han hade mält allt huset innantill, hade han mig ut till den porten österut, och han mälte ifrå honom allt deromkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Österut mälte han femhundrade stänger långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Och norrut mälte han ock femhundrade stänger långt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Desslikes söderut, ock femhundrade stänger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Och då han kom vesterut, mälte han ock femhundrade stänger långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Alltså höll muren, den han mält hade, i fyrkant, på hvar sidon femhundrade stänger, allt omkring, att det helga skulle åtskildt vara ifrå det ohelga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Och han hade mig åter till den porten österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Och si, Israels Guds härlighet kom östanefter, och fräste lika som ett stort vatten fräser, och det vardt ganska ljust på jordene af hans härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Och det var rätt såsom den synen, som jag sett hade vid den älfvena Chebar, då jag kom, att staden skulle förstörd varda; då föll jag neder uppå mitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Och Herrans härlighet kom in uti huset genom den porten österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Då upptog mig ett väder, och förde mig in uti den inra gården; och si, huset var alltsammans ljust af Herrans härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Och jag hörde ena röst utu huset, och en man stod när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Han sade till mig: Du menniskobarn, detta är min stol, der jag uppå sitter, der jag evinnerliga uti bo vill ibland Israels barn; och Israels hus skall icke mer orena mitt helga Namn, hvarken de eller deras Konungar, genom deras horeri, och genom deras höjder och grifter, der deras Konungar uti ligga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Hvilke sin tröskel satte vid min tröskel, och sina dörrar vid mina dörrar, så att der icke var utan en vägg emellan mig och dem; och orenade så mitt helga Namn, genom sin styggelse som de gjorde; hvarföre jag ock förtärde dem i mine vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Men nu skola de bortlägga sitt horeri och sina Konungars grifter ifrå mig, så vill jag bo när dem evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Och du menniskobarn, visa Israels huse templet, att de måga skämma sig vid sina missgerningar, och låt dem taga sig en fazun deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Och när de nu skämma sig vid alla sina gerningar, så visa dem skapnaden och fazunen af huset, dess utgång och ingång, och allt dess sätt, ordning, seder och rätter; och skrif dem det före, att de dess sätt och seder hålla måga, och göra derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Men så skall man hållat i husena; på bergshöjdena, så vidt som det begripet är, skall det aldrahelgasta vara; si, så skall det hållas i husena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Men detta är måttet af altaret, efter den aln som en tvärhand längre är, än eljest en aln: dess botten är en aln hög, och en aln bred, och altaret räcker upp till listan, som är allt omkring en spann bred; och detta är höjden af altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Ifrå bottnen på jordene intill nedra steget äro två alnar till höjden, och en aln till breddena; men ifrå det mindre steget intill det större äro fyra alnar höjden, och en aln bredden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Och HarEl fyra alnar hög, och ifrå AriEl uppåt fyra horn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Och AriEl var tolf alnar lång, och tolf alnar bred, i fyrkant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Och en skifva var öfver stenenom fjorton alnar lång, och fjorton alnar bred, i fyrkant, och en lista gick der allt omkring, en half aln bred; och dess botten var en aln hög, och dess trappor voro österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Och han sade till mig: Du menniskobarn, detta säger Herren Herren: Detta skall vara altarets brukning, när man offrar, att man lägger der bränneoffer uppå, och stänker der blod uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Och Prestomen i Levi utaf Zadoks slägt, hvilke framför mig gå till att tjena mig, säger Herren Herren, skall du få en ung oxa till syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Och af hans blod skall du taga, och bestänka dermed dess fyra horn, och de fyra hörnen af skifvone, och omkring listona; der skall du skära det med och försonat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Och skall taga syndoffrens oxa, och uppbränna honom enstads i husena, som dertill skickadt är, utanför helgedomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Men på annan dagen skall du offra en getabock, den utan vank är, till ett syndoffer, och skära altaret dermed, lika som det med oxanom skärdt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Och när det skärandet skedt är, skall du offra en ung stut, den utan vank är, och en vädur af hjordenom utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Och skall offra dem båda för Herranom, och Presterna skola strö salt deruppå, och skola så offra dem Herranom till bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Alltså skall du i sju dagar, den ena efter den andra, dageliga offra en bock till syndoffer, och de skola offra en ung stut, och en vädur af hjordenom, de både utan vank äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Och skola alltså försona altaret i sju dagar långt, och rena det, och fylla sina händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Och efter de sju dagarna skola Presterna på åttonde dagen, och sedan alltid, offra på altarena sitt bränneoffer och tackoffer; så vill jag vara eder nådelig, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Och han hade mig åter intill yttra porten åt helgedomen österut; men han var tillsluten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Och Herren sade till mig: Denne porten skall blifva tillyckt, och icke upplåten varda, och der skall ingen gå igenom, utan allena Herren Israels Gud, och skall dock tillyckt blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Undantagen Förstan; ty Försten skall sitta deri, till att äta bröd inför Herranom; genom förhuset skall han ingå, och genom det samma åter utgå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Sedan hade han mig bort till den porten för husena norrut; och jag såg, och si, Herrans hus vardt fullt med Herrans härlighet, och jag föll neder på mitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Och Herren sade till mig: Du menniskobarn, märk grant till, och se och hör granneliga på allt det jag dig säga vill, om alla seder och ordningar i Herrans hus, och gif akt uppå, huru man sig i helgedomenom hålla skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Och säg de ohörsamma Israels huse: Så säger Herren Herren: I af Israels hus hafven nog med bedrifvit med all edor styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Ty I läten komma främmande folk, de ett oomskoret hjerta och oomskoret kött hafva, in uti min helgedom, der I med ohelgen mitt hus, när I offren mitt bröd, talg och blod, och bryten alltså mitt förbund med all edor styggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Och hållen icke mins helgedoms sätt; utan gören eder sjelfve ett nytt sätt i minom helgedom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Derföre säger Herren Herren alltså: Ingen främmande af oomskoret hjerta och oomskoret kött skall komma in uti min helgedom, af allom främmandom, som ibland Israels barn äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Ja, ej heller de Leviter, som ifrå mig trädde, och med Israel efter deras afgudar ville gångne äro; derföre skola de bära sina synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Men de skola vakta dörrena uppå mins helgedoms hus, och der göra tjenstena, och skola slagta bränneoffer och annat offer, som folket frambär, och stå för Prestomen, att de skola tjena dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Derföre, att de hafva tjent dem för deras afgudom, och gifvit Israels huse en förargelse till synd; derföre hafver jag räckt ut mina hand öfver dem, säger Herren Herren, att de måste bära sina synd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Och skola icke offra för mig eller vara mine Prester, ej heller i min helgedom komma till det aldrahelgasta; utan skola bära sina skam och sin styggelse, som de gjort hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Derföre hafver jag gjort dem till dörravaktare i husens tjenst, och till allt som der göras skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Men de Prester af Leviterna, Zadoks slägte, som mins helgedoms sätt hållit hafva, då Israels barn afföllo, de skola gå framför mig, och tjena mig, och stå för mig, att de skola offra mig talg och blod, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Och de skola ingå uti min helgedom, och träda inför mitt bord, till att tjena mig, och hålla mitt sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Och då de vilja ingå genom en port åt den inra gården, så skola de draga linnkläder uppå, och hafva intet ullet uppå, så länge de derinne i inra gårdenom tjena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Och skola hafva linna hufvor på sin hufvud, och linna nederkläde om sina länder, och skola icke omgjorda sig allt för hårdt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Och då de gå utu den yttra gårdenom till folket, skola de draga utaf de kläder, som de hafva uti tjent, och lägga dem uti helgedomens sacristie, och åter draga de andra kläden uppå, att folket icke skall synda uppå deras helga kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Sitt hufvud skola de icke raka, och skola ej heller låta växa håret långt, utan skola låta om klippa sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Och der skall ej heller någor Prest dricka vin, då de uti inra gårdenom tjena skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Och skola icke taga någon enko eller bortdrefna till ägtenskap; utan en jungfru utaf Israels huses säd, eller en Prests efterlefda enko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Och de skola lära mitt folk hålla en åtskilnad emellan heligt och oheligt, och emellan rent och orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Och när en sak för dem kommer, så skola de stå och döma, och tala efter mina rätter, och hålla min bud och sätt, och hålla mina högtider och Sabbather;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Och skola icke gå till någon dödan och orena sig, undantagno allenast till fader och moder, son eller dotter, broder eller syster, den ännu ingen man haft hafver; på dem måga de orena sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Dock att, sedan de äro renade, skall man räkna dem i sju dagar långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Och när han åter går in uti helgedomen i inra gården, till att tjena i helgedomenom, så skall han offra sitt syndoffer, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Men den arfvedel, som de hafva skola, den vill jag sjelf vara; derföre skolen I intet eget land gifva dem i Israel; ty jag är deras arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'De skola hafva deras uppehälle af spisoffer, syndoffer och skuldoffer, och allt spillgifvet i Israel skall vara deras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Och all första frukt och förstföding af all häfoffer skall höra Prestomen till; I skolen ock gifva Prestomen förstlingen af allt det man äter, på det att välsignelse må blifva uti ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Men det som ett as är eller rifvet, ehvad det är af fogel eller djur, det skola Presterna icke äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'När I nu utskiften landet genom lott, så skolen I afsöndra ett häfoffer af landena, det Herranom heligt vara skall, fem och tjugu tusend (stänger) långt, och tiotusend bredt; den planen skall vara helig, så vid som han är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Och häraf skola komma till helgedomen ju femhundrade (stänger) i fyrkant, och dertill ett fritt rum omkring, femtio alnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Och på den samma planenom, som fem och tjugutusend (stänger) lång, och tiotusend bred är, skall helgedomen stå, och det aldrahelgasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Det andra af den helgada markene skall höra Prestomen till, som i helgedomenom tjena, och framför Herran träda till att tjena honom, att de skola hafva rum till ljus; det skall också heligt vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Men Leviterna, som för husena tjena, skola också hafva fem och tjugutusend (stänger) långt, och tiotusend bredt, till sin del, till tjugu kamrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Och stadenom skolen I också låta en plan för hela Israels hus, femtusend (stänger) bredt, och fem och tjugutusend (stänger) långt, bredovid dem afskilda planenom till helgedomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Förstanom skolen I ock gifva en plan, på båda sidor, emellan Presternas plan och stadsplanen, östan och vestan; och skall vara lika lång både östan och yestan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Det skall vara hans egen del i Israel, på det att mine Förstar icke mer skola taga mino folke bort det dem tillhörer; utan skola låta landet Israels huse för deras slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Ty detta säger Herren Herren: Är det icke ännu nog, I Israels Förstar? Låter af all oskäl och våld, och görer det rätt och godt är, och betungar icke så mitt folk mer, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'I skolen hafva rätt vigt, och rätta skäppo, och rätt mått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Epha och bath skola all lika vara, så att ett bath skall hålla tiondedelen af ett homer, och epha sammalunda tiondedelen af ett homer; ty efter homer skall man mäta dem båda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Men en sikel skall hålla tjugu gera, och en mina gör tjugu siklar, fem och tjugu siklar, och femton siklar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Detta skall nu vara häfoffret, som I gifva skolen, nämliga sjettedelen af ett epha, af ett homer hvete, och sjettedelen af ett epha, af ett homer bjugg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Och af oljo skolen I gifva ett bath, nämliga ju hvart tionde bath af en cor, och det tionde af homer; ty tio bath göra ett homer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Och ju ett lamb af tuhundrad får af hjordenom utaf Israels hjordemark till spisoffer, och bränneoffer, och tackoffer, till försoning för dem, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Allt folket i landena skall bära sådana häfoffer till Förstan i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Och Försten skall offra sin bränneoffer, spisoffer och drickoffer, på högtiderna, nymånadom och Sabbather, och uppå alla Israels hus stora högtidom; dertill göra syndoffer och spisoffer, bränneoffer och tackoffer, till försoning för Israels hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Detta säger Herren Herren: På första dagen i första månadenom skall du taga en ung stut, den utan vank är, och skära helgedomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Och Presten skall taga af syndoffrens blod, och bestänka dermed dörrträn af huset, och all fyra hörnen af altaret, samt med dörrträn till porten åt inre gårdenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Alltså skall du ock göra på sjunde dagen i månadenom, om någrom hände vara förledd, och förtaga sig af ovetenhet; på det I mågen skära huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'På fjortonde dagen i första månadenom skolen I hålla Passah, och heligt hålla i sju dagar, och äta osyradt bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Och på samma dagen skall Försten offra för sig, och för allt folket i landena, en stut till syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Men i de sju dagar af högtidene skall han hvar dag göra Herranom bränneoffer, ju sju stutar och sju vädrar, de der utan vank äro, och ju en getabock till syndoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Men till spisoffer skall han ju offra ett epha till hvar stut, och ett epha till hvar vädur, och ju ett hin oljo till hvart epha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'På femtonde dagen i sjunde månadenom skall han hålla heligt i sju dagar efter hvarannan, lika som de andra sju dagar, och rätt så hållat med syndoffer, bränneoffer, spisoffer, och med oljo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Detta säger Herren Herren: Den porten på inra gården, som österut ligger, skall i de sex söknadagar tillsluten vara; men om Sabbathsdagen, och i nymånadenom, skall man upplåta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Och Försten skall träda utantill under portens förhus, och blifva ståndandes utantill vid porten afsides; och Presterna skola offra hans bränneoffer och tackoffer; men han skall tillbedja vid portens tröskel, och sedan gå ut igen; men porten skall öppen blifva, allt intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Sammalunda ock folket i landena skola tillbedja för Herranom, i dörrene åt samma port, på Sabbatherna och nymånaderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Men bränneoffret, som Försten för Herranom offra skall, på Sabbathsdagenom, skall vara sex lamb, de utan vank äro, och en vädur utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Och ju ett epha till väduren, till spisoffer men till lamben, så myckt som han förmår, till spisoffer, och ju ett hin oljo till ett epha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Men i nymånadenom skall man offra en ung oxa, den utan vank är, och sex lamb, och en vädur utan vank;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Och ju ett epha till oxan, och ett epha till väduren, till spisoffer; men till lamben så mång epha som han förmår, och ju ett hin oljo till ett epha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Och när Försten går derin, så skall han gå in genom portens förhus, och åter gå der ut igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Men folket i landena, som för Herran kommer på de stora högtider, och ingår genom den porten norrut till att tillbedja, det skall åter utgå genom den porten sunnantill; och de som ingå genom den porten sunnantill, de skola utgå genom den porten nordantill; och skola icke gå ut igen genom porten, der de igenom ingångne äro, utan gå rätt framåt ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Men Försten skall både ingå och utgå med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Och på helgadagomen, och högtidomen, skall man offra till spisoffer, ju till en stut ett epha, och ju till en vädur ett epha, och till lamben så mycket en förmår, och ju ett hin oljo till ett epha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Men då Försten vill göra ett friviljogt bränneoffer eller tackoffer Herranom, så skall man upplåta honom den porten östantill, att han må offra sitt bränneoffer och tackoffer, lika som han det eljest på Sabbathen offra plägar; och när han går åter ut, så skall man sluta porten igen efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Och han skall göra Herranom dagliga ett bränneoffer, nämlige ett årsgammalt lamb utan vank; det samma skall han offra hvar morgon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Och skall hvar morgon lägga deruppå sjettedelen af ett epha till spisoffer, och tredjedelen af ett hin oljo, beblandadt med semlomjöl, till spisoffer Herranom. Det skall vara en evig rätt om det dagliga offret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Och alltså skola de offra lambet, samt med spisoffrena och oljone, hvar morgon till ett dagligit bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Detta säger Herren Herren: När Försten gifver enom sinom son en skänk af sitt arf, det samma skall höra hans sönom till, och de skola besitta det för ett arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Men om han något skänker enom af sina tjenare af sitt arf, det skola de besitta allt intill friåret, och sedan skall det falla intill Förstan igen; ty hans del skall allena komma hans söner till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Och skall Försten intet taga ifrå sino folke af deras arfvedel, eller drifva dem ifrå deras ägor; utan skall låta sinom barnom sina egna ägor; på det att hvar slägten må vid sig blifva åtskiljeliga, och hvar behålla det honom tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Och han hade mig in i ingången vid sidon åt porten nordantill, till helgedomens kamrar, hvilke Prestomen tillhörde; och si, der var ett rum uti ett hörn vesterut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Och han sade till mig: Detta är det rummet, der Presterna skuldoffer och syndoffer koka skola, och baka spisoffer, att de icke skola behöfva bära det ut i yttra gården; på det folket icke skall synda på det helga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Sedan hade han mig ut i den yttra gården, och befallde mig gå uti gårdsens fyra hörn; och si, der var ett rum uti hvart gårdsens hörn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Och i de fyra gårdsens hörn voro rum till att röka, fyratio alnar långa och tretio alnar breda, ju den ene så vid som den andre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Och der gick en liten mur om dem alla fyra; der voro eldstäder gjorde nedre utmed muren allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Och han sade till mig: Detta år kokorummet, der tjenarena i husens uti koka skola det som folket offrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Och han hade mig åter inför tempeldörrena; och si, der utflöt ett vatten, under templets tröskel östantill; ty tempeldörren var ock östantill; och vattnet lopp på templets högra sido, utmed altaret; sunnantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Och han hade mig ut till den norra porten, ifrån yttra portenom östantill; och si, vattnet sprang derut af högra sidone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Och mannen gick ut österut, och hade mätesnöret i handene, och han mälte tusende alnar, och förde mig uti vattnet, till dess att det gick mig upp öfver foten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Och mälte ännu en gång tusende alnar, och förde mig uti vattnet, tilldess det gick mig upp till knän; och mälte åter tusende alnar, och lät mig gå deruti, tilldess det gick mig upp till länderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Så mälte han ändå tusende alnar, och det vardt så djupt, att jag icke mer kunde räcka bottnen; ty vattnet var så djupt, att man deröfver simma måste, och kunde icke räcka bottnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Och han sade till mig: Du menniskobarn, detta hafver du ju sett? Och han hade mig åter tillbaka åt strandena till bäcken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Och si, der stodo ganska mång trä i strandene på båda sidor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Och han sade till mig: Detta vattnet, som österut flyter, skall flyta igenom slättmarkena uti hafvet, och ifrå det ena hafvet ut i det andra, och när det kommer uti hafvet, så skola de vattnen sund varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Ja, allt det deruti lefver och röres, dit denne strömmen kommer, det skall lefva, och skall hafva ganska många fiskar, och all ting skall helbregda varda och lefva, dit denne strömmen kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Der skola fiskare vara; ifrån EnGedi allt intill EnEglaim skall man upphänga fiskagarn; ty ganska många fiskar skola der vara, likasom i stora hafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Men dammar och kärr skola intet helbregda varda, utan salta blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Och utmed den samma bäcken i strandene, på båda sidor, skola växa allahanda fruktsam trä, och deras löf skola intet förvissna, eller deras frukt förruttna, och skola alla månader bära ny frukt; ty deras vatten flyter utu helgedomenom; deras frukt skall tjena till spis, och deras löf till läkedom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Detta säger Herren Herren: Dessa äro de gränsor, der I efter skolen utskifta landet dem tolf Israels slägtom; ty två delar höra Josephs slägte till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Och I skolen utskifta det lika, så dem ena som dem andra; ty jag hafver svorit, att jag ville gifva edra fäder och eder landet till arfs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Detta är nu landets gränsa norrut, ifrå stora hafvet, ifrå Hethlon allt intill Zedad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Nämliga: Hamath, Berotha, Sibraim, hvilke till Damascus och Hamath gränsa; och HazarTicon, det till Havran gränsar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Detta skall vara gränsan ifrå hafvet allt intill HazarEnon; och Damascus och Hamath skola vara änden norrut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Men den gränsan österut skolen I mäla emellan Havran och Damascus, och emellan Gilead, och emellan Israels land, vid Jordan nederåt, allt intill döda hafvet; det skall vara gränsan österut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Men den gränsan söderut är ifrå Thamar allt intill det vattnet Meriba i Kades, och in mot älfvena vid stora hafvet; det skall vara gränsan söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Och den gränsan vesterut är ifrå stora hafvet rätt fram, allt intill Hamath; det vare gränsan vesterut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Alltså, skolen I utdela landet ibland Israels slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Och när I kasten lotten, till att skifta landet emellan eder, så skolen I hålla främlingarna, som bo när eder, och föda barn ibland eder, lika som de ibland Israels barn infödde voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Och skola desslikes hafva sin del af landena, hvar och en ibland den slägt der han när bor, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Detta äro namnen af slägterna: norrut, ifrån Hethlon intill Hamuth och HazarEnon, och ifrå Damasco intill Hamath, det skall Dan hafva för sin del, både öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Näst Dan skall Asser hafva sin del, både öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Näst Asser skall Naphthali hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Näst Naphthali gränso skall Manasse hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Näst Manasse gränso skall Ephraim hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Vid Ephraims gränso skall Ruben hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Vid Rubens gränso skall Juda hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Men vid Juda gränso skolen I afskilja en del ifrån öster och intill vester, den fem och tjugu tusend stänger lång och bred är, lika som eljest en del är ifrån öster och intill vester; der skall helgedomen stå uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Och derifrå skolen I afskilja Herranom en del, fem och tjugu tusend stänger lång, och tiotusend stänger bred.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Och den samme helige delen skall höra Presterna till; nämliga fem och tjugu tusend stänger långt, norrut och söderut, och tiotusend bredt, österut och vesterut; och Herrans helgedom skall stå der midt uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Det skall höra Prestema till, som af Zadoks slägte äro, hvilke mitt sätt hållit hafva, och voro icke affällige med Israels barnom, såsom Leviterna affällige voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Och skola de alltså hafva en egen del af den afskilda markene, der det aldrahelgasta uti är, vid de Leviters gränso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Men Leviterna skola ock hafva fem och tjugu tusend stänger i längdene, och tiotusend i breddene, invid Presternas gränso; all längd skall hafve, fem och tjugu tusend, och bredden tiotusend stänger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Och skola intet deraf bortsälja, eller bortbyta, att landsens förstling, icke skall bortkomma; ty det är helgadt Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Men de femtusend stänger, som öfver äro i breddene, emot de fem och tjugu tusend stänger i längdene, det skall vara allmänningen för stadenom, att bo derpå, och för förstadenom; och staden skall stå der midt uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Och det skall vara vidden åt honom, fyratusend och femhundrad stänger, norrut och söderut; sammalunda österut och vesterut, ock fyratusend och femhundrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Men förstaden skall hålla tuhundrade och femtio stänger, norrut och söderut; desslikes ock österut och vesterut, tuhundrade och femtio stänger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Men det öfver är af dess längd vid den afsöndrade och helgade marken, nämliga tiotusend stänger, österut och vesterut, det hörer till deras uppehälle som stadenom tjena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Och de som stadenom tjena, de skola, bruka det, ehvad slägt de af äro uti Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Och af all denna afskilda delenom, den på båda sidor hafver, i längdene och breddene, fem och tjugu tusend stänger, skolen I afskilja fjerdedelen; det skall vara stadsens eget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Men hvad ännu öfver är på båda sidor vid den afskilda helga delen och vid stadsdelen, nämliga fem och tjugu tusend stänger, österut och vesterut, vid slägternas delar, det skall alltsammans höra Förstanom till; men den afsöndrade helgade marken och helgedomens hus skall vara der midt uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Men hvad deremellan ligger, emellan Levitemas del, och emellan stadsdelen; summa, hvad som öfver är, emellan Juda gränso och BenJamins gränso, det skall höra Förstanom till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Och dernäst skola de slägterna vara, som öfver äro: BenJamin skall hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Men vid BenJamins gränso skall Simeon hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Vid Simeons gränso skall Isaschar hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Vid Isaschars gränso skall Sebulon hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Vid Sebulons gränso skall Gad hafva sin del, öster och vester.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Men näst Gad är den gränsan söderut, bortemot Theman, ifrå Thamar intill det vattnet Meriba i Kades, och in mot älfvena, allt intill stora hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Alltså skall landet utdelt varda till arfs ibland Israels slägter, och det skall vara deras arf, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Och så vid skall staden vara, fyratusend och femhundrad stänger nordantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Och stadsportarna skola nämnde varda efter Israels slägters namn, tre portar norrut; den förste porten Rubens, den andre Juda, den tredje Levi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Alltså ock östantill, fyratusend och femhundrad stänger, och sammalunda tre portar; nämliga den förste porten Joseph, den andre BenJamin, den tredje Dan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Sunnantill ock sammalunda, fyratusend och femhundrad stänger, och desslikes tre portar; den förste porten Simeon, den andre Isaschar, den tredje Sebulon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Alltså ock vestantill, fyratusend och femhundrad stänger, och tre portar; den förste porten Gad, den andre Asser, den tredje Naphthali.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Alltså skall det hafva allt omkring adertontusend stänger: och sedan skall då staden kallad varda: Här är Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Uti tredje årena af Jojakims, Juda Konungs, rike kom NebucadNezar, Konungen i Babel, in för Jerusalem, och belade det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Och Herren gaf Jojakim, Juda Konung, honom i händer, och en hop af kärile utu Guds hus; hvilken han lät föra in uti Sinears land, i sins guds hus, och lade de kärilen uti sins guds fatabur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Och Konungen sade till Aspenas, sin öfversta kamererare, att han skulle utsöka honom af Israels barnom, af Konungsliga slägt, och herrabarnom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Några unga drängar, som ingen vank hade; utan dägelige voro, förnuftige, vise, kloke och förståndige; hvilke skickelige voro till att tjena i Konungens gård, och till att lära Chaldeiska skrift och mål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Dessom beställde Konungen, hvad man dem dageliga gifva skulle af hans spis, och af det vin der han sjelf af drack; på det att, då de så i tre år uppfödde voro, skulle de sedan tjena inför Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Så voro ibland dem Daniel, Hanania, Misael och Asaria, af Juda barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Och den öfverste kamereraren gaf dem namn; och nämnde Daniel Beltesazar, och Hanania Sadrach, och Misael Mesach, och Asaria AbedNego.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Men Daniel satte sig före i sitt hjerta, att han icke ville orena sig med Konungens spis, och med det vin, som han sjelf drack; och bad öfversta kamereraren, att han icke skulle orena sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Och Gud gaf Daniel, att öfverste kamereraren vardt honom gunstig och god.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Och han sade till honom: Jag fruktar för min Herra Konungen, den eder spis och dryck bestyrt hafver; om han får se, att edor ansigte äro magrare än de andra drängers, som eder jemnåldrige äro, så gören I mig brottsligan till döden inför Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Då sade Daniel till Melzar, hvilkom öfverste kamereraren Daniel, Hanania, Misael och Asaria, befallt hade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Försök dock der med dina tjenare i tio dagar, och låt gifva oss mos till att äta, och vatten till att dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Och låt alltså komma för dig vår och de andra drängers ansigte, som af Konungens spis äta; och efter som du då ser, derefter gör med dina tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Och han hörde dem derutinnan, och försökte det med dem i tio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Och efter de tio dagar voro de dägeligare och bättre vid hull, än alle de dränger, som spisades af Konungens spis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Så satte Melzar bort deras spis och dryck, den dem tillskickad var, och gaf dem mos.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Men dessa fyras Gud gaf dem konst och förstånd uti allahanda skrift och vishet; men Daniel gaf han förstånd i alla syner och drömmar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Då tiden förlupen var, som Konungen förelagt hade, att de skulle hafvas inför honom, hade öfverste kamereraren dem in för NebucadNezar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Och Konungen talade med dem; och vardt ingen ibland dem alla funnen, som Daniels, Hanania, Misaels och Asaria like var; och de vordo Konungens tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Och Konungen fann dem i alla saker, de han dem frågade, tio sinom klokare och förståndigare, än alla stjernokikare och visa i hela sino rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Och lefde Daniel intill Konung Cores första år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Uti andro årena af NebucadNezars rike såg NebucadNezar en dröm, af hvilkom han vardt förskräckt, så att han vaknade upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Då lät han tillhopakomma alla stjernokikare, och visa, och trollkarlar, och Chaldeer, att de skulle säga Konungenom sin dröm. De kommo, och trädde fram för Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Och Konungen sade till dem: Jag hafver haft en dröm, som mig förskräckt hafver, och jag vill gerna veta, hvad det för en dröm varit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Då sade de Chaldeer till Konungen, på Syriskt mål: Herre Konung, Gud låte dig länge lefva; säg dinom tjenarom drömmen, så vilje vi uttyda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Konungen svarade, och sade till de Chaldeer: Det är fallet mig utu minnet; om I icke låten mig få veta drömmen, och uttyden honom, så skolen I platt förgöras, och edor hus skämliga förstörd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Om I ock låten mig få drömmen veta, och uttyden honom, så skolen I få skänker, gåfvor och stora äro, af mig; derföre säger mig nu drömmen, och hans uttydning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'De svarade åter, och sade: Konungen säge sinom tjenarom drömmen, så vilje vi uttyda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Konungen svarade, och sade: Sannerliga, jag förmärker att I fördröjen tiden, efter I sen dock, att det är fallet mig utu minnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Men om I icke sägen mig drömmen, så skall rätten gå öfver eder, lika som öfver de der taga sig före att tala lögn och drafvel för mig, så länge tiden skall förlöpa; derföre säger mig nu drömmen, så kan jag märka, att I ock finnen uppå uttydningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Då svarade de Chaldeer för Konungenom, och sade till honom: Ingen menniska är på jordene, den, det Konungen begärar, säga kan; och är ej heller någon Konung, ehuru stor eller mägtig han är, som sådant af någrom stjernokikare, visom eller Chaldee äskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Ty det Konungen uppå äskar, är för högt, och är ej heller någon, som detta för Konungenom säga kan, undantagna gudarna, hvilke icke bo när menniskomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Då vardt Konungen ganska vred, och böd förgöra alla de visa i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Och domen gick ut, att man skulle dräpa de visa; vardt också Daniel med sina stallbröder sökt, att man dem dräpa skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Då förnam Daniel sådana dom och befallning, af Arioch, Konungens öfversta domare, hvilken utfor till att döda de visa i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Och han hof upp, och sade till Konungens befallningsman Arioch: Hvarföre är denne stränge domen utgången ifrå Konungenom? Och Arioch lät Daniel det förstå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Så gick Daniel upp, och bad Konungen, att han skulle gifva honom tid till, att han måtte säga Konungenom uttydningena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Sedan gick Daniel hem, och gaf det sina stallbröder, Hanania, Misael och Asaria, tillkänna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Att de skulle bedja Gud af himmelen om nåd till denna hemlighet; att Daniel och hans medbröder, samt med de andra visa i Babel, icke förgöras skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Då vardt denna hemlig ting Daniel genom ena syn om nattene uppenbarad; för hvilket Daniel lofvade Gud af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Och Daniel tog till att tala, och säga: Lofvadt vare Guds Namn, ifrån evighet till evighet; ty hans är både vishet och starkhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Han förvandlar tider och stunder; han sätter Konungar af, och sätter Konungar upp; han gifver de visa deras vishet, och de förståndiga deras förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Han uppenbarar det djupt och hemligit är; han vet hvad i mörkrena ligger; ty när honom är alltsammans ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Jag tackar och lofvar dig, mina fäders Gud, att du hafver förlänt mig vishet och starkhet, och hafver nu det uppenbarat, der vi dig om bedit hafve; det är, Konungens ärende hafver du oss uppenbarat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Så gick Daniel upp till Arioch, den af Konungenom befallning hade till att dräpa de visa i Babel, och sade till honom alltså: Du skall icke förgöra de visa i Babel; utan haf mig upp till Konungen, jag vill säga Konungenom uttydelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Arioch hade Daniel med hast upp för Konungen, och sade till honom alltså: En är funnen ibland Juda fångar, som Konungenom uttydningen säga kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Konungen svarade, och sade till Daniel, den de Beltesazar kallade: Äst du den samme, som mig kan säga den dröm, som jag hafver, och hans uttydning?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel svarade inför Konungenom, och sade: Den hemlighet, som Konungen äskar af de visa, lärda, stjernokikare och spåmän, står icke i deras magt att säga Konungenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Utan Gud af himmelen, han kan uppenbara hemlig ting; han hafver tett Konungenom NebucadNezar, hvad i tillkommande tider ske skall; din dröm och din syn, då du sof, var denna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Du Konung tänker i dine säng, huru det måtte tillgå i framtiden; och den som hemlig ting uppenbarar, han tedde dig, huru det gå skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Så är mig denna hemlighet uppenbarad, icke igenom mina vishet, lika som hon större vore än allas de som lefva; utan derföre, att uttydningen måtte Konungenom undervist varda, och du dins hjertas tankar veta få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Du Konung sågst, och si, ett ganska stort och högt beläte stod för dig; det var grufveligit att uppå se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Dess belätes hufvud var af klart guld, dess bröst och armar voro af silfver, buken och länderna voro af koppar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Dess ben voro af jern, dess fötter voro somt af jern, och somt af ler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Sådant sågst du, tilldess en sten nederrifven vardt utan händer; han slog belätet uppå dess fötter, som af jern och ler voro, och förkrossade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Då vordo all tillhopa förkrossad, jernet, leret, kopparen, silfret och guldet, och vordo såsom agnar på enom sommarloga, och vädret bortförde det, så att man kunde intet mer finna det; men stenen, som slog belätet, vardt till ett stort berg, så att det uppfyllde hela verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Detta är drömmen. Nu vilje vi säga uttydningen för Konungenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Du Konung äst en Konung öfver alla Konungar, den Gud af himmelen rike, magt, starkhet och äro gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Och allt det, der menniskor bo, och djuren på markene, och foglarna under himmelen, hafver han gifvit i dina händer, och förlänt dig magt öfver detta allt; du äst det gyldene hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Efter dig skall ett annat Konungarike uppkomma, sämre än ditt; derefter det tredje Konungarike, som af koppar är, hvilket öfver all land regera skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Det fjerde skall vara hårdt såsom jern; ty lika visst som jern sönderslår och sönderkrossar all ting; ja, lika som jern sönderslår all ting, så skall ock detta sönderkrossa och sönderslå alltsamman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Men att du sågst fötterna och tårna, somt af ler, och somt af jern, det skall vara ett söndradt Konungarike; dock skall af jerns planto blifva deruti, såsom du sågst jern beblandadt med ler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Och att tårna på dess fötter, somt af jern, och somt af ler voro, det skall vara endels ett starkt, och endels ett svagt rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Och att du sågst jern beblandadt med ler, skola de väl beblanda sig efter menniskos blod tillsammans; men de skola likväl intet hänga tillhopa, lika som jern icke kan bemängas med ler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Men uti dessa Konungarikes tid skall Gud af himmelen upprätta ett Konungarike, det aldrig skall förlagdt varda; och hans rike skall icke komma till något annat folk; det skall förkrossa och förstöra all dessa riken; men det skall blifva i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Såsom du sågst en sten nederrifven af ett berg utan händer, hvilken sönderslog jernet, kopparen, leret, silfret och guldet, alltså hafver nu den store Gud tett Konungenom, hvad som framdeles ske skall; och detta är visserliga drömmen, och uttydningen är rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Då föll Konungen NebucadNezar uppå sitt ansigte, och tillbad inför Daniel; och befallde, att man skulle göra honom spisoffer och rökoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Och Konungen svarade Daniel, och sade: Det är intet tvifvel, edar Gud är en Gud öfver alla gudar, och en Herre öfver alla Konungar, den hemlig ting uppenbara kan; efter du dessa hemlig ting hafver kunnat uppenbara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Och Konungen upphöjde Daniel, och gaf honom stora myckna skänker; och gjorde honom till en Första öfver hela landet Babel, och satte honom till en öfversta öfver alla de visa i Babel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Och Daniel bad Konungen, att han måtte sätta Sadrach, Mesach och AbedNego öfver de landskap i Babel; men Daniel sjelf blef när Konungenom i hans gård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Konung NebucadNezar lät göra ett gyldene beläte, sextio alnar högt, och sex alnar bredt; och lät sätta det i Babels land på en skön plan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Och Konung NebucadNezar sände efter Förstar, herrar, landshöfdingar, domare, fogdar, rådherrar, ämbetsmän, och alla väldiga i landet, att de skulle komma tillsammans, och viga det belätet, som Konungen NebucadNezar hade uppsätta låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Då kommo Förstarna, herrarna, landshöfdingarna, domarena, fogdarna, rådherrarna, ämbetsmännerna, och alle väldige i landet tillsamman, till att viga belätet som Konung NebucadNezar hade uppsätta låtit, och de måste gå fram för belätet som NebucadNezar hade uppsätta låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Och härolden ropade öfverljudt: Det låter eder sagdt vara, I all folk, slägter och tungomål;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Att, när I hören basuner, trummeter, harpor, gigor, psaltare, lutor och allahanda strängaspel, så skolen I nederfalla, och tillbedja det gyldene belätet, som Konung NebucadNezar hafver uppsätta låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Men den som då icke nederfaller och tillbeder, han skall på samma stund kastas uti en brinnande ugn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Då de nu hörde ljudet af basuner, trummeter, gigor, psaltare och allahanda strängaspel, föllo neder all folk, slägter och tungomål, och tillbådo det gyldene belätet, som Konungen NebucadNezar hade uppsätta låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Straxt på samma stund gingo någre Chaldeiske män fram, och anklagade Judarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Begynte, och sade till Konungen NebucadNezar: Herre Konung, Gud unne dig länge lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Du hafver, o Konung, låtit utgå ett bud, att alla menniskor, då de hörde ljudet af basuner, trummeter, harpor, gigor, psaltare, lutor och allahanda strängaspel, skulle de nederfalla, och tillbedja det gyldene belätet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Och den som icke nederfölle och tillbåde, han skulle kastas uti en brinnande ugn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Nu äro här någre Judiske män, hvilka du öfver de ämbete i Babels land satt hafver, Sadrach, Mesach och AbedNego; de samme förakta ditt bud, o Konung, och vörda icke dina gudar, och tillbedja icke det gyldene belätet, som du hafver uppsätta låtit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Då befallde NebucadNezar, med grymhet och vrede, att man skulle hafva fram för honom Sadrach, Mesach och AbedNego; och männerne vordo framhafde för Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Då talade NebucadNezar till dem, och sade: Huru är det? Viljen I, Sadrach, Mesach och AbedNego, icke vörda min gud, och icke tillbedja det gyldene belätet, som jag hafver uppsätta låtit?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nu väl, reder eder till, så snart I hören ljudet af basuner, trummeter, harpor, gigor, psaltare, lutor och allahanda strängaspel, så faller neder, och tillbeder belätet, som jag hafver uppsätta låtit; om I icke tillbedjen det, så skolen I på samma stund varda kastade uti en brinnande ugn. Låt se, hvilken den Guden är, som eder utu mina händer tager.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Då svarade Sadrach, Mesach och AbedNego, och sade till Konung NebucadNezar: Det är icke af nödene, att vi svare dig deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Si, vår Gud, den vi dyrke, kan väl hjelpa oss utu den brinnande ugnen, och frälsa oss utu dine hand, o Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Och om han än icke det göra vill, så skall du ändå veta, o Konung, att vi dina gudar intet vörde, ej heller det gyldene beläte, som du hafver uppsätta låtit, tillbedja viljom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Då vardt NebucadNezar full med grymhet, så att hans ansigte förvandlade sig öfver Sadrach, Mesach och AbedNego; och befallde, att man skulle göra ugnen sju resor hetare, än han eljest plägade vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Och böd de bästa krigsmän, som uti hans här voro, att de skulle binda Sadrach, Mesach och AbedNego, och kasta dem uti den brinnande ugnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Alltså vordo desse männerna, uti deras mantlar, skor, hattar och annor kläder, bundne, och kastade uti den brinnande ugnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Ty Konungens befallning måste man med hast fullgöra; och elden vardt så stark i ugnen, att de män, som Sadrach, Mesach och AbedNego uppbränna skulle, blefvo döde af eldslåganom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Men de tre männerna, Sadrach, Mesach och AbedNego, föllo neder uti den brinnande ugnen, så bundne som de voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Då förskräckte sig Konung NebucadNezar, och gick hastigt upp, och sade till sitt Råd: Hafve vi icke låtit kasta tre män i elden bundna? De svarade, och sade till Konungen: Ja, Herre Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Han svarade, och sade: Ser jag dock fyra män lösa gå i eldenom, och dem skadar intet; och den fjerde är lika som han vore en Gudason.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Och NebucadNezar gick fram för gapet på den brinnande ugnen, och sade: Sadrach, Mesach och AbedNego, högsta Guds tjenare, går härut, och kommer hit. Så gingo Sadrach, Mesach och AbedNego, utur eldenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Och Förstarna, herrarna, fogdarna, och Konungens Råd kommo tillsamman, och sågo uppå, huru elden ingen magt uppå dessa männernas kroppar bevisat hade; och deras hufvudhår icke ens afsvedet var, och deras kläder intet skadd; ja, man kunde icke känna någon eldslukt uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Då hof NebucadNezar sin röst upp, och sade: Lofvad vare Sadrachs, Mesachs och AbedNegos Gud, den sin Ängel utsändt hafver, och halp sina tjenare, som uppå honom trodde, och icke gjorde efter Konungens bud, utan utgåfvo deras lekamen, att de ingen gud ära eller tillbedja ville, utan allena sin Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Så är nu detta mitt bud: Att ho som helst ibland all folk, slägter och tungomål, försmäder Sadrachs, Mesachs och AbedNegos Gud, han skall förgöras, och hans hus skamliga förstördt varda; ty det är ingen annar gud, som så hjelpa kan, som denne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Och Konungen gaf Sadrach, Mesach och AbedNego, stort välde i Babels land. Konung NebucadNezar, allom landom, folkom och tungomålom: Gud gifve eder mycken frid! Mig synes godt vara, att jag förkunnar de tecken och under, som Gud den Högste med mig gjort hafver; Ty hans tecken äro stor, och hans under äro mägtig, och hans rike är ett evigt rike, och hans välde varar ifrå slägte till slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Jag NebucadNezar, då jag god ro hade i mitt hus, och allt väl tillstod i mitt palats;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Såg en dröm, och vardt förskräckt; och de tankar, som jag i mine säng hade, öfver synena, som jag sett hade, bedröfvade mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Och jag befallde, att alle de vise i Babel skulle komma upp för mig, att de måtte säga mig, hvad drömmen betydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Då hade man fram de stjernokikare, visa, Chaldeer och spåmän, och jag förtäljde drömmen för dem; men de kunde intet säga mig, hvad han betydde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Intilldess Daniel, på det sista, kom för mig, hvilken Beltesazar kallas, efter mins guds namn, den de helga gudars anda hafver; och jag förtäljde för honom drömmen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Beltesazar, du öfverste ibland de stjernokikare, jag vet att du hafver de helga gudars andars anda, och dig är intet fördoldt; säg mins dröms syn, den jag sett hafver, och hvad han betyder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Så är detta synen, som jag såg i mine säng: si, ett trä stod midt i landet; det var ganska högt,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Stort och tjockt; dess höjd räckte upp i himmelen, och utvidgade sig allt intill landsens ända;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Dess qvistar voro dägelige, och båro mycken frukt, der alle af äta kunde; all djur i markene funno skugga under thy, och foglarna under himmelen satte sig på dess qvistar, och allt kött hade sin födo deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Och jag såg en syn i mine säng; och si, en helig väktare kom neder af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Han ropade öfverljudt, och sade alltså: Hugger trät omkull, och hugger bort qvistarna, och rifver bort löfvet, och förströr dess frukt, så att djuren, som derunder ligga, löpa sin väg, och foglarna flyga bort af dess qvistar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Dock, låter stubban blifva i jordene med rötterna; men han skall gå i jern och kopparkädjor i gräset på markene, han skall ligga under himmelens dagg, och varda våt, och skall föda sig ibland djuren af gräset på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Och det menniskliga hjertat skall varda ifrå honom taget, och ett vilddjurs hjerta gifvas honom igen, tilldess att sju tider framgångne äro öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Detta är beslutit i väktarenas råd, och i de heligas tal rådslagit; på det de som lefva, måga känna att den Högste hafver magt öfver menniskors rike, och gifver dem hvem han vill, och upphöjer de förnedrada dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Sådana dröm hafver jag, Konung NebucadNezar, sett; men du Beltesazar, säg hvad han betyder; ty alle de vise, som i mitt rike äro, kunna icke säga mig hvad han betyder; men du kan det väl; ty de helga gudars ande är i dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Då vardt Daniel, den ock Beltesazar het, häpen deröfver, vid en timma långt, och hans tankar bedröfvade honom; men Konungen sade: Beltesazar, låt icke drömmen och hans uttydning bedröfva dig. Då hof Beltesazar upp, och sade: Ack! min herre, att denne drömmen gulle dina fiendar uppå, och hans uttydning dina ovänner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Trät, som du sågst, att det var stort och tjockt, och dess höjd räckte upp till himmelen, och utvidgade sig öfver hela landet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Och dess qvistar dägelige, och dess frukt mycken var, der alle sina födo af hade, och djuren på markene bodde derunder, och himmelens foglar på dess qvistar såto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Det äst du, Konung, som så stor och mägtig äst; ty din magt är stor, och räcker upp till himmelen, och ditt välde sträcker sig intill verldenes ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Men det, att Konungen såg en helig väktare komma neder af himmelen, och säga: Hugger trät omkull, och förgörer det; dock låter stubban med sina rötter blifva i jordene; men han skall gå i jern och kopparkädjor i gräset på markene, och ligga under himmelens dagg, och varda våter, och föda sig ibland djuren på markene, tilldess sju tider öfver honom framlidne äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Detta är uttydningen, herre Konung, och sådana dens Högstas råd går öfver min herra Konungen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Man skall drifva dig bort ifrå folk, och du måste blifva med vilddjur på markene, och man skall dig låta äta gräs såsom oxar, och skall ligga under himmelens dagg, och varda våter, tilldess sju tider öfver dig framlidne äro; på det du skall besinna, att den Högste hafver våld öfver menniskors rike, och gifver dem hvem han vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Men det som sagdt är, att man ändå skall låta blifva stubban af trät med sina rötter qvar; ditt rike skall blifva dig, då du känt hafver magten i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Derföre, herre Konung, låt mitt råd täckas dig, och går dig lös ifrå dina synder, genom rättfärdighet, och ledig ifrå dina missgerningar, genom välgerningar emot de fattiga; så hafver han tålamod med dina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Allt detta vederfors Konung NebucadNezar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Ty efter tolf månader, då Konungen gick på Konungsborgene i Babel,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Hof han upp, och sade: Detta är den store Babel, som jag uppbyggt hafver till ett Konungshus, genom mina stora magt, mine härlighet till äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Förr än Konungen dessa orden uttalat hade, kom en röst af himmelen: Dig, Konung NebucadNezar, vare sagdt: Ditt rike skall dig aftaget varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Och man skall drifva dig bort ifrå folk, och du skall blifva med vilddjur, som på markene gå; gräs skall man dig äta låta såsom oxar, tilldess sju tider öfver dig framledne äro; på det du skall förnimma, att den Högste hafver våld öfver menniskors rike, och gifver dem hvem han vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'I samma stund vardt ordet fullkomnadt öfver NebucadNezar, så att han vardt bortdrifven ifrå folk, och han åt gräs såsom oxar, och hans lekamen låg under himmelens dagg, och vardt våter, tilldess hans hår växte såsom örnafjädrar, och hans naglar vordo såsom foglaklor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Efter den tiden hof jag, NebucadNezar, upp min ögon till himmelen, och kom åter till sinne igen, och lofvade den Högsta; jag prisade och ärade honom, som lefver evinnerliga, hvilkens välde är evigt, och hans rike varar slägte ifrå slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Emot hvilkom alle de, som på jordene bo, för intet räknas; han gör allt såsom han vill, både med krafterna i himmelen, och med dem som bo på jordene; och ingen kan stå hans hand emot, eller säga till honom: Hvad gör du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'På samma tid kom jag till sinne igen, och till mina Konungsliga äro, till mina härlighet, och till min skapnad; och mitt Råd och väldige sökte mig: och jag vardt åter satt uti mitt rike igen, och fick ännu större härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Derföre lofvar jag, NebucadNezar, och ärar och prisar Konungen i himmelen; ty alla hans gerningar äro sanning, och hans vägar äro rätte, och den som stolt är, kan han ödmjuka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Konung Belsazar gjorde ett härligit gästabåd till sina väldiga och höfvitsmän, och drack sig drucken med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Och då han drucken var, böd han bära fram de gyldene och silfverkärile, som hans fader, NebucadNezar, utu templet i Jerusalem borttagit hade, att Konungen, med sina väldiga, med sina hustrur, och med sina frillor, skulle dricka deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Alltså vordo framburne de gyldene kärile, som utu templet, utu Guds huse, i Jerusalem tagne voro; och Konungen, hans väldige, hans hustrur och frillor, drucko deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Och då de så drucko, lofvade de de gyldene, silfver, koppar, jern, trä och stengudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'På samma stund syntes finger, såsom ene menniskos hand, de skrefvo tvärsöfver ifrå ljusastakan, på den hvitmenade väggene i Konungssalenom; och Konungen vardt varse handena som skref.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Då förvandlades Konungens ansigte, och hans tankar förskräckte honom, så att hans länder bäfvade, och hans ben darrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Och Konungen ropade öfverljudt, att man skulle låta komma visa, Chaldeer och spåmän, och lät säga till de visa i Babel: Den menniska, som denna skriftena läs, och kan säga hvad hon betyder, han skall varda klädd i purpur, och bära en gyldene kedjo om halsen, och vara den tredje herren i mitt rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Så vordo alle Konungens vise upphafde; men de kunde hvarken läsa skriftena, eller undervisa Konungenom uttydningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Deraf förfärades Konungen Belsazar ännu fastare, och tappade platt sin hy; och hans väldige vordo illa tillfrids.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Då gick Drottningen, för sådana Konungens och hans väldigas ärendes skull, upp i salen, och sade: Herre Konung, Gud unne dig länge lefva; låt dina tankar icke så förskräcka dig, och omskift icke så din hy.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Det är en man i ditt rike, som hafver de helga gudars anda; ty uti dins faders tid vardt i honom funnen upplysning, klokhet och vishet, sådana, som de gudars vishet är; och din fader, Konung NebucadNezar, satte honom öfver de stjernokikare, visa, Chaldeer och spåmän;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Derföre, att en hög ande vardt funnen i honom; dertill förstånd och klokhet till att uttyda drömmar, råda uppå mörkt tal, och uppenbara hemlig ting, nämliga Daniel, den Konungen lät Beltesazar kalla. Så låt nu kalla Daniel; han varder väl sägandes uttydningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Då hade man Daniel upp för Konungen; och Konungen sade till Daniel: Äst du Daniel, en af de fångar utaf Juda, hvilka Konungen, min fader, utu Juda fört hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Jag hafver hört sägas om dig, att du hafver de helga gudars anda, och att upplysning, förstånd och hög vishet i dig funnen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Nu hafver jag låtit komma för mig kloka och visa, att de skola läsa mig denna skriftena, och undervisa mig hvad hon betyder, och de kunna intet säga mig hvad sådant betyder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Men om dig hörer jag att du kan gifva uttydning, och uppenbara det hemligit är, kan du nu läsa denna skriftena, och undervisa mig hvad hon betyder, så skall du med purpur klädd varda, och bära en gyldene kedjo om din hals, och vara den tredje herren i mitt rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Då svarade Daniel, och sade inför Konungen: Behåll dina gåfvor sjelf, och gif din skänk enom androm; jag vill dock väl läsa Konungenom skriftena, och undervisa hvad hon betyder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Herre Konung, Gud den Högste gaf dinom fader, NebucadNezar, rike, magt, äro och härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Och för sådana magts skull, som honom gifven var, fruktade och räddes för honom all land, och folk, och tungomål; han drap hvem han ville, han upphöjde hvem han ville, han nedertryckte hvem han ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Men då hans hjerta upphof sig, att han vardt stolt och högmodig, vardt han kastad ifrå sin Konungsliga stol, och miste sina härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Och vardt drifven ifrå menniskor; och hans hjerta vardt likt vid vilddjur, och han måste löpa ibland vildåsnar, och åt gräs såsom oxar, och hans kropp låg under himmelens dagg, och vardt våt, tilldess han lärde veta, att den Högste hafver våld öfver menniskors rike, och gifver dem hvem han vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Och du Belsazar, hans son, hafver icke ödmjukat ditt hjerta, ändock du allt sådant vetst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Utan hafver upphäfvit dig emot himmelens Herra, och man hafver måst bära hans hus kärile fram för dig, och du, dine väldige, dina hustrur och dina frillor, hafva druckit vin deraf; dertill lofvat de silfver, gyldene, koppar, jern, trä och stengudar, hvilke hvarken se, eller höra, eller känna; men den Guden, som hafver din anda och alla dina vägar i sine hand, hafver du intet ärat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Derföre är denna handen sänd ifrå honom, och den skrift, som der upptecknad står.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Och detta är skriften, som der upptecknad är: Mene Mene, Thekel Upharsin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Och hon betyder detta: Mene, det är: Gud hafver räknat ditt rike, och ändat det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Thekel, det är: Man hafver vägit dig på ene våg, och funnit dig allt för lättan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres, det är: Ditt rike är åtskildt, och gifvit de Meder och Perser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Då befallde Belsazar, att man skulle kläda Daniel uti purpurkläde, och gifva honom ena gyldene kedjo om hans hals; och lät förkunna om honom, att han var den tredje herren i rikena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'I den samma nattene vardt de Chaldeers Konung Belsazar ihjälslagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Och Darios utaf Meden tog riket in, då han tu och sextio år gammal var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Och Darios syntes godt vara, att han skulle sätta öfver hela riket tjugu och hundrade landshöfdingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Öfver dessa satte han tre Förstar; den ene var Daniel, hvilkom de landshöfdingar skulle räkenskap göra, att Konungen dess mindre bekymmer hafva skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Men Daniel gick alla de Förstar och landshöfdingar vidt öfver; ty en hög ande var i honom; derföre tänkte Konungen att sätta honom öfver hela riket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Fördenskull foro de Förstar och landshöfdingar derefter, huru de kunde finna en sak med Daniel, den emot riket vore; men de kunde ingen sak eller missgerning finna; ty han var trogen, så att man ingen skuld eller ogerning med honom finna kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Då sade männerne: Vi finne ingen sak med Daniel, utan om hans Gudstjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Då kommo de Förstar och landshöfdingar tillhopa inför Konungen, och sade till honom alltså: Herre Konung, Darios, Gud unne dig länge lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'De Förstar i rikena, herrarna, landshöfdingarna, Rådet och ämbetsmännerna, hafva alle betänkt, att man skall låta utgå en Konungslig befallning, och ett strängt påbud, att ho som helst i tretio dagar någon ting vill bedja af någon Gud eller mennisko, utan af dig, Konung allena, han skall varda kastad för lejon uti gropena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Derföre, o Konung, måste du detta budet stadfästa, och underskrifva dig; på det att det icke skall omvändt varda, efter de Meders och Persers rätt, det ingen öfverträda djerfves.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Alltså underskref sig Konungen Darios.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Som nu Daniel förnam, att sådant bud underskrifvet var, gick han upp i sitt hus; och han hade i sino sommarhuse öppna fenster emot Jerusalem; der föll han tre resor om dagen på sin knä, bad, lofvade och tackade sin Gud, såsom han tillförene plägade göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Då kommo desse männerna hopetals, och funno Daniel bedjandes och åkallandes inför sin Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Så gingo de fram, och talade med Konungen om det Konungsliga budet: Herre Konung, hafver du icke underskrifvit ett bud, att ho som helst i tretio dagar något både af någon gud, eller af någon mennisko, utan af dig Konungenom allena, han skulle kastas för lejon i gropena? Konungen svarade, och sade: Det är sant, och de Meders och Persers rätt skall ingen öfverträda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'De svarade, och sade för Konungen: Daniel, en af Juda fångar, aktar hvarken dig, o Konung, eller ditt bud, som du underskrifvit hafver; ty han beder tre resor om dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Då Konungen detta hörde, vardt han fast bedröfvad, och vinnlade sig storliga, att han måtte fria Daniel; och arbetade derom intill solen nedergick, att han måtte hjelpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Men männerne kommo samman till Konungen, och sade till honom: Du vetst, herre Konung, att de Meders och Persers rätt är, att all bud och befallningar, som Konungen beslutit hafver, skola oförvandlade blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Då befallde Konungen, att man skulle hafva Daniel fram, och de kastade honom för lejonen i gropena; men Konungen sade till Daniel: Din Gud, den du utan återvändo tjenar, han hjelpe dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Och de båro en sten fram, den lade de på locket af gropene; honom förseglade Konungen med sin egen ring, och med sina väldigas ring, på det att ingen skulle eljest något bruka på Daniel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Och Konungen gick sin väg på sina borg, och åt intet, och lät ingen mat för sig bära, och kunde ej heller sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Om morgonen bittida, då det dagades, stod Konungen upp, och gick med hast till gropena, der lejonen uti voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Och som han kom till gropena, ropade han till Daniel med sorgeliga röst; och Konungen sade till Daniel: Daniel, du lefvandes Guds tjenare, hafver ock din Gud, den du utan återvändo tjenar, förmått frälsa dig för lejonen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Då talade Daniel med Konungen: Herre Konung, Gud unne dig länge lefva!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Min Gud hafver sändt sin Ängel, hvilken lejonens mun tillhållit hafver, att de hafva ingen skada gjort mig; ty för honom är jag oskyldig funnen: Så hafver jag ej heller något gjort emot dig, Herre Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Då vardt Konungen ganska glad, och lät taga Daniel utu gropene; och de togo Daniel utu gropene, och man fann platt ingen skada gjord vara uppå honom; ty han hade trott sinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Då lät Konungen komma fram de män, som Daniel beklagat hade, och kasta dem inför lejonen i gropena, samt med deras barn och hustrur; och förr än de kommo ned till bottnen, fingo lejonen dem fatt, förkrossade ock alla deras ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Sedan lät Konungen Darios skrifva till all land, och folk, och tungomål: Gud gifve eder mycken frid!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Detta är min befallning, att uti allt mins rikes herradöme skall man frukta och rädas Daniels Gud; ty han är den lefvande Gud, som blifver evinnerliga, och hans rike är oförgängeligit, och hans herradöme hafver ingen ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Han är en frälsare och nödhjelpare, och han gör tecken och under, både i himmelen och på jordene; han hafver frälst Daniel ifrå lejonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Och Daniel var väldig i Darios rike, och desslikes i Cores, den Persens, rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Uti första årena Belsazars, Konungens i Babel, hade Daniel en dröm och syn på sin säng; och han skref den samma drömmen, och författade honom alltså:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Jag, Daniel, såg en syn om nattene, och si, de fyra väder under himmelen stormade emot hvartannat på stora hafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Och fyra stor djur stego upp utu hafvet, ju det ena annorlunda än det andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Det första såsom ett lejon, och hade vingar såsom en örn; jag såg till, intilldess att vingarne vordo thy afryckte, och det vardt tagit bort af jordene, och det stod på sina fötter såsom en menniska; och thy vardt ett menniskligit hjerta gifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Och si, det andra djuret dernäst var likt enom björn, och stod på den ena sidone, och hade i sinom mun, ibland sina tänder, tre stora långa tänder; och man sade till det: Statt upp, och ät mycket kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Efter detta såg jag, och si, ett annat djur, likt enom parde, det hade fyra vingar, såsom en fogel, på sin rygg; och det samma djuret hade fyra hufvud, och thy vardt magt gifven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Efter detta såg jag i denna synene om nattena, och si, det fjerde djuret var grufveligit och förskräckligit, och mägta starkt, och hade stora jerntänder; åt omkring sig, och förkrossade, och hvad qvart var, trampade det med sina fötter. Det var ock mycket annars än de förra, och hade tio horn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Då jag nu skådade hornen, si, då gick der ut ibland dem ett annat litet horn, för hvilko de tre främsta hornen afstött vordo; och si, det samma hornet hade ögon såsom menniskoögon, och en mun, den stor ting talade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Sådant såg jag, tilldess stolar framsatte vordo, och den gamle satte sig, hvilkens kläde var snöhvitt, och håret på hans hufvud såsom ren ull; hans stol var alltsammans eldslåge, och hans hjul brunno af eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Och af honom utgick en lång eldstrimma: Tusende sinom tusend tjente honom, och tio sinom hundrade tusend stodo för honom. Domen vardt hållen, och böckerna vordo upplåtna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Jag såg till, för de stora ords skull, som det hornet talade; jag såg till, intilldess djuret dräpit vardt, och dess kropp förgicks, och i eld kastad vardt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Och de andra djurs välde också ute var; ty dem var en tid och stund bestämd, huru länge hvartdera vara skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Jag såg i denna synene om nattene; och si, en kom i himmelens sky, såsom ens menniskos Son, allt intill den gamla, och han vardt framhafd för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Honom gaf han våld, äro och rike, att all land, och folk, och tungomål, skulle tjena honom: Hans välde är evigt, det icke förgås, och hans rike hafver ingen ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Jag, Daniel, förskräckte mig derföre, och sådana syn förfärade mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Och jag gick till en af dem som der stodo, och bad honom, att han skulle gifva mig en viss undervisning om allt detta; och han talade med mig, och tedde mig hvad det betydde:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Dessa fyra stora djur äro fyra rike, som på jordena komma skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Men dens Högstas helige skola intaga riket och skola besitta det i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Sedan hade jag gerna vetat en viss undervisning om det fjerde djuret, hvilket platt annars var, än all de andra, ganska grufveligit; det jerntänder och kopparklor hade, det omkring sig åt, och förkrossade, och det qvart var med sina fötter trampade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Och om de tio horn på dess hufvud, och om det andra som uppväxte, för hvilko tre afföllo; och om det samma hornet som ögon hade, och en mun, som stor ting talade, och större var än de der bredvid voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Och jag såg det samma hornet strida emot de heliga, och det behöll segren emot dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Tilldess den gamle kom, och höll dom för dens Högstas heligom, och tiden kom, att de helige intogo riket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Han sade alltså: Det fjerde djuret skall vara det fjerde riket på jordene, hvilket mägtigare skall vara än all rike; det skall uppäta, förtrampa och förkrossa all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'De tio horn betyda tio Konungar, som i de rikena uppkomma skola; efter dem skall en annan uppkomma, han skall vara mägtigare än någor af de förra, och skall undertrycka tre Konungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Han skall försmäda den Högsta, och för störa dens Högstas heliga; och skall taga sig före att förvandla tider och lag; men de skola varda gifne uti hans hand i en tid, och några tider, och en half tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Derefter skall domen hållen varda; så skall då hans välde borttaget varda, så att han skall i grund förderfvad och förgjord varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Men riket, magten och väldet under hela himmelen skall varda gifvit dens Högstas heligo folke, hvilkes rike evigt är; och allt välde skall tjena honom, och lyda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Det var änden på talet. Men jag, Daniel, vardt svårliga bedröfvad i mina tankar, och mitt ansigte förvandlade sig uppå mig; dock behöll jag talet i mitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Uti tredje årena af Konung Belsazars rike syntes mig, Daniel, en syn, efter den som mig i förstone synts hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Men jag var, då jag denna syn såg, i Susan, hufvudstadenom i Elams land, vid den älfven Ulai.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Och jag hof upp min ögon, och såg; och si, en vädur stod för älfvene, och han hade tu hög horn; dock det ena högre än det andra, och det högsta växte sist.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Jag såg, att väduren stötte med hornen vesterut, norrut och söderut; och intet djur kunde bestå för honom, eller fria sig ifrå hans hand, utan han gjorde hvad han ville, och vardt stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Och vid jag gaf der akt uppå, så kom en getabock, vestanefter, öfver hela jordena, så att han intet kom vid jordena; och den bocken hade ett skönt horn emellan sin ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Och han kom allt intill den väduren som tu horn hade, den jag såg stå för älfvene, och han lopp i sine vrede väldeliga intill honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Och jag såg, att han kom hardt intill väduren, och förgrymmade sig öfver honom, och stötte till väduren, och sönderslog hans tu horn; och väduren hade ingen magt till att stå honom emot, utan han stötte honom till markena, och trampade uppå honom; och ingen förmåtte hjelpa väduren utu hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Och den getabocken vardt ganska stor, och då han som starkast vorden var, gick det stora hornet sönder, och i dess stad växte fyra sköna, emot fyra himmelens väder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Och af enodera växte ett litet horn; det vardt ganska stort, söderut, österut, och inemot det lustiga landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Och det växte allt intill himmelens här, och kastade somliga neder dädan, och af stjernorna till jordena, och trampade uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Ja, det växte allt intill Förstan för hären; och tog bort ifrå honom det dagliga offret, och förödde hans helgedoms boning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Och sådana magt vardt honom gifven emot det dagliga offret för syndernas skull, så att han skulle slå neder sanningena, och hvad han gjorde, skulle framgång hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Men jag hörde en heligan tala; och den samme helige sade till en som talade: Huru länge skall dock denna synen, om det dagliga offret, vara, och om synderna, för hvilkas skull denna förödning sker, så att både helgedomen och hären förtrampad varder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Och han svarade mig: Det är tutusende och trehundrade dagar, efter afton och morgon räknandes, så skall helgedomen åter vigder varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Och då jag, Daniel, såg den synena, och hade gerna förståndit henne; si, då stod för mig såsom en man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Och jag hörde emellan Ulai ene menniskos röst, som ropade och sade: Gabriel, uttyd dessom synena, så att han förstår henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Och han kom hardt intill mig; och jag vardt förskräckt, då han kom, och föll neder uppå mitt ansigte, och han sade till mig: Gif akt häruppå, du menniskobarn, ty denna synen lyder uppå ändans tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Och då han talade med mig, dignade jag af vanmägtighet neder på mitt ansigte till jordena; men han tog uppå mig, och rätte mig upp, så att jag blef ståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Och han sade: Si, jag vill visa dig, huru det gå skall på yttersta vredenes tid; ty änden hafver sin bestämda tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Väduren med de tu horn, som du sågst, äro de Konungar i Meden och Persien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Men getabocken är Konungen i Grekeland; det stora hornet emellan hans ögon är den förste Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Men att fyra stodo i dess stad, då det sönderslagit vardt, betyder, att fyra rike skola uppkomma af det folket; men icke så mägtig som han var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Efter dessa riken, när öfverträdelsen stor vorden är, skall uppkomma en arg och listig Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Han skall vara mägtig, dock icke genom sina kraft; han skall underliga föröda, och skall hafva framgång, att han det uträttar; han skall förstöra de starka, och det heliga folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Och genom hans klokhet skall hans bedrägeri framgå, och han skall upphäfva sig i sitt hjerta, och genom framgång skall han många förderfva, och skall uppsätta sig emot alla Förstars Första; men han skall utan hand förlagd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Denna synen, om afton och morgon, som dig sagd är, hon är sann; men du skall hålla synena hemliga, ty det är ännu en lång tid dit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Och jag, Daniel, vardt svag, och låg i några dagar krank; sedan stod jag upp, och beställde Konungens ärende, och förundrade mig uppå synena; och ingen var, som kunde reda mig henne ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Uti första årena Darios, Ahasveros sons, utaf de Meders slägte, hvilken öfver de Chaldeers rike Konung vardt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Uti de samma första årena af hans rike förmärkte jag, Daniel, i böckerna, uppå det åratalet, der Herren om talat hade till Propheten Jeremia, att Jerusalem skulle öde ligga i sjutio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Och jag vände mig till Herran Gud, till att bedja och åkalla med fasto, uti säck och asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Och jag bad till Herran min Gud, bekände och sade: Ack! Herre, du store och förskräcklige Gud, du som håller förbund och nåde dem, som dig älska, och hålla din bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Vi hafve syndat, gjort orätt, hafve varit ogudaktige, och vordit affällige; vi hafve vikit ifrå din bud och rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Vi lydde icke dina tjenare, Propheterna, som predikade i ditt Namn vårom Konungom, Förstom, fädrom, och allo folkena i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Du, Herre, äst rättfärdig; men vi måstom skämma oss, såsom det ock nu går dem af Juda, och dem af Jerusalem, och hela Israel, både dem som när, och dem som fjerran äro, i all land, dit du dem utkastat hafver, för deras missgerningars skull, som de emot dig bedrifvit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ja, Herre, vi, våre Konungar, våre Förstar och våre Fäder, måstom skämma oss, att vi hafve syndat emot dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Men din, Herre vår Gud, är barmhertighet och förlåtelse; ty vi äre affällige vordne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Och lydde icke Herrans vår Guds röst, att vi hadom måst vandrat i hans lag, som han oss genom sina tjenare, Propheterna, förelade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Utan hele Israel öfverträdde din lag, och veko af, så att de icke lydde dine röst; derföre hafver ock den förbannelse och ed kommit öfver oss, som i Mose, Guds tjenares, lag skrifven står; ty vi hafve syndat emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Och han hafver hållit sin ord, som han talat hafver emot oss, och våra domare, som oss döma skulle; så att han hafver låtit gå så stor olycko öfver oss, att sådant är icke skedt under hela himmelen, såsom öfver Jerusalem skedt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Såsom det skrifvit är i Mose lag, så är allt detta stora onda öfver oss gånget; icke bådom vi heller inför Herran vår Gud, att vi måttom vändt oss ifrå våra synder, och tänkt uppå dina sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Derföre hafver icke heller Herren försummat sig med denna olyckone, utan hafver låtit henne gå oss utöfver; ty Herren vår Gud är rättfärdig i alla sina gerningar, som han gör; ty vi lydde icke hans röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Och nu, Herre vår Gud, du som ditt folk utur Egypti land med starka hand förde, och gjorde dig ett Namn såsom det nu är; vi hafve ju syndat, och hafve, (tyvärr) varit ogudaktige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Ack Herre! för alla dina rättfärdighets skull, håll upp af dine vrede och grymhet öfver din stad Jerusalem, och öfver ditt helga berg; ty för våra synders skull, och för våra fäders missgerningars skull, lider Jerusalem och ditt folk försmädelse, när alla de som häromkring äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Och nu, vår Gud, hör dins tjenares bön och hans begäran, och var miskundsam öfver din helgedom, som förlagd är, för Herrans skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Böj neder din öron, min Gud, och hör; låt upp din ögon, och skåda, huru vi förstörde äro, och staden, som efter ditt Namn nämnder är; ty vi ligge inför dig med våra böner, icke uppå våra rättfärdighet, utan på dina stora barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Ack Herre! hör; ack Herre! var miskundsam; ack Herre! akta uppå, och gör det; fördröj icke, för din egen skull, min Gud; ty din stad och ditt folk är nämndt efter ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Som jag ännu så talade och bad, och mina och mins folks Israels synder bekände, och låg med mine bön inför Herranom minom Gud, för mins Guds helga bergs skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Rätt då jag så talade i mine bön, flög den mannen Gabriel fram, den jag tillförene i synene sett hade, och tog uppå mig i aftonoffrens tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Och han underviste mig, och talade till mig, och sade: Daniel, nu är jag utsänd till att undervisa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Ty då du begynte att bedja, gick denna befallningen ut; och jag kommer fördenskull till att undervisa dig; ty du äst behagelig och täck; så märk nu till, att du må förstå synena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Sjutio veckor äro bestämda öfver ditt folk, och öfver din helga stad; så skall öfverträdelsen blifva förtagen, och synden betäckt, och missgerningen försonad, och den eviga rättfärdigheten framhafd, och synen och Prophetien beseglad, och den Aldraheligaste smord varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Så vet nu, och märk till, ifrå den tiden då befallningen utgår, att Jerusalem skall igen uppbyggd varda, intill den Förstan Christum, äro sju veckor; och två och sextio veckor, så skola gatorna och murarna åter uppbyggde varda, ändock i bullersam tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Och efter de två och sextio veckor skall Christus dödad varda, och de skola icke vilja honom; och ett Förstans folk skall komma, och förstöra staden och helgedomen, så att det skall blifva ändadt, såsom igenom en flod, och efter stridena skall det öde blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Men han skall mångom stadfästa förbundet i ena vecko långt; och midt i veckone skall offret och spisoffret återvända, och förödningens styggelse stå bredovid vingarna; och är beslutet, att det skall öde blifva allt intill ändan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Uti tredje årena Konungs Cores af Persien vardt Daniel, den Beltesazar het, något uppenbaradt, det visst och om dråplig ting är; och han aktade deruppå, och förstod synena väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'På samma tid var jag, Daniel, sorgse i tre veckor långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Jag åt ingen kräselig mat; kött och vin kom intet i min mun, och jag smorde mig ej heller, tilldess tre veckor framledna voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'På fjerde och tjugonde dagen i första månadenom var jag vid den stora älfvena Hiddekel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Och upplyfte min ögon, och såg; och si, der stod en man i linnkläder, och hade ett gyldene bälte omkring sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Hans kropp var såsom en hyacinth, hans anlete syntes såsom en ljungeld, hans ögon såsom brinnande bloss, hans armar och fötter såsom en glödandes koppar, och hans tal var såsom en stor dön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Och jag, Daniel, såg sådana syn allena, och de män, som när mig voro, sågo henne intet; dock föll en stor förskräckelse öfver dem, så att de flydde bort och gömde sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Och jag blef allena, och såg den stora synena; men ingen magt blef uti mig, och min hy vardt förvandlad på mig, och jag hade ingen magt mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Och jag hörde hans tal; och i det jag det hörde, seg jag neder uppå mitt ansigte till jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Och si, en hand tog uppå mig, och halp mig uppå knän, och uppå händerna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Och sade till mig: Du älskelige Daniel, gif akt uppå orden, som jag med dig talar, och res dig upp; ty jag är nu sänder till dig. Och då han sådant sade till mig, reste jag mig upp, och darrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Och han sade till mig: Frukta dig intet Daniel; ty ifrå första dagenom, då du af hjertat begärade förstå, och betvingade dig inför din Gud, äro din ord hörd, och jag är för dina skull kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Men den Försten öfver det riket i Persien hafver ståndit mig emot i en och tjugu dagar, och si, Michael, en af de ypperste Förstar, kom mig till hjelp; då behöll jag segren när Konungenom i Persien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Men nu kommer jag till att undervisa dig, huru dino folke härefter gå skall, ty synen skall ske efter någon tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Och som han detta med mig talade, slog jag mitt ansigte neder åt jordena, och teg stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Och si, en som var lik ene mennisko, tog uppå mina läppar. Då öppnade jag min mun, och talade, och sade till honom, som för mig stod: Min Herre, mine ledamöter bäfva mig öfver synena, och jag hafver ingen magt mer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Och huru kan mins Herras tjenare tala med minom Herra, efter ingen magt är nu mer uti mig, och jag hafver ej heller någon anda mer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Då tog åter en uppå mig, hvilken var såsom en menniska, och han stärkte mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Och han sade: Frukta dig intet, du älskelige man, frid vare med dig, var tröst, var tröst. Och som han med mig talade, förmannade jag mig, och sade: Tala, min Herre; ty du hafver stärkt mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Och han sade: Vetst du ock, hvarföre jag är kommen till dig? Nu vill jag åter mina färde, och strida med Förstanom i Persien; men när jag far mina färde, si, så skall Försten af Grekeland komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Dock vill jag låta dig förstå, hvad skrifvit är, det visserliga ske skall; och ingen är den mig hjelper derutinnan, utan edar Förste Michael.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Jag stod ock med honom uti första årena Darios den Medens, till att hjelpa och styrka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Och nu vill jag undervisa dig, hvad som i sanning ske skall: si, tre Konungar skola ännu blifva i Persien; men den fjerde skall få större rikedomar än alle andre. Och som han i sina rikedomar är aldramägtigast, skall han uppväcka alla emot det riket i Grekeland.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Sedan skall en mägtig Konung uppkomma, och regera med stora magt, och skall göra ehvad han vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Och som han är kommen uppå det högsta, skall hans rike brista, och dela sig i fyra himmelens väder; dock icke till hans affödo, ej heller med sådana magt, som hans varit hafver; ty hans rike varder utrotadt, och skall komma främmandom till lott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Och Konungen i söderlanden, den en af hans Förstar är, skall mägtig varda; men emot honom skall ock en mägtig varda, och regera, hvilkens välde skall stort varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Efter någor år skola de befrynda sig tillhopa; och Konungens dotter i söderlanden skall komma till Konungen i nordlanden, till att göra en förening; men hon varder icke blifvandes vid arms magt, ej heller hennes säd ståndandes; utan hon skall varda öfvergifven, samt med dem som henne framförde, och med barnena, och med dem som henne en tid långt vid magt hållit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Men en telning af hennes slägte skall uppkomma, han skall komma med härskraft, och falla in uti Konungens fäste i nordlanden, och skall blifva vid sig, och få öfverhandena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Och han skall bortföra deras gudar och beläten, samt med de kosteliga klenodier, både af silfver och guld, in uti Egypten; och skall blifva väl ståndandes för Konungenom i nordlanden i någor år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Och då han hafver dragit igenom det riket, skall han draga hem i sitt land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Men hans söner skola varda vrede, och samka tillhopa många härar; och den ene skall komma, och fara framåt såsom en flod, och åter reta den andra till vrede inför hans fäste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Då skall Konungen i söderlanden varda vred, draga ut och strida med Konungenom i nordlanden; och skall hemta tillhopa en så stor hop, att den andre hopen skall varda gifven honom i hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Och han skall föra samma hop bort; och skall hans hjerta förhäfva sig deraf, att han så mång tusend nederlagt hafver; men dermed får han intet öfverhandena med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Ty Konungen af nordlanden skall åter samka en större hop tillsammans, än de förre var; och efter någor år skall han draga dit med stor härskraft, och med stora rikedomar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Och på samma tid skola månge sätta sig upp emot Konungen af söderlanden; skola ock desslikes någre affällige af dino folke upphäfva sig, och uppfylla Prophetien och falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Alltså skall Konungen af nordlanden draga ut, och bålverk göra, och vinna fasta städer; och söderlandens armar skola icke kunna förtagat, och hans bästa folk skola icke kunna stå emot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Utan han skall, när han kommer till honom, skaffa sin vilja, och ingen skall kunna stå honom emot; han skall ock komma in uti det lustiga landet, och skall förderfvat genom dess hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Och skall ställa der sitt ansigte efter, att han må komma med allo sins rikes magt; men han skall förlika sig med honom, och skall gifva honom sina dotter till hustru, på det han skall förderfva honom; dock skall det icke lyckas honom, och der varder intet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Derefter skall han vända sig emot öarna, och vinna många af dem; men en Förste skall tvinga honom, så att han måste vända igen med skam; på det honom icke skall vederfaras mer skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Alltså skall han vända tillbaka till sins lands fäste, och skall stöta sig och falla, så att man intet skall finna honom mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Och i hans stad skall en uppkomma, hvilken sitta skall uti Konungsliga äro, som en öfverträdare och tyrann; men efter få dagar skall han förgås, dock hvarken genom vrede eller strid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Uti hans stad skall uppkomma en föraktelig man, hvilkom riksens ära intet betänkt var; han skall komma, och få sin vilja, och intaga riket med sötom ordom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Och de armar, hvilke såsom en flod komma, skola för honom, såsom med ene flod, öfverfallne och sönderbrutne varda; dertill ock den Försten, som förbundet med gjordt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Ty sedan han med honom befryndad är, skall han listeliga handla med honom; och skall draga upp, och varda honom öfvermägtig med fögo folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Och der skall lyckas honom, så att han skall komma in uti bästa städerna i landena, och skall beskaffa, det hans fäder eller föräldrar icke göra kunde, med rof, skinneri och byte; och skall fara efter de fasta städer, och det en tid långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Och han skall uppväcka sina magt och sitt hjerta emot Konungen i söderlanden, med stor härskraft: Då skall Konungen af söderlanden upprett varda till strid, med en stor mägtig härskraft; men han blifver intet beståndandes; ty förräderi skall varda gjordt emot honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Ja, de som hans bröd äta, de skola hjelpa till att förderfva honom, och hans här undertrycka, så att ganska månge skola slagne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Och båda Konungarnas hjerta skall tänka till, huru de skola göra hvarannan skada, och skola dock öfver ett bord tala falskeliga med hvarannan; men det skall fela dem; ty änden är ännu bestämd inuppå en annan tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Sedan skall han draga hem igen med stora rikedomar, och skall ställa sitt hjerta emot det helga förbundet; der varder han något beskaffandes; och sedan draga hem i sitt land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Derefter skall han åter, på belägen tid, draga emot söderlanden; men det skall icke lyckas honom i den andra resone, såsom i den första.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Ty af Chittim skola skepp komma emot honom, så att han skall varda förtviflad, och måste vända tillbaka igen; då skall han förgrymma sig emot det helga förbundet, och skall beskaffat, och skall se sig om, och draga dem till sig, som det helga förbundet öfvergifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Och hans armar skola der stå; de skola oskära helgedomen i fästet, och aflägga det dageliga offret, och uppsätta en förödnings styggelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Och han skall skrymta, och gifva dem ogudaktigom, som förbundet öfverträda, god ord; men det folk, som sin Gud känna, skola förmanna sig, och beskaffat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Och de förståndige i folket skola lära många andra; derföre skola de förföljde varda med svärd, eld, fängelse och rof, en tid långt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Men i den samma förföljelsen skall dem likväl ske en liten hjelp; dock skola månge gifva sig till dem bedrägeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Och de förståndige skola somlige förföljde varda, på det de skola varda bepröfvade, rene och klare, tilldess att det får en ända; ty det är ännu en annar tid för handene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Och Konungen skall göra ehvad han vill, och skall upphäfva och uppkasta sig öfver allt det Gud är, och skall grufveliga tala emot den som är alla gudars Gud, och det skall lyckas honom, intilldess vreden är ute; ty det är beslutet, huru länge det skall vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Och sina fäders Gud skall han intet akta; han skall icke akta uppå qvinnokärlek, eller uppå någon gud; ty han skall uppsätta sig emot alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Men sin egen gud, Maussim, skall han dyrka; ty en gud, der hans fäder intet af visst hafva, den skall han ära, med guld, silfver, ädla stenar och klenodier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Och han skall göra dem stora äro, som hjelpa honom stärka Maussim, med den främmande guden, som han utvalt hafver; och skall göra dem till herrar öfver stora rikedomar, och utskifta dem landet till lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Och på ändalyktene skall Konungen af söderlanden stötas med honom; och Konungen af nordlanden skall församla sig emot honom, med vagnar, resenärer, och mång skepp, och skall infalla i landen, och förderfva, och draga derigenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Och skall infalla uti det lustiga landet, och månge skola dräpne varda; men desse skola undslippa hans hand: Edom, Moab och Ammons barnas Förstar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Och han skall sända sina magt i landen, och Egypten skall icke undslippa honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Utan han skall med sitt indragande varda rådandes öfver gyldene och silfverskatter, och öfver all klenodier i Egypten, Libyen och Ethiopien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Men ett rykte skall förskräcka honom, af östan och af nordan; så att han skall draga ut med stora vrede, i det sinnet, att han skall många förgöra och förderfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Och han skall uppslå sins palatses tjäll emellan hafven, omkring det lustiga helga berget, tilldess med honom varder en ände; och ingen skall hjelpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'På samma tiden skall den store Försten Michael, som för ditt folk står, uppresa sig; ty en sådana bedröfvad tid skall komma, att ingen slik varit hafver, ifrå den tid menniskor hafva varit till, intill den tiden. Uti den samma tiden skall ditt folk frälst varda, alle de som i bokene skrefne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Och månge de, som under jordene sofva ligga, skola uppvakna, somlige till evigt lif, somlige till evig försmädelse och blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Men lärarena skola lysa såsom himmelens sken, och de som många undervisa till rättfärdighet, såsom stjernor i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Och du, Daniel, fördölj dessa orden och besegla denna skriftena intill den yttersta tiden; så skola månge deröfver komma, och finna ett stort förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Och jag, Daniel, såg, och si, der stodo två andre, en på denna strandene vid älfvena, en annar på den andra strandene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Och han sade till den som i linnkläder ofvanuppå älfvenes vatten stod: När skall då änden varda med sådana under?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Och jag lydde till den mannen, som i linnkläden stod ofvanuppå vattnena; och han hof upp sina högra och venstra hand till himmelen, och svor vid honom som lefver evinnerliga, att det skulle vara till en tid, och några tider, och en half tid; och när dess heliga folkens förskingring en ända hafver, så skall allt sådant ske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Och jag hörde det, men jag för stod det intet; och jag sade: Min Herre, hvad skall ske derefter?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Han sade: Gack, Daniel, ty det är fördoldt och besegladt intill yttersta tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Månge skola renade, luttrade och bepröfvade varda; och de ogudaktige skola föra ett ogudaktigt väsende; och de ogudaktige skola intet aktat; men de förståndige skola aktat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Och ifrå den tiden, när det dageliga offret borttaget, och förödelsens styggelse uppsatt varder, skall vara tusende tuhundrade och niotio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Väl är honom, som då förbidar, och räcker intill tusende trehundrad och fem och tretio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Men du, Daniel, gack bort, tilldess änden kommer, och hvila dig, att du må uppstå i dinom del, när dagarna hafva ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Detta är Herrans ord, som skedde till Osea, Beeri son, uti Ussia, Jotham, Ahas, Jehiskia, Juda Konungars, tid; och uti Jerobeams, Joas sons, Israels Konungs, tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Och då Herren först tog till att tala genom Osea, sade Herren till honom: Gack bort, och tag dig ena sköko till hustru, och skökobarn; ty landet löper ifrå Herranom i boleri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Och han gick bort, och tog Gomer, Diblaims dotter. Hon vardt hafvandes, och födde honom en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Och Herren sade till honom: Kalla honom Jisreel; ty det är ännu om en liten tid till görandes, så vill jag hemsöka de blodskulder i Jisreel, öfver Jehu hus, och skall göra en ända med Israels rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'På den tiden skall jag sönderbryta Israels båga, uti Jisreels dal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Och hon vardt äter hafvandes, och födde ena dotter; och han sade till honom: Kalla henne LoRyhama; ty jag vill intet mer förbarma mig öfver Israels hus; utan lag vill bortkasta dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Dock öfver Juda hus vill jag förbarma mig, och skall hjelpa dem genom Herran deras Gud; men jag vill icke hjelpa dem genom båga, svärd, strid, hästar eller resenärar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Och då hon afvant hade LoRyhama, vardt hon äter hafvandes, och födde en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Och han sade: Kalla honom LoAmmi; ty I ären icke mitt folk, så vill jag ej heller vara edar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Men talet på Israels barn skall varda lika som sanden i hafvena, den man hvarken mäla eller räkna kan; och det skall ske på det rum, der man till dem sagt hafver; I ären icke mitt folk; der skall man säga till dem: O! I lefvande Guds barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Ty Juda barn och Israels barn skola sammankomma, och skola hålla sig alla under ett hufvud, och draga upp utu landena; ty Jisreels dag skall vara en stor lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Säger edrom brödrom: De äro mitt folk, och edro syster, att hon är i ynnest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Säger domen öfver edra moder, att hon är intet mer min hustru, och jag vill intet hafva henne; beder henne kasta bort sitt boleri ifrå sig, och sitt horeri ifrå sin bröst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'På det jag icke skall afkläda henne nakna, och sätta henne, lika som hon var, då hon rådd var, och jag då gör henne såsom ett öde, och såsom ett torrt land, att jag icke låter henne dö af törst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Och icke förbarmar mig öfver hennes barn; ty de äro horobarn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Och deras moder är en hora; och den dem burit hafver, hon häller sig skamliga, I och säger: Jag vill löpa efter mina bolar, hvilke mig gifva bröd, vatten, ull, lin, oljo och dryck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Derföre, si, jag skall igentäppa din väg med törne, och gärda der en gård före, att hon icke skall finna sina stigar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Och då hon löper efter sina bolar, skall hon intet fä dem, och icke finna dem, när hon söker efter dem, och måste säga: Jag vill gå till min förra man igen, der jag bättre mådde, än jag nu mår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Ty hon vill icke veta, att jag är den som gifver henne korn, must och oljo, och hafver gifvit henne mycket silfver och guld, der de Baal af gjort hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Derföre vill jag taga mitt korn och must igen i sinom tid, och bortvända mina ull och lin, der hon sina blygd med betäcker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Nu vill jag upptäcka hennes skam för hennes bolars ögon, och ingen skall undsätta henne utu mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Och jag skall göra en ända med all hennes fröjd, högtider, nymånader, Sabbather, och alla hennes helgedagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Jag skall öde göra hennes vinträ och fikonaträ, efter hon säger: Det är min lön, som mine bolar gifva mig; jag skall göra en skog deraf, att vilddjuren skola uppäta det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Alltså skall jag hemsöka Baalims dagar öfver henne, hvilkom hon rökoffer gör, och pryder sig med spann och halsband, och löper efter sina bolar, och förgäter mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Derföre, si, jag vill locka henne, och föra henne uti öknena, och tala ljufliga med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Der vill jag gifva henne sin rätta vingård, och Achors dal, der man predika skall det I hoppas skolen; och der skall hon sjunga, lika som i hennes ungdoms tid, då hon utur Egypti land drog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Och på den tiden, säger Herren, skall du kalla mig: min man, och icke mer kalla mig: min Baal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Ty jag skall låta Baalims namn bortkomma utu hennes mun, så att man deras namn icke mer ihågkomma skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Och jag skall på den tiden göra dem ett förbund med vilddjuren på markene, med foglarna under himmelen, och med matkarna på jordene; och skall borttaga båga, svärd och krig utu landena, och låta dem bo säkre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Jag vill trolofva dig mig i evig tid; jag skall trolofva dig mig uti rättfärdighet och dom, uti nåd och barmhertighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Ja, uti trone vill jag trolofva dig mig; och du skall känna Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'På den tiden, säger Herren, vill jag höra; jag skall höra himmelen, och himmelen skall höra jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Och jorden skall höra kornet, must och oljo, och de skola höra Jisreel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Och jag skall behålla henne mig för en säd på jordene, och förbarma mig öfver henne som i ogunst var, och säga till det som intet var mitt folk: Du äst mitt folk; och det skall säga: Du äst min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Och Herren sade till mig; Gack än en gång bort, och älska den bolerska och horiska qvinnona; såsom Herren älskar Israels barn, och de vända sig likväl till främmande gudar, och bola för en kanno vins skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Och jag vardt med henne öfverens om femton silfpenningar och halftannat homer bjugg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Och sade till henne: Häll dig efter mig en tid långt, och bedrif intet boleri, och tillstäd ingen annan; ty jag vill ock hålla mig efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Ty Israels barn skola i långan tid blifva utan Konung, utan Första, utan offer, utan altare, utan lifkjortel, och utan Theraphim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Derefter skola Israels barn omvända sig, och söka Herran sin Gud, och sin Konung David; och skola ära Herran, och hans nåd i yttersta tidenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Hörer, I Israels barn, Herrans ord; ty Herren hafver orsak till att straffa dem, som i landena bo; ty der är ingen trohet, ingen kärlek, intet Guds ord i landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Utan Guds hädelse, lögn, mord, stöld och hor hafva fått öfverhandena, och den ena blodskulden kommer efter den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Derföre skall landet stå jämmerliga, och allom inbyggaromen illa gå; ty ock djuren på markene, och foglarna under himmelen, och fiskarna i hafvet skola förkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Dock man torf icke straffa eller tukta någon; ty mitt folk (vill ostraffadt vara; utan) tager sig före att straffa Presterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Derföre skall du falla om dagen, och Propheten falla med dig om nattena; alltså skall jag dina moder späka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mitt folk är förderfvadt, derföre att det icke lära vill; ty du aktar intet Guds ord, derföre vill jag ock intet akta dig, att du min Prest vara skall; du förgäter dins Guds lag, derföre vill jag ock förgäta din barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Ju flere de varda, ju mer de synda emot mig; derföre skall Jag ju så högt göra dem till blygd, som de I ärone högt uppe äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'De äro mins folks syndoffer, och styrka deras själ i deras missgerning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Derföre skall folkena gå lika som Prestomen; ty jag skall hemsöka deras väsende, och vedergälla dem såsom de förtjena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Så att de skola äta, och icke mätte varda; bedrifva boleri, och det skall intet bekomma dem; derföre, att de hafva öfvergifvit Herran, och intet aktat honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Boleri, vin och must göra menniskorna galna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mitt folk frågar sitt trä, och deras staf predikar dem; ty en boleris ande förstörer dem, så att de bedrifva boleri emot sin Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Ofvanpå bergen offra de, och på högomen röka de, under ek, lind och bok, efter de hafva skönan skugga; derföre varda ock edra döttrar skökor, och edra brudar horor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Och jag vill ej heller förtagat, då edra döttrar och brudar skämda och horor varda; efter I upptagen en annor Gudstjenst med de horor, och offren med de slemma slunor; ty det galna folket vill slaget varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Vill du Israel ju bedrifva boleri, att dock Juda icke ock finnes skyldig; går icke bort till Gilgal, och kommer icke upp till BethAven, och svärjer icke: Så sant som Herren lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Ty Israel löper lika som en galen ko; så skall ock Herren låta föda dem, såsom ett lamb det vildt löper.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Ty Ephraim hafver gifvit sig i sällskap med afgudar; så låt honom fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'De hafva gifvit sig uti svalg och boleri; deras herrar hafva lust dertill, att de komma skam åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Ett väder skall bortdrifva dem, hvilko de icke skola kunna emotstå, och måste öfver sina. Gudstjenst till blygd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Så hörer nu detta, I Prester, och akta häruppå, du Israels hus, och fattat i öronen, du Konungens hus; ty ett straff varder öfver eder gångandes. I som ena snaro i Mizpa ställt hafven, och ett utsträckt nät i Thabor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'De slagta fast mycket, och bedraga folket dermed; derföre måste jag straffa dem allasamman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Jag känner Ephraim väl, och Israel är för mig intet fördold; att Ephraim är en sköka, och Israel en sluna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'De tänka intet dertill, att de måtte vända sig till sin Gud; ty de hafva ett skökohjerta, och sköta intet om Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Derföre skall Israels högfärd för deras ansigte ödmjukad varda; och skola både Israel och Ephraim falla för deras ondskos skull; ock skall Juda falla med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Så skola de komma med sin får och fä, till att söka Herran, och dock intet finna honom; ty han hafver vändt sig ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'De förakta Herran, och föda främmande barn; derföre skall ock nymånaden uppfräta med dem deras offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Ja, blåser i basun i Gibea; ja, trummeter i Rama; ja, roper i BethAven, på hinsidon BenJamin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Ty Ephraim skall ett öde varda, på den tid jag dem straffandes varder. Derom hafver jag Israels slägte troliga varnat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Juda Förstar äro like dem som utflytta råmärke; derföre vill jag utgjuta mina vrede öfver dem, lika som vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Ephraim lider väld, och varder plågad; deruti sker honom rätt; ty han hafver gifvit sig uppå menniskobud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Jag är Ephraim såsom en mal, och Juda huse en plåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Och då Ephraim kände sina krankhet, och Juda sitt sår, drog Ephraim bort till Assur, och sände till Konungen i Jareb; men han kunde intet hjelpa eder, eller hela edart sår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Ty jag är Ephraim lika som ett lejon, och Juda huse lika som ett ungt lejon. Jag, jag rifver, och går min väg; jag förer dem bort, och ingen kan undsätta dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Jag vill gå åter till mitt rum igen, tilldess de känna sina skuld, och söka mitt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'När dem illa går, så måste de då bittida söka mig (och säga): Kommer, vi vilje till Herran igen; ty han hafver rifvit oss, han helar oss ock; han hafver slagit oss, han förbinder oss ock;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Efter två dagar gör han oss lefvande; på tredje dagen skall han uppväcka oss, sa att vi få lefva inför honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Och så varde vi deruppå aktande, och vinnlägge oss derom, att vi måge känna Herran; ty han kommer fram lika som en skön morgonrodne, och skall komma oss lika som ett regn, såsom ett serlaregn, hvilket landet fuktar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'O! huru väl vill jag göra emot dig, Ephraim; o! huru väl vill jag göra emot dig, Juda; ty den nåd som jag eder bevisa vill, skall vara såsom ett morgonmoln, och lika som en dagg, som om morgonen bittida faller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Derföre höflar jag dem genom Propheterna, och dödar dem genom mins muns tal, att din ord måga i ljuset komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Ty jag hafver lust till kärlek, och icke till offer; och till Guds kunskap, och icke till bränneoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Men de öfverträda förbundet, lika som Adam; deruti förakta de mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Ty Gilead är en stad full med afguderi och blodskulder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Och Presterna, samt med sina stallbröder, äro lika som röfvare, hvilke i försåt ligga, och mörda på den vägen till Sichem; ty de göra hvad de vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Jag ser det i Israels hus, der mig före grufvar; ty der bedrifver Ephraim boleri, Israel orenar sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Men Juda skall ännu hafva en skördeand för sig, när jag mins folks fängelse omvändandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Då jag Israel hjelpa vill, så finner man först Ephraims otro och Samarie ondsko, så att de bedrifva desto mer afguderi; och ändock de inbördes med tjufvar, och utantill med röfvare plågade äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Likväl vilja de intet märka, att jag dermed gifver akt uppå alla deras ondsko; men jag ser väl deras väsende, som de allstädes bedrifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'De fröjda Konungen genom sitt afguderi, och Förstarna genom sina lögner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Och äro allesamman horkarlar, lika som en bakougn, den bakaren het gör, när han utknådat hafver, och låter degen igenomsyras och jäsa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'I dag är vår Konungs högtid (säga de). Så varda då Förstarna hete lika som af vin; så bjuder han de falska lärare till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Ty deras hjerta är hett uti deras gudelighet, lika som en bakougn, när de offra och bedraga folket; men deras bakare sofver alla nattena, och om morgonen brinner han i ljusom låga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Så äro de ändå så hete i gudelighet, lika som en bakougn; ändock att deras domare uppfrätne varda, och alle deras Konungar falla; likväl är der ändå ingen ibland dem, som åkallar mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Ephraim varder öfverfallen af Hedningom; Ephraim är lika såsom en kaka, den ingen omvänder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Utan främmande uppäta hans kraft, likväl vill han intet aktat; han hafver ock fått grå hår, likväl vill han intet aktat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Och Israels högfärd varder för deras ögon ödmjukad; likväl omvända de sig intet till Herran sin Gud, och fråga ej heller något efter honom i allo desso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Ty Ephraim är lika som en galen dufva, den intet akta vill. Nu åkallade Egypten, nu löpa de till Assur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Men efter de så löpa, nu bit och nu dit, skall jag kasta mitt nät öfver dem, och rycka dem neder, lika som foglar under himmelen; jag skall straffa dem, såsom man det predikar uti deras församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Ve dem, att de ifrå mig vika. De måste förderfvade varda; ty de äro ifrå mig affällige vordne; jag ville väl förlossa dem, om de icke afguderi emot mig lärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Så åkalla de mig ock intet af hjertana, utan tjuta i sin lägre; de församlas för mats och drycks skull, och äro mig ohörsamme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Jag lärer dem, och stärker deras armar; men de tacka mig illa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'De omvända sig dock icke rätteliga, utan äro lika som en falsk båge; derföre måste deras Förstar falla genom svärd; deras trug skall uti Egypti land till spott varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Ropa högt, såsom en basun, och säg: Han kommer allaredo öfver Herrans hus, lika som en örn; derföre, att de hafva öfverträdt mitt förbund, och vordit affällige ifrå min lag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Skola de då ropa till mig: Du äst min Gud; vi känne dig, vi Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Men ehuru väl man det menar, så låter dock Israel intet säga sig; derföre måste fienden förfölja dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'De söka Konungar, och akta intet mig; de hålla sig intill Förstar, och jag måtte intet vetat; af sitt silfver och guld göra de afgudar, att de ju snarliga förgås skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Din kalf, o Samarla, förkastar han. Min vrede hafver förgrymmat sig öfver dem; det kan icke länge stå, de måste straffade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Ty kalfven är kommen ifrån Israel, och en mästare hafver gjort honom, och han kan ju ingen Gud vara; derföre skall Samarie kalf till stoft gjord varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Ty de så väder, och skola uppskära oväder; deras säd skall icke uppkomma, och deras frukt intet mjöl gifva; och om hon det än gifver, så skola dock främmande äta det upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israel varder uppäten; Hedningarna hafva sig med honom, lika som med ett oterigt kärile;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Derföre, att de löpa upp efter Assur, såsom vildåsnen i villone; Ephraim skänker bolarom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Ja, gifver ock Hedningom skatt; de samma Hedningar vill jag nu församla öfver dem; de skola snart ledse varda vid Konungens och Förstarnas tunga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Ty Ephraim hafver gjort mång altare, till att synda; så skola ock altaren varda honom till synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Om jag än mycket predikar dem om min lag, så kalla de det kätteri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Det de ännu mycket offra, och frambära kött och äta i så hafver dock Herren intet behag dertill; utan han vill ihågkomma deras ondsko, och hemsöka deras synder, som sig till Egypten vända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Israel förgäter sin skapare, och bygger kyrkor; så gör Juda många fasta städer; men jag skall sända eld uti hans städer i han skall förtära hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Du behöfver icke fröjda dig, Israel, eller berömma dig öfver annor folk; ty din Gudstjenst är ett horeri emot din Gud, der du nytto med söker, att alla lador måga varda fulla med korn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Derföre skola ladorna och presserna intet föda dig; och vinet skall dig intet lyckas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Och de skola icke blifva uti Herrans land; utan Ephraim måste åter in uti Egypten, och måste äta uti Assyrien det orent är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Der kunna de intet göra Herranom drickoffer af vin, eller eljest honom något till vilja; deras offer skall vara lika som de bedröfvades bröd, af hvilkom orene varda alle de som deraf äta; ty sitt bröd måste de äta för sig sjelf, och det skall intet varda buret in uti Herrans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Hvad viljen I då göra uti årstidom, och Herrans högtidom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Si, de måste bort för förderfvarenom, Egypten skall hemta dem tillhopa, och Moph skall begrafva dem; nässla skall växa, der nu deras lustiga afgudars silfver står; och törne uti deras hyddom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Hemsökningstiden är kommen, vedergällelsetiden; det skall Israel väl förnimma; Propheterna äro galne, och de andelige äro ursinnige, för dina stora missgerning, och för det stora hetsliga afguderiets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'De väktare i Ephraim höllo sig ett skifte intill min Gud; men nu äro de Propheter, som lägga honom snaro på alla hans vägar, genom det hetsliga afguderi, uti sins guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'De gå allt för djupt deruti, och äro förderfvade, såsom i Gibea tid; derföre skall han komma deras ondsko ihåg, och hemsöka deras synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Jag fann Israel i öknene lika som vindrufvor, och såg edra fäder lika som de första fikon på fikonaträt; men derefter gingo de till Baal Peor, och lofvade sig till den skamliga afguden, och vordo ju så styggelige som deras bolar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Derföre måste Ephraims härlighet bortflyga såsom en fogel; så att de hvarken skola föda, hafvande vara, eller afla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Och om de än uppfödde sin barn, så vill jag dock göra dem arfvingalösa, så att de skola intet folk vara; och ve dem, när jag ifrå dem viken är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Ephraim, som mig synes, är planterad och skön lika som Tyrus; likväl måste han nu få dråparenom sin barn ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Herre, gif dem; men hvad vill du gifva dem? gif dem ofruktsamma qveder, och försinade bröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'All deras arghet sker i Gilgal; der hatar jag dem, och skall, får deras onda väsendes skull, drifva dem bort utu mitt hus, och ingen kärlek mer bevisa dem; ty alle deras Förstar äro affällige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Ephraim är slagen, hans rot är borttorkad så att de ingen frukt mer bära kunna; och om de än födde, så vill jag dock, den åstundada fruktena af deras lifve döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Min Gud skall förkasta dem, derföre att de icke ville höra honom; och de måste gå villeråda ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israel är ett onyttigt vinträ vorden, hans frukt är ock alltså; så mycken frukt som han hafver, så mång altare gör han; der landet aldrabäst är, der sikta de aldraskönesta kyrkor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Deras hjerta är deladt, och de syndade nu; men deras altare skola nederbrutna, och deras stiktningar förstörda varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Ty de berömma sig, och säga: Konungen hafver oss icke ännu, och behöfve vi intet frukta Herran; hvad skulle Konungen göra oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'De svärja sig tillhopa förgäfves, och göra ett förbund; och sådana råd grönskas lika som ogräs på alla fårar i markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Samarie inbyggare församla sig till kalfven i BethAven; ty hans folk hafver gråtit öfver honom, der dock hans andelige plägade fröjda sig öfver hans härlighet; ty han är bortförd ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Ja, kalfven är förd in uti Assyrien, Konungen i Jareb till en skänk; alltså måste Ephraim stå med skam, och Israel skamliga gå med sitt anslag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Ty Konungen i Samarien är försvunnen, lika som fradgan på vattnena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'De höjder i Aven, der Israel med syndade, äro förlagde; tistel och törne växer på deras altare, och de skola säga: I berg, förskyler oss, och I backar, faller öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Israel, du hafver syndat allt ifrå Gibea tid; dervid hafva de ock blifvit; men en sådana strid, som emot de onda menniskor i Gibea skedde, den skall intet fatta dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Utan jag skall näpsa dem efter min vilja; så att folk skola komma församladt öfver dem, när jag spänner dem före med deras båda kalfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Ephraim är en kalf, som sig leda låter; jag skall ock en gång tröska med honom, och vill fara öfver hans sköna hals; jag skall lära Ephraim rida, och Juda plöja, och Jacob harfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Derföre sår rättfärdighet, och uppskärer kärlek, och plöjer annorlunda, medan tid är att söka Herran, tilldess han kommer, och lärer eder rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Ty I plöjen ogudaktighet, och uppskären orättfärdighet, och äten lögns frukt. Efter du nu förlåter dig uppå dina mänga hjeltar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Så skall upphäfva sig ett rumor i ditt folk, så att all din fäste skola förstörd varda, lika som Salman Arbeels hus förderfvade i stridenes tid, då modren öfver barnen slagen vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Rätt så skall eder ock gå i BethEl, för edra stora ondskos skull, att Israels Konung skall om morgonen bittida nederlagd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Då Israel ung var, hade jag honom kär, och kallade honom, min son, utur Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Men när man nu kallar honom, så vända de sig bort, och offra Baalim, och röka inför beläte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Jag tog Ephraim i hans arm, och ledde honom; men de hafva nu förgätit, huru jag halp dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Jag lät dem draga ett lustigt ok, och gå med mjuka tömmar: och jag tog oket utaf dem, och gaf dem foder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'På det han ju icke skulle vända sig åt Egypti land igen. Så är nu Assur vorden deras Konung; ty de ville intet omvända sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Derföre skall svärdet komma öfver deras städer, och skall förtära och uppfräta deras bommar, för deras anslags skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Mitt folk hafver ingen lust till att vända sig till mig och ehuru man predikar dem, så skickar sig dock ingen till att höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Hvad skall jag göra af dig, Ephraim? Huru skall jag dock plåga dig, Israel? Skall jag icke med rätto göra såsom Adama, och tillpynta dig lika som Zeboim? Men mitt hjerta hafver ett annat sinne; min barmhertighet är så brinnande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Att jag icke göra vill efter mina grymma vrede, eller vända mig till att jag platt förderfvar Ephraim; ty jag är Gud, och icke menniska, och är den Helige ibland dig dock skall mitt rike icke vara i stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Då skall man efterfölja Herran, och han skall ryta såsom ett lejon; och när han ryter, så skola de förskräcka sig, som vesterut äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Och de uti Egypten skola ock förskräckas, såsom en fogel; och de i Assurs land, lika som dufvor; och jag vill sätta dem uti sin hus, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Uti Ephraim är allstädes afguderi emot mig, och i Israels hus falsk Gudstjenst; men Juda håller sig ännu fast intill Gud, och till den rätta heliga Gudstjensten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Men Ephraim gapar efter väder, och löper efter östanväder, och gör hvar dag mer afguderi och skada; de göra förbund med Assur, och föra balsam uti Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Derföre skall Herren beskärma Juda, och hemsöka Jacob efter hans vägar, och löna honom efter hans förtjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Ja, (säga de) han hafver undertryckt sin broder i moderlifvena, och af allo magt kämpat med Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Han kämpade med Ängelen, och vann; ty han gret, och bad honom; der hafver han ju funnit honom i BethEl, och der hafver han talat med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Men Herren är Gud Zebaoth; Herre är hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Så omvänd dig nu till din Gud; gör barmhertighet och rätt, och hoppas allstädes uppå din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Men köpmannen hafver en falsk våg i sine hand, och bedrager gerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Ty Ephraim säger: Jag är rik, jag hafver nog; man skall intet ondt finna i allt mitt arbete, det synd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Men jag, Herren, är din Gud, allt ifrå Egypti land, och den dig låter ännu i hyddom bo, såsom man i årstider plägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Och talar till Propheterna; och jag är den som så många prophetier gifver, och förkunnar genom Propheterna, ho jag är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Uti Gilead är alltsamman afguderi, och i Gilgal offra de oxar fåfängeliga, och hafva så mång altare, som skylarna på åkren stå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Jacob miste fly uti Syrie land, och Israel måste tjena för ena hustru; för ena hustru måste han vakta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Men derefter förde Herren Israel utur Egypten, genom en Prophet, och lät bevara honom genom en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Men nu förtörnar honom Ephraim genom sina afgudar; derföre skall deras blod komma öfver dem, och deras herre skall vedergälla dem deras försmädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Då Ephraim lärda afguderi med magt, vardt han i Israel upphöjd; sedan syndade de genom Baal, och vordo deröfver dräpne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Men nu synda de än mycket mer, och göra beläte af sitt silfver, såsom de dem upptänka kunna, nämliga afgudar, de dock alltsammans smedsverk äro; likväl predika de om dem, att den som kalfvarna kyssa vill, han skall offra menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'De samme skola hafva morgonmoln, och den dagg som bittida faller; ja, lika som agnar, de utaf loganom bortblåsa, och såsom röken af en skorsten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Men jag är Herren, din Gud, allt ifrån Egypti land; och du skulle ju ingen annan Gud känna, utan mig; och ingen Frälsare, utan mig allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Jag lät mig ju vårda om dig i öknene, i eno torro lande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Men efter de födde äro, så att de äro mätte vordne, och nog hafva, upphäfver sig deras hjerta; derföre förgäta de mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Så skall jag ock varda emot dem lika som ett lejon, och lika som en parder; på vägenom vill jag vakta efter dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Jag skall möta dem lika som en björn, hvilkom hans ungar borttagne äro, och skall sönderrifva deras förstockada hjerta, och skall uppfräta dem der, såsom ett lejon; vilddjur skola rifva dem sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Israel, du rörer dig i olycko; ty din hälsa står allena när mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Hvar är din Konung, som dig hjelpa må uti alla dina städer; och dine domare, der du af sade: Gif mig Konung och Förstar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Nu väl, jag gaf dig; en Konung i mine vrede, och skall taga honom bort i mine grymhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Ephraims misshandel är sammanbunden, och hans synd är behållen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Ty honom skall ve varda, såsom ene barnafödersko; ty de äro oförsigtig barn. Den tid skall komma, att deras barn miste förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Men jag vill förlossa dem utu helvete, och hjelpa dem ifrå döden; död, jag skall vara dig ett förgift; helvete, jag skall vara dig en plåga; dock är trösten fördold för min ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Ty han skall skilja emellan bröder; der skall ett östanväder komma, och Herren uppstiga ifrån öknene, och uttorka hans brunnar, och utöda hans källor; han skall bortröfva all kostelig tyg och håvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Samarien skall öde varda; ty de äro sinom Gud ohörsamme; de skola falla genom svärd, och deras unga barn sönderkrossade, och deras hafvande qvinnor sönderrefna varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Omvänd dig, Israel, till Herran, din Gud; ty du äst fallen för din misshandels skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Tager dessa orden med eder, och vänder eder om till Herran; och säger till honom: Förlåt oss alla synder, och gör oss godt, så vilja vi offra våra läppars oxar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Assur skall intet hjelpa oss, och vi vilje icke mer rida på hästar, och icke mer säga till våra händers verk: I ären vår Gud; utan låt de faderlösa finna nåd när dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Så skall jag åter hela deras afträdelse; gerna vill jag hafva dem kär; då skall jag vända mina vrede ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Jag vill vara Israel lika som en dagg, att han skall blomstras såsom en ros, och hans rötter skola utsträcka sig såsom Libanon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Och hans grenar utvidga sig, att han skall vara så dägelig som ett oljoträ, och skall gifva en sådana god lukt som Libanon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Och skola åter sitta under hans skugga; af korn skola de föda sig, och blomstras lika som ett vinträ; hans åminnelse skall vara lika som vinet på Libanon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Ephraim, bort med de afgudar. Jag skall bönhöra honom, och leda honom; jag vill vara såsom ett grönt furoträ; på mig skall man finna dina frukt. Ho är vis, den detta förstår, och klok, den detta märker? Ty Herrans vägar äro rätte, och de rättfärdige vandra deruppå; men öfverträdarena falla deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Detta är Herrans ord, som skedde till Joel, Pethuels son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Hörer detta, I äldste, och akter häruppå, alle inbyggare i landena; om något sådant skedt är i edar tid, eller i edra fäders tid?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Säger edrom barnom deraf, och låter edor barn säga det för sin barn; och de samma barnen för sina efterkommande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Nämliga: Hvad efter gräsmatken blifver qvart, det uppäter gräshoppan; och hvad gräshoppan igenblifva låter, det äter flogmatken; och hvad flogmatken blifva låter, det fräter lusen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Vaker upp, I druckne, och gråter, och jämrer eder, alle vindrinkare, efter must; ty han är eder ifrån edar mun borttagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Ty ett mägtigt folk och otaligt drager hitupp uti mitt land; det hafver tänder lika som ett lejon, och oxlatänder lika som en lejinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Det samma föröder min vingård, afbryter min fikonaträ, barkar dem, och förkastar dem, så att deras qvistar äro hvite vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Jämra dig, lika som en jungfru, den en säck uppådrager för sin brudgummes skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Ty spisoffer och drickoffer är borto ifrå Herrans hus; Presterna, Herrans tjenare, sörja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Marken är förödd, och åkren står ömkeliga; kornet är förderfvadt, vinet står jämmerliga, och oljan klageliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Åkermännerna se skröpliga ut, och vingårdsmännerna gråta, för hvetes och korns skull, att utaf markene intet inbergas kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Så stå ock vinträn jämmerliga, och fikonaträn klageliga; dertill granatträ, palmträ, äpleträ, och all trä på markene äro förtorkad; ty menniskornas fröjd är till sorg vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Omgjorder eder, och gråter, I Prester; jämrer eder, I altarens tjenare; går in, och ligger i säcker, I mins Guds tjenare; ty både spisoffer och drickoffer är borto af edars Guds hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Helger ena fasto, kaller tillhopa menigheten; församler de äldsta, och alla landsens inbyggare, till Herrans edars Guds hus, och roper till Herran:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ack, ve den dagen! Ty Herrans dag är hardt när, och kommer såsom ett förderf ifrå dem Allsmägtiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Så skall maten för vår ögon borttagen varda, och ifrå vår Guds hus fröjd och glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Säden är bortruttnad i jordene, kornhusen stå öde, ladorna förfalla; ty kornet är förderfvadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'O! huru suckar boskapen? Fät råmar, ty de hafva ingen bet, och fåren försmäkta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Herre, dig åkallar jag; ty elden hafver afbränt de lustiga planar i öknene, och lågen hafver upptändt all trä på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Ja, vilddjuren ropa också till dig; ty vattubäckerna äro uttorkade, och elden hafver förbränt de lustiga planar i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Blåser med basuner i Zion, roper på mino helgo berge, darrer, alle landsens inbyggare; ty Herrans dag kommer, och är hardt när;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'En mörk dag, en bister dag, en mulen dag, och dimbog dag, lika som morgonrodnen utbreder sig öfver bergen; nämliga ett stort och mägtigt folk; hvilkets like tillförene icke varit hafver, och härefter icke varda skall i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'För honom går en förtärande eld, och efter honom en brinnande låge; landet är för honom lika som en lustgård; men efter honom lika som en vild öken, och ingen skall undslippa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'De äro till seende såsom hästar, och ränna såsom resenärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'De springa ofvanpå bergen, lika som der vagnar bullrade, och såsom en låge dånar i halm, såsom ett mägtigt folk, som till strids rustadt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Folken skola förskräcka sig för honom; all ansigte äro så blek som lerpottor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'De skola löpa såsom hjeltar, och bestiga murarna såsom krigsmän; hvar och en skall draga rätt fram, och intet försumma sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Ingen skall hindra den andra, utan hvar och en skall gå i sin orden; och när de storma och infalla, skola de intet såre varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'De skola rida omkring i stadenom, löpa på murarna, och stiga in uti husen; och såsom en tjuf infalla genom fenstren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'För honom darrar landet, och himmelen bäfvar; sol och måne varda mörk, och stjernorna förhålla sitt sken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Ty Herren skall låta gå sin dunder för sinom här; ty hans här är ganska stor och mägtig; han skall uträtta hans befallning; ty Herrans dag är stor, och fast förskräckelig; ho kan lida honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Så säger nu Herren: Vänder eder till mig af allt hjerta, med fastande, med gråtande, och med sörjande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Rifver edor hjerta, och icke edor kläder, och vänder eder till Herran, edar Gud; ty han är nådelig, barmhertig, tålig, och af stor mildhet, och låter sig snart ångra straffet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Ho vet, han förbarmar sig ju ännu och efter sitt straff nåde beviser, till spisoffer och drickoffer Herranom edrom Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Blåser med basun i Zion; helger ena fasto; kaller menigheten tillhopa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Församler folket, helger församlingena; sammankaller de äldsta, hafver de unga barn och däggobarn tillsammans; brudgummen gånge utu sinom kammar, och bruden utu sitt mak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Låter Presterna, Herrans tjenare, gråta emellan förhuset och altaret, och säga: Herre, skona dino folke, och låt icke din arfvedel till skam varda, så att Hedningarna få råda öfver dem; hvi vill du låta säga ibland folken: Hvar är nu deras Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Så skall då Herren hafva nit om sitt land, och skona sino folke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Och Herren skall svara, och säga till sitt folk: Si, jag skall sända eder korn, must och oljo tillfyllest, så att I skolen deraf nog hafva; och skall icke mer låta eder på skam komma ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Och skall jaga dem af nordan långt bort ifrån eder, och drifva honom bort uti ett torrt och öde land; nämliga hans ansigte bort emot hafvet österut, och hans ända bort emot yttersta hafvet; han skall ruttna och lukta för sina högfärds skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Frukta dig intet, du land, utan gläd dig, och var vid ett godt mod; ty Herren kan ock göra mägtig ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Frukter eder intet, I djur på markene; ty boningarna i öknene skola grönskas, och trän bära sin frukt, och fikonaträn och vinträn skola väl bära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Och I Zions barn, fröjder eder, och varer glade i Herranom, edrom Gud, den eder nådeligit regn gifver, och sänder eder neder morgonregn och aftonregn, såsom tillförene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Att ladorna varda fulla med korn, och presserna öfverflödighet af must och oljo hafva skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Och jag skall gifva eder de åren igen, som gräshoppor, flogmatkar, lus och gräsmatkar, som min stora här voro, den jag ibland eder sände, uppätit hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Att I skolen hafva nog till att äta, och prisa Herrans edars Guds Namn, den ibland eder under gjort hafver; och mitt folk skall icke mer till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Och I skolen förnimma, att jag är midt ibland Israel, och att jag är Herren, edar Gud, och ingen mer; och mitt folk skall icke mer till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Och derefter skall jag utgjuta min Anda öfver allt kött, och edra söner och döttrar skola prophetera; edre äldste skola hafva drömmar, och edre ynglingar skola se syner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Och vill jag på den tiden utgjuta min Anda, både öfver tjenare och tjenarinnor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Och skall gifva undertecken i himmelen och på jordene, nämliga blod, eld och rökdamb.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Solen skall förvandlad varda uti mörker, och månen uti blod, förr än den store och förskräckelige Herrans dag kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Och det skall ske: Ho som helst Herrans Namn åkallandes varder, han skall frälst varda; ty på Zions berg och i Jerusalem skall en salighet vara, såsom Herren sagt hafver, och när de andra qvarblefna, de Herren kallandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Ty si, uti de dagar och i den samma tidenom, när jag omvändandes varder Juda och Jerusalems fängelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Så vill jag sammansamka alla Hedningar, och skall föra dem neder i Josaphats dal, och vara der med dem till rätta, på mins folks och mins arfvedels Israels vägnar, att de hafva förstrött dem ibland Hedningarna, och delat emellan sig mitt land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Och kastat lott öfver mitt folk, och gifvit piltar för mat, och sålt pigor för vin, och fördruckit dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Och I af Zor och Zidon, och alla Philisteers gränsor, hvad hafven I med mig att göra? Viljen I trotsa mig? Nu väl, om I trotsen mig, så skall jag snarliga och med hast vedergälla eder det uppå edart hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'I som hafven tagit mitt silfver och guld, och min sköna klenodier, och fört dem in uti edra kyrkor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'Dertill ock sålt Juda barn och Jerusalems barn de Greker, på det I ju skullen låta dem komma långt bort ifrå sina gränsor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Si, jag skall uppväcka dem ifrå det rum, dit I dem sålt hafven, och skall vedergällat eder uppå edart hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Och skall åter sälja edra söner och döttrar genom Juda barn; de skola då sälja dem in uti rika Arabien, eno folke i fjerran land; ty Herren hafver det talat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Roper detta ut ibland Hedningarna: Helger ena strid, uppväcker de starka; låter komma och uppdraga allt krigsfolk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Görer af edrom plogbillom svärd, och af edrom liom spetsar; den svage hålle sig stark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Gadder eder tillhopa, och kommer hit, alle Hedningar allt omkring, och församler eder; der skall Herren nederlägga dina starka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Står upp, I Hedningar, och drager upp till Josaphats dal; ty der vill jag sitta, till att döma alla Hedningar allt omkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Slår till med liarna, ty säden är mogen; kommer neder, ty pressen är full, och pressen löper öfver; ty deras ondska är stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Det skall vara mycket folk här och der i skiljodalenom; ty Herrans dag är hardt när i skiljodalenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Sol och måne skola förmörkas, och stjernorna skola förhålla sitt sken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Och Herren skall ryta utaf Zion, och låta höra sina röst utaf Jerusalem, så att både himmel och jord skola bäfva; men Herren skall vara sino folke en tillflykt, och Israels barnom ett fäste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Och I skolen förnimma att jag, Herren, edar Gud, bor i Zion på mino helgo berge; då skall Jerusalem heligt vara, och inge främmande mera vandra derigenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'På den tiden skola bergen drypa sött vin, och högarna flyta mjölk, och alle Juda bäcker skola gå fulle med vatten; och der skall utgå en källa ifrå Herrans hus; hon skall vattna den dalen Sittim.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Men Egypten skall öde varda, och Edom en vild öken, för den orätts skull, som de på Juda barn bedrifvit hafva, och utgöto oskyldigt blod i deras land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Men Juda skall besuttet varda evinnerliga, och Jerusalem till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Och jag skall icke låta deras blod ohämnadt blifva; och Herren skall bo i Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Detta är det som Amos, den ibland herdarna var i Thekoa, öfver Israel sett hafver, uti Ussia tid, Juda Konungs, och i Jerobeams tid, Joas sons, Israels Konungs, tu år för jordbäfningen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Och sade: Herren skall ryta af Zion, och låta höra sina röst af Jerusalem, att hjordmarken skall stå jämmerlig och Carmel ofvantill förtorkas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Detta säger Herren: För tre och fyra Damasci lasters skull, skall jag icke skona dem; derföre, att de hafva tröskat Gilead med jerntaggar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Utan jag skall sända en eld uti Hasaels hus; han skall upptära Benhadads palats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Och jag skall sönderbryta bommarna i Damasco, och utrota inbyggarena på den markene Aven, samt med honom som spirona håller, utu det sköna huset; så att det folk i Syrien skall till Kir bortfördt varda, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Så säger Herren: För tre och fyra Gaza lasters skull, vill jag icke skona honom; derföre, att de hafva fångat än ytterligare de fångna, och fördrifvit dem bort uti Edoms land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Utan jag skall sända en eld uti murarna i Gaza; han skall förtära hans palats;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Och skall utkasta de inbyggare i Asdod, samt med honom som spirona håller, utur Askelon, och vända mina hand emot Ekron; så att förgöras skall hvad af de Philisteer ännu qvart blifvet är, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Detta säger Herren: För tre och fyra lasters skull, den stadsens Zors, vill jag intet skona honom; derföre, att de än ytterligare bortdrefvo de fångar in uti Edoms land, och intet tänkte uppå brödraförbund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Utan jag vill sända en eld uti murarna i Zor; han skall förtära hans palats.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Så säger Herren: För tre och fyra Edoms lasters skull, skall jag intet skona honom; derföre, att han hafver förföljt sin broder med svärd, och förgjort honom hans barn, och alltid varit honom arg i sine vrede, och drifvit sina grymhet allt framgent;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Utan jag skall sända en eld till Theman; han skall förtära palatsen i Bozra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Detta säger Herren: För tre och fyra Ammons barnas lasters skull, vill jag intet skona dem; derföre, att de hafva sönderrifvit de hafvande qvinnor i Gilead, på det de skulle förvidga sina gränsor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Utan jag skall upptända en eld uppå murarna i Rabba; han skall förtära hans palats, då man ropandes varder i stridstidenom, och då vädret kommandes varder i stormstidenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Så skall då deras Konung, samt med sina Förstar, varda fången bortförd, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Detta säger Herren: För tre och fyra Moabs lasters skull, vill jag intet skona honom; derföre, att de hafva uppbränt Konungens ben i Edom till asko;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Utan jag vill sända en eld i Moab; han skall förtära palatsen i Kerioth, och Moab skall dö uti buller, rop och basunsklang.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Och jag skall borttaga domaren ifrå honom, och dräpa alla hans Förstar med honom, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Detta säger Herren: För tre och fyra Juda lasters skull, vill jag intet skona honom; derföre, att de förakta Herrans lag, och icke hålla hans rätter, och låta sina lögn förföra sig, hvilka deras fäder efterföljt hafva,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Utan jag vill sända en eld i Juda han skall förtära palatsen i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Detta säger Herren: För tre och fyra Israels lasters skull, vill jag intet skona honom; derföre, att de sälja de rättfärdiga för penningar, och de fattiga för ett par skor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'De gå med fötterna öfver de fattiga, och hindra de elända allestäds; sonen och fadren sofva när ena qvinno, med hvilko de ohelga mitt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Och vid all altare slösa de af förpantad kläder, och dricka vin i sins Guds huse af saköre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Nu hafver jag dock förlagt Amoreen för dem, den så hög var som cedreträ, och hans magt såsom eker; och jag förderfvade hans frukt ofvantill, och bans rötter nedantill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Hafver jag ock fört eder utur Egypti land, och ledt eder uti öknene i fyratio år, att I de Amoreers land besitta skullen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Och af edrom barnom uppväckt eder Propheter, och af edrom ynglingom Nazareer? Är det icke så, I Israels barn? säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Så gåfven I de Nazareer dricka vin, och Prophetomen böden I, och saden: I skolen intet prophetera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Si, jag vill göra ibland eder ett gnisslande, såsom en vagn full af kärfvar gnisslar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Att den der rask är, skall icke kunna undfly, ej heller den starke något förmå, och den mägtige skall icke kunna undsätta sitt lif;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Och de bågaskyttar skola icke bestå; och den der rask är till att löpa, skall icke undlöpa; och den der rider, skall icke rädda sitt lit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Och den der aldramanligast är ibland de starka, måste i den tiden nakot undfly, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Hörer hvad Herren med eder talar, I Israels barn, nämliga med alla de slägter, som jag utur Egypti land fört hafver, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Utaf alla slägter på jordene hafver jag upptagit eder allena; derföre vill jag ock hemsöka eder uti alla edra missgerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Kunna ock två vandra tillhopa, utan de draga öfverens med hvarannan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Ryter ock ett lejon i skogenom, utan det hafver rof? Ropar ock ett ungt lejon utu sine kulo, utan det något fångit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Kommer ock någor fogel i snarona på jordene, der ingen foglafångare är? Tager man ock snarona upp af jordene, den ännu intet fångit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Blås man ock i basun i enom stad, och folket deraf icke förskräckes? Är ock något ondt i stadenom, det Herren icke gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Ty Herren Herren gör intet, utan han uppenbarar sinom tjenarom, Prophetomen, sina hemlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Lejonet ryter, ho skulle icke frukta sig? Herren Herren talar, ho skulle icke prophetera?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Förkunner uti palatsen i Asdod, och uti palatsen i Egypti land, och säger: Församler eder på Samarie berg, och ser till, hvilket stort mordskri och orätt der är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'De passa intet på någon rätt, säger Herren; utan öfvervåld och skada går hvart om annat i deras husom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Derföre säger Herren Herren alltså: Man skall belägga detta landet allt omkring, och störta dig neder ifrå dine magt, och skinna din hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Detta säger Herren: Lika som en herde rycker eno lejone två fötter, eller ett stycke af ett öra utu munnenom; alltså skola Israels barn utryckte varda, de som bo i Samarien, och hafva i hörnet ett lägre, och i Damasco ena säng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Hörer, och betyger i Jacobs hus, säger Herren, Herren Gud Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Ty på den tiden, då jag Israels synder hemsökandes varder, vill jag hemsöka de altare i BethEl, och bortbryta hornen af altaret, att de skola falla neder på markena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Och skall slå både vinterhus och sommarhus; och de elphenbenshus skola till intet varda, och mång hus förderfvad blifva, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Hörer detta ordet, I feta kor, som på Samarie berg ären, och gören dem fattiga orätt, och förtrycken den elända, och sägen till edra herrar: Bär hit, låt oss dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Herren Herren hafver svorit vid sina helighet, si, den tiden kommer öfver eder, att man skall bära eder bort på stänger, och edra efterkommande i fiskakettlar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Och skolen utgå igenom refvor, hvar och en för sig, och intill Harmon bortkastade varda, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Ja, kommer hit till BethEl, och bedrifver synd: och till Gilgal, att I mågen föröka synderna; och bärer fram edor offer om morgonen, och edra tiond på tredje dagen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Och röker af surdeg till tackoffer, och prediker om friviljogt offer, och förkunner det; ty I hafven det gerna så, I Israels barn, säger Herren Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Derföre hafver jag ock i alla edra städer gifvit eder lediga tänder, och brist på bröd I all edor rum; likväl omvänden I eder intet till mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Och jag hafver tillbakahållit regn öfver eder, medan ännu tre månader voro intill skördetiden; och jag lät regna uppå den ena staden, och uppå en annan stad lät jag intet regna; en åker vardt beregnad, och den andra åkren, som intet beregnad vardt, förtorkades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Och två eller tre städer drogo intill en stad, på det de måtte dricka vatten, och kunde icke få sina nödtorft; likväl omvänden I eder intet till mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Jag plågade eder med torko, och med brandkorn; så åto ock gräsmatkar upp allt det i edra lustgårdar, vingårdar, på fikonaträ och oljoträ växte; likväl omvänden I eder intet till mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Jag sände pestilentie ibland eder, lika som uti Egypten; jag drap edra unga män med svärd, och lät bortföra edra hästar fångna; jag lät stanket af edrom lägrom gå upp i edra näso; likväl omvänden I eder icke till mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Jag omstörte somliga af eder, lika som Gud omstörte Sodom och Gomorra, så att I voren som en brand, den utur eldenom ryckt varder; likväl vänden I eder intet till mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Derföre vill jag så göra med dig, Israel; efter jag nu så vill göra med dig, så skicka dig Israel, Och gack emot din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Ty si, han är den som gör bergen, skapar vädret, och kungör menniskone hvad hon tala skall; han gör morgonrodnan (och) mörkret; han går på jordenes höjder; han heter Herren Gud Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Hörer, I af Israels hus, detta ordet: ty jag måste göra denna klagovisona öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Jungfrun Israel är fallen, så att hon intet mer uppstå kan; hon är stött neder till jordena, och ingen är som upphjelper henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Ty så säger Herren Herren: Den staden, der tusende utgå, der skola icke utan hundrade qvar blifva i och der hundrade utgå, skola icke utan tio igen behållne blifva i Israels bus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Derföre, så säger Herren till Israels hus: Söker mig, så skolen I lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Söker icke BethEl, och kommer intet till Gilgal, och går icke till BerSeba; förty Gilgal, skall varda fånget bortfördt, och BethEl skall i jämmer komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Söker Herran, så skolen I lefva, på det i Josephs huse icke uppågå skall en eld, hvilken förtärer, och icke utsläckas kan uti BethEl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'I som förvänden rätten uti malört, och stöten rättvisona neder till jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Han gör sjustjernorna och Orion han gör af mörkret morgonen, och af dagen mörka nattena; han kallar vattnet i hafvena, och gjuter det uppå jordenes krets; han heter Herren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Den der en förstöring beställer öfver den starka, och låter komma en förstöring öfver den fasta staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Men de äro honom gramse, som dem uppenbara straffar, och hafva en styggelse vid den som helsosamt lärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Derföre, efter I undertrycken den fattiga, och tagen korn af honom i storom bördom, så skolen I icke bo uti husomen, som I af huggen sten uppbyggt hafven, och icke dricka det vin, som I uti de sköna vingårdar planterat hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Ty jag vet edor öfverträdelse, den mycken är, och edra synder, de der starka äro; huru I trängen de rättfärdiga, och tagen gåfvor, och undertrycken de fattiga i domenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Derföre måste den kloke tiga på den tiden; ty det är en ond tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Söker det goda, och icke det onda, på det I lefva mågen; så skall Herren Gud Zebaoth vara med eder, såsom I berömmen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Hater det onda, och älsker det goda; skaffer rätt i portenom; så skall Herren Gud Zebaoth vara nådelig öfver de igenlefda i Joseph.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Derföre, så säger Herren Gud Zebaoth, Herren: Det skall varda klagogråt på alla gator, och på alla vägar skall man säga: Ack ve, ack ve! Och man skall kalla åkermannen till sorg, och till klagogråt den der gråta kan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Uti alla, vingårdar skall klagogråt vara; ty jag vill fara fram ibland eder, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Ve dem som begära Herrans dag! Hvad skall han eder? Ty Herrans dag är ett mörker, och icke ljus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Lika som då någor flydde för ett lejon, och honom mötte en björn; och lika som någor in uti ett hus komme, och ledde sig med handene utmed väggene, och en orm stunge honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Ty Herrans dag skall ju vara mörk, och icke ljus; skum, och icke klar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Jag är edrom högtidom gramse, och föraktar dem, och kan icke lida edart rökoffer uti edra församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Och om I mig än offraden bränneoffer och spisoffer, så hafver jag dock ingen lust dertill; så orkar jag ock icke se edart feta tackoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Haf bort dina visors buller ifrå mig; ty jag orkar icke höra ditt psaltarespel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Men rätten skall uppenbarad varda lika som vatten, och rättvisan såsom en stark flod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Hafven I, af Israels hus, ock offrat mig slagtoffer och spisoffer i öknene, i fyratio år långt? Ja, skönliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'I bären edars Molochs hyddor, och edra afgudars beläte, och edra gudars stjerno, som eder sjelfve gjort haden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Så skall jag låta föra eder hädan bort till Damascus, säger Herren, som Gud Zebaoth heter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Ve dem stoltom i Zion, och dem som förlåta sig uppå Samarie berg, hvilke sig hålla får de aldrabästa i hela verldene; och regera i Israels hus, såsom dem täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Går bort till Calne, och skåder; och dädan bort till Hamath, den stora staden; och drager dädan neder till Gath de Philisteers, hvilka bättre Konungarike varit hafva än dessa, och deras gränsa större än edor gränsa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Likväl vordo de förjagade, då deras onda stund kom; och I regeren med öfvervåld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Och liggen i elphenbenssängar, och prålen på edor tapeter; och äten det bästa, af hjordenom, och de gödda kalfvar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Och spelen på psaltare, och dikten eder visor, såsom David;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Och dricken vin utu skålar, och smörj en eder med balsam; och bekymrer eder intet om Josephs skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Derföre skola de nu gå främst ibland dem som fångne bortförde varda; och de prålares slösande skall återvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Ty Herren Herren hafver svorit vid sina själ, säger Herren Gud Zebaoth: Mig förtryter Jacobs högfärd, och är deras palatsom gramse; och jag skall desslikes öfvergifva staden, med allt det deruti är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Och om än tio män qvare blefvo uti ett hus, skola de likväl dö;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Så att hvars och ens faderbroder och moderbroder tager honom, och måste draga hans ben utu huset, och säga till den som i husens kammar är: Äro der ock flere? Och han skall svara: De äro alle sin kos: och skall säga: Var tillfrids; ty de ville icke, att man på Herrans Namn tänka skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Ty si, Herren hafver budit, att man skall slå de stora husen, att de skola få refvor, och de små husen, att de få hål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Ho kan ränna med hästom, eller plöja med oxom på hälleberget? Ty I vänden rätten uti galla, och rättvisones frukt uti malört;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Och förtrösten eder uppå det som platt intet är, och sägen: Äro vi icke mägtige och starke nog?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Derföre, si, jag skall uppväcka ett folk öfver eder af Israels hus, säger Herren Gud Zebaoth; det skall tränga eder ifrå det rummet, der man går till Hamath, intill pilträbäcken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Herren Herren viste mig ena syn; och si, der stod en, som gjorde gräshoppor, rätt då som kornet begynte skjuta sig i ax, sedan Konungen hade låtit klippa sin får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Som de nu ville bortfräta allan grödan på landena, sade jag: Ack! Herre Herre, var nådelig; ho skall upphjelpa Jacob igen? Ty han är ju fast ringa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Då ångrade det Herranom; och Herren sade: Nu väl, det skall icke ske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Herren Herren viste mig ena syn; och si, Herren Herren kallade elden till att straffa, dermed han skulle förtära ett stort djup: och han bortfrätte allaredo ett stycke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Då sade jag: Ack! Herre Herre, håll upp; ho skall upphjelpa Jacob igen? Ty han är ju fast ringa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Då ångrade Herranom det ock; och Herren Herren sade: Det skall icke heller ske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Men han viste mig denna synena; och si, Herren stod på enom mur, den med eno mätosnöre mäld var, och han hade mätosnöret i sine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Och Herren sade till mig: Hvad ser du, Amos? Jag sade: Ett mätosnöre. Då sade Herren till mig: Si, jag skall draga ett mätosnöre midt igenom mitt folk Israel, och intet mer öfverse med dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Utan Isaacs höjder skola förödda, och Israels kyrkor förlagda varda; och jag vill stå upp med svärdena öfver Jerobeams hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Då sände Amazia, Presten i BethEl, till Jerobeam, Israels Konung, och lät säga honom: Amos gör ett uppror emot dig uti Israels hus. Landet orkar icke lida hans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Ty Amos säger alltså: Jerobeam måste dö genom svärd, och Israel skall varda fången bortförd utu sitt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Och Amazia sade till Amos: Du Siare, gack hädan, och fly in uti Juda land, och föd dig der, och prophetera der;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Och prophetera intet mer i BethEl; ty det är Konungens kyrka och riksens hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Amos svarade, och sade till Amazia: Jag är ingen Prophet, eller någon Prophetes son; utan jag är en fäherde, den mulbär afhemtar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Men Herren tog mig ifrå hjordenom, och Herren sade till mig: Gack bort, och prophetera mino folke Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Så hör nu Herrans ord: Du säger: Prophetera intet emot Israel, och tala intet emot Isaacs hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Derföre säger Herren alltså: Din hustru skall i stadenom skämd varda, och dine söner och döttrar skola falla genom svärd, och din åker skall med snöre utdelad varda; men du skall dö uti ett orent land, och Israel skall utu sitt land fördrifven varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Herren Herren viste mig ena syn; och si, der stod en korg med sommarfrukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Och han sade: Hvad ser du, Amos? Men jag svarade: En korp; med sommarfrukt. Då sade Herren till mig: Änden är kommen på mitt folk Israel; jag vill icke mer öfverse med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Och de visor uti kyrkomen skola uti gråt vända varda på den tiden, säger Herren Herren. Der skola mäng död lekamen ligga allestäds, de man skall hemliga bortbära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Hörer detta, I som förtrycken den fattiga, och förderfven den elända i landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Och sägen: När vill då den nymånaden hafva en ända, att vi måge korn sälja? och Sabbathen, att vi måge hafva kom falt, och förminska skäppona, och förhöja siklen, och förfalska vigtena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'På det vi måge få de fattiga under oss för penningar, och de torftiga för ett par skor, och sälja agnar för korn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Herren hafver svorit emot Jacobs högfärd: Hvad gäller, om jag sådana deras gerningar evinnerliga förgäta skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Skulle för slik styckers skull landet icke bäfva, och alla inbyggarena gråta? Ja, det skall alltsamman lika som med en flod öfverlupet, och bortfördt, och öfvertäckt varda, lika som floden gör uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'På den tiden, säger Herren Herren, skall jag låta solena nedergå om middagen, och landet mörkt varda om ljusa dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Jag skall förvända edra högtidsdagar sorg, och alla edra visor i klagogråt; och jag skall låta komma en säck öfver alla länder, och göra all hufvud kullot; och skall göra dem ena sorg, lika som man sörjer öfver enda sonen; och de skola få en ömkelig ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Si, tiden kommer, säger Herren Herren, att jag skall sända en hunger i landet; icke en hunger efter bröd, eller törst efter vatten, utan efter att höra Herrans ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Så att de skola löpa omkring hit och dit, ifrå det ena hafvet till det andra, ifrå norr och till öster, till att söka Herrans ord, och skola dock icke finnat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'På den tiden skola sköna jungfrur och ynglingar försmäkta af törst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'De der nu svärja vid Samme synd, och säga: Så sant som din gud i Dan lefver; så sant som din gud i BerSeba lefver; ty de skola så falla, att de intet skola kunna uppstå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Jag såg Herran ståndandes på altaret, och han sade: Slå uppå knappen, sa att dörrträn bäfva; ty deras girighet skall komma dem allom uppå deras hufvud; och jag skall dräpa deras efterkommande med svärd, så att ingen undfly eller undslippa skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Och om de An grofve sig neder i helvetet, så skall dock min hand hemta dem dädan; och om de än före upp i himmelen, skall jag dock stöta dem neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Och om de än gömde sig ofvanuppå Carmels berg, så skall jag der uppsöka dem, och taga dem dädan; och om de än gömde sig för min ögon i hafsens djup, så skall jag dock befalla ormomen, att de skola der stinga dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Och om de än fångne gingo för sina fiendar, så vill jag dock befalla svärdena, att det skall der dräpa dem; ty jag vill hålla min ögon öfver dem till ondt, och icke till godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Ty Herren Herren Zebaoth är sådana; när han kommer vid ett land, då försmälter det, så att alle inbyggarena gråta skola, att det skall allt öfver dem löpa lika som en flod, och öfvertäcka dem lika som floden i Egypten gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Han är den, som sin sal bygger i himmelen, och sina hyddo grundar på jordene; han kallar vattnet i hafvena, och gjuter det på jordena; Herre heter han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Åren I, Israels barn, för mig icke lika som de Ethioper, säger Herren? Hafver jag icke fört Israel utur Egypten, och de Philisteer utu Caphthor, och de Syrer utu Kir?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Si, Herrans Herrans ögon se uppå ett syndigt rike, så att jag platt förgör det af jordene; ändock jag icke Jacobs hus platt förgöra vill, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Dock likväl, si, jag vill befalla, och Israels hus sikta låta ibland alla Hedningar, lika som man siktar med ett såll; och kornen skola icke falla uppå jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Alle syndare i mitt folk skola dö genom svärd, de der säga: Den olyckan är intet så när, och hon vederfars oss intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'På den tiden skall jag igen upprätta den förfallna Davids hyddo, och igentäppa hennes refvor, och igenbota hvad afbrutet är, och skall uppbygga henne, lika som hon i förtiden varit hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'På det att de besitta skola de qvarlefda i Edom, och de qvarblefna ibland alla Hedningar, öfver hvilka mitt Namn skall predikadt varda, säger Herren, den detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Si, tiden kommer, säger Herren, att man skall tillika plöja och uppskära, och tillika pressa vin och så; och bergen skola drypa sött vin, och alla backar skola fruktsamme vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Ty jag vill omvända mins folks Israels fängelse, att de skola uppbygga de öde städer, och besitta dem; plantera vingårdar, och dricka der vin af; göra trägårdar, och äta der frukt af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Ty jag vill plantera dem uti sitt land, så att de icke mer skola varda utrotade utu sitt land, det jag dem gifvit hafver, säger Herren, din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Detta är Obadia syn. Så säger Herren Herren om Edom: Vi hafve hört af Herranom, att ett bådskap är sändt ibland Hedningarna: Upp, och låter oss örliga emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Si, jag hafver gjort dig ringa ibland Hedningarna, och mycket föraktad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Dins hjertas högmod hafver bedragit dig, efter du bor uti stenklyftor, på din höga slott, och säger i dino hjerta: Ho vill drifva mig här neder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Om du än fore uppe i höjdene, lika som en örn, och gjorde ditt näste ibland stjernorna, så vill jag likväl draga dig der neder, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Om tjufvar eller förhärjare komma om nattena öfver dig, o! huru tyst skall du då varda; ja, de skola nog stjäla; och om vinhemtare öfver dig komma, så skola de icke lefva dig någon efterhemtning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'O! huru skola de utransaka Esau, och uppsöka hans håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Alle de, som i förbund med dig äro, de skola drifva dig bort utu landet; de män der du sätter din tröst till, de skola bedraga dig, och öfverfalla dig; de som äta ditt bröd, de skola förråda dig, förr än du vetst der något af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Hvad gäller, säger Herren, jag skall på den tiden nederlägga de visa i Edom, och den klokhet på Esau berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Ty dine starke i Theman skola förtvifla, på det de alle skola förgås genom mord, på Esau berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'För den orätts skull, som emot din broder Jacob bedrifven vardt, skall du på all skam komma, och till evig tid förlagd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Den tid, då du emot honom stod, då främmande bortförde hans här fångnan, och utländningar drogo in igenom hans portar, och kastade lott öfver Jerusalem, då vast du lika som en af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Du skall intet mer se dina lust på dinom broder, i hans eländes tid, och skall icke mer glädja dig öfver Juda barn, i deras jämmers tid; och skall icke tala så stolt ord med din mun, i deras ångests tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Du skall icke indraga genom mins folks portar, i deras jämmers tid; du skall icke se dina lust på deras olycko, uti deras jämmers tid; du skall icke sända emot deras här, uti deras jämmers tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Du skall icke stå i vägaskäl, till att mörda deras flyktiga; du skall icke förråda deras qvarblefna, i deras ångests tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Ty Herrans dag är hardt när öfver alla Hedningar. Lika som du gjort hafver, så skall dig ske igen; och såsom du förtjent hafver, så skall det komma dig uppå ditt hufvud igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Ty lika som I på mitt helga berg druckit hafven, så skola alle Hedningar dricka allt framgent; ja, de skola utsupat och uppsvälgat, att det skall vara lika som der aldrig något varit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Men på Zions berg skola ännu somlige hulpne varda; de skola vara en helgedom, och Jacobs hus skall besitta sina besittare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Och Jacobs hus skall en eld varda, och Josephs hus en låge, men Esau hus strå; de skola upptända och förtära det, så att Esau huse intet skall qvart blifva; ty Herren hafver det talat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Och de söderut skola, besitta Esau berg, och de i dalomen skola besitta de Philisteer; ja, de skola besitta Ephraims mark, och Samarie mark; och BenJamin Gileads berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Och de fördrefne af denna Israels barnas här, hvilke ibland de Cananeer allt intill Zarpath äro, och de fördrefne af Jerusalems stad, hvilke i Sepharad äro, skola besitta de städer söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Och frälsare skola uppkomma på Zions berg, till att döma Esau berg. Alltså skall då riket vara Herrans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Herrans ord skedde till Jona, Amitthai son, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Upp, och gack in uti den stora staden Nineve, och predika derinne; förty hans ondska är kommen upp för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Men Jona stod upp, och flydde ifrå Herranom, och ville ut till hafs, och kom neder till Japho; och då han fann ett skepp, som till hafs fara ville, gaf han skepplön, och steg deruti, på det han skulle fara med dem till hafs, ifrå Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Då lät Herren komma ett stort väder uppå hafvet, och en stor storm upphof sig på hafvet, så att man mente att skeppet skulle söndergå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Och skeppmännerna fruktade sig, och ropade hvar och en till sin gud, och kastade de tyg, som i skeppena voro, uti hafvet, att det skulle lättare varda; men Jona var stigen neder i skeppet, låg och sof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Då gick skepparen till honom, och sade till honom: Hvi sofver du? Statt upp, åkalla din Gud, att Gud tilläfventyrs ville tänka uppå oss, att vi icke förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Och den ene sade till den andra: Kommer, vi vilje kasta lott, att vi förfara måge, för hvilkens skull oss så illa går. Och då de kastade lotten, råkade det på Jona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Då sade de till honom: Säg oss, hvarföre går oss så illa? Hvad är din handel, och hvadan äst du kommen? Utaf hvad land äst du, och af hvad folk äst du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Han sade till dem: Jag är en Ebreer, och fruktar Herran Gud af himmelen, som hafvet och det torra gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Då fruktade männerna storliga, och sade till honom: Hvi hafver du då detta gjort? Ty de visste, att han flydde ifrå Herranom; ty han hade sagt dem det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Då sade de till honom: Hvad skole vi då göra med dig, på det hafvet måtte oss stilla varda? Ty hafvet gick fast uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Han sade till dem: Tager och kaster mig i hafvet, så stillas eder hafvet; ty jag vet, att sådana stor storm öfver eder kommer för mina skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Och männerna rodde, att de måtte åter komma till lands igen; men de kunde intet: ty hafvet gick svårliga uppå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Då ropade de till Herran, och sade: Ack! Herre, låt oss icke förgås för denna mansens själs skull, och räkna oss icke oskyldigt blod till; ty du, Herre, gör, såsom dig täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Och de togo Jona, och kastade honom i hafvet; då vände hafvet igen af sinom storm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Och männerna fruktade Herran storliga, och gjorde Herranom offer och löfte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Och Herren förskaffade en stor fisk, till att uppsluka Jona; och Jona var i fiskens buk tre dagar och tre nätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Och Jona bad till Herran sin Gud, i fiskens buk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Och han sade: Jag ropade till Herran i mine ångest, och han svarade mig; jag ropade utu helvetes buk, och du hörde mina röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Du kastade mig uti djupet, midt i hafvet, så att floderna kommo omkring mig; alle dine våger och böljor gingo öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Jag tänkte, att jag bortkastad var ifrå din ögon; men jag skall ännu få se ditt helga tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Vattnen omhvärfde mig allt intill mitt lif; djupet omgrep mig, sjövassen öfvertäckte mitt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Jag sönk neder till bergsgrunden, jorden hade beslutit mig med sina bommar evinnerliga; men du hafver fört mitt lif utu förderfvet, Herre min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Då min själ öfvergaf sig, tänkte jag uppå Herran, och min bön kom till dig, uti ditt helga tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Men de som förlåta sig uppå sina gerningar, hvilka dock intet äro, de akta intet om nådena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Men jag vill offra med tacksägelse. Min löfte vill jag betala Herranom, att han mig hulpit hafver. Och Herren sade till fisken, och han utsputade Jona in uppå landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Och Herrans ord skedde annan gång till Jona, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Statt upp, och gack in uti den stora staden Nineve, och predika honom den predikan, som jag dig säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Då stod Jona upp, och gick bort till Nineve, såsom Herren sagt hade; men Nineve var en Guds stad, tre dagsresor stor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Och då Jona begynte ingå ena dagsreso in i staden, predikade han, och sade: Det är ännu fyratio dagar, och så skall Nineve förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Då trodde de Ninevitiske män uppå Gud, och läto predika fasto, och drogo säcker uppå sig, både store och små.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Och då det kom för Konungen i Nineve, stod han upp af sitt säte, och lade af sitt purpur, och tog en säck omkring sig, och satte sig i asko;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Och lät utropa och säga i Nineve, af Konungens och hans väldigas befallning, alltså: Det skall hvarken menniska eller djur, hvarken fä eller får något smaka; och man skall intet hafva dem i bet, eller låta dem vatten dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Och skola taga säcker om sig, både folk och fä, och ropa stadeliga till Gud; och hvar och en vände sig ifrå sinom onda väg, och ifrå sina händers ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Ho vet? Gud måtte omvända sig, och ångra det, och vända sig ifrå sine grymma vrede, att vi icke förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Då nu Gud såg deras gerningar, att de omvände sig ifrå sinom onda väg, ångrade Gudi det onda, som han talat hade att han dem göra ville; och gjorde det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Det förtröt Jona ganska storliga, och vardt vred;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Och bad till Herran, och sade: Ack! Herre, det är det som jag sade, då jag ännu var i mitt land; derföre jag ock ville det förekomma, och fly till hafs; ty jag vet att du äst en nådelig Gud, barmhertig, långmodig, och af stor mildhet, och låter dig ångra det onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Så tag då nu mina själ ifrå mig, Herre; ty jag vill heldre vara död, än lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Men Herren sade: Menar du, att du skäliga vredgas?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Och Jona gick utu staden, och satte sig östan för staden, och gjorde sig der ena hyddo; der satte han sig neder i skuggan, tilldess han måtte se hvad stadenom vederfaras skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Men Herren Gud förskaffade en kurbits; den växte öfver Jona, att hon skulle skygga öfver hans hufvud, och vederqvicka honom i hans vedermödo; och Jona gladdes fast öfver den kurbitsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Men Gud förskaffade en matk om morgonen, då morgonrodnen uppgick; han åt kurbitsen, så att hon förtorkades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Men då solen uppgången var, förskaffade Gud ett torrt östanväder, och solen stack Jona uppå hufvudet, så att han vanmägtig vardt. Då önskade han sine själ döden, och sade: Jag ville heldre vara död, än lefvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Då sade Gud till Jona: Menar du, att du skäliga vredgas om kurbitsen? Och han sade: Jag må väl vredgas allt intill döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Och Herren sade: Du jämrar dig om kurbitsen, der du intet uppå arbetat hafver, och hafver ej heller låtit henne uppväxa, hvilken i ene natt vardt, och i ene natt förgicks;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Och jag skulle icke jämra mig öfver Nineve, en sådana stor stad, der mer uti är än hundradetusend och tjugutusend menniskor, som intet veta åtskilja mellan sina högra hand och den venstra; dertill ock mycken djur?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Detta är Herrans ord, som skedde till Micha af Maresa, uti Jothams, Ahas och Jehiskia, Juda Konungars, tid; det han såg öfver Samarien och Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Hörer, all folk; märk till, du land, och hvad deruti är; ty Herren Herren hafver att tala med eder; ja, Herren utu sitt helga tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Ty si, Herren skall utgå af sitt rum, och nederkomma, och gå uppå höjderna i landena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Så att bergen skola smälta under honom, och dalarna skola refna; såsom vax smälter för eldenom, såsom vatten som nederåt flyta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Allt detta för Jacobs öfverträdelses skull, och för Israels hus synders skull. Hvilken är då Jacobs öfverträdelse? Är det icke Samarien? Och hvilka äro Juda höjder? Är det icke Jerusalem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Och jag vill göra Samarien till en stenhop i markene, den man lägger omkring en vingård, och skall bortsläpa dess stenar uti dalen, och bryta det neder i grund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Alle dess afgudar skola sönderslagne varda, och all dess vinning med eld uppbränd varda, och skall jag utöda all dess beläte; ty de äro sammankomne af skökolön, och skola åter skökolön varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Der måste jag gråta öfver, och jämra mig; jag måste gå blott och naken; jag måste klaga såsom drakar, och sörja såsom strutser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Ty till dess plågo är intet råd, hvilken allt intill Juda kommen är, och skall räcka, allt intill mins folks port i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Förkunner det ju icke i Gath: låter icke höra, att I gråten; utan går in uti sörjokammaren, och sätter eder i asko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Du sköne stad måste omkull med all skam; den stolte varder intet mer prålandes för ångests skull; ty grannen skall taga ifrå honom hvad han hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Den ohörsamma staden hoppas, att det skall icke varda så ondt; men olyckan skall komma ifrå Herranom, och intill Jerusalems port.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Du stad Lachis, spänn trafvare före, och far dädan; ty du hafver varit dottrene Zion ett exempel till synd, och hållit Israels afguderi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Du måste gifva fångar, sil väl som Gath. Dem stadenom Achsib skall fela förbundet med Israels Konungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Jag skall föra dig, o Maresa, den rätta arfvingan; och det härliga Israels rike skall varda en kula.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Låt afskära håren, och gack kullot öfver din dägeliga barn; gör dig platt kullot, såsom en örn; ty de äro fångne ifrå dig bortförde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Ve dem som fara efter att göra skada, och hafva ondt för händer uti sina sänger, att de det om morgonen, då ljust varder, fullkomna skola; ty de äro herrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'De rifva åkrar till sig, och taga hus, hvilka de vilja; alltså bedrifva de våld med hvars och ens hus, och med hvars och ens arf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Derföre säger Herren alltså: Si, jag tänker något ondt öfver detta slägte, der I edran hals icke skolen undandraga, och icke gå så stolte; ty det skall vara en ond tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'På den tiden skall man sjunga ena viso om eder, och klaga: Det är ute: skall man säga: Vi äre förstörde; mins folks land tär en främmande herra. När skall han äter skifta oss åkrarna till, som han oss borttagit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Ja väl, I skolen ingen del behålla uti Herrans menighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'De säga: Man skall intet predika: ty sådana predikan kommer oss intet vid; vi varde intet så till skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Jacobs hus tröster sig alltså: Menar du, att Herrans Ande är så all borto? Skulle han detta vilja göra? Det är sant, mitt tal är ljufligit dem frommom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Men mitt folk skickar sig så, att jag deras fiende vara; måste; ty de röfva både kjortel och mantel af dem som säkre gå lika som uti ett örlig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'I drifven mins folks qvinnor ifrå sin lustiga hus, och borttagen allstädes min prydelse ifrå deras unga barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Derföre står upp, I måsten edar väg; I skolen här intet blifva. För deras afguderis skull måste de svårliga förderfvade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Fore jag med drafvel, och vore en lögnpredikare, och predikade huru de dricka och svälja skulle, det vore en Prophet för detta folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Men jag vill församla dig, Jacob, allan samman, och låta de qvarblefna i Israel tillhopakomma. Jag vill hafva dem tillhopa, såsom en hjord uti ett fårahus, och så som en hjord uti sina hyddo; så att det skall gny af menniskom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Hjelten skall för dem slå sig igenom; de skola slå sig igenom, och gå ut och in genom porten; och deras Konung skall gå för dem, och Herren främst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Och jag sade: Hörer dock, I höfvitsmän i Jacobs hus, och I Förstar i Israels hus; I skullen med rätto vara de som veta hvad rätt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Men I haten det goda, och älsken det onda; I skinnen dem hudena af, och köttet ifrå deras ben;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Och äten mins folks kött och när I hafven dragit dem hudena af, så slån I dem ock benen sönder, och stycken det ifrå hvartannat; lika som uti ena gry to, och lika som kött uti en kettil.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Derföre, när I nu till Herran ropande varden, så skall han intet vilja höra eder utan skall fördölja sitt ansigte för eder på den samma tiden, såsom I med edro onda väsende förtjent hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Detta säger Herren, emot de Propheter som förföra mitt folk: De predika, att det skall gå väl, när man gifver dem äta; men om man intet gifver dem i munnen, sa predika de, att ett örlig skall komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Derföre skall edor syn varda till en natt, och edar spådom till ett mörker; solen skall nedergå öfver Propheterna, och dagen öfver dem mörk varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Och Siarena skola till skam varda, och spåmännerna till spott; och måste allesamman skyla sig om munnen, efter der är intet Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Men jag är full med kraft och Herrans Anda; full med rätt och starkhet, att jag förkunna tör Jacob sin öfverträdelse, och Israel sina synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Så hörer dock detta, I höfvitsmän i Jacobs hus, och I Förstar i Israels hus, I som styggens vid rätten, och förvänden allt det redeligit är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'I som uppbyggen Zion med blod, och Jerusalem med orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Hans höfdingar döma för skänker, hans Prester lära för lön, och hans Propheter prophetera för penningar, förlåta sig uppå Herran, och säga: Är icke Herren ibland oss? Oss kan ingen olycka uppåkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Derföre skall Zion för edra skull upplöjd varda såsom en åkermark, och Jerusalem varda till en stenhop, och templets berg till en skogsbacka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Men i yttersta dagarna skall det berget, som Herrans hus uppå står, beredt varda, högre än all berg, och upphöjdt öfver högarna; och folk skola löpa dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Och månge Hedningar skola gå, och säga: Kommer, låter oss gå upp till Herrans berg, och till Jacobs Guds hus, att han lärer oss sina vägar, och vi mågom vandra på hans stigar; ty af Zion skall utgå lagen, och Herrans ord af Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Han skall döma ibland mycken folk, och straffa många Hedningar i fjerran land; de skola göra sin svärd till plogbillar, och sin spjut till liar. Intet folk skall upphäfva svärd emot det andra, och skola intet örlig mer föra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Hvar och en skall sitta under sitt vinträ och fikonaträ, utan fruktan; ty Herrans Zebaoths mun hafver det talat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Ty hvart och ett folk skall vandra uti sins guds namn; men vi skole vandra i Herrans vår Guds Namn, alltid och i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'På den tiden, säger Herren, vill jag församla den halta, och sammansamka den fördrefna, och den jag plågat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Och vill göra med den halta, att hon skall få arfvingar, och göra den svaga till stort folk. Och Herren skall vara Konung öfver dem på Zions berg, ifrå nu och i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Och du torn Eder, ett dottrenes Zions fäste, din gyldene ros skall komma, ditt förra herradöme, dottrenes Jerusalems rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Hvarföre håller du dig då intill andra vänner, lika som du icke skulle fä denna Konungen; eller lika som intet vorde af denna rådgifvarenom, efter värken är dig så uppåkommen, lika som ene i barnsnöd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Kära, lid dock sådana värk, och stanka, du dotter Zion, lika som en i barnsnöd: ty du måste visserliga utu staden, och bo på markene, och komma till Babel; men du skall åter dädan hulpen varda; der skall Herren förlossa dig ifrå dina fiendar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Ty månge Hedningar skola ju församla sig emot dig, och säga: Han är tillspillogjord; vi vilje se våra lust uppå Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Men de veta intet Herrans tankar, och märka intet hans rådslag, att han hafver hemtat dem tillhopa, såsom kärfvar uti ladona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Derföre statt upp, och tröska, du dotter Zion; ty jag vill göra dig jernhorn och kopparklor, och du skall sönderkrossa mycken folk; så skall jag tillspillogifva deras gods Herranom, och deras håfvor honom som råder öfver hela verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Men nu, du krigerska, rusta dig; ty man skall belägga oss, och slå Israels domare uppå kindbenet med ris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Och du BethLehem Ephrata, som liten äst ibland de tusende i Juda; utaf dig skall mig den komma som i Israel en Herre vara skall; hvilkens utgång varit hafver af begynnelsen, och af evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Han låter plåga dem, allt intill den tiden, att hon, som föda skall, födt hafver. Så skola då de hans igenlefde bröder igen, komma till Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Men han skall träda fram och regera uti Herrans kraft, och uti sins Herras Guds Namns härlighet, och de skola bo säkert; ty han skall på den samma tiden varda härlig, så vidt som verlden är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Dertill skole vi ock hafva frid för Assur, den nu uti värt land infallen är, och väl hus förtrampat hafver; ty sju herdar och åtta Förstar skola öfver honom uppväckte varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'De der Assurs land förderfva skola med svärd, och Nimrods land med deras bara vapen. Alltså skole vi ifrån Assur frälste varda, den uti vårt land infallen är, och våra gränsor förtrampat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Och skola de qvarlefde af Jacob vara ibland mång folk, lika som en dagg af Herranom, och såsom dropparna på gräset, det efter ingen bidar, eller efter menniskor väntar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Ja, de qvarlefde af Jacob skola vara ibland Hedningarna när mång folk, lika som ett lejon ibland djuren i skogenom, såsom ett ungt lejon ibland en fårahjord; den ingen afdrifva kan, när han drager derigenom, nedertrampar och rifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Ty dill hand skall behålla segren emot alla dina fiendar, att alle dine ovänner måste utrotade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'På den samma tiden, säger Herren, skall jag taga dina hästar ifrå dig, och förgöra dina vagnar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Och utrota dins lands städer, och bryta neder all din fäste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Och skall utrota de trollkarlar när dig, att inge tecknatydare när dig blifva skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Jag skall förgöra din beläte och afgudar ifrå dig, att du icke mer skall tillbedja dina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Och jag skall nederhugga dina lundar, och förlägga dina städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Och jag skall drifva hämnd med grymhet och vrede, på alle de Hedningar som icke böra vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Hörer dock hvad Herren säger: Statt upp, och straffa bergen, och låt högarna höra dina röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Hörer, I berg, huru Herren straffa vill, samt med de starka jordenes fundament; ty Herren vill straffa sitt folk, och vill näpsa Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Hvad hafver jag gjort dig, mitt folk, och hvarmed hafver jag betungat dig? Det säg mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Hafver jag dock fört dig utur Egypti land, och förlossat dig utu träldomshuset, och för dig sändt Mosen, Aaron och Miriam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mitt folk, tänk dock deruppå, hvad Balak, Konungen i Moab, i sinnet hade, och hvad Bileam, Beors son, svarade honom, allt ifrå Sittim och intill Gilgal, der I ju uppå märka skullen, att Herren hafver gjort eder allt godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Hvarmed skall jag blidka Herran? Med bugande för den höga Gudenom? Skall jag blidka honom med bränneoffer och årsgamla kalfvar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Menar du att Herren hafver behag till mäng tusend vädrar, eller till oljo, om än otaliga strömmar fulle voro? Eller skulle jag gifva min första son för min öfverträdelse; eller mins lifs frukt för mine själs synd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Det är dig sagt, menniska, hvad godt är, och hvad Herren af dig äskar, nämliga, att hålla Guds ord, och bruka kärlek, och vara ödmjuk för dinom Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Herrans röst skall ropa öfver staden men den ditt Namn fruktar, honom skall ske lycka. Hörer, I slägter, hvad predikadt varder:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Skulle jag icke vred varda öfver det orättfärdiga godset, uti dens ogudaktigas hus, och att man vederstyggeligen gör måttet för litet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Eller skulle jag gilla orätta våg, och falska vigt i säckenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Genom hvilka hans rike mycken orätt göra, och hans inbyggare bruka lögn, och hafva falska tungor i deras hals?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Derföre vill Jag ock begynna plåga dig, och göra dig öde för dina synders skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Du skall icke hafva nog till att äta, utan skall försmäkta; och hvad du fattar, det skall dock likväl intet undkomma, och hvad som undkommer, skall jag öfverantvarda svärdena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Du skall så, och intet uppskära: du skall oljo pressa, och intet smörja dig dermed, och must pressa, och intet vin dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Ty I hållen Omri gudstjenst, och all Achabs hus verk, och följen deras läro; derföre vill jag lägga dig öde, och dess inbyggare, så att man skall hvissla åt dem, och skolen till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Ack! det går mig lika som enom, den der efterhemtar i en vingård, der man inga vindrufvor finner till att äta, och ville dock gerna hafva den bästa fruktena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Gode män äro borto i desso lande och de rättfärdige äro intet mer ibland folket. De fara alle efter att utgjuta blod; hvar och en jagar den andra, att han skall förderfva honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Och mena, att de göra der väl utinnan, när de ondt göra. Hvad Försten vill, det säger domaren, på det han skall göm honom en tjenst igen. De väldige tala efter sin egen vilja, till att göra skada, och vrängat hvart de vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Den aldrabäste ibland dem är såsom törne, och den aldraredeligaste såsom tistel; men då dina predikares dag kommer, när du skall hemsökt varda, så skola de icke veta hvart de skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Ingen tro sinom nästa; ingen förlåte sig uppå Förstan. Förvara dins muns dörr för henne, som sofver på dinom arm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Ty sonen föraktar fadren; dottren sätter sig upp emot modrena; sonahustrun är emot sin sväro, och menniskones fiender äro hennes eget husfolk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Men jag vill se efter Herran, och vänta efter Gud, min Frälsare. Min Gud skall höra mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Fröjda dig intet, min fiendska, att jag nedre ligger; jag skall låter uppkomma; och om jag sitter i mörkret, så är dock Herren mitt ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Jag vill bära Herrans vrede, ty jag hafver syndat emot honom, tilldess han uträttar mina sak, och skaffar mig rätt. Han skall föra mig uti ljuset, så att jag skall se mina lust uppå hans nåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Min fiendska måste det se, och bestå med allo skam, den nu till mig säger: Hvar är Herren din Gud? Min ögon skola set att hon, såsom en träck på gatomen, förtrampad varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'På den tiden skola dille murar uppbyggde varda, och Guds ord vida utkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Och uti samma tidenom skola de af Assur, och de af de fasta städer komma till dig, ifrå de fasta städer allt intill flodena; ifrå det ena hafvet intill det andra, ifrå det ena berget intill det andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Ty landet skall öde varda för sina inbyggares skull, och för deras gerningars frukts skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Men regera du ditt folk med dinom staf, din arfvedels hjord, både de som bo uti skogenom allena, och på åkermarkene; lät dem födas i Hasan och Gilead, såsom af ålder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Jag skall låta dem se under, lika som på den tid då de drogo utur Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Att Hedningarna skola det se, och alle deras väldige skämma sig, och lägga handena på sin mun, och tillhålla sin öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'De skola sleka stoft såsom ormar, och darra såsom matkar på jordene uti sin hål; de skola frukta sig för Herranom vårom Gud, och förskräckas för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Ho är en sådana Gud, som du äst; den der synder förlåter, och tillgifver dinom igenlefda arfvedel deras misshandel? Den icke behåller sina vrede evinnerliga; ty han är barmhertig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Han skall ännu förbarma sig öfver oss, slå våra missgerningar neder, och kasta alla våra synder uti hafsens djup.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Du skall hålla Jacob trohet, och Abraham den nåd, som du våra fäder i förtiden svorit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Detta är tungen öfver Nineve, och Nahums Propheties bok af Elkos.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Gud är nitisk, och Herren är en hämnare; ja, en hämnare är Herren, och grym. Herren är en hämnare uppå sina fiendar, och den der sina ovänner intet förgäter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Herren är tålig, och af stora magt, och låter intet ostraffadt blifva. Han är Herren, hvilkens vägar äro uti väder och storm, och tjockt moln under hans fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Den som näpser hafvet, och förtorkar det, och uttorkar alla floder; Basan och Carmel försmäkta, och hvad som blomstras på Libanons berg, det måste försmäkta för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Bergen bäfva för honom, och högarna förgås; jorden darrar för honom; dertill jordenes krets, och alle de som bo der uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Ho kan blifva ståndandes för hans vrede? Och ho kan blifva för hans grymhet? Hans vrede brinner såsom en eld, och hällebergen remna för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Herren är mild, och ett fäste uti nödenes tid; och känner dem som trösta uppå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'När floden löper öfver, så gör han en ända med henne; men sina fiendar förföljer han med mörker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Hvad är då det, som I tagen eder före emot Herran? Han låter del dock intet af varda; ty bedröfvelsen skall icke vara evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Ty lika som när törne, de ännu om hvartannat växa, och bästa musten hafva, varda uppbränd såsom hel torr strå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Alltså varder det skalkarådet, som af dig kommer, ondt tänkandes emot Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Detta säger Herren: De komme så tillrustade och mägtige som de vilja, så skola de likväl omkullhuggne varda, och gå sin kos; ty jag vill ödmjuka dig, men dock icke platt förderfva dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Utan vill då kasta hans ok, som du drager, ifrå dig och slita din band sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Men emot dig hafver Herren budit, att ingen dins namns säd mer blifva skall. Uti dins guds huse vill jag förgöra dig; jag skall gifva dig ena graf ibland afgudar och beläte, och du måste till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Si, på bergen komma ens god bådskaps fötter, den der god tiden de bär: Håll dina högtider, Juda, och betala din löfte; ty skalken skall icke mer komma öfver dig; det är platt ute med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Förskingraren skall uppdraga emot dig, och belägga fästen; men se dig väl om på vägarna, rusta dig det bästa du kan, och stärk dig; det mesta du förmår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Man skall likväl platt afhemta dig, och förderfva dina vinqvistar; ty Herren skall gifva Jacob segren, lika som han Israel segren gaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Hans starkas sköldar äro röde; hans härfolk ser ut såsom purpur, hans vagnar lysa såsom en eld, när det drabba skall; deras spetser gå hvar om annan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Vagnarna rulla på gatomen, och bullra uppå vägomen; deras anseende är lika som bloss, och gå hvar om annan, lika som en ljungeld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Men han skall tänka uppå sina väldiga; dock skola de falla ehvartut de vilja, och skola hasta sig lit murarna, och till skärmen, der de må säkre blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Men de portar vid floderna varda dock upplåtne, och palatset skall nederslås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Drottningen skall fången bortförd varda, och hennes jungfrur skola sucka, lika som dufvor, och slå sig uppå sitt bröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Ty Nineve är lika som en dam full med vatten; men det måste förflyta. Står, står (skola de ropa); men der skall ingen vända om igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Så röfver nu silfver, röfver guld; ty här är en skatt, der ingen ände uppå är, och ganska mång kostelig klenodier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Men nu måste han platt afhemtad och utödd varda, att hans hjerta måste förtvifla, knän ostadig vara, alla länder darra, och alla kinder blekna, lika som en lerpotta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Hvar är nu de lejons boning, och de unga lejons vedemark, der lejonet och lejinnan med de unga lejon vistades, och ingen torde rädda dem bort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Utan lejonet röfvade nog för sina ungar, och drap åt sina lejinnor. Sina kulor uppfyllde han med rof, och sina boning med det han rifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Si, jag vill till dig, säger Herren Zebaoth, och upptända dina vagnar i rök, och svärdet skall uppfräta din unga lejon, och göra en ända på ditt röfveri på Jordene, att man dina bådskaps röst intet mer höra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Ve dem mordiska stadenom, den der full är med lögn och röfveri, och vill af sitt röfveri intet återvända;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Ty der skall man höra sveper smälla, och hjul bullra, hästar skria, och vagnar rulla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Han förer upp resenärar med blänkande svärd och glimmande glafven; der ligga månge slagne, och store hopar med kroppar, så att på dem intet tal är, och man öfver deras kroppar falla måste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Allt detta för den dägeliga och lustiga skökones stora boleris skull, hvilken trolldom brukar, och med sitt boleri hafver förvärft Hedningar, och med sin trolldom land och folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Si, jag vill till dig, säger Herren Zebaoth; jag skall uppkasta din klädefåll öfver ditt ansigte, och skall visa. Hedningomen din blotthet, och Konungariken dina skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Jag skall göra dig ganska styggelig, och skämma dig, och göra dig till en vederstyggelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Att alle de, som dig se, skola fly ifrå dig, och säga: Nineve är förderfvadt; ho vill ömka sig öfver dig, och hvar skall jag söka dig hugsvalare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Menar du, att du äst bättre, än den store staden No, som låg vid floderna, och hade vatten allt omkring sig; hvilkens murar och fäste var hafvet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Ethiopien och Egypten var hans otaliga magt; Put och Libya voro dine hjelpare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Likväl måste han fördrifven varda, och fången bortdraga, och hans barn äro på alla gator slagne, och om hans ädlingar kastade man lott, och alle hans väldige vordo satte i kedjor och bojor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Alltså måste du ock drucken varda, och bortgömma dig, och uppsöka ett fäste för fiendanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Alle dine faste städer äro lika som fikonaträ med mogen fikon; när man skakar dem, falla de honom i munnen, som dem äta vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Si, ditt folk skall i dig varda till qvinnor, och dins lands portar skola dinom fiendanom öppnade varda, och elden skall upptära dina bommar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Hemta dig vatten, ty du skall belagd varda; förbättra din fäste, gack uti leret och trampa det, och gör starkt tegel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Men elden skall upptära dig, och svärdet döda dig; det skall uppäta dig, lika som en flogmatk; det skall öfverfalla dig, lika som en flogmatk; det skall öfverfalla dig, såsom gräshoppor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Du hafver flera köpmän än stjernorna äro på himmelen; men nu skola de utsprida sig, lika som flogmatk, och flyga bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Dine herrar äro så månge som gräshoppor, och dine höfvitsmän lika som flogmatkar, hvilke sig lägra uppå gårdar i de kalla dagar; men när solen uppgår, så draga de dädan, att man icke vet hvar de blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Dine herdar skola sofva, o Konung i Assur; dine mägtige skola lägga sig, och ditt folk skall uppå bergen förströdt varda, och ingen skall församla dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Ingen skall begråta din skada, eller bekymra sig om dina plågo, utan alle de, som detta om dig höra, skola klappa med sina händer öfver dig; ty öfver hvem är din ondska utan återvändo icke gången?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Detta är den tunge, som Propheten Habacuc sett hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Herre, huru länge skall jag ropa, och du vill icke höra? Huru länge skall jag ropa till dig för öfvervålds skull, och du vill icke hjelpa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Hvi låter du mig se mödo och arbete? Hvi hafver du låtit mig se rof och öfvervåld? Våld går öfver rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Derföre måste lagen blifva tillbaka, och ingen rätt kan till ända komma; ty den ogudaktige öfverfaller den rättfärdiga, derföre gå vrånga domar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Ser ibland Hedningarna; ser till, och förundrer eder ty jag vill något göra i edrom tid, det i icke tro skolen, då man derom talar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Ty si, jag vill uppväcka de Chaldeer, ett bittert och snart folk, hvilket draga skall så vidt som landet är, till att intaga de boningar som icke äro deras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Och skall vara grufveligit och förfärligit; och skall bjuda och tvinga såsom det vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Deras hästar äro raskare än parder, så äro de ock ilsknare än ulfvar om aftonen; hans resenärer draga med storom hopom fjerranefter, lika som de flögo, såsom örnar hasta sig till ett as.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'De komma allesamman till att göra skada ehvart de vilja; der gå de igenom, lika som ett östan väder, och samka fångar tillhopa, såsom sand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'De skola bespotta Konungar, och begabba Förstar; all fäste skola vara dem ett skämt; ty de skola göra der blåverk före, och vinna dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Då skola de taga sig ett nytt mod, fara framåt och synda; och så måste då deras seger höra deras gud till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Men du Herre, min Gud, min Helige, du som äst af evighet, låt oss icke dö; utan låt dem, Herre, allenast vara oss till ett straff; och låt dem, o vår tröst, allenast tukta oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Din ögon äro ren, så att du icke orkar se det onda, och kan icke se uppå jämmer. Hvi ser du då på de öfverträdare, och tiger, att den ogudaktige uppslukar den, som frommare är än han?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Och låter menniskorna gå, lika som fiskar i hafvet; såsom matkar, de ingen herm hafva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'De dragat allt med krok, och fuskar med sin nät, och församlat med sin garn; dess fröjda de sig, och äro glade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Derföre offra de sinom nätom, och röka sinom garnom; efter det deras del är derigenom så fet, och deras mat så kräselig vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Derföre kasta de sin nät ännu alltid ut, och vilja icke återvända att dräpa folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Här står jag på mine vakt, och stiger på mitt fäste, och skådar och ser till hvad mig sagdt varder, och hvad jag svara skall honom, som mig straffar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Men Herren svarar mig, och säger: Skrif synena, och måla henne uppå en taflo, att den der framom går, må det läsa (nämliga alltså):');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Prophetian skall ju ännu fullkomnad varda i sinom tid, och skall på ändalyktene fri i ljuset komma, och icke fela; men om hon fördröjer, så förbida henne; hon kommer visserliga, och skall icke fördröja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Hvilken deremot sträfvar, hans själ skall icke gå väl; ty den rättfärdige lefver af sine tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Men vin bedrager den stolta mannen, att han icke blifva kan; hvilken utvidgar sina själ såsom helvetet, och är lika som döden, den intet mättas kan; utan samkar till sig alla Hedningar, och församlar till sig all folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Hvad gäller? Desse allesamman skola göra ett ordspråk om honom, och ena sago och gåto, och säga: Ve den som sitt gods förmerar med annars mans gods (huru länge vill det vara?); och laddar mycken träck uppå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'O! huru hastigt skola de uppstå som dig bita, och uppvaka de som dig bortdrifva, och du måste varda dem till byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Ty du hafver många Hedningar beröfvat; Så skola alla igenlefde af folken beröfva dig igen; för menniskors blods skull, och för den orätts skull, som i landena, och i stadenom, och uppå alla som deruti bo, bedrifven är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Ve den som girig är till sins hus värsta, på det han skall hafva sitt näste uppe i höjdene, att han skall undfly olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Men ditt rådslag skall komma dino huse till skam; ty du hafver allt för mycket folk slagit, och syndat öfverdådeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Ty stenarna i murenom skola ropa och bjelkarna i tråssningene skola svara dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Ve den som bygger staden med blod, och tillreder staden med orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Månn det icke ske af Herranom Zebaoth? Hvad folken dig arbetat hafva, det måste uppbrännas i eld, och der menniskorna trötte uppå vordne äro, det måste förtappadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Ty jorden skall tull varda af Herrans äros kunskap, lika som vattnet, som öfvertäcker hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Ve dig, som skänker uti för din nästa, och blandar din galla deruti, och gör en drucknan, på det du skall se hans blygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Man skall ock mätta dig med skam för äro. Så drick du ock nu, att du må omkull ligga; ty kalken i Herrans högra hand skall omfatta dig, och du måste skamliga spy för dina härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Ty den orätt, uppå Libanon bedrifven, skall öfverfalla dig, och de förstörda djur skola förskräcka dig; för menniskors blods skull, och för den orätts skull, som i landena och i stadenom, och uppå alla de deruti bo, bedrifven är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Hvad kan då belätet hjelpa, det dess mästare gjort hafver, och det falska gjutna belätet, der dess mästare förlät sig uppå, att han stumma afgudar gjorde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Ve honom, som säger till en stock: Vaka upp; och till stumma stenen: Statt upp. Huru skulle det kunna någon lära? Si, det är öfverdraget med guld och silfver, och der är ingen ande uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Men Herren är i sitt helga tempel. Hela verlden vare tyst för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Detta är Propheten Habacucs bön för de oskyldiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Herre, jag hafver hört ditt rykte, så att jag förskräcktes. Herre, du gör ditt verk lefvande midt i åren, och låter det kunnigt varda midt i åren. När bedröfvelse på färde är, så tänker du uppå barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Gud kom sunnanefter, och den Helge ifrå det berget Paran. Sela. Af hans lof var himmelen full, och af hans äro var jorden full.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Hans sken var såsom ett ljus, strimmor gingo af hans händer; der var hans magt hemliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'För honom gick pestilentie, och plåga gick ut, ehvart han gick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Han stod, och mälte landet; han såg till, och förskingrade Hedningarna, så att verldenes berg förkrossad vordo, och sig bocka måste alle högar i verldene, då han gick uti verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Jag såg de Ethiopers hyddor i vedermödo, och de Midianiters tjäll bedröfvad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Vast du icke, Herre, vred i flodene; och din grymhet i vattnom, och din ogunst i hafvena? då du redst på dina hästar, och dine vagnar hehöllo segren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Du drog fram bågan, såsom du slägterna svorit hade; Sela; och delade strömmarna i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Bergen sågo dig, och vordo bedröfvad; vattuströmmen gick sin kos, djupet lät höra sig, höjden hof sina händer upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Sol och måne stodo stilla. Dine pilar foro bortåt med ett sken, och din glafven med ljungelds blänkande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Du nedertrampade landet i vrede, och söndertröskade Hedningarna i grymhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Du drog ut till att hjelpa dino folke, till att hjelpa dinom smorda; du sönderslogst hufvudet uti dens ogudaktigas huse, och blottade grunden allt intill halsen; Sela.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'O! att du ville banna hufvudens spiror, samt med dess byar, hvilke, såsom ett väder, komma till att förströ mig, och glädja sig, lika som de uppslukte de elända hemliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Dine hästar gå i hafvena, uti stor vattens träck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Efter jag sådant hörer, så är min buk bedröfvad; mine läppar darra af rop var går i minom ben om; jag är bedröfvad vid mig. Ack! att jag hvila måtte i bedröfvelsens tid, då vi uppdrage till det folk, som emot oss strider.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Ty fikonaträt skall icke grönskas, och der skall ingen frukt vara på vinträn; arbetet uppå oljoträt felar, och åkrarna bära ingen födo; och fåren skola ryckas utu fårahusen, och intet fä skall vara uti fähusen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Men jag vill glädja mig af Herranom, och glad vara i Gudi, minom Frälsare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Ty Herren Herren är min kraft, och han skall göra mina fötter lika som hjortafötter; och skall föra mig upp i höjdena, så att jag sjunger på min strängaspel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Detta är Herrans ord, som skedde till Zephania, Chusi son, Gedalja sons, Amarja sons, Hiskia sons, uti Josia tid, Amons sons, Juda Konungs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Jag skall taga bort all ting utu landena, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Jag skall borttaga både folk och fä, både himmelens foglar, och fiskarna i hafvet, samt med afgudarna och de ogudaktiga; ja, jag skall utrota menniskorna af landena, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Jag skall uträcka mina hand öfver Juda, och öfver alla de som i Jerusalem bo; alltså skall jag borttaga det qvart är af Baal, dertill de namn, Munkar och Prester, utu desso rumme;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Och de som på taken tillbedja himmelens här; de som honom tillbedja, och svärja dock vid Herran, och vid Malcham derjemte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Och de som affalla ifrå Herranom, och intet fråga efter Herran, och intet akta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Varer tyste för Herranom Herranom; ty Herrans dag är för handene; ty Herren hafver tillredt ett slagtoffer, och budit der sina gäster till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Och på Herrans slagtoffers dag skall jag hemsöka Förstarna och Konungsbarnen, och alla de som bära en främmande kyrkoskrud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Och skall jag den tiden hemsöka dem som öfver tröskelen springa; de deras herrars hus uppfylla med rot och bedrägeri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'På den tiden, säger Herren, skall upphäfva sig ett högt rop ifrå fiskaportenom, och en gråt ifrå dem andra portenom, och en stor jämmer på högomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Jämrer eder, I som bon i qvarnene; ty hela krämarefolket är borto, och alle de som penningar församla, äro förgångne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'På den tiden skall jag utransaka Jerusalem med lyktor, och skall hemsöka dem som ligga på sine drägg, och säga i sitt hjerta: Herren varder hvarken godt eller ondt görandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Och deras ägodelar skola till rofs varda, och deras hus till ett öde; de skola bygga hus, och intet bo deruti; de skola plantera vingårdar, och intet vin dricka deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Ty Herrans store dag är hardt för handene; han är hardt när, och hastar sig svårliga. När det ropet om Herrans dag kommandes varder, så skolade starke ropa bitterliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ty denne dagen är en grymhets dag, en bedröfvelses och ångests dag en väders och storms dag, en mörkers, och dimbos dag, en molns och töcknes dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'En basuns och trummetes dag, emot de fasta städer och höga borger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Jag skall göra menniskomen bekymmer, så att de skola gå omkring såsom de blinde; derföre, att de emot Herran syndat hafva; deras blod skall utgjutet varda, lika som det stoft vore, och deras kroppar såsom träck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Deras silfver och guld skall intet kunna hjelpa dem på Herrans vredes dag; utan hela landet skall genom hans nits eld förtärdt varda; ty han skall snarliga en ända göra med alla de som bo i landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Församler eder, och kommer hit, I obehageliga folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Förr än domen utgår, så att I om dagen bortryken såsom ett stoft, förr än Herrans grymma vrede öfver eder kommer, förr än Herrans vredes dag öfver eder kommer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Söker Herran, alle I elände i landena, I som hans rätter hållen; söker rättfärdighetena, söker ödmjukhetena; på det att I på Herrans vredes dag mågen beskyddade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Ty Gaza måste öfvergifven varda, och Askelon förödd; Asdod skall om middagen förjagad varda, och Ekron utrotad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Ve dem som bo nedre vid hafvet, de krigare. Herrans ord skall komma öfver eder. Du Canaan, de Philisteers land, jag skall förgöra dig, så att der ingen mer bo skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Der skola nedre vid hafvet vara alltsammans herdahus, och fårahus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Och det samma skall varda dem qvarlefdom af Juda hus till del, att de deruppå beta skola. Om aftonen skola de lägra sig uti Askelons husom, då nu Herren deras Gud dem återsökt, och deras fängelse vänd hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Jag hafver hört Moabs hädelse, och Ammons barnas försmädelse, der de med hafva försmädat mitt folk, och berömt sig öfver deras gränsor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Nu väl, så sant som jag lefver, säger Herren Zebaoth, Israels Gud: Moab skall varda lika som Sodom, och Ammons barn lika som Gomorra; ja, lika som en nässlebuske, och en saltgrufva, och ett evigt öde; de qvarlefde af mitt folk skola beröfva dem, och de öfverblefne af mitt folk skola ärfva dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Det skall vederfaras dem för deras högfärd, att de hafva försmädat Herrans Zebaoths folk, och berömt sig öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Förskräckelig skall Herren vara öfver dem; ty han skall förlägga alla gudar på jordene; och alla öar ibland Hedningarna skola tillbedja honom, hvar och en i sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Ock skolen I Ethiopier genom mitt svärd slagne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Och han skall sträcka sina hand norrut, och förgöra Assur; han skall göra Nineve öde, torrt, såsom en öken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Så att sig deruti lägra skola allahanda djur ibland Hedningarna; och rördrommar och ufvar skola bo på deras torn, och skola sjunga i vigskården, och korpar på bjelkomen; ty cedrebräden skola afrifne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Denne är den lustige staden, den så säker bodde, och sade i sitt hjerta: Jag äret, och ingen annan. Huru är han så öde vorden, så att djuren bo derinne; och hvilken som der framom går, han hvisslar till honom, och slår med handene öfver honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Ve dem styggeliga, slemma, och tyranniska stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Han vill intet höra, eller låta sig tukta; han vill icke trösta uppå Herran, eller hålla sig till sin Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Hans Förstar äro derinne rytande lejon, och hans domare ulfvar om aftonen, hvilka intet låta qvart blifva intill morgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Hans Propheter äro lösaktige och föraktare; hans Prester oskära helgedomen, och bedrifva våld under lagsens sken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Men Herren, som ibland dem är, lärer väl rätt, och gör intet ondt; han låter hvar morgon uppenbarliga lära sina rätter, och håller intet upp; men de onde vilja intet; lära skämmas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Derföre vill jag utrota detta folket, föröda deras borger, och göra deras gator så tomma, att ingen derpå gå skall. Deras städer skola förstörde varda, så att der ingen mer bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Jag lät säga dig: Mig skall du frukta och låta tukta dig, så vorde hans boning icke utrotad, och intet deraf komme, der jag honom med hemsöka skall; men de voro oförsumlige till att göra allahanda ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Derföre, säger Herren, måsten I ock bida mig, tilldess jag uppstår i sinom tid; då jag ock döma skall och församla Hedningarna, och låta Konungariken tillhopakomma, till att gjuta mina vrede öfver dem; ja, alla mina grymhets vrede; ty hela verlden skall igenom mins nits eld förtärd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Då vill jag annorlunda låta predika till folken mod vänliga läppar, att de allesamman skola åkalla Herrans Namn, och tjena honom endrägteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Man skall hafva mina tillbedjare, de förströdda på hinsidon flodena i Ethiopien, till mig, för en skänk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'På den samma tiden skall du intet mer skämmas öfver allt ditt väsende, der du med emot mig syndat hafver; ty jag vill taga de stolta helgon ifrå dig, att du icke mer skall upphäfva dig för mitt helga bergs skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Jag skall låta öfverblifva i dig ett fattigt, ringa folk; de skola trösta uppå Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'De qvarblefne i Israel skola intet ondt göra, eller lögn tala; och man skall icke finna någon bedrägelig tungo i deras mun; utan de skola födas och ro hafva, utan all fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Fröjda dig, du dotter Zion; ropa, Israel; var glad och fröjda dig af allo hjerta du dotter Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Ty Herren hafver borttagit ditt straff, I och afvändt dina fiendar. Herren, Israels Konung, är när dig, att du intet mer behöfver frukta dig för någon olycko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'På den samma tiden skall man säga till Jerusalem: Frukta dig intet; och till Zion: Låt dina händer icke nederfalla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Ty Herren, din Gud, är när dig, en stark Frälsare. Han skall fröjda sig öfver dig, och vara dig vänlig, förlåta dig det, och skall glädjas öfver dig med höga röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'De, som igenom menniskors stadgar plågade voro, vill jag bortskaffa, att de skola ifrå dig komma, hvilke stadgar din tunge voro, för hvilka du skyllad var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Si, jag skall på den tiden göra en ända uppå alla dem som dig ondt göra; och skall hjelpa den halta, och församla den fördrefna; och skall sätta dem till lof och äro i all land, der man dem föraktar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'På den tiden skall jag låta komma eder härin, och på den samma tiden församla eder; ty jag skall sätta eder till lof och äro, ibland all folk på jordene; då jag edart fängelse omvändandes varder, för edra ögon, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Uti andra årena Konungs Darios, uti sjette månadenom, på första dagen i månadenom, skedde Herrans ord, genom den Propheten Haggai, till Serubbabel, Sealthiels son, Juda Första, och till Jehosua, Jozadaks son, den öfversta Presten, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Så säger Herren Zebaoth: Detta folket säger: Tiden är ännu icke kommen, att man Herrans hus bygga skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Och Herrans ord skedde genom den Propheten Haggai sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Månn då edar tid vara kommen, att I bo skolen uti hvälfdom husom, och detta huset måste öde stå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Nu, så säger Herren Zebaoth: Ser, huru det går eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'I sån mycket, och fören litet in; I äten, och varden dock icke mätte; I dricken, och varden dock intet otörstige; I kläden eder, och kunnen dock intet värma eder; och den der penningar förtjenar, han lägger dem uti hålogan pung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Så säger Herren Zebaoth: Ser, huru det går eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Går upp på berget, och hemter trä, och bygger huset; det skall vara mig tacknämligt och jag skall bevisa mina äro, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Ty I vänten väl efter mycket, och si, det varder litet; och om I än fören det hem, så blås jag dock det bort. Hvi så? säger Herren Zebaoth. Derföre, att mitt hus så öde står, och hvar och en hastar med sino huse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Derföre hafver himmelen förhållit daggena öfver eder, och jorden sina frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Och jag hafver kallat torko, både öfver land och berg, öfver korn, vin, oljo, och öfver allt det utaf jordene kommer; och öfver folk och fä, och öfver allt händers arbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Då hörde Serubbabel, Sealthiels son, och Jehosua, Jozadaks son, den öfverste Presten, och alle öfverblefne af folket, sådana Herrans, deras Guds, röst, och Prophetens Haggai ord; såsom Herren, deras Gud, honom sändt hade; och folket fruktade sig för Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Då sade Haggai, Herrans Ängel, som Herrans bådskap hade till folket: Jag är med eder, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Och Herren uppväckte Serubbabels anda, Sealthiels sons, Juda Förstas, och Jehosua anda, Jozadaks sons, dens öfversta Prestens, och allt igenlefda folkens anda; så att de kommo, och arbetade uppå Herrans Zebaoths, deras Guds, hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'På fjerde och tjugonde dagen i sjette månadenom, uti andro årena Konungs Darios;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'På första och tjugonde dagen i sjunde månadenom, skedde Herrans ord genom den Propheten Haggai, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Tala till Serubbabel, Sealthiels son, Juda Första, och till Jehosua, Jehozadaks son, den öfversta Presten, och till det igenlefda folket, och säg:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Hvilken är ibland eder igenlefd, som detta hus i dess förra härlighet sett hafver? Och huru synes eder nu derom? Är det icke så, att det tycker eder intet vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Och nu, Serubbabel, haf ett godt mod, säger Herren; haf ett godt mod, du Jehosua, Jehozadaks son, öfverste Prest; hafver ett godt mod, allt folk i landena, säger Herren, och arbeter: ty jag är med eder, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Efter det ordet, då jag ett förbund med eder gjorde, när I utur Egypten drogen, skall min Ande blifva när eder. Frukter eder intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Ty så säger Herren Zebaoth: Det är ännu en liten tid, att jag skall röra himmel och jord, hafvet och det torra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Ja, alla Hedningar skall jag röra; så skall då komma alla Hedningars tröst; och jag vill göra detta hus fullt med härlighet, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Ty mitt är både silfver och guld, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Detta sista husets härlighet skall större varda, än dess förstas varit hafver, säger Herren Zebaoth; och jag skall frid gifva i desso rummena, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'På fjerde och tjugonde dagen i nionde månadenom, uti andro årena Darios, skedde Herrans ord till den Propheten Haggai, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Detta säger Herren Zebaoth: Fråga Presterna om lagen, och säg:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Om någor båre heligt kött uti sins klädes sköt, och komme sedan med sitt klädesköt vid bröd, mos, vin, oljo eller hvad det för spis vara kunde; vorde det ock heligt? Och Presterna svarade, och sade: Nej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Haggai sade: Om nu en, som af ett vederkommet as oren är, komme vid något af dessa tingen, vorde det ock orent? Presterna svarade, och sade: Det vorde orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Då svarade Haggai, och sade: Alltså är ock detta folket, och dessa menniskor, för mig, säger Herren; och allt deras händers verk, och hvad de offra, det är orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Och nu, ser huru det eder gånget är, ifrå denna dagen och tillförene, förra än en sten på den andra lagd vardt af Herrans tempel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Att när en kom till kornhopen, som skulle hålla tjugo mått, så voro der som nogast tio; kom han till pressen, och mente uppfylla femtio åm, så voro der som nogast tjugu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Ty jag plågade eder med torko, brandkorn och hagel, uti allo edro arbete. Likväl omvänden I eder intet till mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Så ser nu deruppå ifrå denna dag, och tillförene, nämliga ifrå fjerde och tjugonde dagen i nionde månadenom, allt intill den dagen då Herrans tempel grundadt vardt, ser deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Ty säden ligger ännu i lårarna, och ingen ting bär ännu något, hvarken vinträ fikonaträ, granatträ, eller oljoträ; men ifrå denna dag vill jag gifva välsignelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Och Herrans ord skedde annan gången till Haggai, på fjerde och tjugonde dagen i månadenom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Tala till Serubbabel, Juda Första, och säg: Jag skall röra himmel och jord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Och skall omstörta rikens säten, och förgöra de mägtiga Hedningarnas rike, och skall omstörta både vagn och resenär; så att både häst och man skola nederfalla, hvar och en genom den andras svärd. På den samma tiden, säger Herren Zebaoth, skall jag taga dig, Serubbabel, Sealthiels son, min tjenare, säger Herren, och vill hålla dig såsom en signetsring; ty jag hafver utvalt dig, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Uti åttonde månadenom, i andro årena (Konungs) Darios, skedde detta Herrans ord till ZacharIa, Berechia son, Iddo sons, den Propheten, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Herren hafver vred varit uppå edra fäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Och säg; till dem: Detta säger Herren Zebaoth: Vänder eder till mig, säger Herren Zebaoth; så vill jag vända mig till eder, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Varer icke såsom edra fäder, hvilkom de förre Propheter predikade, och sade: så säger Herren Zebaoth: Vänder eder ifrån edra onda vägar, och ifrån edart onda väsende; men de hörde intet, och skötte intet om mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Hvar äro nu edre fäder och Propheter? Lefva de ock ännu?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Hafva min ord och mina rätter, som jag böd, genom mina tjenare Propheterna, icke kommit intill edra fäder? att de hafva måst vända sig om, och säga: Lika som Herren Zebaoth i sinnet hade att göra emot oss, efter som vi gingom och gjordom; alltså hafver han ock gjort emot oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'På fjerde och tjugonde dagen i ellofte månadenom, som är den månaden Sebat, uti andro årena (Konungs) Darios, skedde detta Herrans ord till ZacharIa, Berechia son, Iddo sons, den Propheten, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Jag såg om nattena, och si, en man satt på enom rödom häst, och han höll ibland myrtenträ i dalenom; och bakför honom voro röde, brune och hvite hästar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Och jag sade: Min herre, ho äro desse? Och Ängelen, som med mig talade, sade till mig: Jag vill kungöra dig, ho desse äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Och mannen, som höll ibland myrtenträn, svarade, och sade: Desse äro de som Herren utsändt hafver till att draga genom landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Men de svarade Herrans Ängel, som ibland myrtenträn höll, och sade: Vi hafve dragit igenom landet; och si, all land sitta stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Då svarade Herrans Ängel, och sade: Herre Zebaoth, huru länge vill du då icke förbarma dig öfver Jerusalem, och öfver Juda städer, uppå hvilka du hafver vred varit i dessa sjutio år?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Och Herren svarade Änglenom, som med mig talade, vänlig ord, och tröstelig ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Och Ängelen, som med mig talade, sade till mig: Predika, och säg: Detta säger Herren Zebaoth: Jag hafver stort nit haft öfver Jerusalem och Zion.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Men jag är ganska vred uppå de stolta Hedningar; ty jag var icke utan litet vred, men de hulpo till förderf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Derföre så säger Herren: Jag vill åter vända mig till Jerusalem med barmhertighet; och mitt hus skall deruti uppbygdt varda, säger Herren Zebaoth; dertill skall timbersnöret i Jerusalem draget varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Och predika ytterligare, och säg: Detta säger Herren Zebaoth: Mina städer skall åter gå väl, och Herren skall åter trösta Zion, och skall åter utvälja Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Och jag hof upp min ögon, och såg; och si der voro fyra horn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Och jag sade till Ängelen, som med mig talade: Ho äro dessa? Han sade till mig: Desse äro de hornen, som Juda, Israel och Jerusalem förskingrat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Och Herren viste mig fyra smeder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Då sade jag: Hvad vilja dessa göra? Han sade: De hornen, som Juda så förskingrat hafva, att ingen hafver kunnat upplyfta sitt hufvud; till att afskräcka dem äro desse komne, på det de skola afstöta Hedningarnas horn; hvilke hornet upphäfvit hafva öfver Juda land, till att förskingra det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Och jag hof min ögon upp, och si, en man hade ett mätesnöre i handene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Och jag sade: Hvart går du? Men han sade till mig: Till att mäta Jerusalem, och se huru bredt och långt det vara skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Och si, Ängelen, som med mig talade, gick ut; och en annar Ängel gick ut emot honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Och sade till honom: Löp bort, och tala till den unga mannen, och säg: Jerusalem skall besuttet varda utan murar, för mycket folks och fäs skull, som derinne vara skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Och jag vill, säger Herren, vara en eldsmur deromkring; och skall vara der inne, och bevisa mig härliga derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'O, o, flyr utu nordlandet, säger Herren; ty jag hafver förstrött eder uti fyra väder under himmelen, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'O, Zion, du som bor när dottrene Babel, fly.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Ty så säger Herren Zebaoth: Han hafve sändt mig till Hedningarna, som eder beröfvat hafva; deras magt hafver en ända i den eder rörer, han rörer hans ögnasten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Ty si, jag vill upphäfva mina hand öfver dem, att de skola varda dem ett rof, som dem tjent hafva; att I skolen förnimma att Herren Zebaoth mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Fröjda dig, och var glad, du dotter Zion; ty si, jag kommer, och vill bo när dig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Och på den tiden skola månge Hedningar gifva sig intill Herran, och skola vara mitt folk; och jag skall bo när dig, att du skall förnimma, att Herren Zebaoth mig till dig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Och Herren skall ärfva Juda för sin del, uti de helga landena; och skall åter utvälja Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Allt kött vare stilla för Herranom; ty han är uppstånden ifrå sitt helga rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Och mig vardt vist den öfverste Presten Jehosua; ståndandes för Herrans Ängel; och Satan stod på hans högra hand, på det han skulle stå honom emot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Och Herren sade till Satan: Herren näpse dig, Satan; ja, Herren näpse dig, den Jerusalem utvalt hafver. Är icke detta en brand som utur eldenom uthulpen är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Och Jehosua hade oren kläder uppå, och stod för Änglenom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Hvilken svarade, och sade till dem som för honom stodo: Tager de orena kläden utaf honom. Och han sade till honom: Si, jag hafver tagit dina synder ifrå dig, och hafver klädt dig uti högtidskläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Och jag sade: Sätter en ren hatt uppå hans hufvud. Och de satte en ren hatt uppå hans hufvud, och drogo kläder uppå honom; och Herrans Ängel stod der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Och Herrans Ängel betygade Jehosua, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Detta säger Herren Zebaoth: Om du vandrar på minom vägom, och håller mina vakt, så skall du regera mitt hus, och bevara mina gårdar; och jag skall få dig några af dem som här stå, som dine ledsagare vara skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Hör till, Jehosua, öfverste Prest, du och dine vänner, som för dig bo; ty de äro undersmän; ty si, jag vill låta komma min tjenare Zemah.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Ty si, uppå den ena stenen som jag för Jehosua lagt hafver, skola sju ögon vara; men si, jag skall uthugga honom, säger Herren Zebaoth; och skall borttaga dess lands synder på enom dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'På den samma tiden, säger Herren Zebaoth skall hvar bjuda den andra under vinträ, och under fikonaträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Och Ängelen, som med mig talade, kom igen, och väckte mig, lika som en af sömn uppväckt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Och han sade till mig: Hvad ser du? Men jag sade: Jag ser, och si, der stod en ljusastake, allersamman af guld, med en skål ofvanuppå, der sju lampor på voro, och ju sju slefvar vid ena lampo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Och tu oljoträ dernär; ett på högra sidona vid skålena, den andra på den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Och jag svarade, och sade till Ängelen, som med mig talade: Min Herre, hvad är detta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Och Ängelen, som med mig talade, svarade, och sade till mig: Vetst du icke hvad detta är? Jag sade: Nej, min Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Och han svarade, och sade till mig: Det är Herrans ord om Serubbabel: Det skall icke ske igenom någon här, eller magt; utan igenom min Anda, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Ho äst du, stora berg, som dock for Serubbabel en slättmark varda måste? Och han skall lägga den första stenen, så att man ropa skall: Till lycko, till lycko!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Serubbabels händer hafva grundat detta huset, hans händer skola ock fullkomnat; på det I förnimma skolen, att Herren Zebaoth mig till eder sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Ty ho är den, som dessa ringa dagar föraktar; i hvilkom man dock skall glädja sig, och se murlodet uti Serubbabels hand, med de sju, som Herrans ögon äro, de der öfver hela landet löpa?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Och jag svarade, och sade till honom: Hvad äro dessa tu oljoträn, på högra och venstra sidone vid ljusastakan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Och jag svarade annan gång, och sade till honom: Hvad äro de två grenarna af oljoträn, som stå vid de två gyldene ljusa näporna, der man med af tager?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Och han sade till mig: Vetst du icke hvad de äro? Jag sade: Nej, min Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Och han sade: Det äro de tu oljobarn, som stå när honom, som råder öfver allt landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Och jag lyfte åter min ögon upp, och säg; och si, der var ett flygande bref.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Och han sade till mig: Hvad ser du? Och jag sade: Jag ser ett flygande bref, det är tjugu alnar långt, och tio alnar bredt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Och han sade till mig: Det är den förbannelsen, som utgår öfver hela landet; ty allo tjufvar varda efter detta bref fromme dömde, och alle menedare varda efter detta, bref fromme dömde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Men jag vill hafvat fram, säger Herren Zebaoth, att det skall komma tjufvomen hem, och dem som falskeliga svärja vid mitt Namn; och skall blifva uti deras hus, och skall upptära det, med dess trä och stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Och Ängelen, som med mig talade, gick ut, och sade till mig: Lyft din ögon upp, och se, hvad går derut?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Och sade: Hvad är det? Men han sade: En skäppa går derut; och sade: Det är deras anseende i allo landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Och si, der for en centener bly, och der var en qvinna, hvilken i skäppone satt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Men han sade: Det är afguderit; och han kastade henne uti skäppona, och hof den blyklimpen der ofvanuppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Och jag lyfte min ögon upp, och såg; och si, två qvinnor gingo ut, och hade vingar, de der drefvos af vädret; och det voro vingar, lika som storkars vingar; och de förde skäppona mellan jorden och himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Och jag sade till Ängelen, som med mig talade: Hvart föra de skäppona?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Men han sade till mig: Att henne skall ett hus bygdt och tillredt varda uti Sinears land och der satt varda på sin botten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Och jag lyfte åter min ögon upp, och såg; och si, der voro fyra vagnar, som gingo ut emellan tu berg; och bergen voro af koppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'För första vagnen voro röde hästar; för den andra vagnen voro svarte hästar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'För den tredje vagnen voro hvite hästar; för den fjerde vagnen voro brokote, starke hästar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Och jag svarade, och sade till Ängelen, som med mig talade: Min Herre, ho äro desse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Ängelen svarade, och sade till mig: Det äro de fyra väder under himmelen, som utgå, att de framträda skola för honom, som råder öfver all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Der de svarte hästarna före voro, de gingo norråt, och de hvite gingo efter dem; men de brokote gingo söderåt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'De starke gingo, och drogo omkring, så att de foro igenom all land; och han sade: Går åstad, och drager igenom landet. Och de drogo igenom landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Och han kallade mig, och talade med mig, och sade: Si, de som norråt draga, de låta min Anda hvilas i nordlandena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Tag af fångomen, nämliga af Heldai och af Tobia, och af Jedaja; och kom du, på den samma dagen, och gack in uti Josia, Zephania sons hus, hvilke af Babel komne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Men tag silfver och guld, och gör (två) kronor, och sätt dem uppå Josua, dens öfversta Prestens, hufvud, Jozadaks sons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Och säg till honom: Detta säger Herren Zebaoth: Si, der är en man, som heter Zemah; under honom skall det gro, och han skall bygga Herrans tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Ja, Herrans tempel skall han bygga; han skall bära skruden, och skall sitta och råda på sinom stol; skall också vara en Prest på sinom stol, och der skall frid vara emellan dem båda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Och kronorna skola vara Helem, Tobia, Jedaja, och Hen, Zephania sone, till en åminnelse i Herrans tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Och de skola komma fjerranefter, som uppå Herrans tempel bygga skola. Så skolen I förnimma, att Herren Zebaoth mig till eder sändt hafver; och det skall ske, så framt I hörande varden Herrans edars Guds röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Och det skedde i fjerde lirena Konungs Darios, att Herrans ord skedde till ZacharIa, på fjerde dagen af nionde månadenom, den Chislev heter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Då SarEzer och RegemMelech, samt med deras män, sände till BethEl, till att bedja inför Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'Och läto säga Prestomen, som voro omkring Herrans Zebaoths hus, och till Propheterna: Skall jag ock ännu gråta i femte månadenom, och tvinga mig, såsom jag nu i några år gjort hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Och Herrans Zebaoths ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Tala till allt folket i landena, och till Presterna, och säg: Då I fastaden, och jämraden eder, i femte och sjunde månadenom, i dessa sjutio år. Hafven I då fastat mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Eller då I åten och drucken, hafven I icke ätit och druckit för eder sjelf?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Är icke detta, som Herren predika lät genom de förra Propheter; då Jerusalem ännu besuttet var, och hade nog, samt med sina städer omkring, och då der folk bodde, både söderut och i dalomen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Och Herrans ord skedde till ZacharIa och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Så säger Herren Zebaoth: Dömer rätt och hvar och en bevise godhet och barmhertighet uppå sin broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Och görer icke enkom, faderlösom, främlingom och fattigom, orätt; och ingen tänke något ondt emot sin broder i sitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Men de ville intet akta deruppå och vände ryggen till mig, och förstockade sin öron, att de icke höra skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Och gjorde sin hjerta lika som en diamant, att de icke skulle höra lagen och orden, som Herren Zebaoth, i sinom Anda, sände genom de förra Propheter; derföre sådana stor vrede af Herranom Zebaoth kommen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Och det år så skedt, som predikadt vardt, och de ville intet hörat; så ville jag ock intet hörat, då de ropade, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Alltså hafver jag förstrött dem ibland alla Hedningar, hvilka de intet känna; och landet är efter dem öde blifvet, så att der ingen uti vandrar eller bor; och det ädla landet är till ett öde gjordt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Och Herrans ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Detta säger Herren Zebaoth: Jag hafver nit haft ganska svårliga om Zion, och hafver i stor vrede nit haft derom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Så säger Herren: Jag vänder mig åter till Zion, och vill bo i Jerusalem, så att Jerusalem skall kallas en sannfärdig stad, och Herrans Zebaoths berg ett heligt berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Detta säger Herren Zebaoth: Der skola ännu härefter bo på Jerusalems gator gamle män och qvinnor, och de som med käpp gå af stor ålder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Och stadsens gator skola vara fulla med små piltar och pigor, som på gatomen leka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Detta säger Herren Zebaoth: Tycker dem detta omöjeligit vara, för detta igenlefda folks ögon, i denna tid; skulle det ock fördenskull omöjeligit vara för min ögon? säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Detta säger Herren Zebaoth: Si, jag vill förlossa mitt folk ifrån österlandet och ifrå vesterlandet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Och jag skall låta dem komma hit, till att bo i Jerusalem; och de skola vara mitt folk, och jag skall vara deras Gud, i sanning och rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Så säger Herren Zebaoth: Stärker edra händer, I som hören dessa orden, i denna tid, genom Propheternas mun, på den dagen då grunden lagd vardt på Herrans Zebaoths hus, att templet skulle bygdt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Ty för dessa dagar var menniskors arbete förgäfves, och djurens arbete var omintet; och var ingen frid dem som ut och in foro för bedröfvelse; utan jag lät alla menniskor gå, hvar och en emot sin nästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Men nu vill jag icke göra, såsom i de förra dagar, med de öfverblefna af desso folke, säger Herren Zebaoth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Utan de skola vara fridsens säd; vin trät skall gifva sina frukt, och jorden gifva sin växt, och himmelen skall gifva sina dagg; och jag skall låta de öfverblefna af desso folke allt detta besitta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Och det skall ske, lika som I af Juda hus, och af Israels hus, hafven varit en förbannelse ibland Hedningarna; så vill jag förlossa eder, att I skolen vara en välsignelse. Allenast frukter eder intet, och stärker edra händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Så säger Herren Zebaoth: Såsom jag tänkte att plåga eder, då edra fäder förtörnade mig, säger Herren Zebaoth, och det ångrade mig intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Alltså tänker jag nu igen, i dessom dagom, göra väl emot Jerusalem och Juda hus. Allenast frukter eder intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Men detta är det I göra skolen: Hvar och en tale sanningena med den andra; och dömer rätt, och skaffer frid i edrom portom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Och ingen tänke något ondt i sitt hjerta emot sin nästa, och älsker icke falska eder; ty allt sådant hatar jag, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Och Herrans Zebaoths ord skedde till mig, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Så säger Herren Zebaoth: Fjerde, femte, sjunde, och tionde månadens fasta skall vara Jude huse till en fröjd och glädje, och till gladsamma årshögtider. Allenast älsker sanning och frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Detta säger Herren Zebaoth: Framdeles skola ännu komma mycken folk, och många städers borgare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Och borgarena af den ena staden skola gå till de andra, och säga; Låt oss gå bort till att bedja inför Herranom, och till att söka Herran Zebaoth; vi vilje gå med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Alltså skola mång folk och Hedningar hopetals komma till att söka Herran Zebaoth i Jerusalem, och bedja inför Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Så säger Herren Zebaoth: På den tiden skola tio män, af allahanda Hedningars mål, fatta en Judisk man i klädefliken, och sägs: Vi vilje gå med eder; ty vi höre, att Gud är med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Detta är den tunge, der Herren om talar, öfver det landet Hadrach, och öfver Damascon, der det sig uppå förlåter; ty Herren ser uppå menniskorna, och uppå alla Israels slägter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Dertill ock öfver Hamath, som intill dem gränsar; och öfver Tyron och Zidon, hvilke ganska kloke äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Ty Tyrus bygger faste, och församlar silfver lika som sand, och guld såsom träck på gatomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Men si, Herren skall förderfva honom, och skall slå hans magt, som han på hafvena hafver, så att han skall vara lika som den med eld uppbränd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'När Askelon det får se, så skall han förskräckas, och Gaza skall fast bekymrad varda; dertill skall Ekron bedröfvad varda, då han detta ser; ty det skall vara ute med Konungenom i Gaza, och i Askelon skall man intet bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Uti Asdod skola främmande bo. Alltså skola de Philisteers prål utrotadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Och jag skall taga deras blod utu deras mun, och deras styggelse midt utu deras tänder, att de ock vårom Gudi igenblifva skola, att de måga vara lika som Förstar i Juda, och Ekron lika som de Jebuseer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Och jag skall besätta mitt hus med krigsfolk, de der ut och in draga, på det plågaren icke mer skall öfver dem komma; ty jag hafver nu sett derpå med min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Men du, dotter Zion, fröjda dig storliga; och du, dotter Jerusalem, gläd dig. Si, din Konung kommer till dig, en rättfärdig, och en hjelpare; fattig, och rider på enom åsna, och på enom ungom åsninnos fåla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Ty jag vill taga bort vagnen af Ephraim och hästen ifrå Jerusalem och stridsbågen skall sönderbruten varda; ty han skall lära frid ibland Hedningarna; och hans herradöme skall vara ifrå det ena hafvet intill det andra, och ifrå flodene intill verldenes ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Du utsläpper ock genom dins förbunds blod dina fångar utu kulone, der intet vatten uti är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Så vänder eder nu till fästet, I som uti ett hopp fångne liggen; ty ock i dag vill jag förkunnat, och vedergälla dig det dubbelt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Ty jag hafver spänt mig Juda till en båga, och tillrustat Ephraim; och skall uppväcka din barn, Zion, öfver din barn, Grekeland, och vill sätta dig såsom ett hjeltasvärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Och Herren skall synas öfver dem, och hans pilar skola utfara lika som en ljungeld; och Herren Herren skall blåsa i basun, och skall gå lika som ett sunnanväder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Herren Zebaoth skall beskydda dem, att de skola uppäta, och under sig tvinga med slungostenar; att de dricka skola och rumora, lika som af vin, och fulle varda såsom en skål, och såsom hörnen af altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Och Herren, deras Gud, skall på den tiden hjelpa dem, såsom sins folks hjord; ty vigde stenar skola i hans land uppreste varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Ty hvad godt hafva de för andra, eller hvad dägeligit hafva de för andra? Korn, som föder ynglingar, och vin, som jungfrur föder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Så beder nu af Herranom serlaregn, så skall Herren göra moln, och gifva eder regn nog till all växt på markene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Ty afgudarna tala icke annat än vedermödo, och spåmännerna se icke annat än lögn, och tala icke annat än fåfånga drömmar, och deras tröstning är intet; derföre gå de ville såsom får, och äro försmäktade, efter der är ingen herde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Min vrede hafver förgrymmat sig öfver herdarna, och jag skall hemsöka bockarna; ty Herren Zebaoth skall söka sin hjord, nämliga Juda hus, och skall tillrusta dem, såsom en väl tillpyntad häst till strids.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Hörn, nagle, stridsbåge och drifvare, skola alle bort ifrå dem komma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Och skola likväl ändå vara såsom hjeltar, de der träck trampa på gatomen i stridene, och skola strida; ty Herren skall vara med dem, att de resenärer skola till skam varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Och jag skall stärka Juda hus, och hjelpa Josephs hus, och skall sätta dem åter in igen; ty jag förbarmar mig öfver dem, och de skola vara såsom de voro förra än jag fördref dem; ty jag, Herren deras Gud, vill höra dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Och Ephraim skall vara såsom en hjelte, och deras hjerta skall gladt varda, lika som af vin; dertill skola deras barn se det, och fröjda sig, och deras hjerta gladt vara i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Jag skall blåsa till dem, och församla dem; ty jag vill förlossa dem, och de skola förmera sig, såsom de sig tillförene förmerat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Och jag skall så dem ibland folk, att de skola tänka uppå mig i fjerran landom, och skola med sin barn lefva och igenkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Ty jag vill låta dem igenkomma utur Egypti land, och skall församla dem utur Assyrien, och låta dem komma uti Gileads land och Libanon, och dem skull intet fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Och han skall gå igenom det trånga hafvet, och slå böljorna i hafvena, att alla djupa floder skola uttorkade varda. Så skall då förnedradt varda det prål i Assyrien, och spiran uti Egypten skall återvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Jag skall stärka dem i Herranom, så att de skola vandra uti hans Namn, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Låt upp dina dörr, Libanon, att eld må förtära din cedreträ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Jämrer eder, I furoträ ty cedreträn äro fallne, och den härliga byggningen är förstörd. Jämrer eder, I eker i Basan; ty den faste skogen är omkullhuggen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Man hörer herdarna jämra sig; ty deras härliga byggning är förstörd. Man hörer de unga lejonen ryta; ty Jordans prål är förstördt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Det säger Herren, min Gud: Vakta slagtefåren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Ty deras herrar slagta dem, och hålla det för ingen synd; sälja dem; ock säga: Lofvad vare Herren; jag är nu rik; och deras herdar skona dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Derföre vill jag ock intet mer skona inbyggarena i landena, säger Herren. Och si, Jag skall öfvergifva menniskorna, hvar och en uti dens andras hand, och uti deras Konungs hand, att de skola förkrossa landet, och jag skall intet hjelpa dem utu deras hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Och jag vaktade slagtefåren för de elända fårens skull, och tog två stafrar till mig; den ena kallade jag Lust, den andra kallade jag Ve, och vaktade fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Och jag förgjorde tre herdar uti enom månad, ty jag förmådde icke lida dem; så ledo de ej heller mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Och jag sade: Jag vill intet vakta eder. Det som dör, det dö; det som försmäktar, det försmäkte; och de qvarblefne äte det ena dess andras kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Och jag tog min staf Lust, och bröt honom sönder, på det jag skulle rygga mitt förbund, som jag med all folk gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Och det vardt på den dagen ryggadt; och de elände fåren, som med mig höllo, märkte deraf, att det Herrans ord var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Och jag sade till dem: Behagar det eder, så bärer hit så mycket som jag gäller; hvar icke, så låter det blifva. Och de vogo upp så mycket som jag galt, tretio silfpenningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Och Herren sade till mig: Kasta det bort, att det må enom pottomakare gifvet varda, den kosteliga summan, för hvilka jag när dem skattad är. Och jag tog de tretio silfpenningar, och kastade dem uti Herrans hus, på det de skulle pottomakarenom gifne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Och jag bröt sönder den andra min staf Ve; på det jag skulle borttaga broderskapet emellan Juda och Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Och Herren sade till mig: Tag åter till dig ens galens herdas tyg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Ty si, jag skall uppväcka herdar i landena, de der icke skola bese det försmäktada; det slagna icke besöka, och det sönderbrutna icke hela, och det helbregda icke försörja; utan de fetas kött skola de uppäta, och sönderrifva deras klöfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'O! afgudaherdar, som hjorden öfvergifva; svärdet komme öfver deras arm, och uppå deras högra öga; deras arm borttvine, och deras högra öga varde mörkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Detta är Herrans ords tunge öfver Israel, säger Herren, den der utsträcker himmelen, och grundar jordena, och menniskones anda gör uti honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Si, jag vill göra Jerusalem till en fallskål allom folkom deromkring; ty det varder ock Juda gällandes, när Jerusalem belagt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Likväl vill jag på den tiden göra Jerusalem till en tung sten allom folk om; alle de som vilja borthäfva honom, de skola förslita sig på honom; ty alle Hedningar på jordene skola församla sig emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'På den tiden, säger Herren, skall jag göra hvar och en häst sky, och hans åsittare ursinnigan; men öfver Juda hus vill jag hafva min ögon öppne, och plåga alla folks hästar med blindhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Och Förstarna i Juda skola säga uti sitt hjerta: Låt de borgare i Jerusalem hafva ett godt mod i Herranom Zebaoth, deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'På den tiden skall jag göra Juda Förstar till en brinnande ugn i ved, och såsom en eldbrand i halm; så att de skola uppfräta, både på högra sidone och den venstra, all folk omkring sig; och Jerusalem skall åter besuttet varda i sitt rum, i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Och Herren skall hjelpa Juda hyddor, såsom i förtiden; på det Davids hus icke skall högt berömma sig, eller borgarena i Jerusalem emot Juda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'På den tiden skall Herren beskärma borgarena i Jerusalem; och det skall ske, att den der svag är på den tiden, han skall vara såsom David; och Davids hus skall vara såsom Guds hus, såsom Herrans Ängel för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Och på den tiden skall jag tänka till att nederlägga alla Hedningar, som emot Jerusalem dragne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Men öfver Davids hus, och öfver borgarena i Jerusalem, skall jag utgjuta nåds och böns Anda; ty de skola se uppå mig, den de genomstungit hafva; och skola begråta honom, lika som man ett enda barn begråter; och skola bedröfva sig om honom, såsom man bedröfvar sig om ett första barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'På den tiden skall stor klagogråt vara i Jerusalem, lika som det var men HadadRimmon, uti den markene Megiddon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Och landet skall jämra sig, hvart och ett slägte besynnerliga; Davids hus slägte besynnerliga, och deras hustrur besynnerliga; Nathans hus slägte besynnerliga, och deras hustrur besynnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Levi hus slägte besynnerliga, och deras hustrur besynnerliga; Simei hus slägte besynnerliga, och deras hustrur besynnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Alltså alla andras slägter, hvart och ett besynnerliga, och deras hustrur också besynnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'På den samma tiden skall Davids hus, och borgarena i Jerusalem, hafva en fri öppen brunn emot synder och orenhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'På den tiden, säger Herren Zebaoth, skall jag borttaga de afgudars namn utu landena, så att man intet mer skall komma dem ihåg; dertill vill jag ock bortdrifva de spåmän och orena andar utu landena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Och skall ske, att när någor mer spår, så skola hans fader och moder, de honom födt hafva, säga till honom: Du måste dö, ty du talar lögn uti Herrans Namn. Och alltså skola fader och moder, de honom födt hafva, stinga honom genom, då han spår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Ty det skall ske på den tiden, att spåmännerna komma på skam med sina syner, då de derom spå; och skola icke mer draga hårkläder uppå, der de med bedraga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Utan han skall säga: Jag är ingen Prophet, utan en åkerman; ty jag hafver tjent menniskom allt ifrå minom ungdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Men om man då säger: Hvad är det för sår uti dina händer? Då skall han säga: Så är jag slagen uti deras hus, som mig älska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Svärd, upp öfver min herda, och öfver mins folks Första, säger Herren Zebaoth; slå herdan, så varda fåren förskingrad; så vill jag vända mina hand till de små.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Och det skall ske, uti hvilket land, säger Herren, två delar äro, de skola bortryckas och förläggas, och tredjedelen derinne qvarblifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Och jag skall föra den samma tredjedelen genom eld, och rensa honom, såsom man rensar silfver, och fäja honom, såsom man fäjar guld. Desse skola då åkalla mitt Namn, och jag skall höra dem; jag skall säga: Det är mitt folk; och de skola säga: Herren, min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Så Herrans dag kommer, att du skall varda ett rof och byte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Ty jag skall församla allahanda Hedningar emot Jerusalem till strid; och staden skall varda vunnen, husen skinnad, och qvinnor skämda; hälften af stadenom skall fången bortföras, och det öfverblefna folket skall icke utu stadenom drifvet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Men Herren skall draga ut, och strida emot de samma Hedningar, såsom han plägar att strida i stridstid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Ock hans fötter skola på den tiden stå på Oljobergena, som för Jerusalem ligger, östantill; och Oljoberget skall klofna midt i tu stycker, ifrån öster allt intill vester, ganska vidt ifrå hvartannat; så att den ena hälften af bergena skall gifva sig norrut, och den andra söderut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Och I skolen fly ror denna dalenom emellan min berg; ty den dalen emellan bergen skall räcka intill Azal; och skolen fly, lika som I uti förtiden flydden för jordbäfningene i Ussia, Juda Konungs, tid. Så skall Herren, min Gud, komma, och alle helige med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'På den tiden skall intet ljus vara, utan köld och frost.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Och en dag skall varda, den Herranom kunnig är, hvarken dag eller natt, och om aftonen skall det ljust blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'På den tiden skola rinnande vatten flyta utaf Jerusalem; hälften bortåt hafvet österut, och den andra hälften bortåt det yttersta hafvet; och det skall vara både vinter och sommar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Och Herren skall vara en Konung öfver all land; på den tiden skall Herren vara en, och hans Namn ett.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Och man skall gå i allo landena, lika som på en slättmark, ifrå Gibea intill Rimmon, söderut, till Jerusalem; ty han skall upphöjd och besutten varda i sitt rum, ifrå, BenJamins port, intill första portens rum, allt intill hörneporten; och ifrå Hananeels torn, intill Konungens press.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Och man skall bo derinne, och ingen spillgifning skall mer vara; ty Jerusalem skall ganska säkert bo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Och detta skall vara plågan, der Herren all folk med plåga skall, som emot Jerusalem stridt hafva; deras kött skall förtvina; medan de ännu stå på deras fötter; och deras ögon förgås uti sin hål, och deras tunga förfaras i deras mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'På den tiden skall Herren låta komma ett stort buller ibland dem, att den ene skall fatta den andra vid handena, och lägga sina hand uppå dens andras hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Ty ock Juda skall strida emot Jerusalem; på det församlas skola alla de Hedningars gods, som deromkring äro; guld, silfver och kläder, öfvermåtton mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Och så skall då denna plågan gå öfver hästar, mular, camelar, åsnar, och allahanda djur, som i härenom äro, såsom denna plågan är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Och alle öfverblefne ibland alla Hedningar, som emot Jerusalem drogo, skola årliga komma upp, till att tillbedja Konungen, Herran Zebaoth, och till att hålla löfhyddohögtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Men hvad som helst slägte på jordene icke kommer hitupp till Jerusalem, till att tillbedja Konungen, Herran Zebaoth, öfver dem skall intet regn komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Och om de Egyptiers slägte icke uppfara, och komma, så skall öfver dem ock intet regna. Det skall vara plågan, der Herren alla Hedningar med plåga skall, som icke uppkomma till att hålla löfhyddohögtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Ty det skall vara de Egyptiers, och alla Hedningars synd, som icke uppkomma till att hålla löfhyddohögtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'På den tiden skall hästarnas rustning vara Herranom helig; och kettlarne i Herrans hus skola vara lika som de skålar för altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Ty alle kettlar, både i Jerusalem och Juda, skola Herranom Zebaoth helige vara; så att alle de, som offra vilja, skola komma och taga dem, och koka deruti; och ingen Cananeisk skall mer vara uti Herrans Zebaoths hus, på den tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Detta är den tunge, som Herren talade mot Israel, genom Malachi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Jag hafver eder kär, säger Herren. Så sägen I: Hvarmed hafver du oss kär? Är icke Esau Jacobs broder? säger Herren. Likväl hafver jag Jacob kär;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Och jag hatar Esau, och hafver gjort hans berg öde, och hans arf drakomen till en öken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Och om Edom säga ville: Vi äre förderfvade, dock vilje vi uppbygga igen det ödelagdt är; då säger Herren Zebaoth alltså: Om de bygga, så skall jag nederbryta; och det skall heta de fördömda landsändar och ett folk der Herren är vred uppå evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Det skola edor ögon se, och I skolen säga: Herren är härlig uti Israels landsändom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'En son skall hedra sin fader, och en tjenare sin herra. Är jag nu Fader, hvar är min heder? Är jag Herre, hvar fruktar man mig? säger Herren Zebaoth till eder, Presterna, som mitt Namn förakten. Så sägen I då: Hvarmed förakte vi ditt Namn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Dermed att I offren orent bröd uppå mitt altare. Så sägen I: Hvarmed offre vi dig något orent? Dermed, att I sägen: Herrans bord är intet aktandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Och när I offren något det blindt är, så måste det icke heta ondt; och när I offren något det halt är eller krankt, så måste det ock intet heta ondt. Bär det dinom Första; hvad gäller, om du skall täckas honom, eller om han vill se uppå din person? säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Så bedjer nu Gud, att han ville vara oss nådelig; ty detta är skedt af eder. Menen I, att han skall se till edra person? säger I Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Hvilken är ock ibland eder, den ena dörr tillycker? I tänden ock ingen eld uppå mitt altare omsyss. Jag hafver intet behag i eder, säger Herren Zebaoth; och spisoffer af edra händer är mig icke täckeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Men af solenes uppgång allt intill nedergången skall mitt Namn härligit varda ibland Hedningarna; och i all rum skall mino Namne rökt, och ett rent spisoffer offradt varda; ty mitt Namn skall härligit varda ibland Hedningarna, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Men I ohelgen det dermed, att I sägen: Herrans bord är oheligt, och dess offer är föraktadt, samt med sinom spis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Och I sägen: Det är icke utan mödo; och slån det i vädret, säger Herren Zebaoth; och I offren det som röfvadt, halt och krankt är, och offren så spisoffer. Skulle sådant täckas mig ifrån edra hand? säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Förbannad vare den bedragaren, den i sinom hjord hafver en Han; och när han gör ett löfte, så offrar han Herranom det som intet doger; ty jag är en stor Konung, säger Herren Zebaoth, och mitt Namn är förskräckeligit ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Och nu, I Prester, detta budet gäller eder till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Om I det icke hören, eller icke läggen det uppå hjertat, så att I gifven mino Namne ärona, säger Herren Zebaoth; så skall jag sända en förbannelse ibland eder, och skall förbanna edor välsignelse; ja, förbanna skall jag dem, efter I icke villen lägga det uppå hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Si, jag skall förbanna edra efterkommande, och kasta eder träcken af edro offre uti edart ansigte; och han skall låda vid eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Så skolen I då förnimma, att jag sådana bud till eder sändt hafver, att detta skulle vara mitt förbund med Levi, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Ty mitt förbund var med honom, till lif och frid; och jag gaf honom fruktan, så att han mig fruktade, och förskräcktes för mino Namne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Sanningens lag var uti hans mun, och der vardt intet ondt funnet uti hans läppar; han vandrade fridsammeliga och redeliga för mig, och omvände många ifrå synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Ty Prestens läppar skola bevara lärona, att man må befråga lagen af hans mun; ty han är en Herrans Zebaoths Ängel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Men I ären afgångne ifrå vägenom, och hafven förargat många i lagen; och hafven brutit Levi förbund, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Derföre hafver jag ock gjort, att I föraktade och försmädde ären för allo folkena; efter I icke hållen mina vägar, och sen till personen i lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Ty hafvom vi icke alle en fader? Hafver icke allt en Gud skapat oss? Hvi förakte vi då den ene den andra, och ohelgom förbundet, som med våra fäder gjordt är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Ty Juda är vorden en föraktare, och i Israel, och i Jerusalem sker styggelse; ty Juda ohelgar Herrans helighet, den han älskar; och bolar med ens främmandes guds dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Men Herren skall den, som så gör, utrycka utu Jacobs hydda, både mästaren och lärjungan, samt med honom, som Herranom Zebaoth spisoffer offrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Yttermera gören I ock, att för Herrans altare äro icke annat än tårar, och gråt, och suckande; så att jag icke mer kan sa till spisoffret, eller någrahanda tacknämligit undfå af edra händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Och så sägen I: Hvarföre? Derföre att du föraktar dina kära hustru, den Herren dig tillskickat hafver, och den din maka är, hvilko du förpligtad äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Alltså gjorde icke den ene, hvilken dock var af enom storom anda. Men hvad gjorde den ene? Han sökte den säden, som af Gudi tillsagd var. Derföre ser eder före för edrom anda, och ingen förakte sina kära hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Äst du henne vred, så skilj dig ifrå henne, säger Herren Israels Gud; och gif henne en klädnad för försmädelsen, säger Herren Zebaoth. Derföre ser eder före för edrom anda, och förakter henne icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'I hafven rett Herran med edart tal. Så sägen I då: Hvarmed hafve vi rett honom? Dermed, att I sägen: Den der illa gör, han behagar Herranom, och han hafver lust till honom; eller, hvar är nu Gud, som straffar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Så Jag vill utsända min Ängel, den der vägen rör mig bereda skall; och med hast skall komma till sitt tempel Herren, den I söken, och förbundsens Ängel, den I begären. Si, han kommer, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Men ho kan lida hans tillkommelses dag? Och ho skall bestå, då han låter sig se? Ty han är lika som en guldsmeds eld, och såsom en vaskerskos såpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Han skall sitta, och smälta och fäja silfret; han skall fäja och rensa Levi söner, lika som silfver och guld; Så skola de då offra spisoffer uti rättfärdighet Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Och Juda och Jerusalems spisoffer skall väl behaga Herranom, lika som fordomdags, och i de förra år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Och jag skall komma till eder, och straffa eder, och skall vara ett snart vittne emot de trollkarlar, horkarlar och menedare, och emot dem som vild och orätt göra dagakarlenom, enkone och dem faderlösa, och förtrycka främlingen, och intet frukta mig, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Ty jag är Herren, den icke ljuger; och I, Jacobs barn, skolen icke allesamman förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'I hafven ifrå edra fäders tid allstädes afvikit ifrå min bud, och intet hållit dem. Så omvänder eder nu till mig, så vill lag ock vända mig till eder, säger Herren Zebaoth. Så sägen I då: Hvarutinnan skole vi omvända oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Är det rätt, att en menniska besviker Gud, såsom I besviken mig? Så sägen I då: Hvarmed besvike vi dig? Med tiond och häfoffer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Derföre ären I ock förbannade, så att all ting försvinner eder undan händerna; ty I besviken mig allesamman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Men förer mig tiondena allesammans uti mina tiondelado, att i mino huse må spis vara; och bepröfver mig härutinnan, säger Herren Zebaoth, om jag ock icke upplåter eder himmelens fenster, och gjuter välsignelse neder tillfyllest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Och jag vill för eder straffa frätaren att han icke skall förderfva fruktena på markene, och att vinträt i åkrenom icke skall vara eder ofruktsamt, säger Herren Zebaoth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Så att alle Hedningar skola prisa eder saliga; ty I skolen vara ett kosteligit land, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'I talen hårdeliga emot mig, säger Herren. Så sägen I då: Hvad tale vi emot dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Dermed, att I sägen: Det är förgäfves, att man Gudi tjenar, och hvad båtar det, att vi hållom hans bud, och förom ett strängt lefverne för Herranom Zebaoth?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Derföre prise vi de föraktare; ty de ogudaktige växa till; de försöka Gud, och det går dem alltsammans väl utaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Men de, som frukta Herran, trösta hvarann alltså: Herren märker det, och hörer det; och det är en tänkeskrift för honom skrifven, för dem som frukta Herran, och tänka uppå hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'De skola, säger Herren Zebaoth, vara min egendom på dem dagenom, den jag göra skall; och jag vill skona dem, lika som man skonar sin egen son, den honom tjenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Och I skolen deremot åter se, hvad för en åtskilnad är emellan den rättfärdiga och den ogudaktiga, och emellan den som Gudi tjenar, och den som honom icke tjenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Ty si, en dag kommer, som brinna skall, lika som en ugn; så skola då alle föraktare och ogudaktige vara halm, och den tillkommande dagen skall upptända dem, säger Herren Zebaoth, och skall hvarken lefva dem rot eller qvist.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Men eder, som mitt Namn frukten, skall uppgå rättfärdighetenes sol, och salighet under hennes vingar; och I skolen gå ut och in, och växa till, lika som gödokalfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'I skolen trampa uppå, de ogudaktiga; ty de skola varda till asko under edra fötter, på dem dagenom, den jag göra skall, säger Herren Zebaoth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Kommer ihåg Mose, mins tjenares, lag, den jag honom befallde på det berget Horeb till hela Israel, samt med bud och rätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Si, jag skall sända eder den Propheten Elia, förr än den store och förskräckelige Herrans dag kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Han skall omvända fädernas hjerta till barnen, och barnens hjerta till fäderna; på det jag icke skall komma, och slå jordena med spillgifning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Detta är boken af Jesu Christi börd, hvilken som är Davids son, Abrahams sons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham födde Isaac; Isaac födde Jacob; Jacob födde Juda, och hans bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda födde Pharez och Zara, af Thamar; Pharez födde Hezrom; Hezrom födde Aram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram födde Aminadab; Aminadab födde Nahasson; Nahasson födde Salmon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmon födde Boas, af Rahab; Boas födde Obed, af Ruth; Obed födde Jesse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Jesse födde Konung David; Konung David födde Salomon, af henne som var Urie hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomon födde Roboam; Roboam födde Abia; Abia födde Asa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asa födde Josaphat; Josaphat födde Joram; Joram födde Osia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Osia födde Joatham; Joatham födde Achas; Achas födde Ezechia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezechia födde Manasse; Manasse födde Amon; Amon födde Josia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Josia födde Jechonia och hans bröder, vid det Babyloniska fängelset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Men efter det Babyloniska fängelset födde Jechonia Salathiel; Salathiel födde Zorobabel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel födde Abiud; Abiud födde Eliakim; Eliakim födde Asor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Asor födde Zadok; Zadok födde Achim; Achim födde Eliud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud födde Eleazar: Eleazar födde Mattham; Mattham födde Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jacob födde Joseph, Marie man, af hvilko är födder Jesus, som kallas Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Så äro alle lederna, ifrån Abraham intill David, fjorton leder; ifrå David till det Babyloniska fängelset, ock fjorton leder; ifrå det Babyloniska fängelset intill Christum, ock fjorton leder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Jesu Christi födelse gick så till: När Maria, hans moder, var trolofvad Joseph, förr än de kommo samman, fans hon vara hafvandes af den Heliga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Men efter Joseph var en from man, och ville icke röja henne, tänkte han hemliga öfvergifva henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'När han detta tänkte, si, då uppenbarades honom i sömnen Herrans Ängel, och sade: Joseph, Davids son, räds icke taga Maria, din hustru, till dig; ty det som är afladt i henne, det är af den Heliga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Och hon skall föda en Son, och du skall kalla hans Namn JESUS; ty han skall frälsa sitt folk ifrå deras synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Detta är allt skedt, på det fullbordas skulle det af Herranom sagdt är genom Propheten, som sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Si, en Jungfru skall varda hafvandes, och föda en Son, och de skola kalla hans Namn EmmanuEl; det är så mycket sagdt: Gud med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'När Joseph vaknade upp af sömnen, gjorde han som Herrans Ängel hade honom befallt, och tog sina hustru till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Och kände henne intet, tilldess hon födde sin första Son; och kallade hans Namn JESUS.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'När Jesus var födder i BethLehem i Judiska landet, i Konung Herodis tid, si, då kommo vise män af österlanden till Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Och sade: Hvar är den nyfödde Juda Konungen? Ty vi hafve sett hans stjerno i österlanden, och äre komne att tillbedja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'När Konung Herodes det hörde, vardt han bedröfvad, och hele Jerusalems stad med honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Och lät församla alla de öfversta Presterna, och Skriftlärda ibland folket, och frågade dem hvar Christus skulle födas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Och de sade honom: I BethLehem, i Judiska landet; ty det är så skrifvet genom Propheten:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Och du BethLehem, i Judiska landet, äst ingalunda den minste ibland Juda Förstar; ty utaf dig skall mig komma den Försten, som öfver mitt folk, Israel, en Herre vara skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Då kallade Herodes lönliga de visa männerna till sig, och besporde granneliga af dem, hvad tid stjernan syntes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Och sände dem så till BethLehem, och sade: Farer dit, och bespörjer granneliga efter barnet; och när I det finnen, så säger mig det igen, att jag kan ock komma, och tillbedja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'När de hade hört Konungen, foro de åstad; och si, stjernan, som de sett hade i österlanden, gick för dem, så länge hon kom, och blef ståndandes öfver der barnet var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'När de sågo stjernona, vordo de ganska glade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Och gingo in i huset, och funno barnet med Maria dess moder; och föllo neder och tillbådo honom, och uppläto sina håfvor, och skänkte honom guld, rökelse och myrrham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Sedan fingo de uppenbarelse i sömnen, att de skulle icke komma igen till Herodes; och foro så en annan väg hem i sitt land igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'När de voro bortfarne, si, då uppenbarades Herrans Ängel Joseph i sömnen, sägandes: Statt upp, och tag barnet och dess moder till dig, och fly in uti Egypti land, och blif der så länge jag säger dig till; ty det kommer dertill, att Herodes skall söka efter barnet, till att förgöra det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Han stod upp, och tog barnet och dess moder, om nattena, till sig, och flydde in uti Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Och blef der intill Herodis död, på det att fullbordas skulle det som sagdt var af Herranom genom Propheten, som sade: Utaf Egypten hafver jag kallat min Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'När Herodes nu såg, att han var besviken af de visa män, blef han ganska vred; och sände ut, och lät slå ihjäl all svenbarn i BethLehem, och i alla dess gränsor, de som tveggeåra och der förnedan voro, efter den tiden som han hade granneliga besport af de visa män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Då blef fullkomnadt det som af Jeremia Propheten sagdt var, när han sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'I höjdene vardt hörd en röst, stor klagomål, gråt och mycken skrän: Rachel gråter sin barn, och vill icke låta hugsvala sig; ty det var ute med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Men när Herodes var död, si, då uppenbarades Herrans Ängel Joseph i sömnen, i Egypti land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Och sade: Statt upp, och tag barnet och dess moder till dig, och far in i Israels land; ty de äro döde, som foro efter barnets lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Han stod upp, och tog barnet och dess moder till sig, och for in uti Israels land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Men när han hörde, att Archelaus var rådandes i Judiska landet, i sin faders Herodis stad, räddes han fara dit; och fick befallning af Gud i sömnen, och for in uti Galilee landsändar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'Och kom, och bodde i den staden, som heter Nazareth; att det skulle fullkomnas, som var sagdt genom Propheterna: Han skall kallas Nazareus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'I den tiden kom Johannes Döparen, och predikade i öknene, i Judiska landet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Och sade: Görer bättring; himmelriket är kommet hardt när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Och han är den som Esaias Propheten talade om, och sade: Ens ropandes röst är i öknene: Bereder Herrans väg, görer hans stigar rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Men Johannes hade kläder af camelahår, och en lädergjording om sina länder; hans mat var gräshoppor och vildhannog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Då gick Jerusalems stad ut till honom, och hela Judiska landet, och all land som ligga utmed Jordan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Och läto döpa sig af honom i Jordan, och bekände sina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Då han såg många utaf de Phariseer och Sadduceer komma till sin döpelse, sade han till dem: I huggormars afföda, ho hafver eder föregifvit, att I skolen undfly den tillkommande vrede?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Görer fördenskull sådana frukt, som bättring tillhörer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Och tänker icke, att I viljen säga vid eder sjelfva: Vi hafvom Abraham till fader. Ty jag säger eder, att Gud är mägtig uppväcka af dessa stenar Abrahe barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Nu är ock yxen satt till rotena på trän; derföre hvart och ett trä, som icke gör goda frukt, blifver afhugget och kastadt i elden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Jag döper eder i vatten, till bättring; men den efter mig kommer, är starkare än jag, hvilkens skor jag icke är värdig att bära; han skall döpa eder med den Heliga Anda, och med eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Och han hafver sina kastoskofvel i sine hand, och han skall rensa sin loga, och han skall församla sitt hvete i ladona; men agnarna skall han uppbränna i evinnerlig eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Då kom Jesus af Galileen till Jordan, till Johannes, att han skulle låta döpa sig af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Men Johannes förvägrade honom, och sade: Mig behöfves, att jag vorde döpt af dig; och du kommer till mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Då svarade Jesus, och sade till honom: Låt det nu så ske; så bör det sig vara med oss, att vi uppfylle alla rättfärdighet. Då tillstadde han honom det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Och när Jesus var döpt, steg han straxt upp af vattnet; och si, då vardt honom himmelen öppnad, och han såg Guds Anda nederfara som en dufva, och komma öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Och si, en röst af himmelen sade: Denne är min käre Son, i hvilkom jag hafver ett godt behag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Då vardt Jesus förd af Andanom i öknena, på det han skulle försökas af djefvulen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Och när han hade fastat i fyratio dagar och fyratio nätter, så hungrade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Och frestaren gick fram till honom, och sade: Äst du Guds son, så säg, att desse stenar varda bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Då svarade han, och sade: Det är skrifvet: Menniskan lefver icke allenast vid bröd, utan af hvart och ett ord, som går af Guds mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Då tog djefvulen honom med sig till den heliga staden, och satte honom öfverst på tinnarna af templet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'Och sade till honom: Äst du Guds Son, så gif dig härutföre; ty det är skrifvet: Han skall gifva sinom Änglom befallning om dig; och de skola bära dig på sina händer, att du icke skall stöta din fot emot stenen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Då sade Jesus till honom: Det är ock skrifvet: Herran din Gud skall du icke fresta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Då tog åter djefvulen honom med sig uppå ett ganska högt berg, och viste honom all rike i verldene, och deras härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Och sade till honom: Allt detta vill jag gifva dig, om du faller neder, och tillbeder mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Då sade Jesus till honom: Gack bort, Satan; ty det är skrifvet: Herran din Gud skall du tillbedja, och honom allena skall du tjena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Då öfvergaf djefvulen honom; och si, Änglarna gingo fram, och tjente honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Då nu Jesus hörde, att Johannes var fången, drog han in i Galileen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Och öfvergaf Nazareth, och kom, och bodde i Capernaum, som ligger vid hafvet, på gränson vid Zabulon och Nephthalim;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'På det att fullkomnas skulle det som sagdt var genom Esaia Propheten, som sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Det landet Zabulon, och det landet Nephthalim, vid hafsens väg, på denna sidon Jordan, och den hedniska Galileen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Folket, som satt i mörkret, hafver sett ett stort ljus; och dem, som bodde i dödsens ängd och skugga, är ett ljus uppgånget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Ifrå den tiden begynte Jesus till att predika, och sade: Görer bättring; himmelriket är kommet hardt när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'När Jesus gick utmed det Galileiska hafvet, såg han två bröder, Simon, som kallas Petrus, och Andreas, hans broder; de kastade sin nät i hafvet, ty de voro fiskare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Och han sade till dem: Följer mig; jag vill göra eder till menniskors fiskare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'De öfvergåfvo straxt näten, och följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Och när han gick fram bätter, såg han två andra bröder, Jacob, Zebedei son, och Johannes, hans broder, i båten med deras fader Zebedeus, botande sin nät; och han kallade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Straxt öfvergåfvo de båten, och sin fader, och följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Och Jesus gick omkring allt Galileiska landet, och lärde i deras Synagogor, och predikade Evangelium om riket, och botade allahanda sjukdom och krankhet i folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Och hans rykte gick öfver hela Syrien; och de hade till honom alla de der kranke voro af mångahanda sjukdom, och värkbrutna och besatta, och månaderasande och borttagna; och han gjorde dem alla helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Och honom följde mycket folk utaf Galileen, och utaf de tio städer, och utaf Jerusalem, och utaf Judeen, och utaf de land på denna sidon vid Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'När han såg folket, steg han upp på ett berg; och som han hade satt sig, gingo hans Lärjungar fram till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Då öppnade han sin mun, lärde dem, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Salige äro de som äro andelige fattige; ty himmelriket hörer dem till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Salige äro de bedröfvade; ty de skola få hugsvalelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Salige äro de saktmodige; ty de skola besitta jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Salige äro de som hungra och törsta efter rättfärdighetena; ty de skola blifva mättade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Salige äro de barmhertige; ty dem skall ske barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Salige äro de renhjertade; ty de skola se Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Salige äro de fridsamme; ty de skola kallas Guds barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Salige äro de som lida förföljelse för rättvisones skull; ty dem hörer himmelriket till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Salige ären I, när menniskorna försmäda och förfölja eder, och säga allt ondt emot eder, ljugande, för mina skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Glädjens och fröjder eder; ty edor lön är stor i himmelen; förty de hafva sammalunda förföljt Propheterna, som hafva varit för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'I ären jordenes salt; är det så, att saltet mister sin sälto, hvarmed skall man då salta? Till intet mer är det nyttigt, utan att man kastar det ut, och låter det trampas af menniskomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'I ären verldenes ljus; icke kan den staden döljas, som ligger på ett berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Icke tänder man heller ljus, och sätter det under ena skäppo, utan på en ljusastaka; att det lyser allom dem som i huset äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Så låter edart ljus lysa för menniskomen, att de måga se edra goda gerningar, och prisa edar Fader, som är i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'I skolen icke mena, att jag är kommen till att upplossa lagen, eller Propheterna; jag är icke kommen till att upplossa, utan till att fullborda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Ty jag säger eder för sant: Tilldess att himmel och jord förgås, varder ej förgången den minste bokstafven, icke heller en prick af lagen, förr än det är allt skedt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Derföre, hvilken som upplossar ett af dessa minsta buden, och lärer så menniskorna, han skall kallas den minste i himmelriket; men hvilken som det gör och lärer, han skall kallas stor i himmelriket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Ty jag säger eder att, utan edor rättfärdighet öfvergår de Skriftlärdas och de Phariseers, då skolen I icke komma i himmelriket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'I hafven hört, att dem gamlom sagdt är: Du skall icke dräpa; men hvilken som dräper, han skall vara skyldig under domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Men jag säger eder, att hvilken som förtörnas på sin broder, han skall vara skyldig under domen; men hvilken som säger: Racha till sin broder, han är skyldig under rådet; men hvilken som säger: Du dåre, han är skyldig till helvetes eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Derföre, om du offrar dina gåfvo på altaret, och kommer så ihåg, att din broder hafver något emot dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Så lägg der dina gåfvo ned för altaret, och gack först bort, och förlika dig med din broder; och kom sedan, och offra dina gåfvo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Du skall vara din trätobroder benägen till vänskap snart, medan du ännu äst med honom på vägen; att din trätobroder antvardar dig icke domarenom, och domaren antvardar dig tjenarenom, och du kastas så i häktelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Sannerliga säger jag dig, du varder der icke utkommandes, tilldess du hafver betalat den yttersta skärfven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'I hafven hört, att det var sagdt dem gamlom: Du skall icke göra hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Men jag säger eder: Hvilken som ser på ena qvinno, till att begära henne, han hafver allaredo gjort hor med henne i sitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Om så är, att ditt högra öga är dig till förargelse, så rif det ut, och kastat ifrå dig; det är dig bättre att ett ditt ledamot förderfvas, än att din hela kropp skulle kastas till helvetes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Är det ock så, att din högra hand är dig till förargelse, så hugg henne af, och kasta henne ifrå dig; det är dig bättre att ett ditt ledamot förderfvas, än att hela kroppen kastas till helvetes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Det är ock sagdt: Hvilken som öfvergifver sina hustru, han skall gifva henne ett skiljobref.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Men jag säger eder: Hvilken som helst öfvergifver sina hustru, utan för hors skull, han kommer henne till att göra hor; och hvilken ena öfvergifna tager till hustru, han gör hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Åter hafven I hört, att det var sagdt dom gamlom: Du skall icke svärja dig men, utan skall hålla Herranom din ed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Men jag säger eder, att I skolen allsintet svärja, hvarken vid himmelen; ty han är Guds stol;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Eller vid jordena; ty hon är hans fotapall; ej heller vid Jerusalem; ty det är en mägtig Konungs stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Ej heller skall du svärja vid ditt hufvud; ty du förmår icke göra ett hår hvitt eller svart.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Men edart tal skall vara: Ja, ja; nej, nej; hvad deröfver är, det är af ondo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'I hafven hört, att det är sagdt: Öga för öga, tand för tand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Men jag säger eder, att I skolen icke stå det onda emot; utan är det så, att någor slår dig vid det högra kindbenet, så vänd honom ock det andra till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Och om någor vill gå till rätta med dig, och taga din kjortel ifrå dig, låt honom ock hafva kåpona med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Och om någor nödgar dig ena milo, så gack två med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Gif honom, som af dig bedes, och vänd dig icke ifrå honom, som något vill låna af dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'I hafven hört, att det är sagdt: Du skall älska din nästa, och hata din fienda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Men jag säger eder: Älsker edra ovänner; välsigner dem som eder banna, och görer väl emot dem som eder hata; bedjer för dem som göra eder skada, och förfölja eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'På det I skolen vara edar Faders barn, som är i himmelen; ty han låter sina sol uppgå öfver onda och goda, och låter regna öfver rättfärdiga och orättfärdiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Förty, om I älsken dem som eder älska, hvad fån I för lön? Göra icke ock så de Publicaner det samma?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Om I hafven eder vänliga mot edra bröder allenast, hvad besynnerligit gören I? Göra icke ock så de Publicaner?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Varer fördenskull fullkomlige, såsom edar himmelske Fader fullkomlig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Hafver akt uppå edra almoso, att I icke gifven henne för menniskomen, på det I skolen varda sedde af dem; annars hafven I ingen lön när edar Fader, som är i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'När du nu gifver almoso, låt icke stöta i basun för dig, som de skrymtare göra i Synagogorna, och uppå gatorna, att de skola varda prisade af menniskomen; sannerliga säger jag eder, de hafva fått sin lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Men när du vill gifva almoso, så låt dina venstra hand icke veta, hvad den högra gör;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'På det din almosa blifver lönlig; och din Fader, som i löndom ser, vedergäller dig det uppenbarliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Och när du beder, skall du icke vara som de skrymtare; förty de stå gerna i Synagogorna och i gatohörnen och bedja, att de skola blifva sedde af menniskomen; sannerliga säger jag eder, de hafva fått sin lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Men när du beder, så gack in i din kammar, och slå dörrena till, och bed din Fader hemliga; och din Fader, som i löndom ser, skall dig det verdergälla uppenbarliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Och när I bedjen, skolen I icke vara mångtalige, såsom Hedningarna; ty de mena, att de skola varda hörde för sin många ords skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Varer fördenskull dem icke like; edar Fader vet väl hvad eder görs behof, förr än I bedjen honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Derföre skolen I bedja alltså: Fader vår, som äst i himlom, helgadt varde ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Tillkomme ditt rike; ske din vilje, såsom i himmelen, så ock på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Gif oss i dag vårt dagliga bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Och förlåt oss våra skulder, såsom ock vi förlåtom dem oss skyldige äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Och inled oss icke i frestelse; utan fräls oss ifrån ondo. Ty riket är ditt, och magten, och härligheten, i evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Ty om I förlåten menniskomen deras brott, så förlåter ock edar himmelske Fader eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Men om I icke förlåten menniskomen deras brott, så skall edar Fader icke heller förlåta eder edor brott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'När som I fasten, skolen I icke vara som I voren bedröfvade, såsom de skrymtare; ty de förvandla sin ansigte, att de skola synas för menniskomen med sin fasto; sannerliga säger jag eder, de hafva redo sin lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Men när du fastar, så smörj ditt hufvud, och två ditt ansigte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Att du icke synes för menniskomen med dine fasto, utan för din Fader, som lönligen är; och din Fader, som ser i löndom, vedergäller dig det uppenbarliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'I skolen icke församla eder ägodelar på jordene, der mal och rost förderfvar dem, och der som tjufvar grafva, och stjäla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Utan församler eder ägodelar i himmelen, der hvarken rost eller mal förderfvar dem, och der tjufvar icke grafva, eller stjäla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Ty der edre ägodelar äro, der är ock edart hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Kroppsens ljus är ögat; är ditt öga enfaldigt, så varder din hele kropp ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Men är ditt öga argt, så varder din hele kropp mörk. Är det nu så att ljuset, som är i dig, är mörker, huru stort blifver då mörkret sjelft?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Ingen kan tjena två herrar; ty att han antingen skall hata den ena, och den andra älska; eller han håller sig intill den ena, och den andra föraktar han; I kunnen icke tjena Gudi och Mammon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Derföre säger jag eder: Sörjer icke för edart lif, hvad I skolen äta och dricka; och icke för edar kropp, hvad I skolen kläda eder med. Är icke lifvet mer än maten, och kroppen mer än kläden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Ser uppå foglarna under himmelen; de så intet, och intet skära de heller upp, och församla intet i ladorna: och edar himmelske Fader föder dem. Ären I icke mycket mer än de?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Hvilken ibland eder är, som med sin omsorg förmår sätta en aln till sina längd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Och för hvars skull sörjen I för kläden? Skåder liljorna på markene, huru de växa; de arbeta intet, ej heller spinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Dock säger jag eder att icke Salomo, i all sin härlighet, var så klädd som en af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Kläder nu Gud så gräset på markene, hvilket dock i dag står, och i morgon kastas i ugnen, skulle han icke mycket mer göra det eder, o I klentrogne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Så skolen I nu icke hafva omsorg, sägande: Hvad skole vi äta? Eller, hvad skole vi dricka? Eller, hvad skole vi kläda oss med?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Ty allt sådant söka Hedningarna. Edar himmelske Fader vet väl, att allt detta göres eder behof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Söker först efter Guds rike, och hans rättfärdighet, så faller eder allt detta till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Sörjer icke fördenskull för morgondagen; ty morgondagen hafver sjelf sina omsorg med sig. Det är nog, att hvar dag hafver sin egen plågo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Dömer icke, på det I icke skolen varda dömde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Ty med den dom, som I dömen, skolen I dömde varda; och med det mått, som I mäten, skall eder mätet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Huru ser du ett grand i dins broders öga, och varder icke varse en bjelka i ditt öga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Eller, huru säger du dinom broder: Håll, jag vill taga ut grandet af ditt öga; och si, en bjelke är i ditt öga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Du skrymtare, kasta först ut bjelkan af ditt öga; sedan se till, huru du kan uttaga grandet af dins broders öga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'I skolen icke gifva hundomen det heligt är, och edra perlor skolen I icke kasta för svin, att de icke trampa dem med sina fötter, och vända sig om emot eder, och rifva eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Beder, och eder skall varda gifvet; söker, och I skolen finna; klapper, och eder skall upplåtas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Ty den som beder, han får; och den som söker, han finner; och honom, som klappar, varder upplåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Eller, hvilken är den menniska ibland eder, att om hans son bedes bröd af honom, som bjuder honom en sten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Eller, om han bedes fisk, månn han då räcka honom en orm?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Är det nu så att I, som onde ären, kunnen likväl gifva edor barn goda gåfvor, huru mycket mer varder edar Fader som är i himmelen, gifvandes dem godt, som bedas af honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Allt det I nu viljen menniskorna skola göra eder, det görer I ock dem; ty detta är lagen och Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Går in igenom den trånga porten; ty den porten är vid, och den vägen är bred, som drager till fördömelse; och de äro månge, som gå på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Och den porten är trång, och den vägen smal, som drager till lifvet; och få äro de, som finna honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Vakter eder för de falska Propheter, som komma till eder i fårakläder, men invärtes äro de glupande ulfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Utaf deras frukt skolen I känna dem; icke hemtar man vindrufvor af törne, ej heller fikon af tistel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Så bär hvart och ett godt trä goda frukt, men ett ondt trä bär onda frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Ett godt trä kan icke bära onda frukt; icke kan heller ett ondt trä bära goda frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Hvart och ett trä, som icke bär goda frukt, skall afhuggas, och kastas i elden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Derföre skolen I känna dem på deras frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Icke varder hvar och en kommandes in i himmelriket, som säger till mig: Herre, Herre; utan den som gör mins Faders vilja, som är i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'På den dagen varda månge sägande till mig: Herre, Herre, hafve vi icke propheterat uti ditt Namn, och i ditt Namn utdrifvit djeflar, och i ditt Namn många kraftiga gerningar gjort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Då skall jag bekänna dem: Jag kände eder aldrig; går ifrå mig, I ogerningsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Derföre, hvar och en som hörer dessa min ord, och gör derefter, honom liknar jag vid en vis man, som sitt hus byggde på ett hälleberg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Så föll slagregn, och kom flod, och vädret blåste, och stötte på huset, och föll dock icke omkull; ty det var grundadt på hälleberget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Och hvar och en, som hörer af mig dessa ord, och gör icke derefter, han liknas vid en fåvitsk man, som byggde sitt hus på sanden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Och föll slagregn, och kom flod, och vädret blåste, och stötte på huset; och det föll omkull, och dess fall var stort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Och det begaf sig, när Jesus lyktade detta talet, vardt folket förskräckt öfver hans lärdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Ty han predikade väldeliga, och icke som de Skriftlärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'När han nu gick neder af berget, följde honom mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Och si, der kom en spitelsk man, och tillbad honom, och sade: Herre, vill du, så kan du göra mig renan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Då räckte Jesus ut sina hand, och tog på honom, sägandes: Jag vill, var ren; och straxt vardt han ren utaf sin spitelsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Och Jesus sade till honom: Se till, att du säger det för ingom; utan gack bort, och låt Presten se dig, och offra den gåfvo, som Mose budit hafver, till ett vittnesbörd öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Men när Jesus gick in uti Capernaum, kom en höfvitsman till honom, och bad honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Sägandes: Herre, min tjenare ligger hemma borttagen, och hafver stor vedermödo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Då sade Jesus till honom: Jag vill komma, och bota honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Då svarade höfvitsmannen, och sade: Herre, jag är icke värdig, att du skall gå in under mitt tak; utan säg allenast ett ord, så blifver min tjenare helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Ty jag är ock en menniska under annars mans våld, och hafver krigsknektar under mig; och jag säger till den ena: Gack; och han går; och till den andra: Kom; och han kommer; och till min dräng: Gör det; och han gör så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'När Jesus detta hörde, förundrade han sig, och sade till dem, som honom följde: Sannerliga säger jag eder, jag hafver icke funnit sådana tro i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Men jag säger eder, att månge varda kommande af östan och vestan, och skola sitta med Abraham, Isaac och Jacob i himmelriket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Men riksens barn skola varda utkastade i det yttersta mörkret; der skall vara gråt och tandagnisslan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Och Jesus sade till höfvitsmannen: Gack, och som du tror, så ske dig; och i samma stundene blef hans tjenare helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Och när Jesus kom i Petri hus, och såg att hans svära låg, och hade skälfvosot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Då tog han på hennes hand, och skälfvosoten öfvergaf henne; och hon stod upp, och tjente dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Och när aftonen kom, hade de till honom många, som voro besatte; och han dref ut andarna med ord, och alla dem, som ondt hade, botade han;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'På det fullbordas skulle det som sagdt var genom Esaia Propheten, som säger: Han hafver tagit på sig våra skröplighet, och våra sjukdomar hafver han burit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Och när Jesus såg mycket folk omkring sig, böd han, att man skulle fara utöfver på hinsidon hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Och kom en Skriftlärd till honom, och sade till honom: Mästar, jag vill följa dig ehvart du går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Då sade Jesus till honom: Räfvarne hafva kulor, och foglarna under himmelen näste; men menniskones Son hafver intet, der han må luta sitt hufvud till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Och en annar af hans Lärjungar sade till honom: Herre, gif mig lof, att jag går först bort, och begrafver min fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Då sade Jesus till honom: Följ du mig, och låt de döda begrafva sina döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Och han steg i skeppet, och hans Lärjungar följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Och si, en stor storm växte upp i hafvet, så att vågen slog utöfver skeppet; och han sof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Då gingo Lärjungarna till, och väckte honom upp, sägande: Herre, fräls oss, vi förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Då sade han till dem: I klentrogne, hvi rädens I? Och stod upp, och näpste vädret, och hafvet; och det vardt stilla lugnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Men menniskorna förundrade sig, och sade: Hvad är denne för en, att vädret och hafvet äro honom lydig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Och när han kom på hinsidon hafvet, uti de Gergeseners landsändar, kommo två besatte med djefvulen emot honom löpande, utgångne af grifter; och voro ganska gräselige, så att ingen kunde resa den vägen fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Och si, de ropade, och sade: Ack! Jesu, Guds Son, hvad hafve vi med dig göra? Äst du kommen till att plåga oss förr än tid är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Så gick der långt ifrån en stor svinahjord i bet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Då bådo honom djeflarna, och sade: Är det så, att du drifver oss ut, så lofva oss, att vi farom uti den svinahjorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Då sade han till dem: Farer. Då foro de ut, och foro in i svinahjorden; och si, hele svinahjorden lopp, och brådstörte sig i hafvet, och drunknade i vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Men herdarne flydde bort, och gingo in i staden, och förkunnade alltsammans, och huru det var tillgånget med dem som besatte voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Och si, då gick hela staden ut emot Jesum; och då de sågo honom, bådo de att han ville gå bort utu deras landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Då steg han i skeppet, och for utöfver igen, och kom uti sin stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Och si, de hade in för honom en borttagnan, som låg uti ene säng. När nu Jesus såg deras tro, sade han till den borttagna: Var vid ett godt mod, min son, dina synder förlåtas dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Och si, somlige utaf de Skriftlärda sade vid sig sjelfva: Denne häder Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Men när Jesus såg deras tankar, sade han: Hvi tänken I ondt i edor hjerta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Hvilket är lättare säga: Dina synder förlåtas dig; eller säga: Statt upp, och gack?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Men på det I skolen veta, att menniskones Son hafver magt på jordene till att förlåta synder, sade han till den borttagna: Statt upp, tag dina säng, och gack i ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Och han stod upp, och gick hem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'När folket det såg, förundrade de sig, och prisade Gud, som sådana magt hade gifvit menniskom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Och när Jesus gick dädan, såg han en man sittandes vid tullen, som het Mattheus; och han sade till honom: Följ mig. Då stod han upp, och följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Och det begaf sig att, när han satt vid bord i hans hus, si, der kommo månge Publicaner och syndare, och såto till bords med Jesu och hans Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'När de Phariseer det sågo, sade de till hans Lärjungar: Hvi äter edar mästare med Publicaner och syndare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'När Jesus det hörde, sade han till dem: De helbregda behöfva icke läkare, utan de kranke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Men går, och lärer hvad det är: Jag hafver lust till barmhertighet, och icke till offer; jag är icke kommen till att kalla de rättfärdiga, utan syndare till bättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Då kommo till honom Johannis Lärjungar, och sade: Hvi faste vi och Phariseerna så mycket, och dine Lärjungar fasta intet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Då sade Jesus till dem: Huru kan bröllopsfolket sörja, så länge brudgummen är när dem? Men de dagar skola komma, att brudgummen skall tagas ifrå dem, och då skola de fasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Ingen lappar ett gammalt kläde med en ny klut; ty han rifver likväl kluten af klädena igen, och hålet blifver värre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Ej heller låter man nytt vin i gamla flaskor; annars gå flaskorna sönder, och vinet spilles ut, och flaskorna förderfvas; utan man låter nytt vin i nya flaskor, så blifver både förvarad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Vid han detta talade till dem, si, då kom en öfverste, och tillbad honom, och sade: Herre, min dotter är nu straxt blifven död; men kom, och lägg dina hand på henne, så blifver hon lefvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Jesus stod upp, och följde honom, och hans Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Och si, en qvinna, som hade lidit blodgång i tolf år, gick bakefter honom, och kom vid hans klädafåll;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Ty hon sade vid sig sjelf: Måtte jag allenast komma vid hans kläder, så blefve jag helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Då vände Jesus sig om, och som han såg henne, sade han: Var vid goda tröst, dotter, din tro hafver hulpit dig. Och qvinnan vardt helbregda i samma stund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Och när Jesus kom i öfverstans hus, och såg piparena, och folket sorlande,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Sade han till dem: Går edra färde; pigan är icke död, men hon sofver. Och de gjorde spe af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'När nu folket var utdrifvet, gick han in, och tog henne i handen; och pigan stod upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Och detta ryktet gick öfver det hela landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Och när Jesus gick dädan, följde honom två blinde; de ropade, och sade: O Davids Son, förbarma dig öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Och när han kom i huset, stego de blinde fram till honom; och Jesus sade till dem: Tron I, att jag kan detta göra eder? Då sade de till honom: Ja, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Då tog han på deras ögon, och sade: Ske eder efter edra tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Och deras ögon vordo öppnade; och Jesus hotade dem, sägandes: Ser till, att ingen får detta veta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Men de gingo ut, och beryktade honom i det hela landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'När desse voro utgångne, si, då hade de ena mennisko fram för honom, som var en dumbe och besatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Och när djefvulen var utdrifven, talade dumben. Och folket förundrade sig, och sade: Sådant hafver aldrig varit sedt i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Men de Phariseer sade: Med den öfversta djefvulen drifver han djeflar ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Och Jesus gick omkring i alla städer och byar, lärde i deras Synagogor, och predikade Evangelium om riket, och helade allahanda sjuko, och allahanda krankhet ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Och när han såg folket, ömkade han sig öfver dem, att de voro förlåtne och förskingrade, som de får som ingen herdan hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Då sade han till sina Lärjungar: Säden är mycken, och arbetarena äro få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Beder fördenskull sädenes Herra, att han sänder arbetare i sina säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Och han kallade sina tolf Lärjungar till sig, och gaf dem magt öfver de orena andar, att de skulle drifva dem ut, och bota allahanda sjukdom och allahanda krankhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Men dessa äro de tolf Apostlars namn: Den förste, Simon, som kallas Petrus, och Andreas, hans broder; Jacobus, Zebedei son, och Johannes, hans broder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippus och Bartholomeus; Thomas och Mattheus, som hade varit en Publican; Jacobus, Alphei son, och Lebbeus, med det vedernamnet Thaddeus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon af Cana, och Judas Ischarioth, den ock förrådde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Dessa tolf sände Jesus ut, och böd dem, och sade: Går icke på Hedningarnas väg, och går icke i de Samariters städer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Utan går heldre till de borttappade får af Israels hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Men går, och prediker, och säger: Himmelriket är kommet hardt när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Görer de sjuka helbregda, de spitelska rena; reser upp de döda; utdrifver djeflar. I hafven fått förgäfves, så skolen I ock gifva förgäfves.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Hafver icke guld, icke heller silfver, icke heller penningar i edra pungar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Och inga vägskräppo, och icke två kjortlar, icke skor, och ingen staf; ty arbetaren är värd sin mat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Men hvar I gån in uti en stad eller by, så bespörjer om der någor inne är, som dess värdig är; och blifver der, tilldess I dragen dädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Men när I gån in i ett hus, så helser det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Och är det så, att det huset är värdigt, så kommer edar frid öfver det; är det ock icke värdigt, så kommer edar frid till eder igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Och der som ingen anammar eder, eller hörer edor ord, så går utaf det huset eller staden, och skudder stoftet utaf edra fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Sannerliga säger jag eder: Sodome och Gomorre land varder drägeligare på domedag, än dem stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Si, jag sänder eder såsom får ibland ulfvar; varer fördenskull snälle såsom ormar, och enfaldige som dufvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Men vakter eder för menniskomen: ty de skola öfverantvarda eder på sin Rådhus, och uti deras Synagogor skola de hudflänga eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Och I skolen varda framdragne för Förstar och Konungar, för mina skull, till vittnesbörd öfver dem, och öfver Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Och när som de nu öfverantvarda eder, så varer icke bekymrade, huru eller hvad I skolen tala; ty det skall eder gifvas i samma stundene, hvad I tala skolen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Förty det ären icke I, som talen, utan det är edar Faders Ande, som talar i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Den ene brodren skall öfverantvarda den andra till döden, och fadren sonen; och barnen skola sätta sig upp emot föräldrarna, och dräpa dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Och I skolen varda hatade af allom, för mitt Namns skull; men hvilken som står fast uti ändan, han skall blifva salig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'När de förfölja eder i den ena staden, så flyr till den andra. Sannerliga säger jag eder: I skolen icke hafva orkat fara omkring alla Israels städer, förrän menniskones Son kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Lärjungen är icke öfver mästaren; och icke heller tjenaren öfver sin herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Det är Lärjunganom nog, att han är såsom hans mästare, och tjenarenom, att han är såsom hans herre. Hafva de kallat husbonden Beelzebub, huru mycket mer skola de så kalla hans husfolk?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Rädens fördenskull intet för dem; ty det är intet fördoldt, som icke skall varda uppenbaradt; och intet lönligit, som icke skall blifva vetterligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Hvad jag säger eder i mörkret, det säger i ljuset; och hvad som sägs eder i örat, det prediker på taken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Och rädens icke för dem, som dräpa kroppen, och hafva dock icke magt att dräpa själena; utan rädens mer honom, som kan förderfva både själ och kropp i helvete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Säljas icke två sparfvar för en skärf? Och en af dem faller icke på jordena, edar Fader förutan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Äro ock edor hufvudhår all räknad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Derföre skolen I icke rädas; I ären ju mer värde än månge sparfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Derföre, hvar och en som mig bekänner för menniskom, honom vill jag ock bekänna för min Fader, som är i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Men den som mig vedersakar för menniskom, honom skall jag ock vedersaka för min Fader, som är i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'I skolen icke mena, att jag är kommen till att sända frid på jordena; jag är icke kommen till att sända frid, utan svärdet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Ty jag är kommen till att göra menniskona skiljaktiga mot sin fader, och dottrena mot sina moder, och sonahustruna mot sina sväro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'Och menniskones eget husfolk varda hennes fiender.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Hvilken som älskar fader och moder mer än mig, han är mig icke värd; och hvilken som älskar son eller dotter mer än mig, han är mig icke värd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Och hvilken som icke tager sitt kors på sig och följer mig, han är mig icke värd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Hvilken som finner sitt lif, han skall borttappa det; och hvilken som borttappar sitt lif, för mina skull, han skall finna det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Hvilken som eder anammar, han anammar mig; och hvilken som mig anammar, han anammar honom som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Hvilken som anammar en Prophet, i ens Prophets namn, han skall få ens Prophets lön; och hvilken som anammar en rättfärdig, i ens rättfärdigs namn, han skall få ens rättfärdigs lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Och hvilken som gifver enom af dessa minsta en bägare kallt vatten dricka allenast, i ens Lärjungas namn, sannerliga säger jag eder, det skall icke blifva honom olönt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Och det begaf sig, när Jesus sådana bud till sina tolf Lärjungar fullkomnat hade, gick han dädan fram bätter, på det han skulle lära, och predika i deras städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'När Johannes, som då var i fängelset, hörde Christi gerningar, sände han två sina Lärjungar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Och lät säga honom: Äst du den som komma skall, eller skolom vi förbida någon annan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Då svarade Jesus, och sade till dem: Går, och säger Johanni igen, hvad I hafven hört och sett:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'De blinde se, de halte gå, de spitelske göras rene, och de döfva höra; de döde resas upp, och dem fattigom varder predikadt Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Och salig är den, som icke varder förargad i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'När som de gingo bort, begynte Jesus tala till folket om Johanne: Hvad gingen I ut i öknena till att se? Villen I se en rö, som drifs hit och dit af vädret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Eller hvad gingen I ut till att se? Villen I se ena mennisko i len kläder? Si, de som draga len kläder äro i Konungahusen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Eller hvad gingen I ut till att se? Villen I se en Prophet? Ja, jag säger eder, mer än en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Ty han är den samme, om hvilken skrifvet är: Si, jag sänder min Ängel för ditt ansigte, hvilken skall tillreda din väg för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Sannerliga säger jag eder: Ibland dem, som äro födde af qvinnor, är ingen uppkommen, som är större än Johannes Döparen; dock likväl, den som är minst i himmelriket, han är större än han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Men ifrå Johannis Döparens dagar, och till denna dagen, lider himmelriket våld; och de väldige rifva det till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Ty alle Propheterna och lagen hafva spått intill Johannem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Och om I viljen anammat, han är Elias, som komma skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Den som hafver öron till att höra, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Men vid hvem skall jag likna detta slägtet? Det är likt barnom, som uppå torget sitta, och ropa till sina stallbröder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Och säga: Vi hafve pipat för eder, och I villen intet dansa; vi hafve sjungit sorgesång till eder, och I villen intet gråta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Johannes är kommen, och hvarken åt eller drack; och de säga: Han hafver djefvulen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Menniskones Son är kommen, äter och dricker; och de säga: Si, hvilken fråssare och vindrinkare är den mannen, Publicaners och syndares vän. Och visdomenom varder rätt gifvet utaf sinom barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Då begynte han till att förvita de städer, i hvilkom han hade gjort sina mesta krafter, och de hade likväl intet bättrat sig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Ve dig, Chorazin, ve dig, Bethsaida; ty hade sådana krafter varit gjorda i Tyro och Sidon, som i eder gjorda äro, de hade långo uti säck och asko gjort syndabättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Dock säger jag eder, att Tyro och Sidoni skall drägeligare varda på domedag, än eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Och du Capernaum, som äst upphöjd allt intill himmelen, du skall blifva nederstött allt intill helvete; förty hade sådana krafter skett i Sodoma, som i dig skedde äro, det hade stått än i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Dock säger jag eder: De Sodomeers lande skall drägeligare varda på domedag än dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'I den tiden svarade Jesus, och sade: Jag prisar dig, Fader, himmelens och jordenes Herre, att du hafver detta dolt för de visa och förnumstiga, och hafver det uppenbarat för de fåkunniga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Ja, Fader, så hafver varit behageligit för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'All ting äro gifven mig i våld af minom Fader; och ingen känner Sonen, utan Fadren; och ingen heller känner Fadren, utan Sonen, och den som Sonen vill det uppenbara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Kommer till mig, I alle, som arbeten, och ären betungade; och jag vill vederqvicka eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Tager på eder mitt ok, och lärer af mig; ty jag är mild och ödmjuk af hjertat; och I skolen finna ro till edra själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Ty mitt ok är lustigt, och min börda är lätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'I den tiden gick Jesus genom säd på Sabbathen; och hans Lärjungar voro hungrige, och begynte upprycka ax, och äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'När de Phariseer det sågo, sade de till honom: Si, dine Lärjungar göra det som icke lofligit är göra på Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Men han sade till dem: Hafven I icke läsit hvad David gjorde, när han, och de som med honom voro, hungrade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Huru han gick in i Guds hus, och åt skådobröden, som honom icke var lofligit äta; icke heller dem, som med honom voro, utan allenast Prestomen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Eller hafven I icke läsit i lagen, att på Sabbathen bryta Presterna Sabbathen i templet; och äro likväl utan skuld?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Men jag säger eder, att här är den som är mer än templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Men vissten I hvad det vore: Jag hafver lust till barmhertighet, och icke till offer, då dömden I icke de oskyldiga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Ty menniskones Son är en Herre, desslikes ock öfver Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Då gick han dädan fram bätter, och kom i deras Synagogo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Och si, der var en man, som hade ena bortvissnada hand; och de sporde honom, sägande: Må man ock hela om Sabbathen? på det de måtte anklaga honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Då sade han till dem: Hvilken är den menniska ibland eder, som hafver ett får, och om det faller i gropena om Sabbathen, går han icke och fattar uti det, och drager det upp?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Huru mycket bättre är nu en menniska än ett får? Derföre må man ju göra väl på Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Och sade han till mannen: Räck ut dina hand; och han uträckte henne; och hon vardt färdig igen, såsom den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Då gingo de Phariseer ut, och lade råd emot honom, huru de måtte förgöra honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Men när Jesus det förnam, gick han dädan; och honom följde mycket folk, och han gjorde dem alla helbregda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Och hotade dem, att de icke skulle uppenbara honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'På det fullkomnas skulle det som sagdt var genom Propheten Esaias, som sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Si, min tjenare, den jag utvalt hafver; min käreste, i hvilkom min själ hafver ett godt behag; jag skall sätta min Anda på honom, och han skall förkunna Hedningomen domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Han skall icke kifva eller ropa, och hans röst skall man icke höra på gatomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Den rö, som krossad är, skall han icke sönderbryta; och vekan, som ryker, skall han icke utsläcka, tilldess han utförer domen till en seger;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Och i hans Namn skola Hedningarna hoppas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Då hades fram till honom en, som var besatt med djefvulen, han var blind och dumbe; den gjorde han helbregda, så att samme blinde och dumbe både talade och såg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Och allt folket blef förskräckt, och sade: Är denne icke Davids Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Men när de Phariseer det hörde, sade de: Han utdrifver icke djeflar, utan med Beelzebub, djeflarnas öfversta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Då nu Jesus förstod deras tankar, sade han till dem: Hvart och ett rike, som är tvedrägtigt emot sig sjelft, det blifver öde; och hvar och en stad, eller hus, som är tvedrägtigt emot sig sjelft, blifver icke ståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Är det nu så, att Satan drifver Satan ut, då är han tvedrägtigt emot sig sjelf; huru blifver då hans rike beståndandes?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Och är det så, att jag drifver djeflar ut med Beelzebub, med hvem drifva då edor barn dem ut? Derföre skola de vara edra domare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Men är det så, att jag drifver djeflar ut med Guds Anda, då är ju Guds rike kommet till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Eller, huru kan någor gå i ens mägtigs mans hus, och beröfva honom hans boting bort, utan han först binder den mägtiga, och så sedan skinnar hans hus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Hvilken som icke är med mig, han är emot mig; och hvilken som icke församlar med mig, han förskingrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Fördenskull säger jag eder: All synd och försmädelse blifver menniskomen förlåten; men försmädelse mot Andan skall icke blifva menniskomen förlåten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Och hvilken som säger något emot menniskones Son, det varder honom förlåtet: men hvilken som säger något emot den Helga Anda, det varder honom icke förlåtet, hvarken i denna, eller i den tillkommande verld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Görer antingen trät godt, så varder frukten god; eller ock görer trät ondt, så varder frukten ond; ty af fruktene känner man trät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'I huggormars afföda, huru kunnen I tala något godt, medan I ären sjelfve onde? Ty der hjertat med fullt är, deraf talar munnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'En god menniska bär godt fram af hjertans goda fatabur; och en ond menniska bär ondt fram af en ond fatabur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Men jag säger eder, att för hvart och ett fåfängt ord, som menniskorna tala, skola de göra räkenskap på domedag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Ty af din ord skall du blifva rättfärdig hållen, och af din ord skall du varda fördömd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Då svarade någre utaf de Skriftlärda och de Phariseer, och sade: Mästar, vi vilje se tecken af dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Svarade han, och sade till dem: Detta vrånga och horiska slägtet söker efter tecken; och thy skall intet tecken gifvas, annat än Jone Prophetens tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Ty såsom Jonas var i tre dagar och tre nätter i hvalfiskens buk; så skall menniskones Son vara i tre dagar och i tre nätter i jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'De Ninivitiske män skola stå upp på domen med detta slägtet, och fördöma det; ty de bättrade sig efter Jone predikan; och si, här är mer än Jonas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Drottningen af söderlanden skall stå upp på domen med detta slägtet, och fördöma det; ty hon kom ifrå jordenes ända, till att höra Salomons visdom; och si, här är mer än Salomon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'När den orene anden är utfaren af menniskone, så vandrar han genom de rum, som torr äro, söker efter hvilo, och finner ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Så säger han: Jag vill komma igen i mitt hus, der jag utgick; och när han kommer, finner han det tomt, och rent sopadt, och prydt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Så går han bort, och tager sju andra andar till sig, de som värre äro än han sjelfver; och då de der inkomma, bo de der; så blifver den menniskones sista värre än det första. Så varder ock tillgångandes med detta vrånga slägtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Vid han ännu talade till folket, si, hans moder och bröder stodo utanföre, och ville tala med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Då sade en till honom: Si, din moder och dine bröder stå ute, och vilja tala med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Då svarade han, och sade till den, som honom bådade: Hvilken är min moder, och hvilke äro mine bröder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Och räckte ut handena åt sina Lärjungar, och sade: Si, min moder och mine bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Ty hvar och en, som gör mins Faders vilja, som är i himmelen, han är min broder, och syster, och moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'På den dagen gick Jesus ut af huset, och satte sig utmed hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Och der församlades mycket folk till honom, så att han steg uti ett skepp, och satte sig; och allt folket stod på strandene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Och han talade med dem mångahanda i liknelser, sägandes: Si, en sädesman gick ut, och skulle så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Och när han sådde, föll somt vid vägen; och kommo foglarna, och åto det upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Somt föll på stenören, der det hade icke mycken jord; och gick snart upp, ty det hade icke djupa jord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Men när solen gick upp, förvissnade det; och efter det hade inga rötter, torkades det bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Och somt föll ibland törne; och törnebuskarna uppväxte, och förqvafde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Och somt föll i goda jord, och gjorde frukt; somt hundradefaldt, somt sextiofaldt, och somt tretiofaldt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Hvilken som hafver öron till att höra, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Då stego Lärjungarna fram, och sade till honom: Hvi talar du till dem med liknelser?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Då svarade han dem, och sade: Eder är gifvet att veta himmelrikets lönlighet; men dem är det icke gifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Ty hvilken som hafver, honom skall gifvas, att han skall nog hafva; men den som icke hafver, af honom skall ock varda taget det han hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Fördenskull talar jag dem till med liknelser; ty med seende ögon se de intet, och med hörande öron höra de intet; ty de förståt icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Och på dem varder fullkomnad Esaie Prophetie, som säger: Med öronen skolen I höra, och skolen icke förståt; och med seende ögon skolen I se, och skolen icke förnimmat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Ty detta folks hjerta är förstockadt, och deras öron höra illa, och deras ögon hafva de igenlyckt; på det de icke ens skulle se med ögonen, och höra med öronen, och förståt med hjertat, och omvända sig, att jag måtte hela dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Men salig äro edor ögon, att de se, och edor öron, att de höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Sannerliga säger jag eder, att månge Propheter och rättfärdige hafva begärat se det I sen, och fingo dock icke set, och höra det I hören, och fingo dock icke hörat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Så hörer nu I denna liknelsen om sädesmannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Hvar någor hörer ordet om riket, och förstår det icke, så kommer den onde, och rifver det bort, som sådt är i hans hjerta; det är den som vid vägen sådder var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Men den som var sådder på stenören, är den som hörer ordet, och tager det straxt gladeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Men han hafver ingen rot i sig sjelf, utan står till en tid; och när bedröfvelsen och förföljelsen påkomma för ordets skull, straxt förargas han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Men den som var sådder ibland törne, är den som hörer ordet; och desse verldenes bekymmer, och rikedomsens svek förqväfver ordet; och han blifver utan frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Men den som var sådder i goda jord, är den som hörer ordet, och förstår det; och bär också frukt, så att somt gör hundradefaldt, somt sextiofaldt, och somt tretiofaldt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'En annor liknelse satte han dem före, och sade: Himmelriket är likt ene mennisko, som sådde goda säd i sin åker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Men då folket sof, kom hans ovän, och sådde ogräs midt ibland hvetet; och gick sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Då nu säden växte, och bar frukt, syntes ock ogräset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Då gingo husbondans tjenare fram, och sade till honom: Herre, sådde du icke goda säd i din åker? Hvadan hafver han då ogräs?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Då sade han till dem: Det hafver ovännen gjort. Sade tjenarena till honom: Vill du, att vi gåm, och hemte det bort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Då sade han: Nej, på det att, när I upprycken ogräset, I icke skolen ock dermed upprycka hvetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Låter båda växa intill skördetiden; och i skördetiden vill jag säga skördemännomen: Hemter först ogräset samman, och binder det i knippor, till att uppbrännas; men hvetet församler i mina lado.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'En annor liknelse satte han dem före, och sade: Himmelriket är likt ett senapskorn, som en man tog, och sådde i sin åker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Hvilket minst är af all frö; men när det varder uppväxt, är det störst ibland krydder, och blifver ett trä, så att foglarna under himmelen komma, och göra sin näste på dess qvistar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'En annor liknelse sade han till dem: Himmelriket är likt enom surdeg, hvilken en qvinna tog, och blandade i tre skeppor mjöl, tilldess det blef alltsammans surt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Detta allt talade Jesus i liknelser till folket; och utan liknelse talade han intet till dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Att det skulle fullkomnas, som sagdt var genom Propheten som sade: Jag skall öppna min mun i liknelser, och skall uttala det hemligit varit hafver ifrå verldenes begynnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Då skiljde Jesus folket ifrå sig, och kom hem. Och hans Lärjungar stego fram till honom, och sade: Uttyd oss denna liknelsen om åkrens ogräs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Då svarade han, och sade till dem: Menniskones Son är den som den goda sädena sår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Åkren är verlden; den goda säden äro riksens barn; ogräset äro hins ondas barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Ovännen, som sådde, är djefvulen; skördetiden är verldenes ände; skördemännerna äro Änglarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Såsom nu ogräset hemtas samman, och brännes upp med eld, så skall det ske på denna verldenes ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Menniskones Son skall sända sina Änglar, och de skola församla all förargelse utaf hans rike, och dem som illa göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'Och skola kasta dem uti en brinnande ugn; der skall vara gråt och tandagnisslan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Då skola de rättfärdige skina såsom solen i deras faders rike. Hvilken öron hafver till att höra, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Åter är himmelriket likt enom skatt, som fördold var uti en åker, hvilken en man fann, och fördolde honom; och af rätto glädje, som han hafver deraf, går han bort, och säljer allt det han hafver, och köper den åkren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Åter är himmelriket likt enom köpman, som sökte efter goda perlor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Och när han hade funnit ena kosteliga perlo, gick han bort, och sålde allt det han ägde, och köpte henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Åter är himmelriket likt ene not, som kastades i hafvet, och församlade allahanda fiskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Och när hon vardt full, drogo de henne till lands, och såto så och hemte ut de goda i sin käril; men de onda kastade de bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Så skall det ock ske på verldenes ända: Änglarna skola utgå, och skilja de onda ifrå de rättvisa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'Och kasta dem i en brinnande ugn; der skall vara gråt och tandagnisslan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Då sade Jesus till dem: Förstoden I detta allt? Sade de till honom: Ja, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Då sade han till dem: Derföre, hvar och en Skriftlärd, som till himmelriket lärd är, han är lik en husbonda, som af sin fatabur bär fram nytt och gammalt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Och det begaf sig, när Jesus hade lyktat dessa liknelser, gick han dädan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Och kom i sitt fädernesland, och lärde i deras Synagogo, så att de ock förundrade sig storliga, och sade: Hvadan kommer denne sådana visdom och krafter?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Är han icke en timbermans son? Heter icke hans moder Maria; och hans bröder, Jacob, och Joses, och Simon, och Judas?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Och hans systrar, äro de icke alla när oss? Hvadan kommer honom då allt detta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Och de förargades öfver honom. Men Jesus sade till dem: En Prophet är icke föraktad, utan i sitt fädernesland, och i sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Och han gjorde der icke mång tecken, för deras otros skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'I den tiden hörde Herodes Tetrarcha Jesu rykte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Och sade till sina tjenare: Denne är Johannes Döparen; han är uppstånden ifrå de döda, derföre gör han sådana krafter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Ty Herodes hade gripit Johannem, bundit och lagt honom i häktelse, för Herodias, sins broders Philippi hustrus, skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Förty Johannes hade sagt till honom: Dig är icke lofligit hafva henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Och han hade gerna dräpit honom; men han räddes för folket; ty de höllo honom för en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'När då Herodes begick sin födelsedag, dansade Herodias dotter för dem; och det behagade Herodi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Derföre lofvade han henne vid en ed, att han ville gifva henne hvad hon begärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Då sade hon, såsom hennes moder hade lärt henne tillförene: Gif mig här på ett fat Johannis Döparens hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Och Konungen blef bedröfvad; dock för edens skull, och för deras skull, som såto öfver bord med honom, böd han att det skulle gifvas henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Och sände bort, och lät afhugga Johannis hufvud i häktelset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Och hans hufvud vardt framburet på ett fat, och gifvet pigone; och hon bar det till sina moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Och hans Lärjungar kommo, och togo hans lekamen, och begrofvo honom; och gingo sedan bort, och förkunnade det Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'När Jesus det hörde, for han dädan med skepp afsides bort uti en ödemark. När folket det hörde, kommo de efter honom till fot ifrå städerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Och Jesus gick ut, och såg det myckna folket, och varkunnade sig öfver dem, och gjorde deras kranka helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Och när det led åt aftonen, gingo hans Lärjungar till honom, och sade: Här är en ödemark, och tiden är förliden; låt folket gå ifrå dig, att de må gå bort i byarna, och köpa sig mat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Då sade Jesus till dem: Det görs icke behof att de bortgå; gifver I dem äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Då sade de till honom: Vi hafve här icke mer än fem bröd och två fiskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Sade han: Tager mig dem hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Och han böd folket sätta sig ned på gräset; och tog de fem bröd och de två fiskar, såg upp i himmelen, och tackade; bröt det, och gaf Lärjungomen bröden, och Lärjungarna gåfvo så folken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Och de åto alle, och vordo mätte. Och de togo upp det öfver var i styckom, tolf korgar fulla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Och de som ätit hade voro vid femtusend män, förutan qvinnor och barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Och straxt dref Jesus sina Lärjungar, att de skulle stiga i skeppet, och fara framföre utöfver, så länge han skiljde folket ifrå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Och när han hade skiljt folket ifrå sig, gick han upp på ett berg allena, till att bedja; och när aftonen kom, var han der allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Men skeppet var då allaredo midt på hafvet, och led plats i vågene; förty vädret var emot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Men i den fjerde väktene om natten kom Jesus till dem, gångandes på hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Och när Lärjungarna sågo honom gå på hafvet, vordo de förfärade och sade: Det är ett spökelse; och ropade af räddhåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Men Jesus talade dem straxt till, och sade: Varer vid ett godt mod; det är jag, varer icke förfärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Då svarade honom Petrus, och sade: Herre, äret du, så bjud mig komma till dig uppå vattnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Då sade han: Kom. När Petrus då steg utaf skeppet, begynte han gå på vattnet, att han skulle komma till Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Men när han såg att vädret var starkt, vardt han förfärad; och som han begynte sjunka, ropade han, och sade: Herre, hjelp mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Och straxt räckte Jesus ut handena, och fattade uti honom, och sade till honom: O du klentrogne, hvi tviflade du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Och när de voro inkomne i skeppet, stillade vädret sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Men de som voro i skeppet gingo fram, och tillbådo honom, och sade: Visserliga äst du Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Och när de voro öfverfarne, kommo de uti det landet Genesaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Och när folket dersammastäds förnummo honom, sände de båd i hela landet deromkring, och hade alla sjuka till honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'Och bådo honom, att de måtte allenast taga på hans klädafåll; och de, som togo deruppå, blefvo alle helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Då kommo till Jesum de Skriftlärde, och de Phariseer af Jerusalem, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Hvi bryta dina Lärjungar de äldstas stadgar? Förty de två intet sina händer, när de skola äta bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Han svarade, och sade till dem: Hvi bryten ock I Guds bud, för edra stadgars skull?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Ty Gud hafver budit, och sagt: Du skall ära fader och moder; och hvilken som bannar fader eller moder, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Men I sägen: Hvar och en må säga till fader eller moder: Det är allt Gudi gifvet, som du skulle få af mig, dig till nytto. Dermed sker då, att ingen hedrar sin fader eller sina moder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Och hafven dermed gjort Guds bud till intet, för edra stadgars skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'I skrymtare, Esaias hafver rätt spått om eder, sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Detta folket nalkas mig med sin mun, och hedrar mig med sina läppar; men deras hjerta är långt ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Men de tjena mig fåfängt, lärande den lärdom som är menniskobud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Och han kallade till sig folket, och sade till dem: Hörer, och förstår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Det besmittar icke menniskona, som ingår genom munnen; utan det, som utgår af munnen, det besmittar menniskona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Då stego hans Lärjungar fram, och sade till honom: Vetst du, att Phariseerna förargades, när de hörde detta ordet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Han svarade, och sade: Hvar och en plantering, som min himmelske Fader icke planterat hafver, skall uppryckas med rötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Låter fara dem; de äro blinde, och blindas ledare; hvar nu en blinder leder en blindan, så falla de både i gropena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Då svarade Petrus, och sade till honom: Uttyd oss denna liknelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Då sade Jesus: Ären I ock ännu oförståndige?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Förstån I icke ännu, att allt det, som ingår genom munnen, det går i buken, och hafver sin naturliga utgång?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Men det, som går ut af munnen, det kommer ifrå hjertat; och det besmittar menniskona;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Ty af hjertat utgå onda tankar, mord, hor, skörlefnad, tjufveri, falsk vittne, hädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Det äro de stycke, som besmitta menniskona; men äta med otvagna händer, besmittar icke menniskona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Och Jesus gick dädan, och kom i Tyri och Sidons landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Och si, en Cananeisk qvinna kom af de landsändar, och ropade till honom, och sade: O Herre, Davids Son, förbarma dig öfver mig; min dotter qväljs jämmerliga af djefvulen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Men han svarade henne icke ett ord. Då stego hans Lärjungar fram, och bådo honom, och sade: Skilj henne ifrå dig; ty hon ropar efter oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Men han svarade, och sade: Jag är icke utsänd, utan till de borttappada får af Israels hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Men hon kom, och tillbad honom, sägandes: Herre, hjelp mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Då svarade han, och sade: Det är icke höfveligit att taga brödet ifrå barnen, och kasta det för hundarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Svarade hon: Ja, Herre; dock likväl äta hundarna af de smulor, som falla utaf deras herrars bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Då svarade Jesus, och sade till henne: O qvinna, din tro är stor; ske dig som du vill. Och hennes dotter blef helbregda i samma stund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Och Jesus gick dädan länger fram, och kom till det Galileiska hafvet; och gick upp på ett berg, och satte sig der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Och till honom kom mycket folk, och hade med sig halta, blinda, dumbar, lemmalösa och många andra, och kastade dem för Jesu fötter; och han gjorde dem helbregda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Så att folket förundrade sig, när de sågo de dumbar tala, de lemmalösa färdiga, de halta gå, de blinda se; och prisade Israels Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Och Jesus kallade sina Lärjungar till sig, och sade: Jag ömkar mig öfver folket; ty de hafva nu i tre dagar töfvat när mig, och hafva intet äta; och jag vill icke låta dem ifrå mig fastande, att de icke skola gifvas upp i vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Då sade hans Lärjungar till honom: Hvar skole vi få här i öknene så mycket bröd, der vi kunne mätta så mycket folk med?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Sade Jesus till dem: Huru mång bröd hafven I? De sade: Sju, och några små fiskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Då böd han folket sätta sig ned på jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Och tog de sju bröd och fiskarna, tackade, bröt, och gaf sina Lärjungar; och Lärjungarna gåfvo folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Och de åto alle, och vordo mätte; och upptogo det öfver var i styckom, sju korgar fulla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Och de som åto voro fyratusend män, förutan qvinnor och barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Och när han hade skiljt folket ifrå sig, steg han till skepps, och kom uti den gränson vid Magdala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Då stego de Phariseer och Sadduceer fram, och frestade honom, begärandes att han ville låta dem se tecken af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Men han svarade, och sade till dem: Om aftonen sägen I: Det blifver klart väder; förty himmelen är röd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Och om morgonen: Det blifver oväder i dag; ty himmelen är röd och olustig. I skrymtare, om himmelens skepelse kunnen I döma; kunnen I ock icke döma om tidsens tecken?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Det vrånga och horiska slägtet söker efter tecken; och tecken skall icke gifvas dem, utan Jone Prophetens tecken. Och så öfvergaf han dem, och gick sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Och när hans Lärjungar voro komne utöfver på den andra stranden, hade de förgätit taga bröd med sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Då sade Jesus till dem: Ser till, och förvarer eder för de Phariseers och Sadduceers surdeg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Då tänkte de vid sig sjelfva, och sade: Vi hafve intet bröd tagit med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'När Jesus det förnam, sade han till dem: I klentrogne, hvad bekymrar det dock eder, att I icke hafven tagit bröd med eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Förstån I icke ännu, eller minnens, om de fem bröd emellan de femtusend män, och huru många korgar I upptogen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Icke heller om de sju bröd emellan de fyratusend män, och huru många korgar I då upptogen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Huru kommer det då till, att I icke kunnen förstå, att jag icke sade eder om bröd, (då jag sade:) I skolen förvara eder för de Phariseers och Sadduceers surdeg?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Så förstodo de då, att han hade icke budit dem taga sig vara för bröds surdeg, utan för de Phariseers och Sadduceers lärdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Då kom Jesus i den ängden Cesarea Philippi, och frågade sina Lärjungar, och sade: Hvem säger folket mig, menniskones Son, vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Då sade de: Somlige Johannem Döparen, somlige Eliam, somlige Jeremiam, eller en af Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Sade han till dem: Hvem sägen I mig då vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Då svarade Simon Petrus, och sade: Du äst Christus, lefvandes Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Då svarade Jesus, och sade till honom: Salig äst du, Simon, Jone son; ty kött och blod hafver dig det icke uppenbarat; utan min Fader, som är i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Och jag säger dig igen, att du äst Petrus; och uppå detta hälleberget skall jag bygga mina församling; och helvetes portar skola icke varda henne öfvermägtige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Och jag skall gifva dig himmelrikets nycklar. Allt det du binder på jordene, det skall vara bundet i himmelen; och allt det du löser på jordene, det skall vara löst i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Då böd han sina Lärjungar, att de skulle för ingen säga, att han var Jesus Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Ifrå den tiden begynte Jesus förkunna sina Lärjungar, huru han måste gå till Jerusalem, och lida mycket af de äldsta, och af de öfversta Presterna, och af de Skriftlärda; och dräpas, och tredje dagen uppstå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Och Petrus tog honom afsides, och begynte straffa honom, och sade: Herre, skona dig sjelf; detta vederfares dig icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Då vände han sig om, och sade till Petrum: Gack bort ifrå mig, du Satan; du äst mig till hinders; ty du besinnar icke det Gudi tillhörer, utan det menniskom tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Då sade Jesus till sina Lärjungar: Hvilken som vill följa mig, han vedersake sig sjelf, och tage sitt kors uppå sig, och följe mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Ty hvilken som vill behålla sitt lif, han skall mista det; och hvilken som mister sitt lif, för mina skull, han skall finna det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Hvad hjelper nu det menniskone, om hon förvärfvar hela verldena, och får dock skada till sin själ? Eller hvad kan menniskan gifva, der hon kan igenlösa sin själ med?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Förty det skall ske, att menniskones Son skall komma i sins Faders härlighet, med sina Änglar; och då skall han löna hvarjom och enom efter hans gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Sannerliga säger jag eder: Här äro någre ståndande, som icke skola smaka döden, tilldess de få se menniskones Son komma i sitt rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Och sex dagar derefter tog Jesus Petrum, och Jacobum, och Johannem, hans broder, till sig; och hade dem afsides upp på ett högt berg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Och vardt förklarad för dem; och hans ansigte sken som solen, och hans kläder voro hvit som ett ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Och si, dem syntes Mose, och Elias, talande med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Då svarade Petrus, och sade till Jesum: Herre, här är oss godt vara; vill du, så vilje vi här göra tre hyddor; dig ena, och Mosi ena, och Elie ena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Vid han ännu talade, si, en ljus sky omskyggde dem; och si, en röst utur skyn sade: Denne är min käre Son, i hvilkom jag hafver ett godt behag; honom hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Och när Lärjungarna det hörde, föllo de på sitt ansigte, och vordo svårliga förfärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Men Jesus gick till, och tog på dem, och sade: Står upp, och rädens icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Men då de upplyfte sin ögon, sågo de ingen, utan Jesum allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Och när de gingo ned af berget, böd Jesus dem, och sade: Säger för ingen denna synena, tilldess menniskones Son är uppstånden ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Och frågade honom hans Lärjungar, och sade: Hvi säga då de Skriftlärda, att Elias måste komma tillförene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Jesus svarade, och sade till dem: Elias skall ju komma först, och skicka all ting i lag igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Men jag säger eder: Elias är allaredo kommen, och de kände honom intet; utan gjorde honom hvad de ville. Sammalunda skall ock menniskones Son lida af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Då förstodo Lärjungarna, att han sade dem om Johanne Döparen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Och när de kommo till folket, steg en man fram, böjde för honom sin knä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'Och sade: Herre, förbarma dig öfver min son, ty han är månaderasande, och lider stor jämmer; ty han faller ofta i elden, och ofta i vattnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Och jag hade honom fram för dina Lärjungar, och de kunde intet hjelpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Då svarade Jesus, och sade: O du otrogna och genvördiga slägte, huru länge skall jag vara med eder? Huru länge skall jag lida eder? Hafver honom hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Och Jesus hotade honom, och djefvulen gick ut af honom; och drängen vardt helbregda i samma stund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Då gingo Lärjungarna till Jesum afsides, och sade: Hvi kunde icke vi drifva honom ut?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Jesus sade till dem: För edra otros skull. Sannerliga säger jag eder: Om I hafven trona som ett senapskorn, då mågen I säga till detta berget: Gack hädan dit bort, och det skall gå; och eder varder intet omöjeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Men detta slaget går icke ut, utan med bön och fasto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Men då de vistades i Galileen, sade Jesus till dem: Det skall ske, att menniskones Son varder öfverantvardad i menniskors händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'Och de skola dräpa honom, och tredje dagen skall han stå upp igen. Och de vordo storliga bedröfvade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Och när de kommo till Capernaum, gingo de, som skattpenningen plägade uppbära, till Petrum, och sade: Plägar icke edar mästare gifva skattpenning?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Då sade han: Ja; och som han kom i huset, förekom honom Jesus, och sade: Hvad synes dig, Simon? Af hvem taga jorderikes Konungar tull eller skatt? Af sin barn, eller af de främmande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Sade Petrus till honom: Af de främmande. Då sade Jesus till honom: Så äro ju barnen fri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Men på det vi icke skole förarga dem, så gack till hafvet, och kasta ut kroken; och den första fisk du får, tag. Och när du låter upp hans mun, varder du finnandes en penning; den tag, och få honom ut, för mig och dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'I den tiden gingo Lärjungarna till Jesum, och sade: Hvilken är den störste i himmelriket?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Då kallade Jesus fram ett barn, och ställde det midt ibland dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'Och sade: Sannerliga säger jag eder, utan I omvänden eder, och varden såsom barn, skolen I icke komma i himmelriket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Hvilken nu sig sjelf så förnedrar, som detta barnet, han är den störste i himmelriket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Och hvilken som undfår ett sådant barn i mitt Namn, han undfår mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Men hvilken som förargar en af dessa små, som tro på mig, honom vore bättre att en qvarnsten vore bunden vid hans hals, och han sänktes ned i hafsens djup.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Ve verldene för förargelses skull; ty förargelse måste ju komma; dock, ve de mennisko, genom hvilka förargelse kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Är det så att din hand, eller din fot är dig till förargelse, så hugg honom af, och kastan ifrå dig; bättre är dig ingå uti lifvet halt, eller lemmalös, än du skulle hafva två händer och två fötter, och kastas i evinnerlig eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Och är det så att ditt öga är dig till förargelse, rif det ut, och kastat ifrå dig; bättre är dig, att du ingår uti lifvet enögder, än du skulle hafva tu ögon, och kastas i helvetes eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Ser till, att I förakten ingen af dessa små; ty jag säger eder, att deras Änglar i himmelen se alltid mins Faders ansigte, i himlom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Ty menniskones Son är kommen till att frälsa det som förtappadt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Huru synes eder? Om en menniska hade hundrade får, och ett af dem fore vill; öfvergifver hon icke de nio och niotio på bergen, och går bort, och söker efter det som for vill?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Och händer det så, att hon finner det igen, sannerliga säger jag eder, hon gläds mera deröfver, än öfver de nio och niotio, som icke foro vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Så är ock icke edar himmelske Faders vilje, att någor af dessa små skall borttappad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Men om din broder syndar dig emot, så gack och straffa honom emellan dig och honom allena; hörer han dig, så hafver du förvärfvat din broder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Men hörer han dig icke, så tag ännu med dig en eller två, på det all sak skall bestå vid tvegge eller tregge vittnes mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Hörer han dem icke, så säg det församlingene; hörer han icke församlingena, så håll honom såsom en Hedning och Publican.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Sannerliga säger jag eder: Allt det I binden på jordene, det skall vara bundet i himmelen; och allt det I lösen på jordene, det skall vara löst i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Yttermera säger jag eder: Der två af eder komma öfverens på jordene, hvad ting det helst kan vara, som de bedja om, skall dem det vederfaras af minom Fader, som är i himlom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Ty hvar två eller tre äro församlade i mitt Namn, der är jag midt ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Då steg Petrus fram till honom, och sade: Herre, huru ofta skall min broder synda emot mig, och jag skall förlåta honom det? Är sju resor nog?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Då sade Jesus till honom: Jag säger dig, icke sju resor; utan sjutio sinom sju resor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Fördenskull är himmelriket liknadt vid en Konung, som ville hålla räkenskap med sina tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Och när han begynte räkna, kom en fram för honom, som honom var skyldig tiotusend pund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Och efter han hade icke der han kunde betala med, böd herren att han skulle säljas, och hans hustru, och barn, och allt det han ägde, och betalas med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Då föll den tjenaren ned, och tillbad honom, och sade: Herre, haf tålamod med mig, jag vill allt betala dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Då varkunnade herren sig öfver den tjenaren, och lät honom lös, och gaf honom till det han var skyldig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Då gick den tjenaren ut, och fann en af sina medtjenare, som honom var skyldig hundrade penningar; och han tog fatt på honom, och fick honom i halsen, drog honom, och sade: Betala det du äst skyldig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Då föll hans medtjenare till hans fötter, och bad honom, sägandes: Haf tålamod med mig, jag vill allt betala dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Men han ville icke; utan gick bort, och kastade honom i fängelse, så länge han betalade det han var skyldig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Då nu andre hans medtjenare sågo det som skedde, tyckte dem det ganska illa vara, och kommo, och kungjorde sinom herra allt det skedt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Då kallade hans herre honom för sig, och sade till honom: Du skalkaktige tjenare, allt det du skyldig vast, gaf jag dig till, ty du bad mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Skulle du ock icke hafva förbarmat dig öfver din medtjenare, såsom jag förbarmade mig öfver dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Och hans herre vardt vred, och antvardade honom bödlarna i händer, tilldess det var allt betaladt, som han honom skyldig var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Så skall ock min himmelske Fader göra eder, om I icke förlåten af edor hjerta, hvar och en sinom broder det de bryta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Och det begaf sig, när Jesus hade fullkomnat det talet, gick han utaf Galileen, och kom in i Judee landsändar, vid sidon af Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Och honom följde mycket folk; och han gjorde dem der helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Då gingo de Phariseer fram till honom, frestade honom, och sade till honom: Är det ock rätt, att man skiljer sig vid sina hustru, för allahanda sakers skull?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Då svarade han, och sade till dem: Hafven I icke läsit, att den, som gjorde menniskona af begynnelsen, man och qvinna gjorde han dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'Och sade: Fördenskull skall man öfvergifva fader och moder, och blifva när sine hustru; och de tu varda ett kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Så äro de icke nu tu, utan ett kött; det nu Gud hafver sammanfogat, skall menniskan icke åtskilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Då sade de till honom: Hvi böd då Moses gifva skiljobref, och öfvergifva henne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Sade han till dem: För edart hjertas hårdhets skull tillstadde Moses, att I måtten öfvergifva edra hustrur; men af begynnelsen var det icke så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Men jag säger eder: Hvar som skiljer sina hustru ifrå sig, utan för hors skull, och tager ena andra, han gör hor; och den som tager den öfvergifna, han gör hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Då sade hans Lärjungar till honom: Hafver mansens sak sig så med hustrune, då är icke godt gifva sig i ägtenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Då sade han till dem: Hvar man tager icke detta ordet, utan de, hvilkom det blifver gifvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Ty somlige snöpte äro, som så äro födde af moderlifvet; och somlige snöpte äro, som äro snöpte af menniskom; och somlige snöpte äro, som sig sjelfva hafva snöpt, för himmelrikets skull. Hvilken som kan tagat, han taget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Då vordo barn burne till honom, att han skulle lägga händer på dem, och bedja; men Lärjungarna näpste dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Då sade Jesus: Låter betämma barnen, och förmener dem icke komma till mig; ty sådana hörer himmelriket till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Och när han hade lagt händer på dem, gick han dädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Och si, en gick fram, och sade till honom: Gode Mästar, hvad godt skall jag göra, att jag må få evinnerligit lif?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Då sade han till honom: Hvi kallar du mig godan? Ingen är god, utan Gud allena; men vill du ingå till lifvet, så håll budorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Sade han till honom: Hvilka? Sade Jesus: Du skall icke dräpa; du skall icke bedrifva hor; du skall icke stjäla; du skall icke bära falsk vittne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Hedra din fader och dina moder; och du skall älska din nästa, såsom dig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Då sade den unge mannen till honom: Allt detta hafver jag hållit af min ungdom; hvad fattas mig ännu?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Sade Jesus till honom: Vill du vara fullkomlig, så gack bort, sälj det du hafver, och gif de fattiga, och du skall få en skatt i himmelen; och kom, och följ mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'När den unge mannen hörde detta ordet, gick han bedröfvad bort; ty han hade många ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Då sade Jesus till sina Lärjungar: Sannerliga säger jag eder: Dem rika är svårt gå in i himmelriket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Och yttermera säger jag eder: Det är lättare, att en camel går genom ett nålsöga, än att en rik kommer i Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'När Lärjungarna detta hörde, vordo de ganska förfärade, och sade: Ho kan då varda salig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Då såg Jesus till dem, och sade till dem: För menniskom är det omöjeligit; men för Gudi äro all ting möjelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Då svarade Petrus, och sade till honom: Si, vi hafve öfvergifvit all ting, och följt dig; hvad skole vi få derföre?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Då sade Jesus till dem: Sannerliga säger jag eder, att I, som mig hafven efterföljt, i den nya födelsen, när menniskones Son varder sittandes på sins majestäts säte, då skolen ock I sitta på tolf säte, dömande de tolf Israels slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Och hvar och en, som öfvergifver hus, eller bröder, eller systrar, eller fader, eller moder, eller hustru, eller barn, eller åkrar, för mitt Namns skull, han skall få hundradefaldt, och ärfva evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Men månge de främste blifva de ytterste, och de ytterste de främste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Förty himmelriket är likt enom husbonda, som gick ut bittida om morgonen, till att leja sig arbetare i sin vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Och när han hade varit öfverens med arbetarena om en viss dagspenning, sände han dem i sin vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Sedan gick han ut vid tredje stunden, och såg några andra ståndande fåfänga på torget;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Och sade till dem: Går ock I uti min vingård; och hvad skäligit är, vill jag gifva eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Och de gingo. Och åter gick han ut vid sjette och nionde stunden, och gjorde sammaledes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Men vid den ellofte stundena gick han ut, och fann några andra ståndande fåfänga, och sade till dem: Hvi stån I här hela dagen fåfänge?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'De sade till honom: Ty ingen hafver lejt oss. Då sade han till dem: Går ock I uti min vingård; och hvad skäligit är, skolen I få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'När aftonen kom, sade vingårdsherren till sin skaffare: Kalla fram arbetarena, och gif dem deras lön, begynnandes på de sista, intill de första.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Och när de kommo fram, som vid ellofte stundena komne voro, fick hvardera dagspenningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Men när de förste kommo, mente de, att de skulle fått mer; och fingo ock hvardera dagspenningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Och när de så fingo, knorrade de emot husbondan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Och sade: Desse siste hafva arbetat en timma, och du gjorde dem lika med oss, som hafva burit dagsens tunga och hettan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Då svarade han enom af dem, och sade: Min vän, jag gör dig ingen orätt; vast du icke öfverens med mig om en viss dagspenning?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Tag det dig tillhörer, och gack din väg; men jag vill gifva denna sista så mycket som dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Eller må jag icke göra uti min ting hvad jag vill? Ser du fördenskull illa ut, att jag så god är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Alltså varda de ytterste de främste, och de främste de ytterste. Ty månge äro kallade; men få äro utvalde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Och så drog Jesus upp till Jerusalem, och tog de tolf Lärjungarna till sig på vägen, och sade till dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Si, vi farom upp till Jerusalem, och menniskones Son skall öfverantvardas dem öfversta Prestomen, och dem Skriftlärdom; och de skola döma honom till döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'Och de skola öfverantvarda honom Hedningomen, till att begabbas, och hudflängas, och korsfästas; och tredje dagen skall han uppstå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Då steg Zebedei söners moder fram till honom med sina söner, tillbad honom, och begärade något af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Då sade han till henne: Hvad vill du? Sade hon till honom: Låt dessa två mina söner sitta i ditt rike; den ena på dina högra hand, och den andra på dina venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Då svarade Jesus, och sade: I veten icke hvad I bedjen; kunnen I dricka den kalken, som jag skall dricka, och döpas med det dopet, som jag döpes med? Då sade de till honom: Ja, väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Sade han till dem: Min kalk skolen I visst dricka, och döpas med det dop, som jag döpes med; men sitta på mina högra hand och venstra står icke mig till att gifva, utan dem som det tillredt är af minom Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'När de tio det hörde, vordo de misslynte på de två bröderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Då kallade Jesus dem till sig, och sade: I veten, att verldslige Förstar äro rådande, och de som herrar äro, hafva magtena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Så skall det icke vara ibland eder; utan den, som vill vara mägtig ibland eder, han vare edar tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'Och hvilken ibland eder vill vara den främste, han vare edar dräng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Såsom menniskones Son är icke kommen, på det han vill låta tjena sig, utan att han vill tjena, och gifva sitt lif till återlösning för många.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Och när de gingo utaf Jericho, följde honom mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Och si, två blinde såto vid vägen; och när de hörde, att Jesus gick der fram, ropade de, och sade: Ack! Herre, Davids Son, förbarma dig öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Men folket näpste dem, att de skulle tiga. Då ropade de dessmer, och sade: Ack! Herre, Davids Son, förbarma dig öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Då stadnade Jesus, och kallade dem, och sade: Hvad viljen I, att jag skall göra eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'De sade till honom: Herre, att vår ögon måtte öppnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Då varkunnade sig Jesus öfver dem, och tog på deras ögon; och straxt fingo de sina syn, och följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Och när de nalkades Jerusalem, och kommo till Bethphage, vid Oljoberget, sände Jesus två sina Lärjungar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Och sade till dem: Går i byn, som ligger för eder; och straxt varden I finnande ena åsninno bundna, och fålan när henne; löser dem, och leder till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Och om någor talar eder till, så säger: Herren behöfver dem; och straxt släpper han dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Detta är allt skedt, att det skulle fullkomnas, som sagdt är genom Propheten, som sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Säger till dottrena Zion: Si, din Konung kommer till dig, saktmodig, ridandes på ene åsninno, och på en arbetes åsninnos fåla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Lärjungarna gingo bort, och gjorde som Jesus hade dem befallt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Och ledde till honom åsninnona och fålan; och lade sin kläder på dem, och satte honom deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Mycket folk bredde sin kläder på vägen; de andre skåro qvistar af trän, och strödde på vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Men folket, som föregick, och de som efterföljde, ropade och sade: Hosianna, Davids Sone; välsignad vare han, som kommer i Herrans Namn; Hosianna i höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Och när han kom in i Jerusalem, upprörde sig hela staden, och sade: Ho är denne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Då sade folket: Denne är Jesus, den Propheten af Nazareth i Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Och gick Jesus in i Guds tempel, och dref ut alla de der köpte och sålde i templet, och omstötte vexlareborden, och dufvomånglarenas säte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Och sade till dem: Det är skrifvet: Mitt hus skall kallas ett bönehus; men I hafven gjort ena röfvarekulo deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Och till honom kommo blinde och halte i templet; och han gjorde dem helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'När de öfverste Presterna och de Skriftlärde sågo de under, som han gjorde, och barnen, som ropade i templet, sägande: Hosianna, Davids Sone, blefvo de misslynte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'Och sade till honom: Hörer du hvad desse säga? Då sade Jesus till dem: Hvi icke? Hafven I aldrig läsit: Af barnas och spenabarnas mun hafver du fullkomnat lofvet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Då öfvergaf han dem, och gick utu staden till Bethanien, och blef der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Om morgonen, när han gick in i staden igen, hungrade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Och han fick se ett fikonaträ vid vägen, och gick dertill, och fann intet deruppå, utan allenast löf; och sade till det: Växe aldrig härefter frukt på dig. Och fikonaträt blef straxt torrt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Och när Lärjungarna sågo det, förundrade de sig, och sade: Huru är det fikonaträt så snart torkadt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Då svarade Jesus, och sade till dem: Sannerliga säger jag eder: Om I hafven trona, och tviflen intet, så varden I icke allenast görande sådant, som med fikonaträt skedde; utan jemväl, om I sägen till detta berget: Häf dig upp, och kasta dig i hafvet, då skall det ske;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Och allt det I bedjen i bönene, troendes, det skolen I få.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Och när han kom i templet, gingo de öfverste Presterna och de äldste i folket till honom, der han lärde, och sade: Af hvad magt gör du detta? Och hvilken hafver gifvit dig denna magten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Då svarade Jesus, och sade till dem: Jag vill ock spörja eder ett ord; om I sägen mig det, vill jag ock säga eder, af hvad magt jag detta gör:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Hvadan var Johannis döpelse? Af himmelen eller af menniskom? Då tänkte de vid sig sjelfva, och sade: Sägom vi, af himmelen; då säger han till oss: Hvi trodden I då honom icke?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Sägom vi ock, af menniskom; så rädes vi folket; ty alle höllo Johannes för en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Då svarade de Jesu, och sade: Vi vete det icke. Sade han till dem: Icke heller säger jag eder, af hvad magt jag detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Men hvad synes eder? En man hade två söner, och gick till den första, och sade: Son, gack, och arbeta i dag i min vingård.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Han svarade, och sade: Jag vill icke. Sedan ångrade honom det, och gick åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Och gick han till den andra, och sade sammalunda. Då svarade han, och sade: Ja, herre; och gick intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Hvilken af de två gjorde det fadren ville? De sade till honom: Den förste. Sade Jesus till dem: Sannerliga säger jag eder, att Publicaner och skökor skola gå i himmelriket förr än I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Johannes kom till eder, och lärde eder rätta vägen, och I trodden honom intet; men Publicaner och skökor trodde honom; och ändock I det sågen, hafven I dock sedan ingen bättring gjort, att I måtten trott honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Hörer en annor liknelse: Det var en husbonde, som planterade en vingård, och gärde der gård omkring, och grof en press derinne, och byggde ett torn, och utlejde honom vingårdsmännom, och for utländes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'När nu fruktenes tid kom, sände han sina tjenare till vingårdsmännerna, att de skulle uppbära hans frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Då togo vingårdsmännerna fatt på hans tjenare; den ena hudflängde de, den andra slogo de ihjäl, den tredje stenade de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Åter sände han andra tjenare, flera än de första; och de gjorde dem sammaledes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'På det sista sände han sin son till dem, och sade: De hafva ju ena försyn för min son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Men när vingårdsmännerna sågo sonen, sade de emellan sig: Denne är arfvingen; kommer, låter oss slå honom ihjäl, och så få vi hans arfvedel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Och de togo fatt på honom, drefvo honom ut af vingården, och slogo honom ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'När nu vingårdsherren kommer, hvad skall han göra åt de vingårdsmännerna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Sade de till honom: De onda skall han illa förgöra, och leja sin vingård androm vingårdsmännom, de som gifva honom fruktena i rättom tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Då sade Jesus till dem: Hafven I aldrig läsit i Skriftene? Den stenen, som byggningsmännerna bortkastade, han är blifven en hörnsten; af Herranom är detta skedt, och är underligit för vår ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Derföre säger jag eder, att Guds rike skall tagas från eder, och varda gifvet Hedningomen, som göra dess frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Och hvilken som faller på denna stenen, han varder krossad; men uppå hvilken han faller, den slår han sönder i stycker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Och när de öfverste Presterna och Phariseerna hörde hans liknelser, förnummo de, att han talade om dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Och de ville hafva tagit fatt på honom; men de räddes för folket, ty de höllo honom för en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Och svarade Jesus, och talade dem åter till genom liknelser, sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Himmelriket är likt enom Konung, som gjorde bröllop åt sin son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Och sände ut sina tjenare, att de skulle kalla dem, som budne voro till bröllopet; och de ville icke komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Åter sände han ut andra tjenare, sägandes: Säger dem som budne äro: Si, jag hafver tillredt min måltid; mine oxar och min gödeboskap äro slagtad, och all ting äro redo; kommer till bröllop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Men de försummade det; och gingo bort, den ene till sin afvelsgård, den andre till sin köpenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Och somlige togo fatt på hans tjenare, hädde och dråpo dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'När Konungen det hörde, vardt han vred, och sände ut sina härar, och förgjorde de dråpare, och brände upp deras stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Då sade han till sina tjenare: Bröllopet är tillredt; men de, som voro budne, voro icke värdige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Derföre går ut på vägarna, och alle de I finnen, kaller till bröllopet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Och tjenarena gingo ut på vägarna, och församlade alla, så många de funno, både onda och goda; och borden vordo all fullsatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Då gick Konungen in, att han skulle bese gästerna, och såg der en man, som var icke klädd i bröllopskläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Och sade till honom: Min vän, huru kom du härin, och hafver icke bröllopskläder? Och han tigde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Då sade Konungen till tjenarena; Binder honom händer och fötter, och kaster honom i det yttersta mörkret; der skall vara gråt och tandagnisslan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Ty månge äro kallade, och få utkorade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Då gingo de Phariseer bort, och lade råd, huru de måtte beslå honom med orden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Och sände sina lärjungar till honom, med de Herodianer, och sade: Mästar, vi vete att du äst sannfärdig, och lärer Guds väg rätt, och du rädes för ingen; ty du ser icke efter menniskors person.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Så säg oss: Huru synes dig? Är det rätt, att man gifver Kejsarenom skatt, eller ej?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'När Jesus märkte deras skalkhet, sade han: Hvi fresten I mig, I skrymtare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Låter mig se myntet på skattpenningen. Och de fingo honom penningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Och han sade till dem: Hvars beläte och öfverskrift är detta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'De sade till honom: Kejsarens. Då sade han till dem: Så gifver Kejsarenom det Kejsarenom tillhörer, och Gudi det Gudi tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'När de det hörde, förundrade de sig; och öfvergåfvo honom, gångande ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'På den dagen gingo till honom de Sadduceer, som säga att ingen uppståndelse är; och frågade honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Sägande: Mästar, Mose sade: Om någor blifver död barnlös, då skall hans broder taga hans hustru till ägta, och uppväcka sinom broder säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'När oss voro sju bröder; den förste tog sig hustru, och blef död; och efter han hade ingen säd, lefde han sina hustru sinom broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Sammalunda ock den andre, och den tredje, allt intill den sjunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Sist af allom blef ock qvinnan död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'När nu uppståndelsen sker, hvilkens hustru af de sju blifver hon? Ty de hafva alle haft henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Då svarade Jesus, och sade till dem: I faren ville, och veten icke Skriftena, ej heller Guds kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Ty i uppståndelsen hvarken tager man sig hustru, eller qvinna gifs manne; utan de äro lika som Guds Änglar i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Men om de dödas uppståndelse hafven I icke läsit, hvad eder sagdt är af Gudi, som sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Jag är Abrahams Gud, och Isaacs Gud, och Jacobs Gud? Gud är icke de dödas Gud, utan deras som lefvande äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Och när folket sådant hörde, förundrade de sig öfver hans lärdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'När de Phariseer hörde, att han hade stoppat de Sadduceer munnen till, församlade de sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Och en af dem, som var en Skriftlärd, frestade honom, sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Mästar, hvilket är det yppersta budet i lagen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Då sade Jesus till honom: Du skall älska Herran din Gud, af allt ditt hjerta, och af allo dine själ, och af all din håg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Detta är det yppersta och största budet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Det andra är desso likt: Du skall älska din nästa som dig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'På dessa tu buden hänger all lagen och Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'När nu de Phariseer voro tillhopa, frågade dem Jesus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Och sade: Hvad synes eder om Christo? Hvars son är han? Sade de till honom: Davids.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Då sade han till dem: Hvi kallar då David honom i Andanom Herra? sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Herren sade till min Herra: Sätt dig på mina högra hand, tilldess jag lägger dina fiendar dig till en fotapall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Efter nu David kallar honom Herra, huru är han då hans son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Och ingen kunde svara honom ett ord; och ifrå den dagen dristade sig ej heller någor att fråga honom något mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Då talade Jesus till folket, och till sina Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Sägandes: På Mose stol sitta de Skriftlärde och Phariseer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Allt det de bjuda eder hålla, det håller och görer; men efter deras gerningar görer icke; ty de säga, och göra intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'De binda tunga och odrägeliga bördor tillsamman, och lägga menniskomen på härdarna; men de vilja icke sjelfve röra dem med ett finger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Men alla sina gerningar göra de, på det de skola varda sedde af menniskomen; de göra sina tänkeskrifter breda, och fållarna på sin kläder stora;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'De sitta gerna främst vid borden, och i Synagogorna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'Och vilja gerna varda helsade på torgen, och heta af menniskomen: Rabbi, Rabbi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Men I skolen icke låta kalla eder Rabbi; ty en är edar Mästare, Christus, och I ären alle bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Och I skolen ingen fader kalla eder på jordene; ty en är edar Fader, som är i himlom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Och I skolen icke låta kalla eder Mästare; ty en är edar Mästare, Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Den som är ypperst ibland eder, han skall vara edar tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Ty den sig upphöjer, han skall varda förnedrad; och den sig förnedrar, han skall varda upphöjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Ve eder, Skriftlärde och Phariseer; I skrymtare, som tillsluten himmelriket för menniskomen; I gån icke der sjelfve in, och dem som in vilja, tillstädjen I icke ingå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Ve eder, Skriftlärde och Phariseer; I skrymtare, som uppäten enkors hus, förebärande långa böner; fördenskull skolen I få dess hårdare fördömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Ve eder, Skriftlärde och Phariseer; I skrymtare, som faren omkring vatten och land, att I skolen göra en Proselyt; och när han gjord är, gören I honom till helvetes barn, dubbelt mer än I sjelfve ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Ve eder, blinde ledare, ty I sägen: Hvilken som svär vid templet, det är intet; men den som svär vid guldet i templet, han är saker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'I galne och blinde; hvilket är yppare, guldet, eller templet som helgar guldet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Och hvilken som svär vid altaret, det är intet; men den der svär vid offret, som deruppå är, han är saker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'I galne och blinde, hvilket är yppare, offret, eller altaret som helgar offret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Derföre, den som svär vid altaret, han svär vid det sjelft, och vid allt det derpå är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Och den som svär vid templet, han svär vid det sjelft, och vid honom som deruti bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Och den som svär vid himmelen, han svär vid Guds stol, och vid honom som deruppå sitter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Ve eder, Skriftlärde och Phariseer; I skrymtare, som gören tiond af mynto, dill och kumin, och låten bestå det som svårast är i lagen, nämliga domen, barmhertigheten och tron; detta skulle man göra, och det andra icke låta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'I blinde ledare, som silen myggor, och uppsvälgen camelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Ve eder, Skriftlärde och Phariseer; I skrymtare, som gören drickekaret och fatet rent utantill; men innantill äro all ting full med rof och orenlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Du blinde Pharisee, gör först rent det som är innantill i drickekaret, och i fatet, att det utvärtes är må ock rent varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Ve eder, Skriftlärde och Phariseer; I skrymtare, som ären like de grafvar, som utantill äro hvitmenade, hvilka utvärtes synas dägeliga; men innantill äro de fulla med de dödas ben och all orenlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Så synes ock I utvärtes för menniskomen rättfärdige; men invärtes ären I fulle med skrymteri och odygd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Ve eder, Skriftlärde och Phariseer; I skrymtare, som uppbyggen Propheternas grafvar, och pryden de rättfärdigas grifter,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Sägande: Hade vi varit i våra fäders tid, vi skullom icke hafva varit delaktige med dem i Propheternas blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Så betygen I då öfver eder sjelfva, att I ären deras barn, som Propheterna dråpo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Nu väl, uppfyller ock I edra fäders mått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'I ormar, I huggormars afföda, huru skolen I undfly helvetes fördömelse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Derföre, si, jag sänder till eder Propheter, och visa och Skriftlärda; och somliga af dem skolen I dräpa och korsfästa, och somliga af dem skolen I hudflänga i edra Synagogor, och förfölja ifrå den ena staden till den andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'På det öfver eder skall komma allt rättfärdigt blod, som är utgjutet på jordene, ifrå dens rättfärdiga Abels blod, intill Zacharie, Barachie sons, blod, hvilken I dråpen emellan templet och altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Sannerliga säger jag eder, att allt detta skall komma uppå detta slägtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalem, Jerusalem, du som dräper Propheterna, och stenar dem som äro sände till dig; huru ofta hafver jag velat församla din barn, lika som hönan församlar sina kycklingar under sina vingar, och I villen icke?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Si, edart hus skall eder blifva öde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Ty jag säger eder: Efter denna tiden skolen I icke se mig, tilldess I skolen säga: Välsignad vare han, som kommer i Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Då gick Jesus sin väg utaf templet; och hans Lärjungar gingo till honom, att de skulle låta honom se templets byggning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Då sade Jesus till dem: Sen I icke allt detta? Sannerliga säger jag eder: Här skall icke låtas en sten på den andra, som icke blifver nederbruten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Och när han satt på Oljoberget, gingo hans Lärjungar till honom afsides, och sade: Säg oss, när detta skall ske? Och hvad varder för tecken till din tillkommelse, och verldens ända?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Då svarade Jesus, och sade till dem: Ser till, att ingen förförer eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Ty månge skola komma i mitt Namn, och säga: Jag är Christus; och skola förföra många.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'I skolen få höra örlig, och rykte af örlig; ser till, att I blifven icke försoffade; ty allt detta måste ske, men det är icke straxt änden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Det ena folket skall resa sig upp emot det andra, och det ena riket emot det andra; och skola blifva pestilentier, och hunger, och jordbäfning, mångastäds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Då skall nöden aldraförst begynnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Då skola de öfverantvarda eder uti tvång, och dräpa eder; och I skolen blifva hatade af all folk, för mitt Namns skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Och då skola månge förargas, och inbördes den ena förråda den andra, och inbördes hata hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Och månge falske Propheter skola uppkomma, och förföra många.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Och efter det ondskan får öfverhandena, varder kärleken i mångom förkolnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Men den som blifver fast uti ändan, han varder salig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Och detta Evangelium om riket skall varda predikadt i hela verldene, till ett vittnesbörd öfver all folk; och då skall änden komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'När I nu fån se förödelsens styggelse, af hvilko sagdt är genom Daniel Propheten, ståndande i det helga rummet; den som läs det, han gifve akt deruppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'De som då i Judiska landet äro, fly de på bergen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'Och den som är uppå taket, han stige icke ned, till att taga något ut af sitt hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'Och den som är ute på markene, gånge icke tillbaka efter sin kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Men ve dem som hafvande äro, och dem som dia gifva, i den tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Men beder, att edor flykt sker icke om vintren, eller om Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Ty då skall varda en stor vedermöda, så att hon hafver icke varit sådana ifrå verldenes begynnelse och till denna tiden, ej heller varda skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Och om de dagar icke vorde förstäckte, då vorde intet kött frälst; men för de utvaldas skull skola de dagar varda förstäckte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Om någor säger då till eder: Si, här är Christus, eller der; så tror det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Ty falske Christi och falske Propheter skola uppkomma, och skola göra stor tecken och under; så att, om möjeligit vore, skola ock de utvalde förförde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Si, jag hafver sagt eder det framföreåt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Derföre, om de då säga till eder: Si, han är uti öknene; går icke ut: Si, han är i kammaren; tror det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Ty såsom ljungelden går ut af öster, och synes allt intill vester; så varder ock menniskones Sons tillkommelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Men der som åtelen är, dit församla sig ock örnarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Men straxt efter den tidsens vedermödo skall solen blifva mörk, och månen skall icke gifva sitt sken, och stjernorna skola falla af himmelen, och himlarnas krafter skola bäfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Och då skall synas menniskones Sons tecken i himmelen; och då skola all slägte på jordene jämra sig, och skola se menniskones Son komma i himmelens sky, med stora kraft och härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Och han skall utsända sina Änglar, med höga basunaröst; och de skola församla hans utvalda ifrå de fyra väder; ifrå den ena himmelens ända till den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Af fikonaträt lärer en liknelse: När nu dess qvistar knoppas, och löfvet begynner springa ut, så veten I, att sommaren är hardt när;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Så ock, när I sen allt detta, så veter, att det är hardt för dörrene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Sannerliga säger jag eder: Detta slägtet skall icke förgås, förrän allt detta sker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Himmel och jord skola förgås; men min ord skola icke förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Men om den dagen och om den stundena vet ingen, icke Änglarna i himmelen, utan min Fader allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Men lika som det var i Noe tid, så skall ock menniskones Sons tillkommelse vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Ty såsom de voro i de dagar för flodene; de åto och drucko, togo hustrur, och gåfvos mannom, intill den dagen, då Noe gick i arken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'Och visste intet af, förr än floden kom, och tog dem allasamman bort; så skall ock menniskones Sons tillkommelse vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Då skola två vara ute på markene; den ene blifver upptagen, den andre blifver qvarlåten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Två skola mala på ene qvarn; den ene blifver upptagen, den andre blifver qvarlåten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Vaker fördenskull; ty I veten icke, hvad stund edar Herre varder kommandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Men det skolen I veta att, visste husbonden, hvad stund tjufven skulle komma, förvisso vakade han och läte icke uppbryta sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Derföre varer I ock redo; ty, den stund I icke menen, varder menniskones Son kommandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Hvilken är nu en trogen och snäll tjenare, som herren hafver satt öfver sitt husfolk, att han skall gifva dem mat i rättom tid?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Salig är den tjenaren, som hans herre finner så görande, när han kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Sannerliga säger jag eder, han skall sätta honom öfver alla sina ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Men om så är, att den onde tjenaren säger i sitt hjerta: Min herre kommer icke ännu brådt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'Och begynner så slå sina medtjenare; ja, äta och dricka med de druckna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'Så kommer dens tjenarens herre, den dag han icke väntar honom, och den stund han icke menar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'Och skall sönderhugga honom, och gifva honom hans lön med skrymtare. Der skall vara gråt och tandagnisslan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Då varder himmelriket likt tio jungfrur, som togo sina lampor, och gingo ut emot brudgummen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Men fem af dem voro visa, och fem fåvitska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'De fåvitska togo sina lampor, och togo inga oljo med sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Men de visa togo oljo i sin kärile, samt med lampomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Då nu brudgummen dröjde, blefvo de alla sömniga, och sofvo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Men om midnattstid vardt ett anskri: Si, brudgummen kommer; går ut emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Då stodo alla de jungfrurna upp, och redde sina lampor till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Då sade de fåvitska till de visa: Gifver oss af edra oljo; ty våra lampor slockna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Då svarade de visa, sägande: Ingalunda; på det både oss och eder icke skall fattas; utan går heldre till dem som sälja, och köper till eder sjelfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'När de gingo och skulle köpa, kom brudgummen; och de, som redo voro, gingo in med honom i bröllopet, och dörren tillstängdes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'På det sista kommo ock de andra jungfrurna, och sade: Herre, Herre, låt upp för oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Då svarade han, och sade: Sannerliga säger jag eder: Jag känner eder intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Vaker fördenskull; ty I veten hvarken dag eller stund, när menniskones Son är kommandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Ty lika som en man, den utländes for, kallade sina tjenare, och fick dem sina ägodelar i händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Och fick enom fem pund, enom tu, och enom ett, hvarjom efter hans magt; och for straxt bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Då gick den bort, som fem pund hade fått, och handlade med dem; och vann annor fem pund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Sammalunda ock den som tu hade fått, vann ock annor tu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Men den som ett hade fått, gick bort, grof i jordena, och bortgömde sins herras penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'En lång tid derefter kom de tjenares herre, och höll räkenskap med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Då steg han fram, som hade fått fem pund, och sade: Herre, du fick mig fem pund; si, annor fem pund hafver jag vunnit med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Då sade hans herre till honom: Ack! du gode och trogne tjenare, öfver en ringa ting hafver du varit trogen, jag skall sätta dig öfver mycket; gack in i dins herras glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Då gick ock den fram, som hade fått tu pund, och sade: Herre, du fick mig tu pund, si, annor tu hafver jag vunnit dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Då sade hans herre till honom: Ack! du gode och trogne tjenare, öfver en ringa ting hafver du varit trogen, jag skall sätta dig öfver mycket; gack in i dins herras glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Då kom ock den fram, som hade fått ett pund, och sade: Herre, jag visste, att du äst en sträng man; du uppskär der du intet sådde, och upphemtar der du intet strödde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Och jag fruktade mig, gick bort, och gömde ditt pund i jordene; si, här hafver du det dig tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Då svarade hans herre, och sade till honom: Du onde och late tjenare; visste du, att jag uppskär der jag intet sådde, och upphemtar der jag intet strödde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Så skulle du hafva fått vexlarena mina penningar; och när jag hade kommit, hade jag ju fått mitt med vinning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Derföre tager af honom pundet, och gifver honom, som tio pund hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Ty hvarjom och enom, som hafver, skall varda gifvet, och han skall hafva nog; men den som icke hafver, det som han hafver, skall ock tagas ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Och den onyttiga tjenaren kaster uti det yttersta mörkret; der skall vara gråt och tandagnisslan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Men när menniskones Son kommer i sitt majestät, och alle helige Änglar med honom, då skall han sitta på sins härlighets stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Och för honom skola församlas all folk; och han skall skilja dem, den ena ifrå den andra, såsom en herde skiljer fåren ifrå getterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Och fåren skall han ställa på sina högra sido, och getterna på den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Då skall Konungen säga till dem, som äro på hans högra sido: Kommer, I mins Faders välsignade, och besitter det riket, som eder är tillredt ifrå verldenes begynnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Ty jag var hungrig, och I gåfven mig äta; jag var törstig, och I gåfven mig dricka; jag var husvill, och I herbergaden mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Nakot, och I klädden mig; sjuk, och I sökten mig; jag var i häktelse, och I kommen till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Då skola de rättfärdige svara honom, och säga: Herre, när sågom vi dig hungrigan, och spisadom dig; eller törstigan, och gåfvom dig dricka?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'När sågom vi dig vara husvillan, och herbergadom dig; eller nakotan, och kläddom dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Eller när sågom vi dig sjukan, eller i häktelse, och kommom till dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Då skall Konungen svara, och säga till dem: Sannerliga säger jag eder: Det I hafven gjort enom af dessa minsta mina bröder, det hafven I gjort mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Då skall han ock säga till dem på venstra sidone: Går bort ifrå mig, I förbannade, uti evinnerlig eld, som djeflenom och hans änglom tillredd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Ty jag var hungrig, och I gåfven mig icke äta; jag var törstig, och I gåfven mig icke dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Jag var husvill, och I herbergaden mig icke; nakot, och I klädden mig icke; jag var sjuk och i häktelse, och I sökten mig icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Då skola ock de svara honom, och säga: Herre, när såge vi dig hungrigan, eller törstigan, eller husvillan, eller nakotan, eller sjukan, eller i häktelse, och hafvom icke tjent dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Då skall han svara dem och säga: Sannerliga säger jag eder: Hvad I icke hafven gjort enom af dessa minsta, det hafven I ock icke gjort mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Och desse skola då gå uti eviga pino; men de rättfärdige i evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Och det begaf sig, när Jesus hade lyktat all dessa ord, sade han till sina Lärjungar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'I veten att två dagar härefter varder Påska; och menniskones Son skall öfverantvardas till att korsfästas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Då församlade sig de öfverste Presterna och de Skriftlärde, och de äldste i folket, uti den öfversta Prestens palats, som het Caiphas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'Och rådslogo, huru de måtte få gripa Jesum med list, och dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Dock sade de: Icke i högtiden, att ett upplopp icke varder i folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Då nu Jesus var i Bethanien, i den spitelska Simons hus,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Steg en qvinna fram till honom, och hade ett glas med dyr smörjelse; och göt det på hans hufvud, der han satt vid bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Då hans Lärjungar det sågo, vordo de misslynte, och sade: Hvad gjordes denna förspillning behof?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Denna smörjelse måtte man hafva väl dyrt sålt, och gifvit de fattiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'När Jesus det förnam, sade han till dem: Hvi gören I denna qvinnone illa tillfrids? ty hon hafver gjort med mig en god gerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'I hafven alltid fattiga när eder; men alltid hafven I icke mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Det hon hafver utgjutit denna smörjelsen på min lekamen, det hafver hon gjort mig till begrafning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Sannerliga säger jag eder, hvar som helst i hela verldene detta Evangelium varder predikadt, skall ock detta, som hon gjorde, sagdt varda henne till åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Då gick en af de tolf, som het Judas Ischarioth, bort till de öfversta Presterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'Och sade: Hvad viljen I gifva mig, att jag förråder eder honom? Och de vordo öfverens med honom om tretio silfpenningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Och ifrå den tiden sökte han tillfälle, att han måtte förråda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Men på första Sötbrödsdagen gingo Lärjungarna till Jesum, och sade till honom: Hvar vill du, att vi skole tillreda dig Påskalambet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Då sade han: Går in i staden till en, och säger honom: Mästaren låter säga dig: Min tid är hardt när; när dig vill jag hålla Påska, med mina Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Och Lärjungarna gjorde som Jesus befallde dem, och tillredde Påskalambet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Och om aftonen satte han sig till bords med de tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Och vid de åto, sade han: Sannerliga säger jag eder, en af eder skall förråda mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Då vordo de svårliga bedröfvade, och begynte hvar i sin stad säga till honom: Herre, icke är jag den samme?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Då svarade han, och sade: Den, som med mig doppade handena i fatet, han skall förråda mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Menniskones Son varder gåendes, som skrifvet är om honom; men ve den mennisko, af hvilko menniskones Son varder förrådd; det vore de menniskone bättre, att hon aldrig hade född varit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Då svarade Judas, som förrådde honom, och sade: Mästar, icke är jag den samme? Sade han till honom: Du sadet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Men när de åto, tog Jesus brödet; tackade, och bröt, och gaf Lärjungomen, och sade: Tager, äter; detta är min lekamen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Och han tog kalken, och tackade, gaf dem, och sade: Dricker häraf alle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Ty detta är min blod, dess nya Testamentsens, hvilken utgjuten varder för mångom, till syndernas förlåtelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Jag säger eder: Härefter skall jag icke dricka af denna vinträs frukt, intill den dagen jag varder det drickandes nytt med eder i mins Faders rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Och när de hade sagt lofsången, gingo de ut till Oljoberget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Då sade Jesus till dem: I denna nattene skolen I alle förargas i mig; ty det är skrifvet: Jag skall slå herdan, och fåren af hjorden skola varda förskingrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Men när jag är uppstånden igen, vill jag gå fram för eder i Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Då svarade Petrus, och sade till honom: Om än alle förargades i dig, så skall jag dock likväl aldrig förargas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Sade Jesus till honom: Sannerliga säger jag dig, att i desso nattene, förr än hanen gal, skall du neka mig tre resor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Sade Petrus till honom: Om jag skulle än dö med dig, vill jag icke neka dig. Sammaledes sade ock alle Lärjungarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Då kom Jesus med dem på den platsen, som kallas Gethsemane, och sade till Lärjungarna: Sitter här, så länge jag går dit bort, och beder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Och han tog Petrum till sig, och de två Zebedei söner, och begynte bedröfvas och ängslas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Då sade Jesus till dem: Min själ är bedröfvad intill döden; blifver här, och vaker med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Och han gick litet ifrå dem, föll ned på sitt ansigte, bad, och sade: Min Fader, är det möjeligit, så gånge denne kalken ifrå mig; dock icke som jag vill, utan som du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Och han kom till Lärjungarna, och fann dem sofvande; och sade till Petrum: Så förmådden I icke vaka ena stund med mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Vaker och beder, att I fallen icke uti frestelse; anden är viljog, men köttet är svagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Åter gick han bort annan gång, och bad, sägandes: Min Fader, om det är icke möjeligit att denne kalken går ifrå mig, med mindre jag dricker honom, så ske din vilje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Så kom han, och fann dem åter sofvande; ty deras ögon voro tung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Och han lät då blifva dem, och gick åter bort, och bad tredje gången, sägandes samma orden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Då kom han till sina Lärjungar, och sade till dem: Ja, sofver nu, och hviler eder; si, stunden är kommen, och menniskones Son skall antvardas i syndares händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Står upp, och låter oss gå; si, den är här, som mig förråder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Och vid han än talade, si, då kom Judas, en af de tolf, och med honom en stor skare, med svärd och med stafrar, utsände af de öfversta Presterna, och af de äldsta i folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Men den, som förrådde honom, hade gifvit dem ett tecken, sägandes: Hvilken jag kysser, den äret; tager honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Då steg han hastigt fram till Jesum, och sade: Hel Rabbi; och kysste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Då sade Jesus till honom: Min vän, hvarefter kommer du? Då stego de fram, och båro händer på Jesum, och grepo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Och si, en af dem, som voro med Jesu, räckte ut handena, drog ut sitt svärd, och slog dens öfversta Prestens tjenare, och afhögg hans öra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Då sade Jesus till honom: Stick ditt svärd i sitt rum; ty alle de som taga till svärd, de skola förgås med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Eller menar du, jag kunde icke bedja min Fader, att han skickade till mig mer än tolf legioner Änglar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Huru blefve då Skriften fullkomnad, att så ske skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'I samma stundene sade Jesus till skaran: Lika som till en röfvare ären I utgångne, med svärd och stafrar, till att taga fatt på mig; hvar dag hafver jag sutit när eder i templet, lärandes, och I hafven icke gripit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Men detta är allt skedt, på det Propheternas skrifter skulle fullkomnas. Då öfvergåfvo alle Lärjungarna honom, och flydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Men de, som hade gripit Jesum, ledde honom till den öfversta Presten Caiphas, der de Skriftlärde och de äldste församlade voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Men Petrus följde honom långt efter, intill den öfversta Prestens palats; och gick in, och satte sig när tjenarena, på det han skulle se ändan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Men de öfverste Presterne, och de äldste, och hela Rådet, sökte falskt vittnesbörd emot Jesum, att de måtte dräpa honom; och funno intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Och ändock mång falsk vittne kommo fram, funno de likväl intet. På det sista kommo tu falsk vittne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Och sade: Denne hafver sagt: Jag kan bryta ned Guds tempel, och bygga det upp i tre dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Och den öfverste Presten stod upp, och sade till honom: Svarar du intet till det som desse vittna emot dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Men Jesus tigde. Och den öfverste Presten svarade, och sade till honom: Jag besvär dig vid lefvandes Gud, att du säger oss, om du äst Christus, Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Sade Jesus till honom: Du sade det. Dock säger jag eder: Härefter skolen I få se menniskones Son sitta på kraftenes högra hand, och komma i himmelens sky.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Då ref den öfverste Presten sin kläder sönder, och sade: Han hafver förhädat Gud; hvad görs oss nu mer vittne behof? Si, nu hörden I hans hädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Hvad synes eder? Då svarade de, och sade: Han är saker till döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Då spottade de i hans ansigte, och slogo honom med näfvarna; somlige kindpustade honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Och sade: Spå oss, Christe, hvilken är den som dig slog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Men Petrus satt utanföre i palatset; och der kom till honom en tjensteqvinna, och sade: Du vast ock med Jesu af Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Men han nekade för allom, och sade: Jag vet icke hvad du säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Och när han gick ut genom dörrena, såg honom en annor (tjensteqvinna), och sade till dem som der voro: Denne var ock med Jesu Nazareno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Åter nekade han, och svor: Jag känner icke mannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Och litet efter stego de fram, som der stodo, och sade till Petrum: Visserliga äst du ock en af dem; ty ditt tungomål röjer dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Då begynte han förbanna sig, och svärja, att han kände icke mannen. Och straxt gol hanen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Då kom Petrus ihåg Jesu ord, som han hade sagt honom: Förr än hanen gal, skall du neka mig tre resor; och gick ut, och gret bitterliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Men om morgonen höllo alle öfverste Presterna, och de äldste i folket, råd emot Jesum, att de måtte dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Och ledde honom bundnan, och öfverantvardaden landshöfdinganom Pontio Pilato.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'När Judas, som honom förrådde, såg att han var dömder, ångrade det honom, och bar igen de tretio silfpenningar till de öfversta Presterna, och till de äldsta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Och sade: Jag hafver illa gjort, att jag hafver förrådt menlöst blod. Då sade de: Hvad kommer det oss vid? Der må du se dig om.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Och han kastade silfpenningarna i templet, och gick sin väg; och gick bort, och hängde sig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Men de öfverste Presterna togo silfpenningarna, och sade: Man må icke kasta dem i offerkistona; ty det är blods värd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Och när de hade hållit råd, köpte de dermed en krukomakares åker, till främmandes begrafning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Af hvilko den platsen heter Blodplats, intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Då vardt fullkomnadt det som sagdt var genom Jeremias Propheten, som sade: Och de hafva tagit tretio silfpenningar, der den sålde med betalad vardt, hvilken de köpte af Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'Och de hafva dem gifvit för en krukomakares åker, som Herren mig befallt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Och Jesus stod för landshöfdinganom; och landshöfdingen frågade honom, och sade: Äst du Judarnas Konung? Då sade Jesus till honom: Du säger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Och när han anklagades af de öfversta Presterna, och af de äldsta, svarade han intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Då sade Pilatus till honom: Hörer du icke, huru mycket de betyga emot dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Och han svarade honom icke till ett ord, så att landshöfdingen förundrade sig storliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Men om högtidsdagen plägade landshöfdingen gifva folkena en fånga lös, hvilken som de begärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Och hade han på den tid en beryktad fånga, som het Barabbas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Och när de voro församlade, sade Pilatus till dem: Hvilken viljen I att jag skall gifva eder lös, Barabbam, eller Jesum, som kallas Christus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Ty han visste, att de hade öfverantvardat honom för afunds skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Och när han satt på domstolen, sände hans hustru till honom, och lät säga honom: Befatta dig intet med denna rättfärdiga mannen; jag hafver mycket lidit i dag i sömnen för hans skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Men de öfverste Presterna, och de äldste, gåfvo folkena in, att de skulle begära Barabbam, och förgöra Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Då svarade landshöfdingen, och sade till dem: Hvilken af dessa två viljen I att jag skall gifva eder lös? De sade: Barabbam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Då sade Pilatus till dem: Hvad skall jag då göra af Jesu, som kallas Christus? Sade de till honom alle: Låt korsfästa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Då sade landshöfdingen: Hvad hafver han dock illa gjort? Då skriade de ännu mer, och sade: Låt korsfästa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Men när Pilatus såg, att han kunde intet skaffa, utan sorlet blef ju mer, tog han vatten, och tvådde sina händer för folkena, och sade: Oskyldig är jag i denna rättfärdiga mansens blod; I mågen se eder der om.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Då svarade allt folket, och sade: Hans blod komme öfver oss, och öfver vår barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Då gaf han dem Barabbam lös; men Jesum lät han hudflänga, och öfverantvardade honom, att han skulle korsfästas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Då togo landshöfdingens krigsknektar Jesum till sig, in på Rådhuset, och församlade hela skaran till honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Och afklädde honom, och klädde på honom en purpurmantel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Och vredo samman ena törnekrono, och satte på hans hufvud, och fingo honom en rö i sina högra hand, och böjde knä för honom, och begabbade honom, och sade: Hel Judarnas Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Och de spottade på honom, och togo rön, och slogo dermed hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Och när de hade begabbat honom klädde de mantelen af honom, och klädde på honom hans kläder, och ledde honom bort, till att korsfästan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Och när de gingo ut, funno de en man af Cyrene, som het Simon; honom tvingade de till att han skulle bära hans kors.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Och då de kommo till det rummet, som kallas Golgatha, det är, till hufvudskallaplatsen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Gåfvo de honom ättiko dricka, blandad med galla; och när han smakade det, ville han icke drickat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Men sedan de hade korsfäst honom, bytte de hans kläder, och kastade lott derom; på det fullbordas skulle det som sagdt var genom Propheten: De hafva bytt min kläder emellan sig, och på min klädnad hafva de kastat lott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Och de såto der, och togo vara på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Och de satte hans sak, skrifven öfver hans hufvud: Denne är Jesus, Judarnas Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Och då vordo två röfvare korsfäste med honom, den ene på den högra sidon, och den andre på den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Men de, som gingo der fram, hädde honom, och riste sin hufvud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'Och sade: Du, som bryter ned Guds tempel, och bygger det i tre dagar upp, hjelp dig sjelf; äst du Guds Son, så stig ned af korset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Sammaledes ock de öfverste Presterna, med de Skriftlärda och de äldsta, begabbade honom och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Andra hafver han hulpit, sig sjelf kan han icke hjelpa; är han Israels Konung, så stige nu ned af korset, och vi vilje tro honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Han hafver tröst på Gud; han frälse nu honom, om han är något om honom; ty han hafver sagt: Jag är Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Det samma kastade ock röfvarena honom före, som med honom korsfäste voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Och ifrå sjette timman vardt ett mörker öfver hela landet, intill nionde timman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Och vid den nionde timman ropade Jesus med höga röst, och sade: Eli, Eli, Lama Sabachthani? det är: Min Gud, min Gud, hvi hafver du öfvergifvit mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Men någre, som der stodo, när de det hörde, sade de: Han åkallar Elias.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Och straxt lopp en af dem, och tog en svamp, och fyllde honom med ättiko, och satte den på en rö, och gaf honom dricka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Men de andre sade: Håll, låt se om Elias kommer, och hjelper honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Åter ropade Jesus med höga röst, och gaf upp andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Och si, förlåten i templet remnade i tu stycker, ifrån ofvan och ned igenom; och jorden skalf, och hällebergen remnade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'Och grafvarna öppnades; och mång de heligas lekamen, som sofvit hade, stodo upp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'Och gingo ut af sina grafvar, efter hans uppståndelse, och kommo i den heliga staden, och uppenbarades mångom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Men höfvitsmannen, och de som med honom voro, och vaktade på Jesum, när de sågo jordbäfningen, och de ting som skedde, räddes de svårliga, och sade: Visserliga var denne Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Och der voro många qvinnor, ståndande långt ifrån, och sågo uppå, de som hade följt Jesum af Galileen, och tjent honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Ibland hvilka var Maria Magdalena, och Maria, Jacobi och Jose moder, och Zebedei söners moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Men om aftonen kom en rik man af Arimathia, benämnd Joseph, hvilken ock var Jesu Lärjunge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Han gick till Pilatum, och beddes Jesu lekamen; då böd Pilatus, att han skulle varda honom gifven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Och när Joseph hade tagit lekamen, svepte han honom i ett rent linkläde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'Och lade honom i sina nya graf, som han uthuggit hade uti ett hälleberg; och välte en stor sten för dörrena åt grafvene, och gick sina färde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Då voro der Maria Magdalena, och den andra Maria, sittande emot grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Dagen efter tillredelsedagen kommo tillsamman de öfverste Presterna, och de Phariseer, inför Pilatus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Och sade: Herre, oss kommer ihåg, att den förföraren sade, när han än lefde: Efter tre dagar vill jag stå upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Bjud fördenskull, att man förvarar grafvena, intill tredje dagen, att hans Lärjungar icke komma, och stjäla honom bort, och säga folkena: Han är uppstånden ifrån de döda; och blifver så den sista villan värre än den första.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Då sade Pilatus till dem: Der hafven I vaktena; går och förvarer, som I kunnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Då gingo de bort, och förvarade grafvena med väktare, och beseglade stenen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Om Sabbathsaftonen, i gryningen på första Sabbathen, kom Maria Magdalena, och den andra Maria, till att bese grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Och si, det vardt en stor jordbäfning; ty Herrans Ängel steg ned af himmelen, och gick fram, och välte stenen ifrå dörrene, och satte sig på honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Och han var påseendes som en ljungeld, och hans kläde hvit som en snö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Och väktarena blefvo förskräckte af räddhåga, och vordo som de hade varit döde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Men Ängelen svarade, och sade till qvinnorna: Rädens icke; ty jag vet, att I söken Jesum, som var korsfäster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Han är icke här; han är uppstånden, som han sagt hade; kommer, och ser rummet, der Herren var lagder uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Och går snart, och säger hans Lärjungom, att han är uppstånden ifrå de döda; och si, han skall gå fram för eder uti Galileen; der skolen I se honom; si, jag hafver sagt eder det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Och de gingo snarliga ifrå grafvene, med räddhåga och stor glädje, löpande, till att kungörat hans Lärjungom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Och vid de gingo, till att kungörat hans Lärjungom, si då mötte Jesus dem, och sade: Hel eder. Då gingo de fram, och togo på hans fötter, och tillbådo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Då sade Jesus till dem: Rädens icke; går, och kungörer det mina bröder, att de gå till Galileen; der skola de få se mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'När de gingo bort, si, någre af väktarena komma i staden, och kungjorde dem öfverste Prestomen allt det som skedt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Och de församlade sig med de äldsta, och rådgjorde; och gåfvo krigsknektarna en stor summo penningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'Och sade: Säger, hans Lärjungar kommo om nattena, och stulo honom bort, medan vi sofvo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Och om det kommer för landshöfdingan, vilje vi stilla honom, och begå det så, att I skolen vara utan fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Och de togo penningarna, och gjorde som de voro lärde. Och detta talet är beryktadt ibland Judarna, intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Men de ellofva Lärjungarna gingo till Galileen, upp på ett berg, som Jesus hade dem förelagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Och när de sågo honom, tillbådo de honom; men somlige tviflade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Och Jesus gick fram, och talade med dem, och sade: Mig är gifven all magt i himmelen, och på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Går fördenskull ut, och lärer all folk; och döper dem, i Namn Faders, och Sons, och dens Helga Andas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Och lärer dem hålla allt det jag hafver eder befallt; och si, jag är när eder alla dagar, intill verldenes ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Detta är begynnelsen af Jesu Christi, Guds Sons, Evangelio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Såsom skrifvet är i Propheterna: Si, jag sänder min Ängel framför ditt ansigte, hvilken bereda skall din väg för dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Ens ropandes röst är i öknene: Bereder Herrans väg; görer hans stigar rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Johannes var i öknene, döpte, och predikade bättringenes döpelse, till syndernas förlåtelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Och till honom gingo ut hela Judiska landet, och de utaf Jerusalem; och läto sig alle döpa af honom i Jordans flod, och bekände sina synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Och Johannes var klädd med camelahår, och med en lädergjording om sina länder; och åt gräshoppor och vildhannog;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Och predikade, och sade: En kommer efter mig, som starkare är än jag, hvilkens skotvänger jag icke värdig är att nederfalla och upplösa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Jag döper eder med vatten; men han skall döpa eder med dem Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Och det begaf sig i de dagar, att Jesus kom utaf Galileen ifrå Nazareth, och lät sig döpa af Johanne i Jordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Och straxt steg han upp utu vattnet, och såg himlarna öppnas, och Andan, såsom en dufvo, nederkomma öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Och en röst kom af himmelen: Du äst min käre Son, i hvilkom mig väl behagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Och Anden dref honom straxt uti öknena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Och han var i öknene i fyratio dagar, och frestades af Satana; och var med vilddjuren; och Änglarna tjente honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Men sedan Johannes vardt fången, kom Jesus uti Galileen, och predikade Evangelium om Guds rike,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Sägandes: Tiden är fullkomnad, och Guds rike är för handene; bättrer eder, och tror Evangelio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'När han gick utmed det Galileiska hafvet, såg han Simon, och Andream, hans broder, kasta sin nät i hafvet; ty de voro fiskare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Och Jesus sade till dem: Följer mig, och jag vill göra eder till menniskofiskare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Straxt gåfvo de sin nät öfver, och följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Och då han gick dädan litet fram bätter, såg han Jacobum, Zebedei son, och Johannem, hans broder, att de i båtenom byggde sin nät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Och straxt kallade han dem; då öfvergåfvo de sin fader, Zebedeum, uti båten, med legodrängarna, och följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Och de gingo till Capernaum; och straxt, om Sabbatherna, gick han in i Synagogon och lärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Och de förundrade storliga på hans lärdom; förty han lärde väldeliga, och icke såsom de Skriftlärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Och i deras Synagogo var en menniska besatt med den orena andan; och han ropade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'Och sade: Ack! hvad hafve vi med dig beställa, Jesu Nazarene? Äst du kommen till att förderfva oss? Jag vet ho du äst, nämliga den Guds Helige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Och Jesus näpste honom, sägandes: Tig, och gack ut af menniskone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Då ref den orene anden honom, och ropade högt, och for ut af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Och alle förundrade sig svårliga, så att de sporde hvarannan till, och sade: Hvad är detta? Hvad ny lärdom är detta? Ty han bjuder de orena andar med väldighet, och de lyda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Och hans rykte gick straxt allt omkring i Galilee gränsor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Och de gingo straxt utu Synagogon, och kommo uti Simons och Andree hus, med Jacobo och Johanne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Och Simons svära låg sjuk i skälfvo; och straxt sade de honom om henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Då gick han till och reste henne upp, och tog henne vid handena; och i det samma öfvergaf skälfvosjukan henne, och hon gick sedan och tjente dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Om aftonen, då solen nedergången var, hade de till honom allahanda sjuka, och dem som qvaldes af djeflar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Och hele staden var församlad för dörrena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Och han gjorde många helbregda, som kranke voro af allahanda sjukdom; och dref ut många djeflar, och tillstadde icke djeflarna tala; ty de kände honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Och om morgonen, ganska bittida för dag, stod han upp och gick ut; och Jesus gick bort uti ett öde rum, och der bad han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Och Simon kom efter farandes, och de med honom voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Och då de funno honom, sade de till honom: Alle söka dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Sade han dem: Låt oss gå uti nästa städerna, att jag ock der predikar; ty fördenskull är jag kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Och han predikade i deras Synagogor, öfver hela Galileen, och utdref djeflar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Och till honom kom en spitelsk man, och bad honom, föll på knä för honom, och sade till honom: Vill du, så kan du göra mig ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Då varkunnade sig Jesus öfver honom, och uträckte sina hand, och tog uppå honom, och sade: Jag vill, var ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Och när han det sagt hade, gick straxt spitelskan af honom, och han vardt ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Och Jesus hotade honom, och sänden straxt ifrå sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'Och sade honom: Se till, att du säger ingom detta; utan gack bort, och visa dig Prestenom, och offra, för din rening, det Mose budit hafver, till ett vittnesbörd öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Men då han utgången var, begynte han förkunna mycket, och berykta det som skedt var; så att han icke nu mer kunde uppenbarliga gå in uti staden, utan blef ute i öde rum; och de kommo till honom af alla ändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Och efter några dagar gick han åter in i Capernaum; och det spordes, att han var i huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Och straxt församlades der månge, så att de icke rum hade, icke heller utanför dörrene; och han hade tal för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Och de hade fram för honom en borttagnan, den der framburen var af fyra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Och då de icke kunde komma till honom, för folkets skull, refvo de taket på huset, der han var; och gjorde ett hål på taket, och med tåg släppte neder sängena, der den borttagne uti låg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'När Jesus såg deras tro, sade han till den borttagna: Min son, dina synder vare dig förlåtna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Så voro der någre utaf de Skriftlärde sittande, som tänkte i sin hjerta:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Hvi talar denne sådana hädelse? Ho kan förlåta synder, utan allena Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Och straxt Jesus förnam det i sinom anda, att de sådant tänkte vid sig sjelfva, sade han till dem: Hvi tänken I sådant i edor hjerta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Hvilket är lättare säga till den borttagna: Dina synder vare dig förlåtna; eller säga: Statt upp, och tag dina säng och gack?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Men på det I skolen veta, att menniskones Son hafver magt på jordene förlåta synder, sade han till den borttagna:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Dig säger jag: Statt upp; tag dina säng, och gack i ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Och straxt stod han upp, tog sina säng, och gick ut i allas deras åsyn; så att alle undrade storliga, och prisade Gud, sägande: Sådant såge vi aldrig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Och han gick åter ut till hafvet; och allt folket kom till honom, och han lärde dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Och då Jesus gick der fram, såg han Levi, Alphei son, sittandes vid tullen, och sade till honom: Följ mig. Och han stod upp, och följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Och det begaf sig, då han satt till bords i hans hus, såto ock desslikes månge Publicaner och syndare till bords med Jesu och hans Lärjungar; ty de voro månge, som hade följt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Och då de Skriftlärde och Phariseer sågo, att han åt med de Publicaner och syndare, sade de till hans Lärjungar: Hvi äter och dricker han med Publicaner och syndare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'När Jesus det hörde, sade han till dem: De der helbregda äro, behöfva icke läkare, utan de som kranke äro; jag är icke kommen till att kalla de rättfärdiga, utan syndare, till bättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Och Johannis lärjungar och de Phariseers fastade mycket; och de kommo, och sade till honom: Hvi fasta Johannis lärjungar och de Phariseers, och dine Lärjungar fasta intet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Sade Jesus till dem: Bröllopsfolket, kunna de fasta, så länge brudgummen är med dem? Så länge de hafva brudgummen när sig, kunna de icke fasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Men de dagar skola komma, att brudgummen skall varda ifrå dem tagen; och då skola de fasta i de dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Och ingen sömmar en klut af nytt kläde på gammalt kläde; förty han rifver dock det nya stycket ifrå det gamla, och hålet varder värre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Och ingen låter nytt vin i gamla flaskor; annars slår det nya vinet flaskorna sönder, och vinet spilles ut, och flaskorna förderfvas; utan nytt vin skall man låta i nya flaskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Och det begaf sig, att han på Sabbathen gick genom säd; och hans Lärjungar begynte, vid de gingo, taga af axen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Och de Phariseer sade till honom: Si, hvi göra de om Sabbathen det som icke lofligit är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Då sade han till dem: Hafven I aldrig läsit, hvad David gjorde, då honom omträngde, och var hungrig, han och de der med honom voro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Huru han gick in i Guds hus, under den öfversta Presten Abjathar, och åt skådobröden, hvilka ingom voro loflige äta, utan Prestomen; och gaf desslikes dem som med honom voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Och han sade till dem: Sabbathen är gjord för menniskones skull, och icke menniskan för Sabbathens skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Så är nu menniskones Son en Herre, desslikes ock öfver Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Och han gick åter in uti Synagogon; och der var en man, som hade ena bortvissnada hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Och de vaktade på honom, om han ock skulle bota honom om Sabbathen; på det att de skulle få anklaga honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Då sade han till mannen, som den vissna handen hade: Gack hitfram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Och sade till dem: Hvilketdera är lofligit, göra väl om Sabbathen, eller göra illa; hjelpa lifvet, eller dräpa? Då tigde de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Då såg han uppå dem med vrede, och förömkade sig öfver deras hjertas blindhet, och sade till mannen: Räck ut dina hand; och han räckte henne ut; och handen vardt honom färdig igen, såsom den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Men de Phariseer gingo ut, och höllo straxt råd med de Herodianer, emot honom, huru de kunde förgöra honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Men Jesus, med sina Lärjungar, gick afsides bort till hafvet; och honom följde ett stort tal folk, utaf Galileen, och utaf Judeen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Och utaf Jerusalem, och utaf Idumeen, och utaf hinsidon Jordan och de der bodde vid Tyrus och Sidon, en ganska stor hop folk, som kommo till honom, när de hörde af hans gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Och sade han till sina Lärjungar, att de skulle fly honom en båt, för folkets skull, att de icke skulle tränga honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Förty han gjorde många helbregda, så att de öfverföllo honom, och ville taga på honom, så månge som några plågo hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Och de orene andar, när de sågo honom, föllo de neder för honom, och ropade, sägande: Du äst Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Och han hotade dem hårdeliga, att de icke skulle uppenbara honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Och han steg upp på ett berg, och kallade till sig hvilka han ville; och de kommo till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Och då skickade han tolf, att de skulle vara med honom, och att han skulle utsända dem till att predika;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'Och att de skulle hafva magt till att bota sjukdomar och utdrifva djeflar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Och gaf Simon det namnet Petrus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Och Jacobus, Zebedei son, Johannes, Jacobs broder, och nämnde dem Boanerges, det är sagdt: Tordönsbarn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Och Andreas och Philippus, och Bartholomeus, och Mattheus, och Thomas, och Jacobus, Alphei son, och Thaddeus, och Simon Cananeus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'Och Judas Ischarioth, den honom ock förrådde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Och de kommo i huset; och folket församlade sig åter, så att de icke tid hade till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Och när de detta hörde, som honom åkomne voro, gingo de ut, och ville taga fatt på honom, och sade: Han kommer ifrå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Men de Skriftlärde, som af Jerusalem nederkomne voro, sade: Han hafver Beelzebub, och med den öfversta djefvulen drifver han djeflar ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Då kallade han dem till sig, och sade till dem i liknelser: Huru kan en Satan den andra utdrifva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Och om ett rike söndradt varder emot sig sjelft, då kan det riket icke stå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Och der ett hus är söndradt emot sig sjelft, det huset kan icke blifva ståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Sätter nu Satan sig upp emot sig sjelf, och är söndrad, då kan han icke blifva beståndandes, utan det är då ute med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Ingen kan infalla uti en starks hus, och taga hans hustyg bort, utan han först binder den starka; och så skinnar han hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Sannerliga säger jag eder: Alla synder varda menniskors barnom förlåtna; ock försmädelse, dermed de försmäda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Men den der försmäder den Heliga Anda, han hafver ingen förlåtelse i evig tid, utan blifver saker till evig fördömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Ty de sade: Han hafver den orena andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Och då kommo hans bröder och hans moder, och stodo ute, och sände några till honom, som honom utkalla skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Och folket satt när honom, och de sade till honom: Si, din moder och dine bröder äro derute, och söka efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Han svarade dem, och sade: Ho är min moder och mine bröder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Och då han omkringsett hade på Lärjungarna, som der kringom honom såto, sade han: Si, min moder och mine bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Ty den som gör Guds vilja, han är min broder, och min syster, och min moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Och han begynte åter lära vid hafvet; och till honom församlades mycket folk, så att han måste stiga uti ett skepp, och satt der på hafvet; och allt folket blef på landet vid hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Och han lärde dem mycket genom liknelser; och sade till dem uti sin predikan:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Hörer till: Si, en sädesman gick ut till att så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Och hände sig, vid han sådde, föll somt vid vägen; och foglarna under himmelen kommo, och åto det upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Men somt föll på stenören, der icke mycken jord var; och det gick straxt upp, ty der var icke djup jord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Men då solen gick upp, förvissnade det; och efter det var icke väl berotadt, förtorkades det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Och somt föll i törne; och törnen växte upp, och förqvafde det; och det bar ingen frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Och somt föll i goda jord, och det bar frukt, som uppgick, och växte; ett bar tretiofaldt, och ett sextiofaldt, och ett hundradefaldt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Och han sade till dem: Den der öron hafver till att höra, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Då han nu allena var, sporde de, som med honom voro med de tolf, honom till om den liknelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Och han sade till dem: Eder är gifvet att veta Guds rikes hemlighet; men dem der utantill äro sker all ting genom liknelser;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'På det de skola med seende ögon se, och dock icke förnimmat; och med hörande öron höra, och dock icke förståt; på det de sig icke ens skola omvända, och synderna dem förlåtna varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Och han sade till dem: Förstån I icke denna liknelsen? Huru viljen I då förstå alla liknelser?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Sädesmannen sår ordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Men desse äro de som vid vägen äro, der ordet sådt varder; och de hafva det hört, straxt kommer Satan, och tager bort ordet, som sådt var i deras hjertan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Alltså äro ock de som på stenören sådde äro; då de hafva hört ordet, anamma de det straxt med fröjd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Och de hafva inga rötter i sig, utan stå till en tid; då någor bedröfvelse kommer uppå, eller förföljelse, för ordets skull, straxt förargas de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Och desse äro de som i törne sådde äro; de der höra ordet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Och denna verldenes omsorger, och de bedrägelige rikedomar, och mycken annor begärelse, gå derin, och förqväfva ordet, och det varder ofruktsamt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Och desse äro de som uti goda jord sådde äro; de der ordet höra, och anammat, och bära frukt, somt tretiofaldt, och somt sextiofaldt, och somt hundradefaldt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Och han sade till dem: Icke varder ett ljus upptändt fördenskull, att man skall sätta det under ena skäppo, eller under bordet? Sker det icke fördenskull, att det skall uppsättas på ljusastakan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Ty intet är fördoldt, som icke uppenbaras skall; ej heller hemligit, som icke skall uppkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Den der öron hafver till att höra, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Och han sade till dem: Ser till, hvad I hören: Med hvad mått I mälen, der skola andra mäla eder med; och eder varder ändå tillgifvet, I som hören detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Ty den der hafver, honom varder gifvet; och den der icke hafver, af honom skall ock taget varda det han hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Och han sade: Så är Guds rike, som en man kastar ena säd i jordena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'Och sofver, och står upp, natt och dag; och säden går upp, och växer, så att han der intet af vet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Ty jorden bär utaf sig sjelf, först brodd, sedan ax, sedan fullbordadt hvete i axena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'När nu frukten mogen är, straxt brukar han lian; ty skördetiden är för handen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Och han sade: Vid hvem skole vi likna Guds rike? Och med hvad liknelse skole vi beteckna det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Det är såsom ett senapskorn, hvilket, då det sådt varder i jordena, är det mindre än all annor frö på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Och då det sådt är, går det upp, och varder större än all annor krydder, och får stora grenar, så att foglarna under himmelen måga bo under dess skugga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Och med mång sådana liknelser sade han dem ordet, efter som de förmådde hörat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Och utan liknelse talade han intet till dem; men Lärjungomen uttydde han all ting afsides.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Och den samma dagen, då aftonen vardt, sade han till dem: Låt oss fara utöfver, på den andra stranden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Så läto de folket gå, och togo honom, med skeppet der han redo uti var; voro ock desslikes någor annor skepp med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Och der uppväxte en stor storm, och vågen slog in i skeppet, så att det förfylldes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Och han sof bak i skeppet på ett hyende; då väckte de honom upp, och sade till honom: Mästar, sköter du intet derom, att vi förgås?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Och då han uppväckt var, näpste han vädret, och sade till hafvet: Tig, och var stilla. Och vädret saktade sig, och vardt ett stort lugn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Och han sade till dem: Hvarföre ären I så rädde? Huru kommer det till, att I icke hafven trona?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Och de vordo ganska förskräckte, och sade emellan sig: Ho är denne? Ty vädret och hafvet äro honom lydig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Så kommo de öfver hafvet, in i de Gadareners ängd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Och straxt han steg utu skeppet, lopp emot honom, utu grifter, en man besatt med den orena andan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Den der plägade bo uti grifter; och ingen kunde honom binda med kedjor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Förty han hade många resor varit bunden med fjettrar och kedjor; och kedjorna voro sletna af honom, och fjettrarna sönderslagne; och ingen kunde späka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Och han var alltid, dag och natt, på bergen, och i grifterna, ropade och slog sig sjelf med stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Då han nu såg Jesum fjerran ifrå sig, lopp han till, och föll neder för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'Och ropade med höga röst, och sade: Hvad hafver jag med dig göra, Jesu, den högstas Guds Son? Jag besvär dig vid Gud, att du icke qväl mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Då sade han till honom: Far ut af menniskone, du orene ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Och sporde han honom: Hvad är ditt namn? Svarade han och sade: Legio är mitt namn; förty vi äre månge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Och han bad honom storliga, att han icke skulle drifva honom bort utu den ängden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Och der var vid bergen en stor svinahjord, den der gick och födde sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Och djeflarna bådo honom alle, sägande: Sänd oss i svinen, att vi må fara in uti dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Och Jesus tillstadde dem det straxt. Och de orene andar drogo straxt ut, och foro in uti svinen; och hjorden brådstörte sig i hafvet; och de voro vid tutusend, och vordo fördränkte i hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Men de, som skötte svinen, flydde och förkunnade det in i staden, och på bygdene; och de gingo ut till att se hvad skedt var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Och kommo till Jesum, och sågo honom, som hade besatt varit, och haft legionen, sittandes kläddan, och vid sin skäl; och vordo förfärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Och de som det sett hade, förtäljde dem hvad den besatta vederfaret var, och om svinen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Och de begynte bedja honom, att han skulle draga utu deras ängd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Och då han var stigen till skepps, bad honom den som hade besatt varit, att han måtte vara när honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Men Jesus tillstadde det icke, utan sade till honom: Gack dina färde uti ditt hus till dina, och förkunna dem, huru stor ting Herren hafver gjort med dig, och hafver miskundat sig öfver dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Och han gick sina färde, och begynte förkunna uti de tio städer, huru stor ting Jesus med honom gjort hade. Och alle förundrade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Och då Jesus var öfverfaren igen med skeppet, församlades till honom mycket folk; och var vid hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Och si, der kom en af Synagogones öfverstar, benämnd Jairus; och då han fick se honom, föll han ned för hans fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Och bad honom storliga, och sade: Min dotter är i sitt yttersta; jag beder dig, att du kommer, och lägger händer på henne, att hon måtte vederfås, och lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Och han gick med honom; och honom följde mycket folk, och de trängde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Och der var en qvinna, som hade haft blodgång i tolf år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Och hade mycket lidit af mångom läkarom, och förtärt dermed allt sitt, och hade dock ingen hjelp förnummit; utan det vardt heldre värre med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Då hon hörde om Jesu, kom hon ibland folket bakefter, och tog på hans kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Ty hon sade: Kunde jag åtminstone taga på hans kläder, då vorde jag helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Och straxt förtorkades hennes blods källa; och hon kände det i kroppen, att hon botad var utaf den plågon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Och Jesus kändet straxt i sig sjelf, att kraft utgången var af honom; och vände sig om ibland folket, och sade: Ho kom vid min kläder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Och hans Lärjungar sade till honom: Ser du icke, folket tränger dig på alla sidor, och du säger: Ho kom vid mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Och han såg omkring efter henne, som det gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Men qvinnan fruktade och bäfvade; ty hon visste, hvad med henne skedt var; och kom, och föll neder för honom, och sade honom alla sanningena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Då sade han till henne: Dotter, din tro hafver gjort dig helbregda; gack med frid, och var helbregda af dine plågo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Vid han ännu talade, kommo någre ifrå Synagogones öfversta, och sade: Din dotter är död; hvi gör du Mästaren yttermera omak?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Men straxt Jesus hörde talet, som sades, sade han till Synagogones öfversta: Frukta dig intet; allenast tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Och han tillstadde icke, att honom någor följa skulle, förutan Petrus och Jacobus, och Johannes, Jacobi broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Och så kom han i Synagogones öfverstas hus, och fick se sorlet, och dem som mycket sörjde och greto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Och han gick in, och sade till dem: Hvad sorlen I, och gråten? Pigan är icke död; men hon sofver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Och de gjorde gäck af honom. Då dref han alla ut, och tog med sig pigones fader och moder, och dem som med honom voro, och gick in der pigan låg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Och fattade pigona vid handena, sägande till henne: Talitha kumi; det uttydes: Piga, jag säger dig, statt upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Och straxt stod pigan upp, och gick; och hon var vid tolf år gammal. Och de vordo öfvermåtton förskräckte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Och han förböd dem strängeliga, att ingen skulle det veta; och böd gifva henne äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Och han gick ut dädan, och kom in uti sitt fädernesland; och hans Lärjungar följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Och när Sabbathen kom, begynte han lära i Synagogon; och månge, som det hörde, förundrade sig storliga, sägande: Hvadan kommer honom detta? Och hvad visdom är denne, som honom gifven är, och sådana krafter, som ske igenom hans händer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Är icke denne den timbermannen, Marie Son, Jacobi broder, och Jose, och Jude och Simons? Äro ock icke hans systrar här när oss? Och de förargades på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Då sade Jesus till dem: En Prophet varder icke föraktad, utan i sitt fädernesland, och ibland sina fränder, och sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Och han kunde der ingen kraft göra, utan det att han lade händerna på några få sjuka, och botade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Och han förundrade sig på deras otro; och han gick omkring i byarna allestäds deromkring, och lärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Och han kallade för sig de tolf, tog till att utsända dem, två och två; gifvandes dem magt emot de orena andar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Och böd dem, att de intet skulle taga med sig till vägs, utan käppen allena; icke skräppo, icke bröd, inga penningar i pungen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Utan de skulle vara skodde; och att de icke skulle kläda sig uti två kjortlar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Och sade till dem: Hvar som helst I ingån uti ett hus, blifven der, tilldess I dragen dädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Och hvilken som icke anammar eder, eller icke hörer eder, går derut, och skudder af eder det stoft, som är under edra fötter till vittnesbörd öfver dem. Sannerliga säger jag eder: Drägeligare varder Sodome och Gomorre på domedag, än dem stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Och de gingo ut, och predikade, att man skulle bättra sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Och utdrefvo många djeflar, och smorde många kranka med oljo, och botade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Och fick Konung Herodes detta höra; ty hans namn var redo kunnigt; och sade: Den Johannes, som döpte, är uppstånden ifrå de döda; och derföre gör han sådana krafter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Somlige sade: Det är Elias; och somlige sade: Det är en Prophet, eller såsom en af Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Då Herodes sådant hörde, sade han: Denne är Johannes, som jag halshögg; han är uppstånden ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Ty Herodes hade sändt bort, och låtit gripa Johannes, och satt honom i fängelse, för Herodias, sins broders Philippi hustrus skull; ty han hade tagit henne till hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Men Johannes sade till Herodes: Dig är icke lofligit att hafva dins broders hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Men Herodias gick efter hans argesta, och hade gerna dräpit honom; och kunde dock icke komma dess vid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Ty Herodes fruktade Johannem, vetandes att han var en from och helig man; och aktade honom, och lydde honom i mång stycke, och hörde honom gerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Då nu en belägen dag kom, att Herodes på sin födelsedag gaf de öfversta, och höfvitsmän, och de yppersta i Galileen, en aftonkost;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Gick Herodias dotter in, och dansade, och det behagade Herodi, och dem der med honom såto vid bordet. Då sade Konungen till pigona: Bed utaf mig hvad du vill, jag vill gifva dig det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Och svor henne en ed; Hvad du bedjande varder af mig, vill jag gifva dig, allt intill hälften af mitt rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Hon gick ut, och sade till sina moder: Hvad skall jag bedja? Hon sade: Johannis Döparens hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Och hon gick straxt med hast in till Konungen, och bad, sägandes: Jag vill, att du gifver mig nu straxt, på ett fat, Johannis Döparens hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Då vardt Konungen bedröfvad; dock, för edens skull, och för deras skull, som der såto vid bordet, ville han icke visa henne af;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Utan straxt sände Konungen bödelen, och böd inhemta hans hufvud. Han gick åstad, och halshögg honom i fångahuset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Och bar fram hans hufvud på ett fat, och fick pigone; och pigan fick det sine moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Då hans lärjungar det sporde, kommo de, och togo hans lekamen upp, och begrofvo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Och Apostlarna församlades till Jesum, och förkunnade honom all stycke; och hvad de gjort och lärt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Då sade han till dem: Kommer I allene afsides med mig uti ödemarken, och hviler eder något litet; ty der voro månge, som gingo till och ifrå, så att de hade icke tid till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Och så for han bort afsides till skepps uti ödemarken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Och folket såg, att de foro sina färde; och månge kände honom, och lupo dit tillsammans af alla städer, till fot, och kommo fram förr än de, och församlades till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Så gick Jesus ut, och fick se det myckna folket, och varkunnade sig öfver dem; förty de voro såsom får, de ingen herdan hade; och begynte lära dem mycket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Och då nu dagen var fast framliden, gingo hans Lärjungar till honom, och sade: Här är öknen, och tiden är fast förliden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Släpp dem ifrå dig, att de måga gå bort i byarna och torpen här omkring, och köpa sig bröd; ty de hafva intet äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Då svarade han dem, och sade: Gifver I dem äta. Då sade de till honom: Skole vi gå bort, och köpa för tuhundrade penningar bröd, och gifva dem äta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Då sade han till dem: Huru mång bröd hafven I? Går, och ser till. Och sedan de hade sett till, sade de: Fem, och två fiskar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Då böd han dem, att de skulle sätta sig alle i matskap, i gröna gräset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Och de satte sig i hopar, hundrade och hundrade, femtio och femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Och så tog han de fem bröd och de två fiskar; och upplyfte sin ögon till himmelen, tackade, och bröt bröden, och fick sinom Lärjungom, att de skulle lägga för dem; och de två fiskar bytte han emellan dem alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Och de åto alle, och vordo mätte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Och togo sedan upp tolf korgar fulla med styckom, och fiskomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Och de der ätit hade, voro vid femtusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Och straxt dref han sina Lärjungar, att de skulle gå till skepps, och fara för honom öfver hafvet till Bethsaida, medan han skiljde folket ifrå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Och när han hade skiljt dem ifrå sig, gick han dädan upp på ett berg, till att bedja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Och då aftonen kom, var skeppet midt på hafvet, och han på landet allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Och han såg att de hade plats med roende; ty vädret var dem emot. Och vid fjerde väkten om nattena kom han till dem, gångandes på hafvet; och han ville gå framom dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Och när de sågo honom gångandes på hafvet, mente de det hade varit ett spökelse, och ropade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Ty de sågo honom alle, och vordo förskräckte. Då talade han dem straxt till, och sade till dem: Varer vid en god tröst, jag äret; varer icke rädde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Och han steg upp till dem i skeppet, och vädret stillade sig; och de vordo storliga förskräckte, förundrande vid sig sjelfva öfvermåtton.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Ty de hade icke fått förstånd af bröden; ty deras hjerta var förblindadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Och då de öfverfarne voro, kommo de till det landet Genesaret, och lade der i hamn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Och när de gingo utu skeppet, kände de honom straxt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Och lupo omkring allan den landsändan; och begynte omkringföra de sjuka på sängar, dit de hörde han var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Och hvar han ingick, i byar, eller städer, eller torp, der lade de kranka på gatorna, och bådo honom, att de åtminstone måtte taga på hans klädefåll; och så månge, som kommo vid honom, de vordo helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Och till honom församlades de Phariseer, och någre af de Skriftlärda, som ifrå Jerusalem komne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Och då de fingo se, att somlige hans Lärjungar åto bröd med menliga, det är, med otvagna händer, straffade de det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Ty de Phariseer och alle Judar äta icke, utan de alltid två händerna, hållande de äldstas stadgar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Och när de komne äro utaf torget, äta de icke, utan de äro tvagne. Och mycket sådant är, som de hafva tagit sig uppå att hålla, som är, att två dryckekar, och krukor, och kopparkar, och bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Sedan frågade honom de Phariseer och de Skriftlärde: Hvi vandra icke dine Lärjungar efter de stadgar, som de äldste uppåbudit hafva; utan äta bröd med otvagna händer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Då svarade han, och sade till dem: Väl hafver Esaias propheterat om eder, I skrymtare, som skrifvet är: Detta folket ärar mig med läpparna; men deras hjerta är långt ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Men fåfängt dyrka de mig, lärande den lärdom, som är menniskors bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Ty I bortkasten Guds bud, och hållen menniskors stadgar, som är, att två krukor, och dryckekar; och mycket sådant gören I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Och han sade till dem: Skönliga bortkasten I Guds bud, på det att I skolen hålla edar stadga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Ty Mose hafver sagt: Ära din fader och dina moder; och: Den der bannar fader eller moder, han skall döden dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Men I sägen: En menniska må säga till fader och moder: Corban; det är sagdt: Gudi är det gifvet, som dig af mig skulle hafva kommit till nytto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Och tillåten så icke, att han något gör sinom fader, eller sine moder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Och gören Guds ord omintet med edar stadga, som I uppålagt hafven. Och mycket sådant gören I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Och han kallade till sig allt folket, och sade till dem: Hörer mig alle, och förstår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Intet går utanefter in i menniskona, det henne besmitta kan; men det som går utaf menniskone, det är det som besmittar menniskona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Den der hafver öron till att höra, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Och då han skiljdes ifrå folket, och kom i huset, frågade hans Lärjungar honom om liknelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Och han sade till dem: Ären I också oförståndige? Förstån I icke ännu, att allt det utanefter ingår i menniskona, det kan icke besmitta henne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Ty det går icke in i hennes hjerta, utan i buken; och hafver sin naturliga utgång, der all mat med rensas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Och han sade: Det utaf menniskone går, det besmittar menniskona;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Ty innanefter, utu menniskors hjerta, utgå onda tankar, hor, boleri, mandråp,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Stöld, girighet, svek, listighet, otuktighet, ondt öga, hädelse, högfärd, galenskap;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'All denna onda stycke gå innanefter ut, och de besmitta menniskona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Så stod han upp dädan, och gick in i Tyri och Sidons gränsor; och gick in uti ett hus, och ville att det ingen veta skulle; och kunde dock icke blifva fördold.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Ty en qvinna, hvilkens dotter hade en oren anda, straxt hon fick höra om honom, kom hon, och föll ned för hans fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Och det var en Grekisk qvinna, utaf Syrophenice, och bad honom, att han ville utdrifva djefvulen af hennes dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Men Jesus sade till henne: Låt barnen först mätta varda; det är icke höfveligit, att man tager barnens bröd och kastar för hundarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Då svarade hon, och sade till honom: Ja, Herre; dock äta hundarna, under bordet, utaf barnens smulor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Då sade han till henne: För detta talets skull, gack; djefvulen är utgången af dine dotter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Och då hon kom i sitt hus, fann hon djefvulen utgången vara, och dottrena liggande på sängene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Och då han åter utgick ifrå Tyri och Sidons gränsor, kom han till det Galileiska hafvet, midt genom de landsändar vid de tio städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Och de hade fram för honom en döfvan, den der ock en dumbe var; och bådo honom, att han ville lägga handena på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Då tog han honom afsides ut ifrå folket, och satte sina finger i hans öron, och spottade ut, dermed han tog på hans tungo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'Och såg upp i himmelen, suckade, och sade till honom: Hephethah; det är sagdt: Upplåt dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Och straxt öppnades hans öron, och hans tungos band vardt löst, och han talade redeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Och böd han dem, att de skulle ingom sägat; men ju mer han det förböd, ju mer de förkunnade det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Och de förundrade sig öfvermåtton, sägande: Allt hafver han väl beställt; de döfva låter han höra, och dumbar tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Uti de dagar, då folket var ganska mycket, och hade intet det de äta kunde, kallade Jesus till sig sina Lärjungar, och sade till dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Jag varkunnar mig öfver folket; ty de hafva nu i tre dagar töfvat när mig, och hafva intet äta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Och om jag låter dem fastande gå hem, gifvas de upp i vägen; ty somlige utaf dem voro komne långväga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Och hans Lärjungar svarade honom: Hvar tager man bröd här i öknene, der man dem med mätta kan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Då sporde han dem: Huru mång bröd hafven I? Svarade de: Sju.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Och han böd folket sätta sig ned på jordena; och han tog de sju bröd, tackade, bröt, och gaf sina Lärjungar; att de skulle lägga dem fram; och de lade fram för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Hade de ock några små fiskar; och då han välsignat hade, bad han ock lägga dem fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Så åto de, och vordo mätte; och de togo upp sju korgar med aflefvor, som öfver voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Och de der ätit hade, voro vid fyratusend; och så lät han fara dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Och straxt steg han till skepps med sina Lärjungar, och kom intill de landsändar Dalmanutha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Och de Phariseer gingo ut, och begynte disputera med honom, frestande honom, och begärande af honom tecken af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Då suckade han i sinom Anda, och sade: Hvi söker detta slägtet tecken? Sannerliga säger jag eder: Desso slägte skall intet tecken gifvas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Så gaf han dem öfver; och gick åter i skeppet, och for utöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Och de hade förgätit taga bröd, så att de hade icke mer än ett bröd med sig i skeppet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Då böd han dem, sägandes: Ser till, vakter eder för de Phariseers surdeg, och för Herodis surdeg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Och de tänkte hit och dit, sägande emellan sig: Det äret, vi hafve intet bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Då Jesus det förnam, sade han till dem: Hvad bekymren I eder, att I hafven icke bröd? Kunnen I ännu intet akta, eller förstå? Hafven I ännu edor hjerta förblindadt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Hafvandes ögon, och sen intet? och hafvandes öron, och hören intet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Och minnens I icke, då jag bröt fem bröd ibland femtusend, huru många korgar upptogen I fulla med aflefvor? Sade de: Tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Och då jag bröt sju bröd ibland fyratusend, huru många korgar upptogen I utaf de aflefvor? De sade: Sju.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Och han sade till dem: Hvi förstån I då intet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Och han kom till Bethsaida; och de hade fram för honom en blindan, och bådo honom, att han ville taga på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Och så tog han den blinda vid handena, och ledde honom utu byn; och spottade i hans ögon, och lade händer på honom, och frågade honom, om han något såg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Då såg han upp, och sade: Jag ser folket gå, lika som det vore trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Sedan lade han åter händerna på hans ögon, och gjorde det så att han fick synen igen; och vardt så botad, att han sedan såg klarliga alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Och han lät gå honom hem, och sade: Gack intet in i byn, och säg icke heller det någrom derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Och Jesus gick ut, och hans Lärjungar, till de byar vid Cesarea, som kallas Philippi; och i vägen frågade han sina Lärjungar, sägandes till dem: Hvem säger folket mig vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'De svarade: Johannes Döparen; och somlige Elias; och somlige en af Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Då sade han till dem: Hvem sägen I mig vara? Svarade Petrus, och sade till honom: Du äst Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Då hotade han dem, att de skulle ingom säga om honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Och begynte till att undervisa dem, att menniskones Son skulle mycket lida, och förkastas af de äldsta, och af de öfversta Presterna, och af de Skriftlärda, och dödas; och efter tre dagar uppstå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Och talade han det talet uppenbart. Då tog Petrus honom till sig, och begynte näpsa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Då vände han sig om, och såg på sina Lärjungar, och näpste Petrum, sägandes: Gack bort ifrå mig, du Satan; ty du besinnar icke det Gudi tillhörer, utan det menniskor tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Och kallade han till sig folket, med sina Lärjungar, och sade till dem: Den mig vill följa, han försake sig sjelf, och tage sitt kors uppå sig, och följe mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Ty den, som vill behålla sitt lif, han skall mista det; och den som mister sitt lif, för mina och Evangelii skull, han skall det behålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Ty hvad hjelper det menniskone, om hon kunde vinna hela verldena, och toge skada till sin själ?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Eller hvad kan en menniska gifva, der hon sin själ med lösa må?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Men den som blyges vid mig och min ord, uti detta horiska och syndiga slägtet, vid honom skall ock menniskones Son blygas, när han kommer i sins Faders härlighet, med de helga Änglar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Och han sade till dem: Sannerliga säger jag eder, någre äro ibland dem som här stå, de der icke skola smaka döden, tilldess de få se Guds rike komma med kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Och efter sex dagar tog Jesus Petrum, Jacobum och Johannem till sig; och hade dem allena upp på ett högt berg afsides, och vardt förklarad för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Och hans kläder vordo klar, och ganska hvit såsom snö, att ingen färgare på jordene kan göra dem så hvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Och dem syntes Elias med Mose, och de talade med Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Då svarade Petrus, sägandes till Jesum: Rabbi, här är oss godt att vara; låt oss göra här tre hyddor, dig en, Mosi en, och Elie en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Men han visste icke hvad han sade; ty de voro häpne vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Och en sky kom, som öfverskyggde dem; och en röst kom utaf skyn, och sade: Denne är min käre Son; honom hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Och i det samma som de sågo sig om, sågo de ingen vara der när dem, utan allena Jesus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Men då de gingo neder af berget, böd han dem, att de skulle ingom säga hvad de sett hade, förr än menniskones Son vore uppstånden ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Och de behöllo det ordet när sig, och befrågade emellan sig, hvad det skulle vara, att han sade: uppstå ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Och de sporde honom, sägande: Hvad är det, som de Skriftlärde säga, att Elias måste komma först?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Men han svarade, och sade till dem: Elias skall ju komma först, och sätta all ting i lag igen; och att menniskones Son skall mycket lida, och föraktad varda, såsom skrifvet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Men jag säger eder: Elias är kommen, och de gjorde honom allt det de ville, såsom skrifvet var om honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Då han kom till sina Lärjungar, såg han mycket folk omkring dem, och de Skriftlärda disputerande med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Och straxt allt folket såg honom, vordo de häpne; och lupo till och helsade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Och han sporde de Skriftlärda: Hvad disputeren I med dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Och en af folket svarade, och sade: Mästar, jag hafver haft min son hit till dig, den der hafver en stum anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Och då han tager honom fatt, far han illa med honom; och han fradgas, och gnisslar med sina tänder, och förtvinar. Jag talade med dina Lärjungar, att de skulle drifva honom ut; och de kunde icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Då svarade han honom, och sade: O I otrogna slägte; huru länge skall jag vara när eder? Huru länge skall jag lida eder? Leder honom hit till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Och de ledden fram till honom. Då anden fick se honom, straxt for han illa med honom; och föll neder på jordena, och välte sig, och fradgades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Då sporde han hans fader till: Huru länge är, sedan detta kom honom uppå? Då sade han: Utaf barndom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Och han hafver ofta kastat honom i elden, och i vattnet, att han måtte förgöra honom; men förmår du något, så varkunna dig öfver oss, och hjelp oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jesus sade till honom: Om du tro kan; all ting äro möjelig honom, som tror.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Och straxt ropade drängens fader, med gråtande tårar, sägandes: Herre, jag tror; hjelp mina otro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'När Jesus såg, att folket lopp till med, näpste han den orena andan, och sade till honom: Du ande, döfver och dumbe, jag bjuder dig, gack ut af honom, och gack intet mer härefter in uti honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Så ropade anden, och for ganska illa med honom, och gick ut. Och han vardt som han hade varit död; så att månge sade: Han är död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Då tog Jesus honom vid handena, och reste honom upp; och han stod upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Och när han kom hem i huset, frågade hans Lärjungar honom afsides: Hvi förmådde icke vi utdrifva honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Sade han till dem: Detta slägtet kan med ingen ting utfara, utan med bön och fasto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Och de gingo dädan, och vandrade genom Galileen; och han ville icke, att någor skulle vetat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Ty han underviste sina Lärjungar, och han sade till dem: Menniskones Son skall varda öfverantvardad i menniskors händer, och de skola döda honom; och då han är dödad, skall han på tredje dagen uppstå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Men de förstodo intet hvad han sade, och torde icke spörja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Så kom han till Capernaum; och när han var kommen i huset, sporde han dem: Hvad handladen I eder emellan i vägen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Men de tigde; förty de hade handlat emellan sig i vägen, hvilken af dem ypperst var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Och då han hade satt sig, kallade han de tolf, och sade till dem: Hvilken som vill den främste vara, han skall vara ytterst af allom, och allas tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Och så tog han ett barn, och ställde det midt ibland dem. Och då han hade tagit det i sin famn, sade han till dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Hvilken som anammar ett sådant barn i mitt Namn, han anammar mig; och hvilken mig anammar, han anammar icke mig, utan honom som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Men Johannes svarade honom, sägandes: Mästar, vi sågom en utdrifva djeflar uti ditt Namn, och han följer oss icke; och vi förböde honom det, efter han icke följer oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Då sade Jesus: Förbjuder honom icke; ty ingen är den som gör krafter i mitt Namn, som snarliga kan tala ondt på mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Förty den der icke är emot oss, han är med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Men hvilken som gifver eder dricka en bägare vatten, i mitt Namn, derföre att I Christo tillhören, sannerliga säger jag eder, han skall ingalunda mista sin lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Och hvilken som förargar en af de små, som tro på mig, bättre vore honom, att vid hans hals hängdes en qvarnsten, och han bortkastades uti hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Nu, om din hand vore dig till förargelse, hugg henne af. Bättre är dig enhändtan ingå uti lifvet, än att du hafver två händer, och far till helvetet, uti evig eld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Der deras matk icke dör, och elden icke utsläckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Och om din fot vore dig till förargelse, hugg honom af. Dig är bättre, att du ingår uti lifvet halter, än att du hafver två fötter, och varder kastad till helvetet, uti evig eld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Der deras matk icke dör, och elden icke utsläckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Och om ditt öga vore dig till förargelse, rif det ut. Bättre är dig, att du enögder ingår uti Guds rike, än att du skulle hafva tu ögon, och bortkastas i helvetes eld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'Der deras matk icke dör, och elden icke utsläckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Ty hvar och en måste med eld saltad varda, och allt offer måste med salt saltas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Salt är ett godt ting; hvar nu saltet mister sin sälto, hvarmed skall man salta? Hafver salt uti eder, och hafver frid emellan eder inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Och då han stod upp dädan, kom han uti Judee landsändar, vid sidon af Jordan. Och folket församlades åter till honom; och åter lärde han dem, såsom hans seder var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Då gingo de Phariseer till, och frågade honom: Är det ock mannenom lofligit skilja sina hustru ifrå sig? frestande honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Då svarade han, och sade till dem: Hvad hafver Mose budit eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Sade de: Mose tillstadde skrifva ett skiljobref, och öfvergifva henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Svarade Jesus, och sade till dem: För edor hjertas hårdhets skull skref han eder detta budet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Men af första skapelsen hafver Gud gjort dem man och qvinno;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Fördenskull skall man öfvergifva sin fader och moder, och blifva vid sina hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Och de tu varda ett kött; så äro de nu icke tu, utan ett kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Hvad Gud hafver tillhopafogat, det skall menniskan icke åtskilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Och i huset frågade hans Lärjungar honom på nytt om samma ärende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Och han sade till dem: Hvilken som skiljer sina hustru ifrå sig, och tager ena andra, han bedrifver hor emot henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Och om qvinnan öfvergifver sin man, och tager en annan, hon bedrifver hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Och de hade barn till honom, att han skulle taga på dem; men Lärjungarna näpste dem, som dem fram hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Men när Jesus det såg, vardt han misslynt, och sade till dem: Låter barnen komma till mig, och förmener dem icke; ty sådana hörer Guds rike till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Sannerliga säger jag eder; Hvilken som icke undfår Guds rike såsom ett barn, han kommer der aldrig in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Och han tog dem upp i famnen, och lade händerna på dem, och välsignade dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Och då han dädan utgången var på vägen, lopp en till, och föll på knä för honom, och frågade honom: Gode Mästar, hvad skall jag göra, att jag måtte få evinnerligit lif?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Men Jesus sade till honom: Hvi kallar du mig godan? Ingen är god utan en, det är Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Budorden vetst du: Du skall icke bedrifva hor: Du skall icke dräpa: Du skall icke stjäla: Du skall icke tala falskt vittnesbörd: Du skall ingen bedraga: Ära din fader och moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Då svarade han, och sade till honom: Mästar, det hafver jag allt hållit utaf min ungdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jesus såg på honom, och älskade honom, och sade till honom: Ett fattas dig; gack bort, sälj allt det du hafver, och gif de fattiga, och du skall få en skatt i himmelen; och kom, följ mig, och tag korset uppå dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Och han vardt bedröfvad af talet, och gick bort sörjandes; ty han hade många ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Och Jesus såg sig om, och sade till sina Lärjungar: Huru svårliga kunna de rike komma in uti Guds rike!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Men hans Lärjungar vordo förskräckte af hans ord. Då svarade åter Jesus, och sade till dem: Huru svårt är det, kära barn, dem som sätta sina tröst på sina rikedomar, ingå uti Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Lättare är en camel gå igenom ett nålsöga, än en rik gå in uti Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Men de förundrade sig öfvermåtton, och sade vid sig sjelfva: Ho kan då varda salig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Men Jesus såg på dem, och sade: För menniskom är det omöjeligit; men icke för Gud; ty när Gudi äro all ting möjelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Och Petrus begynte säga till honom: Si, vi hafve öfvergifvit all ting, och följt dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Svarade Jesus, och sade: Sannerliga säger jag eder: Ingen är den som hafver öfvergifvit hus, eller bröder, eller systrar, eller fader, eller moder, eller hustru, eller barn, eller åkrar, för min och Evangelii skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'Den icke får hundradefaldt igen, nu i denna tiden, hus, och bröder, och systrar, och mödrar, och barn, och åkrar, med förföljelsen; och i tillkommande verld evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Men månge, de som de främste äro, varda de ytterste, och de ytterste de främste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Och de voro på vägen, gångande upp till Jerusalem; och Jesus gick för dem, och de voro förskräckte, och gingo efter honom, fruktande sig. Så tog Jesus åter till sig de tolf, och begynte säga dem, hvad honom öfvergå skulle:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Si, vi gåm upp till Jerusalem; och menniskones Son skall öfverantvardas de öfversta Presterna, och de Skriftlärda; och de skola fördöman till döds, och öfverantvardan Hedningomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Och de skola begabban, och hudflängan, bespottan, och dödan; och tredje dagen skall han uppstå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Då gingo till honom Jacobus och Johannes, Zebedei söner, och sade: Mästar, vi vilje att du gör oss hvad som helst vi bedje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Sade han till dem: Hvad viljen I jag skall göra eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Sade de till honom: Gif oss, att vi sitte, den ene på dine högra hand, och den andre på dine venstra, uti din härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Men Jesus sade till dem: I veten icke hvad I bedjen; kunnen I dricka den kalken, som jag dricker; och döpas med den döpelsen, der jag med döpes?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Då sade de till honom: Ja, kunne vi så. Sade Jesus till dem: Den kalken jag dricker, skolen I ock dricka; och med den döpelse, der jag med döpes, skolen I döpas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Men sitta på mine högra och venstra hand, står icke mig till att gifva; utan dem händer det, som det beredt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'När de tio hörde detta, begynte de vara illa tillfrids med Jacobo och Johanne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Men Jesus kallade dem till sig, och sade till dem: I veten, att verldslige Förstar äro rådande, och de mägtige ibland dem hafva välde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Men det skall icke så vara ibland eder; utan den, som ibland eder vill ypperst vara, han skall vara edar tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'Och den, som ibland eder vill vara den främste, han skall vara allas dräng;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Ty ock menniskones Son är icke kommen, på det han skulle låta tjena sig; utan på det han ville tjena, och gifva sitt lif till återlösning för många.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Och de kommo till Jericho. Och då han gick ut af Jericho, och hans Lärjungar, och en mägtig stor hop folk, då satt der vid vägen en blinder, Bartimeus, Timei son, tiggandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Och när han hörde, att det var Jesus af Nazareth, begynte han ropa, och säga: Jesu, Davids Son, varkunna dig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Och månge näpste honom, att han skulle tiga; men han ropade dessmer: Davids Son, varkunna dig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Så stadnade Jesus, och lät kalla honom. Och de kallade den blinda, och sade till honom: Var vid ett godt mod; statt upp, han kallar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Han kastade ifrå sig sin mantel, stod upp, och kom till Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Då svarade Jesus, och sade till honom: Hvad vill du, att jag skall göra dig? Den blinde sade till honom: Rabboni, att jag måtte få min syn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jesus sade till honom: Gack, din tro hafver gjort dig helbregda. Och straxt fick han sin syn, och följde Jesum i vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Och då de kommo in mot Jerusalem, till Bethphage och Bethanien, vid Oljoberget, utsände han två af sina Lärjungar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'Och han sade till dem: Går i byn, som för eder är; och straxt I kommen derin, varden I finnande en fåla bunden, der ännu ingen menniska på sutit hafver; löser honom, och hafver honom hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Och om någor säger till eder: Hvi gören I detta? säger: Herren behöfver honom; och då skall han straxt sända honom hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Så gingo de bort, och funno fålan bunden för dörrene, vid vägamotet, och löste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Och somlige, som der stodo, sade till dem: Hvad gören I, att I lösen fålan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Då sade de till dem, såsom Jesus hade budit dem; så läto de betämma dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Och de hade fålan till Jesum, och kastade sin kläder på honom; och han satte sig deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Och månge bredde sin kläder på vägen; och somlige skåro qvistar af trän, och strödde på vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Och de der föregingo, och der efterföljde, ropade, och sade: Hosianna! välsignad vare den, som kommer i Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Välsignad vare vårs faders Davids rike, som kommer i Herrans Namn; Hosianna i höjdene!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Och Herren gick in i Jerusalem, och i templet, och besåg all ting. Och när det led åt aftonen, gick han ut till Bethanien, med de tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Och dagen derefter, då de gingo ut ifrå Bethanien, hungrade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Och han fick se ett fikonaträ der långt ifrå, som löf hade; dit kom han, om han tilläfventyrs måtte finna der något uppå; och då han kom dit, fann han der intet annat än löf; ty det var icke då tid till fikon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Och Jesus svarade, och sade till det: Äte aldrig någor härefter frukt af dig till evig tid. Och hans Lärjungar hörde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Och de kommo till Jerusalem. Och Jesus gick in i templet, och begynte utdrifva dem som sålde och köpte i templet; och förstörte de vexlares bord, och deras stolar som dufvor sålde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Och stadde icke till, att någor bar något genom templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Och han lärde, och sade till dem: Är icke skrifvet: Mitt hus skall kallas ett bönehus allom folkom? Men I hafven gjort det till en röfvarekulo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Och de Skriftlärde och öfverste Presterne fingo det höra; och begynte söka efter, huru de kunde förgöra honom, men de fruktade för honom; ty allt folket förundrade sig på hans lärdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Och då aftonen kom, gick han utu staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Och om morgonen gingo de der framom, och sågo fikonaträt förtorkadt vara intill roten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Då kom Petrus det ihåg, och sade till honom: Rabbi, si, det fikonaträt, som du bannade, är förtorkadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Jesus svarade, och sade till dem: Hafver trona till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Sannerliga säger jag eder: Hvilken som helst sade till detta berg: Häf dig upp, och kasta dig i hafvet; och han tviflade intet i sitt hjerta, utan trodde så ske skola som han sade; honom skall ske allt det han säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Derföre säger jag eder: Allt det I bedjen i edra böner, tror att I fån det, så skall det ske eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Och när I stån och bedjen, så förlåter, om I något hafven emot någon; på det edar Fader, som i himmelen är, skall ock förlåta eder edra brister.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Men om I icke förlåten, så skall icke heller edar Fader, som är i himmelen, förlåta det I bryten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Och som de kommo åter till Jerusalem, och han gick i templet, kommo till honom de öfverste Presterna, och de Skriftlärde, och de äldste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'Och de sade till honom: Af hvad magt gör du detta? Och hvilken hafver gifvit dig denna magten, att du detta göra skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jesus svarade, och sade till dem: Jag vill ock något spörja eder; svarer mig, så vill jag säga eder, af hvad magt jag detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Johannis döpelse, var den af himmelen, eller af menniskor? Svarer mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Och de tänkte vid sig, och sade: Säge vi, af himmelen; då säger han: Hvi trodden I honom icke då?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Men säge vi, att den var af menniskom, rädes vi för folket; ty alle höllo Johannes för en sann Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Och så svarade de, sägande till Jesum: Vi vete det icke. Svarade Jesus, och sade till dem: Icke heller säger jag eder, af hvad magt jag detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Och han begynte tala dem till i liknelser: En man plantade en vingård, och gärde deromkring en gård, och grof en press, och byggde ett torn, och lejde honom ut vingårdsmännom; och for så ut i fremmande land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Och då rätta tiden var, sände han sin tjenare till vingårdsmännerna, att han skulle anamma, af vingårdsmännerna, utaf vingårdsens frukt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Men de togo honom, och slogo honom, och läto honom gå ifrå sig tomhändtan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Åter sände han till dem en annan tjenare; den kastade de hufvudet sönder med sten, och läto honom gå ifrå sig försmäddan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Åter sände han en annan, den dråpo de; och många andra, somliga hudflängde de, och somliga dråpo de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Så hade han ännu en enda son, den han kär hade; honom sände han ock till dem på det sista, sägandes: De hafva ju en försyn för min son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Men vingårdsmännerna sade emellan sig: Denne är arfvingen; kommer, låter oss dräpa honom, så varder arfvedelen vår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Då togo de honom, och dråpo honom, och kastaden utu vingården.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Hvad skall nu vingårdsherren göra? Han skall komma, och förgöra vingårdsmännerna, och få vingården androm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Hafven I ock icke läsit denna Skriften? Den stenen, som byggningsmännerne bortkastade, är vorden en hörnsten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Af Herranom är detta gjordt, och är underligit för vår ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Och de sökte efter att gripa honom; men de räddes för folket; ty de förstodo att han sade denna liknelsen om dem. Så gåfvo de honom öfver, och gingo sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Och sände de till honom några af de Phariseer, och de Herodianer, att de skulle gripa honom i orden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Då de kommo, sade de till honom; Mästar, vi vete, att du äst sannfärdig, och sköter om ingen; ty du ser icke efter menniskors person, utan lärer Guds väg rätt. Är det ock rätt, att man gifver Kejsarenom skatt, eller icke? Skole vi gifvan, eller icke gifvan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Men han förstod deras skrymtan, och sade till dem: Hvi fresten I mig? Tager hit penningen, att jag må se honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Och de båro honom fram. Då sade han till dem: Hvars beläte och öfverskrift är detta? Sade de till honom: Kejsarens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Då svarade Jesus, och sade till dem: Så gifver Kejsarenom hvad Kejsarenom tillhörer, och Gudi det Gudi tillhörer. Och de förundrade sig på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Så kommo de Sadduceer till honom, hvilke säga att ingen uppståndelse är, och sporde honom, sägande:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Mästar, Mose hafver skrifvit oss: Om någors mans broder dör, och låter hustru efter sig, och låter ingen barn efter sig, då skall hans broder taga hans hustru, och uppväcka sinom broder säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Det voro sju bröder; och den förste tog sig hustru, och han blef död, och lefde ingen säd efter sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Och den andre tog henne, och blef död; den icke heller lefde säd efter sig; och den tredje sammalunda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Så att sju togo henne, och lefde dock ingen säd. Sist af allom dödde ock hustrun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Hvilkensderas hustru skall hon nu vara i uppståndelsen, då de skola uppstå? Ty sju hade haft henne till hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Svarade Jesus, och sade till dem: I faren ville, derföre att I icke veten Skriftena, ej heller Guds kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Ty då de uppståndne äro ifrå de döda, tager man sig icke hustru, och icke gifs heller hustru manne; utan de äro såsom Änglar, som i himmelen äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Men om de döda, att de skola uppstå, hafven I icke läsit i Mose bok, huruledes Gud talade med honom i buskanom, sägandes: Jag är Abrahams Gud, och Isaacs Gud, och Jacobs Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Han är icke de dödas Gud, utan deras Gud, som lefva. Så faren I nu mycket ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Då gick en fram af de Skriftlärda, den derpå hört hade, huru de tillhopa disputerat hade, och hade sett att han hade väl svarat dem, och sporde honom till: Hvilket är det yppersta af all budorden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jesus svarade honom: Det yppersta af all budorden är detta: Hör, Israel; Herren vår Gud är allena Herre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Och du skall älska din Herra Gud, af allt ditt hjerta, och af allo dine själ, och af all din håg, och af allo dine magt. Detta är det yppersta budet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Och det andra är desso likt: Älska din nästa som dig sjelf. Intet annat bud är större än dessa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Och den Skriftlärde sade till honom: Mästar, du hafver allt rätt sagt, att Gud är en, och ingen annar är förutan honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Och att älska honom af allt hjerta, och af allt förstånd, och af allo själ, och af allo magt, och älska sin nästa som sig sjelf, det är mer än bränneoffer, och all offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Då Jesus såg, att han visliga svarat hade, sade han till honom: Du äst icke långt ifrå Guds rike. Och sedan torde ingen fråga honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Och svarade Jesus, och sade, lärandes i templet: Huru säga de Skriftlärde, att Christus är Davids Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Ty David, genom den Helga Anda, säger: Herren sade till min Herra: Sätt dig på min högra hand, tilldess jag hafver satt dina ovänner dig till en fotapall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Så kallar nu David honom Herra; hvadan är han då hans Son? Och en stor del af folket hörde honom gerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Och han lärde dem, och sade till dem: Vakter eder för de Skriftlärda; de gå gerna i sid kläder, och låta gerna helsa sig på torgen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'Och sitta gerna främst i Synagogorna, och främst vid bordet i gästabåden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Hvilke uppäta enkors hus, förebärande långa böner; desse skola få dess svårare fördömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Och satte sig Jesus tvärtemot offerkistona, och såg uppå huruledes folket lade penningar i kistona; och månge rike lade mycket in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Och en fattig enka kom, och lade in två skärfvar, det var en penning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Då kallade han sina Lärjungar till sig, och sade till dem: Sannerliga säger jag eder, denna fattiga enkan lade mer in i kistona, än alle de andre som der inlade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Ty de hafva alle inlagt af det dem öfverlopp; men hon inlade, utaf sin fattigdom, allt det hon hade, alla sina näring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Och då han gick ut af templet, sade till honom en af hans Lärjungar: Mästar, se hurudana stenar, och hurudana byggning är detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Jesus svarade, och sade till honom: Ser du denna stora byggningen? En sten varder icke qvarliggandes på den andra, den icke afbruten varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Och då han satt på Oljoberget, tvärtemot templet, frågade honom Petrus, och Jacobus, och Johannes, och Andreas, afsides:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Säg oss, när detta skall ske? Och hvad tecken är dertill, när detta skall allt fullbordas?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Svarade Jesus, och begynte säga: Ser till, att ingen bedrager eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Ty månge varda kommande i mitt Namn, sägande: Jag är Christus; och de skola bedraga många.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Men när I fån höra örlig, och örligs rykte, varer icke bedröfvade; ty det måste så ske; men det är icke straxt änden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Det ena folket skall uppsätta sig emot det andra, och det ena riket emot det andra; och jordbäfning skall varda mångastäds; och hunger och förskräckelser skola varda. Detta är begynnelsen till vedermödon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Men tager I eder vara; ty de skola öfverantvarda eder in på Rådhusen och Synagogorna; och I skolen varda hudflängde, och framdragne för Förstar och Konungar, för mina skull, till ett vittnesbörd öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Och Evangelium måste först predikadt varda för all folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'När de nu draga eder fram, och öfverantvarda eder, så hafver ingen omsorg, hvad I skolen säga; och tänker der intet på framföreåt; utan, hvad eder ingifvet varder i samma stunden, det taler; ty det ären icke I, som talen, utan den Helge Ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Och den ene brodren skall öfverantvarda den andra i döden, och fadren sonen; och barnen skola sig uppsätta mot föräldrarna, och hjelpa till att döda dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Och I skolen varda förhatade af allom, för mitt Namns skull; men den som härdar intill ändan, han varder salig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Men då I fån se förödelsens styggelse, deraf sagdt är genom Propheten Daniel, ståndandes der det icke skall; (den det läs, han förstå det) de som då äro i Judeen, de fly upp på bergen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Men den der är på taket, han gånge icke neder i huset, och gånge icke in, till att taga något utu sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Och den som är på åkren, han vände icke tillbaka, till att taga sin kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Ve dem, som hafvande äro, eller dia gifva, i de dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Men beder, att edor flykt icke sker om vinteren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Ty i de dagar varder sådana bedröfvelse, att slik hafver icke varit, ifrå kreaturens begynnelse, dem Gud skapat hafver, intill nu; och ej heller varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Och hvar Herren icke hade förkortat de dagar, vorde intet kött saligt; men för de utkorades skull, som han utkorat hafver, förkortade han dagarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'När då någor ville säga till eder: Si, här är Christus; eller si, han är der; tror det intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Ty falske Christi och falske Propheter skola upphäfva sig, och skola göra tecken och under, så att de ock skola förföra de utkorada, om möjeligit vore.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Men tager I eder vara; si, jag hafver sagt eder all ting framföreåt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Men i de dagar, efter den bedröfvelsen, skall solen förmörkas, och månen skall icke gifva sitt sken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'Och himmelens stjernor skola nederfalla, och himmelens krafter skola bäfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Och då skola de få se menniskones Son komma i skyn, med stor magt och härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Och då skall han sända sina Änglar, till att församla sina utkorada, ifrå fyra väder; ifrå jordenes ända intill himmelens ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Lärer af fikonaträt en liknelse: När nu dess qvist är klen, och begynner bära löf, så veten I, att sommaren är när;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Sammalunda ock, när I sen detta ske, så veter att det är när för dörrene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Sannerliga säger jag eder, att detta slägtet skall icke förgås, förr än allt detta skedt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Himmel och jord skola förgås; men min ord skola icke förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Men om den dagen, och den stunden, vet ingen; icke Änglarna, som i himmelen äro, ej heller Sonen; utan Fadren allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Ser till, vaker och beder; ty I veten icke, när tiden är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Såsom en man, den der drog bort i främmande land, och lät blifva sitt hus, och gaf sina tjenare magt, och hvarjom och enom sina sysslo, och böd dörravaktaren, att han skulle vaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Vaker fördenskull; ty I veten icke, när husbonden kommer, antingen om aftonen, eller midnattstid, eller i hönsgälden, eller om morgonen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Att, då han kommer hasteliga, han icke skall finna eder sofvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Men hvad jag säger eder, det säger jag allom: Vaker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Och två dagar derefter instundade Påska och Sötbrödsdagarna; och de öfverste Presterna och de Skriftlärde sökte efter, huru de kunde svikliga få fatt på honom, och döda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Men de sade: Icke om högtidsdagen, att ett upplopp icke sker ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Och då han var i Bethanien, i den spitelska Simons hus, vid han satt till bords, kom en qvinna, som hade ett glas med oförfalskadt och kosteligit nardus smörjelse; hon bröt glaset sönder, och utgöt det på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Så voro der någre, som icke togo det väl vid sig, och sade: Hvarefter förspilles denna smörjelsen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Ty det måtte väl varit såldt mer än för trehundrade penningar, och gifvet fattigom; och läto illa på henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Då sade Jesus: Låter henne med frid; hvi gören I henne illa tillfrids? Hon hafver gjort en god gerning på mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Ty I hafven alltid fattiga när eder; och när som helst I viljen, kunnen I göra dem till godo; men mig hafven I icke alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Det hon kunde, det gjorde hon; hon är förekommen att smörja min lekamen till begrafning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Sannerliga säger jag eder: Hvar detta Evangelium predikadt varder uti hela verldene, skall ock detta, som hon gjorde, sagdt varda, henne till åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Och Judas Ischarioth, en af de tolf, gick bort till de öfversta Presterna, på det han skulle förråda honom dem i händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'När de det hörde, vordo de glade, och lofvade honom, att de ville gifva honom penningar; och han sökte, huru han lämpeligast kunde förråda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'På första Sötbrödsdagen, då man offrade Påskalambet, sade hans Lärjungar till honom: Hvar vill du, att vi skole gå och reda till, att du äter Påskalambet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Och han sände två af sina Lärjungar, och sade till dem: Går in i staden, och der möter eder en man, bärandes ena kruko vatten; följer honom efter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Och hvar han ingår, säger till husbondan: Mästaren låter säga dig: Hvar är gästahuset, der jag med minom Lärjungom kan äta Påskalambet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Och han skall visa eder en stor sal, beredd och tillpyntad; der reder till för oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Och hans Lärjungar gingo ut, och kommo in i staden, och funno som han dem sagt hade, och tillredde Påskalambet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Då nu aftonen vardt, kom han med de tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Och vid de såto till bords, och åto, sade Jesus: Sannerliga säger jag eder, en af eder, som äter med mig, skall förråda mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Men de begynte vara illa tillfrids, och sade till honom, hvar i sin stad: Är det jag? och den andre: Är det jag?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Han svarade och sade till dem: En af de tolf, den som tager i fatet med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Ja, menniskones Son varder så gångandes, som skrifvet är om honom; men ve de mennisko, genom hvilken menniskones Son varder förrådder; de mennisko vore bättre, att hon icke vore född.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Och vid de åto, tog Jesus brödet; tackade, och bröt det, och gaf dem, och sade: Tager, äter, detta är min lekamen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Och tog kalken, och tackade, och gaf dem; och de drucko deraf alle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Och sade han till dem: Detta är min blod, dess nya Testamentsens, hvilken för många utgjuten varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Sannerliga säger jag eder: Härefter skall jag icke dricka af vinträs frukt, intill den dagen att jag dricker det nytt i Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Och då de hade sagt lofsången, gingo de ut på Oljoberget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Och Jesus sade till dem: I skolen alle i denna nattene förargas på mig; ty det är skrifvet: Jag skall slå herdan, och fåren varda förskingrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Men då jag är uppstånden, vill jag gå fram för eder uti Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Då sade Petrus till honom: Om än alle förargades, skall jag icke förargas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Jesus sade till honom: Sannerliga säger jag dig, i dag, i denna natt, förr än hanen hafver två resor galit, skall du tre resor försaka mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Då sade han ändå ytterligare: Ja, skulle jag än dö med dig, jag skall icke försaka dig. Sammalunda sade de ock alle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Och de kommo på den platsen, som kallades Gethsemane. Och han sade till sina Lärjungar: Sitter här, så länge jag går afsides, till att bedja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Och så tog han med sig Petrum, och Jacobum, och Johannem, och begynte till att förskräckas och ängslas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Och sade till dem: Min själ är bedröfvad allt intill döden; blifver här, och vaker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Och han gick litet fram bätter, och föll ned på jordena, och bad att, om möjeligit vore, skulle den stunden undgå honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Och sade: Abba, Fader; all ting äro dig möjelig; unddrag mig denna kalken; dock icke hvad jag vill, utan hvad du vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Och han kom, och fann dem sofvande, och sade till Petrum: Simon, sofver du? Förmådde du icke vaka ena stund?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Vaker, och beder, att I icke kommen uti frestelse; anden är viljog, men köttet är svagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Och så gick han åter bort, och bad; och talade samma orden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Och då han kom igen, fann han dem åter sofvande; ty deras ögon voro tung; och de visste icke hvad de honom svarade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Och han kom tredje gången, och sade till dem: Ja, sofver nu, och hviler eder; det är nog, stunden är kommen: Si, menniskones Son varder öfverantvardad uti syndares händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Står upp, låt oss gå: Si, den mig förråder, är hardt när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Och straxt, med samma orden, steg Judas fram, den der en var af de tolf; och med honom ett stort tal folk, med svärd och stafrar, ifrå de öfversta Presterna, och de Skriftlärda, och de äldsta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Så hade den, som förrådde honom, gifvit dem ett tecken, sägandes: Hvilken jag kysser, den äret; tager fatt på honom, och förer honom varliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Och som han kom, trädde han hasteliga fram till honom, och sade till honom: Rabbi, Rabbi; och kysste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Då båro de händer på honom, och grepo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Men en, af de der när stodo, drog ut sitt svärd, och slog öfversta Prestens tjenare, och högg honom ett öra af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Och Jesus svarade, och sade till dem: Såsom till en röfvare ären I utgångne, med svärd och stafrar, till att gripa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Jag hafver hvar dag varit när eder i templet, och lärt, och I togen intet fatt på mig; men detta sker, på det att Skrifterna skola fullbordas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Och Lärjungarna gåfvo honom då alle öfver, och flydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Men en unger man följde honom, klädd på blotta kroppen uti ett linkläde; och unge män grepo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Men han lät fara linklädet, och kom undan ifrå dem naken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Så ledde de Jesum till den öfversta Presten, och med honom församlades alle öfverste Presterna, och de äldste, och Skriftlärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Och Petrus följde långt efter honom, tilldess han kom uti den öfversta Prestens palats; och satte sig ibland tjenarena, och värmde sig vid ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Men de öfverste Presterna, och hela Rådet, sökte efter vittne emot Jesum, att de måtte låta döda honom; och kunde dock ingen finna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Ty månge hade burit falskt vittnesbörd emot honom; dock gjorde deras vittnesbörd icke fyllest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Då stodo någre upp, och båro falskt vittnesbörd emot honom, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Vi hörde honom säga: Jag vill nederslå detta templet, som är med händer uppbygdt, och i tre dagar sätta ett annat upp igen, utan händer uppbygdt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Och deras vittnesbörd gjorde ändå icke fyllest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Då stod den öfverste Presten upp ibland dem, och frågade Jesum, sägandes: Svarar du intet? Hvad vittna desse emot dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Men han tigde, och svarade platt intet. Åter sporde den öfverste Presten, och sade till honom: Äst du Christus, dens välsignades Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jesus sade: Jag är så; och I skolen få se menniskones Son sitta på kraftenes högra hand, och komma i himmelens sky.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Då ref den öfverste Presten sin kläder sönder, och sade: Hvad behöfve vi numera vittne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'I hörden hädelsen. Hvad synes eder? Då fördömde de honom alle, att han var saker till döds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Och somlige begynte till att spotta på honom, och förtäcka hans ansigte, och slå honom med näfvarna, sägande till honom: Spå till. Och tjenarena kindpustade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Och Petrus var nedre i palatset; då kom en öfversta Prestens tjensteqvinna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Och då hon fick se Petrum värma sig, såg hon på honom, och sade: Du vast ock med Jesu Nazareno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Då nekade han, och sade: Jag känner honom intet, ej heller vet jag hvad du säger. Och så gick han ut i gården, och hanen gol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Och qvinnan såg honom åter, och begynte säga till de der när stodo: Denne är utaf dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Då nekade han åter. Och litet derefter talade de åter till Petrum, som när stodo: Sannerliga äst du utaf dem; ty du äst ock en Galileisk man, och ditt mål lyder derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Då begynte han till att förbanna sig, och svärja: Jag känner icke denna mannen, der I om talen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Och åter gol hanen. Då begynte Petrus draga till minnes det ordet, som Jesus hade sagt till honom: Förr än hanen hafver galit två resor, skall du försaka mig tre resor. Och han begynte till att gråta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Och straxt om morgonen höllo de öfverste Presterna råd, med de äldsta och Skriftlärda, och med hela Rådet; och bundo Jesum, och ledde honom bort, och antvardade honom Pilato.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Och Pilatus frågade honom: Äst du den Judarnas Konung? Då svarade han, och sade till honom: Du säger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Och öfverste Presterna anklagade honom om mång ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Då frågade åter Pilatus honom, och sade: Svarar du intet? Si, huru mång stycke de vittna på dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Men Jesus svarade sedan platt intet; så att Pilatus förundrade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Så plägade han i Påskahögtidene gifva dem en fånga lös, hvilken de helst begärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Så var der en, benämnd Barabbas, som gripen var med somliga, de der ett upplopp gjort hade, och hade uti upploppet bedrifvit ett dråp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Då ropade folket, och begynte bedja, att han skulle göra dem som hans plägsed alltid var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Svarade Pilatus, sägandes: Viljen I, att jag skall eder lösgifva Judarnas Konung?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Ty han visste, att de öfverste Presterna hade utaf afund öfverantvardat honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Men öfverste Presterna eggade folket, att han heldre skulle gifva dem Barabbam lös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilatus svarade åter, och sade till dem: Hvad viljen I då att jag skall göra honom, den I kallen Judarnas Konung?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Då ropade de åter: Korsfäst honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilatus sade till dem: Hvad hafver han då illa gjort? Då ropade de ännu fastare: Korsfäst honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Så ville då Pilatus göra folkena fyllest, och gaf dem Barabbam lös; och öfverantvardade dem Jesum, att han skulle hudflängas och korsfästas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Då hade krigsknektarna honom in uti Rådhuset, och kallade tillhopa hela skaran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Och klädde honom uti ett purpurkläde, och vredo tillhopa ena krono af törne, och satte på honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Och begynte till att helsa honom: Hel, Judarnas Konung;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Och slogo hans hufvud med en rö, och spottade på honom; föllo på knä, och tillbådo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Och när de hade så begabbat honom, afklädde de honom purpurklädet, och klädde honom uti sin egen kläder; och ledde honom ut till att korsfästan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Då tvingade de en man, som der framgick, benämnd Simon af Cyrene, Alexandri och Rufi fader, den af markene inkom, att han måste bära hans kors.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Och de ledde honom på det rummet Golgatha; det är, om man det uttyder, hufvudskallaplatsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Och de gåfvo honom bemyrrhadt vin dricka; men han tog det intet till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Och när de hade korsfäst honom, bytte de hans kläder, kastande lott på dem, hvad hvar få skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Och det var vid tredje timman; och de korsfäste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Och det man skyllde honom före, var skrifvet öfver hans hufvud, nämliga: Judarnas Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Och de korsfäste med honom två röfvare, en på hans högra, och den andra på hans venstra sido.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Och så blef Skriften fullbordad, som säger: Ibland ogerningsmän vardt han räknad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Och de, som gingo der framom, hädde honom, och riste sin hufvud, och sade: Tvi dig! Skönliga slår du omkull templet, och i tre dagar uppbygger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Fria dig sjelfvan, och stig neder af korset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Sammalunda ock de öfverste Presterna gjorde spe af honom emellan sig, med de Skriftlärda, och sade: Androm hafver han hulpit, sig sjelfvom kan han icke hjelpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Christus, Israels Konung, stige nu neder af korset, att vi måtte det se, och tro. Och de der korsfäste voro med honom, försmädde honom ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Och i sjette timman vardt ett mörker öfver allt landet, till nionde timman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Och i nionde timman ropade Jesus med höga röst, sägandes: Eloi, Eloi, Lamma Sabachthani? det är uttydt: Min Gud, min Gud, hvi hafver du öfvergifvit mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Och somlige, de der när stodo, och hörde det, sade: Si, Eliam kallar han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Så lopp en till med en svamp, uppfylldan med ättiko; den satte han på en rö, och böd honom dricka, och sade: Håll, låt se, om Elias kommer, till att taga honom neder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Då ropade Jesus med höga röst, och gaf upp andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Och förlåten i templet remnade i tu stycke, ifrån öfverst och neder igenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Då höfvitsmannen, som stod der när gentemot honom, såg att han med ett sådant rop gaf upp andan, sade han: Sannerliga var denne mannen Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Och voro ock qvinnor der, som långt ifrå detta skådade; ibland hvilka var Maria Magdalena, och Maria, litsle Jacobs och Jose moder, och Salome.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Hvilka ock, medan han var i Galileen, hade följt honom, och tjent honom; och många andra, som med honom uppfarit hade till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Då aftonen kom, efter det var tillredelsedagen, den som går före Sabbathen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Kom Joseph, bördig af den staden Arimathia, en ärlig rådherre, den ock vänte efter Guds rike; han tog sig dristighet till, och gick in till Pilatum, och beddes af honom Jesu lekamen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Då förundrade Pilatus, att han allaredo var död; och kallade till sig höfvitsmannen, och frågade, om han länge sedan död var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Och då han det förnummit hade af höfvitsmannenom, gaf han Joseph lekamen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Och han köpte ett linkläde, och tog honom ned, och svepten uti linklädet, och lade honom ned uti ena graf, som uthuggen var uti ett hälleberg; och välte en sten för grafvenes dörr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Men Maria Magdalena och Maria Jose sågo till hvart han lades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Och då Sabbathen framgången var, köpte Maria Magdalena, och Maria Jacobi, och Salome, välluktande krydder, på det de skulle komma och smörja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Och på den ena Sabbathen kommo de till grafvena, ganska bittida, då solen uppgick;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Och sade emellan sig sjelfva: Ho skall välta oss stenen ifrå grafvenes dörr?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Och då de sågo till, sågo de stenen vara afvältad, den ganska stor var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Och när de ingångne voro uti grafvena, sågo de en ung man sittandes på högra sidon, klädd i ett sidt hvitt kläde; och de vordo förfärada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Men han sade till dem: Varer icke förfärada; I söken Jesum af Nazareth, som korsfäst var; han är uppstånden, han är icke här; si rummet, der de hade lagt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Men går bort, och säger hans Lärjungar, och Petro, att han går fram för eder uti Galileen; der skolen I få se honom, såsom han eder sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Och de gingo hasteliga derut, och flydde ifrå grafvene; ty dem var bäfning och häpenhet påkommen; icke heller sade de något för någrom, ty de räddes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Men när Jesus uppstånden var om morgonen, på första Sabbathsdagen, syntes han först Marie Magdalene, af hvilka han sju djeflar utdrifvit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Hon lopp bort, och bådade dem som plägade vara med honom, de der sörjande och gråtande voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Och de samme, när de hörde att han var lefvandes, och var sedder af henne, trodde de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Derefter, då två af dem vandrade ut åt landsbygden, syntes han dem uti en annor skepelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Och de gingo ock bort, och bådade det dem androm; och de trodde icke heller dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Sedan, när de ellofva såto till bords, syntes han dem, och förekastade dem deras otro och hjertas hårdhet, att de icke trott hade dem, som hade sett honom vara uppstånden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Och sade till dem: Går ut i hela verldena, och prediker Evangelium allom kreaturom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Den der tror, och blifver döpt, han skall varda salig; men den der icke tror, han skall varda fördömd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Men dem, som tro, skola dessa tecken efterfölja: genom mitt Namn skola de utdrifva djeflar; de skola tala med nya tungor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'De skola fördrifva ormar; och om de dricka något det dödeligit är, skall det dem intet skada; på de kranka skola de lägga händerna, så varder det bättre med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Då nu Herren Jesus med dem talat hade, vardt han upptagen i himmelen, och sitter på Guds högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Men de gingo ut, och predikade allestäds; och Herren verkade med dem, och stadfäste ordet med efterföljande tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Efter månge hafva tagit sig före att beskrifva de ting, som ibland oss aldravissast äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Såsom de oss sagt hafva, som af begynnelsen det med sin ögon sågo, och sjelfve en del voro af det de sade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Syntes ock mig, sedan jag af begynnelsen all ting granneliga utfrågat hafver, ordenteligen skrifva dig till, min gode Theophile;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Att du må förfara vissa sanningen om de stycker, der du om undervister äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Uti Herodis, Judee Konungs, tid, var en Prest, utaf Abie skifte, benämnd Zacharias; och hans hustru, af Aarons döttrar, benämnd Elisabet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'De voro både rättfärdige för Gud, vandrande i all Herrans bud och stadgar ostraffeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Och de hade inga barn; ty Elisabet var ofruktsam, och både voro de framlidne i sin ålder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Så begaf det sig, då han i sitt skifte skulle hålla sitt Prestaämbete för Gudi,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Efter Presterskapets sed, och det föll på honom, att han skulle upptända rökelse, gick han in i Herrans tempel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Och allt folket var utantill, och bad, så länge rökelsen skedde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Så syntes honom Herrans Ängel, ståndandes på högra sidon vid rökaltaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Och Zacharias vardt förskräckt, då han såg honom, och en räddhåge föll öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Så sade Ängelen till honom: Var icke förfärad, Zacharia; ty din bön är hörd, och din hustru Elisabet skall föda dig en son, hvilkens namn du skall kalla Johannes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Och dig skall varda glädje och fröjd; och månge skola fröjdas af hans födelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Ty han skall varda stor för Herranom; vin och starka drycker skall han icke dricka; och skall straxt i moderlifvet uppfylld varda med den Helga Anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Och han skall omvända många af Israels barn till Herran, deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Och han skall gå för honom, med Elie anda och kraft, till att omvända fädernas hjerta till barnen, och de ohöriga till de rättfärdigas snällhet; och göra Herranom ett beredt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Då sade Zacharias till Ängelen: Hvaraf skall jag detta veta? Ty jag är gammal, och min hustru är framliden i åldren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Ängelen svarade, och sade till honom: Jag är Gabriel, som står i Guds åsyn, och är utsänd till att tala dig till, och båda dig denna goda tidenden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Och si, du skall varda mållös, och skall intet kunna tala, intill den dagen, då detta sker; derföre, att du icke trodde minom ordom, hvilke skola fullkomnad varda i sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Och folket förbidde Zachariam, och förundrade sig, att han så länge dvaldes i templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Men då han utgick, kunde han intet tala med dem; och så förmärkte de, att han hade sett någon syn i templet; och han tecknade dem, och blef mållös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Och det begaf sig, då hans ämbetsdagar ute voro, gick han hem i sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Och efter de dagar vardt hans hustru Elisabet hafvandes; och fördolde sig i fem månader, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Så hafver nu Herren gjort med mig, i de dagar, då han såg till mig, på det han skulle borttaga min försmädelse ibland menniskorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Uti sjette månaden vardt Gabriel Ängel utsänd af Gudi, uti en stad i Galileen, benämnd Nazareth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'Till en jungfru, som förlofvad var enom man, hvilkens namn var Joseph, af Davids hus; och jungfrunes namn Maria.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Och Ängelen kom in till henne, och sade: Hel, full med nåd! Herren är med dig; välsignad du ibland qvinnor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Då hon såg honom, vardt hon förfärad af hans tal, och tänkte uppå, hurudana helsning detta var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Då sade Ängelen till henne: Frukta dig icke, Maria; ty du hafver funnit nåd för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Si, du skall afla i ditt lif, och föda en son, hvilkens Namn du skall kalla JESUS.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Han skall varda stor, och kallas dens Högstas Son; och Herren Gud skall gifva honom hans faders Davids säte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'Och han skall vara en Konung öfver Jacobs hus i evig tid; och på hans rike skall ingen ände vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Då sade Maria till Ängelen: Huru skall detta tillgå? Ty jag vet af ingen man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Ängelen svarade, och sade till henne: Den Helge Ande skall komma öfver dig, och dens Högstas kraft skall öfverskygga dig; derföre ock det Helga, som af dig födt varder, skall kallas Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Och si, Elisabet, din fränka, hafver ock aflat en son i sin ålderdom; och detta är sjette månaden åt henne, som hetes vara ofruktsam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Ty för Gud är ingen ting omöjelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Då sade Maria: Si, Herrans tjenarinna; varde mig efter ditt tal. Och Ängelen skiljdes ifrå henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Uti de dagar stod Maria upp, och gick i bergsbygdena med hast, uti Jude stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Och kom uti Zacharie hus, och helsade Elisabet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Och det begaf sig, då Elisabet hörde Marie helsning, sprang barnet uti hennes lif. Och Elisabet vardt uppfylld med den Helga Anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Och hon ropade med höga röst, och sade: Välsignad du ibland qvinnor, och välsignad dins lifs frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Och hvadan kommer mig detta, att mins Herras moder kommer till mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Si, då rösten af dine helsning kom i min öron, sprang barnet af glädje i mitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Och salig äst du, som trodde; ty all ting varda fullbordad, som dig sagd äro af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Och Maria sade: Min själ prisar storliga Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'Och min ande fröjdar sig i Gudi, minom Frälsare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Ty han hafver sett till sine tjenarinnos ringhet: Si, härefter varda all slägte mig saliga kallande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Ty den Mägtige hafver gjort mägtig ting med mig, och hans Namn är heligt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Och hans barmhertighet varar ifrå slägte till slägte, öfver dem som frukta honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Han hafver bedrifvit magt med sinom arm, och förskingrat dem, som högfärdige äro uti deras hjertas sinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'De mägtige hafver han satt af sätet, och uppsatt de ringa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'De hungriga hafver han med god ting uppfyllt, och de rika hafver han låtit tomma blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Han hafver upptagit sin tjenare Israel, tänkande på sina barmhertighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Såsom han sagt hafver till våra fäder, Abraham och hans säd, till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Och Maria blef när henne vid tre månader; och gick så hem i sitt hus igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Så vardt då Elisabet tiden fullbordad att hon skulle föda, och hon födde en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Och hennes grannar och fränder fingo höra, att Herren hade gjort stor barmhertighet med henne, och fröjdade sig med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Och det begaf sig, på åttonde dagen kommo de till att omskära barnet; och kallade honom, efter hans fader, Zacharias.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Då svarade hans moder, och sade: Ingalunda; men han skall heta Johannes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Då sade de till henne: Uti dine slägt är ingen, som hafver det namnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Så tecknade de hans fader, hvad han ville kalla honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Och han äskade ena taflo, der han uti skref, sägandes: Johannes är hans namn; och alle förundrade sig derpå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Och straxt öppnades hans mun, och hans tunga; och han talade, lofvandes Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Och stor fruktan kom öfver alla deras grannar; och ryktet om allt detta gick ut öfver alla Judiska bergsbygdena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Och alle de, som det hörde, sattet i sitt hjerta, sägande: Hvad månn varda utaf detta barnet? Ty Herrans hand var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Och hans fader Zacharias vardt uppfylld med den Helga Anda, propheterade, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Lofvad vare Herren, Israels Gud; ty han hafver besökt och förlossat sitt folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'Och hafver upprättat oss salighetenes horn, uti sins tjenares Davids hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Såsom han i förtiden talat hafver, genom sina helga Propheters mun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Att han skulle frälsa oss ifrå våra ovänner, och utur allas deras hand, som hata oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Och bevisa barmhertighet med våra fäder, och minnas på sitt helga Testamente;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'Och på den ed, som han svorit hafver vårom fader Abraham, att gifva oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Att vi, frälste utur våra ovänners hand, måtte honom tjena utan fruktan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'I helighet och rättfärdighet, för honom, i alla våra lifsdagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Och du barn skall kallas dens Högstas Prophet; du skall gå för Herranom, till att bereda hans vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'Och gifva hans folke salighetenes kunskap, till deras synders förlåtelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Genom vår Guds innerliga barmhertighet, genom hvilken uppgången af höjdene hafver oss besökt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Till att uppenbaras dem, som sitta i mörkret och dödsens skugga, och styra våra fötter på fridsens väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Och barnet växte upp, och stärktes i Andanom; och vistades i öknene, till den dagen han skulle framkomma för Israels folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Det begaf sig i den tiden, att af Kejsar Augusto utgick ett bud, att all verlden skulle beskattas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Och denna beskattning var den första, och skedde under den höfdingen öfver Syrien, Cyrenio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Och de gingo alle, hvar uti sin stad, till att låta beskatta sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Så for ock Joseph upp af Galileen, af den staden Nazareth, in uti Judiska landet, till Davids stad, som heter BethLehem; ty han var af Davids hus och slägt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'På det han skulle låta beskatta sig, med Maria, sin trolofvada hustru, hvilken hafvandes var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Så begaf sig, medan de voro der, vordo dagarna fullbordade att hon skulle föda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Och hon födde sin förstfödda Son, och svepte honom i lindakläder, och lade honom neder i en krubbo; ty dem var icke rum i herbergena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Och i den samma ängden voro någre herdar, de der vakade, och höllo vård om nattena öfver sin hjord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Och si, Herrans Ängel stod när dem, och Herrans klarhet kringsken dem; och de vordo storliga förfärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Och sade Ängelen till dem: Varer icke förfärade; si, jag bådar eder stor glädje, hvilken allo folkena vederfaras skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Ty i dag är eder födder Frälsaren, som är Christus Herren, i Davids stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Och detta skall vara eder för tecken: I skolen finna barnet svept i lindakläder, nederlagdt i en krubbo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Och straxt vardt med Ängelen ett stort tal af den himmelska härskaran, de der lofvade Gud, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Ära vare Gud i höjdene, och frid på jordene, och menniskomen en god vilje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Och det begaf sig, att Änglarna foro ifrå dem upp i himmelen, och herdarna begynte säga emellan sig: Låter oss nu gå till BethLehem, och se det som vi hafve hört skedt vara, det Herren oss uppenbarat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Och de gingo hasteliga, och funno Maria, och Joseph, och barnet nederlagdt i krubbon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Och då de det sett hade, beryktade de ut hvad dem sagdt var om detta barnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Och alle, de det hörde, förundrade sig på de ting, som dem sagd voro af herdarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Men Maria gömde all dessa ord, betraktandes dem i sitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Och herdarna gingo tillbaka igen, prisade och lofvade Gud öfver allt det de hört och sett hade, såsom dem sagdt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Och då åtta dagar voro framgångne, att barnet skulle omskäras, kallades hans Namn JESUS; hvilket så kalladt var af Ängelen, förr än han aflad vardt i moderlifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Och då deras renselsedagar voro fullkomnade, efter Mose lag, hade de honom till Jerusalem, på det de skulle bära honom fram för Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'Såsom skrifvet är i Herrans lag: Allt mankön, som först öppnar moderlifvet, skall kallas heligt Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'Och på det de skulle offra, såsom sagdt var i Herrans lag, ett par turturdufvor, eller två unga dufvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Och si, i Jerusalem var en man, benämnd Simeon, och den mannen var rättfärdig och gudfruktig, och vänte efter Israels tröst; och den Helge Ande var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Och han hade fått svar af den Helga Anda, att han icke skulle se döden, utan han hade sett tillförene Herrans Christ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Och han kom af Andans tillskyndelse i templet. Och föräldrarna båro in barnet Jesum, att de skulle göra för honom, såsom sedvänja var i lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Då tog han honom i sin famn, och lofvade Gud, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Herre, nu låter du din tjenare fara i frid, efter som du sagt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Ty min ögon hafva sett dina salighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Hvilka du beredt hafver för allo folke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Ett Ljus till Hedningarnas upplysning, och ditt folk Israel till pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Och Joseph och hans moder förundrade sig på det, som sades om honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Och Simeon välsignade dem, och sade till Maria, hans moder: Si, denne är satt till ett fall och uppståndelse mångom i Israel, och till ett tecken, hvilko emot sagdt varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'Ja, ett svärd skall ock gå igenom dina själ, på det mång hjertans tankar skola uppenbaras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Och der var en Prophetissa, benämnd Hanna, Phanuels dotter, af Assurs slägte; hon var kommen till en stor ålder, och hade lefvat i sju år med sin man, ifrå sin jungfrudom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'Och var nu en enka, vid fyra och åttatio år; hon kom aldrig bort utu templet, tjenandes Gudi, med fasto och böner, natt och dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Hon kom ock dertill i samma stundene, och prisade Herran; och talade om honom till alla dem, som i Jerusalem vänte förlossning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Och då de all ting fullbordat hade efter Herrans lag, drogo de in i Galileen igen, uti sin stad Nazareth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Men barnet växte upp, och förstärktes i Andanom, och uppfylldes med vishet; och Guds nåd var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Och hans föräldrar gingo årliga till Jerusalem, till Påskahögtiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Och då han vardt tolf åra gammal, och de uppfarne voro till Jerusalem, efter högtidenes sedvänjo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Och de fullkomnat hade dagarna, och gingo hem igen, blef pilten Jesus qvar i Jerusalem, och Joseph och hans moder visste der intet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Men de mente, att han var i sällskapet, och de gingo ena dagsled, och sökte honom ibland fränder och vänner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Och då de icke funno honom, gingo de till Jerusalem igen, och sökte honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Så begaf det sig, efter tre dagar funno de honom i templet, sittandes midt ibland de lärare, hörandes dem, och frågandes dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Och alle, de honom hörde, förskräckte sig öfver hans förstånd och svar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Och då de sågo honom, förundrade de sig; och hans moder sade till honom: Min Son, hvi gjorde du oss detta? Si, din fader och jag hafve sökt efter dig sörjande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Och han sade till dem: Hvad är det, att I sökten mig? Vissten I icke, att uti de stycker, som min Fader tillhöra, bör mig vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Och de förstodo icke ordet, som han med dem talade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Och så for han ned med dem, och kom till Nazareth, och var dem underdånig; men hans moder gömde all dessa ord uti sitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Och Jesus växte till i visdom, ålder och nåde, för Gud och menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Uti femtonde årena af Tiberii Kejsaredöme, då Pontius Pilatus var landshöfding i Judeen, och Herodes var Tetrarcha i Galileen, och Philippus, hans broder, Tetrarcha i Itureen, och i den ängden Trachonitis, och Lysanias Tetrarcha i Abilene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Under de öfversta Presterna Hannas och Caiphas, kom Guds befallning till Johannes, Zacharie son, i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Och han kom i alla den ängden vid Jordan, och predikade bättringenes döpelse, till syndernas förlåtelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Såsom skrifvet är i den boken af Esaie Prophetens ordom, den der säger: Uti öknen är en ropandes röst: Bereder Herrans väg; görer hans stigar rätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Alla dalar skola uppfyllas, och all berg och backar skola förnedras; och det krokot är, skall rätt varda, och det ojemnt är, skall vändas i släta vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Och allt kött skall se Guds salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Så sade han då till folket, som utgick till att döpas af honom: I huggormars afföda, ho hafver eder föregifvit, att I undkomma skolen den tillkommande vrede?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Görer fördenskull tillbörlig bättrings frukt; och tager eder icke före att säga vid eder sjelf: Vi hafve Abraham till fader; ty jag säger eder: Gud är mägtig uppväcka Abrahe söner af dessa stenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Och nu är allaredo yxen satt till rotena på trän; hvart och ett trä, som icke bär goda frukt, varder afhugget, och kastadt i elden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Och folket frågade honom, sägande: Hvad skole vi då göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Svarade han, och sade till dem: Den der två kjortlar hafver, han gifve den som ingen hafver; och den der mat hafver, göre sammalunda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Så kommo ock de Publicaner, till att döpas, och sade till honom: Mästar, hvad skole då vi göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Sade han till dem: Kräfver icke mer ut, än eder förelagdt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Frågade ock krigsmän honom, sägande: Hvad skole då vi göra? Sade han till dem: Görer ingom öfvervåld och orätt, och låter eder nöja åt edor lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Så begynte då folket hafva en gissan, och alle tänkte i sin hjerta om Johanne, om han icke var Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Då svarade Johannes, och sade till alla: Jag döper eder i vatten; men en varder kommandes, som starkare är än jag, hvilkens skoremmar jag icke värd är att upplösa; han skall döpa eder med den Helga Anda, och med eld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Hvilkens kastoskofvel är uti hans hand, och han skall rensa sin loga, och församla hvetet uti sina lado; men agnarna skall han uppbränna uti evig eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Och mång annor stycke förmanade han, och predikade för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Då Herodes Tetrarcha vardt straffad af honom, för Herodias, sins broders Philippi hustrus, skull, och för allt det onda, som Herodes gjorde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Öfver allt detta lade han Johannem i häktelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Och det begaf sig, då allt folket lät sig döpa, och Jesus vardt ock döpt, och bad, öppnades himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'Och den Helge Ande kom ned i lekamlig hamn, såsom en dufva, på honom; och en röst kom af himmelen, som sade: Du äst min älskelige Son; uti dig behagar mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Och Jesus begynte vara vid tretio år; och han vardt hållen för Josephs son, hvilken var Eli son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Hvilken var Matthats son; hvilken var Levi son; hvilken var Melchi son; hvilken var Janna son; hvilken var Josephs son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Hvilken var Mattathie son; hvilken var Amos son; hvilken var Naums son; hvilken var Esli son; hvilken var Nagge son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Hvilken var Maaths son; hvilken var Mattathie son; hvilken var Semei son; hvilken var Josephs son; hvilken var Juda son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Hvilken var Johanna son; hvilken var Rhesa son; hvilken var Zorobabels son; hvilken var Salathiels son; hvilken var Neri son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Hvilken var Melchi son; hvilken var Addi son; hvilken var Kosams son; hvilken var Elmodams son; hvilken var Ers son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Hvilken var Jose son; hvilken var Eliezers son; hvilken var Jorims son; hvilken var Matthats son; hvilken var Levi son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Hvilken var Simeons son; hvilken var Juda son; hvilken var Josephs son; hvilken var Jonans son; hvilken var Eliakims son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Hvilken var Melea son; hvilken var Mainans son; hvilken var Matthatha son; hvilken var Nathans son; hvilken var Davids son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Hvilken var Jesse son; hvilken var Obeds son; hvilken var Boas son; hvilken var Salmons son; hvilken var Naassons son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Hvilken var Aminadabs son; hvilken var Arams son; hvilken var Esroms son; hvilken var Phares son; hvilken var Juda son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Hvilken var Jacobs son; hvilken var Isaacs son; hvilken var Abrahams son; hvilken var Thara son; hvilken var Nachors son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Hvilken var Saruchs son; hvilken var Ragua son; hvilken var Phalegs son; hvilken var Ebers son; hvilken var Sala son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Hvilken var Cainans son; hvilken var Arphaxads son; hvilken var Sems son; hvilken var Noe son; hvilken var Lamechs son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Hvilken var Mathusala son; hvilken var Enochs son; hvilken var Jareds son; hvilken var Maleleels son; hvilken var Cainans son;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Hvilken var Enos son; hvilken var Seths son; hvilken var Adams son; hvilken var Guds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Sedan gick Jesus ifrå Jordan igen, full med den Helga Anda, och vardt hafder af Andanom uti öknena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'Och frestades i fyratio dagar af djefvulen, och åt intet i de dagar; utan då de ändade voro, sedan hungrade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Då sade djefvulen till honom: Äst du Guds Son, så säg till denna stenen, att han varder bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Då svarade Jesus, och sade till honom: Det är skrifvet: Menniskan lefver icke allenast af bröd, utan af hvart och ett Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Och djefvulen hade honom på ett högt berg, och viste honom all rike i verldene, uti ett ögnablick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'Och djefvulen sade till honom: Dig vill jag gifva all denna magten, och deras härlighet; ty de äro mig i händer gifven, och hvem jag vill, gifver jag dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Vill du nu falla ned, och tillbedja mig, så skola de all höra dig till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Jesus svarade, och sade till honom: Gack bort ifrå mig, Satan; ty det är skrifvet: Din Herra Gud skall du tillbedja, och honom allena skall du dyrka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Och hade han honom till Jerusalem, och satte honom uppå tinnarna af templet, och sade till honom: Äst du Guds Son, så gif dig här nedföre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Ty det är skrifvet: Han skall befalla sina Änglar om dig; att de skola förvara dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'Och bära dig på sina händer, att du icke stöter din fot emot stenen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Då svarade Jesus, och sade till honom: Det är sagdt: Du skall icke fresta Herran din Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Och sedan djefvulen hade fullkomnat all frestelsen, for han ifrå honom till en tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Och Jesus kom, genom Andans kraft, in i Galileen igen; och ryktet gick ut om honom i all den ängden deromkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Och han lärde i deras Synagogor, och vardt prisad af allom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Och han kom till Nazareth, der han uppfödder var; och gick om Sabbathsdagen in i Synagogon, som hans sedvänja var, och stod upp, och ville läsa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Då vardt honom fången Esaie Prophetens bok; och då han lät upp bokena, fann han det rummet, der skrifvet står:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Herrans Ande är öfver mig, derföre att han hafver smort mig; till att förkunna Evangelium dem fattigom hafver han sändt mig, till att läka de förkrossada hjerta; till att predika de fångar frihet, och dem blindom syn, och dem sönderslagnom förlossning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Till att predika Herrans behageliga år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Sedan lade han boken tillhopa, och fick tjenarenom, och satte sig; och allas deras ögon, som i Synagogone vore, aktade på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Då begynte han till att säga till dem: I dag är denna Skrift fullbordad för edor öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Och de båro honom alle vittnesbörd, och förundrade sig på de nådefulla ord, som gingo af hans mun, och sade: Är icke denne Josephs son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Då sade han till dem: Visserliga mågen I säga till mig denna liknelsen: Läkare, läk dig sjelfvan; huru stor ting hafve vi hört i Capernaum skedd vara; gör ock sådana här i ditt fädernesland.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Sade han: Sannerliga säger jag eder: Ingen Prophet är afhållen i sitt fädernesland.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Men jag säger eder i sanning: Många enkor voro i Israel, uti Elie tid, då himmelen igenlyckt var i tre år och sex månader, då stor hunger var öfver hela landet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Och till ingen af dem vardt Elias sänd; utan till ena enko uti Sareptha Sidons.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Och månge spitelske voro i Israel, i Elisei Prophetens tid; och ingen af dem vardt ren gjord, förutan Naeman af Syrien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Och alle, de i Synagogon voro, uppfylldes med vrede, då de detta hörde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Och uppreste sig emot honom, och drefvo honom utu staden, och ledde honom ut öfverst på klinten af berget, der deras stad på byggder var, och ville stört honom der utföre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Men han gick midt igenom dem sin väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Och han kom ned till den staden Capernaum i Galileen; och der lärde han dem om Sabbatherna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Och de förundrade sig på hans lärdom; ty med hans tal var väldighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Och uti Synagogon var en menniska besatt med en oren djefvuls anda; och han ropade med höga röst,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Sägandes: Hej, hvad hafve vi med dig, Jesu Nazarene? Äst du kommen till att förderfva oss? Jag vet ho du äst, nämliga den Guds Helige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Och Jesus näpste honom, sägandes: Var tyst, och gack ut af honom. Och djefvulen kastade honom midt ibland dem, och gick ut af honom, och gjorde honom ingen skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Och en förfärelse kom öfver dem alla; och de talade inbördes med hvarannan, sägande: Hvad skall detta vara? Ty han bjuder de orena andar med magt och väldighet, och de gå ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Och ryktet gick ut om honom allestäds i de landsändar deromkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Då Jesus uppstod utu Synagogon, gick han in i Simons hus. Och Simons svära betvingades med stora skälfvosot; då bådo de honom för henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Och han trädde in till henne, och näpste skälfvone; och skälfvan öfvergaf henne; och hon stod straxt upp, och tjente dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Då solen nedergick, alle de som hade sjukt folk af allahanda sjukor, ledde dem till honom; och han lade händerna på hvar och en, och gjorde dem helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Foro också djeflarna ut af mångom, ropade och sade: Du äst Christus, Guds Son; då näpste han dem, och stadde icke till att de skulle tala; ty de visste, att han var Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Då dager vardt, gick han ut i ödemarken; och folket sökte honom, och kommo till honom, och förhöllo honom, att han icke skulle gå ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Då sade han till dem: Andra städer måste jag ock predika Guds rike; ty jag är dertill sänd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Och han predikade uti de Synagogor i Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Och det begaf sig, då folket föll honom öfver, på det de skulle höra Guds ord; och han stod utmed sjön Genesaret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Och han såg två båtar stå i sjöstranden; men fiskarena voro utgångne af dem, till att två sin nät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Då gick han in uti en båt, som var Simons, och bad honom, att han skulle lägga litet ut ifrå landet. Och han satte sig, och lärde folket utu båten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Då han vände igen tala, sade han till Simon: Lägg ut på djupet, och kaster edor nät ut till drägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Då svarade Simon, och sade till honom: Mästar, vi hafve arbetat hela nattena, och fått intet; men på din ord vill jag kasta ut näten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Och då de det gjorde, beslöto de en mägta stor hop fiskar; och deras nät gick sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Och de vinkade till sina stallbröder, som voro uti den andra båten, att de skulle komma och hjelpa dem. Och de kommo, och uppfyllde båda båtarna, så att de begynte sjunka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Då Simon Petrus det såg, föll han till Jesu knä, sägandes: Herre, gack ut ifrå mig; ty jag är en syndig menniska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Ty en förskräckelse var kommen öfver honom, och öfver alla de med honom voro, för detta fiskafängets skull, som de fått hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Sammalunda ock öfver Jacobum och Johannem, Zebedei söner, som Simons stallbröder voro. Då sade Jesus till Simon: Var icke förfärad; härefter skall du taga menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Och de förde båda båtarna i land, och öfvergåfvo alltsammans, och följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Så begaf det sig, då han var uti en stad, och si, der var en man full med spitelsko; när han fick se Jesum, föll han ned på sitt ansigte, och bad honom, sägandes: Herre, om du vill, kan du göra mig renan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Då räckte han ut handena, och tog på honom, sägandes: Jag vill, var ren. Och straxt gick spitelskan bort af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Och han böd honom, att han det för ingom säga skulle; utan gack (sade han), och visa dig Prestenom, och offra för din renselse, efter som Mose budit hafver, dem till vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Och ryktet gick ändå vidare ut om honom, och mycket folk församlade sig, att de skulle höra honom, och blifva botade af honom ifrå deras krankheter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Men han gick afsides bort i ödemarkena, och bad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Och det begaf sig på en dag, då han lärde, och der voro de Phariseer och Skriftlärde sittande, som komne voro utaf alla städer i Galileen, och Judeen, och af Jerusalem; och Herrans kraft var till att göra dem helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Och si, någre män båro ena mennisko på en säng, hvilken borttagen var, och de sökte efter, huru de skulle komma honom in, och läggan framför honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Och då de icke funno, för folkets skull, på hvilko sidon de skulle bäst komma honom in, stego de upp på taket, och släppte honom ned genom taket, med sängen, midt för Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Och då han såg deras tro, sade han till honom: Menniska, dina synder varda dig förlåtna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Och de Skriftlärde och Phariseer begynte tänka, sägande: Ho är denne, som talar Guds hädelse? Ho kan förlåta synder, utan Gud allena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Då Jesus förmärkte deras tankar, svarade han, och sade till dem: Hvad tänken I uti edor hjerta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Hvilket är lättare säga: Dina synder varda dig förlåtna; eller säga: Statt upp, och gack?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Men på det I skolen veta, att Menniskones Son hafver magt på jordene förlåta synder, sade han till den borttagna: Dig säger jag, statt upp, tag dina säng, och gack i ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Och han stod straxt upp för deras ögon, tog sängen, deruti han legat hade, och gick sina färde hem i sitt hus, och prisade Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Och de förskräcktes alle, och lofvade Gud, och vordo fulle med fruktan, sägande: Vi hafve sett i dag sällsynt ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Sedan gick han ut, och fick se en Publican, benämnd Levi, sittandes vid tullen, och sade till honom: Följ mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Han stod upp, och följde honom, och öfvergaf alltsamman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Och Levi gjorde honom ett stort gästabåd i sitt hus; och der voro en stor hop Publicaner, och andre som med dem till bords såto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Och de Skriftlärde och Phariseer knorrade emot hans Lärjungar, sägande: Hvi äten I och dricken med de Publicaner och syndare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Då svarade Jesus, och sade till dem: De behöfva icke läkare, som helbregda äro, utan de som kranke äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Jag är icke kommen till att kalla de rättfärdiga, utan syndare, till bättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Då sade de till honom: Hvi fasta Johannis lärjungar så ofta, och bedja så mycket, sammalunda ock de Phariseers lärjungar; men dine Lärjungar äta och dricka?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Sade han till dem: Icke kunnen I drifva bröllopsfolket till att fasta, så länge brudgummen är när dem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Men de dagar skola komma, att brudgummen varder tagen ifrå dem; då skola de fasta i de dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Och han sade ock till dem en liknelse: Ingen sätter en klut af nytt kläde på gammalt kläde; annars söndersliter han det nya, och den kluten af det nya skickar sig icke efter det gamla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Och ingen låter nytt vin i gamla flaskor; annars slår det nya vinet flaskorna sönder, och spilles ut, och flaskorna blifva förderfvade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Utan nytt vin skall man låta uti nya flaskor, och så blifva de både förvarad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Och ingen, som dricker gammalt vin, begärar straxt nytt; ty han säger: Det gamla är bättre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Och det begaf sig på en Eftersabbath, att han gick igenom säd; och hans Lärjungar ryckte upp ax, och gnuggade sönder med händerna, och åto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Då sade somlige af de Phariseer till dem: Hvi gören I det som icke är lofligit göra om Sabbatherna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Svarade Jesus, och sade till dem: Hafven I icke läsit hvad David gjorde, då han hungrade, och de med honom voro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Huru han gick in i Guds hus, och tog skådobröden, och åt, och gaf desslikes dem som med honom voro; hvilket ingom lofligit var att äta, utan allenast Prestomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Och sade han till dem: Menniskones Son är en Herre, desslikes ock öfver Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Och det begaf sig på en annan Sabbath, att han gick in uti Synagogon, och lärde; och der var en menniska, hvilkens högra hand var borttvinad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Och de Skriftlärde och Phariseer vaktade på honom, om han någon helbregda gjorde på Sabbathen, att de måtte finna något, der de kunde anklagan före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Men han förstod deras tankar, och sade till menniskona, som den tvinada handen hade: Statt upp, och gack fram. Han stod upp, och gick fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Då sade Jesus till dem: Jag skall spörja eder: Må man göra väl om Sabbatherna, eller göra illa; hjelpa lifvet, eller förspillat?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Och han såg sig om på dem alla, och sade till menniskona: Räck ut dina hand. Han ock så gjorde. Och hans hand vardt honom färdig, såsom den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Men de vordo ursinnige, och talades vid emellan sig, hvad de skulle göra åt Jesus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Så hände det uti de dagar, att han utgick uppå ett berg till att bedja; och blef der öfver nattena i bönen till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Och då dager vardt, kallade han sina Lärjungar; och utvalde tolf af dem, hvilka han ock kallade Apostlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simon, den han ock kallade Petrus, och Andreas, hans broder, Jacobus och Johannes, Philippus och Bartholomeus,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Mattheus och Thomas, Jacobus, Alphei son, och Simon, som kallas Zelotes,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Och Judas, Jacobs (son), och Judas Ischariothes, den ock förrädaren var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Och han gick neder med dem, och stod på en plats i markene, och hele hopen af hans Lärjungar, och ganska mycket folk utaf allt Judiska landet, och Jerusalem, och ifrå Tyrus och Sidon, som vid hafvet ligga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Hvilke komne voro, på det de ville höra honom, och varda botade af sina sjukdomar. Och de, som qvalde voro af de orena andar, vordo helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Och allt folket for efter att taga på honom; ty af honom gick kraft, som alla botade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Och han lyfte upp sin ögon öfver sina Lärjungar, och sade: Salige ären I fattige; ty Guds rike hörer eder till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Salige ären I, som nu hungren; ty I skolen blifva mättade. Salige ären I, som nu gråten; ty I skolen le.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Salige varden I, då menniskorna hata eder, och afskilja eder, och banna eder, och bortkasta edart namn, såsom det ondt vore, för menniskones Sons skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Glädjens och fröjdens på den dagen; ty si, edor lön är mycken i himmelen; sammalunda hafva deras fäder ock gjort Prophetomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Men ve eder, som rike ären; ty I hafven edar hugnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Ve eder, som mätte ären; ty I skolen hungra. Ve eder, som nu len; ty I skolen gråta och sörja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Ve eder, då alla menniskor lofva eder; ty sammalunda hafva ock deras fäder gjort dem falska Prophetomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Men eder, som hören, säger jag: Älsker edra ovänner; görer dem godt, som hata eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Välsigner dem som eder banna, och beder för dem som eder orätt göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Den dig slår på det ena kindbenet, dem håll ock det andra till; och den dig tager mantelen ifrå, honom förhåll icke heller kjortelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Hvarjom och enom, som något begärar af dig, honom gif; och af den, som dina ting tager ifrå dig, beds intet igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Och såsom I viljen att menniskorna skola göra eder, görer ock I dem sammalunda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Och om I älsken dem, som eder älska, hvad tack hafven I derföre? Ty syndarena älska ock dem, af hvilka de älskade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Och om I gören dem godt, som eder godt göra, hvad tack hafven I derföre? Ty syndarena göra det ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Och om I lånen dem, der I hoppens få något igen, hvad tack hafven I derföre? Ty syndarena låna ock syndarom, på det de skola få lika igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Utan heldre älsker edra ovänner, och görer väl, och låner, förhoppandes der intet af; och edor lön skall vara mycken, och I skolen vara dens Högstas barn; ty han är mild emot de otacksamma och onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Varer fördenskull barmhertige, såsom edar Fader ock barmhertig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Dömer icke så varden I icke dömde; fördömer icke, så varden I icke fördömde; förlåter, så varder eder förlåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Gifver, så varder eder gifvet; ett godt mått, väl stoppadt, skakadt och öfverflödande, skall man gifva uti edart sköt; ty med samma mått, som I mäten, skola andre mäta eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Och han sade till dem en liknelse: Kan ock en blinder leda en blindan? Falla de icke både i gropena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Lärjungen är icke öfver sin Mästare; men hvar och en är fullkommen, då han är såsom hans Mästare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Hvad ser du ett grand uti dins broders öga; men en bjelka uti ditt eget öga varder du intet varse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Eller huru kan du säga till din broder: Broder, håll, jag vill borttaga grandet, som uti ditt öga är; och du ser icke sjelf bjelkan uti ditt öga? Du skrymtare, tag först bort bjelkan utu ditt öga, och sedan se till att du kan uttaga grandet, som är i dins broders öga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Ty det är icke godt trä, som gör onda frukt; ej heller ondt trä, som gör goda frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Ty hvart och ett trä varder kändt af sine frukt; ty icke hemtar man heller fikon af törne; ej heller hemtar man vinbär af tistelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'En god menniska bär godt fram utaf sins hjertas goda fatabur, och en ond menniska bär ondt fram utaf sins hjertas onda fatabur; ty deraf hjertat fullt är, det talar munnen af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Hvad kallen I mig Herra, Herra; och gören dock icke hvad jag säger eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Hvilken som kommer till mig, och hörer min ord, och gör derefter, jag vill låta eder se, hvem han lik är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Han är lik enom man, som bygger ett hus; hvilken grof djupt, och lade grundvalen på hälleberget; då floden kom, strömmade hon in på huset, och kunde dock intet röra det; ty det var grundadt på hälleberget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Men den der hörer, och icke gör, han är lik enom man, som byggde sitt hus på jordena, utan grundval; der strömmade floden in på, och straxt föll det; och dess hus fall var stort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Då han all sin ord uttalat hade för folket, gick han till Capernaum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Och en höfvitsmans tjenare låg dödssjuk, och han var honom kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Då han hörde af Jesu, sände han de äldsta af Judarna till honom, och bad honom att han ville komma, och göra hans tjenare helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Då de kommo till Jesum, bådo de honom fliteliga, sägande: Han är värd, att du gör honom det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Ty han hafver vårt folk kärt, och hafver byggt oss Synagogon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Då gick Jesus med dem. Och då han icke långt var ifrå huset, sände höfvitsmannen sina vänner till honom, och sade: Herre, gör dig icke omak; ty jag är icke värdig, att du går under mitt tak;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Hvarföre jag ock icke räknade mig sjelfvan värdigan till att komma till dig; utan säg med ett ord, så varder min tjenare helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Ty jag är ock en man, stadder under härskap, och hafver krigsknektar under mig; och jag säger till den ena: Gack, och han går; och till den andra: Kom, och han kommer; och till min tjenare: Gör det, och han gör så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Då Jesus detta hörde, förundrade han sig på honom, och vände sig om, och sade till folket, som följde honom: Det säger jag eder, så stora tro hafver jag icke funnit i Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Och de, som utsände voro, gingo hem igen, och funno tjenaren helbregda, som sjuk var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Så begaf det sig sedan, att han gick uti den staden, som kallas Nain; och med honom gingo månge hans Lärjungar, och mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Då han nu kom intill stadsporten, si, då bars der ut en döder, sine moders ende son, och hon var enka; och en stor hop folk af staden gick med henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Då Herren såg henne, varkunnade han sig öfver henne, och sade till henne: Gråt icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Och han gick till, och tog på bårena; och de, som båro, stadnade. Då sade han: Jag säger dig, unger man, statt upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Och den döde satte sig upp, och begynte tala; och han fick honom hans moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Och en räddhåge kom öfver alla, och de prisade Gud, sägande: En stor Prophet är uppkommen ibland oss, och Gud hafver sökt sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Och detta ryktet om honom gick ut öfver allt Judiska landet, och all de land deromkring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Och Johannis lärjungar underviste honom om allt detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Och han kallade till sig två af sina lärjungar, och sände dem till Jesum, sägandes: Äst du den som komma skall, eller skole vi vänta någon annan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Då männerna kommo till honom, sade de: Johannes Döparen sände oss till dig sägandes: Äst du den som komma skall, eller skole vi vänta en annan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'På samma tiden gjorde han många helbregda af sjukdomar och plågor, och onda andar; och gaf mångom blindom syn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Då svarade Jesus, och sade till dem: Går, och säger Johanni igen, hvad I sett och hört hafven: De blinde se, de halte gå, de spitelske varda rene, de döfve höra, de döde stå upp igen, dem fattigom varder Evangelium predikadt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Och salig är den som icke förargas på mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Och då Johannis sändebåd voro sin väg gångne, begynte Jesus tala till folket om Johanne: Hvad gingen I ut i öknen till att se? Villen I se en rö, som drifs af vädret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Eller hvad gingen I ut till att se? Villen I se en mennisko, klädd i len kläder? Si, de som hafva härlig kläder uppå, och lefva i kräslighet, äro i Konungsgårdarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Eller hvad gingen I ut till att se? Villen I se en Prophet? Ja, säger jag eder, och mer än en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Han är den, derom skrifvet är: Si, jag sänder min Ängel för ditt ansigte, hvilken din väg bereda skall för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Ty jag säger eder, att ibland dem, som af qvinnor födde äro, är ingen större Prophet uppkommen än Johannes Döparen; dock likväl, den der minst är i Guds rike, han är större än han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Och allt folket, som honom hörde, och de Publicaner, gåfvo Gudi rätt, och läto sig döpa med Johannis döpelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Men de Phariseer och de lagkloke föraktade Guds råd emot sig sjelfva, och läto sig intet döpa af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Sedan sade Herren: Vid hvem skall jag dock likna menniskorna af detta slägtet? Och hvem äro de like?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'De äro like vid barn, som sitta på torget, och ropa emot hvarannan, och säga: Vi hafve pipat för eder, och I hafven intet dansat; vi hafve sjungit sorgesång för eder, och I greten intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Ty Johannes Döparen kom, och hvarken åt bröd, eller drack vin; och I sägen: Han hafver djefvulen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Menniskones Son är kommen, äter och dricker; och I sägen: Si, den mannen är en fråssare och vindrinkare, de Publicaners och syndares vän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Och visdomenom varder rätt gifvet af all sin barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Så bad honom en af de Phariseer, att han skulle få sig mat med honom; och han gick uti Phariseens hus, och satt der till bords.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Och si, en qvinna i staden, som hade varit en synderska, då hon förnam att han till bords satt i Phariseens hus, bar hon dit ett glas med smörjelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'Och stod bakför honom vid hans fötter, gråtandes, och begynte väta hans fötter med tårar, och torkade med sitt hufvudhår; och kysste hans fötter, och smorde dem med smörjelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Då den Phariseen, som honom budit hade, såg detta, sade han vid sig sjelf: Vore denne en Prophet, visserliga visste han ho och hurudana denna qvinnan är, som handterar honom; ty hon är en synderska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Då svarade Jesus, och sade till honom: Simon, jag hafver något säga dig. Han sade: Mästar, säg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'En man hade två gäldenärar; en var honom skyldig femhundrade penningar, och den andra femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'När de icke magt hade att betala, gaf han dem bådom till. Säg nu, hvilken af dem varder honom mera älskandes?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Svarade Simon, och sade: Jag menar, att den som han gaf mera till. Då sade han till honom: Rätt dömde du.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Och så vände han sig till qvinnona, och sade till Simon: Ser du denna qvinnona? Jag gick in i ditt hus; du hafver intet vatten gifvit mig till mina fötter; men hon hafver vätt mina fötter med tårar, och torkat med sitt hufvudhår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Du hafver icke kysst mig; men hon, sedan jag här ingick, hafver icke låtit af kyssa mina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Mitt hufvud hafver du icke smort med oljo; men hon hafver smort mina fötter med smörjelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Hvarföre säger jag dig: Henne varda många synder förlåtna; ty hon älskade mycket; men den som mindre förlåtes, han älskar mindre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Sedan sade han till henne: Synderna förlåtas dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Då begynte de, som med honom till bords såto, säga vid sig: Ho är denne, som ock synder förlåter?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Då sade han till qvinnona: Din tro hafver frälst dig; gack med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Och det begaf sig derefter, att han vandrade i städer och byar, predikade och förkunnade Evangelium om Guds rike; och de tolf med honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'Dertill några qvinnor, som han hade helbregda gjort ifrå de onda andar och krankheter, nämliga: Maria, som kallas Magdalena, af hvilka sju djeflar utgångne voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Och Joanna, Chuse hustru, Herodis fogdes, och Susanna, och många andra, som honom tjente af sina ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Då nu mycket folk kom tillhopa, och utaf städerna sökte till honom, talade han genom liknelse:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'En sädesman gick ut till att så sina säd; och vid han sådde, föll somt vid vägen, och vardt förtrampadt, och foglarna under himmelen åto det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Och somt föll på hälleberget, och då det uppgick, förtorkades det; ty det hade ingen vätsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Och somt föll ibland törne, och törnen gingo med upp, och förqvafde det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Och somt föll i goda jord; och det gick upp, och gjorde hundradefald frukt. Då han detta sade, ropade han: Den der hafver öron till att höra, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Då frågade honom hans Lärjungar, hurudana denna liknelsen var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Han sade till dem: Eder är gifvet veta Guds rikes hemlighet, men dem androm genom liknelse; på det att, ändock de se, skola de likväl icke se, och ändock de höra, skola de likväl icke förstå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Så är nu denna liknelsen. Säden är Guds ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Men de som vid vägen, det äro de som höra; sedan kommer djefvulen, och tager bort ordet utu deras hjerta, att de icke tro skola, och blifva frälste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Men de som på hälleberget, det äro de som, när de höra, anamma de ordet med glädje, och de hafva inga rötter; de der tro till en tid, och då frestelsen påkommer, falla de derifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Men det som föll ibland törnen, äro de som höra; och gå bort, och varda förqvafde af omsorger, och rikedomar, och lifsens vällust; och bära ingen frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Men det uti goda jord, äro de som höra ordet, och behålla det uti ganska godt hjerta; och bära frukt i tålamod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Men ingen upptänder ett ljus, och skyler det under något kar, eller sätter under bänken; utan sätter det på ljusastakan, att de, som ingå, skola få se ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Ty det är intet lönligit, som icke skall varda uppenbart; och intet fördoldt, det icke skall kunnigt varda, och uppkomma skall i ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Ser fördenskull till, huru I hören; ty den der hafver, honom varder gifvet, och den der intet hafver, det han menar sig hafva, det skall ock tagas ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Så gingo till honom hans moder och hans bröder; och kunde dock icke komma till honom, för folkets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Då vardt honom bådadt, och sagdt: Din moder och dine bröder stå härute, och vilja se dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Svarade han, och sade till dem: Min moder och mine bröder äro desse, som höra Guds ord, och görat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Så begaf det sig på en dag, att han steg uti ett skepp, med sina Lärjungar, och sade till dem: Låt oss fara öfver sjön. Och de lade utaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Sedan, vid de foro öfver, somnade han; och der reste upp ett stort väder på sjön; och de förfylldes, och voro i stor fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Så gingo de till, och väckte honom upp, sägande: Mästar, Mästar, vi förgås. Då stod han upp, och näpste vädret och vattnens våg; och så vände det igen, och blef stilla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Och han sade till dem: Hvar är edar tro? Men de fruktade, och förundrade, sägandes emellan sig: Ho må denne vara? Ty han bjuder både vädrena och vattnena; och de lyda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Och de foro till de Gadareners ängd, hvilken är tvärt öfver Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Och då han utgången var af skeppet på landet, mötte honom en man utaf staden, hvilken hade haft djefvulen i lång tid; och han hade inga kläder på, ej heller blef i husen, utan i grifter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Då han såg Jesum, ropade han, och föll ned framför honom, och sade med höga röst: Hvad hafver jag göra med dig, Jesu, dens högstas Guds Son? Jag beder dig, att du icke qväl mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Ty han böd dem orena andanom, att han skulle fara ut af mannenom; ty han hade länge plågat honom; och han vardt bunden i kedjor, och förvarad i fjettrar, och slet sönder banden, och vardt drifven af djefvulen bort i öknen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Då frågade Jesus honom, och sade: Hvad är ditt namn? Han sade: Legio; ty månge djeflar voro inkomne i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Och de bådo honom, att han icke skulle bjuda dem fara uti afgrunden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Men der var en stor svinahjord, som der gick och födde sig på berget. Då bådo de honom, att han ville tillstädja dem fara in i svinen; och han tillstadde dem det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Då foro djeflarna utu menniskone, och foro in uti svinen; och hjorden brådstörte sig uti sjön, och fördränkte sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Men när de, som vaktade svinen, sågo hvad der skedde, flydde de, och båro tidenden i staden, och på bygdena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Då gingo de ut, till att se hvad der skedt var, och kommo till Jesum; och funno mannen, der djeflarna utaf farne voro, klädd och vid sin sinne, sittandes vid Jesu fötter; och vordo förfärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Och de som det sett hade, förkunnade dem desslikes, huruledes den besatte var helbregda vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Och hele hopen af de Gadareners omliggande bådo honom, att han ville fara ifrå dem; ty dem var en stor räddhåge påkommen. Då steg han till skepps, och for tillbaka igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Men mannen, der djeflarna voro utaf farne, bad honom att han måtte blifva när honom. Men Jesus sände honom ifrå sig, sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Gack uti ditt hus igen, och säg utaf, huru stor ting Gud med dig gjort hafver. Och han gick bort, och förkunnade öfver hela staden, huru stor ting Jesus hade gjort med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Och det begaf sig, då Jesus kom igen, undfick honom folket; ty alle vänte efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Och si, der kom en man, som het Jairus, och var en öfverste för Synagogon; han föll ned för Jesu fötter, bedjandes honom, att han ville gå i hans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Ty han hade ena enda dotter, vid tolf åra gammal, och hon begynte själas; men i vägen, vid han gick dit, trängde honom folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Och en qvinna, som blodgång hade haft i tolf år, och hade förtärt allt hvad hon ägde på läkare, och kunde dock botas af ingom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Hon gick bakefter, och tog på hans klädefåll; och straxt stillades hennes blodgång.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Och Jesus sade: Ho är den, som tog på mig? Då de alle nekade, sade Petrus, och de med honom voro: Mästar, folket tränger dig, och omakar dig, och du säger: Ho tog på mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Då sade Jesus: Någor hafver ju tagit på mig; ty jag kände, att kraft gick af mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Då qvinnan såg, att det icke var lönligit, kom hon skälfvandes, och föll ned för hans fötter, och förkunnade för allo folkena, för hvad saks skull hon hade tagit på honom, och huruledes hon blef straxt helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Då sade han till henne: Var tröst, min dotter, din tro hafver frälst dig; gack med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Vid han ännu talade, kom en utaf öfverstans hus för Synagogon, sägandes till honom: Din dotter är död; gör icke Mästaren omak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Då Jesus hörde det ordet, sade han till pigones fader: Räds intet; utan tro allenast, och hon varder helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Då han kom i huset, stadde han ingom ingå med sig, utan Petrum, Jacobum och Johannem, och fadren och modren till pigona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Men de greto alle, och jämrade sig öfver henne. Då sade han: Gråter icke; pigan är icke död, men hon sofver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Då gjorde de spe af honom, väl vetande att hon var död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Men han dref dem alla ut, och tog henne vid handena, och ropade, sägandes: Piga, statt upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Och hennes ande kom igen, och hon stod straxt upp; och han böd gifva henne mat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Och hennes föräldrar förskräcktes. Men han böd dem, att de ingom säga skulle, hvad der skedt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Sedan kallade Jesus tillhopa de tolf, och gaf dem magt och våld öfver alla djeflar, och att de sjukdomar bota kunde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Och sände dem ut till att predika Guds rike, och göra de sjuka helbregda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Och sade till dem: Tager intet med eder till vägs, icke käpp, eller skräppo, icke bröd, icke penningar; hafver ej heller två kjortlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Och i hvad hus I ingån, der blifver, tilldess I dragen dädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Och hvilke icke anamma eder, så går ut af den staden, och skudder ock stoftet af edra fötter, till vittnesbörd öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Och de gingo ut, och vandrade omkring i byarna, predikade Evangelium, och gjorde helbregda allestäds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Då fick Herodes Tetrarcha höra allt det som bedrefs af honom, och honom begynte misshaga; ty det sades af somligom, att Johannes var uppstånden af döda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'Af somligom, att Elias var uppenbarad; af somligom, att någor Prophet af de gamla var uppstånden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Och Herodes sade: Johannem hafver jag halshuggit; men ho är denne, der jag sådant af hörer? Och begärade se honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Och Apostlarna kommo igen, och förtäljde honom allt det de gjort hade. Då tog han dem med sig, och gick afsides uti ena ödemark, som ligger vid den staden, som kallas Bethsaida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Då folket det förnam, kommo de efter honom; och han undfick dem, och talade med dem om Guds rike, och gjorde dem helbregda, som det behöfde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Men dagen begynte varda framliden; då gingo de tolf fram, och sade till honom: Låt folket ifrå dig, att de gå uti köpstäderna, och nästa bygdena, der de måga gästa, och finna mat; ty vi äre här i ödemarkene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Han sade till dem: Gifver I dem äta. Då sade de: Vi hafve icke flera bröd än fem, och två fiskar; utan att vi gå bort, och köpe mat till allt detta folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Och voro de icke långt ifrå femtusend män. Då sade han till sina Lärjungar: Låter dem sätta sig ned, i hvart matskapet femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Och de gjorde så, och läto dem alla sätta sig ned.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Då tog han de fem bröd och de två fiskar; upplyfte sin ögon i himmelen, tackade deröfver, bröt och fick Lärjungarna, att de skulle sedan läggat fram för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Och de åto alle, och vordo mätte. Sedan vardt upptaget det som dem öfverlopp, tolf korgar fulle med stycker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Och det begaf sig, då han var allena i sina böner, voro ock någre hans Lärjungar med honom; dem frågade han, och sade: Hvem säga folket mig vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Då svarade de, och sade: Johannes Döparen; somlige Elias, och somlige, att någon Prophet af de gamla är uppstånden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Då sade han till dem: Hvem sägen då I mig vara? Svarade Petrus, och sade: Du äst Guds Christ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Och han hotade dem, och förböd, att de skulle det någrom säga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Och sade: Menniskones Son måste mycket lida, och bortkastas af de äldsta, och öfversta Presterna, och Skriftlärda, och dräpas, och tredje dagen uppstå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Sade han ock till dem alla: Hvilken mig efterfölja vill, han vedersäge sig sjelf, och tage sitt kors på sig hvar dag, och följe mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Ty den, som vill behålla sitt lif, han skall mista det; och ho som mister sitt lif för mina skull, han skall det behålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Och hvad kommer det menniskone till godo, om hon vunne hela verldena, och förtappar sig sjelf, eller gör skada på sig sjelf?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Hvilken som blyges vid mig och min ord, vid honom skall ock menniskones Son blygas, då han kommer i sin, och sins Faders, och de heliga Änglars härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Men jag säger eder förvisso, att någre äro af dem som här stå, de der icke skola smaka döden, tilldess de få se Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Så begaf det sig, vid åtta dagar efter dessa orden, att han tog till sig Petrum, och Johannem, och Jacobum; och gick upp på ett berg till att bedja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Och vid han bad, vardt hans ansigte förvandladt, och hans klädnad var hvit och skinande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Och si, två män talade med honom, som voro Moses och Elias;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Och syntes i härlighet, och talade om hans afgång, som han fullborda skulle i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Men Petrus, och de med honom voro, förtyngdes af sömn; då de uppvaknade, sågo de hans klarhet, och de två män stå när honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Och det begaf sig, då de gingo ifrå honom, sade Petrus till Jesum: Mästar, oss är godt här vara; låt oss göra tre hyddor, en till dig, och en till Mosen, och en till Eliam; och visste icke hvad han sade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Och vid han så sade, kom en sky, och kringskyggde dem; och de vordo förfärade, vid de vordo invefvade i skyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Och en röst hördes utu skynom, den der sade: Denne är min älskelige Son; honom hörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Och i det samma rösten hördes, funno de Jesum vara allena. Och de tigde, och förkunnade ingom, i de dagar, något af det de sett hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Så hände sig dagen derefter, då de gingo ned af berget, mötte honom mycket folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Och si, en man af folket ropade, och sade: Mästar, jag beder dig, se till min son; ty han är mitt enda barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Si, anden begriper honom, och straxt ropar han; och han sliter honom, så att han fradgas; och han far med nöd ifrå honom, då han honom slitit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Och jag bad dina Lärjungar, att de skulle utdrifva honom; och de kunde icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Då svarade Jesus, och sade: O! du otrogna och genstörtiga slägte, huru länge skall jag vara när eder, och lida eder? Haf din son hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Och vid han nu framgick, ref och slet djefvulen honom. Men Jesus näpste den orena andan, och gjorde pilten helbregda, och fick honom sinom fader igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Och alle vordo förskräckte öfver Guds härlighet. Då alle undrade på allt det han gjorde, sade han till sina Lärjungar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Fatter dessa orden uti edor öron, ty det skall ske, menniskones Son varder öfverantvardad i menniskors händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Men de förstodo icke detta ordet; och det var fördoldt för dem, att de det icke kunde förstå; och de fruktade att fråga honom om det ordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Och kom ibland dem en tanke, hvilkendera skulle störst vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Då Jesus såg deras hjertas tankar, tog han ett barn, och ställde det när sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'Och sade till dem: Hvilken som anammar detta barnet i mitt Namn, han anammar mig; och den mig anammar, han anammar honom, som mig sändt hafver; men den der minst är ibland eder alla, han skall vara störst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Då svarade Johannes, och sade: Mästar, vi sågom en, som utdref djeflar under ditt Namn, och vi förbödom honom det; efter det han icke följer med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Sade Jesus till honom: Förbjuder honom intet; ty den der icke emot oss är, han är med oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Och det begaf sig, då tiden fullbordad var, att han skulle hädantagen varda, vände han sitt ansigte till att fara åt Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Och han sände båd framför sig; de gingo, och kommo intill en stad, som de Samariter uti bodde, att de skulle reda för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Och de undfingo honom intet; ty han hade vändt sitt ansigte till att draga till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Då hans Lärjungar, Jacobus och Johannes, det sågo, sade de: Herre, vill du, så vilje vi säga, att elden måtte komma ned af himmelen, och förtära dem, såsom ock Elias gjorde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Men Jesus vände sig om, och näpste dem, sägandes: I veten icke, hvars andas I ären;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Ty menniskones Son är icke kommen till att förderfva menniskornas själar, utan till att frälsa dem. Och de gingo dädan uti en annan by.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Och det begaf sig, vid de gingo på vägen, sade en till honom: Jag vill följa dig, hvart du går, Herre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Sade Jesus till honom: Räfvarna hafva kulor, och foglarna under himmelen näste; men menniskones Son hafver icke, der han kan luta sitt hufvud till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Men han sade till en annan: Följ mig. Då sade han: Herre, låt mig först gå bort, och begrafva min fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Då sade Jesus till honom: Låt de döda begrafva sina döda; men du, gack, och förkunna Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'En annar sade: Herre, jag vill följa dig; men låt mig först gå, och skilja mig ifrå dem som i mitt hus äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Sade Jesus till honom: Hvilken som sätter sin hand till plogen, och ser tillbaka, han är icke beqväm för Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Sedan skickade Herren andra sjutio; och sände två och två framför sig, i alla städer och rum, dit han komma ville;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Och sade till dem: Säden är stor, men arbetarena äro få; beder fördenskull sädenes Herra, att han utsänder arbetare i sina säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Går; si, jag sänder eder såsom lamb ibland ulfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Bärer ingen säck, ej heller skräppo, ej heller skor; och helser ingen i vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Uti hvad hus I kommen, säger först: Frid vare desso huse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Och om der någor är fridsens barn, så skall eder frid blifva på honom; hvar ock icke, så kommer han till eder igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Uti det samma hus blifver, äter och dricker hvad eder föresätts; ty arbetaren är sin lön värd. Går icke utu hus i hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Och uti hvad stad I kommen, och de anamma eder, äter hvad eder föresätts;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Och görer de sjuka helbregda, som der äro, och säger till dem: Guds rike är kommet hardt när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Uti hvad stad I kommen, och de icke anamma eder, så går ut på hans gator och säger:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Det stoft, som lådde vid oss af edar stad, skake vi af på eder; dock skolen I veta, att Guds rike var kommet hardt när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Jag säger eder, att Sodome skall drägeligare varda på den dagen, än dem stadenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Ve dig, Chorazin; ve dig, Bethsaida; ty hade sådana krafter varit gjorda uti Tyro och Sidon, som de gjorde äro uti eder, länge sedan hade de suttit uti säck och asko, och gjort syndabättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Dock skall Tyro och Sidoni drägeligare varda på domenom än eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Och du, Capernaum, som upphäfven äst allt intill himmelen, du skall nedstört varda till helvete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Hvilken eder hörer, han hörer mig; och den eder föraktar, han föraktar mig; men den mig föraktar, han föraktar honom som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Men de sjutio kommo igen med glädje, och sade: Herre, djeflarna äro oss ock underdånige i ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Då sade han till dem: Jag såg Satanam falla af himmelen, såsom en ljungeld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Si, jag hafver gifvit eder magt att trampa på ormar och scorpioner, och öfver all fiendans kraft; och eder skall intet varda skadandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Dock fröjder eder icke deraf, att andarna äro eder underdånige; utan fröjder eder, att edor namn äro skrifven i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'I samma stundene fröjdade sig Jesus i Andanom, och sade: Jag prisar dig, Fader, himmelens och jordenes Herre, att du hafver detta fördolt för de visa och kloka, och hafver det uppenbarat för de fåkunniga; ja, Fader; ty så hafver varit behageligit för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'All ting äro mig antvardad af minom Fader; och ingen vet ho Sonen är, utan Fadren; och ho Fadren är, utan Sonen och den som Sonen vill det uppenbara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Och han vände sig om till sina Lärjungar afsides, och sade: Salig äro de ögon, som se det I sen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Ty jag säger eder: Månge Propheter och Konungar åstundade se det I sen, och fingo dock icke set; och höra det I hören, och fingo dock icke hörat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Och si, en lagklok stod upp, och frestade honom, sägandes: Mästar, hvad skall jag göra, att jag må få evinnerligit lif?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Då sade han till honom: Hvad är skrifvet i lagen? Huru läs du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Svarade han, och sade: Du skall älska din Herra Gud, af allt ditt hjerta, och af allo dine själ, och af alla dina krafter, och af allom dinom håg; och din nästa, såsom dig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Då sade han till honom: Rätteliga svarade du; gör det, så får du lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Då ville han göra sig sjelfvan rättfärdigan, och sade till Jesum: Hvilken är då min näste?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Då svarade Jesus, och sade: En man for ned af Jerusalem till Jericho, och kom i röfvarehänder; och de klädde af honom, och sargade honom, och gingo dädan, och läto honom ligga halfdödan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Så hände sig, att en Prest for neder åt samma vägen; och då han fick se honom, gick han framom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Sammalunda ock en Levit, då han kom till det samma rummet, gick han fram, och såg på honom; och gick sedan framom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Men en Samaritan reste samma vägen, och kom till honom; och när han såg honom, varkunnade han sig öfver honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Och gick till, och förband hans sår, och göt der oljo och vin in; och laden på sin ök, och förde honom till herberget, och skötte honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Den andra dagen for han dädan, och tog fram två penningar, och gaf värdenom, och sade till honom: Sköt honom; och hvad du mer kostar på honom, vill jag betala dig, när jag kommer igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Hvilken af dessa tre synes dig nu hafva varit hans näste, som för röfvarena kommen var?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Sade han: Den som beviste honom barmhertighet. Då sade Jesus till honom: Gack, och gör du sammaledes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Men det begaf sig, då de vandrade, gick han uti en liten stad; och en qvinna, benämnd Martha, undfick honom uti sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Och hon hade en syster, benämnd Maria; hon satte sig vid Jesu fötter, och hörde hans ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Men Martha bekymrades med idkelig tjenst. Hon gick fram, och sade: Herre, sköter du intet derom, att min syster låter mig tjena allena? Så säg henne nu, att hon hjelper mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Svarade Jesus, och sade till henne: Martha, Martha, du hafver omsorg och bekymmer om mångahanda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Men ett är nödtorftigt; Maria hafver utkorat den goda delen, hvilken henne icke skall ifråtagas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Och det begaf sig, att han bad uti ett rum; då han vände igen, sade en af hans Lärjungar till honom: Herre, lär oss bedja, såsom ock Johannes lärde sina Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Då sade han till dem: När I bedjen, säger så: Fader vår, som äst i himlom, helgadt varde ditt Namn. Tillkomme ditt rike. Ske din vilje, såsom i himmelen, så ock på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Gif oss alltid vårt dageliga bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Och förlåt oss våra synder; ty ock vi förlåte allom, som oss skyldige äro. Och inled oss icke uti frestelse; utan fräls oss ifrån ondo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Och sade han till dem: Hvilken är ibland eder, som hafver en vän, och han går till honom om midnattstid, och säger till honom: Käre vän, låna mig tre bröd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Ty min vän är kommen till mig, vägfarandes, och jag hafver intet lägga för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Och den, som innanföre är, svarar, och säger: Gör mig icke omak; dörren är nu stängd, och min barn äro med mig i säng; jag kan icke stå upp, och få dig det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Jag säger eder: Om han än icke uppstår, och får honom det, derföre att han är hans vän; likväl, derföre att han så trägen är, står han upp, och får honom så mycket han behöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Så säger ock jag eder: Beder, och eder skall gifvet varda; söker, och I skolen finna; klapper, och eder skall varda upplåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Ty den der beder, han får; och den der söker, han finner: och den der klappar, honom varder upplåtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Hvilken ibland eder är den fader, om hans son bedes bröd af honom, som gifver honom en sten? Eller om han bedes fisk, månn han gifva honom en orm för fisk?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Eller om han bedes ägg, månn han få honom en scorpion?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Kunnen nu I, som onde ären, gifva edor barn goda gåfvor; huru mycket mer skall edar himmelske Fader gifva den Helga Anda dem som bedja honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Och han utdref en djefvul, som var en dumbe; och när djefvulen var utdrifven, talade dumben; och folket förundrade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Men somlige af dem sade: Han utdrifver djeflar med Beelzebub, djeflarnas öfversta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Och somlige frestade honom, begärandes af honom tecken af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Men efter han visste deras tankar, sade han till dem: Hvart och ett rike, som söndrar sig emot sig sjelft, det varder förödt, och hus faller på hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Är ock nu Satan söndrad emot sig sjelf, huru varder då hans rike ståndandes? Efter I sägen, att jag utdrifver djeflar med Beelzebub.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Men om jag utdrifver djeflar med Beelzebub, med hvem drifva då edor barn dem ut? Derföre skola de vara edra domare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Men om jag utdrifver djeflar med Guds finger, så är ju Guds rike kommet till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Då en stark beväpnad bevarar sitt hus, så blifver det i frid, som han äger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Men der en starkare tillkommer, och öfvervinner honom, tager han bort all hans vapen, der han tröste uppå, och skifter hans rof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Den icke med mig är, han är emot mig; och den icke församlar med mig, han förskingrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'När den orene anden går ut af menniskone, vandrar han omkring torra platser, söker efter hvilo, och finner ingen. Då säger han: Jag vill komma igen uti mitt hus, der jag utgick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Och när han kommer, finner han det rent sopadt, och väl tillpyntadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Då går han åstad, och tager till sig sju andra andar, som skadeligare äro än han; och de gå derin, och bo der; och den menniskones sista varder värre än det första.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Och det begaf sig, då han detta sade, hof en qvinna sina röst upp ibland folket, och sade till honom: Salig är den qveden, som dig burit hafver, och de spenar, som du ditt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Men han sade: Ja, salige äro de som höra Guds ord, och gömma det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Då folket trängdes intill, begynte han säga; Detta är ett ondt slägte; de begära tecken; och tecken skall dem icke gifvet varda, utan Jone Prophetens tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Ty såsom Jonas var de Nineviter ett tecken, så skall ock menniskones Son vara desso slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Drottningen af söderlanden skall uppstå på domen, med de män af detta slägtet, och skall fördöma dem; ty hon kom ifrå verldenes ända, till att höra Salomons visdom; och si, här är mer än Salomon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'De Ninevitiske män skola uppstå på domen, med detta slägtet, och skola fördöma det; ty de gjorde bättring efter Jone predikan; och si, här är mer än Jonas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Ingen upptänder ett ljus, och sätter det uti något hemligit rum, eller under en skäppo; utan på ljusastakan, att de, som inkomma, skola få se af ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Ögat är kroppsens ljus; när nu ditt öga är enfaldigt, så varder ock all din kropp ljus; är det ock argt, så varder ock din kropp mörk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Derföre se till, att ljuset, som i dig är, icke varder mörker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Om nu din kropp är allsammans ljus, och hafver ingen del af mörkret, så varder han allersamman ljus, och upplyser dig, såsom en klar ljungeld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Och vid han talade, bad honom en Pharisee, att han skulle få sig mat med honom. Då gick han in med honom, och satte sig till bords.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Men då Phariseen såg, att han icke tvådde sig, förr än han gick till bords, förundrade han sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Då sade Herren till honom: I Phariseer gören rent det som utvärtes är på dryckekaret och fatet; och det invärtes är i eder, är fullt med rof och ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'I dårar, den som gjorde det utvärtes är, hafver han ock icke gjort det invärtes är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Dock gifver almoso af det I hafven; och si, så äro eder all ting ren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Men ve eder, Phariseer; ty I gören tiond af mynto och ruto, och allahanda kål; och domen, och Guds kärlek låten I blifva tillbaka; ja, man måste detta göra, och dock det andra icke låta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Ve eder, Phariseer; ty I sitten gerna främst i Synagogorna, och viljen helsade varda på torgen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Ve eder, Skriftlärde och Phariseer, I skrymtare; ty I ären såsom de grifter, som intet synas, der folket går uppå, och vet der intet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Då svarade en af de lagkloka, och sade till honom: Mästar, du försmäder ock oss med dessa orden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Då sade han: Ve ock eder, I lagkloke; ty I läggen bördor på menniskorna, hvilka de icke draga kunna, och I tagen icke sjelfva på bördona med ett edart finger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Ve eder, I som byggen de Propheters grifter; men edre fäder slogo dem ihjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Sannerliga, I betygen, att I hållen deraf, som edre fäder gjort hafva; ty de slogo dem ihjäl, och I byggen deras grifter upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Derföre säger ock Guds visdom: Jag skall sända till dem Propheter och Apostlar; och af dem skola de några döda och förfölja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'På det att af detta slägtet skall utkrafdt varda alla Propheters blod, som utgjuten är, sedan verlden var skapad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Ifrån Abels blod intill Zacharie blod, som förgjordes emellan altaret och templet; visserliga säger jag eder, varder det utkrafdt af detta slägtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Ve eder, I lagkloke; ty I hafven fått nyckelen till förståndet; sjelfve gån I intet in, och förvägren dem som ingå vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'När han nu detta sade till dem, begynte de lagkloke och Phariseer gå hårdt åt honom, och listeliga fråga honom om mång stycker, med försåt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Sökande efter, att de något veda kunde af hans mun, der de måtte beklaga honom före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'När nu församladt vardt otaliga mycket folk, så att de trampade på hvarannan, begynte han säga till sina Lärjungar: Först tager eder vara för de Phariseers surdeg, som är skrymteri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Ty intet är fördoldt, som icke varder uppenbaradt; och intet lönligit, som icke uppkommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Derföre, hvad I sagt hafven i mörkret, det skall varda hördt i ljuset; och det I talat hafven i örat i kamrarna, det skall predikadt varda ofvanpå taken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Men jag säger eder, minom vännom: Rädens icke för dem som döda kroppen, och sedan hafva de intet hvad de mer göra kunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Men jag vill visa eder, hvem I skolen rädas: Rädens honom, som, sedan han dödat hafver, hafver han ock magt att bortkasta till helvetet; ja, säger jag eder, honom rädens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Köpas icke fem sparfvar för två små penningar? Och en af dem är icke förgäten för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Ja, edor hufvudhår äro ock all räknad; derföre frukter eder intet; I ären bättre än månge sparfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Men jag säger eder: Hvilken mig bekänner för menniskor, honom skall ock menniskones Son bekänna inför Guds Änglar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Men den mig nekar för menniskor, han skall ock nekad varda för Guds Änglar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Och den der talar ett ord emot menniskones Son, det skall varda honom förlåtet; men den som häder den Helga Anda, det skall icke förlåtas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'När de nu draga eder fram i Synagogorna, och för Öfverheten, och för de väldiga; hafver ingen omsorg, hvad och huruledes I svara, eller hvad I säga skolen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Ty den Helge Ande skall lära eder, i samma stundene, hvad I säga skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Då sade en af folket till honom: Mästar, säg minom broder, att han byter med mig arfvedelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Sade han till honom: Menniska, ho hafver skickat mig till domare eller skiftare öfver eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Och han sade till dem: Ser till, och tager eder vara för girighet; ty ens (menniskos) lif hänger icke derpå, att hon många ägodelar hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Och sade han en liknelse till dem, sägandes: Det var en riker man, hvilkens åker bar frukt nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Då tänkte han vid sig sjelf, sägandes: Hvad skall jag göra? Ty jag hafver icke, der jag kan lägga mina frukt uti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Och sade: Detta vill jag göra: Jag vill rifva omkull mina lador, och bygga upp större; och dit vill jag församla allt det mig växt är, och mina ägodelar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Och säga till min själ: Själ, du hafver mycket godt förvaradt intill mång år; gör dig goda dagar, ät, drick, var glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Men Gud sade till honom: Du dåre, i denna natt skall man kalla dina själ ifrå dig; ho skall då få det du tillredt hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Alltså går det ock honom, som sig församlar ägodelar, och icke är rik för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Och han sade till sina Lärjungar: Derföre säger jag eder: Hafver icke omsorg för edart lif, hvad I äta skolen; eller för edar kropp, hvad I skolen kläda eder med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Lifvet är mer än maten, och kroppen mer än kläden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Ser på korparna; ty de så intet, ej heller uppskära; de hafva hvarken källare eller lado, och Gud föder dem; huru mycket ären I bättre än foglarna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Hvilken af eder kan med sin omsorg föröka till sin växt en aln?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Kunnen I nu icke det som minst är, hvarföre hafven I då omsorg för det andra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Ser på liljorna, huru de växa; de arbeta intet, och ej heller spinna; men jag säger eder: Icke Salomon i all sin härlighet var så klädd, som en af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Efter nu Gud så kläder gräset, som i dag växer på markene, och i morgon kastas i ugnen; huru mycket mer skall han kläda eder, I klentrogne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Derföre fråger ock I intet efter, hvad I skolen äta, eller dricka; och farer icke i höjdena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Ty efter allt detta söka Hedningarna i verldene; men edar Fader vet väl, att I sådant behöfven;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Utan söker heldre efter Guds rike, så faller eder allt detta till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Frukta dig icke, du klene hjord; ty edar Faders godvilje är så, att han vill gifva eder riket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Säljer hvad I hafven, och gifver almoso; görer eder säcker, som icke föråldras; en skatt, som aldrig minskas i himmelen, der tjufven aldrig tillkommer, ej heller någor mal förderfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Ty der edar skatt är, der blifver ock edart hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Låter edra länder vara omgjordade, och edor ljus brinnande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Och varer I de menniskor like, som vänta sin herra, då han igenkomma skall ifrå bröllopet; att, när han kommer, och klappar, låta de honom straxt upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Salige äro de tjenare, hvilka herren finner vakande, då han kommer; sannerliga säger jag eder: Han skall uppskörta sig, och låta dem sitta till bords, och han skall då gå och tjena dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Och om han kommer uti den andra väkten, och uti den tredje väkten, och finner så; salige äro de tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Men detta skolen I veta, att, om husbonden visste på hvad stund tjufven komma skulle, förvisso vakade han, och icke tillstadde uppbryta sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Derföre varer ock I redo; ty den stund, I icke tänken, skall menniskones Son komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Då sade Petrus till honom: Herre, säger du till oss denna liknelsen, eller ock till alla?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Då sade Herren: Hvar finner man en trogen och snäll skaffare, den hans herre sätter öfver sitt tjenstafolk, att han dem i rättan tid gifver hvad dem behörer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Salig är den tjenaren, den herren finner så göra, då han kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Sannerliga säger jag eder, han skall sätta honom öfver allt det han äger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Men om den tjenaren sade i sitt hjerta: Min herre dröjer fast att komma igen; och begynte slå tjenarena och tjenarinnorna, och äta och dricka, och varda drucken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Så kommer dens tjenarens herre, på den dagen han det sig icke förmodar, och på den stundene den han icke vet; och skall hugga honom i stycker, och skall sätta hans lott med de otrogna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Men den tjenaren, som visste sins herras vilja, och icke beredde sig, och icke gjorde efter hans vilja, han skall lida mycken hugg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Men den der icke visste, och gjorde dock det som hugg värdt var, han skall få hugg lida; ty dem som mycket gifvet är, af honom skall mycket varda utkrafdt; och hvem mycket befaldt är, af honom skall varda mycket äskadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Jag är kommen till att upptända en eld på jordene; och hvad vill jag heldre än att han allaredo brunne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Men jag måste med en döpelse döpas; och huru ängslas jag, tilldess hon fullbordad varder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Menen I, att jag är kommen till att sända frid på jordena? Nej, säger jag eder; utan visserliga tvedrägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Ty härefter skola fem vara skiljaktige uti ett hus; tre emot två, och två emot tre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Fadren skall vara emot sonen, och sonen emot fadren; modren emot dottrena, och dottren emot modrena; sväran emot sina sonahustru, och sonahustrun emot sina sväro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Sade han ock till folket: När I fån se en sky uppgå vesterut, straxt sägen I: Regn kommer; och det sker så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Och när I sen sunnanväder blåsa, sägen I: Det blifver varmt; och det sker så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'I skrymtare, himmelens och jordenes skepelse kunnen I bepröfva; hvi pröfven I icke då denna tiden?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Hvi dömen I icke ock utaf eder sjelfva, hvad rätt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'När du nu går med din trätobroder till öfverstan, så vinnlägg dig i vägen, att du blifver honom fri; att han tilläfventyrs icke drager dig fram för domaren, och domaren antvardar dig stockmästaren, och stockmästaren kastar dig i fängelset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Jag säger dig: Du varder icke utkommandes, tilldess du betalat hafver den yttersta skärfven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'På samma tid voro der någre tillstädes, som bådade honom om de Galileer, hvilkas blod Pilatus hade blandat med deras offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Då svarade Jesus, och sade till dem: Menen I att desse Galileer voro syndare för alla Galileer, efter de sådant ledo?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Nej, säger jag eder; utan om I icke bättren eder, skolen I alle sammalunda förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Eller de aderton, som tornet i Siloa föll uppå, och drap dem, menen I att de brottslige voro för alla menniskor, som bo i Jerusalem?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Nej, säger jag eder; utan om I icke bättren eder, skolen I alle sammalunda förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Sade han ock denna liknelsen: En man hade ett fikonaträ planteradt i sin vingård, och han kom och sökte frukt derpå, och fann ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Då sade han till vingårdsmannen: Si, nu i tre år hafver jag kommit, och sökt frukt på detta fikonaträt, och finner ingen; hugg det bort; hvarefter skall det förhindra jordena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Han svarade, och sade till honom: Herre, låt stå det ännu i detta året, så länge jag grafver omkring det och göder det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Om det så kunde bära frukt; hvar ock icke, så hugg det sedan bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Och han lärde om Sabbathen i en Synagogo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Och si, der var en qvinna, som hade haft krankhetenes anda i aderton år; och var krumpen, och förmådde icke upplyfta hufvudet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'När Jesus såg henne, kallade han henne till sig, och sade till henne: Qvinna, var fri af dine krankhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Och han lade händerna på henne: och straxt reste hon sig upp, och prisade Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Då svarade öfversten för Synagogon, och var vred att Jesus helade på Sabbathen, och sade till folket: Sex dagar äro, der I mågen arbeta på; kommer på dem, och låter hela eder; icke på Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Då svarade Herren honom, och sade: Du skrymtare, löser icke hvar och en af eder om Sabbathen sin oxa eller åsna ifrå krubbone, och leder bort att vattna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Måtte man då icke lösa af detta bandet, på Sabbathen, denna Abrahams dotter, hvilken Satan bundit hafver, si, nu i aderton år?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Och då han detta sade, skämde sig alle som honom emotståndit hade, och allt folket gladde sig af de härliga gerningar, som gjordes af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Så sade han då: Hvem är Guds rike likt? Och vid hvad skall jag likna det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Det är likt vid ett senapskorn, som en man tog, och sådde i sin örtagård; och det växte, och blef ett stort trä, och foglarna under himmelen bodde på dess qvistar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Och åter sade han: Vid hvad skall jag likna Guds rike?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Det är likt enom surdeg, hvilken en qvinna tog, och lade in uti tre skäppor mjöl, tilldess det surnade alltsammans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Och han gick igenom städer och byar, och lärde, och tog vägen åt Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Och en sade till honom: Herre, äro de ock få, som varda salige? Då sade han till dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Vinnlägger eder derom, att I kunnen ingå igenom den trånga porten; ty månge, säger jag eder, skola söka derefter, att de må inkomma, och skola dock icke kunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Sedan husbonden hafver uppståndit, och låtit dörren igen; och I begynnen stå ute, och bulta på dörren, sägande: Herre, Herre, låt upp för oss; och han svarar, och säger till eder: Jag vet intet af eder, hvadan I ären;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Då skolen I begynna säga: Vi hafvom ätit och druckit med dig, och du hafver lärt på våra gator.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Och han skall säga: Jag säger eder, jag vet intet af eder, hvadan I ären; går ifrå mig, alle I ogerningsmän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Och der skall vara gråt och tandagnisslan; när I fån se Abraham, Isaac och Jacob, och alla Propheterna, i Guds rike; och eder utdrifvas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Och de skola komma ifrån östan och vestan, och nordan och sunnan, och skola sitta till bords i Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Och si, det äro någre ytterste, som skola varda de främste; och någre främste, som skola varda de ytterste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Samma dagen gingo någre Phariseer fram, och sade till honom: Skynda dig, och gack hädan; ty Herodes vill dräpa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Då sade han till dem: Går, och säger dem räfvenom: Si, jag utdrifver djeflar, och helar i dag, och i morgon; och tredje dagen varder det ändadt med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Dock likväl måste jag ännu vandra i dag, och i morgon, och öfvermorgon; ty det kan icke vara, att en Prophet förgås annorstädes än i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalem, Jerusalem, du som dräper Propheterna, och stenar dem som sändas till dig; huru ofta ville jag församla din barn, likavisst som foglen sitt näste under sina vingar; och I villen icke?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Si, edart hus skall varda eder öde; och säger jag eder, att I skolen icke se mig, tilldess tiden kommer, att I varden sägande: Välsignad är han, som kommer i Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Och det hände sig, att han kom uti ens mans hus, som var en öfverste för de Phariseer, om en Sabbath, till att få sig mat; och de vaktade på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Och si, en vattusigtig menniska var der för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Då svarade Jesus, och sade till de lagkloka och Phariseer: Må man någon hela om Sabbathen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Och de tigde. Men han tog honom till sig, och gjorde honom helbregda; och lät gån.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Och han svarade, sägandes till dem: Hvilkens edars åsne eller oxe faller uti brunnen, och går han icke straxt till att draga honom ut, om Sabbathsdagen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Och de kunde intet svara honom dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Då sade han ock till dem, som budne voro, en liknelse; märkandes, huru de sökte efter att sitta främst, sägandes till dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'När du blifver buden af någrom till bröllop, så sätt dig icke i främsta rummet; att icke tilläfventyrs någor kommer, som buden är af honom, och är ärligare än du;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Och då kommer han, som både dig och honom budit hafver, och säger till dig: Gif denna rum; och då måste du med blygd begynna sitta ned bätter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Utan heldre, när du varder buden, gack, och sätt dig i yttersta rummet; att, då han kommer, som dig budit hafver, må han säga till dig: Min vän, sitt upp bätter; och då sker dig heder för dem, som der med dig till bords sitta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Ty hvar och en, som upphöjer sig, han skall varda förnedrad; och den sig förnedrar, han skall varda upphöjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Sade han ock desslikes till honom, som honom budit hade: När du gör middagsmåltid, eller nattvard, bjud icke dina vänner, eller dina bröder, eller dina fränder, eller dina grannar, som rike äro; att de icke bjuda dig igen, och löna dig dina välgerning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Utan heldre, då du gör gästabåd, kalla de fattiga, sjuka, halta och blinda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Och salig äst du; ty de förmå icke löna dig igen; men dig varder igenlönt i de rättfärdigas uppståndelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Men då en af dem, som vid bordet såto, detta hörde, sade han till honom: Salig är den som äter bröd i Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Då sade han till honom: En man hade tillredt en stor nattvard, och böd många;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Och utsände sin tjenare, den stund nattvarden skulle stå, att han skulle säga dem som budne voro: Kommer; ty all ting äro nu redo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Och de begynte allesammans ursaka sig. Den förste sade till honom: Jag hafver köpt ett jordagods, och jag måste gå ut och bese det; jag beder dig, gör min ursäkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Och den andre sade: Jag hafver köpt fem par oxar, och jag måste gå bort och försöka dem; jag beder dig, gör min ursäkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Och den tredje sade: Jag hafver tagit mig hustru, och derföre kan jag icke komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Och tjenaren kom, och sade sin herra allt detta igen. Då vardt husbonden vred, och sade till sin tjenare: Gack snarliga ut på gator och gränder i staden, och de fattiga, och krymplingar, halta och blinda haf härin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Och tjenaren sade: Herre, jag hafver gjort som du böd, och här är ännu rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Då sade herren till tjenaren: Gack ut på vägar och gårdar, och nödga dem att komma härin, på det att mitt hus måtte varda fullt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Ty jag säger eder, att ingen af de män, som budne voro, skall smaka min nattvard.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Och gick mycket folk med honom; och han vände sig om, och sade till dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Hvilken som kommer till mig, och icke hatar sin fader och moder, och hustru, och barn, och bröder, och systrar, och dertill sitt eget lif, han kan icke vara min Lärjunge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Och hvilken som icke bär sitt kors, och följer mig, han kan icke vara min Lärjunge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Hvilken är den af eder, som vill bygga ett torn, och icke först sitter och öfverlägger bekostningen, om han hafver det han behöfver till att fullborda det med?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Att, då han hafver lagt grundvalen, och icke kan fullborda det, alle de, som få set, icke skola begynna göra spe af honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Och säga: Denne mannen hafver begynt bygga, och förmådde icke fullbordat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Eller hvad Konung vill gifva sig till örligs, och strida emot en annan Konung, sitter han icke först och tänker, om han förmår med tiotusend möta honom, som kommer emot honom med tjugutusend?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Annars, medan hin ännu långt borto är, sänder han bådskap till honom, och beder om frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Sammalunda hvar och en af eder, som icke vedersakar allt det han äger, han kan icke vara min Lärjunge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Saltet är godt; men om saltet mister sin sälto, med hvad skall man då salta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Det är hvarken nyttigt i jordene, eller i dyngone; utan man kastar det bort. Den der öron hafver till att höra, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Och till honom gingo allehanda Publicaner och syndare, att de måtte höra honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Och de Phariseer och Skriftlärde knorrade och sade: Denne undfår syndare, och äter med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Då sade han till dem denna liknelsen, sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Hvilken är den man ibland eder, som hafver hundrade får, och om han tappar bort ett af dem, låter han icke de nio och niotio uti öknene, och går efter det som borto är, tilldess han finner det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Och då han hafver det funnit, lägger han det på sina axlar med glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Och när han kommer hem i sitt hus, kallar han tillhopa sina vänner och grannar, och säger till dem: Glädjens med mig; ty jag hafver funnit mitt får, som borttappadt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Jag säger eder, att sammalunda varder ock glädje i himmelen öfver en syndare den sig bättrar, mer än öfver nio och niotio rättfärdiga, som ingen bättring behöfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Eller hvad qvinna är, som hafver tio penningar, om hon borttappar en af dem, tänder hon icke upp ljus, och sopar huset, och söker granneliga, tilldess hon finner honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Och då hon funnit hafver, kallar hon tillhopa sina vänner och grannqvinnor, och säger: Glädjens med mig; ty jag hafver funnit min penning, som jag tappat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Sammalunda, säger jag eder, varder glädje för Guds Änglom öfver en syndare som sig bättrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Och han sade: En man hade två söner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Och den yngre af dem sade till fadren: Fader, få mig den parten af ägodelarna, som mig tillkommer. Och han bytte ägodelarna dem emellan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Och icke många dagar derefter, då den yngre sonen hade lagt all sin ting tillhopa, for han långt bort i främmande land; och der förfor han sina ägodelar, och lefde öfverflödeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Och sedan han allt förtärt hade, vardt en stor hunger i det landet; och han begynte lida nöd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Och gick bort, och gaf sig till en borgare der i landet; och han sände honom till sin afvelsgård, att han skulle sköta hans svin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Då begärade han uppfylla sin buk med draf, der svinen med föddes; och honom gaf ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Då besinnade han sig sjelf, och sade: Huru månge mins faders legodränger hafva bröd nog; och jag förgås här i hunger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Jag vill stå upp, och gå till min fader, och säga till honom: Fader, jag hafver syndat i himmelen, och för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Jag är icke nu värd kallas din son; gör mig såsom en af dina legodränger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Och så stod han upp, och kom till sin fader. Och då han ännu långt ifrå var, såg honom hans fader, och begynte varkunna sig öfver honom, och lopp emot honom, föll honom om halsen, och kysste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Och sonen sade till honom: Fader, jag hafver syndat i himmelen, och för dig; och är icke värd härefter kallas din son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Då sade fadren till sina tjenare: Bärer fram den yppersta klädningen, och kläder honom deruti; och får honom en ring på hans hand, och skor på hans fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Och hafver hit den gödda kalfven, och slagter honom; vi vilje äta, och göra oss glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Ty denne min son var död, och hafver fått lif igen; han var borttappad, och är funnen igen. Och de begynte göra sig glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Men den äldre hans son var ute på markene; och när han kom, och nalkades husena, hörde han sjungas och dansas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Och kallade en af sina tjenare, och frågade honom, hvad det var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Då sade han till honom: Din broder är kommen; och din fader lät slagta den gödda kalfven, att han hafver honom helbregda igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Då vardt han vred, och ville icke gå in. Då gick hans fader ut, och bad honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Svarade han, och sade till fadren: Si, jag tjenar dig i så mång år, och hafver aldrig gångit af ditt bud; och du gaf mig aldrig ett kid, att jag måtte göra mig glad med mina vänner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Men sedan denne din son kommen är, som sina ägodelar hafver förtärt med skökor, hafver du till honom slagtat den gödda kalfven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Då sade han till honom: Min son, du äst alltid när mig, och allt det mitt är, det är ditt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Man måste nu glädjas och fröjdas; ty denne din broder var död, och fick lif igen; och var borttappad, och är igenfunnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Sade han ock till sina Lärjungar: Det var en riker man, som hade en gårdsfogda; den vardt beryktad för honom, att han förfor hans ägodelar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Då kallade han honom, och sade till honom: Hvi hörer jag sådant af dig? Gör räkenskap af ditt fögderi; ty du måste icke länger vara min fogde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Då sade fogden vid sig sjelf: Hvad skall jag göra? Ty min herre tager ifrå mig fögderiet; grafva orkar jag icke, tigga blyges jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Nu väl, jag vet hvad jag vill göra, att, då jag varder satt af mitt fögderi, måga de anamma mig uti sin hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Då kallade han till sig alla sins herras gäldenärar, och sade till den första: Huru mycket äst du min herra skyldig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Sade han: Hundrade tunnor oljo. Då sade han till honom: Tag ditt bref, och sätt dig snart ned, och skrif femtio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Sedan sade han till den andra: Huru mycket äst du skyldig? Sade han till honom: Hundrade pund hvete. Sade han till honom: Tag ditt bref, och skrif åttatio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Och herren prisade den orätta fogdan, att han visliga gjorde; ty denna verldenes barn äro visare än ljusens barn, uti sitt slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Och jag säger eder: Görer eder vänner af den orätta Mammon, på det att, när I behöfven, skola de anamma eder uti evinnerliga hyddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Den der trogen är i det minsta, han är ock trogen i det mer är; och den i det minsta orätt är, han är ock orätt i det mer är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Ären I nu icke trogne uti den orätta Mammon; ho vill då betro eder om det sannskyldiga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Och om I ären icke trogne uti ens annars; ho vill få eder det edart är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Ingen tjenare kan tjena två herrar; ty antingen skall han hata den ena, och älska den andra; eller ock hålla sig intill den ena, och förakta den andra. I kunnen icke tjena Gudi och Mammon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Allt detta hörde ock de Phariseer, som girige voro, och gjorde spe af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Och han sade till dem: I ären de som gören eder sjelfva rättfärdiga för menniskom; men Gud vet edor hjerta; ty det som för menniskom högt är, der stygges Gud vid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Lagen och Propheterna hafva propheterat intill Johannem; ifrå den tiden varder Guds rike förkunnadt genom Evangelium, och hvar man gör våld på det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Men snarare skola himmel och jord förgås, än en titel af lagen falla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Den der öfvergifver sina hustru, och tager ena andra, han bedrifver hor; och den der tager henne, som af mannen öfvergifven är, han bedrifver hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Det var en riker man, som klädde sig i purpur och kosteligit linkläde, och lefde hvar dag kräseliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Och det var ock en fattig, benämnd Lazarus, den der låg för hans dörr, full med sår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Begärandes släcka sin hunger af de smulor, som föllo af dens rika mansens bord. Dock kommo hundar, och slekte hans sår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Så hände det sig, att den fattige blef död, och vardt förder af Änglarna uti Abrahams sköt. Blef ock den rike död, och vardt begrafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Som han nu i helvetet och i pinone var, lyfte han sin ögon upp, och fick se Abraham långt ifrån, och Lazarum i hans sköt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Ropade han, och sade: Fader Abraham, varkunna dig öfver mig, och sänd Lazarum, att han doppar det yttersta af sitt finger i vatten, och svalar mina tungo; ty jag pinas svårliga i denna låganom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Då sade Abraham: Min son, tänk uppå, att du hade godt medan du lefde, och Lazarus hade deremot ondt; men nu hafver han hugnad, och du pinas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Och öfver allt detta, är emellan oss och eder befäst ett stort svalg, så att de, som vilja fara hädan till eder, de komma dess icke vid; ej heller fara dädan, och hitöfver till oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Då sade han: Så beder jag då dig, fader, att du sänder honom uti mins faders hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Ty jag hafver fem bröder, att han förvarar dem, att de ock icke komma uti detta pinorummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Sade Abraham till honom: De hafva Mosen och Propheterna, höre dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Då sade han: Nej, fader Abraham; men kommer någor till dem af de döda, då bättra de sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Då sade han till honom: Höra de icke Mosen och Propheterna, så tro de icke heller, om någor af de döda uppstode.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Och han sade till sina Lärjungar: Det är omöjeligit, att icke skulle komma förargelser; men ve honom, genom hvilken de komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Bättre vore honom, att en qvarnsten hängdes vid hans hals, och vorde kastad i hafvet, än han skulle förarga en af dessa små.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Vakter eder. Om din broder bryter dig emot, så straffa honom, och om han bättrar sig, så förlåt honom det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Och om han bryter dig emot sju resor om dagen, och han sju resor om dagen vänder sig om igen till dig, sägandes: Mig ångrar det; så förlåt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Och Apostlarna sade till Herran: Föröka oss trona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Då sade Herren: Om I haden trona såsom ett senapskorn, och saden till detta mulbärsträd: Ryck dig upp, och försätt dig i hafvet; då lydde det eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Hvilken af eder hafver en tjenare, som går vid plogen, eller vaktar boskap, då han kommer hem af markene, att han säger till honom: Gack straxt, och sitt till bords;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Utan säger han icke heldre till honom: Red till nattvarden, och uppskörta dig, och tjena mig medan jag äter och dricker; och sedan ät du och drick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Månn han tacka dem samma tjenarenom, att han gjorde som honom budet var? Nej, menar jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Sammalunda ock I, när I hafven gjort allt det som eder budet är, så säger: Vi äre onyttige tjenare; vi hafve gjort det vi vorom pligtige att göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Och det begaf sig, då han gick till Jerusalem, for han midt igenom Samarien och Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Och då han kom uti en by, mötte honom tio spitelske män, de stodo långt ifrå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'Och de upphöjde sina röst, sägande: Jesu Mästar, varkunna dig öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'När han dem såg, sade han till dem: Går, och viser eder Presterna. Och hände sig, vid de gingo, vordo de rene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Men en af dem, då han såg att han var ren vorden, kom han igen, och prisade Gud med höga röst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'Och föll på sitt ansigte för hans fötter, tackandes honom; och han var en Samarit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Då svarade Jesus, och sade: Voro icke tio rene gjorde? Hvar äro då de nio?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Ingen är funnen, som kom igen till att prisa Gud, utan denne främlingen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Och sade till honom: Statt upp, gack, din tro hafver frälst dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Och då han frågad vardt af de Phariseer, när Guds rike komma skulle, svarade han dem, och sade: Guds rike kommer icke med utvärtes åthäfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Ej heller varder man sägande: Si här, eller, si der äret; ty si, Guds rike är invärtes i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Och han sade till Lärjungarna: Den tid skall komma, att I skolen begära se en af menniskones Sons dagar, och I skolen icke få sen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Och de skola säga till eder: Si här, si der; går icke åstad, och följer icke heller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Ty såsom ljungelden ljungar ofvan af himmelen, och lyser öfver allt det under himmelen är; alltså skall ock menniskones Son vara på sin dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Men tillförene måste han mycket lida, och förkastas af detta slägtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Och såsom det skedde uti Noe tid, så skall det ock ske uti menniskones Sons dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'De åto, drucko; män togo hustrur, och qvinnor gåfvos mannom, intill den dagen då Noe gick in i arken; och floden kom, och förgjorde dem alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Sammalunda ock, såsom det skedde uti Loths tid; de åto, drucko, köpte, sålde, planterade, byggde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Men den dagen, då Loth gick ut af Sodoma, regnade eld och svafvel af himmelen, och förgjorde dem alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Efter det sättet varder det ock gåendes på den dagen, när menniskones Son skall uppenbaras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'På den dagen, den som är på taket, och hans boting i huset, han stige icke neder till att taga dem; sammalunda ock, den i markene är, gånge icke tillbaka igen efter det han left hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Kommer ihåg Loths hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Hvilken som far efter att förvara sin själ, han skall mista henne; och den som mister henne, han fordrar henne till lifs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Jag säger eder: I den natten skola två ligga uti ene säng; den ene varder upptagen, och den andre varder qvarlåten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Två skola mala tillhopa; den ene varder upptagen, och den andre varder qvarlåten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Två skola vara i markene; den ene varder upptagen, och den andre varder qvarlåten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Då svarade de, och sade till honom: Hvar då, Herre? Sade han till dem: Der som åtelen är, dit församlas ock örnarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Sade han ock en liknelse till dem derom, att man skall alltid bedja, och icke förtröttas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Sägandes: En domare var uti en stad, den icke fruktade Gud, och ej heller hade försyn för några mennisko;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Så var i samma stad en enka; hon kom till honom, och sade: Hjelp mig ifrå min trätobroder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Och han ville icke till någon tid. Sedan sade han vid sig: Ändock jag icke fruktar Gud, ej heller hafver försyn för någon mennisko;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Dock, fördenskull att denna enkan öfverfaller mig så svåra, måste jag fly henne rätt, att hon icke skall komma på det sista, och ropa på mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Och sade Herren: Hörer här, hvad den orätta domaren säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Skulle ock icke Gud hämnas sina utkorade, som ropa till honom dag och natt; skulle han hafva tålamod dermed?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Jag säger eder, att han skall hämnas dem snarliga. Dock likväl, då menniskones Son kommer, månn han skall finna tro på jordene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Sade han ock till somliga, som tröste på sig sjelfva, att de voro rättfärdige, och försmådde andra, denna liknelsen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Två män gingo upp i templet till att bedja; den ene en Pharisee, och den andre en Publican.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Phariseen stod och bad så vid sig sjelf: Jag tackar dig Gud, att jag är icke såsom andra menniskor, röfvare, orättfärdige, horkarlar, eller ock såsom denne Publicanen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Jag fastar två resor i veckone, och gifver tiond af allt det jag äger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Och Publicanen stod långt ifrån, och ville icke lyfta sin ögon upp till himmelen; utan slog sig för sitt bröst, och sade: Gud, miskunda dig öfver mig syndare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Jag säger eder: Denne gick dädan hem igen rättfärdigad, mer än den andre; ty den sig upphöjer, han varder förnedrad; och den sig förnedrar, han varder upphöjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Så båro de ock barn till honom, att han skulle taga på dem; då hans Lärjungar det sågo, näpste de dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Men Jesus kallade dem till sig, och sade: Låter barnen komma till mig, och förmener dem icke; ty sådana hörer Guds rike till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Sannerliga säger jag eder: Hvilken som icke tager Guds rike som ett barn, han skall icke komma derin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Och frågade honom en öfverste, sägandes: Gode Mästar, hvad skall jag göra, att jag må få evinnerligit lif?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Sade Jesus till honom: Hvi kallar du mig godan? Ingen är god, utan allena Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Budorden vetst du: Du skall icke bedrifva hor; du skall icke dräpa; du skall icke stjäla; du skall icke säga falskt vittnesbörd; du skall ära din fader och dina moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Då sade han: Allt detta hafver jag hållit af min ungdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Då Jesus det hörde, sade han till honom: Än fattas dig ett; sälj bort allt det du hafver, och skift emellan de fattiga, och du skall få en skatt i himmelen; och kom, och följ mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Då han det hörde, vardt han storliga bedröfvad; ty han var ganska rik.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Då Jesus såg honom vara mägta bedröfvad, sade han: O! med huru stor plats komma de i Guds rike, som penningar hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Ty snarare kan en camel gå igenom ett nålsöga, än en riker komma in i Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Då sade de som det hörde: Ho kan då varda salig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Men han sade: Det omöjeligit är för menniskom, det är möjeligit för Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Då sade Petrus: Si, vi hafve all ting öfvergifvit, och följt dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Sade han till dem: Sannerliga säger jag eder; ingen är den som hafver öfvergifvit hus, eller föräldrar, eller bröder, eller hustru, eller barn, för Guds rikes skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'Den icke skall igenfå mycket mer i denna tiden, och i tillkommande verld evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Då tog Jesus till sig de tolf, och sade till dem: Si, vi gåm upp till Jerusalem, och all ting skola fullbordad varda, som skrifven äro af Propheterna om menniskones Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Ty han skall öfverantvardas Hedningom, och begabbas, och försmädas, och bespottas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'Och sedan de hafva hudflängt honom, skola de döda honom; och tredje dagen skall han uppstå igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Men de förstodo der intet af, och talet var dem så fördoldt, att de icke förstodo hvad som sades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Så hände sig, att när han kom in mot Jericho, satt en blinder vid vägen, och tiggde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Och när han hörde folket framgå, frågade han hvad det var?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Då sade de till honom, att Jesus af Nazareth gick der fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Då ropade han, och sade: Jesu, Davids Son, varkunna dig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Men de, som föregingo, näpste honom, att han skulle tiga; men han ropade dessmer: Davids Son, varkunna dig öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Då stadnade Jesus, och böd leda honom till sig. Då han kom fram, frågade han honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Sägandes: Hvad vill du, att jag skall göra dig? Då sade han: Herre, att jag måtte få min syn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Och Jesus sade till honom: Haf din syn; din tro hafver frälst dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Och straxt fick han sin syn igen, och följde honom, prisandes Gud. Och allt folket, som detta sågo, lofvade Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Och han drog in, och gick igenom Jericho.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Och si, der var en man, benämnd Zacheus; han var en öfverste för de Publicaner, och var rik;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Och sökte efter att han skulle få se Jesum, ho han var; men han kom icke dess vid, för folkets skull; ty han var liten till växt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Så lopp han framföre, och steg upp uti ett mulbärträ, på det han skulle få se honom; ty han skulle gå der fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Och när Jesus kom till den platsen, såg han upp, och fick se honom, och sade till honom: Zachee, stig snarliga ned; ty i dag måste jag gästa i ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Han steg snarliga ned, och undfick honom gladeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Och när de det sågo, knorrade de alle, att han ingången var till att gästa när en syndare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Men Zacheus steg fram, och sade till Herran: Si, Herre, hälftena af mina ägodelar gifver jag de fattiga; och om jag hafver någon bedragit, det gifver jag fyradubbelt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Då sade Jesus till honom: I dag är desso huse salighet vederfaren; efter han är ock Abrahams son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Ty menniskones Son är kommen till att uppsöka och frälsa det som förtappadt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'När de nu detta hörde, sade han ändå en liknelse, efter han var hardt när vid Jerusalem, och de mente att Guds rike skulle straxt uppenbaradt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Så sade han då: En ädla man for långt bort i främmande land, till att intaga sig ett rike, och komma igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Då kallade han till sig tio sina tjenare, och fick dem tio pund, och sade till dem: Handler härmed, tilldess jag igen kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Men hans borgare hatade honom, och sände bådskap efter honom, sägande: Vi vilje icke, att denne skall råda öfver oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Och det begaf sig, att han kom igen, och hade fått riket. Då böd han kalla de tjenare till sig, som han hade fått penningarna, att han måtte veta, huru hvar och en af dem handlat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Så kom den förste, och sade: Herre, ditt pund hafver förvärfvat tio pund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Och han sade till honom: Ack! du gode tjenare, uti en liten ting hafver du varit trogen; du skall hafva magt öfver tio städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Och den andre kom, och sade: Herre, ditt pund hafver vunnit fem pund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Och han sade till honom: Var ock du satter öfver fem städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Och den tredje kom, och sade: Herre, se här ditt pund, som jag hade bevarat uti en svetteduk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Jag var rädder för dig; ty du äst en sträng man; du tager det upp, som du icke hafver nederlagt, och uppskär det du icke hafver sått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Sade han till honom: Af din egen mun dömer jag dig, du onde tjenare; visste du att jag är en sträng man, upptager det jag intet nederlade, och uppskär det jag intet sådde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Hvi fick du då icke mina penningar in i vexlobänken; att, när jag komme, måtte jag ju kraft dem igen med ocker?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Och han sade till dem som der stodo: Tager det pundet ifrå honom och får honom, som hafver tio pund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Då sade de till honom: Herre, han hafver tio pund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Ty jag säger eder, att den som hafver, honom skall varda gifvet; och den som icke hafver, honom skall ock varda ifråtaget det han hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Dock de mina ovänner, som icke ville att jag skulle råda öfver dem, leder hit, och dräper dem här för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Och då han detta sagt hade, gick han dädan, och reste upp åt Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Och det begaf sig att, när han kom till Bethphage och Bethanien, vid det berget, som kallas Oljoberget, sände han två sina Lärjungar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Sägandes: Går in i byn, som för eder ligger; när I kommen derin, skolen I finna en åsnafåla bunden, der ännu ingen menniska på suttit hafver; löser honom, och hafver honom hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Och om någor frågar eder, hvi I lösen honom; så säger till honom: Ty Herren behöfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Så gingo de åstad, som sände voro, och funno, som han hade sagt dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Och när de löste fålan, sade hans herrar till dem: Hvi lösen I fålan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Då sade de: Ty Herren behöfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Och de ledde honom till Jesum; lade sin kläder på fålan, och satte Jesum deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Och der han framfor, bredde de sin kläder på vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Och då han när kom, och drog ned för Oljoberget, begynte hele hopen af hans Lärjungar med fröjd och höga röst lofva Gud, öfver alla de krafter som de sett hade,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Sägandes: Välsignad vare han, som kommer, en Konung i Herrans Namn; frid vare i himmelen, och ära i höjden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Och någre ibland folket, som voro af de Phariseer, sade till honom: Mästar, näps dina Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Men han svarade, och sade till dem: Jag säger eder: Om de tigde, skulle stenarna ropa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Och då han kom fram, och fick se staden, gret han öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Och han sade: Om du ock visste, hvad din frid tillhörer, så vorde du det visserliga i denna dinom dag betänkandes; men nu är det fördoldt för din ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Ty den tid skall komma öfver dig, att dine ovänner skola dig belägga, och skansa kringom dig, och tränga dig på alla sidor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'Och de skola nederslå dig till jorden, och din barn som i dig äro; och de skola icke låta igen i dig sten på sten; derföre, att du icke känna kunde den tiden, der du uti sökt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Så gick han in i templet, och begynte utdrifva dem, som derinne sålde och köpte,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Sägandes till dem: Det är skrifvet: Mitt hus är ett bönehus; men I hafven det gjort till en röfvarekulo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Och han lärde hvar dag i templet. Men de öfverste Presterna, och de ypperste ibland folket, sökte efter att de kunde förgöra honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Och de kunde icke finna, hvad de skulle göra; ty allt folket höll sig intill honom, och hörde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Och det begaf sig på en af de dagar, att han lärde folket i templet, och predikade Evangelium; då församlade sig de öfverste Presterna, och de Skriftlärde, med de Äldsta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'Och sade till honom: Säg oss, af hvad magt gör du detta? Eller ho är den som hafver gifvit dig denna magten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Svarade Jesus, och sade till dem: Jag vill ock spörja eder ett ord; svarer I mig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Var Johannis döpelse af himmelen, eller af menniskor?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Då begynte de tänka vid sig, sägande: Sägom vi, af himmelen; då säger han: Hvi trodden I icke honom då?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Men sägom vi, af menniskor då stenar oss allt folket; ty de hålla det ju så före, att Johannes var en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Ty svarade de, att de icke visste, hvadan den var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Då sade Jesus till dem: Icke heller säger jag eder, med hvad magt jag detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Och han begynte säga till folket denna liknelsen: En man planterade en vingård, och fick honom ut vingårdsmannom, och for bort i främmande land i lång tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'När tid var, sände han en tjenare till vingårdsmännerna, att de skulle låta honom få af vingårdsens frukt; men vingårdsmännerna hudflängde honom, och sänden ifrå sig med tomma händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Sedan sände han ock en annan tjenare; den hudflängde de ock, och försmädde honom, och sänden ifrå sig med tomma händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Åter sände han den tredje; den gjorde de ock såran, och drefvo honom ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Då sade vingårdsherren: Hvad skall jag göra? Jag vill sända min älskeliga son; kan hända att, då de se honom, hafva de försyn för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Då vingårdsmännerna fingo se honom, tänkte de vid sig sjelfva, sägande: Denne är arfvingen; kommer, vi vilje slå honom ihjäl, att arfvedelen må blifva vår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Och så drefvo de honom utu vingården, och dråpo honom. Hvad skall nu vingårdsherren göra dem samma?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Han skall komma, och förgöra dessa vingårdsmännerna, och utfå vingården androm. När de detta hörde, sade de: Bort det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Då såg han på dem, och sade: Hvad är då det som skrifvet står: Den stenen, som byggningsmännerna bortkastade, han är vorden en hörnsten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Hvilken som faller uppå den stenen, han varder krossad; men den han uppå faller, honom slår han all sönder i stycken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Och öfverste Presterna, med de Skriftlärda, sökte efter att de kunde få taga fatt på honom i samma stunden; men de räddes för folket; ty de förstodo, att han hade sagt denna liknelsen emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Och de aktade på honom, och sände ut väktare, som låtos vara rättfärdige; på det de skulle taga honom vid orden, och öfverantvarda honom herrskapet, och i landsherrans våld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Och de frågade honom, sägande: Mästar, vi vete att du säger och lärer det rätt är, och ser icke till personen, utan lärer Guds väg rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Är det rätt, att vi gifve Kejsaren skatt, eller ej?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Då han förmärkte deras illfundighet, sade han till dem: Hvi fresten I mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Låter mig få se penningen; hvars beläte och öfverskrift hafver han? Svarade de, och sade: Kejsarens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Sade han till dem: Så gifver nu Kejsarenom det Kejsarenom tillhörer, och Gudi det Gudi tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Och de kunde icke straffa hans tal, för folket; utan förundrade sig på hans svar, och tigde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Då gingo någre fram till honom af de Sadduceer, hvilke der neka uppståndelsen, och frågade honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Sägande: Mästar, Moses hafver skrifvit oss, att om någors mans broder blifver död, den hustru hafver, och dör barnlös, att hans broder skall taga hans hustru, och uppväcka sinom broder säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Så voro nu sju bröder; och den förste tog sig hustru, och blef död barnlös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Och den andre tog henne, och blef ock desslikes död barnlös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Den tredje tog henne; sammalunda ock alle sju, och läto inga barn efter sig, och blefvo döde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Sist, efter dem alla, blef ock qvinnan död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Uti uppståndelsen, hvilkensderas hustru skall hon vara, efter det sju hade haft henne till hustru?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Då svarade Jesus, och sade till dem: Denna verldenes barn taga sig hustrur och gifvas mannom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Men de som varda värdige till den verldena, och till uppståndelsen ifrå de döda, de hvarken taga hustrur, eller gifvas manne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Och ej heller kunna de mera dö; ty de varda like med Änglarna, och äro Guds barn, medan de äro uppståndelsens barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Men att de döde uppstå, bevisade Moses vid buskan, då han kallade Herran Abrahams Gud, och Isaacs Gud, och Jacobs Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Gud är icke de dödas, utan de lefvandes Gud; ty honom lefva alle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Då svarade någre af de Skriftlärda, sägande: Mästar, du sade rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Och de djerfdes icke yttermera något fråga honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Men han sade till dem: Huru säga de Christum vara Davids Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Och sjelfver David säger i Psalmboken: Herren sade till min Herra: Sätt dig på mina högra hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Tilldess jag nederlägger dina ovänner dig till en fotapall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Så kallar nu David honom Herra; huru är han då hans Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Då sade han till sina Lärjungar, uti allt folkens åhöro:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Tager eder vara för de Skriftlärda, som vilja gå uti sid kläder, och vilja gerna varda helsade på torgen, och sitta främst i Synagogorna, och sitta främst i gästabåden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'De uppfräta enkors hus, förebärande långa böner; de skola få dess större fördömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Och han såg till, aktandes på huru de rike lade sina gåfvor uti offerkistona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Så fick han ock se ena fattiga enko, som lade der två skärfvar in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Och han sade: Sannerliga säger jag eder: Denna fattiga enkan lade mer in, än alle de andre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Ty de hafva alle inlagt, till Guds offer, af det dem till öfverlopps är; men hon hafver, af sin fattigdom, inlagt allt det hon ägde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Och då somlige sade om templet, att det var prydt med härliga stenar och klenodier, sade han:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'De dagar varda kommande, att utaf allt, det I sen, skall icke låtas sten uppå sten, den icke skall afbruten varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Då frågade de honom, och sade: Mästar, när skall detta ske? Och hvad tecken är, när detta ske skall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Sade han: Ser till, att I icke varden förförde; ty månge skola komma under mitt Namn, och säga: Jag äret; och tiden instundar. Följer dem icke efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Men när I hören örlig och uppror, varer icke förfärade; ty sådant måste först ske, men det är icke straxt änden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Och han sade till dem: Folk skall resa sig upp emot folk, och rike emot rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'Och stor jordbäfning skall varda mångastäds, och hunger, och pestilentier; och förskräckelse, och stor tecken skola ske utaf himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Men för allt detta skola de taga fatt på eder, och förfölja eder och öfverantvarda eder in på sin Råd, och i häktelse; dragande eder för Konungar och Förstar, för mitt Namns skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Och det skall eder vederfaras till ett vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Så håller det fast uti edor hjerta, att I ingen omsorg hafven, huru I skolen försvara eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Ty jag skall gifva eder mun och visdom, der alle de, som sätta sig emot eder, icke skola kunna emotsäga, ej heller emotstå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'I skolen ock öfverantvardas af föräldrar, och af bröder, fränder och vänner; och de skola döda somliga af eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Och I skolen varda hatade af allom, för mitt Namns skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Och ett hår af edart hufvud skall icke förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'I skolen behålla edra själar genom edart tålamod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'När I nu sen, att Jerusalem varder belagdt med en här, då skolen I veta, att dess förödelse är för handen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'De då äro i Judeen, de fly upp åt bergen; och de der midt inne äro, de gånge ut; och de som ute i landet äro, de gånge icke derin;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Ty att då äro hämndadagarne, att fullbordas skall allt det som skrifvet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Men ve dem som hafvande äro, och dem som dia gifva i de dagar; ty stor plåga varder på jordene, och vrede öfver detta folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Och de skola falla för svärdsegg, och fångne bortförde varda till allahanda folk; och Jerusalem skall förtrampadt varda af Hedningom, tilldess Hedningarnes tid fullkomnad varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Och skola ske tecken i solen, och i månan, och i stjernorna; och på jordene varder folkena ångest, och de skola förtvifla. Och hafvet och vågen skola mycket bullra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Och menniskorna borttorkas, för räddhågas skull, deraf att de förbida det som hela verldena öfvergå skall; ty himmelens krafter skola bäfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Och då skola de få se menniskones Son komma i skyn, med magt och stora härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Men då detta begynner ske, ser upp, och lyfter edor hufvud upp; ty då nalkas edor förlossning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Och han sade dem en liknelse: Ser på fikonaträt och all trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'När de nu knoppas, kunnen I då se och veta af eder sjelf, att sommaren är när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Alltså ock I, när I sen detta ske, skolen I veta, att Guds rike är när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Sannerliga säger jag eder: Detta slägtet skall icke förgås, förr än det allt skedt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Himmel och jord skola förgås; men min ord skola icke förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Men vakter eder, att edor hjerta icke förtungad varda med svalg och dryckenskap, och med detta lefvernes omsorg, så att den dagen kommer eder för hastigt uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Ty han varder kommandes, såsom en snara, öfver alla som bo på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Så vaker nu alltid, och beder, att I mågen undfly allt detta som komma skall, och stå för menniskones Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Och han lärde om dagen i templet; men om natten gick han ut, och vistades på Oljoberget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Och allt folket var bittida uppe till honom i templet, till att höra honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Då tillstundade Sötbrödshögtiden, den Påska kallas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Och de öfverste Presterna och Skriftlärde sökte efter, huru de kunde dräpa honom; men de fruktade för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Och gick Satanas in uti Judas, som kallades Ischarioth, och var en af de tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Han gick bort, och talade med de öfversta Presterna och föreståndarena, huruledes han skulle fly honom dem i händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Och de gladdes, och voro öfverens med honom, att de skulle gifva honom penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Och han lofvade dem det, och sökte efter läglighet, att han måtte öfverantvarda honom dem utan buller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Så kom då Sötbrödsdagen, på hvilkom man måste offra Påskalambet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Då sände han Petrum, och Johannem, sägandes: Går, och bereder oss Påskalambet, att vi det äte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Då sade de till honom: Hvar vill du, att vi skole bereda det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Sade han till dem: Si, när I kommen in i staden, varder eder mötandes en man, som bär ena vattukruko; följer honom i huset, der han ingår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Och säger husbondanom: Mästaren låter säga dig: Hvar är herberget, der jag må äta Påskalambet med mina Lärjungar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Och han skall visa eder en storan sal bereddan; reder der till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'De gingo åstad, och funno som han dem sagt hade; och redde till Påskalambet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Och då tid var, satte han sig ned, och de tolf Apostlar med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Och han sade till dem: Jag hafver, med mycken åstundan, begärat äta detta Påskalambet med eder, förr än jag lider.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Ty jag säger eder, att jag härefter icke skall äta deraf, tilldess det fullkomnadt varder i Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Och han tog kalken, tackade, och sade: Tager honom, och skifter eder emellan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Ty jag säger eder, att jag icke skall dricka det af vinträ kommet är, tilldess Guds rike kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Och han tog brödet; tackade, och bröt, och gaf dem, sägandes: Detta är min lekamen, som för eder gifven varder; det görer till min åminnelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Sammalunda ock kalken, efter Nattvarden, sägandes: Detta är kalken, det nya Testamentet i mitt blod, som för eder utgjutet varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Dock si, mins förrädares hand är med mig på bordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Och menniskones Son varder gångandes, efter som det beslutet är; dock ve den mennisko, af hvilko han varder förrådder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Och de begynte fråga emellan sig, hvilken den var af dem som det göra skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Så vardt ock en träta emellan dem, hvilkendera skulle synas vara ypperst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Då sade han till dem: Verldslige Konungar regera; och de, som magtena hafva, kallas nådige herrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Men I icke så; utan den som störst är ibland eder, han skall vara som den yngste, och den der ypperst är, han vare såsom en tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Ty hvilkendera är större, den som sitter, eller den som tjenar? Är icke han som sitter? Men jag är midt ibland eder, såsom den som tjenar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Men I ären de samme, som med mig blifvit hafven uti mina frestelser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Och jag vill beställa eder riket, såsom min Fader hafver det beställt mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Att I skolen äta och dricka öfver mitt bord, i mitt rike; och skolen sitta på stolar, och döma tolf Israels slägter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Och Herren sade: Simon, Simon, si, Satanas hafver begärat eder, att han skulle sålla eder såsom hvete;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Men, jag hafver bedit för dig, att din tro skall icke omintet varda; och när du nu omvänder äst, så styrk dina bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Då sade han till honom: Herre, jag är redebogen gå med dig, både i häktelse och i döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Då sade han: Jag säger dig, Petre, i dag skall icke hanen gala, förr än du tre resor nekar att känna mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Och han sade till dem: När jag sände eder utan säck, utan skräppo, och utan skor, hafver eder något fattats? Då sade de: Intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Då sade han till dem: Men nu, ho som säck hafver, han tage honom, sammalunda ock skräppo; och den der icke hafver, han sälje sin kjortel, och köpe svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Ty jag säger eder, att det ännu måste fullbordas på mig, som skrifvet är: Han är räknad ibland ogerningsmän; ty hvad som skrifvet är om mig, det hafver en ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Då sade de: Herre, si, här äro tu svärd. Då sade han till dem: Det är nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Och han gick ut, som hans seder var, till Oljoberget; och hans Lärjungar följde honom till det rummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Och då han kom dit, sade han till dem: Beder, att I icke kommen uti frestelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Och han gick ifrå dem vid pass ett stenkast, och föll ned på sin knä, och bad,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Sägandes: Fader, är så din vilje, tag denna drycken ifrå mig; dock likväl, ske icke min vilje, utan din.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Och syntes honom en Ängel af himmelen, och styrkte honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Och han vardt betagen af en mägta stor ångest, och bad länge; och hans svett var såsom blodsdroppar, löpande ned på jorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Och då han uppstod af bönene, och kom till sina Lärjungar, fann han dem sofvande af bedröfvelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Och sade till dem: Hvi sofven I? Står upp, och beder, att I icke kommen uti frestelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Vid han ännu talade, si, en hop med folk, och en utaf de tolf, som het Judas, gick för dem, och trädde fram till Jesum, till att kyssa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Men Jesus sade till honom: Juda, förråder du menniskones Son med kyssande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Då sågo de som när voro, hvad på färde var, och sade till honom: Herre, skole vi taga till svärds?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Och en af dem slog öfversta Prestens tjenare, och högg af hans högra öra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Då svarade Jesus, och sade: Låter kommat härtill; och så tog han på hans öra, och helade honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Och Jesus sade till de öfversta Presterna, och föreståndarena i templet, och till de äldsta, som till honom komne voro: Såsom till en röfvare ären I utgångne, med svärd och med stafrar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Ändock jag hafver dagliga varit med eder i templet, och I kommen edra händer intet vid mig; men detta är edar stund, och mörksens magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Så grepo de honom, och ledden, och haden in i öfversta Prestens hus. Men Petrus följde långt efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Då gjorde de en eld midt i palatset, och såto dervid; och Petrus satte sig ibland dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Då en tjensteqvinna fick se honom sittandes vid ljuset, såg hon på honom, och sade: Denne var ock med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Då nekade han honom, och sade: Qvinna, jag känner honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Och litet efter såg honom en annar, och sade: Du äst ock af dem. Men Petrus sade: Menniska, jag är det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Och litet derefter, vid en timma, kom en annar, och sannade det samma, sägandes: Sannerliga var han ock med honom; ty han är ock en Galileisk man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Och Petrus sade: Menniska, jag vet icke hvad du säger. Och i det samma, vid han ännu talade, gol hanen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Och Herren vände sig om, och såg på Petrum; och då begynte Petrus tänka på Herrans ord, huru han honom sagt hade: Förr än hanen hafver galit, skall du tre resor neka mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Och Petrus gick ut, och gret bitterliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Och de män, som höllo Jesum, begabbade honom, och slogo honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Bundo för hans ögon, slogo hans ansigte, och frågade honom, sägande: Spå, ho är den som dig slog?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Och mycken annor förhädelse sade de till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Och som det dagades, församlade sig de äldste i folket, och de öfverste Presterna, och de Skriftlärde, och hade honom in för sitt Råd,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Sägande: Äst du Christus, säg det oss? Och han sade till dem: Om jag eder det säger, så tron I det intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'Frågar jag ock, så svaren I intet; ej heller släppen I mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Härefter skall menniskones Son sitta på Guds krafts högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Då sade de alle: Så äst du ju Guds Son? Sade han: I sägen att jag så är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Då sade de: Hvarefter begärom vi ännu vittnesbörd? Vi hafve sjelfve hört det af hans mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Då stod upp hele hopen af dem, och ledde honom bort till Pilatum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Och begynte till att klaga på honom, sägande: Denna hafve vi beslagit dermed, att han förvänder folket, och förbjuder gifva Kejsarenom skatt, och säger sig vara Christus en Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Och Pilatus frågade honom, sägandes: Äst du Judarnas Konung? Då svarade han honom, och sade: Du säger det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Då sade Pilatus till öfversta Presterna, och till folket: Jag finner intet brott med denna mannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Men de höllo sitt tal fram, sägande: Han gör uppror ibland folket, lärandes öfver allt Judiska landet, begynnandes i Galileen, och sedan allt hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Då Pilatus hörde nämnas Galileen, frågade han, om han var en Galileisk man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Och då han förnam, att han var under Herodis välde, försände han honom till Herodes; ty han var ock i Jerusalem på den tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Då Herodes fick se Jesum, vardt han ganska glad; ty han hade i lång tid haft åstundan till att se honom; ty han hade mycket hört om honom, och hoppades få se något tecken göras af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Och han frågade honom om mång stycker; men han svarade honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Stodo ock öfverste Presterna, och de Skriftlärde, och klagade svårliga på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Men Herodes med sitt folk föraktade honom, och begabbade honom, och klädde honom uti ett hvitt kläde, och sände honom igen till Pilatum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Och Pilatus och Herodes vordo vänner emellan sig på samma dag; ty emellan dem hade tillförene varit ovänskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Då kallade Pilatus tillhopa de öfversta Presterna, och föreståndarena, och folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Och sade till dem: I hafven fått mig denna mannen, såsom den der hafver förvändt folket; och si, jag hafver förhört honom i edor närvaro, och finner dock ingen af de ogerningar med denna mannen, der I anklagen honom före;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Och ej heller Herodes; ty jag försände eder till honom; och si, man kunde intet komma på honom, det döden värdt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Derföre vill jag näpsan och släppan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Ty han skulle om högtidena gifva dem en lös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Då ropade hele hopen, och sade: Tag denna af vägen, och gif oss Barabbam lös;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Den der låg i fängelset, för ett upplopps skull, som i staden skedt var, och för ett mandråp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Åter talade Pilatus till dem, och ville gifva Jesum lös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Då ropade de, och sade: Korsfäst, korsfäst honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Då sade han tredje resona till dem: Hvad hafver han då illa gjort? Jag finner ingen dödssak med honom; derföre vill jag näpsan, och gifvan lös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Men de lade åt med stort rop, och begärade att han skulle korsfästas; och deras och de öfversta Presternas rop vardt ju mer och mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Då dömde Pilatus, att så ske skulle, som de begärade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Och gaf dem lös den i fängelset satt var för upploppets och dråpets skull, den de begärat hade; men Jesum öfverantvardade han deras vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Och då de ledde honom ut, fingo de en fatt, som het Simon af Cyrene, den der kom af markene; honom lade de korset uppå, att han skulle bära det efter Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Men honom följde en stor hop folk, och qvinnor, de der greto och ömkade sig öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Då vände sig Jesus om till dem, och sade: I Jerusalems döttrar, gråter icke öfver mig; utan gråter öfver eder sjelfva, och öfver edor barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Ty si, de dagar varda kommande, i hvilkom de skola säga: Saliga äro de ofruktsamma, och de qveder som intet födt hafva, och de spenar som ingom hade dia gifvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Då skola de begynna säga till bergen: Faller öfver oss; och till högarna: Skyler oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Ty är detta skedt på det färska trät, hvad skall då ske på det torra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Leddes der ock ut två andre ogerningsmän med honom, till att aflifvas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Och då de kommo till det rummet, som kallas hufvudskallaplatsen, der korsfäste de honom, och de ogerningsmän med honom; den ena på den högra sidon, den andra på den venstra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Och sade Jesus: Fader, förlåt dem det; ty de veta icke hvad de göra. Och de bytte hans kläder, kastandes lott på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Och folket stod och såg uppå; och de öfverste, samt med dem, begabbade honom, sägande: Androm hafver han hulpit, hjelpe sig nu sjelfvom, om han är Christus, den Guds utkorade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Begabbade honom ock krigsknektarna, och gingo till, och räckte ättiko till honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'Sägande: Äst du Judarnas Konung, så hjelp dig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Var ock en öfverskrift skrifven öfver honom, med Grekiska, Latinska och Ebreiska bokstäfver: Denne är Judarnas Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Men en af de ogerningsmän, som upphängde voro, hädde honom, och sade: Äst du Christus, så hjelp dig sjelf och oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Då svarade den andre, straffade honom, och sade: Fruktar du icke heller Gud, du som äst i samma fördömelsen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Och är det väl rätt med oss; ty vi lide det våra gerningar värda äro; men denne hafver intet ondt gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Och sade han till Jesum: Herre, tänk på mig, då du kommer i ditt rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Och sade Jesus till honom: Sannerliga säger jag dig, i dag skall du vara med mig i paradis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Och var detta vid sjette timman; och ett mörker vardt öfver hela landet, allt intill nionde timman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Och solen miste sitt sken; och förlåten i templet remnade midt i tu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Och Jesus ropade med höga röst, och sade: Fader, jag befaller min anda i dina händer; och då han hade det sagt, gaf han upp andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Då höfvitsmannen såg hvad der skedde, prisade han Gud, och sade: Sannerliga var denne en rättfärdig man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Och allt folket, som dit gånget var att se härpå, då de sett hade hvad der skedde, slogo de sig för sin bröst, och gingo hem igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Men alle hans kände vänner, och qvinnor, som honom följt hade af Galileen, stodo långt ifrån, och sågo derpå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Och si, en man, benämnd Joseph, en rådherre, den var en god och rättfärdig man;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'Och hade icke samtyckt deras råd och gerning; och han var bördig af den Judarnas stad Arimathia; den der ock åstundade efter Guds rike;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Han gick till Pilatum, och beddes Jesu lekamen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Och tog honom ned, svepte honom uti ett linkläde, och laden ned i ena graf, som uthuggen var uti sten, der än då ingen hade uti lagd varit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Och det var tillredelsedagen, och Sabbathen begynte gå uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Och följde der några qvinnor efter, som med honom komna voro af Galileen och besågo grafvena, och huruledes hans lekamen lagd var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Och gingo sedan tillbaka igen, och tillredde välluktandes krydder och smörjelse; men om Sabbathen voro de stilla, som budet var i lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'På den ena Sabbathen, ganska bittida om morgonen, kommo de till grafvena, bärande de välluktande krydder, som de tillredt hade; och några med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Så funno de stenen afvältad ifrå grafvene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'Och gingo in, och funno intet Herrans Jesu lekamen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Och det begaf sig att, då de derom bekymrade voro, si, så stodo när dem två män i skinande kläder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Då vordo de förfärade, och slogo sin ansigte neder åt jordene. Då sade de till dem: Hvi söken I den lefvande ibland de döda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Han är icke här, han är uppstånden; kommer ihåg, huru han sade eder, då han ännu var i Galileen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Sägandes: Menniskones Son måste öfverantvardas i syndiga menniskors händer, och korsfästas; och uppstå på tredje dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Och så begynte de komma ihåg hans ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Och gingo tillbaka ifrå grafvene, och bådade detta allt dem ellofva, och allom dem androm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Och det var Maria Magdalena, och Johanna, och Maria Jacobi, och andra som med dem voro, de detta sade till Apostlarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Och deras ord syntes för dem såsom galenskap; och de trodde dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Men Petrus stod upp, och lopp till grafvena; och då han lutade sig derin, fick han se linkläden liggande allena; och gick sina färde, förundrandes vid sig sjelf hvad der skedt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Och si, två af dem gingo på samma dagen till en by, som låg vid sextio stadier vägs ifrå Jerusalem, benämnd Emaus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Och de talade hvar med annan, om allt det som skedt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Och hände sig, då de talades vid, och befrågade hvarannan, nalkades ock Jesus, och gick med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Men deras ögon voro förhållen, att de icke kände honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Då sade han till dem: Hvad är det för tal, som I hafven eder emellan, vid I gån, och ären bedröfvade?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Då svarade endera, som het Cleophas, och sade till honom: Äst du allena ibland främmande män i Jerusalem, som icke vet hvad der skedt är i dessa dagar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Sade han till dem: Hvad? Sade de till honom: Om Jesu Nazareno, som var en Prophet, mägtig både i gerningar och ord, för Gudi, och allo folkena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'Och huruledes de öfverste Presterna, och våre förmän, öfverantvardade honom i dödsens fördömelse, och korsfäste honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Men vi hoppades, att han skulle vara den som förlossa skulle Israel; och öfver allt detta är nu tredje dagen, sedan det skedde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Och några qvinnor af våra hafva förskräckt oss, de der bittida om morgonen hade kommit till grafvena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'Och då de icke funno hans lekamen, kommo de, och sade, att de ock Änglasyn sett hade, hvilke sagt hade att han lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Och någre af dem, som med oss voro, gingo bort till grafven, och funno såsom qvinnorna sagt hade; men honom funno de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Då sade han till dem: O! I galne, och senhjertade till att tro, uti allt det som Propheterna sagt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Skulle icke Christus sådant lida, och sedan ingå uti sin härlighet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Och han begynte på Mose, och alla Propheterna, och gjorde uttydelse för dem i alla Skrifter, som voro om honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Och de begynte nalkas intill byn, dit de ville; och han låts som han ville gå längre fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Och de nödgade honom, sägande: Blif när oss; ty det lider åt aftonen, och dagen är förliden. Och så gick han in, till att blifva när dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Och det begaf sig, då han satt till bords med dem, tog han brödet; tackade, bröt det, och fick dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Och deras ögon öppnades, att de kände honom; och så försvann han utu deras åsyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Och de sade emellan sig: Var icke vårt hjerta brinnande i oss, då han talade med oss i vägen, och uttydde oss Skrifterna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Och i samma stundene stodo de upp, och gingo till Jerusalem igen, och funno församlade de ellofva, och de som med dem voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'De der sade: Herren är sannerliga uppstånden, och är synter af Simone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Och de förtäljde hvad skedt var i vägen, och huru han vardt känd af dem, i det han bröt brödet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Som de nu härom talade, stod Jesus sjelf midt ibland dem, och sade till dem: Frid vare eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Då vordo de förfärade, och fruktade, menandes att de sågo en anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Då sade han till dem: Hvi ären I förfärade? Och hvi uppstiga sådana tankar uti edor hjerta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Ser mina händer, och mina fötter, att det är jag sjelf: Tager på mig, och skåder; ty anden hafver icke kött och ben, såsom I sen mig hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Och då han hade det sagt, viste han dem händer och fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Och som de ännu icke trodde, för glädjes skull, utan förundrade sig, sade han till dem: Hafven I här något att äta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Då fingo de honom fram ett stycke stekt fisk, och något af en hannogskako.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Och han tog det, och åt deraf i deras åsyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Och han sade till dem: Detta äro de ord, som jag sade till eder, då jag ännu var med eder, att allt måste fullbordas, som skrifvet är i Mose lag, och i Propheterna, och i Psalmerna, om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Då öppnade han dem deras sinne, att de förstodo Skrifterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Och sade till dem: Så är det skrifvet, och så måste Christus lida, och tredje dagen uppstå ifrå de döda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'Och predikas i hans Namn bättring och syndernas förlåtelse ibland all folk, begynnande på Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Och I ären vittne till allt detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Och si, jag vill sända öfver eder mins Faders löfte; men I skolen blifva i staden Jerusalem, tilldess I varden beklädde med kraft af höjdene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Och han hade dem ut till Bethanien, och upplyfte sina händer, och välsignade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Och skedde, då han dem välsignat hade, skiljdes han ifrå dem, och uppfor i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Och de tillbådo honom; och gingo sedan in i Jerusalem igen, med stora glädje;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Och voro alltid i templet, prisade och lofvade Gud. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'I Begynnelsen var Ordet, och Ordet var när Gudi; och Gud var Ordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Det samma var i begynnelsen när Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Genom det äro all ting gjord; och thy förutan är intet gjordt, det gjordt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'I thy var lifvet; och lifvet var menniskornas ljus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Och ljuset lyser i mörkret; och mörkret hafver det icke begripit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'En man var sänd af Gudi, som het Johannes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Han kom till vittnesbörd, på det han skulle vittna om Ljuset, att alle skulle tro genom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Icke var han Ljuset; men (han var sänd) till att vittna om Ljuset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Det var det sanna Ljuset, hvilket upplyser alla menniskor, som komma i verlden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'I verldene var det, och igenom det är verlden gjord; och verlden kände det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Han kom till sitt eget, och hans egne anammade honom icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Men allom dem, som honom anammade, gaf han magt att blifva Guds barn, dem som tro på hans Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Hvilke icke af blod, icke heller af köttslig vilja, icke heller af någors mans vilja, utan af Gudi födde äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Och Ordet vardt kött, och bodde ibland oss; och vi sågom hans härlighet, såsom enda Sonsens härlighet af Fadrenom, full med nåd och sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Johannes vittnar om honom, ropar, och säger: Denne varet, om hvilken jag sagt hafver: Efter mig skall komma, den för mig varit hafver; ty han var förr än jag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Och af hans fullhet hafve vi alle fått, och nåd för nåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Ty genom Mosen är lagen gifven; nåd och sanning är kommen genom Jesum Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Ingen hafver någon tid sett Gud; ende Sonen, som är i Fadrens sköt, han hafver det kungjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Och detta är Johannis vittnesbörd, då Judarna sände Prester och Leviter af Jerusalem, att de skulle fråga honom: Ho äst du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Och han bekände, och försakade icke; och bekände han: Icke är jag Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Då frågade de honom: Hvad då; äst du Elias? Han sade: Jag är det icke. Äst du en Prophet? Och han svarade: Nej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Då sade de till honom: Ho äst du, att vi måge gifva dem svar, som oss sändt hafva? Hvad säger du om dig sjelf?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Sade han: Jag är ens ropandes röst i öknene: Rödjer Herrans väg, som Esaias Propheten sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Och de, som sände voro, voro af de Phariseer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Och de frågade honom, och sade till honom: Hvi döper du då, medan du äst icke Christus, icke heller Elias, icke heller en Prophet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Svarade dem Johannes, och sade: Jag döper med vatten; men midt ibland eder står den I icke kännen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Han är den som efter mig komma skall, hvilken för mig varit hafver; hvilkens skotväng jag icke värdig är upplösa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Detta skedde i Bethabara, på hinsidon Jordan, der Johannes döpte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Dagen derefter såg Johannes Jesum komma till sig, och sade: Si, Guds Lamb, som borttager verldenes synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Denne äret, om hvilken jag sagt hafver: Efter mig skall komma en man, den för mig varit hafver; ty han var förr än jag:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Och jag kände honom icke; men på det han skulle varda uppenbar i Israel, fördenskull är jag kommen, till att döpa med vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Och Johannes vittnade, och sade: Jag såg Andan nederkomma i dufvoliknelse af himmelen, och blef på honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Och jag kände honom icke; men den som mig sände, till att döpa med vatten, han sade till mig: Öfver hvilken du far se Andan nederkomma, och blifva på honom, han är den som döper med den Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Och jag såg det, och vittnade att han är Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Dagen derefter stod åter Johannes, och två af hans lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Och som han fick se Jesum gå, sade han: Si, Guds Lamb.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Och de två hans lärjungar hörde honom tala, och följde Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Då vände Jesus sig om, och såg dem följa sig, och sade till dem: Hvad söken I? Då sade de till honom: Rabbi (det betyder Mästar), hvar vistas du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Då sade han till dem: Kommer, och ser. De kommo, och sågo hvar han vistades, och blefvo den dagen när honom; och det var vid tionde timman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Och var Andreas, Simonis Petri broder, en af de två, som hade hört af Johanne; och följde Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Han fann först sin broder Simon, och sade till honom: Vi hafve funnit Messiam, det betyder den Smorda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Och han hade honom till Jesum. Då Jesus fick se honom, sade han: Du äst Simon, Jona son; du skall heta Cephas, det betyder hälleberg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Dagen derefter ville Jesus gå ut i Galileen; och fann Philippum, och sade till honom: Följ mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Och var Philippus af Bethsaida, Andree och Petri stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippus fann Nathanael, och sade till honom: Den som Mose hafver skrifvit om i lagen, och Propheterna, hafve vi funnit, Jesum, Josephs son af Nazareth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Och Nathanael sade till honom: Kan något godt komma af Nazareth? Philippus sade till honom: Kom, och se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jesus såg Nathanael komma till sig, och sade om honom: Si, en rätt Israelit, i hvilkom intet svek är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Då sade Nathanael till honom: Hvaraf känner du mig? Jesus svarade, och sade till honom: Förr än Philippus kallade dig, då du vast under fikonaträt, såg jag dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanael svarade, och sade till honom: Rabbi, du äst Guds Son: Du äst Israels Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jesus svarade, och sade till honom: Efter det jag sade dig, att jag såg dig under fikonaträt, tror du; större ting, än desse äro, skall du få se;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Och sade till honom: Sannerliga, sannerliga säger jag eder: Härefter skolen I få se himmelen öppen, och Guds Änglar fara upp och neder öfver menniskones Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Och på tredje dagen vardt ett bröllop i Cana i Galileen; och Jesu moder var der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Vardt ock desslikes Jesus buden, och hans Lärjungar, till bröllopet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Och då vinet begynte fattas, sade Jesu moder till honom: De hafva intet vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Då sade Jesus till henne: Qvinna, hvad hafver jag med dig? Min tid är icke ännu kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Då sade hans moder till tjenarena: Hvad han säger eder, det görer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Så voro der sex stenkrukor, som satta voro efter sättet om Judarnas rening, hållandes hvardera tu eller tre mått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Då sade Jesus till dem: Fyller upp krukorna med vatten; och de fyllde dem öfverfulla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Och han sade till dem: Låter nu uti, och bärer till kökemästaren; och de båro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'När då kökemästaren smakade vinet, som vatten varit hade, och icke visste hvadan det kommet var; men tjenarena, som vattnet öst hade, visste det, kallade han brudgummen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'Och sade till honom: Hvar man sätter först fram det goda vinet, och när de äro vordne druckne, då det som sämre är. Du hafver gömt det goda vinet allt härtill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Detta var det första tecken, som Jesus gjorde i Cana i Galileen, och uppenbarade sina härlighet; och hans Lärjungar trodde på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Derefter for han ned till Capernaum, han och hans moder, och hans bröder, och hans Lärjungar; och blefvo der i få dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Och var Judarnas Påska hardt när; och Jesus for upp till Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Och fann i templet dem som sålde fä, och får, och dufvor, och vexlare sittande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Då gjorde han ena gissel af tåg, och dref dem alla ut af templet, med får och fä, och bortspillde vexlarenas penningar, och störte borden omkull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Och sade till dem som dufvor sålde: Hafver detta bort hädan, och görer icke af mins Faders hus ett marknadshus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Då kommo hans Lärjungar ihåg det som skrifvet är: Dins hus nitälskan hafver frätit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Då svarade Judarna, och sade till honom: Hvad tecken låter du oss se, att du skall detta göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Svarade Jesus, och sade till dem: Slår detta templet neder, och i tre dagar vill jag det upprätta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Då sade Judarna: I sex och fyratio år är detta templet uppbygdt, och du vill det upprätta i tre dagar!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Men han sade om sins kropps tempel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Och när han var uppstånden ifrå de döda, kommo hans Lärjungar ihåg, att han hade det sagt dem; och trodde Skriftene, och det tal, som Jesus sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Då han nu var i Jerusalem, om Påskana på högtidsdagen, trodde månge på hans Namn, då de sågo hans tecken, som han gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Men Jesus betrodde icke sig sjelfvan dem; ty han kände alla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'Och behöfde icke, att någor skulle vittna om menniskona; ty han visste väl hvad i menniskone var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Och var en man af de Phariseer, som het Nicodemus, en öfverste ibland Judarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Han kom till Jesum om nattena, och sade till honom: Rabbi, vi vete att du äst kommen af Gudi för en lärare; ty ingen kan göra de tecken, som du gör, utan Gud är med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jesus svarade, och sade till honom: Sannerliga, sannerliga säger jag dig: Utan en blifver född på nytt, kan han icke se Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Då sade Nicodemus till honom: Huru kan en menniska födas, när hon är gammal? Icke kan hon på nytt gå in i sins moders lif, och födas?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Svarade Jesus: Sannerliga, sannerliga säger jag dig: Utan en varder född af vatten och Andanom, kan han icke ingå i Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Det som är födt af kött, det är kött; och det som är födt af Andanom, det är Ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Förundra icke, att jag sade dig, att I måsten födas på nytt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Vädret blås hvart det vill, och du hörer dess röst; och du vetst icke hvadan det kommer, eller hvart det fart alltså är hvar och en, som af Andanom född är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nicodemus svarade, och sade till honom: Huru kan detta ske?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jesus svarade, och sade till honom: Äst du en mästare i Israel, och vetst icke detta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Sannerliga, sannerliga säger jag dig: Vi tale det vi vete, och det vi hafve sett, det vittne vi; och vårt vittnesbörd anammen I icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Tron I icke, när jag säger eder om jordisk ting; huru skolen I då tro, om jag säger eder om himmelsk ting?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Och ingen far upp i himmelen, utan den som for neder af himmelen, menniskones Son, som är i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Och såsom Moses upphöjde ormen i öknene, alltså måste ock menniskones Son varda upphöjd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'På det att hvar och en, som tror på honom, skall icke förgås, utan få evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Ty så älskade Gud verldena, att han utgaf sin enda Son, på det att hvar och en, som tror på honom, skall icke förgås, utan få evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Ty icke hafver Gud sändt sin Son i verldena, att han skall döma verldena; utan på det att verlden skall varda salig genom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Hvilken som tror på honom, han varder icke dömd; men hvilken som icke tror, han är redo dömd, efter det han icke trodde i Guds enda Sons Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Men detta är domen, att Ljuset är kommet i verldena, och menniskorna älskade mer mörkret än Ljuset; ty deras gerningar voro onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Ty hvar och en, som illa gör, hatar ljuset, och kommer icke till ljuset, att hans gerningar skola icke varda straffade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Men den som gör sanningena, han kommer till ljuset, att hans gerningar skola varda uppenbara; ty de äro gjorda i Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Derefter kom Jesus och hans Lärjungar i Judiska landet, och vistades der med dem, och döpte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Döpte ock desslikes Johannes i Enon, hardt vid Salim; ty der var mycket vatten, och de kommo, och läto döpa sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Ty Johannes var icke än då kastad i häktelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Då kom upp ett spörsmål ibland Johannis lärjungar, samt med Judarna, om reningen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Och kommo till Johannem, och sade till honom: Rabbi, den som var när dig på hinsidon Jordan, den du vittnade om, si, han döper, och alle komma till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johannes svarade, och sade: Menniskan kan intet taga, utan det varder henne gifvet af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'I ären sjelfve min vittne, att jag sade: Icke är jag Christus; utan jag är sänd för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Den som brudena hafver, han är brudgummen; men brudgummens vän, som står och hörer honom, han fröjdar sig af brudgummens röst; denna min fröjd är nu fullbordad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Honom bör växa till, och mig bör förminskas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Den som ofvanefter kommer, han är öfver alla; den af jordene är, han är af jord, och af jordene talar han; den af himmelen kommer, han är öfver alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Och det han hafver sett och hört, det vittnar han; och hans vittnesbörd anammar ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Den som anammar hans vittnesbörd, han hafver beseglat, att Gud är sannfärdig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Ty den Gud sändt hafver, han talar Guds ord; ty Gud gifver icke Andan efter mått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Fadren älskar Sonen, och allt hafver han gifvit honom i händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Hvilken som tror Sonenom, han hafver evinnerligit lif; men den som icke tror Sonenom, han skall icke få se lifvet; utan Guds vrede blifver öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Då nu Herren förnam, att Phariseerna hade hört att Jesus gjorde flera Lärjungar, och döpte, än Johannes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(Ändock Jesus döpte icke sjelf, utan hans Lärjungar;)');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Öfvergaf han Judeen, och drog åter in i Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Så måste han gå genom Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Och när han kom till en stad i Samarien, som kallas Sichar, vid en bolstad, som Jacob gaf sinom son Joseph;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Och der var Jacobs brunn. Och efter det Jesus var trötter af vägen, satte han sig så ned vid brunnen; och det var vid sjette timman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Då kom en qvinna af Samarien, till att hemta vatten. Sade Jesus till henne: Gif mig dricka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Ty hans Lärjungar voro gångne in i staden, till att köpa mat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Då sade den Samaritiska qvinnan till honom: Huru bedes du, som äst en Jude, dricka af mig, som är en Samaritisk qvinna? Ty Judarna hafva ingen handel med de Samariter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jesus svarade, och sade till henne: Förstode du Guds gåfvo, och ho den är, som säger till dig: Gif mig dricka; då beddes du af honom, och han gåfve dig lefvandes vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Sade qvinnan till honom: Herre, icke hafver du det du kan tågat med, och brunnen är djuper; hvadan hafver du då lefvandes vatten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Månn du vara mer än vår fader Jacob, som gaf oss brunnen, och drack af honom, med sin barn och sin boskap?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Då svarade Jesus, och sade till henne: Hvar och en som dricker af detta vattnet, han varder törstig igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Men hvilken som dricker af det vatten, som jag honom gifver, han skall icke törsta till evig tid; utan det vatten, som jag honom gifver, skall blifva i honom en källa med springande vatten i evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Då sade qvinnan till honom: Herre, gif mig det vattnet, att jag icke törster, eller behöfver komma hit efter vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Sade Jesus till henne: Gack, kalla din man, och kom hit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Svarade qvinnan, och sade: Jag hafver ingen man. Sade Jesus till henne: Du sade rätt, jag hafver ingen man;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Ty du hafver haft fem män, och den du nu hafver, är icke din man; det sade du sant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Då sade qvinnan till honom: Herre, jag ser, att du äst en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Våre fäder hafva tillbedit på detta berget, och I sägen, att i Jerusalem är det rum, der man tillbedja skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jesus sade till henne: Qvinna, tro mig; den tid kommer, att hvarken på detta berget, eller i Jerusalem, skolen I tillbedja Fadren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'I veten icke hvad I tillbedjen; men vi vete hvad vi tillbedje; ty saligheten är af Judomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Men den tid kommer, och är nu allaredo, att rätte tillbedjare skola tillbedja Fadren i Andanom och sanningen; ty Fadren vill ock sådana hafva, som honom tillbedja skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Gud är en Ande; och de honom tillbedja, skola tillbedja honom i Andanom, och i sanningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Då sade qvinnan till honom: Jag vet, att Messias skall komma, som kallas Christus; när han kommer, varder han oss all ting undervisandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Sade Jesus till henne: Jag är den samme, som talar med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Och i det samma kommo hans Lärjungar, och undrade derpå, att han talade med qvinnone; dock sade ingen: Hvad frågar du, eller hvad talar du med henne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Då lät qvinnan stå sina kruko, och gick in i staden, och sade till det folket:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Kommer, och ser en man, som mig hafver sagt allt det jag hafver gjort. Månn han icke vara Christus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Då gingo de af staden, och kommo till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Deremellan bådo Lärjungarna honom, sägande: Rabbi, ät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Sade han till dem: Jag hafver mat att äta, der I intet af veten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Då sade Lärjungarna emellan sig: Månn någor hafver burit honom äta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Sade Jesus till dem: Min mat är det, att jag gör hans vilja, som mig sändt hafver, och fullbordar hans verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Sägen I icke, fyra månader äro ännu, och skördatimmen kommer? Si, jag säger eder: Lyfter upp edor ögon, och beser markena; ty hon begynner hvitna till skörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Och den der uppskär, han tager lön, och församlar frukt till evinnerligit lif; på det att både den som sår, och den som uppskär, skola tillsamman glädjas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Ty här är det ordet sant, att en annar är den som sår, och en annar som uppskär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Jag sände eder ut att uppskära, det I hafven intet arbetat; andre hafva arbetat, och I ären ingångne i deras arbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Och månge Samariter af den staden trodde på honom, för qvinnones tals skull, som vittnade, att han hade sagt henne allt det hon hade gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'När nu de Samariter kommo till honom, bådo de honom att han ville blifva när dem; och han blef der i två dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Och mycket flere trodde för hans ords skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Och sade till qvinnona: Nu tro vi icke för ditt tals skull; ty vi hafve sjelfve hört, och vete, att han är visst Christus, verldenes Frälsare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Men två dagar derefter gick han dädan, och drog in i Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Ty Jesus vittnade sjelf, att en Prophet varder intet afhållen i sitt fädernesland.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Och när han kom i Galileen, undfingo de Galileer honom, efter de all ting sett hade, som han gjort hade i Jerusalem, på högtidsdagen; ty de hade ock varit till högtidsdagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Så kom åter Jesus i Cana i Galileen, der han hade gjort vin af vatten. Och der var en Konungsman, hvilkens son låg sjuk i Capernaum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'När han hörde, att Jesus var kommen af Judeen till Galileen, gick han till honom, och bad honom, att han ville komma ned, och göra hans son helbregda; ty han låg för döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Då sade Jesus till honom: Utan I sen tecken och under, tron I icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Konungsmannen sade till honom: Herre, kom ned, förr än min son dör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Sade Jesus till honom: Gack, din son lefver. Då trodde mannen ordena, som Jesus sade till honom, och gick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Och i det han gick ned, mötte honom hans tjenare, och bebådade honom, sägande: Din son lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Då besporde han med dem, hvad stund det var vordet bättre med honom. Och de sade till honom: I går, på sjunde timman, öfvergaf skälfvan honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Då förstod fadren, att det var den timmen, i hvilkom Jesus hade sagt till honom: Din son lefver. Och han trodde, och allt hans hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Detta är nu det andra tecknet, som Jesus gjorde, när han kom af Judeen i Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Derefter var en Judarnas högtid; och Jesus for upp till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Men i Jerusalem är en dam, vid fårahuset, som het på Ebreisko Bethesda, och hade fem skjul;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Deruti lågo en stor hop sjuke, blinde halte, borttvinade, och bidde efter att vattnet skulle röras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Ty en Ängel steg ned i dammen, på en viss tid, och rörde vattnet; den der nu först steg ned i vattnet, sedan det var rördt, han blef helbregda, ehvad sjukdom han hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Så var der en man, som hade varit sjuk i åtta och tretio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Då Jesus fick se honom der han låg, och förnam att han nu i lång tid hade legat sjuk, sade han till honom: Vill du blifva helbregda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Svarade den sjuke honom: Herre, jag hafver ingen, som hafver mig i dammen, när vattnet är rördt; men förr än jag kommer, då är en annar stigen in för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Då sade Jesus till honom: Statt upp, tag din säng, och gack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Och straxt blef den mannen helbregda, och tog sin säng, och gick; och det var på en Sabbathsdag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Då sade Judarna till honom, som var vorden helbregda: Det är Sabbath; dig är icke lofligit bära sängena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Svarade han dem: Den som gjorde mig helbregda, han sade till mig: Tag din säng, och gack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Då sporde de honom: Ho är den mannen, som dig sade: Tag din säng, och gack?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Men han, som helbregda var vorden, visste icke, ho han var; ty Jesus var undanviken, efter mycket folk var i det rummet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Derefter fann Jesus honom i templet, och sade till honom: Si, du äst vorden helbregda; synda icke härefter, att dig icke vederfars något värre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Då gick den mannen bort, och sade Judomen, att Jesus var den, som honom hade helbregda gjort;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Och derföre förföljde Judarna Jesum, och sökte efter att döda honom, efter han detta gjorde på Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Då svarade Jesus dem: Min Fader verkar intill nu; och jag verkar ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Derföre sökte Judarna ändå mer efter att döda honom; ty han ej allenast bröt Sabbathen, utan ock sade Gud vara sin Fader, görandes sig sjelf lik med Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Då svarade Jesus, och sade till dem: Sannerliga, sannerliga säger jag eder: Sonen kan intet göra af sig sjelf, utan det han ser Fadren göra; ty allt det han gör, det gör ock Sonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Ty Fadren älskar Sonen, och visar honom allt det han gör; och varder än visandes honom större verk än dessa äro, att I skolen undra derpå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Ty såsom Fadren uppväcker de döda, och gör dem lefvande; så gör ock Sonen lefvande hvem han vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Ty icke dömer heller Fadren någon; utan hafver all dom gifvit Sonenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'På det alle skola hedra Sonen, såsom de hedra Fadren. Hvilken som icke hedrar Sonen, han hedrar icke Fadren, som honom sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Sannerliga, sannerliga säger jag eder: Hvilken som hörer mitt tal, och tror honom, som mig sändt hafver, han hafver evinnerligit lif, och kommer icke i domen; utan är gången ifrå döden till lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Sannerliga, sannerliga säger jag eder: Den tid skall komma, och är nu allaredo, att de döde skola höra Guds Sons röst; och de henne höra, de skola lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Ty såsom Fadren hafver lif i sig sjelfvom, så hafver han ock gifvit Sonenom hafva lif i sig sjelfvom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Och hafver desslikes gifvit honom magt att döma; derföre, att han menniskones Son är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Förundrer eder icke öfver detta: ty den stund skall komma, i hvilko alle de i grifterna äro, skola höra hans röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'Och de som väl hafva gjort, skola framgå till lifsens uppståndelse; men de som illa hafva gjort, till domsens uppståndelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Intet kan jag göra af mig sjelf. Som jag hörer, så dömer jag, och min dom är rätt; ty jag söker icke min vilja, utan Fadrens vilja, som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Om jag vittnar om mig sjelf, då är mitt vittnesbörd icke sant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'En annar är, som vittnar om mig; och jag vet, att det vittnesbörd sant är, som han vittnar om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'I sänden till Johannes, och han gaf vittnesbörd till sanningen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Men jag tager intet vittnesbörd af mennisko; utan säger detta, på det I skolen varda salige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Han var ett brinnande och skinande ljus; och I villen en tid långt fröjdas i hans ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Men jag hafver ett större vittnesbörd än Johannis vittnesbörd; ty de verk, som Fadren hafver gifvit mig att jag skall fullborda, de samma verk, som jag gör, vittna om mig, att Fadren hafver sändt mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Och Fadren, som mig sände, han hafver vittnat om mig: I hafven hvarken någon tid hört hans röst, eller sett hans skepelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'Och hans ord hafven I icke blifvandes i eder; ty I tron icke honom, som han sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Ransaker Skrifterna; ty I menen eder hafva evinnerligit lif i dem; och de äro de som vittna om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Och I viljen icke komma till mig, att I måtten få lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Jag tager ingen pris af menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Men jag känner eder, att I icke hafven Guds kärlek uti eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Jag är kommen i mins Faders Namn, och I anammen mig icke; kommer en annar i sitt eget namn, den varden I anammande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Huru kunnen I tro, I som tagen pris hvar af androm; och den pris, som kommer allena af Gudi, söken I intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'I skolen icke mena, att jag skall anklaga eder för Fadren; det är en, som eder anklagar, nämliga Moses, den I hoppens uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Haden I trott Mosi, så haden I ock trott mig; ty om mig hafver han skrifvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Men tron I icke hans skrifter, huru skolen I då tro min ord?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Derefter for Jesus öfver det Galileiska hafvet, som är vid den staden Tiberias.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Och mycket folk följde honom, derföre att de sågo hans tecken, som han gjorde med dem som sjuke voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Och gick Jesus på ett berg, och satte sig der med sina Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Och då tillstundade Påska, Judarnas högtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Då lyfte Jesus upp sin ögon, och såg att mycket folk kom till honom, och sade till Philippum: Hvar få vi köpa bröd, att desse må äta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Det sade han till att försöka honom; ty han visste väl hvad han ville göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Svarade honom Philippus: För tuhundrade penningar bröd vore dem icke nog, till att hvar finge ett litet stycke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Då sade till honom en af hans Lärjungar, Andreas, Simon Petri broder:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Här är en pilt, som hafver fem bjuggbröd, och två fiskar; men hvad förslår det ibland så många?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Sade Jesus: Låter folket satta sig. Och på det rummet var mycket gräs. Då satte sig ned vid femtusend män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Och Jesus tog bröden, tackade, och fick Lärjungomen, och Lärjungarna skifte ibland dem som såto; sammaledes ock af fiskarna, så mycket han ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Då de voro mätte, sade han till sina Lärjungar: Hemter tillhopa stycker, som öfverblifne äro, att de icke förfaras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Så hemte de tillhopa, och uppfyllde tolf korgar med styckom, som öfver voro af fem bjuggbröd, efter dem som ätit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'När nu de menniskorna sågo, att Jesus hade gjort tecknet, sade de: Visserliga är denne den Propheten, som komma skall i verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'När då Jesus förnam, att de ville komma och taga honom, och göra honom till Konung, gick han åter afsides bort uppå berget, han sjelf allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Och när aftonen kom, gingo hans Lärjungar ned till hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Och stego till skepps, och foro öfver hafvet till Capernaum; och det var redo mörkt vordet, och Jesus var icke till dem kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Då blåste ett stort vader, och vågen begynte gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'När de nu rott hade vid fem och tjugu eller tretio stadier, fingo de se Jesum gå på hafvet, och nalkas skeppet; och de vordo förfärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Då sade han till dem: Det är jag, rädens icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Och de ville hafva tagit honom in i skeppet; och i det samma var skeppet vid landet, som de foro till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Dagen derefter, när folket, som stod på hinsidon hafvet, såg att der var intet annat skepp än det ena, som hans Lärjungar voro uti stegne; och att Jesus var icke instigen med sina Lärjungar i skeppet, utan hans Lärjungar voro bortfarne allena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Men annor skepp kommo af Tiberias, hardt till det rummet, der de hade ätit brödet, genom Herrans tacksägelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'När då folket såg, att Jesus var icke der, ej heller hans Lärjungar, stego de ock i skeppen, och kommo till Capernaum, och sökte Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Och då de funno honom på hinsidon hafvet, sade de till honom: Rabbi, när komst du hit?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Svarade Jesus dem, och sade: Sannerliga, sannerliga säger jag eder: I söken mig icke fördenskull, att I hafven sett tecken; utan fördenskull, att I hafven ätit af brödet, och ären vordne mätte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Verker icke den mat, som förgås, utan den som blifver till evinnerligit lif, den menniskones Son eder gifva skall; ty honom hafver Gud Fader beseglat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Då sade de till honom: Hvad skole vi göra, att vi verka kunne Guds verk?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Svarade Jesus, och sade till dem: Det är Guds verk, att I tron på den han sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Då sade de till honom: Hvad tecken gör du då, att vi se kunne, och tro dig? Hvad verkar du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Våre fader åto Manna i öknene, som skrifvet är: Han gaf dem bröd af himmelen till att äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Då sade Jesus till dem: Sannerliga, sannerliga säger jag eder: Icke gaf Mose eder det brödet af himmelen; men min Fader gifver eder det rätta brödet af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Ty det är Guds bröd, som nederkommer af himmelen, och gifver verldene lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Då sade de till honom: Herre, gif oss alltid detta brödet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Sade Jesus till dem: Jag är lifsens bröd; hvilken som kommer till mig, han skall icke hungra; och hvilken som tror på mig, han skall aldrig törsta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Men jag hafver sagt eder, att I hafven ock sett mig; och tron dock icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Allt det min Fader gifver mig, det kommer till mig; och den till mig kommer, honom kastar jag icke ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Ty jag är nederkommen af himmelen, icke att jag skall göra min vilja, utan hans vilja, som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Och det är mins Faders vilje, som mig sändt hafver, att jag intet borttappa skall af allt det han mig gifvit hafver; utan att jag skall uppväcka det på yttersta dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Detta är nu hans vilje, som mig sändt hafver, att hvar och en, som ser Sonen, och tror på honom, han skall hafva evinnerligit lif; och jag skall uppväcka honom på yttersta dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Då knorrade Judarna deröfver, att han sade: Jag är det brödet, som nederkommet är af himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Och sade: Är icke denne Jesus, Josephs son, hvilkens fader och moder vi känne? Huru säger han då: Jag är nederkommen af himmelen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Då svarade Jesus, och sade till dem: Knorrer icke emellan eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Ingen kan komma till mig, utan Fadren, som mig sändt hafver, drager honom; och jag skall uppväcka honom på yttersta dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Det är skrifvet i Propheterna: De skola alle varda lärde af Gudi: Hvar och en, som det nu hört hafver af Fadren, och lärt det, han kommer till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Icke så, att någor hafver sett Fadren; utan den, som är af Gudi, han hafver sett Fadren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Sannerliga, sannerliga säger jag eder: Hvilken som tror på mig, han hafver evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Jag är lifsens bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Edre fäder åto Manna i öknene, och äro blefne döde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Detta är det brödet, som nederkommer af himmelen, på det den deraf äter, skall icke dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Jag är det lefvandes brödet, som nederkommer af himmelen; hvilken som äter af detta brödet, han skall lefva evinnerliga; och det brödet, som jag gifva skall, är mitt kött, hvilket jag gifva skall för verldenes lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Då kifvade Judarna emellan sig, sägande: Huru kan denne gifva oss sitt kött till att äta?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Sade Jesus till dem: Sannerliga, sannerliga säger jag eder: Utan I äten menniskones Sons kött, och dricken hans blod, då hafven I icke lif i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Hvilken som äter mitt kött, och dricker min blod, han hafver evinnerligit lif; och jag skall uppväcka honom på yttersta dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Ty mitt kött är den rätte maten, och min blod är den rätte drycken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Hvilken som äter mitt kött, och dricker min blod, han blifver i mig, och jag i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Såsom lefvandes Fadren hafver mig sändt, och jag lefver för Fadrens skull; så ock den, som äter mig, han skall ock lefva för mina skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Detta är det brödet, som af himmelen nederkommet är; icke såsom edre fäder åto Manna, och äro blefne döde; den som äter detta brödet, han skall lefva evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Detta sade han i Synagogon, då han lärde i Capernaum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Men månge af hans Lärjungar, när de detta hörde, sade: Detta är ett hårdt tal; ho kan det höra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Så, efter Jesus visste vid sig sjelf, att hans Lärjungar knorrade deröfver, sade han till dem: Förtörnar detta eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Huru skall då ske, när I varden seende menniskones Son uppstiga, dit han förra var?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Anden är den som gör lifaktig; köttet är intet nyttigt; de ord, jag säger eder, äro ande, och äro lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Men någre af eder äro, som icke tro; ty Jesus visste väl af begynnelsen, hvilke de voro som icke trodde, och hvilken honom förråda skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Och han sade: Fördenskull sade jag eder, att ingen kan komma till mig, utan det varder honom gifvet af minom Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Ifrå den tiden gingo månge af hans Lärjungar tillrygga, och vandrade intet länger med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Då sade Jesus till de tolf: Icke viljen I ock gå bort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Svarade honom Simon Petrus: Herre, till hvem skole vi gå? Du hafver eviga lifsens ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'Och vi tro, och hafve förnummit, att du äst Christus, lefvandes Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Svarade dem Jesus: Hafver jag icke eder tolf utvalt? Och en af eder är en djefvul.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Men det sade han om Juda Simons Ischarioth; ty han var den som honom förråda skulle, och var en af de tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Derefter vistades Jesus i Galileen; ty han ville icke vistas i Judeen, derföre att Judarna foro efter att dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Och var då hardt vid Judarnas löfhyddohögtid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Då sade hans bröder till honom: Gack hädan, och gack in i Judeen, att dine Lärjungar må ock se din verk, som du gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Ty ingen, som vill uppenbar vara, förhandlar något hemliga; om du det gör, så uppenbara dig för verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Ty hans bröder trodde icke heller på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Då sade Jesus till dem: Min tid är icke än kommen; men edar tid är alltid redo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Verlden kan icke hata eder; men mig hatar hon; ty jag bär vittne om henne, att hennes verk äro ond.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Går I upp till denna högtidsdagen; jag vill icke ännu gå upp till denna högtiden; ty min tid är icke ännu fullbordad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Då han hade detta sagt till dem, blef han i Galileen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Men när hans bröder voro uppgångne, då gick ock han upp till högtiden, dock icke uppenbarliga, utan så hemliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Då sökte Judarna efter honom i högtidene, och sade: Hvar är han?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Och mycket mummel var ibland folket om honom; ty somlige sade: Han är god; och somlige sade: Nej; men han förförer folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Dock talade ingen uppenbarliga om honom, för Judarnas rädslos skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Då nu half högtiden var öfverstånden, gick Jesus upp i templet, och lärde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Och Judarna förundrade sig, och sade: Huru kan denne Skrift, efter han är icke lärd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Svarade dem Jesus, och sade: Min lärdom är icke min, utan hans som mig sändt hafver,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Hvilken som vill lyda hans vilja, han varder förnimmandes, om denna lärdom är af Gudi, eller om jag talar af mig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Hvilken som talar af sig sjelf, han söker sin egen pris; men den som söker hans pris, som honom hafver sändt, han är sannfärdig, och orättfärdighet är icke i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Gaf icke Moses eder lagen? Och likväl gör ingen af eder lagen fullt. Hvi söken I efter att döda mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Svarade folket, och sade: Du hafver djefvulen; ho söker efter att döda dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Svarade Jesus, och sade till dem: Jag gjorde ena gerning, och der undren I alle på.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Fördenskull gaf Moses eder omskärelsen; icke, att hon är af Mose, utan af fäderna; och likväl omskären I menniskona om Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Tager nu menniskan omskärelsen om Sabbathen, på det att Mose lag icke skall varda bruten; på mig blifven I misslynte, att jag gjorde hela menniskona helbregda om Sabbathen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Dömer icke efter ansigtet; utan dömer en rätt dom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Då sade någre af Jerusalem: Är icke denne, den de fara efter att döda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Och si, han talar fritt, och de tala intet till honom. Veta nu vare öfverste förvisso, att han är visst Christus?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Dock vi vete, hvadan denne är; men när Christus kommer, vet ingen hvadan hanar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Då ropade Jesus i templet, lärde, och sade: Ja, I kännen mig, och I veten hvadan jag är; och jag är icke kommen af mig sjelf; utan den mig sändt hafver han är sannfärdig, den I icke kännen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Men jag känner honom; ty jag är af honom; och han sände mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Då foro de efter att gripa honom; dock kom ingen sina händer vid honom; ty hans tid var icke än då kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Men månge af folket trodde på honom, och sade: När Christus kommer, icke varder han mer tecken görandes, än denne gjort hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Så hörde de Phariseer, att folket mumlade sådant om honom; och sände Phariseerna och de öfverste Presterna tjenarena ut, till att gripa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Då sade Jesus till dem: Jag är ännu en liten tid när eder; och så går jag bort till honom, som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'I skolen söka mig, och intet finna mig; och der jag är, dit kunnen I icke komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Då sade Judarna emellan sig: Hvart vill denne gå, att vi skole icke finna honom? Månn han vilja gå ut ibland Hedningarna, som här och der förströdde äro, och lära Hedningarna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Hvad är det för ett tal, som han sade: I skolen söka mig, och intet finna mig; och der jag är, dit kunnen I icke komma?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Men på yttersta dagen i högtidene, den ock störst var, stod Jesus, och ropade, sägandes: Hvilken som törster, han komme till mig, och dricke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Hvilken som tror på mig, såsom Skriften säger, af hans qved skola flyta lefvandes vattens strömmar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Men det sade han om Andan, hvilken de få skulle, som på honom trodde; ty den Helge Ande var icke än då på färde; ty Jesus var icke ännu förklarad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Då nu månge af folket hörde detta talet, sade de: Denne är sannerliga en Prophet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'En part sade: Denne är Christus. Men somlige sade: Icke skall Christus komma af Galileen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Säger icke Skriften, att Christus skall komma af Davids säd, och af den staden BethLehem, der David var?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Och vardt en tvedrägt ibland folket för hans skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Och somlige af dem ville gripa honom; men ingen kom händer vid honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Då kommo tjenarena till öfversta Presterna och Phariseerna; och de sade till dem: Hvi hafven I icke haft honom hit?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Tjenarena svarade: Aldrig hafver någor menniska så talat som denne mannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Svarade dem Phariseerna: Ären I icke ock förförde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Icke hafver någor af öfverstarna, eller Phariseerna, trott på honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Utan detta folket, som icke vet lagen, är förbannadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Då sade till dem Nicodemus, den som kom till honom om nattena, hvilken var en af dem:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Icke dömer vår lag någon mennisko, med mindre man först förhörer honom, och får veta hvad han gör?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Svarade de, och sade till honom: Äst du icke ock en Galilee? Ransaka, och se, att af Galileen är ingen Prophet uppkommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Och så gick hvar och en hem till sitt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Då gick Jesus ut på Oljoberget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Och om morgonen bittida kom han åter i templet, och allt folket kom till honom; och han satte sig, och lärde dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Då hade de Skriftlärde och Phariseer till honom ena qvinno, som var beslagen med hor; och när de hade ledt henne fram,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Sade de till honom: Mästar, denna qvinnan är beslagen med hor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Och Mose hafver budit oss i lagen, att sådana skola stenas; men hvad säger du?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Detta sade de, till att försöka honom, att de kunde anklaga honom. Då böjde Jesus sig ned, och skref med fingret på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'När de nu så stodo fast på sin frågo, reste han sig upp, och sade till dem: Hvilken af eder utan synd är, han kaste första stenen på henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Och böjde sig åter ned, och skref på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'När de detta hörde, och voro i samvetet öfvertygade, gingo de ut, hvar efter annan, begynnande på de äldsta intill de sista; och Jesus blef allena, och qvinnan der ståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'När Jesus reste sig upp, och såg ingen, utan qvinnona, sade han till henne: Qvinna, hvar äro dine åklagare? Hafver ingen dömt dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Sade hon: Herre, ingen; sade Jesus: Icke heller dömer jag dig. Gack bort, och synda icke härefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Åter talade Jesus till dem, sägandes: Jag är verldenes Ljus; den mig följer, han skall icke vandra i mörkret, utan han skall få lifsens ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Då sade Phariseerna till honom: Du vittnar om dig sjelf; ditt vittnesbörd är icke sant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Svarade Jesus, och sade till dem: Om jag än vittnar om mig sjelf, så är mitt vittnesbörd sant; ty jag vet hvadan jag kommen är, och hvart jag går; men I veten icke hvadan jag kommer, och hvart jag går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'I dömen efter köttet; jag dömer ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Och om jag än dömde, är min dom rätt; ty jag är icke allena; utan jag och Fadren, som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Är ock så skrifvet i edor lag, att tvegge menniskors vittnesbörd är sant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Jag är den som bär vittnesbörd om mig sjelf; bär ock Fadren, som mig sändt hafver, vittnesbörd om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Då sade de till honom: Hvar är din Fader? Jesus svarade: I kännen hvarken mig eller min Fader. Om I känden mig, då känden I ock min Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Dessa ord talade Jesus vid offerkistona, lärandes i templet; och ingen tog fatt på honom, ty hans tid var icke ännu kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Då sade åter Jesus till dem: Jag går bort, och I skolen söka mig, och skolen dö uti edra synder. Dit jag går, kunnen I icke komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Då sade Judarna: Månn han då vilja dräpa sig sjelf, medan han säger: Dit jag går, kunnen I icke komma?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Och han sade till dem: I ären nedanefter, och jag är ofvanefter; I ären af desso verldene, jag är icke af desso verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Så hafver jag nu sagt eder, att I skolen dö i edra synder; ty om I icke tron, att det är jag, skolen I dö i edra synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Då sade de till honom: Ho äst du? Och Jesus sade till dem: Aldraförst jag, som talar med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Jag hafver mycket, som jag måtte tala, och döma om eder; men den mig sändt hafver, är sannfärdig, och det jag hafver hört af honom, det talar jag i verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Men de förstodo icke, att han talade till dem om Fadren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Då sade Jesus till dem: När I hafven upphöjt menniskones Son, då skolen I förstå att det är jag, och att jag gör intet af mig sjelf; utan hvad Fadren hafver lärt mig, det talar jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Och den mig sändt hafver, är med mig. Fadren låter mig icke blifva allena; ty jag gör alltid det honom täckt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'När han detta talade, trodde månge på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Då sade Jesus till de Judar, som trodde på honom: Om I blifven vid min ord, så ären I mine rätte Lärjungar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'Och I skolen förstå sanningen; och sanningen skall göra eder fri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'De svarade honom: Vi äre Abrahams säd, och hafve aldrig någors trälar varit; huru säger då du: I skolen varda fri?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Svarade dem Jesus: Sannerliga, sannerliga säger jag eder, att hvar och en, som syndena gör, han är syndenes träl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Men trälen blifver icke i huset evinnerliga; sonen blifver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Om Sonen gör eder fri, så ären I rättsliga fri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Jag vet, att I ären Abrahams säd: men I faren efter att döda mig; ty mitt tal hafver intet rum i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Jag talar det jag hafver sett när minom Fader; och I gören det I hafven sett när edar fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Svarade de, och sade till honom: Abraham är vår fader. Sade Jesus till dem: Voren I Abrahams barn, då gjorden I Abrahams gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Nu faren I efter att döda mig, som är den man, den eder hafver sagt sanningena, hvilka jag hört hafver af Gudi; det gjorde icke Abraham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'I gören edars faders gerningar. Då sade de till honom: Vi äre icke oägta födde; vi hafve en Fader, nämliga Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jesus sade till dem: Vore Gud edar Fader, så älskaden I ju mig; ty af Gudi är jag utgången och kommen; ty jag är icke heller kommen af mig sjelf; men han hafver mig sändt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Hvi kännen I icke mitt tal? Ty I kunnen icke höra mitt tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'I ären af den fadren djefvulen, och edars faders begär viljen I efterfölja; han hafver varit en mandråpare af begynnelsen, och blef icke ståndandes i sanningene; ty sanningen är icke i honom. När han talar lögnena, talar han af sitt eget; ty han är lögnaktig, och dess fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Men efter det jag säger eder sanningena, tron I mig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Hvilken af eder straffar mig för synd? Säger jag nu eder sanningena, hvi tron I mig icke?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Den der af Gudi är, han hörer Guds ord; derföre hören I icke, att I icke ären af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Då svarade Judarna, och sade till honom: Säge vi icke rätt, att du äst en Samarit, och hafver djefvulen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jesus svarade: Jag hafver icke djefvulen; men jag prisar min Fader, och I hafven försmädat mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Jag söker icke efter min pris; den är väl till, som derefter söker, och dömer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Sannerliga, sannerliga säger jag eder: Hvilken som gömmer mitt tal, han skall icke se döden till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Då sade Judarna till honom: Nu hafve vi förstått, att du hafver djefvulen. Abraham är döder, och Propheterna, och du säger: Hvilken som gömmer min ord, han skall icke smaka döden evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Äst du mer än vår fader Abraham, som döder är? Propheterna äro ock döde; hvem gör du dig sjelfvan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jesus svarade: Är det så, att jag prisar mig sjelf, så är min pris intet; min Fader är den som mig prisar, hvilken I sägen vara eder Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Och I kännen honom dock intet; men jag känner honom; och om jag sade att jag icke kände honom, vorde jag en ljugare, lika som I; men jag känner honom, och håller hans tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham edar fader fröjdades, att han skulle få se min dag; han såg honom, och vardt glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Då sade Judarna till honom: Femtio år hafver du icke ännu, och Abraham hafver du sett!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jesus sade till dem: Sannerliga, sannerliga säger jag eder: Förr än Abraham var född, är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Då togo de upp stenar, till att kasta honom. Men Jesus gömde sig undan; och gick ut af templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Och gick Jesus framom, och såg en man, som var blind född.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Och hans Lärjungar sporde honom till, och sade: Rabbi, hvilken syndade, denne, eller hans föräldrar; att han skulle födas blind?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jesus svarade: Hvarken hafver denne syndat, eller hans föräldrar; men på det Guds verk skola uppenbaras på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Jag måste verka hans verk, som mig sändt hafver, medan dagen är; natten kommer, då ingen kan verka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Så länge jag är i verldene, är jag verldenes Ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Då han detta sagt hade, spottade han på jordena, och gjorde en träck af spotten, och smorde med träcken på dens blindas ögon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Och sade till honom: Gack bort, och två dig i dammen Siloa (det betyder Sänder). Han gick, och tvådde sig; och kom igen, och hade sin syn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Då sade grannarna, och de som honom förr sett hade, att han var en tiggare: Är icke denne den som satt och tiggde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Somlige sade: Det är han; somlige sade: Han är honom liker. Men han sjelf sade: Det är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Då sade de till honom: Huru vordo din ögon öppnad?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Svarade han, och sade: Den mannen, som kallas Jesus, gjorde en träck, och smorde min ögon, och sade till mig: Gack till dammen Siloa, och två dig. Och när jag gick, och tvådde mig, fick jag synen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Då sade de till honom: Hvar är han? Sade han: Jag vet det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Då hade de honom, som blind hade varit, till de Phariseer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Och det var på en Sabbath, när Jesus gjorde träcken, och öppnade hans ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Åter sporde honom ock de Phariseer, huru han hade fått synena. Han sade till dem: Han lade mig träck på ögonen, och jag tvådde mig, och hafver nu min syn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Då sade någre af de Phariseer: Denne mannen är icke af Gudi, efter han icke håller Sabbathen. Somlige sade: Huru kan en syndig menniska göra dessa tecken? Och en tvedrägt var emellan dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Åter sade de till den blinda: Hvad säger du om honom, att han hafver öppnat din ögon? Då sade han: En Prophet är han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Men Judarna trodde icke om honom, att han hade varit blind, och hade fått synena, tilldess de kallade föräldrarna, hans som synen hade fått;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Och sporde dem till, och sade: Är denne eder son, den I sägen vara blind född? Huru ser han nu?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Då svarade dem hans föräldrar, och sade: Vi vete, att denne är vår son, och att han var blind född.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Men huru han nu ser, vete vi icke; eller hvem hans ögon öppnat hafver, vete icke vi; han är åldrig nog, spörjer honom till; tale sjelf för sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Detta sade hans föräldrar derföre, att de räddes för Judarna; ty Judarna hade då redo beslutit emellan sig, att hvilken som bekände honom vara Christus, han skulle utkastas af Synagogon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Fördenskull sade hans föräldrar: Han är åldrig nog, spörjer honom sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Åter kallade de mannen, som hade varit blind, och sade till honom: Gif Gudi ärona; vi vete, att denne mannen är en syndare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Svarade han, och sade: Om han är en syndare, vet jag icke; ett vet jag, att jag var blind, och ser nu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Åter sade de till honom: Hvad gjorde han dig? Huru öppnade han din ögon?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Han svarade dem: Jag sade det nu eder; hörden I det icke? Hvi viljen I nu åter höra det? Viljen I ock varda hans Lärjungar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Då bannade de honom och sade: Var du hans Lärjunge; vi äre Mose lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Vi vete, att Gud hafver talat till Mosen; men hvadan denne är, vete vi icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Då svarade den mannen, och sade till dem: Det är ju underligit, att I icke skolen veta hvadan han är; och likväl hafver han öppnat min ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Vi vete, att Gud icke hörer syndare; utan den som är gudfruktig, och följer hans vilja efter, honom hörer han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Ifrå verldenes begynnelse är icke; hördt, att någor hafver dens ögon öppnat, som hafver varit blind född.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Vore han icke af Gudi, så kunde han intet göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'De svarade, och sade till honom: Du äst aller födder i synd, och vill lära oss! Och så drefvo de honom ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Och fick Jesus höra, att de honom utdrifvit hade; och när han fann honom, sade han till honom: Tror du på Guds Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Han svarade, och sade: Herre, ho är han, att jag må tro på honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Och Jesus sade till honom: Du hafver sett honom, och det är den som talar med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Då sade han: Herre, jag tror; och han tillbad honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Och Jesus sade: Till en dom är jag kommen i denna verldena; att de, som icke se, skola varda seende, och de, som se, skola varda blinde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Och någre af de Phariseer, som voro med honom, hörde detta, och sade till honom: Månne vi ock vara blinde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Sade Jesus till dem: Voren I blinde, då haden I icke synd; men nu sägen I: Vi se; derföre blifver edor synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Sannerliga, sannerliga säger jag eder: Hvilken icke går in genom dörrena i fårahuset, utan stiger annorstäds in, han är en tjuf, och en röfvare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Men hvilken som går in genom dörrena, han är herden till fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'För honom låter dörravården upp, och fåren höra hans röst; och sin egen får kallar han vid namn, och leder dem ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Och när han hafver släppt sin egen får ut, går han för dem, och fåren följa honom efter; ty de känna hans röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Men den främmande följa de icke, utan fly ifrå honom; ty de känna icke deras röst, som främmande äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Denna liknelsen sade Jesus till dem; men de förstodo icke hvad det var, som han sade dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Åter sade Jesus till dem: Sannerliga, sannerliga säger jag eder: Jag är dörren för fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Alle de som för mig komne äro, de äro tjufvar och röfvare; men fåren hörde dem intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Jag är dörren; hvilken som ingår igenom mig, han skall blifva salig; och skall ingå och utgå, och finna bet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Tjufven kommer icke, utan till att stjäla, slagta och förgöra; jag är kommen, på det de skola hafva lif, och öfvernog hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Jag är den gode herden; den gode herden låter sitt lif för fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Men den som lejder är, och icke är herden, hvilkom fåren icke tillhöra, ser ulfven komma, och öfvergifver fåren, och flyr; och ulfven bortrycker och förskingrar fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Men den lejde flyr; ty han är lejd, och värdar intet om fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Jag är den gode herden, och känner min får, och min känna mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Såsom Fadren känner mig; och jag känner Fadren; och jag låter mitt lif för fåren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Jag hafver ock annor får, som icke äro af detta fårahuset; dem måste jag ock draga härtill, och de skola höra min röst; och det skall varda ett fårahus och en herde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Fördenskull älskar Fadren mig, att jag låter mitt lif, på det jag skall åter tagat igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Ingen tager det af mig; men jag låter det af mig sjelf; jag hafver magt att låta det, och jag hafver magt taga det igen. Detta budet fick jag af minom Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Då vardt åter en tvedrägt ibland Judarna, för detta talets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Månge af dem sade: Han hafver djefvulen, och är ursinnig; hvi hören I honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Somlige sade: Sådana ord äro icke dens mans, som djefvulen hafver; icke kan djefvulen öppna de blindas ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Så vardt då i Jerusalem kyrkomessa; och det var vinter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Och Jesus gick i templena, i Salomos förhus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Då kringhvärfde Judarna honom, och sade till honom: Huru länge förhalar du med oss? Säg oss fri, om du äst Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jesus svarade dem: Jag hafver sagt eder det, och I tron det icke; gerningarna, som jag gör i mins Faders Namn, de bära vittne om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Men I tron det icke; ty I ären icke af min får, såsom jag sade eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Min får höra mina röst, och jag känner dem, och de följa mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Och jag gifver dem evinnerligit lif, och de skola icke förgås evinnerliga; ingen skall heller rycka dem utu mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Min Fader, som mig dem gifvit hafver, är store än alle; och ingen kan rycka dem utaf mins Faders hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Jag och Fadren ärom ett.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Då togo åter Judarna stenar, till att stena honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jesus svarade dem: Jag hafver många goda gerningar bevist eder af minom Fader; för hvilka af dem stenen I mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Judarna svarade honom, och sade: För god gernings skull stene vi dig icke, utan för hädelsens skull; och att du, som äst en menniska, gör dig sjelf till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jesus svarade dem: Är icke skrifvet i edor lag: Jag sade, I ären gudar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Hafver han nu kallat dem gudar, till hvilka Guds ord skedde; och Skriften kan icke varda omintet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'Och I sägen dock till honom, som Fadren helgat hafver, och sändt i verldena: Du häder Gud; derföre, att jag säger: Jag är Guds Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Gör jag icke mins Faders gerningar, så tror mig intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Men gör jag dem, tror då gerningomen, om I icke viljen tro mig; på det I skolen förstå, och tro, att Fadren är i mig, och jag i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Åter foro de efter att gripa honom; och han gick utu deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Och drog åter bort på hinsidon Jordan, till det rummet der Johannes hade först döpt; och blef der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Och månge kommo till honom, och sade: Johannes gjorde intet tecken; men allt det Johannes om denna sagt hafver, är sant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Och trodde månge der på honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Och låg en man krank, benämnd Lazarus, af Bethanien, af Marie och hennes systers Marthe by.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Och var Maria den som smorde Herran med smörjelse, och torkade hans fötter med sitt hår; hvilkens broder, Lazarus, låg sjuk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Så sände hans syster till honom, och sade: Herre, si, den du kär hafver, ligger sjuk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'När Jesus det hörde, sade han: Denne sjukdomen är icke till döds, utan till Guds äro; att Guds Son skall deraf ärad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Och hade Jesus Martham, och hennes syster, och Lazarum kär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'När han då hörde, att han var sjuk, blef han der i samma rummet två dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Derefter sade han till Lärjungarna: Låt oss åter gå in i Judeen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Lärjungarna sade till honom: Rabbi, nu ville Judarna stena dig; och åter går du dit?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jesus svarade: Äro icke tolf timmar om dagen? Hvilken som vandrar om dagen, han stöter sig icke; ty han ser denna verldenes ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Men den som vandrar om nattena, han stöter sig; ty ljuset är icke i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Detta talade han; och sedan sade han till dem: Lazarus, vår vän, sofver; men jag går att uppväcka honom af sömnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Då sade hans Lärjungar: Herre, sofver han, så varder det bättre med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Men Jesus talade om hans död; och de mente, att han hade talat om lekamlig sömn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Så sade då Jesus uppenbarliga: Lazarus är död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Och jag gläds för edra skull, att jag icke var der, på det I tro skolen; men låter oss gå till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Då sade Thomas, som kallas Tvilling, till Lärjungarna: Låt ock oss gå, att vi må dö med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Då kom Jesus, och fann honom redo hafva legat fyra dygn i grafvene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Och var Bethanien icke långt ifrå Jerusalem, vid femton stadier vägs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Och månge af Judarna voro komne till Martha och Maria, att de skulle hugsvala dem öfver deras broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'När Martha hörde att Jesus kom, lopp hon emot honom; men Maria satt hemma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Då sade Martha till Jesum: Herre, hade du varit här, hade min broder icke blifvit död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Men jag vet ännu, att allt det du bedes af Gudi, det varder Gud gifvandes dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Sade Jesus till henne: Din broder skall stå upp igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Sade Martha till honom: Jag vet, att han skall uppstå i uppståndelsen, på yttersta dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Sade Jesus till henne: Jag är uppståndelsen och lifvet; hvilken som tror på mig, han skall lefva, om han än död blefve;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Och hvar och en som lefver, och tror på mig, han skall icke dö evinnerliga; tror du det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Sade hon till honom: Ja, Herre, jag tror, att du äst Christus, Guds Son, som komma skulle i verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Och när hon detta hade sagt, gick hon bort, och kallade Maria, sina syster, lönliga, och sade: Mästaren är kommen, och kallar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'När hon det hörde, stod hon straxt upp, och kom till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Ty Jesus var icke än då kommen in i byn; utan var på samma rum, der Martha hade kommit emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Då nu Judarna, som med henne voro i huset, och hugsvalade henne, sågo Maria, att hon stod hasteliga upp och gick ut, följde de henne, och sade: Hon går till grafvena, att hon skall gråta der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Då Maria kom dit som Jesus var, och såg honom, föll hon till hans fötter, och sade till honom: Herre, hade du varit här, vore min broder icke död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'När Jesus såg henne gråta, och Judarna, som voro komne med henne, ock gråta, förbittrade han sig i Andanom, och bedröfvades i sig sjelf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'Och sade: Hvar laden I honom? Sade de till honom: Herre, kom och se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Och Jesus gret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Då sade Judarna: Si, huru kär hade han honom!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Men somlige af dem sade: Kunde icke han, som öppnade dens blindas ögon, hafva så gjort, att denne icke blifvit död?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Då förbittrades åter Jesus i sig sjelf, och kom till grafvena. Och det var en kula; och en sten lagd deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Sade Jesus: Tager bort stenen. Sade till honom Martha, hans syster som död var: Herre, han luktar redo; ty han hafver varit död i fyra dygn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jesus sade till henne: Sade jag icke dig, att, om du trodde, skulle du få se Guds härlighet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Då togo de stenen bort af rummet, der den döde lagder var. Och Jesus hof upp sin ögon, och sade: Fader, jag tackar dig, att du hafver hört mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Dock vet jag, att du hörer mig alltid; men för folkets skull, som här omkring står, säger jag det, på det de tro skola, att du mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Och då han det sagt hade, ropade han med höga röst: Lazare, kom ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Och han, som död var, kom ut, bunden om händer och fötter med svepekläde; och hans ansigte var förtäckt med en svetteduk. Jesus sade till dem: Löser honom, och låter honom gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Då trodde månge af Judarna på honom, som komne voro till Maria, och sågo det Jesus gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Men somlige gingo bort till de Phariseer, och sade dem hvad Jesus hade gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Då församlade de öfverste Presterna och Phariseerna ett Råd, och sade: Hvad göre vi? Ty denne mannen gör mång tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Låte vi honom så blifva, då tro alle på honom; och de Romare komma, och taga bort vårt land och folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Men en af dem, vid namn Caiphas, som var öfverste Prest på det året, sade till dem: I veten intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Ej heller besinnen I, att oss är bättre att en man dör för folket, än att allt folket skulle förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Det sade han icke af sig sjelf; men efter han var öfverste Prest om det året, propheterade han; ty Jesus skulle dö för folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'Och ej allenast för folket, utan att han församla skulle Guds barn, som förströdde voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Ifrå den dagen rådslogo de emellan sig, att de skulle döda honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Så vandrade nu icke Jesus mer uppenbarliga ibland Judarna; utan gick dädan i den landsändan vid öknen, i en stad som heter Ephrem; och vistades der med sina Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Och instundade då Judarnas Påska; och månge gingo utaf landet upp till Jerusalem, för Påska, att de skulle rena sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Då sökte de efter Jesum, och talades vid emellan sig, ståndande i templet: Hvad synes eder, att han är icke kommen till högtidsdagen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Och hade öfverste Presterna och de Phariseer budit på, att hvilken som visste hvar han vore, skulle han det kungöra, att de måtte gripa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Sex dagar för Påska kom Jesus till Bethanien, der Lazarus hade varit död, den han uppväckte ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Der gjorde de honom en nattvard; och Martha tjente, men Lazarus var en af dem som med honom vid bord såto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Då tog Maria ett pund smörjelse, af kosteligit oförfalskadt nardus, och smorde Jesu fötter, och torkade hans fötter med sitt hår; och huset uppfylldes med lukt af smörjelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Då sade en af hans Lärjungar, Judas Simons Ischarioth, som honom förråda skulle:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Hvi vardt icke denna smörjelsen såld för trehundrade penningar, och gifvet fattigom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Det sade han, icke att honom vårdade något om de fattiga; utan förty han var en tjuf, och hade pungen, och bar det gifvet vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Då sade Jesus: Låt henne blifva; hon hafver det bevarat till mins begrafvelses dag,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Ty I hafven alltid fattiga när eder; men mig hafven I icke alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Så förnam mycket folk af Judarna, att han var der; och kommo dit, icke allenast för Jesu skull, utan ock att de skulle se Lazarum, den han uppväckt hade ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Då rådslogo de öfverste Presterna, att de ock skulle dräpa Lazarum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Ty månge af Judarna gingo bort för hans skull, och trodde på Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Dagen derefter, när folket, som då mycket kommet var till högtidsdagen, hörde att Jesus kom till Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Togo de palmqvistar, och gingo ut emot honom, och ropade: Hosianna! Välsignad han, som kommer i Herrans Namn, Israels Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Och fick Jesus ena åsninno, och satte sig deruppå; såsom skrifvet är:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Räds icke, du dotter Zion; si, din Konung kommer, sittandes på en åsninnos fåla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Detta förstodo hans Lärjungar icke med det första; utan då Jesus var förklarad, kommo de ihåg, att detta var skrifvet om honom, och att de hade detta gjort honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Vittnade ock folket om honom, som med honom varit hade, när han kallade Lazarum utaf grafvene, och väckte honom upp ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Fördenskull kom ock folket emot honom, att de hörde, han hade gjort det tecknet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Då sade Phariseerna emellan sig: I sen, att I intet kunnen skaffa; si, hela verlden löper efter honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Voro ock någre Greker, af dem som uppfarne voro, att tillbedja i högtidene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'De gingo till Philippum, som var af Bethsaida i Galileen, och bådo honom, sägande: Herre, vi vilje se Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Philippus kom, och sade det för Andreas; Andreas och Philippus sade det åter till Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Jesus svarade dem, sägandes: Tiden är kommen, att menniskones Son skall varda förklarad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Sannerliga, sannerliga säger jag eder: Utan hvetekornet, som faller i jordena, varder dödt, så blifver det allena; men varder det dödt, så bär det mycken frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Hvilken som älskar sitt lif, han skall mista det; och hvilken som hatar sitt lif i denna verldene, han skall behålla det till evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Den mig tjenar, han följe mig; och hvar jag är, der skall ock min tjenare vara. Hvilken mig tjenar, honom skall min Fader ära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Nu är min själ bedröfvad; och hvad skall jag säga? Fader, hjelp mig utu denna stundene. Dock är jag fördenskull kommen till denna stundena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Fader, förklara ditt Namn. Då kom en röst af himmelen, och sade: Jag hafver det förklarat, och skall ännu förklarat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Folket, som stod och hörde det, sade: Det var en tordön. Somlige sade: En Ängel talade med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Svarade Jesus, och sade: Denna rösten kom icke för mina skull, utan för edra skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Nu går domen öfver denna verldena; nu skall denna verldenes Förste utkastas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Och om jag varder upphöjd ifrå jordene, skall jag draga alla till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Men det sade han, till att beteckna med hvad död han dö skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Svarade honom folket: Vi hafva hört af lagen, att Christus blifver evinnerliga; huru säger då du, menniskones Son måste upphöjas? Ho är denne menniskones Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Då sade Jesus till dem: Än är Ljuset med eder till en kort tid; vandrer medan I hafven Ljuset, att mörkret begriper eder icke. Hvilken som vandrar i mörkret, han vet icke hvart han går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Medan I hafven Ljuset, tror på Ljuset, att I mågen blifva Ljusens barn. Detta sade Jesus; och gick bort, och dolde sig för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Och ändock han gjorde så mång tecken för dem, likväl trodde de intet på honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Att det talet skulle fullkomnas, som Esaias Propheten sagt hade: Herre, ho tror vår predikan; och hvem är Herrans arm uppenbarad?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Derföre kunde de icke tro; ty Esaias hafver åter sagt:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Han hafver förblindat deras ögon, och förhärdat deras hjerta; att de icke skola se med ögonen, och icke förstå med hjertat, och omvända sig, att jag måtte hela dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Detta sade Esaias, när han såg hans härlighet, och talade om honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Dock likväl trodde ock månge af de öfversta på honom; men de bekände det icke, för de Phariseers skull, att de icke skulle utkastas af Synagogon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Ty de höllo mer af menniskors pris, än af Guds pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Då ropade Jesus, och sade: Den som tror på mig, han tror icke på mig, utan på honom som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'Och den mig ser, han ser honom som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Jag är kommen i verldena för ett Ljus, att hvar och en, som tror på mig, skall icke blifva i mörkret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Och hvilken som hörer min ord, och icke tror, icke dömer jag honom; ty jag är icke kommen till att döma verldena; utan att jag skall frälsa verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Hvilken mig föraktar, och tager icke min ord, han hafver den honom döma skall; det talet, jag talat hafver, skall döma honom på yttersta dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Ty jag hafver icke talat af mig sjelf; utan Fadren, som mig sändt hafver, han hafver budit mig hvad jag skall säga, och hvad jag skall tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Och jag vet, att hans bud är evinnerligit lif; derföre, hvad jag talar, det talar jag såsom Fadren hafver sagt mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'För Påskahögtiden, efter Jesus visste att hans tid var kommen, att han gå skulle af denna verldene till Fadren, såsom han hade älskat sina, som voro i verldene, så älskade han dem uti ändan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Och då Nattvarden var gjord, och djefvulen hade redo ingifvit Jude Simons Ischarioth i hjertat, att han skulle förråda honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Visste ock Jesus, att Fadren hade allt gifvit honom i händer, och att han var utgången af Gudi, och gick till Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Stod han upp af Nattvarden, och lade af kläden; och tog ett linnet kläde, och band om sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Sedan lät han vatten i ett bäcken, och begynte två Lärjungarnas fötter, och torkade med det linna klädet, som han var ombunden med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Så kom han då till Simon Petrus. Och han sade till honom: Herre, skulle du två mina fötter?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesus svarade, och sade till honom: Det jag gör, vetst du icke nu; härefter skall du det få veta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Petrus sade till honom: Aldrig skall du två mina fötter. Jesus svarade honom: Om jag icke tvår dig, då hafver du ingen del med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Då sade till honom Simon Petrus: Herre, icke allenast mina fötter, utan ock händer och hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jesus sade till honom: Den som tvagen är, honom görs icke behof, utan att två fötterna; men han är all ren; och I ären rene, dock icke alle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Ty han visste ho den var, som honom förråda skulle; derföre sade han: I ären icke rene alle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Sedan han då hade tvagit deras fötter, och tagit sin kläder på sig igen, och satt sig, sade han åter till dem: Veten I hvad jag eder gjort hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'I kallen mig Mästare och Herre; och I sägen rätt; ty jag är ock så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Hafver nu jag, som är eder Herre och Mästare, tvagit edra fötter, så skolen I ock inbördes två hvarannars fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Jag hafver gifvit eder efterdömelse, att såsom jag gjorde eder, så skolen I ock göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Sannerliga, sannerliga säger jag eder: Tjenaren är icke förmer än hans herre; icke är heller sändabådet förmer än han, som honom sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Om I detta veten, salige ären I, om I det gören.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Icke talar jag om eder alla; jag vet hvilka jag hafver utkorat; men på det att Skriften skall varda fullkomnad: Den der äter bröd med mig, han trampade mig med sin fot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Nu säger jag eder det, förr än det sker, att, när det är skedt, skolen I tro att det är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Sannerliga, sannerliga säger jag eder: Hvilken som undfår dem jag sänder, han undfår mig; men hvilken som mig undfår, han undfår honom som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'När Jesus hade detta sagt, vardt han bedröfvad i Andanom, och betygade, och sade: Sannerliga, sannerliga säger jag eder, att en af eder skall förråda mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Då sågo Lärjungarna hvar på annan, och voro tvehågse om hvem han talade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Och var en af hans Lärjungar, som satt vid bordet intill Jesu bröst, den Jesus hade kär;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Till honom vinkade Simon Petrus, att han fråga skulle, ho den var som han talade om.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'När han nu låg intill Jesu bröst, sade han till honom: Herre, hvilken äret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Svarade Jesus: Den äret, som jag räcker det indoppade brödet. Och när han hade indroppat brödet, gaf han det Jude Simons Ischarioth;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Och efter den betan for Satan in i honom. Så sade då Jesus till honom: Det du gör, gör snart.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Men ingen af dem, som vid bordet såto, förstod, till hvad han sade honom det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Ty somlige mente, efter Judas hade pungen, att Jesus hade sagt honom: Köp hvad behof görs till högtidsdagen; eller, att han skulle gifva de fattiga något.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'När han då tagit hade den betan, gick han straxt ut; och det var natt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Då han var utgången, sade Jesus: Nu är menniskones Son förklarad, och Gud är förklarad i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Är nu Gud förklarad i honom, så skall ock Gud förklara honom i sig sjelfvom, och skall snart förklara honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Kära barn, jag är ännu en liten tid när eder; I skolen söka mig; och såsom jag sade Judomen: Dit jag går, kunnen I icke komma; så säger jag ock nu eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Ett nytt bud gifver jag eder, att I älsken eder inbördes, såsom jag hafver älskat eder; på det I ock skolen älska eder inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Deraf skola alle förstå, att I ären mine Lärjungar, om I hafven kärlek inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Då sade Simon Petrus till honom: Herre, hvart går du? Svarade honom Jesus: Dit jag går, kan du nu icke följa mig; men härefter skall du följa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Sade Petrus till honom: Herre, hvi kan jag icke nu följa dig? Mitt lif vill jag låta för dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jesus svarade honom: Skulle du låta ditt lif för mig? Sannerliga, sannerliga säger jag dig: Hanen skall icke gala, förr än du hafver tre resor nekat mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Och han sade till sina Lärjungar: Edart hjerta vare icke bedröfvadt: Tron I på Gud, så tror ock på mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'I mins Faders hus äro många boningar; om så icke vore, säger jag dock eder, att jag går bort till att bereda eder rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Och om jag än går bort till att bereda eder rum, skall jag likväl komma igen, och taga eder till mig; att hvar jag är, der skolen I ock vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Och hvart jag går, veten I, och vägen veten I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Thomas sade till honom: Herre, vi vete icke hvart du går; och huru kunne vi veta vägen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jesus sade till honom: Jag är vägen, sanningen och lifvet; ingen kommer till Fadren, utan genom mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Känden I mig, så känden I ju ock min Fader; och nu kännen I honom, och hafven sett honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Philippus sade till honom: Herre, låt oss se Fadren, så hafve vi nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Sade Jesus till honom: Jag är så lång tid när eder, och du känner mig icke; Philippe, den mig ser, han ser Fadren; och huru säger du: Låt oss se Fadren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Tror du icke, att jag är i Fadrenom, och Fadren i mig? Orden, som jag talar till eder, talar jag icke af mig sjelf; Fadren, som är i mig, han gör gerningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Tror mig, att jag är i Fadrenom, och Fadren i mig; eljest, tror mig för gerningarnas skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Sannerliga, sannerliga säger jag eder: Den der tror på mig, de gerningar, som jag gör, skall ock han göra; och skall göra större än dessa; ty jag går till Fadren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Och allt det I bedjen i mitt Namn, det skall jag göra; på det att Fadren skall prisad varda i Sonenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Hvad I bedjen i mitt Namn, det skall jag göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Älsken I mig, så håller min bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Och jag skall bedja Fadren, och han skall gifva eder en annan Hugsvalare, att han skall blifva när eder evinnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Sanningenes Anda, den verlden icke kan undfå; ty hon ser honom icke, och känner honom icke; men I kännen honom; ty han blifver när eder, och skall vara i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Jag skall icke låta eder vara faderlösa; jag skall komma till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Än är en liten tid, och verlden ser mig icke mer. Men I skolen se mig; ty jag lefver; I skolen ock lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'På den dagen skolen I förstå, att jag är i minom Fader; och I i mig, och jag i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Den min bud hafver, och håller dem, han är den mig älskar; och den mig älskar, han skall varda älskad af minom Fader; och jag skall älska honom, och honom skall jag uppenbara mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Sade till honom Judas, icke den Ischarioth: Herre, hvad är det då, att du skall uppenbara dig oss, och icke verldene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Svarade Jesus, och sade till honom: Den mig älskar, han varder hållandes min ord, och min Fader skall älska honom; och vi skole komma till honom, och blifva boende när honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Men den mig icke älskar, han håller icke min ord; och det ordet I hören, är icke mitt, utan Fadrens som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Detta hafver jag talat till eder, medan jag hafver varit när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Men Hugsvalaren, den Helge Ande, hvilken Fadren skall sända i mitt Namn, han skall lära eder all ting, och påminna eder allt det jag eder sagt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Friden låter jag eder; min frid gifver jag eder; icke gifver jag eder, såsom verlden gifver. Edart hjerta vare icke bedröfvadt, ej heller rädes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'I hörden, att jag sade eder: Jag går bort, och kommer åter till eder. Haden I mig kär, då gladdens I ju, att jag sade: Jag går till Fadren; ty Fadren är större än jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Och nu sade jag eder det, förr än det sker, att I tro skolen, när det skedt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Härefter talar jag icke mycket med eder; ty denna verldenes Förste kommer; och i mig hafver han intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Men på det att verlden skall förstå, att jag hafver Fadren kär, och så gör som Fadren mig budit hafver; står upp, låter oss gå hädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Jag är ett sant vinträ, och min Fader är en vingårdsman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Hvar och en gren i mig, som icke bär frukt, den tager han bort; och hvar och en, som bär frukt, den rensar han, att han mer frukt bära skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Nu ären I rene, för det tals skull, som jag hafver talat med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Blifver i mig, och jag i eder; såsom grenen kan icke bära frukt af sig sjelf, med mindre han blifver i vinträt, så kunnen icke heller I, utan I blifven i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Jag är vinträt, I ären grenarna; den som blifver i mig, och jag i honom, han bär mycken frukt; ty mig förutan kunnen I intet göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Hvilken som icke blifver i mig, han skall bortkastas, såsom en gren, och förtorkas; och man binder dem samman, och kastar i elden, och de brinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Om I blifven i mig, och min ord blifva i eder, allt det I viljen, mågen I bedas, och det skall ske eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Derutinnan är min Fader prisad, att I bären mycken frukt, och varden mine Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Såsom Fadren hafver älskat mig, så hafver jag ock älskat eder; blifver i min kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Om I hållen min bud, så blifven I i minom kärlek; såsom ock jag hafver hållit mins Faders bud, och blifver i hans kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Detta hafver jag talat till eder, att min glädje skall blifva i eder, och edor glädje fullkommen varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Detta är mitt bud, att I skolen älska eder inbördes, såsom jag hafver älskat eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Ingen hafver större kärlek, än att en låter sitt lif för sina vänner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'I ären mine vänner, om I gören hvad jag bjuder eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Härefter säger jag icke, att I ären tjenare, ty tjenaren vet icke hvad hans herre gör; men vänner hafver jag kallat eder, ty allt det jag hafver hört af minom Fader, hafver jag kungjort eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'I hafven icke utkorat mig; men jag hafver utkorat eder, och tillskickat eder, att I skolen gå, och göra frukt, och edor frukt skall blifva; på det att hvad I bedjen Fadren i mitt Namn, det skall han gifva eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Detta bjuder jag eder, att I älsken eder inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Om verlden hatar eder, så veter, att hon hafver hatat mig förr än eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Voren I af verldene, så älskade verlden det hennes vore; men efter det I icke ären af verldene, utan jag hafver eder utvalt ifrå verldene, derföre hatar verlden eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Kommer ihåg min ord, som jag hafver sagt eder: Tjenaren är icke förmer än hans herre; hafva de förföljt mig, så skola de ock förfölja eder; hafva de hållit min ord, så varda de ock hållande edor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Men allt detta skola de göra eder för mitt Namns skull; ty de känna icke honom, som mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Hade jag icke kommit, och talat med dem, så hade de icke synd; men nu hafva de ingen ursäkt för sina synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Den mig hatar, han hatar ock min Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Hade jag icke gjort de gerningar ibland dem, som ingen annar gjort hafver, så hade de icke synd; men nu hafva de sett det, och hata dock både mig och min Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Dock är det skedt, att det talet fullkomnas skall, som i deras lag skrifvet är: De hafva hatat mig utan sak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Men när Hugsvalaren kommer, den jag skall sända eder af Fadrenom, sanningenes Ande, som utgår af Fadrenom, han skall bära vittnesbörd om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'I skolen ock desslikes vittna; ty I hafven varit med mig af begynnelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Detta hafver jag sagt eder, på det I icke skolen förargas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'De skola utskjuta eder af Synagogorna; men den tid skall komma, att den eder dräper, skall mena sig göra Gudi tjenst dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Och detta skola de göra eder; ty de känna icke Fadren, ej heller mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Men detta hafver jag sagt eder, att, när den tiden kommer, skolen I komma ihåg, att jag hafver det sagt eder. Detta hafver jag icke sagt eder af begynnelsen; ty jag var med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Men nu går jag till honom, som mig sändt hafver; och ingen af eder spor mig, hvart jag går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Men efter det jag hafver detta sagt eder, är edart hjerta vordet fullt med bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Dock säger jag eder sanningen: Eder är nyttigt, att jag bortgår; ty om jag icke bortgår, kommer icke Hugsvalaren till eder; men går jag bort, så skall jag sända honom till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Och när han kommer, skall han straffa verldena för synd, och för rättfärdighet, och för dom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'För synd; ty de tro icke på mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'Men för rättfärdighet; ty jag går till Fadren, och härefter sen I mig intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Men för dom; ty denna verldenes Förste är nu dömd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Jag hafver ännu mycket säga eder; men I kunnen det icke nu bära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Men när han kommer, som är sanningenes Ande, han skall leda eder uti all sanning; ty han skall icke tala af sig sjelf; men hvad han hörer, det skall han tala, och det som ske skall, skall han förkunna eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Han skall prisa mig; ty af mino skall han taga, och förkunna eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Allt det Fadren hafver, det är mitt; fördenskull sade jag, att han skall taga af mino, och förkunna eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Någon liten tid, och I sen mig intet; och åter en liten tid, och I fån se mig; ty jag går till Fadren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Då sade någre af hans Lärjungar emellan sig: Hvad är det han säger oss? En liten tid, och I sen mig intet; och åter: En liten tid, och I fån se mig; och att jag går till Fadren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Då sade de: Hvad är det han säger: En liten tid? Vi vete icke hvad han talar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Då märkte Jesus, att de ville spörja honom, och sade till dem: Derom frågen I emellan eder, att jag sade: En liten tid, och I sen mig intet; och äter: En liten tid, och I fån se mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Sannerliga, sannerliga säger jag eder: I skolen gråta, och jämra eder; men verlden skall glädjas; I skolen varda bedröfvade; men edor sorg skall vändas i glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'När qvinnan föder barn, hafver hon sorg; ty hennes stund är kommen; men när hon hafver födt barnet, kommer hon sin bedröfvelse intet ihåg; ty hon gläds, att menniskan är född i verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Så hafven I ock nu bedröfvelse; men jag skall återse eder, och edart hjerta skall glädjas, och ingen skall taga edor glädje ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Och på den dagen skolen I intet spörja mig. Sannerliga, sannerliga säger jag eder: Allt det I bedjen Fadren i mitt Namn, skall han gifva eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Härtill hafven I icke bedit i mitt Namn; beder, och I skolen få, att edor glädje må varda fullkommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Detta hafver jag talat till eder med förtäckt ord; den tid skall komma, att jag icke skall tala med eder med förtäckt ord; utan uppenbarliga skall jag förkunna eder om min Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'På den dagen skolen I bedja i mitt Namn; och jag säger icke eder, att jag skall bedja Fadren för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Ty Fadren sjelf hafver eder kär, efter det I haden mig kär, och trodden, att jag är utgången af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Jag gick ut af Fadren, och kom i verldena; åter öfvergifver jag verldena, och går till Fadren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Sade hans Lärjungar till honom: Si, nu talar du uppenbarliga, och säger inga förtäckt ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Nu vete vi, att du vetst all ting, och dig görs icke behof, att någor spor dig; derföre tro vi, att du äst utgången af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Svarade Jesus dem: Nu tron I?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Si, tiden tillstundar, och är redo kommen, att I varden förskingrade, hvar och en till sitt, och låten mig blifva allena; men jag är icke allena; ty Fadren är med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Detta hafver jag talat med eder, att I skolen hafva frid i mig; i verldene hafven I tvång; men varer vid en god tröst, jag hafver öfvervunnit verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Detta talade Jesus, och lyfte upp sin ögon till himmelen, och sade: Fader, stunden är kommen; förklara din Son, att din Son förklarar ock dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Såsom du hafver gifvit honom magt öfver allt kött, att allom dem, som du hafver honom gifvit, skall han gifva evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Och detta är evinnerligit lif, att de känna dig allena sannan Gud, och den du sändt hafver, Jesum Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Jag hafver förklarat dig på jordene; jag hafver fullbordat det verk, som du mig; gifvit hafver att jag göra skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Och nu, Fader, förklara du mig när dig sjelfvom, med den klarhet, som jag hade när dig, förr än denna verlden var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Jag hafver uppenbarat ditt Namn menniskomen, som du hafver mig gifvit af verldene; de voro dine, och du hafver gifvit mig dem, och de hafva hållit din ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Nu hafva de förstått, att allt det du mig gifvit hafver, är af dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Ty de ord du hafver mig gifvit, hafver jag gifvit dem, och de togo vid dem; och hafva sannerliga förstått, att jag är utgången af dig, och hafva trott, att du mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Jag beder för dem; för verldene beder jag icke, utan för dem som du hafver mig gifvit: ty de äro dine.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Och allt mitt är ditt, och ditt är mitt; och jag är förklarad i dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Och nu är jag icke mer i verldene; men de äro i verldene, och jag kommer till dig. Helge Fader, förvara, genom ditt Namn, dem som du mig gifvit hafver, att de blifva ett, såsom ock vi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'När jag var med dem i verldene, förvarade jag dem i ditt Namn; dem du mig gifvit hafver, hafver jag förvarat, och ingen af dem är borttappad, utan det förlorade barnet, att Skriften skulle fullbordas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Nu kommer jag till dig, och talar detta i verldene; på det de skola hafva mina fullkomliga glädje i sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Jag hafver fått dem din ord, och verlden hafver hatat dem, efter de icke äro af verldene; såsom ock jag icke är af verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Icke beder jag, att du skall taga dem af verldene; utan att du förvarar dem ifrån ondo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'De äro icke af verldene; såsom ock jag icke är af verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Helga dem i dine sanning; ditt tal är sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Såsom du hafver mig sändt i verldena, så hafver ock jag sändt dem i verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Och jag helgar mig sjelf för dem; att de skola ock vara helgade i sanningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Men icke beder jag allenast för dem, utan ock för dem, som genom deras ord skola tro på mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Att de skola alle vara ett, såsom du, Fader, i mig, och jag i dig; att de ock skola vara ett i oss, på det att verlden skall tro, att du hafver mig sändt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Och jag hafver gifvit dem den härlighet, som du mig gifvit hafver; att de skola vara ett, såsom ock vi ärom ett;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Jag i dem, och du i mig; att de skola vara fullkomne uti ett; och att verlden skall förstå, att du mig sändt hafver, och älskade dem, såsom du ock mig älskade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Fader, jag vill, att der jag är, skola ock de vara med mig, som du mig gifvit hafver; att de skola se mina härlighet, den du mig gifvit hafver; ty du hafver älskat mig, förr än verlden var skapad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Rättvise Fader, verlden hafver icke känt dig; men jag hafver känt dig; och desse hafva förstått att du mig sändt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Och jag hafver kungjort dem ditt Namn, och skall kungörat; på det att den kärlek, som du hafver älskat mig med, skall vara i dem, och jag i dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Då Jesus hade detta sagt, gick han ut med sina Lärjungar, öfver den bäcken Kedron; der var en örtagård, i hvilken han ingick, och hans Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Så visste ock Judas, som förrådde honom, rummet; ty Jesus plägade ofta komma dit med sina Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Då nu Judas hade tagit med sig skaran, och de öfversta Presternas och Phariseernas tjenare, kom han dit med lyktor, och bloss, och värjor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Och efter Jesus visste allt det honom vederfaras skulle, gick han fram, och sade till dem: Hvem söken I?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Svarade de honom: Jesum af Nazareth. Sade Jesus till dem: Jag äret. Stod ock Judas, som honom förrådde, med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'När han då sade till dem: Jag äret? stego de tillrygga, och föllo till jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Då sporde han dem åter till: Hvem söken I? De sade: Jesum af Nazareth.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jesus svarade: Jag sade eder, att det är jag; söken I mig, så låter dessa gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'På det de ord skulle varda fullkomnad, som han sagt hade: Af dem du mig gifvit hafver, borttappade jag ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Då hade Simon Petrus ett svärd, och drog det ut, och högg till öfversta Prestens dräng, och högg hans högra öra af; och var drängsens namn Malchus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Då sade Jesus till Petrum: Stick ditt svärd i skidona; skall jag icke dricka den kalken, som min Fader mig gifvit hafver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Men skaran, och höfvitsmannen, och Judarnas tjenare togo fatt på Jesum, och bundo honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Och ledde honom bort, först till Hannas; ty han var Caiphe svär, hvilken i det året var öfverste Prest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Och Caiphas var den som hade gifvit Judomen rådet, att det var nyttigt, att en menniska dödde för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Och följde Simon Petrus Jesum, och en annar Lärjunge; den samme Lärjungen var känder med öfversta Presten, och gick in med Jesu i öfversta Prestens palats;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Men Petrus stod utanför dörrene. Då gick den andre Lärjungen ut, som känder var med öfversta Presten, och talade till dörravårdinnan, och hade Petrum in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Då sade dörravårdinnan till Petrum: Äst icke ock du af denna mansens Lärjungar? Han sade: Jag är det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Men drängarna, och tjenarena, som hade gjort en koleld, ty det var kallt, stodo och värmde sig; med dem stod ock Petrus och värmde sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Då sporde öfverste Presten Jesum om hans Lärjungar, och om hans lärdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus svarade honom: Jag hafver uppenbarliga talat för verldene; jag hafver alltid lärt i Synagogon, och i templet, der alle Judar komma tillsamman; och hemliga hafver jag intet talat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Hvi spor du mig? Spor dem till, som hört hafva, hvad jag hafver talat till dem; si, de veta hvad jag hafver sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'När han detta sade, gaf en af tjenarena, som der när stodo, Jesu en kindpust, sägandes: Skall du så svara öfversta Presten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jesus svarade honom: Hafver jag illa talat, så vittna om ondt; men hafver jag väl talat, hvi slår du mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Och Hannas hade sändt honom bundnan till öfversta Presten Caiphas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Men Simon Petrus stod och värmde sig. Då sade de till honom: Äst icke ock du af hans Lärjungar? Han nekade, och sade: Jag är det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Då sade till honom en af öfversta Prestens tjenare, dens frände, som Petrus hade huggit örat af: Såg icke jag dig med honom i örtagården?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Då nekade åter Petrus det; och straxt gol hanen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Då ledde de Jesum ifrå Caiphas inför Rådhuset, och det var om morgonen; och de gingo icke in i Rådhuset, att de icke skulle varda besmittade, utan att de måtte äta Påskalambet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Då gick Pilatus ut till dem, och sade: Hvad klagomål hafven I emot denna mannen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Då svarade de, och sade till honom: Vore han icke en ogerningsman, så hade vi icke öfverantvardat dig honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Då sade Pilatus till dem: Tager I honom, och dömer honom efter edor lag. Då sade till honom Judarna: Oss är icke lofligt att döda någon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'På det Jesu tal skulle fullkomnas, som han sagt hade, då han gaf tillkänna, med hvad död han dö skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Då gick Pilatus åter in i Rådhuset, och kallade Jesum, och sade till honom: Äst du Judarnas Konung?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesus svarade: Säger du det af dig sjelf, eller hafva andre sagt dig det om mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatus svarade: Icke är jag en Jude; ditt folk, och de öfverste Presterna, hafva dig mig öfverantvardat; hvad hafver du gjort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jesus svarade: Mitt rike är icke af denna verldene; om mitt rike vore af denna verldene, då fäktade ju mine tjenare derom, att jag icke vorde Judomen öfverantvardad; men mitt rike är icke hädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Då sade Pilatus till honom: Så äst du dock en Konung? Jesus svarade: Du säger det; jag är en Konung; dertill är jag född, och är dertill kommen i verldena, att jag skall vittna med sanningene. Hvar och en, som är af sanningene, han hörer mina röst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Sade Pilatus till honom: Hvad är sanning? Och när han det sagt hade, gick han åter till Judarna, och sade till dem: Jag finner ingen sak med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'I hafven sedvänjo, att jag skall gifva eder en lös om Påska; viljen I då icke, att jag skall gifva eder Judarnas Konung lös?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Åter ropade de alle, och sade: Icke denna, utan Barabbam. Och Barabbas var en röfvare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Då tog Pilatus Jesum, och hudflängde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Och krigsknektarna vredo samman ena krono af törne, och satte på hans hufvud, och hängde ett purpurkläde på honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Och sade: Hel, Judarnas Konung! Och gåfvo honom kindpustar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Då gick åter Pilatus ut, och sade till dem: Si, jag hafver honom ut till eder, att I förstå skolen, att jag finner ingen sak med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Då gick Jesus ut, och bar ena törnekrono, och ett purpurkläde. Och han sade till dem: Si menniskan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'När de öfverste Presterna och tjenarena sågo honom, ropade de, och sade: Korsfäst, korsfäst. Pilatus sade till dem: Tager I honom, och korsfäster; ty jag finner ingen sak med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Judarna svarade honom: Vi hafve lag, och efter vår lag skall han dö; ty han hafver gjort sig sjelf till Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Då Pilatus hörde det talet, fruktade han ännu mer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Och gick åter in i Rådhuset, och sade till Jesum: Hvadan äst du? Jesus svarade honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Då sade Pilatus till honom: Talar du intet med mig? Vetst du icke, att jag hafver magt att korsfästa dig, och hafver magt att släppa dig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jesus svarade: Du hade ingen magt öfver mig, vore hon dig icke gifven ofvanefter; fördenskull hafver han större synd, som mig hafver dig; öfverantvardat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Och ifrå den tiden sökte Pilatus efter att gifva honom lös; men Judarna ropade, och sade: Gifver du honom lös, så äst du icke Kejsarens vän; ty den som sig gör till Konung, han är emot Kejsaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'När Pilatus hörde det talet, hade han Jesum ut, och satte sig på domstolen, på det rum, som kallas Lithostrotos; på Ebreisko Gabbatha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Och det var Påskatillredelsedag, vid sjette timman; och han sade till Judarna: Si, edar Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Då ropade de: Tag bort, korsfäst honom. Pilatus sade till dem: Skall jag korsfästa edar Konung? Svarade öfverste Presterna: Vi hafve ingen Konung, utan Kejsaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Då öfverantvardade han honom dem, att han skulle korsfästas. Då togo de Jesum, och ledde honom bort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Och han bar sitt kors, och gick ut på det rum, som kallas hufvudskallaplatsen; på Ebreisko Golgatha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Der korsfäste de honom, och två andra med honom, hvar på sina sido; och Jesum midt uti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Då skref Pilatus en öfverskrift, och satte på korset. Och var så skrifvet: Jesus af Nazareth, Judarnas Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Denna öfverskriftena läste månge af Judarna; ty rummet, der Jesus var korsfäst, var hardt vid staden; och det var skrifvet på Ebreisko, och Grekisko, och Latin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Då sade Judarnas öfverste Prester till Pilatum: Skrif icke, Judarnas Konung; utan, att han hafver sagt: Jag är Judarnas Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatus svarade: Hvad jag hafver skrifvit, det hafver jag skrifvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Då nu krigsknektarna hade korsfäst Jesum, togo de hans kläder, och gjorde fyra delar, en del hvarjom krigsknekt, och kjortelen med; men kjortelen var icke sömmad, utan virkad, ifrån öfverst och allt igenom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Då sade de emellan sig: Skärom honom icke sönder, utan kastom lott om honom, hvem han skall tillhöra; att Skriften skulle varda fullkomnad, som säger: De hafva bytt min kläder emellan sig, och kastat lott på min kjortel. Och detta gjorde krigsknektarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Då stodo vid Jesu kors hans moder, och hans moders syster, Maria, Cleophe hustru, och Maria Magdalena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Och när Jesus fick se modrena, och Lärjungan, den han älskade, der när ståndande, sade han till sina moder: Qvinna, si, din son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Sedan sade han till Lärjungan: Si, din moder. Och ifrå den tiden tog Lärjungen henne till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Sedan, efter Jesus visste att nu allting voro fullkomnad, att Skriften skulle fullbordas, sade han: Mig törster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Då stod der ett käril, fullt med ättiko; och de uppfyllde en svamp med ättiko, och kringlade isop, och höllo det honom för munnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Då nu Jesus hade tagit ättikona, sade han: Det är fullkomnadt; och böjde ned hufvudet, och gaf upp andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Men efter det var tillredelsedagen, att kropparna icke skulle blifva qvare på korset öfver Sabbathen, ty samme Sabbathsdag var stor, bådo Judarna Pilatum, att deras ben skulle sönderslås, och de borttagas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Då kommo krigsknektarna, och sönderslogo dens förstas ben, och dens andras, som var korsfäst med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'När de kommo till Jesum, och sågo honom allaredo vara död, slogo de icke hans ben sönder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Utan en af krigsknektarna stack upp hans sido med ett spjut; och straxt gick ut blod och vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Och den detta såg, hafver det vittnat, och hans vittnesbörd är sant; och han vet, att han säger sant, på det I ock tro skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Och skedde detta, på det Skriften skulle fullbordas: I skolen intet ben sönderslå på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Och åter säger en annor Skrift: De skola se, i hvem de stungit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Derefter bad Pilatum Joseph af Arimathia, som var Jesu Lärjunge, dock lönligen, för Judarnas rädslos skull, att han måtte taga Jesu lekamen; och Pilatus tillstadde det. Alltså kom han, och tog Jesu lekamen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Kom ock desslikes Nicodemus, som tillförene hade kommit till Jesum om nattena, och bar en blandning af myrrham och aloe, vid hundrade pund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Så togo de då Jesu lekamen, och svepte den i linkläder, med välluktande krydder, såsom Judarna pläga begrafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Och var på det rummet, der han korsfast var, en örtagård, och i örtagården en ny graf, der ännu ingen hade varit uti lagd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Der lade de då Jesum, för Judarnas tillredelsedags skull, efter grafven var när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'På den ena Sabbathen kom Maria Magdalena om morgonen, då ännu mörkt var, till grafvena, och såg stenen vara borto af grafvene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Då lopp hon, och kom till Simon Petrum, och till den andra Lärjungan, som Jesus älskade, och sade till dem: De hafva tagit Herran bort utaf grafvene, och vi vete icke hvart de hafva lagt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Då gick Petrus ut, och den andre Lärjungen, och kommo till grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Både lupo de tillika; och den andre Lärjungen lopp före, snarare än Petrus, och kom först till grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Och när han lutade sig ned, fick han se lakanen lagd; dock gick han icke in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Så kom då Simon Petrus efter honom, och gick in i grafvena, och såg lakanen lagd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'Och svetteduken, som hade varit om hans hufvud, icke lagd när lakanen, utan afsides i ett rum tillhopasvept.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Då gick ock den andre Lärjungen in, som förr var kommen till grafvena, och såg det, och troddet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Ty de förstodo icke än då Skriftena, att han skulle uppstå ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Och Lärjungarna gingo åter tillhopa igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Men Maria stod och gret utanför grafvene. Vid hon nu så gret, lutade hon sig in i grafvena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'Och fick se två Änglar i hvit kläder, sittande, den ene vid hufvudet, och den andre vid fötterna, der de hade lagt Jesu lekamen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'De sade till henne: Qvinna, hvad gråter du? Sade hon till dem: De hafva tagit bort min Herra; och jag vet icke hvart de hafva lagt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'När hon detta sade, vände hon sig tillbaka, och fick se Jesum ståndandes; och visste icke att det var Jesus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Sade Jesus till henne: Qvinna, hvad gråter du? Hvem söker du? Hon mente, att det hade varit örtagårdsmästaren, och sade till honom: Herre, hafver du burit honom bort; säg mig hvart du hafver lagt honom, och jag vill tågan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jesus sade till henne: Maria. Då vände hon sig om, och sade till honom: Rabbuni, det är, Mästar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Sade Jesus till henne: Kom icke vid mig; ty jag är icke ännu uppfaren till min Fader; men gack till mina bröder, och säg dem: Jag far upp till min Fader, och edar Fader; och till min Gud, och edar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria Magdalena kom, och bådade Lärjungomen, att hon hade sett Herran, och att han hade sagt henne detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Men om aftonen, på den samma Sabbathen, då dörrarna voro lyckta, der Lärjungarna voro församlade, för Judarnas rädslos skull, kom Jesus, och stod midt ibland dem, och sade till dem: Frid vare eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Och när han hade detta sagt, lät han dem se händerna, och sina sido. Då vordo Lärjungarna glade, att de sågo Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Då sade Jesus åter till dem: Frid vare eder; såsom Fadren hafver mig sändt, så sänder ock jag eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'När han detta sagt hade, blåste han på dem, och sade till dem: Tager den Helga Anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Hvilkom I förlåten synderna, dem förlåtas de; och hvilkom I behållen dem, dem äro de behållna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Men Thomas, en af de tolf, hvilken kallas Tvilling, var icke med dem, när Jesus kom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Då sade de andre Lärjungarna till honom: Vi sågom Herran. Sade han till dem: Utan jag ser hålen efter spikarna i hans händer, och stinger mitt finger i hålen efter spikarna, och stinger min hand i hans sido, tror jag det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Och åtta dagar derefter voro åter hans Lärjungar inne, och Thomas med dem; då kom Jesus, vid dörrarna voro lyckta, och stod midt ibland dem, och sade: Frid vare eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Sedan sade han till Thomas: Räck hit ditt finger, och ge mina händer, och räck hit dina hand, och stick henne i mina sido; och var icke tvifvelaktig, utan trogen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas svarade, och sade till honom: Min Herre, och min Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jesus sade till honom: Efter du såg mig, Thoma, tror du; salige äro de som icke se, och dock tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Gjorde ock Jesus mång annor tecken, i sina Lärjungars åsyn, som i denna bokene icke äro skrifne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Men dessa äro skrifne, på det I tro skolen, att Jesus är Christus, Guds Son; och att I, genom trona, skolen hafva lif i hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Derefter uppenbarade åter Jesus sig för Lärjungarna, vid Tiberias haf; och uppenbarade han sig I så måtto:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Petrus, och Thomas, som kallas Tvilling, voro tillsamman, och Nathanael, som var af Cana i Galileen, och Zebedei söner, och två andre af hans Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Sade Simon Petrus till dem: Jag vill gå och fiska. De sade till honom: Vi gå in ock med dig. De gingo ut, och stego straxt i båten; och i den natten fingo de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Då nu morgon var, stod Jesus på strandene; dock visste Lärjungarna icke, att det var Jesus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Sade Jesus till dem: Barn, hafven I något till mats? De svarade honom: Nej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Då sade han till dem: Kaster ut nätet på högra sidona om båten, så varden I finnande. Då kastade de ut: och kom så mycken fisk, att de förmådde det icke draga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Då sade den Lärjungen, som Jesus älskade, till Petrum: Herren äret. När Simon Petrus hörde, att det var Herren, band han om sig kjortelen, ty han var naken, och gaf sig i sjön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Men de andre Lärjungarna kommo med båten; ty de voro icke långt ifrå landet, utan vid pass tuhundrade alnar; och drogo fiskanätet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Och när de voro stigne på landet, sågo de der vara lagda glöd, och en fisk derpå, och bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jesus sade till dem: Tager hit af de fiskar, som I nu fingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Petrus steg in och drog nätet upp på landet, fullt med stora fiskar, hundrade femtio och tre; och ändock de voro så månge, gick likväl nätet icke sönder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Sade Jesus till dem: Kommer, och äter. Och ingen af Lärjungarna djerfdes till att spörja honom: Ho äst du? efter de visste, att det var Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Då kom Jesus, och tog brödet och gaf dem; och fisken sammaledes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Detta var nu tredje reson att Jesus uppenbarades sinom Lärjungom, sedan han var uppstånden ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Då de nu hade ätit, sade Jesus till Simon Petrum: Simon Jona, älskar du mig mer än desse? Han sade till honom: Ja, Herre, du vetst, att jag älskar dig. Sade han till honom: Föd min lamb.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Åter sade han till honom: Simon Jona, älskar du mig? Han sade till honom: Ja, Herre, du vetst, att jag älskar dig. Sade han till honom: Föd min får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Sade han till honom tredje reson: Simon Jona, älskar du mig? Petrus vardt bedröfvad, att han sade tredje reson till honom: Älskar du mig? och sade till honom: Herre, du vetst all ting; du vetst, att jag älskar dig. Sade Jesus till honom: Föd min får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Sannerliga, sannerliga säger jag dig: När du vast ung, omgjordade du dig sjelf, och gick hvart du ville; men då du varder gammal, skall du uträcka dina händer, och en annar skall omgjorda dig, och leda dig dit du icke vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Men det sade han, gifvandes tillkänna med hvad död han skulle prisa Gud. Och då han hade detta sagt, sade han till honom: Följ mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Petrus vände sig om, och såg den Lärjungan följa, som Jesus älskade; hvilken ock i Nattvarden låg intill hans bröst, och sade: Herre, hvilken är den dig förråder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Då Petrus såg honom, sade han till Jesum: Herre, hvad skall då denne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Sade Jesus till honom: Om jag ville att han skulle blifva, tilldess jag kommer, hvad kommer det dig vid? Följ du mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Då gick ett tal ut ibland bröderna: Denne Lärjungen dör icke. Och Jesus sade icke till honom: Han dör icke; utan, om jag ville, att han skulle blifva tilldess jag kommer, hvad kommer det dig vid?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Denne är den Lärjungen, som vittnar härom, och den detta skrifvit hafver; och vi vete, att hans vittnesbörd är sant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Äro ock mång annor ting, som Jesus gjorde, hvilka, om de det ena med det andra skrefvos, tror jag att verlden skulle icke kunna begripa de böcker, som skrifvas skulle. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Tillförene hafver jag talat, min gode Theophile, om allt det Jesus begynte både göra och lära;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Intill den dagen han upptagen vardt, sedan han Apostlomen, som han utvalt hade, genom den Helga Anda, hade gifvit befallning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Hvilkom han ock efter sin pino betedde sig lefvandes, med mångahanda bevisning, då han lät sig se af dem i fyratio dagar, och talade med dem om Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Och då han hade församlat dem, böd han dem, att de icke skulle gå utaf Jerusalem, utan förbida Fadrens löfte, der I af hört hafven (sade han) af mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Ty Johannes döpte i vatten; men I skolen döpte varda i dem Helga Anda, icke många dagar härefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Då de nu församlade voro, frågade de honom, sägande: Herre, skall du i denna tiden upprätta igen Israels rike?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Då sade han till dem: Det hörer icke eder till att veta tid och stund, som Fadren hafver satt i sine magt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Men I skolen undfå dens Helga Andas kraft, som öfver eder komma skall; och skolen vara min vittne i Jerusalem, och i hela Judeen och Samarien, och (sedan) intill jordenes ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Och när han detta sagt hade, vardt han i deras åsyn upptagen; och en sky tog honom bort utaf deras syn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Och som de uppsågo i himmelen efter honom, vid han uppfor; si, två män stodo när dem, klädde i hvit kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'De der ock sade: I Galileiske män, hvi stån I och sen upp i himmelen? Denne Jesus, som upptagen är ifrån eder i himmelen, han skall så komma, som I honom sett hafven uppfara i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Sedan gingo de till Jerusalem igen, ifrå berget som heter Oljoberget, hvilket ligger ifrå Jerusalem vid en Sabbaths reso;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Och då de inkommo, stego de upp i salen, der de stadigt blefvo, Petrus och Jacobus, Johannes och Andreas, Philippus och Thomas, Bartholomeus och Mattheus, Jacobus Alphei och Simon Zelotes, och Judas Jacobi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Alle desse voro stadigt tillhopa, endrägtige i böner och förmanelse; samt med qvinnomen, och med Maria, Jesu moder, och med hans bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Uti de dagar stod Petrus upp ibland Lärjungarna, och sade; och var hopen af namnen tillsamman vid tjugu och hundrade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'I män och bröder, den Skriften måste fullbordas, som den Helge Ande långo sagt hade genom Davids mun, om Judas, som deras ledsagare var som grepo Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Ty han var räknad i vårt tal, och hade fått med oss detta ämbetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Och han förvärfde en åker för orättfärdig lön; och upphängde sig, och remnade midt itu, och alla hans inelfver gåfvo sig ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Och det är uppenbart vordet allom dem som bo i Jerusalem; så att den åkren kallas på deras mål Akeldama, det är, blodsåker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Ty det är skrifvet i Psalmboken: Deras hemman varde öde, och ingen vare som deruti bor; och hans ämbete få en annar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Så måste nu en af dessa män, som med oss varit hafva, i allan den tid, som Herren Jesus ut och in gick med oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Ifrå Johannis döpelse till den dagen att han ifrån oss tagen vardt, med oss ett vittne varda till hans uppståndelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Och de satte två i valet, Joseph, som kallas Barsabas, med det vedernamnet Justus, och Matthiam;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Och bådo, och sade: Du Herre, som känner allas hjerta, visa ut hvilken af dessa två du utvalt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Att han skall få denna tjensten, och Apostlaämbetet, der Judas ifrå fallen är, att han skulle bortgå i sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Och de kastade lott derom, och lotten föll på Matthiam; och han vardt räknad till de ellofva Apostlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Och då Pingesdagen fullkomnad var, voro de alle endrägteliga tillsammans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Och vardt hastigt ett dön af himmelen, såsom ett mägtigt stort väder kommit hade; och uppfyllde allt huset, der de såto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Och dem syntes sönderdelada tungor, såsom af eld; och blef sittandes på kvar och en af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Och de vordo alle uppfyllde af den Helga Anda, och begynte till att tala med annor tungomål, efter som Anden gaf dem att tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Så voro i Jerusalem boende Judar, gudfruktige män af allahanda folk, som under himmelen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Då nu denna rösten skett hade, kom tillsammans mycket folk, och vordo förhäpne; ty de hörde dem tala kvar och en med sitt eget mål;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Och vordo alle förskräckte, och förundrade sig, sägande emellan sig: Si, äro icke alle desse, som tala, Galileiske?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Huru höre vi då hvar och en sitt tungomål, der vi uti födde äre?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parther och Meder, och Elamiter, och de som bo uti Mesopotamien, och i Judeen, och Cappadocien, Ponto och Asien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Phrygien och Pamphylien, Egypten, och i de Libye landsändar vid Cyrenen, och de utländningar af Rom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Judar och Proselyter, Creter och Araber; vi höre dem med våra tungor tala Guds dråpeliga verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Och förskräckte de sig alle, och förundrade sig, sägande emellan sig: Hvad månn detta vilja vara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Och somlige gjorde gack af dem, och sade: Desse äro fulle med sött vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Då stod Petrus upp, med de ellofva, och hof upp sin röst, och talade till dem: I Judiske män, och I alle som bon i Jerusalem; detta skall eder vetterligit vara, och anammer min ord uti edor öron;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Ty desse äro icke druckne, såsom I menen; efter det är tredje timmen på dagen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Utan det är det som sagdt är genom Propheten Joel:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Och det skall ske uti de yttersta dagarna, säger Gud: Jag skall utgjuta af minom Anda öfver allt kött; och edre söner och edra döttrar skola prophetera; och edre ynglingar skola se syner, och edre äldste skola drömma drömmar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Och öfver mina tjenare, och öfver mina tjenarinnor skall jag i de dagar utgjuta af minom Anda; och de skola prophetera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Och jag skall gifva under ofvan i himmelen, och tecken neder på jordene; blod och eld, och rökdamb.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Solen skall vändas i mörker, och månen i blod, förr än den store och uppenbarlige Herrans dag kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Och skall ske, att hvar och en som åkallar Herrans Namn, han skall blifva salig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'I män af Israel, hörer dessa orden: Jesum af Nazareth, den man, som när eder af Gudi bevisad är, med krafter, och under, och tecken, som Gud hafver gjort genom honom ibland eder; såsom I ock sjelfve veten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Honom, efter han af Guds betänkta råd och försyn utgifven var, hafven I tagit genom onda mäns händer, korsfäst och dödat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Den hafver Gud uppväckt, och lossat dödsens sveda; efter omöjeligit var, att han skulle behållas af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Ty David säger om honom: Jag hafver alltid föresatt Herran för min ögon; ty han är mig på högra handene, att jag icke skall rörd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Fördenskull är mitt hjerta gladt, och min tunga fröjdar sig; skall också mitt kött hvilas i förhoppning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Ty du öfvergifver icke mina själ i helvete, och tillstäder icke att din Helige skall se förgängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Du hafver mig kungjort lifsens vägar; du skall uppfylla mig med fröjd för ditt ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'I män och bröder, man må fritt tala med eder om den Patriarchen David; han är död och begrafven, och hans graf är när oss intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Efter han nu var en Prophet, och visste att Gud hade lofvat honom med en ed, att han af hans länds frukt skulle efter köttet uppväcka Christum, till att sitta på hans säte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'Såg han det framföreåt, och talade om Christi uppståndelse, att hans själ icke är öfvergifven uti helvete; icke heller hans kött hafver sett förgängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Denna Jesum hafver Gud uppväckt, der vi alle vittne till äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Medan han nu med Guds högra hand upphöjd är, och löfte fått hafver af Fadrenom om den Helga Anda, hafver han utgjutit detta I nu sen och hören.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Ty icke hafver David uppfarit i himmelen; men han säger: Herren sade till min Herra: Sätt dig på mina högra hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Tilldess jag nedlägger dina ovänner dig till en fotapall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Så skall nu hela Israels hus veta förvisso, att denna Jesum, som I korsfäst hafven, hafver Gud gjort till en Herra och Christ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Då de detta hörde, fingo de ett styng i hjertat; och sade till Petrum, och till de andra Apostlarna: I män och bröder, hvad skole vi göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Sade Petrus till dem: Görer bättring, och hvar och en af eder låte sig döpa i Jesu Christi Namn, till syndernas förlåtelse; och I skolen undfå den Helga Andas gåfvo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Ty eder är löftet gjordt, och edrom barnom, och allom dem som fjerran äro, hvilka Herren, vår Gud, härtill kallandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Betygade han ock med mång annor ord, och förmanade dem, sägandes: Låter hjelpa eder ifrå detta onda slägtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'De som då gerna anammade hans tal, de läto sig döpa; och kommo till hopen, på den dagen, vid tretusend själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Och blefvo de stadigt ståndande uti Apostlarnas lärdom, och i delaktighet, och i bröds brytelse, och i böner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Och en fruktan kom uppå hvarjo och ena själ; och mång under och tecken gjordes af Apostlarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Och alle de, som trodde, voro tillsammans, och hade all ting menlig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Sina ägodelar och håfvor sålde de, och delade dem med alla, såsom hvar och en behöfde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Och hvar dag voro de stadigt och endrägteliga i templet; och bröto bröd här och der i husen, ätandes med hvarannan i fröjd; och lofvade Gud i deras hjertans enfaldighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Och de hade ynnest när allt folket. Och Herren förökade hvar dag församlingen med dem som salige vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Så gingo Petrus och Johannes tillhopa upp i templet, vid bönestunden, som var den nionde timmen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Och der var en man, ofärdig allt ifrå sine moders lif, som lät sig bära; den satte de hvar dag för dörrena åt templet, som het den sköna, att han skulle bedas almosa af dem som ingingo i templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Då han fick se Petrum och Johannem, att de ville gå in i templet, bad han dem om almoso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Då såg Petrus på honom, med Johanne, och sade: Se på oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Då såg han på dem, förhoppandes att han skulle något få af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Då sade Petrus: Silfver och guld hafver jag icke; men det jag hafver, det gifver jag dig: I Jesu Christi Nazareni Namn, statt upp, och gack;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Och tog honom vid högra handena, och reste honom upp; och straxt vordo hans fötter och ben stadig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Han sprang upp, och stod, och gick, och följde dem in i templet; gick och sprang hit och dit, prisandes Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Då fick allt folket se honom, att han gick och lofvade Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Och kände honom, att han var den samme, som plägade sitta efter almoso, vid, den sköna dörrena för templet; och vordo fulle med undersamhet och förskräckelse öfver det honom vederfaret var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Då nu denne mannen, som ofärdig varit hade, och helbregda gjord var, höll sig intill Petrum och Johannem, lopp allt folket till dem i förhuset, som kallas Salomons, och förundrade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Då Petrus, det såg, svarade han till folket: I män af Israel, hvi undren I häruppå? Eller hvi sen I på oss, lika visst som vi af vår egen kraft eller förtjenst hade det åstadkommit, att denne hafver fått sin gång?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Abrahams, och Isaacs och Jacobs Gud, våra fäders Gud, hafver förklarat sin Son Jesum, hvilken I öfverantvardat hafven, och förnekat inför Pilatus, då han dömde, att han skulle gifvas lös.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Men I förnekaden den Helga och Rättfärdiga; och båden, att mandråparen skulle gifvas eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Och lifsens Första dråpen I. Den hafver Gud nu uppväckt ifrå de döda; till hvilket vi vittne äre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Och hafver genom trona på hans Namn, på denna, som I sen och kännen, stadfäst sitt Namn; och tron, som är genom honom, hafver gifvit denna hans helbregda, i allas edra åsyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Nu, käre bröder, vet jag väl, att I det gjort hafven af fåkunnighet, såsom ock edre öfverste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Men Gud, som genom alla sina Propheters mun föresagt hafver, att Christus skulle lida, han hafver nu så fullbordat det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Så bättrer eder nu, och vänder eder om, på det edra synder måga afskrapade varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Att vederqvickelsens tid då kommer för Herrans ansigte, när han sändandes varder den eder nu tillförene predikad är, Jesum Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Hvilken himmelen intaga måste, till den tid att igen upprättadt varder allt det Gud sagt hafver, genom alla sina helga Propheters mun, af verldenes begynnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Ty Moses hafver sagt till fäderna: Herren, edar Gud, skall eder uppväcka en Prophet utaf edra bröder, såsom mig; honom skolen I höra i allt det han eder sägandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Och det skall ske, att hvar och en själ, som icke hörer den Propheten, hon skall utkastas ifrå folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Och alle Propheterna, ifrå Samuel, och sedan så månge som talat hafva, hafva bådat dessa dagarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'I ären Propheternas och förbundsens barn, det Gud hafver gjort med våra fäder, sägandes till Abraham: I dine säd skola all folk på jordene välsignad varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Eder först och främst hafver Gud uppväckt sin Son, Jesum, och sändt honom till att välsigna eder, att hvar och en af eder skulle sig omvända ifrå sine ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Då de nu talade till folket, kommo dertill Presterna, och föreståndaren i templet, och de Sadduceer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Och togo det illa vid sig, att de lärde folket, och förkunnade, i Jesu, uppståndelsen ifrå de döda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Och togo fatt på dem, och satte dem i häktelse, till annan dagen; ty det var redo aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Men månge af dem, som orden hört hade, trodde; och vardt talet på männerna vid femtusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Så begaf det sig dagen derefter, att deras öfverste och äldste, och Skriftlärde i Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Och Hannas öfverste Prest, och Caiphas, och Johannes, och Alexander, och så månge som voro af öfversta Prestaslägtet, församlade sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Och hade dem fram för sig, och frågade dem: Af hvad magt, eller i hvad namn, hafven I detta gjort?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Petrus, full med den Helga Anda, sade till dem: I öfverste för folket, och äldste i Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Efter vi i dag blifve dömde för denna välgerningen på denna sjuka mannen, genom hvilka han är helbregda vorden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Så skall det eder allom vetterligit vara, och allo Israels folke, att genom Jesu Christi Nazareni Namn, den I korsfäst hafven, den Gud uppväckt hafver ifrå de döda, står nu denne helbregda för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Han är den stenen, som af eder, byggningsmännerna, förkastad är; och är vorden en hörnsten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Och i ingom androm är salighet; ty det är icke heller något annat Namn under himmelen menniskomen gifvet, i hvilko vi skole salige varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'När de sågo sådana allvarlighet i Petro och Johanne, och funno dock att de voro olärde och lekmän, förundrade de sig, och drogo känslo på dem, att de hade varit med Jesus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Och mannen sågo de ståndandes der när dem, som helbregda var gjorder; ty de kunde der intet emot säga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Utan bödo dem gå ut af Rådet, och handlade sedan emellan sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Sägande: Hvad skole vi göra åt dessa männerna? Ty ett uppenbart tecken är gjordt af dem, och är kunnigt allom dem som bo i Jerusalem; och vi kunne icke neka det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Men på det att det icke skall vidare utkomma ibland folket, vilje vi allvarliga förbjuda dem, att de härefter icke tala i detta Namnet för någro mennisko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Och de kallade dem, och bödo, att de ingalunda mer tala eller lära skulle i Jesu Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Då svarade Petrus och Johannes, och sade till dem: Om det är rättfärdigt för Gudi, att vi höre eder mer än Gud, derom mån I sjelfve döma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Ty vi kunne icke förtiga det vi sett och hört hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Då hotade de dem, och läto gå dem, intet finnandes huruledes de kunde pina dem, för folkets skull; ty alle prisade Gud för det som skedt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Ty mannen var öfver fyratio år, på hvilkom detta helbregda tecknet skedt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Sedan de läto dem gå, kommo de till sina, och kungjorde dem allt det de öfverste Presterna och äldste till dem sagt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Då de det hörde, upphofvo de endrägteliga sina röst till Gud, och sade: Herre, du äst Gud, som gjort hafver himmel och jord, hafvet, och allt det som deruti är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Du, som genom din tjenares Davids mun sagt hafver: Hvi hafva Hedningarna upprest sig, och folket tagit sig före det fåfängt är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Jorderikes Konungar trädde tillhopa, och Förstarna församlade sig ihop, emot Herran, och emot hans Christ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Sannerliga församlade sig emot din heliga Son, Jesum, den du smort hafver, både Herodes, och Pontius Pilatus, med Hedningarna och Israels folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Till att göra hvad din hand och råd tillförene beslutit hade, att ske skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Och nu, Herre, se till deras trug, och gif dina tjenare, att de med all tröst tala din ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Uträckandes dina hand dertill, att sundhet, och tecken, och under måga göras genom din heliga Sons Jesu Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Och då de bedit hade, rördes rummet, der de uti församlade voro; och de vordo alle fulle af dem Helga Anda, och talade Guds ord med tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Och uti hela hopen, som trodde, var ett hjerta och en själ; och ingen af dem sade något vara sitt af det han ägde; utan all ting voro dem menlig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Och Apostlarna båro med stora kraft vittnesbörd till Herrans Jesu Christi uppståndelse; och stor nåd var öfver dem alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Och ingen var heller ibland dem, som något fattades; ty så månge, som åkrar eller hus ägde, de sålde dem, och båro värdet för det som de sålt hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'Och lade fram för Apostlarnas fötter; och delades hvarjom och enom, efter som honom behof var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Men Joses, som ock kallades af Apostlarna Barnabas, det uttydt är, hugsvalelsens son, en Levit, bördig af Cypren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Han hade en åker, den sålde han; och bar fram värdet, och ladet för Apostlarnas fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Men en man benämnd Ananias, med Saphira sin hustru, sålde sina ägor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Och hade lagt afsides något af värdet, med sine hustrus vetskap; och en del bar han fram, och lade för Apostlarnas fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Då sade Petrus: Anania, hvi hafver Satanas uppfyllt ditt hjerta, att du skulle ljuga för dem Helga Anda, och undstinga somt af värdet för åkren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Du hade väl kunnat behållan, då du honom hade; och då han såld var, var han ock i ditt våld. Hvarföre hafver du sådant företagit i ditt hjerta? Du hafver icke ljugit för menniskor, utan för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Då Ananias hörde dessa orden, föll han ned, och gaf upp andan; och en stor räddhåge kom öfver alla dem som detta hörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Då stodo unge män upp; togo honom af vägen, båro honom bort, och begrofvon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Vid tre stunder derefter kom ock hans hustru, och visste icke hvad skedt var, och gick in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Då svarade Petrus henne: Säg mig, hafven I ock för så mycket sålt åkren? Då sade hon: Ja, hafve vi så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Då sade Petrus till henne: Hvarföre voren I öfverens, att I skullen fresta Herrans Anda? Si, deras fötter, som hafva begrafvit din man, äro för dörrene, och de skola ock straxt bära dig ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Och straxt föll hon ned för hans fötter, och gaf upp andan. Då gingo de unge män in, och funno henne död; och båro henne ut, och jordade henne när hennes man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Och en stor räddhåge kom öfver hela församlingena, och öfver alla dem som detta hörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Och igenom Apostlarnas händer gjordes mång tecken och under ibland folket; och de voro endrägteliga alle uti Salomons förhus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Men ingen annar djerfdes gifva sig intill dem; utan folket höll mycket af dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Och hopen växte mer till af dem som trodde Herranom, både män och qvinnor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Så att de utbåro på gatorna sjuka menniskor, och lade dem i sängar, och på bårar, att, då Petrus kom gångandes, måtte åtminstone hans skugge skygga på någon af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Och församlade sig en stor hop af nästa städerna till Jerusalem, och förde dit sjuka, och de som besatte voro med de orena andar; och de vordo alle helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Då stod den öfverste Presten upp, och alle de med honom voro, hvilke äro det parti, som kallas de Sadduceers; och vordo fulle med nit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'Och togo fatt på Apostlarna, och satte dem uti allmänneligit fängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Men Herrans Ängel lät dörrena upp på fångahuset om nattena, och hade dem ut, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Går, och står i templet, och säger folkena all de ord, som detta lifvet tillhöra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Då de detta hört hade, gingo de bittida om morgonen i templet, och begynte till att lära. Då kom den öfverste Presten, och de med honom voro, och kallade Rådet tillhopa, och alle de äldsta ibland Israels barn; och sände till fångahuset, att de skulle hemta dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Då tjenarena kommo, och funno dem icke i fångahuset, kommo de igen, och bådade dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Sägande: Fångahuset funne vi ju granneliga igenläst, och väktarena ståndande utanför dörrene; men då vi uppläste, funno vi der ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Då öfverste Presten, och templets föreståndare, och andre öfverste Presterna hörde detta talet, begynte de varda tvehågse om dem, hvad deraf varda ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Då kom en, och bådade dem: Si, de män, som I insatt haden i fångahuset, de äro i templet, stå och lära folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Då gick föreståndaren med tjenarena, och hade dem fram utan våld; ty de räddes för folket, att de skulle stena dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Och då de hade ledt dem dit, hade de dem fram för Rådet; och den öfverste Presten frågade dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Sägandes: Hafve vi icke en tid och annan budit eder, att I icke skullen lära i detta Namnet? Och si, I hafven uppfyllt Jerusalem med edar lärdom, och viljen draga öfver oss denna mansens blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Då svarade Petrus, och Apostlarna, och sade: Man måste mer lyda Gud, än menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Våra fäders Gud hafver uppväckt Jesum, den I dräpit hafven, och upphängt på träd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Den hafver Gud med sina högra hand upphöjt, för en Höfding och Frälsare, till att gifva Israel bättring och syndernas förlåtelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Och vi äro honom för vittne till det vi sågom; så ock den Helge Ande, den Gud gifvit hafver dem som honom lydaktige äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Då de detta hörde, skar det dem i hjertat, och de begynte rädsla, att de måtte dräpa dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Då stod en Pharisee upp i Rådet, benämnd Gamaliel, en lagkloker, den ibland allt folket mycket afhållen var, och bad att Apostlarna skulle som snarast gå afsides ut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Och sade till dem: I män af Israel, ser till hvad I gören med dessa män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'För dessa dagar hof Theudas sig upp, sägandes sig någon vara, honom föll en hop folk till, vid fyrahundrad; han vardt ihjälslagen, och alle de, som trodde honom, vordo förskingrade, och kommo till intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Efter honom hof Judas sig upp af Galileen, i de dagar då beskattningen skedde; han afvände mycket folk efter sig; han blef ock borto, och alle de som honom lydt hade, vordo förskingrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Och nu säger jag eder: Kommer intet vid dessa männerna, utan låter dem betämma; ty är detta råd eller verk af menniskor, så varder det väl omintet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Men är det af Gudi, så kunnen I icke Slå det neder, såframt I viljen icke finnas strida emot Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Då föllo de alle intill hans råd; och kallade Apostlarna, läto hudflänga dem, och bödo dem, att de icke skulle tala i Jesu Namn; och läto gå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Men de gingo med fröjd ifrå Rådet, att de voro värdige lida smälek för hans Namns skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Och höllo hvar dag uppå, utan återvändo, att lära och predika Evangelium om Jesu Christo, uti templet, och i all hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Uti de dagar, då hopen af Lärjungarna förökades, begynte de Greker knorra emot de Ebreer, derföre att deras enkor vordo föraktade uti den dagliga tjenstene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Då kallade de tolf hela hopen af Lärjungarna tillsamman, och sade: Det är icke tillbörligit att vi skole öfvergifva Guds ord, och akta hvad på bordet komma skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Söker fördenskull ut, käre bröder, sju män af eder, som godt rykte hafva, och fulle äro med dem Helga Anda och visdom; dem vilje vi befalla detta ärendet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Men vi vilje akta på bönen, och att förkunna Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Och det talet täcktes väl hela hopen; och de utvalde dertill Stephanus, som var en man full med tro och dem Helga Anda; och Philippus, och Prochorus, och Nicanor, och Timon, och Parmenas, och Nicolaus, som var en Proselyt af Antiochien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Dem hade de fram för Apostlarna. Och de bådo, och lade händer på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Och Guds ord förkofrade sig, och hopen af Lärjungarna var ganska stor i Jerusalem; och en stor hop af Presterna vordo trone lydaktige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Men Stephanus, som var full med tro och starkhet, gjorde under och stor tecken ibland folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Då reste sig någre upp af den Synagogon, som kallades de Libertiners, och de Cyreners, och de Alexandriners, och de Cilicers, och Asianers, och begynte till att disputera med Stephanus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Och de förmådde icke stå emot den visdom, och den Anda, som talade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Då undersatte de några män, som skulle säga: Vi hafve hört honom säga hädisk ord emot Moses, och emot Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Och de eggade folket, och de äldsta och de Skriftlärda; och gingo till, och togo fatt på honom, och hade honom inför Rådet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Och drogo fram falsk vittne, de der sade: Denne mannen vänder icke igen till att tala hädisk ord emot detta helga rummet, och emot lagen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Ty vi hörde honom säga: Jesus af Nazareth skall kullslå detta rummet, och skall förvandla de stadgar, som Moses hafver fått oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Och alle de på Rådet såto, sågo på honom, och sågo hans ansigte lika visst som en Ängels ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Då sade den öfverste Presten: Hafver detta sig ock så?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Då sade han: I män, bröder och fader, hörer härtill. Härlighetenes Gud syntes vårom fader Abraham, medan han var i Mesopotamien, förr än han bodde i Haran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'Och sade till honom: Gack utu ditt land, och ifrå dine slägt; och kom i det land, som jag vill visa dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Då for han ut af de Chaldeers land, och bodde i Haran; och dädan, då hans fader var död, lät han föra honom hit i detta land, der I nu uti bon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Och gaf honom ingen arfvedel härinne, icke en fot bredt. Och han lofvade honom, att han skulle honom det gifva till att besitta, och hans säd efter honom, den tid han ännu inga barn hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Men Gud sade alltså: Din säd skall varda främmande, uti främmande land; och de skola hafva dem under sig i träldom, och fara illa med dem, i fyrahundrade år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Och det folk, som de tjena skola, vill jag döma, sade Gud; och sedan skola de gå derut, och skola tjena mig i detta rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Och han gaf honom omskärelsens förbund; och han födde Isaac, och omskar honom på åttonde dagen; och Isaac födde Jacob; och Jacob födde de tolf Patriarcher.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Och de Patriarcher sålde Joseph, för afunds skull, in uti Egypten; och Gud var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Och han halp honom utur all hans bedröfvelse, och gaf honom nåd och visdom inför Pharao, Konungen i Egypten; och han satte honom till höfvitsman öfver Egypten, och öfver allt sitt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Så kom hunger öfver hela Egypti land och Canaan, och stor tvång; och våre fäder funno ingen födo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Men då Jacob hörde, att uti Egypten var korn, sände han våra fäder första gången ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Och då han åter sände dem ut, vardt Joseph känder af sina bröder; och Pharao vardt undervist om Josephs slägt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Då sände Joseph, och kallade sin fader Jacob till sig, och all sin slägt, till fem och sjutio själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Och Jacob for ned till Egypten; och blef död, han och våre fäder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Och vordo förde till Sichem, och lades i griften, som Abraham köpt hade, för penningar, af Hemors barn, som var Sichems (son).');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Då nu tiden tillstundade om löftet, om hvilket Gud hade svorit Abraham, växte folket, och vardt förökadt uti Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Tilldess der uppkom en annar Konung, den intet visste af Joseph.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Han gick vårt slägte efter med list, och for illa med våra fäder, så att de utkasta måste sin barn, att de icke skulle blifva lefvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Samma tiden vardt Moses född, och han var Gudi täcker; och vardt fostrader i sins faders hus, i tre månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Då han sedan utkastad vardt, tog Pharaos dotter honom upp, och födde honom upp sig för en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Och vardt Moses lärd i all den visdom, som de Egyptier hade; och var mägtig i ord och gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Men då han vardt fyratio år gammal, kom honom i hjertat, att han ville bese sina bröder, Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Och då han såg, att enom af dem skedde orätt, halp han honom, och hämnade hans skada, som orätt skedde, och slog den Egyptien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Och han mente att hans bröder skulle förstå, att Gud, genom hans hand, skulle frälsa dem; men de förstodo det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Och dagen derefter syntes han ibland dem, der de trätte tillhopa; och ville förlika dem, sägandes: I män, I ären bröder hvi gören I hvarannan orätt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Men den som orätt gjorde sinom nästa, han stötte honom bort, sägandes: Ho hafver satt dig till höfvitsman och domare öfver oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Månn du vilja slå mig ihjäl, såsom du slog den Egyptien i går?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Då flydde Moses, för detta talets skull, och vardt en främling uti det landet Madian; der han två söner födde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Och efter fyratio år syntes honom Herrans Ängel i öknene, vid det berget Sina, uti en brinnande låga, utu buskanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Då Moses det såg, förundrade han sig om den synena; men då han gick fram, och skulle skåda, skedde Herrans röst till honom:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Jag är dina fäders Gud, Abrahams Gud, Isaacs Gud, och Jacobs Gud. Då vardt Moses förfärad, och torde icke se dit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Då sade Herren till honom: Lös dina skor af dina fötter; ty det rum, som du står uppå, är ett heligt land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Jag hafver väl sett mins folks tvång, som är uti Egypten, och hafver hört deras suckan, och är nederstigen till att frälsa dem; så kom nu hit, jag vill sända dig uti Egypten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Denna Mosen, som de försakade, sägande: Ho gjorde dig till höfvitsman och domare? honom (säger jag) hafver Gud sändt för en höfvitsman och förlossare, genom Ängelens hand, som honom syntes i buskanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Han förde dem ut, görandes under och tecken uti Egypten, och uti röda hafvet, och uti öknene, i fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Denne är Moses, som sade till Israels barn: En Prophet skall Herren, edar Gud, uppväcka eder af edra bröder, såsom mig; honom skolen I höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Denne var den som uti församlingen, i öknene, var med Ängelen, som talade med honom på Sina berg, och med våra fäder; han undfick lifsens ord, till att gifva oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Hvilkom edre fäder ville icke lydaktige vara; utan drefvo honom ifrå sig, och vände sig om med sitt hjerta till Egypten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Sägande till Aaron: Gör oss gudar, som gå för oss; ty vi vete icke hvad denna Mosi vederfaret är, som oss utfört hafver af Egypti land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Och gjorde de en kalf, i de dagar, och offrade offer till afgudar, och fröjdade sig öfver sina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Då vände Gud sig om, och gaf dem der till, att de dyrkade himmelens härskap; såsom skrifvet står i Propheternas bok: I Israels hus, hafven I ock i de fyratio år offrat mig i öknene offer och fä?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Och I upptogen Molochs tabernakel, och edars Guds Remphans stjerno; de beläte, som I gjort haden, till att tillbedja dem; och jag skall bortkasta eder utom Babylonien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Våre fader hade vittnesbördsens tabernakel uti öknene; såsom han dem förskickat hade, sägandes till Mosen, att han skulle göra det efter den eftersyn, som han sett hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Hvilket ock våre fäder anammade, och förde det med Josua uti det land, som Hedningarna innehade, hvilka Gud utdref för våra fäders ansigte, intill Davids tid;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Hvilken fann nåd för Gudi, och bad, att han måtte finna ett tabernakel till Jacobs Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Men Salomon byggde honom ett hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Dock den Aldrahögste bor icke uti de tempel, som med händer gjord äro, såsom Propheten säger:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Himmelen är mitt säte, och jorden är min fotapall. Hvad hus viljen I då bygga mig, säger Herren; eller hvad rum är till mina hvilo?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Hafver icke min hand gjort detta alltsammans?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'I hårdnackade, och oomskorne i hjertat och öron, I stån alltid emot den Helga Anda; såsom edra föder, sammalunda ock I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Hvilken af Propheterna hafva icke edra fäder förföljt? De hafva ihjälslagit dem som förkunnade dens Rättfärdigas tillkommelse, hvilkens förrädare och dråpare I nu voren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'I, som undfingen lagen genom Änglaskickelse; och höllen den intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Då de detta hörde, skar det dem i deras hjerta, och beto samman tänderna öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Men han, full af dem Helga Anda, såg upp i himmelen, och fick se Guds härlighet, och Jesum stå på Guds högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'Och han sade: Si, jag ser himmelen öppen, och menniskones Son stå på Guds högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Då ropade de med höga röst, och höllo sin öron till, och stormade alle tillika till honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Och drefvo honom utu staden, och stenade honom. Och vittnen lade sin kläder af vid en ung mans fötter, som het Saulus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Och de stenade Stephanum; och han åkallade, och sade: Herre Jesu, anamma min anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Och så böjde han sin knä neder, och ropade med höga röst: Herre, räkna dem icke denna synden. Och när han hade det sagt, af somnade han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Och Saulus hade samtyckt hans död. Men på samma tid vardt en stor förföljelse emot den församling, som var i Jerusalem; och de vordo alle förströdde omkring i Judee land, och i Samarien, förutan Apostlarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Och någre gudfruktige män skötte Stephanum, och hade stor gråt öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Men Saulus tog till att föröda församlingena; gick hit och dit i husen, och drog fram män och qvinnor, och lät sätta dem i fängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Men de som förströdde voro, foro omkring och predikade ordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Och Philippus kom ned uti en stad i Samarien, och predikade för dem om Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Men folket gåfvo akt uppå hvad Philippus sade; hörandes endrägteliga, och seendes de tecken, som han gjorde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Ty de orene andar foro ut af mångom, som med dem besatte voro, ropande med höga röst; och månge borttagne och ofärdige vordo helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Och i den staden vardt stor glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Så var der en man, benämnd Simon, som tillförene uti den staden plägade bruka trolldom, och hade förvillt det Samaritiska folket, sägandes sig vara mycket myndigan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Till honom höllo sig alle, både små och store, sägande: Denne är Guds kraft, hvilken stor är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Men de höllo sig derföre till honom, att han i lång tid hade förvillt dem med sin trolldom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'När de nu trodde Philippo, som predikade om Guds rike, och om Jesu Christi Namn, vordo der både män och qvinnor döpte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Då trodde ock Simon med, och när han döpt var, höll han sig intill Philippum; och då han såg sådana tecken och krafter ske, förundrade han sig storliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Då nu Apostlarna, som i Jerusalem voro, fingo höra att Samarien hade anammat Guds ord, sände de till dem Petrum och Johannem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'När de kommo derned, bådo de för dem, att de skulle få den Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Ty han var icke än då fallen på någondera; utan de voro allenast döpte i Herrans Jesu Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Då lade de händer på dem, och de fingo den Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'När Simon såg, att den Helge Ande gafs dermed, att Apostlarna lade händer på dem, böd han dem penningar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Sägandes: Gifver ock mig den magten, att hvem som helst jag lägger händer uppå, han får den Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Då sade Petrus till honom: Det du fördömd vorde med dina penningar; efter du menar, att Guds gåfva kan fås för penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Du hafver hvarken del eller lott i detta ordet; ty ditt hjerta är icke rätt för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Derföre bättra dig af denna dine ondsko, och bed Gud, att dig dins hjertas tankar måga förlåtna varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Ty jag ser, att du äst full med bitter galla, och bebunden i vrånghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Då svarade Simon, och sade: Beder I Herran för mig, att mig intet öfvergår af det I saden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Och sedan de hade betygat, och talat Herrans ord, vände de om igen åt Jerusalem; och predikade Evangelium i många städer i Samarien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Men Herrans Ängel talade till Philippum, och sade: Statt upp, och gack söderut, den vägen, som löper nederåt ifrå Jerusalem, till Gaza, som öde är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Så stod han upp, och gick. Och si, en Ethiopisk man, en kamererare, och väldig när Drottning Candaces uti Ethiopien, hvilken hon hade satt öfver alla sina håfvor; han var kommen till Jerusalem, der att tillbedja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'Och for hem igen, satt på sin vagn, och las den Propheten Esaias.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Då sade Anden till Philippus: Gack fram, och gif dig intill denna vagnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Då lopp Philippus fram, och hörde honom läsa Propheten Esaias, och sade: Förstår du ock hvad du läs?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Då sade han: Huru skulle jag förståt, utan mig någor vistet? Och bad Philippus, att han skulle uppstiga, och sitta när sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Och det han las i Skriftene var detta: Såsom ett får vardt han ledder till att slagtas, och såsom ett lamb är tyst för honom, som klipper det, så hafver han icke öppnat sin mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'I hans förnedring är hans dom borttagen; men ho kan uttala hans lifslängd? Ty hans lif är borttaget af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Då svarade kamereraren Philippo, och sade: Jag beder dig, om hvem hafver Propheten detta sagt, om sig, eller om någon annan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Då öppnade Philippus sin mun, och begynte af denna Skriftene predika Evangelium för honom om Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Och vid de foro framåt vägen, kommo de till ett vatten; och kamereraren sade: Si, vattnet; hvad hindrar, att jag icke döpes?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Då sade Philippus: Om du tror af allt hjerta, så må det väl ske. Han svarade, och sade: Jag tror Jesum Christum vara Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Och han lät hålla vagnen; och de stego ned i vattnet, både Philippus och kamereraren; och han döpte honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Och när de gingo upp utu vattnet, tog Herrans Ande Philippum bort, och kamereraren såg honom intet sedan; utan for sin väg, och var glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Och Philippus vardt funnen i Azot; och vandrade omkring, och predikade Evangelium i alla städer, tilldess han kom till Cesarea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Men Saulus hade ännu i sinnet trug och slag emot Herrans Lärjungar; och gick till öfversta Presten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'Och han beddes af honom bref till de Synagogor i Damasco, att hvem han finna kunde af denna vägen, män eller qvinnor, dem skulle han föra bundna till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Och vid han var i vägen, och nalkades intill Damascum, då kringsken honom hasteliga ett sken af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Och han föll ned på jordena, och hörde ena röst, sägandes till sig: Saul, Saul, hvi förföljer du mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Då sade han: Ho äst du, Herre? Sade Herren: Jag är Jesus, den du förföljer; dig är svårt att spjerna emot udden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Då skalf han, och bäfvade, och sade: Herre, hvad vill du jag skall göra? Sade Herren till honom: Statt upp, och gack in i staden, och der skall dig varda sagdt, hvad du göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Och de män, som voro i sällskap med honom, stodo förskräckte, hörandes väl röstena, och dock likväl sågo de ingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Då stod Saulus upp af jordene, och upplät sin ögon, och kunde dock ingen se; utan de togo honom vid handena, och ledde honom in i Damascum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Och han var i tre dagar, så att han såg intet, och intet åt, ej heller drack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Så var uti Damasco en Lärjunge, benämnd Ananias; till honom sade Herren uti en syn: Anania. Och han sade: Herre, här är jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Och Herren sade till honom: Statt upp, och gack in på den gaton, som kallas den Rätta, och sök uti Juda hus en som heter Saulus, af Tarsen; ty si, han beder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'Och han hafver sett i synen en man, som heter Ananias, inkomma, och lägga handena på sig, att han skulle få sin syn igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Då svarade Ananias: Herre, jag hafver hört af mångom om denna mannen, huru mycket ondt han gjort hafver dinom heligom uti Jerusalem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Och här hafver han nu magt af de öfversta Presterna, till att binda alla de som åkalla ditt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Då sade Herren till honom: Gack; ty han är mig ett utkoradt redskap, att han skall bära mitt Namn inför Hedningar, och för Konungar, och för Israels barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Och jag skall visa honom, huru mycket han lida skall för mitt Namns skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Och Ananias gick åstad, och kom i huset, lade händer på honom, och sade: Saul, käre broder, Herren hafver sändt mig, Jesus, som syntes dig i vägen som du kom, att du skall få din syn igen, och uppfyllas med dem Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Och straxt föllo af hans ögon såsom fjäll, och han fick sin syn, och stod upp, och lät döpa sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Och tog mat till sig, och förstärkte sig. Och var Saulus med de Lärjungar, som i Damasco voro, i några dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Och straxt begynte han i Synagogorna predika Christum, att han var Guds Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Och förundrade sig alle, som honom hörde, och sade: Är icke denne, som i Jerusalem förstörde alla de som åkalla detta Namnet; och hit är kommen deruppå, att han skulle föra dem bundna till öfversta Presterna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Men Saulus förkofrade sig ju mer och mer; och öfvervann de Judar, som bodde i Damasco, bevisandes att denne var Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Efter många dagar gingo Judarna till råds emellan sig, att de skulle dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Men Saulus vardt förvarad om deras försåt; och de vaktade i portarna dag och natt, att de skulle få dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Men Lärjungarna togo honom om natten, och släppte honom öfver muren, och läto honom neder uti en korg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'När Saulus kom till Jerusalem, böd han till att gifva sig intill Lärjungarna; och de voro alle rädde för honom, icke troendes att han var vorden Lärjunge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Men Barnabas tog honom till sig, och hade honom bort till Apostlarna; och förtäljde dem, huru han hade sett Herran i vägen, och att han hade talat med honom; och huru han hade manliga bevist sig, i Jesu Namn, uti Damasco.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Och var han sedan med dem i Jerusalem, gick ut och in, och talade trösteliga i Herrans Jesu Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Och talade och disputerade emot de Greker. Men de sökte efter att dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Då bröderna det förnummo, fordrade de honom intill Cesareen, och läto honom fara till Tarsum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Så hade då nu församlingarna frid öfver hela Judeen, och Galileen, och Samarien, och förkofrade sig, vandrandes i Herrans räddhåga, och uppfylldes med den Helga Andas tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Så hände sig att, då Petrus vandrade allestäds omkring, kom han ock till de heliga, som bodde i Lydda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Der fann han en man, benämnd Eneas, som nu i åtta år legat hade på säng, och han var borttagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Och Petrus sade till honom: Enea, bote dig Jesus Christus; statt upp, och bädda åt dig sjelfvom; och straxt stod han upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Och honom sågo alle, som bodde i Lydda, och i Sarona, och vordo omvände till Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Men i Joppe var en lärjunginna, benämnd Tabitha; det uttydes Dorcas, det är, en rå; hon var full med goda gerningar, och almosor, som hon gaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Så hände sig i de dagar, att hon vardt sjuk, och blef död; och de tvådde henne, och lade henne i salen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Och efter Lydda var icke långt ifrå Joppe, och Lärjungarna hörde att Petrus var der, sände de två män till honom, och bådo, att han ville göra sig det omak och komma till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Då stod Petrus upp, och kom till dem. Och då han var kommen, hade de honom in i salen; och kringom honom stodo alla enkor gråtande, och viste honom kjortlar och kläder, som Dorcas hade gjort dem, medan hon var med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Då dref Petrus dem alla ut, och föll ned på sin knä, och bad; och vände sig om till kroppen, och sade: Tabitha, statt upp. Då öppnade hon sin ögon; och som hon fick se Petrum, satte hon sig upp igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Och han räckte henne handena, och reste henne upp; och kallade de heliga, och enkorna, och antvardade dem henne lefvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Och det vardt kunnigt öfver hela Joppe; och månge begynte tro på Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Så begaf sig, att han blef i många dagar i Joppe, när en som het Simon, som var en lädermakare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Uti Cesareen var en man, benämnd Cornelius, en höfvitsman af den skaran, som het den Valske;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Gudelig och gudfruktig med allt sitt hus, gifvandes folkena mycken almoso, och bedjandes Gud alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Han såg uti en syn uppenbarliga, vid nionde timman på dagen, Guds Ängel inkomma till sig, och säga till sig: Corneli.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Då såg han uppå honom, och vardt förfärad, och sade: Hvad äret. Herre? Då sade han till honom: Dina böner och dina almosor äro uppkomne i åminnelse för Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Så sänd nu några män till Joppe, och kalla till dig Simon, som ock kallas Petrus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Han gästar när en, som heter Simon lädermakare, och hans hus är vid hafvet; den skall säga dig hvad du göra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Och då Ängelen, som talade med Cornelio, var bortgången, kallade han till sig två sina tjenare, och en gudfruktig krigsknekt, af dem som togo vara på honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'Och förtäljde dem allt detta, och sände dem till Joppe.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'På den andra dagen, då de voro på vägen, och begynte lida intill staden, gick Petrus upp i salen, till att bedja, vid sjette timman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Och som han vardt hungrig, ville han få sig mat; och vid de tillredde, kom en dvale öfver honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Och han såg himmelen öppen, och nederkomma till sig ett fat, såsom ett stort linnet kläde, tillhopabundet i alla fyra hörnen, nederlåtet på jorden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Uti hvilko voro allahanda fyrafött djur på jorden, och vilddjur, och de som krypande äro, och de som flygande äro under himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Och en röst skedde till honom: Statt upp, Petre; slagta, och ät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Då sade Petrus: Ingalunda, Herre; ty jag hafver aldrig ätit något menligit, eller orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Och rösten sade andra reson till honom: Det Gud hafver rent gjort, det behöfver du icke kalla menligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Och detta skedde ock så tredje reson; och vardt fatet sedan igen upptaget i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Och då Petrus begynte bekymrad varda vid sig sjelf, hvad syn detta skulle vara, som han sett hade; si, männerna, som sände voro af Cornelio, voro för dörrene, och frågade efter Simons hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Och kallade de en ut, och sporde, om Simon, som ock kallades Petrus, var der till herberge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Och vid Petrus tänkte på synena, sade Anden till honom: Si, der äro tre män, som söka efter dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Så statt nu upp, och stig ned, och gack med dem, intet tviflandes; ty jag hafver sändt dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Så steg Petrus ned till männerna, som sände voro af Cornelio till honom, och sade: Si, jag är den som I söken; för hvad sak ären I komne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Svarade de: Cornelius, den höfvitsmannen, som är en rättfärdig och gudfruktig man, och hafver vittnesbörd af allt Judiska folket, hafver fått befallning af en helig Ängel, att han skulle kalla dig uti sitt hus, och höra ord af dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Då kallade han dem in, och behöll dom der till herberges. Dagen derefter for Petrus med dem; och några bröder af Joppe följde honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Och den andra dagen kommo de in uti Cesareen; och Cornelius förbidde dem, och hade kallat tillhopa sina fränder, och sina bästa vänner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Och då dertill kom, att Petrus skulle ingå, gick Cornelius emot honom, och föll ned för hans fötter, och tillbad honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Men Petrus reste honom upp, sägandes: Statt upp; jag är ock en menniska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Och som han hade talat med honom, gick han in, och fann der många, som församlade voro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Och sade till dem: I veten, att icke plägar lofligit vara, att en Judisk man må umgå eller komma till någon främmande; men Gud hafver mig undervist, att jag inga mennisko skall räkna menliga eller orena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Derföre är jag ock otvifvelakteligen kommen, sedan jag vardt kallad af eder. Så frågar jag eder nu, för hvad sak hafven I kallat mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Då sade Cornelius: Fyra dagar sedan fastade jag intill denna stunden, och bad i mitt hus vid nionde timman; och si, en man stod för mig i skinande kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'Och sade: Corneli, din bön är hörd, och Gud hafver tänkt uppå dina almosor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Så sänd nu några till Joppe, och kalla till dig Simon, som ock kallas Petrus; han gästar uti Simons lädermakares hus, utmed hafvet; när han kommer, skall han tala med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Så sände jag ock straxt till dig, och du gjorde väl att du kom. Så äre vi nu här alle för Gudi, till att höra allt det dig af Gudi befaldt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Då öppnade Petrus sin mun, och sade: Nu förnimmer jag i sanning, att när Gudi är intet anseende till personen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Utan i allahanda folk den som fruktar honom, och gör rättfärdigheten, han är honom täck.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'I veten väl om det talet, som Gud utsändt hafver till Israels barn, bebådandes frid genom Jesum Christum, hvilken är Herre öfver allt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Om hvilket tal beryktadt är öfver hela Judiska landet, och först begynt af Galileen, efter den döpelsen som Johannes predikade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Huru Gud hafver smort Jesum af Nazareth med den Helga Anda, och kraft; hvilken vandrade omkring, görandes väl, och hjelpandes allom som besatte voro af djefvulen; ty Gud var med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Och vi äre vittne till allt det han gjort hafver, i Judiska landet, och i Jerusalem; den dråpo de, och hängde på träd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Denna hafver nu Gud uppväckt på tredje dagen, och låtit honom varda uppenbar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Icke allo folkena, utan oss, som Gud tillförene till vittne utvalt hade; vi, som åtom och druckom med honom, sedan han var uppstånden ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Och han böd oss, att vi skulle predika för folket, och vittna, att han är den som af Gudi tillskickad är, till en domare öfver lefvande och döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Honom bära alle Propheterna vittnesbörd, att hvar och en som tror på honom, han skall få syndernas förlåtelse genom hans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Vid Petrus ännu talade dessa orden, föll den Helge Ande på alla dem som talet hörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Och de trogne af omskärelsen, som med Petro komne voro, förundrade sig att den Helga Andas gåfva vardt ock utgjuten öfver Hedningarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Ty de hörde dem tala med tungomål, och prisa Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Då svarade Petrus: Kan någor förbjuda, att desse icke döpas i vatten, som fått hafva den Helga Anda, så väl som vi?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Och så lät han döpa dem i Herrans Namn. Och de bådo honom, att han skulle blifva när dem i några dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Då fingo Apostlarna, och de bröder som med dem voro i Judeen, höra att ock Hedningarne anammade Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Och då Petrus kom upp till Jerusalem, begynte de som voro af omskärelsen kifva med honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Sägande: Du hafver ingångit till de män, som förhud hafva, och hafver ätit med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Då begynte Petrus förtälja dem af begynnelsen, det ena med det andra, sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Jag var i Joppe stad bedjandes; då kom jag uti en dvala, och såg ena syn; nämliga ett fat nederkomma, såsom ett stort linnet kläde, fyrahörnadt, nederlåtet af himmelen; och det kom intill mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Och när jag gaf der akt uppå med ögonen, vardt jag varse, och fick se fyrafött djur på jordene, och vilddjur, och de der krypande äro, och de der flygande äro under himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Och hörde en röst, sägandes till mig: Statt upp, Petre; slagta, och ät.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Och jag sade: Ingalunda, Herre; ty intet menligit eller orent hafver någon tid kommit i min mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Svarade mig åter rösten af himmelen: Det Gud hafver rent gjort, det måste du icke räkna menligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Och det skedde tre resor; och vardt allt åter upptaget i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Och si, i det samma voro tre män för huset, der jag uti var, de der sände voro till mig af Cesareen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Och sade Anden till mig, att jag skulle gå med dem, och tvifla intet. Då följde mig ock desse sex bröderna, och vi kommo uti mansens hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Och han förtäljde för oss, att han hade sett en Ängel i sitt hus, den der för honom stod, och sade till honom: Sänd ut några män till Joppe, och kalla till dig Simon, som ock kallas Petrus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Den skall säga dig ord, hvarmed du skall frälst varda, och allt ditt hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'När jag hade begynt mitt tal, föll den Helge Ande ned på dem, såsom han ock i förstone nederföll på oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Så kom mig ihåg det Herren sagt hade: Johannes hade döpt eder i vatten; men I skolen döpte varda i dem Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Efter nu Gud hafver gifvit dem lika gåfvo med oss, som troddom på Herran Jesum Christum; ho är jag, att jag kunde stå emot Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'När de detta hörde, tigde de, och prisade Gud, sägande: Så hafver ock nu Gud gifvit Hedningomen bättring till lifs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Och de som förströdde voro, för den bedröfvelsens skull, som påkommen var för Stephani skull, vandrade omkring allt intill Phenicen, och Cypren, och Antiochien, talande ordet för ingom, utan allenast för Judomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Och voro någre män ibland dem, af Cypren och Cyrenen; när de kommo till Antiochien, talade de ock till de Greker, predikandes Herran Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Och Herrans hand var med dem; och en stor hop togo vid trona, och omvände sig till Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Så kommo då tidende härom för den församling, som var i Jerusalem; då sände de Barnabam, att han skulle fara till Antiochien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'När han der kom, och fick se Guds nåd, vardt han glad; och förmanade dem alla, att de af hjertat skulle faste blifva, och hålla sig intill Herran;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Ty han var en god man, och full med den Helga Anda, och tro. Och en stor hop med folk förökades intill Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Sedan for Barnabas till Tarsen, och ville uppsöka Saulum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Då han honom fann, tog han honom med sig till Antiochien. Och så begaf det sig, att de ett helt år omgingo med den församlingene, och lärde mycket folk; och att Lärjungarna begynte först der i Antiochien kallas Christne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Och uti de dagar kommo någre Propheter till med af Jerusalem till Antiochien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Och en af dem, benämnd Agabus, stod upp, och underviste dem genom Andan, att en stor hunger komma skulle öfver hela verldena; hvilken som skedde under den Kejsaren Claudius.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Då satte Lärjungarna sig före, efter som hvar förmådde, att sända något till hjelp till de bröder, som bodde i Judeen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Hvilket de ock gjorde; och sände till de äldsta, genom Barnabe och Sauli hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'På samma tid tog Konung Herodes fatt på några af församlingene, till att pina dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Och drap han Jacobum, Johannis broder, med svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Och då han såg, att det behagade Judomen väl, tog han ock fatt på Petrus; och det var om Sötebrödsdagarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Då han nu fick fatt på honom, satte han honom i fängelse, antvardandes honom fyra qvarter krigsknektar, till att förvaran; aktandes efter Påskana hafva honom ut för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Och Petrus förvarades i fängelset. Men församlingen hade bön till Gud för honom, utan återvändo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'När nu Herodes ville haft honom före, i den samma nattene sof Petrus emellan två krigsknektar, bunden med två kedjor; och vaktarena voro för dörrene, och togo vara på fängelset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Och si, Herrans Ängel stod för honom, och ett sken lyste i huset, och stötte Petrum på sidona, och väckte honom upp, sägandes: Statt upp snarliga. Och kedjorna föllo utaf hans händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Och sade Ängelen till honom: Bind om dig, och tag dina skor uppå; han ock så gjorde. Och han sade till honom: Tag din kjortel uppå, och följ mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Och så gick han ut, och följde honom; och visste icke, att det var sant, som skedde af Ängelen, utan mente att han hade sett en syn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Och de gingo fram genom den första och andra vakten, och kommo till jernporten, som drog åt staden; den öppnades dem af sig sjelf; och de gingo derut, dragandes framåt en gato långt; och i det samma kom Ängelen ifrå honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Då Petrus kom till sig igen, sade han: Nu vet jag förvisso, att Herren hafver sändt sin Ängel, och tagit mig utu Herodis hand, och ifrån all Judiska folkens åstundan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Och då han besinnade sig, kom han till Marie hus, som var Johannis moder, den ock kallades Marcus; och der voro månge församlade, och bådo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Då Petrus klappade på porten, gick en piga ut att höra ho der var, benämnd Rode.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Och då hon kände Petri röst, lät hon icke upp porten, för glädjes skull; utan lopp in, och bådade dem att Petrus stod för porten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Då sade de till henne: Du äst icke vid din sinne. Då stod hon fast derpå, att det var så. Då sade de: Hans Ängel äret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Men Petrus höll uppå att klappa. När de då uppläto, fingo de se honom, och förundrade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Då tecknade han dem med handene, att de skulle tiga; och förtäljde dem, huru Herren hade frälst honom utu fängelset; och han sade: Görer Jacobo och bröderna båd härom. Sedan gick han derut, och drog bort på en annan stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Men då dager vardt, var icke litet bekymmer ibland krigsknektarna, hvad af Petro skulle vordit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Och Herodes hade båd efter honom, och fann honom icke; ty lät han ransaka vakterna, och hafva dem bort; och for ned af Judeen till Cesareen, och dvaldes der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Och Herodes var illa tillfrids med dem af Tyro och Sidon. Men de kommo endrägteliga till honom, och talade vid Blastum, som Konungens kamererare var, och begärade frid; ty deras landsände hade sin näring af Konungens land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Då bestämde Herodes en dag, och klädde sig uti Konungslig kläder, och satte sig på domstolen, och hade ett tal till dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Och folket ropade: Guds röst är detta, och icke menniskors.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Och straxt slog honom Herrans Ängel, derföre att han icke gaf Gudi ärona; och han vardt uppfräten af matkar, och gaf upp andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Men Guds ord växte och förökades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Men Barnabas och Paulus foro igen till Jerusalem, och fingo den undsättning ifrå sig; och togo med sig Johannes, som ock kallades Marcus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Och voro uti den församling i Antiochien någre Propheter och Lärare; ibland dem var Barnabas, och Simeon, som kallas Niger; och Lucius af Cyrenen, och Manahen, som var uppfödd med Herode Tetrarcha; och Saulus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'När de samme tjente Herranom, och fastade, sade den Helge Ande: Skiljer mig ut Barnabam och Saulum, till det verk, som jag hafver kallat dem till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Då fastade de, och bådo, och lade händer på dem, och läto dem fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Och som de sände voro af den Helga Anda, drogo de till Seleuciam; och seglade dädan intill Cypren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Och då de voro i den staden Salamine, predikade de Guds ord uti Judarnas Synagogor; och Johannem hade de för en tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Och då de öfverfarit hade öna allt intill (den staden) Paphum, funno de der en trollkarl, som var en falsk Prophet, en Judo som het BarJesus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Han var med landshöfdinganom, som het Sergius Paulus, hvilken en förståndig man var. Han kallade till sig Barnabam och Saulum, och begärade höra Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Men trollkarlen Elymas, ty hans namn uttydes så, stod dem emot, och ville vända landshöfdingan ifrå trone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Men Saulus, den ock Paulus het, full med den Helga Anda, såg på honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Och han sade: O du djefvulsbarn, full med allt bedrägeri, och med alla list, fiende till allt det rättfärdigt är, du låter icke af att förvända Herrans rätta vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Och nu, si, Herrans hand är öfver dig, och du skall varda blind, och icke se solena en tid långt. Och straxt föll på honom töcken och mörker; och han gick omkring, sökandes efter att någor måtte tågan vid handena, och ledan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Då landshöfdingen såg hvad skedt var, trodde han, och förundrade sig öfver Herrans lärdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Då Paulus, och de med honom voro, foro ifrå Papho, kommo de till Pergen i Pamphylien; och Johannes skiljdes ifrå dem, och for igen till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Men de drogo genom de landsändar ifrå Pergen, och kommo till Antiochien, i det landet Pisidien; och gingo in uti Synagogon, om Sabbathsdagen, och satte sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Och sedan lagen var läsen och Propheterna, sände de öfverste af Synagogon till dem, sägande: I män och bröder, hafven I något att tala till folkets förmanelse, så taler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Då stod Paulus upp, och gaf tecken med handene, att de skulle vara tyste, och sade: I män af Israel, och I som frukten Gud, hörer härtill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Detta folks Israels Gud hafver utvalt våra fäder, och upphöjt folket, då de främlingar voro uti Egypti land, och fört dem derut med högom arm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Och vid fyratio år långt led han deras seder uti öknen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Och nederlade sjuhanda folk uti Canaans land; och skifte deras land emellan dem med lott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Och sedan, vid femtio och fyrahundrade år, gaf han dem domare, intill Propheten Samuel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Och derefter begärade de Konung; och Gud gaf dem Saul, Kis son, en man af BenJamins slägte, i fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Sedan satte han honom af, och uppsatte öfver dem David till en Konung, hvilkom han gaf vittnesbörd, och sade: Jag hafver funnit David, Jesse son, en man efter mitt hjerta; han skall göra all min vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Af hans säd hafver Gud upptagit Israels Frälsare, Jesum, efter som han lofvat hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Såsom Johannes predikade Israels folke döpelse till bättring, förr än han begynte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Och när Johannes hade uppfyllt sitt lopp, sade han: Den I hållen mig före, den är jag icke; men si, han kommer efter mig, hvilkens skor jag icke värdig är draga af hans fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'I män och bröder, Abrahams slägtes barn, och de som ibland eder frukta Gud, eder är denna salighetenes ord sändt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Ty de som bodde i Jerusalem, och deras öfverste, efter de icke kände honom, eller Propheternas röster som alla Sabbather läsas, uppfyllde de dem med sin dom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Och ändock de ingen dödssak funno med honom, beddes de likväl af Pilato, att han skulle dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Och när de hade fullbordat allt det som skrifvet var om honom, togo de honom neder af trät, och lade honom i grafvena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Men Gud hafver uppväckt honom ifrå de döda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Och han hafver varit sedder i många dagar af dem, som med honom uppkomne voro ifrå Galileen till Jerusalem, hvilke hans vittne äro till folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Och vi förkunnom eder, att det löfte som till fäderna gjordt var, det hafver Gud fullkomnat oss, deras barnom, i det han uppväckt hafver Jesum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Såsom i andra Psalmen skrifvet är: Du äst min Son, i dag hafver jag födt dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Men att han uppväckte honom ifrå de döda, så att han icke skall mer igenkomma till förgängelighet, sade han så: Den nåd, som David lofvad är, skall jag eder troliga hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Derföre säger han ock annorstäds: Du skall icke tillstädja, att din helige skall se förgängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Ty då David i sinom tid hade tjent Guds vilja, afsomnade han, och vardt lagd till sina fäder, och såg förgängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Men den som Gud uppväckt hafver han såg ingen förgängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Så skall eder nu vetterligit vara, I män och bröder, att genom honom varder eder förkunnad syndernas förlåtelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'Och af allo der I icke med kunden rättfärdige varda, uti Mose lag; men hvilken som tror på denna, han varder rättfärdigad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Så ser nu till, att eder icke öfverkommer det som sagdt är i Propheterna:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Ser till, I föraktare, och förundrer eder, och varder till intet; ty jag skall verka i edra dagar ett verk, det I icke tro skolen, om någor det eder förtäljer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'När nu Judarna voro gångne utu Synagogon, bådo Hedningarna, att de ville hafva dessa orden för dem på nästa Sabbathen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Då folket var åtskildt, följde Paulum och Barnabam månge Judar och gudfruktige Proselyter; till hvilka de talade, och rädde dem, att de skulle blifva stadige i Guds nåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Men på nästa Sabbathen derefter församlade sig så när hele staden, till att höra Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Och när Judarna sågo folket, vordo de fulle med nit, och sade tvärtemot det som Paulus sade, emotsägandes och talandes hädelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Då togo Paulus och Barnabas tröst till sig, och sade: Eder borde man först säga Guds ord; men efter det I drifven det ifrån eder, och hållen eder ovärdiga till evinnerligit lif, si, så vilje vi vända oss till Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Ty Herren hafver så budit oss: Jag hafver satt dig Hedningomen för ett Ljus, att du skall vara salighet intill jordenen ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Och Hedningarna hörde detta med glädje, och prisade Herrans ord; och trodde så månge, som beskärde voro till evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Och Herrans ord vardt utspridt öfver alla den ängden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Men Judarna togo till att egga gudeliga och ärliga qvinnor, och de öfversta i staden; och uppväckte förföljelse emot Paulum och Barnabam, och drefvo dem utu sina landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Men de skuddade stoftet af sina fötter på dem, och kommo till Iconien. Och Lärjungarna vordo uppfyllde med fröjd och den Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Så hände sig uti Iconien, att de kommo tillsammans, och predikade uti Judarnas Synagogo; så att en mägtig stor hop; af Judarna, och jemväl af Grekerna, begynte tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Men de Judar, som icke trodde, uppväckte och rette Hedningarnas sinne emot bröderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Så blefvo de der i lång tid, och handlade stadeliga i Herranom, som vittnesbörd gaf till sina nåds ord, och lät ske tecken och under genom deras händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Och begynte den menige man i staden söndra sig; så att somlige höllo med Judomen, och somlige med Apostlomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Och vardt ett upplopp gjordt af Hedningarna och Judarna, och deras öfverstar, så att de ville öfverfalla dem med våld, och stena dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Hvilket då de förnummo, flydde de till de städer i Lycaonien, Lystra och Derben, och den ängden allt deromkring;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Och predikade der Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Och en man i Lystra, krank i sina fötter, satt der ofärdig ifrå sine moders lif, och hade aldrig gångit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Denne hörde Paulum tala. Så såg han på honom, och förmärkte, att han hade tro till att få sina helbregdo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Ty sade han till honom med höga röst: Upprätt dig på dina fötter. Och han sprang upp, och begynte till att gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Då folket såg det Paulus gjort hade, upphofvo de sina röst på Lycaoniskt mål, sägande: Gudar äro komne ned till oss i menniskoliknelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Och de kallade Barnabam Jupiter; men Paulum kallade de Mercurius, efter han förde ordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Och Jupiters Prest, som var för deras stad, hade oxar och kransar fram för dörrena, och ville samt med folket offra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Då Apostlarna, Paulus och Barnabas, det hörde, refvo de sin kläder sönder, och sprungo ut ibland folket, ropandes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Och sägandes: I män, hvi gören I detta? Vi äre ock menniskor, lika som I, dödelige; och förkunnom eder Evangelium, att I skolen omvändas ifrå denna fåfängheten intill lefvandes Gud, som gjort hafver himmel och jord, och hafvet, och allt det uti dem är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Hvilken i framliden tid hafver låtit alla Hedningar gå sina egna vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Ändock han icke lät sig sjelfvan vara utan vittnesbörd, i det han gjorde väl emot oss, gifvandes oss regn och fruktsam tid af himmelen; uppfyllandes vår hjerta med mat, och glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Och då de detta sade, stillte de folket med plats, att de icke offrade till dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Så kommo der någre Judar till utaf Antiochien och Iconien, hvilke så bestämplade med folket, att de stenade Paulum, och släpade honom utu staden, menandes att han var död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Och vid Lärjungarna stodo der omkring honom, reste han sig upp, och gick in i staden. Och dagen derefter färdades han dädan med Barnabas till Derben;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Och predikade Evangelium i den staden. Och då de der många lärt hade, kommo de igen till Lystra, och Iconien, och Antiochien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Styrkandes Lärjungarnas själar, och förmanandes att de skulle blifva stadige i trone; och att igenom mycken bedröfvelse måste vi ingå i Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Och när de hade utvalt Prester för hvar och en församling, och hade bedit och fastat, befallde de dem Herranom, den de uppå trodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Och de foro igenom Pisidien, och kommo in uti Pamphylien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Och då de predikat hade i Perge, foro de neder till (den staden) Attalien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Och dädan seglade de till Antiochien, dädan de uti Guds nåd befallde voro, till det verk som de uträttat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Och då de der kommo, hade de tillhopa församlingena, och underviste dem, hvad Gud med dem gjort hade; och att han upplåtit hade trones dörr för Hedningomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Och de blefvo der med Lärjungarna ett godt skifte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Och kommo någre neder af Judeen, och lärde bröderna: Utan I låten eder omskära efter Mose sätt, så kunnen I icke blifva salige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Då vardt en tvedrägt och träta, icke den minsta, så att Paulus och Barnabas föllo emot dem; och derföre skickade de att Paulus och Barnabas, och någre andre af dem, skulle uppfara till Apostlarna, och till Presterna i Jerusalem, för detta spörsmålets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Och så vordo de förfordrade af församlingene, och foro genom Phenicien och Samarien, och förtäljde Hedningarnas omvändelse; och gjorde dermed allom brödromen stor glädje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'När de nu kommo till Jerusalem, vordo de undfångne af församlingene, och af Apostlarna, och de äldsta; och de förkunnade allt det Gud hade gjort med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Då reste sig upp någre af de Phariseers parti, som vid trona tagit hade, sägande att man måste omskära dem, och bjuda uppå att man hålla skulle Mose lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Då församlade sig Apostlarna och Presterna, till att ransaka om det ärendet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Och när nu fast derom frågadt var, stod Petrus upp, och sade till dem: I män och bröder, I veten, att uti förgången tid ibland oss hafver Gud utvalt, att Hedningarna hörde Evangelii ord genom min mun, och trodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Och Gud, som hjertat känner, vittnade med dem, gifvandes dem den Helga Anda, så väl som oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'Och gjorde ingen åtskilnad emellan oss och dem; utan rengjorde deras hjerta genom trona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Hvi fresten I då nu Gud, att I viljen lägga det ok på Lärjungarnas hals, det hvarken våra fäder eller vi bära kunde?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Utan genom Herrans Jesu Christi nåd tro vi, att vi skole salige varda, såsom ock de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Då tigde hele hopen, och hörde på Barnabas, och Paulus, som förtäljde hvad tecken och under Gud, genom dem, ibland Hedningarna gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'När de tystnade, svarade Jacobus, och sade: I män och bröder, hörer mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simeon hafver förtäljt, huruledes Gud först sökt hafver, och anammat ett folk till sitt Namn utaf Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Och med honom draga öfverens Propheternas ord; såsom skrifvet är:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Derefter vill jag komma igen, och åter uppbygga Davids tabernakel, som förfallet är; och vill bota de refvor, som derpå äro, och upprätta det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Att det som qvart är af menniskorna skola spörja efter Herran, och desslikes alle Hedningar, öfver hvilka mitt Namn nämndt är, säger Herren, som allt detta gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Gudi äro all hans verk kunnig, ifrå verldenes begynnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Derföre besluter jag, att man icke skall bekymra dem som af Hedningarna omvändas till Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Utan att man skrifver dem till, att de hafva återhåll af afgudars besmittelse, och boleri och af det som förqvafdt är, och af blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Ty Moses hafver af ålder i alla städer dem som honom predika uti Synagogorna, der han på alla Sabbather läsen varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Då belefvade Apostlarna och Presterna med hela församlingene, att man utvalde några män af dem, och sände till Antiochien med Paulo och Barnaba; nämliga Judas, som kallades Barsabas, och Silas, som voro yppersta männerna ibland bröderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Och de fingo dem bref i händerna, vid detta sinnet: Vi Apostlar, och äldste, och bröder, önskom dem brödrom, som äro af Hedningomen uti Antiochien, och Syrien, och Cilicien, helso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Efter vi hört hafve, att någre äro utgångne af oss, och hafva förvillt eder med läro, och förvändt edra själar, bjudandes att I skolen låta eder omskära, och hålla Lagen, dem vi det icke befallt hafve;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Derföre syntes oss endrägteliga i våra församling att taga några män ut, och sända till eder, med oss älskeligom Barnaba och Paulo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Som äro de män, som sina själar utsatt hafva, för vårs Herras Jesu Christi Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Så sände vi nu Judas och Silas, de som ock med munnen skola säga eder det samma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Ty dem Helga Anda, och oss, syntes ingen yttermera tunga lägga på eder, utan dessa stycken som af nödene äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Nämliga att I hafven återhåll af thy som afgudom offradt är, och af blod, och af det förqvafdt är, och af boleri; för hvilken stycke om I eder förvaren, så gören I väl. Farer väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'När de nu hade fått sin afsked, kommo de till Antiochien; och församlade den meniga man, och fingo dem brefvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'När de det läsit hade, vordo de glade af den trösten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Men Judas och Silas, efter de ock voro Propheter, förmanade de bröderna med mång ord, och styrkte dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Och blefvo der i någon tid; och vordo sedan igensände med fred ifrå bröderna till Apostlarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Och Silas täcktes att blifva der.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Men Paulus och Barnabas vistades i Antiochien, lärandes och förkunnandes Herrans ord, med mångom androm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Men efter några dagar sade Paulus till Barnabas: Vi vilje fara tillbaka igen, och bese våra bröder, i alla städer der vi Herrans ord förkunnat hafve, huru de hafva sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Men Barnabas rådde, att de skulle taga med sig Johannem, den ock Marcus kallades.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Då ville icke Paulus, att den skulle följa dem, som hade trädt ifrå dem i Pamphylien, och icke följt dem till verket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Och så skarp vardt deras träta, att den ene skiljdes ifrå den andra. Och Barnabas tog Marcum till sig, och seglade till Cypren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Men Paulus utvalde Silam, och for sina färde, befallder i Guds nåd af bröderna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Och vandrade omkring i Syrien och Cilicien, styrkandes församlingarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Och han kom till Derben och Lystra; och si, der var en Lärjunge, benämnd Timotheus, en Judisk qvinnos son, den der trogen var; men fadren var en Grek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Den samme hade ett godt rykte af de bröder, som voro i Lystris och Iconien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Då ville Paulus, att han skulle fara med honom; och tog och omskar honom, för de Judars skull, som voro i de rum; ty de visste alle, att hans fader var en Grek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Och der de foro genom städerna, befallde de dem hålla de stadgar, som af Apostlarna och Presterna i Jerusalem beslutne voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Och vordo de församlingar stadfäste i trone, och förökades på talet hvar dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Då de vandrade genom Phrygien och Galatie landskap, vardt dem förment af den Helga Anda, tala ordet i Asien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Derföre foro de in i Mysien, och bödo till att fara in i Bithynien; och Anden tillstadde dem icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Men då de hade farit genom Mysien, foro de ned till Troadem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Och en syn syntes Paulo om nattena. En Macedonisk man stod och bad honom, sägandes: Far in i Macedonien, och hjelp oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Och straxt han hade sett synena, tänkte vi till att fara in i Macedonien; och voro visse deruppå, att Herren hade kallat oss till att predika Evangelium för dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Då vi nu seglade af Troade, kommo vi vår rätta kos till Samothracien, och dagen derefter till Neapolis;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'Och dädan till Philippos, som är ypperste staden i Macedonien, och är en fristad. Och vistades vi uti den staden några dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Och om Sabbathsdagen gingo vi ut af staden till älfvena, der man plägade bedja; och satte oss ned, och talade med qvinnor, som der tillsamman kommo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Och en gudelig qvinna, benämnd Lydia, en purpurkrämerska, utaf de Thyatirers stad, lydde till; och Herren öppnade hennes hjerta, att hon gaf akt på det Paulus sade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Och hon lät sig döpa, och allt sitt hus; och bad dem, sägandes: Om I hållen mig derföre att jag tror på Herran, så kommer i mitt hus, och blifver der. Och hon nödgade oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Och hände sig, då vi gingom till bönen, mötte oss en piga, som hade en spådomsanda, och hon drog sina herrar mycken båtning till, med sin spådom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Hon följde Paulum och oss efter, och ropade, sägandes: Desse männerna äro högsta Guds tjenare, de der eder förkunna salighetenes väg;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Och det gjorde hon i många dagar. Men Paulus tog detta illa vid sig, och vände sig om, sägandes till andan: Jag bjuder dig, vid Jesu Christi Namn, att du far ut af henne. Och han for ut i samma stund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Då hennes herrar sågo, att hoppet var borto till deras båtning, togo de fatt på Paulus och Silas, och drogo dem på torget till de öfversta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Och antvardade dem Rådherrarna i händer, sägande: Desse männerna göra ena villo i vår stad, efter de äro Judar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Och lära det sätt, som oss icke höfves anamma eller hålla, efter vi äre Romerske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Och folket lopp ihop med dem; och Rådherrarna refvo deras kläder sönder, och läto hudflänga dem med ris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Och när de hade mycket slagit dem, kastade de dem i fängelse, och befallde fångvaktaren, att han skulle granneliga taga vara på dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Då, efter han fick så sträng befallning, kastade han dem in i innersta fångahuset, och slog en stock öfver deras fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Om midnattstid voro Paulus och Silas i sina böner, och lofvade Gud med sång; och fångarna hörde dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Och med hast vardt en stor jordbäfning, så att grundvalen i fångahuset bäfvade; och straxt vordo alla dörrarna öppna, och allas deras bojor vordo lösa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Då vaknade fångvaktaren, och fick se dörrarna på fångahuset öppna, och drog sitt svärd ut, viljandes dräpa sig sjelf; och mente att fångarna voro bortflydde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Då ropade Paulus med höga röst, sägandes: Gör dig sjelfvom intet ondt; ty vi äre alle här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Då beddes han ett ljus, och gaf sig derin, och föll ned för Pauli och Sile fötter, bäfvandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Och han hade dem ut, och sade: Herrar, hvad skall jag göra, att jag må blifva salig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Då sade de: Tro på Herran Jesum, så blifver du och ditt hus saligt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Och talade för honom Herrans ord, och för allom dem som i hans huse voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Och i samma stunden om natten tog han dem till sig, och tvådde deras sår; och lät sig straxt döpa, och allt sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Och hade dem hem i sitt hus, och gaf dem mat, fröjdandes sig att han med allt sitt hus trodde Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Då dager vardt, sände Rådherrarna stadstjenarena, sägande: Släpp de männerna ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Detta talet förkunnade fångvaktaren Paulo: Rådherrarna hafva budit, att I skolen släppas; går fördenskull ut, och farer i frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Då sade Paulus till dem: De hafva hudflängt oss uppenbarliga, utan lag och dom, ändock vi äre Romerske, och kastat oss i fängelse; och vilja nu hemliga hafva oss härut! Nej, icke så; utan komme sjelfve, och tage oss härut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Då bådade stadstjenarena Rådherromen dessa ord. Då vordo de förfärade, hörande att de voro Romerske;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Och kommo dit, och förmante dem; och togo dem ut, bedjande att de utgå skulle af staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Då gingo de utu fängelset, och kommo till Lydia; och när de hade sett bröderna, och styrkt dem, foro de sina färde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Och då de foro genom Amphipolis och Apollonien, kommo de till Thessalonica, der en Judasynagoga var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Der gick Paulus in till dem, efter som hans seder var; och i tre Sabbather talade han för dem utu Skrifterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Förklarade och beviste, att Christus måste lida, och uppstå ifrå de döda; och att denne är Christus Jesus, hvilken jag (sade han) förkunnar eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Och somlige af dem trodde, och gåfvo sig intill Paulum och Silam; desslikes ock en mägta stor hop af gudfruktiga Greker, och dertill de yppersta qvinnor, väl många.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Då vordo de otrogne Judar fulle med nit, och togo till sig några arga skalkar lös parti; och samlade sig i en rota, och gjorde ett upplopp i staden, trängande sig intill Jasons bus, och ville draga dem derut för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Och då de icke funno dem, drogo de Jason och några bröder till de öfversta i staden, och ropade: Desse, som hela verldena förvilla, äro ock nu hitkomne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Och dem hafver Jason hemliga undfängit, och de alle göra emot Kejsarens bud, och säga af en annan Konung, som är Jesus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Och de upprette folket, och öfverstarna i staden, som sådant hörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Och de anammade en ursäkt af Jason, och af de andra, och släppte dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Men bröderna släppte straxt om nattena ut Paulus och Silas, och läto dem fara till Berea. När de kommo dit, gingo de in i Judarnas Synagogo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Ty de voro de ädlaste ibland dem i Thessalonica; de anammade ordet ganska viljeliga, alla dagar sökande i Skrifterna, om det ock så hade sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Och månge af dem trodde, och ärliga Grekiska qvinnor och män, väl månge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Men när de Judar i Thessalonica förnummo, att Guds ord vardt ock i Berea af Paulo förkunnadt, kommo de dit, och upprette också der folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Och straxt läto bröderna Paulum ut, att han gick allt intill hafvet; men Silas och Thnotheus blefvo der qvare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Men de, som förfordrade Paulum, följde honom till Athen; och de fingo befallning till Silas och Timotheus, att de skulle med hast komma till honom, och foro sina färde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Och då Paulus förbidde dem i Athen, vardt hans ande upptänd i honom, då han såg staden afgudadyrkan undergifven vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Och disputerade han med de Judar och de gudfruktiga uti Synagogon, och på torget, hvar dag, med dem som kommo till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Och någre Philosophi, nämligade Epicureer och Stoiker, begynte kämpas med honom. Och somlige sade: Hvad vill denne sqvallraren säga? Och somlige sade: Det synes som han ville förkunna några nya gudar; derföre att han förkunnade dem Evangelium om Jesu, och uppståndelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Och de togo fatt på honom, och ledde honom på domplatsen, sägande: Måge vi icke veta, hvad denne nye lärdomen är, som du lärer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Ty du gifver vår öron ny styck er före; så vilje vi nu veta, hvad det vara skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Och de af Athen, och alle de främmande som der vistades, aktade på intet annat än att säga eller höra något nytt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Då stod Paulus midt på domplatsen, och sade: I män af Athen, jag ser, att I uti all stycke omgån med vantro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Ty jag hafver gångit omkring, och skådat edor gudsdyrkan, och fann ett altare, derpå skrifvet stod: Dem okända Gudenom. Den I nu dyrken ovetande, honom förkunnar jag eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Gud, som hafver gjort verldena, och allt det deruti är, efter han är Herre öfver himmel och jord, bor han icke uti de tempel, som med händer uppbyggd äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Ej heller dyrkas med menniskohänder, behöfvandes någon ting, efter han gifver allom lif, anda och allt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Och hafver gjort allt menniskoslägtet af ett blod, till att bo på hela jordene, och satt dem före beskärda tider, och skickat huru vidt och långt de bo skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'På det att de skola söka Herran, om de måtte kunna kännan och finnan, ändock han är icke långt ifrå hvarjom och enom af oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Ty i honom lefve vi, röroms och hafve varelse; såsom ock någre af edra Poeter sagt hafva: Ty vi äre ock hans slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Äre vi nu Guds slägte, så skole vi icke tänka att Gudomen är lik vid guld och silfver, eller stenar konsteliga uthuggna, eller vid menniskors fund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Och ändock Gud hafver öfversett härtilldags sådana fåvitskhets tid, förkunnar han dock nu menniskomen, att alle allestäds skola bättra sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Ty han hafver satt en dag före, på hvilken han skall döma jordenes krets med rättfärdighet, genom den man i hvilkom han det beslutit hafver, gifvandes allom trona före, i det han honom uppväckt hade ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Då de hörde nämnas de dödas uppståndelse, gjorde somlige der gack af, och somlige sade: Vi vilje än yttermera höra dig derom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Och så gick Paulus ut ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Och någre män höllo sig intill honom, och trodde; ibland hvilka var Dionysius, en af Rådet, och en qvinna, benämnd Damaris, och andre med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Derefter for Paulus af Athen, och kom till Corinthus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Och der fann han en Juda, benämnd Aqvila, bördig af Ponto, den nyligen kommen var af Valland, och Priscilla, hans hustru; ty Claudius hade budit uppå, att alle Judar skulle fara ut af Rom; och höll han sig intill dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'Ty han var af samma handtverk; och blef när dem, och arbetade; och var deras handtverk att göra paulun,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Och disputerade han uti Synagogon på alla Sabbather, dragandes dertill både Judar och Greker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Och då Silas och Timotheus kommo ifrå Macedonien, tvingade Anden Paulus att betyga Judomen, att Jesus var Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Och då de sade deremot, och talade hädelse, skakade han kläden, och sade till dem: Edart blod vare öfver edart hufvud; härefter går jag nu oskyldig till Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Och så gick han dädan, och kom uti ens mans hus, som het Justus, den der var en gudfruktig man, hvilkens hus var hardt vid Synagogon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Men Crispus, öfversten för Synagogon, trodde Herranom, med allt sitt hus; och månge Corinthier, som på hörde, trodde, och läto sig döpa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Och sade Herren till Paulum uti en syn om natten: Frukta dig intet, utan tala, och tig icke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Ty jag är med dig, och ingen skall bjuda till att göra dig skada; ty jag hafver mycket folk i denna staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Så blef han der ett år och sex månader, lärandes dem Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Men då Gallion var landshöfding öfver Achaja, reste Judarna sig upp endrägteliga emot Paulum, och hade honom fram för domstolen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Sägande: Denne mannen gifver menniskomen in att dyrka Gud emot lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Och som Paulus nu aktade upplåta sin mun, sade Gallion till Judarna: Vore någor orätt skedd, eller någor dråpelig ogerning, vore väl tillbörligit, att jag hörde eder, I Judar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Men är något spörsmål om ord och namn, och om edor lag, der mågen I sjelfve se eder om; ty deröfver vill jag ingen domare vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Och han dref dem ifrå domstolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Då togo alle Grekerna fatt på Sosthenes, öfverstan för Synagogon, och slogo honom framför domstolen; och Gallion skötte der intet om.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Sedan Paulus hade då varit der i lång tid, helsade han bröderna, och seglade sina färde till Syrien, och följde honom Priscilla och Aqvila; och han rakade sitt hufvud i Kenchrea, ty han hade ett löfte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Och kom dädan till Ephesum, och der lät han dem blifva; men han gick in i Synagogon, och disputerade med Judarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Och de bådo honom, att han skulle blifva i längre tid när dem; då ville han icke;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Utan han helsade dem, sägandes: Jag måste ju ändteliga vara i Jerusalem i den högtiden som instundar; men sedan vill jag komma till eder igen, om Gud vill. Och så for han ifrån Epheso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Och han kom till Cesareen; och då han hade varit uppe, och helsat församlingena, for han ned till Antiochien,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Och sedan han der i någon tid varit hade, for han sina färde, och vandrade allt bortåt genom Galatiska landet och Phrygien, styrkandes alla Lärjungarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Då kom till Ephesum en Jude, benämnd Apollos, bördig af Alexandrien, en vältalig man, och mägtig i Skrifterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Denne var undervist i Herrans väg; och talade, upptänder i Andanom, och försummade icke lära det Herranom tillhörde, och visste allenast säga af Johannis döpelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Och han begynte dristeliga tala uti Synagogon. Då Priscilla och Aqvila hörde honom, togo de honom till sig, och uttydde för honom ännu grundeligare Guds väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Och då han ville färdas till Achaja, skrefvo bröderna och förmanade Lärjungarna, att de skulle undfå honom. Och då han framkom, var han dem som trodde mycket till tröst genom nådena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Ty han öfvervann Judarna skarpeliga, och uppenbarliga bevisade med Skrifterna, att Jesus var Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Och begaf sig, medan Apollos var i Corintho, att Paulus vandrade genom de öfra landen, och kom till Ephesum; der fann han några Lärjungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Och han sade till dem: Hafven I fått den Helga Anda, sedan I trodden? Då sade de till honom: Vi hafve icke ens hört, om någor Helig Ande är till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Och han sade till dem: Hvarmed ären I då döpte? De sade: Med Johannis döpelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Då sade Paulus: Johannes döpte med bättringenes döpelse, och sade folkena, att de skulle tro på den som komma skulle efter honom, det är, på Christum Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Och att, då de det hörde, läto de döpa sig i Herrans Jesu Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Och då Paulus lade händer på dem, kom den Helige Ande öfver dem; och de begynte tala med tungomål, och propheterade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Och alle desse voro vid tolf män.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Och han gick in i Synagogon, och talade dristeliga i tre månader, disputerade, och rådde till Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Och efter det någre af dem vordo förhärde, och icke trodde, utan talade illa om den vägen för den meniga man, gick han ifrå dem, och afskiljde Lärjungarna, disputerandes dageliga uti ens mans skola, som het Tyrannus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Och detta gick så till i tu år; så att alle de, som bodde i Asien, hörde Herrans Jesu ord, både Judar och Greker.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Och Gud gjorde icke ringa krafter genom Pauli händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Så att de ock togo svettedukar och skörte, som vid hans kropp hade kommit, och lade på de sjuka; och sjukdomen gick utaf dem, och de onde andar foro ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Så voro någre Judar besvärjare, som foro omkring; de togo sig före åkalla Herrans Jesu Namn, öfver dem som hade de onda andar, sägande: Vi besvärje eder vid Jesum, den Paulus predikar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Och ibland dem, som detta gjorde, voro en Judes sju söner, Sceve, öfversta Prestens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Då svarade den onde anden, och sade: Jesum känner jag väl, och Paulum vet jag väl; men ho ären I?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Och mannen, som den onde anden uti var, sprang uppå dem, och vardt dem öfvermägtig; och kastade dem under sig, så att de nakne och sargade undflydde utaf det huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Och detta vardt allom vetterligit, både Judom och Grekom, som bodde i Epheso; och en räddhåge föll öfver dem alla, och Herrans Jesu Namn vardt storliga prisadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Och månge af dem, som trodde, kommo och bekände, och förkunnade hvad de uträttat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Men månge af dem, som förvetna konster brukat hade, båro fram böckerna, och brände upp i hvars mans åsyn; och då deras värde räknadt vardt, vardt det funnet till femtiotusend penningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Så fast växte då Herrans ord, och kom till magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Då detta skedt var, satte Paulus sig fore i Andanom att fara genom Macedonien och Achaja till Jerusalem, sägandes: När jag hafver varit der, måste jag ock se Rom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Då sände han till Macedonien två af dem som honom tjente, nämliga Timotheum och Erastum; men sjelf blef han qvar till en tid i Asien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'På den tiden vardt icke litet buller om den vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Ty det var en guldsmed, benämnd Demetrius, som gjorde silftempel till Diana, der de en stor vinning af hade, som det handtverk brukade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Hvilka han tillhopakallade, och de der slikt arbete plägade bruka, och sade: I män, I veten, att vi hafve vår näring af detta handtverket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Och I sen och hören, att denne Paulus hafver bedragit, ej allenast i Epheso, utan sånär i hela Asien, och förvändt mycket folk, sägandes, att det är icke gudar, som göras med menniskohänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Och varder icke allenast gällandes den delen af vårt handtverk, att det nederläggs; utan jemväl ock att den stora gudinnones Diane tempel varder för intet hållet; och måtte då ske, att hennes härlighet af kommer, den dock hela Asien och hela verlden dyrkar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'När de detta hörde, vordo de fulle med vrede, och ropade: Stor är de Ephesiers Diana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Och i hela staden vardt ett upplopp; och de föllo hasteliga till, alle med ett mod, in på skådoplatsen, och togo fatt på Gajus och Aristarchus, som voro af Macedonien, och af Pauli sällskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Och Paulus ville gångit in i hopen, till folket; då ville Lärjungarna det icke tillstädja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Sände ock någre af de Öfversta i Asien, som hans vänner voro, till honom, och bådo att han icke skulle gifva sig in på platsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Och andre ropade annat; ty menigheten var förbistrad; och mesta delen visste icke, för hvad sak de voro församlade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Och somlige af folket drogo Alexandrum fram, den Judarna framstötte. Då tecknade Alexander med handene, att de skulle vara tyste, och aktade försvara sig för folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'När de förnummo att han var en Jude, ropade de alle med en mun, sånär i två timmar, sägande: Stor är de Ephesiers Diana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Då cancelleren hade stillat folket, sade han: I män af Epheso, ho är den menniska som icke vet, att Ephesiers stad dyrkar den stora gudinnan Diana, och det beläte som af himmelen kommet är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Så, efter der säger ingen emot, måsten I stilla eder, och intet orådeligit företaga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'I hafven dragit dessa männerna fram, som hvarken äro kyrkoröfvare, eller edor gudinnos försmädare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Om Demetrius, och de med honom äro af hans handtverk, hafva sak emot någon, så hafver man Råd, och rättgång, och fogdar; der måga de klaga och svara hvarannan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Men hafven I om något annat handla, då må det åtskiljas uti någon tillbörlig samqväm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Ty det är fara att vi komme i skuld, för det upplopp som i dag skedt är, efter ingen sak på färde är, der vi kunne någon skäl af taga till detta upplopp. Och då han det sagt hade, lät han folket gå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Då nu upploppet vardt stilladt, kallade Paulus Lärjungarna till sig, och helsade dem, och for sina färde, till att draga in uti Macedonien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Och när han hade vandrat genom de landsändar, och förmanat dem med mycket tal, kom han in i Grekeland;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Och han blef der i tre månader. Och efter Judarna hade satt försåt för honom, när han skulle fara in i Syrien, fick han för råd att vända om igen genom Macedonien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Och följde honom allt intill Asien Sopater af Bereen; och af Thessalonica Aristarchus, och Secundus, och Gajus af Derbe, och Timotheus; och af Asien Tychicus, och Trophimus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Desse foro framföre, och bidde oss i Troade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Men vi seglade af Philippis, efter Påskadagarna, och kommom till dem i Troade innan fem dagar; och töfvade der i sju dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'På en Sabbath, då Lärjungarna kommo tillsammans, till att bryta brödet, hade Paulus ett tal för dem, efter han ville annan dagen färdas; och fördröjde han talet intill midnatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Och mång ljus voro upptänd i salen, der de församlade voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Så satt der en yngling uti ett fenster, benämnd Eutychus, och var förtyngd af svår sömn; och vid Paulus länge talade, tog sömnen honom så svårliga, att han föll ned af tredje bottnen, och vardt upptagen döder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Då steg Paulus ned, och lade sig på honom, och tog omkring honom, och sade: Varer icke bedröfvade; ty själen är ännu uti honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Sedan gick han upp igen, och bröt brödet, och åt; och talade sedan länge med dem, tilldess det dagades; och så färdades han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Och hade de den ynglingen fram lefvandes; och voro deraf icke litet tröstade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Men vi stegom till skepps, och forom dädan till Asson, aktande der intaga Paulum; ty han hade så skickat, och han ville fara landvägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'När vi tillhopakommom i Asson, togom vi honom in, och kommom sedan till Mitylenen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Dädan seglade vi, och kommom dagen nästefter in mot Chium; och så dagen derefter kommom vi till Samum, och töfvade i Trogillio; och nästa dagen efter kommom vi till Miletum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Ty Paulus hade satt sig före att segla framom Ephesus, på det att han icke skulle förtöfva sig i Asien; ty han hastade sig, om möjeligit hade varit, att han kunde varit i Jerusalem om Pingesdagarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Och sände han af Mileto båd till Ephesum, och kallade till sig Presterna i församlingene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'När de kommo till honom, sade han till dem: I veten, huruledes jag hafver varit när eder alltid, ifrå första dagen jag kom in i Asien;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Tjenandes Herranom med all ödmjukhet, och med många tårar och frestelser, som mig vederforos af Judarnas försåt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Så att jag hafver intet försummat, det eder kunde vara till nytto, att jag ju hafver förkunnat eder, och lärt eder uppenbarliga och synnerliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Betygandes både för Judar och Greker den bättring som är inför Gud, och den tro som är till vår Herra Jesum Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Och nu si, jag, bunden i Andanom, färdas till Jerusalem, icke vetandes hvad mig der öfvergå skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Utan den Helge Ande i alla städer betygar och säger, att bojor och bedröfvelse står mig före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Dock aktar jag det intet, ej heller är mig sjelfvom mitt lif kärt; på det jag skall fullkomna mitt lopp med glädje, och det ämbete som jag anammat hafver af Herranom Jesu, till att betyga Evangelium om Guds nåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Och nu si, jag vet, att härefter fån I icke se mitt ansigte, I alle, der jag framfarit hafver och predikat Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Derföre betygar jag eder på denna dagen, att jag oskyldig är för allas blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Ty jag hafver icke försummat, med mindre jag hafver förkunnat eder allt Guds råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Så hafver nu akt på eder, och på allan hjorden, i hvilkom den Helge Ande hafver eder satt till Biskopar, att regera Guds församling, hvilka han hafver förvärfvat med sitt blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Ty jag vet det att, sedan jag skiljs ifrån eder, skola komma ibland eder svåra ulfvar, de der hjorden icke spara skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Och af eder sjelfvom skola män uppkomma, som tala skola det orätt är, och draga lärjungar till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Derföre vaker, och tänker uppå, att jag i tre år, natt och dag, icke hafver återvändt förmana hvar och en, med tårar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Och nu, bröder, befaller jag eder Gudi, och hans nåds orde, hvilken mägtig är uppbygga eder, och gifva eder arfvedel ibland allom dem som helgade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Ingens mans silfver, eller guld, eller kläder hafver jag begärat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Men I veten sjelfve, att dessa händerna hafva tjent till min nödtorft, och deras som med mig voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'All ting hafver jag vist eder, att så måste man arbeta, och upptaga de svaga, och tänka på Herrans Jesu ord, som han sade: Saligare är gifva än taga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Och när han detta sagt hade, föll han på sin knä, och bad med allom dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Och vardt en stor gråt med allom dem; och de föllo Paulo om halsen, och kysste honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Sörjande mest för det ordets skull, som han sagt hade, att de skulle icke mer få se hans ansigte. Och så följde de honom till skepps.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Som nu skedde att vi lade af dädan, och foro ifrå dem, kommom vi rätta kosen till Coum; och dagen nästefter till Rhodum, och dädan till Patara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Och der fingo vi ett skepp, som aktade sig till Phenicien; der stego vi uti, och ladom utaf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Och som Cypren begynte komma oss i sigte, lätom vi det på vänstra handene, och segladom till Syrien, och kommom till Tyrum; ty der lossade skeppet upp laddningena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Och efter vi funne der Lärjungar, blefvo vi der i sju dagar. Och de sade Paulo genom Andan, att han skulle icke fara upp till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Och då de dagar förlupne voro, drogo vi våra färde; och de följde oss alle, samt med hustrur och barn, tilldess vi kommom utu staden; och på stranden fölle vi på knä, och bådom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Och sedan vi hade helsat hvarannan, ginge vi till skepps; och de gingo till sitt igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Men vi höllo seglatsen fram ifrån Tyro, och kommom neder till Ptolemais; och der hel sade vi bröderna, och blefve der en dag med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Dagen derefter kommom vi, som vorom med Paulo, till Cesareen; och gingom in uti Philippi Evangelistens hus, hvilken en var af de sju, och blefvom när honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Och han hade fyra döttrar, jungfrur som propheterade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Och medan vi vorom der i många dagar, kom der en Prophet till utaf Judeen, benämnd Agabus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Då han var kommen till oss, tog han Pauli bälte, och band sig fötter och händer, och sade: Det säger den Helge Ande: Den man, som detta bältet tillhörer, skola Judarna så binda i Jerusalem, och antvarda honom i Hedningahänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'När vi detta hörde, bådom vi, och de som utaf den staden voro, att han icke skulle draga upp till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Då svarade Paulus, och sade: Hvad gören I, gråtandes, och bedröfvandes mitt hjerta? Jag är redebogen icke allenast bindas, utan jemväl dö i Jerusalem, för Herrans Jesu Namns skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Och efter han lät intet säga sig, gåfve vi oss tillfrids, sägande: Varde Herrans vilje.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Efter de dagar redde vi oss till, och forom upp till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Och kommo någre Lärjungar med oss af Cesareen, de der med sig hade en gamlan Lärjunga, som var af Cypren, benämnd Mnason, när hvilkom vi gästa skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Och när vi kommom till Jerusalem, undfingo oss bröderna gerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Dagen derefter gick Paulus med oss in till Jacobum; och alle de äldste församlades;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Då han dem helsat hade, förtäljde han dem alltsammans, det ena med det andra, som Gud gjort hade, genom hans tjenst, ibland Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Då de det hörde, prisade de Herran, och sade till honom: Du ser, käre broder, huru mång tusend Judar äro som tro; och alle hafva nit om lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Och de hafva hört af dig, att du lärer alla de Judar, som bo ibland Hedningarna, att de skola träda ifrå Mose lag; sägandes, att de icke skola omskära sin barn, och icke vandra efter som vant är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Hvad är det då? Den menige man måste ändtliga församlas; ty de få väl höra, att du äst kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Så gör nu, som vi säge dig: Vi hafve här fyra män, som löfte hafva på sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Dem tag till dig, och rena dig med dem, och bekosta der något uppå att de raka sitt hufvud; och deraf kunna alle veta, att det är intet som de hört hafva om dig; utan att du ock så vandrar, att du ock håller lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Men de Hedningar, som vid trona tagit hafva, dem hafve vi tillskrifvit, och beslutit att de intet sådant behöfva att hålla; utan att de taga sig vara för det afgudom offradt är, och för blod, och för det som förqvafdt är, och för boleri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Dagen derefter tog Paulus männerna till sig, och lät rena sig med dem; och gick in i templet, förkunnandes att reningsdagarna voro fullbordade, tilldess utoffradt var, för hvar och en af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Då de sju dagar när ute voro, och de Judar, som voro af Asien, fingo se honom i templet, upprette de allt folket, och togo fatt på honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Ropande: I män af Israel, hjelper; detta är den man, som alla allestäds lärer, emot folket, emot lagen, och emot detta rummet; och derutöfver hafver han dragit Greker in i templet, och gjort detta helga rummet oskärdt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Ty de hade sett Trophimus af Epheso i staden med honom, och mente att Paulus hade haft honom in i templet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Och vardt ett upplopp i hela staden, och folket församlades, och togo Paulum, och drogo honom utu templet. Och straxt vordo portarna tilläste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Och som de ville dräpit honom, fick den öfverste höfvitsmannen för krigsfolket båd, huru hela Jerusalem var upprest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Då tog han straxt till sig krigsknektarna och höfvitsmännerna, och kom löpandes till dem; och när de fingo se höfvitsmannen och krigsknektarna, vände de igen att slå Paulum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Och gick höfvitsmannen fram, och tog fatt på honom, och lät binda honom med två kedjor; och sporde ho han var, eller hvad han gjort hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Men ibland folket ropade den ene så, och den andre så; och efter han kunde intet förfara det visst var, för sorlets skull, lät han föra honom i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Och när han kom till trapporna, hände sig att krigsknektarna måste bära honom, för öfvervålds skull, som gick af folkena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Ty der följde ganska mycket folk efter, och ropade: Tag bort honom!');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Och som nu Paulus begynte komma in i lägret, sade han till höfvitsmannen: Må jag ock tala med dig? Då sade han: Kan du tala Grekisko?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Äst icke du den Egyptiske mannen, som för dessa dagar gjorde ett upplopp, och hade ut i öknena fyratusend mördare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Då sade Paulus: Jag är en Judisk man, af Tarsen i Cilicien, en borgare i den namnkunniga staden; jag beder dig, städ till att jag må tala till folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Och han tillstadde det. Då stod Paulus på trappone, och tecknade till folket med handene. Då nu vardt en stor tysta, talade han till dem på Ebreiskt mål, sägandes:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'I män, bröder och fäder, hörer min ursäkt, som jag nu gör för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Och då de hörde, att han talade på Ebreisko till dem, dessmer ljud gåfvo de honom. Och han sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Jag är en Judisk man, född i Tarsen i Cilicien; men uppfödd här i staden vid Gamaliels fötter, granneliga lärder uti fädernas lag, hafvandes nit om Gud, såsom ock I alle i denna dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Och hafver förföljt denna vägen allt intill döden, bindandes och kastandes i fängelse både män och qvinnor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Såsom ock öfverste Presten mig vittne är, och hele hopen af de äldsta, af hvilkom jag hade tagit bref till bröderna, och for till Damascum, att föra ock dem, som der voro, bundna till Jerusalem, att de skulle blifva näpste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Så hände sig, vid jag var på vägen, och kom in mot Damascum, vid middagstid, att ett stort sken af himmelen ljungade kringom mig hasteliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Och jag föll ned på jordena, och hörde ena röst, sägandes till mig: Saul, Saul, hvi förföljer du mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Och jag svarade: Ho äst du, Herre? Sade han till mig: Jag är Jesus af Nazareth, den du förföljer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Och de som med mig voro, sågo skenet, och vordo förfärade; men röstena hörde de intet, hans som talade med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Då sade jag: Herre, hvad skall jag göra? Då sade Herren till mig: Statt upp, och gack in i Damascum; och der skall dig sagdt varda, om allt det dig förelagdt är till att göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Och efter jag såg intet, för den klarhetens skull som gick af det skenet, vardt jag ledd vid handena af mina följare, som med mig voro, och kom in i Damascum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Och der var en gudfruktig man efter lagen, benämnd Ananias, ett godt rykte hafvandes när alla Judar, som der bodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Han kom till mig, och stod, och sade till mig: Saul, käre broder, haf din syn igen. Och i samma stundene fick jag min syn, och såg honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Då sade han: Våra fäders Gud hafver beredt dig, att du skall känna hans vilja, och se den Rättfärdiga, och höra röstena af hans mun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Ty du skall vara honom ett vittne för alla menniskor, om det du sett och hört hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Och nu, hvad töfvar du? Statt upp, och låt dig döpa, och två af dina synder, åkallandes Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Då hände sig, att när jag var kommen igen till Jerusalem, och bad i templet, att jag vardt tagen uti ena syn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Och såg honom, sägandes till mig: Låt lida dig, och gack snarliga utu Jerusalem; ty de varda icke anammande ditt vittnesbörd om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Och jag sade: Herre, de veta sjelfve att jag drog i häktelse, och hudflängde allestäds i Synagogorna dem som trodde på dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Och då dins vittnes Stephani blod utgjutet vardt, var jag ock med, och samtyckte hans död, och vaktade deras kläder som dråpo honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Och han sade till mig: Gack, ty jag vill sända dig fjerran bort till Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Men de hörde honom allt intill detta ordet. Då upphofvo de sina röst, och sade: Tag bort sådana mennisko af jordene; ty det är icke tillbörligit att han skall lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Och då de så ropade, och kastade sin kläder af, och hofvo stoft upp i vädret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Lät höfvitsmannen leda honom in i lägret, och böd att han skulle huflängas och ransakas, att han måtte få veta, för hvad sak de hade så ropat på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Och då han honom bundit hade med tåg, sade Paulus till underhöfvitsmannen, som när stod: Mågen I ock hudflänga någon Romersk man, och odömdan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Då underhöfvitsmannen det hörde, gick han till öfversta höfvitsmannen, och bådade honom, sägandes: Hvad vill du göra; ty denne mannen är en Romare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Då gick öfverste höfvitsmannen till honom, och sade: Säg mig, äst du ock en Romare? Då sade han: Ja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Då svarade höfvitsmannen: Jag hafver köpt detta borgerskapet med en stor summo. Då sade Paulus: Jag är ock födder (en Romare).');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Och straxt gingo de ifrå honom, som skulle hafva ransakat honom; och höfvitsmannen begynte frukta, sedan han fick veta att han var en Romare, och att han hade bundit honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Dagen derefter ville han veta förvisso, för hvad sak han var beklagad af Judomen; och löste honom utu banden, och lät öfversta Presterna komma tillhopa, och hela Rådet, och lät Paulum komma fram för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Då såg Paulus på Rådet, och sade: I män och bröder, jag hafver vandrat för Gudi uti ett godt samvet, allt intill denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Då böd den öfverste Presten Ananias dem som der när stodo, att de skulle slå honom på munnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Då sade Paulus till honom: Gud skall slå dig, du hvitmenada vägg. Sitter du och skall döma mig efter lagen, och bjuder slå mig emot lagen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Och de der när stodo sade: Bannar du Guds öfversta Prest?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Då sade Paulus: Jag visste icke, käre bröder, att han var öfverste Prest; ty det är skrifvet: Du skall icke banna dins folks öfversta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Och efter Paulus väl visste, att en part af dem voro Sadduceer, och annan parten Phariseer, ropade han inför Rådet: I män och bröder, jag är en Pharisee, och en Pharisees son; jag varder dömder för hoppet och de dödas uppståndelses skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Och då han det sagt hade, vardt en tvedrägt emellan de Phariseer och de Sadduceer; och hopen vardt söndrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Ty de Sadduceer säga, att ingen uppståndelse är, och ingen Ängel, och ingen Ande; men de Phariseer bekänna båda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Och så vardt ett stort rop. Och de Skriftlärde af det Phariseiska parti stodo upp, och begynte kämpas, och sade: Vi finnom intet ondt med den mannen; om så kan hända, att Anden hafver talat med honom, eller en Ängel, så låt oss icke strida emot Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Och efter det begynte varda ett stort upplopp, fruktade öfverste höfvitsmannen, att de skulle sönderslita Paulum, och lät krigsknektarna gå ned, och rycka honom bort ifrå dem, och föra honom i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Om nattena derefter stod Herren när honom, och sade: Var vid ett godt mod, Paule; ty såsom du hafver vittnat om mig i Jerusalem, så måste du ock vittna i Rom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Då dager vardt, slogo sig tillhopa någre af Judarna, och förbannade sig, att de varken äta eller dricka skulle, tilldess de hade dräpit Paulum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Och voro mer än fyratio män, som så hade svorit sig tillhopa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Desse gingo till de öfversta Presterna, och till de äldsta, och sade: Vi hafve, vid förbannelse, bepligtat oss sjelfva ingenting smaka, tilldess vi hafve dräpit Paulum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Så mån I nu förkunna öfversta höfvitsmannenom och Rådet, att han hafver honom fram för oss i morgon, lika som vi ville få veta något vissare om honom; men förr än han kommer fram, äre vi redo till att dräpa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Då Pauli systerson hörde sådana försåt, kom han, och gick in i lägret, och bådade det Paulo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Då kallade Paulus till sig en af de underhöfvitsmän, och sade: Haf denna ynglingen bort till öfversta höfvitsmannen; ty han hafver något undervisa honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Och han tog honom med sig, och hade honom till öfversta höfvitsmannen, och sade: Paulus, som bunden är, kallade mig till sig, och bad att jag skulle hafva denna ynglingen till dig, som något hafver säga dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Då tog öfversta höfvitsmannen honom vid handena, och gick afsides med honom, och frågade honom: Hvad är det som du hafver undervisa mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Då sade han: Judarna hafva samfällt sig att de vilja bedja dig, att du skall i morgon låta Paulum komma ut för Rådet, såsom de ville utfråga något vissare om honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Men lyd dem intet; ty mer än fyratio män af dem vilja vara i försåt för honom, de sig förbannat hafva, att de icke skola äta eller dricka, tilldess de hafva dräpit honom; och nu äro de redo, och vänta att du det utlofva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Sedan lät öfversta höfvitsmannen ynglingen gå sina färde, och böd honom att han för ingom säga skulle, att han honom sådant undervist hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Och kallade till sig två underhöfvitsmän, och sade: Görer redo tuhundrade krigsknektar, att de fara till Cesareen; och sjutio resenärar, och tuhundrade skyttar, till tredje timman på natten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Och tillreder någon fartyg, der man kan sätta Paulum uppå, att de måga föra honom oskaddan till landshöfdingan Felicem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Och skref ett bref vid detta sinnet:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Claudius Lysias, dem mägtiga landshöfdinganom Felici, helso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Denna mannen hade Judarna gripit, och ville dödat honom; och der kom jag till med krigsfolket, och tog honom ifrå dem, efter jag förnam att han var en Romare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Och när jag ville veta sakena, som de hade emot honom, lät jag honom komma inför deras Råd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Så fann jag att han skyllder vardt om någor spörsmål i deras lag; och dock ingen skuld hade, som död eller häktelse värd var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Och vardt mig undervist om försåt, som Judarna hade beställt för honom; och straxt sände jag honom till dig, och böd hans åklagare att, hvad de hafva emot honom, det skola de säga dig. Farväl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Då togo krigsknektarna Paulum, efter som dem befaldt var, och förde honom om nattena till Antipatridem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Och dagen derefter läto de resenärarna följa honom, och de kommo igen i lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'När de kommo till Cesareen, och fingo landshöfdingan brefvet, hade de ock desslikes Paulum fram för honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Då landshöfdingen hade läsit brefvet, och frågat honom, af hvad land han var, och hade förstått, att han var af Cilicien, sade han:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Jag vill höra dig, när dine åklagare komma ock tillstädes; och lät förvara honom uti Herodis Rådhus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Efter fem dagar for öfverste Presten Ananias ned, med de äldsta, och med en förespråkare, benämnd Tertullus; desse gingo till landshöfdingen emot Paulum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Och då han var förekallad, begynte Tertullus klaga, och säga:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Att vi lefve i mycken rolighet under dig, och mång ting beställas i goda måtto, i desso folke, genom dina försigtighet, högmägtige Felix; det anamme vi alltid och allestäds gerna, med all tacksägelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Men på det att jag icke alltför länge skall förhålla dig, beder jag dig, att du hörer oss någor få ord, för din dygds skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Vi hafve funnit denna mannen vara skadelig, den upplopp uppväcker allom Judom öfver hela verldena, och är en mästare för de Nazareners parti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Den ock tillbudit hafver göra templet oskärdt; den vi ock gripit hade, och ville dömt honom efter vår lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Men höfvitsmannen Lysias kom dertill med stora magt, och tog honom utu våra händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Bjudandes, att hans åklagare skulle komma till dig, af hvilkom du kan sjelfver utfråga och låta dig undervisa om all ärende, der vi klage honom före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Och Judarna sade ock dertillmed, att så var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Då svarade Paulus, när landshöfdingen tecknade honom, att han skulle tala: Efter jag nu väl vet, att du nu i mång är hafver domare varit för detta folk, vill jag med dess friare mod försvara mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Ty du kan väl märka, att icke är mer än tolf dagar, sedan jag kom upp till Jerusalem, till att bedja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Och hvarken funno de mig i templet disputera med någrom, eller göra något upplopp ibland folket, hvarken i Synagogorna, eller i staden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Och icke heller kunna de bevisa de stycker, der de klaga mig före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Dock bekänner jag för dig, att jag så dyrkar mina fäders Gud, efter den vägen som de kalla parti, att jag tror allt det i lagen och Propheterna skrifvet är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Och hafver samma hoppet till Gud, der de ock sjelfve efter vänta, som är, att de dödas uppståndelse skall ske, både de rättfärdigas, och orättfärdigas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Ja, för samma saks skull lägger jag mig vinn om hafva ett obesmittadt samvet, inför Gud, och inför menniskor alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Men nu, efter mång år, kom jag, och skulle föra några almosor till mitt folk, och offer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'I hvilkom de funno mig, att jag lät rena mig i templet, utan allt upplopp och buller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Men någre Judar voro af Asien, hvilke nu borde vara här tillstädes för dig, och klaga, om de något hade emot mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Eller säge desse samme, om de funno någor oskäl med mig, medan jag står här för Rådet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Utan för detta ena ordets skull, då jag stod ibland dem, och ropade om de dödas uppståndelse, dömes jag af eder i dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Då Felix detta hörde, förhalade han dem, väl vetandes huru fatt var om denna vägen, och sade: Då höfvitsmannen Lysias kommer härned, vill jag mig undervisa låta om edra sak;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Och befallde underhöfvitsmannen, att han skulle förvara Paulum, och låta honom hafva ro, och ingen af hans förmena att vara honom till tjenst, eller gå till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Efter några dagar kom Felix, med sin hustru Drusilla, och hon var en Judinna. Då kallade han Paulum före, och hörde honom om trona på Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Men då Paulus talade om rättfärdighet, och om kyskhet, och om den tillkommande domen, vardt Felix förskräckt, och sade: Gack dina färde i denna resone; när jag får beläglig tid dertill, vill jag låta kalla dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Men han förhoppades också, att han skulle få penningar af Paulo, på det han skulle gifva honom lös, för hvilka saks skull han ock ofta kallade honom till sig, och talade med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Då nu tu år voro förlupna, kom Porcius Festus i Felix stad; men Felix ville göra Judomen till vilja, och lät Paulum blifva efter sig fången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Då nu Festus var kommen i landet, for han efter tre dagar upp ifrå Cesareen till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Då kommo den öfverste Presten och de ypperste af Judarna till honom emot Paulum, och förmanade honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Och bådo om ynnest emot honom, att han ville kalla honom till Jerusalem; och de satte försåt för honom, till att dräpa honom i vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Då svarade Festus, att Paulus skulle väl förvaras i Cesareen; men innan en kort tid ville han draga dit igen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'De som nu kunna ibland eder (sade han), komme ditned med oss, och klage då på honom, om de hafva något emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Och sedan han hade töfvat der när dem mer än i tio dagar, for han ned till Cesareen; och dagen derefter satt han för rätta, och lät Paulum komma fram.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Då han framkommen var, stodo de Judar kringom honom, som af Jerusalem nederkomne voro; och båro mång och svår klagomål före emot Paulum, som de icke bevisa kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Och han försvarade sig, att han intet brutit hade, hvarken emot Judalagen, eller emot templet, eller emot Kejsaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Då ville Festus göra Judomen till vilja, och svarade Paulo, och sade: Vill du fara upp till Jerusalem, och der härom stå till rätta för mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Sade Paulus: Jag står för Kejsarerätt, och der bör mig dömas; Judomen hafver jag ingen orätt gjort, såsom du ock sjelfver bäst vetst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Men hafver jag någrom gjort skada, eller något det döden värdt är begått, då vedersakar jag icke dö. Är det ock intet sådant, som de åklaga mig före, kan ingen gifva mig dem så bort; jag skjuter mig till Kejsaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Då hade Festus samtal med Rådet, och svarade: Till Kejsaren hafver du skjutit dig; till Kejsaren skall du ock fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Och då någre dagar voro framlidne, foro Konung Agrippa och Bernice ned till Cesareen, och skulle helsa Festum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Och medan de dvaldes der i många dagar, förtäljde Festus Konungenom Pauli sak, sägandes: Felix hafver låtit här efter sig en man fången;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Om hvilken, då jag kom till Jerusalem, underviste mig de öfverste Presterna, och Judarnas äldste, begärandes dom emot honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Och jag svarade dem: Det är icke de Romerskas sed bortgifva några mennisko till att förgöras, förr än den, som anklagad varder, hafver åklagarena jemte sig, och får rum till att försvara sig i sakene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Derföre, då de hitkommo, utan all fördröjelse, dagen derefter satt jag för rätta, och hade mannen före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Då åklagarena kommo före, båro de ingen sak fram, den jag hade tänkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Men de hade någor spörsmål med honom om sina vantro, och om en som kallades Jesus, den död var, och Paulus stod deruppå, att han lefde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Men då jag icke förstod mig i sakene, sade jag: om han ville fara till Jerusalem, och der stå till rätta derom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Och efter Paulus hade skottsmål, att Kejsaren skulle känna om hans sak, lät jag förvara honom, tilldess jag kunde sända honom till Kejsaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Då sade Agrippa till Festum: Jag ville ock gerna höra mannen. I morgon, sade han, skall du få höran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Dagen efter kom Agrippa och Bernice, med stor ståt, och gingo in på Rådhuset, med höfvitsmännerna, och de yppersta i staden; och vardt Paulus efter Festi befallning framhafder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Och sade Festus: Konung Agrippa, och I män alle, som med oss tillstädes ären: Här sen I den mannen, om hvilken hele hopen af Judarna hafver bedit mig, både i Jerusalem och här, ropandes att honom borde icke lefva länger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Men jag fann honom intet bedrifvit hafva, det döden värdt var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Men efter han sköt sig till Kejsaren, så aktar jag ock sända honom. Men hvad jag skall skrifva herranom om honom, det visst är, hafver jag icke; hvarföre hafver jag nu honom här fram för eder, och mest för dig, Konung Agrippa, att när derom ransakadt är, må jag hafva hvad jag skrifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Ty mig synes orätt vara att sända någon fången, och icke dermed gifva saken tillkänna, för hvilka han anklagad är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Då sade Agrippa till Paulum: Dig tillstädjes, att du talar för dig. Då räckte Paulus sina hand ut, och talade för sig:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Jag håller mig nu lycksaligan, att jag skall försvara mig i dag inför dig, Konung Agrippa, i all de stycker, der jag öfver anklagad varder af Judomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Aldramest medan jag vet, att du äst förståndig på de sedvänjor och spörsmål, som ibland Judarna äro; hvarföre beder jag dig, att du ville höra mig tåleliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Mitt lefverne ifrån ungdomen, huru det af begynnelsen ibland detta folk i Jerusalem varit hafver, veta alle Judar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Som mig förr känt hafva, om de vilja best ät; ty jag hafver varit en Pharisee, hvilket är det strängesta parti uti vår Gudstjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Och nu står jag här för rätten, för hoppets skull till det löfte, som skedt är till våra fäder af Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Till hvilket de tolf vår slägte förhoppas sig komma skola, tjenande Gudi stadeliga natt och dag; för detta hopps skull, Konung Agrippa, varder jag anklagad af Judomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Hvi varder det hållet af eder otroligit, om Gud uppväcker de döda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Jag mente väl hos mig sjelf, att jag mycket göra skulle, stridandes emot Jesu Nazareni Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Som jag ock gjorde i Jerusalem; och många heliga kastade jag i fängelse, dertill jag magt tagit hade af de öfversta Presterna; och då de dräpne vordo, förde jag domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Och i alla Synagogor pinade jag dem ofta, och nödgade dem till hädelse; och var dem så mycket ondsinnig, att jag förföljde dem ock uti de främmande städer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'För hvilka sak, när jag for till Damascum, med öfversta Presternas magt och förlof;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'Vid middagstid, o Konung, såg jag i vägen ett sken af himmelen, klarare än solskenet, skinandes kringom mig, och dem som med mig foro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Och när vi alle föllo ned till jordena, hörde jag ena röst tala till mig, och säga på Ebreisko: Saul, Saul, hvi förföljer du mig? Dig är svårt att spjerna emot udden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Då sade jag: Ho äst du. Herre? Sade han: Jag är Jesus, den du förföljer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Men res dig upp, och statt på dina fötter; ty dertill hafver jag uppenbarat mig för dig, att jag skall skicka dig till en tjenare och vittne om det du sett hafver; och desslikes om det jag dig ännu uppenbara skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Och vill frälsa dig för folket, och för Hedningarna, till hvilka jag nu sänder dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Att du skall öppna deras ögon, att de skola omvändas ifrå mörkret till ljuset, och ifrå Satans magt till Gud; att de skola få syndernas förlåtelse, och lott ibland dem som helgade äro, genom trona till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Så var jag icke ohörig den himmelska synene, Konung Agrippa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Utan begynte förkunna först för dem som voro i Damasco och Jerusalem, och öfver allt Judiska landet, och sedan desslikes Hedningomen, att de skulle bättra sig, och omvända sig till Gud, görandes sådana gerningar som bättring tillhörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'För den sakens skull grepo Judarna mig i templet, och bödo till att dräpa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Dock hafver jag njutit Guds hjelp dertill, att jag ännu står i denna dag, betygandes både små och stora; intet annat sägandes, än det Propheterna sagt hafva att ske skulle, och Moses:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Att Christus lida skulle, och vara den förste af de dödas uppståndelse, och förkunna ett ljus folkena och Hedningomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Då han nu sådant för sig svarat hade, sade Festus med höga röst: Du äst rasande, Paule; mycken konst hafver gjort dig rasande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Och sade han: Min gode Feste, jag är intet rasande; utan talar sann och förnuftig ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Ty Konungen vet detta väl, för hvilkom jag ock trösteliga talar; ty jag håller det så före, att intet deraf är honom fördoldt; ty det är icke skedt lönliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Tror du Propheterna, Konung Agrippa? Jag vet, att du tror.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Då sade Agrippa till Paulum: Fögo ting fattas, att du talar så för mig, att jag varder Christen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Och sade Paulus: Jag både väl af Gudi, ehvad der fattas fögo eller mycket uti, att ej allenast du, utan ock alle de, som mig höra i dag, vorde sådane som jag är, undantagne dessa banden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Och när han detta talat hade, stod Konungen upp, och landshöfdingen, och Bernice, och de som såto der med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Och vid de gingo afsides, talade de emellan sig, sägande: Denne mannen hafver intet gjort, det döden eller band värdt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Och sade Agrippa till Festum: Denne mannen måtte väl vordit lösgifven, hade han icke skjutit sig till Kejsaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Sedan nu beslutet var, att vi skulle segla till Valland, antvardade de Paulum och några andra fångar underhöfvitsmannenom, som het Julius, af den Kejserliga skaran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Och som vi stego uti ett Adramytiskt skepp, och skulle segla utmed Asien, lade vi af och med oss blef Aristarchus, en Macedonisk man, af Thessalonica.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Och dagen derefter lade vi till Sidon. Och Julius for väl med Paulo, och tillstadde att han gick till sina vänner, och lät göra sig till godo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Och när vi lade dädan, seglade vi utmed Cypren; ty vädret var oss emot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Och seglade vi öfver hafvet, som är emot Cilicien och Pamphylien, och kommom intill Myra, som är i Lycien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Och der fick höfvitsmannen ett skepp, som var af Alexandria, och segla skulle till Valland; der satte han oss in.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Och då vi långsamliga seglat hade i många dagar, och som nogast komma kunde in mot Gnidum för motväders skull, seglade vi in under Creta, vid Salmone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Och kommom som nogast framom, och intill ett rum, som kallades Sköna hamn; och var staden Lasea icke långt derifrå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Då nu mycken tid var förlupen, och seglatsen begynte vara farlig, derföre att ock fastan var allaredo förliden, förmanade Paulus dem,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Och sade till dem: I män, jag ser, att seglatsen vill vara med vedermödo, och stor skada, icke allenast till skepp och gods, utan jemväl på vårt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Men höfvitsmannen trodde skepparenom och styrmannenom, mer än det Paulus sade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Och efter der var icke hamn till att ligga i vinterläge, föllo de mesta parten på det rådet att lägga dädan, att de, om någorlunda ske kunde, måtte komma till Phenicien, och ligga der i vinterläge; den hamnen är på Creta, för sydvest och nordvest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Och som nu sunnanväder begynte blåsa, mente de hafva efter sin vilja; och då de lade ifrån Asson, seglade de utmed Creta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Men icke långt efter stack sig upp emot dem ett iligt väder, som kallas nordost.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Och då skeppet vardt begripet, och kunde icke begå sig för vädret, låte vi drifva för vädret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Och kommom under ena ö, som kallas Clauda, och kundom med plats få in båten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Då de tagit den upp, brukade de hjelp, och bundo skeppet; och då de fruktade att det skulle komma på sandrefvelen, kastade de ut ett hinderfat, och läto så vräka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Och som stormen gick oss svårliga uppå, kastade de dagen derefter godset ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Och tredje dagen kastade vi skeppredskapen ut med vara händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Och då hvarken sol eller stjernor syntes i många dagar, och stormen låg oss svårliga uppå, var oss allt hopp borto om vår välfärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Och då de nu i lång tid intet ätit hade, stod Paulus upp midt ibland dem, och sade: I män, det hade väl tillbörligit varit, att I haden hört mig, och icke lagt ifrån Creta, och icke kommit oss denna vedermödon och skadan uppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Och nu förmanar jag, att I varen vid ett godt mod; ty ingom af eder skall något skada till lifvet, utan allena skeppet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Ty i denna nattene stod Guds Ängel när mig, den jag tillhörer, och den jag dyrkar, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Frukta dig intet, Paule, du måste komma fram för Kejsaren; och si, Gud hafver gifvit dig alla de som segla med dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Derföre varer vid ett godt mod, I män; ty jag tror Gudi, att så sker, som mig sagdt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Uppå ena ö skole vi vräkne varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Då fjortonde natten kom, och vi forom uti Adria, vid midnattstid, tycktes skeppmännerna att dem syntes ett land;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Och kastade ut lodet, och funno tjugu famnar djup; och kommo litet länger fram, och kastade åter lodet, och funno femton famnar djup.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Och så fruktade de, att de skulle komma på något skarpt grund, och kastade fyra ankare ut af bakskeppet, och önskade att dagas skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Då sökte skeppmännerna efter, huru de skulle komma sina färde utu skeppet, och kastade ut båten i hafvet, under det sken, att de ville föra ut ankare af framskeppet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Då sade Paulus till höfvitsmannen och till krigsknektarna: Utan desse blifva i skeppet, så varden icke I behållne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Då höggo krigsknektarna af fästona till båten, och läto honom fara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Och som dagen begynte synas, rådde Paulus dem allom, att de skulle få sig mat, och sade: Detta är fjortonde dagen att I hafven förbidt, och blifvit fastande, och hafven intet tagit till eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Hvarföre råder jag eder, att I fån eder mat; ty det hörer edra välfärd till; ty ingens edars ett hår skall falla af hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Och när han det sagt hade, tog han brödet, och tackade Gud i allas deras åsyn; och då han det brutit hade, begynte han äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Då vordo de alle vid ett bättre mod, och begynte ock de äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Och vi voro i skeppet, alle tillhopa, tuhundrade sex och sjutio själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Och då de voro mätte, lättade de skeppet, och kastade ut hvete i hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'När dager vardt, kände de intet landet; men de vordo varse ena vik, i hvilko en strand var, dit de mente vilja låta drifva skeppet, om de kunde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Och när de hade upptagit ankaren, gåfvo de sig till sjös, och upplöste roderbanden, och hade upp seglet till väders, och läto gå åt strandene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Dock kommo de på en refvel, och skeppet stötte; och framskeppet blef ståndandes fast orörligit; men bakskeppet lossades af vågene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Men krigsknektarna tyckte råd vara slå fångarna ihjäl, att, då de utsummo, icke skulle någor undfly.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Men höfvitsmannen ville förvara Paulum, och stillte dem ifrå det rådet, och bad att de, som simma kunde, skulle gifva sig först ut åt landet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'Och de andre, somlige på bräder, och somlige på skeppsvraket. Och dermed skedde, att de undsluppo alle behållne i land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Och då de undkomne voro, fingo de veta, att ön het Melite.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Och folket beviste oss icke liten äro, undfångandes oss alla; och upptände en god eld, för regnets skull som oss öfverkommet var, och för köldens skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Och då Paulus bar tillhopa en hop med ris, och lade på elden, kröp en huggorm ut ifrå värman, och stack hans hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Men då folket såg ormen hängandes vid hans hand, sade de emellan sig: Denne mannen måste vara en mandråpare, hvilken hämnden icke tillstäder lefva, ändock han nu undkommen är för hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Men han skuddade ormen i elden, och honom skadde der intet af.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Men de mente ske skola, att han skulle uppsvälla, eller straxt falla neder och dö. Då de länge vänte derefter, och sågo att honom intet ondt vederfors, vände de sig uti ett annat sinne, och sade att han var en gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Och der icke långt ifrå hade den öfverste öfver öna, benämnd Publius, en afvelsgård; den undfick oss till herberge, och for väl med oss i tre dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Och hände sig, att Publii fader låg sjuk i skälfvosot och bukref; till honom gick Paulus in, och när han hade bedit, lade han händer på honom, och gjorde honom helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Och då det var skedt, kommo ock andre, de som sjukdom hade der på öne, och gingo fram, och vordo helbregda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Hvilke oss gjorde mycken äro; och när vi forom våra färde dädan, läto de komma in med oss hvad nödtorftigt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Efter tre månader seglade vi vara färde uti ett skepp ifrån Alexandria, som der under ön hade legat i vinterläge; uti hvilkets baner stod Castor och Pollux.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Och när vi kommom till Syracusa, blefvo vi der i tre dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Dädan seglade vi omkring, och kommom till Regium. Och en dag derefter blåste sunnanväder upp, så att vi kommom den andra dagen derefter till Puteolos.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Och efter vi funne der bröder, vorde vi bedne, att vi skulle blifva när dem i sju dagar; och så komme vi till Rom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Och då bröderna fingo höra om oss, gingo de emot oss intill Appii forum, och till Tretabern. När Paulus dem såg, tackade han Gudi, och tog tröst till sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Och när vi kommom in i Rom, öfverantvardade underhöfvitsmannen fångarna öfverhöfvitsmannenom; men Paulo vardt tillstadt vara för sig sjelf, med en krigsknekt som tog vara på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Efter tredje dagen kallade Paulus tillhopa de yppersta af Judarna. Och när de kommo, sade han till dem: I män och bröder, ändock jag intet gjort hade emot vårt folk, eller emot fädernas stadgar, vardt jag likväl bunden öfverantvardad utur Jerusalem i de Romares händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Hvilke, då de mig ransakat hade, ville de släppt mig, efter ingen dödssak fanns med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Men efter Judarna sade deremot, nödgades jag skjuta mig till Kejsaren; icke så att jag något hafver, der jag vill anklaga mitt folk före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'För denna sakens skull hafver jag kallat eder, att jag måtte se eder, och tala med eder; ty för Israels hopps skull är jag ombunden med denna kedjon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Då sade de till honom: Vi hafve hvarken fått bref om dig af Judeen; ej heller hafver någor af bröderna dädan kommit, och bebådat oss, eller talat något ondt om dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Och begäre vi nu af dig höra, huru du det hafver före; ty om detta partit är oss veterligit, att allestäds sägs deremot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Och då de hade satt honom en dag före, kommo de en stor hop till honom i herberget, hvilkom han uttydde och betygade Guds rike, och gaf dem före om Jesu, utaf Mose lag, och utaf Propheterna, ifrå morgonen intill aftonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Och somlige trodde det som sades; och somlige trodde det icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Och som de icke drogo öfverens, gingo de dädan, då Paulus dem ett ord sagt hade att den Helge Ande rätt talat hafver till våra fäder, genom Propheten Esaias,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Sägandes: Gack till detta folket, och säg: I skolen höra med öronen, och icke förståt; och se med ögonen, och icke kunna besinnat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Ty detta folks hjerta är förhärdt, och de höra svårliga med sin öron, och sin ögon hafva de igenlyckt; att de icke någon tid skola se med ögonen, och höra med öronen, och förstå med hjertat, att de måtte omvändas, att jag dem hela måtte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Så skall eder nu vetterligit vara, att denna Guds salighet är sänd till Hedningarna, och de skola hörat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Och när han hade det sagt, gingo Judarna ut ifrå honom, och hade emellan sig mycken disputering.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Men Paulus blef i hela tu år uti det hus han lejt hade, och undfick alla de som ingingo till honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Predikandes Guds rike, och lärde om Herran Jesu, med all tröst; och ingen förböd honom det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paulus, Jesu Christi tjenare, kallad till Apostel, afskild till att predika Guds Evangelium;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Hvilket han tillförene utlofvat hafver, genom sina Propheter i den Helga Skrift,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Om sin Son, den född är af Davids säd, efter köttet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Hvilken är krafteliga bevisad Guds Son, efter Andan som helgar, deraf att han stod upp ifrå de döda, nämliga Jesus Christus, vår Herre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Genom hvilken vi hafve fått nåd, och Apostlaämbete, till att upprätta trones lydno ibland alla Hedningar, i hans Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Ibland hvilka I ock ären kallade af Jesu Christo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Allom dem som i Rom äro, Guds kärestom, kalladom heligom. Nåd vare med eder, och frid af Gudi vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'I förstone tackar jag min Gud, gjenom Jesum Christum, för eder alla, att i hela verldene talas om edra tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Ty Gud är mitt vittne, hvilkom jag tjenar i minom anda, uti Evangelio som är om hans Son, att jag utan återvändo tänker på eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Bedjandes alltid i mina böner, att jag dock någon tid måtte få en lyckosam väg, om Gud ville, till att komma till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Ty jag åstundar se eder, på det jag måtte några andeliga gåfvo dela med eder, till att styrka eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Det är, att jag, samt med eder, måtte få hugsvalelse, genom begges våra tro, edra och mina.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Jag vill icke dölja för eder, bröder, att jag hafver ofta haft i sinnet komma till eder, ändock jag hafver varit förhindrad allt härtill; på det jag måtte ock någon frukt skaffa ibland eder, såsom ibland andra Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Jag är pligtig både Greker och Barbarer, både visa och ovisa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Derföre, så mycket mig står till görandes, är jag redebogen att jag ock predikar eder Evangelium, som i Rom ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Ty jag skämmes icke vid Christi Evangelium; ty det är Guds kraft allom dem till salighet som tro; Judomen först, så ock Grekomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Derföre att derutinnan varder Guds rättfärdighet uppenbar, af tro i tro; som skrifvet är: Den rättfärdige skall lefva af sine tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Ty Guds vrede af himmelen varder uppenbar öfver alla menniskornas ogudaktighet och orättfärdighet, de der förhålla sanningena i orättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Ty det, som förstås kan om Gud, är dem uppenbart; ty Gud hafver dem det uppenbarat;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Dermed att hans osynliga väsende, och hans eviga kraft och Gudom varder beskådad, när de besinnas af gerningarna, nämliga af verldenes skapelse; så att de äro utan ursäkt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Medan de förstodo Gud, och hafva icke prisat honom som en Gud, och ej heller tackat; utan vordo fåfängelige i sina tankar, och deras oförnuftiga hjerta är vordet mörkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Då de höllo sig för visa, äro de vordne dårar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Och hafva förvandlat dens oförgängeliga Guds härlighet uti beläte, det ej allenast gjordt var efter förgängeliga menniskors, utan jemväl efter foglars, och fyrafött och krypande djurs liknelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Derföre hafver ock Gud öfvergifvit dem i deras hjertans lustar, uti orenlighet, till att skämma sin lekamen inbördes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Hvilke förvandlat hafva Guds sanning i lögn; och hafva ärat och dyrkat de ting, som skapad äro, öfver honom som dem skapat hafver, hvilken är välsignad evinnerliga. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Derföre hafver ock Gud öfvergifvit dem i skamliga lustar; ty deras qvinnor hafva förvandlat den naturliga brukningena uti den, som är emot naturen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Sammaledes ock männerna hafva öfvergifvit den naturliga qvinnones brukning, och hafva brunnit i sin lusta till hvarannan; man med man bedrifvit slemhet, och fått, som tillbörligit var, deras villos rätta lön i sig sjelfvom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Och såsom de intet aktade hafva Gud i känslo, hafver Gud öfvergifvit dem i ett vrångt sinne, till att bedrifva obeqvämlig ting;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Fulle med all orättfärdighet, boleri, arghet, girighet, ondsko; fulle med afund, mord, kif, svek, otukt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Örnatasslare, bakdantare, Guds föraktare, våldsverkare, högfärdige, stolte, illfundige, föräldromen olydige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Oförnuftige, ordlöse, okärlige, trolöse, obarmhertige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Hvilke, ändå de Guds rättviso veta, att de som sådant göra äro värde döden, likväl göra de det icke allenast, utan ock hålla med dem som det göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Derföre äst du utan ursäkt, o menniska, eho du äst som dömer. Ty med det samma du dömer en annan, fördömer du dig sjelf, efter du gör det samma som du dömer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Ty vi vete, att Guds dom är rätt öfver dem som sådana göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Eller menar du, o menniska, som dömer dem som sådana göra, och gör detsamma, att du skall kunna undfly Guds dom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Eller föraktar du hans godhets, tålsamhets och långmodighets rikedom, icke förståndandes, att Guds mildhet lockar dig till bättring?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Utan efter dina hårdhet och obotfärdiga hjerta samkar du dig sjelfvom vrede, på vredenes dag, när Guds rättvisa dom blifver uppenbar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Hvilken gifva skall hvarjom och enom efter hans gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Nämliga pris och äro, och oförgängeligit väsende dem, som med tålamod, uti goda gerningar, fara efter evigt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Men dem som enträtne äro, och icke vilja lyda sanningene, utan lyda orätthetene, ogunst och vrede;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Bedröfvelse och ångest öfver hvar och en menniskos själ, som illa gör; först Judarnas, Grekernas också.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Men heder, och ära, och frid hvarjom och enom som väl gör; först Judomen, Grekomen också.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Ty Gud ser icke efter personen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Alle de som utan lag syndat hafva, de varda ock utan lag förtappade; och alle som uti lagen hafva syndat, de varda med lagen dömde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Ty de äro icke rättfärdige för Gudi, som höra lagen; utan de som göra efter lagen, de varda rättfärdige hållne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Derföre, om Hedningarna, som icke hafva lagen, göra dock af naturen det lagen innehåller; desamme, ändock de icke hafva lagen, äro de likväl sig sjelfvom lag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Hvilke bevisa lagsens verk vara skrifvet i deras hjertan, der deras samvet bär dem vittne, och deras tankar, som sig inbördes anklaga eller ock ursaka;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'På den dagen, när Gud menniskornas lönligheter döma skall, genom Jesum Christum, efter mitt Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Si, du kallas en Jude, och förlåter dig på lagen, och berömmer dig af Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'Och vetst hans vilja; och efter du äst undervister i lagen, profvar du hvad bäst är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Och betröster dig vara en ledare dem som blinde äro, och dem ett ljus som i mörkret äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Dem en tuktomästare, som dåraktige äro; dem en lärare, som enfaldige äro; och hafver formen till det som vetandes och rätt är i lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Nu lärer du andra, och lärer dig intet sjelf. Du predikar: Man skall intet stjäla; och du stjäl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Du säger: Man skall icke göra hor; och du bedrifver hor. Du stygges vid afguderi; och du beröfvar Gudi det honom tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Du berömmer dig af lagen, och vanhedrar Gud med lagsens öfverträdning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Ty för edra skull varder Guds Namn försmädadt ibland Hedningarna, såsom skrifvet är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Omskärelsen doger, om du håller lagen; men håller du icke lagen, så är din omskärelse vorden en förhud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Om nu förhuden håller lagsens rättfärdighet, månn icke hans förhud blifva räknad för omskärelse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Och dermed sker då, att det som af naturen är förhud, och fullkomnar lagen, skall döma dig, som under bokstafven och omskärelsen bryter lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Ty det är icke Jude, som utvärtes är Jude; ej heller det omskärelse, som utvärtes sker på köttet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Utan det är Jude, som invärtes dolder är; och hjertans omskärelse är omskärelse, den som sker i andanom, och icke efter bokstafven; hvilkens pris icke är af menniskom, utan af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Hvad fördel hafva då Judarna? Eller hvad är omskärelsen nyttig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Jo, ganska mycket. Först, att dem hafver varit betrodt det Gud talat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Hvad magt ligger derpå, att somlige af dem icke trodde? Skulle deras otro göra Guds trohet om intet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Bort det. Vare heldre Gud sannfärdig, och hvar och en menniska lögnaktig; såsom skrifvet är: På det du blifver rättfärdig i din ord, och öfvervinner, när du dömes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Är det nu så, att vår orättfärdighet prisar Guds rättfärdighet; hvad vilje vi säga? Är då Gud orättfärdig, som vredgas deröfver? Jag talar efter menniskosätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Bort det; ty huru kunde Gud då döma verldena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Ty om Guds sanning vorde yppare af mine lögn, honom till pris, hvi skulle jag då ännu dömas som en syndare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Och icke heldre göra, såsom vi vardom försmädde, och som någre säga, att vi skole säga: Låt oss göra ondt, på det der kommer godt af; hvilkas fördömelse är all rätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Huru är då derom? Hafve vi någon fördel för dem? Allsingen. Ty vi hafve det nu bevisat, att både Judar och Greker äro alle under synd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Som skrifvet står: Den är icke till som rättfärdig är; icke en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Ingen är ock den som förståndig är; ingen är som aktar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Alle hafva afvikit; allesamman äro onyttige vordne; ingen är som godt gör; icke till en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Deras strupe är en öppen graf; deras tungor bruka de till svek; huggormaetter under deras läppar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Deras mun är full med bannor och bitterhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Deras fötter snare till att utgjuta blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Förtryckelse och vedermöda i deras vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Och fridsens väg veta de icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Guds räddhåge är icke för deras ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Så vete vi, att allt det lagen säger, det säger hon till dem som under lagen äro; att hvar och en mun skall tillstoppas, och all verlden skall för Gudi brottslig varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Derföre, att intet kött kan af lagsens gerningar varda rättfärdigt för honom; ty af lagen känner man syndena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Men nu är Guds rättfärdighet, utan lagsens tillhjelp, uppenbar vorden, bevist genom lagen och Propheterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Den Guds rättfärdighet, säger jag, som kommer af Jesu Christi tro, till alla, och öfver alla de som tro; ty här är ingen åtskilnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Allesamman äro de syndare, och hafva intet berömma sig af för Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Och varda rättfärdige utan förskyllan, af hans nåd, genom den förlossning som i Christo Jesu skedd är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Hvilken Gud hafver satt för en nådastol, genom trona i hans blod, i hvilko han låter se sina rättfärdighet, i thy att han förlåter synderna, som blefna voro under Guds tålamod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Till att låta se i denna tiden sina rättfärdighet; på det han allena skall vara rättfärdig, och göra den rättfärdigan, som är af Jesu tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Hvar är nu din berömmelse? Hon är utelyckt. Med hvad lag? Med gerningarnas lag? Nej; utan med trones lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Så hålle vi nu det, att menniskan varder rättfärdig af trone, utan lagsens gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Eller är Gud allenast Judarnas Gud? Är han ock icke Hedningarnas Gud? Jo visserliga, ock Hedningarnas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Efter det en Gud är, som gör omskärelsen rättfärdig af trone, och förhudena genom trona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Göre vi då lagen om intet med trone? Bort det; utan vi upprättom lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Hvad säge vi då vår fader Abraham efter köttet hafva funnit?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Det säge vi: Är Abraham rättfärdig vorden af gerningarna, så hafver han det han må berömma sig af; men icke för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Men hvad säger Skriften? Abraham trodde Gudi, och det vardt honom räknadt till rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Men honom, som håller sig vid gerningarna, varder lönen icke räknad af nåd, utan af pligt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Men honom, som icke håller sig vid gerningarna, utan tror på honom som den ogudaktiga gör rättfärdigan, hans tro varder honom räknad till rättfärdighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Såsom ock David säger, att saligheten är dens menniskos, hvilko Gud tillräknar rättfärdighetena, utan gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Salige äro de, som deras orättfärdigheter äro förlåtna, och deras synder äro öfverskylda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Salig är den man, som Gud ingen synd tillräknar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Månn nu denna saligheten allenast vara kommen öfver omskärelsen, eller ock öfver förhudena? Vi säge ju, att Abrahe vardt tron räknad till rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Huru blef hon honom då tillräknad? När han var i omskärelsen, eller när han var i förhudene? Icke i omskärelsen, utan i förhudene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Men han tog omskärelsens tecken för ett insegel till trones rättfärdighet, hvilka han hade i förhudene; att han skulle vara allas deras fader, som i förhudene trodde, att sådant skulle ock räknas dem för rättfärdighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Desslikes ock omskärelsens fader, icke dem allenast, som äro af omskärelsen, utan ock dem som vandra i trones fotspår, som var i vår faders Abrahams förhud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Ty det löftet, att han skulle varda verldenes arfvinge, är icke skedt Abrahe och hans säd igenom lagen, utan igenom trones rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Ty om de, som lyda till lagen, äro arfvingar, så är tron onyttig vorden, och löftet är blifvet om intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Ty lagen kommer vrede åstad; ty der ingen lag är, der är icke heller öfverträdelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Derföre måste det vara af trone, att det skall vara af nåd, och löftet fast blifva allo sädene; icke honom allenast som är af lagen, utan ock honom som är af Abrahams tro, hvilken är allas våra fader;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'Som skrifvet är: Jag hafver satt dig till en fader öfver många Hedningar, för Gudi, den du trott hafver, hvilken de döda gör lefvande, och kallar de ting, som icke äro, lika som de voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Och han trodde på det hopp, der intet hopp var, att han skulle varda många Hedningars fader, som sagdt var till honom: Så skall din säd vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Och han vardt icke svag i trone, och aktade icke sin halfdöda kropp, ty han var när hundrade åra gammal; ej heller Saras halfdöda qved;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Ty han tviflade intet på Guds löfte med otro; utan vardt stark i trone, gifvandes Gudi ärona;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Och var full viss derpå, att den som lofvade, han var ock mägtig det att hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Derföre var det ock räknadt honom till rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Så är detta icke allenast skrifvet för hans skull, att honom tillräknadt vardt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Utan ock för våra skull, som det också tillräknadt varder, när vi trom på honom, som vår Herra Jesum uppväckte ifrå de döda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Hvilken för våra synders skull är utgifven, och för våra rättfärdighets skull uppväckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Medan vi nu rättfärdige vordne äro af trone, hafve vi frid med Gud, genom vår Herra Jesum Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Genom hvilken vi hafve ock en tillgång i trone till denna nåd, som vi uti ståm, och berömmom oss af hoppet, som vi hafve, till den härlighet som Gud gifva skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Och icke det allenast; utan vi berömmom oss ock i bedröfvelsen, vetande att bedröfvelse gör tålamod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Och tålamod gör förfarenhet; förfarenhet gör hopp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Men hoppet låter icke komma på skam; ty Guds kärlek är utgjuten i vår hjerta, genom den Helga Anda som oss gifven är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Ty ock Christus, den stund vi ännu svage vorom efter tiden, hafver lidit döden för oss syndare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Nu vill näppliga någor dö för det som rätt är; för det som godt är torde tilläfventyrs någor dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Derföre beprisar Gud sin kärlek till oss att Christus är död för oss, när vi ännu vore syndare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Så varde vi ju mycket mer behållne genom honom för vredene, efter vi äre rättfärdige gjorde i hans blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Ty efter vi vordom förlikte med Gudi, genom hans Sons död, den stund vi ännu voro ovänner; mycket mer, efter vi äre förlikte, blifve vi nu behållne genom hans lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Icke allenast det; utan vi berömmom oss ock af Gudi, genom vår Herra Jesum Christum, genom hvilken vi nu förlikningen fått hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Derföre, såsom igenom ena mennisko är synden kommen i verlden, och för syndenes skull döden; och är så döden kommen öfver alla menniskor, efter de alle syndat hafva,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Ty synden var väl i verldene allt intill lagen; men der ingen lag är, der aktas icke synden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Utan döden var väldig, allt ifrån Adam intill Mosen, öfver dem ock, som icke hade syndat i sådana öfverträdelse som Adam, hvilken är hans liknelse som tillkommande var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Men det hafver sig icke så med gåfvone, som med syndene; ty om igenom ens (menniskos) synd äro månge döde, så är mycket mer Guds nåd och gåfva mångom rikeliga vederfaren genom Jesum Christum, som den ena menniskan var i nådene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Och är icke gåfvan allenast öfver ena synd, såsom förderfvet är kommet fördens ena syndarens ena synd; ty domen är kommen af ene synd till fördömelse, men gåfvan af många synder till rättfärdighet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Ty om döden hafver, för ens synds skull, väldig varit igenom en; mycket mer skola de, som undfå nådenes och gåfvones fullhet till rättfärdighet, vara väldige i lifvena genom en, Jesum Christum,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Ty såsom för ens synds skull, är fördömelse kommen öfver alla menniskor; så kommer ock, igenom ens rättfärdighet, lifsens rättfärdning öfver alla menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Ty såsom, för ene menniskos olydno, äro månge vordne syndare; så varda ock, för ens lydnos skull, månge rättfärdige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Men lagen är också härmed inkommen, att synden skulle öfverflöda; men der synden öfverflödde, der öfverflödde då nåden mycket mer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'På det att, såsom synden hafver väldig varit till döden, så skulle ock nåden väldig vara genom rättfärdighetena till evinnerligit lif, genom Jesum Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Hvad vilje vi Då säga? Skole vi blifva i syndene, på det nåden skall öfverflöda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Bort det; vi som äre döde ifrå syndene, huru skulle vi ännu lefva i henne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Veten I icke, att alle vi som äre döpte till Christum Jesum, vi äre döpte till hans död?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Så äro vi ju begrafne med honom, genom dopet, i döden; att såsom Christus är uppväckt ifrå de döda, genom Fadrens härlighet, så skole ock vi vandra i ett nytt lefverne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Ty om vi, samt med honom, inplantade vardom till en lika död, så varde vi ock uppståndelsen like;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Vetande att vår gamla menniska är korsfäst med honom, på det att syndakroppen skall varda om intet, att vi icke härefter skola tjena syndene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Ty den som döder är, han är rättfärdigad ifrå syndene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Äre vi nu döde med Christo, så tro vi, att vi ock skole lefva med honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Vetande, att Christus, som ifrå de döda uppväckt är, dör intet mer; döden får intet mer magt öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Ty det han blef död, blef han syndene död en gång; men det han lefver, lefver han Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Så håller ock I eder derföre, att I ären döde syndene, och lefven Gudi, genom Christum Jesum, vår Herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Så låter nu icke syndena väldig vara i eder dödeliga lekamen, så att I henne efterföljen uti hennes lustar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Och gifver icke syndene edra lemmar till orättfärdighetenes vapen; utan gifver eder sjelfva Gudi, lika som de der döde hafva varit, och nu lefva; och edra lemmar Gudi, till rättfärdighetenes vapen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Ty synden skall icke vara väldig öfver eder; efter I ären icke under lagen, utan under nådene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Huru då? Skole vi synda, medan vi äre icke under lagen, utan under nådene? Bort det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Veten I icke, att hvem I gifven eder för tjenare till att lyda, hans tjenare ären I, som I lydige ären, ehvad det är mer syndene, till döden, eller lydnone, till rättfärdighetena?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Men lofvad vare Gud, att I hafven varit syndenes tjenare, och ären dock af hjertat lydige vordne, uti den lärdoms eftersyn, som I ären gifne till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Men nu, medan I ären friade ifrå syndene, ären I rättfärdighetenes tjenare vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Jag talar härom efter menniskors sätt, för edra köttsliga skröplighets skull; lika som I hafven edra lemmar gifvit orenlighet ene och orättfärdighetene till tjenst, ifrå den ena orättfärdighetene till den andra; så gifver ock nu edra lemmar rättfärdighetene till tjenst, att de måga varda helige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Ty då I voren syndenes tjenare, då voren I frie ifrå rättfärdighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Hvad gagn haden I då af det, der I nu blygens vid? Ty till sådant är döden ändalykten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Men nu, medan I ären frie vordne ifrå syndene, och vordne Guds tjenare, hafven I edor frukt, att I helige varden; och till ändalykt, evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Ty syndenes lön är döden; men Guds gåfva är det eviga lifvet, genom Christum Jesum, vår Herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Veten I icke, käre bröder (ty jag talar med dem som lagen veta), att lagen regnerar öfver menniskona, så länge hon lefver?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Ty en qvinna, som i mans våld är, så länge mannen lefver, är hon bunden till lagen; men om mannen dör, så blifver hon lös ifrå mansens lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Men om hon är med en annan man, medan hennes man lefver, då varder hon kallad en horkona; men dör mannen, så är hon fri ifrå lagen, att hon icke varder en horkona, om hon är när en annan man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Så ären ock I, mine bröder, dödade ifrå lagen, genom Christi Lekamen; att I skolen vara när enom androm, nämliga när honom som är uppstånden ifrå de döda, på det vi skole göra Gudi frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Ty Då vi vorom köttslige, då voro de syndiga begärelser, som lagen uppväckte, mägtig i våra lemmar, att göra dödenom frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Men nu äre vi friade ifrå lagen, döde ifrå henne som oss höll fångna; så att vi skole tjena uti ett nytt väsende, efter andan, och icke uti det gamla väsendet, efter bokstafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Hvad vilje vi då säga? Är lagen synd? Bort det; men syndena kände jag icke, utan af lagen; ty jag hade intet vetat af begärelsen, hade icke lagen sagt: Du skall icke begära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Då tog synden tillfälle af budordet; och uppväckte i mig all begärelse; ty utan lagen var synden död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Och jag lefde fordom utan lag; men när budordet kom, fick synden lif igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Och jag vardt död; så fanns då, att budordet, som mig var gifvet till lifs, det var mig till döds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Ty synden tog tillfälle af budordet, och besvek mig, och drap mig dermed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Så är väl lagen helig, och budordet heligt, och rättfärdigt, och godt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Är då det, som godt är, vordet mig till döds? Bort det; men synden, på det hon skulle synas vara synd, hafver, med det godt är, verkat döden i mig; på det synen skulle varda öfvermåtton syndig genom budordet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Ty vi vete, att lagen är andelig; men jag är köttslig, sålder under syndena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Ty jag vet icke hvad jag gör; ty jag gör icke hvad jag vill; utan det jag hatar, det gör jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Om jag nu gör det jag icke vill, så samtycker jag, att lagen är god.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Så gör icke nu jag det, utan synden, som bor i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Ty jag vet, att i mig, det är, i mitt kött, bor icke godt; viljan hafver jag, men att göra godt, det finner jag icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Ty det goda, som jag vill, det gör jag intet; utan det onda, som jag icke vill, det gör jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Om jag nu gör det jag icke vill, så gör icke nu jag det, utan synden, som bor i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Så finner jag nu mig en lag, jag som vill göra det godt är, att det onda låder vid mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Ty jag hafver lust till Guds lag, efter den invärtes menniskona;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Men jag ser en annor lag i mina lemmar, som strider emot den lag, som i min håg är, och griper mig fången uti syndenes lag, som är i mina lemmar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Jag arme menniska, ho skall lösa mig ifrå denna dödsens kropp?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Gudi tackar jag, genom Jesum Christum, vår Herra. Så tjenar jag nu Guds lag med hågen; men med köttet tjenar jag syndenes lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Så är nu intet fördömeligit i dem som äro i Christo Jesu, de icke vandra efter köttet, utan efter Andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Ty Andans lag, som lif gifver i Christo Jesu, hafver gjort mig fri ifrå syndenes och dödsens lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Ty det som lagen icke kunde åstadkomma, i det hon vardt försvagad af köttet, det gjorde Gud, sändandes sin Son i syndelig kötts liknelse, och fördömde syndena i köttet genom synd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'På det den rättfärdighet, som lagen äskar, skulle varda fullbordad i oss, som icke vandrom efter köttet, utan efter Andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Ty de som köttslige äro, de äro köttsliga sinnade; men de som andelige äro, de äro andeliga sinnade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Ty köttsens sinne är döden; men Andans sinne är lif och frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Ty köttsligit sinne är en fiendskap emot Gud; efter det är icke Guds lag underdånigt; icke kan det heller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Men de, som äro köttslige, kunna icke vara Gudi täcke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Men I ären icke köttslige, utan andelige, om Guds Ande annars bor i eder; ty hvilken icke hafver Christi Anda, han hörer icke honom till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Men om Christus är i eder, så är väl lekamenen död, för syndenes skull; men Anden är lifvet, för rättfärdighetenes skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Om nu hans Ande, som Jesum uppväckte ifrå de döda, bor i eder, så skall ock den, som Christum uppväckte ifrå de döda, göra edor dödeliga lekamen lefvande, för sin Andas skull, som i eder bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Så äre vi nu, käre bröder, skyldige, icke köttena, att vi skole lefva efter köttet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Ty om I lefven efter köttet, så skolen I dö; men om I döden köttsens gerningar med Andanom, så skolen I lefva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Ty alle de som drifvas af Guds Anda, de äro Guds barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Ty I hafven icke fått träldomsens anda, åter till räddhåga; utan I hafven fått utkorada barns Anda, i hvilkom vi rope: Abba, käre Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Den samme Anden vittnar med vår Anda, att vi äre Guds barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Äre vi nu barn, så äre vi ock arfvingar; nämliga Guds arfvingar, och Christi medarfvingar; om vi annars lidom med honom, att vi ock med honom komma mågom till härligheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Ty jag håller det så före, att denna tidsens vedermöda är icke lika emot den härlighet, som på oss uppenbaras skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Ty kreaturens högeliga åstundan väntar efter, att Guds barn skola uppenbaras;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Efter kreaturen äro vanskelighetene underkastade emot sin vilja; men för hans skull, som dem underkastat hafver, på en förhoppning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Ty kreaturen skola ock varda fri af förgängelighetenes träldom, till Guds barnas härliga frihet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Ty vi vete, att hvart och ett kreatur suckar och ängslas med oss, allt härtill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Och icke de allenast; utan ock vi sjelfve, som hafvom Andans förstling, suckom ock vid oss sjelfva efter barnaskapet, och väntom vår kropps förlossning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Ty vi äre väl salige vordne, dock i hoppet; men hoppet, om det synes, är det icke hopp; ty huru kan man hoppas det man ser?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Om vi nu hoppes det vi icke sem, så vänte vi det med tålamod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Sammaledes hjelper ock Anden våra skröplighet; ty vi vete icke hvad vi skolom bedja, såsom det bör sig; utan sjelfver Anden manar godt för oss, med osägeliga suckan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Men han, som skådar hjertan, han vet hvad Andans sinne är; ty han manar för helgonen, efter Guds behag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Men vi vete att dem, som hafva Gud kär, tjena all ting till det bästa, de som efter uppsåtet äro kallade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Ty hvilka han hafver föresett, dem hafver han ock beskärt, att de skulle vara hans Sons beläte like; på det han skall vara den förstfödde ibland många bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Men dem som han hafver beskärt, dem hafver han ock kallat; och dem han hafver kallat, dem hafver han ock gjort rättfärdiga; men dem som han hafver gjort rättfärdiga, dem hafver han ock gjort härliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Hvad vilje vi nu säga härtill? Är Gud för oss, ho kan vara emot oss?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Hvilken ock icke hafver skonat sin egen Son, utan gifvit honom ut för oss alla; huru skulle han icke ock gifva oss all ting med honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Hvilken vill åklaga dem som Gud hafver utkorat? Gud är den som rättfärdigar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Hvilken är den som vill fördöma? Christus är den som lidit hafver döden; ja, han är ock den som uppväckt är; den ock sitter på Guds högra hand, och manar godt för oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Ho kan skilja oss ifrå Christi kärlek? Bedröfvelse, eller ångest, eller förföljelse, eller hunger, eller nakenhet, eller farlighet, eller svärd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Såsom skrifvet är: För dina skull vardom vi dödade hela dagen; vi vardom hållne såsom slagtofår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Men i allt detta öfvervinne vi, genom honom som oss älskat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Ty jag är viss derpå, att hvarken död, eller lif, eller Änglar, eller Förstadöme, eller väldigheter, eller de ting som nu äro, eller de ting som tillkomma skola;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'Eller höghet, eller djuphet, eller något annat kreatur, skall skilja oss ifrå Guds kärlek, som är i Christo Jesu, vårom Herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Jag säger sanningen i Christo, och ljuger icke; som mitt samvete bär mig der vittne till i dem Helga Anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Att jag hafver ena stora sorg, och idkeliga pino i mitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Ty jag hafver sjelfver önskat mig bortkastad ifrå Christo, för mina bröders skull, som mig köttsliga skylde äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Hvilke äro af Israel, hvilkom barnaskapet tillhörer, och härligheten, och förbundet, och lagen, och Gudstjensten, och löften;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Hvilkas äro fäderna, der Christus af födder är, på köttsens vägnar; hvilken är Gud öfver all ting, lofvad evinnerliga. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Detta säger jag icke fördenskull, att Guds ord äro omintet vorden; ty de äro icke alle Israeliter, som äro af Israel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Icke äro de heller alle söner, att de äro Abrahams säd; utan i Isaac skall dig kallas säden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Det är: Icke äro de Guds barn, som äro barn efter köttet, utan de som äro barn efter löftet, de varda räknade för säd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Ty detta är löftesordet: Jag skall komma i denna tiden; och Sara skall hafva en son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Och icke allenast det; utan ock Rebecka vardt en gång hafvandes af Isaac, vårom fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Ty förr än barnen voro född, och hade hvarken godt eller ondt gjort (på det Guds uppsåt skulle blifva ståndandes efter utkorelsen, icke för gerningarnas skull, utan af kallarens nåde),');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Vardt denne sagdt: Den större skall tjena dem mindre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Såsom skrifvet är: Jacob älskade jag men Esau hatade jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Hvad vilje vi då säga? Är Gud orättfärdig? Bort det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Ty han säger till Mosen: Hvilkom jag är nådelig, honom är jag nådelig; och öfver hvilken jag förbarmar mig, öfver honom förbarmar jag mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Så står det nu icke till någors mans vilja eller lopp, utan till Guds barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Ty Skriften säger till Pharao: Dertill hafver jag uppväckt dig, att jag skall bevisa mina magt på dig; och att mitt Namn skall varda förkunnadt i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Så förbarmar han nu sig öfver hvem han vill, och hvem han vill, förhärdar han.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Så må du säga till mig: Hvad skyllar han då oss? Ho kan stå emot hans vilja?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'O menniska, ho äst du som vill träta med Gud? Icke säger det ting, som gjordt är, till sin mästare: Hvi hafver du gjort mig sådana?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Hafver icke en pottomakare magt att göra af en klimp ett kar till heder, och det andra till vanheder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Derföre, då Gud ville låta se vredena, och kungöra sina magt, hafver han med stor tålsamhet lidit vredsens kar, som äro tillredd till fördömelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'På det han skulle kungöra sina härlighets rikedom på barmhertighetenes kar, som han hafver tillredt till härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Hvilka han ock kallat hafver, nämliga oss, icke allenast af Judomen, utan ock af Hedningomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Såsom han ock säger genom Oseas: Det som icke var mitt folk, det skall jag kalla mitt folk; och den mig intet kär var, skall jag kalla min kära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Och det skall ske, att der som hafver varit sagdt till dem: I ären icke mitt folk; der skola de varda kallade lefvandes Guds barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Men Esaias ropar för Israel: Om talet på Israels barn än vore som sanden i hafvet, så skola dock de igenlefde varda salige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Ty han skall väl låta förderfva dem, och dock likväl stilla det förderfvet till rättfärdighet; ty Herren skall stilla förderfvet på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Och såsom Esaias sade tillförene: Hade icke Herren Zebaoth igenleft oss säd, då hade vi varit såsom Sodoma, och lika som Gomorra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Hvad vilje vi då säga? Det säge vi: Hedningarna, som icke farit hafva efter rättfärdighetene, de hafva fått rättfärdigheten; den rättfärdighet menar jag, som af trone kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Men Israel, som for efter rättfärdighetenes lag, kom icke till rättfärdighetenes lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Hvarföre? Derföre att de icke sökte det af trone, utan såsom af lagsens gerningar; ty de stötte sig på förtörnelsestenen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Såsom skrifvet är: Si, jag lägger i Zion en förtörnelsesten, och ena förargelseklippo: och hvar och en som tror på honom, skall icke komma på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Bröder, mins hjertas begär och bön till Gud är för Israel, att de måtte varda salige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Ty jag bär vittne med dem, att de hafva nit om Gud; dock icke visliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Ty de förstå icke Guds rättfärdighet; utan fara efter att upprätta sin egen rättfärdighet, och äro så icke Guds rättfärdighet undergifne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Ty Christus är lagsens ände, till rättfärdighet hvarjom och enom som tror.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Moses skrifver om den rättfärdighet som kommer af lagen, att hvilken menniska som det gör, hon lefver deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Men den rättfärdighet, som är af trone, säger så: Säg icke i ditt hjerta: Ho vill fara upp i himmelen? Det är, att hemta Christum härned.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Eller, ho vill fara ned i djupet? Det är, att hemta Christum upp igen ifrån de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Men hvad säger (Skriften)? Ordet är hardt när dig, nämliga i dinom mun, och i ditt hjerta. Detta är det ordet om trona, som vi predikom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Ty om du bekänner med dinom mun Jesum, att han är Herren, och tror i ditt hjerta att Gud hafver uppväckt honom ifrå de döda, så varder du salig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Ty med hjertans tro varder man rättfärdig, och med munsens bekännelse varder man salig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Ty Skriften säger: Hvar och en, som tror på honom, skall icke komma på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Det är ingen åtskilnad emellan Juda och Grek; ty en Herre är öfver alla, riker öfver alla dem som åkalla honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Ty hvar och en, som åkallar Herrans namn, skall varda salig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Men huru skola de åkalla den de hafva icke trott på? Och huru skola de tro honom, som de hafva intet hört af? Och huru skola de höra utan predikare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Och huru skola de predika, utan de varda sände? såsom skrifvet är: O! huru ljuflige äro deras fötter, som frid förkunna, deras som godt förkunna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Men de äro icke alle Evangelio lydige; ty Esaias säger: Herre, ho tror vår predikan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Så är tron af predikanen; men predikanen genom Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Så säger jag nu: Hafva de icke hört det? Deras ljud är ju utgånget i all land, och deras ord till verldenes ändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Men jag säger: Hafver då Israel det icke fått veta? Den förste Moses säger: Jag skall uppväcka eder till nit med det folk, som icke är folk; och med ett galet folk skall jag reta eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Dristar ock Esaias sig till, och säger: Jag är funnen af dem, som intet sökte mig, och är vorden uppenbar dem, som intet sporde efter mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Men till Israel säger han: Hela dagen hafver jag uträckt mina händer till det otrogna och genstörtiga folket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Så säger jag nu: Hafver Då Gud bortkastat sitt folk? Bort det; ty jag är ock en Israelit, af Abrahams säd, af BenJamins slägte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Gud hafver icke bortkastat sitt folk, som han hade föresett tillförene. Eller veten I icke hvad Skriften säger om Elias? huru han går fram för Gud emot Israel, och säger:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Herre, de hafva dräpit dina Propheter, och hafva slagit ned din altare; och jag är allena igenblifven, och de fara efter mitt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Men hvad säger honom Guds svar? Jag hafver mig igenleft sjutusend män, som icke hafva böjt sin knä för Baal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Så är det ock i denna tiden med de igenlefda, efter nådenes utkorelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Är det nu af nåd, så är det icke af gerningom; annars vore nåd icke nåd; är det ock af gerningom, så är det nu icke nåd; annars är gerning icke gerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Huru äret då? Det Israel söker, det får han icke; men utkorelsen får det; de andre äro förblindade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'Såsom skrifvet är: Gud hafver gifvit dem en förbittrad anda; ögon, att de icke se skola, och öron, att de icke höra skola allt härtilldags.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Och David säger: Låt deras bord varda en snaro, och till bekajelse, och till förargelse, och dem till deras rätta lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Varde deras ögon förblindad, att de icke se; och böj deras rygg alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Så säger jag nu: Hafva de då fördenskull stött sig, att de skulle falla? Bort det; men af deras fall hände Hedningomen salighet, på det att han dermed skulle uppväcka dem till nit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Är nu deras fall verldenes rikedom, och deras förminskelse är Hedningarnas rikedom; huru mycket mer deras fullhet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Eder Hedningomen säger jag: Efter det jag är Hedningarnas Apostel, prisar jag mitt ämbete;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Om jag kunde någorledes uppväcka dem, som mitt kött äro, till nit, och göra några saliga af dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Ty om deras bortkastelse är verldenes försoning, hvad blifver Då deras upptagelse annat än lif ifrå de döda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Är förstlingen helig, så är ock väl hele degen helig och om roten är helig, så äro ock qvistarna helige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Om nu någre af qvistarna äro afbrutne, och du, som var ett vildoljoträ, blef der inympad igen, och äst vorden delaktig af oljoträns rot och fetma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Så beröm dig icke emot qvistarna. Om du berömmer dig, så bär ju icke du rotena, utan roten bär dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Så säger du då: Qvistarna äro afbrutne, på det jag skulle inympas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Sant säger du; de äro afbrutne för otrones skull; men du äst ståndandes genom trona; var icke för stolt i ditt sinne, utan var i räddhåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Ty hafver Gud de naturliga qvistar icke skonat, se till, att han icke heller skonar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Så se nu här Guds godhet och stränghet; strängheten på dem som föllo, och godheten på dig, så framt du blifver i godhetene; annars varder du ock afhuggen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Och de inympas igen, om de icke blifva i otrone; ty Gud är mägtig åter inympa dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Ty äst du af ett naturligit vildoljoträ afhuggen, och förutan naturen inympad uti ett sannskyldigt oljoträ; huru mycket mer måga de, som naturlige qvistar äro, inympas uti sitt eget oljoträ?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Käre bröder, jag vill icke fördölja eder denna hemlighet, på det I icke skolen högmodas vid eder sjelfva, att blindheten är Israel endels vederfaren, tilldess Hedningarnas fullhet inkommen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'Och så varder hele Israel salig; såsom skrifvet är: Af Zion skall den komma som fria skall, och afvända ogudaktigheten af Jacob.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Och detta är mitt Testament med dem, då jag borttager deras synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Efter Evangelium håller jag dem för ovänner, för edra skull; men efter utkorelsen hafver jag dem kär, för fädernas skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Ty Guds gåfvor och kallelse äro sådana, att han kan dem icke ångra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Ty såsom ock I fordom icke trodden på Gud, och hafven dock nu öfver deras otro fått barmhertighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Så hafva ock nu de icke velat tro på den barmhertighet, som eder vederfaren är, att dem måtte ock barmhertighet vederfaras.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Ty Gud hafver allt beslutit under otro, på det han skall förbarma sig öfver alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O! hvilken djuphet af den rikedom, som är både i Guds visdom och kunskap; huru obegripelige äro hans domar, och oransakelige hans vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Ty ho hafver känt Herrans sinne? Eller ho hafver varit hans rådgifvare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Eller ho hafver gifvit honom något tillförene, det honom skall betaladt varda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Ty af honom, och igenom honom, och i honom äro all ting; honom vare ära i evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Så förmanar jag nu eder, käre bröder, vid Guds barmhertighet, att I utgifven edor lekamen till ett offer, som är lefvande, heligt och Gudi behageligit, edra skäliga Gudstjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Och håller eder icke efter denna verldena; utan förvandler eder med edars sinnes förnyelse, att I mågen förfara hvad Guds gode, behaglige och fullkomlige vilje är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Ty jag säger, igenom den nåd som mig gifven är, hvarjom och enom af eder, att ingen hålle mer af sig, än honom bör hålla; utan hålle sig så, att der är måtta med, efter som Gud hafver utdelat hvarjom och enom trones mått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Ty såsom vi uti en lekamen hafve många lemmar, men alle lemmar hafva icke allt samma ämbete;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Så äre vi nu månge en lekamen i Christo, men inbördes äre vi hvarsannars lemmar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Och hafve åtskilliga gåfvor, efter den nåd som oss gifven är. Hafver någor Prophetiam, så vare hon ens med trone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Hafver någor ett ämbete, så akte han derpå; lärer någor, så akte han på lärona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Förmanar någor, så akte han på förmaningen; gifver någor, så gifve uti enfaldighet; regerar någor, så regere med omsorg; gör någor barmhertighet, så göre det med fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Kärleken vare utan skrymtan; hater det onda, blifvandes vid det godt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Varer hvar med annan vänlige, uti broderlig kärlek; den ene förekomme den andra med inbördes heder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Varer icke tröge uti det I hafven för händer; varer brinnande i Andanom; skicker eder efter tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Varer glade i hoppet; tålige i bedröfvelse; håller på bedja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Deler edart till de heligas nödtorft; herberger gerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Taler väl om dem som gå efter edart argasta; taler väl, och önsker dem icke ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Glädjens med dem som glade äro; och gråter med dem som gråta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Ens till sinnes med hvarannan; håller icke mycket af eder sjelfva; utan håller eder lika vid dem som ringa äro; håller eder icke sjelfva för kloka,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Görer ingom ondt för ondt; vinnlägger eder om det som ärligit är, inför hvar man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Om möjeligit är, så mycket som till eder står, så hafver frid med alla menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Hämnens eder icke sjelfve, käre vänner; utan låter (Guds) vrede hafva rum; ty det är skrifvet: Min är hämnden, jag skall vedergällat, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Om nu din ovän hungrar, så gif honom mat; törster han, så gif honom dricka; när du det gör, så församlar du glödande kol på hans hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Låt dig icke öfvervunnen varda af det onda; utan öfvervinn det onda med det goda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Hvar och en vare Öfverhetene, som väldet hafver, underdånig; ty ingen Öfverhet är, utan af Gudi; den Öfverhet, som är, hon är skickad af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Derföre, ho sig sätter emot Öfverheten, han sätter sig emot Guds skickelse; men de som sätta sig deremot, de skola få en dom öfver sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Ty de, som väldet hafva, äro icke dem till räddhåga som väl göra, utan dem som illa göra. Vill du icke frukta för Öfverheten, så gör det godt är, så får du pris af honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Ty han är Guds tjenare, dig till godo. Men gör du det ondt är, så må du rädas; ty han bär icke svärdet förgäfves; utan han är Guds tjenare, en nämnare honom till straff, som illa gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Fördenskull måste man vara underdånig, icke allenast för straffets skull, utan ock för samvetets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Derföre måsten I ock gifva skatt; ty de äro Guds tjenare, som sådant skola sköta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Så gifver nu hvarjom och enom det I pligtige ären; dem skatt, som skatt bör; dem tull, som tull bör; dem rädsel, som rädsel tillhörer; dem heder, som heder tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Varer ingom något skyldige, utan att I älskens inbördes; ty den som älskar den andra, han hafver fullbordat lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Ty det som sagdt är: Du skall icke göra hor; du skall icke dräpa; du skall icke stjäla; du skall icke bära falskt vittne; du skall icke begära; och annat sådant bud, det beslutes i detta ordet: Du skall älska din nästa som dig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Kärleken gör sin nästa intet ondt. Så är nu kärleken lagsens fullbordan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Och medan vi sådant vete, nämliga tiden, att nu är stunden till att uppstå af sömnen, efter vår salighet är nu närmer, än då vi troddet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Natten är framfaren, och dagen är kommen; derföre låter oss bortkasta mörksens gerningar, och ikläda oss ljusens vapen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Låter oss ärliga vandra, såsom om dagen; icke i fråsseri och dryckenskap; icke i kamrar och okyskhet; icke i kif och nit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Utan ikläder eder Herran Jesum Christum; och fordrer köttet, dock icke till kättja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Den svaga i trone tager upp; och bekymrer icke samvetet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Den ene tror, att han må allahanda äta; men den som svag är, han äter kål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Den der äter, han förakte icke honom som icke äter, och den som icke äter, han döme icke honom som äter; ty Gud hafver honom upptagit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Ho äst du, som dömer en annars tjenare? Sinom egnom herra står han eller faller; men han kan väl varda ståndandes; ty Gud är väl mägtig till att göra honom ståndandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Den ene gör åtskilnad emellan dag och dag; den andre håller alla dagar lika; hvar och en vare viss i sitt sinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Hvilken som aktar någon dag, det gör han Herranom; och hvilken icke aktar någon dag, han gör det ock Herranom. Hvilken som äter, han äter Herranom; ty han tackar Gudi. Den der icke äter, han icke äter Herranom, och tackar Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Ty ingen af oss lefver sig sjelfvom; och ingen dör sig sjelfvom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Lefve vi, så lefve vi Herranom; dö vi, så dö vi Herranom; ehvad vi nu lefve eller dö, så höre vi Herranom till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Ty Christus är derpå både död och uppstånden, och åter lefvandes vorden, att han skall vara Herre, både öfver lefvande och döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Men du, hvi dömer du din broder? Eller du andre, hvi föraktar du din broder? Ty vi måste alle stå framför Christi domstol;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Såsom skrifvet står: Så sant som jag lefver, säger Herren, mig skola all knä böjas; och alla tungor skola bekänna Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Så måste nu hvar och en af oss göra Gudi räkenskap för sig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Derföre, låt oss nu icke mera döma hvarannan; utan dömer heldre så, att ingen förtörnar sin broder, eller förargar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Jag vet väl, och är dess viss i Herranom Jesu, att ingen ting äro af sig sjelf menlig; utan den som håller det för menligit, honom är det menligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Dock, om din broder varder bedröfvad öfver din mat, så vandrar du allaredo icke efter kärleken. Förderfva icke, med din mat, den som Christus hafver lidit döden före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Derföre flyr det så, att edart goda icke varder undergifvet menniskors förtal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Ty Guds rike är icke mat eller dryck, utan rättfärdighet, och frid, och fröjd i dem Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Den der uti tjenar Christo, han är Gudi täck, och menniskomen bepröfvad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Så låt oss nu fara efter det som till frids tjenar, och det som tjenar till förbättring inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Förderfva icke, för mats skull, Guds verk. All ting äro väl ren; men honom är det icke godt, som äter med sitt samvets förkränkelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Godt är dig, att du äter intet kött, eller dricker intet vin; ej heller något der din broder stöter sig på, eller förargas, eller försvagas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Hafver du tron, så haf henne när dig sjelf för Gudi. Salig är den som sig intet samvet gör, om det han bepröfvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Men den som tvifvelaktig är, äter han, så är han fördömd; ty han äter icke af tron; ty allt det icke går af trone, det är synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Skole ock vi, som starke äre, draga deras skröplighet, som svage äro, och icke täckas oss sjelfvom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Så skicke sig hvar och en af oss, att han måtte täckas sin nästa till godo, till förbättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Ty ock Christus täcktes icke sig sjelfvom; utan såsom skrifvet står: Deras försmädelser, som dig försmäda, hafva fallit öfver mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Ty hvad som helst föreskrifvet är, det är skrifvet oss till lärdom; att vi, genom tålamod och Skriftenes tröst, skole hafva en förhoppning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Men Gud, som tålamod och trösten gifver, gifve eder, att I ären inbördes ens till sinnes, efter Christum Jesum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Att I med enom håg, och med enom mun, mågen prisa Gud, och vårs Herras Jesu Christi Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Derföre upptager hvar den andra, såsom ock Christus hafver upptagit oss till Guds äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Men jag säger, att Jesus Christus var omskärelsens tjenare, för Guds sannings skull, till att fast göra de löften, som till fäderna skedde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'Men att Hedningarna skola ära Gud, för barmhertighetenes skull; såsom skrifvet är: Fördenskull skall jag prisa dig ibland Hedningarna, och sjunga dino Namne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Och åter säger han: Glädjens, I Hedningar, med hans folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Och ändå sedan: Lofver Herran, alle Hedningar, och priser honom, all folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Och åter säger Esaias: Det skall vara Jesse rot, och den som uppstå skall att råda öfver Hedningarna; på honom skola Hedningarna hoppas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Men Gud, som hoppet gifver, uppfylle eder med alla fröjd och frid i trone, att I hafven ett fullkommeligit hopp, genom dens Helga Andas kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Mine bröder, jag vet väl sjelf af eder, att I ären fulle af godhet, uppfyllde med all kunskap, förmående förmana hvar den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Dock likväl, bröder, hafver jag skrifvit eder endels dristeliga till, att kommat eder till sinnes, för den nåds skull, som mig gifven är af Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Att jag skall vara Jesu Christi tjenare ibland Hedningarna, offrandes Guds Evangelium; att Hedningarne skola varda ett offer, Gudi anammeligit, helgadt genom den Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Derföre hafver jag, der jag må berömma mig af, igenom Christum Jesum, i det Gudi tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Ty jag dristar icke något tala, det icke Christus verkade igenom mig, till att göra Hedningarna lydaktiga, genom ord och gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'Genom teckens och unders kraft, och genom Guds Andas kraft; så att ifrån Jerusalem, och de land deromkring ligga, allt intill Illyricum, hafver jag uppfyllt med Christi Evangelium;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Och beflitat mig att predika Evangelium, der Christus icke ens hade varit nämnd, på det jag icke skulle bygga på ens annars grund;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Utan, såsom skrifvet står: Dem som intet hafver kungjordt varit om honom, de skola det se; och de som af honom intet hört hafva, de skola det förstå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Det är ock saken, hvarföre jag ofta hafver varit förhindrad att komma till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Nu, efter jag icke mer rum hafver i dessa landen, och hafver dock i mång år åstundat komma till eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Då jag reser ut i Hispanien, vill jag komma till eder; ty jag hoppas att, då jag reser derigenom, skall jag få se eder, och sedan varda af eder hulpen dit att komma; dock att jag ju först någon lust hafver haft af edor umgängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Men nu far jag hädan till Jerusalem, till att göra dem heligom tjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Ty de som bo uti Macedonien, och Achajen, hafva belefvat göra någon undsättning dem fattigom heligom, som äro i Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Ty de hafva så belefvat, och äro dem ock pligtige; fördenskull, att efter de hafva delat med Hedningarna sin andeliga ting, är tillbörligit, att de äro dem till tjenst med deras lekamliga ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Då jag nu beställt hafver, och förseglat dem denna frukt, vill jag komma tillbaka igen, och genom edar (stad) fara till Hispanien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Men jag vet, när jag kommer till eder, varder jag kommandes med Christi Evangelii fullkomliga välsignelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Men, käre bröder, jag förmanar eder genom vår Herra Jesum Christum, och igenom Andans kärlek, att I mig uti mitt arbete hjelpen, med edra böner för mig till Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Att jag må frälst varda ifrå de otrogna i Judeen; och att min tjenst, som jag gör i Jerusalem, må anammelig varda dem heligom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Att jag må med glädje komma till eder, genom Guds vilja, och vederqvicka mig med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Men fridsens Gud vare med eder allom. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Jag befaller eder våra syster Phebe, hvilken är i församlingenes tjenst i Kenchrea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Att I henne undfången i Herranom, såsom helgon höfves; och görer henne bistånd i all ärende, der hon eder behöfver; ty hon hafver mångom, och jemväl mig sjelfvom, varit till godo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Helser Priscilla, och Aqvila, mina hjelpare i Christo Jesu;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Hvilke för mitt lif hafva vågat sin hals; dem tackar icke allenast jag, utan ock alla Hedningars församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Helser ock församlingena i deras hus; helser Epenetus, min älskeliga, hvilken var den första frukt i Achajen, i Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Helser Maria, den der mycket arbete för oss haft hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Helser Andronicus, och Junia, mina fränder och medfångar, de der märkelige äro ibland Apostlarna; de der ock för mig voro i Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Helser Amplia, min älskeliga i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Helser Urbanus, vår hjelpare i Christo, och Stachis, min älskeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Helser Apellen, den der bepröfvad är i Christo; helser dem som äro af Aristobuli hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Helser Herodion, min frända; helser dem som äro af Narcissi hus, i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Helser Tryphena och Tryphosa, de der arbeta i Herranom; helser Persiden, mina älskeliga, som mycket arbetat hafver i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Helser Rufum, den utkorada i Herranom; och hans moder, och mina.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Helser Asyncritum, Phlegontem, Herman, Patroban, Hermen, och de bröder som med dem äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Helser Philologum, och Julian, Nereum, och hans syster, och Olympan, och all helgon när dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Helser eder inbördes med en helig kyss; helsa eder Christi församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Käre bröder, jag förmanar eder, att I hafven uppseende på dem, som tvist och förargelse åstadkomma, emot den lärdom som I hafven lärt; och viker ifrå dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Ty sådane tjena icke Herranom Jesu Christo, utan sinom buk; och igenom söt ord och smekande tal förföra deras hjerta, som menlöse äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Ty edar lydaktighet är utkommen till hvar man. Derföre fröjdar jag mig öfver eder; men jag vill, att I ären vise på det goda, och enfaldige på det onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Men fridsens Gud förträde Satanam under edra fötter snarliga. Vårs Herras Jesu Christi nåd vare med eder. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Helsar eder Timotheus, min medhjelpare, och Lucius, och Jason, och Sosipater, mine fränder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Helsar jag Tertius eder, som brefvet skrifvit hafver, i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Helsar eder Gajus, min och hela församlingenes värd; helsar eder Erastus, stadsens räntomästare, och Qvartus, brodren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Vårs Herras Jesu Christi nåd vare med eder allom. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Men honom, som magt hafver att stadfästa eder, efter mitt Evangelium, och predikan af Jesu Christo, efter hemlighetenes uppenbarelse, den af evig tid härtill hafver förtegad varit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Men nu uppenbarad och kungjord, igenom Propheternas skrifter, af eviga Guds befallning; på det tron skall få lydaktighet ibland alla Hedningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Gudi, som är allena vis, vare pris och ära, genom Jesum Christum, i evighet. Amen. Till de Romare, sänd ifrå Corintho, med Phebe, som i församlingenes tjenst var i Kenchrea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paulus, kallad till Jesu Christi Apostel, genom Guds vilja, och Sosthenes, broderen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Guds församling, som är i Corintho, dem helgadom genom Christum Jesum, kalladom heligom; samt med allom dem som åkalla vårs Herras Jesu Christi Namn, uti hvart och ett rum, deras och vårt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Nåd vare eder, och frid af Gudi vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Jag tackar min Gud alltid för edra skull, för den Guds nåd, som eder gifven är genom Christum Jesum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Att I uti all stycke rike vordne ären genom honom, i all ord, och all kunskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Såsom predikanen om Christo i eder kraftig vorden är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Så att eder icke fattas någor gåfva, och vänten vårs Herras Jesu Christi uppenbarelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Hvilken eder ock stadfäster intill ändan, att I ostraffelige ären på vårs Herras Jesu Christi dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Ty Gud är trofast, genom hvilken I kallade ären till hans Sons Jesu Christi, vårs Herras, delaktighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Men, käre bröder, jag förmanar eder, vid vårs Herras Jesu. Christi Namn, att I talen alle ett, och att ibland eder ingen tvedrägt är; utan att I ären fullborda uti ett sinne och ene mening.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Ty mig är förekommet, mine bröder, om eder, med dem som tjena Chloe, att ibland eder äro trätor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Men jag säger, som hvar och en af eder säger: Jag är Paulisk, jag är Apollisk, jag är Cephisk, och jag är Christisk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Månn Christus vara söndrad? Månn Paulus vara korsfäst för eder? Eller ären I döpte i Pauli namn?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Jag tackar Gud, att jag ingen edra döpt hafver, utan Crispum, och Gajum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Att ingen kan säga, att jag hafver i mitt namn döpt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Desslikes döpte jag Stephane husfolk; sedan vet jag icke, om jag någon annan döpt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Ty Christus hafver icke sändt mig till att döpa, utan till att förkunna Evangelium; icke med klokt tal, på det Christi kors icke skulle omintet varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Ty det tal om korset är en galenskap dem som förtappas; men oss, som salige vardom, är det en Guds kraft;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Ty skrifvet är: Jag skall omintet göra de visas visdom, och de förståndigas förstånd skall jag förkasta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Hvar äro de kloke? Hvar äro de Skriftlärde? Hvar äro denna verldenes vise? Hafver icke Gud denna verldenes vishet gjort till galenskap?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Ty efter verlden icke kunde genom sin visdom känna Gud i hans visdom, så täcktes Gudi med dåraktiga predikan frälsa dem som tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Efter det Judarna begära tecken, och Grekerna söka efter vishet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Men vi predike den korsfästa Christum, Judomen en förargelse, och Grekomen en galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Men dem samma, Judom och Grekom, som kallade äro, predike vi Christum, Guds kraft, och Guds visdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Ty Guds galenskap är visare än menniskor, och Guds svaghet är starkare än menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Käre bröder, ser på edor kallelse; icke månge köttsliga vise, icke månge mägtige, icke månge ädlingar äro kallade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Men det, som galet var för verldene, hafver Gud utvalt, på det han skulle göra de visa till skam; och det svagt var för verldene hafver Gud utvalt, på det han skulle göra det till skam som starkt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Och det, som var oädla, och föraktadt för verldene, hafver Gud utvalt, och det intet är; på det han skulle göra det till intet, som något är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'På det intet kött skall kunna berömma sig för honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Af hvilkom I ock ären i Christo Jesu, den oss af Gudi är gjord till visdom, och till rättfärdighet, och till helgelse, och till förlossning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'På det, som skrifvet står: Den som berömmer sig, han berömme sig i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Och jag, käre bröder, då jag kom till eder, kom jag icke med hög ord, eller hög visdom, att förkunna eder Guds vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Ty jag höll mig icke derföre, att jag något visste ibland eder, utan Jesum Christum, och honom korsfästan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Och jag var med eder i svaghet, och med räddhåga, och med mycket bäfvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Och mitt tal och min predikan var icke i konstelig ord, efter menniskors visdom, utan uti Andans och kraftenes bevisning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Att edor tro icke skall stå på menniskors visdom, utan på Guds kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Men det vi tale om, är visdom när de fullkomliga; dock icke denna verldenes, eller denna verldenes öfverstars visdom, hvilke förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Men vi tale om den hemliga fördolda Guds visdom, den Gud för verldenes begynnelse förskickat hafver, till våra härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Hvilken ingen af denna verldenes Förstar känt hafver; ty om de den känt hade, så hade de aldrig korsfäst härlighetenes Herra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Utan såsom skrifvet är: Det intet öga sett hafver, och intet öra hört, och uti ingen menniskos hjerta stiget är, det hafver Gud beredt dem som honom älska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Men oss hafver Gud det uppenbarat genom sin Anda; ty Anden utransakar all ting; Ja, ock Guds djuphet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Ty hvilken menniska vet hvad i menniskone är, utan menniskones ande som är i henne? Så vet ock ingen hvad i Gudi är, utan Guds Ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Men vi hafve icke fått denna verldenes anda, utan den Anda som är af Gudi, att vi veta kunne, hvad oss af Gudi gifvet är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Hvilket vi ock tale, icke med sådana ord som mennisklig visdom lärer, utan med sådana ord som den Helige Ande lärer; och dömom andeliga saker andeligen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Men den naturliga menniskan förnimmer intet af det Guds Anda tillhörer; ty det är honom en galenskap, och kan icke begripat; ty det måste andeliga dömas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Men den andelige dömer all ting, och varder af ingom dömd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Ty ho hafver känt Herrans sinne? Eller ho vill undervisa honom? Men vi hafve Christi sinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Och jag, käre bröder, kunde icke tala med eder, såsom med andeligom, utan såsom med köttsligom, såsom med barnom i Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Mjölk hafver jag gifvit eder dricka, och icke mat; ty I förmåtten det icke; ej heller ännu förmågen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Fördenskull I ären ännu köttslige; ty medan ibland eder är nit, och kif, och tvedrägt, ären I icke då köttslige, och vandren efter menniskosätt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Ty då en säger: Jag är Paulisk, och den andre säger: Jag är Apollisk; ären I icke då köttslige?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Ho är nu Paulus, ho är Apollos, annat än tjenare, genom hvilka I hafven anammat tron, och dock som Herren hafver hvarjom och en om gifvit?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Jag hafver plantat, Apollos hafver vattnat; men Gud hafver gifvit växten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Så är nu han intet, som plantar; icke heller han, som vattnar, utan Gud, som växten gifver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Men den som plantar, och den som vattnar, den ene är som den andre; men hvar och en skall få sin lön efter sitt arbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Ty vi äre Guds medhjelpare; I ären Guds åkerverk, Guds byggning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Jag, af Guds nåde, som mig gifven är, hafver lagt grundvalen, såsom en vis byggomästare, en annar bygger deruppå; men hvar och en se till, huru han bygger deruppå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Ty en annan grund kan ingen lägga, än den som lagder är, hvilken är Jesus Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Hvar nu någor bygger på denna grund guld, silfver, ädla stenar, trä, hö, strå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Så varder hvars och ens verk uppenbart; ty dagen skall görat klart, hvilken i elden uppenbar varder; och hurudana hvars och ens verk är, det skall elden bepröfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Varder någors verk blifvandes, som han deruppå byggt hafver, så får han lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Men varder någors verk förbrändt, så varder han straffad; men han sjelfver varder salig, dock såsom genom eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Veten I icke, att I ären Guds tempel, och att Guds Ande bor i eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Hvilken Guds tempel förderfvar, honom skall Gud förderfva; ty Guds tempel är heligt, hvilket I ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Ingen bedrage sig sjelf. Hvilken ibland eder låter sig tycka att han är vis, han varde galen i denna verld, att han må varda vis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Ty denna verldenes vishet är galenskap för Gudi; efter som skrifvet är: Han griper de visa uti deras klokhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Och åter: Herren vet de visas tankar, att de äro fåfängelige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Så berömme sig ingen af menniskor; allt är det edart;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Vare sig Paulus, eller Apollos, vare sig Cephas, eller verlden, vare sig lifvet, eller döden, vare sig det nu är, eller det komma skall; allt är det edart.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Men I ären Christi; och Christus är Guds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Der skall man hålla oss fore, att vi äre Christi tjenare, och skaffare till Guds hemlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Nu söker man intet ibland skaftarena annat, än att de finnas måga trogne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Men mig är det en ringa ting, att jag varder dömd af eder, eller af mennisklig dag; dömer jag mig icke heller sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Jag vet intet med mig; dock derutinnan är jag icke rättfärdigad, men Herren är den mig dömer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Derföre dömer icke förr än tid är, så länge att Herren kommer, hvilken ock skall låta komma det i ljuset, som i mörkrena fördoldt är, och uppenbara hjertans anslag; och då varder hvarjom och enom pris af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Men detta hafver jag, käre bröder, uttydt på mig, och på Apollos, för edra skull, att I af oss lära måtten, att ingen hålle mer af sig, än som nu skrifvet är; på det I icke högmodens emot hvarannan för någors mans skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Ty ho framsätter dig? Eller hvad hafver du, det du icke undfått hafver? Hafver du det undfått, hvi berömmer du dig då, lika som du det icke undfått hade?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'I ären nu mätte, I ären nu rike vordne, I regneren utan oss; och gåfve Gud att I regneraden, på det vi ock måtte regnera med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Men mig tycker, att Gud hafver utgifvit oss Apostlar för de aldraringasta, såsom de der dödenom äro ämnade; ty vi äre vordne ett vidunder verldene, och Änglomen, och menniskomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Vi äre dårar, för Christi skull, men I ären kloke i Christo; vi svage, I starke; I härliga, vi föraktade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Allt intill denna tid lide vi både hunger och törst, och äro nakne, och varde kindpustade, och hafve intet visst hemman;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Och arbetom, verkande med våra egna händer. Då vi blifve bannade, välsigne vi; då vi blifve förföljde, lide vi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Då vi blifve hädde, bedjes vi före; såsom verldenes afskrap äre vi vordne, hvars mans afhugg, till denna dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Detta skrifver jag icke fördenskull, att jag vill skämma eder; men jag förmanar eder, såsom min kära barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Ty om I än haden tiotusend tuktomästare i Christo, så hafven I dock icke många fäder; jag hafver födt eder i Christo Jesu, genom Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Derföre förmanar jag eder: Varer mine efterföljare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'För samma saks skull hafver jag sändt till eder Timotheum, hvilken är min käre son, och trogen i Herranom; att han skall draga eder till minnes mina vägar, som äro i Christo, såsom jag allestäds och i alla församling lärer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Somlige af eder äro så uppblåste, lika som jag icke skulle komma till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Men jag vill innan en kort tid komma, om Herren vill; och då skall jag röna, icke deras ord, som så uppblåste äro, utan kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Ty Guds rike står icke i ordom, utan i kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Hvad viljen I? Skall jag komma med ris till eder, eller med kärlek och saktmodigom anda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Det går ett allmänneligit rykte, att boleri är ibland eder; och sådant boleri, der ock icke Hedningarne veta af säga, att en hafver sins faders hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Och I ären uppblåste, der I mycket heldre skullen hafva sörjt; på det att den sådant bedrifvit hafver, måtte utkastas ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Men jag, såsom den med kroppen frånvarandes är, dock med andan närvarandes, hafver allaredo såsom närvarandes beslutit,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'I vårs Herras Jesu Christi Namn, uti edor församling, med minom anda, och samt med vårs Herras Jesu Christi kraft,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Att den, som det så bedrifvit hafver, skall gifvas Satane i våld, till köttsens förderf; på det anden må salig blifva på Herrans Jesu dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Edor berömmelse är icke god. Veten I icke, att litet surdeg försyrer hela degen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Renser fördenskull ut den gamla sur degen, att I mågen blifva en ny deg, såsom I ock ären osyrade; ty vi hafve ock ett Påskalamb, som är Christus, offrader för oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Derföre låter oss hålla Påska, icke uti den gamla surdegen, och icke uti ondskones och arghetenes surdeg; utan uti renhetenes och sanningens osyrade deg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Jag hafver skrifvit eder till uti brefvena, att I intet skullen hafva skaffa med bolare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Det menar jag icke om denna verldenes bolare, eller om giriga, eller om röfvare, eller om afgudadyrkare; annars måsten I rymma utu verlden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Men nu hafver jag skrifvit eder, att I skolen intet hafva skaffa med dem, nämliga om någor vore som kallas en broder, och är en bolare, en girig, en afgudadyrkare, en skändare, en drinkare, eller en röfvare; med sådana skolen I ock icke äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Ty hvad kommer mig vid döma dem, som ute äro? Dömen icke I dem, som inne äro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Men dem, som ute äro, dömer Gud; drifver ock sjelfve den ut ifrån eder, som onder är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Gitter någor edra, som något hafver ute ståndandes med en annan, sig döma låta under de orättfärdiga, och icke heldre under de heliga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Veten I icke, att de helige skola döma verldena? Skall nu verlden dömas af eder, ären I då icke gode nog till att döma de ringa saker?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Veten I icke, att vi skole döma Änglarna? Huru mycket mer timmelig ting?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Men I, när I hafven några saker om timmelig ting, så tagen I dem som föraktade äro i församlingene och sätten dem till domare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Eder till blygd säger jag detta: Är der ju platt ingen vis ibland eder? Eller en som kan döma emellan sin broder och broder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Utan den ene brodren träter med den andra, och dertill inför de otrogna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Det är allaredo en brist med eder, att I gån med hvarannan till rätta; hvi låten I icke heldre göra eder orätt? Hvi låten I icke heldre göra eder skada?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Ja, I gören orätt och skada, och det brödromen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Veten I icke, att de orättfärdige icke skola ärfva Guds rike? Farer icke ville; hvarken bolare, eller afgudadyrkare, eller horkarlar, eller de veklingar, eller drängaskändare,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Eller tjufvar, eller girige, eller drinkare, eller hädare, eller röfvare skola ärfva Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Och detta voren I somlige; men I ären aftvagne, I ären helgade, I ären rättfärdigade, genom Herrans Jesu Namn, och genom vår Guds Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Jag hafver magt till allt, men det är icke allt nyttigt; jag hafver magt till allt, men ingen ting skall taga mig fången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Maten till buken, och buken till maten; men Gud skall både mat och buk till intet göra; men kroppen icke till boleri, utan Herranom, och Herren kroppenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Men Gud hafver uppväckt Herran; han skall också uppväcka oss, genom sina kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Veten I icke, att edre kroppar äro Christi lemmar? Skulle jag nu taga Christi lemmar, och göra der skökolemmar af? Bort det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Eller veten I icke, att den sig håller till en sköko, han blifver en kropp med henne? Ty de varda, säger han, tu uti ett kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Men den som håller sig till Herran, han är en Ande med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Flyr boleri. All synd, som menniskan gör, är utan kroppen; men den som bedrifver boleri, han syndar på sin egen kropp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Eller veten I icke, att edar kropp är dens Helga Andas tempel, som är i eder, hvilken I hafven af Gudi; och ären icke edre egne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Ty I ären dyrt köpte. Derföre priser nu Gud uti edar kropp, och i edrom anda, hvilke Gudi tillhöra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Nu, der I mig om skrefven, svarar jag. Det är mannenom godt, att han intet befattar sig med hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Dock likväl, till att undfly boleri, hafve hvar och en sina hustru, och hvar och en sin man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Mannen skall låta få hustrune skyldig välviljoghet, och sammalunda hustrun mannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Hustrun hafver icke sjelf magt öfver sin egen kropp, utan mannen; sammalunda mannen hafver icke magt öfver sin egen kropp, utan hustrun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Drager eder icke undan för hvarannan, utan det sker med begges edra samtycko, till en tid, att I mågen hafva tom till fasto och böner; och kommer så igen tillsammans, att djefvulen icke skall fresta eder för edor okyskhets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Men sådant säger jag eder efter tillstädjelse, och icke efter bud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Utan jag ville heldre, att alla menniskor voro såsom jag är; men hvar och en hafver sina egna gåfvo af Gudi; den ene så, den andre så.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Dem ogiftom och enkom säger jag: Godt är dem, om de blifva såsom ock jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Men kunna de icke hålla sig, så gifte sig; ty det är bättre gifta sig, än brinna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Men dem giftom bjuder icke jag, utan Herren: Hustrun skilje sig icke ifrå mannen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Skiljes hon ock ifrå honom, så blifve ogift, eller förlike sig med mannen igen; och mannen öfvergifve icke hustruna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Dem androm säger jag, icke Herren: Om så är, att en broder hafver ena otrogna hustru, och hon hafver vilja till att bo med honom; skilje då han icke henne ifrå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Och om en qvinna hafver en otrogen man, och han hafver vilja till att blifva när henne; skilje icke då honom ifrå sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Ty den otrogne mannen är helgad genom hustruna, och den otrogna hustrun är helgad genom mannen; annars vordo edor barn oren; men nu äro de helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Om ock den otrogne vill skiljas, så låt honom skiljas. En broder eller syster är icke bunden till egendom i sådana fallom; utan i frid hafver Gud kallat oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Ty huru vetst du, qvinna, om du kan göra mannen salig? Eller huru vetst du, man, om du kan göra hustruna saliga?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Dock såsom Gud hafver hvarjom och enom utdelat. Hvar och en, såsom Herren honom kallat hafver, så vandre han. Och så stadgar jag i alla församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Är någor omskoren kallad, han begäre icke förhud; är någor kallad i förhuden, han låte icke omskära sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Omskärelsen är intet, och förhuden är intet; utan hålla Guds bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Hvar och en blifve uti den kallelse, i hvilka han kallad är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Äst du kallad i träldom, haf der ingen sorg om; dock kan du fri varda, så bruka det heldre;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Ty den som i träldom kallad är i Herranom, han är Herrans fri; sammalunda ock den som kallad är i frihet, han är Christi egen vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'I ären dyrt köpte; blifver icke menniskors trälar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Hvar och en, käre bröder, der han uti kallad är, der blifve han uti när Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Men om jungfrur hafver jag icke Herrans bud; utan jag säger mina mening, såsom den der barmhertighet fått hafver af Herranom, till att vara trogen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Så menar jag nu sådant vara godt, för den nöd som förhanden är, att menniskone skall godt vara så blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Äst du vid hustru bunden, begära icke skiljas vid henne; äst du ock utan hustru, så begära icke hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Men gifter du dig, syndar du intet, och om en jungfru gifter sig, syndar hon intet; dock varda sådana lidande lekamlig bekymmer; men jag skonade eder gerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Men det säger jag: Käre bröder, tiden är kort. Öfver detta: De som hustrur hafva, vare såsom de inga hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'Och de som gråta, såsom de intet greto; och de som fröjda sig, såsom de fröjdade sig intet; och de som köpa, såsom de behöllo det intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'Och de som bruka denna verldena, såsom de brukade icke; ty denna verldenes väsende förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Men jag ville gerna, att I voren utan omsorg. Den der ogift är, han aktar det Herranom tillhörer, huru han skall täckas Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Men den som gifter sig, han aktar hvad verldene tillhörer, att han skall behaga hustrune.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Och det är skilnad på en qvinna, och en jungfru; den som ogift är, hon aktar det Herranom tillhörer, att hon skall blifva helig både till kropp och till anda; men den som gifter sig, hon aktar det verldene tillhörer, huru hon skall behaga mannenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Men detta säger jag till det som eder kan gagneligit vara, och icke att jag vill kasta band på eder; utan på det I skolen efterfölja det ärligit är, och blifva vid Herran, utan allt hinder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Men om någor låter sig tycka, att det icke väl skickar sig med hans jungfru, sedan hon väl manväxt är, och det vill icke annars vara, så göre som han vill, han syndar intet; han låte henne gifta sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Men om en sätter sig fast före, efter han onödd är, och hafver sin fria vilja, och besluter detta i sitt hjerta, att låta sina jungfru så blifva, han gör väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Den nu utgifter henne, han gör väl; men den icke utgifter henne, han gör bätter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Hustrun är bunden till lagen, så länge hennes man lefver; men när hennes man är afsomnad, är hon fri att gifva sig enom androm, hvem hon vill; dock att det sker i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Men saligare är hon, om hon så blifver, efter mitt sinne; jag menar, att jag ock hafver Guds Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Men om afgudaoffer vete vi; ty vi hafve alle förstånd. Förståndet uppblås; men kärleken förbättrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Om någor låter sig tycka, att han vet något; han vet ännu intet, huru honom bör veta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Men den som älskar Gud, han är känd af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Så vete vi nu om den mat, som offras afgudar; att afguden är intet i verldene, och att ingen Gud är, utan en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Och ändock någre äro, som kallas gudar, hvad det är i himmelen, eller på jordene; såsom månge gudar, och månge herrar äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Så hafve vi dock allenast en Gud, Fadren; af hvilkom all ting äro, och vi uti honom; och en Herra, Jesum Christum, genom hvilken all ting äro, och vi genom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Men hvar man hafver icke förståndet; ty somlige göra sig ännu samvet om afgudarna, ätande det för afgudaoffer; och efter deras samvet är svagt, varder det dermed befläckadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Men maten främjar oss intet för Gudi; äte vi, så varde vi intet bättre dermed; äte vi icke, så varde vi ock icke dess sämre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Ser till likväl, att denna edor frihet icke kommer dem till förargelse, som svage äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Ty om någor får se dig, du som förståndet hafver, sitta och äta i afgudahus, varder då icke hans samvet, som svag är, draget dermed till att äta afgudaoffer?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Och så varder den svage brodren öfver ditt förstånd förtappad, den Christus hafver lidit döden före.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'När I således synden på bröderna, och sargen deras svaga samvet, då synden I på Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Derföre, om maten förargar min broder, ville jag aldrig äta kött till evig tid; på det jag icke skall vara minom broder till förargelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Är jag icke en Apostel? Är jag icke fri? Hafver jag icke sett vår Herra Jesum Christum? Ären icke I mitt verk i Herranom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Är jag icke androm en Apostel, så är jag åtminstone edar Apostel; ty inseglet till mitt Apostlaämbete ären I, uti Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Dem som mig fråga, är detta mitt svar:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Hafve vi icke magt till att äta och dricka?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Hafve vi icke magt att omföra med oss en hustru, som en syster är, såsom de andre Apostlar och Herrans bröder, och Cephas?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Eller hafver jag och Barnabas allena icke magt sammaledes göra?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Ho tjenar till krig på sin egen sold någon tid? Ho planterar en vingård, och icke äter af hans frukt? Eller ho vaktar en hjord, och äter icke af hjordsens mjölk?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Månn jag tala sådant efter menniskosätt? Säger ock icke lagen detsamma?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Ty uti Mose lag är skrifvet: Du skall icke binda munnen till på oxan, som tröskar. Månn Gudi vara omsorg om oxar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Säger han icke det allt för våra skull? Ty för våra skull är det skrifvet: Att den som plöjer, han skall plöja på en förhoppning, och den som tröskar, han skall tröska på en förhoppning, att han må af sitt hopp delaktig varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Hafve vi nu fått eder det andeligit är; synes eder det mycket vara, att vi uppskäre edor lekamliga ting?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Äro andre vordne delaktige i denna magten när eder; hvi icke mycket mer vi? Men vi hafve sådana magt icke brukat; utan vi lidom allahanda, att vi icke något hinder göra skole Christi Evangelio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Veten I icke, att de som offra, de hafva sina näring af offret; och de som sköta altaret, de varda ock altaret åtnjutande?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Så hafver ock Herren skickat, att de, som förkunna Evangelium, skola ock hafva sina näring af Evangelio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Men jag hafver dess intet brukat. Jag skrifver ock icke fördenskull derom, att så ske skall med mig; jag vore heldre död, än att någor skulle min berömmelse om intet göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Ty att jag förkunnar Evangelium, deraf må jag icke berömma mig; ty jag måste det göra, och ve mig, om jag Evangelium icke förkunnar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Gör jag det gerna, så varder mig lönt; men gör jag det nödigt, så är mig dock det ämbetet befaldt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Hvad är då nu min lön? Nämliga att jag predikar Christi Evangelium, och gör det för intet; på det jag icke skall missbruka mina magt, som jag hafver uti Evangelio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Derföre, ändock jag är fri för hvar man, hafver jag likväl gjort mig till hvars mans tjenare, på det jag må vinna dess flera.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Judomen är jag vorden såsom en Jude, på det jag skall vinna Judarna; dem som under lagen äro, är jag vorden lika som jag under lagen vore, på det jag skall vinna dem, som under lagen äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Dem, som utan lag äro, är jag vorden lika som jag utan lag vore; ändock jag icke är utan Guds lag, utan är i Christi lag; på det jag dem vinna må, som utan lag äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Dem svagom är jag svag vorden, på det jag vinna må de svaga; jag är hvarjom manne vorden allahanda, på det jag skall ju några saliga göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Men sådant gör jag för Evangelii skull, på det jag skall varda dess delaktig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Veten icke I, att de som löpa på vädjobanan, alle löpa de; men en får lönen? Löper så, att I fån det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Ty hvar och en som kämpar, han hafver återhåll i all ting; de deruppå, att de skola få en förgängelig krono; men vi en oförgängelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Men jag löper icke såsom till något ovisst; så kämpar jag icke, såsom den som hugger i vädret;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Utan jag späker min lekamen, och underkufvar honom; på det jag icke predikar androm, och varder sjelfver straffelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Käre bröder, jag vill icke dölja för eder, att våre fäder voro alle under skyn, alle gingo de genom hafvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'Och alle vordo de under Mose döpte, i skynom, och i hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'Och hafva alle enahanda andelig mat ätit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'Och alle enahanda andelig dryck druckit; ty de drucko af den andeliga klippan, som dem medföljde; hvilken klippa var Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Men månge af dem voro icke Gudi behagelige; ty de vordo nederslagne i öknene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Men detta är oss skedt till exempel; att vi icke skole hafva begärelse till det ondt är, såsom de begärelse hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Varer icke heller afgudadyrkare, såsom somliga af dem, som skrifvet är: Folket satte sig ned att äta och dricka, och stodo upp till att leka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Låter oss icke heller drifva horeri, såsom somlige af dem besmittade sig med horeri; och föllo på en dag tre och tjugu tusend.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Låter oss ock icke fresta Christum, såsom somlige af dem frestade honom; och vordo dräpne af ormar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Knorrer ock icke, såsom somlige af dem knorrade; och vordo dräpne af förderfvarenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Allt sådant verderfors dem till ett exempel; men det är oss skrifvet till en förvarning, på hvilka verldenes ände kommen är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Derföre, den som låter sig tycka han står, han se till, att han icke faller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Eder hafver ingen frestelse ännu påkommit, utan den mennisklig är; men Gud är trofast, som icke låter eder frestas öfver edra förmågo; utan gör med frestelsen en utgång, så att I kunnen dragat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Derföre, mine käreste, flyr ifrån afgudadyrkan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Jag talar såsom med förståndigom; betrakter I hvad jag säger:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Välsignelsens kalk, den vi välsigne, är icke han Christi blods delaktighet? Det brödet, som vi bryte, är icke det Christi lekamens delaktighet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Ty det är ett bröd; så äre vi månge en lekamen, efter vi alle af eno bröde delaktige äre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Ser på Israel efter köttet; de som äta offren, äro de icke delaktige af altaret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Hvad skall jag då säga: Är afguden något? Eller är det något, som afgudom offras? Nej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Men det säger jag, att hvad Hedningarna offra, det offra de djeflom, och icke Gudi. Nu vill jag icke, att I skolen delaktige varda med djeflomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'I kunnen icke dricka Herrans kalk, och djeflarnas kalk. I kunnen icke delaktige vara af Herrans bord, och djeflarnas bord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Eller vilje vi reta Herran? Månn vi vara starkare än han?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Jag hafver magt till allt, men det kommer icke allt till förbättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Ingen söke sitt, utan annars bästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Allt det falt är i köttboden, det äter, och fråger intet derefter för samvetets skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Ty jorden är Herrans, och allt det derpå är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'När nu en otrogen bjuder eder till gäst, och I viljen gå till honom, så äter allt det eder förelägges, och fråger intet derefter för samvetets skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Men om då någor säger till eder: Detta är offradt afgudom, så äter icke, för hans skull som det underviste, och för samvetets skull; ty jorden är Herrans, och allt det derpå är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Samvetet, säger jag; icke ditt, utan dens andras; ty hvarföre skulle jag låta döma mina frihet af ens annars samvet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Ty om jag äter deraf med tacksägelse, hvi skulle jag då lastad varda för det jag tackar före?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Hvad I nu äten eller dricken, eller hvad I gören, så gören allt Gudi till äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Varer sådane, att I ingen förargen, hvarken Juda, eller Grek, eller Guds församling;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Såsom ock jag i all ting är allom till vilja, icke sökandes min, utan mångs mans nytto, att de måga varda salige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Varer mine efterföljare, såsom ock jag Christi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Käre bröder, jag prisar eder, att I tänken på mig i all stycke, och hållen det sätt, som jag eder föresatt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Så vill jag, att I veta skolen, att Christus är hvars och ens mans hufvud; men mannen är qvinnones hufvud; men Gud är Christi hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Hvar och en man, som beder, eller propheterar, och hafver något på hufvudet, han skämmer sitt hufvud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Men en qvinna, som beder eller propheterar med ohöljdt hufvud, hon skämmer sitt hufvud; ty det vore icke annars, än som hon vore rakad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Vill hon icke hölja sig, så skare ock håret med af; nu, efter det står illa att henne är håret afskoret, eller afrakadt, så hölje sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Men mannen skall icke hölja sitt hufvud; ty han är Guds beläte och ära; men qvinnan är mansens ära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Ty mannen är icke af qvinnone; utan qvinnan af mannenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Och mannen är icke skapad för qvinnones skull; utan qvinnan för mansens skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Derföre skall qvinnan hafva ena magt på hufvudet, för Änglarnas skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Dock är hvarken mannen utan qvinnone, eller qvinnan utan mannen, i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Ty såsom qvinnan är af mannenom, så är ock mannen genom qvinnona; men alltsammans af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Dömer vid eder sjelfva, om det är dägeligit, att en qvinna beder Gud ohöljd?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Eller lärer icke naturen eder det, att enom man är vanheder, om han hafver långt hår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Men qvinnone är ära, att hon hafver långt hår? Håret är henne gifvet till att skyla sig med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Är det ock någor ibland eder, den i detta ärendet enträten är, han vete, att vi hafve icke den seden; och icke Guds församlingar heller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Men detta måste jag befalla: Jag kan icke prisa, att I tillhopakommen, icke till förbättring, utan till förvärring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'I förstone, när I kommen tillhopa i församlingene, hörer jag att ibland eder är skiljaktighet; det jag ock väl endels tror.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Ty ibland eder måste ju vara parti, på det de rättsinnige skola varda uppenbare ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'När I nu tillhopakommen, så håller man då icke Herrans Nattvard.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Ty då man skall hålla nattvard, tager hvar och en sin egen nattvard framföre åt; och den ene hungrar, den andre är drucken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Hafven I nu icke hus, der I uti äta eller dricka mågen? Eller förakten I Guds församling, och skämmen dem som intet hafva? Hvad skall jag säga eder? Skall jag prisa eder? Häruti prisar jag eder intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Ty jag hafver undfått af Herranom, det jag ock eder gifvit hafver: ty Herren Jesus, i den natten, då han förrådder vardt, tog han brödet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'Tackade, bröt det, och sade: Tager, äter; detta är min lekamen, som för eder brytes; detta görer till min åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Sammalunda ock kalken, efter nattvarden, och sade: Denne kalk är det nya Testamentet i minom blod; detta görer, så ofta I dricken, till min åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Ty så ofta I äten af detta bröd, och dricken af denna kalk, skolen I förkunna Herrans död, tilldess han kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Hvilken nu ovärdeliga äter af detta bröd, eller dricker af Herrans kalk, han blifver saker på Herrans lekamen och blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Men pröfve menniskan sig sjelfva, och äte så af det brödet, och dricke af den kalken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Ty den ovärdeliga äter och dricker, han äter och dricker sig sjelfvom domen, icke åtskiljandes Herrans lekamen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Derföre äro ock månge svage och kranke ibland eder, och en stor del sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Ty om vi sjelfve dömde oss, så vorde vi icke dömde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Men då vi dömde varde, så varde vi näpste af Herranom; på det vi icke med verldene skole fördömde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Derföre, mine käre bröder, när I tillhopakommen till att äta, så bide den ene den andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Men hungrar någor, han äte hemma; på det I icke tillhopakommen till fördömelse. Det andra vill jag skicka, när jag kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Om de andeliga gåfvor vill jag, käre bröder, icke fördölja eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'I veten, att I hafven varit Hedningar, och gått till de stumma afgudar, efter som I förförde voren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Derföre gör jag eder vetterligit, att ingen förbannar Jesum, som genom Guds Anda talar; och ingen kan kalla Jesum en Herra, utan genom den Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Gåfvorna äro mångahanda; men Anden är en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Och ämbeten äro mångahanda; men Herren är en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Och krafterna äro mångahanda; men Gud är en, som allt verkar i allom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Uti hvarjom och enom bevisa sig Andans gåfvor till gagns.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Dem ena varder gifvet af Andanom tala om visdom; dem andra tala om förstånd, af samma Andanom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Enom androm tron, af samma Andanom; enom androm helbregda gåfva, af samma Andanom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Enom androm underlig ting göra; enom androm prophetia; enom androm åtskilja andar; enom androm mångahanda tungomål; enom androm tungomåls uttydelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Men allt detta verkar den samme ene Anden, delandes hvarjom sitt, såsom honom täckes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Ty såsom en lekamen är, och hafver dock många lemmar; men alle lemmar af en lekamen, ändock de äro månge, äro de dock en lekamen; sammalunda ock Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Ty vi äre uti enom Anda alle döpte till en lekamen, ehvad vi äre Judar eller Greker, tjenare eller frie; och hafve alle druckit till en Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Ty lekamen är icke en lem, utan månge,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'När nu foten ville säga: Jag är icke hand, derföre är jag icke af lekamenom; skulle han fördenskull icke vara af lekamenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Och om örat ville säga: Jag är icke öga, derföre är jag icke af lekamenom; skulle det fördenskull icke vara af lekamenom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Om hele lekamen vore öga, hvar blefve då hörslen? Vore han aller hörsel, hvar blefve lukten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Men nu hafver Gud satt lemmarna hvar för sig särdeles uti lekamen, såsom han ville.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Om nu alle lemmar vore en lem, hvar blefve då lekamen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Men nu äro lemmarna månge, och lekamen är en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Ögat kan icke säga till handen: Jag behöfver dig intet; eller hufvudet till fötterna: Jag behöfver eder intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Utan mycket mer de kroppsens lemmar, som synas svagast vara, äro oss mest af nöden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Och de vi hålle blygeliga vara, dem lägge vi mästa äron uppå; och de oss snöpliga synas, dem pryde vi aldramest.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Ty de, som dägeliga äro, behöfva intet; men Gud hafver så tillhopamängt lekamenen, och de lemmar, som något fattades, dess mer prydelse tillagt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'På det i lekamenen skall ingen skiljaktighet vara; utan alle lemmar skola den ene för den andra ens omsorg hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Och om en lem lider något, så lida alle lemmarna med; och om en lem varder härliga hållen, så fröjda sig alle lemmarna med.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Men I ären Christi lekamen och lemmar, hvar efter sin del.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Och Gud hafver satt i församlingene först Apostlar, dernäst Propheter, sedan lärare, sedan kraftverkare, sedan helbregdo gåfvor, hjelpare, regerare, mångahanda tungomål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Äro de alle Apostlar? Äro de alle Propheter? Äro de alle lärare? Äro de alle kraftverkare?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Hafva de alle helbregdo gåfvor? Tala de alle mång tungomål? Kunna de alle uttyda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Men farer efter de yppersta gåfvorna; och jag vill ännu visa eder en kosteligare väg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Om jag talade med menniskors och Änglars tungor, och hade icke kärleken, så vore jag en ljudande malm, eller en klingande bjellra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Och om jag kunde prophetera, och visste all hemlighet, och allt förstånd, och hade alla tro, så att jag försatte berg, och hade icke kärleken, så vore jag intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Och om jag gåfve alla mina ägodelar de fattiga, och låte min lekamen brinna, och hade icke kärleken, så vore det mig intet nyttigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Kärleken är tålig och mild; kärleken afundas intet; kärleken skalkas intet, han uppblåses icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Han skickar sig icke ohöfveliga; han söker icke sitt, han förtörnas icke, han tänker intet argt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Han gläds icke öfver orättfärdighet; men han fröjdar sig öfver sanningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Han fördrager all ting, han tror all ting, han hoppas all ting, han lider all ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Kärleken vänder aldrig åter, ändock Prophetierna skola återvända, och tungomålen skola afkomma, och förståndet skall återvända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Ty vi förstå endels, och prophetere endels;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Men då det kommer som fullkomligit är, så vänder det åter som endels är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Då jag var ett barn, talade jag som ett barn, och hade sinne som ett barn, och hade barnsliga tankar; men sedan jag vardt man, lade jag bort det barnsligit var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Ty vi se nu genom en spegel, uti ett mörkt tal; men då ansigte emot ansigte. Nu känner jag endels; men då skall jag kännat, såsom jag ock känd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Men nu blifver tron, hoppet, kärleken, dessa tre; men störst ibland dem är kärleken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Farer efter kärleken; vinnlägger eder om andeliga gåfvor; dock mest, att I propheteren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Ty den som talar med tungomål, han talar icke menniskom, utan Gudi; ty ingen hörer dertill, utan han talar hemligit i Andanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Men den som propheterar, han talar menniskomen till förbättring, och till förmanelse, och till tröst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Den som talar med tungomål, han förbättrar sig sjelf; men den som propheterar, han förbättrar församlingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Jag ville väl, att I alle tala kunden med tungomål; men mycket heldre, att I propheteraden; ty den som propheterar han är större än den som med tungomål talar; utan han det uttyder, på det församlingen får någon förbättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Men nu, käre bröder, om jag komme till eder, och talade med tungomål, hvad vore jag eder nyttig? Utan jag talar med eder, antingen med uppenbarelse, eller med förstånd, eller med prophetia, eller med läro?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Hafver sig dock så med de ting, som ljud göra ifrå sig, och dock intet lif hafva, såsom en pipa eller en harpa; då de icke gifva åtskiljeligit ljud ifrå sig, huru kan man veta, hvad pipadt eller harpadt är?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Så ock, om en basun gifver en ovissa röst, ho gör sig då redo till strids?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Så ock I, om I talen med tungomål, och icke talen det som förstås kan, huru skall man veta hvad taladt är? ty I talen i vädret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Så mångahanda slag är på rösterna i verldene, och ingen af dem är otydelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'När jag nu icke vet uttydningen på rösten, blifver jag honom, som talar, Barbarisk; och den, som talar, blifver för mig Barbarisk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Sammalunda ock I, medan I faren efter andeliga gåfvor, vinnlägger eder om församlingens bästa, att I nog hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Derföre, den som talar med tungomål, han bedje, att han må ock kunna det uttyda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'När jag nu beder med tungone, så beder min ande; men mitt sinne är utan frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Huru skall det då gå till? Nämliga så: Jag skall bedja i andanom; jag skall ock bedja med sinnet; jag skall sjunga i andanom; jag skall ock sjunga med sinnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'När du nu välsignar i andanom, huru skall då den, som står i dens olärdas stad, svara dig Amen på din tacksägelse; efter han icke förstår hvad du säger?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Du säger väl en god tacksägelse; men den andre varder deraf intet förbättrad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Jag tackar min Gud, att jag talar mer med tungomål, än I alle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Men jag vill heldre tala i församlingene fem ord med mitt sinne, på det jag undervisa må andra, än eljest tiotusend ord med tungomål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Käre bröder, varer icke barn i förståndet, utan varer barn i ondskone; men i förståndet varer fullkomlige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'I lagen är skrifvet: Jag vill tala med andra tungor, och med andra läppar till detta folk, och de skola dock icke än så höra mig, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Så äro nu tungomålen för ett tecken, icke dem som tro, utan dem som icke tro; men prophetien är tvärtemot, icke dem som otrogne äro, utan dem som trogne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Hvar nu hela församlingen tillhopakomme på en stad, och talade alla med tungomål, och der kommo någre olärde eller otrogne in, månde de icke skola säga, att I haden mist sinnet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Hvar I nu alle propheteraden, och der komme någor otrogen eller olärd in, han vorde straffad af dem allom, och dömd af allom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Och så vorde det, som lönligit är i hans hjerta, uppenbart; och så fölle han på sitt ansigte, tillbåde Gud, och bekände, att sannerliga vore Gud i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Huru är det då, käre bröder? När I tillsammans kommen, så hafver hvar och en af eder en Psalm; han hafver lärdom, han hafver tungomål, han hafver uppenbarelse, han hafver uttydelse; låter det allt ske till förbättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Hvar nu någor talar med tungomål, det göre han sjelf annar, eller på det mesta sjelf tredje, och då ymsom; och en tyde det ut.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Är han icke en uttydare, så tige i församlingene; men tale vid sig sjelf, och till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Men Propheterna tale två eller tre; och de andre döme derom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Men hvar så händer, att dem, som sitter, varder något uppenbaradt, så tige den förste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'I mågen väl alle prophetera, den ene efter den andra, på det alle måge lära, och alle varda förmanade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Och Propheternas andar äro Prophetomen underdånige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Ty Gud är icke oskickelighetenes, utan fridsens Gud, som uti alla de heligas församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Edra qvinnor tige uti församlingarna; ty dem är icke tillstadt att tala, utan att de äro underdåniga, såsom ock lagen säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Men vilja de något lära, så skola de fråga sina män hemma; det står icke qvinnor väl, att de tala i församlingene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Eller är Guds ord utkommet ifrån eder? Eller är det allena kommet till eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Der nu någor låter sig tycka att han är en Prophet, eller andelig, han besinne hvad jag skrifver eder; ty det äro Herrans bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Men är någor oförståndig, han vare oförståndig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Derföre, käre bröder, lägger eder vinn om att I propheteren, och förmener icke att tala med tungomål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Låter all ting ärliga och skickeliga tillgå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Käre bröder, jag minner eder på Evangelium, som jag eder förkunnat hafver, hvilket I ock anammat hafven, i hvilko I ock stån;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Genom hvilket I ock salige varden, huruledes jag eder det förkunnade, om I hafven det behållit; utan så är, att I förgäfves trott hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Ty jag hafver i förstone eder föregifvit, det jag ock undfått hafver, att Christus är döder för våra synder, efter Skrifterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'Och att han är begrafven; och att han uppstånden är på tredje dagen, efter Skrifterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'Och att han vardt sedder af Cepha, sedan af de tolf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Sedan vardt han sedder af mer än femhundrade bröder på en tid, af hvilkom ännu månge lefva; men mestedelen äro afsomnade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Derefter vardt han sedder af Jacobo; och sedan af alla Apostlarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'På sistone efter allom vardt han ock sedder af mig, såsom af en den der otidig född är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Ty jag är den ringaste ibland Apostlarna, så att jag är icke värd kallas Apostel; derföre, att jag hafver förföljt Guds församling.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Men af Guds nåd är jag det jag är; och hans nåd hafver icke fåfäng varit i mig; utan jag hafver mer arbetat, än de alle; dock icke jag, utan Guds nåd, som i mig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Det vare nu jag, eller de, så predike vi, och så hafven I trott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Är nu Christus predikad för eder, att han är uppstånden ifrå de döda; hvarföre säga då somlige ibland eder, att de dödas uppståndelse är intet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Är nu de dödas uppståndelse intet, så är ock Christus icke heller uppstånden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Är Christus icke uppstånden, så är vår predikan fåfäng; så är ock edor tro fåfäng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Och vi vardom funne falsk Guds vittne, att vi emot Gud vittnat hafve, att han hafver uppväckt Christum; den han icke uppväckt hafver, om de döde icke uppstå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Ty om de döde icke uppstå, så är icke heller Christus uppstånden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Är Christus icke uppstånden, så är edor tro fåfäng; och så ären I ännu uti edra synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Så äro ock de förtappade, som i Christo afsomnade äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Om vi allenast i detta lifvet hafve hoppet till Christum, så äre vi uslast ibland alla menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Men nu är Christus uppstånden ifrå de döda, och vorden förstlingen ibland dem som sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Efter döden är genom en mennisko, ock genom en mennisko de dödas uppståndelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Ty såsom alle dö uti Adam, så skola ock alle i Christo varda lefvande gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Hvar och en uti sin egen ordning; förstlingen Christus, sedan de som Christo tillhöra uti hans tillkommelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Sedan änden, då han öfverantvardar Gudi och Fadrenom riket; och aflägger all herradöme, och alla öfverhet och väldighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Ty han måste regnera, tilldess han lägger alla sina fiendar under sina fötter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Den ytterste fienden döden skall varda borttagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Ty all ting hafver han lagt under hans fötter; så, när han säger, att all ting honom undergifven äro, är nog uppenbart, att han undantagen är, som honom all ting undergifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Då nu all ting honom undergifven äro, så varder ock då Sonen sjelf undergifven honom, som honom all ting undergifvit hafver; på det att Gud blifver allt i allom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Hvad göra de eljest, som sig döpa låta öfver de döda? Om de döde ingalunda uppstå, hvi låta de sig då döpa öfver de döda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Och hvi stå vi alltid uti fara?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Vid vår berömmelse, som jag hafver i Christo Jesu, vårom Herra, dör jag hvar dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Hafver jag efter menniskomening uti Epheso stridt med vilddjur; hvad hjelper mig det, om de döde icke uppstå? Låt oss äta och dricka; ty i morgon måste vi dö.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Låter icke förföra eder; ondt snack förkränker goda seder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Vaker upp rätteliga, och synder icke; ty somlige veta intet af Gudi; till blygd säger jag eder detta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Måtte nu någor säga: Huru skola de döde uppstå? Och med hurudana lekamen skola de komma?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Du dåre, det du sår, det får icke lif, utan det blifver dödt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Och det du sår, är ju icke den kroppen som varda skall, utan ett blott korn, nämliga hvete, eller annat sådant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Men Gud gifver thy en kropp, såsom han vill, och hvarjo och eno af sädene sin egen kropp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Icke är allt kött enahanda kött; utan menniskors kött är annat, annat är fäs, annat är fisks, och annat är fogels.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Och det äro himmelske kroppar, och jordiske kroppar; men en annor härlighet hafva de himmelske, och en annor de jordiske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'En annor klarhet hafver solen, och en annor klarhet hafver månen, och en annor klarhet stjernorna; ty en stjerna går öfver den andra i klarheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Sammaledes ock de dödas uppståndelse; det varder sådt förgängeligit, och skall uppstå oförgängeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Det varder sådt i snöplighet, och skall uppstå i härlighet; det varder sådt i skröplighet, och skall uppstå i kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Det varder sådt ett naturligit lekamen, och skall uppstå ett andeligit lekamen. Man hafver ett naturligit lekamen; man hafver ock ett andeligit lekamen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Såsom skrifvet är: Den första menniskan Adam är gjord till naturligit lif; och den ytterste Adam till andeligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Men den andelige lekamen är icke den förste, utan den naturlige; sedan den andelige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Den första menniskan är af jordene jordisk; den andra menniskan är Herren af himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Hurudana den jordiska är, sådana äro ock de jordiske; och hurudana den himmelska är, sådana äro ock de himmelske.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Och som vi hafve burit dens jordiskas liknelse, så skole vi ock bära dens himmelskas liknelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Men detta säger jag, käre bröder, att kött och blod kunna icke ärfva Guds rike; och det förgängeliga skall icke ärfva oförgängelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Si, jag säger eder en hemlighet: Vi skole icke alle afsofva; men alle måste vi förvandlade varda,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'Uti en punkt, uti ett ögnablick, med yttersta basunen; ty basunen skall ljuda, och de döde skola uppstå oförgängelige, och vi skole förvandlade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Ty detta förgängeliga måste ikläda sig oförgängelighet, och detta dödeliga måste ikläda sig odödelighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Men då detta förgängeliga ikläder sig oförgängelighetena, och detta dödeliga ikläder sig odödelighetena, så varder det ordet fullkomnadt, som skrifvet är: Döden är uppsvolgen uti segren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Du död, hvar är din udd? Du helvete, hvar är din seger?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Dödsens udd är synden; syndenes kraft är lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Men Gudi vare tack, som oss segren gifvit hafver, genom vår Herra Jesum Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Derföre, mine käre bröder, varer faste, ovikelige, och rike uti Herrans verk alltid; efter det I veten, att edart arbete är icke fåfängt i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Nu om den undsättning till de heliga, såsom jag i de församlingar uti Galatia befallt hafver, så görer ock I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Ju på den ena Sabbathen lägge hvar och en af eder när sig sjelf, och samke tillhopa hvad han åstadkommer; på det, då jag kommer, icke skola då först samlas samma undsättningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Men då jag kommen är, de som I då med edart bref dertill hafva viljen, dem vill jag sända, att de framföra edra gåfvor till Jerusalem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Om så behöfves, att jag ock far dit, då måga de följa mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Men jag vill komma till eder, när jag drager genom Macedonien; ty genom Macedonien skall jag draga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Men när eder varder jag tilläfventyrs töfvandes, eller ock öfver vintren blifvandes, att I mig förfordra mågen ehvart jag resandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Jag vill intet nu se eder uti min framfärd; ty jag hoppas, att jag får någon tid dväljas när eder, om Herren det tillstädjer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Men jag vill blifva i Epheso intill Pingsdaga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Ty mig är öppnad en stor och kraftig dörr; och månge motståndare äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Om Timotheus kommer, så ser till, att han är utan fara när eder; ty han verkar ock Herrans verk, såsom ock jag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Så förakte nu ingen honom; utan fordrer honom i frid, att han må komma till mig; ty jag väntar honom med bröderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Men om Apollo brodren veter, att jag ofta hafver förmanat honom, att han skulle komma till eder med bröderna; men hans vilje var ingalunda på denna tid komma: dock varder han likväl kommandes, då honom så belägligit varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Vaker, står i trone, bruker eder manliga, varer starke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'All edor ting låter ske i kärlekenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Jag förmanar eder, käre bröder, I kännen Stephane husfolk, att de äro förstlingen i Achaja, och att de hafva skickat sig sjelfva dem heligom till tjenst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'På det I ock sådana menniskor skolen underdånige vara, och hvarjom och enom, som medverkar och arbetar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Jag fröjdar mig af Stephane tillkommelse, och Fortunati, och Achaici; ty hvad mig fattades i eder, det hafva de uppfyllt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'De hafva ock vederqvickt min och edar anda. Så kännens nu vid sådana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Eder helsa de församlingar uti Asia; helsa eder mycket i Herranom Aqvila och Priscilla, med den församling som är i deras hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Helsa eder alle bröderne; helser eder inbördes med en helig kyss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Jag Paulus helsar eder med mine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Hvilken Herran Jesum Christum icke hafver kär, han vare Anathema, Maran Atha.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Herrans Jesu Christi nåd vare med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Min kärlek vare med eder alla i Christo Jesu: Amen. Den förra Epistel till de Corinthier, sänd af Philippis genom Stephanas, och Fortunatus, och Achaicus, och Timotheus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paulus, Jesu Christi Apostel, genom Guds vilja, och brodren Timotheus, den Guds församling som är i Corintho, samt med all helgon, som äro uti hela Achajen:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Nåd vare med eder, och frid af Gudi, vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Välsignad vare Gud och vårs Herras Jesu Christi Fader, barmhertighetenes Fader, och all hugsvalelses Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Som oss hugsvalar i all vår bedröfvelse, att vi ock hugsvala kunne dem, som i allahanda bedröfvelse äro, med den hugsvalelse, der Gud oss med hugsvalar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Ty såsom Christi lidande är mycket kommet öfver oss, så kommer ock mycken hugsvalelse öfver oss genom Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Men hvad vi hafve bedröfvelse eller hugsvalelse, så sker det eder till godo. Är det bedröfvelse, så sker det eder till hugsvalelse och salighet; hvilken salighet är kraftig, om I liden tåleliga, i den måtton som vi lide; är det hugsvalelse, så sker det ock eder till hugsvalelse och salighet; är ock vårt hopp stadigt för eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Efter vi vete, att såsom I ären delaktige i lidandet, så varden I ock delaktige i hugsvalelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Ty vi vilje icke fördölja eder, käre bröder, vår bedröfvelse, som oss vederfaren är uti Asien; ty vi vore förtungade öfver måtton, och öfver magten, så att vi ock tviflade om lifvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Och satte oss så före, att vi skulle visserligen dö; det skedde fördenskull, att vi ingen tröst skola sätta på oss sjelfva, utan på Gud, som uppväcker de döda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Hvilken oss af slik död friat hafver, och ännu dageliga friar; och hoppoms på honom, att han skall oss ännu härefter fria,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Genom edra böners hjelp för oss; på det af många personer må ske mycken tack för oss, för den gåfvo som oss gifven är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Ty vår berömmelse är detta, nämliga vårt samvets vittnesbörd, att vi uti enfaldighet och Guds renhet, icke uti köttslig vishet, utan i Guds nåd, hafve vandrat på verldene; men aldramest när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Ty vi skrifve eder intet annat, än det I läsen, och tillförene veten. Mig hoppas, att I skolen ock så befinna (oss) allt intill ändan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Såsom I hafven oss endels befunnit; ty vi äro edor berömmelse, såsom ock I ären vår berömmelse, på Herrans Jesu dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Och på den förtröstning ville jag kommit till eder tillförene, att jag måtte eder dubbelt vara till vilja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Och genom eder fordenskap färdas till Macedonien, och ifrå Macedonien komma till eder igen, och af eder fordras till Judeen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Då jag detta så tänkte, månde jag det göra af någon lössinnighet? Eller månn min anslag vara köttslig? Nej; utan när mig är ja ja; och nej är nej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Men Gud är trofast, att vårt ord till eder är icke vordet ja och nej.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Ty Guds Son Jesus Christus, som ibland eder är predikad af oss, nämliga af mig, och Silvano, och Timotheo, hafver icke varit ja och nej, utan det var ja i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Ty all Guds tillsägelse äro Ja i honom, och äro Amen i honom, Gudi till äro genom oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Men Gud är den oss stadfäster, samt med eder, i Christo och hafver smort oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Och förseglat oss, och gifvit uti vår hjerta Andans pant.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Jag kallar Gud till vittne på min själ, det jag icke ännu kom till Corinthum, det är skedt fördenskull att jag skonade eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Icke att vi äro herrar öfver eder på trones vägna; utan vi äre hjelpare till edor glädje; ty I stån i trone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Men jag hafver det betänkt med mig sjelf, att jag icke åter med ångest vill komma till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Ty om jag bedröfvar eder, ho är då den som fröjdar mig, utan den som varder af mig bedröfvad?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Och detsamma hafver jag skrifvit eder, att, när jag komme till eder, jag icke skulle få sorg af dem, der jag heldre skulle få glädje af; efter jag hafver den tröst till eder alla, att min fröjd är allas edra fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Ty jag skref eder till uti stor bedröfvelse och hjertans ångest, med många tårar; icke på det I skullen bedröfvas, utan på det I skullen förstå den kärlek, som jag enkannerliga hafver till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Hvar nu någor hafver bedröfvelse åstadkommit, den hafver icke bedröfvat mig, utan endels; på det jag icke skall betunga eder alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Men det är nog, att den samme af mångom så straffad är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Så att I nu dess mer tvärtemot skolen öfverse med honom, och hugsvala honom, på det han icke skall uppsluken varda uti för mycken bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Derföre förmanar jag eder, att I bevisen honom kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Ty derföre hafver jag ock skrifvit eder till, att jag skulle bepröfva eder, om I lydige ären i all ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Den I förlåten något, den förlåter ock jag; ty hvem ock jag förlåter något, det förlåter jag för edra skull, i Christi stad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'På det vi icke skole varda bedragna af Satana; ty oss är icke ovetterligit, hvad han i sinnet hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Men då jag kom till Troadem, till att predika Christi Evangelium, och mig upplåten vardt en dörr i Herranom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Hade jag ingen ro uti min anda; derföre att jag icke fann min broder Titum; utan gjorde der min afsked, och for till Macedonien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Men Gudi vare lof, som alltid låter oss seger behålla i Christo, och uppenbarar lukten af sin kunskap, genom oss, allestäds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Ty vi äre Gudi en god Christi lukt, både ibland dem som salige varda, också ibland dem som förtappade varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Dessom en döds lukt till döden; men dem androm lifsens lukt till lifs. Ho är nu här dogse till?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Ty vi äre icke såsom månge, de der förfalska Guds ord; utan af renhet, och såsom af Gudi, tale vi för Gud i Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Skole vi då åter begynna prisa oss sjelfva? Eller behöfve vi, såsom någre andre, prisbref till eder, eller ock prisbref ifrån eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'I ären vårt bref, beskrifvet uti vår hjertan, hvilket kändt och läset varder af alla menniskor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Efter I bevisen, att I ären Christi bref, beredt genom vår tjenst, och skrifvet icke med bläck, utan med lefvandes Guds Anda; icke i taflor af sten, utan i hjertans taflor af kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Men en sådan tröst hafve vi till Gud, genom Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Icke att vi beqvämlige äro af oss sjelfvom något tänka, såsom af oss sjelfvom; men äre vi till något beqvämlige, så är det af Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Hvilken ock oss beqvämliga gjort hafver till att föra dess Nya Testamentsens ämbete; icke bokstafsens, utan Andans; ty bokstafven dödar, men Anden gör lefvande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Hade nu det ämbetet klarhet, som genom bokstafven dödar, och i stenar utgrafvet är, så att Israels barn icke kunde se på Mose ansigte, för hans ansigtes klarhets skull, den dock återvänder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Hvi skulle icke mycket mer det ämbetet, som Andan gifver, hafva klarhet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Ty om det ämbete, som fördömelse predikar, hafver klarhet; mycket mer går det ämbete öfver i klarhet, som rättfärdighet predikar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Och dertillmed, det som förklaradt vardt, var dock i denna måtton lika som intet förklaradt, emot denna öfversvinneliga klarheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Ty hade det klarhet, som återvänder, mycket mer hafver det klarhet, som varaktigt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Efter vi nu sådant hopp hafve, äre vi mycket dristige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Och göre icke såsom Moses, den ett täckelse hängde för sitt ansigte, så att Israels barn icke kunde se uppå dess ända, som återvänder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Utan deras sinnen äro förstockade; ty allt intill denna dag blifver samma täckelse oborttaget öfver gamla Testamentet, när de läsat, hvilket i Christo återvänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Men intill denna dag, då Moses läsen varder, hänger täckelset för deras hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Men om de omvände sig till Herran, så vorde täckelset borttaget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Ty Herren är en Ande; der nu Herrans Ande är, der är frihet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Men nu skåde vi alle, såsom uti en spegel, Herrans klarhet med upptäckt ansigte; och vi varde förklarade uti samma beläte, ifrå den ena klarhetene till den andra, såsom af Herrans Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Derföre, medan vi ett sådant ämbete hafve, efter som oss barmhertighet vederfaren är, så varde vi icke försummelige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Utan flym ock hemlig skam, och farom icke med skalkhet, förfalskom ej heller Guds ord; utan med uppenbara sanning bevisom oss väl för alla menniskors samvet, i Guds åsyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Är nu vårt Evangelium förtäckt, så är det förtäckt för dem, som förtappade varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'I hvilkom denna verldenes gud hafver förblindat de otrognas sinnen, att dem icke skall lysa Evangelii ljus af Christi klarhet, hvilken Guds beläte är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Ty vi predike icke oss sjelfva, utan Jesum Christum, att han är Herren; men vi edre tjenare för Jesu skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Ty Gud är den som böd ljuset utu mörkret lysa; och lyste uti vår hjerta, att igenom oss måtte upplysning ske af Guds klarhets kunskap, i Jesu Christi ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Men vi hafve dessa håfvor uti lerkar, på det att den stora kraften skall vara af Gudi, och icke af oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Vi varda allestäds trängde, men vi ängsles intet; vi bekymres, men vi gifve oss icke öfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Vi lide förföljelse, men vi varde icke öfvergifne; vi blifve undertryckte, men vi förgås icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Vi omföre alltid Herrans Jesu död på vår lekamen; på det att ock Jesu lif må på vår lekamen uppenbart varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Ty vi, som lefve, vardom alltid öfvergifne i döden för Jesu skull; på det att ock Jesu lif skall uppenbaradt varda på vårt dödeliga kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Så är nu döden mägtig i oss; men lifvet i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Efter vi hafve den samma trones anda, som skrifvet är: Jag tror, derföre talar jag; så tro vi ock, derföre tale vi ock;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Vetandes, att den som hafver uppväckt Herran Jesum, han skall ock uppväcka oss genom Jesum, och ställa oss med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Ty det sker allt för edra skull; på det den öfverflödiga välgerning, der månge tacka, skall rikeliga komma Gudi till pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Derföre förtröttes vi intet; utan ändock vår utvärtes menniska förgås, så varder dock den invärtes förnyad dag ifrå dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Ty vår bedröfvelse, den dock timmelig och lätt är, föder i oss en evig och öfver alla måtto vigtig härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Vi som icke se efter de ting, som synas, utan de som icke synas; ty de ting, som synas, äro timmelig; men de, som icke synas, äro evig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Men vi vete, att om denna hyddones vårt jordiska hus nederslaget varder, så hafve vi ena byggning af Gudi byggd; ett hus, icke med händer gjordt, det evigt är i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Och öfver detsamma sucke vi ock efter vårt hemman som af himmelen är; och oss längtar, att vi dermed måge öfverklädde varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Dock om vi klädde, och icke nakne finnes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Ty medan vi äre uti denna hyddone, sucke vi, och äre betungade; efter vi vilje icke afklädde, utan heldre öfverklädde varda, på det att det dödeliga måtte uppsvolget varda af lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Men den oss dertill bereder, är Gud, den oss Andan till pant gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Så äre vi fördenskull vid goda tröst alltid, och vete att, så länge vi hafve hemman uti lekamen, så äre vi icke hemma när Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Ty vi vandrom i trone, och se honom intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Men vi hafve tröst, och hafve mycket mer lust till att ute vandra ifrå lekamen, och hemma vara när Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Derföre, hvad vi äre hemma, eller ute vandrande, vinnlägge vi oss ock, att vi måge honom täckas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Ty vi måste alle uppenbarade varda för Christi domstol; på det hvar och en skall få, efter som han handlat hafver, medan han lefde, ehvad det är godt eller ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Efter vi nu vete, att Herren är fruktandes, fare vi sakta med menniskorna; men Gudi äre vi uppenbare; jag hoppas, att vi ock äre uppenbare uti edor samvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Vi prise oss icke åter för eder; men vi gifve eder tillfälle till att berömma eder af oss; på det I något hafva skolen emot dem, som sig efter anseendet, och icke efter hjertat berömma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Ty äre vi för stränge, så äre vi det Gudi; eller äre vi måttelige, så äre vi eder måttelige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Ty Christi kärlek tvingar oss så, efter vi det hålle, att om en är död för alla, så äro de alle döde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Och han är fördenskull död för alla, att de, som lefva, skola icke nu lefva sig sjelfvom, utan honom, som för dem död och uppstånden är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Så känne vi nu ingen ifrå denna tid efter köttet; och om vi än hafve känt Christum efter köttet, så känne vi honom dock nu intet mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Hvar nu någor är i Christo, så är han ett nytt kreatur; det gamla är förgånget; si, all ting äro ny vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Men alltsamman är af Gudi, den oss med sig sjelf försonat hafver genom Jesum Christum, och gifvit oss ämbetet att predika samma försoning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Ty Gud var i Christo, och försonade verldena med sig sjelfvom, och förebrådde dem intet deras synder, och hafver beskickat ibland oss försoningenes ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Så äre vi nu sändningabåd i Christi stad; ty Gud förmanar genom oss. Så bedje vi nu i Christi stad: Låter försona eder med Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Ty den der af ingen synd visste, honom hafver han för oss gjort till synd; på det vi skulle varda Guds rättfärdighet genom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Ja, vi såsom medhjelpare förmane eder, att I icke undfången Guds nåd fåfängt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Ty han säger: Jag hafver bönhört dig i behagelig tid, och jag hafver hulpit dig på salighetenes dag: Si, nu är den behageliga tiden; si, nu är salighetens dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Låter oss ingom i någor måtto förargelse gifva, på det vårt ämbete må ostraffadt blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Utan låter oss i all ting bevisa oss såsom Guds tjenare; i stort tålamod, i bedröfvelse, i nöd, i ångest;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'I slag, i fängelse, i uppror, i arbete, i vako, i fasto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'I renlefnad, i förstånd, i långmodighet, i mildhet, i den Helga Anda, i en oskrymtad kärlek;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'I sanningenes ord, i Guds kraft, genom rättfärdighetenes vapen till högra sidon, och till den venstra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Genom äro och smälek, genom ondt rykte och godt rykte; såsom bedragare, och dock sannfärdige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Såsom okände, och dock kände; såsom de der dö, och si, vi lefvom; såsom näpste, och dock icke dräpne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Såsom bedröfvade, och dock alltid glade; såsom fattige, och dock många rika görande; såsom intet hafvande, och dock all ting ägande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'O I Corinthier, vår mun hafver öppnat sig till eder; vårt hjerta är gladt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'För våra skull behöfven I icke ängslas; men att I ängslens, det gören I af en hjertelig mening.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Jag talar med eder såsom med min barn, att I ock så ställen eder emot mig; och varer ock så glade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Drager icke uti främmande ok med de otrogna; ty hvad hafver rättfärdigheten beställa med orättfärdighetene? Eller hvad delaktighet hafver ljuset med mörkret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Eller huru förlika sig Christus och Belial? Eller hvad del hafver den trogne med dem otrogna?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Eller huru kommer Guds tempel öfverens med afgudar? Ty I ären lefvandes Guds tempel, såsom Gud säger: Jag vill bo uti dem, och vandra uti dem; och jag vill vara deras Gud, och de skola vara mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Derföre går ut ifrå dem, och skiljens ifrå dem, säger Herren, och kommer intet vid det orent är; och så skall jag undfå eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'Och vara edar Fader, och I skolen vara mine söner och döttrar, säger allsvåldige Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Efter vi nu hafve sådana löfte, mine käreste, så görom oss rena af all köttsens och andans besmittelse fullbordande helgelsen i Guds räddhåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Fatter oss; vi hafve ingom gjort skada, vi hafve ingen bedragit, vi hafve ingen besvikit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Sådana säger jag icke till att fördöma eder; ty jag sade eder tillförene, att I ären i vår hjerta, till att dö och lefva med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Jag hafver mycken tröst till eder; jag berömmer mig mycket af eder; jag är uppfylld med hugsvalelse; jag är uti osägeliga glädje, i all vår bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Ty när vi kommom uti Macedonien, då hade vårt kött ingen ro, utan allestädes vorom vi uti bedröfvelse; utvärtes strid, invärtes räddhåge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Men Gud, som hugsvalar dem som förtryckte äro, han hugsvalade oss genom Titi tillkommelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Dock icke allenast genom hans tillkommelse, utan jemväl genom den hugsvalelse han fått hade af eder; och förkunnade oss edra åstundan, edar gråt, edart nit om mig, så att jag blef ända yttermera glad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Ty det jag bedröfvade eder med mitt bref, det ångrar mig intet; och om det än ångrade mig, dock, medan jag ser att samma bref hafver tilläfventyrs en tid långt bedröfvat eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Så fröjdar jag mig nu icke deraf, att I vorden bedröfvade, utan att I vorden bedröfvade till bättring; ty I ären bedröfvade vordne efter Guds sinne, så att I ingen skada lidit hafven af oss i någor måtto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Ty den sorg, som är efter Guds sinne, hon kommer åstad bättring till salighet, den man icke ångrar; men verldenes sorg, hon kommer åstad döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Si, detsamma, att I bedröfvade vorden efter Guds sinne, hvilken omsorg det hafver gjort i eder; ja sannerliga, ursäkt, misshag, räddhåga, åstundan, nit, hämnd; ty I hafven bevisat i all stycken, att I rene ären uti den saken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Derföre, ändock jag skref eder till, så är det likväl icke skedt för hans skull, som skadan gjort hade; icke heller för hans skull, som skadan skedd var; utan fördenskull, att vår nit till eder skulle uppenbar varda när eder för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Derföre hafve vi nu fått hugsvalelse, deraf att I hugsvalade ären; dock än mycket mer hafve vi gladt oss för Titi fröjds skull; ty hans ande vardt vederqvickt af allom eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Hvad jag hafver berömt mig om eder för honom, det blyges mig intet; utan såsom vi all ting i sanningen hafve eder sagt, så är ock vår berömmelse för Tito sann vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Och hans hjerta är öfvermåtton väl till sinnes om eder, då han tänker på allas edra lydno, huruledes I undfingen honom med räddhåga och bäfvan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Jag fröjdar mig, att jag allt godt må förse mig till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Jag gör eder kunnigt, käre bröder, om den Guds nåd, som gifven är uti de församlingar som äro i Macedonien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Ty deras glädje är osägelig, då de genom mycken bedröfvelse bepröfvade vordo; och ändock de ganska fattige voro, hafva de likväl rikeliga gifvit i all enfaldighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Ty de voro välviljoge efter allo sine magt, och öfver sina magt; det betygar jag:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Bedjandes oss med mycken förmaning, att vi anamma ville välgerningen, och tjenstenes delaktighet som skickad var till helgonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Och icke som vi hade hoppats; utan de gåfvo sig sjelfva först Herranom, och sedan oss, genom Guds vilja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Att vi måstom förmana Titum, att såsom han hade tillförene begynt, så skulle han ock nu fullfölja sådana godviljoghet när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Men såsom I uti all stycke rike ären i tro, och i ordom, och i förstånd, och i all flit, och i edar kärlek till oss, så flyr det så, att I ock i denna edor undsättning rike ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Icke så, att jag bjuder eder något; utan efter andre så vinnlägga sig, försöker jag ock edar kärlek, om han sannskyldig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Ty I veten Herrans Jesu Christi godviljoghet, att ändock han var rik, vardt han likväl fattig för edra skull, på det I genom hans fattigdom skullen rike varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Mitt råd gifver jag häruti; ty det är eder nyttigt, efter I för ett år sedan haden begynt icke allenast göra, utan jemväl vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Fullföljer nu med gerningene, såsom I begynten; att, såsom viljen var redebogen, så fullföljer ock af det I förmågen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Ty då viljen är först god, så är han tacknämlig, efter den del han hafver, och icke efter det han icke hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Icke sker detta i den mening, att andre skola hafva nog, och I trång, utan att det skall gå lika till:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Att edar rikedom tjenar deras fattigdom i denna (dyra) tid, och deras rikedom hjelper edra fattigdom, på det lika tillgå skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Såsom skrifvet är: Den der mycket samlade, han hade intet öfverlöpse; och den der litet samlade, honom fattades intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Men Gudi vare tack, som sådana flit gifvit hafver uti Titi hjerta till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Ty han tog den förmaning på sig; ja, sannerliga, han var så flitig, att han tog sig före sjelfviljandes fara till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Men vi hafve sändt med honom en broder, den pris hafver i Evangelio, i alla församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'Och icke det allenast; utan han är ock skickad af församlingarna, till att vara vår följeslagare till denna undsättning, som beställes af oss, Herranom till äro, och edar goda vilja till pris;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Och förvarar, att oss ingen straffa kan för denna rika undsättnings skull, som af oss beställd varder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Och ser derpå, att det redeliga tillgår, icke allenast för Herranom, utan ock för menniskom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Och hafve vi sändt med honom vår broder, den vi ofta bepröfvat hafve i mång stycke, att han flitig är, och nu mycket mer flitig; och förse vi oss storliga till eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Ehvad det är för Titi skull, hvilken min stallbroder och medhjelpare är när eder, eller för våra bröders skull, som äro församlingarnas Apostlar, och Christi ära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Låter nu skina någon bevisning till edar kärlek, och vår berömmelse af eder, på dem; ja ock uppenbarliga för församlingarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Om den undsättning, som sker helgonen, är icke behof att jag skrifver eder till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Ty jag vet edar godvilja, af hvilken jag berömmer mig ibland dem i Macedonien, att Achajen var redo för ett år sedan; och edart efterdöme uppväckte många.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Dock hafver jag sändt dessa bröder, derföre att vår berömmelse om eder icke skall fåfäng vara uti detta ärende; och att I ären redo, såsom jag hafver sagt om eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'På det, om de af Macedonien med mig komma, och finna eder icke redo, att vi (jag vill icke säga I) icke då skolen få en blygd af sådana berömmelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Syntes mig ock af nöden vara att förmana bröderna, att de först foro till eder, och tillredde den undsättning, som tillförene utlofvad var; att hon ligger redo, såsom en god undsättning och icke som någor karghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Men det säger jag: Den som sparliga sår, han skall ock sparliga uppskära; och den som sår i välsignelse, han skall ock uppskära i välsignelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Hvar och en som han sjelf vill; icke med olust, eller af tvång; ty en gladan gifvare älskar Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Gud är mägtig så lagat, att allahanda nåd rikeliga blifver i eder; att I uti all ting alltid nog hafven, nog mägtige till alla goda gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Såsom skrifvet är: Han hafver utstrött, och gifvit de fattiga; hans rättfärdighet blifver i evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Men den som räcker sädesmannenom det han sår, han skall ock räcka eder brödet till att äta, och skall föröka edra säd, och låta växa edra rättfärdighets frukt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Att I rike blifven i all ting, uti all enfaldighet, hvilken i oss verkar, att Gudi sker tack.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Ty denna undsättning icke allenast uppfyller den brist, som helgonen hafva; utan jemväl öfverflödar dertill, att månge tacka Gudi, de som denna hjelp väl täckes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Och prisa Gud för edor underdåniga bekännelse i Christi Evangelio, och för edra enfaldiga meddelan med dem och allom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Och desslikes i deras böner för eder; hvilka ock längta efter eder, för den öfversvinnande Guds nåd som är i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Men Gudi vare tack för sina osägeliga gåfvo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Men jag Paulus förmanar eder, genom Christi saktmodighet och mildhet; jag som ringa är, när jag är när eder; men frånvarandes är jag dristig vid eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Men jag beder eder, att jag icke skall nödgas närvarandes handla dristeliga, och bruka den djerfhet som man mig tillägger, emot några, som oss räkna såsom vi vandrade efter köttet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Ty ändock vi vandre i köttet, likväl stride vi icke efter köttet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Ty vår krigsvapen äro icke köttslig, utan mägtig för Gud, att nederslå fäste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Med hvilko vi kullslå de anslag, och all höghet som sig upphäfver emot Guds kunskap; och tillfångatage allt förnuft under Christi lydno;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'Och äro redebogne att hämnas alla olydno, när edor lydnad fullbordad är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Dömen I efter ansigtet? Om någor förlåter sig derpå, att han hörer Christo till, han tänke det ock med sig sjelf, att, såsom han hörer Christo till, så höre ock vi Christo till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Och om jag ock något mer berömde mig om våra magt, hvilka Herren oss gifvit hafver, eder till förbättring, och icke till förderf, ville jag ändå icke blygas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Men detta säger jag, på det I icke skolen tänka, att jag hade velat förskräcka eder med bref.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Ty brefven, säga de, äro svår och stark; men lekamliga närvarelsen är svag, och orden föraktelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Den sådana är, han tänke, att sådana som vi äre med orden i brefven frånvarande, så äre vi ock väl med gerningen närvarande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Ty vi töre icke sätta eller räkna oss ibland dem, som sig sjelfva prisa; men efter de mäta sig vid sig sjelfva, och hålla allena af sig sjelfva, förstå de intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Men vi berömme oss icke öfver måtton, utan allena efter reglones mått, med hvilko Gud hafver oss afmätit ett mått till att hinna ock allt intill eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Ty vi försträckom oss icke öfver måtton, lika som vi icke hint hade intill eder; ty vi äre ju ock komne allt intill eder, med Christi Evangelio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Icke berömmandes oss öfver måtton af annars mans arbete; förhoppandes att ske skall, då edor tro begynner växa uti eder, att vi efter våra reglo vilje vidare komma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Och predika ock dom Evangelium, som bo utom eder, och icke berömma oss af det genom främmande reglo tillredt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Men den sig berömmer, han berömme sig i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Ty den som lofvar sig sjelf, han är icke bepröfvad; utan den Herren lofvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Jag ville, att I mig något litet lida villen uti min fåvitsko; dock I liden mig väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Ty jag nitälskar eder i Guds nit; ty jag hafver fäst eder enom man, på det jag skulle fly Christo en ren jungfru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Men jag fruktar att tilläfventyrs icke sker, att såsom ormen besvek Eva med sin illfundighet, så varda ock edor sinne förvänd ifrån enfaldigheten i Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Ty om den, som till eder kommer, predikar eder en annan Jesum, den vi icke predikade; eller om I undfån en annan Anda, den I icke undfått hafven; eller ett annat Evangelium, det I icke anammat hafven, så liden I dem med rätto.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Ty jag håller mig icke ringare, än de höga Apostlar äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Och ändock jag är enfaldig i talet, så är jag dock icke enfaldig i förståndet; dock vi äre nog kände allestäds när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Eller hafver jag syndat, att jag hafver förnedrat mig, på det I skullen upphöjde varda? Ty jag hafver förkunnat eder Evangelium utan lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Andra församlingar hafver jag beröfvat, och tagit lön af dem, der jag eder med tjente.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Och då jag var när eder, och mig fattades något, förtungade jag ingen; ty hvad mig fattades, uppfyllde de bröder, som komne voro af Macedonien; och i all ting höll jag mig, att jag ingom var till tunga; och vill ännu så hålla mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Så visst som Christi sanning är i mig, så skall denna berömmelse mig icke förtagen varda uti Achaje landsändar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'För hvad sak? Derföre, att jag icke älskar eder? Gud vet det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Men det jag gör, det vill jag ock göra; på det jag skall förtaga dem tillfällen, som tillfälle söka till att berömma sig, att de äro såsom vi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Ty sådane falske Apostlar, och bedrägelige arbetare, taga sig uppå Christi Apostlars person.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Och det är ock icke under; ty ock sjelfver Satan förskapar sig uti ljusens Ängel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Derföre är icke under att hans tjenare också förskapa sig, lika som de der voro rättfärdighetenes predikare; hvilkas ände skall varda efter deras gerningar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Åter säger jag, att ingen skall tänka att jag är fåvitsk; annars tager mig ock än såsom en fåvitsk man, att jag ock något litet må berömma mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Det jag nu talar, det talar jag icke såsom i Herranom, utan såsom i fåvitskhet, efter vi äre komne uti berömmelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Efter nu månge berömma sig af köttet, vill också jag berömma mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Ty I fördragen gerna de fåvitska, efter I ären sjelfve vise.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'I fördragen, om någor gör eder till trälar, om någor eder uppäter, om någor eder ifrå tager, om någor förhäfver sig öfver eder, om någor eder slår i ansigtet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Det säger jag efter smälighet, såsom vi vore svage vordne. Hvad nu någor uppå dristar (jag talar i fåvitsko), derpå dristar jag ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'De äro Ebreer, så är jag ock; de äro Israeliter, jag ock; de äro Abrahams säd, jag ock.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'De äro Christi tjenare (jag talar i fåvitsko), jag är fast mer; jag hafver mer arbetat; jag hafver mer hugg fått; jag hafver oftare varit fången; ofta varit i dödsnöd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Af Judomen hafver jag fem resor fått fyratio slag, ett mindre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Tre resor hafver jag varit stupad med ris; ena resa stenad; tre resor hafver jag varit i skeppsbrott; natt och dag hafver jag varit i hafsens djup.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Jag hafver ofta färdats; jag hafver varit i farlighet i floder; i farlighet ibland mördare; i farlighet ibland Judarna; i farlighet ibland Hedningarna; i farlighet i städerna; i farlighet i öknene; i farlighet på hafvet; i farlighet ibland falska bröder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'I mödo och arbete; i mycken vako; i hunger och törst; i mycken fasto; i frost och nakenhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Förutan det som eljest påkommer, nämliga att jag dagliga öfverlupen varder, och bär omsorg för alla församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Ho är svag, och jag varder icke svag? Ho förargas, och jag brinner icke?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Efter jag ju skall berömma mig, så vill jag berömma mig af min svaghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Gud och vårs Herras Jesu Christi Fader, hvilkom vare pris i evighet, vet att jag icke ljuger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Landshöfdingen uti Damasco, på Konung Arete vägna, förvarade de Damasceners stad, och ville gripit mig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'Och jag vardt i en korg genom ett fenster, öfver muren, nedersläppt, och undslapp hans händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Mig är ju icke nyttigt att berömma mig; dock vill jag nu komma till syner och Herrans uppenbarelser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Jag känner en man i Christo för fjorton år. Var han i lekamen, det vet jag icke, eller utan lekamen, vet jag ock icke; Gud vet det. Den samme vardt uppryckt intill tredje himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Den samma mannen känner jag; om han i lekamen, eller utan lekamen var, det vet jag icke; Gud vet det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Han vardt uppryckt till Paradis, och hörde outsägeliga ord, hvilka ingen menniska säga må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Deraf vill jag berömma mig; men af mig sjelf vill jag intet berömma mig, utan af mine svaghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Och om jag ville berömma mig; så gjorde jag intet fåvitskliga; ty jag ville säga sanningen; men jag hafver det likväl fördrag, på det ingen skall högre akta mig, än som han ser på mig, eller hörer af mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Och på det att jag mig icke af de stora uppenbarelser förhäfva skulle, vardt mig gifven en påle i köttet, Satans ängel, den mig kindpusta skulle, på det jag icke skulle förhäfvas öfver måtton;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'För hvilka sak jag bad tre resor Herran, att han skulle komma ifrå mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Och han sade till mig: Låt dig nöja åt mine nåd; ty min kraft är mägtig i de svaga. Derföre vill jag aldrahelst berömma mig af mine svaghet, på det Christi kraft skall bo i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Derföre är jag vid godt mod, i svaghet, i föraktelse, i nöd, i förföljelse, i ångest, för Christi skull; ty när jag svag är, så är jag stark.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Jag är fåvitsk vorden med berömmelse; dertill hafven I nödgat mig; ty jag skulle varda prisad af eder, efter det jag icke är ringare än någor af de höga Apostlar, ändock jag är intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Ty ens Apostels tecken äro ju skedd ibland eder, med allt tålamod; med tecken, och under, och mägtiga gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Uti hvad del hafven I varit ringare än de andra församlingar? Annat än det, att jag sjelf intet hafver varit eder till tunga. Förlåter mig den orätten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Si, jag är redebogen tredje reson komma till eder, och vill intet heller betunga eder; ty jag söker icke edart, utan eder; derföre att barnen skola icke draga tillhopa föräldromen, utan föräldrarna barnomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Men jag vill ganska gerna utgifva mig, och utgifven varda för edra själar; ändå I litet älsken mig, den dock ganska mycket älskar eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Men låter nu så vara, att jag intet hafver betungat eder: likväl, medan jag var listig, hafver jag fångat eder med list.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Hafver jag beskattat eder med någrom, som jag hafver sändt till eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Jag bad Titum, och sände med honom en broder. Hafver ock Titus beskattat eder? Hafve vi icke vandrat uti enom anda? Hafve vi icke vandrat i samma fotspåret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Åter, menen I att vi ursake oss för eder? Vi tale i Guds åsyn i Christo; men, mina käreste, allt detta sker eder till förbättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Ty jag fruktar att, då jag kommer, må ske att jag finner eder icke såsom jag vill, och I finnen icke mig som I viljen; att der är i någon måtto trätor, nit, vrede, kif, förtal, örnatasslan, uppblåsning, uppror;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Att jag återkommer, och min Gud betrycker mig när eder; och måste sörja öfver många, som tillförene syndat hafva, och icke hafva gjort bot för deras orenlighet, sköraktighet och otukt, som de bedrifvit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Kommer jag tredje gången till eder, så skola uti två eller tre mäns mun alla saker bestå.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Jag hafver det sagt eder tillförene, och säger eder det tillförene, såsom närvarandes, i den andra reson; och skrifver det nu frånvarandes, dem som tillförene syndat hafva, och allom dem androm. Om jag åter kommer, skall jag intet skona;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Efter I söken att I en gång skolen förnimma honom, som i mig talar, nämliga Christum, hvilken när eder intet svag är, utan är mägtig ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Ty ändock han vardt korsfäst i svagheten, så lefver han likväl i Guds kraft; och ändock vi ock äre svage i honom, så lefve vi likväl med honom, uti Guds kraft, när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Försöker eder sjelfva, om I ären i trone; bepröfver eder sjelfva. Eller kännen I eder icke sjelfva, att Jesus Christus är uti eder? Utan så kunde vara, att I odugelige ären.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Men jag hoppas, att I väl skolen känna, att vi icke odugelige ärom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Och önskar jag af Gudi, att I intet ondt gören; icke på det vi skulle synas dugelige; utan att I skolen göra hvad redeligit är, och vi blifve då som vi odugelige vorom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Ty vi kunnom intet emot sanningene; utan med sanningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Men vi fröjde oss, när vi svage äre, och I mägtige; och det samma önske vi ock, nämliga edor fullkomlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Derföre skrifver jag ock detta frånvarandes, på det, då jag är tillstädes, jag icke skall sträng vara, efter den magt som Herren hafver mig gifvit till förbättring, och icke till förderf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'På sistone, käre bröder, fröjder eder; varer fullkomne, tröster eder, varer ens sinnade, varer fridsamme; så blifver kärlekens och fridsens Gud när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Helser eder inbördes med en helig kyss; helsa eder all helgon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Vårs Herras Jesu Christi nåd, och Guds kärlek, och den Helga Andas delaktighet vare med eder allom. Amen. Den andra Epistel till de Corinthier, sänd af Philippis i Macedonien, med Tito och Luca.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paulus Apostel, icke af menniskor, icke heller genom mennisko; utan genom Jesum Christum, och Gud Fader, som honom uppväckt hafver ifrå de döda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'Och alle bröder, som när mig äro, de församlingar i Galatien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Nåd vare med eder, och frid af Gud Fader, och vårom Herra Jesu Christo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Som sig sjelf för våra synder gifvit hafver, på det han skulle uttaga oss ifrå denna närvarande onda verld, efter Guds och vårs Faders vilja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Hvilkom vare pris ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Mig förundrar, att I så snarliga låten eder afvända ifrå den, som eder kallat hafver uti Christi nåd, till ett annat Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Ändock intet annat är; utan att någre äro de eder förvilla, och vilja förvända Christi Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Men om ock vi, eller en Ängel af himmelen, annorlunda predikade Evangelium för eder, än vi eder predikat hafve, han vare förbannad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Såsom vi nu sadom, så säge vi än en tid: Om någor vore den eder predikar Evangelium annorlunda, än I undfått hafven, han vare förbannad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Predikar jag nu menniskom eller Gudi till vilja? Eller söker jag täckas menniskom? Hade jag härtilldags velat täckas menniskom, så vore jag icke Christi tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Men jag gör eder vetterligit, käre bröder, att det Evangelium, som är predikadt af mig, är icke menniskligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Ty jag hafver det icke fått af mennisko, icke heller lärt; utan genom Jesu Christi uppenbarelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Ty I hafven väl hört min umgängelse fordom i Judaskapet, att jag öfvermåtton förföljde Guds församling, och förstörde henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Och växte till mer och mer i Judaskapet, utöfver många mina likar i mitt slägte; och höll mig strängeliga vid fädernas stadgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Men då Gudi täcktes, som mig af mins moders lif afskiljt hafver, och kallat mig genom sina nåd dertill;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Att han ville uppenbara sin Son genom mig, att jag skulle genom Evangelium förkunna honom ibland Hedningarna; straxt föll jag till, och befrågade mig intet derom med kött och blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Och kom icke heller till Jerusalem igen, till dem som voro Apostlar för mig, utan for bort i Arabien, och kom åter till Damascum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Sedan, efter tre år, kom jag igen till Jerusalem, till att se Petrum; och blef när honom i femton dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Men af de andra Apostlar såg jag ingen, utan Jacobum, Herrans broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Men det jag skrifver eder, si, Gud vet, att jag icke ljuger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Derefter kom jag in uti de land Syrien och Cilicien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Men jag var okänd till ansigtet för de Christeliga församlingar i Judeen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Utan de hade allenast hört, att den som fordom förföljde oss, han predikar nu trona, som han fordom förstörde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Och de prisade Gud för mina skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Sedan, efter fjorton år, for jag åter upp till Jerusalem med Barnaba, och tog Titum ock med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Och for jag dit upp efter en uppenbarelse, och befrågade mig med dem om Evangelium, som jag förkunnar ibland Hedningarna; besynnerliga med dem, som för något voro räknade; på det jag icke skulle löpa fåfängt, eller redo lupit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Men icke vardt heller Titus, som med mig var, nödgad till att låta omskära sig, ändock han var en Grek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Ty då någre falske bröder sig med inträngde, och med inkomne voro, till att bespeja vår frihet, som vi hafve i Christo Jesu, på det de skulle komma oss i träldom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Vekom vi för dem icke en stund till underdånighet; på det Evangelii sanning skulle blifva beståndandes när eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Men af dem som något räknade voro, hurudane de fordom varit hade, det kommer mig intet vid; Gud aktar icke menniskones anseende; men de som något voro räknade, lärde mig intet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Utan heldre tvärtemot; då de sågo, att mig betrodt var Evangelium till förhuden, lika som Petro till omskärelsen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(Ty den som med Petro var kraftig till Apostla-ämbetet ibland omskärelsen, den hafver ock med mig kraftig varit ibland Hedningarna;)');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Och förnummo den nåd, som mig gifven var, räckte Jacobus och Cephas, och Johannes, hvilke såsom pelare räknade voro, mig och Barnabe handena, och förenade sig med oss, så att vi skulle predika ibland Hedningarna, och de ibland omskärelsen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Allenast, att vi skulle tänka på de fattiga; hvilket jag också hafver vinnlagt mig att göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Men då Petrus kom till Antiochien, stod jag honom uppenbarliga emot; ty klagomål var kommen öfver honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Ty förr än någre voro komne ifrå Jacobo, åt han med Hedningarna; men då de kommo, unddrog han sig, och skiljde sig ifrå dem; ty han fruktade dem som voro af omskärelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Och de andre Judar skrymtade ock med honom, så att Barnabas vardt ock bedragen till att skrymta med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Men då jag såg, att de icke rätteliga vandrade efter Evangelii sanning, sade jag till Petrum uppenbarliga för allom: Medan du, som äst en Jude, lefver som en Hedning, och icke som en Jude, hvarföre tvingar du då Hedningarna till att lefva efter Judasättet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Ändock vi af naturen äre Judar, och icke syndare af Hedningomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Likväl, efter vi vete, att menniskan icke varder rättfärdig genom lagsens gerningar, utan genom trona på Jesum Christum, så tro vi ock på Christum Jesum, att vi skole rättfärdige varda genom trona på Christum, och icke af lagsens gerningar; derföre att intet kött varder rättfärdigadt genom lagsens gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Men skulle vi, som söke varda rättfärdige genom Christum, ock ännu sjelfve finnas vara syndare, så vore Christus en syndatjenare. Bort det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Ty om jag bygger det samma upp igen, som jag nederslagit hade, så gör jag mig sjelf till en öfverträdare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Men jag är genom lag död ifrå lagen, på det jag skall lefva Gudi; jag är korsfäst med Christo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Men jag lefver, dock icke nu jag, utan Christus lefver i mig; ty det jag nu lefver i köttet, det lefver jag i Guds Sons tro, den mig älskat hafver, och gifvit sig sjelf ut för mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Jag bortkastar icke Guds nåd; ty om rättfärdigheten kommer af lagen, så är Christus fåfängt död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'O, I oförståndige Galater, ho hafver kjust eder, att I icke skullen lyda sanningene? Hvilkom Jesus Christus för ögonen målad var, och nu ibland eder korsfäst är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Det vill jag allenast veta af eder: Hafven I undfått Andan genom lagsens gerningar, eller genom trones predikan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Ären I så oförståndige? I hafven begynt i Andanom; viljen I nu lyktat i köttet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Hafven I då så mycket lidit fåfängt? Om det eljest fåfängt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Den som nu gifver eder Andan, och gör sådana krafter ibland eder, gör han det genom lagsens gerningar, eller genom trones predikan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Såsom Abraham hafver trott Gudi, och det är räknadt honom till rättfärdighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Så veten I ju nu, att de som äro af trone, de äro Abrahams barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Men Skriften hafver sett framföre åt, att Gud gör Hedningarna rättfärdiga genom trona; derföre förkunnade hon Abrahe: I dig skola alle Hedningar välsignade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Så varda nu de, som af trone äro, välsignade med den trogna Abraham.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Ty alle de som med lagsens gerningar umgå, de äro under förbannelse; ty det är skrifvet: Förbannad vare hvar och en, som icke blifver vid allt det som skrifvet är i lagboken, så att han det gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Men att ingen varder rättfärdig för Gudi genom lagen, är uppenbart; ty den rättfärdige skall lefva af (sine) tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Men lagen är icke af trone; utan den menniska som så gör, hon lefver deraf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christus hafver förlossat oss ifrå lagsens förbannelse, då han vardt en förbannelse för oss; ty det är skrifvet: Förbannad är hvar och en, som hänger på träd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'På det Abrahams välsignelse komma skulle öfver Hedningarna i Christo Jesu, och vi så undfå måtte Andans löfte genom trona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Käre bröder, jag vill tala efter menniskosätt: Man föraktar ju icke ene menniskos testamente, då det gilladt är; man lägger icke heller något dertill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Nu är ju Abraham och hans säd löftet tillsagdt; han säger icke, uti säderna, såsom i mångom; utan, såsom uti enom, uti dine säd, som är Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Men det säger jag: Det Testamentet, som tillförene af Gudi fast gjordt var på Christum, varder icke ogilladt, så att löftet skulle omintet varda med lagen, hvilken gifven var fyrahundrade och tretio år derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Ty om arfvet förtjentes genom lagen, så vorde det icke gifvet genom löftet; men Gud hafver det Abraham, genom löftet, fri skänkt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Hvad skall då lagen? Hon är kommen dertill för öfverträdelsernas skull, till dess säden skulle komma, hvilko löftet skedt var, och är skickad af Änglarna uti Medlarens hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Men Medlaren är icke ens Medlare; men Gud är en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Är då lagen emot Guds löften? Bort det; men om en lag vore gifven, som kunde lefvande göra, så vore rättfärdigheten sannerliga af lagen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Men Skriften hafver allt beslutit under synd, på det löftet skulle komma genom Jesu Christi tro, dem som tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Men förr än tron kom, voro vi förvarade under lagen, och beslutne till den tro som uppenbaras skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Sa hafver nu lagen varit vår tuktomästare till Christum, på det vi skole varda rättfärdige af trone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Nu, sedan tron kommen är, äre vi icke länger under tuktomästaren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Ty I ären alle Guds barn, genom trona på Christum Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Ty I, så månge som döpte ären till Christum, hafven eder iklädt Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Här är icke Jude eller Grek; här är icke tjenare eller fri; här är icke man eller qvinna; alle ären I en i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Ären I nu Christi, så ären I ju Abrahams säd, och arfvingar efter löftet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Men jag säger: Så länge arfvingen är barn, är ingen åtskillnad emellan honom och en tjenare; ändock han är herre öfver alla ägodelarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Utan är under förmyndare och föreståndare, intill den tiden som af fadrenom förelagd är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Sammalunda ock vi, då vi vorom barn, vore vi tvingade under utvärtes stadgar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Men då tiden vardt fullkommen, sände Gud sin Son, föddan af qvinno, gjordan under lagen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'På det han skulle förlossa dem, som under lagen voro, att vi skullom få barnaskapet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Efter I nu ären söner, hafver Gud sändt sins Sons Anda uti edor hjertan, hvilken ropar: Abba, käre Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Så är här nu icke mer tjenare, utan son; är han son, så är han ock Guds arfvinge genom Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Men den tid I intet känden Gud, tjenten I dem som af naturen icke äro gudar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Men nu, medan I Gud känt hafven, ja mycket mer kände ären af Gudi, hvi vänden I eder då om till de svaga och vedertorftiga stadgar igen, hvilkom I på nytt tjena viljen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'I hållen dagar och månader, högtider och årstider.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Jag fruktar om eder, att jag tilläfventyrs icke hafver fåfängt arbetat på eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Varer såsom jag är, efter jag ock är såsom I. Käre bröder, jag beder eder, I hafven mig intet emot gjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'I veten, att jag genom köttsens svaghet i förstone predikade eder Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Och min frestelse, som jag led på köttsens vägnar, hafven I intet föraktat, icke heller försmått, utan anammaden mig såsom en Guds Ängel; ja, såsom Christum Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Huru salige voren I då? Jag är edart vittne, att om det hade möjeligit varit, haden I edor ögon uttagit, och gifvit mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Är jag då nu vorden edar ovän, att jag säger eder sanningen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'De nitälska eder icke rätteliga, utan vilja draga eder ifrå mig, att I skolen nitälska dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Så är nu väl godt nitälska, då det sker om det godt är alltid, och icke allenast då jag tillstädes är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Min kära barn, hvilka jag på nytt föder med ångest, till dess Christus kommer till stadga uti eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Jag ville väl att jag nu vore när eder, och förvandla kunde mina röst; ty jag vet härnäst ingen råd med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Säger mig, I som viljen vara under lagen: Hafven I icke hört lagen?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Ty det är skrifvet, att Abraham hade två söner; en af tjensteqvinnone, den andra af den fria.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Men den som var af tjensteqvinnone, han var född efter köttet; men den af de frio, han var född genom löftet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Hvilka ord betyda något; ty dessa äro de tu Testamenten; ett af det berg Sina, som föder till träldom, hvilket är Agar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Ty Agar heter i Arabien det berg Sina, och sträcker sig emot Jerusalem, det nu är, och är icke fri med sinom barnom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Men det Jerusalem som ofvantill är, det är den fria; hon är allas vår moder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Ty det är skrifvet: Var glad, du ofruktsamma, du som intet föder; brist ut och ropa, du som icke är hafvandes; ty den ensamma hafver flera barn, än den som man hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Men vi, käre bröder, äro löftsens barn efter Isaac.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Men såsom den, som då född var efter köttet, förföljde honom som född var efter Andan; så går det ock nu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Men hvad säger Skriften? Drif ut tjensteqvinnona med hennes son; ty tjensteqvinnones son skall icke blifva arfvinge med dens frios son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Så äro vi nu, käre bröder, icke tjensteqvinnones söner, utan dens frios.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Så blifver nu ståndande uti den frihet, med hvilko Christus oss friat hafver; och låter eder icke på nytt fångas under träldomsens ok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Si, jag Paulus säger eder: Om I låten eder omskära, är eder Christus intet nyttig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Men jag betygar åter hvarjom och enom, som sig låter omskära, att han är pligtig till att hålla hela lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'I hafven mist Christum, I som genom lagen viljen rättfärdige varda; och I ären fallne ifrå nådene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Men vi vänte uti Andanom, genom trona, den rättfärdighet som man hoppas skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Ty i Christo Jesu är intet bevändt, hvarken omskärelse eller förhud; utan tron, som verkar genom kärleken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'I lupen väl; ho hafver hindrat eder, att I icke skullen tro sanningene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Sådana tillskyndelse är icke af honom, som eder kallat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Litet af surdeg försyrer hela degen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Jag förser mig till eder i Herranom, att I tagen eder icke annat sinne; men den eder förvillar, han skall draga sin dom, eho han är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Om jag ännu, käre bröder, predikar omskärelsen, hvi lider jag ännu förföljelse? Så vore korsens förargelse om intet vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Gåfve Gud, att de ock afskorne vordo, som eder bekymra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Men, käre bröder, I ären kallade till frihet; allenast ser till, att I icke låten frihetena gifva köttet tillfälle, utan genom kärleken tjener den ene dem andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Ty all lagen varder fullbordad uti ett ord; det är: Älska din nästa som dig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Men om I med hvarannan bitens och frätens, så ser till att I icke ymsom af hvarannan uppätne varden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Men jag säger: Vandrer i Andanom, så fullkomnen I icke köttsens begärelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Ty köttet hafver begärelse emot Andan, och Andan emot köttet; de samma äro emot hvartannat, så att I icke gören hvad I viljen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Om I regerens af Andanom, så ären I icke under lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Men köttsens gerningar äro uppenbara, som är hor, boleri, orenlighet, lösaktighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Afguderi, trolldom, ovänskap, kif, nit, vrede, trätor, tvedrägt, parti;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Afund, mord, dryckenskap, fråsseri, och sådant mer; der jag eder tillförene af sagt hafver, och säger ännu tillförene, att de, som sådana göra, skola icke ärfva Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Men Andans frukt är kärlek, fröjd, frid, långmodighet, mildhet, godhet, tro,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Saktmodighet, kyskhet; emot sådant är icke lagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Men de, som Christo tillhöra, korsfästa sitt kött, samt med lustar och begärelser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Om vi nu lefve i Andanom, så låter oss ock vandra i Andanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Låter oss icke begära fåfänglig pris, till att förtörna och hata hvarannan inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Käre bröder, om en menniska råkade falla i någon synd, I som andelige ären, upprätter honom med saktmodigom anda; och se uppå dig sjelf, att du icke ock frestad varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Inbördes drager hvarannars bördo, och så fullborden I Christi lag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Derföre, om någor låter sig tycka något vara, ändock han intet är, han bedrager sig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Men hvar och en bepröfve sin egen gerning, och så skall han allenast uti sig sjelf hafva berömmelse, och icke uti androm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Ty hvar och en skall draga sina bördo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Den som undervisad varder med ordom, han dele allt godt med honom, som honom undervisar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Farer icke ville, Gud låter intet gäcka sig; ty hvad menniskan sår, det skall hon ock uppskära.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Den som sår i sitt kött, han skall af köttet uppskära förgängelighet; men den som sår i Andanom, han skall uppskära af Andanom evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Och när vi göre godt, låt oss icke ledas vid; ty vi skole ock i sinom tid uppskära utan återvändo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Medan vi nu tid hafve, låt oss göra godt emot hvar man; men aldramest emot dem, som våre medbröder äro i trone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Ser huru stort bref jag eder tillskrifvit hafver med min egen hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'De som vilja täckas efter köttet, de nödga eder till omskärelsen, allenast fördenskull, att de icke skola förföljde varda med Christi kors.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Ty ock de samma, som låta omskära sig, hålla intet lagen; utan de vilja att I skolen låta omskära eder, på det de måga berömma sig af edart kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Men bort det, att jag af någon ting skulle berömma mig, utan af vårs Herras Jesu Christi kors; genom hvilken verlden är mig korsfäst, och jag verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Ty i Christo Jesu gäller intet, hvarken omskärelse eller förhud, utan ett nytt kreatur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Och alle de som efter denna reglo vandra, öfver dem vare frid och barmhertighet, och öfver Guds Israel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Ingen göre mig mer bekymmer; ty jag drager på min kropp vårs Herras Jesu tecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Vårs Herras Jesu Christi nåd vare med edrom anda, käre bröder. Amen. Till de Galater, sänd af Rom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulus, Jesu Christi Apostel, genom Guds vilja, dem heligom som uti Epheso äro, och trognom i Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Nåd vare med eder, och frid af Gudi, vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Välsignad vare Gud, och vårs Herras Jesu Christi Fader, den oss välsignat hafver med all andelig välsignelse, i de himmelska ting, genom Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Såsom han oss utvalt hafver i honom, förr än verldenes grund lagder var, att vi skole vara helige och ostraffelige för honom uti kärleken;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Och hafver tagit oss sig sjelfvom till barn, genom Jesum Christum, efter sins viljas goda behag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Sina härliga nåd till lof, genom hvilka han hafver oss täcka gjort uti honom, som kärkommen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'I hvilkom vi hafvom förlossning genom hans blod, syndernas förlåtelse, efter hans nåds rikedomar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Af hvilka han oss rundeliga delaktiga gjort hafver uti all visdom och klokhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Och hafver oss låtit få veta sins viljas hemlighet, efter sitt goda behag, och hafver det framhaft igenom honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Att det skulle predikadt varda, då tiden fullkomnad var; på det allting skulle sammanfattad varda i Christo, både det i himmelen och på jordene är, genom den samma;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Genom hvilken vi ock komne äre till arfvedelen, beskärde efter hans uppsåt, som all ting verkar efter sin egen viljas råd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Att vi skole vara hans härlighet till lof, vi som tillförene hoppadoms på Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Genom hvilken ock I hört hafven sanningenes ord, som är edor salighets Evangelium; uti hvilkom I ock, sedan I trodden, ären beseglade vordne med löftsens Helga Anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Hvilken vårt arfs pant är, till vår förlossning, att vi skulle varda hans egendom, hans härlighet till pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Derföre ock jag, efter jag hört hafver af den tro, som i eder är till Herran Jesum, och edar kärlek till all helgon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Vänder jag icke åter att tacka Gud för eder, alltid tänkandes på eder i mina böner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Att vårs Herras Jesu Christi Gud, härlighetenes Fader, ville gifva eder visdomsens och uppenbarelsens Anda, till sin kunskap,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Och upplysa edars förstånds ögon; att I förstå kunnen, hvad hopp han hafver kallat eder uti, och huru rik hans arfs härlighet är uti helgonen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Och huru öfversvinneliga stor hans kraft är till oss, som trom efter hans mägtiga starkhets verkan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Hvilka han verkade i Christo, då han uppväckte honom ifrå de döda, och satte honom på sin högra hand i himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Öfver all Förstadöme, välde, magt, Herradöme, och allt det som nämnas kan, icke allenast i denna verldene, utan ock i den tillkommande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Och hafver all ting lagt under hans fötter, och hafver satt honom församlingene till ett hufvud öfver all ting;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Hvilken är hans kropp, och hans uppfyllelse, som allt i allom uppfyller.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Och eder också, då I döde voren genom öfverträdelser och synder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Der I uti fordom vandraden, efter denna verldenes lopp, efter den Förstan, som magt hafver i vädret, nämliga efter den andan, som nu verkar i otrones barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Ibland hvilka vi ock alle fordom vandrat hafve, uti vårt kötts begärelser, och gjordom hvad köttet och sinnet lyste; och vorom af naturen vredsens barn, såsom ock de andre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Men Gud, som är rik i barmhertigheten, för sina stora kärleks skull, der han oss med älskat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Den tid vi ännu döde vorom i synderna, hafver han oss samt med Christo gjort lefvande (genom nådena ären I frälste);');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Och hafver samt med honom uppväckt oss, och samt med honom satt oss i det himmelska väsendet i Christo Jesu;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'På det han i tillkommande tid bevisa skulle sine nåds öfversvinneliga rikedom, genom sina mildhet öfver oss, i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Ty af nådene ären I frälste, genom trona; och det icke af eder, Guds gåfva är det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Icke af gerningar, på det ingen skall berömma sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Ty vi äre hans verk, skapade i Christo Jesu till goda gerningar, till hvilka Gud oss tillförene beredt hafver, att vi uti dem vandra skole.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Derföre, tänker derpå, att I som fordom efter köttet hafven varit Hedningar, och vorden kallade förhud af dem som kallas omskärelse efter köttet, den med handene sker;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Att I på den tid voren utan Christo, främmande och utan Israels borgareskap, och främmande ifrå löftsens Testament, intet hopp hafvande, och voren utan Gud i verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Men nu, I som i Christo Jesu ären, och fordom fjerran voren, ären nu när vordne, genom Christi blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Ty han är vår frid, den af bådom hafver gjort ett; och hafver nederbrutit medelbalken, i det att han igenom sitt kött borttog ovänskapen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Nämliga lagen, som i budordom stod; på det han skulle af tvåm skapa ena nya mennisko i sig sjelfvom, och frid göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Och att han skulle försona dem båda med Gudi uti en kropp, genom korset; och hafver dödat ovänskapen genom sig sjelf;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Och är kommen, och hafver igenom Evangelium bådat eder frid, I som fjerran voren; så ock dem som när voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Ty genom honom hafve vi både tillgång uti en Anda till Fadren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Så ären I icke nu mera gäster och främmande; utan helgamanna medborgare, och Guds husfolk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Uppbyggde på Apostlarnas och Propheternas grund, der Jesus Christus öfverste hörnestenen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'På hvilken hela byggningen tillhopafogad växer till ett heligt tempel i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'På hvilken ock I med uppbyggde varden, Gudi till ett hemman, genom Andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'För denna saks skull är jag Paulus Christi Jesu fånge för eder, Hedningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Om I eljest hört hafven om Guds nåds ämbete, som mig gifvet är till eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Att denna hemlighet är mig genom uppenbarelse förkunnad, såsom jag tillförene med få ord skref;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Af hvilko, om I det läsen, I mågen märka mitt förstånd i Christi hemlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Hvilket icke kunnigt gjordt är i förtiden menniskors barnom, såsom det nu uppenbaradt är hans heliga Apostlar och Propheter, genom Andan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Nämliga att Hedningarna skola vara medarfvingar, och samma lekamens och hans löftes delaktige i Christo, genom Evangelium;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Hvilkets tjenare jag vorden är, efter den gåfvo af Guds nåd, som mig gifven är, efter hans krafts verkning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mig, som är den aldraringaste ibland all helgon, är denna nåd gifven, att jag skall ibland Hedningarna förkunna de obegrundeliga Christi rikedomar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Och i ljuset frambära för hvar man, hurudana delaktighet är i den hemlighet, som härtilldags i verldene hafver fördold varit i Gudi, den all ting skapat hafver genom Jesum Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'På det nu skulle kunnigt varda Förstadömen och Herradömen i himmelen, på församlingene, Guds margfaldeliga vishet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Efter den försyn af verldenes begynnelse, hvilka han bevist hafver i Christo Jesu, vårom Herra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Genom hvilken vi hafve dristighet och tillgång med all förtröstning, genom trona på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Derföre beder jag, att I icke uppgifvens för mina bedröfvelsers skull, som jag lider för eder, hvilka äro eder till pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Fördenskull böjer jag min knä till vårs Herras Jesu Christi Fader;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Den der rätte Fadren är öfver allt det Fader heter i himmelen och på jordene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Att han ville gifva eder kraft, efter sine härlighets rikedomar, att I starke varden genom hans Anda, till den invärtes menniskan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Att Christus må bo genom trona i edor hjerta, stadeliga rotade och grundade i kärlekenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Att I mågen begripa med all helgon, hvad bredden, och längden, och djupet, och höjden är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Och dermed känna Christi kärlek, den all kunskap öfvergår; på det I mågen uppfyllde varda med allahanda Guds fullhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Men honom, som rikeliga förmår göra, öfver allt det vi bedjom, eller tänkom, efter den kraft som verkar i oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Honom vare ära i församlingen, genom Christum Jesum, i allan tid, ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Så förmanar jag nu eder, jag fången i Herranom, att I vandren såsom tillbörligit är, i den kallelse, der I uti kallade ären;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Med alla ödmjukhet och saktmodighet; med tålamod, unddragandes den ene den andra i kärlekenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Vinnläggande eder att hålla Andans enhet genom fridsens band;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'En kropp, och en Ande, såsom I ock kallade ären uti ett edars kallelses hopp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'En Herre, en tro, ett dop, en Gud, och allas våra Fader;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Hvilken är öfver eder alla, genom eder alla, och i eder alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Men hvarjom och enom af oss är gifven nåd, efter Christi gåfvos mått.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Derföre säger han: Han är uppstigen i höjden, och hafver fört fängelset fånget, och hafver gifvit menniskomen gåfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Men det han uppfaren är, hvad är det annat än han for först härned, uti de nedersta jordenes rum?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Den der nederfor, han är ock den der uppfor öfver alla himlar, på det han skulle all ting uppfylla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Han hafver ock somliga satt till Apostlar, somliga till Propheter, somliga till Evangelister, somliga till herdar och lärare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Att de helige skola skickelige vara till ämbetsens verk, genom hvilket Christi lekamen må uppbyggd varda:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Tilldess att vi alle kommom till ena tro, och Guds Sons kunskap, och vardom en fullkommen man, den der är uti Christi fullbordiga ålders mått;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'På det vi icke mer skolom vara barn, och låta oss beveka och omföras af allahanda lärdomsväder, genom menniskors skalkhet och illfundighet, med hvilka de falla till, att de måga bedraga oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Men varom rättsinnige i kärlekenom, och växom till i all stycke i honom, som hufvudet är, Christus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Af hvilkom hele kroppen tillhopafogas, och en lem hänger intill den andra genom all ledamöten, der den ene tjenar dem andra, efter det verk som hvar lem hafver i sitt mått, och gör att kroppen växer sig sjelf till förbättring, genom kärleken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Så säger jag nu, och betygar det i Herranom, att I icke mer vandren såsom de andre Hedningar vandra, i deras sinnes fåfängelighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Hvilkas förstånd förmörkradt är, och de bortkomne ifrå det lif som af Gudi är, genom den fåvitsko som i dem är, och genom deras hjertas blindhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Hvilke, sedan de vordo förstockade, gåfvo de sig sjelfva uti otukt, till att bedrifva all orenlighet, samt med girighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Men I hafven icke så lärt Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Om I annars honom hört hafven, och uti honom lärde ären, huru ett rättsinnigt väsende är i Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Så lägger nu bort ifrån eder den gamla menniskan, der I förra med umgingen, hvilken genom lustar i villfarelse sig förderfvar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Och förnyer eder i edar sinnes anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'Och ikläder eder den nya menniskona, den efter Gud skapad är, i sannskyldiga rättfärdighet och helighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Derföre, lägger bort lögnen, och taler sanningen, hvar och en med sin nästa; efter vi ärom inbördes lemmar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Vredgens och synder icke; låter icke solena gå ned öfver edra vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Gifver ock icke lastarenom rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Den der stulit hafver, han stjäle icke mer; utan heldre arbete med sina händer det godt är; på det han något skall hafva dela med den som nödtorftig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Intet ohöfviskt tal gånge utaf edar mun; utan det nyttigt är till förbättring, der det behöfves; att det må dem, som det höra, till tacka vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Och bedröfver icke Guds Helga Anda, der I med beseglade ären till förlossningenes dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'All bitterhet och grymhet, och vrede, och rop, och hädelse vare långt ifrån eder, samt med alla ondsko.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Men varer inbördes till hvarannan vänlige, godhjertige; och förlåter den ene dem andra, såsom ock Gud genom Christum hafver förlåtit eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Så varer nu Guds efterföljare, såsom älskelige barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Och vandrer i kärlekenom, såsom ock Christus hafver älskat oss, och utgifvit sig sjelf för oss till gåfvo och offer, Gudi till en söt lukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Boleri och all slemhet, eller girighet låter ibland eder icke ens nämnda varda, såsom helgon tillhörer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Och slem ord, eller gäckeri, eller skämt som icke höfves; utan heldre tacksägelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Ty I skolen veta, att ingen bolare, eller oren, eller giriger, hvilken är en afgudadyrkare, hafver arfvedel uti Christi och Guds rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Låter eder ingen förföra med fåfäng ord; ty för sådana plägar Guds vrede komma öfver otrones barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Derföre varer icke deras stallbröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Ty I voren fordom mörker, men nu ären I ljus i Herranom; vandrar såsom ljusens barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Ty Andans frukt är uti all godhet, och rättfärdighet, och sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Och pröfver hvad Herranom täckt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Och hafver ingen delaktighet med de onyttiga mörksens verk; utan straffer dem heldre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Ty hvad hemliga af dem sker, det är ock skamligit att säga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Men allt detta varder uppenbart, när det af ljuset straffadt varder; ty allt det uppenbart varder, det är ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Derföre säger han: Vaka upp, du som sofver, och statt upp ifrå de döda, så varder Christus dig upplysandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Så ser nu till, huru I vandren visliga; icke som de ovise, utan som vise.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Och skicker eder efter tiden; ty tiden är ond.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Derföre, varer icke oförståndige, utan förståndige hvad Herrans vilje är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Och dricker eder icke druckna af vin, af hvilko ett oskickeligit väsende kommer; utan uppfyllens af den Helga Anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Talande emellan eder i psalmer, och lofsånger, och andeliga visor; sjungandes och spelandes Herranom uti edor hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Alltid tacksägandes Gudi och Fadrenom för hvar man, uti vårs Herras Jesu Christi Namn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Ymsom underdånige, den ene dem andra, i Guds räddhåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Hustrurna vare sina män underdåniga, såsom Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Ty mannen är hustruns hufvud; såsom ock Christus är församlingenes hufvud; och han är ock sins kropps helsa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Såsom nu församlingen är underdånig Christo, så skola ock hustrurna uti all ting vara sina män underdåniga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'I män, älsker edra hustrur, såsom ock Christus älskade församlingen, och hafver utgifvit sig sjelf för henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'På det han henne helga skulle, och hafver gjort henne rena i vattnsens bad, genom ordet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'På det han skulle beställa sig sjelf ena församling, den härlig är, den ingen fläck eller skrynko hafver, eller annat sådant; utan att hon skulle vara helig och ostraffelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Så skola ock männerne älska sina hustrur, såsom sina egna kroppar. Den sina hustru älskar, han älskar sig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Ty ingen hafver någon tid hatat sitt eget kött; utan heldre föder och fordrar det, såsom ock Herren församlingen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Ty vi äre ledamöter af hans kropp, af hans kött, och af hans benom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Fördenskull skall menniskan öfvergifva sin fader och moder, och blifva vid sin hustru, och af tvåm varder ett kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Denna hemlighet är stor; men jag talar om Christo och församlingen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Dock ock I, hvar i sin stad, älske sina hustru, såsom sig sjelf; men hustrun hafve mannen i vördning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'I barn, varer hörige edra föräldrar i Herranom; ty det är rättvist.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Hedra din fader och moder; hvilket är det första bud, som löfte med sig hafver:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'På det dig skall väl gå, och du må blifva långlifvad på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'I fäder, reter icke edor barn till vrede; utan uppföder dem i tukt och Herrans förmaning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'I tjenare, varer hörige edrom lekamligom herrom med räddhåga och bäfvan, i edor hjertas enfaldighet, såsom Christo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Icke tjenande allena för ögonen, såsom menniskom till vilja; utan såsom Christi tjenare, görande det Gud vill utaf hjertat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Med välviljoghet låter eder tycka, att I tjenen Herranom, och icke menniskom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Vetande, att hvad godt hvar och en gör, det skall han igenfå af Herranom, ehvad han är tjenare eller fri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Och I herrar, görer ock detsamma emot dem, och öfvergifver trug; vetande, att ock edar Herre är i himmelen, och för honom är intet anseende till personen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'På det sista, käre bröder, varer starke i Herranom, och i hans starkhets magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Ikläder eder allt Guds harnesk, på det I mågen stå emot djefvulens listiga anlopp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Ty vi hafvom icke strid emot kött och blod; utan emot Förstar och väldiga, nämliga emot verldenes herrar, de som regera i denna verldenes mörker, emot de onda andar under himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Derföre, tager på eder allt Guds harnesk, att I mågen emotstå i den onda dagen, och all ting väl uträtta, och beståndande blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Så står nu omgjordade kringom edra länder med sanningene, och iklädde rättfärdighetenes kräfveto;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Och fötterna skodde, att I mågen redo vara till fridsens Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Men öfver all ting tager trones sköld, med hvilkom I kunnen utsläcka all hins ondas glödande skott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Och tager på eder salighetenes hjelm, och Andans svärd, som är Guds ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'I all bön och åkallan, alltid bedjande i Andanom; och vaker dertill, med all idkelighet, och bön för all helgon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Och för mig, att mig måtte gifvet varda tala dristeliga med öppen mun, att jag måtte kunniga göra Evangelii hemlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Hvilkets bådskap jag är i denna kedjon; på det jag deruti må fri tala, som mig bör tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Men på det I mågen ock veta, huru med oss tillstår, och hvad jag gör, skall Tychicus, min älskelige broder och trogne tjenare i Herranom, eder undervisa;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Hvilken jag derföre sände till eder, att I skolen få veta, huru med mig tillstår; och att han skulle trösta edor hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Frid vare bröderna, och kärlek med trone, af Gud Fader och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Nåd vare med allom, som vår Herra Jesum Christum rättsinneliga kär hafva. Amen. Sänd af Rom till de Epheser, med Tychico.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulus och Timotheus, Jesu Christi tjenare, allom heligom i Christo Jesu, som äro i Philippis, samt med Biskopar och tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Nåd vare med eder, och frid af Gudi, vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Jag tackar min Gud, så ofta jag tänker på eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Hvilket jag alltid gör i alla mina böner för eder alla, och gör samma bön med glädje;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Att I ären delaktige vordne i Evangelio, ifrå första dagen intill nu;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Och förser mig detsamma, att den uti eder ett godt verk begynt hafver, han skall det ock fullborda, intill Jesu Christi dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Såsom mig rätt är, att jag den meningen hafver om eder alla; derföre att jag i minom bojom, i hvilkom jag försvarar och stadfäster Evangelium, hafver eder i mitt hjerta, såsom de der alle med mig delaktige ären i nådene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Ty Gud är mitt vittne, huru jag åstundar eder alla af hjertans grund i Jesu Christo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Och beder, att edar kärlek ju mer och mer må rik varda i all kunskap, och i allt förstånd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Att I mågen bepröfva hvad bäst är; på det I mågen vara rene, och ingom till förargelse, intill Christi dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Uppfyllde med rättfärdighetenes frukt, hvilken genom Jesum Christum kommer till Guds pris och lof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Jag vill att I veta skolen, käre bröder, att det med mig skedt är, det är mer kommet Evangelio till framgång;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Så att mina bojor äro uppenbara vordna i Christo, öfver hela Rådhuset, och när alla andra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Och att månge bröder i Herranom, styrkte af minom bojom, äro dess dristigare vordne till att tala ordet utan räddhåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Somlige predika ock Christum för afunds och trätos skull, och somlige uti en god mening.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'De förre predika Christum af kif, och icke renliga; menandes dermed föröka bedröfvelsen till mitt fängelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Men de sednare af kärlek, vetandes att jag här ligger till Evangelii försvarelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Hvad äret då? Att ju Christus förkunnad varder, i hvad måtto det ske kan, antingen af tillfälle, eller sannskyldeliga; deraf fröjdar jag mig, och jemväl fröjda vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Ty jag vet, att det kommer mig till salighet, genom edra bön, och Jesu Christi Andas tillhjelp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Såsom jag visserliga väntar och förhoppas, att jag uti ingen ting skall till blygd komma; utan med all frihet, såsom alltid, så ock nu, måtte Christus afhållen varda i minom lekamen, ehvad det är genom lif, eller genom död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Ty Christus är mitt lif, och döden är min vinning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Men efter det, att lefva i köttet, tjenar mer till att göra frukt, så vet jag icke hvilket jag utvälja skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Ty både delarne ligga mig hårdt uppå. Jag åstundar skiljas hädan, och vara när Christo; hvilket ock mycket bättre vore;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Men det är mer nödtorftigt blifva i köttet för edra skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Och vet jag visserliga, att jag skall blifva, och med eder allom vara, eder till godo, och till trones fröjd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'På det I mågen storliga berömma eder af mig i Christo Jesu, genom min igenkommelse till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Allenast vandrer såsom Christi Evangelio värdt är; att hvad jag heldre kommer och får eder se, eller frånvarandes får höra om eder, att I blifven ståndande uti enom anda och ene själ, samt med oss kämpande uti Evangelii tro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Och uti ingen ting förskräcken eder för edra motståndare, hvilket dem är ett tecken till förtappelse; men eder till salighet, och det af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Ty eder är gifvet för Christo, icke allenast att I tron på honom, utan jemväl liden för hans skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Hafvande samma stridena, som I sågen i mig, och I nu hören om mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Är nu någor förmaning när eder i Christo; är någor tröst i kärlekenom; är någor Andans delaktighet; är någor hjertelig kärlek och barmhärtighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Så uppfyller mina glädje, att I ären ens till sinnes, lika kärlek hafvande, endrägtige, samhällige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Att intet sker med kif eller fåfäng äro; utan med ödmjukhet räkne hvar den andra yppare än sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Ser icke hvar på sitt eget bästa, utan hvar och en på ens annars bästa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Hvar och en vare så till sinnes, som ock Christus Jesus var;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Hvilken, ändå han var i Guds skepelse, räknade han icke för rof Gudi jemlik vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Utan förnedrade sig sjelf, tagandes på sig en tjenares skepelse, och vardt lika som en annor menniska, och i åthäfvor funnen som en menniska;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Ödmjukade sig sjelf; vardt lydig intill döden, ja, intill korsens död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Derföre hafver ock Gud förhöjt honom, och gifvit honom ett Namn, det öfver all namn är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Att i Jesu Namn skola sig böja all knä, deras som i himmelen, på jordene, och under jordene äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Och alla tungor skola bekänna, att Jesus Christus är Herren, Gud Fader till äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Så, mine älskelige, som I alltid hafven varit lydige, icke allenast i mine närvaro, utan ock nu mycket mer i mine frånvaro, skaffer med fruktan och bäfvan, att I salige varden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Ty Gud är den som verkar i eder både vilja och gerning, efter sitt goda behag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Görer all ting utan knorr och tvekan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'På det I mågen vara oförtalade och rene, och Guds barn ostraffelige, midt ibland det vanartiga och vrånga slägtet; ibland hvilka lyser såsom ljus i verldene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Att I blifven vid lifsens ord, mig till en berömmelse på Christi dag, att jag icke fåfängt lupit, eller fåfängt arbetat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Och om jag än offras öfver edra tros offer och Gudstjenst, så gläder jag mig, och fröjdar mig med eder alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'För det sammas skull skolen I ock glädjas, och skolen glädjas med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Men jag hoppas i Herranom Jesu, att jag innan kort varder sändandes till eder Timotheum; att jag ock må varda vid ett godt mod, då jag förnimmer huru med eder tillstår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Ty jag hafver ingen, den som så alldeles lika med mig till sinnes är, den så hjerteliga omsorg hafver för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Ty de söka alle efter sitt eget, icke det Christo Jesu tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Men I veten, att han bepröfvad är; ty såsom ett barn med fadrenom, hafver han med mig tjent uti Evangelio.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Honom hoppas mig nu sända, det första jag hafver besett min ärende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Jag tröstar ock på Herran, att jag ock sjelf snart kommandes varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Mig hafver ock synts nödtorftigt vara sända till eder Epaphroditum, brodren, min medhjelpare och medstridare, och edar Apostel, den ock mig uti mine nödtorft tjenar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Efter han hade en åstundan till eder alla, och var storliga bekymrad deraf, att I sport haden honom krankan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Som han ock visserliga var dödssjuk; men Gud förbarmade sig öfver honom; och icke allenast öfver honom, utan ock öfver mig, att jag icke skulle få sorg på sorg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Jag hafver nu sändt honom dess snarare, att I skolen få se honom, och dess gladare varda igen, och jag dess mindre sorg hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Så undfår nu honom i Herranom med alla glädje; och de sådane äro, dem hafver i vördning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Ty för Christi verks skull var han dödenom så när kommen, att han fögo tänkte på lifvet; på det han skulle tjena mig i edar stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Ytterligare, mine bröder, Fröjder eder i Herranom. Att jag eder ju allt detsamma skrifver, det förtryter mig intet; men det gör eder dess vissare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Vakter eder för de hundar, vakter eder för de onda arbetare, vakter eder för afskärelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Ty vi äre omskärelsen, vi som tjene Gudi i Andanom, och berömmom oss af Christo Jesu, och sättom icke tröst på köttet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Ändock jag ock väl må trösta på köttet. Hvar en annar sig tycka låter, att han må förtrösta sig på köttet, jag mycket mer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Som på åttonde dagen omskoren är, en af Israels folk och BenJamins slägte, en Ebree af Ebreer, efter lagen en Pharisee;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Efter nitet förföljandes församlingen, efter den rättfärdighet, som är af lagen, ostraffelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Men det mig en vinning var, det hafver jag räknat för skada, för Christi skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Ja, jag räknar det allt för skada emot den öfversvinneliga mins Herras Christi Jesu kunskap; för hvilkens skull jag allt hafver för skada räknat, och håller det för träck, på det jag må vinna Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'Och varda funnen i honom, icke hafvandes mina rättfärdighet, som kommer af lagen, utan den som af Christi tro kommer; nämliga den rättfärdighet, som af Gudi kommer genom trona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Till att känna honom, och hans uppståndelses kraft, och hans pinos delaktighet, lik vorden hans död;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Om jag ock måtte komma emot honom i de dödas uppståndelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Icke att jag allaredo hafver det fattat, eller allaredo fullkommen är; men jag far fast der efter, om jag det ock fatta må, som jag ock fattad är af Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Käre bröder, jag kan icke säga, att jag ännu sjelf det fattat hafver; men ett säger jag: Jag förgäter det till rygga är, och sträcker mig till det som frammantill är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Jagandes efter målet, som föresatt är, till den lön som förehålles ofvanefter, af Guds kallelse i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Så månge vi nu fullkomne äre, varom så sinnade; och om I något annorlunda hålla skolen, så låter Gud eder det uppenbara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Dock så, att vi uti det, der vi allaredo tillkomne äre, vandrom efter ena reglo, och äre ens sinnade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Varer ock, käre bröder, mine efterföljare, och ser på dem som så vandra, som I oss för en efterdömelse hafven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Ty månge vandra, af hvilkom jag eder ofta sagt hafver, men nu säger jag ock gråtandes, fiendar till Christi kors;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Hvilkas ände är förtappelse, och deras buk deras Gud, och deras ära till skam, de der akta hvad jordena tillhörer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Men vår umgängelse är i himmelen, dädan vi ock vänte Frälsaren, Herran Jesum Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Hvilken vår skröpliga lekamen skall förklara; på det han skall göra honom lik med sinom förklarada lekamen, af den kraft der han med förmår sig all ting underlägga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Så, mine käre och önskade bröder, min fröjd och min krona, blifver så ståndande i Herranom, mine älskelige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Evodiam förmanar jag, och Syntychen förmanar jag, att de äro ens till sinnes i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ja, jag beder ock dig, min rättsinniga make, var dem behjelpelig, som med mig öfver Evangelium stridt hafva, samt med Clement, och andra mina medarbetare, hvilkas namn äro uti lifsens bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Fröjder eder i Herranom alltid; och åter säger jag: Fröjder eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Edor saktmodighet låter allom menniskom kunnoga varda. Herren är när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Hafver ingen omsorg; utan edart begär vare kunnigt inför Gud, i all ting, med bön, åkallan, och tacksägelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Och Guds frid, som öfvergår allt förstånd, förvare edor hjerta, och edart sinne, i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Yttermera, käre bröder, hvad sant är, hvad ärligit är, hvad rätt, hvad kyskt, hvad ljufligit, hvad väl lyder; är någor dygd, och är något lof, tänker derefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Hvad I ock lärt, och undfått, och hört, och sett hafven på mig, det görer; och så varder fridsens Gud med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Men jag är storliga fröjdad i Herranom, att I ären åter komne dertill, att I hafven omsorg om mig; ändock I väl allstädes omsorg haft hafven; men tiden sade icke så till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Detta säger jag icke derföre, att mig något fattas; ty jag hafver lärt, ibland dem jag umgår, låta mig nöja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Jag kan låg vara; jag kan ock hög vara; allestäds och i all ting är jag skickelig, både mätt och hungrig vara, både nog hafva och nöd lida.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'All ting förmår jag, genom Christum, som mig mägtigan gör.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Dock hafven I rätt gjort, att I hafven tagit eder min bedröfvelse till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Veten I ock väl, I Philipper, att af första Evangelii begynnelse, då jag drog utu Macedonien, ingen församling hafver något delat med mig, efter räkenskap, i utgift och uppbörd, utan I allena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Ty I sänden ena reso, och så andra, till mig i Thessalonica, till min nödtorft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Icke att jag söker sådana skänker; utan söker derefter, att uti edar räkenskap skall en öfverflödig frukt finnas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Ty jag hafver allt, och öfverflödar, och är uppfylld, sedan jag undfick, med Epaphroditus, det som ifrån eder sändt var, en söt lukt, ett offer, Gudi täckt och anammeligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Men min Gud skall eder uppfylla alla edra nödtorft, efter sina rikedomar i härlighetene, genom Christum Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Men Gudi och vårom Fader vare pris af evighet till evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Helser all helgon i Christo Jesu. Eder helsa de bröder, som med mig äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Eder helsa all helgon, enkannerliga de, som äro utaf Kejsarens hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Vårs Herras Jesu Christi nåd vare med eder allom. Amen. Skrifven af Rom, med Epaphrodito.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulus, Jesu Christi Apostel, genom Guds vilja, och Timotheus brodren;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'De helgon, och trogna bröder i Christo, som äro i Colossen: Nåd vare med eder, och frid af Gudi, vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Vi tackom Gudi, och vårs Herras Jesu Christi Fader, och bedjom alltid för eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Ty vi hafve sport edra tro i Christo Jesu, och (edar) kärlek till all helgon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'För det hopps skull, som eder är förvaradt i himmelen; af hvilket I tillförene hört hafven, genom Evangelii sanna ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Som till eder kommet är, såsom ock i alla verldena, och är fruktsamt, såsom ock i eder, ifrå den dag I hörden och förnummen Guds nåd i sanningene,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Som I ock lärt hafven af Epaphra, vår älskeliga medtjenare, hvilken är en trogen Christi tjenare för eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Den ock oss undervist hafver edar kärlek i Andanom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Derföre ock vi, ifrå den dag vi det hördom, vände vi icke igen bedja för eder och önska, att I mågen uppfyllde varda med hans viljas kunskap, uti all andelig visdom och förstånd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Att I mågen vandra värdeliga Herranom till allt behag; och ären fruktsamme i alla goda gerningar, och växen till i Guds kunskap;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Och stärkte varden med allo kraft, efter hans härliga magt, uti allt tålamod och långmodighet, med glädje;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Och tacken Fadrenom, som oss hafver beqväma gjort till att delaktige vara i de heligas arfvedel i ljuset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Hvilken oss uttagit hafver ifrå mörksens väldighet, och hafver försatt oss uti sin älskeliga Sons rike;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'I hvilkom vi hafve förlossning genom hans blod, nämliga syndernas förlåtelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Hvilken är osynliga Guds beläte, förstfödder för all kreatur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Ty genom honom äro all ting skapade, som i himmelen och på jordene äro, synliga och osynliga, vare sig thron, eller herrskap, eller Förstadöme, eller Öfverhet; allt är skapadt genom honom, och till honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Och han är för alla, och all ting bestå i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Och han är hufvudet till kroppen, nämliga till församlingena, hvilken är begynnelsen, förstfödd ifrå de döda, på det han i all ting skall hafva föregången.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Ty behageligit hafver varit (Fadrenom), att all fullhet skulle bo i honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Och att han genom honom all ting försona skulle med sig sjelf; tillfridsställandes, genom blodet på hans kors, både det på jordene och i himmelen är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Och eder, som fordom voren främmande, och fiender med sinnet i onda gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Men nu hafver han försonat eder med sins kötts lekamen, genom döden; på det han skulle ställa eder heliga, och ostraffeliga, och obesmittade, i sin åsyn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Om I annars blifven i trone, grundade, och faste, och orörlige ifrå det hopp som i Evangelio är, hvilket I hört hafven, och predikadt är för all kreatur, som under himmelen äro, hvilkets jag Paulus är en tjenare vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Nu fröjdar jag mig uti mitt lidande för eder, och uppfyller i mitt kött hvad som fattas i Christi lidande, för hans lekamen, som är församlingen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Hvilkens tjenare jag vorden är, efter Guds predikoämbete, det mig gifvet är ibland eder, att jag Guds ord rikeliga predika skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Nämliga den hemlighet, hvilken fördold hafver varit ifrå verldenes begynnelse, och evig tid; men nu är uppenbar vorden hans helgon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Hvilkom Gud ville kunnigt göra, hvilken denna hemlighetenes härliga rikedom är ibland Hedningarna, hvilken är Christus uti eder, härlighetenes hopp;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Den vi förkunnom, förmanande hvar menniska i all visdom; på det vi skole ställa hvar menniska fullbordada i Christo Jesu;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Der jag ock på arbetar och kämpar, efter hans verkan som krafteliga verkar i mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Så vill jag att I veta skolen, hvilken kamp jag hafver om eder, och om dem som äro i Laodicea, och om alla dem som min person i köttet icke sett hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'På det deras hjerta måga få någon hugnad, och sammanfogade varda i kärlekenom, till all rikedom uti fullkomligit förstånd, till att kunna besinna Guds hemlighet, både Fadrens och Christi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Uti hvilkom fördolda ligga alla visdoms och förstånds håfvor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Men detta säger jag, på det ingen skall bedraga eder med klok ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Ty ändock jag är ifrån eder efter köttet, är jag dock när eder i Andanom, fröjdar mig, och ser edor skickelse, och edar tros stadighet på Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Såsom I nu anammat hafven Herran Christum Jesum, så vandrer i honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Och varer rotade och uppbyggde i honom, och varer faste i trone, såsom I lärde ären, och varer i henne rikeliga tacksamme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Ser till, att eder icke någor bortröfvar med Philosophia och fåfängt bedrägeri, efter menniskors stadgar, och efter verldenes stadgar, och icke efter Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Ty i honom bor all Gudomsens fullhet lekamliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Och I ären i honom fullkomne, hvilken är hufvudet öfver all Förstadöme och väldighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'I hvilkom I ock omskorne ären med den omskärelse, som sker utan händer, då I afladen syndakroppen i köttet, nämliga med Christi omskärelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'I det, att I med honom begrafne ären genom dopet; i hvilkom I ock uppståndne ären genom trona, den Gud verkar, hvilken honom uppväckt hafver ifrå de döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Han hafver ock gjort eder lefvande med honom, då I döde voren i synderna, och uti edars kötts förhud; och hafver förlåtit oss alla synder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Och afplånat den handskrift, som oss emot var; hvilken af stadgarna kom, och var oss emot; och den hafver han tagit oss af vägen, och naglat vid korset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Och hafver blottat Förstadömen, och väldigheterna, och fört dem uppenbarliga, och gjort en härlig seger af dem, genom sig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Så låter nu ingen göra eder samvet öfver mat, eller dryck, eller öfver bestämda helgedagar, eller nymånader, eller Sabbather;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Hvilket är skuggen af det som tillkommande var; men kroppen sjelf är i Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Låter ingen taga eder lönen ifrå, den som vandrar efter egen godtycko i Änglaödmjukhet och andelighet, i de ting han aldrig sett hafver, och är förgäfves uppblåst i sitt köttsliga sinne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'Och håller sig icke vid hufvudet, af hvilko hele lekamenen genom leder och ledamot kraft får och tillsammans hänger, och tillväxer i den förökelse som Gud gifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Efter I nu döde ären med Christo, ifrå de verldsliga stadgar; hvi låten I eder då begripas med beskrefna stadgar, lika som I ännu lefden i verldene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'De der säga: Du skall icke komma vid det; icke smaka det; icke handtera det;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Hvilket dock allt förgås i brukningene, och är efter menniskors bud och lärdom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Hvilke hafva väl ett sken af visdom, genom sjelftagen andelighet och ödmjukhet, och derigenom att de icke skona kroppen, och göra icke köttena dess äro till dess nödtorft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Om I nu ären uppståndne med Christo, så söker det ofvantill är, der Christus är sittandes på Guds högra hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Farer efter det som ofvantill är, icke efter det som på jordene är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Ty I ären döde, och edart lif är fördoldt med Christo i Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Men när edart lif, Christus, uppenbarad varder, då varden ock I uppenbarade med honom i härligheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Så döder nu edra lemmar, som på jordene äro; boleri, orenlighet, lusta, ond begärelse och girighet, hvilken afgudadyrkan är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'För hvilka styckers skull Guds vrede kommer öfver otrones barn;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Uti hvilka I ock fordom vandraden, då I deruti lefden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Men lägger ock nu I bort alltsammans, vrede, grymhet, ondsko, försmädelse, skamlig ord, af edar mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Ljuger icke för hvarannan; afkläder eder den gamla menniskan med hans gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'Och ikläder eder den nya, den der förnyas till hans kunskap och beläte, som honom skapat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Der icke Grek och Jude är, omskärelse och förhud, Barbarisk och Scytisk, tjenare och fri, utan allt i allom Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Så kläder eder nu såsom Guds utkorade, helgon och älskelige, uti hjertans barmhertighet, vänlighet, ödmjukhet, saktmodighet, långmodighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Och unddrager hvarannan, och förlåter hvarandrom, om någor hafver någon klagomål emot den andra; såsom ock Christus eder förlåtit hafver, så görer ock I.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Men öfver allt detta ikläder eder kärleken, hvilken är fullkomlighetenes band.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Och Guds frid regere i edor hjerta, till hvilken I ock kallade ären uti en lekamen; och varer tacksamme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Låter Christi ord rikeliga bo uti eder med all visdom; lärer och förmaner eder inbördes med Psalmer och lofsånger, och andeliga visor i nådene, och sjunger Herranom i edart hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Och allt det I gören, med ord eller gerning, det görer allt i Herrans Jesu Namn, och tacker Gudi och Fadrenom genom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'I hustrur, varer edra män underdåniga, såsom tillbörligit är, i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'I män, älsker edra hustrur, och varer icke bittre emot dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'I barn, varer edra föräldrar lydige i all ting; ty det täckes väl Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'I fäder, reter icke edor barn; på det de icke skola vara klenmodige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'I tjenare, varer lydige edra köttsliga herrar i all ting; icke med tjenst för ögonen, såsom menniskom till vilja, utan med hjertans enfaldighet, och med Gudsfruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Allt hvad I gören, det görer af hjertat, såsom Herranom, och icke menniskom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Och veter, att I af Herranom skolen få arfsens lön; ty I tjenen Herranom Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Men den som orätt gör, han skall undfå hvad han orätt gjort hafver; och varder intet anseende till personen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'I herrar, hvad lika och rätt är, det beviser tjenaromen; vetande, att I hafven ock en Herra i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Håller uppå bedja, och vaker deruti med tacksägelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Bedjande också för oss, att Gud ville upplåta oss ordsens dörr, till att tala Christi hemlighet, för hvilket jag ock bunden är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Att jag må det uppenbara, såsom mig bör att tala.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Vandrer visliga med dem som utantill äro, och skicker eder efter tiden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Edart tal vare alltid ljufligit, och med salt förmängdt, att I veten huru I skolen svara hvarjom och enom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Huru med mig går, skall Tychicus, min älskelige broder, och trogne tjenare och medtjenare i Herranom, eder allt kungöra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Hvilken jag hafver till eder sändt fördenskull, att han skall få veta, huru det hafver sig med eder, och att han må hugsvala edor hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Samt med Onesimo, minom trogna och älskeliga broder, hvilken en af eder är; de skola eder undervisa allt, huru här tillstår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Helsar eder Aristcarchus, min medfånge, och Marcus, Barnabe syssling, af hvilkom I hafven fått några befallningar; kommer han till eder, så undfår honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Och Jesus, som kallas Justus, hvilke äro af omskärelsen; desse äro allena mine medhjelpare till Guds rike, de mig ock varit hafva till hugnad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Helsar eder ock Epaphras, den en af eder är, Christi tjenare, alltid arbetandes för eder i böner, på det I mågen blifva ståndande fullkomlige, och uppfyllde i all Guds vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Jag bär vittnesbörd med honom, att han hafver mycken omsorg om eder, och dem i Laodicea, och dem i Hierapoli.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Helsar eder Lucas, läkaren, den älskelige, och Demas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Helser de bröder i Laodicea, och Nympham, och den församling, som i hans hus är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Och då Epistelen är läsen när eder, så beställer att han varder ock läsen för den församling i Laodicea; och att I ock den Laodiska Epistelen läsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Och säger Archippo: Se på ämbetet som du fått hafver i Herranom, att du det uträttar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Mina helsning med mine Pauli hand. Tänker på mina bojor. Nåd vare med eder. Amen. Skrifven af Rom, med Tychico och Onesimo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulus, och Silvanus, och Timotheus, den församling i Thessalonica, uti Gud Fader, och Herranom Jesu Christo: Nåd vare med eder, och frid af Gudi, vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Vi tackom Gudi alltid för eder alla, och hafvom eder i åminnelse i våra böner, utan återvändo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Tänkande på edart verk i trone, och på edart arbete i kärleken, och på edart tålamod i hoppet, hvilket är vår Herre, Jesus Christus, för Gudi och vårom Fader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Ty, käre bröder, af Gudi älskade, vi vete, huru I ären utvalde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Att vårt Evangelium hafver varit när eder, icke allenast med ordom, utan både i kraft, och i den Helga Anda, och i fulla visshet, såsom I veten, hurudana vi vorom när eder, för edra skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Och I ären vordne våre efterföljare, och Herrans; och hafven anammat ordet ibland mång bedröfvelse, med den Helga Andas fröjd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Så att I ären vordne en efterdömelse allom trognom uti Macedonia och Achaja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Ty af eder är Herrans ord utgånget, icke allenast i Macedonia, och Achaja; utan ock i all rum är edor tro, som I hafven till Gud, utkommen; så att oss är icke behof att säga något.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Ty de sjelfve förkunna om eder, hurudana ingång vi hadom till eder; och huru I omvände vorden till Gud ifrån afgudarna, till att tjena den lefvande och sanna Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'Och till att vänta hans Son af himmelen, hvilken han uppväckt hafver ifrå de döda, Jesum, den oss frälsar ifrå den tillkommande vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Käre bröder, I veten sjelfve vår ingång till eder, att han var icke fåfäng;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Utan, såsom vi tillförene hade lidit, och försmädde varit uti Philippis, som I veten, vorom vi ändå vid god tröst i vårom Gud, till att tala när eder Guds Evangelium, med mycken kämpning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Ty vår förmaning var icke till villfarelse, icke heller till orenlighet, icke heller med list;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Utan, såsom vi af Gudi bepröfvade vorom, att oss Evangelium betrodt är till att predika, så talom vi; icke såsom vi ville täckas menniskom, utan Gudi, den der pröfvar vår hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Ty vi hafve icke umgått med smekligom ordom, såsom I veten, icke heller med tillfälle till girighet; Gud är dess vittne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Hafvom icke heller sökt pris af menniskom, hvarken af eder, eller androm;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Ändock vi väl hadom haft magt att förtunga eder, såsom Christi Apostlar; men vi vorom milde när eder, lika som en amma fostrar sin barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Så hafvom vi hjertans lust haft till eder, att dela med eder icke allenast Guds Evangelium, utan ock vårt eget lif; ty I ären oss käre vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'I minnens väl, käre bröder, vårt arbete och vår mödo; ty dag och natt arbetade vi, på det vi ingen af eder skulle förtunga; och predikadom ibland eder Guds Evangelium.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Dess ären I vittne, och Gud, huru heliga, huru rättfärdeliga och ostraffeliga vi umgingom med eder, som trodden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Såsom I veten, att vi, såsom en fader sin barn, hafve förmanat och tröstat hvar och en ibland eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Och betygat, att I värdeliga skullen vandra för Gudi, den eder kallat hafver till sitt rike och härlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'För hvilket vi ock utan återvändo tackom Gudi, att, då I anammaden af oss det predikade ordet om Gud, anammaden I det icke såsom menniskors ord, utan såsom det sannerliga är, som Guds ord, hvilken ock verkar i eder, som tron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Ty I ären vordne, käre bröder, de Guds församlingars efterföljare, som uti Judeen äro, i Christo Jesu, att I detsamma lidit hafven af edra egna fränder, som de af Judomen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Hvilke ock Herran Jesum dråpo, och sina egna Propheter; och hafva förföljt oss, och täckas icke Gudi, och allom menniskom äro de emot;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Förbjuda oss undervisa Hedningomen, dermed de skola salige varda, på det de skola fullkomna sina synder alltid; ty vreden är kommen öfver dem intill ändan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Men vi, käre bröder, sedan vi till någon tid hade mist eder efter ansigtet, och icke efter hjertat, hafve vi dess mer hastat till att se edart ansigte, med stor begärelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Derföre hadom vi velat komma till eder (jag Paulus), två resor; och Satanas hafver oss förhindrat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Ty hvad är vårt hopp, eller fröjd, eller kronan till vår berömmelse? Ären ock icke I det, för vårom Herra Jesu Christo i hans tillkommelse?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'I ären ju vår pris och fröjd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Derföre kundom vi icke länger hafvat fördrag; och oss syntes, att vi uti Athen allena skulle qvare blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'Och hafve sändt Timotheum, vår broder, och Guds tjenare, och vår hjelpare i Evangelio Christi, till att styrka och trösta eder i edra tro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'På det ingen skulle låta vika sig uti denna bedröfvelse; ty I veten, att vi ärom dertill satte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Ty när vi vorom när eder, sade vi eder det tillförene, att vi måste lida bedröfvelse; såsom ock skedt är, och I veten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Derföre kunde jag ock icke länger hafvat fördrag, utan sände åstad; på det jag skulle förfara edra tro, att tilläfventyrs frestaren icke hade försökt eder, och vårt arbete hade då fåfängt vordit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Men nu nyliga, sedan Timotheus kommen var till oss ifrån eder, och underviste oss edra tro och kärlek; och att I alltid tänken på oss till det bästa, och åstunden att se oss, såsom ock vi eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Vordom vi, käre bröder, hugsvalade på eder, uti all vår bedröfvelse och nöd, genom edra tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Ty vi lefve nu, efter I stån i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Hvad tack kunne vi Gudi säga för eder, för all den glädje som vi hafve af eder, för vår Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Vi bedje dag och natt ganska mycket, I att vi mågom se edart ansigte, och uppfylla det i edra tro fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Men Gud sjelfver, och vår Fader, och vår Herre Jesus Christus, skicke vår väg till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Men Herren föröke eder, och låte kärleken öfverflöda inbördes och till hvar man; såsom ock vi äre till eder:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Att edor hjerta måga styrkt och ostraffelig blifva, i helighet, för Gudi och vårom Fader, uti vårs Herras Jesu Christi tillkommelse, med all hans helgon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Yttermera, käre bröder, bedje vi eder, och förmane genom vår Herra Jesum, såsom I hafven undfångit af oss, huru I vandra skolen, och täckas Gudi, att I ju mer fullkomlige varden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Ty I veten hvad bud vi gåfvom eder, genom Herran Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Ty detta är Guds vilje, edor helgelse, att I flyn boleri;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Och hvar och en af eder vet behålla sitt fat i helgelse och äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Icke uti lustig begärelse, såsom Hedningar, de som af Gudi intet veta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Och att ingen förtrycker eller sviker sin broder i någon handel; ty Herren är hämnaren öfver allt detta; såsom vi ock eder tillförene sadom och betygadom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Ty Gud hafver icke kallat oss till orenlighet, utan till helgelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Den der nu föraktar, han föraktar icke någon mennisko, utan Gud, den sin Helga Anda hafver gifvit i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Men om broderlig kärlek görs icke behof att jag skrifver eder; ty I ären sjelfve lärde af Gudi, att I skolen älska eder inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Och det gören I ock på alla bröderna, som i hela Macedonien äro; men vi förmane eder, käre bröder, att I ju mer fullkomlige varden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Och vinnlägger eder, att I ären rolige, och sköter edor egen stycke; och arbeter med edra händer, såsom vi eder budit hafve;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Att I hafven eder ärliga med dem, som utantill äro; och att I deras intet betorfven.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Men vi vilje icke dölja för eder, käre bröder, om dem som afsomnade äro, att I icke sörjen, såsom de andre, de der intet hopp hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Ty om vi tro, att Jesus är döder och uppstånden, så skall ock Gud dem, som afsomnade äro, genom Jesum framhafva med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Ty detta säge vi eder, såsom Herrans ord, att vi, som lefve och igenblifve uti Herrans tillkommelse, skole icke förekomma dem som sofva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Ty sjelfver Herren skall stiga ned af himmelen med härskri, och Öfverängels röst, och med Guds basun; och de döde i Christo skola uppstå i förstone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Derefter vi som lefve och igenblifve, vardom tillika med dem borttagne i skyn emot Herran i vädret; och så skole vi blifva när Herranom alltid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Så tröster eder nu med dessa orden inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Men om tider och stunder, käre bröder, är icke behof att skrifva eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Ty I veten väl, att Herrans dag skall komma såsom en tjuf om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Derföre, när de varda sägande: Det är frid, och all ting utan fara; då skall dem hasteligit förderf öfverkomma, lika som födslopinan qvinnone påkommer, som hafvandes är; och de skola icke kunna undfly.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Men I, käre bröder, ären icke uti mörkret, att den dagen, såsom en tjuf, skall få eder fatt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Alle I ären ljusens barn, och dagsens barn; vi hörom icke nattene till, icke heller mörkret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Så låter oss nu icke sofva, såsom de andre; utan låter oss vaka och nyktre vara;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Ty de som sofva, de sofva om nattena; och de som druckne äro, de äro druckne om nattena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Men vi, som dagen tillhöre, skole nyktre vara, iklädde trones och kärlekens kräfveto, och salighetenes hopp för en hjelm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Ty Gud hafver icke satt oss till vrede, utan att äga salighet, genom vår Herra Jesum Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Den för oss död är; på det, ehvad vi vake eller sofve, skole vi lefva samt med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Derföre förmaner eder inbördes, och uppbygger hvar den andra, såsom I ock gören.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Men vi bedje eder, käre bröder, att I kännen dem som arbeta ibland eder, och stå eder före i Herranom, och förmana eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Håller dem dess kärare, för deras verks skull; och varer fridsamme med dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Men vi bedje eder, käre bröder, förmaner de osediga, tröster de klenmodiga, hjelper de svaga, varer långmodige vid hvar man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Ser till, att ingen vedergäller någrom ondt för ondt; utan alltid farer efter det goda inbördes, och med hvar man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Varer alltid glade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Bedjer utan återvändo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Varer tacksamme i all ting; ty det är Guds vilje om eder, genom Jesum Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Utsläcker icke Andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Förakter icke Prophetier.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Men pröfver all ting, och behåller det godt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Flyr allt det som ondt synes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Men sjelfver fridsens Gud helge eder öfver allt, att edar hele ande, och själ, och kropp, måtte vara behållen utan straff, i vårs Herras Jesu Christi tillkommelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Han är trofast, som eder kallat hafver; den det ock väl fullbordar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Käre bröder, beder för oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Helser alla bröderna uti en helig kyss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Jag besvär eder vid Herran, att I denna Epistelen läsa låten för alla heliga bröderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Vårs Herras Jesu Christi nåd vare med eder. Amen. Till de Thessalonicer den förra, skrifven af Athen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulus, och Silvanus, och Timotheus, den församling i Thessalonica, i Gudi vårom Fader, och Herranom Jesu Christo:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Nåd vare med eder, och frid af Gudi vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Vi skole tacka Gudi alltid för eder, käre bröder, såsom tillbörligit är; ty edor tro förökas storliga, och allas edar kärlek öfverflödar inbördes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Så att vi sjelfve berömme oss i Guds församlingar, af edart tålamod och tro, uti alla edra förföljelser och bedröfvelser, som I liden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Såsom ett bevis till Guds rättvisa dom; på det I mågen varda värdige till Guds rike; för hvilket I ock liden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Efter det är rättvist för Gudi gifva dem bedröfvelse igen, som eder bedröfva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Men eder, som bedröfvens, rolighet med oss; då Herren Jesus uppenbar varder af himmelen, samt med sine krafts Änglar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Och med eldslåga, till att hämnas öfver dem som icke känna Gud, och öfver dem som icke lydige äro vårs Herras Jesu Christi Evangelio;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Hvilke pino lida skola, det eviga förderfvet, af Herrans ansigte, och af hans härliga magt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Då han skall komma till att förklaras i sin helgon, och underlig varda i allom dem som tro; ty vårt vittnesbörd till eder om den dagen hafven I trott.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Och fördenskull bedje vi ock alltid för eder, att vår Gud ville göra eder värdiga till denna kallelsen, och uppfylla allt godhetenes uppsåt, och trones verk i kraftene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'På det vårs Herras Jesu Christi Namn må prisadt varda på eder, och I på honom, efter vår Guds och Herrans Jesu Christi nåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Men vi bedje eder, käre bröder, för vårs Herras Jesu Christi tillkommelse, och för våra församlings skull i honom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Att I icke snarliga låten beveka eder ifrån edart sinne; icke heller förskräcka, hvarken genom anda, eller genom ord, eller genom bref, lika som det sändt vore af oss, såsom Christi dag för handen vore.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Låter ingen förföra eder i någon måtto; ty han kommer icke, utan tillförene sker affall, och uppenbar varder syndenes menniska, förtappelsens barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Hvilken är en motståndare, och upphäfver sig öfver allt det Gud eller Gudstjenst kallas; så att han sätter sig i Guds tempel, såsom en Gud, och gifver sig före som han vore Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Minnens I icke, att jag sade eder detta, då jag ännu var när eder?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Och hvad ännu hindrar, veten I; att han skall varda uppenbar i sin tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Ty han verkar allaredo ondskona hemliga; allenast den der nu hindrar, han måste komma af vägen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Och så varder då den Onde uppenbar, hvilken Herren skall dräpa med sins muns Anda; och skall göra en ända med honom, genom sin tillkommelses uppenbarelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Hvilkens tillkommelse sker efter Satans verkan, med alla lögnaktiga krafter, och tecken, och under;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'Och med all förförelse till orättfärdighet, ibland dem som förtappade varda; derföre, att de icke anammade kärleken till sanningena, att de måtte salige vordit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Fördenskull skall Gud sända dem kraftig villfarelse, så att de skola tro lögnene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'På det de skola alle dömde varda, som icke hafva trott sanningene, utan hafva lust till orättfärdigheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Men vi skole alltid tacka Gudi för eder, käre bröder, älskade af Herranom, att Gud hafver eder utvalt till salighet af begynnelsen, genom Andans helgelse, och i sanningenes tro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'I hvilko han eder kallat hafver genom vårt Evangelium, till vårs Herras Jesu Christi härliga egendom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Så står nu, käre bröder, och håller eder vid de stadgar, som I lärt hafven, ehvad det är skedt af vårt ord eller bref.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Men sjelfver vår Herre, Jesus Christus, och Gud och vår Fader, den oss älskat hafver, och gifvit en evig tröst, och ett godt hopp genom nådena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Han hugsvale edor hjerta, och styrke eder uti all lärdom, och goda gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Yttermera, kära bröder, beder för oss, att Herrans ord må hafva framgång, och prisadt varda, såsom ock när eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'Och att vi mågom friade varda ifrå vanartiga och arga menniskor; ty tron är icke hvars mans.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Men Herren är trofast, den eder styrka skall, och bevara för det onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Men vi förse oss till eder i Herranom, att I gören, och görande varden, hvad vi eder budit hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Men Herren styre edart hjerta till Guds kärlek, och till Christi tålamod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Och bjudom vi eder, käre bröder, i vårs Herras Jesu Christi Namn, att I dragen eder ifrå hvar och en broder som oskickeliga vandrar, och icke efter den stadga som han hafver fått af oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Ty I veten sjelfve, huru I skolen oss efterfölja; fördenskull vi hadom oss icke oskickeliga ibland eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Icke heller tagit brödet till gäfves af någrom; utan med arbete och mödo, natt och dag, hafve vi brukat oss, på det vi ingen af eder skulle vara till tunga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Icke derföre, att vi dess icke magt hadom; utan att vi skulle gifva oss sjelfva eder till efterdömelse, att efterfölja oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Och då vi vorom när eder, böde vi eder sådant, att ho der icke ville arbeta, han skulle icke heller äta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Ty vi höre, att somlige ibland eder umgås oskickeliga, och arbeta intet, utan drifva fåfängo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Men dem som sådana äro bjude vi och förmane, genom vår Herra Jesum Christum, att de arbeta med stillhet, och äta sitt eget bröd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Men I, käre bröder, förtröttens icke göra det godt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Om nu någor icke ville lyda vårt ord, honom teckner upp i ett bref, och hafver ingen umgängelse med honom, på det han skall blygas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Dock håller honom icke såsom en ovän; utan förmaner honom såsom en broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Men sjelfver fridsens Herre gifve eder frid alltid, i allahanda måtto. Herren vare med eder allom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Helsning med mine Pauli hand, hvilket är tecknet i all bref. Så skrifver jag:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Vårs Herras Jesu Christi nåd vare med eder allom. Amen. Sänd af Athen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulus, Jesu Christi Apostel, efter Guds vår Frälsares och Herrans Jesu Christi befallning, den vårt hopp är,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timotheo, minom rättsinniga son i trone: Nåd, barmhertighet, frid af Gudi vårom Fader, och af Jesu Christo vårom Herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Såsom jag bad dig, att du skulle blifva qvar i Epheso, då jag for in i Macedonien, så gör ock; att du må bjuda somligom, att de ingen annan lärdom efterfölja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Och ingen akt gifva på fabler och slägtregister, de ingen ända hafva, och åstadkomma spörsmål, mer än förbättring till Gud, i trone.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Ty hufvudsumman af budet är kärleken af ett rent hjerta, och af ett godt samvete, och af en oskrymtad tro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Ifrå hvilken somlige hafva farit ville, och äro omvände till onyttigt sqvaller;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Och vilja vara mästare i Skriften, och förstå icke hvad de säga, eller hvad de hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Vi vete väl att lagen är god, då man henne rätteliga brukar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Vetandes, att dem rättfärdiga är ingen lag satt; utan orättfärdigom, och olydigom, ogudaktigom, och syndarom, oheligom, och oandeligom, fadermördarom och modermördarom, mandråparom,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Bolarom, drängaskändarom, menniskotjufvom, ljugarom, menedarom; och hvad annat sådant är, det en helsosam lärdom emot faller;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Efter dens saliga Guds härliga Evangelium, hvilket mig betrodt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Och jag tackar vårom Herra Christo Jesu, som mig hafver gjort mägtig, och räknat mig trogen, och satt i det ämbetet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Jag, som tillförene var en försmädare, och en förföljare, och en våldsverkare; men mig är barmhertighet vederfaren; ty jag hafver det gjort ovetandes, i otro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Men vårs Herras nåd hafver dess mer öfverflödat, genom trona och kärleken, i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Det är ett fast ord, och i alla måtto väl värdt att man det anammar, att Christus Jesus är kommen i verldena, till att frälsa syndare; ibland hvilka jag är den förnämligaste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Men mig är vederfaren barmhertighet, på det Jesus Christus skulle på mig förnämligast bevisa alla långmodighet, dem till efterdöme, som på honom tro skulle till evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Men Gudi, den eviga Konungenom, oförgängligom, osynligom, allena visom, vare pris och ära, i alla evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Detta budet befaller jag dig, min son Timothee, efter de förra Prophetier om dig, att du brukar dig deruti som en god krigsman;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Hafvandes trona, och godt samvet; hvilket somlige hafva bortdrifvit, och äro skeppsbrutne vordne i trone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Af hvilkom är Hymeneus, och Alexander, hvilka jag Satane antvardat hafver; på det de skulle lära icke mer försmäda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Så förmanar jag nu, att man för all ting hafver böner, åkallan, förböner och tacksägelser, för alla menniskor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'För Konungar, och för alla Öfverhet; på det vi måge lefva uti ett roligit och stilla lefverne, i all Gudaktighet och ärlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Ty sådant är godt och tacknämligit för Gudi, vårom Frälsare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Som vill att alla menniskor skola frälste varda, och till sanningenes kunskap komma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Ty det är en Gud, och en Medlare emellan Gud och menniskor, nämliga den menniskan Christus Jesus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Hvilken sig sjelf gifvit hafver för alla till återlösen, att sådant skulle i sin tid predikadt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Der jag ock uti skickad är en Predikare och Apostel; jag säger sanningen i Christo, och ljuger icke, Hedningarnas lärare i trone och sanningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Så vill jag nu, att männerna bedja i all rum, och upplyfta heliga händer, utan vrede och tvekan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Sammalunda ock, att qvinnorna pryda sig i höfveligom klädebonad, med blygaktighet och kyskhet; icke med flätadt hår, eller guld, eller perlor, eller kostelig klädnad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Utan, såsom de qvinnor höfves som gudaktighet bevisa, med goda gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'En qvinna låte lära sig i stillhet, med all underdånighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Men qvinnone städer jag icke, att hon andra lärer; och icke heller råder öfver mannen, utan vare i stillhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Ty Adam vardt först skapad, och sedan Eva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Och Adam vardt icke bedragen; utan qvinnan vardt bedragen, och kom öfverträdelsen åstad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Men hon varder likväl salig, genom barnsbörden, om hon blifver i trone, och kärlekenom, och i helgelse, med kyskhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Det är ju ett fast ord: Om någor begärar ett Biskopsämbete, han åstundar en god gerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Så skall nu en Biskop vara ostraffelig; ene hustrus man, vakande, nykter, sedig, gästgifvare, läraktig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Ingen drinkare, icke bitter, icke sniken efter slem vinning; utan mild, icke trätosam, icke girig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Den sitt hus väl förestår; den der lydig barn hafver, med alla ärlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Hvar nu någor icke kan förestå sitt eget hus, huru skall han förestå Guds församling?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Icke Nychristen; på det han icke skall uppblåsas, och falla i lastarens dom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Han måste ock hafva ett godt vittnesbörd af dem som utantill äro; på det han icke skall falla uti lastarens försmädelse och snaro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Sammalunda ock tjenarena, skola ärlige vara, icke tvetalige, icke drinkare, icke snikne efter slem vinning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Hållandes trones hemlighet med ett rent samvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Och de skola först försökas; och sedan skola de tjena, när ingen kan straffa dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Deras hustrur sammaledes, skola ock ärliga vara, icke förtalerskor; nyktra, trofasta i all ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Tjenarena skola vara ene hustrus män, de sin barn väl förestå, och sin egen hus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Ty de der väl tjena, förvärfva sig ett godt uppsteg, och mycken tröst i trone, som är i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Detta skrifver jag dig, förhoppandes ske skola att jag kommer snart till dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Och om så hände att jag förtöfvar, att du må veta huruledes du umgå skall uti Guds hus, som är lefvandes Guds församling, en pelare, och sanningenes grundval.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Och utan tvifvel är Gudaktighetenes hemlighet stor: Gud är uppenbar vorden i köttet, rättfärdigad i Andanom, synt Änglomen, predikad Hedningomen, trodd i verldene, upptagen i härligheten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Men Anden säger klarliga, att i yttersta tiderna skola somlige falla ifrå trone, hållande sig intill bedrägeliga andar och djeflalärdom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Genom dem som med skrymteri tala lögn, och hafva brändt tecken i sin samvet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Och förbjuda ägtenskap; bjuda skona maten, som Gud skapat hafver till att taga med tacksägelse, dem trognom, och dem som hafva förstått sanningena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Ty allt det Gud skapat hafver är godt, och intet bortkastandes, som med tacksägelse taget varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Ty det varder helgadt genom Guds ord och bönen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'När du sådant gifver bröderna före, så blifver du en god Jesu Christi tjenare; såsom du uppfödder äst i trones ordom, och god lärdom, med hvilken du alltid varit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Men oandeliga och kärlingafabler låt fara; men öfva dig sjelf till gudaktighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Ty lekamlig öfning är föga till nytto; men gudaktighet är nyttig till all ting, och hafver löfte om detta lifvet, och det tillkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Det är ju ett fast ord, och i alla måtto väl värdt att man det anammar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Ty derpå arbete vi ock, och vardom försmädde, att vi hoppas på lefvandes Gud, som är alla menniskors Frälsare, men besynnerliga deras som tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Sådant bjud, och lär.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Ingen förakte din ungdom; utan var dem trognom en eftersyn, i ord, i umgängelse, i kärlek, i andanom, i trone, i kyskhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Håll på att läsa, förmana, lära, tilldess jag kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Försumma icke den gåfvo som i dig är, den dig gifven är genom prophetien, med Presternas händers åläggning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Detta akta; blif deruti; på det din förbättring må hvarjom manne uppenbar varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Haf akt på dig sjelfvan, och på lärdomen; blif i dessa stycker; ty om du så gör, frälsar du dig sjelfvan, och dem som dig höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Den gamla skall du icke hårdeliga straffa; utan förmana såsom en fader; de unga såsom bröder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'De gamla qvinnor såsom mödrar; de unga såsom systrar, med all kyskhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Hedra enkorna, de der rätta enkor äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Om någon enka hafver barn, eller barnabarn, sådana skola först lära väl regera sitt eget hus, och göra såsom föräldrarna dem gjort hafva; ty det är väl gjordt, och Gudi tacknämligit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Men det är en rätt enka, som ensam är, den sitt hopp sätter till Gud, och blifver alltid i böner och åkallan, natt och dag;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Men den som lefver i vällust, hon är lefvandes död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Sådant bjud, att de äro ostraffeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Hvar nu någor sina, besynnerliga sitt husfolk, icke försörjer, den hafver försakat trona, och är argare än en Hedninge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Låt inga enko utväljas yngre än sextio år, den som hafver varit ens mans hustru;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Och vittnesbörd hafver om goda gerningar; om hon hafver uppfödt barn; om hon hafver herbergat; om hon hafver tvagit de heligas fötter; om hon hafver hulpit de bedröfvada; om hon i alla goda gerningar hafver idkelig varit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Men de unga enkor låt fara; ty när de begynna kättjas emot Christum, så vilja de gifta sig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Och hafva sin dom, att de den första tron brutit hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Dertillmed äro de fåfänga, och lära löpa omkring i husen; ja, icke allenast fåfänga, utan ock sqvallerfulla, och förvetna, och tala det som icke borde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Så vill jag nu; att de unga enkor gifta sig, föda barn, stå hus före, intet tillfälle gifva motståndarenom till att tala illa.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Ty några hafva allaredo vändt tillbaka efter Satanam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Hvar nu någor trogen man eller qvinna hafver enkor, han försörje dem, och låte icke församlingen förtungas, att det må dem tillräcka, som rätta enkor äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'De Prester, som väl förestå, skall man hålla vara dubbel heder värda; mest de, som arbeta i ordet och lärdomen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Ty Skriften säger: Du skall icke binda munnen till på oxan som tröskar; och: En arbetare är sin lön värd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Tillstäd ingen klagomål emot en Prest, utan med tu eller tre vittne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'De som synda, straffa för allom, att andre skola ock frukta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Jag betygar för Gudi, och Herranom Jesu Christo, och för de utkorada Änglar, att du håller detta, utan egen godtycko, och gör intet efter väld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Lägg icke hastigt händerna på någon, och gör dig icke heller delaktig i annars mans synder; håll dig sjelfvan kysk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Drick icke länger vatten, utan bruka något fögo vin, för din magas skull, och att du ofta sjuk äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Somliga menniskors synder äro uppenbara, att man dem tillförene döma kan; men somliga varda sedan uppenbara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Sammalunda äro ock somliga goda gerningar uppenbara; och de andra blifva ock intet fördolda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Trälarna, som under ok äro, skola hålla sina herrar alla äro värda; på det Guds Namn och lärdom icke skall försmädd varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Men de som hafva trogna herrar, de skola icke förakta dem, fördenskull de äro bröder; utan vara dess mer tjenstaktige, att de trogne, och älskade, och delaktige uti välgerningene äro. Sådant lär, och förmana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Ho der annars lärer, och icke blifver vid vårs Herras Jesu Christi helsosamma ord, och vid den lärdom som är om Gudaktigheten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Han är förmörkrad, och vet intet, utan är sjuk i spörsmål och ordaträtor, af hvilkom födes afund, kif, försmädelse, onda misstankar,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Onyttiga disputeringar emellan de menniskor, som i sitt sinne förderfvade äro, ifrå hvilka sanningen är borttagen, de der mena att gudaktigheten är en vinning. Drag dig ifrå sådana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Men vara gudelig, och låta sig nöja, är vinning nog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Ty vi hafve intet fört in i verldena; derföre är det klart, att vi icke heller kunne något föra härut;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Utan då vi hafve födo och kläder, så låtom oss dermed nöja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Men de som vilja rike varda, falla uti frestelse, och i snaro, och i mång dåraktig och skadelig begärelse, de der sänka menniskorna uti förderf och fördömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Ty girighet är en rot till allt ondt; till hvilka somlige hafva haft lust, och äro dermed ville farne ifrå trone, och hafva gjort sig sjelfva mycken bedröfvelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Men du, Guds menniska, fly sådant; far efter rättfärdigheten, Gudaktigheten, tron, kärleken, tålamod, saktmod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Kämpa en god trones kamp; fatta evinnerligit lif, till hvilket du ock kallad äst, och bekänt hafver en god bekännelse för mång vittne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Jag bjuder dig för Gudi, som all ting gör lefvande; och för Christo Jesu, som under Pontio Pilato betygat hafver en god bekännelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Att du håller budet obesmittadt, ostraffelig, intill vårs Herras Jesu Christi uppenbarelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Hvilka oss bete skall i sin tid den salige och allena väldige Konungen öfver alla Konungar, och Herren öfver alla herrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Den der allena hafver odödelighet; den der bor uti ett ljus der ingen tillkomma kan; den ingen menniska sett hafver, icke heller se kan; honom vare ära och evigt rike. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Bjud dem som rike äro i denna verld, att de icke äro storsinte, icke heller sätta sitt hopp på de ovissa rikedomar; utan på lefvande Gud, hvilken oss all ting rikeliga gifver till att nyttja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Att de göra väl, och rike varda på goda gerningar, gerna gifva, äro oförtrutne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Sammansamka sig sjelfvom en god grund framdeles, att de måga fatta evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'O Timothee, förvara det dig betrodt är; och fly oandelig och onyttig ord och trätor, som gå af falskeliga berömd konst;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Hvilka somlige föregifva, och fara ville om trona. Nåd vare med dig. Amen. Sänd af Laodicea, hvilken är hufvudstaden i Phrygia Pacatiana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulus, Jesu Christi Apostel, genom Guds vilja, till att predika lifsens löfte, i Christo Jesu;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Minom kära son Timotheo: Nåd, barmhertighet, frid af Gud Fader, och Christo Jesu vårom Herra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Jag tackar Gudi, den jag tjenar ifrå mina föräldrar, uti ett rent samvet, att jag utan upphåll hafver din åminnelse i mina böner, natt och dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Och mig längtar efter att se dig, när jag tänker på dina tårar; på det jag med glädje måtte uppfylld varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Och jag drager mig till minnes den oskrymtade tro, som i dig är, den tillförene bodde uti dine fadermoder Loide, och i dine moder Evnica; är jag viss att sammalunda ock i dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'För hvilka saks skull jag förmanar dig, att du uppväcker Guds gåfvo, som i dig är, genom mina händers påläggning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Ty Gud hafver icke gifvit oss räddhågans anda, utan kraftenes, och kärlekens, och tuktighetenes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Derföre skäm dig icke vid vårs Herras vittnesbörd; icke heller vid mig, som är hans fånge; utan var delaktig uti Evangelii bedröfvelse, efter Guds kraft;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Den oss frälsat hafver, och kallat med en helig kallelse; icke efter våra gerningar, utan efter sitt uppsåt, och nåd, den oss gifven är i Christo Jesu, för evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Men nu är hon uppenbar vorden genom vår Frälsares Jesu Christi uppenbarelse, den der döden borttagit hafver, och lifvet och ett oförgängeligit väsende framburit i ljuset, genom Evangelium;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Uti hvilket jag är satter till en predikare, och Apostel, och Hedningarnas lärare;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'För hvilka saks skull jag ock detta lider; och skämmes dock intet; ty jag vet på hvem jag tror, och är viss att han förmår förvara mitt betrodda gods intill den dagen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Håll dig efter de helsosamma ords eftersyn, som du hört hafver af mig, om trona och kärleken i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Detta goda betrodda godset bevara genom den Helga Anda, den uti oss bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Du vetst att alle de, som i Asien äro, hafva vändt sig ifrå mig; ibland hvilka är Phygellus, och Hermogenes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Herren gifve Onesiphori huse barmhertighet; ty han hafver ofta vederqvickt mig, och skämdes icke vid mina kedjo;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Utan, då han var i Rom, sökte han fliteliga efter mig, och fann mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Gifve honom Herren, att han finner barmhertighet när Herranom på den dagen; och i huru mång stycke han mig till tjenst var i Epheso, vetst du bäst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Så stärk dig nu, min son, genom nådena, som är i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Och hvad du af mig hört hafver, genom mång vittne, det befalla trogna menniskor, som ock dugelige äro att lära andra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Lid och umgäll, såsom en god Jesu Christi stridsman.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Ingen stridsman befattar sig med näringshandel; på det han skall täckas honom, som honom till en stridsman upptagit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Hvar ock nu någor kämpar, han krönes icke, utan han redeliga kämpar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Åkermannen, som åkren brukar, honom bör först få af fruktene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Märk hvad jag säger; men Herren skall gifva dig i all ting förstånd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Tänk på Jesum Christum, som är uppstånden ifrå de döda, af Davids säd, efter mitt Evangelium;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Uti hvilket jag bedröfvelse lider, intill bojor, såsom en ogerningsman; men Guds ord är icke bundet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Derföre lider jag det allt, för de utkoradas skull, att de skola ock få salighet i Christo Jesu, med eviga härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Det är ju ett fast ord: Dö vi med, så skole vi lefva med;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Lide vi, så skole vi med regnera; om vi försake honom, så försakar ock han oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Tro vi honom icke, så blifver han dock trofast; han kan icke neka sig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Sådant förmana, och betyga för Herranom, att de icke träta om ord till ingen nytto, utan till att afvända dem som på höra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Vinnlägg dig att bevisa dig Gudi en bepröfvad och ostraffelig arbetare, som rätt delar sanningenes ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Men oandelig och onyttig ord kasta bort; ty det hjelper mycket till ogudaktighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Och deras tal fräter omkring sig, såsom kräfvetan; ibland hvilka är Hymeneus och Philetus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'De der om sanningen felat hafva, sägande uppståndelsen redan skedd vara; och hafva förvändt somliga menniskors tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Men den faste Guds grund blifver ståndandes, och hafver detta insegel: Herren känner sina; och hvar och en som åkallar Christi Namn, gånge ifrå orättfärdighetene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Men uti ett stort hus äro icke allenast gyldene och silffat, utan jemväl träfat och lerfat; och somlig till heder, och somlig till vanheder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Hvar nu någor renar sig ifrå sådant folk, han varder ett helgadt fat till heder, husherranom brukeligit, beredt till allt godt verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Fly ungdomsens lustar; men far efter rättfärdigheten, tron, kärleken, frid med allom dem, som af rent hjerta åkalla Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Men förkasta dåraktig och öfverdådig spörsmål, vetandes att de föda träto af sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Men Herrans tjenare skall icke vara trätosam, utan ljuflig vid hvar man, läraktig, den de onda lida kan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Och med saktmodighet straffa dem som emotstå; om Gud en gång vill gifva dem bättring, till att förstå sanningen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Och besinna sig ifrå djefvulens snaro, af hvilkom de fångne äro efter hans vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Men detta skall du veta, att uti yttersta dagarna tillstunda farliga tider.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Ty der varda kommande menniskor, som älska sig sjelfva; girige, stortalige, högfärdige, försmädare, föräldromen olydige, otacksamme, ogudaktige,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Okärlige, hårdnackade, skändare, okyske, omilde, hatande det goda,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Förrädare, öfverdådige, uppblåste, de der mer älska vällust än Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Hafvandes ett sken till Gudaktighet; men dess kraft försaka de. Och fly sådana.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Af dem äro de som löpa utu det ena huset i det andra, och föra qvinnfolk fångna, som med synder betungade äro, och drifvas af mångahanda lustar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Alltid läras de, och kunna dock aldrig komma till sanningens kunskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Men såsom Jannes och Jambres stodo emot Mose, så stå ock desse emot sanningene; det äro menniskor, förderfvade i sitt sinne, odugelige till trona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Men de skola icke länger hafva framgång; ty deras galenskap varder allom uppenbar, såsom ock de förras var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Men du hafver förnummit min lärdom, mitt sätt, mitt uppsåt, mina tro, min långmodighet, min kärlek, mitt tålamod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Mina förföljelser, mina bedröfvelser, som mig öfvergingo i Antiochien, Iconio, Lystris; hurudana förföljelser jag der led; och af allt hafver Herren förlossat mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Och alle, de der gudeliga vilja lefva i Christo Jesu, måste lida förföljelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Men med onda menniskor och bedragare varder det ju länger ju argare; de förföra, och varda förförde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Men du, blif vid det du lärt hafver, och det dig betrodt är, vetandes af hvem du det lärt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Och efter du af barndom hafver kunnat den Helga Skrift, kan hon dig undervisa till salighet, genom trona på Christum Jesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Ty all skrift af Gudi utgifven är nyttig till lärdom, till straff, till bättring, till tuktan i rättfärdighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Att en Guds menniska skall vara fullbordad, till alla goda gerningar skickelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Så betygar jag nu för Gudi, och Herranom Jesu Christo, den der döma skall lefvande och döda, i sin tillkommelse, och i sitt rike;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Predika ordet; håll uppå i tid och i otid; straffa, truga, förmana, med all saktmodighet och lärdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Ty den tid skall komma, att de icke skola kunna lida helsosam lärdom; utan skola, efter sina egna lustar, samla sig lärare; efter dem kliar i öronen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'Och skola vända sin öron ifrå sanningen, och vända sig till fabler.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Men du, var vaken i all ting, lid och umgäll; gör ens Evangelisk Predikares verk; uträtta ditt ämbete redeliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Ty jag offras nu, och tiden tillstundar att jag skall skiljas hädan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Jag hafver kämpat en god kamp, jag hafver fullbordat loppet; jag hafver hållit trona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Härefter är mig förvarad rättfärdighetenes krona, hvilka Herren mig gifva skall på den dagen, den rättfärdige domaren; men icke mig allenast, utan ock allom dem, som älska hans uppenbarelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Vinnlägg dig, att du kommer snarliga till mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Ty Demas hafver öfvergifvit mig, och fått kärlek till denna verldena; och är faren till Thessalonica; Crescens till Galatien; Titus till Dalmatien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lucas är allena med mig. Tag Marcum till dig, och haf honom med dig; ty han är mig mycket nyttig till tjenst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tychicum hafver jag sändt till Ephesum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Den mantel, som jag tillbakalät i Troade när Carpus, haf med dig, då du kommer, och böckerna, och enkannerliga de pergamenten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexander, kopparsmeden, hafver mig mycket ondt bevist. Herren betale honom efter hans gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Tag ock du dig vara för honom; ty han hafver svårliga ståndit emot vår ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Uti min första försvarelse stod ingen när mig, utan alle öfvergåfvo mig; det varde dem icke tillräknadt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Men Herren stod med mig, och styrkte mig; på det genom mig skulle predikanen stadfäst varda, och alle Hedningar höra skulle; och jag är friad af lejonens mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Men Herren skall förlossa mig af all ond gerning, och frälsa mig till sitt himmelska rike; hvilkom vare ära ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Helsa Priscam, och Aqvilam, och Onesiphori husfolk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus blef i Corintho; men Trophimum lät jag qvar i Mileto sjuk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Vinnlägg dig, att du kommer för vintren. Dig helsar Eubulus, och Pudens, och Linus, och Claudia, och alle bröderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Herren Jesus Christus vare med din anda. Nåd vare med eder. Amen. Den andra Epistelen till Timotheum, skrifven af Rom, då Paulus åter hades fram för Kejsar Neronem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulus, Guds tjenare, men Jesu Christi Apostel, till att predika Guds utvaldom trona och sanningenes kunskap, hvilken till Gudaktighet förer,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'I hoppet till evinnerligit lif, det Gud, som icke ljuga kan, för evigt utlofvat hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Men i sinom tid hafver han uppenbarat sitt ord genom predikan, den mig betrodd är, efter Guds vår Frälsares befallning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Minom rättsinniga son Tito, efter begges våra tro: Nåd, barmhertighet, frid af Gud Fader, och Herranom Jesu Christo, vårom Frälsare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Fördenskull lät jag dig qvar i Creta, att hvad som ännu fattades, skulle du fullkomliga beställa, och besätta städerna här och der med Prester, såsom jag dig befallt hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Den som är ostraffelig, ene hustrus man; den der trogen barn hafver, oberyktad för öfverflödighet och genstörtighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Ty en Biskop bör vara ostraffelig, såsom en Guds skaffare; icke ensinnig, icke sticken, ingen drinkare, icke bitter, icke sniken efter slem vinning;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Utan gästgifvare, och älskar det godt är; tuktig, rättvis, helig, kysk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Och håller sig vid det ord, som visst är och lära kan; på det han må mägtig vara att förmana genom helsosam lärdom, och öfvervinna dem som deremot säga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Ty månge äro genstörtige, onyttige sqvallrare, och bedragare, besynnerliga de af omskärelsen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Hvilkom man måste tillstoppa munnen; de som hela husen förvända, och lära det intet doger, för slem vinnings skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'En af dem hafver sagt, deras egen Prophet: De Creter äro alltid ljugare, ond djur, och late bukar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Detta vittnesbörd är sant. Derföre straffa dem skarpeliga, att de äro rätte i trone;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Och icke akta på de Judiska fabler och menniskors bud, som sig draga ifrå sanningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Dem, som rene äro, äro all ting rene; men dem orenom och otrognom är intet rent; utan både deras sinne och samvet är orent.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'De säga sig känna Gud; men med gerningarna neka de det; efter de äro styggelige för Gud, och olydige, och till alla goda gerningar odugelige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Men tala du, såsom tillbörligit är, efter en helsosam lärdom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'De gamla, att de äro nyktre, ärlige, tuktige, rätte i trone, i kärlekenom, i tålamod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'De gamla qvinnor desslikes, att de ställa sig såsom heligom höfves, icke förtalerskor, icke drinkerskor, goda lärerskor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Att de unga qvinnor lära tukt af dem; älska sina män, hafva sin barn kär;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'Vara sediga, kyska, husaktiga, fromma, sina män underdåniga; på det Guds ord icke skall försmädt varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Sammalunda förmana ock de unga män, att de äro tuktige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Uti all ting ställ dig sjelf för en eftersyn till goda gerningar, med oförfalskad lärdom, med ärlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Med helsosam och ostraffelig ord; på det han, som emotstår, må blygas, intet ondt hafvandes det han om oss säga kan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Tjenarena, att de äro sinom herrom underdånige, och uti all ting behagelige, icke gensvarige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Icke otrogne; utan alla goda trohet bevisande; på det de måga pryda Guds vår Frälsares lärdom i all stycke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Ty Guds nåd, helsosam allom menniskom, är uppenbarad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Och lärer oss, att vi skole försaka alla ogudaktighet och verldslig lusta, och lefva tukteliga, rättfärdeliga, och gudeliga i denna verlden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Och vänta det saliga hoppet, och den stora Guds och vår Frälsares Jesu Christi härliga uppenbarelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Den sig sjelf gaf för oss; på det han skulle förlossa oss ifrån all orättfärdighet, och rena oss sig sjelfvom ett folk till egendom, det sig om goda gerningar beflitar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Sådant tala, och förmana, och straffa med fullt allvar. Låt ingen förakta dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Förmana dem, att de äro Förstarna och Öfverheten underdånige och lydige; redebogne till alla goda gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Om ingen illa tala, icke trätosamma; utan milde, bevisande all saktmodighet till alla menniskor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Ty vi vorom ock fordom ovise, ohörige, villfarande, tjenande begärelsom och mångahanda lustom, och vandradom i ondsko och afund, hätske; och hatadom hvarannan inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Men sedan Guds, vår Frälsares, godhet och kärlek till menniskorna uppenbarades;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Icke för rättfärdighetenes gernings skull, som vi gjort hade; utan efter sina barmhertighet gjorde han oss saliga, genom den nya födelsens bad, och den Heliga Andas förnyelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Hvilken han öfver oss rikeliga utgjutit hafver, genom vår Frälsare Jesum Christum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'På det vi skole rättfärdige varda genom hans nåd, och arfvingar blifva till evinnerligit lif, efter hoppet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Det är ju ett fast ord; detta vill jag att du lärer, såsom det der visst är, att de, som Gudi trott hafva, vinnlägga sig i goda gerningar föregå; ty sådant är menniskomen godt och nyttigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Men dåraktig spörsmål, och slägtregister, och trätor, och kämpning om lagen förkasta; ty de äro onyttig och fåfäng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Fly en kättersk mennisko, då han en gång och annan förmanad är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Vetandes, att en sådan är förvänd, och syndar, såsom den sig sjelf fördömt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Då jag till dig sänder Artheman, eller Tychicum, så skynda dig snart till mig till Nicopolis; ty jag hafver satt mig före att blifva der öfver vintren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenan, den lagkloka, och Apollo, fordra med flit, att dem intet fattas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Men låt ock dem, som våre äro, lära i goda gerningar föregå der det behöfves, att de icke äro ofruktsamme.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Helsa dig alla, som med mig äro. Helsa dem, som oss älska i trone. Nåd vare med eder allom. Amen. Skrifven af Nicopolis, i Macedonien.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paulus, Christi Jesu fånge, och Timotheus, brodren, dem älskeliga, och vårom hjelpare Philemon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Och de älskeliga Apphie, och Archippo, vår medstridare, och den församling som i ditt hus är:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Nåd vare med eder, och frid af Gudi vårom Fader, och Herranom Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Jag tackar min Gud, och hafver din åminnelse alltid i mina böner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Efter jag hörer af din kärlek, och den tro som du hafver till Herran Jesum, och emot all helgon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Att din tro, som vi hafve med hvarannan, må kraftig varda, genom kunskapen på allt godt, som I hafven i Christo Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Ty vi hafve stor glädje och hugnad af din kärlek; att helgonen äro hjerteliga vederqvickte af dig, käre broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Derföre, ändock jag hafver i Christo en stor tröst, till att bjuda dig det du bör göra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Dock likväl, för kärlekens skull, beder jag heldre, jag som en sådana är, nämliga den gamle Paulus, och ännu derutöfver en Jesu Christi fånge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Så förmanar jag dig, för min son Onesimo, den jag födde i minom bandom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Den dig fordom onyttig var, men nu både dig och mig väl nyttig är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Hvilken jag nu igensändt hafver; men anamma du honom, såsom mitt hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Jag hade velat behålla honom när mig, att han skulle tjent mig i din stad, uti Evangelii bandom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Men jag ville intet göra utan ditt samtycke; på det ditt goda icke skulle vara nödgadt, utan sjelfviljogt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Men derföre tilläfventyrs for han sin väg till en tid, att du skulle få honom evigan igen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Icke nu såsom en tjenare, utan mer än en tjenare; ja, såsom en älskelig broder, besynnerliga mig; huru mycket mer dig, både efter köttet, och efter Herran?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Hvar du nu håller mig för din medbroder, så anamma honom lika som mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Om han dig någon skada gjort hafver, eller något skyldig är, det räkna mig till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Jag Paulus hafver detta skrifvit med mine hand, jag vill betalat; att jag icke skall säga, att du dig sjelfvan mig pligtig äst.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Ja, käre broder, städ till att jag hafver lust af dig i Herranom; vederqvick mitt hjerta i Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Jag hafver skrifvit dig till, förtröstandes på dina lydaktighet; vetandes att du gör väl mer, än jag säger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Dermed bered mig herberge; ty jag hoppas att jag, med edra böners hjelp, eder gifven varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Helsa dig Epaphras, min medfånge i Christo Jesu;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marcus, Aristarchus, Demas, Lucas, mine hjelpare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Vårs Herras Jesu Christi nåd vare med edar anda. Amen. Sänd af Rom, med Onesimo, tjenaren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Fordom talade Gud ofta, och i mångahanda måtto, till fäderna, genom Propheterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'På det yttersta i dessa dagar hafver han talat till oss genom Sonen; hvilken han satt hafver till arfvinga öfver all ting; genom hvilken han ock verldena gjort hafver;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Hvilken, efter han är hans härlighets sken, och hans väsendes rätta beläte, och bär all ting med sitt kraftiga ord, och hafver rensat våra synder genom sig sjelf, sitter han på majestätsens högra sido i höjdene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Så mycket bättre vorden än Änglarne, som han för dem högre Namn ärft hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Ty till hvilken af Änglarna hafver han någon tid sagt: Du äst min Son, i dag hafver jag födt dig? Och åter: Jag skall vara hans Fader, och han skall vara min Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Och åter, då han införer den förstfödda i verldena, säger han: Och alle Guds Änglar skola tillbedja honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Men om Änglarna säger han: Han gör sina Änglar andar, och sina tjenare eldslåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Men till Sonen: Gud, din stol varar ifrån evighet till evighet; dins rikes spira är en rättvis spira.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Du hafver älskat rättfärdighetena, och hatat orättfärdighetena; derföre hafver Gud, din Gud smort dig med glädjens oljo, mer än dina medbröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Och du, Herre, grundade jordena af begynnelsen, och himlarna äro dina händers verk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'De skola förgås; men du skall blifva, och de skola alle föråldras såsom ett kläde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Och såsom en klädnad skall du förvandla dem, och de varda förvandlade; men du blifver densamme, och din år hafva ingen ända.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Men till hvilken af Änglarna hafver han någon tid sagt: Sätt dig på mina högra hand, tilldess jag lägger dina fiendar dig till en fotapall?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Äro de icke allesammans tjensteandar, utsände till tjenst för deras skull, som salighetena ärfva skola?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Derföre skole vi dess bätter taga vara på det oss sagdt är, att vi tilläfventyrs icke förderfves.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Ty vardt det ordet fast, som genom Änglarna taladt var; och all öfverträdelse och olydighet hafver fått sin rätta lön;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Huru skole vi undfly, om vi sådana salighet icke akte? hvilken, sedan hon först predikad vardt af Herranom, är kommen in på oss, af dem som det hört hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Och Gud hafver gifvit vittnesbörd dertill med tecken, under, och mångahanda krafter och med den Helga Andas utskiftelse, efter hans vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Ty han hafver icke undergifvit Änglomen den tillkommande verldena, der vi om tale.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Men en betygar enstäds, och säger: Hvad är menniskan, att du tänker på honom; eller menniskones Son, att du söker honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Du hafver en liten tid låtit honom öfvergifven vara af Änglarna; med äro och pris hafver du krönt honom, och satt honom öfver dina händers verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'All ting hafver du lagt under hans fötter. I det han nu all ting hafver honom underlagt, hafver han intet undantagit, det honom icke underlagdt är. Dock se vi icke ännu all ting vara honom underlagd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Men Jesum, som en liten tid hafver öfvergifven varit af Änglarna, se vi, för dödsens lidandes skull, krönt vara med äro och pris; på det han af Guds nåd skulle smaka döden för alla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Ty det höfde honom, för hvilkens skull all ting äro, och genom hvilken all ting äro, den der mång barn till härlighet fört hade, att han deras salighets höfdinga skulle, genom lidande, fullkommen göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Efter den som helgar, och de som helgade varda, äro alle af enom; derföre skämmes han ock icke kalla dem bröder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Sägandes: Jag vill förkunna ditt Namn minom brödrom, och midt i församlingen prisa dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Och åter: Jag vill sätta min tröst till honom; och åter: Si, jag och barnen, som Gud mig gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Efter barnen hafva kött och blod, är ock han dess delaktig vorden; på det han skulle genom döden nederlägga honom, som döden i våld hade, det är djefvulen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Och göra dem fri, som i allt sitt lefverne, genom dödsens räddhåga, måste trälar vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Ty han tager ingenstäds på sig Änglarna; utan Abrahams säd tager han på sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Derföre måste han i all stycke vara bröderna lik; på det han skulle vara barmhertig, och en trogen öfverste Prest för Gudi, att försona folkens synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Ty deraf att han vardt pint och frestad, kan han hjelpa dem som frestas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Derföre, I helige bröder, som delaktige ären uti den himmelska kallelsen, akter på Apostelen, och öfversta Presten, den vi bekännom, Christum Jesum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Hvilken trogen är honom, som honom gjort hafver, såsom ock Moses, i allt hans hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Så mycket större äro värd än Moses, som han hafver större äro, som huset byggde, än sjelfva huset.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Ty hvart och ett hus bygges af någon; men Gud är den, som all ting gjort hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Och Moses var trogen i allt hans hus, såsom en tjenare, de ting till vittnesbörd, som framdeles yppas skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Men Christus, såsom en Son, i sitt hus; hvilket hus vi ärom, om vi annars förtröstningen, och hoppsens berömmelse, intill ändan fast behålle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Derföre, såsom den Helge Ande säger: I dag, om I fån höra hans röst,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Så förhärder icke edor hjerta; såsom skedde i vredene på frestelsedagen, i öknene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Då edre fäder frestade mig; de bepröfvade, och sågo min verk, i fyratio år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Derföre vardt jag vred på detta slägtet, och sade: Alltid fara de ville med hjertat; men de visste icke mina vägar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Så att jag ock svor i mine vrede: De skola icke komma uti mina rolighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Ser till, käre bröder, att tilläfventyrs uti någon edra icke är ett argt och otroget hjerta, som träder ifrå lefvandes Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Utan förmaner eder sjelfva alla dagar, så länge det nämnes: I dag; att ingen ibland eder blifver förhärd, genom syndenes bedragelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Ty vi äre delaktige vordne af Christo; om vi annars trona, som vi begynt hafve, fast behålle intill ändan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Emedan det sägs: I dag, om I fån höra hans röst, så förhärder icke edor hjerta, såsom skedde i vredene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Ty somlige, som henne hörde, förtörnade honom; men icke alle, som farne voro utaf Egypten, genom Mosen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Men hvilkom var han vred i fyratio år? Var han icke dem som syndat hade, hvilkas kroppar förföllo i öknene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Men hvilkom svor han då, att de icke skulle komma in i hans rolighet, utan dem otrognom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Och vi sem, att de icke kunde ingå, för otrones skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Så låt oss nu frukta, att vi icke försumme det löfte, som är, att vi skole ingå i hans rolighet; och att ibland oss icke någor tillbakablifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Ty det är ock oss förkunnadt, så väl som dem; men det halp dem intet att de hörde ordet; efter de, som hörde, satte der icke tro till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Ty vi, som trom, ingåm i rolighetena, som han sade: Såsom jag svor i mine vrede, de skola icke ingå i mina rolighet; der dock de verk fullbordad voro af verldenes begynnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Ty han sade enstäds om den sjunde dagen alltså: Och Gud hvilade på sjunde dagen af all sin verk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Och åter nu här: De skola icke ingå i min rolighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Efter det är ännu för handene, att somlige skola der ingå, och de, som det i förstone bebådadt vardt, äro icke komne dertill, för otrons skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Lägger han åter en dag före, efter så lång tid, och säger genom David: I dag, såsom sagdt är, i dag, om I hören hans röst, så förhärder icke edor hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Ty om Josue hade kommit dem till rolighet, hade han ingalunda om en annan dag sedan sagt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Derföre står Guds folke en rolighet tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Ty den som ingången är uti hans rolighet, han hafver ock fått hvilo af sin verk, såsom Gud af sin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Så vinnläggom oss nu, att vi mågom inkomma uti denna roligheten, på det icke någor skall falla uti samma otros efterdömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Ty Guds ord är lefvandes och kraftigt, och skarpare än något tveeggadt svärd: och går igenom, tilldess det åtskiljer själ och anda, och märg och ben; och är en domare öfver tankar och hjertans uppsåt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Och för honom är intet kreatur osynligit; utan all ting äro blott och uppenbar för hans ögon; om honom tale vi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Efter vi nu hafve en stor öfversta Prest, Jesum, Guds Son, som i himmelen faren är, så låt oss hålla bekännelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Ty vi hafve icke en öfversta Prest, som icke kan varkunna sig öfver vår svaghet; utan den som frestad är i all ting, lika som vi, dock utan synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Derföre låt oss trösteliga framgå till Nådastolen; att vi måge få barmhertighet, och finna nåd, på den tid oss hjelp behöfves.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Förty hvar och en öfverste Prest, den af menniskom uttags, han varder satt för menniskorna, i de ting som Gudi på röra, att han skall offra gåfvor och offer för synderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Den der kan varkunna sig öfver dem, som fåkunnige äro och ville fara; efter han är ock sjelf belagd med svaghet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Derföre måste han ock, såsom för folket, så ock för sig sjelf offra, för synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Och ingen tager sig sjelf äro; utan den som ock kallad varder af Gudi, lika som Aaron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Så hafver ock icke Christus gjort sig sjelf härligan, att han skulle varda öfverste Prest; utan den, som sade till honom: Du äst min Son, i dag hafver jag födt dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Såsom han ock annorstäds säger: Du äst en Prest i evig tid, efter Melchisedeks sätt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Och hafver på sins kötts dagar offrat bön och åkallan, med starkt rop och tårar till honom, som honom frälsa kunde ifrå döden; och vardt bönhörd, derföre att han höll Gud i vördning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Och ändå han var Guds Son, hafver han dock af thy han led lärt lydno.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Och då han fullkommen vardt, blef han allom dem, som honom lyda, en orsak till evig salighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Kallad af Gudi en öfverste Prest, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Derom vi hade väl mycket tala; men det är svårt, efter I ären så oförståndige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Och I, som längesedan skulle varit lärare, behöfven åter att man lärer eder de första bokstäfverna af Guds ord; och att man gifver eder mjölk, och icke stadig mat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Ty hvem man ännu mjölk gifva måste, han är oförfaren i rättfärdighetenes ord; ty han är ett barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Men dem, som fullkomne äro, tillhörer stadig mat, de som genom vanan öfvade äro i sinnen, till att åtskilja godt och ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Derföre vilje vi låta bestå den lärdom, som lyder på begynnelsen till ett Christeligit lefverne, och taga det före som till fullkomligheten drager; icke på nytt läggande grunden till bättring af döda gerningar, till trona på Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Till döpelsen, till lärdom, till händers påläggning, till de dödas uppståndelse, och till den eviga domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Och det vilje vi göra, om Gud annars det tillstäder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Ty det är omöjeligit att de, som en gång upplyste äro, och smakat hafva den himmelska gåfvan, och delaktige vordne äro af den Helga Anda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Och smakat hafva det goda Guds ord, och den tillkommande verldenes kraft;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Om de affalla, och på nytt sig sjelfvom korsfästa Guds Son, och för spott hålla; att de skola igen förnyas till bättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Ty jorden, som indricker regnet, som ofta kommer på henne, och bär dem beqväma örter som henne bruka, hon får välsignelse af Gudi;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Men den törn och tistel bär, hon är odugelig, och närmast förbannelsen; hvilkens ändalykt är, att hon skall brännas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Men vi förse oss, I älskelige, till eder det bättre är, och det salighetene närmer är; ändock vi så talom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Ty Gud är icke orättvis, att han förgäter edra gerning och arbete i kärlekenom, som I bevisat hafven på hans Namn, då I tjenten helgonen, och ännu tjenen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Men vi begäre, att hvar och en af eder den samma flit bevisar, till att hålla hoppet fast allt intill ändan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Att I icke tröge blifven, utan deras efterföljare, som genom trona och långmodighet få det arf, som utlofvadt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Ty när Gud lofvade Abrahe, då han ingen större hade der han vid svärja kunde, svor han vid sig sjelf,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Och sade: Sannerliga, jag vill välsigna dig, och föröka dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Och så, efter han i tålamod förbidde, fick han det som utlofvadt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Ty menniskorna svärja vid den der större är än de, och dem emellan blifver en ände på alla trätor, om det stadfäst blifver med en ed.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Men då Gud ville rikeliga bevisa arfvingomen till löftet sins uppsåts fasthet, lade han der en ed uppå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Att vi genom tu ovikelig ting, i hvilkom omöjeligit är att Gud ljuga skulle, ena starka tröst hafva skullom, vi som dertill flytt hafve, att vi måtte få det hopp som tillbudet är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Hvilket vi hålle, såsom ett säkert och fast vår själs ankare; det ock ingår intill det som innanför förlåten är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Dit Förelöparen för oss ingången är, Jesus, en öfverste Prest vorden till evig tid, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Denne Melchisedek var Konung i Salem, högsta Guds Prest; den Abrahe mötte, då han igenkom ifrå den Konungaslagtning, och välsignade honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Hvilkom ock Abraham gaf tionde af all ting. Först uttolkas han, rättvisones Konung; men sedan är han ock Salems Konung, det är fredsens Konung;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Utan fader, utan moder, utan slägt; och hafver hvarken begynnelse på dagarna, eller ända på lifvet; men han är lik vorden vid Guds Son, och blifver Prest i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Men ser, huru stor den är, som ock Abraham Patriarchen gaf tionde af bytet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Men Levi söner, då de Presterskapet anamma, hafva befallning taga tiond af folket, det är, af sina bröder, efter lagen; ändå de ock af Abrahams länder komne äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Men den, hvilkens slägte icke räknas ibland dem, han tog tiond af Abraham, och välsignade honom som löftet hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Nu nekar det ingen, att det som mindre är, tager välsignelse af det som större är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Och här taga de menniskor tiond, som dödelige äro; men der han, som betygas om, att han lefver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Och, om jag så säga skall: Levi, som tiondena plägar taga, vardt ock tiondad i Abraham;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Ty han var ändå i sins faders länder, då Melchisedek honom mötte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Är nu fullkomlighet skedd genom det Levitiska Presterskapet, ty derunder fick folket lagen; hvad behöfde sägas, att en annar Prest uppkomma skulle, efter Melchisedeks sätt, och icke efter Aarons sätt?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Ty der Presterskapet förvandladt varder, der måste ock lagen förvandlas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Ty den som detta sägs om, är af ett annat slägte, af hvilko aldrig någor skötte altaret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Ty det är ju uppenbart, att vår Herre är kommen af Juda slägte; till hvilkens slägte Moses intet talat hafver om Presterskapet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Och är det ännu klarare, medan en annar Prest efter Melchisedeks sätt uppkommer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Hvilken icke är gjord efter köttslig budords lag, utan efter oändelig lifs kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Ty han betygar: Du äst en Prest evinnerliga, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Ty dermed sker, att den förra lag afkommer, för hennes svaghet och onyttos skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Ty lagen kunde intet göra fullkomligit; och varder ett bättre hopp infördt, genom hvilket vi nalkoms Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Och så mycket mer, att det icke skedde utan ed; ty de förre äro utan ed Prester vordne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Men denne med ed, genom den som sade till honom: Herren svor, och det skall icke ångra honom: Du äst en Prest evinnerliga, efter Melchisedeks sätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Så mycket bättre Testament hafver Jesus uträttat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Och de förre äro månge Prester vordne; derföre att döden lät dem icke blifva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Men denne, efter han blifver evinnerliga, hafver ett oförgängeligit Presterskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Hvarföre han ock kan evinnerliga saliga göra dem, som genom honom komma till Gud, och lefver alltid, och beder alltid för dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Ty en sådana öfversta Prest höfdes oss hafva, den der helig vore, oskyldig, obesmittad, skild ifrå syndare, och högre än himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Hvilken icke dageliga behöfde, såsom de andre öfverste Prester, först för sina egna synder offra, och sedan för folkens synder; ty han gjorde det ena reso, då han sig sjelf offrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Ty lagen sätter menniskor till öfversta Prester, som svaghet hafva; men edsens ord, som efter lagen sagdt är, det sätter Sonen evig och fullkomlig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Men summan af det vi tale är detta; Vi hafvom en sådan öfversta Prest, som sitter på högra handen på majestätsens stol i himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Och är en skaffare öfver de heliga håfvor, och öfver det sannskyldiga tabernaklet, hvilket Gud upprest hafver, och ingen menniska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Ty hvar och en öfverste Prest varder skickad till att offra gåfvor och offer; derföre är det af nöden, att denne ock något hafver, det han offra skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Hvar han nu vore på jordene, så vore han icke Prest; der Prester äro, de der efter lagen offra gåfvor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Hvilke tjena eftersynene, och skugganom till de himmelska ting; såsom Mose af Gudi svaradt vardt, då han skulle fullkomna tabernaklet: Se till, sade han, att du gör allt efter den eftersyn, som dig vist är på berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Men nu hafver han fått ett bättre ämbete, såsom han ens bättre Testaments Medlare är; det ock på bättre löfte satt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Ty om det första hade varit ostraffeligit, hade ingalunda vordit sökt rum till ett annat.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Ty han straffar dem, och säger: Si, de dagar skola komma, säger Herren, att jag skall fullkomna öfver Israels hus, och Juda hus, ett nytt Testament;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Icke efter det Testamentet, som jag deras fäder gjorde, på den dag då jag tog dem vid deras hand, att utföra dem af Egypti land; efter de blefvo icke ståndande i mitt Testament, så hafver jag ock gifvit dem utu mitt sinne, säger Herren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Ty detta är det Testament, som jag vill göra Israels huse, efter dessa dagar, säger Herren: Jag vill gifva min lag uti deras sinne, och uti deras hjerta vill jag skrifva dem; och jag vill vara deras Gud, och de skola vara mitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Och skall ingen lära sin nästa, eller sin broder, och säga: Känn Herran; ty de skola alle känna mig, ifrå den minsta ibland dem, och till den största.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Ty jag varder förblidkad öfver deras orättfärdigheter, och deras synder, och deras ondsko skall jag icke mer ihågkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'I det han säger: Ett nytt, föråldrade han det första; det nu åldrigt och gammalt är, det är hardt vid ändan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Hade ock väl det första sina rätter, och Gudstjenst, och utvärtes helighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Ty det främre tabernaklet var der uppsatt; uti hvilko voro ljusastakarne, och bordet, och skådobröden; och detta kallades det Helga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Men bak den andra förlåten var det tabernaklet, som man kallade det Aldrahelgasta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Hvilket hade det gyldene rökelsekaret, och Testamentsens ark, på alla sidor beslagen med guld; uti hvilko var det gyldene ämbar, der det himmelsbrödet uti var, och Aarons staf, som blomstrats hade, och Testamentsens taflor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Men der ofvanuppå voro härlighetenes Cherubim, som öfverskyggde Nådastolen; af hvilka stycker på denna tid icke besynnerliga är sägandes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Då nu detta så beredt var, gingo Presterna alltid in i det främre tabernaklet, och uträttade Gudstjensten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Men uti det andra gick allenast den öfverste Presten, en tid om året; icke utan blod, den han offrade för sina egna, och för folkens synder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Der den Helge Ande med betydde, att helighetenes väg ändå icke uppenbar var, emedan det första tabernaklet stod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Hvilket var en liknelse i den tiden, i hvilkom gåfvor och offer offrades, och kunde icke göra honom fullkommen, efter samvetet, som den Gudstjensten gjorde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Allenast med mat och dryck, och mångahanda tvagning, och utvärtes helighet, som pålagda voro intill bättringenes tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Men Christus är kommen, att han skall vara öfverste Prest till det tillkommande goda, genom ett större och fullkomligare tabernakel, det med händer icke gjordt är, det är, det icke så bygdt är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Icke heller genom bockablod, eller kalfvablod; utan han är genom sitt eget blod ena reso ingången uti det helga, och hafver funnit en evig förlossning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Ty hafver oxablod och bockablod, och strödd aska af kone, helgat de orena, till köttslig renhet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Huru mycket mer skall Christi blod, som hafver sig sjelf obesmittad, genom den Helga Anda, Gudi offrat, rena vårt samvet af de döda gerningar, till att tjena lefvandes Gud?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Derföre är han ock Nya Testamentsens Medlare; på det de, som kallade äro, skulle få dess eviga arfsens löfte, i thy att hans död gick deremellan, till förlossning ifrå de öfverträdelser, som under det förra Testamentet voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Ty hvar ett Testament är, måste ock hans död med vara, som Testamentet gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Ty Testamentet blifver gildt genom döden; annars hafver det ännu ingen magt, så länge han lefver som Testamentet gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Derföre var ock icke det första stiktadt utan blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Ty då Moses allo folkena föregifvit hade hvart och ett budord, efter lagen, tog han kalfvablod, och bockablod, med vatten, och purpurull, och hysop, och bestänkte bokena, och allt folket;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Och sade: Detta är Testamentsens blod, det Gud hafver eder budit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Och desslikes tabernaklet, och all kärile, der Gudstjenst plägade med göras, bestänkte han sammalunda med blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Och varda mest all ting efter lagen ren gjord i blod; och utan blodsutgjutelse sker ingen förlåtelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Så är nu af nöden, att de himmelska tings eftersyner skola med sådant renade varda; men de himmelska tingen måste bättre offer hafva, än dessa voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Ty Christus är icke ingången i det helga, som med händer gjordt är, hvilket är en eftersyn till det sannskyldiga; utan in uti sjelfva himmelen, på det han skall nu vara i Guds åsyn för oss;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Icke, att han skall ofta offra sig, såsom öfverste Presten gick hvart år in uti det heliga, med annars blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Eljest måste han skolat ofta lida, af verldenes begynnelse; men nu, på verldenes ändalykt, är han en gång uppenbarad, genom sitt eget offer, till att borttaga syndena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Och såsom menniskomen är förelagdt en gång dö, men sedan domen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Så är ock Christus ena reso offrad, till att borttaga mångs mans synder; men en annan gång skall han låta se sig, utan synd, dem som honom vänta till salighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Ty lagen hafver skuggan af det tillkommande goda, och icke sjelfva varelsen. Årliga måste man offra alltid enahanda offer, och kan icke göra dem fullborda, som det offra;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Annars hade det återvändt offras; efter de, som så offra, hade sedan intet samvet haft af synder, när de hade ena reso varit rene gjorde;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Utan dermed sker en åminnelse på synderna hvart år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Ty omöjeligit är genom oxablod och bockablod borttaga synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Derföre, då han kommer i verldena, säger han: Offer och gåfvor hafver du icke velat; men kroppen hafver du mig beredt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Bränneoffer och syndoffer behaga dig icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Då sade jag: Si, jag kommer; i bokene är skrifvet om mig, att jag skall göra din vilja, o Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Tillförene, då han sade: Offer och gåfvor, bränneoffer och syndoffer hafver du icke velat; icke behaga de dig heller, hvilke efter lagen offras;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Då sade han: Si, jag kommer, till att göra, o Gud, din vilja. Der tager han det första bort, att han det andra insätta skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'I hvilkom vilja vi helgade ärom ena reso, genom Jesu Christi kropps offer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Och hvar och en Prest är insatt, att han dageliga skall sköta Gudstjensten, och ofta offra enahanda offer, hvilka aldrig kunna borttaga synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Men denne, då han hade offrat ett offer för synderna, det evinnerliga gäller, sitter han på Guds högra hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Och väntar nu, tilldess hans ovänner lagde varda, honom till en fotapall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Ty med ett offer hafver han evinnerliga fullkomnat dem, som helige varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Det betygar oss ock den Helge Ande; ty då han tillförene sagt hade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Det är det Testamentet som jag dem göra vill, efter de dagar, säger Herren: Jag vill gifva min lag i deras hjerta, och i deras sinne vill jag skrifva dem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Och deras synder och orättfärdighet vill jag icke mer ihågkomma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Der nu sådana förlåtelse är, der är icke mer offer för synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Efter vi nu hafve, käre bröder, frihet till att ingå uti det helga, genom Jesu blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Hvilken han oss beredt hafver till en ny och lefvande väg, genom förlåten, det är, genom sitt kött;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Och hafvom en öfversta Prest öfver Guds hus;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Så låt oss framgå med ett sannskyldigt hjerta, uti en fullkomlig tro, bestänkte i hjertan ifrån ett ondt samvet, och tvagne om kroppen med rent vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Och låt oss hålla hoppsens bekännelse ovikliga; ty han är trofast, som det lofvat hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Och låt oss akta på oss inbördes, till att uppväcka till kärlek och goda gerningar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Icke öfvergifvandes vår församling, såsom somlige för sed hafva; utan förmaner eder inbördes, och det dess mer, att I sen huru dagen nalkas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Ty om vi sjelfviljande syndom, sedan vi förstått hafve sanningen, då står oss intet offer igen för synderna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Utan en förskräckelig domsens förbidelse, och eldsens nit, som motståndarena förtära skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Ho som bryter Mosi lag, han måste dö utan barmhertighet, efter tu eller tre vittne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Huru mycket större näpst, menen I, förtjenar den som Guds Son förtrampar, och Testamentsens blod såsom orent aktar, genom hvilket han helgad är, och försmädar nådenes Anda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Ty vi kännom den som sade: Hämnden är min; jag skall vedergällat, säger Herren; och åter: Herren skall döma sitt folk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Det är gräseligit falla uti lefvandes Guds händer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Men kommer ihåg de framledna dagar, i hvilkom I upplyste voren, och stoden en stor törning i bedröfvelsen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Endels, då I sjelfve, genom hädelse och bedröfvelse, ett vidunder vorden; och endels, då I sällskap haden med dem, som det så går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Ty I hafven delaktige varit af de bedröfvelser, som af minom bojom gingo, och med fröjd lidit edra ägodelars försköfling, vetandes att I när eder sjelfva bättre och blifvande ägodelar hafven i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Så kaster icke nu bort edra tröst, som en stor lön hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Ty tålamodet är eder behof; på det I mågen göra Guds vilja, och få det som lofvadt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Ty ännu en liten tid, så kommer den som komma skall, och fördröjer icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Men den rättfärdige skall lefva af tron; och hvilken sig undandrager, han skall icke behaga mine själ.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Men vi ärom icke de, som oss undandrage till förtappelse; utan af dem som tro, och frälsa själena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Men tron är en viss förlåtelse på det som man hoppas, och intet tvifla om det man icke ser.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Genom henne hafva de gamle fått vittnesbörd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Genom trona besinnom vi, att verlden är fullbordad genom Guds ord; så att allt det man ser, är vordet af intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Genom trona offrade Abel Gudi större offer än Cain; med hvilko han fick vittnesbörd att han var rättfärdig, då Gud gaf om hans gåfvor vittnesbörd; och genom henne talar han ännu, ändock han död är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Genom trona vardt Enoch borttagen, så att han icke skulle se döden, och fans intet, derföre att Gud borttog honom; ty förr än han borttagen var, hade han fått vittnesbörd att han täcktes Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Ty utan trona är omöjeligit täckas Gudi. Ty den till Gud komma vill, han måste tro att Gud är, och att han lönar dem som söka honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Genom trona ärade Noe Gud, och beredde arken, till sins hus salighet, då han fick Guds befallning om de ting som icke syntes; genom hvilken (ark) han fördömde verldena, och vardt den rättfärdighets arfvinge, som af trone är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Genom trona vardt Abraham lydig, då han kallad vardt till att utgå i det land, som han få skulle till arfs; och for ut, och visste icke hvart han komma skulle.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Genom trona var han en främling uti det landet honom lofvadt var, lika som uti ett främmande land, bodde uti tabernakel, med Isaac och Jacob, som medarfvingar voro till samma löfte;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Ty han vänte efter en stad, som grund hade; hvilkens byggomästare och skapare är Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Genom trona fick ock Sara kraft till att afla, och födde öfver sin ålders tid; ty hon höll honom trofastan, som det lofvat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Derföre vordo ock af enom, som i den måtton död var, månge födde, såsom stjernorna på himmelen, och som sanden är i hafsstrandene, den otalig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'I trone äro desse alle döde, och hafva dock intet fått af löftet; utan sett det fjerran efter, och trott deruppå och låtit sig nöja, bekännande sig vara gäster och främmande på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Ty de som sådant säga, gifva tillkänna att de söka ett fädernesland.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Och om de hade det ment, der de utgångne voro, hade de väl haft tid att vända tillbaka.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Men nu begära de ett bättre, det är, det himmelska. Derföre skämmes icke Gud kallas deras Gud; ty han hafver beredt dem en stad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Genom trona offrade Abraham Isaac, när han försökt vardt; och offrade enda sonen, då han hade fått löftet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Om hvilken sagdt var: Uti Isaac skall dig din säd kallad varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Och tänkte, att Gud kunde ock väl uppväcka ifrå de döda; deraf tog han ock honom igen till en liknelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Genom trona välsignade Isaac Jacob och Esau, om tillkommande ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Genom trona, då Jacob dödde, välsignade han båda Josephs söner; och tillbad det öfversta på hans spiro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Genom trona, då Joseph dö skulle, talade han om Israels barns utgång; och gaf befallning om sin ben.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Genom trona vardt Moses fördold, i tre månader, af sina föräldrar, då han född var; derföre att de sågo att han var ett dägeligit barn, och fruktade intet Konungens bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Genom trona, då Moses var stor vorden, nekade han sig vara Pharaos dotterson;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Och ville mycket heldre lida bedröfvelse med Guds folk, än till en tid hafva lust i syndene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Och höll Christi försmädelse för större rikedom, än de håfvor uti Egypten; ty han såg efter lönen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Genom trona öfvergaf han Egypten, intet fruktandes Konungens vrede; ty han höll sig vid den han icke såg, såsom han honom sett hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Genom trona höll han Påska, och blodsutgjutelse, på det han, som drap allt det förstfödt var, skulle intet komma vid dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Genom trona gingo de genom det röda hafvet, såsom på torra landet; hvilket de Egyptier ock försökte, och drunknade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Genom trona föllo murarna i Jericho, då man i sju dagar omkring gångit hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Genom trona förgicks icke den skökan Rahab med de otrogna, då hon de spejare anammat hade med frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Och hvad skall jag mer säga? Tiden vorde mig för stackot, när jag förtälja skulle om Gideon, om Barak, och Simson, och Jephthah, och David, och Samuel, och Propheterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Hvilke genom trona hafva vunnit Konungarike, gjort rättfärdighet, fått löfte, igenstoppat lejons mun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Eldskraft utsläckt, svärdsegg undkommit, äro kraftige vordne af svaghetene, äro starke vordne i stridene, hafva nederlagt främmande härar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Qvinnorna hafva igenfått sina döda utaf uppståndelsen; somlige vordo sönderslagne, och hafva ingen förlossning velat anamma, på det de skulle få uppståndelsen, som bättre är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Somlige hafva lidit spott och hudflängning, och dertill bojor och fängelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Vordo stenade, sönderhuggne, genomstungne, döde för svärd; hafva gångit i fårskinn och getskin, fattige, trängde, bedröfvade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'Hvilkom verlden icke värdig var; och hafva gått elände i ökner, och i berg, och i skrefvor, och i jordkulor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Alle desse hafva genom trona fått vittnesbörd, och hafva dock icke fått löftet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Derföre att Gud hade föresett om oss något det bättre var; att de icke utan oss skulle fullkomnade varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Efter vi nu hafve om oss en så stor hop med vittne, låt oss aflägga syndena, som alltid låder vid oss och gör oss tröga, och låt oss med tålamod löpa i den kamp som oss förelagd är;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Och se på Jesum, som trona begynt och fullkomnat hafver; hvilken, då han måtte haft glädje, led korset, och aktade intet smäleken; och är sittandes på högra handen på Guds stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Tänker på honom, som af syndarom sådana gensägelse led emot sig; att I icke tröttens i edor sinne, gifvandes eder utöfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Ty I hafven icke ännu allt intill blods emotståndit, kämpande emot syndene;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Och hafven redo förgätit den tröst, som till eder talar, lika som till sin barn: Min son, förakta icke Herrans aga; och gif dig icke utöfver, då du näpses af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Ty hvem Herren älskar, den agar han; men han gisslar hvar och en son, han anammar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Hvar I nu liden agan, så bjuder sig Gud till eder, såsom till barn; ty hvilken är den son, som hans fader icke agar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Ären I utan aga, i hvilkom alle delaktige vordne äro, så ären I oägta, och icke barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Hafve vi nu köttsliga fäder, som oss aga, och frukte dem; skole vi då icke mycket mer underdånige vara dem andeliga Fadrenom, att vi må lefva?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Och de förre hafva agat oss i några få dagar, efter som dem syntes; men denne till det som nyttigt är, att vi må få hans helgelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'All age synes nu icke vara till fröjd, utan till ångest; men sedan vedergäller han en fridsam rättfärdighetenes frukt dem, som deruti öfvade äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Derföre lyfter upp edra lata händer och trötta knä;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Och stiger viss steg med edra fötter; att icke någor haltar såsom en ofärdig, utan heldre helbregda varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Farer efter frid med allom, och efter helgelse, utan hvilken ingen får se Herran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Och ser till, att ingen försummar Guds nåd; att icke uppväxer någon bitter rot, och gör något hinder, och månge måtte genom henne besmittade varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Att ingen vare en bolare, eller ohelig, såsom Esau, hvilken för en måltid bortsålde sin förstfödslorätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Men I veten, att då han ville sedan, med arfsrätt, få välsignelse, vardt han bortdrifven; och var honom då intet rum till någon bot, ändock han med tårar derefter sökte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Ty I ären icke gångne till det berget, der man på taga kunde, och med eld brann, eller till töcknene, och mörkret, och stormen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'Och basunsklanget, och till ordarösten; hvilka de vedersakade, som henne hörde, begärande att ordet skulle dem ju icke sagdt varda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Ty de förmåtte icke lida det, som der sades: Om något djur kom vid berget, skulle det stenas, eller skjutas igenom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Och så förskräckelig var den synen, att Moses sade: Jag är förskräckt, och bäfvar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Utan I ären komne till Sions berg, och till lefvandes Guds stad, det himmelska Jerusalem, och till den otaliga Änglaskaran.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Och till de förstföddas församling, som i himmelen äro beskrefne; och till Gud, som alla dömer, och till de fullkomliga rättfärdigas andar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Och till Nya Testamentsens Medlare, Jesum, och till stänkelseblodet, som bättre talar än Abels blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Ser till, att I icke vedersaken honom som med eder talar; ty kunde icke de undfly, som vedersakade honom som talade på jordene; huru mycket mindre vi, om vi vedersake honom som af himmelen talar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Hvilkens röst på den tid gjorde jordena bäfvande? Men nu lofvar han, och säger: Ännu en tid skall jag göra bäfvande, icke allenast jordena, utan ock himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Det han säger: Ännu en tid, det gifver tillkänna de tings förvandling, som bäfva, såsom de der gjord äro; på det de ting blifva skola, som obäfvande äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Derföre, efter vi få det rike som icke bäfva kan, hafve vi nåd, genom hvilka vi tjene Gudi, till att täckas honom med tuktighet och fruktan;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Ty vår Gud är en förtärande eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Blifver faste i broderlig kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Förgäter icke att herberga; ty dermed hafva somliga fått Änglar, ovetandes, till herberges.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Tänker på dem som bundne äro, såsom medbundne; och på dem som bedröfvelse lida, såsom de der ock af lekamenen äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Ägtenskapet skall hållas ärligit ibland alla, och ägtenskapets säng obesmittad; men bolare och horkarlar skall Gud döma.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Umgängelsen vare utan girighet; och låter eder nöja med det I hafven; ty han sade: Jag skall icke öfvergifva eller förlåta dig;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Så att vi dristeliga måga säga: Herren är min hjelpare, och jag vill icke frukta; hvad kan en menniska göra mig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Tänker på edra lärare, de eder Guds ord sagt hafva, och efterföljer deras tro; skådande hvad ända deras umgängelse hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Christus i går och i dag, och han desslikes i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Låter eder icke omföras med mångahanda och främmande lärdom; ty det är godt att stadfästa hjertat med nådene; icke med maten; hvilken intet gagnat hafver dem, som dermed umgått hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Vi hafve ett altare, af hvilko de hafva icke magt att äta, som tjena i tabernaklet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Ty ehvad djurs blod, som öfverste Presten, för syndene, inbär uti det heliga, deras kroppar uppbrännas utom lägret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Derföre ock Jesus, på det han skulle helga folket med sitt eget blod, hafver han lidit utom porten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Så låt oss nu gå ut till honom utu lägret, och bära hans smälek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Ty vi hafve här ingen varaktig stad, utan vi sökom efter den tillkommande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Så låt oss nu genom honom alltid offra Gudi lofoffer, det är, läpparnas frukt, de hans Namn bekänna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Förgäter icke göra väl, och meddela; ty sådana offer täckas Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Varer edra lärare lydige, och följer dem; ty de vaka öfver edra själar, såsom de der räkenskap göra skola; på det de måga det göra med fröjd, och icke med suckan; ty det är eder icke nyttigt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Beder för oss; vår tröst är den att vi ett godt samvet hafve, och vinnlägge oss hafva en god umgängelse när alla;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Men aldramest beder jag eder, att I sådant gören, att jag med det snaresta måtte komma till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Men fridsens Gud, som igenfört hafver ifrå de döda den stora Fåraherdan, genom dess eviga Testamentsens blod, vår Herra Jesum;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Han göre eder skickeliga uti allt godt verk, till att göra sin vilja, och skaffe uti eder hvad honom täckeligit är, genom Jesum Christum; hvilken vare ära af evighet i evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Jag förmanar eder, käre bröder, tager förmanelsens ord till godo; ty jag hafver eder med få ord tillskrifvit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Veter, att brodren Timotheus lös är; med hvilkom, om han snart kommer, vill jag se eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Helser alla edra lärare, och all helgon. Eder helsa bröderne uti Valland.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Nåd vare med eder allom. Amen. Till de Ebreer, skrifven af Valland, med Timotheo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jacobus, Guds och Herrans Jesu Christi tjenare: dem tolf slägtom, som äro här och der förskingrade, helso.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Mine bröder, håller det för all glädje, när I fallen i mångahanda frestelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Och veter, att edor tros bepröfvelse gör tålamod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Men låter tålamodet hafva ett fullbordadt verk; på det I skolen vara fullkomna och hele, och intet fel hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Hvar nu någrom ibland eder fattas visdom, han bedje af Gudi, den der gifver enfaldeliga allom, och förviter icke; och han skall honom gifven varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Men han bedje i trone, intet tviflandes; ty den der tviflar, han är såsom hafsens våg, som af vädret drifs och föres.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Sådana menniska tänke icke, att hon får något af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'En man, som tviflar, är ostadig i alla sina vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Men en broder, som ringa är, berömme sig af sin upphöjelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Och den som rik är, af sin förnedring; ty såsom blomstret af gräset skall han förgås.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Solen går upp med hetta, och gräset förvissnar, och blomstret faller af, och dess sköna fägring förgås; så skall ock den rike förvissna uti sina vägar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Salig är den man, som tåleliga lider frestelse; ty då han bepröfvad är, skall han ta lifsens krono, den Gud lofvat hafver dem som honom älska.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Ingen säge, då han frestad varder, att han af Gudi frestad varder; ty Gud frestas icke af ondt, han frestar ock ingen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Utan hvar och en varder frestad, då han af sin egen begärelse dragen och lockad varder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Derefter, sedan begärelsen hafver aflat, föder hon synden; men då synden är fullbordad, föder hon döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Farer icke ville, mine käre bröder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'All god gåfva, och all fullkomlig gåfva kommer ofvanefter, ifrå ljusens Fader; när hvilkom ingen förvandling är, eller ljus och mörkers omskiftelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Han hafver oss födt efter sin vilja, genom sanningenes ord, på det vi skulle vara förstlingen af hans kreatur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Derföre, mine käre bröder, hvar och en menniska vare snar till att höra, och sen till att tala, och sen till vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Ty mansens vrede gör icke det rätt är för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Lägger fördenskull bort alla orenlighet och alla ondsko, och anammer ordet med saktmodighet, som i eder plantadt är, det edra själar kan saliga göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Men varer ordets görare, och icke allenast hörare, bedragandes eder sjelfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Ty der någor är allenast ordsens hörare, och icke görare, han är lik den man, som sitt lekamliga ansigte skådar i en spegel;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Ty då han sig beskådat hafver, går han derifrån, och förgäter straxt hurudana han var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Men den der skådar uti frihetenes fullkomliga lag, och blifver deruti, och är icke en glömsker hörare, utan en görare, den samme varder salig uti sin gerning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Hvar nu någor ibland eder låter sig tycka, att han tjenar Gudi, och icke styrer sina tungo, utan bedrager sitt hjerta, hans Gudstjenst är fåfäng.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Detta är för Gudi och Fadren en ren och obesmittad Gudstjenst, söka faderlös och moderlös barn, och enkor, uti deras bedröfvelse, och behålla sig obesmittad af verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mine bröder, håller det icke derföre, att tron på Jesum Christum, vår Herra till härlighetena, kan lida personers anseende.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Ty om uti edra församling komme en man med en guldring, och med en härlig klädnad; komme ock en fattig man i snöplig klädnad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Och I sågen på den som hafver de härliga kläden, och saden till honom: Sitt här väl; och dem fattiga saden I: Statt der, eller, sitt här vid mina fötter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Och betänken det icke rätt, utan varden domare, och gören en ond åtskilnad;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Hörer till, mine käre bröder: Hafver icke Gud utvalt de fattiga i denna verldene, de der rike voro på trona, och arfvingar till riket, som han lofvat hade dem som honom älska?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Men I hafven föraktat den fattiga. Förtrycka icke de rike eder med våld, och draga eder fram för rätten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Försmäda icke de det goda namnet, der I af nämnde ären?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Fullborden I den Konungsliga lagen efter Skriften: Älska din nästa, såsom dig sjelf; så gören I väl.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Men sen I efter personen, då synden I, och varden straffade af lagen, såsom öfverträdare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Ty om någor håller hela lagen, och syndar på ett, han är saker till allt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Ty den som sade: Du skall icke göra hor, han hafver ock sagt: Du skall icke dräpa. Hvar du nu icke gör hor, och dräper likväl, äst du lagsens öfverträdare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Så taler, och så görer, som de der skola genom frihetenes lag dömde varda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Ty dom utan barmhertighet skall honom öfvergå, som barmhertighet icke gjort hafver; och barmhertigheten berömmer sig emot domen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Hvad hjelper det, mine bröder, om någor säger sig hafva trona, och hafver dock icke gerningarna? Kan ock tron göra honom salig?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Om en broder eller syster vore nakot, och fattades dagelig föda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Och någor edra sade till dem: Går i frid, värmer eder, och mätter eder; och gifver dem likväl intet hvad lekamen behöfver; hvad hulpe dem det?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Så ock tron, då hon icke hafver gerningarna, är hon död i sig sjelf.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Nu måtte någor säga: Du hafver trona, och jag hafver gerningarna; visa mig dina tro med dina gerningar, så vill jag ock visa dig mina tro med mina gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Du tror, att en Gud är; der gör du rätt uti; djeflarna tro det ock, och bäfva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Vill du, fåfängelig menniska, veta att tron utan gerningar är död?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Vardt icke Abraham, vår fader, af gerningarna rättfärdigad, då han sin son Isaac offrade på altaret?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Ser du, att tron hafver medverkat i hans gerningar, och att tron är fullkommen vorden af gerningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Och Skriften är fullkomnad, som säger: Abraham trodde Gudi, och det vardt honom räknadt till rättfärdighet; och vardt kallad Guds vän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Sen I nu, att af gerningarna rättfärdigas menniskan, och icke af trone allena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Sammalunda ock den skökan Rahab, vardt hon icke af gerningom rättfärdigad, då hon undfick sändningabåden, och släppte dem en annan väg ut?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Derföre, såsom kroppen utan anda är död, så är ock tron utan gerningar död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Mine bröder, farer icke hvar man efter att vara lärare; vetande att vi dess större dom fåm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Ty i mång stycke fele vi alle; men den der icke felar uti ett ord, han är en fullkommen man, och kan regera hela lekamen med betsel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Si, vi läggom hästomen betsel i munnen, att de skola lyda oss, och omkastom deras hela kropp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Si ock skeppen, ehuru stor de äro, och af starkt väder drifvas, varda de dock likväl omvänd med ett litet roder, ehvart rodermannen vill.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Så är ock tungan en klen lem, och kommer stor ting åstad; si en liten eld, huru stor skog han upptänder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Och tungan är ock en eld, en verld full med orätt. Så är ock tungan ibland våra lemmar, och besmittar hela lekamen, och upptänder all vår umgängelse, då hon upptänd är af helvete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Ty all natur, både djurs, och foglars, och ormars, och deras som i hafvet äro, varder tam, och är tamd af menniskors natur;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Men tungan kan ingen menniska tämja, det oroliga onda, full med dödelig förgift.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Med henne prise vi Gud, och Fadren; och med henne bannom vi menniskorna, som äro skapade efter Guds liknelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Af samma mun går pris och bannor. Det bör icke, mine bröder, så vara.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Icke gifver en källa af ett hål både sött och bäskt vatten?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Icke kan fikonträt, mine bröder, bära oljo, eller vinträt fikon? Så kan ock ingen källa salt och sött vatten gifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Ho är vis och klok ibland eder, han bevise med sin goda umgängelse sina gerningar, uti saktmodighet och visdom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Om I hafven bittert nit och träto uti edart hjerta, berömmer eder icke, och ljuger icke emot sanningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ty den visdom är icke ofvanefter kommen, utan är jordisk, mennisklig, och djefvulsk.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Ty hvar nit och träta är, der är ostadighet och allt ondt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Men den visdom, som ofvanefter är, han är först kysk, och sedan fridsam, saktmodig, låter säga sig, full med barmhertighet och goda frukter, opartisk, oskrymtelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Men rättfärdighetenes frukt varder sådd i frid, dem som frid hålla.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Hvadan äro örlig och krig ibland eder? Äro de icke deraf, af edrom begärelsom, som strida i edra lemmar?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'I begären, och fån intet; I hafven afund och nit, och kunnen intet vinna; I striden och örligen, och hafven intet, derföre att I intet bedjen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'I bedjen, och fån intet; ty I bedjen illa, nämliga att I det uti edra vällust förtära skolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'I horkarlar och horkonor, veten I icke, att verldenes vänskap är Guds ovänskap? Ho som verldenes vän vill vara, han varder Guds ovän.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Menen I att Skriften säger fåfängt: Anden, som bor uti eder, begärar emot hatet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Men han gifver rikeliga nåd. Ty Skriften säger: Gud står emot de högfärdiga; men dem ödmjukom gifver han nåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Så varer nu Gudi underdånige; står emot djefvulen, så flyr han ifrån eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Nalkens Gudi, så nalkas han eder. Rener edra händer, I syndare, och renser edor hjerta, I ostadige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Varer elände, och sörjer, och gråter: edart löje vände sig i gråt, och glädjen i sorg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Förnedrer eder för Herranom, så skall han eder upphöja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Förtaler icke hvarannan, käre bröder; den som förtalar sin broder, och dömer sin broder, han förtalar lagen, och dömer lagen; men dömer du lagen, så äst du icke lagsens görare, utan domare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Ty en är laggifvaren, som kan saliggöra, och fördöma; ho äst du, som dömer en annan?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Nu väl, I som sägen: I dag, eller i morgon vilje vi gå uti den eller den staden, och vilje der ligga ett år, och handla, och vinna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Och veten icke hvad i morgon ske kan; ty hvad är edart lif? Ett damb äret, som en liten tid varar, och sedan försvinner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'För det I säga skullen: Om Herren vill, och vi lefve, så vilje vi göra det eller det.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Men nu berömmen I eder i edart högmod. All sådana berömmelse är ond.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Den der kan göra godt, och gör icke, honom är det synd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Nu väl, I rike, gråter, och tjuter öfver edor uselhet, som eder öfverkomma skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Edre rikedomar äro förruttnade; edor kläder äro uppäten af mal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Edart guld och silfver är förrostadt, och deras rost skall vara eder till vittnesbörd, och skall uppäta edart kött såsom en eld. I hafven församlat eder ägodelar i yttersta dagarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Si, arbetarenas lön, som edart land afbergat hafva, hvilken I dem svikliga ifrå haft hafven, ropar; och deras rop, som afbergade, är inkommet i Herrans Zebaoths öron.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'I hafven lefvat i kräselighet på jordene, och haft edra vällust, och uppfödt edor hjerta, såsom på en slagtedag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'I hafven dömt och dödat den rättfärdiga, och han hafver eder intet emotståndit.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Så varer nu tålige, käre bröder, intill Herrans tillkommelse. Si, åkermannen väntar efter den kosteliga jordenes frukt, tåleliga bidandes, så länge han får ett morgonregn och aftonregn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Så varer ock I tålige, och styrker edor hjerta; ty Herrans tillkommelse är när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Sucker icke, käre bröder, emot hvarannan, på det I icke varden fördömde. Si, domaren är för dörrene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Tager, mine bröder, Propheterna för efterdömelse, till bedröfvelse och tålamod, hvilke talat hafva i Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Si, vi hålle dem saliga, som lidit hafva. Jobs tålamod hafven I hört, och Herrans ända hafven I sett; ty Herren är barmhertig, och en förbarmare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Öfver all ting, mine bröder, svärjer icke, hvarken vid himmelen, eller vid jordena, eller någon annan ed. Men edor ord skola vara: Ja, ja, Nej, nej; på det I icke skolen falla uti skrymteri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Lider någor ibland eder bedröfvelse; han bedje. Är någor vid godt mod, han sjunge psalmer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Är någor sjuk ibland eder, han kalle till sig Presterna i församlingene, och låte dem bedja öfver sig, och smörja med oljo uti Herrans Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Och trones bön skall hjelpa den sjuka, och Herren upprättar honom; och om han är stadd i synder, varda de honom förlåtna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Bekänner inbördes synderna, den ene dem andra, och beder för eder inbördes, att I helbregda varden; ty ens rättfärdigs mans bön förmår mycket, der hon allvar är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elias var en menniska såsom vi, och han bad ena bön, att det icke skulle regna; och det regnade ock intet på jordena, i tre år och sex månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Och bad åter, och himmelen gaf regn, och jorden bar sin frukt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Käre bröder, om någor ibland eder fore vill ifrå sanningen, och någor omvände honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Han skall veta, att den der omvänder en syndare af hans vägars villo, han frälsar ena själ ifrå döden, och skyler all öfverträdelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petrus, Jesu Christi Apostel, dem utkoradom främlingom, som bo här och der i Ponto, Galatien, Cappadocien, Asien, och Bithynien,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Efter Guds Faders försyn, genom Andans helgelse, till lydnona och Jesu Christi blods stänkelse. Nåd och frid föröke sig i eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Välsignad vare Gud, och vårs Herras Jesu Christi Fader, som oss för sin stora barmhertighet hafver födt på nytt till ett lefvandes hopp, genom Jesu Christi uppståndelse ifrå de döda;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Till oförgängeligit, obesmittadt, och ovanskeligit arf; hvilket i himmelen förvaradt är till eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Som med Guds magt bevarens genom trona till salighet, hvilken beredd är, att hon skall uppenbar varda i den yttersta tiden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'I hvilkom I eder fröjda skolen, I som nu en liten tid liden bedröfvelse, i margahanda försökelse, hvar så behöfves:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'På det edor tro skall rättsinnig och mycket kosteligare befunnen varda, än det förgängeliga guld som pröfvas med eld, till lof, pris och äro, när Christus Jesus blifver uppenbar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Hvilken I älsken, ändock I icke sen honom; den I ock nu tron uppå, och dock icke sen; så skolen I fröjda eder med osägeliga och härliga glädje;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Och få edor tros ändalykt, nämliga själarnas salighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Efter hvilken salighet Propheterne hafva sökt och ransakat, som propheterat hafva om den tillkommande nåd till eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Och hafva ransakat, på hvad eller hurudana tid Christi Ande utviste, den i dem var, och tillförene hade betygat de lidande, som i Christo äro, och den härlighet, som derefter följa skulle,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Hvilkom det ock uppenbaradt var: ty de hafva icke sig sjelfvom, utan oss, dermed tjent; hvilke stycker eder nu förkunnad äro, genom dem som eder Evangelium predikat hafva, genom den Helga Anda som sändes af himmelen, hvilket Änglomen ock lyster se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Derföre, begjorder edor sinnes länder, och varer nyktre, och sätter fullkomligit hopp till den nåd som eder tillbuden varder, genom Jesu Christi uppenbarelse,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Såsom lydaktig barn; och ställer eder icke såsom tillförene, då I uti fåvitsko lefden, efter begärelsen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Utan, efter honom, som eder kallat hafver, och helig är, varer ock I helige uti all edor umgängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Ty det är skrifvet: I skolen vara helige; ty jag är helig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Och efter I åkallen honom för en Fader, som dömer efter hvars och ens gerning, och hafver intet anseende till personen, så ser till att I, uti detta edart elände, vandren i räddhåga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Och veter, att I icke med förgängeligit silfver eller guld igenlöste ären ifrån edart fåfänga lefverne, efter fädernas sätt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Utan med Christi dyra blod, såsom med ett menlöst och obesmittadt lambs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Hvilken väl föresedd var för verldenes begynnelse; men uppenbarad i de yttersta tiderna, för edra skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Som genom honom tron på Gud; den honom uppväckt hafver ifrå de döda, och gifvit honom härlighet; på det I skullen hafva tro och hopp till Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Och görer edra själar kyska, i sanningenes lydno genom Andan, till oskrymtad broderlig kärlek; älsker eder storliga inbördes af rent hjerta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Såsom de, som födde äro på nytt; icke af någor förgängelig säd, utan af oförgängelig, som är, af lefvandes Guds ord, det evinnerliga blifver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Ty allt kött är såsom gräs, och all menniskos härlighet såsom blomster på gräset; gräset är vissnadt, och blomstret är affallet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Men Herrans ord blifver evinnerliga; och det är det ord, som predikadt är ibland eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Så lägger nu bort alla ondsko, och allt svek, och skrymteri, och afund, och allt förtal;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Och åstunder förnuftenes mjölk, som intet svek vet, såsom nyfödd barn; på det att I uppväxen af henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Om I annars hafven smakat att Herren är god;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Till hvilken I komne ären, såsom till den lefvande stenen, som af menniskom förkastad är, men när Gudi utkorad och kostelig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'I ock, såsom lefvande stenar, uppbygger eder till ett andeligit hus, och till ett heligt Presterskap, till att offra andelig offer, som Gudi äro tacknämlig, genom Jesum Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Derföre håller ock Skriften: Si, jag lägger i Zion en utvald kostelig hörnsten, och hvilken som tror på honom, han skall icke komma på skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Eder, som tron, är han kostelig; men dem som icke tro är stenen, som byggningsmännerna hafva bortkastat, vorden till en hörnsten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Och en sten, der man stöter sig på, och en förargelseklippo dem som stöta sig på ordet, och tro icke derpå, der de till skickade voro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Men I ären det utvalda slägtet, det Konungsliga Presterskapet, det heliga folket, och det egendomsfolket; att I skolen kungöra hans dygd, som eder kallat hafver af mörkret, till sitt underliga ljus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'I, som tillförene icke voren folk, ären nu Guds folk; och I, som tillförene icke haden fått barmhertighet, hafven nu fått barmhertighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Käre bröder, jag förmanar eder, såsom främmande och elända, att I förvaren eder för köttsliga begärelser, hvilka strida emot själena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Och förer en god umgängelse ibland Hedningarna; på det de, som pläga förtala eder såsom illgerningsmän, måga se edra goda gerningar, och prisa Gud, när det i dagsljuset kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Varer underdånige all mennisklig ordning, för Herrans skull, ehvad det är Konungenom, såsom den öfversta,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Eller befallningsmännerna, såsom de der sände äro af honom, de onda till straff, och de goda till pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Ty så är Guds vilje, att I med goda gerningar skolen igenstoppa munnen af de galna och oförståndiga menniskor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Såsom de frie, och icke såsom I hafven den frihet till att skyla ondskona med, utan såsom Guds tjenare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Varer hedersamme emot hvar man; älsker bröderna; frukter Gud; ärer Konungen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'I tjenare, varer underdånige edrom herrom med all fruktan; icke allenast dem godom och saktmodigom, utan ock dem genvördigom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Ty detta är nåd, om någor, för samvetets skull till Gud, fördrager bedröfvelse, och lider orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Ty hvad pris är det, om I för edra missgerningar slagne varden, och liden? Men när I för välgerningars skull liden, och hafven tålamod, det är nåd för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Ty dertill ären I kallade, efter ock Christus led för oss, låtandes oss en efterdömelse, att I skolen efterfölja hans fotspår;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Hvilken ingen synd gjort hade; och intet bedrägeri vardt funnet i hans mun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'När han blef bannad, bannade han intet igen, och när han led, hotades han intet; utan ställde hämnden till den som rätt dömer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Hvilken våra synder sjelf offrade i sin lekamen på träd; på det vi skulle vara döde syndene, och lefva rättfärdighetene; genom hvilkens sår I ären helbregda vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Ty I voren såsom villfarande får; men I ären nu omvände till herdan, och edra själars Biskop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Sammalunda hustrurna, vare sina män underdåniga; på det ock de, som icke tro på ordet, måga af hustrurnas umgängelse, utan ord, blifva vunne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'När de förmärka edor kyska umgängelse med fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Hvilkas prydning icke skall vara utvärtes, med flätadt hår, eller kringhängande guld, eller i kostelig kläder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Utan om den fördolda menniskan i hjertat är utan vank, med saktmodigom och stillom anda, det är kosteligit för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Ty i så måtto hafva ock de helga qvinnor fordom prydt sig, de der satte sitt hopp till Gud, och voro sina män underdåniga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Såsom Sara var lydig Abrahe, kallandes honom herra; hvilkens döttrar I vordna ären, om I väl gören, och ären icke så förfärade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Sammaledes I män, bor när dem med förnuft, och gifver det qvinliga kärilet, såsom det der svagast är, sina äro; såsom ock medarfvingom till lifsens nåd; på det edra böner icke blifva förhindrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Men på sistone, varer alle vid ett sinne, medlidande, broderlig kärlek hafvande till hvarannan, barmhertige, vänlige;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Icke vedergällande ondt för ondt, icke bannor för bannor; utan heldre tvärtemot, välsigner; vetandes att I ären dertill kallade, att I skolen ärfva välsignelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Ty den der vill älska lifvet, och se goda dagar, han stille sina tungo ifrå det ondt är, och sina läppar, att de icke tala bedrägeri;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Vände sig ifrå det ondt är, och göre det godt är; söke efter friden, och fare honom efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Ty Herrans ögon äro öfver de rättfärdiga, och hans öron till deras bön; men Herrans ansigte är öfver dem som ondt göra.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Och ho är den som kan göra eder skada, om I faren efter det goda?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ja, om I än något liden för rättfärdighetenes skull, ären I dock likväl salige. Frukter eder intet för deras trug; icke heller förskräcker eder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Utan helger Herran Gud uti edor hjerta. Varer ock alltid redebogne till att svara hvarjom och enom, som begärar skäl till det hopp som i eder är; och det med saktmodighet och fruktan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Och hafver ett godt samvet; på det de, som vilja förtala eder såsom ogerningsmän, skola komma på skam, att de förlastat hafva edor goda umgängelse i Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Ty det är bättre, om Guds vilje så är, att I för goda gerningar liden, än för onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Ty Christus led ock ena reso för syndernas skull, rättfärdig för orättfärdiga; på det han skulle offra oss Gudi, och är dödad efter köttet; men lefvande gjord efter Andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'I dem samma gick han ock bort, och predikade för andarna i fängelset;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Som fordom icke trodde, när Gud en gång bidde, och tålamod hade i Noe tid, då arken byggdes, i hvilkom få, det är, åtta själar, blefvo frälste genom vattnet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Hvilket nu ock oss saliga gör i dopet, som genom hint betydt är (icke att köttsens smittor afläggas, utan att man hafver ett godt samvet till Gud), genom Jesu Christi uppståndelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Hvilken är på Guds högra hand, uppfaren till himla; och honom äro Änglarna, och väldigheterna, och krafterna underdåniga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Medan nu Christus lidit hafver i köttet för oss, så skolen I ock väpna eder med det samma sinnet; ty den der lider i köttet, han vänder åter af synden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'På det han den tiden, som tillbaka är i köttet, icke lefva skall efter menniskolusta, utan efter Guds vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Ty det är nog att vi, i förliden tid, hafve vårt lefverne förslitit efter Hedningarnas vilja, då vi vandrade i lösaktighet, i begärelse, i dryckenskap, i fråsseri, i svalg, och grufveliga afgudadyrkan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Och det synes dem sällsynt vara, att I icke löpen med dem uti samma slemma, oskickeliga väsende, och försmäden;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Hvilke skola göra räkenskap honom, som redo är döma lefvande och döda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Ty dertill är ock Evangelium predikadt för de döda, att de skola dömde varda efter menniskor, i köttet; men i Andanom lefva Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Men nu tillstundar änden på all ting. Så varer nu nyktre, och vakande till att bedja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Men öfver all ting hafver ju en brinnande kärlek inbördes; ty kärleken skyler ock all öfverträdelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Varer inbördes hvarannars herbergare, utan allt knorr.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Och varer tjenstaktige inbördes, hvar och en med den gåfvo som han hafver fått, såsom gode den margfaldeliga Guds nåds skaffare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Om någor talar, han tale såsom Guds ord; om någor hafver ett ämbete, han tjene såsom af den förmågo, som Gud gifver; på det Gud blifver ärad i all ting, genom Jesum Christum, hvilkom vare ära och våld evinnerliga. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Mine käreste, förundrer eder icke på den hetta, som eder vederfars (den eder vederfars, att I skolen försökte varda), såsom eder hände något nytt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Utan glädjens heldre, att I liden med Christo; på det I ock fröjdas och glädjas mågen uti hans härlighets uppenbarelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Salige ären I, om I för Christi Namns skull blifven försmädde; ty Anden, som är härlighetenes och Guds Ande, hvilas på eder; när dem blifver han försmädd, men när eder beprisad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Ingen ibland eder lide, såsom en mördare, tjuf, illgerningsman, eller som den der träder in i ens annars ämbete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Men lider han såsom en Christen, skämme sig intet; utan prise Gud för den delen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Ty tiden är, att domen skall begynnas på Guds hus; begynnes det på oss, hvad blifver då deras ändalykt, som icke tro Guds Evangelio?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Och blifver den rättfärdige med plats salig, hvar blifver då den ogudaktige och syndaren?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Derföre, de der lida efter Guds vilja, de skola befalla honom sina själar, såsom enom trofastom Skapare, med goda gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Presterna, som äro ibland eder, förmanar jag, som ock är en Prest, och vittne till Christi pino, och delaktig i den härlighet som uppenbaras skall:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Föder Guds hjord, som är ibland eder; och hafver akt på honom, icke nödige, utan sjelfviljande; icke för slem vinnings skull, utan af en god vilja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Icke heller såsom herrar öfver sitt folk; utan varer hjordenom till efterdömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Och sedan, då öfverste Herden uppenbar varder, skolen I undfå härlighetenes ovanskeliga krona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Sammalunda I unge, varer dem gamlom underdånige. Varer alle inbördes hvarannan underdånige, och håller eder hårdt vid ödmjukhetena; ty Gud står emot de högfärdiga, men de ödmjuka gifver han nåd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Så ödmjuker eder nu under Guds mägtiga hand, på det han eder upphöjer i sinom tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Alla edra omsorg kaster på honom; ty han hafver omsorg om eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Varer nyktre, och vaker; ty edar fiende, djefvulen, går omkring såsom ett rytande lejon, och söker hvem han uppsluka må.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Står honom emot, stadige i trone; och veter, att samma vedermöda vederfars edra bröder i verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Men Gud, som all nåd kommer af, den eder kallat hafver till sin eviga härlighet i Christo Jesu, han fullborde eder, som en liten tid liden, styrke, stödje och stadfäste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Honom vare ära, och magt evinnerliga. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Med edar trogna broder Silvanus, som jag menar, hafver jag eder tillskrifvit med få ord, förmanandes och betygandes, att detta är den rätta Guds nåd, som I uti stån.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Helsar eder den församling i Babylonien, utvald lika med eder; och min son Marcus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Helser eder inbördes med kärlekens kyss. Frid vare med eder allom, som äro i Christo Jesu. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Petrus, Jesu Christi tjenare och Apostel; dem som med oss lika dyrbara tro fått hafva i rättfärdighetena, som vår Gud gifver, och Frälsaren Jesus Christus.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Nåd och frid föröke sig i eder, genom Guds och vårs Herras Jesu Christi kunskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Efter det allahanda af hans Gudoms kraft, hvad som till lif och Gudaktighet tjenar, oss skänkt är, genom hans kunskap, som oss hafver kallat genom (sina) härlighet och dygd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Genom hvilka oss de dyra och aldrastörsta löfte gifna äro; nämliga, att I derigenom mågen blifva delaktige af Guds natur, om I flyn verldenes förgängeliga lusta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Så lägger eder nu derom alla vinning, att I uti edra tro låten finnas dygd, och i dygdene beskedelighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'I beskedelighetene måttelighet, i måttelighetene tålamod, i tålamodet Gudaktighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'I Gudaktighetene broderlig kärlek, i broderlig kärlek allmännelig kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Ty när dessa stycker äro rikeliga när eder, så låta de eder icke finnas fåfänga eller utan frukt, i vårs Herras Jesu Christi kunskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Men hvilken denna icke hafver, han är blind, och ser intet, och hafver förgätit, att han var ren gjord af de synder, som han förra hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Derföre, käre bröder, lägger eder heldre vinning om att I gören edor kallelse och utkorelse fast; ty om I det gören, så fallen I icke någon tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Ty i så måtto blifver eder rikeliga gifven ingången i vårs Herras och Frälsares Jesu Christi eviga rike.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Derföre vill jag icke hafva fördrag att förmana eder alltid härom, ändock I det veten, och ären stadfäste i denna närvarande sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Ty jag menar det vara tillbörligit, så länge jag är i denna hyddo, att uppväcka och förmana eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Ty jag vet att jag skall snarliga aflägga denna mina hyddo, såsom ock vår Herre Jesus Christus hafver mig kungjort.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Men jag vill vinnlägga mig att I, efter min död, skolen behålla detta i åminnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Ty vi hafve icke efterföljt några kloka fabler, då vi kungjordom eder vårs Herras Jesu Christi kraft och tillkommelse; utan vi hafve sjelfve sett hans härlighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Då han fick af Gud Fader äro och pris, genom ena röst, som till honom skedde af den stora härligheten, så lydandes: Denne är min älskelige Son, i hvilkom jag hafver ett godt behag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Och denna röst hörde vi komma af himmelen, då vi vorom med honom på det helga berget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Vi hafvom ett fast prophetiskt ord; och I gören väl att I akten derpå, lika som på ett ljus, som skin uti ett mörkt rum, så länge det dagas, och morgonstjernan uppgår i edor hjerta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Och det skolen I först veta, att ingen Prophetia i Skriftene sker af egen utläggning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Ty ingen Prophetia är ännu framkommen af menniskovilja; utan de helga Guds menniskor hafva talat, rörde af dem Helga Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Men falske Propheter voro ock ibland folket, som ock ibland eder varda skola falske lärare; hvilke med ibland införa skola förderfvelig partier, och förneka Herran, som dem köpt hafver; och skola föra öfver sig sjelfva en hastig fördömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Och månge skola efterfölja deras förderf; genom hvilka sanningenes väg blifver försmädd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Och uti girighet, med diktad ord, skola de handla med eder; hvilkom domen nu längesedan icke sen är, och deras fördömelse sofver icke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Ty hafver Gud icke skonat Änglomen, som syndade, utan hafver dem med mörksens kedjor nederkastat till helvetes, öfverantvardandes till att förvaras till domen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Och hafver icke skonat den förra verldene; utan bevarat Noe, rättfärdighetenes Predikare, sjelf åttonde, och lät floden gå öfver de ogudaktigas verld;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Och hafver gjort de städer Sodoma och Gomorra till asko, omstört och fördömt dem; och satt för ett efterdömelse dem ogudaktigom, som sedan komma skulle;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Och hafver frälst den rättfärdiga Lot, som var plågad af skamliga menniskor, genom deras sköraktiga umgängelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Ty efter han var rättfärdig, och bodde ibland dem, och måste dock sådana se och höra, plågade de dageligen den rättfärdiga själen med sina onda gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Herren kan frälsa de gudaktiga utaf frestelsen, men behålla de orättfärdiga till domedag, till att pinas;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Men aldramest dem som vandra efter köttet, uti orenom lusta, och försmå herrskapet, öfverdådige, ensinnade, och intet rädas försmäda väldigheterna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Ändock Änglarna, som i kraftene och starkhetene större äro, icke draga kunna den försmädeliga domen emot sig, af Herranom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Men de äro såsom de oförnuftiga djur, som af naturen dertill födda äro, att de skola fångna och slagtade varda; försmäda det de intet förstå, och skola uti sitt förderfveliga väsende förgås;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Och få orättfärdighetenes lön. De hållat för vällust, att de lefva i timeliga kräselighet; de äro slemheter och skamfläckar; pråla af edra gåfvor, slösa med edart;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Hafva ögonen full med horeri, låta icke förmena sig syndena, och locka till sig de ostadiga själar; hafva sin hjerta genomöfvad i girighet; förbannadt folk;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Öfvergifva rätta vägen, och gå ville, och efterfölja Balaams, Bosors sons väg, hvilken älskade vrånghetenes lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Men han blef straffad för sin vrånghet; det stumma arbetsdjuret talade med menniskoröst, och förtog Prophetens galenskap.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'De äro källor utan vatten, och molnskyr, som af vädret drifvas; hvilkom förvaradt är ett svart mörker, till evig tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Ty de tala stolt ord, som äro fåfäng: och igenom otukt locka dem till köttslig lusta, som rättsliga undsluppne voro, och ännu vandra i villfarelse;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Och lofva dem frihet, ändock de sjelfve äro förderfvelsens tjenare; ty af hvem någor öfvervunnen varder, hans tjenare är han vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Ty sedan de, genom Herrans och Frälsarens Jesu Christi kunskap, undflytt hafva verldenes orenlighet, och hafva åter bevefvat sig deruti, och äro öfvervunne, är dem det yttersta värre vordet än det första.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Och hade dem bättre varit intet förståndit rättfärdighetenes väg, än, sedan de förstodo, vända sig ifrå det helga budet, som de anammat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Dem är vederfaret det som för ett sant ordspråk plägar sägas: Hunden går åter till sina spyo; och svinet, som tvaget är, sölar sig åter i träcken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Detta är nu den andra Epistelen, som jag skrifver eder till, mine käreste, i hvilko jag uppväcker och förmanar edart rena sinne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Att I ihågkommen de ord, som tillförene sagd äro af de heliga Propheter; och desslikes vårt bud, vi som ärom Herrans och Frälsarens Apostlar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Och veter det i förstone, att i yttersta dagarna varda kommande bespottare, som vandra efter sin egen lusta;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Och säga: Hvar är nu det löfte om hans tillkommelse? Ty ifrå den dag fäderne äro afsomnade, blifver allt såsom det af kreaturens begynnelse varit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Men sjelfviljande vilja de icke veta, att himlarna hafva ock varit i förtiden, och jorden af vattnet, och i vattnena bestånd haft, genom Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Likväl vardt på den tid verlden, genom de samma, med flodene förderfvad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Sammalunda ock nu himlarna och jorden varda genom hans ord sparde, att de skola varda eldenom förvarade till domedag, då de ogudaktiga menniskor fördömas skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Men ett skall eder icke fördoldt vara, mine käreste, att en dag för Herranom är såsom tusende år, och tusende år såsom en dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Herren fördröjer intet sitt löfte, såsom somlige mena det vara fördröjelse; men han hafver tålamod med oss, och vill icke att någre skola förgås, utan att hvar och en vänder sig till bättring.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Men Herrans dag varder kommandes såsom en tjuf om natten; och då skola himlarna med en stor hastighet förgås, och elementen skola försmälta af hetta, och jorden, med de verk, som derpå äro, skola afbrännas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Efter nu allt detta skall förgås, hurudana bör eder då vara, uti helig umgängelse och Gudaktighet?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Så att I vänten och åstunden efter Guds dags tillkommelse; i hvilkom himlarna af eld förgås skola, och elementen försmälta af hetta.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Men nya himlar och en ny jord väntom vi, efter hans löfte, der rättfärdighet uti bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Derföre, mine käreste, medan I detta vänten, så lägger eder vinning om att I obesmittade och ostraffelige för honom finnas mågen i frid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Och vårs Herras Jesu Christi tålamod räkner för edra salighet; såsom ock vår käre broder, Paulus, efter den vishet som honom gifven är, hafver skrifvit eder till;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Såsom han ock i all bref talar om sådana stycker; ibland hvilka något är som är svårt till förstå, det de olärde och lösaktige förvärra, såsom ock andra skrifter, till sin egen förtappelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Men I, mine käreste, medan I veten det tillförene, så förvarer eder, att I icke förförde varden genom de ogudaktigas villfarelse, samt med dem, och fallen ifrå eder egen stadighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Utan växer i nådene, och vårs Herras och Frälsares Jesu Christi kunskap. Honom vare ära, nu och till evig tid. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Det som var af begynnelsen, det vi hafve hört, det vi hafve sett med vår ögon, det vi hafve beskådat, och våra händer handterat hafva, af lifsens ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Och lifvet är uppenbaradt, och vi hafve sett, och vittnom, och kungörom eder det eviga lifvet, hvilket var när Fadren, och är oss uppenbaradt;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Hvad vi hafve sett och hört, det förkunnom vi eder, på det ock I skolen hafva sällskap med oss, och vårt sällskap skall vara med Fadrenom, och hans Son Jesu Christo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Och detta skrifve vi eder, på det edor glädje skall vara fullkommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Och det är bebådelsen, som vi hafve hört af honom, och förkunnom eder, att Gud är ett ljus, och intet mörker är i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Om vi säge oss hafva sällskap med honom, och vandrom i mörkret, då ljugom vi och görom icke sanningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Men vandrom vi i ljuset, såsom han är i ljuset; då hafve vi sällskap inbördes, och Jesu Christi, hans Sons, blod renar oss af alla synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Säge vi, att vi hafve ingen synd, då bedrage vi oss sjelfva, och sanningen är icke i oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Men om vi bekänne våra synder, han är trofast och rättvis, att han förlåter oss synderna, och renar oss af alla orättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Men säge vi, att vi hafve intet syndat, då göre vi honom till ljugare, och hans ord är icke i oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Min barn, detta skrifver jag eder, att I skolen icke synda; och om någor syndar, då hafve vi en försvarare när Fadrenom, Jesum Christum, den rättfärdig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Och han är försoningen för våra synder; icke allenast för våra, utan ock för hela verldenes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Och derpå vete vi att vi kännom honom, om vi hålle hans bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Den der säger: Jag känner honom, och håller icke hans bud, han är en ljugare, och i honom är icke sanningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Men den som håller hans ord, i honom är sannerliga Guds kärlek fullkomligen; och derpå vete vi att vi ärom i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Den der säger sig blifva i honom, han skall ock vandra såsom han vandrade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Bröder, jag skrifver eder intet nytt bud; utan det gamla budet, som I haft hafven af begynnelsen. Det gamla budet är det ord, som I hafven hört af begynnelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Åter skrifver jag eder ett nytt bud, det sant är i honom, och i eder; ty mörkret är förgånget, och det sanna ljuset lyser nu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Den som säger sig vara i ljuset, och hatar sin broder, han är ännu i mörkret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Den der älskar sin broder, han blifver i ljuset, och ingen förargelse är i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Men den som hatar sin broder, han är i mörkret, och vandrar i mörkret, och vet icke hvart han går; ty mörkret hafver förblindat hans ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Jag skrifver eder, kära barn, att eder skola synderna förlåtna varda, för hans Namns skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Jag skrifver eder, I fäder; ty I hafven känt honom, som är af begynnelsen. Jag skrifver eder, I ynglingar; ty I hafven öfvervunnit den onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Jag skrifver eder, I barn; ty I hafven känt Fadren. Jag hafver skrifvit eder, I fäder; ty I hafven känt honom, som är af begynnelsen. Jag hafver skrifvit eder, I ynglingar; ty I ären starke; och Guds ord blifver i eder, och hafven öfvervunnit den onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Älsker icke verldena, icke heller de ting i verldene äro. Den der älskar verldena, i honom är icke Fadrens kärlek.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Ty allt det som är i verldene, nämliga köttsens begärelse, och ögonens begärelse, och högfärdigt lefverne, det är icke af Fadrenom, utan af verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Och verlden förgås, och hennes lusta; men den som gör Guds vilja, han blifver evinnerliga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Käre barn, nu är den ytterste tiden, och såsom I hafven hört, att Antichrist skall komma; ja, nu äro allaredo månge Antichrister vordne, och deraf vete vi att den ytterste tiden är nu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'De äro utgångne af oss; men de voro icke af oss. Hade de varit af oss, då hade de ju blifvit när oss; men på det de skulle blifva uppenbare, att de äro icke alle af oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Men I hafven smörjelse af dem Heliga, och veten allt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Jag hafver icke skrifvit till eder, såsom till dem der icke veta sanningen; utan såsom till dem som henne veta, och att all lögn icke är af sanningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Ho är en ljugare, utan den som nekar, att Jesus är Christus? Den är Antichrist, som nekar Fadren och Sonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Hvar och en som nekar Sonen, han hafver icke heller Fadren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Hvad I nu hört hafven af begynnelsen, det blifve i eder; om det blifver i eder, som I hört hafven af begynnelsen, så skolen ock I blifva i Sonenom och Fadrenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Och detta är det löfte, som han oss lofvat hafver, evinnerligit lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Detta hafver jag skrifvit till eder, om dem som förföra eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Och den smörjelse, som I hafven fått af honom, blifver i eder; och I behöfven icke att någon lärer eder; utan såsom smörjelsen lärer eder om all ting, så är det sant, och icke lögn; och som hon hafver lärt eder, så blifver i henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Och nu, kära barn, blifver i honom; att när han uppenbarad varder, måge vi hafva förtröstning, och icke komma på skam för honom i hans tillkommelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Om I veten att han är rättfärdig, så skolen I ock det veta, att hvar och en som rätt gör, han är född af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Ser till hurudana kärlek Fadren hafver bevist oss, att vi kallas Guds barn; fördenskull känner intet verlden eder; ty hon känner intet honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Mine käreste, vi äre nu Guds barn, och det är än icke uppenbaradt hvad vi varda skole; men det vete vi, när han blifver uppenbar, då vardom vi honom like; ty vi få se honom såsom han är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Och hvar och en som hafver detta hopp i honom, han renar sig, såsom han ock ren är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Hvar och en som gör synd, han gör ock orätt, och synd är orätt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Och I veten att han var uppenbarad, på det han skulle borttaga våra synder; och ingen synd är i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Hvar och en som blifver i honom, han syndar icke; hvar och en som syndar, han hafver icke sett honom, icke heller känt honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Kära barn, låter ingen bedraga eder. Den som gör rätt, han är rättfärdig, såsom ock han rättfärdig är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Den der gör synd, han är af djefvulen; ty djefvulen syndar af begynnelsen; och fördenskull uppenbarades Guds Son, att han skulle nederslå djefvulens gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Hvar och en, som född är af Gudi, han gör icke synd; ty hans säd blifver i honom; och han kan icke synda, ty han är född af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Derpå känner man, hvilke Guds barn, eller hvilke djefvulens barn äro; hvar och en som icke gör rätt, han är icke af Gudi; och den som icke älskar sin broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Ty detta är det budskap, som I hafven hört af begynnelsen, att vi skole älskas inbördes;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Icke såsom Cain, som var af dem onda, och slog sin broder ihjäl. Och för hvars skull slog han honom ihjäl? Ty hans gerningar voro onda; men hans broders gerningar rättfärdiga.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Förundrer icke, mine bröder, om verlden hatar eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Vi vete, att vi ärom förde ifrå döden till lifvet; ty vi älskom bröderna. Den der icke älskar brodren, han blifver i dödenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Hvar och en som hatar sin broder, han är en mandråpare; och I veten, att hvar och en mandråpare hafver icke evinnerligit lif blifvandes i sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Derpå kännom vi Guds kärlek, att han hafver låtit sitt lif för oss; och skolom ock vi låta vårt lif för bröderna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Den som hafver denna verlds gods, och ser sin broder vara nödställd, och sluter sitt hjerta till för honom, huru blifver Guds kärlek i honom?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Min barn, älskoms icke med ordom, eller med tungone, utan med gerning och sanning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Deraf vete vi, att vi ärom af sanningene, och kunnom stilla vår hjerta för honom;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Att om vårt hjerta fördömer oss, då är Gud större än vårt hjerta, och vet all ting.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Mine käreste, om vårt hjerta fördömer oss icke, då hafve vi en förtröstning till Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'Att vi få af honom allt det vi bedje; ty vi hållom hans bud, och görom det honom ljuft är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Och detta är hans bud, att vi skolom tro på hans Sons, Jesu Christi, Namn; och älska oss inbördes, såsom han oss budit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Och den der håller hans bud, han blifver i honom, och han i honom; och deraf vete vi, att han blifver i oss, af Andanom som han oss gifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Mine käreste, I skolen icke tro hvar och en anda; utan pröfver andarna, om de äro af Gudi; ty månge falske Propheter äro utgångne i verldena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Derpå skolen I känna Guds Anda; hvar och en ande, som bekänner att Jesus Christus är kommen i köttet, han är af Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Och hvar och en ande, som icke bekänner att Jesus Christus är kommen i köttet, han är icke af Gudi; och det är Antichrists (ande), af hvilkom I hafven hört att han skulle komma, och är nu allaredo i verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Kära barn, I ären af Gudi, och hafven öfvervunnit dem; ty den som är i eder, han är större än den som är i verldene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'De äro af verldene; derföre tala de af verldene, och verlden hörer dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Vi ärom af Gudi. Den som känner Gud, han hörer oss; den som icke är af Gudi, han hörer oss intet. Deraf känne vi sanningenes Anda, och villones anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Mine käreste, älskom oss inbördes; ty kärleken är af Gudi, och hvar och en som älskar, han är född af Gudi, och känner Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Den som icke älskar, han känner icke Gud; ty Gud är kärleken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Derpå är Guds kärlek till oss uppenbar vorden, att Gud hafver sändt sin enda Son i verldena, att vi skolom lefva genom honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Deruti står kärleken; icke det vi hafvom älskat Gud; men det han hafver älskat oss, och sändt sin Son till en försoning för våra synder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Mine käreste, hafver Gud så älskat oss, så skolom ock vi älskas inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Ingen hafver någon tid sett Gud; om vi älskoms inbördes, så blifver Gud i oss, och hans kärlek är fullkommen i oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Derpå kännom vi, att vi blifvom i honom, och han i oss, att han hafver gifvit oss af sinom Anda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Och vi sågom och betygom, att Fadren hafver sändt Sonen, verldene till en Frälsare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Hvar och en som bekänner, att Jesus är Guds Son, i honom blifver Gud, och han i Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Och vi hafve känt och trott den kärlek, som Gud hafver till oss. Gud är kärleken; och den som blifver i kärlekenom, han blifver i Gudi, och Gud i honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Derpå är kärleken fullkommen med oss, att vi mågom hafva en förtröstning på domedag; ty såsom han är, så ärom ock vi i denna verld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Räddhåge är icke i kärlekenom; utan fullkommelig kärlek utdrifver räddhågan; ty räddhågan hafver pino; men den der rädes, han är icke fullkommen i kärlekenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Älskom honom, ty han hafver först älskat oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Om någor säger: Jag älskar Gud, och hatar sin broder, han är en ljugare. Ty den der icke älskar sin broder, som han ser, huru kan han älska Gud, som han icke ser?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Och detta budet hafve vi af honom, att den der älskar Gud, han skall ock älska sin broder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Hvar och en som tror, att Jesus är Christus, han är född af Gudi; och hvar och en som älskar honom som födde, han älskar ock den som födder är af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Derpå vete vi, att vi älskom Guds barn, när vi älskom Gud, och hållom hans bud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Ty det är kärleken till Gud, att vi hållom hans bud; och hans bud äro icke svår.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Ty allt det som är födt af Gudi, det öfvervinner verldena; och denne är segren, som öfvervinner verldena, vår tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Men ho är den som öfvervinner verldena, utan den som tror, att Jesus är Guds Son?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Denne är den som kommer med vatten och blod, Jesus Christus, icke med vatten allena, utan med vatten och blod; och Anden är den som betygar, att Anden är sanningen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Ty tre äro som vittna i himmelen, Fadren, Ordet och den Helge Ande, och de tre äro ett.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Och tre äro de som vittna på jordene, Anden, Vattnet och Blodet; och de tre äro till ett.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Hvar vi nu anamme menniskors vittnesbörd, Guds vittnesbörd är större; ty detta är Guds vittnesbörd, som han vittnade om sin Son:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Den der tror på Guds Son, han hafver vittnesbörd i sig sjelfvom; den der icke tror Gudi, han gör honom till en ljugare; ty han icke trodde det vittnesbörd, som Gud vittnade om sin Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Och det är vittnesbördet, att Gud oss gifvit hafver det eviga lifvet; och det lifvet är i hans Son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Den Sonen hafver, han hafver lifvet; den icke hafver Guds Son, han hafver icke lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Detta hafver jag skrifvit eder, som tron i Guds Sons Namn; på det I skolen veta, att I hafven evinnerligit lif; och på det I skolen tro i Guds Sons Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Och detta är den förtröstning, som vi hafve till honom, att om vi bedje något efter hans vilja, så hörer han oss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Och efter vi vete, att han hörer oss, ehvad vi bedje, så vete vi att vi de böner hafve, som vi hafvom bedit af honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Hvar någor ser sin broder synda någon synd, icke till döds, han må bedja, så skall han gifva dem lifvet, som synda icke till döds. Det är en synd till döds; för sådana säger jag icke att någor bedja skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'All orätt är synd; är ock somlig synd icke till döds.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Vi vete, att den af Gudi född är, han syndar icke; utan den som född är af Gudi, han förvarar sig, och den onde kommer icke vid honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Vi vete, att vi ärom af Gudi, och hela verlden är stadd i det onda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Men vi vete, att Guds Son är kommen, och hafver gifvit oss sinne, att vi kännom den Sanna, och ärom i den Sanna, i hans Son Jesu Christo; denne är sanner Gud, och det eviga lifvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Kära barn, vakter eder för afgudarna. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Den äldste, den utvalda Frune, och hennes barn, hvilken jag älskar i sanningen; och icke jag allenast, utan ock alle som sanningen känt hafva;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'För sanningens skull, som i oss blifver, och med oss vara skall i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Nåd, barmhertighet, frid af Gud Fader, och af Herranom Jesu Christo, Fadrens Son, i sanningene, och i kärlekenom, vare med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Jag är mycket glad, att jag hafver funnit ibland din barn de der vandra i sanningene; såsom vi budet af Fadrenom fått hafve.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Och nu beder jag dig, Fru; icke skrifver jag dig såsom ett nytt bud, utan det vi hadom af begynnelsen, att vi skolom älska oss inbördes.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Och detta är kärleken, att vi vandrom efter hans bud. Detta är budet, som I hört hafven af begynnelsen, att I vandren deruti.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Ty månge bedragare äro inkomne i verldena, de som icke bekänna Jesum Christum kommen vara i köttet; denne är bedragaren, och Antichrist.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Ser eder väl före, att vi icke borttappom det vi arbetat hafvom, utan att vi fåm full lön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Hvar och en som öfverträder, och icke blifver i Christi lärdom, han hafver ingen Gud; den der blifver i Christi lärdom, han hafver både Fadren och Sonen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Kommer någor till eder, och icke hafver denna lärdomen med sig, undfår honom icke i hus, och helser honom icke heller;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Ty den honom helsar, han är delaktig i hans onda gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Jag hafver väl mycket att skrifva eder, dock ville jag icke med papper eller bläck; utan jag hoppas att komma till eder, och muntliga tala med eder, på det vår glädje skall vara fullkommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Helsa dig dine utvalda systers barn. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Den äldste, dem älskeliga Gajo, den jag älskar i sanningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Min älskelige, jag önskar i all stycken att dig väl går, och du helbregda äst, såsom dine själ väl går.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Men jag var mycket glad, då bröderna kommo, och båro vittnesbörd om dine sanning, såsom du vandrar i sanningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Jag hafver ingen större fröjd än den, att jag hörer min barn vandra i sanningene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Min käreste, du gör troliga hvad som helst du gör emot bröderna, och de främmande;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Som om din kärlek betygat hafva inför församlingen; och du hafver väl gjort, att du hafver dem affordrat värdeliga för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Ty de äro utfarne för hans Namns skull, och hafva intet tagit af Hedningarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Så skole vi nu sådana undfå, på det vi sanningenes medhjelpare varda mågom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Jag hafver skrifvit församlingene; men Diotrephes, som ibland dem vill afhållen vara, anammar oss intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Derföre, när jag kommer, vill jag kungöra hans gerningar som han gör, och sqvallrar emot oss med ondom ordom, och låter sig icke dermed nöja; sjelf anammar han icke bröderna, och förmenar dem som det göra vilja, och drifver dem ut af församlingene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Min käreste, efterfölj icke det ondt är, utan det godt är; den der väl gör, han är af Gudi, och den der illa gör, han ser icke Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetrius hafver vittnesbörd af hvar man, och af sjelfva sanningene; och vi vittnom ock, och I veten, att vårt vittnesbörd sant är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Jag hade mycket till att skrifva; men jag ville icke med bläck och penna skrifva dig till.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Men jag hoppas snarliga få se dig, så vilje vi muntliga tala med hvarannan. Frid vare med dig. Vännerna helsa dig. Helsa du vännerna, hvar vid sitt namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, Jesu Christi tjenare, men Jacobs broder: dem kalladom, som i Gud Fader helgade äro, och i Jesu Christo behållne:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Mycken barmhertighet, och frid, och kärlek vare med eder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Mine käreste, efter det jag tog mig före skrifva eder till om allas våra salighet, syntes mig behöfvas förmana eder med skrifvelse, att I kämpa måtten för trona, som ena reso helgonen föregifven var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Ty det äro några menniskor med ibland inkomna, om hvilka fordom skrifvet var till detta straff: De äro ogudaktige, och draga vår Guds nåd till lösaktighet, och neka Gud, som allena är Herre, och vår Herra Jesum Christum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Men jag vill minna eder uppå, att I en tid detta skolen veta, att då Herren hade utfört folket af Egypten, sedan förgjorde han dem, som icke trodde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Och de Änglar, som icke behöllo sin förstadöme, utan öfvergåfvo sin hemman, dem förvarade han med eviga bojor i mörkret, till den stora dagsens dom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Såsom ock Sodoma och Gomorra, och de städer deromkring, hvilke i samma måtto som de i skörhet syndat hade, och hafva gångit efter främmande kött, de äro satte för ett efterdömelse, och lida evig eldspino;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Sammalunda ock desse drömmare, som besmitta köttet, förakta herrskapet, och försmäda majestätet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Men Michael, den Öfverängelen, då han trätte med djefvulen, och disputerade med honom om Mose kropp, torde han icke utsäga försmädelsens dom; utan sade: Herren straffe dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Men desse försmäda, der de intet af veta; och hvad de af naturen, som annor oskälig djur veta, deruti förderfva de sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Ve dem; ty de gå i Cains väg, och falla i Balaams villfarelse för löns skull, och förgås i Chore uppror.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Desse skamfläckar slösa af edra gåfvor utan fruktan, och föda sig sjelfva; de äro skyar utan vatten, som drifvas omkring af vädret; skallot, ofruktsam trä, två resor död, och med rötter uppryckt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Hafsens vilda vågor, som sin egen skam utskumma; villfarande stjernor, hvilkom det svarta mörkret förvaradt är i evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Hafver ock Enoch, den sjunde ifrån Adam, propheterat tillförene om dessa, och sagt: Si, Herren kommer med mång tusend helgon;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Till att sitta dom öfver alla, och straffa alla dem som ogudaktige äro, för alla deras ogudaktiga gerningar, med hvilka de hafva illa gjort; och för allt det hårda, som de ogudaktige syndare emot honom talat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Desse knorra och klaga alltid, och vandra efter sin egen lusta; och deras mun talar stolt ord, och akta på personer för nyttos skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Men I, mine käreste, drager eder till minnes de ord, som tillförene hafva eder sagd varit af vårs Herras Jesu Christi Apostlar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Att de sade eder: Uti yttersta dagarna skola komma bespottare, de der gå skola efter sin egen ogudaktiga begärelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Desse äro de, som parti göra, köttslige, icke hafvandes Andan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Men I, mine käreste, uppbygger eder sjelfva på edra aldraheligasta tro, genom den Helga Anda, och beder;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Och behåller eder i Guds kärlek, och vänter efter vårs Herras Jesu Christi barmhertighet till evigt lif.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Och håller denna åtskilnad, att I förbarmen eder öfver somliga;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Men somliga görer med fruktan saliga, och rycker dem utur elden; hatande den besmittada köttsens kjortel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Men honom, som förmår förvara eder utan synd, och ställa eder för sitt härlighets ansigte ostraffeliga, med fröjd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Allena visom Gudi, vårom Frälsare, vare ära, och majestät, och välde, och magt, nu och i alla evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Detta är Jesu Christi uppenbarelse, den Gud hafver gifvit honom, till att förkunna sinom tjenarom, hvad innan kort tid ske skall; och hafver betecknat och sändt, med sin Ängel, till sin tjenare Johannem;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Hvilken betygat hafver Guds ord och vittnesbörd om Jesu Christo, hvad han sett hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Salig är den som läs och hörer denna Propheties ord, och håller det deruti skrifvet är; ty tiden är när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johannes, de sju församlingar i Asien: Nåd vare med eder, och frid af honom som är, och som var, och som komma skall, och af de sju Andar som för hans stol äro;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Och af Jesu Christo, som är ett troget vittne, förstfödder ifrå de döda, och en Förste öfver Konungarna på jordene; den oss älskat hafver, och tvagit oss af våra synder med sitt blod;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'Och gjort oss till Konungar och Prester för Gudi, och sinom Fader. Honom vare ära och välde, ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Si, han kommer, med skyn, och all ögon skola se honom, och de honom stungit hafva, och all slägte på jordene skola jämra sig; ja, Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Jag är A och O, begynnelsen och änden, säger Herren, som är, som var, och som komma skall, den Allsmägtige.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Jag, Johannes, edar broder, och delaktig i bedröfvelsen, och i riket, och i Jesu Christi tålamod, var på den ön Pathmos, för Guds ords skull, och för Jesu Christi vittnesbörds skull.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Jag var i andanom, på en Söndag, och hörde efter mig en stor röst, såsom en basun;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Sägandes: Jag är A och O, den förste och den siste. Hvad du ser, det skrif uti ena bok, och sänd till de församlingar, som äro i Asien, i Epheso, och i Smirnen, och i Pergame, och i Thyatira, och i Sardis, och i Philadelphia, och i Laodicea.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Och jag vände mig om till att se efter rösten, som med mig talade; och som jag mig vände, såg jag sju gyldene ljusastakar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Och midt ibland de sju gyldene ljusastakar en, som lik var menniskones Son, klädd i en sid kjortel, och begjordad kring om bröstet med ett gyldene bälte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Men hans hufvud och hans hår var hvitt, som en hvit ull, och såsom snö; och hans ögon voro såsom en eldslåge.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Och hans fötter voro såsom glödande messing i ugnen, och hans röst såsom en dön af mycket vatten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Och han hade i sine högra hand sju stjernor, och af hans mun utgick ett skarpt tveeggadt svärd; och hans ansigte sken såsom klara solen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Och då jag såg honom, föll jag till hans fötter, såsom jag hade varit död; och han lade sin högra hand på mig, och sade till mig: Var icke förfärad; jag är den förste och den siste;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Och den lefvande; och jag var död, och si, jag är lefvandes, ifrån evighet till evighet: Amen; och hafver nycklarna till helvetet och döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Så skrif nu hvad du sett hafver, och hvad nu är, och hvad härefter ske skall;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Hemligheten af de sju stjernor, som du sett hafver i mine högra hand, och de sju gyldene ljusastakar: De sju stjernor äro de sju församlingars Änglar; och de sju ljusastakar, som du sett hafver, äro de sju församlingar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Och skrif den församlings Ängel i Epheso: Detta säger han, som hafver sju stjernor i sine högra hand, den der vandrar midt ibland de sju gyldene ljusastakar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Jag vet dina gerningar, och ditt arbete, och ditt tålamod, och att du icke må lida de onda, och hafver försökt dem som säga att de äro Apostlar, och äro dock icke, och hafver befunnit dem ljugare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Och du lider och hafver tålamod, och arbetar för mitt Namns skull, och är icke trött vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Men jag hafver emot dig, att du den första din kärlek öfvergifvit hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Betänk derföre hvaraf du fallen äst, och bättra dig, och gör de första gerningarna; hvar det icke sker, då varder jag dig snarliga kommandes, och skall bortstöta din ljusastaka af sitt rum, utan du bättrar dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Men detta hafver du, att du hatar de Nicolaiters verk, hvilka jag ock hatar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Den der öra hafver, han höre hvad Anden säger församlingarna: Den der vinner, honom vill jag gifva äta af lifsens trä, som är i Guds Paradis.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Och skrif den församlings Ängel i Smirnen: Detta säger den förste och den siste, den död var, och är lefvandes vorden:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Jag vet dina gerningar och din bedröfvelse, och din fattigdom (men du äst rik), och hädelse af dem som sig säga vara Judar, och äro icke, utan äro Satans hop.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Frukta intet för något, som du lida skall. Si, djefvulen skall kasta några af eder i fängelse, på det I skolen försökte varda, och hafva bedröfvelse i tio dagar. Var trofast intill döden, så skall jag gifva dig lifsens krono.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Den der öra hafver, han höre hvad Anden säger församlingarna. Den der vinner, han skall ingen skada få af den andra döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Och skrif den församlings Ängel i Pergamen: Detta säger han, som hafver det skarpa tveeggade svärdet:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Jag vet dina gerningar, och hvar du bor, att der Satans säte är; och du håller mitt Namn, och hafver icke nekat mina tro; och i de dagar är Antipas, mitt trogna vittne, dödader när eder, der Satan bor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Men jag hafver något litet emot dig; ty du hafver der dem, som hålla Balaams lärdom, hvilken lärde genom Balak åstadkomma förargelse för Israels barn, till att äta af det afgudom offradt var, och bedrifva boleri;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Så hafver du ock dem, som hålla de Nicolaiters lärdom, hvilket jag hatar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Bättra dig; annars skall jag dig snarliga komma, och skall strida med dem, med mins muns svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Den der öra hafver, han höre hvad Anden säger församlingarna. Den der vinner, honom vill jag gifva äta af det fördolda Manna, och vill gifva honom ett godt vittnesbörd, och med det vittnesbörd ett nytt namn beskrifvet, det ingen känner, utan den det får.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Ock skrif den församlings Ängel i Thyatira: Detta säger Guds Son, som ögon hafver såsom eldslåge, och hans fötter lika som messing;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Jag vet dina gerningar, och din kärlek, och dina tjenst, och dina tro, och ditt tålamod, och dina gerningar, de sista flere än de första.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Men jag hafver något litet emot dig, att du tillstädjer den qvinnan Jesabel, som säger att hon är en Prophetissa, lära och bedraga mina tjenare, bedrifva boleri, och äta af det afgudom offradt är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Och jag hafver gifvit henne tid, att hon skulle bättra sig af sitt boleri; och hon hafver intet bättrat sig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Si, jag skall lägga henne i sängena; och de som med henne hor bedrifva, skola komma uti aldrastörsta bedröfvelse, om de icke bättra sig af sina gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Och hennes barn skall jag dräpa; och alla församlingar skola veta, att jag är den som ransakar njurar och hjerta; och skall gifva hvarjom och enom af eder efter hans gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Men eder säger jag, och androm som i Thyatira ären, som icke hafva sådana lärdom, och icke hafva förstått Satans djuphet, såsom de säga: Jag skall icke lägga på eder några andra bördo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Dock hvad I hafven, det håller, så länge jag kommer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Och den der vinner, och håller min verk intill ändan, honom skall jag gifva magt öfver Hedningarna;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'Och han skall regera dem med jernris; och han skall sönderkrossa dem såsom en pottomakares käril;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'Såsom jag ock fått hafver af minom Fader, och vill gifva honom morgonstjernona.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Den der öra hafver, han höre hvad Anden säger församlingarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Skrif ock församlingenes Ängel i Sardis: Detta säger den, som hafver de sju Guds Andar, och de sju stjernor: Jag vet dina gerningar; ty du hafver namnet att du lefver, och äst död.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Var vaken, och stärk det andra som dö vill; ty jag hafver icke befunnit dina gerningar fullkomliga för Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Så tänk nu på hvad du fått och hört hafver, och håll det, och bättra dig; äst du icke vaken, så skall jag komma till dig som en tjuf plägar komma, och du skall icke veta på hvad stund jag kommer till dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Du hafver ock få namn i Sardis, som sin kläder icke besmittat hafva, och de skola vandra med mig i hvit kläder, ty de äro dess värde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Den som vinner, han skall klädder varda med hvit kläder; och jag skall icke utskrapa hans namn af lifsens bok; och jag skall vederkänna hans namn för min Fader, och för hans Änglar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Den der öra hafver, han höre hvad Anden säger församlingarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Skrif ock den församlings Ängel i Philadelphia: Detta säger den Helige, och den Sannfärdige, som hafver Davids nyckel, den der upplåter, och ingen menniska igenlåter; den der igenlåter, och ingen menniska upplåter;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Jag vet dina gerningar. Si, jag hafver gifvit dig en öppen dörr, och ingen kan låta henne igen; ty du hafver liten kraft, och du hafver hållit min ord, och hafver icke nekat mitt Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Si, jag vill gifva dig utu Satans hop; de sig säga vara Judar, och äro icke, utan ljuga. Si, jag vill drifva dem dertill, att de skola komma och tillbedja för dina fötter, och skola veta att jag hafver älskat dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Efter du hafver hållit mitt tålamods ord, skall jag ock bevara dig för frestelsens stund, hvilken tillstundar allo verldene, till att fresta dem som bo på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Si, jag kommer snarliga; håll det du hafver, att ingen tager dina krono.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Den der vinner, honom vill jag göra till en pelare uti mins Guds tempel, och han skall icke mer utgå; och jag skall skrifva på honom mins Guds Namn, och mins Guds stads, dess nya Jerusalems, namn, som nederkommer af himmelen ifrå min Gud, och mitt nya Namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Den der öra hafver, han höre hvad Anden säger församlingarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Skrif ock den församlings Ängel i Laodicea: Detta säger Amen, det trogna och sannfärdiga vittnet, begynnelsen till Guds kreatur:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Jag vet dina gerningar, att du äst hvarken kall eller varm; jag ville att du vore antingen kall, eller varm.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Men efter du äst ljum, och hvarken kall eller varm, skall jag dig utspy utu min mun.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Ty du säger: Jag är rik, och hafver nog, och behöfver intet; och vetst icke att du äst elände, och jämmerlig, fattig, och blind, och nakot.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Jag råder dig att du köper guld af mig, det genomeldadt och bepröfvadt är, att du må blifva rik; och hvit kläder, som du må kläda dig uti, på det dine nakenhets blygd icke skall synas; och smörj din ögon med ögnasalvo, att du må få se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'De jag älskar, dem agar jag och näpser. Så var nu flitig, och bättra dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Si, jag står för dörrene och klappar; den der hörer mina röst, och upplåter dörrena, till honom skall jag ingå, och hålla nattvard med honom, och han med mig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Den der vinner, honom skall jag sitta låta med mig på min stol, såsom ock jag vunnit hafver, och är sittandes vorden med minom Fader på hans stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Den der öra hafver, han höre hvad Anden säger församlingarna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Sedan såg jag, och si, en dörr vardt upplåten i himmelen; och den första rösten, som jag hörde, såsom en basun, med mig tala, sade: Stig här upp; jag vill visa dig, hvad ske skall härefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Och straxt var jag i Andanom; och si, en stol vardt satt i himmelen, och på stolen satt en.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Och den der satt, han var påseende såsom den stenen jaspis, och sardis; och en regnbåge var om stolen, påseendes såsom en smaragd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Och kringom stolen voro fyra och tjugu stolar; och på de stolar såto fyra och tjugu äldste, klädde med hvit kläder, och på deras hufvud voro gyldene kronor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Och af stolenom utgingo ljungeld, tordön och röster; och sju eldslampor brunno för stolen; hvilka äro de sju Guds Andar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Och framför stolen var såsom ett glashaf, likt vid christall; och midt i stolen, och kringom stolen, fyra djur full med ögon, både före och bak.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Och det första djuret var likt ett lejon; och det andra djuret likt enom kalf; och det tredje djuret hade ett ansigte såsom en menniska; och det fjerde djuret likt enom flygande örn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Och de fyra djur hade hvartdera sex vingar allt omkring, och de voro innantill full med ögon, och hade ingen ro dag eller natt, och sade: Helig, Helig, Helig är Herren Gud allsmägtig, som var, och som är, och som komma skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Och då de djuren gåfvo honom pris, och äro, och tack, som satt på stolen, den der lefver ifrån evighet till evighet,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Föllo de fyra och tjugu äldste framför honom, som satt på stolen, och tillbådo den der lefver ifrån evighet till evighet; och kastade sina kronor för stolen, och sade:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Herre, du äst värdig taga pris, och äro, och kraft; ty du hafver skapat all ting, och för din viljas skull hafva de varelse, och äro skapt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Och jag såg i hans högra hand, som satt på stolen, ena bok skrifven innan och utan, beseglad med sju insegel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Och jag såg en stark Ängel, som predikade med höga röst: Ho är värdig upplåta bokena, och uppbryta hennes insegel?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Och ingen i himmelen, eller på jordene, eller under jordene, kunde upplåta bokena, och icke heller se på henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Och jag gret svårliga, att ingen vardt funnen värdig till att upplåta bokena, och läsa henne, eller se på henne;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Och en af de äldsta sade till mig: Gråt icke. Si, Lejonet af Juda slägte, Davids rot, hafver vunnit till att upplåta bokena, och uppbryta hennes sju insegel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Och jag såg, och si, midt i stolen, och ibland de fyra djuren, och midt ibland de äldsta stod ett Lamb, såsom det hade slagtadt varit, och hade sju horn, och sju ögon, hvilka äro de sju Guds Andar sände i all land.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Och det kom, och tog bokena utaf hans högra hand, som satt på stolen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Och då det hade tagit bokena, föllo de fyra djur, och de fyra och tjugu äldste framför Lambet, hafvande hvar och en harpor och gyldene skålar fulla med rökverk, hvilket är de heligas böner;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Och söngo en ny sång, och sade: Du äst värdig att taga bokena, och upplåta hennes insegel; ty du äst dödad, och hafver igenlöst oss Gudi med ditt blod, af allahanda slägte och tungomål, och folk och Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Och hafver gjort oss vårom Gudi till Konungar och Prester; och vi skole regnera på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Och jag såg, och hörde en röst af många Änglar, kringom stolen och kringom djuren, och kringom de äldsta, och talet på dem var mång sinom tusende tusend;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Sägande med höga röst: Lambet, som dödadt är, det är värdigt att hafva kraft, och rikedom, och visdom, och starkhet, och äro, och pris, och lof.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Och all kreatur, som i himmelen äro, och de på jordene, och de under jordene, och i hafvet, och allt det uti dem är, hörde jag säga till honom, som satt på stolen, och till Lambet: Lof, och ära, och pris, och kraft, ifrån evighet till evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Och de fyra djuren sade: Amen; och de fyra och tjugu äldste föllo ned (på sin ansigte), och tillbådo honom, som lefver ifrån evighet till evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Och jag såg, att Lambet uppbröt ett af inseglen, och jag hörde ett af de fyra djuren säga, såsom med tordönsröst: Kom, och se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Och jag såg, och si, en hvit häst; och den derpå satt, hade en båga, och honom vardt gifven en krona; och han for ut till att vinna, och få seger.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Och då det uppbröt det andra inseglet, hörde jag det andra djuret säga: Kom, och se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Och der utgick en annar häst, röd; och honom, som derpå satt, vardt gifvet att han skulle borttaga friden af jordene, och att de skulle slå sig ihjäl inbördes; och honom vardt gifvet ett stort svärd.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Och då det uppbröt det tredje inseglet, hörde jag det tredje djuret säga: Kom, och se. Och jag såg, och si, en svart häst; och den der satt på honom hade ena vågskål i sine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Och jag hörde ena röst midt ibland de fyra djur, sägandes: Ett mått hvete om en penning, och tre mått bjugg om en penning; och oljone och vinet gör ingen skada.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Och då det uppbröt det fjerde inseglet, hörde jag dess fjerde djursens röst säga: Kom, och se.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Och jag såg, och si, en black häst; och den som på honom satt, hans namn var döden, och helvetet följde honom efter; och dem vardt magt gifven öfver fjerde parten på jordene, att döda med svärd, och med hunger, och med döden af de vilddjur på jordene äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Och då det uppbröt det femte inseglet, såg jag, under altaret, deras själar, som dödade voro för Guds ords skull, och för det vittnesbörds skull, som de hade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Och de ropade med höga röst, och sade: Herre, du som äst helig och sannfärdig, huru länge dömer du icke, och hämnas icke vårt blod på dem, som bo på jordene?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Och dem vardt gifvet hvarjom och enom ett sidt hvitt kläde, och till dem vardt sagdt, att de skulle ännu hvilas en liten tid, till dess talet blefve fullt af deras medtjenare och bröder, de der ock skola dödade varda, såsom ock de.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Och jag såg, att det uppbröt det sjette inseglet; och si, då vardt en stor jordbäfning, och solen vardt svart som en hårsäck, och månen vardt alltsammans såsom blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Och stjernorna föllo af himmelen ned på jordena, såsom fikonaträt sin fikon nedersläpper, då det ristes af stort väder.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Och himmelen gick bort, såsom en tillslagen bok; och all berg och öar vordo rörd af sitt rum.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Och Konungarna på jordene, och de öfverste, och rike, och höfvitsmän, och väldige och alle tjenare, och alle frie, fördolde sig uti jordkulor, och i bergskrefvor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Och sade till berg och klippor: Faller öfver oss, och skyler oss för hans ansigte, som sitter på stolen, och för Lambsens vrede;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Ty den store hans vredes dag är kommen; och ho kan bestå?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Sedan såg jag fyra Änglar stå på fyra jordenes hörn, hållande fyra jordenes väder, att intet väder skulle blåsa på jordena, eller på hafvet, eller på något trä.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Och jag såg en annan Ängel uppstiga ifrå solens uppgång; han hade lefvandes Guds insegel, och ropade med höga röst till de fyra Änglar, hvilkom gifvet var skada göra jordene och hafvena;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Och sade: Görer icke jordene skada, eller hafvena, eller trän, så länge vi med insegel tecknom vår Guds tjenare på deras anlete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Och jag hörde talet på dem, som tecknade voro, hundrade fyra och fyratio tusend, som tecknade voro, af all Israels barnas slägter:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Af Juda slägte tolftusend tecknade; af Rubens slägte tolftusend tecknade; af Gads slägte tolftusend tecknade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Af Assers slägte tolftusend tecknade; af Nephthali slägte tolftusend tecknade; af Manasse slägte tolftusend tecknade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Af Simeons slägte tolftusend tecknade; af Levi slägte tolftusend tecknade; af Isaschars slägte tolftusend tecknade;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Af Zabulons slägte tolftusend tecknade; af Josephs slägte tolftusend tecknade; af BenJamins slägte tolftusend tecknade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Sedan såg jag, och si, en stor skare, den ingen räkna kunde, af allom Hedningom, och slägtom, och folkom, och tungomålom, ståndande för stolen, och för Lambena, klädd i sid hvit kläder, och palmer i deras händer;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'Och de ropade med höga röst, och sade: Salighet honom, som sitter på stolen, vårom Gudi och Lambena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Och alle Änglar stodo kringom stolen, och om de äldsta, och om de fyra djuren, och föllo på sin ansigte framför stolen, och tillbådo Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Och sade: Amen, lof, och ära, och vishet, och tack, och pris, och kraft, och starkhet vare vårom Gud, ifrån evighet till evighet. Amen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Och en af de äldsta svarade, och sade till mig: Ho äro desse, som uti de sida hvita kläder klädde äro? Och hvadan äro de komne?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Och jag sade till honom: Herre, du vetst det. Och han sade till mig: Desse äro de som komne äro utu stor bedröfvelse, och hafva tvagit sin kläder, och gjort dem hvit i Lambsens blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Derföre äro de för Guds stol, och tjena honom dag och natt uti hans tempel; och den på stolen sitter, skall bo öfver dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'De skola intet mer hungra, eller törsta; icke heller skall solen falla på dem, icke heller någon hette;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Ty Lambet, som midt i stolen är, skall regera dem, och leda dem till lefvande vattukällor; och Gud skall aftorka alla tårar af deras ögon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Och då det uppbröt det sjunde inseglet, vardt en tysta i himmelen vid en half stund.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Och jag såg sju Änglar stå för Gud, och dem vordo gifne sju basuner.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Och en annar Ängel kom, och stod för altaret, och hade ett gyldene rökelsekar; och honom vardt gifvet mycket rökverk, på det han skulle gifva till all helgons böner på gyldene altaret, som är för stolenom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Och rökverksens rök, af helgonens böner, gick upp af Ängelens hand för Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Och Ängelen tog rökelsekaret, och uppfyllde det med eld af altaret, och kastade ned på jordena; och der skedde tordön, röster, och ljungeld, och jordbäfning.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Och de sju Änglar, med de sju basuner, skickade sig till att basuna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Och den förste Ängelen basunade; och vardt ett hagel och eld, bemängdt med blod, och det vardt kastadt på jordena; och tredjeparten af trän vardt uppbränd, och allt grönt gräs brann upp.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Och den andre Ängelen basunade; och uti hafvet vardt kastadt såsom ett stort brinnande berg, och tredjeparten af hafvet vardt blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'Och tredjeparten af de lefvande kreatur, som i hafvet voro, blefvo döde; och tredjeparten af skeppen förgingos.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Och den tredje Ängelen basunade; och en stor stjerna föll ned af himmelen, brinnandes som ett bloss; och föll uti tredjeparten af älfverna, och uti vattukällorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Och stjernones namn kallas malört; och tredjeparten vändes i malört, och många menniskor blefvo döda af vattnet, som förbittradt vardt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Och den fjerde Ängelen basunade; och tredje parten af solene vardt slagen, och tredjeparten af månan, och tredjeparten af stjernorna, så att tredjeparten af dem vardt förmörkrad, och tredjedelen af dagen intet skina kunde, och af nattene sammalunda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Och jag såg, och hörde en Ängel, som flög midt igenom himmelen, och sade med höga röst: Ve, ve, ve dem som bo på jordene, för de andra röster af de tre Änglars basuner, som ännu basuna skola.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Och den femte Ängelen basunade; och jag såg ena stjerno falla af himmelen på jordena; och honom vardt gifven nyckelen till afgrundens brunn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Och han upplät afgrundens brunn, och der uppgick en rök, såsom af en stor ugn; och solen och vädret vordo förmörkrad af brunsens rök.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Och utu röken kommo gräshoppor på jordena; och dem vardt gifven magt, såsom scorpioner på jordene magt hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Och vardt sagdt till dem, att de icke skulle göra gräset på jordene skada, icke heller något det grönt var, icke heller något trä; utan allena menniskorna, de som icke hade Guds tecken i sin anlete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Och dem vardt gifvet, att de icke skulle döda dem; utan att de skulle qvälja dem i fem månader; och deras qval var såsom qval af scorpion, då han hafver stungit menniskorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Och i de dagar skola menniskorna söka efter döden, och skola icke finna honom, och de skola begära dö, och döden skall fly ifrån dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Och de gräshoppor äro lika de hästar, som till krigs beredde äro, och på deras hufvud såsom kronor gulde lika, och deras ansigte såsom menniskors ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Och de hade hår såsom qvinnohår, och deras tänder voro såsom lejons;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Och hade pansar såsom jernpansar, och bullret af deras vingar såsom vagnsbuller, der månge hästar löpa till krigs;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Och hade stjertar såsom scorpioner, och gaddar voro i deras stjertar; och deras magt var till att qvälja menniskorna i fem månader;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Och hade öfver sig en Konung, en Ängel af afgrunden, hvilkens namn på Ebreisko heter Abaddon, på Grekisko Apollyon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Ett Ve är framfaret, och si, här komma ännu tu annor Ve efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Och den sjette Ängelen basunade, och jag hörde ena röst af de fyra hörn af det gyldene altaret, som är för Guds ögon:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Och sade till den sjette Ängelen, som basunen hade: Lös de fyra Änglar, som bundne äro uti den stora älfven Euphrates.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Och de fyra Änglar vordo löse, hvilke beredde voro till ena stund, till en dag, till en månad, och till ett år, att de skulle döda tredjeparten af menniskorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Och talet på det resigtyget var mång sinom tusende tusend, och jag hörde deras tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Och så såg jag ock hästarna i synene, och de som såto på dem, de hade glödande, gula, och svafvelspansar; och hufvuden på hästarna voro såsom lejonahufvud; och af deras mun utgick eld, och rök, och svafvel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Af dessa tre plågor vardt dödad tredjeparten af menniskorna, af elden, och röken, och svallet, som utaf deras mun gick.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Ty deras magt var i deras mun, och i deras stjertar; och stjertarne voro ormom like, och hade hufvud, der de skada med gjorde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Och voro ännu menniskor, som icke voro dödade af dessa plågor, och icke bättrade sig af sina händers verk; att de icke tillbådo djefvulskap, och afgudar af guld, silfver, koppar, sten och trä, de der hvarken se kunna, eller höra, eller gå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Och icke gjorde bot för sitt mord, trolldom, skörhet och tjufveri.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Och jag såg en annan stark Ängel nederkomma af himmelen; han var klädd med en sky, och en regnbåge öfver hans hufvud, och hans ansigte såsom solen, och hans fötter såsom eldspelare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Och han hade i sine hand en öppen bok; och han satte sin högra fot på hafvet, och den vänstra på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'Och ropade med höga röst, som ett rytande lejon. Och då han ropade, talade sju tordöner sina röster.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Och då de sju tordöner talat hade sina röster, ville jag skrifvit dem; då hörde jag ena röst af himmelen säga till mig: Besegla det de sju tordöner talat hafva, och skrif det intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Och Ängelen, som jag såg stå på hafvet och på jordene, hof sina hand upp till himmelen,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'Och svor vid honom, som lefver ifrån evighet till evighet, den der himmelen skapat hafver och hvad deruti är, och jordena och hvad deruti är, och hafvet och hvad deruti är, att ingen tid skall vara mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Utan i de dagar, då den sjunde Ängelens röst höres, då han varder basunandes; då skall Guds hemlighet fullkomnad varda, såsom han förkunnat hade genom sina tjenare Propheterna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Och jag hörde åter ena röst af himmelen tala med mig, och säga: Gack, och tag den öppna bokena af Ängelens hand, som står på hafvet och på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Och jag gick till Ängelen, och sade till honom: Få mig bokena; och han sade till mig: Tag, och ät upp henne, och hon skall rifva dig i buken; men i din mun skall hon vara söt som hannog.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Och jag tog bokena af Ängelens hand, och åt henne upp, och hon vardt i min mun söt som hannog; och då jag hade ätit henne, ref hon mig i buken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Och han sade till mig: Du måste åter prophetera folkom, Hedningom, och tungomålom, och mångom Konungom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Och mig vardt fången en rö såsom en käpp, och mig vardt sagdt: Statt upp, och mäl Guds tempel och altare, och de som tillbedja derinne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Men den inra choren af templet kasta ut, och mäl honom intet; ty han är gifven Hedningomen, och de skola förtrampa den heliga staden, i två och fyratio månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Och jag skall gifva tu minom vittnom, och de skola prophetera i tusende, tu hundrade och sextio dagar, klädde i säckar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Desse äro tu oljoträ, och tu bloss, ståndande för jorderikes Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Och hvar någor ville göra dem skada, så går elden ut af deras mun, och förtärer deras fiendar; och hvar någor ville göra dem ondt, så måste han dödas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Desse hafva magt till att igenlycka himmelen, att intet regnar uti de dagar då de prophetera; och hafva magt öfver vattnet, att förvända det i blod, och slå jordena med allahanda plågo, så ofta de vilja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Och då de hafva lyktat sitt vittnesbörd, skall det vilddjuret, som uppstiger af afgrunden, hålla ena strid med dem, och skall öfvervinna dem, och döda dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Och deras lekamen skola blifva liggande på gatorna, i den stora staden, som heter andeliga Sodoma och Egypten, der vår Herre korsfäst är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Och skola någre af folken och slägterna, och tungomålen, och af Hedningarna, se deras lekamen i tre dagar och en half, och skola icke vilja tillstädja deras lekamen läggas i grafvar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Och de på jordene bo, skola fröjda sig öfver dem, och skola glädjas, och sända hvarandrom gåfvor; ty desse två Propheter tvingade dem som bo på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Och efter tre dagar och en half kom lifsens ande af Gudi uti dem, och de stodo på sina fötter; och en stor förskräckelse föll på dem som sågo dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Och de hörde en hög röst af himmelen säga till dem: Stiger hit upp. Och de stego upp i himmelen uti en sky, och deras ovänner sågo dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Och i samma stundene vardt en stor jordbäfning, och tionde delen af staden föll ned; och blefvo i jordbävningen dödade sjutusend menniskors namn; och de andre vordo förfärade, och gåfvo Gudi i himmelen pris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Det andra Ve gick öfver, och si, det tredje Ve kommer snart.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Och den sjunde Ängelen basunade, och i himmelen hördes höga röster, de der sade: Denna verldenes rike äro vordne vårs Herras och hans Christs, och han skall regnera af evighet till evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Och de fyra och tjugu äldste, som för Gudi på sina stolar såto, föllo på sin ansigte, och tillbådo Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Och sade: Vi tackom dig, Herre, allsmägtig Gud, du som äst, och varit hafver, och tillkommande äst; ty du hafver tagit dina stora kraft, och regnerar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Och Hedningarna äro vrede vordne; och din vrede är kommen, och de dödas tid, att de skola dömas, och att du skall löna dina tjenare Propheterna, och helgonen, och dem som frukta ditt Namn, små och stora, och förderfva dem som jordena förderfvat hafva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Och Guds tempel vardt upplåtet i himmelen, och hans Testaments ark vardt sedd i hans tempel, och der skedde ljungeld och röster, och tordöner, och jordbäfning, och stort hagel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Och i himmelen syntes ett stort tecken: En qvinna beklädd med solene, och månen under hennes fötter, och på hennes hufvud en krona af tolf stjernor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Och hon var hafvandes, ropade, och pintes med barn, och hade stort qval till att föda.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Och så syntes ett annat tecken i himmelen, och si, en stor röd drake, som hade sju hufvud och tio horn, och på hans hufvud sju kronor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Och hans stjert drog tredjeparten af himmelens stjernor, och kastade dem ned på jordena; och draken stod för qvinnone som föda skulle, på det, när hon födt hade, skulle han uppäta hennes barn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Och hon födde ett svenbarn, som regera skulle alla Hedningar med jernris; och hennes barn vardt borttaget till Gud, och till hans stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Och qvinnan flydde uti öknena, der hon rum hade, beredt af Gudi, att hon der föda skulle, i tusende, tuhundrade och sextio dagar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Och det vardt en stor strid i himmelen: Michael och hans Änglar stridde med drakan, och draken stridde och hans Änglar;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Och de vunno intet; och deras rum vardt icke mer funnet i himmelen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Och den store draken, den gamle ormen, den der heter djefvul och Satanas, vardt utkastad, den der bedrager hela verldena; och han vardt kastad på jordena, och hans änglar vordo ock bortkastade med honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Och jag hörde en stor röst, som sade i himmelen: Nu är vår Guds salighet, och kraft, och rike, och magt hans Christs vorden, efter våra bröders åklagare är förkastad, den dem åklagade för Gud, dag och natt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Och de vunno honom för Lambsens blods skull, och för dess vittnesbörds ords skull, och de hafva icke älskat sitt lif allt intill döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Derföre, glädjens, I himlar, och de som bo i dem. Ve dem som bo på jordene, och på hafvet; ty djefvulen stiger ned till eder, och hafver en stor vrede, vetandes att han icke lång tid hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Och då draken såg att han förkastad var på jordena, förföljde han qvinnona, som svenbarnet födt hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Och qvinnone vordo gifne två vingar, såsom af en stor örn; att hon skulle flyga uti öknena uti sitt rum, der hon födes en tid, och två tider, och en half tid, ifrån ormsens ansigte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Och ormen sputade utu sin mun vatten, såsom en ström, efter qvinnona; på det han skulle fördränka henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Men jorden halp qvinnone, och upplät sin mun, och uppsvalg strömmen, som draken af sin mun utsputat hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Och draken vardt vred på qvinnona, och gick bort, att han skulle örliga med de andra af hennes säd, de som hålla Guds bud, och hafva Jesu Christi vittnesbörd. Och han stod på hafsens sand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Och jag såg ett vilddjur uppstiga utu hafvet, det hade sju hufvud och tio horn, och på dess horn tio kronor, och på dess hufvud hädelsens namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Och vilddjuret, som jag såg, det var likt enom pardel, och dess fötter såsom björnafötter, och dess mun såsom lejons mun; och draken gaf thy sina kraft, och sin stol, och stora magt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Och jag såg ett af hans hufvud såsom sargadt till döds, och dess dödssår var igenläkt, och hela jorden förundrade sig på vilddjuret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Och de tillbådo drakan, som vilddjurena hade magt gifvit; och tillbådo vilddjuret, sägande: Ho är vilddjuret lik? Eller ho förmå strida emot thy?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Och thy vardt gifven en mun, till att tala stor ting och hädelse; och thy vardt gifven magt till att bruka sig i två och fyratio månader.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Och det upplyfte sin mun, till att tala hädelse emot Gud, till att häda hans Namn och hans tabernakel, och dem som bo i himmelen; och thy vardt medgifvet strida med helgonen, och vinna dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Och thy vardt gifven magt öfver all slägter, och tungomål, och Hedningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Och alle de som på jordene bo, tillbådo det, hvilkas namn icke skrifna äro i Lambsens lifs bok, hvilket dödadt är ifrå verldenes begynnelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Den der öra hafver, han höre.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Den der leder i fängelse, han skall gå i fängelse; den der dräper med svärd, han måste dödas med svärd. Här är de heligas tålamod och tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Och jag såg ett annat vilddjur uppstiga utu jordene; och det hade tu horn lika som Lambet; och det talade som drakan.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Och det gör alla dess första vilddjurets magt, i dess åsyn; och det kommer jordena, och dem derpå bo, till att tillbedja det första vilddjuret; hvilkets dödssår igenläkt var.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Och det gör stor tecken, så att det ock låter eld falla ned af himmelen på jordena, i menniskors åsyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Och det bedrager dem som bo på jordene, för de teckens skull, som thy gifna äro att göra för vilddjuret; sägandes till dem som bo på jordene, att de skola göra vilddjurena, som sargadt var af svärd, och var lefvande vordet, ett beläte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Och thy vardt gifvet, att det skulle gifva vilddjurets beläte anda, och att vilddjurets beläte skulle tala, och så beställat, att hvilke som helst icke tillbådo vilddjurets beläte, skulle dödas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Och det lät alla, små och stora, rika och fattiga, fria och tjenare, taga vedertecken uti deras högra hand, eller på deras anlete;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'Att ingen skall må köpa, eller sälja, utan den der hafver vedertecknet, eller vilddjurets namn, eller dess namns tal.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Här är visdomen: Den der förstånd hafver, han räkne vilddjurets tal; ty det är ens menniskos tal, och dess tal är sexhundrad sextio och sex.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Och jag såg, och si: Ett Lamb stod på Sions berg, och med thy hundrade fyra och fyratio tusend: de hade dess Faders Namn beskrifvet på sin anlete.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Och jag hörde ena röst af himmelen, såsom af ett stort vatten; och såsom ena röst af en stor tordön; och rösten, som jag hörde, var såsom harpolekares, de der lekte på sina harpor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Och de söngo såsom en ny sång för stolen, och för de fyra djuren, och för de äldsta; och ingen kunde lära den sången, utan de hundrade fyra och fyratio tusend, som köpte äro af jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Desse äro de, som med qvinnor icke besmittade äro, ty de äro jungfrur; desse äro de som följa Lambet, ehvart det går; desse äro köpte ifrå menniskorna, till en förstling Gudi, och Lambena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Och i deras mun är intet svek funnet; ty de äro utan smitto, för Guds stol.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Och jag såg en annan Ängel flyga midt genom himmelen; han hade ett evigt Evangelium, det han förkunna skulle dem som på jordene bo, och allom Hedningom, och slägtom, och tungomålom, och folkom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Och sade med höga röst: Frukter Gud, och gifver honom äro; ty stunden är kommen till hans dom, och tillbeder honom, som hafver gjort himmel och jord, hafvet och vattukällorna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Och en annar Ängel följde efter, och sade: Fallen, fallen är den store staden Babylon; ty han hafver dricka gifvit allom Hedningom af vredenes vin, sins boleris.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Och tredje Ängelen följde dem, och sade med höga röst: Hvar någor tillbeder vilddjuret, och dess beläte, och tager dess vedertecken på sitt anlete, eller på sin hand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'Han skall ock dricka af Guds vredes vin, det inskänkt och klart är i hans vredes kalk; och han skall varda plågad med eld och svafvel, i heliga Änglars åsyn, och i Lambsens åsyn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Och röken af deras plågo skall uppstiga af evighet till evighet; och de hafva hvarken dag eller natt ro, som tillbedja vilddjuret och dess beläte, och der någor tagit hafver dess namns vedertecken.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Här är de heligas tålamod; här äro de som hålla Guds bud och Jesu tro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Och jag hörde ena röst af himmelen säga till mig: Skrif: Salige äro de döde, som i Herranom dö, härefter; ja, Anden säger, att de skola hvila sig ifrå sitt arbete; ty deras gerningar följa dem efter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Och jag såg, och si en hvit sky; och på skynom satt en, som lik var menniskones Son, och hade på sitt hufvud en guldkrono, och i hans hand en hvass lia.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Och en annar Ängel kom utu templet, och ropade med höga röst till den, som satt på skynom: Hugg till med din lia, och skär; ty tiden är dig kommen, att du skall skära; ty säden på jordene är torr vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Och han, som satt på skyn, högg till med sin lia på jordena, och jorden vardt afskoren.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Och en annar Ängel kom utu templet, som i himmelen är, den ock en hvass lia hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Och en annar Ängel kom utur altaret, den magt hade öfver elden; och ropade med höga röst till honom, som hade den hvassa lian, och sade: Hugg till med din hvassa lia, och skär upp vinqvistarna på jordene; ty hennes vinbär äro mogen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Och Ängelen högg till med sin skarpa lia på jordena, och skar upp vingårdarna på jordene, och kastade dem uti Guds vredes stora präss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Och vardt prässen trampad utom staden; och blodet gick ut af prässen, allt intill betslen på hästarna, utöfver tusende sexhundrad stadier vägs.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Och jag såg ett annat tecken af himmelen, stort och underligit: Sju Änglar, som hade sju de yttersta plågor; ty med dem är fullkomnad Guds vrede.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Och jag såg såsom ett glashaf, beblandadt med eld, och dem stå på samma glashaf, som seger vunnit hade på vilddjuret, och dess beläte, och vedertecken, och på dess namns tal; och de hade Guds harpor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Och de söngo Mose, Guds tjenares, sång, och Lambsens sång, sägande: Stor och underlig äro din verk, Herre Gud allsvåldig; rättfärdige och sanne äro dine vägar, du helgonens Konung.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Ho skulle icke frukta dig, Herre, och prisa ditt Namn? Ty du äst allena helig, och alle Hedningar skola komma och tillbedja i din åsyn; ty dine domar äro uppenbare vordne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Sedan såg jag; och si, vittnesbördsens tabernakels tempel vardt öppnadt i himmelen;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Och gingo derut af templet de sju Änglar, som de sju plågor hade, klädde uti rent, hvitt linkläde, och omgjordade kringom bröstet med gyldene bälte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Och ett af de fyra djuren gaf de sju Änglar sju gyldene skålar, fulla med Guds vrede, den der lefver af evighet till evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Och templet vardt uppfyldt med rök af Guds härlighet, och af hans kraft; och ingen kunde gå in i templet, till dess de sju plågor, som de sju Änglar hade, fullkomnade vordo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Och jag hörde ena stora röst uti templet; den sade till de sju Änglar: Går, och utgjuter de Guds vredes skålar på jordena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Och den förste Ängelen gick åstad, och göt sina skål ut på jordena; och det vardt ett ondt och skadeligit sår på menniskomen, som vilddjurets vedertecken hade, och på dem som tillbådo dess beläte.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Och den andre Ängelen göt ut sina skål i hafvet; och det vardt såsom ens döds mans blod, och allt det lif hade i hafvet blef dödt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Och den tredje Ängelen göt ut sina skål i älfvena, och i vattukällorna; och det vardt blod.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Och jag hörde en Ängel säga: Rättfärdig äst du, Herre, som äst, och varit hafver, och helig, att du detta dömt hafver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Ty de hafva utgjutit helgonens och Propheternas blod, och blod hafver du ock gifvit dem dricka; ty de äro dess värde.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Och jag hörde en annan Ängel säga af altaret: Ja, Herre Gud allsvåldig, sanne och rätte äro dine domar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Och den fjerde Ängelen göt ut sina skål i solena; och honom vardt gifvet att plåga menniskorna med hetta af eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Och menniskorna vordo brinnande uti en stor hetta, och de hädde Guds Namn, som magten hade öfver dessa plågor; och gjorde inga syndabättring, att de måtte gifvit honom äro.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Och den femte Ängelen göt ut sina skål på vilddjurets stol; och dess rike vardt förmörkradt, och de sönderbeto sina tungor, för värks skull;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'Och hädde Gud i himmelen, för sin värk och sin sårs skull, och bättrade sig intet af sina gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Och den sjette Ängelen göt ut sina skål på den stora älfvena Euphrates; och dess vatten borttorkades; på det vägen skulle beredas för de Konungar östanefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Och jag såg utu drakans mun, och utu vilddjurets mun, och utu den falska Prophetens mun, utgå tre orena andar, såsom paddor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Och det äro djefvulsens andar, som tecken göra, och utgå till Konungarna på hela jordene, att församla dem till strids på den stora allsvåldiga Guds dag.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Si, jag kommer, som tjufven plägar komma; salig är den som vakar, och förvarar sin kläder, att han icke går naken, och de få se hans skam.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Och han församlade dem på ett rum, det heter på Ebreisko Armageddon.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Och den sjunde Ängelen göt ut sina skål i vädret; och gick en stor röst utaf himmelens tempel ifrå stolen, som sade: Det är gjordt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Och det vardt röster, och tordön, och ljungeld, och stor jordbäfning, sådana, att dess like icke varit hade, sedan menniskorna på jordene varit hade, sådana jordbäfning, så stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Och den store staden vardt i tre delar, och Hedningarnas städer föllo; och den store Babylon kom i åminnelse för Gudi, att han ville gifva honom kalken af sine grymma vredes vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Och alle öar flydde, och bergen funnos intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Och stort hagel, såsom en centener, kom ned af himmelen på menniskorna; och menniskorna hädde Gud, för den stora plåga af haglet; ty dess plåga var ganska stor.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Och kom en af de sju Änglar, som hade de sju skålar, och talade med mig, och sade till mig: Kom, jag vill visa dig den stora skökones fördömelse, som sitter på mycken vatten;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Med hvilka Konungarna på jordene bolat hafva; och de der på jordene bo, äro druckne vordne af hennes boleris vin.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Och han förde mig i Andanom uti öknena; och jag såg qvinnona sitta på ett rosenfärgo vilddjur, det var fullt med hädelsenamn, och hade sju hufvud och tio horn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Och qvinnan var klädd med purpur och rosenfärgo, och öfvergyld med guld, och ädla stenar, och perlor; och hade en gyldene kalk i sine hand, full med styggelse, och sins boleris orenlighet;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Och på hennes anlete skrifvet det namn, Hemlighet: Den store Babylon, modren till boleri, och till styggelse på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Och jag såg qvinnona druckna af helgonens blod, och af deras blod, som Jesu vittne voro; och jag förundrade mig storliga, då jag såg henne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Och Ängelen sade till mig: Hvi förundrar du dig? Jag vill säga dig hemligheten om denna qvinnone, och om vilddjuret, som bär henne, och hafver sju hufvud och tio horn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Vilddjuret, som du hafver sett, hafver varit, och är icke; och det skall åter uppkomma utaf afgrunden, och skall gå uti fördömelse; och de, som på jordene bo, skola förundra sig, hvilkas namn icke skrifna äro i lifsens bok, ifrå verldenes begynnelse; då de se vilddjuret, som hafver varit, och som icke är, ändock det är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Och här är sinnet, der visdom tillhörer; de sju hufvud äro sju berg, der qvinnan sitter uppå, och det äro sju Konungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Fem äro fallne; en är, och den andre är icke ännu kommen; och när han kommer, skall han icke länge blifva.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Och vilddjuret, som hafver varit, och icke är, den är den åttonde, och han är utaf de sju, och han går uti fördömelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Och de tio horn, som du sett hafver, äro tio Konungar, som ännu icke hafva fått rike, utan skola, såsom Konungar, på en stund få magt med vilddjuret.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Desse hafva alle ett råd, och skola gifva vilddjurena sina magt och kraft.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'De skola strida med Lambena, och Lambet skall vinna dem; ty det är en Herre öfver alla herrar, och en Konung öfver alla Konungar; och med thy äro de utkallade, och utkorade, och trogne.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Och han sade till mig: Vattnet, som du såg, der skökan sitter på, är folk och skarar, och Hedningar, och tungomål.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Och de tio horn, som du sett hafver på vilddjuret, skola hata skökona, och lägga henne öde och naken; och de skola uppäta hennes kött, och bränna henne upp i eld.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Ty Gud hafver gifvit dem i hjertat, att de skola göra det honom behagar, och göra alle ena mening, att de skulle gifva vilddjurena riket, till dess Guds ord varda fullkomnad.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Och qvinnan, som du sett hafver, är den store staden, som rike hafver öfver jordenes Konungar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Och sedan såg jag en annan Ängel komma neder af himmelen, den stora magt hade; och jorden vardt upplyst af hans klarhet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Och han ropade med magt och höga röst, sägandes: Fallen, fallen är den store Babylon, och är vorden djeflaboning, och alla orena andars behåll, och alla orena och ohyggeliga foglars behåll.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Ty alle Hedningar hafva druckit af vredenes vin, hennes boleris, och Konungarne på jordene hafva bolat med henne, och köpmännerne på jordene äro rike vordne af hennes stora vällust.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Och jag hörde ena andra röst af himmelen, som sade: I mitt folk, går ut ifrå henne, att I icke delaktige varden i hennes synder, och att I icke fån något af hennes plågor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Ty hennes synder räcka allt upp i himmelen, och Gud hafver dragit till minnes hennes orättfärdigheter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Betaler henne, såsom hon hafver betalat eder, och görer henne dubbelt efter hennes gerningar; och med samma kalk, som hon hafver inskänkt eder, inskänker henne dubbelt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Så mycket hon sig hafver härliga hållit och i vällust varit, så mycket inskänker henne pino och gråt; ty hon säger i sitt hjerta: Jag sitter och är en Drottning, och icke enka, och hafver ingen sorg.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Derföre skola hennes plågor komma på en dag, död, gråt, och hunger; och hon skall varda uppbränd i eld; ty Herren Gud är stark, som henne döma skall.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Och jordenes Konungar skola gråta henne, och beklaga sig öfver henne, de som med henne bolat, och i vällust lefvat hafva, då de få se röken af hennes brand;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Och skola stå långt ifrå, för hennes plågos räddhågas skull, och säga: Ve, ve den store staden Babylon, den starke staden; ty uti en stund är din dom kommen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Och köpmännerna på jordene skola gråta och sörja öfver henne, att ingen köper deras varor mer:');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Guld, och silfver, och ädla stenar, och perlor, och silke, och purpur, och skarlakan, och allt Thynenträ, och all käril af kosteligit trä, och af koppar, och jern, och marmor,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'Och canel, och timian, och salvo, och rökelse, och vin, och oljo, och semlor, och hvete, och boskap, och får, och hästar, och vagnar, och kroppar, och menniskors själar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Och de äple, som din själ begärar, äro bortkomna ifrå dig, och allt det fett och härligit var, är förgånget ifrå dig, och du skall icke nu finnat härefter.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Köpmännerna som sådana varor pläga hafva, och äro rike vordne af honom, skola stå långt ifrå, för räddhågas skull af hans plågo, gråta och sörja;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'Och säga: Ve, ve den stora staden, som med silke, och purpur, och skarlakan beklädd var, och öfvergyld med guld, och ädla stenar, och perlor;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Ty uti ene stund äro förödde sådane rikedomar; och alle skeppare, och alle de som på skeppen vistas, och sjömän, och de som till sjös handla, stodo långt ifrå;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'Och ropade, då de sågo röken af hans brand, sägande: Hvar är dens stora stadsens like?');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Och de kastade mull på sin hufvud, och ropade, gråtande och sörjande, och sade: Ve, ve den stora staden, i hvilkom alle äro rike vordne, som i hafvet hafva haft sin skepp af hans varor; ty uti en stund är han öde vorden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Fröjda dig öfver honom, himmel, och I helige Apostlar, och Propheter; ty Gud hafver dömt edar dom på honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Och en stark Ängel tog upp en stor sten som en qvarnsten, och kastade i hafvet, och sade: Med sådana hastighet skall förkastad varda den store staden Babylon, och han skall icke nu mer varda funnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Och harpares, och sångares, och pipares, och basuners röst skall icke mer hörd varda i dig; och alle handtverksmän, ehvad handtverk det är, skola icke mer varda funne i dig; och qvarnaröst skall icke mer höras i dig.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Och ljus och ljusastaka skall icke mer lysa i dig; och brudgummes och bruds röst skall icke mer hörd varda i dig; ty dine köpmän voro Förstar på jordene; ty i dinom trolldom hafva alle Hedningar ville farit;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Och i honom vardt funnen Propheternas och helgonens blod, och allas deras som dräpne äro på jordene.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Sedan hörde jag, såsom en stor röst, af en stor skara i himmelen, som sade: Halleluja; salighet och pris, ära och kraft, vare Herranom vårom Gudi.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Ty hans domar äro sanne och rätte; ty han hafver dömt den stora skökan, den med sitt boleri hafver förderfvat jordena; och hafver hämnat sina tjenares blod utu hennes hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Och åter sade de: Halleluja; och röken gick upp af evighet till evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Och de fyra och tjugu äldste, och de fyra djur, föllo neder och tillbådo Gud, som satt på stolen, och sade: Amen, Halleluja.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Och en röst gick af stolen, och sade: Lofver vår Gud, I alle hans tjenare, och I som frukten honom, både små och store.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Och jag hörde ena röst, såsom af en stor skara, och såsom en röst af mycket vatten, och såsom en röst af stor tordön, säga: Halleluja; ty vår Herre, allsmägtig Gud, hafver intagit riket.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Låt oss glädjas och fröjdas, och gifva honom äro; ty Lambsens bröllop är kommet, och dess hustru hafver sig tillredt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Och henne vardt gifvet att kläda sig uti rent och skinande silke; men silket är helgonens rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Och han sade till mig: Skrif: Salige äro de, som kallade äro till Lambsens bröllop. Och han sade till mig: Dessa äro sann Guds ord.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Och jag föll för hans fötter, att tillbedja honom; och han sade till mig: Se till, att du det icke gör; ty jag är din och dina bröders medtjenare, som Jesu vittnesbörd hafva. Tillbed Gud; ty Jesu vittnesbörd är Propheties Ande.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Och jag såg himmelen öppen; och si, en hvit häst; och den som satt på honom, han het Trofast och Sannfärdig; och han dömer och strider med rättfärdighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Och hans ögon såsom eldslåge, och på hans hufvud många kronor; och hade ett namn skrifvet, det ingen kände, utan han sjelfver.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Och han var klädd i ett kläde, som med blod bestänkt var; och hans namn heter: Guds Ord;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Och honom efterföljde den här, som i himmelen är, med hvita hästar, klädde uti hvitt och rent silke.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Och utu hans mun utgick ett skarpt tveeggadt svärd, att han dermed skall slå Hedningarna; och han skall regera dem med jernris; och han trampar allsmägtig Guds grymma vredes vinpräss.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Och han hafver på sin kläder, och på sina länd ett namn, skrifvet alltså: Konung öfver alla Konungar, och Herre öfver alla herrar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Och jag såg en Ängel stå i solene, och han ropade med höga röst, och sade till alla foglar, som flugo under himmelen: Kommer, och församlens till den stora Guds Nattvard;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Att I skolen äta Konungarnas kött, och höfvitsmännernas kött, och de starkas kött, och hästars kött, och deras som sitta på dem, och allas deras kött, som frie och trälar äro, och både smås och storas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Och jag såg vilddjuret, och jordenes Konungar, och deras härar församlada, till att hålla ena strid med honom, som satt på hästen, och med hans här.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Och vilddjuret vardt fånget, och med thy den falske Propheten, som tecken gjorde för thy, med hvilko han bedrog dem, som togo vilddjursens vedertecken, och dem som tillbådo dess beläte; desse två vordo lefvande kastade uti en brinnande sjö, som brann med svafvel.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Och de andre vordo dräpne med hans svärd, som satt på hästen, det utu hans mun gick; och alle foglar vordo mättade af hans kött.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Och jag såg en Ängel nederkomma af himmelen; han hade nyckelen till af grunden, och ena stora kedjo i sine hand.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Och han grep drakan, den gamla ormen, som är djefvulen och Satan, och band honom i tusende år;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Och kastade honom uti afgrunden, och lät åter om honom, och beseglade der ofvan uppå, att han icke mer bedraga skulle Hedningarna, till dess fullkomnad vordo tusende år; och sedan måste han lös varda till någon liten tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Och jag såg stolar, och de såto på dem, och dem vardt gifven dom; och deras själar, som halshuggne voro för Jesu vittnesbörd, och för Guds ords skull; och de der icke tillbådo vilddjuret eller dess beläte; ej heller togo dess vedertecken på sin anlete, eller i sina händer; och de lefde, och regnerade med Christo i tusende år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Men de andre döde fingo icke lif igen, till dess tusende år fullkomnad vordo; denna är den första uppståndelsen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Salig och helig är den som del hafver uti första uppståndelsen; öfver dem hafver den andre döden ingen magt; utan de varda Guds och Christi Prester, och skola regnera med honom i tusende år.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Och då tusende år fullkomnad äro, varder Satanas lös utu sitt fängelse.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'Och han skall utgå, till att bedraga Hedningarna, som äro på fyra jordenes parter, Gog och Magog, på det han skall församla dem i strid; hvilkas tal är såsom sanden i hafvet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Och de gåfvo sig upp på jordenes bred het, och kringhvärfde helgonens lägre, och den älskeliga staden; och neder af himmelen for eld af Gudi, och förtärde dem.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Och djefvulen, som dem bedragit hade, vardt kastad uti den brinnande sjön, och svallet, der både vilddjuret och den falske Propheten skola plågas, dag och natt, ifrån evighet till evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Och jag såg en stor hvit stol, och en sitta på honom, för hvilkens ansigte flydde jord och himmel, och dem vardt intet rum funnet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Och jag såg de döda, stora och små, stå i Guds åsyn, och böckerna vordo upplåtna; och en annar bok vardt upplåten, som är lifsens; och de döde vordo dömde, efter som skrifvet var i böckerna, efter deras gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Och hafvet gaf igen de döda, som deruti voro; och döden och helvetet gåfvo igen de döda, som uti dem voro; och det blef dömdt om hvar och en, efter deras gerningar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Och döden och helvetet vordo kastade, uti den brinnande sjön; denne är den andre döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Och den der icke vardt funnen skrifven i lifsens bok, han vardt kastad i den brinnande sjön.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Och jag såg en ny himmel och en ny jord; ty den förste himmelen och den första jorden förgingos; och hafvet är icke mer.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Och jag, Johannes, såg den helga staden, det nya Jerusalem, nederkomma af himmelen, ifrå Gudi, tillredd såsom en prydd brud till sin man.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Och jag hörde ena stora röst af himmelen säga: Si Guds tabernakel ibland menniskorna, och han skall bo med dem; och de skola vara hans folk, och sjelfver Gud med dem skall vara deras Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Och Gud skall aftorka alla tårar af deras ögon, och ingen död skall sedan vara; icke heller gråt, icke heller rop, icke heller någor värk varder mer; ty det första är förgånget.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Och den der satt på stolen sade: Si, jag gör all ting ny. Och han sade till mig: Skrif; ty dessa ord äro viss och sann.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Och han sade till mig: Det är gjordt. Jag är A och O, begynnelsen och änden; jag skall gifva honom, som törstar, af lefvande vattnens källo för intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Den som vinner, han skall allt detta få äga; och jag skall vara honom hans Gud, och han skall vara min son.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Men dem räddom, och otrognom, och grufligom, och mandråparom, och bolarom, och trollkarlom, och afgudadyrkarom, och allom lögnaktigom, deras del skall vara uti den sjön, som brinner med eld och svafvel; hvilket är den andre döden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Och till mig kom en af de sju Änglar, som hade sju skålar fulla med de sju yttersta plågor; och han talade med mig, och sade: Kom, och jag vill visa dig brudena, Lambsens hustru.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Och han förde mig, i Andanom, på ett stort och högt berg, och viste mig den stora staden, det helga Jerusalem, nederkomma af himmelen ifrå Gud;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Och hade Guds härlighet; och hans ljus var lika som den aldraädlaste stenen, en klar jaspis,');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Och han hade en stor och hög mur, den der tolf portar hade, och i portarna tolf Änglar, och inskrifna namn, hvilka äro de tolf Israels söners slägters namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Östantill tre portar, nordantill tre portar, sunnantill tre portar, vestantill tre portar.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Och stadsmuren hade tolf grundvalar, och i dem de tolf Lambsens Apostlars namn.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Och den som talade med mig, hade ena gyldene rö, der han med mäta skulle staden, och hans portar, och hans mur.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Och staden ligger fyrkant, och hans längd är så stor som bredden; och han mälte staden med rön, tolf tusend stadier; och hans längd, och bredd, och höjd äro lika.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Och han mälte hans mur, hundrade fyra och fyratio alnar, efter ens menniskos mått, som Ängelen hade.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Och hans murs byggning var af jaspis; men sjelfve staden af klart guld, lik vid rent glas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Och stadsmurens grundvalar voro prydde med all dyrbar sten; förste grundvalen var af jaspis, den andre en saphir, den tredje en chalcedonier, den fjerde en smaragd;');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Den femte en sardonix, den sjette en sardis, den sjunde en chrysolith, den åttonde en beryll, den nionde en topazier, den tionde en chrysopras, den ellofte en hyacinth, den tolfte en amethist.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Och de tolf portar voro tolf perlor, hvar för sig; och hvar port var af ene perlo; och stadsens gator voro klart guld, såsom genomskinande glas.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Och jag såg der intet tempel uti; ty Herren, allsvåldig Gud, är templet deruti, och Lambet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Och staden behöfver icke sol eller måna, att de skola lysa deruti; ty Guds härlighet upplyser honom, och hans ljus är Lambet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Och Hedningarna, som salige varda, skola vandra i hans ljus; och Konungarna på jordene skola föra sina härlighet och ära in uti honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Och hans portar låtas intet till om dagen; ty der varder ingen natt.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Och de skola föra Hedningarnas härlighet och ära in uti honom.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Der skall intet inkomma, som besmitteligit är, eller det styggelse gör och lögn; utan de som skrifne äro i Lambsens lefvande bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Och han viste mig ena klara älf, med lefvande vatten, klar som christall, den gick ifrå Guds stol och Lambsens.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Midt uppå hans gator, och på båda sidor vid älfvena, stod lifsens trä, bärandes tolffald frukt, och bar sina frukt alla månader; och löfven af trät tjente till Hedningarnas helbregdo.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Och intet förbannadt skall vara mer; utan Guds och Lambsens stol skall blifva deruti, och hans tjenare skola honom tjena.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'Och de skola se hans ansigte, och hans Namn skall vara på deras anleten.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Och natt blifver icke mer der, och de behöfva icke ljus, icke heller solens ljus; ty Herren Gud upplyser dem, och de skola regnera ifrån evighet till evighet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Och han sade till mig: Dessa ord äro viss och sann; och Herren, de helga Propheters Gud, sände sin Ängel, att visa sina tjenare hvad ske skall innan kort tid.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Och si, jag kommer snarliga; salig är den som håller Prophetiens ord i desso bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Och jag är Johannes, som hörde och såg detta; och sedan jag hade det hört och sett, föll jag ned att tillbedja för Ängelens fötter, som mig detta viste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Och han sade till mig: Se till, att du gör det icke; ty jag är din medtjenare, och dina bröders, Propheternas, och deras som hålla denna boks ord: Tillbed Gud.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Och han sade till mig: Besegla icke denna Propheties ord i desso bok; ty tiden är när.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Den som onder är, han vare ännu onder; och den som oren är, han vare ännu oren; men den som from är, han varde ännu frommare; och den helig är, varde ännu heligare.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Och si, jag kommer snart, och min lön med mig, till att vedergälla hvarjom och enom, såsom hans gerning är.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Jag är A och O, begynnelsen och änden, den förste och den siste.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Salige äro de som hålla hans bud, på det deras magt skall vara i lifsens trä, och ingå genom portarna i staden.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Ty utantill äro hundar, och trollkarlar, och bolare, och mandråpare, och afgudadyrkare, och alle de som älska och göra lögnen.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Jag, Jesus, sände min Ängel, att han skulle betyga eder detta i församlingarna: Jag är Davids rot och slägte, en klar morgonstjerna.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Och Anden och bruden säga: Kom. Och den det hörer, han säge: Kom. Och den der törster, han komme; och den der vill, han tage lifsens vatten för intet.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Men jag betygar hvar och en, som hörer Prophetiens ord i desso bok: Ho som lägger något härtill, på honom skall Gud lägga de plågor, som skrefne äro i denna bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Och om någor tager något ifrå denna boks Propheties ord, hans del skall Gud borttaga utu lifsens bok, och utu den helga staden, och utu det som skrifvet är i denna bok.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Det säger han, som vittnesbörd bär härtill: Ja, jag kommer snart. Amen. Ja, kom, Herre Jesu.');
INSERT INTO `SweKarlXII1873_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Vårs Herras Jesu Christi nåd vare med eder allom. Amen.');
